INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d1de5b-8a86-45d6-a7e3-76d0999fb11e', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS transforms affect stacking context and document flow?', N'Fresher', N'CSS transform (with any value other than none) creates a new stacking context and a new containing block for fixed-position descendants. Key effects: 1. Stacking context: A transformed element and its children are stacked independently from surrounding elements. z-index applies among siblings within the same stacking context. 2. Document flow: Transforms do not affect the element''s layout footprint. The space the element occupies in the flow remains based on its original position and size; only the visual rendering changes. 3. Containing block for position: fixed: A position: fixed child of a transformed element is positioned relative to the transformed ancestor, not the viewport. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d7ca1ac-9c6e-46f4-8ec2-76d65c312bf1', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you manage typography in Tailwind?', N'Intern', N'Tailwind provides a set of utility classes for font size, weight, letter spacing, and line height. You can also use the official Tailwind Typography plugin, which provides a set of sensible default styles for long-form content like blog posts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bc8846c-048b-487d-80b7-76d7df901769', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the main advantage of using the Next.js ''Link'' component over an ''a'' tag?', N'Fresher', N'While an ''a'' tag triggers a full browser refresh, the Link component performs a client-side navigation. This transition is much faster because it only fetches the necessary data and replaces the content on the current page without reloading the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d86d2bd-714e-43da-8087-76d95cf28588', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API security in a microservices environment?', N'Middle', N'In microservices, security is often handled using a central identity provider that issues tokens like JWTs. These tokens are validated at the API Gateway or individual services, ensuring that every request is authenticated and authorized without requiring every service to perform heavy identity lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ccf8be8-93dc-4b05-a566-76d9dbfda06c', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a data class in Kotlin?', N'Intern', N'A data class is a class primarily used to hold data. The compiler automatically generates useful methods like equals, hashCode, toString, and copy based on the properties declared in the primary constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a8a87a1-6d1b-4795-a7dc-76daaf4fbf08', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If you are asked to choose between two different data structures for a feature, how do you decide which one to use?', N'Intern', N'I would first analyze the specific requirements of the feature, such as whether we need fast lookups, ordered data, or frequent insertions. I would then compare the time and space complexity of each data structure against the expected scale of the data. My decision would be based on which structure provides the best balance between performance efficiency and code maintainability for the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c26fbda7-938e-4445-8336-76dcf3ee03e6', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the trade-offs of using JSON-RPC vs REST for public APIs?', N'Senior', N'REST leverages standard HTTP semantics and is highly discoverable, making it ideal for resource-oriented public APIs. JSON-RPC is simpler to implement for internal service-to-service communication but lacks the uniform interface and caching benefits inherent to REST.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21ac431a-1146-4ce3-9f17-76e0e6406e46', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What factors do you consider when estimating the ''cost of failure'' for a system component?', N'Middle', N'I evaluate the impact on user experience, potential data loss, the time required for recovery, and the business revenue affected during downtime. This allows me to prioritize reliability engineering efforts and define appropriate service level objectives for that specific component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b841fc7e-f974-4a00-ae2f-76e17766b708', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is ''arbitrary value'' support in Tailwind?', N'Junior', N'Arbitrary values allow you to use custom values that aren''t in your theme by using square brackets, such as w-[327px] or bg-[#1da1f2]. This is useful for one-off styles that don''t fit into your standard design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaf32e02-f646-44c2-be29-76e1df4200f7', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the ''curiously recurring template pattern'' (CRTP) achieve static polymorphism?', N'Senior', N'CRTP utilizes template inheritance to allow the base class to access derived class members at compile time. By passing the derived class as a template parameter to the base, the compiler generates specialized versions of the base class for each derived type, effectively providing a polymorphic interface without the overhead of runtime vtable lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8af8748b-1ad2-40d2-9f6d-76e37f66bd03', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between embedded documents and references?', N'Junior', N'Embedded documents store related data directly within a single document, which is ideal for data accessed together. References store the ID of a related document in a different collection, which is better for managing large, complex, or highly normalized data relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd3a2420-fd1d-4ce3-a559-76e3bea46695', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is an Axum ''Response'' type?', N'Intern', N'The Response type represents the HTTP output sent back to the client. Axum allows handlers to return any type that implements the IntoResponse trait, making it flexible for returning various formats like JSON, plain text, or custom status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f855281-a7b7-43f4-88a2-76e3bfed70a6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the ''Arbiter'' in Actix?', N'Junior', N'An Arbiter is an event loop execution thread. It is responsible for running actors and managing the scheduling of asynchronous tasks within its specific thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32ed1caa-930f-4872-a090-76e4393383ca', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''readonly'' modifier do when applied to an interface property?', N'Junior', N'The ''readonly'' modifier prevents a property from being reassigned after it has been initialized. This helps ensure data immutability within your application state, preventing accidental changes to objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79766928-96e2-4b89-a7b6-76e89e0f330a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is a template literal in the context of Lit?', N'Intern', N'Lit uses JavaScript tagged template literals to define the HTML structure of a component. These templates are parsed once and then efficiently updated when reactive properties change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b0b8a55-63b3-4c76-b534-76e8ff2c4c07', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between standards mode and quirks mode?', N'Fresher', N'In Quirks mode, layout emulates nonstandard behavior in Navigator 4 and Internet Explorer 5. This is essential in order to support websites that were built before the widespread adoption of web standards. In Standards mode, the behavior is described by the HTML and CSS specifications. For HTML documents, browsers use a in the beginning of the document to decide whether to handle it in quirks mode or standards mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6cd3ded-63ec-45df-9065-76eab59d0d30', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are ''action creators'' and why use them?', N'Middle', N'Action creators are functions that return an action object. They provide an abstraction layer that makes it easier to change the structure of actions throughout an application without having to update every single dispatch call manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30435679-540d-433a-9ac8-76eadb948f2d', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it important to maintain strict separation between the API layer and the internal domain model?', N'Senior', N'Separation prevents internal database schema changes from leaking into the public API, ensuring that the external contract remains stable. It allows the team to refactor internal business logic without forcing breaking changes on API consumers, thereby maintaining long-term system flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a00349-bf5e-4352-a5fe-76ed53b8c006', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach database migrations in a production environment with zero downtime?', N'Senior', N'I use a multi-phase migration approach: first, ensuring the application code is compatible with both schemas; then, performing a dual-write phase to keep both schemas in sync; and finally, switching the read path and cleaning up the legacy schema. This ensures the system remains functional throughout the entire deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4141bc20-35b5-40e1-aa3a-76f0687735a8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is ActiveRecord in Rails?', N'Junior', N'ActiveRecord is the Object-Relational Mapping (ORM) layer of Rails. It allows developers to interact with database tables as if they were standard Ruby objects, providing methods to query, create, update, and delete records without writing SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3375e108-2ca8-4410-b6c7-76f494f6abdd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate if a tool or library is appropriate for a project?', N'Intern', N'I look at the documentation, community support, and whether the tool is well-suited for the specific problem I am trying to solve. I also consider the long-term maintenance costs and whether it adds unnecessary complexity to the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
