INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b75ddbb5-98a3-4c9f-bd6d-76fb1fe6a4e4', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the risks of using @extend across media queries in Sass?', N'Senior', N'Sass cannot extend a selector defined outside a media query into one defined inside it, or vice versa, because the resulting selector would be invalid CSS. This restriction often forces developers to duplicate code or restructure their architecture to avoid complex, cross-media-query dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ceab9ab-3734-48da-92bb-76fbcc38386b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle atomic operations despite being single-threaded?', N'Middle', N'Redis guarantees atomicity for individual commands because it executes them sequentially within its single-threaded event loop. Complex multi-command sequences can be made atomic using the MULTI/EXEC transaction block, which queues commands to be executed as a single unit without interference from other clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'663ab1c6-1796-4c2c-a41b-76ffaecd99c7', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of the Partition Partitioner?', N'Middle', N'The partitioner determines how the partition key is hashed to distribute data across the cluster ring. Choosing the correct partitioner is critical for ensuring balanced data distribution and avoiding uneven load across the nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc8499b9-c56e-48c6-b85f-76ffdf477826', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the primary difference between a relational database like PostgreSQL and a NoSQL database?', N'Junior', N'Relational databases use structured tables with predefined schemas and enforce relationships between data using primary and foreign keys. NoSQL databases are typically schema-less or flexible, allowing for unstructured or semi-structured data storage like documents or key-value pairs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcbf6f9d-0666-49d5-92e8-7701db6b0408', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the role of abstraction in software design?', N'Intern', N'Abstraction hides complex implementation details behind a simple interface, allowing developers to interact with a system without needing to understand its internal mechanics. This makes the system easier to manage and allows the internal logic to be swapped out without affecting the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f620065c-95e2-4042-b235-7703165d8a63', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the borrow checker handle multiple immutable references vs. one mutable reference?', N'Middle', N'The borrow checker enforces the rule that you can have either an unlimited number of immutable references or exactly one mutable reference at any given time. This prevents data races by ensuring that no part of the program can modify data while other parts are reading it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4976ef98-d80c-4942-a904-7705fc7cf069', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Models in the context of Ember Data?', N'Intern', N'Models represent the data structures of your application and define the attributes and relationships of the information you are managing. Ember Data is a library that provides a standardized way to fetch, persist, and update these models from a server, acting as a bridge between the application''s UI and the backend API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcbc210e-5230-42df-b604-7707deb675c3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the benefit of keeping a design simple?', N'Fresher', N'Simple designs are easier to understand, maintain, and debug, which reduces the likelihood of introducing errors. Complex systems often create unnecessary dependencies that make future changes more difficult and time-consuming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47dfd9a3-e5c2-4564-aa65-770a888a9d47', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens when you update a signal with the same value it already holds?', N'Junior', N'SolidJS uses a default equality check for signals. If you set a signal to the same value it currently holds, the framework will skip the update and prevent unnecessary re-renders or effect triggers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae7419b8-6bb4-41a5-9e39-770c5a92a308', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is multi-master replication?', N'Middle', N'Multi-master replication allows write operations on multiple nodes, which are then synchronized with each other. While it provides high write availability and low latency, it introduces complex conflict resolution requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f53b5c2a-c580-46dd-b29f-770d13d86a67', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Compare the performance and usage of ArrayList versus LinkedList.', N'Middle', N'ArrayList provides O(1) random access time but incurs O(n) costs for insertions or deletions in the middle due to array resizing and element shifting. LinkedList offers O(1) time for insertions and deletions when the position is already known, but suffers from O(n) access time and higher memory overhead per element due to node pointers. Choosing between them depends on whether the application requires frequent random access or frequent modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46039303-0154-4026-af81-770ec2ef81cd', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of the ''Next'' function in Fiber middleware?', N'Intern', N'The Next function is used to pass control to the next middleware or route handler in the execution chain. If it is not called, the request cycle will stop at the current function, preventing subsequent handlers from running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd76bfc9-5bfc-47f9-b7ec-771086995070', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the ''Container'' handle lazy loading of application assets?', N'Senior', N'The container supports lazy loading by dynamically resolving modules only when they are requested by the router or by code execution. This keeps the initial bundle size small and improves startup performance for large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a203dae8-2a1c-4389-bfd9-77118f30cde8', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify support multi-tenant architectures through its plugin system?', N'Senior', N'Multi-tenancy can be implemented by creating a root plugin that encapsulates tenant-specific logic, databases, and configuration settings. Because each plugin can define its own hooks and decorators, it is possible to isolate the request processing logic for different tenants within the same application instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b4620f-f999-4276-a065-7711cfd42203', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the benefit of using a service mesh in a microservices architecture?', N'Middle', N'A service mesh handles service-to-service communication, including load balancing, retries, and circuit breaking, at the infrastructure level. This abstracts away networking logic, allowing developers to focus on features while providing robust mechanisms to manage scale and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f4673cf-b983-4986-94c6-7712c9b5e901', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the performance implications of using @extend extensively?', N'Middle', N'Overusing @extend can lead to complex selector chains and bloated CSS output if not managed carefully. While it effectively groups selectors, it can force the compiler to generate deeply nested or overly specific CSS rules that are harder to maintain and override.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e6d55b4-eca1-4ace-8d58-77134f8891bb', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the impact of choosing an inappropriate partition key (shard key) on database performance and scalability.', N'Senior', N'An inappropriate partition key leads to data skew, where one or few nodes hold the majority of the data, creating a hotspot that negates the benefits of horizontal scaling. This causes uneven resource utilization, where specific nodes become performance bottlenecks, increasing latency for requests hitting those shards while other nodes remain underutilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
