INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'769b6e60-959a-4326-8d13-771f702ebc6d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between ''def'' and ''async def'' in FastAPI route handlers?', N'Junior', N'Using ''def'' tells FastAPI to run the function in an external thread pool to prevent blocking the event loop, while ''async def'' runs directly on the event loop. You should use ''async def'' for I/O operations and ''def'' for CPU-bound tasks to keep the server responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
