INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1823c1df-f82a-4849-871f-77336ce65a22', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of database replication?', N'Middle', N'Database replication involves copying data from one server to another to increase data availability and read throughput. It also provides a backup mechanism in case the primary database fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b885d72-92bc-4a70-805c-773675c9dd61', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the IoC container in AdonisJS?', N'Intern', N'The Inversion of Control (IoC) container is a tool for managing class dependencies and performing dependency injection. It allows the framework to automatically resolve and inject necessary classes or services whenever they are required in a controller or other components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25ad8767-627c-4d64-921b-7736de87bd7b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary advantage of using Nuxt.js over vanilla Vue.js?', N'Fresher', N'The primary advantage is that Nuxt.js provides out-of-the-box features like file-system based routing, server-side rendering, and automatic code splitting. These features reduce configuration time and improve both SEO and initial load performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac5be0d8-5ab5-44ee-85b8-7736ea2b6914', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the RouteServiceProvider?', N'Junior', N'The RouteServiceProvider is responsible for loading the route files of your application. It defines the namespaces and middleware groups for your routes, ensuring that your application''s URLs are correctly mapped to the appropriate controller actions when a request enters the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c829cc50-b2c1-4d5a-8e37-7738144835c2', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of a primary key in PostgreSQL?', N'Intern', N'A primary key is a column or a set of columns that uniquely identifies each row in a table. It ensures that no two rows have the same value in the primary key column and prevents null values, guaranteeing data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'903d36a3-5bc4-4c64-8829-773874612f4a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a token in Elasticsearch?', N'Fresher', N'A token is a single term or unit that results from the analysis process. These tokens are stored in the inverted index to allow the search engine to match queries against the document content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4489d20-c78c-4039-89b6-7738ddb1adcc', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle routing and why is it more efficient than dynamic regex-based routing?', N'Senior', N'Rocket uses a sophisticated compile-time routing table that maps request paths to handlers using static analysis. This avoids runtime pattern matching, enabling the server to route requests with constant time complexity regardless of the number of registered routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81455364-7295-430e-9310-7739b7dd910f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are ''Path Parameters'' in Rocket?', N'Intern', N'Path parameters are variables embedded directly into the URL path. Rocket allows you to define these in the route string, automatically extracting them and passing them into your handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c097b8d0-f5e5-4c25-84ae-773cc28f6e29', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are wrapper objects', N'Intern', N'Primitive Values like string,number and boolean don''t have properties and methods but they are temporarily converted or coerced to an object(Wrapper object) when you try to perform actions on them. For example, if you apply toUpperCase() method on a primitive string value, it does not throw an error but returns uppercase of the string. i.e, Every primitive except null and undefined have Wrapper Objects and the list of wrapper objects are String,Number,Boolean,Symbol and BigInt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0526a7d5-f1ff-42b7-a972-773dcce2c8e2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the core difference between using Tailwind CSS and traditional CSS classes?', N'Junior', N'Tailwind CSS is a utility-first framework that provides low-level classes to build designs directly in your markup, whereas traditional CSS involves writing custom styles in separate files. This approach allows developers to style elements without leaving the HTML, which can speed up the development process and avoid the need to constantly switch between files or name custom classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9c91fb1-e937-440b-8d98-77402de49312', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for ensuring data integrity in a system that performs distributed transactions across microservices?', N'Senior', N'I prefer the Saga pattern over distributed transactions like two-phase commit, as it maintains availability and scalability. By using a series of local transactions with compensating actions, I ensure that the system eventually reaches a consistent state even if a partial failure occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'885117f5-bcd8-45cf-9f41-7740bd96eedc', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the implications of the different transaction isolation levels?', N'Middle', N'Isolation levels manage the trade-off between consistency and performance by controlling how transactions interact with each other. Higher levels like Serializable prevent all concurrency anomalies but significantly reduce throughput, while lower levels like Read Committed improve performance at the risk of phenomena like non-repeatable reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57977d43-95c5-4260-9554-77414a522c18', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why MongoDB is not preferred over a 32-bit system?', N'Fresher', N'When running a 32-bit system build of MongoDB, the total storage size for the server, including data and indexes, is 2 gigabytes. The reason for this is that the MongoDB storage engine uses memory-mapped files for performance. If you are running a 64-bit build of MongoDB, there is virtually no limit to storage size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96472018-3b01-47d7-a64e-7741a1fac61d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you bind JSON request bodies to Go structs in Gin?', N'Junior', N'Gin provides ''ShouldBindJSON'' or ''BindJSON'' methods that automatically parse the incoming request body. These methods map the JSON fields to the struct fields based on tags, simplifying data validation and extraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e050b53e-94dc-4cbb-8a0a-7741c12934ac', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s session management work in a multi-server load-balanced environment?', N'Middle', N'By default, PHP stores session data in local files on the server''s filesystem, which fails in load-balanced environments because requests are routed to different servers. To solve this, developers must configure PHP to use a centralized storage mechanism like Redis or Memcached to ensure session persistence across all instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28c2f332-dc6e-4bc3-8169-774525c3ea5e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is JSON? Describe in brief how you\''d convert JSON data into Python data?', N'Intern', N'Ans. JSON stands for JavaScript Object Notation. It is a highly popular data format, and it stores data into NoSQL databases. JSON is generally built on the following two structures: A collection of pairs An ordered list of values. Python supports JSON parsers. In fact, JSON-based data is internally represented as a dictionary in Python. To convert JSON data into Python data, we use the load() function from the JSON module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'922127a6-442b-45cb-9296-774665964aba', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is it possible to use existing React UI libraries with Preact?', N'Middle', N'Yes, through the preact/compat layer, most React components and libraries can work seamlessly. However, libraries that rely heavily on internal React internals or specific, undocumented Fiber APIs might encounter compatibility issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad8a03a-da9f-4de6-8f05-7747784fccc2', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the benefit of Fiber''s built-in error handling mechanism?', N'Middle', N'Fiber provides a centralized way to catch and process errors via custom error handlers. This ensures consistent API responses and logging, preventing sensitive system information from leaking to the client while maintaining a clean separation between business logic and error reporting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fc53a66-73d2-497f-9108-7747a156836a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the role of the ''requestUpdate'' method in the Lit lifecycle.', N'Middle', N'The requestUpdate method is used to manually signal to the component that its internal state has changed and a re-render is required. It is typically used when a property is updated in a way that doesn''t trigger the automatic reactive setter, such as modifying the internal state of a complex object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2df76e82-b59a-41cd-b810-7748b41fd2da', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle schema changes?', N'Junior', N'MongoDB is schema-flexible, meaning you can add or remove fields from documents at any time without needing to run migration scripts or alter table structures. This allows developers to evolve their data models as application requirements change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64bd5cb2-ee71-4e28-b164-774e0378f8d1', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the drawbacks of dynamic directive arguments?', N'Intern', N'Apart from the benefits of dynamic directives arguments, it brings two drawbacks or considerations on the usage 1. Constraints on expressions: When you perform complex JavaScript expressions, make sure that html attribute names cannot contain spaces and quotes. The below expression doesn''t work as expected Instead you may need to use string template syntax 2. Custom Directives: The custom directive implementations need to have potential argument changes in addition to value changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd206250d-8ab5-4288-961e-774e6b528bd5', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is Pattern Matching?', N'Intern', N'Pattern matching is a mechanism for checking a value against a sequence of patterns. It is a powerful way to deconstruct data structures and execute specific logic based on the shape or type of the input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac92ed27-3842-43b4-802d-774f1d6f4a47', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Compare Scala''s ''Macros'' (pre-Scala 3) with the new ''Metaprogramming'' system in Scala 3.', N'Senior', N'Scala''s original macro system relied on internal compiler APIs, making it unstable and prone to breaking across compiler versions. Scala 3 introduces a stable, high-level metaprogramming framework with ''inline'' and ''quoted'' expressions that provide a safer, type-checked way to perform code generation. This shift prioritizes long-term compatibility and maintainability of libraries that rely on metaprogramming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'563435e0-ac19-4e6a-83f0-77503c49018f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the __init__ method versus the __new__ method?', N'Middle', N'The __new__ method is the constructor that creates and returns a new instance of a class. The __init__ method is an initializer that configures the instance after it has been created by __new__.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'313eaad6-c4a6-422b-8c0a-7754750f7cfd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you handle errors in async/await, and what are the pitfalls of unhandled rejections?', N'Fresher', N'Errors in async functions are handled with standard try/catch/finally blocks. An awaited Promise that rejects throws at the await expression, which catch intercepts exactly like a synchronous throw. Key pitfalls: 1. Forgetting await — the Promise is created but not awaited; errors are silently swallowed. 2. Missing catch — an unhandled rejection in Node.js (since v15) causes the process to exit with a non-zero code; in browsers it fires window.unhandledrejection. 3. try/catch around non-awaited Promises — try only catches synchronous throws and awaited rejections, not fire-and-forget Promises inside the block. 4. Partial failure in loops — await inside a for loop is sequential; one failure aborts all subsequent iterations unless each is individually caught.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dffb8cf3-e51b-4e0f-928d-77568f9de028', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s approach to CSS class manipulation compare to classList API?', N'Senior', N'The classList API is a native, high-performance interface for manipulating classes that provides cleaner, more readable syntax. jQuery''s addClass/removeClass methods are abstractions that perform unnecessary DOM reads and writes, making them less performant than native methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a70ecdde-f931-4b7a-9d46-77580f029ddc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of ''idempotency'' when troubleshooting issues related to retried requests?', N'Middle', N'Idempotency ensures that repeating a request does not cause unintended side effects, which is critical for recovering from network timeouts or transient errors. When debugging, I look for operations that are not idempotent to understand if retries are creating duplicate data or inconsistent states in the underlying database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21849fdb-e964-4be2-a8aa-7758991d6549', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of checking logs before making changes to a production system?', N'Junior', N'Logs act as the primary evidence of what the system was doing at the exact moment of failure. Checking them prevents guessing and ensures that you are addressing the root cause rather than just treating the symptoms of a different issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e74c7a33-c1a9-4371-bd3b-7758cf5d8233', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact achieve a smaller bundle size compared to React?', N'Fresher', N'Preact achieves its small size by omitting certain features found in React, such as synthetic events and some legacy lifecycle methods. It uses a custom, streamlined implementation of the virtual DOM and focuses on core functionality to reduce the amount of code that needs to be downloaded and parsed by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e36f908e-7aea-41b4-9414-775a7e263a47', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle a scenario where two senior developers disagree on the architecture of a project?', N'Fresher', N'I would facilitate a discussion to list the pros and cons of each approach based on project goals. Then, I would look for a compromise or perform a small proof-of-concept to identify which path aligns better with the current requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f912c4-ff96-43cb-8450-775c4d648f3a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s ''method dispatch'' mechanism handle the distinction between public, protected, and private methods?', N'Senior', N'Ruby enforces visibility constraints at runtime by checking the caller''s context against the method''s access level. Private methods can only be called without an explicit receiver within the class or module, while protected methods allow access from other instances of the same class, providing a balance between encapsulation and object interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef887118-03e6-4141-ad87-775dc4c113cd', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s build process differ from a standard React build?', N'Middle', N'A standard React build typically creates a single large JavaScript bundle that renders the page in the browser. An Astro build outputs static HTML files for each route and only bundles the specific JavaScript required for the defined interactive islands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c63e528c-372d-4e1e-a2f9-775fa7d54cd3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the WHERE clause?', N'Intern', N'The WHERE clause is used to filter records in a database query. It specifies the criteria that rows must meet in order to be included in the result set, effectively narrowing down the data returned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bc1d4f8-01c2-4c7f-91ba-775fcb295a86', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does ''eventual consistency'' mean in a distributed database?', N'Junior', N'Eventual consistency means that if no new updates are made to a specific piece of data, eventually all accesses to that data will return the last updated value. It acknowledges that there may be a temporary delay where different nodes return different versions of the same data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f92dd55-d543-46c5-bf95-77601e70ed5f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between a production bug and a development bug?', N'Junior', N'A development bug is found during the building process and only affects the developer, while a production bug impacts real users and often requires a higher sense of urgency. Production bugs typically require more careful investigation to understand the scope of impact and a more structured deployment process to fix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e085dcf5-dcfd-4c49-9ef7-77640c71d92e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are Web Workers and how can they be used to improve performance?', N'Intern', N'Web Workers are a way to run JavaScript in the background, separate from the main execution thread of a web application. This helps in performing heavy computations without blocking the user interface. You can create a Web Worker using the Worker constructor and communicate with it using the postMessage and onmessage methods. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of caching and how it can be used to improve performance Caching is a technique used to store copies of files or data in a temporary storage location to reduce the time it takes to access them. It improves performance by reducing the need to fetch data from the original source repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72ee5a92-02b6-4095-aa4d-7764b3054384', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the trade-offs of using Traits in PHP.', N'Middle', N'Traits allow for horizontal code reuse by enabling classes to inherit methods from multiple sources, bypassing the limitation of single inheritance. However, overusing them can lead to complex dependency graphs and naming collisions, making the codebase harder to maintain and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ce6dbf9-499e-484c-a060-77655ac626c7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''flash'' object in Rails?', N'Junior', N'The ''flash'' object is used to pass temporary messages between controller actions, usually to display success or error notifications to the user. These messages persist only for the duration of the next request before being cleared.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ce0be71-bbfa-45cf-9696-7766c760b0cd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does the Axum ecosystem handle tracing and observability?', N'Senior', N'Axum integrates natively with the ''tracing'' crate, allowing developers to instrument handlers and middleware easily. By using the ''TraceLayer'' from tower-http, you can automatically capture request latency, status codes, and headers, which can then be exported to observability backends for distributed tracing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd87377aa-3096-4f12-b6a4-776840d43e8f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s router handle path parameters compared to a regex-based router?', N'Middle', N'Chi uses a trie-based routing algorithm which is significantly more performant than evaluating multiple regular expressions for every request. It parses path parameters during the initial trie traversal, resulting in constant or logarithmic time complexity for route matching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a47145dd-e5bc-47ed-bfd7-776867a98ff0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Discuss the trade-offs of using ''Hyper'' as the underlying HTTP implementation for Axum.', N'Senior', N'Hyper is a highly performant, low-level HTTP library that provides the speed required for modern web services. However, it requires developers to manage complex low-level details, which Axum abstracts away, offering a perfect balance between high-level developer productivity and low-level execution efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dc4eaba-045d-4128-b0eb-7768f4390841', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using Hibernate with Quarkus?', N'Junior', N'Using Hibernate with Quarkus allows developers to use familiar ORM patterns for database interaction. The Quarkus Hibernate extension is specifically optimized to perform mapping and configuration tasks during the build phase, improving startup performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c02bc35-1f98-447c-bd37-776c10462bcf', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is eventual consistency in a distributed database?', N'Middle', N'Eventual consistency is a model where all replicas will eventually reflect the latest data, but reads might return stale data temporarily. It is often chosen to maximize availability and performance in systems that can tolerate minor delays in data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e27300f4-40cd-4df8-bbcd-776c3f7c17b9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is it important to avoid capturing dependencies with a shorter lifetime in a singleton service?', N'Senior', N'This creates a captured dependency issue where a long-lived service holds a reference to a short-lived object, potentially preventing that object from being garbage collected. This leads to memory leaks and can cause runtime exceptions if the short-lived dependency is intended to be disposed of at the end of a scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4ae0e3d-6e51-4393-ab54-776de304b8f7', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the advantages of using a microservices architecture over a monolith?', N'Middle', N'Microservices allow for independent deployment, technology diversity, and better fault isolation, as one service failing does not necessarily crash the entire system. However, this comes at the cost of increased operational complexity and challenges in data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0910da43-fc24-4714-8bdf-777016be46fc', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is meant by ''Live Coding'' in Quarkus?', N'Intern', N'Live coding is a development feature that allows developers to modify their code and see the changes immediately without manually restarting the application. It automatically recompiles and reloads the application in the background whenever a file is saved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a9f3df7-04aa-4283-9d85-7772b71179b8', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does it mean for a Rocket application to be ''async''?', N'Junior', N'Being asynchronous means that Rocket can pause the execution of a handler that is waiting for I/O, such as a database query, and switch to handling another request in the meantime. This significantly improves the concurrency and throughput of the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e67b269f-3d11-4691-9ced-777a4f5f3336', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of using Remix''s ''fetcher'' hook for non-navigation mutations?', N'Senior', N'The fetcher hook allows developers to perform mutations or load data without triggering a full page navigation. This is critical for building isolated components like persistent sidebars, search inputs, or real-time notifications that need to interact with the server independently of the main route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40e71541-bddd-4f0e-8835-777d640e8956', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is meant by ''referential integrity''?', N'Intern', N'Referential integrity ensures that relationships between tables remain consistent. It prevents actions that would leave orphaned records or break links between related data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f541101-7fb5-4b75-b974-77821c187fa0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the LRU policy in Redis?', N'Fresher', N'LRU stands for Least Recently Used. It is an eviction policy that tells Redis to identify and remove the keys that have not been accessed for the longest period when the memory limit is reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed6f68f7-e062-4689-ac5d-7782885ef8b1', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the significance of Micronaut''s support for GraalVM Native Image?', N'Middle', N'Micronaut was designed with Native Image compatibility in mind, meaning it does not rely on reflection or dynamic class loading. This allows applications to be compiled into native binaries, providing near-instant startup and minimal memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91f8651b-8db0-42c1-b881-7785cfd72da7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does ''Eventual Consistency'' mean?', N'Intern', N'Eventual consistency is a model where, given no new updates to an item, all accesses to that item will eventually return the last updated value. It is a common trade-off in NoSQL systems to achieve higher availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b984bec2-0d0d-4a39-b740-77877449384b', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How do Dart extensions impact the performance of the application?', N'Senior', N'Extensions are essentially static syntactic sugar that resolves to static function calls at compile time. Because they do not add fields to the class or modify the runtime object prototype, they incur virtually no performance penalty compared to standard helper functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df01a585-1421-49e2-a6a6-778e7fc26e10', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why might you use table partitioning in a large PostgreSQL database?', N'Middle', N'Partitioning divides a large table into smaller, more manageable pieces based on a key range or list. This improves performance for queries that can prune partitions and simplifies data lifecycle management, such as dropping old data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4078e70-adf5-4867-b571-778e88dcd64b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'When is a Key-Value store preferred?', N'Fresher', N'A key-value store is preferred when the application requires high-speed performance for simple read and write operations. It is commonly used for user profiles, shopping carts, and caching frequent web requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a065ea7-6572-43e3-8fd0-7790a29acc10', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the function of the HTTPError type in Echo?', N'Junior', N'HTTPError is a built-in struct used to return standardized error responses to the client. It allows developers to specify a status code and a message, which Echo then formats into a consistent JSON response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a05f6cf3-403b-4bc4-aaae-7790bf66cdf7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate the reliability of a third-party vendor''s infrastructure before integration?', N'Senior', N'Review their historical uptime reports, service level agreements, and security certifications. Assess their API rate limits, support responsiveness, and whether they provide a sandbox environment for testing integration resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d523fc8-bed0-4935-a0ef-7790df997421', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the Phoenix Presence module maintain state consistency across a distributed cluster?', N'Senior', N'Phoenix Presence utilizes CRDTs (Conflict-free Replicated Data Types) to synchronize state across nodes. By propagating delta updates via distributed Erlang messages, it ensures that every node eventually reaches a consistent view of user presence without requiring a central database lock.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c310492-dcf6-4a68-8742-77942ae59a4f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate the number of words in a document, what is your strategy?', N'Fresher', N'I would count the number of words in a few representative lines to get an average words-per-line. Then, I would count the number of lines on a typical page and multiply that by the total number of pages. This approach provides a reliable estimate without needing to count every single word manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79416852-9a0c-4bfa-8a87-7795c3d24090', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does useLayoutEffect cause layout thrashing?', N'Fresher', N'The useLayoutEffect can cause layout thrashing when you repeatedly read and write to the DOM in ways that force the browser to recalculate layout multiple times per frame. This is because useLayoutEffect runs _before the browser paints_, these reflows happen _synchronously_, blocking rendering and degrading performance. Example: In the above code, each read/write cycle triggers synchronous reflows, blocking the main thread and delays UI rendering. This issue can be avoided by batching your DOM reads and writes and prevent unnecessary reads after writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f089c47-2799-496d-b2ed-7799122dfd79', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the ''freeze'' method?', N'Middle', N'The ''freeze'' method prevents any further modification to an object, such as changing its attributes or adding new instance variables. It is often used to ensure immutability and to prevent side effects in shared state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
