INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38d2f92a-78d4-40ea-a05a-77a82fd81036', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What role does a Content Delivery Network (CDN) play in improving system scalability?', N'Middle', N'A CDN improves scalability by offloading static content delivery from your origin servers to geographically distributed edge servers. This reduces latency for users and significantly lowers the bandwidth and compute load on your primary infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
