INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1824f20c-2480-4f8c-9c90-77a9a5556467', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the role of the ''optimistic UI'' pattern in Remix, and how is it implemented?', N'Senior', N'Optimistic UI in Remix is achieved through the use of the useNavigation or useFetcher hooks, which provide the current submission state. Developers can immediately update the UI based on the submission intent, with Remix handling the rollback if the server-side action fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14f27801-f90b-4268-a0ca-77acc8dbbaae', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle routing?', N'Fresher', N'Nuxt uses file-system-based routing, meaning the structure of the files inside the pages directory defines the application''s URL structure. You simply create a file, and Nuxt automatically sets up the corresponding route for it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6474ecb2-1ed7-489f-a87b-77ad4dac6bec', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does an idempotent API design improve the reliability of distributed systems, and why is it important when dealing with retries?', N'Middle', N'An idempotent operation ensures that performing the same request multiple times has the same effect as performing it once. This is critical in distributed systems because network failures often result in timeouts where the client does not know if the request succeeded, making safe retries essential to maintain data integrity without side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30f9b3d6-6a7d-4335-b38d-77ade35caa16', N'954a0331-deff-4399-b588-96f39fec001d', N'What is angular CLI?', N'Intern', N'Angular CLI(Command Line Interface) is a command line interface to scaffold and build angular apps using nodejs style (commonJs) modules. You need to install using below npm command, Below are the list of few commands, which will come handy while creating angular projects 1. Creating New Project: ng new 2. Generating Components, Directives & Services: ng generate/g The different types of commands would be, * ng generate class my-new-class: add a class to your application * ng generate component my-new-component: add a component to your application * ng generate directive my-new-directive: add a directive to your application * ng generate enum my-new-enum: add an enum to your application * ng generate module my-new-module: add a module to your application * ng generate pipe my-new-pipe: add...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5260959-ab90-4223-9b75-77ade46eb89c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary benefit of the ''Flux'' architecture that Redux implements?', N'Middle', N'The primary benefit is the unidirectional data flow, which makes the state changes predictable and easier to track. By forcing data to move in one direction, it prevents the tangled dependencies often found in two-way data binding systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68637f4b-dc8f-494a-83e1-77ae4cfc1b29', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain how Next.js handles global state management compared to traditional React apps.', N'Middle', N'In Next.js, particularly with Server Components, global state is often moved to the server-side via URL parameters or direct database access. For client-side interactivity, developers typically use React Context or third-party libraries within Client Components, keeping the state scope as localized as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88c21005-f0ec-4958-b820-77b02964cdf4', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What does it mean for Dart to be a type-safe language?', N'Intern', N'Being type-safe means that the value of an expression will always match the static type of the expression. This allows Dart to catch many errors at compile-time rather than at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a38dc636-face-4cc8-9930-77b053bc0808', N'4c000000-0000-0000-0000-000000000005', N'What is the role of a load balancer in a distributed system?', N'Middle', N'A load balancer distributes incoming network traffic across multiple servers to ensure no single server bears too much demand. This improves system availability, reliability, and responsiveness by preventing bottlenecks and providing failover capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aad72f99-0bf4-431e-aa6a-77b0ffd438fe', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the elements of a good software architecture?', N'Senior', N'Robust software architecture makes systems sustainable and manageable. Here are the key elements: Core Components - Software Components: Building pieces optimized for specific functions. - Connectors: Mechanisms to link components, such as interfaces or integration patterns. - Constraints: Design rules and standards that components and connectors must adhere to. Principles of Design - Modularity: Dividing components into logical, self-contained units for versatility, reusability, and reduced complexity. - Consistency: Maintaining uniformity throughout for ease of comprehension and usage. - Simplicity: Favoring straightforward, understandable solutions over intricate ones. Technical Elements - Layers: Segregating components based on their responsibilities into distinct layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec36f6e0-85b8-4e19-a786-77b1ae35c9a5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the ''QRL'' (Qwik Resource Locator) in the framework?', N'Middle', N'A QRL is a unique identifier used to link an interaction to a specific lazy-loaded function or component. It acts as a pointer that tells the browser which piece of code to download and execute for a particular task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fea66d0-06f6-409f-9684-77b467ca382a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Discuss the trade-offs of using Echo''s built-in Error Handler versus a custom global error handling middleware.', N'Senior', N'The built-in error handler provides a standardized way to return responses, but it lacks the flexibility for complex logging, metrics instrumentation, or cross-cutting error transformation. A custom middleware allows for centralized observability and consistent API error formats across the entire application stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
