INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d33f02f-d01c-41d4-84d5-77c05318fef9', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is it important to define a ''timeout'' for network requests?', N'Middle', N'Timeouts prevent an application from waiting indefinitely for a slow or unresponsive service, which could lead to resource exhaustion. By failing fast, the system can gracefully handle the failure and maintain overall stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65e65e31-e587-4a9d-8b08-77c261ab65a8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a cache-aside pattern versus a write-through cache?', N'Junior', N'Use cache-aside when you want to minimize write latency and only cache frequently read data. Use write-through if data consistency is critical and you want to ensure the cache is always updated immediately when the database is modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
