INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39e66519-c296-4ce6-b014-77de1fa407af', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the main rules of promise', N'Intern', N'A promise must follow a specific set of rules: 1. A promise is an object that supplies a standard-compliant .then() method 2. A pending promise may transition into either fulfilled or rejected state 3. A fulfilled or rejected promise is settled and it must not transition into any other state. 4. Once a promise is settled, the value must not change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0248205e-4ffc-42cf-a95a-77e0e637fee3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is data modeling in Cassandra considered ''query-driven'' compared to normalized relational modeling?', N'Middle', N'In Cassandra, you design your tables specifically to support individual query patterns rather than focusing on data normalization. Because Cassandra does not support efficient joins, data is often denormalized and duplicated across multiple tables to ensure that a single query can retrieve all necessary information from one partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f498960d-0850-4253-ac8a-77e40dcce387', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'When designing a large-scale Flask application, how do you manage configuration across different environments?', N'Senior', N'You should utilize a hierarchical configuration approach, typically using a base class for common settings and subclasses for specific environments like production, staging, and development. Sensitive credentials should be injected via environment variables or a secrets management service to ensure they are never committed to version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
