INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53db84ac-4304-47e6-9098-77e5f87f2eae', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the seal method', N'Intern', N'The Object.seal() method is used to seal an object, by preventing new properties from being added to it and marking all existing properties as non-configurable. But values of present properties can still be changed as long as they are writable. The next level of immutability would be the Object.freeze() method. Let''s see the below example to understand more about seal() method', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9df76bb8-e8f7-48d8-b0ac-77e7332666bf', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the trade-offs of using ''Extensions'' versus ''State'' for data sharing.', N'Senior', N'Extensions are dynamic, type-mapped containers that can be modified at runtime, whereas State is statically typed and injected at the router level. State is generally preferred for core dependencies due to compile-time safety and better performance, while Extensions are better suited for request-scoped data added by middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bad16fe-d890-43a8-98df-77e89a23b1eb', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a clustered and non-clustered index?', N'Fresher', N'A clustered index determines the physical order of data in a table, meaning the table can only have one clustered index. A non-clustered index creates a separate structure that points to the actual data, allowing multiple non-clustered indexes on a single table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e09bb03-ced7-405d-ae14-77ea7e140fd5', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do databases usually resolve deadlocks?', N'Fresher', N'The database management system typically detects deadlocks through a wait-for graph or timeout mechanism. Once detected, it aborts one of the involved transactions, rolls back its changes, and allows the other transactions to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98ece8f5-130c-4b94-893d-77eba876b02d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Global Scope in Eloquent and when might you use it?', N'Middle', N'Global Scopes allow you to add constraints to all queries for a given model automatically. They are commonly used for features like ''soft deletes'' or multi-tenancy, where you want to ensure specific data is always filtered out by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b298a5b-3c74-40df-ae72-77ec396721c1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When should you prefer a monolithic architecture over a microservices architecture for a new project?', N'Senior', N'A monolith is preferred during the early stages of a project where team velocity is critical and the domain boundaries are not yet clearly defined. It simplifies deployment, testing, and cross-service communication, allowing for rapid iteration until the system reaches a scale where modularity becomes a necessity rather than an overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f771a2ce-0a9c-4f2a-9955-77ed83610362', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the ''volatile'' keyword?', N'Fresher', N'The volatile keyword tells the compiler that a variable''s value can change at any time due to external factors outside the program''s control, such as hardware or interrupt service routines. This prevents the compiler from optimizing away reads or writes to that variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac9e7a97-f64f-4c9b-8dc4-77ee1f5a9c1e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you implement CORS in Echo?', N'Fresher', N'CORS, or Cross-Origin Resource Sharing, is handled in Echo through a dedicated middleware package. This middleware allows the server to specify which origins are permitted to access resources on the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'323b1a43-9099-4155-9018-77ee1f84dbce', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it important to keep the event loop ''unblocked''?', N'Middle', N'Because Node.js runs on a single thread, any code that takes a long time to execute will block the entire process from responding to new requests. Keeping the loop unblocked ensures that the application remains responsive and maintains high throughput for concurrent users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2691a0b5-3ee8-4082-98f5-77f01f2a34c2', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you implement graceful shutdown for a service using multiple background goroutines?', N'Senior', N'Graceful shutdown is typically implemented by using a synchronization primitive like a WaitGroup to track active tasks and a context cancellation signal to notify them to stop. The main process waits for all goroutines to signal completion before exiting, ensuring no requests are dropped or state is corrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b3345ac-b2ff-4e32-8c3d-77f62f255909', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the architectural impact of Remix''s ''unopinionated'' approach to server runtimes?', N'Senior', N'Remix is built on the Web Fetch API, making it portable across any environment from Node.js to edge runtimes like Cloudflare Workers. This flexibility allows developers to deploy applications in the most geographically advantageous locations without refactoring core logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11928c3c-6398-4c28-8361-77fabcc3fba5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the ''resolve.alias'' configuration in Vite, and when should it be avoided?', N'Senior', N'Aliases improve developer experience by providing shorthand paths for deep directory structures. However, excessive use can obscure file dependencies and make it harder for external tools or IDEs to track absolute paths if not configured consistently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ec94a84-71ad-48ec-9c27-77fe07594f22', N'954a0331-deff-4399-b588-96f39fec001d', N'Describe the trade-offs of using Server-Side Rendering (SSR) via Angular Universal or Hydration.', N'Senior', N'SSR significantly improves First Contentful Paint and SEO by delivering a pre-rendered HTML structure to the client. However, it introduces complexity regarding state synchronization (transfer state) between the server and client and can lead to a ''double-bootstrapping'' performance penalty if hydration is not handled correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'618e3d78-04ad-4dd1-966c-77fe19beb3e8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Is Vite suitable for small projects?', N'Fresher', N'Yes, Vite is excellent for small projects because it is lightweight and requires almost no configuration. Its fast startup time provides a great developer experience even for simple prototypes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cd18756-5638-45cf-be58-78020fcd02c3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate a project but have very little information, how do you handle it?', N'Junior', N'I would provide a rough order of magnitude estimate based on the limited information while explicitly stating the assumptions I made. I would also emphasize that the estimate is subject to change as more requirements are clarified and request a follow-up meeting to refine the details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1853a68e-318a-4592-b79f-7802de33746e', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s template rendering system handle dynamic content securely?', N'Senior', N'Rocket supports server-side template rendering with automatic context escaping. By binding data to templates, the framework mitigates cross-site scripting risks by ensuring that user-provided input is properly sanitized before being injected into the HTML stream.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51a1c092-78f0-44cb-ab85-78043ffac26a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime scheduler implement M:N scheduling?', N'Middle', N'The Go scheduler multiplexes M goroutines onto N OS threads. It uses a work-stealing algorithm to distribute goroutines across threads, ensuring that if one thread is blocked or idling, other threads can take over tasks to maximize CPU utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a7c5f7c-ab03-4e20-9a05-78047fedcb5e', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the concept of eventual consistency in a distributed system.', N'Middle', N'Eventual consistency is a consistency model that guarantees that if no new updates are made to a data item, eventually all accesses will return the last updated value. This approach is often chosen in scalable systems to improve availability and write performance, accepting that some replicas might temporarily serve stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd18d0cd1-3df7-4322-a281-78060dbd66a5', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is ''lit-html'' considered a library rather than a framework?', N'Senior', N'Lit-html is a focused library for efficient HTML templating and DOM updates, without enforcing specific architectural patterns or state management. It provides the low-level rendering engine, while the Lit base class builds a full component framework on top of it by adding lifecycle management and reactive properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
