INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5211f00-6223-47f5-a662-780efc36949b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with an intermittent bug in a production environment, what is your systematic approach to troubleshooting?', N'Middle', N'I start by isolating the variables and reviewing logs for patterns that correlate with the reported failures. Once a hypothesis is formed, I attempt to reproduce the environment configuration in a staging area to verify the cause. If reproduction fails, I implement targeted observability, such as distributed tracing or increased logging, to capture the state during the next occurrence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b9737ee-ab92-48ce-b35b-78112ac109c2', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the security implications of using Flask''s default session handling?', N'Middle', N'Flask''s default session uses client-side signed cookies, meaning the data is visible to the user but protected from tampering via a secret key. You must ensure the secret key is cryptographically strong and kept private, and you should never store sensitive data like passwords or internal IDs in the session, as it can grow too large and expose information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6adc76d-fd9b-433a-8801-7811da32d715', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between a page.svelte file and a layout.svelte file?', N'Fresher', N'A page.svelte file defines the content for a specific route, while a layout.svelte file provides a shared structure, such as headers or footers, that persists across multiple routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2c1fb7e-5a97-4376-9546-78121b5b6fe5', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle read requests when data is spread across replicas?', N'Junior', N'Cassandra typically uses a read repair mechanism or a consistency level setting to check multiple replicas for the latest version of the data. By comparing timestamps across nodes, the system ensures the most recent write is returned to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3079eb96-872d-4d6d-8134-7813370f4a93', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the concept of ''Hydration'' in the context of Next.js and why it is a performance bottleneck.', N'Senior', N'Hydration is the process where the client-side JavaScript takes over the static HTML rendered by the server to attach event listeners and state. It becomes a bottleneck when the bundle size is large, as the browser must parse and execute all JavaScript before the page becomes fully interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17a0d2be-011b-4a7b-a309-7814b1a314bd', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are dynamic parameters in Rocket routes?', N'Fresher', N'Dynamic parameters are placeholders in a URL path that allow a single route to handle various inputs. For example, a route can capture an ID from the URL and pass it as an argument to the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e9b64e1-d443-4cfd-842f-7816df3f1c9a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does Multi-Version Concurrency Control (MVCC) work in PostgreSQL?', N'Middle', N'MVCC allows multiple users to access the database simultaneously by keeping multiple versions of each row. Each transaction sees a snapshot of the data as it existed at the start of the transaction, which prevents readers from blocking writers and vice versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5cfe3de-11b2-4234-b6fb-781a9749313d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does escape analysis enable stack allocation or scalar replacement?', N'Senior', N'Escape analysis determines if an object is only accessed within a single method and does not ''escape'' to other threads or methods. If it doesn''t escape, the JVM can optimize by allocating the object on the thread stack or breaking it into individual variables, eliminating the need for heap allocation and GC.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82ff580a-7cbb-4a5a-9b8b-781eac478494', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the first thing you do when you are assigned a new ticket?', N'Junior', N'I read the ticket carefully to understand the context, expected outcomes, and any specific constraints. I then look for related documentation or existing code to see how it fits into the current system. If anything is unclear, I ask questions immediately to avoid wasting time on incorrect assumptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e7914a-d1fa-4a1e-9d68-7820ef5a8c57', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do optimistic and pessimistic locking differ in distributed environments?', N'Middle', N'Pessimistic locking prevents conflicts by locking a resource when it is first accessed, which can reduce throughput. Optimistic locking assumes conflicts are rare, checking for version changes only at the time of commit, which provides better performance in read-heavy systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6273a74-ba10-4c40-9c0f-782871cc22b4', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is ''Pattern Matching'' and why is it powerful?', N'Middle', N'Pattern matching is a control flow mechanism that matches a value against a sequence of patterns. It is more powerful than a switch statement because it can decompose data structures, check types, and extract values, significantly simplifying complex conditional logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'509d936d-5d27-4fdd-be00-7829885f1f14', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''strictFunctionTypes'' flag affect variance in TypeScript?', N'Senior', N'By default, TypeScript allows bivariant argument checking for functions, which is unsound but convenient. Enabling this flag forces contravariant argument checking, ensuring that a function parameter type is a supertype of the function it replaces, which is the mathematically correct behavior for subtyping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05c8b639-10a7-4b87-8b8e-7829ededc669', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Doctrine ORM?', N'Intern', N'Doctrine is an Object-Relational Mapper that sits between the database and the PHP objects in Symfony. It allows developers to interact with database records as if they were simple objects, abstracting away complex SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd55d23cf-d966-4b1e-b041-782b52525eb5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the performance implications of using AdonisJS''s auto-discovery for providers?', N'Middle', N'Auto-discovery simplifies project setup by automatically detecting and registering providers in the IoC container. While this adds a small amount of overhead during the initial boot sequence, it does not impact the runtime performance of the application once it is fully initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4648752e-a6e9-4fb8-a2ae-7832a008eb99', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does it mean to optimize for ''readability'' over ''cleverness'' in code?', N'Junior', N'Code is read far more often than it is written, so it should be simple and easy for others to understand. ''Clever'' code might be concise but often becomes a burden for others to debug or modify later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58504609-5cae-4058-a593-783442497b6e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular Material?', N'Intern', N'Angular Material is a collection of Material Design components for Angular framework following the Material Design spec. You can apply Material Design very easily using Angular Material. The installation can be done through npm or yarn, It supports the most recent two versions of all major browsers. The latest version of Angular material is 8.1.1', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24bebdac-7943-4c33-98f6-783722d2c7c9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain ''Compaction'' in the context of LSM-tree based databases.', N'Senior', N'Compaction is the background process of merging smaller SSTables into larger ones and discarding obsolete data like deleted records or overwritten values. It is critical for reclaiming storage space and maintaining read performance by keeping the number of files to search at a minimum.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb30fa95-fb8d-4ca6-8d8d-78373ae1fa5b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the ''curiously recurring template pattern'' (CRTP) provide static polymorphism?', N'Senior', N'CRTP uses a base class template that takes the derived class as a template parameter, allowing the base to call derived class methods at compile time. This avoids the cost of virtual function calls and vtable lookups while maintaining a polymorphic interface, effectively providing the benefits of inheritance without the runtime overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd5bfd61-39e4-4405-ba3b-78388fefcd69', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL schema?', N'Intern', N'A schema is a namespace within a database that organizes database objects like tables, views, and indexes. It helps in grouping related objects together and managing permissions for different users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12f5d0d0-14d8-4ec4-9975-783916610799', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the goal of refactoring code as part of your development process?', N'Junior', N'The primary goal is to improve the internal structure and readability of the code without changing its external behavior. This makes the system easier to maintain, extend, and debug in the future. It is a proactive way to reduce technical debt and ensure long-term system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f693151b-6a97-48e2-b3c5-783a2e9f94d4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between Bind and ShouldBind methods in Gin?', N'Junior', N'Bind methods will automatically write a 400 Bad Request error to the response if the data is invalid or cannot be parsed. ShouldBind methods return an error object, allowing the developer to handle the error manually and return a custom response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81b4d246-b7b8-45df-8af9-783c3ec7379c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to apply validation on props in React?', N'Fresher', N'When the application is running in _development mode_, React will automatically check all props that we set on components to make sure they have _correct type_. If the type is incorrect, React will generate warning messages in the console. It''s disabled in _production mode_ due to performance impact. The mandatory props are defined with isRequired. The set of predefined prop types: 1. PropTypes.number 2. PropTypes.string 3. PropTypes.array 4. PropTypes.object 5. PropTypes.func 6. PropTypes.node 7. PropTypes.element 8. PropTypes.bool 9. PropTypes.symbol 10. PropTypes.any We can define propTypes for User component as below: Note: In React v15.5 _PropTypes_ were moved from React.PropTypes to prop-types library. _The Equivalent Functional Component_', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d18e229-1d1e-49a5-8b2f-783cb761a8e6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the ''Kernel'' class in Symfony?', N'Middle', N'The Kernel is the heart of the Symfony application. It is responsible for managing the bundle lifecycle, initializing the service container, and orchestrating the Request to Response conversion process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed0126af-74ed-432f-92bb-783cf2dfe6d6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What does ''fast refresh'' mean in Next.js?', N'Intern', N'Fast refresh is a development feature that provides near-instant feedback when you make changes to your code. It keeps the component state intact while updating the UI, allowing you to iterate quickly without losing your progress on the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b758fa04-c257-498f-b1a8-783d83b699ee', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the let keyword', N'Intern', N'The let keyword in JavaScript is used to declare a block-scoped local variable. This means that variables declared with let are only accessible within the block, statement, or expression where they are defined. This is a significant improvement over the older var keyword, which is function-scoped (or globally-scoped if declared outside a function), and does not respect block-level scoping. Key Features of let: - Block Scope: The variable exists only within the nearest enclosing block (e.g., inside an {} pair). - No Hoisting Issues: While let declarations are hoisted, they are not initialized until the code defining them is executed. Accessing them before declaration results in a ReferenceError (temporal dead zone).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3b30b31-6bbb-4bed-8348-783dfe8e9215', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you evaluate whether a third-party library is suitable for an enterprise-grade Angular application?', N'Senior', N'Evaluation should consider the library''s bundle size, its compatibility with Ivy and AOT compilation, and whether it follows Angular''s DI and lifecycle conventions. It is also critical to check the maintenance frequency, community support, and whether the library provides ''schematics'' for easier integration and upgrades.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aa38a5c-ba7e-4fdb-987c-783e3df756e6', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the Lit render method?', N'Intern', N'The render method is where you define the structure of your component''s template. It returns the markup that should be displayed, and Lit calls this method whenever a reactive property changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae7c3dea-72dd-41ee-aecd-783f34c9d44c', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary purpose of Alpine.js in web development?', N'Intern', N'Alpine.js is a lightweight, declarative JavaScript framework used to add interactivity to HTML pages. It is designed to provide the behavior of large frameworks like Vue or React without the complexity of a build step or heavy bundle sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20315ca7-1c66-4f5f-8717-784586ab1f47', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of Middleware in NestJS?', N'Fresher', N'Middleware is a function called before the route handler. It has access to the request and response objects and the next middleware function in the application’s request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'689a4b7d-6491-4a48-b4f9-78478dc4eafa', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Are NoSQL databases always faster than SQL databases?', N'Intern', N'Not necessarily. NoSQL databases are often faster for specific workloads like write-heavy applications or simple key-value lookups at scale. However, for complex queries and transactional integrity, relational SQL databases can be more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0070fc7a-1855-4b08-b1ee-784957c8f96e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the primary benefit of using Signals over Redux or other global stores?', N'Junior', N'Signals are built into the framework and provide a simple, localized way to manage state without needing external libraries. They are highly performant and integrate directly with the reactivity system, reducing boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f43d50ae-8e4f-4906-8a3e-784af2fcf2d9', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''optimization.splitChunks''?', N'Middle', N'The splitChunks configuration allows Webpack to automatically identify and extract common dependencies into separate chunks. This prevents code duplication when multiple entry points rely on the same libraries, resulting in smaller overall bundles and improved caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ff4dce6-216c-481e-b3d9-784b1d733dab', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it often better to use cursor-based pagination over offset-based pagination in large datasets?', N'Senior', N'Offset-based pagination suffers from performance degradation as the offset grows because the database must scan and discard preceding rows. Cursor-based pagination uses a stable pointer to the last retrieved record, ensuring O(1) lookups regardless of the dataset size and avoiding issues with skipped or duplicate records during concurrent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2225f881-84ef-4f62-965f-784d97a6c1d6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s Cache component leverage different storage backends, and how do you choose the right one?', N'Senior', N'The Cache component provides a unified PSR-6/PSR-16 interface that abstracts away the storage layer. Choosing the backend involves balancing latency and persistence requirements; in-memory stores like Redis are ideal for high-throughput distributed environments, while filesystem caches are suitable for single-node configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4b83e86-5d5b-41ef-8186-784e0b5463b7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Rails asset pipeline affect deployment architecture?', N'Senior', N'The asset pipeline compiles and fingerprints assets for cache-busting, which requires a pre-compilation step during the deployment process. Offloading asset delivery to a CDN is critical for performance, as it ensures that static files are served geographically close to the user and avoids putting unnecessary load on the Rails web servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cba58e78-7510-435e-9997-78545d7eb85d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How would you handle a scenario where a background job needs to interact with a model that has since been updated by a user?', N'Senior', N'Use optimistic locking or pass global IDs to the job to ensure the record state is checked before execution. Alternatively, design jobs to be idempotent so that re-running them with updated data does not result in corrupted state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6957dba3-2692-4b02-9dec-78557732a620', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''rel=preconnect'' hint impact the browser''s connection management?', N'Senior', N'Preconnect allows the browser to set up early connections—including DNS lookups, TCP handshakes, and TLS negotiations—to a specific origin before an actual request is made. This reduces latency for subsequent resource loads from that domain, though it consumes extra network resources and should be used judiciously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'543b7f9c-91c2-409f-80cd-7855b987bae5', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember’s Data layer handle identity map and why is it critical for state management?', N'Senior', N'Ember Data implements an identity map pattern to ensure that a single record is represented by one unique object instance across the entire application. This prevents inconsistencies and data duplication, allowing for reliable state synchronization between the backend and the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67e6ace4-1c50-4e28-b838-7859575d5199', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a ''Package'' in Rust?', N'Fresher', N'A package is a collection of one or more crates that provide a set of functionality. A package contains a Cargo.toml file that describes how to build those crates, serving as the unit of distribution in the Rust ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59d0aa65-4713-460b-b716-785abf4ec87c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you know when to stop refining an estimate?', N'Intern', N'You stop refining an estimate when the cost of gathering more information exceeds the value of the increased precision. Once the estimate is ''good enough'' to support the current decision-making needs, further refinement provides diminishing returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a120528-5bea-4330-9ff5-785af7872382', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''externals'' in a Webpack configuration?', N'Senior', N'The ''externals'' configuration allows developers to prevent specific libraries from being bundled, instead expecting them to be available in the environment, such as via a global variable or a CDN. This is highly effective for reducing bundle size for large, rarely changing libraries that can be cached independently by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91991e2e-ddb2-45ca-b558-785bc06e2913', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the @extend directive differ from @mixin in terms of compiled CSS output?', N'Middle', N'@extend groups selectors together to share styles, which keeps the CSS file size smaller by reducing duplication. In contrast, @mixin copies the entire block of code into every location where it is called, which can lead to larger CSS files but avoids issues with selector specificity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e1f2d0-6fec-479c-9f82-785d419bb04c', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary benefit of read replicas in a database architecture?', N'Middle', N'Read replicas allow you to offload read-heavy traffic from the primary database instance to secondary instances. This improves the overall read throughput and provides a level of high availability if the primary node fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ecce2cb-bb4b-4fcd-a913-7862358d83dd', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What architectural benefits does Quarkus offer for serverless (FaaS) environments?', N'Senior', N'The primary benefit is the elimination of ''cold starts'' due to the tiny memory footprint and instantaneous startup of native executables. This allows applications to scale down to zero and respond immediately to incoming traffic without the latency overhead of a standard JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d86b3db-c3cd-4980-8ed1-7866544bbbba', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the function of the ''Request'' object in Axum?', N'Junior', N'The Request object represents the incoming HTTP request. While extractors simplify access to specific parts of it, the raw Request object can still be accessed if manual inspection of headers or the body is needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4acce24a-64c7-4f2d-bc45-78672a00dc3f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the performance implications of using ''final'' versus ''const'' in Dart?', N'Middle', N'Both keywords ensure immutability, but ''const'' implies compile-time constants that are canonicalized and stored in memory only once. ''Final'' variables are determined at runtime, meaning they can hold values calculated during execution, though they cannot be reassigned once initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
