INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a46b832-2d28-46df-a2b6-7869a36412f9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the role of the ''volatile'' keyword?', N'Intern', N'The volatile keyword tells the compiler that a variable''s value can change at any time due to factors outside the program''s control, such as hardware or interrupts. This prevents the compiler from performing optimizations that might assume the value stays constant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a27ccb6f-eb39-418c-9c53-786a8652b27a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary difference between pessimistic and optimistic concurrency control?', N'Middle', N'Pessimistic concurrency control prevents conflicts by locking resources before accessing them, which is ideal for high-contention environments. Optimistic concurrency control assumes conflicts are rare, allowing transactions to proceed without locks and checking for interference only at the moment of commit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46743f21-8606-46e6-91c2-786ad3e92c16', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the access specifiers in C++ and what do they do?', N'Intern', N'Access specifiers are keywords in C++ that control the visibility and accessibility of class members. They enable the principle of data encapsulation, ensuring data integrity and promoting a clear separation between a class''s interface and its implementation. Types of Access Specifiers C++ provides three main access specifiers: 1. public: Members are accessible from any part of the program. This category typically includes the class''s interface—its public methods and data. 2. protected: Access is limited to the containing class, its derived classes, and friends. This specifier is useful in inheritance scenarios. 3. private: Members are accessible only from within the containing class and its friends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd3760ec-4015-455c-a264-786b3c20ed5a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Events and Listeners?', N'Junior', N'Events and Listeners provide a simple observer implementation that allows you to trigger actions when specific things happen in your application. For example, you might trigger an event when a user registers, which then notifies a listener to send a welcome email.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60bd4f06-705a-4f6e-b781-786e1819c0e6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is meant by the term ''in-memory'' database?', N'Intern', N'An in-memory database keeps its entire dataset in the computer''s RAM. This eliminates the latency caused by disk I/O, allowing for sub-millisecond response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beb07be5-64b2-4e79-b5e8-786e624f1b70', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why does Preact favor using standard DOM attributes over React''s camelCased props?', N'Senior', N'Preact uses standard DOM attribute naming conventions to avoid the overhead of mapping between React-specific syntax and actual HTML attributes. This design choice reduces the amount of code required for attribute normalization, contributing to the framework''s smaller bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f50b5ba7-a0d2-4728-a923-7871bba205cd', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the architectural benefits of using a Reactive State Management pattern compared to simple Service-based state?', N'Senior', N'Reactive patterns enforce unidirectional data flow, making state changes predictable, traceable, and easier to debug through centralized logs or time-travel tools. Service-based state is simpler for small applications but can quickly lead to spaghetti code and ''hidden'' mutations as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa646532-6886-4004-b364-78729273e863', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of the ''load path'' ($LOAD_PATH)?', N'Middle', N'The load path is an array of directories that Ruby searches through when you call ''require'' or ''load''. Managing this path is essential for ensuring that the interpreter correctly finds project dependencies and external libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a76db7e1-162c-4fa0-848d-787327c53405', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing a system for high availability, how do you determine the appropriate redundancy level for a microservice?', N'Senior', N'I apply the N+1 redundancy principle while considering the cost-to-benefit ratio of downtime versus infrastructure expenses. I evaluate the service''s dependency graph, the impact of its failure on the user journey, and the recovery time objective to ensure resources are allocated where they prevent the most significant outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
