INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2777127e-28ab-4640-aca4-789fb2bb76fa', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you handle focus states in Tailwind?', N'Intern', N'Similar to hover states, Tailwind provides a ''focus:'' modifier. When you add this prefix to a class, that style will only be applied when the element is currently focused, such as when a user tabs into an input field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c0fd550-48d4-47fa-9c06-78a029a411fd', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is database isolation?', N'Intern', N'Isolation is the ''I'' in ACID, ensuring that concurrent transactions do not interfere with each other. It determines how the changes made by one transaction become visible to other simultaneous transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29fef542-46d8-45bc-97b6-78a2809b1c61', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you enable debug mode in Flask?', N'Fresher', N'Debug mode is enabled by setting the environment variable FLASK_DEBUG to 1 or by passing the debug=True parameter when running the app. It provides an interactive debugger in the browser and automatically reloads the server when code changes are detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce2341ee-5f07-4b91-95da-78a5deaad650', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'In the context of high-concurrency Go web servers, explain the architectural implications of using a fiber-based concurrency model versus the standard OS-thread-per-request model.', N'Senior', N'Fiber-based models, or user-space threads, significantly reduce the memory overhead and context switching costs associated with OS threads by allowing the Go runtime scheduler to manage stacks efficiently. This approach enables a system to scale to millions of concurrent connections without exhausting kernel resources. However, it requires careful handling of blocking operations, as blocking a fiber can stall the underlying OS thread if not managed by a cooperative scheduler or non-blocking I/O primitives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ab15825-200c-4cf3-9242-78a68f930123', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the challenges of ''Multi-Master'' replication?', N'Senior', N'Multi-master replication allows writes to any node, increasing write availability and reducing latency for geographically distributed users. The primary challenge is managing write conflicts and ensuring that concurrent modifications to the same record are resolved correctly across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41fe068d-f523-4ada-b6a5-78a6d741bbe9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a database connection pool exhaustion issue?', N'Middle', N'I would first verify the pool configuration metrics to see if the maximum connection limit is consistently hit. I would then inspect active transactions to identify long-running queries or connections that were not properly closed by the application code. Finally, I would check if the application threads are blocking while waiting for a connection, which indicates a need for pool tuning or query optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de6808bd-67a0-4f82-81c1-78aa6de9294b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Routing system work?', N'Junior', N'The routing system maps incoming HTTP requests to specific controller actions based on URL patterns. It interprets the request path and parameters to determine which code should execute to generate the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61810ea8-0c5e-4828-a40e-78ab507da79a', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you ensure data consistency in a distributed system accessed via an API?', N'Middle', N'Ensuring strict consistency in distributed systems is difficult, so developers often settle for eventual consistency. Techniques like distributed transactions, sagas, or optimistic locking are used to manage state changes across multiple services while minimizing the impact of network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e44bc2f-52a0-46da-8dc6-78ac34e4b822', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is the use of the `@at-root` directive considered an advanced architectural tool?', N'Senior', N'The `@at-root` directive allows you to break out of nested Sass blocks and place styles at the root level of the document. It is useful for implementing BEM naming conventions where a modifier or element needs to be defined as a standalone block, circumventing the default nesting behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3f5ca3e-145d-4aa5-a8b9-78b205736937', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug a service that is intermittently failing due to a database connection pool exhaustion?', N'Middle', N'I would analyze connection pool metrics to see if connections are being held open longer than expected or if the pool size is insufficient for the current traffic. I would then inspect the application code to ensure that connections are consistently returned to the pool after every transaction, even in error scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d536a51-08b9-4270-99d2-78ba3e684db6', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'A stakeholder asks for a feature that you know will be very difficult to implement within the current deadline. How do you handle this?', N'Junior', N'I would first communicate the technical constraints clearly, explaining why the current scope is challenging within the timeframe. I would then propose a phased approach, identifying a ''minimum viable'' version of the feature that can be delivered on time. This allows the stakeholder to achieve their primary goal while maintaining project stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6317a9-621e-4f5c-9fb1-78bb28b9f60a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between a symptom and a root cause?', N'Intern', N'A symptom is the observable effect of a problem, while the root cause is the underlying defect that triggered the chain of events leading to that effect. Fixing a symptom may stop the immediate issue, but addressing the root cause prevents it from recurring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
