INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4e16831-90ce-4fd9-836e-78c65821b74c', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB ensure read isolation in a multi-node environment?', N'Senior', N'MongoDB provides read isolation through various read concerns and causal consistency sessions. By using a read concern of ''majority'' or ''snapshot,'' the database ensures that clients only read data that is durable and consistent, preventing the observation of uncommitted or rolled-back data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90f72a1c-aa76-49d2-8d1e-78c8ebfb1825', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the architectural implications of using the ''invokedynamic'' instruction?', N'Senior', N'Invokedynamic decouples the call site from the method resolution logic, allowing the language runtime to define how method linkage occurs at runtime. This is the cornerstone for high-performance support for dynamic languages on the JVM and for features like Lambda expressions, as it enables site-specific optimization rather than relying on static reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19623cf7-2a71-4ce8-abd3-78c9c92d4e81', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage memory usage in long-lived single-page applications?', N'Senior', N'Because Qwik only loads the code chunks that are actually used, the memory footprint remains significantly lower than that of traditional frameworks. As the user navigates through different parts of the application, the framework can unload or simply not load unused chunks, preventing the heap from bloating over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdac5f87-75d4-419b-92be-78cb193519b8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the trade-offs in choosing AdonisJS for a microservices architecture?', N'Senior', N'AdonisJS is a monolithic-first framework, meaning its heavy reliance on the IoC container and provider system can lead to bloated artifacts if used for small, single-function microservices. However, its modularity allows it to be stripped down, provided the developer invests effort in removing unused providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
