INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ab0306-0f90-4cf4-8e5f-78d93e609883', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of database replication in a scalable system?', N'Middle', N'Database replication creates copies of data across multiple servers, typically separating read-heavy operations from write operations. By routing read requests to replicas, the system can scale its read throughput horizontally and improve data availability in case of a primary server failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
