INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ba1cda-3208-4c0c-9202-78ddf5791575', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is meant by the term ''interoperability'' between Kotlin and Java?', N'Intern', N'Interoperability means that Kotlin and Java code can coexist and interact seamlessly within the same project. Kotlin is designed to be fully compatible with existing Java libraries and frameworks, allowing developers to call Java code from Kotlin and vice versa without complex configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78595b38-096a-4b31-86df-78df4c04ff83', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask request object?', N'Intern', N'The request object is a global object provided by Flask that contains all the data sent by a client to the server during an HTTP request. It includes information like form data, query parameters, headers, and files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fca9d52-9ee4-4592-86c5-78e1b47b4a1f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Mass Assignment protection?', N'Junior', N'Mass Assignment protection prevents users from passing unexpected HTTP request input into your database models. By default, Laravel requires you to explicitly define ''fillable'' or ''guarded'' attributes on your model to specify which fields are allowed to be updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37e7ff5b-2c7e-417d-8038-78e2ac0194ce', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the role of an eviction policy in a memory-constrained cache?', N'Middle', N'An eviction policy determines which items to remove from the cache when it reaches its maximum capacity. Without an effective policy, the cache would fill up quickly and stop accepting new data, rendering it useless for dynamic application workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'184562e0-5335-444c-ac30-78e2d19ecfb9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s method dispatch mechanism handle inheritance in S3 classes?', N'Senior', N'S3 dispatch uses a class vector attribute to determine the method to execute, checking each class in the vector sequentially until a matching generic method is found. This allows for simple, linear inheritance but lacks the rigorous type safety and multiple dispatch capabilities found in more complex systems like S4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ce2e1bc-1d1f-4398-a606-78e59e6763ad', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the concept of ''Write-Ahead Logging'' (WAL) and its role in durability.', N'Senior', N'WAL ensures that all modifications are written to a persistent log on disk before they are applied to the primary database files. This guarantees that if a crash occurs, the system can replay the log to recover its state, ensuring durability without requiring a heavy checkpoint of the entire dataset on every transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0fd6d2c-19ea-4a9c-b829-78e8346d512e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does the term ''Resumability'' mean in Qwik?', N'Intern', N'Resumability is the ability of an application to pause execution on the server and resume it on the client without re-downloading or re-executing the entire application state. It allows the browser to interact with the page immediately after the HTML is loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'756403c1-6c0f-435a-942e-78f0da1077df', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is ''SFINAE'' (Substitution Failure Is Not An Error) significant for generic programming?', N'Senior', N'SFINAE allows the compiler to silently discard template specializations that are ill-formed during substitution rather than throwing a hard error. This feature is the foundation for template metaprogramming techniques that inspect type properties, allowing developers to create highly generic code that adapts its behavior based on the capabilities of the provided types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
