INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7be063e9-a071-4b53-8fde-78f1d993d412', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Dependency Injection in Symfony?', N'Intern', N'Dependency Injection is a design pattern where an object receives its dependencies from an external source rather than creating them internally. In Symfony, the container automatically injects these dependencies into classes, making the code more flexible and decoupled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'456c4a4f-b9c4-4900-8b1c-78f27de56126', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the function of a junction table?', N'Fresher', N'A junction table is an intermediate table used to resolve many-to-many relationships between two other tables. It contains foreign keys referencing the primary keys of the tables it is connecting, effectively breaking the relationship into two one-to-many connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
