INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b6a8798-d7ad-4798-8e0b-791a679a7064', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of ''Mass Assignment'' and how Laravel protects against it.', N'Middle', N'Mass assignment occurs when an application accepts user input directly into a model, potentially allowing unauthorized updates to sensitive fields. Laravel mitigates this by requiring developers to explicitly define ''fillable'' or ''guarded'' attributes on the model to whitelist or blacklist fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
