INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f2092d5-3df7-4594-940f-79238b740cd8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the CAP theorem and how does it influence NoSQL database design?', N'Middle', N'The CAP theorem states that a distributed system can only provide two out of three guarantees: Consistency, Availability, and Partition Tolerance. Because network partitions are inevitable in distributed systems, designers must choose between Consistency and Availability, leading to the creation of AP or CP database architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
