INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1b69da2-5c38-43af-837e-793499925095', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a ''CommitLog'' in Cassandra and why is it used?', N'Junior', N'The CommitLog is an append-only log on disk that records every write operation performed by the database. It acts as a crash recovery mechanism, ensuring that data is not lost if the node fails before the data is flushed from memory to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'671aa9de-58c6-439a-9526-7936b4ba1bbb', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind integrate with CSS Variables to support dynamic theming?', N'Senior', N'Tailwind can map design tokens to CSS variables, allowing for runtime updates like dark mode or brand color changes without recompiling the CSS. This combines the performance of static utility classes with the flexibility of dynamic runtime styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c473bbb9-ab81-4a94-a88a-7937113bb1fe', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the ternary operator in Python?', N'Fresher', N'Unlike C++, we don''t have ?: in Python, but we have this: [on true] if [expression] else [on false] If the expression is True, the statement under [on true] is executed. Else, that under [on false] is executed. Below is how you would use it: ex 1. Ans: 2 ex 2. Ans: Hi', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8de28c8a-1ebc-4b28-9d63-793a7d38863c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between factory constructors and generative constructors?', N'Middle', N'Generative constructors always create a new instance of the class. Factory constructors do not necessarily create a new instance; they can return a cached instance, a subclass, or perform complex logic to decide what to return, making them useful for implementing patterns like the singleton or object pooling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a33fdcd1-f7e4-47ea-b077-793bbffae7be', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine the appropriate granularity for microservices?', N'Senior', N'I use Domain-Driven Design principles to identify bounded contexts, ensuring that service boundaries align with business capabilities. I avoid making services too small to prevent excessive operational overhead and complex cross-service communication patterns, focusing instead on independent deployability and ownership.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f53e93a-d4c5-46d8-9c27-793d16a1261a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the compaction process in Cassandra and why is it necessary?', N'Senior', N'Compaction merges multiple SSTables into a single file while discarding obsolete or deleted data marked by tombstones. This process is essential to reclaim disk space and optimize read performance by reducing the number of files the coordinator must search.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0f465df-ef15-4dd0-a32e-7940115bd7a9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Describe the integration of Panache within Quarkus.', N'Senior', N'Panache is an abstraction layer that simplifies Hibernate ORM usage by reducing boilerplate code and enforcing common patterns. It allows developers to focus on domain logic while Quarkus handles the underlying persistence complexity through optimized build-time generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a82e674-4b3f-4f4f-b47d-7940cbba765d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a covering index and a standard index?', N'Senior', N'A covering index contains all the columns requested by a query, allowing the engine to retrieve the data directly from the index tree without fetching the actual row from the data pages. This significantly reduces I/O by eliminating the ''bookmark lookup'' step.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92c709be-d891-477a-9834-7943b2506da0', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the ''Background Tasks'' feature in Litestar used for?', N'Middle', N'Background tasks allow you to queue operations that should run after the response has been returned to the client. This is ideal for tasks like sending emails or processing data that do not require an immediate result to be returned to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6956c56f-4cfe-4a04-9b89-7943c48434b0', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle the estimation of a task that is ''boring'' or repetitive compared to a creative task?', N'Junior', N'I apply the same rigor to repetitive tasks as I do to complex ones, as monotony often leads to human error. I might estimate a bit more time for these tasks to allow for extra review or, ideally, suggest a way to automate the repetitive parts to reduce the effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'271b3ad9-b07f-4dfd-8427-79481b65d850', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you change the primary key of an existing DynamoDB table?', N'Junior', N'No, the primary key structure is defined at table creation. To change it, you must create a new table and migrate your data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02117e25-1ded-4490-b786-794e720d12e9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the consequences of using variadic functions in C?', N'Senior', N'Variadic functions lack compile-time type checking for their arguments, which can lead to runtime errors if the caller does not match the format strings or expectations of the callee. They require the use of special macros from the standard library to traverse the argument list, which relies on platform-specific stack layout assumptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb1fd376-4b5a-4eff-b038-794e88359235', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte slots and how do they enhance component reusability?', N'Middle', N'Slots are placeholders that allow parent components to inject content into child components. They enable the creation of flexible wrapper components that define layout structure while remaining agnostic to the specific content being rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6583baf0-1470-4d29-95bf-794f55f0c587', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a teammate disagrees with your proposed solution, how do you handle it?', N'Fresher', N'I listen carefully to their reasoning to understand their perspective and look for technical merits in their argument. If we remain at an impasse, I suggest a small experiment to test both ideas or consult a senior team member for guidance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40f66345-eae6-4368-bef5-79505d72113b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a unique key?', N'Fresher', N'A unique key ensures that all values in a column or set of columns are distinct across the table. Unlike a primary key, it can allow null values depending on the specific database implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65f0ae3a-2a60-48aa-9928-7952faabcac8', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What happens if a panic occurs in a Chi handler?', N'Fresher', N'Chi includes a built-in middleware called Recoverer. If a panic occurs in a handler, this middleware catches it and prevents the entire server from crashing, typically logging the error and returning a 500 status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0920242e-0299-4dff-8451-7954931a71b4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose to implement server-side rendering (SSR) over client-side rendering (CSR)?', N'Junior', N'SSR is generally preferred for SEO-heavy content and faster initial page loads since the server sends a fully rendered page to the browser. CSR is often better for highly interactive dashboards or internal applications where the initial load time is less critical than the subsequent user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'832c6794-b9e1-4130-836b-7956b14c77e0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the main benefit of Nuxt''s auto-import feature?', N'Intern', N'Auto-import allows you to use Vue functions, components, and composables without manually importing them at the top of every file. This reduces boilerplate code and makes development faster and cleaner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd70cd45d-5844-474a-a134-79579a3abfa9', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the ''thundering herd'' problem in the context of caching?', N'Middle', N'The thundering herd problem occurs when a large number of clients request the same data simultaneously when the cache is empty or expired, overwhelming the backend. It is often addressed by implementing distributed locks to ensure only one request retrieves the data while others wait or retry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f5a9b7-36fa-4be7-8fc4-7958b620b8e5', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does ''panic!'' do?', N'Junior', N'The panic! macro stops the current thread of execution immediately and cleans up the stack. It is used for unrecoverable errors where the program cannot continue safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09e045b3-2cf4-4733-8c76-795b5b0bddf0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''Result'' type?', N'Fresher', N'The Result type is used for functions that might fail. It returns either an Ok variant containing the success result or an Err variant containing information about what went wrong, ensuring errors are handled explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f79ab36e-9761-4a0b-983d-795c9f556da3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte approach component isolation and CSS scoping?', N'Middle', N'Svelte automatically scopes CSS to the component by appending unique hashes to class names. This prevents style leakage and ensures that styles defined in one component do not accidentally affect other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9543c740-b342-4e52-aa35-795cf89c62db', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono achieve its characteristic high performance?', N'Middle', N'Hono utilizes a highly optimized router based on a Radix tree implementation. By minimizing overhead and avoiding heavy dependencies, it maintains a small memory footprint and fast request matching, which is crucial for edge computing environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
