INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02d4dac7-451f-4f7b-a8f0-796038d50472', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does move semantics improve performance in C++?', N'Middle', N'Move semantics allow the resources held by a temporary object to be transferred to another object rather than being copied. This avoids expensive deep copies of large containers or buffers, as it simply involves pointer reassignment and nullifying the source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd46b93b6-4976-4060-9468-79616706b1f9', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why should you avoid using synchronous methods in Express route handlers?', N'Middle', N'Synchronous methods block the Node.js event loop, preventing the server from processing other concurrent requests. This leads to a decrease in throughput and makes the application unresponsive under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330220d1-5e71-4046-a03d-7963d81dbf46', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit''s ''server-only'' modules prevent sensitive data leakage?', N'Senior', N'SvelteKit enforces a module boundary where files ending in ''.server.js'' or ''.server.ts'' are explicitly excluded from the client-side bundle. This architectural constraint prevents sensitive code, such as database credentials or private API keys, from ever reaching the browser, mitigating common security risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab91363-fb5b-46de-9ea0-79675cb0bffc', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the benefit of API versioning, and what are the common strategies?', N'Middle', N'Versioning ensures backward compatibility so existing clients do not break when updates are deployed. Common strategies include URI versioning, header versioning, or query parameter versioning, each with different trade-offs regarding cacheability and URL cleanliness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a51d2e1a-c12b-4a09-b112-79683971005d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you send a response back to the client in Flask?', N'Fresher', N'You can return a string, a dictionary, or a template rendered through the render_template function. Flask automatically converts these return values into an HTTP response object with the appropriate status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b084746e-c8a1-4dfd-ac3a-796845c95426', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do ''Observers'' and ''Telemetry'' in Phoenix assist in production-level observability and bottleneck identification?', N'Senior', N'Telemetry allows the application to emit structured events at specific lifecycle points, which can be hooked into metrics systems like Prometheus or OpenTelemetry. Combined with the Erlang Observer, which provides a live visualization of process heaps and run queues, developers can identify memory leaks or CPU bottlenecks in real-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6c999f3-7b2d-4f0a-9fcf-796a5879648f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the security risks associated with server-side data fetching in Next.js, and how should they be mitigated?', N'Senior', N'The primary risk is exposing sensitive API keys or database connection strings within server-side code that could be accidentally leaked to the client. Mitigation involves using environment variables, ensuring strict server-only boundaries, and never passing raw database entities directly to client components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'823b34ac-13ef-406c-ae31-7971bca5ad0a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle request throttling, and what is the best practice for client-side handling?', N'Senior', N'DynamoDB throttles requests when throughput exceeds the provisioned or bursting limits. The best practice is to implement exponential backoff with jitter on the client side to retry failed requests gracefully. This prevents a thundering herd problem and allows the system time to recover without overwhelming the storage layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc431e11-4e32-4f43-ad4b-7974a06f4f9f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the benefit of using an Express generator?', N'Junior', N'The Express generator is a command-line tool that quickly creates a skeleton directory structure for an Express application. It saves time by setting up the necessary folders, configuration files, and dependencies, following standard industry practices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3345e787-8782-457b-97ea-79768d8f4729', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the ''CAP Theorem'' in the context of NoSQL?', N'Junior', N'The CAP Theorem states that a distributed database system can only provide two out of three guarantees simultaneously: Consistency, Availability, and Partition tolerance. Designers must choose which two are most critical for their specific application requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
