INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49bcc1fa-686e-44f0-84e3-7977c2c62e4b', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the trade-off of Svelte''s approach to reactivity regarding deep object mutations?', N'Middle', N'Svelte''s reactivity relies on assignments to trigger updates, so mutations to deep properties in an object may not be detected automatically. Developers must either use assignment to trigger an update or use immutable patterns to ensure the compiler notices the state change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5bcd3ab-30d8-4a08-839c-7979d89b56c4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the primary architectural benefit of using ''Value Objects'' in domain-driven Laravel projects?', N'Senior', N'Value objects encapsulate domain-specific logic and validation for primitive types, making the code more expressive and less prone to errors. They prevent the ''primitive obsession'' anti-pattern and ensure that business rules are enforced consistently throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53cc8592-6038-480c-8e91-797a48ec86b8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go scheduler handle blocking system calls?', N'Middle', N'When a goroutine makes a blocking system call, the Go runtime automatically detaches the underlying M (machine thread) from the P (processor) and attaches a new thread to that processor if there are other goroutines ready to run. This prevents a single blocking call from stalling all other goroutines assigned to that processor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
