INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd032bd5d-a225-4c27-8e68-798878e64fa1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the difference between hydration and resumability?', N'Fresher', N'Hydration is the process of attaching event listeners and rebuilding the state tree on the client after the server sends HTML. Resumability skips this entire process by serializing the state and event references, allowing the app to run immediately without a re-initialization phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
