INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02d28994-c268-4eba-98fc-799e0ffaa5b0', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is the lack of dependency injection in Hono considered a design choice?', N'Middle', N'Hono aims to remain as close to the metal as possible, favoring simplicity and speed over complex abstractions. By omitting a built-in dependency injection container, the framework remains unopinionated and allows developers to manage their own dependencies using patterns that best fit their project''s scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
