INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8984645-5277-41c6-b222-79aa5ca51202', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle multi-tenancy at the architectural level?', N'Senior', N'Multi-tenancy in NestJS is typically implemented using request-scoped providers or custom interceptors that extract tenant information from headers or JWTs. This context is then injected into services, enabling database connection switching or tenant-specific query filtering without duplicating business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecac72a7-bfb8-4180-ba78-79af5a997fcf', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the significance of ''Sendable'' in Swift concurrency.', N'Senior', N'Sendable is a marker protocol that indicates a type can be safely shared across concurrent execution boundaries without data races. The compiler enforces this by checking that the type is either immutable, a value type, or internally synchronized. This allows for compile-time verification of thread safety, significantly reducing the surface area for concurrency bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6682cc6-45e1-43bc-af8c-79b064015810', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of Preact''s small bundle size?', N'Junior', N'A smaller bundle size reduces the amount of JavaScript that needs to be downloaded, parsed, and executed by the browser. This leads to faster Time to Interactive and better overall performance on low-end hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd1b99f9-6c62-42fa-9eaf-79b142b7ed34', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why use indexes if they improve retrieval speed?', N'Fresher', N'While indexes speed up SELECT queries, they also consume additional disk space and can slow down data modification operations like INSERT, UPDATE, and DELETE. This is because the database must update the index whenever the data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6564889a-1d2c-48aa-a992-79b220bc67f7', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What challenges does Qwik pose regarding third-party library integration?', N'Senior', N'Third-party libraries often expect a traditional hydration lifecycle and may rely on global scope or immediate execution patterns. Integrating these requires wrappers or specific architectural patterns to ensure the external code can be lazily loaded and correctly re-initialized within Qwik''s resumable environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd11c3178-ef05-49ce-93b0-79b2fb49c04a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe the impact of large database transactions on the performance of a high-traffic Rails application.', N'Senior', N'Large transactions hold locks on database rows for extended periods, increasing contention and potentially leading to transaction timeouts or deadlocks. They also bloat the transaction log, which can delay replication and degrade overall database write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21c7f153-dc61-4ca8-8823-79b5e3a6eac2', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of the ''vite.config.js'' file?', N'Intern', N'The vite.config.js file is used to configure project-specific settings, such as plugins, build options, or server behavior. It allows developers to customize how Vite processes and builds their application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b05b4f4-72fe-4b24-b315-79b9fe7f5a65', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the C# Task Scheduler influence the execution of asynchronous continuations?', N'Senior', N'The Task Scheduler determines the policy for executing tasks, such as whether they run on the ThreadPool or the UI message loop. By default, it uses the ThreadPool to optimize for throughput, but developers must manage synchronization contexts carefully to prevent deadlocks or thread starvation in complex asynchronous pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'939d144d-1dbf-4617-a63a-79be44462497', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a cache and querying the database directly for a profile page?', N'Fresher', N'Querying the database directly ensures the user always sees the most current data, but it can be slow and resource-intensive under high traffic. Using a cache stores frequently accessed profile information in memory for rapid retrieval, significantly reducing database load. You should use a cache if the data does not change very frequently and user experience speed is a priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed9cde7d-8ac3-475c-a879-79c04d902ce6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Entity Framework Core?', N'Junior', N'Entity Framework Core is an Object-Relational Mapper that allows developers to interact with a database using C# objects. It translates LINQ queries into database-specific SQL, reducing the need for manual data access code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f18bcb05-9f7c-4da6-894b-79c1392fb34b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the dangers of ''Split-Brain'' scenarios in a distributed cluster?', N'Senior', N'Split-brain occurs when a network partition causes a cluster to divide into two or more independent groups, each believing it is the primary authority. This can lead to conflicting data writes and state corruption, which is typically mitigated using consensus algorithms like Raft or Paxos.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4c50652-f3ff-41f0-b469-79c169e36b93', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the Qwik optimizer?', N'Intern', N'The Qwik optimizer is a build-time tool that automatically breaks your code into smaller chunks. This allows the framework to download only the necessary parts of the application as needed, optimizing performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'251c4713-c750-4fc8-8a45-79c27b0288c3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to ensure data consistency in a distributed microservices architecture without relying on traditional XA transactions?', N'Senior', N'I would implement the Saga pattern, utilizing either choreography or orchestration to manage distributed transactions. This approach breaks the process into a series of local transactions with compensating actions to handle failures, ensuring eventual consistency across services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'053836f2-8890-499d-89b7-79c2e1acb979', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why would you use an Exception Filter in a NestJS application?', N'Middle', N'Exception filters allow you to catch unhandled exceptions and transform them into standardized, meaningful HTTP responses. They provide a centralized way to manage error handling across the entire application, ensuring consistent API error formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc2c9cf2-d85a-4102-ae2f-79c4f315fbd0', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit ensure fast page transitions?', N'Fresher', N'SvelteKit uses prefetching to load the JavaScript and data for a page before the user even clicks the link. By the time the user navigates, the necessary resources are already cached, making transitions feel instantaneous.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf16734f-de5e-42f4-ac2f-79c6ecbb557a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the Flux pattern and what are its benefits?', N'Intern', N'The Flux pattern is an architectural design Facebook introduced for managing state in React applications. It enforces a unidirectional data flow, making it easier to manage and debug application state. Today Flux is largely historical — it has been superseded by libraries it inspired, such as Redux, Zustand, and the built-in useReducer + Context combination — but its single-source-of-truth and unidirectional-flow ideas are still the foundation of those tools. - Core components: - Dispatcher: Single hub that manages actions and dispatches them to all registered stores. - Stores: Hold the state and business logic; act as change emitters that notify subscribed views. - Actions: Plain payloads of information sent from the application to the dispatcher.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05a38160-ce1f-4d0e-a8c4-79c7e8a90439', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''Store'' in Ember Data?', N'Fresher', N'The Store acts as the central repository for all data loaded from the server. It caches data to improve performance, ensuring that components do not need to make redundant network requests for the same information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd9be4d6-2352-438b-8d13-79c975f68185', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin improve error handling?', N'Junior', N'Gin allows you to attach errors to the context using the Error method, which can then be collected by custom middleware. This allows for centralized error logging or formatting, ensuring that all errors are handled consistently across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b158cee-12db-4d3c-bc46-79c9de5b83f2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the possible reasons for memory leaks?', N'Intern', N'Memory leaks can lead to poor performance, slow loading times and even crashes in web applications. Some of the common causes of memory leaks are listed below, 1. The execessive usage of global variables or omitting the var keyword in local scope. 2. Forgetting to clear the timers set up by setTimeout or setInterval. 3. Closures retain references to variables from their parent scope, which leads to variables might not garbage collected even they are no longer used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c04e9a55-ddff-4a2b-851e-79ca5a1c6ad9', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is a Svelte store subscription?', N'Intern', N'A subscription is a way for a component to listen for updates from a store. When the value inside the store changes, the component is notified so it can update its own state or view accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
