INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a41bf0c-e507-4ae7-9775-79ce287dad44', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS leverage the IoC container to facilitate architectural decoupling and testability, and why is this approach significant for enterprise-grade applications?', N'Senior', N'The IoC container acts as a centralized registry that manages object lifecycles and dependency resolution, allowing developers to inject abstractions rather than concrete implementations. This inversion of control minimizes tight coupling between services, enabling easier unit testing through dependency mocking and promoting a modular architecture that scales as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cae7ffcc-ccde-43ae-b449-79ce775f303a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What architectural risks arise from using ''innerHTML'' for dynamic content injection?', N'Senior', N'Using innerHTML without sanitization is a primary vector for XSS attacks, as it allows arbitrary scripts to be executed in the context of the document. Beyond security, it causes the browser to discard and recreate existing DOM nodes, which can lead to the loss of state, focus, and event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31927e68-3df5-48f4-9cc1-79cf5e7fcf8c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''GCHandleType.Pinned'' and ''GCHandleType.Normal''?', N'Senior', N'A pinned handle prevents the garbage collector from moving an object in memory, ensuring its physical address remains constant for native code access. A normal handle simply tracks the object for the garbage collector, preventing premature collection without affecting its ability to be relocated during compaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
