INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'300f664a-124c-4c0d-9e33-79d299ae6fb3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When should you consult a team member about a bug?', N'Fresher', N'You should consult a team member if you have spent a reasonable amount of time investigating without progress. It is better to seek a fresh perspective early than to remain stuck for hours on a difficult problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'663c7dc1-f6dc-4a9f-8556-79d42c66ee27', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the architectural implications of using Active Record callbacks for complex business logic?', N'Senior', N'Over-reliance on callbacks leads to hidden side effects and makes unit testing difficult because actions trigger unintended database modifications. It is generally better to move complex logic into Service Objects or Domain Models to ensure explicit execution flows and better maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4db1fd9e-d703-4143-93a7-79d57f3efa1e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What architectural patterns help keep Tailwind-based projects maintainable as they grow to enterprise scale?', N'Senior', N'Maintainability is achieved through strict adherence to a component-driven architecture where utility strings are encapsulated within reusable components. Additionally, maintaining a clear separation between global layout utilities and component-specific styles prevents the codebase from becoming an unmanageable mess of long class lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6de8aa11-b542-43b9-ac68-79d5f533c2a3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the trade-offs between Read Committed and Serializable isolation levels.', N'Middle', N'Read Committed prevents dirty reads by ensuring only committed data is visible, offering a balance between performance and consistency. Serializable is the highest level of isolation, preventing all phenomena like non-repeatable reads and phantom reads, but it significantly reduces concurrency by requiring stricter locking or validation mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b26a71-784b-49a4-b6fe-79d7313121ba', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle environment variables?', N'Junior', N'Nuxt uses a runtime configuration system where environment variables can be defined in the nuxt.config file or via .env files. These variables are then accessible throughout the application via a special runtime config object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b36a3e8-73bf-4e67-a1de-79d83e2cd600', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle asynchronous concurrency compared to traditional thread-based WSGI frameworks?', N'Senior', N'Litestar is built on an ASGI-first architecture, leveraging an event loop to handle non-blocking I/O operations efficiently. This allows the application to manage thousands of concurrent connections using a single process, avoiding the overhead of thread context switching common in legacy WSGI implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'730f91e4-bc35-428d-84b0-79dbb82b21c4', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the trade-offs of using Context API versus state management libraries like Redux.', N'Middle', N'Context API is built-in and ideal for low-frequency updates like theme or user authentication, but it can trigger unnecessary re-renders across consumers. Redux provides more robust debugging, middleware support, and fine-grained control over updates, making it better for complex, high-frequency state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b48da19-ac79-4b0c-b21b-79de4fc564fa', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket utilize Rust''s ownership model to improve memory safety in request processing?', N'Senior', N'Rocket leverages ownership to ensure that request bodies and state are handled safely without data races. By enforcing strict lifetime rules, the framework prevents common memory corruption issues, even when concurrent requests attempt to access shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98c5bf6d-8a15-4e10-b0e4-79df70a8a844', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What role do ''Layer''s play in the Axum architectural hierarchy?', N'Senior', N'Layers are essentially decorators for services that allow for the transformation of requests and responses. They are used to implement cross-cutting concerns like logging, compression, and CORS, enabling a clean separation of infrastructure logic from the application''s core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8d6d66f-3cc2-4e55-93c6-79df7108aab3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the useDispatch hook?', N'Intern', N'The useDispatch hook returns a reference to the dispatch function from the Redux store. It is used to dispatch actions from within a component to trigger state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'760f135f-f77b-403d-b037-79dfd2daa48a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain how Actix handles connection pooling for databases.', N'Middle', N'Actix typically integrates with connection pool libraries like r2d2 or deadpool, which are injected via the App data. By sharing the pool instance across handlers, the application can efficiently reuse database connections instead of opening a new one for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aa48a88-2441-4993-b923-79e23119982b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are Action Filters?', N'Fresher', N'Action Filters are attributes that allow you to execute code before or after a controller action method runs. They are commonly used for tasks like logging, authentication, or handling errors globally across multiple controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
