INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d96bee9-726c-468a-9625-79e4a9fb28b6', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the core philosophy behind Fastify?', N'Fresher', N'The core philosophy is to provide a framework that is extremely fast, highly extensible, and developer-friendly. It achieves this by focusing on low overhead and avoiding unnecessary abstractions that could slow down request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'617e0604-3d19-4ff8-8f6e-79e69e0549e5', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Compare Quarkus''s approach to horizontal scaling versus traditional monolithic frameworks.', N'Senior', N'Quarkus is optimized for ''scale-to-zero'' and fast horizontal scaling. Its low memory usage and instant startup allow the orchestrator to spin up new instances in response to traffic spikes in seconds, whereas traditional frameworks often require long warm-up periods and significant memory overhead per instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdb34bf7-5bab-470e-84ae-79e75788c698', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''ExecutionContext'' in C# asynchronous programming?', N'Senior', N'The ExecutionContext captures ambient data such as security identity, culture, and SynchronizationContext across asynchronous continuations. This ensures that environmental settings flow correctly from the calling thread to the task execution thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4b5080c-051f-4921-a40a-79e822be1d14', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s component architecture differ from React''s functional components?', N'Senior', N'While they look similar, Qwik components are inherently lazy-loaded and serialized. Unlike React components which are re-executed during reconciliation cycles, Qwik components are designed to be ''paused'' and ''resumed'' by the framework''s runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'983c2107-bfa3-4df9-84c2-79e93007b1b4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'A task you are assigned has ambiguous requirements. What is your first step?', N'Junior', N'My first step is to document the questions I have based on the current requirements to clarify the intended behavior. I would then schedule a brief sync with the product manager or stakeholder to ensure my understanding aligns with their expectations before starting any work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'096f9e3a-7ed5-434c-b115-79e96370d6fd', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''ExecutionContext'' in .NET, and why is it important for asynchronous programming?', N'Senior', N'ExecutionContext flows ambient data like user identity, culture, and asynchronous local storage across asynchronous boundaries. It ensures that security contexts and thread-local state remain consistent when code execution shifts between threads. Neglecting to flow the context can lead to subtle bugs in security-sensitive or multi-tenant applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea5792ac-a887-40f6-a952-79ea255f8d0b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does ''isolating the problem'' mean in a troubleshooting context?', N'Fresher', N'Isolating the problem means narrowing down the scope of an error to a specific component, module, or layer of the application. By ruling out working parts, you can focus your investigation on the exact area that is malfunctioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d5f8b53-aa8c-4a89-b5dc-79f12992205d', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the advantages of using ''tower-http'' with Axum?', N'Senior', N'Tower-http provides a collection of ready-to-use services and middleware specifically designed for HTTP applications, such as compression, tracing, and CORS. Using these components with Axum allows developers to benefit from a battle-tested ecosystem that integrates seamlessly with Axum''s Tower-based architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ea831fd-dc93-464f-a365-79f6aa730764', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of ''middleware'' in Nuxt, and when should it be used?', N'Middle', N'Middleware allows you to execute logic before a route is navigated, such as checking user authentication or logging. It is essential for protecting routes or enforcing application-wide logic before the page component is rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5541e71b-d57f-4f93-ae7b-79f77ea33508', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why might you use ''thread-loader'' in a project, and when is it ineffective?', N'Senior', N'Thread-loader offloads expensive loaders to a worker pool to parallelize build tasks and improve speed. It is ineffective for small projects or fast loaders, as the overhead of spawning worker processes and inter-process communication can make the build slower than a single-threaded execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47f6ce9a-fc15-41f4-93f0-79f80e4cf9d0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you prepare for a meeting where you need to present your problem-solving progress?', N'Intern', N'I prepare by organizing my notes, highlighting the key achievements, identifying any remaining blockers, and anticipating potential questions. Having a clear, concise summary of my status ensures that the meeting is productive and keeps all stakeholders informed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77b29cd9-2de0-4374-83be-79f8ec9a8a81', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of ''Denormalization'' in the context of NoSQL.', N'Middle', N'Unlike relational databases that rely on normalization to reduce redundancy, NoSQL databases often use denormalization to store related data together in a single record. This approach minimizes the need for expensive cross-collection joins, significantly improving read performance for complex data models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40284d2e-13a6-473c-a024-79f94637cf6d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is meant by ''Code Splitting'' in Next.js?', N'Junior', N'Code splitting is the automatic process where Next.js breaks your application into smaller JavaScript bundles based on the routes. This ensures that the user only downloads the code necessary for the current page, rather than the entire application at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a8941f3-64b8-4ece-ba6f-79fc03f215bf', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''defer'' statement in Go?', N'Intern', N'The defer statement delays the execution of a function until the surrounding function returns. It is commonly used for cleanup tasks like closing files or releasing resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf93d796-2063-4d95-9fb8-79fd8786dc27', N'075b8862-431c-4678-9767-f55359758a4a', N'What are key modifiers?', N'Intern', N'Vue supports key modifiers on v-on for handling keyboard events. Let''s take an example of keyup event with enter keycode. Remembering all the key codes is really difficult. It supports the full list of key codes aliases 1. .enter 2. .tab 3. .delete (captures both "Delete" and "Backspace" keys) 4. .esc 5. .space 6. .up 7. .down 8. .left 9. .right Now the above keyup code snippet can be written with aliases as follows, Note: The use of keyCode events is deprecated and may not be supported in new browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9046f426-dd15-4172-946c-79fdcabe7fb8', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an HTTP response in Actix-web?', N'Intern', N'An HTTP response is the object returned by a handler to the client. It contains status codes, headers, and the body content that informs the client about the result of their request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1310d8e-8ab2-43b6-b917-7a024ab36880', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the .env file in Laravel?', N'Intern', N'The .env file is used to store environment-specific configuration variables, such as database credentials, API keys, and application settings. By keeping these sensitive values separate from the codebase, Laravel ensures security and allows the same application to run differently in local, staging, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd940fe9e-4bba-44ea-b1e1-7a05c4ba5d16', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of Flask Blueprints in organizing a codebase, and when should you avoid using them?', N'Middle', N'Blueprints are used to organize an application into distinct components, allowing for modular routing, template management, and static file handling. They are ideal for separating logical domains, such as user management or payment processing, into independent, reusable units. However, they should be avoided for very small, single-file applications where the overhead of structure outweighs the benefits of modularity, as it can lead to unnecessary complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1313cbfb-2821-4423-bc39-7a06cd76f65d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a defer block?', N'Junior', N'A defer block is used to execute a set of statements just before the current scope is exited, regardless of how the scope was exited. It is commonly used for cleanup tasks like closing file handles or invalidating timers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e0ddabc-e055-4bc3-9b1d-7a076486825e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the ''Request'' and ''Response'' lifecycle work in AdonisJS?', N'Fresher', N'When a client sends a request, AdonisJS creates a context object containing the request and response helpers. The request object carries incoming data, while the response object provides methods to send data, status codes, or redirects back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bfc5016-dc44-44db-9fc3-7a09fa6c78f6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the primary architectural design pattern used in AdonisJS?', N'Intern', N'AdonisJS is heavily inspired by the Model-View-Controller (MVC) pattern. This pattern separates the application into three main components: the data layer (Model), the user interface layer (View), and the logic layer (Controller) that handles requests and responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afedc647-ab84-46af-b753-7a0b61856634', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between an inline function and a regular function?', N'Fresher', N'An inline function suggests that the compiler replace the function call with the actual function code to reduce overhead. Regular functions involve a jump to the function''s memory location, which incurs a small performance cost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2726b184-17ca-46bc-ba77-7a0c9e6a349d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between typeof and instanceof operator?', N'Fresher', N'The typeof operator checks if a value has type of primitive type which can be one of boolean, function, object, number, string, undefined, symbol, or bigint. Example: The instanceof is a binary operator, accepting an object and a constructor. It returns a boolean indicating whether or not the object has the given constructor in its prototype chain. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'329d910f-a60d-4bc5-af7b-7a10b00aab90', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the form element?', N'Junior', N'The form element acts as a container for user input fields and controls, such as text boxes or checkboxes. It defines the structure for collecting user data and determines how that data is submitted to a server for processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'855bc876-e8d1-4027-a0cf-7a14570ae6a0', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the significance of the ''module.noParse'' option?', N'Senior', N'The ''noParse'' option tells Webpack to skip parsing specific files for dependencies, which is useful for large, pre-compiled libraries that do not contain imports. Skipping these files improves build performance by reducing the amount of code the bundler must analyze for internal dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdff3873-1efc-4b0e-abc0-7a14aa688942', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug data consistency issues in a system using eventual consistency?', N'Senior', N'I audit the replication lag metrics and check for out-of-order message processing in the event stream. I would compare source-of-truth state with read-replica state at specific time intervals to identify if the issue is due to slow synchronization, message loss, or concurrency conflicts in the write path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af8d83b8-ef4a-442a-9a2a-7a15bc07f3eb', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS pseudo-elements differ from pseudo-classes?', N'Middle', N'Pseudo-classes, like hover or focus, target an element based on its specific state or user interaction. Pseudo-elements, like before or after, are used to style specific parts of an element or insert decorative content that does not exist in the HTML markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee735fd-fc7d-4e00-9a86-7a164ab65b5f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using compression to save storage and CPU usage?', N'Fresher', N'Compression saves disk space and reduces bandwidth usage during data transfer, which is efficient for storage-constrained environments. The trade-off is the additional CPU cycles required to compress and decompress the data every time it is accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd262770-8f2b-4515-8450-7a1aa5d5067b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you handle loops in Alpine.js?', N'Junior', N'Loops are handled using the x-for directive, which allows you to iterate over an array or object to generate multiple DOM elements. It must be applied to a template tag or an element that Alpine recognizes as the parent for the repeated items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f42321df-4375-4d78-833a-7a1b4475227c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the ''transient'' keyword used for?', N'Junior', N'The transient keyword is used in serialization to mark a variable so that it is not saved when the object is written to a byte stream. It is typically used for sensitive data or fields that can be recalculated at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1626211a-9c83-44d2-a1da-7a1ee928a326', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a PHP framework?', N'Intern', N'A PHP framework is a platform that provides a standard structure for developing web applications. It offers pre-built libraries and tools to simplify common tasks like database interaction and security, allowing developers to write more efficient and maintainable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d3ae089-8f2c-4307-95e5-7a1ff3b82ca2', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of ''lifespan'' events in FastAPI?', N'Junior', N'Lifespan events allow you to run code when the application starts up and when it shuts down. This is ideal for tasks like initializing database connections or cleaning up resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cdbd7e4-bd32-47dc-a11a-7a214c2ff4d5', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the concept of a circuit breaker pattern and how it improves system reliability.', N'Middle', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail, such as a timed-out remote service. By failing fast, it protects the system from cascading failures and allows the failing service time to recover. Once the service stabilizes, the breaker resets to allow traffic again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b18514aa-d871-48fe-ac4d-7a214c9d28e2', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a Sealead class?', N'Fresher', N'A sealed class is used to represent restricted class hierarchies where a value can have one of the types from a limited set. This is particularly useful in ''when'' expressions to ensure that all possible cases are covered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dae9bbd0-8778-48ea-a5da-7a21b98a99b8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is ACID compliance?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. It is a set of properties that guarantee database transactions are processed reliably, even in the event of errors or power failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'485f2ac2-afa7-4441-9787-7a2465325bcc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between middleware and guards in Litestar?', N'Junior', N'Middleware acts globally or on specific groups to process every request and response, such as logging or compression. Guards, on the other hand, are specifically used for authorization logic to determine if a user has permission to access a specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8376fed-9215-4692-8ddb-7a260d40be8c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When tasked with reducing infrastructure costs by 30%, what is your prioritization framework?', N'Senior', N'I prioritize identifying underutilized resources, such as over-provisioned instances and idle test environments, followed by evaluating Reserved Instances or Spot instances for fault-tolerant workloads. Finally, I analyze architectural inefficiencies like excessive data transfer or inefficient storage tiers to achieve long-term savings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17daebfb-1a37-44cb-9049-7a267f19c0ab', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle long-running tasks in a web-based architecture?', N'Senior', N'I offload long-running tasks to dedicated worker pools using a message queue to ensure the request-response thread is not blocked. This enables horizontal scaling of the worker tier independently of the API tier and provides built-in retries and durability if a task fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d5d49c2-44aa-4e46-87c9-7a28e6956142', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring manage transaction synchronization in a multi-threaded environment?', N'Senior', N'Spring uses ThreadLocal variables to bind the current transaction’s resources—such as the database connection—to the executing thread. This ensures that all components participating in the transaction within the same thread use the exact same transactional resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'088f6bc2-5213-4c56-a527-7a2c0e8281cb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are namespaces used for?', N'Intern', N'Namespaces are used to organize code into logical groupings and prevent naming conflicts between different parts of a large application. They act as a container for classes, interfaces, and other types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
