INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6088bf2-7bfc-4906-89fb-7a2ee88eda5e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask extensions and give an example?', N'Junior', N'Flask extensions are third-party packages that add functionality to the core framework, such as database support or form validation. An example is Flask-SQLAlchemy, which simplifies the process of interacting with databases using an ORM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84cdb0e8-59bc-4a5f-9344-7a30fd672904', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you achieve high availability in a database cluster during a regional failure?', N'Senior', N'High availability is achieved through multi-region replication and automated failover mechanisms. This requires a robust synchronization strategy, such as active-passive or multi-primary, and a global load balancer to redirect traffic to the healthy region once the failure is detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dbd6e46-9cb7-40a9-bbef-7a343e0a5060', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s hybrid rendering strategy differ from traditional Single Page Applications, and what are the performance implications?', N'Middle', N'SvelteKit utilizes universal rendering, where the initial page load is server-side rendered for faster time-to-content and improved SEO, while subsequent navigations are handled client-side via a router. This hybrid approach provides the performance benefits of a static site during the first visit while maintaining the snappy, app-like feel of a client-side bundle for future interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1228b297-a78f-470f-bd5f-7a34c94ae4d0', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the trade-offs of using Gin''s middleware chain versus implementing logic directly in a handler.', N'Senior', N'Middleware allows for cross-cutting concerns like logging, authentication, and error handling to be decoupled from business logic, promoting DRY principles. However, deep middleware chains can introduce overhead and make request flow debugging more complex, so logic should only be moved to middleware if it is truly reusable across multiple endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e602f1-073d-4f05-ac4d-7a35aed74ea7', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of the ''Astro.cookies'' API for handling session management in SSR mode?', N'Senior', N'The Astro.cookies API provides a standardized, server-side interface for reading and setting cookies directly within the page request lifecycle. It simplifies session management and authentication workflows by removing the need for manual header parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ebcb85-6308-4f9c-bbd9-7a35df007483', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of Declaration Merging, and in what architectural scenarios is it useful?', N'Senior', N'Declaration merging allows the compiler to combine multiple definitions of the same entity, such as interfaces or namespaces, into a single structure. It is particularly useful for augmenting third-party libraries or extending built-in global types without modifying the original source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b6578e0-1960-4362-895f-7a3714f4f0fa', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide if a piece of logic belongs in the frontend or the backend?', N'Fresher', N'Logic should reside in the frontend if it directly affects the user interface and needs to be fast and responsive. Logic should be in the backend if it involves sensitive data, complex calculations, or requires interaction with a database, as the backend is more secure and controlled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f234a4d-25f0-4356-bd3b-7a3b2029aaf1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose a push-based model over a pull-based model for service communication?', N'Senior', N'Push-based models are ideal for real-time applications where low-latency delivery of updates is critical, such as stock tickers or notification services. Pull-based models are generally more robust for load balancing and backpressure management, as the consumer controls the consumption rate based on its current processing capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8190088-381e-4001-9ab9-7a3c8f042a13', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is documentation important even if the code is ''self-explanatory''?', N'Fresher', N'Documentation explains the ''why'' behind design decisions, which isn''t always visible in the code itself. It serves as a guide for new team members and helps everyone understand the system architecture, business requirements, and intended behavior, reducing the time needed for onboarding and troubleshooting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a87702dc-6606-42a3-b1b6-7a3d40d27183', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'You realize you will miss your deadline for a task. What is the first thing you do?', N'Junior', N'I would inform my lead or project manager as soon as the delay becomes apparent, rather than waiting until the deadline passes. I would provide a brief explanation of the blocker, a revised estimate for completion, and propose potential ways to mitigate the impact, such as prioritizing core functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1196246c-c92d-4539-93a8-7a3de16aa7c3', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does the choice of serialization format (JSON vs. Protobuf) impact system scalability?', N'Senior', N'Protobuf is a binary format that is more compact and faster to serialize and deserialize compared to JSON. This results in lower network bandwidth usage and reduced CPU overhead, making it significantly more efficient for high-frequency inter-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be03d830-3e71-4b9e-a366-7a3fc96a3ac4', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is ''Build-time Configuration'' a critical security and performance feature in Quarkus?', N'Senior', N'By locking down configuration at build time, Quarkus reduces the attack surface and eliminates the need for runtime environment property parsing. This makes the application more predictable and allows the compiler to make optimizations based on fixed environment variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99c55f74-1117-4b4f-8262-7a44f28701a8', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between symbols and strings in Ruby?', N'Fresher', N'Strings are mutable objects that can be modified after creation, while symbols are immutable identifiers often used as keys or labels. Because symbols are immutable and unique, they are more memory-efficient when used repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
