INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0288ace3-2cdc-447e-b05c-7a4bdd031eac', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between GET and POST methods?', N'Intern', N'GET sends data as part of the URL, making it visible and limited in size, while POST sends data in the body of the HTTP request, which is more secure and supports larger data volumes. GET is typically used for fetching data, while POST is used for submitting sensitive or large amounts of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'908c52b0-c5ff-4898-9309-7a4d72551675', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How should you handle local storage or context propagation in a fiber-based environment?', N'Middle', N'Since fibers can be moved between threads, standard Thread Local Storage is often insufficient or dangerous. You must use a fiber-local storage mechanism that is correctly managed by the runtime to ensure state persists regardless of which thread the fiber is currently executing on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
