INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24a5eea7-5712-411c-bccd-7a5ce6b073d0', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it important to use ''url_for'' instead of hardcoding URLs in your templates and redirects?', N'Middle', N'Using ''url_for'' dynamically generates URLs based on the function name, which decouples the internal logic from the URL structure. If you change the URL path in the route definition, you do not need to update every link or redirect throughout the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41ebc9bc-eecd-4b45-88fc-7a5e82c22ad2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is meant by the term undefined behavior in C?', N'Middle', N'Undefined behavior describes scenarios where the C standard imposes no requirements on the program''s output or execution. It can lead to crashes, silent data corruption, or inconsistent results, as the compiler is free to assume these situations never occur and optimize accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
