INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94864270-3040-46a1-b7d0-7a675e8c83a6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''BodyParser'' handle different request content types?', N'Middle', N'The BodyParser middleware is configured to automatically detect the ''Content-Type'' header and parse the request body accordingly, supporting formats like JSON, form-data, and multipart files. By centralizing this in a middleware, the framework ensures that controllers receive a pre-parsed, sanitized object, removing the need for repetitive parsing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e6eb489-d09a-4dd5-b383-7a6be9dcd55b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is it dangerous to cache user-specific data in a shared distributed cache?', N'Middle', N'Caching user-specific data in a shared environment without strict isolation can lead to data leaks or security vulnerabilities. If proper key namespacing or encryption is not applied, one user might inadvertently access sensitive data belonging to another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d67d903-5a94-49e1-a855-7a6c9199691f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the ''CAP Theorem'' and how does it influence the design of distributed databases?', N'Senior', N'The CAP Theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, designers must choose between either aborting operations to maintain consistency or continuing to serve requests at the risk of returning stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4e33a70-c9e4-4292-8121-7a6cace82466', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between an Actix actor and a standard Rust struct?', N'Fresher', N'An Actix actor is a struct that implements the Actor trait, which allows it to manage its own lifecycle and process messages in a mailbox. A standard Rust struct is simply a data container, whereas an actor provides the infrastructure for concurrent message-based communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'851166b6-5ffe-4475-8445-7a6d96dcc485', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the trade-offs of using Svelte''s stores versus React''s Context API for global state management?', N'Senior', N'Svelte stores are simple observable objects that exist outside the component tree, providing a lightweight, subscription-based pattern that is decoupled from component lifecycle. Unlike React''s Context API, which can trigger re-renders across the entire provider tree, stores allow for granular updates and can be easily accessed outside of components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b64906b7-72bc-40ad-a1aa-7a70c59b91d6', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you implement shared configuration across a NestJS application?', N'Middle', N'The ConfigModule is the standard way to manage environment variables and application settings. It allows for a centralized approach to loading and validating configuration files, ensuring that the application remains portable across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4154e91a-859c-4e89-9080-7a7293e8deb4', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a database view, and when is it appropriate to use one?', N'Middle', N'A view is a virtual table representing the result of a stored query, allowing users to interact with complex data structures simply. They are useful for abstracting complexity, enforcing security by limiting access to specific columns, and providing a consistent interface for legacy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4138628-f2d2-4fee-b60f-7a73ab486abf', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle HTTP requests compared to traditional frameworks like Express?', N'Intern', N'Hono uses the standard Request and Response objects defined by the Fetch API instead of the legacy Node.js-specific request and response objects. This makes it more compatible with modern web standards and serverless architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8367073-544a-4169-90c7-7a783f4c35df', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS maintain security against CSRF attacks?', N'Middle', N'AdonisJS includes built-in CSRF protection that validates a unique token for every state-changing request. By enforcing this check on all non-GET requests, it ensures that requests are coming from a trusted source, preventing unauthorized actions on behalf of the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708ff039-e3a2-4ac0-884a-7a7a2f25697b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is meant by ''mounting'' a middleware or router?', N'Fresher', N'Mounting refers to attaching middleware or a router to a specific path prefix in the application. When a request matches that path prefix, the mounted middleware or router will be executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f3356ee-6316-4fc4-bcbe-7a7b035a4187', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s signal-based state management differ from standard hooks in terms of re-rendering performance?', N'Senior', N'Signals allow Preact to achieve fine-grained reactivity by subscribing components directly to specific data slices rather than re-rendering the entire component tree on state changes. This bypasses the virtual DOM diffing process for those specific nodes, drastically reducing CPU usage in data-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4905c1ab-f0a8-4f4e-8e04-7a7b70f60c4d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is normalization used in databases?', N'Fresher', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b8e0fb2-91ea-4710-a136-7a7cec457a34', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the ''Token Ring'' determine data placement?', N'Middle', N'The Token Ring assigns a range of hash values to each node, creating a logical circle of responsibility. When data is written, the partition key is hashed to a specific token, and the data is stored on the node that owns the corresponding range in the ring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d10e89-f502-4deb-bfe5-7a824fc35cd8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the challenges of performing cross-shard transactions in a distributed database?', N'Senior', N'Cross-shard transactions require complex protocols like two-phase commit (2PC) or Paxos, which introduce significant latency and decrease system throughput. These protocols also increase the risk of deadlocks and can stall operations if a participant node becomes unresponsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
