INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57d6443e-e552-458e-8f34-7a85562cf22f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the trade-offs of using Qwik''s ''Global State'' versus standard React Context?', N'Senior', N'Qwik''s global state is designed to be persistent and serializable across the server-client boundary, allowing for seamless state restoration. Unlike React Context, which is bound to the component tree and often requires re-renders upon hydration, Qwik''s state is decoupled from the DOM and persisted in a way that survives the transition to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
