INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b840a6-d81f-4cb0-a778-7a97d553872d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''slot'' element in Web Components?', N'Senior', N'The slot element acts as a placeholder for external content to be injected into a shadow DOM tree, enabling flexible component composition. It allows developers to create reusable layouts where the internal structure is fixed, but the specific content nodes are provided by the parent component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cc0f04d-5a7f-4bcf-b63d-7a991fbb5e55', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between an ''alias'' in Vite versus a standard module path?', N'Middle', N'Aliases provide a shorthand for deep directory paths, making imports cleaner and more maintainable. Unlike standard paths, they allow the build tool to resolve to a consistent location regardless of the current file''s depth in the directory tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7728ad51-a28e-4749-9b52-7aa450d804cc', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it important to place error-handling middleware at the end of the middleware stack?', N'Fresher', N'Middleware is executed sequentially in the order it is defined. If an error occurs in any of the preceding routes or middleware, the error-handling middleware needs to be defined after them so it can catch and handle the error properly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf10266c-93ba-4c20-886b-7aa65fb462a6', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does message acknowledgement affect system performance?', N'Middle', N'Frequent or synchronous acknowledgements ensure high reliability but introduce latency and overhead because the broker must wait for confirmation before considering a message processed. Batching acknowledgements can improve performance but increases the risk of reprocessing messages if a failure occurs before the batch is confirmed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f9d80df-9992-4cc8-807f-7aa8911639b5', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you sync current route in vuex store?', N'Fresher', N'You can use vue-router-sync library to sync current $route object in vuex store''s state. The usage is quite straight forward with two steps', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c842db6-452a-4681-a065-7aa9754d84db', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the Scala compiler handle ''Type Erasure'' regarding generic types?', N'Senior', N'Like Java, Scala erases generic type parameters at runtime to maintain backward compatibility with the JVM. To circumvent this, Scala uses ''TypeTags'' or ''ClassTags'', which carry type information through implicit evidence, allowing for runtime reflection and pattern matching on generic types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2892c5ef-5d9f-4d48-93f4-7aa9de5f099c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does ''serialization'' refer to in Qwik?', N'Junior', N'Serialization is the process of converting the application''s complex state objects into a string format that can be embedded in the HTML. This allows the client to reconstruct the exact state the server had without re-running initialization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58ec4fa4-b4e9-4f1d-85c2-7aab6624bb72', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a closure memory leak and how do you prevent it?', N'Fresher', N'A closure memory leak occurs when a closure unintentionally keeps a large object (such as a DOM node, a large dataset, or a complete HTTP response) in memory by holding a reference in its closed-over scope long after the object is needed. The V8 garbage collector cannot reclaim the memory because the closure is still reachable. Common patterns that cause leaks: 1. Event listeners not removed — the listener closes over component state, keeping the entire component tree alive. 2. Timers not cleared — setInterval callbacks closing over large objects run indefinitely. 3. Detached DOM nodes — a closure holds a reference to a DOM node that has been removed from the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5307bcd5-29c0-45ed-a840-7aacf205d5e7', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle JSON data binding?', N'Intern', N'Echo provides binding features to automatically map incoming request payloads, such as JSON bodies, into Go structs. This simplifies the process of extracting and validating user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a4a3fa4-b43e-4331-951a-7aad046c203e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Describe the trade-offs between using a monorepo with Vite compared to a single-repo structure.', N'Senior', N'Monorepos allow for better code reuse across packages but introduce complexity in build orchestration and dependency resolution. Vite manages this well via workspace support, though developers must be careful with hoisting issues and cache invalidation across package boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbbfc951-6bca-4e1c-b22c-7aad1eee2362', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between vertical and horizontal partitioning of a database?', N'Middle', N'Vertical partitioning splits a table by columns to isolate frequently accessed fields, while horizontal partitioning splits a table by rows to distribute data across multiple nodes. Vertical partitioning is often used to optimize query performance for wide tables, whereas horizontal partitioning is used to overcome storage and throughput limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6033380-1e04-4327-9275-7aae67001359', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are Qwik ''symbols'' and why are they important?', N'Middle', N'Symbols are references to code chunks that are stored in the HTML. They allow Qwik to identify and lazy-load specific functions or components only when they are needed, enabling the framework to remain interactive without loading the entire bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef367f8e-10f7-46a5-baa6-7aae91927a88', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle error pages?', N'Intern', N'Nuxt provides a built-in error page mechanism that automatically catches errors during rendering or routing. You can customize the error page by creating a specific file in the project to provide a user-friendly interface when something goes wrong.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0e3db08-a8c8-442a-b7b2-7aaed47967f0', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is ''Scope Hoisting'' in Webpack?', N'Middle', N'Scope hoisting is an optimization where Webpack flattens the module tree by concatenating the scope of all modules into a single closure. This reduces the overhead of function wrappers for each module, resulting in faster execution and smaller bundle sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be3585e3-2bef-49a6-8719-7ab3ab22a6a7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of the ''Write-Ahead Logging'' (WAL) mechanism?', N'Middle', N'WAL ensures durability by recording all changes to a log file on stable storage before applying them to the actual data files. If the system crashes, the database can replay the log to restore the data to its last consistent state, fulfilling the Durability requirement of ACID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'615c03f8-c1e1-49e6-9123-7ab4b6dd809d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When is it appropriate to favor technical debt over a perfect solution?', N'Fresher', N'It is appropriate when the business needs to meet a critical market deadline or validate a hypothesis quickly. The trade-off is accepting the burden of fixing the debt later in exchange for immediate strategic gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e03a67c-4835-4ce2-a0ac-7ab8ea05fd13', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is deadlocking in a database and how is it usually resolved?', N'Middle', N'A deadlock occurs when two or more transactions hold locks that the others need, preventing any from proceeding. Databases typically resolve this by using a deadlock detector to automatically kill one of the transactions, allowing the others to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc0afddf-8090-448d-b2cc-7abb640c5049', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of ngFor trackBy?', N'Intern', N'The main purpose of using *ngFor with trackBy option is performance optimization. Normally if you use NgFor with large data sets, a small change to one item by removing or adding an item, can trigger a cascade of DOM manipulations. In this case, Angular sees only a fresh list of new object references and to replace the old DOM elements with all new DOM elements. You can help Angular to track which items added or removed by providing a trackBy function which takes the index and the current item as arguments and needs to return the unique identifier for this item. For example, lets set trackBy to the trackByTodos() method and define the trackByTodos method,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de034bc7-8677-4bee-9fd8-7abb6cc5064a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the significance of the virtual DOM implementation in Preact regarding memory usage.', N'Middle', N'Preact''s virtual DOM is designed to be highly memory-efficient by representing the UI tree using plain objects with minimal overhead. It avoids the heavy object structure used in React, which results in less garbage collection pressure and faster initial rendering times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b75c6d2e-4ff8-4667-83c0-7abbd1e5050c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you access web storage', N'Fresher', N'The Window object implements the WindowLocalStorage and WindowSessionStorage objects which has localStorage(window.localStorage) and sessionStorage(window.sessionStorage) properties respectively. These properties create an instance of the Storage object, through which data items can be set, retrieved and removed for a specific domain and storage type (session or local). For example, you can read and write on local storage objects as below', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84eecab9-619c-44b1-ad20-7abe3d9883ed', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is the order of loaders significant in Webpack, and how does the ''enforce'' property influence execution flow?', N'Senior', N'Loaders execute in reverse order (right-to-left or bottom-to-top) to allow for functional composition. The ''enforce'' property allows developers to override this flow by categorizing loaders into pre, normal, inline, and post, ensuring that critical tasks like linting run before transpilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd5c3710-2ec9-4204-8e4a-7abea86f0543', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a pointer and a reference?', N'Intern', N'A pointer is a variable that stores the memory address of another variable and can be reassigned to point to different locations. A reference is an alias for an existing variable and must be initialized upon declaration, after which it cannot be changed to refer to another object. Unlike pointers, references cannot be null.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fad918a-c313-42cd-9df2-7abfd513a545', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the benefit of using Rocket''s ''FromData'' trait?', N'Junior', N'The FromData trait allows you to define custom logic for parsing incoming request bodies into your own types. It gives you full control over how data is extracted from the request stream, such as performing custom validation or transformation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c99e7ee-3905-46b4-a8fc-7ac258d9c578', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the limitations of ''Scoped Slots'' regarding performance and parent-child coupling?', N'Senior', N'Scoped slots allow children to pass data back to the parent''s template, which creates a tighter coupling between the two components. While powerful, heavily utilizing scoped slots can lead to complex template logic that is difficult to debug and may cause unnecessary re-renders if the slot content is not properly optimized with memoization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b66444a3-e133-4647-82d8-7ac3c0f176af', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is file-based routing in Nuxt?', N'Intern', N'File-based routing means the application''s routes are automatically generated based on the directory structure of the pages folder. You do not need to manually configure a router file because adding a file to the pages directory creates a corresponding URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e275ca5c-3196-4e7c-b79e-7ac7db9566e5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How can you use user feedback to improve the troubleshooting process?', N'Fresher', N'User feedback often provides the ''missing link'' regarding how the application is used in real-world scenarios. Analyzing this feedback helps you create more accurate test cases and identify user behavior patterns that lead to errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ff2b812-ee56-4e0f-81d5-7ac8a598e30a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How can you optimize Tailwind CSS for long-term scalability in a system with thousands of components?', N'Senior', N'Scalability is achieved by strictly enforcing the design system through the Tailwind configuration file rather than allowing arbitrary values. By treating the config as a single source of truth and using component-based frameworks like React or Vue, you can encapsulate Tailwind utilities into reusable components, reducing the overall complexity of class management in the long term.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9decb6eb-cdad-4b91-87bf-7acaf6f22825', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the common use cases for a key-value store?', N'Intern', N'Key-value stores are ideal for caching, shopping carts in e-commerce, user session management, and real-time bidding systems. They excel in scenarios where simple, rapid data retrieval is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13d3be36-1491-48df-b4cf-7acb3430e4b4', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the Isolation property achieve?', N'Intern', N'Isolation ensures that the intermediate state of a transaction is invisible to other concurrent transactions. It prevents multiple transactions from interfering with each other, making them appear as if they are executing sequentially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab210de2-877e-486e-a8ff-7ace7e8a0b8c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can Tailwind CSS be used alongside standard CSS files?', N'Junior', N'Yes, Tailwind is fully compatible with standard CSS. You can include your own custom CSS files in your project and use them alongside Tailwind utility classes without conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56b866f5-caa7-4bd7-a562-7ad33a9e1d4c', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit''s ''actions'' facilitate clean separation of concerns?', N'Senior', N'Actions move mutation logic out of the component and onto the server, keeping the component focused on presentation. This ensures that business logic remains server-side, reducing the client-side bundle size and simplifying security audits by centralizing data modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
