INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2807c05-a8fb-45f6-91db-7adda2838eee', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core implement distributed caching, and what are the architectural trade-offs compared to in-memory caching?', N'Senior', N'Distributed caching uses an external store like Redis or SQL Server to share data across multiple server instances, ensuring consistency in scaled environments. While it introduces network latency compared to local in-memory caching, it is essential for horizontal scalability and maintaining state across stateless web nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
