INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa2dfbf3-1168-478f-bdcb-7b12dc7284e1', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between an API and Web route file?', N'Junior', N'The web routes file is loaded with session state, CSRF protection, and cookie encryption middleware, making it suitable for standard browser-based applications. The API routes file is stateless and typically uses token-based authentication, making it ideal for mobile apps or SPA backends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b85306cb-b4b7-4bd4-9ab4-7b13ad307aac', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What does ''dynamic schema'' mean?', N'Intern', N'A dynamic schema means that documents in the same collection do not need to have the same set of fields or structure. This flexibility allows for rapid iteration and evolution of the data model over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba6ee368-2ff4-4ca1-9798-7b166ee74129', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Scope'' in Actix-web routing?', N'Fresher', N'A scope is a way to group routes under a common path prefix. This helps in organizing large applications by allowing developers to define sub-routers for specific parts of the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6893999-4ac3-45d9-9f09-7b181581447f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the advantage of using Chi’s ''RouteCtx''?', N'Middle', N'RouteCtx allows for efficient retrieval of routing information during the request lifecycle. By accessing this context, developers can programmatically determine the pattern that matched the request, which is helpful for dynamic logging or metrics collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1b221d0-bda6-411c-acba-7b21a666609c', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is AJAX in the context of jQuery?', N'Intern', N'AJAX stands for Asynchronous JavaScript and XML, and in jQuery, it refers to methods used to fetch data from a server without reloading the entire web page. jQuery simplifies AJAX requests by providing a clean, unified interface for standard XHR operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3039e589-a7da-4737-bf62-7b21af2a1a62', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the role of the Symfony EventDispatcher in maintaining a decoupled architecture.', N'Senior', N'The EventDispatcher acts as a central mediator, allowing components to communicate without direct knowledge of each other. By emitting and listening to events, developers can inject custom logic into the framework''s lifecycle or business flows without modifying the underlying core code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e827b378-5e0d-4b3e-a0f5-7b2241e0ffc1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the significance of the ''Saga'' pattern in microservices transactions.', N'Senior', N'A Saga is a sequence of local transactions where each step updates the database and publishes a message to trigger the next step. If a step fails, the Saga executes compensating transactions to undo the changes made by preceding steps, maintaining eventual consistency without distributed locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13a67c6c-851f-4d1f-a8c6-7b22a29c768c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you communicate the risk of ''scope creep'' to a stakeholder during the development phase?', N'Junior', N'I explain that adding new requirements after development has started will impact the existing timeline and budget. I suggest documenting the new ideas for a follow-up phase so we can stay focused on delivering the current scope on time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7bdeaea-0c17-4172-bdef-7b22eff76962', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Discuss the implications of using Gin’s Bind method for JSON parsing versus manual decoding.', N'Senior', N'Gin’s Bind method automates the process of reading the request body and validating the structure based on tags. While convenient, it abstracts the error handling and validation logic; for high-performance requirements, manual decoding might be preferred to implement specific caching strategies or custom validation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3000454e-d30e-489c-abff-7b23a66debf7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the purpose of a ''sanity check'' in engineering?', N'Intern', N'A sanity check is a quick, informal test to ensure that the logic of a solution is fundamentally sound before investing significant time. It verifies that the input and output expectations are logical and that no basic constraints have been violated. It serves as a safety mechanism to catch obvious errors early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8947e98f-46fd-4b25-b617-7b250a1f3ced', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro manage asset optimization and bundling for static resources?', N'Senior', N'Astro uses Vite under the hood to process, minify, and hash assets like CSS, images, and fonts. It automatically optimizes these assets at build time, ensuring that only the files required by the current page are included, which minimizes unnecessary network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75569140-3c03-43e7-9302-7b272ba2d549', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage asynchronous execution compared to standard thread-per-request models?', N'Senior', N'Rocket leverages Rust''s asynchronous runtime to handle I/O-bound tasks without blocking OS threads. This approach allows a single thread to multiplex thousands of concurrent requests, significantly reducing memory consumption and context-switching overhead under high load compared to traditional synchronous models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52c9347e-7541-4abe-b0d2-7b2a22e9f0be', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of Route Model Binding?', N'Junior', N'Route Model Binding automatically injects model instances directly into your routes based on the ID present in the URI. This eliminates the need to manually query the database for a record by its ID inside your controller methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa81e047-2db1-4e3c-976e-7b2a93774994', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the significance of the Unsafe keyword in Rust, and does it disable the borrow checker?', N'Senior', N'The Unsafe keyword does not disable the borrow checker, but it signals to the compiler that the programmer is taking responsibility for upholding safety invariants that the compiler cannot verify. It allows for operations like dereferencing raw pointers or calling FFI, shifting the burden of memory safety from the compiler to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
