INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7057f301-8655-4588-83c8-7b3c069db6b8', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a shard?', N'Intern', N'A shard is a single instance of a Lucene index, which is a low-level worker unit that holds a subset of the data in an index. Sharding allows Elasticsearch to distribute data across multiple nodes in a cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
