INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af23ca14-4a6a-412a-add8-7b3f379f05f3', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Hot Module Replacement (HMR) function under the hood in Vite?', N'Middle', N'Vite establishes a WebSocket connection between the server and the browser. When a file is edited, the server sends a message to the client, which then fetches the updated module and hot-swaps it, maintaining the application state without a full page reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
