INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86883742-d31d-430e-95c9-7b43126940e6', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Discuss the impact of using pointers versus values in Go struct slices.', N'Senior', N'Using value types in slices improves cache locality as elements are stored contiguously in memory, reducing pointer dereferencing and garbage collector scanning. Pointers are useful when the objects are large or need to be shared, but they introduce indirection and increase the pressure on the GC.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0237cea7-cadf-48c9-92dd-7b436f18b491', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does it mean for TypeScript to be ''statically typed''?', N'Intern', N'Being statically typed means that the types of variables and expressions are checked during compilation rather than at runtime. This allows developers to catch type-related errors before the application is deployed or run by the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
