INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec63bba-9e81-4c2b-ae0e-7b470aeac878', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the trade-offs of using Fastify''s built-in hooks versus global middleware?', N'Middle', N'Hooks are scoped to the plugin level, providing granular control over where specific logic executes in the request lifecycle. Global middleware often applies to every route indiscriminately, making hooks more efficient and easier to manage for complex, modular applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
