INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40aa07f0-a4b0-4c68-93b1-7b4b9c0cbdf4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''hot partition'' and how can it be mitigated?', N'Middle', N'A hot partition occurs when a specific shard receives a disproportionately high volume of traffic compared to others, leading to performance bottlenecks. It can be mitigated by choosing a better shard key that distributes data more uniformly across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3460c6c-a5ae-45b3-b9ea-7b4c146ba4db', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Can you explain why you would use a ''loading.js'' file?', N'Middle', N'The ''loading.js'' file leverages React Suspense to automatically show a loading skeleton or spinner while a route segment is rendering. It simplifies the implementation of loading states by creating a clear boundary between the shell of the page and the asynchronous content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
