INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c67d6567-1ebb-480b-b50c-7b5ac0dea5ac', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'In what scenarios would you choose Astro over a traditional SPA architecture?', N'Senior', N'Astro is ideal for sites where SEO, initial load performance, and content management are priorities, such as blogs, documentation, and e-commerce sites. SPAs are generally better suited for highly interactive, authenticated dashboards where the initial load delay is an acceptable trade-off for seamless transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0632e5e6-a006-4970-8029-7b5c665e721a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does ''Content Security Policy'' (CSP) delivered via HTML meta tags restrict resource loading?', N'Senior', N'CSP defines an allow-list of trusted domains for scripts, styles, and other assets, effectively preventing Cross-Site Scripting (XSS) and data injection. Using meta tags to enforce these policies adds an extra layer of defense, though header-based implementation is generally preferred for broader browser support and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e36badf-461e-401e-8cb1-7b5cb3e8a8f1', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the difference between throughput and latency in system performance.', N'Senior', N'Latency is the time taken to process a single request, while throughput is the number of requests processed per unit of time. Architectural designs often require balancing these, as techniques to increase throughput, such as batching, can sometimes increase the latency of individual requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eefbbfb7-5a25-4e11-811e-7b60e0dcf53a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why might you use a function pointer in C?', N'Middle', N'Function pointers enable polymorphism and callback mechanisms, allowing a program to execute different functions based on runtime conditions. They are essential for implementing generic algorithms, event-driven architectures, and plugin-based system designs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7a9f719-0044-408e-9175-7b6166d30c53', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between an API route and a Page endpoint?', N'Middle', N'API routes are designed to return data, usually in JSON format, for use by other services or client-side fetches. Page endpoints are tied to the UI rendering lifecycle and are primarily used to supply data specifically to the associated page component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b676e0bc-df3e-42f4-bb61-7b6214ed5c30', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to implement a sleep function in Node.js?', N'Fresher', N'Node.js has no built-in sleep() — but you can implement one using a Promise + setTimeout combination with async/await. Example: The function returns a Promise that resolves after ms milliseconds. await-ing it pauses execution without blocking the event loop. > In Node.js v16+, timers/promises provides a built-in alternative: import { setTimeout as sleep } from ''timers/promises''; await sleep(1000);', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb365380-17c5-4fbd-9ac0-7b62482ff677', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the Isolation property work in transactions?', N'Junior', N'Isolation ensures that concurrent transactions do not interfere with each other. It makes it appear as if each transaction is executing in complete seclusion, preventing intermediate states from being visible to others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea2a532a-9c41-4712-8b08-7b62ec50eabc', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis ''Hash'' and when should you use it?', N'Junior', N'A Redis Hash is a map between string fields and string values, making it perfect for representing objects like a user profile. It allows you to store multiple related fields under a single key, which is more memory-efficient than storing each field as a separate key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f716fab5-d5fe-4604-8b42-7b62fd819ac2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between a Hono app and a standard Node.js Express app?', N'Intern', N'While both handle HTTP requests, Hono is designed for the modern web standards of the Edge and is significantly lighter. Express is built specifically for the Node.js runtime and relies on legacy modules, whereas Hono is platform-independent and focuses on performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f92e96-1fc8-4250-81fc-7b63d03dae5b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the role of the Lucene ''segment'' in Elasticsearch.', N'Senior', N'A segment is an immutable, self-contained index file within a shard that holds a subset of the document data. Because segments are immutable, Elasticsearch performs updates by creating new segments and marking old documents as deleted, relying on merging to physically remove the deleted documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd396a364-89c7-4fd2-b598-7b640648b241', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the primary disadvantages of using long-running transactions?', N'Middle', N'Long-running transactions hold locks for extended periods, which can lead to resource starvation and increased blocking for other transactions. They also keep the undo logs or transaction logs from being truncated, potentially causing disk space issues and slowing down crash recovery processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6749c590-4b02-4045-8fac-7b64b725be6d', N'a2838158-7305-480a-b22b-4dc35776b400', N'Describe the concept of ''Gossip Protocols'' and their use case.', N'Senior', N'Gossip protocols are peer-to-peer communication methods where nodes periodically exchange information with a subset of other nodes. They are highly resilient and scalable, making them ideal for failure detection and cluster membership management in large-scale distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a036f9cd-b14f-4ab9-9b68-7b656ac86ea6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What factors do you consider when deciding whether to cache data at the application layer versus the database layer?', N'Middle', N'Application-level caching is better for frequently accessed, read-heavy data that doesn''t change often, as it reduces network overhead. Database-level caching is more appropriate for complex query results or when you need centralized cache management to ensure data consistency across multiple service instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d200be5-6257-4373-b849-7b6584465d15', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary difference between an interface and a type alias in TypeScript?', N'Junior', N'Interfaces are primarily used to define the shapes of objects and can be merged through declaration merging if defined multiple times with the same name. Type aliases are more flexible, as they can represent primitives, unions, and tuples, but they cannot be re-opened to add new properties once defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97ed035d-74ce-470c-88b9-7b68ae90238d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach security in a zero-trust architecture?', N'Senior', N'I implement identity-based access control where every service request is authenticated and authorized regardless of its origin. This involves using short-lived tokens, mutual TLS, and strict least-privilege policies to ensure that compromised services cannot gain lateral access to other parts of the network.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ba1f332-127f-48e0-9da4-7b69a1e32139', N'075b8862-431c-4678-9767-f55359758a4a', N'What is hot reloading in vue loader?', N'Intern', N'Hot reloading is not about reloading the page when you edit any .vue file. Instead, when you edit a *.vue file, all instances of that component will be swapped in without reloading the page. It improves the development experience when you are tweaking the templates or styling of your components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d063435-afcf-425a-bd5e-7b6ae11411de', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do you optimize bundle size when using large third-party libraries?', N'Middle', N'You can optimize bundle size by using tree-shaking, code-splitting via dynamic imports, or specifying external dependencies. Additionally, using specific import paths or plugins that strip unused components of a library can further reduce the total footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4681083-b71b-47b4-bc93-7b73b7b3134f', N'954a0331-deff-4399-b588-96f39fec001d', N'What happens if you include a <script> tag inside a template?', N'Junior', N'If you include a tag directly within an Angular component''s template (.html file), Angular''s built-in security mechanisms, specifically sanitization, will prevent it from executing. Angular treats the template content as untrusted HTML by default. During the rendering process, the sanitization pipeline will detect the tag and either remove it entirely or neutralize it, ensuring that the code inside the script does not run in the user''s browser. This is a crucial security feature designed to protect your application from Cross-Site Scripting (XSS) attacks. You should implement dynamic behavior using Angular''s event binding and component logic instead of inline scripts. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd4b770a-1395-4485-b3ae-7b73f65951a6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the +layout.js file?', N'Intern', N'The +layout.js file is used to load data that is shared across all pages within that layout''s hierarchy. It ensures that common data is available to all child components without needing to refetch it on every page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'310f74fc-000b-463f-9737-7b74437e3a8a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the primary use case for thread-local storage in high-concurrency C++ applications?', N'Senior', N'Thread-local storage provides each thread with its own unique instance of a variable, eliminating the need for synchronization primitives like mutexes when accessing global or static data. This significantly reduces contention and improves performance in multi-threaded environments, though it must be used carefully to avoid excessive memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db1eb3c3-bf8e-4df1-82ca-7b75b34add51', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the trade-offs of using closures in JavaScript?', N'Middle', N'Closures allow for data encapsulation and the creation of private variables that persist across function calls. However, excessive use can lead to memory leaks if variables are held in memory longer than necessary, as the garbage collector cannot reclaim objects referenced by the closure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a412b223-f93f-4fe7-b5a8-7b7a50216020', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''void'' and ''never'' return types?', N'Fresher', N'The ''void'' return type indicates that a function does not return any value. The ''never'' type indicates that a function will never return, such as a function that always throws an error or enters an infinite loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9b458bc-26af-4d55-a25b-7b7d11c182e3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the SynchronizationContext in asynchronous programming, and why is it often avoided in modern ASP.NET Core?', N'Senior', N'SynchronizationContext controls the execution environment of asynchronous tasks, often used to marshal work back to a specific thread. ASP.NET Core is designed to be synchronization-context-free, which improves performance and avoids potential deadlocks common in older framework versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce4e1e56-a8ec-4f52-aaa2-7b8221a69517', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is the use of ''DTOs'' (Data Transfer Objects) in Litestar recommended for large-scale microservices?', N'Senior', N'DTOs decouple the internal data models used by the database from the public-facing API schemas. This allows developers to evolve the database schema without breaking the API contract, providing a necessary layer of abstraction for long-term maintenance and versioning in microservice architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3d56dfc-65a1-4c9e-9e7d-7b8485ffb1c1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is an initializer?', N'Intern', N'An initializer is a special method used to prepare an instance of a class, structure, or enumeration for use. This involves setting an initial value for each stored property and performing any other setup required before the instance is ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29838a20-5a9f-4fd1-bc72-7b8499cfebab', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''server'' directory used for?', N'Intern', N'The server directory is used to define server-side API endpoints and middleware. It allows you to write backend logic directly within your Nuxt project, making it a full-stack framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65341897-d06c-48fa-8179-7b84cad09b99', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is Fiber in the context of Go web frameworks?', N'Junior', N'Fiber is a web framework built on top of Fasthttp, which is designed to be extremely fast and memory-efficient. It provides a familiar Express.js-like API for Go developers to build scalable web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5785e0cf-d7f2-4a0d-a2ec-7b8685cea3cd', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the order of fields in a compound index impact its effectiveness?', N'Middle', N'The order of fields follows the ''ESR'' (Equality, Sort, Range) rule, where equality fields should come first, followed by sort fields, and finally range fields. Incorrect ordering can prevent the index from being used effectively for sorting, forcing the database to perform an in-memory sort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9469592b-99ca-4a59-b416-7b86f3c86bc7', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a bug that is intermittent or ''flaky''?', N'Intern', N'Intermittent bugs require careful data collection over time to look for patterns, such as the time of day or specific load conditions. I would focus on monitoring the environment continuously to catch the issue when it finally occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71ca1e0f-a1f0-488c-bb27-7b89306c666d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is ''flask.request'' not thread-safe in a traditional sense, and why does that not cause bugs?', N'Senior', N'It is not a global variable but a proxy object that points to the request data of the current thread. Because Flask uses Werkzeug''s local context mechanism, each thread gets its own unique context, which effectively provides thread isolation without requiring explicit synchronization locks, keeping the logic clean but invisible to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'246f440f-d540-451d-ab35-7b8b6764b2e8', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono ensure type safety without runtime overhead?', N'Middle', N'Hono leverages TypeScript''s powerful type inference to map route handlers to their inputs and outputs. By providing type definitions for the application, it catches potential errors during development rather than at runtime, maintaining high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3243c0d-5da3-4683-a049-7b8f9a06cdc5', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the ''require'' cache impact application modules?', N'Middle', N'Node.js caches modules after the first time they are loaded to improve performance and ensure singleton behavior. While this is efficient, it means that changes to a module''s state will persist across the application until the process is restarted, which can sometimes lead to unexpected side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85227a26-2d16-440d-a5ce-7b8fea440ada', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check whether an object can be extendable or not?', N'Fresher', N'The Object.isExtensible() method is used to determine if an object is extensible or not. i.e, Whether it can have new properties added to it or not. *Note: By default, all the objects are extendable. i.e, The new properties can added or modified.* &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e235e698-fb81-4d71-bd1e-7b90141ce9c0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why might a team choose Chi over a more feature-rich framework?', N'Fresher', N'Teams often choose Chi for its simplicity, stability, and adherence to Go standards. It avoids ''magic'' behavior and allows developers to choose their own libraries for tasks like database interaction or validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0237d778-7ab2-470b-97f0-7b92793d7662', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why might you choose a Wide-Column store over a Key-Value store?', N'Middle', N'A Key-Value store is highly optimized for simple lookups by key, whereas a Wide-Column store supports more complex queries over columns and rows. Wide-Column stores are better suited for large-scale analytical workloads and sparse datasets where rows may have different sets of columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9b62afb-937f-45c2-bc81-7b973a7e18f3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''Access Control'' influence compile-time optimization?', N'Senior', N'Access control markers like ''internal'' and ''private'' allow the compiler to perform ''whole-module optimization'' by knowing exactly which parts of a type are accessible. If a class or method is not exposed outside a module, the compiler can safely inline or remove unused members that would otherwise need to be preserved for public consumption. This enables tighter, more optimized binaries by restricting the surface area of the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'206ad062-43cb-4701-8ee0-7b97f6d6e30f', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of the GraalVM Native Image in a Quarkus ecosystem?', N'Middle', N'GraalVM Native Image is a technology that compiles Java bytecode into a standalone machine-code executable. It is essential for Quarkus to achieve sub-second startup times and minimal resident set size memory consumption, which is ideal for serverless and containerized environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d30a814-744d-4d1a-b566-7b9ceb1d0d00', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the difference between ''intrinsic'' and ''extrinsic'' sizing in CSS.', N'Senior', N'Extrinsic sizing relies on fixed dimensions provided by the developer, whereas intrinsic sizing allows elements to size themselves based on their content and context, such as using ''min-content'' or ''fit-content''. Intrinsic sizing is generally preferred for responsive design as it creates more resilient components that adapt naturally to varied content lengths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81cc5d2a-7b19-445d-bf8d-7ba011dfca28', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What happens if you forget to call ''next()'' in an Express middleware?', N'Intern', N'If you forget to call the next function or send a response, the request will hang indefinitely. The client will wait for a response that never arrives, eventually resulting in a request timeout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'666b5b6c-fc65-4d3f-aa35-7ba05bf1769c', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is an absolute unit versus a relative unit?', N'Junior', N'Absolute units like pixels or inches are fixed and do not change based on other elements. Relative units like percentages or rems change in relation to other factors, such as the parent element size or the root font size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
