INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd1f36b0-ad41-4daf-85e7-7ba53d06b167', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the trade-offs of using Echo''s built-in data binding versus custom deserialization strategies?', N'Senior', N'Built-in binding provides rapid development and seamless integration with struct tags, but it can be less performant under extreme load compared to manual deserialization. Custom strategies allow for fine-tuned validation and optimized memory allocation, which is preferred when latency is the primary architectural constraint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b89b3b03-a905-4881-b40a-7ba73f86b3de', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the Garbage Collector?', N'Intern', N'The Garbage Collector is an automatic memory management process in Java that identifies and deletes objects that are no longer being used by the program. This helps prevent memory leaks and reduces the burden on developers to manually release memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a43d6a-52e3-4c56-92c9-7baae77679f7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s Global Interpreter Lock (GIL) impact multi-threaded performance?', N'Middle', N'The GIL ensures that only one thread executes Python bytecode at a time, preventing race conditions in memory management. While it simplifies implementation, it prevents true parallel execution of CPU-bound tasks in a single process, making multi-threading ineffective for heavy computation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b5cf781-0e3c-4b31-94c6-7babfc239b3f', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the advantage of using a ''prepared statement'' in Cassandra from a server-side perspective?', N'Senior', N'Prepared statements allow the coordinator to parse and optimize the query execution plan once and reuse it across multiple executions. This reduces CPU overhead on the coordinator nodes and minimizes the serialization cost of the query string for repeated operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66879620-5c9c-4a84-825c-7bae489bc593', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the importance of ''Divide and Conquer'' in problem-solving?', N'Fresher', N'Dividing a large, complex problem into smaller, manageable sub-tasks makes the overall objective less overwhelming and easier to track. It allows for better estimation, clearer identification of specific issues, and the ability to solve individual pieces incrementally. This approach reduces the likelihood of errors and improves overall productivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cba226ae-3a5a-48e8-be72-7bb06feb5bc0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it generally recommended to cache jQuery selector results in variables?', N'Middle', N'Every time you call a jQuery selector, the library must search the DOM to find matching elements, which is an expensive operation. Storing the result in a variable allows you to reuse the reference without re-querying the DOM, significantly improving performance in loops or frequently triggered event handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b0f2e21-18ec-4c80-9045-7bb61ac48aef', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle reactivity compared to other frameworks?', N'Fresher', N'Svelte achieves reactivity through simple variable assignments. When a variable changes, the compiler automatically updates the DOM by surgically applying the changes, rather than re-rendering the entire component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
