INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87645710-c5fd-4e3f-b17f-7bbc841e06a0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing for high availability, what is the importance of a multi-region deployment?', N'Middle', N'A multi-region deployment protects the service from localized infrastructure outages, such as cloud provider data center failures. It improves user experience by allowing requests to be routed to the nearest geographic region, though it significantly increases the complexity of data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
