INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2ee0557-9171-44f1-bb02-7bdb60b6cc77', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Discuss the challenges of migrating an existing large-scale application to Redux Toolkit.', N'Senior', N'The primary challenges include refactoring legacy action/reducer patterns to the slice-based architecture and ensuring backward compatibility with existing middleware. A successful migration requires a phased approach, typically running both legacy and new structures in parallel, while ensuring that the underlying state structure remains consistent during the transition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7bc538f-2065-491d-8627-7bdf927a6a71', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''ref'' keyword affect parameter passing?', N'Middle', N'The ref keyword forces a parameter to be passed by reference rather than by value, allowing the method to modify the original variable. This can improve performance when passing large structures, as it avoids copying the entire value, but it requires the variable to be initialized before being passed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70f506da-91ae-4b11-ab72-7be065433772', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''page.js'' file in the app directory?', N'Intern', N'The page file is the main entry point for a specific route in the app directory. It defines the UI for a unique route and exports the React component that will be rendered when a user visits that URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b6fe725-550d-45b8-ae96-7be3ce34636b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it bad practice to expose your database schema directly through your public API?', N'Junior', N'Exposing the schema reveals internal implementation details and makes it impossible to change your database structure without breaking external clients. A Data Transfer Object (DTO) or API layer acts as a buffer, allowing you to evolve your internal storage without affecting API consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97ca51dd-f45e-465e-8c90-7be7b1049909', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a stack in the context of memory management?', N'Intern', N'The stack is a region of memory where data is stored in a last-in, first-out order. It is used for data with a known, fixed size at compile time, making access very fast, though it is limited in size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b7345a6-68ca-46d9-beeb-7becd3d0a91c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary advantage of using the Echo framework''s Context interface compared to the standard library''s context?', N'Middle', N'Echo''s Context interface wraps the standard library context while providing helper methods for request and response handling, such as binding data, rendering templates, and sending JSON. It simplifies common web tasks by bundling these utility methods directly into the request-response lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
