INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddf21d3c-0888-4908-92c6-7c0c1dc095c0', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is statelessness considered a best practice for building scalable web services?', N'Middle', N'Statelessness ensures that any server instance can handle any request because no client session data is stored locally on the server. This allows for seamless load balancing and easy horizontal scaling, as you can add or remove nodes without worrying about losing user state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f2cde56-a25f-4b40-9222-7c0c50f77a98', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle form submissions compared to traditional React?', N'Intern', N'Remix utilizes standard HTML form submissions, which function even if JavaScript fails to load on the client. It intercepts these requests to handle data processing on the server, providing a more reliable experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c813eca-7782-403e-9b1a-7c0f58eb90a0', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'When is it appropriate to use a multi-level caching strategy?', N'Senior', N'Multi-level caching uses a fast, small L1 cache (like process memory) followed by a larger, slower L2 cache (like Redis). This architecture minimizes network latency for the most frequently accessed items while keeping the total capacity large enough to avoid frequent evictions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f935823-58d0-47ea-93da-7c12759875d1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are uncontrolled components?', N'Intern', N'The Uncontrolled components are form elements (like , , or ) that manage their own state internally via the DOM, rather than through React state. You can query the DOM using a ref to find its current value when you need it. This is a bit more like traditional HTML. The uncontrolled components will be implemented using the below steps, 1. Create a ref using useRef react hook in function component or React.createRef() in class based component. 2. Attach this ref to the form element. 3. The form element value can be accessed directly through ref in event handlers or componentDidMount for class components In the below UserProfile component, the username input is accessed using ref. Note: Here, DOM is in charge of the value. React only accesses the value when needed (via ref).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e86fe85-fb88-48bc-b6e4-7c12b0dd7fec', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why might you choose SolidJS over a framework with a Virtual DOM?', N'Middle', N'You would choose SolidJS for its superior runtime performance, lower memory footprint, and smaller bundle size. Because it skips the reconciliation process, it is ideal for performance-critical applications or environments where minimizing overhead is the top priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'276b15d4-5b9c-467e-97a4-7c15584e6972', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is ''Hot Partitioning'' a major risk in a sharded database, and how is it mitigated?', N'Senior', N'Hot partitioning occurs when a disproportionate amount of traffic targets a specific shard, leading to performance bottlenecks. It is mitigated by choosing a high-cardinality shard key that distributes data uniformly or by implementing dynamic resharding strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a635c73-39bd-4316-ac50-7c156c799bdb', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the role of load balancing in a system design?', N'Intern', N'Load balancing distributes incoming network traffic across multiple servers to ensure no single server becomes a bottleneck. This increases the availability and reliability of the application by preventing overload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c3f3f4d-815c-452f-a576-7c16b111591a', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are route parameters in Fastify?', N'Fresher', N'Route parameters are dynamic parts of a URL path, such as user IDs or slugs, defined with a colon prefix. Fastify extracts these values and makes them accessible in the request object for use in your handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7077e2b0-2a23-4778-93ae-7c16d5fbd388', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it recommended to follow the principle of least privilege in system design?', N'Intern', N'The principle of least privilege ensures that every module or user only has the access necessary to perform its specific task. This limits the potential damage if a specific component is compromised, thereby improving overall system security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aa9583f-43bc-4eaf-86c2-7c1792c1b50d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a ''request'' hook and a ''teardown'' hook?', N'Middle', N'A ''request'' hook performs logic before or after the request processing, whereas a ''teardown'' hook is guaranteed to run even if an unhandled exception occurs during the request. Teardown hooks are essential for resource cleanup, such as closing database sessions or freeing up file handles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8b22ab3-4f10-45ee-97f3-7c19caa61fd4', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s dependency tracking handle ''computed'' properties to ensure efficiency?', N'Senior', N'Computed properties are lazily evaluated and cached based on their reactive dependencies. They only re-evaluate when a source dependency actually changes, preventing redundant calculations during re-renders and improving overall performance in complex view layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2098b751-a645-4afd-8330-7c19f35289b6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a function and a method?', N'Intern', N'A function is a standalone block of code that performs a task, while a method is a function that is associated with a specific type like a class, structure, or enumeration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89acafb6-10ba-4acf-8b4f-7c19f4980c59', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''payload'' in Nuxt’s hydration process?', N'Middle', N'The payload is the serialized state of the data fetched during server-side rendering. When the application hydrates on the client, Nuxt reuses this payload instead of re-fetching the data, preventing redundant network requests and ensuring state consistency between the server and the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f783aae-8782-4636-8c8d-7c20044e3bb0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Does using Sass impact page load performance?', N'Junior', N'Sass itself does not impact performance because it is compiled into standard CSS before reaching the browser. However, poorly written Sass can result in large or inefficient CSS files, which can indirectly affect load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53ae94ab-9be9-4206-b3b0-7c2067ad9f4d', N'954a0331-deff-4399-b588-96f39fec001d', N'What is protractor?', N'Intern', N'Protractor is an end-to-end test framework for Angular and AngularJS applications. It runs tests against your application running in a real browser, interacting with it as a user would.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e02e72d2-993a-4c22-b302-7c21ee3be693', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to consider the ''cost of failure'' in your engineering decisions?', N'Intern', N'The cost of failure determines how much effort should be invested in risk mitigation and redundancy. High-cost failures require exhaustive testing and formal processes, while low-cost failures may allow for more rapid, agile experimentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9059f65e-63ec-4090-84f7-7c27d7d46268', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery document ready function?', N'Intern', N'The document ready function ensures that the jQuery code only runs once the DOM (Document Object Model) has been fully loaded and is safe to manipulate. This prevents errors that occur when trying to access elements that have not been rendered yet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08a420e0-b427-40f2-860f-7c2d9c90330f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is your approach to handling an unexpected technical blocker that appears halfway through a task?', N'Junior', N'I would pause to assess the severity of the blocker and determine if I can solve it myself or if I need assistance from a senior developer. Once I have a better understanding, I would update my estimate and inform the relevant stakeholders immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f2ed867-f2b6-4236-bb2c-7c2e57b774be', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the concept of ''DTOs'' (Data Transfer Objects) in Litestar and why they are used.', N'Middle', N'DTOs in Litestar are used to define the contract for incoming and outgoing data, decoupling the internal database models from the external API representation. They improve performance by strictly controlling serialization and deserialization, reducing the risk of exposing sensitive internal fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e53d6198-8989-4a76-a5da-7c2e9d47f752', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between contenthash, chunkhash, and hash in Webpack filenames?', N'Middle', N'A hash changes whenever any part of the build changes, making it poor for caching. A chunkhash changes only when the specific chunk content changes, and a contenthash is derived from the actual content of the file, making it the best choice for long-term browser caching of static assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'906a4e46-7ce0-4d93-a58b-7c3016d7996a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the advantages of using PostgreSQL compared to flat files?', N'Fresher', N'PostgreSQL provides structured storage, data security, and concurrent access support, which flat files lack. It also ensures data consistency through ACID compliance, making it much easier to query and manage large amounts of related information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07271669-ed1a-4936-b1ab-7c328a70a8bc', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the advantages of using Echo''s ''Renderer'' interface?', N'Middle', N'The Renderer interface provides a standardized way to plug in different template engines for server-side rendering. By implementing a single Render method, developers can switch between engines like HTML templates or other view technologies without changing the controller layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9123f5c-16ad-4f5a-8f99-7c33cfa02f1f', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the role of a database proxy in a distributed system?', N'Middle', N'A database proxy acts as an intermediary between the application and the database. It can handle request routing, load balancing, connection pooling, and failover management, abstracting the complexity of the database topology from the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38518c98-d7e1-429d-ad13-7c39209e15ba', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How will you check memory leak on Linux?', N'Fresher', N'There are several tools and techniques that can be used to check for memory leaks on Linux: - Valgrind: Valgrind is a powerful memory debugging tool that can be used to detect memory leaks, among other issues. It works by running the program in a simulated environment that tracks all memory allocations and deallocations, and generates a detailed report of any errors or leaks that it finds. - LeakSanitizer (LSan): LSan is a lightweight tool that is built into the Clang and GCC compilers. It can be used to detect memory leaks at runtime by instrumenting the code with memory tracking code. When a leak is detected, LSan generates a report that includes the stack trace of the leaking allocation. - AddressSanitizer (ASan): ASan is another tool built into the Clang and GCC compilers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf8f271f-7eff-4a4f-ae85-7c3b9cf96f78', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the role of the Buffer class and its shift toward Uint8Array in modern Node.js.', N'Senior', N'The Buffer class was introduced to handle binary data before JavaScript had native support for it. Modern Node.js uses Uint8Array, which is a standard ECMAScript feature, making the codebase more compatible with browser environments. Using typed arrays instead of the legacy Buffer API is preferred for better interoperability and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db74165a-100c-4db3-96a0-7c41fdf67b62', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the significance of the Request Memoization feature in the Next.js App Router.', N'Senior', N'Request Memoization automatically deduplicates identical data fetches within a single React render pass. This prevents redundant network requests when multiple components share the same data, effectively optimizing resource usage without requiring an explicit global cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0572401a-d2e3-46a2-ac0b-7c436a24c3e5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why does AdonisJS prefer a specific directory structure?', N'Middle', N'The opinionated structure follows the ''Convention over Configuration'' principle, which reduces cognitive load for developers moving between projects. By standardizing where controllers, models, and providers live, the framework ensures maintainability and simplifies the process of onboarding new team members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f624a12c-cf9c-4f6f-8818-7c483f1a2cc4', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of +page.js in SvelteKit?', N'Fresher', N'The +page.js file is used to load data for a page before it is rendered. It runs on both the server and the client, allowing you to fetch data from APIs and provide it to the corresponding +page.svelte file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c69b76ca-afcb-4f64-938f-7c48e737192f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the concept of ''arbitrary values'' in Tailwind CSS and why they should be used sparingly.', N'Middle', N'Arbitrary values allow you to inject custom CSS values directly into utility classes using square bracket syntax. They should be used sparingly because they bypass the design system''s predefined constraints, which can lead to visual inconsistencies and ''magic numbers'' that are difficult to manage across a large codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8506bd29-e6a4-4be4-b1eb-7c496d6fc0ed', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Twig in the Symfony ecosystem?', N'Intern', N'Twig is a flexible, fast, and secure template engine used by Symfony to render HTML. It separates the presentation layer from the business logic, making templates easier to read, maintain, and secure against common vulnerabilities like cross-site scripting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c0304fe-8713-4767-89ff-7c4a96682fad', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of @Input and @Output decorators?', N'Intern', N'@Input and @Output are decorators used in Angular for communication between parent and child components. - @Input allows a parent component to pass data _down_ to a child component. You declare a property in the child component with @Input() and the parent binds to it in its template. - @Output allows a child component to send data or notify the parent component about events happening _up_ to the parent. You declare a property in the child with @Output(), initialized as an EventEmitter, and the child calls emit() to send data. The parent listens to this output property using event binding syntax (). This pattern establishes a clear, unidirectional data flow (down) and event flow (up), making component interactions predictable and easier to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49f1ff3e-f382-4816-9049-7c4b90fefd62', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why would you use ''APIRouter'' in a FastAPI project?', N'Junior', N'APIRouter is used to organize your application into smaller, manageable files or modules. It allows you to group related path operations together and mount them onto the main application instance, which is essential for maintaining clean code in larger projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8edb496e-4f5c-401a-a652-7c4c7520606c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''reply.send()'' method used for?', N'Fresher', N'The reply.send() method is the standard way to terminate the request lifecycle and send a payload back to the client. It handles strings, objects, streams, and buffers, automatically setting the correct content-type headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b668227e-5293-4191-98f7-7c4e749f89fd', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the architectural trade-offs between using Laravel''s Events/Listeners versus Jobs/Queues.', N'Senior', N'Events are synchronous and designed for decoupled code execution within the same request lifecycle, suitable for minor side effects. Jobs are asynchronous and offloaded to a background process, making them essential for heavy, time-consuming tasks to ensure the main request remains responsive and scalable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35ce6a3b-0516-4393-854d-7c5240d0c701', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the schema in Fastify?', N'Fresher', N'Schemas in Fastify are used to define the structure of input and output data for routes. They allow the framework to automatically validate incoming requests and serialize outgoing responses, which improves performance and data security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'224f4d2b-8d75-48cd-aa85-7c524a66801b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the advantage of using APIRouter in larger FastAPI applications?', N'Junior', N'APIRouter allows you to split your application into multiple files and modules, keeping your code organized and maintainable. It enables you to group related path operations together and mount them under a common prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb173b57-9c71-4856-806a-7c534da2ee67', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Doctrine in Symfony?', N'Intern', N'Doctrine is an Object-Relational Mapper (ORM) that sits between the database and the PHP objects. It allows developers to interact with the database using PHP objects instead of writing raw SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5be9fc2a-a814-4be1-96f8-7c536ea426f3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you handle the trade-offs between horizontal sharding and vertical scaling when designing a high-throughput distributed database?', N'Senior', N'Vertical scaling is simpler to implement but hits a hard ceiling on hardware capacity and creates a single point of failure. Horizontal sharding allows for near-linear scaling but introduces significant complexity regarding cross-shard joins, rebalancing data partitions, and maintaining global consistency, often requiring a distributed transaction manager.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9276600e-0166-47c2-ada3-7c5555daf057', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the trade-offs between synchronous and asynchronous messaging for inter-service communication?', N'Senior', N'Synchronous messaging provides immediate feedback and simplifies error handling but creates tight coupling and increases the likelihood of cascading failures. Asynchronous messaging improves system resilience and decoupling, but shifts complexity toward eventual consistency, distributed tracing, and more challenging debugging of failure states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'113efa0e-4526-4ebe-b480-7c55be17362d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How can you test asynchronous code in Dart?', N'Middle', N'Asynchronous code is typically tested using the test package, which provides utilities like expectLater and ''await'' to handle futures. By using these tools, tests can wait for the completion of asynchronous operations before asserting their results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
