INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'714ac38f-b08e-4a9a-974c-7c56adf38469', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between system idempotency and performance?', N'Middle', N'Ensuring an operation is idempotent often requires checking state before applying changes, which adds extra database reads. While this might slightly impact performance, it is usually a necessary trade-off to ensure system reliability in distributed environments where retries are inevitable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
