INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'761714af-3b49-4af3-9075-7c7303ae8cf4', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the architectural considerations when implementing a multi-tenant strategy at the database level versus the application level?', N'Senior', N'Application-level multi-tenancy uses a shared schema with a tenant identifier, which is easier to maintain but requires rigorous query scoping to prevent data leaks. Database-level multi-tenancy provides stronger isolation and easier backup management but increases operational complexity due to managing numerous distinct database instances or schemas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60d6c9ef-e8fa-40a1-b992-7c77e919d985', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik differ from traditional hydration?', N'Intern', N'Traditional hydration requires downloading and executing all JavaScript on the page before it becomes interactive, which can be slow. Qwik avoids this by using resumability, meaning it does not need to re-run the application logic to become interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e4002c-0278-4783-a73e-7c78e87a0295', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'When would you prefer using a map over individual variables?', N'Middle', N'Maps are ideal for organizing related data, such as color palettes, breakpoints, or spacing scales, into a single structured object. This approach makes it easier to iterate through the data programmatically using loops and improves maintainability by centralizing configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a51ba63-7de7-4685-bb4e-7c792e8e91d9', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the LitElement base class?', N'Intern', N'The LitElement base class provides the foundational functionality for a web component. It handles property observation, efficient rendering, and the lifecycle of the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd72eed2-281a-4dfc-9e9e-7c79e11e31b2', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What happens when you run the Vite ''build'' command?', N'Intern', N'Running the build command triggers a production-ready process where Vite uses Rollup to compile, bundle, and minify your application. The final output is placed in a distribution folder, ready to be hosted on a web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'910e0a23-414f-48df-b58b-7c7bd6a1c18b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a Goroutine?', N'Intern', N'A Goroutine is a lightweight thread managed by the Go runtime rather than the operating system. They allow for concurrent execution of functions and consume significantly less memory than traditional OS threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3b13d8e-317d-47a2-984f-7c7c9abfa6e4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s ''splitChunks'' plugin determine which modules to pull into a separate bundle?', N'Senior', N'The plugin uses heuristics based on chunk sharing, module size, and the number of parallel requests to identify candidates for extraction. It automatically bundles shared dependencies into a single chunk to prevent code duplication across multiple entry points while maintaining a balance between the number of HTTP requests and cache efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dafa5854-bb11-4a31-9caf-7c82a79cf37b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are ''declaration files'' (.d.ts) and why are they needed?', N'Middle', N'Declaration files contain type information for JavaScript code that lacks built-in TypeScript support. They allow TypeScript to understand the shape of external libraries, enabling autocompletion and type checking for those dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b260db92-72b7-42c7-ad3d-7c8383d3e8ba', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the trade-offs between Incremental Static Regeneration (ISR) and standard Static Site Generation (SSG).', N'Senior', N'SSG provides the fastest performance but requires a full site rebuild for content updates, which is inefficient for large-scale applications. ISR allows for background revalidation of static pages, offering a balance between the speed of static content and the dynamic nature of content that changes over time without requiring redeployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ba024fc-2507-4cf8-9a54-7c841a57f80e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between ''request.args'' and ''request.form''?', N'Fresher', N'request.args is used to access data passed through the URL query string, typically in GET requests. request.form is used to access data submitted through an HTML form, which is typically sent via POST requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e733eff-67c7-45bd-85f6-7c88c53ba440', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Providers'' directory in AdonisJS?', N'Junior', N'Providers are the entry point for booting services into the application. They are used to register bindings or perform setup logic in the IoC container so that services are ready to be used throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
