INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae8785eb-0088-4140-9fff-7c88fe3caf55', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the Redis ''List'' data structure?', N'Junior', N'A Redis List is a linked list of strings that allows for efficient pushing and popping of elements from both ends. It is commonly used for implementing queues, stacks, or managing timelines of events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a06325c7-7115-46d4-86eb-7c8a7338c2d6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the Kestrel web server handle concurrency, and what is its relationship with reverse proxies like Nginx or IIS?', N'Senior', N'Kestrel uses an asynchronous I/O model based on Libuv or its managed Socket implementation to handle high concurrency with low overhead. While Kestrel is production-ready, it is typically placed behind a reverse proxy to handle external-facing concerns like SSL termination, load balancing, and protection against certain types of HTTP-based attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a6302b8-9b30-4a74-a924-7c8b78f8d4ab', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the concept of consistent hashing and why it is used in distributed databases.', N'Senior', N'Consistent hashing maps nodes and data keys onto a logical ring, ensuring that only a small fraction of keys need to be remapped when a node is added or removed. This minimizes data movement and prevents cache/database stampedes during scaling events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cb46251-5d91-4c80-9cf8-7c91884b9bfc', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the function of a middleware in the context of Chi?', N'Intern', N'Middleware in Chi is a function that wraps an HTTP handler to perform tasks before or after the request is processed. Common use cases include logging, authentication, recovery from panics, and setting headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2941d002-7643-4f29-9ab7-7c96eedd80b1', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI manage security and authentication at the architectural level?', N'Senior', N'FastAPI handles security via the Security utility, which allows for dependency-based authentication and authorization schemes like OAuth2 or API keys. This modular approach enables developers to enforce security policies globally or locally per route, ensuring a consistent security posture while maintaining clean separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'031cd759-de53-423f-9a96-7c99b2d71ca8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the role of ''Bouncer'' in AdonisJS and its impact on authorization scalability.', N'Senior', N'Bouncer provides a central, policy-based approach to authorization, which keeps access logic out of controllers and services. This modularity allows for the dynamic scaling of authorization rules as the application grows, ensuring consistency across different parts of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1fa4ed9-a575-439e-a47c-7c9a57e88f1b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''display: none'' property differ from ''visibility: hidden''?', N'Junior', N'The ''display: none'' property removes the element entirely from the document flow, meaning it takes up no space and is ignored by the layout engine. In contrast, ''visibility: hidden'' hides the element from view, but it still occupies its original space in the layout, as if it were still visible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a08c4aa5-1ca1-44eb-80b0-7c9cfdd5d1b9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of a staging environment in the design lifecycle?', N'Intern', N'A staging environment is a mirror of the production environment used to test code and configuration changes before they are deployed to real users. It helps identify bugs, performance bottlenecks, and environment-specific issues in a safe setting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bccc112-4ee8-4d9a-8da3-7c9ec4da4e97', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is MongoDB Atlas?', N'Intern', N'MongoDB Atlas is a fully managed, cloud-based database-as-a-service (DBaaS) offered by MongoDB. It automates tasks like infrastructure setup, database scaling, and backups, allowing developers to focus on application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc9ae48c-2053-4860-bbc3-7ca398e9b168', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the Qwik Optimizer?', N'Intern', N'The Qwik Optimizer is a build-time tool that automatically splits your code into small, lazy-loadable chunks. It transforms your source code to enable fine-grained lazy loading, ensuring that the browser only downloads the specific code required for the current user interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80601ba5-3289-4c4e-873f-7cabb2667d00', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go compiler''s interface implementation check improve developer productivity?', N'Middle', N'The compiler checks at compile time whether a type implements an interface, providing immediate feedback on errors. This prevents subtle bugs where a type might have the right method names but the wrong signatures, which would otherwise only be discovered at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603bbb8d-210c-4e94-8e09-7cac167d1502', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''Json'' extractor in Axum?', N'Middle', N'The Json extractor automatically deserializes the request body into a specified Rust struct using Serde. It also handles setting the correct content-type header for the response, ensuring that data exchange is both type-safe and compliant with REST conventions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3129f601-b796-4de4-92b9-7caee9aa6b5f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where you are stuck and cannot solve a problem?', N'Fresher', N'I set a time limit for independent problem-solving to avoid spinning my wheels. Once that time passes, I reach out for assistance, explaining what I have already tried and what I have learned so far.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1bbe123-1ded-4d25-92e8-7cb32df3ca49', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What happens if a Rocket route fails to match an incoming request?', N'Fresher', N'If no route matches an incoming request, Rocket automatically returns a 404 Not Found status code to the client. This behavior is built-in and ensures that undefined paths are handled gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6c9dac7-dcdf-4fbe-baad-7cb8d5df9c0e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the security implications of using the ''Json'' extractor?', N'Middle', N'The Json extractor automatically deserializes the request body, which can be vulnerable to resource exhaustion if not paired with size limits. Always ensure you have a body size limit configured to prevent large payloads from consuming excessive server resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf88b963-c41b-4036-af4d-7cb95dd67b71', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is an attribute in DynamoDB?', N'Intern', N'An attribute is the smallest unit of data that you can manage in DynamoDB, similar to a column in a relational database. Each item consists of one or more attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d17687a-0bbe-40b9-b13d-7cbc9a015b66', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''setupController'' hook?', N'Junior', N'The ''setupController'' hook allows developers to manually configure a controller after the model has been fetched. It is useful for setting initial state or performing logic that depends on the resolved data from the route''s model hook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fa9d883-4db7-4fe0-8183-7cbf17dfe6b9', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why does Axum prioritize ''tower::Service'' compatibility?', N'Senior', N'By adopting the Tower service trait, Axum gains immediate access to a vast ecosystem of existing middleware for load balancing, retry logic, and timeouts. This architectural choice prevents vendor lock-in and allows developers to leverage battle-tested components that work consistently across the entire Rust network stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9a9b05c-2991-4581-af9f-7cbf20bf7dbe', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the primary difference between a static variable and a global variable in C?', N'Junior', N'Both variables persist for the duration of the program, but they differ in scope. A global variable is accessible from any file in the program, whereas a static variable is restricted to the file or function where it is defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cf6a12d-d154-4dc3-b5ea-7cc166aa4126', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''Astro.glob'' differ from the newer ''getCollection'' API in terms of memory usage?', N'Senior', N'Astro.glob imports all matched files into the module, which can lead to high memory usage in large projects as all content is loaded into the build process. The getCollection API is more efficient, as it is designed to work with the Content Layer to retrieve only necessary metadata and content, allowing for better scaling and build performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0b8fae1-73b8-467a-9676-7cc4e2e6b72e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix encourage developers to use ''fetcher'' instead of standard navigation for certain interactions?', N'Middle', N'Fetchers allow you to interact with loaders and actions without triggering a full page navigation or changing the URL. This is ideal for background tasks like toggling a ''favorite'' button or submitting a search query while the user remains on the current page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e609466-c044-48ba-b7db-7cc5917e5ab9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What does it mean to design a system to be ''stateless''?', N'Junior', N'A stateless system does not store client session information between requests, meaning any server instance can handle any request. This makes the system much easier to scale horizontally because you don''t need to worry about sticky sessions or synchronizing state across nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
