INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e93d0fa2-0f2c-464f-a30c-7cd97f2b1b6d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is eventual consistency in NoSQL databases?', N'Intern', N'Eventual consistency is a consistency model that ensures that if no new updates are made to a data item, eventually all accesses to that item will return the last updated value. This approach favors high availability and performance over immediate data synchronization across all nodes in a distributed system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edecdb4e-0d2f-4522-8412-7cdb9fab6f83', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the trade-offs of using Preact Signals versus standard state management libraries?', N'Senior', N'Signals provide fine-grained reactivity by tracking dependencies at the atomic level, which eliminates the need to re-render entire component trees. This is more efficient than standard state management as it bypasses the virtual DOM diffing entirely for updated values, though it requires a shift in how developers handle state dependency flows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a303f8-2be0-4786-aef3-7cdc6e093a2e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you pass arguments to an event handler?', N'Fresher', N'During iterations or loops, it is common to pass an extra parameter to an event handler. This can be achieved through arrow functions or bind method. Let us take an example of user details updated in a grid, In the both approaches, the synthetic argument e is passed as a second argument. You need to pass it explicitly for arrow functions and it will be passed automatically for bind method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92b8f095-5a6b-496c-90e5-7cdd903b143b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Controller and a Middleware in Laravel?', N'Junior', N'A Controller is responsible for handling the core business logic of an HTTP request and returning a response. Middleware, on the other hand, acts as a layer that sits between the request and the controller, used for tasks like authentication, logging, or modifying the request before it reaches the intended route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
