INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e52841c9-e2e2-4589-9ce6-7ce5b3a1b9fd', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the concept of ''undefined behavior'' in C++.', N'Middle', N'Undefined behavior occurs when code violates language rules, such as accessing out-of-bounds memory or using uninitialized variables. The compiler is not required to provide any specific output, meaning the program might crash, produce incorrect results, or appear to work fine while containing hidden vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4306e842-8c35-42c9-a793-7ce8e29fa82e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the difference between horizontal and vertical scaling in database architecture?', N'Middle', N'Vertical scaling involves increasing the capacity of a single server by adding more CPU, RAM, or storage. Horizontal scaling, which is the primary approach for NoSQL, involves adding more nodes to a distributed system to handle increased load and partition data across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6b4c229-7687-44f5-9beb-7ce9c9a850c1', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of .empty() versus .remove()?', N'Junior', N'.empty() removes all child nodes and content from the selected elements, but keeps the selected elements themselves in the DOM. .remove() deletes the selected elements and all their descendants from the DOM entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e99127f9-daee-4dd3-a1e8-7ceafbb8a21d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''composer.json'' file?', N'Intern', N'The composer.json file is used by Composer to manage the project''s PHP dependencies. It lists all the external libraries your application requires and defines the versions needed for the project to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'296e1a51-e407-44ec-a9a7-7ceb26e35071', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the impact of using high-cardinality fields in aggregations?', N'Middle', N'Aggregating on high-cardinality fields requires significant memory, as Elasticsearch must maintain a global list of all unique values. This can lead to heavy heap usage and potential performance degradation if not managed with proper memory settings or data modeling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e162371-fa6e-45a7-b3e8-7cebbef2ef33', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle heavy media or large assets in a production environment?', N'Senior', N'Remix is designed to work with standard web servers or CDNs, meaning large assets should ideally be served via a dedicated object storage or CDN rather than through the Remix server process. This prevents the Node.js event loop from being blocked by I/O-intensive file serving, keeping the dynamic request handling performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c48f0b62-c36e-48d9-9027-7cec596db191', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the function of the Quarkus ''Fault Tolerance'' extension?', N'Middle', N'Based on MicroProfile Fault Tolerance, this extension provides patterns like retries, circuit breakers, and bulkheads. These are essential for building resilient distributed systems, allowing the application to handle transient failures gracefully without crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3414325c-7885-47de-ad70-7cec7572ba91', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are union types in TypeScript?', N'Intern', N'A union type allows a variable to hold values of more than one specified type. It is denoted by the pipe symbol between types, indicating that the value could be, for example, either a string or a number.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3db68637-665d-43e3-b2fb-7cf0b9b1b2c5', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does ''Zero JavaScript'' mean in the context of Astro?', N'Fresher', N'It means that by default, Astro strips away all JavaScript from your components during the build process. Only the specific components that require interactivity will have their JavaScript shipped to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec92aad-b377-4be6-a33a-7cf10ce3c1c1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you ensure data integrity without traditional relational constraints like foreign keys?', N'Senior', N'In DynamoDB, data integrity must be managed at the application level through business logic, transactional operations, or by embedding related data within the same item. Because there are no server-side foreign keys or referential integrity checks, developers must implement custom validations. This shifts the burden of consistency from the database engine to the application architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa0ea401-6633-43bd-8760-7cf140e0d66b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the ''Read Repair'' mechanism in distributed NoSQL databases.', N'Senior', N'Read repair detects inconsistencies during read operations by comparing values from different replicas. If a discrepancy is found, the system updates the outdated replicas with the latest version before returning the data, proactively fixing inconsistencies without waiting for background repair processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0b296bf-1897-46c7-b88b-7cf52feec0c7', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the architectural considerations when choosing between a monolithic and a microservices architecture?', N'Senior', N'Monoliths offer simpler deployment and debugging but can become difficult to scale and maintain as the codebase grows. Microservices provide independent scalability and technology flexibility but introduce significant operational complexity regarding inter-service communication, distributed consistency, and observability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5b36262-f496-48ca-97c3-7cf7015b1ddf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a prototype chain', N'Intern', N'The prototype chain is a core concept in JavaScript’s inheritance model. It allows objects to inherit properties and methods from other objects. When you try to access a property or method on an object, JavaScript first looks for it on that object itself. If it’s not found, the engine looks up the object''s internal [[Prototype]] reference (accessible via Object.getPrototypeOf(obj) or the deprecated proto property) and continues searching up the chain until it finds the property or reaches the end (usually null). For objects created via constructor functions, the prototype chain starts with the instance, then refers to the constructor’s .prototype object, and continues from there.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7acfd4d-079d-4cd9-b1c6-7cfa3ac97a75', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between a library and a package in Dart?', N'Fresher', N'A library is a file or set of files containing Dart code that can be imported. A package is a directory structure containing one or more libraries, along with metadata and dependencies defined in a configuration file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'490af2e8-b967-4417-a586-7cfa99370858', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle CSS scoping, and what are the performance implications?', N'Senior', N'Svelte scopes CSS by generating unique class names for elements during compilation, ensuring styles do not bleed out of components. Because this happens at build time, it eliminates the need for runtime style-injection libraries, reducing the total CSS footprint and improving initial page load speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76471cde-c543-465a-9563-7cfe49afc52c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the concept of ''lazy-loading'' in Qwik compared to standard module federation.', N'Senior', N'In standard frameworks, lazy loading is usually developer-defined at the route or component level. In Qwik, lazy loading is granular and automated at the function level, where even individual event handlers are split into separate bundles that are only loaded upon interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a509480e-8257-4ca2-b6fc-7cff16b8b827', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you are given feedback that your work is too complex, what steps do you take to improve it?', N'Fresher', N'I would review the code or solution to see if it can be broken down into smaller, more manageable parts. I would also look for ways to simplify the logic, remove unnecessary steps, and add clear comments or documentation to explain the remaining complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cfa6b69-95af-4b81-8340-7cffbf5c8ec0', N'075b8862-431c-4678-9767-f55359758a4a', N'What are global mixins?', N'Intern', N'Sometimes there is a need to extend the functionality of Vue or apply an option to all Vue components available in our application. In this case, mixins can be applied globally to affect all components in Vue. These mixins are called as global mixins. Let''s take an example of global mixin, In the above global mixin, the mixin options spread across all components with the console running during the instance creation. These are useful during test, and debugging or third party libraries. At the same time, You need to use these global mixins sparsely and carefully, because it affects every single Vue instance created, including third party components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b184a0d8-7987-42e8-9527-7cffed0d7535', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the IoC container?', N'Fresher', N'The Inversion of Control (IoC) container is the core of the Spring framework. It is responsible for creating, configuring, and managing the lifecycle of objects (beans) from instantiation to destruction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63f095e1-3daa-4ba4-935e-7d013e1e820f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you account for ''buffer'' or ''contingency'' time in your estimates?', N'Fresher', N'Contingency time should be based on the level of risk and uncertainty associated with the task, not just a random percentage. I include it to handle foreseeable risks, like minor environment setup issues or communication delays, while keeping it separate from the core task effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'632ce69f-43d5-4dcc-9e8b-7d0249d5b8c0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the inverted index in Elasticsearch?', N'Intern', N'The inverted index is the core data structure that allows for full-text search. It maps every unique word in the documents to a list of the documents that contain that word, enabling very fast lookup speeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9436ec29-24cd-4ce3-8b54-7d02d039a1da', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery .attr() method?', N'Intern', N'The .attr() method is used to get or set the values of attributes for selected elements. Common examples include changing the source of an image or the href of a link.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11456a57-ff6d-4026-9fa9-7d0341457391', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage the DOM?', N'Fresher', N'Alpine.js uses a virtual DOM-like approach to keep the real DOM in sync with your JavaScript state. It watches for changes in your data and updates only the specific elements or attributes that are affected by those changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8627b87-5f90-4e8a-bde1-7d045d7185da', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the concept of ''covariance'' and ''contravariance'' apply to C# generic interfaces?', N'Senior', N'Covariance (out) allows a generic interface to accept a more derived type than specified, while contravariance (in) allows it to accept a less derived type. These mechanisms provide type safety when dealing with collections or functional delegates, preventing runtime casting errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a770a1-b6d8-408c-ada0-7d05c1e5f6bb', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a RESTful API in the context of Express?', N'Intern', N'A RESTful API is an architectural style for providing standards between computer systems on the web. In Express, this means using standard HTTP methods like GET to retrieve data, POST to create data, PUT to update data, and DELETE to remove data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a3878ae-142a-4c42-8501-7d06c31cea01', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit leverage the Shadow DOM to optimize performance and encapsulation?', N'Senior', N'Lit uses Shadow DOM to provide style encapsulation, preventing CSS leakage and reducing the scope of style recalculations. By isolating the component tree, it minimizes the work the browser needs to perform during the layout and paint phases when styles change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70498e79-ef81-4ae8-8933-7d08860dfbc4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does hoisting affect function declarations and expressions?', N'Fresher', N'Hoisting in JavaScript means that function declarations are moved to the top of their containing scope during the compile phase, making them available throughout the entire scope. This allows you to call a function before it is defined in the code. However, function expressions are not hoisted in the same way. If you try to call a function expression before it is defined, you will get an error because the variable holding the function is hoisted but not its assignment. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'963e5034-cbd5-49a8-9738-7d08ed991db3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When is it appropriate to use the ''useReducer'' hook instead of Redux?', N'Senior', N'useReducer is ideal for local state management within a single component tree where the complexity does not warrant the overhead of global state. It provides a similar pattern to Redux but lacks the middleware, dev-tools, and cross-component accessibility offered by a global Redux store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ef31dac-cfea-4e68-a2e2-7d0a0e6cace9', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Job in Laravel?', N'Junior', N'A Job is a class that encapsulates a specific task that can be pushed onto a queue to be processed in the background. This improves application performance by allowing the user to receive an immediate response while time-consuming tasks, like sending emails, run asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b40545b1-e976-4ea6-81b4-7d0ae8e6cf68', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs of using environments for data storage compared to lists?', N'Middle', N'Environments are reference-based, meaning they are modified in place rather than copied, which is more memory-efficient for large objects. However, because they are mutable, they can introduce side effects that make code harder to debug compared to the functional, copy-on-modify behavior of lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd70fe2f6-476b-465f-9552-7d0d73854955', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the primary difference between R''s S3 and S4 object-oriented systems?', N'Middle', N'S3 is a informal, class-based system that uses generic functions and method dispatch based on the class attribute. S4 is a formal system that requires explicit class definitions, supports multiple dispatch, and enforces stricter data structures through validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55ff9ed6-c032-4059-83f8-7d0e93288e6e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What happens if you do not define an index on a frequently queried field?', N'Junior', N'If there is no index, MongoDB must perform a collection scan. This means the database engine reads every document in the collection to determine if it matches the criteria, which significantly degrades performance as the collection grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a12091e6-d9cc-4986-a9ac-7d0ec7e1a4cd', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik achieve near-instant page loads through lazy loading?', N'Intern', N'Qwik achieves fast performance by treating all JavaScript as lazy-loadable by default. Instead of downloading and executing all component logic upfront, the framework only downloads the specific code required when a user interacts with a part of the page. This granular approach ensures that the main thread remains free, significantly improving the initial interactive state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49915d2e-d501-46f1-b9bc-7d161d827ce2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle routing?', N'Intern', N'Astro uses file-system-based routing, meaning the structure of your files in the src/pages directory determines the URL structure of your website. Each file represents a route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'678fe6e8-8f39-4b15-8b55-7d166b3e6c23', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix manage database connection pooling?', N'Middle', N'Phoenix uses the ''DBConnection'' library, which provides a pool of connections for Ecto to use. This prevents the application from overwhelming the database with too many simultaneous connection attempts and ensures efficient reuse of established connections, which is critical for high-concurrency systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb174ee8-7020-486b-a85a-7d16bab03102', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What distinguishes an ''abstract class'' from an ''interface'' in Dart?', N'Middle', N'In Dart, every class implicitly defines an interface, so any class can be implemented. An abstract class is a special kind of class that cannot be instantiated and is used to define common behavior or state that subclasses should share, while still leaving some methods to be implemented by children.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7449259-a6d0-4921-878a-7d18b64a386b', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''rate limiting'' contribute to system reliability?', N'Middle', N'Rate limiting protects services from being overwhelmed by too many requests, whether from malicious actors or unexpected traffic spikes. By capping the number of requests a user can make, it ensures the system remains available for all users rather than crashing under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12aa55e2-559c-49a6-bdad-7d199e81b5ea', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What happens if you have a naming conflict in Sass?', N'Intern', N'If you are using the older @import, naming conflicts can occur because everything is in the global scope. Using the modern @use directive avoids this by requiring you to access variables and mixins through the module''s namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bb7f4f3-21a2-4eec-befb-7d1ace06089e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot''s ''Profile'' mechanism facilitate environment-specific behavior?', N'Senior', N'Profiles allow beans to be conditionally registered based on the active runtime environment, such as ''prod'', ''dev'', or ''test''. By partitioning configuration into profiles, developers can avoid hardcoding environment-specific logic, ensuring that sensitive or infrastructure-dependent beans are only initialized when appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cc6ffa3-f224-462f-8ad7-7d1cbfd30621', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of the WHERE clause versus the HAVING clause?', N'Junior', N'The WHERE clause is used to filter individual rows before any grouping occurs. The HAVING clause is used to filter data after the GROUP BY clause has aggregated the rows, typically to filter based on aggregate functions like COUNT or SUM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bd98b08-552a-42b5-bfb2-7d1d87f90e79', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does load balancing improve system scalability?', N'Middle', N'Load balancers distribute incoming network traffic across multiple backend servers, ensuring no single server is overwhelmed. This allows the system to handle more concurrent requests by scaling out the application layer horizontally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b52c2b5a-ea42-45a9-a041-7d1e2e6099de', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the ''Hexagonal Architecture'' (Ports and Adapters) pattern.', N'Senior', N'Hexagonal architecture isolates the core business logic from external concerns like databases, APIs, or UIs through interfaces called ports. This makes the system highly testable and allows for swapping external dependencies without changing the internal domain logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f078c351-6831-4020-9f49-7d1feac6e56a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a method and an associated function in Rust?', N'Intern', N'A method is a function defined within a struct''s implementation block that takes a reference to the instance as its first parameter, usually called self. An associated function is defined in the same block but does not take self, often acting as a constructor or utility function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
