INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9aa1d30b-140a-4144-b234-7d40df45a98a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is it possible to use Preact without a build step?', N'Fresher', N'Yes, you can use Preact by including it via a script tag from a CDN. This allows you to use Preact in simple projects or prototypes without needing complex tools like Webpack or Vite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c75d9bb-72bf-4d22-a390-7d410c3e0483', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the difference between an intrusion detection system (IDS) and an intrusion prevention system (IPS)?', N'Middle', N'An IDS monitors network traffic for suspicious activity and sends alerts to administrators without blocking the traffic. An IPS sits inline and automatically takes action to block or drop packets that match known attack patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4689debd-ec2a-4031-ba17-7d4219c06238', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the ''src/pages'' directory structure?', N'Fresher', N'The ''src/pages'' directory serves as the root for your website''s routing. The structure of folders and files within this directory maps directly to the URL structure of the deployed website.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'122a10b9-c9ed-4e86-8ab6-7d433a9ce366', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix require a specific database?', N'Intern', N'No, Remix is database-agnostic. Because loaders and actions run on the server, you can connect to any database or external API of your choice using standard server-side libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68cd58f8-8e26-4e32-b5a0-7d43e9549ecf', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does ''SSR'' stand for in the context of Remix?', N'Intern', N'SSR stands for Server-Side Rendering. It is the process where the server generates the HTML for a page request and sends it to the browser, allowing the user to see content immediately without waiting for JavaScript execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
