INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c32e790-0ae2-47e6-a3b4-7d45d0ca412c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust distinguish between ''String'' and ''&str'' at the type level?', N'Senior', N'This distinction separates owned, heap-allocated growable buffers from immutable string slices that point to existing memory. By enforcing this difference, the language allows for precise control over memory ownership, minimizing unnecessary allocations and copies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e91fb0a5-6279-47e7-aca9-7d49f0f41b66', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Can Litestar be used for synchronous applications?', N'Junior', N'Yes, Litestar supports both asynchronous and synchronous route handlers. If you define a handler with ''def'' instead of ''async def'', Litestar will execute it in a separate thread to ensure the main event loop remains non-blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'128bcce2-1f5a-47c7-b882-7d4d03c8df16', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does NoSQL stand for and what does it represent?', N'Intern', N'NoSQL stands for Not Only SQL. It represents a category of database management systems that are designed to handle unstructured or semi-structured data, differing from traditional relational databases by not relying on a fixed schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46e69e8d-f9ce-4561-92b5-7d4d6698f20a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does it mean for TypeScript to be a statically typed language?', N'Intern', N'Being statically typed means that variable types are known and checked at compile time rather than at runtime. This allows the TypeScript compiler to verify that values assigned to variables match their declared types, reducing the likelihood of unexpected behavior during program execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49e5c254-2eab-4a99-9fa6-7d4ee6c5a0a1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''self'' keyword?', N'Intern', N'The ''self'' keyword refers to the current instance of a class, struct, or enum. It is commonly used to distinguish between property names and parameter names when they are identical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baae8d20-0953-4dd5-9940-7d502727f5e6', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the performance implications of using partial indexes compared to full-table indexes?', N'Senior', N'Partial indexes contain entries only for rows that satisfy a specific predicate, resulting in smaller index sizes and faster updates. This reduces I/O pressure and memory usage, provided that queries consistently filter by the criteria defined in the partial index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1352ed4-bb8c-478f-85bd-7d51a39458b1', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain data bindings and the different types.', N'Fresher', N'Data binding in Angular is a mechanism that synchronizes data between the component class and the template (view). It allows you to display component data in the view and react to user input or events from the view. There are two main categories: 1. One-way binding: Data flows in a single direction, either from the component to the view or from the view to the component. - Interpolation ({{ value }}): Displays component property values as text in the template. Data flows from component to view. - Property binding ([property]="value"): Sets a DOM element''s property to the value of a component property. Data flows from component to view. - Attribute binding ([attr.attribute]="value"): Sets an HTML attribute''s value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a492e96d-af65-43a1-890f-7d52181379fb', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What impact does the choice of database backend have on Django''s feature set and performance?', N'Senior', N'Different backends have varying support for advanced features like JSON fields, partial indexes, and window functions. Choosing a backend like PostgreSQL offers the most feature-rich integration with Django, whereas others may require custom extensions or result in limited ORM functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4fe53ab-b8df-44f7-af40-7d53a6cf1ece', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the function of the WiredTiger ''Checkpoints'' mechanism?', N'Senior', N'Checkpoints ensure data consistency by periodically flushing the in-memory data to the disk and recording the state of the system. In the event of a crash, WiredTiger uses the last successful checkpoint to recover the data to a known consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6257067-2167-48a2-9232-7d53e3aea7da', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust not have a garbage collector?', N'Intern', N'Rust avoids a garbage collector to ensure predictable performance and lower memory overhead. By using the ownership and borrowing rules, the compiler can determine exactly when to release memory, removing the need for a background process to manage it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd73d8e8f-ae3b-4225-88c2-7d550cc0b68c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''Buffer'' pool in Node.js?', N'Middle', N'Node.js uses a pool of memory to allocate small Buffer instances to improve performance and reduce overhead. By reusing memory chunks, it minimizes the frequency of garbage collection cycles associated with allocating new memory for binary data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'371d1d62-a6f8-4ba3-9e15-7d563963803e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a problem is worth solving?', N'Intern', N'I would weigh the effort required to solve the problem against the value or impact the solution provides. If the cost of the solution outweighs the benefit, I would document the problem but focus resources on higher-impact initiatives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3850450-d56d-4f63-b4c0-7d5897eef4d2', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is it important to keep the ''Client'' boundary as low as possible in the component tree?', N'Senior', N'Keeping the client boundary low ensures that the majority of the component tree remains as Server Components, which are zero-bundle-size. This reduces the amount of JavaScript sent to the browser, leading to faster execution times and better overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'154cd31a-1dc1-4bb2-aa07-7d599ae825c4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Explain your process for debugging a system that is running slower than expected.', N'Fresher', N'I would start by establishing a baseline to measure the performance degradation objectively. Then, I would isolate components by checking resource utilization like CPU, memory, and network latency to identify potential bottlenecks. Once a specific area is identified, I would examine recent changes or configuration updates that might have introduced the regression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09ab7c22-9b5a-4719-8278-7d5fe4c8763f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between shim and polyfill', N'Fresher', N'A shim is a library that brings a new API to an older environment, using only the means of that environment. It isn''t necessarily restricted to a web application. For example, es5-shim.js is used to emulate ES5 features on older browsers (mainly pre IE9). Whereas polyfill is a piece of code (or plugin) that provides the technology that you, the developer, expect the browser to provide natively. In a simple sentence, a polyfill is a shim for a browser API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93423caa-059f-48ea-ae66-7d61c85c0726', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why are NoSQL databases often preferred for horizontal scaling?', N'Junior', N'NoSQL databases are designed to scale horizontally by adding more servers to a distributed network rather than increasing the power of a single machine. This architecture allows them to handle massive volumes of data and traffic across multiple nodes seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff451778-903c-49b6-be4e-7d6658adda2e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does ''final'' mean when applied to a class or method?', N'Junior', N'When applied to a class, ''final'' prevents that class from being inherited. When applied to a method, it prevents child classes from overriding that specific method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65d6cd18-bca2-48b8-98d9-7d690705f538', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the difference between the generational garbage collection strategy and incremental marking in V8.', N'Senior', N'Generational GC splits the heap into young and old generations, assuming most objects die young, which optimizes for frequent minor collections. Incremental marking breaks the marking process into smaller segments to prevent long GC pauses that would otherwise block the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38cac67c-e8b1-405f-bf01-7d6a0d7da69f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the significance of the recycling rule in R?', N'Junior', N'The recycling rule occurs when performing operations on two vectors of unequal length. R automatically repeats the elements of the shorter vector until it matches the length of the longer vector, often issuing a warning if the lengths are not multiples.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd71dbeb-bbc0-4704-b382-7d6a8de7d459', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between a Row and a Partition in Cassandra?', N'Junior', N'A partition is a logical container for related rows that share the same partition key and reside on the same set of nodes. A row is an individual record within that partition, identified by its clustering columns to define its unique position and sort order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83d0a4f8-5366-46de-a0a6-7d6ae0f29805', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of a join table in a many-to-many relationship?', N'Junior', N'A join table serves as an intermediary that maps the relationships between two other tables. It contains foreign keys that point to the primary keys of the two tables being linked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd23e6663-2932-4b9e-a63a-7d6f61d50e00', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine if a task is taking longer than it should?', N'Intern', N'I set personal milestones and time-boxes for specific sub-tasks. If I reach a deadline without making significant progress, it serves as a red flag that I may be stuck or that the problem is more complex than initially estimated, prompting me to seek guidance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48794c41-488c-45ec-9e30-7d727be76da3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You notice a sudden drop in website traffic. What factors would you investigate first?', N'Intern', N'I would start by checking if the website is actually reachable to rule out a total outage. Next, I would investigate recent changes to the site or infrastructure to see if a deployment caused the issue. Finally, I would check external factors like network connectivity or third-party service dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e6ad22d-cd45-4ec0-89bf-7d73dda25594', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''let'' function used for?', N'Fresher', N'The ''let'' function is a scope function that allows you to execute a block of code on an object. It is frequently used to perform null checks, as it only executes the block if the object is not null.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25003ab0-b261-4baf-9701-7d73ec33d650', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do closures impact memory management?', N'Senior', N'Closures retain references to variables from their outer lexical scope as long as the closure exists. If not managed carefully, this can cause variables to stay in memory longer than intended, preventing the garbage collector from freeing them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b11f29a0-a336-4a0d-8f18-7d74509c9254', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle receiving critical feedback on your work?', N'Intern', N'I view feedback as an opportunity to improve my skills and the quality of the project. I listen objectively, ask clarifying questions to ensure I understand the concern, and incorporate the suggestions to produce a better final result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec8105e5-42e8-4f15-906f-7d76b68c60c2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the impact of using ''Doctrine Migrations'' in a multi-node deployment environment?', N'Senior', N'Migrations must be executed in an atomic, serialized fashion to prevent concurrent schema modifications, which could corrupt the database state. In a multi-node setup, it is critical to run migrations as a pre-deployment step from a single instance to ensure synchronization across all application servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa6c8d6e-7cf2-4da6-8a3a-7d774d3620b4', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to use version control systems like Git when working on a team project?', N'Fresher', N'Version control allows multiple developers to work on the same codebase simultaneously without overwriting each other''s changes by managing branches and merges. It also provides a complete history of changes, making it easy to revert to a previous stable state if a bug is introduced. This ensures collaboration remains organized and reduces the risk of losing work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a228b51-657c-4843-b23a-7d780d983e2f', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is dynamic memory allocation in C++?', N'Intern', N'Dynamic memory allocation in C++ allows for memory management during program execution. Unlike automatic and static storage durations, dynamic allocation lets you explicitly control an object''s lifetime, size, and location in the program''s memory. Key Concepts Heap Dynamic memory is allocated from the heap, a large pool of memory that exists throughout the program''s runtime. Unlike the stack, which has a fixed and more limited size, the heap can grow and shrink as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf1fa5ea-a417-4b04-b341-7d793187992f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a Request-scoped provider and a Singleton provider?', N'Junior', N'A singleton provider is instantiated once for the entire application lifecycle and shared across all modules. A request-scoped provider is created anew for every incoming request and is destroyed once the request is completed, which is useful for tasks like tracking user-specific state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b24e1aaf-1e4d-4f7e-b386-7d79e008a23c', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the supported modifiers on model?', N'Intern', N'There are three modifiers supported for v-model directive. 1. lazy: By default, v-model syncs the input with the data after each input event. You can add the lazy modifier to instead sync after change events. 2. number: If you want user input to be automatically typecast as a number, you can add the number modifier to your v-model. Even with type="number", the value of HTML input elements always returns a string. So, this typecast modifier is required. 3. trim: If you want whitespace from user input to be trimmed automatically, you can add the trim modifier to your v-model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7218787-0d14-41ca-a44e-7d7b15ffc152', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the Sidecar pattern benefit microservice development?', N'Middle', N'The sidecar pattern attaches a helper container to the main application container to handle peripheral tasks like logging, monitoring, or networking. This keeps the core business logic lightweight and allows for the reuse of infrastructure logic across different services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb56222d-7a79-4aaa-9eeb-7d7bb7b17535', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the ''Consistency Level'' setting?', N'Intern', N'The consistency level determines how many replica nodes must acknowledge a read or write request before the operation is considered successful. A higher consistency level ensures more accurate data but can increase latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'057267a0-33f4-4e2e-962c-7d7e9d8c6490', N'4c000000-0000-0000-0000-000000000005', N'Why is ''Vector Clocks'' preferred over simple timestamps for conflict resolution in distributed systems?', N'Senior', N'Timestamps are unreliable in distributed systems due to clock skew across machines. Vector clocks track the causality of events, allowing the system to detect if one operation happened before another or if they are concurrent, thus enabling smarter conflict resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14b197ac-a279-45f5-8542-7d7ee011b9f0', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How should you approach error handling in Gin to ensure robust production monitoring?', N'Senior', N'Instead of returning errors directly, you should use the context''s error mechanism to collect errors and then utilize a global recovery middleware to log and format them consistently. This ensures that internal details are hidden from the client while providing sufficient observability data for error tracking systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deab247f-dda5-4ba7-85c2-7d86e18da9ff', N'4c000000-0000-0000-0000-000000000005', N'What is the CAP theorem?', N'Middle', N'The CAP theorem states that a distributed system can only provide two out of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, a system must choose between consistency or availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a4b80ff-9737-418c-be96-7d8794ac9d39', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is Hot Module Replacement (HMR) and how does it improve the developer experience?', N'Junior', N'Hot Module Replacement is a feature that allows the browser to update only the specific module that was changed without requiring a full page reload. This preserves the current application state, such as form inputs or scroll position, making the development process much faster and more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40134017-4f2a-4736-a5fd-7d886608dd9a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the trade-offs of using Echo''s custom Context object versus the standard library''s context.Context.', N'Senior', N'Echo''s custom context wraps the standard library context while adding convenience methods for JSON binding, rendering, and URL parameter retrieval. The trade-off is a tighter coupling to the framework, which makes unit testing more dependent on Echo-specific types rather than standard interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'442e4710-5689-4fdd-af2b-7d8a75086dce', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is Preact strictly for building single-page applications?', N'Junior', N'While Preact is excellent for single-page applications, it can also be used for smaller components or widgets within a traditional multi-page website. Its small size makes it ideal for injecting interactivity into existing pages without bloat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98945976-24dd-4341-beeb-7d8a9f031d59', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the architectural trade-offs of using an out-of-process versus in-process hosting model in IIS for ASP.NET Core?', N'Senior', N'In-process hosting runs the application inside the IIS worker process, eliminating the overhead of proxying requests between IIS and Kestrel, which improves throughput. Out-of-process hosting provides better isolation because the application runs in its own process, ensuring that an application crash does not affect the web server''s stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28a42af3-47b0-4bd7-a1b0-7d8ab0a85106', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you architect a system to handle a ''thundering herd'' problem after a cache invalidation event?', N'Senior', N'I would implement jittered backoff strategies and request collapsing to prevent simultaneous cache misses from overwhelming the backend. Additionally, I might use probabilistic early recomputation or stale-while-revalidate patterns to ensure the cache remains populated without forcing the origin to process redundant requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72e5da0e-c080-48c1-a24a-7d8ad6aa451c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can Preact be used without a build tool?', N'Intern', N'Yes, Preact can be used directly in the browser via script tags without a complex build setup. This makes it a great choice for small projects, prototypes, or adding interactivity to existing static websites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'050e1860-dd96-4cca-b5c0-7d8fc25044a3', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the difference between ''macrotasks'' and ''microtasks'' in the context of the event loop.', N'Senior', N'Macrotasks include I/O, timers, and setImmediate, while microtasks include promise resolutions and process.nextTick. The event loop processes all pending microtasks before moving to the next macrotask phase, which can lead to starvation if microtasks are continuously added during the execution of other microtasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76749206-461a-4744-9012-7d90f55541f1', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do ''Rate Limiting'' and ''Throttling'' protect system scalability?', N'Senior', N'Rate limiting restricts the number of requests a user or client can make within a time window, preventing resource exhaustion from spikes or abuse. Throttling manages the rate of incoming traffic to match the system''s capacity, ensuring stable performance under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5f992b9-6e91-44e4-a7f4-7d92927f80b8', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between a ''node'' and a ''cluster'' in Elasticsearch architecture?', N'Middle', N'A cluster is a collection of one or more nodes that work together to share data and workload, identified by a unique cluster name. A node is a single running instance of Elasticsearch that stores data and participates in the cluster''s indexing and search capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46c6f55f-8ee1-4f37-a390-7d94af5cef01', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can you avoid problems related to hoisting?', N'Fresher', N'To avoid problems related to hoisting, always declare variables at the top of their scope using let or const instead of var. This ensures that variables are block-scoped and not hoisted to the top of their containing function or global scope. Additionally, declare functions before they are called to avoid issues with function hoisting. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1810d18f-6f54-40bf-a153-7d94be3c81b7', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the difference between ''Addr'' and ''WeakAddr'' in Actix.', N'Senior', N'An Addr keeps a strong reference to an actor, ensuring it remains alive as long as the address exists. A WeakAddr does not prevent the actor from stopping, which is useful for avoiding circular reference patterns or when checking for an actor''s presence without forcing its continuation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5067c03c-69dd-4821-b0c7-7d955c07e123', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact considered ''batteries-not-included'' compared to React?', N'Senior', N'Preact provides only the core view layer, intentionally excluding auxiliary tools like complex state management, routing, or advanced testing utilities. This forces developers to select and integrate their own preferred tools, resulting in a more modular architecture but requiring more initial setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09fb62a3-5c9f-45c9-8b06-7d95e8bf7053', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of TypeScript compared to JavaScript?', N'Intern', N'TypeScript is a syntactic superset of JavaScript that adds static type definitions. Its primary purpose is to catch errors during development through type checking before the code is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee1c324b-3ca9-47a9-aa4c-7d967d853298', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle error boundaries?', N'Middle', N'SvelteKit uses a special ''+error.svelte'' file that acts as an error boundary for a specific route or the whole app. If an error occurs during loading or rendering, SvelteKit catches it and renders this error component, allowing you to provide a graceful fallback UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
