INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b26cccee-53af-4082-8059-7d9dccade679', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js approach accessibility in its design?', N'Senior', N'Alpine is framework-agnostic regarding accessibility; it does not enforce specific patterns, requiring developers to manually manage ARIA attributes and focus traps. Because it works directly on the HTML, it encourages developers to write semantic markup, though it requires strict discipline to ensure dynamic changes remain accessible to screen readers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7239a51-4189-4845-89ee-7d9e87ba5d30', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach choosing an appropriate caching strategy for a high-traffic read-heavy application?', N'Middle', N'I evaluate the trade-off between cache consistency and latency. A cache-aside pattern is effective for general data, while write-through caching ensures high data integrity. I also consider eviction policies like LRU to ensure the most relevant data stays in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
