INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'290110b7-d55a-4530-924b-7dbb444cb756', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are negative indexes and why are they used?', N'Intern', N'Python sequences can be index in positive and negative numbers. For positive index, 0 is the first index, 1 is the second index and so forth. For negative index, (-1) is the last index and (-2) is the second last index and so forth. The sequences in Python are indexed and it consists of the positive as well as negative numbers. The numbers that are positive uses ''0'' that is uses as first index and ''1'' as the second index and the process goes on like that. The index for the negative number starts from ''-1'' that represents the last index in the sequence and ''-2'' as the penultimate index and the sequence carries forward like the positive number. The negative index is used to remove any new-line spaces from the string and allow the string to except the last character that is given as S[:-1].', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
