INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ae15a94-7f95-439f-b6f1-7dc8c8039b3e', N'075b8862-431c-4678-9767-f55359758a4a', N'What is async error handling?', N'Intern', N'From 2.6 version onwards, Vue''s built-in error handling mechanism can capture errors inside v-on handlers. Also,if any of your lifecycle hooks or event handlers performs asynchronous operations, you can now return a Promise from the function so that any uncaught errors from that Promise chain are also sent to your error handlers. Let''s take an example of mounted lifecycle hook,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3bccec4-87ce-4060-9ea8-7dc95dce288b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web ensure memory safety?', N'Fresher', N'Actix-web inherits memory safety from the Rust programming language. Because Rust uses a strict ownership and borrowing system, it prevents common issues like null pointer dereferences and data races at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'443f5a66-8f13-4657-bacc-7dcd60df75c3', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle null safety compared to Java?', N'Junior', N'Kotlin treats null safety as a part of its type system, meaning variables cannot hold null values by default. Developers must explicitly declare a type as nullable by adding a question mark to the type name. This design forces the developer to handle potential null values at compile time, significantly reducing NullPointerExceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b11f261-5564-4f78-9f53-7dcecf832f42', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of Astro’s partial hydration?', N'Intern', N'Partial hydration allows you to load only the specific components that need interactivity. This prevents the browser from having to download and parse large amounts of unnecessary code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'242c99d5-8d48-436f-8c96-7dcf5befc8b1', N'954a0331-deff-4399-b588-96f39fec001d', N'What are templates?', N'Intern', N'In Angular, templates are HTML fragments that define the structure and appearance of a component''s view. They are essentially standard HTML enhanced with Angular-specific syntax, allowing you to dynamically display data, respond to user input, and conditionally render elements. Each component is associated with a template, either defined inline using the template property or in a separate file using templateUrl. Angular compiles these templates to render the component''s UI in the browser. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11c134fd-4256-4e3b-9451-7dcf67e2e06b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the Spring DispatcherServlet?', N'Middle', N'The DispatcherServlet acts as the central Front Controller in Spring MVC. It intercepts incoming HTTP requests, directs them to the appropriate handler mapping, manages the execution of interceptors and controllers, and finally coordinates the view resolution or response body serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
