INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ebb4de3-ba2b-4b41-a03e-7dd5c2552356', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you implement custom recovery middleware in Chi?', N'Middle', N'You can implement a custom recovery middleware by creating a function that wraps the next handler in a defer block. Inside the deferred function, you catch panics, log the error, and return a 500 response, then plug this middleware into the Chi router chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4c204c0-bbb0-4d5d-a6e2-7dd5c32dfc47', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is bytecode in the context of Java?', N'Intern', N'Bytecode in Java refers to the compact, platform-independent instructions generated by the Java compiler. It serves as an intermediate representation between Java source code and the Java Virtual Machine (JVM) execution environment. Key Characteristics 1. Platform Independence: Bytecode is designed to run on any device with a compatible JVM, embodying Java''s "Write Once, Run Anywhere" philosophy. 2. Compact Format: Bytecode instructions are typically more concise than equivalent machine code, reducing storage and transmission requirements. 3. Verification: The JVM performs bytecode verification to ensure code safety and integrity before execution. Execution Process 1. Compilation: Java source code is compiled into bytecode. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
