INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b808c12-8fb3-4f2e-936b-7ddbb7b455b2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is immutable object?', N'Intern', N'Immutable objects are objects that don''t change. A Java immutable object must have all its fields be internal, private final fields. It must not implement any setters. It needs a constructor that takes a value for every single field. Creating an Immutable Object: * Do not add any setter method * Declare all fields final and private * If a field is a mutable object create defensive copies of it for getter methods * If a mutable object passed to the constructor must be assigned to a field create a defensive copy of it * Don''t allow subclasses to override methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1a7c3cf-d2e5-498e-a5dc-7dde2ba58200', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the impact of synchronous versus asynchronous replication on system availability and consistency?', N'Senior', N'Synchronous replication ensures strong consistency by waiting for all replicas to acknowledge a write, but it increases latency and reduces availability if a node fails. Asynchronous replication provides higher performance and availability by returning success immediately, but it risks data loss or stale reads during a failover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
