INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b79b1352-6337-40c4-aca3-7e045585197c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the ''Redux-Persist'' strategy and the security considerations involved when using it.', N'Senior', N'Redux-Persist serializes and saves the state to storage like LocalStorage or IndexedDB to maintain state across reloads. The main security risk is storing sensitive data like authentication tokens or PII in cleartext, which can be vulnerable to XSS attacks; such data should be encrypted or excluded from persistence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd455a42-0986-4680-9bf4-7e0b788c84e2', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do constant expressions (''constexpr'') improve code performance?', N'Middle', N'Constexpr allows the compiler to evaluate expressions at compile-time rather than runtime. This shifts the computational burden from the end-user to the build process and allows for better constant folding and optimization of the resulting binary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86821f42-6a79-4355-9317-7e0be54f9fd0', N'954a0331-deff-4399-b588-96f39fec001d', N'Is it safe to use direct DOM API methods in terms of security?', N'Middle', N'No,the built-in browser DOM APIs or methods don''t automatically protect you from security vulnerabilities. In this case it is recommended to use Angular templates instead of directly interacting with DOM. If it is unavoidable then use the built-in Angular sanitization functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'016e2466-27d9-4e44-a8ac-7e116de9e205', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is it important for distributed services to implement circuit breakers?', N'Senior', N'Circuit breakers prevent a service from repeatedly trying an operation that is likely to fail, giving the downstream system time to recover. By failing fast, they protect resources and prevent the propagation of latency across the entire distributed call chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'872ba9f5-cb86-450a-ac7f-7e119e324bec', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why should you avoid over-engineering a solution when a simple one works?', N'Fresher', N'Over-engineering adds unnecessary complexity, which makes the system harder to maintain and test. A simple solution is usually faster to implement, easier to debug, and satisfies the current requirements effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d236f92-46f1-491a-a529-7e160d48633e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s ''Abort'' function affect the middleware chain?', N'Middle', N'The Abort function prevents subsequent handlers in the chain from executing by setting an index value that exceeds the length of the handler stack. This is typically used for authentication or authorization checks where a request should be terminated early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f61b4118-8de7-4d4e-a70a-7e19a4989cd7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the scalability limitations of Vite in extremely large monorepos?', N'Senior', N'In extremely large projects, the browser''s ability to handle the sheer number of individual ESM requests can become a bottleneck. While Vite''s pre-bundling helps, developers may eventually need to implement strategies like micro-frontends or module federation to manage the scale of the dependency graph effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'172f0b5d-06d3-44ae-93ab-7e19c47ea499', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Handler'' in Actix?', N'Intern', N'A handler is a function or a method that is responsible for processing a specific HTTP request. When a request matches a defined route, the associated handler is executed to produce the corresponding response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77db91c7-0cd3-48a8-bc15-7e19d0774661', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is ''Soft State'' in the BASE model?', N'Intern', N'Soft state means the state of the database may change over time, even without new input, due to the eventual consistency model. It reflects the idea that the system does not always have to be in a fixed, final state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b9309b-8154-47c0-a04f-7e1db1ae134a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the significance of the Webpack ''Runtime'' in the generated bundle?', N'Senior', N'The runtime contains the code Webpack uses to manage module loading, chunk resolution, and state between modules. It is the ''glue'' that allows the bundle to function within the browser, and its size can become non-trivial in very complex dependency graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff876cf2-89b0-4e90-9c2e-7e21bdc2bf97', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''Copy-and-Swap'' idiom and why is it preferred?', N'Senior', N'The copy-and-swap idiom provides strong exception safety by performing the potentially throwing allocation first and then swapping the internal state with a temporary object. This ensures that if an operation fails, the original object remains in a valid, unmodified state, effectively achieving an atomic update pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25bd1348-2fe5-4867-97e1-7e24e88285c6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How can you optimize Webpack build performance for large projects?', N'Middle', N'You can improve build performance by using persistent caching, limiting the number of files processed with ''include/exclude'' rules, using faster source map options, and running heavy tasks in parallel using thread-loader. Additionally, minimizing the use of unnecessary plugins helps reduce the overall overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55ccba2-fb6b-40d4-987a-7e26c2003460', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the trade-offs of using ''lock'' versus ''ReaderWriterLockSlim''?', N'Middle', N'The ''lock'' statement is simple and efficient for exclusive access but permits only one thread to read or write. ''ReaderWriterLockSlim'' allows multiple concurrent readers while maintaining exclusive access for writers, which can significantly improve performance in read-heavy scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6112a588-a9f1-4b25-8c2a-7e28088d2372', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with a system bottleneck, what is your systematic approach to identifying the root cause?', N'Middle', N'I start by establishing a baseline using monitoring tools to identify which component shows resource spikes. I then isolate the variable by testing the component in a controlled environment to verify if the throughput limit is caused by CPU, I/O, memory, or network latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf3683e6-2e8c-40fb-aa53-7e28533ead43', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s AOT compilation differ from JIT compilation in terms of deployment?', N'Middle', N'JIT compilation is used during development to enable fast iteration through hot reload by compiling code on the fly. AOT compilation is used for production, creating machine-specific native binaries that start up quickly and offer predictable performance without needing a virtual machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89eca46c-10b6-4935-a0f4-7e29184d0dd9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary purpose of SvelteKit in the context of frontend development?', N'Fresher', N'SvelteKit is a full-stack framework built on top of Svelte that simplifies building web applications by providing routing, server-side rendering, and static site generation. It handles the complex infrastructure required for modern web apps, allowing developers to focus on building UI components. By using a file-based routing system, it streamlines the process of navigating between pages and managing data loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'257beaaa-47b0-413c-9425-7e2986fb7b22', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is a ''write-through'' bottleneck?', N'Middle', N'A write-through bottleneck occurs when the throughput of the entire system is limited by the write speed of the slowest component, which is typically the persistent database. Because every write must wait for both the cache and the database to complete, high write volumes can cause significant latency spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de682382-920f-46e9-8fba-7e2be5b0a034', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the .NET Just-In-Time (JIT) compiler differentiate between Tier 0 and Tier 1 compilation?', N'Senior', N'Tier 0 compilation quickly generates unoptimized machine code to reduce startup latency, while Tier 1 compilation performs profile-guided optimization on frequently executed methods. This tiered strategy balances immediate execution performance with long-term throughput efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38fdf81b-8d29-4ace-9a36-7e2c0277d6ad', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you handle the trade-offs between synchronous and asynchronous replication in a distributed database?', N'Senior', N'Synchronous replication guarantees strong consistency by ensuring all replicas acknowledge a write, but it increases latency and reduces availability if a node fails. Asynchronous replication provides higher throughput and lower latency at the cost of potential data loss during a failover, creating a window for stale reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'000afe0a-b619-447e-845d-7e34d6f57d75', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust ensure thread safety in concurrent programming?', N'Middle', N'Rust uses its type system to prevent data races by enforcing that data shared between threads must implement the Sync trait. Combined with ownership, this ensures that mutable access to shared data is synchronized, preventing multiple threads from modifying memory simultaneously without protection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b30a0f8-8872-49e8-9ab0-7e35d0b28c72', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s update lifecycle handle performance optimization when multiple properties change simultaneously?', N'Senior', N'Lit uses an asynchronous batching mechanism to perform updates. When multiple reactive properties change, the update cycle is scheduled to run once in the next microtask, preventing redundant renders and ensuring that the component only reflects the final state after all synchronous property mutations have completed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'916fefa6-b1b6-476f-b9da-7e360bba6479', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the advantage of using Hono on the Edge?', N'Junior', N'Deploying Hono on the edge means your code runs closer to the end user geographically, which significantly reduces latency. Because Hono is lightweight and cold-start optimized, it performs exceptionally well in serverless edge environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0dd7d74-ffe2-4f37-a32c-7e3811dc3666', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Discuss the implications of R''s single-threaded nature on parallelization architecture.', N'Senior', N'R''s base execution is single-threaded, meaning parallelism must be achieved via multi-processing rather than multi-threading. This necessitates significant data serialization overhead when distributing tasks across cores, as each process requires its own memory space and copy of the environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc78121f-91f7-4d33-b4c0-7e38790c476a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to define viewport metadata for responsive design?', N'Senior', N'The viewport meta tag instructs mobile browsers to scale the page to the device''s physical width rather than the default desktop width. Without it, the browser may render the page at a fixed width and zoom out, leading to poor legibility and forcing users to pinch-and-zoom to interact with content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39a286c1-98c7-4ae5-9aab-7e395de0ff28', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''clean'' option in Webpack output?', N'Fresher', N'When enabled, the clean option automatically deletes the contents of the output directory before a new build starts. This ensures that old, unused files do not persist in your build folder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58163c43-1d7a-4776-b207-7e3c2e0da784', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the advantage of Hono''s validator middleware?', N'Middle', N'Hono''s validator middleware allows for lightweight runtime validation of request data, such as body and query parameters. By integrating with libraries like Zod or Valibot, it enforces strict data contracts, preventing malformed data from reaching business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e47c378-331b-401c-93a7-7e3ed6ce3381', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the Tower ecosystem in Axum?', N'Intern', N'Tower provides a set of modular components called Services and Layers that allow developers to handle requests and responses in a pipeline. Axum uses these abstractions to implement features like timeouts, rate limiting, and request tracing in a reusable way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'281c6348-994a-45af-8f9a-7e3f66a131ea', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the primary role of an API Gateway in a microservices architecture regarding scalability?', N'Senior', N'An API Gateway acts as a centralized entry point that handles cross-cutting concerns like SSL termination, rate limiting, and request routing. By offloading these tasks from individual services, it allows each microservice to scale independently based on specific demand while protecting backend resources from traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a0ead4e-d558-4c1c-8e28-7e43d724c0bc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between an ''Addr'' and an ''Address'' in Actix?', N'Middle', N'In Actix, ''Addr'' is the handle used to send messages to an actor. It abstracts the communication channel, allowing you to send messages without needing direct access to the actor instance itself, thus maintaining encapsulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76621153-1559-4d01-a785-7e47325b6de1', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the significance of ''Eventual Consistency'' for system design?', N'Senior', N'Eventual consistency acknowledges that in a distributed system, it may take time for all nodes to reflect the same data state. Designing for this requires handling conflicts and ensuring that the application logic can tolerate stale data temporarily to achieve high availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'062eb5fe-eb92-4215-8a40-7e4840f7b315', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React handle the priority of updates in the event system?', N'Senior', N'React uses a discrete and continuous event model to assign priorities to updates. User-driven events like clicks are high priority, while background tasks or data fetching updates are assigned lower priority, allowing React to schedule them according to the current frame budget.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa6accc4-a736-431e-a670-7e4cb17a77b0', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of request and response encapsulation in Fastify?', N'Middle', N'Encapsulation ensures that plugins and their registered hooks, decorators, and routes do not leak into parent contexts. This allows developers to create modular, side-effect-free components that can be safely reused throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd6d263e-c721-4c99-aefd-7e5042b8155e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for handling configuration management across multiple environments?', N'Middle', N'I use environment variables or centralized configuration services to decouple configuration from the application code. This ensures that the same binary can be deployed across environments without modification, reducing the risk of configuration drift. I also use secrets management tools to securely handle sensitive information like API keys and credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
