INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20a79b6d-22ff-4ec9-b781-7e554afcae48', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does ''Availability'' mean in the CAP theorem?', N'Junior', N'Availability means that every request made to the database system receives a non-error response, regardless of the state of individual nodes. In a highly available system, the database remains operational and responsive even if some components experience hardware or network failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
