INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c65f640e-737d-43e8-8851-7e55ccc469a4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Discuss the performance implications of Hono’s zero-dependency design in serverless environments.', N'Senior', N'The zero-dependency approach ensures that the framework''s cold start time remains negligible, as there are no heavy internal libraries or complex dependency trees to initialize. In serverless environments where execution duration and startup latency are billed directly, this lean footprint provides a significant competitive advantage over frameworks that rely on large Node.js-centric ecosystems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
