INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b58cef56-9c3e-42e1-9250-7e5dd37fa679', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why are stateless services easier to scale than stateful services?', N'Middle', N'Stateless services do not store client session data locally, meaning any request can be handled by any instance in a cluster. This flexibility allows load balancers to distribute traffic freely and enables the system to scale instances up or down without worrying about data synchronization or session loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
