INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'945f9218-73a6-46ac-825b-7e62bb7be30f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is flux?', N'Intern', N'Flux is an application architecture (not a framework or library) designed by Facebook to manage data flow in React applications. It was created as an alternative to the traditional MVC (Model-View-Controller) pattern, and it emphasizes a unidirectional data flow to make state changes more predictable and easier to debug. Flux complements React by organizing the way data moves through your application, especially in large-scale or complex projects. Core Concepts of Flux Flux operates using four key components, each with a specific responsibility: * Actions * Plain JavaScript objects or functions that describe _what happened_ (e.g., user interactions or API responses).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f40d7e2d-8e33-49e0-a572-7e6399fe57c2', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a crate and a module?', N'Intern', N'A crate is the smallest amount of code that the Rust compiler considers at one time, usually a library or an executable. A module is a way to organize code within a crate into smaller, manageable units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8c69f86-37ae-4396-843e-7e66e6205d0d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating the effort for a complex migration, how do you account for ''unknown unknowns''?', N'Senior', N'I apply a risk-adjusted estimation technique, such as the PERT (Program Evaluation and Review Technique), which incorporates optimistic, pessimistic, and most likely scenarios. Additionally, I mandate a discovery phase or a technical spike to reduce the uncertainty surface area before committing to a final delivery timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'152a6077-700a-425c-b038-7e67fce8a7fc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do ''Future'' return types in Actix handlers influence system throughput?', N'Senior', N'Returning Futures allows the handler to yield execution back to the runtime while waiting for IO. This maximizes thread utilization by allowing the event loop to process other requests instead of idling during network or disk latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15a73265-77fa-4798-b96b-7e685ba99902', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of using Redis as a message broker?', N'Fresher', N'Using Redis as a message broker allows for asynchronous communication between different parts of a system. It is very fast and easy to set up for simple queuing requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46fcf8f-fe97-400c-a01c-7e69f1a6c3f5', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the risks of ''at-least-once'' delivery, and how do you handle them?', N'Senior', N'At-least-once delivery guarantees that no message is lost but risks processing the same message multiple times if acknowledgements fail or network retries occur. This is mitigated by designing idempotent consumer logic, which checks the state of the system before applying any changes to ensure duplicate messages have no side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c0b3352-76dc-4e38-bcb1-7e6c772e3182', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Describe the difference between ''Configuration'' and ''Extension'' classes in Symfony Bundle development.', N'Senior', N'The Configuration class defines the structure and validation rules for the bundle''s configuration file, while the Extension class is responsible for loading the configuration and registering services into the container. The Extension acts as the bridge that translates user-provided configuration values into actionable service definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ac4ce63-3728-4d98-9890-7e6d89b7b14a', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the trade-off between throughput and durability in a distributed messaging system?', N'Middle', N'Higher durability usually requires synchronous disk writes or replication across nodes, which increases latency and reduces throughput. Optimizing for throughput often involves asynchronous acknowledgment or batching, which increases the risk of data loss in the event of a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'920e4f4c-3341-4891-b018-7e6e6a2485b0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary difference between Remix''s loaders and client-side data fetching?', N'Junior', N'Remix loaders execute exclusively on the server before the page renders, ensuring data is available immediately when the component mounts. This eliminates the need for loading states or request waterfalls often associated with fetching data on the client side after the page has loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25fedc3a-f398-4a66-8adf-7e6e6cd0eae1', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle event delegation?', N'Junior', N'SolidJS uses a global event delegation system where events are attached to the document root rather than individual elements. This improves performance by reducing the number of event listeners attached to the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3af69bdb-b683-402f-82d8-7e6f67682a1e', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of a message partition in a system like Apache Kafka?', N'Middle', N'Partitions allow a topic to be split across multiple nodes, enabling horizontal scalability and parallel processing. They ensure that messages are distributed among consumer group members, significantly increasing the total throughput of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'859af6bf-0109-468a-be4a-7e7169a14fa8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between consistency and availability in distributed systems?', N'Intern', N'This is defined by the CAP theorem, which suggests you cannot guarantee both perfect data consistency and 100 percent system availability during a network partition. You must choose based on whether your application can tolerate slightly stale data or needs to be constantly reachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24fdee54-53f3-4195-8ee8-7e71e78c49d6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the architectural difference between ''Action Filters'' and ''Result Filters'' in the MVC pipeline.', N'Senior', N'Action filters execute immediately before and after an action method is invoked, allowing for parameter manipulation or result interception. Result filters execute only after the action method has returned an action result, making them ideal for post-processing the output, such as modifying the HTTP response body or headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccffb8b2-7e78-4e4d-9718-7e71ee9e8a6c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does it mean to ''refactor'' a process or system?', N'Intern', N'Refactoring means improving the internal structure or efficiency of a system without changing its external behavior. It is done to make the system easier to maintain, faster, or more organized. The goal is to clean up technical debt and make future changes less risky.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a7ae16e-b252-47c4-86a2-7e72688339b7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a commit operation?', N'Fresher', N'A commit is a command that saves all the changes made during the current transaction to the database permanently. Once committed, the changes become visible to other users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8d32eef-6fa0-4531-8a58-7e75c393fb9f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Does Actix-web use a garbage collector?', N'Fresher', N'No, Actix-web does not use a garbage collector. It relies on Rust''s ownership and borrowing rules to manage memory, ensuring high performance and predictability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c75bac85-3ebc-4f22-adec-7e7974487fb8', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a ''layout'' in SvelteKit?', N'Intern', N'A layout is a wrapper component that allows you to share common UI elements across multiple pages. By nesting layouts, you can create complex application structures where different sections of your app have their own specific headers or sidebars.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e42c1d06-a305-4689-a9aa-7e7ca933f17e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is it generally recommended to avoid growing objects in a loop in R?', N'Middle', N'In R, growing an object inside a loop triggers a memory reallocation for the entire object at each iteration because objects are immutable. This leads to quadratic time complexity, making the process extremely slow for large datasets; pre-allocating memory is the standard performance optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdb3847d-5937-485e-9145-7e7d0309a443', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to use ''viewport'' meta tags for accessibility?', N'Middle', N'While primarily for responsive design, the viewport tag ensures that text and elements are legible on mobile devices without requiring excessive zooming. If a user is forced to zoom and pan horizontally to read content, it creates an accessibility barrier for users with motor impairments or visual disabilities. Ensuring content fits the viewport is essential for a consistent experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da6dfb7a-d589-41b8-9f3f-7e7ea113472c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''use cache'' directive in modern Next.js applications?', N'Senior', N'The ''use cache'' directive enables fine-grained data caching for functions, allowing developers to cache specific data fetches or expensive computations across requests. This provides a declarative way to manage cache invalidation and reuse, reducing redundant computation and database load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c01297af-48a8-4713-b5e7-7e7f6bd07164', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve lower memory consumption compared to traditional frameworks like Spring Boot?', N'Senior', N'Micronaut moves framework infrastructure logic from runtime to compile-time using annotation processors. By generating bean definitions, dependency injection metadata, and AOP proxies at build time, it avoids heavy reflection and dynamic classpath scanning during startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
