INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71e864bc-d9f6-4300-b89e-7e85ddc76388', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB achieve high availability?', N'Intern', N'DynamoDB automatically replicates data across multiple geographically distributed availability zones within an AWS region. This ensures that data remains accessible even if one physical data center fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a027d506-f865-4392-8326-7e860f42ac4d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach debugging a bug that is difficult to reproduce?', N'Fresher', N'I would start by gathering as much context as possible, such as the user''s actions, timestamps, and browser or device logs. I would then try to isolate the issue by stripping away variables until the behavior becomes consistent. If reproduction remains difficult, I would add detailed logging to the production environment to track the application state when the event occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d079600-a862-45d8-96b2-7e8621713ef8', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the role of the ''Repository Pattern'' in a Laravel application and if it is always necessary.', N'Senior', N'The Repository pattern abstracts data access to separate the business logic from the persistence layer, which is useful for complex applications requiring multiple data sources. It is often unnecessary for simple CRUD apps, where Eloquent''s active record pattern is sufficient and less verbose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'114ab07b-c56a-4a7c-bff0-7e8a18cbbb10', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Discuss the implications of ''Multi-tenancy'' in a NoSQL database cluster.', N'Senior', N'Multi-tenancy allows multiple customers to share the same infrastructure, which improves resource utilization and cost-efficiency. However, it introduces risks of ''noisy neighbor'' effects, where one tenant''s heavy workload impacts the performance of others, requiring robust resource isolation and rate-limiting controls at the database level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e43cd46c-a3e6-4aab-91a5-7e8aa3013a30', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary purpose of Go''s garbage collector?', N'Intern', N'The garbage collector automatically manages memory by identifying and freeing objects that are no longer reachable in the program. This helps prevent memory leaks and reduces the burden on developers to manually allocate and deallocate memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
