INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b397faf-4550-4578-80a9-7e8e9fb7cabb', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle memory management without a garbage collector?', N'Fresher', N'Rust manages memory through a system of ownership with a set of rules that the compiler checks. When a variable goes out of scope, the memory it owns is automatically deallocated, making the process deterministic and efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14a00098-a5ff-4b90-b1c0-7e8f3c13cbfa', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the architectural benefits of using NestJS microservices with a message broker like RabbitMQ.', N'Senior', N'Using a message broker decouples service communication, enabling asynchronous processing and better fault tolerance through retries and dead-letter queues. NestJS simplifies this by abstracting the transport logic, allowing the business logic to remain agnostic of whether it is communicating via HTTP or a message bus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
