INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'902f7fdf-601d-4a16-bc7b-7e96481a2e5e', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the ''manage.py'' script?', N'Intern', N'The manage.py file is a command-line utility that lets you interact with your Django project in various ways. You use it to run the development server, create database migrations, start new apps, and manage user accounts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ee6ba1e-16f2-416c-bbc3-7e9878b280df', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do you define a constant in Go?', N'Intern', N'Constants are defined using the ''const'' keyword. They represent fixed values that are determined at compile time and cannot be changed during program execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2e7356-731d-4009-8c37-7e99bee03a1f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React Fiber and how is it an improvement over the previous approach?', N'Intern', N'React Fiber is a complete rewrite of React''s reconciliation algorithm, introduced in React 16. It improves the rendering process by breaking down rendering work into smaller units, allowing React to pause and resume work, which makes the UI more responsive. This approach enables features like time slicing and suspense, which were not possible with the previous stack-based algorithm. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70b03357-4281-437c-97da-7e9ac2bb9241', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do R''s internal data structures handle memory fragmentation during high-frequency allocation?', N'Senior', N'R''s heap management can suffer from fragmentation when large objects are frequently created and destroyed, as the memory allocator may struggle to find contiguous blocks. This often requires manual intervention through garbage collection triggers or the use of pre-allocated buffers to maintain performance in memory-intensive data science pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39095504-7115-4885-b9ed-7e9b853cbe55', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a server is running out of memory, what is the first conceptual step you would take to identify the cause?', N'Intern', N'The first step is to examine system logs and resource monitoring tools to determine which processes are consuming the most RAM. This helps distinguish between a memory leak in a specific application and an overall lack of hardware capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f7e6ffa-6562-4623-bd74-7e9bb6c37585', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle high-concurrency updates to the same document?', N'Senior', N'Elasticsearch uses optimistic concurrency control via the ''_seq_no'' and ''_primary_term'' metadata fields. When an update request is sent, the engine compares the version in the request with the version currently stored; if they do not match, the update is rejected, preventing race conditions without using expensive locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cdf6306-9c12-4feb-96a4-7e9fbb1c0ea2', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is an inverted index?', N'Intern', N'An inverted index is the core data structure used by Elasticsearch to allow for full-text searches. It maps unique terms to the list of documents that contain them, allowing for fast lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ba34701-1416-4b7b-a168-7ea188cfb19e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a Redux slice?', N'Intern', N'A slice is a collection of Redux reducer logic and actions for a single feature of the app. It helps organize the codebase by grouping related state management logic together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48365f92-04c9-42eb-b064-7ea1c4a658c8', N'954a0331-deff-4399-b588-96f39fec001d', N'Why is ''Ahead-of-Time'' (AOT) compilation superior to ''Just-in-Time'' (JIT) for production environments?', N'Senior', N'AOT compiles templates at build time, resulting in smaller bundles, faster rendering, and the ability to detect template errors before deployment. JIT compiles the application in the browser, which increases the initial download size and adds runtime latency to the startup process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29fdd5c9-7aec-4397-aa7d-7ea3272ede30', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Phoenix Controller?', N'Intern', N'A controller is a module responsible for handling incoming web requests. It processes the request, communicates with the data layer, and determines what response to send back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91f6301c-d60a-4c22-a3a6-7ea33df08097', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you notice that a task is going to take significantly longer than your original estimate, what is your next step?', N'Fresher', N'I would immediately analyze why the task is taking longer, identifying the specific obstacles or complexities encountered. Then, I would communicate this information to my manager or team lead as early as possible, providing an updated estimate and explaining the reasons for the change. Proactive communication helps the team adjust plans and manage dependencies effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c5101f8-b8d7-4797-b26f-7ea86458c810', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between ''new'' and ''malloc''?', N'Fresher', N'The new operator is a language-specific feature that allocates memory and automatically calls the object''s constructor, while malloc is a library function that only allocates raw memory. Furthermore, new is type-safe and returns the correct pointer type, whereas malloc returns a void pointer that must be manually cast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31013914-55e7-49b1-bc08-7ea9b6492704', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between ''SyncActor'' and ''Actor''?', N'Junior', N'A standard Actor runs on an asynchronous event loop and must not perform blocking operations. A SyncActor is designed to run in a separate thread pool, allowing it to perform blocking operations without stalling the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d6b56ab-6633-4fb5-b8cb-7eaa27b620e6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between find and aggregate?', N'Intern', N'The find operation is used for basic querying and filtering of documents. The aggregation framework is more complex and allows for advanced data processing, such as grouping, sorting, and computing multi-document results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0bfd6c7-f001-45ab-bfb7-7eaae605cafc', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the possible ways to apply CSS styles to a web page?', N'Intern', N'There are three ways to apply CSS to HTML: Inline, internal, and external. 1. Inline CSS: Inline CSS is specified directly in the opening tag of the element you want it to apply to. It is entered into the style attribute within HTML. This allows CSS properties on a "per tag" basis. Example: This CSS type is not really recommended, as each HTML tag needs to be styled individually. However, inline CSS in HTML can be useful in some situations. For example, in cases where you don''t have access to CSS files or need to apply styles for a single element only. 2. Internal CSS: Internal or Embedded, styles are used for the whole page. Inside the head element, the style tags surround all of the styles for the page. Example: This CSS style is an effective method of styling a single page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c60d34f-ad7f-4448-959b-7eab5458a943', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik require client-side hydration?', N'Fresher', N'No, Qwik does not perform traditional hydration. Because the server serializes the component state and the structure into the HTML, the client does not need to re-render the entire component tree to make the page interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b69068ff-7541-4fef-bcb7-7eb141debf24', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite require a separate server for production?', N'Fresher', N'Vite itself is a build tool, not a production server. In production, you typically host the static files generated in the ''dist'' folder using any standard web server like Nginx, Apache, or a hosting service like Netlify or Vercel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e4236b4-8020-46d2-9330-7eb5a067dde5', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the benefit of using ''preact-render-to-string'' for static site generation.', N'Senior', N'This utility allows developers to render Preact components to static HTML, which is essential for SEO and initial load performance. It produces standard HTML strings that can be served directly by a web server, allowing for faster content delivery and improved accessibility for crawlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50654f73-789e-4ff8-8bd2-7eb5ac1c9982', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe the mechanism behind Rails'' multi-database support and how it affects connection pooling and transaction isolation.', N'Senior', N'Rails uses multiple database configurations and connection handlers to route queries to different shards or replicas. This requires careful management of connection pools to avoid exhaustion and necessitates distributed transaction handling strategies, as standard ACID transactions cannot span multiple physical database instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adaadefd-7474-4d27-9c6e-7eb7694478f0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the function of the & character in Sass?', N'Intern', N'The ampersand symbol is used during nesting to refer to the parent selector. It is commonly used for pseudo-classes like hover states or for modifying class names based on their parent context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6314b086-14fe-4f21-b41d-7eb7ebb07cd4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does ''reified'' type parameter work in Kotlin?', N'Middle', N'Normally, generic type information is erased at runtime, making it impossible to check the type of a generic parameter. By marking a type parameter as ''reified'' in an inline function, the compiler makes the type information available at runtime, allowing you to perform checks like ''is'' or cast to that type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7321d5af-4d17-4570-964e-7eb8c389d3af', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is a readable store in Svelte?', N'Fresher', N'A readable store is a store whose value cannot be set from outside the store itself. It is useful for data that is controlled by the store''s internal logic, such as a timer or a sensor, where the component should only be able to read the value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
