INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59a69d58-c6d8-4043-8005-7ebc0bd6aac5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the distinction between internal and external linkage, and why does it matter for system architecture?', N'Senior', N'Internal linkage limits symbol visibility to the current translation unit, effectively providing a mechanism for information hiding and preventing name collisions in large codebases. External linkage allows symbols to be shared across the entire program, which is necessary for modular architecture but requires careful management of header files and namespaces. Proper use of the static keyword for internal linkage is critical for reducing binary size and improving link-time performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2b5962c-4d93-4141-a44e-7ebe7c6cd1b8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the ''ref'' attribute work in SolidJS?', N'Junior', N'The ref attribute provides a way to get a direct reference to a DOM element after it has been created. You pass a variable or a function to receive the element, allowing you to perform manual DOM manipulations that are not handled by the reactive system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4930c5d-453f-4e77-bf3f-7ebea19af99c', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the various security contexts in Angular?', N'Fresher', N'Angular defines the following security contexts for sanitization, 1. HTML: It is used when interpreting a value as HTML such as binding to innerHtml. 2. Style: It is used when binding CSS into the style property. 3. URL: It is used for URL properties such as . 4. Resource URL: It is a URL that will be loaded and executed as code such as .', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e37b526-2d5b-4124-8f00-7ebed5f64153', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a caching layer versus optimizing the database queries?', N'Junior', N'You should first optimize database queries to ensure they are efficient and indexed correctly. If performance issues persist despite optimization, adding a caching layer is a great way to reduce database load for frequently accessed, read-heavy data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd73e9b08-6ad0-45a5-ba62-7ec394aecba5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'If you must choose between speed of development and system scalability, how do you decide?', N'Intern', N'I would analyze the project phase; a prototype might prioritize speed to validate an idea quickly, while a production-ready system requires scalability. The decision depends on the current business risk and long-term project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27f3578f-34f4-4426-a4a9-7ec490a13263', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role of the ExecutionContext in NestJS.', N'Middle', N'The ExecutionContext provides access to the current request and response objects, as well as the class and method being invoked. It is essential for guards, interceptors, and filters to inspect the context and apply logic based on the specific handler being executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad9dd88e-49a9-4f9d-acfc-7ecbb5f865aa', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the advantages of Go''s approach to error handling compared to exception-based models?', N'Middle', N'Go treats errors as explicit return values, forcing developers to acknowledge and handle failure states immediately. Unlike exceptions, which can jump across long distances and create hidden control flow paths, Go''s approach makes error handling visible and encourages robust, localized recovery strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd222d53e-c064-4b03-af63-7ecd3ebd5723', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the Ember Inspector?', N'Intern', N'The Ember Inspector is a browser extension tool that helps developers debug their applications. It allows users to view the current state of models, components, routes, and services in real-time within the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f8e6a27-957f-4b55-b3f1-7ecd85645d4e', N'954a0331-deff-4399-b588-96f39fec001d', N'What are Pipes in Angular?', N'Junior', N'Pipes are simple functions used in template expressions to transform data for display. They take an input value and return a transformed version, such as formatting a date, currency, or changing a string to uppercase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00b4253d-b51a-4351-b089-7ecfa67efe63', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the .env file used for in a Laravel project?', N'Intern', N'The .env file is used to store environment-specific configuration variables, such as database credentials, API keys, and application debug settings. It keeps sensitive information separate from the application code, ensuring that different settings can be used for local development versus production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9142ea3-a1ca-4b8c-9a03-7ed754e84069', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Services in Ember, and when should you use them?', N'Junior', N'Services are long-lived singleton objects that exist for the duration of the application. They are used to share state or functionality across multiple parts of the app, such as authentication status, user preferences, or shopping cart data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89a23ae2-09fe-400c-ac1c-7ed77b4ef1c0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Discuss the trade-offs of using Echo''s built-in ''Recover'' middleware in a production environment.', N'Senior', N'The Recover middleware is essential for preventing server crashes from panics, but it should be configured to log errors appropriately to an observability platform. Relying solely on it without proper application-level error handling can hide critical bugs and lead to inconsistent state if a panic occurs mid-transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0127427c-5f6e-4ba5-bf0d-7ed97de8eaba', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using ''Ecto Multi'' for database transactions?', N'Middle', N'Ecto Multi allows you to compose multiple database operations into a single transactional sequence. It provides a clean way to handle complex business logic where multiple records must be created or updated atomically, ensuring that if any step fails, the entire transaction is rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2f08a94-a3e4-445c-b697-7edaa2ece30c', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the caveats of array changes detection?', N'Intern', N'Vue cannot detect changes for the array in the below two cases, 1. When you directly set an item with the index,For example, 2. When you modify the length of the array, For example, You can overcome both the caveats using set and splice methods, Let''s see the solutions with an examples, First use case solution Second use case solution', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b76197b-bf41-46c9-8f79-7edca7f76173', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Compare Hono''s ''Honox'' meta-framework approach to traditional SSR frameworks.', N'Senior', N'Honox focuses on ''Islands Architecture'' to minimize hydration overhead by shipping minimal JavaScript to the client. Unlike frameworks that hydrate the entire DOM, Honox targets specific interactive components, drastically improving Time to Interactive on low-power devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9685ac60-57e3-4e3b-afc8-7edcd06055e8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is destructuring aliases', N'Intern', N'Sometimes you would like to have a destructured variable with a different name than the property name. In that case, you''ll use a : newName to specify a name for the variable. This process is called destructuring aliases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25533b62-a0a6-47fc-9ae2-7ee1390dcf18', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do stateless services facilitate horizontal scaling?', N'Senior', N'Stateless services do not store client-specific session data locally, allowing any request to be routed to any instance of the service. This makes it trivial to add or remove nodes behind a load balancer without affecting the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5df666bc-8a6c-4dd6-acc3-7ee16b414279', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s approach to development differ from traditional bundlers like Webpack?', N'Fresher', N'Traditional bundlers like Webpack bundle the entire application before starting the server, which can be slow. Vite serves source files over native ES modules, meaning it only transforms and serves the files you are currently editing, resulting in near-instant server start times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b62a794f-7824-4163-9a69-7ee3568b704b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo support clean architecture through its handler interface?', N'Senior', N'By defining handlers as functions that accept the Echo context and return an error, the framework forces a separation between the HTTP transport layer and the core business logic. This allows developers to port business logic to other transport mechanisms easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3232193d-4fbb-4e6e-8fee-7ee6668aee21', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''noImplicitAny'' flag enforce architectural consistency in a large codebase?', N'Senior', N'By forcing developers to explicitly annotate types for all function parameters and variables, this flag prevents the ''any'' type from silently propagating through the system. It ensures that the dependency graph remains fully transparent and that type contracts are documented at every boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a51cb472-72ba-46d1-8c45-7ee74620c66d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are given a task with ambiguous requirements, how do you provide an estimate?', N'Fresher', N'I would first ask clarifying questions to resolve the ambiguity and define the scope as clearly as possible. If the requirements remain uncertain, I would provide an estimate based on the most likely scenario while documenting the assumptions made. I would also suggest a phased approach, where the estimate is refined as the requirements become more concrete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
