INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'230981b6-170a-4a6b-ba51-7ee9a3a4fc87', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why would a developer choose Preact over React for a mobile-focused application?', N'Junior', N'Preact is often preferred for mobile applications because its small bundle size results in faster download and parse times. This provides a better user experience on slower network connections and devices with limited resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'310bf211-dcc9-4ca6-8af1-7eea450a641b', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you handle ''Clock Skew'' in distributed systems during transaction ordering?', N'Senior', N'Physical clocks can never be perfectly synchronized across distributed nodes, making them unreliable for ordering events. Instead, systems use logical clocks, such as Lamport timestamps or Vector clocks, to maintain a causal ordering of events regardless of the underlying hardware clock.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1a27858-ba05-4312-9fbb-7ef171f325e7', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is FastAPI considered ''type-hint'' based?', N'Junior', N'FastAPI leverages Python''s type hints to perform data validation, serialization, and automatic documentation generation. By specifying types for parameters and return values, the framework understands exactly what data to expect and how to format the output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd57efa28-e1c1-4e8f-9e44-7ef262742edb', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a server is running out of disk space, what is your step-by-step approach to identifying the culprit?', N'Intern', N'First, I would use system utilities to identify which directories or partitions are consuming the most space. Then, I would look for large log files, temporary directories, or redundant backups that can be safely cleared. Finally, I would analyze the growth patterns to determine if I need to expand storage or implement an automated cleanup policy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'304afba9-ac50-4523-9856-7ef3ff1e7db7', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Interceptors in NestJS?', N'Intern', N'Interceptors are used to bind extra logic before or after method execution. They can transform the result returned from a function, transform the exception thrown, or extend the basic function behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d173815-b177-4689-aeb4-7ef9a0b29c41', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does multi-master replication differ from master-slave in terms of consistency?', N'Senior', N'Multi-master replication allows writes to any node, which increases write availability and performance but creates significant challenges with conflict resolution and write amplification. It typically requires conflict detection mechanisms like vector clocks or last-write-wins policies, often resulting in weaker consistency guarantees compared to master-slave setups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d6a783e-c3d6-4952-bcf2-7efa2d983e4e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the role of cache invalidation in microservices.', N'Middle', N'Cache invalidation ensures that when data changes in one service, the corresponding cached representations in other services are purged or updated. This is critical for maintaining consistency in loosely coupled systems where multiple services may share data dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ed5897c-b3b2-4d2e-8fcf-7efa76bdccbf', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Twig and why is it used in Symfony?', N'Junior', N'Twig is a flexible and secure template engine for PHP that separates presentation logic from business logic. It provides a clean, readable syntax for rendering HTML and prevents common security issues like cross-site scripting through automatic output escaping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cedee29-dc4a-414a-8a1f-7efcfaf1bcef', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between Imperative and Declarative in React?', N'Fresher', N'Imagine a simple UI component, such as a "Like" button. When you tap it, it turns blue if it was previously grey, and grey if it was previously blue. The imperative way of doing this would be: Basically, you have to check what is currently on the screen and handle all the changes necessary to redraw it with the current state, including undoing the changes from the previous state. You can imagine how complex this could be in a real-world scenario. In contrast, the declarative approach would be: Because the declarative approach separates concerns, this part of it only needs to handle how the UI should look in a specific state, and is therefore much simpler to understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4396904a-2539-4085-a0dc-7f036ef0d5de', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''IEnumerable'' and ''IQueryable'' in the context of LINQ?', N'Middle', N'IEnumerable executes the query in-memory after fetching the data from the source, making it suitable for local collections. IQueryable allows the query to be translated into an expression tree, enabling execution directly on the remote data source like a SQL database, which improves performance by reducing data transfer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c241e73d-2238-4996-99e4-7f0cf475935c', N'954a0331-deff-4399-b588-96f39fec001d', N'What is ng-content and its purpose?', N'Intern', N'The ng-content is used to insert the content dynamically inside the component that helps to increase component reusability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abae174a-24f9-43df-a315-7f0eb2e1350d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the trade-offs between using an API Gateway versus a Service Mesh for cross-cutting concerns?', N'Senior', N'An API Gateway handles external traffic, authentication, and rate limiting at the edge, providing a single entry point. A Service Mesh manages internal service-to-service communication, focusing on mTLS, observability, and traffic routing between microservices within the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57aba23b-5c85-49ab-b4d6-7f1078b947bf', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary architectural benefit of Echo being ''minimalist''?', N'Middle', N'A minimalist framework provides only the essential tools for routing and context management, leaving architectural decisions like database ORMs or validation logic to the developer. This allows for greater flexibility and prevents the framework from enforcing patterns that might not fit specific project requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7766247a-cc72-41c6-9faa-7f1261cf76be', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''Buffer Pool'' influence database performance?', N'Senior', N'The buffer pool is a cache area in memory where data pages are stored after being read from disk. By serving subsequent requests from memory, the database significantly reduces disk I/O latency, making the buffer pool size one of the most critical performance tuning parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90ceee2a-c21b-40ee-8502-7f15985aa3a9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a database index, and what is its primary benefit?', N'Junior', N'An index is a data structure that improves the speed of data retrieval operations on a table. By creating an index on a specific column, the database can quickly locate rows without scanning the entire table, significantly improving query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59e43588-95d9-404e-b017-7f17e6f57a52', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary purpose of a database index?', N'Middle', N'The primary purpose of an index is to speed up data retrieval operations by providing a fast lookup path to specific rows in a table. While indexes significantly improve read performance, they introduce overhead for write operations because the index must be updated whenever the data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb37aa45-9900-4287-abeb-7f19a02b28ce', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the concept of ''Process Monitoring'' in Phoenix and how it contributes to fault tolerance.', N'Senior', N'Processes in Phoenix can monitor or link to other processes; if one process crashes, the other receives a notification, allowing for automatic restarts or graceful cleanup. This ''let it crash'' philosophy, managed by supervisors, ensures that failures are contained and the system can recover to a known good state without human intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eef2ac6-a469-4090-9e0c-7f1a19ea7342', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are Data Classes in Kotlin and why are they used?', N'Junior', N'Data classes are designed specifically to hold data. When you declare one, the compiler automatically generates useful methods like equals, hashCode, and toString based on the properties defined in the primary constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3320898b-8f30-4c1b-85d4-7f1bc09bce44', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between optimizing for database read versus write performance?', N'Senior', N'Optimizing for reads often involves denormalization and secondary indexing, which slows down write operations and increases storage requirements. Optimizing for writes usually involves normalized schemas and minimal indexing, which complicates read queries. My choice depends on the specific workload: if the application is read-heavy, I accept write complexity; if write-heavy, I prioritize write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74931486-7f5f-453d-99b4-7f1e7571921c', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of using the AdonisJS exception handler?', N'Junior', N'The exception handler acts as a centralized location to catch and format errors that occur anywhere in the application. This ensures that the user receives a consistent error response and allows developers to log stack traces without exposing sensitive information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd123347-d9d9-40e9-bf7e-7f2102f73219', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s garbage collector interact with C/C++ extensions?', N'Middle', N'R''s garbage collector tracks R objects, but it is unaware of memory allocated directly in C/C++ via external pointers. Developers must manually manage the lifecycle of these external resources to avoid memory leaks that the R interpreter cannot detect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9492add-8a8d-4f1e-809e-7f21f5a12b63', N'954a0331-deff-4399-b588-96f39fec001d', N'What is metadata or annotation?', N'Intern', N'In Angular, metadata or annotations are used to configure classes, telling Angular how they should be processed, used, or behave. They are attached to classes using decorators, which are special functions prefixed with the @ symbol. For example: - The @Component decorator adds metadata to a class, specifying its selector, template, styles, etc. - The @Injectable decorator adds metadata, indicating that a class can be injected as a dependency. - The @NgModule decorator adds metadata to configure a module, listing its declarations, imports, providers, and bootstrap components. This metadata is crucial for Angular''s compiler and runtime to understand the structure and dependencies of your application. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a7b999d-28cf-4b14-8f8f-7f22c2f49ea2', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the Django Template Inheritance?', N'Fresher', N'Template inheritance allows you to create a base skeleton template that contains common elements like headers and footers. Other templates can then extend this base and override specific blocks of content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf930cb-139a-4a17-83f7-7f22e69d8c43', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach capacity planning for a system expecting a 10x spike in traffic during a seasonal event?', N'Senior', N'I conduct load testing to identify the breaking point of current infrastructure and extrapolate resource needs based on throughput metrics. I then implement auto-scaling policies based on resource utilization and ensure that downstream dependencies have sufficient headroom to handle the projected load increase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb88962c-a283-4d0b-8409-7f237257b7a6', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does microservices decomposition help with scalability?', N'Middle', N'Breaking a monolith into smaller services allows teams to scale specific components independently based on their individual resource needs. It also isolates failures, ensuring that a bottleneck in one part of the system does not bring down the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'697ea6e0-8be1-4842-86ae-7f24f6010285', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens if a request does not match the defined schema?', N'Intern', N'If a request fails validation against the defined JSON schema, Fastify will automatically reject the request and return a 400 Bad Request error. This prevents invalid or malicious data from reaching your application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa7cd615-c6c9-472d-b1eb-7f26ca00abc1', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'When should you consider using a covering index?', N'Middle', N'A covering index is used when all columns required by a query are present within the index itself. This allows the database to retrieve the result directly from the index tree without performing a costly ''bookmark lookup'' to read the actual table data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b88a09c2-863e-4f79-9a12-7f275341dbe2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using a service mesh versus standard load balancing for inter-service communication?', N'Senior', N'A service mesh provides advanced capabilities like mTLS, fine-grained traffic shifting, and observability out of the box, but it adds substantial operational complexity. Standard load balancing is simpler and more performant for basic traffic distribution but lacks the sophisticated control plane required for complex service topologies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91857cf3-566c-4ee1-add2-7f275c050ca1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is DynamoDB''s consistency model?', N'Intern', N'DynamoDB supports both eventually consistent and strongly consistent reads. Eventually consistent reads might return stale data, while strongly consistent reads guarantee the most up-to-date data at the cost of higher latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a2211f8-e116-4a02-b0ad-7f284f9049fe', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the role of the write barrier in Go''s Garbage Collector.', N'Senior', N'The write barrier is a mechanism used during concurrent garbage collection to intercept pointer updates and ensure the GC maintains a consistent view of the heap. It prevents the collector from incorrectly reclaiming objects that are being moved or referenced during the marking phase, ensuring the collector remains correct without stopping the world.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'297bc7fe-ed64-4622-80fe-7f2984f3fac8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Does Litestar support synchronous code?', N'Intern', N'Yes, Litestar supports both synchronous and asynchronous route handlers. While it is designed for asynchronous operations, it can execute synchronous functions in a thread pool to avoid blocking the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ffa62c1-f8b8-4c1e-96be-7f2ae7565552', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Describe the role of ''shadow endpoints'' and how they simplify data flow in SvelteKit.', N'Senior', N'Shadow endpoints allow developers to colocate data-fetching logic directly with the UI component in the same directory. This removes the need for separate API routes or external fetch calls, reducing boilerplate and ensuring that data contracts are tightly coupled to the views that consume them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'796700ca-9d4e-41c9-abd2-7f2c52687c34', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why does Kotlin favor composition over inheritance, and how does the ''open'' modifier enforce this?', N'Senior', N'Kotlin defaults all classes and methods to ''final'' to prevent fragile base class problems and encourage developers to explicitly design for extensibility. By requiring the ''open'' modifier, the language forces a conscious decision to allow inheritance, which favors composition as the default architectural pattern for maintainable systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'772a22ea-6d1e-4076-8abc-7f2d6e29550d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a ''Guard'' in the context of Litestar security?', N'Junior', N'A guard is a callable that receives the request and returns a boolean or raises an exception. It is used to enforce access control rules, such as checking if a user is authenticated or has the required permissions before reaching the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9bfcc27-0f8e-420b-ab7a-7f308031ae2c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of Rollup in Vite''s production build?', N'Junior', N'Vite uses Rollup to perform the final production build because it is highly efficient at bundling and tree-shaking. Rollup ensures that the final JavaScript bundle is as small and performant as possible for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'545ef2ca-9cc3-47af-a4b2-7f30e8e3d9cc', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is a React Server Component?', N'Junior', N'A Server Component is a component that renders exclusively on the server. They reduce the amount of JavaScript sent to the browser because the component logic and dependencies do not need to be downloaded or executed by the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22bc7604-196f-4181-93ce-7f32a81e27bb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the architectural trade-offs of Micronaut''s ahead-of-time (AOT) compilation strategy.', N'Senior', N'The primary trade-off is significantly faster startup times and reduced memory overhead, which is ideal for serverless and containerized environments. However, it increases build times and requires all dependency injection to be resolved statically, which limits the use of highly dynamic runtime bean registration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf5544af-4eec-400a-b68f-7f32c0f2a7b3', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of OPcache in a production PHP environment?', N'Middle', N'OPcache improves performance by storing precompiled script bytecode in shared memory. This eliminates the need for PHP to parse and compile the source code on every request, significantly reducing CPU overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0a7e3f8-a3db-438c-b0d6-7f368058610e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''resolve'' configuration used for?', N'Junior', N'The resolve configuration determines how Webpack resolves modules when they are imported. It allows developers to set up aliases for common paths or specify file extensions so that you don''t have to type them out in your import statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d31aa4b-85ad-4850-a0d3-7f398ef4938e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a feature was working yesterday but not today, what is your first thought?', N'Fresher', N'I would investigate what has changed since yesterday, such as new code deployments, configuration updates, or changes in the operating environment. Most issues are introduced by recent modifications, so reviewing the commit history is usually the most effective first step.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91493e28-079a-4e02-9cb4-7f3c064f445e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How is Promise.all() different from Promise.allSettled()?', N'Fresher', N'Promise.all() and Promise.allSettled() are both methods for handling multiple promises in JavaScript, but they behave differently. Promise.all() waits for all promises to resolve and fails fast if any promise rejects, returning a single rejected promise. Promise.allSettled(), on the other hand, waits for all promises to settle (either resolve or reject) and returns an array of objects describing the outcome of each promise. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd04e88f-c04b-400b-b595-7f3e8a664900', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can Qwik applications be rendered on the server?', N'Junior', N'Yes, Qwik is designed to be rendered on the server, which is essential for SEO and initial performance. The server renders the initial HTML and serializes the state, which the client then resumes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27cf1152-1d10-49fd-98d4-7f3ed2a2c475', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do Nuxt plugins differ from standard Vue plugins?', N'Middle', N'Nuxt plugins are automatically registered and can be configured to run only on the server, only on the client, or both. They are essential for integrating libraries that require access to the Vue instance or Nuxt context during the application initialization process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e9a70f-8ced-4f4f-8de7-7f3f844f5be4', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are Query parameters in Actix-web?', N'Fresher', N'Query parameters are the data appended to the end of a URL after a question mark. Actix-web provides extractors to easily parse these parameters into typed structs for use within your handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22004ef9-8512-4070-95f3-7f3fd4dc252d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the difference between ''Any'' and ''Any?''', N'Middle', N'Any represents a non-optional value of any type, while Any? is an optional that can either contain a value of any type or be nil. Using Any? forces the developer to handle the case where the value might be missing, whereas Any implies the value exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'032a9eee-53af-4c3c-a8ca-7f4060deac8f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go use a stack-based memory allocation for goroutines instead of a fixed size?', N'Middle', N'Go uses growable segmented stacks to allow each goroutine to start with a small memory footprint, typically 2KB. This enables the runtime to support hundreds of thousands of concurrent goroutines without exhausting system memory, which would be impossible with fixed-size thread stacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd84c7007-5e7b-4a0c-b4a7-7f40b2ce8b03', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is memory management in Fiber considered more complex than in standard net/http?', N'Senior', N'Because Fiber reuses request and response objects to achieve high performance, the developer must be disciplined about not holding references to these objects. Improper memory management in this model leads to subtle bugs that are difficult to trace, as the state of an object can change unexpectedly between handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
