INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca9f4001-b419-4dd3-a055-7f45d90dd494', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does ''Caching'' strategy impact data staleness and system throughput?', N'Senior', N'Caching improves throughput by serving data from memory, but it introduces the risk of serving stale information. Architects must balance cache expiration policies, such as TTL or write-through strategies, against the business requirement for real-time data accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0826d7d4-1cd9-4409-90bd-7f4864699c29', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of ''teardown_request'' and how does it differ from ''after_request''?', N'Middle', N'The ''after_request'' function runs after the view and can modify the response, but it does not run if an exception occurs. ''teardown_request'' functions always run after the request context is popped, making them ideal for cleanup tasks like closing database connections regardless of success or failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afcff49f-bd75-4b2b-9589-7f4bc0ca408e', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a document-oriented database?', N'Intern', N'A document-oriented database is a type of NoSQL database that stores data in document formats like JSON or XML. Each document contains pairs of fields and values, making it highly flexible for evolving data requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c60b210-d0de-4012-bd87-7f4be308bc18', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between ''req.body'' and ''req.query''?', N'Middle', N'''req.body'' contains data sent in the request payload, typically via POST or PUT methods, and requires body-parsing middleware. ''req.query'' contains parameters extracted directly from the URL query string, which are available without additional parsing middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ead0d8d-e4cf-4786-a137-7f4de99b8e3e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How would you handle global design system tokens, such as brand colors or spacing scales, across multiple micro-frontends using Tailwind?', N'Senior', N'You should maintain a shared configuration package (NPM) that exports a base Tailwind config file. Each micro-frontend can then extend this base configuration, ensuring design consistency while allowing for domain-specific overrides without duplicating token definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f36a4779-c1c4-497c-8aa2-7f4e388be753', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the advantage of Rocket''s design for static file serving?', N'Middle', N'Rocket offers a simple, secure way to serve static files using file-system path-based routes. It includes built-in protections to prevent directory traversal attacks, ensuring that only intended files are accessible to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'122ee318-afb2-4bdf-9f5f-7f4f65b5ebf0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum achieve concurrency?', N'Intern', N'Axum leverages the Tokio async runtime to handle concurrent requests. When an incoming request arrives, the runtime spawns an asynchronous task, allowing the server to handle thousands of connections simultaneously without blocking the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
