INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55e850ec-1cb5-4e4e-bedb-7f5086ea935b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the significance of the ''untrack'' primitive in preventing unnecessary reactivity?', N'Senior', N'The untrack primitive allows developers to read a signal''s value without creating a subscription to it within the current reactive scope. This is critical for performance tuning where you need to access a signal''s current state inside an effect without triggering re-execution when that signal changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'167a7d82-8e94-4b07-834e-7f50b885631a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the ''final'' keyword used for?', N'Intern', N'The final keyword is used to restrict the user from changing the value of a variable, overriding a method, or inheriting a class. It essentially makes the entity immutable or unchangeable once defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
