INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feab3da3-9b61-466b-b3c5-7f53164f5961', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary advantage of Fastify''s logger, Pino, over generic loggers?', N'Middle', N'Pino is designed for extremely low overhead, which is critical for high-performance frameworks like Fastify. It handles logging asynchronously to ensure that I/O operations do not block the event loop, thereby maintaining the overall responsiveness of the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'061c3a51-c1ca-4147-a9ea-7f58f8ef16a1', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are the performance implications of using Rocket''s strict type checking?', N'Middle', N'While strict type checking adds a minor overhead during the initial request parsing, it significantly improves runtime performance by preventing errors related to invalid data. It also allows the compiler to optimize the code more effectively compared to frameworks that rely on runtime reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c775aba-e192-45fc-ab3b-7f5a7479fed7', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you add custom spacing or colors to Tailwind?', N'Fresher', N'You can add custom values by extending the theme section in the tailwind.config.js file. This allows you to define your own palette or spacing scale that integrates seamlessly with existing utility classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5391cb33-6bd2-4674-8b6f-7f5d8b3d39f5', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the ''gem'' command?', N'Junior', N'The ''gem'' command is used to manage Ruby libraries, known as gems. It allows developers to install, uninstall, search, and list the packages that are installed in the local environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e954c938-cdd8-4ff9-8cba-7f5d986b04c3', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the performance impact of ''Code Splitting'' as implemented in Qwik.', N'Senior', N'In Qwik, code splitting is automated at the function level, not just the route level. This creates a highly fragmented bundle structure that ensures users only download the specific logic for the actions they perform, leading to a flatter performance curve as application size grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b345bfc-e540-4a84-a954-7f61507ae2f6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis ''hot key'' and how do you handle it?', N'Middle', N'A hot key is a single key that receives a disproportionately high volume of traffic compared to other keys, potentially causing a bottleneck on a single shard. It is handled by distributing the key across multiple shards, using local in-memory caching on application servers, or implementing request coalescing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa8f77d0-ba8e-472b-a65d-7f619ffd72ab', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of using TypeScript instead of plain JavaScript?', N'Intern', N'TypeScript is a superset of JavaScript that adds static type definitions to the language. Its primary purpose is to catch errors during development by identifying type mismatches before the code is ever executed. This leads to more reliable code and better developer tooling support like autocompletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44513125-d6e9-4217-aac2-7f654a82742b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the risks of using jQuery plugins in a modern production environment?', N'Middle', N'Many jQuery plugins are outdated, unmaintained, and may contain security vulnerabilities or performance bottlenecks. Relying on them creates a dependency on a legacy ecosystem that lacks the tree-shaking and modularity benefits provided by modern bundlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b668835-f685-4330-8e11-7f666f8399fe', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''module.exports'' object?', N'Junior', N'The module.exports object is used to expose functions, objects, or variables from a specific file so they can be imported and used in other files. It is the core mechanism of the CommonJS module system in Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'363a4462-7286-4a1d-bd06-7f670da6cfd6', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach designing a system for audit logging requirements?', N'Middle', N'I would implement an event-driven logging architecture where all critical changes are captured as immutable events and stored in a secure, write-once-read-many storage system. I would ensure that these logs include the actor, timestamp, and context to provide a clear audit trail for compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'752f6437-4d3b-48eb-9bcb-7f6727eb5575', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Compare the architectural benefits of shared memory (SharedArrayBuffer) versus message passing (postMessage) in Web Workers.', N'Senior', N'SharedArrayBuffer allows for low-latency, concurrent access to data but requires complex synchronization logic like Atomics to prevent race conditions. Message passing provides a safer, decoupled architecture but incurs serialization and copying overhead, making it less suitable for high-frequency data exchange.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b38c47b-dd98-4c51-b092-7f69d696756f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s deferred object mechanism compare to modern Promise/A+ implementations?', N'Senior', N'jQuery''s Deferred object predates the official Promise standard and has subtle differences in behavior, such as how it handles multiple arguments in resolve/reject. This can lead to interoperability issues when attempting to use native async/await patterns or standard library promises alongside jQuery code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b42f6db0-a6f9-4b71-91ac-7f6b1dcbd4b5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between a document-oriented database and a relational database for a high-scale service?', N'Senior', N'The decision hinges on the schema flexibility and consistency requirements. If the data structure is highly dynamic and requires horizontal partitioning with eventual consistency, a document store is preferred; if the system requires strict ACID compliance and complex relational queries, a relational database with sharding or read replicas is the better choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44d04b47-579f-4029-b97e-7f6b62c397f3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a database constraint?', N'Intern', N'A constraint is a rule applied to a table column to limit the type of data that can be inserted into it. Common examples include NOT NULL, UNIQUE, and CHECK constraints which ensure data accuracy and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0a0d247-0b48-4b00-b489-7f6b6a6071cb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does the ''fsync'' configuration impact Redis AOF performance?', N'Middle', N'The fsync policy determines how often Redis flushes the AOF buffer to disk. Setting it to ''always'' ensures maximum durability but significantly degrades performance, while ''everysec'' provides a good balance between data safety and throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b333cbaf-d68f-4616-b3bf-7f6c5b6b499d', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the significance of the R workspace?', N'Fresher', N'The R workspace is the current working environment that contains all the user-defined objects, such as variables, functions, and data sets created during an R session. Users can save this workspace to a file to resume their work later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d484ba0-6a5b-4603-ad54-7f6d60619a53', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the trade-offs of using ''Server-Only'' components in Nuxt?', N'Middle', N'Server-only components are never sent to the client, which reduces the JavaScript bundle size and improves security for sensitive business logic. However, because they are not reactive on the client, they are limited to static content or data that does not require user interaction after the page has loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc32185d-e026-4103-9247-7f7107d6288a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does the Redis Pub/Sub mechanism differ from a message queue like RabbitMQ?', N'Middle', N'Redis Pub/Sub is a fire-and-forget messaging system where messages are not persisted; if a subscriber is offline, it misses the messages sent during that time. Message queues typically offer persistence, acknowledgment mechanisms, and guaranteed delivery, making them better suited for critical task distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
