INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b26bf043-f523-4c0f-b9f2-7f7546860255', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is document-based storage in NoSQL?', N'Junior', N'Document-based storage saves data in formats like JSON or BSON, where each record is a self-contained document. This allows for nested data structures and provides flexibility, as each document can have a different schema compared to others in the same collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0e22f00-0598-4e63-af02-7f754c3198e2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why would you choose to use Gin over a more minimalist router like Chi or Gorilla Mux?', N'Middle', N'Gin is preferred when you need a ''batteries-included'' framework that offers built-in validation, rendering, and middleware management out of the box. Chi or Gorilla Mux are more lightweight and adhere closer to the standard library, which is better for projects requiring maximum control over the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0597970a-c2e7-491c-ae03-7f75d579bf7f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an ''Event Loop'' in the context of Actix?', N'Intern', N'The event loop is a core mechanism that constantly checks for new I/O events, such as incoming requests or data readiness. It allows the server to switch between tasks efficiently without blocking the CPU.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1682874b-3338-4424-86f3-7f780de53168', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary architectural difference between Tailwind CSS and traditional CSS-in-JS libraries?', N'Middle', N'Tailwind is a utility-first CSS framework that relies on pre-defined atomic classes applied directly to markup, whereas CSS-in-JS libraries generate styles dynamically via JavaScript at runtime or build time. Tailwind promotes consistency through a constrained design system while avoiding the runtime performance overhead associated with many CSS-in-JS solutions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fa9bb3b-5f96-4f32-8ba4-7f7abc2480d3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''Any'' and ''AnyObject''?', N'Fresher', N'The ''Any'' type can represent an instance of any type at all, including function types. The ''AnyObject'' type can represent an instance of any class type, and it is specifically used for interoperability with Objective-C APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d190bb-2498-4192-b3ce-7f7c850c65de', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does database replication improve availability?', N'Middle', N'Replication creates copies of data on multiple nodes, ensuring that if a primary node fails, a replica can be promoted to take its place. This minimizes downtime and provides read-scaling capabilities by offloading read requests to secondary nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb13a8b2-6735-4159-91a2-7f7cc87381bd', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If an application is returning a 500-level error, where is the problem usually located?', N'Junior', N'A 500-level error indicates an internal server error, meaning the problem is on the server side rather than the client side. This usually points to an issue with server-side logic, database connectivity, or unhandled exceptions in the back-end process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b49dd14-4725-47d4-80ce-7f84b7450340', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a computed property, and when should you use one?', N'Junior', N'A computed property is a function that returns a value based on other reactive data. It is cached based on its dependencies and only recalculates when those dependencies change, making it more efficient than calling a function inside a template for complex data transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd740fabf-d9bc-4a9a-9fa3-7f87b961a383', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage memory efficiency in its Virtual DOM implementation?', N'Senior', N'Preact minimizes memory allocation by reusing VNode objects and keeping the object structure extremely flat. By avoiding complex wrapper objects and minimizing internal metadata tracking per component, it maintains a smaller heap footprint compared to React''s fiber-based architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'add53369-cd47-46be-9f3e-7f8b0239126f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the trade-offs between ''WiredTiger'' compression and performance.', N'Middle', N'WiredTiger offers block-level compression which reduces the disk footprint of data and indexes, saving storage costs. However, this comes at the expense of additional CPU cycles required for compression and decompression operations during read and write cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ff41ba1-62d2-46da-bf1e-7f8c4688f06a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the Django Middleware layer and when should you implement custom middleware?', N'Middle', N'Middleware is a series of hooks into Django’s request/response process that allows you to globally alter input or output. You should implement custom middleware for cross-cutting concerns like logging, authentication headers, or request tracking that must apply to every view in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cec8390b-4936-4a3d-bae7-7f8c55582aa1', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s ''Transition'' component handle DOM removal during exit animations?', N'Senior', N'The Transition component uses CSS classes and JavaScript hooks to orchestrate the animation before physically removing the node from the DOM. It manages the timing of the removal to ensure that the exit animation completes fully before the component instance is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e736f777-ac7c-4fed-9680-7f8cb615e3b3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between arguments object and rest parameter', N'Intern', N'There are three main differences between arguments object and rest parameters 1. The arguments object is an array-like but not an array. Whereas the rest parameters are array instances. 2. The arguments object does not support methods such as sort, map, forEach, or pop. Whereas these methods can be used in rest parameters. 3. The rest parameters are only the ones that haven’t been given a separate name, while the arguments object contains all arguments passed to the function', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60cb13de-41ee-42d8-b7a8-7f8db0861cfe', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is the use of ''Global'' dynamic modules often discouraged in large-scale NestJS applications?', N'Senior', N'Global modules create hidden dependencies that make the dependency graph opaque and difficult to trace. They violate the principle of explicit dependency injection, making unit testing harder and increasing the risk of name collisions or unintended side effects across the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b0b3e2c-71d6-4bd4-8ae6-7f8e648a0240', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s middleware execution model work internally?', N'Senior', N'Gin uses a chain of handlers where each middleware calls the next handler via the context''s Next() method. This stack-like execution allows developers to perform logic both before and after the downstream handlers execute, enabling powerful request/response interception patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
