INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66ac55f6-8b6e-411d-abff-7f94ae8f2917', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is ''Code Splitting'' and why is it used?', N'Junior', N'Code splitting is the process of breaking your bundle into smaller chunks that can be loaded on demand. This improves performance by reducing the initial load time, as the browser only downloads the code necessary for the current page or feature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a708f8c-8eda-4822-9112-7f97519860be', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the ''State'' object used for in Litestar?', N'Junior', N'The State object is a shared container that allows you to store and retrieve data across different parts of the application. It is commonly used to hold references to database connections, configuration settings, or shared cache instances throughout the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'086941bd-ac76-4ad8-a6c5-7f9775672f65', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte stores handle concurrency and race conditions?', N'Senior', N'Svelte stores are essentially synchronous in their update propagation, which prevents the unpredictable race conditions common in frameworks that use complex asynchronous state reconciliation. Because updates occur in a predictable, linear fashion, developers can reason about the state sequence more easily without complex side-effect management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5562c27-38fc-4321-a018-7f991dda4e38', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary risk of using fibers in a system that relies heavily on blocking system calls?', N'Middle', N'If a fiber executes a blocking system call directly at the OS level, it can block the entire underlying OS thread, effectively stalling all other fibers running on that thread. To avoid this, the runtime must use non-blocking I/O primitives or specific wrappers that yield control back to the scheduler during blocking operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5fc32e3-7503-49bd-b20f-7f9b51b541dd', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you distinguish between a front-end issue and a back-end issue when a feature stops working?', N'Junior', N'I use the network tab in the browser''s developer tools to inspect the API request and response. If the request is not being sent or the response is malformed, it is likely a front-end issue; if the server returns an error code or an unexpected data structure, the issue is on the back-end.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
