INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7af09c6-a64b-4ae0-95ce-7faa2b6e0988', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the function of the Phoenix Endpoint?', N'Middle', N'The Endpoint is the entry point for every request that reaches your application. It acts as the final destination for the web server, housing the common configuration and the shared plug pipeline that applies to all incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37f135ac-78dd-4827-bdc8-7fab2dce8c06', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why does Fastify encourage the use of ''fastify-plugin'' for modular development?', N'Senior', N'The ''fastify-plugin'' wrapper prevents the framework from creating a new encapsulation context for the plugin, allowing it to share decorators and hooks with the parent application. This is essential for plugins that need to add global functionality rather than scoped, isolated logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a337f319-07f0-446a-ab41-7facf4f7d3f3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What criteria do you use to determine whether a system component should be built in-house or purchased as a managed service?', N'Senior', N'I evaluate whether the component provides a unique competitive advantage to the business. If it is a commodity service, like authentication or storage, I favor managed services to reduce operational burden; if it is core to our specific value proposition, I consider in-house development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36868155-c604-4ffc-83b2-7fb0d777c0bd', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of esbuild in the Vite architecture and why is it used over Babel or SWC for development?', N'Senior', N'Esbuild is written in Go and uses parallelization to achieve extreme build speeds for transpilation and bundling. Vite uses it for development because it is significantly faster than JS-based transpilers, though it does not perform type checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'783ed447-f145-4d89-abfe-7fb37568eaa1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is optimistic locking?', N'Junior', N'Optimistic locking assumes that multiple transactions can complete without affecting each other. It checks for conflicts only at the time of committing; if a conflict is detected, the transaction is rejected and must be retried.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecefe82c-4817-4168-97fd-7fb3b7f3e640', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite improve the developer experience regarding server startup?', N'Intern', N'Vite improves startup by not bundling the entire application upfront. By serving modules on-demand, the server starts almost immediately regardless of the application size, providing instant feedback to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b1e7d0f-8f89-49b9-9827-7fb4d74e0d78', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the concept of a Secondary Index in DynamoDB?', N'Fresher', N'A secondary index allows you to query data in a table using a different attribute than the original primary key. It provides flexibility by enabling lookups based on fields that are not part of the base table''s primary key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f3bac65-fc9f-4aaf-bcec-7fb89cdb953c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of using Micronaut Data?', N'Junior', N'Micronaut Data provides a data access layer that generates query implementation at compile-time. This eliminates the need for reflection and runtime query generation, resulting in better performance and improved compile-time safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dfd4958-f30c-4238-a35d-7fb91b18f320', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of a legacy system''s technical debt on the development velocity of a new feature?', N'Senior', N'I conduct an analysis of the code churn and bug density in the relevant modules to quantify the ''friction'' factor, which effectively reduces the team''s productive capacity. By applying this historical friction coefficient to the new feature''s estimate, I can provide a more grounded timeline that accounts for the reality of working within a constrained, aging codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df1016d5-8f57-4cd9-9c35-7fb95ca4b0d6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do mapped types improve code maintainability?', N'Middle', N'Mapped types allow you to create new types based on the properties of an existing type by iterating over its keys. This reduces boilerplate and ensures that if a base interface changes, all dependent types update automatically, preventing synchronization bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47317e5e-fc2f-4df7-9fc1-7fbeb71f9263', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the ''Bloom Filter'' improve read performance in Cassandra, and what is the risk of its false-positive rate?', N'Senior', N'Bloom Filters are probabilistic data structures stored in memory that determine if an SSTable contains a specific row key before performing disk I/O. A false positive results in an unnecessary disk seek for an SSTable that does not actually contain the requested data, which increases read latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f28cc8e8-a94d-4529-b465-7fbf194dbb12', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is Apache Cassandra?', N'Intern', N'Apache Cassandra is an open-source, distributed NoSQL database management system designed to handle large amounts of data across many commodity servers. It provides high availability with no single point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db6cef8a-ecc3-44b3-982f-7fbf43d08e29', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you perform unit testing on a Flask application without hitting a real database?', N'Middle', N'You should use the Flask test client to simulate requests and configure the application to use an in-memory SQLite database or a dedicated test database for the testing environment. This ensures tests remain isolated, fast, and repeatable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ccc6115-8ef1-49f0-9f4f-7fc09003dfe7', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are ''Fault Tolerance'' annotations in Quarkus?', N'Junior', N'These are part of the MicroProfile Fault Tolerance specification, providing patterns like Retry, Circuit Breaker, and Timeout. They help build resilient applications by defining how the system should behave when external services fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a14d6fa-48c6-4b76-8584-7fc1e5afc171', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring handle circular dependencies?', N'Middle', N'Spring detects circular dependencies during the bean creation process and throws a BeanCurrentlyInCreationException. While you can sometimes resolve them using @Lazy or setter injection, the best practice is to refactor your code to eliminate the circular relationship by introducing a third service or merging the components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58d695e5-b053-407b-aa2b-7fc244090e90', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the Redis ''Pub/Sub'' feature, and what are its limitations regarding message durability?', N'Senior', N'Pub/Sub allows for real-time messaging between services, but it is ''fire-and-forget'' by design, meaning messages are not persisted. If a subscriber disconnects, it loses all messages sent during its absence, making it unsuitable for scenarios requiring guaranteed delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5e84653-b91f-453b-9852-7fc2b4836500', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Describe the strategy for optimizing deep component trees in Lit.', N'Senior', N'Optimization involves minimizing the depth of the tree, using ''memoization'' for expensive template parts, and employing ''Lit-HTML'' directives to skip unnecessary updates. Additionally, using ''Light DOM'' for non-encapsulated elements can reduce the overhead of nested shadow roots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44ab4d36-1e4d-447c-9467-7fc98eefa3f9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the ''msgspec'' library and why is it used with Litestar?', N'Junior', N'Msgspec is a high-performance library for JSON serialization and data validation. It is supported by Litestar as an alternative to Pydantic to provide faster processing speeds for data-intensive applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'654bdf78-f142-4256-b1e5-7fca66cfe4b1', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle layout systems like Flexbox and Grid?', N'Junior', N'Tailwind includes a comprehensive set of utility classes for both Flexbox and Grid layout systems. You apply these classes directly to container elements to control alignment, justification, wrapping, and grid column configurations without writing raw CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdc5fa8b-fb06-4e85-bce2-7fcce86ded79', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Query Parameter and how do you access it?', N'Junior', N'A query parameter is a part of the URL used to filter or sort data, usually appearing after a question mark. In NestJS, you can access these using the @Query() decorator in a controller method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ee5131b-607a-412f-a2a6-7fce27990804', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''object-fit'' property?', N'Middle', N'The ''object-fit'' property specifies how an image or video should be resized to fit its container''s content box. It is particularly useful for maintaining aspect ratios while cropping or stretching media to fill specific dimensions without relying on background images.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc84b5e6-133b-4de3-bc53-7fcef58da3bf', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the benefit of using the @use rule over @import?', N'Junior', N'The @use rule is the modern standard for loading Sass modules and is preferred over @import. It avoids global namespace pollution by requiring you to reference functions and variables by the namespace of the imported file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fe253ca-4255-426d-a89f-7fcf9950f3ee', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why does React recommend against mutating state?', N'Fresher', N'React recommends against mutating state because several of its mechanisms depend on the previous and next state being different objects (reference inequality). When you mutate state in place, the reference does not change, which breaks Object.is bailouts in useState/useReducer, breaks React.memo and useMemo/useEffect dependency comparisons, and can cause tearing under concurrent rendering. It also defeats time-travel debugging in React DevTools. Always produce a new object/array (with the spread operator, array methods like map/filter/toSorted, or a library such as Immer) and pass it to the state setter. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07393d05-b17f-4ce8-ac12-7fcfd0eeea5c', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the Lucene segment merging process affect system performance and why is it necessary?', N'Senior', N'Lucene segments are immutable, meaning updates are implemented as deletes and new writes. Merging consolidates smaller segments into larger ones, reclaiming disk space and reducing the number of open file handles, which improves search performance. However, background merging can be I/O intensive and may cause latency spikes if not properly throttled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67c8c7d5-895b-4eb3-a8da-7fd068cef2c4', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How can you detect if a cache is becoming a bottleneck?', N'Middle', N'A cache bottleneck is typically identified by observing high CPU usage on cache nodes, network saturation, or increased latency in cache response times. Monitoring cache hit ratios and eviction rates can also indicate if the cache is undersized for the current traffic load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e04fbf9d-7067-49fb-9ac8-7fd434c0da7d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you handle list rendering in Svelte?', N'Intern', N'Svelte uses an each block to iterate over arrays and render a template for each item. This makes it straightforward to generate lists or tables based on dynamic data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf812663-554d-4712-9a3d-7fd481d1c0eb', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle namespaces internally during the lookup process?', N'Senior', N'PHP internalizes namespaces as fully qualified names in the symbol table, resolving them during the compilation phase into flat, alias-resolved identifiers. This translation ensures that at runtime, the Zend Engine can perform hash-table lookups for class and function names without needing to traverse the namespace hierarchy repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecf8b0b5-20e7-4884-ae56-7fd494987386', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the trade-offs of using Svelte''s automatic dependency tracking?', N'Middle', N'Automatic dependency tracking simplifies state management by removing the need for manual dependency arrays found in other frameworks. However, it requires developers to strictly follow assignment-based patterns, as Svelte can only track mutations that occur through direct assignment or specific store updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'119a20af-78a3-4708-91b3-7fd576fd5228', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the danger of applying a ''hotfix'' without understanding the root cause?', N'Fresher', N'Applying a fix without understanding the root cause is like treating the symptom rather than the disease. It may temporarily resolve the issue, but it often leads to recurring bugs or creates technical debt that makes future maintenance more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1fbfcc3-f61f-4112-aad4-7fd920f30062', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of eventual consistency and why it is commonly used in NoSQL systems.', N'Middle', N'Eventual consistency is a model where data updates are propagated to all nodes asynchronously, meaning that read operations might return stale data temporarily. This approach is used to achieve high availability and low latency, as the system does not need to wait for all nodes to acknowledge a write before confirming success.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d73a558-5199-4ccc-ae97-7fd97d69b82b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is normalization and why is it important?', N'Fresher', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables to ensure that each piece of data is stored in only one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af018663-3301-481c-8721-7fdcdbc28e18', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you handle shared state across multiple threads in Axum?', N'Middle', N'Shared state must implement the Clone trait and be thread-safe, typically by wrapping data in an Arc. Axum uses this state to provide read-only or interior-mutable access to resources, ensuring safe concurrency across the Tokio runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64c569e0-6341-471c-9441-7fdf03637cfd', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the main advantage of using a micro-frontend architecture?', N'Middle', N'Micro-frontends allow different teams to work on separate parts of a web application independently using different frameworks. This reduces the complexity of managing a large monolithic codebase and enables faster deployment cycles for specific features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd8c3d7b-6c3a-4d3e-afb5-7fe10d101d0e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What does the ''base'' layer in Tailwind represent?', N'Intern', N'The base layer contains reset styles or base styles for HTML elements, such as setting the default font or removing default margins. It ensures that your project starts with a consistent foundation across different browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da4303a2-1f62-47af-aea5-7fe23b59d833', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the architectural trade-offs of Hono''s implementation of the Web Standards API.', N'Senior', N'By strictly adhering to the Request and Response objects of the Fetch API, Hono achieves near-universal portability across platforms like Cloudflare Workers, Bun, and Deno. The trade-off is that it must strictly follow the specification, which sometimes limits the ability to implement proprietary performance optimizations found in non-standard server frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea750a00-c66f-4798-b560-7fe3cf4b1e20', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of ''Stacking Contexts'' and why they are critical for maintaining z-index reliability.', N'Senior', N'A stacking context is a three-dimensional grouping of elements relative to the viewport. When an element creates a new stacking context, its z-index values are scoped within that context, which often explains why a high z-index on a child element fails to layer it correctly over elements outside that context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
