INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b206b75e-3560-4588-8d87-7fe9e7ccc059', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the significance of the race detector in Go?', N'Middle', N'The race detector is a built-in tool that instruments code at compile-time to identify data races during execution. It is vital for concurrent programming, as it helps find non-deterministic bugs that are otherwise nearly impossible to reproduce or detect through standard testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
