INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d716e91-b672-4109-843c-7ff10cfe697b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is Go and why was it created?', N'Intern', N'Go, also referred to as Golang, is an open-source programming language developed by a team at Google and made available to the public in 2009. The design of Go is influenced by its renowned creators: Rob Pike, Ken Thompson, and Robert Griesemer. The language aimed to address specific challenges experienced by Google developers, and also sought to amalgamate the best features from different languages. Key Objectives of Go''s Design - Simplicity: Go was designed with a minimalistic approach to minimize complexity. Its design steers clear of excessive abstractions and programmer ''magic''. - Efficiency: It was crucial for Go to be efficient and expressive in both time and space. - Safety: The creators aimed to make Go a safe, statically-typed language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
