INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29cbc19b-0cea-45a2-99d2-7ff427e64b6d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of NestJS Interceptors and how do they differ from Middleware?', N'Middle', N'Interceptors are used to bind extra logic before or after method execution, allowing for the transformation of results or exceptions returned from functions. While Middleware is executed before the request reaches the route handler and is limited to interacting with the request and response objects, Interceptors can wrap the entire execution flow and modify the data stream asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e8e3d0-1b57-4bc1-b0bd-7ff61109061f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the benefit of jQuery''s ''deferred'' objects compared to standard callbacks?', N'Middle', N'Deferred objects allow for a more structured way to handle asynchronous operations by enabling chaining of callbacks and better error propagation. While they were a precursor to native Promises, they provided a much-needed abstraction to avoid ''callback hell'' in complex asynchronous flows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da3a2f22-4f0b-44f9-87cf-7ff7159f1484', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What considerations do you make when choosing a serialization format like JSON versus Protobuf?', N'Middle', N'JSON is text-based, easy to debug, and universally supported, making it perfect for public APIs. Protobuf is binary, compact, and significantly faster to serialize, which makes it an excellent choice for high-performance internal service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a74c0e1c-ea5c-4a91-a018-7ffa34a80535', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Compare the use of ETag and Last-Modified headers for API caching and concurrency control.', N'Senior', N'ETags provide stronger validation by using content-based hashes to detect changes, making them ideal for conditional GET requests and optimistic locking. Last-Modified headers rely on timestamps, which are easier to compute but can be imprecise due to clock skew or rapid successive updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38c9842f-22ef-4200-8ce4-7ffcfa06a564', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''Connect'' HOC or ''useSelector'' hook optimize re-renders in React-Redux?', N'Senior', N'These tools implement shallow equality checks on the data extracted from the store. If the selected data has not changed by reference, the component is prevented from re-rendering, thereby isolating it from store updates that do not impact its specific requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc23d92c-c356-4f9c-8f9e-7ffd14cfa8f0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'When would you prefer using a custom User model over Django’s default User model?', N'Senior', N'You should use a custom User model from the very beginning of a project to allow for future flexibility in authentication fields, such as using email instead of a username. Modifying the user model after the project has started is a complex process involving extensive database migrations and potential data loss risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
