INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1848d4eb-a864-464d-bfd0-7ffec40697e4', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the trade-offs between pull-based and push-based messaging models.', N'Senior', N'Pull-based systems allow consumers to control their own processing rate, preventing overload and facilitating batch processing, but introduce latency due to polling intervals. Push-based systems offer lower latency by delivering messages immediately, but risk overwhelming slow consumers, necessitating complex flow control mechanisms or backpressure strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7f5f1d4-4e01-4f5d-840d-8000630fab24', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''isolatedModules'' flag affect how files are transpiled in parallel build environments?', N'Senior', N'The ''isolatedModules'' flag ensures that each file is treated as a standalone module, forbidding features that require cross-file information like const enums or declaration merging. This is essential for transpilers like Babel or SWC, which process files independently and lack the full context of the TypeScript project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47ee460a-e461-4e8e-a450-800066f69e24', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you handle cross-cutting concerns like logging or authentication in Hono to avoid code duplication?', N'Senior', N'These concerns are best handled by implementing reusable middleware that can be applied globally or to specific groups of routes. By leveraging Hono''s context-aware composition, you can pass security credentials or request metadata through the context to subsequent handlers, ensuring a DRY architecture across the entire service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c988e4-51c1-4c67-9a6c-800209d91ae0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery impact the loading performance of a web application?', N'Middle', N'As a large library, jQuery adds to the total payload size, increasing the time to interactive. Even if minimized, the overhead of parsing and executing a large script before the application becomes functional can be significant compared to using native browser APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14b95d47-0d0b-475b-af3b-80029d20291f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''const assertions'' versus ''enums''?', N'Senior', N'Const assertions provide a lightweight, inline way to define immutable values with literal types, which is often more idiomatic and avoids the runtime overhead and behavior quirks of enums. Enums are useful for nominal grouping but introduce runtime artifacts that can complicate bundling and tree-shaking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7b45fc5-a996-419e-bf85-8005bf75fbd4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Phoenix Channel and how does it differ from traditional HTTP requests?', N'Junior', N'Channels are a mechanism for soft real-time communication between the client and the server using persistent connections like WebSockets. Unlike HTTP requests, which are request-response cycles, Channels allow for bidirectional, long-lived data streaming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
