INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c1aac24-dc07-4b3b-bee2-8007a88ff7f6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the ''ParamConverter'' in Symfony controllers?', N'Middle', N'ParamConverter automatically fetches database objects based on request parameters, such as an ID in a URL. By type-hinting an entity in a controller method, Symfony retrieves the corresponding object from the database, reducing the amount of boilerplate code needed to find entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
