INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da8e906d-b594-46d8-965e-801bf1e3d779', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Discuss the performance trade-offs of using nested objects versus parent-child relationships.', N'Senior', N'Nested objects are stored within the same Lucene document, making them fast to query but slow to update because the entire document must be re-indexed. Parent-child relationships (joins) store data in separate documents, allowing for independent updates but introducing significant performance overhead during query time due to the complexity of join operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
