INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5274e456-c587-4f88-9aeb-8033db5d000d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary data model used in Cassandra?', N'Intern', N'Cassandra uses a wide-column store data model. This means data is stored in tables with rows and columns, but unlike relational databases, each row can have a different number of columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9b406a1-9f52-4fb3-9f49-8033eceaf22f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the architectural trade-offs of using Flask''s Blueprints versus a microservices architecture for a large-scale application.', N'Senior', N'Blueprints provide logical modularity within a single process, simplifying code organization and dependency management. However, they share the same memory space and global state, whereas a microservices architecture offers fault isolation and independent scaling at the cost of significantly higher operational complexity and network latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba73c186-b902-4710-ad0d-8035950248f6', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the ''SELECT DISTINCT'' statement used for?', N'Junior', N'SELECT DISTINCT is used to return only unique values from a result set. It removes duplicate rows from the output, ensuring that each entry in the result list is unique.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae15788f-2ca4-4f3d-9c99-80387475f4f9', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between synchronous and asynchronous programming in the context of PHP?', N'Middle', N'Synchronous PHP executes code line-by-line, blocking execution until an I/O operation finishes. Asynchronous PHP, often achieved through extensions or frameworks like Swoole or ReactPHP, allows the event loop to handle other requests while waiting for I/O. This improves concurrency and efficiency for high-traffic applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cad15d3f-8f17-451c-9915-8039a12c24e3', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe the impact of the WiredTiger cache on memory management.', N'Senior', N'WiredTiger uses a cache to store uncompressed data pages for fast access and also maintains a portion for compressed data. If the cache is too small, the system will trigger frequent disk I/O to fetch data; if too large, it may lead to memory pressure and OS-level swapping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6a9fab5-92f3-4282-ac54-803d34afdc09', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a pointer in C and why is it used?', N'Intern', N'A pointer is a variable that stores the memory address of another variable rather than a direct value. Pointers are used to efficiently manage memory, pass large structures to functions without copying them, and enable dynamic memory allocation. They provide a way to interact directly with the computer''s memory architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'210ad42a-f05e-446c-9b8c-8042238b42a6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum facilitate testing compared to frameworks like Actix-web?', N'Senior', N'Because Axum handlers are just asynchronous functions and the router is a service, you can test them by invoking them directly as towers or by using the ''tower::ServiceExt'' trait. This decoupling allows for full-stack integration testing without needing to bind to a physical network port.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7bd884f-3210-40ee-a744-80424a00a4f4', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between a static site and a server-side rendered site in Astro?', N'Junior', N'A static site is pre-rendered at build time, creating fixed HTML files for every route. Server-side rendering (SSR) generates the HTML dynamically on the server for each request, allowing for personalized or frequently changing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51e09b9e-a66d-4058-b8f6-8043043ae031', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''static'' middleware in Express?', N'Intern', N'The express.static middleware is a built-in function that serves static files such as images, CSS files, and JavaScript files. It maps a directory to a public URL path so that files within that directory can be accessed directly by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53978c1d-fc39-4981-bbfc-8043dbd538a7', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the role of a dead-letter queue in an asynchronous messaging system?', N'Middle', N'A dead-letter queue acts as a holding area for messages that could not be processed successfully after multiple attempts. It prevents these ''poison'' messages from blocking the main processing queue and allows developers to inspect and debug them without disrupting system flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
