INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae5a7811-0b7f-49a8-9d8f-80495e0b3e48', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a Web API?', N'Intern', N'A Web API is an interface that allows two software applications to communicate with each other over the web using HTTP. In ASP.NET Core, it is used to expose services that return data to mobile apps, web frontends, or other services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
