INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b12dadd7-720e-4689-835b-804def06d7b2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Discuss the trade-offs of using middleware in Axum versus handler-level logic.', N'Senior', N'Middleware in Axum is ideal for cross-cutting concerns like logging, authentication, and headers because it decouples these tasks from business logic. Handler-level logic is preferred when the operation depends strictly on the specific request context, though it lacks the reusability and architectural separation that middleware provides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
