INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60565578-8aa0-43e6-b535-805997b70c48', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are ''server routes'' in Nuxt, and how do they differ from client-side API calls?', N'Middle', N'Server routes are endpoints created within the Nitro engine that run directly on the server. They are useful for interacting with private databases or secure third-party APIs that should not be exposed or accessed directly from the client-side code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c09d776d-ba34-4d17-b432-8059d2f1aba6', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of Gin''s ''Engine'' and how does it relate to the ''http.Handler'' interface?', N'Senior', N'The ''Engine'' is the core struct that implements the ''http.Handler'' interface, acting as the primary multiplexer. It manages the route tree, middleware stack, and rendering configuration, serving as the entry point for all HTTP requests received by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bad1bccc-e5d4-44f2-bad6-805a9f2898d8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is Gin considered faster than the standard Go library for web development?', N'Intern', N'Gin is faster because it uses a custom implementation of the Radix tree for routing and minimizes memory allocations during the request lifecycle. By optimizing how parameters are parsed and handled, it significantly reduces the overhead compared to more general-purpose implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3812f615-4bad-4bab-a300-805aa7f96834', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core''s internal dependency injection container manage disposable objects, and what are the potential pitfalls?', N'Senior', N'The container automatically calls Dispose on services that implement IDisposable when the scope that created them is disposed. A common pitfall is the ''captive dependency'' problem, where a long-lived service holds onto a short-lived service, preventing it from being disposed of correctly and potentially causing memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'562e2c92-8cf4-4ffc-a869-805bfb343472', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the ''Single Responsibility Principle'' and why does it matter for design?', N'Intern', N'This principle states that a module or class should have only one reason to change. It matters because it simplifies code maintenance, reduces the likelihood of unintended side effects, and makes the system easier to test and understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
