INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3270dcae-c111-42da-8121-80625399b8e8', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the impact of the ''CommitLog'' on write durability.', N'Senior', N'The CommitLog records every mutation to disk before it is applied to the memtable, ensuring durability in the event of a system crash or power failure. Once data is flushed from the memtable to an SSTable, the corresponding segments in the CommitLog can be discarded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a52716cb-a57d-44e5-bae5-8066238e761d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing a new service, how do you ensure that it is testable?', N'Senior', N'I enforce a modular architecture with clear interfaces that allow for dependency injection, enabling me to swap real services with mocks during testing. I prioritize unit tests for business logic and integration tests for service boundaries, ensuring that the system''s behavior can be verified in isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa696e75-d2b6-4be3-9598-8066c490304c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Read Repair important for maintaining data integrity in Cassandra?', N'Senior', N'Read Repair compares data versions across replicas during a read operation to detect inconsistencies caused by missed writes or network issues. If a mismatch is found, Cassandra updates the stale replicas with the latest version, ensuring the system converges toward consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feae4c9f-d63f-474c-809c-80677ed13298', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you debug a deadlocked thread in a multi-threaded application?', N'Middle', N'I would capture a thread dump of the application while it is in the deadlocked state to identify the threads involved and the resources they are waiting for. By analyzing the dependency graph of the locks, I can determine the circular wait condition. The solution typically involves changing the order of lock acquisition or using higher-level concurrency utilities that prevent deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8c24eef-4a1f-442e-b946-806791566db9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Explain the significance of ''Fairings'' in the Rocket ecosystem.', N'Senior', N'Fairings are middleware-like components that hook into the Rocket application lifecycle, such as ignition, liftoff, or request/response processing. They allow for global cross-cutting concerns like logging, metrics collection, or header modification without cluttering individual route handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b503c9f3-c482-42c0-9172-806856634932', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary function of an analyzer?', N'Fresher', N'An analyzer is responsible for converting text into tokens or terms during the indexing process. It typically involves character filtering, tokenization, and token filtering to standardize the text for better search results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'499f2e0d-8adf-47b1-9e75-806a5d619b7b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the ''thundering herd'' problem in cache-aside database patterns and how can it be prevented?', N'Senior', N'The thundering herd problem occurs when a heavily requested cache key expires, causing multiple concurrent requests to query the database simultaneously. This can be prevented using distributed locks to ensure only one request refreshes the cache, or by using probabilistic early expiration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca83e81a-f8b9-47e9-bbc9-806a6fba6694', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @PathVariable and @RequestParam?', N'Intern', N'@PathVariable is used to extract values from the URL path itself, usually for identifying a specific resource. @RequestParam is used to extract query parameters from the URL, which are typically used for filtering or searching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f58f0afc-24c5-48fc-862f-806cab4f6f92', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database connection pooling, and why might you need external tools?', N'Middle', N'Django opens a new database connection for each request by default and closes it afterwards. For high-traffic applications, this overhead is significant, so external tools like PgBouncer are often used to maintain a pool of persistent connections that can be reused across requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9c9fff3-b583-4e18-812c-806cf8510cc1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the significance of the order of middleware registration in Express.', N'Middle', N'Express executes middleware in the exact order it is registered. This is critical because downstream middleware depends on the state modified by upstream middleware, such as authentication results or parsed request bodies, making registration order a fundamental part of application flow control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7a449ed-949d-4bb5-a227-8070108cc9e6', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is ''bulkheading'' in system design?', N'Middle', N'Bulkheading is the practice of isolating system resources to prevent a failure in one area from affecting the entire system. By partitioning resources like thread pools or databases, a failure in one component is contained, ensuring the rest of the application remains functional.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
