INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f12c94-d4dd-48d8-a184-807b95e26a10', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte manage large-scale data updates compared to a framework using immutable state?', N'Senior', N'Svelte uses mutable state and fine-grained reactivity to update only the specific parts of the DOM that changed. While immutable frameworks require deep object comparison to detect changes, Svelte''s compiler knows exactly which parts of the DOM depend on a specific variable, making updates extremely fast regardless of the data structure''s size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
