INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d05e028-c9dd-4666-942c-808cae4178e4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary difference between structural and nominal typing, and which one does TypeScript follow?', N'Middle', N'Nominal typing determines type compatibility based on explicit declarations or names, while structural typing focuses on the shape or members of an object. TypeScript uses structural typing, meaning two types are considered compatible if their members match, regardless of their explicit declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
