INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b553d367-e78d-41a0-b26c-80943f06eadf', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the ''Single Table Design'' pattern in DynamoDB?', N'Middle', N'Single Table Design involves storing multiple entity types in one table using a generic key structure and secondary indexes. It minimizes the number of round-trips to the database by allowing you to retrieve diverse, related information in a single query operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ef84da3-f388-4692-af1f-8096f6c27aa5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between ''pass'', ''continue'', and ''break''?', N'Junior', N'The ''pass'' statement is a null operation that does nothing and is used as a placeholder. The ''continue'' statement skips the rest of the current iteration in a loop and moves to the next one. The ''break'' statement terminates the loop entirely, causing the program to exit the loop block immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cf5beed-eab1-401b-9937-809be16cec1f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the function of the CSS ''content-visibility'' property and how does it assist in rendering performance?', N'Senior', N'The content-visibility property allows the browser to skip the rendering work—including layout and painting—for elements that are off-screen. By utilizing this, developers can significantly improve initial page load times and interaction responsiveness for long-scrolling documents by deferring the heavy lifting until the user approaches those sections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'762b4186-1587-4712-9c81-809bf3602d78', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does the ''context'' object inside Fastify affect route performance?', N'Senior', N'The context object stores pre-compiled route settings and handlers, allowing the router to immediately know which hooks and validation schemas apply to a request. This avoids runtime lookups during the request lifecycle, ensuring that the overhead per request remains constant regardless of the number of registered routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df78b9ca-766c-4f32-99ac-809e4947338c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle 404 errors?', N'Fresher', N'Chi provides a default 404 handler that returns a ''Not Found'' response. You can also define a custom NotFound handler by configuring the router to return a specific response or template when no route matches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2054e00d-17ad-4daf-ad89-809fc9705adb', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix achieve ''cache-first'' data fetching, and what trade-offs are involved?', N'Senior', N'Remix encourages using standard HTTP caching headers (like Cache-Control) directly within the loader function. By offloading caching to the CDN or browser, it reduces server load significantly, though it requires developers to be diligent about cache invalidation strategies and understanding stale-while-revalidate patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f4d194c-0ac1-4ea3-b965-80a0187fc53e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the role of the ''implicit'' keyword in Scala and the trade-offs of using it in a large codebase.', N'Middle', N'The implicit keyword allows the compiler to automatically provide arguments or convert types to satisfy function signatures. While it reduces boilerplate and enables elegant patterns like type classes, overusing it can make code difficult to debug because the source of the injected value is not explicitly visible to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1241cc8f-a66d-4b7f-abe5-80a4c22f9b0a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary reason to use an API gateway when designing a system with multiple microservices?', N'Fresher', N'An API gateway acts as a single entry point that directs incoming requests to the appropriate service. It handles common tasks like authentication, rate limiting, and request routing, which simplifies the client-side interaction. This design keeps the internal service structure hidden from the client and provides a centralized point for security and monitoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2861117-ab3d-44a4-8d5e-80aaa518c46a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the importance of the ''build'' vs ''runtime'' environment in Nuxt.', N'Senior', N'The build environment is where assets are transpiled and optimized, while the runtime environment is where the application executes. Keeping these environments distinct allows for flexible deployments, where the same build artifact can be configured for different environments using runtime configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f28ebf-9632-4939-bc9d-80b27728ee35', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the benefit of using ''contenthash'' over ''chunkhash'' for long-term caching.', N'Senior', N'Contenthash is based on the actual content of the file, meaning the hash only changes if the file content changes. Chunkhash changes if any part of the chunk or its dependencies change, which can lead to unnecessary cache invalidation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69133e5a-2dd9-4a07-8c97-80b2a13f17fd', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does caching improve application scalability?', N'Middle', N'Caching stores frequently accessed data in high-speed memory, reducing the need to query the database or perform expensive computations repeatedly. This lowers the latency of requests and significantly reduces the load on backend infrastructure, allowing it to support more concurrent users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'117edf70-46ff-488c-9f54-80b3003cbe0c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the architectural difference between Axum''s routing and a traditional object-oriented router.', N'Senior', N'Axum uses a declarative, type-safe routing tree where handlers are functions rather than methods on an object. This functional approach encourages stateless handlers, which are easier to test in isolation and naturally lend themselves to the concurrent, non-blocking execution model of the underlying runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75148b5d-69f3-4073-a8b5-80b50d9a95b1', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte actions differ from standard component lifecycle hooks?', N'Middle', N'Actions are reusable functions that attach behavior to specific DOM elements, providing a way to manage elements directly. They are more targeted and modular than lifecycle hooks, which are tied to the entire component''s state and rendering lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'744c6c9e-2f49-4ebc-aaf0-80b5b3a20872', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of peer reviews in a technical environment?', N'Intern', N'Peer reviews provide a fresh set of eyes that can catch errors, suggest optimizations, and ensure the solution is understandable to others. They facilitate knowledge sharing across the team and maintain consistent quality across different project modules. This collaborative process leads to more robust and reliable outcomes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc39be20-927d-4d76-b6f4-80bb4cb4efe3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you ensure type safety in a large-scale Redux application using TypeScript?', N'Senior', N'Type safety is achieved by defining interfaces for the root state, action types, and payload structures, and using utility types like ReturnType to derive state shapes. This ensures that selectors and reducers remain strictly coupled to the actual state structure, catching errors during development rather than at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b62a9b0a-e887-4985-b91b-80bc2678d25e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a ''Partial'' in Rails views?', N'Fresher', N'A partial is a small, reusable chunk of a view template that can be shared across multiple pages. They help keep the code DRY (Don''t Repeat Yourself) by allowing common UI elements like headers, footers, or forms to be defined once and included where needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57c93258-d877-4fb7-b241-80bc350310f3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Consistency in the context of ACID?', N'Intern', N'Consistency ensures that a transaction takes the database from one valid state to another valid state. It maintains all predefined rules, such as constraints, cascades, and triggers, throughout the transaction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61151f3a-3d01-4b20-9905-80bf243a0e54', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the body tag?', N'Intern', N'The body tag contains all the visible content of the HTML document, such as text, images, links, tables, and lists. Everything that the user sees in the browser window should be placed within the opening and closing body tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ec7560-def1-4b64-81c7-80c00a014089', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you reason about the trade-off between using a managed cloud service versus hosting on virtual machines?', N'Junior', N'Managed services offload the operational burden of maintenance, updates, and scaling to the provider, but they can be more expensive and cause vendor lock-in. Hosting on virtual machines gives you full control over the environment and software stack, but requires a dedicated team to manage infrastructure and security patches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb315e9c-e226-4062-a77c-80c047e36047', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between a WeakReference and a SoftReference?', N'Middle', N'A SoftReference is intended for memory-sensitive caches and is cleared only when the JVM is running low on memory. A WeakReference is cleared as soon as the garbage collector finds it, regardless of memory pressure. SoftReferences are useful for caching data that can be recomputed, while WeakReferences are ideal for metadata or listeners that shouldn''t prevent object collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca94b94-c6a8-4115-a2db-80c1a88ab383', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it considered best practice to use JWTs for stateless authentication?', N'Middle', N'JWTs encapsulate user identity and claims within the token itself, eliminating the need for the server to perform a database lookup for every request. This improves scalability by allowing the server to remain stateless and simplifies authentication across distributed microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'415b04b6-f3df-409c-85c2-80c2605eeee3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix improve the developer experience?', N'Intern', N'Remix improves the developer experience by keeping the data loading and UI logic together in the same file. It removes the need for complex state management libraries for server data, as the server handles the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
