INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98743545-3b2f-4b4d-ba34-80c40eeae17f', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Compare Blue-Green deployment with Canary releases.', N'Senior', N'Blue-Green deployment focuses on zero-downtime cutover by maintaining two identical environments, offering an instant rollback mechanism. Canary releases prioritize risk mitigation by gradually exposing new functionality to a subset of users, allowing for real-time monitoring and impact analysis before a full rollout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7ef430e-9494-422d-aa13-80c500c933c4', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do Bloom Filters optimize performance in large-scale storage engines?', N'Senior', N'Bloom filters are probabilistic data structures that allow a system to determine if an element is definitely not in a set or potentially in a set. In storage engines like LSM-trees, they prevent unnecessary disk I/O by checking the filter before querying individual SSTables. This significantly reduces latency for ''key not found'' lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ac305d2-6911-4884-a885-80c84e269e01', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is an Application Context in Flask?', N'Junior', N'The application context tracks application-level data, such as configuration variables and the database connection. It ensures that the application instance is accessible during the lifecycle of a request without relying on global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3eacafa4-ffc5-451a-8362-80ca002cfc22', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of Serde in Axum?', N'Intern', N'Serde is the standard Rust framework for serializing and deserializing data. Axum relies heavily on Serde to convert incoming request bodies from formats like JSON into Rust structs and to convert Rust structs back into response formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd76ad2de-4088-4331-b57e-80cbb8b0a5a1', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring manage transaction propagation?', N'Middle', N'Transaction propagation defines how a transaction should behave when a transactional method is called from another transactional method. Common settings include REQUIRED, which joins an existing transaction if present, or REQUIRES_NEW, which suspends the current transaction to start an entirely independent one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'159a10fc-ed2e-43fe-a9bf-80d1c825fa68', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the role of the ''Supervisor'' pattern in Actix and why it is critical for fault tolerance.', N'Senior', N'The Supervisor pattern monitors an actor''s lifecycle and automatically restarts it if it crashes or terminates unexpectedly. This allows for self-healing systems where transient failures in individual actors do not bring down the entire application stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b08e4b4-1774-4b44-9d3c-80d358842619', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of non-standard evaluation (NSE) in R.', N'Middle', N'NSE allows functions to capture the unevaluated expression passed as an argument rather than the resulting value. This is commonly used in packages like ggplot2 or dplyr to allow users to refer to data frame columns directly by name without using quotes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1d15edb-9de1-4869-a308-80d563828840', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB scale to handle increased traffic?', N'Intern', N'DynamoDB scales automatically by partitioning data across multiple servers as the table size or request volume increases. This allows it to maintain consistent performance without manual intervention from the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'470bf16a-3050-4e91-826e-80d6069adb00', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is Django and what are its key features?', N'Intern', N'Django is a high-level Python web framework celebrated for its emphasis on simplifying complex tasks and following the "Don''t Repeat Yourself" (DRY) and "model-template-views" (MTV) paradigms. It''s renowned for rapid development, robustness, and vast ecosystem of packages. Key Features - Object-Relational Mapping : Enables database interactions using Python objects. - Admin Panel : Generates a user-friendly interface for database management. - URL Mapping : Routes web requests based on URLs, using urls.py files. - Template Engine : Processes HTML templates, separating design from logic. - Form Handling : Simplifies form validation and rendering. - Security : Offers built-in protections against common web vulnerabilities. - Middleware : Allows global request/response customization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db5067c9-f737-44b4-8170-80d8d1367779', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How would you make a Python script executable on Unix?', N'Fresher', N'Ans. For this to happen, two conditions must be met: The script file''s mode must be executable The first line must begin with a hash(#). An example of this will be: #!/usr/local/bin/python', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6de9fb1f-7578-4f98-8860-80d8fef26d94', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you decide whether state should be in Redux or local component state?', N'Middle', N'State should stay local if it is only needed by one component or its immediate children. If state needs to be accessed by distant components, shared across pages, or persisted across route changes, it is a candidate for the Redux store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23ab29d0-d114-4758-98e3-80da2efc0d6f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Discuss the trade-offs of using Express as an API gateway versus a dedicated service mesh or API management solution.', N'Senior', N'Express is flexible but lacks built-in features like advanced rate limiting, circuit breaking, and mTLS termination common in dedicated gateways. Using Express for these tasks requires extensive third-party library integration, increasing technical debt compared to using infrastructure-level solutions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3afa3c7-6171-4cea-99a7-80dafaffe0c7', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it often better to use relative estimation instead of absolute estimation?', N'Intern', N'Relative estimation, such as comparing a task''s complexity to a known baseline, is often more consistent because humans are better at comparing two things than assigning an arbitrary absolute value. It reduces the impact of individual bias and helps teams reach a consensus more quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06b3f99d-fce6-4cf7-aa4a-80dcdd2494a2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'In a high-performance scenario, why would you prefer Alpine.js''s lazy evaluation over a full SPA framework?', N'Senior', N'Alpine.js initializes components only when they are needed and remains inert until triggered, resulting in a minimal initial payload and fast time-to-interactive. SPA frameworks require loading the entire application bundle and hydrating the virtual DOM, whereas Alpine integrates into existing HTML, providing a leaner footprint for pages that only require progressive enhancement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f501fde-1513-4e76-9c0a-80df436461d7', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix optimize performance during navigation?', N'Intern', N'Remix optimizes performance by only loading the data and code needed for the next page. It pre-fetches resources as the user navigates, making the transition feel near-instant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80b9558f-1965-416e-9a08-80e0bfe7d72a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you handle file uploads in Actix-web?', N'Junior', N'File uploads are handled using the Multipart extractor. This allows the server to process multipart/form-data requests, providing an asynchronous stream of parts that you can parse and save to the filesystem or storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37d0debe-a076-4972-8f5f-80e1d7621887', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the entry point of a Dart application?', N'Fresher', N'The entry point of every Dart application is the main function. When the program starts, the runtime environment calls this function to execute the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48433d03-ab5e-4a25-b21a-80e30b665136', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''Never'' type and when is it used?', N'Middle', N'The ''never'' type represents values that will never occur, such as a function that always throws an error or an infinite loop. It is also used in exhaustive checks within switch statements to ensure all branches of a union type are handled. If a branch is missing, the compiler will alert you because the variable''s type will be inferred as something other than never.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b5ec390-6c0d-4e09-85f5-80e3c6db1b15', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of migrations in Laravel?', N'Intern', N'Migrations act as version control for your database, allowing a team to define and share the application''s database schema definition. Instead of manually creating tables in a database manager, you define the structure in migration files that can be run on any environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f854eb9-a206-45d6-8dce-80e68a11d1a1', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s reactivity model differ from that of React or Vue?', N'Middle', N'Svelte is a compiler that converts declarative code into imperative JavaScript that surgically updates the DOM. Unlike React or Vue, which use a Virtual DOM to compare changes, Svelte updates the DOM directly when state variables change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe5a707e-7da0-4cdc-85f5-80e6ce3d3011', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are ''Middleware'' in Astro and how are they used?', N'Middle', N'Middleware allows you to run code before every request is processed, making it ideal for tasks like authentication, logging, or modifying headers. It acts as a bridge between the incoming request and the final page response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d627781-81d2-48af-8e47-80e6eb33518b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the jQuery .each() method?', N'Intern', N'The .each() method is a loop function that allows you to iterate over a collection of jQuery elements. It executes a specified function for every element in the matched set, which is useful for performing repetitive tasks on multiple items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fb92fb0-24c3-49a7-8b57-80e7bbd78375', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Local Secondary Index (LSI) and when is it created?', N'Junior', N'An LSI has the same partition key as the base table but a different sort key. It must be created at the same time the table is created and allows for efficient sorting and querying within a specific partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51295eaa-689e-4147-ab92-80e9e58a18df', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you create your own bind method using either call or apply method?', N'Fresher', N'The custom bind function needs to be created on Function prototype inorder to use it as other builtin functions. This custom function should return a function similar to original bind method and the implementation of inner function needs to use apply method call. The function which is going to bind using custom myOwnBind method act as the attached function(boundTargetFunction) and argument as the object for apply method call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46e950b-fa7c-4ef6-ab92-80ebfb4bd834', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does database encryption at rest protect data in a cloud environment?', N'Middle', N'Encryption at rest protects data against physical theft or unauthorized access to the underlying storage media, such as leaked cloud snapshots or physical hard drive theft. It ensures that even if an attacker gains access to the storage files, the data remains unreadable without the decryption keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7b5e6af-239d-4f7f-91fe-80ed4c6c1d16', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How do you inject dependencies in Micronaut?', N'Junior', N'You can use constructor injection, field injection, or method injection. Constructor injection is the recommended practice because it makes dependencies explicit and facilitates easier unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'555764df-6cd3-468e-947b-80ee402af6df', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the function of the Rails ''routes.rb'' file?', N'Intern', N'The routes file acts as a map for the application by connecting incoming HTTP requests to specific controller actions. It defines the URL structure of the website and determines which part of the application code should handle a particular user request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61492de4-4924-4b83-a40c-80f1efd9ca76', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does Content Security Policy (CSP) function as an architectural defense against Cross-Site Scripting (XSS)?', N'Senior', N'CSP is an HTTP response header that allows site operators to restrict the resources, such as JavaScript or CSS, that a browser is allowed to load for a given page. By defining a strict allow-list of trusted sources, CSP prevents the execution of malicious injected scripts, providing an effective browser-side defense-in-depth mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'777ce028-cf36-42b7-9aec-80f5a5860d52', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the significance of the ''$refs'' object in Alpine.js?', N'Middle', N'The ''$refs'' object provides a clean way to access DOM elements directly within a component without resorting to ''querySelector''. It is particularly useful for interacting with elements that are not easily managed via data binding, such as focusing an input or measuring an element''s dimensions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5115f621-8b0d-49c4-b46e-80f6c9ff4c62', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why do we use the HtmlWebpackPlugin?', N'Fresher', N'This plugin simplifies the creation of HTML files to serve your Webpack bundles. It automatically injects the generated bundle script tags into your HTML file, so you do not have to update them manually whenever the filename changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd883fa8f-3715-4645-b7cf-80f8afecf027', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Describe the purpose of the pg_stat_statements module.', N'Middle', N'The pg_stat_statements module tracks execution statistics for all queries executed by the server. It is a critical tool for database administrators to identify performance bottlenecks, such as queries with high total execution time, high disk I/O, or frequent cache misses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6afff0a8-9429-4909-99f2-80fa5ae35921', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What are the trade-offs of using a shared database for multiple microservices?', N'Middle', N'A shared database simplifies data consistency and avoids complex distributed transactions, but it creates tight coupling between services. This prevents independent schema changes and can lead to performance contention as the system scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
