INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2db0ee8-466f-46d9-8739-80fe37692365', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the Phoenix PubSub system?', N'Fresher', N'PubSub stands for Publish-Subscribe, and it is a mechanism that allows different parts of your application to communicate asynchronously. It is commonly used in Phoenix to broadcast messages to multiple connected clients via Channels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e023f60-7cbe-46da-8b66-80fe816f063c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'In a distributed team, how does Astro''s architecture facilitate collaboration between frontend and content editors?', N'Senior', N'By separating content (Markdown/MDX) from UI logic (Components), developers can iterate on the framework code without interfering with content editors. The schema-driven Content Collections further ensure that editors cannot break the build with invalid data, fostering a stable workflow between technical and non-technical stakeholders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3116587c-ca3b-4c36-9043-8100c310b793', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is it important to use ''this.args'' in Glimmer components?', N'Middle', N'In Glimmer components, arguments passed from a parent are accessed via the args object, which remains immutable for the component itself. This enforces the DDAU pattern and ensures that components do not inadvertently mutate the state owned by their parents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'036d9466-ba8a-4d30-83ac-810290ccecde', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can you use standard Go ''net/http'' middleware with Fiber?', N'Intern', N'No, Fiber uses its own internal context and middleware signature. You cannot directly use standard library middleware without an adapter, because Fiber is built on Fasthttp, which is incompatible with ''net/http''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c5a526c-4e2a-4d8a-b821-81031530c20e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What architectural challenges arise when scaling SvelteKit applications across multiple domains or micro-frontends?', N'Senior', N'Scaling requires managing shared state and routing conflicts, which can be difficult in a file-based system. Developers must implement robust communication protocols and consider independent deployment pipelines, often requiring custom adapters or monorepo configurations to maintain consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad84fe78-7ce5-4d5e-962d-8104c54a84c1', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the recovery middleware in Gin?', N'Intern', N'The recovery middleware is a built-in feature that catches any panic occurring during a request''s lifecycle. It prevents the entire server from crashing and allows it to return a 500 internal server error instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d4d097c-97f5-496d-8c45-8104d6d6c5f0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Describe the purpose of Pipes in NestJS.', N'Middle', N'Pipes serve two main purposes: transforming input data to a desired output format and validating data against a schema. By using pipes, you ensure that route handlers receive data in the correct shape and type, reducing boilerplate code in controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86077940-7ccb-467e-8516-810562742d06', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the V8 garbage collection mechanism and how it impacts performance in Node.js.', N'Senior', N'V8 uses a generational scavenging approach, splitting the heap into young and old generations. Minor GC happens frequently for short-lived objects, while major GC is more expensive and can cause ''stop-the-world'' pauses. Frequent creation of large objects forces more major GCs, which directly increases latency in request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37b9c8b3-65bb-4c38-a4d6-8105cc357261', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik suitable for high-frequency interactive applications like games or complex editors?', N'Middle', N'Qwik can be used for complex applications, but the benefits of lazy-loading may diminish if the application requires immediate access to a large portion of its code. In such cases, developers must design their code splitting strategies carefully to avoid frequent network requests during critical user actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02fd03c8-248e-4fe1-81be-810630243bd4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs between using base R and the Tidyverse?', N'Middle', N'Base R provides a stable, dependency-free environment suitable for long-term production scripts. The Tidyverse offers a consistent, human-readable syntax and powerful data manipulation tools, but it introduces many dependencies and undergoes more frequent updates that can impact code stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efd00521-4ea0-4374-8991-8106cdecd2ba', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Migration and a Seeder?', N'Junior', N'A migration is used to define the structure of the database tables, such as adding columns or indexes. A seeder is used to populate those tables with initial or dummy data for testing and development purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04ea57d0-cd08-468f-a2e0-8107986effe4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Foreign Key in a Django model?', N'Intern', N'A Foreign Key is a field used to create a many-to-one relationship between two database models. It allows a record in one table to reference a specific record in another table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
