INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e60eeffa-4c8c-44ed-860b-810ec82340de', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Self-Type'' annotation in Scala?', N'Middle', N'A self-type annotation declares that a trait or class must be mixed into another type. It allows a trait to access members of the type it is mixed into, effectively creating a dependency constraint that is checked at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44ae7508-237c-45b0-ba90-8112485fab27', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the limitations of Ember''s computed properties regarding dependency tracking?', N'Senior', N'Computed properties can lead to ''teardown'' issues or performance bottlenecks if they are too complex or rely on deep, nested object graphs. Over-reliance on them can create hidden dependencies that are difficult to trace, which is why Ember encourages moving toward tracked properties and explicit state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'435f9942-96f7-42c4-abbb-8113168a1865', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the role of the libuv thread pool in a Node.js application and identify which operations utilize it.', N'Senior', N'The libuv thread pool handles blocking I/O tasks that cannot be performed by the OS kernel asynchronously, such as file system operations, DNS lookups, and certain crypto functions. By default, it consists of four threads which are shared across the entire process, meaning CPU-intensive tasks can starve the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'358d2a57-3f47-4d44-b603-81141e746b02', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the role of ''CORS'' middleware in Echo and the security implications of misconfiguration.', N'Senior', N'The CORS middleware manages the Access-Control-Allow-Origin headers to control cross-domain requests. Misconfiguration, such as allowing wildcard origins with credentials, can expose private user data to malicious third-party sites, making strict origin whitelisting a mandatory security practice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20014ba7-c916-4216-b4b7-8115289ab877', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''Option'' type?', N'Junior', N'The Option type is used to represent the presence or absence of a value, helping to avoid null pointer exceptions. It has two subclasses, Some, which contains a value, and None, which indicates the absence of a value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec8feae0-caba-443e-ae7a-8116248401de', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between vertical scaling and horizontal scaling for a legacy monolith?', N'Senior', N'Vertical scaling is often simpler to implement and requires no architectural changes, but it hits a physical hardware ceiling and is costly. Horizontal scaling offers theoretically infinite capacity and high availability, but it necessitates significant refactoring to handle state management and data partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
