INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0462fe44-e424-4e28-936d-811973138ab0', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Discuss the challenges of binary compatibility (ABI) in C++.', N'Senior', N'C++ lacks a standardized ABI, meaning that code compiled with different compilers or even different versions of the same compiler may be binary-incompatible. Changes to class layouts, name mangling, or the implementation of standard library templates can break linking, forcing developers to use C-compatible interfaces for stable shared libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27d66a49-0cbf-4fc1-9ff5-811b27bce75a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the architectural implications of using ''Box'' versus stack allocation?', N'Senior', N'Box moves data from the stack to the heap, which is necessary for recursive types or large structures that exceed stack limits. While it provides heap allocation, it introduces a level of indirection and the overhead of dynamic memory management, which can impact cache locality compared to stack-allocated data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'effc0889-123e-47f0-8ba0-811bf165f002', N'954a0331-deff-4399-b588-96f39fec001d', N'What does the ''ChangeDetectorRef'' allow you to do?', N'Middle', N'ChangeDetectorRef provides methods to manually control the change detection process, such as marking a component for checking or detaching it from the tree. It is useful in highly optimized scenarios where you want to bypass the default detection mechanism for specific components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e1dd114-ea91-41a9-af75-811cbaad9790', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are Migrations in AdonisJS, and why are they important?', N'Junior', N'Migrations are version control for database schemas. They allow developers to define, modify, and share database structures in a structured way, ensuring that all team members have consistent database environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef68f72e-6b30-4f04-8327-811f62f9add9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How is a .pyc file different from a .py file?', N'Fresher', N'While both files hold bytecode, .pyc is the compiled version of a Python file. It has platform-independent bytecode. Hence, we can execute it on any platform that supports the .pyc format. Python automatically generates it to improve performance(in terms of load time, not speed).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6ff33b7-1774-4075-8f9b-8122368b39c5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does an optimistic concurrency control strategy differ from a pessimistic one?', N'Middle', N'Pessimistic concurrency control locks records to prevent others from accessing them until a transaction is complete, ensuring safety but reducing throughput. Optimistic concurrency control assumes conflicts are rare, checking for changes only at the time of commit and rolling back if a conflict is detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df4f1282-e304-4ff5-9c29-8125d5c1f6f3', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle large file uploads to minimize memory pressure?', N'Senior', N'Fiber uses streaming buffers and allows direct access to the request body stream, enabling the processing of large files without loading the entire payload into RAM. This is critical for scaling in environments with restricted memory footprints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f698e5ee-0fef-494a-8f78-81268ca37965', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s caching strategy work to improve performance?', N'Middle', N'Symfony uses a multi-layered caching approach, including metadata, configuration, and routing caches, which are generated and stored to disk to avoid expensive parsing on every request. This reduces CPU usage and significantly speeds up the application startup time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbe4b59e-e674-4aeb-9e3c-812812927139', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is PHP?', N'Intern', N'PHP is a widely-used open-source server-side scripting language specifically designed for web development. It is embedded into HTML to create dynamic web pages and interacts heavily with databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aabecae9-9e66-4aaa-b97c-8128744368b5', N'075b8862-431c-4678-9767-f55359758a4a', N'Can you discuss the difference between computed properties and methods?', N'Fresher', N'- Computed Properties: These are like data fields that are derived from other data based on specific logic. You define computed properties using the computed option in a Vue component. - Methods: They are like functions, meaning they are called on demand. You define methods using the methods option in a Vue component. Efficiency - Computed Properties: The natural caching mechanism in Vue ensures that if the data properties on which the computed property depends haven''t changed, the computed property doesn''t recompute. - Methods: They execute every time they are needed, irrespective of whether the underlying data has changed or not. Use in Templates - Computed Properties: They can be used in Vue templates very much like data properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7254d7a-504b-4035-ae88-812e432f8ea9', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s ''resolve.alias'' differ from ''resolve.modules'' in terms of build performance?', N'Senior', N'Resolve.alias provides a direct mapping for specific paths, allowing the resolver to skip disk lookups and drastically reducing filesystem overhead. Resolve.modules tells Webpack where to look for dependencies; while useful, overly broad search paths force the resolver to check multiple directories, which can slow down the resolution process in large projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9de0ba32-897a-4b4e-9d5f-813058b6da50', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the performance implications of using Tailwind''s arbitrary value syntax versus standard utility classes?', N'Senior', N'Standard utility classes are highly optimized and cached by the CSS engine, while arbitrary values cause the JIT compiler to generate unique, one-off CSS rules. Overusing arbitrary values can increase the size of the generated CSS file and potentially lead to specificity issues if not managed carefully within the design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77595a48-2e89-4710-a0cd-813293b40973', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Can you use standard Java libraries in Quarkus?', N'Intern', N'Yes, most standard Java libraries work in Quarkus. However, libraries that rely heavily on complex reflection or dynamic code generation may require custom extensions to function correctly in native mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b40dcc27-eca8-4dfa-894e-81344a13017b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit achieve ''progressive enhancement'' in form actions?', N'Middle', N'SvelteKit form actions allow forms to function without JavaScript by using standard HTML form submissions. If JavaScript is available, SvelteKit intercepts the submission to provide a seamless SPA experience, such as updating the page content without a full reload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'599574d9-4b2d-4350-8a59-81347d4df5fc', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is meant by the term ''serverless'' in the context of DynamoDB?', N'Intern', N'Serverless means that developers do not need to provision, patch, or manage any underlying servers or infrastructure. DynamoDB automatically scales capacity up or down based on traffic demands and handles all maintenance tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9733e6dd-a8b0-4c26-9eae-813541cb68b1', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you handle long-running tasks in an Echo handler to avoid blocking the event loop?', N'Senior', N'Long-running tasks should be offloaded to a background worker or a separate goroutine, returning an ''accepted'' status to the client immediately. Blocking the handler goroutine unnecessarily can exhaust the server''s thread pool and increase latency for other concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f4bad84-261e-4857-a0c3-8136a98ff557', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'When would you prefer a NoSQL document store over a traditional relational database in a high-scale environment?', N'Senior', N'NoSQL document stores are preferred when the application requires flexible schema evolution, high write throughput, and simplified horizontal scaling that is difficult to achieve with rigid relational constraints. They are ideal for unstructured data where complex relational joins are not a primary access pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70d77a98-f6ae-4c9b-96cd-813ad86b9b6d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle CORS, and why is it important?', N'Middle', N'FastAPI provides a built-in CORSMiddleware that allows you to configure which origins, methods, and headers are permitted for cross-origin requests. This is crucial for browser security, preventing unauthorized domains from interacting with your API without explicit permission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3022d656-1d93-428a-90e3-813cc82dce4f', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a Quarkus extension, and why is it essential?', N'Middle', N'A Quarkus extension is a module that integrates third-party libraries or frameworks into the Quarkus build process. It allows the framework to perform ahead-of-time optimization, configuration, and native image compatibility for the integrated library, ensuring it fits the Quarkus runtime model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43a3ac48-cd11-4267-94e8-813e85f885e4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of an interface in C#?', N'Intern', N'An interface defines a contract of methods, properties, or events that a class must implement without providing the implementation logic itself. It allows for multiple inheritance of behavior, enabling different classes to share common functionality regardless of their place in the inheritance hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
