INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1154cb3-f57e-4d79-a49d-814a6c17b31e', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you provide a singleton service?', N'Fresher', N'There are two possible ways to provide a singleton service. 1. Set the providedIn property of the @Injectable() to "root". This is the preferred way(starting from Angular 6.0) of creating a singleton service since it makes your services tree-shakable. 2. Include the service in root module or in a module that is only imported by root module. It has been used to register services before Angular 6.0.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
