INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2f0f516-21f4-4d34-8cc0-8155da81f080', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a scan operation and a query operation in DynamoDB?', N'Intern', N'A query operation retrieves items based on specific primary key attributes, making it very fast and efficient. A scan operation examines every single item in the entire table, which is significantly slower and more resource-intensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11d61ca2-9569-403f-915e-815b475aff9a', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular Routing and how do you set it up?', N'Fresher', N'Angular Routing is a mechanism that allows you to navigate between different views or components in your single-page application (SPA) without requiring a full page reload. It maps URL paths to specific components, enabling features like deep linking, browser history navigation, and organized application structure. To set it up: 1. Include the Router Module: When creating a new project with the Angular CLI, you can add routing automatically. For an existing project, import RouterModule from @angular/router into your main application module (usually AppModule). 2. Define Routes: Create an array of Route objects, typically in a separate file like app-routing.module.ts. Each route object specifies a path (the URL segment) and the component to display when that path is active. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dde5548a-1ef4-4fd2-982b-815b6100d0c0', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle route parameter parsing compared to traditional regex-based routers?', N'Middle', N'Fiber uses a highly optimized, custom-built router that emphasizes performance through string indexing and pre-compiled patterns. This avoids the overhead of complex regex engines during request routing, making it significantly faster for applications with a large number of defined routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07802181-11ab-4547-9012-815d72af9fbb', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact differ from standard DOM manipulation?', N'Intern', N'Standard DOM manipulation involves manually finding and updating elements, which can be slow and error-prone. Preact abstracts this by managing the synchronization between the state and the DOM, ensuring that updates are applied efficiently without manual intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0945fc06-2f5e-465a-aa4e-815e40fec496', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between two different approaches for solving a specific task?', N'Fresher', N'I compare the two approaches based on simplicity, maintainability, and how well they meet the requirements. I prefer the solution that is easier to read and modify in the future, even if it takes slightly longer to implement initially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc75a26-df2d-4580-9a08-8160c709c076', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is an environment in the context of a Rails application?', N'Intern', N'An environment represents the specific setting in which the application is running, such as development, test, or production. Each environment allows for unique configurations, such as different database connections or logging levels, to ensure the application behaves appropriately for its current purpose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
