INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81f97073-b9a6-4aaf-8192-81640e8bd1d2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle ''Scoped Registries'' and what problem does it solve in large-scale applications?', N'Senior', N'Scoped Registries allow components to define their own set of custom element definitions, preventing naming collisions in complex environments. This solves the global namespace issue where multiple versions of the same component might otherwise conflict in a shared application context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
