INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eac60477-8e06-4da6-804b-81686b073947', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket approach memory safety in its request-response handling?', N'Senior', N'Rocket inherits Rust''s ownership and borrowing model, ensuring that request data is handled without data races or memory leaks. By strictly managing the lifetime of incoming buffers and objects, the framework prevents common vulnerabilities like use-after-free or buffer overflows inherent in lower-level C++ frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92b43ff7-6a9e-4bd1-91c2-816e34990440', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the trade-off of using reflection in Java?', N'Middle', N'Reflection allows for powerful, dynamic code that can inspect and modify classes at runtime, which is essential for frameworks. However, it bypasses compile-time type checking, is significantly slower than direct code, and can expose private internals. It should be used sparingly, primarily for infrastructure-level code rather than standard business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
