INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e4684b0-b47c-493a-9425-8196adfaee01', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the difference between a ''Finalizer'' and a ''Dispose'' pattern.', N'Senior', N'Finalizers are non-deterministic hooks called by the GC to clean up unmanaged resources, often leading to delayed memory reclamation. The Dispose pattern provides a deterministic way to release resources immediately, reducing the pressure on the GC and preventing potential resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b66f8b-2f7e-4782-8d68-8196bad83b99', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the role of the V8 engine in Node.js?', N'Intern', N'The V8 engine is the JavaScript engine developed by Google that powers Node.js. It is responsible for compiling JavaScript code directly into machine code, which allows for high-performance execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f9d9f1a-45a2-486e-af08-81992192e62f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust manage binary compatibility in the absence of a stable ABI?', N'Senior', N'Rust does not currently guarantee a stable ABI, meaning binaries compiled with different versions of the compiler may not be link-compatible. This allows the language to evolve rapidly and optimize internal data structures, though it forces libraries to rely on C-compatible ABIs when interoperating across binary boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51cd9fd5-3157-478b-9674-819be873ddb5', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating, why is it often better to provide a range rather than a fixed deadline?', N'Fresher', N'Ranges acknowledge the existence of uncertainty and variables that are outside of one''s control. Providing a range helps stakeholders understand the level of confidence in the estimate and sets more realistic expectations regarding potential delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'236cef52-d832-4886-a2c6-819c064f0d5f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How can FastAPI''s dependency injection system be used to implement multi-tenancy?', N'Senior', N'You can create a dependency that extracts tenant-specific information from headers or JWT claims. By injecting this dependency into your database session factory or repository, you can ensure that all queries are scoped to the correct tenant automatically, reducing the risk of data leakage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36592069-d651-4de5-8b88-81a1221bedcc', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the benefit of using a ''push'' model versus a ''pull'' model for consumers?', N'Middle', N'The push model allows for lower latency as the broker delivers messages immediately upon arrival. The pull model allows consumers to manage their own resource consumption, preventing them from being overwhelmed by the broker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b14c778-3c7d-42fe-8f36-81a206a6c274', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is a ''Hook'' in the context of Fastify?', N'Intern', N'Hooks are lifecycle events that allow you to execute code at specific points during the request-response cycle. Common examples include ''onRequest'', ''preHandler'', and ''onResponse'', which are used for tasks like authentication or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e4c00b1-e365-4143-8039-81a36a7af9b6', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary difference between a relational database and Elasticsearch in terms of how they store and search data?', N'Junior', N'A relational database typically stores data in rows and columns and is optimized for transactional integrity and structured queries. Elasticsearch is a document-oriented search engine that stores data as JSON documents and uses inverted indexes to provide fast, full-text search capabilities across large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e33013a2-ee15-4e1f-8e65-81a3ec56096d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is it important to use ''import.meta.url'' when handling static assets in Vite?', N'Senior', N'Using the URL constructor with import.meta.url allows Vite to resolve asset paths relative to the current module. This ensures that assets are correctly located and processed by the build pipeline, regardless of the final directory structure in the production output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b01415b9-b82d-456a-a725-81a3f3fcc438', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Describe the impact of Django’s middleware on the request-response lifecycle in a high-traffic environment.', N'Senior', N'Middleware wraps every request and response in a series of layers, which adds overhead to every single request processed by the server. In high-traffic systems, excessive or inefficient middleware can become a bottleneck, necessitating the offloading of tasks or the use of leaner entry points.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77c74f5f-7c84-4105-b283-81aada1a493f', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between an adapter in SvelteKit and a standard build?', N'Junior', N'An adapter is a plugin that tells SvelteKit how to transform your application for a specific deployment environment, such as Vercel, Netlify, or a Node.js server. Without an adapter, SvelteKit would not know how to format the build output for your host.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0bb4098-49d3-4f5c-8841-81ac817c9224', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Discuss the trade-offs of using AdonisJS ''Hooks'' versus database-level triggers.', N'Senior', N'Hooks allow for complex business logic execution within the application layer, facilitating easier unit testing and cross-database portability. However, database triggers are more robust as they guarantee execution regardless of the application''s state, though they are harder to maintain and version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
