INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48c2e386-1702-4723-9062-81af84f6a334', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the ''autovacuum'' daemon work and why should it not be disabled?', N'Middle', N'Autovacuum periodically scans tables to identify dead tuples and mark them for reuse, preventing table bloat and managing transaction ID wraparound. Disabling it leads to massive storage growth and eventual system failure, as PostgreSQL would be unable to reuse space or prevent old transactions from causing data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
