INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37a484ab-4c74-4fb3-8319-81b2e91c987e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does it mean for a type to be a value type?', N'Intern', N'A value type is a type whose value is copied when it is assigned to a variable or constant, or when it is passed to a function. This ensures that each instance has its own unique copy of the data, preventing unexpected side effects from other parts of the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
