INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81365e45-7cc9-455f-bd17-81c02c4dabcf', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the function of Redis Pub/Sub.', N'Middle', N'Redis Pub/Sub is a messaging pattern where senders publish messages to channels without knowing who the receivers are. It is useful for real-time notification systems or simple inter-service communication, though it is not persistent; messages are lost if a subscriber is offline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d27fa26-5288-4af2-af54-81c0f41d0fe2', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s ''Tracked'' properties differ from traditional observer patterns in terms of memory overhead and predictability?', N'Senior', N'Tracked properties use a system of auto-tracking where the framework automatically detects dependencies during a render pass without requiring manual observer definitions. This is more memory-efficient and predictable than manual observers, which often lead to memory leaks if not explicitly torn down, and reduces the risk of complex dependency cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c18692f4-3796-4b7d-961a-81c2c5123353', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does a service mesh help in enforcing global security policies?', N'Senior', N'A service mesh uses sidecars to intercept all network traffic, allowing for centralized enforcement of security policies such as mTLS, authorization, and traffic rate limiting. This decouples security logic from application code, ensuring consistent policy application across diverse services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afd6950b-f298-454c-883c-81c554e755c0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the concept of middleware chaining in Chi.', N'Middle', N'Chi uses a functional approach to middleware, where each middleware is a function that wraps an http.Handler. This allows developers to easily stack cross-cutting concerns like logging, recovery, and authentication in a predictable order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbabe640-4a00-4585-9185-81c5d1f86df8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a sudden increase in p99 latency across a microservices architecture without a clear upstream trigger?', N'Senior', N'I would use a service mesh or distributed tracing platform to identify which specific hop in the call chain is experiencing the latency regression. I would then examine the infrastructure metrics for that service, specifically looking for thread pool exhaustion, garbage collection pauses, or I/O wait times caused by downstream database locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94748827-8bd6-41bd-807f-81c872e4ed38', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How can you optimize performance when passing large data objects as props?', N'Senior', N'To optimize performance, pass the signal or store itself rather than the raw value, or use memoized getters if the data is derived. This prevents unnecessary re-computation of child components if the parent''s data object is replaced but the specific values haven''t changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46155a03-96b3-4199-ab58-81cb0f839bc7', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle errors in Flask?', N'Fresher', N'Flask provides the ''errorhandler'' decorator, which allows you to define custom functions to handle specific HTTP error codes like 404 or 500. This enables you to display user-friendly error pages instead of the default browser responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dbd6b4a-4bd3-49b0-8a2b-81d06264b4d2', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the significance of the ASGI standard for FastAPI.', N'Middle', N'ASGI is the successor to WSGI and is designed to support asynchronous, long-lived connections like WebSockets. By following the ASGI standard, FastAPI can leverage the full power of Python''s asynchronous ecosystem, enabling high-concurrency capabilities that WSGI-based frameworks cannot support natively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae98b60-913d-43ec-bde3-81d2927c0859', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Decorator in NestJS?', N'Intern', N'Decorators are a language feature that allows you to attach metadata to classes, methods, or properties. In NestJS, they are used extensively to define routes, dependency injection, and request handling configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2e2339b-f6b5-45a1-950e-81d3f7ba88e4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s ''watch mode'' detect file changes?', N'Senior', N'Webpack uses file system polling or native operating system events (like inotify on Linux) to detect changes in the dependency graph. When a change is detected, it triggers an incremental rebuild, only processing the modified files and their affected parents to maintain high development velocity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'351e3fa7-9bae-4950-b2b7-81d4e78fbaf3', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are ''inline'' middlewares in Chi?', N'Junior', N'Inline middlewares are applied directly to specific routes or route groups instead of being applied globally. This allows you to restrict certain logic, like authentication, to only the routes that truly require it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4be759c0-b90e-48ef-acfd-81d7139ee58c', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the difference between x-bind and x-on?', N'Junior', N'x-bind is used to dynamically set HTML attributes on an element based on data, such as changing an ID, source, or style. x-on is used strictly to listen for and handle DOM events, such as user interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfa8505b-446d-4760-9469-81d833ddf0b4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why do streams use forEach()and forEachOrdered() methods?', N'Fresher', N'* forEach() applies a function to each stream object; ordering in parallel execution is not guaranteed; * forEachOrdered() applies a function to each stream object while maintaining the order of the elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b10b59f-bacc-4f12-aff6-81d88e7286e1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the benefits of using a column-family store?', N'Middle', N'Column-family stores are optimized for storing large volumes of sparse data, allowing for efficient aggregation and high write throughput. They are particularly well-suited for analytical workloads where queries only need to access a small subset of columns from very wide rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bffd778-f584-4990-a19f-81daabe8cfd4', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are ''Background Tasks'' in Litestar?', N'Junior', N'Background tasks allow you to trigger actions that run after the response has been sent to the client. This is useful for non-essential operations like sending emails or processing logs that shouldn''t slow down the main user request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95459ab9-9cee-44f7-bb0e-81dc6c69c759', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is it important to choose the correct data type for a column?', N'Junior', N'Choosing the correct data type ensures that the database uses storage space efficiently and performs calculations accurately. Using an inappropriate type can lead to data loss, storage overhead, or performance issues during sorting and filtering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f3c70b-dd7a-44da-a4d7-81de3f857b06', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js implement Incremental Static Regeneration (ISR) and what are its trade-offs?', N'Senior', N'ISR allows you to update static pages after the site has been built by regenerating them in the background on a per-page basis. The trade-off is the potential for stale content during the revalidation window and increased complexity in managing cache invalidation across distributed environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90f85614-4148-4722-a384-81de527d2cb5', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is ''mean time to recovery'' (MTTR) a more important metric than ''mean time between failures'' (MTBF) for modern cloud services?', N'Middle', N'In distributed systems, failures are considered inevitable. MTTR focuses on how quickly a service can be restored, which directly impacts user experience and SLA compliance, whereas MTBF is less relevant when systems are designed to be fault-tolerant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2d4ae8b-00d5-4595-8515-81e0483bc976', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What happens if you write constructor more than once in a class', N'Junior', N'The "constructor" in a class is a special method and it should be defined only once in a class. i.e, If you write a constructor method more than once in a class it will throw a SyntaxError error. This constructor is called by using the special function call new (see example above).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9afd1ce2-b28b-4f8e-bd9e-81e446f5b8a1', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does the ''context'' setting affect Webpack''s resolution process?', N'Senior', N'The context setting defines the base directory for resolving entry points and loaders from relative paths. By setting an absolute path for the context, you ensure that the configuration is portable and not dependent on the machine''s current working directory, which prevents resolution errors in CI/CD environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf4b7e38-1a9c-4b80-9ad6-81e4eebe7cf8', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the trade-off between vertical and horizontal scaling?', N'Senior', N'Vertical scaling involves increasing the resources of a single node, which is simpler but hits a physical limit and creates a single point of failure. Horizontal scaling adds more nodes to the pool, offering near-infinite scalability and resilience, but requires complex distributed coordination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'484908a0-424c-425d-a680-81e5378dc7f3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a refresh interval?', N'Intern', N'The refresh interval is the frequency at which the index is refreshed, making new operations available for search. The default interval is one second, but it can be adjusted to balance performance and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8fef668-06c5-42a6-8544-81e729ba06ed', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the concept of RESTful routing in Rails.', N'Fresher', N'RESTful routing maps HTTP verbs like GET, POST, PATCH, and DELETE to standard controller actions. This approach ensures that your application follows a predictable structure where specific URLs correspond to specific resource operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc748d55-88bf-4abe-8943-81e7cfd0e5db', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary trade-off when using lazy loading in a web application?', N'Middle', N'Lazy loading reduces the initial bundle size, leading to faster startup times, but it introduces network requests when the user navigates to a new feature. If implemented poorly, it can cause a noticeable delay for the user while the required code is fetched and parsed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
