INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b9b14c4-fd78-4278-bf03-81ee369cc20f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Describe how you would estimate the necessary database throughput for a new feature expected to handle high concurrent writes.', N'Middle', N'I would start by calculating the peak requests per second and the data size per transaction based on expected user growth models. I would then use this data to perform load tests on a staging environment to observe how the database behaves under synthetic stress before committing to a production configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
