INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3d35318-f711-4311-b22e-81f587a77757', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the performance implications of the prototype chain in JavaScript, and how does it differ from traditional class-based inheritance?', N'Senior', N'The prototype chain involves dynamic lookups during property access, which can be slower than direct memory offsets found in class-based languages. While modern JIT compilers optimize these lookups extensively, excessive depth in the prototype chain can still impact performance during hot execution paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7575982e-d9ca-433f-bd05-81f637bcf36a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the trade-off between indexing speed and search performance?', N'Middle', N'Indexing speed can be improved by increasing the refresh interval and reducing replica counts, but this negatively impacts search latency and data redundancy. Conversely, more replicas and shorter refresh cycles improve search performance and consistency at the cost of slower indexing throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8640a16c-e593-4e94-adfa-81f8639be9c3', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s ''hono/jsx'' support?', N'Junior', N'Hono includes built-in support for JSX, which allows developers to write server-side templates with a familiar syntax. This is particularly useful for server-side rendering, as it enables the creation of dynamic HTML responses directly within the backend application without needing a separate template engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31215dcd-a852-4947-af39-81f863bfd5ad', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript Promises and the microtask queue interact with the browser''s event loop to influence rendering performance?', N'Senior', N'Microtasks, such as Promise resolutions, are executed immediately after the current task finishes and before the browser moves to the next phase of the event loop, such as rendering. If a continuous stream of microtasks is queued, it can starve the rendering pipeline, causing the UI to freeze or appear unresponsive to user inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbd2ec49-93ee-4f4e-a4b9-81f8a0181f0f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does "type inference" mean in the context of TypeScript?', N'Intern', N'In TypeScript, type inference is a core feature that allows the type of a variable to be automatically determined from its value. This provides the benefits of static typing without the need for explicit type annotations. How It Works TypeScript employs a best common type algorithm to infer a variable''s type. When TypeScript encounters multiple types for a variable during assignment or an array literal, it computes the union of these types and selects the best common type for the variable. Code Example: Type Inference Consider the following code: TypeScript can infer the most likely type from the context, such as: - When a value is assigned immediately, TypeScript assigns the value''s type to the variable. - Type information from adjacent types is used to determine the best common type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c48181cf-7dc8-470b-ab54-81f984ff22b4', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the concept of ''Hot Partitions'' and how to mitigate them.', N'Middle', N'A hot partition occurs when a specific partition receives a disproportionately high volume of read or write traffic compared to others. This is mitigated by choosing a partition key with high cardinality and using techniques like write sharding or adding random suffixes to keys to distribute traffic more evenly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc68d53f-4645-49a4-a85f-81fa53ada67f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of normalization?', N'Fresher', N'Normalization is the process of organizing data to reduce redundancy and improve data integrity. It involves dividing a database into two or more tables and defining relationships between them to ensure that data is stored logically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8ac5cc3-1da5-4bd9-a47d-81ff7c69a1e7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Is Ruby a compiled or interpreted language?', N'Intern', N'Ruby is primarily considered an interpreted language. Source code is parsed and executed by an interpreter, which allows for dynamic execution without the need for a separate compilation step before running the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd68d3e8-1690-4595-85e9-81ff93603ed1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of the Router in an Ember application?', N'Intern', N'The Ember Router is responsible for mapping URLs to specific application states, which are represented by routes. It determines which template to render and which data to load when a user navigates to a particular URL, ensuring that the application state is always synchronized with the browser''s address bar.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5841b5a-1de5-49cc-9dfa-8201a0f8e52e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s structural typing system differ from nominal typing?', N'Middle', N'TypeScript uses structural typing, where type compatibility is determined by the members of the type rather than its explicit name or declaration. In contrast, nominal typing systems require objects to be explicitly declared as a specific type to be considered compatible, regardless of whether their structures match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25027d5-e986-493a-bac6-8204dceb520d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the viewport meta tag and why is it used?', N'Intern', N'The viewport meta tag is used to control the layout of a webpage on mobile browsers. It tells the browser how to scale the page and set its width, which is a fundamental requirement for making a website responsive on different devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'617ac10d-d53a-4a2d-b442-820ae849b6f1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a centralized database versus a distributed data store?', N'Intern', N'A centralized database is simpler to manage and guarantees strong consistency. A distributed store allows for higher availability and horizontal growth but introduces significant complexity regarding data synchronization and conflict resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a157d9fb-b4ed-4e3d-8334-820e83756dfb', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'When building a high-traffic Hono application, how should you approach caching strategy at the middleware layer?', N'Senior', N'Caching should be implemented using a tiered approach, utilizing a fast in-memory middleware cache for highly frequent, non-sensitive data, and a distributed cache like Redis for shared states across instances. It is essential to implement cache-invalidation logic within the middleware to ensure data consistency, while leveraging HTTP cache headers to offload traffic to CDNs whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f30afb8-465d-4236-a601-8211b10a8862', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What''s a common pitfall when using useContext with objects?', N'Intern', N'A common pitfall when using useContext with objects is triggering unnecessary re-renders across all consuming components — even when only part of the context value changes. When you provide an object as the context value, React compares the entire object reference. If the object changes (even slightly), React assumes the whole context has changed, and all components using useContext(MyContext) will re-render, regardless of whether they use the part that changed. Example: In this case, a change in theme will also trigger a re-render in components that only care about user. This issue can be fixed in two ways, 1. Split Contexts Create separate contexts for unrelated pieces of state: 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b2d7f06-20db-4d62-8d4a-8211c8907d59', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does type deduction in ''auto'' differ from template type deduction?', N'Middle', N'The ''auto'' keyword uses the same rules as template type deduction but ignores top-level const and reference qualifiers by default. This makes it convenient for declaring variables without manually specifying the type, though developers must be careful when they explicitly require references or const-correctness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b05454af-b642-4460-87e6-8212c1dd9daf', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle server-side rendering in comparison to Next.js?', N'Senior', N'Unlike Next.js, which performs SSR followed by client-side hydration, Qwik uses SSR to produce a completely serialized state that requires no hydration step. This eliminates the ''double-execution'' problem where code runs once on the server and again on the client to attach event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8064cb5-7332-4a81-8af0-8213071b01a9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber optimize the parsing of JSON request bodies?', N'Middle', N'Fiber provides built-in methods that use high-performance JSON libraries to unmarshal incoming requests. By avoiding reflection where possible and using optimized encoders, it minimizes the CPU time required to transform incoming bytes into Go structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9c4b446-d326-4a32-923e-8213f22352c1', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary purpose of the x-data directive?', N'Fresher', N'The x-data directive is used to declare a new component scope and define its initial data. It turns the element and its children into an Alpine component, allowing them to access the variables defined within the data object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6017c7e-33cd-4e8d-b495-821597e181ca', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is meant by contiguous memory allocation?', N'Intern', N'Contiguous memory allocation means that all elements of a data structure, such as an array, are stored in adjacent memory addresses. This property enables efficient access to elements using index calculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1badf40a-3444-4694-9179-8215ee94610b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the ''maxmemory-samples'' configuration?', N'Middle', N'The maxmemory-samples parameter controls how many keys Redis samples when it needs to evict data based on LRU or LFU policies. A higher number provides a more accurate approximation of the true least-recently-used key but increases CPU usage during the eviction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad1f8095-7046-41dd-a68a-8216bbfd710b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does the ''mutating'' keyword do?', N'Fresher', N'The ''mutating'' keyword is used in methods within structs or enums to indicate that the method is allowed to modify the properties of that instance. Without this keyword, methods cannot change the state of the value type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ae51193-c937-491f-b17c-8218b8110f11', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does the Gossip protocol facilitate failure detection in a large-scale cluster?', N'Senior', N'In the Gossip protocol, nodes periodically exchange state information with a few random peers, allowing information about node health to propagate exponentially fast throughout the network. It is highly scalable and fault-tolerant because there is no central authority responsible for monitoring every node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a96c364d-16f6-46f8-9c8a-82190e14dec9', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is a wrapper component?', N'Intern', N'A wrapper in React is a component that wraps or surrounds another component or group of components. It can be used for a variety of purposes such as adding additional functionality, styling, or layout to the wrapped components. For example, consider a simple component that displays a message: We can create a wrapper component that will add a border to the message component: Now we can use the MessageWrapper component instead of the Message component and the message will be displayed with a border: Wrapper component can also accept its own props and pass them down to the wrapped component, for example, we can create a wrapper component that will add a title to the message component: Now we can use the MessageWrapperWithTitle component and pass title props: This way, the wrapper component ca...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06174a00-2449-41f0-9f4f-8219b320ccbe', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the significance of the ''BaseController'' and why should it be used?', N'Middle', N'The BaseController provides a standardized structure for handling HTTP requests, ensuring that all controllers follow the same architectural patterns. It simplifies the implementation of cross-cutting concerns like logging or authorization checks across multiple endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ded0d49d-5801-4189-9a9c-821a4484ae13', N'954a0331-deff-4399-b588-96f39fec001d', N'Why is it important to keep Angular components ''dumb'' or ''presentational'' in a large-scale application?', N'Senior', N'Presentational components only receive data via Inputs and emit events via Outputs, making them highly reusable and easy to unit test. By separating them from business logic, which is handled by smart containers or services, you ensure the UI is decoupled from the data layer, facilitating easier changes and maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d077f67-f26e-45b0-a3c6-821f89de536a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Can you update an existing document in Elasticsearch?', N'Fresher', N'Elasticsearch documents are immutable, meaning they cannot be updated directly. To update a document, Elasticsearch retrieves the existing document, makes the changes, and indexes a new version of the document while marking the old one as deleted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e7ceabb-4817-43ce-9f98-82224c2676f4', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''SyncArbiter'' in the Actix ecosystem?', N'Senior', N'A SyncArbiter allows for the execution of synchronous, blocking code within an asynchronous system by dedicating a pool of threads to run specific actors. This allows developers to integrate legacy blocking libraries without compromising the non-blocking nature of the primary application threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e08b1715-e62b-4294-a295-822354ce541b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is it often recommended to favor composition over inheritance in Scala?', N'Senior', N'Inheritance can lead to rigid, brittle class hierarchies that are difficult to refactor as requirements evolve. Composition, often facilitated by traits and mixins, allows for more flexible, granular design that adheres to the principle of single responsibility and improves testability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4f22fce-1701-4145-86f6-82248cdc84a6', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the risks of performing a major schema change in a live Cassandra cluster?', N'Senior', N'Schema changes must propagate through the Gossip protocol to all nodes; if there is a mismatch in schema versions across the cluster, it can lead to failed queries and data corruption. It is crucial to ensure all nodes are on the same version before proceeding to avoid split-brain scenarios regarding table metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2928a297-f26e-4b90-83d2-82252c30cf24', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of an Acknowledgement (ACK) in a message queue?', N'Middle', N'An acknowledgement confirms that a consumer has successfully received and processed a message. If the broker does not receive an ACK, it can re-queue the message to ensure it is not lost, providing delivery guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ddea801-8ddc-44f9-b049-8227124db016', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the stack management of fibers differ from standard OS threads?', N'Middle', N'OS threads typically have large, fixed-size stacks allocated by the kernel, which can lead to memory exhaustion when scaling to thousands of threads. Fibers often use growable or smaller, segmented stacks, allowing for a much higher density of concurrent execution units within the same memory limit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'371f8e9d-d8f3-4d42-bb5c-8228150f31db', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis and what do you use it for?', N'Intern', N'Redis (Remote Dictionary Server) is an in-memory key-value data store renowned for its performance and versatility. It was developed in 2009 by Salvatore Sanfilippo, and it remains an influential tool in modern data management and caching. Key Features - Data Structures: Redis goes beyond basic key-value storage to support various data structures, including strings, lists, sets, sorted sets, and hashes. - Persistence: It offers both options: disk-based persistence and pure in-memory storage. This flexibility caters to use cases where durability and speed requirements differ. - Replication: Redis allows you to create multiple replicas, ensuring high availability and data redundancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'522ada34-8a17-404b-89a2-8228bfa5f03b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''void'' type used for?', N'Intern', N'The ''void'' type is typically used as a return type for functions that do not return any value. It indicates that the function performs an action but does not produce a result that needs to be captured or used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baa1a3a5-16ab-4217-9363-8229819b8693', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can Qwik applications function without JavaScript?', N'Intern', N'Qwik applications rely on JavaScript for interactivity, but because the initial HTML is fully rendered on the server, the content is visible to users even if JavaScript is blocked or slow to download. Basic page navigation may work, but dynamic features require JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6619f63a-9ac5-43a5-ae2e-8229aac785bf', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are access modifiers in TypeScript classes?', N'Fresher', N'Access modifiers define the visibility of class members. ''public'' allows access from anywhere, ''private'' limits access to within the class itself, and ''protected'' allows access within the class and its subclasses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5f50064-1d8e-4ce0-a491-8229b2ceb2c2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do databases ensure atomicity if the log becomes corrupted?', N'Senior', N'Databases use checksums on log pages to detect corruption and often maintain mirrored logs or backup files. If a primary log is damaged, the database may rely on point-in-time recovery using full backups and archived logs to restore the state, though this results in downtime and potential data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa89c875-485b-44c8-8623-822c0c56f315', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the significance of the ''Durability'' property in ACID?', N'Middle', N'Durability guarantees that once a transaction is committed, its changes are permanently recorded in non-volatile memory. Even in the event of a power loss or system crash, the database ensures the committed data is recoverable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'326da5c2-9eb9-4b55-ac64-822de7899e1d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between a ''val'' and a ''const val'' in Kotlin?', N'Fresher', N'A ''val'' is a read-only property that is evaluated at runtime, meaning its value can be determined during execution. A ''const val'' is a compile-time constant that must be known at the time the code is compiled, and it can only be used at the top level or inside an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e4bd0ce-52c2-43fc-b713-822f0827e52c', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the _id field in a document?', N'Fresher', N'The _id field is a unique identifier for each document within a specific index. It allows Elasticsearch to retrieve, update, or delete a specific document efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b0e2229-1db4-400d-994c-8231c44ea186', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why might you choose Svelte over a framework like React for a memory-constrained environment?', N'Middle', N'Svelte''s lack of a virtual DOM and smaller runtime footprint significantly reduces the memory overhead in the browser. This makes it an ideal choice for mobile devices or low-end hardware where minimizing JavaScript execution and memory usage is critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'432dbcb3-48b4-401f-8ed0-8238af67f98f', N'4c000000-0000-0000-0000-000000000005', N'What is the role of backpressure in a reactive system architecture?', N'Senior', N'Backpressure is a mechanism that allows consumers to signal their processing capacity to producers, preventing buffer overflows and system crashes. It shifts the system from a push-based model to a pull-based or reactive model to maintain stability under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbcab147-839a-431f-a2ce-823fc14f243e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''string'' type in C# and why is it immutable?', N'Junior', N'A string is a reference type representing a sequence of characters. It is immutable, meaning once a string object is created, its value cannot be modified; any operation that appears to change a string actually creates a new string object in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29c350e2-6d80-4d9b-9bf2-82407b343cea', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is Sass and how does it relate to CSS?', N'Intern', N'Sass is a CSS preprocessor, which is a scripting language that extends CSS by allowing features that do not exist in standard CSS. It is not natively understood by browsers, so it must be compiled or transpiled into standard CSS files to be used on the web.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c41c87b-cca8-4bdc-8034-8242686f034b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''operator overloading'' mechanism work in Kotlin?', N'Middle', N'Kotlin allows you to provide custom implementations for predefined operators like ''+'' or ''[]'' by defining functions with specific names and the ''operator'' modifier. This enables more natural syntax for your own types while ensuring the code remains readable and predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'badca37b-d907-4c2f-bf36-8242a9e121e0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the trade-offs of using streams over loading data into memory?', N'Middle', N'Streams allow you to process large datasets in chunks, which significantly reduces memory consumption and latency. The trade-off is increased complexity in handling stream events, errors, and backpressure compared to simply loading a file entirely into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'777a7a51-618a-4cd7-ae5d-824314a2689f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact perform when dealing with deep component trees?', N'Middle', N'Preact handles deep component trees efficiently by keeping the diffing process synchronous and predictable. Because it avoids complex reconciliation queues, it generally maintains a stable performance profile, though extremely complex trees can still benefit from standard optimization techniques like memoization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d552343-e16d-49ec-9df3-824349f514b4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a header file and a source file?', N'Junior', N'Header files typically contain declarations for classes, functions, and constants so they can be shared across multiple source files. Source files contain the actual implementations of those declarations, which are then compiled into object files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0840857a-911c-4015-b7a7-82434fdbdedb', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the difference between ''SyncActor'' and ''Actor'' in Actix.', N'Middle', N'An Actor runs on an asynchronous event loop and is intended for non-blocking tasks. A SyncActor runs on a dedicated thread pool and is designed specifically to handle synchronous, blocking operations without affecting the performance of the main event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
