INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93da8498-cbf5-4e23-9077-824682c098b5', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle event propagation differently from standard HTML?', N'Middle', N'Svelte provides event modifiers that can be chained to event listeners to handle common tasks like preventing default behavior or stopping propagation. This simplifies the logic inside event handlers by offloading repetitive tasks to the framework''s declarative syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9adfbfe7-6aae-4e4f-b567-824c66b18caa', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why might you choose a Graph database over a Document or Key-Value store?', N'Middle', N'A Graph database is designed specifically to store and navigate relationships between data entities. While other NoSQL stores struggle with deep multi-level joins, graph databases provide highly efficient traversal of interconnected data, making them ideal for social networks, recommendation engines, and fraud detection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'029eaf89-2a5d-4390-9332-824e81c3b4ac', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does PHP stand for?', N'Intern', N'PHP stands for Hypertext Preprocessor. It is a recursive acronym where the name reflects its function as a tool for processing hypertext.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96e66028-8efb-47f6-8823-8251dbdc81a1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is Elasticsearch and what is its primary use case?', N'Intern', N'Elasticsearch is a distributed, open-source search and analytics engine built on top of Apache Lucene. It is primarily used for full-text search, logging, and real-time data analysis because it allows users to store, retrieve, and manage large volumes of data quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70b73ca9-16da-485a-9d59-8253b33e360c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the advantages of using Materialized Views in a complex reporting architecture?', N'Senior', N'Materialized views pre-compute and store the results of expensive queries, providing near-instant responses for analytical workloads. The trade-off is the latency of the refresh cycle and the additional storage required to maintain the materialized data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df2f903d-a6da-4401-bc9b-8259c126f6d8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle the trade-off between technical debt and shipping features?', N'Senior', N'I treat technical debt as a financial loan, assessing the interest rate in terms of decreased developer velocity and system instability. I negotiate a balance by dedicating a fixed percentage of each sprint cycle to refactoring, ensuring that critical business milestones are met while preventing the system from becoming unmaintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46c2364-e335-4533-88fb-825d5380942a', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the concept of ''Hydration'' in Server-Side Rendering (SSR) with Vue.', N'Senior', N'Hydration is the process where the client-side Vue framework attaches itself to the static HTML generated by the server. It makes the static markup interactive by attaching event listeners and establishing the reactivity system, ensuring the client-side state matches the server-rendered state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed32fd9e-c0b2-426c-b9e9-825e0bf8284f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the difference between a buffered and unbuffered channel.', N'Middle', N'An unbuffered channel requires both the sender and receiver to be ready simultaneously, enforcing strict synchronization. A buffered channel decouples the sender from the receiver up to the capacity of the buffer, allowing for asynchronous communication and flow control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8af526b0-462b-4e1c-9909-826276067f86', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a response header?', N'Intern', N'A response header is a piece of metadata sent back to the client along with the response body. It can contain information such as the content type, security settings, or caching instructions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c45ec8bb-0968-45fa-afb5-82634093aa55', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the benefit of using ''TypedArrays'' for high-performance data processing?', N'Senior', N'TypedArrays provide a fixed-length raw binary data buffer, allowing direct memory access similar to C arrays. This avoids the overhead of object boxing and garbage collection associated with standard JavaScript arrays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9fbced7-d5fe-430e-9a27-82665dff5fd2', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of ''launch'' in a Rocket application?', N'Junior', N'The ''launch'' attribute macro marks the main function of a Rocket application. It initializes the web server and starts the runtime, effectively beginning the process of listening for and serving incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9371b2a3-46d0-49cc-a9c1-826a680c7f16', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is SEO better in Nuxt compared to a standard SPA?', N'Fresher', N'Standard SPAs render content on the client side, which search engine crawlers may struggle to index effectively. Nuxt provides server-side rendering, which sends fully populated HTML to the crawler, making it much easier for search engines to understand and rank the content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecdc8bd4-4019-49c7-9e0c-826b37cbf231', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you differentiate between an application logic error and an infrastructure issue?', N'Middle', N'I look at the scope of the problem; if it only affects a specific feature or user flow, it is likely an application logic error. If it affects all services, the entire cluster, or causes intermittent failures across different endpoints, it points toward infrastructure issues like resource exhaustion or networking problems. Correlating application logs with infrastructure metrics is the fastest way to isolate the source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ff694df-8907-4907-bb2b-826ba13be40b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why would you use a Custom Decorator in NestJS?', N'Middle', N'Custom decorators allow you to extract repetitive logic, such as retrieving user data from a request object or validating specific headers, into reusable annotations. They make controller methods cleaner by abstracting infrastructure concerns away from business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea953458-35d3-429f-9139-826bdfd31470', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the ''provide/inject'' pattern and when is it appropriate?', N'Middle', N'This pattern allows a parent component to serve as a dependency provider for all its descendants, regardless of depth. It is most appropriate for plugin development or deep component trees where passing props through every layer would be impractical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85e88f27-a713-4812-9794-826c7d3e9b27', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a +page.server.js file used for?', N'Fresher', N'A +page.server.js file is used to run code exclusively on the server, such as fetching data from a database or accessing private environment variables. The data exported from the load function in this file is passed as props to the corresponding +page.svelte component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
