INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fce48963-abdb-4541-8e0b-826f44e4be0b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why is it often discouraged to put complex business logic directly into Eloquent models, and what pattern should be used instead?', N'Senior', N'Placing business logic in models violates the Domain Model pattern by coupling data persistence with domain rules, leading to ''Fat Models'' that are hard to test and maintain. Instead, use Domain Services or Action classes to encapsulate complex logic, keeping models focused on data representation and simple relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcf42244-72a3-48e2-8b92-82706519d738', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is an enum in Swift?', N'Intern', N'An enumeration defines a common type for a group of related values and enables you to work with those values in a type-safe way. Swift enums are powerful and can include associated values, methods, and computed properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'717b95d7-7a52-4d31-b408-827121c4d07d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Discuss the implications of using large pages for JVM memory allocation.', N'Senior', N'Large pages reduce the number of translation lookaside buffer (TLB) misses, as fewer entries are required to map the same amount of memory. This can significantly improve performance for memory-intensive applications, though it requires specific OS-level configuration and can lead to increased memory fragmentation if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e4c2497-ab46-43e3-af3e-827530a63c42', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is Ruby''s approach to multiple inheritance?', N'Junior', N'Ruby does not support multiple inheritance of classes, meaning a class can only inherit from one parent class. However, Ruby achieves similar functionality through Mixins, which allow classes to include multiple modules to share behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e9f39f-f703-427d-9079-827800f69363', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the significance of the Application Binary Interface (ABI) for C libraries.', N'Senior', N'The ABI defines the low-level contracts for binary compatibility, including calling conventions, stack layout, structure padding, and name mangling. If two libraries are compiled with different ABIs, attempting to link them or pass data between them will result in memory corruption or undefined behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c3070fc-be69-421e-b068-827b929ce949', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle HTTP requests compared to traditional frameworks?', N'Fresher', N'Fiber uses a custom context object that allows for zero-allocation request handling. It provides a more ergonomic way to access request data like headers, cookies, and parameters compared to the standard Go library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7954502-d10f-4e1f-9aa6-8280ce215c28', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s routing mechanism differentiate it from traditional framework routers?', N'Senior', N'Axum uses a type-safe routing tree that is built at compile time, reducing the need for runtime path matching overhead. It allows for nesting routers and composing middleware at specific tree branches, providing fine-grained control over which routes inherit which policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8898a1a0-72b7-4c81-aebc-828253998155', N'954a0331-deff-4399-b588-96f39fec001d', N'Compare the performance implications of using a Resolver versus handling data loading directly inside a component''s lifecycle.', N'Senior', N'Resolvers block navigation until the data is fetched, ensuring the component is fully hydrated before rendering, which provides a seamless user experience. However, this can lead to perceived latency; handling data internally allows for immediate view rendering with loading states, improving perceived performance at the cost of more complex UI state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddefb668-439b-4ba3-8ca6-82847f2ecf97', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of ''Dead Letter Queues'' in message-driven systems?', N'Senior', N'Dead Letter Queues act as a holding area for messages that cannot be processed successfully after multiple attempts. They enable architects to isolate problematic messages for debugging without blocking the main processing pipeline or losing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
