INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'189b664f-ce76-41f7-a065-8285e7a81345', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the function of the ''sealed'' keyword?', N'Intern', N'The sealed keyword is used to prevent a class from being inherited by other classes. It is also used on methods to prevent them from being overridden in derived classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19169f10-b6bc-42d6-adc0-8285f687f9e9', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the ''Request'' object in Django views?', N'Junior', N'The request object contains metadata about the current HTTP request, such as the user''s browser, the HTTP method used, and any submitted form data. Django creates this object automatically and passes it as the first argument to every view function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5595030-2657-4aaf-8630-8287a3a2aa96', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik differ from traditional hydration-based frameworks?', N'Junior', N'Traditional frameworks must download and execute all JavaScript components during hydration to make the page interactive. Qwik avoids this by serializing the application state and event listeners into HTML, allowing it to resume execution only when a user interacts with a specific part of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cac79b26-d43a-4f9c-b1a2-8288a19ba3e2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when choosing between a relational database and a NoSQL store for a high-write-throughput system?', N'Senior', N'Relational databases provide ACID guarantees and complex query capabilities, which trade off against horizontal scalability and schema flexibility. NoSQL stores excel at high write throughput and horizontal partitioning but often require shifting consistency burdens to the application layer. My choice depends on whether the data model is highly structured or requires dynamic, rapid evolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec664af-2f69-4b1f-bdaf-828952480906', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is an Ecto Repository?', N'Intern', N'An Ecto repository is a module that acts as the interface for your database. It provides the functions needed to perform CRUD operations and execute complex queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd1668f4-717e-422f-844e-828bce134c4a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle database transactions across multiple model operations?', N'Middle', N'AdonisJS provides a transaction API that allows grouping multiple database operations into a single atomic unit. This ensures that either all operations succeed or none are committed, maintaining data consistency even if an error occurs during processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64d0534c-fcc1-460f-bcab-828e073177c4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit leverage the Shadow DOM to improve component encapsulation?', N'Middle', N'Shadow DOM provides a scoped tree for the component, ensuring that global CSS styles do not leak into the component and the component''s internal styles do not affect the rest of the application. It also encapsulates the component''s internal structure, preventing external scripts from accidentally querying or modifying internal elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf364246-17ee-4bdd-be4a-828e298e1d8f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the significance of the ''QRL'' (Qwik Resource Locator) in Qwik''s architecture?', N'Senior', N'A QRL is a unique identifier that points to a specific lazy-loadable module and exported symbol. It allows the framework to dynamically import code chunks exactly when needed, facilitating fine-grained code splitting that is significantly smaller than traditional route-based splitting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3394ba25-6f87-4148-9867-828eaa5f2db9', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle asset optimization for images, and what are the performance benefits?', N'Senior', N'Astro provides an integrated image processing service that automatically handles resizing, cropping, and format conversion like WebP or AVIF. By offloading these tasks to the build step or a server-side handler, it ensures images are optimized for the user''s device, reducing page weight and improving Largest Contentful Paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87bece01-5b53-4ca9-a886-829026f833cc', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the advantage of Nuxt''s auto-import feature for components and composables?', N'Middle', N'Auto-import reduces development time by eliminating the need to manually import Vue components and Nuxt composables in every file. This results in cleaner code and smaller bundle sizes, as Nuxt only imports the specific modules that are actually used in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
