INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cb0c186-f9d5-49f1-8fce-8296aca0a34c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach the migration of a legacy monolithic database to a distributed data store?', N'Senior', N'I would start by identifying bounded contexts and data domains to determine which parts of the monolith are suitable for extraction. I would then employ a dual-write pattern or change data capture (CDC) to synchronize data between the old and new systems, allowing for a phased transition and easy rollback capability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecee1dc4-dda8-49e4-9167-829706954ef1', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the performance implications of Python''s dynamic typing system compared to statically typed languages?', N'Senior', N'Dynamic typing requires the interpreter to perform type checking and lookups at runtime, which imposes a performance overhead compared to compiled, statically typed languages. This flexibility allows for rapid prototyping, but often necessitates the use of C-extensions or JIT compilers for computationally intensive tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05b0e933-c74c-470c-bdf3-82971b7df811', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a clustered and a secondary index in InnoDB?', N'Middle', N'A clustered index stores the actual row data at the leaf nodes, meaning the table itself is organized by the primary key. Secondary indexes contain the indexed column values and a pointer back to the primary key, which the engine then uses to fetch the full row if needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
