INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6aa1fadc-c60b-4a52-9ba6-829fcd611d8f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What does it mean that Java is a statically typed language?', N'Intern', N'Java being a statically typed language means that the type of a variable is known at compile time. This characteristic requires explicit declaration of a variable''s type before it can be used. Key Characteristics of Static Typing in Java Type Safety - All data objects have a specific type - Types cannot change unless explicitly converted - Helps prevent type-related errors at runtime Performance Efficiency - Compile-time type determination allows for code optimization - Reduces runtime overhead associated with type checking Predictability - Known types improve code reliability and maintainability - Easier to reason about code behavior Enhanced Development Experience - IDEs can provide better auto-completion and error detection - Facilitates early identification of type-related issues Code...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
