INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd0f92cc-b4ee-4222-8531-82a496ec650c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Host in ASP.NET Core?', N'Fresher', N'The Host is an object that encapsulates an application''s resources, such as dependency injection, logging, and configuration. Its primary role is to manage the application lifetime and ensure that the server is running and ready to process requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bcc02ee-e34a-41b2-b3a3-82a6d4fb47c3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery manage the complexity of form serialization?', N'Middle', N'The serialize method automatically gathers all form input values and encodes them into a standard URL-encoded string. This is a significant convenience over manually iterating through form elements, though developers must still handle validation and security sanitization on the server side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddbfcc66-cbd4-4260-82c1-82a6ee9e1f67', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a cache in an application?', N'Fresher', N'A cache stores frequently accessed data in a temporary storage area to make future requests faster. By serving data from the cache instead of querying a database or an external API, the application becomes more responsive and reduces overall load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dca8b505-0dda-4656-ae1d-82aa0ea139f4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a ''supervisor'' in Phoenix?', N'Intern', N'A supervisor is a process that monitors other processes. If a child process crashes, the supervisor can automatically restart it, which is the foundation of the ''let it crash'' philosophy used to maintain high availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23887f30-02e7-4e9d-9b04-82ab2c9fb7aa', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Generics in TypeScript?', N'Intern', N'Generics provide a way to create reusable components that can work with a variety of types rather than a single one. They allow functions and classes to accept type parameters, making the code more flexible while maintaining type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'809ed7ff-a5dd-4925-be02-82ab3806b1f4', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the difference between FastAPI middleware and dependencies.', N'Middle', N'Middleware wraps the entire request-response cycle and runs for every single request, making it suitable for global concerns like CORS or request logging. Dependencies are more granular and can be injected into specific routes, allowing for targeted logic such as user authentication or data fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffb8701c-d19a-4150-9f8c-82ade319cdd9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why are lifetimes sometimes omitted in function signatures?', N'Middle', N'Lifetimes are omitted via lifetime elision rules when the compiler can unambiguously determine the relationship between input and output references. This makes code cleaner without sacrificing the safety guarantees enforced by the borrow checker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
