INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b16616-cf8c-45fb-bd90-82b3a0b6228f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember Modifiers work and why would you use them over component lifecycle hooks?', N'Middle', N'Modifiers are used to attach behavior to specific DOM elements, such as initializing a third-party library or setting up event listeners. They are preferred over component hooks because they are tied directly to the element''s lifecycle and are highly reusable across different components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6070af3-2273-40b5-99a6-82b48b105e57', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of the ''Instruction Sequence'' (ISeq) in Ruby?', N'Senior', N'The ISeq is the compiled form of Ruby code, representing the bytecode that the YARV virtual machine executes. By introspecting ISeqs, developers can gain deep insights into how the interpreter transforms high-level Ruby syntax into executable operations, which is useful for performance optimization and debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
