INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbd965aa-74b0-4b15-b710-82b765e444d9', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it important to align the ''effective_cache_size'' parameter with the underlying operating system''s cache?', N'Senior', N'The planner uses this value to estimate how much data is likely to be cached in memory, which influences its preference for index scans over sequential scans. A value that is too low may cause the planner to avoid efficient index operations, while a value that is too high may lead to sub-optimal scan strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
