INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32fa65d8-9313-4736-8499-82c9ade0a5c1', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the common trade-offs when choosing between a B-Tree index and a Hash index?', N'Middle', N'B-Tree indexes support range queries, sorting, and prefix matching, making them highly versatile for most database operations. Hash indexes provide O(1) complexity for exact lookups but do not support range scans or ordered data retrieval, limiting their use cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'826ddd27-1c8e-4c15-91c8-82c9e84dbca0', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a tuple in Python?', N'Intern', N'A tuple is a collection of items similar to a list, but it is immutable. This means that once a tuple is created, its contents cannot be modified, added to, or removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e04c0df4-312d-4396-a3b7-82ca7613675f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the concept of ''N+1'' query problems in Django.', N'Middle', N'An N+1 problem occurs when the code executes one query to fetch a set of objects and then performs an additional query for every single object to retrieve related data. This can be resolved by using ''select_related'' or ''prefetch_related'' to fetch the necessary data efficiently in fewer queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
