INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ced985f-3020-4a79-9a01-82d03bda4e67', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the trade-offs of using IndexedDB versus LocalStorage for client-side storage?', N'Senior', N'LocalStorage is synchronous and limited to small string-based data, making it unsuitable for large datasets as it blocks the main thread. IndexedDB is an asynchronous, transactional database capable of storing complex structured data, making it necessary for offline-first applications and high-performance caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa7c512e-48f7-4b29-ac14-82d0e0df022e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of the $refs magic property in Alpine.js?', N'Middle', N'The $refs magic property provides a convenient way to access DOM elements directly within a component scope. It is useful for tasks that require direct DOM manipulation, such as focusing an input field, measuring element dimensions, or integrating with third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'403d2310-ec54-4b41-aea2-82d1456f0cba', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle memory management for reactive primitives?', N'Senior', N'SolidJS handles cleanup through automatic disposal of reactive effects when their parent scope is destroyed. This prevents memory leaks by ensuring that subscribers are unsubscribed from signals when they are no longer reachable in the UI tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'584a6d4c-086b-4755-8450-82d28a7b8654', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle streaming responses, and what are the memory implications for large payloads?', N'Senior', N'Express supports streaming through the response object, which allows data to be piped directly from a source to the client. This is essential for memory efficiency, as buffering large data payloads into memory before sending would quickly cause heap exhaustion and service crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0070e2f-1913-442e-8cf6-82d351e62afa', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the ''Parallel Query'' feature in PostgreSQL affect resource utilization?', N'Senior', N'Parallel queries enable a single large operation to be split across multiple background worker processes, improving throughput for CPU-bound tasks. However, this increases the total CPU load and memory usage, requiring careful management of concurrent connection limits and resource queues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ca318d4-6a50-4319-8243-82d36b96eba5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is Threads Life Cycle?', N'Intern', N'Threads Life Cycle - Creating the object of a class which is overwriting run method of thread class is known as a creating thread. - Whenever thread is created then we call thread is in new state or birth state thread. - Whenever we call the start method on the new state threads then those threads will be forwarded for scheduling. - The threads which are forwarded for scheduling are known as ready state threads - Whenever scheduling time occurs, ready state thread starts execution. - The threads which are executing are known as running state threads Whenever sleep fun or join methods are called on the running state threads then immediately those threads will wait.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db91e1d0-7afe-42c7-84f9-82d387501399', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the underlying mechanism of the object reference counting system and its limitations.', N'Senior', N'Python tracks the number of references to each object, reclaiming memory immediately when the count hits zero. However, this mechanism cannot resolve circular references, which necessitates a secondary cyclic garbage collector to periodically scan and collect unreachable object groups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe7c9ad2-427d-4b70-bf26-82d51036617a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Discuss the ''readability vs. maintenance'' trade-off when using long strings of utility classes.', N'Senior', N'Long utility class strings can initially degrade readability, but they improve maintenance by eliminating the need to context-switch between HTML and CSS files. Senior teams often mitigate this by using component abstraction or code-folding tools to maintain clean source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb0d1479-14a4-405e-b6ef-82d57b0f527d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Is Alpine.js suitable for large team development, and why or why not?', N'Senior', N'Alpine.js is generally less suitable for large teams than component-based frameworks because it lacks a strict separation of concerns and TypeScript support is often less robust. The tight coupling of logic and HTML can lead to maintenance difficulties in large codebases where multiple developers need to coordinate on shared logic and state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d8ae4d5-7cc1-4879-9841-82d877d83c8d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the benefit of using ''web components'' and the Shadow DOM in HTML structure?', N'Middle', N'Web components allow for the creation of reusable, encapsulated custom elements that maintain their own internal structure and styles. The Shadow DOM ensures that the styles and logic within a component do not leak out or get affected by global CSS, promoting modularity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fece2932-36fb-4446-adf4-82daf8160f76', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a ''finally'' block?', N'Junior', N'The ''finally'' block is used in conjunction with a try-catch statement to execute code regardless of whether an exception was thrown or caught. It is typically used for resource cleanup, such as closing file streams or database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6413fb8-67f8-4086-b2d6-82dd2e3fb2ff', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the ''params'' hash work in Rails?', N'Junior', N'The params hash is a collection that holds data passed from the client to the server, typically from URL parameters or form submissions. It allows controllers to access the inputs provided by the user in a standardized format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd905fe8d-b2f8-441a-8664-82dfb73301cd', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'In a distributed queue, how does the choice of acknowledgment strategy affect throughput and reliability?', N'Senior', N'Synchronous acknowledgments confirm receipt before proceeding, ensuring high durability at the cost of reduced throughput. Asynchronous acknowledgments improve performance significantly but increase the risk of data loss if the broker crashes before the message is persisted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec96187f-1022-4c2f-94e4-82e1da1f6996', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the primary architectural pattern used by Gin?', N'Intern', N'Gin follows a design similar to Martini but utilizes a high-performance HTTP router called HttpRouter. It focuses on speed and memory efficiency to handle large volumes of requests in web services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb6d4742-1f70-47d2-a60f-82e26aa69b17', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the difference between ''any'' and ''unknown'' types.', N'Fresher', N'The ''any'' type tells the compiler to opt-out of type checking for a variable, effectively treating it like standard JavaScript. The ''unknown'' type is a safer alternative that also represents any value but requires the developer to perform type checking or narrowing before performing operations on that variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3cebe2f-7bf6-44e7-ae0f-82e3afd40a8a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra''s log-structured merge-tree architecture affect write performance compared to B-trees?', N'Senior', N'Cassandra uses an LSM-tree architecture which converts random writes into sequential I/O by appending to commit logs and memtables. This avoids the expensive disk seeks required by B-trees for page updates, allowing for significantly higher write throughput at the cost of more complex read paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
