INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa5f20a8-a3c8-4a14-b979-82e503446b41', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate the cost of a project with many unknowns, what is your strategy?', N'Intern', N'I would use a tiered approach, providing a high-level estimate for the known components and a separate risk buffer for the unknowns. I would also outline a plan for how we can reduce these uncertainties through early research or prototyping to refine the cost estimate over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
