INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'604ff7ca-cafc-4c07-b5b8-82e66e212cfb', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between component and container in React Redux?', N'Fresher', N'Component is a class or function component that describes the presentational part of your application. Container is an informal term for a component that is connected to a Redux store. Containers _subscribe_ to Redux state updates and _dispatch_ actions, and they usually don''t render DOM elements; they delegate rendering to presentational child components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
