INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19e60621-26ce-4b94-b118-82f03fb8f10e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber facilitate graceful shutdowns, and why is this critical for high-availability systems?', N'Senior', N'Fiber provides a Shutdown method that stops the listener and allows existing requests to complete before closing the process. This is critical for high availability, as it prevents dropped requests during rolling deployments or infrastructure scaling events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
