INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c27003a9-44f5-4b4e-a538-82f47988bc01', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the purpose of the ''Suspense'' component in Preact?', N'Middle', N'Suspense allows components to pause rendering while waiting for asynchronous data or code-splitting chunks to load. In Preact, it provides a way to declare fallback UI while the main content is being fetched, improving the perceived loading performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'543c67ae-013f-47cb-b68d-82f4a9880aec', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is a ''Fragment'' in React and why is it used?', N'Middle', N'Fragments allow you to group a list of children without adding extra nodes to the DOM. This keeps the DOM tree cleaner and avoids breaking CSS layouts that rely on specific parent-child relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb0c1bb3-5c2a-43a8-afb8-82f6593a773b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of Active Record in a Rails application?', N'Junior', N'Active Record is the Object-Relational Mapping (ORM) layer in Rails. It allows developers to interact with database tables as if they were standard Ruby objects, abstracting away the need to write raw SQL queries for basic CRUD operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c061397-cf2f-4c0b-b002-82f9114d57f0', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the significance of the ''Supervisor'' tree in a Phoenix application''s fault tolerance strategy?', N'Senior', N'The supervision tree defines a hierarchical structure where parent processes monitor and restart their children upon failure. This ''let it crash'' philosophy ensures that individual component failures are contained and isolated, allowing the application to maintain high availability by self-healing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d10c7eb-3ab5-4d4e-99eb-830139cec140', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it dangerous to pass a Fiber context to a goroutine that outlives the request handler?', N'Senior', N'Since Fiber pools its context objects, the memory address is reclaimed and reset once the handler returns. If a background goroutine accesses this context after the handler has finished, it will read mutated or invalid data, leading to unpredictable behavior or crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0f62855-06a3-4977-8f7b-8301928d0c00', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What impact does including the full jQuery library have on performance for a simple website?', N'Middle', N'Including the entire jQuery library adds significant file weight to the initial bundle, increasing the time to interactive. For small projects that only need basic tasks, this is unnecessary bloat that negatively impacts core web vitals like Largest Contentful Paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3434248-a3f0-4c84-9197-8301b4c19d43', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary benefit of Kotlin''s null safety compared to Java?', N'Junior', N'Kotlin''s type system distinguishes between nullable and non-nullable references at compile time. This forces developers to explicitly handle potential null values, which significantly reduces the frequency of runtime null pointer exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37a1107c-251f-41bc-bc23-8303623878ed', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When selecting a storage format for analytical workloads, how do you balance row-based versus column-based approaches?', N'Senior', N'Row-based formats are ideal for transactional updates and single-record retrieval. Column-based formats are chosen for analytical queries because they significantly reduce I/O by only reading relevant attributes, albeit at the expense of slower individual record insertions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd812dc9d-3275-4789-b2d9-8303c04a4a3e', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''Ember Octane'' refer to?', N'Fresher', N'Ember Octane is a major update to the framework that introduced modern JavaScript features and a more streamlined component model. It focuses on making Ember easier to learn and more performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4732eaa-6014-420f-91f1-8306f4e76907', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Discuss the performance impact of boxing and unboxing on the CLR heap.', N'Senior', N'Boxing converts a value type to a reference type, forcing an allocation on the heap and creating a wrapper object, which increases GC pressure. Unboxing retrieves the value from the wrapper, involving a type check that incurs runtime overhead, making frequent boxing/unboxing a common bottleneck in generic collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a587ed1-0b43-4e57-9b20-830780b73a02', N'4c000000-0000-0000-0000-000000000005', N'When would you choose a NoSQL database over a relational database?', N'Middle', N'You choose NoSQL when dealing with unstructured data, high write throughput, or the need for rapid schema changes. Relational databases are preferred when ACID compliance and complex join operations across structured data are critical to the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4070a343-00a5-4770-ba82-83096bf7c5c8', N'4c000000-0000-0000-0000-000000000005', N'What are the benefits of using an API Gateway?', N'Middle', N'An API Gateway acts as a single entry point that handles cross-cutting concerns like authentication, rate limiting, and request routing. It simplifies client interactions and provides a centralized point to monitor and secure traffic flowing to backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ec369d-7384-4e95-bf63-830cbe3bbce2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle the performance of DOM updates, and what are the limitations of this approach?', N'Middle', N'Alpine.js uses a simple reactivity system that observes changes in proxy-wrapped objects and triggers direct DOM updates for specific elements. Because it does not use a virtual DOM or differential rendering, it is extremely fast for small-scale updates, but it may face performance bottlenecks if a single page contains thousands of reactive elements updating simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da9d2776-372a-4cbb-990d-830fb5dddca5', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it important to use prepared statements for database queries?', N'Middle', N'Prepared statements separate the SQL logic from the user-provided data by sending them to the database in separate steps. This effectively neutralizes SQL injection attacks by treating user input strictly as data rather than executable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
