INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'379b5233-113c-4941-ad9d-832093bdfe7b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the __slots__ attribute in a class?', N'Middle', N'The __slots__ attribute restricts the creation of instance attributes to a predefined list, preventing the creation of the standard __dict__ for each instance. This significantly reduces the memory footprint of objects with many instances and can lead to faster attribute access. It is best used for classes that need to store millions of objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
