INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aad6c95c-0a39-474d-9a03-83344f464329', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the impact of using String pooling in Java?', N'Middle', N'String pooling allows Java to reuse String literals by storing them in a special memory region, significantly reducing memory consumption for applications with redundant text data. While it optimizes space, it adds a small overhead to object creation as the JVM must perform a lookup in the pool. This mechanism is only applicable to string literals created without the ''new'' keyword.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ad0a76-a087-465e-b74c-83350856a679', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of ''Type Erasure'' in TypeScript''s design philosophy?', N'Senior', N'Type erasure means that all type annotations are stripped during compilation, leaving only plain JavaScript. This guarantees that TypeScript code doesn''t suffer from runtime performance penalties, but it also means that types cannot be used for runtime logic like ''instanceof'' checks on interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f301a7-6514-43b0-aec8-83353887671d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What happens if you throw an error in an asynchronous route handler?', N'Junior', N'In older versions of Express, an unhandled promise rejection might crash the process. In modern Express, you must pass the error to the next() function to ensure it reaches your error-handling middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a1ece16-5348-40ba-9951-8338e891782c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you copy properties from one object to other', N'Fresher', N'You can use the Object.assign() method which is used to copy the values and properties from one or more source objects to a target object. It returns the target object which has properties and values copied from the source objects. The syntax would be as below, Let''s take example with one source and one target object, As observed in the above code, there is a common property(b) from source to target so it''s value has been overwritten.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d8c639c-60c4-4eff-8109-833a6c5caea1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you declare variables in TypeScript?', N'Fresher', N'In TypeScript, variable declarations support different methodologies for declaring variables and their associated types. Variable and Type Declaration Methods 1. var This declaration can lead to variable hoisting and has global scope or function-level scope. 2. let Use let when you want to define variables within a block scope. This is the recommended default choice: 3. const const allows you to declare constants and is especially useful for maintaining data integrity: 4. Function Scope All three methods (var, let, and const) are confined to their immediate function scope: Rules for Variable Declaration and Initialization - Order Matters: In TypeScript, a variable must be declared before being used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a9d3ca1-c818-4ac2-beae-833d559c0e25', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle the ''Hibernate ORM'' integration to optimize database access in a cloud-native context?', N'Middle', N'Quarkus optimizes Hibernate by performing metadata scanning and entity mapping at build time, reducing the initialization work required when the application starts. Furthermore, it integrates with Agroal, a lightweight connection pool designed specifically for high-performance reactive and imperative applications, ensuring efficient resource management under varying load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b58bc98-cc70-4d48-a9af-833d75ada207', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are database constraints?', N'Intern', N'Constraints are rules applied to columns in a table to limit the type of data that can be stored. Common examples include NOT NULL, UNIQUE, PRIMARY KEY, and CHECK constraints which maintain the accuracy and reliability of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2e25f54-db57-444a-bb01-83402ab6b071', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''public'' directory?', N'Fresher', N'The ''public'' directory is used to store static assets like images, CSS files, and client-side JavaScript. Files in this directory are served directly to the browser without passing through the framework''s routing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8400edac-3a98-448a-a07e-83405e0a4e23', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary architectural benefit of Hono''s ''Preset'' middleware system?', N'Senior', N'Presets allow for the modular aggregation of security, logging, and observability middleware into a single unit. This promotes architectural consistency across large teams by ensuring that all services adhere to the same compliance and monitoring standards with minimal configuration drift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ad57aee-0e67-4f0d-8828-83422c75e9b6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why are interfaces in Go considered implicit rather than explicit?', N'Middle', N'Implicit interfaces promote loose coupling between packages because a type does not need to declare which interfaces it satisfies. This allows consumers to define the interfaces they need without modifying the original source code of the implementation, making systems easier to refactor and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a3da9e3-41c7-4640-976a-83442043609a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How can you debug a Redux application effectively?', N'Middle', N'The Redux DevTools extension is the standard for debugging, providing a visual representation of actions, state changes, and the ability to time-travel. It allows developers to inspect exactly how the state evolved over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecde13f1-31b5-48c8-8201-83466423cb5f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Implicit Conversions'' mechanism impact system predictability?', N'Senior', N'Implicit conversions allow for seamless type bridging, but they can make code behavior opaque by performing ''hidden'' transformations that are not visible in the source code. This makes debugging difficult and can lead to unexpected performance hits or subtle bugs if multiple conversions exist. Modern Scala encourages using explicit extensions or type classes instead of implicit conversions to maintain system predictability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee0e8148-9cd6-4e0c-9ad9-8346bd40e79b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are descriptors in Python, and why are they useful?', N'Middle', N'Descriptors are objects that define how attribute access is handled for other objects through methods like __get__, __set__, and __delete__. They are the underlying mechanism behind properties, methods, and static methods, allowing for fine-grained control over attribute interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
