INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0e1c7c5-6f38-4bdc-9081-834afeeb0b85', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of an Index in MySQL?', N'Fresher', N'An index is a database structure that improves the speed of data retrieval operations on a table. It works like an index in a book, allowing the database to find specific rows without having to scan every single record in the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b706d90d-dc6d-4363-97d0-834dd43eb1f5', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a 1:1 and a 1:N relationship?', N'Fresher', N'A 1:1 relationship occurs when one record in table A corresponds to exactly one record in table B. A 1:N relationship occurs when one record in table A can be associated with multiple records in table B, but each record in table B is associated with only one record in table A.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
