INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09e032f1-57cc-4d53-a6ab-8351cbf4bc4a', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle requests compared to traditional frameworks like Rails or Django?', N'Fresher', N'Unlike traditional frameworks that often use one thread per request, Phoenix uses lightweight processes managed by the Erlang VM. This allows the framework to handle a much higher volume of concurrent users with significantly less memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
