INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55f81bc6-a975-4cad-9fd0-835414bb3898', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the concept of ''At-least-once'' delivery.', N'Middle', N'At-least-once delivery ensures that a message is delivered to the consumer at least once, but potentially more due to network failures or missed acknowledgements. Systems using this approach must be idempotent, as consumers may receive duplicate messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ad6cab1-4c6f-4330-b2dd-8355487e20d4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you decide between using a relational database versus a NoSQL database for a new microservice handling user profile data?', N'Middle', N'The decision should be based on data structure requirements and consistency needs. If the user profile data is highly structured with complex relationships and requires strong ACID compliance, a relational database is superior. Conversely, if the schema is expected to evolve rapidly or requires horizontal scalability to handle massive write throughput, a NoSQL document store provides better flexibility and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18c8c52c-9a31-4c3a-88ba-835660dec319', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is vertical scaling?', N'Intern', N'Vertical scaling, or scaling up, involves increasing the capacity of a single server by adding more power, such as CPU, RAM, or storage. It is often used to handle increased database loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dc8a11d-f8af-48b1-92dd-835d032c488d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of the ''App'' instance in a Litestar project?', N'Junior', N'The ''App'' instance is the central object that initializes the application, registers routes, configures middleware, and manages the lifecycle of the service. It serves as the entry point for the ASGI server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b947dc7-e750-40f4-8669-8361bacc9d08', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When presented with two different ways to solve a problem, how do you choose?', N'Junior', N'I compare them based on factors like simplicity, maintainability, and impact on performance. I choose the solution that is easiest for the team to maintain and understand in the long run, rather than just the most clever or complex one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fd8a69c-46e5-4a0e-b192-836332a3e838', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does the term ''denormalization'' mean?', N'Intern', N'Denormalization is the practice of intentionally adding redundant data to a database schema to improve read performance. It is often used in data warehousing or large-scale systems to avoid expensive join operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8eed4c2-6aea-4f3b-b5fa-8368f9f06114', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary benefit of Hono''s middleware system?', N'Junior', N'Hono''s middleware allows developers to execute code before or after the main request handler. This is useful for cross-cutting concerns like logging, authentication, and CORS, making the application modular and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b65e4fd-5655-4580-abe7-836a258dcb02', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the benefits of using environment variables in an Express application?', N'Middle', N'Environment variables decouple configuration from the code, allowing the same application to behave differently in development, staging, and production. This keeps sensitive information like database credentials out of the version control system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd2a66bf-14df-450f-9708-836a8c82775a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI facilitate service-oriented architecture (SOA) patterns?', N'Senior', N'FastAPI''s support for sub-applications, modular dependency injection, and easy OpenAPI definition makes it an ideal candidate for building microservices. Its ability to quickly define and expose structured APIs allows teams to build decoupled services that communicate efficiently over HTTP/REST.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d77daa9-90e2-4b50-bfe0-836c3dc8e0b7', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide when to implement a database sharding strategy?', N'Senior', N'Sharding is a last resort to be implemented only when vertical scaling reaches a physical limit or cost-prohibitive threshold. I would perform a cost-benefit analysis on the increased operational overhead of data rebalancing and cross-shard queries versus the performance gains required for the specific workload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'463e1bac-296a-4b15-a38a-83705de4e2ff', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the Link component in Next.js?', N'Intern', N'The Link component is used for navigation between different pages in a Next.js application. It enables client-side transitions, which prevents the browser from performing a full page reload and makes navigation feel smoother.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bdf9a73-5901-4c93-8d41-83711351f405', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary difference between a Phoenix Channel and a standard RESTful HTTP request in terms of process lifecycle?', N'Middle', N'REST requests are short-lived, handled by a single process that terminates once the response is sent. Channels are persistent, stateful connections handled by a dedicated long-running process, which allows for bidirectional communication and maintaining client state without repeated handshakes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbfb79b0-e9b6-4631-961f-83725ebff120', N'075b8862-431c-4678-9767-f55359758a4a', N'When should you use a functional component in Vue?', N'Middle', N'Functional components are stateless and have no instance, making them more performant for simple presentational elements. They are ideal for high-frequency rendering scenarios where component overhead needs to be minimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'508aed6b-b8f1-4402-b522-83751ad27875', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does the term ''lazy loading'' mean in the context of Qwik?', N'Junior', N'In Qwik, lazy loading refers to the automatic splitting of application code into tiny, granular chunks. These chunks are only fetched from the server when they are actually needed, such as when a user clicks a button.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c8bfe3f-eb7c-48e5-ad2a-8375bcaeebd9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How is Python executed?', N'Fresher', N'Python source code is not directly executed by the CPU. Instead, it undergoes a multi-stage process involving both compilation and interpretation. Compilation & Interpretation Python utilizes a hybrid model to balance portability and ease of development. - Bytecode Compilation: When a script is run, the Python interpreter first compiles the high-level source code into bytecode. This is an intermediate, platform-independent representation of the code, often stored in pycache directories as .pyc files. - Python Virtual Machine (PVM): The PVM is the runtime engine that executes the bytecode. It iterates through the instructions and maps them to the corresponding machine-specific actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b76d3a59-644a-4945-9ac7-8377717d617d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach troubleshooting a non-deterministic, intermittent performance degradation in a distributed microservices environment?', N'Senior', N'I would start by correlating logs and metrics across the service mesh using a distributed tracing tool to identify where latency spikes occur. I would then analyze resource utilization patterns—specifically looking for garbage collection pauses, lock contention, or network saturation—to determine if the issue correlates with specific node deployments or heavy traffic bursts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30c49d62-7b03-43b0-828d-837857500ae5', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s ''Dependency Injection'' system facilitate unit and integration testing?', N'Senior', N'Ember''s DI system allows developers to inject mocks or stubs for services and adapters directly into components or routes during testing. This decoupling enables isolated testing of business logic without needing to mock the entire application context or perform real network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bab37ac-de53-4f22-ac67-83798eb6671b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary difference between Remix and a traditional single-page application?', N'Fresher', N'A traditional single-page application typically loads all JavaScript upfront and fetches data on the client. Remix works by leveraging the browser''s native capabilities to handle data loading and navigation on the server, resulting in faster initial page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e128ed1f-b718-450d-87ad-837b2e5800cc', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Data Validation in Symfony?', N'Fresher', N'Validation is the process of checking if the data submitted by a user meets specific criteria, such as being a valid email address or not being empty. Symfony provides a Validation component that allows developers to define these rules using simple attributes on class properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a77c28d7-1d89-4dd1-8845-837d136bfc85', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is it important to consider the ''target'' setting in your tsconfig.json?', N'Middle', N'The ''target'' setting determines which ECMAScript version the TypeScript code is compiled down to, affecting which JavaScript features are transpiled into polyfills. Choosing the right target is essential for balancing modern code syntax with the compatibility requirements of the intended runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08da812f-8c86-4d58-a9dc-837e1e985443', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is an annotation processor in Micronaut?', N'Intern', N'An annotation processor is a tool that runs during the Java compilation phase to scan source code for specific annotations. It generates additional source code or metadata files that handle framework tasks like bean registration and dependency injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74586073-18b8-48dc-a058-8380a37bdd55', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ControllerBase class in Web API controllers?', N'Fresher', N'ControllerBase is a base class that provides access to common properties and methods for handling HTTP requests, such as Request, Response, and helper methods like Ok or BadRequest. It is specifically designed for APIs where views are not required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41131b31-67f9-4886-b48a-8382ab69a557', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle concurrency compared to the standard net/http library?', N'Middle', N'Fiber utilizes the Fasthttp engine, which employs a worker pool pattern to manage incoming connections instead of spawning a new goroutine for every single request. This approach limits the number of active goroutines, preventing potential resource exhaustion during high traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3165e5a6-2e91-4c20-b0b5-8383ccf5872c', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''phantom read'' phenomenon, and how can it be prevented in SQL standards?', N'Senior', N'A phantom read occurs when a transaction executes a query twice and finds a new row added by a concurrent transaction that committed between the two reads. It is typically prevented by using Range Locks or Index-Range Locks, which prevent insertions into the specific range of data being queried.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7b8a19e-1a60-4118-a71c-838546d6be5b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you optimize bundle size when using large external libraries in Nuxt?', N'Senior', N'You can optimize bundle size by using ''transpile'' options in the Nuxt config to handle ES modules, utilizing dynamic imports to split code, or configuring the build to exclude specific dependencies. Additionally, leveraging tree-shaking and preferring lightweight alternatives or native browser APIs can significantly reduce the final payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06737034-834b-472a-be3f-83866034f5b7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the main goal of React Fiber?', N'Intern', N'The goal of _React Fiber_ is to increase its suitability for areas like animation, layout, and gestures. Its headline feature is incremental rendering: the ability to split rendering work into chunks and spread it out over multiple frames. Its main goals are: * Incremental Rendering – Breaks work into chunks for smoother updates. * Interruptible Rendering – Pauses and resumes rendering to keep the UI responsive. * Prioritization – Handles high-priority updates (e.g. animations) before low-priority ones. * Concurrency Support – Enables working on multiple UI versions simultaneously. * Better Error Handling – Supports component-level error boundaries. * Suspense Support – Allows waiting for async data before rendering. * Improved DevTools – Enables better debugging and performance tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c23497d-042d-47d2-bb0c-83878d6770fd', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a slice in Go?', N'Intern', N'A slice is a dynamically sized, flexible view into the elements of an array. It is one of the most commonly used data structures because it is more versatile than a fixed-size array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bffdd0c-9c34-4ed4-a244-83880f3e9188', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of the InnoDB Change Buffer and when is it most effective?', N'Senior', N'The Change Buffer caches changes to non-unique secondary index pages when those pages are not in the buffer pool. It is highly effective for write-heavy workloads, as it merges these modifications into the secondary index during background read operations, reducing random I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24abacc0-3444-40cc-b2b6-8388e40f4e0e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the role of Dependency Injection (DI) in Angular, and how do Tree-shakable providers work?', N'Senior', N'Angular''s DI system manages the lifecycle and instantiation of services throughout the application. Tree-shakable providers use the ''providedIn'' property in the Injectable decorator, allowing the build process to prune unused services from the final bundle if they are never injected into any component, thereby reducing bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f18db66e-7ab0-46fd-aa58-8389ade1d6c1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''Ember Object'' provide?', N'Fresher', N'Ember Object is the base class for most objects in the framework. It provides core features like computed properties, observers, and built-in support for the Ember run loop, ensuring that objects interact seamlessly with the rest of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dfbca14-d46c-44be-8b7f-838df5f468cd', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js achieve reactivity?', N'Intern', N'Alpine.js uses a reactivity system that tracks when state properties change. When a property defined in your ''x-data'' is updated, Alpine automatically updates any DOM elements that are bound to that property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00f6975b-de93-42f6-ae69-838f817c7d74', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When a project''s requirements change mid-development, how do you manage the impact on the existing design?', N'Middle', N'I evaluate the scope of the changes against the current architectural foundation to determine if the existing design is flexible enough to accommodate them. I communicate the impact on the timeline and effort to stakeholders and favor modular changes that minimize disruption to established parts of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1e8af45-1f7b-409d-a4ef-8392357cab8f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are attributes in the context of Lit components?', N'Fresher', N'Attributes are the HTML-level representation of a component''s data. They are typically used for static configuration or passing initial values to components from the parent HTML, and Lit can map these attributes to reactive properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dafcc85-ea48-429f-8a10-83926fe1245a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of Redis Sentinel, and how does it contribute to high availability?', N'Middle', N'Redis Sentinel is a distributed system that monitors Redis instances for failures. If a master node fails, Sentinel automatically performs an election process to promote a replica to master, ensuring minimal downtime and providing automatic failover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'223ca9ea-1830-455f-9d0b-8394c310ab49', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does it mean for a type to implement the Copy trait?', N'Junior', N'A type that implements the Copy trait is copied bitwise when assigned to a new variable rather than being moved. This is typically reserved for simple types like integers or booleans that are stored entirely on the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f06a337d-f86a-4d29-b747-83961ac0a83c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''void'' keyword?', N'Intern', N'The void keyword indicates that a method does not return any value to the caller. It signifies that the method executes its logic without producing a result that needs to be captured or used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ecbf286-1b07-43c6-8a3d-8398bd87bb75', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the advantages of using partitioned tables in PostgreSQL compared to traditional monolithic tables?', N'Senior', N'Partitioning improves performance through partition pruning, where the planner skips irrelevant data segments, and makes data lifecycle management easier via detachment or dropping of old partitions. It is particularly effective for managing very large datasets with time-series or range-based access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa41debc-7bac-45a9-b733-839965a838ee', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a table and an index in DynamoDB?', N'Intern', N'A table is the main collection of items, while an index is a data structure that enables fast querying of data using attributes other than the primary key. Indexes allow for flexible data access patterns without requiring full table scans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f18528be-ab6e-4a07-bfdb-839b4a1a92b2', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How do you handle cross-platform compatibility when working with native dependencies in ASP.NET Core?', N'Senior', N'When using native dependencies, you must ensure that the appropriate binaries are provided for each target platform, typically through conditional compilation or runtime detection. It is also important to use abstractions that can swap implementations based on the underlying operating system to maintain cross-platform portability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11823de9-0c1a-44b8-9289-839c3c51e3a7', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you ensure consistency in a Symfony application that uses multiple database connections?', N'Senior', N'Consistency across multiple connections requires implementing explicit transaction management at the service layer. Since standard database transactions cannot span multiple distinct connections, developers must use the Unit of Work pattern or a distributed transaction coordinator to ensure data integrity during complex operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66641483-4525-4568-b01f-839fb0273db8', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between JIT and AOT compilation in Dart?', N'Intern', N'JIT compilation compiles code during execution, which enables hot reloading and fast development cycles. AOT compilation translates code into native machine code before execution, resulting in faster startup times and better performance for end-users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'910f984a-e473-414b-b126-83a0ff60e657', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle function overloading compared to other languages?', N'Middle', N'TypeScript supports function overloading by providing multiple signatures for a single function implementation. However, unlike traditional compiled languages, the implementation signature must be compatible with all overloads, and the actual execution logic resides in one block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bbdeb31-370b-4769-967f-83a18b6319ad', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle the trade-offs of using a serverless architecture compared to traditional containerized services?', N'Middle', N'Serverless is excellent for event-driven, intermittent, or variable workloads where scaling to zero is beneficial. I avoid it if the application has strict cold-start requirements, requires persistent connections, or if the costs become unpredictable at high, constant traffic levels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f8bebab-1c08-4d1d-af35-83a273418e90', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the Phoenix LiveView framework?', N'Fresher', N'LiveView allows developers to build rich, real-time user interfaces without writing custom JavaScript. It manages the state on the server and pushes updates to the browser over a WebSocket connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16f8b03e-9ae9-4190-9fd1-83a37c0d568f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript’s ''strictFunctionTypes'' flag alter the behavior of function parameter variance?', N'Senior', N'Enabling this flag forces function parameter types to be compared contravariantly rather than bivariantly. This prevents errors where a function expecting a specific subtype is assigned a function that accepts a broader supertype, significantly improving type safety in callback-heavy architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe5c295f-9b0b-4ad0-b6e6-83a592a63705', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''using'' statement in C# and how does it relate to the IDisposable interface?', N'Middle', N'The ''using'' statement provides a syntax-sugar mechanism to ensure that the Dispose method of an object is called automatically when the object goes out of scope. It is used for managing unmanaged resources, such as file handles or database connections, to ensure they are released promptly rather than waiting for the garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1291d46f-23b0-42f5-a932-83a6c5f5a7e1', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between ASP.NET Core and ASP.NET MVC?', N'Intern', N'ASP.NET Core is a modern, modular, cross-platform framework designed for cloud and containerized environments. The older ASP.NET MVC framework is primarily tied to the Windows-only .NET Framework and is considered a legacy technology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'436fcff5-d299-40e0-b421-83a86e76ddd3', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between interceptors and middleware?', N'Fresher', N'In NestJS, both interceptors and middleware can be used to add extra logic before or after HTTP requests. However, they have some key differences: Interceptors: have a more comprehensive scope than middleware. They can be used with both HTTP requests and other types of transport like WebSockets and microservices. Interceptors can also manipulate the response sent back to the client, for example by transforming the response object, adding extra headers, or changing the status code. They can also be used to implement performance tracking, logging, caching, etc. Middleware: in NestJS is similar to Express middleware. It''s specific to the HTTP request-response cycle and can''t be used with other types of transport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4489f3cf-d696-43c1-a03f-83ae7500c709', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of the PHP configuration file?', N'Intern', N'The PHP configuration file, typically named php.ini, is used to configure settings for the PHP interpreter. It controls features like file upload limits, error reporting levels, and extension loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abeb0bdf-d040-41cf-9fe5-83af3f72b057', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle HTTP exceptions?', N'Intern', N'Litestar provides a standardized way to raise HTTP exceptions that include status codes and error messages. When an exception is raised, the framework automatically catches it and returns a formatted JSON response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5937176d-1c35-46ac-bc75-83b1fc756d58', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI ensure that global exception handlers are effective across the entire application?', N'Middle', N'FastAPI allows for defining custom exception handlers that catch specific exceptions thrown anywhere in the request-response lifecycle. By using these handlers, you can ensure a consistent error response structure across all endpoints, separating error logic from the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8512fadd-224c-4e6e-ad3a-83b2b9b024f3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the ''Alpine.store'' feature and its use case.', N'Middle', N'Alpine.store provides a way to define global reactive data that can be accessed by any component on the page. It is best used for state that needs to be shared across the entire application, such as user authentication status, theme preferences, or shopping cart contents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3224774e-1af2-4366-9b77-83b35a64ec5a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is replication in NoSQL?', N'Intern', N'Replication is the process of copying data across multiple nodes or servers. This ensures data redundancy, improves system reliability, and allows the system to remain available even if one node fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bc2f093-a500-4607-badb-83b3b6ac1bda', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the implications of using ''Shadow DOM'' on global CSS performance?', N'Senior', N'Shadow DOM provides CSS scoping, which eliminates the need for naming conventions like BEM and prevents styles from leaking into or out of the component. This improves CSS performance by narrowing the scope of style recalculations and preventing unexpected style overrides that can cause layout shifts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a86cf11-ada4-4828-b261-83b3cb0be076', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the features provided by Vue CLI?', N'Intern', N'VueCLI provides below major features, 1. Interactive project scaffolding via @vue/cli 2. A rich collection of official plugins integrating the best tools in the frontend ecosystem. 3. A full graphical user interface to create and manage Vue.js projects. 4. Zero config rapid prototyping via combination of @vue/cli and @vue/cli-service-global 5. A runtime dependency (@vue/cli-service) built on top of webpack and extensible via plugins', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7848863-486a-4855-923f-83b41e354ad4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the trade-offs between using Interfaces and Type Aliases for defining complex object structures.', N'Senior', N'Interfaces are generally better for defining object shapes because they support declaration merging and provide better error messages in IDEs. Type aliases offer more power through union types, mapped types, and conditional logic, making them preferable for complex functional transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24494497-5085-4507-8abb-83b76c772011', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the ingest node?', N'Junior', N'An ingest node is used to perform common data transformations and enrichments before the document is indexed. It allows users to execute pipelines that can modify fields or format data on the fly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7d47a40-6358-4eb9-b153-83bbe443043e', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Vert.x in the context of Quarkus?', N'Intern', N'Vert.x is a toolkit for building reactive, non-blocking applications on the JVM. It serves as the core engine for the reactive capabilities in Quarkus, enabling high performance and efficient resource usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55ea6fcf-e6b8-4966-bec0-83bc58faf0ec', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can you use standard JavaScript inside SolidJS templates?', N'Fresher', N'Yes, since SolidJS uses JSX, you can use standard JavaScript expressions inside curly braces. This allows for simple logic like mapping arrays or applying conditional classes directly in the template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a77fc1ae-015e-4992-acbc-83be19ed3dd6', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is it important to monitor the ''golden signals'' of a service?', N'Middle', N'The golden signals—latency, traffic, errors, and saturation—provide a comprehensive view of service health. Monitoring these helps identify performance bottlenecks and capacity issues before they impact the end-user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'095d7b4d-f2b0-408e-9191-83c2f0424edd', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the HTML5 ''slot'' element facilitate a micro-frontend architecture?', N'Senior', N'Slots enable the Shadow DOM to act as a placeholder for externally provided content, allowing different teams or micro-apps to inject UI components into a parent host without tight coupling. This promotes encapsulation by ensuring the host container defines the structure while the injected content remains scoped to its own logic and styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fdc9a47-b3a6-483f-afa4-83c444d5768b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix ensure that data remains in sync between the client and server?', N'Senior', N'By mandating that all mutations pass through actions and triggering automatic revalidation of all loaders, Remix creates a ''single source of truth'' pattern. This eliminates the need for manual state synchronization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd101bf45-01df-44b3-b405-83c54e92b967', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the trade-offs between using synchronous and asynchronous replication in a high-availability setup.', N'Senior', N'Synchronous replication ensures zero data loss by waiting for standby acknowledgment, but it introduces latency and availability risks if the standby fails. Asynchronous replication provides better performance and decouples primary performance from network conditions, but it risks data loss during a primary failover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcc61fc0-9cb0-46eb-a5e0-83c7a8c7478c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s approach to hydration differ from traditional frameworks like React?', N'Junior', N'Traditional frameworks perform hydration, which involves downloading and executing all component code to rebuild the application state and attach event listeners. Qwik avoids this by using resumability, meaning it only loads the specific JavaScript required for a user interaction at the moment it happens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4273980-3000-42b6-a26d-83c8a9fb340e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage the ''Flash of Unstyled Content'' (FOUC) during client-side hydration?', N'Senior', N'Because SvelteKit generates static HTML during the server-rendering phase, the browser receives a fully rendered page before the JavaScript bundle executes. The CSS is also extracted and included in the head, ensuring the browser renders the page correctly before any hydration takes place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abd03379-0487-4a15-bb03-83cb2756cf05', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the difference between ''query'' and ''filter'' context in Elasticsearch.', N'Senior', N'Query context evaluates how well a document matches a criterion and calculates a relevance score. Filter context is a binary yes/no check that does not affect scoring and is cached by Elasticsearch for high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc0c5566-edbe-417b-bcdb-83cebeff8542', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi maintain thread safety during high-concurrency request handling?', N'Senior', N'Chi is designed to be immutable once the routing tree is initialized. During the request lifecycle, the router only performs read operations on the radix tree, allowing multiple goroutines to safely traverse the tree concurrently without requiring complex mutex locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b62dc1bf-a1d4-4c2b-b22e-83cfa404879f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''Store'' in SolidJS, and when should it be used?', N'Middle', N'Stores are used for managing complex, nested state objects while maintaining reactivity. They should be used instead of individual signals when you need to update deeply nested data structures without manually traversing and updating every level of the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac169624-f1ef-4264-a75a-83d08c3ffcc3', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What role does the ''Request-Id'' header play in debugging distributed Rails services?', N'Senior', N'The Request-Id provides a unique identifier for each incoming request, which is passed through logs and downstream service calls. This allows developers to trace a single request''s path across multiple internal services, making it essential for troubleshooting in microservices architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'327afa51-f290-470d-b8ac-83d10d934d8d', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the architectural considerations for implementing a ''Backend for Frontend'' (BFF) pattern?', N'Senior', N'BFF isolates the specific needs of different client types (e.g., mobile vs. web) by creating dedicated gateway layers. While it improves performance and tailoring for each client, it introduces code duplication and requires careful management of shared logic to avoid inconsistent behavior across the frontends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75f6cfed-7307-45bb-86f1-83d1cda778a5', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between synchronous and asynchronous execution patterns in PHP, and why is asynchronous support traditionally difficult?', N'Senior', N'PHP was designed for a synchronous, request-response lifecycle where execution blocks until an operation finishes. Asynchronous patterns are difficult because the shared-nothing architecture lacks persistent memory to maintain state across non-blocking I/O operations without specialized extensions like Swoole or ReactPHP.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d842db9-7afd-4a5c-9d3c-83d211c6c2fe', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What role does the ''output buffering'' mechanism play in PHP request handling?', N'Senior', N'Output buffering captures the script''s output in a memory buffer before sending it to the client, allowing developers to manipulate headers even after content has been generated. This is essential for features like dynamic compression and template rendering where parts of the response may need to be rewritten.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24d215b1-e5a0-4de7-8a57-83d369e25b5f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''this'' keyword binding change in strict mode vs. non-strict mode?', N'Senior', N'In non-strict mode, a standalone function call sets ''this'' to the global object, which is a major source of bugs. In strict mode, ''this'' is set to undefined, encouraging better coding practices and preventing accidental pollution of the global namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'092543c2-8c58-4cb4-934b-83d3700eb68d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of ''Bundler''?', N'Fresher', N'Bundler is a tool that manages an application''s dependencies by installing the exact gems specified in the Gemfile. It ensures that every developer on a team is using the same library versions, preventing environment-related issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4d1853a-91f5-406d-b02a-83d704cfa15d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the trade-offs of using NestJS Microservices vs. a standard monolith with event-driven communication.', N'Senior', N'Microservices offer independent deployment and technology stack flexibility but introduce significant operational overhead regarding network latency, distributed tracing, and data consistency. A monolith with event-driven communication is easier to maintain initially but may face scaling bottlenecks if the internal event bus becomes a single point of contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2f1f83f-8b81-4999-a466-83da18b56a7d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between ''$'' and ''$:'' in Svelte?', N'Junior', N'The ''$'' prefix is used to access the current value of a store, while ''$:'' is used to define reactive declarations that automatically recalculate when their dependencies change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36b3e61a-6574-48a8-ab68-83e21a03492e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why is it generally discouraged to use global variables in Go applications?', N'Middle', N'Global variables create hidden dependencies between components, making the code harder to test, reason about, and parallelize. They also present significant challenges for concurrency, as protecting global state requires synchronization primitives that can become major bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f85f7c9-6671-4392-8ed9-83e25c4270a4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s routing architecture differ from traditional frameworks?', N'Middle', N'Axum uses a tree-based router that allows for nesting and modularity through service composition. This enables developers to attach middleware to specific routes or groups of routes rather than applying them globally to the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e7ff7af-4ce3-411f-9a63-83e5672a4fa0', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are server-side load functions and when should you use them?', N'Junior', N'Server-side load functions run exclusively on the server, which is useful for accessing databases or private API keys securely. They prevent sensitive logic from being exposed in the browser''s bundle, enhancing both security and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a824d3de-b6a5-43a9-af3e-83e6278c6f58', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the risk of having ''hard-coded'' credentials in your application?', N'Fresher', N'Hard-coding credentials is a major security risk because the passwords become visible to anyone who has access to the source code. If the code is shared or pushed to a public repository, the system becomes immediately vulnerable to unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fef81f28-89f9-45a5-8306-83e7213f5014', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is it beneficial that Hono uses the Request and Response objects from the Fetch API?', N'Middle', N'Using standard Web API objects makes the framework more predictable and interoperable with other web tools. It reduces the learning curve for developers familiar with browser-native APIs and ensures compatibility with various modern JavaScript runtimes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7189104f-74ba-4259-80c3-83e8e1557f95', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between interface merging and type alias union types in TypeScript?', N'Middle', N'Interface merging allows you to declare the same interface multiple times, where the compiler automatically combines them into a single definition. In contrast, type aliases cannot be redeclared and are better suited for defining complex union, intersection, or mapped types that interfaces cannot represent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca890686-2dc9-4244-8fcb-83e97311d963', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the role of the ''c'' function in R?', N'Intern', N'The ''c'' function stands for ''combine'' and is used to create vectors by joining individual elements together. It is one of the most frequently used functions for initializing data structures in R.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa82322e-42c4-4ebe-b241-83ea2f41fd39', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s router perform path matching, and what is the impact on performance?', N'Middle', N'Echo uses a highly optimized radix tree algorithm to manage routes, which ensures that lookups remain fast even as the number of registered routes grows. This structure is significantly more efficient than linear array-based routing, as it reduces the time complexity of finding a matching handler to proportional to the length of the URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'140613b4-4471-4aba-94cb-83eb1e21eed1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the number of windows in a large city?', N'Intern', N'I would start by estimating the average number of windows per building type, such as residential, commercial, and industrial. I would then estimate the number of buildings of each type in the city based on population density and land area. Multiplying these figures provides a reasonable order-of-magnitude approximation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'059a8808-7169-43cf-bdeb-83ed99805718', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s implementation of ''Sub-apps'' improve the maintainability of large-scale monoliths?', N'Senior', N'Sub-apps allow for the decomposition of a large application into modular, independent routing trees that can be mounted under specific paths. This improves maintainability by allowing teams to own and test specific sub-apps in isolation without interfering with the global routing configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd52086e0-6a88-471c-8232-83ef3f0877b0', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the trade-offs of using Laravel''s Broadcast system versus traditional polling for real-time features.', N'Senior', N'Broadcasting via WebSockets provides near-instantaneous updates and reduces server load by eliminating frequent polling requests. However, it introduces infrastructure complexity, requiring a WebSocket server and proper authentication handling, whereas polling is easier to implement but scales poorly and adds significant latency to updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1a9c7ba-fbdc-4483-9906-83f0b14e46de', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does String deduplication in the G1 GC differ from the String Intern pool?', N'Senior', N'String intern uses a global hash map to ensure all references point to a single literal instance, which is manually managed. String deduplication is an automated G1 background process that identifies identical char arrays in the heap and points them to a single backing array, reducing footprint without changing object identities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5da76a7-f75b-41eb-8ad6-83f116226db9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What does it mean for Gin to be ''high-performance''?', N'Intern', N'Being high-performance means Gin is optimized for speed and low memory usage, primarily due to its efficient custom routing algorithm. This makes it suitable for building services that need to handle a high volume of concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ce60e25-5be7-4c10-8da3-83f15f7eb4a2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What does ''Tunable Consistency'' mean?', N'Intern', N'Tunable consistency allows developers to choose the level of consistency for each individual read and write operation. You can balance between strong consistency and low latency depending on the specific application requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abfa77e4-b5fb-4ed8-b1b3-83f180c6ffe6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a ''thunk'' in the context of Redux?', N'Junior', N'A thunk is a middleware that allows you to write action creators that return a function instead of an action object. This is commonly used to handle asynchronous logic, such as API calls, before dispatching the final action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f8040e1-3764-4b3e-8256-83f21452db1a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is Litestar''s design considered more ''opinionated'' regarding the use of Dataclasses and Pydantic?', N'Senior', N'Litestar is built to be agnostic but offers first-class support for both Dataclasses and Pydantic, enforcing strict typing across the board. By preferring structured data types over generic dictionaries, it forces developers to define explicit schemas, which improves robustness and simplifies automated documentation generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
