INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd05e7167-a5aa-4bcb-b553-83f3c31b0d22', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro often described as a ''Content-Driven'' framework?', N'Fresher', N'Astro is designed to prioritize content delivery. It assumes that most websites are document-based, so it optimizes the delivery of text and media rather than focusing on complex, highly interactive application states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'613d1e29-1ab4-49fa-9325-83f4de17954e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot’s auto-configuration mechanism detect when to apply specific configurations?', N'Senior', N'It relies on the @EnableAutoConfiguration annotation, which triggers a search for META-INF/spring.factories files. It then uses conditional annotations like @ConditionalOnClass or @ConditionalOnMissingBean to verify the classpath and existing bean definitions before applying configuration classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52e914a1-238a-497a-85c8-83f4e6ada1d6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is atomicity in database transactions?', N'Fresher', N'Atomicity ensures that a transaction is treated as a single unit of work. Either all the operations within the transaction are successfully completed, or none of them are, preventing partial data updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b14e49e-1371-42b7-90c2-83f68d08de92', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between relative and absolute positioning?', N'Intern', N'Relative positioning places an element according to its normal flow in the document. Absolute positioning removes the element from the document flow and positions it relative to its nearest positioned ancestor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b19faa5f-c435-407f-a769-83f80c4b46a8', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you optimize the ''Time to First Byte'' (TTFB) in a Next.js application that relies on multiple external microservices?', N'Senior', N'TTFB can be optimized by using parallel data fetching patterns and caching strategies like SWR or ISR. Additionally, moving API aggregation logic to the server layer minimizes round-trips from the client and allows for faster internal network communication between the Next.js server and microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d151666-d08e-4097-a864-83f85e74acb6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is it important to remove event listeners after use?', N'Fresher', N'In JavaScript, you need to be mindful of removing event listeners to avoid memory leaks — especially in long-lived apps like single-page applications (SPAs) or when working with frameworks/libraries. Eventhough JavaScript has automatic garbage collection, memory leaks can still happen if: 1. A DOM element is removed, but a listener still references it. 2. A callback (event listener) holds a reference to a large object or closure that can''t be cleaned up. 3. Global objects like window, document etc retain listeners indefinitely unless manually removed. So if you add any event listeners to DOM element, it is a good practice to remove it after its usage as shown below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afc6a079-eda6-47a5-ae45-83fa4f9100c9', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What happens if you have a syntax error in your code while using Vite?', N'Junior', N'Vite will display an error overlay directly in the browser during development. This provides immediate feedback, allowing you to see the error and the location in the code without needing to check the terminal console.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f68dc0f1-52e6-486e-9e02-83ff5e0a7860', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is meant by duck typing in Ruby?', N'Intern', N'Duck typing is a programming concept where an object''s suitability is determined by the presence of certain methods rather than its actual class. If it walks like a duck and quacks like a duck, Ruby treats it as a duck, focusing on behavior over strict type checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51efe4f5-5724-48e2-a456-84005b7118af', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How should an API handle errors to ensure they are actionable for the client while protecting internal system details?', N'Senior', N'Use standard HTTP status codes mapped to internal error types, and provide a consistent error body containing a unique request ID, a machine-readable error code, and a human-readable message. Never leak stack traces or database schema information in the response, as this aids potential attackers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'321109b3-436a-432b-87fd-8401dfbcec83', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle JSON serialization?', N'Intern', N'FastAPI automatically converts Python objects, such as dictionaries or Pydantic models, into JSON format for HTTP responses. Conversely, it validates and converts incoming JSON request bodies into Python objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d39a9c7-a512-41bf-b2b7-8403701e02d3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can you have transactions across multiple NoSQL nodes?', N'Junior', N'While it is more complex than in single-node systems, some modern NoSQL databases support distributed transactions. However, these often come with significant performance trade-offs compared to local transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1823358-deee-4085-b710-840649e84190', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django view and how is it created?', N'Intern', N'A Django view functions as an endpoint for web requests. It retrieves data from a database, processes it as needed, and then returns a response, which can be an HTML page, a redirect, or a JSON object, among others. Types of Views - Function-Based Views (FBV): These are created using functions. - Class-Based Views (CBV): These are created using classes and offer a more structured approach, often with built-in features like HTTP method handling and view mixins. Steps to Create a Django View 1. Define the View Function or Class: This entails specifying the unique logic for the view. In the case of a function-based view, it''s a Python function with the @ decorator and an HTTP method. For a class-based view, you define a class with specific method names for different HTTP methods. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b824276-0fce-48ab-bafd-84092207cef8', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a cross join?', N'Fresher', N'A cross join produces a Cartesian product of the two tables involved. It returns the number of rows equal to the product of the number of rows in both tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf9c3147-ceb9-49fe-80b4-840b97d4c9fa', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the trade-offs of using a high replication factor?', N'Middle', N'A high replication factor increases fault tolerance and read availability because data exists on more nodes. However, it also increases storage requirements and write latency, as every write must be propagated to a larger number of replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98107118-8455-466c-9285-840dd2302473', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you distinguish between metrics, logs, and distributed traces in an observability strategy, and when should you prioritize each?', N'Middle', N'Metrics provide numerical snapshots for alerting and trend analysis, while logs offer granular event-level detail for debugging specific failures. Distributed traces track the path of a request across multiple services to identify bottlenecks in complex architectures. You should prioritize metrics for real-time health monitoring, logs for post-mortem analysis of failures, and traces for troubleshooting latency issues in microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de2a8aec-a187-4a2d-a98d-840e1510906d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where a security patch requires a breaking change in an upstream dependency?', N'Middle', N'I prioritize the security patch and allocate time to refactor the code to accommodate the breaking change. I use the transition period to conduct thorough regression testing to ensure that the security fix does not introduce instability in dependent components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61df5890-c765-4098-b54b-840e66a392b9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the mechanics and potential pitfalls of using ''any'' versus ''unknown'' in a large-scale codebase.', N'Senior', N'The ''any'' type disables type checking entirely, which can lead to runtime errors and loss of type safety across layers. ''unknown'' is the type-safe counterpart that forces explicit narrowing before usage, preventing unsafe operations and improving code robustness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de39baab-54e7-4aa1-916c-8411c83278da', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary benefit of Echo''s radix tree-based router over a standard map-based implementation?', N'Senior', N'A radix tree allows for efficient prefix-based routing and path parameter extraction with O(k) complexity, where k is the length of the path. This is significantly more memory-efficient and performant than map-based routing when dealing with large numbers of dynamic, parameterized routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50af3f65-2dcd-493d-b803-8416615ebe15', N'4c000000-0000-0000-0000-000000000005', N'What is the role of a CDN in system architecture?', N'Middle', N'A Content Delivery Network (CDN) caches static content such as images, CSS, and videos on edge servers located closer to the end user. This significantly reduces latency and offloads traffic from the origin server, improving the overall user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9000b31-a6ce-4d09-9354-8419788c6d39', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Kestrel server?', N'Junior', N'Kestrel is the cross-platform, lightweight web server included by default in ASP.NET Core. It is designed to be used as an edge server or behind a reverse proxy like Nginx or IIS to handle incoming HTTP traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781aec0a-95ba-4ce0-a2e1-84199a114257', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you use ''Lazy Services'' in Symfony?', N'Middle', N'Lazy services are only instantiated when they are actually accessed, rather than when the container is built. This improves performance by reducing the initialization time and memory usage for services that are not always needed during a request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15cae69d-13ca-45fd-8198-841a156536aa', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte facilitate integration with legacy DOM manipulation libraries?', N'Senior', N'Svelte provides direct access to DOM nodes through actions and element references, allowing developers to safely wrap legacy libraries. Because Svelte does not manage the DOM via a virtual layer, these external libraries can manipulate the DOM directly without causing conflicts with the framework''s internal state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
