INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acd19bba-9ef9-43b8-b5a5-841c0b4a66df', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is an optional property in an interface?', N'Intern', N'An optional property is a member of an object that does not need to be present for the object to satisfy the interface. It is marked using a question mark after the property name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e45e0875-910c-4d40-bdb0-841fc4d2dedb', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can you destructure props in SolidJS?', N'Intern', N'You should not destructure props in SolidJS because it breaks the reactive connection. If you destructure them, you lose the signal functionality, and the component will not update when the props change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
