INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd540ac42-b013-4980-b45a-84245e8a7575', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the features of create react app?', N'Intern', N'Below are the list of some of the features provided by create react app. 1. React, JSX, ES6, Typescript and Flow syntax support. 2. Autoprefixed CSS 3. CSS Reset/Normalize 4. A live development server 5. A fast interactive unit test runner with built-in support for coverage reporting 6. A build script to bundle JS, CSS, and images for production, with hashes and sourcemaps 7. An offline-first service worker and a web app manifest, meeting all the Progressive Web App criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ade9c1b-595d-406f-80c9-8427b76a2b2b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ACID stand for in database systems?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These are the four essential properties that guarantee reliable transaction processing in a database system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3abfd8fc-341b-4094-a7dc-842979e75b68', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle schema evolution in a messaging system to avoid breaking consumers?', N'Senior', N'Use a schema registry to manage versions and enforce compatibility rules (e.g., forward or backward). Producers should only publish messages that adhere to these rules, and consumers should be designed to ignore unknown fields to ensure system stability during deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a4eaef5-cfc6-4974-939e-842a8164e2cd', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''Transition'' in SolidJS?', N'Middle', N'Transition allows you to mark state updates as non-urgent, preventing the UI from showing loading states immediately if the transition is fast enough. It helps in keeping the UI responsive during concurrent updates, avoiding unnecessary flickering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52d914d6-e28a-48ed-a0b9-842f95dd5426', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is it often recommended to use an auto-incrementing integer as a primary key in InnoDB, and how does it relate to B-tree fragmentation?', N'Senior', N'InnoDB stores data in a clustered index sorted by the primary key. Using a non-sequential primary key, like a UUID, causes frequent page splits and massive rebalancing of the B-tree as new data is inserted into random locations, leading to fragmentation and decreased write performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a1ac414-a321-4e30-a0ad-842f9e6c561c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is Cargo in the context of Rust?', N'Intern', N'Cargo is Rust''s official build system and package manager. It handles tasks such as downloading dependencies, compiling your code, generating documentation, and running tests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2ae0419-9cd2-4c7e-87bb-84302de902ff', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it important to define routes in a specific order in some frameworks, and does Gin have this constraint?', N'Junior', N'Some frameworks require specific ordering if they use regex-based routing. Gin''s Radix tree router is generally order-independent for static routes, but overlapping patterns should still be carefully managed to ensure the correct handler is matched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4967c252-7d56-4b4c-b3de-843101e05cc6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do you evaluate the trade-offs between using Module Federation versus standard shared library bundling in a large-scale micro-frontend architecture?', N'Senior', N'Module Federation enables independent deployment and runtime dependency sharing, which drastically reduces build times and allows teams to ship features autonomously. However, it introduces significant complexity in version management and shared context handling, potentially leading to runtime conflicts if dependency versions are not strictly aligned. Standard bundling ensures consistency and type safety through a monolithic dependency graph but creates tight coupling, forcing redeployments of all consuming applications whenever a shared core utility is updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e21f543-d2c6-40ee-a3c3-8434026ae443', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of ''Mutiny'' in Quarkus?', N'Middle', N'Mutiny is the reactive programming library used in Quarkus for handling asynchronous data streams. It provides an intuitive, fluent API for composing reactive operations, making it easier to manage complex asynchronous flows without ''callback hell''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43b89adc-b810-4cd4-8625-8434aae31b4b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite need a separate server to run in production?', N'Fresher', N'No, Vite produces static files like HTML, CSS, and JavaScript. These files can be hosted on any standard web server or static site hosting service; no specialized Node.js server is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b358f9c-6af1-45d9-9a78-8439711848f0', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is the scan operation discouraged for large-scale production workloads?', N'Senior', N'A scan operation iterates through every single item in the entire table, consuming massive amounts of read capacity and introducing high latency. It is an O(N) operation that does not scale well as the dataset grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35fbaf04-e0d6-4aca-a305-84398c9a4cd6', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you ensure data consistency between a database update and a message queue publication?', N'Senior', N'The most robust approach is the Transactional Outbox pattern, where messages are saved to a local database table in the same transaction as the business data. A separate process then polls this table or reads the transaction log to publish the messages to the broker, ensuring atomicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fe1f101-6d17-4b65-902c-843a9f8c7672', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why does Ember use the ''Adapter'' and ''Serializer'' pattern?', N'Junior', N'Adapters and Serializers separate the concerns of data communication. The Adapter handles how to communicate with the API server, while the Serializer defines how to translate the raw JSON response into the format Ember Data expects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0d1e818-4486-42cf-a0ff-843b802ddfe4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a table and a view in PostgreSQL?', N'Fresher', N'A table is a database object that physically stores data in rows and columns on the disk. A view is a virtual table that does not store data itself but instead provides a saved query that retrieves data from underlying base tables whenever it is accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb85108-82b7-4325-8fbf-843d79bcca8a', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express maintain state between requests?', N'Intern', N'Express is stateless by default, meaning it does not automatically remember information about the user between requests. State is typically maintained using external mechanisms like sessions, cookies, or database storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'628191dd-3f48-4905-8dde-843dba34d155', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between the ''val'' and ''var'' keywords in Kotlin?', N'Junior', N'The ''val'' keyword is used to declare read-only variables, meaning the reference cannot be changed after the initial assignment. In contrast, ''var'' is used for mutable variables, allowing the value to be reassigned at any point during execution. Using ''val'' is preferred whenever possible to promote immutability and reduce potential bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f6ec09a-0584-445b-920b-843e0dae9d51', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How are environment variables typically handled in a Fastify app?', N'Junior', N'While not strictly part of the core, developers typically use plugins like ''fastify-env'' to load and validate environment variables at startup. This ensures that the application fails early if required configuration is missing, preventing runtime errors later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a65d161-f1a8-41d5-bd83-8442d0ef1ebd', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is testing in Fiber often done using the ''app.Test'' method?', N'Middle', N'The ''app.Test'' method allows developers to simulate HTTP requests directly against the application instance without opening a network socket. This makes unit tests significantly faster and more reliable, as they bypass the OS networking stack entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e98ac1d-16ea-4cfc-ad40-8445d9ffe312', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is NULL in a database?', N'Junior', N'NULL represents a missing or unknown value in a database field. It is important to remember that NULL is not the same as zero or an empty string, and special operators must be used to check for its presence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
