INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a834c38-1903-4eda-84fa-84482c1a78f3', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is ''request context'' teardown critical in Flask, and what are the consequences of failing to handle it?', N'Senior', N'Teardown functions are responsible for cleaning up resources, such as closing database sessions or clearing cached buffers, when a request cycle ends. Failure to handle this correctly leads to resource exhaustion, such as database connection leaks, which can eventually crash the application process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f17df1d2-6e12-4458-9634-8449ff0c1393', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why are ''Clone'' requirements common for Axum application state?', N'Middle', N'Because handlers are often executed in parallel across different threads, the state must be clonable to be passed into each handler instance. A shallow clone of an ''Arc'' is cheap and provides thread-safe access to the underlying data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35a821ac-ebd5-40e4-9077-844b51cd65ea', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do Template Literal Types improve type safety?', N'Middle', N'Template literal types allow you to define types based on string patterns by combining literal types. They are useful for enforcing strict naming conventions, such as keys in an object or specific event names, at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'597ba805-c0b1-469a-a2a2-844cca022754', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the ''autovacuum'' daemon prevent transaction ID wraparound?', N'Senior', N'PostgreSQL uses 32-bit transaction IDs, which will eventually wrap around; if they do, data becomes invisible. Autovacuum monitors the age of tables and forces aggressive vacuuming to update the frozen transaction ID markers, ensuring data visibility is maintained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6659ab50-c635-4bbe-9ff7-844d41612c65', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the ''silent'' comment in Sass?', N'Intern', N'A silent comment begins with double slashes and is only visible in the original Sass file. It is ''silent'' because it is not included in the final, compiled CSS file, keeping the production code clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
