INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9474e02d-f1e4-4f92-ab73-845194c3a0ac', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the page.server.js file in a SvelteKit application?', N'Junior', N'The page.server.js file is used to define a load function that runs exclusively on the server before a page is rendered. It is primarily used for fetching data from databases or APIs securely, ensuring that sensitive logic or credentials remain on the server and are never exposed to the client-side bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
