INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d5ea580-898c-4774-9431-8452f2bc9b87', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you handle background tasks in a Hono application running on a serverless platform?', N'Middle', N'Since serverless functions terminate after the response is sent, background tasks should be offloaded to external message queues or event-driven services like Cloudflare Queues or AWS SQS. Hono should only trigger these tasks rather than executing them within the same request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
