INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e16480b-ec20-4684-b61c-8459d5b3e219', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What happens if a transaction is left open for a long time in PostgreSQL?', N'Middle', N'Long-running transactions prevent the autovacuum process from cleaning up dead tuples that were created after the transaction started, leading to table bloat. This can cause performance degradation and, in severe cases, transaction ID wraparound issues that could force a shutdown of the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
