INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cc7dde3-8f93-47d9-8dd2-8468f61fd421', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the performance implications of using Ruby symbols as hash keys?', N'Middle', N'Symbols are immutable and unique identifiers in Ruby''s memory space, meaning the same symbol object is reused throughout the application. Using symbols as hash keys is more memory-efficient and faster than strings because it avoids repeated object allocation and string comparison. This is standard practice in Ruby for configuration and data keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e75cb8f-d809-4c19-9b5b-84696d266270', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How are responses handled in Axum?', N'Intern', N'Handlers return types that implement the IntoResponse trait, which defines how to convert a value into an HTTP response. This allows developers to easily return various types like strings, JSON objects, or custom status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'991cecc3-0ddc-4c18-9b9a-84715bbf513a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you handle configuration management in a multi-environment Symfony setup?', N'Senior', N'Symfony uses environment variables combined with configuration files specific to the environment (dev, test, prod). This ensures that sensitive credentials and performance-tuning settings are externalized and injected via the environment, adhering to 12-factor app principles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ab3980b-c544-4c67-8825-8472d908d3e1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it important to keep the Redux state immutable?', N'Intern', N'Immutability ensures that state changes are predictable and easy to track. It allows Redux to efficiently detect changes, which is necessary for performance optimizations like preventing unnecessary re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0976812-51ad-4de0-b64a-84740f02fdb4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Does NoSQL support ACID properties?', N'Fresher', N'Traditionally, NoSQL databases prioritized performance over strict ACID compliance, opting for BASE (Basically Available, Soft state, Eventual consistency). However, many modern NoSQL databases have introduced ACID support for specific use cases and operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e9dd2ee-fc9c-4b25-af50-847597039d06', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of ''Covering Indexes'' and why they are effective for read-heavy workloads.', N'Senior', N'A covering index contains all the columns requested by a query, allowing the database to satisfy the request entirely from the index tree. This avoids the need to perform additional lookups into the heap or clustered index, significantly reducing I/O overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eae2773-80eb-498b-b233-8476cc2d1205', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why are transactions important in NoSQL databases?', N'Intern', N'While many NoSQL databases prioritize availability and speed, transactions remain important for maintaining data integrity. Some NoSQL systems offer multi-document transactions, while others rely on single-document atomicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28c3eaea-2df7-400d-9f3c-8478ca5a37bb', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle error boundaries for server-side requests?', N'Senior', N'Nuxt provides a unified error handling system that catches errors during the server-side lifecycle and renders a custom error page. Developers can use the ''useError'' composable to handle and display these errors gracefully, ensuring that a single failing request does not crash the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6717e69-ea7c-4fbe-b270-8478dcc51d82', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the Dart SDK?', N'Intern', N'The Dart Software Development Kit is a set of tools and libraries required to develop Dart applications. It includes the Dart compiler, the Dart VM, and the package manager known as Pub.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c9939c-b30b-4104-92fc-847a321f5ea1', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the limitations of jQuery''s animation module in the context of modern browser hardware acceleration.', N'Senior', N'jQuery animations primarily rely on JavaScript-based timers and changing style properties like top or left, which are CPU-intensive and trigger layout shifts. Modern standards prefer CSS transitions or the Web Animations API, which can be offloaded to the GPU for smoother performance and better battery efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ca12907-5456-4c5c-8c78-847b6784a5ea', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the risk of having ''single points of failure'' in a project?', N'Intern', N'A single point of failure is a component whose failure would cause the entire system to stop working. This creates a high risk of downtime, as there is no backup or alternative path for the system to follow. Identifying and removing these points is essential for building a resilient and reliable system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69d64329-1de7-4af1-96b7-847bfbf7ad8b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a foreign key in a relational database?', N'Fresher', N'A foreign key is a field in one table that refers to the primary key in another table. It creates a link between two tables, ensuring referential integrity by preventing actions that would destroy links between data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a4c16d1-887c-491d-9969-847c4ee02eba', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''untrack'' function used for?', N'Middle', N'The untrack function allows you to read a signal''s value without creating a reactive dependency. It is useful when you need to access a signal''s current value inside an effect or computed without triggering an update when that specific signal changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5095da3b-450c-4f39-a236-847e6995158d', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the App Router in Next.js?', N'Intern', N'The App Router is a routing system introduced in newer versions of Next.js that uses the file system to define routes. It utilizes React Server Components by default and offers more advanced data fetching and layout capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f472f41c-a12d-42a4-9851-847ea5231f53', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How does API caching strategy differ between Edge caching and Application-level caching?', N'Senior', N'Edge caching offloads traffic from the origin server by serving static or semi-static content closer to the user via CDN. Application-level caching, such as Redis, focuses on reducing database load for expensive queries or computed business logic, providing more granular control over cache invalidation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c37a4417-4408-4a03-ad72-847fbdb6fa21', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What happens if you do not call next() in middleware?', N'Fresher', N'If you do not call next() and you do not send a response to the client, the request will hang indefinitely. The client will eventually time out because the server never completed the response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
