INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bf97782-165e-477b-98a9-848a035bdd9f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the concept of ''Tracked Properties'' in modern Ember and how they differ from older Observer patterns.', N'Senior', N'Tracked properties use native JavaScript getters and setters to automatically detect dependencies without the need for manual ''propertyDidChange'' notifications. This eliminates the ''observer hell'' associated with older versions of Ember, resulting in less boilerplate and fewer bugs related to stale state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
