INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50933539-6c57-4576-a9cb-848db1a6dea9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'You find a security vulnerability in a dependency. How do you handle it?', N'Junior', N'I immediately notify my team and check if there is an official security patch or a newer version of the dependency available. If no patch exists, I evaluate the impact of the vulnerability and look for workarounds or alternative libraries to mitigate the risk until a permanent fix is available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'504fc33a-93ab-4862-9a25-8490cbcee856', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''universal'' rendering mode in Nuxt?', N'Fresher', N'Universal rendering is the default mode where Nuxt performs server-side rendering for the initial page load to ensure speed and SEO, and then switches to client-side navigation for subsequent interactions, providing a fast and smooth user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c202fa76-ff8b-4819-ba83-8492fa2e24cc', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the trade-offs of using template metaprogramming?', N'Middle', N'Template metaprogramming allows for highly generic code and compile-time optimizations that can significantly improve performance. However, it leads to longer compilation times, produces notoriously difficult-to-read error messages, and increases the complexity of the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ea9a475-75ab-45b1-b976-849328dd5a3e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the trade-offs of the ''Global Event Delegation'' pattern used in Qwik?', N'Senior', N'By using a single global event listener at the document level, Qwik avoids attaching listeners to individual DOM elements, which reduces memory usage and prevents reconciliation issues. The trade-off is the need for a lookup mechanism to map event targets to the corresponding serialized functions, which requires careful management of event propagation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e06364-8404-4ab7-8877-8493b7f2e9e6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the function of the CRAN repository?', N'Intern', N'CRAN, or the Comprehensive R Archive Network, is a global network of servers that store identical, up-to-date versions of R code and documentation. It serves as the primary repository for installing R packages and the base software itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98f8d5fa-3eeb-45d4-843a-84948497ace0', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''lock'' statement in C# map to underlying synchronization primitives?', N'Senior', N'The lock statement is syntactic sugar for Monitor.Enter and Monitor.Exit, which interact with the SyncBlockIndex in an object''s header. It provides a reentrant mutual exclusion lock, allowing the same thread to acquire the lock multiple times without deadlock.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b2822c3-da46-4152-808a-84955e6b8d98', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does sharding improve performance in a NoSQL database?', N'Middle', N'Sharding distributes data across multiple servers or nodes, preventing any single node from becoming a bottleneck. This horizontal scaling allows the system to handle larger datasets and higher throughput by parallelizing read and write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09d37e7a-10b7-4a26-931f-84977800c74b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the trade-offs of using ''Any'' versus generics in Swift.', N'Middle', N'Using ''Any'' sacrifices type safety and requires constant type casting, which is error-prone and impacts performance. Generics enforce type safety at compile time and allow the compiler to generate specialized code, resulting in better performance and cleaner, more reusable abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'040b2173-dd9c-400b-bc90-849be32d393b', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is ''graceful degradation''?', N'Middle', N'Graceful degradation is the ability of a system to maintain limited functionality when parts of it are failing. Instead of failing completely, the system might disable non-essential features to ensure that core operations remain available to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37f5282a-3d06-404a-a2b8-849fdfc58be9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s performance compare to other async frameworks like FastAPI?', N'Middle', N'Litestar is designed for high performance, often outperforming alternatives due to its efficient request routing and minimized overhead in the internal dispatch mechanism. It is built to maximize the throughput of ASGI-compliant servers while maintaining strict type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c0a5d82-7afa-47a5-8392-84a1ba11f3e8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain how AdonisJS''s configuration system supports multi-environment deployment strategies.', N'Senior', N'The configuration system leverages environment variables and environment-specific files, allowing the same code base to behave differently based on the deployment target. This separation ensures that sensitive credentials and performance-tuning parameters can be managed externally, promoting security and operational flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8255a4ff-2ebd-4543-9447-84a4128b5ddd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the reason to deprecate Web Tracing Framework?', N'Intern', N'Angular has supported the integration with the Web Tracing Framework (WTF) for the purpose of performance testing. Since it is not well maintained and failed in majority of the applications, the support is deprecated in latest releases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc142b7-4e75-4c29-b1fd-84a4da15810f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is ''asynchronous'' programming important for a backend framework?', N'Intern', N'Asynchronous programming allows the backend to perform I/O-bound tasks—like querying a database or calling external APIs—without blocking the entire server. This leads to significantly higher throughput and better performance under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd573a6af-2383-4b66-9bff-84a5b880c774', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''Template Literal Type'' feature and in what architecture scenarios is it most useful?', N'Senior', N'Template literal types allow you to construct new string types by concatenating literals or union types at compile time. They are highly effective for modeling complex string patterns such as CSS utility class names, localized keys, or specific API endpoint path segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e23c401f-0a24-48a6-93cf-84a750e13e41', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is it recommended to use ''browserslist'' in conjunction with Webpack?', N'Middle', N'Browserslist provides a centralized way to define the target browsers for your project. Webpack-compatible tools like Babel and Autoprefixer use this list to automatically apply necessary polyfills and CSS prefixes, ensuring your application supports the required browsers without unnecessary overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be40f4f9-53ed-44a5-8748-84ab966ac5ba', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What happens if you don''t use a client directive in Astro?', N'Fresher', N'If no client directive is used, the component will render as static HTML on the server and will not have any interactive JavaScript functionality in the browser. It will effectively be a plain HTML element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
