INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c59a6c6-5332-4c1b-bd0d-84af0caefa1d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is a ''dead letter queue'' in messaging systems?', N'Middle', N'A dead letter queue is a destination for messages that cannot be successfully processed by the intended consumer after a certain number of attempts. It allows developers to isolate problematic messages for manual inspection without blocking the processing of other valid messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
