INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62ac34c3-6d55-4b66-b0a5-84bc6adc087f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is function execution context?', N'Intern', N'Whenever a function is invoked, the JavaScript engine creates a different type of Execution Context known as a Function Execution Context (FEC) within the Global Execution Context (GEC) to evaluate and execute the code within that function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bd5bafb-1f27-4555-8d02-84bcd721eafc', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the limitations of the virtual DOM in extremely large lists.', N'Senior', N'In very large lists, the virtual DOM must still perform diffing on all elements if the list is not properly keyed or virtualized. Without windowing techniques that only render visible items, the memory usage and reconciliation time will scale linearly with the list size, causing performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
