INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ab7172b-7a38-4a63-9f4a-84c20f794c76', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is ''Partition Key'' design the most critical factor for performance in a Cassandra data model?', N'Senior', N'The partition key determines which node in the cluster holds the data; poor design leads to hot partitions where one node receives disproportionate traffic. Effective partitioning ensures an even distribution of data and requests across the cluster, preventing bottlenecks that degrade overall throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
