INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d7eb1b6-426b-4646-8b6e-84c4dcc9d545', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What steps do you take when you encounter an error message you have never seen before?', N'Junior', N'I start by searching the error message in documentation and developer forums to see if others have faced the same issue. I then analyze the stack trace to pinpoint which part of the system triggered the error and verify if there were any recent environment changes that could be the root cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d96bd04-0ff4-4492-ac8c-84c5c5664eb7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the trade-off of using surrogate keys versus natural keys?', N'Middle', N'Natural keys are based on real-world data but can become problematic if the business rule defining the key changes. Surrogate keys are system-generated, immutable, and provide a stable reference that is decoupled from business logic, though they require additional indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a30d3e43-8f3c-4d0f-88a7-84c68e5daee3', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the C# ''async/await'' state machine handle context switching and thread affinity?', N'Senior', N'The compiler transforms async methods into a state machine that tracks execution progress. By default, the state machine captures the SynchronizationContext, ensuring the continuation runs on the original thread if available. This avoids blocking threads, though developers must manage potential deadlocks by configuring awaiters to ignore the context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f470b445-61e3-44ca-95b9-84c83a26c57b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @import rule in Sass?', N'Intern', N'The @import rule allows you to split your CSS into smaller, manageable files and combine them into one single output file. It helps keep your project organized by allowing you to separate styles for different components or layouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4959fdd3-9861-402c-98ff-84cb0d950cbf', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the difference between clustered and non-clustered indexes in terms of data storage and performance.', N'Senior', N'A clustered index determines the physical order of data in the table, meaning there can only be one per table. Non-clustered indexes are stored separately from the data rows and contain pointers to the clustered index or the heap, making them faster for lookups but requiring an extra step to fetch the full row.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05217ff1-19f7-442d-998a-84cc10a7b249', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the advantages of using Sass over plain CSS for a large team?', N'Fresher', N'Sass provides a structured way to manage styles through partials, variables, and mixins, which is essential for large teams. It ensures that everyone follows the same design system and reduces the risk of conflicting styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90418ac2-e116-4270-b0ae-84ced7cdad8a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik sometimes described as ''zero-bundle'' architecture?', N'Middle', N'It is not literally zero-bundle, but rather ''zero-load-at-start.'' The framework aims to send only the bare minimum of JavaScript needed to make the page interactive, effectively keeping the initial bundle size near zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e389e7e-dd2e-4719-ac8e-84cf16dd9fff', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Dependency Injection work in Spring?', N'Junior', N'Dependency Injection is a design pattern where the Spring IoC container manages the creation and lifecycle of objects. Instead of a class creating its own dependencies, the container ''injects'' them, usually through constructor or field injection, making the code more modular and easier to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ea4a875-bd6d-4369-bb92-84cffaaaa4c4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of the ''rocket::build()'' function?', N'Intern', N'The build function initializes the Rocket instance configuration. It is the starting point for setting up your routes, managed state, and fairings before the application is launched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3971c54-74e3-4b97-8552-84d308ae2017', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the architectural implications of choosing a shard key that has low cardinality?', N'Senior', N'Low cardinality shard keys lead to ''jumbo chunks'' that cannot be split effectively, causing uneven data distribution across the cluster. This results in hotspots where specific shards handle a disproportionate amount of traffic, negating the scalability benefits of horizontal sharding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba0bc5d2-ba79-4c79-88ce-84d8bcb70a45', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the performance implications of using a high isolation level like Serializable in a high-concurrency environment?', N'Senior', N'High isolation levels increase the frequency of transaction aborts and retries due to increased detection of concurrent conflicts. This leads to higher latency and reduced overall system throughput as the database engine must work harder to validate transactional integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dee04de9-35f8-4a6f-8a23-84dc10b3532e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the function of the appsettings.json file?', N'Intern', N'The appsettings.json file is a configuration file used to store application settings such as database connection strings, logging levels, and custom application parameters. It allows developers to change settings without recompiling the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9b194e1-4377-4dc1-8c9a-84de20a43e61', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js leverage MutationObserver to maintain component reactivity within the DOM?', N'Senior', N'Alpine.js uses MutationObserver to detect new DOM elements added dynamically after the initial page load. This allows it to automatically attach behavior to injected HTML without requiring manual re-initialization of the component tree. This mechanism is essential for seamless integration with server-side fragment updates or third-party libraries that modify the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'196b2427-19b3-4754-9681-84dec95507ed', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do SolidJS signals differ from React''s state hooks?', N'Middle', N'Signals are independent reactive primitives that track their own subscribers. In Solid, reading a signal registers a dependency, whereas in React, state updates trigger a re-execution of the entire component function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9643aefc-7d6b-4100-9d0e-84e1b8e5b832', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use context in Preact?', N'Fresher', N'Yes, Preact supports the Context API, which allows you to pass data through the component tree without manually passing props down at every level. This is useful for global state like themes or user authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dcdf009-4e85-4359-9084-84e38dce73f9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide when to stop optimizing a piece of code?', N'Junior', N'I stop optimizing when the performance meets the defined requirements and the code remains readable and maintainable. Premature optimization often adds unnecessary complexity, so I focus on ensuring the solution is efficient enough for the current scale while keeping technical debt low.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7fd5582-da9a-496e-ba33-84e502b1e170', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary risk of over-engineering a solution early in a project?', N'Junior', N'Over-engineering introduces unnecessary complexity that makes the system harder to maintain, understand, and change later. It is better to focus on solving the immediate problem with a simple solution and refactor or scale only when the need is actually proven.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e15c8e9-946f-4bce-8ac9-84e52169cb74', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is the order of execution in the Lit lifecycle critical for performance tuning?', N'Senior', N'The lifecycle progresses through ''shouldUpdate'', ''willUpdate'', ''render'', and ''updated'', allowing developers to hook into specific phases. Understanding this order is crucial for preventing unnecessary re-renders or avoiding layout thrashing by separating read and write operations on the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00390b91-a122-4e76-a69a-84e53e6b9de7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the trade-offs of using Express for WebSockets versus a dedicated library or service.', N'Senior', N'Express is designed for request-response cycles and does not natively handle persistent WebSocket connections efficiently. While it can be done, it ties up a Node.js process and complicates scaling; dedicated solutions or external services like Socket.io or managed WebSocket gateways are more robust.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'827df581-9468-468b-b7ae-84e7cce8c3cb', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the architectural benefits of using PIMPL (Pointer to Implementation) in large C++ projects?', N'Senior', N'The PIMPL idiom decouples a class''s interface from its implementation details, significantly reducing compilation dependencies and improving build times. By hiding private members behind a pointer, changes to the implementation do not force a recompilation of all files that include the header, effectively isolating the API from internal modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf6aaeab-aeb7-4543-8685-84e897b17f38', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is ''Eta Expansion'' in Scala and when does it occur?', N'Senior', N'Eta expansion is the process by which the compiler automatically converts a method into a function object (a value of type FunctionN). This allows methods to be passed as higher-order functions seamlessly. It occurs when a method is used where a function value is expected, bridging the gap between Scala''s object-oriented methods and its functional programming capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11ff6840-55a7-411c-90b6-84eff2c84382', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does hoisting behave differently for function declarations versus function expressions and arrow functions?', N'Fresher', N'- Function declaration (function foo() {}): The entire function — name and body — is hoisted. The function is callable anywhere in its scope, even before the line it appears on. - Function expression (const foo = function() {}): Only the variable declaration is hoisted (if var); the assignment — the function value itself — is not. Calling it before the line throws TypeError (not ReferenceError) because the variable exists but holds undefined. - Arrow function (const foo = () => {}): Same as function expression — it is always assigned to a variable, so the same rules apply. Example: Real-World Use Case: In large React component files, developers often define helper arrow functions (const formatDate = (d) => ...) after the component function that uses them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34d2542a-0ed4-476e-a228-84f1455900f4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is an entry point in Webpack?', N'Intern', N'The entry point indicates which module Webpack should use to begin building out its internal dependency graph. From this entry point, Webpack figures out which other modules and libraries that entry point depends on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2afd171e-c9c2-4f4e-8f24-84f1b00057f2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the advantages of minification', N'Intern', N'Normally it is recommended to use minification for heavy traffic and intensive requirements of resources. It reduces file sizes with below benefits, 1. Decreases loading times of a web page 2. Saves bandwidth usages', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4f2a4e6-ae1e-4071-baf5-84f3f7dd0408', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the ''q-data.json'' file in a Qwik application?', N'Senior', N'The q-data.json file serves as the serialized state container for the application. It allows the server to pass the calculated state to the client, enabling the client-side framework to pick up exactly where the server left off without re-fetching or re-computing initial data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dde060d-41ea-4452-9985-84f587539bda', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the primary architectural benefit of Ruby''s ''Mixins''?', N'Middle', N'Mixins allow for horizontal code reuse by enabling classes to inherit functionality from multiple modules. This avoids the complexities and limitations of multiple inheritance found in other languages while keeping the class hierarchy clean and focused.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c22651c4-0383-430b-a05a-84f609f53b1e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is Sass considered better for maintainability than standard CSS?', N'Junior', N'Sass provides logical structure through variables, nesting, and modular file imports. These features reduce repetitive code and make it easier to maintain a design system as the project grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'433c5438-f186-4ed0-80d1-84f6877611a6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle data fetching caching, and what are the trade-offs of using the ''no-store'' option?', N'Middle', N'Next.js caches data fetches by default to improve performance and reduce server load. Using the ''no-store'' option forces the application to fetch fresh data on every request, which ensures real-time accuracy but increases latency and server resource consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
