INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a310521-2d8f-49a5-b5e6-84f69b5fe0b2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a keyspace in Cassandra?', N'Intern', N'A keyspace is the outermost container for data in Cassandra, similar to a schema in a relational database. It defines how data is replicated across nodes, including the replication factor and strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d0dcf4b-e2cd-415f-beba-84f960ded7e2', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe how database-level locks (pessimistic vs optimistic) function in Rails.', N'Senior', N'Pessimistic locking uses SELECT FOR UPDATE to lock rows at the database level, preventing other processes from modifying them until the transaction completes. Optimistic locking uses a version column to ensure that records are not overwritten by concurrent updates, raising an error if a collision is detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd918db7a-3839-4141-a1a6-84facdf260b5', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of Symfony''s Validation component?', N'Intern', N'The Validation component provides a set of constraints to check if data meets specific requirements, such as email format or minimum length. It ensures that data remains consistent and secure before being processed by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'becfb5a9-2655-434a-a9d9-84fdb8d8a7ce', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why would you choose ''web::Json'' over manual parsing in an Actix handler?', N'Middle', N'Using web::Json enables automatic validation and error handling as part of the request pipeline. If the JSON is malformed, Actix automatically returns a 400 Bad Request error, reducing boilerplate code in your handler and ensuring that your business logic only processes well-formed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
