INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'145ae3f1-f10f-4c60-9e1d-8527b71619e9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the advantage of using Doctrine Migrations over manual schema updates?', N'Middle', N'Doctrine Migrations provide a version-controlled, repeatable way to update the database schema. They ensure that all environments—development, staging, and production—are synchronized, and they allow for rolling back changes if a deployment fails, which is impossible with manual database modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1488d2ee-f0cb-4c26-805f-852d8152f465', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the primary purpose of Spring Boot compared to the traditional Spring Framework?', N'Fresher', N'Spring Boot simplifies the configuration and deployment of Spring applications by providing ''opinionated'' defaults. It eliminates the need for complex manual XML or Java configuration and comes with an embedded server, allowing applications to run as standalone executable units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad674538-fab8-4ac3-af78-853141e7b78f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a deadlock in MySQL?', N'Junior', N'A deadlock occurs when two or more transactions hold locks that the other needs, resulting in a situation where neither can proceed. MySQL automatically detects this and kills one of the transactions to allow the others to finish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5cb8d48-4690-4fcc-a6cb-8532061f3f22', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle legacy browser support?', N'Middle', N'Vite provides the official @vitejs/plugin-legacy plugin, which generates polyfills and legacy chunks for browsers that do not support native ESM. This allows modern syntax to be used while maintaining compatibility with older environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d5b609f-cd66-4925-b4d9-85352d2bf9a5', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a zone context?', N'Intern', N'Execution Context is an abstract concept that holds information about the environment within the current code being executed. A zone provides an execution context that persists across asynchronous operations is called as zone context. For example, the zone context will be same in both outside and inside setTimeout callback function, The current zone is retrieved through Zone.current.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adf4ea9a-cba6-40b1-9570-85352d6dff6f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of eslint plugin for hooks?', N'Intern', N'The ESLint plugin enforces rules of Hooks to avoid bugs. It assumes that any function starting with ”use” and a capital letter right after it is a Hook. In particular, the rule enforces that, 1. Calls to Hooks are either inside a PascalCase function (assumed to be a component) or another useSomething function (assumed to be a custom Hook). 2. Hooks are called in the same order on every render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bf4059f-e285-4c52-9169-8538083eca0d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the difference between app.use() and app.all() in the context of request routing.', N'Middle', N'The app.use method matches any path that begins with the specified prefix, making it ideal for mounting middleware or routers that handle multiple sub-routes. Conversely, app.all matches a specific route path for all HTTP methods, such as GET, POST, or PUT. While app.use is path-prefix based, app.all is route-specific and strictly scoped to the exact path provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cee8b72-26d1-417f-a9d4-853899589687', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a ''defer'' block used for?', N'Junior', N'A defer block is used to execute a set of statements just before the current scope is exited, regardless of how the execution leaves the scope. It is commonly used for cleanup tasks like closing files or releasing resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d52b0c9-bd59-48b8-992a-8539d38b639f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between Provider and Services in Nestjs, can we have a provider without an injectable decorator, Give examples?', N'Fresher', N'A provider is a more general concept, while a service is a specific type of provider. Providers are a fundamental concept in NestJS system of dependency injection. They can be used to inject not only services, but also values, factories, and more. A service is a class annotated with @Injectable() decorator, typically used to handle complex business logic or to provide access to shared data. Here''s an example: However, a provider doesn''t necessarily need to be a service. It can be any value that should be available for injection. For example, you can provide a simple string: In this case, HelloMessage is a token that can be used to inject the string Hello, World!. While services are typically decorated with @Injectable(), other types of providers don''t need this decorator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bbad33f-2e70-4947-b52d-853ad0c036d9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide when it is appropriate to introduce a new technology stack into an existing project?', N'Middle', N'I evaluate the cost-benefit ratio by comparing the maintenance overhead of the new technology against the tangible performance or feature gains it provides. I ensure that the team has the necessary expertise and that the new stack aligns with the long-term architectural goals rather than just following a trend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21a63b68-d6b6-4293-ab13-853b04dc6f7c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain how Phoenix handles ''backpressure'' when a client is unable to consume data as fast as the server produces it.', N'Senior', N'Phoenix relies on the underlying Erlang VM''s message-passing architecture and mailbox limits for backpressure. By monitoring process mailbox sizes, developers can implement strategies like dropping older messages or slowing down producers to ensure that a slow client does not lead to memory exhaustion on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91ec5bb5-a249-4d3b-89b9-853b31903f02', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis eviction policy?', N'Junior', N'An eviction policy determines how Redis removes old data when the memory limit is reached. Common policies include LRU (Least Recently Used), which discards the keys that haven''t been accessed for the longest time to make room for new data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c63221e1-e231-41a1-a5cb-853ce241c650', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between a matrix and a data frame?', N'Intern', N'A matrix is a two-dimensional structure where all elements must be of the same data type, such as all numeric. A data frame allows different columns to hold different data types, making it more flexible for real-world datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ba8fd72-7b69-4b85-bd23-853e70f03f9d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What does ''res.redirect()'' do?', N'Fresher', N'The res.redirect() method sends an HTTP redirect response to the client. It instructs the client''s browser to navigate to a different URL provided as an argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9f06cba-656d-4dd3-b6c4-854174ec1726', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is a read replica and how does it help with performance?', N'Middle', N'A read replica is a copy of the primary database that only accepts read-only queries. By directing read traffic to these replicas, the primary database is freed up to focus on write-heavy tasks, significantly improving overall system throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f52b71d-b124-4635-8f7c-854497617a11', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of exec method', N'Intern', N'The purpose of exec method is similar to test method but it executes a search for a match in a specified string and returns a result array, or null instead of returning true/false.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8790981-58ff-422a-bde8-854539653b2b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the architectural implication of using ''SyncArbiter'' in Actix.', N'Senior', N'SyncArbiter is used to offload CPU-intensive tasks to a dedicated pool of synchronous actors. While it prevents blocking the main event loop, it introduces the complexity of managing thread safety and potential bottlenecks within the synchronous worker pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f935f344-a6bc-4c1e-9dfc-85453a2ed8d1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it important to never store pointers to request context objects in Fiber?', N'Middle', N'Fiber and the underlying Fasthttp library reuse request and response objects to save memory. If you store a pointer to these objects after the handler returns, the data they point to will be overwritten by a subsequent request, leading to data corruption and memory safety issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6b2409d-dc8d-45bf-8d46-8547ee9b5c31', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why does JavaScript''s single-threaded nature require specific handling for CPU-intensive tasks?', N'Senior', N'Since there is only one call stack, CPU-intensive tasks block the event loop, preventing UI updates and I/O processing. Developers must use Web Workers or Worker Threads to move heavy computations to separate threads, maintaining the responsiveness of the main application thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16ba428e-68f6-4390-a20f-85486f024fde', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the ''shared_buffers'' setting?', N'Middle', N'Shared_buffers determines how much memory PostgreSQL uses for caching data blocks. A properly sized buffer pool allows the database to serve frequently accessed data from RAM instead of reading from disk, which is essential for maintaining high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c783af15-53e2-4527-aff5-8548e52c35f6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a pessimistic locking strategy?', N'Junior', N'Pessimistic locking prevents conflicts by placing a lock on data as soon as a transaction starts accessing it. This ensures that no other transaction can modify or lock the data until the current transaction is finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec66029a-0a1b-48df-b817-854a204c1c2d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask context globals?', N'Fresher', N'Context globals like ''request'' and ''session'' are objects that are available throughout the lifecycle of a single request. They allow you to access data specific to the current user interaction without passing variables explicitly to every function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65d917f8-ecfe-49bd-85ab-854a4f203818', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a table and a database?', N'Intern', N'A database is a collection of structured information or data, while a table is a specific object within a database that organizes data into rows and columns. A single database can contain multiple tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42627136-0cf5-4d66-a7c1-854e6c730a86', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of a two-phase commit (2PC) protocol in distributed databases?', N'Middle', N'The two-phase commit protocol ensures atomicity across multiple nodes in a distributed system. It consists of a prepare phase where all nodes agree to commit, and a commit phase where the coordinator instructs all nodes to finalize the transaction, ensuring that either every node commits or none do.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'953bdd12-1875-46d0-88f2-854f28d32261', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the impact of hidden classes (shapes) in V8 on object property access performance?', N'Senior', N'V8 uses hidden classes to track the structure of objects at runtime, allowing the engine to optimize property lookups into fixed offsets instead of dictionary-based searches. If an object''s structure changes frequently or property order is inconsistent, the engine deoptimizes the object to a slow-mode dictionary, significantly degrading performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6254627e-95e8-49f2-8223-8552381e4255', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is nullish coalescing operator (??)?', N'Intern', N'It is a logical operator that returns its right-hand side operand when its left-hand side operand is null or undefined, and otherwise returns its left-hand side operand. This can be contrasted with the logical OR (||) operator, which returns the right-hand side operand if the left operand is any falsy value, not only null or undefined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77c715b8-aad9-4af0-a410-8552d6ef0a36', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why do we use ''next'' in error handling?', N'Fresher', N'In error handling, next is used to pass the error to the next error-handling middleware in the sequence. If you have multiple error handlers, calling next(err) ensures the next one in line gets the chance to process the error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ea0ce7-a768-4de2-b9de-85545c7d0caf', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the trade-offs of using ''unsafe'' code blocks in a C# application?', N'Senior', N'Unsafe blocks enable raw pointer manipulation and direct memory access, bypassing GC safety and bounds checking. While this allows for extreme performance optimizations, it introduces significant risks of memory corruption and security vulnerabilities if not handled with rigorous validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
