INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcac212e-9dcd-4d38-8951-856286a8151f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the performance impacts of using ''Global Indexes'' in a sharded cluster?', N'Senior', N'Global indexes maintain index entries for all documents in a collection across all shards, which can lead to significant overhead on individual shards. This design simplifies query routing but increases the write penalty as every index update must manage global state rather than local scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
