INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd34b41f5-3fbc-4a05-bd1d-85653eb5710f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the concept of ''Route-driven development'' and why it is the backbone of Ember apps.', N'Senior', N'Ember is built around the idea that the URL is the source of truth, and the router maps this URL to a hierarchy of routes, controllers, and templates. This architecture ensures that application state is always shareable and bookmarkable, and it provides a standard lifecycle for loading data and handling transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c73550c0-39a6-479b-b475-8566384a0c6e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch perform ''query-then-fetch'' during a distributed search?', N'Middle', N'In the query phase, the coordinating node sends the request to all relevant shards, which return document IDs and scores. In the fetch phase, the coordinating node requests the full document content only for the top results from the specific shards that hold them, minimizing network traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
