INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c405804-9c8d-4840-879e-857f3337b42c', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the trade-offs of using provide/inject for state management?', N'Middle', N'Provide/inject allows for easy dependency injection across deep component trees, avoiding prop drilling. However, it makes tracking data flow harder because the connection between the provider and injector is not explicit in the component''s interface, which can lead to maintainability issues in large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9852f83b-5a05-407f-827a-857f393f926b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do Actors prevent data races in Swift?', N'Middle', N'Actors protect their internal state by ensuring that only one task can access their mutable properties at any given time. By forcing external access to be asynchronous, they prevent concurrent read-write collisions that lead to memory corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1a061fa-3e8c-44f4-b02a-857f54dc3eaa', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle extractors?', N'Intern', N'Extractors are a feature that allows handlers to automatically parse data from an HTTP request, such as JSON bodies, query parameters, or headers. They simplify code by decoupling the parsing logic from the main business logic of the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75c087e1-41f8-4eb3-ac46-85806828e838', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the ''Metadata Lock'' in MySQL?', N'Senior', N'Metadata locks protect the integrity of the database schema by ensuring that DDL operations, like dropping or altering a table, do not occur while a DML operation is accessing the table. They prevent inconsistent states where a structure changes while data is actively being modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51b3e1b0-9943-492c-b055-8589bd0e90ee', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle middleware compared to standard WSGI frameworks?', N'Middle', N'Litestar uses an ASGI-compliant middleware stack, which allows for asynchronous processing of requests and responses. This enables non-blocking operations throughout the middleware chain, which is essential for scaling high-concurrency applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28e8e3f4-58f2-4433-863f-858b0ff45b98', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the limitations of Django''s default signal mechanism in large-scale applications?', N'Senior', N'Signals are executed synchronously within the same process, meaning a signal handler failure can block the primary operation or cause race conditions. For complex, decoupled workflows, message queues are a safer, more robust alternative to internal signals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0fc3053-5f8f-4a08-a875-858ccb307597', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between JVM mode and Native mode in Quarkus?', N'Intern', N'JVM mode runs the application on a standard Java Virtual Machine, offering high throughput and compatibility. Native mode uses GraalVM to compile the application into a standalone binary, offering superior startup speed and memory efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bfaa28c-a4ae-4eac-8e22-85902dae08eb', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is a major security disadvantage of using a monolithic architecture compared to microservices?', N'Middle', N'In a monolith, a vulnerability in one module might allow an attacker to gain full access to the entire application''s memory space and database. Microservices allow for better isolation and the ability to apply granular security policies to individual components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0420e723-6bf5-44a6-aa4e-859124159ed0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a dynamic mapping?', N'Intern', N'Dynamic mapping is a feature where Elasticsearch automatically detects and adds new fields to a document mapping when they are first encountered. This allows for schema-less data ingestion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eba18b4-80d8-4cf6-9d14-8594333c1c5b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between a ''timeout'' error and a ''permission'' error, and how do you troubleshoot each?', N'Junior', N'A timeout indicates the server is taking too long to respond, which I would troubleshoot by checking for high load or unoptimized queries. A permission error indicates the user lacks the necessary authorization, which I would troubleshoot by inspecting the user''s roles and the system''s access control configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd701ec8d-6235-4746-b926-859440bf1510', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix''s ''useFetcher'' hook enable complex UI patterns without navigation?', N'Senior', N'The useFetcher hook allows interaction with loaders and actions without triggering a route change or page transition. This is essential for building features like background data synchronization, modals, or partial UI updates that must persist independently of the main navigation stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80e037d2-3135-49ec-9b82-85957215434f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''readonly'' properties and ''const'' declarations?', N'Middle', N'''Const'' prevents the reassignment of a variable binding, while ''readonly'' prevents the reassignment of a specific property within an object or class. Using ''readonly'' allows you to create immutable-like data structures even when the object reference itself is stored in a mutable variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
