INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b92dcf0c-d234-4d4a-ad6d-859928259c28', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''size_t'' and ''int''?', N'Junior', N'The ''size_t'' type is an unsigned integer type used to represent the size of objects in bytes and is guaranteed to be large enough to hold the maximum size of any object on the system. An ''int'' is a signed integer type used for general arithmetic, and its size can vary depending on the architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f046403f-5292-4103-bb37-8599bb3c3370', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of foreign key constraints in a relational database?', N'Middle', N'Foreign keys enforce referential integrity, ensuring that a relationship between two tables remains consistent. They prevent operations that would destroy links between rows, such as deleting a parent record that still has associated child records in another table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b677a818-1d1a-42d4-abc4-859a335890ed', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you choose between synchronous and asynchronous processing for a task like sending an email after user registration?', N'Junior', N'Synchronous processing makes the user wait for the email to be sent before completing the registration, which can lead to latency. Asynchronous processing offloads the email task to a background worker, allowing the user to continue immediately while the email is sent reliably in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca925214-3fc3-464c-a3e2-859d4e668c1b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of ''Isolation Level'' configuration in database tuning?', N'Senior', N'The isolation level is tuned to balance the trade-off between data correctness and system performance. Developers must choose the lowest level that provides sufficient safety for their specific business logic to maximize concurrency and throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
