INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'687db207-59fe-4cba-9226-85ab14147a48', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the concept of ''Eventual Consistency'' and its implications for database design.', N'Middle', N'Eventual consistency allows for temporary discrepancies between replicas to prioritize high availability and low latency during network partitions. In system design, this requires developers to handle potential stale reads or conflicts at the application level, rather than relying on the database to provide a single global state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
