INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'399a94a5-5100-4246-b963-85ad6dd697ba', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the risk of using ''non-null assertion operators'' in TypeScript?', N'Middle', N'The non-null assertion operator tells the compiler to ignore the possibility that a value is null or undefined. If the developer is incorrect, it will lead to runtime errors, essentially bypassing the safety features that TypeScript is designed to provide.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02f1e3dc-d5e8-480d-8bc8-85ad8ad81177', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does the term ''atomic'' mean regarding Redis commands?', N'Junior', N'Atomic means that a command will either succeed completely or fail completely, with no other client seeing a partial state. Because Redis is single-threaded, every individual command is guaranteed to be atomic, preventing data corruption from concurrent access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
