INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aebf5bfa-9e4f-4fd3-8347-85be2eb54257', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between a cache and a primary database?', N'Fresher', N'A cache is a temporary storage layer designed to speed up data retrieval by storing copies of data that are frequently accessed. A primary database acts as the system of record where the original, permanent data is stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a67586d3-038b-4ef7-b113-85c03c30a0ab', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does service discovery improve reliability in a dynamic environment?', N'Middle', N'Service discovery allows services to find and communicate with each other dynamically by querying a registry instead of using hardcoded IP addresses. This is essential in cloud environments where instances are frequently created and destroyed, ensuring traffic is always directed to healthy, active nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9bb90e8-6074-48ff-877d-85c051ad65a6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between an Actix service and an Actix actor?', N'Intern', N'A service in Actix is a generic component that handles incoming requests, whereas an actor is a specific component that manages state and processes messages. While all actors can be treated as services, not every service requires the full overhead of an actor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41440cb9-fe6a-4986-b9d5-85c0c3c406ef', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Explain the trade-offs between synchronous and asynchronous communication between microservices.', N'Middle', N'Synchronous communication, like REST or gRPC, is simpler to implement and provides immediate feedback but creates tight coupling and risks cascading failures. Asynchronous communication via message brokers decouples services and increases system resilience, though it introduces complexity in handling eventual consistency and error tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
