INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a08b36de-2ff6-495d-aa0f-85dea47807b5', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When working on a shared project, how do you ensure your progress is transparent to the team?', N'Junior', N'I provide regular updates during daily stand-ups, keep my ticket status up to date in the task tracker, and communicate any blockers immediately. This ensures that the rest of the team knows exactly what I am working on and when they can expect it to be finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7528fa4a-5bbf-4655-95f7-85e0eed5d834', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Discuss the impact of Axum''s ''IntoResponse'' trait on API design and error handling.', N'Senior', N'The IntoResponse trait enables a polymorphic way to convert any custom error or data type into an HTTP response. This allows developers to centralize error mapping, ensuring that domain-specific errors are consistently translated into appropriate HTTP status codes and payloads across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cdbd721-8fea-494d-8c08-85e650d118bd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What methodology do you use to estimate the memory requirements for a service handling massive concurrent WebSocket connections?', N'Senior', N'I calculate the per-connection overhead, including buffer sizes, state storage, and protocol frames, and multiply this by the expected maximum concurrent connection count. I then add a safety margin to account for garbage collection pressure and heap fragmentation, ensuring the service remains stable at peak occupancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c4bedd5-eb62-4806-b2ed-85e96363d035', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is it considered a best practice to use Chi''s RouteContext for passing metadata through the request pipeline?', N'Middle', N'Chi''s RouteContext provides a structured way to store and retrieve URL parameters and other request-scoped data without polluting the global request context. It ensures type safety and consistency across the middleware chain, reducing the risk of collisions that might occur if using arbitrary keys in the standard context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'becadfa5-00a1-4463-8b66-85e9cacf605d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Reserved Attribute Name?', N'Fresher', N'A reserved attribute name is a word that DynamoDB uses for internal purposes, such as ''Name'' or ''Date''. While you can use these for your attributes, you must use expression attribute names to avoid conflicts in your queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5374240c-63e9-4c6c-879c-85ed3eac8034', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What does it mean for a SvelteKit app to be ''isomorphic''?', N'Intern', N'An isomorphic application is one where the same JavaScript code can run on both the server and the client. This allows for shared logic, consistent data handling, and improved performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af461fd-3cca-41aa-a1e0-85ed4a0af943', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What role does the ''ParamConverter'' play in a Symfony Controller, and why is it useful?', N'Senior', N'ParamConverters automate the transformation of request parameters into rich objects, such as fetching a database entity by ID. This eliminates repetitive boilerplate code inside controllers, centralizes data validation, and enforces a cleaner separation of concerns between the transport and domain layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c26e3b9-5ad6-49d3-ab7b-85ee13d3e8fa', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the trade-offs of using Merkle trees for anti-entropy in distributed databases.', N'Senior', N'Merkle trees enable efficient detection of data discrepancies between replicas by comparing hash summaries of data ranges rather than the raw data itself. While this significantly reduces network bandwidth during synchronization, it requires periodic computational overhead to rebuild the tree as data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a159335d-c2f7-4dbb-b820-85f1d7f4f41e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is the ''Stop-the-World'' phase in GCs considered a design challenge for distributed systems?', N'Senior', N'Stop-the-world pauses halt all application threads, which can cause heartbeats to timeout in distributed systems, leading to accidental node removal by cluster orchestrators. Developers must tune the GC or utilize concurrent collectors to ensure pause times remain well below the failure-detection threshold of the network heartbeat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70c7c16d-8ccb-4d36-bdb5-85f5a710ef4a', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What does it mean for an object to be hashable?', N'Middle', N'An object is hashable if it has a hash value that remains constant throughout its lifetime and can be compared to other objects. Only immutable types, like tuples or frozen sets, are generally hashable and can be used as keys in dictionaries or elements in sets. Mutable objects like lists are not hashable because their value can change, which would invalidate their hash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'041e462a-ad86-4060-916b-85fa16c9e8d4', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is the concept of immutability critical in Redux?', N'Middle', N'Immutability is essential because Redux uses shallow comparison to detect state changes. If objects were mutated directly, the store would not trigger re-renders because the reference would remain the same, leading to inconsistent UI states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bb7a3e0-07f4-4198-9881-85fa23cff631', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is meant by the ''Single Source of Truth'' principle in Redux?', N'Intern', N'This principle states that the entire state of your application is stored in an object tree within a single store. This makes it easier to debug, maintain, and persist the state, as there is only one location where application data is managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8071fb5-f16b-46f7-81e3-85fa6eb33511', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between ''this.args'' and component properties?', N'Junior', N'In modern Ember, ''this.args'' is used to access data passed into a component from its parent template. Internal state, which is not passed from the parent, is defined directly as a property on the class and managed with @tracked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64e3a721-bc20-43c5-81c6-85faacd1afed', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between a prop and a store in Svelte?', N'Middle', N'Props are for passing data down the component tree from parent to child, representing the component''s interface. Stores are for managing independent data that can be accessed from anywhere, regardless of the component structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd99c22ce-6c6f-4561-8a96-85fba3779469', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are ''Loading'' sub-states in Ember?', N'Middle', N'Loading sub-states are automatically rendered by Ember when a route''s model hook takes a long time to resolve. They provide a native way to show loading spinners or skeleton screens, improving the perceived performance of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0fb5512-1051-413c-bf0c-85fdf678f099', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the ''adapter'' in SvelteKit, and why is it necessary?', N'Middle', N'Adapters transform the built SvelteKit application into a format compatible with specific deployment platforms like Vercel, Netlify, or Node.js servers. They abstract platform-specific concerns such as serverless function signatures or static asset handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b7ba796-0c14-4288-99de-85ffb79c9629', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the ''Thundering Herd'' problem in the context of cache invalidation.', N'Senior', N'The thundering herd problem occurs when a widely shared resource is invalidated, causing a large number of threads or processes to wake up and simultaneously attempt to fetch or rebuild the resource. This leads to a spike in CPU and I/O usage that can destabilize the backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaf3e1a3-c34c-40b2-8728-86012910a762', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is Gin often chosen over the standard library ''net/http'' for RESTful services?', N'Senior', N'Gin provides built-in utilities for common tasks like parameter binding, JSON validation, and grouping routes, which would otherwise require significant boilerplate in ''net/http''. Its optimized Radix tree router also provides better scalability for applications with complex URL path structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deb3ccc2-e1c0-4b33-8236-8603d07d8448', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is Alpine.js?', N'Intern', N'Alpine.js is a lightweight, minimal JavaScript framework used to add behavior directly to your HTML markup. It is often described as a tool for offering the reactive nature of large frameworks like Vue or React without the complexity of build steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f816e68b-a0e6-478b-b541-860aa95ac1a8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where you discover that a dependency you relied on is broken?', N'Fresher', N'I inform the relevant team or owner immediately to see if a fix is in progress. In the meantime, I look for a temporary workaround or an alternative dependency to keep the project moving forward without being completely blocked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22ae1b0f-864c-47ab-beeb-860bffbffe40', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do conditional types impact the resolution of complex generic transformations, and what are the risks of recursive conditional types?', N'Senior', N'Conditional types allow for type-level branching based on the input type, enabling highly reusable utility types. Recursive conditional types can easily exceed the compiler''s depth limit, causing performance degradation or build failures, and they often become difficult to debug due to the lack of clear error messages in deep nesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a74fc1fa-6b2e-4f02-990a-860dd310fc3f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the significance of ''tail call optimization'' (or the lack thereof) in Python?', N'Senior', N'Python does not implement tail call optimization, meaning recursive functions can hit the recursion depth limit and cause stack overflows. This design choice is intentional to preserve stack traces for debugging purposes, which is considered a priority in the language''s philosophy. For deep recursion, iterative solutions are preferred to ensure memory stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94e1dc3f-f7ca-4e26-bcdc-86131ce30f20', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s ViewEncapsulation affect CSS scoping?', N'Middle', N'Emulated encapsulation adds unique attributes to component elements to simulate shadow DOM scoping, ensuring styles do not leak out. Native encapsulation uses the browser''s native Shadow DOM implementation, while None allows styles to be applied globally, which is useful for shared design systems but requires careful management to avoid collisions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b2571ee-1f35-4cd4-b34f-861364f48467', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the consequence of exceeding the mailbox capacity in an Actix actor?', N'Senior', N'When an actor''s mailbox exceeds its defined capacity, new messages may be dropped or the sender may be forced to wait, depending on the implementation. This serves as a fundamental backpressure mechanism to prevent unbounded memory growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f149bd1c-e5da-4c4e-8157-86170f949b59', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''Reply'' send method?', N'Intern', N'The send method is used to finalize the response and send it to the client. You can pass objects, strings, or streams to this method, and Fastify will handle the serialization and header management automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0b2c6e0-4bf8-478c-a03c-8617495d1b0b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is ''API Versioning'' and why is it necessary in microservices?', N'Middle', N'API versioning allows services to evolve their interfaces without breaking existing clients. By supporting multiple versions simultaneously, teams can migrate consumers gradually rather than forcing a lock-step upgrade across the entire ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca2e0f4a-d4a4-471e-b5e5-861a601125e3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''unknown'' type?', N'Intern', N'The unknown type is a safer alternative to ''any''. It represents a value that could be anything, but you must perform type checking or narrowing before you are allowed to perform operations on it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'958dda93-67a6-4fa0-81c5-861c890c05fc', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is an interface in C# and why is it used?', N'Fresher', N'An interface is a contract that defines a set of methods and properties without providing their implementation. It is used to achieve multiple inheritance of behavior, allowing different classes to implement the same interface while providing their own specific logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'311618f6-3b33-4e71-a4b9-861dbd189b94', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a deadlock and how do databases typically resolve it?', N'Middle', N'A deadlock occurs when two or more transactions are waiting for each other to release locks, resulting in a circular dependency. Databases resolve this by using a deadlock detector that identifies the cycle and forcibly aborts one of the involved transactions to break the loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08306047-6023-4b46-a75a-861e56524c9d', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the advantages of stored procedures?', N'Intern', N'- Compiled execution plan cached for reuse → better performance. - Code reuse and centralized business logic. - Security: grant EXECUTE without direct table access → prevents SQL injection. - Reduces network traffic (one EXEC call vs. many statements). - Supports output parameters, return codes, and result sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f12c0805-1ee6-465e-8e2b-861f5d2d2c24', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of the Quarkus ''Arc'' container?', N'Middle', N'Arc is a lightweight dependency injection container tailored for Quarkus. It is designed to be fully compatible with CDI specifications while performing the vast majority of dependency resolution during build time rather than at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44d7a9ca-e6dc-4aad-a117-86206a20d9e1', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the different types of Redis databases?', N'Intern', N'Redis provides a range of data types, each optimized for specific tasks. Core Data Types 1. Strings: Useful for key-value pairs or simple message storage. 2. Hashes: Ideal for representing objects, aggregate data, or handling user input. 3. Lists: Suitable for storing logs, messaging queues, or tasks. Both ends are optimized for fast operations. 4. Sets: Designed to manage unique item collections. 5. Sorted Sets: Like sets, but items are sorted based on scores; great for leaderboards or ranged lookups. 6. Bitmaps: Efficient for state tracking, for instance, user activities on specific dates. 7. Hyperloglogs: Provides fast, approximate set cardinality; helpful for data analytics. 8. Geospatial Indexes: Efficient for location-based queries. 9.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa0e1524-2912-4867-b3c2-8622146bcfc5', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @Value annotation?', N'Intern', N'@Value is used to inject values from properties files, environment variables, or system properties into class fields. It provides a simple way to access externalized configuration settings within your application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'690a4d7a-98e5-4560-a90e-8622602e0cdf', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s ''Bind'' mechanism affect application performance during high-throughput JSON processing?', N'Senior', N'The Bind mechanism uses reflection to map request payloads to structs, which introduces overhead compared to manual unmarshaling. In performance-critical scenarios, minimizing reflection by using specialized decoders or pre-compiled schemas can significantly reduce CPU usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3904bae7-f8a7-4128-a82a-8622e6954257', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between a document and a document type in Elasticsearch?', N'Junior', N'A document is the basic unit of information in JSON format that can be indexed. While older versions of Elasticsearch supported multiple types per index, modern versions have moved to a single type per index to ensure better performance and data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c580b5f-fd5f-491b-8af0-862497a1d20e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is PostgreSQL and what is its primary role?', N'Fresher', N'PostgreSQL is an open-source object-relational database management system. Its primary role is to store, retrieve, and manage data securely while supporting complex queries and data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0153c12c-95be-4b73-b1cb-8625c0fada94', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is the lack of a Virtual DOM considered a benefit for SolidJS?', N'Middle', N'By eliminating the Virtual DOM, SolidJS removes the need for constant object diffing and reconciliation. This reduces CPU usage and allows the framework to map state changes directly to specific DOM nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708cfdaf-b0a3-4239-afdc-862633b90f20', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between automated testing and manual testing in a software release cycle?', N'Junior', N'Automated testing is fast, repeatable, and scales well for regression testing, but requires significant time to write and maintain. Manual testing is better for exploratory testing and edge cases that are hard to script, but it is slow, error-prone, and expensive to scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'979fe542-52d0-43b3-857b-862726cf1af7', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you access path parameters in Hono?', N'Junior', N'Path parameters defined in the route pattern are accessible via the context object. The framework parses these parameters and makes them available through a dedicated method, allowing the handler to extract values like IDs or names directly from the URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89b50dfc-cd71-493f-b5b4-86287efac8b0', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''guard'' statement in Swift?', N'Intern', N'The guard statement is used to transfer program control out of a scope if one or more conditions are not met. It is primarily used to improve code readability by handling early exits and ensuring that certain requirements are satisfied before proceeding with the rest of the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1a06a3e-ac36-4315-9c25-8629256a6c77', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle security and authentication?', N'Junior', N'FastAPI has built-in security utilities that support various authentication schemes like HTTP Basic, OAuth2, and API keys. These are implemented as dependencies, allowing you to easily protect specific routes by requiring a valid user token or credential.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6bd2ff8-0157-4af7-a173-862fc34cb0e9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of a makefile?', N'Junior', N'A makefile is a configuration file used to automate the build process of a program. It defines the dependencies between source files and instructions for how to compile and link them into an executable. This ensures that only files that have changed are recompiled, saving time during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5aa8a53-dd46-4315-9657-86326f319b8c', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the conditional directives?', N'Intern', N'VueJS provides set of directives to show or hide elements based on conditions. The available directives are: v-if, v-else, v-else-if and v-show 1. v-if: The v-if directive adds or removes DOM elements based on the given expression. For example, the below button will not show if isLoggedIn is set to false. You can also control multiple elements with a single v-if statement by wrapping all the elements in a element with the condition. For example, you can have both label and button together conditionally applied, 2. v-else: This directive is used to display content only when the expression adjacent v-if resolves to false. This is similar to else block in any programming language to display alternative content and it is preceded by v-if or v-else-if block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6ad23df-d0cd-4a91-ad89-8633ef2993ce', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of using Hibernate Reactive with Quarkus?', N'Middle', N'Hibernate Reactive allows for non-blocking database interaction, which is essential for scaling applications that use an event-loop architecture. It prevents the application from blocking threads while waiting for database I/O, increasing overall system concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02b96df9-d8fc-4891-8756-863633575262', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS achieve ''fine-grained'' updates in lists?', N'Senior', N'SolidJS uses a specialized ''For'' component that maps over a signal-based array, tracking individual items and their positions. This allows the framework to move, add, or remove DOM elements without re-rendering the entire list when the underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fad597fa-63a8-4be4-a8b8-86367c791d6a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s architecture handle browser compatibility for newer CSS features?', N'Senior', N'Tailwind relies on PostCSS for its build pipeline, which allows for the integration of autoprefixer. This ensures that as Tailwind generates utility classes, the necessary vendor prefixes or fallbacks for modern CSS properties are automatically applied, maintaining cross-browser compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e64c21c7-5e07-4b84-8b17-8638eb6ca8c3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''static'' storage class specifier when applied to functions?', N'Senior', N'Applying ''static'' to a function limits its visibility to the current translation unit, effectively providing encapsulation at the file level. This prevents symbol collisions during the linking phase when multiple object files are combined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4116b936-0cd2-4932-923a-863aac05bc8a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What approach would you take if you were asked to fix a bug but could not reproduce it?', N'Fresher', N'I would gather more information by asking for the specific steps taken, the user''s browser version, and any error logs generated during the event. If still unable to reproduce, I would look at telemetry or monitoring tools to identify patterns in the logs that might reveal the trigger.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17de589b-b759-471f-9767-863ab724ac57', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off involved in caching frequently accessed data?', N'Fresher', N'Caching drastically improves performance by reducing redundant calculations or database queries. The trade-off is the complexity of managing cache invalidation to ensure users do not see stale or incorrect data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7218078-f8a8-4584-8c64-863b417e3ce8', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you define and implement a successful Service Level Objective (SLO) strategy in a distributed system?', N'Senior', N'An SLO strategy should be based on user-centric journeys rather than just infrastructure metrics. You define error budgets based on these objectives, which dictate the acceptable risk and velocity of deployments, allowing teams to balance feature development with reliability engineering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90f3f02d-07c7-487d-99d0-863cd7c3ee26', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the significance of the ''AnyVal'' class in Scala for performance optimization?', N'Senior', N'AnyVal allows the creation of value classes that avoid heap allocation by wrapping a single primitive type. During compilation, the compiler attempts to inline these wrappers, treating the value as the underlying primitive wherever possible. This reduces garbage collection pressure and memory usage, though it is limited by scenarios where boxing is forced by generic type interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9ee38ea-d795-4021-b3bb-863f2ffab3f4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is JSON', N'Intern', N'JSON (JavaScript Object Notation) is a lightweight format that is used for data interchanging. It is based on a subset of JavaScript language in the way objects are built in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84aaf544-f61f-46ac-9c5a-864136038a90', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Image optimization in Next.js?', N'Intern', N'Next.js includes an Image component that automatically optimizes images for different screen sizes and formats. This helps improve website performance by ensuring users only download the specific size of image they need.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68b2c6ef-fe62-4a5b-a6d8-864141127afc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you handle sensitive data like API keys in a Rails application?', N'Middle', N'Sensitive data should never be committed to version control; instead, it should be managed using Rails Credentials or environment variables. These tools inject secrets at runtime, ensuring that sensitive information remains secure across different development, staging, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c7cb5c1-5b79-4b63-8205-864334928a39', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you pass parameters in Angular routes?', N'Fresher', N'You can pass parameters in Angular routes primarily in two ways: 1. Route Parameters: These are part of the URL path itself, typically used to identify a specific resource. You define them in the route configuration using a colon (:), like path: ''items/:id''. To navigate, you pass them as segments in the router.navigate array, for example, this.router.navigate([''/items'', itemId]). In the target component, you read them using the ActivatedRoute service, accessing this.route.snapshot.paramMap.get(''id'') for the initial load or subscribing to this.route.paramMap for changes. 2. Query Parameters: These are appended to the URL after a question mark (?), used for optional values like filtering, sorting, or pagination. They are not defined in the route path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75de40b6-c62d-4d38-a9c0-8644230eaba1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to provide an estimate for a task you''ve never done before, how do you proceed?', N'Middle', N'I would decompose the task into smaller, familiar sub-tasks and compare the complexity to similar past work. Consulting with senior team members or performing a brief feasibility check helps validate my assumptions and improves the accuracy of the estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ffb3058-5894-4fab-888f-86442f20fd02', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the global environment in R?', N'Junior', N'The global environment is the interactive workspace where user-defined variables and functions are stored during an R session. It serves as the top-level environment for the user''s current project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5edd165-e380-4773-89c5-864477afb592', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the difference between ''val'' and ''var'' in Kotlin.', N'Fresher', N'The ''val'' keyword is used to declare read-only variables, meaning the reference cannot be changed once assigned, which is similar to a constant. Conversely, ''var'' is used for mutable variables, allowing the value to be reassigned multiple times throughout the program''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ada854cc-e9c0-46cf-80de-8645ac8b46ce', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Can Rocket be used to build APIs?', N'Intern', N'Yes, Rocket is frequently used to build RESTful APIs. It makes this easy by automatically serializing and deserializing data formats like JSON and providing tools for managing request headers and status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e5cb26c-21b4-4e31-a31d-8646024db693', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the difference between symmetric and asymmetric encryption?', N'Middle', N'Symmetric encryption uses a single key for both encryption and decryption, making it fast but requiring a secure way to share the key. Asymmetric encryption uses a pair of keys, a public key for encryption and a private key for decryption, which is more secure for key distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129aa476-4773-4961-b980-8648eba41076', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''skipLibCheck'' compiler option affect the reliability of the build process?', N'Senior', N'The ''skipLibCheck'' option prevents the compiler from type-checking all imported declaration files, which significantly speeds up compilation. However, it can mask type incompatibilities within third-party libraries, potentially leading to runtime issues that are only discovered during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b09ac5c5-45bc-42fa-b0eb-864b187a05a4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a NULL value in MySQL?', N'Intern', N'A NULL value represents the absence of data in a database field. It is distinct from an empty string or a zero value, as it indicates that the information is unknown, missing, or not applicable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b881045-bae7-4093-b73a-864e694c8616', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does cache partitioning (sharding) impact system scalability and what is the primary risk of using simple modulo-based sharding?', N'Senior', N'Partitioning distributes cache load across multiple nodes, allowing horizontal scaling of memory and throughput. Simple modulo-based sharding is highly sensitive to cluster membership changes, causing massive cache misses and ''rehash storms'' whenever a node is added or removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
