INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcd29280-9164-48c1-9b53-865343b46472', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is ''strictNullChecks'' considered a best practice in TypeScript?', N'Middle', N'Strict null checks prevent null or undefined values from being assigned to variables unless explicitly declared. This forces developers to handle potential absences of values, which eliminates a large class of ''cannot read property of null'' runtime exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
