INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf0f494b-c98d-4f79-a5dc-8653a9880003', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is automatic code splitting in Next.js?', N'Junior', N'Next.js automatically splits your code into smaller chunks based on the routes and components you use. This means the browser only downloads the JavaScript necessary for the specific page being visited, which improves initial load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8425018-c1d2-4ee8-ab6c-8654564f9330', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Discuss the trade-offs of using direct memory buffers for I/O operations.', N'Senior', N'Direct memory buffers allow the JVM to perform I/O operations directly from operating system memory, avoiding the overhead of copying data between the Java heap and native memory. However, allocating and deallocating direct memory is more expensive than heap allocation, and it requires careful management to avoid native memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec97357-e06f-41be-8d49-86561af761d6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''unknown'' type in TypeScript?', N'Fresher', N'The ''unknown'' type is a type-safe alternative to ''any''. It represents any value, but unlike ''any'', you cannot perform operations on an ''unknown'' value without first narrowing it down through type checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
