INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e33bba1b-794a-46c6-9a59-8657709590b6', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser handle style recalculations when dynamic classes are added via JavaScript?', N'Senior', N'When a class is added to the DOM, the browser performs a style recalculation by invalidating the cached styles of the affected element and its descendants. The engine iterates through the style rules to determine the new computed style, which can be computationally expensive if the document contains a large number of nodes or complex selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3854cb02-d6b8-40b8-a4e1-86586be95b13', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does ''type-safe'' mean in the context of the Rocket framework?', N'Intern', N'Type-safety means that Rocket uses Rust''s powerful type system to ensure that input parameters, such as URL path segments or form data, match the expected types before the handler function is ever executed. This prevents common runtime errors by catching mismatches during the request processing phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19d0ac22-27dd-40d6-b068-865ab4446e0c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you import and export modules in JavaScript?', N'Fresher', N'In JavaScript, you can import and export modules using the import and export statements. To export a module, you can use export before a function, variable, or class, or use export default for a single default export. To import a module, you use the import statement followed by the name of the exported module and the path to the module file. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'111a9517-7cfc-4d92-a295-865be8b9e109', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of ''Hinted Handoff'' in distributed databases?', N'Senior', N'Hinted handoff is a durability feature where a replica stores a write ''hint'' for another node that is temporarily unavailable. Once the failed node recovers, the helper node delivers the missed updates, reducing the window of inconsistency without requiring a full anti-entropy read-repair process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55b97e1-9561-495f-bc6d-865c413c3c84', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a microTask queue', N'Intern', N'Microtask Queue is the new queue where all the tasks initiated by promise objects get processed before the callback queue. The microtasks queue are processed before the next rendering and painting jobs. But if these microtasks are running for a long time then it leads to visual degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a87a49d-84c6-43b4-b52b-865c71cca0a9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''search path'' in R?', N'Middle', N'The search path is a hierarchy of environments, starting from the global environment and extending to loaded packages, where R looks for objects by name. Understanding this order is critical for preventing naming conflicts when multiple packages export functions with the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aa708f0-5990-443e-b4ff-8660cf76753e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of Hono''s RPC feature, and what are its performance trade-offs?', N'Middle', N'The RPC feature allows the client to infer types directly from the server''s routes, eliminating the need for manual API documentation or custom SDKs. The performance overhead is negligible, as it is essentially a thin wrapper that improves developer productivity and safety during integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'982b7e22-eb38-4cb9-b1d9-86635abd9e66', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the concept of ''Request Scoped'' dependencies in Litestar.', N'Middle', N'Request-scoped dependencies are created at the start of a request and destroyed once the response is sent. This ensures that resources like database transactions or user session information are isolated per request, preventing data contamination between parallel processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66244e26-52dd-4388-be46-866385b9f16d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an API, how do you decide whether to use REST or GraphQL?', N'Junior', N'REST is ideal for simple, predictable data requirements and leverages standard HTTP caching effectively. GraphQL is a better choice if the client needs to request specific fields across multiple resources in a single call, helping to prevent over-fetching or under-fetching of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d18ae8b-02c4-46a1-a0e1-8664cc39b91d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your strategy for troubleshooting a memory leak in a production environment without causing downtime?', N'Middle', N'I would first monitor heap usage metrics to confirm the leak pattern and then trigger a heap dump during a period of high consumption. I would analyze the dump offline to identify objects that are not being garbage collected, specifically looking for long-lived references or unclosed resources in the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a997d46b-2399-4ca9-82f2-86673ca88082', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the N+1 query problem and how can it be mitigated?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a set of records and then executes an additional query for each record to fetch related data. It can be mitigated by using join statements or eager loading techniques to fetch all necessary data in a single batch query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9434a21d-dce0-4cb9-ab71-86677e9c4ddc', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary architectural goal of Qwik compared to traditional frameworks?', N'Middle', N'Qwik aims to achieve near-instant page loads by eliminating hydration. It achieves this through resumability, where the application state and event listeners are serialized and recovered on the client without re-executing the entire component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da40ab64-4670-4a46-beb3-86678721ea4f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When designing an API, how do you decide between synchronous and asynchronous communication?', N'Middle', N'Synchronous communication is preferred when the client requires an immediate response to confirm an action. Asynchronous communication, often using message queues, is better for long-running processes or high-volume tasks where decoupling services and improving system resilience are prioritized over immediate feedback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91fcadfd-1cd9-45bf-a6de-86686f14581d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''IHostedService'' and ''BackgroundService'' abstractions?', N'Senior', N'These abstractions allow developers to run long-running, background tasks within the application process, such as message queue consumers, scheduled jobs, or cache refreshes. They integrate with the host''s lifecycle, ensuring that background work starts and stops gracefully along with the web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a742c55-e978-45f3-9395-86690b616759', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does ''null'' mean in the context of pointers?', N'Intern', N'A null pointer is a pointer that does not point to any valid memory address. It is often used to indicate that a pointer is not currently initialized or to signify the end of a data structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
