INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1ccf3d6-935e-4b8a-9618-8671fc2aea57', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is CSS flexbox?', N'Intern', N'The Flexible Box Layout Module, makes it easier to design flexible responsive layout structure without using float or positioning. Flexbox makes it simple to align items vertically and horizontally using rows and columns. Items will "flex" to different sizes to fill the space. Before the Flexbox Layout module, there were four layout modes: * Block, for sections in a webpage * Inline, for text * Table, for two-dimensional table data * Positioned, for explicit position of an element Flex Container: An area of a document laid out using flexbox is called a flex container. To create a flex container, we set the value of the area''s container''s display property to flex or inline-flex. As soon as we do this the direct children of that container become flex items. Flexbox Terminology:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
