INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a77d8c6d-3425-4d3f-b377-867f025f6761', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s implementation of the ''reply'' object differ from the standard Node.js response object?', N'Senior', N'The reply object is a Fastify-specific abstraction that provides a consistent API for sending responses regardless of the underlying transport layer. It manages the serialization process, header management, and error handling internally, ensuring that developers interact with a high-level interface rather than raw streams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5619a322-13d5-46e9-b298-867f0dd7960b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the security implications of using Hono''s middleware system?', N'Middle', N'Because Hono follows the standard middleware pattern, developers must be diligent about the order of execution to prevent security bypasses. If security middleware like CORS or Authentication is placed after business logic, it will not protect those specific routes, so careful architectural planning is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
