INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1584a59d-3c91-4b71-99fa-868bd7f9c40b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle form submissions differently than a standard HTML form?', N'Junior', N'Remix intercepts the standard browser form submission and sends it to the server action instead of performing a full page reload. This allows the framework to manage the UI state and revalidate data automatically after the action completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1515781a-92f6-474d-b306-868f0e8af3cd', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the primary difference between a struct and a class in C#, and when should you choose one over the other?', N'Middle', N'A class is a reference type stored on the heap, while a struct is a value type typically stored on the stack. You should choose a struct for small, immutable data structures that do not require inheritance to minimize garbage collection pressure. Conversely, choose a class for larger objects, scenarios requiring polymorphism, or when identity and reference equality are more important than value equality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bca9edcf-d079-4d05-88f7-869078a69b92', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a NULL value in a database?', N'Fresher', N'A NULL value represents missing, unknown, or inapplicable data. It is important to note that NULL is not the same as zero or an empty string, as it indicates the total absence of a value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40b79483-1132-4330-ac40-8690cef7f3fd', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Describe the lifecycle of an action in Redux and how it interacts with the root store.', N'Senior', N'An action is dispatched to the store, where it passes through any configured middleware. Once processed, it reaches the root reducer, which combines the results of smaller reducers to produce a new state tree. Finally, the store notifies all subscribers, triggering re-renders in components connected to the updated state slices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9286619-5a4a-41cc-a4b3-8697563bcaa8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does declaration merging work with interfaces?', N'Middle', N'Declaration merging allows the TypeScript compiler to automatically merge multiple interface declarations with the same name into a single definition. This is highly useful for extending third-party libraries or adding properties to the global scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2552e96-ddc5-406b-b703-8697b9d21e36', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the viewport meta tag in responsive web design?', N'Middle', N'The viewport meta tag instructs the browser on how to control the page''s dimensions and scaling on different devices. Without it, mobile browsers often render pages at a desktop width and zoom out, leading to a poor user experience. Setting width to device-width ensures the content scales appropriately to the screen size of the device.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1cea763-37fc-445a-97a7-869d14addcab', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s ''copy-on-write'' mechanism optimize performance for variable assignments?', N'Senior', N'Copy-on-write allows multiple variables to point to the same internal ZVAL in memory. A separate copy is only created if one of the variables is modified, significantly reducing memory usage and CPU overhead during simple variable assignments and function arguments passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f22ab4d-f864-42fb-bafd-869d5adb08f1', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''Request Guard'' in Rocket?', N'Fresher', N'Request Guards are a mechanism used to validate incoming requests before they reach the route handler. They can perform tasks like authentication or data validation, and if the guard fails, Rocket automatically rejects the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d86b4e8-cad6-4d89-b7c4-869fbc338283', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why does SolidJS require the use of ''mergeProps''?', N'Middle', N'mergeProps is used to combine multiple objects into a single set of props while maintaining reactivity. It ensures that if the source signals change, the merged object correctly propagates those updates to the consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'add3ab40-6326-4db8-8a26-86a0cb25eb99', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What happens to a Stream when there are no listeners attached?', N'Middle', N'In Dart, streams are either ''cold'' or ''hot''. A cold stream usually waits until a listener is attached before starting its data production, while a hot stream might emit events regardless of whether anyone is listening, potentially resulting in data loss if the producer is faster than the consumer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76607479-60a9-4d06-afbb-86a1d847e693', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''package'' keyword?', N'Fresher', N'The package keyword defines which package a file belongs to, which organizes code into logical units. It also controls the visibility of identifiers, where names starting with a capital letter are exported and accessible from other packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1e402ff-da79-42e2-9fbf-86a224efcf52', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe the difference between a database transaction and a database lock.', N'Middle', N'A transaction ensures that a series of operations either all succeed or all fail, maintaining data integrity. A lock is a concurrency control mechanism that prevents multiple processes from accessing or modifying the same resource simultaneously, preventing race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'971872ec-0703-431e-9d87-86a6e744cac9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it important to align the Elasticsearch JVM heap size with the underlying operating system''s RAM?', N'Senior', N'Elasticsearch relies heavily on the OS file system cache to cache segments and speed up searches. If the JVM heap is too large, it leaves insufficient RAM for the OS, negating the benefits of the file system cache and significantly degrading search performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee1678c0-1611-4cec-8019-86a9b7797d1d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is a loader function in Remix?', N'Fresher', N'A loader is a function that runs exclusively on the server to fetch data required by a specific route. It is called before the component renders, ensuring that the necessary data is ready to be displayed as soon as the page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aff4a94e-5abb-4624-874d-86aa930c4819', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the difference between select_related and prefetch_related and when to use each.', N'Middle', N'select_related performs a SQL join to retrieve related objects in a single query, which is ideal for single-valued relationships like ForeignKey or OneToOne. prefetch_related performs separate lookups for each relationship and joins them in Python, which is necessary for multi-valued relationships like ManyToMany or reverse foreign keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30c18ecf-4c8b-477e-9926-86ab14f73dd3', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''property'' decorator used for?', N'Junior', N'The property decorator tells Lit that a specific class field should be tracked for changes. When that field is modified, Lit automatically schedules an update to reflect the change in the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5cb6ff6-f82c-4e29-b1a1-86ab354901fd', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''innodb_flush_log_at_trx_commit'' setting affect data integrity?', N'Senior', N'A value of 1 ensures the log is flushed to disk on every commit, guaranteeing ACID compliance but limiting transaction throughput. Lower values improve write performance by buffering log flushes but risk losing the most recent transactions during a power loss or kernel panic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10a0bdc0-1705-4763-b0d0-86ad7c3548cc', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the ''Balancer'' and why is it important?', N'Senior', N'The balancer is a background process that monitors the distribution of data across shards and migrates chunks to ensure an even balance. It is vital for preventing one shard from becoming a performance bottleneck while others remain underutilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36881667-d9bd-455a-833a-86af5f666414', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary purpose of Alpine.js and how does it differ from a framework like React?', N'Junior', N'Alpine.js is a lightweight, declarative framework designed for adding minimal interactivity directly into HTML markup. Unlike React, which is a component-based library that requires a build step and manages complex application state, Alpine.js is intended to be dropped into a page via a script tag to handle simple tasks like toggling visibility or managing form inputs without the overhead of a virtual DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c8a174f-9a47-4482-b999-86afc31f8f3c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the useRef hook in React and when should it be used?', N'Fresher', N'The useRef hook in React is used to create a mutable object that persists across renders. It can be used to access and manipulate DOM elements directly, store mutable values that do not cause re-renders when updated, and keep a reference to a value without triggering a re-render. For example, you can use useRef to focus an input element: ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ada640b5-dfbc-4d1a-a8ea-86b653d3120e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the performance impact of Astro''s ''View Transitions'' compared to a traditional full-page refresh.', N'Senior', N'View Transitions allow for seamless SPA-like navigation by morphing the DOM between pages while maintaining layout persistence. This improves the user experience by providing fluid animations and state preservation without the complexity of managing a full client-side router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
