INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ff8ff4-dcd1-4220-b4be-86bc18c798f7', N'075b8862-431c-4678-9767-f55359758a4a', N'What are custom directives?', N'Intern', N'Custom Directives are tiny commands that you can attach to DOM elements. They are prefixed with v- to let the library know you''re using a special bit of markup and to keep syntax consistent. They are typically useful if you need low-level access to an HTML element to control a bit of behavior. Let''s create a custom focus directive to provide focus on specific form element during page load time, Now you can use v-focus directive on any element as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b8f82d6-83e1-4ec3-89db-86bd7b08ae19', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the benefits and drawbacks of using ActionCable for real-time features compared to external services?', N'Senior', N'ActionCable allows for seamless real-time updates within the Rails ecosystem using WebSockets, reducing the need for external service integration. However, it is stateful and memory-intensive, which can make scaling the application horizontally more challenging compared to offloading real-time traffic to specialized third-party message brokers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eadbaf94-f03a-4669-94b9-86c13866c084', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle WebSocket upgrades?', N'Middle', N'Actix provides built-in support for WebSockets through a specific handler that accepts a request and upgrades the connection. Once upgraded, the connection is managed by an actor that can handle asynchronous messaging between the client and the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
