INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'734a4036-54cf-4a97-a31a-86cb1fbaca74', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do channels facilitate communication between goroutines?', N'Junior', N'Channels are pipes that connect concurrent goroutines, allowing them to send and receive values. They act as a synchronization mechanism to ensure that data is passed safely between goroutines without needing explicit locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
