INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ade9c7fd-945a-48f5-91fa-86cf6928d12a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How can ''template literal types'' be leveraged to model domain-specific languages within TypeScript?', N'Senior', N'Template literal types allow for string manipulation and pattern matching at the type level, enabling the definition of complex constraints like URL builders or localized keys. They provide compile-time safety for string-based APIs, though they can significantly increase the complexity of type resolution and lead to performance overhead if overused.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c55d4cf6-5c4e-4f95-a2ed-86cfb600627a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the N+1 query problem in Rails and how can you solve it?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch parent records and then executes an additional query for each parent to fetch associated children. It is solved using eager loading methods like includes, preload, or eager_load, which fetch associated data in a single or minimal number of queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
