INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41a092cb-51fd-4974-a18c-86d4dd060549', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the difference between ''debouncing'' and ''throttling'' in event handling.', N'Senior', N'Debouncing resets a timer on every event, executing the callback only after a period of inactivity, which is ideal for search inputs. Throttling ensures a function executes at most once every specified interval, which is ideal for scroll or resize events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
