INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'303d2a7f-8394-4136-82e6-86e6ec223d3f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you configure a database in Laravel?', N'Fresher', N'In Laravel, configuring a database is crucial for data persistence. By default, Laravel uses MySQL. However, you can easily configure it to work with a variety of databases such as PostgreSQL, SQLite, and more. Steps to Configure a Database 1. .env File: - Define the connection details in the .env file, including the database type, host, port, and credentials. 2. config/database.php: - Laravel configures the database connection dynamically based on the settings in the .env file. For more specific settings, you can modify the config/database.php file. 3. Migrations & Models: - Use Laravel''s migration files to maintain your database and models to interact with tables. 4. Eloquent ORM: - Access database tables using Laravel''s Eloquent ORM. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
