INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ca42522-79b8-4517-af29-86f5daed6608', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the impact of index overhead on write performance in a high-concurrency database?', N'Senior', N'Every index on a table requires an additional write operation whenever a record is inserted, updated, or deleted, leading to write amplification. In high-concurrency systems, excessive indexing can saturate disk I/O and increase lock contention, necessitating a careful balance between read-speed requirements and write-throughput needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
