INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60ad47d6-fb1f-42b7-9ef6-86fcbcaf8c8e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the security implications of exposing the ''Server'' or ''X-Powered-By'' HTTP headers, and how do you remove them?', N'Senior', N'These headers reveal information about the server infrastructure and framework version, which can be used by attackers for reconnaissance. You can remove them by configuring the Kestrel server options or by adding a middleware component to strip these headers from the outgoing response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ce0ba1e-6c1d-4fc9-ac6b-86fceca5e535', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of hoisting in JavaScript.', N'Junior', N'Hoisting is the default behavior where variable and function declarations are moved to the top of their containing scope during the compilation phase. While function declarations are fully hoisted, variables declared with let and const are hoisted but remain in a temporal dead zone until the line of declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb0a437b-2484-43fc-b50f-86fcf89aadf8', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage environment variables?', N'Fresher', N'In Hono, environment variables are typically accessed through the context object or the runtime''s global configuration. This allows the framework to remain flexible across different deployment platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4400b9b1-8491-4290-accd-86ff8304e2b2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain how Gin''s Binding feature handles type safety and its potential for runtime errors.', N'Senior', N'Binding automatically validates request data against struct tags, providing a convenient way to enforce API contracts. However, because it relies on reflection, type mismatches or missing tags can lead to runtime errors or silent failures; robust production systems should implement manual validation as a secondary layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c16ec485-b49c-4c21-913b-8701a37f8804', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI generate OpenApi and JSON Schema documentation, and why is this useful?', N'Middle', N'FastAPI automatically generates an OpenAPI schema by introspecting path operations, type hints, and Pydantic models. This provides an interactive documentation UI like Swagger or ReDoc out-of-the-box, which simplifies API discovery and testing for frontend teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'676f2051-e17a-44a0-8de1-8701ca43f252', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does it mean that Fiber is built on top of Fasthttp?', N'Junior', N'It means that Fiber inherits the performance benefits of Fasthttp, such as zero-allocation request handling. However, it is important to note that Fasthttp is not fully compatible with the standard net/http interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54e15dc9-3123-437d-9bcf-87021a15775d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''associatedtype'' in protocols?', N'Middle', N'Associated types act as a placeholder for a specific type that will be defined by the type conforming to the protocol. They are essential for creating generic protocols, allowing developers to build flexible interfaces that work with varying data types while maintaining type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a7cffc7-85e1-4104-9df7-8703b666e95e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of the ''Next'' function in Fiber middleware?', N'Intern', N'The Next function is used within middleware to pass control to the next function in the chain. If a middleware decides not to call the Next function, the request-response cycle is effectively halted, and the subsequent handlers will not be executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
