INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a4c73f8-bba1-4ecb-bfd2-87090b7c22c6', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ''ul'' and ''ol'' lists?', N'Junior', N'A ul represents an unordered list where the order of items does not matter, typically using bullet points. An ol represents an ordered list where the sequence of items is significant, typically using numbers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deecb305-ee0f-40b1-b51d-87098afe705e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing an API style (REST vs. GraphQL vs. gRPC), how do you assess the trade-offs?', N'Senior', N'REST is chosen for public-facing APIs due to its simplicity and broad compatibility. GraphQL is preferred when client-side developers need to minimize payload sizes and prevent over-fetching, while gRPC is chosen for internal service-to-service communication where high performance and strict contract definitions are required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12388863-ef7e-44a9-bc80-870d1b270188', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose a fixed-size data structure over a dynamic one?', N'Fresher', N'Fixed-size structures are generally more memory-efficient and have predictable performance because they avoid the overhead of resizing. Dynamic structures offer flexibility and ease of use but may involve costly memory reallocation operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cae39214-fc3a-475b-8bd7-870d1e4d69f6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''noImplicitAny'' setting and why is it necessary for a project to be considered ''strictly typed''?', N'Senior', N'This setting prevents the compiler from defaulting to ''any'' when a type cannot be inferred, requiring explicit annotation. It ensures that every part of the codebase is covered by the type system, preventing hidden bugs caused by variables that lack structural definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a5f262c-530f-49d7-9cf0-870d1ea613dd', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When dealing with logging, what is the trade-off between verbose logging and storage costs/performance?', N'Middle', N'Verbose logging provides excellent visibility for debugging complex issues, but it significantly increases storage costs and can negatively impact application performance due to I/O overhead. The trade-off involves implementing tiered logging levels where debug logs are only enabled in specific environments or for specific modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2362feee-eee7-4f9d-ba55-870e16c5345d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the benefits of using hooks in React?', N'Intern', N'Hooks let you use state and other React features in plain functions, without classes. They were introduced to solve real pain points in the class-component era — "wrapper hell" from HOCs and render props, the awkwardness of this binding, and the difficulty of sharing stateful logic between components. Custom hooks make that logic genuinely reusable through composition. React 19 expands the set further with hooks like use, useActionState, useOptimistic, and useFormStatus for promises, forms, and optimistic UI. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
