INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'168d3082-d4ab-4a89-919e-8718f1e87fd0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the trade-off of using Rust''s ''String'' versus ''&str''?', N'Middle', N'String is an owned, growable heap-allocated buffer, while &str is an immutable reference to a sequence of UTF-8 encoded bytes. String allows for mutation and ownership transfer, but it involves heap allocation, whereas &str is a lightweight view that is more efficient for read-only access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f38b0e40-805e-4564-9e9c-871a745f08b2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express''s routing engine scale as the number of routes increases to thousands?', N'Senior', N'Express uses a linear regex-matching process for routes, which can introduce latency as the route table grows. For very large applications, this can lead to measurable degradation, necessitating the use of organized sub-routers or migrating to a more performant routing engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0a82fd7-9d83-4636-bb38-871ab3a2aba2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Analyze the impact of PHP''s cyclic garbage collection on long-running processes.', N'Senior', N'The cyclic garbage collector periodically scans for circular references that reference counting cannot resolve. This prevents memory leaks in long-running processes, such as those used in CLI-based message consumers, by proactively deallocating unreachable memory structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
