INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9643baf2-c7f6-4737-aafe-8721200c736d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your strategy for troubleshooting a distributed deadlock in a system using a consensus algorithm?', N'Senior', N'I would examine the state machine logs of the nodes to identify which node is holding a lock or waiting for a quorum response that never arrives. I would also look for network partitions or misconfigured leader election timeouts that might be causing nodes to become stuck in a perpetual re-election or recovery state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
