INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f7dba1-5385-4b91-bdb1-8723506886ed', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the trade-offs of using ''async/await'' versus chaining ''then'' callbacks?', N'Middle', N'Async/await provides a linear, synchronous-looking style that simplifies debugging and error handling via standard try-catch blocks. Chaining ''then'' callbacks can lead to deeply nested code, often referred to as ''callback hell,'' though it can be more performant in very specific, high-frequency execution scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d55e810-9cd2-41cc-90e0-872ce54fbebe', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are HTML events?', N'Intern', N'HTML events are actions or occurrences that happen in the browser — triggered by the user or by the browser itself. JavaScript can listen for these events and execute code in response. Events can originate from: - User interaction — mouse clicks, key presses, form input - Browser lifecycle — page load, resize, scroll - Media — video play/pause/end - Network — online/offline state changes How to handle events: 1. Inline HTML attribute (not recommended): 2. DOM property: 3. addEventListener (recommended): addEventListener is preferred because it allows multiple listeners on the same element and provides cleaner separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
