INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e136efeb-33ed-464f-87bf-872edf423421', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Can you explain a Pointcut and an Advice in Spring AOP?', N'Junior', N'A Pointcut in Spring AOP defines the join points matched for advice and determines the regions in an application where cross-cutting concerns are applied. In AOP, a Pointcut serves as a predicate for identifying the locations in an application where advice is to be applied. These locations are primarily method executions but can also include field references and updates. Certain attributes are fundamental to Pointcuts. For example, the scope of the application and the type of join points, for instance, the Start of the Method of execution or even well within its body. Using Pointcuts To apply AOP in Spring, mark the points in your application where cross-cutting is required. From there, define methods using annotations such as @Before, @After, or @Around to apply the advice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2583241-af03-46e1-8ab3-873236d39455', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the performance implications of using ''find_each'' versus ''all'' when fetching large datasets?', N'Middle', N'Using ''all'' loads every record in the table into memory at once, which can cause significant memory pressure or crashes with large datasets. ''find_each'' fetches records in batches, keeping memory usage stable regardless of the total record count.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
