INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ec588a4-8045-4a65-9b2a-87436f7a3abe', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Does Rust support object-oriented programming?', N'Fresher', N'Rust is not purely object-oriented, but it provides features like structs for data storage and traits for behavior definition. While it lacks class-based inheritance, it achieves polymorphism through traits and composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6974719-9aa1-4270-b91b-8743ee8ed770', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the primary architectural advantage of Litestar over frameworks like Flask?', N'Middle', N'Litestar is built from the ground up to be asynchronous and utilizes type hints for automatic request parsing and validation. This design allows for better performance and reduced boilerplate compared to the traditional synchronous patterns found in Flask.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d32765f-83f4-4c06-92a3-874597c5b65e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the ''createMemo'' primitive?', N'Middle', N'createMemo is used to cache the result of a computation that depends on other signals. It ensures that the calculation only re-runs when its specific dependencies change, preventing expensive operations from executing unnecessarily during every render cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5e5661b-419a-4561-a677-87490f1de809', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact often favored in ''low-power'' or mobile-first environments?', N'Senior', N'Preact''s minimal CPU requirements and small bundle size result in faster execution times on devices with limited processing power. By reducing the time spent parsing and executing JavaScript, it significantly improves battery life and responsiveness on mobile browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95a2fe7c-a17e-46ce-bdaf-874985126d00', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Describe the difference between vertical and horizontal scaling and why horizontal is preferred for distributed systems.', N'Senior', N'Vertical scaling increases the resources of a single node, which hits a hardware ceiling and creates a single point of failure. Horizontal scaling adds more nodes to the pool, providing near-infinite capacity, improved fault tolerance, and the ability to scale components independently based on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5126a1bf-3d43-4b85-937f-874a13558648', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the Vite configuration file?', N'Fresher', N'The vite.config file allows developers to customize the behavior of the Vite server and build process. You can use it to define plugins, set up proxy rules, configure aliases, and adjust build output settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dcf2c11-92e2-4d97-bf76-874ae87ea361', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery generally considered unsuitable for modern large-scale reactive applications?', N'Senior', N'jQuery relies on imperative DOM manipulation, which becomes difficult to maintain and debug as application state grows. Modern frameworks use declarative data-binding and virtual DOM reconciliation to manage UI state, whereas jQuery lacks a built-in state management architecture, leading to tightly coupled components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f213a26-2fb4-47ec-b5da-874bd01c17b9', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Redo Log'' ensure durability in the face of sudden power loss?', N'Senior', N'The redo log is a circular, write-ahead log that records all physical changes made to the database pages. Because it is written sequentially to disk, it is highly performant; during recovery, InnoDB replays these logs to ensure that committed transactions that were not yet flushed to the data files are persistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95d0fce3-2469-446f-9819-874d8ba38e1c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the CRAN repository?', N'Fresher', N'CRAN stands for the Comprehensive R Archive Network, which is a global network of servers that store identical, up-to-date versions of R code and documentation. It is the official and primary repository for downloading R and verified R packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78492085-24b4-49ed-abd6-874e615e2a4d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''ShouldBindQuery'' method in Gin?', N'Middle', N'ShouldBindQuery is specifically designed to parse and validate URL query parameters into a struct. It is more efficient than manually retrieving parameters from the context and performing type conversion, as it automates the mapping and validation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57b4678b-4779-476d-9bef-874eff2e3da8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is database replication?', N'Junior', N'Replication is the process of copying data from one database server to another. It is used to improve read performance by distributing traffic and to provide high availability by ensuring a backup server can take over if the primary fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55d92411-2ed0-4f69-817f-874fbbb5f0f9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the primary key in a database table?', N'Fresher', N'A primary key is a specific column or set of columns that uniquely identifies each record in a database table. It must contain unique values and cannot contain null values, ensuring that every row can be accessed independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
