INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ca30c96-2e05-46e3-a113-8752860c9d67', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How do you determine if a query is performing a collection scan versus an index scan?', N'Middle', N'You can use the explain execution plan tool to analyze the query performance. If the ''totalDocsExamined'' is significantly higher than ''nReturned'', or if the ''inputStage'' indicates ''COLLSCAN'', it means the database is scanning the entire collection instead of using an index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a2289a1-8495-4770-9216-8752b4b80597', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the architectural trade-off of using Chi''s built-in middleware versus building a custom decorator pattern.', N'Senior', N'Chi’s middleware is optimized for the standard library and integrates seamlessly with the router''s lifecycle. Custom decorators can provide more granular control but may introduce complexity or incompatibility with Chi''s context-aware utilities and standard net/http handler expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'836f612a-00c2-4887-8688-8752e9fe4af7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Does Rocket require a specific web server to run?', N'Intern', N'Rocket includes its own built-in, multi-threaded web server based on the Tokio asynchronous runtime. It is designed to handle high concurrency out of the box without requiring external configurations like Nginx or Apache to serve the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c645de4d-ef9b-4104-93dd-8754f55096f1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you implement custom extractors in Axum?', N'Middle', N'Custom extractors are implemented by creating a struct that implements the ''FromRequestParts'' or ''FromRequest'' trait. This allows developers to encapsulate complex logic, such as validating a JWT token or checking custom headers, into a reusable, declarative format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9fe6efd-ba37-45c0-93d6-8755c3221ddd', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ACID property of atomicity prevent partial updates?', N'Middle', N'Atomicity ensures that all operations within a transaction are treated as a single unit; either all operations succeed or none are applied. If any part of the transaction fails, the database rolls back to the state existing before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cbf0a6d-9885-40a8-9849-8756eddd0274', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS Custom Properties differ from preprocessor variables in terms of scope and reactivity?', N'Senior', N'Preprocessor variables are processed at build-time and lack runtime awareness. CSS Custom Properties are dynamic, living in the DOM tree, and can be updated via JavaScript or media queries to trigger live style updates across the entire application without needing a full re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fbf2fbd-7c4d-493b-b606-875974f2bb2b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the performance overhead of implementing a new security protocol across a distributed service mesh?', N'Senior', N'I would design a controlled canary deployment to measure the baseline latency shift and resource consumption per request before a full rollout. By extrapolating this delta across the total peak request volume, I can accurately predict the necessary head-room required in the service mesh control plane and sidecar proxy fleet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c1b4f60-51e3-4f65-bbf6-876370500f74', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between props and state in Svelte?', N'Fresher', N'Props are values passed down from a parent component to a child, making the child dynamic based on external input. State refers to the internal data managed within a component that dictates its current appearance or behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a97629a-4175-404f-bc7a-8768552d5a9b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary difference between a SPA and Universal rendering in Nuxt?', N'Intern', N'A Single Page Application (SPA) renders content entirely in the browser, while Universal rendering performs the initial page render on the server. Universal rendering improves search engine optimization and perceived performance because the browser receives a fully populated HTML document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d6ee125-65a4-4b04-893b-87694933b07e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @use rule?', N'Intern', N'The @use rule is the modern way to import Sass modules. It namespaces the content of the imported file, which helps avoid naming conflicts and makes it clearer where specific variables or mixins are coming from.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd790f23-5136-4d06-b76e-87698cad493c', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a unique index?', N'Junior', N'A unique index ensures that the indexed fields do not store duplicate values for any document in the collection. This is commonly used for fields like email addresses or usernames to maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edadba06-6362-420a-9d1a-876a1336a465', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why might you implement a custom ''errorHandler'' instead of relying on the default one?', N'Middle', N'A custom error handler allows you to map specific internal errors to standardized API error responses, such as masking database stack traces for security. It also enables centralized logging of errors to external monitoring services like Sentry or Datadog.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffbf1fea-68e5-4bee-a28f-876be335b4d2', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL''s MVCC implementation handle vacuuming, and what are the potential performance implications of long-running transactions?', N'Senior', N'PostgreSQL uses Multi-Version Concurrency Control to allow simultaneous reading and writing without blocking. Long-running transactions prevent the VACUUM process from reclaiming space occupied by dead tuples, leading to table bloat and degraded query performance due to increased I/O requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d9a08a8-90a3-49cd-9b68-876c49c84712', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Discuss the impact of Svelte''s approach on ''hydration'' in large, data-heavy applications.', N'Senior', N'Svelte''s approach to hydration is significantly lighter because it doesn''t need to rebuild the entire state tree to match the server output. It simply attaches event listeners and establishes its reactive bindings, which reduces ''jank'' and improves the perceived performance of the page during the transition from static HTML to an interactive app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'362ccf7a-f4ff-476b-96c4-876df07e8d12', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is SvelteKit considered a ''meta-framework''?', N'Fresher', N'It is called a meta-framework because it adds a layer of configuration and tooling on top of the Svelte UI library. It solves common problems like routing, data fetching, and build optimization that Svelte itself does not handle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ade4e612-4d63-4bb3-ac8a-876f2a97e93b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it often impossible to optimize for both development speed and code maintainability simultaneously?', N'Fresher', N'Development speed often relies on quick, tactical decisions that may create technical debt. Maintainability requires structured, long-term planning, which takes more initial time to implement properly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb5fd37f-6c04-4149-ad91-8770462a8cc6', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the CAP theorem and how does it relate to NoSQL systems?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. NoSQL databases are often categorized by how they navigate these trade-offs, particularly in distributed environments where network partitions are inevitable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4defca2-8bca-4cc4-84ba-87711b8a1963', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between real-time data streaming and batch processing?', N'Senior', N'Real-time streaming enables instantaneous insights and reactions but is resource-intensive and complex to maintain. Batch processing is highly efficient and predictable for massive datasets, but it introduces latency, meaning decisions are always based on a historical view of the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
