INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56cdfbfd-c26b-4ba8-8c0f-8776f6b25159', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How can you improve the security of an API beyond basic authentication?', N'Middle', N'Security can be enhanced by implementing rate limiting, input validation to prevent injection attacks, and using TLS for data encryption in transit. Additionally, incorporating OAuth2 or OpenID Connect provides robust authorization and delegated access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0894f7b9-14aa-4f9c-9fd1-877860c4288f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is an Exception Handler in Litestar?', N'Intern', N'An exception handler is a function registered to catch specific types of exceptions raised during the request-response cycle. It allows developers to return custom error responses to the client instead of standard server errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74d33d10-f400-473b-b0db-8779713f0670', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix require a client-side router?', N'Junior', N'Remix includes its own internal router based on React Router. It handles transitions between routes and ensures that data is fetched and updated correctly during navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9401677-3400-40d2-b17c-8779dca2c722', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is meant by strict null checking in TypeScript?', N'Fresher', N'Strict null checking is a compiler option that ensures that ''null'' and ''undefined'' are not implicitly assignable to other types. This forces developers to explicitly handle cases where a value might be missing, which prevents common runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7bb6a64-e7aa-4b2d-8a6e-877f454f32ab', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle connection management compared to other databases?', N'Middle', N'PostgreSQL creates a separate OS process for every incoming connection, which can lead to high memory consumption under heavy load. Because of this overhead, it is standard practice to use connection poolers like PgBouncer to manage and reuse existing connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'407c0bf2-f3d6-47ff-9180-8785a0e1e7ae', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the types of memory leaks in node.js?', N'Intern', N'A memory leak is a condition that occurs when a program doesn''t release the memory it allocates. For instance, the system assigns memory locations to store values for the variables that we declare inside our program. High-level programming languages such as JavaScript utilize automatic memory management, known as garbage collection. Garbage collection allocates the memory to a variable once we declare it and reclaims the memory once it is no longer needed. Unfortunately, even though JavaScript uses a garbage collector to release the memory, sometimes determining whether to free the memory or not is undecidable. The common causes of Memory Leaks in Node.JS are: 1. Global variables: This is one of the most common causes of leaks in Node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
