INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3212c93-160f-4f3a-989d-878929074eb1', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does it mean for a programming language to be statically typed?', N'Intern', N'In a statically typed language, variable types are checked at compile-time rather than runtime. This means the programmer must declare the data type of every variable, which helps catch type-related errors before the program ever runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10a2f8a2-77e5-4b47-9e28-8789c60f6cc7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why use React in 2026?', N'Fresher', N'* Server-Side First: Modern frameworks (e.g., Next.js, Remix) built on React leverage React Server Components (RSC) for superior SEO and performance metrics. * Declarative UI: By defining UI as a function of state ($UI = f(state)$), React simplifies state transitions and ensures predictable rendering. * The Ecosystem: 2026 React is part of a massive ecosystem including TanStack (Query/Router), Zustand (State), and Tailwind CSS, providing a standardized path for enterprise-grade scalability. * Type Safety: First-class support for TypeScript is now the baseline. Prop definitions and state types are strictly enforced during the build process, minimizing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d4fcd30-9577-4634-ab2f-878c9c3b5040', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''register'' function used for in Fastify?', N'Intern', N'The register function is used to load plugins into your Fastify application. It creates a new encapsulation context, ensuring that the loaded plugin operates within its own isolated scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bae5be57-1d4c-4939-a7ea-878da91d30c5', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is type safety and type inference in Swift?', N'Fresher', N'Type safety means the language prevents code from performing operations on incompatible types, such as adding a string to an integer. Type inference allows the compiler to automatically deduce the type of a variable based on the value provided, which reduces the need to explicitly declare the type in the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36d0475e-6c14-4136-b38a-87927dad2526', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does cache partitioning (sharding) improve the scalability of a distributed cache?', N'Senior', N'Sharding distributes the cache keyspace across multiple nodes, allowing the system to scale horizontally and handle larger datasets than a single node could accommodate. It also distributes the request load, preventing a single cache node from becoming a bottleneck for throughput or network bandwidth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2be81090-eece-4105-80f1-8794039fbc3f', N'954a0331-deff-4399-b588-96f39fec001d', N'What is an angular library?', N'Intern', N'An Angular library is an Angular project that differs from an app in that it cannot run on its own. It must be imported and used in an app. For example, you can import or add service worker library to an Angular application which turns an application into a Progressive Web App (PWA). Note: You can create own third party library and publish it as npm package to be used in an Application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'763d972f-f754-4589-b2c3-879556cbbf17', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure data safety during server restarts?', N'Middle', N'Redis ensures data safety through its persistence mechanisms, RDB and AOF. By loading the RDB snapshot or replaying the AOF log upon startup, the server can reconstruct the dataset as it existed prior to the shutdown or crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8248ed60-f254-4b70-ac15-879650899028', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the architectural trade-offs of using SvelteKit''s adapter-auto compared to target-specific adapters.', N'Senior', N'Adapter-auto provides a generic abstraction that detects the environment, making it ideal for quick prototyping or multi-platform deployments. However, using target-specific adapters like adapter-node or adapter-vercel allows for deep integration with platform-specific features like edge functions, incremental static regeneration, or specialized caching headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76ae6ff1-6f8a-472f-b314-879a47a9f3c6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is AJAX', N'Intern', N'AJAX stands for Asynchronous JavaScript and XML and it is a group of related technologies(HTML, CSS, JavaScript, XMLHttpRequest API etc) used to display data asynchronously. i.e. We can send data to the server and get data from the server without reloading the web page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b02f80b-a1cd-4d91-ab97-879c41b4f1b2', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the role of idempotent methods in RESTful API design.', N'Middle', N'Idempotent methods, such as GET, PUT, and DELETE, guarantee that multiple identical requests produce the same result as a single request. This is critical for building resilient systems where network retries are expected without causing unintended side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c895dcf5-3ecd-4fe3-b010-879cdeedb4fc', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the ''virtual'' keyword in inheritance?', N'Junior', N'The virtual keyword enables polymorphism by allowing a derived class to override a function defined in the base class. It ensures that the correct function is called at runtime based on the actual object type rather than the pointer or reference type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75afa2c5-20cd-46c0-b59f-879e6f742bca', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle CSS scoping?', N'Intern', N'Lit uses Shadow DOM to provide strict CSS encapsulation. Styles defined within a component''s static styles property are automatically scoped to that component, meaning they will not affect or be affected by global CSS styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c19ae66-b24d-44dd-903d-87a8e5916b9a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is ''SELECT *'' considered an anti-pattern in high-scale MySQL environments?', N'Senior', N'It increases network bandwidth consumption and prevents the use of covering indexes, which allow queries to be satisfied entirely from the index tree. Fetching unnecessary columns also forces more page reads into the buffer pool, reducing overall cache efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84480bb4-4490-427c-b38c-87ab41dcc6e9', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the difference between an Event and a Listener in Laravel.', N'Middle', N'An Event is a simple object that represents an occurrence in the application, while a Listener is a class or closure that handles the logic triggered by that event. This decoupling allows you to trigger side effects without modifying the primary business logic flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c37ffd6-6044-4820-a4c5-87acc20bdf6e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the Master Node?', N'Intern', N'The master node is responsible for lightweight cluster-wide operations such as creating or deleting an index, tracking which nodes are part of the cluster, and deciding which shards to allocate to which nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81073378-e766-40d8-b6a5-87b078b84548', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rust''s ownership model beneficial for Rocket?', N'Intern', N'Rust''s ownership model ensures memory safety without needing a garbage collector. This makes Rocket applications highly efficient and prevents common memory-related vulnerabilities that can occur in other web frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59058262-1dd3-4968-bae5-87b2f3cfa9f1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the impact of ''Tombstones'' in LSM-tree based databases and how to mitigate their performance degradation.', N'Senior', N'Tombstones are markers used to track deletions in immutable files, which can accumulate and degrade read performance because the database must scan through them to verify if a record was deleted. Performance can be mitigated by aggressive compaction strategies that merge files and physically purge data marked by tombstones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e37da06f-d627-4173-be8a-87b318901799', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is encapsulation in Java?', N'Intern', N'Encapsulation is the practice of wrapping data and the methods that operate on that data into a single unit called a class. It restricts direct access to some of an object''s components, which helps prevent accidental modification of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21359a05-d52f-4c94-a9f7-87b32eee7db4', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is Replication Factor in Cassandra?', N'Intern', N'The replication factor determines the total number of nodes in the cluster that will hold a copy of the same data. Increasing the replication factor improves fault tolerance and read availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab94cfe0-f453-415a-a815-87b3abdeada3', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of an AdonisJS Model?', N'Fresher', N'A Model represents a table in your database. It defines the structure of your data and provides methods to perform CRUD operations, such as creating, reading, updating, and deleting records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71bfca6e-3993-4d52-a399-87b711b9e6d7', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are hreflang tags and when should you use them?', N'Fresher', N'hreflang is an HTML attribute used to tell search engines which language and/or geographic region a page is intended for. It helps Google serve the correct regional or language variant to users. When to use: - Your site has content in multiple languages (e.g., English, French, Spanish) - Your site has region-specific versions (e.g., en-US, en-GB, en-AU) - Your site has translated pages with different URLs Syntax: Rules: 1. Every page in the set must reference all other pages, including itself 2. The x-default tag indicates the fallback page when no language match is found 3. Language codes follow IETF BCP 47 format (e.g., en, en-GB, zh-Hant) 4. Hreflang can also be set in the HTTP header or XML sitemap', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb3aac28-179e-4c04-bcaa-87b7a5866bf9', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the trade-off between choosing a normalized versus a denormalized database schema?', N'Middle', N'Normalized schemas reduce data redundancy and ensure consistency, but often require complex joins that can degrade read performance. Denormalized schemas improve read performance by minimizing joins but introduce the risk of data anomalies and require more complex logic to keep data synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaf85f96-5e27-4ef3-b4b8-87b86253adaf', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are HOC factory implementations?', N'Intern', N'There are two main ways of implementing HOCs in React. 1. Props Proxy (PP) and 2. Inheritance Inversion (II). But they follow different approaches for manipulating the _WrappedComponent_. Props Proxy In this approach, the render method of the HOC returns a React Element of the type of the WrappedComponent. We also pass through the props that the HOC receives, hence the name Props Proxy. Inheritance Inversion In this approach, the returned HOC class (Enhancer) extends the WrappedComponent. It is called Inheritance Inversion because instead of the WrappedComponent extending some Enhancer class, it is passively extended by the Enhancer. In this way the relationship between them seems inverse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eec1740a-735c-4e60-b745-87b8ccf9cdf0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What strategy do you use when investigating a memory leak in a production application?', N'Middle', N'I would analyze memory heap dumps and profile the application to identify objects that are not being garbage collected. By correlating memory growth with specific traffic patterns or scheduled tasks, I can narrow down the leaking component and verify the fix in a staging environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba268221-cc66-4809-9e55-87bbb63bfa47', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the trade-offs of using ''Pin'' in Rust for asynchronous programming.', N'Senior', N'Pin is used to guarantee that a value will not be moved in memory, which is essential for self-referential structures like async state machines. While it adds complexity to the API, it allows for safe asynchronous execution by ensuring that pointers to internal state remain valid even when the underlying task is polled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a7ce25a-16b6-4177-a80f-87bc0e3568c2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing a system that requires strict event ordering, what architectural constraints do you consider?', N'Senior', N'Ensure that events are partitioned by a specific key to maintain order within that shard. Acknowledge that strict ordering often limits throughput, so carefully evaluate if a relaxed consistency model is sufficient for the business use case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31c42de6-cc24-464c-8f52-87bf9ed70b7e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the significance of the ''Isolate.spawnUri'' versus ''Isolate.spawn'' in terms of scalability.', N'Senior', N'Isolate.spawn is generally more efficient as it shares the same code base and isolates a specific function for execution. Isolate.spawnUri involves loading a new script, which incurs additional I/O and parsing overhead, making it less suitable for high-frequency task distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0daa00cb-52b3-488f-8a2c-87c4cd878adf', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a foreign key and what does it do?', N'Junior', N'A foreign key is a column that creates a link between data in two tables. It enforces referential integrity by ensuring that values in the foreign key column must exist in the primary key column of the referenced table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc8ae93d-d939-48a4-a53d-87c5ee0c424e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the ''Thundering Herd'' problem in the context of distributed caches?', N'Middle', N'The thundering herd problem occurs when a cache miss leads to a massive surge of concurrent requests hitting the database simultaneously to fetch the same missing key. This can overwhelm the database and cause cascading failures throughout the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
