INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94d4c3df-f9e3-4d70-9569-87c6a8ec0f5e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is the Lit update cycle asynchronous?', N'Fresher', N'The update cycle is asynchronous to improve performance by batching multiple property changes. If several reactive properties change at once, Lit waits until the next microtask to perform a single render, preventing unnecessary DOM updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
