INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'423c6600-c968-42c9-824a-87c90b3b929a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the trade-offs of Go''s interface implementation mechanism compared to C++ virtual tables.', N'Senior', N'Go interfaces use a two-word structure containing a type descriptor and a data pointer, resolving method calls at runtime via type assertion or dynamic dispatch. While this provides flexibility and decoupling, it introduces a slight performance overhead due to pointer indirection and potential heap allocations compared to the static, compile-time offset lookups used by C++ vtables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bd4a0f7-2249-4f45-8511-87c9bddc70ce', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte stores, and when should you use them?', N'Fresher', N'Svelte stores are objects that provide a simple mechanism for sharing state across components without requiring a complex global state management library. They are best used when multiple components need to access or modify the same data independently of the component hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
