INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bfb1d3e-b7c3-4dd7-bc28-87cf2e223566', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the use of ''Virtual Nodes'' (vnodes) improve cluster rebalancing?', N'Senior', N'Vnodes allow a physical node to own multiple smaller ranges of the hash ring rather than one large range. This makes adding or removing nodes from the cluster much faster and more balanced, as data movement is distributed across many nodes instead of just two neighbors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
