INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'215d348f-c25a-45da-9554-87d5d9c0faee', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a problem is worth solving immediately or if it can wait?', N'Intern', N'I would evaluate the problem based on its impact on the user experience and its urgency regarding system stability. If the problem blocks core functionality or poses a security risk, it requires immediate attention. Otherwise, I would compare its priority against existing tasks to determine where it fits in the roadmap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ef1ad0b-bfa1-4b55-a8a2-87d6ce7c3c3a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does the term ''singleton pattern'' refer to in PHP?', N'Junior', N'The singleton pattern is a design pattern that ensures a class has only one instance and provides a global point of access to that instance. It is commonly used for managing database connections or shared configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fabd2292-02fb-42d1-9ba6-87dbc9603291', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using a standard load balancer versus an API Gateway?', N'Middle', N'A load balancer is a simple, high-performance tool for distributing traffic across multiple instances. An API Gateway adds a layer of intelligence, providing cross-cutting concerns like authentication, rate limiting, and request transformation, but adds latency and an additional point of potential failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f6c3f7-2b10-4f20-901d-87dc92394fc6', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between an action and an action creator?', N'Middle', N'An action is a plain JavaScript object that describes an event that has occurred in the application. An action creator is a function that creates and returns these action objects, promoting reusability and consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0def62f-8540-4f00-8178-87de0a5d8596', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you verify that your solution has actually solved the problem?', N'Fresher', N'I verify the solution by testing it against the original requirements and ensuring the specific error or issue is no longer reproducible. I also conduct regression testing to ensure the fix did not break any existing functionality elsewhere in the system. Successful verification means the solution works as intended without introducing new issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56e7eec2-cfbe-4587-b598-87dfe8562e29', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a ''strong'' and ''weak'' reference?', N'Fresher', N'A strong reference increases the reference count of an object, preventing it from being deallocated. A weak reference does not increase the reference count, allowing the object to be deallocated if no other strong references exist, which helps prevent memory cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58af72b4-b8f3-46d7-8b47-87e0036c65c6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Describe the concept of ''Hydration'' in the context of React SSR.', N'Senior', N'Hydration is the process where React attaches event listeners and makes the static HTML delivered by the server interactive on the client. During this phase, React walks the DOM tree and matches it with the virtual DOM, mounting hooks and wiring up state management without re-rendering the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'208a9b58-e822-4b25-8bb2-87e07d6509b7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a declaration file (.d.ts) in TypeScript?', N'Junior', N'A declaration file is used to provide type information for JavaScript libraries that do not have built-in TypeScript support. It allows TypeScript to understand the structure of external code without needing to change the original JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd80477f2-e09f-4108-9141-87e1878ed744', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the primary purpose of using a CSS preprocessor like Sass?', N'Fresher', N'Sass extends CSS by providing features that are not available in standard CSS, such as variables, nested rules, mixins, and inheritance. It helps developers write cleaner, more modular, and maintainable stylesheets by reducing code repetition and organizing complex styles more effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33647440-f04c-4daf-b3bf-87e20f6d092a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''cache'' and why is Redis often used for this purpose?', N'Intern', N'A cache is a high-speed data storage layer that stores a subset of data so that future requests for that data are served faster. Redis is popular for caching because its in-memory nature allows it to quickly provide frequently accessed data, reducing the load on a primary database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04cd0ef2-b027-419b-9f8b-87e35653e2dc', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s ''nextTick'' function work?', N'Middle', N'Vue performs DOM updates asynchronously; when you change reactive state, the DOM does not update immediately. nextTick waits until the next DOM update cycle has finished, allowing you to execute logic that requires access to the updated DOM state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b358a04-4171-44e4-bc3a-87e4cd24b961', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''super-mixin'' constraint improve type safety in complex class structures?', N'Senior', N'Super-mixin constraints restrict the classes that a mixin can be applied to by requiring the host class to implement or extend a specific type. This ensures that the mixin has access to expected members, preventing runtime errors caused by missing requirements in the target class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d65cc76-c081-416f-8f42-87e6f801cb8a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of the Saga pattern?', N'Middle', N'The Saga pattern manages distributed transactions across multiple microservices to ensure data consistency. It breaks a global transaction into a series of local transactions, where each step has a corresponding compensating transaction to roll back changes if a failure occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'012cb295-5806-4c67-8171-87e9c86c610d', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the significance of ''ngOnChanges'' in component lifecycle?', N'Middle', N'ngOnChanges is triggered whenever an input property of a component changes. It receives a SimpleChanges object that contains the current and previous values, allowing for logic that depends on specific input updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db9e6cdc-8eaf-4458-be70-87ea78d74dd6', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Migrations in Laravel?', N'Intern', N'Migrations are essentially version control for your database schema. They allow you to define your database structure using PHP code, making it easy to share and synchronize table changes across different development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7cc166b-e4c8-41a7-bab4-87ecccf77b51', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to choosing a cloud provider for a large-scale system?', N'Senior', N'I evaluate cloud providers based on their managed service offerings, ecosystem maturity, and cost structure relative to our specific workload requirements. I also strongly consider multi-cloud or cloud-agnostic architectures if vendor lock-in poses a significant business or regulatory risk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78ab69db-7bcb-4c60-832e-87ed7778bfa9', N'954a0331-deff-4399-b588-96f39fec001d', N'What is select ICU expression?', N'Intern', N'ICU expression is is similar to the plural expressions except that you choose among alternative translations based on a string value instead of a number. Here you define those string values. Let''s take component binding with residenceStatus property which has "citizen", "permanent resident" and "foreigner" possible values and the message maps those values to the appropriate translations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11f7fab2-2694-48a0-8b93-87ee8f11528d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary difference between SvelteKit''s ''load'' functions running on the server versus the client?', N'Middle', N'When a load function runs on the server, it has direct access to database drivers and private environment variables, making it ideal for secure data fetching. When running on the client during navigation, it executes in the browser, which reduces server load but requires exposed APIs to fetch the same data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49980dfb-5535-4129-bdfd-87eefdaebcef', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the performance implications of using complex CSS filters and box-shadows on high-frequency animations?', N'Senior', N'Complex CSS filters and shadows require expensive per-frame pixel calculations during the paint phase, which can drop the framerate below 60fps. These properties are not typically handled by the compositor thread, unlike transforms and opacity, leading to main-thread congestion if applied to elements that are moving.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bce7245b-172e-4290-b165-87ef874128db', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does a database handle the ''split-brain'' scenario during a network partition?', N'Senior', N'Split-brain occurs when the network partitions, causing multiple nodes to believe they are the primary. This is typically mitigated using consensus algorithms like Paxos or Raft, or by using a quorum-based approach where a majority of nodes must agree to perform an operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8759c4d0-284c-4250-8cde-87efabb22683', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle form data compared to JSON data?', N'Junior', N'JSON data is handled by declaring Pydantic models as parameters, while form data is handled by using the ''Form'' class. This allows the framework to parse ''application/x-www-form-urlencoded'' data instead of the default JSON body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fe659d0-5205-4fb3-979b-87f15b651d88', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does a broker determine which consumer should receive the next message in a round-robin distribution?', N'Senior', N'The broker maintains a pointer or index for each consumer in the group to track distribution state. It cycles through available consumers, ensuring a relatively even distribution of load, though this approach does not account for the varying processing speeds of individual consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5121bfe3-7c8d-4bdf-b749-87f1f61c9ac8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of an index in MySQL?', N'Intern', N'An index is a data structure that improves the speed of data retrieval operations on a table. It works similarly to an index in the back of a book, allowing the database to find rows without scanning every single record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fea4d9ed-2b61-4982-b188-87f24a071809', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the difference between hydration and serialization in the context of Qwik?', N'Intern', N'Hydration is the traditional process where a framework downloads, parses, and executes all JavaScript on the client to attach event listeners to static HTML. Serialization in Qwik avoids this by embedding the necessary state and event data directly into the HTML during server-side rendering. This means the application is ready for interaction immediately without needing to perform the expensive hydration phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20668562-6ca2-46d0-b364-87f625fffc07', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''Any'' and ''AnyObject'' types?', N'Fresher', N'Any can represent an instance of any type at all, including function types. AnyObject can represent an instance of any class type only, which is useful when working with APIs that rely on reference types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58f0a825-9e37-414f-8b3a-87f662d17222', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a reference variable in C++?', N'Intern', N'A reference is an alias for an existing variable, meaning it provides an alternative name for the same memory location. Once a reference is initialized to a variable, it cannot be changed to refer to another variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ec3bbc8-f5c1-4d2f-b5e0-87f6ebf9bfec', N'954a0331-deff-4399-b588-96f39fec001d', N'What is platform in Angular?', N'Intern', N'A platform is the context in which an Angular application runs. The most common platform for Angular applications is a web browser, but it can also be an operating system for a mobile device, or a web server. The runtime-platform is provided by the @angular/platform-* packages and these packages allow applications that make use of @angular/core and @angular/common to execute in different environments. i.e, Angular can be used as platform-independent framework in different environments, For example, 1. While running in the browser, it uses platform-browser package. 2. When SSR(server-side rendering ) is used, it uses platform-server package for providing web server implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b979edeb-9d48-4db2-b92b-87f75ab5868f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS differ from React in terms of how it updates the DOM?', N'Junior', N'Unlike React, which uses a Virtual DOM and re-renders component functions entirely, SolidJS uses fine-grained reactivity to update only the specific parts of the DOM that depend on a changing value. This means components in SolidJS run only once during initialization rather than every time state changes. As a result, SolidJS avoids the overhead of reconciliation and diffing processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0dc5623-4073-4ca5-a472-87f83594c330', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why use Redux instead of React''s built-in state management?', N'Intern', N'Redux provides a more structured and predictable architecture for large-scale applications. It offers powerful debugging tools and makes state management easier to test and maintain across complex component trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f283e671-379a-4a1a-8a98-87fb496b8300', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the trade-offs of using Litestar''s automatic OpenAPI schema generation for complex domain models?', N'Senior', N'Automatic generation significantly reduces documentation maintenance overhead and ensures sync between code and spec. However, it can leak internal implementation details if not properly managed, and it may require manual overrides via custom DTOs or schema modifiers to represent complex polymorphism or legacy data structures accurately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cda08bb-52bc-4089-a329-87fc299fb655', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a route handler in Express?', N'Intern', N'A route handler is a function that executes when a client makes a request to a specific URL path and HTTP method. It performs the necessary logic for that route and sends the final response back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9edf1b4-85a0-4fd4-b659-87fd2a16b081', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How do you handle ''Graceful Shutdown'' in ASP.NET Core to ensure active requests are completed?', N'Senior', N'Graceful shutdown is handled by the host, which triggers a cancellation token to stop accepting new requests while allowing existing requests a defined timeout period to complete. Applications should listen for this signal to perform cleanup tasks, such as closing database connections or flushing logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'135ea88e-62c0-44f1-b161-87fd84c25d44', N'4c000000-0000-0000-0000-000000000005', N'What are the advantages of using a distributed cache like Redis?', N'Middle', N'A distributed cache allows multiple application nodes to share the same cache state, ensuring consistency across the cluster. It also provides high performance and persistence features that local, in-memory caches lack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f9b2cce-9565-4c1f-a257-87fdc3edc975', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the ''Data Mapper'' pattern used by Doctrine ORM in Symfony?', N'Middle', N'The Data Mapper pattern decouples the domain entities from the database schema by using a mapper layer to move data between them. This allows entities to remain clean of persistence concerns, facilitating better domain-driven design and easier testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b334b31-7f61-46ef-ba72-87fff43084e6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is type erasure in Swift, and when is it necessary?', N'Middle', N'Type erasure is a pattern used to hide the underlying concrete type of a generic or protocol-constrained object, often by wrapping it in a non-generic container. It is necessary when you need to store different implementations of a generic protocol in a collection where the specific type cannot be known at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'824e529d-417f-462f-801c-88038588aa07', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the difference between Tailwind CSS and SASS/SCSS?', N'Fresher', N'SASS is a CSS preprocessor that adds features like nesting and variables to standard CSS. Tailwind CSS is a framework built on top of CSS that provides a predefined set of utility classes to speed up styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
