INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a9d6f1c-d668-43dd-850a-8806dc26d71b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is eventual consistency and why is it used in NoSQL databases?', N'Middle', N'Eventual consistency is a model where data updates are propagated to all nodes over time, ensuring that all accesses will eventually return the last updated value. It is used to achieve high availability and low latency by allowing reads to occur before all replicas are synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
