INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40dc5669-c610-47d9-899b-8813413ff182', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is meant by the term ''Database Integrity''?', N'Junior', N'Database integrity refers to the accuracy and consistency of data stored in a database. It is maintained through constraints, triggers, and proper design, ensuring that data remains reliable throughout its lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96442a0f-2d13-4785-bb10-8815a6943b06', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a Database Index and a Unique Constraint?', N'Middle', N'A database index is primarily a data structure that improves the speed of data retrieval operations, while a unique constraint ensures that all values in a column are distinct. While a unique constraint implicitly creates an index for performance and enforcement, a standard index does not guarantee value uniqueness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
