INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37823496-5153-4e95-9ee2-88177fb131e4', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is ''Database Replication Lag'' and how can it affect application architecture?', N'Senior', N'Replication lag is the delay between a write on a primary node and its visibility on a replica. It necessitates ''read-your-writes'' consistency strategies at the application level, such as routing primary-key reads to the primary node or using session-based routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a27d668-9fc6-41fd-9a44-881a051d0fa8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary benefit of using MVCC over strict locking?', N'Middle', N'MVCC significantly improves concurrency by allowing read operations to proceed without being blocked by write operations. It reduces lock contention, leading to better throughput in systems where reads are much more frequent than writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c910574d-5dfc-4bfc-9297-881a391a5dd7', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the function of a ''cache-aside'' load-on-demand pattern?', N'Middle', N'In this pattern, the application checks the cache; if the data is missing, it fetches the data from the database and updates the cache for future requests. This ensures that the cache only contains data that is actually being requested by users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
