INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c00855bb-c142-4c1d-afa2-881ded99158d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of pattern matching in Rust?', N'Intern', N'Pattern matching is a control flow construct that compares a value against a series of patterns and then executes code based on which pattern matches. It is a powerful tool for handling complex data structures like enums and ensures that all possible cases are covered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80b0e3db-46d4-4a2f-bd16-882078d2c500', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does the ''OPCache preloading'' feature change in terms of application deployment and startup?', N'Senior', N'Preloading allows specific scripts to be loaded into memory at server startup and remain permanently available, bypassing the need for inclusion and compilation checks during every request. This improves performance for large frameworks, but it also means that code changes to preloaded files require a full server restart to take effect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2da1b4f-29af-4a71-acfa-88225a03be17', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Controller in the Symfony framework?', N'Intern', N'A controller is a PHP function or method that receives an HTTP request and returns an HTTP response. It acts as the central logic handler that orchestrates the interaction between the model and the view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64d18290-2be2-4148-b50f-8827da20cdca', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .val() and .text()?', N'Fresher', N'.val() is primarily used to get or set the values of form elements like inputs, selects, and textareas. .text() is used to get or set the text content of general HTML elements like paragraphs or divs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'766f2f1a-6557-4899-bd07-8827df9dc526', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Describe the difference between ''Dispatchers.Default'' and ''Dispatchers.IO'' in coroutine scheduling.', N'Senior', N'Dispatchers.Default uses a shared thread pool sized to the number of CPU cores, making it optimal for CPU-intensive computations. Dispatchers.IO is designed for blocking I/O operations and uses an elastic thread pool that can scale up to handle many concurrent blocking tasks, preventing the CPU-bound pool from being saturated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3ffead1-ecfb-4909-8d7d-882b8cb3e8f0', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do you handle errors globally in a Fastify application?', N'Junior', N'You can define a global error handler using the ''setErrorHandler'' method on the Fastify instance. This function intercepts any errors thrown during the request lifecycle, allowing you to send a consistent error response to the client and log the incident appropriately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1adc8a57-47f7-4f8f-a99a-882ebabf795c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why does Python treat functions as first-class objects?', N'Senior', N'Functions are treated as first-class objects to support functional programming paradigms, where functions can be passed as arguments, returned from other functions, and stored in data structures. This capability enables powerful patterns such as callbacks, closures, and dynamic function generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39ff658d-9111-4341-a99f-8830a8ed86d3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''Engine'' concept in Ember?', N'Middle', N'Engines are a way to modularize large applications into smaller, independent units that can have their own routes, templates, and services. They help in managing complexity, allowing teams to develop and test parts of a massive application in isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
