INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'473e85b5-f91c-4a88-8485-8833d1006da8', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''onReady'' lifecycle event?', N'Intern', N'The onReady event is triggered when all plugins have been registered and the server is initialized. It is the appropriate place to perform final setup tasks before the server starts accepting traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e84c1570-fac4-47ea-b426-88355a9cd8ed', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is an asynchronous function in Dart and why is it used?', N'Junior', N'An asynchronous function allows the program to perform long-running tasks, such as fetching data from an API, without blocking the main execution thread. It uses the Future object to represent a value that will be available at some point in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bea51ef0-4cfe-48bf-8ec3-883566489809', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the architectural implications of the Node.js event loop regarding CPU-bound tasks.', N'Senior', N'Since Node.js runs on a single thread, CPU-bound tasks block the event loop, preventing the processing of I/O callbacks. This leads to latency spikes and degraded throughput for all concurrent requests. To handle such tasks, developers must offload them to a worker pool or microservices to maintain event loop responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42886a6c-dd25-46dd-bca0-88379105b422', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of dependency pre-bundling in Vite?', N'Middle', N'Pre-bundling converts CommonJS or UMD dependencies into ESM format for the browser and collapses many small files into a single module. This prevents the browser from being overwhelmed by hundreds of network requests for nested dependency files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db9aea3d-b69a-45fb-82ea-8838f42b03cc', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of a ''Dataloader'' in a GraphQL-Node.js setup?', N'Middle', N'Dataloader is used to solve the N+1 query problem by batching multiple individual requests into a single database query. It also provides request-level caching, which prevents the application from fetching the same data multiple times during a single request execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'976c02ce-2c22-4203-b57f-883945ee013c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the drawbacks of choosing a NoSQL database?', N'Junior', N'The main drawbacks include the lack of standardized query languages, limited support for complex cross-document joins, and the potential for data inconsistency due to the distributed nature of the systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c974519-5645-40c4-a174-883c807d9d50', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with a memory leak in a managed runtime service, what is your systematic strategy for identification?', N'Senior', N'I would start by capturing heap dumps at two distinct time intervals and performing a differential analysis to identify objects that are growing in count or size. I would then correlate these findings with specific traffic patterns or long-lived background tasks to identify which service components are failing to trigger garbage collection or are inadvertently holding onto object references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
