INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fe11b19-7d24-4b95-8a68-8845257186d6', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a namespace and why is it used?', N'Junior', N'A namespace is a declarative region that provides a scope for identifiers such as classes, functions, and variables. It is primarily used to prevent name collisions when multiple libraries define entities with the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6d6fa4c-938c-4a61-9235-88464aa12b49', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s Event and Listener system facilitate the decoupling of core business logic from side effects?', N'Senior', N'Events allow you to trigger side effects—such as sending emails or updating caches—without hardcoding those actions into the main business logic. By dispatching events, the primary service remains unaware of these downstream consumers, allowing you to add or remove features without modifying the critical execution path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aa1c2b3-8f8f-4570-8795-884d1292b89f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the function of the ''onCleanup'' hook?', N'Middle', N'The onCleanup hook allows developers to register a callback that runs when a reactive scope, such as an effect or a component, is disposed. This is essential for preventing memory leaks by clearing timers, removing event listeners, or canceling network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
