INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93ff5a97-f1f9-4a6c-bb78-88561505b352', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage information overload when researching a new topic?', N'Intern', N'I filter information by focusing on high-quality, official documentation first rather than secondary sources. I take notes to synthesize the information, prioritizing concepts that are directly relevant to the current problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8008b89-def3-4fde-b587-885b5803e764', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What does it mean for an Axum handler to be ''composable''?', N'Intern', N'Composability means that you can easily combine small, independent pieces of logic or routers into a larger application. Axum allows you to nest routers and apply middleware to specific sub-routes, making the code easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7dd03e6-71cf-4d15-afaf-885c3e688fa7', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does the ''search path'' influence package loading in R?', N'Middle', N'The search path is an ordered list of environments that R checks when looking for an object or function. When a package is loaded, it is typically inserted at the second position in the search path, which can cause naming conflicts if two packages export functions with the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83bbe147-3c42-45d6-8afe-885c435aee3c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Purge'' thread contribute to system health?', N'Senior', N'The Purge thread asynchronously removes rows from the undo logs that are no longer needed by any active transactions. If the purge thread falls behind, the system experiences ''undo log bloat,'' which increases storage usage and slows down long-running read queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a946ac5c-7f42-4605-b18a-885d5939709b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Discuss the impact of using singleton classes (eigenclasses) on object memory and method dispatch performance.', N'Senior', N'Every object in Ruby can have a singleton class, which acts as a hidden class inserted into the inheritance chain to hold object-specific methods. While this enables the meta-programming paradigm, it consumes additional memory and complicates the method cache, as each unique singleton class forces the VM to invalidate parts of its inline method cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc50e14-a742-473c-a7ee-88665b1cbe6c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you decide between using a relational database and a NoSQL database for a new feature?', N'Middle', N'I evaluate the data structure and consistency requirements. If the data has strict schema requirements and complex relationship queries, a relational database is preferred for ACID compliance, whereas NoSQL is better suited for unstructured data that requires horizontal scalability and high write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77cb1b88-83ca-43a3-a783-8867156aac10', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why would you use the x-cloak directive?', N'Junior', N'The x-cloak directive is used to prevent the ''flash of unstyled content'' that can occur before Alpine.js finishes loading. By applying a CSS rule that sets elements with this attribute to display: none, you ensure they remain hidden until Alpine is ready to process them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df67cceb-f2a8-49e2-ba53-88678e7f628e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of method overloading.', N'Junior', N'Method overloading occurs when multiple methods in the same class share the same name but have different parameter lists. The compiler distinguishes between them based on the number, type, or order of the arguments provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7ad5623-8f9d-40f9-a187-886c97f0784b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between an embedded server and a traditional application server?', N'Intern', N'An embedded server is packaged directly into the application''s executable file, meaning the application runs as a standalone process. A traditional application server requires a separate, pre-installed container to host and run the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21b736e0-0688-450e-b44e-88710597c936', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you handle database sessions in FastAPI?', N'Junior', N'Database sessions are typically managed using a dependency that creates a new session for each request and ensures it is closed after the response is returned. This prevents connection leaks and ensures that each request has its own isolated database transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9297aa5-3b68-4d42-bf82-88726d057610', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a distributed system, how do you approach the trade-off between consistency and availability under partition?', N'Senior', N'I analyze the business impact of stale data versus downtime. If the system requires strict linearizability for financial transactions, I prioritize consistency using consensus protocols; for social feeds or analytical dashboards, I favor availability and eventual consistency to ensure system resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f930d9b1-20ca-4fc7-8b5c-8872e0531442', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin support HTTP status codes?', N'Fresher', N'Gin provides helper methods on the context object to explicitly set the HTTP status code for a response. This ensures that the client receives the correct status information, such as 200 for success or 404 for not found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55cd644b-0859-4364-8d55-887553f8af66', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''notFound.js'' file in Next.js?', N'Middle', N'The ''notFound'' file is a specialized file that renders a custom UI when a 404 error occurs within a specific route segment. It allows developers to provide consistent, branded error handling while keeping the rest of the application layout intact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd054cbbd-7dd2-4a92-b0a9-88756c626133', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What architectural trade-offs are involved when migrating from a monolith to microservices?', N'Senior', N'The primary trade-off is moving from in-process communication to network-based communication, which introduces complexity in failure handling and data consistency. While microservices offer independent scalability and deployment, they require significant investment in DevOps, service discovery, and observability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69ca88b5-5ab8-4195-9241-8876345897b8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the ''Sendable'' protocol enforce concurrency safety in Swift 5.5 and later?', N'Senior', N'The Sendable protocol marks types that can be safely passed across concurrency boundaries without data races. The compiler statically enforces that only immutable types or thread-safe classes can conform to this protocol, ensuring that shared state is not accidentally mutated concurrently between different tasks or actors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'488fcd8d-5889-486f-947d-88786c6fb0a8', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What trade-offs should be considered when using Echo''s default JSON binding?', N'Middle', N'Echo''s default binding is highly convenient but can be less performant than manual decoding for extremely high-throughput systems. It relies on reflection, so developers should evaluate if custom unmarshalers or specialized libraries are needed for performance-critical endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e93743e-6ad7-4ce1-addb-8879cffa24d1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the significance of the ''attr_accessor'' method?', N'Middle', N'It is a macro that automatically generates both getter and setter methods for an instance variable. By abstracting these boilerplate methods, it encourages encapsulation while maintaining a clean, readable interface for accessing state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c871410-8bac-4853-bebb-887c6bfd0f4c', N'954a0331-deff-4399-b588-96f39fec001d', N'What are template expressions and template statements?', N'Intern', N'In Angular templates, you use two main types of syntax to interact with your component''s data and logic: template expressions and template statements. - Template expressions are used for data binding. They evaluate to a value and are typically used to display data ({{ user.name }}) or bind properties ([src]="imageUrl"). They are read-only and cannot change the state of the application directly (e.g., no assignments like x = 1). - Template statements are used for event binding. They execute code in response to an event ((click)="saveData()"). They can call component methods or perform simple assignments. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83dd94b5-ae9d-48b9-8e4f-887f56e7271a', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How are computed properties used in Ember?', N'Junior', N'Computed properties allow you to define a property whose value is derived from other properties. They are automatically updated whenever the underlying dependent properties change, which is useful for formatting data or performing complex calculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a467591-483e-4874-8cd6-8880f387b494', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain how the JVM handles ''deoptimization'' when speculative optimizations fail.', N'Senior', N'The JIT compiler makes speculative assumptions, such as predicting that a particular class hierarchy will not change. If these assumptions are invalidated, such as by a dynamic class load, the JVM performs a deoptimization, discarding the highly optimized machine code and reverting to interpreted mode or re-triggering compilation to ensure correctness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d9ac746-0739-4694-8f13-8881927b69c7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''delegate'' keyword and how is it related to events?', N'Middle', N'A delegate is a type-safe function pointer that holds a reference to a method. Events are wrappers around delegates that provide a subscription mechanism, allowing a class to notify other components when something happens while restricting direct access to the delegate itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8c46aea-092d-4457-ae08-8881a60287d5', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of an error handler in Fiber?', N'Intern', N'An error handler is a specific function that catches errors thrown during the request cycle. It allows the developer to customize the response sent to the client when something goes wrong, rather than returning a default server error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e14d9758-6c06-4269-8a85-88842adc0e7c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you ensure proper error handling across asynchronous microservices in a NestJS architecture?', N'Senior', N'Implement a centralized Exception Filter that can catch and serialize errors into a standardized response format. In distributed environments, you must also utilize distributed tracing and correlation IDs to track errors across service boundaries, ensuring that failed operations can be correlated with the originating request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'232f9c3e-ab30-4089-b427-888799ec7613', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage the ''this'' context inside directives?', N'Middle', N'Alpine.js sets the context of ''this'' to the component''s data object within directives, allowing easy access to variables and methods defined in x-data. This creates a clean and intuitive scope where the HTML markup has direct access to the component''s internal logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3510c4a3-0e03-4fa5-8a14-8887e1ef05ae', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How do you define components in Preact?', N'Junior', N'Components can be defined as functional components or ES6 classes, just like in React. They are essentially functions or classes that return JSX representing the UI structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e996f9-98d3-4604-8a92-8888a0c81977', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte stores and why are they used?', N'Junior', N'Stores are objects that hold state that needs to be accessed by multiple components throughout an application. They provide a simple way to share data outside of the standard parent-child component hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'430141e4-49f1-4a4e-a961-888a57c35190', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'When should you prefer using Form Requests over Controllers for validation?', N'Senior', N'Form Requests adhere to the Single Responsibility Principle by encapsulating validation and authorization logic away from the controller. This keeps controllers lean and ensures that validation occurs before the controller method is even invoked, improving security and code maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c496f6f0-ce42-4070-abb9-888b9a29c771', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the benefit of using x-transition for UI animations?', N'Middle', N'The x-transition directive provides a declarative way to handle element entry and exit transitions by managing CSS classes during the lifecycle of an element. This abstracts the complexity of timing and class toggling, making it easier to implement smooth UI interactions without managing state manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc7e13c7-5530-4dc7-bb6f-888d10db67fd', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are Go Modules?', N'Intern', N'Go Modules are the standard way to manage dependencies in Go. They allow developers to define specific versions of external libraries used in a project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da1b26b7-5977-4969-9198-8892b343ff4a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between {} vs new Object()?', N'Fresher', N'1. Object Literal Syntax ({}): Object literal syntax is a shorthand way of creating an object. We can create an object by placing a comma-separated list of key-value pairs inside curly braces { }. The key represents a property name of the object and the value represents the value of that property. Syntax: Example: 2. Object Constructor Syntax (new Object()): The object constructor syntax is a way of creating an object using the new operator and the Object constructor function. We can create an empty object by calling the Object constructor without any arguments. We can also create an object by passing an object literal as an argument to the Object constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d51670b-ab34-4fb5-b5f8-8893f67be7c1', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is meant by ''immutability'' in Elixir and how does it affect Phoenix?', N'Fresher', N'Immutability means that data cannot be changed after it is created. This makes Phoenix applications easier to reason about and debug, as there is no hidden state that can be unexpectedly modified by other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd707ce7-e65c-48ce-8067-889829dfa071', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering API versioning, what are the trade-offs between URL versioning and header-based versioning?', N'Middle', N'URL versioning is explicit and easy to cache or bookmark, making it very developer-friendly, but it can lead to cluttered resource paths. Header-based versioning keeps URLs clean and represents the resource accurately, but it makes testing in browsers and caching more complex due to the hidden versioning metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3368386-c49e-4ebd-aeaa-889bb97e59d2', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the performance impact of using ''sequences'' versus ''collections'' in Kotlin.', N'Middle', N'Collections are processed eagerly, creating intermediate results for every step in a chain, which can be memory-intensive. Sequences use lazy evaluation, processing elements one by one through the entire chain, which is more efficient for large datasets or long transformation pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b0a692c-d66a-43d8-b95d-889bf25cf586', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the ''select'' statement function in Go concurrency?', N'Middle', N'The select statement allows a goroutine to wait on multiple channel operations simultaneously. It blocks until one of the cases can proceed, at which point it executes that case; if multiple are ready, it chooses one pseudo-randomly, providing a powerful way to multiplex concurrent events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23c71e1b-1d6b-44e2-a403-889c661dcd0a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do Go channels function as a synchronization primitive under the hood?', N'Senior', N'Channels are essentially thread-safe queues protected by a mutex, managing a circular buffer for data and wait queues for blocked goroutines. They provide a high-level abstraction for communication, but they incur locking overhead that can be a bottleneck compared to atomic operations in high-throughput scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd72c44e-62e4-4f32-a03d-889cdd497b5e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the difference between the data segment and the BSS segment in a C program.', N'Senior', N'The data segment contains initialized global and static variables, which occupy space in the object file. The BSS segment contains uninitialized global and static variables, which are stored only as a size requirement in the object file, reducing the final binary''s disk footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'286348ce-5f5a-4e36-a3d7-889eb35a0cef', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of the ''Catchers'' feature in Rocket?', N'Junior', N'Catchers are dedicated handlers designed to manage errors, such as 404 Not Found or 500 Internal Server Error. They allow you to define custom logic or return specific templates when an error occurs during request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2672ba1-8f7d-443a-932b-889f667e9192', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the trade-offs of using Node.js Cluster module versus container orchestration for horizontal scaling?', N'Senior', N'The Cluster module shares the same memory space for some resources but is limited to a single machine, creating a single point of failure. Container orchestration provides better fault tolerance, independent resource allocation per instance, and easier deployment cycles, though it adds infrastructure complexity compared to simple process forking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e1532ca-9f7c-4691-b46f-88a14e53acfa', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a pointer and how is it used in Go?', N'Junior', N'A pointer holds the memory address of a value. Using pointers allows functions to modify the original variable rather than working on a copy, which can improve performance for large data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'531de57c-462d-414a-84e3-88a1b964cac2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle complex state synchronization between multiple Lit components?', N'Senior', N'For complex state, one should move the state into a centralized store or a singleton ReactiveController. Components then subscribe to this state, ensuring a single source of truth and preventing synchronization issues common with fragmented, local-only state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccab7e5e-c1a1-47f1-88bb-88a1f6286e06', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle event listeners compared to standard HTML?', N'Junior', N'Preact uses synthetic event handling, which normalizes events across different browsers. You attach events using camelCase attributes like ''onClick'' instead of standard HTML ''onclick'', and the event object passed to the handler is a cross-browser compatible wrapper.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
