INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89fa8e68-e1c2-488e-bb36-88a55e3c05aa', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle exception handling globally?', N'Middle', N'Micronaut uses ''ExceptionHandlers'' to decouple error handling logic from business logic. By implementing a specific handler for a given exception type, you can catch errors globally across the application and return appropriate HTTP responses without cluttering controllers with try-catch blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
