INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c55b462-79dd-4451-9766-88ae45abede6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Discuss the performance implications of deep conditional type nesting in large TypeScript projects.', N'Senior', N'Deeply nested conditional types significantly increase the computational overhead of the TypeScript compiler during type resolution. This can lead to slower build times and unresponsive IDE performance, as the compiler must evaluate many potential paths for every type reference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d32ee9-8641-4425-b82b-88afd06c6c31', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a problem that requires a trade-off between speed and quality?', N'Fresher', N'I would first clarify the project''s goals with stakeholders to see if speed or quality is the priority. If speed is essential, I might propose a ''Minimum Viable'' approach that fulfills core needs while noting that technical debt may need to be addressed later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9979c1f-674a-4c4e-8e56-88b0979baedf', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the concept of ''technical debt'' to a manager?', N'Fresher', N'Technical debt is the extra work we create for ourselves by choosing a quick, temporary solution instead of a more robust, long-term one. Just like financial debt, it needs to be paid off eventually through refactoring, otherwise, it slows down future development and makes the system harder to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63dfa4c8-cc63-45e3-b5e3-88b0e7d3a48f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the significance of the ''quorum'' (R+W > N) formula in distributed systems?', N'Senior', N'This formula ensures that at least one node in a read operation will have the most recent data if the sum of read nodes and write nodes exceeds the total number of replicas. It provides a tunable mechanism to achieve strong consistency by ensuring that read sets and write sets always overlap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f525599-3804-4498-afc8-88b1a4163273', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the concept of ''Split Brain'' in Elasticsearch and how modern versions prevent it.', N'Senior', N'Split brain occurs when network partitions cause two nodes to believe they are the master simultaneously, leading to data inconsistency. Modern versions prevent this using an ensemble-based quorum voting system that requires a majority of master-eligible nodes to agree on a leader.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
