INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0fdb245-41aa-4075-b7a0-88b515985c8f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why would you choose Ember Data over manual fetch requests?', N'Middle', N'Ember Data provides a powerful abstraction layer for managing application state, including normalized caching, relationship tracking, and identity mapping. It reduces boilerplate code by standardizing how data is fetched, transformed, and persisted to an API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe6e4d3f-58f2-4228-80b9-88b562f4edb3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the role of the Python Method Resolution Order (MRO).', N'Middle', N'MRO determines the order in which base classes are searched when executing a method in a class hierarchy. Python uses the C3 Linearization algorithm to ensure a consistent, monotonic order that respects both local precedence and the order of inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c49bdafa-a759-437f-b5e9-88b96c8c70f8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between strict type checking and dynamic typing?', N'Fresher', N'Strict type checking catches errors during compilation, leading to more robust systems, but it requires more verbose code and slower development cycles. Dynamic typing allows for rapid prototyping and flexibility, but it shifts the burden of catching type-related errors to runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca2533c9-2f87-4a73-b652-88be9543b854', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why would you choose ''std::vector'' over ''std::list'' for most general-purpose collections?', N'Middle', N'std::vector provides contiguous memory storage, which is highly cache-friendly and allows for efficient random access. std::list uses nodes scattered in memory, which leads to poor cache locality and higher memory overhead per element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bc97594-5fb8-40d4-b6ba-88bf2d9cb54a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is SolidJS considered efficient?', N'Fresher', N'SolidJS is efficient because it avoids the overhead of a Virtual DOM and component re-renders. By updating the DOM directly through fine-grained reactivity, it minimizes unnecessary work and provides faster UI updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcab6137-1ff2-472e-868c-88c080025698', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you handle global error boundaries in a Nuxt 3 application?', N'Middle', N'You can use the ''vue:error'' hook or define a custom error page in the root directory to catch unhandled errors. Additionally, using the ''NuxtErrorBoundary'' component allows you to wrap specific parts of the UI to recover gracefully from runtime errors without crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'263e2590-b3ab-4999-9575-88c0db393bc9', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is Next.js considered a ''full-stack'' framework?', N'Intern', N'Next.js is considered full-stack because it allows developers to write both the frontend UI and the backend API logic within a single project. This simplifies the development process by keeping everything in one codebase and sharing data logic easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c5a5558-80e9-4609-bcb6-88c2749a8c83', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the Angular Router?', N'Junior', N'The Angular Router enables navigation from one view to the next as users perform application tasks. It maps browser URLs to specific components, allowing the application to behave like a multi-page app while remaining a single-page application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe26ee65-5c0c-4e1b-b901-88c351386f19', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle prop spreading?', N'Middle', N'Preact handles prop spreading just like React, passing object properties as individual attributes. It is optimized to perform this operation quickly without unnecessary object cloning, ensuring that even large prop objects do not create significant performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd103b4b-8aec-4aef-9030-88c485e84021', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra maintain availability during a network partition?', N'Senior', N'Cassandra is an AP system in the CAP theorem, meaning it prioritizes availability over consistency by allowing writes and reads to proceed on available replicas. It uses hinted handoffs and anti-entropy repairs to reconcile data discrepancies once the partition is resolved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df4e3415-aab2-4a45-a3fd-88c4ef1a48d7', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the risks of using Tailwind in a project with a high frequency of dynamic class generation?', N'Senior', N'If class names are constructed dynamically using string concatenation, Tailwind’s static analysis tool will fail to detect them. This results in missing styles in production, requiring developers to either use full class strings or configure a whitelist for dynamically generated classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83058893-16e8-43fa-ae3f-88c593ebeb86', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a keyword field in Elasticsearch?', N'Fresher', N'A keyword field is used for exact matches, sorting, and aggregations. The content is not analyzed, so it is treated as a single, immutable unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a1d83a5-4e6c-41bd-a9e6-88c83192bda7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s memory layout for structs differ from classes in terms of heap allocation?', N'Senior', N'Structs are typically allocated on the stack or inline within their parent objects, avoiding heap allocation and reference counting overhead. Classes are always allocated on the heap, requiring metadata and reference count management, which introduces cache locality concerns and potential memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b3e50ad-5372-4082-a724-88c9dbdeed6f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the role of the ''GOMAXPROCS'' environment variable?', N'Middle', N'GOMAXPROCS defines the maximum number of OS threads that can execute user-level Go code simultaneously. Setting this value correctly allows the Go runtime to effectively utilize multi-core architectures without causing excessive context switching overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
