INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc82dac2-746c-4517-9810-88d5d5d23a1c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra''s LSM-tree storage engine architecture impact write and read performance compared to B-trees?', N'Senior', N'LSM-trees turn random writes into sequential I/O by appending to commit logs and memtables, which are then flushed to immutable SSTables. This provides significantly higher write throughput than B-trees, though it introduces read amplification as the system must merge data from multiple SSTables during query execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
