INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'752cc075-038a-4899-8600-88dedce43420', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is meant by platform independence in Java?', N'Intern', N'Platform independence means that Java programs can run on any operating system without being recompiled. This is achieved by compiling source code into bytecode, which is then executed by the Java Virtual Machine installed on the target machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
