INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60eada30-15f6-465f-80dc-88dfa35cbded', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the deinit method?', N'Intern', N'The deinit method is called automatically just before a class instance is deallocated from memory. It is primarily used to perform any necessary cleanup tasks, such as closing file handles or invalidating timers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'621f7746-b849-41a9-8e44-88e1009ef4b2', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What does the cascading portion of CSS mean?', N'Intern', N'The cascading in CSS refers to the fact that styling rules "cascade" down from several sources. This means that CSS has an inherent hierarchy and styles of a higher precedence will overwrite rules of a lower precedence. Even the simplest HTML document may have three or more style sheets associated with it including: * The browser''s style sheet * The user''s style sheet * The author''s style sheet 1. Browser style sheets: Browsers apply style sheets to all web documents. Although these style sheets vary from browser to browser, they all have common characteristics such as black text, blue links, purple visited links etc. These are referred to as a "default" browser stylesheet. As soon as you, the author, apply a style sheet to a document, it will override the browser''s style sheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5d5b141-91cb-4609-a96a-88e1564cf2b2', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the benefits of using a stateless architecture?', N'Middle', N'Stateless services do not store client session data, allowing any instance to handle any request. This simplifies horizontal scaling, improves fault tolerance, and makes it easier to manage load balancing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fffc5245-2f02-4da5-ba4f-88e788fa373b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can you get the list of keys of any object', N'Fresher', N'You can use the Object.keys() method which is used to return an array of a given object''s own property names, in the same order as we get with a normal loop. For example, you can get the keys of a user object,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'811cba7a-cd19-40c1-9194-88e79e1e1f68', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the role of the Service Provider in AdonisJS and how it facilitates loose coupling.', N'Senior', N'Service Providers act as the primary bootstrapper for the application, allowing developers to register services into the IoC container. By decoupling the definition of a service from its consumption, providers enable easier testing and swapping of implementations without modifying consumer logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79491a89-e9ff-43d2-9f8f-88e8411b8851', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How can you make a property optional in an interface?', N'Middle', N'You can use the ''?'' modifier after the property name to mark it as optional. This tells the compiler that the property may be omitted, and the type effectively becomes ''T | undefined''. It is useful for configuration objects or partial data updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16200dbb-9a94-44a5-b345-88eb27c5d05b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the impact of ''Deadlock Detection'' on performance?', N'Senior', N'InnoDB constantly monitors for lock dependencies to kill one of the transactions when a cycle is detected. While this prevents indefinite hangs, high-concurrency workloads with many lock overlaps can spend significant CPU resources simply checking for deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e3c548b-c992-4247-87e7-88ec43e2fcf8', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the concept of ''Nitro'' in the context of the Nuxt architecture.', N'Middle', N'Nitro is the server engine that powers Nuxt, responsible for generating the server build and handling API routes. It is designed to be platform-agnostic, meaning it can deploy the same application to various environments like Vercel, Netlify, or standard Node.js servers with minimal configuration changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd98314a-9468-413c-ba6c-88ec881cb71e', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle asynchronous operations in route handlers?', N'Junior', N'Express route handlers can be marked as async functions, allowing the use of await for asynchronous operations like database queries. If an error occurs within an async handler, it must be caught and passed to the next function to ensure the error-handling middleware is triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec3c4051-a48f-47b6-aa58-88ef2c6f0f3b', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the concept of ''Input Transforms'' in Angular and why they are useful for API consistency.', N'Senior', N'Input transforms allow developers to define functions that intercept and convert incoming property values before they reach the component. This is useful for normalizing data formats, such as converting boolean strings to actual booleans, ensuring the component internal logic remains type-safe and consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5038631-9574-4e56-8fdb-88f014357991', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the string methods that accept Regular expression', N'Intern', N'There are six string methods: search(), replace(), replaceAll(), match(), matchAll(), and split(). The search() method uses an expression to search for a match, and returns the position of the match. The replace() and replaceAll() methods are used to return a modified string where the pattern is replaced. The match() and matchAll() methods are used to return the matches when matching a string against a regular expression. The split() method is used to split a string into an array of substrings, and returns the new array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac277f7a-b8aa-4b09-9413-88f0c27c972e', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the MySQL storage engine?', N'Intern', N'A storage engine is the component of MySQL that handles the SQL operations for different table types. It determines how data is stored, handled, and retrieved, with InnoDB being the most common default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
