INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'544937cd-d38d-4629-8c40-88f5962e6b63', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''Launch'' attribute?', N'Junior', N'The launch attribute marks the main function of the application, signaling to Rocket that this function should initialize and start the web server. It handles the setup of the server instance and blocks until the server is shut down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfeb9be1-3c86-4698-b3f0-88f9016db547', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails routes?', N'Fresher', N'Routes act as a mapping system that directs incoming HTTP requests to the appropriate controller action. They are defined in a configuration file and determine the URL structure of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0769319-1ca6-4289-9bc5-88f941bf0905', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Define ''MTTR'' and explain why it is a critical metric for reliability.', N'Middle', N'MTTR stands for Mean Time To Recovery, representing the average time taken to restore a system to operational status after a failure. It is a critical metric because it measures the effectiveness of your incident response process and the system''s overall maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e801eff9-0565-4f29-a077-88fa926e1bc5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Object.seal() for?', N'Intern', N'Object.seal() is used to prevent new properties from being added to an object and to mark all existing properties as non-configurable. This means you can still modify the values of existing properties, but you cannot delete them or add new ones. Doing so will throw errors in strict mode but fail silently in non-strict mode. In the following examples, you can uncomment the ''use strict'' comment to see this. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b50a28dc-6133-4e6f-8518-88faa1c786e0', N'4c000000-0000-0000-0000-000000000005', N'What is the trade-off between consistency and availability in the CAP theorem?', N'Middle', N'The CAP theorem states that in a distributed system, you can only guarantee two out of three properties: consistency, availability, and partition tolerance. In the event of a network partition, you must choose between returning the most recent write, which might be unavailable, or returning the latest available data, which might be stale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06018734-f0b1-46b4-adb4-88fab2154ad6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you handle errors in Actix actor communication?', N'Junior', N'Errors are handled using the Result type within the message handler. If an actor encounters an issue, it returns an error variant, which is then propagated back to the sender as part of the future''s result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2c31ef0-28d7-463d-9b2c-88fe183cae47', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a constant in C?', N'Intern', N'A constant is a data type whose value cannot be modified during the execution of the program. It is typically defined using the const keyword to ensure data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ecc51b4-a354-4978-995e-890573c6ca6f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the Dart sound null safety model?', N'Intern', N'Sound null safety is a system where the compiler and runtime environment guarantee that non-nullable variables will never be null. This provides high reliability and allows the compiler to optimize the code for better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
