INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'975a313c-913b-4739-961e-89076063482f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an Iterator?', N'Intern', N'An iterator is an object which defines a sequence and a return value upon its termination. It implements the Iterator protocol with a .next() method which returns an object with two properties: * value: The next value in the iteration sequence. * done: This is true if the last value in the sequence has already been consumed. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbe50acc-9cb8-4bea-8c99-8908d220a35a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does database normalization help in ensuring data consistency?', N'Middle', N'Normalization reduces data redundancy by ensuring that each piece of information is stored in only one place. This minimizes the risk of update anomalies, where a piece of information is updated in one location but not another, leading to conflicting data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e31211-5bd6-4cff-bb94-890a74600391', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the primary purpose of the ''private'' members feature in Sass modules?', N'Senior', N'Private members, denoted by a leading underscore in a variable or mixin name, are intended to be used only within the module where they are defined. This enforces encapsulation, allowing developers to hide implementation details from external consumers and prevent accidental dependency on internal logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb481903-6bfa-4020-871c-890aa9142e95', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''Backpressure'' pattern and when should it be implemented?', N'Senior', N'Backpressure is a mechanism where a consumer signals to a producer that it cannot keep up with the incoming rate of data, allowing the producer to slow down or buffer accordingly. It is essential for preventing system collapse due to resource exhaustion when a downstream service becomes a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2dedfb1-43db-4441-92b0-890d8493b96c', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point for all client requests, routing them to appropriate microservices. It centralizes cross-cutting concerns like authentication, rate limiting, logging, and request transformation, reducing the complexity of individual services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'456315c7-6765-4405-a659-8911bffb8230', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript’s ''Control Flow Analysis'' differ from a standard linter’s reachability check?', N'Senior', N'Control flow analysis tracks the state of types as the compiler traverses the code, allowing the type checker to refine the type of a variable based on specific code paths. Unlike a linter, which identifies stylistic or common errors, this analysis is integral to the type system’s core logic for determining validity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a808d5e9-6fc9-4136-8ff8-89122a6493b7', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the ''as-if'' rule in C++ compiler optimization?', N'Senior', N'The as-if rule allows the compiler to perform any transformation on the code as long as the observable behavior of the program remains the same as that defined by the abstract machine. This enables advanced optimizations like dead code elimination, loop unrolling, and expression reordering, provided the resulting execution maintains the required sequential consistency for non-atomic operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd02fb904-560a-4bf5-b1b1-89128583e938', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the benefit of using ''async'' and ''await'' in C# applications?', N'Middle', N'These keywords enable asynchronous programming, which prevents blocking the calling thread during long-running I/O-bound operations. This improves the responsiveness of applications, particularly in UI frameworks or web servers, by allowing threads to be returned to the pool while waiting for external operations to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3f42bdd-38ba-4697-b306-89135e4cb9f6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to remove all line breaks from a string', N'Fresher', N'The easiest approach is using regular expressions to detect and replace newlines in the string. In this case, we use replace function along with string to replace with, which in our case is an empty string. In the above expression, g and m are for global and multiline flags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73f30cfb-29b9-403b-8615-891756d54455', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary benefit of Quarkus regarding startup time?', N'Intern', N'Quarkus performs most of its initialization and dependency injection during the build phase rather than at runtime. This ''build-time boot'' allows applications to start almost instantaneously compared to traditional Java frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e197e2f-f27b-4fb2-824b-891804471936', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle security regarding user-generated content?', N'Middle', N'Alpine.js uses a custom evaluation engine that is designed to be safer than native browser functions like eval(). However, developers must still sanitize any data injected into the DOM, as Alpine directives can execute expressions that might pose risks if untrusted input is allowed to influence the directive logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2436924-c4c5-4692-8204-891b571eb90a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What architectural risks are associated with improper use of ''dynamic'' typing in a large Dart codebase?', N'Senior', N'Using ''dynamic'' disables compile-time type checking, which shifts type errors to runtime and degrades the performance of the optimizing compiler. In large systems, this makes refactoring hazardous, reduces code readability, and obscures the contract between different modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00909401-595a-420f-9250-891f66983271', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''resolve'' property in configuration?', N'Intern', N'The resolve property helps Webpack understand how to find modules when they are imported. It can be used to set up path aliases or specify which file extensions Webpack should automatically look for.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01ab07e9-1b32-4bf2-b949-892039d1b064', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What does ''Peer-to-Peer'' architecture mean in Cassandra?', N'Fresher', N'In a peer-to-peer architecture, all nodes in the cluster are equal, meaning there is no master or slave node. This design eliminates single points of failure and allows any node to handle read and write requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9e9ef56-b3bf-432f-87ae-8922855c692b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the trade-offs of using Redis as a cache store versus a primary datastore in Rails?', N'Senior', N'Redis provides high-speed, in-memory access ideal for caching or transient session data, but it lacks the ACID compliance and complex querying capabilities of a relational database. Using it as a primary store puts your persistent data at risk of loss if not configured with proper persistence and replication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4206c7b8-1cae-4f6c-83b9-892297a8035c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why should you be careful with memory in Fiber?', N'Junior', N'Because Fiber is designed to be zero-allocation, it reuses objects during the request lifecycle. If you try to store or access parts of the request object after the handler finishes, you may encounter data corruption or unexpected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0361387-0b32-44a6-949a-89261ef34221', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you stop the default action of an event in jQuery?', N'Intern', N'You can use the event.preventDefault() method within your event handler. This prevents the browser from executing the default behavior, such as following a link or submitting a form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd29b68a6-7be3-4bc4-b328-892caba77c1c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you ensure idempotency in a distributed API, especially for POST requests?', N'Senior', N'Use idempotency keys passed in the request header, which the server stores in a high-speed key-value store like Redis. Before processing a request, the server checks if the key has already been processed to return the cached response; otherwise, it executes the operation and stores the result associated with the key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'026e7c5f-f351-461f-addc-892edd33a5b5', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of the @nestjs/graphql Resolver and @nestjs/graphql Scalar decorators, and how they relate to GraphQL in NestJS?', N'Senior', N'GraphQL is a powerful query language for APIs and a runtime for fulfilling those queries with your existing data. It''s an elegant approach that solves many problems typically found with REST APIs. The @nestjs/graphql package provides decorators that allow you to define GraphQL schemas directly from your TypeScript classes. 1. @Resolver(): This decorator is used to mark a class as a GraphQL resolver. Resolvers are the building blocks of GraphQL servers. They are responsible for fetching the data for individual fields in a schema. When you send a query to a GraphQL server, the server uses resolver functions to produce a response. On how its used check here 2. @Scalar(): This decorator is used to define a custom scalar. Scalars are primitive values: Int, Float, String, Boolean, or ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04f1d176-97b0-41a8-9f95-8931614011c8', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does ''sharding by range'' differ from ''sharding by hash'', and when would you choose one over the other?', N'Senior', N'Range sharding keeps related data together, allowing efficient range queries, but often leads to uneven data distribution. Hash sharding ensures uniform data distribution and avoids hot spots, but makes range-based queries across the entire dataset extremely inefficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90eeb9f1-c276-4f78-bfd5-893405e78bc9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of jQuery''s ''noConflict'' mode?', N'Middle', N'The noConflict mode allows developers to release the dollar sign alias used by jQuery, enabling it to coexist with other libraries that might also use it as a shortcut. This is essential for preventing namespace collisions in projects where multiple libraries are loaded simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b2ad107-bada-4b1a-bba9-8935f5936349', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is distributed tracing preferred over standard logging for debugging microservices?', N'Senior', N'Logs provide isolated context per service, making it difficult to reconstruct the flow of a single request across system boundaries. Distributed tracing provides a causal map of request latency and dependencies, allowing engineers to pinpoint exactly where an operation failed or stalled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84d253ef-90fc-4d2c-821c-893644e4955e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte''s approach to reactivity considered more ''standard'' JavaScript?', N'Senior', N'Svelte''s syntax relies on standard language features like variable assignment and top-level statements rather than proprietary hooks or complex proxy APIs. This lowers the barrier to entry and allows the compiler to perform optimizations that are more aligned with standard JavaScript execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'558cea17-96dc-45d8-9fee-893650158e7d', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the primary architectural difference between a side-cache and an inline-cache (read-through) pattern?', N'Senior', N'In a side-cache pattern, the application is responsible for checking the cache and updating it, which gives the application full control over the lifecycle. An inline-cache abstracts this logic into the cache layer itself, simplifying application code but potentially making it harder to handle complex cache miss logic or partial updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66a0fb41-1308-41ef-b266-8937531ad0a4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does it mean that Fiber is ''opinionated''?', N'Fresher', N'Fiber provides a set of sensible defaults and a structured way to handle web requests. Being opinionated means it encourages a specific way of building applications, which helps keep codebases consistent and easier to maintain for teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdaad964-dd5a-426b-8b9a-8938a4271d18', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'In a distributed Next.js architecture, how do you handle shared state between the server and the client without over-fetching?', N'Senior', N'Shared state can be handled by serializing data on the server and passing it to the client via props or a context provider. To prevent over-fetching, use selective data injection, ensuring only the necessary data required for the initial render is serialized into the HTML payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
