INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad8044b-b0f9-4fac-a00e-894178347e04', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the main difference between Webpack and Vite?', N'Fresher', N'Webpack bundles the entire application before starting the development server, which can lead to slow startup times. Vite uses native ES modules to serve files on demand, resulting in near-instant server start times regardless of project size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc23451a-7b50-4000-9072-8942bf22fdf5', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the benefit of using Chi''s context package for request-scoped data.', N'Middle', N'Chi utilizes the standard context package to pass request-scoped values through the middleware chain and into handlers. This ensures thread-safe data propagation, such as user authentication tokens or trace IDs, across different components of the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'969f1f2f-b86d-417c-8404-8944b421c28d', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum achieve type safety during request routing?', N'Middle', N'Axum uses sophisticated Rust macros and trait systems to verify that handlers match the expected request structure at compile time. This ensures that if a handler expects a specific JSON body, the router will enforce that contract before the handler is even invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0295126c-e77c-4a39-a1a4-8945277c6883', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are ''Refreshable'' beans?', N'Middle', N'Refreshable beans are components that can be re-instantiated at runtime when a refresh event is triggered. This is commonly used to update application configurations or feature flags without needing to restart the entire service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'570b8aa4-886a-4838-972b-8945dc5ba715', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is a stub?', N'Intern', N'Stubbing and verification for node.js tests. Enables you to validate and override behaviour of nested pieces of code such as methods, require() and npm modules or even instances of classes. This library is inspired on node-gently, MockJS and mock-require. Features of Stub: * Produces simple, lightweight Objects capable of extending down their tree * Compatible with Nodejs * Easily extendable directly or through an ExtensionManager * Comes with predefined, usable extensions Stubs are functions/programs that simulate the behaviours of components/modules. Stubs provide canned answers to function calls made during test cases. Also, you can assert on with what these stubs were called. A use-case can be a file read, when you do not want to read an actual file:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5fa28ca-166a-4945-8692-89498ca7e5be', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why should you implement pagination for a list of items rather than returning all results at once?', N'Junior', N'Returning all items at once can lead to performance degradation, high memory usage, and slow load times as the dataset grows. Pagination ensures the application remains responsive by limiting the amount of data transferred and processed per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'542bc62e-e25f-42c1-90bd-8949e6ac117e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is AdonisJS considered ''opinionated''?', N'Intern', N'AdonisJS is considered opinionated because it provides a specific, pre-configured structure and set of tools for building applications. By enforcing these standards, it reduces the need for developers to make constant configuration decisions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ae7fec5-9f6e-4e1d-b4b6-894be6602287', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why is it recommended to use ''List'' over ''MutableList'' in public APIs?', N'Middle', N'Using read-only ''List'' interfaces in public APIs ensures encapsulation and immutability, preventing external consumers from modifying internal state. This makes the code safer and easier to reason about, as the state of the list is guaranteed not to change unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c3c490a-1eb2-4a24-a0b0-894dbd908277', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between Ctx.Send and Ctx.JSON?', N'Junior', N'Ctx.Send is a generic method used to send a raw byte slice or string as the response body. Ctx.JSON automatically serializes a Go struct or map into JSON format and sets the appropriate Content-Type header to application/json.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3fab4c1-c2fe-4b6f-934f-895253245de2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the function of the Class Data Sharing (CDS) feature in modern JVMs?', N'Senior', N'CDS reduces startup time and memory footprint by storing class metadata in a shared archive file that can be mapped into memory by multiple JVM instances. This eliminates the need to parse class files and perform verification repeatedly, which is particularly beneficial for containerized environments running multiple microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a2d31d-552f-41d5-a60a-8954dec093c2', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle circuit breakers and fault tolerance?', N'Middle', N'Quarkus uses the SmallRye Fault Tolerance extension, which implements the MicroProfile Fault Tolerance specification. It allows developers to easily add annotations for retries, timeouts, and circuit breakers, ensuring resilient communication between microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b08a9c14-48f4-41e9-ae3d-89586841c95e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''implements'' keyword differ from ''extends''?', N'Middle', N'Extends is used for class inheritance, where the subclass inherits implementation and state from the parent. Implements requires the class to redefine all methods and properties defined in the interface, allowing for multiple implementation and enforcing a contract rather than sharing code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b934babe-badd-465a-bd92-895b65e41f29', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the trade-offs of using Node.js for microservices vs. monolithic architectures?', N'Senior', N'Node.js is excellent for microservices due to its low footprint and rapid startup time, which aligns well with container-based scaling. However, for complex, compute-intensive monoliths, the lack of true multi-threading and type safety (without TypeScript) can lead to maintainability and performance challenges. Microservices mitigate these by allowing different languages for specific domain needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b86735de-5fe8-4e78-b9b4-895c3e58973f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''display: content'' property affect accessibility and the accessibility tree?', N'Senior', N'Using display: contents removes the container from the box tree while keeping its children in place. This can negatively impact accessibility, as semantic wrappers or landmarks may become invisible to screen readers, potentially breaking document structure and navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5da6c2f9-089e-4805-bf4e-895d29b5a14f', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to handling data consistency in a distributed system with high availability requirements?', N'Senior', N'I prioritize eventual consistency using techniques like saga patterns or event sourcing to maintain system responsiveness. If strict consistency is required, I limit the scope to specific bounded contexts or use distributed locking mechanisms, while acknowledging the performance trade-offs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2438054a-5d25-4bd0-a3af-895e68207a1c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach choosing a primary key for a database table?', N'Junior', N'I look for a value that is unique, immutable, and ideally index-friendly. UUIDs are excellent for distributed systems where collision avoidance is critical, while auto-incrementing integers are simpler and more compact for smaller, self-contained applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4cc0359-a7ef-474d-941f-895f3abf87c1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the role of the Write-Ahead Log (WAL) in maintaining transaction durability.', N'Senior', N'The Write-Ahead Log ensures durability by recording all changes to a stable storage medium before they are applied to the actual database files. In the event of a crash, the system can replay the log to reconstruct committed transactions or undo uncommitted ones, maintaining Atomicity and Durability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b3b09f7-72a1-4eb9-882c-895f570baa8d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the common data models used in NoSQL?', N'Intern', N'The four most common NoSQL data models are document stores, key-value stores, wide-column stores, and graph databases. Each model is optimized for specific types of data access patterns and performance requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dddcdd64-8470-43b7-91e0-89604b792caa', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the significance of the ''sync.Pool'' in memory management.', N'Middle', N'Sync.Pool is a cache of allocated objects that are not currently in use, intended to reduce garbage collection pressure by reusing memory. It is most effective for frequently allocated and discarded objects, helping to maintain stable memory usage under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e64c9124-a8a6-439c-90b1-896186c5f15e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle server-side rendering?', N'Intern', N'Astro renders pages to HTML on the server at build time or request time. This approach ensures that the browser receives a fully formed page immediately, which improves initial load performance and SEO.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c5f39a8-a90f-41c1-86f6-8963941fcebc', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it generally better to use specific data types rather than generic ones?', N'Junior', N'Using specific data types like integers for numbers or timestamps for dates improves performance and storage efficiency. It also enforces data integrity at the database level by ensuring that only valid, expected information is stored in a column.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b9e1880-522c-43ae-941a-8964202c055f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a deadlock in database transactions?', N'Intern', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on resources. Because each transaction is waiting for the other to finish, neither can proceed, and the system must intervene to break the cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54f8b93a-fecd-473d-b0af-896437895528', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding in the context of NoSQL?', N'Fresher', N'Sharding is the process of splitting a large dataset into smaller, more manageable parts called shards. These shards are distributed across multiple servers, allowing the database to process requests in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f044c79-8559-4ba5-b7fd-896466f7d115', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar utilize Pydantic for data validation compared to other frameworks?', N'Middle', N'Litestar uses Pydantic to enforce strict type checking and schema definition directly within route handler signatures. This tight integration ensures that incoming request data is validated against the model before the handler logic executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08325068-544e-4e32-926d-8966dcbfd94d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How are connections managed in Redis?', N'Fresher', N'Redis uses a client-server architecture where clients connect via a network port. It manages these connections efficiently using an event-driven model that allows the server to handle thousands of concurrent client connections with very low overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
