INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42d72308-21ac-4ae9-ba9e-89693a254312', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What happens when an exception is thrown but not caught within an application?', N'Middle', N'If an exception reaches the top of the call stack without being caught, the runtime terminates the process. This is typically handled by global exception handlers in production environments to log the error and allow for a graceful shutdown or recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4cc0298-dd4b-4472-bfb9-89693bea5ed1', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle JSON serialization?', N'Intern', N'Fastify uses a library called fast-json-stringify, which pre-compiles JSON schemas into highly optimized serialization functions. This approach is significantly faster than the built-in JSON.stringify method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
