INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce9a54ed-a7b8-4b06-bfc2-896ae2d330b0', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit maintain consistency during concurrent updates to the same component?', N'Senior', N'Lit''s update cycle is designed to be idempotent; if multiple updates are requested, the final state is derived from the current value of the properties. The batching mechanism ensures that regardless of the frequency of property changes, the component only renders the latest state to the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd8f4a85-9d0c-4289-9fad-896bd1022e30', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is ''Pattern Matching'' using the match keyword?', N'Fresher', N'Pattern matching is a control flow construct that allows you to compare a value against a series of patterns and execute code based on which pattern matches. It is exhaustive, meaning the compiler ensures all possible cases are handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd57b1c9-af86-4feb-8f49-896c88fddfbd', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the asset pipeline?', N'Fresher', N'The asset pipeline is a framework that manages and optimizes static files like CSS, JavaScript, and images. It handles tasks like minification and concatenation to improve website performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adefaace-1194-41c9-b7bb-89731afab9b6', N'954a0331-deff-4399-b588-96f39fec001d', N'What is AOT compiler?', N'Intern', N'The AOT compiler is part of a build process that produces a small, fast, ready-to-run application package, typically for production. It converts your Angular HTML and TypeScript code into efficient JavaScript code during the build phase before the browser downloads and runs that code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83f40d59-ac41-4150-b950-8973ce11c9f0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra''s use of LSM-trees impact write performance compared to B-trees?', N'Senior', N'LSM-trees treat writes as append-only operations to an immutable memtable and sequential log, which avoids the random disk I/O associated with in-place B-tree updates. This architecture allows Cassandra to achieve extremely high write throughput at the cost of potential read amplification during compaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecb4ca89-1afa-41dd-9859-89766544685d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact achieve such a small file size compared to React?', N'Intern', N'Preact achieves a small footprint by implementing only the most essential features of the Virtual DOM. It omits some of the more complex legacy features and internal optimizations found in the larger React library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1e70abe-383a-4ca7-9bfb-8977611d146a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are route groups in Fiber?', N'Intern', N'Route groups allow developers to prefix a set of routes with a common path segment. This is useful for versioning APIs or grouping routes that share the same middleware, such as requiring authentication for a specific set of endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60511224-38e6-464d-80ed-89778a2856db', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis Replication?', N'Intern', N'Redis replication allows data to be copied from one Redis server, known as the master, to one or more servers, known as replicas. This setup improves data availability and allows for read scaling by distributing read requests across replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e87168b1-e825-4ebd-8be1-8984cf47c87e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a backup system in a real-world engineering project?', N'Intern', N'A backup system ensures that data can be recovered in the event of accidental deletion, hardware failure, or cyberattacks. It provides business continuity by minimizing downtime and data loss. Without backups, critical information could be permanently lost, causing significant operational damage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'586a66f3-7a4a-465d-8a3d-8985cd00564d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP engine handle memory allocation for large arrays?', N'Senior', N'PHP arrays are implemented as ordered hash maps, which consume significant memory compared to contiguous arrays in lower-level languages. For extremely large datasets, using SplFixedArray or external data stores is preferred to reduce memory overhead and avoid heap fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bec5aff-c6f7-44d0-a2f4-89878369d2a9', N'075b8862-431c-4678-9767-f55359758a4a', N'Discuss the impact of ''Suspense'' on the loading architecture of a Vue application.', N'Senior', N'Suspense provides a declarative way to handle asynchronous dependencies in a component tree, allowing the UI to show fallback states while waiting for async setup or nested components. It simplifies the orchestration of loading states, though it is still considered an experimental feature that requires cautious implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
