INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ec896b1-988c-41be-bc96-8996cf9cde2c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between public, private, and protected visibility?', N'Intern', N'Public properties or methods can be accessed from anywhere. Protected can be accessed only within the class itself and its subclasses, while private can only be accessed within the class that defines it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2e26185-ae31-4c74-9bf8-8998a7cfed03', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach a situation where an upgrade to a library dependency breaks the application?', N'Middle', N'I would first review the library''s changelog and release notes to identify breaking changes or deprecated APIs that match the symptoms. I would then use a binary search approach by reverting to previous versions of the dependency to confirm the specific version where the breakage occurred. Once identified, I would evaluate if the fix requires updating our implementation to align with the new library standards or if we need to pin the dependency version until a patch is available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9e7cd51-30e3-4508-9121-899b52ba8172', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Ember Engines and what problem do they solve?', N'Middle', N'Engines are essentially applications within an application that allow you to isolate parts of a codebase into distinct modules with their own routes, services, and components. They are primarily used to improve build times and enable lazy loading for large-scale enterprise applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4a35501-14fb-45a9-8034-899c3efb9789', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime handle goroutine scheduling?', N'Middle', N'Go employs an M:N scheduler that multiplexes many goroutines onto a smaller number of OS threads. It uses a work-stealing algorithm to balance loads across processor cores, ensuring that blocked goroutines do not stall the execution of others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e1a3bf-2b05-4b48-9733-89a314a7375f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can Alpine.js be used alongside other JavaScript libraries?', N'Intern', N'Yes, Alpine.js is designed to be compatible with other libraries and frameworks. Because it operates within the HTML and doesn''t require a specific architecture, it can easily coexist with jQuery or other utility libraries on the same page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18fc0116-898d-4c64-859c-89a3aac2d79e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the trade-off of using an ''Addr'' versus a ''SyncAddr'' in Actix.', N'Middle', N'An Addr is used to communicate with actors running on the same thread or asynchronous context. SyncAddr is used for actors that perform blocking operations and need to be offloaded to a separate thread pool to prevent stalling the main event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db5fabcf-ccc0-4214-88ae-89a56a743b33', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'In a microservices architecture, how does Litestar''s OpenAPI generation facilitate inter-service communication?', N'Senior', N'Litestar automatically generates accurate OpenAPI documentation based on the application''s type hints and DTOs, providing a single source of truth for other services to consume. This enables automated client generation and contract testing, significantly reducing integration errors between services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fbd5671-2266-4daa-bf65-89a67f9bcbfc', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the primary advantage of using an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point that handles cross-cutting concerns like authentication, SSL termination, rate limiting, and request routing. It decouples client applications from the internal microservices structure, allowing for easier service refactoring and evolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58a6572c-e473-44d6-bb45-89a8a3cd0139', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does the size of a message impact the performance of a distributed broker?', N'Senior', N'Large messages increase memory pressure, network bandwidth consumption, and disk I/O. For large payloads, it is better to store the data in an object store (like S3) and send a reference or URI via the message broker to keep the broker''s throughput high.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae41cd33-966a-4cff-88fd-89abe7ac48d9', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between dependency injection and inversion of control (IoC)?', N'Fresher', N'Dependency Injection (DI) and Inversion of Control (IoC) are both design patterns used to reduce the coupling between classes, making the code more modular, easier to test and maintain. However, they are not the same thing, but rather, DI is a form of IoC. Inversion of Control (IoC) is a general principle where the control flow of a program is inverted: instead of the programmer controlling the flow of a program, the external framework or runtime controls it. Dependency Injection (DI) is a form of IoC where the creation and binding of dependent objects is controlled by a container or a framework. Instead of a class creating or finding its dependencies, they are passed in (injected) at runtime by another piece of code, typically a container or a framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fec460a9-deae-4bb8-ae6e-89ac3f1066dc', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Discuss the impact of ''Contravariance'' and ''Covariance'' on generic API design in Kotlin.', N'Senior', N'Covariance (out) allows a generic type to be a subtype of another based on its parameter, which is essential for safe read-only collections. Contravariance (in) allows for broader type handling in consumer APIs, and balancing these ensures that APIs remain type-safe while maximizing reuse without compromising the integrity of the data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de6f9d4c-7874-4076-aa78-89ac7d398db5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik suitable for complex applications?', N'Junior', N'Yes, Qwik is designed for large-scale, complex applications. Its ability to break down massive codebases into tiny, manageable chunks makes it highly performant even for enterprise-level projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acb444a8-8312-4a42-be5d-89ad62ec360d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Does Redis support transactions like SQL?', N'Intern', N'Redis transactions are different from SQL ACID transactions. While they ensure sequential execution, they do not support rollbacks if an error occurs during the execution of queued commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e37ddfc-c9de-4cc5-985f-89aefb146afe', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the ''hydration'' process in standard frameworks?', N'Intern', N'Hydration is the process where a framework attaches event listeners and logic to server-rendered HTML. Qwik attempts to eliminate this process entirely to improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c97c4168-ec90-4837-99ba-89af0c476beb', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ''button'' and ''a'' tags?', N'Junior', N'An anchor tag is primarily used for navigation to a new URL or section of a page. A button tag is meant for triggering actions on the page, such as submitting a form or opening a modal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c9e053b-6ce0-4e8d-adf4-89b175da9b03', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why string is immutable in java?', N'Fresher', N'The string is Immutable in Java because String objects are cached in String pool. Since cached String literals are shared between multiple clients there is always a risk, where one client''s action would affect all another client. Since string is immutable it can safely share between many threads and avoid any synchronization issues in java.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60ec998-fbef-44a2-8e2e-89b224a0e23b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''public'' directory in Rails?', N'Junior', N'The public directory is meant for static files that should be served directly by the web server without passing through the Rails stack. Files placed here, such as the 404 error page or robots.txt, are accessible directly via their URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed6e8940-888b-499e-85f7-89b3126c526d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is ''as'' type assertion considered dangerous?', N'Middle', N'Type assertion tells the compiler to trust your knowledge of the type over its own analysis. If the assertion is incorrect, it can lead to runtime errors because the compiler will stop checking the expression, effectively bypassing the safety mechanisms of TypeScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dac3b284-1901-45ce-804b-89b396154812', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Bundle in the context of Symfony?', N'Intern', N'A bundle is a structured directory that acts as a plugin for a Symfony application, allowing you to group related features together. It can contain controllers, templates, configuration files, and services, making it easy to reuse functionality across different projects. Think of it as a modular way to organize and distribute code within the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f756b535-c841-4342-843e-89b4870bebc0', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s build process differ from traditional React frameworks?', N'Middle', N'Unlike traditional frameworks that bundle the entire application into a single JS file, Astro builds individual pages as independent static units. This modular approach ensures that CSS and JS are only included if used, preventing unnecessary bloat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'074cb983-0a48-4697-bb39-89b58c052d52', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the Result type used for in Rust?', N'Fresher', N'The Result type is used for error handling, representing either a success or a failure. It forces developers to handle potential errors explicitly, ensuring that the program remains robust and does not crash unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a01fe25-4504-4aec-ad05-89b72d75a8d4', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is idempotency important when designing distributed APIs?', N'Middle', N'Idempotency ensures that performing the same operation multiple times yields the same result as performing it once. It is critical in distributed systems to handle network retries safely when a client is unsure if a previous request succeeded due to a timeout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6207eed7-5b34-443e-a1c1-89b745120ceb', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'In a distributed system, how would you handle logging in Hono across multiple edge nodes?', N'Senior', N'Since edge logs are often ephemeral, you should use Hono''s middleware to stream logs to a centralized observability platform like Logflare or Datadog via the fetch API. This ensures that logs are persisted and searchable despite the distributed nature of the execution environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8b2e167-6511-4471-968a-89b7867a17c6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are data types in MySQL?', N'Intern', N'Data types define the kind of information that can be stored in a column, such as integers, floating-point numbers, strings, or dates. Choosing the correct data type is essential for optimizing storage space and ensuring data accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
