INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ecff714-78da-41b8-8dfa-89b8e704ce37', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the concept of ''Covering Index'' and why it improves query performance.', N'Senior', N'A covering index occurs when all columns required by a query are present in a single index. This allows the engine to satisfy the query entirely from the index tree without ever having to perform a costly lookup into the clustered index to retrieve additional row data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
