INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79b502a2-314a-48e5-8f35-89d165bf7b81', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is SolidJS often described as ''React without the Virtual DOM''?', N'Junior', N'It uses a similar component-based structure and JSX syntax, making it familiar to React developers. However, it replaces the Virtual DOM reconciliation with a direct, reactive update system that modifies the DOM node-by-node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fdf0b38-cc6d-4188-acc4-89d19aff6d63', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the benefits of using an Event-Driven Architecture (EDA) in microservices?', N'Middle', N'EDA allows services to communicate via events, which promotes high decoupling and scalability. It enables the system to be highly responsive to changes in state, as services can react to events asynchronously without needing to know who produced them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d65c321-d1ca-47d6-afa1-89d2c5d4fd1f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is the order of plugin registration critical in Fastify?', N'Senior', N'Since plugins have their own scope and lifecycle, a plugin might depend on a decorator or configuration provided by a parent. If a plugin is registered before its dependency, the application will fail during the boot process, as Fastify enforces strict order for context and dependency resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
