INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23d94149-966f-4eaa-af38-89db2b96d179', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the primary benefit of using relative sizing (like story points) instead of absolute time (like hours) for estimation?', N'Junior', N'Relative sizing focuses on the complexity and effort of a task compared to others rather than predicting an exact clock time. This accounts for uncertainty and individual productivity differences, making it easier for teams to forecast capacity over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebd12b4a-a924-4962-ae35-89dc62b3dbaf', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can transactions exist in NoSQL databases?', N'Fresher', N'Yes, many modern NoSQL databases support transactions, though they are often limited to single-document or single-partition operations. Some document-oriented databases now support multi-document transactions with ACID properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4f5b756-2a00-402e-92a7-89ded6e1f0f3', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support HTTP methods like GET, POST, PUT, and DELETE?', N'Fresher', N'Yes, Hono provides dedicated methods for all standard HTTP verbs. This makes it straightforward to define RESTful APIs by mapping specific request types to corresponding handler functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18780b20-70d6-403f-8932-89df02f0cbe2', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of database sharding in a Rails application, and what are its primary challenges?', N'Senior', N'Sharding distributes data across multiple database instances to scale horizontally beyond a single server''s capacity. The primary challenges include complex application-level routing, difficulties in performing cross-shard joins, and the need for robust migration management across distributed nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ebdfc11-84bb-4d8e-a858-89e0edf39e9f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does ''structural typing'' mean in TypeScript?', N'Fresher', N'Structural typing means that TypeScript compares types based on their shape or properties rather than their explicit names. If two objects have the same set of properties with matching types, they are considered compatible, even if they come from different interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fd3464f-0c90-4890-bb7e-89e1e17832fe', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the Redis ''Client-side caching'' feature?', N'Middle', N'Client-side caching allows applications to store frequently accessed data locally in their own memory to reduce network latency to the Redis server. Redis facilitates this by tracking keys requested by clients and sending invalidation messages when data changes, ensuring the local cache remains consistent with the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eebeaa6b-ae2f-4960-86cc-89e3a610cb78', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you design a rate-limiting strategy that works across multiple service instances?', N'Senior', N'A distributed rate-limiting strategy requires a shared state store like Redis to track request counts globally across service instances. You should use a sliding window algorithm to ensure accuracy and implement a backoff mechanism on the client side to handle 429 Too Many Requests responses gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
