INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03f2136e-5e48-4f16-8995-89ee9dc6e72d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it dangerous to perform blocking operations inside an Actix actor''s message handler?', N'Senior', N'Blocking operations halt the specific Arbiter thread, effectively stopping the event loop for all actors assigned to that thread. This leads to latency spikes and degraded throughput for all concurrent requests managed by that Arbiter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
