INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21dcec9e-06b5-4b90-8799-89ffd0a7c53e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the benefit of TypeORM or Prisma integration in NestJS.', N'Middle', N'These ORMs provide an abstraction layer for database operations, allowing developers to interact with data using objects rather than raw SQL. NestJS integrates them via modules that handle connection pooling and repository injection, simplifying data access layer management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23eb3206-c8e0-4d38-b6bd-8a0007212152', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are superglobal variables?', N'Fresher', N'Superglobals are built-in variables that are always available in all scopes throughout a script. Examples include $_GET, $_POST, $_SESSION, and $_SERVER.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d7ee166-6d7d-43bd-a698-8a01c4c9cfd2', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If you are designing a login page, why would you choose to hash passwords instead of storing them as plain text?', N'Fresher', N'Storing passwords as plain text is a major security vulnerability because any unauthorized access to the database would expose user credentials immediately. Hashing provides a one-way transformation that makes it computationally infeasible to retrieve the original password from the stored value. This ensures that even if the database is breached, user accounts remain protected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59276bc6-6960-4530-85be-8a02b50f0bf9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Describe the trade-offs of using Interface types in Go performance-critical paths.', N'Senior', N'Interfaces in Go involve dynamic dispatch, which requires a lookup in the interface''s method table, potentially hindering compiler optimizations like inlining. Additionally, boxing values into interfaces often results in heap allocations, increasing pressure on the garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63d5f6bd-ff28-4b40-8b46-8a02c0b6ac3d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between controlled and uncontrolled React Components?', N'Fresher', N'A controlled component drives a form input from React state — you pass value/checked plus an onChange handler, and React state is the single source of truth. An uncontrolled component lets the DOM keep the value; you read it via a ref (or on submit) and seed the initial value with defaultValue/defaultChecked. Controlled inputs are the right default when you need validation, conditional UI, or to derive other state from the value. Uncontrolled inputs are simpler for write-once forms and for , which is always uncontrolled. React 19 also added first-class form support via the form action prop, useFormStatus, and useActionState, which often removes the need for per-field controlled state. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495c32e1-20aa-41c6-8ee9-8a0615fdbbc1', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it recommended to place CSS in the head and scripts at the end of the body?', N'Middle', N'Placing CSS in the head ensures that the browser receives styling instructions early, preventing a ''flash of unstyled content'' during rendering. Placing scripts at the end of the body prevents the script execution from blocking the initial HTML parsing, allowing the page to render the DOM structure before attempting to attach logic. This improves the perceived performance of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a48a0ebc-f97f-43e2-8234-8a06cc7e3a3b', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the role of an orchestrator in container management?', N'Middle', N'An orchestrator manages the lifecycle of containers, including deployment, scaling, networking, and self-healing. It ensures that the desired number of container instances are running and automatically replaces failed instances to maintain service availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4cf7618-2fc3-4c59-bf51-8a07cb092c8d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between buying a managed service versus building a custom solution?', N'Senior', N'I prioritize buying managed services when the component is not a core differentiator for the business, as this offloads operational overhead and speeds up time to market. I choose to build only when the custom solution offers a unique competitive advantage, lower long-term costs, or deeper integration capabilities that off-the-shelf products cannot match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'381485e2-3158-4ae7-a66f-8a087eb4a970', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the trade-offs of using WebSockets in Actix-web?', N'Middle', N'WebSockets provide real-time, bidirectional communication but require maintaining persistent connections per user. This consumes more server memory compared to standard HTTP requests, necessitating careful resource management and scaling strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08806ac7-ce61-42c5-b00f-8a0b50e3447c', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch calculate relevance scores for search results?', N'Middle', N'Elasticsearch typically uses the BM25 algorithm, which evaluates how often a term appears in a document compared to how often it appears across the entire index. It rewards documents where the term is rare globally but frequent locally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b696675-0622-4639-ad35-8a0d6e0ac18c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a Rails ''service object'' and a ''concern''?', N'Middle', N'A service object is a design pattern used to encapsulate a specific business process or action, keeping controllers and models slim. A concern is a module used to share common logic across multiple models or controllers through mixins, focusing on code reusability rather than business logic orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f9a335d-ce26-4e41-9401-8a116f7e98b8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a unique constraint?', N'Fresher', N'A unique constraint ensures that all values in a column are different from one another. Unlike a primary key, a table can have multiple unique constraints, and it may allow a NULL value depending on the database configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'211a6c6b-8761-4a3a-bc78-8a1253968b46', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the common trade-offs when choosing between a relational database and a NoSQL store in Rails?', N'Middle', N'Relational databases (like PostgreSQL) are excellent for complex queries, strict data integrity, and ACID compliance, which is standard for Rails applications. NoSQL stores offer higher write throughput and flexible schemas, but they often lack relational consistency, making them better suited for unstructured data or high-scale caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9aec2bee-5d0b-4446-9fc1-8a17aef2193b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Web Debug Toolbar?', N'Intern', N'The Web Debug Toolbar is a development tool that appears at the bottom of the page in the development environment. It provides real-time information about performance, database queries, route matching, and memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3665b2a-3ecc-42b9-9109-8a1833082359', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an ''Extractor'' in Actix?', N'Intern', N'An extractor is a mechanism used to pull specific information from an incoming HTTP request, such as path parameters, query strings, or JSON body data. They allow developers to easily access request data directly in the arguments of a handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13fd4748-7d95-46c4-81e6-8a1ad6dd563d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle late-arriving or out-of-order messages in a stream processing system?', N'Middle', N'You can use watermarks or event-time windows to track progress and buffer out-of-order events. By defining a grace period, the system can wait for delayed messages before finalizing the result for a specific time window.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e876ead-4285-4c1a-b65e-8a1e6460655d', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the impact of global styles on an Angular application''s modularity?', N'Senior', N'Global styles can easily lead to unintended side effects and maintainability issues, as they lack scoping and can be overridden by specific component styles unpredictably. It is better to encapsulate styles within components and only use global styles for base reset, typography, and common design tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a97d5a1b-f5c7-4ea1-8a9c-8a1eab7ac454', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Are SolidJS components re-executed on every update?', N'Intern', N'No, SolidJS components only execute once when they are initialized. The logic inside the component body runs once, and subsequent updates happen via granular reactive bindings, not by re-running the component function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0246cc9-a288-4988-9ff2-8a1fd074aaba', N'4c000000-0000-0000-0000-000000000005', N'Explain the architectural difference between a push-based and pull-based observability system.', N'Senior', N'Push-based systems like Prometheus exporters allow services to initiate data transmission, which is easier for ephemeral jobs but can overwhelm the server. Pull-based systems give the server control over ingestion rate and discovery, though they require persistent endpoints for all targets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8992ea1f-1b7b-4b39-849f-8a204ef80f29', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''public'' directory used for?', N'Intern', N'The public directory is used to store static assets that do not need to be processed by the build tool, such as images, icons, or robots.txt files. Files placed here are served directly at the root URL of your website.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
