INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4df3ba39-70d8-4090-94de-8a26f8be68cd', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is ''mode'' in Webpack configuration?', N'Intern', N'The mode option tells Webpack to use its built-in optimizations corresponding to the specified environment. The two primary modes are ''development'' for faster build times and ''production'' for code minification and size reduction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec32ff79-9b9f-4bb1-9cdf-8a273922864c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an index, and what is the performance trade-off of having too many?', N'Middle', N'An index is a data structure, such as a B-Tree, that improves the speed of data retrieval operations. However, every additional index imposes a performance penalty on write operations like inserts, updates, and deletes because the database must update the index structure every time the data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f41eab7-f8c5-49e5-b39a-8a278825163e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Discuss the trade-offs of using ''Actors'' in Swift for state management.', N'Senior', N'Actors provide a safe mechanism for managing shared mutable state by serializing access to their internal data through a mailbox system. While they simplify thread safety, they introduce asynchronous interfaces for all properties and methods, which can lead to complex call chains. Additionally, overusing actors can create bottlenecks, as all tasks must wait for the actor''s executor to process requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e7684ac-3b66-46d4-95b2-8a298377e98a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of the Gin Engine?', N'Junior', N'The Engine is the main instance of the Gin framework. It acts as the central router and configuration hub that manages middleware, defines API endpoints, and starts the HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'397d6008-3e26-44df-b42d-8a299657fbf7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite differ from Webpack in terms of its core development server architecture?', N'Senior', N'Vite leverages native ES modules in the browser to serve source files on demand without bundling during development. Webpack bundles the entire application before starting the dev server, leading to slower startup times as the project grows compared to Vite''s instant server start.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef99f4a-b508-4ef7-a8ad-8a2d537c397f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is ''web::Path'' used for?', N'Intern', N'The web::Path extractor is used to capture variable parts of a URL path. It parses these segments and maps them to parameters in the handler function, making it easy to create dynamic routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fb8da2a-a544-4461-8182-8a2d618d2ebf', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain generators and iterators in python?', N'Fresher', N'- They do, but there are subtle differences: - For a generator, we create a function. For an iterator, we use in-built functions iter() and next(). - For a generator, we use the keyword ''yield'' to yield/return an object at a time. - A generator may have as many ''yield'' statements as you want. - A generator will save the states of the local variables every time ''yield'' will pause the loop. - An iterator does not use local variables; it only needs an iterable to iterate on. - Using a class, you can implement your own iterator, but not a generator. - Generators are fast, compact, and simpler. - Iterators are more memory-efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'812e497b-bcd6-4b89-ba43-8a2ea03de84a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is a Service Provider in AdonisJS?', N'Intern', N'Service Providers are the central place to configure and register services within the IoC container. They are responsible for booting up parts of the application, such as database connections, custom middleware, or third-party packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b7ab694-cbcf-4070-a8f9-8a2f63f74c25', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM''s memory barrier implementation ensure thread safety on weakly ordered architectures?', N'Senior', N'On architectures like ARM, the hardware may reorder memory operations; the JVM uses memory barriers (or fence instructions) to enforce strict ordering constraints. These barriers ensure that load and store operations are committed in a way that aligns with the requirements of the Java Memory Model, preventing invalid thread-local states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c09f78f5-0f3e-4eb7-b0f5-8a305f54ed6e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What role does the ''deferred loading'' feature play in large-scale applications?', N'Senior', N'Deferred loading allows for code splitting by instructing the compiler to load specific libraries lazily at runtime. This significantly reduces the initial application bundle size and decreases startup time, which is essential for performance-critical web and mobile applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab4adcdb-83a3-4f57-a300-8a306e69b5ae', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the Micronaut Configuration Properties system, and how does it support hierarchical configuration?', N'Senior', N'The configuration system uses type-safe property binding that maps environment variables or file-based settings directly to POJOs. It supports hierarchical resolution, allowing developers to override global settings with environment-specific values, promoting clean separation between application logic and infrastructure settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e516db8-1109-48bc-b609-8a33375c76e9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis considered faster than a disk-based database?', N'Fresher', N'Redis is faster because it performs operations directly in RAM, which has significantly lower latency than hard disk drives or even solid-state drives. Accessing data from memory avoids the mechanical or electronic delays associated with disk I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f1cb55c-5872-4830-bd9f-8a3626f8b896', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are the trade-offs of using Rocket''s strict routing system?', N'Middle', N'The main trade-off is a steeper learning curve regarding the type system and procedural macros. However, the benefit is significantly higher reliability and performance, as the framework catches routing and parameter mismatches at compile time rather than during runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3602626c-ba1c-4cf4-9dac-8a3989a61ce0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s binder interface compared to manual request deserialization?', N'Senior', N'The binder interface provides a unified, extensible way to map request data from various sources like JSON, XML, or form data into structs. Using it promotes cleaner code and allows for global input validation logic to be applied consistently across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca024b9a-b458-4158-82ea-8a3a7b93afef', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why might you want to create static class members in JavaScript?', N'Fresher', N'Static class members (properties/methods) have a static keyword prepended. Such members cannot be directly accessed on instances of the class. Instead, they''re accessed on the class itself. Static members are useful under the following scenarios: - Namespace organization: Static properties can be used to define constants or configuration values that are specific to a class. This helps organize related data within the class namespace and prevents naming conflicts with other variables. Examples include Math.PI, Math.SQRT2. - Helper functions: Static methods can be used as helper functions that operate on the class itself or its instances. This can improve code readability and maintainability by separating utility logic from the core functionality of the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'861f2f24-ffcd-4fa9-afb2-8a3afe114039', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''hot spot'' in a NoSQL database and how can it be avoided?', N'Middle', N'A hot spot occurs when a disproportionate amount of read or write traffic is directed at a single node or partition. This can be mitigated by choosing a high-cardinality partition key that distributes data more uniformly across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd932ee7-53aa-4319-a288-8a3d354597e4', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a WSGI server in relation to Flask?', N'Intern', N'WSGI stands for Web Server Gateway Interface, which acts as a bridge between the Flask application and the web server. Flask provides a built-in development server, but a production-grade WSGI server is required to handle real-world traffic safely and efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'432ce73c-8c20-4e2c-989d-8a3f7f0b0cb5', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the order of execution for Echo middleware?', N'Junior', N'Middleware in Echo is executed in the order it is registered. When a request comes in, it passes through the middleware chain sequentially before reaching the final handler, and then passes back through them in reverse order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff35b288-18bd-4529-b4cd-8a43701ba7d7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a container component?', N'Intern', N'A container component is a component that is connected to the Redux store. Its primary role is to retrieve data from the state and pass it down to child components, which are often called presentational components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04dbbfb1-1345-469c-8f80-8a479028676b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the impact of choosing a cutting-edge technology over a stable, older one?', N'Intern', N'Cutting-edge tools may offer better efficiency or features but often lack community support, documentation, and stability. Mature technologies are safer and easier to troubleshoot, though they may feel less innovative or efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
