INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7adf3d4b-c5fc-4020-bed5-8a4b98e86ca1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When choosing a naming convention for your database tables, why is consistency more important than the specific style chosen?', N'Fresher', N'Consistency ensures that the codebase remains readable and predictable for everyone on the team. When naming patterns are uniform, developers can easily infer table names and relationships without constantly checking documentation. A consistent style reduces cognitive load and helps prevent errors during development and maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ff45966-a768-4741-945b-8a4ce3d32529', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between UNION and UNION ALL?', N'Fresher', N'UNION removes duplicate rows from the final result set, whereas UNION ALL includes all rows, including duplicates. Because UNION performs a distinct operation, it is generally slower than UNION ALL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
