INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f5af456-5ce5-485c-b583-8a5b8d8214d9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a DTO and an Entity model, and why should you keep them separate?', N'Middle', N'An Entity represents the database schema, while a DTO is a contract for the API response or request. Separating them prevents internal database structure from leaking to the client and allows for flexible API versioning without breaking underlying database schemas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd26c9c5f-52c1-4bef-b546-8a6045d68902', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is Type Inference?', N'Intern', N'Type inference is the ability of the TypeScript compiler to automatically determine the type of a variable based on its value. This allows developers to omit explicit type annotations while still maintaining type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87b90c1d-d7d8-4f58-a838-8a6163fb1f97', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the significance of the ''State'' extractor in Axum.', N'Middle', N'The State extractor allows for sharing application-wide data, such as database connection pools or configuration settings, across multiple handlers. It provides a thread-safe way to access shared resources by injecting the state directly into the handler signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84043496-4903-435f-9089-8a61904ef8ce', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the trade-offs between using ''struct'' and ''class'' in C# regarding memory allocation and the garbage collector.', N'Senior', N'Structs are value types typically allocated on the stack or inline within containing types, which reduces pressure on the garbage collector. Classes are reference types allocated on the heap, requiring garbage collection. Overusing structs can lead to performance overhead due to memory copying, while classes introduce pointer indirection and potential heap fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3534202d-1905-49d5-912a-8a61dd03d652', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the difference between strictNullChecks and standard type checking.', N'Middle', N'With strictNullChecks enabled, null and undefined are not automatically included in every type, forcing the developer to explicitly handle them. This significantly reduces runtime errors caused by accessing properties on null or undefined objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39c3199c-059b-4412-a861-8a63c4a7201a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve lower memory usage than other Java frameworks?', N'Middle', N'By avoiding heavy reflection-based frameworks and dynamic proxy generation, Micronaut reduces the heap requirements significantly. The compile-time approach ensures that only the necessary classes are loaded, which is crucial for containerized environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b83e67ac-b006-46fd-9a0b-8a6793883d67', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the trade-off of using synchronous REST versus asynchronous messaging for inter-service communication.', N'Middle', N'Synchronous REST is simple to implement and easier to debug, but it creates temporal coupling where the caller must wait for the receiver to respond. Asynchronous messaging decouples services and improves system resilience and throughput, but adds complexity regarding message delivery guarantees and debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98a56cd4-2503-47ba-9c4e-8a68e44bfe49', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the importance of version control when working in a team?', N'Junior', N'Version control allows multiple developers to work on the same codebase simultaneously without overwriting each other''s changes. It provides a history of modifications, making it easy to revert to a previous stable state if a new change introduces a bug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
