INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b604825-da55-4770-bc04-8a73476667a7', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is sharding and why is it used?', N'Middle', N'Sharding is the process of splitting a large dataset into smaller, more manageable chunks across multiple database servers. It is used to distribute the storage and query load, allowing the system to scale horizontally when a single database instance can no longer handle the traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b60a4a6-bb87-4fe2-a7d9-8a74b2963073', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle server-side data loading?', N'Junior', N'SvelteKit uses a +page.server.js file to execute code exclusively on the server before the page is rendered. This allows you to securely fetch data from databases or APIs and pass it to your component as props before the user sees the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'242705ca-5252-43d2-a777-8a78d78c5a33', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the role of the copy-and-swap idiom.', N'Middle', N'The copy-and-swap idiom is a technique used to implement robust assignment operators that provide strong exception guarantees. It works by creating a temporary copy of the source object and then swapping its internal state with the current object, ensuring that the operation either succeeds completely or leaves the object unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ccdc00b-2137-4b20-9ed5-8a799832db07', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the performance trade-offs of using abstract classes versus interfaces in Java?', N'Middle', N'Abstract classes allow for stateful objects and protected members, which can simplify code reuse but limit flexibility due to single inheritance. Interfaces provide greater design flexibility through multiple inheritance of type, and since Java 8, they support default methods, though they cannot hold instance state, which may impact how data is encapsulated within a hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
