INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b91c7d8-4342-46bf-a336-8a7f6ebc19cd', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the performance implications of using too many ''onRequest'' hooks?', N'Middle', N'Every ''onRequest'' hook adds a layer of execution to the request lifecycle, which increases the time taken to process each incoming request. While helpful for global tasks, excessive use can lead to increased latency and potential event loop starvation if the hooks perform heavy synchronous operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'064a38d2-e654-4d9c-9b7c-8a7fed1340ac', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of the ''Coordinator'' node in a search request, and when does it become a bottleneck?', N'Senior', N'A coordinating node receives the request, broadcasts it to the relevant shards, merges the results, and returns them to the client. It becomes a bottleneck when it lacks the CPU or memory resources to handle the accumulation and sorting of large volumes of data returned from a high number of shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c9c4baa-454b-49c8-93ce-8a812a2e09cc', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS ''aspect-ratio'' and ''content-visibility'' help prevent Cumulative Layout Shift (CLS)?', N'Senior', N'These properties allow the browser to reserve space or delay rendering for content that has not yet loaded. By defining explicit aspect ratios, the layout remains stable even before images or iframes finish loading, directly contributing to better user experience metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
