INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c9655e7-0cec-4d18-a59d-8a87fe8bd93a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What happens when you call the setState method in a Preact component?', N'Junior', N'Calling setState queues a change to the component''s state and triggers a re-render. Preact batches these updates for efficiency, meaning it will wait until the next tick to apply the changes to the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1800e11d-8a79-4a7d-86d3-8a88cd97667b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the architectural risks of ''CSS-in-JS'' when rendering on the server?', N'Senior', N'Server-side rendering with CSS-in-JS requires generating and injecting styles into the initial HTML payload. This increases the total HTML size and complexity, potentially delaying the time to first byte and requiring careful management of style rehydration to avoid a flash of unstyled content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecc34228-d1eb-4168-a718-8a8954d30754', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the role of the browser''s preload scanner and how it influences network performance.', N'Senior', N'The preload scanner parses the raw HTML while the main parser is blocked, identifying and initiating downloads for critical resources like CSS and scripts early. Optimizing this via link tags (preload/prefetch) is essential for reducing the critical request path and improving Largest Contentful Paint (LCP).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cbae114-2b47-4e6c-bbdf-8a8970880aed', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach scaling a service that is hitting its CPU limits under peak load?', N'Middle', N'I first perform a bottleneck analysis to determine if the CPU usage is due to inefficient algorithms, excessive serialization, or high request volume. If the logic is optimal, I would look into horizontal scaling by adding more instances behind a load balancer. If the load is skewed, I would investigate implementing asynchronous processing or offloading heavy tasks to a background worker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a2b3996-8bcf-4c0c-9efc-8a9020d624d8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS manage global state without a Context API wrapper?', N'Middle', N'Since SolidJS signals are independent of the component tree, you can export a signal instance from a separate module and import it into any component. This makes global state management highly performant and easy to implement without needing complex provider patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb115729-2a47-450a-b205-8a909e5c2743', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is there only one store in a Redux application?', N'Intern', N'Having a single store makes it easier to track changes and debug the application. It provides a centralized location for state, which simplifies state synchronization and data flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f07a3d5-3f38-4eff-bdb6-8a9195190d5a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How do you define a configuration property in Micronaut?', N'Junior', N'Properties are typically defined in application configuration files like application.yml or application.properties. Micronaut allows you to inject these values into beans using specific annotations, making it easy to manage environment-specific settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb946cc6-d104-4fa5-9508-8a92054f41d2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle reactivity?', N'Intern', N'Svelte achieves reactivity through simple variable assignments. When a variable defined in the script section is updated, Svelte automatically detects the change and updates the corresponding part of the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0333de94-4b8e-4972-82c7-8a923f6a5fb3', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Are Webpack plugins executed in a specific order?', N'Intern', N'Generally, plugins are executed in the order they appear in the plugins array within the configuration. However, some plugins may have internal hooks that execute at specific stages of the compilation lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0482ef14-51b0-44a9-a8fd-8a92485ec400', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If you receive a vague error message, what is your next step?', N'Intern', N'Search internal documentation or technical support forums for the specific error code or string to see if others have encountered it. If that fails, look for associated logs that provide more detail or context around the moment the error was triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c376a967-a2fa-4b4d-b0f6-8a98ef60ac40', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the !default flag?', N'Middle', N'The !default flag assigns a value to a variable only if it has not been previously assigned. It is essential for creating themeable components where you want to provide a fallback value but allow the user to override it globally before the component is imported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5938f0f-d0c7-4689-b8ca-8a9ada3cafa7', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why might you use multiple entry points in a Webpack project?', N'Middle', N'Multiple entry points are useful for multi-page applications where each page has its own distinct script. This allows you to generate separate bundles for different parts of an application, ensuring that users only download the code required for their specific page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a30bc93d-928d-441c-ae26-8a9bfc39bf69', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How Relay is different from Redux?', N'Fresher', N'Relay is similar to Redux in that they both use a single store. The main difference is that relay only manages state originated from the server, and all access to the state is used via _GraphQL_ queries (for reading data) and mutations (for changing data). Relay caches the data for you and optimizes data fetching for you, by fetching only changed data and nothing more.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ced712f-d4ef-4a48-8619-8aa34e3d7e5c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between @Singleton and @Prototype scopes in Micronaut?', N'Junior', N'The @Singleton scope ensures that only one instance of a bean exists, while the @Prototype scope creates a new instance of the bean every time it is requested or injected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a67725e-6e6a-4e21-a209-8aa43f1591d8', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between physical and logical database design?', N'Senior', N'Logical design focuses on the structure of the data, the relationships between entities, and normalization without regard for the underlying storage technology. Physical design concerns itself with implementation details like indexing strategies, sharding, partitioning, and storage hardware performance optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9af5f2e2-2f7c-44b7-8802-8aa478acae7d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you submit a form using JavaScript?', N'Fresher', N'Generally, a form is submitted when the user presses a submit button. JavaScript provides the form object that contains the submit() method. Use the "id" of the form to get the form object. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6580ff3-bfcf-4b79-89e1-8aa580874138', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a major risk of using very large keys in Redis?', N'Middle', N'Large keys, such as massive hashes or lists, can cause memory fragmentation and latency during network transmission. Deleting a very large key can also block the event loop for a significant amount of time, which can impact the performance of other operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a094c8e-b227-428f-b2e5-8aa59bd9e332', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How would one optimize the performance of React contexts to reduce rerenders?', N'Senior', N'The first thing to know in 2026 is that the React Compiler auto-memoizes components and values, so a lot of the manual useMemo/useCallback work that used to be required for context performance is now done for you — adopt it before reaching for other tricks. Beyond that, the canonical patterns are: split a single context into a state context and a dispatch (or setter) context so consumers that only dispatch don''t rerender on state changes; memoize the value object you pass to the provider; wrap consumer components in React.memo; and reach for selector libraries like use-context-selector when you need to subscribe to a slice of a large value. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'226536d8-ad43-4886-bbf0-8aa6a6cd0361', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What does it mean for Dart''s type system to be ''sound''?', N'Senior', N'A sound type system ensures that a variable of a specific type can never hold a value of an incompatible type at runtime, regardless of what the static analysis suggests. In Dart, this is enforced by combining static compile-time checks with runtime checks, ensuring that type-related bugs are caught reliably.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a50b1673-b2b6-49b7-8662-8aa6d8e169ae', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are Webpack''s ''loaders'' specifically used for with CSS?', N'Fresher', N'Since Webpack only understands JavaScript, CSS loaders are used to read CSS files and inject them into the DOM or bundle them into a single stylesheet. Common loaders for this include css-loader and style-loader.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
