INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc03e4cc-00d1-42a6-9221-8aa97566ed69', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary benefit of using Echo''s data binding feature?', N'Middle', N'Data binding automatically maps incoming request payloads like JSON, XML, or form data into Go structs based on struct tags. This eliminates the need for manual parsing and type conversion, reducing boilerplate code and potential errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33cacf4b-3192-4b49-a0c9-8aaa326a0e6b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are readonly properties?', N'Intern', N'Readonly properties are fields that can only be assigned a value when they are first initialized. Once assigned, they cannot be modified throughout the lifecycle of the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f20a892-4501-4bdd-a4a3-8aadbfc71cf8', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is Fasthttp important for Fiber?', N'Intern', N'Fasthttp is the underlying engine that makes Fiber fast by optimizing how HTTP requests are parsed and responses are written. It is specifically designed to handle high concurrency with minimal memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a8c3483-544f-4b17-b20d-8ab1a92dd286', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the distinction between ''binding'' and ''assignment'' in R?', N'Middle', N'Assignment refers to the act of associating a value with a name in an environment. Binding is the underlying mechanism that links a name to an object reference, and understanding this is critical when dealing with environments or when passing objects that might share the same reference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6c49af5-9e1b-432b-8851-8ab4c15a74c7', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is Scala''s ''Either'' type preferred over throwing exceptions in functional pipelines?', N'Senior', N'Either explicitly encodes the possibility of failure into the method''s return type, forcing the caller to handle the error condition as part of the normal program flow. Unlike exceptions, which create hidden control flow and can be ignored, Either makes error handling a typed, explicit requirement. This leads to more robust code where failures are treated as values rather than control flow interruptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cec1faf-e084-4b52-beaf-8ab4e0c14934', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''express-validator'' library?', N'Middle', N'It provides a set of middleware that validates and sanitizes request data before it reaches the main route logic. This helps ensure that the input matches expected formats and prevents common security issues like SQL injection or cross-site scripting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b719efb-14d0-4c0c-9e36-8ab5dda14079', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle environment variables across different platforms?', N'Junior', N'Hono provides a consistent way to access environment variables through the Context object. Because it abstracts the runtime, developers can access platform-specific secrets or configuration variables without needing environment-specific boilerplate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18c8efc1-6415-4e83-b7ea-8ab7f4af8591', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the Panache Active Record pattern?', N'Junior', N'The Active Record pattern allows developers to define entities that contain both data and the logic to persist that data. By extending the PanacheEntity class, developers can perform database operations directly on the entity class without needing separate repository classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51f7bce1-62e0-4387-950e-8ab829851583', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the ''Qwikloader'' and why is it important?', N'Fresher', N'The Qwikloader is a tiny script that is embedded in the initial HTML document. Its main role is to intercept user interactions, such as clicks or scrolls, and then fetch and execute only the specific code required for that interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdd5949a-80ed-4447-8ab7-8ab9cc13cea4', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does message batching affect throughput and latency in a messaging system?', N'Senior', N'Batching improves throughput by reducing network round-trips and overhead per message, but it increases end-to-end latency because the producer must wait for the batch to fill or a timeout to expire. It is a trade-off that should be tuned based on the application''s sensitivity to real-time data versus total volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38a90676-d045-4d43-980a-8abbef53ff30', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the architectural challenge of ''method_missing'' in terms of static analysis and API discoverability.', N'Senior', N'method_missing enables dynamic proxying and flexible APIs by intercepting calls to undefined methods, but it makes static code analysis and IDE autocompletion impossible for these dynamic calls. This creates a ''black box'' effect where developers cannot easily track where methods are defined or invoked, complicating long-term maintenance of the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5197ab8e-9a8d-4251-8bc4-8abf70de522e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How can you mitigate buffer overflows in C?', N'Middle', N'Buffer overflows are mitigated by consistently checking array bounds before writing data and preferring safer standard library functions that require an explicit buffer size. Using modern static analysis tools and sanitizers during testing also helps detect potential vulnerabilities before deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7b3a6f1-c6e0-4b28-bfd0-8abfaa12497c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does PHP stand for and what is its main purpose?', N'Intern', N'PHP originally represented "Personal Home Page," signifying its early focus on web development. It has since evolved to suggest "PHP: Hypertext Preprocessor," emphasizing its role in server-side scripting and building dynamic web content. Core Functions - Generating Dynamic Content: PHP is adept at generating dynamic web content, web pages, images, and more. - Handling Form Data: It efficiently processes form data from HTML input fields. - Accessing Databases: PHP can interact with databases, empowering dynamic content storage and management. - Session Management: It enables web state management, crucial for maintaining user context across multiple requests. - File System Interaction: PHP can manipulate files on the server filesystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4139bc0e-d4ce-4041-bf06-8ac1097f4bc5', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is a ''child process'' in Node.js?', N'Junior', N'The child_process module enables Node.js to spawn new processes that run independently of the main event loop. This is useful for executing system commands or offloading CPU-intensive tasks to external scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31d18ede-d347-4ce4-8662-8ac282f7a8ee', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is formik?', N'Intern', N'Formik is a small react form library that helps you with the three major problems, 1. Getting values in and out of form state 2. Validation and error messages 3. Handling form submission', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0333173-a98d-41c5-b832-8ac38257eebd', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the ''Quarkus Platform''?', N'Fresher', N'The Quarkus Platform is a curated set of extensions that have been tested to work together seamlessly. Using the platform ensures compatibility and stability across different components within a Quarkus project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd050bd93-92a0-4cb1-aa6f-8ac7e67dc0da', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of the ''include'' versus ''prepend'' keywords in module composition?', N'Middle', N'Using ''include'' adds a module to the ancestor chain after the current class, meaning methods in the class take precedence. Conversely, ''prepend'' adds the module before the current class, allowing the module''s methods to override or wrap the original class methods. This is a common pattern for implementing decorators or cross-cutting concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b9faf4b-00c9-43a1-b403-8ac9cba7f671', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring support AOP?', N'Fresher', N'Spring provides a powerful Aspect-Oriented Programming (AOP) framework. This framework simplifies the development process by enabling the separation of cross-cutting concerns from the main business logic. This leads to modular and more maintainable code. Core Concepts Aspect An aspect is a module encapsulating concerns such as logging or security. These typically cross-cut multiple application modules. Join Point A join point is a point during the execution of a program such as a method invocation. Advice The action taken by an aspect at a particular join point. Different types of advice include *before*, *after*, *around*, *after-returning*, and *after-throwing*. Pointcut A rule in AOP that defines the join points where advice should be applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36d06066-1e47-4f50-9d1b-8ad00946e5c8', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is the order of CSS rules in the cascade critical for large-scale applications?', N'Senior', N'The cascade determines style application based on origin, specificity, and source order. In large applications, reliance on source order creates fragile dependencies that are difficult to debug, often necessitating strict naming conventions like BEM or architectural patterns like ITCSS to maintain control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e29ef3db-00d4-4503-b83e-8ad09bd7b208', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is database normalization and when should it be avoided?', N'Middle', N'Normalization organizes data to reduce redundancy and improve integrity. It should be avoided in read-heavy systems where performance is more critical than data storage efficiency, as it often requires complex joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85113047-fdda-4df9-b44b-8ad3a56b0b69', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Describe the architectural impact of Preact''s ''diff'' function on browser layout thrashing.', N'Senior', N'Preact''s diffing algorithm is highly optimized to minimize direct DOM mutations, effectively reducing the number of layout reflows triggered by the browser. By grouping changes and applying them in a single pass, it prevents the layout thrashing that occurs when interleaved reads and writes are performed on the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fd21667-057f-4ae9-a758-8ad6aab0de1b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the ''maxmemory-policy'' and how do different strategies impact system behavior?', N'Senior', N'The policy determines how Redis evicts keys when the memory limit is reached, such as LRU, LFU, or random expiration. Choosing the right policy is critical for performance, as improper configuration can lead to the eviction of frequently accessed data or unnecessary CPU overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecc463c1-82d8-4b55-8207-8ad6c9c66ef0', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you update specific properties of a form model?', N'Fresher', N'You can use patchValue() method to update specific properties defined in the form model. For example,you can update the name and street of certain profile on click of the update button as shown below. You can also use setValue method to update properties. Note: Remember to update the properties against the exact model structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64c995c9-e0b7-4cf1-bbee-8ad9866d9212', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is CRA and its benefits?', N'Intern', N'The create-react-app CLI tool allows you to quickly create & run React applications with no configuration step. Let''s create Todo App using _CRA_: It includes everything we need to build a React app: 1. React, JSX, ES6, and Flow syntax support. 2. Language extras beyond ES6 like the object spread operator. 3. Autoprefixed CSS, so you don’t need -webkit- or other prefixes. 4. A fast interactive unit test runner with built-in support for coverage reporting. 5. A live development server that warns about common mistakes. 6. A build script to bundle JS, CSS, and images for production, with hashes and sourcemaps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae9ac3f9-bc7a-4b68-a33d-8ada10f45d8b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the performance trade-off of enabling AOF fsync every second versus every write?', N'Middle', N'Using ''fsync every second'' provides a good balance between data safety and performance by batching disk writes. Using ''fsync always'' ensures maximum durability but drastically reduces throughput because the server must wait for disk I/O confirmation for every single write command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2784460f-3d39-4e19-9b44-8adba2ef7fbe', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary trade-off when choosing between Snapshot Isolation and Serializability?', N'Senior', N'Snapshot isolation provides high concurrency by allowing transactions to read from a consistent version of the database without blocking writers, but it is susceptible to write skew anomalies. True serializability guarantees the highest level of correctness by ensuring the outcome is equivalent to some sequential execution, though it significantly reduces throughput due to increased contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf176d48-5f85-4ddb-ac46-8adc1084bdd7', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of Compaction in Cassandra?', N'Fresher', N'Compaction is the process of merging multiple SSTables into a single, larger SSTable. It helps reclaim space by removing obsolete data and improves read performance by reducing the number of files the system must check.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68b4a5a6-39ec-4492-9f73-8add3ed53c86', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the Exception Filter?', N'Junior', N'Exception filters are used to catch unhandled exceptions across the application and return a user-friendly response. They allow you to centralize error handling logic rather than writing try-catch blocks in every controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47a78d8c-a955-42a7-a6d4-8add600398a6', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the impact of microservices on system testing?', N'Middle', N'Testing becomes more complex because it requires testing individual services in isolation (unit/integration tests) as well as verifying interactions between services (contract testing). End-to-end testing also becomes harder to maintain and slower to execute, necessitating a shift toward consumer-driven contract testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'357e341c-2f2f-49b6-9297-8add86e7fcb2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Describe the trade-offs of using Svelte''s ''module'' context for state persistence.', N'Senior', N'The context=''module'' block allows state to be shared across all instances of a component. While powerful for singleton-like behavior, it can introduce side effects that make components harder to isolate and test independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b66e6bc-59af-4e94-8b55-8ae1ce1e3008', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain database connection in Python Flask?', N'Fresher', N'Best database for flask is MySQL. Flask supports database powered application (RDBS). Such system requires creating a schema, which requires piping the shema.sql file into a sqlite3 command. So you need to install sqlite3 command in order to create or initiate the database in Flask. Flask allows to request database in three ways - before_request(): They are called before a request and pass no arguments. - after_request(): They are called after a request and pass the response that will be sent to the client. - teardown_request(): They are called in situation when exception is raised, and response are not guaranteed. They are called after the response been constructed. They are not allowed to modify the request, and their values are ignored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bdfb60e-398f-4b0e-8de1-8ae4c7b1bd44', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the trade-offs of using Secondary Indexes in Cassandra?', N'Middle', N'Secondary Indexes are useful for querying by non-partition key columns but can cause significant performance degradation. They require the cluster to scan all nodes for a query, which is inefficient for high-cardinality data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58a002a5-ec7e-423c-89ae-8ae656cc9773', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between centralized and decentralized logging systems?', N'Fresher', N'Centralized logging makes troubleshooting easier across multiple services but introduces a single point of failure and potential latency. Decentralized logging is more resilient but makes it difficult to aggregate and correlate events for debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'347e8a78-11ae-4a66-a415-8ae7cbdec180', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are Fastify lifecycle hooks?', N'Junior', N'Lifecycle hooks are specific points in the processing of a request where you can inject code. These include onRequest, preParsing, preValidation, preHandler, preSerialization, and onSend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'592d45d0-07da-4603-84d7-8aea29a54e96', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between internal and external linkage?', N'Middle', N'External linkage means a variable or function is visible throughout the entire program, allowing it to be shared across multiple object files. Internal linkage, specified by the static keyword, limits the visibility of the identifier to the current translation unit, which helps prevent naming collisions in large projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71acca44-aaf7-4c7f-bbb2-8aeda300092f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Temporal Dead Zone'' in block-scoped declarations reflect the internal parsing and lexical environment lifecycle?', N'Senior', N'The TDZ exists because variables declared with let or const are hoisted to the top of the block but remain uninitialized. The engine enforces this by tracking the lexical binding status, ensuring that accessing these variables before their declaration results in a runtime error to maintain predictability in scope integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08002f8a-c805-457c-8c73-8aeeaf237a2c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the advantage of Vite''s ''on-demand'' compilation strategy?', N'Fresher', N'By only compiling the code that the browser actually requests, Vite avoids processing files that are not part of the current page. This results in significantly faster server startup and a more efficient development workflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3ec368-6f98-4ded-8f39-8aef7a7d6be1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach debugging a cascading failure in a microservices architecture?', N'Senior', N'I would prioritize observability by analyzing distributed traces to identify the point of origin and the propagation path of the failure. I would then implement circuit breakers to stop the ripple effect, followed by a post-mortem analysis to introduce structural safeguards like bulkheads and automated health-check-based traffic shifting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e3659db-ef12-44ea-bfc4-8af0de66a4a0', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle asynchronous requests?', N'Junior', N'FastAPI is built on top of Starlette and uses the async/await syntax to handle concurrency. This allows the server to process multiple requests simultaneously without blocking the main execution thread, which is efficient for I/O-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d4ec927-97c3-40a3-aa4d-8af15a11c41f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Is component-level state possible in SolidJS?', N'Senior', N'Yes, but it works differently than React; components in SolidJS are only executed once during initialization. State is defined as signals within that scope, which remain in memory even after the component function returns, serving as closure-based reactive values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22791eff-f320-4a0d-a096-8af4c021f8ce', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the x-data directive do?', N'Intern', N'The x-data directive is used to declare a new component scope in Alpine.js. It initializes the component''s state by defining an object of properties that can be accessed by other directives within that element and its children.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c39e9ae-3aa7-496d-8874-8af7e1d2aee0', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the primary role of Flask in a web application?', N'Junior', N'Flask is a micro-framework designed to be lightweight and modular. It provides the essential tools to handle HTTP requests, route URLs to functions, and return responses, leaving architectural decisions like database ORMs or form validation to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'591900d5-8354-4a02-a947-8afad88a7ee3', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the significance of the ''App'' object in Fiber?', N'Fresher', N'The App object is the entry point of the Fiber application. It is used to define routes, register middleware, configure settings, and start the HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53433859-66df-4bda-b5d4-8afae6e51aaf', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle component state compared to React?', N'Fresher', N'Preact handles state in a way very similar to React, using the useState hook or class-based state. The logic for updating and re-rendering components based on state changes follows the same standard pattern as React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf064bbb-41ce-41bc-aaa7-8afeb32079fc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix achieve high-performance request routing?', N'Senior', N'Actix uses a sophisticated internal routing tree that matches paths using efficient pattern matching rather than linear scans. This architecture allows the framework to handle complex URL structures with minimal performance degradation as the number of routes grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc1007ba-d95a-40e6-9af4-8b0076ec7926', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are Vendor-Prefixes?', N'Intern', N'CSS vendor prefixes, also sometimes known as or CSS browser prefixes, are a way for browser makers to add support for new CSS features before those features are fully supported in all browsers. Example: transition property CSS prefixes The major browsers use the following prefixes: * -webkit- (Chrome, Safari, newer versions of Opera, almost all iOS browsers including Firefox for iOS; basically, any WebKit based browser) * -moz- (Firefox) * -o- (old pre-WebKit versions of Opera) * -ms- (Internet Explorer and Microsoft Edge)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dee06f40-e83b-411b-a6a4-8b04cef8301c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'A microservice is experiencing intermittent latency spikes. How do you approach the root cause analysis?', N'Middle', N'I start by reviewing distributed tracing logs to identify the specific component causing the delay. I then investigate resource utilization metrics like CPU throttling or memory pressure, and finally check for external dependencies or network congestion that might be causing blocking operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e57db9b-4e76-4093-b6de-8b05a8a256fa', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is meant by the Atomicity property?', N'Fresher', N'Atomicity ensures that a transaction is treated as an ''all-or-nothing'' unit. If any part of the transaction fails, the entire transaction is aborted, and the database is rolled back to its state before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b519d784-8240-407f-92ff-8b0861ce9e12', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of Flask configuration files?', N'Junior', N'Configuration files allow developers to manage settings like secret keys, database URIs, and debug modes outside the main logic. This keeps sensitive information secure and makes it easier to change settings between development and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7399cd7f-1df9-4662-b3ee-8b08a9b79a54', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript engine''s event loop prioritize microtasks versus macrotasks, and why does this matter for rendering performance?', N'Senior', N'The event loop processes all pending microtasks, such as promises and mutation observers, immediately after the current task and before the next rendering cycle. Macrotasks like setTimeout or UI events are processed one at a time in subsequent iterations. Overloading the microtask queue can block the main thread and delay frame painting, leading to perceived UI unresponsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e766b82-60b3-405f-bdf3-8b0a07819371', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What architectural trade-off is involved in using ''Annotation'' or ''Attribute'' based metadata for configuration?', N'Senior', N'Attributes allow for co-locating metadata directly with the code, which improves developer productivity and readability. However, they require the framework to parse reflection data at runtime, which can be slower than static configuration files, though this is often mitigated by caching the parsed metadata in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b2f606c-c0fe-4293-90f2-8b0c76e0f116', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of an Interface in TypeScript.', N'Fresher', N'An interface is a way to define a contract for the shape of an object within the code. It specifies the properties and methods an object must have without providing the implementation details, which helps ensure consistent data structures across an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f54a316-5c81-45c4-8851-8b0ec815e2ac', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What happens if you use a React-only library in Preact?', N'Junior', N'If the library relies on specific React internals that are not present in Preact, it may fail or behave unexpectedly. The ''compat'' layer helps resolve most of these issues, but some highly complex libraries may still experience compatibility gaps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beed4690-f9ca-451e-ba26-8b142863946a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off when selecting a programming language for a new project?', N'Intern', N'Choosing a language involves balancing execution speed, developer productivity, and ecosystem support. A language like C++ offers high performance but takes longer to write, while Python offers high productivity but may be slower at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4fd5653-19d0-499b-9a73-8b15bb1682c9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is it important to use connection pooling with Rocket''s Managed State?', N'Middle', N'Because Rocket is asynchronous and handles many concurrent requests, opening a new database connection for every request would quickly exhaust database resources and create latency. Connection pooling allows the application to reuse a set of pre-established connections, significantly improving scalability and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc0d4f3-5f74-42b2-aa0f-8b181cad22a0', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is ACID compliance, and how does it relate to NoSQL?', N'Intern', N'ACID refers to Atomicity, Consistency, Isolation, and Durability. While traditional relational databases are strictly ACID-compliant, many NoSQL databases prioritize performance and availability, sometimes opting for a model called BASE.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cf297fb-0e70-4e6e-b87e-8b1929b431f6', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the significance of Hono''s zero-dependency policy?', N'Middle', N'The zero-dependency policy ensures that the framework is lightweight, secure, and easy to maintain. It minimizes the risk of supply-chain attacks and helps avoid version conflicts that often plague frameworks with deep dependency trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'711e7491-3b1a-47fc-a309-8b1a1af935a2', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support React''s Virtual DOM concept?', N'Junior', N'Yes, Preact uses a virtual DOM to optimize UI updates. When state or props change, Preact creates a new virtual DOM tree, compares it to the previous one, and applies only the necessary changes to the actual browser DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aca34350-c389-4042-be39-8b1a93132069', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you determine the appropriate granularity for breaking a monolith into microservices?', N'Senior', N'I focus on Domain-Driven Design, identifying bounded contexts where internal logic is highly cohesive and external dependencies are minimized. I would avoid premature optimization by starting with larger modules and splitting them further only when independent scaling, deployment cycles, or team ownership requirements justify the added operational complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2405c11a-88c0-4700-8ce1-8b1eb8d3c9d8', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s ''form actions'' pattern over traditional REST or GraphQL API endpoints for data mutations?', N'Senior', N'Form actions allow for progressive enhancement, enabling the application to function even before JavaScript is fully loaded or executed. This pattern centralizes state mutation logic within the route itself, reducing the need for separate API layers and simplifying synchronization between the server-side state and UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd95352d-b5c3-4dcb-8944-8b1ee8beb551', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS media queries contribute to a mobile-first design strategy?', N'Middle', N'Mobile-first design involves writing CSS for small screens by default and using media queries to add complexity as the screen width increases. This reduces the amount of code mobile devices need to parse and ensures a baseline experience that is performant across all hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3197ff34-f302-4212-86c3-8b1ef1d25e61', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of a Transaction Log?', N'Intern', N'A transaction log is a file that records all changes made to the database before they are permanently written to the data files. It is essential for recovery, allowing the system to undo uncommitted transactions or redo committed ones after a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
