INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ea3b42e-60eb-4e78-931b-8b28fa84dc76', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs of choosing a microservices architecture over a monolith?', N'Middle', N'Microservices offer better scalability, independent deployability, and technology flexibility but introduce significant operational complexity in networking, distributed tracing, and consistency. A monolith is easier to develop and test initially but can become a bottleneck as the team and codebase grow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec795d1f-81e2-4b17-b83e-8b2a0026d96d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of ''Security by Design''.', N'Middle', N'Security by design means integrating security controls into the software development lifecycle from the initial requirements phase rather than treating it as an afterthought. It shifts security left, ensuring that architectural decisions and code are inherently resilient to threats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
