INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee2bcfa8-9d90-42dc-8648-8b2fddd1750f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the trade-offs of using Ruby''s Global Interpreter Lock (GIL) in a multi-threaded application.', N'Middle', N'The GIL ensures that only one thread executes Ruby code at a time, which simplifies memory management and prevents race conditions for internal data structures. While this makes thread-safe programming easier, it limits the ability of CPU-bound tasks to utilize multiple cores, making it less effective for high-compute parallel processing compared to I/O-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
