INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb95b330-23ad-4971-97f1-8b5866b620f3', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the significance of the PHP ''yield'' keyword in memory-constrained applications.', N'Middle', N'The yield keyword allows a function to act as a generator, which produces values one at a time during iteration rather than creating a large array in memory. This is highly effective for processing large datasets or files, as it keeps the memory footprint low regardless of the input size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64268ab5-2da4-4aa1-b710-8b598c3d2813', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the ''gossip protocol'' and its importance for cluster management.', N'Senior', N'The gossip protocol is a peer-to-peer communication method where nodes periodically exchange state information with a random set of neighbors. This decentralized approach allows the entire cluster to converge on a view of node membership and health without a centralized master, ensuring fault tolerance and scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e29f820a-4cf3-4e63-b44a-8b5ac6478cfa', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of introducing a new technology or framework to the stack?', N'Middle', N'I add an ''innovation tax'' or learning curve factor to the estimate for the initial tasks. This accounts for the time required to set up tooling, learn best practices, and perform necessary experimentation before the team reaches peak productivity with the new tool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10451e63-0e6d-47f5-8306-8b5aec0b4c0a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle images and fonts?', N'Junior', N'Webpack handles these static assets through loaders or asset modules. These tools either copy the files to the output directory and provide a path to them or inline the assets as data URIs within the bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c45f25cd-32f8-4d6f-ad15-8b5cf51d022d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do lifetimes prevent dangling references in Rust?', N'Middle', N'Lifetimes are annotations that describe how long a reference remains valid. The compiler uses these to ensure that no reference can point to a memory location that has already been deallocated, effectively preventing use-after-free errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5380a5c-10cc-439c-a8b7-8b5dcd59b8f1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is Axum considered ''ergonomic''?', N'Intern', N'Axum is considered ergonomic because it utilizes Rust''s type system to handle complex tasks like data extraction and type conversion automatically. This reduces boilerplate code and allows the developer to focus on writing business logic rather than parsing HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8e52460-ff78-44c7-8df0-8b5fcc18e5a7', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI support WebSocket communication?', N'Middle', N'FastAPI treats WebSockets as first-class citizens, providing a WebSocket class that can be used in path operations. It allows you to handle persistent, bidirectional connections asynchronously, which is ideal for real-time applications like chat or live dashboards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'446f8e97-88de-4634-8926-8b63c084a56a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the architectural difference between Swift''s static dispatch and dynamic dispatch.', N'Senior', N'Static dispatch occurs at compile-time, allowing the compiler to perform inlining and direct function calls, which significantly improves performance. Dynamic dispatch uses vtables or witness tables to resolve calls at runtime, enabling polymorphism at the cost of execution overhead and reduced optimization opportunities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
