INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31a0ea94-a488-41bc-8eb5-8b7788802221', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Describe the security considerations for an API dealing with sensitive PII.', N'Senior', N'Security must be implemented in depth: enforce TLS 1.3, use OAuth 2.0 with OIDC for authentication, and implement fine-grained RBAC or ABAC. Additionally, ensure sensitive data is encrypted at rest, masked in logs, and that the API implements strict input validation to prevent injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3aa72f3f-0e1e-4b62-9a72-8b7928173177', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin manage context cancellation when a client disconnects prematurely?', N'Senior', N'Gin wraps the standard library''s request context, meaning that if a client closes the connection, the context will receive a cancellation signal. Senior developers should check this context in long-running operations to stop unnecessary work, thereby freeing up resources for other pending requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a954bb71-78be-42a4-b5ff-8b7a18b06af4', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the concept of technical debt to a non-technical person?', N'Fresher', N'Technical debt is like taking out a loan to get a feature out faster today, which will eventually need to be paid back with interest in the form of extra cleanup work. If you never pay it back, it becomes harder to build new features later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f34f8b5-9058-477d-9216-8b7c8f155991', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the JIT (Just-In-Time) compiler in relation to Tiered Compilation?', N'Senior', N'Tiered compilation allows the JIT to initially generate unoptimized code for rapid startup and then re-compile ''hot'' methods with advanced optimizations later. This approach balances the need for fast application responsiveness with the demand for peak execution performance in long-running services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'264c9a32-1fe4-4c64-a1d1-8b801209e1ed', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is ''Prop Drilling'' and how does Redux solve it?', N'Intern', N'Prop drilling is the process of passing data through multiple layers of components that do not need the data themselves. Redux solves this by allowing any component to access the global state directly via a provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'805af057-05fb-46e5-98a8-8b828fecaaba', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s small bundle size?', N'Fresher', N'The small bundle size ensures that the framework has a minimal cold start time. This is critical for serverless functions where startup speed directly impacts the latency perceived by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'683f7b23-62ed-4538-9921-8b833b64c03f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''declare'' keyword?', N'Intern', N'The declare keyword is used to tell the compiler that a variable or function exists somewhere else, usually in a JavaScript file or a third-party library. It allows TypeScript to recognize these external entities without providing an implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e1582c5-ec32-4da6-8b3a-8b85fd76b644', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What impact does Ruby''s ''Copy-on-Write'' (CoW) friendliness have on scaling multi-process applications like Puma or Unicorn?', N'Senior', N'CoW allows worker processes to share memory pages with the master process until they are modified, significantly reducing the total memory footprint when spawning many workers. However, Ruby''s frequent object allocation and GC-induced heap modifications can trigger early page copying, effectively reducing the efficacy of CoW in high-load scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa955edf-254a-44fb-91a4-8b8a4f386593', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the architectural benefits of using a ''Facade'' pattern in an Angular application with NgRx?', N'Senior', N'The Facade pattern abstracts complex state management logic away from components, providing a simplified API for the UI to consume. This creates a decoupling layer that allows developers to change underlying state implementation, such as switching from NgRx to a simpler signal-based approach, without refactoring the components themselves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ec6e3bb-f72d-4338-acf0-8b8b5bffd9f6', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle message ordering guarantees in a partitioned messaging system?', N'Senior', N'Ordering is typically guaranteed only within a single partition, requiring producers to use a consistent hashing key to ensure related messages are always routed to the same partition. If global ordering is required, you must sacrifice horizontal scalability by using a single-partition queue, which becomes a significant performance bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'215f9b2c-e554-4143-89e9-8b8b714cc4ef', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you handle multiple classes in Tailwind if they conflict?', N'Junior', N'Tailwind applies classes in the order they appear in your HTML. If two classes attempt to set the same CSS property, the one defined later in the class string will typically take precedence, though it is best practice to avoid conflicting utility classes on the same element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
