INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40ff5dbd-2317-4bbd-b786-8b934535bf49', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When would you choose a ''Columnar'' database over a ''Row-oriented'' database?', N'Senior', N'Columnar databases are optimized for analytical (OLAP) workloads where queries aggregate large datasets across few columns. Row-oriented databases are superior for transactional (OLTP) workloads that require fast retrieval or modification of individual records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4277ca19-1855-4cd5-9078-8b940bd3bfa9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle ''split-brain'' scenarios?', N'Middle', N'Elasticsearch prevents split-brain by requiring a quorum of master-eligible nodes to form a cluster. If a network partition occurs, the side with fewer than the required number of master-eligible nodes will stop electing a master, ensuring data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
