INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b40a9d73-5d40-4cd3-857d-8bbbb548f514', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What happens if you use a utility class that does not exist in Tailwind?', N'Intern', N'If you use an invalid class name, it will simply be ignored by the browser, and the element will not receive that specific style. If you are using JIT mode, Tailwind will not generate any CSS for a class that it does not recognize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e984b97-bbcd-430b-835b-8bbcf627bfb2', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why should you prefer HTTPS over HTTP for API communication?', N'Middle', N'HTTPS encrypts the data in transit, protecting sensitive information like credentials and user data from interception. It also provides identity verification for the server, ensuring that the client is communicating with the intended destination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c26290f-2017-4fae-9bd2-8bbeffd8f6dc', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of an index in a database?', N'Intern', N'An index is a data structure that improves the speed of data retrieval operations on a table. It works similarly to an index in a book, allowing the database to find rows without scanning the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7358f5ac-9b12-4d83-be66-8bbf112f74f5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between the ''button'' type=''submit'' and a standard ''input'' type=''submit''?', N'Middle', N'A ''button'' element provides more flexibility because it can contain HTML content like icons or nested elements, whereas an ''input'' element is a self-closing tag that only accepts text values. In terms of functionality, both can submit a form, but the button element is generally preferred for modern UI development due to its rich styling capabilities. Both should always have their type explicitly defined to avoid unintended form submissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c331fc2c-15f7-40e5-ac2d-8bbf56cda20b', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''rel=preload'' link relationship improve page performance?', N'Middle', N'Preloading informs the browser that a specific resource is needed for the current page and should be fetched with high priority before the browser discovers it in the normal parsing process. This is particularly useful for critical assets like fonts, hero images, or essential CSS files. By reducing the time until these resources are available, you can significantly improve metrics like First Contentful Paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b81ac3c9-95e6-48cd-af2c-8bc05c2baa16', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of the ''mobile-first'' approach in Tailwind?', N'Fresher', N'The mobile-first approach ensures that your default styles are optimized for small screens, and you only add complexity for larger screens. This results in cleaner code and improved performance on mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd5bd56f-fc36-4874-9615-8bc2cd8c9d62', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of ExecutionContext in NestJS?', N'Intern', N'ExecutionContext represents the context of the currently processed HTTP request. It contains information about the request, response, route handler, and other details. ExecutionContext is often used in custom decorators, guards, and interceptors to access and manipulate request-related information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4175ed3-c63f-4b65-b3b5-8bc54033a75c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the architectural considerations when choosing between On-Demand and Provisioned capacity modes?', N'Senior', N'Provisioned mode is cost-effective for predictable workloads where you can accurately forecast usage and reserve capacity. On-Demand mode is ideal for unpredictable, spiky traffic patterns where capacity planning is difficult, though it generally carries a higher cost per unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdc3e8d4-61ee-499b-83a3-8bccf8c0dae9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage your time when you have multiple competing priorities?', N'Junior', N'I prioritize tasks based on their urgency and impact on the business or team, often using a list or a project management tool. I communicate these priorities to my manager to ensure my focus aligns with the team''s current goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34b4c149-e85d-41e1-91b7-8bcda6fa458d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is Quarkus considered ''Developer Joy'' focused?', N'Intern', N'It is considered developer-focused because it provides features like hot-reloading in Dev Mode, easy-to-use extensions, and minimal configuration requirements. These features remove common friction points, allowing developers to focus on writing business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05325862-cba0-40c5-a8e2-8bd0f6bae995', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the impact of frozen string literals on memory management in modern Ruby?', N'Senior', N'Enabling frozen string literals ensures that string literals are created once and reused, significantly reducing object allocation and pressure on the garbage collector. This is a critical optimization in high-throughput applications where string creation is a frequent operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999fb2e4-a54e-43ef-8e4f-8bd7c2a20ac7', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you handle ''thundering herd'' problems during system recovery?', N'Senior', N'Implement exponential backoff with jitter in client-side retry logic. This prevents a massive surge of concurrent requests from overwhelming a recovering service, allowing it to stabilize before accepting full traffic load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49322b4a-8e5d-4891-abda-8bd94c65277b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the performance implications of ''Function Inlining'' in Swift?', N'Senior', N'Inlining replaces a function call with the actual code of the function, eliminating the overhead of setting up a stack frame and jumping to a new memory address. While this can significantly improve speed, it increases the binary size and can lead to instruction cache pressure if overused. Swift''s compiler uses heuristics to decide when to inline, balancing performance gains against binary size constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea26e422-414b-4df1-a3b8-8bd9f6c4d3e3', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Fairing'' in Rocket?', N'Intern', N'A fairing is a piece of middleware that hooks into the lifecycle of a Rocket application. Fairings allow you to perform actions during events like application launch, request reception, or response generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce19bb20-caae-499b-bc63-8bdbc48506f9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB''s ''Adaptive Capacity'' feature function during traffic spikes?', N'Senior', N'Adaptive capacity automatically rebalances partition throughput when a specific partition is under-utilized, allowing it to borrow capacity from other under-performing partitions. This allows the system to handle ''hot keys'' more gracefully without immediate throttling, provided the total table throughput is sufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24de6ed6-7bfd-46c2-b8cf-8bde7177bc9c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you determine if a trade-off decision is reversible?', N'Intern', N'A reversible decision is one where the system can return to its previous state without significant data loss or business disruption. Engineers should prioritize reversible designs so that if a chosen trade-off proves to be incorrect, the system can be adapted without major cost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
