INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa0d01be-7a08-4a78-803b-8be08e1fbb18', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis manage memory allocation to avoid fragmentation and system-level OOM errors?', N'Senior', N'Redis relies on jemalloc''s efficient memory management and provides configuration options to limit total memory usage. It is critical to set ''maxmemory'' appropriately and monitor the ''used_memory'' metrics to ensure the system does not trigger operating system OOM killers during peak loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
