INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbe9bec3-ec80-433a-a1cd-8be862f59801', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the scalability of a team versus the scalability of the codebase?', N'Senior', N'I consider Conway''s Law and evaluate if the current architectural boundaries support independent work streams. I estimate the overhead of team communication versus the modularity of the code, recommending structural changes to reduce cross-team dependencies as the organization grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'206d975c-547a-4c2c-b910-8be8c6720c1f', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do PHP''s ''opcache.validate_timestamps'' settings affect production performance?', N'Senior', N'When enabled, the engine checks the file modification time of every script to see if it needs recompilation, which involves expensive filesystem stat calls. Disabling this in production ensures that the engine never checks the disk, maximizing performance at the cost of requiring a manual cache flush after code deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
