INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9979a7a-9e5c-4872-932c-8bed75240798', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary difference between Fiber and the standard library ''net/http''?', N'Intern', N'The standard library uses a design that can be slower due to memory allocation patterns, while Fiber utilizes Fasthttp to minimize garbage collection overhead. Fiber is specifically optimized for high-performance requirements and provides a more developer-friendly API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f95695ae-b60d-499e-bcb3-8bf03090a191', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of the ''Registry'' in Phoenix and how does it assist in process discovery?', N'Senior', N'The Registry is a local, process-based key-value store that allows for mapping processes to specific keys. It is used in Phoenix to find processes associated with a user or resource without relying on a global name registry, enabling high-performance, process-level concurrency management while avoiding global bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
