INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61ea0a21-bdbe-41fc-baff-8bf481a01dff', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the significance of the event loop in a FastAPI application.', N'Middle', N'The event loop is the engine that manages asynchronous task execution in a single thread. In FastAPI, it continuously polls for I/O completion and switches tasks, which allows the application to handle thousands of concurrent requests by never idling while waiting for external resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b37e8b28-5fc7-4520-a960-8bf60c0c5041', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass color functions?', N'Intern', N'Sass provides built-in color functions that allow you to modify colors programmatically, such as lightening, darkening, or adjusting the saturation of a color. These functions are useful for creating consistent color palettes throughout a design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'178cd3b7-8a8d-4c15-8a6c-8bfb207fa30f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Event Loop'' handle I/O operations?', N'Senior', N'JavaScript performs I/O operations asynchronously using internal OS-level bindings (like libuv). When an I/O task completes, a callback is pushed to the task queue, and the event loop executes it once the call stack is clear, ensuring the main thread remains unblocked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea7cf7f1-b98d-4726-869e-8bfbb52a23aa', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is the order of execution in Qwik different from React?', N'Senior', N'In React, execution starts from the root and propagates down to children during hydration. In Qwik, execution is ''demand-driven,'' starting only when an event occurs and only for the specific handler associated with that event.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b515dda-d0f0-446b-b678-8bfc942b302d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When implementing logging and monitoring, what is the trade-off regarding granularity?', N'Middle', N'High-granularity logging provides deep insights into system behavior, which is invaluable for debugging, but it increases storage costs and can degrade application performance. You must balance the need for comprehensive observability with the impact on system overhead and the difficulty of filtering through excessive noise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cd0c1e5-c72c-464a-9d90-8bfcf16d3206', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle ''transitive dependencies'' in a module graph?', N'Senior', N'Webpack recursively traverses the dependency tree, ensuring that all transitive dependencies are resolved and included in the bundle. It manages version conflicts through its resolution algorithm, which typically respects the dependency requirements defined in the package manager''s lockfile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b81aa79-2500-4c80-9e40-8bfdaf41dbe6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut optimize HTTP serialization?', N'Middle', N'Micronaut uses compile-time introspection to generate serializers for Jackson, bypassing the need for reflection. This significantly increases the throughput and reduces the CPU overhead for JSON processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'048cf542-6e32-47be-8f3b-8bff9f32396a', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the role of the Sass compiler?', N'Fresher', N'Since browsers cannot understand Sass syntax, the Sass compiler is a tool that translates Sass files into standard CSS files. This process ensures that the resulting code is compatible with all web browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73a2e1e5-5080-4950-a32a-8bffedaee88d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s caching system work with multiple drivers?', N'Middle', N'Laravel provides a unified API for various caching backends like Redis, Memcached, or file storage. You can switch drivers in the configuration without changing your application code, allowing for flexible scaling based on environment needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb2c2c7c-2556-4ce8-b2e1-8c031df9a9bf', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the advantages of Hono''s ''HonoClient'' for frontend developers?', N'Middle', N'The HonoClient provides a type-safe way to interact with the backend by mirroring the server''s API structure. It allows frontend teams to call backend endpoints as if they were local functions, reducing integration bugs and streamlining the development cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a349513-931a-4270-98ef-8c062a0fc8d0', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does ''sizes'' attribute in ''img'' tags help with responsive image optimization?', N'Senior', N'The sizes attribute tells the browser how wide the image will be displayed before the CSS is fully parsed, enabling the browser to make an informed decision on which source to download from the srcset. This prevents the browser from downloading high-resolution images for small displays, significantly optimizing data usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c81db1c-d1b2-4f2d-8cb9-8c082b78e322', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the ''CAP Theorem'' and its implications for database selection.', N'Senior', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. Database designers must decide whether to prioritize immediate consistency or system availability during network partitions based on the application''s business requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8ad822a-7e89-4db7-8281-8c0b4af7b95a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the benefit of a centralized store?', N'Intern', N'A centralized store eliminates the need to pass data through multiple layers of components, a problem known as ''prop drilling.'' It allows any component in the application to access the data it needs directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73ed82b7-16e4-4599-b83c-8c0faae850a4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s ''Router'' handle route matching compared to traditional regex-based routers?', N'Senior', N'Axum uses a trie-based routing mechanism to match URL paths efficiently. This approach provides O(N) complexity relative to the number of segments, ensuring high performance even in applications with thousands of complex, nested routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6941da4b-45ae-479d-8076-8c0fda634091', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift favor protocol-oriented programming over inheritance?', N'Middle', N'Protocol-oriented programming allows for horizontal composition of behavior rather than rigid vertical class hierarchies. This reduces code duplication and avoids the complexity of diamond-shaped inheritance patterns, making the codebase more modular and testable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edf745c7-f9a9-4d1b-87a0-8c13119d31c9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the risks of using the sizeof operator on a pointer?', N'Middle', N'Using sizeof on a pointer returns the size of the pointer variable itself, which is typically 4 or 8 bytes, rather than the size of the data it points to. This is a frequent source of bugs when programmers mistakenly expect it to return the total size of the allocated memory block or the size of an array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
