INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb9a743d-6828-470e-8498-8c1484e536ca', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Describe the impact of Flask''s routing order on performance and collision handling.', N'Senior', N'Routes are evaluated in the order they are registered in the URL map; if overlapping patterns exist, the first match wins. For high-traffic applications, keeping the routing table optimized and ensuring more specific routes are defined before generic ones prevents unexpected route mismatches and reduces lookup overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85f4326a-660d-4729-a8ba-8c14a1f4412d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the benefit of caching at the application level?', N'Middle', N'Application-level caching reduces the need to query the database repeatedly for frequently accessed data, significantly lowering response times. It also reduces the load on the database layer, allowing the system to handle higher volumes of traffic with lower latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66e604ba-fa1b-4ea4-b7a8-8c18decd8042', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the benefits of using Redis Sorted Sets compared to standard Lists?', N'Middle', N'Sorted Sets associate a score with every member, allowing for efficient range queries, ranking, and ordering operations based on the score. Lists are better suited for simple queues or stacks where order is determined by insertion time and position, but they lack the ability to query elements by a specific value or score range.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e69c515-2d02-4e65-b12a-8c190e50b323', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between Redis and Memcached?', N'Intern', N'While both are in-memory data stores, Redis supports more complex data structures like lists and sets, whereas Memcached is limited to simple key-value pairs. Additionally, Redis offers better built-in persistence options than Memcached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5b0abe6-cd2e-400d-aee2-8c1aa0d14272', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the +layout.server.js file?', N'Fresher', N'The +layout.server.js file is used to fetch data for a layout that should be available to all child routes. It runs on the server and provides common data, such as user authentication status or site settings, to the entire layout hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
