INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8e18884-7df9-42da-821a-8c2058f27f64', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the main features of Java?', N'Intern', N'Java''s robustness makes it stand out with its powerful features. Core Features of Java 1. Platform Independence: Write once, run anywhere (WORA) through Java Virtual Machine (JVM). 2. Object-Oriented: Emphasizes objects and classes, promoting encapsulation, inheritance, and polymorphism. 3. Strong Typing: Variables are strongly typed, reducing ambiguity and potential for errors. 4. Security: Offers a secure platform with features such as a bytecode verifier and a security manager. 5. Automatic Memory Management: Centralized memory allocation and automatic garbage collection, reducing the risk of memory leaks. 6. Concurrency: Supports multi-threading, enabling concurrent execution and efficient multitasking. 7.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c27b82b3-fc87-4852-91b3-8c211e629686', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the Phoenix ''assets'' directory?', N'Intern', N'The assets directory stores static files like CSS, JavaScript, and images. Phoenix uses build tools to process these files so they can be served efficiently to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed58f154-9384-4030-95d3-8c21f126174a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the architectural implications of the ''Zero-Overhead Principle'' in C++?', N'Senior', N'The principle states that what you don''t use, you don''t pay for, and further, what you do use, you couldn''t hand-code any better. Architecturally, this forces language features like exceptions and RTTI to be implemented such that they impose no performance penalty unless explicitly enabled or triggered, often shifting costs to binary size or compilation time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'927cdd76-9f43-4ede-a12a-8c2217f274c7', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does the ''prerender'' export do in an Astro page?', N'Junior', N'The prerender export is used to explicitly tell Astro whether a page should be built at build-time or rendered at request-time. This allows developers to mix and match between static and dynamic rendering strategies within the same project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44f72818-991e-49a7-8b3c-8c23a7556076', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro have built-in support for Markdown?', N'Fresher', N'Yes, Astro has first-class support for Markdown and MDX. This allows you to write your content in easy-to-use formats while still having the full power of Astro components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90e546bc-23d2-4844-b1c0-8c2458ce2e18', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens when an action is dispatched?', N'Intern', N'The action is passed to the root reducer, which evaluates the action type and determines how to update the relevant part of the state. The store then returns the new state, which is used to update the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c1f37cb-54d8-49de-af6b-8c273a7fb753', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between a property and a field?', N'Junior', N'A field is a direct variable of a class, while a property is a specialized member that provides a flexible mechanism to read, write, or compute the values of private fields. Properties allow for logic, such as validation, to be executed during access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'460fb81d-c85f-4beb-9c7e-8c28512aaf0d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the role of an index in MongoDB?', N'Fresher', N'Indexes in MongoDB support the efficient execution of queries. Without indexes, MongoDB must perform a collection scan to select documents that match the query, which is significantly slower as the data volume grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd324dece-d6eb-4c36-b08b-8c2b356749d8', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of Form Validation in AdonisJS?', N'Intern', N'Form validation ensures that data submitted by users meets specific criteria before being processed by the server. AdonisJS provides a validation module to check inputs against rules, returning errors if the data is invalid or missing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f5e9b73-1d0a-4a85-a116-8c2b9b3d6019', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a cache in a web application, and what is a potential drawback of using it?', N'Fresher', N'A cache stores copies of frequently accessed data to speed up response times and reduce server load. The potential drawback is that users might see stale or outdated information if the cache is not cleared or updated correctly when the underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c31364f0-a98e-4693-9857-8c2c83bfd4a0', N'954a0331-deff-4399-b588-96f39fec001d', N'What are Angular elements?', N'Intern', N'Angular elements are Angular components packaged as custom elements (a web standard for defining new HTML elements in a framework-agnostic way). Angular Elements host an Angular component, providing a bridge between the data and the logic defined in the component and the standard DOM APIs, thus, providing a way to use Angular components in non-Angular environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c382a474-bfc3-4803-a45b-8c3021d7bac7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you pass data to a component in Ember?', N'Fresher', N'Data is passed to components using arguments. These arguments are defined by the parent component and are accessed within the child component''s template or backing class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37d90755-fb35-4791-8d40-8c322e49b34b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What does it mean for a SolidJS component to be a ''Function''?', N'Intern', N'A component in SolidJS is simply a function that returns a JSX element. Because it only runs once, the component logic acts more like a setup configuration rather than a template rendering engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7cddf06-61d3-45b5-8de0-8c349879b201', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is database sharding and when is it necessary?', N'Middle', N'Sharding is the process of splitting a single logical dataset across multiple database instances to distribute the load. It is necessary when the dataset size or the write/read throughput exceeds the physical capacity of a single server or cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'935ae3bb-9415-4b16-b191-8c3798fda19a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you prioritize multiple bugs reported at the same time?', N'Intern', N'I would prioritize bugs based on their impact on users and the severity of the issue, such as whether it causes data loss or complete system failure. Issues affecting the most users or critical business functions are typically addressed before minor cosmetic bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'423e1fc0-de67-4c40-b4ab-8c39e7c5d618', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What approach do you take when logs are missing or suppressed during a critical production incident?', N'Senior', N'I shift focus to metrics, infrastructure telemetry, and network-level packet analysis to infer system state. I look for patterns in traffic volume, error codes at the load balancer level, and resource utilization spikes to reconstruct the sequence of events without relying on application-level logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7439c336-2e3f-45bc-926b-8c3a57bdabad', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP autoloader mechanism impact application performance at scale?', N'Senior', N'Autoloading introduces filesystem I/O overhead every time a class is referenced for the first time. In large-scale applications, using optimized composer class-map generation is critical, as it replaces dynamic filesystem lookups with a static, pre-calculated hash map, drastically reducing the number of stat calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dd251bc-6d4d-4bbf-a297-8c3aadc85e1b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you handle database transactions in NestJS, and why are transactions important in certain scenarios?', N'Fresher', N'Database transactions in NestJS can be handled using the TypeORM package. Transactions are important when you want to ensure data integrity. If a series of database operations need to succeed or fail together, transactions can ensure that if any operation fails, all changes are rolled back and the database remains in a consistent state. This is particularly important in scenarios such as financial operations, where it''s crucial that either all parts of a transaction are completed or none of them are.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3f990d5-850b-4d3a-a7da-8c3abb08027b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why do some NoSQL databases abandon ACID transactions in favor of BASE?', N'Senior', N'NoSQL databases often prioritize high availability and horizontal scalability over strict ACID compliance. The BASE model (Basically Available, Soft state, Eventual consistency) allows for significantly higher throughput and lower latency by relaxing the requirement that every node must be consistent at every instant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26721e34-89dc-4557-bedb-8c3d806475a8', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the role of the ''effect'' function in the Vue 3 reactivity core.', N'Senior', N'The effect function is the fundamental unit of reactivity that tracks dependencies during execution. When a reactive property is accessed within an effect, the dependency is collected; when the property changes, the effect is re-triggered to update the UI or perform side effects, forming the basis for computed properties and watchers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
