INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'577b5ead-d132-4f1d-93d3-8c3f45a81036', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a collection in MongoDB?', N'Intern', N'A collection is a grouping of MongoDB documents, which functions similarly to a table in a relational database. Collections do not enforce a rigid schema, allowing documents within them to have varied structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13b030a3-a759-4beb-aaa2-8c406862cf21', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When presented with two conflicting architectural requirements, how do you decide which one to prioritize?', N'Middle', N'I map each requirement to the core business objectives and analyze the downstream impacts of neglecting either. I then facilitate a discussion with product owners to clarify the trade-offs, opting for the solution that provides the most value while minimizing long-term technical risk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a44aba2-3251-497f-97fd-8c410921d62b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a header-only library and a compiled library?', N'Middle', N'A header-only library provides all implementation in header files, allowing the compiler to inline code and perform better optimizations across translation units. A compiled library hides the implementation and reduces compilation time for the user, but limits the ability of the compiler to perform cross-file optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c4734b4-6de1-44de-9489-8c424028599a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you use the ''picture'' element instead of just an ''img'' tag for responsive images?', N'Middle', N'The picture element allows developers to define multiple image sources based on media queries or file formats. This enables art direction, where different versions of an image are shown at different breakpoints, or the delivery of modern formats like WebP to supported browsers. It prevents downloading unnecessary high-resolution assets for smaller screens, improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0c7c31e-255f-42c0-9c91-8c433dbf2e16', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a Template in Ember.js?', N'Fresher', N'Templates are files written in Handlebars syntax that define the structure of the user interface. They allow developers to declaratively describe the HTML, using helpers and bindings to dynamically display data from the underlying components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd75f7bcc-08f4-4b07-8b42-8c453c1f2e2a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it generally recommended to avoid using the ''global'' keyword in PHP?', N'Middle', N'The global keyword creates hidden dependencies and makes code harder to test, debug, and maintain by introducing unpredictable state changes. It breaks encapsulation principles, as any part of the application can modify global variables at any time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80e130b0-c538-4be3-bb4a-8c45c1b50a7e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the role of ''Bloom Filters'' in NoSQL database architectures.', N'Senior', N'Bloom filters are space-efficient probabilistic data structures used to quickly determine if an element is definitely not in a set or possibly in it. In databases like LSM-tree based systems, they prevent unnecessary disk reads by skipping SSTables that do not contain the requested key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
