INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c57491-57f9-473d-ba60-8c54c7d20614', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the scalability risks associated with jQuery''s global namespace pollution?', N'Senior', N'jQuery attaches itself to the global window object, which creates potential conflicts in complex applications or when integrating multiple third-party libraries. This lack of modular encapsulation makes it difficult to isolate dependencies and manage versioning in large-scale enterprise environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8468a93-c954-4338-bf92-8c56a122c35c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When building a new API, how do you reason about versioning strategies?', N'Senior', N'I prioritize backward compatibility to minimize client impact. I prefer URI versioning for major, breaking changes that require significant logic shifts, while utilizing header-based versioning for non-breaking iterations that allow for a smoother transition for API consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee81609c-34e1-41c2-96e0-8c56d1192bad', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If you are stuck on a problem for a long time, at what point should you ask for help?', N'Intern', N'You should ask for help after you have clearly defined the problem, exhausted your initial research, and attempted a few logical troubleshooting steps. Providing a summary of what you have already tried demonstrates initiative and helps the colleague assist you more efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
