INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0594a101-c6e7-421b-9888-8c5c505d308a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is meant by ''Eventual Consistency'' in Cassandra?', N'Fresher', N'Eventual consistency means that while data may not be consistent across all nodes immediately after a write, all replicas will eventually reach the same value. It allows the system to prioritize availability and speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'810c8bec-cb77-43ea-9529-8c5cc4c50211', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your approach to troubleshooting a service that experiences periodic ''connection reset'' errors under moderate load?', N'Senior', N'I would investigate the connection pool configuration to ensure the application isn''t hitting maximum connection limits or experiencing aggressive connection timeouts. Additionally, I would inspect the load balancer and firewall logs for idle timeout settings or TCP RST packets sent due to resource exhaustion in the underlying network stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f78a432f-ec3e-417b-b5e5-8c5db04b65e0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are Nuxt components and where should they live?', N'Intern', N'Components are reusable UI pieces that help keep your code clean and modular. In Nuxt, these should be placed in the components directory, which allows them to be automatically imported without needing manual import statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fed292c-70ae-4750-a1cc-8c604accbd87', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain why cross-shard joins are considered expensive.', N'Middle', N'Cross-shard joins require fetching data from multiple physical servers, aggregating the results, and performing the join operation in the application or middleware layer. This increases network latency and consumes significant memory compared to local joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
