INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93187afb-1105-485d-a7ec-8c65a9485850', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''final'' keyword beyond preventing subclassing?', N'Senior', N'The final keyword acts as an optimization hint for the compiler by guaranteeing that a class or method cannot be overridden. This allows the compiler to devirtualize calls, effectively converting dynamic dispatch into static dispatch. This reduces the overhead of vtable lookups and allows for aggressive method inlining.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94cf796c-566a-44e3-b2f1-8c6616fa2352', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the benefit of using a TTL (Time-To-Live) index?', N'Middle', N'A TTL index automatically removes documents from a collection after a certain amount of time or at a specific clock time. This is highly efficient for managing transient data like session logs, cached items, or event streams without requiring manual cleanup scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15314ad5-c18e-4c92-a382-8c67a77859ff', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''fastify-plugin'' utility?', N'Fresher', N'The fastify-plugin utility is used to wrap plugins so they can share their decorators and hooks with the parent application. It prevents the creation of a new encapsulation context, allowing the plugin to modify the parent''s server instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87c62f0a-31b2-48e8-a7ea-8c67f48662f8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to keep the environment parity between development and production when troubleshooting?', N'Middle', N'Environment parity ensures that the infrastructure, configurations, and network settings are as similar as possible, which prevents issues that are specific to one environment. If configurations differ, a bug might be hidden or exacerbated by the differences in container orchestration, resource limits, or dependency versions. Maintaining parity significantly reduces the time spent investigating infrastructure-related discrepancies during incident response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f202d122-a4be-403d-b75f-8c687e97b279', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are NestJS Pipes and what are their two main use cases?', N'Middle', N'Pipes act as a transformation layer between the incoming request and the route handler. Their primary use cases are data transformation, such as converting a string ID to an integer, and data validation, ensuring incoming payloads match a required schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f101696-b57b-44dd-9e59-8c6ac2c4b1de', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What architectural patterns facilitate the implementation of A/B testing in Astro?', N'Senior', N'A/B testing is best handled via edge middleware, where the request is analyzed to determine the variant and the response is modified accordingly before it reaches the browser. This prevents layout shifts and ensures that the server delivers the correct version of the content, maintaining consistency for the user throughout their session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95a00527-b27d-481d-b61b-8c6db63bbf68', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Discuss the trade-off of Kotlin''s ''non-nullable'' types in terms of reflection-heavy frameworks.', N'Senior', N'Kotlin''s strict type system can conflict with reflection-heavy Java frameworks that expect nullable types by default, often requiring the use of specific annotations to ensure correct behavior. While this provides a more robust development experience, it can create friction when integrating with legacy systems or frameworks that rely on runtime inspection of types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b867be9a-28e1-402c-b8df-8c6dc7cbf50e', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Describe the function of the '':is()'' and '':where()'' pseudo-classes.', N'Middle', N'These pseudo-classes allow developers to group multiple selectors together, reducing the need for repetitive code. The primary difference is that '':is()'' takes the specificity of the most specific selector in its argument list, whereas '':where()'' always has a specificity of zero. This makes '':where()'' extremely useful for building base styles that are easy to override.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5afa0bf5-b8d7-4f9a-bcf3-8c6f3aa8e7b6', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of Rocket''s ''Managed State'' and how does it handle concurrency?', N'Senior', N'Managed State allows developers to inject thread-safe resources, such as database pools or configuration objects, into the application state. Rocket ensures that these resources are accessible across different request handlers while enforcing Rust''s safety guarantees to manage concurrent access correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91ae2d14-a26f-4f4e-a747-8c710332ce33', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is an ''Option'' type and why is it preferred over null?', N'Junior', N'An ''Option'' is a container that represents the presence or absence of a value, using ''Some'' if a value exists or ''None'' if it is missing. It forces developers to explicitly handle the empty case, which helps prevent null pointer exceptions at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f01aafe4-2ce8-4005-af8f-8c74d7d41604', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix require JavaScript to function?', N'Intern', N'Remix is designed to work even if JavaScript is disabled in the user''s browser. It uses standard HTML forms and links, ensuring that the application remains functional for all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54ad8f0a-2a2e-450a-8465-8c75d89e40cf', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between prioritizing performance or readability in your code?', N'Junior', N'Readability should generally be the priority to ensure the code is maintainable by the team. Performance optimizations should only be pursued if profiling confirms a significant bottleneck, as premature optimization often makes code unnecessarily complex and harder to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86a293b5-9a44-448a-9e88-8c7672d0b459', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is a CSS media query?', N'Junior', N'A media query is a feature that allows you to apply different CSS styles based on the characteristics of the device, such as screen width, height, or orientation. It is the fundamental tool for creating responsive designs that adapt to different screen sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9244486b-1c69-448c-972d-8c778e23118f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket considered a ''Type-Safe'' framework?', N'Fresher', N'It is type-safe because it leverages Rust''s compiler to ensure that the code handling requests is logically consistent with the data types being passed. It eliminates many common runtime errors by catching them at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28cf0ce2-1200-4c8d-a283-8c7899dfb6f0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you gather requirements for a new task?', N'Fresher', N'I start by asking what the desired end state is and who the target user will be. I try to understand the constraints and potential dependencies to ensure my approach is aligned with the overall project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac5e8450-7481-4c01-8c8a-8c798c3098ae', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What steps do you take when a performance issue is caused by a cold cache?', N'Middle', N'I would analyze the cache hit/miss ratio to confirm the hypothesis that requests are bypassing the cache. To mitigate the impact, I would implement warm-up strategies for the cache before traffic spikes occur or during deployment. Additionally, I would review the cache invalidation logic to ensure that keys are not being evicted prematurely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f6bb6d1-b1e8-4da4-aa96-8c79d8c7c2ad', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When deciding between microservices and a monolith, what factors dictate your architectural choice?', N'Senior', N'The decision hinges on organizational size, deployment velocity, and team autonomy requirements. A monolith is preferable for early-stage products to minimize operational complexity and latency, while microservices are chosen when independent scaling, technology diversity, and decoupled deployment cycles become necessary to prevent developer bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3da7b156-4bd9-47f0-903d-8c7b9df2b5d9', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between Exception Filters and standard error handling?', N'Junior', N'NestJS provides a built-in exceptions layer that handles all unhandled exceptions across the application. Exception filters allow you to define custom logic for how these errors are caught and formatted before being sent back to the client, providing a consistent API error response structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ece7fffb-eb5b-426d-91c0-8c7ca1c69bba', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'In a distributed system, how do you estimate the impact of adding a new service on overall system latency?', N'Senior', N'I use load testing in a staging environment that mirrors production traffic to measure the P99 latency overhead of the new service. I also calculate the cumulative effect of the increased network hops and dependency chains to ensure the change stays within the defined service level objectives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16c11511-3ffd-487c-b0ce-8c7db1a11783', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the time required to complete a new feature you have never worked on before?', N'Junior', N'I would break the task down into smaller, manageable sub-tasks and research any unfamiliar technologies involved. I would then consult with a senior developer to validate my assumptions and apply a buffer for unforeseen complexities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68f71f42-5dd8-4a41-8a14-8c7e2629d111', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the phases of execution context?', N'Intern', N'The execution context in JavaScript is a data structure that stores the information necessary for executing a piece of code. It includes the code itself, the values of the variables used in the code, and the scope chain. The scope chain is a list of objects that are used to resolve variable names. The execution context has two phases: - Creation phase: In this phase, the JavaScript engine creates the execution context and sets up the script''s environment. This includes creating the variable object and the scope chain. - Execution phase: In this phase, the JavaScript engine executes the code in the execution context. This includes evaluating expressions, assigning values to variables, and calling functions. The execution context is created when a function is called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'101d363c-3a18-4448-8b3d-8c8228806f27', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of application.properties or application.yml?', N'Intern', N'These files are used to define configuration properties for a Spring Boot application. They allow you to externalize settings such as database credentials, port numbers, and feature toggles, making it easy to change application behavior without modifying the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edcd1759-ce13-4596-a6c0-8c827da465ca', N'4c000000-0000-0000-0000-000000000005', N'What is a Content Delivery Network (CDN) and how does it optimize web performance?', N'Middle', N'A CDN is a geographically distributed network of proxy servers that cache static content like images, CSS, and videos closer to the end user. By serving content from a location physically near the user, the CDN reduces network latency and decreases the bandwidth load on the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69dcc96a-42bd-4d15-99ae-8c83255b4b1d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose a client-side rendering approach over server-side rendering for a web application?', N'Junior', N'Client-side rendering offloads processing to the user''s browser, reducing server load and enabling a smoother, app-like transition between pages. However, it trades off initial load time and SEO performance, as the browser must download and execute scripts before content becomes visible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'884cfe3f-6925-4666-82bd-8c83d2294313', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Describe the benefits and drawbacks of using an API Gateway in a large-scale system.', N'Senior', N'An API Gateway provides a centralized point for authentication, rate limiting, and request routing, simplifying client-side interactions. However, it can become a single point of failure and a performance bottleneck if not designed for high availability and low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'692399af-4800-49b6-9a22-8c88d9f0b8c1', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the Garbage Collector in C#?', N'Fresher', N'The Garbage Collector is an automated memory management service that frees memory occupied by objects that are no longer being used by the application. It helps prevent memory leaks and reduces the need for manual memory management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba354f78-536f-47f8-b44a-8c8954ae6a32', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a Transient, Scoped, and Singleton service lifetime?', N'Intern', N'Transient services are created every time they are requested. Scoped services are created once per client request, and Singleton services are created the first time they are requested and then every subsequent request uses the same instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9583cf4-3f4e-4b8c-9383-8c94ad42a6a9', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the performance implications of using JSON serialization/deserialization in Axum?', N'Senior', N'JSON operations are CPU-intensive and can become a bottleneck under high throughput. To mitigate this, developers should use high-performance libraries like Serde with optimized configuration and consider offloading heavy serialization tasks to background threads if the payload sizes are significantly large.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6632a236-94b9-4027-8cb5-8c94ca214a2a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How is data stored in MongoDB?', N'Fresher', N'In MongoDB, Data is stored in BSON documents (short for Bin­ary JSON). These documents are stored in MongoDB in JSON (JavaScript Object Notation) format. JSON documents support embedded fields, so related data and lists of data can be stored with the document instead of an external table. Documents contain one or more fields, and each field contains a value of a specific data type, including arrays, binary data and sub-documents. Documents that tend to share a similar structure are organized as collections. JSON is formatted as name/value pairs. In JSON documents, field names and values are separated by a colon, field name and value pairs are separated by commas, and sets of fields are encapsulated in "curly braces" ({}). Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e6668b7-5caf-48f0-81a7-8c98a0574a6a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle dependency management?', N'Fresher', N'Spring Boot uses a parent POM or a Bill of Materials (BOM) to manage dependency versions. This ensures that all the Spring libraries you use are compatible with each other, preventing version conflict issues common in large Java projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'934940f3-843d-4fc1-870b-8c98b1c1e9ae', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between Static Site Generation (SSG) and Server-Side Rendering (SSR)?', N'Fresher', N'Static Site Generation builds the HTML pages at build time, making them extremely fast to serve from a cache or CDN. Server-Side Rendering generates the HTML at request time, allowing the page to display dynamic or personalized data that changes frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'568bf355-c4f3-4b34-91fa-8c9b6526b4dc', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the ''public'' directory in Symfony?', N'Fresher', N'The public directory is the web root of the application, intended to be the only folder accessible from the browser. It contains the front controller and static assets like images, CSS, and JavaScript files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1788dcaf-8711-421e-940b-8c9bd07e82d8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to follow security best practices?', N'Intern', N'Security best practices protect sensitive user data, maintain system integrity, and prevent unauthorized access or malicious attacks. Failing to follow these practices can lead to data breaches, loss of customer trust, and legal consequences. Prioritizing security from the beginning is much cheaper and more effective than trying to fix vulnerabilities after an incident occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ef0315-4cfa-4403-9d0c-8c9efc7f3646', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle type inference?', N'Fresher', N'Type inference is the ability of the compiler to automatically detect the data type of a variable based on its assigned value. This reduces boilerplate code as developers do not need to explicitly declare the type in every declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a36ba5e2-b2ad-4403-85bb-8c9f62fc06f3', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe how Actix handles potential memory leaks when actors are not properly stopped.', N'Senior', N'If an actor is not explicitly stopped and references to its address persist, the actor and its mailbox remain in memory indefinitely. Actix relies on Rust''s ownership model and the dropping of address handles to trigger cleanup, so failure to clear these references effectively leaks the actor''s state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de5d468b-f3d9-44bb-9559-8ca0086c8d2d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is an Ember Service and when should it be used?', N'Fresher', N'An Ember Service is a long-lived object that is available throughout the application. It is primarily used to share state or logic across different parts of the app, such as user authentication status, shopping cart data, or global configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95d2d229-eed6-47f4-a7fb-8ca1734fff85', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''context'' property in Webpack configuration?', N'Intern', N'The context is the base directory for resolving entry points and loaders from the configuration. It is an absolute path that helps Webpack locate your project files correctly regardless of where the command is run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'846bcbcf-ff2a-4dd2-a040-8ca20201e839', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of version control systems like Git?', N'Fresher', N'Version control allows developers to track changes to the codebase over time, enabling them to revert to previous states if something goes wrong. It also facilitates collaboration by allowing multiple people to work on the same project without overwriting each other''s changes. It provides a history of who changed what and why, which is essential for project maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c1c8ebd-2c49-4d72-aed9-8ca2f6e1fefd', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Is R an interpreted or compiled language?', N'Intern', N'R is an interpreted language. This means that R code is executed line-by-line by an interpreter rather than being compiled into machine code before execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcb3b147-db43-4890-a62b-8ca33f42ad21', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary difference between a relational and a non-relational database?', N'Junior', N'Relational databases store data in structured tables with predefined schemas and use SQL for operations. Non-relational databases use flexible models like documents, key-values, or graphs, allowing for dynamic schemas and easier scaling of unstructured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35f3a8c6-fed1-4df9-b403-8caa25723508', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the preprocessor in C++?', N'Intern', N'The preprocessor is the first step in the compilation process that handles directives starting with a hash symbol. It performs tasks like including header files and replacing macros before the actual compilation of the code begins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781cc652-4eea-4398-8861-8cab71ab5bd9', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary benefit of Svelte being a compiler?', N'Fresher', N'Because Svelte compiles code during the build process, it does not need to ship a heavy framework runtime to the user''s browser. This results in smaller bundle sizes and faster initial page load times for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79c37a2f-ffae-4405-853e-8cabbd373d34', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What impact does the ''Stream'' functionality have on memory usage in Fiber?', N'Middle', N'Streaming allows the server to send data to the client in chunks rather than buffering the entire response in memory. This is crucial for handling large payloads efficiently, as it keeps the memory footprint low regardless of the total data size being transmitted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c715fcdd-f786-4dc6-a84f-8cac006c155a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the ''web::Path'' extractor used for?', N'Fresher', N'The web::Path extractor is used to capture variables from the URL path. It maps segments of the URL to parameters in your handler function, allowing for dynamic routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fffeed3e-09c6-42c2-89c8-8cb20724550f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are indexed access types, and why are they useful?', N'Middle', N'Indexed access types allow you to look up the type of a specific property in another type using a key. They are useful for ensuring type consistency when you need to reference a property type from a large model or configuration object elsewhere in your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34742455-6d7b-44d2-bd66-8cb5afe5093f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'When would you prefer using a custom recovery middleware over Gin''s default recovery mechanism?', N'Senior', N'The default recovery middleware is generic and primarily focuses on logging stack traces. In a production environment, a custom recovery middleware is necessary to integrate with external observability tools, alert SRE teams via PagerDuty/Slack, and provide sanitized, user-friendly error messages that hide internal implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a7753bc-2ed0-4066-8e49-8cb66ddc4930', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''middleware'' directory used for?', N'Intern', N'Middleware allows you to define custom logic that runs before a page or a route is navigated to. It is commonly used for tasks like checking if a user is logged in before allowing access to a protected page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f3bc6fd-fa59-4479-9836-8cb791d118b9', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle context compared to React?', N'Middle', N'SolidJS uses a context API that functions similarly to React''s but is built on the reactive system. Since SolidJS does not re-render components, context updates only trigger downstream effects or memoized values, making it highly efficient for global state propagation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaec4396-a3b6-4ea6-a0f8-8cb90d4c8259', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle feedback from a code or design review that highlights significant flaws?', N'Fresher', N'I view the feedback as an opportunity to improve the quality of my work rather than a personal criticism. I thank the reviewer, ask clarifying questions to ensure I understand their points, and then revise the work accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1305b8ca-99bc-48ef-be51-8cba5e4a9314', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does WiredTiger handle checkpointing?', N'Senior', N'Checkpointing is the process where WiredTiger creates a consistent snapshot of the data and metadata, flushing all modified data to disk. This ensures that the database has a known good state to recover from, balancing the frequency of checkpoints to mitigate the risk of losing too much data while avoiding excessive performance impact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98562326-1cf9-4ade-9bd0-8cbd179f95fb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between comprehensive testing and development speed?', N'Fresher', N'Comprehensive testing ensures higher reliability and fewer bugs, which saves time during maintenance. However, it requires a larger upfront investment in time, which can slow down the initial development cycle compared to testing only core functionalities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78dfc6f3-5903-438e-8196-8cbeeb1139c9', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why does Cassandra not support joins?', N'Intern', N'Cassandra is designed for massive scale and high performance across distributed nodes. Joins would require excessive network communication between nodes, which would severely degrade the performance of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3639c367-9c95-470a-853d-8cbef93d3dfb', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is resumability in the context of Qwik?', N'Intern', N'Resumability is the ability of an application to be serialized on the server and then resumed on the client. It allows the browser to pick up the execution state exactly where the server left off, eliminating the need for hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20a9a8e6-d2b0-42fd-a7bd-8cbf2ecbc495', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is an aggregation pipeline?', N'Intern', N'An aggregation pipeline is a framework for data transformation and analysis. It processes documents through a series of stages, such as filtering, grouping, and sorting, to produce calculated results from the collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69f6be67-9416-4969-ae2c-8cc610d6f5e6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the use cases for dynamic imports', N'Intern', N'Below are some of the use cases of using dynamic imports over static imports, 1. Import a module on-demand or conditionally. For example, if you want to load a polyfill on legacy browser 2. Compute the module specifier at runtime. For example, you can use it for internationalization. 3. Import a module from within a regular script instead a module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'114198e2-7052-4c5d-a4c2-8cc74e9b5fe0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Describe the purpose of the ''useLayoutEffect'' hook and when it is necessary over ''useEffect''.', N'Senior', N'useLayoutEffect runs synchronously after DOM mutations but before the browser paints, making it necessary for measuring DOM elements or making DOM changes that must be visible immediately. Using it unnecessarily can block the main thread and degrade perceived performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dcb5df1-6895-41b0-ba64-8cc8d3058350', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it important to use ''shallow'' or ''triggerRef'' in specific scenarios?', N'Middle', N'These tools allow for fine-grained control over the reactivity system. They are useful when dealing with very large objects where deep reactivity would cause unacceptable performance hits, allowing you to manually trigger updates only when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b20d4aa3-bfb5-4a8b-a2d2-8cc92737d82a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do we need callbacks', N'Fresher', N'The callbacks are needed because javascript is an event driven language. That means instead of waiting for a response, javascript will keep executing while listening for other events. Let''s take an example with the first function invoking an API call(simulated by setTimeout) and the next function which logs the message. As observed from the output, javascript didn''t wait for the response of the first function and the remaining code block got executed. So callbacks are used in a way to make sure that certain code doesn’t execute until the other code finishes execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f8f6404-bfdd-4119-a677-8cca421f078e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle missing values?', N'Intern', N'R uses the symbol NA to represent missing or unavailable data. Most statistical functions in R have parameters to handle these values by either excluding them from calculations or treating them as errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bae8e489-2fb4-488e-9c53-8ccbc4d3bb13', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are various operators supported by javascript', N'Intern', N'An operator is capable of manipulating(mathematical and logical computations) a certain value or operand. There are various operators supported by JavaScript as below, 1. Arithmetic Operators: Includes + (Addition), – (Subtraction), \* (Multiplication), / (Division), % (Modulus), ++ (Increment) and – – (Decrement) 2. Comparison Operators: Includes == (Equal), != (Not Equal), === (Equal with type), > (Greater than), >= (Greater than or Equal to), < (Less than), <= (Less than or Equal to) 3. Logical Operators: Includes && (Logical AND), || (Logical OR), ! (Logical NOT) 4. Assignment Operators: Includes = (Assignment Operator), += (Add and Assignment Operator), –= (Subtract and Assignment Operator), \*= (Multiply and Assignment), /= (Divide and Assignment), %= (Modules and Assignment) 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22ed88b1-c99d-4e22-b94b-8ccdda999985', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are the performance implications of Remix''s nested routing architecture?', N'Senior', N'Nested routes allow Remix to load data for different parts of the page in parallel while only re-rendering the segments that change during navigation. This granular approach reduces data over-fetching and minimizes layout shift compared to monolithic page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40fc39d2-9885-4ddd-8231-8cce3e8ec360', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the benefit of using a composite index?', N'Middle', N'A composite index covers multiple columns, allowing the database to optimize queries that filter or sort by those columns in combination. It is highly efficient for queries where multiple conditions are present, provided the column order matches the query''s filter order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a907d0c7-b39f-49e5-94f3-8ccf5a165a48', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Can you use Axum with different web servers?', N'Junior', N'Axum is designed to be used with the Hyper library. While it is tightly integrated with Hyper''s HTTP implementation, it is built to be a high-level framework that simplifies the complexity of working with raw HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0731c4ef-68a1-4123-b075-8cd0b7763ddb', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of using native ESM during development?', N'Fresher', N'Native ESM allows the browser to load individual files as requested rather than waiting for one large bundle. This drastically reduces the time spent on processing files when the server starts or when a change is made.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc9e1f83-dda8-4880-be76-8cd0c8ed30e8', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is testing critical in a loosely typed language like PHP?', N'Middle', N'Because PHP often allows implicit type conversion, logic errors can easily hide until runtime. Automated testing, including unit and integration tests, provides a safety net that catches regressions and type-related bugs that the compiler might miss. It is essential for maintaining code quality in a rapidly evolving codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54238e50-15b7-477c-9971-8cd258379196', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you perform dependency injection in Python?', N'Middle', N'Dependency injection is achieved by passing required objects or services into a function or class constructor as arguments rather than hardcoding them inside. This decoupling makes code more testable by allowing developers to inject mock objects during unit testing. It is a fundamental pattern for building modular, maintainable systems that are easier to refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'801770ba-bd7f-4424-9d68-8cd2ffb73c0d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between +page.js and +page.server.js?', N'Intern', N'A +page.js file runs on both the server and the client, while a +page.server.js file runs exclusively on the server. The latter is necessary for secure operations like database access or interacting with private API keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0b943b6-0882-4c03-9693-8cd32dfe9e83', N'4c000000-0000-0000-0000-000000000005', N'Describe the impact of database indexing on write-heavy systems.', N'Senior', N'While indexes significantly speed up read operations, they introduce overhead on every write, update, or delete operation because the index structure must also be updated. In write-heavy systems, architects must carefully balance the number of indexes against write throughput requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'301ff74d-2065-4ff7-8a7a-8cd3f40bf73b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of the DynamoDB Accelerator (DAX)?', N'Junior', N'DAX is a managed, highly available, in-memory cache for DynamoDB. It provides microsecond performance for read-heavy workloads by reducing the load on the underlying database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af06bdae-a252-42d9-a88c-8cd59e310c24', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue where users report ''session expired'' errors randomly?', N'Senior', N'I investigate the session storage mechanism and its replication strategy to see if sessions are being prematurely evicted or lost due to node failures. I also check for clock skew between servers if session tokens rely on expiration timestamps, and analyze load balancer stickiness configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e846611-d790-4741-9bd5-8cd62d406e7a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the ''require'' cache impact module loading and memory consumption?', N'Senior', N'Node.js caches modules after the first time they are loaded, meaning subsequent requires return the same object reference. While this improves performance, it also means that module-level state persists for the duration of the process. If a module maintains large internal state, that memory is never reclaimed until the process exits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97414186-a6c7-4e98-905b-8cd63c6a5d22', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro work with other frontend frameworks like React or Vue?', N'Fresher', N'Yes, Astro is a framework-agnostic tool. You can use component libraries from frameworks like React, Vue, Svelte, or Solid within an Astro project by installing the appropriate integrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4fbaaad-9962-4484-a678-8cd7edc34fea', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js''s event handling differ from standard browser event delegation?', N'Senior', N'Alpine simplifies event handling by providing declarative modifiers directly in the HTML, which internally maps to standard event listener attachments. While it uses bubbling by default, it adds an abstraction layer for common patterns like debouncing and preventing defaults. This reduces the need for manual listener management but creates a slight abstraction overhead compared to native ''addEventListener'' calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b278912-c2f0-44de-9bec-8cdbd9466461', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the significance of the ''Future'' class in Dart?', N'Junior', N'A Future represents a potential value or error that will be available at some time in the future. It is a core component of asynchronous programming, allowing the program to continue executing other tasks while waiting for a long-running operation to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'137939d0-977b-438b-b2e1-8cdbfeaa3af1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle middleware execution order?', N'Middle', N'Fiber executes middleware in the order they are registered in the application stack. Middleware functions can control the flow by calling the next function, which passes control to the subsequent handler in the chain or stops the execution if a response is returned early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cee63665-196d-4068-a409-8cdf0fdb1a4f', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the trade-offs of using ''eval'' based source maps versus ''source-map'' in a production environment.', N'Senior', N'Eval-based source maps are fast during development because they rebuild quickly by appending source URLs, but they are insecure and bloat bundle size. In production, ''source-map'' is preferred as it generates separate files, providing accurate debugging without impacting the runtime performance or security of the main bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
