INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2616ec87-0430-467c-8b8c-8ce0e5a97f8b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is ''Cache Invalidation by Versioning'' and why is it preferred over deletion?', N'Senior', N'Versioning involves tagging cached objects with a generation or version ID, allowing the application to simply ignore or overwrite old entries rather than performing expensive deletion operations. This avoids race conditions where a concurrent read might re-populate an old value immediately after a deletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
