INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26ae7b26-3415-43f3-bcb4-8cfd279fdc42', N'4c000000-0000-0000-0000-000000000005', N'How do you handle cascading failures in a microservices architecture?', N'Senior', N'Implement circuit breakers to fail fast when downstream services are unresponsive, preventing resource exhaustion. Additionally, use bulkhead patterns to isolate critical components and implement retries with exponential backoff and jitter to avoid thundering herd problems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0cf23cd-ffa6-45ca-8c74-8d00612a4ba5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the MVC pattern as applied in Phoenix.', N'Fresher', N'Phoenix follows the Model-View-Controller pattern. Models represent data, Controllers handle the business logic and requests, and Views render the templates or data to be presented to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f524a599-95f9-448b-a8ec-8d0062c3fc7b', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How can I get indexed better by search engines?', N'Fresher', N'HTML tags are used to influence the way our pages appear in search results. With the help of certain tags, we can turn regular search snippets into rich snippets, and maybe even into featured snippets. And, as our search snippets get more advanced, they are able to secure better Search Engine Results Pages (SERP) positions and attract more traffic. Here are all the HTML tags that still matter: 1. Title tag: Title tags are used by search engines to determine the subject of a page and display it in SERP. As a rule of thumb, titles that are under 60 characters long will fit on most screens. In HTML, a title tag looks like this: 2. Meta description tag: Meta description is a short paragraph of text used to describe your page in search results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'749269e9-97ae-4277-a472-8d0238d8b080', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''Sidecars'' improve observability in a microservices mesh?', N'Senior', N'Sidecars decouple observability logic from the application code by intercepting all inbound and outbound network traffic. This allows for standardized metrics collection, logging, and tracing across services written in different languages without requiring code changes in the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe7c03d2-660e-4fee-89a3-8d0250ea2070', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Discuss the security implications of Phoenix''s CSRF protection mechanism and why it is essential for stateful connections.', N'Senior', N'Phoenix includes built-in CSRF protection to prevent unauthorized command execution by verifying a unique token on non-GET requests. For stateful connections like Channels, this ensures that the initial handshake is authentic, preventing attackers from hijacking user sessions or initiating unauthorized real-time events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'727f4b93-e56d-4166-9da6-8d03ef18cfd1', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain how the ''yield return'' construct operates in the C# compiler.', N'Senior', N'The compiler generates a state machine that implements the IEnumerable/IEnumerator interfaces. This allows the method to pause execution and return a value to the caller, resuming from the exact point of suspension on the next iteration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bd92292-8911-4211-a705-8d05c2bca4e0', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Scan operation, and why is it generally discouraged?', N'Junior', N'A Scan operation reads every single item in an entire table. It is discouraged for large tables because it is slow and consumes a high amount of read capacity, which can lead to significant performance issues and increased costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1adf5d27-13f6-425f-b0b6-8d0bcd1a498b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you notice your system''s memory usage is slowly climbing over time, what is your systematic approach to finding the leak?', N'Middle', N'I would start by capturing heap dumps at different time intervals to compare object retention patterns and identify which objects are not being garbage collected. I would also profile the application to track allocation hotspots and verify if third-party libraries or internal caches are retaining references indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b047b3a7-dcbf-4640-a009-8d0d2cf52539', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the ''before_request'' hook?', N'Fresher', N'The ''before_request'' hook allows you to register a function to run before each request is processed by the application. This is commonly used for tasks like opening database connections or checking user authentication status before reaching the view function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80c02231-cef1-4be7-9f23-8d1066822da2', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle clock drift during cluster operations?', N'Senior', N'Redis relies on monotonic clocks for internal timeouts and TTL calculations, making it largely resilient to system-level clock drift. However, external operations like snapshot scheduling or synchronized maintenance tasks may be affected, requiring careful NTP management across nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41fb37b2-c8ad-4575-9e68-8d10734bf119', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between ''abort'' and ''redirect'' in Flask?', N'Junior', N'The ''abort'' function is used to immediately stop request processing and return an HTTP error code, like 404 or 403. A ''redirect'' sends the client to a different URL entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87da53a9-c41d-4a17-92c6-8d13239d97db', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does it mean for PHP to be dynamically typed?', N'Intern', N'Being dynamically typed means that the type of a variable is determined at runtime rather than at compile time. You do not need to declare the data type of a variable when you create it, as the engine handles type conversion automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e346d65d-9d63-4f77-8317-8d1514725734', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary difference between Svelte and React?', N'Intern', N'React uses a virtual DOM to reconcile changes, which requires a runtime library to be shipped to the browser. Svelte is a compiler that converts your code into efficient imperative DOM updates, removing the need for a runtime library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da80dac0-4653-4407-90b4-8d15bad230c9', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix''s use of ''GenStage'' or ''Broadway'' address high-volume data ingestion challenges?', N'Senior', N'These libraries implement demand-driven data processing, where consumers request data from producers, naturally applying backpressure. This prevents the system from being overwhelmed by spikes in ingestion, as the rate of consumption dictates the speed at which producers pull data from external sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0704ec7d-1669-4cc2-a18d-8d16b17e1722', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the recommended ordering of methods in component class?', N'Intern', N'_Recommended_ ordering of methods from _mounting_ to _render stage_: 1. static methods 2. constructor() 3. getChildContext() 4. componentWillMount() 5. componentDidMount() 6. componentWillReceiveProps() 7. shouldComponentUpdate() 8. componentWillUpdate() 9. componentDidUpdate() 10. componentWillUnmount() 11. click handlers or event handlers like onClickSubmit() or onChangeDescription() 12. getter methods for render like getSelectReason() or getFooterContent() 13. optional render methods like renderNavigation() or renderProfilePicture() 14. render()', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccc94acb-4faf-45e5-9822-8d1815e42bda', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle circular dependencies?', N'Middle', N'Webpack handles circular dependencies by resolving modules as they are needed. However, if a circular dependency causes an issue, the module might return an empty object, so it is generally recommended to refactor code to avoid these loops to ensure stable execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fd05daa-5625-4355-b819-8d1b8d736b0d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the function of the ''preact/compat'' layer and when should it be avoided?', N'Senior', N'The ''compat'' layer provides an alias for React''s API, allowing existing React libraries and components to run in a Preact environment. It should be avoided when building new projects from scratch, as it increases the bundle size and introduces unnecessary abstraction layers that negate Preact''s primary benefit of minimalism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
