INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a990ecab-dfb0-4015-9e69-8d21bb9b8319', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of the Undo Log in MySQL''s MVCC implementation?', N'Senior', N'The undo log stores the older versions of data rows, allowing the database to perform rollbacks and provide consistent snapshots for long-running read transactions. It is essential for MVCC because it allows readers to access ''historical'' data without blocking writers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c415974-0e2b-4b8d-bd6a-8d267004d9dd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the impact of global CSS styles versus component-scoped styles?', N'Middle', N'Global styles apply to the entire application and can lead to style conflicts and maintenance challenges. Component-scoped styles (encapsulated) ensure that CSS rules are restricted to the component''s template, promoting modularity and preventing unintended side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54370af5-d191-48c6-896c-8d268add5dea', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s build output differ when targeting a Node.js server versus a static site?', N'Senior', N'Targeting Node.js produces a dynamic server application capable of runtime logic, database connections, and SSR. A static build produces an optimized collection of HTML, CSS, and JS files that can be served via a CDN, completely removing the need for a persistent server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9052414-2a3b-4d4c-ab94-8d27a9f20d02', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle read requests?', N'Fresher', N'When a read request is received, Cassandra checks both the memtable and the SSTables on disk to retrieve the most recent version of the data. It then merges these results and returns the response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bb357e9-f447-4267-a2e0-8d2a0532502d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL ''VACUUM'' command?', N'Junior', N'VACUUM reclaims storage occupied by dead tuples that are no longer needed due to updates or deletions. It is essential for maintaining database performance and preventing disk bloat over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
