INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15eb1f60-300a-45b4-92c8-8d2c4e5618b1', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do you implement traits in Scala?', N'Senior', N'In Scala, a trait is analogous to a Java interface, but can also include method implementations and even fields. Traits allow for multiple inheritance, defining a consistent structure for related classes. Syntax A trait is declared using the trait keyword. You can add method and field definitions, along with their possible implementations: Integrating Traits with Classes You can integrate traits with a class through either of these methods: 1. Inherited Methods: These methods can be directly inherited from traits. 2. Overridden Methods: Your class can selectively override any methods from the trait. Code Example: Inheriting Traits Here is the Scala code: In this example, the class Person acquires both methods from the Speaker and Greeter traits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5657530f-ff3c-4be7-8503-8d2dc4b0352a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do ''indices.memory.index_buffer_size'' and shard-level circuit breakers prevent cluster instability?', N'Senior', N'The index buffer size limits the amount of memory allocated for indexing; if exceeded, it triggers a flush. Circuit breakers monitor memory usage at the request and node levels, aborting operations that would exceed the heap limit, thus preventing nodes from crashing due to memory exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67fb03dc-eb66-4e73-81ea-8d31474b0f23', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the function of the Django admin interface?', N'Fresher', N'The Django admin interface is a built-in tool that automatically generates a web-based user interface for managing data in your database. It allows developers and site administrators to create, read, update, and delete model instances without writing custom backend code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e2a2e12-eb1e-4f75-acf1-8d36e654d890', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Facade and a standard class injection?', N'Middle', N'Facades provide a static-like interface to classes available in the service container, offering a concise syntax for accessing services. Standard dependency injection is generally preferred for explicit type-hinting and better testability, as it clearly defines what a class depends on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a394685-685e-4c4a-bf46-8d3bb7073a46', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a Controller and a Provider?', N'Intern', N'Controllers are the entry point that handle incoming HTTP requests and map them to specific logic. Providers are services that contain the actual business logic, data processing, and interaction with databases or external APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaeaad56-2538-48bb-844a-8d3bc24fbf11', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix''s actor model differ from the traditional thread-per-request model in terms of resource utilization?', N'Senior', N'Actix uses an asynchronous, non-blocking model where actors run on a thread pool and process messages sequentially. This significantly reduces the memory overhead associated with thread stacks and context switching, allowing a single process to handle tens of thousands of concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53b11436-6c9a-4789-9f52-8d3be335a3bb', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary purpose of the translog in Elasticsearch, and how does it ensure data durability?', N'Senior', N'The translog acts as a write-ahead log that records all operations before they are flushed to the disk-based Lucene segments. It prevents data loss in the event of a node crash by allowing the system to replay uncommitted operations during recovery, ensuring durability between refreshes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b40fbf72-d6e4-4c69-a8e8-8d3e450f7cf9', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of Body Parsers in AdonisJS?', N'Intern', N'Body parsers are middleware that extract data from the incoming HTTP request body. They convert formats like JSON or form-data into a standard object that can be easily accessed by the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d253f2b-91f5-4562-8e47-8d3ffa559473', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s Fairing system affect the request/response lifecycle?', N'Senior', N'Fairings are middleware-like structures that allow developers to hook into the lifecycle of an application, such as request arrival or response dispatch. They enable cross-cutting concerns like logging, metrics collection, or header modification to be handled consistently across all routes without bloating individual handler logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83024e6b-6a63-40f7-a589-8d4259b05843', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the IHostedService interface, and how does it differ from BackgroundService in modern ASP.NET Core?', N'Senior', N'IHostedService provides a low-level abstraction for background tasks that start when the application host starts and stop when it shuts down. BackgroundService is a convenience base class that implements IHostedService, simplifying the implementation by providing a single ExecuteAsync method to handle the long-running execution loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dc1be98-ae32-4e4c-ad2f-8d43191e82e6', N'954a0331-deff-4399-b588-96f39fec001d', N'How do ''Interceptors'' in Angular''s HTTP client allow for cross-cutting concern management?', N'Senior', N'Interceptors provide a centralized way to modify outgoing requests or incoming responses, making them ideal for tasks like adding authentication tokens, logging, global error handling, or caching. They decouple these concerns from individual service calls, promoting a clean, DRY architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db36b3c4-9abb-4fcd-9efa-8d45aee05e3b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle static assets?', N'Fresher', N'Static assets like images, fonts, and global CSS files are placed in the static folder at the root of the project. Files in this folder are served directly by the web server at the base URL path without being processed by the Svelte compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
