INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7c7af16-fadf-4f93-a0e7-8d4cdac85d52', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What does ''Universal Rendering'' mean?', N'Intern', N'Universal rendering means that the same application code can be rendered on both the server and the client. This provides the fast performance of server-side rendering for the first load and the smooth experience of a client-side application for subsequent navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db6e386d-a8b6-42d3-a6fa-8d50e81beb24', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is ''Load Shedding'' and how is it implemented?', N'Senior', N'Load shedding is the deliberate rejection of traffic when a service is under extreme pressure to ensure the remaining requests are processed successfully. It is typically implemented by dropping lower-priority requests or enforcing strict concurrency limits at the API gateway level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27ef7cc6-6ca0-4c13-bb92-8d535a98ab8e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the trade-offs of using smart pointers versus raw pointers?', N'Middle', N'Smart pointers provide automated memory management and exception safety by handling object lifetimes, which reduces memory leaks. Raw pointers offer slightly better performance due to lack of bookkeeping but require manual management, making them more error-prone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
