INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91e24866-08ff-4eaf-8d0f-8d5abeb6869d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between a monolithic and a microservices architecture in the context of Spring Boot.', N'Middle', N'A monolith is a single deployable unit where all business logic resides in one codebase and process. Microservices split the application into small, independent, and loosely coupled services, each managed by its own Spring Boot instance, which communicate over networks to achieve complex functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31505a25-5152-4450-87a8-8d5de553468a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between a Servlet Filter and a Spring Interceptor.', N'Middle', N'Filters operate at the Servlet container level and can process requests before they reach the DispatcherServlet, making them ideal for cross-cutting concerns like logging or security. Interceptors operate within the Spring MVC context, providing deeper access to the handler methods and view models, making them better for business-logic related request manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
