INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77eb2e5f-46e2-4c8d-805f-8d65b2671799', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between ''presentational'' and ''container'' components in a Redux-heavy app?', N'Middle', N'Presentational components focus on how things look and receive data via props, while container components are concerned with how things work and are responsible for connecting to the Redux store to dispatch actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eec7b140-2d55-43e0-bac6-8d664705f540', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the primary architectural benefit of moving from a shared database to a database-per-service model?', N'Senior', N'The primary benefit is loose coupling, which allows each service to scale, evolve, and choose the storage technology that best fits its specific data access requirements. It prevents tight coupling at the schema level, enabling independent deployments and preventing accidental data integrity issues across service boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59543854-6047-443f-8765-8d6a911b7ca7', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What does ''Fine-grained reactivity'' mean in Qwik?', N'Intern', N'Fine-grained reactivity refers to the ability of the framework to update only the specific parts of the DOM that depend on a piece of data that has changed. Qwik uses this to ensure that re-rendering is kept to the absolute minimum.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df6a4912-7c3a-4147-9a15-8d6c9aa7b8ac', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What happens when a component''s state changes in Lit?', N'Junior', N'When a reactive property changes, Lit marks the component as ''dirty'' and schedules an update. The update cycle then calls the render method and patches the DOM to reflect the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'822ea540-ad08-414b-ab1b-8d70fa4d64aa', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the trade-offs of the fine-grained reactivity model?', N'Middle', N'The primary benefit is performance, as it avoids unnecessary re-renders. A trade-off is that developers must be careful not to destructure props, as doing so breaks the reactive connection, requiring the use of specific getters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'265e6125-99ed-4eac-9400-8d71c8f97869', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the x-effect directive?', N'Fresher', N'The x-effect directive allows you to run a piece of code every time one of its dependencies changes. It is useful for side effects that need to react to state changes, such as logging data or triggering external animations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47f15e22-411f-4ad5-bfbc-8d72a7ae8514', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it recommended to keep utility classes organized?', N'Junior', N'Since you are stacking many classes on single elements, keeping them in a logical order—such as layout first, then spacing, then typography—improves readability for team members. Consistent ordering makes it easier to scan and debug the markup during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be67292b-8d31-45b5-822f-8d7555a7f6e1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why should component names start with capital letter?', N'Fresher', N'If you are rendering your component using JSX, the name of that component has to begin with a capital letter otherwise React will throw an error as an unrecognized tag. This convention is because only HTML elements and SVG tags can begin with a lowercase letter. You can define function component whose name starts with lowercase letter, but when it''s imported it should have a capital letter. Here lowercase is fine: While when imported in another file it should start with capital letter:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2839beb-0315-40ab-913e-8d7771fb1e33', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it important to use semantic HTML elements instead of generic div or span tags?', N'Middle', N'Semantic elements like header, main, and article provide clear meaning to both browsers and assistive technologies like screen readers, which improves accessibility. Furthermore, they help search engines index page content more effectively by defining the structure and hierarchy of the information. This leads to a more maintainable codebase and a better user experience for people with disabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f53715d-77d3-4ae0-9e8f-8d7a9661fe98', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of migration scripts in TypeORM, and how can you create and run migrations in a NestJS application?', N'Intern', N'Migration scripts in TypeORM are a way to manage changes to your database schema over time. They allow you to version control your database schema and apply updates in a controlled manner. This is especially useful when working in a team or when you need to ensure that your database schema is consistent across different environments (development, staging, production, etc.). 1. First, you need to set up TypeORM in your NestJS application. This typically involves importing the TypeOrmModule into your application module and configuring it with your database connection details. 2. After you need to add a migrations path and a cli configuration to your ormconfig.json or ormconfig.js file: 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b824307f-bbb7-49ee-a9a3-8d7ac7f21b7b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is it generally recommended to avoid ''async void'' in ASP.NET Core?', N'Middle', N'Async void methods have limited exception handling and cannot be awaited by the caller, which can lead to application crashes or unpredictable behavior. They should only be used for event handlers, while all other asynchronous operations should return Task or Task of T.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ee5356-5cd6-412e-b24a-8d7afe2a6f72', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the function of the Java Garbage Collector?', N'Intern', N'The Garbage Collector is an automatic memory management process that identifies and deletes objects that are no longer being used by the application. This prevents memory leaks by freeing up space in the heap for new objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e85f2eb5-b074-4856-a8b2-8d7c0746d876', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle CORS (Cross-Origin Resource Sharing)?', N'Junior', N'FastAPI provides a specific middleware called CORSMiddleware that manages which origins, methods, and headers are allowed to access your API. This is essential for allowing web browsers to securely communicate with your backend from different domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f011ab73-7db5-4d6b-9cda-8d7cecfaf28a', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the concept of ''Graceful Degradation'' and provide an architectural example.', N'Senior', N'Graceful degradation is the ability of a system to maintain limited functionality when parts of the system fail. For example, an e-commerce site might disable personalized recommendations if the recommendation engine is down, while still allowing users to search and purchase products.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30a267af-2c6c-4cc1-b64f-8d7fd5269d79', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the benefit of using ''Codable'' over manual JSON parsing?', N'Middle', N'Codable automates the serialization and deserialization process by leveraging the compiler to generate the necessary mapping logic. This reduces the surface area for bugs and maintenance overhead compared to manual parsing, where field names must be mapped explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb144197-19fd-4b98-b1f5-8d801a025a7f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the difference between a query parameter and a dynamic path segment in Rocket?', N'Junior', N'Dynamic path segments are part of the URL structure itself, defined using angle brackets in the route path. Query parameters are appended to the URL after a question mark and are accessed separately from the path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9647999a-23f7-45b1-a6b1-8d806b09528f', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you achieve exactly-once delivery semantics in a distributed messaging system?', N'Senior', N'Exactly-once delivery requires a combination of idempotent producers, where the system deduplicates messages based on unique identifiers, and atomic transactions between the message broker and the consumer''s state store. Without transactional coordination between the consumer processing the message and the acknowledgement sent to the broker, true exactly-once remains theoretically impossible due to the Two Generals'' Problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff3605e1-17b0-4cf1-8e74-8d80ac57f1b5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is dynamic memory allocation?', N'Fresher', N'Dynamic memory allocation allows a program to request memory from the heap during runtime using functions like malloc or calloc. This is useful when the required amount of memory is not known until the program is executing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'985285ad-e6cb-4ed8-bba9-8d80d2b98458', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle HTTP routing?', N'Intern', N'Fiber uses a high-performance router that maps incoming HTTP request paths and methods to specific handler functions. It supports parameter extraction, wildcards, and grouping to organize complex application endpoints efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8c7c6e9-dafb-4138-b7fc-8d81f82b80db', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Why is it generally discouraged to store large files directly in the Django database?', N'Senior', N'Storing files in a database increases backup times, bloats the database size, and degrades performance due to increased memory usage and I/O pressure. Instead, store files in object storage like AWS S3 and save only the file path or URL in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cdbba50-84ee-479d-9903-8d829aa999ce', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ''Materialized View'' optimize read performance?', N'Middle', N'A materialized view stores the result of a precomputed query physically on disk. It is ideal for complex, resource-intensive aggregations that do not need to be updated in real-time, effectively trading storage space and update latency for significantly faster read access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a94620be-2995-4019-b938-8d82a60782c1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a server is unresponsive, what is your initial approach to diagnose the issue?', N'Fresher', N'I would first verify network connectivity using basic tools to check if the server is reachable. Next, I would examine system resource usage logs to see if CPU or memory saturation is causing the unresponsiveness. Finally, I would check recent service logs for error messages that indicate a crash or hang.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
