INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fe00dac-2d87-4075-9160-8d8731f7cf0a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle navigation compared to standard HTML links?', N'Junior', N'SvelteKit uses a client-side router that intercepts link clicks to prevent a full page reload. This allows for faster transitions, state preservation, and a smoother user experience, only fetching the necessary data for the new page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff55e0d5-3893-43ed-ab12-8d880d631460', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''transpilation'' in the context of Webpack?', N'Junior', N'Transpilation converts modern JavaScript or TypeScript into a version that is compatible with older browsers. Webpack typically uses loaders like ''babel-loader'' to perform this transformation during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d9c501f-2406-458c-9bb5-8d89f61e69b8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do distributed databases manage transaction isolation across partitioned data?', N'Senior', N'Distributed databases typically use a combination of distributed lock managers or multi-version concurrency control (MVCC) coupled with a global transaction manager. By assigning globally unique timestamps, the system can order transactions consistently across multiple nodes, ensuring that read/write operations respect the required isolation level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4a3519a-a3aa-47f3-8ea4-8d8aaeea11ed', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the Service Provider in Laravel''s boot sequence, and how does it influence system initialization?', N'Senior', N'Service Providers are the primary location for bootstrapping application components, including binding services into the container and registering event listeners or routes. The boot sequence is critical because it ensures that dependencies are resolved in the correct order, allowing the framework to prepare the environment before the application logic executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'288d83d8-f091-4ab5-99cf-8d8bf1f65842', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might you choose a batch processing job over a real-time stream processing pipeline?', N'Middle', N'Batch processing is much simpler to implement, test, and debug, making it ideal for data that does not require immediate processing. Real-time stream processing provides immediate insights but requires complex infrastructure, high operational expertise, and is significantly more expensive to run and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e4531bb-0fb5-4be9-9a0e-8d8dd42557b8', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue 3''s ''Teleport'' component affect the component hierarchy and event bubbling?', N'Senior', N'Teleport renders component content into a different DOM node outside the parent component''s DOM structure, but the logical hierarchy remains intact. Event bubbling still follows the logical component tree, meaning parents can still capture events emitted by teleported children regardless of their physical placement in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2823403f-5236-4bd9-b202-8d8fa7828ece', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does ''Consistency'' ensure during a transaction?', N'Junior', N'Consistency ensures that a transaction takes the database from one valid state to another valid state. It maintains all predefined rules, such as constraints, cascades, and triggers, so that data integrity is never compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17454f5d-0824-4705-a96f-8d906cb7429c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'When should you use an Interceptor instead of a Filter?', N'Middle', N'Use an interceptor when you need to modify the successful response body or measure execution time. Use a filter when you need to catch exceptions and format the error response sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7557f343-21fe-4d50-b9f8-8d931ef3d5c5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off involved when deciding between client-side rendering and server-side rendering for a web application?', N'Junior', N'Server-side rendering provides faster initial page loads and better SEO, but it increases server load and latency for subsequent interactions. Client-side rendering creates a smoother, app-like experience after the initial load, but can result in a slower first paint and issues with search engine indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3c7b501-beb2-4c97-ae4b-8d95ef9c066d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it generally discouraged to use jQuery''s animate method in modern development?', N'Middle', N'jQuery''s animate method relies on JavaScript-driven style updates, which can be less efficient than CSS transitions and animations. CSS animations are often offloaded to the browser''s compositor thread, resulting in smoother performance and lower CPU usage compared to script-based animations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef0f108a-8cb9-4981-87b6-8d9994440b04', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the common strategies to optimize slow-running SQL queries?', N'Middle', N'Optimization strategies include ensuring proper indexing on join and filter columns, avoiding unnecessary select statements, and rewriting queries to use efficient join patterns. Additionally, analyzing the execution plan helps identify bottlenecks like full table scans or inefficient sorting operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ce44e40-f1b1-4699-b12c-8d9afae2bf99', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of secret management services like HashiCorp Vault?', N'Middle', N'Secret management services provide a secure, centralized way to store, manage, and audit access to sensitive information like API keys, database credentials, and certificates. They help prevent hardcoded secrets in source code and provide mechanisms for dynamic credential rotation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c57bfd35-cf84-4a37-af52-8d9cc049d184', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do modules impact TypeScript''s global scope?', N'Middle', N'Files in TypeScript are treated as modules if they contain top-level import or export statements, meaning their variables are not accessible globally. Without these statements, files are treated as scripts, and their contents are added to the global namespace, which can cause naming conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'156047f7-97ca-47ed-a000-8da09a40d46c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the advantage of using Actix over a synchronous framework?', N'Intern', N'Actix provides significantly higher concurrency and performance by not blocking threads while waiting for I/O. This allows the application to serve many more concurrent users with fewer hardware resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
