INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7df98fdc-e787-43d6-a78a-8da65142a2c3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your approach to managing technical debt in a fast-paced engineering organization?', N'Senior', N'I advocate for a balanced approach where technical debt is treated as a first-class citizen in the product backlog, allocating a fixed percentage of each sprint toward refactoring. I ensure that debt is clearly documented and prioritized based on the risk it poses to velocity, reliability, and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
