INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2eba216-c06b-4f8d-b2a5-8dc5fea75582', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''balancer'' process affect cluster performance?', N'Senior', N'The balancer monitors the data distribution across shards and migrates chunks to balance the load. While necessary for scalability, the migration process consumes significant network bandwidth and disk I/O, which can negatively impact the performance of production queries during peak traffic hours.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9368060a-d14f-4440-af79-8dc8bf9c01e6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS help maintain a consistent design system?', N'Junior', N'By forcing developers to choose from a shared set of spacing, colors, and typography values defined in the configuration, it ensures visual consistency across the entire project. This prevents the ''magic number'' problem where developers pick arbitrary spacing or color values on every new page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b175845-1085-4331-ad5e-8dca8c82b26c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the trade-offs of using ''READ COMMITTED'' versus ''REPEATABLE READ'' isolation levels.', N'Senior', N'REPEATABLE READ prevents phantom reads using gap locking, ensuring consistent snapshots but increasing the likelihood of deadlocks. READ COMMITTED allows for higher concurrency and fewer deadlocks but does not guarantee consistency across multiple reads within the same transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0595fc37-cf4d-46cf-89f7-8dcecca706d4', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the CatchBoundary or ErrorBoundary in Remix?', N'Junior', N'These components are used to gracefully handle errors that occur during the rendering or data-loading phase of a route. If a loader fails or a route is not found, the framework renders these components instead of crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f354d990-0ebb-4c48-ba37-8dd2a6e20ec0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are regular expression patterns?', N'Intern', N'Regular Expressions provided group of patterns in order to match characters. Basically they are categorized into 3 types, Brackets: These are used to find a range of characters. * [...]: Any one character between the brackets. * [^...]: Any one character not between the brackets. * [0-9]: It matches any decimal digit from 0 through 9. * [a-z]: It matches any character from lowercase a through lowercase z. * [A-Z]: It matches any character from uppercase A through uppercase Z. * [a-Z]: It matches any character from lowercase a through uppercase Z.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc779775-6875-4a65-8cf3-8dd347bb9bfc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you handle middleware in Actix-web?', N'Junior', N'Middleware in Actix-web are components that wrap the request-response cycle. They can be used for tasks like logging, authentication, or modifying headers before the request reaches the final route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d92574e-7946-4f54-9aa5-8dd55d6d8b84', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is CSS?', N'Intern', N'CSS stands for Cascading Style Sheets. CSS is used to define styles for web pages, including the design, layout and variations in display for different devices and screen sizes. CSS was intended to allow web professionals to separate the content and structure of a website''s code from the visual design. CSS can be used for document text styling — for example changing the color and size of headings and links. It can be used to create layout — for example turning a single column of text into a layout with a main content area and a sidebar for related information. It can even be used for effects such as animation. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f4b781-9a23-4301-96d9-8dd60f07b404', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does declaration merging work, and when is it appropriate to use?', N'Senior', N'Declaration merging allows the compiler to merge multiple declarations with the same name into a single definition. It is most commonly used for extending global interfaces or adding custom properties to existing library types without modifying the underlying source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9aff33e3-cef0-4835-931d-8ddd05b45f4c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you scale a database that has a ''write bottleneck'' due to heavy indexing?', N'Senior', N'To address write bottlenecks caused by indexing, you can move indexing tasks to an asynchronous process, reduce the number of secondary indices, or utilize a change data capture (CDC) stream to update external search engines. This allows the primary database to handle simple inserts quickly while offloading the heavy lifting of index maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae003424-1cb1-426f-8f5d-8ddd1e937cb2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs of using R''s ''formula'' interface?', N'Middle', N'The formula interface provides a very intuitive, symbolic way to specify statistical models and plot relationships. However, it relies on non-standard evaluation, which can make it difficult to pass variables programmatically into models without using specific techniques like bang-bang operators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e84d65a3-067c-4b16-bcb5-8dde48f6cace', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite improve development server startup time compared to traditional bundlers?', N'Fresher', N'Traditional bundlers must bundle the entire application before starting the server. Vite starts the server instantly by serving source files over native ESM, only transforming files on-demand as the browser requests them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'767d2c87-826c-431e-a6a3-8ddfb609a07f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'When should you use Buffers versus typed arrays in Node.js for data manipulation?', N'Senior', N'Buffers are a subclass of Uint8Array optimized for binary I/O operations and memory management outside the V8 heap. Typed arrays are more suitable for general-purpose mathematical computations and data structures where direct, predictable memory access is preferred over specialized I/O handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'165766cb-b269-46da-a80b-8de012754723', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the Ruby ''VM'' handle method dispatch for ''protected'' versus ''private'' methods?', N'Senior', N'Private methods in Ruby can only be called in a functional style without an explicit receiver, while protected methods can be called by any instance of the defining class or its subclasses. These visibility rules are enforced at the VM level to maintain encapsulation, though they can be bypassed using metaprogramming techniques like ''send'', which violates the intended architectural boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'841c9c24-29fc-4469-a2da-8de124564aaf', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why use ''private'' or ''protected'' access modifiers in a class?', N'Junior', N'These modifiers control the visibility of class members to ensure encapsulation. ''Private'' members are only accessible within the class they are defined in, while ''protected'' members are accessible within the class and its subclasses, helping to hide internal implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e750672-0b3b-4768-a5f3-8de1db7a21ba', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is Kotlin and why is it used for Android development?', N'Fresher', N'Kotlin is a statically typed, cross-platform programming language that runs on the Java Virtual Machine. It is officially supported by Google for Android development because it is concise, safe, and fully interoperable with existing Java code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bdb7027-c089-4743-b8f0-8de49e59b9a1', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the role of the Redis ''Client-side caching'' feature in high-scale systems.', N'Senior', N'Client-side caching allows applications to store frequently accessed data in their local memory, reducing the network round-trip time to the Redis server. Redis uses a tracking mechanism to notify clients when cached data is modified, ensuring cache invalidation and data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdd5940f-233d-49d1-a707-8de54dfb8b78', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the ''query cache'' and why might it be disabled in modern MySQL versions?', N'Middle', N'The query cache stored the results of SELECT statements to serve identical queries quickly. It was removed in newer versions because it became a significant bottleneck in multi-core systems due to the need for a global mutex lock whenever the cache was accessed or invalidated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8638cb7b-f744-483c-9059-8de867b73f34', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle responsiveness compared to traditional media queries?', N'Middle', N'Tailwind uses a mobile-first approach where utility classes are prefixed with breakpoints, such as md: or lg:. This allows developers to apply styles conditionally based on screen width directly in the markup, which is often faster than writing separate media query blocks in external CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'594e4a45-5f7e-4f6c-b040-8deaa68f90d9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Can you define custom middleware in Gin?', N'Intern', N'Yes, you can create custom middleware by defining a function that accepts the context object as a parameter. This function can then be registered to run globally or on specific route groups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b45b3dd8-309b-46b9-889f-8decde7b76f8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the importance of ''data integrity''?', N'Intern', N'Data integrity ensures that information is accurate, consistent, and reliable throughout its entire lifecycle. It prevents data from being corrupted or altered incorrectly, which is essential for making informed business decisions. If data is unreliable, the systems relying on it will likely produce incorrect or harmful results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83deb0ee-4d13-40e3-8cda-8ded168cf09b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Recipient'' in Actix?', N'Junior', N'A Recipient is a type-erased version of an address that can only send messages of a specific type. It is useful for decoupling components, as a sender only needs to know that the receiver can handle a specific message type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'943a30ec-8b26-4a3b-a7c4-8defb6ab1ffd', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you handle asynchronous providers in NestJS?', N'Middle', N'Asynchronous providers are handled using the ''useFactory'' provider pattern, where the factory function is marked as async. The application will wait for the promise to resolve before completing the DI container initialization, ensuring dependencies are ready before the server starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d88b5dd-6dff-49c3-b302-8df1896f1acb', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of an index in a MySQL database?', N'Intern', N'An index is a data structure that improves the speed of data retrieval operations on a table at the cost of additional storage and slower writes. It functions similarly to an index in a book, allowing the database engine to locate specific rows quickly without having to scan the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dda3b76-e7b3-4d08-85b5-8df1b13d4d20', N'954a0331-deff-4399-b588-96f39fec001d', N'What are Angular Guards and how are they used?', N'Intern', N'Angular Guards are services that implement specific interfaces to control navigation within your application. They are used to protect routes by deciding if a user can activate a route (CanActivate), activate a child route (CanActivateChild), deactivate a route (CanDeactivate), load a lazy-loaded module (CanLoad), or match a route definition (CanMatch). They can also be used to pre-fetch data before a route is activated (Resolve). Guards are typically implemented as injectable services or, from Angular 14 onwards, as functions. They return a boolean (true to allow, false to deny) or a UrlTree (to redirect), or an Observable or Promise that resolves to one of these types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1823ed2-1e80-4901-ab9e-8df7ceeec363', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s DI system prevent dependency cycles, and how should they be addressed?', N'Senior', N'Angular''s DI system does not inherently prevent cycles, and circular dependencies can lead to runtime initialization failures. They should be addressed by refactoring shared logic into a separate service or using a common interface that both services can implement, thereby decoupling them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8595d71-2376-4a09-9dcb-8df7e9a81d71', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi ensure compatibility with third-party Go libraries?', N'Senior', N'Since Chi is built on top of the standard net/http interface, any library that accepts or returns a Handler or HandlerFunc is immediately compatible. There is no need for specialized adapters, which avoids the ''framework lock-in'' common in more opinionated toolsets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a947078-3936-4a7a-ab37-8dfb639e259d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How can Chi’s middleware chain be optimized to minimize latency in a high-throughput backend?', N'Senior', N'To minimize latency, middleware should be placed strategically, ensuring that early-exit logic, such as authentication and rate limiting, occurs before resource-intensive handlers. Additionally, keeping the middleware stack lean and avoiding unnecessary context allocations helps maintain a low per-request overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7f57931-1cc1-4e3d-aaf4-8dfb720246f8', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'When would you choose to use ''fastify-reply-from'' in a microservices architecture?', N'Senior', N'The ''fastify-reply-from'' plugin is designed to act as a highly performant proxy or API gateway. It allows the server to stream responses directly from upstream services to the client without buffering, which reduces latency and memory usage when handling large payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d20e95b-5908-4fef-90e6-8dfc801a93c9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the internal mechanism of Python''s ''with'' statement and how it ensures resource safety.', N'Senior', N'The ''with'' statement leverages the Context Manager protocol, specifically the __enter__ and __exit__ methods. It guarantees that cleanup code, such as closing file handles or releasing locks, is executed automatically even if an exception occurs within the managed block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86df6b73-f669-4e82-937a-8dfd3a7e7b8f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle SEO optimization differently than client-side rendered applications?', N'Senior', N'Astro renders the full HTML on the server, ensuring search engine crawlers receive a complete document immediately. Unlike client-side rendered apps, which may struggle with metadata and content indexing due to JavaScript execution delays, Astro provides an optimal crawlable environment by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70ffefd2-34b5-4327-8593-8dff915da86a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Compare jQuery''s animation queue system with modern CSS transitions and Web Animations API.', N'Senior', N'jQuery''s animation engine runs on the main thread using JavaScript-based timers, which can cause jank during heavy computations. CSS transitions and the Web Animations API are offloaded to the compositor thread, providing significantly smoother performance and better energy efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74b9e14c-7128-45c7-8b7e-8dffe2195d24', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What role does the ''app.Use'' method play in Fiber''s architecture?', N'Senior', N'The app.Use method registers global middleware that executes for every incoming request regardless of the route. This is architecturally significant for cross-cutting concerns like CORS, logging, and panic recovery, ensuring consistent behavior across the entire service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'376f6433-ca0d-4f30-86c1-8e00e033ad96', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the importance of version control in a collaborative environment?', N'Intern', N'Version control allows multiple people to work on the same project without overwriting each other''s changes. It provides a history of modifications, which is essential for rolling back to stable versions if a new change introduces errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fcb4e2c-49eb-4302-aaf4-8e01195e6332', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are environment variables, and why are they used in Node.js?', N'Junior', N'Environment variables are key-value pairs stored outside the application code, typically accessed via process.env. They are used to manage configuration settings such as database credentials or API keys, ensuring sensitive data is not hardcoded in the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3bc1272-ba2c-45ec-a9a9-8e012e629968', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle concurrency compared to the standard Go net/http package?', N'Middle', N'While the standard library spawns a new goroutine for every incoming request, Fiber''s performance-oriented approach relies on optimized buffer reuse to handle many concurrent connections. While it still leverages goroutines, the architecture is specifically tuned to minimize the latency penalties associated with high-frequency allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cea5bda9-dd7a-447a-981f-8e03363b057b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why might you choose to cache at the CDN level instead of the application server?', N'Middle', N'Caching at the CDN level pushes content closer to the end-user geographically, significantly reducing latency and offloading traffic from the origin servers. It is ideal for static assets or public data that does not require personalization per user request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1702afc-f69d-4c9a-b1a5-8e04b60ebe9e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a ''Covered Query'' in MongoDB, and why is it beneficial for performance?', N'Middle', N'A covered query is one where all fields in the query and the projection are present in a single index. Because the database can return the result directly from the index without loading the actual documents from disk, it significantly reduces I/O latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
