INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'178a9b5b-594c-4f82-9f0a-8e05225483f2', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the trade-offs between eventual consistency and linearizability in distributed NoSQL databases.', N'Senior', N'Linearizability provides the strongest consistency model, where every operation appears instantaneous, but it significantly limits availability and performance due to the required synchronization across nodes. Eventual consistency prioritizes high availability and low latency by allowing temporary state divergence, accepting that read operations may return stale data until background synchronization completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
