INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f47d702-222b-4763-af21-8e2d2702391d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Generics in TypeScript, and why are they useful?', N'Junior', N'Generics allow you to create reusable components or functions that can work with a variety of types while still maintaining type safety. They enable you to define a template that specifies the type at the time the component is used, rather than locking it into a single specific type upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
