INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ad497cc-8a61-4dba-b7ad-8e2f48c764a8', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Nitro in Nuxt 3?', N'Junior', N'Nitro is the server engine that powers Nuxt. It handles the server-side rendering, API routes, and deployment, and it is designed to be platform-agnostic, allowing Nuxt to run on various hosting environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4f87f6b-cb9c-4283-827c-8e32d75179dc', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the significance of the ''db_index'' attribute in model fields?', N'Middle', N'Setting db_index=True tells the database to create an index for that column, which significantly speeds up lookups, filtering, and sorting operations. However, it comes with the trade-off of slightly slower write operations and increased disk storage requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79002f2c-343a-4bb9-93bc-8e35aefe27cc', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between synchronous and asynchronous communication?', N'Middle', N'Synchronous communication requires the sender to wait for a response from the receiver before continuing, which can lead to blocking issues. Asynchronous communication allows the sender to continue processing after sending a request, usually via a message broker, which improves system throughput and decoupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81d9a0ec-ead0-478f-a36a-8e3605cbe75b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''transition'' API in SolidJS?', N'Middle', N'The transition API allows you to mark state updates as non-urgent, preventing the UI from suspending immediately. This enables developers to keep the existing UI interactive while new data is being fetched, providing a smoother user experience during navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9ebebad-0928-4340-a2ec-8e374e0cc2ce', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin facilitate API versioning?', N'Intern', N'API versioning is achieved in Gin by using route groups. By grouping routes under a prefix like ''/api/v1'' or ''/api/v2'', developers can maintain multiple versions of an endpoint simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dcfdedb-a410-4222-8e32-8e3a322f8a23', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you send a JSON response in Echo?', N'Intern', N'To send a JSON response, you use the JSON method on the Context object. You provide the HTTP status code and the interface object you want to serialize, and Echo handles the content-type and encoding automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43986b93-b8cc-47ee-867f-8e3a440df4ec', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a query and a cursor in MongoDB?', N'Fresher', N'A query is the operation used to find specific data in a collection. A cursor is the object returned by the query that allows the application to iterate over the result set one document at a time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d4f9ecb-a5e6-4cab-900b-8e3c16fc7f9c', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why does Kotlin favor ''delegation'' over inheritance for code reuse?', N'Middle', N'Delegation allows a class to implement an interface by forwarding calls to an underlying object, promoting composition over inheritance. This approach avoids the fragility of deep class hierarchies and makes code more modular and easier to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb409565-b5e6-40a8-a771-8e3c74ccc579', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the distinction between stack and heap memory critical for avoiding security vulnerabilities?', N'Senior', N'The stack is typically used for local variables and function call frames, making it a primary target for buffer overflow attacks that overwrite return addresses. The heap is used for dynamic memory, where vulnerabilities often involve use-after-free or double-free errors that lead to arbitrary code execution. Understanding the lifecycle and security boundary of these memory regions is fundamental to building robust, exploit-resistant systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7b6f592-8a15-49a3-8ea1-8e3d1601bc58', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''by'' keyword in property delegation?', N'Fresher', N'The ''by'' keyword is used to delegate the implementation of a property to another object. This allows you to extract common property logic, such as lazy loading or observable patterns, into reusable delegate classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29cc26be-6a26-4e1d-b6e3-8e3f78b2fb05', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does ''Multi-Version Concurrency Control'' (MVCC) affect storage requirements?', N'Senior', N'MVCC maintains multiple versions of data rows to allow concurrent read and write operations. This increases storage overhead because old versions must be retained until they are no longer needed by any active transaction, necessitating a background process like vacuuming to reclaim space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec265868-cf1f-435a-84f9-8e411dd51cbf', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the impact of long-running transactions on autovacuum?', N'Senior', N'Long-running transactions prevent the removal of dead tuples that were created after the transaction started, as these tuples might still be visible to that transaction. This forces the table to grow, leading to significant bloat and preventing autovacuum from reclaiming space, which degrades overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8094b7db-7f61-484c-8fc9-8e416296cb3a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the role of the ''Recoverer'' middleware in Chi?', N'Fresher', N'The Recoverer middleware is a standard utility that catches panics during the execution of a handler. It prevents the entire server from crashing and instead returns a 500 internal server error to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b15386b-1a59-403b-8943-8e421cf613c3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is an infinite loop?', N'Intern', N'An infinite loop is a block of code that repeats indefinitely because its termination condition is never met. This usually happens when the loop condition is always true or if the logic meant to break the loop is never triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'104d8c4a-f67b-4ac0-b9dd-8e43042b8849', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is the use of strict types considered a best practice in modern PHP?', N'Middle', N'Strict typing forces the engine to throw a TypeError when a value does not match the declared type, rather than attempting implicit type coercion. This leads to more predictable code, easier debugging, and a reduction in runtime logic errors. It enhances the reliability and maintainability of the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d8ec21f-d543-487c-94f3-8e43062fa962', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you handle a situation where a third-party API integration causes your application to behave unpredictably?', N'Senior', N'I would implement defensive wrappers around the API calls, including strict timeouts, circuit breakers, and comprehensive logging of request and response payloads. I would also analyze the third-party''s status page and historical performance data to determine if the unpredictability stems from their rate limiting, unplanned outages, or malformed data responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba6daff9-1417-4722-95a6-8e43a14e327a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do ''Bloom Filters'' assist in database performance?', N'Senior', N'Bloom filters are probabilistic data structures used to quickly determine if an element is definitely not in a set or possibly in a set. They are used in LSM-tree based engines to avoid unnecessary disk reads for keys that do not exist in specific data files, thus reducing latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d4f6738-d449-427a-80a3-8e44af25b0df', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''Validator'' ensure data integrity in distributed systems?', N'Senior', N'The validator provides a declarative schema-based approach to data sanitization and validation before it reaches the service layer. By enforcing strict schemas at the entry point, it prevents malformed data from propagating through the system, acting as a crucial first line of defense in complex architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f83acae2-8506-4d05-83e6-8e4677b29d8c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the role of the loading.js file?', N'Junior', N'The loading.js file is a special file that automatically creates a React Suspense boundary around your page content. It allows you to show a loading state, such as a spinner or skeleton screen, while the page or nested components are being fetched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8def2ee8-04c4-4bef-85e7-8e46f3ffd25f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a closure in JavaScript, and how/why would you use one?', N'Intern', N'In the book "You Don''t Know JS" (YDKJS) by Kyle Simpson, a closure is defined as follows: > Closure is when a function is able to remember and access its lexical scope even when that function is executing outside its lexical scope In simple terms, functions have access to variables that were in their scope at the time of their creation. This is what we call the function''s lexical scope. A closure is a function that retains access to these variables even after the outer function has finished executing. It is as if the function has a memory of its original environment. Key points to remember: - Closure occurs when an inner function has access to variables in its outer (lexical) scope, even when the outer function has finished executing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'305dec7d-4826-4044-ae96-8e471e0ae46e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle conditional rendering without a Virtual DOM?', N'Middle', N'SolidJS provides built-in components like ''Show'' or ''For'' that manage DOM nodes reactively. These components utilize the framework''s internal tracking to mount or unmount elements only when the underlying condition changes, avoiding expensive re-renders of the entire list or block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'956a441a-1e3a-4ef7-8d04-8e4890601774', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How could you make sure a const value is garbage collected?', N'Fresher', N'In JavaScript, garbage collection is automatically performed by the browser or the JavaScript engine. When a value is no longer being used or referenced, it becomes eligible for garbage collection. In the case of a const value, the same rules apply as with any other value. As long as the const value is not referenced by any other variables or objects in the program, it will become eligible for garbage collection when the variable goes out of scope. Here are some best practices to follow when working with const variables: 1. Only use const when you know that the value should not be reassigned. 2. If you ever want to change the contents of the variable for any reason in the future, then don''t declare it as const. 3. Use let or var instead of const if you need to reassign the value. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0ad2f75-e747-48e0-ae52-8e4a3804adf0', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When working on a team, how do you handle a disagreement about an approach?', N'Intern', N'I would ask for the reasoning behind the other person''s perspective to understand their point of view. I would then present my own logic and suggest testing both approaches on a small scale to see which one performs better, or defer to a lead if a consensus cannot be reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'262081fb-a0dc-4e69-9a47-8e4a8d169e79', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are custom data attributes (''data-*''), and how should they be used?', N'Middle', N'Data attributes allow you to store extra information on standard HTML elements without creating non-standard attributes. They are intended for storing application-specific data that is not visible to the user but needed by JavaScript logic. They should not be used for styling purposes, as that should remain within the domain of CSS classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c51f5dd-4dd3-4447-8ddd-8e4aedacf503', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'In Ruby, is everything considered an object?', N'Fresher', N'Yes, Ruby is a pure object-oriented language where every piece of data, including primitive types like numbers, booleans, and nil, is an instance of a class. This design ensures that all data types can have methods called upon them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fb11f08-adc5-457e-853e-8e4fefbba466', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is it important to use ''MiniCssExtractPlugin'' in production instead of ''style-loader''?', N'Middle', N'The style-loader injects CSS into the DOM via style tags, which is convenient for development but leads to a ''flash of unstyled content'' and forces the browser to wait for JavaScript to execute. MiniCssExtractPlugin extracts CSS into separate files, allowing for parallel loading of styles and better caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed62345f-3ab9-4ccd-af3e-8e50e6b9d3a8', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a transaction in SQL?', N'Fresher', N'A transaction is a sequence of operations performed as a single logical unit of work. If all operations succeed, the transaction is committed; if any operation fails, the entire transaction is rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4a2cd5d-9672-4cb0-b808-8e54492e4412', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''Type Branded'' or ''Opaque Types'' in TypeScript.', N'Senior', N'Opaque types use an intersection with a unique symbol or literal to prevent different types with the same structure from being accidentally swapped. This simulates nominal typing for specific business logic values, such as ID types, ensuring that a UserID cannot be accidentally used where a ProductID is expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5efa98f8-d413-41c0-b619-8e54515956b6', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the role of ''x-cloak'' and why is it essential for user experience?', N'Middle', N'x-cloak is a utility directive used to hide elements until Alpine.js has finished initializing the component. It prevents the ''flash of unstyled content'' where users might see raw template syntax or raw data before the framework processes the directives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bee9950a-e869-4de0-8db5-8e54cccc0884', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary advantage of using a middleware chain in Fiber?', N'Middle', N'Middleware allows for the modular execution of cross-cutting concerns like logging, authentication, and error handling before the request reaches the business logic. By chaining these functions, developers can keep handlers clean and maintain a consistent request pipeline across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a8344b4-d502-43aa-90c5-8e5889e77e65', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the fundamental purpose of trade-off analysis in software engineering?', N'Fresher', N'The purpose is to evaluate competing design options to determine which best satisfies project requirements. Since no solution is perfect, it helps identify the hidden costs or drawbacks of choosing one approach over another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca4000b-7f2c-4be8-94b4-8e59297bf043', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the risks of performing blocking I/O inside an Actix actor?', N'Senior', N'Performing blocking I/O directly in an actor blocks the thread on which the Arbiter is running, potentially stalling all other actors assigned to that same thread. This degrades throughput and can lead to complete system unresponsiveness if the thread pool is exhausted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd67cef72-6482-44cc-a0f3-8e5b0c1fa09c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the advantages of dependency injection in Java applications?', N'Middle', N'Dependency injection decouples the creation of objects from their usage, making the system easier to test, maintain, and configure. It allows for swapping implementations without modifying the code that consumes them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9df75804-8171-4e16-996d-8e5c08624d07', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle graceful shutdowns, and why is this important for zero-downtime deployments?', N'Senior', N'Echo utilizes the standard library''s server shutdown methods to stop accepting new requests while allowing current ones to complete within a specified timeout. This is crucial for preventing dropped connections during rolling updates and ensuring that in-flight database transactions are finished correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51453800-66e0-40a7-8690-8e5f850091f5', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to use TypeScript in create-react-app application?', N'Fresher', N'Starting from react-scripts@3.3.0+ releases onwards, you can now optionally start a new app from a template by appending --template [template-name] to the creation command. If you don''t select a template, it will create your project with base template. Remember that templates are always named in the format cra-template-[template-name], here you only need to fill the [template-name] section. The typeScript can be used in your project by appending --template typescript to the creation command. But if you are using React Scripting between react-scripts@2.1.0 and react-scripts@3.2.x , there is a built-in support for TypeScript. i.e, create-react-app now supports TypeScript natively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64b64313-21ea-495c-b18e-8e601009cd7e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Laravel Events?', N'Junior', N'Events provide a simple observer implementation that allows you to subscribe to and listen for various events in your application. They decouple the code that triggers an action from the code that responds to it, making the application easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ca6be77-93ef-4821-ac88-8e63b4604599', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What does it mean for Hono to be ''minimalist''?', N'Junior', N'Being minimalist means Hono provides only the essential primitives required to build web services, such as routing, middleware support, and context management. It avoids bundling heavy features by default, allowing developers to add only the specific plugins or utilities they need for their project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8996bd4-ea80-4903-a5ab-8e64eb58a196', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is an Elixir process?', N'Intern', N'An Elixir process is a lightweight, isolated unit of execution managed by the Erlang VM. Processes do not share memory and communicate by sending messages to one another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de0676d8-a8ea-4ce0-bea4-8e65e5c0efa0', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''Request Services'' scope in ASP.NET Core, and how is it managed by the framework?', N'Senior', N'The Request Services scope ensures that all services injected during a single HTTP request share the same lifetime and are disposed of once the request completes. The framework automatically creates this scope for each request, ensuring that scoped services are correctly resolved and cleaned up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db96b1cf-6938-40a5-8e79-8e66c84ba700', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''app.vue'' file in Nuxt?', N'Intern', N'The app.vue file serves as the main entry point for your application. It acts as the root component that wraps your entire project and is used for global settings, such as layout wrappers or global styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6731a332-058a-41dc-912f-8e66e9f1b6f3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach troubleshooting when a system appears healthy but users report functional errors?', N'Middle', N'I would investigate the client-side error logs and network traffic captures to see what the user is actually experiencing versus what the backend reports. Often, this reveals issues like silent failures in the UI, client-side validation errors, or mismatched API versions that standard backend monitoring would not catch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29cc043e-ea7c-480b-a2d3-8e68b0c4bf59', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the Cascade layer feature (at-layer) solve specificity wars in large codebases?', N'Senior', N'Cascade layers provide a way to control the priority of CSS rules based on the layer definition order rather than selector specificity. This allows developers to define base styles, component styles, and overrides in a predictable sequence, eliminating the need for overly specific selectors or the use of !important.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5137fa9-66bc-4413-99d3-8e6baaf11758', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the significance of the ''Supersonic Subatomic Java'' tagline in Quarkus?', N'Fresher', N'The tagline refers to the framework''s ability to provide extremely fast boot times and a small memory footprint. It achieves this by shifting much of the heavy lifting, like dependency injection and reflection, from runtime to build time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19cc8ba7-3104-4561-bc37-8e6d170f2f39', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the importance of ''margin of error'' in technical estimation?', N'Fresher', N'Estimation is inherently probabilistic, not deterministic, because unforeseen issues often arise during implementation. Including a margin of error accounts for these unknowns and prevents the project from being derailed by minor setbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b56e3ac-9215-4945-b221-8e72c539d610', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the concept of ''action'' functions in Svelte and their use in building reusable UI logic.', N'Senior', N'Actions are functions that provide a hook into the lifecycle of a specific DOM element, allowing for integration with third-party libraries or custom DOM manipulations. They are superior to components for non-UI logic because they do not require an extra wrapper element and are optimized to run once per element lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bc9ba24-bf38-412b-8104-8e739a22cc12', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How are JSON requests handled in Actix-web?', N'Intern', N'Actix-web uses the Json extractor to automatically deserialize incoming HTTP request bodies into structured Rust objects. It uses the Serde library to perform the conversion from JSON to data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e98669c3-48f5-4917-8de1-8e73bbee9b51', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between data being a plain object and a function in a component?', N'Junior', N'In a component, the data option must be a function that returns a new object. This ensures that each instance of the component gets its own independent copy of the data, preventing different instances from accidentally sharing the same state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8638ede-85da-4d20-af28-8e755b8ab5c8', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What does the ''target'' configuration option do?', N'Intern', N'The target option tells Webpack what environment the code is intended for, such as a web browser or a Node.js server. This ensures that the generated code is compatible with the specific runtime environment''s features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c30c5ae-4ac2-45ef-88a6-8e7d0aeda38f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you decode an URL?', N'Fresher', N'The decodeURI() function is used to decode a Uniform Resource Identifier (URI) previously created by encodeURI(). 1. decodeURIComponent() — decodes a single encoded URI component: 2. decodeURI() — decodes a fully encoded URL, leaving valid URL structure characters intact: Example — reading query params: Modern alternative — use URLSearchParams which handles encoding/decoding automatically:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c35fe98-e47d-4f05-908c-8e7d3ef05b0f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a method reference?', N'Intern', N'If the method existing in the class already does everything that is necessary, then you can use the method reference mechanism (method reference) to directly pass this method. The result will be exactly the same as in the case of defining a lambda expression that calls this method. Example: Method references are potentially more efficient than using lambda expressions. In addition, they provide the compiler with better information about the type, and if you can choose between using a reference to an existing method and using a lambda expression, you should always use a method reference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6431f36-e345-44be-ac5b-8e7d72faccc9', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the architectural considerations for implementing asynchronous patterns in PHP given its synchronous nature?', N'Senior', N'Implementing asynchronous behavior in PHP requires event-loop-based libraries or extensions like Swoole or ReactPHP, which deviate from the standard synchronous execution flow. These solutions allow for non-blocking I/O operations but require developers to manage state carefully, as the environment becomes persistent rather than request-isolated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c40a4a52-3386-446b-a1a5-8e82e1f44704', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the trade-off of using ''lazy'' initialization for singleton properties?', N'Senior', N'Lazy initialization defers object creation until the first time it is accessed, which improves startup time and reduces memory usage for unused objects. The trade-off is the overhead of synchronization in the default thread-safe implementation, which can introduce minor performance costs during the initial access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'063d46a4-d989-4c91-9e64-8e849f824b78', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is ''caching'' critical for API design?', N'Middle', N'Caching reduces redundant processing and database load by serving repeated requests from memory or a CDN. It significantly decreases latency for the user and improves the overall scalability of the API by allowing it to handle more requests with fewer resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0d9c293-3fd8-4cc0-a175-8e8517c7bae6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Describe the role of the ''app.config.ts'' file compared to ''nuxt.config.ts''.', N'Middle', N'nuxt.config.ts is used for build-time configuration that alters how the application is constructed, such as modules and plugins. app.config.ts is for reactive configuration that can be updated at runtime, allowing parts of the application state to be configured without requiring a full rebuild.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ede7b47-5243-4752-9a4b-8e8853586f40', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does it mean for Redis to be ''eventually consistent'' in a master-replica setup?', N'Middle', N'In a master-replica configuration, data is replicated asynchronously from the master to replicas to maintain performance. This means there is a small time window where a replica might serve stale data before receiving the latest updates from the master, requiring the application to tolerate brief inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ffda023-2584-412d-9a9e-8e8aadf1f882', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the significance of the ''Kernel'' in Symfony and how it differs from a traditional monolithic entry point.', N'Senior', N'The Kernel manages the lifecycle of the application, including the initialization of the service container, bundle management, and request handling. Unlike simple scripts, the Kernel provides a structured way to boot the application in different environments, facilitating complex configuration management and middleware-like event processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'746cb372-dacf-4381-a2e4-8e8b91117c58', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Service Providers in Laravel?', N'Intern', N'In Laravel, Service Providers act as the main entry point for registering several components such as view composers, routes, and much more in the application. Key Responsibilities - Registering Services: This includes services such as repositories, interfaces, and any binding within the Laravel service container (App::make()). - Bootstrapping and Configuration: Provides a platform to set up the application''s initial state before it boots up. Categories of Service Providers 1. Application Service Providers: They are specific only to the application and are not a part of the Laravel framework. 2. Framework Service Providers: These are applicable across different Laravel applications and pertain to the Laravel framework itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77005477-1e6b-4345-9a10-8e8fb73152d2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the scope of an Alpine.js component?', N'Intern', N'The scope of an Alpine component is defined by the element carrying the x-data attribute and all of its children. Any data or methods defined in x-data are accessible only within that specific element''s subtree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09ed78fe-a82c-4d24-b4a8-8e8fd4c47add', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the importance of logging and error tracking in a production environment?', N'Junior', N'Effective logging provides visibility into system behavior and helps diagnose issues quickly when they occur in production. Without proper logs, identifying the root cause of a bug becomes a guessing game. It is a critical tool for maintaining system reliability and improving the debugging process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bf89366-4040-4864-b984-8e918a36cf13', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Tail Latency'' affect the design of a large-scale NoSQL cluster?', N'Senior', N'Tail latency refers to the response time experienced by the slowest percentage of requests. In large clusters, this is mitigated by techniques like hedged requests, where a redundant request is sent to a second node if the first does not respond quickly, ensuring consistent performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b05b38b-d039-4e53-9527-8e93b34e7bf6', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Are Preact components compatible with React components?', N'Intern', N'Most Preact components are highly compatible with React, but they are not identical. While the API surface is the same, some advanced React features may require additional libraries like preact-compat or aliases to function correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b2247e1-981c-4cc5-bc12-8e941255a3b1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of middleware in Redux?', N'Junior', N'Middleware provides a way to interact with actions after they are dispatched but before they reach the reducer. It is commonly used for logging, error reporting, or handling asynchronous operations like fetching data from an API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
