INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da26e88e-225f-474d-9e59-8e99301e6422', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''before_request'' hook?', N'Junior', N'The ''before_request'' hook allows you to define functions that run before every incoming request is processed by the view. It is commonly used for tasks like opening database connections or verifying user authentication tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80a4472d-5334-4413-93b6-8e99551d2bf9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Discuss the performance implications of Hono''s ''Smart'' middleware execution.', N'Senior', N'Hono''s middleware is designed to be lightweight and zero-dependency, minimizing the cold start penalty in serverless environments. By avoiding complex wrapper objects and utilizing standard web APIs, it ensures that the execution path remains minimal, which is critical for maintaining sub-millisecond overhead in edge deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9fcb3d5-67ec-4a91-bf22-8e9c5a112ba9', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to create react class components without ES6?', N'Fresher', N'If you don’t use ES6 then you may need to use the create-react-class module instead. For default props, you need to define getDefaultProps() as a function on the passed object. Whereas for initial state, you have to provide a separate getInitialState method that returns the initial state. Note: If you use createReactClass then auto binding is available for all methods. i.e, You don''t need to use .bind(this) with in constructor for event handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6175ba-5781-40dc-9af5-8ea013bbc2af', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of ''nodemon'' during development?', N'Junior', N'Nodemon is a utility that monitors your project files for changes. Whenever a file is modified, it automatically restarts the Node.js application, which speeds up the development process by removing the need to manually stop and start the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c9addb8-cfdc-4255-8fee-8ea231126a09', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it beneficial to define schemas for both request and response in Fastify?', N'Middle', N'Defining both ensures that your API contract is strictly enforced, preventing malformed data from reaching your business logic and ensuring clients receive predictable output. Additionally, Fastify uses response schemas to optimize serialization, leading to faster response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0915a411-1a58-4862-b424-8ea4136fdb84', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Describe the role of the ''mapping'' in an Elasticsearch index.', N'Middle', N'Mapping is the process of defining how a document and its fields are stored and indexed, similar to a schema in a relational database. It determines the data type of each field and specifies how they should be analyzed, which is critical for search accuracy and storage efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57dc4905-fc43-4970-9bdd-8ea5eafb4c68', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you manage complex, shared state across multiple Nuxt pages without polluting global memory?', N'Senior', N'You should utilize a scoped state management pattern using ''useState'' combined with composables to keep state lifecycle aligned with the component tree. For more complex requirements, integrating a dedicated state library with persistence plugins ensures that memory is managed effectively and state is only instantiated when needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fd9b1b3-51e9-4662-8646-8ea832c84ae7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the mechanics of ''Deoptimization'' in V8 and what triggers it.', N'Senior', N'Deoptimization occurs when a speculative optimization, based on assumptions about types or object shapes, is invalidated by the actual runtime data. The engine must discard the optimized machine code, revert to an interpreted state, and potentially re-optimize later, which creates a noticeable performance ''hiccup'' in the execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b594bcbe-6e8e-4f68-a1c7-8eace0c13de3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core achieve high scalability through its asynchronous programming model?', N'Senior', N'ASP.NET Core utilizes non-blocking I/O operations, allowing threads to return to the thread pool while awaiting tasks like database queries or network calls. This prevents thread starvation under high load, enabling the server to handle a significantly higher number of concurrent requests with fewer threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a18c1c5c-c325-427d-b774-8ead5c64f6cd', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the ''Qwik City'' framework and its relationship to Qwik?', N'Senior', N'Qwik City is the meta-framework built on top of Qwik, providing file-based routing, data loading, and layouts. It provides the necessary infrastructure for server-side operations, similar to how Next.js provides the infrastructure for React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a191207-37b4-4ec6-a309-8eae29fb6089', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the benefit of using Ember''s ''Tracked'' properties over traditional observers?', N'Middle', N'Tracked properties provide a more performant and predictable way to handle reactivity by automatically linking state changes to the UI. Observers are often discouraged because they are side-effect prone, harder to debug, and can lead to infinite loops if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5091d89-6295-49b0-b07d-8eb7f35bce8c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the advantages of using the spread operator with arrays and objects?', N'Intern', N'The spread operator (...) in JavaScript allows you to easily copy arrays and objects, merge them, and add new elements or properties. It simplifies syntax and improves readability. For arrays, it can be used to concatenate or clone arrays. For objects, it can be used to merge objects or add new properties. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4898cc98-903e-4f97-9c52-8eb7f95548b3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the advantages of using SvelteKit''s server-side rendering (SSR) compared to client-side rendering (CSR)?', N'Middle', N'SSR delivers fully rendered HTML to the browser, which improves initial load times and ensures that search engines can easily index the content. While CSR is useful for highly interactive dashboards, SSR provides a better experience for content-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ecee58d-062d-4c6b-83a2-8eb859ec2da5', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the difference between Kestrel and IIS when hosting an ASP.NET Core application.', N'Middle', N'Kestrel is a cross-platform, high-performance web server that runs the application directly. IIS is a full-featured web server that acts as a reverse proxy, providing additional management, security, and process monitoring features when hosting on Windows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44ee18d0-93b4-4f0c-9ca4-8ebb97e96e09', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How would you convert a string into an int in Python?', N'Fresher', N'If a string contains only numerical characters, you can convert it into an integer using the int() function. int(''227'') 227 Let''s check the types: type(''227'') type(int(''227''))', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cdef639-2ee9-4f05-9742-8ebc06df62c4', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the impact of using a microservices architecture on testing?', N'Middle', N'Microservices increase testing complexity because they require integration and contract testing to ensure that independently deployed services communicate correctly. Testing must also account for network failures, service discovery issues, and partial system availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a30dbb31-d641-40c9-a06c-8ebd6f4f0e4a', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is it generally recommended to keep business logic out of Phoenix Controllers and move it into separate service modules or contexts?', N'Middle', N'Moving logic into contexts creates a clean separation of concerns, making the codebase easier to maintain, test, and refactor. Controllers should only be responsible for handling HTTP input and preparing the response, while contexts encapsulate the domain logic, allowing it to be reused by other interfaces like CLI tasks or background jobs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e043db26-f0fe-42c6-8606-8ec09dc38c58', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage database connections in a reactive environment?', N'Middle', N'Quarkus uses reactive drivers that do not block the event loop while waiting for database responses. This ensures that the application remains responsive even when performing I/O-intensive operations, preventing thread exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
