INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b4d05d0-4767-447d-bb52-8ec402c7338d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s ''Content Security Policy'' (CSP) integration protect against common web vulnerabilities?', N'Senior', N'Ember includes built-in support for CSP, which restricts where resources can be loaded from and prevents the execution of inline scripts. By enforcing these policies, Ember helps mitigate Cross-Site Scripting (XSS) attacks, ensuring that the application only interacts with trusted domains and origins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f320d4f0-af23-49f5-aaaa-8ec4f6a2961c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Does NoSQL support joins?', N'Intern', N'Most NoSQL databases do not support joins in the same way relational databases do. Developers are typically encouraged to denormalize their data by nesting related information into a single document or structure to avoid the need for joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12da844e-76c5-432e-a2e4-8ec59b685cee', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate the quality of a solution after you have finished a task?', N'Fresher', N'I check if the solution meets all original requirements and verify that no new issues were introduced in related areas. I also reflect on whether the logic is clean and easy for others to follow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92501d26-3245-4cb4-be12-8ec6751165cf', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI automatically document APIs?', N'Intern', N'FastAPI uses the OpenAPI specification to automatically generate interactive API documentation. It creates Swagger UI and ReDoc interfaces, which allow developers to view and test the API endpoints directly in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6aa78848-9472-4c1e-a546-8ec6b67f4bbe', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is an Exception in C#?', N'Intern', N'An exception is an error condition that occurs during the execution of a program. C# uses a try-catch-finally block mechanism to gracefully handle these unexpected situations and prevent the application from crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c77de454-6902-4329-b283-8ec8aed12ed0', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the concept of ''exactly-once'' processing in a distributed system.', N'Middle', N'Exactly-once processing ensures that even in the presence of system failures, a message is effectively processed by the consumer once. This is notoriously difficult to achieve and usually requires coordination between the messaging system''s offset management and the consumer''s local state storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2696c1f9-f134-4b3c-af72-8ecb51eb5587', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ASP.NET Core Data Protection API handle key management in a load-balanced environment?', N'Senior', N'The Data Protection API provides a secure way to protect sensitive data by managing cryptographic keys, which can be persisted to shared storage like network drives or database tables. This allows multiple instances of an application to encrypt and decrypt data consistently without needing to know the underlying key details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eab9ac45-10c0-4d82-8136-8ecbc8963b46', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why Node.js?', N'Fresher', N'- Unified Language: Utilizing JavaScript both on the frontend and backend brings coherence to development efforts, potentially reducing debugging time and enabling shared libraries. - NPM Ecosystem: The NPM repository offers myriad open-source packages, empowering rapid development and feature expansion. - Rapid Prototyping: Express, a minimalist web framework for Node.js, and NPM''s wealth of modules expedite early application development and testing. - Scalability: Cluster modules, load balancers, and Microservice Architecture aid in linear, on-demand scaling for both simple and intricate applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d5b1c92-7f68-4999-a0df-8ecc0a97c6ff', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle static files?', N'Junior', N'NestJS can serve static files using the ''@nestjs/platform-express'' package. You typically configure this in the main.ts file by using the ''useStaticAssets'' method, which maps a specific path to a directory containing your files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b881c97-7b36-4882-9078-8eceb69ac456', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why does C++ favor stack allocation over heap allocation where possible?', N'Senior', N'Stack allocation is significantly faster than heap allocation as it involves a simple pointer adjustment rather than searching for free blocks or managing metadata. Furthermore, stack objects follow scope-based lifetime management, which facilitates RAII, ensuring resources are automatically released without the risk of leaks associated with manual heap management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef9b5a5f-a649-42ee-8b86-8ed2cdba268e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What architectural considerations should be made when using WebSockets with FastAPI?', N'Senior', N'WebSockets in FastAPI are stateful and long-lived, which can lead to memory growth and connection management issues if not tracked properly. Developers must implement robust connection managers to handle broadcasting and cleanup, and consider the impact of horizontal scaling, as WebSockets are tied to a specific process instance, often requiring an external message broker like Redis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b80cb7b-da93-4b01-942c-8ed30e2c85d7', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage configuration properties?', N'Fresher', N'Micronaut uses a centralized configuration system that supports various formats like YAML, JSON, and properties files. It allows developers to inject configuration values directly into beans using the @Value or @ConfigurationProperties annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa8fee4a-b327-4bf3-b61f-8ed3d8e4d8af', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the main difference between SQL and NoSQL databases?', N'Junior', N'SQL databases are relational, using structured schemas and predefined table formats. NoSQL databases are non-relational, offering flexible schemas that allow for the storage of unstructured or semi-structured data like documents or key-value pairs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f786f19f-08ee-43c0-ad6e-8ed4d532da8c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s approach to serialization support distributed computing?', N'Senior', N'R''s internal serialization format allows complex objects and environments to be converted into a stream of bytes for inter-process communication. This architecture supports distributed task scheduling by ensuring that stateful functions and data can be reliably transported across a network cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92c81d4a-c0e9-40c6-8c78-8ed68da40160', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix optimize for cache locality in its actor placement strategy?', N'Senior', N'Actix attempts to minimize cross-thread communication by keeping actors that frequently interact within the same Arbiter or thread context. By reducing the frequency of message passing across thread boundaries, the system reduces cache invalidation and context switching overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09e068f1-0c84-4ffe-887f-8ed751165d4f', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is meant by SvelteKit''s file-based routing system?', N'Junior', N'File-based routing means that the structure of your application''s URLs is determined by the folder names within the src/routes directory. Instead of manually configuring a route table, creating a new folder automatically creates a corresponding URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a720f5e-b8ab-4614-ab6b-8eda2049521a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is Tailwind CSS considered a component-based framework?', N'Fresher', N'Tailwind is technically a utility-based framework, not a component-based one, because it does not provide pre-styled widgets like buttons or navbars. However, it is designed to work seamlessly with component-based libraries like React or Vue, where you can wrap utility-heavy HTML into reusable components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a72ca8e-4d2d-4d88-ac1e-8edba74e7a0f', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the concept of ''Lazy Initialization'' in Spring beans.', N'Middle', N'By default, Spring creates all singleton beans at startup. Lazy initialization postpones the creation of these beans until they are first requested by the application, which can significantly reduce the startup time for large applications but may hide configuration errors until runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9aca9dd3-4e0b-49ce-815c-8edbe9db933d', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How does an API gateway improve the architecture of a microservices system?', N'Middle', N'An API gateway acts as a single entry point that handles cross-cutting concerns like authentication, rate limiting, logging, and SSL termination. This decouples these responsibilities from individual services and simplifies the client-side interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c3a0fe0-543b-4897-805e-8eddef9acd8e', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the best way to test Express route handlers?', N'Middle', N'The best approach is to use testing frameworks like Jest or Mocha along with Supertest. Supertest allows you to make simulated HTTP requests to your Express app instance, enabling you to verify status codes, response bodies, and headers without needing to listen on a real network port.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e894b9d9-1030-4207-b68c-8edfcacfb26f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte transitions and animations differ from standard CSS transitions?', N'Middle', N'Svelte transitions are built into the framework and handle the lifecycle of elements being added or removed from the DOM. They provide a declarative API that coordinates with the framework''s reactivity to manage complex entry and exit animations easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05394075-ffeb-4ba1-9c99-8ee62ddaf588', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do declaration files (.d.ts) facilitate interoperability with legacy JavaScript codebases?', N'Senior', N'Declaration files provide a layer of type definitions for JavaScript code without requiring the original source to be modified. They act as a contract that informs the TypeScript compiler about the shape and function signatures of the JavaScript modules, enabling type-safe integration in mixed projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b7c1134-a0fa-468d-aa46-8eed76d134c6', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What testing frameworks work best with NestJS?', N'Middle', N'NestJS is a Node.js framework, so any testing framework that works with Node.js will work with NestJS. Some popular options include Jest, Mocha, and Jasmine. NestJS is built with testing in mind and it comes with its own testing module called @nestjs/testing. This module provides utilities for testing, such as a testing module and HTTP testing utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0b843ee-3943-4ed8-9ab4-8eedb0f13f1f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can Sass help in implementing a scalable grid system?', N'Senior', N'Sass enables the creation of a programmatic grid system where column widths and spacing are calculated based on map configurations. By using loops and mixins, you can generate responsive grid classes at compile time, ensuring a scalable and consistent layout structure across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd81ad8a8-88d9-409c-9c32-8eef0c1470f5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the ampersand (&) operator used for in Sass?', N'Junior', N'The ampersand represents the parent selector in a nested rule. It is most commonly used for creating pseudo-classes like hover states or for applying modifiers to BEM-style class names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63245437-2d33-4362-8537-8eef622d398e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is Aspect-Oriented Programming (AOP) in Micronaut?', N'Intern', N'AOP is a programming paradigm that allows developers to separate cross-cutting concerns, such as logging, security, or transaction management, from the main business logic. Micronaut implements AOP using compile-time advice to wrap method calls with additional behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd736b09-7f5e-47e4-a6d2-8ef2235a0d18', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do PHP''s magic methods impact the performance of object-oriented designs?', N'Senior', N'Magic methods like __get, __set, and __call allow for dynamic behavior but force the engine to perform lookups at runtime rather than resolving methods at compile time. Overusing these for performance-critical logic can introduce significant overhead compared to direct property access or explicit method calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a92bcd92-a50d-4b68-82c3-8ef28e9a13c9', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind help prevent the ''CSS bloat'' common in large applications?', N'Middle', N'By generating only the CSS that is actually used in the project, Tailwind keeps the CSS bundle as small as possible. Unlike traditional frameworks that ship entire libraries of components and styles, Tailwind’s output is strictly limited to the styles defined in the project''s source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb736a5c-be7a-4c54-beb3-8ef312a5bc9c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the Recover middleware in Echo?', N'Intern', N'The Recover middleware is used to prevent the application from crashing when a panic occurs in a handler. It catches the panic, logs the error, and returns a 500 Internal Server Error response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a8b91c6-6c07-4b87-bbe4-8ef82d75add9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the benefit of using Rocket''s procedural macros?', N'Fresher', N'Procedural macros allow for a declarative style of programming, where routing and request handling logic is clearly visible. They also enable compile-time checks, which catch errors before the application even runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'910afb6a-70fd-4fbc-a7a0-8efa15cf828f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the concept of sequence points and how they relate to compiler instruction reordering.', N'Senior', N'Sequence points define the boundary at which all side effects of the previous operations must be complete before the next operation begins. By ensuring a well-defined state at these points, the language allows the compiler to reorder instructions within those bounds for better pipeline utilization. Mastering this concept is vital for preventing race conditions and ensuring deterministic behavior in concurrent environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07558e0e-f6b2-4e0a-9558-8efa652494e1', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a WSGI server and why is it needed for Flask?', N'Fresher', N'WSGI stands for Web Server Gateway Interface. It acts as a bridge between the web server and the Flask application, ensuring that the server can communicate with the Python code to process requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ea19d54-ce2e-43ad-a7f6-8efe447ca4af', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are SvelteKit actions, and when should you use them?', N'Junior', N'Actions are functions exported from +page.server.js used to handle form submissions. They allow you to process data on the server, validate inputs, and return responses without needing to write custom API endpoints for every form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5dc1c1e-5c3e-460e-bb43-8eff22d71ac0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Discuss the trade-offs between using Symfony ''Bundles'' versus ''Micro-services'' for scaling.', N'Senior', N'Bundles are excellent for internal code organization and reuse within a single application but can create tight coupling if not managed carefully. Micro-services offer superior isolation and independent scaling at the cost of significantly increased operational complexity and the need for robust inter-service communication patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
