INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df665f82-79ae-4be6-bd4a-8f074ca374ed', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary purpose of ''Idempotency'' in distributed systems?', N'Senior', N'Idempotency ensures that performing the same operation multiple times results in the same state change as a single operation. This is critical for robust distributed systems where network timeouts or retries may cause duplicate requests to reach a service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f087b788-973c-4d6c-b897-8f07d8c79cc4', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the performance implications of using a heavy ORM versus raw SQL queries?', N'Middle', N'ORMs increase developer productivity by abstracting database interactions into objects, but they can generate inefficient queries that lead to performance bottlenecks. Raw SQL provides full control over optimization and indexing, resulting in better performance for complex operations. The trade-off is higher maintenance and increased risk of security vulnerabilities like injection if not handled carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74d0497d-6341-4b6a-8ac1-8f09df7de474', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the role of ngModule metadata in compilation process?', N'Intern', N'The @NgModule metadata is used to tell the Angular compiler what components to be compiled for this module and how to link this module with other modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd5dc62b-9385-4bb9-b1c6-8f0b5c2cbf30', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the primary architectural trade-off between using V8''s pointer compression versus full 64-bit pointers?', N'Senior', N'Pointer compression reduces memory footprint and improves cache locality by representing pointers as 32-bit offsets from a base address. The trade-off is the minor CPU overhead required to decompress the address before every memory access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac0fc568-edb2-4293-9a3e-8f0b8c33c2ab', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where you disagree with a peer''s technical approach?', N'Junior', N'I frame the discussion around the specific trade-offs of both approaches, focusing on maintainability, scalability, and project goals rather than personal preference. I listen to their reasoning to ensure I understand their perspective, and if we cannot reach a consensus, I suggest involving a senior team member for guidance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'399058a9-333e-46ec-a680-8f0ce3199d15', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide whether to fix a bug immediately or prioritize a new feature?', N'Junior', N'I evaluate the bug''s impact, such as whether it causes data loss or breaks critical functionality, versus the priority and deadline of the new feature. I would consult with my lead or product manager to align on the business impact and determine which task provides the most value to the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
