INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b22bf53c-cd87-4c57-8809-8f0de5940598', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the trade-offs of using ''Box<T>''?', N'Middle', N'Using ''Box '' allows for heap allocation, which is useful for recursive data structures or storing large objects. However, it introduces a small runtime overhead due to the indirection and potential cache misses compared to stack-allocated data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
