INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3aa5fbf-1009-42bc-9e0e-8f0ffe93333b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the memory management advantages of Quarkus in containerized environments.', N'Senior', N'Because Quarkus native images do not require a full JVM runtime and eliminate many runtime metadata caches, they consume significantly less RAM. This allows for higher density of service instances on the same underlying hardware, directly reducing infrastructure costs in Kubernetes or serverless platforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5242122e-b4bc-40c6-aaf8-8f101ec819c6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how the microtask queue interacts with the event loop during the rendering pipeline.', N'Senior', N'Microtasks are processed immediately after the current operation finishes, even before the event loop yields control to the rendering or task phases. If a microtask queue is never empty, it can effectively starve the rendering pipeline, causing the UI to freeze.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb005965-b25d-46bd-b2e7-8f14805117c1', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How can PHP''s ''strict_types'' mode change the behavior of type enforcement?', N'Middle', N'When ''strict_types'' is enabled, PHP disables implicit type coercion for scalar types in function calls and return values. This ensures that only variables of the exact type specified in the signature are accepted, preventing subtle logic bugs caused by loose type juggling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
