INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4af808-77b7-490e-9c14-8f1a65b01335', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What happens when you execute a ROLLBACK command?', N'Junior', N'A ROLLBACK command undoes all changes made during the current transaction. It reverts the database state to how it was before the transaction started, ensuring that partial or corrupted data is not saved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9577f1b0-509e-4f18-af5c-8f1aba8f06ba', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is MVCC and how does it affect PostgreSQL performance?', N'Middle', N'MVCC stands for Multi-Version Concurrency Control, allowing multiple transactions to read and write to the same data simultaneously without blocking each other. It works by creating snapshots of data, which avoids the need for heavy read locks but requires background processes like autovacuum to clean up obsolete row versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
