INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3924231-23f2-4d76-b5f0-8f1fc0751fe0', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between synchronous and asynchronous tasks?', N'Junior', N'Synchronous tasks execute one after another, blocking the thread until the current task completes. Asynchronous tasks allow the program to start a task and move on to other work immediately, executing the task in the background and returning the result later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
