INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a305106-bbc4-4209-aed5-8f2458e84536', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the impact of Flask''s synchronous nature on performance when dealing with I/O-bound operations?', N'Senior', N'Because Flask is inherently synchronous, a single request blocking on an I/O operation will hold up the worker process, limiting concurrency. To mitigate this, developers should use asynchronous libraries, offload tasks to background workers, or migrate to a framework that natively supports asynchronous request handling for I/O-intensive workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
