INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c10e657c-1704-4035-9404-8f2dc5972f39', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''readonly'' keyword do in TypeScript?', N'Fresher', N'The ''readonly'' keyword is used to mark a property in an interface or object as immutable. Once a value is assigned to a readonly property, it cannot be changed or reassigned, which helps prevent accidental mutations of data throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'281a188f-88d3-4228-b195-8f2e67e3eefe', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the significance of the C++ ''strict aliasing'' rule for compiler optimizations?', N'Senior', N'The strict aliasing rule states that an object shall have its stored value accessed only by an lvalue expression of its dynamic type, with few exceptions. This rule permits the compiler to assume that pointers of different types do not refer to the same memory location, facilitating aggressive register allocation and instruction reordering that would otherwise be unsafe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7e83e76-7479-4551-bcdb-8f30a459f987', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''Deadlock'' mechanism in InnoDB and how is it detected?', N'Senior', N'A deadlock occurs when two or more transactions hold locks that the others need, creating a circular dependency. InnoDB continuously runs a wait-for-graph algorithm to detect these cycles and automatically rolls back the transaction that has the smallest undo log size to resolve the conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
