INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22f48f68-c275-4edb-b035-8f336ba3e1a4', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift handle the ''ABI Stability'' across different compiler versions?', N'Senior', N'ABI stability allows binaries built with different versions of the Swift compiler to interact with each other, provided they target the same runtime version. This requires a stable layout for classes, value types, and protocol witness tables, ensuring that the runtime can correctly access properties and methods regardless of the build environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
