INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c880ac87-1dd8-4f98-8aa0-8f3e8bf37323', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind minimize the size of the final CSS file?', N'Intern', N'Tailwind scans your project files for utility classes and only includes those that are actually being used in the final production build. By stripping out unused styles, it keeps the final CSS bundle significantly smaller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6844a2d6-d4c5-4042-99db-8f3fed60df3c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How Node.js read the content of a file?', N'Fresher', N'Node.js provides several ways to read file content using the built-in fs (File System) module. The choice depends on whether you want the operation to be blocking (synchronous) or non-blocking (asynchronous). 1. Asynchronous (Non-Blocking) – Recommended This is the standard approach for most Node.js applications as it allows the event loop to continue working while the file is being read. * Promises (fs.promises): Modern standard using async/await for clean, readable code. Example: * Callbacks: The traditional method using an error-first callback function. Example: 2. Synchronous (Blocking) The fs.readFileSync() method stops all other code execution until the file is fully read. It returns the content directly rather than using a callback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eb80c9a-eeb0-4c38-9c6f-8f41236a3bb5', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of CSRF protection in Laravel?', N'Fresher', N'Cross-Site Request Forgery (CSRF) protection is a security feature that prevents unauthorized commands from being executed on behalf of an authenticated user. Laravel automatically generates a CSRF token for each active user session, which must be verified for every state-changing request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df8f6aec-b0a6-4a7a-b181-8f435fda0d99', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is RAII in C++?', N'Junior', N'RAII stands for Resource Acquisition Is Initialization, a programming idiom where resource management is tied to object lifetime. By acquiring resources in a constructor and releasing them in a destructor, developers ensure that resources are properly cleaned up even if an exception occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
