INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e7cd85a-21c1-4b4e-82ab-8f5a92c4c5de', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Compare the performance overhead of PHP''s late static binding versus standard method dispatching.', N'Senior', N'Late static binding requires the engine to resolve the class context at runtime rather than at compile time, which involves additional lookups in the inheritance tree. While the performance impact is usually minimal, it is measurable in extremely high-frequency method calls, making standard dispatching more efficient for performance-critical inner loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
