INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04d8f6a8-2c1c-4d9d-9c48-8f6e1889e481', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the Java Memory Model (JMM) in multithreaded programming?', N'Middle', N'The JMM defines the rules for how threads interact through memory, ensuring visibility and ordering of operations. It specifies how and when changes made by one thread are visible to others, primarily through the use of happens-before relationships. This is crucial for avoiding data races and ensuring consistency in concurrent applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5301f9d9-4479-483e-a30a-8f6f1f6afb6a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the impact of the ''LeveledCompactionStrategy'' (LCS) on read and write latency.', N'Senior', N'LCS organizes SSTables into levels with fixed size limits, ensuring that most partitions reside in a single SSTable and reducing read amplification. However, it incurs higher write amplification and CPU overhead because it requires more frequent compaction operations compared to SizeTieredCompactionStrategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea58547b-4569-402b-9a77-8f7034dccff2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is state hoisting a common pattern in React architecture?', N'Senior', N'State hoisting allows multiple sibling components to share and synchronize data by moving the state to their closest common ancestor. This ensures a single source of truth and simplifies data flow, though it can lead to prop drilling if the ancestor is too high in the tree, necessitating tools like Context or state managers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bebb5637-9ebe-4289-a779-8f722feb8f63', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Are Go functions first-class citizens?', N'Fresher', N'Yes, functions in Go are first-class, meaning they can be assigned to variables, passed as arguments to other functions, and returned as values from functions. This enables powerful functional programming patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd64dad9-95d1-4be0-9c34-8f72c3103113', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does ''attr_accessor'' do?', N'Junior', N'The ''attr_accessor'' method is a shortcut that automatically generates both getter and setter methods for an instance variable. It makes the variable accessible and modifiable from outside the class instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
