INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c19cc76f-64ca-44b7-ae5a-8f7304a8caed', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot''s Auto-configuration mechanism function internally?', N'Senior', N'Spring Boot uses @EnableAutoConfiguration, which triggers the AutoConfigurationImportSelector to scan META-INF/spring.factories files on the classpath. It evaluates @Conditional annotations to determine if specific beans should be registered based on the presence of classes or properties, effectively creating an opinionated application context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cb18b5e-c4b7-4d5c-924e-8f75acadc3a2', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose a NoSQL database over a relational database for a rapidly evolving application prototype?', N'Junior', N'NoSQL databases offer a flexible schema, allowing you to add new data fields without performing expensive migrations on existing data. This speed is beneficial in a prototype stage where the data structure is frequently changing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f4b9950-b5bb-4a02-89b8-8f7651722f5f', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is an IDE?', N'Intern', N'An Integrated Development Environment (IDE) is a software application that provides comprehensive facilities for software development. It typically includes a source code editor, build automation tools, and a debugger in a single graphical user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c89f0533-853b-475e-ad31-8f7694cceabf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between for..in and for..of?', N'Fresher', N'Both for..of and for..in statements iterate over lists; the values iterated on are different though, for..in returns a list of keys on the object being iterated, whereas for..of returns a list of values of the numeric properties of the object being iterated. * for in: iterates over all enumerable properties of an object that are keyed by strings. * for of: iterates over the values of an iterable objects. including: built-in String, Array, array-like objects (e.g., arguments or NodeList), TypedArray, Map, Set, and user-defined iterables. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd369ed3e-4486-4d75-9512-8f782070f411', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between a parameter and an argument?', N'Fresher', N'A parameter is a variable in the declaration of a function, while an argument is the actual value passed to the function when it is called. For example, in the function function add(a, b) { return a + b; }, a and b are parameters. When you call add(2, 3), 2 and 3 are arguments. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of hoisting with regards to functions Hoisting in JavaScript is a behavior where function declarations are moved to the top of their containing scope during the compile phase. This means you can call a function before it is defined in the code. However, this does not apply to function expressions or arrow functions, which are not hoisted in the same way. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0a67216-0e6f-45ad-a5b9-8f793f9270ef', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the trade-offs of deploying Astro to an edge runtime compared to a traditional Node.js server.', N'Senior', N'Edge runtimes provide lower latency by executing code geographically closer to the user, but they often impose stricter constraints on memory and execution time compared to Node.js environments. Node.js is generally more flexible for complex server-side operations, while the edge is superior for globally distributed, lightweight request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48cfe188-7dbc-4de0-a3b9-8f79adf5e32e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ''Multi-Version Concurrency Control'' (MVCC) handle long-running read transactions without blocking writes?', N'Senior', N'MVCC maintains multiple versions of data rows, allowing readers to access a consistent snapshot of the data as it existed at the start of their transaction. This avoids read-write contention because writers create new versions instead of overwriting existing ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dffa6469-1911-4e18-a403-8f7c6154f9b4', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle asset optimization compared to standard Webpack-based setups?', N'Middle', N'Astro uses Vite as its underlying build tool, which automatically handles asset bundling, minification, and code splitting. It optimizes images and scripts by processing them during the build phase, reducing the manual configuration typically required in older bundlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e75495b-e050-4385-9dd3-8f7fce306c36', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS facilitate the implementation of the CQRS pattern, and what is the benefit for high-load systems?', N'Senior', N'NestJS provides a dedicated CQRS module that separates read and write operations via commands and queries. This pattern allows for independent scaling of read and write models, optimization of database schemas for specific access patterns, and improved system maintainability in complex business domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f34ed0e7-2822-411c-94e9-8f82cf70f708', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the advantage of using class-based controllers?', N'Intern', N'Class-based controllers provide a clean way to organize routes, share state through class attributes, and manage dependencies. They improve code readability and maintainability for larger API projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7164a01c-3fc3-4aea-a39e-8f85e0dc096d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the Ember Data library?', N'Junior', N'Ember Data is a data persistence library that helps manage the communication between your application and a backend API. It provides a standardized way to fetch, update, and delete records using models and adapters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c87d0797-8494-4afe-b07b-8f899e656deb', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the trade-offs between eventual consistency and strong consistency in a distributed database.', N'Senior', N'Strong consistency guarantees that a read always returns the most recent write, but it increases latency due to synchronous replication and locking requirements. Eventual consistency prioritizes high availability and low latency by allowing temporary data divergence, which is resolved asynchronously, requiring the application to handle potential conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a100ea5b-84dc-4cc1-b14b-8f8e9be9615c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why is Ruby''s memory management considered ''stop-the-world'' in certain contexts?', N'Middle', N'Ruby uses a mark-and-sweep garbage collector that identifies reachable objects and reclaims memory from unreachable ones. During the sweeping phase, the Ruby interpreter pauses the execution of the application to ensure that memory is not moved or reclaimed while the program is actively using it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'299eae08-4840-43c4-b06e-8f9121295648', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js event loop handle asynchronous I/O operations, and what is the role of the libuv library?', N'Middle', N'Node.js offloads heavy I/O operations to the libuv library, which manages a thread pool to handle tasks that cannot be performed non-blockingly by the operating system kernel. Once these operations complete, libuv pushes the callbacks back into the event loop''s task queues to be executed by the main thread. This architecture allows Node.js to remain responsive while performing complex I/O without blocking the execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cd574d4-c11c-4955-b272-8f9322a72392', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between a class and an object?', N'Intern', N'A class is a blueprint or template used to create objects, defining the data and behaviors that objects of that type will have. An object is a specific instance of a class that holds actual values for the defined attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'671088cb-d128-4e7e-a51a-8f94b9e24773', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'In what ways does Remix simplify authentication compared to client-side only implementations?', N'Senior', N'Remix allows authentication checks to occur within the loader function, preventing unauthorized data from ever reaching the client. This secure-by-default approach eliminates the need for complex client-side middleware or protecting routes via redirects in the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79a19d80-59b8-493c-a107-8f99837fdcf7', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between a local development environment and a production environment?', N'Intern', N'A local environment is where a developer builds and tests changes in isolation. The production environment is the live system accessed by real users, requiring higher stability, security, and performance standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'149260a9-a7d2-4127-9762-8f9c26299cd4', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach a bug that you cannot reproduce consistently?', N'Fresher', N'I would gather as much context as possible, such as the environment details, user actions, and time of occurrence. Then, I would attempt to isolate variables by systematically changing conditions until the issue appears reliably, which makes it easier to verify a fix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fa5d76a-f292-44e3-a713-8f9c353e1bb0', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the primary difference between Server-Side Rendering (SSR) and Static Site Generation (SSG) in Next.js?', N'Fresher', N'In SSR, pages are rendered on the server for every single request, ensuring the content is always up to date. In SSG, pages are generated at build time, making them extremely fast to load, but they are only updated when the application is re-deployed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1501c57c-8137-4f90-8b81-8f9f08078dae', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the primary difference between Zone.js-based change detection and the newer Signal-based approach?', N'Senior', N'Zone.js relies on monkey-patching asynchronous browser APIs to trigger global change detection cycles, which is imprecise and often results in unnecessary re-renders. Signals provide a fine-grained reactivity system that tracks dependencies explicitly, allowing the framework to update only the specific DOM nodes bound to the changed state without checking the entire component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fb0bf65-faba-4a09-a712-8f9f3e6bc68d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between static and instance members?', N'Intern', N'Static members belong to the class itself and are shared across all instances of that class, meaning there is only one copy in memory. Instance members belong to a specific object, and each instance maintains its own separate copy of those members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5d83ef2-13d1-42ba-9608-8f9f81d77044', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API versioning in a distributed system, and what are the trade-offs between URI, header, and media type versioning?', N'Senior', N'URI versioning is the most visible and cache-friendly but breaks RESTful resource identification. Header versioning keeps URIs clean but complicates caching and proxy handling. Media type versioning, or content negotiation, is the most semantically correct but is often considered complex to implement and debug for developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5604c68-0c11-44ba-a833-8fa236b90066', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the Block Formatting Context (BFC) and how does it affect the box model?', N'Intern', N'A Block Formatting Context (BFC) is an independent rendering region where block boxes are laid out according to normal flow rules. Elements inside a BFC do not affect the layout of elements outside it. A BFC is created by: * overflow value other than visible (e.g., hidden, auto, scroll) * display: flow-root * display: flex or display: grid (on the container) * position: absolute or position: fixed * float: left or float: right Use cases: 1. Contain floats – A BFC container grows to wrap its floated children (clearfix alternative). 2. Prevent margin collapse – Margins between a BFC element and its children do not collapse. 3. Avoid float overlap – A BFC box will not overlap with a sibling float.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23d211b4-788f-4597-a5ec-8fa3ab30f80f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the benefit of using ''web::Data'' instead of a global static variable?', N'Middle', N'Using web::Data allows for better testability and dependency injection. It scopes the state to the application lifecycle rather than the global process scope, ensuring that dependencies are correctly initialized and dropped when the application context is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2da951c-61eb-4e23-8dea-8fa46befe40b', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of Laravel Queues, and how do they improve performance?', N'Middle', N'Queues allow you to defer the processing of time-consuming tasks, such as sending large batches of emails or image processing, to a background process. By offloading these tasks, you significantly reduce response times for the end user and improve overall application throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a24266c6-d89c-435b-a2a6-8faab0217213', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are callback functions and how are they used?', N'Intern', N'A callback function is a function passed into another function as an argument, which is then invoked inside the outer function to complete some kind of routine or action. They are commonly used for asynchronous operations like handling events, making API calls, or reading files. For example: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c697b3db-dc03-484d-8b4c-8fabeaa24fbf', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you use Bazel with Angular CLI?', N'Fresher', N'The @angular/bazel package provides a builder that allows Angular CLI to use Bazel as the build tool. 1. Use in an existing application: Add @angular/bazel using CLI 2. Use in a new application: Install the package and create the application with collection option When you use ng build and ng serve commands, Bazel is used behind the scenes and outputs the results in dist/bin folder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a66b72f-95f5-4f1c-a787-8fad7a2eb4df', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the difference between Laravel''s ''Events'' and ''Jobs'' in terms of architectural communication.', N'Senior', N'Events are for decoupling side effects within the same request-response cycle or local process, often used for observers. Jobs are for offloading intensive tasks to background workers, decoupling the task from the user''s current request cycle to improve responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1accdfa-9189-4c34-b7f4-8fb261477b21', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the advantages of Micronaut''s support for reactive programming in the controller layer?', N'Senior', N'Reactive support allows controllers to handle streams of data using non-blocking backpressure, preventing the server from being overwhelmed by burst traffic. It enables efficient integration with databases and external APIs that support reactive drivers, maximizing resource utilization across the entire call stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c665e4b3-89a2-4a4e-a8b5-8fb4c891687c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the Memtable contribute to write performance?', N'Middle', N'The Memtable is an in-memory data structure that buffers incoming writes before they are flushed to disk. This allows Cassandra to perform extremely fast, non-blocking sequential writes to the commit log and memory, significantly reducing latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82836668-ff52-4263-9f8a-8fb4cce65c8b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of using the useFetcher hook?', N'Junior', N'The useFetcher hook allows you to interact with loaders and actions without navigating to a new page. It is ideal for background tasks like submitting a ''like'' button, updating a specific part of the UI, or fetching data outside of the current route''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47df1d5f-1961-47e2-8221-8fb64673e90e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the reasoning behind choosing a specific programming language for a new service?', N'Junior', N'The choice should depend on the team''s existing expertise, the availability of libraries for the specific task, and the performance requirements of the service. It is often better to stick to a language the team knows well to ensure faster delivery and easier maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c8a748d-2709-4ece-8dcc-8fb77977f041', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the role of the ''picture'' element in responsive image architecture?', N'Senior', N'The picture element enables art direction by allowing developers to provide different image sources based on media queries or file formats like WebP or AVIF. This architecture minimizes data usage by ensuring the browser only downloads the most appropriate asset for the specific device and network conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
