INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0de2762e-1ed0-4c57-983c-8fbc0a244cd8', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do microservices promote scalability compared to monolithic architectures?', N'Middle', N'Microservices allow individual components of an application to be scaled independently based on their specific resource needs. In a monolith, the entire application must be replicated, which is often inefficient if only one specific feature is experiencing high demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd53ad570-2e0d-424a-94cf-8fbcc31cf7c3', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'In what ways does Hono''s implementation of ''Headers'' and ''Cookies'' differ from traditional Node frameworks to support edge-native features?', N'Senior', N'Hono uses standard Headers and Cookie APIs that are compliant with web standards, making them directly compatible with the Fetch API. Unlike Node''s legacy ''req.headers'' object, Hono''s approach ensures that manipulations are consistent across environments that do not support Node-specific header parsing, ensuring that headers behave predictably in V8-based runtimes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b06392de-8dae-4b69-9780-8fbf5dc99ed7', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a deadlock and how does MySQL handle it?', N'Middle', N'A deadlock occurs when two or more transactions hold locks on resources the other needs, creating a circular dependency. MySQL automatically detects deadlocks and rolls back the transaction that has the least amount of work to do, allowing the other transactions to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c727c4e-c9c9-4bef-9d4d-8fc0d89e0d4f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between security hardening and system usability?', N'Senior', N'I apply a risk-based approach, implementing the most rigorous controls on high-value data paths and less restrictive ones on public or low-risk endpoints. Security measures that introduce significant friction, such as excessive MFA or complex key rotation, are mitigated through automation to ensure that the developer and user workflows remain productive while maintaining compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'523fd08f-b56c-440a-8d4d-8fc36ce69b64', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the role of a mongod process?', N'Junior', N'The mongod process is the primary daemon process for the MongoDB system. It handles data requests, manages data access, and performs background management operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5fb30f0-cee6-4ce5-9a5d-8fc538544079', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How is data stored in collections in MongoDB?', N'Fresher', N'In MongoDB, data is stored in types of collections, ensuring flexibility and efficiency in data modeling. Collection Basics - Collections are the primary data storage structures in MongoDB, akin to tables in relational databases. - They are schema-less, meaning that documents within a collection can have varying structures. This offers superior flexibility, while still allowing for structure validation through the use of JSON schema. Documents - Documents serve as the unit of data storage in MongoDB. These are akin to rows in relational databases or objects in languages such as JavaScript. - Documents are represented in BSON (Binary JSON) format, a binary representation closely mirroring JSON''s attribute-value data model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5675230-5c51-425e-b2b8-8fc63276f18d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle ''poison pill'' messages that cause consumer crashes?', N'Senior', N'Poison pills should be moved to a Dead Letter Queue (DLQ) after a specified number of failed retry attempts. This prevents the message from blocking the main processing pipeline while allowing developers to inspect and debug the problematic payload offline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaaa9dc0-3d08-4314-9b45-8fc660bd3cd9', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the mergeProps helper?', N'Intern', N'The mergeProps helper is used to combine multiple objects into a single set of props while maintaining reactivity. It ensures that the resulting object remains tracked by the SolidJS reactive system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4534b0b-de73-4d53-9bf3-8fc6bba707b7', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you determine if a problem is caused by network latency or application logic?', N'Fresher', N'You can use diagnostic tools to measure the response time of network requests compared to the internal processing time of the application. If the delay consistently happens during data transmission, the issue is likely network-related.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb0380dc-b584-4b36-89ee-8fcbe0641024', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Discuss the trade-off of maintaining secondary indexes in highly write-intensive workloads.', N'Senior', N'Every secondary index requires an additional write operation and index tree update for every row insertion or modification. In high-write environments, this can create a bottleneck, often leading architects to offload indexing to external search engines or stream processors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83677596-f0bd-47d2-b470-8fcc53b5b780', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of the ''useTransition'' hook in modern React?', N'Senior', N'useTransition allows developers to mark state updates as non-urgent transitions, meaning React will not block the UI while processing them. This is particularly useful for UI patterns like search filters where displaying a loading state would be jarring but immediate response to input is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'714af20c-e9c4-4a4e-b541-8fce5cfeb2fb', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you improve the performance of an Express application under high load?', N'Middle', N'Performance can be improved by using a reverse proxy like Nginx for static files and load balancing, implementing caching strategies, and optimizing database queries. Additionally, running the application in a cluster mode using process managers like PM2 helps utilize multi-core systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c6b5bda-f117-4135-909a-8fcf29ff3fcc', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS perform validation?', N'Intern', N'NestJS typically uses the class-validator library combined with Pipes. By adding validation decorators to DTO properties, the framework automatically validates the incoming request payload against the defined rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33edeaef-4cae-469b-8642-8fcf94435ac3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the delivery timeline for a project with high technical uncertainty and unknown dependencies?', N'Senior', N'I use a range-based estimation approach combined with a spike-driven discovery phase to reduce uncertainty. By breaking the project into smaller, verifiable chunks and applying a confidence factor to each, I can provide a probability-based delivery window rather than a fixed date.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84d68224-0d39-4094-a204-8fcfcb6aa746', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does ''static typing'' mean in the context of TypeScript?', N'Intern', N'Static typing means that variable types are checked at compile time rather than at runtime. By declaring the type of a variable, the developer ensures that the variable only holds values of that specific type, preventing many common programming errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f0b80ce-ea4b-4d33-b90c-8fd07239c924', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does immutability affect the performance of state management in frameworks?', N'Middle', N'Immutability allows for quick reference equality checks to determine if state has changed, which is much faster than deep-comparing object trees. This optimization is crucial for frameworks to efficiently decide which parts of the UI need to be re-rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b322ac9-5b1a-44ba-b096-8fd0c397cf96', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is a reactive property in Lit?', N'Intern', N'A reactive property is a class field that, when changed, triggers the component to re-render. You define these properties to tell Lit which data points should drive UI updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fa2fc62-d63e-474e-a282-8fd3e31d90c5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a microservice that is intermittently crashing with ''Out of Memory'' errors?', N'Senior', N'I analyze the trend of memory growth before the crash to distinguish between a slow leak and sudden allocation spikes. I review the container''s memory limit vs. JVM heap configuration to ensure the process isn''t being killed by the kernel for exceeding cgroup limits due to native memory usage or heap fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67de9b40-b291-4331-8856-8fd8737224d5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where a team member disagrees with your approach?', N'Intern', N'I would invite the team member to discuss their concerns openly and ask them to explain their reasoning. I would also clearly explain my own logic and the goals I am trying to achieve. If we cannot agree, I would suggest bringing in a third party or the project lead to help us weigh the pros and cons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2635da44-40bb-4063-8c11-8fda6bac0800', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is ''Write Skew'' and why does it occur?', N'Middle', N'Write skew occurs when two concurrent transactions read overlapping data sets but modify disjoint sets of data that are logically related. Because the modifications do not conflict directly at the row level, the database may allow both to commit, violating the business constraints that define consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6e63532-b298-4b6e-8af0-8fdc6f86eaf1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is ''perfect'' software usually considered an unrealistic goal?', N'Intern', N'Software development involves finite time, budget, and resources. Achieving perfection in one area, such as security or speed, often requires sacrificing resources that could be used for other critical features or faster delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9589ff0f-335c-4afa-b248-8fdef3edd5d0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik require the browser to download all JavaScript on initial load?', N'Intern', N'No, Qwik is designed to download almost zero JavaScript on the initial page load. It only fetches the necessary code when a user interacts with an element, such as clicking a button or scrolling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e969aabe-7b56-465c-b208-8fe0cdcab8b4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the trade-offs of using ''Lazy Loading'' (dynamic imports) extensively?', N'Senior', N'Lazy loading improves initial load time by deferring the download of non-critical code. However, excessive splitting can lead to a fragmented user experience where components appear late, and it necessitates careful management of network requests and potential loading states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4628fcc-4fb7-4f0a-b64f-8fe31eca7a4b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you detect and mitigate race conditions in a production backend?', N'Senior', N'Race conditions are detected during development using the built-in race detector, which instruments code to track memory access patterns. In production, mitigation involves adopting immutable data structures, using synchronization primitives like channels or mutexes, and ensuring strict ownership of shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72892421-a4b1-48ab-bd6f-8fe42e8a5cb2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a scenario where a third-party API is unreliable, causing your system to fail?', N'Middle', N'I would implement the circuit breaker pattern to prevent cascading failures and provide a fallback mechanism, such as returning cached data or a default response. Additionally, I would introduce retries with exponential backoff and jitter to reduce load on the failing service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed7ccd2b-fc3a-4853-9176-8fe766fb8985', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you check the type of an object in Python?', N'Junior', N'You can use the built-in type() function to return the type of an object. Alternatively, you can use the isinstance() function to check if an object is an instance of a specific class or a tuple of classes. Using isinstance() is generally preferred because it supports inheritance, meaning it returns true if the object belongs to a subclass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18239ea9-c8b4-4db3-91e4-8fe799c32b3c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you manage complex entity relationships within a Redux store?', N'Senior', N'Complex relationships are managed by normalizing the state and using lookup tables or specialized libraries like Normalizr. This approach avoids deeply nested structures, allowing for easier updates to related entities without having to perform deep object merges, which is both error-prone and computationally expensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd69ea4ae-7a18-452c-ac5b-8fe7f223ff3d', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the concept of Just-in-Time (JIT) mode in Tailwind CSS.', N'Fresher', N'JIT mode generates CSS styles on-demand as you author your HTML, rather than generating them all at once. This results in faster build times, the ability to use arbitrary values, and a smaller final CSS file size since only used styles are included.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2611eef3-5fef-4369-966d-8fea257685a6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is the separation of ''Controllers'' and ''Routers'' beneficial in a large-scale Litestar application?', N'Senior', N'This separation enforces modularity by allowing developers to group related functionality into distinct classes while maintaining a clean routing hierarchy. It prevents the ''God Object'' antipattern and allows for granular application of middleware and dependencies at different levels of the routing tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa579e62-befa-4ca0-9c22-8fea60c2ecf7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe the function of the ''balancer'' in a sharded cluster.', N'Middle', N'The balancer is a background process that monitors the distribution of data chunks across shards. When it detects an imbalance, it migrates chunks between shards to ensure an even distribution of data and traffic across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea2bc560-336d-4ace-b16e-8fead167547f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the Flask ''app.route'' decorator?', N'Fresher', N'The route decorator is used to bind a specific URL path to a Python function. When a user navigates to that URL in their browser, Flask executes the associated function to generate the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'991661b4-62a0-4f1f-a21f-8fec1f493327', N'954a0331-deff-4399-b588-96f39fec001d', N'Why is ''Lazy Loading'' important for Angular performance?', N'Middle', N'Lazy loading splits the application into smaller chunks, loading only the necessary code for the current route. This significantly reduces the initial bundle size, leading to faster application startup times and improved user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c36fc2ed-80df-47c7-b49f-8fefadee5e1b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do actors share state in Actix?', N'Junior', N'Actors should follow the principle of sharing memory by communicating rather than sharing data directly. If state must be shared, it is typically managed by a dedicated manager actor that holds the data and processes access requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6461398b-49cc-41b1-8cb0-8ff014f047bc', N'4c000000-0000-0000-0000-000000000005', N'When should you use a distributed cache like Redis?', N'Middle', N'You use a distributed cache to store frequently accessed data in memory to reduce latency and load on the primary database. It is ideal for read-heavy workloads where the cost of fetching data from the main database is high.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
