INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0594c70-4336-492e-bbd8-8ffb0aed6ba5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle module resolution?', N'Middle', N'TypeScript uses module resolution strategies, such as Node or Classic, to determine where to find imported files. This process mirrors the way runtime environments locate modules, ensuring that the compiler can correctly resolve dependencies in a project structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f16d83ec-eb82-4414-b6ea-8ffb4a21a7c5', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the Extractors in the Axum framework?', N'Junior', N'Extractors are a mechanism used to pull data out of an incoming HTTP request, such as path parameters, JSON bodies, or query strings. They allow developers to define the expected structure of the input, and Axum automatically handles the deserialization and validation before the request reaches the handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48364eb8-8da8-4ab2-9f35-8ffd25eb7394', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence your choice of a load balancer configuration?', N'Middle', N'I consider the traffic patterns, the necessity of session stickiness, and whether TLS termination should happen at the load balancer or the application server. The choice depends on balancing performance overhead with the operational simplicity of managing SSL certificates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'204542d2-d8a8-4add-8b8a-9005472a4d66', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a centralized logging system versus local logs?', N'Senior', N'Centralized logging is non-negotiable for distributed systems to enable efficient search, aggregation, and alerting across nodes. Local logs are only useful for immediate, per-node debugging, but they are insufficient for post-mortem analysis in ephemeral cloud environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bcff866-27b6-4b2f-a596-90091fe07f60', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it recommended to use ''Echo.New()'' instead of manual server setup?', N'Middle', N'Using Echo.New() initializes a fully configured instance with default settings for routing, error handling, and middleware management. It abstracts the complexity of server initialization, providing a standardized environment that adheres to framework best practices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2171e5f-dc2b-49a3-8a14-9011a486d08b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''actix-rt'' crate?', N'Intern', N'The ''actix-rt'' crate provides the asynchronous runtime environment that Actix-web relies on. It manages task scheduling and the execution of asynchronous operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ab4064e-0869-45a5-8bdb-9012ca47b150', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of ''getStaticProps'' in the pages directory?', N'Intern', N'In the pages directory, getStaticProps is a function used to fetch data at build time. It allows the page to be pre-rendered with the necessary data, making it highly performant for SEO and load speeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2d0243c-a024-4246-aced-9014466e2f4f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle HTTP methods?', N'Fresher', N'Chi provides explicit methods for standard HTTP verbs such as Get, Post, Put, Delete, and Patch on the router object. Each method maps a specific URL pattern and HTTP verb to a handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd75cd229-3f25-4057-9ef4-901504792395', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why are indexes used in databases?', N'Junior', N'Indexes are used to speed up data retrieval operations by creating a separate data structure that points to the location of rows. While they make searching faster, they can slightly slow down write operations because the index must also be updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b7fb490-41b7-4fb9-bbe3-90151f07fe9e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the ''PubSub'' module in Phoenix?', N'Junior', N'PubSub is a publish-subscribe system that allows different parts of your application to communicate by broadcasting messages to topics. It is frequently used with Channels to notify multiple users of updates in real-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1baa7133-1084-466e-b302-90157af966a5', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Data JPA''s ''Open Session in View'' pattern impact database connection management?', N'Senior', N'OSIV keeps the database connection open for the duration of the entire web request to allow lazy loading of entities in the view layer. This can lead to connection pool exhaustion under high traffic and is generally considered an anti-pattern in high-scale systems where data fetching should be explicit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ae04931-9271-4d89-980c-90183b6f7564', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ memory model handle data races and atomicity?', N'Senior', N'The memory model defines the semantics of memory operations in a multi-threaded context, specifying that data races cause undefined behavior. It provides atomic types and memory ordering constraints, such as sequentially consistent or relaxed, which dictate how the compiler and hardware may reorder instructions to balance performance with synchronization requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78fd40c9-2eff-49b8-9b58-901886eed4db', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''yield from'' syntax facilitate sub-generator delegation?', N'Senior', N'The yield from syntax allows a generator to delegate part of its operations to another generator, establishing a transparent channel between the caller and the sub-generator. It handles the propagation of values, exceptions, and closing signals automatically. This is essential for building complex, modular generator-based pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09cd74dc-e7a8-470d-8a4d-9018c443cd99', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle file caching?', N'Fresher', N'Vite improves caching by adding content hashes to filenames in production builds. This ensures that browsers only download new versions of files when the content actually changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd882572-4251-4c6b-9359-901b4bf18c17', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Lost Update'' anomaly and how is it prevented?', N'Middle', N'A lost update occurs when two transactions read the same data, calculate a new value, and write it back, with the second write overwriting the first without incorporating its changes. It is typically prevented using row-level locks or optimistic concurrency control via version numbering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7885d912-1aee-4ecd-b4c4-901b912266cf', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix Presence features?', N'Junior', N'Presence is a feature that allows developers to track and synchronize the state of users or devices across a cluster of servers. It is commonly used to show which users are currently online or active in a chat room.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36f2f42a-8df0-44f1-9224-901cd4a91416', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are generics in C#?', N'Intern', N'Generics allow you to write code that works with any data type by defining placeholders for types. They provide type safety and performance benefits by avoiding the need for casting and reducing the amount of duplicate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aedf1298-ebfd-4945-8bed-901d91e9427d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle URL parameters?', N'Intern', N'Rocket uses dynamic path segments in route definitions to capture parts of the URL. These segments are automatically parsed and passed as arguments to the handler function, ensuring they match the expected data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'774d3fea-d17b-46d7-bffc-9020dd081db6', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why should you avoid using variable-length arrays (VLAs) in safety-critical systems?', N'Middle', N'VLAs are allocated on the stack, and because their size is determined at runtime, they can easily cause stack overflow if the size is unexpectedly large. This unpredictability makes them unsuitable for systems where memory usage must be strictly bounded and deterministic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f458b9c9-60d7-4625-88fb-9021ac5607d1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the ''event delegation'' pattern and its scalability benefits.', N'Senior', N'Event delegation attaches a single event listener to a parent element to manage events for all its children using bubbling. This significantly reduces memory usage and improves performance when dealing with large lists or dynamically added elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
