INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05eca344-8866-4330-ba4c-902a582ec0f7', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do you handle cleanup in an effect?', N'Junior', N'You handle cleanup by returning a function from within a createEffect. This function will be called automatically before the effect re-runs or when the component is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6487fef9-70de-4f98-aee1-902de94d4a2d', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the significance of the ''promises'' object in R''s evaluation model?', N'Middle', N'A promise is the data structure that stores the unevaluated expression and the environment where it should be evaluated. It is the underlying mechanism that enables lazy evaluation, allowing R to defer computation until the value is actually needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f766651-2d49-479f-b297-9032afdca52d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you handle unhandled promise rejections in a Node.js application?', N'Middle', N'You should listen to the unhandledRejection event on the process object to log errors and perform cleanup. Ideally, the process should be restarted after such an event because the application state may have become unpredictable or unstable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85c91ad0-b1ae-4462-8f22-90335a5531cb', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''public'' directory in AdonisJS?', N'Intern', N'The public directory is used to store static assets such as images, CSS files, and client-side JavaScript files. These files are served directly to the browser without being processed by the application''s backend logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'551441aa-370e-4a37-9495-90357fa44292', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the impact of using ''async/await'' on the call stack compared to raw promises?', N'Senior', N'Async/await creates smaller, more manageable call stacks compared to deeply nested promise chains or callbacks. However, it still relies on the microtask queue, which means excessive awaiting of microtasks can delay the execution of macrotasks like I/O operations. It improves readability but does not change the underlying single-threaded execution model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bb66b45-79e8-464b-a1e2-903748096f6b', N'4c000000-0000-0000-0000-000000000005', N'What is the CAP theorem and what does it imply for system design?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, designers must choose whether to prioritize data consistency or system availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcc37955-cfa4-44a3-beab-903db6bd3e6c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Does Astro support server-side rendering?', N'Intern', N'Yes, Astro supports Server-Side Rendering, or SSR. This allows pages to be rendered on-demand on the server when a request is made, which is useful for personalized content or data that changes frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5c088da-f018-4f4b-ad87-903efed7182f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the Flask-Migrate extension?', N'Intern', N'Flask-Migrate is an extension that handles database schema migrations for SQLAlchemy. It allows developers to track changes to their database models over time and apply those changes to the database structure safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'125aae45-1ad0-476e-8d8f-903fe24025b7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the common pitfalls of using the this keyword?', N'Intern', N'The this keyword in JavaScript can be tricky because its value depends on how a function is called. Common pitfalls include losing the context of this when passing methods as callbacks, using this in nested functions, and misunderstanding this in arrow functions. To avoid these issues, you can use .bind(), arrow functions, or store the context in a variable. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of this binding in event handlers In JavaScript, the this keyword refers to the object that is currently executing the code. In event handlers, this typically refers to the element that triggered the event. However, the value of this can change depending on how the event handler is defined and called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6748dd71-36d2-411b-9b21-9045282fe03b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What does the runtime environment mean in Node.js?', N'Intern', N'The Node.js runtime is the software stack responsible for installing your web service''s code and its dependencies and running your service. The Node.js runtime for App Engine in the standard environment is declared in the app.yaml file: The runtime environment is literally just the environment your application is running in. This can be used to describe both the hardware and the software that is running your application. How much RAM, what version of node, what operating system, how much CPU cores, can all be referenced when talking about a runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19e4ba34-7879-4a5c-b38e-90460c0cc329', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''library()'' function?', N'Junior', N'The ''library()'' function is used to load an installed package into the current R session. Once loaded, the functions and datasets provided by that package become accessible for use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53d9e5bd-792b-4ca4-b957-904d858d955e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is caching considered a trade-off?', N'Fresher', N'Caching improves performance by storing data for quick access, but it introduces the challenge of cache invalidation. The trade-off is the risk of serving stale data versus the gain in speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc93df47-2c9a-4bdf-95da-904f5b56456e', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of Rocket''s ''Fairings'' in the request-response lifecycle?', N'Senior', N'Fairings are middleware-like components that hook into specific lifecycle events such as request initiation, response generation, or application liftoff. They allow for cross-cutting concerns like request logging, header modification, or performance instrumentation without polluting the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6471d43c-a014-43e6-bce2-905211bd053b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s ''Bind'' over manually decoding JSON?', N'Junior', N'The Bind method simplifies code by automatically handling the reading of the request body and decoding it into a struct. It reduces boilerplate code and provides a unified interface for handling different content types like JSON, XML, and Form data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07eb6383-435b-485d-bb0b-9053bbd3e527', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide if a system needs a message queue?', N'Middle', N'I introduce a message queue when I need to buffer traffic spikes, decouple producers from consumers, or ensure reliable delivery of background tasks. It is essential when the workload is bursty and the system needs to maintain stability without scaling all components simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d5a901d-28ba-4401-8262-9055788b3eb6', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus achieve ''supersonic subatomic'' startup times?', N'Middle', N'Quarkus uses GraalVM to compile Java applications into native executables. This process removes the need for a Just-In-Time compiler at runtime and allows the application to start in milliseconds with a very small resident set size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d602ff8-3c13-4904-8fc5-90562546c429', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary architectural difference between Fiber and standard HTTP libraries in Go?', N'Middle', N'Fiber is built on top of Fasthttp, which is optimized for high performance by minimizing memory allocations and reusing objects. Unlike the standard library''s net/http, which creates new objects for every request, Fasthttp uses a worker pool and buffer reuse to significantly reduce GC pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa00f115-89da-4dd9-ae41-9056bb8a5627', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle lifecycle hooks (e.g., onModuleInit) in a large dependency graph?', N'Senior', N'NestJS executes lifecycle hooks in the order of the dependency graph, ensuring that all dependencies are initialized before the dependent service calls its own hook. This guarantees that services are fully prepared before they are accessed, preventing runtime errors during the application boot phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf283843-67a3-4312-938c-905e109243bd', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the NestJS Request Lifecycle?', N'Intern', N'The request lifecycle defines the order in which parts of the framework execute when a request arrives. It generally follows this order: Middleware, Guards, Interceptors, Pipes, Route Handlers, and Exception Filters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2acb45b2-57f4-4645-9e0a-906080053656', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the trade-offs of using an Ecto ''Repository'' as a global singleton vs. using multiple repositories?', N'Senior', N'Using a single repository simplifies configuration and transaction management for most applications. However, using multiple repositories is necessary when interacting with different databases or data sources, providing better isolation and avoiding cross-database transaction contamination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
