INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a551076a-7e5c-4b6f-ba5c-9076d4dc76cf', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What strategy should you use to handle global error recovery in a Chi application?', N'Senior', N'A custom middleware should be defined to recover from panics and log the error context. By wrapping the root Mux with this middleware, you ensure that any unhandled exceptions in deep business logic are caught gracefully and converted into a standard 500 status code response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3fcb090-6e7a-40dc-97f5-907735e6c11f', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the Phoenix framework leverage the Erlang VM to handle millions of concurrent connections compared to traditional thread-per-request models?', N'Senior', N'Phoenix utilizes the BEAM''s lightweight process model, where each connection is a separate process with a tiny memory footprint. Unlike thread-per-request models, which are limited by OS thread overhead and context switching, BEAM processes are scheduled cooperatively by the VM, allowing for massive concurrency with minimal resource consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
