INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e3d99db-e3ec-446f-9468-907d1ce93fea', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Can you run a Spring Boot application without a web server?', N'Intern', N'Yes, you can. If you do not include the web-related starters in your dependencies, the application will simply run as a standard console-based application, which is useful for background tasks or batch processing jobs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cf19db2-97b0-4b2a-ba64-907e2754b839', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Options pattern in ASP.NET Core, and how does it facilitate configuration management?', N'Senior', N'The Options pattern uses strongly-typed classes to represent configuration groups, decoupling the application logic from the underlying configuration providers. It supports features like validation, change tracking via IOptionsMonitor, and singleton-scoped configuration snapshots, making complex settings easier to manage and inject.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8ccb0aa-0b10-42c1-9f77-907fb17190d9', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the difference between @click and x-on:click?', N'Fresher', N'They are identical in functionality. @click is simply shorthand for x-on:click, designed to make the code more concise and readable while performing the exact same action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcf922fa-fa57-4221-a41d-907fe841eb17', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle session management?', N'Fresher', N'Phoenix uses Plugs to manage sessions, typically by storing a session ID in a browser cookie. The server then uses this ID to look up session data associated with that specific user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a1776fd-7b28-4862-93d3-90813d365241', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the architectural implications of using Content Projection vs. Component Composition.', N'Senior', N'Content projection allows components to act as wrappers that accept arbitrary UI fragments, promoting flexibility and design system consistency. Component composition, by contrast, builds functionality through nested components; choosing between them depends on whether the parent needs to control the layout or if the child should remain agnostic of its container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1882c19-a66a-4b42-8d0c-90822ca49954', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the architectural challenge of ''constant caching'' in Ruby.', N'Senior', N'Ruby caches constant lookups to speed up execution, but these caches must be invalidated whenever the class hierarchy or nested modules change. This invalidation mechanism is complex and must be strictly managed by the VM to ensure that constant resolution remains correct while maintaining high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'730f3daa-5d75-4d89-bd45-9088eefdc25c', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does Alpine.js mean by ''reactive''?', N'Intern', N'Reactivity means that when the data inside an Alpine component changes, the DOM elements that depend on that data are automatically updated. You do not need to manually manipulate the DOM to show the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afaec202-1d13-4b30-91c0-908a62cec874', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''pinia'' integration in Nuxt?', N'Middle', N'Pinia provides a standardized, reactive state management solution that integrates seamlessly with Nuxt’s SSR lifecycle. It ensures that the store state is correctly serialized and transferred from the server to the client, preventing synchronization issues during hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbb4f2f6-c380-48d8-b113-908a862578dd', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Expression Problem'' and how does Scala solve it?', N'Senior', N'The expression problem concerns the difficulty of adding both new data types and new operations to a system without recompilation. Scala addresses this through a combination of object-oriented inheritance and functional typeclasses. By using traits and implicit resolution, developers can extend functionality for existing types without modifying the original code, effectively resolving the tension between extensibility and type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
