INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ca20527-d878-4410-bd09-908b436ec872', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the @property decorator?', N'Fresher', N'The @property decorator is used to declare a class field as a reactive property. It allows you to configure options like reflection to attributes, type checking, and custom update triggers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8337610d-b5ea-4938-aadd-908ca8ddf7fd', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the impact of data denormalization in NoSQL databases?', N'Middle', N'Denormalization involves storing redundant data to optimize read performance and simplify query patterns by avoiding joins. While it increases storage requirements and write complexity, it is a standard practice in NoSQL to achieve the high performance required by distributed architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
