INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2508e14b-a4ac-4334-b24f-908feb213a47', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is meant by a ''document'' in Elasticsearch?', N'Intern', N'A document is the basic unit of information that can be indexed in Elasticsearch, represented in JSON format. It contains the fields and values that define the data being stored, similar to a row in a database table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9fb2a2f-1455-4377-bf43-908ff1856670', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is ''schema-on-read'' and how does it differ from traditional schema-on-write?', N'Senior', N'Schema-on-read allows data to be ingested in its raw format without predefined structure, with the application enforcing the schema when the data is queried. This provides extreme flexibility for evolving data models, whereas schema-on-write enforces integrity during ingestion, ensuring higher data quality at the cost of rigidity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc403417-056d-4ed5-8aeb-9094bee997a3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the primary trade-offs when choosing between a relational database and a NoSQL database for a new microservice?', N'Middle', N'Relational databases provide ACID compliance and complex querying capabilities, making them ideal for structured data with strict integrity needs, but they can be harder to scale horizontally. NoSQL databases offer superior scalability and flexibility for unstructured or rapidly evolving data schemas, though they often sacrifice atomicity and complex join operations. The choice depends on whether the priority is transactional integrity or horizontal growth and schema agility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3fbdb0f-a8c1-46f4-8979-90954bc6ee43', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is the ''never'' type used in TypeScript?', N'Middle', N'The ''never'' type represents values that never occur, such as a function that always throws an error or an infinite loop. It is also used in exhaustive checking to ensure that all possible cases in a switch or union type have been handled by the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
