INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6ce0bf7-1715-4f79-a45a-9095f53717e4', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro''s performance generally better than traditional JavaScript frameworks?', N'Intern', N'Astro''s performance is superior because it ships significantly less JavaScript to the user. By rendering content on the server and only loading JavaScript for interactive components, the browser does less work to display the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec5e7a6c-ca42-41f2-a24c-9097d3434ed8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the PostgreSQL query planner utilize statistics stored in the system catalogs to choose an execution plan?', N'Senior', N'The planner uses histograms and most-common-value statistics generated by the ANALYZE command to estimate the selectivity of predicates. These estimations determine whether the planner chooses a sequential scan, an index scan, or specific join algorithms like hash joins versus nested loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e598fb3-4f09-4ff7-985b-909a1ae82490', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the role of the ''Option'' type in Scala?', N'Fresher', N'The Option type is a container used to represent the presence or absence of a value, acting as a safer alternative to null references. It has two subclasses: Some, which contains a value, and None, which indicates that no value is present.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
