INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc70f1b1-0c74-4568-ac1f-90a14cffe6dc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the concept of an ''inverted index'' and why it is critical for Elasticsearch performance.', N'Middle', N'An inverted index is a data structure that maps terms to the list of documents where they appear, similar to an index in the back of a book. This structure allows Elasticsearch to perform extremely fast full-text searches by avoiding a linear scan of every document in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e242157-56ef-412a-bafa-90a3bdda6ff2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are stateless components?', N'Intern', N'If the behaviour of a component is independent of its state then it can be a stateless component. You can use either a function or a class for creating stateless components. But unless you need to use a lifecycle hook in your components, you should go for function components. There are a lot of benefits if you decide to use function components here; they are easy to write, understand, and test, a little faster, and you can avoid the this keyword altogether.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba2018d0-0602-4b3a-9fc4-90a3fbdfd116', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary purpose of Vite in a frontend project?', N'Junior', N'Vite is a build tool that provides a faster and leaner development experience for modern web projects. It acts as a development server and a bundler, significantly improving startup times by leveraging native ES modules in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd73e69c9-cdde-48ac-8eaf-90a42ee52d23', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When is it appropriate to introduce a caching layer, and what are the primary risks?', N'Senior', N'Introduce caching to reduce latency and database load for read-heavy operations, but be wary of cache invalidation complexity and stale data. Mitigate these risks by implementing robust TTL strategies, cache-aside patterns, and monitoring cache hit ratios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
