INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ca601c0-e94c-487c-a425-90a7acb87e87', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it important to use consistent HTTP status codes?', N'Middle', N'Consistent status codes provide a standardized way for clients to interpret the outcome of a request without parsing the response body. This enables generic error handling logic in client applications and ensures compatibility with standard HTTP caches and proxies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c995a687-5cac-4fdd-8291-90aaad9965d8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose a compiled language over an interpreted language for a system-level task?', N'Fresher', N'Compiled languages generally offer better performance and lower-level hardware control, which is essential for resource-intensive system tasks. Interpreted languages are better for rapid development and scripting where performance is less of a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc87010d-8548-48a4-9304-90ad0b8272dc', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the difference between ''display: none'', ''visibility: hidden'', and setting height/width to zero.', N'Middle', N'Display: none removes the element from the document flow entirely, meaning it takes up no space. Visibility: hidden hides the element visually but it still occupies space in the layout. Setting dimensions to zero may still render the element depending on overflow settings, which can lead to layout shifts or accessibility issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66c49fe0-3ac2-46ee-bdc9-90af70219cf7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the ''virtual'' keyword?', N'Fresher', N'The ''virtual'' keyword allows a method or property in a base class to be overridden in a derived class. It enables polymorphism, allowing the specific implementation to be determined at runtime based on the actual object type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a61b47b3-4b4d-4316-8985-90afc277ecd5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''readonly'' modifier used for?', N'Intern', N'The ''readonly'' modifier is used to make a property in an object or class immutable. Once a value is assigned to a read-only property, it cannot be changed or reassigned later in the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6f28fb5-7325-43a9-b842-90b13cdca9cb', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a Redirect in Fiber?', N'Fresher', N'A redirect is a response that instructs the client''s browser to navigate to a different URL. Fiber provides a simple method to perform both temporary and permanent redirects easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dbe6fe9-91c7-4182-85fb-90b2aa131c5b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is documentation considered an essential part of the engineering process?', N'Fresher', N'Documentation serves as a guide for other developers to understand the intent and functionality of the system without needing to read every line of code. It reduces the knowledge transfer time when new team members join and helps prevent long-term technical debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de9a4560-419e-4560-a9c6-90b467009ee6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What does ''Stateless'' mean in terms of HTTP?', N'Intern', N'Stateless means that every HTTP request is independent and contains all the information necessary to be processed. The server does not store any information about the client session between separate requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaf114a3-560f-4e20-8296-90b5888d17f9', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Is it possible to have multiple Redux stores in one application?', N'Middle', N'While it is technically possible, it is highly discouraged. Redux is designed with the assumption of a single store, and using multiple stores breaks the ability to use standard middleware, dev tools, and creates significant complexity in state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55c2607d-68c6-4484-a7e9-90b80eec2500', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you balance the need for perfection with the need to meet deadlines?', N'Junior', N'I focus on delivering a high-quality solution that meets the core requirements within the allocated time. I aim for ''good enough'' to be functional and maintainable, while noting potential improvements for future iterations if time allows. Perfectionism can lead to delays, so I prioritize delivering value and iterating based on feedback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03e3feac-2675-4776-b8a2-90b9410b1de7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a unary function?', N'Intern', N'Unary function (i.e. monadic) is a function that accepts exactly one argument. It stands for single argument accepted by a function. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43ea86bc-0b9b-4204-b49d-90baffce2c59', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut optimize dependency injection for large-scale modular applications?', N'Senior', N'Micronaut uses JSR-330 compliant dependency injection that is computed at compile time, creating an efficient graph of dependencies. This eliminates the need for runtime component scanning, which significantly speeds up application startup as the number of modules and beans increases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'581aafb8-5d82-4f2f-9f33-90bbb9fc473b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Describe the strategy Vite uses to handle CSS pre-processors and why it doesn''t require extra configuration for simple cases.', N'Senior', N'Vite includes built-in support for pre-processors like Sass or Less, provided the corresponding compiler is installed as a dependency. It automatically resolves the imports and injects the styles into the document head, abstracting the loader configuration complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edd6f92e-7a42-4dbb-bde7-90bfe0ba4fe6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the considerations for handling large file uploads in Express?', N'Middle', N'Handling large uploads requires streaming the data to avoid loading the entire file into memory, which would crash the process. Middleware like Multer is commonly used, as it provides efficient buffering and streaming capabilities while managing file storage locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db3f07ab-fc3f-4d88-82cd-90c4a821042f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the concept of ''Hydration'' and the common issues associated with mismatches between server and client rendering.', N'Senior', N'Hydration is the process where React attaches event listeners and state to the server-rendered HTML. Mismatches occur when the server-generated structure differs from the client-side initial render, often caused by non-deterministic data like timestamps or random IDs, leading to performance degradation or UI glitches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86976149-2f64-452e-a8a1-90c870e8c829', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it considered a best practice to avoid using Tailwind''s arbitrary values for primary design tokens?', N'Senior', N'Using arbitrary values for primary tokens bypasses the design system''s governance, leading to visual inconsistency and ''magic numbers'' in the UI. Primary tokens should be strictly defined in the configuration file to ensure they are constrained, discoverable, and easily updateable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d3a9f5b-3c3e-4589-9406-90c912c1e044', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of ''Any'' and ''AnyObject''?', N'Junior', N'Any can represent an instance of any type at all, including function types. AnyObject can represent an instance of any class type, which is useful when working with Cocoa APIs that expect objects rather than structs or enums.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'583b8828-c306-43b2-ab00-90ca4c7a6b35', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'When should you choose a pull-based consumer model over a push-based model?', N'Middle', N'A pull-based model is preferred when consumers have varying processing capacities, as it prevents overloading slower consumers. It allows the consumer to request messages at their own pace, providing better control over flow and backpressure management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e094e70b-b318-4f39-b2a3-90cc59c2533a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If you suspect an external service is causing an issue, how do you verify it?', N'Fresher', N'I would check the status page of the external service or attempt to perform a simple test request to see if it responds correctly. If the service is unreachable or returning errors, I can confirm the issue is external rather than within my own application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0398adb0-7692-4679-8a7a-90cc9146a419', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you define a ''successful'' outcome for a project?', N'Fresher', N'Success means the solution meets all defined requirements, is delivered on time, and is reliable enough for its intended users. It also includes ensuring the project was completed within the scope and is maintainable for future updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22a28252-7474-443d-a3f0-90ce906b953e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the AdonisJS Response object?', N'Intern', N'The Response object represents the HTTP response that the server sends back to the client. It provides methods to set the status code, content type, headers, and the body content, such as JSON data or rendered HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16fdc8d7-e4ff-4a19-9d91-90cf405aa688', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the ''res'' object in Express?', N'Intern', N'The ''res'' object represents the HTTP response that an Express app sends when it gets an HTTP request. It provides methods to send data back to the client, such as sending JSON, setting status codes, or rendering templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89088fc5-18b7-4560-8c5d-90d05f929dec', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between std::vector and std::list in terms of cache locality?', N'Middle', N'std::vector stores elements in a contiguous memory block, which results in excellent cache locality and fast access times. std::list uses linked nodes that are scattered in memory, causing frequent cache misses, which typically makes it less performant than a vector for most standard operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f56af8a-3781-4867-9962-90d186212a9a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle race conditions in asynchronous actions?', N'Senior', N'Race conditions occur when multiple asynchronous actions overlap, leading to an inconsistent final state. Redux addresses this by using middleware like Saga to cancel previous tasks, or by using unique request IDs and status flags in the state to ignore responses that arrive out of order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd59105a6-86ad-4555-b753-90d653502b61', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''Bulkhead'' pattern in architecture, and why is it useful?', N'Senior', N'The bulkhead pattern isolates system components into pools so that if one pool fails, the others continue to function. It prevents a failure in one area of the system from consuming all resources, effectively compartmentalizing the impact of the outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e97f109-c7a4-4e29-8902-90dadebd3553', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are wrapper classes and why are they needed?', N'Junior', N'Wrapper classes like Integer or Double convert primitive data types into objects. They are necessary when working with collections like ArrayLists, which can only store objects, not primitive values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
