INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d51861d-c65f-416a-beb8-90dfc3223c2e', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How can you implement prioritization in a messaging system that natively only supports FIFO?', N'Senior', N'Prioritization can be achieved by using separate queues for different priority levels (e.g., High, Medium, Low) and configuring consumers to poll them in a weighted fashion. This ensures high-priority messages are processed sooner without blocking the entire system on lower-priority tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa6e91e7-ca4c-4aad-9fae-90e0997d3b38', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the advantage of using ''r.Use'' at the root level vs. a sub-router?', N'Middle', N'Using ''r.Use'' at the root level applies middleware to every single request hitting the server, such as logging or panic recovery. Applying it to a sub-router ensures the logic only runs for specific segments of the API, reducing unnecessary execution for public or unauthenticated endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c2df379-53ed-43e0-8acd-90e12ec595c0', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus ensure security in native executables?', N'Middle', N'Quarkus integrates security extensions like OIDC and Elytron, which are optimized to work within the constraints of native images. By shifting security configurations to build time, it reduces the attack surface and ensures that security policies are strictly enforced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2aa838e-0055-461e-b38c-90e224896aea', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do you control visibility in Go?', N'Junior', N'Visibility is determined by the capitalization of the identifier name. If a name starts with an uppercase letter, it is exported and visible to other packages; if it starts with a lowercase letter, it is package-private.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
