INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad4b78f6-0d23-49b6-b379-90e4a7e4e092', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you join tables in DynamoDB?', N'Intern', N'No, DynamoDB does not support joins like relational databases. Data is typically modeled to fit access patterns so that all required information is available in a single item or can be retrieved through a single query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e82e18-c42a-4e0a-897b-90e554887200', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the purpose of HATEOAS in a RESTful architecture, and why is it often omitted in practice?', N'Middle', N'HATEOAS allows clients to discover available actions through links provided in the API response, creating a self-descriptive interface. It is often omitted because it increases payload size and implementation complexity, and most developers prefer static documentation like OpenAPI over dynamic link discovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
