INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8520fd64-250e-4cda-8e35-90f0bdc61435', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s ''refinement'' mechanism provide a safer alternative to monkey-patching?', N'Senior', N'Refinements limit the scope of class modifications to the specific file or module where they are activated, preventing global side effects. This architectural choice solves the fragility of traditional monkey-patching, where global changes can cause unpredictable conflicts across large codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78bd8b80-2f86-48d9-ba9e-90f1ad51edda', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s approach to property delegation differ from standard getter/setter overrides?', N'Senior', N'Property delegation separates the logic of property access from the property definition itself, allowing for reusable interceptors like lazy loading or observable patterns. This is superior to overriding getters and setters because it decouples the state management logic from the class implementation, promoting cleaner separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
