INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70946eb5-e1ac-48f5-81a0-90f33389031c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ''Compaction'' in a database engine impact system performance?', N'Senior', N'Compaction is the process of merging and cleaning up data files to remove obsolete records and reclaim space. While essential for long-term health and read performance, it is a resource-intensive background task that can lead to periodic spikes in CPU and disk I/O, potentially impacting application latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35d092f3-baa6-4472-b3b9-90f477912d71', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the trade-offs of using ''Provide/Inject'' versus a global state management library like Pinia in large-scale applications.', N'Senior', N'Provide/Inject is ideal for deep component tree dependency injection, such as theming or configuration, but lacks centralized debugging and dev-tool integration. Pinia provides a structured, reactive, and testable store architecture that is better suited for managing complex global application state across disparate parts of the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
