INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'044420a4-cd35-464a-ad9a-9106837c24a1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do Projection Expressions impact the performance and cost of read operations?', N'Senior', N'Projection expressions allow you to retrieve only a subset of attributes from an item, reducing the amount of data transferred over the network. While this does not reduce the Read Capacity Units consumed, it minimizes application-side processing and memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b6dd8e4-a2ac-4949-8ad4-9109db7fc5a8', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Domain-Driven Design'' (DDD) considered essential for defining microservice boundaries?', N'Senior', N'DDD helps identify ''Bounded Contexts'' which define the logical boundaries within which a domain model is consistent. Aligning microservices with these contexts prevents ''distributed monoliths'' by ensuring that services are grouped by cohesive business capabilities rather than technical layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37be7291-862c-4578-a4dc-910a22237160', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a ''ThreadLocal'' variable?', N'Middle', N'A ThreadLocal variable provides storage that is isolated to each individual thread. It allows threads to maintain their own unique data instance, preventing the need for locks when accessing data that should not be shared across threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32c3f296-5ab3-48f7-8feb-910b7342f101', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between ''External'' and ''Internal'' observability?', N'Senior', N'External observability focuses on the user experience and service-level objectives, usually measured via synthetic monitoring and black-box probes. Internal observability focuses on the health and performance of the infrastructure components themselves, typically using white-box metrics, logs, and distributed traces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be28f133-17b5-4cd1-9681-910cd8843bcc', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the benefits of using read replicas in a database architecture?', N'Middle', N'Read replicas offload read-intensive queries from the primary node, improving overall system performance and availability. This design allows the primary node to focus on write operations and provides a failover mechanism if the primary node becomes unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a04b47c5-8995-444c-9b30-910e5840a18a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''Result'' type in Swift?', N'Middle', N'The Result type is an enum that represents either a success or a failure, containing the associated value or error. It provides a type-safe way to handle asynchronous operations and error propagation compared to traditional error throwing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1875338e-d9c2-4394-a829-910fa45fb80b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s structural typing system differ from nominal typing systems, and what are the architectural implications for large-scale refactoring?', N'Senior', N'Structural typing determines compatibility based on the shape of objects rather than explicit declarations, which increases flexibility but can lead to unintentional valid assignments. In large systems, this requires developers to rely on branding or explicit interfaces to enforce domain boundaries, as the compiler does not distinguish between types with identical structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b554998f-1260-4980-8eda-9111aa1eb7fd', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between the ''entry'' and ''output'' properties in a Webpack configuration?', N'Intern', N'The entry property tells Webpack which file to use as the starting point to begin building its internal dependency graph. The output property tells Webpack where to emit the bundled files it creates and what name to give those resulting files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'202e24b5-62c8-459f-9615-9112d69a25dc', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix Channels used for?', N'Junior', N'Channels are a mechanism for real-time, bi-directional communication between the client and the server. They allow developers to push data to connected clients instantly, which is ideal for features like chat applications or live dashboards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'405a4d55-bd51-474d-b026-911502ae5387', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the overhead associated with ''Method Swizzling'' in Swift compared to Objective-C.', N'Senior', N'Swift does not support method swizzling natively because it relies on static dispatch and non-dynamic method tables for performance. Attempting to bridge this functionality requires using the Objective-C runtime via the dynamic keyword, which disables many of Swift''s compiler-level optimizations and increases runtime complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e74a7dc-8d68-4d30-b61f-9119b3672ae9', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of the Webpack ''tapable'' library in plugin architecture?', N'Senior', N'Tapable is a small library that provides the hook system used by Webpack to manage the plugin lifecycle. It allows developers to tap into specific stages of the compilation process, enabling the asynchronous orchestration of loaders and plugins throughout the build pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1a6fefd-8309-4823-a18b-911b558b8d07', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach deciding whether to add a new feature or spend time refactoring existing code?', N'Fresher', N'I look at the technical debt and the urgency of the feature. If the current code is too brittle to support the new feature safely, I prioritize refactoring to ensure stability. If the code is healthy, I focus on the feature while keeping an eye on where future refactoring might be needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6cd2b62-f2b2-4318-85d2-911b5f0bf890', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose a message queue over a direct API call for a task processing system?', N'Middle', N'A message queue provides load leveling and decoupling, ensuring that the system can handle spikes in traffic without failing. It also provides built-in retries and persistence, ensuring that tasks are not lost if the consumer service is temporarily unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
