INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e7f812f-8a5c-4ffb-97df-911ffaae1f03', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How should logging be implemented in a Gin application?', N'Middle', N'Logging is best handled by implementing a custom middleware that captures request metadata, such as latency, status code, and client IP. Using structured logging libraries instead of basic print statements is essential for effective log aggregation and analysis in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
