INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de0dad13-fbe2-472a-9786-9125617c7bc7', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of Astro''s static site generation for SEO?', N'Senior', N'SSG ensures that fully rendered HTML is served directly to search engine crawlers, eliminating the need for client-side execution to see content. This results in faster indexing and higher reliability for metadata, as there is no dependency on the client-side environment to construct the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'770f9f34-1aa3-423a-952d-9125cbf1a3de', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the significance of the microtask queue compared to the macrotask queue.', N'Middle', N'Microtasks, such as promise resolutions, have higher priority than macrotasks like setTimeouts. The event loop will process all pending microtasks immediately after the current task finishes and before moving on to the next macrotask, which can lead to starvation of the macrotask queue if microtasks are recursively added.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a25ebb5-2691-4b78-becb-9126e658de29', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''createResource'', and how does it integrate with the reactive system?', N'Senior', N'createResource is a primitive for handling asynchronous data fetching, wrapping a promise into a signal-like interface. It automatically integrates with Suspense and Error Boundaries, making it the standard approach for data fetching that needs to be reactive to changes in its input parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3751f4da-deec-4386-91ef-912877d2af23', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does the term ''cluster'' mean in Elasticsearch?', N'Intern', N'A cluster is a collection of one or more nodes that work together to store data and provide federated indexing and search capabilities across all nodes. It is identified by a unique name and ensures that data remains accessible even if individual nodes fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb62e9c6-757f-4c23-8677-9129a497a841', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s middleware stack differ from the standard net/http middleware approach?', N'Senior', N'Chi utilizes a specific middleware chain pattern that remains fully compatible with net/http, but it leverages a context-based approach for chaining. This allows middleware to pass state efficiently down the request lifecycle while maintaining standard library interoperability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e2a8b62-28c0-4636-9ca5-912a0c3ae8a8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s dev server differ from traditional bundlers like Webpack?', N'Intern', N'Traditional bundlers must bundle the entire application before starting the server, which gets slower as the app grows. Vite serves files over native ES modules, meaning it only transforms the specific files requested by the browser, making startup nearly instantaneous.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c5e5afb-6c8f-4c55-90c7-912b7ca2623e', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does it mean for a Service to be a singleton?', N'Junior', N'A singleton means that only one instance of the service exists for the entire lifetime of the application. This allows different components or routes to access and share the exact same state and data throughout the user''s session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68b0a5c1-7c3f-4a30-a930-912e2da857d5', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does the size of a cache impact its hit rate, and what are the diminishing returns?', N'Senior', N'Increasing cache size generally improves the hit rate by allowing more working set data to remain resident. However, the benefits follow a logarithmic curve where once the cache is large enough to hold the most critical hot data, adding more capacity provides negligible improvements in latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0619caa7-f81e-4664-9074-912e40f6e3f7', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the +error.svelte file used for?', N'Intern', N'This file is a specialized component that SvelteKit renders when an error occurs during page loading or navigation. It allows you to provide a custom UI to the user instead of displaying a generic browser error page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e98a21f0-89e4-4f82-bbc5-912f5d215964', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C translation unit structure impact build times?', N'Middle', N'Each C file is compiled independently into an object file, meaning a change in one file only requires recompiling that specific unit rather than the entire project. However, heavy reliance on large header files included in every translation unit can significantly increase the total preprocessing and compilation time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4d95ea6-614e-4048-bfe1-913018a03c6e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Future'' abstraction and how does it handle concurrency?', N'Middle', N'A Future represents a value that may be available at some point in the future, allowing for non-blocking asynchronous computations. It relies on an ExecutionContext to manage thread pools, separating the logic of the task from the mechanical details of thread scheduling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4661d53-5c7b-4f21-bad7-9130b3ee71c3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why would an architect choose to implement ''Event Sourcing'' instead of traditional CRUD operations?', N'Senior', N'Event sourcing stores the sequence of state-changing events rather than the current state, providing a complete audit trail and the ability to reconstruct state at any point in time. It is highly effective for complex domain models but introduces challenges regarding data versioning and event replay performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a176e757-6006-4f0b-aa5d-9131a788caa2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the concept of ''Declaration Merging'' and how it impacts module architecture.', N'Senior', N'Declaration merging allows the compiler to combine multiple declarations with the same name into a single definition. This is critical for extending third-party libraries or augmenting global interfaces, though it requires careful management to avoid namespace collisions and unexpected side effects in large codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bfb209b-e0c9-434d-bb4e-913268bb02ac', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a Singleton and a Scoped service?', N'Intern', N'A Singleton service is created once the first time it is requested and lives for the entire application duration. A Scoped service is created once per client request, meaning all components within the same request share the same instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f702e98-fb76-4f64-9ad2-913648ac5b26', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is Rust considered a ''systems programming'' language?', N'Fresher', N'Rust provides low-level control over hardware and memory layout, similar to C or C++. It achieves this while maintaining high-level abstractions and memory safety guarantees that prevent entire classes of bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f3d9f12-62d9-45e5-8484-913683db3719', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle capacity management with On-Demand mode versus Provisioned mode?', N'Middle', N'Provisioned mode requires you to specify the number of reads and writes per second, which is cost-effective for predictable workloads. On-Demand mode automatically scales throughput to accommodate traffic spikes, making it better for unpredictable or sporadic workloads, albeit at a higher cost per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41b774da-6609-427b-8f98-91374b49ae6c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain how data partitioning works in Redis Cluster.', N'Middle', N'Redis Cluster uses hash slots to distribute data, where the total keyspace is divided into 16,384 slots mapped to different nodes. When a client performs an operation, the key is hashed to determine its slot, and the cluster redirects the client to the node responsible for that specific slot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e90df9-31b4-4998-ac7b-9138690510ca', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the benefit of using ''readonly'' properties in TypeScript?', N'Middle', N'The ''readonly'' modifier prevents properties from being reassigned after initialization, ensuring immutability for specific data structures. This helps prevent accidental state mutations, which is particularly beneficial when managing application state or passing objects as configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bad45d4f-a065-419e-ab5d-91389a0c9ea8', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the primary difference between a message queue and a pub/sub model?', N'Middle', N'In a message queue, each message is typically delivered to only one consumer, ensuring point-to-point communication. In a pub/sub model, a message is broadcast to all active subscribers of a specific topic, enabling one-to-many communication patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
