INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8059777-e275-4343-adae-915c1b8f160e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a table and a view?', N'Junior', N'A table is a physical structure that stores data directly on the disk. A view is a virtual table that is based on the result of a query, providing a simplified or filtered way to look at data without storing it separately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73dfd70d-e418-4a03-919e-915da909a6b8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis key and how should you structure it for best performance?', N'Intern', N'In Redis, a key serves as the primary identifier for data storage. Efficient key design is crucial for advanced performance. Key Naming Conventions - Keyspace Segmentation: Categorize keys logically, such as by user. This practice optimizes operations like DEL or KEYS under a subset. - Consistent Naming: Use a standardized format, e.g., "RESOURCE:ID". Key Length and Complexity - Minimize: Short and simple keys reduce memory and lookup time. - Avoid Repetition: Using a consistent prefix reduces redundancy, but excessive repetition can be counterproductive. Data Encoding - Redis distinguishes between direct (explicit) and indirect (implicit) encodings. Explicit encoding is preferred for performance and clarity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e70a2c84-2dc3-4448-8437-915e8dcef401', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the role of the Metaspace in modern Java versions and how it differs from PermGen.', N'Senior', N'Metaspace stores class metadata and resides in native memory rather than the heap, allowing it to grow dynamically based on system availability. Unlike PermGen, which was a fixed-size heap area that frequently caused ''OutOfMemory'' errors, Metaspace is self-tuning and reduces the risk of memory exhaustion during class loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0867f072-b4a6-446d-a92c-915f19f202c5', N'4c000000-0000-0000-0000-000000000005', N'Explain the trade-offs between using a SQL database and a NoSQL database.', N'Middle', N'SQL databases are relational and offer strong ACID compliance, making them ideal for structured data requiring complex transactions. NoSQL databases offer higher scalability and flexibility with schema-less data models, which is beneficial for rapidly changing data structures or massive datasets where horizontal partitioning is necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ff30fb1-f6ec-40d4-946e-915fb0d05c0a', N'075b8862-431c-4678-9767-f55359758a4a', N'Describe the mechanism behind ''Teleport'' and why it is essential for modern UI design.', N'Senior', N'Teleport allows a component''s template to be rendered in a different part of the DOM tree while maintaining the component''s logical context and reactivity. This is crucial for accessibility and styling, as it enables modals, tooltips, and notifications to exist at the root level while remaining controlled by the parent component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'492d65fa-3ca0-402a-903d-915fee28263f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''strictFunctionTypes'' flag alter the behavior of function parameter contravariance?', N'Senior', N'With the flag disabled, TypeScript treats function parameters as bivariant, which is unsound but convenient. Enabling it enforces contravariance, where a function can only be assigned to a variable if its parameters are equal or wider, preventing runtime errors caused by passing incompatible types into callback signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f812708-c108-46d6-ae40-91636a53bbba', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle DOM events?', N'Intern', N'Svelte uses a standard syntax to listen for DOM events directly on elements. You can attach event listeners to elements to trigger functions in your script whenever a user interacts with the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
