INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac149e86-68c6-4d69-92bf-9165a4f81d13', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does it mean for Swift to be a compiled language?', N'Intern', N'Being a compiled language means that Swift source code is translated directly into machine code by the compiler before the program is executed. This process allows the application to run directly on the processor, generally resulting in higher performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dd1d4d3-1a6b-41b0-a25b-91675eb53d43', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the significance of the DRY principle in software engineering?', N'Fresher', N'The DRY (Don''t Repeat Yourself) principle aims to reduce duplication by ensuring that every piece of information or logic has a single, unambiguous representation. This makes the system easier to maintain and reduces the likelihood of bugs caused by updating one instance of logic but forgetting others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
