INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a37d60e-c135-4226-ad96-917425f339ac', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Compare the performance and memory overhead of list comprehensions versus generator expressions.', N'Senior', N'List comprehensions create the entire collection in memory immediately, which is faster for small datasets but memory-intensive for large ones. Generator expressions use lazy evaluation, producing items one at a time, which significantly reduces memory footprint. This makes generators ideal for processing large streams of data where the entire sequence does not need to reside in RAM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
