INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce15c84a-4155-4a56-98e2-918490563a00', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the architectural advantage of using the ''CQRS'' module in NestJS?', N'Senior', N'The CQRS module separates read and write operations, allowing for independent scaling and optimization of database queries versus command processing. This is particularly beneficial in event-driven systems where write operations might trigger complex side effects like event sourcing or notifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1018fe7c-9663-4e3d-bcfa-9185a9044e47', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do you handle memory exhaustion in Redis?', N'Middle', N'Redis handles memory exhaustion through eviction policies, which define how the system should remove keys when the ''maxmemory'' limit is reached. Policies range from ''noeviction'' that returns errors, to ''allkeys-lru'' which removes the least recently used keys, allowing the system to continue functioning under constrained memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1ddf9ab-e15d-4db3-9365-918e1ca28e13', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Is Fiber suitable for small, hobbyist projects?', N'Junior', N'Yes, Fiber is highly suitable for hobbyist projects because it is easy to set up and provides a rich set of features out of the box. Its high performance is an added benefit even for smaller applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'179a4d2c-cc1b-41b3-bff0-918ec642f774', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between an Environment in Symfony and how is it used?', N'Junior', N'Environments allow you to use different configurations for different stages of development, such as dev, test, and prod. They enable features like detailed debugging information in development while ensuring maximum performance and security in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdeafabb-d947-4f1e-ae25-918f56e1b92d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Option'' type improve type safety compared to using null values in other languages?', N'Middle', N'The Option type forces developers to explicitly handle the absence of a value, moving the check from runtime to compile time. By using pattern matching or functional combinators like map and flatMap, you eliminate the risk of unexpected null pointer exceptions, making the codebase significantly more robust and self-documenting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d3583fa-47d0-4d2f-80f3-918f6e01a759', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Undo Log'' support MVCC (Multi-Version Concurrency Control)?', N'Middle', N'The undo log stores the older versions of data that are modified by active transactions. MVCC uses these logs to allow concurrent reads to access a consistent snapshot of the data as it existed before the modifications, enabling high concurrency without locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89da2fa4-d3fb-42a1-95d9-91914ba8c62d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with two different ways to solve a problem, how do you choose the right one?', N'Junior', N'I evaluate both options based on factors like simplicity, maintainability, performance, and the time required to implement them. I often lean toward the solution that is easier to read and maintain, as this reduces technical debt. If the trade-offs are significant, I discuss both options with a senior team member to get their input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'923074ab-0c61-4086-bbba-9196ec2f9de4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the data frame in R?', N'Junior', N'A data frame is a tabular data structure used to store data in rows and columns, similar to a spreadsheet. It is the standard way to represent datasets in R because each column can hold different types of data while all rows must have the same length.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdfe9527-eb4e-497e-8d2a-9197af68f7ad', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does ''web::scope'' help in organizing large Actix-web applications?', N'Middle', N'Scopes allow you to group related routes under a common path prefix and apply specific middleware or configurations to that entire group. This promotes modularity and makes it easier to manage complex routing structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58274f07-085e-4426-86f2-9197b2544543', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'When would you prefer pull-based consumers over push-based consumers?', N'Middle', N'Pull-based systems allow consumers to control their own processing rate, preventing them from being overwhelmed by a fast producer. Push-based systems generally provide lower latency as messages are delivered as soon as they arrive at the broker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'372031cd-4682-41eb-a585-919a44331d21', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the various url properties of location object', N'Intern', N'The below Location object properties can be used to access URL components of the page, 1. href - The entire URL 2. protocol - The protocol of the URL 3. host - The hostname and port of the URL 4. hostname - The hostname of the URL 5. port - The port number in the URL 6. pathname - The path name of the URL 7. search - The query portion of the URL 8. hash - The anchor portion of the URL', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e51a8182-f8fa-4b59-8bf3-919a527a4009', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the importance of version control in a team environment?', N'Junior', N'Version control allows multiple developers to work on the same project simultaneously without overwriting each other''s changes. It provides a history of modifications, making it easy to revert to stable versions if something goes wrong and facilitating collaboration through branches and pull requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
