INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c9170db-6ea6-49fb-bada-919b58b7666e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How should one approach versioning an API built with FastAPI?', N'Senior', N'Versioning in FastAPI can be achieved via URL path prefixing, custom headers, or sub-applications using the ''APIRouter'' mount functionality. Using sub-applications is the most architectural-sound method as it allows for isolated dependency trees and distinct configurations for different API versions within the same process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
