INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a96a37ff-72dc-4ded-8384-91ad09090a1f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the Garbage Collector (GC) in C# and how do generations work?', N'Middle', N'The GC manages heap memory automatically by identifying and reclaiming unreachable objects. It uses generations—0, 1, and 2—to optimize performance; newer objects are collected more frequently, while long-lived objects move to higher generations, which are scanned less often to reduce latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e04571d-7ff5-460b-aa46-91af257542ae', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is the FastBoot environment technically challenging to implement in Ember?', N'Senior', N'FastBoot requires running Ember in a Node.js environment, which lacks native browser APIs like the DOM, window, or local storage. Developers must ensure code is isomorphic, meaning they must carefully guard access to browser-specific globals to avoid crashes during server-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f36c0e6-d338-4d24-8e0c-91b0171764bb', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix achieve faster page transitions?', N'Intern', N'Remix fetches data in parallel as soon as a user clicks a link, rather than waiting for the new page to load first. This minimizes the time spent waiting for content and makes the app feel highly responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a2109ce-0427-46e4-b4f5-91b17227ef10', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the significance of the ''reactive declaration'' syntax?', N'Middle', N'The reactive declaration allows you to define variables that automatically recompute whenever their dependencies change. By using a specific syntax, you inform the compiler to treat that variable as a derived dependency, ensuring data consistency across the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a21b193-407b-4d03-ae9e-91b341c87f89', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle breaking changes in a shared internal library?', N'Senior', N'I enforce semantic versioning and maintain multiple versions of the library in parallel during a transition period. I utilize deprecation warnings and automated deprecation tracking to alert teams, providing a clear migration path before removing the old version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'110fba1e-d67a-4f32-abd9-91b5929abe68', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Global Module in NestJS?', N'Intern', N'A global module is a module that is registered globally, making its exported providers available throughout the entire application without needing to import the module in every feature module. It is created using the @Global decorator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2b4b2e-5b24-4325-8296-91b7f02bd79a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the impact of database normalization on write versus read performance.', N'Senior', N'Normalization minimizes data redundancy by splitting tables, which optimizes write operations and ensures data integrity by preventing update anomalies. However, it often forces the database to perform expensive joins during read operations, which can degrade performance compared to denormalized structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e29c317d-0062-4f36-8c33-91b9d5325d98', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why might you use Redis as a primary database instead of a cache?', N'Middle', N'Redis can serve as a primary database when the data model fits simple key-value or collection structures and speed is the absolute priority. By enabling AOF persistence, it offers enough durability for many use cases while maintaining the performance advantages of in-memory storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2867062f-33ab-44eb-bf02-91bab17bdd5d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are given a vague request, how do you handle it?', N'Intern', N'I would ask clarifying questions to narrow down the scope, objectives, and deliverables. I would then summarize my understanding back to the requester to ensure we are in agreement before I begin the actual work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db10837-5154-479a-8c5e-91bc5b1d99a2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between JavaScript and TypeScript?', N'Intern', N'JavaScript is a dynamically typed language, meaning types are checked at runtime. TypeScript adds an optional static type system to JavaScript, which is checked during development before the code is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'413ba020-9240-4edd-9ac6-91bd25e45f25', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the significance of ''Associated Types'' in Swift protocols?', N'Middle', N'Associated types act as placeholders for a type used within a protocol, allowing the protocol to be generic. This makes protocols flexible, as the conforming type can define the specific implementation of that placeholder to suit its needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2760669d-6404-47fc-a102-91bd505e58fd', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence the choice between a client-side and server-side rendering strategy?', N'Intern', N'Server-side rendering is often better for SEO and initial page load speed, as the browser receives a fully rendered page. Client-side rendering provides a more dynamic, app-like user experience but requires more initial processing time on the user''s device.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'650238cc-7315-46ad-b513-91c3d7b6c262', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass handle variable scoping in the context of the @use and @forward rules?', N'Senior', N'With the modern @use module system, variables are scoped to the file they are defined in and are accessed via namespaces. This prevents the global namespace pollution common in the legacy @import system, ensuring that variables, mixins, and functions are encapsulated and explicitly imported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c883df2a-2edc-40cc-b480-91c5c7eee04d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between a Route and a Template?', N'Junior', N'A Route handles the logic of what to load and which data to provide, while the Template defines the visual representation of that data. You cannot have a route-specific template without a corresponding route file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a748b4bb-7846-4800-8b0d-91c6704c5fad', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the ''Type-level programming'' capabilities in Scala affect compile-time performance?', N'Senior', N'Extensive use of type-level programming, such as recursive implicit search or complex path-dependent types, exponentially increases the workload on the Scala compiler. This can lead to significantly longer build times and high memory usage during compilation. Architects must balance the benefits of compile-time safety and expressive DSLs against the practical constraints of developer productivity and CI/CD throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b54a583-4ad2-46aa-bea7-91c680684939', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of using the Next.js ''Image'' component over a standard HTML ''img'' tag?', N'Fresher', N'The Image component provides performance benefits like automatic lazy loading, prevent layout shifts, and serving responsive image sizes. Standard HTML tags do not provide these optimizations, which can result in slower page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cbea93a-7c53-42d7-8b49-91c890687972', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is WebSQL?', N'Intern', N'WebSQL is a deprecated browser API that provided a relational database using a variant of SQLite directly in the browser. It allowed web pages to use SQL queries (SELECT, INSERT, UPDATE, DELETE) on a local client-side database. Status: Deprecated and removed WebSQL was never standardized by the W3C. It was rejected in favor of IndexedDB and was removed from Chrome in 2024 and has not been supported in Firefox or Edge for many years. Basic WebSQL usage (historical reference): Why WebSQL was deprecated: 1. It was based on SQLite, which tied the spec to a specific SQL dialect 2. No browser other than WebKit-based browsers implemented it 3. The W3C stopped working on it in 2010 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcf18bce-2563-4d5e-8ae8-91c8f96481aa', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a Django signal and a model''s save method, and when should you prefer one over the other?', N'Middle', N'The save method is part of the model''s lifecycle and is best for data validation or logic tightly coupled to the specific model instance. Signals provide a decoupled way to trigger actions in response to events across the entire application, making them better for side effects like sending emails or updating caches without bloating model code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c56c9cc8-bfd2-41d3-9ccc-91c988d8dd9c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How does database indexing improve performance?', N'Intern', N'Database indexing creates a separate data structure that allows the database engine to find rows much faster without scanning every single record. While it speeds up read operations, it can slightly slow down write operations because the index must be updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc3f89d7-84e1-41bd-ad9f-91ca12e42a8e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik use a Virtual DOM?', N'Intern', N'Qwik does not rely on a traditional Virtual DOM in the same way as frameworks like React. Instead, it uses a unique approach that focuses on direct DOM updates and efficient tracking of state changes to achieve high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e29ce772-723a-4a36-b8ee-91cb55b3eaa8', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why would a senior developer choose Ember over a more lightweight library for a large-scale project?', N'Senior', N'Ember provides an ''opinionated'' architecture that eliminates decision fatigue regarding state management, routing, and testing. For large teams, this standardization ensures that all developers follow the same patterns, drastically reducing the cognitive load and maintenance costs as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9b3dc1a-0621-4e70-8339-91cbeef17d1f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is monomorphization and how does it affect binary size?', N'Middle', N'Monomorphization is the process where the compiler generates specialized machine code for each concrete type used with a generic function. While this allows for highly optimized execution, it can lead to increased binary size due to the duplication of code for every type instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdd3f7b8-3d1f-43df-a769-91cd2fac0eaf', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the common usecases of useRef hook?', N'Intern', N'Some of the common cases are: * Automatically focus an input when a component mounts. * Scroll to a specific element. * Measure element dimensions (offsetWidth, clientHeight). * Control video/audio playback. * Integrate with non-React libraries (like D3 or jQuery).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'452fe3c9-8df8-4f02-bdf7-91cfbcddfde7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis multi-threaded?', N'Intern', N'Historically, Redis was single-threaded, meaning it processed one command at a time. While recent versions have introduced multi-threading for specific background tasks, the core command processing engine remains primarily single-threaded to avoid lock contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02ae77f6-432d-447a-9d40-91d025609edf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a bug that you cannot reproduce?', N'Intern', N'When a bug is intermittent, you should gather as much telemetry and log data as possible during the failure. Examining patterns in environment variables, user actions, or system load can help reveal the hidden conditions causing the issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f798f059-e083-45ef-b742-91d16e690b94', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the primary risk of applying a quick fix without understanding the underlying cause of a problem?', N'Intern', N'Applying a quick fix often masks the symptoms rather than resolving the root cause, which can lead to the bug reappearing later. Additionally, such fixes may introduce side effects or technical debt that make the system harder to maintain in the long run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5df09128-23e2-4101-9ab8-91d3373c48bc', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do Service Providers work in Laravel?', N'Fresher', N'Service Providers are the central place of all Laravel application bootstrapping. They are responsible for binding services into the service container, registering event listeners, middleware, or routes, and configuring various components of the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'696b183d-8995-441e-a268-91d49a1cb4bf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you investigate a service that is consuming more CPU than expected without an increase in traffic?', N'Senior', N'I would look for infinite loops, inefficient algorithm complexity introduced by recent changes, or excessive background tasks like logging, polling, or scheduled cleanup jobs. I would use profiling tools to identify the most CPU-intensive methods and evaluate if recent configuration changes increased the frequency of these operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd11ac38f-4083-417b-906b-91d5a6bf5441', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide between fixing a bug quickly versus taking more time to find the root cause?', N'Fresher', N'I would prioritize a quick fix only if the system is currently broken for users and requires immediate relief. However, I would follow up as soon as possible to identify the root cause to ensure the problem does not recur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd56b873d-1a10-4660-8385-91d5c0a8b1fe', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary advantage of using Hono compared to traditional Node.js frameworks like Express?', N'Junior', N'Hono is designed to be lightweight and runtime-agnostic, meaning it runs efficiently on various platforms like Cloudflare Workers, Bun, and Deno, not just Node.js. It achieves high performance by utilizing the Web Standards API, such as the Fetch API, which makes it significantly smaller and faster for edge computing environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01735418-7ff6-4eba-94f0-91d7429ee180', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is meant by ''Loose Coupling''?', N'Intern', N'Loose coupling is a software design approach where components are independent and have little knowledge of the inner workings of other components. In Spring, this is achieved through dependency injection, allowing components to interact through interfaces rather than concrete implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5c98beb-297c-4086-b33d-91d876fc45db', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do Python descriptors work and when should they be used?', N'Middle', N'Descriptors are objects that define how attribute access is managed via __get__, __set__, or __delete__ methods. They are used to implement properties, methods, and static methods, providing a clean way to intercept and customize attribute access logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b66dfd27-e5e5-4b9d-ae96-91d968c1a049', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Discuss the performance impact of reflection in Gin''s validator.', N'Senior', N'Gin uses the ''go-playground/validator'' package, which relies heavily on reflection to inspect struct tags. While this allows for powerful declarative validation, it is computationally expensive; in ultra-low latency services, custom validation logic can be faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cda5b979-cda6-4089-88f1-91dc7a526ff6', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do performance budgets help in software architecture?', N'Middle', N'A performance budget sets a threshold for metrics like page load time or API latency that the team agrees not to exceed. It helps shift reliability to the left by forcing teams to address performance regressions before they reach production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aca1f93f-c9fe-4f71-b2a8-91deda0b5abf', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the concept of ''Sub-Applications'' in FastAPI and how they facilitate architectural scaling.', N'Senior', N'Sub-applications allow you to mount independent FastAPI instances under a specific path prefix. This pattern is essential for modularizing large codebases, allowing teams to own and deploy different parts of the API as separate logical units while sharing a single entry point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b93f4730-b79a-454b-80b6-91e0666dac48', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the concept of an attack surface.', N'Middle', N'The attack surface represents the sum total of all points where an unauthorized user can attempt to enter data to or extract data from an environment. Reducing the attack surface by disabling unnecessary services and closing unused ports is a fundamental security strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d54cc60-b421-49a2-b577-91e1c56e0fda', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Discuss the challenges of implementing Microservices in NestJS using the default Event Bus versus external message brokers.', N'Senior', N'The default in-memory event bus is limited to single-node communication and lacks persistence, making it unsuitable for distributed systems. Using external brokers like RabbitMQ or Kafka provides the necessary durability, message acknowledgement, and horizontal scalability required for reliable inter-service communication in a microservices architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bc23fd3-9d1b-4b95-bc01-91e465e7d097', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Describe how to model one-to-many relationships in DynamoDB.', N'Senior', N'One-to-many relationships are typically modeled using adjacency lists, where related items share a partition key and are differentiated by their sort key. This allows all related entities to be retrieved in a single efficient query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a73ed1f6-8f3f-426e-9487-91e765046ae0', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the benefit of using an abstraction layer (like a controller pattern) over writing logic directly in route handlers?', N'Senior', N'Moving logic into dedicated controllers decouples the business logic from the transport layer (HTTP). This allows for easier unit testing, better reusability of logic across different interfaces like CLI or Pub/Sub consumers, and improved maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb84f73b-49a1-4bc7-8826-91e7b21bab5a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle conditional rendering?', N'Fresher', N'SolidJS uses a built-in Show component to handle conditional rendering. This component efficiently manages the mounting and unmounting of its children based on a reactive boolean condition provided to it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45d84f62-80e4-4f8d-92b6-91e9c5f42be4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the role of the NAMESPACE file in an R package?', N'Middle', N'The NAMESPACE file defines which functions from a package are exported for the user and which functions from other packages are imported. This prevents namespace collisions and ensures that the package has access to all necessary dependencies without cluttering the user''s workspace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6159b9a8-2498-47cf-8285-91eccd76f647', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the role of ''Alpine.data'' and why is it preferred over inline objects?', N'Middle', N'The ''Alpine.data'' helper allows developers to extract component logic into reusable objects. This improves maintainability, makes testing easier, and keeps the HTML markup uncluttered, which is a significant architectural improvement over placing large objects directly in the ''x-data'' attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d4b9def-913c-49cd-9571-91ed7e4313df', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s approach to DOM diffing compare to the Virtual DOM model?', N'Senior', N'Lit does not use a virtual DOM; instead, it tracks the specific DOM nodes associated with dynamic expressions. By keeping references to these ''parts'', Lit updates only the changed content directly, which is generally more memory-efficient than maintaining a full virtual tree representation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'421cb4dc-1f1b-4e07-81cc-91eead5ff7ee', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between ''shallow'' and ''deep'' monitoring of Node.js applications?', N'Middle', N'Shallow monitoring tracks basic metrics like uptime and CPU usage, while deep monitoring involves instrumenting the code to track internal function execution times and database query performance. Deep monitoring is essential for identifying specific performance bottlenecks within the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1be5907-cac1-4f00-9532-91eec10d2188', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a Template Helper in Ember?', N'Intern', N'A Template Helper is a function that can be used inside Handlebars templates to perform simple transformations or logic. They help keep templates clean by moving small, repetitive formatting tasks out of the main logic and into reusable functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32fbd673-3dc5-4229-b5cf-91f6c1503823', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Describe the impact of jQuery''s global $ object on enterprise-level application architecture.', N'Senior', N'The global $ namespace creates a significant risk of version conflicts, especially when multiple third-party libraries or legacy codebases attempt to coexist. This lack of isolation forces developers to rely on complex conflict-resolution strategies, whereas modern modular systems offer scope isolation by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bea420aa-6d4b-4b18-b2ac-91fa6856d357', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How do you add an alias to import paths in Vite?', N'Junior', N'Aliases can be defined in the resolve.alias section of the vite.config.js file. This allows you to create shortcuts for long or deeply nested directory paths, making imports cleaner and easier to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6d81817-e979-4d6e-b846-91fcf4eaa301', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does it mean that Ruby is a pure object-oriented language?', N'Fresher', N'In Ruby, everything is treated as an object, including primitive data types like numbers, booleans, and nil. Every value has methods and properties associated with it, which allows for consistent behavior across all data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bab9ec30-2ad0-4282-9321-91fffe6c9932', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle the Virtual DOM compared to React?', N'Junior', N'Preact uses a highly optimized diffing algorithm to update the DOM. While both libraries use a Virtual DOM to minimize direct updates, Preact''s implementation is designed to be as lightweight as possible while maintaining compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb802f1-26d4-43b2-bfef-92027967fbc3', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is CSS BEM?', N'Intern', N'The BEM (Block Element Modifier) methodology is a naming convention for CSS classes in order to keep CSS more maintainable by defining namespaces to solve scoping issues. A Block is a standalone component that is reusable across projects and acts as a "namespace" for sub components (Elements). Modifiers are used as flags when a Block or Element is in a certain state or is different in structure or style. Example: Benefits: * Modularity: Block styles are never dependent on other elements on a page, so you will never experience problems from cascading. * Reusability: Composing independent blocks in different ways, and reusing them intelligently, reduces the amount of CSS code that you will have to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'112f4fc9-40b0-4057-8ee8-920527cff97f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a transaction?', N'Intern', N'A transaction is a single unit of work that consists of one or more database operations. It ensures that a series of operations are either all completed successfully or none of them are applied, maintaining data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf57de26-c089-4dd7-8034-920814dd3c2b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does the ''Sidecar'' pattern enhance the scalability and maintainability of microservices?', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like logging, service discovery, and traffic encryption to a separate container residing alongside the application. This allows the core service to remain focused on business logic while enabling consistent infrastructure updates across the fleet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1291d898-fc39-40ab-bf14-9209d2ee6dbe', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle browser caching?', N'Fresher', N'Because Qwik breaks the application into many small, distinct chunks, browsers can cache these individual pieces effectively. If a small part of the application changes, only that specific chunk needs to be re-downloaded by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5322e837-699e-4c8c-b05b-920a6c74d526', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is a package in Dart?', N'Intern', N'A package is a bundle of code that can be shared and reused across different projects. It typically contains a set of related classes, functions, and resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eea99952-92cf-4304-ab7f-920d77cd6189', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis schema-less?', N'Fresher', N'Yes, Redis is schema-less. You do not need to define a structure for your data before saving it, allowing for high flexibility in how data is stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a07df9-6b78-4e75-bbae-920dd132ee56', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the key principles of inheritance in Swift?', N'Intern', N'Inheritance is a central concept in Object-Oriented Programming (OOP) that allows classes to inherit characteristics from other classes. Swift has a single-inheritance model. Key Principles Limited to a Single Superclass In Swift, each class is explicitly derived from one, and only one, superclass. However, it''s still possible to have multiple subclasses associated with the same superclass. This helps keep the class hierarchy easily understandable, preventing complexities that arise from multiple inheritance. Unavoidable Inheritance Chain Even if a class is explicitly declared with no superclass, it still indirectly inherits from Swift''s base class, Any. Fundamental Base Class: "Any" Swift''s "Object" counterpart, Any, is the base class for all other classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72c8081b-8360-4b92-9fe6-92137cb983ee', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the performance impact of using too many Sass mixins.', N'Senior', N'Overusing mixins can lead to significant code duplication in the compiled CSS, as every instance of a mixin generates a fresh set of rules. This increases the total file size, which can negatively impact page load performance, especially on mobile devices with limited bandwidth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42a2d6e3-4ab5-4a39-85ee-9213c48954f7', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the strategy for horizontal scaling of Laravel applications when dealing with session state.', N'Senior', N'Since local file-based sessions are not shared across servers, horizontal scaling requires moving session storage to an external, high-performance distributed store like Redis or Memcached. This ensures that session state remains consistent regardless of which application server handles the incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db6e9872-ab3b-4cbe-9142-9214528b7dd5', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the concept of type hinting in PHP.', N'Junior', N'Type hinting allows developers to specify the expected data type for function arguments and return values. This improves code reliability and IDE support by catching type-related errors before the code is even executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f198b72d-17c6-4ce4-9437-9214532cb904', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between static and dynamic linking, and how does it affect the final executable?', N'Middle', N'Static linking copies all library code into the final executable, resulting in a larger file that is independent of external dependencies. Dynamic linking keeps library code separate, requiring the OS to load shared libraries at runtime, which allows for smaller files and easier updates to shared code without recompiling the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d78461e-92b6-4961-a098-921485a611bd', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Under what specific conditions would you recommend against using Fiber for a Go backend project?', N'Senior', N'I would recommend against Fiber if the project requires strict adherence to HTTP specification edge cases, needs to use a vast existing middleware library, or if the development team lacks the expertise to manage the nuances of object pooling and memory safety in Go.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c065fa37-0604-4dc8-9ab0-9221fd5fb64d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between using a simple, readable solution versus a complex, highly optimized one?', N'Fresher', N'You should prioritize maintainability and code clarity for long-term project viability unless performance profiling shows a specific bottleneck. Simple code is easier to debug and update, which reduces the cost of ownership.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95858eb5-e5dc-49e3-b4f6-92238c0a9494', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the value of a ''proof of concept'' before starting a full-scale project?', N'Fresher', N'A proof of concept allows the team to validate that a proposed technical approach is feasible before committing significant time and resources. It helps identify major risks and technical blockers early in the development cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
