INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2b569d0-5d34-480c-bbbd-922a2fc62404', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between immediate feedback in continuous integration and the depth of test coverage?', N'Junior', N'Running a large test suite ensures high confidence and broad coverage, but it takes a long time and slows down the development cycle. Running only a subset of critical tests provides fast feedback, but risks letting bugs slip through that are only caught by the full suite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
