INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b28835b-2a7e-483a-a8f9-922b4bbc581d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How to achieve pixel perfect design in HTML/CSS?', N'Fresher', N'Pixel perfect design means implementing a UI that matches the designer''s mockup precisely — every margin, padding, font size, color, and spacing aligns exactly with the design specification. 1. Use the correct base styles Reset browser defaults to eliminate inconsistencies across browsers: 2. Match the design''s spacing system Use a consistent spacing scale (e.g., 4px or 8px grid): 3. Use exact font settings from the design 4. Match colors exactly Copy hex/rgba values directly from design tools (Figma, Sketch, XD): 5. Use a design overlay extension Browser extensions (e.g., PerfectPixel for Chrome/Firefox) let you overlay the design mockup directly on top of the browser — you can adjust opacity to compare pixel by pixel. 6.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2308c71-c75d-4871-909b-922c99c7e1fb', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the trade-offs of using Kestrel as an edge server versus placing it behind a reverse proxy like Nginx or IIS.', N'Senior', N'While Kestrel is highly performant, it lacks some robust edge security features like advanced request filtering, SSL offloading, and sophisticated rate limiting. Placing Kestrel behind a reverse proxy provides an additional layer of security, load balancing, and static file optimization, which is standard practice for production-grade deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
