INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec1b2375-6265-458c-8acf-92328e934489', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why might you use an embedded container like Tomcat in Spring Boot instead of deploying a WAR to an external server?', N'Middle', N'Embedded containers simplify the deployment process by packaging the entire application and its server runtime into a single executable JAR file. This promotes the ''build once, run anywhere'' paradigm, ensures consistent environments between development and production, and facilitates cloud-native deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
