INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbc633d6-0576-41c7-a68b-923bac6cec32', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the relationship between the ''Dispatch'' function and the middleware chain?', N'Senior', N'The dispatch function acts as the entry point to the middleware chain; when called, it passes the action through each middleware layer sequentially. This chain allows for the transformation, logging, or interception of actions before they eventually reach the root reducer, which then updates the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
