INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7d53a36-9a2e-42b5-90d8-924364152770', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the purpose of the ''useAsyncData'' composable in Nuxt 3.', N'Middle', N'It is used to fetch data that needs to be available during server-side rendering. It automatically handles deduplication of requests and ensures the data is serialized and transferred to the client to prevent redundant fetching during hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'716083e7-3ed1-495a-98d2-9244928c90d4', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain what React hydration is', N'Fresher', N'React hydration is the process of attaching event listeners and making a server-rendered HTML page interactive on the client side. When a React application is server-side rendered, the HTML is sent to the client, and React takes over to make it dynamic by attaching event handlers and initializing state. This process is called hydration. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44b22552-5133-437d-b873-924822734fd4', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle reactivity?', N'Intern', N'Alpine.js uses a system called reactivity where the framework automatically tracks dependencies between data and the DOM. When a piece of data changes, Alpine detects the update and instantly synchronizes the corresponding part of the HTML to reflect that new value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c845034e-1278-4a07-a521-9248c00c8694', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the security implications of Hono’s middleware-based authentication.', N'Senior', N'Authentication is handled as a gatekeeper middleware that executes before the route handler, preventing unauthorized access to sensitive business logic. Because Hono’s middleware is composable, security policies can be strictly enforced by wrapping specific route groups, minimizing the risk of accidentally exposing endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faeedbb6-d6a6-4f89-884d-92498d2f57a4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why might using ''eval'' or the ''Function'' constructor pose significant security and performance risks?', N'Senior', N'These features execute arbitrary strings as code, opening the application to cross-site scripting vulnerabilities if user input is not sanitized. Furthermore, they prevent the JavaScript engine from applying optimizations like pre-compilation, resulting in significantly slower execution compared to native code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ea568cd-54e6-4e9e-9673-924a83ecbe12', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI provide automatic documentation?', N'Fresher', N'FastAPI automatically generates interactive API documentation using Swagger UI and ReDoc by reading the path operation definitions and type hints. This documentation is available at the /docs endpoint and allows developers to test the API directly from the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'346add12-cd6a-40f2-b5be-924b4803646b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle dependency injection if you have multiple beans of the same type?', N'Junior', N'Micronaut provides qualifiers like @Named or custom annotations to distinguish between beans of the same type. This allows you to explicitly inject the desired implementation when multiple candidates are present in the context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69442302-3bf0-4eae-abd4-924dd7d0f9b5', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it generally better to use database-level constraints even if you have validations in your models?', N'Middle', N'Model validations are application-level checks that can be bypassed by direct database queries or race conditions between validation and saving. Database constraints, such as NOT NULL or unique indexes, provide the final guarantee of data integrity that is enforced regardless of how the data is being inserted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd481a08-0fcd-456a-926f-9250333bc015', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does the CAP theorem state?', N'Fresher', N'The CAP theorem states that a distributed system can only provide two out of three guarantees: Consistency, Availability, and Partition Tolerance. In practice, most distributed NoSQL databases must balance these three depending on the business requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd139cbc-9bcb-422d-9d7a-925174497786', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of the shared buffers in PostgreSQL''s caching strategy?', N'Senior', N'Shared buffers represent the memory area where data pages are cached to minimize disk I/O. PostgreSQL relies on the operating system''s page cache for additional caching, creating a two-tier caching hierarchy that requires careful tuning to avoid double-buffering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'574658a7-47f3-45ae-b25e-92555f328cd4', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is ''Contract Testing'' and why is it used?', N'Middle', N'Contract testing verifies the interaction between a consumer and a provider based on a shared agreement of the API structure. It catches breaking changes early in the development lifecycle without requiring the entire system to be deployed for integration testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
