INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efeb0269-7834-43f3-8ccd-925a0fc2f6e7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is jQuery', N'Intern', N'jQuery is a popular cross-browser JavaScript library that provides Document Object Model (DOM) traversal, event handling, animations and AJAX interactions by minimizing the discrepancies across browsers. It is widely famous with its philosophy of “Write less, do more”. For example, you can display welcome message on the page load using jQuery as below, Note: You can download it from jquery''s official site or install it from CDNs, like google.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca23e80a-b3e6-4c9e-bb03-925a40805e42', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is data binding in Echo, and why is it useful?', N'Junior', N'Data binding is the process of automatically mapping incoming request data, such as JSON bodies or form fields, into Go structs. This eliminates the need for manual parsing, reducing code complexity and potential bugs during data processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed050860-6b46-4c32-a63b-925c5cf0564e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is type inference in TypeScript?', N'Intern', N'Type inference is the ability of the TypeScript compiler to automatically determine the type of a variable when an explicit type annotation is not provided. It bases this decision on the value assigned to the variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30833762-58ab-4e9b-8015-925e8b6f8363', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is ''eventual consistency'' often acceptable for large-scale social media feeds?', N'Senior', N'In social media, the cost of enforcing immediate consistency across a global cluster outweighs the benefits, as users rarely notice if a post takes a few seconds to propagate. Eventual consistency allows for high read availability and lower latency by allowing replicas to lag behind the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781eec1a-22a7-4eb5-b7ba-92614c4ccfde', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary architectural benefit of utilizing the CQRS pattern?', N'Senior', N'CQRS separates the read and write models, allowing for independent scaling and optimization of each path. This is particularly effective in high-scale systems where read and write workloads are asymmetric, enabling the use of specialized data stores for queries while keeping the write model optimized for consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb3e7b9e-17b3-42db-9340-9264ef21fd0b', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the trade-offs of Svelte''s component-level scoped CSS implementation regarding bundle size and style inheritance?', N'Senior', N'Svelte achieves scoped styles by automatically appending unique hashes to CSS classes at build time, which prevents style collisions without requiring CSS-in-JS libraries. While this leads to excellent performance and zero runtime CSS overhead, it forces a flat style architecture that can make global theme overrides or complex descendant styling more challenging to manage compared to traditional CSS methodologies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca62bda-3fc8-4b47-824e-926765f37e60', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of the ''tags'' parameter in FastAPI routes?', N'Intern', N'The tags parameter is used to group related API endpoints together in the generated Swagger UI documentation. This helps improve the organization and readability of the API for developers consuming it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9faf0a01-26c9-4879-97e9-926bcab6d2ec', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How are indices managed in R compared to languages like Python?', N'Junior', N'R uses 1-based indexing, meaning the first element of a vector or array is at index 1. Many other programming languages, such as Python or C, use 0-based indexing, where the first element is at index 0.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce45b0c8-8b7e-4ed2-bcec-9273885131db', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is avoiding excessive allocations important for GC-heavy applications?', N'Senior', N'Every allocation increases the work the garbage collector must perform to identify and reclaim unreachable memory, which consumes CPU cycles and increases pause times. By using techniques like object pooling or stack allocation, developers can reduce the number of objects the GC tracks, leading to more predictable performance and lower tail latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30ec8233-e7d1-497b-a452-9273932f9ab5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a wide-column store database?', N'Intern', N'A wide-column store organizes data into columns rather than rows, similar to a two-dimensional key-value store. This structure is highly optimized for querying large datasets across many columns simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c376942-820c-4e8b-b3f8-9273e5d0a8ad', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the impact of biased locking on JVM performance and why was it deprecated?', N'Senior', N'Biased locking optimizes uncontended synchronization by assuming a monitor is accessed by the same thread repeatedly, eliminating the need for expensive atomic compare-and-swap operations. It was deprecated because the complexity it introduced to the synchronization subsystem and the overhead of revoking biases in multi-threaded scenarios outweighed the performance gains in modern applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24da2604-ee00-43c9-82b1-92740583081f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''Security'' component maintain state in a stateless environment like an API?', N'Middle', N'In stateless APIs, the Security component uses tokens, such as JWTs or API keys, passed in the request header to authenticate the user for every request. It validates the token against a provider, ensuring the identity is verified without relying on session storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61fcb2dc-0913-4947-a280-9275b775dac8', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are the trade-offs of using Fastify instead of Express in NestJS?', N'Middle', N'Fastify offers significantly higher performance and lower overhead compared to Express, making it ideal for high-throughput applications. However, it has a smaller ecosystem of plugins and middleware compared to the mature Express framework, which might require extra effort for compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ae659bc-d786-4656-87aa-927634d79269', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How many arguments can the range() function take?', N'Fresher', N'Ans. The range() function in Python can take up to 3 arguments. Let''s see this one by one. a. One argument When we pass only one argument, it takes it as the stop value. Here, the start value is 0, and the step value is +1. list(range(5)) [0, 1, 2, 3, 4] list(range(-5)) [] list(range(0)) [] b. Two arguments When we pass two arguments, the first one is the start value, and the second is the stop value. list(range(2,7)) [2, 3, 4, 5, 6] list(range(7,2)) [] list(range(-3,4)) [-3, -2, -1, 0, 1, 2, 3] c. Three arguments Here, the first argument is the start value, the second is the stop value, and the third is the step value. list(range(2,9,2)) [2, 4, 6, 8] list(range(9,2,-1)) [9, 8, 7, 6, 5, 4, 3]', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82c57ce9-f8c0-48e6-924e-927b6d55d0f1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''crossinline'' modifier in higher-order functions?', N'Middle', N'''crossinline'' prevents non-local returns from being used inside a lambda passed to an inline function. This is necessary when the lambda is called from a different execution context, such as a separate thread or a local object, where returning from the enclosing function is invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f44d225d-b719-4d1d-9ab2-927dfcf36fc9', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart optimize for web environments?', N'Middle', N'Dart compiles to JavaScript using the dart2js compiler or the Dart Dev Compiler. These tools translate Dart''s features, such as classes and async/await, into efficient JavaScript equivalents, while leveraging tree shaking to reduce payload size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf72b722-4b69-43b7-978f-927f066fc0e8', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle deep object reactivity, and what are the performance impacts?', N'Senior', N'Alpine.js uses a recursive Proxy to wrap objects, allowing it to track changes to nested properties. While this provides a very seamless developer experience, deeply nested structures can be performance-heavy because every property access must pass through the proxy trap, potentially slowing down operations in highly dynamic data sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffe5ca04-4842-4579-8892-92858bce9084', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue where data consistency is drifting between two microservices?', N'Senior', N'I would trace the event stream to identify gaps in message processing or failures in dual-write operations that might have been lost without proper acknowledgment. I would also check for race conditions in the distributed locking mechanism or eventual consistency lag that could be causing stale reads in the downstream service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b738527e-91aa-4540-9867-92887903370e', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of a Write-Ahead Log (WAL) in distributed storage systems?', N'Senior', N'The WAL provides durability by ensuring that every change is persisted to stable storage before being applied to the main state. It allows the system to recover state after crashes by replaying log entries and serves as the primary mechanism for replicating state changes to followers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9deff72-98ee-4e9a-9c86-9288ea1e0c81', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your methodology for debugging an issue involving corrupted data in a distributed database?', N'Senior', N'I isolate the time window of corruption by inspecting audit logs and version history to determine which transaction or node introduced the invalid state. I then perform a cross-node consistency check to see if the issue is isolated to a specific shard or replica and assess the impact of potential rollback or repair strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e4ba5c5-e185-400b-a31b-92890d9fa7ec', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is an RDB snapshot in Redis?', N'Intern', N'RDB (Redis Database Backup) creates point-in-time snapshots of your dataset at specified intervals. It is a compact file that is very efficient for disaster recovery and backups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1996b523-c1f0-42e3-83dc-928ee7e3383d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle file system operations?', N'Junior', N'Node.js uses the ''fs'' module to interact with the file system. It provides both synchronous and asynchronous methods, with asynchronous versions being preferred to prevent blocking the event loop during file I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'115abc3a-d40a-4e86-a4d9-928f7026b527', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can you use Alpine.js with other libraries like jQuery or Bootstrap?', N'Junior', N'Yes, Alpine.js is designed to play well with other libraries. Since it interacts with standard HTML, it can coexist alongside jQuery or Bootstrap, allowing you to use Alpine for reactive state management while using other libraries for their specific strengths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
