INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d52752b-2c58-4dc2-be71-92929261e630', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are mapped types in TypeScript?', N'Fresher', N'Mapped types allow you to create new types by transforming properties from an existing type. They are often used to make properties of an object read-only or optional based on an existing definition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f6af505-6fed-4f2c-bd9a-9292baca3aed', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Difference between Function, Method and Constructor calls in JavaScript?', N'Middle', N'1. Functions: The simplest usages of function call: 2. Methods: in JavaScript are nothing more than object properties that are functions. 3. Constructors: Like function and method, constructors are defined with function. Unlike function calls and method calls, a constructor call new Employee(''Drishya Sama'', 28) creates a new object and passes it as the value of this, and implicitly returns the new object as its result. The primary role of the constructor function is to initialize the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
