INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04782238-b190-4da9-bd19-92981570d77b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary advantage of using MongoDB over a relational database?', N'Fresher', N'The primary advantage is its flexible data model, which allows developers to store complex, nested data structures easily. It also facilitates faster development cycles since developers do not need to perform complex schema migrations when requirements change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19747331-4af6-49cc-83c8-9298ff85789c', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the concept of ''Context'' keys in Gin and why they should be used carefully.', N'Middle', N'Context keys allow passing data between middleware and handlers, such as an authenticated user object. They should be used sparingly because they are not type-safe and can lead to runtime errors if the expected data is missing or of the wrong type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'489fb58c-b2b6-4fcd-9622-929a3a17e0af', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the risk of shared libraries in a microservices ecosystem?', N'Senior', N'Shared libraries can introduce tight coupling, where a change in a core library necessitates redeploying all services that depend on it. This undermines the autonomy of individual teams and complicates versioning strategies across the architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
