INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1186194c-c016-47c9-bbe4-929f648dbebb', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the CAP theorem''s relevance to distributed database design.', N'Senior', N'The CAP theorem states that in the presence of a network partition, a system must choose between consistency and availability. Architects must evaluate the business requirements to determine whether the system can tolerate stale data during outages or if it must sacrifice availability to ensure absolute data accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a674207-4b5f-4db1-a024-92a0db6ceec3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are closures?', N'Intern', N'A closure is the combination of a function and the lexical environment within which that function was declared. i.e, it is an inner function that has access to the outer or enclosing function''s variables. Closure is useful in hiding implementation detail in JavaScript. In other words, it can be useful to create private variables or functions. Lexical Scope: In lexical scoping, free variables must belong to a parent scope. JavaScript uses lexical scoping — a function''s scope is determined by where it is declared, not where it is called. Example 01: As per the above code, the inner function displayName() has access to the variable name from the outer function init(), even after init() has returned. This is a closure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'256a0db9-013f-4fe7-9988-92a193bba298', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the significance of using standard HTTP status codes correctly?', N'Middle', N'Standard status codes provide a common language for client-server communication. Using codes like 401 for unauthorized or 429 for too many requests allows client libraries to handle errors automatically and improves the maintainability of the integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd656eed7-2053-413e-a2f5-92a1c96f32a9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the primary architectural benefit of Gin''s Context object design in a high-concurrency environment?', N'Senior', N'The Context object is designed to be reusable via a sync.Pool mechanism, which significantly reduces garbage collection pressure by minimizing heap allocations per request. This allows Gin to handle a higher volume of concurrent requests with lower memory overhead compared to frameworks that instantiate new objects for every incoming connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6489563-a7cb-4cf9-a357-92a2039a64ed', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is it important to implement idempotent consumers in a messaging system?', N'Senior', N'Idempotent consumers ensure that processing the same message multiple times has no side effects beyond the initial execution. This is essential for handling retries, network glitches, and at-least-once delivery semantics, which are common in distributed messaging environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'060e6a66-c3a9-4aba-b151-92a2713dc079', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How can you optimize performance in a Symfony application that uses heavy container compilation?', N'Middle', N'You can optimize performance by using the container''s production mode, which dumps the container to a compiled PHP file, eliminating the need to parse YAML or XML on every request. Additionally, caching service definitions and using optimized autowiring improves the startup time of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f6dface-3e29-45d9-bc60-92a74b20208d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is a Fastify ''plugin'' and why is it used?', N'Junior', N'A plugin is the fundamental building block of a Fastify application used to encapsulate functionality, such as database connections, utility functions, or route groups. It promotes modularity and allows you to organize your application into isolated scopes with their own configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd94340ff-a8f3-4281-94fa-92ab4b0fc319', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s compilation strategy differ from virtual DOM-based frameworks, and what are the architectural performance implications?', N'Senior', N'Svelte shifts the reconciliation work from the browser runtime to a build-time step by compiling components into highly optimized imperative code that directly updates the DOM. This eliminates the overhead of maintaining a virtual DOM tree and performing diffing algorithms at runtime, resulting in smaller bundle sizes and faster initial rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f30197e-2271-44cc-9844-92ada6123e91', N'954a0331-deff-4399-b588-96f39fec001d', N'What are ViewEncapsulation modes, and why would you change them?', N'Middle', N'ViewEncapsulation determines how component styles are scoped to prevent leakage into other parts of the app. You might change it to ''None'' if you need global styles to affect a component, or ''ShadowDom'' for strict native scoping if required by your design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
