INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae593eee-7689-412d-b61d-92bd16876107', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the Gin framework primarily used for in the Go ecosystem?', N'Junior', N'Gin is a high-performance HTTP web framework used for building web applications and RESTful APIs. It is designed to be lightweight and fast, providing a productivity-focused toolkit for routing, middleware, and request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4db841ae-89e0-4207-965f-92bd6a9c2fdf', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is Consistency in the CAP theorem?', N'Fresher', N'Consistency ensures that every read request receives the most recent write or an error. It means all nodes in the system see the same data at the same time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ba47b01-ddc7-4884-a749-92beaadfd989', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the difference between a HOT update and a standard update in PostgreSQL.', N'Senior', N'A Heap-Only Tuple (HOT) update occurs when the updated row fits on the same data page as the original and no index columns are modified. This avoids the overhead of updating associated indexes, significantly reducing I/O and write amplification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'463c999a-b95b-4188-92ab-92c2e2fd4ad5', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle secrets management in a microservices architecture?', N'Middle', N'Secrets should never be hardcoded; instead, they should be stored in a centralized, secure vault and injected into the service at runtime. This allows for centralized rotation, auditing, and fine-grained access control for sensitive credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0316407-7ab0-4b3b-8c5b-92c3ba4dba04', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of a Profiles in Spring Boot?', N'Junior', N'Profiles allow you to segregate parts of your application configuration and make it available only in certain environments, such as development, testing, or production. You can activate specific profiles to load different database settings or external service URLs without changing the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c031598b-59cd-4ca8-b8bc-92c920190b35', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the architectural implications of using synchronous REST versus asynchronous messaging for inter-service communication.', N'Senior', N'Synchronous REST introduces temporal coupling and cascading failure risks, requiring robust circuit breakers. Asynchronous messaging enables loose coupling and better resilience, but increases complexity due to the need for handling idempotency, message ordering, and eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008f22c2-b297-482c-8777-92cc53dba7fc', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''onMount'' lifecycle function in Svelte?', N'Intern', N'The onMount function is a lifecycle hook that executes code immediately after a component is first rendered and added to the DOM. It is commonly used for tasks such as fetching initial data from an API or setting up event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a028d65d-718f-450f-a190-92cede5b2307', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between Redux Thunk and Redux Saga?', N'Middle', N'Redux Thunk is a simple middleware that allows action creators to return functions instead of objects, which is useful for basic async logic. Redux Saga uses generator functions to manage more complex side effects, offering better testability and control over cancellation or concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c73feaf-ca0b-46f9-b2a6-92d02b7f17a9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are WeakRef and FinalizationRegistry in JavaScript?', N'Intern', N'Introduced in ES2021, WeakRef and FinalizationRegistry provide low-level access to the garbage collector — primarily for caches and resource management. WeakRef: A WeakRef holds a *weak reference* to an object, meaning it does not prevent the object from being garbage-collected. Use .deref() to access the object; it returns undefined if already collected. FinalizationRegistry: Lets you register a callback to be called when a registered object is garbage-collected. Practical use — weak cache: Important caveats: * GC timing is non-deterministic — never rely on FinalizationRegistry for critical cleanup. * WeakRef should be a last resort; prefer WeakMap/WeakSet for most weak-reference patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4fc693c-cd3a-4f40-a653-92d11e2dec66', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the concept of Middleware chaining in Hono.', N'Middle', N'Middleware in Hono is executed in a stack-based order. Each middleware receives the context and a next function; calling next passes control to the subsequent middleware or route handler, allowing for layered logic like authentication, logging, or error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53156092-c042-49a3-835e-92d3614fa25e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React and why is it used?', N'Intern', N'React: Modern Definition (2026) React is a declarative, component-based library for building user interfaces. As of 2026, it is governed by the React 19+ paradigm, emphasizing Concurrent Rendering, Server Components, and Actions. --- Core Architectural Concepts Concurrent Rendering & Virtual DOM While React still utilizes a Virtual DOM for reconciliation, the 2026 standard emphasizes Concurrent React. This allows React to prepare multiple versions of the UI simultaneously without blocking the main thread. By prioritizing updates (e.g., input typing over data fetching), React achieves better responsiveness. The diffing algorithm maintains $O(n)$ complexity through heuristic assumptions, optimized for modern browser engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'125c2f4c-c0af-4889-85dd-92d397155c26', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the ''Astro'' file format (.astro)?', N'Middle', N'The .astro file format is a component-based templating language that separates frontmatter logic from the HTML template. It is designed to be zero-runtime, meaning all code inside the frontmatter is executed during build or request time and stripped away before reaching the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7399bb02-4f8d-40a8-b1ef-92d404de44ba', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the impact of the single-threaded nature of the Redis command execution engine on modern multi-core systems?', N'Senior', N'While Redis is single-threaded for command execution to avoid lock contention and context switching, it utilizes I/O threads for network operations in newer versions to scale horizontally. On multi-core systems, this architecture still implies that a single instance is bound to one core for processing, requiring users to run multiple instances or clusters to leverage all available CPU resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ef57587-5a84-41ee-bf94-92d5f5a88be7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What criteria do you use to evaluate a third-party library before adding it to a project?', N'Junior', N'I check the library''s documentation, the frequency of recent updates, the number of open issues, and the size of its community. A well-maintained library with active community support reduces the risk of long-term technical debt and security vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db4161cc-4684-45cd-81b9-92d804143f39', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Tombstone in Cassandra and why is it necessary?', N'Middle', N'A Tombstone is a marker used to represent a deleted record, as Cassandra performs updates via appends rather than in-place overwrites. It prevents deleted data from reappearing during reads until it is permanently removed during compaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
