INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb2946c-3d49-4f94-81cf-92da4c6a9977', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the difference between message queues and event streaming platforms like Kafka in terms of message retention and consumer coupling.', N'Senior', N'Message queues typically delete messages once acknowledged by a consumer, emphasizing task distribution. Kafka uses a distributed append-only log that retains messages for a configured duration, allowing multiple independent consumer groups to replay or process data at their own pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
