INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dbb510a-0db4-4438-9118-92dd08a02bda', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the impact of team size on project estimation?', N'Intern', N'Adding more people to a project does not always result in a linear increase in productivity due to the overhead of communication and coordination. An estimation must account for these ''Brooks''s Law'' effects, where the complexity of interaction increases with the square of the number of team members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fa0706f-db82-4d24-9354-92ddcab39d4e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does ''x-effect'' differ from standard event-driven reactivity?', N'Middle', N'The ''x-effect'' directive runs a piece of code whenever its dependencies change, making it perfect for side effects like logging, DOM manipulation, or updating non-Alpine libraries. Unlike event-driven updates, it automatically tracks changes to the specific data points referenced within the block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c4447a9-b32f-4018-a560-92defaebf6ae', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between creating String as new() and literal?', N'Fresher', N'When you create String object using new() operator, it always create a new object in heap memory. On the other hand, if you create object using String literal syntax e.g. "Java", it may return an existing object from String pool ( a cache of String object in Perm gen space, which is now moved to heap space in recent Java release ), if it''s already exists. Otherwise it will create a new string object and put in string pool for future re-use. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4b7740a-29c6-4140-a006-92df967a20b0', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Discuss the scalability challenges of Redux in micro-frontend architectures.', N'Senior', N'In micro-frontends, sharing a single Redux store creates tight coupling and potential namespace collisions between teams. It is generally better to isolate state within each micro-frontend or use an event-bus pattern for cross-application communication, keeping global state strictly for cross-cutting concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708206c2-7c1c-4cc3-95ec-92e03c4f7a27', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the benefit of using Litestar''s built-in OpenAPI support?', N'Fresher', N'Litestar automatically generates an OpenAPI specification based on your application code, including routes, models, and type hints. This enables the automatic creation of interactive documentation, such as Swagger UI, which helps developers and users understand how to interact with the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6cadefb-4f10-4d58-ae9a-92e4c713d1c1', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How is the Implementation of Python\''s dictionaries done?', N'Fresher', N'Python dictionary needs to be declared first: dict = {} Key value pair can be added as: dict[key] = value or objDict.update({key:value}) Remove element by: dict.pop(key) Remove all: objDict.clear() A hash value of the key is computed using a hash function, The hash value addresses a location in an array of "buckets" or "collision lists" which contains the (key , value) pair.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e95b045f-82f1-418b-a3cc-92e61e60d3a9', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket achieve high performance while maintaining a high level of abstraction?', N'Senior', N'Rocket utilizes extensive code generation through procedural macros to perform routing, type validation, and data serialization at compile-time. By shifting these tasks from runtime to compile-time, it minimizes overhead and avoids the performance penalties associated with reflection-based frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24b547f5-6c60-42a4-967a-92e680604023', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus support externalizing configuration for different environments?', N'Middle', N'Quarkus uses a profile-based configuration system where properties can be prefixed with environment names like %prod or %dev. This allows developers to easily switch configurations between environments without modifying the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc71c121-1330-4f10-ae3d-92ef4bf795bf', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the .attr() and .prop() methods?', N'Fresher', N'The .attr() method is used to get or set HTML attributes as defined in the markup, such as src or href. The .prop() method is used for properties that are part of the DOM object, such as the checked or disabled status of an input element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cda5913a-a6aa-4ec6-a425-92f045e87809', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix use client-side routing?', N'Fresher', N'Yes, Remix uses client-side routing. Once the initial page is loaded, navigating to other parts of the app happens without a full browser refresh by fetching only the necessary data and components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79a4c1f2-9364-42d3-affe-92f0af70a226', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle CSS?', N'Intern', N'Next.js has built-in support for CSS modules, which allow you to scope styles to specific components to avoid naming conflicts. It also supports global CSS files and preprocessors like Sass, making it flexible for various styling requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35ed45ca-8a89-49cf-9fe6-92f7e16a88a8', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the primary difference between monitoring and observability in a distributed system?', N'Middle', N'Monitoring focuses on tracking known metrics to detect predefined failure states, such as high CPU usage. Observability is a broader property that allows you to understand the internal state of a system by examining its external outputs, specifically logs, metrics, and traces, enabling the debugging of unknown, unforeseen issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c9cdfd-1eab-4c9d-8caf-92fbe920fd5e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When troubleshooting a network connectivity issue, what is the standard order of operations?', N'Intern', N'Start by verifying the physical connection, then check the configuration settings like IP addresses and DNS, and finally test connectivity to intermediate nodes. This ''bottom-up'' approach ensures you rule out the simplest potential failures before investigating more complex network path issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a7226ab-2d09-4cf1-b2d7-92ff5affbd27', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the trade-offs of using Laravel''s Eloquent ORM in a high-concurrency, read-heavy system.', N'Senior', N'Eloquent provides developer productivity but introduces overhead due to object hydration and the Active Record pattern. In high-concurrency systems, the memory footprint of hydrated models can be significant, necessitating the use of query builder or raw SQL for performance-critical paths to bypass model instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68968095-5b33-4189-b663-92ff66239154', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the primary risk of over-sharding a database?', N'Middle', N'Over-sharding can lead to excessive management overhead and complex application logic. It increases the probability of cross-shard queries, which are significantly slower than single-node queries and can degrade overall system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bea74511-709d-4c63-9da6-93029549c404', N'075b8862-431c-4678-9767-f55359758a4a', N'How does the ''render'' function differ from templates, and when is it preferred in a senior-level architecture?', N'Senior', N'Templates are declarative and optimized by the compiler, whereas render functions provide full programmatic control over the VDOM generation. Render functions are preferred for high-level abstraction components, such as dynamic table renderers or recursive UI elements, where template syntax would become overly verbose or impossible to implement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19293ddc-5694-4b56-9b5f-93035d025537', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the trade-off between consistency and availability in a distributed system?', N'Middle', N'I evaluate the business requirement for the specific data; for instance, financial transactions require strong consistency, while social media feeds can favor availability. I design the system to handle the chosen trade-off, perhaps by implementing eventual consistency for non-critical features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92fbe7b5-a617-4ea7-937b-9306627471ac', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In terms of testing, what is the trade-off between writing many unit tests versus fewer integration tests?', N'Junior', N'Unit tests are fast, cheap to maintain, and isolate specific logic, providing high confidence in code correctness. Integration tests cover the interaction between components and provide better end-to-end confidence, but they are slower, more brittle, and harder to debug when they fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7bca5a7-20b6-4f04-a627-9307f9e503f5', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary architectural advantage of using Fastify over other Node.js frameworks?', N'Junior', N'Fastify is designed from the ground up to be highly performant with low overhead. It achieves this by using a highly optimized internal routing mechanism and a schema-based approach for request and response validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22e99a2d-181f-4ec0-beb6-9308d568c7d8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''type'' aliases and ''interface'' declarations differ in TypeScript?', N'Middle', N'Interfaces are primarily used for defining object shapes and support declaration merging, whereas type aliases can represent unions, primitives, and tuples. While they are often interchangeable for objects, interfaces are better suited for defining public APIs or extensible library structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1f4e293-110c-4c18-84bf-930fa13204e0', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is an IDOR (Insecure Direct Object Reference) vulnerability?', N'Middle', N'IDOR occurs when an application exposes a direct reference to an internal database object, such as a user ID, without proper authorization checks. An attacker can change the ID in the request to access another user''s data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc565145-1f5a-453a-a59f-930fe0928807', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between ''dev'' and ''build'' commands in Vite?', N'Junior', N'The ''dev'' command starts a local development server that uses native ESM for fast iteration. The ''build'' command runs a production-ready build using Rollup to bundle and optimize the application for deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3da5bd3d-2667-4213-b7e5-931056a7d1aa', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain how DynamoDB calculates read capacity units (RCU) for eventually consistent versus strongly consistent reads.', N'Senior', N'A strongly consistent read consumes one RCU per 4KB of data, while an eventually consistent read consumes 0.5 RCU for the same amount of data. This cost difference incentivizes the use of eventual consistency for read-heavy workloads where immediate accuracy is not strictly required. Choosing the right consistency level is a direct lever for optimizing operational expenditure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6098ca9-8bde-4a05-8c56-9314140cee63', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the advantages of compiling a Micronaut application into a GraalVM native image?', N'Middle', N'Native images provide near-instant startup times and drastically reduced memory consumption compared to traditional JVM deployments. This makes them ideal for serverless environments and microservices where resource efficiency and scaling speed are critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99f5686f-9ff0-4623-9a95-9317cbf6d30b', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you upgrade location service of angularjs?', N'Fresher', N'If you are using $location service in your old AngularJS application, now you can use LocationUpgradeModule(unified location service) which puts the responsibilities of $location service to Location service in Angular. Let''s add this module to AppModule as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'125d8e26-52c0-4bf6-8b69-9317cc7df6ab', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does HTML accessibility labeling (e.g., aria-label) affect the accessibility tree?', N'Senior', N'Aria labels override the default accessible name derived from the element''s content, which is useful when the visual label is insufficient or absent. However, over-relying on these attributes can lead to a divergence between the visual UI and the accessibility tree, potentially confusing users if the labels are not kept in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'073e9361-e482-49e2-a625-931826460e64', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of ''Vector Clocks'' in systems like Riak, and why are they considered superior to simple timestamps?', N'Senior', N'Vector clocks track the causal history of updates across distributed nodes by maintaining a map of counters for every participant, allowing the system to detect if two updates are concurrent or if one strictly follows another. Unlike physical timestamps, which suffer from clock skew and synchronization issues, vector clocks provide a reliable mechanism for resolving conflicts in partition-tolerant systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'419d9079-b6cd-4eb0-a5e6-93188e3895bb', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the performance impact of Echo''s middleware stack depth on request latency.', N'Senior', N'Every middleware added to the stack adds function call overhead and potential context switching. In high-frequency trading or extremely low-latency environments, minimizing the middleware chain depth is essential to keep the total request overhead within performance budgets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43d1e62b-1a90-48f9-a1c5-931bf8abc5cf', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB ensure data durability?', N'Junior', N'MongoDB uses a write-ahead logging mechanism called the journal to ensure that data is written to disk consistently. This allows the database to recover to a valid state in the event of a system crash or power failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aafe487e-5b28-494a-bd08-931ee29e657d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is an Ecto association?', N'Junior', N'Associations allow you to define relationships between different schemas, such as one-to-many or many-to-many. Ecto uses these definitions to handle join queries and preloading related data efficiently when fetching records from the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
