INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c689523-fa7d-42b4-97f9-9350a6e80309', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the impact of long-running transactions on database vacuuming and storage bloat?', N'Senior', N'Long-running transactions prevent the database from cleaning up old versions of rows created by subsequent transactions, as those rows might still be visible to the long-running transaction. This results in significant storage bloat and increased I/O overhead for queries as the system scans through expired data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
