INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c78dcf48-24f6-4292-91cb-93587c417daa', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the performance considerations for Tailwind in a server-side rendered (SSR) application?', N'Senior', N'Because Tailwind generates static CSS, it is highly optimized for SSR as there is no flash of unstyled content or runtime style injection. The CSS is delivered as a standard static asset, which is cacheable by browsers and CDNs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd521be50-97fd-48b0-a303-9358bc842cb6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the Redo Log differ from the Binary Log in MySQL?', N'Senior', N'The redo log is an InnoDB-specific physical log used for crash recovery to ensure durability of committed transactions. The binary log is a server-level logical log used primarily for replication and point-in-time recovery, containing information about changes to data regardless of the storage engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdd5cc0d-b63e-4d3e-a471-935a8baf1945', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the Symfony Form component used for?', N'Junior', N'The Form component provides a structured way to handle HTML form creation, data binding, and validation. It automates the process of mapping user input to object properties while ensuring that the data conforms to defined security and business rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec7c309f-cec1-4abb-87c7-935cf243e175', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Adapters and Serializers in Ember Data?', N'Fresher', N'Adapters determine how data is fetched from the server, such as the URL structure or request headers. Serializers are responsible for translating the data format received from the API into a format that Ember Data understands and vice versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'300a0031-a7de-458e-9814-935dafd5d0af', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How can you group routes in Axum?', N'Intern', N'Axum allows you to define sub-routers and merge them into the main application router. This helps keep the codebase organized by grouping related endpoints together in separate modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8c1f614-7d3c-4b2d-8c12-935df18d2495', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the architectural trade-offs of using Ruby''s ''Module'' system for dependency injection versus traditional class inheritance?', N'Senior', N'Modules facilitate a flattened, horizontal composition structure that avoids the rigid hierarchy of deep inheritance trees, promoting better code reuse and separation of concerns. However, excessive use of mixins can obscure the method lookup chain, making debugging complex and increasing the cognitive load required to trace state mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9393a036-d8a1-4fd8-8c3a-935e44a0b4e4', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does testing affect the trade-off between delivery speed and stability?', N'Intern', N'Rigorous testing slows down the initial release speed but drastically reduces the cost and frequency of fixing bugs later. Skipping tests allows for a faster initial launch but increases the risk of instability and technical debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6775c692-fd10-4c8e-be61-93611c74f4b6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the difference between an Action and a Loader?', N'Intern', N'A loader is strictly for reading data from the server, while an action is for modifying or writing data. Loaders run on every GET request, whereas actions run only when a request method like POST, PUT, or DELETE is used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e86e56d-a7be-431b-9aa8-9362596b8551', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why would you choose asynchronous messaging over synchronous REST calls in a microservices architecture?', N'Middle', N'Asynchronous messaging decouples services, allowing them to scale independently and continue functioning if one service is temporarily unavailable. It also improves system responsiveness by offloading time-consuming tasks to background workers instead of blocking the user request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e4098d1-7740-42dc-80e9-9363b8d0cbf9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the role of the ''hono/jsx'' feature?', N'Intern', N'Hono includes a built-in JSX renderer that allows developers to write and render HTML components directly within their application. This is useful for server-side rendering without needing heavy external libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f85389c6-05bf-432b-ab44-9368e46557d6', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of Hono''s ''app.use()'' method?', N'Fresher', N'The ''app.use()'' method is used to register global middleware that runs for every request entering the application. It is commonly used for logging or security headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4968905e-6af7-4755-bd3a-936ad0912000', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How can you prevent buffer overflows in C?', N'Middle', N'Buffer overflows are prevented by always performing bounds checking before writing to an array or buffer. Developers should favor safer string handling functions that require an explicit buffer size and use static analysis tools to identify potential vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8202d126-919b-47a5-981f-936cd5b3b551', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why would you use the repository pattern in a large Laravel project?', N'Middle', N'The repository pattern creates an abstraction layer between your application logic and the data access layer. It makes your code easier to unit test by allowing you to swap out the underlying data source without affecting the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b5983f0-aeeb-47af-a9de-937025a54158', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does one perform validations in Laravel?', N'Fresher', N'Laravel simplifies data validation, ensuring integrity in both forms and API requests. Basic Data Validation For more general validation rules, Laravel provides a simple validate() method that many beginners find helpful. Here''s the typical workflow: 1. Create a Controller: Define methods for HTTP verbs like store() for POST requests. In these methods, use the validate() helper. If the validation fails, Laravel automatically redirects back to the previous location. 2. Add Validation Messages: Tailor error messages for each field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb8ff7f1-a36e-415a-89dd-937345e5ee94', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide between a quick, temporary fix and a long-term, time-consuming solution?', N'Intern', N'I would evaluate the impact of the problem and the urgency of the situation. A quick fix might be appropriate if the goal is to restore service immediately, but I would document it as technical debt and plan to revisit it for a permanent solution once the urgency subsides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c1c599e-d65f-4ceb-9e30-9374cd13e780', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to implement idempotency in API endpoints that perform state mutations?', N'Middle', N'Idempotency ensures that performing the same operation multiple times has the same effect as performing it once, which is critical for handling network retries in distributed systems. Without it, a client might inadvertently create duplicate orders or transactions if the network connection drops after the request reaches the server but before the acknowledgement returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cc6f7b3-43e8-4c2e-90e8-9379264f257a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the difference between vertical and horizontal scaling?', N'Junior', N'Vertical scaling involves adding more power, such as CPU or RAM, to an existing machine, which has a hard ceiling. Horizontal scaling involves adding more machines to the pool, which is generally more flexible and allows for virtually infinite growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'122dd7dc-1b87-40af-80e4-937adfb32a13', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi''s design encourage or discourage the use of global state?', N'Middle', N'Chi''s design is neutral but discourages global state by promoting handler-based dependency injection. Because handlers are functions that can be attached to routers, it is standard practice to pass necessary dependencies through struct fields or closures, rather than relying on global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2f4075d-c367-49e6-8875-937af79d23ed', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the risk of having a shared database between two independent services?', N'Junior', N'Sharing a database creates a tight coupling between services, meaning a schema change in one service might break the other. It makes it difficult to scale services independently and obscures the boundaries of service responsibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63c81bcd-55de-4aac-adb0-937c82083943', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between ''SyncActor'' and a standard ''Actor'' in Actix?', N'Middle', N'A standard Actor is non-blocking and runs on the event loop, while a SyncActor runs in a separate pool of threads designed specifically for synchronous, blocking operations. SyncActors are useful for legacy code or libraries that do not support asynchronous interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b118a1d3-6e17-4b4a-a4f3-937ec86a36ce', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle a situation where you realize you will not meet a deadline for a task?', N'Intern', N'I would communicate the delay to my manager or team lead as soon as I recognize the risk, rather than waiting until the deadline passes. I would explain the obstacles I am facing and provide an updated estimate of when the task will be completed, possibly suggesting which parts of the task can be prioritized to provide partial value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'535e0897-1b42-4207-9d06-938201ef3d45', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you manage your time when you have multiple tasks with the same deadline?', N'Junior', N'I assess the relative importance of each task and check if there are any dependencies that need to be completed first. I then prioritize the tasks based on business value and communicate the plan to my manager to ensure alignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18397678-af01-4678-88c6-9383810a1aad', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary benefit of the Just-in-Time (JIT) compiler in Tailwind CSS compared to the previous engine?', N'Middle', N'The JIT compiler generates CSS on-demand as you author your HTML, rather than scanning a pre-defined set of utilities. This allows for arbitrary value support, better performance in development, and identical CSS output between development and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a19fec32-891d-4bcd-9081-9383a2c1ced1', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the importance of ''Pre-compiled'' templates in Phoenix performance?', N'Middle', N'Phoenix compiles templates into functions at compile time rather than parsing them at runtime. This turns template rendering into a fast function call, significantly reducing overhead and improving response times compared to frameworks that interpret templates on every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'373357ce-3e6a-4236-8f19-9385422eb0fc', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the difference between a high-availability system and a fault-tolerant system.', N'Senior', N'High availability focuses on minimizing downtime through redundancy and failover mechanisms, aiming for a high percentage of uptime. Fault tolerance implies the system can continue operating at a full or degraded capacity even when one or more components fail, without any interruption to the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'134129aa-924e-49f2-8452-938a4ef98acf', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the architectural purpose of Provisioned Capacity with Auto Scaling versus On-Demand mode?', N'Senior', N'Provisioned Capacity with Auto Scaling is optimized for predictable workloads where you can reserve throughput at a lower cost. On-Demand mode is intended for unpredictable, bursty workloads where capacity management is automated but at a higher unit price. The choice depends on the trade-off between cost predictability and operational overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b4b1507-296f-4cc9-96bc-938be5fbd1d2', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle asynchronous operations within its request-response cycle?', N'Fresher', N'Fastify is built on top of an asynchronous core, allowing it to handle concurrent connections efficiently. It supports promises and async/await syntax natively, ensuring that non-blocking I/O operations do not stall the event loop while waiting for database or external API responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b811d37-7761-4d8d-8211-938ef4fd838e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why might you prefer a namedtuple over a standard dictionary?', N'Middle', N'Namedtuples are memory-efficient, immutable, and provide attribute-style access which improves code readability. They are faster than dictionaries for storing fixed sets of data because they do not require a hash table. However, they lack the mutability and flexibility required if the data structure needs to change dynamically at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b195a695-392c-4ef7-9ab1-938f231c8f16', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of ''Borrowing'' as opposed to ''Copying'' in Rust?', N'Senior', N'Borrowing allows temporary access to data without transferring ownership, which is crucial for efficiency by avoiding expensive memory allocations and deep copies. By enforcing strict rules on the duration and mutability of these references, Rust enables efficient data sharing while preventing dangling pointers and data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed695827-1967-4bd6-8d1c-9390861ebf1b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are default arguments in Kotlin?', N'Intern', N'Default arguments allow you to assign a default value to a function parameter, which is used if the caller does not provide an argument for that parameter. This reduces the need for creating multiple function overloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e30a51f-b781-42c2-8af3-93934b154883', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is a Mixin in Dart and why would you use one?', N'Middle', N'A mixin is a way of reusing a class''s code in multiple class hierarchies without requiring inheritance. It allows developers to add specific behaviors to a class without creating complex or deep inheritance trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2a57c4e-fa4a-4bd2-b9b6-93935fe4be16', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How do you perform side effects in Preact?', N'Junior', N'Side effects, such as data fetching or subscriptions, are handled using the ''useEffect'' hook in functional components. In class components, these are managed within lifecycle methods like ''componentDidMount''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5241247a-48ac-4a2a-a1b0-9393c13efef0', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How can you leverage Laravel''s ''Middleware'' for cross-cutting concerns without cluttering application logic?', N'Senior', N'Middleware allows for the modular implementation of cross-cutting concerns like logging, rate limiting, and authentication. By keeping these concerns out of controllers and services, you maintain a cleaner business logic layer and improve the reusability of security and auditing components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'932efdb4-df16-459b-ba8d-9393c3dc7684', N'954a0331-deff-4399-b588-96f39fec001d', N'What are components?', N'Intern', N'Components are the most basic UI building block of an Angular app, which form a tree of Angular components. These components are a subset of directives. Unlike directives, components always have a template, and only one component can be instantiated per element in a template. Let''s see a simple example of Angular component', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bda4513c-c1e2-4545-9ba8-9395d3618fb2', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between shallow and deep copying in the context of C++ classes?', N'Middle', N'Shallow copying performs a bitwise copy of member variables, which can lead to double-free errors if pointers are involved. Deep copying involves allocating new memory and copying the actual data, ensuring that each object manages its own resources independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8985e99-1f34-4f3c-95af-93966790fc06', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber''s internal routing tree structure influence lookup time complexity?', N'Senior', N'Fiber utilizes a radix tree or similar optimized structure for routing, ensuring that path lookup time is independent of the total number of routes defined. This O(k) complexity, where k is the length of the path, remains efficient even as the API grows to include hundreds of endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9810293-840c-4186-9849-9397d7a791b6', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why does Rocket prefer compile-time routing over runtime dynamic routing?', N'Middle', N'By validating routes at compile-time, Rocket ensures that all defined endpoints, parameters, and guards are consistent and correctly typed before the application even runs. This reduces the surface area for runtime errors and improves performance by minimizing the amount of work required to dispatch a request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
