INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae783649-4c95-4935-aa13-93a79944b408', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a stack-allocated object and a heap-allocated object in C++?', N'Junior', N'Stack-allocated objects have their memory managed automatically by the scope of the function, meaning they are destroyed when the function returns. Heap-allocated objects are created using the new keyword and persist until they are explicitly deleted, requiring manual memory management to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96177083-d53b-490c-933c-93ab043ec918', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between building a custom solution versus integrating an off-the-shelf third-party service?', N'Senior', N'I assess whether the feature is a core competitive advantage or a commodity requirement. If the functionality is a core differentiator, I build it to maintain control; if it is a standard business need like authentication or email delivery, I prefer integrating a managed service to reduce maintenance overhead and accelerate time-to-market.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
