INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'685b9e24-2ef4-4e1c-9f3a-93bc1839b9a9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve low memory consumption?', N'Intern', N'Micronaut uses ahead-of-time compilation to process framework infrastructure, avoiding the creation of large metadata caches at runtime. By not using reflection or dynamic proxies, it significantly reduces the heap memory required to start the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b33c433b-4ae5-4f87-a1db-93bcbe025f52', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the useMemo hook in React and when should it be used?', N'Fresher', N'The useMemo hook in React is used to memoize expensive calculations so that they are only recomputed when one of the dependencies has changed. This can improve performance by avoiding unnecessary recalculations. You should use useMemo when you have a computationally expensive function that doesn''t need to run on every render. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca11fb0-9773-4f03-9eb6-93bed3e99e70', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s schema-based validation improve performance compared to standard middleware validation?', N'Middle', N'Fastify uses Ajv to compile JSON schemas into highly optimized JavaScript functions during startup. This avoids the overhead of parsing and validating request bodies at runtime using interpreted logic, significantly reducing CPU cycles per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'601ed865-3777-4481-9a8b-93c0611d6b72', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the difference between Least Recently Used (LRU) and Least Frequently Used (LFU) eviction policies.', N'Middle', N'LRU evicts items based on the time of last access, assuming that recently used data is likely to be needed again soon. LFU evicts items based on the total count of accesses, which is better for scenarios where access patterns are stable but individual items vary significantly in popularity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7ae8502-59db-4179-ba20-93c389da3061', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do Tailwind''s ''peer'' modifiers work?', N'Junior', N'Peer modifiers allow you to style an element based on the state of a preceding sibling element. By adding the peer class to one element, you can use peer-checked: or peer-focus: on a sibling to apply styles when the first element changes state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
