INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9abfa00-588f-440e-9879-93c8a96a4efc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When is it appropriate to ask for help from a senior developer?', N'Junior', N'It is appropriate to ask for help after you have spent a reasonable amount of time investigating the issue, documenting your findings, and attempting various potential solutions. Asking for help is not a sign of failure, but a way to ensure efficiency when you are blocked and need a fresh perspective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22a117a8-f3e9-45cf-9e69-93c9df3d36e9', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'When building a RESTful API in Flask, how should you handle long-running tasks to maintain responsiveness?', N'Senior', N'Long-running tasks should be decoupled from the HTTP request-response cycle by offloading them to a background task queue like Celery or RQ. The API should return an immediate 202 Accepted status with a reference to the task, allowing the client to poll or receive a webhook notification upon completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2420caf-b0a8-4de2-99e7-93ca0b5cfd79', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When is it appropriate to use a Graph database compared to a Relational database with recursive CTEs?', N'Senior', N'Graph databases are optimized for traversing complex, multi-hop relationships where the depth of the relationship is unknown or variable. While SQL can handle recursion, it performs poorly at scale for highly connected networks; graph models provide O(1) traversal time regardless of total data size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
