INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd29b22b2-bd8d-40c7-9259-93d8a4b8ce6b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of ''Safe Points'' in the context of thread suspension for GC.', N'Senior', N'Safe points are locations in the code where the state of the JVM is guaranteed to be consistent, allowing the GC to pause threads safely. The JVM forces threads to reach these points by using a global flag, ensuring that no thread is mid-operation when the GC needs to perform root scanning or heap compaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
