INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c693edd3-e5ca-43f7-a33f-93df17cf2237', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does the item size limit affect DynamoDB design?', N'Middle', N'DynamoDB has a 400 KB limit per item, which forces developers to design data models that either split large objects across multiple items or offload large binary data to Object Storage like S3. This limit ensures predictable performance and low latency for operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
