INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbfe8aa1-7693-4de6-ab9c-93e4961cf252', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain how AdonisJS manages database connection pools and why this matters for high-concurrency systems.', N'Senior', N'AdonisJS manages a configured pool of database connections that are reused across requests, avoiding the overhead of establishing a new connection for every query. This is critical for high-concurrency, as it prevents the database from being overwhelmed by connection handshake requests, which can lead to latency spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
