INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0819e7a-0945-472c-bce0-93e7f459c86f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s architecture handle CSS encapsulation compared to CSS-in-JS libraries?', N'Senior', N'Svelte generates scoped CSS at compile-time by hashing class names and injecting them into the stylesheet, ensuring no style leakage without runtime overhead. Unlike CSS-in-JS libraries that inject styles via JavaScript during execution, Svelte''s approach eliminates the need for runtime style calculations and reduces the overall JavaScript payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'420edc61-aac6-47f0-ad34-93ea38a08d3f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How can you implement cross-origin resource sharing (CORS) in Echo?', N'Middle', N'CORS is handled via Echo''s middleware package, which allows for granular configuration of allowed origins, methods, and headers. This ensures that the server can securely manage cross-domain requests without exposing the application to unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
