INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a9004b8-40b2-4054-beb9-93f141c3f969', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you factor in external dependencies when estimating a task?', N'Fresher', N'I identify any task that relies on another person, team, or system to provide input or approval. I then estimate the time needed for those external parties to complete their part and add a buffer for communication delays. Clearly stating these dependencies as assumptions helps manage expectations regarding the timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f949028a-0dc0-4c0e-8ec1-93f434124c22', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does the Django ORM handle database-level constraints, and why might you define them at the model level versus the database level?', N'Senior', N'Django model constraints provide metadata for form validation and data integrity, while database-level constraints ensure enforcement at the storage layer. Relying solely on the ORM is insufficient for high-concurrency systems, where database-level constraints act as the final authority against race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
