INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1db69075-9fc0-4f4c-8b3c-93f6d9ef75c9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''static'' storage class specifier do in C?', N'Fresher', N'A static variable retains its value between function calls, meaning it is not destroyed when the function exits. When applied to a global variable or function, it limits its scope to the file in which it is defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dddbd96-48b0-4d58-a060-93f731e8234b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'When would a developer choose the JVM mode over the Native mode in production?', N'Senior', N'JVM mode is preferred when the application requires dynamic class loading, extensive use of reflection, or when peak throughput and JIT-optimized performance are more important than startup speed. It is also easier to maintain, as it avoids the complexity and long build times associated with native compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b794a819-362f-4d1c-aa38-93f786c98459', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the network bandwidth requirements for a geo-distributed system?', N'Senior', N'I aggregate the data volume per inter-region request and account for the replication lag and synchronization overhead required for cross-region data consistency. I then model these against the peak traffic patterns to ensure that the infrastructure can handle the inter-regional traffic without incurring excessive latency or saturation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e38c4e0-6598-48b7-8c3d-93f853a4d48f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI manage automatic API documentation generation, and why is this useful for system architecture?', N'Senior', N'FastAPI automatically generates OpenAPI and JSON Schema definitions based on path operation parameters and Pydantic models. This ensures that documentation is always in sync with the codebase, facilitating better contract-driven development and integration with frontend or gateway services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'590c10b5-7ac6-41d9-a6df-93f90a02f846', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When might you sacrifice code readability for performance?', N'Intern', N'This is acceptable only in highly performance-critical sections of the system where the bottleneck has been identified. For the vast majority of the application, readability is more important because it reduces bugs and future development time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d3fbf7c-ff34-48b6-862e-93f9ea9f328a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Database per Service'' the recommended pattern, and what is the primary challenge it introduces?', N'Senior', N'It ensures loose coupling and prevents services from accessing each other''s private data, enabling independent scaling and technology choices. The primary challenge is performing joins or complex queries across services, which often requires implementing CQRS or API composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a9edf37-3819-4ecb-8047-93faae757173', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the function of .attr() versus .prop()?', N'Junior', N'.attr() is used to get or set HTML attributes as they appear in the markup. .prop() is used to get or set properties of the DOM element, which is generally preferred for boolean attributes like checked, disabled, or selected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94ab8b37-ed45-4b9e-a77d-93faf8b9668d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does it mean for Remix to be ''data-centric''?', N'Intern', N'Being data-centric means the framework is built around the idea that loading data is the most important part of a request. Remix emphasizes fetching data directly on the server for every route to ensure the UI is always in sync with the backend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db6237ca-eace-47f6-bf50-93fca4166148', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What does ''Fetch API'' compliance mean for Hono?', N'Intern', N'It means Hono relies on the standardized Request, Response, and Headers interfaces found in modern browsers and runtimes. This compliance ensures that Hono code is portable and follows current web standards rather than platform-specific conventions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'794d0022-e291-4f9f-82f0-93fe40e4f1b8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the ''res'' object in Express?', N'Intern', N'The ''res'' object represents the HTTP response that the Express application sends when it receives an HTTP request. It provides methods to send data back to the client, such as rendering views, sending JSON objects, or setting HTTP status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18b88d61-2a74-43b6-b8d3-9400e9b67359', N'075b8862-431c-4678-9767-f55359758a4a', N'When would you prefer a custom directive over a component?', N'Middle', N'Custom directives are best suited for low-level DOM access, such as focusing an input, handling click-outside logic, or integrating non-Vue libraries. Components should be used for UI elements that contain their own template and logic, whereas directives are for augmenting behavior on existing elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39ffd60a-5a5e-4812-995d-9409de0e3276', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the role of the PHP-FPM process manager and how it handles concurrency compared to traditional CGI.', N'Senior', N'PHP-FPM acts as a FastCGI process manager that maintains a pool of persistent worker processes, avoiding the overhead of spawning a new process for every request. It manages worker lifecycles, load balancing, and graceful shutdowns, providing better scalability and resource management than traditional CGI which required process creation per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73a0ce7d-1933-4dd9-84a1-940a161445b9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do ''Bloom Filters'' improve performance in LSM-tree based databases?', N'Senior', N'Bloom filters are probabilistic data structures that allow the system to determine if a key exists in a specific SSTable without reading the file from disk. This significantly reduces I/O overhead by skipping files that definitely do not contain the requested data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95984103-58a4-4686-b722-940dc5ee0dbb', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''payload'' in the context of Nuxt rendering?', N'Middle', N'The payload is the state of the application at the end of the server-side rendering process. It is serialized and embedded in the HTML so that the client-side app can restore the state without having to re-fetch the data that was already processed on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28d364c7-d25f-4468-9132-940e3d820bbc', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of ''match.call()'' in function development?', N'Middle', N'match.call captures the exact call made to a function, including the arguments and their assigned values. It is frequently used in metaprogramming to record how a function was invoked, which is helpful for debugging or for creating wrappers that pass arguments to other functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f7569ba-ffc2-4019-929c-940fc3eb2a71', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between an initializer and a deinitializer?', N'Junior', N'An initializer prepares an instance of a class, structure, or enumeration for use by setting initial values for stored properties. A deinitializer is called immediately before a class instance is deallocated to perform any necessary cleanup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eaeafca-89e0-42ab-9b04-940fd44e9c11', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the advantages of using Webpack''s ''persistent caching'' feature?', N'Senior', N'Persistent caching stores the result of compilation and module resolution on the filesystem across multiple build runs. This drastically reduces incremental build times by avoiding redundant parsing and transformation tasks when the source code hasn''t changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a6b09ce-2b8e-4b7f-90ed-94103c59a8b1', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'When should you use Echo''s ''Echo.Start'' vs ''Echo.StartServer''?', N'Middle', N'Start is a convenience method for simple applications, while StartServer allows for finer control over the HTTP server configuration, such as timeouts and TLS settings. Using StartServer is generally preferred in production to ensure proper server hardening.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a070f9e6-dbab-40b7-8b41-941106968ae1', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a struct and a map?', N'Junior', N'A struct is a fixed collection of fields with named types, used to represent a record of data with a known structure. A map is a dynamic collection of key-value pairs that allows for efficient lookups by key, where all keys must be of the same type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd713a74f-b479-464c-8876-941185965576', N'954a0331-deff-4399-b588-96f39fec001d', N'What is ngcc?', N'Intern', N'The ngcc(Angular Compatibility Compiler) is a tool which upgrades node_module compiled with non-ivy ngc into ivy compliant format. The postinstall script from package.json will make sure your node_modules will be compatible with the Ivy renderer. Whereas, Ivy compiler (ngtsc), which compiles Ivy-compatible code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f49305c5-1bd6-4bae-be0e-94125ecf524f', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you maintain data consistency across microservices in a distributed system?', N'Senior', N'Since distributed transactions like 2PC are often impractical due to latency and availability concerns, you typically use the Saga pattern. This involves a sequence of local transactions coordinated through asynchronous events or command orchestration, where each transaction has a corresponding compensating transaction to handle failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aded9db0-1f1f-44eb-b38d-9414db321c67', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Is Vite suitable for large-scale production applications?', N'Fresher', N'Yes, Vite is designed to be production-ready. Its production build uses Rollup, which is a mature and highly optimized tool for creating efficient, production-grade bundles for web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8612e1f-b3b0-4ebc-b38c-9415791b591c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis considered ''atomic''?', N'Intern', N'Redis operations are atomic, meaning that each command is executed completely in isolation. Even if multiple clients access the data simultaneously, the operations are processed one by one, preventing data corruption or race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecb2f2dd-233c-47f7-b275-94176a46879f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are the advantages of Rocket''s ''Data'' guard for file uploads?', N'Senior', N'The ''Data'' guard provides a controlled way to stream incoming request bodies, preventing attackers from exhausting server memory with large files. It forces developers to handle data consumption explicitly, ensuring that large payloads are processed in chunks rather than loaded into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9d4fe25-38c5-4260-afb4-941a45e6aa20', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If you cannot reproduce a reported bug, what should you do?', N'Fresher', N'You should ask the user for more specific details, such as their operating system, browser version, or the exact sequence of steps taken before the error. Without a clear path to reproduction, you cannot verify if a fix is successful.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'522456cd-aa13-4d9e-9db9-941ada6b6ed6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a decorator?', N'Intern', N'A decorator is an expression that evaluates to a function and that takes the target, name, and decorator descriptor as arguments. Also, it optionally returns a decorator descriptor to install on the target object. Let us define admin decorator for user class at design time,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40d146d4-3520-46ce-8972-941bd533db89', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle connection pooling limitations?', N'Senior', N'Redis connections are relatively inexpensive, but excessive connection churn can lead to overhead. Using connection pooling at the application level allows for reusing existing TCP connections, reducing the latency associated with the initial handshake and TLS setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7ac9752-0cb8-46e4-b3d0-941e71fcb87b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does a distributed lock manager help maintain consistency in a scaled system?', N'Senior', N'A distributed lock manager prevents race conditions by ensuring that only one process can modify a specific piece of data across multiple database nodes. It acts as a centralized coordinator for mutual exclusion, though it introduces latency and can become a bottleneck if not implemented with high availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e546139-c51d-46a7-9d14-941eec4bc9b2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach designing an API that will be used by many different clients?', N'Middle', N'I prioritize consistency, versioning, and clear documentation to ensure ease of use and long-term compatibility. I follow RESTful principles or use schema-driven approaches like OpenAPI to provide a predictable interface. I also implement robust error handling and rate limiting to protect the service from misuse while maintaining a stable contract for consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28150bb9-91c6-4c36-9143-94202b1b9fb6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are Server Components?', N'Intern', N'Server Components are React components that render exclusively on the server. Because they do not send any JavaScript to the client, they help reduce the bundle size and improve the overall performance of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b96e6846-1932-48b9-940a-9420b3afad91', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''public'' directory used for in Nuxt?', N'Intern', N'The public directory stores static assets that do not need to be processed by the build tool. Files placed here are served directly at the root of the application, such as robots.txt, favicon.ico, or images that should remain untouched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75c91912-b970-4a38-8a41-942225294851', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the limitations of Qwik''s event handling system?', N'Senior', N'Because event handlers are lazy-loaded, there is a tiny potential latency between the user interaction and the first execution of the handler. Additionally, because handlers are decoupled from the component lifecycle, complex state synchronization across non-parent components requires careful architecture using global stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'105166ba-329e-4f2f-a1f4-9422e7e08a88', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of ''Critical CSS'' and why it is used for performance optimization.', N'Middle', N'Critical CSS is the practice of identifying and inlining the styles required to render the ''above-the-fold'' content directly into the HTML document. This prevents render-blocking by allowing the browser to display the initial view immediately without waiting for the full CSS file to download and parse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84e1e068-4fb9-4d02-bba8-942425266a91', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary purpose of the +page.server.js file in SvelteKit?', N'Middle', N'The +page.server.js file is used to define load functions that run exclusively on the server. This allows developers to securely fetch data from databases or private APIs without exposing credentials to the client, while also enabling server-side rendering for that specific page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
