INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a8bea48-cedf-47a9-94cf-94391c4fc4c3', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How would you implement request rate limiting in a Django project?', N'Senior', N'Rate limiting is best handled at the infrastructure level, such as via Nginx or an API Gateway, to prevent unnecessary load on the Django application. If implemented in Django, it typically requires middleware or cache-based logic using a library like Django Ratelimit to track request counts per user or IP.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccbc9c96-fda8-461d-b4e4-943b63c30c67', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the Kotlin compiler ensure null safety at the bytecode level?', N'Senior', N'Kotlin inserts hidden null checks (via ''checkNotNullParameter'' or similar runtime methods) at the boundaries of public APIs. This ensures that even if a Java caller passes a null value to a Kotlin method, a NullPointerException is thrown immediately rather than causing non-deterministic behavior later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc3d85cb-6617-40e3-8ce0-943c4c1ad9ba', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a ''soft delete'' and a hard delete in Django, and why might you choose one over the other?', N'Middle', N'A hard delete removes the record from the database permanently, while a soft delete marks the record as inactive using a boolean flag. Soft deletes are preferred for data recovery, audit trails, and maintaining referential integrity in systems where historical data is legally or operationally required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'213c9331-2799-4ab0-b54c-943dcfb11d4e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS solve the ''specificity wars'' in CSS, and if so, how?', N'Senior', N'Yes, by providing a limited set of utility classes and discouraging complex nested selectors, Tailwind effectively eliminates specificity conflicts. Since most classes act at the same level of the cascade, you rarely encounter the need to use ''!important'' or overly specific selectors, which is a common source of bugs in large CSS codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b6fa7d1-4b6e-4d8b-81d9-94455a18d677', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Python version numbering scheme work?', N'Fresher', N'Python versions are numbered A.B.C or A.B. A is the major version number. It is only incremented for major changes in the language. B is the minor version number, incremented for less earth-shattering changes. C is the micro-level. It is incremented for each bug fix release. Not all releases are bug fix releases. In the run-up to a new major release, ''A'' series of development releases are made denoted as alpha, beta, or release candidate. Alphas are early releases in which interfaces aren''t finalized yet; it''s not unexpected to see an interface change between two alpha releases. Betas are more stable, preserving existing interfaces but possibly adding new modules, and release candidates are frozen, making no changes except as needed to fix critical bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'953df013-1743-4dd6-9c1c-9445b7747d83', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What architectural constraints does Qwik impose on developers to maintain resumability?', N'Senior', N'Developers must ensure that all state and event handlers are serializable, meaning they cannot use standard JavaScript closures that capture non-serializable scopes. This requires using specific hooks and scope-capture patterns to ensure the framework can correctly serialize and restore application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'977fe6b6-fb71-48ba-beec-9445e3616b07', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the trade-offs of using high-cardinality data in your observability metrics?', N'Middle', N'High-cardinality data, such as unique user IDs or request IDs in metrics, provides deep granularity for debugging. However, it significantly increases the storage cost and computational overhead for aggregation systems, potentially leading to performance degradation in your monitoring tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
