INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'553e6421-9a7f-4bc6-8860-944b462086a9', N'954a0331-deff-4399-b588-96f39fec001d', N'Can you explain what dependency injection is in Angular?', N'Junior', N'Dependency Injection (DI) is a core concept in Angular, where components (or services) depend on other components. Angular handles the creation and management of these dependencies. Simplified Explanation DI takes three steps: 1. Registration: Identify the components to be injected. 2. Resolution: Find the appropriate dependencies. 3. Injection: Insert the resolved dependencies. Key Angular Features Linked to DI - Modules: Angular applications are made up of modules, each with its dependency injector. - Providers: Within modules, providers offer a mechanism for registering dependencies. Code Example: DI in Angular Here is the Angular code:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
