INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'326427f6-054e-4bb9-bc5f-947ad01901f9', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you implement background tasks in NestJS?', N'Middle', N'You can use the built-in Task Scheduling module, which is based on cron jobs, or integrate a message queue like RabbitMQ or Bull. These allow for offloading time-consuming tasks from the main request-response cycle to improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
