INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0541a03-7e29-460b-b690-947dbb702bcb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is ''cache stampede'' and how can you mitigate it with Redis?', N'Middle', N'A cache stampede occurs when multiple concurrent requests attempt to regenerate a cache key that has expired simultaneously, overwhelming the database. Mitigation strategies include using mutex locks to ensure only one process regenerates the data, or implementing probabilistic early expiration to refresh keys before they actually expire.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30612d17-8319-4477-9742-947e0a6885b9', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Hydration in Next.js?', N'Intern', N'Hydration is the process where React takes the static HTML rendered by the server and attaches event listeners to it. This makes the page interactive for the user once it has been loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25056aad-7c5e-4b80-9df5-947ea785a386', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of esbuild in the Vite ecosystem and why is it used?', N'Middle', N'Esbuild is a JavaScript bundler written in Go that performs transpilation and minification at extremely high speeds. Vite uses it during development to pre-bundle dependencies and transform files, significantly outperforming legacy tools like Webpack or Rollup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98eac3cb-1b7f-48a8-a889-94828ab47fe7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a dynamic path parameter in Rocket?', N'Intern', N'A dynamic path parameter is a placeholder in a URL route defined by angle brackets. It allows the handler to extract values directly from the URL path as arguments to the function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74f5f55c-5067-4e5d-bbe1-9483a9c30199', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the BEAM in relation to Phoenix?', N'Intern', N'The BEAM is the Erlang Virtual Machine that executes Elixir and Erlang code. It provides the foundation for Phoenix''s fault-tolerant and highly concurrent nature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3f19b71-6551-42cc-a726-948500ed2f2c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a namespace in Python?', N'Intern', N'In Python, every name introduced has a place where it lives and can be hooked for. This is known as namespace. It is like a box where a variable name is mapped to the object placed. Whenever the variable is searched out, this box will be searched, to get corresponding object. A namespace is a collection of names. It maps names to corresponding objects. When different namespaces contain objects with the same names, this avoids any name collisions. Internally, a namespace is implemented as a Python dictionary. On starting the interpreter, it creates a namespace for as long as we don''t exit. We have local namespaces, global namespaces, and a built-in namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd67c57f3-9551-4fe7-9126-9485222aaf35', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the trade-offs of using Laravel''s ''Form Requests'' for validation versus performing validation within the Controller or a dedicated Service class.', N'Senior', N'Form Requests provide a clean, declarative way to enforce validation before controller logic, promoting the Single Responsibility Principle. However, if business logic dictates validation based on state, keeping it in a Service class is often more appropriate to avoid bloating the request object with complex domain knowledge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3653b7c7-8c0c-4b6a-b552-94857ec5ab75', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind manage design system versioning when multiple teams share a common design language?', N'Senior', N'Versioning is managed by publishing the shared Tailwind configuration as an internal npm package. Teams then import this configuration, ensuring that all micro-frontends or services stay in sync with the latest design tokens and architectural guidelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6d4ca24-5313-4888-99ab-948596e21bdb', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between DDL and DML?', N'Fresher', N'DDL (Data Definition Language) commands like CREATE and ALTER are used to define or modify the structure of the database objects. DML (Data Manipulation Language) commands like INSERT and UPDATE are used to manage and manipulate the actual data within those objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2729ff9f-95da-461f-bc64-948ed3db6e2f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a Lambda in Ruby?', N'Intern', N'A Lambda is a type of Proc that enforces argument count and handles returns differently. It behaves more like a regular method than a standard block, making it useful for creating reusable, strictly defined code segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f7d2a28-37ce-4e46-9e41-949043baf647', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'In what scenario would you choose to use Chi''s context-based middleware over global middleware?', N'Middle', N'You would use context-based or group-specific middleware when you need to apply logic only to a subset of routes, such as an authentication check for API endpoints but not for public health checks. This approach prevents unnecessary processing for endpoints that do not require specific security or data enrichment steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'110ab4ad-49e0-470c-ae76-94907e3a793f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of Micronaut''s ''Netty'' integration?', N'Middle', N'Micronaut uses Netty as its core non-blocking, event-driven HTTP server implementation. This allows the framework to handle a high volume of concurrent connections with low resource consumption, making it ideal for reactive and microservices architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
