INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c9d8575-4377-4dca-a8b3-949a501c0aea', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the function of the internal ''altrep'' system in R.', N'Senior', N'Altrep, or alternative representation, allows the R engine to represent vectors in specialized ways, such as memory-mapped files or sequences, without materializing the full vector in RAM. This significantly reduces memory usage and improves performance for large-scale operations on structured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
