INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36eabde4-6557-467d-a0a5-949e90b86064', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the various kinds of directives?', N'Intern', N'There are mainly three kinds of directives: 1. Components — These are directives with a template. 2. Structural directives — These directives change the DOM layout by adding and removing DOM elements. 3. Attribute directives — These directives change the appearance or behavior of an element, component, or another directive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330f4b2c-ed75-4546-8f49-94a0a168e800', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine if a database needs indexing, and what are the trade-offs?', N'Middle', N'I analyze query execution plans to identify slow operations like full table scans. While indexes significantly speed up read operations, they increase storage requirements and slow down write operations because the index must be updated. I only add indexes that provide high value for the most frequent query patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a31e968f-9f48-4e86-84be-94a147c62f57', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is ''Mean Time to Repair'' (MTTR) often considered a misleading metric in complex distributed systems?', N'Senior', N'MTTR assumes that failures are independent and linear, which is rarely true in microservices where cascading failures are common. Focusing solely on repair time ignores the frequency of incidents and the severity of impact, often incentivizing quick, brittle patches over long-term architectural stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1d9b5d8-57e8-4508-85e9-94a39fb3cd06', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle CSS scoping and what are the advantages of its approach?', N'Senior', N'SvelteKit scopes CSS to the component by default by adding unique hash-based classes to elements, preventing style leakage and the need for BEM naming conventions. Because this is done at compile-time, there is no runtime overhead for style application, keeping the CSS bundle size minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99be98d7-9b4c-4b91-875a-94a3f2848595', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is ''Write Amplification'' and why is it a concern in SSD-backed NoSQL systems?', N'Senior', N'Write amplification occurs when the amount of physical data written to the storage media is a multiple of the logical data requested by the application. In SSDs, high write amplification accelerates hardware wear and degrades performance, making it a critical metric for storage engine design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'419754d0-0a2d-4815-88f5-94a417ddd1c1', N'075b8862-431c-4678-9767-f55359758a4a', N'What are mixins?', N'Intern', N'Mixin gives us a way to distribute reusable functionalities in Vue components. These reusable functions are merged with existing functions. A mixin object can contain any component options. Let us take an example of mixin with created lifecycle which can be shared across components, Note: Multiple mixins can be specified in the mixin array of the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b184ff7d-48b2-4532-af88-94aa75645044', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery .ajax() method?', N'Fresher', N'The .ajax() method is the core function for performing asynchronous HTTP requests. It allows you to load data from a server without refreshing the entire web page, which is essential for dynamic web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8c2ded7-31d0-48ea-8d84-94ac7c96c25a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the architectural implications of Remix''s ''Actions'' on standard HTTP form handling.', N'Senior', N'Remix treats form submissions as first-class citizens by leveraging standard HTML form POSTs, which are intercepted by server-side Actions. This architectural choice enables functional applications to work without client-side JavaScript, while progressive enhancement ensures a seamless transition to a SPA experience once the bundle hydrates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee22b6f-e2f8-4961-b470-94ad7bd29d2e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle asset modules compared to the older ''url-loader'' or ''file-loader''?', N'Middle', N'Asset modules are a built-in feature in Webpack 5 that replaces the need for extra loaders to handle assets like images or fonts. They provide a unified way to emit separate files, inline assets as data URIs, or automatically choose between the two based on file size, simplifying configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a236db61-6512-4a4a-a504-94aecc5a52f1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When a project deadline is tight, how do you manage the trade-off between technical debt and shipping a feature?', N'Middle', N'I communicate the long-term maintenance costs of shortcuts to stakeholders to ensure transparency. If a compromise is necessary, I document the technical debt clearly and schedule a follow-up task in the roadmap to refactor the code once the immediate deadline is met. This ensures we deliver value while maintaining accountability for system quality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51dbcec2-65de-4ff6-bba4-94aefb7405ac', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber have a built-in logger?', N'Intern', N'Fiber provides a standard logger middleware that can be attached to the application. This middleware automatically logs information about every incoming request, such as the HTTP method, URL, status code, and execution time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4113941-a2c8-4c23-ba92-94b196bfc6f6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Describe the purpose of Micronaut''s ''Configuration Properties'' and how they facilitate environment-specific deployments.', N'Middle', N'Configuration Properties allow developers to bind external configuration files or environment variables directly to Java objects using type-safe annotations. This mechanism enables easy switching between development, testing, and production profiles by simply swapping configuration sources without changing the underlying business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28f191ac-9058-4196-9129-94b1d0337812', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the architectural implications of choosing a hashed shard key vs. a ranged shard key?', N'Senior', N'A ranged shard key supports efficient range-based queries but risks hotspots if the key is monotonically increasing. A hashed shard key ensures an even distribution of data across shards by randomizing the location, but it prevents efficient range scans since related data is scattered across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'398f5ecf-de88-4f05-91a8-94b33b39349f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a ''hot partition'' in DynamoDB?', N'Intern', N'A hot partition occurs when a large volume of read or write requests is directed at a single partition key. This can lead to throttling if the request rate exceeds the capacity allocated to that partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94bbdddd-7b9b-4d8e-b787-94ba5ff65a08', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between ''vite'' and ''vite build''?', N'Fresher', N'The ''vite'' command starts the local development server with hot module replacement, while ''vite build'' executes the production build process to create a set of optimized static files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02d20d29-49d1-4846-b16f-94bb91ae54e8', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Is Chi a full-stack framework?', N'Intern', N'No, Chi is a micro-framework or library focused solely on routing. It does not include ORMs, template engines, or database drivers, as those are considered separate concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c399c452-584a-4025-96d3-94bbed82cf71', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a caching strategy, what is the trade-off between write-through and write-back caching?', N'Senior', N'Write-through caching ensures data consistency between the cache and the backing store, which is safer but introduces higher latency on every write. Write-back caching improves write performance significantly but poses a risk of data loss if the cache node fails before the data is persisted to the primary store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
