INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26e07b8b-bd48-4ee6-9b8e-94c3b9f4d326', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the significance of the ''hash slot'' concept in Redis Cluster.', N'Senior', N'Redis Cluster uses 16,384 hash slots to distribute keys across multiple nodes, ensuring balanced data distribution and easy rebalancing. By mapping keys to slots using CRC16, the system can determine the node responsible for any given key, enabling transparent horizontal scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e322c3c7-9cab-4798-87c3-94c49e12f22c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to handling service failures in a system with many dependencies?', N'Middle', N'I implement circuit breakers to stop cascading failures and provide graceful degradation. I also use retry strategies with exponential backoff and jitter to avoid overwhelming recovering services. Monitoring and alerting are crucial to identify which dependency is causing the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b66c31fb-73a6-4f3c-a6f8-94c721db1c3c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of using JSON Schema for validation?', N'Fresher', N'Using JSON Schema provides a standardized way to define expected data formats, which allows Fastify to perform automated validation. This prevents invalid data from reaching your business logic and helps generate clear API documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8edea266-67e2-476d-a29f-94c7abcbb476', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Compare the ''Ask'' pattern with the ''Fire and Forget'' pattern in terms of system coupling.', N'Senior', N'The Ask pattern introduces strong coupling because the sender must wait for a response, often resulting in a synchronous-like flow that can increase latency. Fire and forget promotes loose coupling and higher throughput, but requires alternative mechanisms, such as state polling or event streaming, to verify task completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc8d5f51-51fc-429f-8e60-94c8a2c347ba', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi manage URL parameter parsing, and how does this affect memory allocation?', N'Senior', N'Chi extracts URL parameters into a context-bound structure, minimizing heap allocations by reusing memory where possible. This is critical in high-concurrency scenarios, as it reduces Garbage Collector pressure compared to frameworks that generate large numbers of temporary objects during routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ed0b9c4-febf-4807-a097-94c9d11f1379', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask sessions and how do they differ from cookies?', N'Junior', N'Sessions allow you to store information specific to a user across multiple requests, usually implemented using a signed cookie. While a cookie is just a piece of data stored in the browser, a session provides a secure way to persist data on the server or client-side with encryption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
