INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'342d26a0-3317-456e-bae0-94cda81780ab', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is Hono and why is it used in backend development?', N'Fresher', N'Hono is a lightweight, high-performance web framework designed for edge computing environments like Cloudflare Workers. It is used because it is ultra-fast, has a tiny footprint, and is built to work seamlessly across various JavaScript runtimes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
