INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66faeab3-e48b-4825-8092-94d35dc341c8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between feature velocity and technical debt?', N'Senior', N'I view technical debt as a financial loan where interest is paid in developer productivity. I balance the immediate need to capture market share with the long-term maintainability of the codebase by scheduling ''debt repayment'' periods into the roadmap based on the impact of current bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6d4d49e-0be8-44a4-88d7-94d470b58d0f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are optional parameters in Dart functions?', N'Fresher', N'Optional parameters allow functions to accept varying numbers of arguments. They are categorized as either optional positional parameters, enclosed in square brackets, or optional named parameters, enclosed in curly braces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c132e4-52d6-4430-a302-94d5a8ef7ca1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a unique index and a regular index?', N'Junior', N'A regular index improves query speed but allows duplicate values for the indexed field. A unique index enforces that no two documents have the same value for that specific field, effectively preventing data duplication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaffaf55-561f-41b5-b5d6-94d731152a44', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the architectural benefit of decoupling the UI layer from the Redux store structure.', N'Senior', N'Decoupling allows the internal state schema to evolve or be refactored without breaking the UI components. By using selectors as a translation layer, components remain unaware of the store''s shape, ensuring that UI components are reusable and decoupled from the data storage strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4be982ae-470a-4b5d-8840-94db2ce0e029', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the purpose of the App Router''s ''layout.js'' file in Next.js.', N'Junior', N'A layout file is used to share UI components across multiple pages, such as navigation bars or footers, that should remain persistent during navigation. It wraps nested children components, allowing the shared UI to stay mounted and maintain its state while only the specific page content updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cf1ddaa-b419-4a19-8e33-94dc104f2c40', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you choose between RabbitMQ and Apache Kafka?', N'Middle', N'Choose RabbitMQ for complex routing requirements, lower latency, and simpler management where messages are typically deleted after consumption. Choose Kafka for high-throughput, log-based storage, replayability, and handling massive streams of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98b8cdca-aa4e-4a40-a31f-94dc12cc9fae', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do database locks affect concurrency in MySQL?', N'Middle', N'Locks ensure data integrity by preventing multiple transactions from modifying the same data simultaneously. However, excessive locking, especially at the table level, can lead to contention and blocking, where transactions wait for each other to finish, effectively serializing access and reducing performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0546f03e-1958-4a1b-87a3-94dce51b14e8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When tasked with refactoring a legacy system that lacks documentation and test coverage, how do you proceed?', N'Middle', N'I would start by creating a safety net of integration tests around the critical paths to ensure current behavior is captured. Then, I would refactor incrementally, focusing on small, isolated modules while continuously validating against the new test suite to prevent regressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddf69f46-b9c3-4f0b-948d-94dd1037eded', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of type narrowing and provide examples of how it is achieved.', N'Middle', N'Type narrowing occurs when the compiler deduces a more specific type for a variable within a certain scope. It is achieved through type guards such as typeof checks, instanceof operators, equality checks, or user-defined type predicates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17e3a98d-c29e-4ca3-a8e4-94dd24974e09', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C standard define the behavior of integer overflow?', N'Senior', N'For unsigned integers, overflow is defined as modulo arithmetic, wrapping around. However, signed integer overflow is undefined behavior, allowing the compiler to optimize code under the assumption that the overflow never happens, which can lead to unexpected logic paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'076e6804-78fa-45ea-b662-94ddcb6d4422', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the translog in Elasticsearch, and how does it relate to the Lucene commit process?', N'Senior', N'The translog is a write-ahead log that prevents data loss between Lucene commits by recording every operation before it is acknowledged. Lucene commits, which flush segments to disk, are expensive operations; the translog ensures that if a node crashes before a commit, operations can be replayed upon restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'167f0c66-bfd2-45b8-aee1-94de145a95b9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the significance of data types in database design?', N'Junior', N'Data types define the kind of information a column can hold, such as integers, strings, or dates. Choosing the correct data type ensures data consistency, saves storage space, and allows the database engine to perform operations more efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
