INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12507db8-6ec4-4123-a533-94fc7f47bb03', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can DynamoDB be used for relational data?', N'Intern', N'While DynamoDB is a NoSQL database, it can model relational data using techniques like denormalization or by using multiple tables and indexes. However, it does not support SQL joins, so it is optimized for different access patterns than traditional RDBMS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'084c5188-bd53-45ec-83b8-950167233514', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a managed cloud service versus self-hosting infrastructure?', N'Junior', N'Managed services significantly reduce operational overhead and provide built-in reliability, though they are usually more expensive. Self-hosting provides full control and potentially lower costs at scale, but it requires a dedicated team to manage maintenance, security patches, and hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fc3117c-16d0-44aa-b2d2-9504344846a2', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Does Echo allow you to modify response headers?', N'Intern', N'Yes, the Context object provides methods to access and modify the response headers before the response is sent to the client. This is useful for setting cookies, security policies, or caching instructions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29b4476e-9aba-4b96-8ea4-95093652610d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the benefit of component stack trace from error boundary?', N'Intern', N'Apart from error messages and javascript stack, React16 will display the component stack trace with file names and line numbers using error boundary concept. For example, BuggyCounter component displays the component stack trace as below, !stacktrace', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dced03ec-00a5-47c6-8d64-950d51583a2e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a ''HTTPException'' in FastAPI?', N'Intern', N'An ''HTTPException'' is a special exception that you can raise within your code to return an error response to the client. It allows you to specify the status code and the error message to be returned when something goes wrong.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eebe74c-bad7-4bdb-ad5f-950d76da848e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Describe how to handle graceful shutdowns in a FastAPI application to ensure data integrity.', N'Senior', N'Utilize the ''lifespan'' context manager to define startup and shutdown logic, such as closing database pools or flushing caches. This ensures that the application finishes pending requests and releases system resources cleanly before the process exits, preventing data corruption or connection leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba47c2d0-a343-4ad9-93d8-950ee3d79c74', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role of Custom Providers in NestJS and why they are useful for dependency injection.', N'Middle', N'Custom providers allow you to inject dependencies that are not simple classes, such as values, factory functions, or existing instances. They are crucial for implementing the strategy pattern, mocking dependencies during unit testing, or handling complex initialization logic that standard constructor-based injection cannot easily manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7db0ee63-ba75-4347-97f5-95108c9124f3', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Discuss how Dart handles asynchronous exceptions compared to synchronous ones.', N'Senior', N'Synchronous exceptions are caught by standard try-catch blocks within the current execution scope, whereas asynchronous exceptions must be caught through Future error handlers or async-await try-catch blocks. Because asynchronous code can execute outside the original stack, the runtime must propagate these errors across event loop cycles to maintain stack trace integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a7a8a1-e8bf-463a-acf8-951218efb0de', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why would an architect choose Litestar over an older framework for a new microservice?', N'Senior', N'Litestar offers a more modern architectural approach by prioritizing type safety, explicit dependency management, and high-performance reflection. Its design is better suited for modern Python practices that emphasize maintainability and performance in asynchronous environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5bd2014-411b-4b1e-a29e-9514733dcd3d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between synchronous and asynchronous communication in microservices?', N'Senior', N'Synchronous communication is easier to reason about and debug, but it creates tight temporal coupling and cascading failure risks. Asynchronous communication via message queues improves system resilience and decoupling but increases architectural complexity regarding eventual consistency and observability. I prefer async for non-blocking workflows to ensure system stability under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9013ccfd-b99c-43cf-a140-95147bace281', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP 8''s Just-In-Time (JIT) compilation work, and what are its limitations in typical web applications?', N'Senior', N'The JIT compiler translates bytecode into machine-level instructions at runtime for specific hot code paths. In typical I/O-bound web applications, the performance gains are negligible because execution time is dominated by database queries and network calls rather than CPU-intensive computations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6641e432-bd47-474e-8506-9517933aba64', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain how Python handles exception propagation and the role of the ''traceback'' object.', N'Senior', N'When an exception is raised, Python unwinds the call stack until it finds a matching ''except'' block. The ''traceback'' object is created to store the stack frames, line numbers, and file information, providing a detailed history of the execution path that led to the exception.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'051f9b7e-511f-47ac-ad05-951a067b3512', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js differ from frameworks like React or Angular?', N'Fresher', N'React and Angular are heavy, full-blown frameworks that usually require a build step and a complex component structure. Alpine.js is designed to be dropped into a page via a script tag and works directly within your existing HTML, making it ideal for smaller projects or enhancing static sites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c77ee45-034a-4dfa-abc5-952180069dd0', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'The difference between Serial and Parallel Garbage Collector?', N'Fresher', N'1. Serial Garbage Collector: Serial garbage collector works by holding all the application threads. It is designed for the single-threaded environments. It uses just a single thread for garbage collection. The way it works by freezing all the application threads while doing garbage collection may not be suitable for a server environment. It is best suited for simple command-line programs. Turn on the -XX:+UseSerialGC JVM argument to use the serial garbage collector. 2. Parallel Garbage Collector: Parallel garbage collector is also called as throughput collector. It is the default garbage collector of the JVM. Unlike serial garbage collector, this uses multiple threads for garbage collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1de174d4-2574-45d9-9492-952416d28a9f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails filters (before_action, etc)?', N'Fresher', N'Filters are methods that run before, after, or around controller actions. They are commonly used for tasks like authenticating users, setting up shared data, or performing logging before the main logic of the action executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb24c602-4560-4d53-a7d6-9526ef28d11e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Symfony Cache component?', N'Intern', N'The cache component provides a standard way to store and retrieve data temporarily to improve application performance. It reduces the need to re-calculate expensive operations or re-fetch data from the database on every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c901ad83-934a-442c-8476-952788e34016', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is ''Code Splitting'' important in Qwik?', N'Fresher', N'Code splitting is essential to keep the initial JavaScript bundle size small. By splitting code into smaller chunks, Qwik ensures that the browser only downloads the specific code needed for the current view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f930492b-a2fe-4205-8a4d-9528c0b888a8', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of ngIf directive?', N'Intern', N'Sometimes an app needs to display a view or a portion of a view only under specific circumstances. The Angular *ngIf directive inserts or removes an element based on a truthy/falsy condition. Let''s take an example to display a message if the user age is more than 18: Note: Angular isn''t showing and hiding the message. It is adding and removing the paragraph element from the DOM. That improves performance, especially in the larger projects with many data bindings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6cca1ec-7af1-4a0f-9297-952a45a0da19', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why does Scala prefer immutable data structures over mutable ones?', N'Middle', N'Immutable structures simplify reasoning about state, eliminate side effects, and are inherently thread-safe in concurrent environments. This reduces the need for explicit locking mechanisms, making programs easier to test and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa8fb6d1-8ba1-4223-a6d7-952b3ff62818', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is ''Distributed Consensus'' and why is it important for reliability?', N'Senior', N'Distributed consensus allows multiple nodes in a system to agree on a single state despite network failures or latency. It is essential for maintaining consistency in distributed databases, configuration stores, and leader election processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4efaacd6-85f7-424e-acba-952b602af4e3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the event loop in JavaScript?', N'Intern', N'JavaScript is single-threaded — it can execute only one task at a time. The event loop is the mechanism that allows JavaScript to perform non-blocking I/O operations (like network requests and timers) despite this single-thread constraint. How it works: 1. Synchronous code runs on the call stack first. 2. Async operations (e.g. setTimeout, fetch) are handed off to Web APIs. 3. When complete, their callbacks are pushed to a queue. 4. The event loop continuously checks: *"Is the call stack empty?"* — if yes, it dequeues the next callback and pushes it onto the stack. Microtask queue vs. macro-task queue: * Microtasks (Promises .then/.catch, queueMicrotask, MutationObserver) are processed before the next macro-task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a12e821-6e94-4235-8084-952c196c4240', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you distinguish between a front-end and a back-end issue when a feature fails?', N'Junior', N'I would use the browser''s developer tools to inspect network requests to see if the API call is being sent, if it returns an error, or if the response data is malformed. If the request never leaves the browser, it is likely a front-end logic issue, whereas an error response indicates a back-end problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77980634-151a-4e7f-874d-952d40e0ba32', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the ''volatile'' qualifier?', N'Middle', N'Volatile tells the compiler that the value of an object can change at any time due to external factors like hardware or an interrupt service routine. It prevents the compiler from performing optimizations like caching the value in a register, ensuring that every read or write actually touches memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21e18907-5e72-4138-a620-952d74af7734', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If you need to store user passwords, what is your approach to security?', N'Junior', N'I never store passwords in plain text. I use a strong, salted cryptographic hashing algorithm like Argon2 or bcrypt to ensure that even if the database is compromised, the actual passwords remain protected and difficult to reverse-engineer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccdd7fa5-b29d-46b2-a1c2-952eaca2d2cc', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the shadow DOM in the context of Lit?', N'Intern', N'The shadow DOM is a browser technology that allows for scoping CSS styles and DOM elements within a component. Lit uses it to ensure that styles defined inside a component do not leak out or get affected by styles from the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb822fdc-0a5a-49a8-96e8-952ecc282a95', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the function of the render method in a Lit component?', N'Intern', N'The render method is a lifecycle function that defines the structure and content of the component''s UI. It returns a template that Lit uses to efficiently update the DOM whenever the component''s state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b86ab6d6-d7a9-4467-89e8-952f57e8f8c1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Can Express serve multiple static folders?', N'Fresher', N'Yes, you can call the express.static middleware multiple times for different directories. Express will look for the file in the order the middleware functions were defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40620e76-79bf-4fbd-ab04-952f8420aa97', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact use the Virtual DOM?', N'Fresher', N'Yes, Preact uses a Virtual DOM to manage updates efficiently. It creates a lightweight representation of the actual DOM and compares changes to minimize the number of direct manipulations, which leads to faster rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1be745e6-f053-4442-8202-9532420685fe', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Define ''Database Partitioning'' and its impact on performance.', N'Middle', N'Partitioning divides a large table into smaller, more manageable pieces based on a specific key, such as a date or region. This improves performance by allowing queries to scan only the relevant partition rather than the entire dataset, and it facilitates easier data archiving or maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5b60bdf-7fbc-42f1-ba9f-95334f7b0ca7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s memory management handle cyclic references?', N'Senior', N'Python primarily uses reference counting for immediate memory reclamation, but it also employs a cyclic garbage collector. This collector periodically scans containers like lists and dictionaries to detect and break reference cycles that would otherwise lead to memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8680bd7b-6e16-436f-89de-9535051938b6', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle write operations differently than an RDBMS?', N'Junior', N'Cassandra uses a log-structured merge tree approach, where writes are appended to a commit log and written to an in-memory structure called a Memtable. This makes writes extremely fast because they avoid random disk I/O, unlike RDBMS which often requires complex locking and index updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a4873ec-f30e-4af9-b642-9536a1618777', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the concept of ''context locals'' in Flask.', N'Middle', N'Context locals are objects that behave like global variables but are actually thread-local or greenlet-local. They allow Flask to keep request and application information isolated to the current execution context, enabling the framework to handle concurrent requests safely without data leakage between users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'747005a7-8e0b-4ff3-9d3d-95376913e765', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does JavaScript''s prototypical inheritance differ from classical inheritance in terms of memory usage?', N'Senior', N'Prototypical inheritance uses a delegation-based model where methods are shared on a single prototype object rather than copied to every instance. This significantly reduces memory footprint when creating thousands of objects compared to classical models that might duplicate method definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'913e1555-1751-4136-9821-953789ead844', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails ''params''?', N'Fresher', N'The params object is a hash-like container that holds data submitted by the user through a web request. This includes data from URL query strings, form submissions, and route variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac32b49f-25cd-41cc-84ba-9539123459e2', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the difference between a Service Provider and a Middleware.', N'Middle', N'Service Providers are the central place to configure and register application services, bindings, or event listeners during the application bootstrap process. Middleware acts as a layer between a request and your application, providing a convenient mechanism for inspecting and modifying HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a54e5402-299c-47d7-bd10-953923ac113f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why might you need to configure ''define'' in the Vite configuration file?', N'Middle', N'The ''define'' option allows for the replacement of global constants during the build process. This is useful for injecting feature flags or build-time metadata that can be tree-shaken away if the condition evaluates to false.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21ed2c4e-77f1-4f4f-bb82-9539a3ebb4ce', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you evaluate the reliability of a third-party service before integrating it into your architecture?', N'Middle', N'I review their service level agreements (SLAs), historical uptime records, and public status pages. I also perform a ''stress test'' integration in a sandbox environment to see how their API behaves under simulated load and failure conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6778c3cc-4f25-4c3f-9ef9-953a6cebc5b5', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''InternalsVisibleTo'' attribute affect C# project encapsulation?', N'Senior', N'This attribute allows internal members of one assembly to be accessed by another designated assembly. While useful for unit testing private logic, it effectively bypasses internal-level access modifiers, which can erode encapsulation boundaries if overused across a large system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
