INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69834c56-05e4-4d64-a058-953d58532dc2', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between model methods and model managers?', N'Junior', N'A model method is a function that acts on a specific instance of a model, such as calculating a value based on a record''s fields. A manager is an interface that acts on the entire model class to perform database queries, such as filtering or creating records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bdc862f-d4fe-46d6-9f04-953e018e166b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the architectural difference between Fastify''s ''preHandler'' and ''preSerialization'' hooks.', N'Senior', N'preHandler runs before the route handler is executed, making it ideal for authentication or input validation. preSerialization runs after the handler has produced a result but before it is turned into a string, which is the perfect place to format or mask sensitive data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
