INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaaf0d4a-0eb0-4450-9de7-953fb221b79f', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the ''Quarkus DI'' (Dependency Injection) container compared to standard CDI?', N'Senior', N'Quarkus uses a subset of the CDI specification that is optimized for build-time resolution. By resolving dependencies at build time, it avoids the overhead of runtime annotation scanning and provides better error reporting for injection failures before the app ever runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'898e31b3-7f78-4461-b495-95403a42d562', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing a user interface, why is consistency across different screens important?', N'Intern', N'Consistency creates a predictable experience, which reduces the learning curve for users and helps them understand how to interact with the system intuitively. When buttons, navigation patterns, and visual styles remain uniform, users spend less time figuring out the interface and more time accomplishing their tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6888f7c1-3f9e-4fdf-936c-9548a73a1b9f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the benefit of enabling ''strictNullChecks'' in a TypeScript project?', N'Middle', N'Enabling ''strictNullChecks'' ensures that null and undefined are not implicitly included in every type, forcing the developer to handle potential absence of values explicitly. This prevents common runtime errors caused by attempting to access properties on null or undefined objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd148b89b-4fa6-4b97-a0a0-9548a80c31cd', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the differences between inheritance and partitioning in PostgreSQL?', N'Middle', N'Inheritance allows a table to inherit columns from a parent, but it is rarely used for performance today. Partitioning breaks a large table into smaller, physically separate pieces based on a key like a date or range, which improves query performance through partition pruning and makes maintenance tasks like deleting old data much faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a758e2d-23d0-4650-a8b7-954c0395ca90', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How can you achieve primary key - foreign key relationships in MongoDB?', N'Fresher', N'The primary key-foreign key relationship can be achieved by embedding one document inside the another. As an example, a department document can have its employee document(s).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62d0309a-5254-410e-8a7e-954c8e872b66', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of a ''Write-Ahead Log'' (WAL) in database durability?', N'Middle', N'A WAL is a file that records all modifications to the database before they are permanently applied to the actual data files. It ensures durability by allowing the database to recover to a consistent state in the event of a crash, as the log can be replayed to restore lost operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'464908c6-331a-47ef-bf0e-954c8f9d87f1', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the role of the Route file in Laravel.', N'Fresher', N'The route file acts as the entry point for all incoming HTTP requests to the application. It maps specific URLs to the corresponding controller methods or closures, ensuring that the application knows exactly which logic to execute for a given endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0aaa693-9065-43a4-a8f8-954d9ff23104', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a collection in the context of document databases?', N'Junior', N'In a document database, a collection is a group of related documents, similar to a table in a relational database. Unlike tables, collections do not enforce a rigid schema on the documents they contain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b464c29a-0a5e-4c68-8c73-95542436f631', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the useCallback hook in React and when should it be used?', N'Fresher', N'useCallback returns a memoized function whose identity only changes when one of its dependencies changes. The point is referential stability — so a React.memo-wrapped child does not re-render, or a useEffect whose deps include the function does not re-fire. Re-creating a plain function literal each render is essentially free; the actual cost being avoided is the downstream work triggered by a new reference. > Note for 2026: with the React Compiler (stable in React 19), most components no longer need manual useCallback / useMemo / React.memo — the compiler memoizes automatically. New code targeting a compiler-enabled project should generally not reach for useCallback unless profiling shows a specific need. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cfb47fc-4df1-4afd-8d8e-95543a60d2a0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the benefit of using ''Nuxt Layers'' for enterprise-level projects.', N'Senior', N'Nuxt Layers enable the composition of multiple Nuxt applications into a single project, allowing for the sharing of layouts, components, and configurations across different sub-sites or themes. This promotes a micro-frontend-like architecture where common UI design systems can be maintained in a base layer and extended by specific applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8d3105c-8486-4d51-9f68-955841e44ed8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the ''Retry'' pattern implementation in Micronaut.', N'Middle', N'Micronaut provides a declarative @Retryable annotation that automatically handles transient failures for annotated methods. It allows for configurable backoff strategies and jitter, which prevents overwhelming downstream services during recovery periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f9dbe42-e5a7-481a-a278-955880329eac', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s configuration file impact the build process in a micro-frontend architecture?', N'Senior', N'In micro-frontends, sharing a global Tailwind configuration is critical to ensure design system consistency. If individual micro-apps maintain separate configs, it can lead to inconsistent design tokens and increased total bundle size due to redundant CSS generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1eda437-766d-4bb5-9f37-9558c3df3b29', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the trade-offs of Svelte''s ''compile-time'' approach compared to ''runtime'' frameworks?', N'Middle', N'The main benefit is significantly smaller bundle sizes and faster initial load times since the framework runtime is largely eliminated. A potential trade-off is the increased reliance on the build step, which makes dynamic runtime features like runtime component generation more complex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25f3ad44-f531-46fa-9ce5-955bc58a5ffb', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the primary advantage of using synthetic monitoring?', N'Middle', N'Synthetic monitoring uses automated scripts to simulate user behavior from various locations. Its primary advantage is that it monitors the system even when there is no real traffic, allowing you to detect issues before users encounter them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'697d2117-df74-42d3-8f78-955cef77c0d3', N'a2838158-7305-480a-b22b-4dc35776b400', N'Describe the concept of ''backpressure'' in a stream processing system and why it is critical.', N'Senior', N'Backpressure is a feedback mechanism where a consumer signals to the producer that it is unable to keep up with the incoming data rate. Without it, buffers overflow, leading to data loss, system instability, or cascading failures across the pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c4cc846-ea87-4f6a-9f45-955e4b94c26a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the role of the ''DispatcherServlet'' in the Spring MVC request lifecycle.', N'Senior', N'The DispatcherServlet acts as the Front Controller, centralizing request handling by delegating to specific handlers, interceptors, and view resolvers. It manages the entire workflow of mapping a request to a controller method, invoking the method, and rendering the final output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e59cd85-b8cd-4e19-b015-955f47f2d6be', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''onCleanup'' helper function?', N'Junior', N'onCleanup is a function that registers a callback to run when the current reactive scope is disposed. It is essential for cleaning up subscriptions, timers, or event listeners to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56c56b82-c638-4de3-85a3-955faa6b6136', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle database connection pooling and transaction management effectively?', N'Senior', N'Micronaut integrates with connection pool libraries like HikariCP and provides a declarative transaction management system using the @Transactional annotation. It uses AOP to ensure that database transactions are scoped correctly to the method execution, managing commit and rollback operations without requiring manual resource handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53db0f5c-04df-43b7-bff6-9560b7930e8e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do you check the data type of an object in R?', N'Junior', N'The ''class'' or ''typeof'' functions are used to determine the data type or structure of an object. These functions help developers verify that data is in the expected format before performing operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f0bd7e9-82ea-4857-a986-95623e650fbf', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you factor ''context switching'' into your team''s overall capacity estimation?', N'Middle', N'I reduce the available capacity for planned work based on the team''s typical involvement in production support or meetings. By acknowledging that developers are rarely 100% focused on a single feature, I create more achievable sprint plans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'776cdb90-591b-482a-acd3-9564b50cff16', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the ''Backends for Frontends'' (BFF) pattern, and why is it used?', N'Senior', N'BFF involves creating dedicated API layers for specific client types, such as mobile or web, to provide data optimized for their specific requirements. This reduces the amount of unnecessary data transferred and simplifies client-side logic by offloading orchestration to the backend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'394c693c-0777-432d-89da-9564c06b4962', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do ''Modules'' in JavaScript improve the architectural integrity of an application?', N'Senior', N'Modules enforce strict encapsulation by providing their own top-level scope and explicit export/import interfaces. This prevents namespace pollution and allows for better static analysis, tree-shaking, and dependency management during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'912d32a1-9a99-4ff8-a16e-9566a54abab4', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is ''Force Merge'' and under what circumstances should it be used?', N'Senior', N'Force merge is an administrative action to reduce an index to a specific number of segments, typically one. It is best used for read-only indices because it optimizes search performance but is very resource-intensive and counterproductive for indices that are still receiving writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7bcf7e2-10aa-4b4b-bf24-956808cdc802', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Does AdonisJS support TypeScript?', N'Fresher', N'Yes, AdonisJS is built from the ground up with TypeScript support. This provides developers with better autocompletion, type safety, and early detection of bugs during the development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9bd5e1c-143a-4820-be98-9569fb6b3224', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask configuration file?', N'Intern', N'A configuration file is used to store settings for the application, such as debug modes, database URIs, or secret keys. Keeping settings in a separate file keeps the application code clean and secure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60b270e9-f9a4-4fe0-bd6f-956bb82e53ed', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are Case Classes?', N'Intern', N'Case classes are special classes that are optimized for use in pattern matching and immutable data modeling. They automatically generate useful methods like equality checks, string representations, and copy constructors, making them ideal for representing data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'981a0f14-1048-4890-9a40-956ce28f2cce', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'You discover a bug in production that only happens for a small subset of users. What is your systematic approach to troubleshooting this issue without having a direct way to reproduce it locally?', N'Junior', N'I would start by gathering logs and metadata from the affected users to identify common patterns, such as browser type, geographic location, or specific user account configurations. Once a pattern is identified, I would isolate the variables by attempting to replicate the environment in a staging area using that specific configuration. If direct reproduction remains difficult, I would implement additional telemetry or targeted logging to capture the state of the application at the exact moment the error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0319263-9ad3-4cfc-94bf-956d004919b3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where your initial estimate for a task turns out to be significantly off?', N'Middle', N'I communicate the discrepancy as early as possible with the relevant stakeholders, explaining the technical reasons for the delay. I then offer a revised timeline based on the new information and propose potential scope adjustments to bring the project back on track.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7203089d-7990-42e8-a2c2-956d27d9ec27', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between let and var?', N'Intern', N'The let keyword is used for immutable values that cannot change once assigned. The var keyword is used for mutable values that can be reassigned to a different value later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9450f1ec-fc00-42d0-a5be-956d2b6c5d01', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Request and a Response in Laravel?', N'Fresher', N'A Request object represents the data sent by the client to the server, such as form inputs or headers. A Response object is the data sent back from the server to the client, which can be an HTML view, a JSON string, or a redirect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3647a72f-35d9-473c-823a-956dbde557b8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a Controller in Litestar?', N'Intern', N'A Controller is a class used to organize related route handlers together. It provides a way to group endpoints under a common path prefix or apply shared middleware to a specific set of routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4456e421-865b-4e43-ad39-957045b11269', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Cluster in Cassandra?', N'Intern', N'A cluster is the collection of all nodes that work together to store and manage data. Nodes in a cluster communicate via the gossip protocol to manage state and membership.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8761261f-1167-479e-ab59-9570618a29c6', N'954a0331-deff-4399-b588-96f39fec001d', N'What happens if browserModule used in feature module?', N'Junior', N'If you do import BrowserModule into a lazy loaded feature module, Angular returns an error telling you to use CommonModule instead. Because BrowserModule’s providers are for the entire app so it should only be in the root module, not in feature module. Whereas Feature modules only need the common directives in CommonModule. !ScreenShot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a13d036-f45f-4c3c-b8b4-9572347de886', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'When should you prefer a mixin over a placeholder selector?', N'Middle', N'Mixins should be used when you need to pass arguments to customize the output, such as colors or dimensions. Placeholder selectors are better suited for static sets of properties that need to be shared across unrelated selectors without adding extra bulk to the CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c525e211-cea0-40f3-aa09-9576848cb424', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik compatible with standard HTML and CSS?', N'Intern', N'Yes, Qwik is fully compatible with standard HTML and CSS. It focuses on how JavaScript is loaded and executed, but it does not change the fundamental way that web pages are structured or styled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34959292-626e-4cd2-8231-95772c648c1d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is it important to keep the ''Working Set'' within physical memory?', N'Senior', N'The working set represents the subset of data and indexes that the application frequently accesses. If this set exceeds available physical memory, the system must swap data from disk, which is orders of magnitude slower than memory access, causing significant latency spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fadf9b37-4c06-4947-82b4-9578ade0fdb8', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass mixins work and when should you use them?', N'Fresher', N'Mixins allow you to define reusable blocks of styles that can be included throughout your stylesheet. You should use them when you need to share a set of CSS declarations across multiple elements, as they help avoid code duplication and simplify the process of updating shared styles in one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d749f2d-8e2e-4570-83d9-9578bb15629d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the ''FLUSHALL'' command?', N'Fresher', N'The FLUSHALL command removes all existing keys from all databases on the Redis server. It is a dangerous operation that should be used with extreme caution, usually only in development or testing environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0bc9f48-b46b-4c6b-8670-95795276d9c2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is collaboration often more effective than working alone on a difficult bug?', N'Intern', N'Collaboration brings different perspectives and experiences to the problem, helping to identify biases or blind spots. A second pair of eyes can often notice patterns or details that the original investigator might have overlooked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8062e402-f81e-4635-9786-957cc2f86b52', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is an Environment in Symfony and why is it used?', N'Intern', N'An environment represents a specific configuration setup for an application, such as ''dev'', ''prod'', or ''test''. It allows developers to use different settings, like enabling detailed debugging in development while keeping the application secure and optimized for performance in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bae1cbc-944d-46dd-b686-957d5b319ca8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the significance of the render function in Preact?', N'Intern', N'The render function is the entry point that takes a virtual component tree and mounts it to a real DOM node in the browser. It is responsible for turning the component structure into visible HTML elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b717243-c111-43e7-ac6f-957e0b7f3c4c', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain why ''Graceful Degradation'' is a good design practice.', N'Middle', N'Graceful degradation ensures that if a system component fails, the application continues to provide a reduced but functional service rather than crashing completely. This improves user experience by prioritizing core features during partial system outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3577d85-046c-492c-b911-957e3438b9a5', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are environment variables in ASP.NET Core?', N'Intern', N'Environment variables are key-value pairs used to configure the application environment, such as ''Development'', ''Staging'', or ''Production''. ASP.NET Core uses these settings to determine which configuration files to load and how to handle errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b224273-aaf8-450d-b692-9580af01b359', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of the ''Ctx'' object in Fiber?', N'Junior', N'The Ctx object, or Context, represents the request and response lifecycle. It provides methods to read request data, set headers, write response bodies, and manage the flow of the middleware chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f336782-288d-4059-a3e9-958280b56138', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the advantage of using Micronaut''s ''Client'' interfaces over standard HTTP clients?', N'Senior', N'By using declarative interfaces, Micronaut generates the HTTP client implementation at compile-time. This eliminates the need for boilerplate code to handle connection pooling, request serialization, and error handling, while also providing type-safe interaction with remote APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef29bc80-3360-4196-a1eb-95877ab6e02e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are higher order components in React?', N'Intern', N'Higher order components (HOCs) in React are functions that take a component and return a new component with additional props or behavior. They are used to reuse component logic. For example, if you have a component MyComponent, you can create an HOC like this: HOCs are largely a legacy pattern. The current React docs (React 19) discourage HOCs in favor of custom hooks for sharing logic between function components. You''ll still see HOCs in older code and in libraries (e.g. connect from React Redux), but for new code, prefer hooks. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb9cf2f-c3bf-4287-92e2-9587c920d21b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the trade-offs of using Sparse Indexes in DynamoDB?', N'Senior', N'Sparse indexes only contain items that have the index''s key attributes defined. They are useful for querying a subset of data efficiently, but they require careful application logic to ensure data is correctly included in the index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bf7d5f0-074d-4a07-88a7-95884a6e79dd', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is Critical Rendering Path?', N'Intern', N'The Critical Rendering Path (CRP) is the sequence of steps the browser takes to convert HTML, CSS, and JavaScript into pixels on the screen. The 6 steps in order: 1. Constructing the DOM Tree — Browser parses HTML and builds the Document Object Model (tree of nodes) 2. Constructing the CSSOM Tree — Browser parses CSS and builds the CSS Object Model (style rules tree) 3. Running JavaScript — JS is a parser-blocking resource; the browser stops HTML parsing to execute it (unless async/defer is used) 4. Creating the Render Tree — DOM + CSSOM are combined; only visible elements are included (e.g., display:none nodes are excluded) 5. Generating the Layout — Browser calculates the exact size and position of each element on the screen (also called "reflow") 6.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8110c56-7ddd-4236-bf03-958c3885ba26', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of res.json()?', N'Junior', N'The res.json() method sends a JSON response. It automatically sets the Content-Type header to application/json and converts the provided object or array into a JSON string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95c34998-1b58-41ea-83f3-958db2da1228', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between an optional parameter and a required parameter?', N'Intern', N'A required parameter must be provided every time a function is called, or the code will not compile. An optional parameter can be omitted, in which case it will either be assigned a default value or treated as null.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce59d330-2e27-4263-ab18-9591538fe410', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a class method and an instance method?', N'Junior', N'An instance method belongs to a specific instance of a type and operates on that instance''s properties. A class method (or static method) belongs to the type itself and can be called without creating an instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06760497-0885-4371-a222-9599b5ddedad', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart manage memory, and does it provide manual memory management?', N'Middle', N'Dart uses a generational garbage collector to manage memory automatically. It does not provide manual memory management, as this would conflict with the safety guarantees required for a high-level, productivity-focused language and would complicate the isolate-based architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e72b1470-9bd0-4314-b1c1-959af318688f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is the order of union types significant in some TypeScript inference scenarios?', N'Senior', N'While union types are generally unordered sets, the order can influence the compiler''s preference for type narrowing and the order of candidate type resolutions. Understanding this behavior is necessary when writing complex generic utility types where specific narrowings are expected to take precedence over broader ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bc7e066-b0b5-451d-8944-959e453a4510', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux middleware like Redux-Saga or Redux-Observable handle asynchronous side effects differently than Redux-Thunk?', N'Senior', N'Redux-Thunk treats async actions as simple function calls, which can lead to complex nested callbacks or logic bloat inside action creators. Sagas and Observables utilize generators or streams to treat side effects as first-class citizens, allowing for advanced control flow like cancellation, debouncing, and race condition management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7c9325b-d858-44e6-8100-95a3c6dd8627', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the Preact DevTools extension help developers?', N'Junior', N'The Preact DevTools extension allows you to inspect the component tree, view current state and props, and debug performance issues. It provides a visual representation of your application''s structure in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13b7d5fc-3ab5-4a05-92b6-95a646ff41e3', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What does ''unidirectional data flow'' mean in Preact?', N'Intern', N'Unidirectional data flow means that data typically flows in one direction, from parent components down to child components via props. This makes it easier to track how data changes affect the UI throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92416fb2-1d7b-4b59-a9f9-95a6e85eb0b5', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is partitioning, and how does it differ from sharding?', N'Middle', N'Partitioning is the process of splitting a logical database table into smaller physical pieces, typically within a single instance. Sharding is a form of partitioning that distributes these pieces across multiple distinct physical servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'588e3cf4-b0ed-437d-bd0f-95a8d63ffe8a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to handle exceptions in your application logic?', N'Fresher', N'Exception handling ensures that when an unexpected error occurs, the application fails gracefully instead of crashing entirely. It allows the system to log the error for debugging purposes and provides a meaningful message to the user. Without it, the application state could become corrupted or leave the user with an unresponsive screen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3539d423-b4f3-4f99-a55b-95aa120dbfd4', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the value of using Sass to manage media query breakpoints?', N'Senior', N'Sass provides a centralized location to manage breakpoints as map variables, ensuring that media queries remain consistent across the entire application. By using a mixin to wrap these values, you can create a standard syntax that makes responsive code easier to read and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
