INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45250689-5cec-4ef9-ab25-95ad7e7d685c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of automated testing in a continuous integration pipeline?', N'Junior', N'Automated testing catches bugs early in the development lifecycle before they reach production. It provides confidence that new changes do not break existing functionality, allowing for faster and more frequent deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7967c168-60b6-466b-9c32-95b1dcebb388', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s routing algorithm handle path ambiguity?', N'Senior', N'Rocket uses a deterministic ranking system based on the specificity of the route''s segments, including static strings, dynamic parameters, and segments. It resolves ambiguity by selecting the ''most specific'' match, preventing overlapping route conflicts at compile-time rather than runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c81c48ec-3cef-45cb-a2f8-95b27c6a26b1', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a Request and a Response object in Symfony?', N'Intern', N'A Request object represents the data sent by the client, such as URL parameters and form inputs. A Response object represents the data the application sends back to the client, such as HTML content or JSON data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f60bae59-dd95-443a-b661-95b418cc0b14', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the list of cases error thrown from non-strict mode to strict mode', N'Intern', N'When you apply ''use strict''; syntax, some of the below cases will throw a SyntaxError before executing the script 1. When you use Octal syntax 2. Using with statement 3. When you use delete operator on a variable name 4. Using eval or arguments as variable or function argument name 5. When you use newly reserved keywords 6. When you declare a function in a block and access it from outside of the block Hence, the errors from above cases are helpful to avoid errors in development/production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77ce512c-268c-4811-85e7-95b5cd62384c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the benefit of using the ''readonly'' modifier on fields?', N'Middle', N'The readonly modifier ensures that a field can only be assigned a value during declaration or within the constructor of the class. This promotes immutability, which reduces the likelihood of side effects and makes code easier to reason about in multi-threaded environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'398a254c-6d82-4cb7-aba6-95b65fff672e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the risk of using a cache as a primary data store?', N'Middle', N'Caches are generally designed for performance and not for persistence or high durability. If the cache layer is used as the primary store and it crashes, the data will be lost, potentially causing permanent system failure if no backup data exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebea99f7-edfd-48a9-8a92-95b756af9952', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the ''if'' block in Svelte?', N'Junior', N'The if block is used for conditional rendering in the template. It allows you to show or hide specific parts of the DOM based on whether a given expression evaluates to true or false.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10138c5a-75d9-422d-a478-95b8c941f1a0', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart handle private members?', N'Intern', N'Dart does not have explicit keywords like ''private'' or ''public''. Instead, it uses an underscore prefix for names; any class, method, or variable starting with an underscore is private to the library it is defined in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6ed50f3-32b3-430c-afee-95bb169b9483', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are Coroutines and why are they preferred over standard threads for asynchronous programming?', N'Middle', N'Coroutines are lightweight abstractions that allow for asynchronous, non-blocking code execution. They are preferred over threads because they are much cheaper to create and manage, allowing thousands of coroutines to run on a small number of threads without the overhead of context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a79c4720-0f64-44a4-bddd-95bd90e113a9', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the trade-offs of using eventual consistency versus strong consistency in a distributed NoSQL system.', N'Senior', N'Eventual consistency maximizes availability and low latency by allowing nodes to diverge temporarily, which is ideal for high-write-throughput systems. Strong consistency ensures linearizability but requires synchronous coordination across nodes, significantly increasing latency and reducing availability during network partitions as dictated by the CAP theorem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51fbba8a-b474-46b6-b511-95beeb823009', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the ''Router::merge'' function?', N'Fresher', N'The merge function allows you to combine multiple routers into a single larger router. This is useful for organizing code into smaller, manageable modules based on functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e9a9eca-9dae-4847-9e3b-95c00793cfdc', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL implement ''Serializable'' isolation, and what is the cost of using it?', N'Senior', N'PostgreSQL implements Serializable isolation using Serializable Snapshot Isolation (SSI), which tracks read and write dependencies between transactions to detect serialization anomalies. This provides the highest level of isolation but can cause transaction failures that require application-level retry logic when conflicts are detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2697c1df-9034-4738-9f09-95c1f3dab6bb', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are property observers, and how do they differ from computed properties?', N'Middle', N'Property observers like willSet and didSet monitor changes to a property''s value and trigger code execution accordingly. Computed properties do not store values themselves but provide a getter and an optional setter to calculate values on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fcf76a-aab9-4931-9e18-95ca2f1abdd5', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle data binding between templates and components?', N'Junior', N'Ember uses a one-way data flow where data is passed into components via arguments. If a component needs to change that data, it sends an action back up to the parent component or controller, ensuring that the data flow remains predictable and easy to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90b782f2-d331-44de-aa80-95cc6c031a26', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What happens during the Astro build process?', N'Junior', N'During the build, Astro runs the JavaScript in your Frontmatter, processes your components and styles, and generates a static website. The final output is a collection of optimized HTML, CSS, and JavaScript files ready for deployment to any web host.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f68df7-e7b2-4e3f-afb9-95d1581923b7', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the ''Service'' trait in Actix?', N'Fresher', N'The Service trait is the fundamental abstraction for processing requests and returning responses. It defines the contract that all handlers and middleware must follow within the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c249090d-fcd4-4f89-9135-95d26fea7cb5', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the significance of the Angular ''forRoot'' and ''forChild'' pattern?', N'Middle', N'This pattern ensures that singleton services are only instantiated once in the root module while allowing feature modules to register additional providers or routes. It prevents issues where multiple instances of the same service are created in different modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5acd40eb-c137-4474-ac02-95d656686538', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why should developers be cautious about using jQuery for complex form validation?', N'Middle', N'Relying on client-side plugins for validation can create a false sense of security, as users can easily bypass or disable client-side checks. Robust validation should always occur on the server, and modern frameworks often provide better reactive tools for real-time UI validation than jQuery plugins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ec6d50e-a65c-4600-8d51-95d8f515c3ed', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Event Listeners and Subscribers?', N'Fresher', N'They are mechanisms that allow you to hook into the application''s lifecycle and execute custom code when specific events occur. For example, you can listen for an event that triggers every time a new user registers to send them a welcome email.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b955b0ed-ee26-40c7-a57c-95d986a4bd10', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you handle environment variable scoping to prevent accidental leakage to the client-side?', N'Senior', N'Nuxt enforces strict scoping via ''runtimeConfig'' and ''app.config''. Variables intended for the server must remain in the server-side runtime config, while only explicitly exposed variables should be placed in the public runtime config to prevent sensitive API keys from being bundled into the client-side JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c3da161-ece0-408d-a999-95d98bdc8024', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the architectural trade-offs of Axum''s ''State'' pattern regarding performance and thread safety.', N'Senior', N'Axum uses a shared application state that must be wrapped in thread-safe containers like Arc if mutable access is required. While this introduces overhead from synchronization primitives, it ensures memory safety and allows the state to be efficiently shared across all asynchronous worker threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8befb77-ed81-4523-b1a0-95d9e6831e70', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are smart casts?', N'Intern', N'Smart casts are a feature where the compiler automatically casts a variable to a specific type after a type check is performed. Once the compiler confirms the type of the variable, you can access its members without explicit casting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1de16f8-49e3-48d5-8ea9-95d9ea4e19cf', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the ''req'' object in Express?', N'Intern', N'The ''req'' object represents the HTTP request and has properties for the request query string, parameters, body, HTTP headers, and more. It allows developers to access data sent by the client to the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'daa8caa6-9de9-4f3b-969f-95dc74f987d3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the main advantage of using slots over dictionaries for instance attributes?', N'Middle', N'The primary advantage is a significant reduction in memory usage because slots prevent the creation of a per-instance dictionary. This is particularly beneficial when a program needs to create millions of instances of a specific class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73f6b3f1-5198-4ac0-97ff-95dd7559e377', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the definition of a ''lazy'' QuerySet?', N'Intern', N'A lazy QuerySet means that the database query is not executed until you iterate over the result or convert it to a list. This optimization helps performance by ensuring that complex queries are only run at the exact moment the data is needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35dc1822-e423-43fc-bdfb-95e2d719738e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is PHP primarily designed for in web development?', N'Intern', N'PHP is a server-side scripting language designed specifically for web development. It allows developers to create dynamic web content that interacts with databases and performs server-side processing before the page is sent to the client''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b850b446-81da-4191-a1a5-95e4e30de502', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the trade-offs of using ''unit testing'' in R packages.', N'Middle', N'Unit testing provides a safety net that ensures code behaves as expected and prevents regressions when changes are introduced. While it requires time to write and maintain tests, the benefit is significantly higher code quality and easier debugging in large-scale collaborative projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e59f25a3-cb5a-4edf-871b-95e817e765f4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How can you mitigate the risk of performance bottlenecks in large-scale Lit applications?', N'Senior', N'Bottlenecks are mitigated by leveraging code splitting, lazy-loading components, and minimizing the complexity of templates. Using ''memoization'' techniques within templates and ensuring that reactive updates are as granular as possible are also essential for maintaining 60fps performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99f1033e-8c5f-4ee1-a353-95e9ee6694a1', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between client-side and server-side processing?', N'Intern', N'Client-side processing occurs in the user''s web browser using languages like JavaScript, allowing for interactive user interfaces. Server-side processing occurs on the web server using PHP, allowing for secure data handling, database interaction, and business logic execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2f23f49-f6bc-4187-80a3-95ecaee55359', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle concurrent requests despite being single-threaded?', N'Middle', N'Express runs on the Node.js event loop, which handles I/O operations asynchronously. While the main thread processes the request logic, I/O tasks are offloaded to the system kernel or thread pool, allowing the server to handle multiple requests without blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db689515-4297-444a-bbe8-95ed7ac1c02d', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does ''zero allocation'' mean in Fiber?', N'Fresher', N'Zero allocation refers to the optimization where the framework minimizes the creation of new objects in memory during request processing. This reduces garbage collection pressure and significantly improves the performance and speed of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'967f2122-3b56-4f21-8233-95edb29b40c4', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between ''require'' and ''import'' in Node.js?', N'Intern', N'Require is part of the CommonJS module system, which is the traditional way to load modules in Node.js. Import is part of the newer ES Modules standard, which is now supported by Node.js for modern project structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'339faddd-0f09-41ca-8f42-95f4cf67ad42', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the memory overhead associated with Ruby''s ''copy-on-write'' (COW) friendliness in multi-process environments.', N'Senior', N'Ruby''s COW friendliness allows child processes to share the memory pages of the parent process, only creating copies when data is modified. However, Ruby''s GC often modifies objects during its marking phase, which can trigger COW and cause memory bloat; optimizing this requires tuning GC settings to minimize heap modifications after forking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'578cdf1a-3129-4af7-810e-95f69945bfa3', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''List'' and ''MutableList''?', N'Fresher', N'A ''List'' in Kotlin is read-only, meaning its elements cannot be modified after creation. A ''MutableList'' provides additional methods to add, remove, or update elements within the collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ff8d284-2bee-4792-9e68-95fac8858a31', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why should you use ''HTTPException'' instead of raising standard exceptions?', N'Junior', N'HTTPException is a special exception that FastAPI knows how to catch and convert into a standard HTTP error response. Using it ensures the client receives a properly formatted JSON response with the correct status code rather than a generic server error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45a225ec-7136-4229-b45c-95fc03c31f40', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database migrations, and why are they safer than manual SQL?', N'Middle', N'Django migrations track changes to your model definitions and apply them to the database schema automatically. They provide a version-controlled, repeatable way to update the database state, reducing the risk of human error compared to writing and executing raw SQL scripts manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd385e12-70fd-40c7-8562-95fc839616b0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you handle long-running processes in Symfony without causing memory leaks?', N'Senior', N'Memory leaks in long-running processes are typically caused by objects accumulating in the Identity Map or static caches. Strategies to mitigate this include manually clearing the Doctrine EntityManager, resetting services after each task, and using process managers that restart workers after a defined number of requests or memory threshold.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3e2c91c-6430-416e-ad7c-95ff29310be0', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does partitioning in a distributed message bus affect the ordering guarantees of messages?', N'Senior', N'Partitioning allows for horizontal scalability by distributing data across multiple nodes. Ordering is only guaranteed within a single partition, meaning if a producer sends related messages to different partitions, the global order is lost and consumers must handle reassembly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cb00aac-cb51-4b04-a670-95ff56a0ea17', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the primary paradigm shift when moving from Java to Scala?', N'Fresher', N'Scala is a multi-paradigm language that seamlessly integrates object-oriented and functional programming. Unlike Java, which is primarily object-oriented, Scala encourages the use of immutable data structures and first-class functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
