INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bb79c3d-7edf-44ea-a4f9-9601160e03bd', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the function of the ''ExecutionContext'' in asynchronous operations.', N'Senior', N'ExecutionContext captures information like SecurityContext, LogicalCallContext, and synchronization data to flow it across asynchronous boundaries. This ensures that environmental settings remain consistent when a task continues on a different thread, although capturing it carries a minor performance cost for every context switch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9e91b2d-3e2c-408a-b9d0-960175f93551', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a namespace in TypeScript, and is it still recommended?', N'Middle', N'Namespaces were originally designed to organize code and prevent global scope pollution in early JavaScript. In modern TypeScript projects, they are largely superseded by ES Modules, which provide a standard and more efficient way to handle code bundling and dependency management. Namespaces are now mostly used for legacy codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
