INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60fd1b0-2a02-4d0b-83ea-960f033db02f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system is throwing frequent ''Connection Timeout'' errors, how do you determine if the issue is in the client, the network, or the server?', N'Middle', N'I would verify the server-side metrics to see if requests are even reaching the application, then check network-level metrics like packet loss or latency between the nodes. If the server is unresponsive, I would inspect the thread pool and request queues; if the client is timing out before sending data, the issue likely resides in the client or the local network path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ab03ba2-1e9f-408e-ac81-9611e9d820b2', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the main difference between ''hot reload'' and ''hot restart''?', N'Junior', N'Hot reload injects updated source code into the running Dart Virtual Machine, preserving the current state of the application. Hot restart destroys the current app state and restarts the application from the beginning to apply larger code changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
