INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd87f9042-d804-40df-b9b3-96148840f962', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the architectural advantages of using Litestar''s ''Provide'' pattern over middleware for cross-cutting concerns.', N'Senior', N'The ''Provide'' pattern allows for injectable dependencies that are only instantiated when requested by a handler, reducing overhead for routes that do not require specific services. Middleware, by contrast, executes for every request regardless of the specific route requirements, making the ''Provide'' pattern more efficient for resource-heavy operations like database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5469966-59b4-411b-a0d4-9615ed12f2c2', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus differ from traditional Java frameworks like Spring Boot?', N'Fresher', N'Traditional frameworks perform most of their initialization at runtime, which consumes significant memory and time. Quarkus performs this initialization during the build phase, resulting in faster startup and lower memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e053697-6147-48cd-b73c-96199619b985', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Model and a Controller?', N'Intern', N'The Model represents the data and business rules of the application, typically interacting directly with the database. The Controller processes the user''s input, interacts with the Model to retrieve or update data, and then decides which view to return to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f0115f-95dd-4991-a669-9619ca2c0373', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the difference between strong consistency and eventual consistency?', N'Junior', N'Strong consistency guarantees that every read receives the most recent write, while eventual consistency allows a delay where reads might return older data before the system synchronizes. Strong consistency prioritizes data accuracy, while eventual consistency prioritizes system uptime and responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b73c984-9ed0-4781-b02d-961ede9c8927', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When integrating a third-party service, how do you protect your system from potential instability of that service?', N'Middle', N'I wrap the integration in an adapter or facade to decouple it from my core logic. I also enforce strict timeouts and circuit breakers, and I ensure that the system can still function in a degraded state if the third-party provider experiences downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fcc2aed-1838-4445-bbad-96240ee2fae1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the difference between ''Guards'' and ''Interceptors'' in terms of authorization and authentication workflows.', N'Senior', N'Guards are strictly for authorization, returning a boolean to determine if a request should proceed to the next stage of the pipeline. Interceptors are more versatile, allowing for the inspection or manipulation of the response, making them suitable for logging, response transformation, or caching, but they should not be used to enforce access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20b7425a-c1bf-4154-b9de-962414fa4cb3', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it important to use strong parameters in Rails controllers?', N'Middle', N'Strong parameters prevent mass assignment vulnerabilities by requiring developers to explicitly whitelist which attributes can be updated via external input. This ensures that a malicious user cannot modify sensitive fields, such as administrative flags or user IDs, during a form submission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4024cdf3-63cd-498b-b944-96270f9438a9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Mapped Types and how do they improve maintainability?', N'Middle', N'Mapped types allow you to create new types by iterating over the properties of an existing type, such as making all properties optional or readonly in one go. They improve maintainability by ensuring that changes to a base model are automatically propagated to derived types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a5cdd3-fe12-49dc-9851-962839eb765a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''Responder'' trait?', N'Intern', N'The Responder trait defines how a type can be converted into an HTTP response. Any type that implements this trait can be returned from an Actix handler function to be sent back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a07cc5a-573c-42f9-8b49-962879dbe621', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS minimize DOM mutations?', N'Senior', N'SolidJS compiles components into DOM creation and update functions. By using fine-grained bindings, it updates only the attribute or text content of a DOM node directly, rather than touching the DOM structure unless absolutely necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cde7009-2ad3-465d-af11-962935a71aba', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a vector in R?', N'Intern', N'A vector is the most basic data structure in R, used to store a sequence of elements of the same data type. These elements can be numbers, characters, or logical values, and they are indexed starting from one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03d605a2-266a-487e-8d60-962bc2196508', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What steps do you take when you are asked to estimate a project with vague requirements?', N'Junior', N'I would list the assumptions I am making based on the current information and ask clarifying questions to narrow down the scope. If the requirements remain too vague, I would suggest a research phase to define the needs before providing a formal estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa3a5456-40ff-4bc3-8d36-962c68421b92', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is the lack of a built-in ''ORM'' or ''Database'' abstraction considered an architectural strength in Fastify?', N'Senior', N'It avoids ''leaky abstractions'' and allows developers to choose the best-in-class driver for their specific database needs. This ensures that the application remains performant and isn''t tied to the limitations or overhead of a one-size-fits-all framework-level database tool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'506eed8c-e66a-4a08-b53e-962c9cfe5f0b', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you effectively manage memory leaks in long-running Angular applications, especially when dealing with RxJS subscriptions?', N'Senior', N'Memory leaks often occur from hanging subscriptions that are not unsubscribed when a component is destroyed. Developers should utilize the ''takeUntilDestroyed'' operator, the async pipe for automatic template cleanup, or explicit unsubscribe logic in the ngOnDestroy lifecycle hook to ensure all observable streams are properly terminated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c169d9fa-1f39-4f56-b895-962f19e5b7a9', N'4c000000-0000-0000-0000-000000000005', N'Contrast horizontal scaling versus vertical scaling in terms of architectural limitations.', N'Senior', N'Vertical scaling is limited by the physical hardware capacity and cost, eventually hitting a ceiling for performance. Horizontal scaling is theoretically infinite but introduces significant complexity regarding state management, network overhead, and consistency across distributed nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c602d03b-5e4f-4547-a6ba-963153dd8cf2', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix achieve faster page transitions compared to traditional multi-page apps?', N'Junior', N'Remix uses nested routing and intelligent prefetching to load only the specific data needed for the next page. This avoids full browser reloads and minimizes the amount of data transferred over the network.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3033eb4c-38f1-473e-85c2-9631bd84c2de', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does the CORS middleware do in Echo?', N'Intern', N'The CORS middleware manages Cross-Origin Resource Sharing settings for your application. It allows you to specify which domains are permitted to access your API and which HTTP methods are allowed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5d64908-8835-4442-b68b-9633eccf15b2', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How can you implement fine-grained rate limiting in Echo without impacting global performance?', N'Senior', N'Implement rate limiting as a middleware using an atomic counter or a sliding window algorithm backed by an in-memory store like Redis. By using a distributed store, you maintain consistency across multiple service instances while keeping the logic decoupled from the core business handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e39f5d3a-f824-438c-8d06-96367a05a5dd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the best way to organize a large Hono application?', N'Middle', N'For large applications, you should use the ''Hono'' instance composition features, such as mounting sub-apps or using routers to group related routes. This promotes modularity and keeps individual files focused on specific domain logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a25011d-f7ca-4794-9606-9638277f33e1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the function of a ''Rollback'' operation?', N'Fresher', N'A rollback is used to undo the changes made during a transaction if an error occurs before the commit. It reverts the database to the state it was in before the transaction began, ensuring no partial or invalid data is saved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79c7f6d3-0816-4889-b312-963c6a2b8096', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What strategies would you use to manage schema evolution in a microservices environment?', N'Senior', N'You should enforce backward compatibility by never renaming or deleting fields and always providing default values for new ones. Using contract-driven development with tools like Pact ensures that consumers and providers remain aligned even when independent deployments occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e4b56e9-004f-4eac-b9d9-963dc728afde', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you customize model directive for a component?', N'Fresher', N'The v-model directive on a component uses value as the prop and input as the event, but some input types such as checkboxes and radio buttons may need to use the value attribute for a server side value. In this case, it is preferred to customize model directive. Let''s take an example of checkbox component, Now you can use v-model on this customized component as below, The selectFramework property will be passed to the checked prop and same property will be updated when custom checkbox component emits a change event with a new value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fd2c30b-e027-458a-aff8-96435e1d1444', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the role of the ''app'' directory in modern Next.js.', N'Fresher', N'The app directory is the modern file-system-based router in Next.js. It allows developers to define routes, layouts, and data fetching methods using a nested folder structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd160a113-7788-46e9-86c1-9645399fadf6', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why are global variables generally discouraged in PHP applications?', N'Middle', N'Global variables create hidden dependencies between unrelated parts of an application, making the code unpredictable and difficult to debug. They also pose significant security risks by allowing any part of the application to accidentally overwrite sensitive state data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1569040-348b-49ab-bca1-96494d4a93d1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift forbid inheritance from multiple classes but allow conformance to multiple protocols?', N'Middle', N'Multiple inheritance creates complex issues like the diamond problem, where it is ambiguous which implementation of a method to use. Protocols do not store state, so there is no conflict; they simply define a contract, making multiple conformance a safe way to add functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'007b5f76-fa7b-4595-84f4-96495792a39c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why might you use ''DllPlugin'' in a large Webpack project?', N'Senior', N'DllPlugin is used to pre-compile rarely changing dependencies, such as frameworks or large libraries, into a separate bundle. This prevents these dependencies from being re-processed during every build, which significantly reduces the time required for incremental builds during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'824cf10d-f790-4c08-bc44-964a4cc9efa1', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What happens if you don''t call the ''next()'' function in Echo middleware?', N'Middle', N'If you fail to call the next function in the chain, the request lifecycle is terminated, and subsequent middleware or the final route handler will never be executed. This is useful for short-circuiting requests, such as when an authentication middleware detects an invalid token.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6c84bde-5d5c-4f74-9d97-964a9c5096e4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the implications of using CSS variables (custom properties) versus preprocessor variables like SASS?', N'Senior', N'CSS variables are resolved at runtime and can be manipulated via JavaScript, enabling theme switching without full re-compilation. Preprocessor variables are resolved at build-time, meaning they are immutable in the browser but offer better compatibility and more advanced logic during the development phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f256e18-b663-4643-ad32-964bd5b39edb', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you measure the effectiveness of a caching strategy?', N'Middle', N'Effectiveness is primarily measured through the Cache Hit Ratio, which is the percentage of requests served by the cache versus the total requests. Secondary metrics include latency improvements and the reduction in CPU or IOPS load on the backing database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c890ff02-10a2-4587-9db6-96520a4d21e4', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the architectural significance of Litestar''s ''DTO'' layer compared to manual Pydantic model validation?', N'Senior', N'The DTO layer acts as an abstraction between the internal domain models and the external API representation, allowing for decoupled schema evolution. By separating the transport layer from the business logic, you gain granular control over data transformation and partial updates without polluting your core domain entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3ceb1ab-17c9-4efd-bfae-9654b4ab9986', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why might someone prefer Tailwind over writing plain CSS?', N'Intern', N'Tailwind provides a consistent set of design tokens, which helps maintain design uniformity. It also eliminates the cognitive load of coming up with class names for every element and speeds up the development process by keeping styles close to the markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d1c9208-670b-4dc7-8d4a-9656c76b50b6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle CSS files?', N'Intern', N'Webpack does not natively understand CSS files. To use them, you must use loaders like css-loader to interpret the file and style-loader to inject the styles into the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc01fb94-c492-4c57-8a68-965882cf4ea7', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How can you ensure message ordering in a distributed queue that has multiple consumers?', N'Middle', N'To ensure ordering, you must use a single partition or a single consumer thread for the specific sequence of messages. If messages are distributed across multiple partitions or consumers, global ordering is lost, so you must use a key-based partitioning strategy to group related messages into the same partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b224869-b5ae-49b7-8e22-965a5d392c85', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI support CORS (Cross-Origin Resource Sharing)?', N'Fresher', N'FastAPI provides a dedicated CORSMiddleware that can be added to the application to handle requests from different domains. It allows you to specify which origins, methods, and headers are permitted, ensuring secure communication between browsers and the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a80cd770-7db7-43b5-9656-965add157af6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are Property Observers?', N'Fresher', N'Property observers, such as ''willSet'' and ''didSet'', observe and respond to changes in a property''s value. They are called every time a property''s value is set, even if the new value is the same as the current value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f678ff6-05f4-42c7-9d35-965e61fd7e80', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage configuration changes in a distributed system to avoid system-wide outages?', N'Senior', N'Implement dynamic configuration management with centralized versioning and roll-back capabilities. Use canary deployments for configuration updates to monitor the impact on a small subset of the infrastructure before rolling out globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96198c97-1573-4499-81f3-965ec7890dea', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you reason about the potential impact of a new security requirement on an existing project''s timeline?', N'Middle', N'I assess how deep the security requirement penetrates the current stack—whether it is a configuration change or a fundamental architecture modification. I then communicate the impact by explaining that security measures are non-negotiable and prioritize them within the schedule, adjusting less critical deliverables to accommodate the new work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d15637f-9246-430e-91a5-9661cb9634c2', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the role of a Component in Angular?', N'Junior', N'A component controls a patch of screen real estate. It consists of a TypeScript class that handles data and logic, an HTML template that defines the view, and CSS styles that define the appearance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9175f68c-a26e-48bd-9f1b-96637508c7b4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the distinction between R''s lexical scoping and dynamic scoping?', N'Middle', N'R primarily uses lexical scoping, where the search for free variables is determined by the environment where the function was defined. Dynamic scoping, which R does not typically use, would instead search based on the call stack at the time of execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9ea5900-9892-44ef-ad4e-96651e93671d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Does jQuery simplify cross-browser AJAX request headers?', N'Middle', N'Yes, jQuery abstracts the creation of the XMLHttpRequest object and handles header normalization automatically across different browser versions. This saves developers from writing boilerplate code to account for how older browsers handled specific HTTP headers or content types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc813ec7-ac20-4e93-aa56-966730a9d8f8', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary architectural benefit of Tailwind''s utility-first approach regarding CSS bundle size?', N'Senior', N'Tailwind''s approach ensures that the CSS bundle size remains constant regardless of the project''s complexity. Since utilities are reused across the application, adding new components does not proportionally increase the CSS file size, unlike component-level scoped CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99c87b28-88d2-4d72-aa26-9668794b51e9', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js implement data binding and what are the potential pitfalls in complex forms?', N'Senior', N'It uses a two-way binding mechanism via x-model, which synchronizes the DOM element''s value with the underlying proxy state. In complex forms, this can lead to performance degradation if the state object is large and deep, causing unnecessary re-renders of the entire subtree during input events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ff04ad9-38a4-4175-b2c5-9669429911d2', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of using Redis as a cache?', N'Fresher', N'Using Redis as a cache significantly reduces the load on the primary backend database by serving frequently requested data directly from RAM. This improves application response times for users and prevents the primary database from becoming a bottleneck during high traffic periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0362ef3f-afbb-4b40-a4b8-966d6f2b3c89', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the ''parallel query'' feature work in PostgreSQL?', N'Senior', N'PostgreSQL can spawn worker processes to execute parts of a query plan in parallel when the cost exceeds a certain threshold. This is particularly effective for sequential scans, joins, and aggregates on large tables where multiple CPUs can reduce total execution time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31ad849b-2e91-4063-b457-966dfe4deb0c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What happens if a user submits a form while JavaScript is still loading?', N'Junior', N'Remix is designed to be resilient, meaning it uses standard HTML form functionality. If the user submits before the client-side bundle is ready, the browser will perform a full-page submission, which Remix will handle server-side as usual.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4e71828-8b05-48bc-a009-966f76c6c452', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is upsert operation in MongoDB?', N'Intern', N'Upsert operation in MongoDB is utilized to save document into collection. If document matches query criteria then it will perform update operation otherwise it will insert a new document into collection. Upsert operation is useful while importing data from external source which will update existing documents if matched otherwise it will insert new documents into collection. Example: Upsert option set for update This operation first searches for the document if not present then inserts the new document into the database. The car with the name Qualis is checked for existence and if not, a document with car name "Qualis" and speed 50 is inserted into the database. The nUpserted with value "1" indicates a new document is inserted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'995baaf7-8f19-4336-9289-96714ff42bf7', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is it important to use Nuxt''s ''Link'' component instead of a standard HTML anchor tag?', N'Middle', N'The Nuxt Link component enables client-side routing, which prevents full page reloads and maintains the application state. It also provides performance benefits like prefetching linked pages when they enter the viewport, resulting in near-instant navigation for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a623382-10bd-41a1-b1e6-967457cbb747', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Describe the trade-offs of using ''value classes'' versus standard data classes.', N'Senior', N'Value classes provide a way to wrap a single value with zero runtime overhead by inlining the wrapper into the usage site, effectively eliminating heap allocation. While they provide type safety, they are restricted to a single underlying property and lack the structural equality and copy features inherent to data classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'585dc8c3-fa0d-447a-ac3e-9674bc1a74ba', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the significance of the ''Micronaut Data'' project?', N'Intern', N'Micronaut Data is a library that provides data access support by generating query logic at compile time. It eliminates the need for runtime reflection often found in traditional ORMs, improving performance and reducing startup time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef7aff54-4a67-4058-a9f8-96765ceaedf5', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of Micronaut''s ''Introspection'' feature for JSON serialization libraries?', N'Senior', N'Introspection allows Micronaut to access class metadata at runtime without using reflection. By providing a compile-time generated view of a class''s properties, it allows JSON libraries to serialize and deserialize data significantly faster while maintaining compatibility with native images.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc28d77-3f2c-4560-936f-967725221ad7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding?', N'Intern', N'Sharding is a database architecture pattern that splits a large dataset into smaller, manageable chunks called shards. These shards are distributed across multiple servers, allowing the database to process requests in parallel and support much larger storage capacities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e493bece-2cf2-48c3-8f10-9677923e9792', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the importance of reference counting?', N'Intern', N'In Python, reference counting is a technique used for automatic memory management. It involves keeping track of the number of references to an object and automatically deallocating the object when there are no more references to it. The importance of reference counting in Python can be summarized as follows: - Automatic memory management: Reference counting allows Python to automatically manage memory without requiring explicit memory allocation or deallocation by the programmer. This simplifies programming and reduces the risk of memory leaks and other memory-related bugs. - Efficient memory management: By deallocating objects as soon as they are no longer needed, reference counting helps to minimize the amount of memory used by a program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'992ae812-a13b-494c-b608-96782409aa0a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are jQuery selectors and how are they similar to CSS?', N'Fresher', N'jQuery selectors are strings used to find HTML elements based on their tag name, class, ID, or attributes. They use the same syntax as CSS selectors, making them very easy for developers familiar with CSS to start using immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa35b36c-4e52-4c55-b854-967828304bda', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the function of the flash() method?', N'Intern', N'The flash() method is a simple way to store a message in the session that can be displayed to the user on the next request. It is typically used for showing feedback, such as success notifications or error messages after a form submission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
