INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbe4f991-b3e0-47f0-850e-9678d84de693', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a middleware function in Express?', N'Intern', N'Middleware functions are functions that have access to the request object, the response object, and the next middleware function in the application''s request-response cycle. They can execute code, make changes to the request and response objects, end the cycle, or call the next middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbc96e72-6fb2-47a6-957e-967b4021cc09', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the effect of having too many indexes on a collection?', N'Junior', N'Every index consumes disk space and memory, and every write operation must update all associated indexes. Having too many indexes can significantly slow down write performance and increase resource consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
