INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4553146-3870-4b2d-ad4f-96846de58259', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the interaction between ''Generic Constraints'' and API flexibility.', N'Senior', N'Generic constraints limit the types that can be used with a generic, ensuring that the internal logic can safely rely on specific properties or methods. This creates a balance between the flexibility of generics and the safety of concrete interfaces, preventing the over-use of ''any'' within generic functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70c66246-f879-4330-8476-96858d7cd95f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the MongoDB Aggregation Framework?', N'Fresher', N'The aggregation framework is a powerful tool for data analysis and transformation. It processes documents through a pipeline of stages, such as filtering, grouping, and sorting, to produce calculated results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9159a83-db70-4b48-8df7-9686618f444a', N'075b8862-431c-4678-9767-f55359758a4a', N'Describe the lifecycle of a Vue component update cycle.', N'Senior', N'When a reactive dependency changes, Vue queues the component for an update in a scheduler. To avoid redundant DOM operations, Vue flushes this queue asynchronously in a single tick, performing a virtual DOM diff and patching only the necessary elements, which ensures consistency and high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d7756cf-9f79-4483-8e0b-96880b086fb7', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary goal of the Preact library?', N'Intern', N'Preact is designed to be a lightweight alternative to React. It aims to provide the same core API and component-based architecture while significantly reducing the bundle size to improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46a3d404-9ae4-49d7-8b11-9688cdab7b23', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the purpose of the volatile keyword in C.', N'Middle', N'The volatile keyword informs the compiler that a variable''s value can change at any time without any action being taken by the code the compiler is currently processing. This prevents the compiler from performing optimizations like caching the variable in a register, ensuring it is re-read from memory every time it is accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94763837-79e0-445f-9e54-968969a3be41', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it important to implement rate limiting, and what are the common strategies?', N'Middle', N'Rate limiting protects your API from abuse, denial-of-service attacks, and accidental resource exhaustion by limiting the number of requests a user can make. Common strategies include fixed-window counters, sliding-window logs, or the token bucket algorithm, each balancing accuracy and performance differently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d44c970-134b-4985-9657-9689dfb38dba', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ''src'' and ''srcset'' attributes in an image tag?', N'Middle', N'The ''src'' attribute provides a fallback or default image source for browsers. The ''srcset'' attribute allows you to provide a list of different image versions along with their widths or pixel densities, enabling the browser to choose the most appropriate file based on the user''s current screen resolution. This prevents wasting bandwidth by loading high-resolution images on devices that cannot display the extra detail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'453a87bc-aff8-4b58-87c4-968b6c126ff8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Can NoSQL databases handle ACID transactions?', N'Junior', N'While traditionally NoSQL favored BASE, many modern NoSQL databases have added support for multi-document ACID transactions. However, these features usually come with a performance trade-off compared to the BASE model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
