INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fae95e66-9e6a-4c58-953a-96ad2ebd40d8', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Compare the security architectures of Token-based authentication versus Session-based authentication in microservices.', N'Senior', N'Session-based authentication typically relies on server-side state, making it difficult to scale across distributed services without shared storage like Redis. Token-based authentication is stateless, allowing each service to verify user identity independently, though it necessitates a robust mechanism for token validation and revocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b683574-6aff-4bc3-aa65-96b46cf4d479', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s bundle size impact the ''Total Blocking Time'' metric?', N'Middle', N'Because Preact is smaller, the browser spends significantly less time parsing and compiling JavaScript. This reduces the Total Blocking Time, allowing the main thread to become available for user interactions much faster than if a larger framework were used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
