INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd26f9354-6ee0-4c60-8318-96b69312d7b7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch differ from a relational database?', N'Fresher', N'Elasticsearch is a document-oriented NoSQL search engine, whereas relational databases use tables and rows. Elasticsearch excels at full-text search and schema-less data, while relational databases are optimized for complex transactions and data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'377c4f89-e2dc-4096-989f-96b983724068', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does ''mutating'' mean in the context of structs?', N'Junior', N'Since structs are value types, their properties cannot be modified from within their instance methods by default. The mutating keyword allows a method to modify the properties of the struct and write those changes back to the original instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31181132-1e42-4bc0-a402-96bb3ddd13bc', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle ''404 Not Found'' errors in Express?', N'Middle', N'A 404 error is handled by placing a middleware function at the end of the stack, after all other routes have been defined. If a request reaches this point, it means no previous route or middleware matched the request, and you can then send a 404 response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c45a4f2-6f1d-4ac3-946d-96bccfceec78', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of TypeScript in relation to JavaScript?', N'Intern', N'TypeScript is a syntactic superset of JavaScript that adds optional static typing. Its primary purpose is to provide compile-time type checking, which helps developers catch errors early in the development process before the code is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e2a9dae-215a-4f3e-9142-96c740b66f15', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the $lib folder?', N'Intern', N'The $lib folder is a central directory for library code, such as utility functions, reusable components, or shared logic. It is easily accessible from anywhere in your project using a special import alias.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0bd108e-a363-409d-b83d-96ceef29365a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the advantage of using H2 database for testing?', N'Intern', N'H2 is an in-memory database that is very fast and easy to set up. It is ideal for testing because it does not require an external server installation and the data is cleared every time the application restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d4d107a-3984-4684-889a-96d4bdf2fbf7', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it recommended to use the ''static get properties()'' or decorators in Lit?', N'Middle', N'These mechanisms allow Lit to register properties for the reactive system, enabling automatic observation, attribute reflection, and type conversion. Without this declaration, the component cannot track changes or trigger re-renders based on property modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a5cdcf7-b5c7-47cf-b38a-96d62d62490d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Is useState Synchronous or Asynchronous?', N'Middle', N'The useState hook is synchronous, but state updates are asynchronous. When you call useState(), it runs synchronously and returns the state variable and setter function as tuple. This happens immediately during rendering. However, the state update function (setState) is asynchronous in the sense that it doesn''t update the state immediately. React batches updates and applies them before the next render. You won’t see the updated value immediately after calling setState. Example: The > console.log(count) prints the old value, because the update hasn’t happened yet. To see the updated state value, you can use useEffect() hook. It runs after the component has re-rendered. By the time useEffect runs: * The component has been updated. * The state contains the new value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'563609e8-3644-45d0-94d1-96d764eca74b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Hot Module Replacement (HMR) function in Vite?', N'Middle', N'Vite performs HMR over native ESM. When a file is edited, Vite accurately invalidates the chain between the modified module and its nearest HMR boundary, ensuring only the affected module is re-fetched by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cdbc1e5-9917-47aa-975b-96d8bdc3d018', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is "npm" and what is it used for?', N'Intern', N'npm (Node Package Manager) is a powerful and highly popular package manager that is focused on the Node.js environment. Its primary purpose is to simplify the installation, management, and sharing of libraries or tools written in Node.js. npm is more than just a package manager: It''s also a thriving ecosystem, offering a plethora of ready-to-use modules and tools, thereby making the development workflow for Node.js even more efficient. Key Functions - Package Installation: npm makes it easy to install and specify dependencies for Node.js applications. Developers can simply define required packages in a package.json file, and npm resolves and installs all dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb751d9d-d97a-4108-9ac9-96d8c63c02ac', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why are stored procedures called executable code?', N'Fresher', N'Stored procedures are named, pre-compiled T-SQL batches stored in the database. SQL Server caches their execution plans, so repeated calls reuse the compiled plan — avoiding re-parsing and re-optimizing on every call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad7eaa4d-7fbb-4949-9297-96dae5096cd9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the concept of eventual consistency.', N'Middle', N'Eventual consistency is a consistency model in distributed systems where, if no new updates are made to a data item, eventually all accesses to that item will return the last updated value. It allows for high availability and performance by accepting that different nodes may temporarily hold different versions of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f9e5a71-b0cf-4693-b8b1-96ddfdbf1451', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS require a build step?', N'Intern', N'Yes, Tailwind requires a build step to process the CSS. Because it generates styles based on the classes found in your files, a tool must run to scan your project and produce the final, optimized CSS file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'880f862f-438f-4524-a7d1-96deaaa67a47', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle the Virtual DOM?', N'Fresher', N'Like React, Preact uses a Virtual DOM to minimize direct interaction with the actual browser DOM. When component state changes, Preact calculates the difference between the new and old Virtual DOM trees and updates only the necessary parts of the real DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98cfc14d-e851-4b6b-9e57-96e3565de991', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you redirect new page in javascript?', N'Fresher', N'To redirect to a new URL or page, you assign the new URL to the location.href property or use the location.assign() method. The location.replace() method does redirect to a new URL but does not create an entry in the history stack of the browser. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee868f16-92fb-42a9-975e-96e44b63df00', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the trade-offs involved in using ''setjmp'' and ''longjmp'' for non-local control flow?', N'Senior', N'These functions allow a program to jump back to a previously saved execution state, effectively bypassing normal function return mechanisms. While powerful for error handling or coroutine implementation, they can lead to resource leaks and stack corruption if objects with automatic storage duration are not properly managed during the jump.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d9552fd-c23b-4a45-9260-96e7af7a1b80', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a resolve alias in Webpack?', N'Intern', N'A resolve alias is a way to create shorter or more readable imports for modules. It allows you to map specific paths to shorthand names, avoiding long relative path strings like deep directory nesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01e55192-5ce4-4b0c-9844-96e82543f2d4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is it important to analyze tables after large bulk inserts?', N'Senior', N'Bulk inserts significantly change the data distribution, rendering the existing statistics in the pg_statistic table obsolete. Running ANALYZE updates these statistics, ensuring the query planner has accurate information regarding row counts and data histograms, which is vital for choosing the most efficient execution plans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7753c895-c716-4944-9c22-96e9c4088c38', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is Pattern Matching and how does it improve code readability?', N'Junior', N'Pattern matching is a powerful mechanism that allows you to check a value against a series of patterns and execute code based on which one matches. It acts as a sophisticated alternative to complex if-else chains, making logic flow much easier to follow and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
