INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f85ef543-a794-4a92-bd2d-96ea14466320', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the architectural purpose of the ''Magnet Pattern'' in Scala?', N'Senior', N'The Magnet Pattern replaces traditional method overloading with a single method that accepts a ''magnet'' type, which then dispatches to the correct implementation. This solves the problem of type erasure in overloaded methods and allows for more flexible API design, such as supporting multiple argument types without creating a combinatorial explosion of method signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99027a43-24ba-462e-94a9-96eb9b2765cc', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery .remove() method?', N'Fresher', N'The .remove() method deletes the selected elements from the DOM entirely, including all their child elements and any event handlers attached to them. This is used when you want to permanently delete an element from the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f515c7c-ddec-43ea-af5c-96ee8e673ff0', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of a partition key in NoSQL?', N'Fresher', N'A partition key is used to determine how data is distributed across different nodes in a cluster. By using this key, the database can efficiently route read and write requests to the correct location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb53a3ad-be2f-4b4c-85f6-96efe6fbd766', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the architectural considerations when implementing micro-frontends with Angular?', N'Senior', N'Key considerations include shared dependency management to prevent bundle bloat, maintaining a consistent design system, and choosing between build-time integration via npm packages or run-time integration using Module Federation. Runtime integration is generally preferred for independent deployment cycles but requires careful handling of shared state and global styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2620a523-ce3e-4893-a296-96f0db3002b0', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the purpose of ''Compaction'' in a Log-Structured Merge (LSM) tree?', N'Middle', N'Compaction is the background process of merging multiple data files into a single, organized file and removing obsolete records or tombstones. It is crucial for reclaiming disk space and improving read performance by reducing the number of files the system must search.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b738bf18-1590-47b1-807c-96f4a5a9b47a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does it mean to pass by value?', N'Intern', N'Passing by value means that a copy of the actual argument''s value is passed to the function. Changes made to the parameter inside the function do not affect the original variable in the calling function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cacfa93-a43a-4f47-b259-96f52f6f1f71', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is it often recommended to use strict mode in JavaScript applications?', N'Middle', N'Strict mode enforces better coding practices by throwing errors for silent failures, such as assigning values to undeclared variables. It also disables features that are considered error-prone or poorly designed, leading to cleaner code and improved engine optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4825abb9-25b6-4562-8d3d-96f77024388c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Can you define the CAP theorem as it relates to Cassandra?', N'Fresher', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition tolerance. Cassandra is considered an AP system, prioritizing Availability and Partition tolerance over strict Consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56623815-5ddf-4ace-95ad-96fb1690a4ab', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the architectural implications of using Blueprints in a modular Flask application?', N'Senior', N'Blueprints allow for the logical partitioning of routes, templates, and static files into independent components. This promotes separation of concerns and facilitates team scaling by allowing different modules to be developed and tested in relative isolation before being registered to the main application instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7d683a7-6753-4501-81c3-96fc8681faa4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the Common Language Runtime (CLR) in C#?', N'Intern', N'The CLR is the execution engine that manages the execution of C# programs. It handles services like memory management, security, and exception handling for code compiled into the Common Intermediate Language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f11d0fa-f0ef-414e-a550-9700b9c26a3c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between a Singleton and a Prototype bean?', N'Intern', N'A Singleton bean is shared across the entire application, meaning only one instance exists. A Prototype bean is created every time it is requested by the container, ensuring that each consumer receives a unique instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd101b486-1978-4ed4-af9c-970260c8b059', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a schema in the context of databases?', N'Fresher', N'A schema is the formal structure or blueprint of a database that defines how data is organized and how the relations among them are associated. It describes the tables, fields, data types, and constraints that constitute the database design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdd7dbba-759b-4de7-9b8a-970337c1b5e1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the trade-offs of using MongoDB''s ''majority'' write concern in a distributed cluster.', N'Senior', N'Using ''majority'' write concern ensures that data is persisted to a majority of voting nodes, providing strong consistency guarantees against rollbacks. The trade-off is increased latency, as the client must wait for acknowledgment from multiple nodes, and reduced availability if a majority of nodes cannot be reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05c7f380-2d12-47fd-9c92-97049bdd30f2', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain what is the common way for the Flask script to work?', N'Fresher', N'The common way for the flask script to work is Either it should be the import path for your application Or the path to a Python file', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2b9d5ce-3985-42a8-82fc-970523e4f147', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does transaction isolation level affect database design?', N'Middle', N'Transaction isolation levels determine how data is locked during concurrent operations, balancing data consistency against system concurrency. Higher isolation levels prevent anomalies like phantom reads but reduce system throughput by increasing lock contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ee5437-d93e-4b92-8578-970570b2b5fd', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the function of the ''coordinating node'' in a non-data node configuration?', N'Senior', N'A dedicated coordinating node acts as a load balancer and request aggregator, offloading the work of broadcasting queries, merging results, and managing client connections from the data nodes. This improves cluster stability by isolating the heavy CPU and memory requirements of result aggregation from the storage and indexing duties of data nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99df850b-d243-4beb-887c-970736fb7494', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify achieve high performance?', N'Intern', N'Fastify achieves high performance by utilizing a highly optimized internal routing system and leveraging the Ajv library for schema validation. It also minimizes memory consumption and reduces overhead by avoiding unnecessary object creation during the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f1a6a4d-1629-4f7f-82a7-97075b5a8c7e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle static files like CSS and JavaScript?', N'Fresher', N'Flask looks for static files in a directory named ''static'' located at the root of the project. You can link these files in your HTML templates using the ''url_for'' function pointing to the ''static'' endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66f16c4c-24bf-4d94-a6af-970aed6fa233', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle errors differently than exceptions?', N'Middle', N'Rust uses return values for errors, which forces the caller to acknowledge and handle them as part of the function''s contract. Unlike exceptions, which can jump across stack frames and create hidden control flow paths, Rust''s approach makes error handling explicit and integrates it into the type system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'693d4c1c-9b58-4784-a381-970c8b0bdedc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the ''TracePoint'' API differ from traditional debuggers, and what is its architectural impact?', N'Senior', N'TracePoint allows for hooks into internal VM events like method calls, class definitions, and line execution without modifying the source code. While it is powerful for profiling and instrumentation, it adds overhead to the VM''s execution, as it must trigger callbacks for every event, which can significantly slow down high-throughput applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
