INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82ba3f11-8df8-4f8e-a8b5-971fee8756ae', N'075b8862-431c-4678-9767-f55359758a4a', N'What are Vue.js components and how do you use them?', N'Fresher', N'Vue.js components are reusable, self-contained elements that consist of three main parts: a template, script, and style. These encapsulated building blocks enable a clear separation of concerns within your web application. Efficiently constructed components can significantly contribute to the maintainability and scalability of your Vue app. In component-based development, a larger application is broken down into smaller, interconnected units—the components. Each component focuses on one specific task, such as presenting the user interface for an email, a customer, or a form. This modular structure streamlines the development process and enhances code reusability. Anatomy of a Vue Component Here''s the step by step: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
