INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d812705-77e5-4dd7-8b58-972384b55cca', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the architectural difference between Vue 2''s Object.defineProperty reactivity and Vue 3''s Proxy-based system.', N'Senior', N'Object.defineProperty requires iterating over all object keys to define getters and setters, which fails to detect property additions or deletions without specific API calls. Proxies act as a trap on the entire object, allowing for dynamic interception of operations, resulting in better performance and comprehensive change detection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1ff97fa-f46a-4392-a4d3-9724ed68fdd0', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the dangers of ''Distributed Monolith'' architecture?', N'Senior', N'A distributed monolith occurs when microservices are so tightly coupled that they must be deployed together to function correctly. This negates the benefits of microservices, such as independent deployability and fault isolation, resulting in all the complexity of a distributed system with none of the agility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfb33193-ce25-4549-ba34-9725777367f8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS differ from React in terms of its reactive primitive execution model?', N'Senior', N'SolidJS uses fine-grained reactivity where components execute only once during initialization, with individual reactive primitives tracking their own dependencies. In contrast, React re-executes the entire component function whenever state changes, relying on a virtual DOM reconciliation process to detect differences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89e02be0-4fe0-48ae-86fa-97289687abae', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the nuxt.config file?', N'Intern', N'The nuxt.config file is the central configuration file for your Nuxt application. It is used to define global settings, environment variables, module registrations, and head meta-information that affect the entire project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff18c5fb-8f4a-45e1-92f5-972ff3a832f8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between physical and logical replication in MySQL?', N'Senior', N'Physical replication (Row-based) records the exact changes to rows, ensuring complete consistency even with non-deterministic functions. Logical replication (Statement-based) records the SQL queries, which is more space-efficient but can lead to data divergence if functions like NOW() or UUID() are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b53a5b7e-b6fb-425c-83ac-973318d910d5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the css selectors?', N'Intern', N'A CSS selector is the part of a CSS rule set that actually selects the content you want to style. i) Universal Selector: The universal selector works like a wild card character, selecting all elements on a page. Every HTML page is built on content placed within HTML tags. Each set of tags represents an element on the page. ii) Element Type Selector: This selector match one or more HTML elements of the same name. iii) ID Selector: This selector matches any HTML element that has an ID attribute with the same value as that of the selector. iv) Class Selector: The class selector also matches all elements on the page that have their class attribute set to the same value as the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fa8a335-1e26-41a8-8d48-97359e235efe', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You discover that a software system you are working on has a bug that only occurs intermittently. How do you approach debugging this?', N'Intern', N'I would first attempt to document the specific steps or conditions under which the bug appears, as consistency is key to reproduction. I would then analyze system logs or monitoring data from the times the issue occurred to look for patterns, such as spikes in traffic or specific user actions, that correlate with the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'306284da-f9aa-4c00-a710-9736f93c2611', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between a shallow copy and a deep copy in Ruby?', N'Middle', N'A shallow copy duplicates the object but keeps references to the same nested objects as the original. A deep copy would recursively duplicate all contained objects, ensuring the new object has no shared state with the original, which is not provided natively by Ruby''s standard library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c83b154a-b7e5-4a11-ace9-973ac2782b26', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the ''content'' directive in Sass mixins, and how does it enable architectural patterns like wrapper components?', N'Senior', N'The @content directive allows a mixin to accept a block of styles as an argument. This enables the creation of layout wrappers or media query abstractions that encapsulate shared behavior while allowing the consuming component to define its own specific internal styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8de57d93-a2f3-4343-abcd-973c02e5b911', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the benefit of using ''functional'' programming styles in R?', N'Middle', N'Functional programming reduces side effects and promotes modular, predictable code by relying on pure functions and data transformations. This approach makes code easier to test, debug, and parallelize across multiple CPU cores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'592c3ef2-9163-417d-aae6-973cdf65a48b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How do you handle state in a Preact application?', N'Junior', N'Preact uses the useState hook or the Component state object in class components, similar to React. You update state using the provided setter function, which triggers a re-render of the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9096a58d-10fb-451f-b77c-973e6804234c', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Is Litestar compatible with standard ASGI servers?', N'Fresher', N'Yes, Litestar is an ASGI framework, meaning it is compatible with any ASGI-compliant server such as Uvicorn or Hypercorn. This ensures high performance and interoperability with other parts of the Python web ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51597ad9-8cc6-4fa4-ac35-973fb3fca1c6', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What does eventual consistency mean in DynamoDB?', N'Intern', N'Eventual consistency means that a read operation might not immediately reflect the results of a recently completed write. Data is replicated across all storage nodes, and the system becomes consistent within a short period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea1052ba-e989-4066-a3fa-974074b5df5d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix improve user experience during data mutations?', N'Fresher', N'Remix uses ''optimistic UI'' techniques, where the interface updates to reflect a successful action before the server has even finished processing. This makes the application feel instantaneous and responsive even on slower network connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32843912-849f-48ea-95a6-974171c2ecbd', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix ensure thread safety given the shared-nothing nature of Rust?', N'Senior', N'Actix leverages Rust’s ownership and Send/Sync traits to enforce thread safety at compile time. By ensuring that mutable state is either encapsulated within an actor or protected by appropriate synchronization primitives, it prevents data races by design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05096e45-4b2f-46b1-bdb0-9747d2d562ff', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Optional Properties?', N'Intern', N'Optional properties are fields in an object or interface that do not have to be provided. They are marked with a question mark and allow for more flexible data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a689dfe9-8ed3-480d-b1e9-9747dd38532e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the trade-offs of using Kotlin''s ''inline'' functions?', N'Middle', N'Using the inline keyword instructs the compiler to copy the function body directly into the call site, which can improve performance by reducing object allocation for lambda expressions. However, excessive use can lead to significant increases in the generated bytecode size and may negatively affect performance if the inlined function is very large.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1973b0c1-e45d-451f-9ab4-974a37ee147b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go ensure memory safety?', N'Intern', N'Go ensures memory safety by providing features like garbage collection and bounds checking on arrays and slices. It also limits pointer arithmetic, preventing common programming errors that can lead to memory corruption or crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'136882ac-db8c-481e-8acb-974d67966c28', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a relational database and a NoSQL database for a new microservice?', N'Middle', N'Relational databases are preferred when data integrity, complex queries, and ACID transactions are critical for the business logic. NoSQL is a better fit when the data schema is highly dynamic, the volume is massive, or horizontal scalability is required through sharding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'278fb7d0-3b98-4122-85a1-97500253864a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the Nuxt Nitro engine in the overall framework architecture?', N'Senior', N'Nitro is a high-performance server engine that powers Nuxt''s server-side capabilities, designed to be platform-agnostic. It abstracts the underlying deployment environment, enabling features like cross-platform compatibility, built-in caching, and optimized cold-start times for serverless functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd73824e4-a3dd-4b24-830b-975015931f76', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the HTTP/2 implementation in Node.js differ from HTTP/1.1 regarding stream multiplexing?', N'Senior', N'HTTP/2 allows for multiplexing multiple requests and responses over a single TCP connection, reducing head-of-line blocking compared to the serial nature of HTTP/1.1. In Node.js, this is handled through the ''http2'' module, which manages streams and flow control to optimize network utilization and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca7a8289-3bb2-4a94-982a-9750683345be', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is hot module replacement (HMR)?', N'Intern', N'HMR is a feature that allows modules to be updated in the browser while the application is running, without requiring a full page refresh. This significantly speeds up the development process by preserving the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c7f97a3-ef56-4f14-8f8c-97587e4f3557', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does a WAF (Web Application Firewall) differ from a standard network firewall?', N'Middle', N'A network firewall operates at lower layers to filter traffic based on IP addresses and ports. A WAF operates at the application layer to inspect HTTP traffic for patterns like SQL injection or XSS, providing protection specific to web vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f630341b-a09b-4e40-9a50-975915afc4b4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your philosophy on technical debt and when should it be paid down?', N'Senior', N'Technical debt is a strategic tool for speed, but it must be tracked as a financial liability. I advocate for paying it down when it begins to impede velocity, increase defect rates, or pose a security risk, ideally scheduling it as a percentage of each development sprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5881400b-55a1-414e-9eb2-97597b1bd3b7', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does the DynamoDB adaptive capacity feature work and what are its limitations?', N'Senior', N'Adaptive capacity automatically rebalances partitions to handle uneven traffic patterns by shifting throughput capacity to busier partitions. Its limitation is that it cannot instantaneously resolve extremely spiky traffic patterns that exceed the total table throughput limit. It is a reactive mechanism rather than a proactive scaling strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49f77dbb-5c67-4e0f-9f53-975b0693bddb', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is the order of middleware significant in an Axum application?', N'Senior', N'Middleware in Axum is applied as a layered stack, meaning the order of ''layer()'' calls determines the execution order. An outer layer wraps the inner layers, so concerns like logging or authentication must be placed correctly to ensure they execute before the request reaches the handler logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1d5b769-3f98-4453-b804-975cf5ee734f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the Scala REPL?', N'Fresher', N'REPL stands for Read-Eval-Print Loop. It is an interactive shell that allows developers to write and execute Scala expressions instantly, making it a great tool for experimenting and testing code snippets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0668675d-0f9c-48fd-a31c-975ea813ed8d', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is an index and why is it used?', N'Junior', N'An index is a data structure that improves the speed of data retrieval operations on a table. While it speeds up reading data, it can slightly slow down write operations because the index must be updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6cf29d3-9f42-4766-a58f-9760443b56d5', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the benefit of Alpine.js being ''buildless''?', N'Intern', N'Being buildless means Alpine.js can be included in a project via a simple script tag without needing tools like Webpack, Vite, or a complex Node.js environment. This makes it very easy to integrate into simple projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb785b71-22f4-49db-95e1-97609a7f6717', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''Hash'' provider improve security in user management?', N'Senior', N'The Hash provider abstracts the hashing algorithm, allowing for seamless upgrades to stronger algorithms as security standards evolve. By centralizing this logic, it ensures that all password storage remains consistent and protected against rainbow table attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40ad756e-39a7-4447-af14-97611e896460', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is meant by the term ''subsetting'' in R?', N'Intern', N'Subsetting is the act of selecting specific elements, rows, or columns from a data structure like a vector, matrix, or data frame. It allows users to isolate and analyze specific parts of a larger dataset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02f55dde-4d25-4f70-a798-97618ccfb10a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the role of Chi''s ''RouteContext'' in complex request flows.', N'Senior', N'RouteContext is an internal object that Chi uses to track the state of the routing process, including current route patterns and parameter values. It is stored in the request context, allowing handlers to inspect the routing metadata, which is useful for audit logging or dynamic access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e2037c9-daa6-49ae-9a9b-9765cc187827', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between binary log group commit and parallel replication?', N'Senior', N'Group commit allows multiple transactions to be flushed to the binary log in a single disk I/O operation, reducing sync overhead. Parallel replication allows a replica to apply transactions from the relay log using multiple worker threads, provided those transactions do not have conflicting row dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff553839-846e-4482-ac90-9766b62fcac3', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a ''helper'' in Ruby on Rails?', N'Fresher', N'Helpers are modules that contain methods designed to be used in view templates to keep the logic out of the views. They are primarily used to format data or generate HTML snippets, which makes the templates cleaner and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7700b73a-8669-4d11-8574-9767d481953f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the benefit of using fibers for handling long-lived WebSocket connections?', N'Middle', N'Fibers allow each WebSocket connection to have its own dedicated flow of logic without the massive memory overhead of threads. This enables a single server instance to maintain a massive number of active, stateful connections with efficient context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a1f49d3-45bc-45a8-ad51-976845026dd7', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle JSON serialization?', N'Fresher', N'Litestar uses high-performance libraries to automatically serialize Python objects to JSON. It handles complex types and models defined by the developer, ensuring the response matches the expected output schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2890a412-a7b5-458b-a035-976baa1b328a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket considered ''opinionated''?', N'Fresher', N'Rocket is opinionated because it encourages specific ways of structuring code and handling requests to ensure safety and performance. This reduces decision fatigue for developers by providing a standard, recommended way to build web services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad2c53eb-0e94-45f9-ab1f-976d94b739e6', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why are locks used in database transactions?', N'Intern', N'Locks are used to manage concurrent access to data by ensuring that only one transaction can modify a specific piece of data at a time. This prevents conflicts and helps maintain the integrity of the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41f55bb7-3ef1-41f9-b40d-976edc566fa4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the significance of the ''search path'' in R.', N'Middle', N'The search path is the sequence of environments R looks through to resolve a variable name. It includes the global environment, loaded packages, and the base environment, which can lead to name masking if two packages export functions with the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f308d715-0a46-4b11-b8d8-9773a9d471c3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the primary risk of using ''story points'' for estimation in a team that is new to the practice?', N'Middle', N'The main risk is the tendency to map story points directly to man-hours, which defeats the purpose of relative estimation. I would coach the team to focus on complexity, effort, and risk rather than time, ensuring that points are used for velocity tracking rather than scheduling pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91b50869-38c9-40ec-a99a-97752d9143b9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the time required for a task you have never performed before?', N'Intern', N'I would break the task into the smallest possible components that I do understand. I would then estimate each of those components, apply a buffer for the learning curve, and consult with a mentor to see if my estimate aligns with their expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccb8e542-5a54-46e0-88ad-97765b084b9b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket utilize Rust''s type system to enforce security at compile-time?', N'Senior', N'Rocket leverages Rust''s ownership model and type system to ensure that request data is automatically validated and converted into typed structures before reaching the handler. This prevents common vulnerabilities like injection attacks by ensuring that only type-safe, validated data is processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f66cca44-89ac-4ea4-abb4-97765f062866', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of the Dockerfile in a NestJS application, and how it facilitates containerization?', N'Fresher', N'A Dockerfile is a text document that contains all the commands a user could call on the command line to assemble an image. In the context of a NestJS application, a Dockerfile is used to create a Docker image of the application. A Docker image is a lightweight, standalone, executable package of software that includes everything needed to run an application. It includes code, runtime, system tools, system libraries, and settings. This image can be run consistently on any machine that has Docker installed, regardless of the underlying operating system. Here is an example of a Dockerfile for Nest application: This Dockerfile does the following: Starts from a base image with Node.js installed (node:14-alpine). Sets the working directory in the container to /usr/src/app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23171ba7-5bca-49a2-b905-97786cefe117', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'When is it appropriate to use FastAPI''s ''BackgroundTasks'' versus a message broker architecture?', N'Senior', N'BackgroundTasks are suitable for lightweight, non-critical tasks that don''t need persistent guarantees. If the task requires high reliability, retries, or needs to survive a service restart, a message broker like RabbitMQ or Redis with a consumer-worker pattern is the standard architectural choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c330e29-fad8-4c00-b793-9779983864b6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the difference between ''layout'' and ''page'' components in the context of SvelteKit''s component tree.', N'Senior', N'Layouts serve as persistent wrappers that encapsulate shared UI, such as headers and footers, and maintain their state across sub-route navigations. Pages are the leaf nodes of the routing tree, representing the specific content that changes, allowing for efficient nested rendering and state preservation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129ccf74-1ac9-499e-932b-977e319e097c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why should you avoid ''quick fixes'' without understanding the root cause?', N'Fresher', N'Quick fixes often mask the symptoms without solving the underlying problem, which can lead to the bug reappearing later. Understanding the root cause ensures a permanent solution that prevents the issue from recurring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38dca852-4781-46f7-9af1-978130bb9e49', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the limitations of using Lit components within a server-side rendered (SSR) environment?', N'Senior', N'SSR with Lit requires a compatible implementation of the Declarative Shadow DOM specification to ensure the browser can hydrate the shadow content immediately upon loading. Without proper SSR support, components may suffer from FOUC or re-hydration costs where the entire component must be re-rendered on the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ecce00a-5401-41fa-8ac8-978268bc7f63', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix treat the URL as the primary state manager?', N'Senior', N'By encoding application state into the URL parameters and search queries, Remix makes navigation bookmarkable and shareable. This architecture ensures that the application state is always recoverable and predictable, as the URL acts as the single source of truth for the user''s current view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fd7b5e0-53d4-46f8-9b30-978325f7cdff', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Can you describe the principles behind the microservices architecture?', N'Senior', N'Microservices is an architectural style that structures an application as a collection of small, loosely coupled services. Each service is self-contained, focused on a specific business goal, and can be developed, deployed, and maintained independently. Core Principles of Microservices Codebase & Infrastructure as a Service Each microservice manages its own codebase and data storage. It uses its own independent infrastructure, ranging from the number of virtual machines to persistence layers, messaging systems, or even data models. Antifragility Microservices, instead of resisting failure, respond to it favorably. They self-adapt and become more resilient in the face of breakdowns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6671785-8cde-4965-be43-978802ab43e3', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''defer'' and ''only'' methods in QuerySets?', N'Middle', N'These methods are used to optimize database performance by limiting the columns retrieved from the database. ''Only'' fetches only the specified fields, while ''defer'' fetches all fields except those explicitly excluded, which reduces memory usage when dealing with tables containing large text or binary fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1da73f3c-3a81-45d3-9398-9789cef71a04', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the fundamental unit of data storage in Elasticsearch?', N'Junior', N'The fundamental unit is the document, which is stored as a JSON object. Documents are grouped into types and indices, representing a collection of related data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6019521-8463-4beb-8a6f-978bf11b744c', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a destructor in C++?', N'Intern', N'A destructor is a special member function that is automatically called when an object goes out of scope or is explicitly deleted. It is used to release resources, such as memory or file handles, acquired by the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80b3dcaf-18b0-4fcd-8b74-978dd7591f13', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a parameterized pipe?', N'Intern', N'A pipe can accept any number of optional parameters to fine-tune its output. The parameterized pipe can be created by declaring the pipe name with a colon ( : ) and then the parameter value. If the pipe accepts multiple parameters, separate the values with colons. Let''s take a birthday example with a particular format(dd/MM/yyyy): Note: The parameter value can be any valid template expression, such as a string literal or a component property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5794203c-f306-4387-8526-9792733a3219', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does ''Expiration'' mean in Redis?', N'Intern', N'Expiration is a feature where you can set a time-to-live for a specific key. Once the time expires, Redis automatically deletes the key, which is very useful for managing temporary data like user session tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e1a547c-3387-4b4d-973b-9793dcee78e5', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the architectural impact of Svelte''s CSS encapsulation strategy?', N'Senior', N'Svelte scopes CSS by automatically hashing class names at compile-time. This prevents style leakage and eliminates the need for CSS-in-JS libraries, resulting in better performance as browsers can parse standard CSS files without runtime execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
