INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9b8e4b0-8f1a-4640-93da-9794fbe4eb73', N'4c000000-0000-0000-0000-000000000005', N'How does a message broker ensure reliable delivery?', N'Middle', N'Message brokers provide features like persistence, acknowledgments, and retries to ensure messages are not lost. If a consumer fails to process a message, the broker can hold the message and attempt redelivery later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9319b4f7-65ce-4867-bcbd-97951ab4468a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the function of the Qwik Optimizer?', N'Middle', N'The Optimizer is a build-time tool that automatically breaks the application code into small, lazy-loadable chunks. It transforms the source code to facilitate fine-grained code splitting, ensuring only the necessary functions are loaded during interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29b14326-de02-4b7e-9115-9795cf3d3873', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a lambda?', N'Junior', N'A lambda is a type of Proc that checks the number of arguments passed to it strictly. It also behaves more like a standard method regarding the ''return'' keyword, which returns from the lambda rather than the surrounding scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63e1f7e8-3576-4849-9bb0-9795e69687b2', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between a class variable and an instance variable?', N'Fresher', N'An instance variable is specific to each object created from a class, while a class variable (declared with ''static'') is shared across all instances of that class. Static variables are accessed through the class name rather than an object instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5ac1056-dea2-4607-9bff-979a632da840', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the derive attribute in Rust?', N'Junior', N'The derive attribute allows you to automatically implement certain standard traits for your own structs and enums. This saves time by generating boilerplate code for common tasks like equality checking or formatting for output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df2c2fdb-b9ad-48aa-89ef-979af67541e2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP Zend Engine''s Opcache mechanism affect memory usage and execution speed in a multi-process environment?', N'Senior', N'Opcache stores precompiled script bytecode in shared memory, allowing multiple PHP processes to access the same memory segment instead of recompiling scripts on every request. This significantly reduces CPU overhead and memory footprint by eliminating redundant compilation cycles across the lifecycle of the web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e09c8ed-9b8c-4fe4-b94d-979de048dd76', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a comment in R code?', N'Intern', N'A comment is a line of text in an R script that is preceded by a hash symbol and is ignored by the R interpreter. Comments are used to describe the intent of the code for human readers without affecting the execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0df172b2-3a6a-4fe3-a28b-979ef7527b7f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do distributed databases manage atomicity across multiple nodes?', N'Senior', N'Distributed databases typically use the Two-Phase Commit (2PC) protocol, which introduces a coordinator to ensure all participating nodes agree to commit or abort. Alternatively, some systems use Paxos or Raft consensus algorithms to replicate the transaction log across nodes, ensuring consistency even if individual nodes fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f75f0244-9aeb-406c-bd98-97a0246ba4ed', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing for high availability, what is the trade-off between multi-region and multi-zone deployment?', N'Middle', N'Multi-zone deployment protects against localized data center failures with low latency and lower cost. Multi-region deployment provides protection against entire geographic disasters but introduces significant complexity regarding data replication latency and the challenge of keeping the application functional across regions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6427c9a7-1a40-4979-949b-97a511e50414', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is Astro, and how does it differ from traditional single-page application frameworks?', N'Intern', N'Astro is a web framework focused on content-driven websites, designed to deliver fast performance by shipping minimal JavaScript to the browser. Unlike traditional frameworks that render everything on the client, Astro prioritizes server-side rendering and static site generation to reduce page load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
