INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05c1b8c0-bf3d-4bc5-ac3e-97ab94dd6795', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the benefits of using native ES modules during development?', N'Fresher', N'Native ES modules allow the browser to request only the files that are currently needed. This avoids the overhead of bundling the entire project every time a change is made, leading to extremely fast development feedback loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce3f0e39-147a-4331-8f0c-97ac31158012', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is PDO and why is it used?', N'Junior', N'PDO, or PHP Data Objects, is a database access layer that provides a uniform method to interact with different database systems. It is preferred over older extensions because it supports prepared statements, which help prevent SQL injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'385b7c82-f39d-43c8-a7f6-97ac355fc257', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the architectural difference between Server Components and Client Components in the Next.js App Router.', N'Senior', N'Server Components are rendered exclusively on the server, resulting in zero-bundle-size overhead for the client, while Client Components utilize hydration to become interactive. This architecture allows developers to keep heavy dependencies on the server and only ship the minimal necessary JavaScript for interactivity to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6f9d01e-2748-4b53-a502-97ad4e3e19c8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript engine''s ''Mark-and-Sweep'' garbage collection algorithm identify unreachable objects?', N'Senior', N'The engine starts from a set of roots, such as the global object or active stack frames, and traverses all reachable object references. Any objects that are not reached during this traversal are marked as unreachable and are reclaimed by the garbage collector, effectively clearing memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca30b0ed-5d32-4852-a863-97ae20e6f8c3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the use of preventDefault method', N'Intern', N'The preventDefault() method cancels the event if it is cancelable, meaning that the default action or behaviour that belongs to the event will not occur. For example, prevent form submission when clicking on submit button and prevent opening the page URL when clicking on hyperlink are some common use cases. Note: Remember that not all events are cancelable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52cc2439-c3eb-45cc-9652-97b283a8ee96', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the mechanics and architectural implications of Ruby''s Method Lookup Path.', N'Senior', N'Ruby resolves methods by traversing the ancestors chain starting from the object''s singleton class, then its class, included modules, and finally the superclass chain. This dynamic dispatch mechanism allows for powerful mixin-based composition, but requires careful management of namespace pollution and performance overhead due to constant cache invalidation during runtime modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
