INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efcd25cc-c667-49d8-8c15-97c84bed6265', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the primary architectural pattern used by Litestar for handling incoming web requests?', N'Junior', N'Litestar uses a dependency injection-based architectural pattern. This allows developers to define requirements for route handlers, and the framework automatically resolves and injects those dependencies, such as database sessions or authentication services, at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'781508a1-8aa6-412a-9322-97c9609230bb', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered a ''type-safe'' framework, and how does this affect developer productivity in large-scale systems?', N'Senior', N'Hono leverages TypeScript to provide full-stack type inference for routes, including path parameters, query strings, and body payloads. This eliminates the need for manual runtime validation and contract documentation, as the client can consume the server''s types directly, significantly reducing integration bugs and maintenance overhead in distributed microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c0bfd56-8e9f-4d0e-8aba-97c96a5996a8', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''watch'' mode in Webpack?', N'Intern', N'Watch mode instructs Webpack to monitor your project files for any changes. When a file is saved, Webpack automatically triggers a re-build, which is a convenient way to see updates without manually running the build command every time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a21579d-79c0-457f-9569-97c9fa0e6219', N'4c000000-0000-0000-0000-000000000005', N'What are the trade-offs of using a microservices architecture?', N'Middle', N'Microservices allow for independent deployment, technology diversity, and better fault isolation. However, they introduce complexity in service communication, data consistency across services, and operational overhead for monitoring and debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa6688e3-91d7-4a2a-931c-97cb581aa205', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Analyze the performance overhead of Kotlin sequences compared to standard collections.', N'Senior', N'Sequences provide lazy evaluation, which prevents the creation of intermediate collections during chain operations, significantly reducing heap allocation and garbage collection pressure for large data sets. However, for small collections, the overhead of creating sequence objects and the iterator machinery can actually be slower than the eager processing of standard collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e97066-fe54-45a2-b57a-97cbe0f7ed5a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of the ''Autovacuum'' daemon, and why is manual tuning often necessary for large tables?', N'Senior', N'Autovacuum automates the cleanup of dead tuples and updates statistics for the query planner. Manual tuning is required for large tables because default thresholds may trigger too infrequently, leading to excessive bloat, or too aggressively, consuming excessive system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0754a251-e4dd-49db-b5b0-97cc636093f0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why might using an index as a ''key'' in a list be problematic for component state and DOM performance?', N'Senior', N'When items are reordered, inserted, or removed, indices change, causing React to incorrectly associate component state with the wrong data. This leads to bugs in controlled inputs or animations and forces React to perform unnecessary DOM updates instead of reusing existing elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79db4083-88e6-4d6e-9de2-97ce1b41b10d', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the benefit of the ''Nitro'' storage layer for application scalability?', N'Senior', N'The Nitro storage layer provides a unified interface for key-value stores, allowing developers to switch between memory, Redis, or cloud-based storage providers without changing application logic. This abstraction makes it easier to scale horizontally across different infrastructure providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65fe1a13-837f-4995-9b99-97d077c69f6b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite require a separate build step for TypeScript instead of performing it during bundling?', N'Senior', N'Vite uses esbuild to strip types instantly for speed, ignoring the actual type validation. This separation allows the development loop to remain fast, while developers are expected to run the standard TypeScript compiler separately to catch type errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a4d6b97-0678-4ded-850f-97d29e7b2bc8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When dealing with high traffic, what is the trade-off between blocking and non-blocking I/O operations?', N'Junior', N'Blocking I/O is easier to reason about and code but leads to poor performance under high concurrency. Non-blocking I/O allows a single process to handle many simultaneous connections, but it requires more complex programming models to avoid callback or promise hell.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f935706-2a2f-4588-8939-97d8f3b8163a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle function overloading?', N'Intern', N'Function overloading allows you to define multiple signatures for a single function. This provides different ways to call the function based on the input arguments while maintaining strict type safety for each variation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be72b17d-50f2-4f3e-b6f9-97e6123b1fa3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a pure function, and why does it matter for predictable software?', N'Intern', N'A pure function has two properties: 1. Deterministic — given the same inputs, it always returns the same output. 2. No side effects — it does not modify external state, mutate arguments, perform I/O, or depend on anything outside its arguments (no global variables, no Date.now(), no Math.random()). Pure functions are the foundation of functional programming. They are: - Trivially testable — no mocks, no setup, no teardown needed. - Safely cacheable — results can be memoised (same input → same output). - Safely parallelisable — no shared state mutations. - Composable — output of one is safely passed as input to another. Example 01: Example 02: Real-World Use Case: Redux reducers are required to be pure functions — (state, action) => newState.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b2c92e5-a4fe-40b4-9816-97e67a59f725', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the role of an HTTP Status Code in an Echo response?', N'Intern', N'An HTTP status code informs the client about the result of their request, such as success, client error, or server error. Echo allows developers to easily set these codes, such as 200 for OK or 404 for Not Found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50416171-c5f5-4f89-8bc5-97e67acfdf6b', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you handle horizontal scaling of a Django application when dealing with static files?', N'Senior', N'Django should not serve static files directly in production; instead, they should be collected and served via a dedicated web server or a Content Delivery Network. This ensures that the application server remains free to handle dynamic requests rather than I/O-heavy file serving.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62a0afb8-c808-4d40-87f6-97e971119d6a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Discuss the trade-offs of using Astro''s ''client:only'' directive.', N'Senior', N'The ''client:only'' directive bypasses server-side rendering entirely, rendering the component only in the browser. While useful for components that rely on browser-specific APIs not available during build time, it sacrifices SEO and initial page load speed for that specific component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6605f8e9-4adf-4f0b-b99b-97ea5eb32dde', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of TypeScript, and how does it relate to JavaScript?', N'Fresher', N'TypeScript is a strongly typed superset of JavaScript that adds static type definitions to the language. Its primary purpose is to catch errors early during development by ensuring variables adhere to specified data types. Once the code is written, TypeScript is compiled or transpiled back into plain JavaScript, which can then run in any browser or environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5eefdb2-f161-4b30-8aa9-97eaa8a19733', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle data revalidation after a mutation?', N'Fresher', N'After an action function completes, Remix automatically re-runs all active loader functions on the page to fetch the latest data. This ensures that the user interface always reflects the most current state from the server without needing manual state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
