INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8811c0ef-c98d-4a08-95ad-97f65b9984f6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of Type Guards and how do User-Defined Type Guards differ from built-in ones?', N'Senior', N'Type guards narrow the type of a variable within a specific block, reducing ambiguity during runtime. Built-in guards like ''typeof'' or ''instanceof'' handle primitives and classes, while user-defined type guards use a predicate return type to allow custom logic for complex object shapes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
