INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b4fb640-d69b-47f2-98a7-97fa122c7ba9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the difference between a prototype bean and a singleton bean in Micronaut.', N'Middle', N'A singleton bean is instantiated once and shared across the entire application context, making it memory-efficient for stateless services. A prototype bean is created anew every time it is injected, which is useful when the object needs to maintain unique state for each consumer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77bc48ed-1e90-4fee-8143-97fad2132cc6', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When designing a system, how do you reason about the trade-off between consistency and availability in a distributed environment?', N'Middle', N'I evaluate the specific business requirements to see if the system can tolerate eventual consistency. If the data sensitivity is high, I favor consistency at the cost of latency; if the system requires high uptime and responsiveness, I prioritize availability and implement conflict resolution strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
