INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fabcf3-cd8f-4027-beb6-97ffbfac2d71', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What does the ''bin/console'' file do?', N'Fresher', N'The ''bin/console'' file is the entry point for all Symfony command-line tools. It is used to execute various tasks like clearing the cache, creating database schemas, or debugging your application configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e50366-026a-49dc-add2-980004123d53', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby support metaprogramming?', N'Fresher', N'Ruby offers powerful metaprogramming capabilities, enabling developers to write flexible, dynamic code. Key to Ruby''s metaprogramming are class methods such as define_method and language features like Open Classes leading to advanced techniques like Dynamic Dispatch. Dynamic Dispatch Mechanism - Dynamic Dispatch: Methods can be called at runtime, based on the object''s context, using send. This makes it easier to manage method invocations in metaprogrammed code. Class Modifications with Open Classes - Open Classes: Ruby allows changing a class''s definition dynamically, even after its initial declaration. This example adds a reverse method to the String class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f58c55db-816e-4184-882d-980246a3383b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of a status code in a FastAPI response?', N'Fresher', N'Status codes inform the client about the outcome of their request, such as whether it was successful, if there was a client error, or if a server error occurred. FastAPI allows you to specify the status code for each response to ensure clear communication between the server and the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
