INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f1a40a5-4a9a-487a-9cd6-980b178c541a', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you handle a scenario where the consumer is significantly slower than the producer?', N'Middle', N'You can implement horizontal scaling by adding more consumer instances to process the queue in parallel. If scaling is not enough, you may need to optimize the processing logic, increase batch sizes, or implement a rate-limiting strategy on the producer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ecf8365-62e2-4893-b9c8-980c0dfa91f6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the benefits of using a custom Health Check implementation in a microservices architecture?', N'Senior', N'Custom health checks allow an application to report its status to orchestration tools like Kubernetes, including checks for database connectivity or external dependency availability. This enables the infrastructure to automatically restart unhealthy instances or route traffic away from failing services, increasing overall system resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
