INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'591ec54a-a148-4765-acbc-98129e84728b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web leverage the actor model compared to traditional thread-per-request architectures?', N'Middle', N'Actix-web utilizes an actor-based concurrency model where each actor processes messages sequentially in its own mailbox, preventing data races without heavy locking. This differs from thread-per-request models by decoupling request handling from execution, allowing for higher throughput and lower resource overhead by efficiently scheduling tasks across a thread pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45afaa14-88e2-4f90-9898-9816d812ccc3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between the DROP, TRUNCATE, and DELETE commands in SQL?', N'Fresher', N'DELETE is a DML command used to remove specific rows based on a condition and can be rolled back. TRUNCATE is a DDL command that removes all rows from a table while keeping the structure intact, and it is generally faster than DELETE. DROP is a DDL command that removes the entire table definition along with its data from the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33c86986-6403-4831-9ca0-981deb5acaaf', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the difference between reified type parameters and standard generics in Kotlin.', N'Senior', N'Standard generics suffer from type erasure, meaning the type information is lost at runtime, preventing direct checks like ''is T''. Reified type parameters, used in conjunction with inline functions, allow the type information to be preserved and accessible at runtime because the compiler copies the function body into the call site with the concrete type substituted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
