INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2443064b-2ac6-49d4-926a-9827847320dc', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What happens during a ''Stop-the-World'' garbage collection event?', N'Senior', N'During a full garbage collection, the runtime suspends all managed threads to safely scan the object graph and perform heap compaction. This ensures that object references are updated correctly and that the heap remains consistent. In high-performance systems, minimizing the frequency and duration of these pauses is a critical architectural challenge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
