INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d852ee8-53f3-4a59-ac94-98352f2b7496', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the role of the Go scheduler in relation to operating system threads?', N'Middle', N'The Go scheduler uses an M:N model, mapping multiple goroutines onto a smaller number of OS threads. This allows for lightweight concurrency, as the runtime handles context switching between goroutines much more efficiently than the kernel manages OS thread context switches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a5f70da-a6f2-4b6f-91be-9835cf9562b7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the trade-offs of using PyPy versus CPython for high-performance applications?', N'Senior', N'PyPy uses Just-In-Time (JIT) compilation to significantly accelerate execution speed for long-running processes compared to CPython. However, it often has higher memory consumption, longer startup times, and limited compatibility with C-extension modules that rely on CPython-specific internal APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
