INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'081b0368-2177-46ca-b4fd-983b3ebc6222', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of the ''target'' property in Webpack configuration?', N'Middle', N'The target property tells Webpack which environment the bundle will run in, such as web or node. This ensures that Webpack uses the correct standard library and handles built-in modules appropriately for that specific runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c378b168-efe4-41fe-91b8-983cee313ede', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the significance of using environment variables versus hardcoding configuration values?', N'Intern', N'Hardcoding configuration makes it difficult to change settings across different environments like development, testing, and production. Environment variables allow you to inject environment-specific settings securely without modifying the application logic or exposing sensitive credentials in your project files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8070aeb2-db43-4f1e-ad85-984241c3f4b5', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the role of the ''self'' keyword in Ruby?', N'Fresher', N'The ''self'' keyword refers to the current object that is receiving a method call. Its value changes depending on the context, such as whether it is inside a class definition, an instance method, or a singleton method, helping to identify the object currently in scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'138bdc16-577a-4079-922e-9847d498ccdd', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the function of the x-cloak directive?', N'Fresher', N'The x-cloak directive is used to hide Alpine elements until the framework has finished initializing. This prevents the ''flash of unstyled content'' where the user might see raw HTML template tags before the JavaScript processes them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30a03033-d5f4-4d29-9406-9848154acc2a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s router perform path matching, and what are the performance implications compared to a regex-based router?', N'Senior', N'Echo uses a radix tree (or prefix tree) for routing, which provides O(k) lookup time where k is the length of the path. This is significantly more efficient than regex-based routers, which scale linearly with the number of routes, making Echo highly performant for applications with hundreds of endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d14e866-4fbd-4cbd-b973-9848b8bc47b3', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is Qwik City?', N'Junior', N'Qwik City is the meta-framework built on top of Qwik. It provides features like file-based routing, layout management, and data loading capabilities similar to other full-stack frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66f6544e-5a69-468d-8f92-984a4bd236de', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When faced with a trade-off between using a well-known library versus building a custom solution, what factors should you consider?', N'Intern', N'Consider the maintenance burden, development time, and the specific needs of the project. A library saves time but adds a dependency, while a custom solution offers full control but requires more effort to build and support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40639f9d-99a8-42ec-9b86-984d37de9150', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between Query parameters and Path parameters in Gin?', N'Junior', N'Path parameters are part of the URL structure itself, defined in the route pattern, while query parameters are appended to the end of the URL after a question mark. Gin provides distinct methods for accessing each, specifically Param for paths and Query for query strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'338e4faf-fbf7-4ab6-8688-985332a9bcd1', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the significance of the ''Request Delegate'' in the middleware pipeline?', N'Middle', N'A Request Delegate is a function that processes an HTTP request and represents the next step in the middleware chain. By calling this delegate, a middleware can pass control to the rest of the application or choose to short-circuit the request by not calling it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
