INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4eda8b3-e0e9-408d-b280-985840059682', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is meant by event delegation in jQuery?', N'Fresher', N'Event delegation allows you to attach a single event handler to a parent element that will trigger for all its current and future child elements. This is highly efficient for elements added to the DOM dynamically after the initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef39c6c0-34a4-47ff-a58e-985997996f08', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is cache invalidation often considered the hardest problem in distributed systems?', N'Senior', N'Maintaining cache consistency across distributed nodes requires complex coordination, such as two-phase commits or distributed locking, which severely impact latency and availability. Achieving strong consistency typically forces a trade-off against the latency benefits that caching is intended to provide in the first place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
