INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'170111df-c781-45ba-a59b-985cbffe2bcf', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it important to use a unique ''key'' attribute when rendering lists?', N'Middle', N'The key attribute provides a unique identifier for each element, allowing Vue''s diffing algorithm to accurately track nodes. Without it, Vue uses an in-place patch strategy that can lead to bugs with stateful components or incorrect DOM reordering during list updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13a7b09b-4b38-4127-9fde-985d5081d9d8', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is the finalizer pattern considered a ''last resort'' mechanism in C# resource management?', N'Senior', N'Finalizers rely on the Garbage Collector to identify unreachable objects, which introduces non-deterministic latency in resource cleanup. Objects with finalizers are promoted to the finalization queue and require at least two GC cycles to be reclaimed, creating unnecessary memory retention and pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
