INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4b09064-0593-426e-a987-986956b3d7f2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do memory alignment and padding affect C structs?', N'Middle', N'Compilers often insert invisible padding bytes between struct members to ensure that each member starts at a memory address aligned with its size, which improves CPU access speed. This increases the total size of the struct, and developers can sometimes reorder members to minimize this padding overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75c22517-64bb-49ae-9ef5-986b8d0be4eb', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the ''mongos'' process in a sharded cluster?', N'Middle', N'The ''mongos'' process acts as a query router, providing an interface between client applications and the sharded cluster. It determines where data is located by querying the config servers and directs requests to the appropriate shard, abstracting the complexity of sharding from the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'877bf5b4-a088-42a3-828c-986b9ac5e9fe', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is it important to use asynchronous logging and monitoring?', N'Middle', N'Asynchronous logging prevents the application from blocking while waiting for log write operations to complete, which could otherwise hurt performance. It ensures that monitoring and logging overhead does not negatively impact the main execution path of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a7f5cc9-f234-44f4-a396-986c0f15bfe8', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi’s design influence the memory footprint of a high-throughput backend?', N'Senior', N'By minimizing allocations during the routing process and avoiding reflection, Chi keeps the heap pressure low. Its reliance on standard net/http interfaces and efficient path traversal ensures that request overhead remains constant regardless of the number of registered routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'942bf2f2-6ae0-4534-afa3-986e79f202c8', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What does the function zip() do?', N'Intern', N'One of the less common functions with beginners, zip() returns an iterator of tuples. list(zip([''a'',''b'',''c''],[1,2,3])) [(''a'', 1), (''b'', 2), (''c'', 3)] Here, it pairs items from the two lists, and creates tuples with those. But it doesn''t have to be lists. list(zip((''a'',''b'',''c''),(1,2,3))) [(''a'', 1), (''b'', 2), (''c'', 3)]', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
