INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc390fd8-7743-4a26-b6ba-98721099b4cf', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is data integrity?', N'Intern', N'Data integrity refers to the overall accuracy, completeness, and consistency of data stored in a database. It is maintained through the use of constraints, keys, and validation rules to ensure data remains reliable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ce23c58-7554-4f37-93a9-98721a5316a8', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust achieve zero-cost abstractions?', N'Middle', N'Zero-cost abstractions mean that features like iterators, closures, and generics generate machine code as efficient as hand-written code for the same task. The compiler performs aggressive inlining and monomorphization, removing the overhead of the abstraction layer during the optimization process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ce3900a-3b37-4d4f-a446-98739f78e979', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When is it appropriate to use a graph database?', N'Middle', N'Graph databases are ideal for modeling highly interconnected data where relationships are as important as the entities themselves. They provide superior performance for traversing complex paths, such as social networks or recommendation engines, which would require expensive join operations in SQL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af64a645-f020-4f6a-8a92-98786b67b5fd', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Events and Listeners in Laravel?', N'Fresher', N'Events and Listeners provide a simple observer implementation, allowing you to subscribe and listen for various events in your application. This helps in decoupling the core logic from side-effects, such as sending an email after a user registers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31873c5f-ee9c-48e9-a630-9878a37c281c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS support the ''Hexagonal Architecture'' (Ports and Adapters) pattern?', N'Senior', N'NestJS supports this by defining ''Ports'' as interfaces or abstract classes and ''Adapters'' as infrastructure providers that implement those interfaces. By injecting these abstractions into business services, the core domain logic remains isolated from external concerns like database drivers, API frameworks, or third-party SDKs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5fda940-63e7-4443-907b-987a01b88869', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the role of ''Lit-HTML'' as a standalone library versus ''Lit'' as a full component framework.', N'Senior', N'Lit-HTML is the engine that handles efficient DOM updates via template literals, while Lit is the framework that adds the component lifecycle, reactive properties, and attribute management. You can use Lit-HTML independently for lightweight DOM manipulation without the overhead of full component classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c2e2dad-5d58-4fde-a378-987a0926751f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you test routes in a Chi-based application?', N'Middle', N'Because Chi uses the standard http.Handler interface, you can use the standard library''s ''net/http/httptest'' package. You simply pass the router instance to the test recorder, allowing for full integration testing without needing a running server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'476e7bca-6e2e-4edc-8644-987a5fe505d6', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do Query Filters differ from Key Condition Expressions, and why does this matter for efficiency?', N'Senior', N'Key Condition Expressions are evaluated at the storage engine level to locate the data, making them highly efficient. Query Filters are applied after the data is retrieved from storage but before the result is returned to the client, meaning they do not reduce the amount of data read from the disk. Consequently, filters do not save on capacity consumption and can lead to inefficient resource usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39004bf7-1944-4b9f-a95b-987ea1e16fc5', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a Callback in Rails?', N'Fresher', N'Callbacks are methods that get called at certain moments of an object''s lifecycle, such as before, after, or around the saving or destroying of a record. They allow you to trigger logic, like sending a welcome email after a user is created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34686f4b-ab63-49f9-bca8-9883cfa2e4b0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the decision to build a custom solution versus using an existing SaaS product?', N'Junior', N'Choose a SaaS product if the functionality is a commodity that does not provide a competitive advantage to your business. Build a custom solution only if the requirement is a core differentiator that requires deep integration or specific logic not offered by off-the-shelf tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fe561ea-33ff-41cb-8925-988ad9190421', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Repeatable Read'' isolation level work in InnoDB?', N'Middle', N'Repeatable Read is the default isolation level in InnoDB, which ensures that if a transaction reads data multiple times, the results remain consistent. It achieves this using Multi-Version Concurrency Control (MVCC) to provide a consistent snapshot of the data at the start of the transaction, preventing non-repeatable reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68ec6574-d61e-4961-898e-98912df6487a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a request body in Fiber?', N'Fresher', N'The request body is the data sent by the client, often in POST or PUT requests, typically formatted as JSON or form data. Fiber provides utility methods to access and parse this raw data into usable formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d5f43ec-dd86-4fb8-873a-98975c756190', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you handle global scope pollution in Sass?', N'Senior', N'Global scope pollution is mitigated by adopting the @use rule, which forces explicit namespacing for all imported modules. Additionally, keeping variables, mixins, and functions within specific feature folders and using underscores for partials helps maintain a clean, organized global namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
