INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef8634b1-a3ca-4ad6-a59d-98984acbfe86', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle multipart form data compared to traditional Node.js body-parsers?', N'Middle', N'Hono uses standard Web API-compliant methods to process multipart data, avoiding the need for heavy legacy Node.js dependencies like ''multer''. This ensures that form processing is consistent regardless of the underlying runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bed17ad0-174b-4885-8b46-989a38b13a2c', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js maintain state when a user navigates between pages?', N'Middle', N'By default, Alpine state is reset on page load. To maintain state across navigation, you must implement persistence strategies such as storing data in localStorage or sessionStorage, which can then be initialized in the component''s x-data or via a custom Alpine plugin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
