INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5215e13-618f-40ec-8937-989fee9186cc', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte manage CSS scoping?', N'Fresher', N'Svelte automatically scopes CSS styles to the component they are defined in. It accomplishes this by adding unique classes to elements, ensuring that styles do not leak out or affect other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e9b03b4-4e9e-4f99-99e2-98a38c1c27dc', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a table partition and a table inheritance?', N'Middle', N'Partitioning splits a large table into smaller, more manageable physical pieces while remaining logically a single table, improving query performance through partition pruning. Inheritance allows a child table to inherit columns and constraints from a parent, but it does not automatically provide the same performance benefits for large-scale data distribution as native partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33ba24b8-8261-4cac-822e-98a3ed91e12a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ''formaction'' and ''action'' in a form?', N'Middle', N'The ''action'' attribute defines the default URL where the form data is sent when submitted. The ''formaction'' attribute can be applied to individual submit buttons to override the default action, allowing different buttons to send data to different endpoints. This is useful in scenarios where a form has multiple distinct actions, like ''Save'' versus ''Preview''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72cd41e0-0b7b-4ae2-a0e0-98a422fc2bde', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is dependency injection?', N'Intern', N'Dependency injection is a pattern where an object receives its dependencies from an external source rather than creating them itself. This makes code more modular and easier to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be80989f-b247-451b-9d91-98a71f682de7', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do distributed messaging systems ensure high availability during a leader node failure?', N'Senior', N'Systems use a consensus algorithm or a cluster manager to detect leader failure and promote a follower to a leader. Synchronized replicas ensure that the new leader is caught up with the state of the old leader to prevent data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
