INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70a45378-a817-4b89-abe5-98a903a28c39', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the benefit of using Compiler Passes in a Symfony application?', N'Senior', N'Compiler Passes allow you to manipulate the Service Container definition before the container is compiled and cached. They are essential for advanced features like tag-based service discovery, allowing you to automatically register services that implement a specific interface into a collector service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'515f712c-bf03-4ec9-b452-98a9708c5b35', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the core architectural difference between Fiber and standard net/http in Go?', N'Middle', N'Fiber is built on top of Fasthttp, which is designed for high performance by minimizing memory allocations and reusing objects. Unlike the standard library which creates a new request object for every connection, Fasthttp utilizes a worker pool model to reduce garbage collection overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b472a2a-fbd0-44eb-9b3b-98ab1080b29c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Is Astro suitable for building a Single Page Application (SPA)?', N'Fresher', N'Astro is primarily designed for multi-page websites and content-heavy sites. While you can build SPAs, it is not optimized for that pattern compared to frameworks like React or Next.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0733466d-cdac-4fa4-a258-98acad48443f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the ''StringBuilder'' class and why is it preferred over ''String'' for concatenation?', N'Junior', N'String objects in Java are immutable, meaning every concatenation creates a new object in memory. StringBuilder is mutable, allowing modifications without creating multiple intermediate objects, making it more memory-efficient for frequent string manipulations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66181666-b398-463f-a270-98b1cbf294d5', N'a2838158-7305-480a-b22b-4dc35776b400', N'Compare the use of bloom filters versus traditional hash sets for membership testing in a distributed system.', N'Senior', N'Bloom filters are space-efficient, probabilistic data structures that can return false positives but never false negatives, making them ideal for checking membership in large, memory-constrained datasets. In contrast, hash sets provide absolute accuracy but require significantly more memory, which may be prohibitive for large-scale distributed caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c053c7b9-9771-461d-b4a4-98b27aed7394', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Can you use middlewares in Fastify?', N'Intern', N'Yes, Fastify supports Express-style middleware through a specific plugin. However, it is generally recommended to use Fastify hooks instead, as they are more performant and better integrated into the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
