INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8719c285-1a3d-460a-80ad-98bcc76e7416', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'In a distributed environment, why should Flask''s session be stored in an external cache like Redis instead of client-side cookies?', N'Senior', N'Client-side cookies are limited by size (4KB) and can be tampered with by clients if the secret key is leaked. Moving sessions to a server-side store like Redis allows for larger data storage, centralized session management, and the ability to revoke sessions globally if a security breach occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
