INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'533b046d-1261-4c5d-866a-98cc48edf71a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do macros in Rust differ from functions?', N'Middle', N'Macros are expanded into code before the compiler performs type checking, allowing for metaprogramming and syntactic extensions. Functions are compiled as discrete units of logic; macros provide more flexibility by being able to accept a variable number of arguments and manipulate the syntax tree directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6a4553b-d841-4dbc-a47f-98cda1a482cd', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does ''Quorum'' consensus improve fault tolerance?', N'Senior', N'Quorum requires a minimum number of nodes to participate in an operation to ensure system integrity. By requiring (N/2 + 1) nodes, the system can tolerate up to (N/2 - 1) failures while still guaranteeing that the latest data is available and conflicts are minimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
