INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0418d72e-9bf1-43c9-a66a-98e8e766742f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage the ''dirty checking'' or reactivity detection for arrays and objects?', N'Senior', N'Alpine uses a Proxy-based reactivity system or property observers to track mutations in objects and arrays. When a property is updated, it triggers a dependency tracking system that identifies which DOM nodes need to be updated. This ensures that the DOM remains in sync with the underlying data model without requiring a full re-render of the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
