INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f301d88-2039-4cc1-9445-9905929a59e8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the role of ''Metatypes'' in Swift meta-programming?', N'Senior', N'Metatypes allow a program to refer to a type itself as a value, enabling the dynamic creation of instances or access to static members. By using the .self syntax, developers can pass types as arguments to generic functions or factories, facilitating flexible architectural patterns. This is a powerful feature for dependency injection and reflection-like behavior in a strictly typed language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd230288e-b6a6-4245-838d-9906103e4117', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does the ''main'' package signify?', N'Intern', N'The ''main'' package is a special package that tells the Go compiler that the directory should be compiled as an executable program rather than a shared library. It must contain the ''main'' function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'854e8808-916a-4a62-9c78-99087712fd76', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the Django template context, and how can context processors be used?', N'Middle', N'The template context is a dictionary-like object mapping variable names to values for rendering in templates. Context processors are functions that add global variables to every template context automatically, which is useful for values like user information or site settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3da46fcd-615a-4ab4-bbe1-9908ca6a86e3', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Are Go functions pass-by-value or pass-by-reference?', N'Junior', N'Go is always pass-by-value. When you pass a variable to a function, the function receives a copy of the data; if you need to modify the original data, you must pass a pointer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c73e8718-8b7f-4fbc-89a8-990dd6b45fa3', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s asset pipeline optimize images compared to traditional manual optimization workflows?', N'Senior', N'Astro provides an integrated image service that automatically handles resizing, format conversion, and attribute generation at build or request time. This reduces human error and ensures that images are served in modern formats like WebP or AVIF with correct dimensions for the viewport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c06192a4-5afe-4392-b750-990f59a3f694', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Discuss the trade-offs of using Rails Engines for modularity versus a full microservices architecture.', N'Senior', N'Rails Engines provide logical separation within a single codebase, making them easier to manage and deploy while sharing the same memory space. Microservices offer true fault isolation and independent scalability but introduce significant operational complexity in terms of network latency, distributed tracing, and data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e31653d-c103-48e2-b42c-991065f8ddd0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does the Nest logger differ from the standard console.log() and when would you prefer one over the other?', N'Fresher', N'The NestJS Logger provides additional features compared to console.log(). It includes context information, supports log levels such as (log, fatal, error,warn, debug, and verbose), and can be customized. Use console.log() for quick debugging or simple logging needs. Use NestJS Logger when you need more control over your logs, such as in larger or production applications. It helps in filtering logs based on levels and provides context, making it easier to trace the source of the log. On how the Nest logger is implemented checkout Nestjs Documentation', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaaabfb3-9aa3-414c-b02e-99147a18eaaf', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the main advantage of using containerization like Docker?', N'Middle', N'Containerization packages an application and its dependencies into a single unit, ensuring it runs consistently across different computing environments. This eliminates the ''it works on my machine'' problem and simplifies the deployment process by providing an isolated, immutable runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75b9fbbf-6ea6-451e-99d3-9915d46bb2a6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s ''ErrorHandler'' component improve debugging?', N'Middle', N'The ErrorHandler converts standard PHP errors into exceptions, providing a unified and detailed way to manage failures. It offers features like stack traces, variable inspection, and integration with logging, which significantly reduces the time required to diagnose issues in development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0ace836-d99b-44eb-80de-99187749a313', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the impact of ''async/await'' on error handling and readability compared to raw Promises.', N'Senior', N'Async/await enables writing asynchronous code that looks and behaves like synchronous code, improving readability and maintainability. It simplifies error handling by allowing the use of standard try-catch blocks, whereas raw Promises require chained .catch() methods which can lead to nested or fragmented error logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efb545ba-3c1f-4d80-aed5-9919207c6c8a', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is ''write amplification'' in the context of database performance?', N'Middle', N'Write amplification occurs when the physical amount of data written to the storage exceeds the logical amount of data requested by the application. This is common in databases using log-structured merge trees and can lead to storage and performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6906dcaa-5d6f-4914-96f1-9919a9be9850', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is cache invalidation considered one of the hardest problems in computer science?', N'Middle', N'Invalidation is difficult because it requires perfect synchronization between the cache and the primary data store under race conditions. If the invalidation signal fails or is delayed, the system may serve stale data indefinitely, leading to inconsistencies that are hard to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab917ac7-9af9-4ba9-8f88-9919e10392a9', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'When would you choose a NoSQL database over a relational (SQL) database?', N'Middle', N'NoSQL databases are often preferred when handling massive volumes of unstructured or semi-structured data, or when high horizontal scalability and rapid development speed are prioritized over ACID compliance. They are ideal for use cases involving flexible schemas and high write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
