INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bea94174-1691-410b-9bea-991a2e6ce165', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the MVCC (Multi-Version Concurrency Control) mechanism improve performance?', N'Middle', N'MVCC allows multiple versions of a data row to exist simultaneously, enabling readers to access an older, consistent version of data without being blocked by writers. This significantly increases concurrency as read operations do not block write operations and vice-versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
