INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3898a919-6646-41c7-b876-992a03d7e79a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Describe the impact of ''Streaming'' on the user experience in a React-based SSR application.', N'Senior', N'Streaming allows the server to send the HTML to the client in chunks, starting with the static shell and followed by dynamic components as they resolve. This prevents the browser from waiting for the entire page to render, drastically improving Time to First Byte and perceived performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
