INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f55cba0-c6ea-48e2-8d0d-992b591fbe20', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between an ''index'' and a ''document'' in Elasticsearch?', N'Middle', N'A document is the basic unit of information represented in JSON format, while an index is a logical namespace that groups related documents together. You can think of an index as a collection of documents that share the same configuration and mapping settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'885dc84a-76ec-44da-94bb-992cdffd05dc', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do Fiber''s body parsers handle incoming request data?', N'Middle', N'Fiber''s body parsers automatically unmarshal JSON, XML, or form data into structures or maps based on the Content-Type header. This reduces boilerplate code but requires developers to be mindful of input validation and potential injection risks if the data is not sanitized after parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc6c7101-097b-4a7a-ad18-992db0af4a46', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is an HTTP verb?', N'Intern', N'An HTTP verb, or method, indicates the desired action to be performed on a resource. Common verbs used in Express include GET for retrieving data, POST for creating data, PUT for updating, and DELETE for removing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63fd2283-2bd3-4dc3-9cfe-992f583a5de0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a mount point in Chi?', N'Intern', N'A mount point allows you to attach a sub-router to a specific path prefix on the main router. This is a powerful feature for modularizing large applications into smaller, manageable components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2aff800f-51d6-4729-820a-992fb15c41b6', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of ''string.Intern'' in C#?', N'Middle', N'String interning is a mechanism that stores only one copy of each distinct string value in a pool. It reduces memory usage when an application has many identical strings, though it incurs a performance cost for string creation and lookup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'257239db-b911-47b2-9801-9930ba16cf52', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does the $nextTick magic property do?', N'Junior', N'The $nextTick property waits for the current DOM update cycle to complete before executing the provided code. It is useful when you need to interact with an element after Alpine has finished updating its state in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afbc8a38-8e5c-4090-a1ea-9931330c4d6b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the concept of ''Progressive Hydration'' vs Qwik''s ''Resumability''.', N'Senior', N'Progressive hydration still requires the framework to eventually hydrate parts of the application, often leading to a ''jank'' or delayed interactivity. Resumability treats the application as a snapshot that is paused after server-side rendering and resumed exactly where it left off, eliminating the hydration phase entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33c7ab9d-1a1d-49dc-981e-9933a0324065', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the ''Sidecar'' pattern improve microservices management?', N'Middle', N'The sidecar pattern attaches a separate container to the main application container to handle peripheral tasks like logging, security, or proxying. This allows developers to keep application code focused on business logic while offloading infrastructure concerns to the sidecar.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a3a52f7-2e0e-4c4d-bd09-9933c5ca843b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot''s auto-configuration work under the hood?', N'Middle', N'Auto-configuration uses the @EnableAutoConfiguration annotation, which triggers the SpringFactoriesLoader to scan for classes in the classpath. It then applies conditional annotations, such as @ConditionalOnClass or @ConditionalOnMissingBean, to determine whether to instantiate specific beans based on the presence of libraries and existing configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1937ae8-e5ec-49b2-9c7c-9933d1599e32', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the concept of ''lazy evaluation'' in Django QuerySets.', N'Middle', N'QuerySets in Django are lazy, meaning they do not hit the database until you explicitly evaluate them, such as by iterating over them or calling a function like len(). This allows you to chain multiple filters and exclusions without executing redundant database queries until the exact moment the data is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1727455-59fb-4173-ab94-9934644771f4', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is caching often more effective for read-heavy workloads?', N'Middle', N'Caching reduces the latency of read operations by keeping data in memory, which is significantly faster than disk-based databases. In write-heavy workloads, the overhead of maintaining cache coherence and updating the cache during every write operation can negate the performance benefits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09678b9b-fc0d-4ca2-a490-99347d606798', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''url_for'' function?', N'Junior', N'The ''url_for'' function generates a URL for a specific function name, rather than hardcoding paths. This is beneficial because if you change the URL structure in your routes, the application will automatically update all generated links to point to the new location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aa7b456-e6bb-4a58-9850-9936495fc472', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'When is it appropriate to use a ''Saga'' pattern instead of distributed transactions?', N'Senior', N'The Saga pattern is used in microservices architectures to manage long-running business processes that span multiple databases without global locks. It breaks a transaction into a series of local transactions with compensating actions, providing eventual consistency instead of the strict atomicity of traditional distributed transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
