INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b57aac26-5e39-4439-82eb-99380d41767a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When tasked with estimating a project where the team is unfamiliar with the tech stack, what is your strategy?', N'Middle', N'I would start by benchmarking a small ''proof of concept'' to validate core assumptions and measure how the team learns the new tools. I would then adjust the project timeline to include a ramp-up phase, ensuring the team''s velocity reflects their actual progress as they gain proficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dc85176-5692-4ff1-8304-9938184f8e2b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra''s LSM-tree storage architecture differ from a B-Tree used in traditional relational databases?', N'Middle', N'LSM-trees use sequential writes to an in-memory structure called a Memtable, which is later flushed to immutable SSTables on disk, making write operations extremely fast. In contrast, B-Trees involve frequent random disk I/O to maintain the tree structure, which optimizes for read speed at the expense of write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23570f08-6693-4299-934a-993c1ec94315', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary benefit of Svelte being a compiler rather than a framework?', N'Middle', N'Because Svelte compiles code into highly optimized vanilla JavaScript, it eliminates the overhead of a virtual DOM at runtime. This results in smaller bundle sizes and improved performance since the framework does not need to perform complex diffing operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3410b57-27b5-41ae-85ed-993c879d5d6f', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary difference between the Primary Key and Unique constraints in a SQL database?', N'Junior', N'A Primary Key uniquely identifies each record in a table and cannot contain null values, with only one allowed per table. A Unique constraint also ensures all values in a column are different, but it allows for a single null value and multiple unique constraints can be applied to a single table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f1ae258-3c80-481e-86df-993de13c177e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the concept of method visibility in Ruby.', N'Junior', N'Ruby uses public, protected, and private access modifiers to control how methods are called. Public methods are accessible by anyone, protected methods can be called by instances of the same class or subclasses, and private methods can only be called within the object itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f1d0b88-eb71-48a0-8d7e-9944d6c4ec23', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus achieve faster startup times and lower memory footprint compared to traditional JVM frameworks?', N'Senior', N'Quarkus performs build-time metadata processing and dependency injection wiring, moving the heavy lifting from runtime to the build phase. By utilizing GraalVM native image generation, it compiles the application into a standalone executable that excludes unused classes, significantly reducing memory consumption and start-up latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
