INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c04f6a0-10b6-43ef-97a8-994c0898ea86', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a CDN and how does it improve performance?', N'Middle', N'A Content Delivery Network is a geographically distributed group of servers that cache content close to end-users. It improves performance by reducing the physical distance data must travel, thereby decreasing latency and offloading traffic from origin servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82779978-5235-4cce-bc74-994da0b988cd', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between High Availability and Fault Tolerance?', N'Middle', N'High Availability focuses on minimizing downtime through redundancy and failover mechanisms. Fault Tolerance refers to the ability of a system to continue operating properly even when one or more of its components fail, often without noticeable interruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fcfc1c4-b71d-43e4-9234-99506e6ccce2', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to implement pagination when displaying a list of thousands of items in a web application?', N'Fresher', N'Loading thousands of items at once can overwhelm the client''s browser memory and lead to slow page load times. Pagination breaks the data into smaller, manageable chunks, significantly improving initial load speed and responsiveness. It provides a better user experience by allowing the user to browse through content incrementally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51d930c8-b4fa-4b69-86a4-9951f974a0dc', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is ''Cache Avalanche'' and how can it be avoided?', N'Middle', N'Cache avalanche happens when a large number of keys expire at the same time or a cache node fails, causing a surge of traffic to hit the primary database. This can be prevented by adding random jitter or expiration offsets to cache keys to ensure they do not all expire simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'236da2bf-2f5c-4e47-a3bd-995302d85eb3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra maintain high availability during writes?', N'Junior', N'Cassandra achieves high availability by allowing writes to occur even if some nodes are down, provided the requested consistency level can be met by the available replicas. Data is replicated across the cluster, ensuring that multiple nodes have the same information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e483d946-889b-4d0f-889e-9954fd93073a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle election cycles in a Replica Set when a Primary node fails?', N'Senior', N'When a Primary fails, secondary nodes initiate an election via a heartbeat mechanism. Candidates request votes from other nodes; a node becomes the new Primary only if it receives a majority of votes, ensuring that only one primary exists and preventing split-brain scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aced2c33-5514-4800-966e-995666f92c26', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript’s ''Control Flow Analysis'' improve developer experience compared to standard JavaScript?', N'Senior', N'Control flow analysis tracks the possible types of a variable at different points in the code based on narrowing operations like typeof, instanceof, and equality checks. This allows the compiler to understand exactly what a variable is at any given scope, reducing the need for explicit type casting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a37b6c0b-0f40-4e5e-8560-995c3e61bb3a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''this'' keyword?', N'Fresher', N'The ''this'' keyword refers to the current instance of the class. It is commonly used to distinguish between class fields and method parameters that have the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e4624c4-e5c6-456d-87f3-9960ad2e73a3', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is an ORM and why does Django use one?', N'Intern', N'An ORM, or Object-Relational Mapper, is a programming technique that allows developers to interact with a database using object-oriented code instead of writing raw SQL queries. Django uses an ORM to make database operations more intuitive, secure against injections, and portable across different database engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48bb7773-4af6-43f1-8e16-9960c7ea81c5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does it mean for PostgreSQL to be object-relational?', N'Intern', N'It means PostgreSQL is primarily a relational database that stores data in tables, but it also includes object-oriented features. These include inheritance, table functions, and the ability to define custom data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e84bf6f1-6b59-4380-9e90-9961dc58ebbe', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are server-sent events', N'Intern', N'Server-sent events (SSE) is a server push technology enabling a browser to receive automatic updates from a server via HTTP connection without resorting to polling. These are a one way communications channel - events flow from server to client only. This has been used in Facebook/Twitter/X updates, stock price updates, news feeds etc.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbbf207c-15a0-456b-b73f-9964a8e2e73c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating, how do you handle tasks that are dependent on other team members?', N'Fresher', N'I would communicate with the dependent parties to understand their availability and potential bottlenecks. I would then build those dependencies into my estimate, ensuring that the timeline reflects the necessary wait times or hand-off periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0c98726-0085-4544-aa78-9965993ae98d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the role of the Arbiter in Actix and why it is critical for scalability.', N'Senior', N'An Arbiter is a dedicated thread running an event loop that manages actors and their mailboxes. By distributing actors across multiple Arbiters, Actix can leverage multi-core architectures effectively while ensuring internal actor state remains thread-safe and isolated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83047156-f7ff-44e7-a270-99664528dfbb', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Is Chi suitable for building non-RESTful APIs, like gRPC-Web or WebSockets?', N'Middle', N'Yes, because Chi is simply a router that works with the standard HTTP request/response cycle, it can serve as a base for any HTTP-based communication. You can easily plug in WebSocket upgrader handlers or gRPC-Web gateways into Chi routes just as you would any other standard handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
