INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c648bed2-414e-4279-aefe-996aab9a1b28', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the concept of ''Covered Queries'' and why they are performant.', N'Senior', N'A covered query occurs when all fields requested by a query are present in a single index. Because the database can satisfy the request entirely from the index structure without loading the actual document from disk, it significantly reduces I/O and CPU overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a506744a-3c1c-446d-beca-996af4caf16b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s lightweight design influence the security posture of an application compared to ''batteries-included'' frameworks?', N'Senior', N'Hono’s minimal surface area reduces the attack vector by excluding unnecessary features and dependencies that often lead to vulnerabilities in larger frameworks. Security is achieved by design through explicit middleware composition, which forces developers to be intentional about authentication, rate limiting, and CORS, rather than relying on black-box defaults.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
