INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d8f0a5d-2145-403d-a31f-9983955dc19a', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the advantages and disadvantages of using CSS preprocessors like SASS or PostCSS?', N'Middle', N'Preprocessors offer powerful features like nesting, mixins, and functions that make CSS easier to maintain and scale in large projects. However, they introduce a build step that can slow down development and complicate debugging since the generated CSS differs from the source. Modern CSS features have rendered some preprocessor functions redundant, reducing the necessity of these tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'367a16a0-a8b8-47af-a195-99854553c7e4', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the trade-off between using synchronous REST vs. asynchronous messaging in microservices?', N'Middle', N'Synchronous REST provides immediate feedback and is simpler to implement but creates tight coupling and potential cascading failures. Asynchronous messaging improves system resilience and decoupling but introduces complexity regarding message ordering, delivery guarantees, and eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09c83a06-0df6-4d28-b832-9985a18bf90a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the significance of the ''this'' parameter in TypeScript functions?', N'Middle', N'The ''this'' parameter allows you to explicitly define the expected context of a function. This helps the compiler verify that the function is being called with the correct context, preventing common errors related to how the ''this'' keyword is bound in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f11793b3-319b-4818-98e2-998627ea32dd', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''Ember.js is opinionated'' mean?', N'Junior', N'It means the framework has a preferred way of solving problems and structuring code. While this requires learning specific patterns, it ensures consistency across different projects and reduces decision fatigue for the development team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ffa145c-8e9f-45c4-a57a-9988edb83db8', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is Spring Data JPA?', N'Intern', N'Spring Data JPA is a part of the broader Spring Data project that simplifies the implementation of data access layers. It provides abstractions to interact with relational databases by reducing the amount of boilerplate code needed for common database operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22368eb0-7d03-446a-b3fd-998aa638903e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite optimize assets for production?', N'Fresher', N'Vite optimizes assets by minifying JavaScript and CSS, splitting code into smaller chunks for better caching, and applying content hashes to filenames for cache busting. These optimizations ensure the final application loads quickly for users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fedbb1c9-dde4-44d3-8a14-998bafe336bb', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''tabindex'' attribute, and how does it influence accessibility?', N'Middle', N'The ''tabindex'' attribute allows developers to control the keyboard focus sequence of elements on a page. A positive value forces a specific order, while ''0'' puts the element in the natural tab order, and ''-1'' removes it from the tab sequence while keeping it focusable via JavaScript. Improper use of positive tab indexes can break the intuitive navigation flow for keyboard-only users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd65bf0b-d3f0-4b15-b235-998bb545d122', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Routes in Laravel?', N'Intern', N'Routes are the entry points for the application. They map incoming URLs to specific Controller actions or Closures, determining how the application should respond to a request from a user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d812f7e-e9b3-428e-846b-998cfb3c2497', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is JVM and is it platform independent?', N'Intern', N'Java Virtual Machine (JVM) is a specification that provides runtime environment in which java bytecode(.class files) can be executed. The JVM is the platform. The JVM acts as a "virtual" machine or processor. Java''s platform independence consists mostly of its Java Virtual Machine (JVM). JVM makes this possible because it is aware of the specific instruction lengths and other particularities of the platform (Operating System). The JVM is not platform independent. Java Virtual Machine (JVM) provides the environment to execute the java file(. Class file). So at the end it''s depends on kernel and kernel is differ from OS (Operating System) to OS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb52e528-f068-4f4c-9193-998e20f3fd70', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the primary purpose of the ASP.NET Core framework?', N'Intern', N'ASP.NET Core is a cross-platform, high-performance, open-source framework for building modern, cloud-enabled, Internet-connected applications. It allows developers to create web apps, APIs, and microservices that run on Windows, Linux, and macOS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a412ea0-c9f8-4769-b4c5-999272618912', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs in choosing between a multi-region deployment and a single-region deployment?', N'Middle', N'A multi-region deployment provides low latency for a global user base and superior disaster recovery capabilities. The trade-off is the significant increase in architectural complexity, data synchronization challenges, and higher operational costs compared to a simple single-region setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8943b1b-77d3-49d8-b361-999502baf03d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When building an API, what are the trade-offs between a RESTful architecture and using GraphQL?', N'Middle', N'RESTful APIs are predictable and leverage standard HTTP caching mechanisms, making them easy to implement and cache at the edge. GraphQL provides flexibility by allowing clients to request exactly the data they need, which reduces over-fetching and under-fetching, but it shifts the complexity of query execution and security validation to the server. You should choose REST for simple, resource-oriented services and GraphQL for complex frontend applications that require precise data shaping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09464f46-870b-404d-8d72-99971324fe84', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does database partitioning differ from indexing?', N'Middle', N'Partitioning divides a large table into smaller, more manageable physical pieces based on a specific key, often to improve maintenance and query performance for time-series data. Indexing, by contrast, creates a secondary structure to speed up data retrieval without changing the table''s physical storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1c18d94-74f9-42ba-9d64-999a5aaf941c', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it important to disable unused ports and services on a server?', N'Middle', N'Every open port and running service represents a potential attack surface. Disabling unnecessary components reduces the number of entry points available for exploitation, effectively minimizing the system''s overall attack vector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed210eaa-432b-473f-a546-999b88d72848', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it important to use Echo''s custom Context within middleware?', N'Middle', N'Using the custom Context ensures that the middleware has access to Echo-specific features like data stores and helper methods. It maintains compatibility with the framework''s design, ensuring that downstream handlers receive the correctly initialized and augmented request data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e1e0682-4da8-42d7-b661-999f2dd66f86', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is it important to use type definitions for external JavaScript libraries?', N'Intern', N'Since external libraries are often written in plain JavaScript, TypeScript does not know their internal structure. Using type definition files provides the compiler with the necessary information to offer autocompletion and error checking for those libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b05e926-0bed-4b0a-9e4e-99a2cb527fa9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the trade-offs of using Litestar''s built-in message-based exception handling.', N'Senior', N'Litestar allows for global exception handlers that map specific errors to consistent HTTP responses, ensuring API uniformity across the entire system. The trade-off is a slight increase in abstraction, which requires developers to thoroughly understand the exception hierarchy to avoid leaking internal error details to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e1112dd-7e13-4927-9d7d-99a438f554d6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ''Index Cardinality'' affect query optimizer decisions?', N'Senior', N'High-cardinality columns have many unique values, making them ideal for indexing because they allow the optimizer to narrow down results quickly. Low-cardinality columns are often ignored by optimizers, as a full table scan is usually cheaper than performing an index lookup that retrieves a significant percentage of the dataset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b013fd82-fad5-4356-b686-99a4853e7c0c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the advantage of using Form Requests for validation?', N'Middle', N'Form Requests allow you to encapsulate validation logic into dedicated classes, keeping your controllers thin and focused on business logic. They automatically handle authorization and validation, throwing an exception and redirecting back if the rules are not met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6aa24531-d4be-42fe-a6ae-99a5b9417891', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the role of the ''Composition API'' in Vue 3?', N'Middle', N'The Composition API provides a way to group component logic by feature rather than by option type, such as data or methods. This significantly improves code reusability through composables and makes large components easier to maintain and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce3ce504-5bba-4cde-8d7f-99a5ed44388f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why should you separate Express ''app'' and ''server''?', N'Fresher', N'Keeping the API declaration separated from the network related configuration (port, protocol, etc) allows testing the API in-process, without performing network calls, with all the benefits that it brings to the table: fast testing execution and getting coverage metrics of the code. It also allows deploying the same API under flexible and different network conditions. API declaration, should reside in app.js: Server network declaration', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fff6124-5ab5-40c1-a4a7-99a6e2527113', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the benefit of using Alpine.js for server-side rendered applications?', N'Junior', N'It provides interactivity without the overhead of a complex build pipeline or a virtual DOM. It enhances the existing HTML generated by the server, keeping the project lightweight and easier to maintain for smaller interactive features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'952e9c40-e570-4cbe-9ad1-99a9a80c9e6f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the MySQL optimizer decide between using an index and performing a full table scan?', N'Senior', N'The optimizer uses cost-based estimation, considering factors like index cardinality, the number of pages to be read, and the cost of random versus sequential I/O. If the optimizer estimates that the cost of scanning the index and performing bookmark lookups exceeds the cost of a sequential table scan, it will choose the full scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4985aacf-1163-413b-b35e-99aa98f33f22', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between ''abstract'' and ''interface'' when considering inheritance?', N'Junior', N'A class can extend only one abstract class, enforcing a strict hierarchical relationship. Conversely, a class can implement multiple interfaces, allowing it to inherit behavior from different sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18a60724-826e-45e1-a8d8-99b4b085af80', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How do you handle configuration properties in Quarkus, and what is the ''SmallRye Config'' role?', N'Middle', N'Quarkus uses SmallRye Config to manage application settings, which supports dynamic sources like environment variables, system properties, and profiles. It provides features like type-safe configuration mapping, which allows developers to inject configuration objects directly into beans with validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'312b4a40-acf7-4113-a971-99bb5c1e7792', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite generally considered faster for larger projects?', N'Junior', N'Because Vite only compiles the code that is being requested by the browser during development, it doesn''t need to re-bundle the entire application when a single file changes. This incremental approach keeps performance high regardless of the size of the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efd04857-67f2-4ac2-89f6-99c0bc25b588', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the borrow checker?', N'Junior', N'The borrow checker is a component of the compiler that enforces ownership and borrowing rules. It ensures that references do not outlive the data they point to and prevents data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e1cd227-e292-44cf-8c04-99c4495286df', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Atomicity in a database transaction?', N'Intern', N'Atomicity ensures that all operations within a transaction are completed successfully as a single unit. If any part of the transaction fails, the entire transaction is aborted and the database is left unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf40d405-0878-4ff9-9bfd-99c4cae7a671', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'When does a SolidJS component function run?', N'Junior', N'Unlike React, a SolidJS component function runs only once when the component is first initialized. The UI updates are handled by the framework''s reactive primitives inside the component, not by re-executing the component function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
