INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64f49f5c-8e99-4722-8bd2-99ca8f2e1f41', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens if a node holding a primary shard goes down?', N'Junior', N'If a node holding a primary shard fails, the cluster will automatically promote one of the corresponding replica shards to become the new primary. This ensures that the data remains available and consistent without manual intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54b806fa-4da6-4fbf-8a98-99ca924ece2f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you handle database migrations in a distributed Rails environment to ensure zero downtime?', N'Senior', N'Ensure migrations are backward compatible by splitting changes into multiple deployments: first add the new column or table, update the application to write to both, migrate the data, and finally remove the old column. Avoid heavy operations like adding indexes on large tables in a single migration without using concurrent index creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b15f6dd7-17e6-4f9e-b484-99cbcba5a3e3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What does the ''Abort'' method do in Gin?', N'Fresher', N'The Abort method is used to stop the middleware chain for the current request. It is typically used in authorization middleware when a condition is not met, preventing the main handler from executing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
