INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0df8c09-d2e4-4371-a289-99cd44971ba5', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the security considerations when using Alpine.js expressions.', N'Senior', N'Alpine.js evaluates expressions within a sandboxed context, but it must be used carefully to avoid XSS vulnerabilities when dealing with user-provided data. Developers should never bind user-inputted content directly into directives that evaluate code, as it could lead to arbitrary script execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c97685c-859d-4521-90f7-99ce3bc5bb60', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit achieve ''Progressive Enhancement'' without compromising the user experience of a Single Page Application?', N'Senior', N'SvelteKit uses the browser''s native form submission capabilities by default, which are then intercepted by the framework''s router if JavaScript is enabled. This ensures that the application remains functional in restricted environments while providing a seamless, SPA-like navigation experience in modern browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17821a8b-2c9a-47a7-a0a6-99cf140c9efe', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between ''block'', ''inline'', and ''inline-block'' display types?', N'Middle', N'Block elements start on a new line and occupy the full available width of their container. Inline elements do not start on a new line and only occupy the width of their content, with no control over height or top/bottom margins. Inline-block combines both, allowing elements to sit side-by-side while still supporting width, height, and margin properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
