INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3daa4ac2-545c-4f98-a656-99db329e5de2', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between DELETE and TRUNCATE?', N'Intern', N'DELETE is a DML command used to remove specific rows from a table based on a condition, and it logs each row deletion. TRUNCATE is a DDL command that removes all rows from a table quickly by deallocating the pages used to store the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f99a07-e54d-42a2-bfa5-99dbd9ed5d4e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why does strict mode render twice in React?', N'Fresher', N'StrictMode renders components twice in development mode(not production) in order to detect any problems with your code and warn you about those problems. This is used to detect accidental side effects in the render phase. If you used create-react-app development tool then it automatically enables StrictMode by default. If you want to disable this behavior then you can simply remove strict mode. To detect side effects the following functions are invoked twice: 1. Function component bodies, excluding the code inside event handlers. 2. Functions passed to useState, useMemo, or useReducer (any other Hook) 3. Class component''s constructor, render, and shouldComponentUpdate methods 4. Class component static getDerivedStateFromProps method 5. State updater functions', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
