INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f83e65a3-95ac-428f-bc81-99f9142ab4ac', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''synthetic transactions'' help in monitoring?', N'Middle', N'Synthetic transactions are scripted, automated tests that mimic real user behavior on a live application. They allow teams to detect issues proactively even when there is no real traffic, ensuring that key user flows are functioning as expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bae4ee7-c57b-42ff-ad7c-99f9f64dce51', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you ensure a fix hasn''t broken anything else?', N'Intern', N'After applying a fix, you should perform regression testing, which involves running a suite of existing tests to ensure that previously working features still function correctly. This confirms that the change did not cause unintended side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d13ffbf-c3e0-4c3c-ad5f-99fa9d6b001a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of an Index in a database?', N'Fresher', N'An index is a performance-tuning structure that allows the database to find rows more quickly without scanning every single row in a table. It works similarly to an index in a book, pointing the database directly to the location of the requested data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8c26da5-721e-4d6d-8c11-99fab693c259', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the function of the ''Router'' in an Axum application?', N'Fresher', N'The Router is the central component that defines how HTTP requests are dispatched to handlers. It acts as a builder where you define paths, methods, and middleware layers that apply to specific segments of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b647e2e5-48b5-4e2a-92ec-99fb69ed4fe8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of ''Table Partitioning'', and how does declarative partitioning improve management?', N'Senior', N'Partitioning divides large tables into smaller, manageable chunks based on ranges, lists, or hashes to improve performance and maintenance. Declarative partitioning simplifies this by automating the routing of data to partitions and enabling partition pruning, where the planner ignores irrelevant partitions during queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f6c748-9e1f-4e5d-826d-99fbaed66e7b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What does ''star-projection'' signify in generic types?', N'Middle', N'Star-projection is used when you know nothing about the generic arguments of a type but want to use it safely. It acts as a read-only view where you can retrieve elements as ''Any?'' but cannot add elements, as the specific type is unknown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'595c2382-9882-4df8-b61a-99fd2ce5355f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of the ''q-manifest.json'' file?', N'Middle', N'The manifest acts as a map that links specific component symbols to their corresponding JavaScript chunks. It allows the framework to know exactly which file to fetch when a specific component needs to be rendered or a function needs to be executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b1188d2-5944-4b98-aad7-99fd7483ed35', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the advantage of using ''useHead'' in Nuxt?', N'Junior', N'useHead is a composable used to manage the document head of your page. It allows you to dynamically update the title, meta tags, and link tags based on the current page content, which is essential for SEO.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab17e744-8af1-4f17-b97c-99fdab221139', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is a factory constructor in Dart?', N'Intern', N'A factory constructor is a special type of constructor that does not always create a new instance of its class. It is often used to return an existing instance from a cache or to return an instance of a subtype.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e9827d3-a4a3-4cda-8ebb-99ff1f375980', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a self-referencing relationship?', N'Fresher', N'A self-referencing relationship occurs when a table has a foreign key that references its own primary key. This is commonly used in hierarchical data, such as an employee reporting to a manager who is also an employee in the same table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6cb7f00-8948-461f-bcab-99ff37bbfafc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is memoization and how do you implement it correctly for production use?', N'Senior', N'Memoization is a caching technique that stores the return value of a pure function keyed by its arguments. On subsequent calls with the same arguments, the cached result is returned without re-executing the function. It is the programmatic application of the mathematical concept that pure functions are referentially transparent (same input → same output). Production concerns beyond the naïve implementation: 1. Cache key strategy — JSON.stringify fails for non-serialisable args (functions, circular refs, Symbols, undefined). A WeakMap keyed on object identity avoids this. 2. Cache eviction — unbounded caches grow without limit. LRU (Least Recently Used) eviction is standard. 3. Async memoization — memoize the Promise itself, not the resolved value, to prevent duplicate in-flight requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1dd61c2-fb05-45dd-9130-9a0114d35cb0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of a foreign key?', N'Junior', N'A foreign key is a field that links one table to the primary key of another table. It enforces referential integrity, ensuring that relationships between tables remain consistent and valid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65314f0b-6e1d-40d2-afc6-9a0159bb1d80', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence the decision to use vertical scaling versus horizontal scaling?', N'Middle', N'Vertical scaling is simpler to implement but has a physical upper limit on hardware capacity and creates a single point of failure. Horizontal scaling is more complex to manage due to distributed state and load balancing, but it offers virtually unlimited scale and higher fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac6910fd-a57a-4c28-b593-9a0839c43548', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between Tree Shaking and Dead Code Elimination, and how does Webpack implement the former?', N'Senior', N'Tree shaking is a static analysis technique that removes unused exports from modules, while dead code elimination is a broader process often performed by minifiers. Webpack achieves tree shaking by relying on ES module static structure to identify ''live'' exports and stripping out unreachable code during the bundling phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5280348-b9c2-4a52-b21d-9a09fc47676a', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue handle scoped CSS, and what are its limitations?', N'Middle', N'Scoped CSS uses PostCSS to automatically add unique data attributes to elements, ensuring styles only apply to the current component. A limitation is that it does not affect child components unless the deep selector is used, and it can increase CSS bundle size if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d1bc9db-bed8-4bc5-8311-9a0ed90656a4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''fillable'' property in an Eloquent model?', N'Junior', N'The fillable property is a whitelist that defines which database columns can be ''mass-assigned'' through the model. This is a critical security feature that prevents malicious users from updating sensitive attributes like user roles or account status via HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e390a74-547c-45e9-8106-9a134739abc4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'In the context of CAP theorem, why is it often considered a misnomer to choose ''AP'' over ''CP''?', N'Senior', N'The CAP theorem is often misunderstood because network partitions are inevitable in distributed systems. Choosing AP or CP is not a binary switch but a configuration of how the system handles latency and consistency trade-offs when a partition occurs, rather than a permanent architectural state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9027a94d-567d-4307-a258-9a13587da446', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle image and asset loading?', N'Fresher', N'Remix treats static assets like images and styles as standard web resources. Because it follows web standards, you can link to these assets directly in your HTML or import them through the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df363406-e123-45e8-9983-9a138063947d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How can you return different status codes in Gin?', N'Fresher', N'Gin provides a specific parameter within the response methods to set the HTTP status code. You can use the standard HTTP constants provided by the net/http package to ensure the correct status code is sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5159644f-e6b7-4e3a-a17b-9a14b2157abe', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is the decorator pattern preferred over prototype modification in Fastify?', N'Senior', N'Decorators provide a safe, namespaced way to extend the server, request, or reply objects without causing prototype pollution or naming collisions. This ensures that third-party plugins remain isolated and compatible, maintaining the integrity of the core framework objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'827f92c7-0848-41eb-919b-9a1ab4f20d7e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between ''blocking'' and ''non-blocking'' controllers in Micronaut?', N'Middle', N'Blocking controllers execute on the worker thread pool and are suitable for legacy synchronous operations, while non-blocking controllers leverage the event loop to handle requests asynchronously. Non-blocking controllers are preferred for high-concurrency scenarios to prevent thread starvation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'635b6bad-3f35-48c1-946d-9a1d085ec3d9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle a situation where two stakeholders disagree on a technical approach?', N'Fresher', N'I would analyze both approaches by listing their pros and cons, impact on the timeline, and long-term maintenance costs. The goal is to provide an objective comparison so the team can reach a decision based on business priorities rather than personal preference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0398561c-968c-442a-bbe3-9a21539b3802', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you use an ORM (Object-Relational Mapping) tool when interacting with a database?', N'Fresher', N'An ORM allows you to interact with database records using objects in your preferred programming language, abstracting away raw query syntax. This makes the code easier to read and maintain while reducing the potential for syntax errors. However, it is important to be aware of the performance overhead that abstraction layers can sometimes introduce.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8da2549-c8c1-456d-b552-9a2299a49eb4', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does horizontal scaling (sharding) differ from vertical scaling?', N'Junior', N'Vertical scaling involves adding more power, such as CPU or RAM, to an existing server. Horizontal scaling involves adding more machines to the database pool to distribute the load across multiple servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5b36e50-3837-4d93-800f-9a233025bb39', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if you do not specify a Webpack configuration file?', N'Junior', N'If no configuration file is provided, Webpack will use its default settings. By default, it expects the entry point to be at ''src/index.js'' and outputs the bundled file to ''dist/main.js''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ad4af8d-f1fa-4972-9fe3-9a23eb3aa38b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between CSS Grid and Flexbox, and when should you choose one over the other?', N'Middle', N'Flexbox is designed for one-dimensional layouts, either as a row or a column, making it ideal for aligning components within a container. CSS Grid is a two-dimensional system that manages both rows and columns simultaneously, making it better suited for complex page structures and overall dashboard layouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'098a6ab4-c7fa-44b6-812c-9a260fd8e18c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro manage the integration of multiple UI frameworks (e.g., React, Vue, Svelte) within a single project?', N'Senior', N'Astro acts as a framework-agnostic orchestrator, allowing different UI frameworks to coexist by treating them as isolated islands. Each framework is compiled independently and hydrated only when required, preventing library conflicts and allowing teams to migrate or mix technologies without complex configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82608c10-0823-49ef-b76b-9a2a383e9934', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do ''derive'' macros improve maintainability?', N'Middle', N'Derive macros automatically implement common traits for types, reducing boilerplate code for standard operations like equality checks or cloning. This ensures consistency across the codebase and prevents manual implementation errors while allowing the compiler to handle the repetitive aspects of type system integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84e30307-f0e1-42b5-b825-9a2f12ba0eb4', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite not perform type checking during development?', N'Fresher', N'Vite focuses on speed by using esbuild, which only strips away type annotations rather than performing a full type check. This keeps the development server highly responsive, leaving type checking to your IDE or a separate command-line process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72c6b3da-2382-42e5-b2ba-9a31f107d66c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is ACID compliance often different in NoSQL databases?', N'Junior', N'Many NoSQL databases favor the BASE model (Basically Available, Soft state, Eventual consistency) over strict ACID compliance to achieve higher throughput and scalability. While some NoSQL databases provide ACID transactions, many prioritize speed and partition tolerance, leaving consistency to be managed at the application level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18fb49e2-c5ca-4248-a0c3-9a33508dd9c7', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s zero-config setup?', N'Junior', N'Zero-config means that SvelteKit comes with sensible defaults for common tasks like routing, building, and bundling. This allows developers to focus on building features rather than spending time configuring complex build tools or bundlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'645692b2-8119-4a75-8811-9a374202adad', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a buffered channel, and when should it be used?', N'Middle', N'A buffered channel allows a certain number of elements to be stored without a corresponding receiver immediately present. It should be used to decouple producers from consumers to improve performance by reducing synchronization overhead during bursty traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11563d94-f4cd-4bfa-8e35-9a3bc5901eac', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is BSON and how is it related to MongoDB?', N'Junior', N'BSON stands for Binary JSON. It is the binary-encoded serialization format used by MongoDB to store documents and perform remote procedure calls, offering more data types and efficiency than standard text-based JSON.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
