INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9a83066-8f74-4faa-9d1c-9a3ed9b3f422', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does a database engine do?', N'Junior', N'A database engine is the underlying software component that a database management system uses to create, read, update, and delete data. It handles tasks like file storage, transaction management, indexing, and query optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
