INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d4476be-451e-438f-ba22-9a40cd56d2a9', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How are props treated when passed to components?', N'Junior', N'Props in SolidJS are read-only reactive objects. Accessing a prop acts as a subscription to that value, ensuring that any component consuming that prop will update when the parent changes it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b102c64f-4244-4da0-88f7-9a425a7c4dfe', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo manage the ''Content-Type'' header during response rendering, and what happens if you override it manually?', N'Senior', N'Echo automatically sets the Content-Type based on the rendering method or data type returned, such as JSON or HTML. Manually overriding this requires careful handling to ensure it matches the actual payload format, as an incorrect header can cause client-side parsing errors or security vulnerabilities like MIME-sniffing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
