INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'015f7263-f50f-4cd8-ba48-9a4c1971fc27', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using inheritance and composition in object-oriented design?', N'Fresher', N'Inheritance should be used to represent an ''is-a'' relationship, while composition is preferred for ''has-a'' relationships. Composition is generally more flexible because it allows you to change behavior at runtime by swapping components, whereas inheritance creates a rigid hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37eb0db6-d93a-4cb2-a02f-9a4c3449f51c', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of the Bulkhead pattern?', N'Middle', N'The Bulkhead pattern isolates elements of an application into pools so that if one fails, the others will continue to function. By partitioning resources like thread pools or connection pools, it prevents a failure in one service or component from consuming all available system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
