INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f987308-9553-4b9a-97c5-9a571aabc416', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the common scopes for a Spring Bean?', N'Junior', N'The most common scopes are ''singleton'', which creates one instance per container, and ''prototype'', which creates a new instance every time the bean is requested. Other scopes like ''request'', ''session'', and ''application'' are also available for web-aware applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26178eff-4077-42c0-935e-9a5b65e6b582', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of ''Buffer Pool'' management in database engines.', N'Senior', N'The buffer pool is a dedicated area of RAM that caches data pages to minimize disk I/O. Effective management involves using algorithms like LRU (Least Recently Used) to keep frequently accessed data in memory, significantly accelerating read-heavy workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec0bd0b-fce7-49e6-93ea-9a5ec73172f9', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use Hooks in Preact, and are there any differences?', N'Middle', N'Preact has built-in support for Hooks that mirrors the React API almost perfectly. The logic remains consistent, but the underlying implementation is more compact, ensuring developers can switch between libraries with minimal friction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11193488-41b3-4b4a-b8f6-9a63cd8bd44b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are push notifications in PWA?', N'Intern', N'Push Notifications allow a server to send messages to a user''s device even when the PWA is not open in the browser, using the Push API and Notifications API together. Flow: 1. App requests notification permission from the user. 2. App subscribes to the browser''s push service (generates a unique subscription endpoint). 3. Subscription is sent to the app''s server. 4. Server sends a push message to the endpoint via the Web Push Protocol. 5. Service worker receives the push event and shows a notification. Step 1 — Request permission: Step 2 — Subscribe: Step 3 — Handle push in service worker (sw.js): The service worker acts as a background daemon — it can receive push events and display notifications even when the app tab is closed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eed08fd0-4a9e-485d-88ab-9a6411cb4e3a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the benefit of Rocket''s ''Launch'' attribute?', N'Middle', N'The launch attribute simplifies the application entry point by setting up the asynchronous runtime and initializing the Rocket server instance. It removes the need for manual boilerplate code usually required to bootstrap an async web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'578f49f8-a724-464a-845f-9a6a5f5a67d2', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How can Redis be utilized to implement rate limiting in a distributed system?', N'Senior', N'Rate limiting can be implemented using the INCR command with an expiration time, or using sorted sets to maintain a sliding window of timestamps. By using atomic operations, Redis ensures that rate limit checks are consistent across multiple application instances without requiring complex distributed locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ec80c87-8699-4815-8ced-9a6d1dbd4b8d', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What happens if an Axum handler returns an error?', N'Fresher', N'Axum handlers can return a result type where the error variant implements IntoResponse. This allows the developer to define how specific errors are mapped to HTTP status codes and error messages for the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76c7e2ed-e1bc-44c2-865f-9a6d2301d691', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle navigation differently than a traditional multi-page application?', N'Middle', N'SvelteKit uses a router that intercepts link clicks to perform client-side navigation, replacing only the necessary parts of the DOM. This provides a single-page application experience with instant transitions while maintaining standard browser behavior like history management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c72fe50-aea1-47f0-9f45-9a6fc3d15d14', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Describe the strategy for managing database migrations in a distributed Symfony environment.', N'Senior', N'Database migrations should be idempotent and managed through a versioning tool like Doctrine Migrations integrated into the CI/CD pipeline. In distributed systems, it is critical to implement a locking mechanism to ensure only one node executes migrations, preventing race conditions or schema corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac4bbd95-7d3b-4ddb-b8f6-9a70f5ec8f2d', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the implications of network partitions on distributed caches?', N'Middle', N'Network partitions can lead to ''split-brain'' scenarios where different nodes in the cache cluster have conflicting data. Depending on the consistency model, this can cause the system to return stale data or become unavailable while trying to resolve the conflict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee46eec6-f2aa-41fb-a5b6-9a722be3f8e5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is meant by ''Lazy Loading'' in Qwik?', N'Fresher', N'Lazy loading in Qwik refers to loading JavaScript modules only when they are needed by the user, such as when they click a button or scroll to a section. This drastically reduces the initial payload size sent to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b51ece31-e612-423e-b5c0-9a78e0b81b11', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary architectural advantage of Preact''s ''h'' function over React''s ''createElement''?', N'Senior', N'The ''h'' function in Preact is designed to be highly concise and map directly to virtual DOM nodes without the overhead of React''s property validation and normalization. This allows for smaller bundle sizes and faster compilation, as the function signature is optimized for minification and quick execution during the render phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'784c6cad-6e0d-4363-8cfe-9a7a73001df5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How can TypeScript''s ''Readonly'' and ''ReadonlyArray'' utilities be used to enforce immutability in state management?', N'Senior', N'These utilities provide a way to mark object properties and arrays as immutable, causing compile-time errors if any mutations are attempted. This helps enforce unidirectional data flow and prevents side effects in complex state management architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'448b8a36-42dc-4060-8f0e-9a7a92e4170b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web relate to the Actix framework?', N'Junior', N'Actix-web is a high-performance web framework built on top of the Actix actor system. While they share the same underlying architecture and ecosystem, Actix-web specifically focuses on handling HTTP requests and responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'630fb1a6-fe6b-4d35-8b7f-9a7fe50e696e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how prototypal inheritance works?', N'Fresher', N'The Prototypal Inheritance is a feature in javascript used to add methods and properties in objects. It is a method by which an object can inherit the properties and methods of another object. In order to get and set the [[Prototype]] of an object, we use Object.getPrototypeOf() and Object.setPrototypeOf(). Nowadays, in modern language, it is being set using proto. Syntax: Example: In the given example, there are two objects ParentUser and ChildUser. The object ChildUser inherits the methods and properties of the object ParentUser and further uses them. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2045333-246f-4f5e-bf8a-9a8017e25ea2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using JSON and binary formats like Protocol Buffers for data transmission?', N'Junior', N'JSON is human-readable, widely supported, and easy to debug, making it excellent for public APIs. Binary formats are significantly more compact and faster to parse, which reduces bandwidth and CPU usage, but they are not human-readable and require shared schemas between the sender and receiver.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f4eafba-f2b8-4936-8112-9a84e6df3b66', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the four phases of template translation?', N'Intern', N'The i18n template translation process has four phases: 1. Mark static text messages in your component templates for translation: You can place i18n on every element tag whose fixed text is to be translated. For example, you need i18n attribute for heading as below, 2. Create a translation file: Use the Angular CLI xi18n command to extract the marked text into an industry-standard translation source file. i.e, Open terminal window at the root of the app project and run the CLI command xi18n. The above command creates a file named messages.xlf in your project''s root directory. Note: You can supply command options to change the format, the name, the location, and the source locale of the extracted file. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f3ca30c-cca6-4886-bb9e-9a8640fd08c1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'When should you prefer ''sequence'' over ''iterable'' for collection operations?', N'Middle', N'Sequences perform lazy evaluation, meaning they process elements one by one through the entire chain of operations rather than creating intermediate collections at each step. This is much more efficient for large datasets or chains involving multiple transformation functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5192c6b4-dc1b-427f-9599-9a86788a3096', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the trade-offs of using ''async/await'' compared to raw Promises?', N'Middle', N'Async/await improves readability by making asynchronous code look synchronous, which simplifies error handling with try/catch blocks. While functionally equivalent to Promises, it can sometimes hide the underlying concurrency, potentially leading developers to accidentally execute tasks sequentially when they could run in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c76fb27-5c38-4860-ba21-9a88afef1a5d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the role of the Zend Engine in the PHP lifecycle.', N'Middle', N'The Zend Engine is the core interpreter that compiles PHP source code into opcodes and executes them. It manages memory, handles the Zend Virtual Machine, and provides the underlying infrastructure for language features like variables and function calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a6b2e78-bc76-4923-b248-9a8e636b1e4d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra achieve high availability compared to traditional relational databases?', N'Fresher', N'Cassandra achieves high availability by using a peer-to-peer architecture where all nodes are equal, eliminating a single point of failure. It replicates data across multiple nodes so that if one node goes down, the data remains accessible from other replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b43357b7-05e4-46bc-8f35-9a8fee0f8fa7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the difference between SQL and NoSQL databases regarding their schema?', N'Fresher', N'SQL databases are schema-based, meaning they require a predefined structure before data can be inserted. In contrast, NoSQL databases are schema-less or have dynamic schemas, allowing data to be added without following a strict, predefined format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6789e0f-689d-4c4c-bc0b-9a910feeab3c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the pub tool?', N'Fresher', N'Pub is the package manager for the Dart language. It is used to manage dependencies, download external packages from the pub.dev repository, and automate common tasks like building and testing projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fff4e0f5-5934-4624-a881-9a93b7ec9f48', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the security principles in angular?', N'Fresher', N'Below are the list of security principles in angular, 1. You should avoid direct use of the DOM APIs. 2. You should enable Content Security Policy (CSP) and configure your web server to return appropriate CSP HTTP headers. 3. You should Use the offline template compiler. 4. You should Use Server Side XSS protection. 5. You should Use DOM Sanitizer. 6. You should Preventing CSRF or XSRF attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0e110a4-623c-449d-b14e-9a94c083353d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s memory footprint compare to other Node.js frameworks, and why?', N'Senior', N'Fastify has a smaller memory footprint because it avoids the overhead of large, multi-purpose middleware stacks and uses efficient internal structures like radix trees. By keeping the core lightweight and using high-performance dependencies, it reduces the allocation rate per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cfefa3c-9ecf-4e9f-ab27-9a991e814caf', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a situation where you realize your initial plan will not work?', N'Fresher', N'I stop immediately to prevent further wasted effort and reassess the goal. I analyze why the initial plan failed, gather new information, and adjust my strategy before restarting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b64b6042-3eac-4203-9b16-9a99b64d07c6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the concept of ''Strong Parameters'' and why they are necessary.', N'Middle', N'Strong Parameters provide a security mechanism to prevent mass assignment vulnerabilities, where an attacker might inject unexpected parameters into a model. By requiring developers to explicitly whitelist which attributes can be updated via the request, it ensures that sensitive fields like administrative flags cannot be modified by end-users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1150df37-e486-4453-99da-9a9a0e2ae455', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the trade-offs of using synchronous vs asynchronous communication between services?', N'Middle', N'Synchronous communication is easier to implement and provides immediate feedback but creates tight coupling and dependencies on service availability. Asynchronous communication decouples services and increases resilience, but adds complexity regarding eventual consistency and error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'145bb0cb-6cfb-43e2-89c1-9a9c1ec712dd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach capacity planning for a system expected to grow to millions of users?', N'Senior', N'I would perform load testing based on historical user behavior to establish a baseline of resource consumption per user. I would then identify the system''s performance bottlenecks, such as database locks or network I/O, and plan for horizontal scalability while ensuring that every component is stateless where possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5124d1a-1efa-4730-a453-9a9db2fd6f5e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a ''multi-compiler'' mode in Webpack?', N'Middle', N'Multi-compiler mode allows Webpack to run multiple configurations in a single command. This is useful for projects that need to generate different builds simultaneously, such as one for the frontend client and another for the backend server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c964b95c-9c91-4025-b77f-9a9e9f97dc85', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is an ''onMount'' lifecycle function?', N'Fresher', N'The onMount function is a hook that runs after the component is first rendered and attached to the DOM. It is typically used for tasks that require access to the DOM, such as initializing third-party libraries or fetching initial data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ceb3bbb7-0615-4671-affa-9aa0ec38117c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why does Tailwind encourage building ''components'' instead of just using utilities everywhere?', N'Middle', N'Building components promotes the DRY (Don''t Repeat Yourself) principle and makes the codebase easier to maintain. If you need to change the padding or color of a primary button, you only update the component definition rather than searching and replacing the same utility classes across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9d41724-cd7b-4ed1-a36d-9aa2a1e19d5e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the effect of calling ''Abort'' inside a Gin middleware?', N'Middle', N'Calling Abort prevents subsequent handlers in the chain from executing, but it does not stop the current handler from finishing its execution. It is typically used to stop the flow of request processing after an authentication check or validation failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e07df76-97d9-4c52-bdd7-9aa2fd01240b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the architectural implications of ''Route Rules'' for caching strategies.', N'Senior', N'Route Rules provide a declarative way to define caching headers, ISR (Incremental Static Regeneration), and rendering modes per route. This allows for fine-grained control over server load, enabling you to cache heavy pages at the edge while keeping dynamic pages server-rendered, balancing freshness with performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
