INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5edf1412-6978-4431-a9f0-9aa589c79607', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Kernel in Symfony, and how does it manage the request-response lifecycle?', N'Senior', N'The Kernel is the heart of the framework that converts a Request object into a Response object by orchestrating the dispatching of events. It manages the full lifecycle including booting bundles, resolving the controller, executing listeners, and handling exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02a32f3b-21fe-4534-80f1-9aa7906dad03', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between ''white-box'' and ''black-box'' monitoring?', N'Senior', N'White-box monitoring relies on internal metrics like CPU, memory, and application logs to give insight into internal system state. Black-box monitoring checks the system from the outside, such as checking if an endpoint returns 200 OK, focusing on user-perceived availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3aeb6c9-925b-4031-8d74-9aa7ea4ee255', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Controller in the MVC pattern?', N'Intern', N'The controller acts as an intermediary between the user request and the model layer. It receives input from the route, processes the logic, interacts with models to retrieve or save data, and returns a response, usually by loading a view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de553f4e-b8d0-4671-8087-9aac22da9f04', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where a service is consuming too much memory and causing OOM errors?', N'Middle', N'I would first use profiling tools to identify memory leaks or inefficient object allocation patterns in the code. If the code is optimized, I would adjust the service’s memory limits in the container orchestrator and evaluate if the service should be refactored to process data in smaller batches to reduce the memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1547d2b7-6cc2-48c6-b79f-9aac3c93efeb', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite ensure consistency between development and production?', N'Middle', N'Vite uses the same configuration object for both environments, which helps prevent discrepancies. While the transformation pipeline differs—using esbuild for speed in dev and Rollup for optimization in production—the resolved module graph remains largely consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
