INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e48d6b52-f18d-4b50-b876-9ab7527475ce', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How to condense large volumes of data in Mongodb?', N'Fresher', N'compact: Rewrites and defragments all data and indexes in a collection. On WiredTiger databases, this command will release unneeded disk space to the operating system. This command will perform a compaction "in-line". MongoDB compresses the files by: * copying the files to a new location * looping through the documents and re-ordering / re-solving them * replacing the original files with the new files Syntax:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08efeae3-7c8f-499f-8ff7-9ab7d873d70a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do you handle database connections efficiently in a Rocket application?', N'Middle', N'The recommended way is to use a connection pool, such as those provided by database-specific integration crates. These pools are registered as managed state, allowing handlers to request a connection from the pool, which is then automatically returned once the handler finishes execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fad4d17e-354a-4c65-8cd8-9abd494bc52a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach selecting a technology stack for a new project?', N'Intern', N'The selection should be based on the project''s specific requirements, the team''s existing expertise, and the long-term maintainability of the tools. It is also important to consider community support, documentation, and whether the ecosystem is growing or shrinking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14f6fe4d-b2a1-408d-b229-9abd8d699508', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why might you use a message queue instead of synchronous HTTP calls for microservice communication?', N'Middle', N'Message queues enable asynchronous communication, which improves system resilience by allowing services to continue operating even if the receiver is temporarily offline. It also decouples service deployment cycles and helps smooth out traffic bursts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45591505-b100-4852-be59-9abe60a5bbf5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If two team members disagree on the best technical approach, how do you handle it?', N'Fresher', N'I would facilitate a discussion where both parties explain the trade-offs of their proposed solutions, focusing on factors like maintainability, performance, and development time. If a consensus cannot be reached, I would look for a compromise or ask a senior team member to help evaluate which approach better aligns with our project standards. The focus should remain on the project goal rather than personal preference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'299454f9-2198-4b0f-8e6d-9abe759c5773', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the core principles of Redux?', N'Intern', N'Redux follows three fundamental principles: 1. Single source of truth: The state of your whole application is stored in an object tree within a single store. The single state tree makes it easier to keep track of changes over time and debug or inspect the application. 2. State is read-only: The only way to change the state is to emit an action, an object describing what happened. This ensures that neither the views nor the network callbacks will ever write directly to the state. 3. Changes are made with pure functions(Reducers): To specify how the state tree is transformed by actions, you write reducers. Reducers are just pure functions that take the previous state and an action as parameters, and return the next state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'111b806c-dce8-4e54-a0b1-9abff517d6a0', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the trade-offs of using a centralized Identity Provider (IdP) versus decentralized identity management.', N'Senior', N'Centralized IdPs provide a single point of audit, consistent security policy enforcement, and easier user management. Decentralized systems improve availability and eliminate the central point of failure, but they introduce significant complexity in synchronization, consistency, and unified revocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc627a9d-3550-4ffc-a8da-9ac229a67232', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of a ''coordinate node''?', N'Middle', N'A coordinate node receives search or indexing requests from the client and routes them to the appropriate data nodes. It then collects the partial results, merges them, and sends the final response back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
