INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01cee0f9-fdbc-4aa8-9fa2-9ac53907e28d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage environment variables to ensure security?', N'Middle', N'SvelteKit uses specific naming conventions to distinguish between public and private variables, ensuring that private secrets are never bundled into client-side code. This prevents sensitive information like database credentials from being exposed to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
