INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1aacaae-ee11-49cc-89f6-9af2fa87b083', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the trade-off between strong consistency and low latency?', N'Middle', N'Strong consistency requires synchronization between all nodes before a write is confirmed, which introduces network latency and reduces throughput. Choosing low latency often requires accepting eventual consistency, where some nodes might briefly serve stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f98b9bfc-c380-4804-8fe2-9afbd7ceea8d', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you implement model on custom input components?', N'Fresher', N'The custom events can also be used to create custom inputs that work with v-model. The inside the component must follow below rules, 1. Bind the value attribute to a value prop 2. On input, emit its own custom input event with the new value. Let''s take a custom-input component as an example, Now you can use v-model with this component,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4113fd3d-a8ed-4441-a729-9afd1afbf80a', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the architectural benefits of using ''Standalone Components'' in modern Angular?', N'Senior', N'Standalone components simplify the architecture by removing the need for NgModules, reducing the boilerplate required to manage dependencies and declarations. They make components more self-contained, easier to lazy-load via route configurations, and improve the overall developer experience by making dependency relationships explicit within the component itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98f8ba8c-f478-4543-aef9-9afedcf76c43', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with an intermittent ''flaky'' test in CI, what is your systematic approach to resolving it?', N'Middle', N'I would first isolate the test to run it in a loop to confirm its non-deterministic nature, then examine it for common causes like race conditions, shared state, or timing dependencies. Once identified, I would refactor the test to use proper synchronization primitives or mock external dependencies to ensure consistent execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ca28c74-1ca4-4625-ae59-9aff03285a6d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why should you use prepared statements when working with databases?', N'Junior', N'Prepared statements prevent SQL injection attacks by separating the SQL logic from the data. They ensure that user input is never interpreted as part of the command, making the database interaction secure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17158727-ea34-4074-97b6-9affd71acc7b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Can you have multiple return values in Go?', N'Junior', N'Yes, Go functions can return multiple values. This is frequently used to return both a result and an error status from a single function call.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df113d96-35a2-4085-869a-9b0081666e6f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why should you avoid storing redundant data in multiple places?', N'Junior', N'Storing redundant data leads to storage waste and increases the risk of data inconsistency. If a piece of information changes, you would have to update it in every location, which is prone to error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58fa3b9e-4460-4cc5-a4dc-9b02301f308d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A user reports that a website feature is broken only in their browser. How would you start investigating?', N'Junior', N'I would first verify the issue by trying to reproduce it in the same browser version. Then, I would check the browser console for specific error logs and suggest the user clear their cache or disable extensions to rule out client-side interference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a868b13a-fec2-4147-aa93-9b0416fa0bd8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis a Relational or a NoSQL database?', N'Fresher', N'Redis is classified as a NoSQL database. It does not use tables, rows, or columns, and it does not use SQL for data manipulation; instead, it uses a flexible key-value model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ea2259d-dd19-4025-b9a1-9b062202d325', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why might you choose to use CSS Custom Properties over Sass variables for theme variables?', N'Senior', N'CSS Custom Properties are live in the browser, allowing for dynamic updates via JavaScript and easier runtime theme switching. Sass variables are compiled at build time, making them static, whereas custom properties provide more flexibility for real-time interactivity and user-controlled themes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae0ec5ae-5ce3-4bf0-8b16-9b096061df35', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Describe the impact of NestJS ''Dynamic Modules'' on scalability.', N'Senior', N'Dynamic modules allow for the runtime configuration of services based on environment variables or external sources, enabling a ''plugin-based'' architecture. This increases scalability by allowing shared services to be instantiated with different configurations without changing the core codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a5b59de-41bd-4099-87d9-9b09e4566d19', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch store data?', N'Fresher', N'Elasticsearch stores data as JSON documents. These documents are organized into types within indices, which act as logical namespaces for related data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'455ca01e-bb87-4027-b80e-9b0bda051ed1', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''Signature Model'' in Litestar?', N'Middle', N'The signature model is generated automatically from the type hints of a handler, serving as the source of truth for request parsing and validation. It allows Litestar to interpret complex types and generate OpenAPI documentation dynamically without manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ef1d0b9-04c3-4f88-9c5d-9b0d33bb51a5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the primary purpose of using Sass in frontend development?', N'Fresher', N'Sass is a CSS preprocessor that extends the capabilities of standard CSS by adding features like variables, nested rules, and mixins. It allows developers to write more maintainable and organized stylesheets by reducing code repetition. Once written, Sass code is compiled into standard CSS that browsers can understand and execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb6fc067-420a-4398-a6d0-9b0eacb1b001', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the role of the Global Offset Table (GOT) in dynamic linking.', N'Senior', N'The GOT is a table in the data segment of a dynamically linked executable that stores the absolute addresses of global variables and functions. Since the final address of these symbols is only known at runtime, the loader updates the GOT, allowing the code to remain position-independent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0a05b80-d155-41f3-bc73-9b14c8e9c7e7', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the CAP theorem and how does it apply to database scaling?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. When scaling a database, architects must choose between prioritizing consistency or availability during network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfeb7e79-1eab-4019-9ad0-9b197a78bdc7', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of ''Lazy Loading'' in Eloquent and how to identify and fix the N+1 problem.', N'Senior', N'Lazy loading fetches related records only when accessed, which triggers an extra query per relationship, leading to the N+1 problem. This is identified via monitoring tools or debug logs and fixed by using eager loading to retrieve all required relations in a single, secondary query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a2d17b1-d021-46b8-bf7f-9b1ac72bc9d2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the architectural limitations of R''s standard ''data.frame'' for high-performance computing?', N'Senior', N'The standard ''data.frame'' is a list of vectors that enforces row-level synchronization and carries significant metadata overhead. This structure is suboptimal for memory locality and cache efficiency, leading to scaling bottlenecks compared to column-oriented formats or specialized in-memory data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'006a9d8e-d7ee-47a6-962a-9b20b9f70f2d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the limitations of Echo''s built-in validation, and when should you consider moving to a dedicated validation layer?', N'Senior', N'Echo''s default validator is a simple interface wrapper, often implemented using third-party packages like go-playground/validator. For complex cross-field validation or business-logic-heavy requirements, you should move validation to a separate service layer to decouple input sanitization from framework-specific implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9db6e4c-5160-4cf4-9598-9b22529e1887', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is logging structured data (e.g., JSON) critical for high-scale observability?', N'Senior', N'Structured logging allows observability platforms to index fields, enabling fast querying and aggregation across millions of log entries. It transforms logs from simple text streams into searchable data, which is essential for identifying patterns during an active incident.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cdcfb21-07e5-4fa8-bae8-9b25d992bb24', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you handle spacing in Tailwind?', N'Intern', N'Tailwind provides a comprehensive spacing scale that covers margins, padding, width, and height. Using this scale ensures that your layout remains consistent and that all elements align correctly according to your design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'577a4ba7-e80d-4d67-bd80-9b27a90aa54e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a lazy stored property?', N'Intern', N'A lazy stored property is a property whose initial value is not calculated until the first time it is used. It must be declared as a variable because its initial value might not be retrieved until after instance initialization is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2880813-46ad-40d4-a1d7-9b2a7ae166c9', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''Validator'' service?', N'Fresher', N'The validator service provides a structured way to enforce rules on incoming request data. It returns clear error messages if the data is invalid, which can be sent back to the client to inform them exactly what needs to be corrected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'494cd061-a270-4ac0-901c-9b2b669ca1e5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you calculate the total width and height of an element?', N'Fresher', N'With the default box-sizing: content-box: $$\text{Total Width} = \text{width} + \text{padding-left} + \text{padding-right} + \text{border-left} + \text{border-right} + \text{margin-left} + \text{margin-right}$$ $$\text{Total Height} = \text{height} + \text{padding-top} + \text{padding-bottom} + \text{border-top} + \text{border-bottom} + \text{margin-top} + \text{margin-bottom}$$ Example: * Rendered width (space taken in layout without margin): 300 + 10 + 10 + 5 + 5 = 330px * Space occupied (including margin): 330 + 20 + 20 = 370px * Rendered height (without margin): 150 + 10 + 10 + 5 + 5 = 180px With box-sizing: border-box, the rendered width equals the declared width (300px), and padding/border are subtracted from the content area.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d1c57db-a17a-415d-9ee3-9b2b7b8818a1', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does ''zero-cost abstractions'' mean in Rust?', N'Intern', N'This principle means that the high-level features provided by the language do not impose extra performance overhead. The abstractions provided are compiled down to machine code that is as efficient as if it had been written manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efad9e6f-b888-4c30-9251-9b2c537a9547', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the role of the ''effect'' scope in Vue 3, and how does it prevent memory leaks in complex applications?', N'Senior', N'Effect scopes allow for grouping reactive effects and computed properties to be disposed of collectively. This prevents memory leaks by ensuring that when a component or a dynamic feature is destroyed, all associated watchers and side effects are properly unsubscribed from the reactivity system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82d3b758-1928-4b07-ba92-9b2cebc9e771', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the challenges of maintaining globally consistent counters in a highly distributed system?', N'Senior', N'Global counters require high levels of synchronization, which creates a performance bottleneck at the point of contention. Techniques like CRDTs (Conflict-free Replicated Data Types) or sharded counters are often used to distribute the load across multiple nodes, accepting eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e97141f7-b380-431d-a09c-9b2df6b0f237', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of ''Sloppy Quorum'' and its relation to availability.', N'Senior', N'Sloppy quorum allows a request to succeed if any ''W'' nodes respond, even if they are not the ones traditionally designated as the primary owners of that data. This increases write availability during network partitions but introduces a higher risk of temporary data inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
