INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08589097-89f1-425a-a1af-9b624eb911ab', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a database normalization and why is it important?', N'Fresher', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them. This approach minimizes data anomalies during insertion, updates, or deletions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'786a1fba-f3bf-452e-be83-9b629d036b0f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle ''strict'' mode?', N'Fresher', N'Strict mode is a compiler configuration that enforces much tighter type checking rules, such as disallowing implicit ''any'' types and ensuring strict null checks. It is highly recommended to use this mode to minimize bugs in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b76af42-2cd1-4253-9ed7-9b62d179cb96', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is database sharding considered a ''last resort'' for scaling?', N'Senior', N'Sharding introduces massive operational complexity, including challenges with cross-shard joins, rebalancing data, and maintaining application-level logic for routing. It is usually avoided until query throughput or storage volume exceeds the capabilities of read replicas and vertical scaling techniques.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b3c82ea-6015-4707-a3f4-9b642df212c0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between Universal Rendering and Client-side Rendering in the context of Nuxt, and when would you choose one over the other?', N'Middle', N'Universal rendering involves rendering the page on the server first to provide a fully populated HTML document, which significantly improves SEO and perceived performance, followed by hydration on the client. Client-side rendering delivers a minimal shell and fetches data in the browser, which is more suitable for highly interactive internal dashboards where SEO is not a priority and initial load time is less critical than subsequent state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1951ddf-25c6-42b6-9a9a-9b6459ae6818', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the ''Oplog'' in a MongoDB replica set?', N'Senior', N'The Oplog is a capped collection that stores a rolling record of all operations that modify the data stored in the database. Secondaries read from this log to replicate data asynchronously, ensuring eventual consistency across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85016459-d475-4b9f-b27d-9b6502e4e0cf', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is horizontal scaling in NoSQL?', N'Intern', N'Horizontal scaling, or scaling out, involves adding more servers or nodes to a distributed system to handle increased load. Unlike vertical scaling, which adds power to a single machine, horizontal scaling allows NoSQL databases to distribute data across a cluster of commodity hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cb8b719-f002-4a88-875c-9b6756db4127', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is logging important in a production environment?', N'Fresher', N'Logging provides an audit trail of everything that happens within an application, which is crucial for troubleshooting errors and understanding user behavior. Without logs, it is nearly impossible to diagnose why an issue occurred or to reconstruct the steps leading up to a system failure. They are the primary tool for gaining visibility into an otherwise ''black box'' production system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bf15d11-3c69-41cd-873e-9b6aaa27cb11', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails'' integration with Redis for caching impact the consistency of distributed systems?', N'Senior', N'Using Redis for caching introduces the risk of cache invalidation challenges, where the application state in the database and the cached view diverge. To maintain consistency, developers must implement robust expiration policies or event-driven cache invalidation patterns to synchronize state across multiple application nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d745e2-1b6c-4283-8289-9b706fdf7e44', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the Model-View-Controller (MVC) pattern?', N'Intern', N'MVC is an architectural pattern that separates an application into three main logical components: the Model, which handles data and logic; the View, which displays the user interface; and the Controller, which acts as an intermediary to process requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc38a122-ab9a-488c-bc6c-9b729138af18', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can Sass Maps be leveraged to build a themeable design system?', N'Senior', N'Sass Maps allow for structured, nested data representation of design tokens like colors, spacing, and typography. By iterating over these maps, developers can programmatically generate entire utility classes or theme variants, ensuring consistency and reducing manual maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7a902ed-fa82-4d39-b8be-9b742df33e2d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a HOT (Heap Only Tuple) update and a standard update in PostgreSQL?', N'Middle', N'A HOT update occurs when a row is updated in a way that doesn''t modify any indexed columns, allowing the new version to reside on the same page as the old one. This avoids the overhead of updating index pointers and improves performance by reducing index bloat and I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddc08960-bbb3-4a2c-9d04-9b742eaa3811', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the trade-offs of using too many shards in a cluster?', N'Middle', N'Having too many shards leads to high overhead for the master node, as it must manage the state of every shard. Furthermore, each shard consumes memory and file descriptors, which can lead to cluster instability and slow recovery times during node failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c77dbad-6f1d-4b51-a14b-9b763d156692', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the possible ways to create objects in JavaScript?', N'Intern', N'1. Object Constructor: The simpliest way to create an empty object is using Object constructor. Currently this approach is not recommended. 2. Object create method: The create method of Object creates a new object by passing the prototype object as a parameter 3. Object Literal: The object literal syntax is equivalent to create method when it passes null as parameter 4. Function Constructor: Create any function and apply the new operator to create object instances, 5. Function Constructor with prototype: This is similar to function constructor but it uses prototype for their properties and methods, 6. ES6 Class: ES6 introduces class feature to create the objects 7. Singleton Pattern: A Singleton is an object which can only be instantiated one time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1403dc90-5a61-4397-b268-9b7b5f7f0c14', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary difference between ''Action'' and ''Event'' in the context of Redux architecture?', N'Senior', N'An action represents a command or an intent to change state, whereas an event is a notification that something has already occurred. Redux actions are typically treated as commands that trigger specific reducers, emphasizing a declarative approach to state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'070bf5c7-469e-4bd6-a8d9-9b7c435b45bf', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Can NoSQL databases store structured data?', N'Intern', N'Yes, NoSQL databases can store structured data, but they do not enforce a rigid schema like relational databases. They provide the flexibility to store structured, semi-structured, and unstructured data side-by-side if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4337e3ea-72cb-45e5-822b-9b7c587d23aa', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is meant by a ''Dangling Pointer'' in Rust and how is it prevented?', N'Fresher', N'A dangling pointer occurs when a reference points to a memory location that has been deallocated or freed. Rust prevents this by ensuring that all references are valid and checking at compile time that the data referred to lives at least as long as the reference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94139159-ea3a-4286-a150-9b7c77ebaaa7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the risk of having too many indexes on a table?', N'Junior', N'While indexes speed up data retrieval, having too many of them can negatively impact performance during insert, update, and delete operations. This happens because every time data is modified, the database engine must also update all associated indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3acd998-1121-41e4-89fe-9b7d5689aed4', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle backpressure and memory management when processing large request payloads?', N'Senior', N'Fastify leverages the underlying Node.js stream API and provides hooks to manage payload size limits at the schema level. By preventing the buffering of entire payloads into memory before processing, it allows developers to implement efficient stream-to-stream transformations that protect the process from heap exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad9e350-0230-4702-9712-9b8270c7e531', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the core difference between SolidJS and frameworks like React regarding the DOM?', N'Intern', N'SolidJS uses fine-grained reactivity to update only the specific parts of the DOM that change, rather than re-rendering entire component trees. It does not use a Virtual DOM, which allows it to perform updates directly and efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71d6b045-2604-405d-a6ee-9b82eca1d9ea', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage state across multiple requests without relying on global variables?', N'Senior', N'Litestar manages state through a combination of request-scoped dependency providers and the ''State'' object attached to the application or router. This ensures that state is thread-safe and isolated, preventing race conditions and simplifying the testing of stateful components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'659a7475-683c-40ca-b3ef-9b85ec7679fa', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database isolation levels like ''Snapshot Isolation'' prevent phantom reads?', N'Senior', N'Snapshot Isolation uses Multi-Version Concurrency Control (MVCC) to provide each transaction with a consistent view of the database as it existed at the start of the transaction. By reading from a versioned snapshot rather than the live data, the transaction is immune to changes made by concurrent processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd4d42c7-c501-4a58-810d-9b884834690f', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is it important to use salted hashes instead of plain hashes for storing passwords?', N'Middle', N'Salting adds a unique, random value to each password before hashing, which prevents attackers from using precomputed tables like Rainbow Tables to crack passwords. It ensures that identical passwords result in different hash values, significantly increasing the difficulty of brute-force attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
