INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eac44795-7b07-4dd3-a927-9b8de329dfa5', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is an implicit transaction?', N'Intern', N'An implicit transaction is one where the database system automatically handles the starting and committing of a transaction for every individual statement. The user does not need to explicitly define the transaction boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37a26eba-2000-4709-940a-9b90281dc31b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does ''cache-control'' header management impact browser and proxy caching?', N'Senior', N'These headers inform intermediary proxies and browsers how long to cache a resource and whether it must be revalidated before use. Misconfigured headers can result in users seeing stale data indefinitely or excessive load on the origin server due to bypassed caches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02ee333e-2842-4033-9c10-9b91da4445ad', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the @Singleton annotation?', N'Intern', N'The @Singleton annotation declares that a class should be instantiated only once by the Micronaut container. This instance is then shared throughout the application wherever the bean is injected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4c46199-8b5f-4746-92ff-9b94431b4f66', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the benefits of using ''sealed classes'' over standard enums?', N'Middle', N'Sealed classes allow for restricted class hierarchies where a type can only have a predefined set of subclasses. Unlike enums, each subclass can contain its own state and data, making them ideal for representing complex states in a type-safe and exhaustive manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2344317-5477-4e34-abfd-9b98da9571f5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do browser preload scanners optimize page load performance?', N'Senior', N'A preload scanner is a secondary lightweight parser that runs ahead of the main HTML parser. It identifies and initiates network requests for high-priority resources like stylesheets, scripts, and images before the main parser discovers them, effectively parallelizing resource loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33f9fc0f-c634-43ce-95e5-9b9bbcbcc5d2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of the Partition Key and Sort Key in DynamoDB''s physical data layout?', N'Senior', N'The partition key determines the physical partition where the item is stored, while the sort key determines the physical order of items within that partition. This composite structure enables efficient range queries and complex data modeling by colocation of related items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34c1fe48-179b-4d69-b5b8-9b9c476c389b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a deinitializer in a class?', N'Fresher', N'A deinitializer is called immediately before a class instance is deallocated from memory. It allows you to perform cleanup tasks like closing files or removing observers before the object is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a3f699d-2f29-497f-9420-9b9c9a108862', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where you discover a security vulnerability in a piece of code you just wrote?', N'Fresher', N'I would immediately inform my lead or team, document the vulnerability, and prioritize fixing it before deploying the code to production. Transparency and taking immediate action to mitigate risks are essential for maintaining system integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30aba9a7-7ede-426b-a359-9b9ca2280bc6', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''MEDIA_ROOT'' setting?', N'Intern', N'MEDIA_ROOT is the absolute filesystem path to the directory where user-uploaded files are stored. It is distinct from the static files directory and is used to manage files uploaded by users through forms, such as profile pictures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1342b6d-eba2-49ea-911c-9b9f2e8671ef', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it better to troubleshoot in a clean, minimal environment?', N'Intern', N'A minimal environment reduces noise and potential interference from unrelated background processes or configurations. This makes it easier to observe the direct impact of your inputs and verify the behavior of the specific component under test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'601b1447-5bab-47a7-82a8-9ba1124e5e32', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary purpose of Remix as a web framework?', N'Intern', N'Remix is a full-stack web framework designed to focus on web standards and modern user experience. It leverages server-side rendering and data loading patterns to ensure that applications are fast, resilient, and work well even with limited network connectivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ef6267-b2ec-4106-847d-9ba26c230a81', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit''s environment variables (@sveltejs/env) ensure security?', N'Senior', N'SvelteKit differentiates between private and public environment variables through naming conventions. Private variables are only accessible in server-side code, preventing accidental leakage into the client-side bundle, which is crucial for protecting database credentials and API secrets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'771b0ce3-c9d3-446c-86e9-9ba39113bba8', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain how ASP.NET Core handles authentication and authorization separation.', N'Senior', N'Authentication verifies the identity of the user via schemes like JWT or cookies, while authorization determines what that identified user is permitted to do. Decoupling these allows for flexible policy-based authorization where access decisions can be based on claims, roles, or complex custom requirements independent of the authentication provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7037f142-ed47-4baa-80f2-9ba6ebd14ddc', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle cookies?', N'Fresher', N'Fiber provides simple methods to set and get cookies directly from the request and response. It simplifies the process of reading values sent by the client or setting security flags on cookies sent to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53b94a1c-d3fb-4bc0-8042-9ba7aba6560f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is TTL in Redis?', N'Intern', N'TTL stands for Time-To-Live. It is a property that can be set on a key to define how long it should exist before Redis automatically deletes it from memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84c79773-2604-42f1-a565-9baa9ce5a99d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach the estimation of cloud migration costs for an on-premises legacy system?', N'Senior', N'I conduct a thorough audit of the current resource utilization and map it to cloud equivalents, accounting for data egress, storage costs, and managed service premiums. I also include a buffer for operational adjustments needed to refactor legacy code to be cloud-native.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b321118-0b1b-4467-b416-9baae062d098', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the default behavior of Actix-web regarding thread management?', N'Fresher', N'Actix-web automatically spawns a number of worker threads based on the number of logical CPU cores available. This allows the framework to scale horizontally across multiple cores automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a33bdac-9d1c-4a43-94c4-9bafd4845824', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is it important to use ''createResource'' for data fetching?', N'Junior', N'CreateResource is designed specifically to handle asynchronous data fetching by providing reactive states for loading, error, and success. It integrates seamlessly with Solid''s suspense and transition features to provide a smooth user experience during data operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d74fb3c-382a-4ead-86a6-9bb27b529d98', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the impact of data consistency requirements on system latency?', N'Middle', N'Strict consistency requires all nodes to agree on the state of the data before a request completes, which increases latency and limits availability. Relaxing consistency to ''eventual consistency'' allows for lower latency and better scalability in geographically distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b75013-29bb-457e-8e01-9bb312ef772f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the advantage of using the ''Responder'' trait?', N'Middle', N'The Responder trait allows any type to be converted into an HTTP response. It enables flexible return types in handlers, letting developers return custom structs, strings, or JSON, which the framework automatically serializes and sends to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc2cce63-fd81-49ae-bd4f-9bb5faa7bc9c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the impact of a large object heap (LOH) allocation on memory fragmentation?', N'Senior', N'Objects over 85,000 bytes are allocated on the LOH, which is not compacted by default to avoid the high cost of moving large memory blocks. This leads to fragmentation over time, potentially causing OutOfMemoryExceptions even when total free memory appears sufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbe97b4e-040c-414c-a9ac-9bb80da3d510', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is Fiber considered ''Express-like''?', N'Fresher', N'Fiber adopts a similar API structure to Express.js, including the use of middleware stacks, route definitions, and request/response context objects. This design choice makes it very approachable for developers who prefer a minimalist and intuitive routing syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0b35700-d9bf-4dd3-9aac-9bbc56a2966e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the ''app'' directory?', N'Fresher', N'The app directory contains the core logic of the application, including models, controllers, middleware, and service providers. This is where most of your custom code will reside as you build the functionality of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fa6a69d-c4f3-4102-bf34-9bc355af5521', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the trade-offs of using ''Message Priority'' features in a queue?', N'Senior', N'Priority queues allow critical tasks to bypass regular ones, but they often lead to ''starvation'' of lower-priority messages. Furthermore, implementing strict priority at scale significantly complicates the broker''s internal logic, often leading to performance degradation as the queue grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeeb506a-41ba-4cf1-b5bd-9bc37327ea0d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass loops?', N'Fresher', N'Sass loops, such as @for, @each, and @while, allow you to generate CSS dynamically. They are extremely useful for creating repetitive styles, like generating a series of margin or padding classes without writing them out manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbdf51a1-1fcb-4990-9368-9bc614bdf511', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API request validation to minimize surface area for attacks?', N'Senior', N'Validation should occur at the edge or gateway level using strict JSON schemas to reject malformed requests early. Beyond structural validation, business logic validation must be enforced at the service level to prevent injection attacks and ensure data integrity within the internal domain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b67ab1cc-ae0f-4b0e-ac52-9bca645a3f7c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you handle pagination in DynamoDB, and what is the role of the LastEvaluatedKey?', N'Senior', N'DynamoDB limits the amount of data returned in a single response to 1MB. When the result set exceeds this, the service returns a LastEvaluatedKey, which acts as a pointer to the next set of data. The client must use this token in subsequent requests to continue the operation, ensuring the database does not overwhelm the client or the system memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61f70d6f-82e2-4388-a298-9bcb41a0fe27', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the architectural trade-off between using Tailwind''s arbitrary values and extending the theme configuration.', N'Senior', N'Extending the theme configuration enforces strict design tokens, ensuring global consistency and maintainability. Using arbitrary values provides flexibility for unique, one-off layouts but risks design drift and violates the principle of a constrained design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42a40de4-b0b7-4323-b02b-9bcb59524e9d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the trade-offs of using Entity Framework Core versus Dapper in high-performance ASP.NET Core scenarios?', N'Senior', N'EF Core provides high developer productivity through abstraction but can introduce overhead due to change tracking and complex query generation. Dapper offers near-native performance by mapping SQL results directly to objects, but requires manual query management and lacks the safety of an abstraction layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba6ec7c-5ad3-4446-bbcc-9bcf1ec2697c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How are SolidJS components different from standard functions?', N'Fresher', N'SolidJS components are simple functions that run only once during initialization. They define the structure and set up reactive bindings, unlike React components which re-run whenever state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b72c652e-989b-458f-90dc-9bd03f52b5dd', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the advantage of using SvelteKit for SEO?', N'Fresher', N'Because SvelteKit renders the page content on the server, search engine crawlers receive fully formed HTML. This is much more effective for SEO compared to client-side rendered apps, where crawlers might struggle to see the content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d8c6550-45a2-48a1-9868-9bd061deba17', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the trade-off between performance and simplicity in Actix compared to high-level frameworks?', N'Middle', N'Actix offers high performance and fine-grained control over concurrency at the cost of higher complexity. Developers must manage lifetimes, message passing, and async/await syntax, which is more demanding than using frameworks that hide these details behind simpler abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f66f8b5a-cdcb-4a3b-bf31-9bd0d564e8f1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you handle HTTP status codes in Fiber?', N'Intern', N'Fiber provides a set of constants representing standard HTTP status codes, such as StatusOK or StatusNotFound. Developers use these constants when sending responses to clearly indicate the outcome of an operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11c8fa92-59a0-40b2-ad96-9bd1b7d40212', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary difference between Quarkus and traditional Java frameworks?', N'Intern', N'Traditional frameworks perform most dependency injection and configuration processing at runtime. Quarkus performs much of this work during the build phase, which significantly reduces the startup time and memory footprint of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dff892ec-4c39-4019-9b74-9bd42476ac94', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are pure functions and side effects in the context of Redux?', N'Intern', N'In the context of Redux, actions alter state through reducers, and middlewares handle side effects. It''s essential that reducer functions be pure to ensure predictability in state changes. Fundamental Concepts - Actions: Objects describing a state change. - Reducers: Pure functions defining the state change. - State: An immutable object accessible throughout the app. Pure Functions Reducers must be pure, that is, their behavior should be entirely predictable. - Determination of Output: Output should be a direct result of input. The function should not base its output on any external state or data. - No Side Effects: They should not cause alterations outside their scope, like modifying global variables or invoking functions that perform I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc3d4bb8-36d3-4453-9045-9bd45821b766', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React Fiber?', N'Intern', N'React Fiber is the new reconciliation engine in React, introduced in React 16. It’s a complete rewrite of React’s core algorithm(old stack-based algorithm) for rendering and updating the UI. Fiber enhances React’s ability to handle asynchronous rendering, prioritized updates(assign priority to different types of updates), and interruption(ability to pause, abort, or reuse work) of rendering work, enabling smoother and more responsive user interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ac7bf27-ab43-454a-a0d6-9bd895bcb00a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are validations in Rails models?', N'Junior', N'Validations are rules defined in models to ensure that only valid data is saved to the database. They prevent errors like saving a user record without an email address or a product with an invalid price.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
