INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c173fe73-02c9-45fa-98a0-9bdcb88167ac', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s plugin architecture differ from modern package-based dependency management?', N'Senior', N'jQuery plugins are often globally scoped, lack formal versioning constraints, and usually require manual loading order management. Modern ecosystems use modular dependency managers like NPM, which allow for better scope encapsulation, dependency tree resolution, and automated build-time checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
