INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc8b2ee8-d6c1-431a-b420-9be321dfe880', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'In what scenario would you choose to use ''force merge'' on an index?', N'Senior', N'Force merge is used on read-only indices to collapse segments into a single file or a small number of files. This is typically done after index lifecycle movement to a cold tier to optimize storage footprint and improve search performance, as fewer segments mean fewer files to open and scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a133b9b-ce8d-4ebe-a8ca-9be4eb047f5d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where you discover your chosen approach will not work midway through a task?', N'Intern', N'I immediately stop the current path to prevent further wasted effort and perform a quick retrospective to understand why the approach failed. I then document the findings and propose an alternative strategy based on the new information. Communication with stakeholders is key to resetting expectations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
