INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21c50f60-9d2d-46c3-8cc3-9bea6dfc6f58', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s implementation of ''Symbols'' optimize memory and performance compared to ''Strings''?', N'Senior', N'Symbols are immutable, interned strings that are stored uniquely in memory, which allows for faster comparison and reduced allocation overhead when used as hash keys or method identifiers. While they improve performance, they are not garbage collected in older Ruby versions, leading to potential memory leaks if they are generated dynamically from untrusted user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
