INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96392e36-be8f-41b7-93df-9c098adb4c31', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a shallow copy and a deep copy in Go, and why does it matter?', N'Middle', N'A shallow copy duplicates the structure but references the same underlying data for pointers or slices, while a deep copy recursively duplicates all referenced data. Understanding this is vital to avoid unintended side effects where modifying a copy unexpectedly alters the original data structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba305532-dc5d-4be5-87a4-9c09b7e6baf9', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js optimize images?', N'Intern', N'Next.js provides an Image component that automatically optimizes images for the browser. It handles resizing, compression, and serving images in modern formats like WebP to ensure faster loading times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9f3bcda-6a18-4bfc-9d11-9c0caf560617', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Is Alpine.js suitable for large, complex state management?', N'Intern', N'Alpine.js is best suited for small-to-medium interactions and simple state management. For very large or global state management needs, Alpine offers a ''store'' feature, but it is generally recommended to use more robust state management tools for highly complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6286bbe-b8b1-46f8-b78e-9c0df44a8435', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is difference between promises and async-await in Node.js?', N'Fresher', N'1. Promises: A promise is used to handle the asynchronous result of an operation. JavaScript is designed to not wait for an asynchronous block of code to completely execute before other synchronous parts of the code can run. With Promises, we can defer the execution of a code block until an async request is completed. This way, other operations can keep running without interruption. States of Promises: * Pending: Initial State, before the Promise succeeds or fails. * Resolved: Completed Promise * Rejected: Failed Promise, throw an error Example: 2. Async-Await: Await is basically syntactic sugar for Promises. It makes asynchronous code look more like synchronous/procedural code, which is easier for humans to understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4caa3081-e540-4fb1-b9fc-9c1281d801d4', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS handle the trade-off between build-time performance and bundle size in large-scale applications?', N'Senior', N'Tailwind uses Just-in-Time (JIT) compilation to generate CSS only for the utility classes actually used in the project. This prevents the generation of massive, unused CSS files and ensures the build remains performant by processing tokens on demand rather than pre-generating a full library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c525ea0b-5486-4bf7-afc0-9c16b33b860d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the importance of ''Health Checks'' in a load-balanced environment?', N'Senior', N'Health checks inform the load balancer when a service instance is unable to process requests, allowing the balancer to remove the node from the pool. This ensures traffic is only routed to healthy instances, maintaining high availability for end-users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15cb80ad-a6c4-4dc8-b0af-9c19f2fc455f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono facilitate testing?', N'Middle', N'Since Hono is based on the Fetch API, you can test routes by passing standard Request objects to the app and inspecting the returned Response. This allows for unit and integration testing without needing to start a local network server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62b16a52-c2a4-44d2-80ec-9c1d2a6c1a72', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the common benefits of using Echo over a full-featured web framework?', N'Junior', N'Echo is lightweight and provides better performance, making it easier to understand and debug. It provides just enough structure for API development without forcing complex patterns or unnecessary dependencies on the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'316aa6d4-dedf-4eb7-a3ab-9c1fd3ff0db1', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s middleware stack differ in performance compared to the standard library''s net/http middleware approach?', N'Senior', N'Chi utilizes a lightweight, chainable middleware pattern that integrates natively with the standard library''s http.Handler interface. Because it avoids complex reflection and maintains a flat execution chain, it incurs minimal overhead while remaining fully compatible with the standard ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fec3f5f-b9d8-4fdb-ae61-9c2004258621', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you reason about the trade-off between technical debt and shipping a feature on time?', N'Middle', N'I would assess whether the debt introduces immediate risk to system stability or creates long-term maintenance costs that outweigh the benefit of the feature launch. If the business value of the deadline is critical, I would document the debt as a formal task in the backlog to be addressed in a dedicated sprint immediately following the release.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'279562a0-c82d-4e83-b65a-9c23ca228d13', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of Symfony''s ''public'' directory?', N'Fresher', N'The public directory is the only folder accessible from the web server. It contains the front controller, index.php, and static assets like CSS, JavaScript, and images, ensuring that sensitive application files remain protected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abef2554-32b5-4f75-b12d-9c23f593cc59', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why do we use environment variables for sensitive information like API keys?', N'Intern', N'Storing sensitive information in environment variables prevents them from being hardcoded directly into the source code, which is a major security risk. By keeping these keys outside the codebase, we ensure they are not accidentally committed to version control systems. This also allows for different configurations across development, testing, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c62a2a63-9fc7-4c3b-a9e0-9c2634b4b78a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the function of the plus-server.svelte file?', N'Junior', N'Actually, it is named plus-server.js or .ts, and it is used to create API endpoints. It allows you to handle HTTP requests like GET, POST, or DELETE directly within your application without needing an external backend server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5efaed11-42e3-459e-8136-9c2a059e8018', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are The Data Types Supports in Python Language?', N'Intern', N'- Numbers- Numbers use to hold numerical values. - Strings- A string is a sequence of characters. We declare it using single or double quotes. - Lists- A list is an ordered collection of values, and we declare it using square brackets. - Tuples- A tuple, like a list, is an ordered collection of values. The difference. However, is that a tupleis immutable. This means that we cannot change a value in it. - Dictionary- A dictionary is a data structure that holds key-value pairs. We declare it using curly braces. - We can also use a dictionary comprehension: Numbers: Int Float Complex Boolean Operational: Strings List Tuple Set Dictionary Every data type in python language is internally implemented as a class. Python language data types are categorized into two types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c0de09a-721d-4aaf-a69c-9c2b52bca688', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the performance impact of introducing a new cache layer into an existing data pipeline?', N'Senior', N'I would calculate the cache hit-to-miss ratio based on access patterns and evaluate the latency added by cache synchronization versus the latency saved by avoiding backend hits. I would also consider the eviction policy and the potential for cache stampedes during high-traffic events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6f800b9-8b09-4c2b-b8b5-9c2cbea2eca6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do you handle large datasets that exceed the available RAM in Redis?', N'Junior', N'When memory is full, Redis can be configured with an eviction policy, such as LRU (Least Recently Used), to remove older or less frequently used keys. Alternatively, you can scale horizontally using Redis Cluster to distribute the data across multiple physical nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66fa6a59-563a-416d-8914-9c2dce1689fd', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you establish and enforce CSS coding standards across a team?', N'Fresher', N'Standards reduce inconsistency, prevent specificity wars, and make stylesheets maintainable as the codebase grows. They must be automated, documented, and agreed upon — not enforced only through code review. Tooling layer (automated enforcement): Configure husky + lint-staged to run Stylelint and Prettier on every commit. Block merges in CI if linting fails. Documentation layer: * Maintain a Style Guide (docs/css-guide.md) covering naming convention (BEM, utility-first, etc.), file organization, when to use custom properties vs. hard-coded values, and how to handle z-index. * Record significant architecture decisions (e.g., "We use CSS Modules instead of global stylesheets") in ADR files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe4a2990-4ade-4246-b1de-9c3054776efa', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the storage capacity required for a new database system?', N'Intern', N'I would start by estimating the average size of a single data entry and multiplying it by the expected number of records over a specific timeframe. I would then add a buffer for system overhead, logs, and potential future growth to ensure the estimate accounts for long-term operational needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49f405c4-0712-4313-8a05-9c31299a068b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the function of the Swift compiler''s ''Specialization'' pass?', N'Senior', N'Specialization is a compiler optimization where generic functions are converted into concrete implementations for specific types used at call sites. By replacing abstract generic code with specialized versions, the compiler can inline operations and bypass dynamic dispatch overhead, significantly improving execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
