INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d317d6d-7659-41ce-8a5e-9c3562349602', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Ecto handle transactions?', N'Middle', N'Ecto uses the ''multi'' function to group multiple database operations into a single atomic transaction. If any operation within the multi fails, the entire set of changes is rolled back, ensuring data integrity across complex related changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5489d22-e48b-4cf9-af53-9c375d0ca6db', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does multi-version concurrency control (MVCC) improve database performance?', N'Senior', N'MVCC allows multiple versions of a data item to coexist, enabling readers and writers to operate simultaneously without blocking each other. This significantly improves concurrency in high-read systems by allowing readers to access a consistent snapshot of the data without needing exclusive locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20122bb9-a8ca-4535-a0ec-9c3abc7fb846', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage transactions?', N'Middle', N'Micronaut provides a declarative transaction management system, typically through integration with Jakarta Transactions. By using annotations on service methods, the framework handles the opening, committing, and rolling back of database transactions automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'180f45d1-6907-4e18-a0e7-9c40d59911a8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between a class and an object in Scala?', N'Intern', N'A class is a blueprint for creating objects, while an object is a single, pre-instantiated entity. Classes support instantiation with the ''new'' keyword, whereas objects are accessed directly as static-like instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84d38426-0941-4866-84df-9c453bca7330', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''thundering herd'' problem and how can it be mitigated at the cache layer?', N'Senior', N'The thundering herd problem occurs when a high-traffic cache key expires, causing many concurrent requests to hit the underlying database simultaneously, potentially overwhelming it. This is mitigated using techniques like cache locking, probabilistic early expiration, or using a background refresh mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42fbb1bb-8e82-4c8d-878e-9c455468f1a4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Discuss the challenges of integrating non-Qwik libraries into a Qwik application.', N'Senior', N'Integrating third-party libraries is challenging because Qwik expects fine-grained control over execution. Libraries that rely on heavy initialization, global side effects, or non-serializable state often break Qwik''s resumability model, requiring custom wrappers to delay execution until necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f365a78-e6a4-4815-841b-9c4731213036', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript’s ''strictFunctionTypes'' flag alter the assignment compatibility of function types?', N'Senior', N'Enabling this flag enforces stricter contravariant checking for function parameters, which prevents unsafe assignments that might occur with bivariance. It ensures that a function can only be assigned to a signature if its parameters are at least as general as the target signature.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a8024a9-3964-47c1-816f-9c47dbd7d1ee', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the CAP theorem and how does it influence database design?', N'Senior', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the context of database design, it forces architects to choose how the system will behave during a network partition, prioritizing either data correctness or service availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72fe16c7-e8ef-4ff9-98cb-9c48b0486e64', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a feature that involves file uploads, why is it better to upload files to cloud storage rather than the server''s local disk?', N'Fresher', N'Uploading files to a local disk makes the server stateful and difficult to scale, as files would not be accessible by other server instances. Cloud storage provides a centralized, scalable, and highly available location for assets. This architecture ensures that all server instances can access the same files regardless of which one handled the upload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cbd9ea9-60c2-4fc9-8b80-9c4a40f1694e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the significance of Hono’s ''Middleware-first'' architecture in debugging complex request flows.', N'Senior', N'The middleware-first architecture treats every request processing step as a distinct, observable unit, making it straightforward to inject tracing or logging middleware at any point in the flow. This granular observability allows developers to pinpoint exactly which stage of the request lifecycle failed, which is far more efficient than debugging through monolithic controller functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc8531d1-dd16-45df-b5d3-9c4b4d3d2cfa', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala handle multiple inheritance issues like the Diamond Problem?', N'Middle', N'Scala uses trait linearization to resolve the order in which methods are called when multiple traits are mixed into a class. It assigns a deterministic sequence to the traits, ensuring that method calls follow a specific hierarchy and avoiding the ambiguity found in languages with traditional multiple inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec0f8419-00f2-4bf6-97ce-9c4b51a70282', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is Active Record?', N'Intern', N'Active Record is the Object-Relational Mapping (ORM) layer of Rails. It allows you to interact with database tables as if they were standard Ruby objects, enabling you to perform database operations like creating, reading, updating, and deleting records using simple method calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50ea74a7-9d14-43f2-bbab-9c5190ebab87', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt support internationalization (i18n)?', N'Middle', N'Nuxt supports i18n through official modules that handle route prefixing, language switching, and translation loading. These modules integrate with the Nuxt lifecycle to ensure that the correct language is served based on the URL or user preferences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab7458f2-54fc-4330-861e-9c53f686c53f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off involved in adding comprehensive logging to an application?', N'Fresher', N'Logging is essential for debugging and monitoring, but excessive logging can consume significant disk space and disk I/O performance. The goal is to log enough information for troubleshooting without impacting the system''s runtime efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bcac9a2-14d5-4681-a1f5-9c5854227137', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Either'' type improve error handling architectures compared to throwing exceptions?', N'Senior', N'Exceptions bypass normal control flow and can be easily ignored, leading to unstable systems. ''Either'' forces the error to be part of the method''s signature, necessitating explicit handling and providing a type-safe way to represent alternative outcomes, which leads to more predictable and resilient error management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0425409-52a9-4e42-8788-9c59e05d77e1', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What additional methods for working with associative arrays (maps) appeared in Java 8?', N'Junior', N'* putIfAbsent() adds a key-value pair only if the key was missing: * forEach() accepts a function that performs an operation on each element: * compute() creates or updates the current value to the result of the calculation (it is possible to use the key and the current value): * computeIfPresent() if the key exists, updates the current value to the result of the calculation (it is possible to use the key and the current value): * computeIfAbsent() if the key is missing, creates it with the value that is calculated (it is possible to use the key): * getOrDefault() if there is no key, returns the passed value by default: * merge() accepts a key, a value, and a function that combines the transmitted and current values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd5bd942-0cef-4078-954f-9c5a09ab58cc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the trade-offs of using ''enum'' versus ''union types'' for representing a set of fixed values?', N'Senior', N'Enums are a TypeScript-specific feature that exists at runtime, which can cause issues with tree-shaking and module bundling. Union types are erased at compile time, providing better performance and smaller bundle sizes while offering the same level of type safety for fixed sets of values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7a5e425-a116-4fc8-8a5a-9c5e8ed3de25', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of ''Covering Indexes''.', N'Middle', N'A covering index is an index that includes all the columns requested in a specific query. Because all necessary data resides within the index structure itself, the database engine avoids a costly lookup to the main table, significantly improving query speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98b21178-e28d-4197-8ef1-9c6061b46c2a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the MongoDB commands for deleting documents?', N'Intern', N'MongoDB offers several methods for deleting documents. Deletion Methods in MongoDB 1. deleteOne(): Deletes the first matched document. 2. deleteMany(): Removes all matching documents. 3. remove(): Legacy function; use deleteOne() or deleteMany() instead. General Syntax - For deleteOne(), the syntax is: - db.collection.deleteOne({filter}, {options}) - For deleteMany(), the syntax is: - db.collection.deleteMany({filter}, {options}) Code Example: Deleting One or Many Here is the MongoDB shell script: Explore all 100 answers here 👉 Devinterview.io - MongoDB', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6545fd28-35d0-4154-9554-9c60c46502ed', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between a synchronous and an asynchronous operation in a real-world scenario?', N'Junior', N'A synchronous operation blocks the main execution flow until the task is complete, which can cause the interface to freeze. An asynchronous operation allows the system to continue working on other tasks while waiting for a response, preventing the user from seeing a frozen screen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7fd725f-8f87-46ad-99fb-9c60ea18da1f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What does the ''Peer'' modifier do?', N'Fresher', N'The peer modifier allows you to style an element based on the state of a sibling element that comes before it in the DOM. This is particularly useful for building form components where you might want to show or hide an error message based on the status of an input field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e31fb24c-a967-4a40-8c01-9c620364a1b2', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the concept of ''Hydration'' in the context of Next.js.', N'Middle', N'Hydration is the process where the static HTML generated by the server is ''attached'' to the React event listeners in the browser. This makes the static page interactive without the user needing to download and execute the entire application logic before seeing content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2057d256-818c-4dfc-b936-9c6225974ddd', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your process for diagnosing an issue where a service is crashing due to an OutOfMemoryError but the heap usage seems normal?', N'Senior', N'I would investigate non-heap memory areas such as the metaspace, thread stacks, or native memory usage, which are common culprits in such cases. I would use OS-level tools to inspect native memory allocations and check if external libraries are leaking memory outside the managed runtime''s garbage collection scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3d80df9-d713-4a93-a376-9c68f2e85f4d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is it important to use ''enum'' types for constants?', N'Middle', N'Enums provide type-safe constants that are more robust than static final integers or strings. They can include methods, fields, and constructors, allowing for more object-oriented design patterns. Using enums prevents invalid values from being passed to methods and improves code readability and maintainability compared to magic numbers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a0b64ec-801b-40b7-a833-9c6c28ae9502', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does using a message queue help handle traffic spikes?', N'Middle', N'Message queues act as a buffer between the request producers and the consumers. During sudden traffic spikes, requests are queued rather than overwhelming the backend, allowing the system to process tasks at a sustainable rate without crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81f14d7c-0376-4e9e-97ec-9c6cb47b3b8b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between session storage and local storage?', N'Junior', N'Local storage persists data even after the browser window is closed, while session storage clears the data as soon as the tab or window session ends. Both are used for storing key-value pairs in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3ffac7b-a2bd-48d4-b84b-9c6e41108a2b', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you invoke a builder?', N'Fresher', N'The Angular CLI command ng run is used to invoke a builder with a specific target configuration. The workspace configuration file, angular.json, contains default configurations for built-in builders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21e84f5e-0f8a-432e-a2d9-9c6f49130146', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to use connect() from React Redux?', N'Fresher', N'You need to follow two steps to use your store in your container: 1. Use mapStateToProps(): It maps the state variables from your store to the props that you specify. 2. Connect the above props to your container: The object returned by the mapStateToProps function is connected to the container. You can import connect() from react-redux.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29cb4433-6daf-4dd5-be68-9c7005c15791', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the Cache facade?', N'Intern', N'The Cache facade provides a unified API for various caching backends. It allows you to store and retrieve frequently accessed data quickly, which significantly improves the performance of your application by reducing database load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab06e4a0-5259-49cc-8ed3-9c73c4c3741d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Explain your strategy for handling a cascading failure in a microservices environment.', N'Senior', N'I would implement circuit breakers at each service boundary to prevent the propagation of failures and integrate bulkhead patterns to isolate resource pools. Additionally, I would prioritize graceful degradation by returning cached or default responses when downstream dependencies are unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
