INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cce890ab-e027-4fc2-b0ca-9c7816066458', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the trade-offs of using a persistent message queue versus an in-memory queue?', N'Middle', N'Persistent queues write messages to disk, ensuring data durability during system crashes but at the cost of higher latency. In-memory queues offer extremely high throughput and low latency but risk losing data if the broker process fails or restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1006fae5-0d63-4947-8610-9c7a1a6fb665', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the concept of a ''null'' value?', N'Fresher', N'A null value in a database represents the absence of data or an unknown value in a specific field. It is distinct from a zero or an empty string, as it indicates that no data has been provided for that attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7d9482b-3667-45db-a37c-9c7cc5c0293f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does x-html work?', N'Intern', N'The x-html directive renders raw HTML content inside an element based on a variable in the component state. It is useful when you need to inject dynamic strings that contain HTML tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d66201a-cceb-4b57-9a14-9c7de8b0cd2e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Describe the purpose of the ''willUpdate'' lifecycle method in a Lit component.', N'Senior', N'The ''willUpdate'' method is called before the component renders, providing a hook to compute derived state or perform side effects based on property changes. It is the ideal place to synchronize internal state that depends on updated properties before the template is generated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cef4773-8fb2-4953-87f5-9c8178256228', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it important to consider the ''box-sizing'' model when developing reusable components?', N'Senior', N'The default content-box model includes padding and borders outside the specified width, which often causes components to overflow their containers when styles are composed. Switching to border-box ensures that padding and borders are included within the element''s width, making layout calculations predictable and preventing unintended structural breakage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11e64496-02aa-417e-8783-9c8204a03806', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a nullable type in Kotlin?', N'Intern', N'A nullable type is a type that can explicitly hold a null value in addition to its defined type. These are denoted by adding a question mark to the type name, requiring the developer to handle potential null cases before accessing the variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f9ff878-8833-46b2-be66-9c85f826ad82', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does CSS work under the hood?', N'Senior', N'The CSS language is designed to be used alongside a "markup" language like HTML. CSS defines how HTML elements are formatted – controlling their layout, colors, fonts, and so on. When a browser displays a document, it must combine the document''s content with its style information. It processes the document in a number of stages, which we''ve listed below. 1. The browser loads the HTML (e.g. receives it from the network). 2. It converts the HTML into a DOM (Document Object Model). 3. The browser then fetches most of the resources that are linked to by the HTML document, such as embedded images and videos and linked CSS. 4. The browser parses the fetched CSS, and sorts the different rules by their selector types into different "buckets", e.g. element, class, ID, and so on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adc9c696-70c7-49de-9acb-9c894ac89870', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between batch processing and stream processing for data analysis?', N'Junior', N'Batch processing is simpler to implement and efficient for large volumes of historical data. Stream processing enables real-time insights and decision-making, but it is significantly more complex to architect and requires specialized infrastructure to handle data flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9243b41c-ba53-463f-9d76-9c8ebb9f27f2', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle asynchronous operations?', N'Junior', N'Actix is built on top of the Tokio runtime, which provides the foundation for asynchronous I/O in Rust. It utilizes the async/await syntax to perform non-blocking operations, allowing a single thread to handle many concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f28cad-4b31-4700-b58a-9c8f44ee99f0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is it recommended to use DTOs (Data Transfer Objects) in NestJS?', N'Middle', N'DTOs define the shape of data sent over the network, providing a contract for incoming requests. They enable type safety and, when combined with validation pipes, ensure that the application logic only processes sanitized and structured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d861295-b612-406a-a83b-9c8fbbc4272b', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the Redux store in a frontend application?', N'Intern', N'The Redux store serves as a centralized container that holds the entire state tree of an application. By keeping the state in one place, it makes it easier to track changes, debug, and ensure that data remains consistent across different components. It acts as the single source of truth, preventing the need to pass data manually through many layers of nested components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0c649e7-80ea-4283-b260-9c920b1e4b69', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle error propagation within plugins?', N'Middle', N'Errors in Fastify bubble up through the plugin hierarchy until they are caught by an error handler. If no local error handler is defined for the specific plugin context, the error propagates to the global error handler, ensuring centralized logging and response formatting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a355dcd8-1f57-4455-a74c-9c9272766b10', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of ''API Versioning'' from a security perspective?', N'Senior', N'API versioning allows for the deprecation and removal of vulnerable or insecure endpoints without breaking existing clients. It provides a controlled path for enforcing new security standards, such as migrating from outdated authentication protocols to modern ones, while maintaining backwards compatibility for legitimate users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e88694c5-a932-472b-a753-9c96489163cb', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the role of the Echo Context object in memory management during high-concurrency requests.', N'Senior', N'The Context object is pooled using sync.Pool to reduce garbage collection pressure by reusing instances across requests. This is a critical optimization for high-throughput systems, though it necessitates that developers do not store references to the context outside of the request scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b03015-df3a-4a06-acc5-9c968a5b6027', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is the HTML markup often longer when using Tailwind?', N'Junior', N'The markup is longer because all styling information is explicitly defined in the class attribute. While this makes the HTML look busy, it makes the code much easier to read and maintain because you do not have to jump to a separate CSS file to see how an element is styled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64f8b64a-409f-4d59-be72-9c975a3902e7', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is SQL Injection, and how can it be mitigated at the architectural level?', N'Middle', N'SQL Injection occurs when malicious input is inserted into database queries, allowing unauthorized data access. It is best mitigated by using parameterized queries or prepared statements, which separate the SQL code from the user-provided data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'843fe013-fff4-4509-b8f4-9c976c6f8adc', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is Tailwind CSS suitable for legacy projects, and how would you implement it?', N'Middle', N'Tailwind can be integrated into legacy projects by using the prefix option to avoid class name collisions with existing CSS. It can be adopted incrementally, allowing teams to start using Tailwind for new features while gradually refactoring old styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11069857-cade-4909-bcf6-9c996bbc749b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS achieve ''fine-grained'' updates in lists using ''For'' or ''Index'' components?', N'Senior', N'The ''For'' and ''Index'' components use specific reconciliation algorithms that track individual items in an array. Instead of re-rendering the entire list, they only update, move, or remove the specific DOM nodes corresponding to the changed array elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95a663b7-33dd-4d51-89c0-9c99e035ef5c', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the trade-offs between using symmetric and asymmetric encryption for data at rest?', N'Middle', N'Symmetric encryption is significantly faster and more efficient for encrypting large volumes of data. Asymmetric encryption is computationally expensive but is better for secure key exchange, which is why systems often use a hybrid approach of encrypting data with a symmetric key and wrapping that key with an asymmetric one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd919f7f0-4ee3-4a43-baf7-9c9bca706a57', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of the ''links'' export in Remix route modules?', N'Middle', N'The links function allows you to define route-specific assets like stylesheets or pre-fetch hints that are only loaded when that specific route is active. This promotes better performance by reducing the total bundle size and ensuring that the browser only downloads the resources required for the current view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0996d14-3ec5-4c5b-8780-9c9cc9ceb7ea', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is memory footprint important in Quarkus applications?', N'Intern', N'Lower memory usage allows you to run more application instances on the same amount of hardware. This is particularly important in cloud environments where you pay for memory consumption and need to scale instances up or down quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'927e7534-5cdf-47bc-b446-9c9d8f748a3c', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the ''final'' keyword in Swift classes?', N'Middle', N'The final keyword prevents a class from being subclassed or a method from being overridden. This allows the compiler to use static dispatch instead of dynamic dispatch, which improves performance and provides design clarity by explicitly locking down an implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a2418c3-4e03-4451-bd17-9ca06f168489', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the Java Memory Model in multi-threaded applications?', N'Middle', N'The Java Memory Model defines the rules for how threads interact through memory, specifically regarding visibility, ordering, and atomicity. It ensures that changes made by one thread to shared variables are visible to others by establishing happens-before relationships. This is critical for writing thread-safe code without relying on low-level hardware specifics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1541002-c3ab-4991-8e78-9ca0b018ec64', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Non null type assertion operator?', N'Intern', N'You can use the non-null type assertion operator to suppress the Object is possibly ''undefined'' error. In the following example, the user and contact properties are always set together, implying that contact is always non-null if user is non-null. The error is suppressed in the example by using contact!.email.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca6d546-349f-43d7-ad15-9ca1b4c334f8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does the ''last change'' heuristic help in troubleshooting?', N'Fresher', N'If a system was working fine and suddenly stopped, the last change made to the system is the most probable cause. Reverting or reviewing the most recent configuration or file updates is often the fastest way to restore functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb25393e-04cc-4f10-9062-9ca2b2adccf8', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Why is it important to use Queued Events in a high-traffic Laravel application?', N'Senior', N'Synchronous events block the current request until all listeners have finished, which can lead to significant latency if the listeners perform I/O operations. Queued events move this processing to background workers, freeing up the web server to handle more concurrent user requests, thus improving overall scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bdf700a-7a0a-4a3e-b303-9ca4c8a31c3a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery noConflict mode?', N'Intern', N'NoConflict mode is a feature that releases the control of the dollar sign ($) back to other libraries. It is useful if you are using jQuery alongside other JavaScript libraries that also use the dollar sign as a shortcut.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9784985b-19f7-4485-8136-9ca6825a50cf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a polyfill', N'Intern', N'A polyfill is a piece of JS code used to provide modern functionality on older browsers that do not natively support it. For example, Silverlight plugin polyfill can be used to mimic the functionality of an HTML Canvas element on Microsoft Internet Explorer 7. There are two main polyfill libraries available, 1. Core.js: It is a modular javascript library used for cutting-edge ECMAScript features. 2. Polyfill.io: It provides polyfills that are required for browser needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5c4c802-ff90-4eb2-b82a-9ca826bb575f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery''s chainability considered a double-edged sword?', N'Middle', N'Chainability allows for concise and expressive code by executing multiple operations on the same element set in a single statement. However, it can make debugging difficult because individual steps in a long chain are harder to inspect, and a failure in one link can stop the execution of the entire chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'493cfe07-910a-4661-b603-9ca947e7a3f1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite resolve file paths?', N'Fresher', N'Vite supports path aliases, which allow you to define shortcuts for commonly used directories. This makes importing modules from deep folder structures cleaner by avoiding relative path syntax like ''../../../''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fa7f2de-9409-451a-90cf-9caab91874f9', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the architectural risks of using ''Large Documents'' in a document store?', N'Senior', N'Large documents can lead to performance degradation during updates because the database may need to rewrite the entire document to disk due to size changes. It also increases memory pressure for cache management and can cause network congestion during replication of large payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9f94a62-0aec-46fc-a166-9caefa0f7464', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence your decision to choose between a microservices architecture and a monolithic architecture?', N'Middle', N'A monolith is often better for early-stage development due to simplicity in deployment and testing. I would recommend moving to microservices when the team size grows, specific modules require independent scaling, or different parts of the application need to be deployed at different cadences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33b38b25-8f55-4fd2-9cc1-9caefbaa5a76', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of an acknowledgment (ACK) in a messaging system?', N'Middle', N'An ACK is a signal sent from the consumer to the broker indicating that a message has been successfully processed. The broker uses this to decide when to remove the message from the queue or mark it as delivered, ensuring no data is lost during transit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9bdfed1-1080-4a0c-8832-9cb01dc5f760', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the @Autowired annotation?', N'Junior', N'The @Autowired annotation is used to perform dependency injection by allowing Spring to resolve and inject collaborating beans into your class. Spring attempts to find a matching bean in the container based on the type of the field or constructor parameter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc17599c-147b-4035-b1bb-9cb11dee482b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle middleware execution flow, and how can you stop the chain?', N'Middle', N'Gin uses a chain of handlers where each middleware calls the Next() method to proceed to the next handler in the stack. To stop the execution chain, such as in an authentication failure, you simply return from the current middleware without calling Next() and optionally abort the request context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5146ec22-03b1-4a42-ad98-9cb1ea009a66', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of the ''Security'' dependency in FastAPI?', N'Middle', N'The ''Security'' class is a specialized version of ''Depends'' used for authentication and authorization. It allows you to declare scopes and security requirements that are included in the generated OpenAPI documentation, helping users understand how to authenticate with the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88c4444c-58bb-42ad-a3a9-9cb2c86607dc', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between an Observable and a Subject in RxJS?', N'Middle', N'An Observable is a stream of data that is unicast, meaning each subscriber gets its own independent execution. A Subject is a special type of Observable that is multicast, allowing multiple subscribers to receive the same emitted values simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6f8cb6b-0cc9-4c81-8bd2-9cb3f1729fd7', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is ''std::forward'' essential for implementing perfect forwarding in wrapper functions?', N'Senior', N'Perfect forwarding allows a wrapper function to pass arguments to another function while preserving their original value category, such as lvalue or rvalue. std::forward uses template type deduction to conditionally cast the argument back to its original category, ensuring that move constructors are invoked when appropriate instead of expensive copies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f50d2eb5-68d2-49a0-aa1a-9cb6830eb5b5', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does the Quarkus ''Continuous Testing'' feature improve quality assurance?', N'Senior', N'Continuous testing runs tests in the background as code changes are made during development. By automatically identifying which tests are affected by specific code modifications and executing only those, it provides immediate feedback on regressions without waiting for a full test suite run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8540b036-4cd4-4e0a-b5f9-9cb96ad4520b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does tiered caching improve performance in large-scale systems?', N'Senior', N'Tiered caching uses multiple layers, such as local memory (L1) and a distributed cache (L2), to balance speed and capacity. L1 handles the most frequent requests with minimal latency, while L2 acts as a broader, shared pool to catch requests that missed the local layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dbdc945-754a-4951-9dbf-9cbc433f3275', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Is Vite suitable for production environments?', N'Intern', N'Yes, Vite is designed to be used in production. While its development server is optimized for speed, its production build process produces highly optimized, minified, and bundled code ready for live deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e7fed28-afac-4bdc-9f78-9cbf8fa3e640', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the role of ''Isolation Levels'' in transaction management?', N'Senior', N'Isolation levels define how transaction integrity is visible to other concurrent transactions, ranging from Read Uncommitted to Serializable. They represent a trade-off between consistency and performance, where higher isolation levels prevent anomalies like phantom reads but increase lock contention and decrease parallelism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330edef8-7793-4119-bb2a-9cc13900f509', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle the ''thundering herd'' problem if an application is configured to restart automatically on failure?', N'Senior', N'Express itself does not handle this; it relies on process managers like PM2 or container orchestrators like Kubernetes to implement exponential backoff and health checks. Without these, rapid restarts can overwhelm downstream services or the database, creating a cascade failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec174bb3-753e-4148-b46e-9cc206f32787', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the technical debt versus velocity trade-off in an agile environment?', N'Senior', N'I track the ratio of feature work to maintenance tasks and quantify the slowdown caused by legacy code. I present this to stakeholders as a ''tax'' on future development, justifying scheduled refactoring intervals as a necessary investment to sustain long-term delivery velocity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0efd28a7-4b5e-4be4-86df-9cc33982ac4e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the common ways to handle errors in Fiber?', N'Fresher', N'Fiber allows developers to return errors directly from handlers, which are then caught by a global error handler. This centralized approach keeps the code clean, as you do not need to manually check for errors and write response logic inside every single endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b924ea40-c542-4e7f-a188-9cc383b48b8b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Can Webpack be used for projects without a framework like React or Vue?', N'Junior', N'Yes, Webpack is a general-purpose module bundler that works with any JavaScript project. It is perfectly capable of bundling plain JavaScript, HTML, and CSS without the need for a specific frontend framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6eca35c-26ca-4d28-9573-9cc5c6aebe0e', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Are DynamoDB attributes case-sensitive?', N'Fresher', N'Yes, attribute names are case-sensitive. For example, an attribute named ''UserID'' is treated as distinct from an attribute named ''userid''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1df9cf84-1b7e-4184-a411-9cc702afb8be', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s HTTP server implementation differ from traditional servlet-based containers?', N'Senior', N'Micronaut uses a non-blocking, event-loop-based HTTP server built on Netty. Unlike traditional Servlet-based containers that allocate a thread per request, Micronaut''s reactive approach allows it to handle high concurrency with a much smaller thread pool, significantly reducing memory consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc4f4d57-4ff4-4bc8-8cdf-9cc851a38688', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of Replication in Cassandra?', N'Intern', N'Replication is the process of storing copies of the same data on multiple nodes to ensure high availability and fault tolerance. If one node fails, the data remains accessible from other nodes that hold the replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'075892af-2969-442a-a7be-9cc8dbe61705', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is ''strict mode'' in TypeScript configuration?', N'Intern', N'Strict mode is a compiler setting that enables a range of type-checking behaviors that result in stronger guarantees of program correctness. It includes features like strict null checks, which prevent null or undefined from being assigned to variables without explicit allowance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaea750a-750c-4c7b-9eda-9ccbb2a28d55', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What mechanism allows Kotlin to achieve interoperability with Java''s checked exceptions?', N'Senior', N'Kotlin treats all exceptions as unchecked, which simplifies code by removing the need for explicit ''throws'' declarations. For Java interoperability, Kotlin provides the ''@Throws'' annotation, which informs the compiler to generate the appropriate ''throws'' signature in the bytecode so Java consumers can handle those exceptions correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'884097fe-700b-4588-801c-9ccc595ce2eb', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Describe the concept of ''Eventual Consistency'' and how it is managed in distributed systems.', N'Senior', N'Eventual consistency ensures that all replicas of a data item will eventually converge to the same value if no further updates occur. It is managed using protocols like vector clocks or CRDTs to resolve conflicts and track the causality of updates across distributed nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35b3fea3-bb12-4354-a8b1-9ccd94019b06', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the architectural benefits of using Chi''s sub-routers in a microservices environment.', N'Senior', N'Sub-routers allow for logical decoupling of API domains, enabling modular code organization and independent middleware application per route group. This architecture improves maintainability by allowing teams to own specific path prefixes without global state pollution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'776b878f-b2c7-42f0-88d6-9cce505b94c0', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the significance of the ''$app/navigation'' module in controlling complex application flows?', N'Senior', N'This module provides programmatic control over routing, such as triggering imperative transitions or preventing navigation via lifecycle hooks. It is essential for building advanced user experiences like ''unsaved changes'' warnings or custom transition animations between pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29450c73-205d-4f90-aa42-9cd0a17ed458', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How do Preact components differ from standard HTML elements?', N'Intern', N'Preact components are reusable functions or classes that return virtual nodes representing parts of the UI. Unlike standard HTML elements, they can hold internal state and encapsulate logic, making the UI modular.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e67f5f01-f59d-4017-a440-9cd4ad65b7e9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Kernel in the Symfony request lifecycle?', N'Middle', N'The Kernel is the heart of a Symfony application that transforms a Request into a Response. It manages the request-response cycle by dispatching events, invoking the appropriate controller, and handling the core logic required to bootstrap the framework''s various components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dda1ab8d-9c15-4986-8893-9cd4e4f7f7b1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a tuple in TypeScript?', N'Intern', N'A tuple is a type of array where the number of elements and the type of each specific element are fixed. Unlike a standard array, a tuple allows you to define a collection with a specific structure at every index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'835d64b1-ff3a-4287-acc7-9cd79d4f659a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the BASE model used in NoSQL?', N'Fresher', N'BASE stands for Basically Available, Soft state, and Eventual consistency. It is an alternative to ACID for distributed systems where immediate consistency is traded for higher availability and scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b82f3042-81c0-410c-a6ff-9cd8938c0ba9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-offs between using a managed cloud service versus hosting on raw infrastructure?', N'Middle', N'Managed services drastically reduce operational overhead and ensure high availability, allowing teams to focus on features. However, managed services can lead to higher long-term costs and vendor lock-in, whereas raw infrastructure provides complete control and potentially lower costs at scale, at the expense of significant management effort.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99aa932c-90b5-4f19-bf5c-9cda64701d3e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is pass by value and pass by reference?', N'Intern', N'Pass-by-value creates a new space in memory and makes a copy of a value. Primitives such as string, number, boolean etc will actually create a new copy. Hence, updating one value doesn''t impact the other value. i.e, The values are independent of each other. In the above code snippet, the value of a is assigned to b and the variable b has been incremented. Since there is a new space created for variable b, any update on this variable doesn''t impact the variable a. Pass by reference doesn''t create a new space in memory but the new variable adopts a memory address of an initial variable. Non-primitives such as objects, arrays and functions gets the reference of the initiable variable. i.e, updating one value will impact the other variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19a11c6c-93a4-42ca-9e23-9cdb63398b6c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the concept of Redis Cluster and its approach to data distribution.', N'Middle', N'Redis Cluster provides automatic sharding by partitioning data across multiple nodes using hash slots. This allows the database to scale horizontally by adding more nodes, while the cluster handles the mapping of keys to specific slots to maintain data distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06c04e1a-ade4-40c8-b122-9cdbfab5fe5c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you pass data into a Lit component?', N'Intern', N'Data is passed into a Lit component through its properties. These properties can be set via HTML attributes or by directly assigning values to the component''s properties in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bea331cb-7f98-491e-bffc-9cdcbf081d2b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an index in MySQL and how does it improve performance?', N'Junior', N'An index is a data structure that allows the database to locate rows faster without scanning every single row in a table. It works similarly to an index in a book, significantly speeding up data retrieval operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28a02d51-4d4e-4d05-bb2a-9ce1754023d3', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does a Column-family database differ from a standard relational table?', N'Middle', N'In a column-family database, data is stored in columns rather than rows, allowing for very efficient retrieval of specific attributes across billions of rows. This design is highly scalable for analytical workloads and sparse datasets where rows may have a vastly different number of columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26682dea-7bf9-4247-a6b1-9ce44fb0ccd6', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between an App instance and a Router in Fiber?', N'Fresher', N'An App instance represents the main application lifecycle and settings, while a Router is a group of routes that can be modularized. Routers help in organizing large applications by grouping related endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
