INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6b42c96-f74c-4ff8-87c7-9cee90855b47', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of the ''combineReducers'' utility?', N'Intern', N'As an application grows, it becomes difficult to manage a single reducer function. ''combineReducers'' allows you to split the state logic into separate, smaller functions that handle specific slices of the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab5f7e56-2270-45dd-b300-9cf3e6cd9d1f', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular CLI and what can it be used for?', N'Intern', N'Angular CLI (Command Line Interface) is a powerful tool that accelerates Angular development. It automates various tasks from initializing projects to deployment. Key Features and Uses - Project Initialization: Angular CLI streamlines the creation of new projects, sparing developers from having to set up configurations manually. - Scaffold: It generates files and folders for components, services and other Angular elements with structured code. - Integrated Testing: Developers can run both unit tests and end-to-end tests seamlessly using built-in tools like Karma and Protractor. - Web Server: For local development, Angular CLI has a built-in web server. - Live Code Changes: Utilizing LiveReload, the development server immediately reflects code changes in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01135962-0a56-4a6d-9e4d-9cf3ec7cac92', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is escape analysis, and why does it matter for performance?', N'Middle', N'Escape analysis is a compiler technique that determines whether a variable can be safely allocated on the stack or must ''escape'' to the heap. Efficient use of local variables allows the compiler to use the stack, which is faster and avoids garbage collection overhead compared to heap allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e4b591-424b-4658-b3aa-9cf454834cf1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between MongoDB and a relational database?', N'Intern', N'Relational databases use tables, rows, and columns with a strict schema, while MongoDB uses collections and documents with a flexible schema. MongoDB is generally easier to scale horizontally and better suited for unstructured or rapidly changing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edfd3f45-c249-4613-99fb-9cf9f9aa3d91', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage context compared to React?', N'Middle', N'Preact implements the Context API similarly to React, allowing state to be passed down through the component tree without prop drilling. While the implementation details differ, the API surface and functional outcome for the developer remain effectively the same.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18bc890f-df32-464a-9a7e-9cfaafe67f47', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''suspend'' modifier in Kotlin coroutines?', N'Middle', N'The suspend modifier marks a function as capable of pausing its execution without blocking the underlying thread. This allows the thread to perform other tasks while waiting for a long-running operation to complete, which is resumed once the operation finishes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a81f1745-995e-4ba3-9f2a-9cfb0818e81a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the trade-off of using a Global Secondary Index (GSI) compared to a Local Secondary Index (LSI)?', N'Middle', N'GSIs allow querying on any attribute and can be created or deleted at any time, but they are eventually consistent and incur their own throughput costs. LSIs must be created when the table is created, share throughput with the base table, and support strong consistency, but they are limited to the same partition key as the base table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dad279d-4fb5-4640-9679-9cfb20b488e8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''counter_cache'' option in ActiveRecord associations?', N'Middle', N'The counter_cache option optimizes performance by storing the count of associated records on the parent model. This avoids performing a ''count'' query on the child table every time the number of associations needs to be displayed, which is especially beneficial for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d6b50b2-a55c-48e7-83a5-9cfc7c812f82', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle list rendering differently than React?', N'Middle', N'SolidJS uses the For component to handle lists, which performs keyed updates on the DOM. This approach ensures that when items are added, removed, or reordered, only the affected DOM nodes are touched, rather than re-rendering the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b2f8c50-56d7-44dd-a1fc-9cfca80ae279', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM handle stack memory versus heap memory?', N'Middle', N'Stack memory is used for static allocation and contains local variables and method call frames, which are managed automatically and follow a LIFO structure. Heap memory is used for dynamic allocation of all objects and is managed by the garbage collector. Stack memory is thread-specific and faster, while heap memory is shared across threads and requires more complex management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a04a3c0-1a0b-41b4-8155-9cff29f37291', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix require a dedicated API backend?', N'Junior', N'No, Remix does not require a separate API. Because loaders and actions run on the server, you can interact with your database or third-party services directly within your route files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6016e476-03f1-456f-9e10-9d090c9cee4c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a graph database?', N'Fresher', N'A graph database uses nodes, edges, and properties to represent and store data. It is specifically designed to manage complex relationships between data points, making it ideal for social networks or recommendation engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac6bd28b-5cdc-4d4a-9dcd-9d0a1f716d76', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of a Service Provider''s ''boot'' method versus the ''register'' method?', N'Middle', N'The ''register'' method is strictly for binding services into the service container and should not attempt to use any other services. The ''boot'' method is called after all other services have been registered, allowing you to safely interact with other services or access the container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45178cb1-5fb9-4c4a-bc41-9d0b4f62f07d', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono provide helpers for cookie management?', N'Fresher', N'Yes, Hono includes built-in utility functions to set and get cookies. These helpers simplify the process of reading and writing cookies directly from the request and response objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df1589de-f395-48a8-9afd-9d0bb35f738c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the concept of ''lifespan'' events in FastAPI and their use cases.', N'Middle', N'Lifespan events allow you to define startup and shutdown logic, such as initializing database connections or closing resource pools. This ensures that expensive resources are prepared before the application starts accepting requests and cleaned up gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e5d5113-d44c-4a0c-9a1f-9d0c4357bd7d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do read-only replicas affect transaction consistency?', N'Middle', N'Read-only replicas introduce the risk of reading stale data because of replication lag. Applications must be designed to tolerate this latency or explicitly route critical read operations to the primary node to ensure strict consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f3966d2-749f-4042-89ce-9d0d6ada7609', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle template inheritance, and what are the performance impacts of complex inheritance trees?', N'Senior', N'Flask uses the Jinja2 engine, which compiles templates into Python bytecode. While inheritance enables modular UI design, excessively deep template trees can increase the time required for template resolution and compilation, potentially impacting response latency under high load if caching is not implemented correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be220821-95e1-4f59-904f-9d0da51d0ffb', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is choosing the right shard key important?', N'Middle', N'The shard key determines how data is distributed across nodes; a poor choice can lead to uneven data distribution. An ideal shard key ensures uniform load balancing and minimizes the need for cross-shard queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ac45114-02a4-4213-9ab3-9d112eaf81d8', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the difference between a global middleware and a route-specific middleware in Chi?', N'Intern', N'Global middleware runs on every request that enters the router. Route-specific middleware is only applied to a specific group of routes or a single endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'103ef46a-afcf-4cce-82a8-9d1303dc6e82', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the difference between include() and require() in PHP.', N'Fresher', N'Both functions are used to include external files, but they handle errors differently. If a file is not found, include() emits a warning and allows the script to continue, whereas require() throws a fatal error and stops the execution of the script.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7e283a0-6f97-43ac-9413-9d13a968163b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the main trade-off when using asynchronous replication?', N'Middle', N'Asynchronous replication offers lower latency for write operations because the primary node does not wait for replicas to acknowledge the write. The trade-off is the risk of data loss or reading stale data if the primary fails before the changes are propagated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
