INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d893f85-3e69-4810-91c9-9d1c2613c4b6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'When designing a large-scale Flask application, what is the architectural advantage of using Blueprints?', N'Senior', N'Blueprints promote modularity by allowing developers to decompose a large application into smaller, reusable components, each with its own routes, templates, and static files. This improves maintainability and scalability, as it allows teams to work on distinct functional areas independently and simplifies the registration of middleware or error handlers for specific segments of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
