INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e07ac9e2-132e-4991-99d3-9d1e6466fa94', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between symbols and strings in Ruby, and when should you prefer a symbol?', N'Junior', N'Strings are mutable objects that can be changed after creation, while symbols are immutable identifiers that are generally faster and more memory-efficient. Symbols are preferred for hash keys or representing internal method names because they are unique and do not need to be reallocated every time they are referenced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41d2af3a-ebed-4775-bc24-9d2173aff7ca', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why do NoSQL databases sometimes choose BASE over ACID?', N'Intern', N'Some NoSQL databases prioritize availability and speed over strict consistency, following the BASE model (Basically Available, Soft state, Eventual consistency). This is often preferred in large-scale distributed systems where immediate consistency is difficult to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
