INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fba095f-b02d-4691-8fc5-9d26e5dd0e2c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle multipart form data compared to traditional JSON bodies?', N'Senior', N'Axum provides specialized extractors to stream multipart data, which prevents the entire file from being loaded into memory at once. This is crucial for handling large file uploads in a scalable manner, as it keeps memory consumption constant regardless of the size of the uploaded data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8502e3f-99f6-4de2-b289-9d282577a6a6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is it recommended to use ''useFetcher'' instead of a standard link or form in some cases?', N'Middle', N'useFetcher is used when you want to interact with the server—like submitting a form or calling a loader—without triggering a full page navigation. This is ideal for background tasks, such as liking a post or toggling a switch, while keeping the user on the current page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54cd638d-0b0d-48b2-bbde-9d2a3ea06aa6', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Request Body''?', N'Intern', N'The request body is the part of an HTTP request that contains the actual data sent by the client, often in JSON format. FastAPI uses Pydantic models to parse, validate, and convert this body into a usable Python object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99c9b9c4-e95d-4d1c-a901-9d2bbe54b16e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the difference between ''managed'' and ''unmanaged'' memory in a .NET process.', N'Senior', N'Managed memory is controlled by the Garbage Collector, which tracks object lifetimes and performs automatic deallocation. Unmanaged memory exists outside the GC''s purview, requiring the developer to manually manage allocation and deallocation using platform invoke or native APIs, which introduces risks of memory leaks and corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d7cdb1e-7289-47ed-aff9-9d2be1a4b18f', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does the size of a cache entry impact system performance?', N'Middle', N'Storing very large objects in a cache can lead to fragmentation, high memory pressure, and increased network latency when retrieving the object. It is generally better to store smaller, granular objects that can be composed on the application side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a45389df-e014-44d8-915f-9d2cc513486d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of a commit log in Cassandra?', N'Intern', N'The commit log is a crash-recovery mechanism that records all incoming write operations. If a node crashes, Cassandra replays the commit log to restore data that was in the Memtable but not yet flushed to an SSTable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d89b8d5-fae5-4d70-80a1-9d2e2a153dfc', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are Scala traits and how do they differ from classes?', N'Intern', N'Traits are fundamental units of code reuse in Scala that can contain both method definitions and field declarations. Unlike classes, traits can be mixed into classes to provide additional functionality, effectively supporting multiple inheritance of behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ea0336a-2473-44ad-9593-9d2fff6e5e7a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''break'' and ''continue'' statements?', N'Intern', N'The break statement terminates the entire loop immediately, while the continue statement skips the current iteration and jumps to the start of the next iteration of the loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e4625c-923b-4e98-9d4f-9d30c650ad34', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Does Swift support multiple inheritance?', N'Fresher', N'Swift does not support multiple inheritance for classes. However, it achieves similar functionality through the use of protocols, which allow a type to conform to multiple requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9bf7f65-226a-4abb-a45c-9d3167f48450', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of dir method of console object', N'Intern', N'The console.dir() is used to display an interactive list of the properties of the specified JavaScript object as JSON. The user object displayed in JSON representation !Screenshot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0fe312b-3e86-4e1b-9214-9d3469cc8c11', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage state during client-side navigation?', N'Middle', N'SvelteKit preserves the application state across navigations by maintaining the component tree and data stores. This prevents unnecessary re-initialization of components and allows for smooth transitions and persistent UI states like scroll position or input focus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f428d7e-0bb5-46fd-aca4-9d38d4a35f43', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'When would you prefer Cassandra over a relational database?', N'Middle', N'Cassandra is preferred when you require massive write throughput, high availability across multiple data centers, and the ability to scale linearly by adding nodes. It is ideal for time-series data or high-velocity workloads where strict ACID compliance is not the primary requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'defc7517-37f2-4f75-b88e-9d3ce40c7172', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the lifecycle methods of React?', N'Fresher', N'Before React 16.3 - componentWillMount: Executed before rendering and is used for App level configuration in your root component. - componentDidMount: Executed after first rendering and here all AJAX requests, DOM or state updates, and set up event listeners should occur. - componentWillReceiveProps: Executed when particular prop updates to trigger state transitions. - shouldComponentUpdate: Determines if the component will be updated or not. By default it returns true. If you are sure that the component doesn''t need to render after state or props are updated, you can return false value. It is a great place to improve performance as it allows you to prevent a re-render if component receives new prop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f079cf-9241-4b31-9e75-9d4014b5db30', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary role of SvelteKit in a web application?', N'Junior', N'SvelteKit is a full-stack framework built on top of Svelte that handles routing, server-side rendering, and data fetching. It simplifies the process of building robust web applications by providing a structured file-based routing system and built-in optimization tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7589f09-e293-4b4e-b9e4-9d409323fd48', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why does Gin use sync.Pool for managing Context objects?', N'Senior', N'The sync.Pool is used to reuse gin.Context structures, which drastically reduces garbage collector pressure under high load. By recycling these objects instead of allocating a new one for every incoming request, Gin maintains low latency and reduced heap fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2627617b-8897-43de-b97d-9d415aafd72c', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What approach should be taken to ensure structured logging within Gin middleware?', N'Senior', N'One should replace the default logger with a middleware that extracts request metadata—such as latency, status code, and client IP—and formats them as structured JSON. This ensures that logs are machine-readable, which is vital for integration with centralized logging systems like ELK or Datadog.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72085553-481a-48d0-b412-9d43baf9b42d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the concept of ''Qrl'' (Qwik URL) and its importance in lazy loading.', N'Senior', N'A Qrl is a lightweight reference to a lazy-loadable chunk of code that contains a component''s logic or an event handler. These URLs allow the browser to fetch only the necessary JavaScript bundle exactly when an interaction is triggered, preventing unnecessary code evaluation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82f19348-bb37-403e-9c9d-9d43fc211f90', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do browser rendering engines prioritize CSS selectors during the style calculation phase?', N'Senior', N'Browsers process selectors from right to left to optimize performance. By starting with the key selector, the engine can quickly discard elements that do not match the most specific part of the rule before evaluating the rest of the selector chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a666a36b-b9e1-416b-bdf1-9d444a956344', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Is Next.js suitable for building a single-page application?', N'Fresher', N'Yes, Next.js can be used for single-page applications. While it is known for server-side capabilities, it supports client-side navigation and state management, providing the benefits of both worlds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'863c5338-3eef-4742-b86c-9d46f50d2e6a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a user reports an issue that seems ''impossible'' based on your understanding of the system, what is your next move?', N'Junior', N'I would investigate the user''s environment and the specific steps they took, as they might be triggering a path I haven''t considered. I would also check the logs for any errors that occurred at the time of the report. It is better to verify the system behavior empirically than to rely on assumptions about how it should work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64315b5e-4f1e-4f86-a31e-9d4da8a59b47', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a mutable and an immutable object in Python?', N'Intern', N'A mutable object is one whose internal state or value can be changed after it is created, such as a list or a dictionary. Conversely, an immutable object has a fixed value that cannot be altered once it is initialized, such as a string, integer, or tuple. Understanding this distinction is important because it dictates how these objects behave when passed into functions or stored in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09b77369-d23c-46df-b25f-9d4fd3920901', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does error handling work in Go?', N'Intern', N'Go treats errors as standard values rather than using exceptions. Functions return an error type as the last return value, and the caller is expected to check if the error is nil before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c6be636-d6e5-4537-9775-9d5215a63667', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is an Ember Controller?', N'Intern', N'A Controller is used to store the state of a template and manage user interactions. While components have largely replaced them for UI logic, controllers are still used to manage query parameters and specific template-level properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b68f3914-b927-4c8c-8382-9d576e9377f0', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do ''extension functions'' affect the encapsulation of a class?', N'Middle', N'Extension functions do not have access to the private members of the class they extend, which preserves encapsulation. They are resolved statically based on the declared type, meaning they are a convenient way to add utility methods without modifying the original source code or violating class boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e537505c-347a-4c02-a515-9d5b9083ad73', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle state sharing between different request handlers?', N'Middle', N'Actix uses an Application State pattern where data is wrapped in the Data extractor. This state is thread-safe, typically using Arc pointers, and is injected into handler functions at runtime, allowing safe, concurrent access to shared resources like database pools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f61c564-dbf7-4654-a961-9d5c75437b7e', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When is a CQRS (Command Query Responsibility Segregation) pattern useful?', N'Middle', N'CQRS is useful when the read and write workloads for an entity are vastly different in terms of scale or data structure. It allows architects to optimize the read side and the write side independently, often using different data stores for each.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae45db73-e0da-4130-81cb-9d5ed6ee7dca', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Describe the difference between clustered and secondary indexes in InnoDB.', N'Senior', N'The clustered index stores the actual row data at the leaf nodes, ordered by the primary key. Secondary indexes store the indexed columns and the primary key value, requiring a secondary lookup in the clustered index to retrieve the full row, known as a bookmark lookup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93116de2-c85b-41f6-9eec-9d5f8cab0725', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''new'' and ''delete'' operators?', N'Junior', N'The ''new'' operator is used to allocate memory on the heap and call the object''s constructor. The ''delete'' operator is used to deallocate that memory and call the object''s destructor to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9175ad9b-c61d-4fa1-9a2c-9d5f96b4d20a', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the performance implication of having hundreds of Alpine components on a single page?', N'Middle', N'While Alpine is lightweight, initializing a massive number of components can impact the initial load time and memory usage because each component requires its own reactivity observer. For very large pages, developers should consider lazy-loading or limiting scope to prevent performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a0e69c9-6b4d-4b51-a160-9d5fddf31196', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle concurrent requests under high load?', N'Senior', N'Litestar leverages the asynchronous nature of the ASGI specification and the Python asyncio library to handle high concurrency within a single process. By utilizing non-blocking I/O and efficient request scheduling, it maximizes throughput while maintaining low memory overhead per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81962866-d5e5-4082-9e1f-9d613cad39a7', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do Webpack code splitting and lazy loading improve performance?', N'Middle', N'Code splitting allows you to break your bundle into smaller chunks that can be loaded on demand rather than all at once. Lazy loading ensures that specific parts of the application are only downloaded when the user navigates to a relevant route or interacts with a feature, significantly reducing the initial page load time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3ffb5b9-3ccc-40a0-9585-9d6207d3e395', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is a ''Universal'' application in Nuxt?', N'Fresher', N'A universal application refers to code that can run on both the server and the client. This is the core strength of Nuxt, allowing the same logic to handle the initial server-rendered page and subsequent client-side updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c57369b-62c3-4c97-b1b0-9d679ebe20ff', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the difference between a handler and a service in Axum?', N'Fresher', N'A handler is a function that processes an HTTP request and returns a response, while a service is a more general abstraction that represents a component capable of processing requests. In Axum, handlers are converted into services to be executed by the router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
