INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'793c6660-71e9-48d9-b11d-9d6c3d48dbae', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why does Dart use a single-threaded execution model?', N'Middle', N'A single-threaded model simplifies application development by eliminating the need for complex locks, mutexes, or race-condition management. By using an event loop to handle asynchronous tasks, Dart achieves high concurrency without the overhead or risks associated with traditional multi-threaded memory access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a7bd568-446c-454b-98ef-9d6cbc5d94c5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of using the Next.js Link component over a standard anchor tag?', N'Fresher', N'The Link component enables prefetching, which means Next.js loads the code for the linked page in the background before the user clicks it. This creates a faster, near-instant navigation experience compared to a standard anchor tag that triggers a full browser refresh.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'652495e0-888a-4b5d-a6f6-9d6ddc4687ae', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach an issue where a user reports that they are seeing outdated data?', N'Middle', N'I would first investigate the caching layers, including CDN, server-side cache, and client-side browser cache. I would check if the cache invalidation logic is triggered correctly when the underlying data is updated. If the cache is fine, I would look for potential replication lag in the database if the application reads from read-replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fa684ec-c7b8-4858-9219-9d71fa958ded', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of ''ambient modules'' in TypeScript and when should they be utilized?', N'Senior', N'Ambient modules allow developers to define types for JavaScript code that lacks its own type definitions, effectively ''wrapping'' external code in a type-safe layer. They are essential for integrating non-TS libraries into a strictly typed environment without modifying the original source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4aedada1-bd66-4a12-bf01-9d7234c51a5f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What role does the ''translog'' play in Elasticsearch durability?', N'Middle', N'The translog acts as a write-ahead log that records all operations before they are flushed to the Lucene index. It ensures that data is not lost if the node crashes before segments are committed to disk, allowing the system to replay operations during recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
