INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2b888c7-6e11-47bf-966d-9d8719d41e1a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Explain the trade-offs when choosing between a relational database and a NoSQL database for a high-write-throughput application.', N'Senior', N'Relational databases provide ACID compliance and complex querying but often struggle with horizontal scaling under extreme write loads. NoSQL databases offer superior write scalability and flexible schemas through partitioning, but at the cost of complex data modeling and the loss of cross-document transaction guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
