INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be31956e-bfb5-4414-866d-9d9bfb448288', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between path parameters and query parameters in Express?', N'Middle', N'Path parameters are part of the URL structure, such as identifiers for specific resources, and are accessed via req.params. Query parameters follow a question mark in the URL and are used for filtering or sorting, accessible via req.query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28fa8f8a-ed2f-4925-bcf9-9d9c3697586b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you handle graceful shutdowns in a Node.js microservice to ensure data integrity?', N'Senior', N'Upon receiving a termination signal, the application should stop accepting new connections, finish processing existing requests, and close database or message broker connections. This is typically implemented by listening for SIGTERM or SIGINT signals and using a timeout to force-exit if the cleanup process takes too long.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baf2af44-c1ee-49f2-adba-9d9d4e5fa61c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the implications of network partitions in a Redis Sentinel-managed system?', N'Senior', N'Network partitions can lead to ''split-brain'' scenarios where both the original primary and a promoted replica believe they are the authoritative primary. Sentinel mitigates this through quorum-based voting, but careful configuration of failover timeouts is necessary to prevent unnecessary failovers during transient network instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f523c11b-3677-4d4a-a991-9d9e974fa099', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of introducing a service mesh in a Kubernetes environment?', N'Senior', N'A service mesh provides powerful observability, security, and traffic management features out of the box. However, it adds significant latency overhead, increases infrastructure resource usage, and introduces a steep learning curve for the operations team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbddec83-17a9-41c1-badf-9d9f383250b8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the advantage of using ''Cookie'' and ''Header'' parameters?', N'Fresher', N'Using ''Cookie'' and ''Header'' parameters allows you to easily extract values from the request headers or cookies. FastAPI automatically validates these values based on the type hints provided, similar to path and query parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ce50139-6166-4597-b006-9da08b4da507', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How can Tailwind CSS be integrated into a project using Shadow DOM or Web Components?', N'Middle', N'Since Tailwind generates CSS classes, you must ensure the generated stylesheet is injected into the Shadow Root of the web component. This often requires build-time configuration to duplicate the styles into each shadow boundary, as standard global CSS does not penetrate the Shadow DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd33f6a72-f3f9-4779-8ada-9da113cb6c68', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the ''defer'' statement impact function performance and flow?', N'Middle', N'Defer pushes a function call onto a stack that executes when the surrounding function returns, ensuring resource cleanup even in case of panics. While convenient, it adds a small performance overhead; developers should be cautious about using it inside tight loops to avoid memory accumulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc143a5-d8b5-49cb-a16d-9da31290192f', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What architectural trade-offs exist when using ''Any'' versus a concrete type in Swift?', N'Senior', N'Using ''Any'' sacrifices type safety and performance by forcing the compiler to use type erasure and existential containers, which involve heap allocation and runtime checks. Concrete types allow the compiler to enforce strict rules and perform static optimizations. ''Any'' should be reserved for scenarios where complete type flexibility is required, such as heterogeneous collections or generic serialization frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31a0716d-91ac-4bd0-8366-9da61a35ec07', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can you use standard JavaScript ''if'' statements for conditional rendering in SolidJS?', N'Intern', N'While standard JavaScript works, using control flow components like ''Show'' is preferred because they are reactive. Standard statements may not automatically trigger the necessary DOM updates when the condition state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee2ff9ec-32c8-44a1-a94f-9da6c9a998a5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is Qwik and how does it differ from traditional frameworks?', N'Fresher', N'Qwik is a frontend framework designed for instant loading by focusing on resumability. Unlike traditional frameworks that require hydration, Qwik sends HTML that is already interactive, eliminating the need to download and execute large JavaScript bundles on startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3c4bd1-b9dc-4aeb-bafb-9daa48d691b0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does ''Index Condition Pushdown'' (ICP) optimize?', N'Senior', N'ICP allows the storage engine to filter index records based on conditions that would normally require a full row retrieval. By pushing the filter down, MySQL reduces the number of times the engine must access the base table, decreasing total I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b81f29f-f5e0-4aaa-a282-9daae67bf97e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the advantage of using the list type in Sass?', N'Middle', N'Lists allow you to group related values, such as breakpoints or color sequences, into an ordered collection. You can iterate over these lists to generate responsive CSS rules or utility classes, which significantly reduces the amount of manual code needed for systematic design changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b5904f9-8eb1-41d6-bb95-9dab9231a7b9', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s ''glob import'' feature for large-scale applications?', N'Senior', N'Glob imports allow developers to import multiple files at once using patterns, which is useful for tasks like dynamic routing or automated registration of components. This reduces boilerplate and allows Vite to optimize the inclusion of these files in the bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
