INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6589988b-b75d-4f01-b3ed-9dafeb22e049', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Compare the S4 and R6 object-oriented systems.', N'Middle', N'S4 is a formal system that enforces strict structure and multiple dispatch, making it suitable for complex mathematical libraries. R6, by contrast, uses a reference-based approach with encapsulated state, which is better suited for managing complex application state or interacting with external systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e37d5f-ee4a-400c-9a81-9db30a083cc6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the main drawback of using too many utility classes on a single HTML element?', N'Junior', N'The main drawback is code readability, as an excessive number of utility classes can make the HTML look cluttered and difficult to scan. This is often mitigated by using component extraction, such as with the @apply directive or by creating reusable UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efc0387f-e817-42d4-ac7a-9db5cbab3c70', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of ''hooks'' in Fastify, and give an example of one?', N'Junior', N'Hooks are functions that allow you to interact with the request and response lifecycle at specific points. A common example is the ''preHandler'' hook, which is used to execute logic, such as authentication or rate limiting, after the request is routed but before the main route handler is invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c872de82-9b2a-455b-abde-9db66f7bc4e4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What does the ''settings.py'' file do?', N'Fresher', N'The settings.py file is the central configuration hub for a Django project. It contains settings for database connectivity, installed applications, middleware, security keys, and environment-specific variables needed for the project to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d832f1-6d8d-48d6-a612-9dbabbf76d03', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the virtual DOM in Svelte?', N'Fresher', N'Svelte does not have a virtual DOM. It is designed to be a compiler that tracks changes and updates the actual DOM directly, which is one of the main reasons for its high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d5455a1-87a4-4521-b7d9-9dbb31185692', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of connection pooling in database drivers?', N'Senior', N'Connection pooling avoids the high latency overhead of establishing a new TCP connection and performing the TLS/authentication handshake for every request. By maintaining a set of ready-to-use connections, the application can reuse resources, reducing latency and preventing the database from being overwhelmed by connection establishment requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e081b06b-c758-42ff-8a85-9dbc6c8d5f2b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What architectural challenges arise when using Hono for a monolithic application versus a microservices architecture?', N'Senior', N'In a monolith, Hono''s routing table can become difficult to manage if not properly modularized using sub-routers and route grouping. While microservices benefit from Hono''s simplicity, a monolith requires strict discipline in defining shared interfaces and maintaining organizational boundaries to prevent the application from becoming a ''big ball of mud''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6051421e-978d-4d7e-95a8-9dbcc8f321ee', N'4c000000-0000-0000-0000-000000000005', N'Explain the benefit of database replication.', N'Middle', N'Replication involves copying data from a primary database to one or more replicas. It provides high availability and fault tolerance, and allows read traffic to be offloaded from the primary node to secondary nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa2bb7e5-08ff-4975-a60d-9dbd16bbb431', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is promise chaining', N'Intern', N'The process of executing a sequence of asynchronous tasks one after another using promises is known as Promise chaining. Let''s take an example of promise chaining for calculating the final result, In the above handlers, the result is passed to the chain of .then() handlers with the below work flow, 1. The initial promise resolves in 1 second, 2. After that .then handler is called by logging the result(1) and then return a promise with the value of result \* 2. 3. After that the value passed to the next .then handler by logging the result(2) and return a promise with result \* 3. 4. Finally the value passed to the last .then handler by logging the result(6) and return a promise with result \* 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b508c97-b1ab-4bda-aea1-9dbd71ca5ea0', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is ''Hot Code Swapping'' a unique feature of Phoenix/Erlang environments?', N'Middle', N'Hot code swapping allows you to update the application''s code while it is running without dropping connections or losing state. This is possible because the VM allows two versions of a module to exist simultaneously, with processes transitioning to the new version as they execute code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936c170e-56b7-45d5-bde7-9dbd860af860', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is PEP 8 and why is it important?', N'Intern', N'PEP 8 is the official Style Guide for Python Code, established as a Python Enhancement Proposal. It defines the conventions for formatting and structuring Python code to maximize readability, consistency, and maintainability across the global Python ecosystem. As Python creator Guido van Rossum famously stated, "code is read much more often than it is written." Adhering to PEP 8 reduces cognitive load, allowing developers to focus on logic rather than formatting quirks. Key Design Principles * Readability: Prioritizes human comprehension; if a style choice makes code harder to understand, readability takes precedence. * Consistency: Ensures a uniform "look and feel" within a project and across the community.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f069d26a-5f9a-4cfe-b2d5-9dbdd8b3e211', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How can you implement an effective multi-tenant database architecture while maintaining data isolation?', N'Senior', N'Isolation can be achieved via separate schemas per tenant, separate databases per tenant, or by including a ''tenant_id'' in every table row. While row-level tagging allows for higher consolidation, it requires strict application-level enforcement to ensure that one tenant cannot access another''s data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76ced95d-c455-448f-9f4e-9dbe9f411dc2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the trade-offs of using Phoenix PubSub for cross-node communication in a distributed cluster?', N'Senior', N'Phoenix PubSub allows for efficient message distribution across nodes, but it relies on an adapter mechanism, such as PG2 or Redis. While it simplifies real-time coordination, developers must account for network partition risks and the latency added by the chosen distribution mechanism when scaling to very large clusters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0ec5cfa-94ad-4c36-80b9-9dbf62cd2971', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin manage static file serving, and what are the limitations for high-traffic environments?', N'Senior', N'Gin''s static serving is built on Go''s ''http.ServeFile'' which is suitable for small-scale assets. For high-traffic systems, serving static files directly through a CDN or a specialized reverse proxy like Nginx is recommended to offload the Go runtime and improve cache efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb92e1b0-7f8f-4d6e-8ff6-9dc46a146aff', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the relationship between a slice, an array, and a backing array?', N'Middle', N'An array is a fixed-size sequence of elements, while a slice is a header pointing to a contiguous segment of an underlying array. Slices provide flexibility because they can be resized and passed around without copying the entire underlying data structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61d598f1-ff6a-4bb6-b8f5-9dc4a54940e4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the difference between a Hash Join and a Nested Loop join.', N'Middle', N'A Nested Loop join iterates through one table and performs a lookup in the other for every row, making it efficient for small datasets or when an index is available. A Hash Join builds a hash table in memory for the smaller table and scans the larger one, which is generally faster for large, unsorted datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5b74f27-70e6-4c68-b4d1-9dc59b3ac047', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you ensure data integrity during parallel execution in Spring Boot?', N'Senior', N'You can use JPA''s Optimistic Locking via the @Version annotation to detect concurrent modifications. For more complex requirements, you might implement pessimistic locking at the database level or use distributed locks provided by tools like Redis (Redlock).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b4a2370-d579-450a-8a90-9dc690394b80', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the resolve property in Webpack configuration?', N'Fresher', N'The resolve property tells Webpack how to find modules when you import them. It allows you to configure things like file extensions to omit or create aliases for frequently accessed directories, making imports cleaner and easier to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a65c9c1f-55e3-4da9-8ccc-9dc932abf6f0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you identify and mitigate the ''noisy neighbor'' problem in a shared multi-tenant infrastructure?', N'Senior', N'I implement strict resource isolation using container quotas or virtualization to prevent a single tenant from consuming excessive CPU, memory, or I/O. I also monitor per-tenant metrics to set rate limits that ensure fair access to shared infrastructure resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc418d36-8215-449d-86e5-9dcad78e7b3d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of Isolation in transactions?', N'Fresher', N'Isolation ensures that concurrent transactions do not interfere with each other. It makes it appear as though each transaction is executing in complete seclusion from others happening at the same time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ccbdde2-bb8a-4598-a15a-9dcb6976ecc2', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Eager Loading in Eloquent and why is it important?', N'Junior', N'Eager Loading is a technique used to solve the N+1 query problem, where the application executes one query to fetch the main model and subsequent queries for each related model. By using eager loading, Laravel fetches all related models in a single or minimal number of queries, significantly improving performance for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70a683b8-b062-4ea1-9aa8-9dcb9597d08f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What steps do you take when a rolling deployment causes an unexpected increase in error rates?', N'Senior', N'I immediately initiate an automated rollback to restore service stability while preserving the faulty state in a subset of nodes for investigation. I compare the metrics and logs of the new version against the previous one to identify configuration mismatches, incompatible API changes, or resource regressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b616c9-0f41-4004-976f-9dcfe4ae05a0', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is pass in Python?', N'Intern', N'Pass means, no-operation Python statement, or in other words it is a place holder in compound statement, where there should be a blank left and nothing has to be written there.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4baea7ac-5d10-46f2-a0e9-9dd09c0d5b09', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Does Quarkus support testing?', N'Fresher', N'Yes, Quarkus provides built-in support for testing using tools like JUnit 5 and RestAssured. It allows developers to run tests against the application in the same way it would run in production, including native mode testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dc25416-35c3-4735-a48f-9dd1dca4510d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''final'' keyword in C++ classes and methods?', N'Middle', N'The ''final'' specifier prevents a class from being inherited or a virtual function from being overridden. This is useful for design enforcement, ensuring that specific class hierarchies or polymorphic behaviors remain unchanged by future modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f0c61a-8afa-4cc9-b3a9-9dd22f49143f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''request'' context in Flask?', N'Middle', N'The request context temporarily stores information about the current HTTP request, such as form data, headers, and URL parameters. It allows you to access request-specific information globally within a view function without needing to pass the request object manually through every function in your call stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
