INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6330c34-8a0b-4960-949b-9dd683b8b55f', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle 404 and 500 errors?', N'Middle', N'SvelteKit provides a specialized +error.svelte file that acts as a boundary for errors occurring within its route folder. You can trigger these errors manually via the error helper in load functions, and the framework will automatically render the error component while keeping the surrounding layout intact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc680b18-54cd-47ef-812b-9dd69cc20cd4', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How can you implement cross-cutting concerns like authentication in Chi effectively?', N'Senior', N'Authentication is best implemented as a middleware that intercepts the request and verifies credentials before calling the next handler. In Chi, this can be applied globally to the root router or selectively to specific sub-routers, allowing for fine-grained access control across the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
