INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'311c696b-c2fb-44ce-bec4-9ddc2a896008', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do ''Property Wrappers'' alter the underlying storage of a property?', N'Senior', N'Property wrappers introduce an intermediate layer of storage that encapsulates the logic of reading and writing a property. The compiler generates the necessary backing storage, which allows developers to extract repetitive logic like thread synchronization or data validation into reusable, declarative components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'895d4412-45f0-4de7-9ce0-9dde3053676c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your methodology for capacity planning for a new application?', N'Middle', N'I define performance targets based on expected user traffic and perform load testing to find the breaking point of the current infrastructure. Based on these metrics, I extrapolate the resource requirements and establish an auto-scaling policy that triggers based on CPU or memory thresholds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'108864a6-9881-4e55-a4b3-9de275e4704d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of an action creator?', N'Junior', N'An action creator is a function that creates and returns an action object. Using action creators makes code more reusable and portable, as you do not need to manually write the action object every time you want to dispatch it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
