INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4246c6de-9eaf-4736-a564-9de4b9180539', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you evaluate if a proposed solution is ''good enough'' versus ''perfect''?', N'Intern', N'I evaluate the trade-offs between the time spent and the value gained from additional improvements. If a solution meets all requirements and performs reliably, it is often better to ship it than to aim for perfection at the cost of significant delays. I prioritize meeting business goals and user needs over unnecessary optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85e9acaa-cbfd-4617-bd79-9de58219db09', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the significance of the ''Primary Term'' and ''Sequence Number'' in Elasticsearch concurrency control.', N'Senior', N'These metadata fields allow Elasticsearch to track the history of operations on a per-shard basis. They enable robust replica synchronization and ensure that operations are applied in the correct order, which is critical for maintaining consistency during concurrent updates and recovery processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'410a4e68-75fd-4000-9ee8-9de5f8803507', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the ''useFetch'' or ''useAsyncData'' composables in Nuxt?', N'Intern', N'These composables are used to fetch data from an API during the server-side rendering phase or on the client side. They handle the data fetching lifecycle, ensure that data is correctly serialized from the server to the client, and prevent duplicate requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ec5e4bb-aad0-4d6f-aad5-9ded393b5ac6', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a ''race condition'' in the context of system troubleshooting?', N'Fresher', N'A race condition occurs when system behavior depends on the uncontrolled sequence or timing of multiple independent events. Troubleshooting this requires identifying areas where shared resources are accessed without proper synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'112988ad-3aba-4c83-ae96-9dedc92db9cf', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is ''Write Amplification'' a concern in transaction-heavy workloads?', N'Senior', N'Write amplification occurs when a single logical update requires multiple physical writes to storage, such as updating data pages, index pages, and transaction logs. This overhead increases I/O pressure and reduces the effective throughput of the database, especially on SSDs where excessive writes wear out the hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f37683a8-9e6c-4d07-a27f-9defdf4ab1f4', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Discuss the architectural difference between Redux Thunk and Redux Saga.', N'Senior', N'Redux Thunk is a simple approach that allows action creators to return functions, making it ideal for basic asynchronous tasks. Redux Saga uses generator functions to manage side effects, providing a more robust and testable architecture for complex flow control, cancellation, and race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fdc3ad9-6d5a-4f2d-be4c-9df0f1cb301d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are actions in Redux and why are they used?', N'Junior', N'Actions are plain JavaScript objects that represent an intention to change the state. They must contain a type property to describe the action and optionally carry additional data, serving as the only way to send information from the application to the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'124cb93f-980a-4f4b-889a-9df2f7031cc8', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Kernel in Symfony?', N'Fresher', N'The Kernel is the heart of a Symfony application that handles every request. It receives an HTTP request, converts it into a response by passing it through the event dispatcher and routing system, and then returns the final output to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2d3fd30-6539-47cd-8cd6-9df3071fc561', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux ensure data consistency across multiple connected components?', N'Senior', N'Redux ensures consistency by maintaining a single, unified state tree and requiring all changes to go through a single dispatcher. By pushing state changes through a centralized flow, every connected component is guaranteed to receive the most current version of the state simultaneously after an action is processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf7b9c59-0900-4e73-a1a4-9df5219a8acd', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the ''content'' directive within a Sass mixin?', N'Middle', N'The @content directive acts as a placeholder that allows you to pass custom CSS blocks into a mixin at the point of usage. This makes mixins highly reusable, as they can define a structure or wrapper while the caller provides the specific implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b450b85b-c79f-4ac8-9cbb-9df5dbe7224a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the DOM and how is it structured?', N'Intern', N'The DOM, or Document Object Model, is a programming interface for web documents. It represents the page so that programs can change the document structure, style, and content. The DOM is structured as a tree of objects, where each node represents part of the document, such as elements, attributes, and text. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a77d8de6-e46a-4270-b5a8-9df70bd637b4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does the term ''normalization'' mean?', N'Intern', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
