INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a57ab7ff-431d-449f-a4b4-9dfbf52f2e46', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of Middleware in Django?', N'Junior', N'Middleware is a series of hooks that process requests and responses globally in Django. It sits between the web server and the view, allowing you to perform actions like security checks, session management, or authentication on every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7716422-b201-4ca6-92c1-9dfc057e9044', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'In what scenario would you prefer using a Sass function over a mixin?', N'Senior', N'You should use a function when you need to perform calculations or logic to return a single value, such as a color or a dimension, for use within a property. Mixins are intended for generating blocks of CSS rules, whereas functions are specifically for data transformation and returning values to be consumed by CSS properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
