INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b291a983-bea8-470a-9a38-9e03ffde7f96', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the role of the ''reducer'' as a pure function in the context of predictability.', N'Senior', N'A reducer must be a pure function because it must return the same output for the same input without producing side effects. This purity ensures that the state transition is deterministic, making the application behavior predictable, testable, and capable of being replayed or reordered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78b14724-f13c-48de-8f8d-9e042770415b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why would you choose NoSQL over SQL for a specific project?', N'Junior', N'NoSQL is preferred when handling rapidly changing data structures, massive volumes of unstructured data, or when the application requires high-speed horizontal scaling. It is also useful when the data model does not fit well into a rigid, tabular relational format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1156951a-7658-4807-9c2d-9e04f2d9506c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why should you use parameterized queries instead of concatenating user input?', N'Junior', N'Using parameterized queries prevents SQL injection attacks by ensuring that user input is treated strictly as data and never as executable code. It also helps the database engine reuse query execution plans, which can improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
