INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9efa671-1dd4-42d9-b00e-9e0a61f71f38', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the compiler in the Svelte ecosystem?', N'Intern', N'The compiler analyzes your code at build time to determine exactly how your application should update when state changes. By doing this work ahead of time, Svelte eliminates the need for a virtual DOM, leading to faster performance and smaller bundle sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efd8454a-7ceb-482b-b10e-9e0b57d8ec91', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a component in Angular and how is it used?', N'Intern', N'In Angular, a component represents a logical UI element that defines a part of the user interface. It consists of a TypeScript class that holds the component''s data and logic, and an HTML file that defines the view, along with a CSS file for styling. Components can nest inside each other to form a component tree, and they often communicate with each other using inputs, outputs, services, and observables. Key Component Parts - Class: Represents the component''s behavior and data using TypeScript. It may include properties, methods, lifecycles, and decorators. - Template: Specifies the UI structure using HTML, often integrated with Angular directives and data binding. - Styles: Uses CSS to define the component''s visual appearance. Can be scope-limited to the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fbb98f7-68fd-438a-9141-9e0c9ed09858', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the significance of the ''Query'' operation compared to ''GetItem''?', N'Senior', N'GetItem retrieves a single item using its full primary key, which is highly efficient. Query allows you to fetch multiple items that share the same partition key, enabling efficient filtering and range scans based on sort keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1035d99-9974-4cf0-ba6c-9e10a8a83820', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask and how is it categorized?', N'Fresher', N'Flask is a lightweight web framework written in Python. It is categorized as a micro-framework because it provides the essential tools to build web applications without requiring specific tools or libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0da2c885-9348-41f1-b285-9e1303297866', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between the Spring Bean lifecycle and the Spring Boot ApplicationContext lifecycle.', N'Senior', N'The Bean lifecycle focuses on the individual object''s creation, dependency injection, and destruction phases. In contrast, the ApplicationContext lifecycle manages the entire container, encompassing configuration loading, bean instantiation, event publishing, and the graceful shutdown of the context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4e5f51e-b1ac-4449-a906-9e153b64b10e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between document-oriented databases and key-value stores?', N'Middle', N'Key-value stores are designed for high-performance retrieval of data based on a simple unique identifier, whereas document-oriented databases store data in structured formats like JSON or BSON. Document stores allow for secondary indexing and complex querying of fields within the documents, which is not natively supported by standard key-value stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65c13227-1c63-4d33-84dc-9e15f7584136', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''content collections'' improve developer experience compared to flat-file storage?', N'Senior', N'Content collections enforce strict typing and schema validation, which prevents runtime errors when accessing frontmatter fields. It also provides built-in query capabilities, making it easier to filter, sort, and link related content while maintaining a clear directory structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af425e18-c8e4-4cea-b91e-9e16e1c2ec7e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What are the trade-offs of using a message broker versus direct HTTP communication between services?', N'Senior', N'Message brokers provide loose coupling, better load leveling, and asynchronous processing, which enhances system scalability and resilience. However, they add architectural complexity and operational overhead compared to direct HTTP calls, which are simpler to implement but create tighter coupling and synchronous blocking dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10ddbf64-ba33-4c3f-b439-9e16f2238357', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix''s approach to data loading differ from standard client-side fetching patterns in SPAs?', N'Senior', N'Remix utilizes route-based loaders that execute on the server before the component renders. This eliminates the ''waterfall'' effect common in useEffect-based fetching by parallelizing data requirements at the route level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd45722a-7e7e-4beb-b61f-9e1a4f0bfe1a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Job Queue in Laravel?', N'Junior', N'A Job Queue allows you to defer time-consuming tasks, such as sending emails or processing images, to be executed in the background. This improves the performance of your application by allowing the user to receive a response immediately while the task completes later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a384a4f-1499-4d20-9061-9e1a6e7895b6', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens if you do not define a JSON schema for a route in Fastify?', N'Middle', N'If no schema is defined, Fastify skips the validation and serialization steps, which can lead to slightly higher throughput for simple routes. However, you lose the performance benefits of optimized JSON stringification and the automatic generation of API documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10e0c38d-1cf2-48e1-84fd-9e1caa112332', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is it important to use ''defineNuxtComponent'' or ''defineNuxtConfig'' instead of raw objects?', N'Senior', N'These helper functions provide critical IDE autocompletion and TypeScript support for Nuxt-specific options. They act as a contract that ensures the configuration or component structure conforms to the expected framework API, preventing runtime errors caused by structural mismatches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bbd3cd0-4adf-486d-97a6-9e1d8ebc4653', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Describe the process of ''Online DDL'' in MySQL and the limitations associated with metadata locks.', N'Senior', N'Online DDL allows modifications to table structures without blocking reads or writes by performing changes in the background. However, it requires an initial metadata lock to update the table definition; if long-running transactions are active, they can block the DDL operation, causing subsequent queries to queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20980f46-2c85-466d-8d76-9e1f946c620d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the trade-offs of using ''Any'' and ''AnyObject'' in Swift architecture?', N'Senior', N'Using Any and AnyObject sacrifices type safety and performance by forcing the compiler to use dynamic type checking and boxing. These types require runtime type casting, which bypasses compile-time checks and prevents the compiler from performing optimizations like static dispatch. They should be avoided in favor of generics or protocol constraints whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e77ba067-0259-406c-a942-9e231892b273', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''will-change'' property and what are the risks of overusing it?', N'Middle', N'The ''will-change'' property informs the browser about which properties are likely to change, allowing it to optimize by promoting the element to its own compositor layer. Overusing it can lead to excessive memory consumption, as each promoted layer occupies video memory. It should be used sparingly and removed once the animation or transition is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c669a3c-7105-470a-a21a-9e28cd45a098', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''select_for_update'' method, and what locking behavior does it enforce?', N'Middle', N'select_for_update is used to lock selected rows in the database until the end of the current transaction, preventing other processes from modifying or locking those rows. This is essential for preventing race conditions in operations like inventory management or balance updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4f78206-ca04-4d34-a43f-9e2aa25036d8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Describe how to secure an endpoint using FastAPI''s security utilities.', N'Middle', N'FastAPI provides built-in support for security schemes like OAuth2, API keys, and HTTP Basic auth through the fastapi.security module. You combine these with dependency injection to require authentication for specific endpoints, ensuring that the logic is reusable and strictly enforced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b263773-42e3-4794-a5f2-9e2b4b9378fe', N'075b8862-431c-4678-9767-f55359758a4a', N'Compare the performance impact of using v-if versus v-show in a high-frequency rendering scenario.', N'Senior', N'v-if is a lazy toggle that destroys and recreates component instances, which is expensive for complex components but saves memory. v-show toggles the CSS display property, keeping the component alive in the DOM, making it more performant for elements that need to be toggled frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ddc39dd-cd5a-49cf-bc6c-9e2de20f8a27', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Request-Response cycle handle ''Kernel Events'' to facilitate middleware-like behavior?', N'Senior', N'The Kernel dispatches specific events—such as Request, Controller, View, and Response—at distinct stages of the lifecycle. By attaching listeners to these events, developers can intercept the flow to perform tasks like authentication, content negotiation, or global response modification before the final output is sent to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
