INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eae65aa9-575a-4719-ac40-9e311c8e94f5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the use of Promise.any()?', N'Fresher', N'The Promise.any() method is used to handle multiple promises simultaneously, and it resolves with the value of the first fulfilled promise.regardless of whether any of the other promises reject. If all of the promises reject, then Promise.any() rejects with an AggregateError object that contains an array of rejection reasons. The Promise.any() method takes an iterable of Promises as an input, and returns a new Promise. Here''s an example: Example: *Note: Promise.any() is supported in all modern browsers since 2021.*', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
