INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2726e127-fdcf-43ee-9d0f-9e408705dd94', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle static assets?', N'Intern', N'Vite treats static assets like images, fonts, and CSS files as first-class citizens. They can be imported directly into JavaScript files, and Vite will automatically resolve their paths and optimize them during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b279e60-cbed-4013-b569-9e41599f6cae', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is MySQL?', N'Intern', N'MySQL is an open-source RDBMS that uses Structured Query Language to manage and manipulate data. It is widely used in web applications for its reliability, performance, and ease of use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77d9ffe3-ac9d-455b-8c50-9e44424f9686', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is the Saga pattern preferred over distributed transactions (2PC) in microservices?', N'Middle', N'Distributed transactions require blocking locks across multiple databases, which severely impacts availability and performance in a distributed environment. The Saga pattern maintains data consistency through a sequence of local transactions and compensating actions, ensuring better scalability and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee86a1c-8929-4c46-a974-9e44e30c68b4', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the trade-offs of using global vs. local middleware in Litestar?', N'Middle', N'Global middleware affects every request, which is efficient for common tasks but can lead to unnecessary processing for public endpoints. Local middleware allows for targeted application, ensuring that expensive logic only runs when necessary, though it increases configuration complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ce24440-3cd8-4b01-b31c-9e458277e00d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of a minor change request on an existing task?', N'Fresher', N'I would evaluate the change against the existing logic to see if it requires refactoring or just an addition. I consider the impact on testing, documentation, and potential side effects on other parts of the system. Even a ''small'' change can have ripple effects, so I assess the entire scope of the change before updating the estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed574513-3e6f-4e98-b0a9-9e482d185cc3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the problems with global variables', N'Intern', N'The problem with global variables is the conflict of variable names of local and global scope. It is also difficult to debug and test the code that relies on global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dd69193-d249-4725-9489-9e4ccb52fb2d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you mitigate the risks of dependency-related attacks in a large-scale software supply chain?', N'Senior', N'Mitigation involves implementing Software Bill of Materials (SBOM) to track components, using automated vulnerability scanning in the CI/CD pipeline, and pinning dependencies to specific hashes. Additionally, relying on internal package mirrors and performing thorough audit of third-party code before ingestion helps prevent the introduction of malicious packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'288ccdca-88cb-49d3-bb9f-9e559c2b8925', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''self'' parameter in a class method?', N'Intern', N'The ''self'' parameter refers to the specific instance of the class that is calling the method. It allows the code to access the attributes and other methods of that particular object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39e326bb-5537-471e-9ab6-9e59159495d8', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is ''Serializing'' in Qwik?', N'Fresher', N'Serializing is the process of converting the internal state of a component into a string format that can be embedded directly into the HTML. This allows the client-side application to pick up exactly where the server left off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b0bf956-1c49-476d-984a-9e5c38423a67', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of Pydantic in a Litestar application?', N'Fresher', N'Pydantic is used in Litestar for data parsing and validation. It ensures that the data sent by clients matches the expected structure defined in your application models, throwing errors if the data is invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf657a6-fd2d-4001-b07c-9e60670d93a8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''batching'' in SolidJS?', N'Intern', N'Batching is a performance technique that groups multiple reactive updates into a single update cycle. This prevents unnecessary intermediate renders or effect executions when multiple signals are changed simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
