INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4718127d-5dcf-48f4-9337-9e63b32ef7af', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does choosing a schema-on-read approach versus a schema-on-write approach affect system design?', N'Middle', N'Schema-on-write ensures data integrity and performance for structured queries but requires upfront modeling and makes changing the schema difficult later. Schema-on-read offers greater flexibility for evolving data and faster ingestion, but pushes the complexity of data validation and transformation to the query time, potentially impacting performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd695c5b-7b85-425c-a216-9e6591ab4a57', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the security risk associated with Cross-Site Request Forgery (CSRF)?', N'Middle', N'CSRF forces an authenticated user to execute unwanted actions on a web application in which they are currently logged in. It exploits the trust a site has in the user''s browser, which automatically attaches cookies to requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2bac99d-4e83-4dc7-86af-9e67cd914188', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the function of the ''Request'' object in FastAPI?', N'Fresher', N'The Request object provides access to the details of the incoming HTTP request, such as headers, cookies, and body content. It allows developers to inspect or manipulate the request data before processing it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee6a7b71-ed4d-47f6-99e6-9e6a0106b5a7', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do Middleware components function in Litestar?', N'Fresher', N'Middleware in Litestar are components that process incoming requests before they reach the route handler and process outgoing responses before they are sent to the client. They are commonly used for tasks like logging, authentication, adding custom headers, or handling cross-cutting concerns across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b762407d-5daf-43b5-9e56-9e6aa084c45f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the size of the Preact library compare to React in a production build?', N'Middle', N'Preact is significantly smaller, usually coming in at around 3-4 KB compared to React''s much larger footprint. This difference is achieved by stripping out rarely used features, simplifying the internal architecture, and relying more heavily on native browser capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17c89424-7b76-4435-88a3-9e6e916cd74e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a function, why is it better to keep it focused on a single responsibility?', N'Fresher', N'A function with a single responsibility is easier to understand, test, and maintain over time. If a bug occurs, it is much simpler to isolate the cause when the function does only one specific task rather than managing multiple unrelated operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca05a503-c822-4fdc-a022-9e75836d235c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is your approach to estimating the capacity needs for a service expecting a sudden traffic spike?', N'Middle', N'I would conduct load testing to identify the breaking points of current infrastructure and establish a baseline performance metric. Based on the projected spike volume, I would calculate the necessary resource scaling and implement auto-scaling policies to handle the surge while monitoring for cost efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d55c75a-818f-44aa-9884-9e75a84c2711', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the significance of the NestJS ''Module Ref'' in handling late-bound dependency resolution.', N'Senior', N'The Module Ref acts as a service locator that allows for the manual retrieval of providers from the DI container at runtime. It is particularly useful when you need to resolve dependencies that are not statically available or when working with dynamic modules that might be instantiated conditionally during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49d68703-9b04-46dd-83aa-9e762bd33996', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''Unit'' type?', N'Fresher', N'The ''Unit'' type in Scala is equivalent to ''void'' in languages like Java. It indicates that a function or expression returns no meaningful value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55cf6468-4bcc-4106-87d3-9e77b0d04eff', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system, how do you decide where to implement validation logic: on the client-side or the server-side?', N'Middle', N'Client-side validation is essential for providing immediate user feedback and reducing unnecessary network round-trips. However, server-side validation is mandatory for security and data integrity. I treat client-side validation as a UX convenience, while server-side validation is the final, authoritative gatekeeper.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4581471a-f842-42eb-b6cf-9e7a0c198a53', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the ''Qwik Loader'' script in the document?', N'Senior', N'The Qwik Loader is a tiny, highly optimized snippet of JavaScript included in the initial HTML. Its sole responsibility is to intercept events and coordinate the fetching of the necessary Qrls, acting as the entry point for the framework''s lazy-loading mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'224b3736-4522-4185-8d1b-9e7b8f49c9af', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is a read-through cache strategy?', N'Middle', N'In a read-through cache, the application always talks to the cache, and the cache is responsible for fetching data from the database if a miss occurs. This simplifies the application logic and ensures that the cache stays populated with requested data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22e870ef-32be-4a6f-838f-9e7d8821e900', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is ''Write Concern: 0'' risky for production environments?', N'Senior', N'Using a write concern of 0 means the client does not wait for any acknowledgment from the database. If a network error or node failure occurs, the client has no way of knowing if the write was successful, leading to potential data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0a902c0-6663-45d3-a24a-9e86b2b8557a', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the Sass @use rule solve the architectural pitfalls associated with the legacy @import system in large-scale applications?', N'Senior', N'The @import rule historically relied on global scope, leading to unpredictable variable overrides and naming collisions across large codebases. In contrast, @use enforces namespaces, requires explicit references to modules, and evaluates files only once regardless of how many times they are imported. This promotes better encapsulation, improves compilation performance, and makes dependency management significantly more predictable in modular architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e048ff3-9c6e-4840-8056-9e8a35228f55', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you investigate a situation where an application is experiencing intermittent TLS handshake failures?', N'Senior', N'I would analyze the client-side and server-side logs to see if there is a mismatch in supported TLS versions or cipher suites. I would also look for network-level issues such as packet loss or MTU size mismatches, which can frequently cause large TLS handshake packets to be dropped or corrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'182fc39d-b217-485b-a98c-9e8b3dfd89b9', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the significance of the ''db/seeds.rb'' file?', N'Intern', N'The seeds.rb file is used to populate the database with initial or default data. It is particularly useful for setting up required configurations or master data that the application needs to function correctly immediately after installation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad399766-e72b-40e2-a1af-9e8b42d58096', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the benefit of a ''fail-fast'' approach to system design?', N'Intern', N'A fail-fast approach identifies and reports errors immediately, which aids in debugging and prevents corrupt data from propagating. The trade-off is that it might cause a system to crash sooner rather than attempting to recover silently, but it creates a more transparent and predictable system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb324706-cd95-482d-bcf1-9e8dd4069575', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the trade-offs of using Echo''s built-in data binding compared to manual parsing?', N'Middle', N'Built-in binding automates the mapping of request data to structs, which reduces boilerplate and improves development speed. However, it can make custom validation logic harder to manage if the input structure does not map perfectly to your internal models, sometimes requiring an extra layer of validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d658856-489f-4813-96dd-9e8e37c9db43', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does the use of Rust''s Futures within Rocket influence the development of long-running requests?', N'Senior', N'Futures allow Rocket to suspend the execution of a handler while waiting for external I/O, freeing up the underlying executor to handle other requests. This is crucial for long-running operations like database queries or external API calls, ensuring the system remains responsive under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b630c29-5866-4cd2-8a8a-9e9000ee92af', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the ''q-manifest'' file?', N'Fresher', N'The q-manifest file is a map generated at build time that tells Qwik which symbols and functions are located in which JavaScript chunks. This allows the framework to know exactly which file to fetch when a specific interaction occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40da934c-455b-48db-b6ce-9e912596388f', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does ''Consistent Hashing'' help in scaling distributed caches?', N'Senior', N'Consistent hashing maps nodes and keys onto a logical ring, ensuring that when nodes are added or removed, only a minimal fraction of keys need to be remapped. This prevents massive cache misses that would otherwise overwhelm the underlying database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc4970b4-217b-4036-be87-9e916df097a3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you access the global Alpine object?', N'Fresher', N'The global Alpine object is attached to the window object in the browser. It provides access to internal methods and utilities, allowing developers to extend Alpine''s functionality or interact with it programmatically from outside the HTML markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3fbd03-ea95-4ead-b280-9e919298631a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you perform a side effect directly inside a reducer?', N'Middle', N'Performing side effects inside a reducer violates the principle of purity, which makes the application behavior unpredictable and non-deterministic. It can break testing, time-travel debugging, and cause inconsistent state updates across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a35a63c8-d971-4737-a41a-9e941c85a11b', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js achieve parallel data fetching?', N'Middle', N'Next.js encourages parallel fetching by initiating multiple fetch requests at the top level of a Server Component without awaiting each one individually. By initiating the requests and awaiting them later, you ensure that the server processes the data in parallel, reducing total load time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
