INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'255c333c-b5ea-466e-8b9f-9e9c27c4dbde', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Define the concept of ''Vector Clocks'' and their utility in conflict resolution.', N'Senior', N'Vector clocks track the causal history of updates across nodes by maintaining a counter for each replica. They allow the system to determine if one update strictly follows another, if updates are concurrent, or if they have diverged, providing the necessary metadata to resolve conflicts during data merging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
