INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31e09f8a-9f7a-43f5-b050-9eaab81f2bcb', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is an asynchronous function in Dart?', N'Intern', N'An asynchronous function is a function that can perform operations without blocking the main execution thread. It typically uses the async and await keywords to handle tasks like network requests or file I/O efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a0006d-8c1b-466e-9ac4-9eaace43ab37', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the memory management challenges posed by long-lived event listeners attached to the window or document object.', N'Senior', N'If event listeners attached to global objects are not explicitly removed when components are destroyed, they maintain references to those components in memory. This prevents the garbage collector from reclaiming the memory, eventually leading to a memory leak in single-page applications that frequently mount and unmount views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e26715a1-b5c6-412b-b4bf-9eacae18de8e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the concept of ''Immutability'' in Redux?', N'Intern', N'Immutability means that you never change the existing state object directly. Instead, you return a new copy of the state with the necessary updates, which helps Redux track changes efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f86c91d9-5b33-4bfa-ae97-9ead7f79eb45', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What do you think of CommonJS vs ESM?', N'Middle', N'JavaScript has evolved its module systems. ESM (ECMAScript Modules) using import / export is the official standard, natively supported in modern browsers and Node.js, designed for both synchronous and asynchronous use cases. CommonJS (CJS) using require / module.exports was the original standard for Node.js, primarily synchronous, and remains prevalent in the Node ecosystem. AMD (Asynchronous Module Definition) using define / require was an early system designed for asynchronous loading in browsers but is now largely obsolete, replaced by ESM. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'170206de-83f1-409b-9fc0-9eadb3a7dde7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of using AdonisJS middleware compared to standard Express middleware?', N'Middle', N'AdonisJS middleware is strictly typed and integrated into the framework''s lifecycle, allowing for predictable execution order and easier dependency injection. Unlike the loose structure of some other frameworks, AdonisJS middleware can easily access the IoC container to perform complex operations like authentication or role-based access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baf633e0-9b8b-4e8a-8fa1-9eb22f115ac9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens if a primary shard fails?', N'Intern', N'If a primary shard fails, Elasticsearch promotes one of its replica shards to become the new primary shard. This process ensures that the cluster remains operational and no data is lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'795897c8-e8d6-41f3-a51e-9eb3213ffaea', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do Python''s closure mechanisms work?', N'Middle', N'Closures allow a nested function to capture and retain references to variables from its enclosing scope, even after the outer function has finished executing. This is achieved by storing the non-local variables in a cell object attached to the nested function''s closure attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12300308-83d6-4f93-84e6-9eb32647916c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a View Component in ASP.NET Core?', N'Fresher', N'A View Component is similar to a partial view but is much more powerful because it contains its own logic. It is used to render chunks of a page that are reused across different parts of an application, such as a shopping cart summary or a login widget.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eaa058c-8987-43c6-9cd4-9eb33f558e47', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a scope function in Kotlin?', N'Intern', N'Scope functions are standard library functions that execute a block of code within the context of an object. They make code more readable by grouping operations on an object without needing to repeatedly reference the object name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3dd9c4e-442b-4f02-81b0-9eb41cec9bf5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between `__new__` and `__init__` in the object creation lifecycle?', N'Senior', N'__new__ is a static method responsible for creating and returning a new instance of the class, while __init__ is an instance method that initializes that instance. __new__ is rarely overridden except in cases involving immutable types or metaclasses, whereas __init__ is used for standard attribute setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0f2b9df-9071-4827-96ce-9eb6a3d98142', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the browser''s preload scanner improve performance, and what are its limitations?', N'Senior', N'The preload scanner parses the raw HTML byte stream in the background while the main parser is blocked by script execution. It identifies and fetches critical resources like CSS and images early, but it cannot execute JavaScript or handle dynamically injected elements, meaning it relies entirely on the initial markup structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ed65fe7-510f-4578-8ea0-9eb71bcf825a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony EventDispatcher component improve application architecture?', N'Middle', N'The EventDispatcher implements the observer pattern, allowing different parts of the application to communicate without being tightly coupled. It enables developers to hook into the request-response lifecycle or custom business logic triggers, enhancing extensibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d01d8f9-f98a-4025-bb63-9ebec59e4662', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In terms of API design, what is the trade-off between REST and GraphQL?', N'Junior', N'REST is predictable, easy to cache at the network level, and follows standard HTTP conventions, but it can lead to over-fetching or under-fetching of data. GraphQL allows clients to request exactly the data they need, reducing bandwidth usage, but it increases server-side complexity and makes caching significantly harder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78d2ddc9-8087-485e-a0d3-9ec01e0453fd', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a list and a tuple in Python, and when would you choose one over the other?', N'Junior', N'A list is mutable, meaning its elements can be changed after creation, whereas a tuple is immutable and cannot be modified. You should use a list when you need a collection of items that may change throughout the program''s execution. Tuples are preferred for fixed collections of data where you want to ensure the integrity of the information and prevent accidental modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61e62735-f336-4d88-9e49-9ec24b63898b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the ACID properties in a database?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data validity even in the event of errors or power failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b79e17e2-3165-4176-83f6-9ec2a4965028', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle the ''planning fallacy'' when estimating long-term roadmap items?', N'Middle', N'I account for known unknowns by adding a buffer based on historical team velocity and past project performance. Additionally, I utilize rolling-wave planning where estimates become more granular as we approach the execution phase, reducing the error margin of long-term projections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad7df98-c11a-40a2-a89d-9ec52681714a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Explain the concept of eventual consistency and why it is used in distributed systems.', N'Middle', N'Eventual consistency allows for high availability and low latency by accepting that different nodes might hold slightly different versions of data for a short time. It is used because strictly enforcing strong consistency across global regions often incurs prohibitive latency costs due to the CAP theorem trade-offs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'273f529b-1013-4a19-ba4d-9ec6bbc8d5f1', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the benefit of a microservices architecture for scalability?', N'Middle', N'Microservices allow independent scaling of individual components based on their specific resource requirements. If one service experiences high traffic, it can be scaled out independently without the need to replicate the entire application monolith.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca127534-40af-43dc-b0a9-9ec78228dffd', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the performance implications of using ''attributeChangedCallback'' in Lit?', N'Middle', N'Excessive attribute changes trigger the full update lifecycle, which can be expensive if performed frequently. Lit optimizes this by batching updates, but developers should still prefer property updates over attribute updates for high-frequency data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbbaf5db-f792-4aa5-928e-9ec810ee5d90', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is data consistency?', N'Intern', N'Data consistency ensures that all copies of data within a database remain identical and accurate throughout transactions. It guarantees that the database adheres to all defined rules, constraints, and relationships after every update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9163ca8-80c6-43a3-abd5-9ec8e77c52a2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain a complex technical concept to a non-technical stakeholder?', N'Intern', N'I would focus on the business value and the ''what'' and ''why'' rather than the ''how''. I would use analogies to relate the technical concept to familiar real-world processes to ensure the stakeholder understands the impact of the decision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
