INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ac38b60-a742-4220-8f25-9ece69b77ea4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is C# and what are its key features?', N'Intern', N'C#, pronounced "C-sharp," is an object-oriented, multi-paradigm programming language developed by Microsoft as part of its .NET initiative. It''s widely used for developing applications targeting the Windows ecosystem. Key Features of C 1. Simplicity: Cstreamlines complex tasks, making common programming patterns more manageable. 2. Type Safety: It employs a robust type system that mitigates many common programming errors at compile time. 3. Object-Oriented Design: It encourages modular, reusable code structures through classes and interfaces. 4. Scalability: Csupports both small, quick programs and large, intricate applications. 5. Cross-Language Support: It integrates seamlessly with other languages in the .NET ecosystem, offering advantages such as unified debugging and code reuse. 6.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
