INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9227676d-8afe-494c-8d86-9ed5566c240b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the dependency injection container in ASP.NET Core handle object lifetimes, and what are the risks of capturing a scoped service in a singleton?', N'Senior', N'The container supports Transient, Scoped, and Singleton lifetimes. Capturing a scoped service in a singleton causes a ''captive dependency'' issue, where the scoped service is effectively promoted to a singleton, potentially leading to concurrency bugs, memory leaks, or stale state issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc9ec484-1732-4f33-bb52-9ed7fabb1654', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the difference between @apply and inline utility classes?', N'Intern', N'Inline utility classes are applied directly in the HTML markup. The @apply directive is used in CSS files to extract repeated utility patterns into a single custom class name, which can help clean up cluttered HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e1977be-e665-443b-82fe-9edbcab1d6f7', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the access modifiers in Java and what do they control?', N'Junior', N'Access modifiers are keywords like private, protected, public, and default that control the visibility and accessibility of classes, methods, and variables. They define which other parts of the code can interact with a specific member.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'558a894c-cad8-4357-a588-9edc138dd8a9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you balance the need for high-accuracy estimates with the need for agile delivery speed?', N'Middle', N'I use relative sizing techniques like story points to estimate complexity rather than absolute hours, which is faster and less prone to individual productivity bias. This allows the team to maintain a steady cadence while still providing stakeholders with reliable long-term delivery projections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e54cd3f5-1d2c-4300-92c6-9eddcf3fac6b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is idempotency a critical design requirement for distributed services?', N'Middle', N'In distributed systems, network failures often lead to retries, meaning a request might be executed multiple times. Idempotency ensures that multiple identical requests do not result in unintended side effects or corrupted data states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07b37aa3-af52-472b-a3d3-9edf5a3f55be', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the benefit of eventually consistent reads?', N'Fresher', N'Eventually consistent reads are more cost-effective and provide lower latency because they do not require the database to ensure all replicas are updated before returning the result. They are ideal for applications where absolute real-time accuracy is less critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ecfdbfb-5433-4b9a-a92c-9edfa5d04ee4', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support environment-specific configurations?', N'Junior', N'Micronaut allows for environment-specific configuration files, such as application-dev.yml or application-prod.yml. The framework automatically loads the file corresponding to the active environment at startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'662ade75-4b03-4fa5-baa3-9ee0e53cdaa1', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why should you check the return value of ''malloc''?', N'Junior', N'Malloc returns a null pointer if it fails to allocate the requested amount of memory. Checking for null allows the program to handle the failure gracefully instead of crashing due to a null pointer dereference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89ad6b33-d429-43e6-9110-9ee1431a7e0f', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Can Webpack bundle CSS files?', N'Fresher', N'Yes, Webpack can bundle CSS files, but it requires specific loaders to process them. Typically, ''css-loader'' is used to interpret CSS imports, and ''style-loader'' is used to inject the resulting CSS into the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'638c756b-9a3c-49d1-ac1e-9ee3c3546457', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s error handling strategy affect system resilience?', N'Senior', N'Fastify provides a centralized error handler that allows developers to define global or scoped error responses. This ensures consistent API error structures and prevents sensitive internal server details from leaking to clients while maintaining a clean separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5701b51-af6d-4b78-8c23-9ee49331835b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the benefits of strict type safety versus dynamic typing in large-scale systems?', N'Senior', N'Strict type safety reduces runtime errors and improves code documentation, which is vital for large, long-lived codebases. Dynamic typing offers rapid prototyping and flexibility, but shifts the burden of validation to tests and runtime, which can lead to brittle systems at scale. I prefer strict typing for core business logic and infrastructure where correctness is non-negotiable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74c7e6a3-6733-4ee4-b624-9ee7101b79a4', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the role of a circuit breaker in a scalable architecture?', N'Middle', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail. By failing fast and stopping requests to a struggling service, it prevents cascading failures and gives the downstream service time to recover, maintaining overall system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8f83b1c-4f96-4882-95f0-9ee8cc2695ea', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle route nesting?', N'Fresher', N'Route nesting is achieved by calling the Route method on a router instance, which creates a sub-router for a specific path prefix. This enables hierarchical organization of API endpoints, such as grouping all versioned routes under a /v1 prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
