INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b19be593-08b5-41d2-b972-9ef8e7ef18c0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of the ''Unsafe'' keyword?', N'Middle', N'The ''unsafe'' keyword tells the compiler that the developer is taking responsibility for ensuring memory safety in a block of code. It is used for low-level operations that the compiler cannot verify, such as dereferencing raw pointers or calling foreign functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12064d71-c6ee-4734-af2d-9ef9df272d0c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When investigating a security-related bug, how does your mindset differ from a standard functional bug?', N'Junior', N'For security bugs, I prioritize containment and potential impact over just fixing the feature. I assume a malicious actor could exploit the vulnerability, so I focus on validating inputs, checking access controls, and ensuring the patch is robust enough to prevent further unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
