INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be178061-e3cb-4431-906c-9efb1d0f9915', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between a unique key and a primary key?', N'Intern', N'While both ensure uniqueness, a primary key cannot contain null values and there can be only one primary key per table. A unique key allows for null values and multiple unique keys can exist within a single table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'808fcba1-40f1-4bf4-bc45-9efcbe3dbf6a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What happens when an unhandled promise rejection occurs in a modern Node.js version?', N'Senior', N'In recent versions of Node.js, an unhandled promise rejection will trigger an ''unhandledRejection'' event and, by default, terminate the process with a non-zero exit code. This behavior is intended to force developers to handle errors explicitly, preventing the application from continuing in an unstable or indeterminate state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'046f0e33-3e18-4ca0-95d8-9efd3849c2c8', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the concept of ''Cold/Warm/Hot'' architecture in Elasticsearch and why it is used.', N'Senior', N'This architecture optimizes hardware utilization by placing recently ingested data on high-performance NVMe drives (Hot nodes) for fast access. Older, less frequently queried data is moved to cheaper, high-capacity storage (Warm/Cold nodes), reducing total cost of ownership while maintaining acceptable performance for historical data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e82009f9-115e-4f75-adad-9eff968f8fd2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''css'' tagged template literal?', N'Junior', N'The css tagged template literal is used to define styles for a component. It parses the CSS string once for the component class, which makes it more efficient than creating multiple style tags for every instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef9967ee-b786-4fed-a5a7-9f01afed97b4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the function of the Phoenix ''Endpoint'' module?', N'Middle', N'The Endpoint is the entry point for all requests to a Phoenix application. It acts as the supervisor for the application''s supervision tree and handles the initial plug pipeline, including static file serving, instrumentation, and request routing to the appropriate router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37593376-6ffe-460e-a52c-9f01b6d50fbc', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why should you avoid using ''SELECT *'' in production code?', N'Junior', N'Using ''SELECT *'' retrieves every column in a table, which can lead to unnecessary network traffic and memory usage. It is better to explicitly list only the columns you need to improve query performance and code readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8ef7bbb-f818-4c81-8d4e-9f01fb3bfa62', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between a static type and a dynamic type?', N'Intern', N'A static type is checked at compile-time, meaning the type of a variable is known before the code runs. A dynamic type is checked at runtime, meaning the type can change while the program is executing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a754d0d-52cd-480f-9397-9f040d47bf94', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the advantage of using ''fastify-autoload'' in a large-scale project?', N'Middle', N'Autoload automatically loads all plugins and routes from a directory structure, reducing the amount of manual boilerplate code. It simplifies file organization and ensures that all components are registered in the correct dependency order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
