INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3de469eb-0d61-4138-8a86-9f06a285f934', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot perform profile-specific configuration?', N'Junior', N'Spring Profiles allow you to define different configuration sets for different environments, such as ''dev'', ''test'', or ''prod''. You can activate a profile using a property setting, and Spring will load the corresponding configuration file, such as application-prod.properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec931426-197d-4879-a606-9f0ad3b0c6d6', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the architectural trade-offs of using Webpack Module Federation compared to a monolithic build.', N'Senior', N'Module Federation allows for independent deployment and runtime sharing of code between separate builds, reducing the need for monolithic recompilation. However, it introduces risks regarding version mismatch, shared dependency management, and increased runtime complexity for resolving remote modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6512f2b7-c95e-4956-8d33-9f0fc2bac56a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is ''prerendering'' considered a high-performance strategy, and what are its limitations?', N'Senior', N'Prerendering generates static HTML at build time, allowing for near-instant delivery via a CDN with no server-side processing. The limitation is that it does not support truly dynamic or user-specific content, requiring a fallback to CSR or SSR for personalized routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e85780a-4eb3-46ae-93cf-9f1182400ce4', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB''s sharding architecture handle cluster-wide transactions?', N'Senior', N'MongoDB uses a two-phase commit protocol coordinated by the mongos router to manage multi-document transactions across shards. It utilizes a transaction coordinator on the primary shard and a global transaction record to ensure atomicity, though this introduces significant overhead compared to single-shard operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bf653d9-aea2-4591-989d-9f12c604bb8d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your approach to debugging a system that shows ''silent failures'' where requests are acknowledged but no data is processed?', N'Senior', N'I would trace the asynchronous message flow to ensure that the producer is successfully committing to the broker and that the consumer is correctly acknowledging the delivery. I would also investigate the consumer''s error handling and retry logic to see if messages are being silently dropped due to unhandled exceptions or poisoning in the message queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eccbd5e-ed8b-4160-8ae7-9f134dd0a6b3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does a database detect a deadlock?', N'Middle', N'Databases typically use a Wait-For Graph to track which transactions are waiting for locks held by others. If the graph contains a cycle, the database identifies a deadlock and will automatically abort one of the transactions to break the loop and allow the others to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'577c6dd9-1d7c-4f14-8a9f-9f13f1be28a9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure data safety during a master-replica failover?', N'Senior', N'Redis uses an offset-based synchronization mechanism where replicas track their progress against the master''s replication buffer. During failover, the replica that is most up-to-date is promoted to master, minimizing the risk of data loss, though asynchronous replication means some recent writes may still be lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d541634-eb1f-496f-816a-9f14f2e106e8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Discuss the impact of FastAPI''s request validation on API security.', N'Senior', N'By enforcing strict schemas via Pydantic, FastAPI provides a first line of defense against injection attacks and malformed input. This automatic validation prevents unexpected data types from reaching the business logic, effectively sanitizing the input surface area of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be174791-b564-4210-a25c-9f1611d77b84', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the challenges of maintaining referential integrity in a horizontally scaled NoSQL database?', N'Senior', N'NoSQL systems often lack native support for foreign key constraints because enforcing them across distributed nodes would require expensive distributed transactions. Developers must handle referential integrity at the application layer, often leading to eventual consistency where orphaned records may exist temporarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51eaa253-34bd-4f8f-a575-9f18d68d2369', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using tagged template literals?', N'Fresher', N'Tagged template literals allow Lit to pre-parse the static parts of your UI structure. This optimization means the browser doesn''t have to re-evaluate the entire template every time a change occurs, significantly improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e826f98a-de43-459b-b479-9f1a0541e578', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are default arguments in Kotlin functions?', N'Intern', N'Default arguments allow you to assign a default value to function parameters. If the caller does not provide a value for that parameter, the default one is used, which reduces the need for function overloading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e87e81d-75d3-4cc8-8323-9f1e09c0c893', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the key features of Node.js?', N'Intern', N'* Asynchronous and Event driven – All APIs of Node.js are asynchronous. This feature means that if a Node receives a request for some Input/Output operation, it will execute that operation in the background and continue with the processing of other requests. Thus it will not wait for the response from the previous requests. * Fast in Code execution – Node.js uses the V8 JavaScript Runtime engine, the one which is used by Google Chrome. Node has a wrapper over the JavaScript engine which makes the runtime engine much faster and hence processing of requests within Node.js also become faster. * Single Threaded but Highly Scalable – Node.js uses a single thread model for event looping. The response from these events may or may not reach the server immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2558e86-5da8-43c3-93d8-9f1ec2716644', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of ''Dead Letter Queues'' in message-driven architectures?', N'Senior', N'Dead letter queues act as a holding area for messages that cannot be processed successfully after multiple retries. This prevents malformed or problematic messages from blocking the primary processing pipeline and allows engineers to inspect and debug failures without losing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36b68fb2-9d29-448b-a8b5-9f23167dbadd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check whether an object can be extended or not', N'Fresher', N'The Object.isExtensible() method is used to determine if an object is extendable or not. i.e, Whether it can have new properties added to it or not. Note: By default, all the objects are extendable. i.e, The new properties can be added or modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1cff7df-48a2-44dd-8715-9f26278327d6', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why are ''Enums'' with associated values considered powerful for modeling state?', N'Senior', N'Enums with associated values allow for sum types that can carry distinct data per case, enabling exhaustive state representation. This forces developers to handle every state explicitly, which, combined with the compiler''s safety checks, effectively eliminates invalid state transitions and nullability issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59247594-edf6-4801-a2d7-9f268b660816', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of the ''untrack'' function in SolidJS?', N'Senior', N'untrack is used to read signal values without establishing a reactive dependency. This is critical for preventing an effect or computation from being triggered by a specific signal while still allowing it to be triggered by others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae01c9c4-b3f0-4ae8-aca1-9f2b6d634a2f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is an optimistic locking strategy?', N'Junior', N'Optimistic locking assumes that multiple transactions can complete without affecting each other. Instead of locking data, it checks if the data has changed since it was read before committing the update, preventing overwrites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dd436c0-72a0-4358-8e2c-9f2d3e2e8578', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do you monitor Redis performance in a production environment?', N'Middle', N'Performance monitoring involves tracking key metrics such as CPU usage, memory fragmentation, total connected clients, and command latency using the INFO command or external monitoring tools. Specifically, watching for slow queries and cache hit/miss ratios helps identify bottlenecks and optimize memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a6d5681-d53f-4ab6-86c1-9f2d9bcd12e3', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the significance of the CAP theorem for NoSQL database design.', N'Middle', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. NoSQL databases must choose which two to prioritize based on the specific requirements of the application, such as favoring availability during network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5189825c-86ff-460d-9f5a-9f2db25b85fd', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the trade-offs of using Spring Data JPA vs. Spring Data R2DBC in high-throughput systems.', N'Senior', N'JPA uses a blocking I/O model based on JDBC, which can lead to thread starvation under high concurrency. R2DBC offers a non-blocking, reactive approach that improves scalability by handling more concurrent requests with fewer threads, though it requires a shift to a completely reactive programming model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b7364c9-0ec9-4c23-a645-9f32b9ab4d4b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the interaction between cache consistency and CAP theorem constraints.', N'Senior', N'Caching often forces a choice between consistency and availability; maintaining strict cache consistency typically requires synchronous communication that reduces availability during network partitions. Most distributed caches prioritize performance and availability, accepting eventual consistency as a tradeoff.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f4ac0ed-9f71-44af-af69-9f342e6c1113', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the architectural considerations for scaling a Rails application''s background job processing?', N'Senior', N'Decouple job queues from the web server by using a dedicated worker process model like Sidekiq or Resque backed by Redis. Ensure jobs are idempotent, handle retries with exponential backoff, and monitor queue depth to trigger horizontal scaling of worker nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ad73c07-ecab-4c38-a96c-9f34a07dde37', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for troubleshooting a memory leak in a production environment?', N'Middle', N'I analyze heap dumps at different time intervals to identify which objects are not being garbage collected. I compare these dumps to detect growth patterns in specific classes, then review the code paths that handle those objects to find missing clean-up operations or static references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4de7e96-b3e1-4074-b6a1-9f35bb3e1955', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the cost-effectiveness of implementing a microservices architecture versus a monolith?', N'Senior', N'I evaluate the organizational cognitive load, deployment velocity requirements, and the necessity for independent scalability of components. If the team size and domain complexity do not justify the operational overhead of microservices, I would argue for a modular monolith to maintain simplicity without sacrificing future extensibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'046e4395-89d0-4a7a-b441-9f37958832ed', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a router-level middleware?', N'Fresher', N'Router-level middleware works in the same way as application-level middleware, but it is bound to an instance of express.Router(). This allows for modularizing code by grouping routes and their associated middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dee63c3a-926d-4241-897d-9f3875277062', N'954a0331-deff-4399-b588-96f39fec001d', N'What are ''Guards'' and why are they used?', N'Middle', N'Guards are interfaces that tell the router whether it should allow navigation to a requested route. They are essential for security and UX, used for tasks like checking authentication status, confirming unsaved changes, or loading data before navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36b1b69f-6476-4830-9258-9f3bfbd4c00a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of TypeScript in frontend development?', N'Intern', N'TypeScript is a statically typed superset of JavaScript that adds optional type definitions to the language. Its main purpose is to catch errors during development through static analysis, which helps improve code quality and maintainability in large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'190ffbe3-7a56-467d-931c-9f3f394ad4b9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the significance of the trie-based router in terms of memory usage?', N'Middle', N'The trie structure is memory-efficient because it stores common route prefixes only once. This is significantly more compact than storing a flat list of paths or complex regex patterns when dealing with large-scale APIs with hundreds of endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7bd8b41-f952-4336-93ec-9f43f6239efb', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the concept of ''Data Down, Actions Up'' (DDAU) and its impact on application architecture.', N'Senior', N'DDAU enforces unidirectional data flow by ensuring data only flows into components via properties, while changes are communicated back through actions. This pattern simplifies debugging and testing by making the origin and destination of state mutations explicit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8675845a-0b2d-4116-8149-9f44428d96db', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''cache-loader'' and its impact on the build pipeline?', N'Senior', N'Cache-loader caches the output of expensive loaders to disk, significantly reducing build times for subsequent runs. While it improves speed, it adds slight overhead and requires proper configuration to ensure the cache is invalidated correctly when source code or dependencies change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a414378f-24ba-419e-916b-9f46afb5b666', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB ensure data durability?', N'Middle', N'DynamoDB synchronously replicates data across three different Availability Zones within an AWS region by default. This design ensures that the data is protected against hardware failures, software bugs, or even the loss of an entire data center.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62b1f278-b1c6-46eb-872c-9f47759bb6c9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the impact of function pointer usage on compiler optimization?', N'Senior', N'Function pointers make it difficult for the compiler to perform inter-procedural analysis or inlining because the target of the call is only resolved at runtime. This creates an indirect call that prevents the compiler from making assumptions about the state of the program before and after the function execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4050db64-aea7-469b-a1ce-9f47ae189d7c', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the benefit of using ''by-name'' parameters in logging or assertion libraries?', N'Middle', N'By-name parameters prevent the evaluation of the passed expression if it is not needed by the function logic. In logging, this means expensive string concatenation or data fetching only occurs if the log level is enabled, saving significant CPU cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'567c0e79-9df7-4cb0-97bf-9f48d351d29f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the trade-off of using Rocket''s ''Managed State'' compared to a global singleton or external cache?', N'Senior', N'Managed state provides thread-safe, dependency-injected access to shared resources like database pools. While it simplifies testing by allowing easy substitution of mocks, it requires careful management of synchronization primitives to avoid contention when shared across many high-concurrency request threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'133510ee-8c70-4f0e-b9d9-9f4af8a203d7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''Cache Stampede'' and how can Redis help prevent it?', N'Junior', N'A cache stampede occurs when many concurrent requests hit a cache, find a miss, and all try to regenerate the same data at once, overwhelming the backend. Redis can help by using locking mechanisms or by re-populating the cache before the expiration time is reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc7bdf8-ee0f-4005-9336-9f4c74a898e2', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the benefit of AOT compilation in Dart?', N'Intern', N'AOT compilation translates Dart source code into native machine code before the application is even run. This results in faster startup times and more consistent performance compared to JIT compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a72d99b4-af57-4c9c-9d34-9f503909ec71', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is hydration and why does Qwik try to avoid it?', N'Intern', N'Hydration is the process where a framework attaches event listeners and state to server-rendered HTML on the client. Qwik avoids it because hydration requires downloading and executing large amounts of JavaScript before the page becomes interactive, which slows down the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07b0ca3c-3f9a-4b9b-8d63-9f513cb07fb7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why is ''MainActor'' critical for UI development in Swift?', N'Senior', N'MainActor ensures that UI updates and state mutations occur on the main thread, which is a requirement for thread-safe rendering in frameworks like UIKit and SwiftUI. By using the MainActor attribute, the compiler enforces that annotated code is only executed on the main queue, preventing race conditions. This declarative approach replaces error-prone manual dispatching to the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c54d274-d793-49c0-844c-9f5211c0ef30', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the significance of R''s ''formula'' objects in statistical modeling.', N'Senior', N'Formula objects encapsulate a symbolic representation of a model''s structure, allowing R to perform deferred evaluation and data transformation. This architecture separates the definition of the model from the data, enabling the same formula to be applied to different data sources dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33e82944-068f-45a2-9761-9f5284b004c5', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can Fiber serve HTML templates?', N'Fresher', N'Yes, Fiber has built-in support for template engines like HTML, Handlebars, or Pongo2. This allows the backend to render dynamic server-side pages before sending them to the client browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eacac26-2363-4f04-af00-9f53a1618f73', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does ''denormalization'' mean in the context of NoSQL?', N'Fresher', N'Denormalization is the practice of storing related data together in one place, such as embedding a list of addresses inside a user document. This is done to improve read performance by avoiding the need to perform joins between multiple tables or collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd73a4ccb-8e1c-4315-9b2e-9f53dc66f96a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the significance of the ''routing'' parameter in document indexing?', N'Middle', N'The routing parameter determines which shard a document is placed in by hashing the value. Using a custom routing key allows related documents to be co-located on the same shard, which significantly speeds up queries that target specific related data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a80830c-c7e1-47a0-96e2-9f542afcea9e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the benefit of using an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point that handles cross-cutting concerns like authentication, SSL termination, and request routing. It simplifies the client-side implementation by hiding the internal service structure and provides a centralized place to apply security policies and monitoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06e930d0-1141-4777-9960-9f59219537b6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Describe the mechanism behind Litestar''s plugin system and its impact on framework extensibility.', N'Senior', N'Litestar''s plugin system allows for deep integration with third-party libraries by hooking into the application lifecycle and dependency resolution process. This enables seamless integration of ORMs or external services without polluting the core codebase, ensuring a modular and pluggable architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'100cb887-f804-4069-80d2-9f5a5ff8b237', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s ''Dependency Pre-bundling'' during development?', N'Fresher', N'It reduces the number of network requests the browser makes by combining multiple small dependency files into a single module. This prevents common issues with deeply nested node_modules structures and improves initial page load speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'493d72e0-7188-462f-9e66-9f5fd9b6bb28', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do materialized views in Cassandra differ from those in RDBMS?', N'Senior', N'In Cassandra, materialized views are maintained by the server and updated asynchronously, which can lead to temporary inconsistencies between the base table and the view. RDBMS views are often computed on-the-fly or synchronously, offering stricter consistency but lower write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a66e141f-c212-4fc9-8aaf-9f60403f5089', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the mechanics of the ''Data Race Detector'' in Go.', N'Senior', N'The race detector uses a technique called ThreadSanitizer, which instruments memory access operations during compilation. It maintains a shadow memory that tracks the history of accesses to each memory location, identifying concurrent reads and writes that are not protected by synchronization primitives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53b62e76-e61a-489b-9254-9f6675470aa1', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of interior mutability in Rust?', N'Middle', N'Interior mutability allows for modifying data even when a variable is held as an immutable reference. It is achieved through types like RefCell, which perform runtime borrow checking, enabling patterns like shared mutable state that would otherwise be forbidden by the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fe242df-66f5-4065-8da6-9f6799e8a24d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What happens if a plugin fails to register in a Fastify application?', N'Middle', N'Fastify treats plugin registration as a synchronous or asynchronous lifecycle process that must succeed for the server to start. If a plugin fails during registration, the application will emit an error and prevent the server from listening, ensuring a fail-fast startup behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a8ceb29-02bb-4511-a7fc-9f67a95f4d47', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the implications of using a ''tombstone'' in a distributed database?', N'Senior', N'Since deletes in log-structured systems are effectively writes, a tombstone is a marker indicating that a record has been deleted. These markers must be kept until a compaction process physically removes the underlying data, which can lead to storage overhead and logic complexities during read merges.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4efcdd22-f0a2-46c7-8737-9f68c00537bc', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Define ''Distributed Deadlock'' and how it is typically addressed.', N'Senior', N'A distributed deadlock occurs when two or more transactions across different database nodes are waiting for each other''s resources, creating a cyclic dependency. It is usually addressed through timeout mechanisms, global deadlock detection algorithms, or by ensuring strict ordering of resource acquisitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc58be26-3d90-4b65-a7dd-9f68eb02e215', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary goal of Astro''s ''Islands Architecture''?', N'Intern', N'Islands Architecture aims to improve performance by isolating interactive components from the static parts of a page. This allows the browser to load only the necessary JavaScript for specific interactive sections while keeping the rest of the page as static HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf68c5fa-a0dd-49f4-b325-9f6dc50ffd0f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Can Svelte be used for static site generation?', N'Intern', N'Yes, Svelte can be used for static site generation through frameworks like SvelteKit. This allows you to pre-render your application into static HTML files for faster loading and improved search engine optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'480963b1-756c-4775-8250-9f710792e499', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle ''State Management'' synchronization between server and client?', N'Senior', N'Nuxt uses a payload serialization mechanism where the server-side state is stored in the ''nuxtApp'' instance and injected into the HTML as a JSON blob. The client-side automatically picks up this state during hydration, preventing unnecessary re-fetching of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c4a48c0-2c67-4506-87d9-9f72d88d5b45', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to initialize pointers in C?', N'Junior', N'An uninitialized pointer contains a random memory address, often called a dangling or wild pointer. Attempting to dereference such a pointer can lead to undefined behavior, such as segmentation faults or the accidental corruption of data in other parts of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b59b9375-5c6a-462b-b0e8-9f7bed801ca0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the role of the ''void'' keyword in a function?', N'Intern', N'When used as a return type, void indicates that the function does not return any value to the caller. When used in a parameter list, it signifies that the function accepts no arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6a50afd-beb4-4656-b248-9f7c49b47e2b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does database sharding affect the ACID properties of a system?', N'Senior', N'Sharding complicates ACID properties because transactions that span multiple shards can no longer rely on a single local lock manager. Maintaining atomicity and isolation requires complex distributed protocols like two-phase commit or sagas, which significantly increase latency and reduce throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5655170e-e192-41ef-9030-9f7ccc406fd2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Twig template engine in Symfony?', N'Intern', N'Twig is a template engine that separates the presentation logic from the backend business logic. It provides a secure and concise syntax for rendering dynamic HTML content in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30ffbe25-90cd-40d7-b44d-9f7d72f5c309', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What strategies would you use to optimize Django’s performance under heavy read loads?', N'Senior', N'Strategies include implementing database read replicas with a custom database router, aggressive caching of view results or querysets, and optimizing ORM queries by selecting only necessary fields via .only() or .values(). You can also offload static assets to a CDN to reduce the load on the application server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3147f0a8-58ee-45d9-b2a8-9f8006c0ce01', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How can you perform complex aggregations in DynamoDB?', N'Middle', N'DynamoDB is not designed for complex aggregations or joins like SQL databases. To perform such operations, it is best practice to stream data to Amazon OpenSearch or a data warehouse like Redshift using DynamoDB Streams to handle analytical queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
