INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa2970db-2f14-4558-afae-9f898f51b277', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the architectural benefits of using ''Frozen String Literals'' in Ruby?', N'Senior', N'Enabling frozen string literals reduces memory allocation by preventing the creation of new string objects for identical string constants. This lowers the pressure on the garbage collector and improves performance by allowing the VM to reuse the same memory address for string literals across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'946785a8-50f8-4dff-91c2-9f907bc73dab', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber''s request context handling differ from net/http?', N'Middle', N'In Fiber, the context object is pooled and reused across requests to improve performance. Because of this, you must never store a reference to the context object or its members after the handler has returned, as the underlying memory will be reclaimed and reassigned to a new request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a26eb6ab-3fea-421d-b745-9f90a3833cc1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the concept of Dependency Injection in NestJS. How does it help in building modular and testable applications?', N'Fresher', N'Dependency Injection (DI) is a design pattern in which a class receives its dependencies from external sources rather than creating them itself. This pattern is fundamental to the way NestJS is designed. dependency injection involves letting the framework manage the creation and injection of dependencies into the components (controllers, services, and more) as needed. This is achieved through decorators, providers, and the NestJS IoC (Inversion of Control) container Here is an example: In this example, AppService is a provider that is injected into AppController through the constructor. When AppController is created, NestJS automatically creates an instance of AppService and passes it to the constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beb8df0e-0ce1-41fc-8f07-9f90ec7a8e01', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle request binding and why is it preferred over manual parsing?', N'Middle', N'Gin''s binding mechanisms automatically infer the data type and validation rules from struct tags. This reduces boilerplate code and enforces strict schema validation at the entry point of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8b33aa4-01fd-41f4-a651-9f91e0a7e61f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'When would you prefer using Tailwind''s ''container'' class over manually defined widths?', N'Middle', N'The container class is useful when you want to enforce a standard max-width and horizontal alignment across your site based on the theme configuration. It simplifies responsive design by automatically adjusting widths based on defined breakpoints, rather than forcing you to define pixel widths everywhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b8f369e-050b-4312-8cd3-9f96c529bdde', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus achieve ''Build Time'' optimization?', N'Junior', N'Quarkus analyzes the application code, dependencies, and configuration during the build process to resolve as much metadata as possible. By pre-computing these structures and removing unused code, it drastically reduces the work required by the JVM when the application starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'044de545-4cb3-4b0f-adaa-9f9a45ead29c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle security-related bugs that involve sensitive user data?', N'Middle', N'I would prioritize isolating the affected component and disabling the vulnerable feature to prevent further data exposure. I would conduct a thorough audit of the logs to determine the extent of the impact and ensure that all access was logged. The fix would involve applying the necessary security patches and potentially rotating credentials or keys that were compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bc11317-e9c8-4e2b-99f1-9f9bed8c94a3', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between static and dynamic dispatch in Rust, and when should you prefer one over the other?', N'Middle', N'Static dispatch uses generics with trait bounds, allowing the compiler to generate specialized code for each type, which enables aggressive inlining and better performance. Dynamic dispatch uses trait objects, providing flexibility for heterogeneous collections, but it introduces a small runtime overhead due to vtable lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0855712-f0b0-41ec-a9c9-9fa0c12495f8', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the ''ngOnChanges'' lifecycle hook?', N'Middle', N'The ngOnChanges hook is triggered whenever one or more input properties of a component change. It is primarily used to respond to parent-to-child data updates that require logic to be executed based on the new input values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'382060fd-d52c-4fe9-845e-9fa386b153d5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is a deadlock and how can it be avoided?', N'Fresher', N'A deadlock occurs when two or more processes are blocked forever because each is waiting for the other to release a resource. It can be avoided by ensuring that resources are always acquired in a consistent, predefined order across the entire system. Implementing timeouts for resource requests can also help break potential deadlocks before they cause a system freeze.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fb33fe4-503e-4d91-b1fb-9fa44834672a', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between an element being ''painted'' and ''composited''?', N'Senior', N'Painting is the process of filling in pixels, text, colors, and shadows, while compositing is the process of drawing these painted layers in the correct order to the screen. Offloading as much as possible to the compositor layer is critical for maintaining high frame rates during animations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7957174d-c56f-4b2f-bb18-9fa640dfbb1c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB ensure atomic updates?', N'Middle', N'DynamoDB supports atomic counters using the UpdateItem operation, which allows you to increment or decrement a numeric attribute without needing to read the current value first. This prevents race conditions in scenarios where multiple processes attempt to modify the same attribute simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad5347ea-b086-498e-a705-9fa7d0683842', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s hydration process work during Server-Side Rendering (SSR), and what causes hydration mismatches?', N'Senior', N'Hydration is the process of attaching event listeners and reactive state to the static HTML provided by the server. Mismatches occur when the server-rendered DOM structure differs from the client-side virtual DOM, often caused by non-deterministic data like timestamps or window-dependent logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2683220-5e3f-47f3-943b-9fa8429c7b70', N'075b8862-431c-4678-9767-f55359758a4a', N'What are Dynamic Directive Arguments?', N'Intern', N'In Vue 2.6 release onwards, Directive arguments can now accept dynamic JavaScript expressions. i.e, the specific argument that we want to use is only known at runtime. Let''s assign dynamic key and event directives for a div element,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ac7c0a4-d0c9-4dec-b236-9faede106d79', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you achieve transactional consistency in DynamoDB?', N'Senior', N'DynamoDB Transactions (TransactWriteItems and TransactGetItems) provide ACID compliance by allowing you to group multiple operations into a single atomic transaction. This ensures all operations succeed or fail together, preventing partial state updates across different items or tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0035ca57-c8f2-44ba-af66-9faf22f7fe2a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why should you design for failure in a distributed system?', N'Intern', N'In distributed systems, hardware and network failures are inevitable rather than exceptional. Designing for failure ensures the system can gracefully handle outages, perform retries, or failover to a healthy state without crashing the entire service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eed81cf8-d036-4f24-a3df-9fafcda69709', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When should you implement an API Gateway pattern?', N'Middle', N'An API Gateway is useful when you need a single entry point to manage cross-cutting concerns like rate limiting, authentication, and request routing across multiple backend services. It simplifies the client-side experience but adds a centralized component that must be monitored to avoid becoming a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48a66984-ec2b-4cdf-8988-9fb139c7e4cb', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between fetch() and XMLHttpRequest() in JavaScript?', N'Fresher', N'1. XMLHttpRequest: XMLHttpRequest() is a built-in browser object that allows to make HTTP requests in JavaScript. XMLHttpRequest has two modes of operation: synchronous and asynchronous. Example: &#9885; Try this example on CodeSandbox 2. Fetch(): Fetch allows to make network requests similar to XMLHttpRequest. Fetch makes it easier to make asynchronous requests and handle responses better than with the older XMLHttpRequest. It is an improvement over the XMLHttpRequest API. The main difference between Fetch() and XMLHttpRequest() is that the Fetch API uses Promises, hence avoiding callback hell. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e5aded4-772c-458e-aab0-9fb21bcb21b1', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between a Redis ''Client-side Cache'' and server-side caching?', N'Middle', N'Client-side caching involves storing data in the application''s memory to avoid network latency to the Redis server. Server-side caching is the standard Redis model where data is stored in the remote Redis node, providing a centralized cache that is shared across multiple application instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c659c326-5290-450f-bee1-9fb4b0b0a894', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What role does jQuery play in the context of modern ''Buildless'' or ''Zero-bundle'' architectures?', N'Senior', N'jQuery is generally antithetical to modern zero-bundle architectures because it is a monolithic library that forces the inclusion of many features that are likely unused. Modern development favors micro-libraries or native browser APIs to keep the bundle size minimal and the execution performance high.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce013cb8-4590-4456-b1a1-9fb79f25c278', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are route handlers in Litestar?', N'Intern', N'Route handlers are functions or methods decorated with specific path decorators. They are responsible for processing incoming HTTP requests and returning appropriate responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c176b65a-26d3-4a49-bdc2-9fb8539e3df6', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the benefit of using an API Gateway in front of a Node.js microservice architecture?', N'Middle', N'An API Gateway centralizes cross-cutting concerns like authentication, rate limiting, and request logging. It simplifies the client-side interaction by providing a single entry point and decouples the internal service structure from the external interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a44d4f5c-c2e9-4e29-ae9d-9fb996d1f4e4', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Rails ''counter_cache'' and how does it improve performance?', N'Middle', N'A counter cache maintains a count of associated objects directly on the parent model, avoiding the need to perform a COUNT query on the child table every time the number of associations is needed. This significantly improves performance when displaying lists of records that include counts, such as comments on a blog post.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11671251-1f7f-4a30-8381-9fbe633ec1b3', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are Laravel Contracts?', N'Intern', N'Laravel Contracts represent interfaces that define core framework services and are essential for facilitating modular, component-based application design. By providing defined methods, Laravel Contracts ensure interoperability between various components and services. This results in an environment where different pieces of the ecosystem can ''contract'' to a set of specified behaviors. This helps in maintaining loose coupling between software components. Key Benefits - Consistency: Contracts enforce a common structure for interacting components. - Flexibility: They facilitate interchangeable implementations for services. - Ease of Testing: Contracts enable robust unit testing by ensuring precise behavior specifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'120958fb-b80e-481b-a000-9fc0fc5863a4', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the function of the Quarkus ''Health'' extension?', N'Junior', N'The Health extension provides endpoints that report the status of the application, such as liveness and readiness probes. These are crucial for orchestrators like Kubernetes to determine if an application is running correctly and if it is ready to handle incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a84d68c-ffc7-4ee4-9e1b-9fc14f99ad34', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Discuss the importance of ''Chaos Engineering'' in modern architecture.', N'Senior', N'Chaos engineering proactively introduces controlled failures into a production environment to verify the system''s ability to withstand turbulence. It helps uncover hidden dependencies, test automated recovery mechanisms, and validate the effectiveness of observability tools before a real incident occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dc5ca07-6ac9-4ead-acd3-9fc54b36ed1d', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why must reducers be pure functions?', N'Intern', N'Reducers must be pure functions so that they do not produce side effects or mutate the existing state. This ensures that the state transitions are predictable, testable, and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd39f48f-34ea-45aa-ac76-9fc898a75bc0', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between synchronous and asynchronous programming in Dart?', N'Junior', N'Synchronous programming executes tasks one after another, blocking the main thread until each finishes. Asynchronous programming allows tasks to run in the background, keeping the application responsive while waiting for operations like network requests to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ded2aea5-1d58-442e-8327-9fccdea2ec2c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you decide between fixing a bug immediately and implementing a long-term architectural change?', N'Middle', N'I weigh the severity and impact of the bug against the technical debt and risk associated with an architectural shift. If the bug is critical and the underlying architecture is fragile, I might implement a short-term ''hotfix'' to stabilize the system while scheduling the architectural refactor as a planned task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81db025e-dc1d-47e3-ab7f-9fced60eebfe', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the impact of ''Struct'' inlining on binary size and execution performance?', N'Senior', N'Inlining struct methods improves performance by removing function call overhead and enabling further optimizations like constant propagation. However, aggressive inlining can lead to binary bloat if the same logic is duplicated across many call sites, creating a trade-off between speed and executable size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35421a5f-3260-4b52-b291-9fcf539f3ffe', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle rate limiting in a distributed API environment?', N'Middle', N'Rate limiting is typically enforced at the API gateway or load balancer level using a distributed cache like Redis to track request counts. This prevents any single user or service from overwhelming the backend, ensuring fair usage and system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8aae2ccc-8dea-44b7-9686-9fd45f9121b5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'When should ''defer'' be used instead of placing scripts at the end of the body?', N'Senior', N'While placing scripts at the end of the body was a historical optimization, ''defer'' is now preferred because it allows scripts to begin downloading as soon as they are discovered by the preload scanner. This initiates the download much earlier than waiting for the entire document to be parsed before finding the script tags at the bottom.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13588ceb-7c08-4772-8dd7-9fd4c3d0e898', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the advantages of Rust''s ''Result<T, E>'' type over traditional exception handling?', N'Senior', N'Result makes errors part of the function signature, forcing callers to explicitly handle or propagate failures, which improves reliability and code transparency. Unlike exceptions, which are hidden control flows, Result-based error handling provides better performance by avoiding stack unwinding and allows the compiler to verify that errors are not ignored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4b93ca5-7e03-4027-a761-9fd5f7394189', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the Gin ''HandlerFunc''?', N'Intern', N'A HandlerFunc is a function signature that Gin uses for request processing. It accepts a pointer to the Context object, which allows the function to access the request data and write the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7e3b65e-8ea5-41f8-baca-9fd82f7c0cdc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle method missing, and what are the drawbacks?', N'Middle', N'The ''method_missing'' hook allows an object to respond to calls that aren''t explicitly defined, which is powerful for building dynamic APIs. The drawback is that it can make code very difficult to navigate and debug because the method does not exist in the standard object hierarchy. Additionally, it can lead to performance overhead and unexpected behavior if not handled with proper care.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c2d9594-2f15-473b-941b-9fdb316a673e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What should you watch for when upgrading Hono versions?', N'Middle', N'Because Hono follows the Web Standards API, upgrades are generally straightforward. However, you should review the changelog for any changes to internal middleware APIs or context properties, as minor versions may occasionally refine the way request context is accessed to better match emerging browser standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
