INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd354afa-c11d-4d01-96db-9fe03d2f1560', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between implementing a multi-region active-active versus active-passive database architecture?', N'Senior', N'I weigh the Recovery Time Objective and Recovery Point Objective requirements against the complexity of conflict resolution. Active-active requires sophisticated replication and resolution logic for concurrent writes, whereas active-passive is simpler to manage but inherently risks data loss during the failover window.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aa12ef2-c1cb-4a69-9a23-9fe0d639e834', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the architectural advantage of Axum''s ''Extractors'' pattern?', N'Senior', N'Extractors decouple request parsing logic from business logic by leveraging Rust''s type system to automatically validate and transform incoming data. This approach promotes cleaner controllers that focus purely on domain logic while ensuring that malformed requests are rejected at the framework level before reaching the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77c262ce-ca81-4c0b-99b5-9fe17ae4a9ec', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the dependency injection hierarchy in Angular?', N'Intern', N'Angular''s dependency injection (DI) system works as a hierarchical tree of injectors, mirroring the component tree structure. When a component or service requests a dependency, Angular starts looking for a provider in that component''s own injector. If not found, it walks up the injector tree to the parent component''s injector, then its parent, and so on, until it reaches the root injector. The first provider found for the requested token is used to create or provide the dependency instance. This hierarchy determines the scope and lifetime of service instances: - Providers defined at the root level (e.g., using @Injectable({ providedIn: ''root'' }) or in the root AppModule) are typically singletons for the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a59a817-4155-4f55-a87c-9fe1bf9022a3', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why would you choose gRPC over REST for internal microservice communication?', N'Senior', N'gRPC uses Protocol Buffers for efficient binary serialization and leverages HTTP/2 for multiplexing, leading to significantly lower latency and smaller payload sizes than JSON-based REST. It also provides strongly typed interfaces and built-in support for streaming, which is ideal for high-throughput, low-latency internal service interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b45311b1-1f04-4238-9f5a-9fe4359b1009', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are Web Components?', N'Intern', N'Web Components are a set of web platform APIs that allow you to create custom, reusable, encapsulated HTML tags. They work across modern browsers and can be used with any framework or no framework at all.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65519be9-c2ed-4bed-8a66-9fe474399d47', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the ''final'' keyword?', N'Junior', N'The final keyword is used to restrict the user from changing the implementation. When applied to a variable, it makes it a constant; when applied to a method, it prevents overriding; and when applied to a class, it prevents inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c00d7294-11a7-428a-ae8e-9fe5dc6389a0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of ''IntoResponse'' in Axum?', N'Middle', N'IntoResponse is a trait that defines how a type can be converted into an HTTP response. Implementing this trait allows custom data structures or error types to be returned directly from route handlers, automatically handling status codes and response bodies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35460ea0-b88a-4355-97d0-9fe6c09765ce', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the performance implications of having too many indexes on a collection?', N'Middle', N'Every index adds overhead to write operations because each insert, update, or delete must also update all relevant indexes. Excess indexes consume significant RAM, which can lead to cache eviction and degraded overall database performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'403ccc5e-a94a-4758-a929-9fe8c4de7c81', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type inference for generic functions?', N'Middle', N'TypeScript performs type inference by looking at the arguments passed to a generic function to determine the types of the generic placeholders. If the compiler cannot infer the type accurately, it defaults to the constraint provided or the ''unknown'' type, requiring explicit type arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4506fc9-fdcf-4c2c-90a8-9fea0889dd4e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the utility of ''utility types'' like Pick, Omit, and Record in managing complex state.', N'Senior', N'Utility types provide a standard way to transform types, allowing for cleaner code and less duplication. They help maintain a single source of truth for base models while enabling the derivation of subsets or projections required for specific UI components or API responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b21ec89f-9bb1-4dfa-8a92-9fea95d67b39', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between horizontal and vertical scaling?', N'Intern', N'Vertical scaling involves upgrading the capacity of a single server, which is simple but has a hard limit and a single point of failure. Horizontal scaling involves adding more servers, which is more reliable and scalable but introduces significant complexity in load balancing and data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49b3dab7-2e61-4b82-a50c-9feaee09bfd6', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the purpose of Data Binding in Echo?', N'Fresher', N'Data binding allows Echo to automatically map incoming request data, such as JSON bodies or form parameters, directly into Go structures. This simplifies the process of extracting and validating user input without manual parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'995759e9-b094-4923-ac12-9fece308d9eb', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Depends'' object in FastAPI''s dependency injection system?', N'Senior', N'The ''Depends'' object acts as a marker that tells FastAPI to resolve a specific dependency before executing the path operation function. It handles the lifecycle of the dependency, including calling it, managing its scope, and cleaning up resources like database connections once the request is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8871c45d-11a0-4f77-b8d8-9fed4e2d9e42', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the Scala compiler handle ''Tailrec'' annotation and what happens if it fails?', N'Senior', N'The @tailrec annotation forces the compiler to verify that a method is truly tail-recursive and can be optimized into a loop. If the compiler cannot perform this optimization, it will generate a compilation error rather than failing silently. This provides a strict safety net for developers, ensuring that recursive algorithms do not risk stack overflows at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc7c460f-a5b5-4562-b20c-9feda75b5d8d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the significance of the ''Witness Table'' in Swift''s protocol implementation?', N'Senior', N'A witness table is a runtime structure that maps protocol requirements to the actual implementation provided by a specific type. It enables polymorphism by allowing the runtime to look up the correct function implementation when a protocol is used as a type, even if the underlying concrete type is unknown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbe036fe-85a9-40be-9a33-9fee99a145bd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where you are stuck on a problem for a long time?', N'Intern', N'I would first take a break to clear my mind and return with a fresh perspective. If I am still stuck, I would document what I have tried so far and then reach out to a colleague or mentor for guidance. Explaining the problem to someone else often helps clarify my own thinking and leads to a breakthrough.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cfcd85e-d2f2-42b3-9ed1-9feedafcb7ec', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a constructor and what are its types in C++?', N'Intern', N'A constructor in C++ is a special member function responsible for initializing instances of a class. Constructors are called automatically when an object is created. Types of Constructors 1. Default Constructor If a class doesn''t have any constructors specified, the compiler automatically generates a default constructor. Its role is to initialize the object to a default state. 2. Parameterized Constructor Designed to accept arguments for custom object initialization. 3. Copy Constructor Used for creating an object as a copy of an existing object. The parameter is typically a const reference to the same class. 4. Move Constructor Optimized for moving data from temporary objects or rvalue references. Introduced in C++11. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cd42a85-dfae-4501-bda6-9fef3b1c7340', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does a message queue support horizontal scaling of consumers?', N'Middle', N'By allowing multiple consumer instances to join a consumer group, the broker can load-balance incoming messages across all available instances. This enables the system to scale its processing capacity dynamically based on the current load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d1eb988-3fa6-4ea0-9a6e-9fef7e94422f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure your work is testable before you even start implementation?', N'Junior', N'I would focus on writing modular components with single responsibilities, which makes it easier to test individual parts in isolation. I would also consider the edge cases during the design phase to ensure the logic can be verified under different input conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fd7aee2-d6ab-4215-b288-9fef9cf23ea2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does multi-version concurrency control (MVCC) improve performance?', N'Middle', N'MVCC improves performance by maintaining multiple versions of data, allowing readers to access older versions without being blocked by concurrent writers. This significantly increases concurrency because read operations do not require locks, effectively separating the reader path from the writer path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7f8868d-784a-4931-ad32-9ff349edc80f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the function of the ''Ember CLI'' and why is it considered a core part of the framework''s stability?', N'Senior', N'Ember CLI provides a standardized project structure, build pipeline, and testing environment across all Ember projects. This uniformity ensures that developers can easily switch between projects and that the community can maintain shared plugins, reducing the ''configuration fatigue'' often found in other frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2afe47c9-430c-45cd-b9ba-9ff45e8bb3bc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a refresh in Elasticsearch?', N'Fresher', N'A refresh is the process that makes the changes made to an index available for search. By default, Elasticsearch performs this operation periodically to ensure that new data becomes searchable shortly after indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'064e0b55-c20a-4cc4-a715-9ff81ba8243d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the significance of the x-cloak directive in a high-performance production environment.', N'Senior', N'x-cloak prevents the raw HTML from flashing on the screen before Alpine.js finishes parsing the DOM. In a production environment, this is critical for perceived performance and user experience, ensuring a seamless transition from the initial server-rendered state to the interactive state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de2c847f-18c8-4084-96b1-9ff9a50859e0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a field in a document?', N'Fresher', N'A field is a key-value pair within a JSON document. It represents a specific attribute of the data, such as a username, email, or timestamp.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6abad59c-edb3-42fc-a450-9ffb2c4a3221', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the primary purpose of RTTI (Run-Time Type Information) in C++?', N'Middle', N'RTTI allows a program to query the type of an object at runtime, primarily through the use of dynamic_cast and typeid. While useful for downcasting in inheritance hierarchies, it introduces runtime overhead and should be used sparingly in performance-critical applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27b58d66-c5ea-4309-b934-9fff508ecea0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''as const'' assertion?', N'Junior', N'The ''as const'' assertion tells the compiler to treat an expression as a literal type rather than a general type. This makes the object properties read-only and prevents the compiler from widening the types, keeping them as specific as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91aaff65-ff32-4105-a3f4-9fff66eb25b3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a user reports that a web application is loading slowly, how would you begin to troubleshoot the issue?', N'Fresher', N'I would start by checking the network tab in the browser developer tools to identify which assets, like images or scripts, are taking the longest to load. I would also check if the issue persists across different browsers or network connections to determine if it is a client-side performance problem or a server-side latency issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d80318e-aab8-45ad-80e5-9fffabb7ec0c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the internal purpose of the ''singleton class'' (or eigenclass) in Ruby''s object model?', N'Senior', N'The singleton class is an anonymous, hidden class that acts as the receiver for methods specific to a single instance. It sits at the beginning of the method lookup path for that object, allowing Ruby to implement per-instance behavior without modifying the base class or affecting other instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3609a5c1-7f67-4776-aabf-a00163c9c312', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the concept of ''Cache Pollution'' and how it can be minimized.', N'Middle', N'Cache pollution occurs when the cache is filled with data that is rarely accessed, displacing frequently used data. It can be minimized by using smart eviction policies like LRU or LFU, or by setting shorter TTLs on data that is known to be transient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0640bc9-2fc9-47ff-96de-a00278d887b6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of the ''application'' template?', N'Fresher', N'The application template is the top-level template that is always rendered in every Ember application. It typically contains the global layout, such as the navigation header or footer, which remains constant as the user navigates through the app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad00ef2-c744-4bb8-8475-a00311cff616', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the role of ''Decorators'' in the Symfony Service Container.', N'Middle', N'Decorators allow you to wrap an existing service with a new implementation to add functionality without modifying the original class. This is useful for implementing cross-cutting concerns like logging or caching while maintaining the original service''s contract.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'414dc47d-31e5-4215-9543-a0033817ef60', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is Express.js in the context of backend development?', N'Fresher', N'Express.js is a minimal and flexible web application framework for Node.js. It provides a robust set of features for web and mobile applications, acting as a layer on top of the Node.js HTTP module to simplify server creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04d5d98d-c76f-409c-aa3b-a003593ec7c3', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular simplify Internationalization?', N'Fresher', N'Angular simplifies the below areas of internationalization, 1. Displaying dates, number, percentages, and currencies in a local format. 2. Preparing text in component templates for translation. 3. Handling plural forms of words. 4. Handling alternative text.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1260c719-d918-48b6-b8be-a006959bc95c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the primary difference between React''s reconciliation process and the browser''s native DOM updates?', N'Senior', N'React uses a virtual DOM to calculate the minimal necessary changes between render cycles, batching these updates to minimize direct DOM manipulation. Direct DOM manipulation is expensive due to layout reflows and repaints, whereas React''s diffing algorithm optimizes the actual number of nodes changed in the document tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0506a8a8-ac56-4ee8-9f9f-a0096b1a7d4b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a static member variable in a class?', N'Intern', N'A static member variable is shared by all instances of a class rather than having a unique copy for each object. It exists for the entire duration of the program''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a66b3bb4-14b0-4494-9ee2-a009a578266e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a synchronous and asynchronous request in Flask?', N'Intern', N'A synchronous request blocks the server until the processing is complete and a response is returned. Flask is traditionally synchronous, meaning it handles one request at a time per worker process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a89d3145-f766-40a0-9cb5-a009db973d1c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is an atomic counter in DynamoDB?', N'Fresher', N'An atomic counter is a numeric attribute that is incremented or decremented without interfering with other write requests. It is useful for counting events or keeping track of simple numeric totals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a395efd-fc0d-4f5c-b04d-a00e1b2a42d5', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the primary purpose of the Ember Service in an application?', N'Junior', N'Services in Ember are singleton objects designed to manage long-lived state or shared functionality that needs to persist across different parts of the application. They are useful for tasks like authentication, managing user settings, or sharing data between components that do not have a parent-child relationship.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e943d4a8-78da-4f02-904b-a00e2e4deb49', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the role of the database transaction atomicity in Django and why global autocommit settings might be insufficient.', N'Senior', N'Django’s transaction management ensures that groups of operations succeed or fail together, maintaining data consistency. Relying solely on autocommit can lead to race conditions or partial data updates; explicit transaction blocks are necessary for operations that span multiple dependent records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9709717a-28a5-40df-9e19-a00e7b149abc', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Describe the benefits of using a CDN (Content Delivery Network) for an API.', N'Middle', N'A CDN caches static or semi-static API responses at edge locations geographically closer to the user. This reduces latency, lowers the load on the origin server, and provides a buffer against traffic spikes, significantly improving global performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6216c6e-ac1b-4bb9-80fd-a0115d34fc29', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is a ''hot shard'' in a distributed database and how do you resolve it?', N'Middle', N'A hot shard occurs when one partition receives significantly more traffic than others, creating a performance bottleneck. It is typically resolved by choosing a better partition key to distribute data more uniformly or by rebalancing the data across more shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ca23707-47a6-4f2d-a53a-a0120bacf6fa', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Does Echo support automatic TLS configuration, and how is it managed?', N'Middle', N'Yes, Echo provides built-in support for Auto-TLS, which can automatically fetch and renew SSL certificates via Let''s Encrypt. This simplifies the process of securing the application without manually managing certificates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37bf04af-eebf-4ad9-bd03-a012fdf9680d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why does Dart utilize a single-threaded execution model for its main isolate?', N'Senior', N'A single-threaded model simplifies the developer experience by removing the complexities of thread synchronization and data contention. Because UI updates and event handling occur on one thread, it ensures consistent state updates and prevents the visual glitches associated with multi-threaded UI access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0f75c2a-abaf-4b4d-a728-a015ddfb6816', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the impact of middleware nesting on request latency in a Gin application?', N'Senior', N'Each layer of middleware adds overhead to the request lifecycle by executing additional logic and function calls. While minimal, excessive nesting or inefficient logic in a middleware chain can accumulate latency, so middleware should be kept lean and optimized for speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd31d1c07-436d-4b4a-9dc6-a01666108451', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you evaluate the trade-offs between choosing a microservices architecture versus a modular monolith?', N'Senior', N'Microservices offer independent scalability and deployment flexibility but introduce significant operational complexity and distributed system challenges like eventual consistency. A modular monolith provides simpler development and testing cycles while maintaining strong boundaries, making it a better choice until organizational scale necessitates independent service lifecycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d745035-284e-4443-9fa5-a0166c0738e3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the impact of long-running database queries on the Phoenix connection pool?', N'Senior', N'Long-running queries can saturate the connection pool, leading to request queuing and increased latency for all other users. Developers should monitor pool usage and implement query timeouts or move heavy processing to asynchronous workers to preserve system responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72bb535d-5cce-43f7-ac93-a01c50fa8d5b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the ''prerender'' configuration option?', N'Intern', N'The prerender option tells SvelteKit to generate a static HTML version of a specific page at build time. This is useful for content that does not change frequently and can be served efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff89bf84-fb6c-4aad-8f13-a01c7977ea1b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is mobile-first? Can you explain the difference between coding a website to be responsive versus using a mobile-first strategy?', N'Fresher', N'Making a website responsive means the some elements will respond by adapting its size or other functionality according to the device''s screen size, typically the viewport width, through CSS media queries, for example, making the font size smaller on smaller devices. A mobile-first strategy is also responsive, however it agrees we should default and define all the styles for mobile devices, and only add specific responsive rules to other devices later. Following the previous example: A mobile-first strategy has 2 main advantages: * It''s more performant on mobile devices, since all the rules applied for them don''t have to be validated against any media queries. * It forces to write cleaner code in respect to responsive CSS rules. Example: Live Demo: Media Query', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd21f0660-9c2b-484e-ae54-a01c81cb77f4', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'When would you prefer Preact over React for a micro-frontend architecture?', N'Senior', N'Preact is ideal for micro-frontends because it minimizes the total bundle size downloaded by the client when multiple frameworks or heavy dependencies are involved. Its low overhead ensures that even if several isolated components are loaded, the impact on the overall page load time remains negligible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a33dedc-424c-4d2d-a39c-a01d1ac7880b', N'4c000000-0000-0000-0000-000000000005', N'What is the significance of the Write-Ahead Log (WAL) in databases?', N'Middle', N'WAL ensures data integrity by recording all changes to a log before they are applied to the actual database files. In the event of a crash, the database can replay the log to restore its state, preventing data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19ca5336-f850-4b04-bec2-a01e6e347da9', N'4c000000-0000-0000-0000-000000000005', N'How do you manage database migrations in a zero-downtime deployment environment?', N'Senior', N'Use an expand-contract pattern where you first add new columns or tables, deploy code that supports both formats, and finally remove the old schema once the new version is verified. This ensures backward and forward compatibility, allowing the application to function correctly during the transition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58608435-46fc-474c-b759-a0248911e3ef', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s code splitting improve application performance?', N'Middle', N'Code splitting breaks a large bundle into smaller, manageable chunks that can be loaded on demand or in parallel. This improves performance by reducing the initial load time, as the browser only downloads the code necessary for the current view instead of the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
