INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd52e6b5d-520e-48e6-87ea-a025ed96ebce', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How can you analyze the execution plan of a query in MySQL?', N'Middle', N'You can use the EXPLAIN statement to view how the optimizer intends to execute a query. It provides information on index usage, join types, and the number of rows scanned, which is essential for identifying bottlenecks and improving query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa2305de-8c52-4278-89df-a0293a078621', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle routing in the App Router?', N'Junior', N'Next.js uses a file-system based router where the folder structure inside the app directory defines the URL paths. Each folder represents a route segment, and special files like page.js define the UI for that specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'390c39a5-5002-421c-9f9c-a02ae8bc528b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite support Server-Side Rendering (SSR) out of the box?', N'Middle', N'Vite provides the foundational mechanisms for SSR by allowing you to run a server that imports your modules directly. While Vite handles the transformation, it does not provide an opinionated framework for SSR, leaving the implementation details to the developer or higher-level frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e68aaa8-042e-4d30-a35b-a02bfdb70dde', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'When would you prefer a B-Tree index over a Hash index?', N'Middle', N'B-Tree indexes are preferred for range queries and sorting because they maintain data in a sorted order. Hash indexes are optimized for equality comparisons and generally provide faster point lookups but cannot be used for range-based operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cd02c73-a44c-4e98-baa1-a02d2a3864ea', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit manage accessibility in custom elements?', N'Middle', N'Lit follows standard Web Components patterns for accessibility, such as using ARIA attributes and managing focus. Because Lit components are native DOM elements, they integrate seamlessly with standard browser accessibility APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'959d441a-5730-4981-97ec-a02d4f1bb21e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the testing implications of using Tailwind CSS compared to CSS modules?', N'Middle', N'Testing utility-heavy components is generally easier because the visual styles are tied directly to the classes in the markup, making it clear which styles affect a component. However, it can make snapshot testing noisier, as minor changes to utility classes can cause large differences in snapshot files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'095ca6f5-e922-4585-a36f-a02d7e721f52', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the trade-offs of using AdonisJS compared to a minimalist framework?', N'Middle', N'AdonisJS is a full-stack, opinionated framework that provides batteries-included functionality, which significantly speeds up development and enforces best practices. A minimalist framework offers more flexibility but requires more effort to setup, integrate, and maintain common features like authentication and validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e175d6-c69c-4c89-b11c-a02eb774542e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono leverage the Request/Response object mutability to handle cross-cutting concerns effectively?', N'Senior', N'Hono utilizes a context object that persists throughout the request lifecycle, allowing middleware to inject metadata or state without polluting the global scope. This pattern enables type-safe propagation of authenticated user data or request-scoped logging IDs, ensuring that downstream handlers have access to necessary information without redundant lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'502daa15-bc35-4d48-a349-a030aefd966b', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Discuss the strategy for managing database migrations in a CI/CD environment with zero downtime.', N'Senior', N'Zero-downtime migrations require an additive approach where changes are applied in multiple steps, such as adding a nullable column first, updating the application code, and then enforcing non-nullability. This ensures that the database schema is always compatible with both the old and new versions of the application code running concurrently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d98b135-ee3a-484f-aaf7-a032fe304d2e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s method chaining mechanism work internally, and what are its drawbacks regarding error handling?', N'Senior', N'jQuery methods return the object instance, allowing consecutive calls on the same selection set. A major drawback is that silent failures or errors in the middle of a chain are difficult to debug, as the chain obscures which specific operation failed to return the expected result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ade04ceb-18c8-476e-bf3a-a038ead138b6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the use of the ''useLoaderData'' hook?', N'Fresher', N'The useLoaderData hook is used in a component to access the data returned by the server-side loader function. It makes the data available for rendering in your component UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'debad16a-8f9b-496a-a5c4-a03a7d6a3f23', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why would you choose Chi over a full-featured framework like Gin?', N'Middle', N'Chi is a minimalist router that avoids the ''batteries-included'' overhead of larger frameworks. It is preferred when you want to keep your dependency tree small and maintain maximum control over your application''s architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4ada84b-d7c4-4e1f-8836-a03f041a10b2', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What does ''atomic'' behavior provide in a database migration?', N'Middle', N'Atomic migrations ensure that all operations within a migration file are treated as a single transaction. If any part of the migration fails, the entire database state is rolled back, preventing the schema from being left in a partially updated or inconsistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd1124bc-123a-4178-a456-a041f46eb8f6', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''Boxed'' middleware in Axum, and when should it be avoided?', N'Senior', N'The ''Boxed'' middleware is used to erase the concrete type of a service stack, which helps reduce compile times and binary size by simplifying complex nested generic types. However, it introduces a small performance cost due to dynamic dispatch, so it should be used strategically in parts of the application with high type complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ca225f-194e-423d-a671-a04606a129af', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the InnoDB Undo Log facilitate transaction rollback?', N'Senior', N'The undo log stores the inverse of every modification, allowing the engine to reverse changes to the data if a transaction is rolled back. It is also the foundation of MVCC, enabling other transactions to access the state of a row prior to an active modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'332c1b0d-df3a-48a3-ac6d-a046dcab8aad', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is meant by ''hydration'' in SolidJS?', N'Fresher', N'Hydration is the process where the client-side SolidJS application attaches event listeners and reactive logic to the static HTML generated by the server. This allows the page to become interactive without re-rendering the entire content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'459a0984-94c3-43a9-a154-a0474b514785', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of an API (Application Programming Interface)?', N'Intern', N'An API is a set of rules that allows different software applications to communicate with each other. It abstracts the underlying complexity, providing a standard way to request and exchange data. This enables developers to integrate third-party services or build modular systems without needing to know how the other application is built.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1f69dc4-0ae6-4c5a-9cf6-a047a627882b', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of backpressure in a distributed system?', N'Middle', N'Backpressure is a strategy where a consumer informs the producer to slow down the rate of data ingestion when it is overwhelmed. This prevents buffer overflows and system crashes by ensuring that the rate of work does not exceed the capacity of the components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ce307e1-424e-44d2-acc3-a04af0938822', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Compare ''Optimistic'' and ''Pessimistic'' concurrency control.', N'Senior', N'Pessimistic concurrency control locks data resources for the duration of a transaction to prevent conflicts, which is safer but reduces throughput. Optimistic concurrency control assumes conflicts are rare, allowing transactions to proceed without locks and validating for conflicts only at the time of commit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'847f777c-b09f-435f-a5a4-a04fbc26bf58', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the similarities between VueJS and ReactJS?', N'Intern', N'Even though ReactJS and VueJS are two different frameworks there are few similarities(apart from the common goal of utilized in interface design) between them. 1. Both frameworks are based on the Virtual DOM model 2. They provide features such Component-based structure and reactivity 3. They are intended for working with the root library, while all the additional tasks are transferred to other libraries(routing, state management etc).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82d1a9ef-427f-4af2-88ca-a0577c33137d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is borrowing in Rust?', N'Junior', N'Borrowing allows functions to access data without taking ownership of it. By using references, code can read or modify values temporarily, ensuring that the original owner remains in control of the data''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fff15b8-0776-4976-856f-a05859c3c3f7', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails handle request concurrency, and what are the limitations of the Global Interpreter Lock (GIL) in Ruby?', N'Senior', N'Rails relies on multi-threaded web servers to handle concurrent requests, but the MRI Ruby GIL prevents true parallel execution of Ruby code within a single process. Consequently, while threads improve throughput for I/O-bound tasks, CPU-bound tasks do not benefit from thread-level parallelism and require multi-process architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e125dc5-cebf-4f5d-8212-a059d33fc2d5', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the ''render'' function in Preact?', N'Fresher', N'The render function is the entry point that mounts your Preact component tree into a specific DOM element. It takes the component to be rendered and the target container as arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
