INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a088624e-603e-4e92-acae-a05d36b8bd97', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about scaling a database when it reaches its IOPS limits?', N'Senior', N'I first look at vertical scaling options like query optimization and adding read replicas to offload read-heavy traffic. If that is insufficient, I would plan for horizontal sharding by partitioning the data based on a high-cardinality key, carefully considering the complexity of cross-shard transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd7810d2-ca06-4722-b2fb-a05daa12114a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What does the ''lifespan'' event handler in FastAPI provide, and why is it useful?', N'Middle', N'The lifespan event handler allows you to execute code before the application starts and after it shuts down, such as initializing database pools or closing network connections. This ensures that expensive resources are properly managed throughout the lifetime of the application process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f755fd-dc35-4d99-8712-a0603564ec54', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How would you handle multipart form data efficiently in a Chi application?', N'Senior', N'Since Chi is standard-library compliant, you use the standard net/http Request methods to parse multipart data. For large files, you must ensure your middleware doesn''t buffer the entire body into memory, using streaming techniques instead to maintain a low memory profile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25779b96-02de-4af5-b388-a0664b896303', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the architectural implications of choosing On-Demand vs. Provisioned throughput modes?', N'Senior', N'Provisioned mode is cost-effective for predictable workloads where you can accurately forecast traffic and reserve capacity. On-Demand mode is better for unpredictable, bursty workloads, though it is generally more expensive per request and lacks the granular control of reserved capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05d9fe42-67f7-4c67-bb84-a0665a7c89c5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Migrations file in Ecto?', N'Junior', N'Migrations are version-controlled scripts used to modify the database schema over time. They allow developers to create tables, add columns, or change data types in a repeatable and reversible way across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47afa251-19ad-4764-b677-a0684d89d80d', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s Global Interpreter Lock (GIL) influence concurrency patterns in multi-threaded applications?', N'Senior', N'The GIL ensures that only one thread executes Ruby bytecode at a time, effectively preventing true parallel CPU-bound execution within a single process. While it simplifies memory management and thread safety for internal data structures, it mandates a multi-process architecture, such as Puma or Sidekiq, to achieve horizontal scalability across multiple processor cores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bd2efd9-8e2c-4f38-9130-a06a4924f6dc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why would you choose to use a database view over a standard Rails model?', N'Middle', N'A database view is useful for abstracting complex joins or aggregations that are frequently used across the application. By moving this logic to the database layer, you can query the data as if it were a standard table, improving performance for read-heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed6c075b-4cb4-44f6-9fad-a06ac07ab319', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the difference between a queue-based and a log-based message broker?', N'Senior', N'A queue-based broker like RabbitMQ removes messages once consumed, focusing on task distribution. A log-based broker like Kafka keeps messages in an immutable, ordered log, allowing multiple consumers to replay or process the stream independently at their own pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69c0f1bd-50ac-4dcf-b855-a06b69187b15', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle content-type parsing internally?', N'Middle', N'Fastify uses a content-type parser registration system that allows you to define how specific MIME types should be processed. This is more efficient than parsing everything as JSON, as it allows for specialized handling of binary, XML, or multipart data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11db2bff-99d0-45a9-92cf-a06ca982c331', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If two team members disagree on an implementation approach, what is the best way to resolve the conflict?', N'Junior', N'I would suggest evaluating each approach based on technical requirements, long-term maintainability, and complexity. If a consensus cannot be reached, we should present the trade-offs to a senior developer or lead to make an informed decision based on project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
