INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e497b13-9bcd-46fd-bb40-a06e1988a1b5', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''g'' object in Flask and when should it be used?', N'Junior', N'The ''g'' object is a global namespace for storing data that is relevant only during a single request-response cycle. It is used to share information across different functions or modules during the processing of one specific request, such as storing a database connection or user information retrieved from a token.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09fe9484-fb6c-4b84-891a-a07399fe9453', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why might you choose to bypass Active Record and use raw SQL in specific parts of a Rails application?', N'Senior', N'Raw SQL is necessary when performing complex operations like window functions, recursive CTEs, or massive bulk inserts that are not supported by the Active Record DSL. It provides maximum performance and database-specific optimization, though it sacrifices database abstraction and increases maintenance burden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'877dc618-ae45-4d01-bfa8-a07584b5a529', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure data consistency in a distributed system where services might fail during a transaction?', N'Middle', N'I would implement the Saga pattern or use two-phase commits depending on the consistency requirements. Sagas are generally preferred in distributed environments as they use a series of local transactions with compensating actions to roll back changes if a step in the process fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
