INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b34f5964-9eee-416c-8375-a088d2437e52', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the mechanism behind Alpine''s x-transition and its impact on browser layout.', N'Senior', N'x-transition works by manipulating CSS classes during the DOM''s insertion and removal phases. It orchestrates class additions at specific animation frames to ensure smooth transitions, though it relies on the browser''s ability to handle layout transitions efficiently without causing massive layout shifts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec0e2c6-15d2-48e6-9ba8-a0890045c053', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'A distributed service is experiencing intermittent 500 errors that only occur under high load. How would you systematically isolate the root cause?', N'Middle', N'I would start by analyzing distributed traces to identify if the failure occurs at a specific service boundary or database dependency. If the traces are inconclusive, I would examine infrastructure metrics like thread pool exhaustion, connection pool saturation, or CPU throttling during load spikes. By correlating the exact timing of errors with resource utilization logs, I could determine if the issue is a race condition, a timeout, or resource starvation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3afa905-ed59-42d1-8704-a08d315c6bd7', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify ensure thread-safety given Node.js is single-threaded?', N'Senior', N'While Node.js is single-threaded, Fastify ensures state safety by scoping decorators to specific plugin instances. This design prevents different parts of the application from accidentally overwriting shared configurations, essentially providing a ''thread-safe'' pattern within the single-threaded event loop architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6496eab-9959-420b-a476-a08d5017acee', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the memory footprint of fibers compare to OS threads, and why does this matter for scalability?', N'Middle', N'Fibers typically start with very small, growable stacks, whereas OS threads often require a fixed, relatively large memory allocation for their stack. This lower per-unit memory footprint allows a single backend service to support a significantly higher number of concurrent connections or tasks before hitting memory constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a8dffeb-d4d7-4229-9db2-a08d68d01583', N'954a0331-deff-4399-b588-96f39fec001d', N'What are active router links?', N'Intern', N'RouterLinkActive is a directive that toggles css classes for active RouterLink bindings based on the current RouterState. i.e, The Router will add CSS classes when this link is active and remove when the link is inactive. For example, you can add them to RouterLinks as below.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49c1e674-eb9c-4d5e-be49-a08e572007c3', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''select'' statement?', N'Junior', N'The select statement lets a goroutine wait on multiple communication operations. It blocks until one of its cases can run, then executes that case, which is useful for managing multiple channels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df4b7073-8c19-4b0c-9537-a08e64d9497f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the benefit of SolidJS components running only once?', N'Fresher', N'Because components run only once, there is no risk of stale closures or accidental performance degradation from unnecessary re-renders. It makes the execution flow predictable and significantly reduces the overhead of the UI update cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'706edccf-981a-4355-abc0-a08f056aaecf', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the significance of the ''alt'' attribute on an image tag?', N'Middle', N'The alt attribute provides a text alternative for images if they fail to load or for users who rely on screen readers. It improves accessibility by describing the content or function of the image, and it helps search engines index the image content. It should be descriptive but concise, or empty if the image is purely decorative.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a252c51a-e4cd-41d1-82b7-a094121d4e5c', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you create displayBlock components?', N'Fresher', N'By default, Angular CLI creates components in an inline displayed mode(i.e, display:inline). But it is possible to create components with display: block style using displayBlock option, (OR) the option can be turned on by default in Angular.json with schematics.@schematics/angular:component.displayBlock key value as true.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22d7a122-0802-43af-ab43-a0963061f4bb', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is Node.js?', N'Intern', N'Node.js is an open-source server side runtime environment built on Chrome''s V8 JavaScript engine. It provides an event driven, non-blocking (asynchronous) I/O and cross-platform runtime environment for building highly scalable server-side applications using JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b8e1a37-f89c-453c-9722-a097aa8ba395', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is an ''Edge'' environment in the context of Hono?', N'Intern', N'An edge environment refers to a distributed network of servers located geographically closer to the end user. Hono is optimized for these environments to reduce latency and improve execution speed compared to traditional centralized servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5190339b-f68c-4745-ba87-a098d7d72cdb', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Can Actix-web be used to implement WebSockets, and how does it handle the state?', N'Senior', N'Yes, Actix-web provides first-class support for WebSockets through an actor-based implementation. Each WebSocket connection is typically mapped to an actor, which maintains the session state and handles incoming and outgoing message frames asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'029e32ae-4bb4-4423-89d6-a09b5b8ddc34', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the purpose of a ''Bloom Filter'' in a caching architecture?', N'Senior', N'A Bloom filter is a probabilistic data structure used to quickly determine if an item is definitely not in the cache, preventing unnecessary, expensive queries to the backend. It effectively handles the problem of ''negative caching'' for keys that do not exist in the underlying data store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4545a8a2-b79a-49cd-ad47-a0aa6ce62bee', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system, how do you determine if a task should be handled synchronously or asynchronously?', N'Middle', N'Synchronous processing is appropriate when the user requires an immediate confirmation or result of an action. Asynchronous processing should be used for long-running tasks, heavy computation, or external service integrations to improve responsiveness and decouple components, thereby preventing system bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb704fe5-25f5-43c0-a4de-a0abc580de68', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the package.json file?', N'Intern', N'The package.json file acts as the manifest for a Node.js project. It contains metadata such as the project name, version, and entry point, as well as a list of dependencies and scripts required to run or build the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'630c67e5-9f59-44b9-87b0-a0abe69693e1', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a compiler and a linker?', N'Intern', N'A compiler translates high-level source code into machine-readable object files. The linker then takes these object files and combines them into a single executable program by resolving references between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eda3f874-b550-4716-a7ee-a0acd6f1f9b5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can DynamoDB store complex data types?', N'Fresher', N'Yes, DynamoDB supports scalar types like strings and numbers, as well as complex types like lists, maps, and sets. These allow you to nest data structures directly within an attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbb34eb1-3169-4903-99d1-a0b33e2a6ca9', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Tombstone in Cassandra?', N'Intern', N'A tombstone is a marker used to represent a deleted piece of data in an SSTable. Because SSTables are immutable, Cassandra cannot delete data immediately; instead, it writes a tombstone that tells the system the data should be ignored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc2dd102-5e4b-4040-8162-a0b348aca149', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is an API token in AdonisJS?', N'Intern', N'An API token is a unique string used to authenticate requests to an API. It allows the server to identify which user is making the request without requiring them to log in every time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'876148ce-6d59-4e41-b425-a0b47d795178', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the architectural benefit of Fiber''s ''App'' instance being separate from the global state.', N'Senior', N'By not relying on global state, Fiber allows for easier unit and integration testing. Developers can spin up multiple instances of the application on different ports within a single test suite to verify behavior without side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6eabedb-47ee-4ba7-a121-a0b5dfa1dfe1', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the concept of ''type juggling'' and its impact on the Zend Engine''s performance.', N'Senior', N'Type juggling allows PHP to automatically convert variables between types based on context, which simplifies development but adds hidden branching and conversion logic to the Zend Engine. While flexible, this requires the engine to perform runtime checks and potential reallocations, which is slower than languages with explicit static typing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11c42769-0f16-440c-bcfc-a0bc4a3d94d0', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do constants behave differently from variables in Ruby?', N'Middle', N'Constants are defined by starting with an uppercase letter and are intended to remain static throughout the application. While Ruby does not strictly enforce their immutability, it will trigger a warning if a constant is reassigned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61d5a46f-36e0-4947-aca2-a0bdfb156ddc', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the role of a consistent hashing algorithm in a distributed database system.', N'Middle', N'Consistent hashing minimizes the amount of data that needs to be remapped when nodes are added or removed from a cluster. By mapping both data and nodes to a circular keyspace, it ensures that only a small portion of keys need to be moved during cluster resizing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8833b3b-d1f7-44f3-85df-a0c0db081183', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the role of a circuit breaker pattern in system reliability?', N'Middle', N'A circuit breaker prevents a system from repeatedly trying to execute an operation that is likely to fail. By failing fast and stopping requests to a struggling downstream service, it prevents cascading failures and gives the underlying service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dea339b-84f3-4d45-800a-a0c356efd5e6', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between ''is'' and ''=='' in Python.', N'Junior', N'The ''=='' operator checks for equality of values, determining if the content of two objects is the same. The ''is'' operator checks for identity, determining if both variables point to the exact same memory address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'886537cb-ebee-44bd-8714-a0c5d7cb5cc2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the difference between Chi and a full framework like Gin?', N'Fresher', N'Chi is a minimal router that relies on the standard library, whereas frameworks like Gin often include built-in features like JSON binding, validation, and rendering engines. Chi offers more control, while Gin offers more out-of-the-box convenience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df7e7c65-d110-4b5d-a1db-a0c602925869', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Eloquent Eager Loading?', N'Junior', N'Eager loading is a technique to solve the N+1 query problem by loading related models at the same time as the main model. By using the ''with'' method, Laravel fetches all necessary related data in a single additional query, significantly improving database performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff403a6d-c36e-4207-a60a-a0c62b564256', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the concept of ''utility-first'' architecture in the context of design system consistency.', N'Senior', N'A utility-first architecture enforces design constraints by restricting developers to a pre-defined configuration of spacing, colors, and typography. This ensures that even without strict component libraries, the application maintains visual coherence because all developers are pulling from the same restricted set of design tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5d18381-ff78-42cb-9fc5-a0c688903664', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of an ''Arbiter'' in the Actix framework?', N'Intern', N'An Arbiter in Actix acts as an event loop that runs the actors assigned to it. It manages the execution context and allows for asynchronous task scheduling, ensuring that blocking operations do not stall the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53cddec8-d10d-4cfa-8b1a-a0c82d3639aa', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of the ASGI specification in FastAPI''s architecture?', N'Senior', N'ASGI is the successor to WSGI, designed to support asynchronous, long-lived connections like WebSockets and HTTP/2. By implementing ASGI, FastAPI can handle multiple asynchronous tasks concurrently within a single process, making it suitable for modern, high-concurrency web applications that WSGI-based frameworks cannot efficiently support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
