INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2977c2a-79d8-4bb9-b994-a0cebb2a7246', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the role of the Redis Cluster and how does it manage data?', N'Middle', N'Redis Cluster provides horizontal scalability by automatically partitioning data across multiple nodes using a concept called hash slots. It maps keys to one of 16,384 available hash slots, allowing the system to distribute the workload and expand capacity by moving slots between nodes without significant downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
