INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'847ec1ff-5b9d-469f-8e51-a10ab23bf141', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you create a dictionary in Python?', N'Fresher', N'In Python, a dictionary is an ordered collection of key:value pairs that provides $O(1)$ average time complexity for lookups, insertions, and deletions. They are highly optimized hash tables and serve as one of the most fundamental data structures in the language. Key Concepts - Keys: Must be unique and hashable (immutable types like str, int, or a tuple containing only hashable elements). - Values: Can be of any data type, including lists or other dictionaries, and can be duplicated. - Ordered: Since Python 3.7+, dictionaries are guaranteed to maintain the insertion order of items. - Mutable: You can add, remove, or modify items after the dictionary is created. Creation Methods There are several idiomatic ways to create a dictionary in Python: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26294ea3-6a8e-4415-af76-a10c683e1695', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s architecture handle cross-browser inconsistencies, and why is this approach less relevant in the modern web era?', N'Senior', N'jQuery utilizes a massive internal abstraction layer that normalizes inconsistent browser APIs into a unified interface. This was critical when browser engines were highly fragmented, but modern standards and evergreen browsers have largely resolved these disparities, making native APIs more performant and reliable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64075550-c8ee-4812-9534-a10de802ce31', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary function of a ''Quorum'' in NoSQL systems?', N'Senior', N'A quorum ensures consistency by requiring a minimum number of nodes to acknowledge a read or write operation (R + W > N). By adjusting R and W values, developers can tune the system for either stronger consistency or higher performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'136f318d-ca67-4729-9f71-a10f091e97a9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the key features of Python?', N'Intern', N'Python is a high-level, multi-paradigm programming language known for its simplicity, readable syntax, and a massive ecosystem. It is widely used in AI, web development, and automation. Key Features of Python 1. Interpreted and Interactive Python is an interpreted language, meaning code is executed line-by-line by the CPython interpreter. This removes the need for a separate compilation step, enabling an interactive workflow through REPLs and notebooks. 2. Simple and Readable Syntax Python uses significant indentation rather than curly braces or keywords to define code blocks. Its syntax mimics natural English, adhering to the PEP 8 style guide to ensure high maintainability and readability. 3. Cross-Platform Compatibility Python is platform-independent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4ff65f0-3a9f-40d9-8171-a10f336813ab', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the ''Cache Stampede'' problem and identify two architectural strategies to mitigate it.', N'Senior', N'Cache Stampede occurs when a highly requested key expires, causing multiple concurrent requests to overwhelm the backend database while trying to recompute the value. Mitigations include using Probabilistic Early Recomputation to refresh keys before expiration or implementing distributed mutex locks to ensure only one process regenerates the cache entry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd4301ed-46bf-4277-83da-a11091eb3be2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between a class and an interface in TypeScript?', N'Fresher', N'A class is an object-oriented blueprint that includes both property definitions and implementation logic, whereas an interface is purely a structural contract that exists only for type checking. Interfaces are removed during compilation, while classes remain in the output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f515ffa-1f21-4767-ac54-a110aadc9d34', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the ''onReady'' hook in a Fastify application?', N'Middle', N'The onReady hook is triggered after all plugins have been registered and the server is prepared to start. It is useful for performing final validation or initialization tasks, such as verifying database connections, before the server begins listening for incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edc557fd-8c23-4675-a16c-a110f9480d68', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you listen to DOM events in Svelte?', N'Junior', N'You use the on: directive followed by the event name, such as on:click. You then assign a function reference to handle the event directly within the HTML template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f326f80-0980-4b9a-9018-a113684a9541', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you implement API authentication for machine-to-machine communication?', N'Senior', N'Machine-to-machine authentication is best handled using OAuth 2.0 Client Credentials flow, where the client exchanges a secret for a short-lived access token. This ensures secure, auditable communication without requiring human intervention or long-lived static credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c218870b-7533-491e-b5b1-a11815b9c1d0', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the trade-offs of using virtual threads in Java compared to platform threads?', N'Senior', N'Virtual threads are lightweight, user-mode threads managed by the JVM rather than the operating system, allowing for massive scalability in I/O-bound applications. While they significantly reduce the memory overhead of context switching, they are not suitable for compute-intensive tasks, as the OS scheduler still manages the underlying carrier threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c001e77-02a7-497e-9c23-a11be2a0861a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the implications of choosing an inappropriate shard count for an index?', N'Senior', N'Too many shards lead to excessive metadata overhead and fragmented resource usage, which can degrade cluster performance. Conversely, too few shards limit the ability to scale horizontally and can cause hot spots where a single node becomes a bottleneck for large indices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9ef244e-efb2-4554-b527-a11c583f0984', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between border-box and content-box?', N'Fresher', N'1. content-box: Default box-sizing property. The width and height properties (and min/max properties) includes only the content. Border and padding are not included 2. border-box: The width and height properties (and min/max properties) includes content, padding and border.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdc3624d-615c-4927-b028-a11f51127077', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between an Exception Handler and standard error handling in Litestar?', N'Intern', N'Exception handlers are specialized functions that catch and process specific errors globally or per-route. Instead of letting an application crash, they allow you to return a consistent, user-friendly JSON error response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f8c630d-aecd-40e1-af9d-a12388fdd96c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing an API, how do you balance the need for backward compatibility with the desire to evolve the system?', N'Middle', N'I use versioning strategies like URI versioning or header-based versioning to support older clients while introducing new features. I also implement a deprecation policy that provides sufficient notice to consumers before removing obsolete endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'427cd1e9-ab1a-454b-b1ab-a123cb30581c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you resolve a race condition occurring in a distributed environment?', N'Middle', N'I would use optimistic locking by including a version field in the data records to detect concurrent modifications. If that is insufficient, I would implement distributed locks using a tool like Redis or ZooKeeper to serialize access to the critical section.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'784f392d-b435-4611-8dcd-a124fe02d246', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django''s middleware pipeline affect request processing time, and how should it be optimized?', N'Senior', N'Middleware wraps every request and response, creating a layered execution stack that adds overhead for every layer included. Optimization involves auditing the middleware list, removing unused components, and ensuring that high-latency operations are not performed in the request path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66322f26-75f4-43bc-96f9-a12a017024b4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the role of the ''Origin-Agent-Cluster'' header in relation to DOM access.', N'Senior', N'This header instructs the browser to isolate the document into a separate agent cluster, which limits cross-origin DOM access between subdomains. It is primarily used for security, preventing side-channel attacks by disabling synchronous access to frames that might otherwise share the same memory space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e879569d-991f-4b43-97e1-a12ad6111a61', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass''s color manipulation engine handle color spaces, and why is this important for modern design systems?', N'Senior', N'Sass provides functions to modify colors across various spaces like HSL and RGB, though legacy functions often struggle with perceptual uniformity. Modern Sass implementations are moving toward supporting color spaces like OKLCH, which is crucial for maintaining consistent contrast and vibrancy across different themes in a design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4056568-40f3-4b96-8128-a12cb6c3e5d6', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the architectural implications of Qwik''s ''Fine-grained Reactivity'' system?', N'Senior', N'Fine-grained reactivity allows the framework to track specific state dependencies at the signal level rather than the component level. This architecture minimizes re-renders by updating only the specific DOM nodes bound to the changed state, avoiding the overhead of virtual DOM diffing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0e1cce1-00f0-4532-8041-a12fe55b2978', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you distinguish between a cascading failure and a localized service outage in a distributed system?', N'Senior', N'A cascading failure is characterized by a positive feedback loop where the failure of one component increases the load on others, causing sequential exhaustion of resources. A localized outage is restricted to a specific service or node, typically identified by stable dependency health metrics and lack of propagation patterns in distributed tracing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
