INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afd9978b-f423-4a71-ab51-a131b5aea685', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How would you implement multi-tenancy in a large-scale Laravel application, and what are the primary architectural challenges?', N'Senior', N'Multi-tenancy can be implemented via a shared database with tenant-scope columns or isolated databases per tenant. The primary challenge is ensuring strict data isolation and preventing cross-tenant information leakage, which requires robust middleware to inject tenant context into every query throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
