INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44141039-c562-4fa0-b458-a13f6e72ec39', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What architectural considerations should be made when implementing custom error handlers in Echo?', N'Senior', N'Custom error handlers must maintain a consistent response contract for the client while ensuring sensitive internal stack traces are redacted. They should also integrate with centralized observability tools to ensure errors are captured for alerting without leaking implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e9bbe0a-e60a-468f-b225-a13fc33a7b38', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a database transaction and a database lock?', N'Middle', N'A transaction ensures a set of operations are treated as a single unit, either all succeeding or all failing to maintain data integrity. A lock prevents concurrent processes from accessing or modifying specific rows or tables, which is necessary to prevent race conditions during high-concurrency operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84ce79aa-33d0-4fc1-a118-a13fd6d422bb', N'075b8862-431c-4678-9767-f55359758a4a', N'What are dynamic components?', N'Junior', N'Dynamic components allow you to switch between different components within the same mounting point using the component tag. This is useful for building tab interfaces or wizards where the content changes based on user selection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f96a2e72-83dc-49b9-87de-a1415f8c0fde', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Discuss the performance implications of the C++ exception handling mechanism.', N'Senior', N'C++ exception handling typically uses a zero-cost model where no overhead is incurred during the ''happy path'' of execution. However, when an exception is thrown, the stack unwinding process is computationally expensive, involving lookups in side-tables to identify cleanup actions, which can introduce unpredictable latency in real-time systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'888cb787-2d1d-450c-8d64-a1429799fbe7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go use a mark-and-sweep garbage collector instead of reference counting?', N'Middle', N'Reference counting introduces significant overhead for every pointer assignment and struggles with circular references, which require complex logic to resolve. Mark-and-sweep is more efficient for high-throughput systems because it handles cycles naturally and allows for concurrent execution, minimizing pause times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01b62eec-db42-463e-9799-a1429a18bf8c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if a module cannot be resolved by Webpack?', N'Junior', N'If Webpack cannot resolve a module, it will throw a build error and stop the compilation process. This usually happens because of a typo in the import path, a missing file, or a misconfiguration in the resolve settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fdf99cd-c880-4e1e-b98b-a142ab01df19', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the security implications of Express''s default settings regarding request headers and server fingerprinting?', N'Senior', N'By default, Express includes the ''X-Powered-By'' header, which exposes the framework version to potential attackers for targeted exploits. Security best practices require disabling this header and using middleware like Helmet to set appropriate security-related HTTP headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4749d7b2-9a1a-4c27-b456-a1432c2f2336', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do goroutines differ from OS threads in terms of stack management and memory overhead?', N'Senior', N'Goroutines start with a small, growable stack (typically 2KB) that expands and shrinks as needed, whereas OS threads typically have a fixed, large stack size (often 1MB-2MB). This allows Go to multiplex thousands of goroutines onto a small number of OS threads, significantly reducing memory consumption and context-switching overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17c20ee1-c87d-4c0b-8e03-a143a8771786', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do you need a Cookie', N'Fresher', N'Cookies are used to remember information about the user profile(such as username). It basically involves two steps, 1. When a user visits a web page, the user profile can be stored in a cookie. 2. Next time the user visits the page, the cookie remembers the user profile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
