INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efea4cf9-def0-427f-8f2f-a1457586f760', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary use case for ''Context Receivers'' in Kotlin?', N'Middle', N'Context receivers allow functions to declare their dependency on specific types being available in the scope without passing them as explicit arguments. This helps in building cleaner APIs where shared state or dependencies are implicitly provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b920b2c-5ff7-41b5-8688-a149bdeb75c2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'In what ways does Svelte''s architecture support tree-shaking better than runtime-heavy frameworks?', N'Senior', N'Because Svelte is a compiler, it only includes the code necessary for the features actually used in a component. It does not ship a large general-purpose runtime, ensuring that dead code is eliminated at the source rather than relying on bundler-level tree-shaking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad61c8e3-f5e2-45d1-9507-a14a1a7ed5d4', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is meant by the term ''schema-less'' in MongoDB?', N'Junior', N'Schema-less means that documents in the same collection do not need to have the same set of fields or structure. This provides developers with the flexibility to change the data model over time without performing complex database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
