INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80ebfeb1-6576-490c-aa68-a14dcb627d3e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it often preferred to use a custom ''group'' structure in Echo for versioning APIs?', N'Senior', N'Using routing groups allows for isolated middleware application, such as requiring authentication only on specific versions or paths. This provides a clean architectural separation that prevents logic leakage between different API versions and improves readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c401efb6-99b2-4143-8856-a14e92f59853', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the advantages and disadvantages of using AJAX?', N'Fresher', N'AJAX (Asynchronous JavaScript and XML) is a technique in JavaScript that allows web pages to send and retrieve data asynchronously from servers without refreshing or reloading the entire page. Advantages - Smoother user experience: Updates happen without full page reloads, like in mail and chat applications. - Lighter server load: Only necessary data is fetched via AJAX, reducing server load and improving perceived performance of webpages. - Maintains client state: User interactions and any client states are persisted within the page. Disadvantages - Reliance on JavaScript: If disabled, AJAX functionality breaks. - Bookmarking issues: Dynamic content makes bookmarking specific page states difficult. - SEO challenges: Search engines may struggle to index dynamic content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5574e7e-6f38-4428-84c7-a14f3fa01ac8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the ''Optional Chaining'' feature?', N'Fresher', N'Optional chaining is a process for querying and calling properties, methods, and subscripts on an optional that might currently be nil. If the optional contains a value, the call succeeds; if it is nil, the call returns nil, preventing crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbd2915c-c760-465f-92cf-a15085192b00', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the role of the ''Context'' object in Hono, and why is it preferred over raw Request/Response objects?', N'Middle', N'The Context object acts as a unified interface that encapsulates both the Request and Response objects along with helper methods. It provides a clean API for state management, data validation, and header manipulation while abstracting away the underlying runtime differences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43c2f91c-98da-4033-8525-a151e7b66260', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does a content delivery network (CDN) optimize performance?', N'Middle', N'A CDN caches static assets like images, CSS, and JavaScript files on geographically distributed servers closer to the end user. This minimizes latency by reducing the physical distance data must travel and offloads traffic from the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6fc75e4-6296-4f7a-a8d8-a15823789572', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is an optimistic UI update?', N'Fresher', N'An optimistic UI update is a pattern where the UI updates to show the result of an action before the server has confirmed it. Remix makes it easy to implement this to make applications feel faster to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
