INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b36f90b8-0461-4114-a215-a159af50f9a9', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s partial hydration contribute to core web vitals?', N'Middle', N'Partial hydration significantly reduces the Total Blocking Time and Time to Interactive by preventing large JavaScript bundles from executing on page load. This results in better performance scores, specifically regarding Largest Contentful Paint and Cumulative Layout Shift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4096ca9a-7e81-4e7a-a7f7-a15b3bb5f991', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is ''Ahead-of-Time'' (AOT) compilation in the context of Quarkus?', N'Middle', N'AOT compilation refers to the process of converting Java bytecode into native machine code before the application runs. In Quarkus, this is used to create native images that start instantly and consume minimal memory, as the virtual machine does not need to perform JIT compilation at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7442489-290e-4ac1-a7f4-a15e23791570', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web manage multiple workers?', N'Fresher', N'Actix-web automatically spawns a number of worker threads based on the number of available CPU cores. Each worker runs its own instance of the application, allowing the server to utilize multi-core architectures effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed26f304-b1d2-44cf-929a-a15e6bbebd8a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s development server leverage native ES modules to achieve near-instant startup times?', N'Senior', N'Vite skips the traditional bundling step during development by serving source files over native ESM. The browser requests modules on-demand, allowing Vite to only transform and serve the specific file requested rather than processing the entire dependency graph upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d97d00f-6778-4b1c-9497-a15ea32e7bd8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Compare and contrast Redux Thunk and Redux Saga for handling side effects.', N'Senior', N'Thunk is simple and uses promises, making it ideal for straightforward asynchronous flows, but it can lead to ''callback hell'' in complex scenarios. Sagas utilize generator functions to provide a more robust, testable, and declarative way to handle complex concurrency, race conditions, and cancellation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e09fb6a-3e4e-491d-a18e-a15fba626cab', N'4c000000-0000-0000-0000-000000000005', N'How do you approach schema migration in a large-scale, zero-downtime system?', N'Senior', N'Use a multi-phase deployment approach where the application is updated to support both old and new schema versions simultaneously. Once the transition is complete, the old schema is deprecated and removed in a subsequent release to ensure continuous availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
