INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ccaac11-1a49-4fb5-9f78-a162204a6466', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the significance of the ''ArgumentResolver'' in the controller lifecycle?', N'Middle', N'The ArgumentResolver is responsible for inspecting the parameters of a controller method and mapping them to incoming request data. It automates tasks like converting route parameters into entity objects, reducing boilerplate code within the controller itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d6276bf-a1c1-4b2d-aa84-a1641f862e97', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You pushed a change that caused a production outage. What is your immediate priority?', N'Junior', N'The immediate priority is to restore service, usually by rolling back the deployment to the last known stable version. Once the system is stable, you can investigate the root cause without the pressure of an ongoing outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
