INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bc9065e-96b6-4131-a50e-a16758fedb36', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage service discovery in a microservices architecture?', N'Senior', N'Micronaut provides a client-side load balancing and service discovery abstraction that integrates with various registries like Consul, Eureka, or Kubernetes. By shifting the discovery responsibility to the client, it simplifies service communication and increases resilience by allowing the client to maintain a local cache of service instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6db63b62-cf89-4117-9a56-a16918399745', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does it mean for an Actix-web handler to be ''Send''?', N'Junior', N'Because Actix-web runs on a multi-threaded runtime, handlers and their dependencies must be ''Send'' to be safely moved between threads. This ensures that data can be accessed across the different worker threads that the server manages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50ed2902-62f5-46e8-87bc-a169884bb232', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of ''Bundle'' in Symfony and when it might be considered an anti-pattern to create too many.', N'Senior', N'Bundles are meant to encapsulate reusable features, but creating too many can lead to fragmented dependencies and complex service configuration. In modern Symfony, many developers prefer keeping application-specific logic in organized folders within the src directory, using bundles only for true modularity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc3bdd26-aa59-43f5-ad54-a16a7000ccf7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''Finalizer'' differ from ''Dispose''?', N'Middle', N'The Finalizer is called by the garbage collector during the reclamation process and is non-deterministic, making it unsuitable for releasing critical resources promptly. Dispose is a pattern implemented via IDisposable that allows for deterministic cleanup of resources, which is preferred for performance and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
