INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a717e1af-b0af-48bc-aa67-a174d3496067', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is the CAP theorem often criticized as being too simplistic for real-world system design?', N'Senior', N'The CAP theorem only addresses a binary choice between availability and consistency during a network partition, ignoring the latency-consistency trade-off that exists during normal operation. Furthermore, it treats the system as a monolith rather than accounting for partial failures or varying levels of consistency models. Modern systems often use the PACELC theorem to better describe behavior during both partition and non-partition scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aad7a19d-1965-4aa4-8276-a1777f52540b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the benefits and drawbacks of using streams for large data processing in Node.js.', N'Senior', N'Streams allow processing data in chunks rather than loading the entire payload into memory, which prevents memory exhaustion and reduces latency. The drawback is increased architectural complexity, as handling backpressure and error propagation across piped streams requires careful management to avoid data loss or unhandled promise rejections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
