INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a3df875-0663-411b-a2e2-a17e8ae66303', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s approach to error handling facilitate the ''Fail-Fast'' principle in backend systems?', N'Senior', N'By allowing handlers to return errors immediately, Echo''s middleware stack can intercept and process them at a centralized level. This prevents the execution of subsequent logic and ensures that the response is returned to the client as soon as a failure is detected, minimizing resource wastage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6de01b5e-70ac-463e-b99c-a18076d8b788', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is an enum?', N'Intern', N'An enum is a user-defined data type consisting of a set of named integer constants. It is used to make code more readable by replacing magic numbers with descriptive names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79702603-af92-4963-a482-a180c90530bf', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is the rule of three/five/zero important in C++ when managing resources within a class?', N'Middle', N'These rules dictate that if a class manages a resource like dynamic memory, it must explicitly define a destructor, copy constructor, and copy assignment operator to prevent shallow copy issues. Failure to implement these correctly leads to double-free errors or memory leaks, whereas the rule of zero encourages relying on RAII-compliant members to avoid manual resource management entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ef0f72-81e5-40f6-aaae-a1825414e625', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is an event handler in jQuery?', N'Intern', N'An event handler is a function that executes when a specific interaction occurs, such as a click, mouse hover, or keyboard press. jQuery simplifies this by providing methods like .click() or .on() to attach these functions to elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27fa8208-b8a7-4438-9d42-a18367f9b2d0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a tunable consistency?', N'Intern', N'Tunable consistency allows developers to choose the level of consistency for each individual read or write operation. You can decide whether you need the fastest possible response or the most up-to-date data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
