INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'854903ae-7507-4ed3-8c5d-a18833836d86', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the primary role of Rocket in web development?', N'Intern', N'Rocket is a web framework for the Rust programming language designed to make it easy to write fast, type-safe, and secure web applications. It provides high-level abstractions that handle request routing, parameter parsing, and response generation while leveraging Rust''s safety guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc36024a-bff3-4b1b-beb5-a1883a53c9dc', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the architectural implications of using ''opaque types'' versus ''boxed protocols''?', N'Senior', N'Opaque types allow a function to hide the underlying concrete type while ensuring the caller sees a specific protocol, allowing the compiler to retain static type information for optimization. Conversely, boxed protocols (existentials) erase the concrete type, forcing runtime dispatch and potential heap allocations. Using opaque types is generally preferred for performance-critical APIs where the return type is fixed at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'affbaad7-26f3-486a-8ff4-a189a75454b2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle concurrent requests at the routing level?', N'Senior', N'Chi is inherently thread-safe because it does not store mutable state during the routing process for a specific request. Since each request is handled in its own goroutine and the routing tree is read-only after initialization, it handles high concurrency natively without the need for mutexes or locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a5d42b7-88e2-4165-ba81-a18a81d6202b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does it mean for a framework like Fiber to be ''zero-allocation''?', N'Intern', N'Zero-allocation refers to a design goal where the framework minimizes the creation of new objects in memory during request processing. By reusing memory buffers, it reduces the pressure on the garbage collector and improves overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14999aa4-fa2b-4b4d-bf9f-a18efe26a918', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage to achieve near-instant TTI regardless of application size?', N'Senior', N'Qwik achieves this by keeping the initial JavaScript execution footprint near zero. Because it does not hydrate, it avoids the main-thread blocking associated with framework initialization, only fetching the specific chunk of code required for an interaction at the moment it happens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca0e1166-a326-4585-813f-a18f3e0f9641', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of ''tail call optimization'' in C# and why it is not guaranteed.', N'Senior', N'Tail call optimization allows a method to reuse the current stack frame for a final call to another method. The C# compiler and JIT do not guarantee this optimization, as it complicates debugging and stack trace generation, and it is only reliably performed in specific IL patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6994802-7b76-4aef-8e6c-a192de2febcd', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does Zero-Copy optimization improve messaging broker performance?', N'Senior', N'Zero-copy allows the broker to transfer data directly from the disk cache to the network stack without copying it into the application buffer. This significantly reduces CPU utilization and memory bandwidth consumption, allowing high-throughput brokers to handle millions of messages per second.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'254e7370-286e-4f88-a05d-a193a8e0b6aa', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why is it often unnecessary to use global state management libraries like Redux in Remix?', N'Middle', N'In Remix, the server acts as the single source of truth, and data is passed down through components via loaders. Since the server synchronizes the state after every mutation, there is rarely a need for complex client-side stores to track application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'069fb18d-dc13-4095-b5cd-a193d09e1928', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When working on a complex system, how do you estimate the potential for regression testing?', N'Middle', N'I analyze the impact scope of the proposed changes and determine the level of automated versus manual coverage needed. If the system lacks sufficient tests, I add an estimation buffer for the time required to write necessary safety-net tests before implementing the change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'722c13a9-4da0-4011-8364-a1951e5465a3', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the architectural risks of ''over-hydrating'' a Nuxt application.', N'Senior', N'Over-hydration occurs when too much data or component logic is serialized and sent to the client, leading to a long ''Time to Interactive''. To mitigate this, developers should use lazy-loading for non-critical components and ensure only the necessary state is serialized in the payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d2ad606-8a12-43a4-b36c-a19abc2ffa41', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of isFinite function?', N'Intern', N'The global isFinite() function determines whether the passed value is a finite number. It returns false if the value is +infinity, -infinity, or NaN (Not-a-Number), otherwise it returns true. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f189e6-0fe5-4c99-b018-a19ce482ed94', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can you use standard browser APIs in Qwik?', N'Junior', N'Yes, Qwik supports all standard browser APIs. Since the code eventually runs in the browser, you can access the DOM, fetch data, or use Web APIs just as you would in any other JavaScript framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'442aa8bd-6cd9-4af1-b231-a19d69dec0ee', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a redirect in Flask?', N'Intern', N'A redirect is a response that tells the client''s browser to navigate to a different URL. It is commonly used after a user submits a form to prevent the form from being resubmitted if the user refreshes the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44f72441-93c2-438f-8257-a19f507a3a02', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix manage backpressure?', N'Middle', N'Actix uses mailbox limits for actors to prevent memory exhaustion. When a mailbox reaches its capacity, the sender is either forced to wait or the message is dropped, depending on the implementation, ensuring the system remains stable under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c160304b-4371-4dca-b80e-a1a2f1dada8c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What does the ''target'' configuration in Webpack control?', N'Middle', N'The target property tells Webpack to compile for a specific environment, such as ''web'' for browsers or ''node'' for server-side execution. It ensures that the generated code uses compatible features and APIs, such as correctly handling built-in modules or global objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1086a7f1-e9f8-4915-b981-a1a570c44e0e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why should you prefer ''size_t'' over ''int'' for indexing containers?', N'Middle', N'size_t is an unsigned integer type guaranteed to be large enough to hold the size of the largest possible object on the target platform. Using int can lead to overflow issues on systems where the number of elements exceeds the range of a signed integer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20197486-e44e-4122-81cb-a1a70e818a14', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What does res.json() do?', N'Intern', N'The res.json() method sends a JSON response. It automatically sets the Content-Type header to application/json and converts the provided JavaScript object or array into a JSON string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9d3e382-3d9f-42e3-8a76-a1a7e6aa0431', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Jest?', N'Intern', N'_Jest_ is a JavaScript unit testing framework created by Facebook based on Jasmine and provides automated mock creation and a jsdom environment. It''s often used for testing components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44a15b3f-3f45-4465-b641-a1aa3215b49e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does the use of useMemo and useCallback impact application memory usage and performance?', N'Senior', N'These hooks memoize values and functions, preventing expensive recalculations or unnecessary child component re-renders. However, over-using them introduces overhead, as React must store the dependencies and the previous result in memory, which can lead to increased heap usage if applied prematurely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6a7b39b-c453-4be8-bf90-a1ac6dfea897', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the architectural trade-offs of using Pydantic for data validation within FastAPI.', N'Senior', N'Pydantic provides robust, type-hint-driven validation that ensures data integrity and automatic documentation generation via OpenAPI. However, the trade-off is the CPU overhead incurred during the parsing and validation process, which can become a bottleneck in extremely high-throughput systems if the models are overly complex or deeply nested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41dd7d5d-8dbe-446f-9936-a1ac75239b67', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is a Mutator in Eloquent?', N'Intern', N'A mutator is a method that allows you to transform or format an Eloquent attribute value before it is saved to the database. It is useful for tasks like hashing passwords, stripping whitespace, or converting strings to lowercase automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c222e599-0fa9-4ebc-a1e5-a1aced694449', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between a request-response cycle and a channel communication?', N'Fresher', N'The request-response cycle is stateless and follows the HTTP protocol, where a client sends a request and the server sends a response. Channel communication is stateful, keeping a persistent connection open for ongoing data exchange.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ab9a567-1160-45ef-bf72-a1ad6bdc077b', N'954a0331-deff-4399-b588-96f39fec001d', N'What techniques can improve performance in an Angular app?', N'Middle', N'Improving Angular app performance involves both build-time and runtime optimizations. Key techniques include: - Build-time: - Using Ahead-of-Time (AOT) compilation, which is the default for production builds, compiles your Angular HTML and TypeScript into efficient JavaScript code during the build process - Building with production flags (ng build --configuration production or ng build --prod in older versions) to enable optimizations like tree shaking, minification, and dead code elimination - Runtime: - Implementing lazy loading for modules to load application parts only when they are needed, significantly reducing the initial bundle size and load time - Setting the change detection strategy to OnPush for components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'856d7d10-029e-47d8-9345-a1b0733df7b9', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does ''Eventual Consistency'' mean in a distributed database?', N'Middle', N'Eventual consistency is a model where data updates may not be visible immediately across all nodes, but the system guarantees that all nodes will eventually converge to the same state. This model is often chosen to maximize availability and partition tolerance in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b543f5fc-ea64-4936-ba77-a1b697c347d8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is eval function in javascript?', N'Intern', N'The eval() function evaluates JavaScript code represented as a string. The string can be a JavaScript expression, variable, statement, or sequence of statements. If the argument of eval() is not a string, eval() returns the argument unchanged. In the following example, the String constructor is specified and eval() returns a String object rather than evaluating the string. Warning: *Executing JavaScript from a string is an enormous security risk. It is far too easy for a bad actor to run arbitrary code when you use eval().* &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e6ef190-262a-4b01-9e11-a1b7bb018d95', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the architectural advantages of Litestar''s ''Plugin'' system for integration.', N'Middle', N'Litestar''s plugin system allows for the decoupling of framework core logic from third-party integrations like ORMs or validation libraries. By using a standardized interface, plugins enable the framework to automatically inspect and adapt to external data structures, which reduces boilerplate code and ensures consistent behavior across different database or service integrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd825f03-c819-4817-bd7d-a1ba6b021ec9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the borrow checker in Rust''s memory safety model?', N'Middle', N'The borrow checker is a static analysis tool that enforces strict rules for memory access at compile time. It ensures that references do not outlive the data they point to and that there is either one mutable reference or multiple immutable references to a resource, preventing data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21d9c7ca-4b2c-4f43-89b9-a1bd822d5504', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of a Snitch in Cassandra?', N'Junior', N'A Snitch informs the database about the network topology of the cluster. It maps nodes to data centers and racks, allowing Cassandra to route requests efficiently and replicate data across different locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b933c1b-6a47-47d3-b65f-a1be8d857e45', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do jQuery event namespaces improve event management?', N'Middle', N'Namespaces allow developers to group event handlers and remove specific ones without affecting other handlers attached to the same event type. This is particularly useful in complex components where multiple plugins might be listening to the same events on the same elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cffecd11-b7b6-4904-956a-a1bf9692611e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you handle external libraries that don''t have TypeScript support?', N'Junior', N'You can install type definition files from the DefinitelyTyped repository, usually prefixed with ''@types/''. If no types exist, you can create a declaration file to define the shapes of the library''s exports yourself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
