INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27b50e72-a71d-4008-b4a5-a1c1d04d7b69', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a ''GenServer'' in the context of a Phoenix application, and when should you use it?', N'Middle', N'A GenServer is a generic process behavior that encapsulates state and handles asynchronous or synchronous requests. You should use it to manage long-running background tasks, maintain shared in-memory state, or coordinate resources that need to persist beyond the lifecycle of a single HTTP request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
