INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69684bc7-5d6d-4e02-858e-a1d78292bceb', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a Storage Engine in MongoDB?', N'Intern', N'The storage engine is the component of the database that is responsible for managing how data is stored, both in memory and on disk. MongoDB supports multiple storage engines, as different engines perform better for specific workloads. Example: command to find storage engine MongoDB supports mainly 3 storage engines whose performance differ in accordance to some specific workloads. The storage engines are: * WiredTiger Storage Engine * In-Memory Storage Engine * ~~MMAPv1 Storage Engine~~ ( This Storage Engine has been deprecated after MongoDB 4.2 ) 1. WiredTiger Storage Engine WiredTiger is the default storage engine starting in MongoDB 3.2. It is well-suited for most workloads and is recommended for new deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
