INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'115c31b2-b998-40f5-884d-a1ec5143f18a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a GET and POST request in Django?', N'Intern', N'A GET request is used to retrieve data from the server without changing the state of the system. A POST request is used to send data to the server to create or update resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'275d5795-1bcd-489c-9b0d-a1ecbdbeca1b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js event loop handle asynchronous I/O operations compared to a traditional multi-threaded model?', N'Middle', N'Node.js uses a single-threaded event loop and offloads I/O tasks to the libuv thread pool or system kernel. This allows the main thread to remain non-blocking while waiting for operations to complete, whereas traditional models assign a dedicated thread to each request, which can lead to high memory consumption under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05fa7f0d-4ffe-4238-8a2a-a1ecf2d73a7a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the impact of ''Snapshot Isolation'' on transaction anomalies?', N'Senior', N'Snapshot Isolation ensures that a transaction operates on a consistent version of the database at the time it started, preventing dirty and non-repeatable reads. However, it is susceptible to write skew, where two transactions read overlapping data and update disjoint sets, leading to a violation of integrity constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65ed2fb3-a514-4b25-bb4a-a1f0449acff7', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Describe the role of a write-ahead log (WAL) in maintaining database durability and performance.', N'Senior', N'A WAL ensures ACID compliance by recording changes to disk before they are applied to the main data files, allowing for recovery after a crash. By appending changes sequentially rather than performing random I/O writes to the main storage, it significantly improves write performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43afb3b5-bd72-44db-95cd-a1f11c02631b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the Decorator pattern and how is it used?', N'Intern', N'The Decorator pattern is a structural design pattern that allows behavior to be added to individual objects, dynamically, without affecting the behavior of other objects from the same class. It is used to extend the functionalities of objects by wrapping them with additional behavior. In JavaScript, this can be achieved using higher-order functions or classes. For example, if you have a Car class and you want to add features like GPS or Sunroof without modifying the Car class itself, you can create decorators for these features. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of the Strategy pattern The Strategy pattern is a behavioral design pattern that allows you to define a family of algorithms, encapsulate each one as a separate class, and make them interchangeable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9568432c-f23e-43f8-a542-a1f2f2397ded', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does routing work in Flask?', N'Intern', N'Routing is the process of mapping a specific URL to a Python function. When a user visits a URL, the Flask router determines which function should be executed to handle that request and return a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e353e58-bb9c-42b5-808f-a1f567b6e886', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of using Astro for SEO?', N'Fresher', N'Because Astro renders static HTML, search engine bots can easily crawl and index the content without needing to execute JavaScript. This results in significantly better search engine optimization out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0e3a32b-a89e-4130-b6ba-a1f9f1fbce61', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle assets like CSS and images?', N'Junior', N'Remix treats assets as first-class citizens, allowing you to link CSS files directly within route components. This ensures that only the necessary styles for a specific route are loaded, improving overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c81b33e2-5554-415e-9b46-a1faa33c968c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the trade-off between using ArrayList and LinkedList.', N'Middle', N'ArrayList provides faster random access but expensive insertions or deletions in the middle of the list due to element shifting. LinkedList provides faster insertions and deletions, but it incurs higher memory overhead and slower random access due to pointer traversal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59c91103-64ab-4888-a66e-a1fc4535f35f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between prioritizing execution speed versus memory usage?', N'Fresher', N'You analyze the constraints of the target environment. If the system has limited hardware resources, memory efficiency is prioritized, whereas if the system requires low latency for real-time processing, execution speed takes precedence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f0cec3c-ccb9-43bc-829b-a1fe587ae9f6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is Ember Data?', N'Intern', N'Ember Data is a library specifically designed to handle data persistence and management within an Ember application. It provides a standardized way to fetch, update, and delete data from a backend server, often using JSON:API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d739628-53cd-4786-bc8b-a1ff857eb707', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of logging in ASP.NET Core?', N'Intern', N'Logging is used to capture diagnostic information about an application''s behavior while it is running. It helps developers track down issues, monitor performance, and understand the flow of events within the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
