INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2e0e087-8a87-4262-8229-a1ffbd831040', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s approach to hydration differ from frameworks like React, and what is the impact on performance?', N'Senior', N'SvelteKit uses a compile-time approach where the framework generates highly optimized imperative code that manipulates the DOM directly. Because it does not require a virtual DOM diffing process at runtime, the hydration phase is significantly faster and requires less memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a13e567b-66b9-4218-b4ef-a2011a349cda', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo facilitate the implementation of the decorator pattern for cross-cutting concerns?', N'Senior', N'Echo''s middleware structure inherently supports the decorator pattern by allowing you to wrap handlers with logic that executes before or after the main request. This promotes clean separation of concerns, such as authentication, logging, and rate limiting, without cluttering business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22fdcb01-3d2a-457b-a00c-a2018dc40209', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle styling?', N'Fresher', N'Preact supports standard CSS classes, inline styles, and CSS-in-JS libraries. Inline styles in Preact are passed as objects, similar to React, which provides a flexible way to manage component-level styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a775687-0a29-42a5-8cd9-a2022315cbcf', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the trade-offs of using a ''Centralized'' vs ''Decentralized'' configuration management system?', N'Senior', N'Centralized systems are easier to manage and provide a single source of truth but introduce a single point of failure and potential bottleneck. Decentralized systems offer higher availability and fault tolerance but introduce complexity regarding synchronization and eventual consistency across nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17885021-d035-4450-9d7e-a204e2c93994', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage response serialization?', N'Intern', N'Litestar automatically serializes returned data into JSON or other formats based on the response headers. It uses type hints to determine the structure and ensures the output matches the expected API schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25bfd52-68ce-4061-a9cb-a2072327caab', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary goal of refactoring a design?', N'Intern', N'The primary goal of refactoring is to improve the internal structure, readability, and maintainability of the design without changing its external behavior. It helps keep the codebase clean and prevents it from becoming overly complex as new features are added.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbbc3273-5b49-4546-aa60-a207295033de', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Doctrine ORM in the context of Symfony?', N'Intern', N'Doctrine is an Object-Relational Mapper that acts as a bridge between the database and the application. It allows developers to interact with the database using PHP objects instead of writing raw SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'890b2088-358b-467b-a99b-a20d4b31bc1e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Content Negotiation?', N'Fresher', N'Content negotiation is the mechanism by which the server selects the best representation of a resource for a client based on the request headers. For example, it determines whether to return JSON or XML depending on what the client requested in the Accept header.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e87820b7-67fc-4747-8b16-a20dced31fd9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the Buffer class in Node.js?', N'Intern', N'In Node.js, the Buffer class is a core module that provides a way to read, manipulate, and allocate binary data, which primarily represents a sequence of bytes (octets). Key Features - Backbone of I/O Operations: Buffers serve as the primary data structure for handling I/O in Node.js, acting as a transient container for data being read from or written to streams and files. - Raw Binary Data: Buffers are used for handling raw binary data, which is particularly useful for tasks like cryptography, network protocols, and WebGL operations. - Unmodifiable Size: Buffers are fixed in size after allocation. To resize a buffer, you''d need to create a new buffer with the necessary size and optionally copy over the original data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26ab12ba-7b02-4753-9147-a21043c61de6', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between global and route-level middleware in Hono?', N'Intern', N'Global middleware runs for every single request that hits the application, whereas route-level middleware is applied only to specific paths or groups of routes. This allows for granular control over which logic executes for specific endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef01b3c4-c602-485e-8381-a214de7d747f', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Compare ''Optimistic'' and ''Pessimistic'' locking strategies in high-concurrency environments.', N'Senior', N'Pessimistic locking prevents conflicts by locking resources upon access, ensuring data consistency but reducing concurrency. Optimistic locking assumes conflicts are rare, checking for modification only at the time of commit; it is more performant in read-heavy systems but requires logic to handle retries during contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7264791d-0e4e-42e5-874a-a21534d6ac44', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is database replication?', N'Intern', N'Database replication is the process of copying data from one database server to one or more other servers. It is used to improve availability, provide read-scaling, and act as a backup mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1e85191-cd44-4055-b5bf-a21600ea2178', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When investigating a network-related issue between services, what tools or metrics do you prioritize?', N'Middle', N'I would prioritize checking network latency, packet loss, and connection timeouts between the services. Tools like ping, traceroute, or network-level monitoring dashboards are useful to identify if there is a bottleneck at the infrastructure layer, such as a misconfigured load balancer or firewall rule. I would also inspect service mesh telemetry to see if traffic is being routed or dropped incorrectly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9452aea-20df-4c3a-9212-a2169c896979', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach capacity planning for a system that expects a 10x increase in users over the next year?', N'Middle', N'I use load testing to determine the breaking point of individual components and identify which parts of the system are the most likely bottlenecks. I then design for modularity, ensuring that each service can be scaled independently, and establish clear monitoring thresholds to trigger automated scaling events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ef0e762-173a-4153-81bd-a217577fc7c4', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you handle schema migrations in a large-scale, sharded database without downtime?', N'Senior', N'Schema migrations are performed using a multi-step process: adding new columns as nullable, updating application code to write to both old and new columns, backfilling historical data, and finally dropping the old columns. This ''Expand and Contract'' pattern ensures the system remains operational throughout the schema evolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'591d3e4d-4e62-4bb3-9d71-a21bd25a4aae', N'954a0331-deff-4399-b588-96f39fec001d', N'Why are ''Pure Pipes'' preferred in Angular?', N'Middle', N'Pure pipes are only re-evaluated when their input arguments change, which makes them highly efficient. In contrast, impure pipes run on every change detection cycle, which can lead to performance degradation if they perform complex calculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0000da13-4cce-42c9-8f60-a21c7bf4a141', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Is Litestar suitable for large applications?', N'Fresher', N'Yes, Litestar is designed with modularity in mind. It supports features like route partitioning, complex dependency injection, and clear code organization, which make it well-suited for maintaining and scaling large, professional codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c03dd05-cab1-4288-ab2c-a21f73b1698d', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is ''Idempotency'' critical in distributed system architectures?', N'Senior', N'Idempotency ensures that performing the same operation multiple times produces the same result as performing it once. It is essential for handling retries after network timeouts or partial failures, preventing side effects like double-charging a user or duplicate data entry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'268b6b57-83f2-499d-b1bc-a21fa9050db2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the performance overhead of Express middleware chains and how deep nesting affects request latency.', N'Senior', N'Each middleware adds a layer of function execution and stack tracing to the request lifecycle. While individual overhead is minimal, deep chains or synchronous operations within middleware can block the event loop, causing cumulative latency and reducing the overall throughput of the Node.js process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b29386af-1b74-4b5d-b3c4-a223ec362c2a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt improve development speed?', N'Fresher', N'Nuxt improves development speed by providing an opinionated project structure, auto-importing components, handling routing automatically, and offering a robust module system that manages complex configurations for you.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ebed511-fbf6-4972-839d-a224e9fb1492', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a covering index?', N'Middle', N'A covering index contains all the columns requested by a specific query, allowing the database to retrieve the data directly from the index structure. This eliminates the need for an additional lookup to the base table, significantly reducing disk I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a43ded34-e88b-42ca-a559-a2275369aeac', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why should you check for ''dependency conflicts'' when an application suddenly stops working?', N'Fresher', N'Applications often rely on external libraries or services that may be updated independently. If one of these dependencies changes, it can become incompatible with your application, leading to failures that are not caused by your own code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'275ad00f-5658-493d-9cfe-a228bc9df5ee', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify approach security in terms of input validation?', N'Middle', N'Fastify enforces strict schema validation on input parameters, headers, and bodies by default. This approach prevents common vulnerabilities like mass assignment or injection attacks by ensuring that only expected data structures are allowed into the business logic layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd91dcb49-b086-471c-9f98-a22905f54cb0', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of an attribute projection expression in a query?', N'Middle', N'Projection expressions allow you to specify only the attributes you need in the response rather than retrieving the entire item. This reduces the amount of data transferred over the network, lowering latency and decreasing the total read capacity consumed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
