INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff275bd5-8300-4e92-9d8f-a232753b9c23', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''untrack'' in SolidJS, and when should it be used?', N'Senior', N'Untrack is a utility that prevents an effect or block from registering dependencies on signals accessed within its scope. It is useful when you need to read the current value of a signal inside an effect without triggering a re-execution when that signal changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
