INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2adb98de-fd1c-47f1-a3d3-a23a33537607', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the advantages of using JWT for API authentication?', N'Middle', N'JWTs are stateless, meaning the server does not need to query a database to verify the user''s identity on every request. This reduces latency and makes horizontal scaling easier since the authentication information is self-contained within the token.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
