INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ea0d22e-b310-4af4-b6ec-a243a05bf75f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the architectural considerations when implementing a client-side state management system in a high-concurrency real-time application?', N'Senior', N'You must prioritize data normalization to avoid redundant updates and ensure efficient reconciliation. Implementing immutable state updates helps with change detection, but you must balance this against memory pressure and the cost of deep cloning objects. Furthermore, handling optimistic updates requires a robust mechanism to revert state if the server-side synchronization fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9e45d4e-a573-4342-9fa2-a24479c3882f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the limitations of Qwik''s ''Resumability'' when dealing with third-party scripts?', N'Senior', N'Third-party scripts that rely on global window events or standard hydration behaviors can conflict with Qwik''s event delegation. Developers must ensure these scripts are wrapped or loaded in a way that respects Qwik''s non-hydration lifecycle to avoid unexpected errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cac301b8-f1b8-4d19-8a10-a246449bd67f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'A user reports an error that you have never seen before. What information do you request from them?', N'Junior', N'I would ask for the specific steps taken leading up to the error, a screenshot or exact text of the error message, and details about their browser or device. Understanding the sequence of actions and the user''s environment is critical to replicating the state that triggered the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44ff811e-4f2f-486b-bd4a-a2468f333fc4', N'4c000000-0000-0000-0000-000000000005', N'How do you ensure data consistency in a system utilizing eventual consistency?', N'Senior', N'Consistency is managed through techniques like versioning, vector clocks, or deterministic conflict resolution strategies such as Last-Write-Wins. Additionally, read-repair or background anti-entropy processes are used to reconcile discrepancies between replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74f7ca83-0a8a-4b5d-801e-a247728b0221', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it generally discouraged to perform heavy CPU-bound computations in the main Node.js event loop?', N'Senior', N'Since Node.js operates on a single-threaded event loop, any synchronous CPU-bound task blocks the loop, preventing it from handling incoming I/O events or timers. This leads to increased latency and potential timeouts for all concurrent requests, effectively stalling the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ce0b2b2-e9c7-4f6a-a93e-a24807b373d9', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a computed property in Vue?', N'Junior', N'A computed property is a function that returns a value based on other reactive data. It is cached based on its dependencies and will only re-evaluate when those specific dependencies change, making it more efficient than calling a method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f456ccbc-b5a9-478f-b799-a24be73d3f67', N'4c000000-0000-0000-0000-000000000005', N'Why use an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point for all clients, handling concerns like authentication, rate limiting, and request routing. It simplifies the client interface and provides a centralized location for cross-cutting service concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbcb8cdf-079a-4b0d-8e18-a24f17b96c21', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi support RESTful API development?', N'Intern', N'Chi supports RESTful design by providing easy access to HTTP methods like GET, POST, PUT, and DELETE. Its routing structure makes it straightforward to map these methods to specific resource endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09d720bd-9eaa-4b0b-bfb1-a25056fd6e83', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the interaction between Actix actors and the ''Stream'' trait.', N'Senior', N'Actors can consume Streams to process asynchronous sequences of messages, allowing them to handle data sources like web sockets or file reads over time. By implementing the StreamHandler trait, an actor can react to every item emitted by a stream without blocking its mailbox.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da91838a-6e5c-40ad-aaf8-a250e5f9692b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a relational database and a NoSQL database?', N'Intern', N'Relational databases are best for structured data with complex relationships where data integrity and ACID compliance are critical. NoSQL databases are preferred for unstructured or rapidly evolving data that requires high horizontal scalability and flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c10bdf57-241d-4e88-a08e-a2529ae34609', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you achieve accessibility with Tailwind CSS?', N'Fresher', N'Tailwind encourages accessibility by providing utilities for screen-reader-only text and standard CSS properties that support accessibility standards. Developers must still follow best practices for ARIA labels and semantic HTML structure alongside their styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ee0d510-0618-4c6f-b26c-a256129785f3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'When should you use a Proxy pattern in Doctrine, and what is its impact on performance?', N'Senior', N'Doctrine uses lazy-loading proxies to instantiate objects only when they are accessed, which avoids loading unnecessary data from the database. This improves initial request performance significantly, though it requires careful management to avoid N+1 query problems when accessing properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b814a853-5133-4521-9d5c-a257767eb7a0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is it considered ''idiomatic'' to use Chi?', N'Middle', N'It is considered idiomatic because it strictly adheres to the standard Go interfaces for HTTP servers. It does not force a proprietary way of writing handlers, meaning Go developers can transition to Chi with virtually no learning curve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5934957c-6526-424b-8030-a257bfead81e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you define a route for a specific HTTP method in Actix-web?', N'Fresher', N'You define routes by using macros or builder methods that specify the HTTP method, such as GET, POST, or PUT, alongside the URL path. These methods bind the request to a specific handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64f310c5-ab44-47a2-bc2d-a258838f59e2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Discuss the trade-offs of using NestJS ''Custom Decorators'' for authentication metadata.', N'Senior', N'Custom decorators provide a clean, declarative way to inject metadata into route handlers, improving code readability. However, excessive use can hide logic from static analysis tools, potentially making it harder for new team members to trace the execution flow of authentication requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4c17ec0-8596-475c-a26b-a259220dac39', N'075b8862-431c-4678-9767-f55359758a4a', N'What are slots in Vue and how do they improve component reusability?', N'Middle', N'Slots are placeholders that allow parent components to inject custom content into a child component''s template. This promotes flexibility, as the child component defines the layout while the parent controls the specific content displayed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'624bf44e-6cb0-429b-97bb-a25a1d903bb7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'In what way does Rocket’s handling of static files differ from traditional Nginx/Apache deployments?', N'Senior', N'Unlike traditional servers that offload static content to reverse proxies, Rocket can serve static files directly with high efficiency due to its asynchronous I/O and zero-copy capabilities. This reduces architectural complexity in simple deployments, though highly loaded systems may still prefer offloading to a dedicated CDN.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c42d32e-bd5b-413d-bd6a-a25c783b377b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the function of the .nuxt directory?', N'Junior', N'The .nuxt directory is a hidden folder generated by the framework that contains the internal build files. You should never modify files inside this folder, as they are regenerated whenever you run the development server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcbafb05-5da0-403c-b2bc-a25d26233ce8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the purpose of ''Form'' and ''File'' data types in FastAPI.', N'Middle', N'These classes are used to handle ''multipart/form-data'' requests, which are typical for file uploads or HTML form submissions. They allow FastAPI to correctly parse and validate non-JSON data types, providing a seamless way to integrate with traditional web forms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b7474da-45f0-4b1d-b7e8-a25f2633f84b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Discuss the scalability of Alpine.js when integrating with complex state management patterns.', N'Senior', N'Alpine.js scales best as a view layer for server-rendered apps, but it struggles with centralized complex state management compared to Redux or Pinia. To scale, one should use Alpine''s global stores to share data across components, though this eventually hits a ceiling where a more formal state architecture becomes necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5f4ae2e-5deb-4721-888c-a2601e697bde', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the significance of the ''package-lock.json'' file in a project?', N'Middle', N'The lock file ensures that the exact versions of dependencies are installed across different environments, including development and production. This prevents ''it works on my machine'' issues caused by minor dependency updates that might introduce breaking changes or bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8360662-a19f-4f37-8a3b-a2602e7a9167', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the distinction between R''s lazy evaluation and eager evaluation?', N'Middle', N'R utilizes lazy evaluation, meaning function arguments are only evaluated when they are actually accessed within the function body. Eager evaluation would require all arguments to be computed before entering the function, which would be less efficient if some arguments are conditionally unused.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77999e35-b51d-4588-8e81-a26077dc2969', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the primary paradigm of Scala?', N'Intern', N'Scala is a multi-paradigm language that seamlessly integrates object-oriented programming and functional programming. It allows developers to use classes and objects for structure while utilizing functions as first-class citizens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f980985f-5447-4f93-9125-a2608faa8e82', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What happens if you use the same variable name in two different modules?', N'Middle', N'If you use the @use rule, variables are namespaced by the filename, preventing collisions even if the names are identical. If you were using the legacy @import rule, the second definition would overwrite the first, which can cause unpredictable bugs in large projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1748469-9a8d-472a-9979-a260b9944d28', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of ''web::Path''?', N'Junior', N'The web::Path extractor is used to capture dynamic segments from a URL path. For example, if you define a route like ''/users/{id}'', the path extractor will allow you to inject the value of ''id'' directly into your handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23875454-4541-435a-a53f-a26144142116', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How can you validate path parameters in FastAPI?', N'Fresher', N'You can use the ''Path'' class to add extra validation to path parameters, such as defining minimum or maximum values. This is similar to how the ''Query'' class validates query parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58d03f03-838c-476e-99ce-a261488d927f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate whether a feature is worth the complexity it introduces?', N'Intern', N'I would assess the feature''s value to the end user versus the cost of implementation and ongoing maintenance. If the complexity outweighs the benefit, I would consider simplifying the feature or omitting it until it becomes necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fc564c9-6237-46b8-8110-a2614b30d9c8', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the concept of technical debt and why does it occur?', N'Intern', N'Technical debt is the implied cost of choosing an easy, quick solution today instead of a better approach that would take longer to implement. It occurs when teams prioritize speed of delivery over long-term code quality, often to meet tight deadlines. If not addressed, this debt makes future updates harder and slower to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06312952-90ff-4078-aa97-a2618daa71b4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte''s ''special elements'' like <svelte:component> provide architectural flexibility?', N'Senior', N'Special elements allow for dynamic UI composition where the component type is determined at runtime. This provides a clean interface for building highly flexible systems like dashboards or CMS-driven layouts while still respecting the framework''s reactive lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'233dfb03-ff6a-45b4-9060-a269786dd205', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the risks of ''Type Assertions'' in a project with strict type requirements?', N'Senior', N'Type assertions provide a way to override the compiler''s inference, which can hide underlying logic errors and bypass intended safety checks. Over-reliance on assertions effectively voids the benefits of TypeScript, turning it into a documentation tool rather than a robust guardrail for application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1112623c-1d70-48f6-a719-a26bf8d77250', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain how C''s ''volatile'' qualifier interacts with compiler optimization and hardware peripherals.', N'Senior', N'Volatile instructs the compiler that the value of an object may change through means outside the program''s control, such as hardware registers or interrupt service routines. It forces the compiler to perform a physical read or write operation every time the variable is accessed, preventing the optimization of redundant loads or stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4981725-35b0-4db1-8f7e-a26c8d3c55b1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of CDI (Contexts and Dependency Injection) in Quarkus?', N'Junior', N'CDI is the foundation of dependency management in Quarkus, allowing for loosely coupled code through bean injection. It manages the lifecycle of objects and provides a standard way to inject services or components into other classes using annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e7c3793-88b8-4cff-8945-a26d558d016d', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does the ''working directory'' signify in R?', N'Intern', N'The working directory is the folder on your computer that R uses as the default location to read and write files. It is important to set this correctly so that R can locate your data files without needing full file paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7e158f9-b890-471d-a3bd-a26f24354068', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you handle key rotation in a distributed system without causing downtime?', N'Senior', N'Key rotation should be implemented using a versioning scheme where the system supports multiple active keys simultaneously during the transition period. The application is updated to support the new key, followed by a phased transition where old keys are decommissioned only after ensuring no traffic is still encrypted with them, typically verified through audit logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e25ebd8c-1fdf-4212-b859-a2707148ec64', N'4c000000-0000-0000-0000-000000000005', N'How does caching help in system design?', N'Middle', N'Caching stores frequently accessed data in memory to reduce the number of expensive database or external API calls. This significantly reduces latency and improves overall system response time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d4bc57-8588-4c76-8947-a27112767876', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why should you consider edge cases when planning a solution?', N'Intern', N'Edge cases represent unusual or extreme scenarios that are often overlooked but can lead to system failures if not handled. Considering them ensures the solution is robust and can handle unexpected inputs or states. Ignoring them usually results in bugs or performance issues once the system is in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c45f9fc9-f592-4622-a76b-a27234dcf599', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why would you use a WSGI middleware in a Flask application?', N'Middle', N'Middleware sits between the web server and the Flask application to intercept and modify requests or responses globally. It is useful for tasks like request logging, handling authentication, or adding security headers. It provides a clean way to apply logic that should affect every request regardless of the specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5101cf5-8bb3-4356-ae9a-a272eafd0c8f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the common MySQL data types?', N'Fresher', N'Common MySQL data types include numeric types like INT, string types like VARCHAR and TEXT, and date-time types like DATE and TIMESTAMP. Each type is chosen based on the nature and size of the data being stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4fe5ea0-3962-49c8-9874-a274fdf97822', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Feature Module?', N'Junior', N'A feature module encapsulates code relevant to a specific feature, such as a ''UserModule'' or ''AuthModule''. This approach helps keep the codebase maintainable by organizing related functionality into self-contained units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a8750a3-497c-445a-a706-a27666989a5a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''selector'' pattern and why is it useful?', N'Middle', N'Selectors are functions that encapsulate the logic for retrieving specific slices of the state tree. Using them promotes decoupling, as components do not need to know the internal structure of the state, only how to call the selector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1d70110-3f5d-4cea-9686-a277e946f77c', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the trade-offs of using a cache as a write-through vs write-back buffer?', N'Senior', N'Write-through caching ensures consistency between the cache and the database but increases write latency because every write must reach the database synchronously. Write-back caching provides high write performance by acknowledging the application immediately, but risks data loss if the cache node fails before syncing to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcde568b-e649-4152-a1f6-a278838bf783', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s ''sideEffects'' flag in package.json improve build outcomes?', N'Senior', N'The sideEffects flag informs Webpack that certain files or packages do not perform any operations outside of exporting values. This allows Webpack to safely skip these files during tree-shaking, even if the static analysis is unsure, resulting in significantly smaller bundles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd82f30d8-8049-4795-9409-a279adaf8dfe', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to use version control systems like Git in a team environment?', N'Intern', N'Version control allows multiple people to work on the same project simultaneously without overwriting each other''s changes. It maintains a complete history of modifications, making it easy to revert to a previous stable state if a mistake is made. It also provides a structured way to review code before it is integrated into the main project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c532abed-4746-46ab-a617-a279ca85c4e3', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the browser rendering engine work?', N'Fresher', N'In order to render content the browser has to go through a series of steps: * Document Object Model(DOM) * CSS object model(CSSOM) * Render Tree * Layout * Paint', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'735f72cb-01b9-4a78-8fdd-a27aa6310b98', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Compare the performance implications of Server-Side Rendering (SSR) versus Static Site Generation (SSG) in a high-traffic e-commerce scenario.', N'Senior', N'SSG provides superior Time to First Byte and scalability since pages are cached on a CDN, making it ideal for product catalogs. SSR is necessary when data is highly dynamic or personalized, though it requires more server resources and increases latency due to per-request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38dcddf1-aabe-4dce-ab6a-a27bfd35f28f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the ''JIT'' compiler in C# performance tuning?', N'Senior', N'The Just-In-Time compiler translates Intermediate Language (IL) to native machine code at runtime, applying optimizations based on the actual CPU architecture. It can inline methods, unroll loops, and perform devirtualization. Understanding JIT behavior is vital because it determines the final performance characteristics that static analysis alone cannot predict.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ad3e855-4826-405d-a951-a27e7adc2578', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary trade-off when choosing Chi over a full-featured web framework?', N'Senior', N'The primary trade-off is the lack of ''batteries-included'' features like built-in ORMs, form validation, or templating engines. While this requires more manual setup, it results in a more flexible and performant architecture that is easier to reason about and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
