INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16ece6f4-dbcd-4d29-91d8-a28a6b9e7376', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of Astro being a ''multi-page application'' framework?', N'Intern', N'Being a multi-page application framework means that Astro typically navigates between pages using standard browser page loads rather than client-side routing. This simplifies the development process, ensures better SEO, and prevents the memory issues often associated with large single-page applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f82ff03f-8703-4b66-9431-a28b0be26301', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do retries and backoff strategies prevent system overload?', N'Middle', N'Retries allow a system to recover from transient errors, but without an exponential backoff, they can overwhelm a struggling service. Backoff strategies introduce delays between retries, giving the downstream service breathing room to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
