INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fff5302-ef61-4f58-b27c-a28dc79654ba', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How does technical debt influence your ability to estimate future tasks?', N'Junior', N'Technical debt slows down development by making the existing system harder to change or extend. I must account for this by adding extra time to navigate or fix the debt, or by recommending a refactor before starting new work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73509a36-748a-4c2d-8a63-a28ec9a5e584', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does the Alpine.js plugin system affect the runtime performance and bundle size of an application?', N'Senior', N'The plugin system is modular, allowing developers to import only the necessary features, which keeps the core bundle size minimal. However, each registered plugin adds overhead to the initialization process as it hooks into the core''s lifecycle events. For large applications, the cumulative impact of multiple plugins can increase the initial script execution time significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
