INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b96733ee-bba9-4d5c-a0ab-a2912d903239', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the risks of a ''Distributed Monolith''?', N'Middle', N'A distributed monolith occurs when microservices are so tightly coupled that they must be deployed together or share a common database. This loses the benefits of independent scalability and deployment, while adding the overhead of network communication and distributed systems complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a611cb6-ec6f-47b1-831e-a2924fc01320', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the performance impact of Preact''s ''async'' rendering mechanism.', N'Senior', N'Preact batches state updates and performs them asynchronously to avoid multiple layout thrashing cycles, which ensures that complex UI updates are rendered in a single frame. This prevents unnecessary DOM writes, significantly improving performance in components that trigger multiple state updates in quick succession.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de968ca6-8394-4208-aa63-a292ee736fb1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Read Repair'' function in Cassandra to maintain data consistency?', N'Senior', N'Read repair is an anti-entropy mechanism that compares data versions from multiple replicas during a read request when the consistency level is less than ''ALL''. If the system detects inconsistencies, it returns the most recent version to the client and asynchronously triggers updates to the out-of-date replicas to bring them into alignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54a13767-210a-4903-a511-a2932e844ab0', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle user interactions like clicks?', N'Junior', N'Alpine.js uses the x-on directive, often shortened to the @ symbol, to listen for browser events. When the specified event occurs on the element, it executes the provided JavaScript expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9ee6628-f1ff-4bfc-8362-a296f7c2d3d4', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the core difference between SolidJS and React in terms of how they handle updates?', N'Junior', N'React uses a Virtual DOM and re-renders the entire component tree when state changes. SolidJS uses fine-grained reactivity, meaning it updates only the specific parts of the DOM that depend on a changing signal without re-running the component function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d59b058-687c-48b9-bf5a-a2988bda170c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel manage session state in a stateless architecture like a REST API?', N'Senior', N'In a stateless REST API, sessions are typically disabled, and authentication is handled via stateless mechanisms like JWT or Sanctum tokens. If session state is required, it must be offloaded to a shared store like Redis to ensure consistency across multiple server nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d9eee1b-61db-46b3-947a-a29aa3e556f3', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is type assertion in Go?', N'Junior', N'Type assertion is a process used to extract the concrete value stored inside an interface. It checks if the underlying value of the interface matches the specified type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57e9f7c6-5beb-4431-a4af-a29c92bfd22b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between shallow and deep copying, and why is this relevant to object design?', N'Middle', N'A shallow copy duplicates the object''s reference fields, meaning both objects point to the same underlying data, which can lead to unintended side effects if the data is mutable. A deep copy recursively duplicates all referenced objects, ensuring total independence between the original and the clone, which is critical for maintaining encapsulation and preventing data corruption in complex object graphs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'718d99b3-5cb6-44dc-9b1c-a29e0a036bc0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How JSX prevents Injection Attacks?', N'Fresher', N'React DOM escapes any values embedded in JSX before rendering them. Thus it ensures that you can never inject anything that’s not explicitly written in your application. Everything is converted to a string before being rendered. For example, you can embed user input as below, This way you can prevent XSS(Cross-site-scripting) attacks in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cbef512-53d1-40b9-aa56-a2a032653691', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the significance of the ''Reachability Metadata'' in GraalVM native builds for Quarkus apps.', N'Senior', N'Reachability metadata tells the native compiler which classes and methods are actually needed by the application, effectively pruning unused code. This is essential for keeping the binary size small and ensuring that the final executable contains only the necessary dependencies and logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f667268-8b66-47c5-9ce4-a2a1947dfc83', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What considerations are necessary when designing an API for mobile devices versus web clients?', N'Senior', N'Mobile APIs must prioritize bandwidth efficiency, battery usage, and network resilience, often favoring smaller payloads and fewer round-trips. Web APIs can leverage broader browser caching capabilities and often handle larger, more structured JSON payloads without the same level of concern for device resource constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba23fe87-0d74-4bd3-8334-a2a25b8d0889', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Is it possible to pass data from middleware to handlers in Chi?', N'Junior', N'Yes, you can pass data by using context.WithValue to store values in the request context within your middleware. You then retrieve these values in your handler using the context stored in the request object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6f70e4a-d60e-4328-9e4a-a2a2a70e67db', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a header file in C and why is it used?', N'Fresher', N'A header file, typically ending in .h, contains function declarations, macro definitions, and data type definitions. It is used to share these definitions across multiple source files, allowing the compiler to know the signatures of functions used in different parts of a program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd651bf51-95db-4e39-9683-a2a31020924d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing for extensibility, what techniques do you use to ensure the system can support future requirements?', N'Middle', N'I adhere to design principles like dependency injection and the open-closed principle to keep modules loosely coupled. I also favor composition over inheritance and use interfaces to define clear boundaries between components. This architecture allows me to add new functionality by plugging in new modules rather than modifying existing, stable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52dad368-1b34-45f4-ab0e-a2a65e6b7ebe', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do Sets and Maps handle equality checks for objects?', N'Fresher', N'Sets and Maps in JavaScript handle equality checks for objects based on reference equality, not deep equality. This means that two objects are considered equal only if they reference the same memory location. For example, if you add two different object literals with the same properties to a Set, they will be treated as distinct entries. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
