INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4247dc4f-3c66-4878-8d73-a2adcb7ea366', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why might you choose to use ''delegation'' over ''inheritance'' in Rails models?', N'Senior', N'Inheritance (like Single Table Inheritance) can lead to bloated database tables with many sparse columns and rigid class hierarchies. Delegation (via the delegate pattern) favors composition, allowing objects to maintain cleaner interfaces and better separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33e0ad0e-0ad6-4211-a351-a2ae06246093', N'075b8862-431c-4678-9767-f55359758a4a', N'Compare the ''Options API'' and ''Composition API'' from an architectural scalability perspective.', N'Senior', N'The Options API organizes code by component property, which can lead to fragmented logic as components grow in complexity. The Composition API encourages organizing code by feature or concern, promoting better reusability through composables and making it easier to maintain large, logic-heavy components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
