INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6de42bcd-7658-4e86-824f-a2b0f73a7577', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If you are designing a system to track a user''s location, would you use a relational database or a time-series database?', N'Fresher', N'I would choose a time-series database because location tracking involves a high volume of data points indexed by time. Time-series databases are optimized for this specific pattern of high-frequency writes and time-based range queries, making them much more efficient than a standard relational database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08f8cb1f-5741-45d4-a83e-a2b3211eb934', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the advantages of Getters and Setters', N'Intern', N'Below are the list of benefits of Getters and Setters, 1. They provide simpler syntax 2. They are used for defining computed properties, or accessors in JS. 3. Useful to provide equivalence relation between properties and methods 4. They can provide better data quality 5. Useful for doing things behind the scenes with the encapsulated logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'747ca09f-cba4-4a6a-9f57-a2b3cabdb71d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the trade-off of Preact''s synchronous execution regarding UI responsiveness?', N'Senior', N'Synchronous execution ensures that all updates are handled immediately, which creates a very responsive UI for standard applications. However, if a component tree is excessively deep or complex, this synchronous blocking behavior can lead to dropped frames, as the main thread cannot be yielded until the entire render cycle completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c59c53f-10fb-4cfd-a7e2-a2b55c0eaf96', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might a designer choose to cache data instead of fetching it from the database every time?', N'Intern', N'Caching reduces latency and lowers the load on the primary database, leading to faster response times for the user. It is highly effective for frequently accessed data that does not change very often.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'910ce889-e794-434e-9d82-a2b8fa622b31', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''N+1'' query problem and how does it affect scalability?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a list of items and then executes an additional query for each item to fetch related data. This pattern creates excessive database load and network latency, preventing the system from scaling effectively under higher request volumes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7553e3e-2fbc-42c3-84e6-a2b9f8700910', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does ''clean state'' mean when reproducing a bug?', N'Fresher', N'A clean state means starting the application from a default configuration, without cached data, temporary files, or previous user sessions. This ensures that the bug is caused by the application logic and not by leftover data from a previous run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac4910fe-efbd-4e88-991f-a2bbb97d4c3a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of ''Data Denormalization'' in search-indexed architectures?', N'Senior', N'Denormalization in search-indexed architectures pulls data from multiple relational tables into a single document-like structure to avoid performing expensive joins at query time. This pre-joining allows the search engine to perform high-speed full-text searches and filtering operations on a single record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae99a503-b585-41ad-ae91-a2bc49f7c305', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is Declaration Merging and when does it occur?', N'Middle', N'Declaration merging is the process where the compiler merges multiple declarations with the same name into a single definition. It specifically occurs with interfaces, namespaces, and enums, allowing developers to extend existing types from third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'975b43f5-30a4-4340-894c-a2be25ed2217', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are aggregate functions in PostgreSQL?', N'Fresher', N'Aggregate functions are used to perform calculations on a set of values and return a single scalar result. Common examples include COUNT, SUM, AVG, MIN, and MAX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9908ec43-c172-40af-9fdf-a2be8437fba2', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle state management across concurrent requests?', N'Senior', N'Litestar provides a ''State'' object that facilitates the sharing of data across the application lifecycle. While thread-safety depends on the underlying ASGI server, Litestar encourages using this object for immutable configuration and shared resources that are injected into handlers, ensuring clean separation of state and execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b49df002-9337-462d-afdf-a2c06aab4c84', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are ''locals'' in the Fiber context?', N'Intern', N'Locals are a way to store data in the request context that needs to be passed between multiple middleware or handlers. It is a convenient way to share information like user IDs or database handles throughout a single request''s lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd42b9c5b-69e6-4394-88bf-a2c0e03902e4', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is ''Eventual Consistency'' acceptable for some systems but not for others?', N'Senior', N'Eventual consistency is acceptable for systems where high availability and low latency are prioritized, and where temporary stale data does not cause business harm, such as social media feeds. It is unacceptable for financial or inventory systems where strict correctness is mandatory to prevent double-spending or overselling. The choice depends entirely on the business requirements for accuracy versus performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69a2c190-5fa4-4570-a77f-a2c4db196fa3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the significance of the ''readonly'' modifier in interfaces?', N'Middle', N'The ''readonly'' modifier prevents a property from being reassigned after initial assignment. It helps enforce immutability in your application state and prevents accidental side effects where data might be mutated unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
