INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'194676d4-606a-4348-bc05-a2c6fc1c2004', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does the ''combineReducers'' function do?', N'Intern', N'It is a helper utility that allows you to split your root reducer into smaller, manageable functions, each responsible for a specific slice of the state. It then combines them into a single root reducer that the store can use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11271ca1-8581-4683-9045-a2c899eba214', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between Pessimistic and Optimistic locking in transaction management?', N'Middle', N'Pessimistic locking assumes conflict is likely and prevents it by locking records at the start of a transaction, ensuring data integrity but reducing concurrency. Optimistic locking assumes conflict is rare, allowing multiple transactions to proceed without locks and only checking for data modification conflicts at the time of commit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64a2fbea-ea1b-4771-aa85-a2cc5fd97aef', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of an ASGI server in running a FastAPI application?', N'Fresher', N'FastAPI is an ASGI framework, meaning it requires an ASGI server like Uvicorn or Hypercorn to run. The ASGI server acts as the interface between the web server and the application, translating incoming HTTP requests into a format the application can process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
