INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ee942e0-de71-4a47-ae8f-a2e13c98b2de', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery considered less essential in modern frontend development compared to its peak popularity?', N'Junior', N'Modern vanilla JavaScript has evolved significantly, incorporating native methods like querySelector and fetch that replace most jQuery functionality. Additionally, modern frameworks like React and Vue manage the DOM more efficiently through virtual DOM systems, making the direct manipulation approach of jQuery less performant and harder to scale in complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1724a495-76b6-4a09-aa2d-a2e37c538287', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono require a specific build tool?', N'Fresher', N'Hono does not strictly require a specific build tool, but it is often used with modern bundlers like Vite. Because it is written in TypeScript and designed for modern environments, it works seamlessly with standard JavaScript development workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'446aff41-e0a7-45d1-a7a6-a2e69fb285a9', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the limitations of Express''s built-in ''body-parser'' when handling large payloads, and how should it be mitigated?', N'Senior', N'The built-in parser buffers the entire request body into memory, which can lead to OOM errors with large files or malicious payloads. Mitigation involves using streaming parsers or middleware that restricts payload size and processes data as a stream rather than loading it entirely into RAM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6d24c58-2f83-4f0d-838c-a2e6a8c0ec0a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the difference between Lit''s reactive properties and standard JavaScript getters/setters.', N'Senior', N'Lit''s reactive properties integrate directly into the component lifecycle, automatically triggering an update cycle when values change. Standard getters and setters lack this built-in connection to the rendering pipeline, requiring manual calls to request an update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82a9e95b-a7f6-4e28-a3c5-a2e87ccf2a57', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the primary purpose of the Event Loop in Node.js?', N'Junior', N'The Event Loop allows Node.js to perform non-blocking I/O operations despite JavaScript being single-threaded. It offloads operations to the system kernel whenever possible and executes callbacks when tasks are completed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3eae149a-3596-47c9-a3dc-a2e93ad8b67d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Describe the lifecycle of a request in Echo and where you would best inject performance instrumentation.', N'Senior', N'The lifecycle proceeds from the server listener to middleware, then the router, and finally the handler, before returning back through the middleware stack. Instrumentation is best placed at the very start of the middleware chain for latency tracking and just before the response is sent to capture the full request duration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fd6b040-42e4-4de8-9c9a-a2f037ed37f1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Analyze the impact of ''TCO'' (Tail Call Optimization) and why it is not universally implemented in all engines.', N'Senior', N'TCO allows recursive functions to execute without growing the stack, enabling memory-efficient recursion. However, implementing it consistently is difficult because it requires preserving stack trace information for debugging and error reporting, which is often lost when frame consolidation occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a39971b0-91ca-4bd5-9753-a2f44d27d100', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the $: label in Svelte, and how does the compiler process it?', N'Senior', N'The $: label denotes reactive declarations that re-run whenever their dependencies change. The compiler tracks these dependencies and wraps the associated code in an update function that is triggered only when the relevant state variables are modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
