INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9b21a43-f330-4706-9547-a2fc3565fd76', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is Alpine.js considered a ''zero-build'' or ''minimal-build'' tool and what are the trade-offs for production pipelines?', N'Senior', N'Alpine.js can be dropped in via script tag, enabling rapid development without complex build steps. However, in production, this prevents tree-shaking and bundle optimization, forcing the inclusion of the full library even if only a fraction of its directives are utilized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19e7bf0e-3be6-4456-9a7f-a2fcf0a2250b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle the serialization and deserialization of request bodies?', N'Senior', N'Rocket uses the Serde framework to perform type-safe conversion between raw request bodies and strongly typed structures. This happens automatically based on the handler''s signature, ensuring that invalid input is rejected early with appropriate HTTP status codes, thus shielding business logic from malformed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
