INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe1732f6-ee20-42dc-876b-a30a879967b6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do you need strict mode', N'Fresher', N'Strict mode is useful to write "secure" JavaScript by notifying "bad syntax" into real errors. For example, it eliminates accidentally creating a global variable by throwing an error and also throws an error for assignment to a non-writable property, a getter-only property, a non-existing property, a non-existing variable, or a non-existing object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'daf32aa9-f148-44b7-be69-a30b302c951e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the Option type in Scala?', N'Intern', N'The Option type is a container used to represent the presence or absence of a value. It prevents null pointer exceptions by forcing developers to explicitly handle cases where a value might be missing, using either Some or None.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea1225c3-8978-405c-93a8-a30f3f853873', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core handle CORS?', N'Fresher', N'Cross-Origin Resource Sharing (CORS) is a security feature that allows a server to specify which origins are permitted to access its resources. In ASP.NET Core, CORS is configured as a middleware service that checks the origin header of incoming requests against a defined policy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c49d704d-bc8b-4f96-9b34-a30ff1ba3e74', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the architectural risks of the ''Diamond Problem'' in multiple inheritance.', N'Senior', N'The diamond problem occurs when a class inherits from two classes that both inherit from a common base, potentially leading to multiple instances of the base class within the final object. This causes ambiguity in member access and potential memory corruption; C++ resolves this using virtual inheritance, which creates a shared, single instance of the common base class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
