INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ff628f4-ac4e-4cce-b723-a33438cb648e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to support real-time user notifications at a scale of millions of users?', N'Senior', N'I would use a pub-sub architecture with dedicated worker pools to manage the fan-out of messages to notification providers. To maintain low latency, I would use a high-throughput message broker and optimize the notification delivery path to be asynchronous, offloading the heavy lifting from the main request flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
