INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dd2281c-e16d-4c8e-ab01-a3662fb780f5', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why would you choose Hono over a more mature framework for a new project?', N'Junior', N'You would choose Hono for its performance, small size, and ability to run anywhere. It is an excellent choice for modern cloud-native applications that prioritize low latency and minimal cold-start overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'666ac6e6-1ee4-414a-9aa7-a36a10de81c9', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is the ''Fat Model, Skinny Controller'' pattern often criticized in modern, large-scale Rails applications?', N'Senior', N'As applications grow, models become bloated with too many responsibilities, violating the Single Responsibility Principle. Modern architecture favors extracting domain logic into Service Objects, Use Case classes, or Operation objects to keep the models focused strictly on data persistence and basic validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f2e10e9-cc30-459b-9a04-a36ca9dc89e5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of ''keyof'' and ''typeof'' operators?', N'Middle', N'''Keyof'' creates a union type of all property names of an object, while ''typeof'' extracts the type of a variable or property. Using them together allows you to create highly dynamic and type-safe code that automatically updates when the underlying data structures change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7699191-f075-4bbc-9d3d-a36d3d27bf84', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a primary key in a NoSQL database?', N'Junior', N'A primary key is a unique identifier used to access a specific record or document within the database. It is essential for efficient data retrieval, as it allows the database to quickly locate the exact storage partition where the requested data resides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c04dcad2-03a1-430b-933a-a36e1d7b4e8a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering error handling, what is the trade-off between failing fast and attempting a retry?', N'Junior', N'Failing fast prevents the system from wasting resources on doomed operations and provides immediate error feedback to the user or system. Retrying operations can recover from transient network issues, but it can also overwhelm a struggling service if not managed with strategies like exponential backoff.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
