INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ceb8ef1-d8a8-4653-9b60-a376409e89f4', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does it mean for a Swift type to be a ''Value Type''?', N'Fresher', N'A value type is a type whose value is copied when it is assigned to a variable or constant, or when it is passed to a function. This ensures that each instance has its own unique data, preventing unintended side effects from changes made elsewhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69087eda-539d-476a-8e17-a37ecb443ad8', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''{#each}'' block?', N'Junior', N'The ''{#each}'' block is used to iterate over arrays or iterable objects to render a list of elements. It automatically updates the list in the DOM whenever the underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
