INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5f64d84-188c-4322-b4ad-a388daaa2915', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does the term ''in-memory'' mean in the context of Redis?', N'Fresher', N'In-memory means that the primary dataset is stored in the server''s RAM instead of on a hard drive or solid-state drive. Because accessing data from RAM is significantly faster than reading from disk, Redis can perform operations in microseconds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0094fbc7-df71-40d7-97d0-a38a42c68e39', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does the ACID acronym stand for in the context of relational databases?', N'Junior', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, guaranteeing that either all operations in a transaction succeed or none do, and that the database remains in a valid state even in the event of a system failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
