INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fe85e62-0af8-4646-9b8e-a38ca3805a70', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When dealing with a bottleneck in a distributed system, what is your diagnostic hierarchy?', N'Senior', N'First, analyze resource utilization metrics like CPU, memory, and disk I/O to check for hardware saturation. Next, examine network latency and connection pooling limits, followed by application-level profiling to identify inefficient algorithms or database query patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a885b1a-a324-4d1e-8ce2-a38db26ec837', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s Copy-on-Write optimization work for collection types?', N'Middle', N'Copy-on-Write ensures that copying a collection is initially cheap by sharing the underlying storage between the original and the new instance. A deep copy is only performed if one of the instances is modified, minimizing unnecessary memory allocation and performance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
