INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9989a634-f70c-4597-9ec7-a38e10e77b19', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are indexes in MongoDB, and why are they used?', N'Intern', N'Indexes are employed in MongoDB to optimize database queries by providing faster access to data. Without indexes, MongoDB performs full collection scans. Common Types of Indexes in MongoDB - Single Field Index: The most basic form of index. - Compound Index: Generated across multiple fields; used for queries involving these fields. - Multikey Index: Specially designed for arrays or embedded documents. Batch Insert Operations on an Indexed Collection Describe any performance bottlenecks you anticipate. - Text Index: Suited for text searches, often leveraging stemming and stop words. Unique Explain in which situations it''s beneficial to manage a unique index. Discard icon GEO Index Describe the purpose of this index type and the type of queries it can optimize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f543d342-acfb-4da6-9e4c-a38ec6941007', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What strategies do you use to ensure high availability for a database cluster?', N'Middle', N'I would configure the database with a primary-replica architecture with automatic failover capabilities. I ensure that backups are taken regularly and tested for restoration, and I use multi-region replication if the service requirements mandate protection against regional cloud provider outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df21c604-44bd-45da-bd47-a38fd5152354', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a database user and a database role?', N'Intern', N'A database user is an account used to authenticate and connect to the database. A role is a collection of permissions that can be assigned to multiple users to simplify access management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9f8e214-1245-453d-95d7-a39503aeec78', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle write availability during a primary node failure?', N'Middle', N'When a primary node fails, the remaining nodes in the replica set hold an election to promote a secondary node to primary. During this short election window, the replica set cannot accept writes, but it resumes once the new primary is elected and ready to process operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1de6268f-86e8-4d2f-ad03-a3958d274a0e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the ''Startup'' class versus the ''Program'' class in modern ASP.NET Core versions?', N'Senior', N'In newer versions, the distinction has been blurred by the minimal hosting model, where the Startup class is often merged into the Program file. This simplifies the entry point by centralizing configuration, service registration, and middleware pipeline definition in a single, fluent builder pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc9781e2-d49c-45cf-9c58-a3967e36680a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery simplify DOM manipulation?', N'Fresher', N'jQuery provides intuitive methods to select, change, add, or remove HTML elements. It hides the complexity of standard JavaScript DOM methods, reducing the amount of code needed to perform tasks like changing styles or updating content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63b82539-f982-486c-92a8-a396dd32b86e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is Hono''s RPC mode?', N'Fresher', N'Hono''s RPC mode allows developers to share type definitions between the backend API and the frontend client. This enables the frontend to have full autocompletion and type checking for API routes, reducing integration errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73dadef9-fd58-44bf-bf21-a39822dda10b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Enums versus Const Enums?', N'Fresher', N'Regular enums are preserved as objects in the generated JavaScript, whereas const enums are completely erased during compilation. Const enums are more efficient because they inline the values directly into the code where they are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c6aa790-2ed9-4f11-be20-a398b7ccba48', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is reconciliation?', N'Intern', N'Reconciliation is the process through which React updates the Browser DOM and makes React work faster. React use a diffing algorithm so that component updates are predictable and faster. React would first calculate the difference between the real DOM and the copy of DOM (Virtual DOM) when there''s an update of components. React stores a copy of Browser DOM which is called Virtual DOM. When we make changes or add data, React creates a new Virtual DOM and compares it with the previous one. This comparison is done by Diffing Algorithm. Now React compares the Virtual DOM with Real DOM. It finds out the changed nodes and updates only the changed nodes in Real DOM leaving the rest nodes as it is. This process is called _Reconciliation_.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0b64c7c-d34b-4116-9f1f-a3997868addd', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''important'' configuration option in Tailwind?', N'Junior', N'The ''important'' option in the config file adds an !important flag to all utility classes. This is generally used as a last resort when integrating Tailwind into a legacy project where existing CSS has high specificity that needs to be overridden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46ff7cac-60bf-4423-8eb5-a39997e886aa', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you define a ''done'' task in an engineering context?', N'Junior', N'A task is done when it meets the agreed-upon acceptance criteria, has passed all necessary tests, and is reviewed by another team member. It should also be documented where necessary and ensure that no obvious technical debt is left behind.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8666833-99f6-40db-bea2-a39cb9a4c0ea', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS keep the final production CSS file size small?', N'Intern', N'Tailwind uses a tool called PurgeCSS that scans your HTML or template files for class names. It then removes all unused CSS from the final build, resulting in a very small file size for production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be809320-a6c9-4b1c-a289-a39cebfa61bf', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify ensure that plugin registration order is respected?', N'Middle', N'Fastify uses a dependency-aware loading mechanism that respects the order in which plugins are registered. This ensures that if a plugin depends on a decorator or service provided by another, the requirement is satisfied before the dependent plugin executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'946356d4-1c82-47ba-8164-a39fa3404e08', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If your service''s memory usage is constantly increasing, what steps do you take to debug the leak?', N'Middle', N'I would take a heap dump of the running process to analyze object allocation patterns and identify long-lived objects that are not being garbage collected. I would also review recent code changes for potential issues like unbounded cache growth or unclosed resources that might be preventing memory reclamation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc5c899d-338d-4341-9641-a3a1c3139bdf', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is meant by ''diffing'' in Preact?', N'Intern', N'Diffing is the reconciliation process where Preact compares two versions of the virtual tree to identify exactly what has changed. By only applying the necessary updates to the actual browser DOM rather than re-rendering everything, Preact optimizes performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbba2a4a-bc72-4257-9043-a3a5c28cf8aa', N'4c000000-0000-0000-0000-000000000005', N'How does database indexing improve read performance?', N'Middle', N'Indexing creates a separate data structure, like a B-tree, that allows the database to locate rows without scanning the entire table. While it speeds up reads, it introduces overhead for write operations because the index must also be updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc804975-9b06-455d-9469-a3a6543548ba', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''Object Header'' in the JVM and why does it affect memory footprint?', N'Senior', N'The object header contains metadata such as the mark word for locking information and the class pointer for type identification. In systems with many small objects, this overhead can occupy a significant percentage of total heap memory, often mitigated by compressed oops (ordinary object pointers).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93f63253-6dd1-4888-bac1-a3a6c5c75820', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of using environment variables to store configuration settings instead of hardcoding them?', N'Fresher', N'Hardcoding configuration values like database URLs or API keys makes the application inflexible and insecure. Environment variables allow you to change settings based on the deployment environment, such as development or production, without modifying the code. This practice promotes better security by keeping sensitive credentials out of the source code repository.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae7081e-4fce-4ce6-9145-a3a7d90ae82b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Are Go strings mutable?', N'Fresher', N'No, strings in Go are immutable, meaning their content cannot be changed once created. Any operation that appears to modify a string actually creates a new string in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b80eba7-ddaa-4989-a77d-a3a90719cb28', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does a ''Read-Only'' transaction differ from a standard transaction?', N'Middle', N'Read-only transactions do not modify data, allowing the database to optimize by skipping write-locks or logging overhead. In systems using MVCC, read-only transactions can safely access older versions of data without impacting the performance of active write transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97bc1e36-3fae-4498-9d32-a3aa69aae828', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of rate limiting in a public-facing API?', N'Middle', N'Rate limiting protects system reliability by restricting the number of requests a user can make within a specific timeframe. This prevents resource exhaustion from spikes in traffic, malicious attacks, or buggy client-side code, ensuring fair usage for all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd23f9d5-c95d-4f18-8792-a3aa82862252', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of a metaclass in Python?', N'Middle', N'A metaclass is the class of a class, defining how a class behaves and is constructed. It allows developers to intercept class creation, automatically register classes, or modify class attributes dynamically at the time the class is defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4091ad00-a991-4763-aef4-a3ae1e058ac1', N'075b8862-431c-4678-9767-f55359758a4a', N'Describe the mechanism behind ''Teleport'' and its impact on component architecture.', N'Senior', N'Teleport decouples a component''s logical placement from its visual rendering in the DOM tree. This allows developers to maintain clean, modular parent-child relationships while rendering elements like modals or tooltips at the root level to avoid CSS z-index and overflow clipping issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da5b62a3-eaf8-49fb-af23-a3ae24100616', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How are event listeners handled in Qwik before the code is loaded?', N'Junior', N'Qwik uses global event delegation. It attaches a small, lightweight listener to the document that captures events and then fetches the corresponding lazy-loaded code chunk to handle the interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2573f8e2-c32f-4ac1-a3e4-a3aea4f8e513', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a ''circuit breaker'' in Elasticsearch?', N'Junior', N'A circuit breaker is a safety mechanism that monitors memory usage and prevents operations that would cause an out-of-memory error. If a request consumes too much memory, the circuit breaker interrupts the operation and returns an error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4ac152-b5d8-4158-949c-a3afa868d648', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of middleware in Redux and when would you use it?', N'Middle', N'Middleware provides a third-party extension point between dispatching an action and the moment it reaches the reducer. It is primarily used for handling asynchronous operations like API calls, logging, crash reporting, or routing, allowing you to intercept actions before they are processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fcfd105-13e9-458f-b736-a3b04d0dc065', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a dangling pointer and how is it created?', N'Middle', N'A dangling pointer is a pointer that points to a memory location that has already been deallocated or freed. It is created when memory is freed but the pointer is not set to null, leading to potential crashes or data corruption if the program attempts to access the invalid memory address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd01e71f1-5e84-4333-a0ff-a3b379831939', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''Result'' class improve error handling in Kotlin?', N'Middle', N'The Result class encapsulates a successful value or an exception, allowing functions to return a single type that represents the outcome of an operation. It encourages explicit handling of both success and failure states, reducing the reliance on throwing and catching exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddd4ed8d-ecba-49a7-8e52-a3b541af9d91', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s routing work for static pages?', N'Middle', N'Astro uses file-system-based routing, where the structure of the src/pages directory directly maps to the site''s URL structure. This makes it intuitive to manage and scale navigation without needing complex routing configuration files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e8ec71-efef-4ffc-9268-a3b6993ec604', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How can you implement cross-origin resource sharing (CORS) in Rocket?', N'Senior', N'CORS is typically implemented in Rocket using a Fairing that intercepts responses to add the appropriate Access-Control headers. By placing this logic in a Fairing, you ensure that CORS policies are applied uniformly to all routes, maintaining architectural consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec3bc406-ea5d-4423-8352-a3b8fc9f80a9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary purpose of the jQuery wrapper function?', N'Fresher', N'The jQuery wrapper function, represented by the dollar sign, is used to select HTML elements from the DOM and wrap them in a jQuery object. This object provides access to a variety of methods that make it easier to manipulate or style the selected elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0df5f672-1a1f-4e2f-a380-a3ba97b58b09', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary advantage of using MongoDB over a SQL database?', N'Fresher', N'The main advantage is flexibility. MongoDB allows developers to store evolving data structures without the need for complex schema migrations, which is particularly useful for rapid development and handling unstructured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94719435-41e9-4fff-b384-a3bab626b6c6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle data durability compared to traditional RDBMS?', N'Middle', N'MongoDB ensures durability by writing data to an on-disk journal before applying changes to the data files. This allows the system to recover to a consistent state in the event of a crash, similar to the write-ahead logging used in many RDBMS systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
