INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'458b32f5-c96c-427e-8b41-a3ec8b4e8cd7', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a configuration object in Flask?', N'Intern', N'A configuration object is used to store settings for a Flask application, such as database credentials or secret keys. It allows developers to manage different environments, like development and production, by switching configuration files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd699e87-0203-43cf-9a67-a3ecc2e18c3d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a polling-based mechanism and a push-based mechanism for event notification?', N'Middle', N'Polling is easier to implement and provides better control over load but is inefficient and introduces latency. Push mechanisms like Webhooks or WebSockets are real-time and efficient but require more complex infrastructure to handle connection management and reliable delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5667cde0-37a1-4e17-85ad-a3ed18e4a4bb', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS support CSS variables?', N'Fresher', N'Yes, Tailwind fully supports CSS variables. You can define them in your theme configuration or use them directly in arbitrary values to make your styles more dynamic and maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31da3f5c-7113-44ee-b30c-a3ed5f270be5', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Describe the purpose of a ''Database Transaction'' and the ACID properties.', N'Middle', N'A transaction is a single logical unit of work that ensures data integrity through ACID properties: Atomicity (all or nothing), Consistency (valid state transitions), Isolation (independent execution), and Durability (permanent results). These properties ensure the database remains reliable even during failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb55ea8a-659a-487f-af22-a3f021608427', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the performance implications of ''Prefetching'' in Nuxt?', N'Middle', N'Prefetching downloads the JavaScript and data for links currently in the viewport, which makes subsequent navigation feel instantaneous to the user. While this creates a better user experience, it can increase bandwidth usage, so Nuxt allows developers to selectively disable it for specific links.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcea0094-7eb4-49f8-bc1e-a3f29e5f4fb7', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''effectScope'' API in Vue 3?', N'Senior', N'EffectScope allows developers to group reactive effects, such as watchers or computed properties, and dispose of them simultaneously. This is essential for managing memory in complex applications, particularly when creating dynamic composables that need to be cleaned up to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b973eeb-23b8-434a-81a1-a3f376b4bb97', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the advantages of using a ''Command Query Responsibility Segregation'' (CQRS) pattern with transactions?', N'Senior', N'CQRS separates read and write models, allowing them to be optimized independently for different workloads. This improves scalability by allowing the write side to handle complex ACID transactions while the read side serves data from highly optimized, eventually consistent materialized views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7dacf1f-3c50-4b49-b6b1-a3f4935ccd00', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the trade-offs of using utility-first CSS compared to semantic class naming?', N'Middle', N'Utility-first CSS offers rapid development and prevents the need to invent naming conventions for every element, leading to a smaller total CSS footprint. However, it can lead to cluttered HTML templates and may make global design changes more difficult if the design system isn''t well-defined in the configuration, whereas semantic naming keeps HTML clean but often results in larger, harder-to-maintain stylesheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'814f801f-a073-47df-b7a2-a3f5d6c9e0ce', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ''Ownership'' and ''Borrowing'' in the context of Swift''s performance.', N'Senior', N'Ownership and borrowing are mechanisms that define which part of the code is responsible for a value''s lifetime and how it is accessed. By allowing functions to ''borrow'' a value rather than taking ownership, Swift avoids unnecessary copies and reference counting updates. This minimizes the performance cost of passing complex data structures through deep call stacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee4502c-fa27-40ac-850f-a3f62d7849b0', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is Redux DevTools and why is it useful?', N'Junior', N'Redux DevTools is a browser extension that provides a visual interface for debugging Redux applications. It allows developers to track action history, inspect the state at any point in time, and even ''time travel'' by replaying or undoing actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb1d7c1b-d56c-409a-a659-a3f6479ee9ca', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What does the @mixin directive require to function?', N'Intern', N'A mixin requires a definition using the @mixin keyword followed by its name, and it must be explicitly included in the desired location using the @include directive. Without the @include call, the code inside the mixin will not be rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55d0b982-36a3-49fe-98c7-a3f7ce05f1d1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is ''Eventual Consistency'' often chosen for distributed systems?', N'Middle', N'Eventual consistency is chosen to maximize availability and throughput by allowing nodes to respond to requests without waiting for global synchronization. It assumes that as long as updates propagate to all replicas over time, the system will eventually settle on a consistent state, which is sufficient for many high-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3df54c8-78c4-490a-9d2c-a3fb7d6f7ce9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a segmentation fault and why does it occur?', N'Junior', N'A segmentation fault occurs when a program attempts to access a memory location it is not allowed to reach or is not currently allocated. Common causes include dereferencing a null pointer or accessing an array out of its defined bounds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce40ad28-da18-4755-bcca-a3fb7e5967e7', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between props and internal state?', N'Intern', N'Props are values passed into a component from the outside, typically from a parent, while internal state refers to variables defined within the component that track its own data. Internal state is managed by the component itself, whereas props are considered read-only from the child''s perspective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17c042db-232c-4041-9c52-a3febbafa0dd', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Does Elasticsearch support data types like dates and numbers?', N'Fresher', N'Yes, Elasticsearch supports a wide range of data types including text, keyword, dates, various numeric types, booleans, and geographical points. This allows for flexible storage and precise query operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12a3712b-ef23-46ef-9514-a3ff5236dd63', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle component styling?', N'Fresher', N'Svelte provides scoped styling by default, meaning any CSS written inside a component only applies to the elements within that specific component. The compiler automatically generates unique class names to prevent style leakage or conflicts with other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03343b56-4518-480d-a8aa-a4039d800903', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does MySQL''s query optimizer decide whether to use an index?', N'Middle', N'The optimizer uses statistics about the table, such as cardinality and data distribution, to estimate the cost of different execution plans. It chooses the path with the lowest estimated cost, considering index efficiency and the overhead of scanning the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c9b3832-b6e0-4ba0-bef9-a406f1513d93', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between a search query and a filter?', N'Fresher', N'A search query calculates a relevance score to determine how well a document matches the criteria. A filter checks for a true/false match without calculating a score, which makes it faster and more cache-friendly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b2ef676-1822-4633-8409-a407a07df314', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a lost update anomaly?', N'Fresher', N'A lost update occurs when two transactions read the same data, calculate a new value, and write it back, with the second transaction overwriting the first one. This results in the changes made by the first transaction being lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b81990c6-e88b-4f36-9626-a408c7097eb6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you weigh the trade-offs between implementing a cache versus optimizing the underlying database query?', N'Senior', N'Database optimization is the first priority because it addresses the root cause and reduces operational load on the storage engine. Caching is a secondary strategy used to reduce latency for read-heavy workloads or to protect the database from extreme spikes, but it introduces the complexity of cache invalidation and potential data staleness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
