INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eae7da4-2502-4f40-9db7-a40b69c8599d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the primary purpose of the Kestrel web server in ASP.NET Core?', N'Fresher', N'Kestrel is a cross-platform, open-source web server included by default in ASP.NET Core projects. It is designed to be lightweight and fast, serving as the primary process that listens for incoming HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7581266-be36-495f-8a43-a40c916fee35', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the distinction between stack allocation and heap allocation in C++, and how does it influence object lifetime?', N'Middle', N'Stack allocation is managed automatically by the compiler through scope-based lifecycles, offering high performance due to simple pointer adjustments. Heap allocation, managed via dynamic memory, allows for objects that persist beyond the scope of their creation but introduces overhead and the risk of memory leaks if not properly handled by smart pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79fe3491-4159-412b-9ea4-a41158799c53', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s microtask queue differ from the event queue in the context of the event loop?', N'Senior', N'The event loop processes microtasks before returning to the event queue. Microtasks are typically used for short, asynchronous actions that should execute immediately after the current task but before yielding control back to the event loop, ensuring high-priority scheduling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bf6c611-0caa-4abb-8fa0-a4115bb7942f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the functional interfaces Predicate<T>, DoublePredicate, IntPredicateand LongPredicate?', N'Intern', N'Predicate (predicate) - the interface with which a function is implemented that receives an instance of the class as input Tand returns the type value at the output boolean. The interface contains a variety of methods by default, allow to build complex conditions ( and, or, negate). * DoublePredicate- predicate receiving input Double; * IntPredicate- predicate receiving input Integer; * LongPredicate- predicate receiving input Long.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0d440e9-85e3-4fe2-aa7f-a4128b58888c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go compiler manage dependencies?', N'Middle', N'Go uses a module-based system that tracks dependencies in a dedicated file, ensuring reproducible builds by pinning specific versions of external packages. This eliminates the ''dependency hell'' common in other ecosystems by enforcing strict versioning and local caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d450e06-0ff9-4049-9b93-a412bb96c1f8', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do Structs and Classes differ in Swift?', N'Fresher', N'The primary difference is that structs are value types, meaning they are copied when assigned or passed, while classes are reference types, meaning they share the same instance. Additionally, classes support inheritance and deinitializers, whereas structs do not.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e77ebc7b-fb42-4f1b-b2d7-a4181ecdaa8b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does user experience (UX) design often conflict with technical performance requirements?', N'Intern', N'Rich, high-fidelity graphics or complex animations enhance the user experience but can significantly increase page load times and resource consumption. Engineers must find a balance where the visual appeal does not degrade the responsiveness or accessibility of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5442a95d-b846-4bdc-832e-a41f8758d70f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle cross-component communication?', N'Middle', N'Cross-component communication is primarily handled through browser-native Custom Events using the $dispatch helper. This allows components to communicate in a decoupled manner by broadcasting and listening to events within the DOM tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06cc6b0c-805b-477e-9178-a425a78718b8', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why would you use a ''layout group'' in SvelteKit?', N'Intern', N'A layout group, represented by folders in parentheses, allows you to organize routes and apply specific layouts to a subset of pages without affecting the URL structure. It is useful for grouping related sections of an application together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f11c4075-19c9-4771-8630-a425ae4a6a40', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum utilize the ''Future'' trait?', N'Middle', N'Axum handlers and middleware are inherently asynchronous, relying on the Future trait to represent operations that complete at a later time. This non-blocking design allows the server to remain responsive while waiting for I/O tasks like database queries or network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc35c954-252b-4328-8549-a426dadc54fa', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are Request Bodies in FastAPI?', N'Junior', N'Request bodies are the data sent by the client to your API, usually in a POST or PUT request. FastAPI uses Pydantic models to define the structure of this body, ensuring the incoming JSON is validated and parsed into a Python object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'306b3320-33f3-4927-acf1-a42881212017', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is ''Data Partitioning'' essential for large datasets?', N'Senior', N'Partitioning divides a large table into smaller, more manageable pieces based on a key, which improves performance by allowing the optimizer to prune unused partitions during queries. It also simplifies maintenance tasks like archiving old data or rebuilding indexes on a per-partition basis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f91900e-27b1-4e4e-92d7-a42a2980e25b', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is it important to keep handlers as thin as possible in a Chi application?', N'Senior', N'Thin handlers ensure that the routing layer remains decoupled from business logic. This separation of concerns is critical for testing, as it allows you to unit test the business logic independently of the HTTP delivery mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
