INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b788d57-f24d-4951-9d3c-a430dcf8640d', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a memory leak and why is it particularly problematic in C?', N'Middle', N'A memory leak occurs when memory is allocated on the heap but never deallocated, rendering it inaccessible to the program. In C, which lacks a garbage collector, these leaks accumulate over time, eventually exhausting available system memory and causing the application to crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
