INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4d674fc-228f-4281-a285-a449cd2396cb', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is a loading.js file?', N'Intern', N'The loading.js file is a special file that allows you to create an automatic loading UI for a route. It helps improve user experience by displaying a loading state while the page content is being fetched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9c1756e-a6c9-468d-a7ae-a44ecb1095e1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript engine''s event loop prioritize tasks between macro-tasks and micro-tasks, and why is this critical for performance?', N'Senior', N'Micro-tasks, such as promises, are executed immediately after the current execution stack clears and before the browser renders the next frame. Macro-tasks, like setTimeout, are processed in subsequent event loop iterations. Understanding this distinction is vital to prevent UI blocking and ensuring timely updates to the Document Object Model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c83b092-c611-4625-a142-a44f8a482e6a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the benefit of using ''server routes'' in the Nuxt Nitro engine?', N'Middle', N'Server routes allow you to create custom API endpoints directly within your Nuxt project, eliminating the need for a separate backend service for simple tasks. This simplifies deployment and keeps logic unified, while leveraging Nitro’s cross-platform compatibility to run on various edge or server environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fb53368-6224-4b19-915d-a450ca4e6421', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is meant by the term ''Garbage Collection'' in C#?', N'Intern', N'Garbage collection is an automatic memory management feature that reclaims memory occupied by objects that are no longer being used by the application. This helps prevent memory leaks and reduces the need for manual memory deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e3b927e-0f68-4b93-8a8b-a454d6905d24', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database transactions across multiple requests, and what are the limitations?', N'Senior', N'Django uses the atomic decorator to manage transactions, which binds a transaction to a single database connection for the duration of a block. It does not natively support distributed transactions across multiple databases or microservices, requiring external tools like two-phase commit or saga patterns for consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b340a17-50b5-48c9-8351-a4556d53ee40', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a module in Angular and what is its purpose?', N'Intern', N'In Angular, a module is a way to group components, services, directives, and pipes. It helps in both organizing and dividing your application into smaller, more manageable and efficient pieces. Key Module Elements - Components: The visual and behavioral building blocks of your application. - Directives: Tools for modifying the DOM or containing certain behaviors. - Services: Reusable units of code, often central to your application''s functionality. - Pipes: Data transformation agents, primarily used for UI purposes. Types of Modules - Root Module: The core module that serves as the entry point for your application. It''s often called AppModule. - Feature Module: An optional module that''s usually smaller in scope and can be lazily loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3a5a54e-c9af-418d-8a93-a45a3cca225f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the jQuery .addClass() method?', N'Intern', N'The .addClass() method adds one or more CSS classes to the selected elements. This is a standard way to change the styling of an element without directly manipulating individual CSS properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fb279a7-b2a2-41d1-99ee-a45c060a5975', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the security implications of Gin''s default JSON binding behavior?', N'Senior', N'Default JSON binding can be vulnerable to mass assignment attacks if developers bind directly to database-backed structs. It is a best practice to use Data Transfer Objects (DTOs) for request input to ensure only intended fields are mapped and validated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37cdfd79-c7dd-45bc-a186-a45e1b121ef0', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''test_client'' in Flask testing?', N'Middle', N'The ''test_client'' allows you to simulate HTTP requests to your application without needing to start a live server. It provides a way to verify the entire request-response cycle, including routing, middleware, and database interactions, in a controlled, isolated testing environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54bec91a-35f3-4033-8701-a45e8dbea650', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the ''thundering herd'' problem in a database environment?', N'Middle', N'This happens when a heavily requested cache key expires and multiple application processes attempt to regenerate the value by querying the database simultaneously. This can overwhelm the database, which is why techniques like cache locking or probabilistic early expiration are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0777c5a5-21a8-4f6d-9126-a460974abe7f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''session'' object in Flask?', N'Fresher', N'The session object allows you to store information specific to a user across multiple requests. It uses signed cookies to maintain state, enabling features like user authentication and shopping carts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'761bc262-756f-4125-a40b-a46199a77b1b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of ''hinting'' or ''optimizer overrides'' in query execution?', N'Senior', N'Query optimizers sometimes choose sub-optimal execution plans based on stale statistics or complexity limits. Hints allow developers or DBAs to manually force a specific index or join order to improve performance for known query patterns, although this requires careful maintenance as data distributions change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a430c8d-b73d-4d35-87c3-a46273914501', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type narrowing?', N'Fresher', N'Type narrowing is the process of moving from a broader type to a more specific type within a conditional block. TypeScript uses control flow analysis, such as checking for null or using the ''typeof'' operator, to narrow types automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa41c45f-4152-4de2-9bd9-a4629769878e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary difference between a clustered and a non-clustered index in terms of data storage?', N'Middle', N'A clustered index determines the physical order of data in the table, meaning the table can have only one clustered index. A non-clustered index creates a separate structure that contains pointers to the actual data rows, allowing multiple non-clustered indexes per table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
