INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c82cb13e-efec-403c-b10d-a4663d78c342', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the advantage of using Redis over a traditional relational database for caching?', N'Intern', N'Redis is significantly faster because it operates entirely in RAM, whereas relational databases typically read from disk. This low latency makes Redis ideal for high-frequency data access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
