INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'091b47f0-433a-4712-991b-a466ab08c14b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the InnoDB Buffer Pool manage page replacement, and why is it critical for performance?', N'Senior', N'The InnoDB Buffer Pool uses a modified LRU (Least Recently Used) algorithm to keep frequently accessed data in memory. It prevents excessive disk I/O by managing page aging and flushing, ensuring that hot data remains cached for rapid retrieval while balancing memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
