INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a5bddbd-cd8d-40da-94c9-a46eaf30886d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does ''Infrastructure as Code'' (IaC) improve the consistency of security group configurations?', N'Senior', N'IaC allows for security configurations to be defined in version-controlled files, enabling peer reviews and automated testing before deployment. This ensures that network security policies are applied consistently across environments, reducing the risk of human error or misconfiguration that often leads to open ports and unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bf8aa97-d050-4ae4-8f38-a46ed3156ac6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you design for graceful degradation when a critical dependency fails?', N'Senior', N'I employ circuit breakers to stop requests to failing services, combined with fallback logic that returns cached or default data. This ensures the user experience remains partially functional rather than failing entirely, preserving core business value during partial outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0d59b81-17e6-4cd4-adce-a470440a9a03', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the role of the ''WiredTiger'' storage engine in MongoDB and its impact on concurrency.', N'Senior', N'WiredTiger utilizes document-level concurrency control rather than collection-level locking, significantly improving write throughput. It achieves this through optimistic concurrency control and snapshot isolation, allowing multiple threads to modify different documents within the same collection simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d1eefed-0022-4880-8950-a474f9cc7d67', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary advantage of Chi''s dependency-free design?', N'Intern', N'The dependency-free design means Chi does not rely on third-party libraries outside of the Go standard library. This results in smaller binaries, fewer security vulnerabilities, and easier dependency management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67b63ca2-03fc-4a69-8219-a475ae3988ef', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a Response and a JsonResponse?', N'Junior', N'A standard Response is typically used for returning HTML content to the browser. A JsonResponse is a specialized version that automatically sets the ''Content-Type'' header to application/json and serializes the provided data for use in APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d0edf72-0a38-4e18-898b-a47691d6e7c1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the maximum user capacity for a real-time chat application?', N'Senior', N'I calculate the message throughput per user and the concurrent connection limits of the websocket servers. I then perform stress tests to identify the memory footprint per connection and the CPU cost of message broadcasting to determine the scaling thresholds for the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d34b2d8-2dff-47d4-9fcf-a477e935fe76', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s Logger middleware?', N'Junior', N'The Logger middleware automatically records information about every incoming request, such as the HTTP method, path, response status code, and latency. This is essential for debugging and monitoring API performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc6494df-94df-430f-884f-a479d4513be1', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary difference between SQL and Cassandra?', N'Intern', N'SQL databases are typically relational and prioritize strong consistency, while Cassandra is a NoSQL database designed for high availability and horizontal scalability. Cassandra lacks complex joins and transactions found in traditional relational systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c8cfeb8-9330-4955-baac-a47a2e793515', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to define requirements before starting the design of a system?', N'Intern', N'Defining requirements ensures that the team understands exactly what the system needs to achieve. It prevents scope creep and ensures that the final product aligns with user expectations and business goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'102b7fef-18e3-47e0-b631-a480b8a0a735', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the purpose of the ''@tailwind'' directive?', N'Intern', N'The ''@tailwind'' directives are used in your main CSS file to inject Tailwind''s base, components, and utilities styles into your project. This is the entry point for the framework''s CSS generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29cd604b-4cd0-4ce9-8526-a482ff2d1e4f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When working on a team project, how do you handle conflicting opinions on a technical approach?', N'Fresher', N'I listen to the reasoning behind the other person''s perspective and share my own based on factual evidence or project constraints. If a consensus cannot be reached, I suggest a quick test or prototype for both ideas to see which performs better.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6121436-2099-4d8c-b2e0-a483761b0174', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you diagnose a race condition that only appears under high concurrency?', N'Middle', N'I would start by reviewing the logic for shared resource access and identifying areas lacking proper synchronization or atomic operations. I would then use stress testing tools to simulate high load while increasing logging granularity to catch the timing overlap, verifying that the implementation correctly uses locks or concurrency-safe data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e673ad25-8ee9-4343-92a6-a4853d09c4ba', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Can you have multiple middleware functions for a single route?', N'Intern', N'Yes, you can pass multiple middleware functions as arguments to a route method. Express will execute them in the order they are provided, provided that each function calls the next() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e26a1c-b77d-48f5-a834-a485d2f5aa97', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a lambda expression?', N'Intern', N'A lambda expression is a concise way to define an anonymous function that can be treated as a value. It is frequently used when passing behavior as an argument to higher-order functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a04e730-1489-42be-ad95-a48644058b09', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the advantage of using a Content Delivery Network (CDN) for serving static assets like images and CSS?', N'Fresher', N'A CDN serves assets from servers geographically closer to the user, which significantly reduces latency and load times. It also reduces the bandwidth burden on your primary server by offloading the delivery of static content. This improves the overall performance and reliability of the application for a global user base.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74e158c1-e3f8-45e6-883e-a48a8bc3a274', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the significance of database constraints like foreign keys in design?', N'Middle', N'Constraints enforce business rules and maintain referential integrity at the database level. By preventing invalid data states, they ensure that the application layer does not have to implement complex logic to protect the data''s structural integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8735df39-9ac2-4a82-8ad3-a48b1c1de97a', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'In what ways can Alpine.js be used to bridge the gap between static HTML and full-stack frameworks like Laravel?', N'Senior', N'Alpine.js serves as the ideal ''glue'' layer, allowing server-side frameworks to render complete HTML while Alpine adds the necessary interactivity without requiring a separate API or client-side build pipeline. This architecture reduces the complexity of maintaining two separate codebases for frontend and backend. It allows for a seamless ''isomorphic-like'' experience where the server handles data and the client handles transient UI state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ded3cb-a5e7-4bb0-90a0-a48bbd2d3194', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s AOT compilation influence runtime performance and binary size compared to JIT?', N'Senior', N'AOT compilation converts Dart code into native machine code during build time, which significantly improves startup latency and reduces runtime CPU overhead. While this leads to larger binary sizes due to the inclusion of the runtime and tree-shaken code, it eliminates the need for a JIT compiler on the user''s device.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f178b7-8fe5-4ae0-bb2d-a48dd4b6cbda', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are generics?', N'Junior', N'Generics allow you to write functions, structs, and enums that can operate on multiple data types. This promotes code reuse and helps avoid duplication while maintaining type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97af833d-6bc7-4579-8356-a490d61477ff', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask extensions and how do they integrate with the app object?', N'Middle', N'Extensions are packages that provide additional functionality like database ORMs, form validation, or authentication. They usually follow the factory pattern, where you initialize the extension by passing the app instance to it. This pattern ensures the extension is properly registered with the application context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'691b7ef3-a7fa-44f6-ac26-a4934363a66f', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do you mitigate the ''thundering herd'' problem in a distributed caching architecture?', N'Senior', N'This is typically mitigated using request collapsing, where multiple concurrent requests for the same expired key are coalesced into a single backend fetch. Alternatively, implementing probabilistic early recomputation or using a distributed lock ensures only one process refreshes the cache while others continue to serve stale data briefly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c2b21a9-27c5-4248-9a86-a498c0ada09c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Describe the role of the ''resolve.alias'' configuration in Webpack.', N'Middle', N'The resolve.alias configuration allows you to create shorter or more meaningful aliases for import paths. This simplifies complex directory structures, making imports easier to manage and reducing the risk of errors when moving files between deep folder hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7c024b3-917c-4e54-8b76-a4991c6ed54b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery help with DOM manipulation?', N'Junior', N'jQuery provides a wide array of methods to easily insert, move, or remove elements from the page. It simplifies tasks like wrapping content in new tags, appending new children to a container, or removing specific elements based on criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c937a69-5e0b-4d74-b9dd-a499bfc7c883', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is global execution context?', N'Intern', N'The global execution context is the default or first execution context that is created by the JavaScript engine before any code is executed(i.e, when the file first loads in the browser). All the global code that is not inside a function or object will be executed inside this global execution context. Since JS engine is single threaded there will be only one global environment and there will be only one global execution context. For example, the below code other than code inside any function or object is executed inside the global execution context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dda6deb8-afad-449e-b487-a499d81ef5a4', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle navigation and asset prefetching?', N'Middle', N'Remix prefetches the necessary data, modules, and CSS for a route when the user hovers over or focuses on a link. This makes the application feel instantaneous because the required resources are already available when the user clicks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aca945dd-fac7-4444-9c4a-a49c432f9f5d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact ensure performance efficiency?', N'Fresher', N'Preact ensures efficiency by using a very small core library, an optimized diffing algorithm, and a minimal set of abstractions. By avoiding heavy features that aren''t strictly necessary, it keeps the runtime overhead extremely low.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0328d90c-2d23-42ae-be6e-a4a19badac47', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do Flask signals work, and why might you prefer them over direct function calls for cross-module communication?', N'Senior', N'Signals provide a decoupled, pub-sub mechanism where the sender does not need to know which listeners are attached or how many there are. This architecture reduces tight coupling between system components, allowing you to trigger secondary side effects like logging or analytics without cluttering the primary business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd16f3bac-4d4b-4e5a-92b5-a4a35b4ae13e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does the term ''BASE'' mean in the context of NoSQL?', N'Intern', N'BASE stands for Basically Available, Soft state, and Eventual consistency. It is a consistency model used in many NoSQL databases that prioritizes high availability and performance over the strict immediate consistency found in traditional SQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a94499c4-c665-4791-b9fa-a4a3a759ee64', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix Presence?', N'Middle', N'Phoenix Presence is a feature that allows you to track user state, such as online status or activity, across a distributed cluster of nodes. It relies on CRDTs to ensure that presence information is eventually consistent across all connected servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bf6e59f-db13-4760-891c-a4a5cf4b2ce7', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between a cache-aside and a write-through caching strategy?', N'Middle', N'In cache-aside, the application is responsible for reading from and writing to the cache. In write-through, the application updates the cache, and the cache provider automatically updates the underlying database, ensuring the cache is always consistent with the data store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01c09f15-2a7d-4fc8-9cad-a4a5ee04ae62', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle dynamic path segments?', N'Junior', N'Rocket uses dynamic path parameters defined within angle brackets in the route path, such as . The framework automatically parses these segments into the function arguments, provided the types implement the required traits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4270883-1133-4a52-bcb6-a4a6a07d3ba0', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it discouraged to run a Flask development server in a production environment?', N'Middle', N'The built-in development server is single-threaded and not designed for high concurrency or security hardening. It lacks advanced features like process management, load balancing, and protection against common network attacks. Production environments require a WSGI server like Gunicorn or uWSGI to handle concurrent requests efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c51919-d7c7-496b-b425-a4a6f8939b06', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the trade-offs of using Static Site Generation (SSG) versus Server-Side Rendering (SSR).', N'Middle', N'SSG offers superior performance and lower server costs because pages are generated at build time and served via CDN. SSR generates pages on-demand for every request, which is ideal for highly dynamic content that must always be fresh, but it increases server load and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a546b46c-9982-45bc-8431-a4a9e8a19e58', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it dangerous to return a pointer to a local variable from a function?', N'Junior', N'Local variables exist only within the scope of the function and are destroyed when the function returns. If you return a pointer to a local variable, that pointer will reference memory that is no longer valid or that has been reclaimed by the system. Accessing this ''dangling pointer'' results in undefined behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2b12fe5-86ad-425a-8a98-a4ab4df1788d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of ''composition over inheritance''.', N'Middle', N'Composition over inheritance suggests that classes should achieve polymorphic behavior and code reuse by containing instances of other classes rather than inheriting from a base class. This approach promotes looser coupling and prevents the pitfalls of fragile base classes, where changes in a parent class unexpectedly break child implementations. It leads to more maintainable and testable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8a54d47-ae18-40f0-9007-a4acc9c0a541', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a ''SSTable'' in the context of storage?', N'Middle', N'An SSTable (Sorted String Table) is an immutable file on disk where Memtables are flushed once they reach a certain size. Because they are immutable, Cassandra never modifies them, which simplifies the storage architecture and improves performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d2f2e00-f518-4dce-91d0-a4b115568baa', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro implement partial hydration to avoid the ''rehydration'' problem?', N'Senior', N'Astro avoids the ''rehydration'' problem by not attempting to ''re-run'' the entire component tree on the client. Instead, it mounts only the specific islands specified by the developer, leaving the rest of the HTML as static, non-interactive markup, which prevents the UI flicker or state loss associated with full-page hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f58e2b2f-e01a-4b8b-b255-a4b180247f6a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Entity Framework Core?', N'Intern', N'Entity Framework Core is an object-database mapper that enables .NET developers to work with a database using .NET objects. It eliminates the need for most of the data-access code that developers usually need to write by allowing interaction with data via LINQ queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dc560bf-aad9-4b6d-ba50-a4b52383ad85', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain how partitioning a message queue (e.g., Kafka partitions) impacts parallelism.', N'Senior', N'Partitions allow a queue to scale horizontally by enabling multiple consumers to process messages from different shards in parallel. Since messages within a single partition are processed sequentially, partitioning allows you to balance the need for high throughput with the need for ordered message processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'268d0578-6eda-417e-b124-a4b545e41cf2', N'075b8862-431c-4678-9767-f55359758a4a', N'How does reactivity works with ref?', N'Fresher', N'VueJS automatically detects the changes to ref''s value and updates the DOM with a dependency-tracking based reactivity system. 1. When a component is rendered for the first time, it tracks every ref that was used during the render. 2. Whenever a ref is mutated, it will trigger a re-render of the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24b57d04-f2ae-4c7a-aa25-a4b941ecc414', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is ''Covering Index'' optimization effective for read-heavy workloads?', N'Senior', N'A covering index contains all the columns requested by a query, allowing the database to satisfy the request entirely from the index tree without ever accessing the clustered data pages. This eliminates the expensive random I/O required to fetch rows, leading to a massive reduction in latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51f9b482-c35e-465f-a8f1-a4baaf50b048', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the reason to deprecate web worker packages?', N'Intern', N'Both @angular/platform-webworker and @angular/platform-webworker-dynamic are officially deprecated, the Angular team realized it''s not good practice to run the Angular application on Web worker', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab7e6244-3de4-44bf-8622-a4be36ce9d4b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is meant by the term ''resumability'' in Qwik?', N'Fresher', N'Resumability is the ability of an application to resume execution on the client side exactly where it left off on the server. Because the state and event listeners are serialized into the HTML, Qwik does not need to re-run the entire component tree to make the page interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7706e0d-fdbd-4083-8e3d-a4c11c634fb7', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the ''Meta'' class in a Django model?', N'Middle', N'The Meta class is used to define model-level options that are not specific to any individual field, such as database table names, default ordering, permissions, or constraints. It allows you to configure the model''s behavior in the database and the admin interface without cluttering the model''s primary attribute definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2139058a-a7d4-4c2d-8656-a4c39804d98e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the ''Micronaut Data'' abstraction, and how does it improve performance?', N'Senior', N'Micronaut Data generates query implementations at compile-time based on method signatures rather than using reflection-based ORM mapping. This results in zero-overhead database access, as the SQL is determined and validated before the application even runs, preventing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
