INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37d6a43c-4956-448f-a8a6-a4ca4717154a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the difference between Qwik and a traditional SPA?', N'Fresher', N'A traditional SPA typically loads a large JavaScript bundle to initialize the entire application state on the client. Qwik, in contrast, loads JavaScript only when needed, avoiding the heavy initial cost and providing a faster interactive experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c3d838-9d26-422c-9a25-a4ce06f7515a', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you handle schema migrations in a large-scale database with zero downtime?', N'Senior', N'Zero-downtime migrations typically involve a multi-phase approach: adding new columns as nullable, updating application logic to write to both old and new schemas, backfilling legacy data, and finally removing the old schema. This requires careful orchestration to ensure the application remains compatible with the database state at all times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc539db6-ee9c-49fc-8b53-a4cfa11ce145', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the concept of ''Route Constraints'' in Fastify.', N'Senior', N'Route constraints allow the router to differentiate between routes based on properties like the version header or host name without having to define separate route definitions. This simplifies the management of API versioning and multi-tenant routing, keeping the codebase clean and performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
