INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f2ad9eb-bfe3-47ec-9634-a4d7404d7564', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the impact of document structure on accessibility tree construction?', N'Senior', N'Browsers translate HTML into an accessibility tree that screen readers consume; improper nesting or bypassing semantic landmarks disrupts this hierarchy. A flat or logically ordered document ensures that assistive technology can reliably navigate and announce content, which is a fundamental requirement for WCAG compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'570f346d-7e97-46bf-abbe-a4d873645cf1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a centralized configuration store and environmental variables in a containerized environment?', N'Middle', N'Centralized configuration stores allow for dynamic updates and centralized management across many services but introduce a dependency on an external service. Environment variables are simple, immutable, and have no external dependencies, but they require a container restart to update and can be harder to manage across large-scale deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea77997a-5779-4a3e-a6f0-a4d91b7a0c93', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the primary difference between a ''final'' and a ''const'' variable in Dart?', N'Junior', N'A ''final'' variable is set once and initialized at runtime, meaning its value can be determined by a function or a dynamic calculation. A ''const'' variable is a compile-time constant, meaning its value must be known before the program starts running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8be93cfc-b205-4d81-afe7-a4d9c5a9e44f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the difference between a ''push'' and ''pull'' model for API data updates.', N'Middle', N'A pull model requires the client to request data periodically, which is simple but inefficient if data changes rarely. A push model, such as Webhooks or WebSockets, allows the server to send updates to the client immediately, reducing latency and unnecessary network traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e63166fa-568b-4184-9463-a4da499f47c0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''break'' and ''continue'' in a loop?', N'Junior', N'The ''break'' statement terminates the entire loop immediately and exits to the next line of code after the loop. The ''continue'' statement skips only the current iteration and jumps immediately to the next cycle of the loop. Both are used to control the flow of execution within repetitive logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'693b35c4-813b-4c8b-ad44-a4dc5ecc36dc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the impact of the V8 ''In-object properties'' optimization on memory layout.', N'Senior', N'In-object properties store object fields directly within the memory allocated for the object itself rather than in a separate backing store. This eliminates one pointer dereference, significantly speeding up access to frequently used properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20397c98-ff49-4349-8f2d-a4dc77b19d41', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between useEffect and useLayoutEffect in React?', N'Fresher', N'Both hooks run side effects after render, but they differ in when they fire relative to paint: - useEffect runs asynchronously after the browser has painted. It does not block the user from seeing the new frame. Use it for data fetching, subscriptions, logging, and most side effects. - useLayoutEffect runs synchronously during the commit phase, after DOM mutations but before the browser paints. It blocks paint, so use it only when you need to measure the DOM and write to it in the same frame to avoid a visual flicker. Both accept a dependency array with the same semantics, both fire twice on mount in Strict Mode development builds, and useLayoutEffect has no effect during server rendering (React warns if you use it in SSR). Code example: ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ff10f27-8c20-4416-ba61-a4de97734340', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine if a task should be processed synchronously or asynchronously?', N'Junior', N'Synchronous processing is appropriate for operations where the user needs an immediate response or confirmation, such as a login attempt. Asynchronous processing should be used for long-running, non-blocking tasks like sending emails or image processing to keep the user interface responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca815a57-e8f9-4e48-a9b3-a4e0c4530cb9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle dependency injection without using runtime reflection?', N'Middle', N'Micronaut uses Java annotation processors or KSP to generate metadata during the compilation phase. This metadata allows the framework to instantiate beans and inject dependencies directly, avoiding the need for heavy reflection-based scanning at application startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a992365-351e-4361-ad8e-a4e14f530f81', N'4c000000-0000-0000-0000-000000000005', N'What is the primary trade-off when choosing between SQL and NoSQL databases?', N'Middle', N'SQL databases prioritize ACID compliance, structured data, and complex joins, making them ideal for transactional integrity. NoSQL databases prioritize horizontal scalability, flexible schemas, and high write throughput, often sacrificing strict consistency for availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'966fbe18-92bf-4f4c-bec2-a4e2ca478b14', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a wide-column store and when is it the best choice?', N'Middle', N'A wide-column store organizes data into flexible columns rather than rows, allowing for sparse datasets where each row can have a different number of columns. It is an excellent choice for time-series data or massive scale analytical workloads where fast writes are prioritized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'188c01c3-e505-4266-93d3-a4e4bfe119ab', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle multipart form data?', N'Fresher', N'Axum provides a Multipart extractor that allows for processing file uploads and form data. It handles the parsing of the multipart stream, providing access to individual fields and files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f6f9a66-1b13-43ef-8ff5-a4e94bcea262', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus optimize memory usage in high-scale environments?', N'Senior', N'Quarkus optimizes memory by discarding unused classes and metadata during the native compilation process. By removing the need for a runtime JVM meta-space and minimizing object overhead through build-time wiring, it maintains a small resident set size (RSS) even under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2cf77f0-677b-4707-b8dd-a4ea62b60058', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''Validator'' ensure data integrity compared to manual validation?', N'Senior', N'The validator integrates directly with the request lifecycle, ensuring that data is sanitized and type-checked before reaching the business logic layer. This proactive approach prevents malformed data from entering the system, reducing the need for redundant defensive coding within services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c43a497f-6a05-45d4-a453-a4eaadcae790', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the benefit of using the html tag function in Lit?', N'Fresher', N'The html tag function parses the template literal into a dynamic template that Lit can efficiently update. It prevents common security issues like cross-site scripting by ensuring that data is properly escaped before being rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18cc1dab-a0f6-4458-9c61-a4eb0e353fe9', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage code size on the client?', N'Fresher', N'Qwik manages code size by strictly limiting the amount of JavaScript sent to the browser. By using fine-grained code splitting and only loading what is necessary for a specific user interaction, the total size of client-side code remains minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15da79df-89b1-483b-b6e2-a4ebe282057d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is reflection a concern in Quarkus native images, and how is it handled?', N'Middle', N'GraalVM Native Image requires a closed-world assumption where all reachable code must be known at build-time, which conflicts with Java''s dynamic reflection. Quarkus handles this by allowing developers to register classes for reflection through configuration files or annotations, ensuring the static analyzer can include them in the native binary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'954a8159-0b31-4748-93d5-a4ec9fb9e2c8', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does the ''volatile'' keyword signify in multi-threaded C# code?', N'Middle', N'The ''volatile'' keyword indicates that a field might be modified by multiple threads that are executing at the same time. It prevents the compiler and the CPU from performing optimizations like reordering or caching the value in a register, ensuring that the thread always reads the most current value from memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
