INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3c520e2-8019-4cbc-b95c-a4fc9cfc9fa7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What happens when a document exceeds the 16MB limit in MongoDB?', N'Middle', N'MongoDB enforces a 16MB document size limit to prevent excessive memory usage and ensure predictable performance. If a document exceeds this limit, the application must be refactored to use techniques like GridFS for large data or to split the document into smaller, linked documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'856bed6e-3bb4-495f-ba19-a4fcea300b9f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS ensure that effects are only triggered when necessary?', N'Middle', N'SolidJS uses a dependency tracking system where the effect automatically records which signals were accessed during its first execution. It then subscribes to those specific signals, ensuring the effect function only re-runs when one of the recorded dependencies emits a new value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29471b47-6a3d-4b5b-95b2-a5012eafa3e9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is an ''Expression'' versus a ''Statement'' in Rust?', N'Fresher', N'Statements are instructions that perform an action but do not return a value. Expressions evaluate to a resulting value, and most of the body of a function in Rust is composed of expressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e86ca84-2dd6-4d8c-849e-a501a2884077', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit optimize the rendering process during rapid property changes?', N'Middle', N'Lit batches all property changes into a single asynchronous update cycle. This prevents redundant DOM re-renders if multiple properties are modified in the same synchronous task, ensuring high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2be7eac3-d57c-427b-9074-a50522e94784', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of ''Error Handling'' in Actix-web?', N'Intern', N'Error handling ensures that if an operation fails, the application returns a meaningful HTTP error code to the client instead of crashing. It provides a way to map internal errors to user-friendly HTTP responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50ecd226-69b3-4f99-b12f-a507d34d9b88', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime detect and handle goroutine leaks?', N'Senior', N'The Go runtime does not automatically detect or kill leaked goroutines, as it cannot distinguish between a long-running background task and a leak. Developers must utilize tools like context cancellation or proper channel closing patterns to ensure goroutines exit gracefully, as leaked goroutines consume memory and can cause long-term resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa118ee8-45d2-49ce-9f43-a50c5d550a4e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the ''nitro'' engine in Nuxt?', N'Fresher', N'Nitro is the server engine that powers Nuxt. It is responsible for building the server and handling requests, providing high-performance features like edge-side rendering and deployment flexibility across various cloud providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15d929c2-5325-4e8c-929a-a50cefe6b443', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the risk of ''optimism bias'' in engineering estimation?', N'Junior', N'Optimism bias leads developers to believe they can complete a task in the best-case scenario without encountering any errors or delays. This results in unrealistic deadlines that are rarely met, leading to team burnout and a loss of trust from stakeholders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38feb33e-95cd-430f-a12c-a50d02156a16', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are jQuery events?', N'Intern', N'jQuery events are wrappers around standard JavaScript browser events like clicks, form submissions, or key presses. They provide a standardized way to attach listeners to elements and trigger actions when those events occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab37cc6c-5aee-43b0-a902-a50dd9b91d57', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the architectural advantages of Hono''s middleware composition model compared to the ''next'' callback pattern.', N'Senior', N'Hono uses a stack-based execution model where middleware can perform operations both before and after the handler by awaiting the next function call. This structure allows for cleaner resource management, such as wrapping database transactions or response transformations, without the callback-hell risks associated with older middleware architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa20fc37-03cf-4473-9cc1-a5121200c705', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s sound null safety affect runtime performance and binary size?', N'Senior', N'Sound null safety allows the compiler to make aggressive optimizations by assuming non-nullable variables will never contain null. This reduces the need for runtime null checks, resulting in tighter machine code, improved execution speed, and smaller binary footprints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4911975-bf22-4a44-860f-a5170aba894a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is meant by Durability?', N'Junior', N'Durability guarantees that once a transaction has been committed, it will remain saved even in the event of a system failure, such as a power outage or crash. The changes are permanently recorded in non-volatile memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66f51f7f-e742-4b1f-89f4-a51b2ee42ee4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with two equally valid technical solutions, how do you decide which one to choose?', N'Intern', N'I evaluate both options based on long-term maintainability, scalability, and resource requirements. I consider which solution aligns better with current project standards and team expertise. Choosing the simpler, more readable solution is usually preferable to reduce future technical debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb6459a3-fb91-42c8-9524-a51b714b4c2e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you bind input values to Alpine.js state?', N'Fresher', N'You use the x-model directive to create two-way data binding between an input element and your Alpine component state. When the user types into the input, the corresponding state variable is updated automatically, and vice-versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
