INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2caa33f-09bc-4820-89e7-a530f1d308ad', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js''s ''x-teleport'' directive change the way developers approach UI component composition?', N'Senior', N'Teleport allows developers to render parts of a component in a different location in the DOM tree while maintaining the original reactive scope. This solves the challenge of handling absolute-positioned elements like modals or tooltips that might otherwise suffer from CSS overflow or stacking context issues. It enables clean architectural separation between the logical component and its visual representation in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
