INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c74265cf-fd1d-4d4c-8d98-a53bfe70ece1', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle context?', N'Fresher', N'Context allows you to pass data through the component tree without manually passing props at every level. You create a context, provide it at a high level, and consume it in any descendant component using a dedicated hook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'508a900b-2639-490b-9352-a53e1e79ad08', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of Chi''s design regarding dependency injection?', N'Senior', N'Chi doesn''t enforce a specific dependency injection strategy, which allows it to integrate seamlessly with any DI container or constructor-based injection. By keeping the router logic decoupled from the business logic, you can easily inject service layer dependencies into your handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b733440-e560-4248-8b93-a53f4d4b176c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle API routes in a static site?', N'Middle', N'Astro uses endpoint files to define API routes that execute on the server. In static builds, these endpoints are evaluated at build time to generate JSON or other files, whereas in SSR mode, they function as dynamic server-side handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ad90813-23f4-431d-a5b1-a540c750516a', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the ''Thundering Herd'' problem in distributed caching, and how does it relate to system availability?', N'Senior', N'The thundering herd occurs when a shared resource becomes available or a cache key expires, triggering a massive surge of concurrent requests that overwhelm the system. It threatens availability by creating CPU and I/O spikes that can lead to cascading failures across the backend infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41fc5c5a-d42f-4912-b202-a5437ee53888', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Can Vite be used for server-side rendering (SSR)?', N'Middle', N'Yes, Vite supports SSR by providing APIs to load the server entry point and transform modules for a Node.js environment. It is widely used with frameworks like Nuxt or SvelteKit to provide a unified dev experience for both client and server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17e70fda-1fa5-4622-8db8-a5443c98c9c8', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the limitations of Hono''s architecture when migrating a legacy, stateful application?', N'Senior', N'Hono is fundamentally built for stateless request-response cycles, which makes it challenging to implement persistent WebSocket connections or long-lived server-side states. Migrating a legacy application would require decoupling state into an external store like Redis or a database and refactoring the logic to be purely event-driven.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1162def8-c681-49bd-8b68-a546dd2759b4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik achieve near-instant TTI (Time to Interactive)?', N'Middle', N'Qwik achieves this by shipping almost zero JavaScript to the browser initially. It uses lazy loading to download only the specific code required for user interactions at the moment they occur, effectively delaying execution until strictly necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'597864a2-e527-49e6-b074-a55007d1c8aa', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does Lucid''s ''Eager Loading'' improve performance?', N'Middle', N'Eager loading solves the N+1 query problem by fetching related models in a separate query and mapping them to the parent records in memory. This significantly reduces the number of database round-trips when accessing relationships in a loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c9a9701-5b8f-4fb5-830f-a55044b23824', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a header file and a source file in C?', N'Intern', N'A header file generally contains declarations such as function prototypes and macro definitions meant to be shared across multiple files. A source file contains the actual implementation of logic and function definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15b92aa4-0922-4464-8850-a552f3e8142d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between for...of and for...in statements', N'Intern', N'Both for...in and for...of statements iterate over js data structures. The only difference is over what they iterate: 1. for..in iterates over all enumerable property keys of an object 2. for..of iterates over the values of an iterable object. Let''s explain this difference with an example, Since for..in loop iterates over the keys of the object, the first loop logs 0, 1, 2 and newProp while iterating over the array object. The for..of loop iterates over the values of a arr data structure and logs a, b, c in the console.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58d1db62-d03a-4a2f-a82b-a5559f034764', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an Auto Increment field?', N'Fresher', N'An Auto Increment field is a column that automatically generates a unique numeric value for each new record inserted into the table. It is commonly used to generate unique primary keys automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78b69785-8ef4-4ecc-967a-a5575abf856d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Discuss the architectural benefit of ''Extension Functions'' compared to ''Utility Classes''.', N'Senior', N'Extension functions provide better discoverability via IDE completion and improve code readability by allowing objects to be used as if they possessed the added functionality. Unlike utility classes, which often lead to ''static soup'', extensions maintain a more natural object-oriented flow while avoiding the need to modify original class source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'323e6d70-662a-4277-82dc-a55902442de9', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle bean scoping compared to traditional frameworks?', N'Senior', N'Micronaut generates bean factories at compile-time, allowing the framework to manage object lifecycles without runtime introspection. This approach provides fine-grained control over singleton, prototype, and request scopes while maintaining high performance through static initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cc7e7f6-60db-4fcf-ada1-a55a34360954', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How are exceptions handled globally in Micronaut?', N'Junior', N'Global exception handling is managed by creating a class that implements the ExceptionHandler interface. This class is annotated with @Produces to catch specific exceptions thrown during request processing and return appropriate HTTP responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbda2a9d-e54b-4d2a-89c3-a55b7f65a830', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the common strategies for handling background tasks in a Django application?', N'Middle', N'For tasks that take too long to run during a request-response cycle, such as sending emails or heavy processing, developers use task queues like Celery or Django Q. These tools offload the work to separate worker processes, allowing the application to remain responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff0369d8-9f31-46fa-8fbe-a55ba8d7f4a5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the relationship between the number of partitions and throughput.', N'Middle', N'DynamoDB partitions the data based on the partition key. Each partition has a fixed amount of throughput capacity; as your data grows or throughput requirements increase, DynamoDB automatically splits partitions to maintain performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
