INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3aa61a56-68f6-4c54-ada4-a563541aeeda', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you handle long-running requests in Django to prevent worker timeouts?', N'Senior', N'Long-running requests should be offloaded to a background task queue. The view should immediately return an accepted status or a task ID to the user, while the worker processes the heavy logic, preventing the web server process from being held hostage and becoming unavailable to other users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0495bdd3-1220-43ad-8eca-a5684a3efdd3', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the risks of using an in-memory message queue?', N'Middle', N'In-memory queues provide very low latency but risk data loss if the broker process crashes or the server loses power. They are generally only suitable for non-critical telemetry or transient data where persistence is not required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef9c5789-9180-407b-981f-a56c0165a678', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you find that your task will take significantly longer than expected, what information should you provide to your lead?', N'Junior', N'I should explain exactly why it is taking longer, what portion of the work is complete, what remains, and whether the delay will affect the final deadline. I should also propose a plan to get back on track or ask for help if the complexity is beyond my current experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66f8468b-86ea-45a8-8538-a56d76005907', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why would using fibers potentially improve the performance of a high-concurrency I/O-bound application?', N'Middle', N'Fibers allow the application to handle many blocked I/O operations without tying up expensive OS threads. When a fiber performs a blocking operation, the runtime can pause that specific fiber and switch to another one, maximizing CPU utilization while waiting for network or disk responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37019330-9e77-414f-ac39-a572a6fd37e7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does the ''internal'' access modifier mean?', N'Junior', N'The ''internal'' access modifier restricts access to the current assembly. Only code within the same project or compiled binary can access members marked as internal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'036f6e6c-e2d4-40b3-bb11-a5744763738d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is the use of ''flex'' and ''grid'' preferred over legacy float-based layouts in modern responsive design?', N'Senior', N'Float-based layouts were never intended for structural design, requiring complex clearfix hacks and rigid width calculations. Flexbox and Grid provide intrinsic layout capabilities that respond to content size and container constraints, reducing the need for media-query-heavy layouts and improving the maintainability of complex interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49e35c75-87a3-4bbb-bc19-a574dc7697a4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the Gin framework and what is its primary purpose in Go backend development?', N'Fresher', N'Gin is a high-performance web framework for the Go programming language that uses a custom version of the HttpRouter. Its primary purpose is to simplify the creation of web applications and RESTful APIs by providing a faster alternative to the standard library''s net/http package. It offers features like middleware support, easy JSON validation, and efficient routing to handle HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af953a3f-5391-4164-b2df-a575b9e05904', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the key components of Angular?', N'Intern', N'Angular has the key components below, 1. Component: These are the basic building blocks of an Angular application to control HTML views. 2. Modules: An Angular module is a set of angular basic building blocks like components, directives, services etc. An application is divided into logical pieces and each piece of code is called as "module" which perform a single task. 3. Templates: These represent the views of an Angular application. 4. Services: Are used to create components which can be shared across the entire application. 5. Metadata: This can be used to add more data to an Angular class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a1794d-d5eb-449c-8f45-a57a2d3fdcb9', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the role of ''Cache Warming'' in preventing performance degradation during deployments?', N'Senior', N'Cache warming involves pre-populating the cache with frequently accessed data before a service goes live or scales up. This prevents an immediate spike in database load and latency as the system handles initial traffic, ensuring a smooth transition to the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6752f7b-1697-44d1-a829-a57b5bb7f866', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is an autocommit mode?', N'Fresher', N'Autocommit mode is a setting where every individual SQL statement is treated as a single transaction and is committed automatically upon successful execution. This removes the need for manual commit commands for single-statement operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e5a11b4-77a6-4a99-8b3b-a57cc48c1a10', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the role of the LitElement base class?', N'Intern', N'LitElement is the primary base class provided by Lit. It extends the native HTMLElement class to add features like reactive properties, an efficient rendering system, and lifecycle callbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e108c2e-322c-4501-b9b0-a57dbf9fb83c', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a cluster in PostgreSQL?', N'Intern', N'A cluster is a collection of databases managed by a single PostgreSQL server instance. All databases in the cluster share the same configuration files and background processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c29e9ae7-7cdf-49ad-8fa3-a5819ded6101', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Route'' in Rocket?', N'Intern', N'A route is a mapping between a specific URL path and a function that handles the request. When a client makes a request to that path, Rocket executes the associated handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1307c70-1a6b-480b-9b7a-a58226776bca', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you optimize Django for high-concurrency environments?', N'Middle', N'Optimization involves using an asynchronous server like Gunicorn or Uvicorn, implementing effective database indexing, and leveraging caching mechanisms like Redis for frequent reads. Additionally, offloading time-consuming tasks to background workers using Celery or similar task queues prevents blocking the main request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6502591c-e4cb-49ef-95a6-a5828ea6a772', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between a query and a filter in Elasticsearch?', N'Intern', N'A query is used to find documents and calculates a relevance score based on how well they match. A filter is used for binary yes/no questions, such as range checks, and does not calculate relevance scores, making it faster to cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bc184ce-0c9d-4aa0-8c3d-a582cc75de65', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt facilitate ''Critical CSS'' extraction to improve First Contentful Paint (FCP)?', N'Senior', N'Nuxt detects which components are being rendered on the server and extracts only the CSS required for those specific components. This critical CSS is then injected directly into the document head, ensuring the browser can render the page style immediately without waiting for external stylesheet downloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
