INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a65bf757-6b37-4c95-9286-a5855ee3f45b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Define the various types of errors which occur in JavaScript?', N'Intern', N'There are three main types of errors that can occur while compiling a JavaScript program: syntax errors, runtime errors ( also called exceptions ), and logical errors. When an exception occurs, an object representing the error is created and thrown. The JavaScript language defines seven types of built-in error objects. 1. Error: The "Error" type is used to represent generic exceptions. This type of exception is most often used for implementing user defined exceptions. 2. RangeError: "RangeError" exceptions are generated by numbers that fall outside of a specified range. 3. ReferenceError: A "ReferenceError" exception is thrown when a non-existent variable is accessed. These exceptions commonly occur when an existing variable name is misspelled. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58f9c94d-3970-47ae-b052-a5895efa54fb', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Discuss the performance impact of PHP''s magic methods on the executor.', N'Senior', N'Magic methods introduce a layer of dynamic dispatch that requires the engine to perform additional checks at runtime. Because these methods are invoked via hooks, they are generally slower than standard method calls and should be avoided in highly performance-critical hot paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b983df1-77a3-4ac8-ad32-a58a2c085a10', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is ''Incremental Static Regeneration'' (ISR) considered a middle ground between SSR and SSG?', N'Senior', N'ISR allows pages to be pre-rendered like SSG, but updates them in the background after a specified duration, offering the speed of static files with the freshness of dynamic content. It eliminates the need for full site rebuilds while providing a much faster response time than traditional SSR.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b5b9ed5-e7b7-4159-b5ea-a58c329ed1f8', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the implications of using ''Refs'' for DOM manipulation in a declarative framework?', N'Senior', N'Refs bypass React''s declarative data flow, creating ''escape hatches'' that can lead to synchronization issues between the DOM state and React''s internal state. They should be used only for non-declarative tasks like manual focus management, scrolling, or integrating with third-party DOM libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c1b9f07-ea97-439a-a381-a58c6648d002', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you decide between using React state, context, and external state managers?', N'Fresher', N'Match the tool to the kind of state. Use useState/useReducer for local component state, and lift state up before reaching for anything heavier. Use React Context to pass values that change rarely (theme, locale, current user) — Context is not a state manager and re-renders all consumers on every change. Reach for a client-state library like Zustand, Jotai, or Redux Toolkit when many unrelated components need to share frequently-changing state. Critically, treat server state separately: TanStack Query, SWR, or RTK Query handle caching, refetching, and invalidation far better than any general-purpose store. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'866a4549-1337-49ce-8c47-a58e5942ef79', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are render props?', N'Intern', N'Render Props is a simple technique for sharing code between components using a prop whose value is a function. The below component uses render prop which returns a React element. Libraries such as React Router and DownShift are using this pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59d37e09-931d-4103-82f7-a58e730f6fba', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the architectural benefits of Protocol-Oriented Programming in Swift over traditional class inheritance?', N'Senior', N'Protocol-oriented programming promotes composition over inheritance, allowing for more flexible and decoupled designs. By defining capabilities through protocols, you avoid the rigid deep inheritance hierarchies that often become fragile and difficult to maintain as the system scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07e0cc3e-669d-48c1-91cb-a58ebb8daea2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of attribute reflection in Lit and when should you avoid it?', N'Middle', N'Attribute reflection synchronizes a property value with a DOM attribute, making it visible to CSS selectors and global DOM queries. You should avoid it for frequently changing data or complex objects, as it can cause significant performance overhead due to constant DOM string serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33844396-fa92-4ac1-9536-a5915f3a3cf5', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is Dependency Injection in NestJS?', N'Intern', N'Dependency Injection is a design pattern where a class requests dependencies from external sources rather than creating them itself. NestJS uses a built-in dependency injection container to manage the instantiation and lifecycle of these dependencies automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9941073e-5018-4941-a970-a59162a390b0', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL transaction?', N'Fresher', N'A transaction is a logical unit of work that contains one or more SQL statements. It ensures that either all operations within the unit are completed successfully or none of them are, maintaining the database in a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9a68394-87c6-4b9c-909a-a59366e83e39', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is boxing and why should it be avoided in performance-critical code?', N'Middle', N'Boxing is the process of converting a value type into an object reference, which involves allocating memory on the heap and copying the value. Frequent boxing and unboxing operations create unnecessary garbage collector pressure and overhead, potentially degrading application performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f831ab-975a-4562-8ea3-a59421d3035a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the ''require'' statement?', N'Intern', N'The ''require'' statement is used to load external libraries or files into the current Ruby script. It ensures that the code within those files is available for use by the current program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42d94b0e-cf83-450e-8987-a594edd9f011', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the role of the ''Accept'' header in content negotiation?', N'Middle', N'The ''Accept'' header allows the client to specify which media types they are capable of understanding, such as JSON or Protobuf. The server uses this to determine the appropriate format to return, enabling a single endpoint to support multiple client requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdda91a5-f840-46cc-a7d7-a5977fd22100', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS handle pseudo-classes and pseudo-elements?', N'Middle', N'Tailwind handles pseudo-classes like hover, focus, or active by using modifier prefixes attached to utility classes. This allows for conditional styling directly within the HTML without needing to write custom CSS rules for every interactive state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c60dedf-bfd5-418e-bdba-a597cd2b65ca', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the benefit of using ''prepend'' over ''include'' for module integration.', N'Middle', N'While ''include'' adds a module above the current class in the lookup chain, ''prepend'' adds it below the class. This allows the module''s methods to override or wrap methods defined in the class, which is highly effective for cross-cutting concerns like logging or instrumentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6462ea43-c761-4c16-949e-a59bf513e5e0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why are database constraints important?', N'Intern', N'Database constraints are rules placed on data columns to ensure the accuracy and reliability of the information. They prevent invalid data from being entered, such as duplicates or inappropriate types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3c5e9ba-4bbe-4b0c-8985-a59e514d8bab', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When is it appropriate to use a PATCH request instead of PUT?', N'Middle', N'PUT is meant for replacing an entire resource, requiring the client to send the full state. PATCH is used for partial updates, allowing the client to send only the fields that need to be changed, which saves bandwidth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97ec6032-c956-4170-9c3d-a59e87264c66', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is PostgreSQL?', N'Intern', N'PostgreSQL is an open-source, object-relational database management system. It is known for its reliability, feature robustness, and strict adherence to SQL standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13a6f2fc-6af1-4b20-82e0-a5a04aabac12', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the PostgreSQL query planner use statistics?', N'Middle', N'The planner uses statistics collected by the ANALYZE command to estimate the cardinality and distribution of data in tables. These estimates help the planner choose the most efficient join algorithms and execution paths, such as deciding between a sequential scan and an index scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca8f19ff-8293-4ded-9619-a5a2953bbda0', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the trade-offs of using Flask-SQLAlchemy compared to writing raw SQL?', N'Middle', N'Flask-SQLAlchemy provides an abstraction layer that makes database interactions more readable and portable across different database engines. The trade-off is the overhead of the ORM and the risk of inefficient queries, which can be harder to debug or optimize compared to hand-written, fine-tuned SQL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
