INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bc76736-a5ed-40cb-be16-a5b50d5cb8ad', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of using Preact Signals over standard state management?', N'Middle', N'Signals provide an observable-based state management system that allows for fine-grained updates. Instead of re-rendering entire component trees, signals trigger updates only in the specific parts of the DOM that depend on that data, significantly boosting performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
