INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d7cc568-d56a-4b8e-9802-a5b8977ab294', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you determine if an issue is caused by the infrastructure or the application code?', N'Middle', N'I would analyze telemetry data from both the host environment and the application layer. If system-level metrics like disk I/O, network drops, or kernel errors correlate with the failure, it is likely infrastructure-related, whereas consistent application-layer errors or stack traces suggest a logic bug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72d0c51d-7df6-45c6-95ab-a5bc2f9deafe', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Compare the performance overhead of using Streams versus standard asynchronous futures.', N'Senior', N'Streams represent a sequence of asynchronous events and involve higher overhead due to subscription management and event propagation mechanisms. Futures are lightweight, one-time asynchronous objects; using streams for simple one-off tasks introduces unnecessary complexity and potential memory leaks if subscriptions are not properly managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
