INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df4477b3-5841-4987-879d-a5cf4612b3b3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is it important to use a function to access signal values in templates?', N'Middle', N'Accessing the signal as a function call establishes the dependency relationship between the template and the signal. If you simply pass the value, the framework cannot track the dependency, and the UI will not update when the signal changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a29fdcaf-ab82-4d66-9113-a5cf6440f5ed', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do Rocket responders facilitate content negotiation?', N'Middle', N'Responders are types that implement the Responder trait, defining how data should be serialized into an HTTP response. Rocket uses this to automatically handle content negotiation based on the request''s Accept header, allowing a single handler to return data in multiple formats like JSON or HTML depending on the client''s needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0156ae15-f7f7-4a6e-84e5-a5d690bfe5ba', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the role of ''Continuation'' in the internal representation of a coroutine?', N'Senior', N'A Continuation is an interface that represents the state of a suspended computation, holding the stack frame and the current execution point. When a coroutine suspends, the state is serialized into this object, allowing the scheduler to resume the computation at a later time on a different thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9b684de-7f08-4bba-a485-a5da3a310fa1', N'075b8862-431c-4678-9767-f55359758a4a', N'Why mutations should be synchronous?', N'Fresher', N'You need to remember that mutation handler functions must be synchronous. This is why because any state mutation performed in the callback is essentially un-trackable. It is going to be problematic when the devtool will need to capture a "before" and "after" snapshots of the state during the mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dfcf6a0-0957-4516-8a3c-a5def80fe978', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of using the ''class'' attribute over ''className'' in Preact?', N'Fresher', N'Preact supports the standard ''class'' attribute directly on DOM elements, which aligns more closely with standard HTML. While ''className'' is supported for compatibility, ''class'' is often preferred for its simplicity and direct mapping to HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17258f04-3190-4698-8c09-a5e2fc0d0e76', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''Coherence'' rule for trait implementations prevent conflicts?', N'Senior', N'The coherence rule, specifically the orphan rule, prevents trait implementations that could conflict with future or third-party implementations. It mandates that a trait can only be implemented for a type if either the trait or the type is defined within the current crate, ensuring a predictable and stable trait resolution process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e95e7d0-0886-48c4-82f2-a5e519ffc32f', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s session management handle data persistence across requests?', N'Middle', N'PHP creates a unique session ID, typically stored in a browser cookie, which acts as a key to retrieve data stored on the server. This allows stateful information to be maintained across multiple stateless HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d162c7-fa16-4d9d-9fd3-a5e64f97db37', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of Structural Typing in TypeScript.', N'Middle', N'TypeScript uses a structural type system, meaning compatibility is determined by the shape of the data rather than its explicit declaration. If two objects have the same properties and types, they are considered compatible regardless of their inheritance or naming. This promotes flexibility but requires careful handling of extra properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04b2b5dd-ce22-4377-a54f-a5e76e302ca3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the key differences between Python 2 and 3?', N'Intern', N'- Text and Data instead of Unicode and 8-bit strings. Python 3.0 uses the concepts of text and (binary) data instead of Unicode strings and 8-bit strings. The biggest ramification of this is that any attempt to mix text and data in Python 3.0 raises a TypeError (to combine the two safely, you must decode bytes or encode Unicode, but you need to know the proper encoding, e.g. UTF-8) - This addresses a longstanding pitfall for naïve Python programmers. In Python 2, mixing Unicode and 8-bit data would work if the string happened to contain only 7-bit (ASCII) bytes, but you would get UnicodeDecodeError if it contained non-ASCII values. Moreover, the exception would happen at the combination point, not at the point at which the non-ASCII characters were put into the str object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c36555-5418-492d-ad89-a5e7e40aed7e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the role of ''Time-to-Market'' in engineering trade-offs?', N'Intern', N'Time-to-market is the duration it takes to get a product into the hands of users. Engineers often trade away ''extra'' features or perfect architecture to ensure the product launches in time to meet a specific market window or competitor deadline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72636258-19e4-4ba6-b6c0-a5e81c4ab257', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does a Python function work?', N'Fresher', N'Python functions are first-class objects that encapsulate logic, enable reusability, and manage state through scoping. In Python, a function is an instance of the function class, allowing it to be passed as an argument, returned from other functions, and assigned to variables. Key Components - Function Signature: Defined by the def keyword, it includes the name, parameters (positional, keyword-only, or variadic), and optional type hints for static analysis. - Function Body: An indented block of code containing the logic. Python compiles this into bytecode (stored in the code attribute) upon definition. - Return Statement: Explicitly exits a function with a value. If omitted, the function implicitly returns the None singleton.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4be4608e-b266-4e6a-b8eb-a5e846f920ac', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are ''Bloom Filters'' and how do they optimize read operations in LSM-based databases?', N'Senior', N'Bloom filters are probabilistic data structures that quickly determine whether an element is definitely not present in a file or potentially present. By checking the Bloom filter before performing an expensive disk read, the database avoids searching unnecessary SSTables, significantly reducing I/O latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e19872c6-8ff0-4f5a-88d6-a5e8c0ecabbb', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Describe the internal structure of a ZVAL and why its size matters for memory optimization.', N'Senior', N'A ZVAL is the union-based container for all PHP variable types, containing the type, value, and reference management metadata. Because every variable is a ZVAL, minimizing the number of variables and avoiding unnecessary copies is essential for managing memory pressure in memory-constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef91609-6b58-4260-841e-a5ec159a295d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the trade-offs of using Worker Threads versus the Cluster module?', N'Middle', N'Cluster is best for scaling an entire HTTP server across CPU cores, while Worker Threads are designed for offloading CPU-intensive tasks like data processing within a single process. Worker Threads are more memory-efficient because they share the same process memory space, whereas clusters require separate memory for each instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b20a15ab-4ac5-4428-8041-a5ec37c4cf29', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is an interceptor in Quarkus?', N'Junior', N'An interceptor is a mechanism used to cross-cut application logic, such as logging, security, or transaction management. It allows you to wrap method calls with additional behavior without modifying the original business logic code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'505c5259-eb2b-44a5-aa20-a5f1998a6100', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you serve static files using Express.js?', N'Fresher', N'In an Express.js web application, you often need to serve static files such as stylesheets, client-side JavaScript, and images. You can accomplish this using the express.static middleware. Middleware for Serving Static Files The express.static middleware function serves static files and is typically used to serve assets like images, CSS, and client-side JavaScript. Here is the code example: In this example, the folder named public will be used to serve the static assets. Additional Configuration with Method Chaining You can further configure the behavior of the express.static middleware by chaining methods. For example, to set the cache-control header, the code looks like this: Here, the ''1d'' ensures that caching is enabled for a day.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecacab6d-efed-4627-a90c-a5f205f7ff82', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'In what scenario would you prefer using a ''Controller'' over standard routing functions?', N'Middle', N'Controllers are preferred when you need to group related endpoints under a shared path prefix or apply common dependencies and guards to a set of routes. This improves code organization and reduces redundancy for complex API structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcee73ec-0835-49c7-aa77-a5f253fded62', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Can Lit components be used outside of a Lit application?', N'Fresher', N'Yes, because Lit components are standard web components, they can be used in any environment that supports custom elements. This includes plain HTML files, React applications, Angular projects, or Vue applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40c3ea43-2d90-4dc8-81c1-a5f5276da386', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is a Request Extractor in Axum?', N'Intern', N'Extractors are a mechanism in Axum used to pull data out of an HTTP request. They allow you to automatically deserialize request components like headers, path parameters, or JSON bodies into Rust types that your handler functions can use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c591d6fc-91ac-4de7-91cc-a5f718a3c686', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of ''c.Abort'' in Gin?', N'Intern', N'The c.Abort method stops the execution of the pending handlers in the middleware chain. It is typically used when a request fails validation or authentication, preventing the main handler from ever being executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
