INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd1d6440-fc54-41ee-867e-a5f9a901c5fc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are given a task with ambiguous requirements, what is your first step?', N'Fresher', N'My first step is to document the unclear areas and schedule a meeting with stakeholders to ask clarifying questions. I believe it is better to seek alignment early rather than making assumptions that could lead to rework later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2282de04-93d5-45d4-990f-a5fdcdf18b1e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is middleware in the context of Echo?', N'Intern', N'Middleware consists of functions that are executed during the lifecycle of an HTTP request, either before or after the main handler. It is commonly used for tasks such as logging, authentication, recovery from panics, and modifying request headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85321045-fde3-4a24-be35-a5ff9472303d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is it important to use ''hasChanged'' in a property declaration?', N'Middle', N'The hasChanged function allows you to define custom logic to determine if a property update should trigger a re-render. This is crucial for performance optimization when dealing with complex objects or arrays where a deep equality check might be needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e74e215a-d32b-4e4d-9e11-a603de68e6ea', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is database sharding used, and what is its main drawback?', N'Middle', N'Sharding is used to distribute a large dataset across multiple database instances to improve horizontal scalability and throughput. The main drawback is the increased complexity in application logic, specifically regarding cross-shard joins and maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b1a66dc-4b9b-45d2-bd5f-a603f9e9fb43', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What trade-offs should be considered when choosing Hono for a high-traffic microservice?', N'Middle', N'Hono provides extreme performance and minimal cold start times, which is ideal for serverless architectures. The trade-off is that it lacks the extensive ecosystem of plugins and deep middleware library support that mature frameworks like NestJS offer, potentially requiring more custom implementation for complex enterprise features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85c29e1f-314b-4e06-b41f-a606e47339ca', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the Laravel Service Layer?', N'Junior', N'While not a built-in feature, the Service Layer is a design pattern used to keep controllers thin. It involves moving business logic into dedicated service classes, ensuring that controllers only handle the request-response cycle and delegate the heavy lifting to these services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
