INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'335716f1-14ad-4bd6-9039-a631058b793e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between array_push and $array[] = ?', N'Junior', N'Both add elements to an array, but $array[] = is generally preferred for adding a single element because it is faster and more concise. array_push is useful when you need to add multiple elements at once to an array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd98b282-2757-4737-881b-a63168afe268', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why should you use ''const'' with pointers?', N'Junior', N'Using ''const'' with pointers allows you to enforce read-only access to the data they point to, which prevents accidental modification. It provides a layer of safety and documentation for other developers, signaling that a function will not change the contents of the passed memory. This practice reduces bugs related to unintended side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd48b332d-c958-4d9c-96e9-a6337705b46e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s architecture achieve higher throughput compared to Express?', N'Senior', N'Fastify utilizes a highly optimized internal router based on a Radix Tree implementation, which performs faster lookups than the linear middleware iteration used by Express. Additionally, Fastify is designed to be low-overhead by minimizing object allocation and using a faster JSON serialization library called fast-json-stringify.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fd623cc-e208-410a-a2e0-a63384c5b368', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s manifest file generation support backend integration?', N'Senior', N'Vite generates a manifest file that maps raw source filenames to their hashed, production-ready output filenames. This allows backend frameworks like Ruby on Rails or Laravel to dynamically inject the correct script tags and asset paths into HTML templates, facilitating seamless integration between the frontend build and server-side templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d0eb649-26fe-4bc4-a456-a634ca3acf82', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with an error, how do you determine the root cause rather than just fixing the symptom?', N'Intern', N'I use a systematic process of elimination by isolating components to see where the behavior deviates from the expected outcome. By tracing the data flow or the sequence of events leading up to the error, I can identify the underlying issue rather than just applying a temporary patch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e46fa3d1-7906-4353-b05d-a636c79e8724', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you maintain distributed tracing in a microservices environment?', N'Senior', N'Distributed tracing is achieved by injecting a unique correlation ID into the header of every request that enters the system. This ID is passed through all downstream service calls, allowing observability tools to reconstruct the entire request lifecycle across multiple services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efac8d03-287f-422c-9b8a-a639fa057635', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to handling ''noisy neighbor'' issues in a multi-tenant cloud environment?', N'Senior', N'I would implement strict resource quotas and rate-limiting at the API gateway layer to prevent any single tenant from exhausting shared resources. Additionally, I would favor resource isolation techniques such as dedicated compute clusters or separate database schemas if the SLA requirements necessitate strict performance guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36881681-d9c9-4711-a7e8-a63a7c0f8392', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If two team members provide very different estimates for the same task, how would you resolve the discrepancy?', N'Fresher', N'I would facilitate a discussion where both members explain their reasoning and the assumptions they made. This often reveals that one person may have considered a technical risk or detail that the other overlooked, leading to a more comprehensive and accurate estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2bdce6d-661d-46cb-a3ea-a63d52daeb8a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for maintaining system performance as the volume of data grows significantly?', N'Middle', N'I implement database indexing, query optimization, and data partitioning strategies like sharding to keep read/write performance within acceptable bounds. I also periodically re-evaluate the storage architecture to ensure it scales gracefully with the increasing data footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f48dc206-d814-41a2-b4d9-a63f8d286999', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prefer standard Web APIs over proprietary framework-specific abstractions?', N'Senior', N'By adhering to standards like the Fetch API and Request/Response objects, Remix ensures developers build against the platform rather than the framework. This approach increases long-term code maintainability and allows for easier deployment across different serverless environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8da8e86-b307-4d03-8a6b-a641d823626c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary benefit of using Tailwind CSS compared to writing custom CSS?', N'Fresher', N'The primary benefit is the speed of development and consistency in design. It eliminates the need to constantly switch between HTML and CSS files and prevents the common issue of naming classes, as you use a predefined system of utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64de4811-811f-482e-a8fd-a642a84d2ce7', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How can Hono be used to implement a ''Backend-for-Frontend'' (BFF) pattern effectively?', N'Senior', N'Hono is ideal for a BFF because it can efficiently aggregate multiple backend service calls into a single response while implementing authentication and request transformation at the edge. Its speed ensures that the BFF layer does not become a performance bottleneck for the frontend client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d914835-e42e-4b91-9b04-a6464bb56112', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is Actix-web often cited for its high performance in benchmarks?', N'Senior', N'Its performance is primarily due to the combination of Rust''s low-level memory management and the efficient, zero-copy design of the HTTP stack. Furthermore, its ability to scale across multiple CPU cores without contention makes it highly effective for compute-intensive web services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c720f621-fc39-427d-aff0-a64665a21fdc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the Fastify ''test'' utility?', N'Intern', N'Fastify provides helper utilities that make it easy to inject requests into the application for testing purposes. These utilities allow developers to verify that routes and plugins behave correctly without needing to start a full network server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afa7276a-94c0-45c1-808a-a648dbf765e1', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Does Flask have a built-in database ORM?', N'Fresher', N'No, Flask does not have a built-in ORM. Developers typically use extensions like Flask-SQLAlchemy to integrate database management and object-relational mapping into their applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ce4697-4ce1-4fc6-8afd-a6492eebf31f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between ''is'' and ''=='' in Python and when to use each.', N'Senior', N'The ''=='' operator checks for value equality by calling the __eq__ method, while ''is'' checks for object identity by comparing memory addresses. You should use ''=='' for comparing content and ''is'' primarily when checking for singleton objects like None.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'040f9f59-a83b-4c5b-8e7b-a649a1d36a79', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do namespaces in R influence package development and dependency resolution?', N'Senior', N'Namespaces provide a private scope for a package, ensuring that internal functions do not collide with the global environment or other packages. They explicitly define exported and imported symbols, which is crucial for maintaining a stable and reliable dependency graph in complex systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3db2e842-5478-4e27-97c6-a64bc0fa74fc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to reflect on completed tasks?', N'Fresher', N'Reflection allows me to identify what went well and what could be improved in my process. This practice turns individual experiences into lessons, helping me become more efficient and effective in future problem-solving.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f89f671-808e-4a5e-ba72-a64d787e6372', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a scenario where you have incomplete information to provide an estimate?', N'Fresher', N'I would explicitly state my assumptions and the missing variables. I would provide a range estimate—best case, worst case, and most likely—rather than a single number, highlighting that the estimate will be refined as more information becomes available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9006e6d-0a9b-4300-866d-a6563a976aca', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What architectural risks are associated with using ''ThreadLocal<T>'' in a multi-threaded server environment?', N'Senior', N'ThreadLocal ensures each thread has its own isolated instance of a resource, preventing contention, but it can cause excessive memory consumption if threads are frequently created and destroyed. Furthermore, it may lead to resource leaks if the values stored in the thread-local storage are not explicitly disposed of when no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a43cf402-5741-4e7b-8913-a65656c136c4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are properties in C# and why are they used?', N'Fresher', N'Properties provide a flexible mechanism to read, write, or compute the value of private fields. They allow you to encapsulate data by using accessors, which enables validation or logic to be executed whenever a value is accessed or modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47227840-3688-4807-99c3-a65819e71163', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the strategic advantage of using ''Payload Extraction'' in static site generation (SSG)?', N'Senior', N'Payload extraction allows Nuxt to separate the data required for a page from the HTML shell. This enables ''fast navigation'' by fetching only the JSON data for subsequent pages rather than reloading the entire HTML structure, significantly reducing bandwidth and improving perceived performance for end-users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd220a921-9826-46e2-8703-a6597d4cfa9a', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular DSL?', N'Intern', N'A domain-specific language (DSL) is a computer language specialized to a particular application domain. Angular has its own Domain Specific Language (DSL) which allows us to write Angular specific html-like syntax on top of normal html. It has its own compiler that compiles this syntax to html that the browser can understand. This DSL is defined in NgModules such as animations, forms, and routing and navigation. Basically you will see 3 main syntax in Angular DSL. 1. (): Used for Output and DOM events. 2. []: Used for Input and specific DOM element attributes. 3. *: Structural directives(*ngFor or *ngIf) will affect/change the DOM structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9dc88be-2451-40b6-936a-a65c228f49bc', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you access parent instance?', N'Fresher', N'The $parent object refers to the immediate outer scope. The parent will be accessible as this.$parent for the child, and the child will be pushed into the parent''s $children array. It establishes a parent-child relationship between the two instances(parent and child). You can access parent data and properties similar to $root.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7774ab0c-8fdf-4a2b-ac0c-a65dd5d50c2f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What does ''reflect'' mean in the @property decorator?', N'Intern', N'The reflect option allows a property value to be synchronized back to the element''s HTML attribute. This is useful for styling the component based on its state using CSS attribute selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57a9fd83-6dfe-459c-86ac-a66048113b32', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go''s approach to concurrency differ from traditional thread-based models?', N'Middle', N'Traditional threads are heavy and managed by the OS, leading to significant overhead when creating large numbers of them. Goroutines are managed by the Go runtime, require much smaller initial stack sizes, and can be created or destroyed by the thousands with minimal performance impact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b05b5d0d-3280-43ce-a017-a661958da517', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a route handler in Rocket?', N'Intern', N'A route handler is a function that is associated with a specific URL path and HTTP request method. When a request matches the defined path, Rocket executes the handler function to generate a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0a4b9d8-1e41-4cf2-b9b2-a6622d29672a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why should you never store plain-text passwords in a database?', N'Fresher', N'If the database is ever breached, storing passwords in plain text gives attackers immediate access to every user''s account. Passwords should always be hashed using a strong, salted algorithm so that even if the database is exposed, the original passwords remain unreadable. This is a fundamental security requirement for protecting user data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9fb9633-be00-4a08-bd1d-a663189e704e', N'954a0331-deff-4399-b588-96f39fec001d', N'What is TestBed and how is it used in Angular testing?', N'Fresher', N'TestBed is the primary utility in Angular''s @angular/core/testing module used to configure and create a testing module environment. It allows you to set up the necessary components, services, imports, and providers required to test a specific part of your Angular application, such as a component or a service, in isolation or with controlled dependencies. You typically use TestBed within a beforeEach block in your test file to: - Configure a testing module using TestBed.configureTestingModule({...}), similar to defining an @NgModule. - Create instances of components using TestBed.createComponent(YourComponent). - Get instances of services or other injectables using TestBed.inject(YourService).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b98f332-043e-40f5-bee0-a66507fbe47d', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the architectural trade-offs of using a request-response model versus an asynchronous message-passing model.', N'Senior', N'Request-response is simpler to implement and debug, but it creates tight coupling and synchronous dependencies between services. Asynchronous message-passing decouples services and improves resilience by allowing for buffering and retries, but it introduces complexity in error handling and requires managing eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88850715-91a6-43d4-816d-a6668ae80336', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does Lucid ORM simplify database interactions in AdonisJS?', N'Fresher', N'Lucid ORM provides an abstraction layer that allows developers to interact with the database using object-oriented syntax rather than raw SQL queries. It handles the mapping between database tables and application models, simplifying tasks like creating, reading, updating, and deleting records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bfe4732-cc54-4ec8-9ea1-a669c5d857f2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Discuss the impact of HTTP/2 on Axum''s connection handling.', N'Senior', N'Axum relies on the underlying Hyper library for HTTP/2 support, which enables multiplexing multiple requests over a single TCP connection. This significantly reduces latency and resource consumption compared to HTTP/1.1, as the framework can handle multiple streams concurrently within the same connection context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'790f6092-93c3-42ae-8396-a6715bed98bb', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary goal of the Fastify framework?', N'Intern', N'The primary goal is to provide a highly efficient web server that maximizes throughput. It achieves this by using a fast internal router and a highly optimized serialization process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65c35f39-5a0c-453a-bdff-a672556b732f', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is name mangling and why does it occur in C++?', N'Middle', N'Name mangling is the process where the compiler transforms function and variable names into unique internal symbols to support features like function overloading and namespaces. This ensures that the linker can distinguish between functions with the same name but different signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f84dbedb-5b93-42e9-9aee-a672f9418166', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why does DynamoDB limit the number of global secondary indexes per table?', N'Senior', N'Every GSI requires synchronous or asynchronous overhead to keep the index updated whenever the base table changes. Limiting the number of GSIs prevents significant write latency and complex synchronization issues that could degrade system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b3114e3-6a62-478b-911a-a676b0b08da2', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the benefits of using generics in C#?', N'Middle', N'Generics provide type safety by allowing classes and methods to operate on specified data types without requiring casting or runtime type checks. They also improve performance by reducing the need for boxing value types and allow for code reuse by defining logic that is independent of specific data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4570749-05c1-4bb1-8e02-a677a035c178', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the benefits of using currying and partial application?', N'Intern', N'Currying transforms a function with multiple arguments into a sequence of functions, each taking a single argument. This allows for more flexible and reusable code. Partial application, on the other hand, allows you to fix a few arguments of a function and generate a new function. Both techniques help in creating more modular and maintainable code. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Provide some examples of how currying and partial application can be used Currying transforms a function with multiple arguments into a sequence of functions, each taking a single argument. Partial application fixes a few arguments of a function, producing another function with a smaller number of arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2db72a1-fc28-4a84-8004-a6797121b563', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does ''Refinement'' lookup differ from standard module inclusion?', N'Senior', N'Refinements are only active within the scope where they are explicitly imported using the ''using'' keyword. Unlike standard module inclusion, which affects the entire class hierarchy globally, refinements provide a localized change that does not leak into other parts of the application, ensuring safer monkey-patching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b01c0022-8d8d-45d9-b5dd-a679ae2ef434', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are document data types in DynamoDB?', N'Fresher', N'Document types allow you to store complex data structures within a single attribute. They include lists and maps, which enable you to store nested data hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a181abff-d200-4ff1-aaf0-a679bad0609f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of the ''unknown'' type, and how does it improve type safety compared to ''any''?', N'Senior', N'Unknown is a type-safe counterpart to any because it forces the developer to perform type checking or narrowing before performing operations on a value. Any disables the type checker entirely, whereas unknown preserves the integrity of the type system by requiring explicit validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c68fa3ab-bedc-46ba-b96f-a67d03e0364b', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are BASE properties?', N'Fresher', N'BASE stands for Basically Available, Soft state, and Eventual consistency. It is an alternative to the traditional ACID model used in some NoSQL systems to prioritize high availability and speed over immediate consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'296eadd4-9ff2-49cb-a514-a67dfa72f9de', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle error boundaries in the component tree?', N'Senior', N'Preact implements error boundaries through a standard lifecycle method that catches errors in child components during the render phase. It maintains a simplified approach, ensuring that errors are caught and handled without the overhead of the more complex error-reporting and recovery stacks found in modern React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'482519c6-e1b3-4934-aca4-a67ed72ddae9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the trade-offs of using ''inline'' CSS versus external stylesheets in the HTML document?', N'Senior', N'Inlining critical CSS reduces the number of round-trips required to render the initial viewport, improving performance. However, it prevents the browser from caching the CSS separately and increases the overall HTML payload size, which can be detrimental for sites with large amounts of shared style code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
