INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'975eedbf-8d47-44d8-aa74-a68123bd7f64', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between state and props in React?', N'Fresher', N'State is data a component owns and can update over time; props are data a component receives from its parent and is not allowed to mutate. State changes trigger a re-render of the owning component (and its descendants); prop changes happen because the parent re-rendered with new values. Together they implement React''s one-way data flow: state lives at the lowest common ancestor that needs it, flows down as props, and changes flow back up via callbacks passed as props. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c77c9feb-cbdb-417d-b5fb-a681e58a8caf', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why would you use a CSS loader?', N'Intern', N'A CSS loader is necessary because Webpack, by default, only understands JavaScript. The loader allows Webpack to interpret CSS files as modules, enabling you to import stylesheets directly into your JavaScript components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c273d66-37b0-4b68-a2bc-a682ea37c74e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a primary key and why is it important?', N'Fresher', N'A primary key is a specific column or set of columns that uniquely identifies each record in a database table. It is essential because it prevents duplicate records and allows the database to retrieve specific data efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
