INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1471b8b-fcb1-46b5-9f86-a687cf3ae82b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the risks of ''utility sprawl'' in a large codebase, and how can they be mitigated?', N'Senior', N'Utility sprawl occurs when templates become unreadable due to excessive class strings. This is mitigated by enforcing component extraction, using template partials, or employing JavaScript-based logic to compose class names into reusable abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b5cd29c-c2e7-404d-a533-a6882acc696c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is dynamic typing?', N'Intern', N'Dynamic typing means that variable types are checked at runtime rather than at compile time. In Ruby, you do not need to explicitly declare the type of a variable, as the type is determined by the value assigned to it during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b7d07fd-de7c-4aba-951a-a688ab9f9d5d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus support monitoring and metrics?', N'Intern', N'Quarkus provides built-in support for exposing metrics in a format compatible with monitoring tools like Prometheus. This allows developers to easily track application performance, such as request counts and execution times, without manual implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce2fd675-6552-4e1e-8ea1-a68923e0065f', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does database indexing affect write performance?', N'Middle', N'While indexes significantly speed up read queries, they impose a penalty on write operations. Every time a record is inserted, updated, or deleted, the database must also update the corresponding index structures, which consumes additional I/O and CPU.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2536bf5c-42e9-443e-86e9-a68c9ffcf2dc', N'4c000000-0000-0000-0000-000000000005', N'How do you achieve high availability in a system that relies on a single leader for writes?', N'Senior', N'High availability is achieved through automated failover mechanisms, such as using a consensus algorithm like Raft or Paxos to elect a new leader when the current one fails. Additionally, synchronous or asynchronous replication ensures that data is replicated to standby nodes for quick promotion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8353f569-16b7-4bc0-b702-a68d8ab00280', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does Durability guarantee?', N'Fresher', N'Durability guarantees that once a transaction has been committed, it will remain committed even in the event of a system failure, such as a power loss or crash. The changes are permanently recorded in non-volatile memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'222416d9-5558-4b3c-b3af-a68db06d155d', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the special handling for null values in dynamic directive arguments?', N'Intern', N'Dynamic argument values are expected to be strings but it allows null as a special value that explicitly indicates that the binding should be removed. Other types will be treated as mistakes and will trigger a warning. So null value can be applied for v-bind and v-on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae113d8-2197-4220-b308-a690e4d46428', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the role and lifecycle of Interceptors in the NestJS request-response pipeline.', N'Senior', N'Interceptors utilize the RxJS Observable stream to wrap the execution of route handlers. They can perform logic both before and after the handler executes, enabling cross-cutting concerns like logging, response transformation, or caching by manipulating the underlying stream.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aee891de-8d6a-45e6-997e-a694e95bc40a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage bean lifecycle events and what are the benefits of using them?', N'Senior', N'Micronaut allows developers to hook into the bean lifecycle using annotations like @PostConstruct or @PreDestroy. These events provide controlled points for initializing resources or cleaning up connections, ensuring that the application remains stable and avoids memory leaks during startup or shutdown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcc39d46-e9bd-408e-9238-a694edb66ebb', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the function of the .css() method in jQuery?', N'Fresher', N'The .css() method is used to get or set one or more style properties for the selected elements. It allows developers to dynamically change the visual appearance of page elements based on user interaction or other events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c398987b-019c-4738-9b25-a695df2c6623', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the memory overhead associated with R''s ''vectorized'' operations.', N'Senior', N'While vectorized operations are faster, they often require the creation of temporary intermediate vectors of the same size as the input. For extremely large datasets, this can cause memory spikes that exceed system limits, necessitating chunked processing or streaming architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78180354-f403-4143-b238-a697bc88fe3a', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is idempotent design crucial for reliable distributed message processing?', N'Senior', N'In distributed systems, network failures often lead to retries, causing messages to be processed multiple times. Idempotency ensures that processing the same message repeatedly does not change the state beyond the initial successful application, preventing data corruption and inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9905c48c-9263-4b21-b21f-a69a6a14ed95', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the core concept of Resumability in Qwik?', N'Intern', N'Resumability is the ability of an application to pause its execution on the server and resume it on the client without re-executing the entire component tree. It allows the browser to pick up exactly where the server left off by serializing the application state and event listeners into the HTML. This eliminates the need for large hydration processes, leading to faster initial load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac09fd00-65c0-4037-b07e-a69b1f210903', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are closures in JavaScript?', N'Junior', N'A closure is a function that remembers the variables from its lexical scope even when the function is executed outside that scope. It allows a function to access variables from an outer function that has already finished execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc1a6cc4-b734-4703-9070-a69b5be23ca9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do HTML ''iframe'' sandbox attributes enhance security?', N'Middle', N'The sandbox attribute restricts the capabilities of the content within an iframe, such as preventing script execution, form submissions, or opening new windows. By applying these restrictions, you mitigate risks like cross-site scripting and unauthorized actions if the third-party content is compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ecc4169-a86d-4f4b-be3b-a69b82044a6f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the @import directive work in Sass?', N'Fresher', N'The @import directive allows you to include the contents of one Sass file into another. This is the primary method for splitting your styles into smaller, manageable partials and combining them into a single compiled CSS file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6fb12f0-f0dd-45b8-aa23-a69cf7efc987', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is ''Cache Poisoning'' and how do you defend against it?', N'Senior', N'Cache poisoning occurs when malicious or malformed data is injected into the cache, causing subsequent requests to serve incorrect or harmful content. Defenses include input validation before populating the cache and using secure headers or signatures to ensure the integrity of the cached content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e5da92a-fb47-4115-aaa7-a69d31e8770c', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is ''std::vector'' generally preferred over ''std::list''?', N'Middle', N'std::vector stores elements in contiguous memory, which provides excellent cache locality and fast random access. While std::list allows for constant-time insertions anywhere, its node-based structure leads to fragmented memory and poor performance due to frequent cache misses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15f671f3-4b4a-4375-9cb0-a69fc43218d1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why are NoSQL databases often preferred for Big Data applications?', N'Junior', N'NoSQL databases are preferred because they are designed to be distributed by default, allowing them to process vast amounts of unstructured data across commodity hardware. Their horizontal scalability makes them cost-effective and capable of handling data growth that would overwhelm traditional centralized SQL databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f874cf38-dc3c-4d7d-84ce-a6a01d49b523', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s architecture support modularity?', N'Middle', N'Rocket supports modularity through ''mount points'' and ''fairings'', which allow different parts of an application to be developed in isolation and combined under a single server instance. This makes it easy to group related routes into modules and apply specific configuration or middleware only to those subsets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73b4c031-13d3-4343-b896-a6a2eaba5ec3', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle the ''Liskov Substitution Principle'' regarding mutable and immutable collections?', N'Senior', N'Kotlin enforces read-only interfaces that do not expose mutation methods, distinct from mutable interfaces. This design prevents runtime errors by ensuring that a reference to a read-only collection cannot be cast to a mutable one, upholding type safety despite the underlying implementation potentially being mutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd18088b-6b20-434d-8152-a6a6c8516310', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix''s ''Plug'' architecture influence the request-response lifecycle?', N'Middle', N'Plug provides a standardized way to compose modular components into a request processing pipeline. It allows developers to easily inject functionality like authentication, logging, or session management by chaining small, reusable functions before the request reaches the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6a47634-8304-4810-b048-a6a774eb1b5f', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a stack and the heap in the context of Rust memory management?', N'Junior', N'The stack stores values with a known, fixed size that are accessed in a last-in, first-out order, making them very fast to allocate. The heap is used for data with a size that might change at runtime, requiring the programmer to manage pointer references, which is slightly slower but more flexible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ace7423-81ef-4d4f-b1f1-a6a799896644', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are anonymous functions?', N'Intern', N'Anonymous functions are functions that do not have a name. They are often used as short-term functions passed into higher-order methods like map or filter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e4b0fc7-30b6-4863-83c2-a6a99b5aac4d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do Redis''s LFU (Least Frequently Used) and LRU (Least Recently Used) eviction policies differ in practice?', N'Senior', N'LRU evicts keys based on the time of last access, which works well for temporal locality but fails if data is accessed in patterns that don''t reflect usage frequency. LFU tracks the frequency of access, making it more effective for workloads where certain keys remain popular over long periods regardless of the last access time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26e1f9b4-5be2-4c45-b6fb-a6ab366e205b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Compare the performance overhead of JSON vs. Protobuf serialization in RPC communication.', N'Senior', N'JSON is a text-based format that is human-readable but incurs high parsing overhead and larger payload sizes due to its verbose nature. Protobuf is a binary format that requires schema definition, leading to significantly faster serialization and deserialization speeds and smaller payloads, which is crucial for low-latency microservice communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbf68418-88dc-4358-a917-a6abe417415f', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What happens if a fiber performs a blocking I/O operation?', N'Intern', N'If a fiber performs a blocking operation, it can stall the entire thread it is running on unless the runtime is designed to handle it. Modern fiber-based runtimes typically use non-blocking I/O primitives to ensure that the thread can switch to another fiber while waiting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'143c8ff5-7f52-4920-88fc-a6ad76a707d1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the trade-offs of using the ''Read Uncommitted'' isolation level?', N'Middle', N'Read Uncommitted offers the highest performance by eliminating locking overhead, but it allows dirty reads where a transaction reads uncommitted data from another. It is generally avoided in systems requiring strict data consistency but may be acceptable for analytical workloads where exact accuracy is less critical than speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'874b1877-4056-4506-8d63-a6b3b56d56c3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When configuring a system, what is the trade-off between hard-coding values and using environment variables?', N'Junior', N'Hard-coding is easier to implement initially but makes the system inflexible and difficult to manage across different environments. Using environment variables enables better configuration management and security, though it requires setting up a robust deployment pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5141dcc0-f9b4-432f-863e-a6b3c4ae9a8e', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the unit type in Rust?', N'Junior', N'The unit type is represented by an empty tuple and is the default return value for functions that do not return anything else. It signifies that the function is called only for its side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'303c96b8-c78b-45b4-9c1e-a6b53af58f37', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain ''Semantic Logging'' and why it is superior to flat-text logs.', N'Senior', N'Semantic logging involves recording events as structured data, such as JSON, rather than unstructured strings. This allows observability platforms to index specific fields, enabling efficient filtering, aggregation, and correlation of events across distributed services without expensive regex parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b0c7fbe-0382-424b-bd63-a6b720f3e83a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Routing in ASP.NET Core?', N'Intern', N'Routing is the process of mapping an incoming HTTP request to an executable endpoint in the application. It determines which controller action should handle the request based on the URL and the HTTP method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89a6533a-6060-4902-a191-a6bd216a20a1', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle route matching performance?', N'Middle', N'Chi uses a radix tree-based routing algorithm to match incoming requests. This approach provides O(k) lookup time, where k is the length of the path, ensuring high performance even with a large number of defined routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70b8b51a-c3fa-4ced-a674-a6c0aa09d275', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a Controller in Spring MVC?', N'Intern', N'A Controller is a class responsible for handling incoming HTTP requests and returning the appropriate response to the client. It acts as an intermediary between the user interface and the business logic of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68499199-631c-44b1-bfc3-a6c10a3cce87', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the advantages of using a graph database over a relational model for social networks?', N'Middle', N'Graph databases excel at managing highly interconnected data where the relationships are as important as the entities themselves. While relational databases require complex joins to traverse deep relationship trees, graph databases store relationships as first-class objects, making traversals significantly faster and easier to query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca47481a-be83-4b66-9373-a6c18124391f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How do you fetch data in an Astro component?', N'Junior', N'You can fetch data directly in the frontmatter of an Astro component using standard fetch calls. Because the frontmatter runs on the server during the build process, the fetched data is available for use in the static HTML template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9feec9fe-0b39-4c68-b4a7-a6c1d3831a69', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When would you choose a push-based model over a pull-based model for service communication?', N'Middle', N'I use a push-based model when immediate updates are required, such as real-time notifications or chat applications. A pull-based model is generally more robust for batch processing or when the consumer has varying processing capacity, as it allows the consumer to control the pace of data ingestion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
