INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cae15a0-8b43-4f54-a1c7-a6f13d47704a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the concept of ''Eventual Consistency'' and why it is necessary for massive scale.', N'Senior', N'Eventual consistency allows for high write availability by accepting that data updates will propagate to all nodes asynchronously. It is necessary for scale because enforcing strict ACID compliance globally would require synchronous locks that drastically increase latency and reduce throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
