INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8ab62df-9794-423a-9c0f-a6f40707369a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is Actix-web considered ''pragmatic''?', N'Intern', N'It is considered pragmatic because it prioritizes developer productivity and performance by providing high-level abstractions for common web tasks. It balances the strict safety guarantees of Rust with the flexible requirements of modern web development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caf44037-4300-4c86-8eaf-a6f676c27ba5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do you optimize critical rendering path performance using HTML resource hints?', N'Senior', N'Resource hints like dns-prefetch, preconnect, and preload allow developers to prioritize critical assets and establish early connections to third-party domains. By strategically placing these in the document head, you reduce round-trip times for essential resources, significantly improving the Largest Contentful Paint metric.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cb45a27-4066-41b4-99bc-a6f78962da5a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the effect of using a function on an indexed column in a WHERE clause?', N'Middle', N'Applying a function to an indexed column prevents the MySQL optimizer from using the index effectively, often resulting in a full table scan. The database engine must evaluate the function for every row to determine if it matches the criteria, which is computationally expensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d3cdad4-c3c7-459b-b28e-a6f8e6fdbb3f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is meant by the term ''Concurrency'' in PostgreSQL?', N'Intern', N'Concurrency refers to the ability of the database to handle multiple users accessing and modifying data at the same time. PostgreSQL uses Multiversion Concurrency Control (MVCC) to manage this without locking rows unnecessarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8da9e109-3b07-4a07-8114-a6f97004a7a5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the common benefits of using JSON in document databases?', N'Junior', N'JSON is human-readable, lightweight, and supports nested data structures, allowing developers to map data naturally to application objects. Its flexibility allows developers to add or remove fields without needing to perform expensive database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76ae3502-b9ce-4037-ac9f-a6fb0f42861b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle data durability and recovery?', N'Senior', N'DynamoDB automatically replicates data across three distinct Availability Zones within a region to ensure high durability. It also supports Point-in-Time Recovery (PITR) to protect against accidental writes or deletes by allowing table restoration to any second within the last 35 days.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60e7ff1a-28b6-42b8-a76a-a6fb2c190a2c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'When would you prefer FastAPI over a framework like Django?', N'Middle', N'FastAPI is preferred for building high-performance microservices, APIs with complex validation requirements, or systems where asynchronous I/O is critical. Django is better suited for monolithic applications that require a full-stack, ''batteries-included'' approach, including ORM, admin panel, and authentication systems out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e652fc42-5753-484d-9189-a6fd7f8203ad', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure you are not creating technical debt while solving problems?', N'Fresher', N'I follow established team guidelines and best practices, keeping my solutions as simple and readable as possible. I avoid ''quick and dirty'' hacks unless absolutely necessary, and I ensure that any workarounds are clearly marked for future refactoring. Keeping the code clean and well-documented from the start prevents it from becoming a burden later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22f019de-c149-4fb7-9973-a6feb4d9e567', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is tail recursion and why is it important in Scala?', N'Middle', N'Tail recursion occurs when a function calls itself as its final action. Scala''s compiler can optimize these calls into a loop, preventing stack overflow errors and allowing for efficient recursion in functional programming patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c7e3b7f-599a-4a3c-9cf7-a700e1f34929', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of the LIMIT clause?', N'Junior', N'The LIMIT clause is used to restrict the number of rows returned by a query. This is particularly useful for pagination or when you only need to see a sample of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0bb1282-4c8d-4967-b1ac-a70117a2f416', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the function of the C preprocessor''s token-pasting operator in a modular architecture?', N'Senior', N'The token-pasting operator allows for the programmatic generation of identifiers at compile time, which is essential for implementing generic patterns or boilerplate reduction. However, it requires careful design to avoid namespace pollution and can make debugging significantly harder as the generated symbols do not exist in the source code directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29adcd36-49e6-46e7-a4f3-a7056bc86cde', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is the separation of ''View'' and ''Controller'' in Phoenix distinct from MVC frameworks in other ecosystems?', N'Senior', N'In Phoenix, the View layer is responsible for data transformation and preparation, while the Template layer is purely for rendering. This separation allows developers to unit test their data-shaping logic independently of the HTML structure, leading to more robust and maintainable codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'468375f0-9b4d-4163-a194-a70635759f4d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What does it mean to consider ''edge cases'' when designing a solution?', N'Intern', N'Edge cases are unusual or extreme scenarios that fall outside the typical operation of a system. Considering them ensures the solution is robust and does not fail catastrophically when presented with unexpected, though valid, inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff9c262e-a99c-45cd-91bf-a70693edc658', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the trade-offs of using Redux in a small project?', N'Middle', N'The main trade-off is increased boilerplate and complexity. For small applications with minimal state sharing, Redux can be overkill, leading to longer development time compared to using local component state or the Context API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd85da263-9410-4542-b71e-a708e2edaa5e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does ''hydration'' mean in the context of Astro?', N'Intern', N'Hydration is the process where client-side JavaScript attaches event listeners and state management to server-rendered HTML. In Astro, this process is optional and explicitly controlled, allowing developers to choose which components need interactivity and which should remain static.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92d3dc9f-3b3c-43f6-9fce-a70e04b90fb3', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are Model Managers?', N'Junior', N'A Manager is the interface through which database query operations are provided to Django models. You can define custom managers to add extra helper methods to your models, allowing you to centralize common database lookup logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebb48a69-7575-4853-add1-a70e1bda41f2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is it important to keep services stateless in NestJS?', N'Middle', N'Stateless services are easier to test, scale, and maintain because they do not rely on local variables that persist between requests. This design allows the DI container to effectively manage singleton instances and makes the application more predictable in concurrent environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c3182a1-4c21-4804-bce4-a70f3ea74560', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Nuxt?', N'Intern', N'Nuxt is an open-source framework built on top of Vue.js. It simplifies the development of web applications by providing a structured architecture and features like server-side rendering, static site generation, and file-based routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba048ee6-dd6e-4229-92a9-a710fb1c66b2', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik achieve its signature ''resumability''?', N'Junior', N'Resumability works by serializing the application state into the HTML itself. When a user interacts with the page, Qwik uses this state to resume execution exactly where it left off on the server, removing the need for a full re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e4f364a-61a2-48d5-9344-a7127ad667ae', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the differences between ES6 class and ES5 function constructors?', N'Intern', N'Classes are a template for creating objects. They encapsulate data with code to work on that data. Classes in JS are built on prototypes but also have some syntax and semantics that are not shared with ES5 class-like semantics. ES6 Classes formalize the common JavaScript pattern of simulating class-like inheritance hierarchies using functions and prototypes. They are effectively simple sugaring over prototype-based OO, offering a convenient declarative form for class patterns which encourage interoperability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88765a6c-11a5-44e8-916d-a712d0fc9b6a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does the ''static'' keyword do?', N'Intern', N'The static keyword defines a property or method that belongs to the type itself rather than to an instance of that type. You access static members directly through the type name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46c26aba-689b-4081-958d-a714cb72dd4b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus implement health checks?', N'Intern', N'Quarkus uses the MicroProfile Health specification to expose endpoints that inform orchestrators like Kubernetes about the application''s status. It allows for readiness probes, which signal when the app is ready to serve traffic, and liveness probes, which signal if the app needs to be restarted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee17dbfb-278f-48cc-9c56-a714ceedd599', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''Intersection Types'' differ from ''Interface Extension'' in terms of object composition?', N'Senior', N'Interface extensions are more performant and provide better error messages because the compiler can optimize them as a single entity. Intersection types are more flexible for merging disparate types on the fly but can lead to ''unresolvable'' types if properties conflict in incompatible ways.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5526d4d3-ef06-4d06-a7d2-a715e2bb39d5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you implement circuit breakers to improve system resilience?', N'Senior', N'I wrap calls to external dependencies in a circuit breaker pattern that monitors error rates or latency thresholds. Once a threshold is crossed, the circuit ''opens,'' immediately failing subsequent requests to prevent cascading failures and allowing the downstream service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae4b0c8b-d970-45c7-9da9-a715e5e021a8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the concept of ''interfaces'' as implicit contracts.', N'Middle', N'An interface in Go defines a set of behaviors that a type must satisfy to be considered an implementation of that interface. Because the implementation is implicit, a type can satisfy multiple interfaces without knowing about them, allowing for highly decoupled architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c01f29-c4bb-41b8-8809-a718d5120e79', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is the selection of a shard key considered irreversible in MongoDB?', N'Senior', N'A shard key determines the physical distribution of data across the cluster, and changing it would require a complete redistribution of all data, which is computationally expensive and operationally complex. Once a collection is sharded, the document structure and the shard key index are immutable to ensure cluster integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'160b92f6-518b-4676-b00e-a72210b02db6', N'4c000000-0000-0000-0000-000000000005', N'How do you handle ''Clock Drift'' in a distributed system requiring ordered events?', N'Senior', N'Since physical clocks can never be perfectly synchronized, use logical clocks like Lamport timestamps or Hybrid Logical Clocks (HLC) to maintain order. HLCs combine physical timestamps with logical counters to maintain a causal order that is also close to real-world time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21ef67b8-e364-47fb-98c3-a7221bcf84df', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between Spring AOP and AspectJ.', N'Senior', N'Spring AOP is proxy-based, meaning it only works on public method calls of Spring-managed beans and has limited pointcut support. AspectJ uses bytecode weaving, allowing it to intercept private methods, constructors, and field access, offering superior performance and flexibility at the cost of complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dec30cd-4f06-4c3f-af21-a72863b641f4', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''Identity Map'' pattern, and does Rails use it?', N'Middle', N'The Identity Map ensures that each database row is represented by only one object in memory within a single request. While older versions of Rails experimented with this, it is not a default feature in modern Rails because it can lead to memory bloat and complex state synchronization issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
