INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cdfdbbd-5dff-46e1-869a-a728b9867d47', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the difference between ''Dispatchers.Default'' and ''Dispatchers.IO'' in terms of thread pool design.', N'Senior', N'Default is optimized for CPU-intensive work and uses a fixed-size thread pool equal to the number of CPU cores. IO is designed for blocking I/O operations and uses a larger, elastic thread pool that can expand to accommodate many waiting threads, preventing exhaustion of the CPU-bound pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74fbc1c4-4937-4574-8fcf-a72a6db92a5b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the difference between Astro''s ''Static'' and ''Server'' output modes in the context of scalability.', N'Senior', N'Static mode generates all pages at build-time, making it ideal for high-traffic sites that can be served directly from a CDN with infinite scalability. Server mode enables dynamic SSR, which allows for per-request customization and data fetching but requires an active backend environment, shifting the scaling burden from the CDN to your server infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79dbddf7-d16a-440f-9dfb-a72ce07f64e6', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is item-level atomicity in DynamoDB?', N'Junior', N'DynamoDB ensures that write operations to a single item are atomic. This means an update to an item either succeeds entirely or fails completely, preventing partial updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd41ddb8b-0e36-4cb5-abac-a72ea5d3f4c7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do constant lookups work in Ruby?', N'Middle', N'Ruby searches for constants starting in the current lexical scope, moving through enclosing modules or classes, and finally checking the inheritance hierarchy. This differs from method lookup, which primarily relies on the object''s class and inheritance chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
