INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f2868a4-5c2b-4f4c-8c25-a73bb2ec95d2', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of a ''Dead Letter Queue'' in an asynchronous messaging system?', N'Middle', N'A dead letter queue is a storage location for messages that cannot be processed successfully after multiple attempts. It ensures that faulty messages do not block the processing pipeline and allows developers to inspect and debug the problematic payloads later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab17f92a-7a1b-456c-a0dd-a73bb6d03ef6', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the impact of heavy middleware chains on Chi''s latency?', N'Senior', N'Every middleware added to the chain increases the stack depth and the number of function calls per request. While negligible in most cases, extreme chaining can lead to stack overhead and increased latency, necessitating a balance between modularity and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1341e43-022c-4a5b-9df3-a73c78d6fc52', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach building a system that needs to be highly available during peak traffic events?', N'Middle', N'I focus on horizontal scaling, load balancing, and implementing robust caching strategies to reduce backend pressure. I also emphasize service isolation and bulkhead patterns to ensure that a failure in one non-critical component does not bring down the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d0154d1-383a-4654-aa0d-a740a2fd9c54', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the response object in Express?', N'Intern', N'The response object represents the HTTP response that an Express application sends when it gets an HTTP request. It provides methods to send data, status codes, and headers back to the client, such as sending JSON or rendering a template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'039be612-a89d-48e0-82de-a744d4d050c1', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the difference between .on() and the older .live() or .delegate() methods.', N'Middle', N'.on() is the unified method for event binding in modern jQuery, replacing deprecated methods like .live() and .delegate(). It provides a consistent and more performant way to handle event delegation and direct event binding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'487685d5-7019-4338-81da-a746406431f5', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is idempotency critical when using message queues?', N'Middle', N'Message brokers often guarantee ''at-least-once'' delivery, meaning a service might receive the same message multiple times. Services must be designed to handle these duplicates gracefully by ensuring that processing the same event twice does not lead to incorrect data states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a3376cd-d3d3-4f97-92fe-a747a43cc8b7', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi support the implementation of RESTful resource hierarchies?', N'Senior', N'By using nested routers, Chi allows developers to mirror the resource hierarchy in the code structure, such as /users/{userID}/posts/{postID}. This mapping makes the code intuitive to navigate and simplifies the application of middleware that is specific to certain resource types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b35908de-0d47-4cc8-aaea-a7491a5d2480', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the Kotlin type inference rules?', N'Intern', N'Kotlin type inference represents a powerful feature that automatically determines variable types. Nonetheless, it does so within the constraints of Kotlin''s Type Hierarchy. - Kotlin types are static, meaning they''re determined at compile time. - The Kotlin compiler analyses assignments and method calls to infer types. - When there are multiple possible types, the compiler selects the most specific one. In case of ambiguity, the code will not compile, and a type annotation is needed to provide clarity. Kotlin also supports type inference with: - Lambda expressions - Generics The Kotlin compiler uses both the expected type and the inferred type of the arguments to infer the type of both return value and the arguments of the run and ''let'' extension function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'590189c9-fc40-4c08-99af-a74bedec72c4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does the R garbage collector (GC) interact with the heap, and what are the performance implications of frequent triggers?', N'Senior', N'R''s GC is a mark-and-sweep collector that operates on the heap, tracking object references to identify garbage. Frequent GC cycles significantly degrade performance by pausing execution, which is particularly problematic when working with large objects that saturate memory thresholds, leading to increased latency in real-time or production workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'131a1e74-9bf5-4258-a1cf-a74d7e873608', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between an interface and a trait?', N'Junior', N'An interface defines a contract that a class must follow, containing only method signatures. A trait is a mechanism for code reuse that allows you to inject actual method implementations into multiple classes without using inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'508c315c-426c-4614-867a-a74fa43337ff', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the concept of ''Live Coding'' in Quarkus and its impact on developer productivity.', N'Middle', N'Live coding allows developers to see changes reflected instantly without manually restarting the application. When a file is modified, Quarkus automatically recompiles and reloads the updated components in the background, drastically reducing the feedback loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f9b6cc4-1b57-4b2e-8777-a75057f38971', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle recovery from panics?', N'Fresher', N'Gin includes a built-in recovery middleware that catches any panics that occur during the execution of a request handler. It prevents the entire server from crashing and instead returns a 500 Internal Server Error response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6258f11-67f6-4fbf-8fe1-a7506d9700a6', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro be used to build a full-stack application?', N'Middle', N'Yes, by enabling SSR mode and using API endpoints or server-side functions, Astro can handle data fetching, authentication, and database interactions. It serves as a backend-for-frontend, allowing seamless integration between server-side logic and the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
