INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7acd6344-7b64-4417-bb73-a7579668122b', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart handle memory management, and why is it generally sufficient for high-performance applications?', N'Senior', N'Dart utilizes a generational garbage collector that treats short-lived objects differently from long-lived ones, optimizing for throughput in UI-heavy applications. By keeping the heap divided into young and old generations, the GC minimizes pause times, which is critical for maintaining high frame rates in interactive software.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
