INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef102f23-6ef8-4a0f-aa2d-a788b6207440', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a cascading failure where one service''s latency causes a system-wide outage?', N'Senior', N'I would analyze the request call graph to identify the dependency that triggered the initial timeout and check if circuit breakers were configured correctly to fail fast. My recovery strategy would involve isolating the compromised service, shedding load, and verifying that the system has proper bulkhead patterns to prevent the failure from saturating the entire infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9207e4e0-8bb3-45bb-8ceb-a789d446e48c', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the concept of ''Cache Penetration'' and how Bloom filters help solve it.', N'Senior', N'Cache penetration occurs when requests for non-existent keys bypass the cache and hit the database directly, often as part of a denial-of-service attack. A Bloom filter acts as a space-efficient probabilistic check that quickly determines if a key exists, allowing the system to reject invalid requests without querying the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
