INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd112941d-d3c7-4686-b611-a78c8e203c6d', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the main risks associated with manual memory management?', N'Middle', N'Manual management risks include memory leaks, where memory is allocated but never freed, and dangling pointers, which occur when accessing memory after it has been deallocated. These issues can lead to unpredictable crashes, security vulnerabilities, and system instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a034b8d-ea5d-4c32-9fe7-a78daf20a90d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the middleware pipeline in ASP.NET Core and how does request processing work?', N'Middle', N'The middleware pipeline is a chain of components that handle HTTP requests and responses. Each middleware can perform tasks before and after the next middleware in the chain, allowing for flexible request processing such as logging, authentication, and error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efdf69a0-02ec-4444-8a8a-a78f9f8e2ac9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does declaration merging work in TypeScript?', N'Middle', N'Declaration merging occurs when the compiler automatically merges multiple declarations of the same name into a single definition. This is most commonly applied to interfaces, allowing developers to extend third-party libraries by adding new fields to existing interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c46ea1-0613-4568-8800-a792bdb4f831', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of Middleware ordering?', N'Junior', N'In the ASP.NET Core pipeline, middleware components are executed in the order they are added. Ordering is crucial because some components depend on others, such as authentication needing to run before authorization or routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b8fc498-61a8-4f70-8911-a797d648af8a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve GraalVM Native Image compatibility without the need for manual reflection configuration?', N'Senior', N'Micronaut''s AOT compilation creates all necessary metadata and bean wiring instructions at build time, essentially eliminating the dynamic behavior that typically breaks Native Images. By avoiding runtime reflection, proxies, and dynamic class loading, it provides a seamless transition to a static native executable environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f20bb393-a595-48c4-bd3f-a798ff96973e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a Foreign Key and a Check constraint?', N'Middle', N'A Foreign Key ensures referential integrity by requiring that values in a column correspond to a primary key in another table. A Check constraint enforces a boolean condition on the data within a single row, ensuring that specific business rules are always met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b541b05-527b-46a3-a99a-a79bd953acf7', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of ''Task'' and ''Task.Supervisor'' in parallelizing long-running Phoenix operations?', N'Senior', N'Tasks allow for easy offloading of asynchronous work to separate processes without the overhead of full GenServer boilerplate. Using a Task.Supervisor ensures that these background tasks are properly monitored and cleaned up, preventing memory leaks if the task fails or takes too long to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bfcd71d-aab8-471c-968e-a79c56f95aff', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does it mean for Redis to be single-threaded?', N'Fresher', N'Redis uses a single-threaded event loop to process commands, meaning it handles one request at a time sequentially. Despite this, it remains incredibly fast because the in-memory operations are so efficient that the overhead of managing multi-threaded synchronization is unnecessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63ea27b3-3fd2-4563-92af-a79cb20c7a21', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What consideration should be taken when deploying Fiber applications in a containerized environment?', N'Middle', N'In containerized environments, you should ensure that the number of worker processes matches the assigned CPU limits, often leveraging the Prefork feature. Additionally, because Fiber handles its own connection pooling, it is important to monitor memory usage to ensure it stays within container limits during high traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4cdb095-616c-4ea5-9b42-a79d212441c1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is TypeScript''s type system considered ''unsound'' in certain areas, and what is the impact on large-scale applications?', N'Senior', N'The type system is intentionally unsound in areas like function parameter bivariance and array indexing to balance developer productivity with correctness. In large applications, this requires stricter linting rules and disciplined coding standards to prevent runtime type errors that the compiler fails to catch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
