INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be2b1d4d-5c65-403c-95f3-a7b61ca067f4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When integrating with a third-party API that has unpredictable latency, what architectural patterns do you employ?', N'Senior', N'I would wrap the integration in an asynchronous pattern using message queues or a bulkhead pattern to isolate the latency from the core system. I would also implement robust timeout handling and a circuit breaker to ensure the third-party dependency cannot degrade the performance of the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
