INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48380ed2-b006-4162-9ccb-a7c13b17a960', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why does Next.js favor server-side data fetching?', N'Junior', N'Fetching data on the server keeps secrets like API keys secure and closer to your database, reducing latency. It also allows the server to send the final HTML to the browser, which improves the initial render time for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3b0d881-aea3-41d7-921f-a7c7068acfa9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a feature estimate should include time for future-proofing?', N'Middle', N'I weigh the probability of future requirements against the immediate cost of implementation. If the cost of adding extensibility is low and the likelihood of future changes is high, I include it; otherwise, I stick to a YAGNI (You Ain''t Gonna Need It) approach to avoid unnecessary complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3469cd0c-399f-4ee2-806d-a7c9e45a2245', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the purpose of mutual TLS (mTLS)?', N'Middle', N'mTLS provides both encryption and bidirectional authentication by requiring both the client and the server to present a digital certificate. This ensures that only authorized clients can communicate with a specific server, which is essential in zero-trust microservice architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a137c4ee-50bd-48f9-ab87-a7cb341485f7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the trade-offs of Go''s escape analysis algorithm in terms of heap versus stack allocation.', N'Senior', N'The compiler uses escape analysis to determine if a variable''s lifetime exceeds the scope of the function. If it does, the variable is moved to the heap, which increases garbage collection pressure, whereas stack allocation is essentially free as it simply adjusts the stack pointer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2d7463-a123-48f6-8d12-a7ce1a2fb0f8', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to pass params to history.push method in React Router v4?', N'Fresher', N'While navigating you can pass props to the history object: The search property is used to pass query params in push() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb1dd53d-7dcc-4e9c-a19e-a7ceb6e82ea5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does CSS font-display impact the perceived performance of a web page?', N'Senior', N'The font-display property controls how a browser swaps or hides a custom font while it is loading. Setting it to ''swap'' ensures text is immediately readable using a fallback font, which improves the user experience by reducing the duration of invisible or flash-of-unstyled-text states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'285f2f71-1d07-4d47-b7d2-a7cf86017419', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a node in a NoSQL cluster?', N'Intern', N'A node is a single server or instance that is part of a distributed NoSQL database cluster. Data is distributed across these nodes to ensure fault tolerance and load balancing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1075860c-cf89-4cb5-8d0a-a7cfd1bf565f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the primary purpose of Pydantic in a FastAPI application?', N'Junior', N'Pydantic is used for data validation and settings management. It ensures that the incoming request data matches the expected types and structure defined in the schema, automatically raising errors if the data is invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c82ef4c-9d44-4c3e-949e-a7d193119ed5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What steps do you take when you realize you will miss a deadline?', N'Fresher', N'I notify my lead or manager as soon as I identify the risk, providing an explanation of the delay and a revised estimate for completion. I offer potential workarounds or suggest which parts of the task can be delivered in a later iteration to minimize the impact on the overall project. Honesty and transparency are essential for maintaining team trust.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7652fdcc-3b39-4ad3-bd30-a7d21d1f5bcb', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the trade-offs of using Litestar''s built-in OpenAPI schema generation?', N'Middle', N'The primary benefit is automatic, always-up-to-date documentation that matches the implementation. The trade-off is the initial configuration complexity and the requirement to define precise type hints, which can be restrictive for developers used to dynamic or loosely typed frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62c286d0-2e1e-41c3-948d-a7d4c319fa6b', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you manually register locale data?', N'Fresher', N'By default, Angular only contains locale data for en-US which is English as spoken in the United States of America . But if you want to set to another locale, you must import locale data for that new locale. After that you can register using registerLocaleData method and the syntax of this method looks like below, For example, let us import German locale and register it in the application', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6204a36b-2e7f-4394-a32e-a7d53dbe2f20', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What architectural advantage does AdonisJS provide regarding Node.js versioning and stability?', N'Senior', N'AdonisJS is designed with a strong emphasis on stability and consistent API design, often lagging slightly behind the newest Node.js features to ensure long-term support. This allows enterprise teams to focus on business features rather than frequent, breaking framework upgrades.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28aa6305-ad71-45e5-8de0-a7d8025dba1d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is ''Deadlock Detection'' and how does the database handle it?', N'Senior', N'Deadlock detection involves the database engine periodically checking for cyclic dependencies between transactions waiting for locks. When a cycle is detected, the database selects one transaction as a victim, rolls it back to break the cycle, and releases its locks so other transactions can proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df539325-331a-4704-84b5-a7d9577ac7b9', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s ''FastCGI Process Manager'' (PHP-FPM) enhance execution efficiency?', N'Middle', N'PHP-FPM manages a pool of worker processes that persist between requests, avoiding the overhead of spawning a new process for every web request. This results in faster response times and better resource utilization under high traffic compared to traditional CGI methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'011b643a-7c8b-404e-8b86-a7dbaa678cdd', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between ''apply'' and ''lapply'' in R?', N'Middle', N'lapply is a specialized function that always returns a list regardless of the input, making its output predictable for further processing. apply is a more general function that can operate on margins of matrices or arrays, often simplifying results into vectors or matrices if possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
