INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c08b878-cc4b-43b7-aa51-a7dc5b11f3c1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between term-based search and full-text search in Elasticsearch?', N'Junior', N'Term-based search looks for exact matches of specific values, such as an ID or a status code, without any normalization. Full-text search analyzes the input by breaking it into individual words, normalizing them, and matching them against the inverted index to find relevant documents even with minor variations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'525fac46-cad5-408a-853e-a7dd111648c2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the architectural trade-offs of using Symfony''s ''Auto-wiring'' feature in a large-scale enterprise application?', N'Senior', N'Auto-wiring significantly reduces boilerplate and configuration overhead, speeding up development. However, it can make dependency chains less transparent and may lead to circular dependencies or runtime errors that are only discovered when the container is compiled, necessitating stricter architectural oversight.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'295debb0-37ad-4563-a1f6-a7e1afee1e34', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach the estimation of a project that requires significant cross-departmental alignment?', N'Senior', N'I treat the alignment phase as a project milestone with its own dependencies and risks. I factor in a buffer for bureaucratic delays and focus on establishing clear owners and communication channels to keep the project moving forward despite external dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11888408-7a40-40f9-addb-a7e2891e7000', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What happens if you use a blocking synchronous library inside an ''async def'' route handler?', N'Middle', N'Using a blocking synchronous library, like standard ''requests'', inside an ''async def'' function blocks the entire event loop. This prevents the server from handling other concurrent requests, effectively nullifying the performance benefits of using asynchronous programming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc5ff072-14e5-452b-a1ce-a7e330639a2e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why are Python strings immutable?', N'Middle', N'Strings are immutable to ensure they are thread-safe, hashable, and can be safely used as dictionary keys. This immutability allows Python to optimize memory by interning strings and preventing accidental side effects during string manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fada79ca-b235-44c6-a903-a7eae9167727', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the limitations of TypeScript''s ''is'' type predicate in complex inheritance trees?', N'Senior', N'Type predicates are not dynamically checked at runtime; they rely on the logic provided by the developer, which can be incorrect or become stale. In complex inheritance, relying solely on ''is'' might bypass the prototype chain checks that ''instanceof'' would otherwise handle, leading to potential false positives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'583fd189-fc7b-4cf8-8c1d-a7ec90021c93', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the performance implications of using ''thread-loader'' in a Webpack pipeline?', N'Senior', N'Thread-loader offloads expensive loaders to a worker pool, parallelizing the build process. While it improves performance for heavy tasks like Babel transpilation, it introduces overhead for inter-process communication, so it is ineffective for lightweight loaders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f21225e0-5749-404c-9b44-a7ec955d5a5a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of an API, and why do we version them?', N'Junior', N'An API allows different software components to communicate and share data. We version APIs to introduce updates or changes without breaking existing integrations that rely on the older version, ensuring backward compatibility for users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
