INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f427523-fb71-4928-a7d5-a80e195e2774', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary factor in choosing between a single-region and multi-region deployment?', N'Middle', N'The primary factor is the geographic distribution of users and the required latency. Multi-region deployments significantly reduce latency for global users and provide disaster recovery, but they introduce extreme complexity in data replication and synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f0828e8-1daa-4bcb-a590-a811da26d416', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the impact of partitioning on message ordering in systems like Apache Kafka?', N'Senior', N'Partitioning allows for horizontal scalability by distributing data across nodes, but it limits strict global ordering to the scope of a single partition. To maintain order, messages with causal dependencies must be routed to the same partition using a consistent hashing key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
