INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c53362fc-8683-4820-af51-a812a6097b3e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between aggregation and composition?', N'Fresher', N'1. Aggregation: We call aggregation those relationships whose objects have an independent lifecycle, but there is ownership, and child objects cannot belong to another parent object. Example: Since Organization has Person as employees, the relationship between them is Aggregation. Here is how they look like in terms of Java classes 2. Composition: We use the term composition to refer to relationships whose objects don''t have an independent lifecycle, and if the parent object is deleted, all child objects will also be deleted. Example: Since Engine is-part-of Car, the relationship between them is Composition. Here is how they are implemented between Java classes. Aggregation Composition Aggregation is a weak Association. Composition is a strong Association.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b103f196-46ee-4107-ac64-a813e3f9ebc2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does ''dns-prefetch'' improve page load performance?', N'Middle', N'Dns-prefetch allows the browser to resolve the domain name of a third-party resource in the background while the current page is loading. By resolving the IP address ahead of time, the subsequent connection to that domain is faster. It is particularly useful for domains that will be accessed later, such as external CDNs or social media widgets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'148d44ce-a459-439e-8694-a815d9f7e19a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it often preferred to use background jobs for heavy tasks in Rails?', N'Middle', N'Rails applications are typically served by web servers that handle requests synchronously; long-running tasks block these workers, leading to poor user experience. Offloading these tasks to a background worker queue keeps the request-response cycle fast and improves the overall scalability of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
