INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf889c7f-4ab7-48fb-b875-a81be70ed96a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of the ''client:visible'' directive for performance optimization?', N'Senior', N'The ''client:visible'' directive uses the Intersection Observer API to defer the hydration of a component until it enters the viewport. This is a critical performance strategy for off-screen components, as it prevents unnecessary JavaScript execution during the initial page load, prioritizing resources for the above-the-fold content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b57fb9a-91aa-4768-b3d5-a81ce41a96d8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the TypeScript compiler''s ''Incremental'' mode work, and when should it be avoided?', N'Senior', N'Incremental builds use a .tsbuildinfo file to store signatures of the previous compilation, allowing the compiler to rebuild only changed modules. It should be avoided in environments where the build environment is ephemeral and clean, as the overhead of reading/writing the cache may exceed the benefit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
