INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c94427a-9af9-4f25-b306-a81dfb808628', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Explain the concept of ''technical debt'' in simple terms.', N'Intern', N'Technical debt is the implied cost of additional rework caused by choosing an easy, fast solution now instead of a better, more robust approach that would take longer. Like financial debt, it accumulates interest in the form of extra effort required to fix or maintain the system later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dec4ca93-a46b-48fd-8d2f-a8200ec046c3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to perform a ''sanity check'' on your assumptions?', N'Intern', N'A sanity check involves questioning basic premises, such as whether the power is on, if the network is connected, or if the correct version of a file is being used. Often, complex errors are actually caused by simple oversights that are overlooked when looking for complex solutions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
