INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e61eaea-44c2-4344-ac7b-a8289bd1e65e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of php.ini file?', N'Intern', N'The php.ini file is the configuration center for PHP settings, governing a range of operational aspects. It is an essential tool for managing a server''s PHP environment. Key Functions - Settings Management: The file allows for the configuration of PHP settings, offering granular control over key directives such as memory_limit and error_reporting. - Environment Tailoring: By modifying php.ini, developers can fine-tune PHP to best suit their specific applications and environments. - Error and Security Settings: The file provides a centralized location to manage error reporting, display, and log settings, alongside various security-related configurations. PHP Versions and Editions - It''s important to note that \foo` variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e16f4879-7bf8-476d-8f4e-a82ee99d2f25', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage memory usage?', N'Fresher', N'By splitting the application into small chunks and only loading what is necessary, Qwik keeps memory usage lean. The browser does not need to hold the entire application logic in memory, which is beneficial for performance on mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25cacf99-cb7e-44ea-a97d-a82f84708f78', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How are environment variables usually handled in Phoenix?', N'Junior', N'Environment variables are typically loaded via the ''config'' files located in the config directory. This allows for environment-specific settings, such as different database credentials for development, testing, and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
