INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64323ff3-b3ed-42e9-a3fc-a83304f5a4f5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is ''debouncing'' and why is it used in performance-critical interfaces?', N'Middle', N'Debouncing is a technique that limits the frequency at which a function is executed by ensuring it only runs after a certain amount of time has passed since the last trigger. It is essential for performance-intensive tasks like scroll listeners or input validation, preventing unnecessary re-renders or API calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
