INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b390f993-d25b-4664-aacb-a838b0faefaa', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When asked to estimate a project you have no direct experience with, what is your reasoning process?', N'Senior', N'I start by conducting interviews with subject matter experts to identify the system''s architectural boundaries and potential integration risks. I then use historical data from similar projects, apply a factor for the unknown, and establish a feedback loop for early re-estimation once the first phase is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cad17ed8-c2b2-499b-b34c-a839da5e4d80', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Utility Types like ''Pick'' and ''Omit''?', N'Middle', N'Pick and Omit are built-in utility types that allow developers to create new types by selecting or excluding specific keys from an existing interface. They help maintain the ''DRY'' principle by deriving new models from base types instead of duplicating them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9932d767-939f-47fd-82cd-a83afcde4e79', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''co_consts'' and ''co_names'' fields in a Python code object?', N'Senior', N'These fields are part of the compiled bytecode metadata; ''co_consts'' stores literals like numbers and strings used in the code, while ''co_names'' holds names of variables and attributes accessed. Keeping these separate from the instruction stream allows for efficient lookups and reduced bytecode size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b94974a4-e013-4692-b25f-a83d75485a67', N'954a0331-deff-4399-b588-96f39fec001d', N'How does forRoot method helpful to avoid duplicate router instances?', N'Fresher', N'If the RouterModule module didn’t have forRoot() static method then each feature module would instantiate a new Router instance, which leads to broken application due to duplicate instances. After using forRoot() method, the root application module imports RouterModule.forRoot(...) and gets a Router, and all feature modules import RouterModule.forChild(...) which does not instantiate another Router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42250821-e43b-43c1-ac2b-a83e130da5d1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the ''Liveness'' problem in distributed systems?', N'Senior', N'Liveness ensures that the system eventually performs an operation despite failures or delays. In the context of transactions, it means that the system must avoid indefinite blocking or starvation, ensuring that every transaction is eventually either committed or aborted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78cef04c-36b3-4446-9df8-a843aa988f1e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the concept of null-aware operators in Dart.', N'Junior', N'Null-aware operators like ''??'' or ''??='' allow you to handle null values gracefully. They let you provide a default value if a variable is null, preventing the need for verbose if-null checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c59d2bc0-57f8-461d-9f40-a843bfd80914', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle concurrency in relation to its context object?', N'Senior', N'Fiber''s context object is not thread-safe and is tied to the lifecycle of the incoming request. Concurrent access to the context from multiple goroutines within a single request handler will result in race conditions, requiring external synchronization if parallel processing is necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
