INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5812019-8508-4a26-99f9-a84c26934e3b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s copy-on-modify semantics impact memory management in large-scale data processing?', N'Senior', N'R''s copy-on-modify behavior ensures functional purity by creating a new object in memory when a modification is attempted on a shared reference. While this prevents side effects, it can lead to significant memory overhead and performance degradation during large dataset manipulation, necessitating the use of specialized structures like environments or external pointers to perform in-place updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29b6780e-6862-4cf3-818f-a84d09d1062d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix favor server-side rendering (SSR) by default?', N'Middle', N'SSR ensures that the content is fully rendered before reaching the browser, which improves SEO and provides a faster perceived performance. By sending HTML directly from the server, the browser can display meaningful content immediately without waiting for a large JavaScript bundle to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88428809-558f-4894-a6c8-a84ed0da90f2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are lifecycle functions in Svelte and why are they useful?', N'Fresher', N'Lifecycle functions, such as onMount, allow you to run code at specific stages of a component''s existence, like when it is first added to the DOM. They are essential for tasks like fetching initial data from an API or setting up event listeners that need to be cleaned up later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c57c23fc-34e4-4520-8435-a84f1d59104f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the difference between ''App'' state and ''Data'' in Actix-web.', N'Middle', N'App state typically refers to global data initialized once and made available to all routes. ''Data'' is the wrapper used to inject this state into handlers, ensuring that the necessary thread-safe access is provided through the dependency injection system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b72e5fe9-d46a-4d87-a2c4-a84fa52d1153', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix’s approach to error handling differ from standard React Error Boundaries?', N'Senior', N'Remix extends Error Boundaries to the server-side, allowing developers to catch data loading or action execution errors at the route level. This ensures that a failure in one nested route segment does not crash the entire application, and allows for specialized error UI based on the HTTP status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
