INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69ac0092-a1d7-48ff-8a7a-a850685cf317', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s deferred object implementation compare to modern native JavaScript Promises?', N'Senior', N'jQuery''s Deferred objects are not fully compliant with the Promises/A+ specification, which can lead to subtle interoperability issues when interacting with modern libraries. Native Promises provide a standard, performant, and more predictable way to handle asynchronous control flow in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ff52123-5626-4245-aab9-a85648d4dfe8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the nullish coalescing (??) and optional chaining (?.) operators, and how do they relate to control flow?', N'Intern', N'Both operators introduced in ES2020 reduce verbose defensive if checks for null/undefined values: - Nullish coalescing (??): Returns the right-hand operand when the left is null or undefined (not other falsy values like 0 or ""). - Optional chaining (?.): Short-circuits and returns undefined instead of throwing a TypeError when accessing a property on null or undefined. Example: Real-World Use Case: When consuming third-party REST APIs or GraphQL responses, deeply nested fields may be absent depending on the query. Optional chaining eliminates dozens of guard clauses like if (response && response.data && response.data.user).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'364592bc-7393-46fd-955c-a8568371a887', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why might a senior developer prefer ''Final'' classes and methods in a Scala library API?', N'Senior', N'Marking classes and methods as final prevents unintended inheritance and overriding, which stabilizes the library''s internal behavior and performance characteristics. It allows the compiler to perform better optimizations like devirtualization. This practice enforces a clear contract, protecting the library''s internal state and reducing the surface area for breaking changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85ca6585-8259-4e3e-8f1e-a85836d2e4f2', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'In a microservices architecture, how do you handle communication between two services?', N'Junior', N'I choose between synchronous communication via HTTP/REST for requests that require an immediate response and asynchronous communication via a message broker for tasks that can be processed in the background. Asynchronous communication is generally preferred to decouple services and improve system resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe3b2eba-011a-45fe-9775-a8590fe76dd3', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the main benefit of using a schema-less database?', N'Intern', N'A schema-less database allows developers to change the data structure on the fly without needing to perform complex migrations. This provides significant agility for applications undergoing rapid development cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a41946ad-9af4-49fa-ba50-a85ffe754e9e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain how Vite handles ''Dependency Pre-bundling'' and why it is necessary.', N'Senior', N'Vite uses esbuild to pre-bundle dependencies into single modules to reduce the number of HTTP requests the browser must make. This also converts CommonJS or UMD dependencies into ESM, ensuring compatibility with the browser''s native module system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e547e605-ab33-4710-8b48-a860c11ded3e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the role of the BeanContext in Micronaut and how it manages application lifecycle.', N'Senior', N'The BeanContext is the central registry and orchestrator for all managed beans in a Micronaut application. It handles the resolution, instantiation, and destruction of beans based on AOT-generated metadata, ensuring that dependencies are injected efficiently without relying on runtime reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcf18d5e-f2b3-4a16-b30a-a863803c58e0', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is ''Vacuuming'' or ''Compaction'' necessary in databases using MVCC?', N'Senior', N'MVCC creates multiple versions of rows during updates; these obsolete versions consume storage and degrade performance over time. Vacuuming processes identify and remove these dead tuples, reclaiming space and allowing the database to reuse pages for new data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b223c1e9-4e1a-4e0f-8fd2-a86380594dd9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach debugging a race condition that only appears under high concurrency?', N'Middle', N'I would attempt to simulate the high-concurrency environment using load testing tools to reproduce the issue in a controlled setting. I would then review synchronization mechanisms and shared state usage, potentially adding logging or using thread analysis tools to visualize the sequence of operations leading to the race condition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75aee152-86be-443f-9c7a-a86c375abe94', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why would you choose an asynchronous messaging system over synchronous HTTP requests?', N'Middle', N'Asynchronous messaging improves system decoupling, availability, and fault tolerance by allowing services to process requests at their own pace. It also helps manage traffic spikes by acting as a buffer, preventing downstream services from being overwhelmed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'361f3111-e17d-4ceb-bc80-a86da378471a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is code splitting in Webpack?', N'Fresher', N'Code splitting allows you to split your code into various bundles which can then be loaded on demand or in parallel. This improves performance by reducing the initial load time of the application since the browser only downloads the code necessary for the current view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a2f02c6-d46b-4f62-9762-a86fc8673985', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Symfony Routing component?', N'Intern', N'The Routing component maps an incoming HTTP request URL to a specific controller action. It defines the patterns that the application should respond to and extracts variables from the URL for use in the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'308b20fb-44f1-4cb2-afd9-a8710444fabf', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the difference between ''Reference'' types (Weak, Soft, Phantom) and their impact on GC behavior.', N'Senior', N'These reference types allow developers to influence the garbage collector''s decision-making process for object reclamation. Soft references are reclaimed only under memory pressure, weak references are reclaimed at the next cycle, and phantom references are used for post-mortem resource cleanup, providing varying levels of control over lifecycle management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a8404cd-539b-4e7f-8ad5-a8711aa84810', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''stackalloc'' keyword work and when should it be used?', N'Middle', N'The ''stackalloc'' keyword allocates a block of memory on the stack instead of the heap. It is used in performance-critical code to avoid garbage collection pressure, but it must be used with caution because stack size is limited and memory is automatically freed when the method returns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49e9e792-0fb0-4c51-be33-a8721048beaa', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an SQL join?', N'Intern', N'An SQL join is a method used to combine rows from two or more tables based on a related column between them. It allows users to retrieve data that is spread across different tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e41c83f-ff4b-411e-ad64-a8726aedfb75', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is ''Lazy Loading'' in the context of Qwik?', N'Intern', N'Lazy loading in Qwik refers to the strategy of deferring the loading of non-essential resources until they are required. This ensures that the initial bundle size remains extremely small, leading to faster startup times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b29d4c1c-70ef-4a11-b602-a87adaced99f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the concept of ''fat models'' versus ''fat views'' and why it matters.', N'Middle', N'The debate centers on where to put business logic. ''Fat models'' keep logic in the model layer, making it reusable and testable, while ''fat views'' keep logic in the controller, which often leads to code duplication and harder unit testing. The modern consensus favors moving complex logic into a separate service layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01556825-83f5-4537-8e37-a87d7cf71915', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the Vite ''public'' directory?', N'Intern', N'The public directory is a special folder where files are served at the root path without being processed by Vite. Assets placed here are copied to the build folder as-is and are useful for files that should not be bundled, like robots.txt or favicons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8580387-0926-4713-a7fc-a87e48ff4856', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does ''near real-time'' mean in the context of Elasticsearch?', N'Intern', N'Near real-time means there is a slight delay, usually one second, between when a document is indexed and when it becomes available for search. This architecture allows Elasticsearch to maintain high performance while ensuring data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'957f233b-774c-48e9-a673-a87fd8829379', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a builder?', N'Intern', N'A builder function is a function that uses the Architect API to perform a complex process such as "build" or "test". The builder code is defined in an npm package. For example, BrowserBuilder runs a webpack build for a browser target and KarmaBuilder starts the Karma server and runs a webpack build for unit tests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70eaf1f7-3bc0-419f-8497-a880e5ac6a99', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a Foreign Key and why is it used?', N'Fresher', N'A foreign key is a column or group of columns that provides a link between data in two tables. It acts as a cross-reference between tables because it references the primary key of another table, thereby establishing a relationship and maintaining referential integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed575654-b32e-47f5-83ee-a88299418e79', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the relationship between the HTML ''Content-Visibility'' property and rendering performance?', N'Senior', N'Content-visibility allows the user agent to skip the layout and rendering work for an element until it approaches the viewport. This significantly reduces the initial rendering time for large documents by deferring costly computations until they are actually needed by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c28309b-f31c-425f-8288-a8856eca0bff', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is NoSQL often considered better for big data?', N'Junior', N'NoSQL databases can handle massive amounts of unstructured data and can be easily scaled horizontally across commodity hardware. This makes them more cost-effective and performant for big data projects compared to traditional relational databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6d811a9-5fb3-4f02-bec7-a887c3a3c8fc', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s Glimmer VM improve rendering performance compared to a standard virtual DOM implementation?', N'Senior', N'The Glimmer VM compiles templates into low-level bytecode that is executed by a specialized virtual machine. By utilizing an append-only structure for the DOM and maintaining a static analysis of bindings, it minimizes the work required to update the UI, effectively bypassing the expensive diffing processes found in traditional virtual DOM libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e675946f-f19e-4695-b1bc-a8896e89b050', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is R''s dispatch mechanism considered dynamic rather than static?', N'Senior', N'Method dispatch in R is determined at runtime based on the class of the object passed to a generic function. This allows for highly flexible and extensible code, but it prevents the compiler from performing exhaustive type checking or aggressive method inlining.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8b2b9d2-3885-4911-8f3e-a889f6150c14', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js compare to React?', N'Fresher', N'React is a component-based library that requires a virtual DOM and a build process for complex state management. Alpine.js is much lighter, works directly in the DOM, and is intended for adding interactivity to static HTML without the overhead of a full application bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8dbe11ae-2396-4486-913a-a88b08ea1430', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the viewport meta tag?', N'Junior', N'The viewport meta tag controls the layout on mobile browsers by setting the width and scaling of the page. It ensures that the website scales correctly to fit the screen size of the device being used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5bd8452-5afa-4449-b136-a88b77a12cf3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does partitioning (sharding) differ from replication, and when should each be used?', N'Middle', N'Replication involves copying data to multiple nodes to improve read availability and provide fault tolerance. Partitioning splits the dataset into smaller, distinct chunks across multiple nodes to improve write throughput and bypass the storage limits of a single machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de51f5c2-1323-4ccb-bb2e-a88ca2134a91', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What happens if a user never interacts with a Qwik page?', N'Intern', N'If a user never interacts with the page, the browser will not download any additional JavaScript beyond the absolute minimum required. This results in an incredibly fast and efficient user experience, especially on mobile devices with limited bandwidth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c336c3c-767b-4348-8539-a88d24c36f27', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''init'' block used for?', N'Junior', N'The ''init'' block is used to execute initialization code for a class that runs immediately after the primary constructor. It is a convenient place to perform validation or setup logic that depends on the constructor parameters. You can have multiple ''init'' blocks in a single class, which execute in the order they appear.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ead283d-e6f9-4bb0-8c79-a88eda397f6a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift ensure memory safety?', N'Fresher', N'Swift uses Automatic Reference Counting to track and manage memory usage by automatically deallocating instances that are no longer needed. It also enforces strict type safety and requires explicit handling of optional values to prevent common memory-related bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
