INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36731a44-c756-4013-aa9f-a8cfa0653182', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is display: contents and what does it do?', N'Intern', N'display: contents makes an element act as if it is not there for layout purposes — it disappears from the box tree, but its children remain and participate in the parent''s layout as if they were direct children. Use case — unwrapping a semantic element for layout: Important caveats: * The element itself becomes invisible to layout — padding, border, background, and margin on it have no visual effect. * The element is still in the DOM and accessible to JavaScript. * Accessibility warning: Applying display: contents to certain semantic elements ( , , ) can strip their ARIA roles in some browsers, breaking accessibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08caa5ef-82d3-48e1-af0b-a8d0a47aeeb5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Function binding?', N'Intern', N'Function binding ( .bind() ) is a method on the prototype of all functions in JavaScript. It allows to create a new function from an existing function, change the new function''s this context, and provide any arguments you want the new function to be called with. The arguments provided to bind will precede any arguments that are passed to the new function when it is called. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc586461-8d72-48e6-b040-a8d334756c8c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a schema in a relational database?', N'Intern', N'A schema is the formal structure or blueprint that defines how a database is organized. It specifies the tables, fields, data types, and relationships that exist within the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'103051dd-b9de-48d3-8c49-a8dac3c3f1a4', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is referential integrity?', N'Intern', N'Referential integrity is a database concept that ensures the relationship between two tables remains consistent. It prevents users from adding records to a related table if there is no corresponding record in the primary table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3657fb10-0521-4909-913a-a8dbbf9e2b76', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the concept of ''directive'' in Lit and when it is appropriate to create a custom one.', N'Senior', N'Directives are functions that provide advanced control over rendering, such as managing DOM nodes outside the standard template lifecycle or optimizing specific updates. You should create custom directives when you need to perform complex DOM operations that are repeated across multiple components and cannot be cleanly encapsulated within standard render templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e2d13a6-4ffa-4dc4-9906-a8dc353c2077', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are generics in Kotlin?', N'Intern', N'Generics allow classes and functions to work with various data types while maintaining type safety. They enable the creation of reusable components that can operate on any type specified at the time of use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'359af9b2-748b-40c4-a618-a8dedcfc2a6e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the benefit of using Option instead of null in Scala?', N'Middle', N'Option forces developers to explicitly handle the absence of a value, preventing common null pointer exceptions. It encourages a functional style of error handling and transformation, allowing developers to use combinators like map and flatMap to process values safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64e11ebb-e0bd-4ab5-84f5-a8e027ff257e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is a reactive statement in Svelte?', N'Intern', N'A reactive statement is a block of code that automatically re-runs whenever the variables it depends on change. It is defined using a special label syntax that tells the compiler to treat the block as a dependency that needs to be re-evaluated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ed44119-d59c-4047-b660-a8e12ae8da0b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the trade-offs between using Scala''s structural types versus type classes.', N'Senior', N'Structural types rely on reflection, which introduces significant performance overhead and runtime risk. In contrast, type classes offer a compile-time polymorphism mechanism that is type-safe, performant, and highly extensible, making them the preferred choice for designing robust, decoupled libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa871ac0-d346-433c-a15d-a8e1646f3743', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of version control in a collaborative engineering environment?', N'Intern', N'Version control tracks changes made to files over time, allowing multiple people to work on the same project without overwriting each other''s work. It also provides a history of changes, making it easy to revert to a previous state if an error is introduced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7880fa52-a2e2-4b3a-a2e8-a8e1a0d703cf', N'4c000000-0000-0000-0000-000000000005', N'What is the role of a Bloom filter in a distributed storage system?', N'Senior', N'A Bloom filter is a space-efficient probabilistic data structure used to test whether an element is a member of a set. It is primarily used to prevent unnecessary disk reads by quickly determining if a key does not exist in a specific storage file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0270c79a-1c88-4c5b-8f7b-a8e48d9d5ffc', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the Micronaut ''Introspection'' feature, and why is it preferred over standard Java reflection?', N'Senior', N'Introspection provides a compile-time generated metadata API that allows the framework to access class properties and annotations without using expensive reflection calls. This improves performance and ensures full compatibility with GraalVM native image compilation, where runtime reflection is restricted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a454d30-d3cf-4b14-83fb-a8e57a38dbc7', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is EventEmitter in Node.js?', N'Intern', N'EventEmitter is a class from Node.js''s built-in events module that implements the Observer (Pub/Sub) pattern — objects can emit named events, and listeners registered for those events are called when they fire. EventEmitter is at the core of Node asynchronous event-driven architecture. Many of Node''s built-in modules inherit from EventEmitter including prominent frameworks like Express.js. An emitter object basically has two main features: * Emitting name events. * Registering and unregistering listener functions. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85ec195d-c28e-41c6-89dd-a8e63053a22c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the primary architectural pattern used by Ruby on Rails?', N'Intern', N'Ruby on Rails uses the Model-View-Controller (MVC) architectural pattern. This pattern separates the application into three logical components: the Model handles data and business logic, the View manages the user interface, and the Controller handles user input and coordinates between the Model and the View.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0d4b4f0-2cf1-4dab-9c32-a8e9b746e447', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the primary trade-off between monolithic and microservices architectures?', N'Middle', N'Monoliths offer simplicity in deployment and lower latency due to in-memory calls, but suffer from scaling limitations and tight coupling. Microservices provide independent scalability and technology flexibility, but introduce significant operational complexity and network overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ffc7b48-3b22-4308-8133-a8ed94fd1329', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing an API, why is it important to use standard HTTP status codes instead of just returning a custom error message in the body?', N'Fresher', N'Standard HTTP status codes provide a universal language that allows clients and browsers to understand the outcome of a request without needing to parse the response body. Using codes like 200 for success, 404 for missing resources, and 500 for server errors ensures consistent behavior across different tools and frameworks. This predictability makes the API easier to debug and integrate for other developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8e196ff-1a1d-4538-ad40-a8f0342e136c', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a stack and the heap in C++?', N'Intern', N'The stack is a region of memory used for static memory allocation where variables are created and destroyed automatically by the scope. The heap is a region of memory used for dynamic memory allocation where the programmer manually manages the lifespan of objects. Stack allocation is generally faster, while the heap is used for data that needs to persist beyond the current function scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f73c69d-238b-4a94-b15d-a8f04953f17a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for choosing between a message queue and a synchronous REST API call for inter-service communication?', N'Middle', N'I choose synchronous REST when immediate feedback is required for the user experience and the operation is lightweight. I opt for a message queue when the process can be handled asynchronously, requires high fault tolerance, or involves decoupling services to manage traffic bursts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8b3e908-00bb-4fa1-a503-a8f05b01bff5', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the trade-offs of using Annotations versus Attributes for configuration?', N'Middle', N'Annotations rely on docblock parsing, which can be slower and prone to syntax errors. PHP Attributes are native, typed, and integrated into the language, offering better performance, improved IDE support, and compile-time validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d2bd846-0507-44ee-b003-a8f05f19ad4a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of double exclamation?', N'Intern', N'The double exclamation mark (!!) in JavaScript forces any value into its corresponding strict boolean representation (true or false). The !! (double negation) operator converts any value to its boolean equivalent: * First ! negates the value (converting it to a boolean) * Second ! negates it again, giving the true boolean representation Example: Note: It''s commonly used to explicitly cast a value to boolean without using Boolean(value).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e34851-f2e2-44a6-b254-a8f0a95249f0', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum ensure performance?', N'Fresher', N'Axum is built on high-performance Rust primitives, leveraging zero-cost abstractions and the highly efficient Tokio runtime. Its design avoids unnecessary allocations, making it very competitive in terms of throughput and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f1c34b5-bb3c-4d06-a348-a8f1641464ff', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does the NULL value represent in MySQL?', N'Junior', N'A NULL value represents the absence of data or an unknown value. It is distinct from an empty string or a zero, and it requires special handling in comparison operations because comparisons with NULL typically return UNKNOWN rather than true or false.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9b9180a-237a-4284-bf11-a8f183489d9f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle static file serving, and when should you avoid it?', N'Middle', N'Echo provides a simple Static method to serve files from a directory, which is convenient for development or small applications. In production with high traffic, it is generally recommended to serve static files via a reverse proxy like Nginx to offload the Go runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ac4a38d-b482-4fef-92f7-a8f18fda89a9', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the concept of a variable scope.', N'Intern', N'Variable scope defines the region of the program where a particular variable is accessible. A variable declared inside a block is local to that block, while global variables can be accessed from anywhere in the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'409502e4-6975-40f5-a4a4-a8f2564ce615', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the event queue', N'Intern', N'The event queue follows the queue data structure. It stores async callbacks to be added to the call stack. It is also known as the Callback Queue or Macrotask Queue. Whenever the call stack receives an async function, it is moved into the Web API. Based on the function, Web API executes it and awaits the result. Once it is finished, it moves the callback into the event queue (the callback of a promise is moved into the microtask queue). The event loop constantly checks whether or not the call stack is empty. Once the call stack is empty and there is a callback in the event queue, the event loop moves the callback into the call stack. But if there is a callback in the microtask queue as well, it is moved first. The microtask queue has a higher priority than the event queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c162b871-46be-49f8-aaac-a8f3b129f473', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the architectural risks of integrating jQuery into a React or Vue application?', N'Senior', N'Integrating jQuery creates a conflict in the ''source of truth'' for the DOM, as jQuery modifies elements directly while the framework expects to control them via state. This bypasses the framework''s reconciliation process, leading to UI inconsistencies and unpredictable behavior when the framework attempts to update elements modified by jQuery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d7f971a-2900-4a76-9f42-a8f4683fbc6f', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''autocomplete'' attribute on form inputs?', N'Middle', N'The ''autocomplete'' attribute provides hints to the browser regarding the expected data type, such as names, emails, or addresses. This allows the browser to offer pre-filled data from the user''s stored information, significantly improving form conversion rates and user convenience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'632ef4ee-3eeb-474e-a321-a8f5dce06086', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Discuss the trade-offs of using Edge Runtime versus the Node.js runtime for API handlers.', N'Senior', N'The Edge Runtime offers significantly lower latency by running code closer to the user, but it has limitations regarding supported Node.js APIs and memory size. The Node.js runtime is more versatile and suitable for complex tasks, but it incurs higher latency due to the geographic distance between the server and the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49425f40-3e31-4e1f-bf5d-a8fb33c0e3a4', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s handling of the ''this'' keyword in event callbacks differ from standard ES6 arrow functions?', N'Senior', N'In jQuery callbacks, ''this'' refers to the DOM element that triggered the event, which is vital for traditional jQuery patterns. Arrow functions do not have their own ''this'' context, meaning they will fail in scenarios where the library expects access to the DOM node via the lexical scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b9f4ab0-f39c-4d5b-87b0-a8fba0861712', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is the Preact ecosystem large?', N'Intern', N'While smaller than React''s ecosystem, the Preact ecosystem is robust. Most libraries built for React work seamlessly with Preact, especially when using the compatibility layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5e507d7-33f8-4028-97dd-a8fba846679e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the lifecycle of a Svelte component?', N'Fresher', N'The lifecycle consists of stages such as creation, mounting to the DOM, updating, and destruction. Svelte provides built-in lifecycle functions that allow developers to run code at specific points in these stages, such as after a component is mounted or before it is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adcdba07-7401-425b-8505-a8fce40bc990', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between ''text'' and ''keyword'' field types?', N'Intern', N'A ''text'' field is analyzed, meaning the content is broken into individual words for full-text search. A ''keyword'' field is not analyzed and is used for exact matching, sorting, and aggregations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a6f5397-78d2-4216-9e35-a8ff32591bef', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle CORS?', N'Intern', N'CORS, or Cross-Origin Resource Sharing, is handled in FastAPI using a built-in middleware. It allows developers to specify which origins are permitted to access the API, preventing unauthorized cross-domain requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9783395-ac29-4602-b456-a9013f76b92a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you update Node.js to the latest version?', N'Fresher', N'Regular updates ensure that your Node.js setup is secure, efficient, and equipped with the latest features. Here''s how to keep it up-to-date. Using Package Managers - NPM: Run the following commands to find and install the latest stable version of Node.js: - Yarn: Execute the following command that fetches the latest version and updates Node.js in your system: Using the Official Installer You can use the official installer to upgrade to the latest stable version. Version Management Tools Tools like nvm (Node Version Manager), n (Node Version Manager) and nvs (Node Version Switcher) can be convenient for managing multiple Node.js versions and performing updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2ca3b0b-3003-4dda-bc09-a904c1c6888d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix Views?', N'Intern', N'Views in Phoenix are modules that prepare data for rendering. They act as a bridge between the controller and the templates by transforming raw data into a format suitable for display.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f253ebf2-8b14-4897-8859-a90805c7412e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a trampoline function? What is it used for?', N'Intern', N'The trampoline is just a technique to optimize recursion and prevent stack-overflow exceptions in languages that don''t support tail call optimization like Javascript ES5 implementation. However, ES6 will probably have support for tail call optimization. The problem with regular recursion is that every recursive call adds a stack frame to the call stack, which you can visualize as a pyramid of calls. Here is a visualization of calling a factorial function recursively: Here is a visualization of the stack where each vertical dash is a stack frame: The problem is that the stack has limited size, and stacking up these stack frames can overflow the stack. Depending on the stack size, a calculation of a larger factorial would overflow the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20249803-2594-4aee-a039-a909cd42099b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Can you explain how useState works internally?', N'Junior', N'React’s hooks, including useState, rely on some internal machinery that keeps track of state per component and per hook call during rendering. Here''s a simplified explanation of the internal mechanics: 1. Hook List / Linked List * React maintains a linked list or array of "hook states" for each component. * When a component renders, React keeps track of which hook it is currently processing via a cursor/index. * Each call to useState() corresponds to one "slot" in this list. 2. State Storage * Each slot stores: * The current state value. * A queue of pending state updates. 3. Initial Render * When the component first renders, React: * Creates a new slot for useState with the initial state (e.g., 0). * Returns [state, updaterFunction]. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca9a7346-c8f5-45e1-8c7c-a909f7a37c64', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is an Environment file (.env) and why is it important?', N'Fresher', N'The .env file is used to store sensitive configuration variables that change depending on the environment, such as database credentials and API keys. It keeps these configuration values separate from the application code, which enhances security and simplifies deployment across different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f4e142e-280c-436a-97a8-a90b3a2d8260', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does it mean for a pointer to be ''null''?', N'Junior', N'A null pointer is a pointer that does not point to any valid memory address. It is used to signify that the pointer is currently not referencing a specific object or data. Attempting to access or dereference a null pointer typically results in a runtime error or program crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38a14e70-649d-4a65-95bc-a90b8ad95ba7', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why is Micronaut considered well-suited for serverless functions and microservices?', N'Intern', N'Because Micronaut uses compile-time injection, it suffers from no ''cold start'' penalty caused by reflection-heavy frameworks. This makes it ideal for environments where fast startup times and low memory consumption are critical, such as AWS Lambda.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5961285b-32b4-402e-bc89-a90cfa6f9d3b', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the advantages and trade-offs of using Django''s built-in ORM versus writing raw SQL?', N'Middle', N'The ORM provides abstraction, security against SQL injection, and portability across different database engines, which speeds up development. However, raw SQL may be necessary for highly complex queries that are inefficient or impossible to express using the ORM''s syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b879f51-e7b1-48f0-b046-a90f43e0cc06', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue where a distributed cache is frequently experiencing high eviction rates?', N'Senior', N'I would analyze the cache hit ratio and key distribution patterns to determine if the eviction is caused by an undersized cache or a change in application data access patterns. I would then investigate if the cache key strategy is too granular or if specific hot keys are causing cache stampedes, potentially requiring a re-evaluation of the TTL or caching strategy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38e4d2cf-f6b8-415b-b9ca-a910056f17dd', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is ''database-per-service'' a recommended pattern in microservices, and what are the trade-offs?', N'Senior', N'It ensures loose coupling and allows each service to choose the best storage technology for its specific use case. The main trade-off is the increased complexity of maintaining data consistency across services and the challenge of performing cross-service analytical queries, which often requires a dedicated data lake or reporting service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fbea36c-9e8d-4d21-a4cd-a911073b599e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the required cache hit ratio for a system to meet a specific latency SLA?', N'Senior', N'I calculate the latency delta between cache hits and database misses, then use Little’s Law and request distribution modeling to determine the minimum hit rate required to keep average response times within the SLA. This allows me to define the cache sizing and eviction policy requirements needed to maintain performance under peak load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76bb8c7e-eac3-4661-a033-a9137226f210', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the architectural trade-offs between using Shadow DOM versus standard DOM encapsulation.', N'Senior', N'Shadow DOM provides true style and DOM isolation, preventing CSS bleed and internal component leakage, which is crucial for building robust design systems. However, it introduces complexity in global styling, potential accessibility challenges with focus management, and increased memory overhead compared to standard DOM structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85a0d668-cb02-4db3-9138-a918e64d3b2c', N'954a0331-deff-4399-b588-96f39fec001d', N'What is incremental hydration?', N'Intern', N'Incremental hydration is a technique used in Angular Server-Side Rendering (SSR) applications to improve performance, specifically the Time To Interactive (TTI). Instead of hydrating the entire application''s DOM and attaching event listeners all at once after the client-side JavaScript loads, incremental hydration allows Angular to hydrate and make individual components interactive incrementally. This means parts of your application become interactive sooner, leading to a faster perceived performance and a better user experience, especially on slower networks or devices. It preserves the server-rendered HTML structure and attaches behavior without re-rendering the entire page. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd864159-4176-48fd-977c-a91977c74abb', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the trade-offs of using Server-Side Rendering (SSR) compared to Static Site Generation (SSG) in Nuxt?', N'Middle', N'SSR provides dynamic, real-time data for each request, which is ideal for user-specific content, but it requires a Node.js server. SSG generates pages at build time, offering extremely fast performance and lower hosting costs, but it requires a new build to update content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'054e5e4f-3999-4927-9aed-a9198e1ade89', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass modules improve the compilation speed compared to the old global scope architecture?', N'Senior', N'Modules ensure that each file is parsed and compiled exactly once, regardless of how many times it is referenced in the project. The old global scope required the compiler to re-process dependencies repeatedly, leading to exponential build time growth in large projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b27124e-7cec-4bfb-9afd-a91a0e577c05', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between structural typing and nominal typing?', N'Junior', N'TypeScript uses structural typing, meaning if two types have the same shape, they are considered compatible. Nominal typing, found in languages like Java, requires explicit compatibility regardless of whether the structures match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca9fc13c-4d94-465f-895d-a91a838c8e8a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is data denormalization in NoSQL?', N'Intern', N'Denormalization involves storing related data together in a single document or record instead of splitting it across multiple tables. This reduces the need for expensive join operations, leading to faster read performance in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81d2887b-e601-4d4d-921e-a91e31d4aba8', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why would you choose to use the Spring WebFlux stack over the traditional Spring MVC stack?', N'Senior', N'WebFlux is designed for asynchronous, non-blocking communication, making it ideal for systems requiring high concurrency with limited resources. You should choose it for streaming data or when your application relies heavily on non-blocking external services, whereas MVC remains better for standard CRUD applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76a1ea18-2b2d-47fd-b893-a91f17919212', N'954a0331-deff-4399-b588-96f39fec001d', N'What are signals and why is it introduced?', N'Intern', N'Signals, available from Angular 16 onwards, are a new reactive primitive that provide a way to manage state changes in a more explicit and efficient manner. They are simple wrappers around values that notify interested consumers when the value changes. The primary reasons for introducing signals are: - Simplifying change detection: Signals enable fine-grained reactivity, allowing Angular to update only the specific parts of the UI that depend on a changed signal, rather than potentially checking the entire component tree via Zone.js. - Improving performance: By reducing the amount of work needed for change detection, signals can significantly improve application performance, especially in complex applications. They also pave the way for potential future zoneless applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f82bf32c-9fcc-45c5-a5e8-a920b190d3e6', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you handle scope in Python when nested functions access outer variables?', N'Middle', N'Python uses the LEGB rule (Local, Enclosing, Global, Built-in) to resolve variable scope. When a nested function modifies an outer variable, the ''nonlocal'' keyword must be used to explicitly signal that the variable is not local to the current scope but belongs to an enclosing function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa0a4139-1ef8-408c-8bce-a920b8dd7f2c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of the partition key in data distribution?', N'Fresher', N'The partition key determines the logical and physical distribution of data across multiple partitions. A well-chosen partition key ensures that data is spread evenly across the storage system, preventing performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ad419e-670a-4789-b7b1-a92108c8d99b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What does ''Forward Reference'' solve in NestJS?', N'Middle', N'It solves the circular dependency problem where two modules depend on each other. By using forward references, you allow NestJS to resolve the dependencies in an order that avoids undefined provider errors during initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d6d96ac-dbc5-4baa-b277-a923101b0a0c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the @app.route decorator?', N'Junior', N'The @app.route decorator maps a specific URL path to a Python function. When a request matches the defined URL, Flask executes the associated function and returns the result as an HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
