INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdad23c8-5279-4b3a-9758-a924dd49cbf3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why would you use a unique constraint?', N'Junior', N'A unique constraint ensures that all values in a column are different from one another. This prevents duplicate entries in columns that are not necessarily the primary key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
