INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e8ea36b-aa2e-4bd0-a40a-a93789619d7e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the difference between function foo() {} and var foo = function() {}?', N'Fresher', N'1. Function Declaration: Function declarations are evaluated upon entry into the enclosing scope, before any step-by-step code is executed. The function''s name (foo) is added to the enclosing scope. 2. Function Expression: Function expressions are evaluated as part of the step-by-step code, at the point where they appear. That one creates a function with no name, which it assigns to the foo variable. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c786846d-e511-4318-8e42-a93828fddde5', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is an atomic vector in R?', N'Intern', N'An atomic vector is the simplest data structure in R that stores a sequence of elements of the same data type. Common types include logical, integer, double, and character, and every element within the vector must be of the same type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
