INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1527b54-7557-4f01-88bf-a939eeae3174', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the limitations of ''Master-Slave'' replication in a high-concurrency environment?', N'Senior', N'Master-slave replication creates a bottleneck at the primary node for all write operations, limiting write scaling. Additionally, there is an inherent replication lag between the master and slaves, which can lead to read-after-write consistency issues for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
