INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3d0614-6160-47a7-9c67-a9418477c70d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between ''eager_load'' and ''preload'' in Active Record?', N'Middle', N'Preload always loads associations in a separate query using an IN clause, whereas eager_load forces a LEFT OUTER JOIN to load the association in a single query. Preload is better for avoiding large Cartesian products, while eager_load is useful when you need to filter the main query based on columns in the associated table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'215a6a3d-eea3-4583-b751-a9418d7b47d2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are mapped types and why would you use them?', N'Middle', N'Mapped types allow you to create new types based on the properties of an existing type by iterating over its keys. They are essential for creating utility types that transform object shapes, such as making all properties optional, read-only, or mapping them to a different value type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
