INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c64adaa-e069-4fca-b959-a94575dba659', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to design with ''monitoring and observability'' in mind?', N'Intern', N'Designing for observability ensures that you can understand the state of the system by examining its outputs. This allows engineers to quickly detect, diagnose, and resolve issues in production, which is essential for maintaining a reliable service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2af4f5f0-eed1-462b-b072-a946d9886f4c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis ensure data consistency in a primary-replica replication setup?', N'Senior', N'Redis uses asynchronous replication by default, meaning there is a small window where data might be lost if the primary fails before propagating changes to replicas. For stronger consistency, users can implement the WAIT command, which forces the primary to wait for a specified number of replicas to acknowledge the write before returning success.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f134eb1-adff-4391-a3a5-a9471406cdea', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the trade-offs of using ''defineAsyncComponent'' for code splitting?', N'Senior', N'Defining components asynchronously allows for lazy-loading, which significantly reduces the initial bundle size and improves load times for large applications. The trade-off is the added complexity of managing loading, error, and timeout states, as well as potential network latency when the component is first requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c66a6e-2ac0-48ea-a32a-a947438167c9', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the Spring Event mechanism, and when should you avoid it?', N'Senior', N'Spring Events provide an observer pattern implementation for loose coupling between components. You should avoid them for critical, synchronous business logic because they can make the application flow difficult to trace and debug due to the lack of clear, direct method calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59bfda60-68f6-4df7-82ea-a949fb1927b4', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does the ''important'' configuration option in Tailwind affect style predictability?', N'Senior', N'Setting the ''important'' flag globally forces every utility class to include ''!important'', which can make debugging layout issues extremely difficult. It is generally discouraged in large applications as it breaks the natural CSS cascade and makes it nearly impossible to override styles without further ''important'' declarations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11b34721-8875-4eae-a983-a94b88fc1014', N'075b8862-431c-4678-9767-f55359758a4a', N'What are plugins and their various services?', N'Intern', N'Plugins provides global-level functionality to Vue application. The plugins provide various services, 1. Add some global methods or properties. For example, vue-custom-element 2. Add one or more global assets (directives, filters and transitions). For example, vue-touch 3. Add some component options by global mixin. For example, vue-router 4. Add some Vue instance methods by attaching them to Vue.prototype. 5. A library that provides an API of its own, while at the same time injecting some combination of the above. For example, vue-router', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2d5aa14-5bda-480c-96cd-a94e4529ff3f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are AdonisJS Validators, and how do they improve security?', N'Junior', N'Validators are used to enforce schema rules on incoming request data. They improve security by sanitizing and verifying input before it reaches the business logic, preventing issues like mass assignment or malformed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66e79ff3-2c22-4bec-b6ae-a951f26c3673', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the ACID acronym stand for in database systems?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These are the four fundamental properties that ensure a database transaction is processed reliably.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78e6f5e7-3fb2-4023-b8e7-a95300e93a46', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do you handle atomic operations in Redis?', N'Fresher', N'Redis primarily employs single-operation atomicity at the level of commands or scripts. This minimizes race conditions and makes data management safer. To ensure atomicity during multi-step processes, Redis supports Transactional Commands and WATCH-EXEC Mechanism for additional layers of consistency. Multi-Step Atomicity Mechanisms 1. WATCH-EXEC: Protects transactional integrity of specific keys by monitoring them. The ensuing multi-step EXEC block ensures actions are processed only if the watched keys are unaltered. 2. MULTI-EXEC: Encloses an array of commands to be executed atomically, either all together or none at all. This safeguards against partial executions of the enclosed commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fe79fa6-29a0-422f-89ea-a953fa7751d3', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of a Load Balancer in a distributed system?', N'Middle', N'A load balancer distributes incoming network traffic across multiple servers to ensure no single server bears too much load. This improves responsiveness, increases availability by routing around failed instances, and allows for seamless scaling of the backend fleet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97e82848-2804-484f-8f8a-a9553b46ce5a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM enforce type safety at the bytecode level?', N'Senior', N'The JVM uses a bytecode verifier that checks for type consistency, stack depth validity, and proper initialization before allowing code execution. This ensures that even if bytecode was generated by a non-Java compiler, it cannot violate memory integrity or access private fields of other classes, maintaining a secure execution environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60a86be3-3c2b-408d-bd29-a955803e4059', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the architectural benefit of using Laravel''s ''Resources'' layer for API responses?', N'Senior', N'Resources act as a transformation layer that decouples your internal database schema from your public API contract. This allows you to refactor database columns or rename fields without breaking API consumers, as the Resource class maintains the mapping to the public-facing response structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0432ac53-7440-4a8e-a64b-a955b129d91e', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How do you add interactivity to an Astro page?', N'Junior', N'You add interactivity by importing UI components from frameworks like React, Vue, or Svelte and applying a client directive to them. This tells Astro to load the necessary JavaScript for those specific components only.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce9220df-be33-4f75-a595-a9569cbe80e4', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle environment variables and why is ''import.meta.env'' used?', N'Middle', N'Vite exposes environment variables through the import.meta.env object to ensure compatibility with ESM standards. It also uses a prefix strategy to prevent accidental exposure of sensitive server-side variables to the client-side bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'146735f2-14a2-4415-8e87-a95a04ddc04e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the primary advantage of using ''Symbol'' as an object key?', N'Senior', N'Symbols provide unique, immutable identifiers that are guaranteed to be unique even if the same description is used. This prevents property name collisions, particularly when adding metadata or private properties to objects that may be extended or merged by third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c611462-dc08-4d7d-a404-a95a50f1293f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s ''Object Space'' work and why is it considered a performance hazard?', N'Senior', N'ObjectSpace allows an application to iterate over every active object in the heap, which requires the VM to pause and traverse the entire memory graph. Enabling this feature prevents certain optimizations and increases GC overhead, making it unsuitable for production environments with high memory churn.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45d920d4-e817-4ae0-8775-a95aae8660cb', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte considered more performant in terms of bundle size?', N'Middle', N'Because Svelte compiles to native DOM operations, the resulting JavaScript bundle does not need to include a heavy framework runtime. This results in significantly smaller initial load sizes compared to frameworks that ship their entire VDOM engine to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dcfa9ac-e343-4aca-9d83-a95c41a9b061', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of ''closures'' in R and their utility in factory functions.', N'Senior', N'Closures are functions that retain access to the environment in which they were created, even after that environment has finished executing. They are highly effective for creating factory functions that encapsulate configuration state and constants, providing a clean interface for generating specialized sub-functions without relying on global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6fc5860-fc52-4faa-9bab-a95d2dd295de', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you update arrays inside state?', N'Fresher', N'Eventhough arrays in JavaScript are mutable in nature, you need to treat them as immutable while storing them in a state. That means, similar to objects, the arrays cannot be updated directly inside state. Instead, you need to create a copy of the existing array and then set the state to use newly copied array. To ensure that arrays are not mutated, the mutation operations like direct direct assignment(arr[1]=''one''), push, pop, shift, unshift, splice etc methods should be avoided on original array. Instead, you can create a copy of existing array with help of array operations such as filter, map, slice, spread syntax etc. For example, the below push operation doesn''t add the new todo to the total todo''s list in an event handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06ee149f-2a8e-49d2-9bd5-a95e2f44b10c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the best way to handle ''noisy neighbor'' issues in a multi-tenant SaaS platform?', N'Senior', N'I would implement strict resource quotas and rate-limiting at the API gateway level to ensure no single tenant can monopolize shared infrastructure. Furthermore, I would utilize container orchestration features to enforce CPU and memory limits, and consider isolating high-value tenants into dedicated compute clusters if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4115b36b-4244-4d3a-8794-a95e38a6de45', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the difference between ''Middleware'' and ''Guards'' in the context of Litestar.', N'Middle', N'Middleware wraps the entire request-response cycle and can modify both the request and response objects globally. Guards are specifically tied to route handlers and focus on conditional execution or authorization, making them more granular and easier to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e1e4dea-d21b-4507-ab88-a95fb753fa6e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle multipart/form-data requests?', N'Middle', N'Actix-web provides a dedicated payload extractor for multipart data, which streams the incoming body content to avoid loading the entire file into memory. This is critical for building performant file upload services that remain responsive under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db87dafb-9f21-44c8-a5af-a962445556c4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach estimating the impact of a database schema change on an existing production system?', N'Middle', N'I would perform a risk assessment on the migration path, checking for table locking issues and potential downtime during the schema update. I would ensure the change is backward compatible where possible and prepare a rollback script to mitigate the impact of unforeseen failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75231c39-56e0-4966-81de-a9644fd7c333', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the trade-offs of using an event-driven architecture?', N'Middle', N'Event-driven systems offer high scalability and loose coupling, making the system more responsive. However, they introduce complexity regarding eventual consistency, debugging, and the need for robust event delivery guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e05cbf6-c5bf-4a10-8faf-a9645fc76215', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What happens if a validation error occurs in a FastAPI endpoint?', N'Junior', N'FastAPI automatically catches validation errors from Pydantic models and returns a 422 Unprocessable Entity response. This response includes a clear, structured JSON body detailing exactly which fields failed and why.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98b71639-50bd-493d-ab70-a965789ae376', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you ensure that Express handles unexpected crashes without impacting the entire user base?', N'Senior', N'By running multiple instances of the application behind a load balancer and using a process manager to monitor health, you ensure high availability. If one process crashes, the load balancer routes traffic to healthy instances while the orchestrator automatically restarts the failed process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81869815-720c-4352-82a9-a968e1edd362', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the ''handle'' function in ''hooks.server.js''?', N'Middle', N'The handle function is the main entry point for server requests, allowing you to intercept and transform the request object. It is the primary location for implementing global middleware like session validation, cookie parsing, or request logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6877f20-679c-49e5-85f1-a96ac155bd2d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is type erasure in Java Generics and why is it implemented?', N'Middle', N'Type erasure is the process where the compiler removes all generic type information at compile time, replacing it with the raw type or bounded type. It was implemented primarily to maintain backward compatibility with older versions of Java that did not support generics. This means generic type information is not available at runtime, which imposes certain limitations on operations like array creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5783f67-8620-43c5-b88b-a96b4d36d782', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are lambda expressions or arrow functions', N'Intern', N'Arrow functions (also known as "lambda expressions") provide a concise syntax for writing function expressions in JavaScript. Introduced in ES6, arrow functions are often shorter and more readable, especially for simple operations or callbacks. Key Features: - Arrow functions do not have their own this, arguments, super, or new.target bindings. They inherit these from their surrounding (lexical) context. - They are best suited for non-method functions, such as callbacks or simple computations. - Arrow functions cannot be used as constructors and do not have a prototype property. - They also cannot be used with new, yield, or as generator functions. Syntax Examples:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18c8590d-daea-4a87-a1d0-a96bb2f9cb99', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s ''shallow routing'' or ''goto'' navigation?', N'Middle', N'Using ''goto'' allows for programmatic navigation without triggering a full browser page refresh. This maintains the application state and provides a significantly faster user experience by only fetching the necessary data for the destination route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8062b1db-5098-4cc3-8f31-a96c607069cd', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''IHostedService'' or ''BackgroundService'' in ASP.NET Core?', N'Middle', N'These interfaces are used to implement long-running background tasks within an application. They are useful for processes like processing message queues, running scheduled cleanup tasks, or performing recurring background maintenance without blocking the main request pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
