INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d95159f-b92c-44e5-a8b7-a98d84aac302', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between synchronous and asynchronous design in Swift''s concurrency model?', N'Senior', N'Synchronous design blocks the execution thread until completion, which can lead to resource contention and thread starvation in high-concurrency systems. Asynchronous design, using Swift''s structured concurrency, allows the system to suspend tasks and reclaim threads, improving scalability and responsiveness. This model prevents common issues like deadlocks and priority inversion by managing task execution on a cooperative thread pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
