INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ce95010-6dd7-4da8-b959-a99aebd17bf4', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the significance of the ''Ember Octane'' shift for the framework''s evolution?', N'Senior', N'Octane represents a major architectural shift toward modern JavaScript standards, emphasizing native classes, tracked properties, and component-first development. It significantly reduced framework-specific boilerplate, making Ember more accessible to standard web developers and easier to integrate with the broader JS ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'756fe5b3-e755-4502-bbe0-a99b9a596f31', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is ''preconnect'' often more effective than ''dns-prefetch'' for performance optimization?', N'Senior', N'While dns-prefetch only resolves the domain name, preconnect performs the full DNS resolution, TCP handshake, and TLS negotiation. This saves several round-trip times for subsequent resource requests, providing a more significant performance boost for critical third-party dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
