INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'085ffaf0-11bc-43fc-b11e-a99e9698e430', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ASP.NET Core configuration system support dynamic updates without requiring an application restart?', N'Senior', N'The configuration system uses IOptionsMonitor or IOptionsSnapshot to listen for changes in the underlying configuration sources, such as JSON files or environment variables. This allows the application to react to configuration changes in real-time by re-binding the options objects whenever the source is modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dceadea9-3406-410a-9fa8-a99f3fbbd94e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of ''Rate Limiting'' middleware, and how does it prevent resource exhaustion?', N'Senior', N'Rate limiting restricts the number of requests a client can make within a specific time window, protecting the system from denial-of-service attacks or noisy neighbors. It ensures that critical resources remain available for all users by preventing individual clients from overwhelming the backend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
