INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c3be787-c29e-4bf8-9701-a9a983de4ec7', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the trade-offs of using Astro’s ''client:only'' directive versus ''client:load''?', N'Senior', N'The ''client:only'' directive skips server-side rendering entirely, executing the component only in the browser, which is useful for client-dependent libraries that rely on window objects. ''client:load'' performs server-side rendering first to provide immediate content and then hydrates the component, offering better SEO and faster perceived initial load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fe8526a-2484-40ef-bc63-a9ac158d43d0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does a system''s state impact bug reproducibility?', N'Fresher', N'The system''s state, such as the current database content or active user sessions, can influence how the code executes. Bugs often depend on specific state conditions, so resetting the environment is crucial for consistent reproduction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f08c68cd-5eb4-4dd8-954b-a9acf3dcebc0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary difference between a relational database and Cassandra?', N'Fresher', N'Relational databases use a fixed schema and emphasize ACID properties, making them suitable for complex transactions. Cassandra uses a flexible, column-oriented data model and prioritizes high availability and partition tolerance, making it better suited for massive scale and high-speed write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f994853-b1d3-41c3-b8cd-a9ad1081ec1f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does memory-mapped I/O influence MongoDB''s performance?', N'Senior', N'MongoDB relies on the operating system''s virtual memory manager to map data files directly into the address space. This allows the OS to handle caching and paging efficiently, though it requires careful tuning of the OS-level swappiness and memory limits to prevent performance stalls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
