INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54e9a94a-ddcd-4156-8e88-a9b0bb96b932', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you determine if a performance degradation is caused by network issues or application logic?', N'Senior', N'I look at TCP retransmission rates, round-trip time (RTT) metrics, and packet loss statistics from the infrastructure layer. If network metrics are clean, I shift to application-level profiling to look for inefficient serialization, blocking I/O, or high lock contention that correlates with the performance drop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999cca09-8620-4fe5-806f-a9b136315494', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is a package.json file?', N'Intern', N'The package.json file in Node.js projects contains valuable information, such as project metadata and dependencies. This file is essential for managing project modules, scripts, and version control and helps ensure the consistency and stability of your project. Key Elements The package.json file consists of several essential sections: 1. Name and Version: Required elements that identify the project and its version. 2. Dependencies: Separated into dependencies, devDependencies, and optionalDependencies which list package dependencies needed for development, production, or as optional features, respectively. 3. Scripts: Encompasses a series of custom commands, managed by npm or yarn, that can be executed to perform various tasks. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
