INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93142334-8eda-4828-837f-a9b2a0ed07e2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What happens when you execute a COMMIT command?', N'Junior', N'The COMMIT command permanently saves all changes made during the current transaction to the database. Once committed, the changes become visible to other users and cannot be rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6d167e2-3318-4382-b4e9-a9b4c7fe6b49', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue 3''s reactivity system leverage Proxies compared to Vue 2''s Object.defineProperty?', N'Senior', N'Vue 2 used Object.defineProperty to intercept property access, which required deep recursion on initialization and could not detect property additions or deletions. Vue 3 uses ES6 Proxies, which wrap the entire object and intercept operations at the proxy level, enabling better performance, native support for Maps and Sets, and automatic detection of dynamic property changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21dc7d3a-d3d2-47d5-be1a-a9b67010a19e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you diagnose a production issue where a service is consuming excessive CPU but the application logs show no errors?', N'Senior', N'I would use profiling tools to generate a CPU flame graph to pinpoint which specific functions or threads are consuming the most cycles. If the profile indicates frequent garbage collection, I would investigate heap fragmentation; if it indicates busy-wait loops or inefficient serialization, I would focus on algorithmic complexity or locking contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd7252ec-a191-4c1e-bace-a9b78782ac36', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI perform type conversion?', N'Fresher', N'FastAPI uses Python type hints to automatically convert incoming data from strings (like those found in URLs) into the expected Python types like integers, booleans, or lists. If the conversion fails, it automatically returns a validation error to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc7be139-5d9e-42b1-b3d3-a9bc06d90da7', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a Join and a Union?', N'Fresher', N'A Join is used to combine columns from two or more tables based on a related column between them. A Union is used to combine the result sets of two or more select statements into a single result set, provided the columns match in data type and number.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a52802a3-9acc-41a9-b748-a9bc5a6d7db2', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why is the singleton scope the default in Spring, and what are the concurrency implications?', N'Senior', N'Singleton scope is the default because it is highly memory-efficient and reduces the overhead of constant object instantiation. However, since singleton beans are shared across threads, developers must ensure they are thread-safe by avoiding mutable instance variables or using synchronization/concurrent collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cc45e01-9ee8-4d4e-932b-a9bd1a7a5e89', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''any'' type in TypeScript and why should it be used sparingly?', N'Fresher', N'The ''any'' type tells the TypeScript compiler to disable type checking for a specific variable, effectively treating it like standard JavaScript. It should be used sparingly because it defeats the purpose of using TypeScript by bypassing type safety, which can lead to unexpected runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f092bf3f-10ad-49ab-bae2-a9bda6eb273e', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'When should you choose a distributed log system like Apache Kafka over a traditional queue like RabbitMQ?', N'Middle', N'You choose Kafka when you need high throughput, message replayability, and long-term data retention for stream processing. RabbitMQ is generally better suited for complex routing logic and scenarios where individual message acknowledgement and immediate task completion are prioritized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc656a44-3a43-4842-bd01-a9c05349c010', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is the SAGA pattern preferred over distributed transactions in microservices architectures?', N'Senior', N'SAGA breaks a global transaction into a series of local transactions that execute sequentially, each with a corresponding compensating transaction to undo changes if a step fails. This avoids the long-lived database locks associated with 2PC and provides better availability and scalability in loosely coupled environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18f874ac-93c2-4742-a551-a9c09aaa3e67', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the risks associated with the ''Fast'' prefix in Fiber''s underlying engine regarding HTTP protocol compliance?', N'Senior', N'Fasthttp prioritizes speed by making assumptions that may violate strict HTTP/1.1 or 2.0 standards, such as header order or specific whitespace handling. For public-facing APIs that require absolute compliance with legacy clients or strict proxies, these optimizations could cause intermittent handshake or parsing failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93d170b0-4d64-4e62-82e3-a9c28cbce69b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why are transactions harder to implement in distributed databases?', N'Intern', N'Distributed databases span multiple servers, making it difficult to coordinate changes simultaneously. Maintaining ACID properties requires complex protocols to ensure all nodes agree on the state of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da5d8b7e-99f5-40f4-a628-a9c2cbceaf3c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to document the steps taken during a troubleshooting process?', N'Intern', N'Documenting your steps ensures you do not repeat failed attempts and provides a clear audit trail for others who might encounter the same issue. It also helps you verify which actions actually contributed to the solution, allowing for better future prevention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58e75bc3-3c99-42aa-980d-a9c68023796c', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle ''split-brain'' scenarios in cluster discovery?', N'Senior', N'Elasticsearch uses an election-based consensus algorithm that requires a quorum of master-eligible nodes to form a cluster. By enforcing a minimum number of active master-eligible nodes, the system prevents multiple nodes from believing they are the master, thereby ensuring data consistency and preventing split-brain conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'952871f1-263c-4c1c-a256-a9c6e27d5d41', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Discuss the trade-offs of using FastAPI''s built-in background tasks versus an external task queue like Celery.', N'Senior', N'Built-in background tasks are simple to implement for fire-and-forget operations within the same process but lack persistence, retry mechanisms, and horizontal scalability. Celery provides a robust, distributed architecture suitable for long-running, fault-tolerant, and high-throughput background processing across multiple worker nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'157132e9-a38f-47b4-9809-a9c79a6c74df', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the limitations of using the Preact compat layer in a highly custom UI library?', N'Senior', N'The compat layer may struggle with highly specialized React patterns, such as deep context manipulation or complex ref forwarding, which might not be perfectly mimicked in the Preact runtime. If a UI library relies heavily on React internals or private APIs, those features will likely fail or require significant refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67c201db-1755-4834-b182-a9c7bf6aacc3', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt middleware differ from server-side Nitro middleware?', N'Senior', N'Nuxt route middleware executes during the client-side transition or server-side request flow for UI navigation control, such as authentication checks. Nitro middleware operates at the server engine layer, handling HTTP requests and responses globally before they reach the Nuxt application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fd5933b-6ab9-4853-9725-a9c8df9528d5', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the difference between a high-level estimate and a detailed estimate?', N'Fresher', N'A high-level estimate is typically done early in a project with limited information to gauge feasibility. A detailed estimate is performed after requirements are fully understood, providing a more accurate prediction of time and resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02186e5c-32f7-4b19-b638-a9cb50b0a587', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the benefit of lazy loading modules in an Angular application?', N'Middle', N'Lazy loading improves the initial load time of an application by splitting the bundle into smaller chunks that are only downloaded when the user navigates to a specific route. This reduces the amount of code the browser must parse and execute immediately, significantly improving startup performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0811920-9313-4d0d-a86c-a9cdf5db3588', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra maintain high availability during a partial cluster failure?', N'Senior', N'Cassandra uses a peer-to-peer gossip protocol to monitor node health and detects failures in real-time. By utilizing replication factors and tunable consistency, the system can route requests to healthy replicas, ensuring that the cluster remains operational as long as at least one replica is available for the given consistency level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
