INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0b6d7ef-abce-4417-9a07-a9d2f13d4919', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between @ApplicationScoped and @RequestScoped in Quarkus?', N'Junior', N'ApplicationScoped beans are created once and shared across the entire application lifespan. RequestScoped beans are created at the start of an HTTP request and destroyed once that specific request has been completed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
