INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64d88951-763b-4a1e-9b21-a9d459b55cc8', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between a route handler and middleware?', N'Intern', N'A route handler is the final function that generates the response for a specific URL path. Middleware is an intermediary function that runs before or after the handler to perform auxiliary tasks like logging or security checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d2dd80c-e8e3-43d8-a7cf-a9d471a66a79', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the primary difference between a primary-replica and a multi-primary replication topology?', N'Senior', N'Primary-replica architectures simplify conflict resolution by centralizing writes to one node, which is ideal for read-heavy workloads. Multi-primary allows writes to any node, improving write availability and latency, but introduces significant complexity in managing write conflicts and causal consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61c68960-6a58-473d-935a-a9d4aaecb4e6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do Go interfaces differ from class-based polymorphism in languages like Java?', N'Middle', N'Go utilizes implicit implementation, meaning types satisfy interfaces by simply defining the required methods rather than explicitly declaring them. This decoupling allows for more flexible code organization and easier integration of third-party types without modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f1336f9-d6db-4bb0-a6d1-a9d79610aa34', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What does ''ACID'' stand for and why is it often discussed with NoSQL?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability, which are the standard properties of traditional relational database transactions. NoSQL databases are often contrasted with SQL because they typically trade off strict ACID compliance for better performance and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dd533a2-b0bc-46a9-aa17-a9d81268891c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Describe the evolution of Go''s garbage collector and its impact on latency.', N'Senior', N'Go''s garbage collector has evolved from a stop-the-world collector to a concurrent, tri-color mark-and-sweep collector. This shift significantly reduces pause times to sub-millisecond ranges, making the language suitable for low-latency services, though it requires a trade-off in higher CPU usage and potential memory throughput overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
