INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46302e5f-7aaa-4712-bb69-a9e064c62a40', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ''alt'' text and ''title'' attributes?', N'Middle', N'The ''alt'' attribute provides a textual description of an image for screen readers and serves as a fallback if the image fails to load. The ''title'' attribute provides supplemental, advisory information that is usually displayed as a tooltip on hover. While ''alt'' is mandatory for accessibility, ''title'' is optional and should not be used for critical information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
