INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'958a3e69-7308-4dd6-9dd9-a9e1a2386e6d', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is meant by ''schema-on-read'' versus ''schema-on-write''?', N'Middle', N'Schema-on-write requires data to conform to a pre-defined structure before it is stored, ensuring high data quality. Schema-on-read allows data to be stored in its raw format, with the structure defined only when the data is queried, offering flexibility for data exploration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
