INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f29a173d-cc7a-4f8d-9cff-a9e5c21d1d87', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle context propagation across the component tree?', N'Senior', N'Preact uses a provider-consumer pattern that traverses the tree to pass state implicitly. When a provider''s value updates, Preact performs a top-down update starting from the provider, ensuring all consumers receive the latest value without requiring explicit prop drilling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eab1ce6-5a27-4c0c-9d45-a9e7d8f49afe', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are hooks?', N'Intern', N'Hooks is a special JavaScript function that allows you use state and other React features without writing a class. This pattern has been introduced as a new feature in React 16.8 and helped to isolate the stateful logic from the components. Let''s see an example of useState hook: Note: Hooks can be used inside an existing function component without rewriting the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d73464f-ae66-4434-b541-a9e7f4cfe203', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Request object in Symfony?', N'Intern', N'The Request object represents an incoming HTTP request from the client. It encapsulates all data sent by the user, including URL parameters, headers, cookies, and file uploads, in a single, accessible object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c351d51b-94c3-4804-8089-a9e9b734d5ec', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL''s MVCC implementation impact storage management and what is the role of the autovacuum process?', N'Senior', N'PostgreSQL implements MVCC by storing multiple versions of rows, which leads to ''bloat'' when updates or deletes occur. The autovacuum process is essential to reclaim space by marking dead tuples as reusable and updating the visibility map, preventing performance degradation from long scan times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea6f3fa7-fd30-4748-8b60-a9ea77d2445b', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you ensure data integrity in Django when performing mass updates?', N'Senior', N'Data integrity is ensured by using transaction.atomic() blocks to ensure that either all updates succeed or none are applied. Additionally, using bulk_update() is more efficient than looping over objects and saving individually, as it minimizes database round-trips and reduces the window for race conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66f6d09a-16bc-4232-9d14-a9eba030ed58', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the function of the main() method?', N'Intern', N'The main() method is the entry point for every Dart application. When a program starts, the runtime environment looks for this top-level function to begin execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eecc2c97-aa7e-4b04-ac7b-a9ec8101ab56', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust not support function overloading?', N'Middle', N'Rust achieves similar functionality through traits and generic implementations, which are more explicit and easier to reason about. By avoiding overloading, the language keeps method resolution simple and predictable, reducing the ambiguity that often arises in complex inheritance hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ed069f9-2ae2-429b-8a0a-a9ee45710303', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'When to use client and server components?', N'Senior', N'You can efficiently build nextjs application if you are aware about which part of the application needs to use client components and which other parts needs to use server components. The common cases of both client and server components are listed below: Client components: 1. Whenever your need to add interactivity and event listeners such as onClick(), onChange(), etc to the pages 2. If you need to use State and Lifecycle Effects like useState(), useReducer(), useEffect() etc. 3. If there is a requirement to use browser-only APIs. 4. If you need to implement custom hooks that depend on state, effects, or browser-only APIs. 5. There are React Class components in the pages. Server components: 1. If the component logic is about data fetching. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f6427b-7f4a-4ea0-aa2a-a9eec4be6e13', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Are Go variables passed by reference or by value?', N'Intern', N'Everything in Go is passed by value. When you pass a variable to a function, a copy of that value is made; if you want to modify the original, you must pass a pointer to it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d97552f-cb45-43f9-9c62-a9f0634b02d0', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What role does the ''ExecutionContext'' play in asynchronous programming in Scala?', N'Senior', N'The ExecutionContext acts as a thread pool or scheduler that manages the execution of asynchronous tasks, such as those wrapped in Futures. It decouples the definition of an asynchronous operation from its actual execution strategy, allowing for flexible configuration based on the workload. Improper configuration of the ExecutionContext, such as blocking operations in a global thread pool, is a common cause of performance degradation in Scala applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'447e21c6-ac36-4ccc-8176-a9f13491ee46', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between the Options API and the Composition API?', N'Junior', N'The Options API organizes code by specific objects like data, methods, and computed properties, which is intuitive for beginners. The Composition API organizes code based on logical functionality, making it easier to extract and reuse logic across multiple components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'954cde25-16ce-4f16-b7ff-a9f1be9402f0', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle streaming responses, and when should this be preferred over standard JSON responses?', N'Middle', N'Hono supports streaming via the ReadableStream API, which allows sending data chunks to the client as they become available. This is preferred for long-running processes or large datasets to reduce the Time to First Byte (TTFB) and improve user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
