INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce70a368-4110-44cf-a207-aa09cf01b2ea', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''WeakReference'' and a standard object reference?', N'Senior', N'A weak reference allows an object to be collected by the garbage collector even if the reference is still held. It is used to implement caches or object pools where memory can be reclaimed if pressure is high. A standard reference, by contrast, creates a strong root, preventing the object from being collected as long as the reference exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'935734f7-3e0c-40e3-8051-aa0a129c2026', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the role of an Identity Provider (IdP) in a distributed system architecture?', N'Senior', N'The IdP acts as the single source of truth for user identities, centralizing authentication logic and enabling SSO across multiple applications. It simplifies the security architecture by offloading authentication from individual services and providing a centralized point for MFA, password policies, and identity lifecycle management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1fe45b7-9754-4b87-9926-aa0cf4778c0a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between an ''Expression'' and a ''Func'' in LINQ?', N'Middle', N'A ''Func'' is a delegate that executes code directly, while an ''Expression'' represents the code as an abstract syntax tree. The latter can be analyzed and translated into other formats, which is the primary mechanism that allows LINQ-to-SQL or Entity Framework to convert C# logic into database queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9d8ba1e-d731-4827-87c2-aa0f846c8b55', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the architectural benefit of using Django’s ContentTypes framework, and when should you avoid it?', N'Senior', N'The ContentTypes framework allows for generic relationships, enabling a model to link to any other model in the project. It should be avoided when data integrity is paramount, as it bypasses database-level foreign key constraints, making referential integrity much harder to enforce.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708f76c4-0a5f-4a64-a654-aa151036cab5', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can Hono be used for server-side rendering?', N'Intern', N'Yes, Hono includes a JSX-based engine that allows developers to generate HTML on the server. This enables rendering dynamic web pages directly from the backend framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e519afcc-2046-4557-9493-aa164603f929', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the difference between synchronous and asynchronous communication in microservices.', N'Middle', N'Synchronous communication, like REST or gRPC, requires the caller to wait for a response, creating tight coupling. Asynchronous communication, via message brokers like Kafka or RabbitMQ, decouples services and improves scalability but introduces complexity in tracking request completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd2c30fa-50c2-42fd-826a-aa16718f84af', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''Drop'' trait interact with Rust''s RAII (Resource Acquisition Is Initialization) pattern?', N'Senior', N'The Drop trait defines the destructor for a type, ensuring that resources are automatically cleaned up when an object goes out of scope. This pattern guarantees deterministic resource management, such as closing file handles or releasing memory, without requiring explicit manual cleanup or a garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2cd7da8-afcc-4f5d-8f52-aa199be9093b', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the impact of excessive boxing in a tight loop?', N'Middle', N'Excessive boxing creates many short-lived objects on the heap, which increases the pressure on the garbage collector. This leads to more frequent garbage collection cycles, significantly degrading application performance and responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a01ddb2-3916-42e9-b861-aa1a86fc852e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What reasoning process do you use to prioritize technical debt against new feature development?', N'Middle', N'I evaluate technical debt based on its impact on current development velocity and system stability. If the debt actively blocks or slows down critical features, it takes priority; otherwise, I schedule it as a portion of each sprint to ensure gradual improvements without stalling product delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b1caf19-07e3-47f1-a0f6-aa1cca6523aa', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket utilize Rust''s type system to improve API reliability?', N'Middle', N'Rocket leverages Rust''s strong typing to ensure that route parameters and request data are automatically parsed into the expected types. If the input does not match the defined type, the request is rejected before the handler executes, effectively preventing type-mismatch errors and common runtime crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a98c9a9d-45c1-4ee1-8768-aa1fc1ccea38', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the advantages of using Spring Data JPA over native SQL?', N'Middle', N'Spring Data JPA provides an abstraction layer that reduces boilerplate code by automating repository implementation and query generation. It enhances maintainability by allowing developers to work with object-oriented paradigms rather than raw SQL, while still providing hooks to execute custom queries when necessary for performance optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efdfb7e0-e744-4ccf-9243-aa22b971879b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Describe the trade-offs of using the REPEATABLE READ isolation level versus READ COMMITTED in MySQL.', N'Senior', N'REPEATABLE READ uses gap locking to prevent phantom reads, which increases the likelihood of deadlocks under high concurrency. READ COMMITTED offers better concurrency by avoiding gap locks but requires application-level handling for phantom reads and relies on statement-based binlog restrictions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6174f801-2d94-40fd-b5fd-aa287fa320fd', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do you handle error boundaries in SolidJS?', N'Middle', N'SolidJS provides an ''ErrorBoundary'' component that catches errors thrown in the subtree of its children. This allows you to display a fallback UI for specific parts of the application without crashing the entire page, improving overall app resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51a9a5f0-3020-4934-a250-aa2acd9c5bf4', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary goal of the Consistency property in ACID?', N'Junior', N'Consistency ensures that a transaction brings the database from one valid state to another, maintaining all predefined rules and constraints. It prevents the database from entering an invalid or corrupted state due to partial updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f2ffae3-1e84-4f6f-9070-aa2cfcd8b11c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the BeanPostProcessor interface in the Spring lifecycle?', N'Senior', N'A BeanPostProcessor allows for custom logic to be executed before or after the initialization of any bean. It is a powerful extension point used by frameworks to provide features like proxy creation for AOP or processing custom annotations like @Autowired.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d5019b0-187f-4d5a-bddf-aa2d04d4387d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of Qwik''s ''progressive hydration'' vs. traditional approaches?', N'Senior', N'Traditional hydration is an all-or-nothing process that blocks the main thread. Qwik''s approach is truly progressive, loading only the necessary parts of the component when an interaction occurs, which prevents long-task blocking and improves overall responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
