INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32a1afb9-add7-4a9d-9dc6-aa47f4ff4aa3', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s reactivity system work under the hood?', N'Middle', N'Vue uses JavaScript proxies to intercept property access and mutation. When data is accessed, the system tracks dependencies; when data is modified, it triggers a notification to re-render the components that depend on that specific data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0b27812-2b64-4b28-97d7-aa4dfb5ac79c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is a stateful component?', N'Intern', N'Modernization Audit (2026 Standards) The original content relies on Class Components (React.Component), which are legacy patterns. In React 19, the industry standard for state management is the Hooks API. While class components remain supported for backward compatibility, they are deprecated in modern architectural paradigms. Definition Stateful components in React are components that manage internal data that persists across renders. In modern React, this is achieved using the useState or useReducer hooks. When state values update, React triggers a re-render of the component to synchronize the DOM with the new state. When to Use * Dynamic Interactions: Components requiring real-time updates (e.g., counters, toggles). * User Input Handling: Managing controlled components in forms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'412a1e5d-1fec-427c-87f7-aa4e17a37212', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between props and attributes in Vue?', N'Middle', N'Props are custom properties defined in a component''s interface used to pass data down from a parent to a child. Attributes are standard HTML attributes that fall through to the component''s root element if they are not explicitly declared as props.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7957b8a5-a176-498f-bf60-aa4eba0e445b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your work meets the quality standards of your team?', N'Intern', N'I strictly adhere to team guidelines, style guides, and design patterns established for the project. I actively seek feedback through peer reviews to ensure my work is consistent with the team''s expectations. I also perform thorough self-verification against the project requirements before submitting my work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
