INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4db88f27-a344-40dc-8a08-aa5413efc80c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is OTP in the context of Phoenix?', N'Intern', N'OTP stands for Open Telecom Platform. It is a set of libraries and design principles for building distributed, fault-tolerant applications that Phoenix leverages for its reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
