INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91ed1e98-e9db-47fa-b092-aa574b8d298b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''connection pool'' in Rails, and how should it be tuned?', N'Senior', N'The connection pool limits the number of concurrent database connections a process can open, preventing the database from being overwhelmed. It should be tuned based on the number of threads per process and the expected concurrency level of the application to avoid connection timeout errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6d4153f-ef96-4aa2-a876-aa58203034e4', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''cluster'' module, and how does it improve application performance?', N'Middle', N'The cluster module allows you to create child processes that share the same server port to utilize multi-core systems. By distributing incoming connections across multiple instances, it overcomes the single-thread limitation of Node.js and increases the total request-handling capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f328d516-0dae-4459-abe5-aa58d0cf4c61', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why are identifier names with a leading underscore disparaged?', N'Fresher', N'Since Python does not have a concept of private variables, it is a convention to use leading underscores to declare a variable private. This is why we mustn''t do that to variables we do not want to make private.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
