INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dfcc1c5-1f49-4536-9cf9-aa806df12e4d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between @Injectable and a standard class?', N'Junior', N'@Injectable is a decorator that marks a class as a provider that can be managed by the NestJS IoC container. Without this decorator, the framework cannot perform dependency injection for that specific class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'898bcc4f-587e-404a-805e-aa8a1bb1f7ec', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between Classic Inheritance and Prototypical Inheritance?', N'Fresher', N'1. Class Inheritance: Instances inherit from classes (like a blueprint — a description of the class), and create sub-class relationships: hierarchical class taxonomies. Instances are typically instantiated via constructor functions with the new keyword. Class inheritance may or may not use the class keyword from ES6. 2. Prototypal Inheritance: Instances inherit directly from other objects. Instances are typically instantiated via factory functions or Object.create(). Instances may be composed from many different objects, allowing for easy selective inheritance. Features * Classes: create tight coupling or hierarchies/taxonomies. * Prototypes: mentions of concatenative inheritance, prototype delegation, functional inheritance, object composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55e7198d-33a3-4d5a-bd1d-aa8a8823b0b9', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Client-Side Hydration?', N'Junior', N'Hydration is the process where the browser takes the static HTML generated by the server and attaches JavaScript event listeners to it. This makes the page interactive and converts it into a fully functional single-page application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af8d41f4-9a68-449c-bc50-aa8ef7a35f24', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the advantages of using a NoSQL database for scaling?', N'Middle', N'NoSQL databases are often designed with horizontal scaling in mind, using flexible schemas and built-in partitioning features. They typically sacrifice strict ACID compliance in favor of higher availability and partition tolerance, making them easier to scale globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90f2c08e-0032-448c-83a2-aa9056de016b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s ''defer'' statement work, and in what scenarios is it most useful?', N'Middle', N'The defer statement executes its block of code immediately before the current scope is exited, regardless of how the exit occurs. It is most useful for cleanup tasks like closing file handles or invalidating timers, ensuring resources are released even if an error is thrown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1249c3db-a65f-4d82-91cf-aa924f012613', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis suitable for long-term data storage?', N'Intern', N'While Redis can store data, it is generally intended as a cache or transient data store. For critical long-term storage, a traditional database is usually preferred because Redis is constrained by the physical RAM available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db276420-4168-46d4-8e69-aa933cf5fb55', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of the ''mode'' configuration property in Webpack?', N'Middle', N'The mode property tells Webpack which built-in optimizations to apply based on the environment. Setting it to ''production'' enables optimizations like minification and tree shaking, while ''development'' prioritizes build speed and helpful debugging information like source maps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a1c4c3d-1e94-4c59-bae8-aa97eed39f50', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it generally recommended to avoid putting complex business logic in Rails models?', N'Middle', N'Placing complex business logic in models often leads to the ''Fat Model'' anti-pattern, making the code harder to read, debug, and test. By extracting this logic into Service Objects or Domain Models, you improve separation of concerns and make the codebase easier to maintain as requirements evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a173d16d-fede-4521-bae2-aa9912dd1ef9', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does the ''Astro.glob'' function facilitate dynamic page generation?', N'Senior', N'Astro.glob allows developers to import multiple files matching a pattern, enabling the creation of dynamic routes from content files like Markdown or JSON. This pattern is fundamental for building blog indexes, tag pages, and documentation sites where the file system structure defines the routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b5c7eef-0445-48cb-a64e-aa993fa952aa', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is ''strongly consistent'' read in DynamoDB?', N'Intern', N'A strongly consistent read returns a response with the most up-to-date data, reflecting all successful prior write operations. This type of read consumes more read capacity units than an eventually consistent read.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3b55a52-f626-40ce-a70e-aa9af485a925', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you trim a string in javascript?', N'Fresher', N'The trim() method removes whitespace from both sides of a string. JavaScript provides 3 simple functions on how to trim strings. 1. string.trim(): The string.trim() removes sequences of whitespaces and line terminators from both the start and the end of the string. 2. string.trimStart(): The string.trimStart() removes sequences of whitespaces and line terminators only from the start of the string. 3. string.trimEnd(): The string.trimEnd() removes sequences of whitespaces and line terminators only from the end of the string. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2212ef2f-60da-49d8-aa04-aa9ba18dbe70', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a situation where you don''t understand the error message?', N'Junior', N'I would search for the error message in internal documentation and external resources to see if others have encountered it. If that fails, I would look at the surrounding code to understand what operation was being performed when the error was triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc9fd04-4a94-475d-aa7a-aa9cf6814e0b', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the form element?', N'Junior', N'The form element acts as a container for different types of input elements, such as text fields, checkboxes, and buttons. It collects user input and allows it to be sent to a server for processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac1705e9-e210-4dec-9df8-aa9f12e74b3b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between a Route Handler and a Controller?', N'Fresher', N'A route handler is a specific function decorated to handle a single HTTP request, while a controller is a class that acts as a container for multiple route handlers. Controllers allow for better code organization and shared configuration across multiple endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b731c1f-cb93-4b7d-82fa-aaa144370534', N'954a0331-deff-4399-b588-96f39fec001d', N'What is TypeScript?', N'Intern', N'TypeScript is a strongly typed superset of JavaScript created by Microsoft that adds optional types, classes, async/await and many other features, and compiles to plain JavaScript. Angular is written entirely in TypeScript as a primary language. You can install TypeScript globally as Let''s see a simple example of TypeScript usage:- The greeter method allows only string type as argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fda07a4-a4cf-4f57-8b36-aaa24fca87d5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''when'' expression in Kotlin?', N'Fresher', N'The ''when'' expression is a powerful replacement for the traditional switch statement. It can return values, check ranges, and handle complex conditions, making conditional logic more readable and expressive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33f2fbab-415c-4add-99bf-aaa29236321c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an environment record?', N'Intern', N'According to ECMAScript specification 262 (9.1): > Environment Record is a specification type used to define the association of Identifiers to specific variables and functions, based upon the lexical nesting structure of ECMAScript code. Usually an Environment Record is associated with some specific syntactic structure of ECMAScript code such as a FunctionDeclaration, a BlockStatement, or a Catch clause of a TryStatement. Each time such code is evaluated, a new Environment Record is created to record the identifier bindings that are created by that code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8ea8eaa-56fc-4890-b119-aaa48a89ab9b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the summary function in R?', N'Fresher', N'The summary function provides a quick statistical overview of an object, such as a data frame or a vector. It typically outputs values like the minimum, maximum, mean, median, and quartiles, making it essential for initial data exploration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c201ffdd-b093-40c4-a90b-aaa6710bdc4c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is MicroProfile in relation to Quarkus?', N'Intern', N'MicroProfile is a set of specifications designed to optimize enterprise Java for microservices architectures. Quarkus implements many of these specifications, such as Health, Metrics, and Fault Tolerance, to ensure standardized cloud-native development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
