INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ffb0548-b2d3-4fe8-931e-aaafba09aa8c', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Laravel and what is its primary design pattern?', N'Fresher', N'Laravel is an open-source PHP framework designed for web application development. It follows the Model-View-Controller (MVC) architectural pattern, which helps in separating the business logic from the user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'700cd989-e797-4a97-b1b2-aab04b358e7d', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of encapsulation.', N'Fresher', N'Encapsulation is the practice of bundling data and the methods that operate on that data into a single unit, usually a class. It restricts direct access to some of an object''s components, which prevents unintended interference and misuse of internal data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
