INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1460529b-90f8-49b5-82db-aaee345a75c4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What happens when you perform an operation on two vectors of unequal length in R?', N'Junior', N'R uses a process called recycling. If the shorter vector is shorter than the longer one, R will repeat the elements of the shorter vector until it matches the length of the longer one, often issuing a warning if the lengths are not exact multiples.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f0a9ed-c8c6-4b90-b1d5-aaf1bef3d479', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the $lib folder?', N'Intern', N'The $lib folder is a central place to store reusable components, utility functions, and shared logic. It is easily importable throughout the project using the alias $lib.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3fa8614-03d2-4aec-b228-aaf336e9a43d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating, how do you decide between a ''buy versus build'' approach?', N'Middle', N'I evaluate the cost of development, maintenance, and long-term integration against the cost of licensing a third-party solution. I estimate the effort for both paths, including the hidden cost of technical debt and vendor lock-in for the buy option.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00070811-0641-4ac9-935f-aaf3a5fa7480', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the trade-offs of using Ember Data’s ''Identity Map'' pattern in a large-scale application.', N'Senior', N'The Identity Map ensures that requesting the same record multiple times returns the same object instance, maintaining data consistency and preventing redundant network requests. However, this can lead to memory pressure in long-running sessions, requiring careful management of the store''s cache and record unloading strategies to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe3e978e-4050-42d5-a192-aaf49060555e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the significance of the circuit breaker pattern in Elasticsearch.', N'Senior', N'The circuit breaker is a safety mechanism that monitors memory usage and prevents operations—such as large aggregations or heavy queries—from causing an OutOfMemoryError. If a request would exceed defined heap limits, the system rejects it and returns an error, protecting the stability of the entire node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5852941-be8f-4d1b-be60-aaf59f4ab1f6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Next.js and how does it differ from React?', N'Fresher', N'Next.js is a React framework that provides structure, features, and optimizations for building web applications. While React is a library focused on building user interfaces, Next.js adds essential features like server-side rendering, routing, and static site generation out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2f29a4a-f3a6-483d-ac8e-aaf6997200dd', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the echo statement in PHP?', N'Intern', N'The echo statement is used to output strings or variables to the browser or standard output. It is the most common way to display content generated by PHP within an HTML page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b21661da-3449-4088-8bea-aafa124fb648', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does memory management work in Swift?', N'Junior', N'Swift uses Automatic Reference Counting (ARC) to manage memory usage. ARC automatically tracks the number of references to class instances and deallocates the memory when the reference count drops to zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'784d604d-82c8-4505-b18f-aafb091d174d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the significance of the ''Service'' trait in Actix-web.', N'Middle', N'The Service trait is the core abstraction for processing requests and producing responses. It provides a unified interface for middleware, routers, and handlers, allowing the framework to compose these components into a single request-handling pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68ef80e2-0853-4429-af9e-aafe9fab6d53', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Compare AdonisJS ''Events'' with ''BullMQ'' for background tasks.', N'Senior', N'Adonis events are ideal for internal application notifications and lightweight tasks that must happen within the same process. BullMQ is necessary for complex background jobs that require retry strategies, prioritization, and persistent monitoring across service restarts, acting as a robust queue manager outside the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8482160e-8761-4296-b8b9-ab0386b4e733', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is a custom element?', N'Intern', N'A custom element is a standard web feature that allows developers to define their own HTML tags. Lit provides a straightforward way to register these tags with the browser so they can be used just like native elements like div or span.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70cd5392-d51a-4abe-a947-ab050ae72cbd', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why is the ''inline'' keyword often ineffective for functions with complex logic or deep recursion?', N'Senior', N'Inlining complex or recursive functions causes an exponential increase in the generated bytecode because the function body is duplicated at every call site. This not only consumes more memory and impacts instruction cache performance but can also lead to compilation limits or stack overflow issues during the inlining process itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a3fc602-0d3a-48c1-90ca-ab0920098fc5', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach API versioning when you need to introduce breaking changes to a public-facing service?', N'Senior', N'I follow a deprecation policy that involves running parallel versions of the API for a defined period while notifying consumers. I use header-based or URI-based versioning to route requests appropriately, allowing clients to migrate at their own pace without experiencing service disruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21cf3ca9-cbf8-4038-81d4-ab0ead8a5c22', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the benefit of using Form Requests over validating inside the Controller?', N'Middle', N'Form Requests move validation logic into dedicated classes, keeping your controllers slim and adhering to the Single Responsibility Principle. This makes validation logic reusable and keeps the HTTP layer focused on handling requests rather than processing data rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'933fd9ca-d37c-4d5b-9fc7-ab11242ebd6d', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the importance of secure secret management in cloud environments.', N'Middle', N'Secrets like API keys and database passwords should never be hardcoded or stored in version control systems. Using a dedicated secret management service allows for encrypted storage, automated rotation, and granular access control for sensitive credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
