INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bc4b8c3-a418-4c01-bd2f-ab1588c19ff4', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle routing compared to standard Vue.js?', N'Fresher', N'In standard Vue.js, you must manually define route objects and map them to components in a separate configuration file. Nuxt uses a file-system-based router where the structure of the pages directory directly determines the application''s URL structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed2fa53b-c372-49a1-ae60-ab17b74dcec9', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact support JSX?', N'Intern', N'Yes, Preact supports JSX, which is a syntax extension that allows you to write HTML-like structures within JavaScript. Preact uses a transpiler to convert this JSX into function calls that build the virtual tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb99a248-1d18-4334-94ab-ab1973dfd311', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you localize React applications?', N'Fresher', N'To localize a React application, you typically use a library like react-i18next or react-intl. First, you set up your translation files for different languages. Then, you configure the localization library in your React app. Finally, you use the provided hooks or components to display localized text in your components. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbca75f1-9737-403a-a1db-ab1cb0ec4f91', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Describe the role of the WSGI/ASGI interface in Django’s deployment architecture.', N'Senior', N'WSGI provides a standard interface for synchronous Python applications to communicate with web servers, while ASGI extends this to support asynchronous, long-lived connections like WebSockets. These interfaces decouple the Django application from the underlying server, allowing developers to switch between various high-performance web servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd4e4186-80ea-499f-a409-ab1cedda08e1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the function of the ''tsconfig.json'' file, and why is it critical for a project?', N'Middle', N'The tsconfig.json file defines the compiler options and the scope of files to be included in the build process. It is critical because it enforces project-wide rules, such as strict null checks or target ECMAScript versions, ensuring consistency across the development team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c18c00eb-ca40-4b17-bba4-ab2077c4ba9e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the difference between ''unknown'' and ''any'' in TypeScript.', N'Middle', N'While ''any'' allows almost any operation without type checking, ''unknown'' is the type-safe counterpart that requires the developer to perform type narrowing before interacting with the value. ''unknown'' forces explicit validation, significantly reducing the risk of runtime errors compared to ''any''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f86310c-4bff-4ceb-b247-ab20961f5630', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit optimize template rendering compared to traditional innerHTML manipulation?', N'Senior', N'Lit uses tagged template literals to parse static and dynamic parts of a template once, creating a template cache. During updates, it only modifies the dynamic ''parts'' of the DOM, avoiding the overhead of re-parsing or destroying and recreating DOM nodes, which is significantly faster than innerHTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cfe7ac6-5edb-4189-a4ec-ab2143123753', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to document engineering decisions?', N'Intern', N'Documentation preserves the reasoning behind specific design choices, which is essential for future team members to understand the system. It helps prevent repeating past mistakes and ensures consistency as the project evolves over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8deef998-3ba2-478a-b879-ab21e7032441', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is a microservice and how does it differ from a monolithic architecture?', N'Senior', N'Microservices and monolithic architecture are two distinct software design paradigms, each with its unique traits. A monolithic architecture consolidates all software components into a single program, whereas a microservices architecture divides the application into separate, self-contained services. Microservices offer several advantages but also have their own challenges, requiring careful consideration in the software design process. Key Differences - Decomposition: Monolithic applications are not easily separable, housing all functionality in a single codebase. Microservices are modular, each responsible for a specific set of tasks. - Deployment Unit: The entire monolithic application is packaged and deployed as a single unit. In contrast, microservices are deployed individually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f845f949-4fbd-4fbf-89b4-ab257ef8d6a6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS security package prevent common web vulnerabilities like CSRF and XSS?', N'Senior', N'AdonisJS includes built-in middleware for CSRF protection and automatic output escaping in its template engine, which mitigates the most common injection attacks. These protections are enforced at the framework level, ensuring a secure-by-default environment for all developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cc7167d-d758-477b-a32d-ab2d1d606bec', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle asynchronous execution compared to synchronous frameworks?', N'Middle', N'Rocket is built on top of the Tokio asynchronous runtime, allowing it to handle many concurrent requests efficiently without blocking threads. This architecture is crucial for I/O-bound tasks, such as database queries or external API calls, significantly increasing the throughput of the backend service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5987e239-577d-4ffe-9e6f-ab3111d90060', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails handle multi-tenancy and what are the common approaches?', N'Middle', N'Rails handles multi-tenancy either through a shared database approach using a ''tenant_id'' column on all tables, or by using separate databases or schemas per tenant. The shared database approach is easier to maintain but requires strict query filtering, while separate schemas offer better data isolation at the cost of significantly higher infrastructure complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3bc32a-e13b-4578-94cb-ab34f705d263', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When choosing a messaging protocol (e.g., Kafka vs. RabbitMQ), what are the key trade-offs?', N'Senior', N'I choose Kafka for high-throughput, log-based persistence where historical data replay is necessary for downstream consumers. I choose RabbitMQ for complex routing logic, lower-latency message delivery, and scenarios where immediate acknowledgment and worker-queue semantics are more important than large-scale data stream processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ff267d1-2de9-43a1-b4ee-ab37a0b84f9f', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between vertical and horizontal scaling, and when would you choose one over the other?', N'Middle', N'Vertical scaling involves increasing the resources of a single server, such as CPU or RAM, while horizontal scaling involves adding more servers to the system. Horizontal scaling is generally preferred for distributed systems because it avoids single points of failure and allows for virtually infinite capacity, whereas vertical scaling is limited by the maximum hardware capacity of a single machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0eb0075d-9cd7-4a96-b867-ab3a3741804f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between a class and an object in Kotlin?', N'Intern', N'A class acts as a blueprint for creating objects, defining the properties and behaviors that instances will have. An object is a specific implementation of a class, or in the case of Kotlin''s ''object'' keyword, a way to define a singleton instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6769ec6-f1e9-4dc4-9c7c-ab3aef37f028', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is ''strict mode'' important in TypeScript projects?', N'Middle', N'Strict mode enables a suite of compiler checks, such as ''noImplicitAny'' and ''strictNullChecks'', that significantly improve type safety. It prevents common bugs like null pointer exceptions and ensures a more consistent and predictable codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbab9cac-0321-4ff2-bc34-ab3e677ef54e', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between ''async'' and ''async*''?', N'Junior', N'The ''async'' keyword is used to define a function that returns a single Future value. The ''async*'' keyword is used to define a function that returns a Stream, which emits multiple values over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b8e9f73-8a8c-4d20-893d-ab40a0a2eee6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the role of the Rails middleware stack and how you would insert custom logic for global request handling.', N'Senior', N'The middleware stack processes incoming HTTP requests before they reach the ActionDispatch router. You can insert custom middleware in the application configuration to handle cross-cutting concerns like custom logging, authentication headers, or request shaping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab3e65c0-b275-4211-98ed-ab4111542638', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Startup class?', N'Intern', N'The Startup class is used to configure the application''s request pipeline and register services in the dependency injection container. While modern versions use a simplified program configuration, its core purpose remains defining how the application handles requests and interacts with external components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7747dca5-d60c-4dbb-a5cb-ab415d48415c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a promise', N'Intern', N'A Promise is a JavaScript object that represents the eventual completion (or failure) of an asynchronous operation and its resulting value. It acts as a placeholder for a value that may not be available yet but will be resolved in the future. A Promise can be in one of three states: - pending: Initial state, neither fulfilled nor rejected. - fulfilled: The operation completed successfully. - rejected: The operation failed (e.g., due to a network error). Promise Syntax Example: Creating and Using a Promise In the above example: * A Promise is created to handle an asynchronous operation with resolve and reject callbacks. * The setTimeout resolves the promise with a value after 5 seconds. * .then(), .catch(), and .finally() are used to handle success, errors, and cleanup respectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b600dcd-2850-43e8-a6a9-ab421902f5ac', N'075b8862-431c-4678-9767-f55359758a4a', N'Why do we use ''v-bind''?', N'Junior', N'v-bind is used to dynamically bind one or more attributes to an element, such as linking a data property to an image source or a CSS class. It ensures that whenever the underlying data changes, the attribute value in the DOM updates automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21dc31e2-0986-489c-977d-ab453de66ddf', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React? Describe the benefits of React', N'Intern', N'React is a JavaScript library created by Facebook for building user interfaces, primarily for single-page applications. It allows developers to create reusable components that manage their own state. Key benefits of React include a component-based architecture for modular code, the virtual DOM for efficient updates, a declarative UI for more readable code, one-way data binding for predictable data flow, and a strong community and ecosystem with abundant resources and tools. Key characteristics of React: - Declarative: You describe the desired state of your UI based on data, and React handles updating the actual DOM efficiently. - Component-based: Build reusable and modular UI elements (components) that manage their own state and logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba795fa0-f07f-4900-a1dd-ab46ccc94b03', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Try'' type?', N'Junior', N'The ''Try'' type is a container used for exception handling, representing a computation that might either succeed (''Success'') or fail (''Failure''). It is preferred over traditional try-catch blocks because it allows for functional composition of error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed713f8b-b1a9-4515-bc64-ab47d30d1f4c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle large request bodies compared to a standard Go server?', N'Senior', N'Fiber allows for configurable limits on request body sizes to prevent memory overflow attacks. By streaming or limiting the buffer size, it ensures that an attacker cannot crash the server simply by sending an extremely large payload that exceeds available RAM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90d30f23-6fef-4464-bceb-ab4888edf3b1', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the continue statement?', N'Fresher', N'The continue statement skips the current iteration of a loop and moves to the next iteration. It does not terminate the loop but rather ignores the remaining code inside the current loop block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eecd7579-d089-4544-9428-ab494b443728', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a ''type assertion'' in TypeScript?', N'Intern', N'A type assertion is a way to tell the compiler to treat a value as a specific type, overriding the compiler''s inferred type. It is essentially a way for the developer to say they know more about the value''s type than the compiler does.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccbf0ede-a9c7-4da1-88cf-ab49af3d1860', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''implicit interface'' feature of Dart impact class design?', N'Middle', N'In Dart, every class implicitly defines an interface containing all its public members. This allows any class to be implemented by another class using the ''implements'' keyword, decoupling the definition of an interface from its implementation and favoring composition over strict inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c6b9365-5387-4fe4-9ac1-ab4adbd960f9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the advantage of using a reverse proxy like Nginx in front of a Node.js application?', N'Middle', N'A reverse proxy handles tasks like SSL termination, static file serving, load balancing, and request rate limiting. This offloads resource-heavy tasks from the Node.js application, allowing it to focus solely on executing business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5efcedac-ecfc-48fb-b4e2-ab4cded04650', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What does the @import directive do in Sass?', N'Junior', N'The @import directive allows you to include content from one Sass file into another. This enables developers to split large stylesheets into smaller, manageable partials that are bundled into a single file during compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2afe8cfb-7f81-4bb0-b6a9-ab4cf06afbbb', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS manage state that must be shared across disparate components?', N'Senior', N'State can be managed via context providers or by defining signals in a higher-level scope or external module. Because signals are just functions, they can be passed as props or imported directly without needing a complex state container library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e97aa2fe-5488-41e6-bb6b-ab4f63d12056', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the main advantage of using an enumeration (enum)?', N'Junior', N'An enum allows you to define a set of named integer constants, which makes code much more readable and maintainable. Instead of using arbitrary magic numbers throughout the code, you can use descriptive names. This reduces errors and makes the code''s intent clearer to other developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4846d33b-2872-45ab-b527-ab517d97de34', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart handle null safety, and why is it important?', N'Fresher', N'Dart''s null safety feature ensures that variables cannot hold a null value unless explicitly declared as nullable. This prevents common runtime errors caused by unexpected null references, leading to more stable and reliable applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bf2ad40-e9dc-4227-a71a-ab55ac994ce0', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between HTTP GET and POST requests?', N'Intern', N'GET requests are used to retrieve data from a server and should not change the state of the server. POST requests are used to send data to the server to create or update a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4a0ccdf-3adf-4cde-bd71-ab58264fb0f7', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does the ''pull-based'' model differ from a ''push-based'' model in message broker architecture, and when would you choose one over the other?', N'Senior', N'In a pull-based model, consumers request messages at their own pace, which inherently provides flow control and prevents consumer overload. Push-based models provide lower latency as messages are delivered immediately upon arrival, but they require robust backpressure mechanisms to prevent overwhelming slow consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f80107df-d995-414c-a39c-ab5a946925d8', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the use case for ''Lifecycle Events'' like ''onModuleInit''?', N'Middle', N'Lifecycle hooks allow you to execute custom logic at specific stages of the application lifecycle, such as initializing connections or performing health checks. This ensures that essential setup tasks are completed before the application starts accepting traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75370b7b-c3a6-4ea0-a1b1-ab5c3d7180f8', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between static and dynamic linking?', N'Middle', N'Static linking embeds the entire library code into the executable during the compilation process, resulting in a single, self-contained binary file. Dynamic linking loads the library into memory at runtime, allowing multiple programs to share the same library instance, which saves disk space and memory but requires the library to be present on the target system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b99ca63b-1572-4550-81a7-ab5ccd046d17', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Describe the difference between the AdonisJS ''Ace'' CLI and standard npm scripts.', N'Middle', N'Ace is a full-featured command-line interface that integrates deeply with the framework''s internal components, allowing for scaffolding, database migrations, and custom application tasks. Unlike npm scripts, Ace commands have access to the application''s IoC container, making them powerful tools for maintenance, data seeding, and administrative operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a180ec2e-40b0-44ff-8edf-ab5cd4657fe8', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do you mitigate the ''thundering herd'' problem when a cache key expires in a high-traffic distributed system?', N'Senior', N'Implement cache locking or ''probabilistic early expiration'' to ensure only one process regenerates the data while others continue serving stale content. Alternatively, use a mutex or semaphore pattern to force sequential access to the backend source during the regeneration phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c00c936-c407-419d-8049-ab5d21ddb797', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Compare the performance implications of R''s functional programming paradigm versus imperative approaches.', N'Senior', N'R''s preference for functional constructs like map and apply reduces the need for explicit loops, which are notoriously slow in the interpreter due to overhead. While functional programming promotes cleaner, more modular code, it often relies on internal C-compiled loops that significantly outperform manual iterative constructs in the R language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
