INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5a92b8f-98fd-412b-8e6a-ab5e59e8a8df', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are static files in a Flask application?', N'Fresher', N'Static files are assets like CSS, JavaScript, and images that do not change based on user input. Flask serves these files from a dedicated folder named ''static'' and makes them accessible to the browser via a specific URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29270247-0358-4671-b616-ab5e6acce585', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the trade-offs between using ActiveRecord callbacks versus service objects for business logic.', N'Senior', N'ActiveRecord callbacks can lead to bloated models, hidden side effects, and difficulty in testing isolated logic. Service objects promote the Single Responsibility Principle by encapsulating complex workflows, making the codebase more modular and easier to maintain as business requirements evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f79f2377-5caa-413d-a7ca-ab5effd9cf3c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the ''assets'' directory?', N'Junior', N'The assets directory contains the source files for frontend assets like CSS, JavaScript, and images. These are processed by the build pipeline to generate the static files that the browser eventually consumes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2fbaf53-2fa1-4c21-b0e1-ab5ff0d0d316', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is it recommended to use a reverse proxy with ASP.NET Core?', N'Middle', N'A reverse proxy provides an additional layer of security, handles SSL termination, and offers better load balancing capabilities. It also protects the application from direct exposure to the public internet and manages static file caching more efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a26153a-2b79-4d17-873a-ab5ff608a0d0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you select the parent of an element in jQuery?', N'Junior', N'You can use the .parent() method to select the immediate parent of the matched element. There are also related methods like .parents() and .closest() which allow you to traverse further up the DOM tree to find ancestors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a7217a9-7b83-4342-ab6c-ab60f87f0284', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why might you use Echo''s ''Subrouter'' or ''Group'' for versioning your API?', N'Middle', N'Versioning via groups allows you to maintain different API schemas side-by-side, such as /v1 and /v2, while sharing common middleware. This makes it easier to deprecate older versions while developing new features without duplicating the entire routing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f72e0c8-9751-4791-b723-ab6322447c84', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the limitations of B-Tree indexes for specific data types?', N'Senior', N'B-Tree indexes are optimized for range and equality queries on ordered data, but perform poorly for high-cardinality searches like full-text matching or multi-dimensional spatial data. For these, specialized structures like inverted indexes or R-trees are required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3096cbb7-2a07-4526-8ad9-ab633ce1ac91', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between an index and a type?', N'Intern', N'An index is a collection of documents with similar characteristics, while types were historical ways to group documents within an index. In modern versions of Elasticsearch, the concept of types has been deprecated in favor of a single document type per index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cb4590c-08ce-49eb-a4d8-ab640aee3e34', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain how AdonisJS handles exception reporting and formatting.', N'Middle', N'AdonisJS utilizes a centralized Exception Handler that catches all application errors and allows for standardized formatting of responses. This ensures that the API consistently returns meaningful error messages and correct HTTP status codes, regardless of where the exception was thrown in the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a419b56f-3a24-4d24-9606-ab66d476d601', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the ''Json'' extractor?', N'Intern', N'The Json extractor is a specialized tool that parses the incoming request body as JSON. It automatically validates that the body content matches the expected structure, returning an error if the parsing fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bedce205-f986-4114-a995-ab6729f38e9d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is database clustering in PostgreSQL?', N'Intern', N'Clustering is the process of physically reordering the data in a table to match the order of an index. This can speed up sequential scans and range queries by keeping related data physically closer together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e05387c-498c-4a2a-bf95-ab6982889863', N'954a0331-deff-4399-b588-96f39fec001d', N'What is change detection in Angular and how does it work?', N'Intern', N'Change detection in Angular is the mechanism that synchronizes the application''s data model with the user interface (DOM). Angular needs this because JavaScript is dynamic, and it doesn''t automatically know when data bound to the view has changed. By default, Angular uses Zone.js to detect asynchronous operations like browser events (clicks, input), timers (setTimeout), and HTTP requests. When one of these operations completes, Zone.js notifies Angular, triggering a change detection cycle. During a cycle, Angular traverses the component tree from top to bottom. For each component, it checks if the values of any template expressions (like {{ data }} or [property]="data") have changed since the last check. If a change is detected, Angular updates the corresponding part of the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25d9244-97a6-41e5-9a39-ab6b1fe79fd3', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle session management in a stateless API?', N'Middle', N'In a stateless API, AdonisJS typically uses JWT or signed tokens stored in request headers rather than server-side sessions. If state is required, developers often use Redis-backed stores to maintain consistency across multiple horizontally scaled server instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e225de-5c3b-4425-9d6d-ab6d8855ed19', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is minification important for production bundles?', N'Junior', N'Minification reduces the file size of your JavaScript and CSS by removing unnecessary characters like whitespace, comments, and shortening variable names. Smaller files mean faster download times for the user, which directly improves website performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0d8a59f-0f54-4a73-a818-ab6ed456c425', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you mitigate cascading failures in a microservices ecosystem?', N'Senior', N'Implement circuit breakers to prevent a failing service from consuming resources indefinitely, and use bulkheads to isolate service pools so failures are contained. Additionally, ensure proper timeouts and retries with exponential backoff and jitter are configured to protect downstream dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99395b58-4045-4e53-acd8-ab708e219dca', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Can you run Actix-web without the actor system?', N'Fresher', N'Yes, modern versions of Actix-web are decoupled from the actor system. While the framework originated from it, you can build web services using standard async/await patterns without explicitly managing actors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'788f874e-bd24-4621-b56b-ab71e4bfb1a0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize the loading of event listeners?', N'Junior', N'Instead of attaching event listeners to all elements during hydration, Qwik uses global event delegation. Listeners are only downloaded and executed when the user actually interacts with an element, meaning no JavaScript is loaded for events that never occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee9973bf-6953-4ab4-abcd-ab725d607750', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are state and props in React?', N'Intern', N'Data Management in React (2026 Standards) In modern React (v19+), props and state remain the fundamental primitives for data propagation and UI synchronization. React''s architecture follows a unidirectional data flow where data typically moves from parent to child via props, while state remains localized to the component or lifted to shared ancestors. Role & Lifecycle * Props (Properties): Immutable data objects passed from a parent component to a child. They serve as the component’s configuration. A component must be pure with respect to its props; it should never modify its own props, as they are managed by the parent. * State: Local, mutable data storage within a component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b73ac085-02ec-4acf-9780-ab728ccd993a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the ''Job'' or ''Scheduled'' feature in Micronaut?', N'Junior', N'The scheduling feature allows developers to execute tasks at fixed intervals or based on cron expressions. It is integrated directly into the framework, enabling background processing without needing external libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495e832a-65ad-4a28-99fd-ab72ed9e2a7e', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle routing?', N'Intern', N'Next.js uses a file-system-based router where the folder structure of the application determines the routes. Each folder corresponds to a URL path, and specific files like page.js are used to define the content of those routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'384c2f09-caad-4a1f-b96c-ab76741be6d3', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the performance implications of deep nesting in Sass and how it affects the CSSOM.', N'Senior', N'Deep nesting results in overly specific CSS selectors that increase the complexity of the browser''s style calculation engine. It also makes overrides difficult, leading to the proliferation of !important flags and hindering the browser''s ability to efficiently match selectors during rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'521248ad-1cf0-4c15-b208-ab79821b3cac', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the main benefit of denormalization?', N'Intern', N'Denormalization is the process of adding redundant data to a database to optimize read performance. By reducing the number of joins required to retrieve data, it can significantly speed up complex queries, though it increases the risk of data inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0a0cd95-9d0c-4d3c-aaaa-ab79a920bc66', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to build a microservices architecture with Node.js?', N'Senior', N'Microservices are a style of Service Oriented Architecture (SOA) where the app is structured on an assembly of interconnected services. With microservices, the application architecture is built with lightweight protocols. The services are finely seeded in the architecture. Microservices disintegrate the app into smaller services and enable improved modularity. There are few things worth emphasizing about the superiority of microservices, and distributed systems generally, over monolithic architecture: * Modularity — responsibility for specific operations is assigned to separate pieces of the application * Uniformity — microservices interfaces (API endpoints) consist of a base URI identifying a data object and standard HTTP methods (GET, POST, PUT, PATCH and DELETE) used to manipulate the o...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f389cf8d-8fca-4f1b-b327-ab7c943c1f54', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of a Two-Phase Commit (2PC) protocol in distributed transactions?', N'Middle', N'2PC is used to ensure atomicity across multiple distributed nodes by coordinating a prepare phase and a commit phase. It guarantees that either all participating nodes commit the transaction or all of them roll back, ensuring a consistent global state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d316a77-dc8b-41f8-9e2a-ab7cfd20c6ae', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the primary difference between call-by-value and call-by-name evaluation in Scala?', N'Middle', N'Call-by-value evaluates the argument once before entering the function, while call-by-name evaluates the argument every time it is referenced within the function body. Call-by-name is useful for implementing custom control structures or lazy evaluation, but it can be less performant if the expression is computationally expensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3941c000-e7dc-4256-9d71-ab7d25120ee2', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does ''duck typing'' mean in the context of Ruby''s design philosophy?', N'Middle', N'Duck typing means that the suitability of an object for a specific operation is determined by the methods it responds to rather than its class or inheritance hierarchy. If an object behaves like a specific type by implementing the required interface, Ruby treats it as that type regardless of its actual class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b79d0e0-9e03-4179-be11-ab7df61e7032', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript differ from JavaScript regarding type checking?', N'Fresher', N'JavaScript is a dynamically typed language, meaning types are checked at runtime and variables can change types. TypeScript provides static type checking, where types are validated during the compilation process before the code is executed in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16f986c3-3b36-4f27-b45e-ab7f97b88ff6', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do Alpine.js transitions work with CSS?', N'Middle', N'Alpine.js manages CSS transitions by toggling specific classes on an element during its enter and leave phases. By using directives that map to these phases, developers can leverage standard CSS transition or animation properties to create smooth UI effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dbac496-4757-4bb5-89bf-ab81be90d3b2', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'In what scenario would you choose to use ''externals'' over bundling a library?', N'Senior', N'Externals are used to exclude dependencies from the bundle, typically when they are provided via a CDN or a global variable. This reduces bundle size and improves load times by leveraging browser caching across different applications that share the same CDN-hosted library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70ade1c2-5a21-418e-bf25-ab8447e644b2', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is idempotency important in distributed API design?', N'Middle', N'Idempotency ensures that making the same request multiple times has the same effect as making it once. This is critical in distributed systems to handle network retries safely when an acknowledgement of a successful request is lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff943336-867b-4f00-9370-ab85b2ef289f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of Layouts in the Next.js App Router?', N'Middle', N'Layouts allow you to share UI components, such as headers or sidebars, across multiple pages while preserving state and avoiding expensive re-renders during navigation. They wrap nested child routes and can be nested themselves to create complex UI hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68231c59-578f-4f16-b986-ab86ab8e65c9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a header in a Fiber request?', N'Fresher', N'Headers are key-value pairs that provide metadata about the HTTP request or response. Fiber''s context object allows you to both read incoming headers and set outgoing response headers easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'598fd77d-e18e-49eb-b5f8-ab87780114b9', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle authentication in a microservices API architecture?', N'Middle', N'In microservices, stateless tokens like JWT (JSON Web Tokens) are commonly used. The API gateway validates the token once and passes the user identity context to internal services, avoiding the need for every service to query an authentication database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c28106e-6565-41a9-bef2-ab87780d1f7a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the impact of schema design on MongoDB performance?', N'Middle', N'Because MongoDB is schema-flexible, poor design can lead to massive documents that exceed size limits or excessive application-level joins. Proper modeling—balancing embedding and referencing—is crucial for minimizing query complexity and maximizing throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea758193-da3a-4c86-b0d6-ab87af511c98', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary purpose of Redux in a web application?', N'Junior', N'Redux is a predictable state container used to manage the global state of an application. It helps in maintaining a single source of truth, making it easier to track state changes and debug complex data flows across multiple components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffd07584-62fe-4e04-870f-ab889bd5373d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Can you explain the virtual DOM in React?', N'Senior', N'Virtual DOM: 2026 Technical Audit The Virtual DOM (VDOM) remains a fundamental architectural pattern in React, though its implementation has evolved significantly with the introduction of React Fiber and concurrent rendering primitives. It serves as a declarative blueprint for the UI, allowing React to decouple UI state from expensive imperative browser DOM manipulations. Refined Mechanism 1. Initial Rendering: React creates a Fiber tree, a internal data structure representing the component tree. Each Fiber node corresponds to a React component or DOM element, holding state, props, and side effects. 2. Reconciliation (The Diffing Algorithm): When state updates occur, React triggers a re-render. It performs a tree comparison between the current Fiber tree and the new structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e135ac9c-802b-4f24-8910-ab894d8cceb5', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the time required to read all the books in a large library?', N'Intern', N'I would estimate the total number of books and the average reading speed for a standard page count. By calculating the total number of pages and dividing by the speed, I can determine the raw hours needed. I would then apply a multiplier to account for breaks, sleep, and the varying complexity of the material.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3870af6b-ada0-4472-8153-ab897fa16c24', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is database sharding and when should it be used?', N'Middle', N'Sharding is the process of splitting a large database into smaller, faster, more easily managed pieces called shards, distributed across multiple servers. It is used to overcome the limitations of vertical scaling when a single database node can no longer handle the read/write load or storage requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'954b8a37-07b9-4b20-b1ba-ab89cd6954ee', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Gems and how do you use them in a Rails project?', N'Fresher', N'Gems are pre-built, reusable packages in Ruby on Rails, serving similar purposes as libraries do in other languages. They streamline common software development tasks and add functionality to your application. RubyGems, the package manager for Ruby, is responsible for managing these gems. - Install Gems: Use the gem command-line tool to install a gem into your system, making it globally accessible: - Require Gems: When a gem is installed, you need to require it in your code. However, when using Rails, many gems are automatically loaded, removing the need for an explicit require statement: - Filter Gems: You can specify the versions of gems to use within your application by including them in the Gemfile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78ecf56c-6826-441a-9b85-ab89faa800a9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it important to use Doctrine''s ''flush'' method?', N'Junior', N'The ''flush'' method synchronizes the state of the entities managed by the Unit of Work with the actual database. Without calling this method, any changes made to entities, such as updates or deletions, will not be persisted to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79a503be-371e-4e54-9790-ab8f2d09ecfe', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle the trade-off between performance and the declarative UI approach?', N'Senior', N'Alpine.js prioritizes performance by manipulating the DOM directly rather than using a virtual DOM reconciler. This reduces memory usage and initial load time, though it requires more manual optimization when dealing with complex, high-frequency state updates to avoid browser layout thrashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fab4b05-cece-43f6-afee-ab8f610564d5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Discuss the impact of Tailwind CSS on the critical rendering path for complex applications.', N'Senior', N'Tailwind drastically reduces the total CSS bundle size by purging unused styles during the build process, which improves the critical rendering path. A smaller CSS file means faster parsing and less time spent in the render-blocking phase before the First Contentful Paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb44c12-f6c9-43e7-8754-ab90c36b8cc8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is ''Tail Call Optimization'' (TCO) rarely implemented in JavaScript engines, and how does this affect recursive architecture?', N'Senior', N'TCO requires that the stack frame be discarded before the recursive call, which complicates the ability to retrieve stack traces for debugging purposes. Because most engines prioritize developer experience and debugging capabilities, developers must architect recursive logic iteratively or use trampolining to prevent stack overflow errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'640e947f-1c13-48d1-825a-ab925f53a7bf', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does the concept of inheritance mean in C++?', N'Intern', N'Inheritance is a fundamental feature that allows a new class to derive properties and behaviors from an existing class. This promotes code reuse and establishes a hierarchical relationship between classes, where a derived class can extend or modify the functionality of a base class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61573473-1f3c-499f-8a85-ab9423fdd578', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When should you prefer GraphQL over REST for a distributed microservices architecture?', N'Senior', N'GraphQL is preferable when the frontend requires data from multiple disparate services and wants to avoid over-fetching or multiple round trips. However, it introduces complexity in caching, rate limiting, and complexity analysis which must be weighed against the benefit of a single flexible schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63fa8659-ed42-474e-829a-ab94c156c23a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle authentication?', N'Junior', N'Authentication is usually handled using the security utilities provided by FastAPI, such as OAuth2PasswordBearer. These tools work with the dependency injection system to extract tokens or credentials from requests and validate them before allowing access to a route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
