INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55cbf88f-6991-43f8-ac24-ab9bc934449b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the role of the Phoenix PubSub system and why it is essential for scaling real-time features.', N'Middle', N'Phoenix PubSub acts as a distributed message distribution layer that allows different nodes in a cluster to communicate. It decouples message producers from consumers, enabling real-time features to broadcast events across multiple server nodes seamlessly, ensuring that all connected clients receive updates regardless of which node they are connected to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
