INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dbbf7d1-33e5-448f-910d-ab9c9100860b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do Symfony''s ''Environment Variables'' enable the ''Twelve-Factor App'' methodology?', N'Senior', N'By externalizing configuration into environment variables, Symfony allows the same application build to run across different environments—development, staging, and production—without modification. This ensures the application adheres to strict separation of code and config, facilitating easier deployment and secret management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
