INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a37a0e8c-27a0-4214-95e1-ab9eb7018cdc', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What role does historical velocity play in your estimation process?', N'Middle', N'Historical velocity serves as a baseline for how much work a team can realistically complete in a given timeframe. It is a vital data point for capacity planning, but it must be adjusted based on the nature of the upcoming work, team composition changes, and external risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
