INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4e7bed1-3ff2-421a-b8cf-ab9ff918838d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the benefit of monomorphization in Rust''s generics?', N'Middle', N'Monomorphization generates specialized code for every concrete type used with a generic function or struct at compile time. This leads to high execution performance because the compiler can optimize the code for specific types, though it can increase binary size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
