INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'475a0a6a-1c9b-4399-89e9-aba46d96066f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are ''Signals'' in the context of Preact and why are they performant?', N'Middle', N'Signals are a reactive primitive that allow components to subscribe to state changes at a granular level. They are performant because they bypass the need to re-render the entire component tree, updating only the specific parts of the DOM that depend on the changed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df87bcf4-7169-41ec-90f9-aba57ea311a6', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does data denormalization improve performance?', N'Junior', N'Denormalization intentionally adds redundant data to a database to speed up read-heavy queries by reducing the number of table joins required. While it improves performance, it requires extra care to ensure data remains consistent during updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d8c393f-9ef5-4c0e-8b78-aba6bd67f9c4', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you assess the trade-off between build time and test coverage?', N'Middle', N'High test coverage is essential for stability, but excessive testing can lead to prohibitively slow CI/CD pipelines, frustrating developers and slowing down delivery. The trade-off is managed by prioritizing critical paths in unit tests and using integration or contract tests sparingly to keep build times within an acceptable threshold.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb6310ca-d578-4267-9cef-abaeb032f5fa', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'When should you use ''useSelector'' and ''useDispatch'' hooks?', N'Middle', N'These hooks are used in functional components to interact with the Redux store. ''useSelector'' retrieves data from the store state, while ''useDispatch'' provides access to the dispatch function for triggering actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'991da062-20cc-4cc2-9d54-abaecc5fc31f', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What architectural challenge does Remix''s parallel data loading solve?', N'Senior', N'It solves the ''Waterfall'' problem where the client must wait for one API call to finish before knowing which subsequent calls to make. By defining data needs at the route level, the server initiates all requests simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9f76d05-8fdb-4749-8228-abb2ef746e28', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''boot'' method in a Service Provider?', N'Fresher', N'The boot method is called after all other service providers have been registered, meaning you have access to all other services bound by the container. It is the ideal place to perform tasks that require other services to be fully initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3fd4d83-33fc-4d4c-9386-abb54bc6f155', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the trade-off between using an API Gateway versus a Service Mesh?', N'Senior', N'An API Gateway acts as the entry point for external traffic, handling authentication, rate limiting, and request routing. A Service Mesh focuses on internal east-west communication, managing mTLS, service discovery, and observability between services without the application being aware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd833a393-eff2-41e3-97cf-abb6487ba488', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is a negative cache (caching misses)?', N'Middle', N'Negative caching involves storing the result of a failed lookup (e.g., a database query that returns no results) in the cache. This prevents the system from repeatedly querying the database for keys that do not exist, protecting it from potential denial-of-service attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
