INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9021ced-e521-4c96-9d39-abc566dcca64', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between a method and a function in javascript?', N'Fresher', N'1. Function: A function is a piece of code that is called by name and function itself not associated with any object and not defined inside any object. It can be passed data to operate on (i.e. parameter) and can optionally return value. Example: Here, message() function call is not associated with object hence not invoked through any object. 2. Method: A JavaScript method is a property of an object that contains a function definition. Methods are functions stored as object properties. Example: Here employee is an object and getName is a method which is associated with employee. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
