INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f02a2c7-9c8d-4d7f-921f-abd8968a2445', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix ''Components''?', N'Junior', N'Components are reusable pieces of UI that can be shared across different templates or LiveViews. They help maintain a clean codebase by encapsulating HTML structure and logic into a single, testable unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec2fa241-cae8-4cca-9ff1-abda20707dcf', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How Garbage collection works in Node.JS?', N'Fresher', N'The V8 uses a scheme similar to the Java Virtual Machine and divides the memory into segments. The thing that wraps the scheme concept is known as Resident Set, which refers to the portion of memory occupied by a process that is held in the RAM. * Stack: Stores static data, method and function frames, primitive values, and pointers to stored objects. The stack is managed by the operating system. * Heap: Stores objects. Because everything in JavaScript is an object this means all dynamic data like arrays, closures, etc. The heap is the biggest block of memory and it''s where Garbage Collection (GC) happens. * Code Segment: the actual code is being executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40864a91-7d94-4aff-a888-abdbff63a5d0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between setState() and replaceState() methods?', N'Fresher', N'When you use setState() the current and previous states are merged. replaceState() throws out the current state, and replaces it with only what you provide. Usually setState() is used unless you really need to remove all previous keys for some reason. You can also set state to false/null in setState() instead of using replaceState().', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad3ade8-4f1a-40a8-b4ca-abdc80eed30e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle memory allocation for large sorts and joins?', N'Senior', N'PostgreSQL allocates memory dynamically based on the work_mem setting per operation. If the data set for a sort or hash operation exceeds this threshold, the engine spills the data to temporary files on disk, which drastically increases latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd47c19d-2610-4456-bd66-abdf26dabcb8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can Preact be used in non-browser environments?', N'Middle', N'Yes, Preact can be used for server-side rendering or in environments like React Native through specific adapters. Because it is a lightweight library, it is often easier to adapt to custom environments than heavier alternatives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad436a3b-1384-4999-bcfe-abe28d9ad18a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust treat shadowing?', N'Junior', N'Shadowing allows you to declare a new variable with the same name as a previous one, effectively hiding the old value. Unlike mutability, this allows you to change the type of the value while keeping the same variable name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33a73da9-e5b8-4d60-9467-abe2eae8ecac', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''Task.Run'' and ''Task.Factory.StartNew''?', N'Middle', N'Task.Run is a simplified method for offloading work to a thread pool thread, providing sensible defaults for most scenarios. Task.Factory.StartNew offers more advanced configuration options, such as specifying custom schedulers or long-running task behavior, but it requires careful use to avoid issues with nested tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a11d9640-d14a-4e20-ad17-abe38c52fa65', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the browser''s Garbage Collector decide when to clean up objects?', N'Senior', N'Modern engines use a generational garbage collection strategy, separating objects into young and old generations. It primarily uses a mark-and-sweep algorithm, where it identifies reachable objects from roots; those not marked as reachable are considered garbage and removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c46350d-998b-4894-b41a-abe42bdbfe1f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro components communicate with each other if they are isolated as islands?', N'Middle', N'While islands are isolated, they can communicate through shared state managers like Nano Stores or standard browser events. However, the framework design encourages independent components to minimize the complexity of inter-island communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb8542cb-a308-4744-8ef0-abe626ad45aa', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the benefit of using LINQ?', N'Junior', N'LINQ provides a consistent, readable, and declarative syntax for querying data from various sources like collections, databases, or XML. It reduces the need for complex nested loops and improves code maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
