INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e48c214e-20fd-43d4-9a0c-abee3d8eab13', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a helper and a controller action?', N'Intern', N'Controller actions handle business logic and data retrieval, while helpers are methods designed specifically to assist in rendering views. Helpers should generally be used for formatting or displaying data rather than manipulating database state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9674853-14e1-4f64-ab4b-abf00411870b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the architectural difference between a single process with multiple threads and a cluster of multiple processes.', N'Senior', N'A cluster utilizes multiple instances of the Node.js process, offering better fault tolerance and leveraging multi-core CPUs by spreading the load across separate event loops. A single process with worker threads shares memory, which is faster for data-intensive tasks but risks crashing the entire process if an unhandled exception occurs in a thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67aff7cd-8c2d-42ea-93de-abf1d306b8f2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Can you perform joins in Cassandra?', N'Intern', N'No, Cassandra does not support joins between tables. Data in Cassandra should be modeled according to the queries you intend to perform, often resulting in denormalized data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
