INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e39ebe9-8129-45f7-83ef-abf4d7e1ecff', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What does the ''Consistency Level'' setting control?', N'Junior', N'The consistency level determines how many replicas must respond to a read or write request for it to be considered successful. Higher consistency levels provide more accuracy at the cost of latency, while lower levels offer faster performance with a greater risk of reading stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d6b02af-e270-483f-b4c6-abf56bf4aa56', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''mounted'' hook?', N'Junior', N'The mounted hook is called after the component has been inserted into the DOM. It is the ideal place to perform operations that require access to the rendered elements, such as initializing third-party libraries or measuring DOM dimensions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bfffda0-3c39-4a9c-8d65-abf5c95a4382', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary difference between React and Preact?', N'Intern', N'Preact is a lightweight alternative to React that offers the same core API but with a significantly smaller file size. It achieves this by stripping away some of the less commonly used features found in the larger React library. This makes Preact an excellent choice for performance-sensitive web applications where load time is a priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9357c878-8b14-4077-9057-abf5f0274b95', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the role of the ''use client'' directive in a Next.js App Router environment?', N'Senior', N'The ''use client'' directive marks the boundary between server-rendered components and client-side interactivity. It instructs the framework to bundle these modules for the browser, enabling the use of React hooks and browser-only APIs while keeping the rest of the application tree on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5abb7bcd-b5b0-473c-b346-abfae1500f16', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How can you implement request throttling in Flask without overloading the application process?', N'Senior', N'Throttling should ideally be offloaded to an edge layer or API gateway (like Nginx or Kong) to prevent malicious traffic from ever reaching the application. If implemented at the application level, it requires a distributed cache like Redis to track request counts across multiple application instances, as local memory stores would be inconsistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
