INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b43dbd32-8312-4016-8abf-abfcd71eeb39', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the architectural advantage of Axum''s ''Router'' nesting?', N'Senior', N'Router nesting allows developers to modularize complex applications into smaller, isolated components. By mounting sub-routers at specific paths, teams can manage different parts of the API independently, each with its own set of middleware, state, and versioning, improving maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48f7ea90-1ee5-4f89-a5f2-abfcfd9f5f36', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle the request timeout, and what is the best practice for managing long-running requests?', N'Middle', N'Express does not have a built-in timeout mechanism, so developers often use middleware like ''connect-timeout'' to enforce limits. For long-running operations, it is best practice to perform the work asynchronously and return a 202 Accepted status, or use WebSockets/Server-Sent Events to provide updates to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48da936b-ed1c-43d7-a39d-abfd09ace184', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the advantage of using jQuery animations over CSS transitions?', N'Intern', N'While CSS transitions are generally more performant, jQuery animations provide greater programmatic control and ease of use for complex sequences. They are useful when you need to trigger animations dynamically based on logic or when supporting very old browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92417b1a-fbe2-4142-96b9-abfe6d4ad4d3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin manage concurrent request handling?', N'Middle', N'Gin leverages the underlying Go http.Server, which spawns a new goroutine for every incoming request. Gin''s Context is designed to be safe for concurrent access within the scope of a single request, but it should not be shared across different requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5ed4941-108c-4b44-b414-ac0063395e8c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are decorators in Python and when are they used?', N'Junior', N'Decorators are a design pattern that allows you to wrap another function to extend its behavior without explicitly modifying its source code. They are commonly used for tasks like logging, access control, or caching results, as they provide a clean way to add reusable functionality to existing functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc6920c9-c044-4dd1-a709-ac02913ac5c0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is database atomicity?', N'Intern', N'Atomicity is a property of database transactions that ensures a series of operations either all succeed or all fail as a single unit. This prevents the database from being left in a partially updated or inconsistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10efb6d4-3c77-4082-8072-ac03847240d9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust distinguish between ''&'' and ''&mut''?', N'Intern', N'This distinction enforces the rule that you can have either multiple read-only references or one read-write reference to data. By preventing simultaneous modification and access, it eliminates data races at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5020acaf-ecde-43ef-8dcf-ac04b3df0928', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a Counter in Python?', N'Intern', N'Ans. The function Counter() from the module ''collections''. It counts the number of occurrences of the elements of a container. from collections import Counter Counter([1,3,2,1,4,2,1,3,1]) Counter({1: 4, 3: 2, 2: 2, 4: 1}) Python provides us with a range of ways and methods to work with a Counter. Read Python Counter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5053e0bc-152b-4ce8-8cd3-ac07cead7b0b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between a method and a function in javascript?', N'Fresher', N'1. Function: A function is a piece of code that is called by name and function itself not associated with any object and not defined inside any object. It can be passed data to operate on (i.e. parameter) and can optionally return value. Example: Here, message() function call is not associated with object hence not invoked through any object. 2. Method: A JavaScript method is a property of an object that contains a function definition. Methods are functions stored as object properties. Example: Here employee is an object and getName is a method which is associated with employee. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a453a855-ef7d-4422-b119-ac08921f855b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What does ''currentColor'' do in CSS?', N'Junior', N'The ''currentColor'' keyword is a variable that represents the value of the color property of the current element. It is very useful for keeping icons or borders in sync with the text color of an element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a9796cc-c181-41b7-a077-ac08c227c7f0', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''footer'' element?', N'Junior', N'The footer element contains information about the author, copyright data, or links to related documents. It typically appears at the bottom of the page or at the end of a section.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03944dd8-e728-4078-967e-ac090d7df7c0', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle routing to specific controller functions?', N'Junior', N'Rocket uses procedural macros, such as #[get] or #[post], to map incoming HTTP requests to specific functions. By annotating a function, you define the path and method it handles, allowing the framework to route traffic automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e24745b-98f1-4151-9018-ac0a051627e4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why should developers favor ''static styles'' in Lit components?', N'Senior', N'Static styles are parsed and processed once per component class rather than once per instance. This significantly reduces the memory footprint and initial render time when multiple instances of the same component are present on a page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67bb16a1-5265-4400-af22-ac101b7baa66', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''const'' constructor affect memory allocation and performance?', N'Senior', N'Const constructors allow for compile-time constant objects, which are canonicalized by the compiler. This ensures that multiple references to the same constant value point to the same memory address, reducing heap allocation overhead and memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92f4cd64-0f9e-47b7-8531-ac14b46b225b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI support testing with the ''TestClient''?', N'Middle', N'The TestClient is built on the ''httpx'' library and allows you to simulate requests to your FastAPI application without needing to run a live server. It integrates perfectly with standard testing frameworks like ''pytest'' and allows you to override dependencies to mock external services or databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'327467e7-dc0f-4ba3-8e84-ac1877712b06', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are magic methods in PHP?', N'Intern', N'Magic methods are special methods prefixed with double underscores that are triggered by specific actions. Examples include object creation, property access, or method invocation, allowing for advanced object-oriented behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a07c90b7-f064-4a5c-80c1-ac18e79be276', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the Event Loop in Dart''s execution model?', N'Middle', N'The Event Loop manages the execution of asynchronous code by maintaining two queues: the microtask queue and the event queue. It continuously checks these queues, processing all microtasks first before moving to the next item in the event queue, ensuring non-blocking I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09e2fd94-c9b2-436a-b344-ac1b2164b52e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where a team member disagrees with your proposed technical solution?', N'Middle', N'I treat the disagreement as an opportunity to pressure-test the design by asking for a detailed critique of my proposal. I listen to their concerns and encourage them to present an alternative approach, evaluating both options based on objective criteria like performance, maintainability, and complexity. If we remain split, I seek a third opinion or run a small experiment to gather data that informs the final decision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f768222-06a9-4ed8-a874-ac1c96ab3289', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between a ''val'' and a ''def'' in terms of evaluation?', N'Middle', N'A ''val'' is evaluated once when the object is initialized and then stored in memory, whereas a ''def'' is evaluated every time it is invoked. Using ''val'' is generally preferred for performance when the value is constant, while ''def'' is better for dynamic computation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9824e103-df8e-4632-b853-ac1d4443a209', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of the ''c.JSON'' method in Gin?', N'Intern', N'The c.JSON method is used to send a JSON-encoded response to the client. It automatically sets the ''Content-Type'' header to ''application/json'' and serializes the provided data structure into the response body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f291e209-c2f5-45a9-8df1-ac20e0afaee5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is a CSS preprocessor?', N'Intern', N'A CSS preprocessor is a tool that allows you to write code in a language that extends CSS with features like logic and variables. Because browsers cannot read this code directly, the preprocessor compiles it into standard CSS files that browsers can understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3269426-7bf8-4092-bc56-ac22649ebf52', N'4c000000-0000-0000-0000-000000000005', N'What are the primary architectural risks of a shared database in a microservices environment?', N'Senior', N'A shared database creates tight coupling between services, making independent schema evolution impossible and causing hidden dependencies. It often leads to performance contention and makes it difficult to scale individual services based on their specific workload requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'108060bb-9f53-442a-b4c7-ac237be44fa8', N'075b8862-431c-4678-9767-f55359758a4a', N'What are computed properties and how are they used?', N'Intern', N'Computed properties in Vue.js are derived data elements that automatically update whenever their "watched" dependencies change. They eliminate the need for manual tracking and updating of data, offering a simpler and more efficient data management tool. Core Benefits - Caching: Computed values are cached based on their dependencies. They recalculate only when a dependency changes, enhancing performance. - Simplicity: Create and use computed properties with the same seamless syntax as other data properties, like data and methods. When to Use Computed Properties - Derivative Data: It''s best used for data that is derived from other data, rather than being independent. - Data Aggregation: For processes like filtering, sorting, and data aggregations like sums or averages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d7d14a3-3da0-409a-972f-ac238f73b219', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is MDX in the context of Astro?', N'Intern', N'MDX is a format that allows you to write JSX within Markdown files. It enables you to import and use Astro or UI framework components directly inside your Markdown content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'422ab0e9-cb99-4fd0-a36a-ac252a68fba3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the architectural benefits of moving business logic into type-level code?', N'Senior', N'Moving logic into type-level code ensures that constraints are checked before runtime, effectively turning business rules into compiler errors. This results in a self-documenting codebase and prevents illegal states from ever being represented in the application memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59c6505b-ded2-4c89-a49b-ac266b0c7600', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''defer'' attribute affect script loading?', N'Junior', N'The defer attribute tells the browser to download the script in the background and execute it only after the HTML document has been fully parsed. This prevents the script from blocking the rendering of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a9bcf10-b88e-4d25-b050-ac27e87fa96d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the trade-offs of using Phoenix for a high-throughput microservice versus a monolithic architecture?', N'Senior', N'Phoenix excels in microservices due to its low footprint and high concurrency, but its greatest strength lies in monoliths where you can leverage internal process communication instead of network calls. While it can handle both, the ability to avoid inter-service network latency by keeping related components in the same VM often favors a modular monolith approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76f9ab63-9ee1-40ba-9598-ac2832c606d8', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the role of the Spring DispatcherServlet.', N'Middle', N'The DispatcherServlet acts as the Front Controller in the Spring MVC framework, receiving all incoming HTTP requests. It manages the request flow by delegating to handler mappings, controllers, and view resolvers to generate the final response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd0be2eb-4d43-4caa-b620-ac2d733f96ff', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What does the @Injectable decorator do?', N'Fresher', N'The @Injectable decorator attaches metadata to a class, declaring that it is a provider that can be managed by the NestJS IoC (Inversion of Control) container. This allows the class to be automatically injected into other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c76ebcd-82fe-4da9-aa00-ac30fd571949', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the significance of the Content Security Policy (CSP) in relation to the execution of third-party scripts?', N'Senior', N'CSP provides a security layer that restricts the domains from which scripts can be loaded and executed, mitigating the risk of XSS and data exfiltration. Configuring a strict CSP is vital for enterprise apps to prevent malicious third-party code from accessing sensitive user data or unauthorized DOM areas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e12c64e-9838-4ccb-985d-ac31b6153a6b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Describe the concept of ''Graceful Degradation'' in a distributed system.', N'Senior', N'Graceful degradation ensures that when parts of a system fail, the application continues to provide core functionality rather than crashing entirely. This is achieved by serving cached data, disabling non-essential features, or providing simplified responses during high-load periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11104123-7a8c-4615-a0cb-ac31ef72eb13', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a raw value in an enumeration?', N'Junior', N'A raw value is a pre-assigned default value of a specific type that is associated with each case in an enumeration. All cases in an enum must have the same type, such as strings, characters, or integers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b10792f2-f889-4720-862d-ac32658d4ac3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Can you use standard JavaScript with jQuery?', N'Intern', N'Yes, jQuery is built on top of JavaScript, so they are fully compatible. You can freely mix jQuery methods with native JavaScript code in the same project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64418aea-4759-4150-91e3-ac39de1b5a7f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between using a managed cloud service versus hosting your own infrastructure on VMs?', N'Middle', N'Managed services significantly reduce operational burden and time-to-market, but they often come with higher costs and vendor lock-in. Self-hosting on VMs offers greater control, cost optimization, and portability, but it requires a dedicated team to manage patching, scaling, and high availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47c684fb-ae99-4600-afce-ac3d3e7b0f9e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do ''Higher-Order Components'' (HOCs) compare to ''Custom Hooks'' for logic reuse?', N'Senior', N'HOCs wrap components in a function, which can lead to ''wrapper hell'' and prop collisions. Custom hooks provide a more direct, composable way to share logic without altering the component tree structure, making the data flow more transparent and easier to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1086b21-e8e2-42fc-97e7-ac3d55732e4b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are Indexes in MongoDB?', N'Intern', N'Indexes support the efficient execution of queries in MongoDB. Without indexes, MongoDB must perform a collection scan, i.e. scan every document in a collection, to select those documents that match the query statement. If an appropriate index exists for a query, MongoDB can use the index to limit the number of documents it must inspect. Indexes are special data structures that store a small portion of the collection''s data set in an easy to traverse form. The index stores the value of a specific field or set of fields, ordered by the value of the field. The ordering of the index entries supports efficient equality matches and range-based query operations. In addition, MongoDB can return sorted results by using the ordering in the index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f81edca-29f0-4655-9991-ac41ac5bb4ef', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the trade-offs of using Tunable Consistency in a distributed system.', N'Senior', N'Tunable consistency allows developers to balance latency and data accuracy by adjusting the number of nodes that must acknowledge a read or write operation. Choosing higher consistency levels increases data safety but raises latency and reduces availability during network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b42fdd86-3d56-4222-97b3-ac4268410c51', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-offs of implementing feature flags in a production application?', N'Middle', N'Feature flags enable safer deployments, A/B testing, and rapid rollbacks, but they introduce code complexity and the risk of ''flag debt'' where obsolete flags clutter the codebase. Successful usage requires a strict lifecycle policy for creating, using, and cleaning up flags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'915fe595-5b77-461f-9ca2-ac452ff3a617', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Does Gin support multiple HTTP methods for the same route?', N'Fresher', N'Yes, you can define different handlers for different HTTP methods like GET, POST, PUT, and DELETE on the same path. Gin keeps these mappings separate within its routing engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e91c1af6-d224-458c-a378-ac4a43203137', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the concept of ''silent'' vs. ''public'' members in Sass modules.', N'Senior', N'Members (variables, functions, mixins) are private by default if they start with an underscore or hyphen, making them accessible only within the module. This encapsulation allows developers to hide implementation details and expose only the intended public API, reducing the risk of breaking changes for consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea0cdb83-8c80-4387-8f1e-ac4ae1b5150b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is it recommended to use Dynamic Modules for configuration or database connections in large-scale NestJS applications?', N'Senior', N'Dynamic modules allow for the runtime configuration of providers based on external settings or environment variables. This pattern enables the injection of dynamic values into services during initialization, which is essential for creating flexible, environment-agnostic infrastructure layers that don''t hardcode sensitive configuration data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd50e92a9-76a8-4ef6-9405-ac4bfc7aae5a', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the common pitfalls when scaling a Rails application on a platform like Heroku versus AWS EC2?', N'Senior', N'Heroku abstracts infrastructure but limits control over network tuning and persistent background processes, leading to higher costs at scale. AWS EC2 offers full control and better cost-efficiency for large workloads but requires significant investment in DevOps for managing auto-scaling groups, load balancers, and container orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72143ab4-9c4b-4832-931a-ac4cad744c29', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Mounting'' point in Rocket?', N'Intern', N'Mounting is the process of attaching a set of routes to a specific base path. It allows you to organize your application by grouping related routes under a common URL prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54bfd900-7ace-42d8-84a4-ac4f0362d366', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the architectural advantage of using Pydantic''s ''ORMO mode'' when working with database models?', N'Senior', N'ORM mode allows Pydantic to read data from ORM objects using attribute access rather than dictionary keys, making it compatible with non-dict database entities. This enables seamless conversion between complex database model instances and clean, validated API response schemas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68d6dc3e-241e-4c85-937a-ac50a5da3d67', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the performance implications of ''source-map'' generation in large-scale applications?', N'Senior', N'Generating full source maps significantly increases build time and memory consumption during the compilation process. For very large codebases, developers often opt for lighter source map formats or disable them entirely in development to maintain rapid iteration cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31a36991-a86d-4546-b1af-ac51bfd3c3cf', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-offs between implementing a caching layer and optimizing the underlying database queries?', N'Middle', N'Optimizing database queries is generally preferred as it addresses the root cause of latency and reduces resource utilization across the board. Caching is an excellent strategy for high-read scenarios where data doesn''t change frequently, but it introduces complexity regarding cache invalidation and stale data. The approach should favor query optimization first, using caching as a supplementary layer for read-heavy workloads where latency remains unacceptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
