INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a04ae6f-ee5c-408d-b075-ac598f7c4906', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a reference and a pointer in Rust?', N'Intern', N'References in Rust are a type of pointer that is guaranteed to point to a valid value of a particular type due to the borrow checker''s rules. Raw pointers exist but are considered ''unsafe'' because they do not have the same safety guarantees as references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e86cebcc-ee48-4eaf-9bbc-ac5b86e9469e', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle data replication across Availability Zones?', N'Middle', N'DynamoDB automatically replicates data across three separate Availability Zones within a region by default. This ensures high availability and durability, allowing the database to remain operational even if an entire data center fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1d6e9bd-c5a5-4d1e-abb5-ac610791c3f4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of ''override'' and ''new'' keywords?', N'Fresher', N'The ''override'' keyword extends or modifies the implementation of an inherited virtual method. The ''new'' keyword hides the base class member, creating a separate implementation that is not part of the polymorphic hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10a785d3-2670-467b-bd0d-ac6770dc350a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is a ''Bounded Context'' in Domain-Driven Design and how does it relate to microservices?', N'Middle', N'A Bounded Context defines the scope within which a particular domain model is valid. It serves as the logical boundary for a microservice, ensuring that services remain focused and that the data model is consistent only where it matters, preventing ''leaky abstractions'' between services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ab9dd3f-e1cc-491a-9a2a-ac68297be86a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the architectural implications of the InnoDB Change Buffer?', N'Senior', N'The Change Buffer caches changes to secondary index pages that are not in the buffer pool, delaying disk writes until the pages are read into memory. This improves write performance by transforming random disk I/O into sequential operations, though it may cause a performance spike during heavy read workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f07a433-e686-43cb-95c1-ac6c4d5750a1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Mixins and why is their use discouraged in modern Ember?', N'Middle', N'Mixins allow you to share code across classes by merging properties and methods, but they often lead to ''fragile base class'' issues and naming collisions. Modern Ember favors composition via components, services, and modifiers, which provide better type safety and clearer data flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8682387a-e86c-42c8-b8c5-ac6e4fca40db', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the performance impact of using Hibernate''s ''Open Session in View'' pattern?', N'Senior', N'Open Session in View keeps the database connection open throughout the entire HTTP request lifecycle, including view rendering. This significantly increases the duration of connections held per request, leading to database connection pool exhaustion and reduced throughput under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62e8992a-28e4-4b9a-bf56-ac6f230cb2da', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of the DISTINCT keyword?', N'Fresher', N'The DISTINCT keyword is used in a SELECT statement to return only unique or different values. It effectively removes all duplicate records from the query result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4d9a979-5c24-4fd9-8f15-ac6f573d5b79', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do ''Indexes'' differ in NoSQL compared to RDBMS, specifically regarding write overhead?', N'Senior', N'In RDBMS, indexes are often B-Trees that require complex tree rebalancing during every write, which can become a bottleneck. In NoSQL, indexes are often maintained as separate structures or secondary indexes, which can lead to significant write amplification because every write operation must trigger secondary updates, potentially across different nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1da7e233-4179-43b8-997e-ac70a3bea2de', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the security trade-off between using a shared database versus a database-per-service model?', N'Senior', N'A shared database creates a single point of failure and makes it harder to enforce fine-grained access controls, as one service may inadvertently access another''s data. A database-per-service model enforces strong data isolation and allows for specialized security configurations per service, though it increases operational complexity in cross-service data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4268e737-96d4-4e92-b77f-ac7240bd98c0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are ''associated types'' in traits?', N'Middle', N'Associated types allow a trait to define a type placeholder that will be determined by the implementer of the trait. This approach makes trait definitions cleaner by avoiding the need for extra generic parameters when a trait is strongly linked to a specific type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad1fab4b-9102-4cd7-b659-ac778bf2282b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between COUNT(*) and COUNT(column_name)?', N'Junior', N'COUNT(*) counts all rows in a result set including those with null values. COUNT(column_name) counts only the rows where the specified column contains a non-null value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38f8ca65-d942-4003-ac78-ac79f76383e4', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between a row-oriented and a column-oriented database?', N'Middle', N'Row-oriented databases store data in rows, making them ideal for transaction-heavy applications (OLTP) where full records are frequently accessed. Column-oriented databases store data in columns, which is highly efficient for analytical queries (OLAP) that aggregate large volumes of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'075be661-200c-47d8-8ac8-ac7e8913162f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of a Primary Key?', N'Intern', N'A primary key is a column or a set of columns that uniquely identifies each row in a table. It ensures that no two rows have the same identifier and prevents null values, guaranteeing data uniqueness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa780d96-39c5-449b-a350-ac7ff19cd365', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between First Normal Form (1NF) and Second Normal Form (2NF)?', N'Junior', N'1NF requires that table cells contain atomic values and each record is unique. 2NF builds on this by requiring that all non-key attributes are fully functionally dependent on the entire primary key, eliminating partial dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
