INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a4b56f-9560-40d3-92f5-ac82a8a2bd05', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary architectural difference between Cassandra and a traditional RDBMS?', N'Junior', N'Cassandra is a distributed NoSQL database designed for high availability and horizontal scalability, whereas RDBMS is typically centralized and focuses on ACID compliance. Cassandra uses a peer-to-peer architecture with no single point of failure, while RDBMS usually relies on a primary-replica model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
