INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd88d0cbe-60c6-4ba0-84a1-ac9a55d7d6e5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What steps do you take when a third-party API starts returning unexpected errors?', N'Middle', N'I would immediately check the third-party provider''s status page to see if there is a known service outage. If no outage is reported, I would analyze the error payloads to determine if our integration is sending malformed requests or if the API behavior has changed. I would then implement circuit breakers or fallback logic to isolate our system from the failing dependency and ensure continued operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'340b2324-9369-4d25-a38e-ac9c5b02afd1', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the trade-offs between using struct and class types regarding CPU cache locality and GC pressure.', N'Senior', N'Structs allow for value-type semantics that improve cache locality by storing data inline within arrays or parent objects, reducing pointer indirection. However, excessive use of large structs can increase stack pressure or lead to hidden copies when passed as arguments, whereas classes rely on heap allocation and garbage collection, impacting memory throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abea16b0-a418-4b86-a503-ac9fedd09c14', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the ''Spring Cache'' abstraction, and how does it impact system performance?', N'Senior', N'Spring Cache provides a consistent API for integrating various caching providers like Redis or Ehcache without coupling the code to a specific implementation. It improves performance by reducing the number of expensive operations, such as database queries or API calls, by storing and retrieving data from faster, in-memory storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d472e38-745a-48d3-a289-aca22393fd27', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why should you minimize the number of external libraries or dependencies in a project?', N'Fresher', N'Each added dependency increases the size of the application and introduces potential security risks if the library is not well-maintained. It also makes the project harder to upgrade and manage over time as you become reliant on third-party code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0da3f90f-2628-47da-82e3-aca2b07cab78', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why would you choose to use a Content Delivery Network (CDN) for a web application?', N'Middle', N'A CDN caches static assets at edge locations closer to the end user, significantly reducing latency and server load. This improves the overall user experience and provides an additional layer of protection against certain types of traffic-based attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de33157b-2102-4b29-8235-aca3c439ed3c', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s handling of static files compare to using a dedicated reverse proxy like Nginx?', N'Senior', N'Echo is capable of serving static files, but it is architecturally inferior to a dedicated proxy like Nginx or a CDN. Offloading static assets to Nginx reduces the load on the Go runtime, freeing resources for business-critical application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'001d3f3e-e6a4-456c-8871-aca4522a0cbc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'A production service is suddenly crashing. What is your immediate priority?', N'Junior', N'The immediate priority is to restore service stability, typically through a rollback to the last known stable version if the crash followed a recent deployment. Once the system is stable, I would then begin a post-mortem analysis to identify the cause of the failure without the pressure of an ongoing outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b1ab479-20c2-4632-bf76-aca6fd5aae61', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Describe the implications of strict aliasing rules for the C compiler.', N'Senior', N'Strict aliasing assumes that pointers of different types do not point to the same memory location, unless one is a character type. This allows the compiler to perform aggressive optimizations like register caching, but violating these rules leads to undefined behavior if the compiler assumes memory addresses are independent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f1a467c-4364-482d-8996-aca79e2b6c44', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How should you approach the trade-off between using established technology versus cutting-edge, experimental tools?', N'Intern', N'Established technology offers stability, community support, and known pitfalls, which reduces project risk. Experimental tools may offer superior efficiency or features, but they carry the risk of lack of support, bugs, and a steeper learning curve for the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'820744b2-7548-4d75-9b72-aca982602beb', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of normalization in a relational database, and what is its main goal?', N'Junior', N'Normalization is the process of organizing data to reduce redundancy and improve data integrity. The primary goal is to ensure that each piece of data is stored in only one place, which prevents anomalies during updates, insertions, or deletions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ae5fa3d-9d06-42fa-9c26-acaadbeadf45', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the function of the ''Drop'' trait?', N'Middle', N'The Drop trait allows a type to define custom cleanup logic that runs automatically when an instance goes out of scope. This is the mechanism that powers RAII, ensuring resources like file handles or network sockets are closed immediately when their owner is dropped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6c84236-d955-4fd6-bf7a-acad22561695', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'When should you choose DynamoDB over a Relational Database Management System (RDBMS)?', N'Middle', N'DynamoDB is preferred for applications requiring predictable single-digit millisecond latency at any scale and those with massive, rapidly growing datasets. RDBMS is better suited for complex transactional integrity, multi-table joins, and scenarios where schema flexibility is secondary to strict relational consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3b55e2d-6074-4819-a39e-acad4f40cb5a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How do you perform database migrations in Django?', N'Junior', N'Migrations are managed via the command line using ''makemigrations'' to create files that describe changes to your models and ''migrate'' to apply those changes to the database schema. This version-controls your database structure alongside your code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21c66feb-48d8-4cdb-9469-acaec3b6c837', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database triggers impact system maintainability?', N'Middle', N'Triggers automate tasks based on data changes, which can be useful for auditing or cross-table integrity. However, they are often hidden from application code, which can make debugging complex, performance profiling difficult, and logic harder to maintain over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ee7cc79-5c50-4909-9fb7-acafc416bcdb', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between ''onModuleInit'' and ''onApplicationBootstrap'' lifecycle hooks?', N'Middle', N'onModuleInit is called once the module''s dependencies have been resolved, while onApplicationBootstrap is called once all modules have been initialized but before the application starts listening for connections. The latter is preferred for tasks that require the entire dependency graph to be ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
