INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6946925-3ecf-4162-bb42-acb80978bebd', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of small memory footprint in Quarkus?', N'Intern', N'A small memory footprint allows for higher density of application instances on a single physical host or cloud node. This reduces infrastructure costs and improves the efficiency of scaling in containerized environments like Kubernetes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'348c0720-8b1d-4de5-b5bd-acb984d80006', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s ahead-of-time (AOT) compilation differ from the runtime reflection used by traditional frameworks like Spring?', N'Middle', N'Traditional frameworks use runtime reflection to scan the classpath and build dependency graphs, which increases startup time and memory consumption. Micronaut performs this processing at compile time, generating metadata and bean definitions as part of the build process, resulting in significantly faster startup times and lower memory footprints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
