INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f88cfb4-4177-45d0-8f00-acbd06f4406d', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is it dangerous to perform side effects directly in the component body in SolidJS?', N'Senior', N'Since components only execute once, code written in the component body is not reactive. Any side effect that needs to react to state changes must be wrapped in an Effect or other reactive primitive to ensure it updates when the data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5a13bd7-00e4-4100-9c5a-acbd71f06544', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Dependency Injection?', N'Junior', N'Dependency injection is a design pattern where an object receives other objects it needs to function, rather than creating them itself. This makes code easier to test, maintain, and decouple from specific implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68447cac-343c-4229-ba0c-acbdb7734355', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'When should you choose a ''multi-document transaction'' over document-level atomicity?', N'Middle', N'Document-level atomicity is sufficient for most operations in MongoDB. Multi-document transactions should be reserved for complex use cases requiring ACID guarantees across multiple documents or collections, noting that they incur a performance penalty in terms of latency and resource locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cbeeef3-5e33-4c4e-be7d-acbe4ac80eb2', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the benefits of using ''async'' and ''await'' over manual thread management?', N'Middle', N'Asynchronous programming with async and await allows the thread to be released back to the thread pool while waiting for I/O operations to complete. This improves the scalability of the application, as fewer threads are needed to handle a high volume of concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd316f160-749d-4f31-93a2-acbe7b1e0c1a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the benefit of using ''optimization.splitChunks''.', N'Middle', N'This feature automatically identifies common dependencies shared across multiple entry points or asynchronous chunks and extracts them into separate files. This prevents duplicate code in the final bundle and improves caching efficiency as common libraries remain constant across updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b924441-c6f8-4f1b-8cb4-acc2bab8f913', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik often called a ''zero-hydration'' framework?', N'Junior', N'It is called zero-hydration because it eliminates the hydration phase entirely, where frameworks usually download all components to verify the DOM. Instead, Qwik just resumes execution from the server-defined state, effectively skipping the need to reconstruct the application tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'451ba430-4e51-475c-a410-acc4e4fc8d2c', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Discuss the performance trade-offs of using ''display: none'' vs ''visibility: hidden'' regarding the rendering tree.', N'Senior', N'Display: none removes an element from the document flow entirely, triggering a reflow and preventing the browser from painting or interacting with the element. Visibility: hidden keeps the element in the layout, meaning the browser still reserves space for it and includes it in geometry calculations, only skipping the paint step.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42629b74-d5fe-4d45-b5d2-acc6648d7c16', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the architectural significance of the ''g'' object in Flask, and how should it be used?', N'Senior', N'The ''g'' object provides a safe way to share data during a single request lifecycle, such as storing a database connection or user object initialized by a ''before_request'' hook. It acts as a request-scoped registry, preventing the need to pass variables through every function call in the call stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fc3080c-ca61-41f1-ab93-acc7dd9c3023', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Discuss the trade-offs of using Ember''s ''Registry'' versus the ''Container'' pattern.', N'Senior', N'The registry acts as a blueprint defining how objects should be instantiated, while the container is the object that manages the lifetime and lookup of those instances. This abstraction enables advanced patterns like feature flagging, mocking dependencies in testing, and environment-specific object overrides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c8099d3-1204-4cec-b661-acc848861f9e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Compare the performance overhead of JSON serialization versus Protobuf or MessagePack in ASP.NET Core.', N'Senior', N'JSON is text-based and human-readable, but carries high overhead for parsing and serialization due to its verbosity. Binary formats like Protobuf or MessagePack are significantly more compact and faster to serialize/deserialize, making them ideal for high-throughput internal communication between microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ca9f65c-254e-4acd-ae47-acc97d5b9c48', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of an AdonisJS Validator?', N'Junior', N'The validator is used to enforce rules on incoming request data, such as requiring specific fields or verifying data formats. It ensures that the input is sanitized and structurally correct before it ever reaches the controller logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b567dea1-f40a-4352-8892-accc3412445d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Isolation'' property in ACID ensure data integrity?', N'Middle', N'Isolation ensures that concurrent transactions execute as if they were running sequentially. It prevents intermediate states of one transaction from being visible to others, thereby avoiding anomalies like dirty reads or non-repeatable reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36d9cc10-6d9c-4fea-94e9-accc7b794a7d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to test your changes, even if you are confident they are correct?', N'Junior', N'Even small changes can have unintended side effects in complex systems. Testing ensures that the new functionality works as expected and that existing features remain unaffected. It provides a safety net that gives the whole team confidence when deploying code to production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a5be20d-2dfc-48a9-9dab-acd036ea9180', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the main advantage of the ''Result'' pattern compared to traditional error handling?', N'Middle', N'The Result pattern turns errors into first-class citizens, allowing them to be passed around, stored, and transformed like any other value. This is especially powerful in functional programming chains and asynchronous flows where traditional try-catch blocks would be cumbersome.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b71e4b9c-92af-47e3-be60-acd4de43ba02', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain Vite''s approach to code-splitting and how it differs from Webpack''s manual chunking.', N'Senior', N'Vite leverages Rollup''s advanced heuristic-based code splitting by default, automatically creating shared chunks for common dependencies. While manual chunking is possible, Vite’s default configuration is generally optimized to reduce redundant code across application entry points.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
