INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22be428c-c10d-4249-aad3-acd9b3f3ecd2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you render lists in Svelte?', N'Intern', N'Svelte provides a dedicated loop syntax in its templates to iterate over arrays and render a block of HTML for each item. This ensures that the UI stays in sync if the underlying array is modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef3788d1-ef3d-4630-83b6-acda28bdffb4', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle schema-based serialization and its impact on performance?', N'Senior', N'Fastify uses JSON Schema to generate highly optimized serialization functions at startup. By compiling schemas into specialized code, Fastify skips the dynamic inspection of objects during response serialization, significantly reducing CPU cycles per request compared to standard JSON.stringify calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'485ffcde-299e-4649-a1a5-ace010167f8f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it generally recommended to avoid high-cardinality terms for aggregations?', N'Senior', N'High-cardinality fields require significant memory to build the global ordinals used for grouping and sorting, which can lead to significant heap usage. If the cardinality is too high, the aggregation may exceed memory limits or significantly degrade search performance due to the overhead of creating massive data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e794e6e-8e4d-4743-8402-ace1c1570881', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does the ''source()'' function do?', N'Junior', N'The ''source()'' function reads an external R script file and executes the code within it in the current R session. It is commonly used to load custom functions or data processing routines from separate files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'365a7177-9496-4f14-8a9d-ace3e2abae8e', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the implications of using Django''s signals versus explicit method overrides for business logic?', N'Senior', N'Signals decouple components, allowing for modularity, but they make the execution flow opaque, harder to debug, and prone to unintended side effects. Explicit method overrides like save() or clean() provide clearer visibility and better stack traces, making them preferable for core domain logic where execution order must be deterministic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
