INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cbf615f-3f4f-4840-ad70-acebccccdaeb', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the building blocks of HTML5?', N'Intern', N'* Semantics: allowing you to describe more precisely what your content is. * Connectivity: allowing you to communicate with the server in new and innovative ways. * Offline and storage: allowing webpages to store data on the client-side locally and operate offline more efficiently. * Multimedia: making video and audio first-class citizens in the Open Web. * 2D/3D graphics and effects: allowing a much more diverse range of presentation options. * Performance and integration: providing greater speed optimization and better usage of computer hardware. * Device access: allowing for the usage of various input and output devices. * Styling: letting authors write more sophisticated themes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69714297-1abf-47c7-802a-acf07bd810ea', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach error handling in a robust system?', N'Fresher', N'I approach error handling by anticipating potential failure points and implementing specific recovery logic for each case. It is important to provide meaningful error messages to the user while logging detailed information internally for debugging purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'324dc9e9-4b88-4d16-831a-acf3d764f7c7', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the performance impact of using the compat layer?', N'Middle', N'Using the compat layer adds a slight overhead to the bundle size and execution, as it acts as a translation layer. However, this is usually negligible compared to the total size savings achieved by using Preact as the base framework instead of React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb1e027b-baff-4c07-bfe5-acf40d8d7984', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you perform integration testing in an Actix application?', N'Middle', N'Integration testing is typically performed using the actix-rt test runtime, which allows you to spin up a local server instance or use a service factory. You then use a test client to send requests against the local server, verifying the responses and side effects in a real-world execution environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8154a1c5-7412-49a8-b1ad-acf43287fc26', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''Cache Stampede''?', N'Junior', N'A cache stampede occurs when a highly popular cached item expires, causing multiple concurrent requests to try and regenerate the data from the database simultaneously. This can overwhelm the primary database, and it is usually solved by implementing locking or recomputing the cache before it expires.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba1618db-e38a-40cf-ac62-acf56e88feac', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How does ''Parkinson''s Law''—the idea that work expands to fill the time available—affect your approach to estimation?', N'Fresher', N'It teaches me that setting loose deadlines can lead to procrastination or unnecessary gold-plating of tasks. I aim to estimate the actual effort needed for completion rather than just padding time, ensuring that the focus remains on delivering the necessary functionality efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f04c2b-eaf8-4402-99ab-acf666bd54fc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the function of the TypeScript compiler?', N'Intern', N'The TypeScript compiler, known as tsc, transforms TypeScript code into standard JavaScript that browsers or Node.js can execute. During this process, it also performs type checking to identify potential errors before the code is ever run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
