INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad575e9d-e675-4596-9913-acf8b5cef524', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the performance implications of not having a Virtual DOM?', N'Senior', N'By eliminating the Virtual DOM, SolidJS removes the overhead of reconciliation and diffing algorithms. This results in faster initial loads and lower memory consumption, as updates are surgically applied to the actual DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0512ace2-cfab-49e6-ab64-acf9197fbfd0', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the Swift ''Actor'' model ensure memory safety while preventing data races?', N'Senior', N'Actors protect their internal state by ensuring that only one task can access their mutable state at any given time. By enforcing strict isolation and requiring asynchronous access points, the compiler prevents data races at compile-time, though this introduces potential suspension points that require careful management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4fb9629-55a2-4858-8545-acfc0fc34bcf', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'When is it appropriate to use the @error or @warn directives?', N'Middle', N'@warn is useful for notifying developers about deprecated features or minor issues without stopping the compilation process. @error is used to halt compilation entirely when a condition is not met, such as passing an invalid value to a mixin, ensuring developers fix critical configuration mistakes immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'238f1c60-20db-4c96-b30b-acfc286e6abd', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a user reports that a website is loading very slowly, how would you begin troubleshooting?', N'Intern', N'I would start by checking if the issue is global or localized to the user by testing the site from different network locations. Then, I would inspect the network tab in browser developer tools to see if the delay is caused by large assets, slow server response times, or external third-party scripts. This helps narrow down whether the bottleneck is on the client side, the network, or the backend server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a675c36-30f5-47f4-a70d-acfd6aa9c768', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is NoSQL often considered schema-less?', N'Intern', N'NoSQL is called schema-less because it does not require a predefined structure for data before it is inserted. This allows developers to add new fields to documents or records on the fly without needing to perform administrative schema migration tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'930db244-641f-4b5e-a86e-acff9f6afba6', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s ''FastBoot'' feature enable Server-Side Rendering (SSR) in a framework designed for the browser?', N'Senior', N'FastBoot runs the Ember application in a Node.js environment, allowing the server to generate the HTML for a route before sending it to the client. This significantly improves perceived performance and SEO by reducing the time to first meaningful paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0fa2eeb-d844-4745-9323-ad03d968f3c2', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the ''Phantom Read'' anomaly and how do isolation levels mitigate it?', N'Senior', N'A phantom read occurs when a transaction executes a query twice and sees new rows added by another concurrent transaction. This is prevented by higher isolation levels like Serializable, which typically use range locks or predicate locks to ensure that the set of rows returned by a query remains constant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0baa837d-d63d-4489-8e1b-ad08fa3b3b5b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket optimize for binary size and performance in production builds?', N'Senior', N'Rocket leverages Rust''s aggressive compile-time optimization and monomorphization. By generating specialized code for every route and guard type at compile-time, it removes the need for bulky runtime dynamic dispatch, resulting in a smaller and faster executable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62b459e2-d776-47bf-93e8-ad09c3d63712', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP Generator architectural pattern impact memory efficiency compared to returning large arrays?', N'Senior', N'Generators implement coroutines that yield values one at a time, keeping only the current state in memory. Returning large arrays forces the entire dataset into memory at once, which can easily lead to memory exhaustion when processing large streams or datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e97b0ff0-2604-4d2f-bce2-ad0a5d63b5a3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure your work is secure when handling user data?', N'Junior', N'I would never store sensitive data like passwords or tokens in plain text and ensure that any user input is properly validated to prevent common attacks like injection. I would also follow the principle of least privilege, ensuring that only necessary services have access to specific data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9fd1cfe-dfea-46a5-901c-ad0c431d668e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between ''inline-source-map'' and ''eval-source-map''?', N'Middle', N'Inline-source-map embeds the source map directly into the bundle as a data URL, which is convenient for development but increases bundle size significantly. Eval-source-map uses eval functions to handle source maps, which is generally faster for rebuilds in development but is not suitable for production use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72480149-7a87-4b7d-8e7b-ad0c64c6d285', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do NestJS ''Filters'' provide an advantage over traditional try-catch blocks in route handlers?', N'Senior', N'Filters centralize exception handling, allowing you to map specific error types to HTTP status codes and response bodies in one location. This removes the need for repetitive try-catch blocks in every controller, ensuring consistent error messaging and status reporting across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d838f3d-a96a-4d4d-97cc-ad0c98305473', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between shallow and deep cloning objects, and why does it matter for performance?', N'Middle', N'Shallow cloning copies only the top-level properties, while deep cloning recursively copies all nested objects, which is much more memory and CPU intensive. In performance-critical applications, unnecessary deep cloning can lead to significant overhead and increased garbage collection pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7bba488-ab54-4feb-8cc0-ad0e6f56eec5', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is a Controller in the MVC architecture of AdonisJS?', N'Intern', N'A controller is a class that handles the incoming request logic and returns a response. It typically acts as the intermediary between the model, which manages data, and the view, which displays the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f47e4213-42c7-4b8c-923b-ad0fc58ad501', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the difference between Alpine''s ''x-data'' scope and the global ''$store''.', N'Senior', N'x-data defines local, private state for a specific component instance, ensuring encapsulation. The $store provides a mechanism for sharing state across components globally, acting as a singleton that any Alpine component can access, which is useful for shared UI themes or authentication status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da0310fc-0146-4925-9894-ad1434171812', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP support cookies?', N'Fresher', N'Cookies are HTTP headers that help websites remember users. In PHP, you can achieve seamless cookie management using built-in functions. PHP Functions for Cookie Handling - setcookie: Creates a new cookie or modifies an existing one. - \$_COOKIE: A global associative array that holds all set cookies, accessible from any script. - \$_COOKIE[ ''cookieName'' ]: Particularly useful for reading cookie values. - Example of Setcookie: Take a look! Common Cookie Parameters - Name: The cookie''s unique identifier. - Value: Data associated with the cookie. - Expiration: Time when the cookie should expire. - Path: The directory for which the cookie is valid. - Domain: The domain for which the cookie is valid. - Secure: Specifies if the cookie should be sent only over secure (HTTPS) connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fbf5f2d-ffe7-41d2-8c39-ad19404c4dc7', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit approach form validation?', N'Junior', N'SvelteKit encourages performing validation inside the form action on the server. You can validate the data, and if it fails, return the error messages back to the page to display them to the user, maintaining sync between client and server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e92a95f-0130-4343-8f92-ad197a1075e7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the role of the Fiber architecture in enabling concurrent rendering in React?', N'Senior', N'Fiber is a reimplementation of the reconciliation engine that allows React to break the work of rendering into incremental units. By prioritizing and pausing rendering tasks, React ensures the UI remains responsive even during complex state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9b21c80-ebdd-4860-8338-ad1bbebe7d7d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is the Paxos or Raft consensus algorithm often preferred over 2PC in modern distributed databases?', N'Senior', N'2PC is a blocking protocol that suffers from a single point of failure if the coordinator crashes, leading to potential system-wide unavailability. Consensus algorithms like Raft or Paxos allow for progress as long as a majority of nodes are functional, providing better fault tolerance and availability in distributed environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'828c8d67-e1da-4bbc-81d3-ad1e6672b05f', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Discuss the challenges of managing authentication in a distributed Next.js environment.', N'Senior', N'The primary challenge is synchronizing session state across the client and server while ensuring tokens remain secure. This usually requires a combination of secure HTTP-only cookies and middleware to verify authentication status before rendering sensitive pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bbe0a4e-e531-42ea-8374-ad1f0d0b6b22', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the benefits of using a Process Manager like PM2 in production?', N'Middle', N'A process manager handles application restarts, log management, and load balancing across cores automatically. It ensures high availability by monitoring the process and restarting it if it crashes, while also providing tools to manage environment variables and zero-downtime deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a17d06b-40ee-4561-a6b4-ad20dc4138c3', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Are Sass comments kept in the compiled CSS?', N'Intern', N'Sass supports two types of comments: standard CSS comments that are kept in the output, and single-line comments that are stripped out during compilation. Using the single-line style is great for internal documentation that doesn''t need to be seen by the public.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae23f56-3171-49fa-b5eb-ad21440bf1c7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are React Mixins?', N'Intern', N'_Mixins_ are a way to totally separate components to have a common functionality. Mixins should not be used and can be replaced with _higher-order components_ or _decorators_. One of the most commonly used mixins is PureRenderMixin. You might be using it in some components to prevent unnecessary re-renders when the props and state are shallowly equal to the previous props and state:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd12d32d-218c-4aee-9195-ad240d45ddc7', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''register'' function in Fastify?', N'Intern', N'The register function is used to load plugins into your Fastify application. It ensures that the plugin is properly initialized within the application''s lifecycle and, if necessary, waits for the plugin to complete its setup before moving on to the next part of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d9591ae-a469-4cf6-8aab-ad2aa9230bf4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain how Svelte''s compiler handles prop reactivity and the trade-offs of its syntax.', N'Senior', N'Svelte treats props as reactive variables that are updated by the parent component. While this syntax is concise, it requires the compiler to track these updates strictly, which can sometimes lead to complexity when dealing with deeply nested objects that require manual immutable reassignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bd577c6-e4e3-48d9-88ed-ad2de041d858', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain how DynamoDB maintains high availability across AWS Regions.', N'Senior', N'DynamoDB Global Tables use multi-region, multi-active replication to provide high availability and local read/write latency. It utilizes a conflict-resolution policy, typically ''last writer wins'', to synchronize changes across regions asynchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'807c0a75-4ec0-4ed0-8277-ad2f279333e8', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular handle Content Projection, and what are the performance implications of using ''ng-content''?', N'Senior', N'Content projection allows components to act as wrappers for external markup, which promotes component reusability. While performant, deep nesting of projected content can lead to complex change detection paths, as the parent component must still manage the lifecycle of projected nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9740cc86-5585-4cd6-a097-ad31a21ac02f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''path parameter'' in FastAPI?', N'Intern', N'Path parameters are segments of the URL path that act as variables to identify a specific resource. They are defined in the route path using curly braces and are automatically injected into the function arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1806ddd3-c2fe-440d-84bf-ad335e86d695', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the role of the Data Protection API and how it handles key management in distributed environments.', N'Senior', N'The Data Protection API provides a secure way to encrypt and sign sensitive data like cookies or anti-forgery tokens. In distributed environments, it supports key persistence to shared storage like Redis or Azure Key Vault, ensuring that all application instances can decrypt data protected by other instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'712a5789-91ed-4f7e-b1e5-ad33d99d44b1', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the role of the ''defer'' keyword in terms of stack frame management and performance.', N'Senior', N'Defer pushes a function call onto a list that is executed when the surrounding function returns, which involves a slight performance cost due to the registration of the deferred function. Recent compiler optimizations have integrated defer into the function stack frame, significantly reducing this overhead by avoiding heap allocation for the defer structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1323c058-ef46-4351-821e-ad36f65b8b55', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is indexing a double-edged sword for database design?', N'Middle', N'While indexes significantly speed up read operations, they also impose a performance penalty on write operations. Every insert, update, or delete requires the database to update the associated index structures, leading to increased storage overhead and maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a9f1798-f187-4f65-b4a6-ad3935c6302c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between ''extends'' and ''implements'' in Dart?', N'Junior', N'The ''extends'' keyword is used for class inheritance, where a subclass inherits behavior and state from a single parent class. The ''implements'' keyword is used to conform to an interface, requiring the class to provide its own implementation for all methods defined in the interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07976307-dca9-44cc-a84a-ad3bf3fb0045', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the benefits of using ''Doctrine Query Builder'' over DQL (Doctrine Query Language) strings?', N'Senior', N'The Query Builder provides a programmatic, object-oriented way to construct queries, which is less error-prone than manually concatenating strings. It allows for dynamic query construction based on runtime conditions, improving readability and maintainability of complex search or filtering logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a055459-cdb0-4549-8bab-ad3e73e49da4', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the difference between a TTL index and a regular index.', N'Middle', N'A TTL (Time-To-Live) index automatically removes documents from a collection after a certain amount of time or at a specific clock time. A regular index is used solely for optimizing query performance and does not affect the lifecycle of the documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e9850bf-ebfb-4a63-80b1-ad416545e220', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the security implications of failing to validate the anti-forgery tokens in a state-changing request?', N'Senior', N'Failing to validate anti-forgery tokens leaves the application vulnerable to Cross-Site Request Forgery attacks, where an attacker tricks a logged-in user into performing unwanted actions. These tokens ensure that the request originated from a trusted source, effectively mitigating the risk of unauthorized state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccd24274-adb3-4055-a798-ad44f970ffab', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the ''package.json'' file in an Express project?', N'Intern', N'The package.json file serves as the manifest for a Node.js project, listing the project''s metadata and its dependencies. It allows Express to manage installed libraries and define scripts to easily start or test the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eba4bf4-fd68-4c40-8956-ad46f520a2cd', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain how an SAGA pattern manages transactions in microservices.', N'Middle', N'A Saga manages distributed transactions by breaking them into a sequence of local transactions, each updating a single service''s database. If a step fails, the Saga executes a series of compensating transactions to undo the changes made by preceding steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc852089-692a-48bf-8096-ad49eb024234', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you justify spending time on refactoring a stable but ''messy'' codebase to leadership?', N'Middle', N'I would quantify the impact of the current state by showing increased bug rates, slower feature delivery cycles, or higher infrastructure costs related to the code. By framing refactoring as a ''feature for developer productivity'' that reduces long-term delivery risk, I can align technical quality with business goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e19c936b-4e2d-466c-b169-ad4ad378519c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is it important to keep the bundle size small in Next.js?', N'Middle', N'A smaller bundle size results in faster page loads, better performance on mobile devices, and improved SEO rankings. By utilizing Server Components and code splitting, Next.js minimizes the amount of JavaScript the client needs to download and execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b39f7793-c22b-4a08-aad3-ad4b03589adb', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'You suspect a memory leak in a production microservice. What strategy would you use to confirm it and identify the responsible component?', N'Middle', N'First, I would verify the leak by observing a monotonic increase in heap usage over time despite garbage collection cycles in monitoring dashboards. To identify the cause, I would trigger a heap dump at two distinct time intervals and perform a differential analysis to see which object types are growing in count or size. This approach helps pinpoint whether the leak stems from unclosed resources like file handles or static collections that are accumulating data without being cleared.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41071155-11b7-44b7-aa9e-ad4bb1dcf85b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''contain-intrinsic-size'' property when used in conjunction with ''content-visibility''?', N'Senior', N'When an element is hidden via content-visibility, its rendered size is effectively zero, which can cause layout shifts when the content is finally rendered. The contain-intrinsic-size property provides an estimated size for the element, allowing the browser to reserve space in the layout and maintain scrollbar stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1c2f603-d466-4ce9-9985-ad4e68318eb6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What criteria do you use to decide if a third-party service or library is suitable for a production system?', N'Middle', N'I evaluate the project''s maintenance status, community support, security history, and the complexity of its integration. I also consider the ''vendor lock-in'' risk and whether the service provides a critical business value that outweighs the cost of maintaining a custom solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'438d1c33-1d7d-47c4-9bab-ad4eea0d68bd', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary goal of Qwik''s ''Instant-on'' feature?', N'Fresher', N'The primary goal is to provide a seamless user experience where the page feels fast and ready to use the moment it loads. By prioritizing content visibility and deferring non-essential JavaScript, Qwik ensures the UI is responsive immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d109a41-5a70-4a03-b6ab-ad4f135cfedf', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage logging?', N'Junior', N'Quarkus uses the JBoss Logging framework, which is highly configurable and supports various output formats. It can be easily configured via the application properties file to control log levels, formats, and destinations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30ed42b7-6eca-4a36-937a-ad4f44ee5c6b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is middleware in Actix-web?', N'Intern', N'Middleware is a layer that sits between the incoming request and the final handler. It can be used to perform tasks like logging, authentication, or modifying requests and responses as they pass through the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c58dd0cb-f78f-4508-ae2c-ad4ffc0f161e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do Lit''s ''PropertyOptions'' like ''attribute'', ''converter'', and ''hasChanged'' affect reactivity?', N'Senior', N'These options allow fine-grained control over how properties are synced with DOM attributes and when an update should be triggered. They are essential for integrating Lit components with external data sources or non-standard attribute formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97b1cb2b-f1c2-4a1f-ab2b-ad504a995d5a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between an array and a linked list?', N'Fresher', N'An array is a fixed-size data structure stored in contiguous memory locations, allowing fast access by index. A linked list consists of nodes distributed in memory, allowing for dynamic resizing but requiring sequential traversal to access elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32c6b59c-1af5-460a-8ab9-ad522a7efa78', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it impossible to maximize every quality attribute simultaneously?', N'Fresher', N'Resources like time, budget, and developer effort are finite, and some quality attributes are inherently contradictory. For example, increasing security often requires additional authentication steps, which negatively impacts user experience and speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d9ac144-5392-4ed8-9bba-ad54adb8a737', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Can you define multiple handlers for the same path with different HTTP methods?', N'Fresher', N'Yes, Axum allows you to define different handlers for GET, POST, PUT, DELETE, and other HTTP methods on the same route. The router will automatically dispatch the request to the correct handler based on the method used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddadf063-f618-4bc4-8987-ad5c2a862527', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How would you handle global state or shared services in a Hono application while maintaining testability?', N'Senior', N'Shared services should be injected into the context via custom middleware or a dependency injection container during the application initialization phase. By treating the environment and services as dependencies rather than globals, you can easily mock these services during unit testing to ensure the application logic remains isolated and verifiable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ca0a94f-66e1-4041-9bd1-ad5ebaf97ebc', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the trade-offs of using Lit over a Virtual DOM-based framework like React?', N'Middle', N'Lit relies on native browser features like Shadow DOM and template literals, resulting in a much smaller bundle size and faster initialization. However, it lacks a built-in virtual DOM diffing engine, which means developers must be more mindful of how they structure their templates for optimal performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8e3a8e6-d88d-4c6f-8059-ad5ed4a442f1', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is meant by the ''composable'' nature of the Chi router?', N'Fresher', N'Being composable means that Chi allows you to build complex routing structures by nesting sub-routers or groups. You can define specific middleware or URL prefixes for a subset of your application endpoints, which makes the code more modular and easier to maintain as the number of routes grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18437bcd-2ad9-4efa-a9a5-ad647e1f351a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When would you prefer a document-oriented NoSQL database over a relational database?', N'Middle', N'A document database is preferred when the data model is hierarchical, deeply nested, or highly polymorphic with rapidly evolving schemas. It offers better horizontal scalability for read-heavy workloads where strict ACID compliance across multiple tables is not the primary requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'680a67b2-551f-43ad-841c-ad6569f86f63', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Explain the concept of ''Serialization'' in the context of Qwik.', N'Middle', N'Serialization is the process of converting the component state and function references into a JSON-like format stored directly in the HTML. This allows the client to reconstruct the application''s state without needing to re-run the server-side initialization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db575c12-5211-45aa-848b-ad692e1136b9', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary purpose of middleware in Echo?', N'Intern', N'Middleware in Echo is a function that executes before or after the main handler of a request. It is used to perform common tasks such as logging, authentication, recovering from panics, and modifying request or response objects globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cef3067-45e8-4577-9ac1-ad716aa74e09', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the problems with postmessage target origin as wildcard', N'Intern', N'The second argument of postMessage method specifies which origin is allowed to receive the message. If you use the wildcard “\*” as an argument then any origin is allowed to receive the message. In this case, there is no way for the sender window to know if the target window is at the target origin when sending the message. If the target window has been navigated to another origin, the other origin would receive the data. Hence, this may lead to XSS vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1281d2a4-19f9-476e-9bc3-ad76f5cb30fc', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of middleware in FastAPI?', N'Fresher', N'Middleware is a function that runs before every request is processed and after every response is generated. It is commonly used for tasks like logging, adding custom headers, or handling cross-origin resource sharing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11d7d0c8-4cb1-4e58-b87e-ad7850df49cd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you decide between building a custom internal tool versus buying a commercial solution?', N'Middle', N'If the problem is core to our competitive advantage, building is often better to ensure custom features and ownership. If the problem is a commodity (like billing or authentication), buying is usually more cost-effective because it allows the team to focus on features that actually differentiate the product.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e61064b7-34eb-42b8-822f-ad7a6d34409a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the .vite folder?', N'Fresher', N'The .vite folder is a cache directory created by Vite. It stores the pre-bundled dependencies to improve subsequent startup times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6363a43c-1106-4c6e-a08f-ad7cbdf04bf2', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the .attr() method used for?', N'Intern', N'The .attr() method is used to get or set the value of specific HTML attributes on an element, such as ''src'', ''href'', or ''id''. It provides a convenient way to manipulate element properties that are not CSS-related.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73cb8677-dea3-470d-b211-ad7dc4ff1962', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you find a security vulnerability, what is your immediate course of action?', N'Junior', N'I would stop my current work and report the vulnerability to my lead or the security team immediately, following the company''s disclosure protocol. I would not share the details of the vulnerability in public channels and would focus on assisting with the remediation as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51443da2-6b89-4400-90a4-ad7e24a4f0d9', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is meta-programming in Ruby?', N'Intern', N'Meta-programming is the practice of writing code that writes or modifies other code during runtime. Ruby''s dynamic nature allows developers to define methods, classes, and behaviors on the fly, making the language highly flexible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cdbf554-1f50-4c41-bd22-ad7eb900df44', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is eval function in javascript?', N'Intern', N'The eval() function evaluates JavaScript code represented as a string. The string can be a JavaScript expression, variable, statement, or sequence of statements. If the argument of eval() is not a string, eval() returns the argument unchanged. In the following example, the String constructor is specified and eval() returns a String object rather than evaluating the string. Warning: *Executing JavaScript from a string is an enormous security risk. It is far too easy for a bad actor to run arbitrary code when you use eval().* &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdeacb21-ae35-439a-854a-ad804795e63b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is Tail Recursion?', N'Intern', N'Tail recursion is a specific form of recursion where the recursive call is the final action performed by the function. Scala can optimize these calls to prevent stack overflow errors, effectively turning the recursion into a loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ee1abe2-1e1d-4331-9987-ad809bd0c4b1', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the performance implications of using select_related versus prefetch_related in Django.', N'Senior', N'select_related performs a SQL JOIN to retrieve related objects in a single query, which is efficient for single-valued relationships like ForeignKey or OneToOne. prefetch_related performs separate lookups and joins them in Python, which is necessary for multi-valued relationships like ManyToMany or reverse foreign keys to avoid the N+1 query problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'211ee25f-6e22-48c4-a527-ad809cb1372f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the ''bind:'' directive used for?', N'Junior', N'The ''bind:'' directive creates a two-way data binding between a component variable and an HTML form element. This means that if the user changes the input value, the variable updates, and if the variable changes programmatically, the input value updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db1c82d2-0381-452d-b12a-ad80f4250b6b', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt 3 handle state synchronization between the server and client during hydration?', N'Senior', N'Nuxt uses a payload serialization mechanism where the state defined in composables like useAsyncData is serialized into the HTML document. During hydration, the client-side app retrieves this payload to initialize its state, ensuring the DOM matches the server-rendered output and preventing hydration mismatches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e147a55c-3855-433c-b65a-ad81a68e3fb5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why might you use a ''Write Sharding'' strategy in DynamoDB?', N'Middle', N'Write sharding involves appending a random suffix to the partition key to distribute write traffic across multiple partitions. This is a common technique to mitigate write hotspots when a single partition key is subject to extremely high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b03eefe-24c8-4ee2-a9e2-ad8211a9e419', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the different component’s lifecycle hooks?', N'Fresher', N'Angular components have a lifecycle managed by Angular itself. As the component is created, updated, and destroyed, Angular calls specific methods on the component class at predefined moments. These methods are called lifecycle hooks. The most common hooks, in their typical execution order, are: - ngOnChanges: Called when input properties change - ngOnInit: Called once after the component is initialized and its inputs are set - ngDoCheck: Called during every change detection run - ngAfterContentInit: Called after content projected into the component''s view is initialized - ngAfterContentChecked: Called after the projected content has been checked - ngAfterViewInit: Called after the component''s view and its child views are initialized - ngAfterViewChecked: Called after the component''s view...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11aacdf7-398a-41d2-bef3-ad826b86c157', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is same-origin policy', N'Intern', N'The same-origin policy is a policy that prevents JavaScript from making requests across domain boundaries. An origin is defined as a combination of URI scheme, hostname, and port number. If you enable this policy then it prevents a malicious script on one page from obtaining access to sensitive data on another web page using Document Object Model(DOM).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38e67013-541d-4755-bfbe-ad82db7e9e04', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is specificity in CSS?', N'Intern', N'Specificity is a weight calculation used by browsers to decide which CSS rule applies when multiple rules target the same element. More specific selectors, such as IDs, have higher priority than generic selectors like tags or classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1ff6d2e-3565-4721-a397-ad862e04a1cb', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the impact of return value optimization (RVO) and copy elision on performance?', N'Senior', N'RVO and copy elision allow the compiler to construct objects directly in the target memory location, bypassing unnecessary copy or move operations. This is a critical optimization that minimizes object creation overhead and memory bandwidth usage, especially when returning large objects from functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f96d56f4-9b3b-4321-89e3-ad86385696fa', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do environments in R act as hash maps for symbol lookup?', N'Senior', N'Environments are internally implemented as hash tables that map symbol names to memory addresses. This design allows for O(1) average time complexity for variable lookups, which is a critical architectural feature supporting R''s dynamic nature and runtime scope resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8272f09-8138-48dd-bdb9-ad92037fdde9', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between an ''optional'' and a ''result'' type for handling failure?', N'Middle', N'Optionals are used to represent the presence or absence of a value, which is useful for simple success or failure. The Result type provides more context by containing either a success value or a specific error object, making it better for complex operations where the reason for failure is important.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c237b8b9-8173-4b4b-8131-ad931c4c0746', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s type system handle ''conditional conformance''?', N'Senior', N'Conditional conformance allows a generic type to conform to a protocol only if its underlying generic arguments also conform to that same protocol. This enables powerful extensions that provide additional functionality to collections like arrays only when their elements support specific operations. It maintains type safety while maximizing code reuse in complex generic architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d0e9725-77d1-4f5d-9a96-ad97941627fa', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why are top-level functions in Dart preferred for certain utilities?', N'Middle', N'Top-level functions are easy to test and do not maintain state, making them perfect for pure utility operations. Because they are not tied to an instance, they avoid unnecessary object creation and reduce the memory footprint of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb28f2fb-937b-4883-a1ae-ad99eeeee0a5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the advantage of using Phoenix over traditional frameworks?', N'Intern', N'Phoenix provides high performance and scalability by leveraging Elixir''s concurrency model. It is particularly well-suited for real-time applications and systems that require high availability and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a0f8618-a656-4eb0-a68a-ad9ae5f2fb26', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the primary differences between Server-Side Rendering (SSR) and Static Site Generation (SSG) in Next.js, and when would you choose one over the other?', N'Middle', N'SSG pre-renders pages at build time, resulting in extremely fast load times and minimal server load, making it ideal for content that doesn''t change often. SSR generates pages on each request, which is necessary for dynamic data that must be fresh for every user. You should choose SSG for marketing pages or documentation and SSR for personalized dashboards or data-heavy views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'423993c7-2414-43b8-81d9-ad9b240aa883', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle configuration files?', N'Junior', N'AdonisJS uses a dedicated config directory where you define settings for various services like database, auth, or mail. These settings are accessed through a unified config helper, which ensures all settings are loaded and validated at application startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9316bd3a-02fd-4383-adf1-ad9c11196700', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''tsconfig.json'' file?', N'Intern', N'The tsconfig.json file serves as the configuration file for a TypeScript project. It specifies the root files and the compiler options required to control how the TypeScript compiler processes the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c86a6d58-e3dd-4f87-b851-ad9c93af8d10', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s method lookup path (ancestors chain) function when modules are included in a class?', N'Middle', N'When a module is included, Ruby inserts it into the inheritance chain immediately above the class that included it. If multiple modules are included, they are added in reverse order of inclusion, placing the most recently included module at the front of the lookup path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'134ab98f-fdaa-4138-9e32-ad9f38a5ef42', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the currying function', N'Intern', N'Currying is the process of transforming a function with multiple arguments into a sequence of nested functions, each accepting only one argument at a time. This concept is named after mathematician Haskell Curry, and is commonly used in functional programming to enhance modularity and reuse. Before Currying (Normal n-ary Function) This is a standard function that takes three arguments at once. After Currying (Unary Function Chain) Each function in the chain accepts one argument and returns the next function, until all arguments are provided and the final result is computed. Benefits of Currying - Improves code reusability → You can partially apply functions with known arguments. - Enhances functional composition → Easier to compose small, pure functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22c989d9-07c1-4134-9765-ada0415e6ca0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the use of jQuery''s global $ object generally discouraged in modern modular JavaScript?', N'Middle', N'The global $ object relies on the window scope, which makes dependency management difficult and prevents the use of modern module bundlers like Webpack or Vite. It also makes unit testing harder, as it requires mocking global state rather than importing dependencies explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbb513a6-2f94-4f46-88a7-ada1fcaef2c4', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between synchronous and asynchronous code?', N'Junior', N'Synchronous code executes tasks one after another, blocking the thread until each task completes. Asynchronous code initiates a task and continues execution immediately, allowing the system to handle other work while waiting for the task to finish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cefd9ff8-e093-4d13-9f08-adaaa4cd6bd7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between NumPy and SciPy?', N'Fresher', N'In an ideal world, NumPy would contain nothing but the array data type and the most basic operations: indexing, sorting, reshaping, basic element wise functions, et cetera. All numerical code would reside in SciPy. However, one of NumPy''s important goals is compatibility, so NumPy tries to retain all features supported by either of its predecessors. Thus NumPy contains some linear algebra functions, even though these more properly belong in SciPy. In any case, SciPy contains more fully-featured versions of the linear algebra modules, as well as many other numerical algorithms. If you are doing scientific computing with python, you should probably install both NumPy and SciPy. Most new features belong in SciPy rather than NumPy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e563bd1-de15-4d73-8dc2-adab0e7c06e0', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the significance of the ''Events'' system in AdonisJS?', N'Middle', N'The Events system allows for decoupling of side-effect operations from the main request-response cycle by using an emitter pattern. This is particularly useful for tasks like sending emails or notifying other services, as these can be handled asynchronously, improving response latency for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4d6ed36-39cb-4e03-b5b3-adac0c8b1cf2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a system failure where data integrity might have been compromised?', N'Middle', N'I prioritize isolating the affected component to prevent further corruption and then assess the extent of the damage using audit logs and backups. Once the scope is identified, I develop a remediation plan that involves either reconciling the state via idempotent operations or restoring from a known-good backup. I conclude with a post-mortem to identify how to prevent the failure from occurring again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42ce131f-e854-494f-8806-adada4bd2e03', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are utility types and can you name a few?', N'Middle', N'Utility types are built-in helpers that facilitate common type transformations. Examples include ''Partial'' to make properties optional, ''Pick'' to select specific properties, and ''Readonly'' to make properties immutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3b4294-7447-4d20-8a2a-adb619d57da0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the difference between ''at-most-once'' and ''at-least-once'' delivery in Redis Streams.', N'Senior', N'At-most-once delivery occurs when a consumer reads a message without acknowledgment, risking loss if the consumer crashes. At-least-once is achieved using the XREADGROUP command combined with PEL, where messages remain in a pending state until explicitly acknowledged by the consumer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59cd5635-0e08-4c50-91fe-adb72bae2b4b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between late static binding and standard static binding in PHP?', N'Middle', N'Standard static binding resolves static calls at compile-time to the class where the method is defined. Late static binding uses the ''static'' keyword to defer the resolution of a class reference to the runtime context of the calling class, allowing for better inheritance patterns in static methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09dc36ac-a06c-4cb5-bea8-adbbc9c3ee07', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a race condition in the context of Go concurrency, and how is it mitigated?', N'Middle', N'A race condition occurs when multiple goroutines access shared memory concurrently and at least one access is a write. Go provides the built-in race detector tool during testing and encourages the use of channels or sync primitives like Mutexes to synchronize access to shared data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'052a46a2-3b17-41f8-bc66-adbdce5e8e60', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber support HTTPS?', N'Intern', N'Yes, Fiber supports HTTPS by allowing developers to provide SSL/TLS certificate and key files when starting the server. This ensures that the communication between the client and the server is encrypted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4050235-6385-4de8-8ebd-adbdeaea8c2b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How can you implement cross-service logging in a microservices environment?', N'Middle', N'Cross-service logging requires a centralized logging stack where all services push their logs to a common storage and analysis platform. Using structured logging formats and including correlation IDs in every log entry allows developers to reconstruct the sequence of events across services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffdc3ec1-627d-4da0-907a-adbe3d58e329', N'075b8862-431c-4678-9767-f55359758a4a', N'Why should you use Pinia over the legacy Vuex?', N'Middle', N'Pinia offers a more intuitive API, better TypeScript support, and a modular architecture by default. It eliminates the need for mutations, simplifies the store structure, and provides a lighter footprint compared to the centralized Vuex pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1279692-f5e6-429d-b465-adc1957581a3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember’s Glimmer VM improve rendering performance compared to traditional Virtual DOM implementations?', N'Senior', N'The Glimmer VM compiles templates into bytecode that operates on a low-level register-based machine. By creating a linearized instruction stream, it minimizes the overhead of object creation and diffing, allowing for faster updates by directly updating specific memory locations rather than re-traversing a full tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48b51820-e8a7-4c53-b8bb-adc3f8c1cd89', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the payload property in a Redux action?', N'Junior', N'The payload is a conventional property name used to carry the data needed for the state update. While not strictly required by Redux, it is a standard practice to keep the data separate from the action type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
