INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aad226ea-f695-4653-b46f-adc877c87864', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does it mean for a closure to capture by move, reference, or mutable reference?', N'Middle', N'These capture modes define how a closure interacts with its environment''s variables. Capturing by move transfers ownership, capturing by reference allows reading without taking ownership, and capturing by mutable reference allows modifying the environment variables directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
