INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52b4d769-085b-4624-826c-add221c19a17', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What does ''encapsulation'' mean in the context of Fastify plugins?', N'Intern', N'Encapsulation means that plugins are scoped to their own context, preventing side effects from leaking into other parts of the application. Changes made to the Fastify instance within a plugin, such as adding a decorator, are only visible to that plugin and its descendants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9278ec4a-81d1-4716-bff1-add4448850f9', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the benefits of using a database index?', N'Middle', N'An index is a data structure that improves the speed of data retrieval operations on a database table at the cost of slower writes and additional storage space. By providing a faster lookup path, it significantly reduces the time required to execute complex queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16862335-11c7-4ee6-800e-add9c0dbd794', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono differ from Express.js?', N'Fresher', N'While Express.js is designed specifically for Node.js, Hono is built on Web Standards. Hono is significantly smaller in bundle size and is optimized for serverless and edge environments, whereas Express is more traditional and monolithic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'682a0552-c9ef-4a8e-87bd-adde90497b03', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of Flask Blueprints?', N'Junior', N'Blueprints are used to organize an application into smaller, reusable modules or components. They allow developers to group related routes, templates, and static files, which makes the codebase easier to manage as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b693b53-52d6-4b73-b9fe-addee64ced2b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If an application is experiencing high latency, how do you determine if the issue is in the database or the application layer?', N'Middle', N'I would check the application''s request logs to see the time spent in the database driver versus the processing time. If the database query execution time is high, I would analyze the slow query logs and check for missing indexes or table locks. If the database is fast but the application is slow, I would look for thread contention, blocking I/O operations, or external API call latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4609d95c-bf2d-43c6-b6b3-ade4ca394e54', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between a Quarkus extension and a standard library?', N'Fresher', N'A standard library is just a JAR dependency, while a Quarkus extension includes build-time integration logic. This logic allows the framework to optimize the library specifically for Quarkus and ensures it works correctly in native mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40c5cbc3-65e8-4e64-baa0-ade7dcef7a39', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the advantage of Chi''s ''composable'' nature?', N'Fresher', N'Composability means you can easily nest routers within other routers. This allows for modular code organization, where different parts of an application can manage their own routing logic independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'733c6734-1226-46bc-8ef6-ade8f3b920e5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can you define custom colors in Tailwind?', N'Fresher', N'Yes, you can extend the default theme in the tailwind.config.js file to include your own brand colors. Once defined, these colors become available as utility classes, such as bg-brand-500 or text-brand-primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7eabc3e-9285-462e-8c6a-ade996e65213', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are the trade-offs of using native compilation in a production Quarkus environment?', N'Senior', N'Native compilation significantly improves cold starts and memory usage, but it increases build times dramatically and requires specific OS-level compilation environments. Additionally, dynamic features like reflection, proxies, and JNI must be explicitly configured or registered, which can complicate the migration of legacy codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd087124c-b55c-40e3-860c-adebd905bc34', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What does it mean for a router to be ''idiomatic'' in Go?', N'Fresher', N'Being idiomatic means the library follows the established patterns, conventions, and style guidelines common to the Go language community. For Chi, this means working seamlessly with the standard http.Handler interface rather than introducing proprietary abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a8c7d77-3a59-44d7-ac4e-adee282d7bfd', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the benefit of SvelteKit''s component-based error handling.', N'Senior', N'By using ''error.svelte'' files, developers can define hierarchical error boundaries that catch failures at specific route levels. This prevents a single failing component or data fetch from crashing the entire application, allowing for graceful degradation and better user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43d128cb-cb17-4731-bfdd-adeea2a41192', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What happens during the Sass compilation process?', N'Intern', N'During compilation, the Sass preprocessor parses your .scss files and executes all variables, mixins, and functions. It then flattens the nested structures and outputs a standard .css file that the browser can understand and render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96673fc4-c474-4664-8f67-adeead70cc61', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is ''Single Table Design'' often recommended, and what are its drawbacks?', N'Senior', N'Single Table Design consolidates multiple entity types into one table to optimize for specific access patterns and reduce cross-table joins. The drawback is that it requires rigorous schema planning, becomes difficult to manage as access patterns evolve, and leads to complex key structures that can be harder to query using traditional SQL-like logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1fc2ad1-3b55-4abd-93cb-adefa1bdd2b6', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''inherit'' keyword work in CSS?', N'Junior', N'The inherit keyword forces a property to take the same computed value as its parent element. This is useful for ensuring that child elements stay consistent with the styles applied to their containers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b7a2b9-1c15-45ae-8455-adf20b504f09', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'When should you choose Redis over a disk-based NoSQL database like MongoDB?', N'Middle', N'Redis is the ideal choice when sub-millisecond latency is the primary requirement and data sets fit within memory. If the application requires complex querying, secondary indexing, or needs to store datasets significantly larger than available RAM, a disk-based NoSQL database is more appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
