INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6632467-8ef8-43d2-9b93-ae0b1b145fe5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How can HTML ''forms'' be architected to handle complex client-side validation without sacrificing security?', N'Senior', N'Modern HTML5 form validation attributes provide a declarative layer for client-side checks, but they must always be paired with rigorous server-side validation to ensure data integrity. Relying solely on client-side constraints is a security vulnerability, as these can be easily bypassed by malicious actors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4f99a3c-8814-40a9-b687-ae10abefc6a6', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the primary differences between Vue''s ''Template Compiler'' and ''Render Functions''?', N'Senior', N'The template compiler parses HTML-like syntax into optimized render functions that include static hoisting and patch flags for faster execution. Render functions provide full programmatic control over the virtual DOM, which is useful for highly dynamic components, but they lack the compiler''s built-in performance optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
