INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a24a3ccd-d957-4a4f-985b-ae130a019a60', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the MVC pattern as implemented in Laravel?', N'Intern', N'MVC stands for Model-View-Controller, an architectural pattern that separates an application into three main components. The Model manages the data and business logic, the View handles the user interface and display, and the Controller acts as an intermediary that processes incoming requests and returns responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
