INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0b7b7f6-ef27-4be2-b8b5-ae478eecbf59', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a module in TypeScript?', N'Intern', N'A module is a file containing code that is executed in its own scope rather than the global scope. TypeScript uses modules to manage dependencies and organize code into smaller, reusable pieces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'128a13e3-8ab0-4b65-a3cc-ae4849768a9e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the impact of ''shimming'' modules in Webpack?', N'Senior', N'Shimming is used to polyfill or provide dependencies to legacy modules that expect global variables like jQuery or process. It is a necessary evil for integrating older libraries into a modern module-based architecture, but it can introduce implicit global dependencies that make code harder to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3566c873-de04-4667-9ec3-ae4a9fd2a893', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the benefits of using a Content Delivery Network (CDN) in a microservices architecture?', N'Senior', N'A CDN offloads static asset delivery and cached API responses to the edge of the network. This reduces latency for global users and lowers the load on backend microservices by shielding them from repetitive read-heavy traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'140fc77b-1883-4aa3-806e-ae4b8e613cd9', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of ''mix'' in the Phoenix ecosystem?', N'Middle', N'Mix is the build tool that handles project creation, dependency management, task execution, and testing. It provides a standardized interface for developers to manage the entire application lifecycle, from compiling code to running migrations and generating documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16aa255c-480b-462c-82b9-ae4ff5005cda', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Is Elasticsearch a relational database?', N'Intern', N'No, Elasticsearch is a NoSQL document-based search engine. It does not support joins, foreign keys, or ACID transactions in the same way traditional relational databases do.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5907df8b-efae-4569-a613-ae50ea71b8ba', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Is it possible to use async/await in plain React?', N'Middle', N'Yes, you can use async/await in plain React, as long as your JavaScript environment supports ES2017+. Nowadays most modern browsers and build tools support ES2017+ version. If you''re using Create React App, Next.js, Remix, or any modern React setup, async/await is supported out of the box through Babel. Example Usage But If you''re not using a bundler like Webpack or Babel, you will need _Babel_ and transform-async-to-generator plugin. However, React Native ships with Babel and a set of transforms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de93697a-6439-4b8c-895b-ae50f185e006', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do context managers interact with the exception handling system?', N'Senior', N'Context managers use the `__exit__` method, which receives information about any exception that occurred within the managed block. This allows the manager to suppress the exception or perform cleanup, ensuring system resources are released even when errors occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec58665d-424a-4a6e-9ea9-ae52837202a2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is it generally discouraged to use scan operations in production?', N'Middle', N'A scan operation iterates through every single item in the entire table, which is highly inefficient and expensive for large datasets. It consumes significant read capacity and can lead to performance degradation; queries should be used whenever possible by targeting indexed attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75cd6a4f-01d0-4440-a3e2-ae52dc7afc29', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Describe the difference between ''target: web'' and ''target: node'' in Webpack configuration.', N'Senior', N'The target determines how Webpack bundles code for a specific environment, affecting how built-in modules and globals are handled. ''Web'' targets assume browser globals, while ''Node'' targets assume environment-specific modules like ''fs'' or ''path'' and handle chunk loading differently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5c240cb-ddcc-4c69-98fe-ae531c89a880', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the primary differences between process.nextTick() and setImmediate() in terms of event loop phases?', N'Senior', N'process.nextTick() executes immediately after the current operation finishes, regardless of the event loop phase, essentially preempting the loop. setImmediate() schedules a task to run in the ''check'' phase of the event loop, allowing for fairer scheduling and preventing I/O starvation during recursive calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd683d1e3-2ed2-4a0e-be4d-ae566fc6cdb6', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the concept of ''Zone.js'' and its role in change detection.', N'Middle', N'Zone.js patches standard browser APIs like timers and XHR requests to create an execution context that tracks asynchronous activity. Angular uses this to know exactly when to trigger the change detection cycle, ensuring the view stays synchronized with the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaecd7bc-ac00-41da-b631-ae5988607644', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When managing secrets, what is the trade-off between convenience and security?', N'Junior', N'Hardcoding secrets or storing them in environment files is convenient for local development but poses a severe security risk. Using a dedicated secret management service is much more secure and allows for rotation and access auditing, but it adds an extra dependency and architectural complexity to the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ed944c7-3076-4182-87f1-ae5989e04430', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the role of the WHERE clause?', N'Fresher', N'The WHERE clause is used to filter records in a query. It specifies the criteria that rows must meet to be included in the result set returned by the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1703bdd-3719-44b9-bb6e-ae5d78dd35ff', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle memory management when components are removed from the DOM?', N'Senior', N'Alpine.js cleans up event listeners and internal state references when components are destroyed or removed from the DOM tree through its built-in lifecycle management. Because Alpine attaches state directly to DOM nodes, the garbage collector can reclaim memory once the element is detached and no longer referenced. This prevents memory leaks common in more complex frameworks that maintain external shadow state stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca5b9eff-7d11-439a-9bdb-ae5f6850661b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the architectural differences between logical and physical replication?', N'Senior', N'Physical replication copies the exact disk blocks from the primary to the standby, requiring identical database versions. Logical replication replicates data at the row level, allowing for cross-version migration and partial database replication between different instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a929949-c7c3-4e8a-b9dd-ae6396003e60', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum manage request timeouts?', N'Junior', N'Axum manages timeouts by using the ''Timeout'' middleware provided by the Tower library. This can be applied to the entire application or specific routes to ensure that requests do not hang indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2afeda26-ddca-4402-bdf1-ae6927cc8b02', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the security implications of using Express''s ''trust proxy'' setting in a cloud-native environment?', N'Senior', N'The trust proxy setting tells Express to trust the X-Forwarded-For headers sent by the load balancer. If not configured correctly or if the load balancer is misconfigured, an attacker could spoof their IP address, potentially bypassing IP-based rate limiting or security policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e677a93e-033a-4095-8a40-ae69bf20d2c1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does case-sensitivity mean in R?', N'Intern', N'R is case-sensitive, meaning that uppercase and lowercase letters are treated as distinct characters. For example, a variable named ''Data'' is considered completely different from a variable named ''data''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f755ad09-f86a-403a-9ed1-ae6b07e4b61a', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are the trade-offs of using utility classes versus traditional BEM or component-based CSS?', N'Middle', N'Utility classes speed up development and eliminate the need to invent class names, but they can make HTML markup look cluttered and harder to read. BEM provides better separation of concerns and cleaner HTML but requires more time spent naming classes and managing cascading style sheets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd0da405-e3fb-4080-a430-ae6b81161123', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do procs and lambdas differ?', N'Junior', N'Lambdas are stricter than procs because they check the number of arguments passed to them and return control to the calling method. Procs are more lenient and return from the current scope when executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd457c47d-42af-40ce-9b8b-ae6e90e06d97', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the benefit of the ''in'' parameter modifier?', N'Middle', N'The in modifier ensures that a parameter is passed by reference but cannot be modified by the method, providing both performance efficiency and data safety. It is particularly useful for large structs where passing by value would cause unnecessary copying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e320f84-018c-4a17-a571-ae6f2d10c940', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle CSS imports?', N'Intern', N'Vite treats CSS files as modules. When you import a CSS file in your JavaScript, Vite automatically injects the styles into the document head and supports features like CSS modules out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e89895e2-d0ef-4e19-b29a-ae7020a3fe8b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does the term ''near real-time'' mean in Elasticsearch?', N'Fresher', N'Near real-time means there is a slight delay, usually one second, between the time a document is indexed and the time it becomes searchable. This happens because the system periodically refreshes the index to make new data visible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca1eea4b-bb9b-4fe7-903d-ae7178c720c0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are WeakRef and FinalizationRegistry in JavaScript?', N'Intern', N'Introduced in ES2021, WeakRef and FinalizationRegistry provide low-level access to the garbage collector — primarily for caches and resource management. WeakRef: A WeakRef holds a *weak reference* to an object, meaning it does not prevent the object from being garbage-collected. Use .deref() to access the object; it returns undefined if already collected. FinalizationRegistry: Lets you register a callback to be called when a registered object is garbage-collected. Practical use — weak cache: Important caveats: * GC timing is non-deterministic — never rely on FinalizationRegistry for critical cleanup. * WeakRef should be a last resort; prefer WeakMap/WeakSet for most weak-reference patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35c3c6b4-98ea-4fe3-8154-ae72b4853e0e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the NestJS CLI?', N'Intern', N'The NestJS CLI is a command-line interface tool used to initialize, develop, and maintain NestJS applications. It helps developers quickly generate boilerplate code, modules, controllers, and services following the framework''s standard structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f134dfbf-6581-410e-886f-ae78edbfad15', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''strictNullChecks'' flag change the behavior of ''undefined'' and ''null''?', N'Senior', N'With strict null checks disabled, null and undefined are considered valid values for every type, which is a major source of runtime errors. Enabling it forces developers to explicitly handle nullish cases, ensuring that variables cannot be accessed until they are verified to exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19667797-8886-4955-a4e2-ae7d9f4cd21e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''transient'' keyword in serialization?', N'Middle', N'The transient keyword marks a field as not part of an object''s persistent state during serialization. This is useful for security-sensitive data or fields that can be easily recalculated, such as caches or temporary objects. When the object is deserialized, these fields are initialized to their default values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65113249-7da8-4ec9-9974-ae7e2728d97c', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Compare the impact of TTL (Time-To-Live) settings on cache hit rates and data freshness.', N'Senior', N'Short TTLs ensure high data freshness but result in lower hit rates and increased load on the backend due to frequent re-fetches. Long TTLs maximize hit rates and reduce backend load, but they increase the window during which users may see stale or inaccurate information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7ec7ff1-9f6c-48df-a1bf-ae7f30374d59', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do closures impact memory consumption?', N'Middle', N'Closures allow a function to retain access to its lexical scope even after the outer function has finished executing. Because the outer scope''s variables remain in memory to support the closure, excessive or unnecessary use of closures can lead to increased memory usage and potential leaks if those references are not eventually cleared.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'831b1ed9-fea3-461a-9f92-ae816d0a066b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s Cache component support multi-tier caching strategies?', N'Senior', N'The Cache component uses a PSR-6 or PSR-16 compliant interface to abstract storage, allowing for hierarchical caching. You can chain adapters, such as using an in-memory Redis store for high-speed access and a filesystem adapter as a persistent fallback, ensuring optimal performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'128bf325-439e-416c-8996-ae8297d060ae', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between an ''Arbiters'' and a ''Delayed Secondary'' in a replica set?', N'Senior', N'An arbiter participates in elections but does not store data, acting only as a tie-breaker to ensure a majority exists. A delayed secondary maintains a copy of the data with a time lag, serving as a recovery mechanism against accidental data deletion or corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f63118df-2653-428a-9ccf-ae83d9efba10', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a singleton class in Ruby?', N'Middle', N'A singleton class, or eigenclass, is a hidden class associated with a single specific object. It is used to store methods that are unique to that object, allowing for per-instance behavior without affecting the entire class hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a9c20d0-6078-48ef-80d1-ae84e6772862', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can you prevent clickjacking attacks?', N'Fresher', N'To prevent clickjacking attacks, you can use the X-Frame-Options HTTP header to control whether your site can be embedded in iframes. Set it to DENY to prevent all framing, or SAMEORIGIN to allow framing only from the same origin. Additionally, you can use the Content-Security-Policy (CSP) header with the frame-ancestors directive to specify which origins are allowed to frame your content. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of input validation and its importance in security Input validation is the process of ensuring that user input is correct, safe, and meets the application''s requirements. It is crucial for security because it helps prevent attacks like SQL injection, cross-site scripting (XSS), and other forms of data manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7471709b-8f99-4eff-ae84-ae87f2ab97c8', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the significance of the ''AppInitializer'' token in the application bootstrap process.', N'Senior', N'The AppInitializer token allows developers to execute code before the application fully starts, which is useful for loading configurations or authentication states. However, it blocks the bootstrap process, so heavy logic here can significantly delay the user''s initial interaction with the app.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1016c3a5-8e7f-491d-b335-ae8870cca4bf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is ''RequestIdleCallback'' useful for performance optimization?', N'Senior', N'RequestIdleCallback allows tasks to run during the browser''s idle periods, preventing them from interfering with high-priority tasks like animations or input handling. It is an excellent tool for scheduling low-priority background work to keep the main thread fluid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d556396-5384-41a3-b64f-ae8e692691da', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the use of the ''IActionResult'' return type?', N'Junior', N'IActionResult is an interface that allows an action method to return different types of HTTP responses, such as 200 OK, 404 Not Found, or 400 Bad Request. It provides a flexible way to signal the result of an operation back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'682ff05a-e3d1-496b-97c1-ae8f8bf522fa', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the concept of a join?', N'Fresher', N'A join is an operation that combines rows from two or more tables based on a related column between them. This allows users to retrieve data that is spread across multiple tables in a relational database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1615b91d-14e7-4dbb-abef-ae90aadfb48e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass compilation speed scale with the complexity of a project?', N'Senior', N'As projects grow, the number of imports, loops, and complex logic blocks can significantly increase compilation time. Utilizing modular architecture with @use and minimizing unnecessary calculations or deeply recursive functions helps keep build times efficient during development cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6bddd78-9c1f-4b28-920c-ae942542d4f2', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the trade-offs of Qwik''s granular chunking approach?', N'Middle', N'While granular chunking provides excellent load times, it can increase the number of network requests if not managed correctly. Additionally, it requires developers to be mindful of how they structure code to ensure optimal chunk boundaries and avoid unnecessary code splitting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0072ac47-8d93-4046-aaaf-ae946e390a73', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle concurrency at the framework level?', N'Middle', N'Axum relies on the Tokio runtime, which uses a multi-threaded work-stealing scheduler. This allows the framework to handle thousands of concurrent connections efficiently by distributing tasks across available CPU cores without blocking the main execution thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b207aa36-cebe-46fb-a043-ae94ccc2a363', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between ''ViewChild'' and ''ContentChild''?', N'Middle', N'ViewChild queries elements that exist within the component''s own template. ContentChild queries elements that have been passed into the component from a parent component through content projection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5ae9c2a-85fb-49da-bb21-ae9a64fc7cbe', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why should you avoid using a wide range of partition keys with ''ALLOW FILTERING''?', N'Senior', N'Using ALLOW FILTERING forces the coordinator to scan all partitions across the cluster, which is extremely expensive and can lead to massive latency spikes. It bypasses the efficient partition-key lookup mechanism and essentially performs a full table scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24f61a8d-2001-4376-81c0-ae9b44bb77c1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you create custom HTML element?', N'Fresher', N'The creation of custom HTML elements involves two main steps, 1. Define your custom HTML element: First you need to define some custom class by extending HTMLElement class. After that define your component properties (styles,text etc) using connectedCallback method. Note: The browser exposes a function called customElements.define inorder to reuse the element. 2. Use custom element just like other HTML element: Declare your custom element as a HTML tag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1c7fd54-1ce0-4a43-93f2-ae9b924b4d97', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite''s plugin system based on Rollup, and what does this imply?', N'Middle', N'Vite''s plugin system extends the Rollup plugin interface, meaning many existing Rollup plugins are compatible with Vite. This allows developers to leverage a massive existing ecosystem while benefiting from Vite-specific hooks designed for the development server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fc60b12-4e27-432c-8aec-ae9e6d890455', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the architectural impact of changing a key system dependency, such as an identity provider or database engine?', N'Senior', N'I perform a risk assessment on the depth of the dependency integration. I estimate the cost of abstraction layer implementation versus direct refactoring, considering the effort for data migration, service downtime, and the validation strategy required to ensure system integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'520871de-7c3d-45e9-bf7a-ae9f986bbc64', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between ''search_after'' and ''scroll'' for deep pagination?', N'Senior', N'Search_after is a stateless, performant way to paginate through results by using the sort values of the last document in the previous page. Scroll is stateful, maintaining a snapshot of the index, which is useful for bulk exports but consumes significant memory and is discouraged for real-time user-facing applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcbe2670-b128-4a8f-8cf0-aea1c58d3824', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s router hierarchy facilitate large-scale application development?', N'Senior', N'Litestar allows for nested routers that inherit configurations, dependencies, and middleware from parent routers. This facilitates a modular architecture where different domains can be independently maintained while sharing a unified security and dependency management policy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ede4244-9119-4451-a243-aea20381c2dc', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of GraalVM in Quarkus?', N'Intern', N'GraalVM is the underlying technology used to perform ''Ahead-of-Time'' (AOT) compilation. It allows Quarkus to transform Java bytecode into a native binary that runs directly on the operating system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc43e13c-3b75-4d97-b653-aea5987a54d5', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle HTTP requests compared to traditional frameworks?', N'Intern', N'Fastify is built on top of an efficient internal router called Find-My-Way, which uses a radix tree to perform extremely fast route matching. This approach is significantly faster than the linear search methods used by some older frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69123a14-5abb-4cd0-85f4-aea73e78d5c8', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the benefit of testing internal modules versus public APIs?', N'Middle', N'Testing internal modules allows for fine-grained verification of logic and private helper functions, ensuring components work in isolation. Testing public APIs ensures the final interface meets external requirements, providing a contract that guarantees stability for users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14e33f58-2e25-4b4b-8725-aea7529c59f2', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between ''include <header>'' and ''include "header"''?', N'Junior', N'Using angle brackets tells the preprocessor to look for the file in the system or standard library directories. Using double quotes tells the preprocessor to look in the current project''s directory first, which is typically used for user-defined headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42c96459-3968-421c-9096-aeaa27eedc1f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a ''regression'' in the context of fixing bugs?', N'Intern', N'A regression occurs when a fix for one bug inadvertently breaks a previously working feature. This is why testing the entire system after applying a fix is a critical part of the troubleshooting cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c07cf8f4-8f1e-41b7-9e2e-aeaa425ee5c9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you handle the trade-off between modularity and performance?', N'Fresher', N'Modularity makes code reusable and easier to maintain by separating concerns. However, excessive modularity can introduce function call overhead and hinder certain compiler optimizations, so you must find a balance where the code is clean without sacrificing necessary performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90a4e7e4-6ffc-406e-bb89-aeab0e0c38d1', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the InnoDB Buffer Pool manage memory and what is the trade-off of its size?', N'Senior', N'The Buffer Pool caches data pages and indexes in memory to minimize disk I/O. If set too small, performance suffers due to excessive paging; if set too large, it may cause the operating system to swap, significantly degrading performance due to memory contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c995641-d890-44cf-a291-aeb5f1bde46d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the role of ''Ecto.Repo'' as a wrapper for database connection pools.', N'Senior', N'Ecto.Repo manages a pool of database connections, abstracting the complexity of connection handling, transaction management, and query execution. It allows the application to handle concurrent database interactions efficiently by dynamically allocating connections based on load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'862714aa-c407-4fd0-bdef-aeb6858711af', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the ''defer'' and ''only'' query methods, and when should they be used?', N'Middle', N'These methods allow you to limit the fields retrieved from the database to improve performance by reducing the amount of data transferred. Use ''only'' to specify exactly which fields you need, and ''defer'' to exclude specific heavy fields, which is useful when dealing with large text or binary data that isn''t always needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'702fab39-190e-4a5d-b8d3-aebbf1c70ea6', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Discuss the impact of long selector chains on browser style recalculation.', N'Senior', N'Long selector chains increase the computational complexity of matching rules against DOM nodes. While modern engines are highly optimized, excessively deep or complex selectors can lead to micro-stutters during dynamic DOM manipulations in large, complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdd458fe-0adb-418f-ab01-aebd46029d0b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why might a team choose to move from Sass to CSS-in-JS or Tailwind?', N'Middle', N'Teams often move to CSS-in-JS or Tailwind to solve issues related to global scope, dead code elimination, and the tight coupling of styles to logic. While Sass is excellent for preprocessing, modern alternatives offer better integration with component-based frameworks and often result in more performant, purged CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50e01ca8-0fc8-43d8-8a63-aec0ab070ac7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the inverted index work in Elasticsearch?', N'Middle', N'The inverted index maps every unique term in the dataset to the list of documents that contain it. This structure allows the engine to perform extremely fast full-text searches by looking up terms directly rather than scanning through every document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'711cb8b9-c12d-4fb7-80f1-aec0dbc77dfb', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the possible errors with declarations?', N'Intern', N'There are two common possible errors with declarations array, 1. If you use a component without declaring it, Angular returns an error message. 2. If you try to declare the same class in more than one module then compiler emits an error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfbccaf0-e30e-4446-b8f9-aec11eaf0380', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the concept of event bubbling and how it impacts event delegation.', N'Middle', N'Event bubbling is the propagation of an event from the target element up through its ancestors in the DOM tree. Event delegation leverages this by attaching a single listener to a parent container instead of multiple listeners to children, improving memory efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'341b3d01-6b67-48d2-a935-aec5095b7e82', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the concept of ''x-effect'' and when it is appropriate to use it.', N'Middle', N'x-effect is used to execute a side effect whenever one of its dependencies changes. It is ideal for tasks that need to stay in sync with state, such as updating a third-party library''s configuration or logging changes, without needing a manual event listener.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd94d447-af37-4328-af74-aec5a5b1a22d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Discuss the trade-offs of using custom allocators in C++ containers.', N'Senior', N'Custom allocators allow fine-grained control over memory management, such as using pool allocators for small objects to reduce heap fragmentation or placing data in specific memory segments. However, they complicate the type system as the allocator becomes part of the container''s type, potentially leading to template bloat and complex signature requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c4135e-90d6-4941-a819-aec7c57c1029', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does ''Conflict-Free Replicated Data Type'' (CRDT) relate to transaction consistency?', N'Senior', N'CRDTs provide a way to achieve strong eventual consistency in distributed systems without the need for traditional locking or heavy consensus. By designing data structures that are commutative and associative, updates can be applied in any order across nodes and always converge to the same state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22543588-6374-4f67-bd96-aecabc6e3b2f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are DTOs in Litestar and why are they used?', N'Fresher', N'DTO stands for Data Transfer Object, and in Litestar, they are used to define the schema for data entering or leaving the application. They ensure that only the intended fields are exposed or accepted, providing a clear contract between the API and the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a4f380b-338e-41d4-ae8a-aecb60764b31', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When choosing between a relational database and a NoSQL database for a new feature, what is the most important factor to consider?', N'Junior', N'The most important factor is the structure and consistency requirements of the data. Use a relational database if the data is highly structured and requires complex relationships or ACID transactions, and choose NoSQL if the data is unstructured, requires high horizontal scalability, or has a rapidly evolving schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
