INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08486b28-b641-4280-9da4-aee5a695bc66', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the Global Interpreter Lock (GIL) and why does it exist?', N'Junior', N'The GIL is a mutex that prevents multiple native threads from executing Python bytecodes at once, effectively limiting execution to a single thread at a time. It exists to simplify memory management and ensure thread safety for the CPython interpreter''s internal data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ac47c79-f358-458d-aae3-aee6a86ba283', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is a middleware in the Gin framework?', N'Fresher', N'Middleware is a function that sits between the incoming request and the final handler. It can perform tasks like logging, authentication, or error recovery before or after the request is processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0d5974d-c7d0-4d8d-8e88-aee8337e65f8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the scalability limitations of Gin in a stateful application design?', N'Senior', N'Gin, like most Go frameworks, is stateless by design. If state is maintained locally within the application memory, horizontal scaling becomes impossible because requests may land on different instances that lack access to the shared state, requiring the use of external distributed stores like Redis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d70dc3a-dfd8-4996-ab55-aee9972ef29a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why would you choose Micronaut over a more mature framework like Spring Boot?', N'Middle', N'You would choose Micronaut when startup time, low memory overhead, and cloud-native efficiency are the highest priorities. It is particularly well-suited for serverless functions, multi-tenant architectures, or environments where resource costs are strictly monitored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed0cb423-9bdc-4a27-a047-aeed34a06f3d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of $dispatch in Alpine.js?', N'Junior', N'$dispatch is used to trigger custom browser events from within a component. This is a powerful way for components to communicate with each other, as other parts of the application can listen for these events and react accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71d75980-ae62-42e7-9728-aeef8b862110', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the null-aware operators like ?? and ?. in Dart?', N'Junior', N'These operators help handle null values safely without writing verbose if-else statements. The ? operator is used for safe property access, returning null if the object is null, while the ?? operator provides a default value to use if the expression on its left evaluates to null.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4756cfd-ec7d-4b1b-b147-aef4c8a83ff9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why might a Senior Engineer choose Fiber over a more standard-compliant framework like Gin?', N'Senior', N'A choice for Fiber is typically driven by raw performance requirements where Fasthttp''s architectural optimizations are necessary to handle extreme throughput. If strict adherence to the net/http standard library ecosystem is less critical than minimizing latency and CPU overhead, Fiber is the preferred choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52990df5-9842-4c0c-a09b-aef5833741ba', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact achieve a smaller bundle size?', N'Middle', N'Preact achieves a small bundle size by stripping out rarely used features, reducing internal complexity, and strictly adhering to modern browser standards. It avoids the overhead of backward compatibility for outdated browsers and complex edge cases that React includes by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20ca3383-e620-4a46-8a40-aef5ace8668a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the trade-offs of using SolidJS''s fine-grained reactivity?', N'Middle', N'The primary benefit is superior performance and smaller bundle sizes due to the lack of a reconciliation engine. However, developers must be careful not to destruct reactive objects, as doing so can break the dependency tracking and cause updates to stop working.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e243011-92a2-4834-bab4-aef5f800fb41', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are sealed classes in Kotlin?', N'Intern', N'Sealed classes are used to represent restricted class hierarchies. They are useful when a value can have one of the types from a limited set, often used in state management to ensure all possible cases are covered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26293950-08d1-43a4-bef1-aef7313f8018', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS''s utility-first approach impact the performance and maintainability of a large-scale enterprise application compared to traditional BEM or CSS-in-JS solutions?', N'Senior', N'Tailwind improves performance by enforcing a finite set of design tokens, which results in a smaller, deterministic CSS footprint that does not grow linearly with the number of components. In large-scale apps, it eliminates the overhead of managing complex CSS class naming schemas like BEM or the runtime performance costs associated with CSS-in-JS libraries. This approach ensures long-term maintainability by preventing style leakage and reducing the cognitive load required to manage global stylesheet cascades.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d567fe6-16bf-460c-b358-aef99477a15e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is choosing a ''good'' shard key critical for scalability?', N'Middle', N'A good shard key ensures even distribution of data and traffic across all nodes. A poor choice, such as a timestamp or a low-cardinality column, leads to data skew and uneven load distribution, rendering the horizontal scaling ineffective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
