INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5090e991-a93e-47af-a10e-af015fc30ebf', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle polymorphism differently from object-oriented languages?', N'Middle', N'Rust uses traits for polymorphism, which decouples data structures from behavior. Unlike traditional inheritance that uses classes, Rust relies on trait bounds and generics to achieve static dispatch via monomorphization or dynamic dispatch via trait objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
