INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a780226-8c96-463a-b370-af04b269bb19', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the performance considerations of using ''Arc'' compared to ''Rc''?', N'Senior', N'Both types provide shared ownership, but ''Arc'' uses atomic reference counting to ensure thread safety, which involves expensive synchronization primitives. ''Rc'' uses non-atomic counters, making it significantly faster for single-threaded scenarios where thread-safe sharing is not required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
