INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3f03ea2-58cb-4869-8063-af08eb58d6cc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle asynchronous lifecycle hooks?', N'Middle', N'Fastify supports asynchronous hooks by awaiting the returned Promise or calling a provided callback. If a hook throws an error or returns a rejected promise, the request lifecycle is immediately aborted and the error handler is triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42f282fa-8d80-42fd-87a9-af0a7486db99', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it important to use `c.Copy()` when passing the Gin Context to an asynchronous task?', N'Senior', N'The Context object is intended to be used only within the lifetime of the request; once the handler returns, the object is returned to a pool and its fields are reset. Passing the raw context to a goroutine is a race condition; `c.Copy()` creates a read-only snapshot that is safe for access in background tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44991daf-48df-43bf-886b-af0b7dae963c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is Sass and why do developers use it instead of standard CSS?', N'Intern', N'Sass is a CSS preprocessor that extends CSS by adding features like variables, nested rules, and mixins. It allows developers to write cleaner, more maintainable code that is then compiled into standard CSS that browsers can understand. By using these features, developers can avoid repeating styles and organize their stylesheets more efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
