INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e69f0ba-f0b4-41d1-8356-af20103b0bed', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Is Axum suitable for microservices?', N'Junior', N'Yes, Axum is well-suited for microservices due to its modular design, performance, and type-safe request handling. Its ability to easily share state and integrate with other ecosystem crates makes it a strong candidate for backend services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdb90104-bf58-43d6-ac7c-af231434e58c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the role of the JIT (Just-In-Time) compiler in Tailwind CSS regarding developer experience and bundle size.', N'Senior', N'The JIT compiler generates styles on-demand as you write them, which eliminates the need to purge unused CSS after the fact. This enables unlimited design flexibility and significantly faster build times compared to the legacy extraction method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
