INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7ba2613-bbfe-4d54-a357-af23d8fe9237', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is ''eventual consistency'' in DynamoDB?', N'Intern', N'Eventual consistency means that when you read data, it might not reflect the most recent write immediately. Given a short period of time, all copies of the data will eventually be consistent across all storage nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7b977bf-fbdf-45bc-b5dc-af26c3123fcf', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle environment variables?', N'Intern', N'AdonisJS uses a dedicated environment variable module that validates variables against a defined schema. This ensures that the application has all the required configuration settings before it starts, preventing runtime errors due to missing or misconfigured settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'359927f4-c26c-41ef-a2a9-af272597ef7b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing an authentication method, what is the trade-off between user convenience and security?', N'Junior', N'Strong security measures like multi-factor authentication or long, complex passwords protect user data effectively but create friction during login. Minimizing these steps improves user experience and retention but significantly increases the risk of unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50305dbe-7f58-4335-94c0-af2a44859533', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the various statements in error handling?', N'Intern', N'Below are the list of statements used in an error handling, 1. try: This statement is used to test a block of code for errors 2. catch: This statement is used to handle the error 3. throw: This statement is used to create custom errors. 4. finally: This statement is used to execute code after try and catch regardless of the result. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ff221d9-1730-4569-bf5b-af2b57df3d66', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''shared libraries'' for cross-service logic often an anti-pattern?', N'Senior', N'Shared libraries create tight coupling because every service must update and redeploy the library whenever a change is made. This undermines the goal of independent deployability and can lead to dependency hell if different services require conflicting versions of the same shared library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25d8177e-c1bd-46d6-a54c-af2c8b3463b0', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the ''DispatcherServlet'' in Spring MVC, and how does it relate to the ''Front Controller'' pattern?', N'Senior', N'The DispatcherServlet acts as the central entry point for all incoming requests, implementing the Front Controller pattern. It orchestrates the request lifecycle by delegating to handler mappings, controllers, and view resolvers, centralizing cross-cutting concerns like logging and exception handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d11c08c-80ac-4441-9580-af2ed324af69', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is color manipulation in Sass?', N'Intern', N'Sass provides built-in color functions that allow you to lighten, darken, saturate, or desaturate colors programmatically. This ensures design consistency, as you can generate a whole color palette from a single base brand color.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11f0ac82-c02d-46ed-b046-af2ed49c4979', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of Dependency Injection.', N'Fresher', N'Dependency Injection is a design pattern where an object receives other objects that it depends on, rather than creating them internally. In Laravel, this is primarily handled by the Service Container, making code more testable and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58c36cc6-7a40-4281-b976-af2f3321a6cd', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the role of API versioning in a long-term system evolution?', N'Senior', N'Enforce versioning via URI or header-based approaches to allow breaking changes without disrupting existing clients. Use deprecation policies to manage the lifecycle of older versions and communicate changes proactively to consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0bdea44-6f14-44c2-ac71-af32a81cf33c', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the components directory?', N'Intern', N'The components directory is where you store your reusable UI building blocks. Nuxt automatically imports these components, allowing you to use them in your pages without needing to write import statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b0dc4cc-453a-4d92-b420-af32abe82c0f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between == and is operator in Python?', N'Fresher', N'Difference between == and is in Python Both the == and is operators in Python facilitate different types of comparisons: - The == operator evaluates value equality. It checks if the data held by two objects is equivalent, typically by invoking the eq method. - The is operator evaluates object identity. It verifies if two variables reference the exact same instance in memory. In Python, every object has a unique identifier assigned by the interpreter. The is operator compares these memory addresses. If $id(a) = id(b)$, then a is b evaluates to True. Comparison Logic - is: Compares the identity (memory address) of two objects using the id() function. - ==: Compares the value (contents) of two objects by checking for logical equivalence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0892f8bb-a810-4863-bcb5-af36883fb5a6', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why would someone choose NoSQL over SQL?', N'Intern', N'NoSQL is often chosen for its ability to scale horizontally across multiple servers and for its flexible schema, which allows developers to iterate quickly. It is particularly useful for applications with rapidly changing data requirements or massive datasets that exceed the capacity of a single server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a31775d-018d-4be0-bd11-af37cdc068b9', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Discuss the trade-offs of using ''Constructor Injection'' versus ''Field Injection'' in Spring-managed beans.', N'Senior', N'Constructor injection allows for immutable beans and makes dependencies explicit, facilitating easier unit testing without needing a Spring container. Field injection is more concise but obscures dependencies, makes unit testing harder, and can lead to hidden circular dependencies that are harder to detect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a643584-2b05-4734-9779-af3b4fdb7eea', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the relationship between ''Blocks'' and ''Closures'' in the Ruby language architecture.', N'Senior', N'Blocks in Ruby are syntactic structures that capture the lexical environment in which they are defined, effectively acting as closures. This design allows for elegant implementation of the ''Execute Around'' pattern, though it necessitates that the VM manages the lifetime of local variables that must outlive the scope in which they were created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6184b765-ec7e-4707-a803-af40f2dd8cfa', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between development mode and production mode?', N'Intern', N'Development mode includes tools like hot module replacement for a faster feedback loop during coding. Production mode focuses on performance, applying minification and optimizations to make the application as fast and small as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62cef04b-72a6-49dd-8c11-af41755bd4b5', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a deadlock in a transaction?', N'Fresher', N'A deadlock occurs when two or more transactions are waiting for each other to release locks. Neither can proceed, forcing the database system to kill one of the transactions to break the cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6783f94c-36aa-4871-8940-af42655a8d32', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact use a synthetic event system like React?', N'Intern', N'Preact aims to be closer to the browser standards and generally uses native DOM events rather than a synthetic event system. This helps keep the library smaller and makes it more compatible with standard browser behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4836b373-ab57-45cf-b49f-af45cd31a11c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do you handle ''Hot Partitions'' in a distributed database?', N'Senior', N'Hot partitions occur when a disproportionate amount of traffic targets a single shard, often due to a poor partition key choice. Solutions include using a more granular or composite partition key, implementing request caching in front of the specific shard, or dynamically re-sharding the data to distribute the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a6a880c-6d55-44da-a664-af461acdd496', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the impact of Preact''s lack of a Fiber-like reconciliation engine?', N'Senior', N'The absence of a Fiber-like engine means Preact does not support time-slicing or interruptible rendering by default. While this makes the core library much smaller and faster for typical tasks, it places the burden of preventing long-running main thread tasks on the developer through careful component design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad07168b-5fc2-46a3-9cd3-af47689fa0be', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the advantages of using a distributed cache compared to an in-memory cache?', N'Middle', N'An in-memory cache is local to a single server and is lost if the server restarts, whereas a distributed cache is shared across multiple nodes. Distributed caches provide a unified, persistent data layer that is accessible by any instance, making it ideal for scaling applications with stateless web tiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'152c39ab-e1c8-4717-b5ef-af49906da284', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Does PHP support multiple inheritance?', N'Intern', N'No, PHP does not support multiple inheritance for classes. A class can only inherit from one parent class, though it can implement multiple interfaces to achieve similar functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8051036d-f80c-46a6-9187-af4a116a5427', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you handle shared mutable state in Axum without creating bottlenecks?', N'Senior', N'To avoid contention on shared state, developers should favor granular locking using RwLock or by utilizing atomic types for simple counters. If the state is heavily contended, shifting to an actor-based model or a message-passing architecture using channels can prevent thread blocking and improve throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3d9da05-f5e4-4fff-a3d5-af4aafeacca7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between Structural Typing and Nominal Typing?', N'Middle', N'TypeScript uses structural typing, meaning if two types have the same shape, they are considered compatible regardless of their name. Nominal typing, found in languages like Java, requires explicit compatibility between types even if their structures are identical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca2d7ef-c6d0-4285-bd53-af4fed1f29b1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'In a fiber-based architecture, what happens when a fiber performs a blocking system call?', N'Middle', N'If a fiber performs a blocking system call that the runtime is not aware of, it may block the entire underlying OS thread, effectively halting all other fibers assigned to that thread. To prevent this, the runtime must use non-blocking I/O or a specialized scheduler that can intercept and offload such calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb2752d2-0927-43f8-b22e-af55a8419ac6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the Translation component?', N'Intern', N'The Translation component provides tools to internationalize an application. It allows developers to define messages in different languages and automatically serve the correct version based on the user''s locale settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63eceeac-deab-41c1-bcb2-af55b47eca63', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why would you choose Litestar over a basic framework like Flask?', N'Junior', N'Litestar is built for performance and modern Python features, specifically designed for async/await workflows and type safety. It offers built-in dependency injection and automatic OpenAPI generation, which requires more manual effort in older frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'922010e7-6390-4ff6-a48a-af5af8f50f0d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the ''app.html'' file?', N'Fresher', N'The app.html file is the root template for the entire application. It contains the basic HTML structure, including the head and body tags, where the Svelte application is injected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c76163a-cd3c-4f2c-85c2-af5e90535713', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Discuss the challenges of ''Distributed Monolith'' and how to identify if you have built one.', N'Senior', N'A distributed monolith occurs when microservices are highly coupled and require a specific deployment order or shared database access. You identify it when changing one service forces changes in others, or when a failure in a minor service brings down the entire ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c27fe7d8-d6dc-4635-bb01-af5f284fe7bf', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'When building a multi-tenant application with Astro, what are the architectural considerations for Middleware?', N'Senior', N'Middleware in Astro allows for request interception, which is crucial for handling authentication, localization, and tenant-based routing. You must ensure that middleware logic remains lightweight, as it executes on every request, and consider how to share context safely across the server lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0dd64ae-c3a8-4423-a3ca-af60e1de6958', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is SEO better with Next.js?', N'Intern', N'Next.js provides server-rendered HTML, which allows search engine crawlers to easily index the content of your pages. This is more effective than client-side rendering, where crawlers might struggle to see content that is generated dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92635711-bbc3-41dd-829d-af66e3826080', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why might you use a caching layer like Redis in front of a database?', N'Middle', N'A cache reduces the load on the primary database by serving frequently accessed data from memory. This drastically lowers latency and allows the database to handle fewer concurrent connections, effectively scaling the read capacity of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae8b816-03ad-4e3d-b672-af6756ac5226', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a watcher in Vue?', N'Junior', N'A watcher is a reactive feature used to perform side effects in response to changes in a specific data property. It is best used for asynchronous operations or expensive tasks that need to run whenever a certain piece of data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
