INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eadccc3b-a62b-4972-a498-af834d89f126', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database systems handle the trade-off between strict consistency and performance in a distributed environment?', N'Senior', N'Systems typically adhere to the CAP theorem, choosing either consistency or availability during a partition. To optimize, many systems use tunable consistency, allowing developers to choose between strong synchronous replication or eventual consistency based on the specific requirements of the operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70c97427-e4d3-40a9-9444-af837090ea36', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Explain the role of ''DTOs'' in Litestar and why they are preferred over simple Pydantic models for data transfer.', N'Senior', N'Litestar DTOs provide a dedicated layer for data transformation that separates the internal domain model from the external API contract. This prevents over-posting or over-fetching issues by allowing developers to define explicit read/write schemas that adapt dynamically based on the operation context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8d82530-068f-442c-9ed2-af8406c08397', N'954a0331-deff-4399-b588-96f39fec001d', N'Discuss the trade-offs of using Lazy Loading for feature modules in a large-scale Angular application.', N'Senior', N'Lazy loading significantly improves initial load time by splitting the application into smaller, on-demand chunks. However, it introduces complexity in terms of shared service instances, as lazy-loaded modules create their own child injectors, requiring a clear strategy for whether services should be application-wide (singleton) or module-scoped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9019c48-a6a3-487c-91a5-af850edc0d11', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the Gossip protocol facilitate cluster membership and state propagation?', N'Senior', N'The Gossip protocol is a peer-to-peer communication mechanism where nodes periodically exchange state information with randomly selected neighbors. This allows the cluster to maintain an accurate view of node availability and schema versions without requiring a centralized master node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9df45744-f3bb-4571-84eb-af868623c896', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django form?', N'Intern', N'A Django form is a class that handles data input, validation, and rendering. It allows developers to define the structure of input fields and automatically validates the data submitted by users before it is processed by the backend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a5c188d-dd97-4492-b8e7-af8a4a74a704', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''DefinePlugin'' and how should it be used securely?', N'Senior', N'DefinePlugin performs a direct text replacement of variables at compile time. It should be used to inject environment-specific configuration, but sensitive credentials should never be exposed here as they are bundled into plain text in the final output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c204820d-d0a4-480a-8784-af8a785dc26d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it generally discouraged to run long-running tasks directly inside a Gin handler?', N'Middle', N'Gin handlers execute within the request-response cycle; blocking the handler keeps the connection open and consumes server resources. For long-running tasks, it is better to offload the work to a background worker or a goroutine and return an accepted status immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dc26ea0-aea5-4ea4-8d83-af8c3aabb995', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the trade-off between using ''interface'' and ''type'' aliases for defining object shapes?', N'Senior', N'Interfaces support declaration merging and are generally preferred for public API definitions due to better error reporting. Type aliases offer more flexibility, such as union types, mapped types, and tuple manipulation, making them better suited for complex internal transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae062e8e-d7f9-4041-8646-af8c975f823c', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you handle global error handling in Angular, and why is an ErrorHandler subclass preferred?', N'Senior', N'Implementing a custom ErrorHandler allows for centralized logging, user notification, and telemetry reporting for all unhandled exceptions across the application. This is preferred over local try-catch blocks because it ensures consistency and prevents the application from entering an inconsistent state without the developer''s knowledge.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7faac15c-adc4-4a8f-b400-af8fef45632b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the request-response cycle in NestJS?', N'Fresher', N'The cycle starts with a request hitting a middleware, then potentially a guard, followed by an interceptor and a pipe. Finally, the controller handles the request, and the response flows back through interceptors and filters to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec7505ec-98ae-4eb0-99f1-af909d38a9ae', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the benefit of using an idempotent consumer?', N'Middle', N'An idempotent consumer ensures that processing the same message multiple times has the same effect as processing it once. This is critical for maintaining data integrity in systems where ''at-least-once'' delivery is used, as it makes the system resilient to network retries and duplicate messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1246074b-4789-4dcb-ae66-af933f113b3e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it important to handle timeouts in a Gin application?', N'Senior', N'Go''s default net/http server does not enforce timeouts, which leaves the application vulnerable to slow-loris attacks or resource exhaustion from stalled clients. You must configure the http.Server''s ReadTimeout, WriteTimeout, and IdleTimeout when initializing your Gin instance to ensure stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80f47a58-388e-463e-9152-af952dad1edf', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve its low memory footprint?', N'Fresher', N'Micronaut avoids reflection, dynamic proxies, and runtime bytecode generation. By processing annotations during the compilation phase, it creates the necessary metadata for the application, which eliminates the need for heavy runtime frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34c0d7b5-9ca9-4b99-b32a-af954c6e4850', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''useLoaderData'' hook?', N'Intern', N'The useLoaderData hook is a client-side function used to access the data returned by the route''s server-side loader. It makes the data fetched on the server available to your React components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d941b88-4138-40dc-8413-af9639311232', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What approach should you take when faced with two equally viable technical solutions?', N'Intern', N'Compare them against the project''s specific non-functional requirements like maintainability, documentation, and team familiarity. Often, the ''better'' solution is the one the team can support and evolve most effectively over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
