INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c4b2785-3f2d-4ffb-863a-af9bc8317f60', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Can you use standard third-party libraries in Qwik?', N'Middle', N'Yes, but they must be compatible with server-side execution and serialization requirements. Developers must be careful with libraries that rely heavily on global browser APIs or complex state that cannot be serialized into HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb6c9041-c3a4-4bc8-ab43-afa0c2d687b2', N'4c000000-0000-0000-0000-000000000005', N'Explain the significance of the CAP theorem in designing a distributed database.', N'Senior', N'CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, an architect must explicitly choose between returning an error or potentially stale data, guiding the selection of database consistency models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
