INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71175956-4857-401f-a1fd-afa4ca2db863', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the trade-offs of using Python''s ''metaclasses'' compared to class decorators?', N'Senior', N'Metaclasses provide the ability to intercept and modify class creation itself, offering deep control over the class object. Class decorators are generally simpler, more readable, and sufficient for modifying or wrapping classes after they are created. Metaclasses are best reserved for advanced framework development, while decorators are preferred for standard configuration tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9520b29e-1e14-4deb-a702-afaa43c23f66', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of health checks in a microservices architecture?', N'Middle', N'Health checks are endpoints exposed by services that allow orchestration platforms to verify if a service instance is running and capable of processing requests. If a health check fails, the orchestrator can automatically restart or replace the unhealthy instance to maintain system availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7d0dece-9a3f-47ae-9182-afad2b19be80', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the memory layout differences between structs and classes in Swift.', N'Senior', N'Structs are value types and are typically allocated on the stack or inline within their parent container, which provides high cache locality and avoids ARC overhead. Classes are reference types stored on the heap, requiring heap allocation, deallocation, and reference counting. The choice between them significantly impacts application memory footprint and performance due to these fundamental allocation differences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0257ff4-caca-4862-9840-afb134a71ed1', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why should you avoid using SELECT * in production applications?', N'Junior', N'Using SELECT * retrieves every column from a table, which often results in fetching unnecessary data. This increases network traffic, consumes more memory, and can break application code if the table schema changes in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da3f36ef-2650-4334-9c28-afb15a7f92c9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How do you manage authentication in a Remix application?', N'Middle', N'Authentication is typically managed using server-side sessions stored in cookies. You check the session in your loaders or actions and redirect unauthorized users to the login route, ensuring that security is handled entirely on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8f3ebdd-9206-4212-9d81-afb35463be67', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind’s JIT engine handle dynamic class generation compared to its older ''purging'' approach?', N'Senior', N'The older purging approach relied on generating a massive superset of all possible utility classes and then stripping unused ones, which was slow and limited. The JIT engine generates CSS on-demand based on the tokens found in your source files, allowing for arbitrary values and significantly faster build times even in massive codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59797b30-c8d2-40de-a3b1-afb38cd7515c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are given a task with ambiguous requirements, how do you proceed?', N'Fresher', N'I would first document the unclear areas and formulate specific questions to clarify them. Then, I would schedule a brief meeting with the stakeholder or lead to ensure my understanding aligns with their expectations before starting any work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fa81482-d5e8-4b1a-b856-afb7ec4574eb', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the interior mutability pattern work, and why is it necessary in Rust?', N'Senior', N'Interior mutability allows for mutation of data even when a variable is held behind an immutable reference, typically facilitated by types like Cell or RefCell. It is necessary when the ownership rules are too restrictive for certain design patterns, such as implementing caches or doubly linked lists, by deferring borrow checking from compile time to runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecd7c1d4-26f7-48b8-a5bc-afb83291d13d', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is an ORM and why is it used?', N'Junior', N'An ORM, or Object-Relational Mapper, is a tool that allows developers to interact with a database using object-oriented code instead of writing raw SQL. It simplifies development by mapping database tables to programming language classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
