INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c579176a-06b8-4f97-9841-afbc9c059b25', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''unknown'' type, and how is it different from ''any''?', N'Intern', N'The ''unknown'' type is a safer version of ''any'' that forces you to perform type checking before you can use the value. Unlike ''any'', you cannot perform operations on an ''unknown'' variable without first narrowing its type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02fe81d9-0bd0-469a-9ebb-afbd1291e68a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the significance of the ThreadPool''s ''Hill Climbing'' algorithm.', N'Senior', N'The Hill Climbing algorithm dynamically adjusts the size of the ThreadPool by monitoring throughput metrics to find the optimal number of active threads. It balances the need for parallelism against the overhead of context switching, preventing the system from becoming overwhelmed by excessive concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e49bf30-d84a-4f5e-8aea-afc020272d6c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the memory management benefits of Fastify''s response handling.', N'Senior', N'By leveraging schema-based serialization, Fastify avoids creating large intermediate object representations. It writes the response directly to the socket buffer more efficiently, reducing garbage collection pressure during peak traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45eed5c4-211f-4e67-b67e-afc0e22864ae', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the alignment requirement of data structures impact CPU performance and memory usage?', N'Senior', N'Most CPUs access memory more efficiently when data is aligned to its native word size, as unaligned access can require multiple memory cycles or cause hardware exceptions. Padding structures to meet these requirements increases memory footprint but significantly improves execution speed by preventing bus-level misalignment penalties. Compilers often handle this automatically, but developers must be aware of it when designing packed structures for network protocols or hardware interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b097a1ac-4b8e-49fa-a09d-afc1b56f0963', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of the dependency array in useEffect?', N'Middle', N'The dependency array informs React when to re-run the effect based on changes in specific variables. If the array is omitted, the effect runs after every render; if empty, it runs only once on mount, and if it contains values, it runs whenever those values change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f911e20-0c3f-4726-9cc2-afc49db96803', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do you handle database transactions in AdonisJS to maintain data integrity?', N'Middle', N'AdonisJS provides a transaction manager that allows you to wrap multiple database operations into a single unit of work. By using callbacks or manual commit/rollback methods, you ensure that all operations either succeed together or are rolled back if an error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
