INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b129e7c-9a16-4d8c-a903-afc8999e7b71', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle the ''split-brain'' scenario during network partitions?', N'Senior', N'Elasticsearch uses a quorum-based voting system for master election, requiring a majority of voting-eligible nodes to agree on the master. By requiring a minimum number of master-eligible nodes, the cluster ensures that only one partition can remain active, preventing conflicting cluster states from existing simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
