INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06c80f3a-73a7-4b36-853a-afcae4048e3d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript Promises handle errors differently than synchronous try-catch blocks?', N'Senior', N'Promises encapsulate asynchronous failure states, requiring the use of .catch() or await/try-catch to handle rejections. Unlike synchronous blocks, unhandled promise rejections can remain silent in some environments, necessitating explicit error handling strategies or global rejection trackers to avoid hidden failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cb72559-10bc-4eb4-9282-afcb5278ec3e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte''s reactivity model more performant for complex state updates than a dirty-checking model?', N'Senior', N'Svelte uses a surgical update approach where it knows exactly which slice of the DOM corresponds to which variable. Dirty-checking frameworks must re-evaluate the entire component tree or sub-trees to determine what changed, whereas Svelte jumps straight to the specific DOM mutation, bypassing the entire diffing algorithm.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
