INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f57058-fb8e-4ace-850d-afdf87d809da', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is dependency injection in FastAPI?', N'Intern', N'Dependency injection is a design pattern where the framework provides the necessary objects or services to a function rather than the function creating them itself. This makes the code modular, easier to test, and allows for reusable logic across different endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'226991f1-041f-4b7c-b538-afe1e8b40776', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s context usage differ from standard net/http in older Go versions?', N'Senior', N'Chi was an early adopter of context-based request propagation, which became a standard pattern in later Go releases. It essentially bridges the gap by providing a reliable, standardized way to pass request-scoped data that the standard library now supports natively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ff138a-ef5c-4224-b874-afe2a81d218b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What role do log files play in troubleshooting?', N'Intern', N'Log files act as a historical record of system events, providing a timeline of activity leading up to a crash or error. They are essential for identifying the state of the system at the exact moment a failure occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd48d70fe-55b9-49db-9972-afe355f701b1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What trade-offs are involved in using ''eval'' or ''new Function'' in a secure JavaScript environment?', N'Senior', N'These constructs bypass static analysis and can expose the runtime to code injection vulnerabilities if input is not strictly controlled. Furthermore, they prevent the engine from performing various optimizations, leading to unpredictable performance outcomes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1498e3c-52e9-4716-b75f-afe3712721ad', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core handle configuration settings?', N'Junior', N'Configuration is handled through a providers-based system that reads data from various sources like JSON files, environment variables, and command-line arguments. These sources are aggregated into an IConfiguration object, which can be injected into services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'913a29de-c287-4e73-9416-afe5d173a66f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is it important to use ''Query Builders'' instead of raw SQL?', N'Junior', N'Query builders provide a secure way to interact with the database, protecting against SQL injection vulnerabilities. They also offer a cleaner, more readable syntax that is consistent across different database systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5da921a2-3809-47c5-b6e6-afe6a59d7c0c', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React Intl?', N'Intern', N'The _React Intl_ library makes internationalization in React straightforward, with off-the-shelf components and an API that can handle everything from formatting strings, dates, and numbers, to pluralization. React Intl is part of _FormatJS_ which provides bindings to React via its components and API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffb54834-c527-481a-9736-afe6f04f346c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the classic trade-off between memory usage and processing speed in an algorithm?', N'Junior', N'Often, you can speed up a process by caching results in memory, which consumes more RAM. Conversely, if memory is limited, you must recompute data on the fly, which saves space but increases CPU usage and processing time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29a19818-e770-4ca1-a588-aff40668ab1e', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the challenges of caching at the API layer?', N'Senior', N'Challenges include cache invalidation, maintaining freshness for dynamic data, and handling varying levels of authorization. Effective caching requires careful consideration of cache-control headers, implementing e-tags for conditional requests, and deciding whether to cache at the edge, the gateway, or the individual service level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'249ae991-68e6-4826-a7af-aff4ab906e2f', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security implications of using a monolith versus microservices for data exposure?', N'Middle', N'A monolith often shares a single database, which can lead to excessive privilege accumulation if the entire application has access to all tables. Microservices allow for data isolation, where each service owns its own database, making it easier to enforce strict access controls and minimize data leakage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f09340f-cfeb-4d49-b753-aff53fe0aadb', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does it mean for a database to be schema-less, and how does it differ from a relational database?', N'Junior', N'A schema-less database, common in NoSQL systems, does not require a predefined structure for data, allowing for flexible and varied document formats within the same collection. In contrast, relational databases require a strict schema where data types and table structures must be defined before any data is inserted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5a9846e-e681-43aa-a910-aff5703fb7d1', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the trade-offs of using Flask-SQLAlchemy versus using the SQLAlchemy core directly?', N'Senior', N'Flask-SQLAlchemy provides convenience features like automatic session management and simplified configuration that integrate seamlessly with the Flask lifecycle. However, it can hide the underlying complexity of session scopes, which may lead to subtle bugs in complex, multi-threaded applications where direct control over engine and session lifecycle is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74e9a428-74f5-4640-ad14-aff76ac8f550', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What are the trade-offs between using CSS-in-JS libraries versus traditional CSS Modules?', N'Middle', N'CSS-in-JS allows for dynamic styling based on component props and easier scoping, but it introduces runtime overhead due to style injection and parsing. CSS Modules offer better performance by generating static CSS files at build time, though they lack the same level of tight integration with component-level state logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
