INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b33eae5d-f9db-4df7-b3b3-affe77b42266', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''pass'' statement?', N'Intern', N'The ''pass'' statement is a null operation that is used as a placeholder. It is often used when a statement is syntactically required but no code needs to be executed, such as in an empty function or loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f5e72d6-baf5-42c4-afd4-afff9ab92b50', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do reactive dependencies in the useEffect dependency array affect its execution behavior?', N'Fresher', N'The useEffect hook accepts an optional dependencies argument that accepts an array of reactive values. The dependency array determines when the effect runs. i.e, It makes useEffect _reactive_ to changes in specified values. How Dependency Array Affects Behavior 1. Empty Dependency Array: [] * Effect runs only once (like componentDidMount). * Ignores all state/prop changes. 2. With Specific Dependencies: [count, user] * Effect runs on first render, and * Again every time any dependency value changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1d0a40a-4ff4-4cc2-9b62-b000c32c2339', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the architectural trade-offs of using API keys versus OAuth2 for authentication?', N'Senior', N'API keys are simple to implement but lack granular scope control and revocation capabilities, making them suited for internal or low-risk access. OAuth2 provides a robust, standardized framework for delegated authorization, supporting scopes, token expiration, and third-party access management, which is essential for public or enterprise APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d633246-2d4e-4ca3-9f7b-b000e16427af', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a Flask extension?', N'Intern', N'A Flask extension is a package that adds specific functionality to a Flask application, such as database integration, form validation, or authentication. Examples include Flask-SQLAlchemy and Flask-WTF.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129ba1f2-3cfa-4c0f-8862-b000fccf2487', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose to implement a caching layer in front of your database?', N'Junior', N'A cache is used to improve read performance and reduce latency by serving frequently accessed data from memory instead of querying the database. This offloads pressure from the primary database, which is particularly beneficial for read-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcd910be-ee5a-4fe9-a2fe-b00181537807', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are ambient declarations, and where are they typically used?', N'Middle', N'Ambient declarations, typically defined using the ''declare'' keyword, notify the compiler that a variable or module exists in the global scope, even if it is not defined in the current file. They are commonly used to provide types for global variables or legacy JavaScript libraries that are injected into the runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b81fdec-f3d2-47c7-88bd-b00295d7de07', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a composite primary key?', N'Intern', N'A composite primary key is a primary key that consists of two or more columns combined together. It is used when a single column is not sufficient to uniquely identify a record in a table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7af4e5ff-b61f-4f08-adc7-b006951de5cf', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Can you define a route without a schema in Fastify?', N'Junior', N'Yes, you can define routes without a schema. However, omitting the schema means you lose the performance benefits of optimized serialization and automatic input validation, which are key features of the framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a4bdb74-e30f-4d1c-955e-b0083ee943ac', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the main challenge of implementing microservices regarding data consistency?', N'Middle', N'Microservices often result in distributed data where ACID transactions are not feasible across service boundaries. The main challenge is shifting from strong consistency to eventual consistency, which requires careful management of retries, compensating transactions, and idempotent operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86801fa7-c62f-4d4a-b750-b00977ae4c21', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is it important to create indexes that match the query pattern in MongoDB?', N'Middle', N'Indexes allow the database to locate documents without scanning every record in a collection, which drastically reduces disk I/O. If queries do not utilize an index, the database performs a collection scan, which is computationally expensive and slow as dataset size increases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
