INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f89173a-3e0b-4936-b647-b00a7228bff2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the benefit of using version control systems like Git in a team setting?', N'Intern', N'Version control allows multiple people to work on the same project simultaneously without overwriting each other''s work. It maintains a history of changes, allowing the team to revert to previous versions if a new update introduces bugs. This creates a safe environment for collaboration and experimentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bde739fe-aa76-455e-bf2b-b00b33ab0a4c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a namespace in TypeScript?', N'Intern', N'A namespace is a way to organize code into logical blocks and prevent naming collisions in the global scope. It groups related functions, classes, and variables under a single name, helping to keep the codebase clean and modular.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
