INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ced01d80-6040-4b11-9d92-b00f083195e4', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Active Record pattern in Rails, and what are its primary trade-offs?', N'Middle', N'Active Record maps database tables to objects, allowing developers to interact with data using an object-oriented syntax. A primary trade-off is that it can lead to ''fat models'' if business logic is not properly extracted into services, and it may hide complex SQL performance issues from developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'215387a1-91d5-4487-9a9d-b00f7ae76695', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the concept of ''write sharding'' and when it is necessary in a DynamoDB design.', N'Senior', N'Write sharding involves appending a random suffix to a partition key to distribute write operations across multiple physical partitions. This is necessary when a single partition key experiences write throughput that exceeds the limits of a single partition. The trade-off is that read operations become more expensive, requiring a scatter-gather approach across all potential shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad089ad8-b408-4d65-9ed3-b010e1ef40d1', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to verify the assumptions made during a requirements gathering phase?', N'Fresher', N'Assumptions can lead to incorrect project scope or technical debt if they are based on faulty premises. Verifying them with stakeholders ensures that the team is building the right features and avoids wasted effort on misunderstandings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'093a12fa-57b6-4bde-bae9-b011b5913ef4', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the _id field in MongoDB?', N'Intern', N'Every document in MongoDB must have a unique _id field that acts as its primary key. If a document is inserted without this field, MongoDB automatically generates a unique ObjectId to identify it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'629c4abf-149f-4375-858f-b01264dc8ac2', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is the JVM heap size configuration critical for Elasticsearch?', N'Middle', N'Elasticsearch is a Java-based application, and its performance is highly dependent on memory management. If the heap is too small, the system will trigger frequent garbage collection, leading to latency spikes; if it is too large, the system may run out of memory or suffer from extremely long garbage collection pauses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d9fa66-2d9a-4939-9202-b012bd87e26f', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary data model used by Redis?', N'Intern', N'The primary data model is the key-value store. Every piece of data is associated with a unique key, which acts as a pointer to the value stored in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
