INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4053785b-035e-4ed2-a763-b01581844198', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'In what scenarios would you choose ''interfaces'' over ''type aliases'' in a library architecture?', N'Senior', N'Interfaces are generally preferred for public-facing APIs because they support declaration merging and provide better error messages in IDEs. Type aliases offer more flexibility for complex unions and intersection types, but they do not support declaration merging, making them better suited for internal implementation details or complex type transformations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e6e63b9-e053-4af0-a372-b01795428514', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is method overriding in Ruby?', N'Fresher', N'Method overriding occurs when a subclass provides a specific implementation for a method that is already defined in its superclass. This allows the subclass to change or extend the behavior of the inherited method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93f77922-0b67-4caa-b70b-b0186a5147df', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between property binding and action handling?', N'Junior', N'Property binding is used to pass data down from a parent to a child, ensuring the child UI stays updated. Action handling is the process of sending notifications up from the child to the parent to request a state change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff1cf2fe-b133-4f67-b98a-b0190fb5cac8', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a decorator? How do I define my own?', N'Intern', N'Ans. A decorator is a function that adds functionality to another function without modifying it. It wraps another function to add functionality to it. A Python decorator is a specific change that we make in Python syntax to alter functions easily. $$$$$$$$$$$$$$$$$ Hi $$$$$$$$$$$$$$$$$ Decorators are an example of metaprogramming, where one part of the code tries to change another. For more on decorators, read Python Decorators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a7ff069-c037-4bcb-a5a1-b022290698a5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the benefit of null safety in Kotlin?', N'Intern', N'Null safety is a core feature designed to eliminate the danger of null references, often called the billion-dollar mistake. It forces developers to explicitly handle potential null values, which significantly reduces the frequency of runtime null pointer exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ba6b8d9-c16f-424a-af27-b022f3c4e1f0', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS''s fine-grained reactivity differ from the Virtual DOM reconciliation approach used by React?', N'Senior', N'React uses a virtual DOM to compare component trees and perform diffing when state changes, which often leads to re-executing entire component functions. SolidJS uses fine-grained reactivity where updates are pushed directly to the specific DOM nodes that depend on a signal, bypassing the need for a virtual DOM or full component re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5871a531-105b-4ce6-be77-b0248c4be619', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the role of a cache-miss penalty?', N'Middle', N'The cache-miss penalty is the additional latency introduced when an application must fetch data from the slow underlying storage because it was not found in the cache. Minimizing this penalty is a key goal of architecture design, often achieved by keeping the cache as close to the compute logic as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8597b7da-6d87-4d66-bcf8-b02879f78d9f', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the primary purpose of the Circuit Breaker pattern, and when should it be triggered?', N'Senior', N'It prevents a failure in one service from cascading throughout the system by stopping requests to an unresponsive downstream service. It should trigger when error rates or latency thresholds exceed predefined limits, allowing the system to fail fast and recover gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93d004f1-f6f5-404f-a353-b02aa59ae6dc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the default behavior of Fastify when an async handler throws an error?', N'Fresher', N'When an async handler throws an error, Fastify catches the rejection and automatically sends an error response to the client. This centralized error handling ensures that the server does not crash and provides consistent error messaging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
