INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c37717cf-ae3e-4d03-a069-b02bc6d97472', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the security implications of executing untrusted R code.', N'Senior', N'R''s dynamic nature, including its ability to execute arbitrary expressions and access the file system via base functions, makes it highly vulnerable to code injection attacks. Executing untrusted code should always be done in a sandboxed, restricted environment with limited permissions to prevent system-level compromise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89f64330-12de-4123-aa06-b02ca9d11eed', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the impact of Tailwind''s ''Content'' configuration on build performance in a monorepo structure?', N'Senior', N'The ''content'' array tells the JIT compiler where to look for class names; in a monorepo, if this is not scoped correctly, the compiler may scan too many unrelated files, leading to slow incremental builds. Proper configuration of these paths is essential for maintaining sub-second HMR (Hot Module Replacement) during active development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b72d3272-a7e1-464c-b067-b02dbaad86ea', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why would you choose to use a Service Object over placing business logic in an ActiveRecord model?', N'Middle', N'ActiveRecord models can become ''fat'' and difficult to test when they contain too much business logic, leading to violations of the Single Responsibility Principle. Service Objects encapsulate specific business processes, making the code more modular, easier to maintain, and simpler to unit test independently of the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2320d663-2105-4e0f-a9ca-b02ee7bf02f4', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What does it mean for a jQuery operation to be ''synchronous'' versus ''asynchronous'' in the context of AJAX?', N'Middle', N'Synchronous AJAX requests block the browser''s UI thread entirely, preventing user interaction until the server responds. jQuery defaults to asynchronous requests to keep the UI responsive, though historically it allowed synchronous requests, which are now deprecated due to poor user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'661576e8-d5ca-42ce-b960-b0303769cd4d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the advantage of monomorphization in Rust?', N'Middle', N'Monomorphization generates a unique copy of a generic function or struct for every concrete type used in the program. This allows the compiler to optimize the specific implementation for each type, but it comes at the cost of increased binary size and potentially longer compilation times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0ab5b1b-253f-44d5-a23c-b03091de3d53', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the impact of excessive actor spawning on the Actix runtime?', N'Senior', N'While actors are lightweight, spawning too many can lead to increased scheduling overhead and contention for the runtime''s task queue. Monitoring the number of active actors is essential to prevent performance degradation and ensure the event loop remains responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3baafb3b-df2e-494c-959f-b03362f28093', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Discuss the strategy for handling database migrations in a distributed Flask deployment.', N'Senior', N'Migrations should be executed as a pre-deployment step by a single container instance to avoid race conditions and schema corruption. The migration tool, such as Alembic, must be integrated into the CI/CD pipeline to ensure that the database schema is updated before the new application code is deployed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11847914-6079-490f-9c07-b033cc4a1633', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Dirty Read'' in transaction processing?', N'Fresher', N'A dirty read occurs when a transaction reads data that has been modified by another concurrent transaction but has not yet been committed. If the other transaction rolls back, the first transaction is left with invalid data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27f0aedb-df69-498c-8f01-b034481b29fc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a non-deterministic ''heisenbug'' in a distributed system?', N'Senior', N'I would implement comprehensive distributed tracing and correlation IDs to track request flows across services. By centralizing logs with high-resolution timestamps and comparing state snapshots across nodes, I look for race conditions or hidden dependencies on external side effects that might cause intermittent failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f074c89a-2489-4e8a-8715-b035d1300a49', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you account for team vacations and meetings when planning a project timeline?', N'Middle', N'I use the concept of ''available capacity'' rather than theoretical full-time hours. By calculating the actual working days minus holidays and estimated meeting loads, I derive a more realistic velocity that reflects the team''s true throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d3dffde-f607-4a07-b627-b038e2f9806d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass help in maintaining design tokens in a large-scale application?', N'Middle', N'Sass centralizes design tokens like spacing units, colors, and font sizes into dedicated configuration files. By referencing these variables throughout the application, you ensure consistency and enable global updates to the design system by modifying only a single source of truth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73fdaa2a-59da-4c74-acdb-b0392b24198c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of ''API Versioning'' in a web API?', N'Middle', N'API versioning allows you to evolve your API over time by maintaining multiple versions simultaneously, ensuring backward compatibility for existing clients. It is typically implemented via URL segments, query strings, or custom request headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e9dd181-321c-4be0-b5b4-b0392ea6a212', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do you mitigate the ''hot partition'' problem in a wide-column store like Cassandra?', N'Senior', N'The hot partition problem is typically addressed by refining the partition key design to ensure a more uniform distribution of data across the cluster. If the key space is inherently skewed, implementing a synthetic sharding strategy by appending a random suffix to the partition key can distribute load, though it requires client-side logic to query all shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad5b78b5-76c6-46f4-a735-b03f8ed66497', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you manage logging in a Flask application to ensure errors are captured in production?', N'Middle', N'You should configure the standard Python ''logging'' module to write logs to a file or an external aggregator like ELK or Sentry. Using proper log levels (INFO, WARNING, ERROR) ensures that you can filter for critical issues without being overwhelmed by excessive debug information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60568584-d002-4b2b-917f-b04219f72b0c', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does routing work in a Flask application?', N'Fresher', N'Routing is the process of mapping a specific URL to a Python function. Flask uses decorators to associate a URL pattern with a function, which then executes when that specific route is visited by a user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b027de69-793c-4ed1-bfbf-b042a5871d3b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Describe the relationship between Quarkus and GraalVM''s Substrate VM.', N'Senior', N'Substrate VM is the lightweight runtime used by GraalVM to execute native images. Quarkus leverages Substrate VM to replace the standard JVM, providing the ''closed-world'' execution environment necessary for compiling Java code into a standalone, optimized native executable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
