INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a351c329-2d42-4f06-96df-b048dda8e307', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .html() and .text() in jQuery?', N'Intern', N'The .html() method gets or sets the HTML content of an element, including any child tags. The .text() method retrieves or updates only the raw text content, automatically stripping away or ignoring any HTML tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a9f4604-281e-4011-9af5-b04aa49316cf', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it recommended to use Fastify''s built-in ''logger'' (Pino) instead of console.log in production?', N'Senior', N'Pino is designed for extreme performance and asynchronous logging, which prevents blocking the event loop during high-load scenarios. Console.log is synchronous in many versions of Node.js and can cause significant performance degradation when logging large amounts of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97cdb046-bc1f-4c11-9172-b04dcc79bb46', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Is Chi a full-fledged web framework like Django or Spring?', N'Intern', N'No, Chi is strictly a router and does not include built-in features like an ORM, template engine, or session management. It is designed to be a minimalist tool that lets developers choose their own libraries for other backend requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
