INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3fc7752-4a3d-4ef9-aa8c-b051c2abcc55', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of session management in PHP?', N'Junior', N'Sessions allow you to store user information on the server to be used across multiple pages. Because HTTP is stateless, sessions provide a way to maintain state, such as a user''s logged-in status or shopping cart contents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48960d39-2711-4c22-8866-b053460d05b0', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s Ivy compiler differ from View Engine, and what architectural benefits did it introduce?', N'Senior', N'Ivy is a complete rewrite of the Angular compilation pipeline that enables locality, meaning each component is compiled independently. This allows for better incremental builds, smaller bundle sizes through improved tree-shaking, and the ability to dynamically load components without needing a module-based entry point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8356b8b5-07ad-49c0-8da2-b053d5910645', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''Unit'' type?', N'Intern', N'The ''Unit'' type in Kotlin is equivalent to ''void'' in other languages. It indicates that a function does not return any meaningful value, and it is the default return type when none is specified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c35ffe10-784e-4ff6-9d07-b05424b2d4c6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is reselect and how it works?', N'Intern', N'_Reselect_ is a selector library (for Redux) which uses _memoization_ concept. It was originally written to compute derived data from Redux-like applications state, but it can''t be tied to any architecture or library. Reselect keeps a copy of the last inputs/outputs of the last call, and recomputes the result only if one of the inputs changes. If the same inputs are provided twice in a row, Reselect returns the cached output. It''s memoization and cache are fully customizable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9003c33a-ab09-4a64-b3d2-b0553b0801d5', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is serialization important in Fastify?', N'Junior', N'Serialization is the process of converting JavaScript objects into a string format for the HTTP response. Fastify uses schema-based serialization, which is much faster than standard JSON stringify because it knows the structure of the data beforehand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e93ba9b-17c9-43de-ba8e-b0578b98d50a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a task is too large to estimate effectively?', N'Middle', N'If a task cannot be clearly defined or requires more than a standard sprint to complete, it is likely an ''epic'' that needs further decomposition. I break it down into smaller, discrete units until each piece is well-understood and can be estimated with a high degree of confidence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba024074-29f8-4906-8fe0-b05843323f8b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary architectural goal of Apache Cassandra?', N'Intern', N'Apache Cassandra is designed to provide high availability and scalability across many commodity servers. It achieves this by being a distributed, decentralized database that eliminates single points of failure through a peer-to-peer architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e4246b9-db80-4c21-bd1a-b05a50d95404', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you handle user clicks in Alpine.js?', N'Fresher', N'You handle user clicks using the x-on directive, followed by the click event. For example, x-on:click allows you to execute a piece of JavaScript or update a state variable when the user clicks on an element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'507f7ba4-ef62-481b-9955-b05c7d5a7b86', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact achieve its small bundle size?', N'Intern', N'Preact achieves a small bundle size by implementing a subset of the React API and removing less commonly used features. It focuses on the essential core of virtual DOM rendering to keep the library footprint minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d876d92-46ef-4204-936f-b05d37f88c9e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When would you prefer an Eventual Consistency model over Strong Consistency?', N'Senior', N'Eventual consistency is chosen when high availability and low latency are prioritized over immediate data accuracy, such as in global distributed systems or social media feeds. Strong consistency is required for financial or inventory systems where the cost of reading stale data outweighs the benefits of reduced latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac7e0aa8-c8e2-4f1b-bb27-b05ffcfe0859', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the advantages and risks of using a hashed shard key?', N'Senior', N'A hashed shard key ensures a uniform distribution of data, preventing hotspots even if the input data is monotonic. The risk is that it makes range-based queries highly inefficient, as the query must be broadcast to all shards instead of being targeted to a specific subset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7161039f-b043-4022-8cce-b0600b41bda2', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the difference between ''Any'', ''Any?'', and ''Nothing'' in Kotlin.', N'Middle', N'Any is the non-nullable root of the Kotlin hierarchy, while Any? is the nullable equivalent that includes null. Nothing is a special type that has no instances and represents a computation that never completes, often used to indicate unreachable code or thrown exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73d69ca1-face-47c6-9245-b061abe33b6e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle CSS and style loading?', N'Middle', N'Remix uses a links function in each route to export a list of stylesheet URLs. Remix automatically manages these, injecting only the necessary CSS for the currently active routes, which helps reduce the total bundle size and prevents style collisions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0b7ee8d-b0d9-4cc9-904b-b061f9cdf252', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for debugging an error when the cause is not immediately obvious?', N'Fresher', N'I isolate the problematic area by testing smaller segments of the system to see where the output deviates from expectations. By narrowing down the scope, I can verify assumptions until I identify the specific point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4666d6e9-f5dc-4f60-a557-b0637eedea58', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle dependencies on other team members for your work?', N'Junior', N'I identify dependencies early in the planning phase and communicate clearly with the relevant team members about timelines. I check in periodically to see if there are any blockers on their end that might impact my schedule. Managing these relationships proactively helps avoid bottlenecks and keeps the project moving smoothly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c20cd463-1626-4c5e-9614-b0643749da67', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Is Alpine.js suitable for large, complex single-page applications?', N'Intern', N'Alpine.js is generally intended for smaller interactive components rather than massive single-page applications. While it is powerful, larger applications usually benefit from the structure and state-management tools provided by frameworks like Vue or React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52c6e437-d899-42e1-9edf-b06443bf2ef6', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle memoization to prevent unnecessary re-renders?', N'Middle', N'Preact provides a memo function that wraps components to perform shallow prop comparisons. If props remain unchanged, the component skips the re-render, effectively reducing the workload during state updates in complex UI trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f352f6ab-ea2a-4499-b6c4-b0649d0991d7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of ''Mixins'' in Ember, and why is the community moving toward composition instead?', N'Senior', N'Mixins allow code reuse by injecting methods and properties into classes, but they can lead to naming collisions and obscured dependency flows. Composition, through Services or utility functions, provides a clearer, more predictable way to share logic without the hidden side effects of inheritance-based mixins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02701069-7bf0-4270-8d93-b06739605113', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can Sass placeholders (%) be used to improve performance compared to standard classes?', N'Senior', N'Placeholders are only rendered in the compiled CSS if they are explicitly extended by another selector. This prevents the generation of unused CSS code, effectively acting as a ''silent'' base class that helps keep the final stylesheet clean and minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97acfe7d-6d2c-4d4d-94fe-b06781bb4cb3', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Can you use standard React hooks in Remix?', N'Junior', N'Yes, you can use any standard React hooks like useState or useEffect in your Remix components. Remix is built on top of React, so it supports all standard React features alongside its own data-loading utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5c4ad84-4147-4016-a246-b069998929f4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a Model and a Database Table?', N'Intern', N'A Model is a Python class that defines the structure and behavior of your data, acting as the single source of truth for information. A database table is the actual physical storage structure in your database where the data defined by the model resides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef5938b8-8e97-41bd-9bab-b06c8b8db27d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What criteria do you use to select a third-party library or framework for a project?', N'Junior', N'Evaluate the library based on community support, frequency of updates, documentation quality, and security track record. You should also consider how much the dependency locks you into a specific vendor or ecosystem and whether the core functionality is easy to replace later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed148e0e-906d-4119-83b2-b06eeda69852', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a pointer and a value type?', N'Intern', N'A value type holds the actual data, while a pointer holds the memory address of a value. Passing a pointer allows a function to modify the original data, whereas passing by value creates a copy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2d3e272-a778-4c1d-b895-b071f554e771', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the limitations of FastAPI''s request-response lifecycle when dealing with long-running tasks?', N'Senior', N'FastAPI is designed for HTTP request-response cycles and is not inherently built for long-running background processing. Attempting to run heavy computations or long tasks within a request handler will block the event loop or tie up worker processes, leading to timeouts; such tasks should be offloaded to a distributed task queue like Celery or Dramatiq.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'159b2067-a11d-4ccc-9989-b07587d0f5f2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the Gin Context object, and why is it passed by value?', N'Middle', N'The Context object stores request and response data, parameters, and metadata while providing helper methods for serialization. It is passed by pointer rather than by value to maintain consistency across the middleware chain and to avoid expensive memory copies during request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec7721d3-05f4-4f7e-9af4-b07ba0c04bce', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB''s read preference ''secondary'' affect application performance?', N'Middle', N'The ''secondary'' read preference directs read traffic to replica set members other than the primary. This helps offload read-heavy workloads from the primary, though it introduces the risk of reading stale data because of asynchronous replication lag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65f25c81-eb7f-47a7-b806-b07c1b7d79aa', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is ''code-splitting'' easier to implement in SvelteKit than in vanilla Svelte?', N'Middle', N'SvelteKit provides built-in routing that automatically splits code based on the file-system structure. This allows the application to load only the necessary code for the current route, significantly reducing the initial bundle size compared to a manually configured single-page application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0cd0f07-cfef-4348-a365-b07cd172bfe4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Discuss the impact of Method Inlining on the JIT compiler''s ability to optimize code.', N'Senior', N'Inlining is the process of replacing a method call with the body of the called method, which eliminates call overhead and exposes the code to further compiler optimizations like constant folding and dead code elimination. It is arguably the most critical optimization phase, as it expands the scope of analysis available to the JIT compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330b72a0-85c2-47a9-9177-b080325a34d0', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify support testability in a modular backend architecture?', N'Middle', N'Fastify provides built-in testing utilities that allow developers to inject requests into the server instance without actually starting a network socket. This makes unit and integration testing significantly faster and more reliable by avoiding the overhead of network I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46b4695-a473-4a6a-8305-b0822a6f8fb9', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s reactivity system handle nested objects versus shallow reactive objects, and what are the performance trade-offs?', N'Senior', N'Vue uses Proxy-based reactivity to recursively track properties. While deep reactivity provides convenience, it incurs overhead during initialization and memory consumption; shallow reactivity is a performance optimization used to bypass deep observation for large, read-only data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ec15a0-9860-438e-bf15-b08519685e15', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of a message schema registry in an event-driven architecture?', N'Middle', N'A schema registry manages versioned data contracts for messages, ensuring that producers and consumers can communicate safely. It prevents breaking changes where a producer changes the message structure, which would otherwise crash existing consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f30e46df-9fef-44a9-bcda-b0853cc1ff9a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between an HTTP GET and an HTTP POST request?', N'Intern', N'GET requests are used to retrieve data from a server and should not modify the state of the resource. POST requests are used to send data to the server to create or update a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'402ede7e-0cc0-4ec0-a139-b086ef582835', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle URL path parameters?', N'Intern', N'Gin uses colon-prefixed tokens in the route path to define parameters. These parameters can be easily retrieved from the context object by name during the request handling process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7f3e822-4ab5-4de7-837c-b086f40c6aba', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the trade-offs between using a polymorphic association versus Single Table Inheritance (STI) in Rails.', N'Senior', N'Polymorphic associations allow a model to belong to more than one other model on a single association, providing flexibility at the cost of database integrity as foreign keys cannot be constrained. STI keeps all subclasses in one table, simplifying queries, but often results in sparse tables with many null columns and potential normalization issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ff2e180-bf45-4f6f-9676-b0881bb3d8ee', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the role of backpressure in a reactive microservices architecture.', N'Senior', N'Backpressure is a mechanism that allows a consumer to signal to the producer that it is being overwhelmed by data volume. By regulating the flow, it prevents system failure and memory exhaustion in downstream services, ensuring overall system stability under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c40244-d98e-4be6-9307-b08c52890146', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between ''render'' and ''redirect'' in a controller?', N'Junior', N'Rendering returns a template or JSON response directly to the client within the same request-response cycle. Redirecting tells the client''s browser to make a new, separate HTTP request to a different URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b6a7fa7-5de0-4907-86d9-b08ccbb9bc76', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary risk of adopting Tailwind in a team that lacks strong CSS fundamentals?', N'Senior', N'Developers might treat Tailwind as a shortcut and fail to understand the underlying CSS properties, leading to inefficient layouts or accessibility issues. A strong grasp of the CSS box model and positioning is still required to use the utility classes effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81437664-0f63-4d29-bab3-b08f1f6833cc', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the trade-offs of using @Transactional at the class level versus the method level?', N'Senior', N'Class-level configuration applies transaction settings to all public methods, which is convenient but can lead to unintentional transaction overhead. Method-level configuration provides granular control, allowing specific methods to override default propagation or isolation levels based on specific business requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e93a22e-472c-448f-90f0-b091365fbaa8', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is the ''View Transitions'' API important in Astro?', N'Middle', N'View Transitions allow developers to create seamless page transitions and persistent UI elements without a full browser reload. This provides a Single Page Application (SPA) feel while maintaining the benefits of a multi-page architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55fedbd4-f717-4a0b-9f2a-b091b386a660', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why might you prefer using a message queue over direct HTTP communication between services?', N'Middle', N'Message queues enable asynchronous communication, which decouples services and increases system resilience. If a downstream service is temporarily unavailable, the message queue buffers the requests, preventing data loss and allowing for retries without impacting the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeefd5a8-11c8-4f81-bb15-b0938380bba0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary difference between a Row Cache and a Key Cache?', N'Middle', N'A Key Cache stores the mapping of partition keys to their locations in SSTables, speeding up disk lookups. A Row Cache stores the actual content of frequently accessed rows in memory, which can significantly reduce read latency but consumes significantly more heap space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd952f74-7d35-4140-b44e-b093bf6758a8', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''volatile'' keyword in concurrent programming?', N'Middle', N'The volatile keyword ensures that any thread reading a variable sees the most recent write by any other thread by forcing access directly from main memory. It prevents the compiler and processor from caching the variable in a CPU register or local thread cache. However, it does not guarantee atomicity for compound operations, only visibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49bd72c5-6d10-411b-a1fe-b094d7de3642', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is Tailwind CSS a component library?', N'Intern', N'No, Tailwind is a utility-first CSS framework, not a component library. It provides the building blocks for styling, but you are responsible for creating your own components like buttons or navigation bars using those utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'953e36d0-280c-42c1-b1bf-b095051a6944', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ''OpenAPI/Swagger'' integration impact the development lifecycle of an API?', N'Senior', N'OpenAPI provides a standardized contract for APIs, enabling automatic documentation and client SDK generation. This improves team productivity by ensuring the documentation remains in sync with the code and simplifies the testing process for front-end developers and external consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52a20245-30bc-4af5-9764-b099c5f58727', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'When would you choose a log-based messaging system like Kafka over a traditional queue like RabbitMQ?', N'Senior', N'Choose a log-based system when you require message replayability, long-term persistence, and high-throughput streaming capabilities where multiple independent consumers need to read the same data stream. Use traditional queues when your primary requirements are low-latency task distribution, complex routing patterns, and immediate acknowledgement of individual message completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f0c0331-38d1-408e-91f8-b09d10b76487', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s approach to data validation compare to library-agnostic validation patterns?', N'Senior', N'Echo''s validation is usually tied to the binding process, making it convenient but less decoupled from the framework. Using a library-agnostic validator allows for the same validation rules to be applied in background workers or CLI tools, promoting better code reuse outside of the HTTP layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
