INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfb732ad-bace-4510-bb7c-b0a8678746aa', N'954a0331-deff-4399-b588-96f39fec001d', N'Why would an architect choose to use ''Module Federation'' in a large-scale enterprise Angular project?', N'Senior', N'Module Federation allows for the creation of Micro-frontends by enabling separate builds and deployments of independent application pieces. It solves scalability issues in teams by allowing independent release cycles and reducing the blast radius of potential bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f41f2237-47ba-4959-a6d7-b0a932d5b9ad', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the difference between clustered and secondary indexes in InnoDB.', N'Middle', N'A clustered index physically orders the data rows in the table based on the primary key, meaning there is only one per table. Secondary indexes store the primary key value alongside the index key, requiring a second lookup to retrieve the full row data from the clustered index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
