INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8ee16b4-a4d0-4637-acf8-b0ae3c13bde2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are the risks of overusing the ''renderRoot'' property to return ''this''?', N'Middle', N'Returning ''this'' as the renderRoot bypasses Shadow DOM, rendering the component''s template directly into the light DOM. This risks style collisions with global CSS and makes the component''s internals public, negating the encapsulation benefits that come with Web Components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63c842ec-fc97-47f7-8c77-b0aedad40679', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis ''Pub/Sub'' system?', N'Intern', N'Pub/Sub stands for Publish/Subscribe. It is a messaging pattern where senders publish messages to channels and receivers subscribe to those channels to receive updates instantly, facilitating real-time communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c49f489b-7eec-4122-944a-b0b2192f62c9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using the Quarkus ''Panache'' library?', N'Middle', N'Panache simplifies the data access layer by providing an active record or repository pattern that reduces boilerplate code. It abstracts complex JPA or Hibernate operations, allowing developers to write more expressive and concise data manipulation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4f9eaf8-92de-4537-b3f7-b0b2a0191deb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage the lifecycle of beans with circular dependencies?', N'Senior', N'Micronaut generally discourages circular dependencies, but it handles them during the dependency injection phase by using lazy-loading proxies for specific beans. This allows the container to resolve the graph structure even when dependencies are intertwined, preventing initialization deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0945709f-dc18-4b11-b54f-b0b77bff7b08', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Describe the impact of Kotlin''s ''star-projection'' on type safety and reflection.', N'Senior', N'Star-projection acts as a safe wildcard that allows reading from a generic type while treating it as having an unknown type argument, preventing unsafe write operations. While it maintains a degree of type safety, it can limit the functionality of reflection-based libraries that need to inspect or instantiate generic types at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de593f0e-ba5b-40d9-85bd-b0b975c711c0', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s ViewEncapsulation.ShadowDom differ from ViewEncapsulation.Emulated?', N'Senior', N'Emulated encapsulation uses CSS attribute selectors to simulate scope, which is highly compatible but can be bypassed by global styles or deep selectors. ShadowDom uses the native browser Shadow DOM API for true style isolation, providing better security against global style leakage but potentially causing issues with third-party libraries that expect global CSS access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efc31a79-0a70-4b82-9663-b0bb57bb51b4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''const assertions'' affect the inference of object properties and arrays?', N'Senior', N'Const assertions treat expressions as immutable, meaning literals are inferred as literal types rather than widened to their primitive types. This is essential for scenarios like state machines or configuration objects where the exact value is required for type narrowing rather than just the general type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26aa26bf-18fe-45f4-86e6-b0bcc75f233b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a Document in MongoDB?', N'Intern', N'In MongoDB, a document is the basic data storage unit. It''s a JSON-like structure that stores data in key-value pairs known as fields. Document Structure Each document: - Is a top-level entity, analogous to a row in a relational database. - Is composed of field-and-value pairs, where the value can be a variety of data types, including arrays or sub-documents. - Has a unique _id or primary key that is indexed for fast lookups. Here is the document structure: Collections Documents are grouped into collections. Each collection acts as a container with a unique namespace within a database. Collections don''t enforce a predefined schema, which allows for flexibility in data modeling. Key Advantages 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dea8d93c-24ee-444c-bf9a-b0bd721d51d8', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of the ''Ctx'' object in Fiber, and how does it differ from ''http.ResponseWriter''?', N'Middle', N'The ''Ctx'' object is a unified context that encapsulates both the request and the response, providing intuitive methods to read and write data. Unlike the standard library where you interact with an interface and a stream separately, Fiber''s context provides a high-level API for parameters, headers, and cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4278760c-90a0-49f2-9a1e-b0c18b3b886f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What does $(this) refer to inside a jQuery event handler?', N'Junior', N'$(this) is a jQuery-wrapped version of the current DOM element that triggered the event. It allows you to use jQuery methods on the specific element that was clicked or interacted with.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28677e9d-db91-4142-85f4-b0c2b556c56f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why does TypeScript use ''readonly'' instead of ''const'' for properties?', N'Middle', N'Const is a variable declaration keyword that prevents the reassignment of a variable reference. Readonly is a modifier used within interfaces or classes to prevent the reassignment of specific properties on an object, even if the object reference itself is mutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77cb44f8-6874-45fb-ada7-b0c38d640c0b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach designing a system that must comply with strict data residency laws?', N'Senior', N'I would architect the system with regional data silos, ensuring that user data is stored and processed exclusively within specified geographic boundaries. I would use localized database instances and infrastructure-as-code templates to deploy compliant environments in each required region while maintaining a global management plane.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b548827-5b00-4f63-8594-b0c6cf6e22e4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the C ''ABI'' (Application Binary Interface) in system integration?', N'Senior', N'The ABI defines the low-level rules for function calls, register usage, and data structure padding, ensuring that compiled modules from different sources can interoperate correctly. A stable ABI is critical for library maintenance, as it allows updates without requiring a full recompilation of dependent applications. When designing cross-language interfaces, developers must strictly adhere to the C ABI to prevent alignment errors and stack corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7defd750-8137-4d10-8c4f-b0c80308adb9', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the advantages of Echo''s performance?', N'Fresher', N'Echo is optimized for speed by using a highly efficient routing algorithm and minimizing memory allocations. Its small footprint and focus on Go''s strengths make it faster and more resource-efficient than many larger, full-featured web frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e56c6397-9546-49f9-91e6-b0c99c6f6d96', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s middleware chain implementation differ from standard net/http middleware, and what are the architectural implications?', N'Senior', N'Echo uses a specific execution chain where middleware is wrapped and executed sequentially using a handler function pattern. This allows for cleaner context propagation and easier control flow, though it requires developers to strictly follow the chain execution pattern to avoid breaking the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e227355-3ec0-416a-abef-b0c9f036596b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the implications of using an Unlogged table in a database?', N'Senior', N'Unlogged tables bypass the Write-Ahead Log, significantly increasing write performance by avoiding disk synchronization. However, they are not crash-safe and are automatically truncated upon server restart, making them suitable only for transient data or temporary scratch work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a776fd8-e3fd-4044-be91-b0ca2ec80b64', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''Convention over Configuration'' mean in Ember?', N'Intern', N'This principle means that Ember makes reasonable assumptions about how an application should be structured, reducing the need for developers to write boilerplate code. By following Ember''s naming conventions, the framework automatically understands how components, routes, and models relate to each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17bc4321-91a1-459a-a8c2-b0cb4d2ec1e3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you stop an event from bubbling up in jQuery?', N'Junior', N'You can stop event bubbling by calling the .stopPropagation() method on the event object passed to your handler. This prevents the event from triggering listeners on parent elements in the DOM tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97798e23-5983-426f-b932-b0cbb26711b8', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How can you implement error handling in Hono effectively?', N'Middle', N'Hono provides a built-in ''onError'' hook that allows for centralized error handling across the entire application. By defining a global error handler, you can catch exceptions, log them, and return standardized JSON responses to the client without repetitive try-catch blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fad39a1-049b-46f9-8758-b0cbfd483642', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Jinja2 templates in Flask?', N'Fresher', N'Jinja2 is the templating engine used by Flask to generate dynamic HTML pages. It allows developers to embed Python-like expressions, logic, and variables directly into HTML files, which Flask renders before sending them to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f73d30e7-2701-4c6f-ac29-b0cd32b1c81a', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between horizontal and vertical scaling?', N'Middle', N'Vertical scaling involves adding more resources like CPU or RAM to an existing server, which is simpler but has a hard upper limit. Horizontal scaling involves adding more machines to the pool, which offers better fault tolerance and infinite scalability but increases system complexity regarding data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd03cb0af-214d-4169-a6a7-b0d459a9df9d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Depends'' object in FastAPI, and how does it relate to the Single Responsibility Principle?', N'Senior', N'The ''Depends'' object decouples route handlers from their infrastructure requirements. By injecting dependencies, route handlers remain focused on business logic, adhering to the Single Responsibility Principle, and making the code significantly more maintainable and testable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e797cc1-a625-4f54-9cf4-b0d5cabbc84c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you handle errors in asynchronous operations?', N'Fresher', N'To handle errors in asynchronous operations, you can use try...catch blocks with async/await syntax or .catch() method with Promises. For example, with async/await, you can wrap your code in a try...catch block to catch any errors: With Promises, you can use the .catch() method: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of a microtask queue The microtask queue is a queue of tasks that need to be executed after the currently executing script and before any other task. Microtasks are typically used for tasks that need to be executed immediately after the current operation, such as promise callbacks. The microtask queue is processed before the macrotask queue, ensuring that microtasks are executed as soon as possible. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c37d785a-1d67-40ec-b583-b0d607bfba4a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does database normalization aim to achieve?', N'Junior', N'Normalization is the process of organizing data to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables to ensure that each piece of data is stored in only one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'323e62a1-053e-4c01-b121-b0d63ee25d4c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is Ecto and how does it relate to Phoenix?', N'Fresher', N'Ecto is the database wrapper and query generator used by Phoenix applications. It manages the connection to the database and allows developers to interact with data using a functional approach, handling tasks like schema definitions and migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f5f929b-f9fd-44cb-a5b7-b0d8001abeec', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Are transactions supported in all NoSQL databases?', N'Junior', N'No, many NoSQL databases prioritize availability and scalability over strict ACID transactions. While some modern NoSQL systems have introduced multi-document transaction support, many remain limited to single-document atomicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f1aac73-adc0-41fd-97fa-b0dbf0a0cbcd', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the importance of the return type in a function?', N'Junior', N'The return type tells the compiler what type of data the function will pass back to the caller. If a function does not return a value, it must be declared with a void return type to prevent errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b92fc40c-87b6-4181-91d0-b0e28e80bac7', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of build-time metadata processing in Quarkus?', N'Fresher', N'Quarkus performs dependency injection and configuration processing during the build phase rather than at runtime. This reduces the work the application needs to do when it starts, leading to significantly faster initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c623b326-fbe6-4e4f-a4f9-b0e3d245e2bb', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the role of a message queue in system architecture.', N'Middle', N'A message queue acts as an intermediary that allows services to communicate asynchronously by decoupling the producer of a message from the consumer. This improves system resilience and performance by buffering traffic spikes and allowing the consumer to process tasks at its own pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28368e56-94d3-4bb7-b9a2-b0e46d124f68', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing for fault tolerance, how do you determine the appropriate retry policy for failed network requests?', N'Middle', N'I implement exponential backoff with jitter to prevent overwhelming the downstream service during a recovery period. This prevents the thundering herd problem and allows the system to recover gracefully from transient network issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bb46810-ce6e-44cb-a83b-b0e551783b22', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between Constructor Injection and Field Injection.', N'Middle', N'Constructor injection is considered best practice because it ensures that a bean is fully initialized with its dependencies before use and facilitates immutability. Field injection is simpler to write but makes unit testing harder and hides dependency requirements, making it generally discouraged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce579ce8-86a0-41d9-af1d-b0e55db269e8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is an async function', N'Intern', N'An async function is a function declared with the async keyword which enables asynchronous, promise-based behavior to be written in a cleaner style by avoiding promise chains. These functions can contain zero or more await expressions. Let''s take a below async function example, It is basically syntax sugar over ES2015 promises and generators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4df92db-db84-4b77-8f1f-b0e579eff87d', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the Micronaut ''Context'' and how is it managed?', N'Middle', N'The ApplicationContext manages the lifecycle of all beans, configuration, and event publishing within the application. It is initialized once during startup and provides the infrastructure for dependency lookup and dependency injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e960d76f-7c50-4a2d-bd6a-b0e5b77c8c74', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''OpenAPI'' documentation in Litestar?', N'Intern', N'Litestar automatically generates OpenAPI documentation based on route definitions and type hints. This provides an interactive user interface for testing endpoints and serves as a formal contract for API consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4165252-7587-484b-ba0e-b0e72e38669b', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why would you check the network tab of your browser developer tools when investigating a web application bug?', N'Junior', N'The network tab shows all outgoing requests and incoming responses, allowing me to see status codes, payload content, and latency. This helps me confirm if the server is returning the expected data or if the request is failing due to an incorrect URL, bad headers, or server errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3812ee5d-9e86-495f-8c1a-b0eab554dcab', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you define a route parameter in Chi?', N'Junior', N'Route parameters are defined using curly braces, such as {id}. These values can then be retrieved within the handler by using the chi.URLParam function with the request context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab66c566-5430-476b-b2bc-b0eb23133dba', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the refresh operation?', N'Junior', N'The refresh operation makes the changes made to an index available for search. Without a refresh, newly indexed documents would not be discoverable by search queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90afd3f3-d669-49d8-952a-b0ec8c1d4706', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does nesting work in Sass?', N'Intern', N'Nesting allows you to write CSS selectors in the same visual hierarchy as your HTML document. It helps reduce code repetition and makes the relationship between parent and child elements much clearer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abdedbdd-53b0-40c6-a6d9-b0ed781dc880', N'075b8862-431c-4678-9767-f55359758a4a', N'How does ''Suspense'' improve the UX of asynchronous component loading?', N'Senior', N'Suspense manages the loading states of nested asynchronous component trees, allowing developers to show fallback UI while waiting for asynchronous dependencies to resolve. This centralizes error and loading handling, preventing layout shifts and providing a smoother user experience during data-fetching operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfdffe26-78a0-4d32-8630-b0ef8018c9cc', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber support standard Go http.Handler interfaces?', N'Intern', N'Fiber is not natively compatible with the standard library http.Handler interface because it is built on Fasthttp. While you can use adapters to bridge the two, the framework is designed to work primarily with its own internal request and response types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d461c6e-a4ba-4ad9-8254-b0f1ca11498e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle panics, and why is this important for production services?', N'Middle', N'Gin provides a built-in Recovery middleware that captures panics occurring during request handling. Without this, a single unhandled panic would crash the entire server process; the recovery middleware ensures the server remains stable by logging the error and returning a 500 status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb14eccb-773f-4c3d-912e-b0f4095d90bf', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between NULL and an empty string?', N'Junior', N'A NULL value represents the absence of a value or an unknown state in a column. An empty string is a valid value with a length of zero, which is treated as data rather than the lack of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'438a3c70-9b55-45d2-87fa-b0f8657a4e6f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the concept of Dependency Injection in ASP.NET Core.', N'Fresher', N'Dependency Injection is a technique to achieve Inversion of Control between classes and their dependencies. It allows the framework to automatically provide required services to a class, promoting loose coupling and making the code easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f447aa76-5b5b-43b3-89f1-b0f939f045e2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Discuss the trade-offs of using fixed-size buffers versus dynamic allocation in high-performance C systems.', N'Senior', N'Fixed-size buffers provide deterministic memory usage and avoid the overhead of heap management, making them ideal for real-time systems where jitter must be minimized. Conversely, dynamic allocation offers flexibility for varying workloads but introduces risks like fragmentation and the overhead of allocator synchronization. Choosing between them requires a careful analysis of the system''s memory constraints and performance requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bda5eb8-80d5-46dc-a26b-b0fa76815a7c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of Remix''s ''Remix.config'' approach regarding deployment flexibility?', N'Senior', N'The configuration system abstracts the build process, allowing the same codebase to be deployed to diverse environments like serverless functions or traditional servers. This decoupling of the application code from the deployment target is critical for modern infrastructure-as-code workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edf9b54a-ef32-4310-b6a1-b0fb2db03346', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s ''adapter'' architecture?', N'Middle', N'The adapter architecture decouples the application code from the specific deployment platform. By swapping adapters, you can deploy the same codebase to diverse environments like Vercel, Netlify, or standard Node.js servers without modifying your core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4c7a133-98eb-4362-bdce-b0fc43607484', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle TypeScript files?', N'Junior', N'Vite performs transpilation on TypeScript files to remove types and output standard JavaScript. Note that Vite only performs this transpilation and does not perform type checking, which should be handled by a separate process like your IDE or a CLI command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35fd53c1-1b45-4822-9723-b0fde81f3dbf', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Can you explain the purpose of optionals in Swift?', N'Junior', N'In Swift, optionals are a special type that represents either a valid value or no value at all. Merging the best of both Objective-C''s nullable references and Swift''s type safety, they contribute to modern Swift''s safety and flexibility. Key Features of Optionals - Safety First: They assist in managing nil or null pointer-related operations and prevent common programming errors, such as directly accessing a nil object or referencing an uninitialized pointer. - Clarity and Intention: The presence of an optional in a type declaration transparently conveys the possibility of a nil value. - Flexibility in Initialization: Variables are often initialized as nil and only assigned a value later based on certain conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e66dc4d-b0b8-43dd-86c4-b101b28e135f', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are JIT (Just-In-Time) mode features in Tailwind?', N'Intern', N'JIT mode generates CSS on-demand as you author your HTML, rather than generating all possible CSS variations at the start. This results in significantly faster build times and allows for arbitrary value support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fadad513-4ffe-4cf1-a1bd-b101b7de42c6', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite perform code splitting compared to traditional methods?', N'Senior', N'Vite leverages Rollup’s advanced chunking algorithms, which automatically identify shared dependencies and move them into separate chunks to reduce load times. It also supports dynamic imports via the standard JavaScript import() syntax, which Vite treats as a trigger to automatically split the code into a separate bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4465891d-f8eb-4f59-b3a9-b1035b4bb989', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web ensure thread safety when using multiple workers?', N'Senior', N'Actix-web uses a shared-nothing architecture for worker threads, where each worker manages its own request-processing loop. Shared data is typically protected by ''Sync'' and ''Send'' constraints enforced by the compiler, ensuring that state shared across threads is safe for concurrent access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd035286f-5bdd-4faf-bb03-b105807c30ed', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is the finalizer mechanism considered harmful for high-performance systems?', N'Senior', N'Finalizers run on a dedicated low-priority thread, which can lead to accumulation of objects waiting for finalization, causing heap pressure and potential OOM errors. Furthermore, because finalization is non-deterministic and can resurrect objects, it introduces significant complexity and performance bottlenecks compared to the Cleaner API or try-with-resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3b2c328-4c16-4efd-b06d-b105d2dfce72', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are Micronaut ''Profiles''?', N'Junior', N'Profiles are templates used by the Micronaut CLI to generate boilerplate code for specific types of projects, such as a CLI application, a microservice, or a function. They help developers quickly set up the necessary project structure and dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708dc10b-3802-4d34-b620-b10aafd26caf', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to include testing and documentation in your task estimates?', N'Fresher', N'Testing and documentation are integral parts of a complete deliverable, not optional extras. If they are excluded, the estimate will be artificially low and won''t reflect the true cost of completing a high-quality task. Including them ensures the project timeline remains accurate and that the final output meets quality standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4fc7862-b559-4549-a978-b10b04f67965', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle cookies and session management?', N'Middle', N'Express requires external middleware like cookie-parser to read cookies from requests. For session management, developers typically use express-session, which stores session data in a server-side store, such as Redis or a database, and uses a signed cookie to identify the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f90a2852-50ed-4a38-b111-b10b0c2fb788', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle CSS styling?', N'Fresher', N'Svelte scopes CSS styles to the component by default. During compilation, it attaches a unique class to the elements within the component, ensuring that styles do not leak out or affect other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47874fc6-c169-4570-a807-b10b148331d7', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does index cardinality affect query performance for JOIN operations?', N'Senior', N'High-cardinality indexes allow the optimizer to more accurately estimate the number of matching rows, which is crucial for choosing the most efficient join algorithm, such as nested-loop versus hash joins. Low-cardinality indexes provide little benefit, often leading the optimizer to ignore them entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d52a6c8-bd35-469a-a8e3-b10c718dbc73', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go use a ''main'' package?', N'Junior', N'The ''main'' package is a special package name that signals to the Go build system that this package should be compiled into a standalone binary. Without this package, the compiler would not know how to generate an executable file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4ac03f1-e639-4f56-9f40-b10ed049e1f0', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the benefit of using ''Pattern Matching'' in Scala?', N'Junior', N'Pattern matching allows you to check a value against a series of patterns and execute code based on the match. It is much more readable and safer than long chains of if-else statements, especially when dealing with complex data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f3bfd1e-6934-4966-9a4f-b10ef89c1423', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin''s routing handle path parameter extraction, and how does it compare to query parameter parsing?', N'Senior', N'Path parameters are parsed during the tree traversal phase, making them highly efficient and available as part of the routing result. Query parameters require parsing the URL string, which is slightly more expensive; for high-performance endpoints, path parameters should be preferred for identifiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98cc9712-0a8e-405c-b7f4-b1104fdd93eb', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the best way to handle ''Not Found'' and ''Method Not Allowed'' scenarios in Chi?', N'Senior', N'Chi allows for custom handler overrides for 404 and 405 errors, which should be configured on the router instance. This allows for consistent, API-compliant error responses across the entire application, ensuring that clients receive structured data instead of default plain-text responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fba0cb25-395c-4566-a7e8-b110cd5a7c6e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary role of a MongoDB primary node?', N'Junior', N'The primary node is the only member in a replica set that receives all write operations. All data changes are recorded in the primary''s operation log, which secondaries then replicate to maintain data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2b0a70b-5fff-4ffa-bf97-b1113f6d374e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with an error message you have never seen before, what is your strategy?', N'Fresher', N'I start by reading the error message carefully to identify the component or operation that triggered it. I then use official documentation or internal knowledge bases to understand the underlying cause. If that fails, I use search engines to see if others have faced similar issues, ensuring I understand the solution rather than blindly copying it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e9259d-69b1-4692-92bb-b112f8482698', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Describe the benefit of using Route Groups in Next.js.', N'Senior', N'Route Groups allow you to organize routes into logical folders without affecting the URL structure. This is useful for grouping related routes that share different layouts or for managing complex application folder structures without exposing internal organization to the public URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3e69fd8-6923-4819-a3bd-b11393919c22', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''RAILS_ENV'' environment variable?', N'Fresher', N'It specifies the environment in which the application is running, such as development, test, or production. Each environment typically uses different configurations, such as separate databases and logging levels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d3135a4-b58a-46fd-b420-b113f4957d09', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the significance of the ''Future'' trait in Actix''s design?', N'Senior', N'The Future trait is the cornerstone of Actix''s asynchronous execution, representing a value that may not be available yet. It allows the runtime to poll for progress, enabling the system to switch tasks efficiently while waiting for I/O, timers, or other actors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7592b846-456a-49bc-aa13-b1142633f571', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a schema in database design?', N'Intern', N'A schema is the formal structure or blueprint of a database. It defines how data is organized, including the tables, fields, data types, and the relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7fc7d88-91da-4b9b-82c4-b116108de5fc', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the significance of ''Readiness'' and ''Liveness'' probes in container orchestration?', N'Senior', N'Liveness probes determine if a container needs to be restarted, while readiness probes determine if it can accept traffic. Misconfiguring these can lead to ''flapping'' or traffic being routed to non-functional instances, both of which severely degrade system reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
