INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14986927-a184-4965-a573-b11a753d17a0', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix ensure fault tolerance during request handling?', N'Middle', N'Phoenix relies on the ''let it crash'' philosophy provided by the Erlang VM supervision trees. If a process handling a specific request encounters an error, the supervisor can restart that process to a known good state without affecting other concurrent requests or the overall health of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
