INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e90d9d91-a0cd-4807-8b96-b138b7f5d65c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does it mean that everything in Ruby is an object?', N'Intern', N'In Ruby, even primitive data types like integers, floats, and booleans are instances of classes. This means every value has methods and properties that can be called, providing a uniform way to interact with data throughout the language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd72a3ed8-ba37-44fb-a3b1-b13981d1fabd', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a Column-oriented NoSQL database?', N'Fresher', N'A column-oriented database stores data in columns rather than rows, which makes it highly efficient for reading specific attributes across massive datasets. This structure is particularly useful for analytical tasks and high-performance querying of large-scale distributed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc86a5b2-32e5-4d24-9662-b13b9467e2b2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How should a team handle accessibility (a11y) when using Tailwind?', N'Middle', N'Accessibility is handled by ensuring that the underlying HTML structure is semantic and accessible, regardless of the styling framework. Tailwind provides utilities for focus states, screen-reader-only text, and color contrast, but the developer remains responsible for ensuring the final component follows WAI-ARIA standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b94ec5fd-50da-4341-b2d3-b13d9644d4ad', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are attribute accessors in Ruby?', N'Fresher', N'Attribute accessors are helper methods like ''attr_reader'', ''attr_writer'', and ''attr_accessor'' used to automatically generate getter and setter methods for instance variables. This reduces boilerplate code significantly when defining class attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'391aaf8a-1bbb-4da2-99d7-b13dacb0c5ca', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of using Preact for mobile devices?', N'Intern', N'Because of its small size, Preact reduces the amount of JavaScript that needs to be downloaded, parsed, and executed by a browser. This leads to faster page load times and better performance on mobile devices with limited processing power or slower network connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72927bf6-84ca-4d63-8465-b1409a0ef4a8', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle JSON responses?', N'Fresher', N'Echo provides a built-in JSON method within the Context object that automatically serializes a Go struct or map into a JSON string. It also sets the correct Content-Type header to application/json automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc1ac12e-78f9-41cf-9c27-b140acfa1dc2', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go detect and handle stack overflows?', N'Senior', N'Go inserts a small preamble at the start of every function that checks the available stack space against the current requirement. If the space is insufficient, the runtime triggers a stack growth procedure, preventing traditional segmentation faults caused by stack exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'792119d8-376d-4026-a4a6-b14162d4a298', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the ''Database-per-Service'' pattern.', N'Middle', N'This pattern requires that each microservice has its own private database to ensure loose coupling and independent deployment. It prevents services from sharing data through the database layer, which would otherwise create a hidden dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da1aae51-cf85-4176-bc68-b1417112eb5e', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the role of the ''Model'' hook in Ember routes and how it manages asynchronous data fetching.', N'Senior', N'The model hook is the designated place to initiate data fetching before a route renders. It automatically handles promises, ensuring that the transition to the next route waits until the data is resolved, preventing flickering or incomplete UI states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0589ec05-f836-4a71-9c47-b1421566855e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte manage server-side rendering (SSR) and hydration compared to traditional hydration-heavy frameworks?', N'Senior', N'Svelte''s SSR generates static HTML strings directly from components. During hydration, it attaches event listeners, but because the compiled code is already aware of the DOM structure, it avoids the expensive ''re-hydrating'' the entire tree, resulting in faster Time to Interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbf5de5a-d7cc-4c51-aa0a-b1448231444a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi manage routing groups?', N'Fresher', N'Chi allows you to group routes that share a common URL prefix or middleware set using the Route method. This helps in organizing code logically and applying specific configurations to sub-sections of an API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'443fdf63-17b0-4d47-bdcc-b14512158293', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is it often preferred to use ''lifting state up'' instead of complex component hierarchies?', N'Senior', N'Lifting state up simplifies data flow by centralizing the source of truth, which makes debugging and state synchronization easier. It avoids the complexity of passing callbacks through multiple layers and reduces the likelihood of state desynchronization across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8984e9d3-1905-47e3-a56c-b14657b76c8b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the limitations of Spring''s @Async annotation?', N'Senior', N'@Async only works on public methods and must be invoked from outside the class containing the method to trigger the proxy mechanism. Additionally, it requires a properly configured TaskExecutor to prevent unbounded thread creation, which can lead to OutOfMemory errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b89d41a2-079f-4c39-aa30-b146c180c187', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the significance of the ''Startup'' class being replaced by the ''Program'' file in modern .NET versions.', N'Senior', N'The transition to a unified Program.cs file simplifies the application entry point and reduces boilerplate code. By using the Minimal APIs hosting model, developers can configure services and the middleware pipeline in one place, which is more intuitive and aligns with modern cloud-native development practices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd97f2e33-d02a-4d7f-b392-b146c7f3b079', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the architectural purpose of the ''Root'' route in a Remix application?', N'Senior', N'The root route acts as the top-level layout wrapper for the entire application, handling global assets, meta tags, and the base HTML skeleton. It ensures that shared logic, like authentication checks or global navigation bars, is executed once per request, providing a centralized point for app-wide configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9198ac9e-d2d3-45eb-a2f9-b147fb86ae58', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the role of a signal in the SolidJS framework?', N'Intern', N'A signal is a primitive that holds a piece of state and notifies its subscribers whenever that state changes. It acts as the core building block for reactivity, allowing the framework to track dependencies and update the UI efficiently without needing a component re-render cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b98fc093-cace-48ff-8ba0-b14837437451', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the significance of the C memory model regarding the volatile keyword and compiler optimizations.', N'Senior', N'The volatile keyword instructs the compiler that a variable''s value can change through means outside the program''s control, such as hardware registers or concurrent signals. This forces the compiler to suppress optimizations like caching the value in a register, ensuring every access results in a fresh memory read or write. It is essential for low-level systems programming and memory-mapped I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28995737-a988-427a-877e-b14877501eed', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle data loading compared to traditional client-side fetching?', N'Intern', N'Instead of fetching data inside individual components after they mount, Remix uses loader functions that run on the server. This allows the data to be fetched in parallel with the document request, preventing layout shifts and eliminating the need for loading spinners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'accda482-a299-4e21-b530-b14a8d93e0e7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of a protocol in Swift?', N'Intern', N'A protocol defines a blueprint of methods, properties, or other requirements that a class, struct, or enum must implement. It allows for a design pattern where different types can conform to the same interface, promoting modular and reusable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96ef5bef-6f55-44cf-9bb9-b14d780642f2', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of an index in PostgreSQL?', N'Fresher', N'An index is a performance optimization tool that allows the database engine to find rows without scanning the entire table. It functions similarly to the index in the back of a textbook to speed up data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0deeb66-3829-4753-9544-b14dd6a08def', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you handle global error handling in a Vue application?', N'Middle', N'You can use the global error handler via the app.config.errorHandler hook. This allows you to log errors to an external monitoring service or display a generic error message to the user whenever an uncaught error occurs in a component or lifecycle hook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13f91724-f553-49d8-ab3a-b14e194576c8', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does mTLS (mutual TLS) improve security in internal service-to-service communication?', N'Middle', N'mTLS ensures that both the client and the server verify each other''s identity using digital certificates. This prevents man-in-the-middle attacks and ensures that only authorized services within the network can establish a connection, effectively securing traffic even inside a private cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'390e1446-33f1-43ad-9dc5-b15158c02782', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the ''RequestID'' middleware in Chi?', N'Junior', N'The RequestID middleware is a common utility that injects a unique identifier into the request context for each incoming HTTP request. This ID is then available for logging and tracing, making it easier to debug issues across distributed services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'890f55d5-ce1d-454e-90ce-b1544626b973', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an authentication system, what factors determine the choice of JWT versus session-based storage?', N'Middle', N'JWTs are stateless and ideal for distributed systems where the server does not need to maintain state. Session-based authentication is easier to revoke and more secure for sensitive applications where the server needs tight control over user state. The choice depends on the need for scalability versus control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a312855e-cfdd-43c6-a6f4-b154bd6aabfd', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What security benefits does Rocket provide through its design?', N'Middle', N'Rocket''s design emphasizes compile-time safety, preventing many common web vulnerabilities like parameter injection or type-related errors. By enforcing strict type checking and providing controlled access to request data via guards, it reduces the likelihood of insecure data handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4014e15c-0db4-49e0-8887-b15676b9d868', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket minimize memory overhead when handling large request payloads?', N'Senior', N'Rocket provides streaming support for request bodies, allowing developers to process large files or streams piece-by-piece rather than loading them entirely into memory. This prevents out-of-memory errors and keeps the heap usage stable even when handling concurrent large uploads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'211c15bf-c1db-4318-b900-b15877bdc10d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Can you define methods on types in Go?', N'Intern', N'Yes, you can define methods on structs or other custom types. A method is a function that has a special receiver argument, which links the function to that specific type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c2f2c39-a14c-4b0b-b85c-b15b8b3d5bd9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to cast the result of malloc, or is it optional?', N'Middle', N'In C, casting the result of malloc is optional because the compiler automatically converts the void pointer returned by malloc to the appropriate type. However, some developers prefer to explicitly cast for compatibility with C++ compilers or to clearly document the intended type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b66ffd3f-9334-4044-89a1-b15bd4a39645', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do metaclasses differ from class decorators?', N'Middle', N'Metaclasses control the creation and behavior of classes themselves, executing during class definition time to manipulate the class object before it exists. Class decorators are wrappers applied to a class after it has been created to modify its attributes or methods. Metaclasses are more powerful and invasive, while decorators are generally easier to implement and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20dcbfd4-6eca-43e7-a6c6-b15d37517a73', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does SQL stand for and what is it used for?', N'Intern', N'SQL stands for Structured Query Language. It is the standard language used to communicate with and manipulate relational databases, including tasks like querying, updating, inserting, and deleting data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8af575a7-fcaf-4322-af10-b15e57a849a7', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is InnoDB generally preferred over MyISAM?', N'Junior', N'InnoDB is preferred because it supports ACID-compliant transactions, row-level locking, and foreign key constraints, which ensure better data integrity. MyISAM only supports table-level locking and lacks native transaction support, making it less suitable for systems with frequent write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80646517-be9e-481d-9e02-b161e2f227c2', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the advantage of using ''Case Classes'' for data modeling?', N'Middle', N'Case classes automatically provide implementations for equality, hashing, and string representation, alongside deep pattern matching support. They are ideal for immutable data structures, as they also generate ''copy'' methods that simplify creating modified versions of existing objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81952c8e-76bf-483a-9613-b163c09804cf', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you parse a JSON body in a Fiber request?', N'Junior', N'You use the BodyParser method on the context object. By passing a pointer to a struct, Fiber automatically unmarshals the incoming JSON request body into the provided data structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59a4951d-0d0b-40eb-9ede-b1645befb2f4', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle errors in asynchronous code, and why is using try-catch with callbacks insufficient?', N'Middle', N'Callbacks are executed outside the call stack where they were defined, meaning try-catch blocks cannot catch errors thrown inside asynchronous callbacks. Modern Node.js uses promises and async/await, which allow errors to be caught in standard try-catch blocks or via rejection handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79fce8c0-88fa-40f8-bdda-b166bb36f234', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is Type Assertion?', N'Intern', N'Type assertion is a way to tell the compiler to treat a value as a specific type, overriding the compiler''s inferred type. It is essentially a way to manually inform the compiler that you know more about the data type than it does.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4b78dea-4516-49b2-bdb5-b16754fec348', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are class-based views in Django?', N'Junior', N'Class-based views (CBVs) provide an object-oriented approach to defining views. They allow developers to use inheritance and mixins to reuse common logic across different parts of an application, reducing code duplication compared to function-based views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eea623c-c69b-403a-b417-b1687c1f6636', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing between different programming languages, how do you weigh ecosystem support against developer familiarity?', N'Junior', N'If the team is already proficient in a language, they will be more productive and produce fewer bugs. However, if a different language has a vastly superior library ecosystem for the specific problem, it may be worth the investment in training to ensure the project''s long-term success.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f665405b-db99-4299-ac8e-b169bcec4eec', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why is it important to use ''Connection Pool'' settings in Spring Boot for database connectivity?', N'Senior', N'Database connections are expensive to create and destroy; connection pooling keeps a set of active connections ready for reuse. Proper tuning of pool size, idle timeouts, and validation queries prevents connection leakages and ensures that the application can handle traffic spikes without exhausting database resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23f782d2-88ba-4d79-9ed8-b16a95a53ac2', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between a class and a struct?', N'Intern', N'A class is a reference type that supports inheritance, while a struct is a value type that is generally used for small, lightweight data structures. Structs do not support inheritance and are usually stored on the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b906f92-b110-4df3-97c5-b16ad0609d58', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix minimize the total ''Time to Interactive'' (TTI)?', N'Senior', N'By prioritizing server-side rendering and optimizing the delivery of minimal JavaScript bundles, Remix ensures the page is functional as soon as the HTML arrives. It avoids shipping massive client-side bundles that require significant parsing and execution time before the user can interact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c57e255-f2fb-4fda-a776-b16c1e37f44f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between mapStateToProps() and mapDispatchToProps()?', N'Fresher', N'mapStateToProps() is a utility which helps your component get updated state (which is updated by some other components): mapDispatchToProps() is a utility which will help your component to fire an action event (dispatching action which may cause change of application state): It is recommended to always use the “object shorthand” form for the mapDispatchToProps. Redux wraps it in another function that looks like (…args) => dispatch(onTodoClick(…args)), and pass that wrapper function as a prop to your component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'943531d0-b922-4688-b471-b16e3c23511e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the ''priv'' directory in a Phoenix project?', N'Fresher', N'The ''priv'' directory is used for files that are not part of the source code but are necessary for the application to run. This typically includes database migrations, static assets, and pre-compiled resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd36f771c-7df8-480e-9a3f-b1711eb08d79', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between a Controller and a LiveView?', N'Intern', N'A controller is designed for standard request-response cycles, where each interaction triggers a full page reload. A LiveView is designed for interactive, stateful interfaces that update parts of the page in real-time over a persistent connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9baed2e0-ab40-43cc-b08e-b172aa2ec9af', N'075b8862-431c-4678-9767-f55359758a4a', N'What is Vue''s reactivity system?', N'Junior', N'Vue''s reactivity system tracks changes to data objects and automatically updates the UI when those changes occur. It achieves this by using JavaScript proxies to intercept property access and modifications, triggering updates only where necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48793232-b062-412a-9757-b173b08b4835', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you handle redirects in SvelteKit''s load functions?', N'Middle', N'Redirects are handled by throwing a redirect object provided by the SvelteKit library within a load function or form action. This intercepts the navigation process and tells the client to immediately navigate to the new location, ensuring proper routing flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01e68d3c-69f1-4fd2-b81b-b174877f2b45', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the benefit of using ''Dependency Injection'' over resolving from the global container?', N'Middle', N'Dependency injection makes class dependencies explicit in the constructor, which improves code readability and maintainability. It also makes the code easier to test because you can easily inject mock implementations rather than relying on the state of the global container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fc95af6-58fc-4d77-a8c1-b17559a21361', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a first class function?', N'Intern', N'In javaScript, functions can be stored as a variable inside an object or an array as well as it can be passed as an argument or be returned by another function. That makes function first-class function in JavaScript. A first-class function means functions are treated as values — they can be: - Assigned to variables: const greet = function() { return "Hello"; } - Passed as arguments: arr.map(fn) - Returned from other functions: function outer() { return function inner() {} } - Stored in data structures: const obj = { fn: () => {} } JavaScript fully supports first-class functions, which enables patterns like callbacks, higher-order functions, and closures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8302b61f-07fc-4458-91a2-b1790314ba9f', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the different API styles available?', N'Intern', N'The Vue components can be created in two different API styles 1. Options API: The Options API uses component logic using an object of options such as data, props, computed, methods and life cycle methods etc. The properties will be accessible inside functions using component instance(i.e, this). 2. Composition API: The Composition API uses component logic using imported API functions. The Single File Components(SFCs) requires setup attribute( ) to use imported variables and functions directly inside template section.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77de0bd2-ac2f-4c60-b02b-b17be2d9c2e5', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Compare RDB and AOF persistence in terms of recovery speed and data integrity.', N'Senior', N'RDB creates point-in-time snapshots of the dataset, allowing for very fast recovery but risking the loss of data between snapshots. AOF logs every write operation, providing much higher data integrity and durability, but at the cost of larger file sizes and slower recovery times due to the need to replay the command log.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96e2830c-6856-480f-b44c-b17c6896fef9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js achieve high concurrency despite being single-threaded?', N'Senior', N'Node.js offloads I/O operations to the operating system kernel or the libuv thread pool, allowing the main thread to continue executing other code. Once the I/O operation completes, a callback is queued in the event loop to be processed. This non-blocking I/O model allows a single process to handle thousands of concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4dcb334-3a46-40ce-bc1d-b17ccd4c132a', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Discuss the trade-offs of using Alpine.js for complex form validation versus using a dedicated validation library.', N'Senior', N'Alpine.js is excellent for simple, reactive validation logic that provides immediate UI feedback based on local state. For complex forms involving server-side schema validation, async dependencies, or multi-step flows, Alpine''s lack of built-in form orchestration can lead to messy, imperative code. Using a dedicated library provides robust handling of edge cases but increases the weight of the frontend bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aa5b920-50c1-48bc-bdb5-b186660dd02f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What does the @use rule do?', N'Fresher', N'The @use rule is the modern replacement for @import. It loads mixins, functions, and variables from other Sass files while keeping them namespaced, which helps prevent naming conflicts in larger projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7b2dab6-312c-46cf-ab3c-b186e61024c0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the trade-offs of using jQuery for state management in a large-scale enterprise application.', N'Senior', N'jQuery lacks a formal reactive state management system, forcing developers to manually synchronize DOM state with data, which leads to ''spaghetti'' code and fragile UI updates. Modern frameworks provide declarative data-binding that prevents the desynchronization issues common in imperative jQuery-based architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb6e696e-8cc4-4f89-8b77-b1872f2467ff', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is Fastify and why is it used?', N'Fresher', N'Fastify is a web framework for Node.js focused on providing the best developer experience with the least overhead and a powerful plugin architecture. It is designed to be highly performant and extensible, making it a popular choice for building efficient web servers and APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51069ce1-550b-457c-9bcf-b18751246c85', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'In the context of Hono, what is the role of the ''Environment'' generic, and why is it important for cloud scalability?', N'Senior', N'The Environment generic allows developers to strictly define the bindings, secrets, and KV namespaces available within a specific runtime, such as Cloudflare Workers. By enforcing these types at compile time, it prevents runtime failures in production environments and clearly documents the infrastructure dependencies required by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92874478-b7d5-4cad-9e01-b1889b0ebaa3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the primary motivation for implementing Database Sharding, and what are the main challenges?', N'Senior', N'Sharding is used to horizontally scale data across multiple nodes to bypass hardware limits on single instances. The main challenges include managing cross-shard transactions, complex joins across nodes, and the operational complexity of rebalancing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
