INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90a169ef-04b9-40f3-b660-b190958af455', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch ensure that search requests remain accurate during concurrent indexing?', N'Senior', N'Elasticsearch uses versioning and optimistic concurrency control to handle updates. When a search occurs, it views a consistent snapshot of the index based on the latest committed segments, ensuring that ongoing indexing operations do not corrupt or inconsistently represent the state of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
