INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff1e4d35-c889-4e44-aba5-b1badd970183', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s middleware architecture differ from traditional WSGI middleware?', N'Senior', N'FastAPI uses ASGI middleware, which is designed to handle asynchronous communication between the server and the application. This allows middleware to perform non-blocking operations, such as async logging or authentication, without degrading the performance of the entire request pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'459b6da2-5a8f-41e5-a03c-b1bc1b1293b3', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the trade-offs of using Flask''s ''g'' object versus thread-local storage for state management.', N'Senior', N'The ''g'' object is a namespace bound to the application context, making it the idiomatic way to share data across functions during a single request. Unlike manual thread-local storage, ''g'' is automatically managed by Flask''s context stack, reducing the risk of memory leaks or data bleeding across concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faefe5c3-15ae-438e-8317-b1bccc1a3bcd', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the C++ linker in handling template instantiation?', N'Senior', N'The linker is responsible for resolving template instantiations across translation units to ensure there is only one definition for each unique template specialization. While the compiler generates the code, the linker must merge these instantiations to prevent multiple definition errors while keeping the final executable compact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c83a438a-6571-4a9c-b400-b1bf80e5a077', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the common HTTP methods supported by Fiber?', N'Fresher', N'Fiber provides methods for all standard HTTP verbs including GET, POST, PUT, DELETE, PATCH, HEAD, and OPTIONS. Each method corresponds to a function on the app or router object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acca4f40-8ab0-408d-ae8c-b1c1e0126558', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between using an existing standard protocol versus creating a custom internal protocol?', N'Junior', N'Standard protocols like HTTP or gRPC are well-documented, widely supported, and have extensive tooling. Custom protocols might be optimized for a very specific, high-performance use case but come with high maintenance costs and a steep learning curve for new developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
