INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0823327e-d02f-405a-b5bf-b1c416d1bc56', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is the API Gateway pattern useful in microservices architectures?', N'Middle', N'An API Gateway acts as a single entry point for all client requests, handling tasks like authentication, rate limiting, and request routing. It decouples the client from the internal microservices structure, simplifying the client-side implementation and providing a centralized point for cross-cutting concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
