INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b499a78e-fcd4-457f-afac-b1cc44529715', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''Deadlock'' detection mechanism in InnoDB, and why might it become a performance issue?', N'Senior', N'InnoDB continuously runs a background thread to detect circular lock dependencies and automatically rolls back the smallest transaction to break the deadlock. While essential for integrity, in extremely high-concurrency systems, the overhead of constant deadlock checking can consume significant CPU cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
