INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc99174e-a211-4240-8ff2-b1d362390847', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between synchronous and asynchronous functions in FastAPI?', N'Fresher', N'Synchronous functions run one after another and block the execution flow until the task is finished. Asynchronous functions use the async and await keywords to allow the server to handle other incoming requests while waiting for slow operations, like database queries, to complete. This improves the concurrency of the application without requiring multiple threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd748a5a9-9eda-4482-b7e3-b1d63e9debf2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the best way to handle authentication in Chi to ensure it is not bypassed?', N'Senior', N'Authentication should be enforced using a middleware applied to the top-level router or protected sub-routers. This ensures that every request to a secured path is validated before it hits the business logic, effectively preventing accidental exposure of sensitive endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
