INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77a1b081-f99b-4a9f-934b-b1e5b5f43fbc', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the role of the virtual DOM in Vue''s rendering process.', N'Middle', N'The virtual DOM is a lightweight JavaScript representation of the actual DOM. When data changes, Vue creates a new virtual DOM tree and compares it with the previous one using a diffing algorithm to determine the minimum number of changes required, which are then applied to the real DOM to improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05f00cc4-5d9b-4ef1-8d8b-b1e64c71d832', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage security?', N'Junior', N'Quarkus provides a unified security layer that supports various authentication and authorization mechanisms like JWT, OIDC, and basic auth. It integrates these directly into the application stack, allowing for consistent security policies across different types of services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebb3a479-a408-46fe-bb36-b1e70757b25f', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle data consistency?', N'Junior', N'Cassandra uses tunable consistency, which allows developers to choose the trade-off between consistency and availability for each read or write operation. You can specify how many nodes must acknowledge a request before it is considered successful.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3b65f46-2875-40d0-bd1b-b1e7f98791b3', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What happens if a query result set is too large?', N'Fresher', N'If a query result exceeds the size limit for a single response, DynamoDB returns a paginated result. It includes a last evaluated key, which you use in subsequent requests to retrieve the remaining data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4169a45c-f422-443e-b7b1-b1ebe890e01f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the impact of ''Inlining'' on program execution and debugging?', N'Senior', N'Inlining replaces a method call with the body of the method, reducing call overhead and enabling further compiler optimizations. While it improves runtime performance, it complicates debugging because the call stack becomes flattened and does not accurately represent the source-level method calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7adba27e-219e-4c5f-8333-b1ee7412d698', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the advantages of using Cassandra over a relational database for high-write workloads?', N'Middle', N'Cassandra''s architecture uses an append-only log and in-memory buffering, allowing it to handle massive write throughput without the locking overhead inherent in ACID-compliant relational databases. Its linear scalability also allows for adding capacity by simply adding more nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb612f0b-c37c-4a33-bcfe-b1ef8e56d3b4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum ensure memory safety during asynchronous request processing?', N'Senior', N'Axum benefits from Rust''s ownership and lifetime rules, which prevent data races and dangling pointers at compile time. Because all data passed into handlers must satisfy Send and Sync bounds, the compiler guarantees that state shared across asynchronous boundaries cannot be corrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfdd999a-ee4f-4e40-ab62-b1f2ba20ca23', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a header guard?', N'Intern', N'A header guard is a preprocessor technique used to prevent a header file from being included more than once in a single compilation unit. It typically uses conditional macros to check if the file has already been processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8ea5873-8bac-41bc-bad2-b1f3f3484a6b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the trade-offs of using a Write-Around caching strategy?', N'Middle', N'Write-Around writes data directly to the database, bypassing the cache entirely. This prevents cache pollution by data that is written once but rarely read, though it introduces a latency penalty for subsequent reads of that same data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ccb5dcb-9767-4cef-b336-b1f4508ad83f', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is MongoDB considered schema-flexible?', N'Intern', N'MongoDB is considered schema-flexible because it does not require a predefined structure for documents. New fields can be added to documents at any time without modifying the entire collection, allowing for agile development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc92a1f8-d052-46f9-b489-b1f570829a7d', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does the ''Saga Pattern'' handle distributed transactions across multiple services?', N'Senior', N'The Saga pattern breaks a distributed transaction into a sequence of local transactions, where each service updates its own database and publishes an event. If a step fails, the Saga executes a series of ''compensating transactions'' to undo the changes made by preceding steps. This maintains eventual consistency without the need for long-lived, blocking locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7f0a683-1a35-472f-8829-b1f693c373f9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is the order of fields in a struct sometimes important for performance?', N'Middle', N'Rust does not automatically reorder struct fields to optimize for alignment unless specifically instructed. By arranging fields by size, developers can minimize memory padding caused by alignment requirements, thereby reducing the overall memory footprint of the structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e89419c6-7f0c-4921-8465-b1f92dd88097', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the concept of ''code splitting'' and its impact on the Critical Rendering Path.', N'Senior', N'Code splitting breaks a large bundle into smaller chunks that can be loaded on demand, reducing the initial payload size. By deferring non-essential code, it optimizes the Critical Rendering Path, allowing the browser to render the initial view faster and improving perceived performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
