INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60abc468-263e-4978-992d-b20d5c5b013c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it generally advised to avoid using Node.js for heavy computational tasks, and what is the architectural alternative?', N'Senior', N'Because JavaScript is single-threaded, heavy computations block the event loop, causing the server to ignore all other incoming network requests. The architectural alternative is to offload these tasks to specialized services written in languages like Go, Rust, or C++, or to use Node.js Worker Threads for parallel CPU execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f24f1b63-7f53-4c6b-8c79-b20dab2a0a16', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is an Eloquent ORM?', N'Intern', N'Eloquent is Laravel''s built-in Object-Relational Mapper. It allows you to interact with your database tables as if they were simple PHP objects, making it easier to perform database operations without writing raw SQL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9c3a9d9-a596-4c9c-bdef-b20e6ae9a83c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you choose between a relational database and a NoSQL solution for a new service?', N'Middle', N'The choice depends on the data structure and consistency requirements. If the data has strict schema requirements and requires complex relational queries or ACID compliance, I prefer a relational database. If the data is highly unstructured, requires massive horizontal scalability, and can tolerate eventual consistency, a NoSQL solution is more appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e805c04-bab0-4775-8717-b210b072216e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does an ''inverted index'' function in a NoSQL search-oriented database?', N'Senior', N'An inverted index maps content, such as words or tokens, to the document IDs containing them rather than mapping documents to their content. This allows for near-instant full-text search across large datasets, as the system only needs to look up the pre-indexed term list to find relevant records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'091a21c3-237e-4dd6-a566-b21107b5a1fb', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Combining with useReducer for Global State Management', N'Middle', N'When combined with useReducer, useContext becomes a powerful tool for managing more complex global state logic. This pattern helps maintain cleaner, scalable state logic without introducing external libraries like Redux. Some of the common use cases of useContext are listed below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8c3e3e2-1ddb-419a-aec0-b211f86d2cdf', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain the difference between ''createMemo'' and ''createEffect'' in terms of execution timing and purpose.', N'Senior', N'createMemo is designed for deriving state and is executed synchronously during the update phase to provide a stable value, often used for performance optimization. createEffect is intended for side effects, executes asynchronously after rendering, and does not return a value to the reactive graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdcd2719-7f49-4d82-a75b-b212e28e20ff', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the distinction between ''server-only'' modules and ''universal'' modules in SvelteKit?', N'Senior', N'Server-only modules, denoted by the ''.server.js'' suffix, are guaranteed never to be bundled into the client-side code, which is essential for protecting secret keys and database logic. Universal modules run on both, allowing for faster initial page loads by sharing data-fetching logic between server and client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c38f3a68-c062-4e4b-9bc3-b2138efec4b6', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the main challenge for developers migrating to Qwik?', N'Middle', N'The main challenge is adopting the mental model of ''resumability'' and understanding serialization requirements. Developers must ensure that all data and functions used in components are compatible with Qwik''s lazy-loading and serialization constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'071b870e-d089-4c1d-a832-b21872af1c39', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'When designing for high performance, how does Litestar''s serialization choice impact the response cycle?', N'Senior', N'Litestar allows for pluggable serialization backends, which can be optimized based on the data structure and expected client usage. Choosing a high-performance serializer like Orjson can significantly reduce latency in the response pipeline for large JSON payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37ce7f43-ed7d-44dc-85cf-b21a3ddb9df2', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between WHERE and HAVING clauses?', N'Fresher', N'WHERE vs. HAVING: Architectural Distinction The fundamental difference lies in the logical order of operations within the SQL execution pipeline. While both clauses filter rows, they function at distinct stages of the query lifecycle. WHERE Clause: Row-Level Predicate The WHERE clause acts as a pre-aggregation filter. It evaluates conditions against individual rows before any GROUP BY operation occurs. * Execution Order: Applied immediately after the FROM/JOIN phase. * Performance: Highly efficient when used with SARGable (Search ARGumentable) expressions. Indexing columns referenced in a WHERE clause allows for $O(\log n)$ lookup performance via B-tree index traversal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3374ff73-754f-44db-9fd5-b220c028478f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why does Svelte require the use of ''let'' or ''const'' for state variables?', N'Middle', N'Svelte uses static analysis to identify variables that participate in reactivity. By using standard JavaScript declarations, the compiler can track reassignments and trigger the necessary UI updates without needing custom state wrappers like those found in other frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'304445d6-4cb0-4d32-aead-b220e8864051', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the considerations for choosing between Provisioned and On-Demand capacity modes?', N'Senior', N'Provisioned mode is cost-effective for predictable, steady-state workloads where you can forecast capacity requirements. On-Demand mode is better for unpredictable traffic spikes or new applications where capacity patterns are unknown, though it is typically more expensive per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'087a9ae8-018e-4b2b-9400-b22126968236', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s utility-first approach affect the accessibility (a11y) of a web application?', N'Senior', N'Tailwind does not inherently provide accessibility, but it facilitates it by allowing developers to rapidly apply standard states like hover, focus, and active. However, because it is utility-based, developers must still manually ensure that semantic HTML and ARIA attributes are implemented correctly as Tailwind only dictates the visual layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df777b14-7ca3-40cc-a3e8-b221581dc63d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you handle events in jQuery?', N'Intern', N'jQuery provides methods like .on(), .click(), and .hover() to attach event listeners to DOM elements. These methods simplify the process of responding to user interactions like mouse clicks, keyboard inputs, or window resizing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f26f442-9c8e-46c6-9953-b222229bff6e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the benefits of React Router V4?', N'Intern', N'Below are the main benefits of React Router V4 module, 1. In React Router v4(version 4), the API is completely about components. A router can be visualized as a single component( ) which wraps specific child router components( ). 2. You don''t need to manually set history. The router module will take care history by wrapping routes with component. 3. The application size is reduced by adding only the specific router module(Web, core, or native)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'958f4682-ea6f-4bfa-a002-b2233d1293b1', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the concept of ''nested routing'' in Remix and its benefits.', N'Middle', N'Nested routing maps URL segments to a hierarchy of components. This allows parts of the page to re-render independently while keeping layout components persistent, resulting in a more efficient UI and better performance by only fetching data for the changed segments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f43fb9b6-fc78-4dae-b395-b22443335a1a', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are Procs and Lambdas?', N'Fresher', N'Both are objects that wrap chunks of code to be executed later. The primary difference is that a lambda checks the number of arguments passed to it, while a proc is more lenient, and they handle the return keyword differently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ad4b54d-3c31-442d-964a-b229493c40ad', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with an incident caused by a recent deployment, what steps do you take to restore service stability immediately?', N'Middle', N'The priority is to restore service, so I would perform an immediate rollback to the last known stable version of the application. Once stability is restored, I would perform a post-mortem analysis to identify the root cause of the regression without the pressure of active production outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26aa0cd5-8310-4cba-a780-b22aae579a77', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle event delegation, and what are the implications for performance?', N'Senior', N'Preact uses a single global event listener attached to the document root, which delegates events to the appropriate component instances. This approach significantly reduces the overhead of attaching multiple listeners to individual nodes, improving memory efficiency and reducing overall garbage collection pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3c4de1c-a71b-459f-a0ef-b22bae7202e5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of ''Transaction ID Wraparound'' prevention?', N'Middle', N'PostgreSQL uses 32-bit transaction IDs. If these IDs are allowed to reach their limit, the database will treat old data as being in the future, causing severe corruption. Autovacuum automatically triggers to freeze old rows and reset the transaction ID counter to prevent this critical failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8addfa07-ac75-41c8-82d7-b22d44873769', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is an AdonisJS Provider?', N'Intern', N'A Provider is the mechanism used to register and configure services within the AdonisJS application container. It is the primary way to boot up dependencies and make them available throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39f4469d-bd32-4a05-a6fb-b22f36ecfcbe', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the function of the C ''inline'' keyword?', N'Senior', N'The ''inline'' keyword is a hint to the compiler that it should attempt to replace a function call with the actual body of the function to reduce call overhead. However, the compiler is free to ignore this hint if it determines that inlining would negatively impact binary size or cache performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83edc846-0ad8-4251-ab74-b23067892571', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .remove() and .detach()?', N'Intern', N'Both remove elements from the DOM, but .remove() discards the element and all associated data and events. The .detach() method also removes the element but keeps the associated data and events intact, allowing the element to be re-inserted later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e2877e4-598b-400a-89b9-b232be9fea7d', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the imported modules in CLI generated feature modules?', N'Intern', N'In the CLI generated feature module, there are two JavaScript import statements at the top of the file 1. NgModule: InOrder to use the @NgModule decorator 2. CommonModule: It provides many common directives such as ngIf and ngFor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e067f6b-9563-4fe2-a5cf-b2342b27ff34', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you implement two-way binding?', N'Fresher', N'You can use the v-model directive to create two-way data bindings on form input, textarea, and select elements. Lets take an example of it using input component, Remember, v-model will ignore the initial value, checked or selected attributes found on any form elements. So it always use the Vue instance data as the source of truth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d92b79-784d-46cc-87c9-b2346b89de77', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s default ''code splitting'' behavior?', N'Middle', N'SvelteKit automatically splits the application bundle based on routes. When a user navigates to a specific page, the browser only downloads the JavaScript required for that route, which significantly reduces the initial payload size and improves performance for larger applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c9cafda-ad9b-4a7f-a700-b235422c8fc2', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''recover'' function used for?', N'Fresher', N'The recover function is used to regain control of a panicking Goroutine. It is typically called inside a deferred function to catch a panic and prevent the entire program from crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1b6a68e-f1c3-4eca-a81f-b2391a5439ee', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'In what scenario would you choose ''Astro.glob'' over ''Content Collections''?', N'Senior', N'Astro.glob is a lower-level API used for quick, unstructured imports of local files when schema validation or performance optimization of content metadata is not required. Content Collections should be preferred for structured data to ensure type safety and faster, build-time performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c201625-df42-46f0-86a9-b23e97875539', N'075b8862-431c-4678-9767-f55359758a4a', N'Why does Vue 3 discourage the use of ''mixins'' in favor of ''composables''?', N'Senior', N'Mixins suffer from implicit dependencies, property name collisions, and lack of type safety, making it difficult to understand where logic originates. Composables are explicit, encapsulated functions that use standard JavaScript patterns, leading to clearer data flow and better maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd09652f7-6410-4d72-aaf9-b240caaa009d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is distributed tracing essential in microservices?', N'Middle', N'In a microservices architecture, a single user request can traverse dozens of services, making it difficult to debug performance bottlenecks or errors. Distributed tracing uses unique correlation IDs to track the request flow across service boundaries, providing visibility into the entire request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d9e8cea-458a-475e-a5e5-b242a548b830', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between template engines and serving static files in Express?', N'Middle', N'Template engines are used to dynamically render HTML on the server side by injecting data into templates. Serving static files, using express.static, is a way to deliver pre-existing assets like images, CSS, or client-side JavaScript files directly to the browser without processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da3cdc9e-432d-4737-95df-b2477a584d66', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is file-based routing in SvelteKit?', N'Intern', N'File-based routing means that the structure of your application''s URLs is determined by the file system structure within the src/routes directory. Each folder typically represents a URL segment, and specific file names like +page.svelte define the content shown at that route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'580704e0-0810-48cc-bbef-b248510b3bba', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'In what scenario would you still consider using jQuery today?', N'Middle', N'jQuery might be appropriate for maintaining legacy projects where refactoring is not feasible or for simple, small-scale websites where adding a heavy framework would be overkill. It remains a reliable tool for simple DOM manipulation if the project requirements are minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e27df6bd-845a-44bd-be04-b2490dcfc6f1', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach observability in a distributed system?', N'Middle', N'I implement a combination of logs for detailed event tracing, metrics for high-level health monitoring, and distributed tracing to follow requests across service boundaries. This three-pillar approach ensures I can identify not just that a system is failing, but exactly where and why the failure occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5729bce6-33ff-4555-a044-b249179aff61', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does Sharding affect the performance of cross-partition joins?', N'Senior', N'Sharding physically distributes data across nodes, making cross-partition joins extremely expensive as they require a global scatter-gather operation. These operations often force large amounts of data over the network, leading to significant latency and potential bottlenecks that are usually avoided by denormalizing or redesigning the data model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7ac069c-e515-47e2-bb63-b24a2eefd0a0', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How do virtual threads (Project Loom) change the scalability model of Java applications?', N'Senior', N'Virtual threads are lightweight, user-mode threads managed by the JVM rather than the OS kernel, allowing applications to scale to millions of concurrent tasks. This changes the concurrency model from thread-per-request to a blocking-style programming model that remains highly performant, as it eliminates the overhead associated with heavy kernel-level context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0524675e-b5a0-4854-b305-b24c01a3b37e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails manage database migrations to ensure zero-downtime deployments?', N'Senior', N'Zero-downtime migrations require a two-step process: applying database changes (like adding columns) in a backwards-compatible manner first, and then updating application code. This ensures that old and new code versions can coexist during the deployment window without failing due to schema mismatches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cef6e35-2cec-42a4-9d08-b24c379480e7', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is margin collapsing in CSS?', N'Intern', N'Margin collapsing occurs when the top and bottom margins of block-level elements combine into a single margin equal to the larger of the two values. Scenarios where margin collapsing occurs: 1. Adjacent siblings: The bottom margin of one element collapses with the top margin of the next sibling. 2. Parent and first/last child: If there is no border, padding, or block formatting context separating a parent''s top margin from its first child''s top margin, they collapse. 3. Empty blocks: A block with no height, border, or padding collapses its own top and bottom margins. How to prevent margin collapsing: * Add padding or border to the parent. * Use overflow: hidden or overflow: auto on the parent (creates a Block Formatting Context). * Use display: flex or display: grid on the parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5db33d6-5f65-47c9-b584-b2503cbb5d4a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''assets'' and ''public'' directories in Nuxt?', N'Fresher', N'The assets directory is used for files that need to be processed by the build tool, such as CSS, fonts, or images that require optimization. The public directory is used for static files that should be served as-is, such as icons or robots.txt files, without any processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bfcd058-8fa3-4105-8a27-b2538858d7b1', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle transactions compared to relational databases?', N'Middle', N'Redis uses the MULTI and EXEC commands to queue a sequence of commands that are executed as a single atomic operation. Unlike relational databases, Redis does not support full rollback capabilities if a command fails during execution, as it prioritizes performance over complex transaction semantics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'addd8060-c741-41a4-bccb-b253c5b315dc', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of a circuit breaker pattern in a microservices architecture?', N'Middle', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail. It monitors for failures, trips to an open state to block requests, and allows the failing service time to recover, preventing cascading failures across the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab540bff-f906-43a5-8565-b25898681af3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary advantage of building on Phoenix compared to other frameworks?', N'Intern', N'The primary advantage is its foundation on the Erlang VM (BEAM). This provides high concurrency, fault tolerance, and the ability to handle a massive number of simultaneous connections with low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f4b3050-e7e7-46c9-a024-b258fbc65f7e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB decide which shard to route a document to, and what role does the shard key play?', N'Middle', N'MongoDB uses the shard key to distribute documents across shards based on a hashed or ranged partitioning strategy defined by the balancer. The shard key is critical because it determines data distribution and query efficiency; an improperly chosen shard key can lead to unbalanced data chunks or ''hot shards''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9f0e3b5-347b-4db6-942c-b259495bbe60', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle garbage collection?', N'Junior', N'Node.js uses the V8 engine, which manages memory automatically through a garbage collector. It periodically identifies objects that are no longer reachable by the application and deallocates their memory to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
