INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb8142df-4d8b-4c27-8346-b26fc93af039', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a fiber in the context of backend systems?', N'Intern', N'A fiber is a lightweight unit of execution that allows for cooperative multitasking. Unlike OS threads, fibers are managed by the application runtime rather than the operating system kernel, making them significantly cheaper to create and switch between.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
