INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3e2c112-59a4-4095-8444-b27102f0cd7c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do asynchronous message queues help in decoupling system components?', N'Middle', N'Message queues allow services to communicate without waiting for an immediate response, which decouples the sender from the receiver. This helps in smoothing out traffic spikes by allowing the system to process tasks at a manageable rate rather than failing under peak load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd085c07d-913f-4c95-9dcf-b2744923e42e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''Sequence'' API in Kotlin differ from ''Iterable'' in terms of evaluation strategy and performance?', N'Senior', N'Sequences utilize lazy, short-circuiting evaluation, which processes elements one by one through the entire pipeline, whereas Iterables perform eager, intermediate allocations for each transformation step. Sequences are more efficient for large datasets or complex chains, though they can incur overhead for small operations due to the creation of wrapper objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'641f6485-a41f-4a08-a518-b2745502717a', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Ecto in a Phoenix application?', N'Junior', N'Ecto is a database wrapper and query generator for Elixir. It handles database communication, schema definition, and data validation, allowing developers to interact with the database using Elixir syntax instead of raw SQL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4653e347-7b1c-48f9-a924-b275f82acb5d', N'4c000000-0000-0000-0000-000000000005', N'What is the ''Database-per-service'' pattern and why is it important?', N'Senior', N'This pattern ensures that each microservice owns its own database, preventing hidden coupling through shared data schemas. It allows services to evolve their data models independently and use the most appropriate storage technology for their specific use case, though it complicates cross-service data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'810daba1-00d9-4aa7-bfa2-b27f7483a8d2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to isolate a bug?', N'Intern', N'Isolating a bug means identifying the smallest possible set of inputs or system states that trigger the issue. This helps ensure that your eventual fix is targeted and does not create unintended side effects elsewhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'632a73ea-7055-4fc3-9f53-b28292c21a33', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is it critical that reducers remain pure functions, and what happens if they are not?', N'Senior', N'Pure functions ensure that the state transition is predictable and testable, which is fundamental to Redux''s core promise. If a reducer performs side effects or mutates state, it breaks time-travel debugging, prevents reliable state caching, and leads to inconsistent UI updates because the store cannot accurately determine when a state change occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e2714fb-1b1f-4c86-838d-b285c3f00439', N'075b8862-431c-4678-9767-f55359758a4a', N'What are lifecycle hooks in a Vue component?', N'Junior', N'Lifecycle hooks are methods that allow you to execute code at specific stages of a component''s existence, such as creation, mounting, updating, or destruction. They provide opportunities to perform tasks like fetching initial data, setting up event listeners, or cleaning up resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41e22b42-daa2-4c95-b609-b28882271206', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the trade-off of using ''Structural Types'' in Scala versus nominal interfaces.', N'Senior', N'Structural types allow for duck typing by defining the required method signatures without needing a common base class, which is highly flexible for loose coupling. However, they are implemented via reflection or extensive byte-code generation, which can significantly impact performance. Nominal interfaces are preferred for performance-critical paths as they provide static, compile-time dispatch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ed9abd4-97d3-4327-bb19-b28939bb5f6d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle server-side rendering (SSR) differently than a standard client-side render?', N'Senior', N'During SSR, Preact serializes the component tree into an HTML string on the server without creating a full DOM tree. On the client, it performs a hydration process where it attaches event listeners and links the existing server-generated HTML to the Virtual DOM, ensuring the state is correctly synchronized without re-rendering the entire document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c902190f-c158-4a2d-ab0d-b289beea39e8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the architectural trade-offs of using Scala''s ''path-dependent types''?', N'Senior', N'Path-dependent types enforce strict decoupling by tying a type to a specific instance of an object, which improves safety by preventing the mixing of instances from different contexts. However, this creates significant complexity in type signatures and can lead to difficulties when serializing data or performing equality checks across different instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c088dace-2afc-4bdb-9224-b28a8c0e1f44', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'When would you prefer using a ''preSerialization'' hook over an ''onSend'' hook?', N'Middle', N'Use preSerialization when you need to transform the data object before it gets stringified into JSON. Use onSend when you need to modify the final stringified payload or the response headers immediately before they are flushed to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'174a8624-fd17-4879-9fb6-b28f88430e2b', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for debugging an issue that is reported by a user but you cannot reproduce?', N'Junior', N'I would gather as much context as possible, including the user''s browser, operating system, and the specific steps they took leading up to the error. If I still cannot reproduce it, I would add more logging to the application to capture the state when the error occurs next time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9489ec02-35f8-4d3f-82da-b28faff27595', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''extern'' keyword?', N'Intern', N'The extern keyword is used to declare a variable or function that is defined in another source file. It tells the compiler that the identifier exists elsewhere and will be resolved during the linking process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d4d8aea-d192-48f6-b689-b290580cff87', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your methodology for capacity planning in a cloud-native architecture?', N'Senior', N'I establish baselines through load testing and analyze growth trends to set auto-scaling thresholds that trigger well before resource exhaustion. I also design for ''graceful degradation'' so that if capacity limits are breached, the system serves reduced functionality rather than failing entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f0d42dc-bef7-479d-97de-b29076a40baf', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'When should you prefer using a ''Service'' over an ''Actor'' in Actix?', N'Senior', N'Services are better suited for request/response cycles that do not require independent lifecycle management or internal state maintenance. Actors should be reserved for scenarios requiring state persistence, background task coordination, or complex asynchronous orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
