INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94a32423-e4c4-4d70-b4ec-b2ba2cff12c7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the ''leaky abstraction'' risk associated with using ''eval'' and ''exec'' in production systems?', N'Senior', N'Using eval or exec introduces significant security risks, as they can execute arbitrary code passed as strings, leading to command injection vulnerabilities. Beyond security, they make static analysis and debugging extremely difficult because the execution context is dynamic. They should be avoided in favor of safer alternatives like the ast module or dispatch patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94f62dab-a0e2-48b9-a9a6-b2bc997346a3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the benefit of using ''Enums'' versus ''Union Types''?', N'Middle', N'Enums provide a named set of constants that can be easier to manage and document in large projects. However, Union types are generally preferred in modern TypeScript because they are more lightweight, integrate better with structural typing, and do not introduce extra runtime code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6cfedaa-53be-4129-8065-b2beba387ae9', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle file uploads?', N'Intern', N'FastAPI uses the ''UploadFile'' class to handle incoming files efficiently. It allows you to access file metadata and stream the content of the file, which is more memory-efficient than loading the entire file into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af265cf5-992b-48d3-9680-b2c4f0af336b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the impact of a high number of SSTables on query latency?', N'Senior', N'A high number of SSTables increases read amplification because the database must check multiple files to satisfy a single query. This creates overhead in merging the results and increases the probability of hitting disk I/O bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd78b2185-28c4-4efa-8c3b-b2c52aa2dcbf', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is it important to provide a unique ''key'' prop when rendering lists?', N'Middle', N'Keys help React identify which items in a list have changed, been added, or removed during the reconciliation process. Using stable, unique keys ensures efficient DOM updates and prevents issues with component state persistence when items are reordered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfea6a6f-2b3c-4ff3-9c36-b2c5c9fb2541', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the difference between a view and a materialized view.', N'Middle', N'A standard view is a virtual table that executes its underlying query every time it is accessed. A materialized view stores the result of the query physically on disk, offering faster access at the cost of requiring periodic updates or refreshes to stay current.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f66bce6-b4b7-4f62-8c9f-b2c67c6eec2f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the primary trade-off between Dart''s JIT and AOT compilation modes?', N'Middle', N'JIT compilation is optimized for fast development cycles, enabling features like Hot Reload by recompiling code on the fly. AOT compilation produces highly optimized machine code for production, resulting in faster startup times and better runtime performance at the cost of longer build times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
