INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18dec03a-d994-4481-a438-b2d4c0ea7f99', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How can caching improve system reliability?', N'Middle', N'Caching reduces the load on backend databases and downstream services by serving frequently accessed data from memory. This protects backend components from traffic spikes and allows the system to remain functional if the original data source becomes temporarily unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fd30b7-f118-4872-9a7d-b2d77ea67bd3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of ''adapter-auto'' and how does it influence the deployment strategy of a SvelteKit application?', N'Senior', N'Adapter-auto detects the environment during the build process to determine the optimal output format, such as Node.js, Vercel, or Netlify. This abstraction allows developers to write platform-agnostic code while maintaining the ability to leverage serverless or edge-specific features like streaming or ISR.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
