INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08764a3d-5eb4-4d5d-a40b-b2f1ac981b20', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix differ from a typical Single Page Application (SPA)?', N'Junior', N'Remix is a full-stack framework that emphasizes server-side rendering and progressive enhancement. While SPAs often rely heavily on client-side JavaScript to fetch data after the page loads, Remix fetches data on the server, making the initial page load faster and more reliable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7605ed42-44bd-4bac-851b-b2f338a53423', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of an offset or message acknowledgement in a distributed queue?', N'Middle', N'Offsets or acknowledgements track the progress of message consumption to ensure that the system knows which messages have been successfully processed. This mechanism is crucial for enabling fault tolerance, as it allows consumers to resume from the last successfully processed point after a crash or restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'704adb3b-166c-4d21-88b2-b2f4e15318d5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between an interface and an abstract class in Kotlin?', N'Intern', N'An abstract class can hold state through properties and has a constructor, while an interface cannot hold state but can define method signatures and default implementations. A class can implement multiple interfaces, but it can only inherit from one abstract class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ba74a25-dcb0-4f90-b2f6-b2f5c566157f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the difference between Auth guards and providers in Laravel.', N'Middle', N'Guards define how users are authenticated for each request, such as using session cookies or API tokens. Providers define how users are retrieved from your persistent storage, such as a database or an LDAP directory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cce953ff-aec0-437c-ae19-b2f729ce1ad5', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the function of the dollar-sign syntax in Svelte, and how does the compiler interpret it?', N'Senior', N'The dollar-sign syntax denotes reactive declarations that automatically re-run whenever their referenced dependencies change. The compiler treats these as memoized values, effectively tracking the dependency graph to ensure they are only recalculated when necessary, which is highly efficient for derived state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56872d60-db13-460b-b36b-b2f768d5eae8', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What happens if you don''t use a WHERE clause with an UPDATE statement?', N'Fresher', N'If you omit the WHERE clause in an UPDATE statement, all rows in the table will be updated with the new values. This usually results in unintended data loss or corruption of all table records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f0f4deb-ecee-480c-9ba4-b2f91fee9d7a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the default storage engine in modern MySQL versions?', N'Junior', N'The default storage engine in modern versions of MySQL is InnoDB. It is preferred because it supports transactions, row-level locking, and foreign key constraints, which are essential for data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4889c3be-59f8-40ee-baf4-b2f9d3e99a3d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the best way to handle a task that is too large to estimate accurately?', N'Fresher', N'The best approach is to decompose the task into smaller, atomic sub-tasks that are easier to understand and evaluate. Once broken down, I would estimate each sub-task individually and aggregate them for a more reliable total.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28f70176-766c-4e6d-bcee-b2f9e20886d3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the architectural trade-offs of using a NoSQL database over a relational one for scaling?', N'Senior', N'NoSQL databases are designed for horizontal scalability and schema flexibility, making them ideal for unstructured or rapidly evolving data. However, they often sacrifice the ACID compliance and mature query capabilities of relational databases, shifting the burden of managing relationships and consistency to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99643c1f-55bc-403d-b687-b2fb6a1a59b6', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rocket''s type-system integration considered a security feature?', N'Senior', N'By mapping HTTP parameters directly to Rust types, Rocket prevents injection attacks and type-mismatch bugs at the perimeter. If a parameter cannot be parsed into the expected type, the request is automatically rejected, preventing tainted data from ever reaching the business logic layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35d4289c-0827-4626-936d-b2fbd0a15d9f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does MySQL manage disk I/O scheduling to prevent performance bottlenecks?', N'Senior', N'MySQL uses a background writer thread (the ''master thread'') and page cleaners to flush dirty pages at a rate that keeps the buffer pool responsive. It also utilizes the doublewrite buffer to minimize the impact of random I/O during heavy write workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19ece3b2-17ea-46d7-916f-b2fe7674ff5d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a system component, how do you decide what should be configurable versus what should be hard-coded?', N'Intern', N'I consider how likely a value is to change over time or based on the environment. Values that are business-specific, vary by region, or involve external integrations should be configurable to avoid redeploying the entire system. Logic that defines the fundamental behavior of the component should remain hard-coded to ensure consistency and prevent accidental misconfiguration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68f1b4ea-5586-4ba7-bd0a-b302d38c599e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a strict mode in javascript', N'Intern', N'JavaScript’s "use strict" directive is used to opt into a stricter parsing and error-handling mode for your scripts or functions. It helps catch common bugs, makes your code more secure, and prepares it for future versions of JavaScript. Strict Mode is a new feature in ECMAScript 5 that allows you to place a program, or a function, in a “strict” operating context. This way it prevents certain actions from being taken and throws more exceptions. The literal expression "use strict"; instructs the browser to use the javascript code in the Strict mode. This also enables block-scoped variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8914045-0bcf-4719-b6e8-b30342d423b3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a signed and unsigned integer?', N'Intern', N'A signed integer can represent both positive and negative numbers by using one bit to indicate the sign. An unsigned integer only represents non-negative numbers, allowing it to store a larger range of positive values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
