INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ccadcf-a94f-4e5d-999a-b30dff4c34c6', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of the ''Snitch'' in Cassandra?', N'Junior', N'The snitch determines the network topology of the cluster, mapping IP addresses to racks and data centers. This information allows Cassandra to make intelligent decisions about where to place replicas to ensure data availability even if an entire rack or data center fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
