INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c10ee7-d68a-450e-88c5-b30fc8fe6892', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it generally discouraged to perform heavy CPU-bound operations in the main event loop?', N'Middle', N'Because Node.js runs on a single thread, any heavy synchronous computation blocks the event loop. This prevents the server from processing new incoming requests or executing other pending callbacks, leading to increased latency and potential unresponsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e10d5428-44f9-459b-bcb4-b31202e5cc4f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it recommended to use schema-based validation instead of manual checks?', N'Junior', N'Schema-based validation is handled by the framework at the entry point, which is more performant and less error-prone than manual checks. It centralizes your data integrity rules, allows for automatic generation of documentation, and ensures consistent error responses for invalid inputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a86e345-1e41-477b-9176-b3136aefe4c9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of using a binary search approach when debugging a regression?', N'Junior', N'Binary search debugging involves reverting half of the recent changes to see if the issue persists, which helps isolate the specific commit or change that introduced the bug. This is highly efficient because it reduces the search space for the root cause exponentially rather than checking every single change individually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4348cd25-f643-4188-93e2-b314b09abcc8', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''Unwind'' mechanism in Rust handle panics, and what implications does this have for FFI?', N'Senior', N'Rust''s panic mechanism typically unwinds the stack, calling destructors for all objects in scope to ensure resource cleanup. This can cause undefined behavior if a panic crosses an FFI boundary into a language like C, which does not understand the unwinding ABI, making it critical to catch panics before they leave Rust code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f94c38-4263-4f61-97cc-b314e4f1f793', N'075b8862-431c-4678-9767-f55359758a4a', N'Describe the architectural pattern for handling ''Shared Mutable State'' across independent feature modules.', N'Senior', N'The recommended pattern is to encapsulate shared state within a specialized store or a centralized reactive object that acts as a single source of truth. This prevents ''prop drilling'' and ensures that all feature modules react predictably to changes in the shared state while maintaining loose coupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
