INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49a75a8c-ebee-4e95-88de-b31c1ab23018', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the significance of the ''app.module.ts'' file in an Angular application?', N'Middle', N'The main module, usually AppModule, acts as the entry point that bootstraps the application and declares the root components, imports necessary modules, and defines global providers. It serves as the primary configuration center that links all parts of the application together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05a20ed8-3b6c-43ce-a494-b31c8a142f34', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the architectural implications of using ''Server Middleware'' in a Nuxt application?', N'Senior', N'Server middleware intercepts requests before they reach the application logic, allowing for global tasks like authentication, logging, or header manipulation. Because this runs on the server, it is highly efficient, but it must be kept lightweight to avoid increasing the latency of every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ba04349-16f1-4a5b-bfaf-b31d28a0fbb1', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is Actix-web considered ''Type-Safe''?', N'Intern', N'It is type-safe because it leverages Rust''s strict compiler to ensure that data being extracted from requests and sent in responses matches the expected types. This eliminates many common bugs related to mismatched data formats or null values at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'827932a8-9cf4-4f5c-a705-b31d9fefb6b9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure that your code changes don''t introduce performance regressions?', N'Middle', N'I integrate performance benchmarks into the CI/CD pipeline to compare execution times against established baselines for critical paths. If a PR causes a significant deviation in latency or throughput, the build is flagged for investigation before it can be merged into the main branch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f5fc0e4-9fa8-4de6-be6b-b31e605d2651', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it important to use ''v-once'' or ''v-memo'' in performance-critical Vue templates?', N'Senior', N'v-once renders an element or component only once, skipping future updates, while v-memo allows conditional re-rendering based on specific dependencies. Using these directives reduces the burden on the virtual DOM diffing engine by pruning branches of the tree that do not require reactivity, which is vital for high-frequency list rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fea73ca2-69e4-4a3a-89c9-b31fa44a8f75', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you optimize ActiveRecord queries to prevent N+1 issues in a large-scale application?', N'Senior', N'N+1 issues occur when the application performs an extra query for every item in a collection. This is resolved by using eager loading via includes, preload, or eager_load to fetch associated records in a single or minimal set of queries, significantly reducing database round-trips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd24cccd1-dfa3-4328-ba64-b322ed2c00d1', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the primary role of the ''Self-Type'' in Scala?', N'Middle', N'A self-type declares that a trait must be mixed into another specific type. This allows the trait to access members of the host class while keeping the implementation decoupled, effectively enforcing architectural constraints at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a6bf43b-d195-4063-b84f-b323c2b19595', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite bundle the application when running in development mode?', N'Junior', N'No, Vite does not bundle the entire application in development. It uses native browser ESM support to serve individual files as requested, which makes the startup time extremely fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b245236-a9fe-4681-b6da-b323d848b27e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java String Constant Pool interact with the heap and what are the implications for memory footprint?', N'Senior', N'The String Constant Pool is a specialized memory region in the heap that stores unique string literals to prevent redundancy and conserve memory. By using interning, the JVM avoids creating duplicate objects, though it requires careful management to prevent memory leaks if arbitrary strings are interned programmatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15282ef8-59f7-465c-a8de-b327c447b60b', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does the ''Sidecar'' pattern enhance microservices architecture?', N'Senior', N'The sidecar pattern attaches a separate process to a container or pod to handle cross-cutting concerns like logging, service discovery, encryption, or observability. By offloading these tasks to the sidecar, the main application remains focused on business logic and becomes language-agnostic regarding infrastructure concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71ef8ac5-5f74-4ad5-aa12-b3294f473a19', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle large request bodies, and what are the risks?', N'Senior', N'Gin reads request bodies into memory, which can lead to OOM (Out of Memory) errors if attackers send maliciously large payloads. It is critical to use ''MaxMultipartMemory'' or middleware that enforces content-length limits to protect against such exhaustion attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'152307e4-f560-4d10-991c-b32a1fba0ec9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go have a preprocessor?', N'Intern', N'No, Go does not have a preprocessor like C or C++. This design choice helps keep the compilation process fast and the source code clean and predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'897b3a26-4153-4087-bda2-b32c70b747be', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS ensure that ''stores'' remain performant when dealing with deeply nested data?', N'Senior', N'Stores use a proxy-based system that tracks access to specific properties at runtime. This allows SolidJS to create fine-grained subscriptions for deep paths, meaning only the specific component observing a nested property will re-render when that property changes, rather than the entire store being treated as a single unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
