INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0d8b084-f93a-42a0-94d0-b33dcb55b9f7', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the difference between ''val'' and ''const val''.', N'Junior', N'''val'' is a read-only property that is evaluated at runtime, meaning its value can be determined during execution. ''const val'' is a compile-time constant that must be known when the code is compiled. ''const val'' can only be used at the top level or inside an object or companion object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
