INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca0e1fd-cc8c-4ec2-b8de-b34555af8976', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between SQL and NoSQL databases?', N'Junior', N'SQL databases are relational and use structured schemas with tables, while NoSQL databases are non-relational and use flexible data models like documents, key-values, or graphs. NoSQL is generally designed to handle unstructured data and scale horizontally more easily than traditional SQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1e31fcb-fdad-4c7d-a2e1-b347e5d6762f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle server-side rendering (SSR) hydration differently than React?', N'Senior', N'Preact''s hydration process is designed to be lightweight, attempting to patch existing DOM nodes with minimal overhead by avoiding the creation of a full shadow copy of the virtual DOM. While this results in faster time-to-interactive, it requires the server-rendered HTML to match the client-side component structure perfectly to avoid full re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29376fe4-0e8e-4da1-ac1b-b34bdd9705ed', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle concurrency safety?', N'Fresher', N'Go encourages the philosophy of ''Do not communicate by sharing memory; instead, share memory by communicating.'' By using channels to pass data between goroutines, developers can avoid complex locking mechanisms and reduce the risk of data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c2f554-65cf-48c0-91f9-b34c5fdb1fa7', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why might you choose to use an embedded message queue inside an application rather than a standalone broker?', N'Senior', N'Embedded queues eliminate network hops and infrastructure management overhead for low-latency, single-node requirements. However, they lack the scalability, centralized monitoring, and cluster-wide reliability of standalone brokers, making them unsuitable for large, distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69616345-44bb-48b0-97ae-b34e7e7579f4', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Can you use standard CSS in a Sass file?', N'Intern', N'Yes, Sass is a superset of CSS, which means any valid CSS file is also a valid Sass file. You can simply rename a .css file to .scss and start adding Sass features incrementally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
