INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'159b0062-165a-4096-9845-b353d6ad3c60', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Are Sass files browser-ready by default?', N'Junior', N'No, browsers cannot read Sass files directly because they are not valid CSS. Sass files must be compiled or transpiled into standard CSS files before they can be interpreted and rendered by a browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18cc5710-0e3a-4875-8bf2-b3548734d7cf', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM''s adaptive optimization strategy differ from static AOT compilation?', N'Senior', N'Adaptive optimization uses runtime profiles to make decisions about which code paths to optimize based on actual execution data, allowing for highly specific machine code generation. Static AOT compilation makes these decisions at build time, which leads to faster application startup but misses out on runtime-specific optimizations that could otherwise improve performance during steady-state execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e8deb4f-b5d4-4e43-afda-b35674826fc1', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is an execution plan and why is it important?', N'Middle', N'An execution plan is the sequence of operations the database engine determines is the most efficient way to execute a query. It is crucial for performance tuning, as it allows developers to identify bottlenecks like full table scans versus index seeks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'547aa7a7-008b-40e6-b9d9-b358fa1ceb52', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is meant by the term ''utility-first'' in the context of Tailwind CSS?', N'Fresher', N'The utility-first approach means that you style elements by applying small, single-purpose classes directly to your HTML elements. Instead of writing custom CSS classes, you use predefined utility classes for properties like padding, margin, color, and font size to build your interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a9e0eb2-ece4-4393-b596-b35c9eba9ad5', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Compare vertical versus horizontal scaling in MongoDB.', N'Senior', N'Vertical scaling involves increasing the resources of a single node, which has physical limits and diminishing returns. Horizontal scaling, or sharding, distributes data across multiple servers, allowing for virtually unlimited capacity and throughput by adding more commodity hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc2ec02f-232f-4c71-b416-b35f1b44927b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the trade-offs of using DynamoDB Accelerator (DAX)?', N'Senior', N'DAX provides microsecond latency for read-heavy workloads by acting as an in-memory write-through cache. The trade-off is the added cost of managing the cluster, the complexity of managing cache invalidation, and potential consistency challenges if the cache is not configured for the specific application needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f709ba4-2e8d-4c5b-a1f2-b3634ea87c92', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What does the ''Bind'' method do in Gin?', N'Intern', N'The Bind method is used to parse the request body into a specific data structure or struct. It automatically validates the input based on tags defined in the struct, simplifying the process of handling user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bca314f-6baa-4e30-a47c-b3647e95c66a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Unit'' type in Scala?', N'Intern', N'The ''Unit'' type is similar to ''void'' in other languages, indicating that a method does not return a meaningful value. Every method that does not explicitly return a value is considered to return the Unit instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18feebd7-3285-4f6e-8d4e-b365a49b792d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the role of the Phoenix Presence module.', N'Middle', N'Phoenix Presence tracks user state and process metadata across a distributed cluster of nodes. It uses Conflict-free Replicated Data Types (CRDTs) to ensure that presence information is eventually consistent across all nodes without requiring a central database lock.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
