INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'586502ea-a524-41dc-8335-b3693cdd8e81', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the MEAN stack', N'Intern', N'The MEAN (MongoDB, Express, AngularJS, and Node.js) stack is the most popular open-source JavaScript software tech stack available for building dynamic web apps where you can write both the server-side and client-side halves of the web project entirely in JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32975dfd-eb62-483f-9d06-b36bee1f7188', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is garbage collection in the context of C#?', N'Intern', N'Garbage collection is an automatic memory management feature that reclaims memory occupied by objects that are no longer being used by the application. The garbage collector periodically identifies unreachable objects and clears them to prevent memory leaks. This process allows developers to focus on logic without needing to manually allocate and deallocate memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'835a531a-1cb9-43f7-b582-b372d845ea8a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between full and runtime only builds?', N'Fresher', N'There are two types of builds provided by VueJS, 1. Full: These are the builds that contain both the compiler and the runtime. 2. Runtime Only: These builds doesn''t include compiler but the code is responsible for creating Vue instances, rendering and patching virtual DOM. These are about 6KB lighter min+gzip.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dab70f2e-4104-4006-8c62-b3772c890903', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''main'' package in Go?', N'Fresher', N'The main package is a special package that tells the Go compiler that this directory should compile as an executable program rather than a shared library. It must contain a main function, which acts as the entry point of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'128fc8ed-1c6a-4320-afd7-b377b0a935a1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does replication differ from sharding?', N'Middle', N'Replication involves copying data to multiple nodes to ensure high availability and fault tolerance. Sharding involves splitting the dataset across multiple nodes to improve scalability and performance; they are often used together to achieve both availability and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd818c531-2791-4cf4-a3af-b3792252ed1b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle security in a native compiled application?', N'Senior', N'Quarkus integrates security providers at build time, ensuring that cryptographic libraries and authentication modules are correctly included in the native binary. It follows a ''Security-first'' approach by providing out-of-the-box support for OIDC, JWT, and OAuth2, even in restricted native environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd4e183d-5086-4233-932d-b37a650372c9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is async/await and how does it simplify asynchronous code?', N'Intern', N'async/await is a modern syntax in JavaScript that simplifies working with promises. By using the async keyword before a function, you can use the await keyword inside that function to pause execution until a promise is resolved. This makes asynchronous code look and behave more like synchronous code, making it easier to read and maintain. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd53946f6-0446-42c1-b115-b37aa06d2b69', N'075b8862-431c-4678-9767-f55359758a4a', N'What are state preservation rules in hot reloading?', N'Intern', N'Below are the state preservation rules in hot reloading, 1. When editing the of a component, instances of the edited component will re-render in place, preserving all current private state. 2. When editing the part of a component, instances of the edited component will be destroyed and re-created in place. 3. When editing the hot reload operates on its own via vue-style-loader without affecting application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3a59fb1-32f8-45c6-981c-b37af3a1d486', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the risk of over-optimizing a solution too early?', N'Intern', N'Over-optimizing early can lead to ''premature optimization,'' where time is wasted improving parts of a system that are not bottlenecks. It is better to build a functional, readable solution first and then optimize only the specific areas identified by performance testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea646d85-f262-433a-af0a-b37ca9b80ab6', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What does the ''static'' keyword do when used with local variables?', N'Junior', N'When applied to a local variable, static preserves its value between function calls. Instead of being re-initialized every time the function runs, the variable remains in memory for the entire lifetime of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59e5a8a9-95f5-4f91-88a0-b37ebeff27d3', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the ''initialize'' method?', N'Junior', N'The initialize method is a special method that is automatically called when a new instance of a class is created via the new method. It is used to set up the initial state of the object, such as assigning values to instance variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d729880-d028-44fd-9d5d-b37fd9cfc88f', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is data consistency harder to achieve in a microservices architecture compared to a monolith?', N'Middle', N'Microservices typically follow a database-per-service pattern, meaning you cannot rely on ACID transactions across services. You must instead implement eventual consistency patterns like Saga or distributed transactions, which add significant complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'974a65f3-82b9-409b-b26b-b38192a9af8f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the mechanics and purpose of Safepoints in the JVM.', N'Senior', N'Safepoints are specific points in program execution where the state of the JVM is consistent, allowing the GC or other maintenance tasks to inspect thread stacks. Threads reach these points by polling a global flag, ensuring that the runtime can safely perform operations like heap snapshots or thread suspension without risking data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f73f8923-5712-4276-8033-b38224a5a5fa', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a many-to-many relationship?', N'Intern', N'A many-to-many relationship occurs when multiple records in one table can be related to multiple records in another table. This usually requires a junction or bridge table to link the two entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008b1b69-ca55-405e-b86e-b3838513ed40', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of a sidecar pattern in a service mesh, and how does it affect system observability?', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like mTLS, load balancing, and telemetry collection from the application logic to a separate proxy process. This enhances observability by standardizing metrics and logging across diverse services without requiring developers to instrument each application manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89d579e3-c8b6-4e5f-847c-b3863300810f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is it important to use ''tokio::main'' with Axum?', N'Junior', N'Axum handlers and internal components are asynchronous and rely on the Tokio runtime for execution. Using the ''tokio::main'' attribute ensures that the necessary multi-threaded event loop is initialized before the server starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
