INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46eecfed-d8a2-4fe4-84fc-b388ea49e5de', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How do you handle redirects in a Remix action?', N'Junior', N'You use the redirect helper function provided by Remix. It creates a standard HTTP response with a redirect status code, which the browser follows to take the user to a new location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56ca1c91-08c1-4c30-8cbd-b38a8c022220', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix use the Fetch API?', N'Intern', N'Remix uses the Fetch API because it is a standard web interface for making network requests. Using standards makes the framework predictable and allows it to run in various environments, including different server types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60cbbaaa-085c-4f4e-a02f-b38c29e71abb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might a developer choose a synchronous process over an asynchronous one in a small application?', N'Fresher', N'Synchronous processes are easier to implement, reason about, and debug because the execution flow is linear. Asynchronous processes offer better responsiveness but introduce complexity in managing state and error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc416f4b-5d37-426f-abf0-b38cb261e200', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''StripSlashes'' middleware in Chi?', N'Fresher', N'The ''StripSlashes'' middleware is used to normalize URL paths. It ensures that requests with and without a trailing slash are treated as the same route, preventing potential issues with duplicate routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e99fe53e-5bc5-41e5-8a14-b38fadab9c19', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the overheads associated with virtual destructors?', N'Senior', N'Virtual destructors are required to ensure the correct destructor of a derived class is called when an object is deleted through a base class pointer. The overhead involves adding a vtable entry to the class, which increases the object''s memory footprint and introduces an indirect jump during the destruction process, though this is negligible compared to the necessity of preventing memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7ef4669-430c-415c-a7c5-b3935cd966c3', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do you handle file uploads in Rocket?', N'Junior', N'Rocket provides a ''Data'' type to stream incoming file data. You can process this stream and store the file on the server''s filesystem, ensuring that the upload process remains efficient and memory-safe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
