INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ed29f3-3ad7-4726-9d34-b39a0856b6f3', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are path parameters in Actix-web?', N'Intern', N'Path parameters are variable segments within a URL route, such as a user ID. Actix-web allows you to define these segments and extract them directly into function arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6b88533-0c13-4deb-af5f-b39c57fdee39', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the role of the dependency pre-bundling mechanism in Vite?', N'Senior', N'Vite uses the pre-bundling step to convert CommonJS or UMD dependencies into ESM and to consolidate hundreds of small module files into a single request. This prevents the browser from being overwhelmed by the network waterfall effect of hundreds of individual imports during initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
