INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da1ebd65-a205-498c-b7ff-b39ee6ea4853', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''Dispatchers.Main.immediate'' and ''Dispatchers.Main''?', N'Middle', N'''Dispatchers.Main'' always schedules the coroutine execution on the next loop of the main thread, even if already on the main thread. ''immediate'' checks if the current thread is the main thread; if it is, the code executes synchronously, reducing unnecessary scheduling overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
