INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaa92c46-95ec-4856-b82d-b3a1fd038626', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between document.getElementById() and document.querySelector()?', N'Fresher', N'1. document.getElementById(): Returns an element object representing the element whose id property matches the specified string. Since element IDs are required to be unique if specified, they''re a useful way to get access to a specific element quickly. 2. document.querySelector(): Returns the first matching Element node within the node''s subtree. If no matching node is found, null is returned. 3. document.querySelectorAll(): Returns a NodeList containing all matching Element nodes within the node''s subtree, or an empty NodeList if no matches are found. *Note: querySelector() is more useful when we want to use more complex selectors*.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
