INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72447d7f-def0-4683-9e64-b3a40fec4643', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you manage team expectations when an initial architectural assumption is proven wrong midway through a project?', N'Senior', N'I facilitate a transparent ''blameless'' retrospective to assess the impact of the shift and communicate the necessary pivot to stakeholders immediately. I prioritize re-aligning the team on the new direction by breaking the recovery path into high-visibility milestones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa201522-a22a-4232-8218-b3a41464ad94', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why should you use RequestStack instead of injecting the Request object directly into a service?', N'Middle', N'Injecting the Request object directly into a service can lead to errors if the service is instantiated before a request exists, such as in CLI commands. RequestStack provides a proxy that always returns the current request, ensuring the service remains functional across different contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0592823-982d-4cd1-889b-b3a453c53086', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you manage breaking changes in a public API?', N'Middle', N'Breaking changes should be handled by releasing a new version of the API while supporting the old version for a defined deprecation period. This gives consumers time to migrate their integrations without suffering downtime or service interruptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a0d5f03-88ab-4a09-b5c8-b3a9351eabc1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of Mutiny in the Quarkus reactive programming model?', N'Senior', N'Mutiny is an event-driven reactive programming library that provides a more intuitive and readable API for managing asynchronous streams compared to traditional approaches. It serves as the primary reactive engine within Quarkus, enabling complex non-blocking flows with clear error handling and backpressure support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'848d0fbb-e35f-4cb4-b963-b3aa500618ad', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does a database driver do?', N'Intern', N'A database driver is a piece of software that acts as an interface between an application and the database. It allows the application to send commands to the database and receive results back in a compatible format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f00aa86-475e-469d-8f8f-b3b911da659d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React ensure that the UI remains consistent during concurrent transitions?', N'Senior', N'React uses ''transitions'' to categorize updates as either urgent or non-urgent. During a concurrent transition, React calculates the new state in the background and only commits the update to the DOM when the new UI is ready, preventing the display of an inconsistent or partially updated interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e01f125-635b-4d97-ad97-b3b9d89bfd55', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle JSON serialization and deserialization?', N'Intern', N'Axum uses the Serde library for JSON handling. It provides an extractor to automatically parse JSON request bodies into Rust structs and a responder to convert Rust structs into JSON HTTP responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd58a8ec-4c09-44a8-a77a-b3ba02d2e391', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between Value Types and Reference Types in Swift?', N'Middle', N'Value types, such as structs and enums, are copied when assigned or passed, ensuring independent state. Reference types, like classes, share a single instance, meaning changes in one place affect all references. Choosing between them impacts memory management and thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4aa3101d-b403-4aea-982e-b3bb137d07b0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do closures in functional components impact the behavior of hooks, and how does the dependency array mitigate this?', N'Senior', N'Hooks capture variables from the scope in which they were created, meaning they can become stale if dependencies change without the effect re-running. The dependency array acts as a synchronization mechanism, telling React when to discard the old closure and create a new one that captures the updated state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a381ea0a-cdfe-47a9-8b4e-b3bb2e18c6af', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s file-based routing mechanism differ from traditional client-side routers?', N'Middle', N'SvelteKit uses a file-system-based router where the directory structure directly maps to URL paths. This approach eliminates the need for manual route configuration files, simplifies navigation logic, and allows the framework to automatically handle code-splitting at the route level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37d2b8c7-0dd8-439d-a8d6-b3bb94b9f9be', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the benefits of using a middleware pattern in PHP applications?', N'Middle', N'Middleware allows developers to encapsulate cross-cutting concerns like authentication, logging, and error handling into separate, reusable layers. By wrapping the application in a chain of middleware, you keep core business logic clean and allow for a modular approach to request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
