INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c59caab-532d-45ac-aed8-b3c265eb61ea', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the trade-offs of using asynchronous handlers in Axum?', N'Middle', N'Asynchronous handlers allow the server to remain non-blocking while waiting for I/O operations like database queries or network requests, leading to higher throughput. However, they introduce complexity in managing thread safety and potential risks of blocking the executor if CPU-bound tasks are not offloaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98791909-3d38-42c6-81a7-b3c3414cd4f8', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do ''LSM Trees'' differ from ''B-Trees'' for write-heavy workloads?', N'Senior', N'LSM Trees optimize for write throughput by buffering writes in memory and flushing them sequentially to disk in sorted runs. B-Trees perform random I/O updates which are slower, making LSM trees the preferred choice for log-structured storage engines used in modern NoSQL databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6ccc231-2e04-4c41-8685-b3c4e988f2f7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is multithreading?', N'Intern', N'It means running several different programs at the same time concurrently by invoking multiple threads. Multiple threads within a process refer the data space with main thread and they can communicate with each other to share information more easily.Threads are light-weight processes and have less memory overhead. Threads can be used just for quick task like calculating results and also running other processes in the background while the main program is running. Thread Is a functionality or logic which can execute simultaneously along with the other part of the program. Thread is a light weight process. Any program which is under execution is known as process. We can define the threads in python by overwriting run method of thread class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e62def4-ba28-4195-8510-b3c623dbcd78', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the difference between a route and a catcher?', N'Junior', N'A route maps a specific URL and request method to a handler function that processes successful requests. A catcher is a specialized handler that triggers only when an error occurs during the request-response lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5189e70-8c6c-4499-b853-b3c820689517', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between ''is'' and ''==''?', N'Intern', N'The ''=='' operator compares the values of two objects to see if they are equal. The ''is'' operator checks if two variables point to the exact same object in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
