INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10f24600-be15-4559-95fb-b3cb72d4a84a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of eventual consistency in distributed NoSQL systems.', N'Middle', N'Eventual consistency means that if no new updates are made to a data item, all accesses to that item will eventually return the last updated value. This trade-off allows for higher availability and lower latency by allowing replicas to be temporarily out of sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
