INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef82b422-72d3-471b-8c6d-b3eb0adf3dcf', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis and how does it differ from a traditional relational database?', N'Intern', N'Redis is an open-source, in-memory data structure store used as a database, cache, and message broker. Unlike relational databases that store data on disk, Redis stores data in RAM, which allows for significantly faster read and write operations. It uses a key-value model rather than tables with rows and columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
