INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'079e8895-569c-4fbd-8e16-b3f849595e56', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a failable initializer and a standard initializer?', N'Intern', N'A standard initializer guarantees that an instance is created successfully, while a failable initializer can return nil if the initialization parameters are invalid. Failable initializers are useful for handling scenarios where an object cannot be created due to incorrect input data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a931f882-52b6-424f-9120-b3f9964e9fac', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the benefits of using Redis Streams over traditional Pub/Sub for message queuing?', N'Senior', N'Redis Streams provide persistent storage and consumer groups, allowing for message acknowledgment and the ability to re-read messages, which is not possible with traditional Pub/Sub. This makes Streams suitable for reliable, distributed task queues where message loss is unacceptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
