INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9e0b29e-a1e9-434a-92b3-b3fb0292d10d', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is meant by the term ''Ahead-of-Time'' (AOT) compilation in the context of Micronaut?', N'Fresher', N'AOT compilation refers to the process where the framework analyzes the application code during the build phase to generate configuration, bean definitions, and proxies. By moving this work from runtime to build time, the application avoids the overhead of scanning the classpath and performing reflection when the server starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
