INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21dc3ab8-6d7f-45a7-a8bc-b41a1f074674', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the concept of eventual consistency in distributed systems.', N'Middle', N'Eventual consistency is a consistency model that guarantees that, if no new updates are made to a data item, eventually all accesses to that item will return the last updated value. It allows for higher availability and lower latency by not requiring immediate synchronization across all replicas, though it risks reading stale data temporarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ac127be-9a45-4783-b5f0-b41cf4d2ff12', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the problems of using render props with pure components?', N'Intern', N'If you create a function inside a render method, it negates the purpose of pure component. Because the shallow prop comparison will always return false for new props, and each render in this case will generate a new value for the render prop. You can solve this issue by defining the render function as instance method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
