INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82126278-2f56-45c3-8a0e-b44196761aba', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Describe the risks of bypassing the Shadow DOM by using ''createRenderRoot''.', N'Senior', N'Overriding ''createRenderRoot'' to return ''this'' disables Shadow DOM encapsulation, meaning styles defined in the component will leak into the global scope. This should only be used in specific cases, such as when integrating with legacy CSS frameworks that require access to the entire document structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e659937b-8e9f-428f-99f7-b44495f1c603', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach the problem of managing state consistency across multiple microservices?', N'Middle', N'I would evaluate whether strong consistency is strictly required or if eventual consistency is acceptable for the business logic. If eventual consistency is sufficient, I would implement patterns like the Saga pattern or outbox pattern to ensure that all services eventually reach the correct state without locking resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d692409-2922-405a-b09d-b44ac6c3b3f9', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the architectural risks of having ''hot partitions'' in a message broker cluster?', N'Senior', N'Hot partitions occur when keys are unevenly distributed, causing a single node to handle significantly more traffic than others. This creates a bottleneck that limits the throughput of the entire cluster and can lead to node failure due to resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79b1f779-a561-42c9-b3ac-b44dff8dcf68', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the advantages of using Ecto Changesets for data validation?', N'Middle', N'Changesets decouple data validation from database insertion, allowing you to validate data structures before they ever hit the database. They also provide a clean way to track changes and handle errors, making them ideal for forms and API input validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cba11a2e-2645-4d11-85ac-b44e3aebc1b2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are Alpine.js ''refs''?', N'Fresher', N'Refs provide a way to access specific DOM elements directly within your component logic. By adding an x-ref attribute to an element, you can easily reference it in your JavaScript expressions using the $refs magic property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddea4471-f923-4ca7-829e-b451d0184430', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does it mean for Redis to be a NoSQL database?', N'Intern', N'Being a NoSQL database means Redis does not use the traditional relational table structure or SQL as its primary query language. Instead, it provides a flexible schema-less approach by storing data in various formats like strings, hashes, lists, and sets. This design prioritizes high performance and scalability over the complex relational constraints found in SQL databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93aa7149-3a0f-4d7e-8da1-b4563f0a1127', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What does ''Hydration'' mean in Nuxt?', N'Fresher', N'Hydration is the process where the client-side JavaScript takes over a static HTML page delivered by the server. It attaches event listeners and makes the page interactive, turning the static content into a fully functional application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef0a7482-38b8-48c2-b9ee-b456f22fe27d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a complex technical problem that you have never encountered before?', N'Intern', N'I start by breaking the problem into smaller, manageable components to understand the individual requirements. I then research existing documentation, standard practices, and theoretical frameworks to see how similar issues have been resolved. Finally, I identify the core constraints and test potential solutions conceptually before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dc1fea7-2b67-41af-a64e-b457a0406610', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is Quarkus considered suitable for microservices?', N'Fresher', N'Quarkus is ideal for microservices because of its small footprint and rapid startup time, which allows for efficient scaling in container orchestration platforms. It also offers built-in support for fault tolerance, health checks, and metrics, which are essential for managing distributed services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e5832e5-334c-4b63-b83c-b458973560de', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the ''Sidecar'' pattern improve the operability of microservices?', N'Senior', N'The sidecar pattern allows you to offload cross-cutting concerns like logging, monitoring, and security to a separate container that runs alongside the main application. This keeps the application code focused on business logic while standardizing infrastructure capabilities across different languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
