INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92dd2693-c996-43b7-bb25-b4626687bd84', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between createElement and cloneElement?', N'Fresher', N'Both React.createElement and React.cloneElement are used to work with React elements, but they serve different purposes. createElement: Creates a new React element from scratch. JSX elements will be transpiled to React.createElement() functions to create React elements which are going to be used for the object representation of UI. Syntax: Example: cloneElement: The cloneElement method is used to clone an existing React element and optionally adds or overrides props. Syntax: Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e2c528f-7dfe-4d21-aee9-b462dfebcd6e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does data denormalization help performance in NoSQL?', N'Intern', N'Denormalization involves storing related data together in one place, which eliminates the need for expensive join operations at read-time. By reading all necessary information in a single request, the application performance is significantly improved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7dd6ba9-fdfe-4a82-9e96-b464a8aad41f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How do you handle exceptions in Dart?', N'Fresher', N'Exceptions are handled using ''try'', ''catch'', and ''finally'' blocks. You place code that might throw an error inside the ''try'' block, catch specific exceptions in the ''catch'' block, and use ''finally'' to execute cleanup code regardless of whether an error occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6366251b-726b-4e48-827e-b46a867f1faa', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of Middleware in Laravel?', N'Intern', N'Middleware provides a convenient mechanism for inspecting and filtering HTTP requests entering your application. For example, a middleware can verify if a user is authenticated or check if they have specific permissions before allowing them to access a certain route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc2a5396-4b1f-4488-bc52-b46ef89cb735', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the trade-offs of using GraphQL in a microservices architecture?', N'Senior', N'GraphQL provides a powerful way for clients to fetch exactly the data they need, reducing over-fetching and under-fetching. However, it can make it difficult to implement fine-grained caching, rate limiting, and backend performance monitoring compared to RESTful services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'241b65ee-c360-47c5-bd47-b4709f209da0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach the decision to migrate a monolith to microservices versus optimizing the existing monolith?', N'Senior', N'I assess the pain points in the current development lifecycle, such as deployment bottlenecks or team coupling, against the complexity overhead of distributed systems. If the monolith''s constraints outweigh the operational complexity of service discovery, network latency, and data consistency, then a phased extraction strategy is preferred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e404fa9c-fa20-47ae-b21c-b470f100c12a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is structuredClone and how is it used for deep copying objects?', N'Intern', N'In JavaScript, structuredClone() is a built-in method used to create a deep copy of a value. It safely clones nested objects, arrays, Maps, Sets, Dates, TypedArrays, and even circular references — without sharing references to the original value. This prevents accidental mutations and makes it useful for state management and data processing. For example, the below snippet demonstrates deep cloning of a nested object, `javascript const originalObject = { name: "Deep Copy Test", nested: { value: 10, list: [1, 2, 3] }, }; const deepCopy = structuredClone(originalObject); // Modify cloned value deepCopy.nested.value = 99; deepCopy.nested.list.push(4); console.log(originalObject.nested.value); // 10 console.log(deepCopy.nested.value); // 99 console.log(originalObject.nested.list); // [1, 2, 3]...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88b7e064-5fbc-4795-9b49-b471c79a8a25', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can you define what Hono''s ''builtin middleware'' refers to?', N'Fresher', N'Hono includes a set of pre-built, commonly used middleware functions that are shipped with the framework. These include tools for tasks like basic logging, handling CORS, providing basic authentication, and serving static files, which saves developers from writing these features from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'787e867e-e794-4458-9293-b4721e5a3033', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does transaction isolation affect the performance of read-only analytical queries in a mixed-workload system?', N'Senior', N'Using snapshot-based isolation allows read-only analytical queries to access a consistent point-in-time view of the data without acquiring locks. This prevents analytical queries from blocking or being blocked by write-heavy OLTP transactions, thereby maximizing concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f819253e-776a-4d02-b8e9-b4724cbcec57', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the architectural implications of implementing database sharding?', N'Senior', N'Sharding increases complexity by requiring a sharding key strategy and a mechanism to route queries to the correct shard. It also complicates cross-shard joins and transactions, necessitating application-level logic or distributed transaction managers to maintain data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ceba0330-0d11-4387-8e5b-b4744ffece9b', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between a Future and a Stream?', N'Junior', N'A Future represents a single asynchronous operation that will eventually complete with a value or an error. A Stream represents a sequence of asynchronous events, allowing you to receive multiple values over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cf87729-f823-4eb1-aad1-b477f162e230', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''cors'' package?', N'Junior', N'CORS, or Cross-Origin Resource Sharing, is a security feature implemented by browsers to restrict web pages from making requests to a domain different from the one that served the web page. The ''cors'' package allows developers to easily configure which origins are permitted to access the Express API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c59a21d0-b510-4b8f-bf29-b47d87f4cf46', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a sealed class?', N'Intern', N'A sealed class is a class that cannot be inherited by any other class. This is often used to prevent modification of a class''s behavior through inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66383ec1-fb2b-4545-bb28-b47d95fceea9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Can you perform transactions in Redis?', N'Fresher', N'Yes, Redis supports basic transactions using commands that group a sequence of operations. These operations are executed sequentially as a single isolated event.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1fbbcc0-30ee-4b49-9f17-b47dfbc49e4d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is a ''canary deployment'' and how does it relate to reliability?', N'Middle', N'A canary deployment releases a new version of software to a small subset of users before rolling it out to the entire environment. It allows for real-world testing and early detection of bugs or performance degradation, minimizing the ''blast radius'' if something goes wrong.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3942a34e-7d28-4df9-9c34-b47e5b921af4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between shallow and deep copying in C++?', N'Middle', N'A shallow copy duplicates the object''s member values, which can lead to double-free errors if those members are pointers to dynamic memory. A deep copy allocates new memory for the pointed-to data and copies the contents, ensuring that each object manages its own unique resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1619e445-5314-46f8-a5ab-b47ee6285eae', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java Memory Model (JMM) define the happens-before relationship?', N'Senior', N'The happens-before relationship is a partial ordering of memory operations that guarantees memory visibility between threads. It dictates that if one action happens-before another, the results of the first are visible to the second, providing the theoretical foundation for thread safety in concurrent programs without relying solely on lower-level hardware memory barriers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cef9d4c6-7dde-4aee-946b-b484b0941d08', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does a distributed lock service assist in scaling?', N'Middle', N'Distributed lock services coordinate access to shared resources across multiple service instances to prevent race conditions. This is essential for maintaining data integrity when scaling out systems that modify the same underlying data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dc439b5-8566-4f17-b9cb-b4851902a576', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage streaming responses?', N'Middle', N'Hono supports streaming by leveraging the native ReadableStream API, allowing servers to send data in chunks to the client. This is highly effective for reducing Time to First Byte (TTFB) and handling large payloads without loading the entire response into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
