INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49eea471-6640-4f6d-a526-b4896f408ffd', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go prioritize simple, explicit error handling over exceptions?', N'Senior', N'Go''s error handling design forces developers to treat errors as values that must be explicitly checked, which promotes predictable code flow and easier debugging. Exceptions can create hidden control flow paths that make it difficult to reason about the state of the application during a failure. By returning errors, the language ensures that the caller is aware of potential failures and can handle them in a way appropriate to the local context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f45dfcaa-c3ab-410c-abdf-b48b4cd97aa2', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you handle incoming JSON data in a Litestar route handler?', N'Junior', N'You handle JSON data by defining a data parameter in your route handler function with a specific type hint. Litestar automatically parses the request body and validates it against that type before your function code executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
