INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53958be6-4cd2-4cb5-900d-b490f0628c25', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the difference between ''Lazy Parsing'' and ''Eager Parsing'' in modern engines.', N'Senior', N'Eager parsing generates a full AST for immediate execution, while lazy parsing creates a lightweight representation of functions that are not currently needed. This optimization significantly reduces startup time by delaying the expensive process of parsing and syntax checking until a function is actually invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
