INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0377f9cd-156f-4e0f-abc6-b4ad7755efcf', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the ''translog'' in Elasticsearch?', N'Middle', N'The translog is a persistent write-ahead log that records all operations before they are flushed to the Lucene index. It ensures data durability in the event of a crash, as operations that have not yet been committed to a Lucene segment can be replayed from the translog upon restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
