INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5c2a2d3-3aae-4a9d-be24-b4b638a4df1d', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the primary differences between optimistic and pessimistic concurrency control?', N'Senior', N'Pessimistic concurrency uses locks to prevent conflicts before they happen, which is effective for high-contention environments but reduces performance due to blocking. Optimistic control assumes conflicts are rare and validates the transaction at commit time, which increases throughput but requires logic to handle retries upon collision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8262885e-8bd8-48fa-a05a-b4bbc61586cc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why might ''dummy'' data be useful in troubleshooting?', N'Fresher', N'Dummy data allows you to test specific scenarios without risks associated with real production data. It helps confirm if a bug is related to the data format or the logic processing that data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd236897e-f5bf-4acc-a37e-b4bc4947d347', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between synchronous and asynchronous execution in the context of the JavaScript event loop?', N'Middle', N'Synchronous code blocks the call stack, executing sequentially until completion. Asynchronous code offloads tasks to the browser or Node.js APIs, placing callbacks into the task queue to be processed by the event loop once the stack is empty.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a149576-724b-40b4-a407-b4bcb952fedf', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a candidate key?', N'Fresher', N'A candidate key is a column or set of columns that can uniquely identify a record in a table. A table may have multiple candidate keys, and one of them is selected as the primary key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02c0abec-783c-4e08-95f9-b4bd5fad770b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'You are designing a distributed system where data consistency and system availability are both critical, but network partitions are inevitable. How do you approach the trade-off between consistency and latency when selecting a replication strategy for a globally distributed database?', N'Senior', N'I would evaluate the specific business requirements to determine whether the system can tolerate stale reads or if it must guarantee linearizability, effectively navigating the CAP theorem constraints. For latency-sensitive workloads, I would propose an asynchronous replication model or conflict-free replicated data types (CRDTs) to prioritize availability, acknowledging that this requires robust conflict resolution logic. If strict consistency is non-negotiable for specific transaction paths, I would implement multi-leader or synchronous quorum-based writes, while mitigating the resulting latency impact through intelligent regional data sharding and localized read replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6062ca9a-6038-4f71-9b92-b4bdc8223b4f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you access history in javascript', N'Fresher', N'The window.history object contains the browser''s history. You can load previous and next URLs in the history using back() and next() methods. Note: You can also access history without window prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'917e79c9-365d-44ab-aef8-b4d2b5f8f6ee', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''dynamic'' keyword in Dart?', N'Fresher', N'The dynamic keyword disables static type checking, allowing a variable to hold any type of value. While it provides flexibility, it should be used sparingly because it bypasses the safety benefits of Dart''s strong type system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e2e1fc4-8b07-481e-9b0f-b4d2d2ba43b7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Does AdonisJS support session-based authentication?', N'Intern', N'Yes, AdonisJS has built-in support for session-based authentication. It handles the storage and retrieval of user sessions, making it easy to keep users logged in across multiple page requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e33f83ae-fb6e-4679-ac7d-b4d6eb1ac275', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C memory model handle the ''strict aliasing rule'', and what are the architectural implications for compiler optimization?', N'Senior', N'The strict aliasing rule prohibits accessing an object through a pointer of a different type, with few exceptions like character types. This constraint allows compilers to assume that pointers of incompatible types do not alias the same memory location, enabling aggressive optimizations such as reordering memory operations and keeping values in registers across stores. Violating this rule leads to undefined behavior because the compiler may have already cached memory values in registers based on the assumption that no alias exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9902fe1-a521-45a7-b41c-b4d871b99d94', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database migrations, and why should you avoid manual schema changes?', N'Middle', N'Django migrations track changes to your model definitions and apply them to the database schema in a version-controlled manner. Bypassing them with manual changes causes the database state to drift from the codebase, leading to deployment failures and synchronization issues in team environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'168c3fa2-92af-44ea-9fd7-b4d8eca3b669', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber manage memory allocation for request and response objects?', N'Middle', N'Fiber leverages sync.Pool to reuse objects that are frequently allocated, such as request contexts and headers. This reduces the pressure on the Go garbage collector by recycling memory rather than letting it be reclaimed after every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6cc80fc-d0f1-47af-aad0-b4da655376bb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do C# ''Generics'' behave differently for reference types versus value types at runtime?', N'Senior', N'The runtime creates specialized machine code for generic types instantiated with value types to avoid boxing and improve performance. For reference types, the runtime shares a single implementation because all reference types are pointer-sized, relying on the JIT compiler to generate the necessary type-specific logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0828e5bd-b4f6-40f6-89ce-b4dc184ad656', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does the ''static lifetime mean?', N'Junior', N'The ''static lifetime denotes that a reference can live for the entire duration of the program. It is commonly used for string literals that are embedded directly into the program''s binary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe5d0fa7-cb2f-4e32-9eac-b4dd385f8fe4', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the main advantage of using FastAPI''s dependency injection system?', N'Junior', N'It allows for clean, modular code by decoupling logic such as database connections, authentication, and configuration from your path operations. It makes code easier to test because you can override dependencies with mock versions during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7771be49-f2b5-4995-a167-b4dd4f2aa2de', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to provide an estimate without a full requirements document, how do you proceed?', N'Middle', N'I provide a high-level order-of-magnitude estimate based on similar past projects and explicitly state the assumptions made. I frame the estimate as a rough baseline that will be refined and narrowed down once the requirements are formalized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
