INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c58be43-dae4-4eb6-8915-b4e6b3a5ae75', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the ''Extractor'' in Actix?', N'Intern', N'An extractor is a mechanism used to pull specific data from an HTTP request, such as JSON bodies, path parameters, or query strings. It automatically validates and converts this data into a usable Rust type for the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46635ee5-dbe4-49e4-bc76-b4e824ba3da2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a system where logs show a service is receiving requests but not emitting responses?', N'Senior', N'I would check for thread pool exhaustion, where all worker threads are stuck in a blocked state, often due to synchronous I/O or waiting on a downstream resource. I would also verify if the process is stuck in a deadlock or if it has entered an infinite loop that prevents it from returning to the event loop or request processor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f548e725-d0a2-4671-be73-b4ea208dbb58', N'954a0331-deff-4399-b588-96f39fec001d', N'How is data shared between components?', N'Fresher', N'Data sharing between Angular components depends on their relationship: - Parent to Child: Use the @Input() decorator in the child component to receive data passed from the parent''s template. - Child to Parent: Use the @Output() decorator and EventEmitter in the child component to emit events (often carrying data) that the parent component listens to in its template. - Sibling or Unrelated Components: Use a shared service. The service holds the data and provides methods to update and access it. Components inject the service and interact with it. For reactive data updates, the service typically uses RxJS Observables (Subject, BehaviorSubject) or Signals (available from Angular 17+). > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
