INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba0284a4-5bb6-4962-8a76-b4eb66c2f1ab', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is meant by ''Stateless'' in the context of Web APIs?', N'Intern', N'Stateless means that each individual HTTP request contains all the information necessary for the server to understand and process it. The server does not store any client session information between requests, which improves scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4291d71-aed0-47ef-8dcf-b4eb97167c88', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are the advantages of using custom Eloquent Scopes compared to standard query building?', N'Senior', N'Custom scopes allow you to encapsulate common query constraints into reusable, expressive methods on your models. This improves code maintainability by ensuring that complex logic, such as status filters or date-range constraints, is defined in one place and used consistently throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eab5b7ac-b92c-4d69-81e6-b4ebd8bde243', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Discuss the trade-offs of using Tailwind''s ''apply'' directive in CSS files.', N'Senior', N'The ''apply'' directive allows for extracting complex utility patterns into reusable CSS classes, which can help clean up markup. However, overuse of ''apply'' can lead to ''CSS-in-CSS'' problems, effectively recreating the maintenance debt of traditional stylesheets if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7810642f-005b-4e9a-861e-b4ee064a29bb', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python handle the `LEGB` scope resolution rule?', N'Senior', N'Python resolves variable names by searching in order: Local, Enclosing (non-local), Global, and Built-in scopes. This hierarchy ensures that inner scopes have access to outer scopes, but prevents accidental mutation of global variables without explicit declarations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4077a6bc-3ef8-43d3-815e-b4ee53ea1f50', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Describe the trade-offs between stateless and stateful API designs in terms of scalability.', N'Senior', N'Stateless designs allow any server instance to handle any request, enabling seamless horizontal scaling and simplified load balancing. Stateful designs require session stickiness or external state management, which increases complexity and makes it difficult to scale the system dynamically during traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb7aee6a-97b4-4758-a86e-b4f8f6b972c3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is ''Database Sharding'' and what are its primary architectural challenges?', N'Senior', N'Sharding is the horizontal partitioning of data across multiple independent database instances to scale write throughput and storage capacity. The primary challenges include managing cross-shard joins, maintaining global uniqueness of primary keys, and rebalancing data as the system grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5389eac2-2953-49a2-b639-b4fac36b81f1', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage browser history and state transitions differently from traditional SPA frameworks?', N'Senior', N'Remix treats navigation as a mechanism to re-fetch only the data required for the changed routes, rather than reloading the entire application state. It uses the browser''s native history API effectively, ensuring that back/forward buttons work naturally with the server-rendered state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
