INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34e340f8-1839-4767-b49e-b4fea23c5ae4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum''s design handle the ''async trait'' limitation in Rust?', N'Senior', N'Axum uses a combination of generics and specialized traits to bridge the gap created by Rust''s current lack of native async trait support. By leveraging ''Future'' return types and specific trait bounds, it manages to provide a clean, ergonomic experience despite the underlying language complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18fac3ba-c62b-479b-87ee-b5013d022f04', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Idempotency'' contribute to system reliability?', N'Middle', N'Idempotency ensures that performing the same operation multiple times produces the same result as performing it once. This is vital in distributed systems where network retries are common, as it prevents duplicate actions or corrupted data states when a request is inadvertently sent twice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
