INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd984720a-835e-4a86-a0b4-b503e8098be4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Discuss the performance trade-offs of using high-resolution images as CSS backgrounds compared to ''img'' tags.', N'Senior', N'Background images defined in CSS are often discovered later by the browser''s preload scanner, potentially delaying the visual load. Unlike img tags, they are difficult for the browser to prioritize and cannot leverage modern loading attributes like ''lazy'' or ''fetchpriority'', making them less optimal for critical image content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
