INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dddcf0f-e9c5-4bb6-836d-b508922f6634', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''Write Barrier'' in Go''s garbage collector?', N'Senior', N'The write barrier is a mechanism used during concurrent marking to ensure that pointers modified by the application during the garbage collection cycle are tracked correctly. It prevents the collector from missing live objects that could be moved between memory locations while the marking process is concurrently running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc8384a6-d4af-40ce-927f-b50d9092f517', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of the Next.js middleware feature?', N'Middle', N'Middleware allows you to run code before a request is completed, enabling logic like authentication, URL rewrites, redirects, or header manipulation. Because it runs at the edge, it provides a performant way to intercept requests without hitting your primary application server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7c0ce2d-64e4-4e6a-83c2-b50f686c691c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you address the ''Thundering Herd'' problem in API design?', N'Senior', N'The thundering herd occurs when many clients request the same expired cached resource simultaneously, overwhelming the backend. This is mitigated by implementing request collapsing, jittered cache expiration, or stale-while-revalidate patterns to ensure only one process refreshes the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
