INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bd855f5-1e46-4bd0-9ce7-b528e0efb59e', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the role of the ''v-once'' and ''v-memo'' directives in performance optimization?', N'Senior', N'v-once renders an element or component only once and skips updates, while v-memo allows for conditional re-rendering based on specific reactive dependencies. Both are powerful tools for optimizing complex list renderings by reducing the amount of work the virtual DOM diffing process performs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d762320-d595-479b-b3d7-b52910809268', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''Double Assertion'' pattern, and why is it generally considered an anti-pattern?', N'Senior', N'A double assertion involves casting a value to ''unknown'' and then to a target type, effectively bypassing TypeScript''s safety checks for type compatibility. It is considered an anti-pattern because it hides structural mismatches, potentially leading to runtime crashes when the actual data structure does not align with the assertion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f46e9d1-5844-4b8a-b49e-b52a67484ced', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between a Controller and a standalone route handler in Litestar?', N'Intern', N'A Controller is a class that groups related route handlers together, allowing for shared configuration like base paths, security requirements, or middleware. Standalone route handlers are independent functions used for smaller or isolated API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b01db684-33cf-42db-b403-b52e885a26d3', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do PHP''s typed properties improve engine-level performance and runtime stability?', N'Senior', N'Typed properties allow the Zend Engine to enforce schema integrity at the language level rather than through manual validation. This reduces the need for defensive type-checking code and allows the engine to optimize memory layout for specific data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30a7f3cc-3a1a-49e1-ab53-b52ea27f6367', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Does Redis support data expiration?', N'Fresher', N'Yes, Redis natively supports data expiration using commands like EXPIRE or PEXPIRE. This allows developers to manage memory usage by ensuring that temporary data is automatically cleaned up after a defined period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e38040ac-8884-457c-9928-b52fb688ea44', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle errors?', N'Fresher', N'Echo features a centralized HTTP error handler that catches errors returned by handlers or middleware. This ensures that the application returns consistent error responses, such as JSON-formatted messages and appropriate HTTP status codes, instead of crashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4243c6cf-3061-43f8-aa09-b5314a54af10', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''unknown'' type?', N'Intern', N'The ''unknown'' type is a type-safe counterpart to ''any''. It represents any value, but unlike ''any'', you must perform type checking or narrowing before you can perform operations on a variable of type ''unknown''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eca9b35c-9c7c-4021-9ffe-b531c67e7312', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What happens if a system crashes during a transaction commit?', N'Intern', N'The database uses the transaction log during the recovery process to determine if the transaction was fully committed or not. If the log shows the commit was completed, it ensures the changes are persisted; otherwise, it rolls back the partial changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc1aba6c-b3fe-4add-b415-b53271deaf65', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is a message broker''s role in implementing the Saga pattern?', N'Middle', N'In a distributed transaction spanning multiple services, the broker manages the sequence of events and compensating actions. It ensures that if one step in the transaction fails, the subsequent events required to roll back previous state changes are reliably delivered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a7c5c1f-94a6-495c-bfb8-b534ce6de3eb', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the purpose of the ''Prefer'' header in HTTP, and why is it useful?', N'Senior', N'The Prefer header allows the client to request specific server-side behaviors, such as returning the full object after a POST request or executing the request asynchronously. It helps reduce payload sizes and improves performance by allowing clients to control server response depth without needing separate API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc021589-dd77-46a1-a10e-b53649949d96', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the primary role of the event loop in Node.js?', N'Intern', N'The event loop is the mechanism that allows Node.js to perform non-blocking I/O operations despite JavaScript being single-threaded. It offloads operations to the system kernel whenever possible and continuously monitors the call stack and the task queues to execute callbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da9a990f-5f3d-41c8-a290-b537c9352dde', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is an interface in TypeScript and why is it useful?', N'Intern', N'An interface is a way to define a contract for the shape of an object, specifying which properties it must have and their corresponding types. It is useful because it allows developers to enforce consistency across their application and provides clear documentation about what data structures are expected in different functions or components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef90a7c4-f4b7-42f1-b0d4-b5381d271e68', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of ''False Sharing'' and how the @Contended annotation mitigates it.', N'Senior', N'False sharing occurs when multiple threads modify variables residing on the same CPU cache line, causing unnecessary cache coherency traffic and performance degradation. The @Contended annotation instructs the JVM to pad the object fields, forcing them onto different cache lines and preventing the hardware from invalidating caches needlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b89d4805-8bea-4c69-967f-b5387c13b2ea', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar utilize Pydantic for data validation?', N'Junior', N'Litestar uses Pydantic models to automatically validate incoming request data and serialize outgoing response data. If the incoming data does not match the defined model schema, Litestar automatically raises a validation error, returning a 422 status code to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f456778e-2075-4efd-9de7-b53ad5a74734', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS''s reactivity model differ from React''s virtual DOM approach?', N'Middle', N'React relies on a virtual DOM and re-renders components top-down whenever state changes, which requires reconciliation. SolidJS uses fine-grained reactivity where components execute only once during initialization; updates are performed by directly modifying specific DOM nodes via granular subscriptions, eliminating the need for a virtual DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'828e4383-f045-4bbd-8ba7-b53ef555b68a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is ownership in Rust and why is it important?', N'Intern', N'Ownership in Rust refers to the rules regarding memory management and resource handling. It''s a fundamental concept for understanding Rust''s memory safety, and it ensures both thread and memory safety without the need for a garbage collector. Key Ownership Principles - Each Variable Owns its Data: In Rust, a single variable "owns" the data it points to. This ensures clear accountability for memory management. - Ownership is Transferred: When an owned piece of data is assigned to another variable or passed into a function, its ownership is transferred from the previous owner. - Only One Owner at a Time: To protect against data races and unsafe memory access, Rust enforces that only one owner (variable or function) exists at any given time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5bb8e8e-6229-413c-ad13-b53f8720f421', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of a consensus algorithm in a distributed database cluster?', N'Senior', N'Consensus algorithms like Raft or Paxos ensure that all nodes in a cluster agree on the order and state of transactions, even in the presence of node failures or network partitions. They are essential for maintaining strong consistency across distributed replicas, ensuring that the system behaves as a single logical entity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
