INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5da49234-6646-42f5-a1ea-b545cc38c753', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is ''String Interning'' and why should it be used cautiously?', N'Senior', N'String interning stores a single instance of a literal string in a special pool, allowing multiple references to point to the same memory address. It saves memory for repetitive strings but can cause performance issues if applied to dynamic strings, as the interning table grows and incurs synchronization overhead, potentially leading to memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
