INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6e46113-8165-4ec5-a9e2-b547affe180f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you handle performance for large CSS files?', N'Middle', N'Performance for large files can be improved by minifying the CSS, removing unused styles, and splitting CSS into smaller chunks that are loaded only when needed. Techniques like critical CSS, which loads only the styles required for the above-the-fold content, also significantly improve initial load times. Using modern tools to purge unused CSS during the build process is also highly effective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02eaeba6-736b-4a31-891c-b5483bb6bac2', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the performance implications of creating indexes on highly volatile fields?', N'Middle', N'Indexing fields that change frequently causes the index to be updated with every write operation, which introduces significant overhead. This can lead to increased write latency and index fragmentation, negatively impacting overall database performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b629d785-68a6-495b-badc-b54aff3a6a6b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle database connections?', N'Junior', N'Flask does not have a built-in database layer, so developers typically use extensions like Flask-SQLAlchemy. These extensions manage the connection pool and ensure that connections are properly opened and closed during a request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6121ad75-601b-4731-9bff-b54d4a2ae762', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Query Parameters in Ember?', N'Junior', N'Query parameters are pieces of state that are reflected in the URL, usually after a question mark. They allow users to share a specific view or filter state, such as search results or pagination, by simply sharing the link.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd613ae48-bec2-49dc-a295-b54e672336b3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is it difficult to achieve both high performance and strong consistency in a geographically distributed system?', N'Senior', N'The CAP theorem and the PACELC trade-off dictate that in the presence of network latency or partitions, one must choose between consistency and latency. Synchronizing state across geographic distances requires multiple round trips for consensus, which inherently increases latency for write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbc056a7-e48d-43ba-a703-b5505e8ca1b3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does the ''divide and conquer'' strategy apply to debugging a complex system?', N'Junior', N'This strategy involves breaking the system into smaller, independent modules and testing each one to see if it functions as expected. By isolating the failing component, you reduce the complexity of the debugging process and make it easier to pinpoint the exact location of the error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'572bc220-3afc-42d6-a389-b5527f8a92ea', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the impact of the ''Write-Ahead Log'' (WAL) on database durability and performance.', N'Senior', N'WAL ensures durability by persisting transaction changes to stable storage before applying them to the data files, allowing recovery after crashes. While it adds I/O overhead, it improves performance by transforming random data page updates into sequential log writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71d3e20d-61f6-4c15-b15b-b554231d78fe', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a clustered index?', N'Intern', N'A clustered index determines the physical order of data in a table. Because the data rows themselves can only be sorted in one order, there can be only one clustered index per table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ce8af5f-cb99-4d4c-9b90-b554eb524bad', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the significance of the ''useTransition'' hook in maintaining a fluid UI?', N'Senior', N'useTransition allows developers to mark state updates as non-urgent transitions, signaling to React that they can be interrupted by higher-priority tasks like user input. This prevents the UI from freezing during heavy processing, ensuring that immediate feedback remains smooth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'337b0fb7-44cf-4db9-b653-b5551605b172', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle distributed tracing in a microservices architecture?', N'Senior', N'Distribute unique Trace IDs and Span IDs across all service boundaries via HTTP headers or message metadata. These IDs are collected by a tracing agent and forwarded to a centralized store to reconstruct the request lifecycle, which is essential for debugging latency and failures in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0469d232-1454-4379-9ea9-b555952eb954', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your strategy for managing database schema migrations in a high-availability environment?', N'Senior', N'I enforce backward-compatible schema changes, such as adding nullable columns instead of renaming existing ones. This allows the application to deploy across multiple versions simultaneously without downtime, followed by a cleanup phase once the new code version is fully adopted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9325855-33bc-43f5-bff3-b555a7633e36', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the trade-offs of implementing a circuit breaker pattern?', N'Senior', N'Circuit breakers protect downstream services by failing fast when a dependency is unhealthy, preventing cascading failures. While this improves overall system stability, it requires careful configuration of failure thresholds and timeout settings to avoid premature tripping or slow detection of recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c3f30ea-cb14-499e-a28e-b55830a180d4', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can you use Alpine.js with other libraries like Tailwind CSS?', N'Junior', N'Yes, Alpine.js is designed to be highly compatible with Tailwind CSS. Since both libraries are meant to be used directly within HTML markup, they work seamlessly together to create interactive and styled components without needing external build tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcaceb17-e772-4c39-9d39-b55941da0a33', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''defer'' keyword in Go?', N'Fresher', N'The defer keyword schedules a function call to be executed immediately before the surrounding function returns. It is primarily used for cleanup tasks, such as closing files or releasing network connections, ensuring these actions occur regardless of how the function exits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e72d76f-bfd7-4bcc-b901-b55cbfe9b70a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''def'' and ''val'' when defining a member of a class?', N'Fresher', N'A ''def'' defines a method that is evaluated every time it is called, whereas a ''val'' defines a field that is evaluated only once when the object is initialized. Using ''val'' is more efficient for constant values, while ''def'' is necessary for logic that depends on parameters or dynamic state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5530f9f-deed-4ac4-b377-b55cc7e3c24d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle configuration?', N'Intern', N'NestJS handles configuration typically through a dedicated module that loads environment variables from a file. This allows developers to manage different settings for various environments like development, staging, or production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18a1b48a-7e7d-40d4-82c3-b55cfecfe089', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the alt attribute used for in images?', N'Intern', N'The alt attribute provides alternative text for an image if the image fails to load or if a user is using a screen reader. It is essential for web accessibility, as it describes the content or function of the image to visually impaired users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd82208dd-932a-46c0-8a20-b55e36185f4f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is FastAPI considered ''fast''?', N'Intern', N'FastAPI is considered fast because it is built on Starlette and Pydantic, which are designed for high performance. Its asynchronous nature allows it to handle many concurrent connections effectively, making it competitive with other high-performance frameworks like Go or Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3113512-1e5f-44d9-ad4a-b5602beaef0f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''any'' type and why should it be avoided?', N'Fresher', N'The ''any'' type tells the compiler to opt out of type checking for a variable, effectively treating it like standard JavaScript. It should be avoided because it bypasses the safety benefits of TypeScript and can lead to hidden runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da1ed895-f09c-4518-afef-b56156c64558', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'When should you use a database index, and what are the trade-offs?', N'Middle', N'Indexes significantly speed up data retrieval queries by creating a lookup structure for table columns. The trade-off is that they increase storage space and can slightly slow down write operations, as the index must be updated whenever data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e729cbcc-cd71-4a8b-b1a5-b5635ec72354', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle automatic documentation, and why is it useful?', N'Middle', N'FastAPI automatically generates interactive OpenAPI and JSON Schema documentation based on the path operations and type hints defined in the code. This documentation is exposed via Swagger UI and ReDoc, which facilitates seamless communication between backend and frontend teams and serves as a living specification for API consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8852d69c-f780-4f24-8fec-b568230ee833', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure that your team''s code remains maintainable as the project grows?', N'Middle', N'I advocate for consistent coding standards, automated linting, and regular code reviews that focus on design patterns rather than just correctness. I also encourage the team to prioritize clear documentation and modular design, which helps new members onboard easily and reduces complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1147486d-23d4-440b-8446-b5689177d154', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does database encryption at rest impact system design and recovery?', N'Senior', N'While encryption at rest protects against physical disk theft, it necessitates a robust key management architecture, as losing access to the encryption keys results in permanent data loss. Architecturally, one must account for the latency overhead of cryptographic operations and integrate the key management system into the disaster recovery plan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5ed8265-ffda-4681-a032-b56c6bc5da8e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the role of the JIT (Just-in-Time) compiler in Tailwind CSS.', N'Middle', N'The JIT compiler generates CSS on-demand as you author your HTML, rather than generating all possible utility classes upfront. This allows for arbitrary values, improved performance during development, and the ability to use utility variants like hover and focus without pre-configuring them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78045cb9-9179-40f1-a05b-b56e67fce685', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do generics improve code quality?', N'Junior', N'Generics allow you to write functions and data structures that can handle different types without duplicating code. This reduces redundancy and makes your codebase more maintainable and flexible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eed6e7d2-f390-48a3-a3c8-b56f35632ec8', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik achieve instant interactivity?', N'Intern', N'Qwik achieves instant interactivity by shipping almost zero JavaScript to the browser initially. It only downloads the specific code required for an event when the user clicks or interacts with an element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29a35057-65ce-44ed-8422-b5734743afe2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between the stack and the heap?', N'Intern', N'The stack is a region of memory used for static memory allocation and managing function calls, where memory is managed automatically. The heap is used for dynamic memory allocation, where the programmer must explicitly request and release memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bb49e97-3195-4455-a506-b5757bb1459f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What does ''AOT'' stand for in Micronaut?', N'Intern', N'AOT stands for Ahead-Of-Time. It refers to the process of performing framework configuration, bean initialization, and routing logic during the build phase rather than when the application starts running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ac18900-c9a8-4782-ad9f-b57647e0dc72', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is autovacuum in PostgreSQL?', N'Intern', N'Autovacuum is a background process that automatically cleans up dead rows and updates statistics for the query planner. It is essential for maintaining database performance over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'951c64a0-b126-4465-8c62-b576a738163a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ''section'' and ''div'' elements?', N'Junior', N'A section element is a semantic container for a thematic grouping of content. A div is a generic container used primarily for styling or layout purposes that carries no specific semantic meaning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5ff3ade-0175-45a1-a868-b57781eb50b2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''group'' utility in Tailwind?', N'Intern', N'The ''group'' utility allows you to style child elements based on the state of a parent element. By adding the ''group'' class to a parent, you can use ''group-hover:'' on a child to trigger styles when the parent is hovered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8813f329-ef39-4785-9cb3-b578b873270c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle image optimization?', N'Junior', N'Qwik includes a built-in Image component that automatically handles resizing, format conversion, and lazy loading. It ensures that images are optimized for the user''s device, contributing to faster page load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7faa0934-8a2f-4249-8376-b5796fde0b21', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What does the CAP theorem state regarding database scaling?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the event of a network partition, a system designer must choose between keeping the system available with potentially stale data or prioritizing consistency by rejecting writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bba914b-4e53-44d6-9091-b57ba820ec44', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS achieve reactivity without a Virtual DOM?', N'Senior', N'SolidJS uses fine-grained reactivity based on dependency tracking via signals. Instead of re-rendering components, it compiles JSX into direct DOM operations, updating only the specific nodes that depend on a changed signal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'077339d1-fd5d-4ceb-9a85-b57fecb5da57', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of field data, and why should ''fielddata'' be avoided on text fields?', N'Senior', N'Field data is an in-memory structure used for sorting and aggregations on analyzed string fields. Enabling it on text fields consumes massive amounts of JVM heap because it loads the entire field into memory as a list of terms, often leading to OutOfMemoryErrors; keyword fields should be used for these operations instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7f6ac11-669e-47d6-b84f-b580f1cc034e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to define a problem before attempting to find a solution?', N'Intern', N'Defining the problem ensures that the solution actually addresses the root cause rather than just the symptoms. Without a clear definition, you risk wasting time and resources on irrelevant fixes that do not achieve the desired result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f16fe6c-9bd0-4b7a-8045-b5827ff043d4', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'In what scenarios would you still consider using jQuery in a modern frontend stack?', N'Middle', N'jQuery might be used when maintaining legacy codebases, developing simple, non-reactive landing pages where overhead is minimal, or when specific, highly stable jQuery plugins are required that have no modern equivalents. However, for complex applications, it is generally discouraged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
