INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c06e934a-49a3-47a5-92b0-b585e4526184', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How would you handle database connection pooling in a standard Laravel environment to improve scalability?', N'Senior', N'Laravel''s default architecture does not natively support persistent connection pooling across HTTP requests, as each request terminates the connection. To scale, you should utilize an external proxy like PgBouncer or ProxySQL to maintain a pool of persistent connections between the application server and the database, reducing the latency associated with TCP handshakes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'923a0c22-cf0b-4966-9403-b58606585d4b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of the ''Serialization'' layer in Litestar?', N'Middle', N'The serialization layer handles the conversion of Python objects into responses, such as JSON or MessagePack. It allows for custom serialization logic, ensuring that complex types like datetimes or custom classes are formatted consistently across the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bd67f10-ed40-4638-a11e-b586827ef5e9', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the Qwik Optimizer during the build process?', N'Senior', N'The Qwik Optimizer is a build-time tool that automatically transforms source code by extracting component logic and event handlers into individual, lazy-loadable files. It performs static analysis to identify boundaries where code splitting can occur, ensuring the application maintains the smallest possible initial JavaScript footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d85a142-76a0-4aaa-a22c-b58aa440d4b1', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is a ''hook'' in Fastify?', N'Intern', N'A hook is a lifecycle event that allows developers to execute custom code at specific points during the request-response cycle, such as before a handler is called or after a response is sent. They are commonly used for tasks like authentication, logging, or data transformation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57f45ef6-5be0-4837-9739-b58af01aae7b', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you architect protection against SSRF in a cloud environment where services have access to metadata endpoints?', N'Senior', N'You should implement strict network-level egress filtering using security groups or firewalls to block traffic to internal metadata IP addresses. Additionally, application-level input validation using allow-lists for hostnames and enforcing proxy-based egress traffic control helps prevent malicious requests from reaching sensitive cloud infrastructure endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c449f9bd-6e8e-4ace-aecc-b5910f1f8409', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is it difficult to implement exactly-once delivery in distributed messaging systems?', N'Senior', N'Exactly-once delivery requires atomicity between the message processing and the state update of the consumer. If the consumer processes a message but crashes before committing the offset, the message will be reprocessed. Achieving true exactly-once requires distributed transactions or idempotent operations that can safely handle duplicate deliveries without side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
