INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1f824a4-0352-42b3-b996-b5970dc79de9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the benefit of Go''s strict import rules regarding unused imports?', N'Middle', N'By forcing developers to remove unused imports, the Go compiler keeps build times fast and dependencies clean. This prevents the binary from growing unnecessarily large and forces developers to maintain a clear and intentional dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1046281d-3f0c-41cf-89c8-b597c3dd2198', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .on() and .bind() in jQuery?', N'Fresher', N'.on() is the modern, preferred method for attaching event handlers because it supports delegated events and replaces older methods like .bind(). While .bind() still functions, it is considered deprecated in favor of the more versatile .on() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'419bdc69-dce3-4369-ac59-b59808dfc6a8', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle form validation and data binding?', N'Senior', N'Alpine uses the x-model directive for two-way data binding, which effectively syncs the DOM state with the JavaScript object. For validation, it relies on standard HTML5 validation attributes or custom logic attached to submit events, lacking a robust built-in validation engine compared to heavy frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e33d547-1521-4428-8a6d-b59f404e7bc1', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle concurrency, and what are the limitations of its built-in development server?', N'Middle', N'Flask''s built-in development server is designed solely for local development and is single-threaded or uses basic threading, which cannot handle high-concurrency production traffic. In production, you must use a production-grade WSGI server like Gunicorn or uWSGI, which manages multiple worker processes or threads to handle concurrent requests efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa52ef7b-6027-47c4-a93b-b5a1ced08c34', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does it mean for PostgreSQL to be an ACID-compliant database?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, meaning that if a series of operations fails, the database remains in a stable state without partial data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7577ee58-8c06-4c75-95cc-b5a28c077062', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is service discovery critical in a dynamic, horizontally scaled environment?', N'Middle', N'In a system where instances are frequently added or removed, service discovery allows components to locate each other automatically without hardcoded IP addresses. This enables seamless scaling and fault tolerance by ensuring that traffic is only routed to healthy, active service instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f12a23a0-f553-4698-8c74-b5a4f106fb65', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Describe an architectural approach to mitigating Distributed Denial of Service (DDoS) attacks.', N'Senior', N'Mitigation relies on a multi-layered approach including global edge caching, rate limiting at the API gateway, and utilizing cloud-native DDoS protection services that can absorb volumetric traffic at the network edge. These layers ensure that the core application infrastructure remains reachable even under high traffic volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41875e44-4713-45e1-b72c-b5a5eab375c9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a scenario where a database deadlock is occurring, but the deadlock logs are inconclusive?', N'Senior', N'I would enable granular database transaction tracing and analyze the query execution plans for long-running transactions that might be holding locks unnecessarily. I would also evaluate the application''s transaction isolation levels and concurrency control patterns to ensure that access patterns are consistent across services to prevent circular dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebc1c2c2-7d0f-4a91-bda4-b5a71dc55bee', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the difference between a ''Layer'' and a ''Service'' in the Tower/Axum architecture?', N'Middle', N'A Service is a component that processes a request and returns a response, while a Layer is a factory that produces a service. Layers are essentially wrappers that allow you to decorate or modify the behavior of a service before it is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd687e42-8564-47dc-b09a-b5a92ab8fc0d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is the API Gateway pattern preferred over direct service-to-service communication for external clients?', N'Senior', N'The API Gateway acts as a reverse proxy that abstracts internal architecture, handles cross-cutting concerns like authentication and rate limiting, and reduces the number of round-trips for the client by aggregating multiple service responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa578d47-4e2d-4932-b492-b5ab1e95c12e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is scope chain in javascript?', N'Intern', N'The scope chain is the mechanism JavaScript uses to resolve variable references by searching through nested scopes from innermost to outermost until the variable is found (or a ReferenceError is thrown). Example:: Note: * The chain is created at function definition time (lexical scoping), not at call time * It only goes outward — outer scopes cannot access inner variables * Closures work because inner functions retain a reference to their outer scope chain', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bd6dcb9-5883-4951-b040-b5ae24bc66c8', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of ''Voters'' in Symfony Security and how they differ from traditional role-based access control.', N'Senior', N'Voters provide a flexible, granular approach to authorization by allowing custom business logic to be evaluated for any resource. Unlike simple role-based checks, voters can inspect the state of an object and the current user''s attributes, making them ideal for complex permission schemes like ownership-based access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'901e3dfd-2859-4f19-a099-b5b116e790f0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of a type assertion?', N'Junior', N'A type assertion is a way to tell the compiler to treat a value as a specific type, overriding the inferred type. It is essentially a hint to the compiler that you know more about the data structure than it does.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'524a627c-2581-48c0-9489-b5b2e4e6f267', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is immutability considered a pillar of Scala''s concurrency model?', N'Senior', N'Immutability eliminates data races by definition, as state cannot change once an object is initialized. This enables thread safety without the heavy reliance on locks or synchronization primitives, leading to cleaner, more scalable concurrent designs that leverage parallel collection processing effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08e9e7c1-4ecb-49b5-a914-b5b2f0bc66d0', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the ''Memory Barrier'' concept in the context of C# volatile fields.', N'Senior', N'A memory barrier prevents the processor or compiler from reordering read and write operations across the boundary, ensuring memory visibility across threads. Using the volatile keyword ensures that the most up-to-date value is always read from main memory, preventing the use of stale cached values in multi-threaded scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f311dbe-968a-4b3a-9dd4-b5b67978859e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the impact of the ''synchronized'' keyword on application performance.', N'Middle', N'The synchronized keyword ensures mutual exclusion, which prevents race conditions but introduces performance overhead due to thread blocking and context switching. Excessive use of synchronization can lead to lock contention and thread starvation, reducing overall system throughput. Modern alternatives like concurrent collections or atomic variables are often preferred for higher scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fda6e71f-64ce-4ad7-9757-b5b8951e3020', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle garbage collection?', N'Intern', N'Ruby uses an automatic garbage collection system to manage memory. It periodically identifies and removes objects that are no longer referenced by the program, freeing up memory without requiring the developer to manually deallocate resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c2ee62c-1791-4cd7-97b0-b5bbe1b89fef', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of routing in a Flask application?', N'Junior', N'Routing maps specific URLs to Python functions known as view functions. When a user requests a URL, the Flask router determines which function should handle that request and return a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65bf5c2c-9959-4e73-a327-b5bc307b3fed', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle partial failures in an API gateway aggregation pattern?', N'Senior', N'Use a circuit breaker pattern to prevent cascading failures when a downstream service is unresponsive. The gateway should return a partial response with explicit error metadata for the failed segments, allowing the client to decide whether to ignore the missing data or retry the specific failed operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03dd3202-1b73-418a-a2c3-b5bde0660621', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is dependency injection crucial for maintaining a large-scale NestJS codebase?', N'Senior', N'Dependency injection manages the instantiation and lifecycle of objects, ensuring that components remain loosely coupled and easily swappable. This is critical in large systems where changing one component should not require refactoring dependent modules, significantly reducing the blast radius of code changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaf12349-4a4d-4519-b24d-b5be02f72d16', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a ''view function'' in Flask?', N'Fresher', N'A view function is a Python function that is decorated with a route and is responsible for processing a request and returning a response. The response can be an HTML string, a JSON object, or a rendered template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b8dc458-ed23-435c-b1be-b5bfaf831934', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of a Load Balancer, and how do different algorithms like Round Robin and Least Connections impact traffic?', N'Middle', N'A load balancer distributes incoming network traffic across multiple servers to ensure no single server bears too much load. Round Robin distributes requests sequentially, which is simple but ignores server load, while Least Connections directs traffic to the server with the fewest active sessions, leading to more efficient resource utilization in heterogeneous environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77ca6d12-b722-4813-a592-b5c0ff13f589', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the architectural risks of ''fat'' handlers in a Gin application?', N'Senior', N'Fat handlers lead to poor testability, code duplication, and violation of the Single Responsibility Principle. As the application grows, these handlers become difficult to maintain, so logic should be extracted into service layers that are agnostic of the HTTP framework, keeping the Gin handlers strictly for request orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4d65a25-b3b1-4fa1-bb30-b5c18de1c8bf', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite approach asset caching for production?', N'Middle', N'Vite appends content hashes to filenames by default. Because these filenames change whenever the content changes, you can safely set long-term cache headers on your static assets, ensuring browsers only download new versions when files are updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e3984d2-a3be-4f25-b81c-b5c2b60311dc', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the role of an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point that handles cross-cutting concerns like authentication, SSL termination, rate limiting, and request routing. It simplifies the client experience by aggregating multiple microservice calls into a single response and decoupling internal service topology from the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1b60029-a5e3-4221-99d9-b5c2e4df86c0', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve fast startup time?', N'Fresher', N'Unlike traditional frameworks that use runtime reflection to wire dependencies, Micronaut uses ahead-of-time (AOT) compilation. It processes dependency injection and configuration at compile-time, which significantly reduces startup overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f0dcf6d-5cef-441c-b5a4-b5c35ddb6962', N'4c000000-0000-0000-0000-000000000005', N'Why would you choose a NoSQL database over a relational database?', N'Middle', N'NoSQL databases are preferred when you need high write throughput, horizontal scalability, or when dealing with unstructured data that doesn''t fit a rigid schema. They offer flexibility in data modeling but often sacrifice strict ACID compliance for eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ecd6392-4403-4121-b943-b5c3c13e0fce', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of the ''pg_stat_statements'' extension?', N'Middle', N'This extension tracks execution statistics for all SQL statements executed by the server. It is an essential tool for performance tuning as it provides information on total execution time, call counts, and block read/write operations for every query, allowing developers to identify the most expensive queries in the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b1aacf5-be0f-4671-8832-b5c49304b20f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is a Gin context?', N'Intern', N'The context object is the primary interface in Gin that carries information throughout the request-response lifecycle. It provides methods for reading request parameters, sending responses, and controlling the flow of middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6d17c4e-42d9-40cd-be7c-b5c4c607041f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage the trade-off between perfection and delivery speed?', N'Fresher', N'I prioritize delivering a functional and stable solution that meets all core requirements on time. Perfection is often subjective and can lead to unnecessary delays, so I focus on ''good enough'' for the current phase while ensuring the solution is robust and extensible. I aim to deliver value incrementally rather than waiting for a perfect result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e42c247-94bf-46ee-8184-b5c4da53e1ba', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are HTTP methods and why are they important?', N'Intern', N'HTTP methods, such as GET, POST, PUT, and DELETE, define the type of action a client wants to perform on a resource. They are fundamental to RESTful design, helping the server understand whether to retrieve, create, update, or remove data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9685cef-5711-45c8-9f96-b5c52d55870c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the ''time to recover'' (MTTR) for a catastrophic failure in a complex microservices architecture?', N'Senior', N'I analyze the dependencies of each service and the automation levels for deployment and rollback, using past incident data to estimate the mean time for detection, triage, and resolution. By identifying the critical paths that lack automated recovery, I can provide a realistic MTTR estimate and suggest targeted investments in observability and resilience engineering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0d65a80-2888-467f-9bc5-b5c603ac2600', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What happens if you don''t use a client directive on an interactive component?', N'Junior', N'If you don''t use a client directive, the component will be rendered as static HTML on the server. The interactive functionality, such as event listeners or state management, will not work in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5767699f-2a83-4aa5-be3a-b5c7e162aa6e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the C# Garbage Collector handle objects in the Large Object Heap (LOH) differently than the small object heap?', N'Senior', N'The LOH is typically not compacted to avoid the high performance cost of moving very large memory blocks. Consequently, the LOH is prone to fragmentation, which can lead to OutOfMemoryExceptions even when total free memory appears sufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a692fcdc-7ddb-4c3e-931c-b5c851505662', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does the Spring Boot Actuator health endpoint contribute to microservices reliability?', N'Senior', N'Actuator provides a standardized way to expose internal state, such as database connectivity, disk space, and custom component status. In a distributed system, orchestrators like Kubernetes use these endpoints for liveness and readiness probes to manage traffic routing and automated self-healing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d641395-79a5-49ba-9e4d-b5cc9ce3f550', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between ''hot module replacement'' (HMR) and ''live reloading''?', N'Senior', N'Live reloading performs a full page refresh when files change, losing current application state. HMR updates modules in-place within the running application without a full reload, allowing the state to persist during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'609cf4b6-7dd9-40c0-9c40-b5cd5c21701b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a query parameter in a web request?', N'Intern', N'A query parameter is a key-value pair appended to the end of a URL after a question mark. Fiber provides convenient methods to extract these values from the request context to filter or sort data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'268655cf-caf7-4274-96ce-b5ced3d95a06', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte''s ''slots'' enable better component composition?', N'Middle', N'Slots allow developers to pass content into a component, making components highly flexible and reusable. This composition pattern avoids the need for passing deep component structures as props and allows for cleaner separation of layout and content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'009bb754-5899-49ec-9587-b5cf0525b9c0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the significance of the ''q:id'' attribute in Qwik?', N'Fresher', N'The ''q:id'' attribute is used to uniquely identify elements in the DOM that are associated with specific state or event listeners. It acts as a bridge, allowing Qwik to reconnect DOM elements to their corresponding JavaScript logic after the page has loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6719122f-884d-4553-b7ad-b5d1ad1cf5ed', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis differ from a traditional Relational Database Management System (RDBMS)?', N'Fresher', N'Traditional RDBMS are disk-based and use tables with strict schemas to store data, prioritizing complex relationships and ACID compliance. Redis is a NoSQL, key-value store that prioritizes speed and simplicity, using flexible data structures without a rigid schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c512e45b-e99f-4303-8672-b5d7d055b08a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between routing by convention and attribute routing?', N'Junior', N'Convention-based routing defines global URL patterns in a central location, typically mapping URLs to controller and action names. Attribute routing allows developers to define routes directly on controller actions using decorators, providing more granular control over specific endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
