INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee804b5c-e1e1-4ba7-98a2-b5de72d41982', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you handle timeouts in a Gin application?', N'Middle', N'Timeouts should be handled by setting a timeout on the underlying http.Server instance or by using a middleware that utilizes context.WithTimeout. This ensures that long-running requests do not block server resources indefinitely and lead to cascading failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
