INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a72586b-eebf-4c9e-8f3b-b5ed1e0e64c1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the trade-offs of using Server-Side Rendering (SSR) versus Static Site Generation (SSG) in a large-scale enterprise application.', N'Senior', N'SSR provides dynamic, per-request content rendering, which is ideal for personalized data but increases server load and time-to-first-byte latency. SSG offers superior performance and scalability through pre-rendering at build time, but it is less practical for highly dynamic data that changes frequently across user sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd788c1a-ad58-484f-af9d-b5eece41deaf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the value of automated testing in the development lifecycle?', N'Intern', N'Automated testing provides a safety net that detects bugs early and ensures that new changes do not break existing functionality. It significantly increases development confidence and speed, as manual regression testing becomes unnecessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
