INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee90c25-ebc5-4a2e-b57f-b60545bd82a0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the benefit of Tailwind''s JIT (Just-In-Time) compiler compared to the previous pre-compiled approach?', N'Middle', N'The JIT compiler generates CSS on-demand as you author your HTML, which removes the need for PurgeCSS and eliminates the performance bottleneck of processing large CSS files. This allows for arbitrary values, such as specific pixel spacing not in the theme, without needing to pre-configure every possible variant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'273c5f99-cdfc-486e-a7e2-b607a77d1025', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the ''Cache Stampede'' or ''Thundering Herd'' problem?', N'Middle', N'This occurs when a highly requested cache key expires, causing multiple concurrent requests to miss the cache and overwhelm the database simultaneously. It can be mitigated by using mutex locks to ensure only one request repopulates the cache or by implementing probabilistic early expiration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df3079e9-438b-416c-b7f5-b60b743687d5', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When is it appropriate to use an API Gateway versus an API Orchestrator?', N'Senior', N'An API Gateway acts as a centralized entry point for authentication, rate limiting, and request routing across all services. An Orchestrator is a higher-level service that coordinates multiple microservices to fulfill a complex business request, often managing transactional state and workflow logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aee70826-03c7-4fc6-8840-b60dd9b35e58', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Under what conditions would a full table scan outperform an index range scan?', N'Senior', N'A full table scan is often faster when the requested data represents a large percentage of the table, as sequential disk I/O is much faster than the random I/O required to navigate an index tree for many rows. The optimizer usually switches to a table scan if the selectivity of the filter is low.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f75ca63b-f406-4c62-bcac-b60e2cb9c85b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a situation where a service is experiencing increased latency due to a downstream dependency bottleneck?', N'Middle', N'I would implement a circuit breaker pattern to prevent cascading failures and provide a fallback response. Additionally, I would introduce asynchronous processing or caching mechanisms to reduce the load on the downstream service while monitoring the health of the dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ab44bab-1677-4817-9eb9-b610ccb0baf6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the @Inject annotation?', N'Intern', N'The @Inject annotation is used to mark a constructor, field, or method where the dependency injection container should provide a bean instance. It tells Micronaut that the class requires this dependency to function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'467aa901-02cb-4e23-9dd5-b61180711dd5', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s method lookup path work when using mixins?', N'Middle', N'When a module is included, it is inserted into the inheritance chain immediately after the class itself. Ruby searches for methods in the class, then the included modules in reverse order of inclusion, and finally the superclass, ensuring that mixins can override or extend existing behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f4b2eb5-c28a-475f-8a07-b6122b7108cc', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How can Chi be extended to support custom request observability without modifying core logic?', N'Senior', N'Chi allows for the injection of custom middleware at any point in the request lifecycle, which is ideal for implementing distributed tracing, logging, and metrics collection. By wrapping the handler, you can capture telemetry data, request headers, and response status codes before passing the request down the chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83f98584-bf74-41df-bc99-b612af57a550', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ARC and how it manages memory.', N'Middle', N'Automatic Reference Counting tracks the number of strong references to an instance. When the reference count drops to zero, the instance is deallocated. It automates memory management but requires developers to handle reference cycles manually using weak or unowned keywords.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0da99b72-d12f-4b3e-acf6-b61443761cde', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What does DOM stand for and how does jQuery interact with it?', N'Fresher', N'DOM stands for Document Object Model, which is the programming interface for web documents. jQuery interacts with the DOM by providing simple methods to select elements, change their content, modify their CSS styles, and respond to user events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f6a1f3e-8373-474b-8cf8-b61452b958ed', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between microtasks and macrotasks, and why does it matter?', N'Fresher', N'The distinction between microtasks and macrotasks determines when callbacks run relative to each other and to rendering. Getting this wrong causes subtle ordering bugs, laggy UIs, and starvation scenarios. Microtask sources: - Promise.then() / .catch() / .finally() - async/await continuations (desugars to .then()) - queueMicrotask() - MutationObserver callbacks Macrotask sources: - setTimeout / setInterval - setImmediate (Node.js only) - I/O callbacks (Node.js) - UI event callbacks (click, input, etc.) - MessageChannel.postMessage() - requestAnimationFrame (browser — runs before paint, after microtasks) Critical difference: After each macrotask, the entire microtask queue is drained before the next macrotask or render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48f985d6-de3e-4866-a986-b6168cf76873', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How can you leverage Flask''s URL converters to clean up route-level validation logic?', N'Senior', N'Custom URL converters allow you to move validation and object lookup logic out of the view function and into the routing layer. This keeps the view function focused on business logic and ensures that if a URL parameter doesn''t match the required format or existence check, the application automatically returns a 404 error before the view code even runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec9da3cf-ec13-47ff-abbe-b61be76e6ff6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are NA and NULL in R?', N'Fresher', N'NA represents a missing value or ''not available'' in a dataset, which is a placeholder for data that is absent. NULL represents an object that is empty or does not exist, often used to indicate the absence of a value or an undefined object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0652958-04ec-4186-b6b6-b61c3cb1dbc6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the trade-offs of using ''prerendering'' for a SvelteKit route?', N'Middle', N'Prerendering generates static HTML at build time, which results in extremely fast load times and excellent SEO performance. However, it is not suitable for pages with highly dynamic, user-specific data that must be fetched at request time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b026e298-cd71-4895-9a21-b61d7c7a7543', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a materialized view and a standard view?', N'Middle', N'A standard view is a virtual table that executes a stored query every time it is accessed. A materialized view stores the result set physically on disk, offering much faster read performance at the cost of needing explicit refreshes to update the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c61d503-d445-4375-96e8-b61e7432064e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Explain the concept of database replication and its primary benefits.', N'Middle', N'Database replication is the process of copying data from one database server to one or more other servers. It improves read scalability by offloading read queries to replicas and increases fault tolerance by providing redundant data copies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f73fadc-d252-4980-9651-b6206d7a7601', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of ''keep-alive''?', N'Middle', N'keep-alive caches inactive component instances rather than destroying them when they are switched out. This preserves the component state and avoids expensive re-rendering when the user navigates back to the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'629419f8-b86d-4198-902e-b6211849aee5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does denormalization work in NoSQL?', N'Junior', N'Denormalization involves storing related data together in a single document or record instead of splitting it across multiple tables. This reduces the need for complex joins, which are expensive and difficult to perform in distributed NoSQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef258af-d79f-44fe-9b69-b623b423aefd', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Does Rocket support HTTPS?', N'Intern', N'Yes, Rocket supports TLS (Transport Layer Security) for HTTPS. It can be configured to use SSL certificates to encrypt traffic between the client and the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98408328-f148-44c3-8997-b6262acabb33', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the impact of Echo''s middleware ordering?', N'Middle', N'Middleware in Echo is executed in the order it is registered. Placing authentication middleware before logging, for example, might result in unauthenticated requests not being logged, so careful ordering is required to ensure proper request flow and security coverage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'044a8b66-5aa6-44c4-8d04-b626a1780a76', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of the ''web::Json'' extractor?', N'Intern', N'The ''web::Json'' extractor is used to automatically parse the request body as JSON. It validates the content type and transforms the payload into a Rust type that implements the necessary trait.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9a52af6-5ad7-4f87-99fe-b6270d7f64e0', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''when'' expression used for?', N'Fresher', N'The ''when'' expression is a versatile replacement for the traditional switch statement found in other languages. It can match values, ranges, or types and can be used as either a statement or an expression that returns a value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8952ce8e-103f-431e-af5a-b627980f69f4', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the concept of Sharding in MongoDB and when it should be implemented.', N'Middle', N'Sharding is the process of partitioning data across multiple servers to support deployments with very large datasets and high throughput. It should be implemented when the dataset exceeds the storage capacity of a single server or when the read/write load surpasses the capabilities of a single primary node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e35027b9-4af9-4e8a-8f39-b62802e76b21', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it generally not recommended to perform joins in Elasticsearch?', N'Junior', N'Elasticsearch is a distributed search engine designed for speed, and performing relational-style joins across shards is extremely resource-intensive. It is recommended to denormalize your data, meaning you should store related information within a single document whenever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'769803d9-d1e3-43e8-9674-b62856088933', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between InnoDB and MyISAM in MySQL?', N'Intern', N'InnoDB is the default storage engine that supports ACID compliance, row-level locking, and foreign key constraints, making it ideal for transactional data. MyISAM is an older engine that supports table-level locking and is generally faster for read-heavy operations but lacks support for transactions and data integrity features like foreign keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9135e32d-6dbb-41fd-9641-b62a7c45d957', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Symfony Routing component?', N'Intern', N'The routing component maps HTTP requests to specific controller actions based on URL patterns. It allows developers to define clean, readable URLs and link them to the logic that should handle the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a01f1da-1a7b-430b-aeab-b62bf0b09edd', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How can you architect a system to ensure data privacy in a multi-tenant environment?', N'Senior', N'Architectural isolation can be achieved through logical separation using tenant IDs in every database query or physical separation using distinct database instances or schemas per tenant. Implementing Row-Level Security at the database tier provides a final enforcement layer to prevent cross-tenant data leakage even if application-level logic fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21a46592-1f83-4e22-afbf-b62f2e1fb6a0', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the role of namespaces in the R package system regarding dependency management.', N'Senior', N'Namespaces provide an isolated environment for package functions, controlling visibility and preventing symbol conflicts between packages. By explicitly importing necessary symbols and exporting only a defined interface, namespaces ensure that a package''s internal logic remains shielded from the global workspace and other loaded packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a09da18-a7a3-4ef9-9a05-b62f9b87ef5e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is NoSQL considered suitable for big data?', N'Fresher', N'NoSQL is suitable for big data because it is designed to be distributed across many servers, allowing it to handle massive amounts of data that would be difficult to manage in a single relational instance. Its flexible schema also makes it easy to ingest and store diverse types of incoming data without pre-processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fabbe06-435c-47b0-b30b-b630725d2188', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass parent selectors specifically useful for?', N'Junior', N'They are essential for handling state-based styling, such as targeting the active or focused state of an element. Using the ampersand keeps the related states grouped together under the base selector, improving readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'480cb6ac-5196-425e-9f06-b632685f175d', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the significance of the Vector Clock mechanism in distributed systems.', N'Senior', N'Vector clocks are used to track causality between events in a distributed system where physical clocks cannot be perfectly synchronized. By maintaining a vector of counters for each node, the system can determine if two operations are causally related or concurrent, facilitating conflict resolution in eventually consistent databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15c4c3c2-b273-470d-a967-b6326c427fb5', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the Quarkus Dev UI, and how do you access it?', N'Junior', N'The Dev UI is a browser-based dashboard that provides insights into the running application, including installed extensions, configuration properties, and database connections. It is typically accessed by navigating to the /q/dev endpoint while the application is running in development mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
