INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd65af656-09b8-49f0-ae03-b640cb31ccdc', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s filesystem-based routing determine the hierarchy of a page?', N'Middle', N'The routing is determined by the directory structure within the ''src/routes'' folder, where each folder represents a URL path segment. The hierarchy ensures that layouts defined in parent folders are automatically inherited by nested routes, creating a predictable structure for UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad81e548-f487-4bdf-8df9-b6444be6157b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are smart casts in Kotlin?', N'Intern', N'Smart casts are a compiler feature that automatically performs type casting after a type check is performed. Once an object is verified to be of a certain type, the compiler treats it as that type, removing the need for manual casting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21147d78-ea8f-465e-ac19-b647bf8d5dae', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .hide() and .fadeOut()?', N'Fresher', N'The .hide() method immediately removes an element from view by setting its display property to none. The .fadeOut() method creates an animation that gradually decreases the opacity of an element before hiding it, providing a smoother visual transition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fad38903-8ea1-441d-9357-b648c97387e9', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS depend on JavaScript at runtime?', N'Fresher', N'No, Tailwind CSS does not require JavaScript at runtime. It is a CSS-only framework that generates static stylesheets during the build process, ensuring that there is no performance overhead when the page is loaded by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43a2b1cf-c015-4ac7-916e-b649b8ad79f4', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the architectural implications of the ''everything is middleware'' design in Express.', N'Senior', N'This design promotes high modularity and ease of extensibility but lacks a strict structure for dependency injection and state management. Without disciplined architectural patterns, this often leads to monolithic, tightly coupled codebases that are difficult to unit test and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81673b46-48ac-4353-8253-b649f7f61373', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you get enumerable key and value pairs', N'Fresher', N'The Object.entries() method is used to return an array of a given object''s own enumerable string-keyed property [key, value] pairs, in the same order as that provided by a for...in loop. Let''s see the functionality of object.entries() method in an example, Note: The order is not guaranteed as object defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20bb15f2-9069-45fa-9e06-b64c28f56b21', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a distributed system, how do you decide between eventual consistency and strong consistency?', N'Senior', N'The decision hinges on the business requirements for data accuracy versus system availability. Strong consistency is necessary for financial or critical state systems where correctness is paramount, whereas eventual consistency is preferred for high-availability, low-latency systems where temporary staleness is an acceptable trade-off for better performance and partition tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'152453a2-7d26-4df4-a868-b64c7e0d5608', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik considered ''O(1)'' in terms of loading?', N'Intern', N'Qwik is considered O(1) because the initial load time is independent of the size of the application. Whether the app has one component or a thousand, the initial download and execution remain minimal because only the essential bootstrap code is loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf296170-2f58-47f5-a751-b64d01d3962e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are +page.svelte files?', N'Intern', N'These files are the standard components used to define the user interface for a specific route. When a user navigates to a URL corresponding to the file path, the contents of the +page.svelte file are rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
