INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'812f71c9-4382-415e-89d8-b6523aaed742', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does indexing strategy change when moving from a monolithic to a distributed database?', N'Senior', N'In a distributed database, global indices become difficult to manage because they require cross-shard communication to maintain. Architects often rely on local indices within each shard or denormalize data to create dedicated index tables to avoid the performance penalties of distributed index lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
