INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12f6ab48-842f-4a8b-9853-b65d1445cf08', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s type-safe request routing affect application scalability?', N'Senior', N'Rocket''s routing is evaluated at compile-time rather than runtime, which eliminates the overhead of dynamic dispatch and regex pattern matching during request handling. This allows the framework to achieve extremely high throughput and low latency, as the request dispatching logic is baked into the binary''s machine code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
