INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c106502-8337-4f0b-bc16-b66c8866648b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the primary purpose of a constructor in C++?', N'Intern', N'A constructor is a special member function that is automatically called when an object of a class is created. Its main purpose is to initialize the member variables of the object to a valid state. Constructors ensure that an object is ready for use as soon as it is instantiated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'658b5cdf-12db-49af-af63-b66dea0a2433', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why might a senior engineer choose to replace Gin''s default JSON renderer in a high-throughput microservice?', N'Senior', N'The default encoding/json package uses reflection to marshal and unmarshal data, which is computationally expensive. Replacing it with code-generation-based libraries like easyjson or segmentio/encoding/json can significantly reduce CPU utilization and latency in systems where JSON serialization is the primary bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'546dd048-053d-4260-8113-b6709d857c21', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are guards in the context of NestJS?', N'Intern', N'Guards are functions that have a single responsibility. They determine whether a given request will be handled by the route handler or not, depending on certain conditions (like permissions, roles, ACLs, etc.) present at run-time. For example, you might use a guard to check if a user is logged in before allowing them to access a route. A guard is a class annotated with the @Injectable() decorator, which implements the CanActivate interface. This interface should return a boolean or a Promise that resolves to a boolean. If it returns true, the request proceeds to the route handler. If it returns false, the request is denied and the route handler is not executed. Here''s an example of a basic guard: In this example, AuthGuard allows all requests to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ca8340d-8b68-40cf-b240-b677a583dafe', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the role of the ''Preload'' feature in Lucid ORM and how it affects query performance.', N'Senior', N'Preloading allows for efficient eager loading of relationships to solve the N+1 query problem by executing a separate query with an IN clause. While this drastically improves performance for related data, improper use can lead to large memory consumption if too many records are loaded into memory at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d2409ed-5873-4539-8584-b6795bb89267', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is generator in JS?', N'Intern', N'Generator-Function: A generator-function is defined like a normal function, but whenever it needs to generate a value, it does so with the yield keyword rather than return. The yield statement suspends function''s execution and sends a value back to caller, but retains enough state to enable function to resume where it is left off. When resumed, the function continues execution immediately after the last yield run. Syntax: Generator-Object: Generator functions return a generator object. Generator objects are used either by calling the next method on the generator object or using the generator object in a "for in" loop. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'101d75e6-43b6-476c-b358-b67ac1f6a220', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are ''Implicit Conversions'' and why should they be used sparingly?', N'Middle', N'Implicit conversions allow the compiler to automatically convert one type to another to satisfy a type mismatch. They should be used sparingly because they can make code difficult to read and debug, as the logic flow is no longer explicit to the reader.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e21ff26f-6e60-48fc-8a37-b67b032a12d1', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the purpose of the Chi ''middleware.Recoverer''.', N'Middle', N'The Recoverer middleware catches panics that occur during the request lifecycle. It prevents the entire server from crashing and logs the stack trace, allowing the server to return a 500 internal server error instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0572e8aa-ed2a-48e2-be53-b67ddd0dc0c3', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is method lookup in Ruby?', N'Intern', N'Method lookup is the process Ruby uses to find which definition of a method to execute when a message is sent to an object. The interpreter searches the object''s class, then its superclasses, and finally included modules until the method is found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf024701-c311-4dbf-b194-b67e2c2325f3', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle JSON data?', N'Intern', N'Rocket provides built-in support for JSON through the Serde library, which handles the serialization and deserialization of data. You can specify a type in the handler, and Rocket will automatically attempt to parse the incoming JSON body into that structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91903ffd-87ec-419b-8b24-b67e488ac6a5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to design for observability from the start?', N'Intern', N'Observability ensures you have sufficient logs, metrics, and traces to understand the state of the system in production. Without it, debugging performance issues or outages becomes extremely difficult because you lack visibility into how the system is behaving.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddd115ac-9c11-44e5-b16e-b67f01d66cd5', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s testing client differ from performing actual HTTP requests against a running server?', N'Senior', N'The test client triggers the Flask application directly through the WSGI interface without going through a network stack or an HTTP server. This makes tests significantly faster and allows for easier introspection of the request/response context, though it may miss issues related to network configuration, timeouts, or proxy interference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a242e47-2d64-4c27-8404-b67fe1216389', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''dynamic'' keyword?', N'Intern', N'The dynamic keyword disables static type checking for a variable, essentially telling the compiler to postpone type verification until runtime. It is useful when the type of a value is not known at compile time, but it should be used sparingly to avoid runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dcae20e-013e-4084-85f8-b681db2b7d13', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of migrations in Rails?', N'Junior', N'Migrations are a feature of Active Record that allows you to evolve your database schema over time. They provide a version-controlled way to create, modify, or delete database tables and columns using Ruby code instead of SQL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5e7f5a6-350b-4012-b391-b68204e3b9b7', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the difference between ''satisfies'' and explicit type annotations.', N'Senior', N'The satisfies operator checks that a value matches a type without changing the inferred type of the value itself, preserving specific literal types. Explicit annotations, by contrast, force the value to conform to the type, often losing specific information about the exact properties assigned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4264aa94-c06f-4722-ac0c-b6884f42e0bf', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar support WebSockets compared to standard REST endpoints?', N'Senior', N'Litestar treats WebSockets as first-class citizens with distinct handler types that maintain the same dependency injection and validation benefits as REST endpoints. It provides a structured way to manage WebSocket lifecycle events, simplifying the management of long-lived connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9421a79f-149b-4c5e-bf51-b6892e05f7ce', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is Error Handling in Node.js?', N'Intern', N'An error is any problem given out by the program due to a number of factors such as logic, syntax, timeout, etc. An error in Node.js is any instance of the Error object. Common examples include built-in error classes, such as ReferenceError, RangeError, TypeError, URIError, EvalError, and SyntaxError. User-defined errors can also be created by extending the base Error object, a built-in error class, or another custom error. In general, Node.js errors are divided into two distinct categories: operational errors and programmer errors. 1. Operational Errors: Operational errors represent runtime problems. These errors are expected in the Node.js runtime and should be dealt with in a proper way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66d86bdf-d97b-4201-8c12-b68c0a029df1', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the concept of ''tail recursion'' in Kotlin.', N'Middle', N'Tail recursion is a technique where a function calls itself as its last action. By using the ''tailrec'' modifier, the compiler optimizes the recursion into a loop, preventing stack overflow errors and improving performance for recursive algorithms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01fb4951-5fc4-4c95-95bf-b68fe1f40297', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is a Content Collection in Astro?', N'Intern', N'Content Collections are a feature used to organize and validate your local content files like Markdown or MDX. They provide type-safe access to your content, ensuring data is structured consistently across the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b5e85a9-c3b5-4ece-9c94-b6909e954deb', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the trade-offs of using Vite''s glob import feature compared to standard static imports?', N'Senior', N'Glob imports allow dynamic file loading based on patterns, which is useful for plugin systems or automated routing. However, it can lead to larger bundle sizes if not managed carefully, as it may include unintended files in the production chunk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'522bb722-b819-4e96-b5ea-b691faf2a50d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the purpose of a ''PhantomData'' type?', N'Middle', N'PhantomData is used to inform the compiler that a struct ''owns'' data of a certain type, even if that type does not appear in the struct''s fields. It is essential for correctly managing drop check requirements and variance for complex, generic data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39339344-4031-43d6-8df9-b697081c9fe4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is web speech API', N'Intern', N'Web speech API is used to enable modern browsers recognize and synthesize speech(i.e, voice data into web apps). This API was introduced by W3C Community in the year 2012. It has two main parts: 1. SpeechRecognition (Asynchronous Speech Recognition or Speech-to-Text): It provides the ability to recognize voice context from an audio input and respond accordingly. This is accessed by the SpeechRecognition interface. The example below shows how to use this API to get text from speech, In this API, browser is going to ask you for permission to use your microphone 2. SpeechSynthesis (Text-to-Speech): It provides the ability to recognize voice context from an audio input and respond. This is accessed by the SpeechSynthesis interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dd12804-2b7c-4da6-ac7d-b69921281dd4', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How microservices communicate with each other?', N'Fresher', N'Microservices are an architectural style and comprises of small modules/elements which are independent of each other. At times they are interdependent on other microservices or even a database. Breaking down applications into smaller elements brings scalability and efficiency to the structure. The microservices are distributed and communicate with each other by inter-service communication on network level. Each microservice has its own instance and process. Therefore, services must interact using an inter-service communication protocols like HTTP, gRPC or message brokers AMQP protocol. Client and services communicate with each other with many different types of communication. Mainly, those types of communications can be classified in two axes. 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f6ddc3a-be5e-496a-b603-b699b8008aa4', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of ''markRaw'' and when should it be used in a reactive state?', N'Senior', N'MarkRaw tells the reactivity system to skip an object, ensuring it is never converted to a proxy. This is essential for performance when storing instances of non-reactive classes, heavy objects, or third-party libraries that should not be observed, preventing unnecessary tracking overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05b70ec5-6ac3-463b-b552-b699ef8a883c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a ''Unit test'' and an ''Integration test'' in the context of Rails?', N'Middle', N'Unit tests focus on verifying the behavior of a single class or method in isolation, typically testing model logic or utility functions. Integration tests verify how different parts of the application, such as controllers, views, and models, work together to process a full HTTP request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f22b717-719b-445e-8c57-b69ae2ca54df', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ''Environment'' abstraction simplify multi-stage deployments in ASP.NET Core?', N'Senior', N'The environment abstraction allows for environment-specific configurations, such as connection strings or feature flags, to be loaded automatically based on the ''ASPNETCORE_ENVIRONMENT'' variable. This eliminates hardcoded environment logic and ensures that the application behaves predictably across development, staging, and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8db9db2-47e1-4a92-b480-b6a0cef85f6e', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'When should you use a buffer versus a string in Node.js?', N'Middle', N'Strings are used for text data and are optimized for UTF-8 encoding. Buffers are used for raw binary data, such as images, cryptographic keys, or network packets, providing a more efficient way to handle non-textual data at the memory level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86829f11-81e9-4450-a722-b6a130848d8e', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the main advantage of using a Content Security Policy (CSP)?', N'Middle', N'CSP is an HTTP header that allows site administrators to restrict the resources, such as scripts or images, that a user agent is allowed to load for a given page. It acts as a powerful defense-in-depth mechanism to mitigate the risk of cross-site scripting and data injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eeeb5f3-563a-4bad-a2ac-b6a2924eb379', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus ensure compatibility with existing Java libraries?', N'Senior', N'Quarkus uses a library of extensions that act as compatibility layers. These extensions provide the necessary GraalVM configuration files and build-time logic to ensure that libraries using reflection or dynamic class loading can function correctly when compiled to native code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f8da86f-0669-4f34-84f8-b6a7919387d1', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the architectural trade-offs of Remix''s ''Actions'' compared to traditional REST API endpoints.', N'Senior', N'Remix Actions centralize state mutation logic within the route module, tightly coupling the UI to the data modification process. This reduces the need for complex global state management and separate API services, though it can lead to larger file sizes if not modularized correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'222163d1-8dbe-4396-b6ec-b6a90c1fe4f7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS ''Logger'' differ from standard console logging?', N'Middle', N'The AdonisJS logger is a structured, production-ready implementation that supports multiple transports, such as files or external services. It includes features like log level management, request ID tracking, and serializable metadata, which are essential for debugging complex distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49a9e6ae-5395-45f5-90cf-b6aa1f25f2f1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the difference between copy-on-modify and pass-by-reference in R.', N'Middle', N'R primarily uses copy-on-modify semantics, meaning that when you modify an object, R creates a copy in memory to preserve functional purity. While R is generally pass-by-value, environments and external pointers behave as pass-by-reference, allowing for mutable state without triggering copies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4fed0e0-7097-4ce9-a2dd-b6aa3f8d88a1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a strongly consistent read?', N'Intern', N'A strongly consistent read returns a response that reflects all successful writes that occurred prior to the read. This ensures you always get the most up-to-date data, though it may have higher latency and consume more capacity than eventually consistent reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fe114ff-8fcb-4e6b-8030-b6abb849fc9f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the ''Request'' object in Laravel''s lifecycle?', N'Senior', N'The Request object encapsulates all data from the incoming HTTP request, including headers, cookies, and input parameters. It acts as a single point of truth that middleware and controllers use to evaluate the state of the request, facilitating cleaner controller logic and improved security through request validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26d2edca-836b-4ea6-b22c-b6ae9530b522', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi often preferred over heavier frameworks like Gin or Echo in a senior engineering context?', N'Senior', N'Chi is preferred for its strict adherence to the net/http standard library, which avoids framework lock-in and ''magic'' behavior. It provides essential routing and middleware features without enforcing a specific architectural paradigm, giving senior engineers the flexibility to design systems that align with specific business requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
