INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'365e3cbc-559d-44ac-8aaf-b6c23c5faf56', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''contenthash'' in Webpack output filenames?', N'Middle', N'The contenthash is a unique string generated based on the file''s content. It is used to ensure effective browser caching, as the filename will only change when the content of the file changes, forcing the browser to fetch the new version while keeping unchanged files cached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2501ae4e-31cc-4d80-833d-b6c642b4d741', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you handle a situation where two users try to update the same record at the same time?', N'Fresher', N'I would implement a locking mechanism or use optimistic concurrency control. Optimistic concurrency checks if the record has changed since it was last read; if it has, the system denies the second update and prompts the user to refresh, preventing data conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0eea8bcc-406f-4ca5-9a58-b6cc840374a2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is it recommended to use Immutable objects in multi-threaded environments?', N'Middle', N'Immutable objects are inherently thread-safe because their state cannot be changed after instantiation. Since no thread can modify the object, there is no need for synchronization or locks when sharing them across threads. This simplifies design, eliminates data races, and improves performance by reducing contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22f478ad-a3e2-480c-8c35-b6ce35bdf440', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the benefit of using Gin over the standard library ''net/http''?', N'Intern', N'Gin offers a more developer-friendly API with built-in features like middleware support, improved routing performance, and easy JSON binding. It reduces the amount of boilerplate code required to set up a robust web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df1240a5-d3c7-451b-8a18-b6cece2b6a88', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do global secondary indexes impact write performance in a sharded database?', N'Senior', N'Global secondary indexes require a write to be propagated across multiple shards to update the index entries, increasing write latency and complexity. It transforms a local write into a distributed transaction or an asynchronous background update, which can lead to eventual consistency issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cfd07fa-e0da-420e-b91c-b6cf698e02c5', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch''s ''dfs_query_then_fetch'' search type differ from ''query_then_fetch''?', N'Senior', N'Query_then_fetch executes the search locally on each shard and merges results, which can lead to inaccurate scoring if document frequencies vary significantly across shards. Dfs_query_then_fetch adds an initial phase to calculate global term frequencies, ensuring more accurate document relevance scoring at the cost of an extra network round trip.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48cc6366-250c-4d04-b579-b6cff52672f7', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the role of the ''requestUpdate'' method in Lit''s internal update cycle.', N'Senior', N'requestUpdate is an asynchronous scheduling mechanism that batches DOM updates to happen at the next microtask. By coalescing multiple property changes into a single update cycle, it prevents unnecessary layout thrashing and optimizes performance for complex component trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed932187-8649-432a-a436-b6d0457f5ace', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the impact of excessive indexing on write performance?', N'Middle', N'Every index must be updated whenever an INSERT, UPDATE, or DELETE operation occurs on the table. Too many indexes increase the overhead of write operations and consume additional disk space and memory in the buffer pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc0b21d5-44b1-44ad-963b-b6d7204280c1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between blocking and non-blocking code?', N'Intern', N'Blocking code stops the execution of further instructions until the current operation finishes, such as reading a large file. Non-blocking code allows the program to continue executing other tasks while waiting for an operation like a database query to complete in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9bff154-9b2c-484f-b3f8-b6d7fbcb1b30', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the benefits of using a message header for metadata?', N'Middle', N'Headers allow you to attach context such as trace IDs, timestamps, or content types to a message without modifying the core payload. This metadata is useful for logging, monitoring, and routing decisions in complex middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4ecf206-8c72-4837-bf6f-b6d8ab368eb3', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How can you share a database connection in Fastify?', N'Intern', N'You can share a database connection by registering it as a decorator on the Fastify instance. This makes the connection available to any plugin or route that shares that instance''s scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'380214d7-789c-44ee-90c2-b6d9e655299b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Is Fiber suitable for small-scale applications?', N'Junior', N'Yes, Fiber is suitable for applications of any size. While it is famous for high performance, it also provides a clean and productive developer experience that helps teams build and maintain web services quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'514b8b11-20e5-40e4-a9c1-b6dbee2ae64b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ''referential integrity'' mean?', N'Junior', N'Referential integrity is a rule that ensures relationships between tables remain consistent. It dictates that a foreign key value must always reference a valid primary key in the related table, preventing orphaned records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d943a2f-0d2c-4ab2-9ae4-b6dc8c389f76', N'4c000000-0000-0000-0000-000000000005', N'What is the role of a service mesh in a large-scale microservices architecture?', N'Senior', N'A service mesh offloads infrastructure concerns like service discovery, mutual TLS, traffic shifting, and observability from the application layer to a sidecar proxy. This allows developers to focus on business logic while standardizing cross-cutting reliability patterns across diverse polyglot services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b38864a9-c17d-4557-af3f-b6dd2a77fd0a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is your approach to estimating the effort for an API change that affects multiple downstream consumers?', N'Middle', N'I identify all dependent systems and account for the coordination time, testing, and potential backward-compatibility layers required. I estimate the effort as a cross-team project, factoring in the time needed for documentation updates and support during the transition for other teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fae62f6-e063-4962-bf28-b6e54b457527', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle component re-rendering?', N'Fresher', N'In SolidJS, components are executed only once when they are initialized. Subsequent updates do not re-run the entire component function; instead, only the specific reactive expressions inside the template that depend on the changed data are updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d6bd331-19e3-4d9b-9971-b6e653102f4f', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the event modifiers provided by vue?', N'Intern', N'Normally, javascript provides event.preventDefault() or event.stopPropagation() inside event handlers. You can use methods provided by vue, but these methods are meant for data logic instead of dealing with DOM events. Vue provides below event modifiers for v-on and these modifiers are directive postfixes denoted by a dot. 1. .stop 2. .prevent 3. .capture 4. .self 5. .once 6. .passive Let''s take an example of stop modifier, You can also chain modifiers as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'800ccb92-ca99-41c0-b68b-b6e75e962b1c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the core architectural difference between Micronaut and Spring Boot?', N'Middle', N'Micronaut performs dependency injection and AOP proxy generation at compile-time using annotation processors, whereas Spring Boot typically performs these tasks at runtime using reflection. This results in faster startup times and a significantly lower memory footprint for Micronaut applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9fd4a33-4450-42c2-9c54-b6e85d29770d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are nested routes in Remix?', N'Intern', N'Nested routes allow you to define parts of your UI that correspond to specific segments of a URL. This structure enables multiple parts of a page to load data independently and update without refreshing the entire screen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e67098e-cbeb-4286-af57-b6e910f9aa60', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What impact does PHP''s error reporting level have on production security?', N'Middle', N'Displaying detailed error messages in production can reveal sensitive information about the file system, database structure, or configuration. It is critical to disable error display and log errors to a secure file, ensuring that end-users see only generic messages while developers retain access to diagnostic info.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25f24192-9a6d-4018-bbbc-b6e9990d1a37', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is it considered good practice to use a router like Chi instead of just the standard library''s ServeMux?', N'Intern', N'While the standard library ServeMux is functional, Chi offers more powerful features such as route grouping, parameter capturing, and better middleware support. These features simplify the development of complex APIs compared to the basic capabilities of the standard library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd867bc3a-6d3d-4bcd-95f7-b6ece8f685c3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Compare ''std::vector'' and ''std::list'' regarding CPU cache and memory allocation patterns.', N'Senior', N'std::vector stores elements contiguously, which maximizes cache hit rates and allows for efficient prefetching, making it faster for most workloads. std::list uses nodes scattered in memory, incurring overhead for pointers and causing frequent cache misses, though it provides faster insertion and deletion at arbitrary positions without invalidating existing iterators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f453ebe-24b8-4d0a-a708-b6f076177c61', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between a block, a proc, and a lambda in Ruby?', N'Fresher', N'A block is a chunk of code passed to a method that is not an object. A proc is an objectified block that can be stored in a variable, and a lambda is a special type of proc that enforces argument count and returns control flow differently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44688f3d-10cd-486d-8f53-b6f0e19efb1e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the function of the x-model directive?', N'Fresher', N'The x-model directive creates a two-way data binding between an HTML input element and the component''s data. This ensures that whenever the input value changes, the corresponding data property updates, and vice versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eed05284-5fda-4a7d-80bc-b6f1ff32ea38', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the trade-offs between stack and heap memory allocation in C.', N'Middle', N'Stack allocation is managed automatically by the compiler and is extremely fast, but it is limited in size and requires the variable''s lifetime to be tied to the function scope. Heap allocation provides manual control over memory lifetime and allows for much larger data structures, but it introduces overhead, risks of memory leaks, and potential fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b663a4d6-d834-4a6a-8dcb-b6f2010cbcec', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the significance of the ''Nothing'' type?', N'Junior', N'Nothing is a subtype of every other type in Scala, but it has no instances. It is typically used to indicate non-termination, such as when a function throws an exception or enters an infinite loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60586f8a-62a9-40da-914b-b6f5707e5c84', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the difference between synchronous and asynchronous replication in a database cluster?', N'Senior', N'Synchronous replication ensures that a write is committed on all replicas before acknowledging success, providing strong consistency but increasing latency. Asynchronous replication acknowledges the write as soon as the primary commits, offering lower latency but introducing the risk of data loss if the primary fails before propagating the change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2911a8b0-197d-4b26-b072-b6fc077f630c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What does the ''super()'' function do?', N'Junior', N'The ''super()'' function is used to call methods from a parent or sibling class. It is commonly used in child classes to invoke the parent class''s __init__ method to ensure that base class attributes are properly initialized. This allows for clean inheritance and prevents the need to hardcode the parent class name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cb46884-1595-44ab-a2ff-b6fc6b223afc', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the advantage of using Echo''s Logger middleware in production?', N'Middle', N'The Logger middleware provides standardized, structured output for every incoming request, including status codes, latency, and request paths. This is essential for monitoring application performance and debugging issues in a production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c79e1b04-744f-481b-95c1-b6fd7b05d184', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Can Elasticsearch handle relational data?', N'Junior', N'Elasticsearch is not a relational database and does not support joins in the same way SQL does. While it can store nested or parent-child data, it is designed for denormalized data to ensure high-performance search and retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c94f2607-bbb2-4f20-bc2a-b6fe5d8d8fee', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the architectural benefits of the Fastify ''onRegister'' hook?', N'Senior', N'The ''onRegister'' hook allows developers to intercept the registration of new plugins, enabling dynamic configuration or logging. This is particularly useful for building platform-level frameworks or plugins that need to monitor or modify the behavior of subsequent modules during startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1016f87-590f-43d8-bbbf-b70134733f0c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What strategy should be used to avoid ''Hot Partition'' issues in DynamoDB?', N'Senior', N'To avoid hot partitions, one must choose a high-cardinality partition key that distributes traffic evenly across all available partitions. If a specific key must be accessed frequently, adding a random suffix or prefix to the key can spread the load across multiple partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5795ffd-cb19-4448-a6d0-b70613ab2c80', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the role of the Kestrel web server and why a reverse proxy like Nginx or IIS is typically placed in front of it.', N'Senior', N'Kestrel is a cross-platform, asynchronous, event-driven HTTP server designed for high-performance internal request processing. A reverse proxy is used in production to provide features Kestrel lacks, such as SSL termination, request buffering, load balancing, and protection against specific network-level attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4880e09-58e6-45a6-87be-b7062f99e51b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''batch'' function used for in SolidJS?', N'Middle', N'The batch function allows multiple signal updates to be processed together in a single cycle. This is useful for performance optimization, as it prevents the UI from re-evaluating multiple times when several related states are updated simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c54279f6-31bf-4f9e-9c19-b707eedb1da5', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do Lua scripts enhance Redis functionality?', N'Middle', N'Lua scripts allow you to execute multiple commands atomically on the server side, reducing network round trips between the application and the database. By encapsulating logic within a script, you ensure that no other commands are processed during the script''s execution, maintaining consistency for complex operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'746333f9-fa26-4592-9196-b70b12704045', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you handle events in Svelte?', N'Intern', N'Event handling in Svelte is done using specific directives that attach listeners to HTML elements. When an event, such as a click or input change, is triggered, it executes a defined function within the component to update the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2172d2ac-4409-44e7-99eb-b70b8039aca9', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of Django’s database router and when is it used?', N'Senior', N'A database router controls which database a query is sent to, enabling patterns like read-write splitting or sharding. It is used when an application needs to distribute load across multiple database instances or isolate specific models to different physical databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a66332e9-c377-4446-85de-b70e260529f2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Describe the trade-offs of using Astro versus a framework like Next.js.', N'Middle', N'Astro is optimized for content-heavy websites with minimal interactivity, favoring performance through zero-JS defaults. Next.js is better suited for complex, highly interactive applications that require frequent state updates and deep client-side routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66067bb5-272e-40af-96ce-b70f4041bbc8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the Micronaut Data project?', N'Intern', N'Micronaut Data is a library that provides an abstraction for database access. It generates repository implementations at compile-time, reducing the need for manual boilerplate code for database operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b69306af-b970-43d1-b9ae-b71020183a4f', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Why is persistent storage critical in a distributed message broker, even if data is consumed immediately?', N'Senior', N'Persistence provides a buffer against consumer downtime and ensures the system can recover state after a broker crash. Without disk-backed storage, the system is susceptible to complete data loss during power failures or network partitions, violating the durability expectations of most distributed enterprise systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc39cb62-96aa-4532-b18d-b712100396cc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why does Web Storage only support strings, and how do you safely store and retrieve complex data?', N'Fresher', N'The Web Storage API stores all values as plain strings. Passing a non-string value calls .toString() on it implicitly — which for objects produces "[object Object]" and for arrays produces a comma-joined string — silently corrupting the data. The correct solution is to serialise with JSON.stringify before writing and deserialise with JSON.parse after reading. JSON.stringify has limitations: it drops undefined values, converts Date objects to ISO strings (losing the Date type), cannot serialise functions, and throws on circular references. A robust storage utility must handle these edge cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8acb5407-c8e9-4873-9005-b71dd6456ac4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''infer'' keyword in conditional types, and how does it enable advanced type metaprogramming?', N'Senior', N'The ''infer'' keyword allows the compiler to extract and name types from within other types, such as return types of functions or generic parameters. It is fundamental for building utility types like ''ReturnType'' or ''Parameters'' that perform introspection on existing definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4f9b01e-501e-4678-9466-b71f11759fea', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What does it mean to ''fail fast'' in an engineering context?', N'Intern', N'Failing fast means testing the riskiest parts of a project early on to see if they are feasible. By identifying fatal flaws early, you save resources and time that would have been spent on a project doomed to fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'011ac6c4-5473-4e10-a91b-b72537f57ca8', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of the @Body() decorator?', N'Intern', N'The @Body() decorator in NestJS is used to extract the entire body of the incoming HTTP request. It''s commonly used in methods that handle POST and PUT requests where data is sent in the body of the request. For example, if you have a method in your controller to create a new user, you might use the @Body() decorator to get the user data from the request: In this example, createUserDto is an object that contains the data sent in the request body. The @Body() decorator automatically parses the JSON request body and assigns it to the createUserDto parameter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfa1e1ca-1c29-497b-aaff-b730180f4894', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain the role of ''context'' in Webpack configuration.', N'Middle', N'The context is the base directory for resolving entry points and loaders from the configuration. By setting this property, you ensure that Webpack looks for files relative to a specific project root, which helps in maintaining consistency across different environments and build machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57ab2d63-15c1-4d51-9130-b7305ee92800', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the ''weakref'' module prevent memory leaks in caching scenarios?', N'Senior', N'Weak references allow an object to be referenced without increasing its reference count, meaning the garbage collector can reclaim the object if no strong references remain. This is essential for building caches where you want to store objects without preventing them from being deallocated when they are no longer needed elsewhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11c389c6-b812-4df1-81a6-b731be95edfe', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What does it mean for Dart to be soundly typed?', N'Fresher', N'Dart uses a sound type system, which ensures that an expression''s static type matches its runtime value. This helps catch bugs during development and enables better performance by allowing the compiler to make reliable assumptions about data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33d4f6ee-66e7-4096-a5d6-b7320c260211', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why would you implement a multi-level cache architecture?', N'Middle', N'A multi-level architecture usually combines a small, fast local cache with a larger, slower distributed cache. This hierarchy balances the need for extreme low-latency access for hot items with the need for a wide-reaching, shared cache for general application data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2955296-5bbf-45de-b06d-b733ab73d302', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the Result enum used for?', N'Intern', N'The Result enum is the standard way to handle recoverable errors in Rust. It contains either a success value or an error value, requiring the caller to acknowledge and handle the error before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f5a8d63-c22d-4520-8769-b733f46b856b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a factor in R and when is it used?', N'Junior', N'A factor is a data object used to store categorical data. It represents data as a set of discrete levels, which is particularly useful for statistical modeling and grouping data in visualizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
