INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3e2bef4-dc82-4eca-ae36-b7390dc9200a', N'a2838158-7305-480a-b22b-4dc35776b400', N'Describe the difference between ''Active-Active'' and ''Active-Passive'' database replication.', N'Senior', N'Active-Passive uses one node for writes and others for reads, providing strong consistency but creating a potential bottleneck and slower failover. Active-Active allows writes to all nodes, improving write availability and reducing latency for geographically distributed clients, but introduces significant complexity in conflict resolution and consistency management. Active-Active is generally more complex to operationalize and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df5d4bea-ae01-4c41-9c04-b73cc76be582', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What happens if two routes overlap in Chi?', N'Intern', N'Chi matches routes in the order they are defined. If a request matches multiple patterns, the router will select the first one defined in the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9366ccb2-f5c4-45a9-ab67-b74017b314dc', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between an ''API'' and a ''User Interface''?', N'Intern', N'A User Interface is designed for humans to interact with a system through visuals, buttons, and menus. An API is designed for different software systems to communicate and exchange data with each other automatically. While the UI is for human users, the API is the bridge between machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
