INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f4a190-a40d-4ecf-a05e-b74621f4ccb5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''super()'' function?', N'Junior', N'The ''super()'' function is used in inheritance to call methods from a parent class. It allows a child class to extend or override functionality while still utilizing the base logic defined in the parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'248e8ebb-40f9-43a0-8f87-b7481c27e675', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you implement defense-in-depth within a microservices architecture?', N'Senior', N'Defense-in-depth is achieved by layering security controls such as mTLS for service-to-service communication, network segmentation via VPCs or service meshes, and identity-aware proxies at the edge. By ensuring that no single failure of a security component compromises the entire system, you reduce the blast radius of any potential breach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71dc7c79-e778-4328-b076-b748ee3ccfde', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How can you implement circuit breakers at the API level to improve resilience?', N'Senior', N'Circuit breakers monitor for failures in downstream services and trip when thresholds are met, preventing cascading failures by immediately rejecting requests or returning a fallback response. This architectural pattern isolates the failing component and allows the system to recover gracefully without exhausting resources on retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a93ada75-be99-4559-aacc-b74f7d197f50', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the concept of ownership in Rust?', N'Intern', N'Ownership is a set of rules that governs how a Rust program manages memory. Every value in Rust has a variable that is called its owner, and there can only be one owner at a time. When the owner goes out of scope, the value is automatically dropped and the memory is reclaimed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'272da8d5-42bf-4b4f-acdc-b75035637b90', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between full-text search and exact match search?', N'Intern', N'Full-text search analyzes the content of fields to find matches based on linguistic relevance, such as stemming or synonyms. Exact match search looks for the precise value in a field without any analysis or transformation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'330b734d-7a77-4a08-a70f-b7506e013c4f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''nuxt dev'' command?', N'Intern', N'The nuxt dev command starts a development server with hot module replacement. This allows you to see changes in real-time as you modify your files without needing to refresh the browser manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9266e600-de1a-4935-bfd1-b7542cbf165f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is jQuery and why is it used?', N'Fresher', N'jQuery is a fast, small, and feature-rich JavaScript library. It simplifies HTML document traversal, event handling, and animation by providing an easy-to-use API that works across a multitude of browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dafaa42-3a73-463c-b136-b7542f885d5d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the ''Dispatching'' mechanism of Coroutine Builders and its effect on performance.', N'Senior', N'Coroutine builders like ''launch'' or ''async'' define where the coroutine starts executing, allowing developers to precisely control thread affinity. Proper selection of dispatchers is critical to prevent thread starvation and ensure that UI-related or blocking tasks do not interfere with the responsiveness of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74fc9c19-8bfc-42fd-89ad-b754fe5ede13', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the process of compaction in Cassandra.', N'Middle', N'Compaction is the background process that merges multiple SSTables into a single new one while discarding deleted or overwritten data. This process is essential for reclaiming disk space and improving read performance by reducing the number of files the system must check.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2153c14-73aa-416d-9e5a-b75718c8a263', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What does serverless mean in the context of DynamoDB?', N'Intern', N'Serverless means that the user does not need to provision, patch, or manage any physical servers or infrastructure. AWS handles all hardware maintenance, software patching, and capacity scaling automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'719024f8-4363-47fb-aa76-b7581d223fa7', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''body'' in an Axum response?', N'Junior', N'The body contains the actual content of the HTTP response, such as a JSON string, a stream of bytes, or HTML. Axum provides several ways to construct this body, depending on the data type returned by the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4a830da-481f-4008-b36b-b75a8997f2b3', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the trade-offs between using provide/inject versus Pinia for state management.', N'Senior', N'Provide/inject is ideal for dependency injection in component trees to avoid prop drilling without adding external dependencies. Pinia is preferred for global state management because it provides centralized stores, better devtools integration, and built-in support for SSR and plugins, making it more scalable for complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12c57fd4-23e2-424e-ba75-b75b81bd27c5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the impact of procedural macros on Rocket''s compilation time?', N'Senior', N'Procedural macros allow Rocket to perform extensive static analysis, which increases compilation time as the complexity of the application grows. However, this trade-off is intentional because it enables the framework to catch errors at compile-time that would otherwise remain hidden until runtime in other languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16ad6f7f-dfa3-4d74-a7a3-b75d045254a6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does Lucid ORM function within the AdonisJS ecosystem?', N'Intern', N'Lucid is the official ORM for AdonisJS that allows developers to interact with databases using object-oriented syntax instead of raw SQL. It maps database tables to classes and rows to objects, simplifying tasks like data retrieval, updates, and relationship management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8babd15e-cd9a-41d9-bed9-b75d9e788665', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Describe the impact of the ''Write Skew'' anomaly.', N'Senior', N'Write skew occurs when two transactions read overlapping data sets but modify disjoint sets in a way that violates a global constraint. Because neither transaction sees the other''s update, the database integrity is compromised despite each transaction individually adhering to its own logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
