INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'369a6d59-8568-46db-a452-b76307f93f62', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What does ''Lazy Evaluation'' mean in Django QuerySets?', N'Intern', N'Lazy evaluation means that creating a QuerySet does not actually hit the database until the data is explicitly requested. This optimization prevents unnecessary database queries until the moment the results are needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
