INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e533959e-f4a5-45d7-a0b9-b766c2fcc417', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle HTTP request contexts?', N'Intern', N'Gin uses a context object, typically named ''c'', which is passed to every handler. This object encapsulates the HTTP request and response writer, providing methods to retrieve parameters, read request bodies, and send various types of responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bad4756-2f9b-4808-ac44-b76b50cd18e3', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the architectural implications of the C++ zero-overhead principle on template metaprogramming and static polymorphism?', N'Senior', N'The zero-overhead principle dictates that what you do not use, you do not pay for, and what you do use, you could not hand-code better. In template metaprogramming, this results in shifting the computational burden from runtime to compile-time, effectively eliminating dynamic dispatch overhead. While this leads to highly efficient machine code, it often results in increased binary size and longer compilation times due to the instantiation of specialized code paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b9d83bd-6e2c-474f-a81e-b7727a93ede5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What happens to TypeScript code when it is compiled?', N'Junior', N'TypeScript is transpiled into plain JavaScript by the TypeScript compiler (tsc). During this process, all type annotations and interface definitions are removed, leaving behind standard JavaScript that can run in any browser or Node.js environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e00e6baa-ca65-4b1b-beb7-b775b043a778', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Describe the purpose of a Content Security Policy (CSP).', N'Middle', N'CSP is an HTTP header that allows site operators to restrict the resources, such as JavaScript, CSS, or images, that a browser is allowed to load for a given page. It acts as a defense-in-depth mechanism to mitigate Cross-Site Scripting (XSS) and data injection attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c1e1ff6-bb80-48e0-9f8d-b7782e89c06b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is function overloading in C++?', N'Intern', N'Function overloading in C++ is a feature that allows multiple functions to have the same name but different parameter lists. The compiler distinguishes between these functions based on the number, types, and order of parameters. Key Concepts Parameter Lists - Functions are differentiated based on: - Types of parameters - Order of parameters - Total number of parameters - An empty parameter list is valid (nullary function) Restrictions - Return type alone is not sufficient to differentiate functions - Overloading works for both global and member functions Code Example Here''s a C++ code snippet demonstrating function overloading: Best Practices - Consistent Naming: Use function names that reflect their purpose - Clarity Over Complexity: Use overloading judiciously to maintain readability - C...', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37a84f3c-7b21-468e-837d-b7809470e29a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does the Next.js Image component optimize delivery beyond simple compression?', N'Senior', N'The Image component provides automatic responsive resizing, format conversion to modern types like WebP or AVIF, and lazy loading by default. It also prevents layout shifts by enforcing height and width dimensions, ensuring optimal performance on diverse network and device conditions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d2a2a59-7be1-4234-8e6b-b780f5ae5382', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What are the trade-offs of using a distributed lock manager?', N'Middle', N'A lock manager provides a way to coordinate access to shared resources across multiple nodes, ensuring data integrity in concurrent processes. However, it introduces a new point of failure, increases latency due to network communication, and is notoriously difficult to implement correctly under split-brain scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08064caf-8d70-418e-bf65-b7837dc494c5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the advantages of using Type Hints in modern Python?', N'Middle', N'Type hints improve code readability and maintainability by documenting the expected data types for function arguments and return values. They also enable static analysis tools to catch type-related bugs during development without affecting runtime performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd96104b0-1bcc-4a88-800e-b783da259176', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does routing work in Echo?', N'Intern', N'Routing is the process of mapping a specific HTTP request method and URL path to a corresponding handler function. Echo uses a highly optimized tree-based router to quickly match incoming requests to the correct logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a48f52d4-3016-4b52-9ace-b784ba9a2219', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is durability in database transactions?', N'Fresher', N'Durability guarantees that once a transaction has been committed, the changes are permanently saved in the database. Even in the event of a system crash or power failure, the committed data remains intact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6055d0c-6a36-4725-9eb0-b785d2054505', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle JSON serialization?', N'Junior', N'Fiber uses the highly optimized jsoniter library by default to perform JSON marshaling and unmarshaling. This is significantly faster than the standard library''s reflect-based JSON processing, which helps in reducing overall CPU usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8493a11-7661-4542-85fa-b788475f066b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar leverage Type Hints to enhance architectural maintainability?', N'Senior', N'Litestar uses type hints not just for validation, but as the primary source of truth for its reflection-based architecture. This allows the framework to automatically generate OpenAPI documentation, perform dependency injection, and validate request data without requiring redundant configuration or decorators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18c7eabc-85f2-4894-b133-b78a525d973b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the differences between redux-saga and redux-thunk?', N'Intern', N'Both _Redux Thunk_ and _Redux Saga_ take care of dealing with side effects. In most of the scenarios, Thunk uses _Promises_ to deal with them, whereas Saga uses _Generators_. Thunk is simple to use and Promises are familiar to many developers, Sagas/Generators are more powerful but you will need to learn them. But both middleware can coexist, so you can start with Thunks and introduce Sagas when/if you need them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2466a95-1f17-40fa-bfb6-b78c1e97579b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why would you choose Tailwind''s ''apply'' directive, and what are the risks associated with it?', N'Middle', N'The ''apply'' directive allows you to extract common utility patterns into custom CSS classes to clean up HTML. The risk is that overusing it can lead to ''CSS-in-CSS'' anti-patterns, where you end up recreating a standard CSS architecture that defeats the purpose of the utility-first approach and makes debugging harder.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed7ba101-b3dc-4abc-8925-b78dee3cab7f', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the difference between early binding and late static binding in PHP.', N'Middle', N'Early binding resolves ''self::'' to the class where the method is defined, regardless of which class called it. Late static binding uses the ''static::'' keyword to resolve the reference at runtime to the class that was actually called, allowing for polymorphic behavior in static methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8386fb9-720b-4310-82ad-b78f72394269', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the advantages of React?', N'Intern', N'Below are the list of main advantages of React, 1. Increases the application''s performance with _Virtual DOM_. 2. JSX makes code easy to read and write. 3. It renders both on client and server side (_SSR_). 4. Easy to integrate with frameworks (Angular, Backbone) since it is only a view library. 5. Easy to write unit and integration tests with tools such as Jest.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'094adf64-ed52-4101-927b-b79334d55b3d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the concept of polymorphism in C++?', N'Intern', N'Polymorphism allows objects of different classes to be treated as objects of a common base class. It enables a single interface to represent different underlying forms, typically through the use of virtual functions. This allows for flexible and reusable code by letting derived classes provide specific implementations of methods defined in the base class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b559401-ed3c-4c4a-99b0-b795b55c75e1', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does ''Zero JavaScript by default'' mean in Astro?', N'Intern', N'It means that Astro strips away all client-side JavaScript from your components unless you explicitly tell it otherwise. This results in faster page loads because the browser processes less code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49e6a29c-a6c5-4ef8-be41-b7999a776caf', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is an Eventually Consistent Read in DynamoDB?', N'Intern', N'An eventually consistent read returns data that might not reflect the results of a recently completed write operation. This mode maximizes read throughput but accepts a brief delay before all copies of the data are synchronized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f9b5de6-a9ed-460b-bba6-b79b19d59d9e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does routing work in the Echo framework?', N'Fresher', N'Routing in Echo maps incoming HTTP requests to specific handler functions based on the request method and the URL path. It supports static paths, path parameters, and query parameters to handle dynamic requests effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b14c8b70-6604-4f86-a5a7-b7a16ca8bd8e', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of html directive?', N'Intern', N'The v-html directive is used to update the inner html of a DOM element with latest data. It is similar to innerHTML property in DOM. The example usage of this directive as shown below, Note: This directive should be used with trused content only but not on user provided content. Otherwise it can leads to XSS vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8467a007-cf29-4fdb-a8a1-b7a27146d4bb', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are NestJS Providers and how do they function?', N'Intern', N'Providers are a core concept in NestJS, acting as classes that can be injected as dependencies into other components. They are typically used to encapsulate business logic, services, or data access layers, ensuring that shared functionality is easily accessible throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'646ef29b-5d03-4d5d-94e8-b7a283916580', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the role of feature flags in troubleshooting production issues?', N'Middle', N'Feature flags act as a safety mechanism, allowing developers to disable a specific piece of functionality immediately if it is suspected of causing a production issue. By toggling off a new feature without a full rollback, we can quickly verify if the feature is the root cause. This minimizes the mean time to recovery and reduces the blast radius of new deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07e8a7b7-285c-4220-b85b-b7a341ea7863', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does the ''Circuit Breaker'' pattern protect system stability?', N'Senior', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail by tripping the circuit after a threshold of errors. This allows the failing service time to recover while providing an immediate fallback response to the caller, preventing resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af38690b-a2cf-4333-b988-b7aaf3d95793', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary difference between a traditional bundler and Vite?', N'Intern', N'Traditional bundlers like Webpack must process and bundle the entire application before starting the server. Vite, by contrast, uses native ES modules to serve files on demand, which results in significantly faster startup times regardless of project size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23f0fe41-130c-406c-b95d-b7adf3309fff', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit hooks (handle, handleError, handleFetch) influence the request lifecycle?', N'Senior', N'Hooks act as middleware that intercept every request at the server level, allowing for global authentication checks, custom header injection, or global error logging. They provide a unified pipeline for cross-cutting concerns that would otherwise need to be duplicated across multiple route files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3081603c-a995-4948-9765-b7aecd575cc2', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why should you always cast the result of malloc in C?', N'Junior', N'In standard C, casting the result of malloc is not strictly required because void pointers are automatically promoted to any other pointer type. However, some developers include it to maintain compatibility with C++ compilers, which do not permit implicit conversion from void pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a3278a7-35ab-4390-b504-b7b56d01197a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the benefit of Redux''s strict data flow?', N'Fresher', N'The strict data flow ensures that every change to the state happens in a predictable, unidirectional cycle. This makes it much easier to understand how data moves through an application and makes debugging significantly simpler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45d49e96-82c3-441e-9b53-b7bde887d0e2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the DOM? How does the DOM work?', N'Intern', N'The DOM (Document Object Model) is a cross-platform API that treats HTML documents as a tree structure consisting of nodes. These nodes (such as elements and text nodes) are objects that can be programmatically manipulated and any visible changes made to them are reflected live in the document. In a browser, this API is available to JavaScript where DOM nodes can be manipulated to change their styles, contents, placement in the document, or interacted with through event listeners. * The DOM was designed to be independent of any particular programming language, making the structural representation of the document available from a single, consistent API. * document.getElementById() and document.querySelector() are common functions for selecting DOM nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe53b54c-0723-40e9-8e95-b7c06ab922fc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of the TypeScript compiler?', N'Intern', N'The TypeScript compiler, known as tsc, is responsible for checking the code for type errors and converting TypeScript files into standard JavaScript. It also provides configuration options that allow developers to control how strictly the code is checked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0738541d-928c-4476-bf41-b7c0963809d6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the benefit of the Actor model for debugging?', N'Junior', N'The Actor model promotes isolation, meaning each actor manages its own state. This makes it easier to track down bugs because state changes are localized to specific actors rather than being spread across global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd330fd38-e6ec-400c-9518-b7c1ba1c558e', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between == operator and .Equals() method?', N'Fresher', N'The == operator in Cis used to compare two objects for reference equality, meaning it checks whether the two objects are the same instance in memory. On the other hand, the .Equals() method is used to compare the actual values of the two objects, based on how the method is implemented for a particular class. For value types like int, bool, double, and structs, the == operator compares the values, whereas for reference types like string and custom classes, it compares the references. It''s important to note that the behavior of the == operator can be overridden for reference types by overloading the operator, allowing it to compare values instead of references. The .Equals() method can also be overridden in classes to provide custom equality comparisons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9ac682d-cfb8-4db8-afd9-b7c43f9f2cd9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the C programming language?', N'Intern', N'C is a high-level, general-purpose programming language that provides low-level access to memory and system processes. It is widely used for system programming, such as operating systems and embedded hardware, because of its efficiency and portability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9288d27-4db2-4c56-b90f-b7c5e13c957c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What happens when a goroutine panics in a multi-threaded application?', N'Middle', N'A panic will crash the entire process unless it is recovered within the same goroutine. Other goroutines will be terminated abruptly, making it critical to design robust error handling that does not rely on panics for standard control flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bca025a2-c919-4f12-aa9d-b7c812769b87', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s approach to state management compare to patterns like Redux or Context?', N'Senior', N'Lit is framework-agnostic regarding state management, but it integrates well with patterns like Context or external stores. While internal reactive properties handle local component state, for global state, Lit developers typically use the Context API or an external observable store to provide data down the component tree without prop-drilling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'660fcd24-0d75-45ee-9970-b7cbbaac8c3c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is a ''Request Guard'' in Rocket?', N'Intern', N'A request guard is a mechanism used to validate requests before they reach a handler. They are often used for authentication, authorization, or ensuring specific headers exist, preventing invalid requests from executing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff5b6a2a-462e-43e1-b8e2-b7cbd9b1fd2d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What happens when a Lit component''s property changes?', N'Junior', N'When a property changes, Lit schedules an update to the component. This update process includes checking for changes, running the render method, and performing a minimal update to the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc5db58c-f751-4623-b800-b7d2526ed9ff', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are Route Groups in AdonisJS?', N'Fresher', N'Route groups allow you to apply shared configuration to a collection of routes. This is commonly used to apply middleware, prefixes, or domain constraints to a set of related endpoints without repeating code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ac49655-f636-4d3c-af65-b7d4baf768a4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Describe how the C++ standard library manages the ''Iterator Invalidation'' problem.', N'Senior', N'Iterator invalidation occurs when a container''s underlying memory is reallocated or elements are moved, rendering existing iterators dangling. The C++ standard defines specific rules for each container type regarding when iterators are invalidated, forcing developers to be mindful of state changes during iteration and to use updated iterators returned by methods like insert or erase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f199fa1-40ce-4772-a181-b7d5830b1956', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is Sass and why is it used in frontend development?', N'Intern', N'Sass stands for Syntactically Awesome Style Sheets and is a CSS preprocessor. It extends CSS by adding features like variables, nesting, and mixins, which help make stylesheets more organized, maintainable, and easier to write.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f5975d-e6ea-4712-9ed1-b7d5a0f2aadd', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between using a shared cache versus local in-memory caching?', N'Senior', N'Local in-memory caches offer the lowest possible latency but make cache invalidation difficult across multiple nodes, potentially leading to stale data. Shared caches like Redis provide a single source of truth and easier invalidation, but they introduce network latency and an additional moving part. I use local caches for highly static data and shared caches for dynamic data that requires global consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea8ea7dc-315b-48bd-85b7-b7d60d7d5d19', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the difference between a Router and a Service in Axum.', N'Middle', N'A Router is a specialized structure that maps request paths and methods to specific handlers. A Service is the lower-level abstraction that executes the logic, meaning every Router can be treated as a Service, allowing for easy composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f33c765c-7015-4553-9a9b-b7d99f5e4128', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you design an API to be secure against mass assignment vulnerabilities?', N'Middle', N'Mass assignment occurs when an API automatically binds client input to internal database models. You can prevent this by using Data Transfer Objects (DTOs) to explicitly define which fields are allowed to be updated, rather than mapping input directly to the entity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22cc9184-eed8-4d4b-a8c8-b7db23c807a0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt handle environment variables securely across server and client environments?', N'Senior', N'Nuxt differentiates between server-only and runtime-public environment variables. Variables defined with the ''NUXT_PUBLIC_'' prefix are bundled into the client-side code, while others remain strictly server-side, preventing sensitive keys from being exposed to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72a72b11-a445-4988-a1a5-b7dcd4893932', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why would you use a read replica in a database setup?', N'Middle', N'A read replica is used to offload read-heavy traffic from the primary database, thereby improving system performance and availability. It allows the system to scale its read capacity independently of write capacity, though it introduces a slight lag in data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
