INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58dd1aab-c345-4a75-87fd-b7ee1f10bae9', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle animation, and why might CSS transitions be preferred?', N'Middle', N'jQuery animates elements by calculating values and applying inline styles over time, which can trigger frequent layout recalculations and reflows. CSS transitions and animations are handled by the browser''s compositor thread, which is more efficient and usually results in smoother performance than JS-based animations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
