INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23a12523-0026-45eb-b5e4-b7f51514998a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the role of Database Indexes and how you would implement them in a Django model.', N'Middle', N'Indexes significantly speed up data retrieval by creating a lookup structure for specific columns. In Django, you implement them using the ''db_index=True'' attribute on a field or by defining an ''Index'' object within the model''s Meta class for more complex or multi-column indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
