INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6841cae3-e57e-4ac6-aaed-b7fa0b77dbbf', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the structure of a for loop?', N'Intern', N'for in : … The ellipsis represents a code block to be executed, once for each item in the sequence. Within the block the item is available as the current item from the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72dd8b70-c773-477b-bd29-b7fa0c2d17b2', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is synchronous replication rarely used in globally distributed databases?', N'Senior', N'Synchronous replication requires the primary node to wait for acknowledgment from replicas before confirming a write, which couples the write latency to the slowest round-trip time in the network. In a global setup, this results in prohibitively high latency and reduced availability if any replica becomes slow or unreachable. Asynchronous replication is preferred to prioritize performance and availability, accepting the risk of potential data loss during a failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bd82fe0-f69f-44d1-b5cb-b7fd172bf26e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Since Redis stores data in memory, what happens to the data if the server loses power?', N'Fresher', N'If Redis is configured only for in-memory storage, all data would be lost upon a power failure or server restart. However, Redis provides optional persistence mechanisms like RDB snapshots or Append Only File (AOF) logging, which periodically save the in-memory data to disk to allow for recovery after a restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93159471-d30e-42d3-95a9-b7fdb3f786d3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why is ''defer'' useful in Swift?', N'Middle', N'The defer statement ensures that a block of code runs regardless of how the current scope is exited, such as through a return, break, or thrown error. It is primarily used for cleanup operations like closing file handles or releasing resources, ensuring they are always executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94edc769-7163-4b8b-9599-b7feed4c1c3f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why is Kotlin considered interoperable with Java?', N'Intern', N'Kotlin is designed to be fully compatible with Java, meaning you can call Java code from Kotlin and vice versa without any issues. This allows developers to integrate Kotlin into existing Java projects incrementally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1822d82-fa31-4e04-b0dd-b80075f13cbf', N'954a0331-deff-4399-b588-96f39fec001d', N'What are macros?', N'Intern', N'The AOT compiler supports macros in the form of functions or static methods that return an expression in a single return expression. For example, let us take a below macro function, You can use it inside metadata as an expression, The compiler treats the macro expression as it written directly', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27b85ec7-d711-4462-9c6f-b801792b47c4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django model and how is it defined?', N'Intern', N'Django Models form the architectural foundation for database-driven applications. A model serves as a data structure and includes essential fields and behaviors. Model Definition A model class is a Python subclass of django.db.models.Model. Each attribute within the class represents a database field. The model class specifies the database table name, any data relationships, metadata, and methods for data manipulation. Key Model Components Fields - Definition: Represent the table''s columns. - Types: e.g., CharField, DateField. - Primary Key: id is default or can be customized. - Descriptors: Define field attributes e.g., null, blank. Meta Options - table_name: Database table name. - unique_together: A list of tuples for fields that should be unique when considered together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2fb0be6-1f6a-45bc-9c9d-b8019593552a', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is TypeScript preferred for NestJS?', N'Fresher', N'TypeScript is preferred because it provides static typing, which helps catch errors during development. NestJS is built on TypeScript to provide better tooling, maintainability, and code readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aeb228d-b1e9-426d-8d87-b8034e95f94c', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the alt attribute on images?', N'Intern', N'The alt attribute provides alternative information for an image if a user cannot view it. The alt attribute should be used to describe any images except those which only serve a decorative purposes, in which case it should be left empty.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e24254c-093d-4b84-a14c-b805c6d22157', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch ensure data is not lost during a node restart?', N'Middle', N'Elasticsearch ensures data durability through a combination of the translog and segment flushing to disk. When a node restarts, it recovers the latest state from the translog and re-syncs with the primary shard to ensure it has the most recent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'029e22e8-21c7-4043-9bee-b805d96920ed', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify use JSON Schema for request validation?', N'Junior', N'Fastify uses the Ajv library to compile JSON schemas into highly optimized functions for validating incoming request data. By defining a schema for body, query, or params, Fastify automatically rejects invalid requests before they reach your handler, improving security and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb00f7cf-fc4c-4016-ab00-b806d6806330', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the stack memory segment used for?', N'Intern', N'The stack is a region of memory that stores local variables and function call information. It operates on a last-in, first-out basis and is managed automatically by the system when functions are called and return.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'839c1c89-0cb6-460c-a147-b80bfa2b0870', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What does ''debug mode'' do in Flask?', N'Intern', N'Debug mode provides features that help during development, such as an interactive debugger in the browser and automatic reloading of the server when code changes occur. It should never be enabled in a production environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2267155-223b-450a-81e5-b80c47998953', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Describe the difference between the Repeatable Read and Serializable isolation levels.', N'Senior', N'Repeatable Read prevents dirty and non-repeatable reads but allows phantom reads where new rows can appear in a range scan. Serializable is the strictest level, preventing phantom reads and ensuring the outcome is equivalent to executing transactions one after another, typically via range locks or predicate locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0824bad-e6d2-42ee-b8d9-b80f5e7ae413', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the ''GenStage'' or ''Flow'' integration within Phoenix help manage backpressure?', N'Senior', N'GenStage provides a standard for producers and consumers to communicate, where the consumer explicitly requests the amount of work it can handle. This prevents the system from being overwhelmed by spikes in traffic, as the producers are naturally throttled by the downstream demand, ensuring overall system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46149ca3-4d22-4867-8a1d-b8122ca05017', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of a schema in MySQL?', N'Intern', N'In MySQL, a schema is logically equivalent to a database. It acts as a container that defines the structure of the data, including tables, views, and data types. It provides a way to organize and manage related database objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'484ff81e-8d31-4d87-8d7c-b81604064b86', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Distributed Transaction'' and why is it complex to implement?', N'Middle', N'A distributed transaction involves multiple independent databases or nodes that must all commit or abort together to maintain global consistency. The complexity arises from the need for consensus protocols like Two-Phase Commit, which can suffer from blocking issues and performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fc15ab3-038d-4097-9093-b81784be718b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is an index in a database?', N'Intern', N'An index is a data structure that improves the speed of data retrieval operations on a table. It acts like an index in a book, allowing the database engine to find rows without scanning the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'853f9120-ae1f-477b-9320-b819e63336a2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why does Lit favor native browser APIs over a virtual DOM?', N'Middle', N'By leveraging native browser features, Lit minimizes the overhead of a virtual DOM reconciliation layer. This results in smaller bundle sizes and faster performance, as the browser handles the core DOM operations natively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5657b61-0f46-40ab-a97d-b81e1803600a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono support the ''Edge-Side Rendering'' (ESR) pattern, and how does it differ from traditional SSR?', N'Senior', N'Hono facilitates ESR by running the rendering logic as close to the user as possible on the edge, reducing latency by avoiding round-trips to a central server. Unlike traditional SSR, which often relies on a heavy Node.js runtime and centralized database connections, Hono’s lightweight nature allows it to render content dynamically using edge-cached data or distributed storage, providing a faster, more resilient user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1356011c-6eaf-43d4-8610-b8264d93a8cd', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do you search for keys in Redis?', N'Fresher', N'You can search for keys using the KEYS command or, for larger datasets, the SCAN command. The SCAN command is preferred in production because it avoids blocking the server while iterating through the keyspace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b8664d5-81e2-44ef-9f55-b826a1e939b2', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you enforce immutability in Redux, and why is it vital for the React reconciliation process?', N'Senior', N'Immutability is enforced by creating new objects instead of modifying existing ones, often using libraries like Immer or spread operators. React uses shallow comparison of props and state objects to determine if a re-render is necessary; mutable updates would cause React to miss state changes, leading to UI bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
