INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd7cdc29-0aa5-4aa3-b42a-b834ef474a49', N'954a0331-deff-4399-b588-96f39fec001d', N'Why is it important to unsubscribe from Observables in Angular components?', N'Middle', N'Failing to unsubscribe leads to memory leaks because the Observable maintains a reference to the component, preventing garbage collection. Additionally, active subscriptions continue to execute logic in the background, which can cause unexpected behavior or performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20355014-c98a-4ca3-a34d-b835c93aa52c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between a Row Key and a Partition Key?', N'Intern', N'In many contexts, they are used interchangeably to refer to the value that determines the data distribution. Specifically, the partition key is the component of the primary key responsible for mapping data to a specific node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f4405af-46f3-49b1-8c72-b835e9712900', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of Ember Data?', N'Intern', N'Ember Data is a library for managing application data. It provides a consistent way to load, save, and update data from a server, mapping it into objects that can be used easily within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'296d42ba-3563-4044-8a56-b839473c97c9', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the trade-offs of using ''Leveled Compaction Strategy'' (LCS) versus ''Size Tiered Compaction Strategy'' (STCS) in a high-write-volume environment.', N'Senior', N'STCS is optimized for write-heavy workloads by grouping SSTables of similar sizes, but it can lead to massive read amplification. LCS maintains strict leveling to ensure most reads are satisfied by a single SSTable, making it superior for read-heavy workloads, though it imposes a much higher I/O overhead on background compaction processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82e59fb0-c9a3-4262-867e-b83aa8a39cf5', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo instead of the standard library ''net/http''?', N'Junior', N'While the standard library is powerful, Echo simplifies common tasks like routing, parameter extraction, and JSON handling. It provides a more ergonomic API, built-in middleware support, and better performance for complex routing scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2b7dff4-5707-410a-8c53-b83c4a5a2cb8', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Can Lit components be used without a build tool?', N'Intern', N'Yes, Lit can be used directly in the browser via ES modules. You can import Lit from a CDN and use it without needing complex build configurations like Webpack or Vite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7ad2a72-1195-4a93-9199-b83d6698ea05', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle data persistence?', N'Fresher', N'Redis generally prioritizes speed with in-memory data, using persistence methods for improved reliability and recovery. Persistence Options 1. RDB (Snapshots): - Saves point-in-time snapshots. - Configuration method often combined with AOF for full durability. 2. AOF (Append-Only File): - Logs every write operation, ideal for full durability. - Can be set to sync after every command or periodically. Understanding RDB and AOF - RDB Advantages: - Simplifies recovery. Loads faster from a binary dump on restart. - Efficient for infrequently-changing datasets. - AOF Advantages: - Best for ensuring every write is saved. Ideal for compliance and data integrity. May have a slight impact on performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'169021b5-b5a3-4cd2-9882-b83f90cbc802', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the concept of a ''Defense in Depth'' strategy?', N'Middle', N'Defense in depth involves layering multiple security controls so that if one security mechanism fails, others are in place to stop the threat. This holistic approach protects systems by ensuring no single point of failure compromises the entire architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b272fd4-6ccf-4ce4-aa07-b840d6e7d01f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the benefit of using Nuxt modules.', N'Middle', N'Nuxt modules allow developers to extend the framework''s core functionality, such as adding third-party integrations or modifying the build configuration. They promote modularity by encapsulating complex logic, which can be easily shared across different projects or maintained independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a94b02b-27f5-4abb-9762-b844549ef353', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does the Swift compiler''s ''Specialization'' pass improve generic code performance?', N'Senior', N'Specialization is a compiler optimization where generic functions are rewritten for specific concrete types used within a codebase. By creating specialized versions of generic code, the compiler can inline functions and eliminate the overhead of dynamic dispatch through witness tables. This brings the performance of generic code closer to that of non-generic, type-specific implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c9377a0-7de4-4325-af11-b84455410f7b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is the use of jQuery''s $.ajax() often discouraged in modern applications despite its convenience?', N'Senior', N'The Fetch API is now the native standard, offering cleaner promise-based syntax without the overhead of the entire jQuery library. Furthermore, jQuery''s AJAX implementation is built on top of the older XMLHttpRequest object, which provides less control over streaming and request cancellation compared to Fetch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e05b6b7-aad6-4751-b1d1-b8451396e093', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is a Gin ''Group'' and why would you use it?', N'Junior', N'A route group allows you to organize related routes and apply shared middleware to all of them at once. It is useful for implementing versioning, such as grouping all v1 API endpoints under a single path prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'512a80d6-36fc-4957-a2d0-b847f48c2ede', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Discuss the risks of using ''res.send'' versus ''res.json'' when building an enterprise-grade REST API.', N'Senior', N'res.json automatically sets the correct Content-Type header and handles object serialization safely, whereas res.send attempts to sniff the content type. In an API context, relying on sniffing can lead to security vulnerabilities or incorrect data interpretation by clients if the payload format is misinterpreted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1de5844f-fa08-4ae8-9a6d-b84811684354', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the Logger middleware in Gin?', N'Fresher', N'The Logger middleware automatically prints details about each incoming HTTP request to the console. It includes information such as the request method, URL path, response status code, and the time taken to process the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10f19013-b006-44e6-b0e1-b848e90f8369', N'075b8862-431c-4678-9767-f55359758a4a', N'Why should you avoid modifying props directly inside a child component?', N'Junior', N'Props are intended to be read-only from the child''s perspective to maintain a clear unidirectional data flow. Modifying them directly can lead to unexpected behavior and makes tracking data changes across the application very difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34a1aef3-242e-4f41-98f2-b84ab99c0af6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the assets directory?', N'Intern', N'The assets directory is used for files that need to be processed by a build tool, such as CSS, Sass, or images that require optimization. These files are bundled and transformed before being served to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbefa8ae-b41d-4aff-a457-b84b4065a32e', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How can you implement authentication in Litestar?', N'Middle', N'Authentication is typically implemented using an ''AuthenticationMiddleware'' or a custom guard. You define a strategy to verify credentials and set the user identity in the request scope, which can then be accessed by any downstream route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71ba629f-fb1c-4933-967e-b84dfa626d17', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the role of the ''maxmemory-policy'' in a production environment with limited RAM?', N'Senior', N'The maxmemory-policy determines how Redis evicts keys when the memory limit is reached, such as LRU, LFU, or random eviction. Choosing the correct policy is vital for balancing cache hit rates against the risk of evicting frequently accessed data, which can lead to increased load on the primary backend database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17e47ba0-fc1e-4c0a-8699-b84e2751a7f0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the impact of tree-shaking on bundle size and the requirements for it to function correctly.', N'Senior', N'Tree-shaking relies on static analysis of ES modules to prune dead code from the final bundle, significantly reducing payload size. For it to work, developers must ensure the use of ESM imports/exports and avoid patterns that obscure object structure, such as dynamic imports or side-effect-heavy module exports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fb25bf7-b53c-4828-85c0-b8517e95d2be', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle request body limits?', N'Middle', N'Chi does not have a specific ''limit'' middleware built-in, but it is expected that developers use the standard library''s http.MaxBytesReader to wrap the request body. This demonstrates the philosophy of Chi: leverage standard library tools for security and resource management rather than creating custom, framework-specific abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'652ada3e-1266-497f-bc91-b85282b85740', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a ''session'' in a Rails application?', N'Intern', N'A session is a mechanism that allows the application to store small bits of data across multiple requests from the same user. It is commonly used to keep track of user authentication status or temporary user preferences during their visit to the site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c8e88b-f40e-4210-a05a-b852d575bc2a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the impact of Remix on SEO compared to an SPA?', N'Middle', N'Remix provides superior SEO because it sends fully rendered HTML to the crawler, unlike SPAs which might require the crawler to execute JavaScript to see content. This ensures faster indexing and more accurate parsing of page content by search engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc1ad647-44a1-4a2a-a19b-b854b954eed5', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the ready event in jQuery?', N'Fresher', N'The document ready event ensures that the jQuery code only executes once the HTML document has been fully loaded and the DOM is ready to be manipulated. This prevents errors that might occur if a script tries to interact with elements that have not yet been rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cbb9b9b-f3ae-4e83-927c-b85628d321f5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are abstract base classes (ABCs) and how do they enforce interface design in Python?', N'Senior', N'ABCs, provided by the ''abc'' module, allow developers to define a formal interface that subclasses must implement. By using the @abstractmethod decorator, an ABC ensures that any concrete subclass must override specified methods, providing a compile-time check for architectural consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'724d7d41-9bba-4436-9fa2-b85744bef854', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to access Redux store outside a component?', N'Fresher', N'You just need to export the store from the module where it created with createStore(). Also, it shouldn''t pollute the global window object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ad99c6c-8dfd-4faf-b5c1-b85869f7e982', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between vertical and horizontal scaling for a service bottleneck?', N'Senior', N'Vertical scaling is faster to implement and avoids distributed system complexity but is limited by hardware capacity and introduces a single point of failure. Horizontal scaling allows for theoretically infinite growth and better fault tolerance, but requires investment in load balancing, state management, and service orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'642605f6-8aa8-4d3f-97a4-b859d7f262bb', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How are static files served in Actix-web?', N'Junior', N'Actix-web provides a ''Files'' service that can be registered to serve static files from a specific directory. This allows the server to efficiently handle requests for images, CSS, or JavaScript files without needing custom logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bafe1ad1-0968-4a2e-ad1b-b85aea5b4f40', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How many types of memory areas are allocated by JVM?', N'Fresher', N'JVM is a program which takes Java bytecode and converts the byte code (line by line) into machine understandable code. JVM perform some particular types of operations: * Loading of code * Verification of code * Executing the code * It provide run-time environment to the users Types of Memory areas allocated by the JVM: 1. Classloader: Classloader is a subsystem of JVM that is used to load class files. 2. Class(Method) Area: Class(Method) Area stores per-class structures such as the runtime constant pool, field and method data, the code for methods. 3. Heap: It is the runtime data area in which objects are allocated. 4. Stack: Java Stack stores frames.It holds local variables and partial results, and plays a part in method invocation and return.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec4e6706-3c67-4dbd-8852-b85d3de2e046', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle ''TOAST'' (The Oversized-Attribute Storage Technique), and when is it triggered?', N'Senior', N'TOAST automatically moves large attribute values into separate storage tables when a row exceeds a specific size threshold, typically 2KB. This allows PostgreSQL to keep rows compact and efficient for the primary storage, only retrieving the large data when explicitly accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b39045a-2902-4bb2-9b93-b86270f144f8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of middleware in Litestar?', N'Fresher', N'Middleware in Litestar acts as a bridge between the client and the application, allowing you to process incoming requests or outgoing responses. It is used for tasks like logging, authentication, or modifying headers globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5ca09c6-e20b-4764-a95e-b863e7a35711', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What happens when a user visits an Astro page?', N'Intern', N'When a user visits a page, the server sends the pre-rendered HTML to the browser for instant viewing. If there are interactive components, the browser only downloads the specific JavaScript required for those parts of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c975c60-ee79-4a27-b42e-b864cbbf9c98', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How would you implement graceful shutdown in an Express application to ensure no requests are dropped?', N'Senior', N'Graceful shutdown is achieved by listening for termination signals like SIGTERM, stopping the server from accepting new connections while allowing existing requests to finish processing. Once all active connections are closed or a timeout is reached, the process can safely exit, ensuring data consistency and preventing aborted transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ef31633-96bd-4942-9b73-b864e414fec5', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a database association in Rails?', N'Intern', N'An association is a connection between two Active Record models that simplifies common operations. It allows you to express relationships such as one-to-one, one-to-many, or many-to-many, enabling easy navigation between related data records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c16a6775-4637-44b9-9a74-b8654b9786af', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Compare and contrast the performance implications of Scala''s ''Future'' versus the newer ''IO'' monads found in libraries like Cats Effect.', N'Senior', N'Scala Futures are ''eager'' and begin execution immediately upon creation, which can lead to non-deterministic side effects and resource exhaustion under load. IO monads are ''lazy'' and represent a description of a computation that is only executed by a runtime system, providing better control over resource management, cancellation, and thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65819f42-9030-4d92-b714-b86648698a13', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s middleware chain implementation differ from standard Go net/http handlers?', N'Middle', N'Echo uses a specialized Middleware interface that wraps the HandlerFunc, allowing it to execute code before and after the main request handler. This chain-of-responsibility pattern enables clean composition of cross-cutting concerns like logging, recovery, and authentication without cluttering the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a414a8d-3145-4ae2-a649-b8666d785ebd', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart handle concurrency?', N'Intern', N'Dart uses an event loop architecture combined with isolates. An isolate is an independent worker that does not share memory with other isolates, communicating instead through message passing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f4b556a-0fc3-446e-b8c4-b867936924f9', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is it difficult to learn Tailwind if I already know CSS?', N'Intern', N'If you know CSS, Tailwind is generally easy to learn because the utility classes map directly to standard CSS properties. The main learning curve is simply memorizing the class naming conventions and how to structure them efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2f7880a-9896-403f-86e0-b869c22d40e8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the primary architectural style that Litestar is designed to support?', N'Junior', N'Litestar is primarily designed for building RESTful APIs. It provides a robust, type-hinted framework that simplifies the creation of web services that follow standard HTTP conventions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76673811-4a14-4679-a909-b86ac597eb6f', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of ''Write Amplification'' in the context of LSM-trees versus B-trees.', N'Senior', N'B-trees suffer from write amplification because updating a single value may require rewriting entire pages to maintain structural balance. LSM-trees mitigate this by converting random writes into sequential appends, though they pay a price in read amplification as the system must search multiple levels of the structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7751f8f3-1470-4d14-b534-b86f2a8be694', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between SAGA patterns and Two-Phase Commit (2PC) in distributed transactions?', N'Senior', N'2PC provides strong consistency by locking resources across distributed systems but risks significant latency and availability issues during coordinator failure. SAGA maintains eventual consistency by executing a sequence of local transactions with compensating logic to roll back changes, offering higher availability and scalability at the cost of immediate consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
