INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'162dd04b-3c92-4412-bf1a-b88837f5b72c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between an entry point and an output point?', N'Junior', N'The entry point is the starting file where Webpack begins the bundling process, while the output point is the destination folder where the final processed files are saved. One is the source of truth for the dependency graph, and the other is the result of the compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5037c974-0936-421d-a225-b88a51d9fea9', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of denormalization in NoSQL?', N'Junior', N'Denormalization involves intentionally duplicating data across multiple records to reduce the need for complex joins. This practice improves read performance and scalability, which is critical for distributed NoSQL architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'500415aa-8872-4bf0-850f-b88cd7fb9798', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the benefit of ''Span<T>'' and ''Memory<T>'' for memory management?', N'Senior', N'These types provide a type-safe, performant window into contiguous memory without requiring heap allocations or copying. Span is a stack-only type that allows for efficient slicing of arrays, strings, or unmanaged memory. This significantly reduces memory pressure in performance-critical parsing or data-processing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5fe55c8-2196-464d-ab88-b88e7a476142', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Does Cassandra support JOIN operations?', N'Fresher', N'No, Cassandra does not support JOIN operations. Because the data is distributed across multiple nodes, joining tables would require expensive network communication, which contradicts Cassandra''s design goal of extreme performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'375313eb-5cc5-48e3-b7ef-b8904df47327', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you define a route in Rails?', N'Fresher', N'In Ruby on Rails, routes define how an HTTP request is processed, matching it to a controller action. Components 1. HTTP Verb: The action (GET, POST, PUT, DELETE) that triggers the route. 2. Path: The URL that the matching request accesses. 3. Controller#Action: Specifies the controller and its method to handle the request. Syntax Here is how to define the route: - Simple Route: Uses the match method to map a path to a specific controller and action. - Ruby on Rails 3.0 and above - Ruby on Rails 4.0 and above - Resource Routes: Utilizes a RESTful interface to define multiple routes for a resource. - Redirect: Sends a 301 or 302 HTTP status code and a URL to redirect the request to. - Non-Resourceful Routes: For custom actions that do not fit REST conventions, use the add_route method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26952816-f379-4621-8f1b-b892f256026d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why would an architect choose ''Serverless'' functions over traditional containerized services?', N'Senior', N'Serverless functions offer rapid scaling and cost efficiency for event-driven or sporadic workloads because you only pay for execution time. However, they introduce challenges like cold starts, vendor lock-in, and limited control over the underlying runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'503c9180-5076-4581-87a7-b893cc287e73', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you verify if a database query is the cause of a slow page load?', N'Junior', N'I would use database profiling tools to measure the execution time of the query and check if it is missing appropriate indexes. If the query takes a long time to run in isolation compared to the application response time, it is likely the bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f1296bb-9233-4137-8ab7-b8947478c952', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the architectural implications of Kotlin''s platform types when consuming Java APIs.', N'Senior', N'Platform types represent a lack of nullability information from Java, essentially creating a ''trust me'' contract where the compiler disables null safety checks. This forces developers to manage potential runtime null pointer exceptions manually, creating a significant point of failure that requires rigorous validation or defensive wrapping at the boundaries of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a947b7a-2ce1-4caf-b0e5-b89479fc8a93', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the benefit of using ''canary deployments'' when troubleshooting potential production regressions?', N'Middle', N'Canary deployments allow you to expose a small subset of traffic to the new version, making it easier to isolate errors to specific instances without impacting the entire user base. This limits the blast radius of a bug and provides a controlled environment to verify stability before a full rollout.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40027f0a-06b0-42dd-8ebb-b895184c92be', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass''s type system handle complex data validation?', N'Senior', N'Sass includes built-in functions like type-of() that allow developers to check the data type of variables before processing them. This is critical when writing robust mixins or functions that need to handle varying input types, such as numbers with or without units, to prevent runtime compilation errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1580ddd-3e70-4bf5-9415-b89624076a7b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is ''prop drilling'' and how can it be mitigated?', N'Middle', N'Prop drilling occurs when data is passed through multiple layers of components that do not need the data themselves, just to reach a deeply nested child. It can be mitigated by using the Context API, composition patterns, or state management libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46cb3ab7-d991-4610-9cf6-b8964d04b551', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the advantage of using ''IntoResponse'' in Axum?', N'Middle', N'The IntoResponse trait allows handlers to return various types—such as tuples, strings, or custom structs—that are automatically converted into HTTP responses. This flexibility simplifies API design by allowing developers to return domain objects directly rather than manually constructing response objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b90626d-b4de-47e8-a525-b8985943ea2a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a friend function in C++?', N'Junior', N'A friend function is a non-member function that is granted access to the private and protected members of a specific class. It is used when an external function needs to interact closely with the internal implementation of a class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7cd37a6-8a7a-4031-bf35-b899370fb4b8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the main benefit of using Pattern Matching over if-else statements?', N'Middle', N'Pattern matching is more declarative and readable, allowing for complex data decomposition and structural analysis in a single construct. It is also safer due to compiler-enforced exhaustiveness checks when used with sealed hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32fcc6cc-8264-43ae-a767-b899e6d486fa', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How can you leverage Fastify''s schema validation to improve security and performance?', N'Senior', N'By defining AJV-based schemas for all inputs, Fastify rejects malformed requests before they reach the route handler, preventing potential injection attacks and invalid state processing. This also allows the framework to optimize serialization, as it already knows the structure of the data it is handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94921faf-5b2e-4161-8c15-b89cf592f26b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the difference between x-on and event modifiers?', N'Junior', N'While x-on handles the event, modifiers such as .prevent or .stop are appended to the directive to perform common tasks like stopping event propagation or preventing the default browser behavior of form submissions. They act as shorthand for calling those methods inside the handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fae23f9f-fcfb-40ec-9d5c-b89d435330f9', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS leverage the IoC container to achieve decoupling in large-scale applications?', N'Senior', N'The IoC container acts as a centralized registry for dependencies, allowing components to be injected rather than instantiated manually. This promotes loose coupling and simplifies unit testing by allowing developers to swap real implementations with mocks or stubs during the testing phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb8e1eb6-7a14-4267-8e46-b89e82f85aec', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is it possible to use Tailwind CSS variables for theming?', N'Fresher', N'Yes, Tailwind integrates well with CSS variables, allowing you to define dynamic colors or spacing values. You can reference these variables in your configuration file to create a flexible, themeable design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc478db4-bfb6-4254-b2eb-b8a04b0d9ec9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-offs between observability (logging, metrics, tracing) and system performance?', N'Senior', N'I use sampling for high-volume tracing and aggregate metrics to keep overhead minimal while maintaining visibility. While instrumentation consumes CPU and memory, the cost of not being able to diagnose production outages is significantly higher, so I prioritize performance-efficient monitoring agents that provide actionable insights.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00d28ced-bb70-4dd6-b065-b8a5037231c5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of Vite''s CSS code-splitting?', N'Middle', N'Vite automatically extracts CSS imported in asynchronous chunks into separate files. This ensures that the browser only loads the CSS required for the current view, improving initial load performance by reducing the total amount of unused CSS delivered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aa0ff44-0047-4ed6-8a59-b8a558238f5a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the significance of the ACID properties in database management?', N'Middle', N'ACID properties ensure that database transactions are processed reliably, maintaining data validity even in the event of errors or system failures. Atomicity, Consistency, Isolation, and Durability together guarantee that transactions are treated as a single unit of work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8598d2cb-c8c1-4f11-b70c-b8a59a92ebf2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a type guard?', N'Intern', N'A type guard is a technique used to narrow down the type of a variable within a conditional block. It involves an expression that performs a runtime check which guarantees the type in a specific scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5b95d67-86db-458c-be47-b8a6a30234a2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you differentiate between a network-level issue and an application-level bottleneck in a microservices architecture?', N'Senior', N'I would compare the service-to-service latency metrics from the service mesh or ingress controller against internal application processing time metrics. If the latency exists outside the application layer, it points toward network congestion or DNS resolution delays; if the internal metrics show high processing time, the issue is likely within the application logic or database layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77601162-0743-4f87-95ab-b8aa5d7fa6fe', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the role of past experience when estimating a new project, and how do you use it?', N'Fresher', N'Past experience provides a historical baseline for how long similar tasks typically take, which helps in calibrating new estimates. I use it by comparing the current requirements to previous work, noting the differences in complexity and scope. However, I remain cautious to adjust for new factors or technologies that might change the outcome.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46ffec88-e690-4565-8109-b8ab51df799b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the ''splitProps'' utility?', N'Fresher', N'The splitProps utility is used to divide a props object into multiple smaller objects. This is useful for passing specific parts of the props to different child components while maintaining reactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6890ccb3-76c7-4aa9-9a0c-b8ac58a57620', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS media queries interact with resource loading, and what is the ''Media Query List'' optimization?', N'Senior', N'Media queries dictate whether the browser downloads a linked stylesheet; if the condition is not met, the browser may still download the file but with a lower priority. Modern browsers are optimized to only render the CSS that matches the current viewport, but developers should still use media-specific loading to avoid unnecessary network overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4ea3a9f-0e9c-44db-87bc-b8b0efd66d26', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle code-splitting for different routes?', N'Senior', N'SvelteKit automatically performs code-splitting at the route level, ensuring that only the JavaScript required for the current page is sent to the client. This reduces the time-to-interactive metric significantly, as users do not download the entire application bundle upfront.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7acba72-4cc1-4731-a5fd-b8b567e54d73', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are default interface methods?', N'Intern', N'Java 8 allows you to add non-abstract method implementations to an interface using the keyword default: * If a class implements an interface, it can, but does not have to, implement the default methods already implemented in the * interface. The class inherits the default implementation. * If a class implements several interfaces that have the same default method, then the class must implement the method with the same signature on its own. The situation is similar if one interface has a default method, and in the other the same method is abstract - no class default implementation is inherited. * The default method cannot override the class method java.lang.Object. * They help implement interfaces without fear of disrupting other classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ecf2fc6-f009-4e5d-a7d9-b8b5aadd064d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle panics within a request handler?', N'Middle', N'Gin provides a built-in Recovery middleware that catches any panics occurring during the request lifecycle. It prevents the server from crashing by logging the error and returning a 500 Internal Server Error status to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef83f53-36ac-4955-b998-b8b8e1fb1903', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between a route handler and a hook?', N'Intern', N'A route handler is the primary function that processes the business logic for a specific URL and HTTP method. A hook, on the other hand, is a function that runs at specific lifecycle stages, such as before or after the handler, to perform tasks like logging or authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd36299d-20f7-42fa-94c8-b8b9968a3565', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is an app in Django?', N'Intern', N'An app is a self-contained module that does something specific, such as a blog system, a user registration system, or a public record database. The design philosophy of Django encourages modularity by allowing you to plug and play these apps within a project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf0f757a-e50f-46d5-9e53-b8ba14ef2047', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In a scenario where you must choose between consistency and availability, how do you decide?', N'Fresher', N'This depends on the business requirements; if it is a financial system, consistency is non-negotiable even if the system becomes temporarily unavailable. If it is a social media feed, availability is usually prioritized so users can always see content, even if it is slightly outdated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'127d7d49-069f-447d-819c-b8bb1bdb9462', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of innerHTML?', N'Intern', N'The innerHtml is a property of HTML-Elements, which allows you to set it''s html-content programmatically. Let''s display the below html code snippet in a tag as below using innerHTML binding, and define the htmlSnippet property from any component Unfortunately this property could cause Cross Site Scripting (XSS) security bugs when improperly handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3435b03d-0036-4f88-a8c8-b8bb496a8bc4', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does read-replication address performance bottlenecks in read-heavy applications?', N'Senior', N'Read-replication offloads read traffic from the primary node to multiple secondary nodes, allowing the primary to focus exclusively on write operations. This architecture scales read throughput linearly with the number of replicas, though it introduces eventual consistency concerns for application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46ed331a-696a-4269-a377-b8c3a4b95ce1', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the benefit of using a CSS preprocessor like Sass or Less?', N'Middle', N'CSS preprocessors extend the functionality of standard CSS by adding features like nesting, mixins, functions, and mathematical operations. These features allow for cleaner, modular code that is easier to manage, although the final output must still be compiled back into standard CSS for the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39abdf82-fcd4-497a-80fb-b8c5c365f4e5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''infer'' keyword in conditional types?', N'Middle', N'The ''infer'' keyword is used within a conditional type to declare a type variable that can be extracted from another type. It is commonly used to extract the return type of a function or the element type of an array. It allows you to ''look inside'' complex types and reuse parts of them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1528799-da69-41de-9e23-b8c67f258edc', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the role of the C runtime (CRT) startup code before ''main'' is executed.', N'Senior', N'The CRT startup code initializes the execution environment, including setting up the stack, initializing global variables, and preparing the heap. It also handles the command-line argument vector processing and environment variable setup before passing control to the user-defined entry point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ada8aa3b-84f9-4066-a959-b8c6a0533b50', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between provisioned and on-demand capacity mode?', N'Intern', N'Provisioned mode requires you to specify the number of reads and writes per second you expect your application to perform. On-demand mode automatically scales capacity to accommodate your application''s traffic without requiring manual configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fed16419-6e37-4a44-bde8-b8ca5f634107', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the trade-offs of using generators versus standard list comprehensions for large datasets.', N'Senior', N'Generators provide lazy evaluation, yielding items one at a time, which significantly reduces memory footprint when handling massive datasets. List comprehensions, conversely, allocate the entire result set in memory, offering better performance for smaller datasets due to reduced overhead from context switching and repeated function calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
