INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de17a5d3-41e0-4471-b2b6-b8df995224e2', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the Service Container in Laravel and why is it useful?', N'Middle', N'The Service Container is a powerful tool for managing class dependencies and performing dependency injection. It allows for loose coupling between components by resolving classes at runtime, making the application easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f7f618a-ad75-4d25-a2cb-b8e037664aa9', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the ''final'' keyword when applied to classes, methods, and variables?', N'Middle', N'The final keyword acts as a modifier to restrict mutation and inheritance. A final class cannot be subclassed, a final method cannot be overridden, and a final variable cannot have its reference reassigned once initialized. It is essential for creating immutable objects and protecting the structural integrity of critical API components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da29e037-4cd0-487d-b444-b8e31cb07a08', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Can you use Sass to create conditional logic?', N'Fresher', N'Yes, Sass supports conditional logic through @if, @else if, and @else directives. This allows you to apply styles dynamically based on specific conditions or configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8a32369-f2f0-4484-abf2-b8e325b27575', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''symbols table'' in the Zend engine and how is it managed?', N'Senior', N'The symbol table is a hash map that maps variable names to their corresponding ZVAL structures. PHP maintains a global symbol table for the main scope and local symbol tables for each function or method call, which are destroyed upon function return to facilitate cleanup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1bdc403-b8af-47b6-9124-b8e4080541b3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary difference between jQuery''s data method and using the HTML5 data-attributes API?', N'Middle', N'The jQuery data method stores information internally within a JavaScript object linked to the DOM element in memory, allowing for storage of complex data types. The native data-attributes API reads and writes directly to the DOM as string attributes, which is slower for frequent updates and limited to simple primitive values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8395f830-0bfb-47e9-8df0-b8e9a2ecea80', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'In the context of modern frontend architecture, why is jQuery considered a library rather than a framework?', N'Middle', N'jQuery is a library because it provides a set of utility functions for DOM manipulation and AJAX without enforcing a specific architectural pattern. A framework, by contrast, dictates the structure of the application and handles data flow and component lifecycle, which jQuery does not do.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8be6bd1e-eac4-4b22-a111-b8e9d8d7d175', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is ''Clone'' required for services in Tower and Axum?', N'Senior', N'In Tower, services are often cloned to create new instances for concurrent requests or to satisfy trait bounds required by middleware stacks. Since Axum handlers are converted into services, the underlying data must be clonable to ensure that the framework can spawn the necessary resources to handle high-concurrency requests independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'916ca987-8fdc-43ad-980a-b8eb3a13a986', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the COMMIT command?', N'Fresher', N'The COMMIT command is used to permanently save the changes made during the current transaction to the database. Once committed, the changes become visible to other database users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f15aef0-c94e-42a7-852c-b8eb7730a622', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the role of the App Router''s ''server components'' compared to ''client components''.', N'Middle', N'Server components execute exclusively on the server, allowing direct database access and reducing the amount of JavaScript sent to the client. Client components are rendered on the client after an initial server render, enabling interactivity through hooks and browser-specific APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9381a728-f084-4295-bbd5-b8eba997ab03', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust prefer ''Result'' and ''Option'' over exceptions?', N'Middle', N'Using ''Result'' and ''Option'' makes error handling and absence of values explicit in the type system. This forces developers to handle these cases at compile time, leading to more robust and predictable code compared to stack-unwinding exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'399d5293-17e2-4521-8662-b8ec45040442', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of ''template literal types''?', N'Middle', N'Template literal types allow you to construct complex string types by interpolating smaller string types. They are particularly useful for creating highly specific API endpoints, event names, or localized string patterns with type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e66fcad3-71f5-4d92-8048-b8ee703c9ebd', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Why is it important to consider scalability when designing a system?', N'Intern', N'Scalability ensures that a system can handle increased demand without requiring a complete redesign. Designing for growth from the start prevents future bottlenecks and technical debt that could crash the system as user volume rises. It is a proactive approach to long-term stability and success.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6f4f707-f4de-4cfd-ac4c-b8eec1fb0531', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the role of the Saga pattern in distributed transactions.', N'Senior', N'The Saga pattern manages distributed transactions by breaking them into a sequence of local transactions, each with an associated compensating action. It maintains data integrity across microservices by executing these compensations if any step in the sequence fails, effectively managing long-lived transactions without two-phase commit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d8e4e47-b3da-4338-9bf5-b8f3b5898f28', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of BFC (Block Formatting Context) and when it is triggered.', N'Middle', N'A BFC is an isolated region in a web page where block-level elements are laid out independently of the rest of the page. It is triggered by properties such as overflow other than visible, floats, or display types like flex and grid, and it effectively prevents margin collapse and clears floats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'728b500e-e6eb-42d8-b151-b8f7bd9d8c08', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is Lit HTML?', N'Fresher', N'Lit-html is the templating library used by Lit to efficiently render HTML. It uses tagged template literals to create dynamic content, updating only the specific parts of the DOM that have changed instead of re-rendering the entire template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'283acea4-dafb-4cac-b2d6-b8f89f369d67', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the trade-off between consistency and availability in a distributed database?', N'Middle', N'Following the CAP theorem, if the system requires strict data accuracy for financial operations, I prioritize consistency over availability. If the system is user-facing content where temporary staleness is acceptable, I prioritize availability to ensure the platform remains responsive under network partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f890106b-3bcd-4ddd-8ed1-b8f93fe8a0e1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of a Module in NestJS?', N'Intern', N'A module is a class annotated with the @Module decorator. It helps organize application structure by grouping related components, controllers, and providers together, making the code more maintainable and modular.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba0090e1-9e4a-45af-8ac4-b8fe43ba1709', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of a bulkhead pattern in system architecture?', N'Middle', N'The bulkhead pattern isolates elements of an application into pools so that if one fails, the others continue to function. It prevents a single service''s resource exhaustion from impacting the entire system''s availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00038691-cc30-4d64-b04f-b8ffc5d3e51d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''Any'' vs ''Unknown'' trade-off in terms of type safety and API design?', N'Senior', N'Using ''any'' disables the type checker, essentially opting out of safety, which often leads to runtime exceptions. ''Unknown'' forces the developer to perform type checking or narrowing before interacting with the value, providing a safe bridge for untrusted data like API responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f3f49a0-68bc-499e-b9d5-b8ffdaae3092', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you prioritize your tasks when you have multiple conflicting deadlines?', N'Junior', N'I check the project requirements and business impact with my lead to understand which tasks are critical. I focus on delivering the highest value items first while keeping stakeholders informed about the timeline for the remaining tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
