INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'414617b3-3310-4a37-a0cc-b903edac6144', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle the trade-off between server-side execution and client-side interactivity?', N'Senior', N'Remix uses a hybrid approach where server-side loaders handle the initial state and data fetching, while client-side hydration provides interactivity. By favoring server-side primitives for core functionality, it ensures a resilient experience while maintaining the performance benefits of a Single Page Application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74501287-83bb-471a-8dc6-b905b3caabda', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between the .html() and .text() methods?', N'Fresher', N'The .html() method gets or sets the inner HTML content of an element, including any nested tags, while the .text() method only retrieves or sets the text content. Using .text() is safer when you want to treat input as plain text rather than markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6408e49c-0cff-48e8-b864-b908863cb690', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the Spring Framework and what are its core features?', N'Intern', N'The Spring Framework is a comprehensive software platform that provides infrastructure support for developing enterprise-level applications. It''s known for its robust features that simplify complex tasks and for its support of best coding practices. Core Features 1. Inversion of Control (IoC): Centralized bean management ensures loose coupling leading to easy maintenance and testing. 2. Aspect-Oriented Programming (AOP): Modularizes cross-cutting concerns such as logging and caching, promoting reusability. 3. Validation and Data Binding: Offers powerful validation and data binding mechanisms compatible with JavaBeans components, thereby ensuring data integrity. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8be3430-8b1e-4c20-9834-b909151667f6', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How can you resolve paths to project folders in Vite without long relative imports?', N'Junior', N'You can use path aliases in your configuration file, typically mapping a symbol like ''@'' to the ''src'' directory. This allows you to import files using absolute-style paths regardless of your current file''s depth in the folder structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfbd56e1-9027-4f3c-a8b9-b90b135e837e', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does lazy evaluation work in R function arguments?', N'Middle', N'Lazy evaluation means that arguments to a function are only evaluated when they are actually used inside the function body. This allows for conditional execution of arguments and the creation of custom control structures that do not evaluate expressions unless necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a94c997-f52a-4185-85ab-b90b4dfac0f7', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the importance of logging in an application?', N'Fresher', N'Logging provides a historical record of what the application was doing at any given time, which is essential for diagnosing issues after they occur. Without logs, it is nearly impossible to track down the root cause of intermittent errors or unexpected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3c0c3db-2f64-4a6f-a231-b90c6cab1652', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Discuss the performance implications of NestJS''s reflection-based metadata system in a production environment.', N'Senior', N'Reflection-based metadata is computed primarily during the application bootstrap phase, resulting in negligible runtime overhead for subsequent requests. However, in extremely large applications with thousands of decorators, the initialization time might increase, necessitating a strategy to optimize module loading or use ahead-of-time compilation techniques if available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1c7edfd-cf09-4a82-8187-b90fa07397d6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the mechanism of Flask''s request teardown process and its importance in resource cleanup.', N'Senior', N'Teardown functions are executed regardless of whether the request succeeded or raised an exception, making them ideal for closing database connections or cleaning up temporary resources. By hooking into the request lifecycle, it ensures that external resources are released deterministically, preventing connection pool exhaustion and memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd17c31e6-f558-4414-9433-b91200a23b61', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of any type cast function?', N'Intern', N'You can disable binding expression type checking using $any() type cast function(by surrounding the expression). In the following example, the error Property contacts does not exist is suppressed by casting user to the any type. The $any() cast function also works with this to allow access to undeclared members of the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6629773f-0812-4840-a8cc-b913a23c2b46', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle type hints?', N'Fresher', N'FastAPI uses standard Python type hints to declare parameters and return types. It leverages these hints to perform automatic data conversion, validation, and to generate the interactive API documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2da71b95-0c20-47ea-822b-b913f9b502f5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the impact of minification on the final bundle?', N'Junior', N'Minification is the process of removing unnecessary characters, such as whitespace and comments, and shortening variable names without changing the functionality. This significantly reduces the file size, which leads to faster download times for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a81946d7-ae2a-4311-8ea3-b91637e87c66', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the significance of Tailwind''s ''variants'' and how they handle pseudo-classes.', N'Senior', N'Variants allow utilities to be conditionally applied based on states like hover, focus, or media features. By standardizing these as prefixes, Tailwind ensures a consistent syntax for complex UI states, keeping the CSS output structured and predictable compared to writing manual media queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf520cb5-1cea-4cee-9650-b9163d63194b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the EventDispatcher component?', N'Junior', N'The EventDispatcher allows different parts of the application to communicate without being tightly coupled. One part of the code can dispatch an event, and other parts can listen for that event to perform additional actions, such as logging or sending emails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50043b0c-3065-4802-b443-b9165df8caa9', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is it generally recommended to avoid ''Select *'' in production applications?', N'Middle', N'Using ''Select *'' retrieves all columns, which increases network bandwidth usage and memory consumption. It also prevents the database from using covering indexes and can break application code if the table schema changes, such as adding a large text column.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbf08477-f712-4214-abf1-b9189d7dd394', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Tail Latency'' amplification occur in microservices architectures?', N'Senior', N'Tail latency amplification occurs because a single user request often fans out to multiple downstream dependencies. If any single service in the dependency tree experiences a latency spike, the entire request''s response time is gated by that slowest path, causing the P99 latency of the aggregate request to be significantly higher than individual service latencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b649f3f-be37-443f-bc9f-b91e8dde4ef4', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the @SpringBootApplication annotation?', N'Intern', N'This annotation is used to mark the main class of a Spring Boot application. It combines @Configuration, @EnableAutoConfiguration, and @ComponentScan, which together enable auto-configuration, component scanning, and define the class as a source of bean definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e73e2013-9e23-46eb-aae2-b91f8dbe4b18', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of ''call()'' in a Dart class?', N'Middle', N'If a class implements a call method, its instances can be invoked as if they were functions. This allows for the creation of callable objects that can maintain internal state while providing a clean and concise function-like API for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d4a8c2e-9516-4d42-970c-b91ff46c771d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the Sass compiler handle ''silent'' classes, and what is their primary use case in large-scale architecture?', N'Senior', N'Silent classes, defined with a percent sign, are not compiled into CSS until they are explicitly extended. They are highly effective for defining abstract base styles that should not occupy space in the final stylesheet unless specifically applied, helping to keep the CSS payload lean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'346e0c37-c59c-4ab4-a3df-b9202a4b61ca', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the role of distributed tracing in debugging asynchronous microservices architectures.', N'Senior', N'Distributed tracing injects correlation IDs into request headers, allowing you to reconstruct the entire call graph across service boundaries. This is critical for identifying latency bottlenecks and logical errors in event-driven systems where traditional logs are fragmented and lack temporal context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
