INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'246d903d-1016-4f58-a99b-b92b5b5561f1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you decide between a Normalized (3NF) and Denormalized schema for a high-scale system?', N'Senior', N'Normalization is preferred for write-heavy systems to maintain data integrity and avoid update anomalies. Denormalization is chosen for read-heavy systems to minimize expensive join operations and improve latency, despite the risk of data inconsistency and increased storage overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
