INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a8f3c45-0f85-4cda-a817-b92ee16f8f54', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the primary constraint imposed by Python''s ''LEGB'' scope rule?', N'Senior', N'The LEGB (Local, Enclosing, Global, Built-in) rule defines the order in which the interpreter searches for variable names. This hierarchy ensures that inner scopes have access to outer variables, but modifications to outer variables require explicit keywords like ''global'' or ''nonlocal'' to prevent accidental shadowing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a65e227-878f-439e-8e62-b92fae16d1a1', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are ''mounted'' apps in Express?', N'Junior', N'Mounting occurs when you use app.use() to attach a secondary Express application or router to a specific path in the main application. This helps keep code organized by separating different domains of the application into their own distinct modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
