INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4710ca6d-c8a1-4716-80b3-b93595c64102', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the core architectural difference between Qwik''s resumability and traditional hydration?', N'Senior', N'Traditional hydration requires downloading, parsing, and executing the entire component tree to attach event listeners, which is computationally expensive. Qwik achieves resumability by serializing the application state and event handlers into HTML, allowing the framework to resume execution only when a specific user interaction occurs without re-executing existing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18f88801-86a6-4c07-9f3a-b9363490b9c8', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask-SQLAlchemy and why is it commonly used?', N'Junior', N'Flask-SQLAlchemy is an extension that adds support for the SQLAlchemy ORM to Flask applications. It simplifies database interactions by allowing developers to manage database records using Python classes instead of writing raw SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'673afae7-3bbb-4b35-9731-b939a7f6491d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a channel in Go and why is it used?', N'Fresher', N'A channel is a communication pipe that allows goroutines to send and receive values to and from each other. It provides a synchronized way to share data between concurrent processes, effectively preventing race conditions without the need for complex explicit locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e590205-8af6-4a04-bf0d-b93b49d1a7ae', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the volatile keyword important in C?', N'Middle', N'The volatile keyword informs the compiler that a variable''s value may change at any time due to external factors, such as hardware or interrupt service routines. It prevents the compiler from performing optimizations like caching the value in a register, ensuring every read or write operation actually accesses the memory location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'828702fa-cf13-4a60-8df0-b93d22e1a842', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the performance impact of branch misprediction on tight loops.', N'Senior', N'Branch misprediction occurs when the CPU''s speculative execution unit guesses a conditional branch incorrectly, forcing the pipeline to be flushed and restarted. In tight loops, frequent mispredictions significantly degrade performance, leading developers to use branchless programming techniques like conditional moves or data-driven designs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'651e82c6-5f7f-4e08-b889-b93d542b71f4', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the try-with-resources statement?', N'Middle', N'Introduced in Java 7, it ensures that each resource, such as a file or socket, is closed automatically at the end of the statement. This prevents resource leaks and simplifies code by removing the need for verbose finally blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9068423c-d33e-44a1-ae8d-b93dbe5f2ad6', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the benefit of using Fastify''s plugin system for database connections?', N'Junior', N'By registering a database connection as a plugin, you ensure that the connection is initialized correctly and shared across parts of the application. It also ensures the connection is properly closed when the server shuts down.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9495c5fc-4004-4623-beca-b93fabc1669d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle externalized configuration, and what is the order of precedence?', N'Middle', N'Spring Boot supports various sources like property files, environment variables, and command-line arguments. The order of precedence is strict, where command-line arguments take the highest priority, followed by environment variables, and finally application.properties or .yml files, allowing for easy environment-specific overrides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea597e81-7476-4e5b-b233-b94219040278', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''seeds.rb'' file?', N'Junior', N'The seeds file is used to populate your database with initial data required for the application to function. This is commonly used for creating default admin users, lookup tables, or sample data for development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16d89e28-a01d-490a-8c43-b9421cdbe603', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the advantage of using @content in a mixin?', N'Middle', N'The @content directive allows you to pass a block of custom CSS into a mixin, which is then injected wherever the directive is placed. This is highly effective for creating wrapper mixins, such as those that handle media queries or browser-specific feature detection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'341264e7-ee82-4bfc-8749-b945bd025508', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the significance of the ''virtual'' keyword in inheritance?', N'Fresher', N'The virtual keyword is used to enable polymorphism by allowing a base class pointer or reference to call the appropriate overridden function in a derived class. It ensures that the function call is resolved at runtime based on the actual type of the object rather than the pointer type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caac4cc2-f29e-40fe-8214-b94740a36454', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using third-party libraries versus building custom solutions?', N'Fresher', N'Third-party libraries save development time and benefit from community testing. However, they add external dependencies and may limit control, while custom solutions provide full control but require significant time for development and maintenance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb2f433-9705-4da1-b498-b94784b8d96e', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If asked to estimate the number of piano tuners in a city, what is your logical reasoning process?', N'Fresher', N'I would start by estimating the population of the city and then calculate the number of households likely to own a piano. Then, I would estimate how often a piano needs tuning and how many pianos a single tuner can service in a day. By multiplying these figures, I can derive a reasonable estimate of the total number of tuners needed to support that demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6fd9572-3619-4272-9b81-b948de5fc02b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is NumPy? Is it better than a list?', N'Intern', N'Python Programming Interview Questions - Numpy vs List Python Programming Interview Questions – Numpy vs List Ans. NumPy, a Python package, has made its place in the world of scientific computing. It can deal with large data sizes, and also has a powerful N-dimensional array object along with a set of advanced functions. Yes, a NumPy array is better than a Python list. This is in the following ways: It is more compact. It is more convenient. It Is more efficiently. It is easier to read and write items with NumPy. Read our latest tutorial on Python NumPy', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abd4ed85-fd7b-40a0-967b-b949209163ce', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does chi handle path wildcards?', N'Junior', N'Chi supports wildcard routing using the asterisk character, which allows a single route to match a variety of sub-paths. This is useful for scenarios like serving static files from a directory or creating catch-all routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aa92688-f49c-4c89-9fc2-b949b8e69198', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a ''memory fence'' or ''memory barrier'' in concurrent programming?', N'Middle', N'A memory fence is a synchronization primitive that enforces an ordering constraint on memory operations. It prevents the compiler and the CPU from reordering read and write instructions across the barrier, ensuring that threads observe memory updates in the intended sequence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b99f7974-511a-495c-a51c-b94d4143a16d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you define reactive state in Svelte?', N'Junior', N'You define reactive state by simply declaring variables using standard JavaScript let statements within the script tag. Svelte automatically tracks these variables and updates the DOM whenever their values are reassigned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc72e999-7238-4bb5-ae76-b94d882dfa18', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of ''Rails Engines''?', N'Middle', N'Rails Engines allow developers to package a mini-application that provides its own routes, controllers, and models. They are ideal for extracting shared functionality, such as authentication systems or administrative dashboards, into a reusable, modular component that can be shared across multiple Rails projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e439b788-0a1f-4f19-8770-b94fa205f4fb', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the function of the ''Memtable'' in the write path.', N'Senior', N'The memtable is an in-memory structure that buffers incoming writes. Once it reaches a specific size threshold, its contents are sorted and flushed to disk as an immutable SSTable, which allows for efficient data persistence while maintaining high write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f97250c6-8225-4fcc-9a04-b95c9166b47d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to use constructor functions for inheritance in JavaScript?', N'Fresher', N'Let say we have Person class which has name, age, salary properties and incrementSalary() method. Now we wish to create Employee class which contains all the properties of Person class and wanted to add some additional properties into Employee class. In the example above, Employee type inherits from Person. It does so by assigning a new instance of Person to Employee prototype. After that, every instance of Employee inherits its properties and methods from Person. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ebf9b5-8ff1-42a0-96c8-b95d43ec4d47', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is reactivity in Svelte?', N'Intern', N'Reactivity in Svelte refers to the ability of the framework to automatically update the DOM whenever the state of a component changes. This is achieved through simple variable assignments, which the compiler tracks and links to specific DOM elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a9a9171-59f6-4fd4-98f4-b95d4f55dda8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'In what scenario would you choose Redux over React Context?', N'Middle', N'Redux is preferred when the application has complex state logic, frequent updates, or requires advanced debugging tools. Context API is usually sufficient for simple state sharing, but it lacks the middleware ecosystem and performance optimization tools that Redux provides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24e94113-8be8-4c72-9292-b95daa1d41ac', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are jQuery effects and how are they used?', N'Junior', N'jQuery effects are built-in methods that animate the appearance or visibility of elements, such as fading, sliding, or showing/hiding. They simplify the process of creating smooth user interface transitions that would otherwise require complex CSS keyframes or manual JavaScript timers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b7bbebe-beec-4f2c-94fd-b95f829cc3ac', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Strangler Fig'' pattern?', N'Middle', N'This pattern is used to migrate a legacy monolith to microservices by incrementally replacing specific functionalities with new services. Over time, the new services ''strangle'' the monolith until it can be decommissioned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c05e390-c40b-452f-bd6e-b9623eecbc1f', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to selecting a primary key strategy for a distributed database?', N'Middle', N'I evaluate requirements for sortability, collision probability, and privacy. Sequential IDs are easy to index but can reveal system usage; UUIDs offer uniqueness without coordination but can impact index performance due to fragmentation. A distributed ID generator like Snowflake is often the best balance for high-scale environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9adcd6c4-6a37-484a-a82e-b967b53ec0d9', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Can you have multiple extractors in a single Axum handler?', N'Fresher', N'Yes, you can include multiple extractors as arguments in a handler function. Axum will attempt to run each one, and if any extractor fails, the request will be rejected with an error response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d53a06e-3cdb-4d76-b8fd-b96c4e05edf4', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'In a micro-frontend architecture, how would you approach state management if each micro-app uses its own Redux store?', N'Senior', N'The preferred approach is to maintain isolated stores for each micro-frontend to ensure decoupling and independent deployment. If cross-app communication is required, it should be handled via a global event bus or a shared custom hook layer rather than attempting to share a single Redux store across boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0853fc05-45fb-449d-be67-b96c914811bd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the primary role of the Extractors in the Axum web framework?', N'Fresher', N'Extractors are a mechanism used to transform incoming HTTP requests into typed data structures that your handler functions can consume. They allow you to automatically parse headers, path parameters, query strings, or JSON request bodies without manually handling the raw request stream. If the extraction fails, Axum automatically returns a bad request response to the client, simplifying error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55d74f96-7ba1-4309-8810-b96fa833fb0e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Describe the impact of Fastify''s hook system on request lifecycle performance.', N'Senior', N'Fastify hooks are executed in a strictly defined order and are designed to avoid blocking the main event loop. By keeping these hooks lightweight and supporting asynchronous execution, the framework maintains low latency even when complex middleware-like logic is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cc4a48a-d524-40b7-9d78-b9746b4d15cf', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you group and nest console output?', N'Fresher', N'The console.group() can be used to group related log messages to be able to easily read the logs and use console.groupEnd()to close the group. Along with this, you can also nest groups which allows to output message in hierarchical manner. For example, if you’re logging a user’s details: You can also use console.groupCollapsed() instead of console.group() if you want the groups to be collapsed by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee76eeab-a8cb-4c08-8482-b97478711353', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the difference between ''Context'' and ''AsyncContext'' in Actix actor management.', N'Senior', N'Context is used for synchronous actor operations, while AsyncContext allows for non-blocking operations and integration with asynchronous futures. Choosing the latter is vital for performing IO-bound tasks like database queries or network requests within the actor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc91b1ff-99a0-4cfc-9b04-b974f32b93e0', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle asynchronous streaming compared to traditional blocking frameworks?', N'Senior', N'Litestar supports native asynchronous generators for streaming data, allowing the server to push content to the client without blocking the event loop. This is essential for building high-performance APIs that handle large payloads or real-time data updates efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f937a876-4b9f-4c31-bb83-b97679944f54', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does the ''Rocket'' crate provide?', N'Intern', N'The Rocket crate provides the core framework functionality, including the routing engine, request handling, and response generation. It serves as the primary library dependency for building a Rocket application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d2f1581-901a-4056-a947-b977b98fab4e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does the ''Single-threaded'' nature of Redis mean for developers?', N'Fresher', N'It means that Redis processes one command at a time. While this simplifies the internal architecture and prevents concurrency issues, developers should avoid running long-running or blocking commands that could slow down the entire server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0848f29e-f703-443b-b83b-b979a4b42419', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a major disadvantage of using a NoSQL database compared to a SQL database?', N'Junior', N'A major disadvantage is the lack of support for complex multi-table joins and standard ACID transactions across multiple documents. This makes it more difficult to maintain data integrity and perform relational queries that require linking data across different collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f441ca74-02d7-4595-a489-b97db5abfa30', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How can you implement backpressure in a messaging system?', N'Middle', N'Backpressure can be implemented by setting limits on queue sizes or by having consumers pull messages at their own pace rather than having the broker push them. This prevents the producer from overwhelming the consumer during traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
