INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32720ad7-a176-4b63-b7e2-b97e4c627102', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a Sealed Class, and why is it useful?', N'Junior', N'A sealed class represents a restricted class hierarchy where an object can have one of a limited set of types. It is particularly useful in when expressions, as the compiler can verify that all possible cases are covered without needing a default branch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'830859c4-6221-4e11-b4d0-b98202a48bcd', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'When should you use ''attr_accessor'' versus defining manual getters and setters?', N'Middle', N'Use ''attr_accessor'' for standard attributes where no custom logic is required, as it reduces boilerplate code. Define manual getters and setters when you need to perform validation, logging, or data transformation during variable access or assignment. Manual definition provides the control necessary to encapsulate logic within the object''s interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f27d858-983a-4360-93f9-b983381efc27', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does ''dns-prefetch'' differ from ''preconnect'' regarding connection state?', N'Senior', N'DNS-prefetch only performs the domain name resolution, which is a low-cost operation that saves time on subsequent requests. Preconnect establishes the full connection path, including TLS, which is more resource-intensive but reduces latency significantly for high-priority external origins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e77717b-b816-4686-8545-b984ebc62ba7', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How would you optimize the performance of a Django form that has a large number of choices?', N'Middle', N'Fetching all choices from the database on every request can be slow. You can optimize this by caching the choices list, using ModelChoiceField strategically, or implementing AJAX-based loading where choices are fetched dynamically as the user types or interacts with the form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92a9a367-ed0b-4ffd-b27f-b98ad67f6ff9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure you are not introducing regressions when adding a new feature?', N'Junior', N'Run existing automated tests to ensure current functionality remains intact before and after your changes. If the project lacks sufficient test coverage, manually test critical paths that could be affected by the new update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'217c4c95-0bfa-4472-b4e2-b98dfb311032', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the advantages and drawbacks of using gRPC over REST/JSON for internal communication?', N'Senior', N'gRPC offers high performance via Protobuf serialization and HTTP/2 multiplexing, making it ideal for low-latency internal microservice communication. The drawbacks include lack of browser support, stricter schema management requirements, and the need for a proxy for HTTP/1.1 compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
