INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b792153e-e5f9-40bf-87c0-b9909fd0191d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you define a POST route in Gin?', N'Junior', N'You define a POST route by calling the ''POST'' method on the Gin engine instance. You provide the path string as the first argument and the handler function as the second argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59a9c412-e3c4-4c84-abfb-b99256d53064', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If an existing service is experiencing latency, how do you start diagnosing the root cause?', N'Middle', N'I begin by reviewing observability metrics like request duration, throughput, and error rates to isolate the bottleneck. I check resource utilization on the host, analyze database query performance, and inspect external dependency latency. This systematic approach helps distinguish between infrastructure issues and inefficient application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'832b5acc-e72f-477a-bc0e-b994025013de', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the Startup class used for in an ASP.NET Core application?', N'Intern', N'The Startup class is the entry point for configuring the application''s request processing pipeline and its services. It typically contains methods to register dependencies in the container and to define how the application responds to HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'553d1645-61d9-4957-bdff-b9959c7c720f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the role of the Scala implicit resolution mechanism in the context of type-class pattern implementation?', N'Senior', N'Implicit resolution provides a compile-time mechanism for ad-hoc polymorphism by searching for eligible instances in the scope based on the required type constraints. When a function expects a type-class instance, the compiler recursively searches through local, imported, and companion object scopes to satisfy the dependency. This enables developers to extend functionality to types without modifying their original class definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a75d5fa0-382c-4a5f-8cc5-b9995e143f6f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the difference between ''const'' and ''final'' in terms of memory allocation.', N'Senior', N'Final variables are assigned at runtime and their memory is allocated when the runtime reaches the assignment statement. Const variables are compile-time constants, meaning they are canonicalized and allocated in a read-only data segment of the binary, providing both memory efficiency and performance gains through pre-computation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08da3fc7-e188-445e-9d6c-b999df50d314', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is reflection restricted in Quarkus Native mode?', N'Junior', N'Native compilation requires all code paths to be known at build time to optimize the executable. Because reflection allows for dynamic code execution at runtime, it cannot be easily analyzed, so developers must explicitly register classes for reflection if they are used dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55b5840-ed11-4cee-be58-b99b52f94232', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you achieve dependency injection in Axum?', N'Senior', N'Dependency injection is primarily achieved through the State extractor, where shared resources like database pools or API clients are injected into handlers. By wrapping these in an Arc, you ensure the resources are efficiently shared across threads while maintaining strict type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b255d93-6c8d-4cce-8fb3-b99c111efbca', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to break a large, complex problem into smaller parts?', N'Fresher', N'Breaking a problem into smaller parts makes it easier to manage, test, and debug. It allows me to make consistent progress and prevents me from feeling overwhelmed by the complexity of the entire task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6a849f9-8ceb-4c59-829b-b99cda233b6c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the trade-off of using server-side rendering in Remix compared to static site generation?', N'Middle', N'Server-side rendering provides real-time, dynamic data for every request, which is ideal for highly personalized or frequently changing content. The trade-off is higher server load and potentially increased latency, whereas static site generation offers faster delivery but lacks the ability to serve dynamic per-user content out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'874fd451-4a43-44d3-a69c-b99d711406d8', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a render function?', N'Intern', N'Render function is a normal function which receives a createElement method as it''s first argument used to create virtual nodes. Internally Vue.js'' templates actually compile down to render functions at build time. Hence templates are just syntactic sugar of render functions. Let''s take an example of simple Div markup and corresponding render function. The HTML markup can be written in template tag as below, and the compiled down or explicit render function would appear as below, Note: The react components are built with render functions in JSX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'273f24a6-61e1-420b-a068-b99f20b3b8b7', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the function of the ''Sync'' trait in multi-threaded programming?', N'Senior', N'The Sync trait identifies types that can be safely shared between threads, meaning that a type is Sync if and only if a reference to it is Send. It enables the compiler to verify that shared data structures do not introduce data races, ensuring that concurrent access is either immutable or protected by synchronization primitives.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'952b2a36-1262-4bcf-8dc8-b9a192dc6be0', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle the destruction of objects with circular references?', N'Senior', N'PHP employs a dedicated cycle collector that runs when the root buffer is full, identifying isolated cyclic references that cannot be reached by the main program. It temporarily decrements reference counts to see if the objects are truly unreachable, after which it triggers a cleanup process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'897c1d1b-9a3c-4703-98de-b9a207e1ae7e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''session'' object in Rails?', N'Fresher', N'The session object allows you to store data across multiple HTTP requests for a specific user. It is commonly used to manage user authentication and track state, like items in a shopping cart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3382955d-3923-4ff0-94ea-b9a4da1fc2ca', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle memory management compared to languages with garbage collection like Java?', N'Middle', N'PHP uses a reference counting mechanism combined with a cycle collector to reclaim memory immediately after a script finishes execution. While it does have a garbage collector for circular references, the short-lived nature of the PHP request lifecycle makes traditional long-running memory management less of a concern. This simplicity is a core feature of its architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e177ee3-54a3-4d5d-9de4-b9a5cebf5502', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do stored procedures impact database portability?', N'Middle', N'Stored procedures are specific to the database engine''s proprietary language, which makes migrating the application to a different database vendor significantly harder. They bind the business logic to the database layer, creating a vendor lock-in scenario.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99bcdfad-5b55-4d57-8fa8-b9a5f8aaba47', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Are NoSQL databases always ACID compliant?', N'Junior', N'No, many NoSQL databases prioritize availability and partition tolerance over strict ACID compliance, often following the BASE model instead. However, some modern NoSQL systems provide ACID-compliant transactions for specific use cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77261f14-b00c-4409-a061-b9a7645d00b5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of specificity in CSS and how it is calculated.', N'Middle', N'Specificity determines which CSS rule is applied when multiple rules target the same element. It is calculated by weighing the types of selectors used, with inline styles having the highest weight, followed by IDs, then classes and attributes, and finally element types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb497d38-ce68-43c1-9132-b9a7ab1b5e4a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the architectural significance of Micronaut''s ''HTTP Client'' being non-blocking?', N'Senior', N'By being fully non-blocking, the HTTP client allows a single service to manage thousands of concurrent outgoing requests without requiring a massive thread pool. This is essential for microservices that aggregate data from multiple downstream dependencies, preventing thread starvation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de8947ba-10db-4629-b64e-b9a7c00c5a50', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do you control access to a DynamoDB table?', N'Intern', N'Access to DynamoDB tables is controlled using AWS Identity and Access Management (IAM) policies. These policies define which users or services have permissions to perform specific actions like reading, writing, or deleting data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05b6638b-3a54-4f48-a949-b9a8aa5a2436', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Is Echo considered a synchronous or asynchronous framework?', N'Fresher', N'Echo runs on Go''s net/http server, which utilizes goroutines to handle each request concurrently. While the handler code is written in a sequential style, the underlying server is asynchronous as it handles multiple requests simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58b95dc2-716b-4b34-8319-b9a9cc12e96c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is it important to use ''const'' by default over ''let'' and ''var''?', N'Middle', N'Using ''const'' makes the intent of the code clearer by signaling that the reference will not be reassigned, which reduces the surface area for bugs. It also enables the JavaScript engine to perform better static analysis and potential optimizations since the variable identifier is guaranteed to point to the same memory location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79fb5252-122b-49fb-8ab9-b9af834d4828', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why does Kotlin forbid the declaration of ''open'' properties inside a final class?', N'Middle', N'A final class cannot be inherited, making the ''open'' modifier redundant for its members. The compiler enforces this to prevent confusion and ensure that the class design reflects its intended usage as a non-extensible component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34bb61a8-22ca-4c7c-9859-b9b139d9514e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the trade-offs of using AdonisJS''s ''Edge'' template engine over a client-side library?', N'Middle', N'Edge provides server-side rendering which improves initial page load speed and SEO by sending fully populated HTML to the browser. However, it requires more server resources and may be less suitable for highly interactive, state-heavy interfaces where a decoupled client-side framework might offer a better user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20e5f862-5135-42ee-970d-b9b264c3e560', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the function of the ''using'' statement in C#?', N'Fresher', N'The ''using'' statement ensures that objects that implement the IDisposable interface are properly disposed of once they go out of scope. It automatically calls the dispose method, which is essential for releasing unmanaged resources like file handles or database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'366b7b78-5c8d-4408-b5bc-b9b314bc4b21', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is an ''optional parameter'' in SvelteKit routing?', N'Fresher', N'An optional parameter is a part of a route path enclosed in double brackets, such as [[slug]]. It allows the route to match regardless of whether that segment exists in the URL, making the route flexible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'257c75f0-9a5d-42f1-bf43-b9b3187796b9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does logging contribute to an effective troubleshooting strategy?', N'Intern', N'Logs provide a historical timeline of events, state changes, and errors that occurred before a failure. By reviewing these entries, you can reconstruct the sequence of events leading up to the issue, which is essential for identifying the root cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6829dee5-17ab-46b2-a684-b9b9acd57c3a', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the ''Phoenix.LiveView'' diffing algorithm optimize network traffic?', N'Senior', N'LiveView tracks the state of the component and only calculates the delta between the old and new HTML structures. By sending only the changed parts of the UI over the WebSocket, it significantly reduces the amount of data transferred compared to re-rendering the entire page or sending large JSON payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dfec623-32c4-4403-84df-b9baff53239c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''virtual'' and ''abstract'' methods?', N'Intern', N'A ''virtual'' method has a default implementation and can be overridden by a derived class, while an ''abstract'' method has no implementation and must be overridden by any non-abstract derived class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
