INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58769e88-4be3-48c6-89f8-b9c19a13e17c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of a primary node in a cluster?', N'Intern', N'The primary node usually handles all write operations within a cluster to ensure data consistency. It then propagates these changes to secondary nodes, which are typically used to handle read requests and provide failover protection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8db6c82a-0d74-46fe-bdb9-b9c3b53db37b', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are the security implications of exposing Server Actions?', N'Senior', N'Server Actions are essentially public API endpoints that can be invoked by anyone. They must be treated with the same security rigor as traditional REST endpoints, including input validation, authorization checks, and CSRF protection to prevent unauthorized data mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
