INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32d986de-a049-406a-a005-b9c99a47868d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the difference between controlled and uncontrolled components in Preact?', N'Fresher', N'Controlled components have their state managed by Preact, meaning form inputs are synced with component state. Uncontrolled components rely on the DOM itself to handle input values, usually accessed via references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a6ebaca-7394-419b-8f7d-b9c9f3b2518b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is forwardRef() in React used for?', N'Intern', N'As of React 19 (December 2024), forwardRef() is no longer necessary — function components can now accept ref as a regular prop, so wrapping in forwardRef() is no longer required. React plans to deprecate forwardRef() in a future release. forwardRef() historically existed because, before React 19, function components could not receive a ref prop and forwardRef() was the official workaround for forwarding a parent''s ref down to a child DOM node or component. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96326704-d44e-4c3a-bf53-b9cab3b517ae', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus differ from traditional frameworks regarding the deployment of applications to the cloud?', N'Junior', N'Quarkus allows applications to be compiled into native executables using GraalVM, which significantly reduces the footprint and improves startup speed. This ''Supersonic Subatomic'' approach helps minimize costs and latency in serverless or containerized cloud deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a49cb1e8-a60c-4a94-a928-b9d01648fcdf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What should you do if your initial troubleshooting plan isn''t working?', N'Intern', N'You should step back, clear your mind, and re-evaluate your assumptions. Sometimes it is helpful to explain the problem to a colleague, as the process of describing the issue often highlights gaps in your own understanding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f78d72c5-5487-4d8c-9158-b9d0a7bbfa0c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why does Actix use ''Future'' trait extensively?', N'Middle', N'The Future trait allows Actix to represent values that will be available later, enabling asynchronous composition. By using futures, the framework can suspend execution of a task while waiting for an external result, freeing up the thread to handle other work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8756f1f4-5483-47a8-81c8-b9d278818355', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Compare the performance overhead of traditional callbacks versus Promises and Async/Await.', N'Senior', N'While Promises and Async/Await introduce a minor overhead due to microtask queue management and object allocation, this is negligible compared to the architectural benefits of improved readability and error handling. The primary performance concern is not the syntax itself, but the creation of excessive objects in tight, high-frequency loops. Modern V8 engines have optimized these constructs to be highly efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a966b580-aa13-4762-91a7-b9d2dfccad71', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to implement a circuit breaker pattern in a distributed system?', N'Middle', N'A circuit breaker prevents a system from repeatedly attempting to call a failing service, which protects the calling service from resource exhaustion. It allows the failing service time to recover and provides a graceful fallback mechanism for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd25a2aa-3a45-4632-9906-b9d3748a7110', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of an index in Elasticsearch?', N'Intern', N'An index is a logical namespace that groups related documents together. It acts as a container for data that shares similar characteristics, allowing users to perform operations like searching or updating across all documents contained within it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb1b60e9-e229-4fa0-be89-b9d4408ebb07', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is Pydantic''s ''BaseModel'' central to FastAPI performance and security?', N'Middle', N'Pydantic performs data validation at runtime using compiled C code, making it extremely fast. It ensures that only expected data types enter the application, preventing common vulnerabilities like mass assignment or injection of unexpected fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75c9186a-eafa-4045-aa87-b9d741767f22', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How are path parameters defined in Litestar?', N'Junior', N'Path parameters are defined using curly braces in the route string, such as ''/users/{user_id:int}''. Litestar automatically parses these parameters and injects them as arguments into your route handler function based on their names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c581779d-c2ea-4aa7-abbd-b9dc0f91a6d6', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the first step you should take when you encounter a bug in a system?', N'Intern', N'The first step is to reproduce the issue consistently in a controlled environment. By confirming that the bug occurs reliably, you can isolate the conditions that trigger the failure before attempting to fix it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
