INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed73012c-4afd-4011-ae19-b9e2f5415030', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a data type, and why is it important in database design?', N'Junior', N'A data type defines the kind of data a column can hold, such as integers, text, or dates. It is important because it enforces data validation, optimizes storage space, and ensures that the database engine can perform appropriate calculations or operations on the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f74d2302-dc34-43c0-adcb-b9ebc08319e0', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite considered ''framework-agnostic''?', N'Fresher', N'Vite is designed to work with almost any frontend framework, including React, Vue, Svelte, and Solid. It uses a plugin system to provide framework-specific features without being tied to the internal logic of any single one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e73f259d-e52c-4a2b-9f13-b9ecc14e64c0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between using a caching layer and optimizing the database query directly?', N'Middle', N'I first analyze the frequency of the data access and the cost of the query. If the data is read-heavy and computationally expensive, caching is the better choice to reduce load, whereas database optimization is preferred for complex relational integrity or when data freshness is critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
