INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31de969f-2d40-4096-b510-b9ef1439622e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are replaceAll(), padStart() and padEnd() string methods?', N'Intern', N'1. String.prototype.replaceAll(): The replaceAll() method returns a new string with all matches of a pattern replaced by a replacement. Unlike replace(), it replaces every occurrence without needing a global regex flag. 2. String.prototype.padStart(): The padStart() method pads the current string with another string from the start until it reaches the given length. 3. String.prototype.padEnd(): The padEnd() method pads the current string with another string from the end until it reaches the given length.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
