INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca5ba47c-0916-415d-a40b-ba05f13e0faa', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the trade-offs between static and dynamic dispatch in Rust?', N'Senior', N'Static dispatch uses generics with trait bounds, leading to monomorphization where the compiler generates specialized code for each type, resulting in faster execution due to inlining but larger binary sizes. Dynamic dispatch uses trait objects with vtables, which introduces a small runtime overhead for pointer indirection but reduces binary bloat by sharing code across types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96510f94-86a4-4325-a349-ba069f976429', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the performance implications of ''Serializable'' snapshot isolation (SSI)?', N'Senior', N'SSI is an optimistic concurrency control mechanism that tracks dependencies between transactions to detect potential serializability violations without using heavy locks. It provides the benefits of serializability with much higher concurrency, though it may cause a higher rate of transaction aborts under heavy contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
