INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4779c8a8-9fc6-4e7b-97a7-ba1349a552b1', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Routing component work?', N'Fresher', N'The Routing component maps a URL request to a specific controller action. It parses the incoming request path against defined patterns and extracts parameters to determine which piece of code should handle the logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85c946d5-5b42-4b14-ad65-ba154196f5bf', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the role of the Symfony Kernel.', N'Fresher', N'The Kernel is the heart of a Symfony application that handles the request-to-response lifecycle. It receives a Request object, manages the event dispatcher to trigger various stages of the application process, and returns a Response object to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd335989f-737f-42f8-9703-ba16d9e6c96b', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the lifecycle methods of VueJS?', N'Fresher', N'Lifecycle hooks are a window into how the library you''re using works behind-the-scenes. By using these hooks, you will know when your component is created, added to the DOM, updated, or destroyed. Let''s look at lifecycle diagram before going to each lifecycle hook in detail,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12a1ca02-3ac8-4f3a-b84f-ba17c4b1c8c7', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik benefit mobile users specifically?', N'Middle', N'Mobile users benefit significantly from reduced data usage and faster interactions on slower networks. By shipping almost no JavaScript on the initial load, Qwik minimizes the impact of limited CPU power and network latency common on mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcd61cdb-2e71-4f3b-ad8c-ba1823dc88d0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle context in comparison to the standard library net/http?', N'Middle', N'Echo wraps the standard request and response objects into a custom Context interface. This provides helper methods for parsing parameters, binding JSON payloads, and rendering responses, which significantly simplifies the API compared to the raw request and response manipulation required by net/http.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'634b321f-72d4-428b-8f86-ba1adeb33c23', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the main design philosophy behind Rocket?', N'Fresher', N'Rocket emphasizes ease of use, type safety, and developer experience. It leverages Rust''s strong type system to catch errors at compile time rather than at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05ed2e15-7e90-4c21-b510-ba1ae8964787', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do JavaScript engines prefer TypedArrays for high-performance numerical data?', N'Senior', N'TypedArrays provide a contiguous block of memory with a specific data layout, mirroring C-style arrays. This allows the engine to skip type checks and avoid boxing/unboxing overhead, enabling efficient SIMD-like operations and predictable cache locality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b44f573-096d-46fb-aa75-ba1b93de38d3', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered ''edge-native''?', N'Fresher', N'Hono is built to run on edge computing platforms like Cloudflare Workers. It is lightweight, has no heavy dependencies, and starts up extremely quickly, which is crucial for reducing latency in distributed environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfb24843-3d91-490f-956b-ba1c6eb008bb', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is it important for tokens to have an expiration time? How can you implement token expiration in NestJS, and what role do refresh tokens play in maintaining user sessions?', N'Fresher', N'Tokens having an expiration time is important for security reasons. If a token is stolen or leaked, it can be used to gain unauthorized access to the system. By setting an expiration time, you limit the time window in which a stolen token can be used. In NestJS, you can set the expiration time of a JWT when you sign it using the JwtService. Here''s an example: In this example, the token will expire 60 seconds after it''s issued. However, having tokens expire can be inconvenient for the user, as they would have to log in again every time their token expires. This is where refresh tokens come in.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be0cae16-3554-4855-9c93-ba1dc612bf54', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the function of a ''Health Check'' endpoint in an API?', N'Middle', N'A health check endpoint provides a simple way for load balancers and monitoring systems to verify that an API instance is operational. It ensures that traffic is only routed to healthy nodes, improving system availability and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd95c1c8c-b9a4-4ec1-adc9-ba2009a9fdee', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a stakeholder request to ''just add a small feature'' that threatens a critical project deadline?', N'Senior', N'I perform a rapid impact assessment to determine how the feature affects the critical path and resource allocation. I then present the trade-offs to the stakeholder, offering options such as de-scoping lower-priority items, adjusting the timeline, or deferring the feature to a follow-up release.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'622e8a9a-f5f4-4de9-8a18-ba2059c302e9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is Fastify and why is it used in backend development?', N'Fresher', N'Fastify is a web framework for Node.js focused on providing the best developer experience with minimal overhead and a powerful plugin architecture. It is designed to be highly efficient and capable of handling a large number of requests per second with low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30823c23-00a2-4a25-a292-ba20855bad7d', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the role of the ''PostCSS'' build step in Tailwind?', N'Intern', N'Tailwind acts as a PostCSS plugin. It processes your CSS files, scans your source code for class names, and generates the final CSS output based on the utilities found in your project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
