INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eee9e2d1-43bc-4243-aea3-ba2b99945f8c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a Controller in ASP.NET Core?', N'Intern', N'A controller is a class that handles incoming HTTP requests and coordinates the application''s response. It processes user input, interacts with services or data models, and returns an appropriate result, such as a view or a data object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9472d0f-0241-4b71-a107-ba2f6b248951', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do Custom Decorators improve code maintainability compared to standard NestJS decorators?', N'Senior', N'Custom decorators allow for the abstraction of repetitive logic, such as extracting user info from a JWT or validating custom request headers, into reusable declarations. This reduces boilerplate in controller signatures and promotes declarative programming, making the business logic cleaner and the dependency on the transport layer more explicit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2ea56f4-f2f8-45aa-9c5c-ba313834ee5a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Explain the trade-off of using Echo''s ''Group'' feature for API versioning.', N'Middle', N'Using route groups improves code organization and readability by allowing shared middleware and prefixing for specific URL segments. The trade-off is slightly increased memory usage for the routing tree, though this is negligible compared to the benefits of maintainability in large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcf414d6-2cac-4e31-80b1-ba33fb0acb66', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the ''context'' API in Svelte, and how does it differ from global stores?', N'Senior', N'Context allows data to be passed down the component tree without prop drilling, but it is scoped to the specific component hierarchy. It is ideal for dependency injection within a tree, whereas stores are better suited for global application-wide state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e68f6ed-6963-431f-a62e-ba34a6859987', N'954a0331-deff-4399-b588-96f39fec001d', N'What are some uses of interceptors and can we provide multi-interceptors?', N'Intern', N'Angular HTTP Interceptors allow you to intercept outgoing HTTP requests and incoming HTTP responses, process them, and pass them along. They are useful for tasks like adding authentication tokens to headers, logging requests and responses, handling errors globally, or caching responses. You can provide multiple interceptors in your application. Angular processes them in a chain. To provide multiple interceptors, you use the HTTP_INTERCEPTORS injection token and set the multi property to true for each interceptor provider in your module or component''s providers array. The order in which you list them in the providers array determines the order they are applied to requests and responses. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0eb3c1f-eaad-40b1-83f4-ba34b5f938e3', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the architectural trade-off of using a ''Fat Router'' versus a ''Fat Controller'' in an Express application.', N'Senior', N'A ''Fat Router'' keeps business logic out of controllers but can become difficult to maintain as routes grow, whereas a ''Fat Controller'' keeps routes clean but tends to accumulate too much business logic, violating the Single Responsibility Principle. A better approach is to delegate logic to service layers, keeping both routers and controllers thin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d90ade2-1030-40f4-ad0f-ba3618a2d29c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why would you choose Chi over a full-featured web framework?', N'Fresher', N'You would choose Chi if you prefer a ''minimalist'' approach where you want to keep the application lightweight and choose your own libraries for database access, validation, or templating. It gives you control over the stack rather than forcing a specific design pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba1451a9-5205-4beb-819e-ba39d697c7e3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing an API, how do you manage versioning to avoid breaking existing clients?', N'Middle', N'I prefer using URI versioning for major, breaking changes to ensure complete isolation between versions. For minor, backward-compatible changes, I use headers or query parameters to allow clients to opt-in to new features without disrupting the existing integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8143df48-0bdd-4501-9863-ba3a18c50a01', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between an interface and a type alias?', N'Intern', N'Both are used to define the shape of objects or data, but they have subtle differences in syntax and capabilities. Interfaces are generally better for defining object structures, while type aliases are more flexible and can represent unions, primitives, and tuples.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'004f718e-762d-4530-85bb-ba3bee02c212', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the significance of the ''h'' function in Vue''s render function API?', N'Senior', N'The h function, or hyperscript, is used to create virtual DOM nodes programmatically. It provides a way to bypass templates for highly dynamic or complex component structures, giving developers full control over the rendering logic while still benefiting from Vue''s reactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94e48faf-a71f-4131-8343-ba3e19951012', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Security implement authentication and authorization using the Filter Chain?', N'Senior', N'Spring Security inserts a DelegatingFilterProxy into the Servlet container''s filter chain. This proxy delegates to a chain of internal security filters that perform tasks such as credential extraction, session management, and access control decision-making before the request reaches the Controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a64c3914-43f0-49c4-9400-ba419215af55', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of ''Anti-Entropy Repair''?', N'Senior', N'Anti-entropy repair uses Merkle trees to compare data between nodes and identify discrepancies that were not caught by read repair or hinted handoffs. It is essential for long-term consistency in distributed systems where nodes may have been offline for extended periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adba1c94-8efb-4c8f-b9d7-ba431198c502', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is PostgreSQL and how is it classified?', N'Intern', N'PostgreSQL is an open-source object-relational database management system. It is classified as an RDBMS because it uses tables to store data and relies on structured query language for data manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'320eedee-977f-4e07-aeaa-ba45aee10c12', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Compare the performance overhead of CSS transitions versus Web Animations API (WAAPI).', N'Senior', N'CSS transitions are declarative and easily offloaded to the compositor thread, making them highly performant. WAAPI provides greater programmatic control and synchronization, but if used improperly to animate non-compositor properties, it can force main-thread layout thrashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f78b8fc-e469-4405-8dfb-ba4665348742', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a protocol in Swift and why is it useful?', N'Junior', N'A protocol defines a blueprint of methods, properties, or other requirements that a class, struct, or enum must implement. It is useful for enabling polymorphism and decoupling code, as it allows you to write functions that work with any type that conforms to a specific protocol.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'248c2be2-9395-40db-ae0d-ba493e015e2d', N'954a0331-deff-4399-b588-96f39fec001d', N'Why do we need compilation process?', N'Fresher', N'The Angular components and templates cannot be understood by the browser directly. Due to that Angular applications require a compilation process before they can run in a browser. For example, In AOT compilation, both Angular HTML and TypeScript code converted into efficient JavaScript code during the build phase before browser runs it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
