INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be194ed9-1a50-4c4b-9098-ba7177fa2431', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you ensure that your estimates remain accurate throughout the lifecycle of a long-term project?', N'Middle', N'I update estimates periodically based on velocity data and progress against milestones. I maintain a feedback loop where we review past estimates against actuals to identify patterns in over- or under-estimation and adjust our planning methodology accordingly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4f6bbc9-48ab-4b9d-9443-ba71df71b38f', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is ''Addr::do_send''?', N'Junior', N'The do_send method is a fire-and-forget way to send a message to an actor. It does not wait for a response and returns immediately, making it useful for notifications where the result is not needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ee009de-9e56-4baf-bdc7-ba722550c0b2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do distributed databases handle the trade-offs of the CAP theorem when implementing ACID transactions?', N'Senior', N'Distributed databases often prioritize consistency and partition tolerance (CP) by utilizing consensus algorithms like Paxos or Raft. This ensures that even in the presence of network partitions, the system maintains a single version of truth, though it may sacrifice availability during leader election or synchronization phases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e51f90dc-fd63-4176-93bc-ba76b0fa89a5', N'075b8862-431c-4678-9767-f55359758a4a', N'What are Vue slots and why are they useful?', N'Middle', N'Slots are a mechanism for component composition that allows a parent to pass custom template content into a child component''s layout. They enable the creation of highly flexible, generic components that can be customized by the consumer without modifying the internal component code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f12e5782-5b14-4291-99ad-ba77703c5001', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are sealed classes?', N'Intern', N'Sealed classes are used to represent restricted class hierarchies where a value can have one of the types from a limited set. They are often used to represent state or result types in a safe and predictable way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcf378a5-9f53-4604-81ce-ba7ab0e7408c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of NestJS Interceptors and when should they be used?', N'Middle', N'Interceptors use the AOP pattern to bind extra logic to method execution, such as transforming results or caching responses. They are ideal for cross-cutting concerns like logging, request transformation, or mapping data before it leaves the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90a3aba0-924b-4e79-9533-ba7ab556e34f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you optimize the startup time of a microservice that has heavy initialization dependencies?', N'Senior', N'I would implement lazy loading for non-critical dependencies and use a readiness probe to ensure the service only receives traffic once it is truly ready. I would also investigate caching initialization results or pre-warming the application state during the CI/CD pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25c1b2e7-fd5c-4f17-bf78-ba7e3ae8470d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the performance implications of using synchronous I/O in ASP.NET Core, and how does the framework mitigate this?', N'Senior', N'Synchronous I/O blocks the thread pool, leading to thread starvation and increased latency under high load, as the server cannot process new requests while waiting for I/O. ASP.NET Core mitigates this by providing asynchronous APIs throughout the framework and by disabling synchronous I/O by default in Kestrel for certain operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e268953-4f0c-4591-bb81-ba807bde3208', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the primary function of the MySQL database engine?', N'Intern', N'MySQL acts as a Relational Database Management System (RDBMS) that stores, retrieves, and manages data organized into tables. It uses Structured Query Language to allow users to interact with the database, ensuring data integrity and efficient access through a client-server architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'162e719c-97ac-4f78-b861-ba87c007417a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite''s ''optimization.exclude'' option important?', N'Middle', N'The exclude option allows developers to prevent certain dependencies from being pre-bundled by esbuild. This is useful when a dependency is incompatible with esbuild''s bundling logic or if it is already distributed as a highly optimized ESM module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62727b99-4f95-4c0d-aaf0-ba888f323693', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain how Flask handles global state and why this presents challenges for unit testing.', N'Senior', N'Flask relies on global proxies (request, session, g) which are bound to the current execution context, making it difficult to test components in isolation without mocking the entire request environment. This necessitates the use of test request contexts or factory patterns to ensure each test case runs in a clean, reproducible state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c22d6723-9917-4be0-abaf-ba89295bfd82', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why would an organization choose a NoSQL database over a relational database?', N'Intern', N'NoSQL databases are often chosen for their ability to handle large volumes of unstructured or semi-structured data. They also provide flexible schemas and are designed to scale horizontally across multiple servers easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdaa2873-be8d-4e69-b1a5-ba8a7293a0ac', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a struct in Rust?', N'Intern', N'A struct is a custom data type that lets you name and package together multiple related values that make up a meaningful group. It is similar to objects in other languages but focuses on data structure rather than behavioral inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a30d08b2-98b7-4328-9dcb-ba8eae3f18a3', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How can read-repair be used to improve cache consistency?', N'Middle', N'Read-repair is a technique where the system checks the validity of data during a read operation and updates the cache if it detects that the stored value is out of sync with the database. This acts as a background consistency mechanism that self-heals the cache over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'057d505a-4f24-420e-87a0-ba938cf4fda0', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you don''t return a state in a reducer?', N'Fresher', N'If a reducer does not return a state, the state will become undefined. This will cause the application to crash or behave unexpectedly because the store expects a valid state object to be returned after every action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'347cf31c-8ec5-4350-afea-ba989a0f7b4a', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does the ''Bulkhead'' pattern improve system resilience?', N'Middle', N'The bulkhead pattern isolates elements of an application into separate pools so that if one fails, the others continue to function. This prevents a failure in one component from consuming all shared resources and taking down the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beb17983-57cc-402d-b2c7-ba9c059254a2', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit ensure type safety across the entire application?', N'Middle', N'SvelteKit automatically generates TypeScript definitions for routes, page data, and form actions based on the file-system structure. This allows developers to have end-to-end type inference from the server-side data loading down to the UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f71188a-0602-4a68-849a-ba9cae1680e0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the purpose of ''unknown'' versus ''any'' in TypeScript.', N'Middle', N'The ''any'' type disables type checking, allowing any operation on the variable. ''Unknown'' is a type-safe alternative that forces you to perform type narrowing or assertion before interacting with the value, preventing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d46a82c-5d28-44ad-9f28-ba9d9b2fc2b3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How is a view related to data independence?', N'Fresher', N'A VIEW stores a query, not data. Applications query the view so underlying schema changes (renamed tables, added columns) don''t break the application as long as the view definition is updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cf588d9-1733-409d-b2dd-ba9f57f562db', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a regression in software testing?', N'Fresher', N'A regression happens when a previously working feature breaks after a new change or update. It indicates that the new modification inadvertently impacted existing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'715e8934-8893-4eb5-b05d-baa007e50892', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Describe the impact of the ''callback hell'' legacy on modern Express development.', N'Senior', N'While modern Express supports async/await, the framework''s internal architecture is built on callbacks, which can still lead to inconsistent error handling if not used carefully. Mixing callback-based middleware with async handlers can result in ''silent'' failures that are difficult to capture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'304014fe-c5cd-47a4-9922-baa0e5fdefc4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of the ''launch'' macro in Rocket?', N'Fresher', N'The launch macro is used to define the entry point of a Rocket application. It initializes the server and starts listening for incoming requests based on the routes and state configured in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4af3417c-1c6d-46e4-8528-baa197a47a63', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue where services are experiencing intermittent DNS resolution failures?', N'Senior', N'I would check the DNS server load, the TTL settings on the records, and the local resolver cache on the affected nodes. I would also investigate if the application is caching DNS lookups indefinitely, which prevents it from picking up updated IP addresses when service endpoints change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5f0ef88-8e27-46a0-9738-baa2171de951', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the built-in data types in Python?', N'Intern', N'Python offers numerous built-in data types that provide varying functionalities and utilities for efficient memory management and data manipulation. These are generally categorized by their mutability. Immutable Data Types 1. int Represents arbitrary-precision integers, such as 42 or -10. In modern Python, the int type handles all integer sizes automatically, removing the need for a separate "long" type. 2. float Represents double-precision floating-point numbers, such as 3.14 or -0.001, following the IEEE 754 standard. 3. complex Used for mathematical computations involving a real and an imaginary part, represented as $z = a + bj$, where $j = \sqrt{-1}$. 4. bool A subclass of integers representing logical values: True (internally 1) and False (internally 0). 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c77574d9-c6da-471f-b7e9-baa459571f77', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s reactivity system handle nested objects versus arrays differently?', N'Senior', N'Vue uses Proxy-based reactivity to intercept property access and mutations. For objects, it recursively converts nested properties into reactive proxies upon access, whereas for arrays, it intercepts specific mutation methods like push or splice while tracking index-based changes to ensure dependency collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49ee1b49-6b8f-4bd7-9f25-baa6a6209ed7', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''layouts'' directory in Nuxt?', N'Middle', N'The layouts directory allows you to define reusable wrapper components for your pages, such as headers, footers, or sidebars. This keeps the page components clean and ensures a consistent UI structure across different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9cdcf32-62a4-47f6-840b-baa6e76bc152', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prioritize web standards like HTML forms and HTTP requests?', N'Junior', N'By prioritizing web standards, Remix applications can remain functional even if JavaScript fails to load or is disabled. This approach simplifies the development process by leveraging built-in browser features rather than reinventing complex client-side state management patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba368369-6c24-44a1-a9c6-baa7edc4a9d2', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you handle dynamic routes in Nuxt?', N'Intern', N'Dynamic routes are handled by using square brackets in the filename within the pages directory. For example, a file named [id].vue allows you to capture dynamic segments of the URL as parameters in your page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b4ab68b-2da0-4330-9c69-baad0431fb03', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of a Rails helper?', N'Junior', N'Helpers are modules that contain logic intended to be used in views to format data or generate HTML snippets. They help keep view templates clean by moving complex display logic out of the HTML files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e73b0ee-d0da-4970-b555-baad2f18e56c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the main benefit of Hono''s performance?', N'Intern', N'The main benefit is low latency and high throughput. Because Hono is lightweight and avoids excessive abstraction, it processes requests with minimal overhead, which is crucial for serverless and edge computing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31f02e60-1f27-42c6-9413-baae15b3c6b0', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do ''Consumer-Driven Contracts'' aid in microservice evolution?', N'Senior', N'Consumer-driven contracts ensure that producers are aware of the specific needs of their consumers, allowing them to test changes against those expectations before deployment. This prevents breaking changes from reaching production and facilitates safer, independent service releases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f7f78d7-5f78-4861-8fc0-baae5c558208', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''var'' keyword work in C#?', N'Junior', N'The var keyword allows the compiler to infer the data type of a variable based on the expression used to initialize it. It is still a strongly typed variable, meaning once the type is inferred at compile-time, it cannot be changed to a different type later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f7af1e9-dc68-493c-808d-baaef5ce5d9a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of ''shallowRef'' and when should it be used for performance optimization?', N'Senior', N'shallowRef creates a reactive reference that only tracks changes to the .value property itself, rather than recursively making all nested properties reactive. This is a significant performance optimization for large data structures where deep reactivity is unnecessary or computationally expensive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f808e43b-b76d-431a-9335-baaf853dadfb', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the main advantage of using a schema-based data format like JSON over plain text?', N'Intern', N'Schema-based formats provide a structured, predictable way to exchange and validate data between different systems. This reduces the risk of parsing errors and ensures that both the sender and receiver have a shared understanding of the data structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a256f30-ef2c-479c-8a75-baafa1821eb0', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a Functional Interface?', N'Intern', N'A functional interface is an interface that defines only one abstract method. To accurately determine the interface as functional, an annotation has been added @FunctionalInterface that works on the principle of @Override. It will designate a plan and will not allow to define the second abstract method in the interface. An interface can include as many default methods as you like while remaining functional, because default methods are not abstract.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a1b9822-d86b-4e97-accb-baaff746ca4b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you approach migrating a monolithic database to a microservices architecture without causing significant downtime or data inconsistency?', N'Senior', N'I would implement the strangler fig pattern, gradually routing traffic to new services while keeping the legacy database as the source of truth initially. I would utilize change data capture (CDC) to synchronize data between the old schema and new service databases to ensure consistency during the transition phase before fully decommissioning the monolith''s database access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'533024a9-988e-4d75-9739-bab0240e0305', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the limitations of Preact''s server-side rendering (SSR) capabilities?', N'Middle', N'Preact''s SSR is highly efficient but lacks some of the advanced features found in React''s modern streaming or Suspense-based server architectures. It is primarily designed for generating static HTML strings quickly, which is sufficient for most use cases but less robust for highly complex, data-heavy streaming requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c11302fe-a848-4328-8202-bab1f0b40431', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the +page.server.js file?', N'Intern', N'The +page.server.js file is used to perform data loading and form action handling that must occur on the server. It is primarily used for tasks that require access to databases or private credentials that should not be exposed to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec8a5a25-f8fb-4280-83a5-bab373464589', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI manage the event loop when running with Uvicorn?', N'Middle', N'Uvicorn is an ASGI server that manages the event loop and handles the low-level socket communication. It runs the FastAPI application within an async context, allowing the framework to schedule multiple concurrent requests on a single process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3ad571d-843b-4de0-a077-bab4e2ef5626', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach a trade-off where your solution is efficient but requires a complex setup?', N'Fresher', N'You consider the operational overhead for the team. If the complexity is manageable and the efficiency gains are substantial for the business, it is a good trade-off; if it creates a single point of failure or high maintenance burden, a simpler approach is better.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37387d27-f2fd-4aee-95da-bab62d726531', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Describe the ''Thundering Herd'' problem in the context of cache invalidation.', N'Senior', N'The Thundering Herd occurs when a frequently accessed cache key is invalidated or deleted, causing a surge of simultaneous requests to hit the database. This can lead to latency spikes or service outages, requiring strategies like request collapsing or randomizing expiration times to flatten the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c67005d-1327-4f95-92e6-bab64793d3df', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of the x-model directive?', N'Intern', N'The x-model directive creates two-way data binding between an HTML input element and the component''s state. Any change made in the input field automatically updates the underlying data, and vice versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcf5cb1b-123f-4744-9001-bab686d0090e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Describe the main advantage of Alpine''s ''no-build'' workflow.', N'Middle', N'The ''no-build'' workflow allows developers to drop a single script tag into an HTML file and start building immediately. This eliminates the complexity of Webpack, Vite, or other bundlers, making it highly accessible for quick prototypes or adding functionality to legacy websites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63273665-8302-4e79-9352-bab6e1a1f52c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What role does the ''scheduler'' play in a fiber-based backend?', N'Middle', N'The scheduler is responsible for distributing fiber tasks across available CPU cores or OS threads. It manages the run queue, handles fiber suspension/resumption, and ensures that no single fiber monopolizes the execution time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ced9432-1803-4895-bece-bab8f29188dc', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Describe the impact of ''DOM depth'' on browser rendering performance.', N'Senior', N'Excessive DOM depth increases the complexity of tree traversal for layout, style, and paint calculations, leading to higher CPU usage and slower interactions. Keeping the DOM shallow and efficient is critical for mobile performance, as it reduces the computational budget required for each frame update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12bebb25-7429-4cc0-a190-babc44dcd25a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Partition in Cassandra?', N'Intern', N'A partition is the collection of rows that share the same partition key. It is the basic unit of data distribution within the Cassandra cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4f3f08d-c386-45c6-b8d6-babc7417880b', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite perform type checking separately from the build?', N'Fresher', N'Vite uses esbuild for compilation, which focuses on speed and ignores type checking. By separating the type check process, Vite remains fast, and developers can run type checking as a separate step or via their IDE while they code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33590981-36e9-4ada-837d-babc86635a1a', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a Serializer in Ember Data?', N'Intern', N'A Serializer is responsible for translating data between the format expected by your application and the format provided by the API. It ensures that the JSON received from a server is correctly mapped to Ember models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3862deb-6988-4d3c-8a4c-bac0ac0ab0a0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you approach testing a mission-critical system that requires high availability?', N'Middle', N'I would implement comprehensive automated testing including unit, integration, and load tests, complemented by chaos engineering to simulate component failures. I would also ensure there are robust health checks and automated rollback procedures in place for any new deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0ce26dc-4b56-4294-8f92-bac29380266e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the difference between a global hook and a route-level hook?', N'Junior', N'A global hook runs for every request that enters the application, whereas a route-level hook is defined specifically for a single route or a group of routes. Global hooks are typically used for cross-cutting concerns like logging or CORS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c416acae-a207-4f7d-adb6-bac3f07cdddb', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the benefit of using Ember CLI for project management?', N'Middle', N'Ember CLI provides a standardized build pipeline, asset management, and testing environment that enforces project structure. It ensures consistency across Ember projects and simplifies tasks like dependency management and environment-specific configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f80d9710-0a12-4707-aec3-bac7e022e0ad', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the primary architectural benefit of using Chi''s middleware stack in a backend application?', N'Middle', N'Chi''s middleware stack allows for the modular execution of cross-cutting concerns like logging, authentication, and recovery before the request reaches the handler. This decoupling promotes cleaner business logic and makes it easier to inject or remove functionality across different routes without modifying the handlers themselves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb8372fc-8c26-4016-8f41-bac7ee9cd8ce', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle cache control?', N'Fresher', N'Remix allows you to set HTTP cache-control headers directly within your loader functions. This gives developers granular control over how long data should be cached by the browser or edge servers, improving overall application speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa24bcf7-9569-40df-9c3e-bacb1e2af50a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a property observer in Swift?', N'Intern', N'Property observers observe and respond to changes in a property’s value. They are called every time a property’s value is set, even if the new value is the same as the property''s current value, allowing you to trigger logic when updates occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2697e3d0-1197-4eed-8705-bacb4485ee46', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a schema and a database in PostgreSQL?', N'Intern', N'A database is a collection of schemas, while a schema is a namespace that contains database objects like tables, views, and functions. Schemas help organize database objects into logical groups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3a1610a-3b12-407f-915a-bacc8dc79b89', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the SQL SELECT statement?', N'Intern', N'The SELECT statement is used to retrieve data from a database. It allows users to specify which columns they want to view and from which table the data should be fetched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70a2d46b-b492-4daf-a9d5-bacf7b0bbec4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary purpose of a module bundler like Webpack?', N'Intern', N'A module bundler takes all the individual files in a project, such as JavaScript, CSS, and images, and combines them into optimized static assets. It resolves dependencies between these files to ensure they load in the correct order. This process allows developers to write modular code while ensuring the final output is efficient for browsers to execute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'723ee1d1-cce5-46e4-91ca-bad22c2f9799', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle error reporting during development versus production?', N'Junior', N'During development, error reporting should be enabled to display all warnings and notices to help identify bugs quickly. In production, error reporting should be disabled or logged to a file to prevent sensitive system information from being exposed to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'300910c4-b7e1-4048-9076-bad4c71570c4', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React updates screen in an application?', N'Fresher', N'React updates UI in three steps, 1. Triggering or initiating a render: The component is going to triggered for render in two ways. 1. Initial render: When the app starts, you can trigger the initial render by calling creatRoot with the target DOM node followed by invoking component''s render method. For example, the following code snippet renders App component on root DOM node. 2. Re-render when the state updated: When you update the component state using the state setter function, the componen''t state automatically queues for a render. 2. Rendering components: After triggering a render, React will call your components to display them on the screen. React will call the root component for initial render and call the function component whose state update triggered the render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f787d97-e36e-433f-9602-bad845496122', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the architectural considerations when choosing between Redis Sentinel and Redis Cluster for high availability?', N'Senior', N'Redis Sentinel is designed for high availability of a single primary-replica set, focusing on automated failover and monitoring without sharding. Redis Cluster is intended for horizontal scalability and high availability across multiple nodes, but it introduces complexity in client-side routing and limitations on cross-slot operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68148cad-e833-4802-bdbe-bad865d45a75', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle SEO?', N'Junior', N'Qwik is excellent for SEO because it sends fully rendered HTML from the server to the browser. Search engine crawlers can read the content immediately without needing to execute complex JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b981639-a3ca-4020-8d60-badcb22408ed', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ''Request Delegate'' in ASP.NET Core, and how does it relate to the pipeline?', N'Senior', N'A request delegate is a function that handles an HTTP request and is the fundamental building block of the middleware pipeline. Each middleware component wraps a request delegate, allowing it to delegate work to the next component in the chain or terminate the request early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b257cd3-1c91-4f28-b1f6-badf5788bba4', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Explain the role of the ''Ember Run Loop'' and why it is critical for performance.', N'Senior', N'The Run Loop is a queueing mechanism that schedules tasks like rendering, binding updates, and promise resolution into distinct phases. By batching these operations, it prevents unnecessary DOM thrashing and ensures that multiple data changes are reconciled in a single layout pass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a2e33c2-73f2-414b-b5d5-bae4d159f1cf', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for scaling a database that has reached its vertical capacity limit?', N'Senior', N'I evaluate horizontal scaling options, such as read replicas for read-heavy workloads or sharding for write-heavy workloads. If those are insufficient, I look at partitioning data by business domain to distribute the load across multiple independent database instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'805d6791-f0ac-4fa2-bf2d-bae7cef1e99d', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do LSM-trees differ from B-Trees in terms of write performance?', N'Senior', N'LSM-trees optimize for write-heavy workloads by buffering writes in memory and flushing them sequentially to disk as sorted files, avoiding the random I/O associated with B-tree page updates. However, they incur a performance penalty during reads due to the need to merge results from multiple levels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7687efd-f148-45d6-95cc-bae90864882b', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Does Dart support object-oriented programming?', N'Intern', N'Yes, Dart is a true object-oriented language. It supports classes, objects, inheritance, mixins, and interfaces, allowing developers to structure code using common OOP principles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ef78a72-77d1-4e0b-9aa0-baea1041315d', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does a database cluster ensure high availability during a hardware failure?', N'Middle', N'High availability is achieved through automated failover mechanisms, where a standby replica is promoted to the primary role if the active primary becomes unresponsive. This minimizes downtime and ensures the application remains accessible to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbc62e0f-c859-460c-8e85-baea97889942', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a database user and a role in PostgreSQL?', N'Junior', N'In PostgreSQL, they are essentially the same, but a role is a broader concept that can represent a user or a group of users. Roles are used to manage permissions and access control, making it easier to grant the same privileges to multiple users at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fcb642e-3973-41d5-bc7a-baeb3f33351e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does the Redis ''lazyfree'' mechanism improve performance during key deletion?', N'Senior', N'The lazyfree mechanism offloads the memory reclamation of large objects, such as massive sets or hashes, to background threads instead of deleting them in the main event loop. This prevents the primary thread from blocking while the allocator frees memory, which is critical for maintaining consistent latency in high-traffic environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44596ee9-5398-4550-ac8a-baebf186fea4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of using version control for database schemas during the development process?', N'Fresher', N'Versioning database schemas ensures that all team members are using the same structure and can easily track changes over time. It allows for automated migrations, reducing the risk of human error when deploying updates to different environments. This approach makes it possible to roll back changes if a migration introduces unexpected issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b43faaef-4682-4c65-a7ee-baed573c65b6', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does cache locality influence data structure design in C++?', N'Senior', N'Modern CPUs are optimized for sequential access and cache lines, meaning that storing related data contiguously in memory significantly improves performance. Data-oriented design, which favors arrays of structures or structures of arrays over pointer-chasing linked structures, is vital to maximizing cache hit rates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
