INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbb99d73-be1f-476c-8611-baefbddd2ff3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of ''Correlation IDs'' in troubleshooting?', N'Middle', N'Correlation IDs are unique identifiers passed through headers in distributed requests, allowing developers to link all logs and traces across different services related to a single user action. They are essential for reconstructing the path of a request in a complex architecture. Without them, it is nearly impossible to distinguish between interleaving requests from different users in the logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e67b6c4-f568-4bf9-92b9-baf053a8426f', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you mitigate the ''split-brain'' syndrome in a distributed cluster using a consensus algorithm?', N'Senior', N'Split-brain occurs when a network partition causes two nodes to believe they are the leader. Consensus algorithms like Raft or Paxos solve this by requiring a quorum, where a leader must receive acknowledgement from a majority of nodes to commit any state change, effectively preventing minority segments from acting independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
