INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'145d8b15-2b81-4033-a86d-baf10e287dfc', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the side effects of implementing a custom SynchronizationContext?', N'Senior', N'A custom SynchronizationContext allows developers to dictate how and where tasks are resumed, which is vital for framework-specific threading models. However, incorrectly implementing it can lead to silent deadlocks or performance degradation if the scheduler does not properly manage the underlying thread pool resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'838f43b5-12dd-4d9c-bb43-baf150eebe2c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the function of the ''HttpResponse'' type?', N'Fresher', N'HttpResponse is a struct that represents the final response sent back to the client. It allows the developer to set the HTTP status code, headers, and the body of the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'246148ac-acb0-4f0e-bcf8-baf7a5288cd6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is a ''CORS'' issue in Express?', N'Junior', N'CORS (Cross-Origin Resource Sharing) is a browser security feature that restricts web pages from making requests to a different domain than the one that served the page. You resolve this in Express by using the ''cors'' middleware to set the appropriate response headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'885656b2-5f8f-40ee-b1bb-baf8f176cb65', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle global state management across multiple UI frameworks?', N'Senior', N'Since components are isolated, global state cannot be easily shared between different UI frameworks using standard props. Developers must typically use browser-native solutions like the Custom Events API, the Web Storage API, or third-party libraries like Nano Stores that are framework-agnostic to share state across the island boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64da90c6-0e70-4953-807f-baf92d0e15f5', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain how the Java garbage collector decides when an object is eligible for collection.', N'Middle', N'An object becomes eligible for garbage collection when it is no longer reachable from any live thread or static reference. The JVM uses reachability analysis, traversing the object graph from garbage collection roots, such as active stack frames or static fields. Objects that cannot be reached are considered dead and are reclaimed during the next cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7acbd02a-d73d-486d-bba7-bafdb0ccb847', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django manage static and media files differently?', N'Middle', N'Static files like CSS, JavaScript, and images are part of the application infrastructure and are typically served by a dedicated web server like Nginx or a CDN in production. Media files are user-uploaded content and require secure storage and serving logic that is distinct from the static assets managed by the project''s source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c917682b-ab15-4d1e-a04c-bb014d5546e1', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is Nil-Coalescing Operator?', N'Fresher', N'The nil-coalescing operator (??) unwraps an optional if it contains a value, or returns a default value if the optional is nil. It provides a concise way to handle optional values without writing explicit if-else logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eecc85e3-c929-4513-bdd8-bb02332c46de', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the advantage of using Type Hints in Litestar?', N'Fresher', N'Using type hints allows Litestar to perform automatic validation and provide better IDE support. It creates a self-documenting code base where the expected data formats are clearly defined, reducing the likelihood of runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8793c07e-47f3-4e20-a874-bb033723d52a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI integrate with OpenAPI and why is this critical for microservices architecture?', N'Senior', N'FastAPI automatically generates an OpenAPI schema based on Pydantic models and path operation parameters. In a microservices ecosystem, this schema serves as a single source of truth, enabling automated client SDK generation, contract testing, and seamless integration with API gateways, which significantly reduces the integration overhead between services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54d5f0c9-9bdf-470a-b984-bb038c6d9385', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the ''doctype'' declaration at the top of an HTML file?', N'Middle', N'The doctype declaration informs the browser about the version of HTML the page is written in. It triggers ''standards mode'' in modern browsers, ensuring the page is rendered according to W3C specifications. Without it, browsers may switch to ''quirks mode,'' which attempts to emulate older browser behavior and causes inconsistent styling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff1e1bb3-3092-4db1-8f16-bb04389ed6ef', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between ''implements'' and ''extends'' in class inheritance?', N'Middle', N'Extends establishes an ''is-a'' relationship, inheriting both the implementation and the interface of the parent class. Implements creates a ''can-do'' relationship, where the class must provide its own implementation for all members of the interface, allowing for flexible polymorphic behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f344f8b3-ed3b-40f0-94fc-bb086e86b558', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the significance of variance annotations (covariant, contravariant, and invariant) in Scala generics.', N'Middle', N'Variance annotations control how subtyping relationships between complex types relate to the subtyping of their component types. Covariance allows a type to be a subtype of another if its parameter is a subtype, contravariance reverses this, and invariance requires exact type matches, which is essential for type safety in mutable structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35d4cd53-6212-4147-9844-bb0ad7078e52', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix use cookies and sessions?', N'Fresher', N'Yes, Remix provides built-in utilities to manage cookies and sessions. This makes it straightforward to handle user authentication and store temporary state across requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'660f72a9-4cc5-4733-ab9c-bb0f1de1894c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go lack traditional exception handling in favor of error values?', N'Middle', N'Go treats errors as regular values that must be explicitly checked, which forces developers to handle failure states at the point of origin. This design increases code readability and prevents hidden control flow, making the application''s behavior more predictable and easier to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3d6f977-8294-4c51-b9d7-bb127f56d4d3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the effort required for a refactoring task that lacks clear boundaries?', N'Senior', N'I define a ''success criteria'' scope and perform an exploratory analysis to map out the dependencies and potential break points. I then provide a phased estimate that includes a ''stop-loss'' condition, where we re-evaluate if the refactor proves more complex than the initial analysis suggested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd5b92e3-dae4-4830-a3eb-bb13935c9858', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When faced with two conflicting pieces of data, how do you decide which one to trust?', N'Intern', N'I would investigate the source and methodology behind each data point to identify potential biases or collection errors. I would check for consistency with other reliable metrics and attempt to isolate the variables that caused the discrepancy. If I cannot determine the cause, I would consult a mentor or perform a small experiment to validate the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a280f3d-a1b1-4c76-a583-bb17fa1ebdae', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix optimize the loading of assets like CSS?', N'Middle', N'Remix allows you to define CSS dependencies per route, ensuring that styles are only loaded when they are actually needed for the current view. This prevents style collisions and reduces the total amount of unused CSS shipped to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8577ff8b-a700-42ba-a111-bb19f1b5ae02', N'4c000000-0000-0000-0000-000000000005', N'What is the ''N+1'' query problem in ORM usage?', N'Middle', N'The N+1 query problem occurs when an application executes one query to fetch a list of items and then executes an additional query for each item to fetch related data. This causes a massive performance degradation and is typically solved by using eager loading or joining tables in the initial query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af577641-2826-41fd-be35-bb1b681e55c1', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a ''bundle'' in Webpack?', N'Intern', N'A bundle is the final output file generated by Webpack after it has processed and combined all the modules in your dependency graph. It contains all the necessary code for your application to run in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89778918-0915-43cc-a135-bb1be000e111', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the advantages of using functional programming patterns in R?', N'Middle', N'Functional programming patterns like mapping and reducing emphasize small, testable, and reusable functions. This approach reduces complexity, makes the code easier to parallelize, and avoids the common bugs associated with mutable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80149905-9ffa-4c5e-9588-bb1be0a6ca2f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you architect an API to prevent ''Denial of Service'' attacks beyond simple rate limiting?', N'Senior', N'Implement depth limits for nested queries (especially in GraphQL), enforce maximum payload sizes, and utilize request timeouts to prevent long-running queries from exhausting thread pools. Additionally, employ input validation and schema enforcement at the edge to reject malformed traffic before it hits core services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2831cfa-77d0-41a9-bd15-bb1be59da653', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the primary architectural trade-off when using Django’s built-in signals versus explicit method overrides?', N'Senior', N'Signals provide loose coupling, allowing decoupled applications to react to model changes without modifying the core logic. However, they make the execution flow implicit and harder to debug, whereas explicit method overrides like save() are more traceable but increase coupling between components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed27f10a-1021-4cbf-8ed1-bb1c53888aa2', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of a decorator in Fastify?', N'Intern', N'A decorator is a mechanism that allows you to attach custom properties or methods to the Fastify server instance, request object, or reply object. This is a common way to share utilities, such as database connections or helper functions, across different parts of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40cb2576-3503-4afc-b6a2-bb1e8b07a77a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the ''cost of delay'' concept in the context of trade-off analysis?', N'Intern', N'Cost of delay represents the economic impact of postponing the delivery of a feature or product. It helps engineers decide if it is worth spending more resources to ship a solution earlier or if waiting for a more refined, lower-cost approach is preferable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41ef9df9-9f4e-4c65-8ca2-bb1f6d23e6d4', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you implement a custom ''Voter'' in Symfony''s security system, and how does it relate to the Principle of Least Privilege?', N'Senior', N'Voters allow for granular, context-aware authorization logic that is isolated from the business services. They support the Principle of Least Privilege by centralizing access control checks, ensuring that only authenticated users with specific permissions can interact with sensitive domain resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'510d561d-30a5-4768-b1a5-bb1fb26c0227', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How do Go modules handle dependency management compared to older approaches?', N'Middle', N'Go modules provide a standard, versioned way to manage dependencies within the language ecosystem. They eliminate the need for a specific workspace structure and provide reproducible builds through a lock file, ensuring consistency across different development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df21db7c-520b-44a6-93db-bb2642c0ffd2', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the trade-offs of using Micronaut’s ''Introspection'' feature?', N'Senior', N'Introspection allows the framework to access bean properties at runtime without using traditional Java reflection, which is a major performance boost for JSON serialization and data binding. The trade-off is the generation of extra metadata classes, which slightly increases the size of the compiled artifact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'110346bc-ee72-4b3f-9941-bb26a9395156', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''fastify-cors'' plugin?', N'Intern', N'The fastify-cors plugin is used to enable Cross-Origin Resource Sharing (CORS) for the application. It allows you to configure which domains are permitted to interact with your API, which is essential for web security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13726c55-5b2b-4d3c-a085-bb27a898ada3', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a clustered index and a non-clustered index?', N'Fresher', N'A clustered index determines the physical order of data in a table and there can be only one per table. A non-clustered index creates a separate structure that points to the data, allowing for multiple non-clustered indexes on a single table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a5ec768-9be6-4ff8-84a4-bb28192e6159', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle exception management compared to standard try-except blocks?', N'Middle', N'Litestar provides a structured exception handling system where you can register global or route-specific exception handlers. This allows for centralized error reporting and consistent API response formats, preventing unhandled exceptions from leaking stack traces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2abd8a53-6cdc-49e6-9207-bb28d31ac081', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the role of Django signals and the risks associated with using them.', N'Middle', N'Signals allow decoupled applications to get notified when certain actions occur elsewhere in the framework. They introduce hidden side effects that make code harder to trace and debug, so they should be used sparingly, typically only when you cannot modify the source code generating the event.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e94fc4ea-dddd-43c9-8e48-bb296d031de8', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is Aspect-Oriented Programming (AOP)?', N'Intern', N'Aspect-Oriented Programming (AOP) complements Object-Oriented Programming (OOP) by addressing cross-cutting concerns, like logging or security settings, that cut across disparate modules and classes. AOP achieves modularity by: - Identifying cross-cutting concerns - Specifying join points in the code, where these concerns can be applied - Defining advice, which provides actions to be taken at these points For example, you might have logging code scattered throughout your application, triggered at various points. With AOP, you can consolidate this logic separately, marking points in the code (e.g., method calls) where logging should occur. Core Concepts - Aspect: A module of classes containing related advice and join point definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'340edc90-7b1a-4ca1-bae0-bb2a4eceff1e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s OpCache mechanism improve performance in a web server environment?', N'Middle', N'OpCache improves performance by storing precompiled script bytecode in shared memory, eliminating the need to parse and compile PHP scripts on every request. By skipping the compilation phase, the interpreter can execute the bytecode directly, significantly reducing CPU usage and latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d18c6b6-077e-4cbf-8b2b-bb2a9d0adbab', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does the ''contract'' concept work in Laravel?', N'Middle', N'Contracts are a set of interfaces that define the core services provided by the framework. They allow you to swap out implementations of a service, such as changing the mail driver, while ensuring that the rest of the application remains compatible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'844c7a6d-592b-4f99-b587-bb2e37103832', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does Columnar storage impact analytical query performance compared to Row-based storage?', N'Senior', N'Columnar storage allows the database to read only the columns required for a specific query, significantly reducing I/O and enabling better compression ratios. Row-based storage is optimized for transactional workloads where entire records are retrieved, making it less efficient for aggregate operations on large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eecdad2-ce01-4705-9c97-bb2f1128f214', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the primary benefit of using an API Gateway?', N'Middle', N'An API Gateway serves as a single entry point for all client requests, handling cross-cutting concerns like authentication, rate limiting, logging, and request routing. This simplifies client-side interaction and centralizes security and monitoring policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a2800de-5d62-4652-9049-bb37a4deb98d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using ''Panache'' in Quarkus for database interactions?', N'Middle', N'Panache simplifies the use of Hibernate ORM by reducing boilerplate code through the Active Record or Repository patterns. It provides a more fluent API that abstracts complex mapping and transaction management, making database interactions cleaner and faster to implement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8939f28b-2920-4727-883b-bb3b862ec9ae', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Isolation'' property in ACID ensure data integrity during concurrent transactions?', N'Middle', N'Isolation ensures that the intermediate state of a transaction is invisible to other concurrent transactions. By enforcing isolation levels, the database prevents phenomena like dirty reads or phantom reads, ensuring each transaction behaves as if it were the only one executing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
