INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39bb9763-75f3-4d1f-8d92-bb4830377a76', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the role of the ''dart:ffi'' library in Dart.', N'Middle', N'The Foreign Function Interface allows Dart to call C-style functions in native libraries. This is critical for performance-sensitive tasks, interacting with platform-specific hardware APIs, or reusing existing high-performance C/C++ codebases without writing platform-specific wrappers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
