INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d843413-4ffa-46b5-a724-bb56ba0e41f4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why should you avoid using ''async void'' in C#?', N'Middle', N'Async void methods cannot be awaited, which makes error handling and exception propagation significantly more difficult. If an exception occurs inside an async void method, it will crash the process because the caller has no mechanism to catch it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ab2c010-e145-4286-befc-bb57284f450b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Are SolidJS components functions that run every time state changes?', N'Junior', N'No, SolidJS components run only once when they are first mounted. The reactivity is handled by the observables inside the JSX, which update the DOM directly, making the component function execution unnecessary for subsequent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'300b92f4-8dcd-42ff-acc5-bb5c01bdbb4e', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is it recommended to use a function for the ''data'' option in Vue components?', N'Middle', N'Using a function ensures that every instance of a component gets a unique, independent copy of the data object. If a plain object were used, all instances of the component would share the same data reference, leading to unintended side effects when one instance modifies the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc6523b7-45f0-49cd-8f8a-bb5c947cc6ae', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js optimize font loading?', N'Fresher', N'Next.js automatically optimizes fonts by downloading them at build time and self-hosting them alongside the rest of your assets. This eliminates external network requests during page load and prevents layout shifts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f40cffc1-caf5-4217-92da-bb621e0e8048', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are route groups in Chi and why are they used?', N'Junior', N'Route groups allow you to organize routes under a common path prefix or apply a specific set of middleware to a subset of routes. This improves code organization and makes it easier to manage security or versioning for different API endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8efa1504-0980-4337-8c8d-bb63b17768fb', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the @use rule improve upon the older @import rule?', N'Middle', N'@use provides namespacing for variables, mixins, and functions, which prevents naming collisions across files. Unlike @import, which copies the entire contents of a file into the global scope, @use loads the module only once, improving compilation performance and project maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54ccdee9-4373-4cbd-b8c8-bb6649f77bf6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you remove falsy values from an array', N'Fresher', N'You can apply the filter method on the array by passing Boolean as a parameter. This way it removes all falsy values(0, undefined, null, false and "") from the array.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eff1558e-ba50-48f2-bd0d-bb66f35e3ac3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the security risk of exposing Gin''s default error messages.', N'Senior', N'Gin''s default error messages may leak sensitive internal information about the stack or database structure. In production, you should always implement a custom error handler that sanitizes the output, returning only generic messages while logging the actual details to a secure, internal store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5986426e-a17e-4c88-b0c3-bb697365c788', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do tombstones affect read performance and what are the risks of high tombstone density?', N'Senior', N'Tombstones represent deleted data and must be scanned during read operations until they are removed by compaction. An excessive number of tombstones can cause read timeouts and high memory pressure, as the system must process them to determine the current state of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af6f3560-6a6f-47e9-8c40-bb6bc41d6ab6', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the internal mechanism of Ruby''s garbage collector and its impact on application memory footprint.', N'Senior', N'Ruby uses a generational mark-and-sweep garbage collector that categorizes objects by age to optimize collection cycles. While this improves performance for short-lived objects, the heap can become fragmented, leading to memory bloat; developers must often tune environment variables like MALLOC_ARENA_MAX or adjust GC settings to balance throughput against memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f505c99-0a8c-42c3-a4c5-bb6c01abd9ae', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the impact of network partitions on a distributed message broker cluster?', N'Senior', N'A network partition forces the cluster to choose between consistency and availability according to the CAP theorem. Systems favoring consistency will stop accepting writes if a quorum cannot be reached, while systems favoring availability might allow conflicting writes or stale reads, requiring complex reconciliation later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43ad5671-8c50-4045-bb50-bb6c594b8ca0', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How will you find, in a string, the first word that rhymes with ''cake''?', N'Fresher', N'For our purpose, we will use the function search(), and then use group() to get the output. import re rhyme=re.search(''.ake'',''I would make a cake, but I hate to bake'') rhyme.group() ''make'' And as we know, the function search() stops at the first match. Hence, we have our first rhyme to ''cake''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'676efdf5-1a03-49d3-8fa4-bb6d537eeb44', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Kestrel in ASP.NET Core?', N'Intern', N'Kestrel is a cross-platform, open-source, event-driven, asynchronous web server for ASP.NET Core. It is included by default in project templates and is designed to be fast and lightweight, usually sitting behind a reverse proxy like Nginx or IIS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c882993-5dc0-40c5-b5e2-bb6f5d0fb702', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the difference between a key-value store and a relational database?', N'Intern', N'A key-value store like Redis is a type of NoSQL database that maps a unique identifier to a specific piece of data, making it optimized for simple lookups. In contrast, a relational database organizes data into predefined tables with rows and columns, focusing on structured data and complex relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'245d15c1-ecaa-493c-896d-bb77efd34e11', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why might you use a ''Template Engine'' with Litestar instead of purely JSON responses?', N'Middle', N'While Litestar is primarily an API framework, integrating a template engine is useful for Server-Side Rendering (SSR) scenarios where dynamic HTML is required. It allows the framework to serve both machine-readable APIs and human-readable web pages from the same codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c4df653-3c9d-40a9-b11c-bb7b70415aa9', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the risks of ''transmute'' in systems-level programming?', N'Senior', N'The ''transmute'' function forces the compiler to treat a value as a different type, completely bypassing the type system and borrow checker. It is extremely dangerous because it can violate memory layout assumptions, leading to undefined behavior if the source and target types are not perfectly compatible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbd4b4f4-0bda-4dbe-8ae6-bb7be52ff509', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between map and forEach functions?', N'Fresher', N'Both map and forEach functions are used to iterate over an arrays but there are some differences in their functionality. 1. Returning values: The map method returns a new array with transformed elements whereas forEach method returns undefined even though both of them are doing the same job. 2. Chaining methods: The map method is chainable. i.e, It can be attached with reduce, filter, sort and other methods as well. Whereas forEach cannot be attached with any other methods because it returns undefined value. 3. Mutation: The map method doesn''t mutate the original array by returning new array. Whereas forEach method also doesn''t mutate the original array but it''s callback is allowed to mutate the original array. Note: Both these methods existed since ES5 onwards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f34f2d40-ed9a-485f-8797-bb7c0c2263c8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the danger of focusing only on the most recent changes when troubleshooting?', N'Intern', N'While recent changes are common sources of errors, relying solely on them can blind you to long-standing issues or systemic problems. Always perform a thorough investigation rather than assuming the most recent change is the sole cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbb04c21-6c1d-4030-a93e-bb7c1fb221d9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s lazy evaluation strategy impact performance and control flow?', N'Middle', N'R only evaluates function arguments when they are explicitly called, which allows for advanced control flow constructs like short-circuiting logical operators. This can improve performance by avoiding unnecessary computations, but it can also delay the detection of errors within those arguments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
