INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91d1d229-6f55-4796-baa2-bb809f49c610', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Who developed NestJS? Why did they develop NestJS?', N'Junior', N'NestJS was developed by Kamil Myśliwiec, who is a Polish software engineer. He developed NestJS to address the lack of a consistent structure in Node.js applications and to bring powerful features of frameworks like Angular to the server-side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8e2a325-27f9-4f9f-9c7e-bb81de29a4a7', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is idempotency critical in distributed microservices communication?', N'Middle', N'In distributed systems, network failures often lead to retries, meaning a service might receive the same request multiple times. Idempotency ensures that performing the same operation multiple times does not result in unintended side effects, maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7c91da7-8e78-4088-b5f3-bb8290260102', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js event loop handle CPU-bound tasks, and what are the architectural consequences?', N'Senior', N'The event loop runs on a single thread, so CPU-bound tasks block the execution of all other events, including I/O callbacks. This leads to latency spikes and degraded throughput. For such tasks, offloading to Worker Threads or external microservices is necessary to keep the main event loop responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdba0612-5cc3-4451-a11e-bb83b282d4db', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of ''Live Coding'' in the Quarkus development workflow?', N'Junior', N'Live coding allows developers to see changes in their application instantly without manually restarting the entire process. When a file is modified, Quarkus automatically recompiles the necessary parts in the background, allowing for a much faster feedback loop during local development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
