INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e8193e2-cdeb-4ead-b0b4-bb87798c026e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the implications of choosing an unbounded array as a shard key?', N'Middle', N'Using an unbounded array as a shard key causes the database to create a document for every element in the array across different shards. This leads to data duplication and massive write amplification, which can severely degrade cluster performance and cause excessive resource consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b1cfc52-3398-4499-b60a-bb88f5250808', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When assessing the feasibility of a complex engineering requirement, what is your first step?', N'Middle', N'I break the high-level requirement into functional units and perform a gap analysis against our existing architecture. I identify the highest-risk components and conduct a proof-of-concept or research spike to validate whether the proposed approach is technically sound before committing to an estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba646da8-dde7-4511-8542-bb8929e83c43', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis maintain atomicity during multi-key operations in a cluster?', N'Senior', N'In a cluster, multi-key operations are only permitted if all involved keys hash to the same slot, which is enforced via hash tags. If keys reside in different slots, the operation must be orchestrated at the application level or via Lua scripts, as cross-slot transactions are not natively supported.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a5d119-d351-4fc6-8b35-bb89f4f0b488', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the purpose of the ''Next'' method within Gin middleware.', N'Middle', N'The Next method allows a middleware to pause its execution, pass control to the subsequent handlers in the chain, and then resume execution after those handlers complete. This is critical for post-processing tasks like logging response times or modifying response headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'968a61c4-031f-4079-8506-bb8b456188a2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle errors globally compared to traditional try-catch blocks?', N'Senior', N'Hono features an ''onError'' hook that intercepts exceptions thrown within any middleware or route handler. This centralized error handling allows for uniform response formatting and automated error logging without requiring repetitive try-catch blocks in every controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'290f13c4-6662-4269-a942-bb8f0b89ec24', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle code-splitting at the framework level?', N'Senior', N'Remix automatically splits code based on route boundaries. When a user navigates to a new route, only the necessary JavaScript for that route and its parent hierarchy is downloaded, optimizing the initial bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
