INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7423513d-7a85-4f84-9616-bb939adcaf56', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between firstChild and firstElementChild?', N'Fresher', N'1. firstChild: The firstChild property returns the first child node of the specified node, as a Node object. 2. firstElementChild: The firstElementChild property returns the first child element of the specified element. Difference: firstChild returns the first child node (an element node, a text node or a comment node). Whitespace between elements are also text nodes. firstElementChild returns the first child element (not text and comment nodes).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bb88bfe-231e-4681-aaa6-bb943ebfe04f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a ''deadlock'' in a database context?', N'Middle', N'A deadlock occurs when two or more transactions are waiting for each other to release locks, creating a circular dependency. PostgreSQL automatically detects these cycles and aborts one of the transactions to break the loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab31e787-f99f-4643-9f14-bb96d23a037a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the role of Isolates in Dart''s concurrency model.', N'Middle', N'Isolates are independent workers that do not share memory, communicating strictly through message passing. They allow Dart to perform computationally expensive tasks on separate threads without blocking the main UI thread, effectively utilizing multi-core processors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'664b2c8a-db20-48a4-a4b7-bb9c311f30ac', N'4c000000-0000-0000-0000-000000000005', N'How do you handle ''Hot Keys'' in a distributed caching system like Redis?', N'Senior', N'Identify hot keys through monitoring and mitigate them by implementing local in-memory caching on application servers, using query splitting, or distributing the key across multiple cache shards with a random prefix. These approaches reduce the pressure on a single node and prevent cache hotspots from crashing the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f5288a1-61b3-4897-ba49-bb9efb890066', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How does pagination influence API performance and user experience?', N'Middle', N'Pagination prevents the server from attempting to return large datasets in a single response, which would otherwise consume excessive memory and network bandwidth. It improves performance by limiting payload sizes and provides a more manageable experience for clients, especially on mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
