INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cd73e4d-74f6-4e57-873f-bba924553fe6', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Compare the security implications of Alpine''s expression evaluation using ''new Function'' against traditional template compilation.', N'Senior', N'Alpine evaluates expressions within the context of the component scope using a constructor approach, which effectively creates a sandbox for data access. While this allows for flexible syntax, it requires strict adherence to Content Security Policy (CSP) guidelines that might forbid ''unsafe-eval''. Developers must ensure that user-provided data is not directly injected into attributes to prevent Cross-Site Scripting (XSS) vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
