INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdfc7072-9751-4906-a112-bbc38fb7b4bb', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the DOM?', N'Junior', N'The Document Object Model is a programming interface for web documents. It represents the page so that programs can change the document structure, style, and content by treating the HTML as a tree of objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ca48604-a7ef-4686-8322-bbcc194776db', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you justify a trade-off decision to a non-technical manager?', N'Intern', N'I would explain the decision in terms of business impact, such as cost, timeline, or user satisfaction. Focusing on the ''why'' behind the trade-off helps them see how it aligns with the broader project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46a33cad-df08-427e-9ab1-bbcc240f88e1', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the WHERE clause in a SQL query?', N'Junior', N'The WHERE clause is used to filter records that meet specific criteria. It ensures that only rows satisfying the condition are returned by the query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c69eb29a-f962-4024-8262-bbce49afb571', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the primary architectural benefit of using a message broker for service decoupling?', N'Middle', N'It allows services to evolve, scale, and fail independently. If a consumer service goes down, the broker continues to hold the messages, allowing the producer to function normally and the consumer to catch up once it is back online.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33557d5e-7805-4174-a4fb-bbd0471dd270', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a compile-time error and a runtime error?', N'Junior', N'A compile-time error occurs when the code violates the syntax rules of the language, preventing the program from building. A runtime error occurs while the program is executing, such as dividing by zero or accessing invalid memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fa33c8f-4b12-4deb-9049-bbd19579a97c', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Describe the mechanism behind Kotlin''s delegation pattern compared to traditional inheritance.', N'Senior', N'Delegation is a composition-based alternative to inheritance where an object explicitly delegates the implementation of an interface to a secondary object. The compiler generates the boilerplate code to forward interface calls to the delegate, avoiding the fragility of deep class hierarchies and allowing for more flexible, runtime-composable behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96872f1c-9a76-4b19-b3fd-bbd493f680f1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''ILM'' (Index Lifecycle Management) feature improve long-term cluster scalability?', N'Senior', N'ILM automates the transition of indices through hot, warm, cold, and frozen phases based on age or size. This allows the system to move older, less frequently accessed data to nodes with cheaper storage hardware while reducing the memory footprint on the primary hot nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99d9eec4-7418-4100-b603-bbd544c51134', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s type inference system impact code readability and compilation?', N'Middle', N'Type inference reduces boilerplate by allowing the compiler to deduce types from context, making code cleaner and more expressive. However, excessive reliance on complex inference can increase compilation time as the compiler must perform more analysis to resolve types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aec7c5fe-3f29-4335-800b-bbd708bc4767', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the benefits of using Stored Procedures?', N'Middle', N'Stored procedures allow for pre-compiled code execution, which can reduce network traffic by sending only the procedure name rather than long query strings. They also enhance security by allowing access to data through defined interfaces rather than raw table access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aea17877-fc82-4a2e-b4e7-bbd77f969b86', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the significance of the ''hasChanged'' option in a property?', N'Junior', N'The hasChanged option is a function that allows you to define custom logic to determine if a property update should actually trigger a re-render. This is useful for complex objects where you might want to perform a deep comparison.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
