INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6286681-8aca-4d17-af9d-bbe1883930e8', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the main challenge of ''Distributed Tracing''?', N'Middle', N'The main challenge is maintaining a unique correlation ID across all service hops, including asynchronous message queues. Without consistent header propagation, it becomes impossible to map the full lifecycle of a single user request across the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6831e009-c577-4a7f-9e5b-bbe4906ef52d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle polyfills for older browsers?', N'Middle', N'Vite focuses on modern browser standards; for legacy browser support, developers typically use plugins like @vitejs/plugin-legacy. This plugin automatically generates two versions of the app—modern and legacy—and injects the necessary polyfills.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dd50993-66df-4e04-bb26-bbe62ba06e7c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does the ''lifespan'' event system improve upon the older ''startup'' and ''shutdown'' event handlers?', N'Senior', N'The lifespan system provides a single, unified context manager that handles both startup and shutdown operations in a structured way, ensuring that errors during startup prevent the application from starting entirely. It simplifies resource management by guaranteeing that shutdown logic executes even if the application initialization fails midway.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82dfe2fa-aa43-4325-89ff-bbe653c2dd0c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Describe the mechanism behind Spring Security''s Filter Chain.', N'Senior', N'Spring Security inserts a DelegatingFilterProxy into the standard Servlet filter chain, which delegates to a FilterChainProxy. This proxy manages a chain of internal security filters that execute in a specific order to handle authentication, authorization, CSRF protection, and session management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d29e0e4-95a2-40b0-bf28-bbebd3866816', N'954a0331-deff-4399-b588-96f39fec001d', N'What is control flow in Angular?', N'Intern', N'Angular''s built-in control flow, available from Angular 17 onwards, is a new syntax for handling conditional rendering and list iteration directly within component templates. It replaces the older structural directives like *ngIf, *ngFor, and *ngSwitch. The new syntax uses block-like structures starting with @: - @if: For conditional rendering, similar to *ngIf, supporting @else if and @else blocks. - @for: For iterating over collections, similar to *ngFor, supporting an @empty block and requiring a track function for efficient updates. - @switch: For rendering one block based on a condition, similar to *ngSwitch, using @case and @default blocks. This new control flow offers several advantages: - Improved performance, especially for @for loops due to mandatory tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcb1d4fb-ef31-4281-9af2-bbed6e5f0a51', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the Result enum handle errors in Rust?', N'Junior', N'Result is an enum used for error handling, representing either success as Ok or failure as Err. It requires the programmer to acknowledge potential errors, ensuring that failure cases are not ignored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bd42c28-a739-4cc4-a83f-bbedfd2ce3cd', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Describe the function of MVCC (Multi-Version Concurrency Control).', N'Middle', N'MVCC allows multiple versions of a data object to exist simultaneously, enabling readers to access a consistent snapshot without blocking writers. This mechanism significantly improves performance in read-heavy workloads by reducing contention for locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a7d825b-17b3-4e33-96aa-bbf0fca594c3', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between ''HashMap'' and ''Hashtable''?', N'Junior', N'HashMap is not thread-safe and allows one null key and multiple null values. Hashtable is synchronized, making it thread-safe, but it does not allow any null keys or null values, and it is generally considered legacy code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb422c2-dc88-4a98-980a-bbf13dede2dd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine the appropriate database consistency model for a new service?', N'Middle', N'I consider the CAP theorem and the specific needs of the business, such as the criticality of real-time accuracy versus system availability. If high availability is prioritized over immediate consistency, I would design the system to handle eventual consistency, ensuring that conflicts are resolved gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a234fb9c-12be-44a8-845d-bbf28aead843', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle ''missing values'' (NA) at the low-level data structure level?', N'Senior', N'R implements NA values as specific bit patterns within the underlying atomic vectors, allowing for native handling of missing data without separate indicator variables. This design choice ensures that arithmetic and logical operations can propagate missingness efficiently across datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04a58ae1-50f9-4548-8d10-bbf32721517a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Is Chi thread-safe for concurrent requests?', N'Intern', N'Yes, Chi is designed to be thread-safe. Because it does not rely on global state and uses the standard Go HTTP server, it can safely handle multiple incoming requests concurrently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'941b9462-3d52-449e-a788-bbf412b530bd', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Can Echo run on HTTPS?', N'Junior', N'Yes, Echo supports starting the server with TLS/SSL. You can provide a certificate and private key file to the server instance to ensure encrypted communication between the client and the backend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e872494-8a13-4600-a835-bbf50311b27c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between structured and unstructured data?', N'Intern', N'Structured data is highly organized and fits into traditional rows and columns, like in a spreadsheet. Unstructured data has no predefined format, such as social media posts, images, or videos, making it better suited for NoSQL databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'280f8b6a-1c50-4945-97a1-bbf7503a69c1', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of a controller in Rails?', N'Intern', N'The controller in Ruby on Rails serves as the processing hub for HTTP requests and determines the application''s response. It plays a central role in implementing the MVC architecture. By collecting user input from the view, handling data from the model, and finally responding back to the view, the controller acts as the fulcrum for application logic and external interaction. Key Responsibilities Input Handling The controller is responsible for processing and validating data received from the client. Any data manipulation or validation logic, such as form input sanitation, goes through the controller before updating the model. Model Interaction The controller mediates interactions between the view and the model. It retrieves and updates data from the model as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9de6f7bc-b558-4960-8f0d-bbf93301661f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What impact does Qwik have on the Core Web Vitals, specifically Largest Contentful Paint (LCP) and Interaction to Next Paint (INP)?', N'Middle', N'Qwik significantly improves Core Web Vitals by minimizing main-thread blocking during load. By deferring JavaScript execution until user interaction, it keeps the main thread free for rendering, leading to faster LCP and lower INP, as the browser does not need to process hydration tasks immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67706d33-4576-4cb2-a137-bbf9bc62b8ea', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ownership model influence the overhead of garbage collection compared to managed languages?', N'Senior', N'Rust eliminates the need for a runtime garbage collector by enforcing memory safety at compile time through the ownership and borrowing system. This removes the non-deterministic latency spikes associated with GC pauses, allowing for predictable performance and memory usage suitable for real-time systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8154c200-d95b-423b-9ea8-bbfabe25a331', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are Redis pub/sub channels, and what are their limitations?', N'Middle', N'Pub/Sub is a messaging pattern where publishers send messages to channels and subscribers receive them. The main limitation is that it is ''fire-and-forget''; if a subscriber is offline, it will not receive messages sent during its absence, making it unsuitable for reliable message queues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2223f1e-8cdc-48e3-a1cb-bbfb90d3ed66', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''context'' package in Chi?', N'Fresher', N'Chi uses the context package to pass request-scoped values, such as URL parameters, throughout the handler chain. This allows middleware and handlers to access data extracted from the route without needing to modify the function signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddf6db0f-318d-419b-9441-bbfdf33939a9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging, why is it important to consider the environment context?', N'Intern', N'System behavior can vary significantly between development, staging, and production environments due to differences in configuration or data scale. Understanding these differences helps identify whether the bug is environment-specific or a fundamental flaw in the logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7099e45d-e6f8-408c-8adf-bbfeda46d632', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the advantages and disadvantages of using a service mesh for inter-service communication?', N'Senior', N'Service meshes provide out-of-the-box observability, mTLS, and traffic routing control, simplifying microservice management. However, they introduce operational complexity and additional latency due to the sidecar proxy overhead in every request path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e0ccd30-9fe3-4ffa-b187-bbffc9988c37', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the ''Recoverer'' middleware used for?', N'Junior', N'The Recoverer middleware is used to catch panics that occur during the execution of an HTTP handler. It prevents the entire server from crashing and logs the stack trace, allowing you to return a 500 Internal Server Error instead of dropping the connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3631f5fc-07d7-4b7d-adbd-bc02577a6f40', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is meant by the ''undefined behavior'' (UB) in the C standard, and why is it dangerous?', N'Senior', N'Undefined behavior means the standard imposes no requirements on the program''s behavior, allowing the compiler to make assumptions that can lead to security vulnerabilities or silent data corruption. Compilers often optimize code based on the assumption that UB will never occur, which can result in unpredictable execution if the assumption is violated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b81a861-c826-445b-a02d-bc026a0040fa', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a global scope and a controller scope for Middleware?', N'Junior', N'Global scope middleware is applied to every route in the application. Controller scope middleware is limited to a specific controller and its defined routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37e212ed-675e-4cdc-81f7-bc055a35f27c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When should you introduce a load balancer into your architecture?', N'Junior', N'You should introduce a load balancer as soon as you have more than one instance of a service running. It is essential for distributing traffic, ensuring high availability, and performing health checks to remove failing instances from rotation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf231889-2962-412f-b22a-bc06741ef39a', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @content directive in a mixin?', N'Junior', N'The @content directive allows you to pass a block of custom styles into a mixin. This is extremely useful for things like media query mixins, where you want to wrap specific styles inside a screen-size condition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e01d01b8-4c29-4ae8-ac28-bc09dfb7dfee', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you decide between a temporary workaround and a permanent fix during an active incident?', N'Middle', N'The priority during an active incident is to restore service, so a temporary workaround is justified if it safely mitigates the impact on users. However, I would immediately create a tracking ticket for the permanent fix to ensure that the root cause is addressed once the system is stable. Relying on workarounds without follow-up leads to technical debt and a brittle system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af1de22f-6529-4889-89b6-bc0ad61e3288', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How is consistency handled in DynamoDB?', N'Fresher', N'DynamoDB offers two consistency models: eventually consistent reads and strongly consistent reads. Eventually consistent reads might reflect stale data, while strongly consistent reads guarantee the most up-to-date data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3203ed0-2f30-4388-9c8d-bc0b787f9da7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the significance of the ''__call__'' magic method in the context of functional programming.', N'Senior', N'The ''__call__'' method allows an instance of a class to be invoked like a regular function. This effectively blurs the line between data objects and executable code, enabling stateful objects to act as callables while maintaining internal configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'032712c1-1460-4848-8f90-bc0d954815ea', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''object'' keyword differ from a ''class''?', N'Junior', N'A ''class'' is a blueprint for creating objects, while an ''object'' is a singleton, meaning only one instance of it exists in the application. Objects are typically used to hold static-like members or utility methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bedfcd82-441f-42fe-9187-bc0efe11c9f8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''BeforeRequest'' hook?', N'Middle', N'The BeforeRequest hook is used to intercept requests globally before they hit any route handler. It is commonly used for request logging, adding custom headers, or performing early security checks that apply to every endpoint in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f901f7fe-ff4d-4023-9727-bc0efeb6005c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the role of the ''write barrier'' in Go''s concurrent garbage collection.', N'Senior', N'The write barrier is a hardware or software mechanism that intercepts pointer updates during the mark phase of garbage collection. It ensures that the collector maintains a consistent view of the object graph even as the application mutates pointers concurrently. This is essential for preventing the collector from incorrectly reclaiming objects that are still reachable, thereby maintaining correctness without stopping the entire program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24b96c42-a1a0-47ab-8433-bc10e197671a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How can you optimize SvelteKit for high-performance SEO?', N'Middle', N'You can optimize SEO by leveraging server-side rendering to ensure search engines receive fully populated HTML. Additionally, using prerendering for static content and dynamically updating meta tags via the ''app.html'' and layout components ensures that crawlers can accurately index your pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
