INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'765430bf-2f0a-40ba-9310-bc158d72be8a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the main risk of ''Microservice Sprawl''?', N'Middle', N'Microservice sprawl occurs when a system is decomposed into too many small, granular services, leading to unmanageable operational complexity. This increases the overhead of deployment, monitoring, testing, and networking, often outweighing the benefits of decoupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
