INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b07fccb9-9ab0-4347-b8e1-bc189a6d5d7c', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between an optimistic and pessimistic locking strategy?', N'Junior', N'Pessimistic locking assumes conflicts will happen and locks data as soon as it is accessed. Optimistic locking assumes conflicts are rare, checking for changes only at the time of the commit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f9be176-ca52-4c0c-88cf-bc19476910d2', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are Redux actions and reducers, and how do they interact?', N'Fresher', N'An action is a plain object that describes an intent to change the state, while a reducer is a pure function that takes the current state and an action to return a new state. When an action is dispatched, the reducer processes it to determine how the state should be updated, ensuring that state changes are predictable and traceable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd805949a-473a-400b-80c3-bc1a2b02b03c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using an array and a linked list for storing a collection of items?', N'Fresher', N'Choose an array if you need fast, random access to elements by index, as it provides constant time lookups. Choose a linked list if you frequently need to insert or delete elements in the middle of the list, as these operations are more efficient without needing to shift existing elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'255d7710-64ac-41f0-86c1-bc1b5558c907', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain what is horizontal scalability in mongodb?', N'Senior', N'Horizontal Scaling involves dividing the system dataset and load over multiple servers, adding additional servers to increase capacity as required. While the overall speed or capacity of a single machine may not be high, each machine handles a subset of the overall workload, potentially providing better efficiency than a single high-speed high-capacity server. Expanding the capacity of the deployment only requires adding additional servers as needed, which can be a lower overall cost than high-end hardware for a single machine. The trade off is increased complexity in infrastructure and maintenance for the deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07b18b13-b659-4c05-b297-bc1c19523017', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Interceptors used for regarding request/response transformation?', N'Middle', N'Interceptors can intercept the stream of data coming into or leaving the route handler, allowing for the modification of response bodies. This is commonly used for wrapping responses in standard envelopes, masking sensitive data, or converting DTOs into serializable formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'109adbc8-f78f-4f27-808c-bc1cee196857', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is an interface, and how does it differ from an abstract class?', N'Junior', N'An interface defines a contract of methods and properties that a class must implement but contains no implementation logic. An abstract class can provide some implementation details and can contain fields, whereas interfaces cannot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'581b2647-64d3-4470-acec-bc1da93a09bb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage multi-tenancy in a native environment?', N'Middle', N'Quarkus supports multi-tenancy through various extensions that allow for dynamic database switching or tenant-aware security contexts. These features are designed to be efficient, ensuring that the overhead of multi-tenant logic is minimized during request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'724b7005-33e7-4bf6-bd91-bc200db586a0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''Single Page Application'' mean in the context of Ember?', N'Intern', N'An SPA is a web application that loads a single HTML page and dynamically updates the content as the user interacts with the app. Ember manages this transition without needing to reload the entire browser page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0267ff7-7ceb-4123-8d52-bc21e9b9bc5f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the parent selector (&) in Sass?', N'Intern', N'The parent selector, represented by the ampersand, refers to the parent element in a nested rule. It is commonly used to style hover states or to target specific variations of a class name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f49633a-ca4d-40ef-9766-bc225383ce02', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the difference between a ''shallow'' and ''deep'' copy in the context of C# reference and value types.', N'Senior', N'A shallow copy duplicates the references of reference-type members, meaning both objects share the same underlying instance. A deep copy recursively duplicates all referenced objects, ensuring total independence between the original and the copy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1dc405e-37e6-488d-9d29-bc23e0bcf7fa', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift use Automatic Reference Counting (ARC) instead of a Garbage Collector?', N'Middle', N'ARC manages memory at compile-time by inserting retain and release calls, providing deterministic performance without the unpredictable pauses associated with garbage collection. This is crucial for resource-constrained environments like mobile devices where latency must be minimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd2bc8cb-706c-45ec-811f-bc27be1d53d6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs of using R''s ''quote'' and ''substitute'' functions?', N'Middle', N'These functions allow for non-standard evaluation, enabling the capture of unevaluated expressions rather than their resulting values. While powerful for building domain-specific languages and meta-programming, they can make code debugging significantly harder due to the decoupling of variables from their values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d5fdce3-cbe6-4d67-8841-bc2b5e6e0956', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''hasChanged'' property in Lit decorators?', N'Middle', N'The hasChanged function is a custom comparator used to determine whether a property update should trigger a re-render. It is particularly useful for complex objects or arrays where a shallow reference check is insufficient to detect meaningful data mutations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9a8fa91-d692-4bb9-a32f-bc2e08d1df77', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'If you have to choose between readability and memory efficiency, how would you approach the problem?', N'Intern', N'I would analyze the environment where the system runs. If the system has strict hardware memory limitations, efficiency is mandatory, but if the system runs on modern cloud infrastructure, readability is usually preferred to make maintenance and debugging easier for the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2907f50a-8eeb-49e0-88d0-bc32f2d2054c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the ''newtype'' pattern and why is it used?', N'Middle', N'The newtype pattern involves wrapping a primitive or foreign type in a tuple struct to provide type safety and encapsulate implementation details. It allows developers to implement traits for the new type that would otherwise be forbidden by the orphan rule.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78c4a5f4-eda3-4abf-bc09-bc32f8848a14', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''sink'' function?', N'Intern', N'The sink function is used to divert R output from the console to an external file. It is commonly used when a user wants to save the text-based results of a long analysis into a log file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'933087ad-99e3-4d9f-957f-bc33ecb737ca', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How do you handle ''Hot Keys'' in a distributed cache?', N'Senior', N'Hot keys occur when a single key receives a disproportionately high amount of traffic, potentially overloading a single node. Strategies to handle this include local caching on application nodes to reduce network load, or using request replication to spread the load across multiple cache partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62b23c52-0511-4907-8af5-bc360f9cd28e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How React Router is different from history library?', N'Fresher', N'React Router is a wrapper around the history library which handles interaction with the browser''s window.history with its browser and hash histories. It also provides memory history which is useful for environments that don''t have global history, such as mobile app development (React Native) and unit testing with Node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64d92734-a26d-4657-8128-bc3900378cfc', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the trade-offs of using FastAPI''s ''BackgroundTasks'' versus an ASGI-native event bus?', N'Senior', N'BackgroundTasks are scoped to the request lifecycle and are simpler to use, but they are tied to the specific request execution context. An event bus architecture decouples services completely, allowing for more complex event-driven patterns and better failure isolation in microservices environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a02e55e7-10e7-42e9-8e04-bc4073b47227', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik considered an ''O(1)'' framework?', N'Fresher', N'Qwik is called O(1) because the initial load time remains constant regardless of how large the application grows. Since it only loads the code needed for the immediate interaction, adding more features does not increase the initial JavaScript payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ee4ecc7-c32a-4e89-9126-bc4170120ebf', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a task that seems completely unfamiliar?', N'Fresher', N'I break the task down into smaller, researchable units and identify what I already know versus what I need to learn. I reach out to subject matter experts or review internal documentation to get up to speed quickly. By framing the unknown parts as specific learning objectives, I can approach the task with a structured plan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e741be-b48b-40d3-b0a2-bc419bc5a6b4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of the Erlang VM in Phoenix applications?', N'Fresher', N'The Erlang VM, or BEAM, is the runtime environment that allows Phoenix to handle millions of concurrent connections. It provides the lightweight processes and isolation necessary for high-performance backend systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cc61fb5-d8fc-4fe7-928b-bc41ceb4690c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach the trade-off between code reuse and service autonomy?', N'Middle', N'I prefer duplication over shared dependencies if the dependency couples services together. While shared libraries are good for common logic like logging, I avoid sharing business logic libraries between microservices because it creates tight coupling that prevents independent deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'439831a2-df0e-45be-a404-bc42d72a9829', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between vertical and horizontal scaling for a legacy database?', N'Senior', N'Vertical scaling is the first approach to address performance bottlenecks if the cost and downtime fit the business model. Horizontal scaling is reserved for when vertical limits are reached, involving complex strategies like sharding or read replicas, which introduce significant operational overhead and query limitations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36fbb4bc-feb5-49c9-ae2f-bc43e5eeab3d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the advantage of Alpine.js being ''DOM-centric''?', N'Intern', N'Being DOM-centric means Alpine.js works on the actual HTML elements currently in the browser. This eliminates the need for a virtual DOM or complex state synchronization, making it very easy to understand and integrate into existing static HTML sites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e48dc58-62e4-433f-96fe-bc443a048b3b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does consistent hashing help when scaling a distributed cache cluster?', N'Middle', N'Consistent hashing minimizes the remapping of keys when adding or removing cache nodes from a cluster. It ensures that only a small subset of keys needs to be moved, preventing massive cache misses that would occur with simple modulo-based hashing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'921749aa-56d1-48ae-894b-bc46641c44ad', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the use of the ''Depends'' function?', N'Junior', N'The ''Depends'' function is the core of the dependency injection system. It informs FastAPI that a specific argument to a path operation needs to be resolved by a separate function before the main code runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'270933d7-0ea8-44b0-bd59-bc4740a6a447', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of ''req.params''?', N'Junior', N'req.params is an object containing properties mapped to the named route ''parameters''. For example, if you define a route with ''/user/:id'', the value of '':id'' will be available inside the handler via req.params.id.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b48c4d7d-a961-4f1c-b6b2-bc48eb48e56c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'In what way does Micronaut ensure thread safety in non-blocking I/O operations?', N'Senior', N'Micronaut leverages the non-blocking nature of Netty and supports Project Reactor or RxJava for reactive streams. It encourages a programming model where expensive I/O operations are offloaded to dedicated thread pools, preventing the event loop from being blocked and ensuring consistent throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce1d38a4-d170-47e7-bdba-bc4955d019e5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a Database Cluster in PostgreSQL?', N'Intern', N'A database cluster is a collection of databases that are managed by a single instance of a running PostgreSQL server. It shares a single set of configuration files and is managed by one master process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baf90d45-ac5b-4665-88dc-bc4a95250a4f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Describe how Dart''s runtime detects and prevents memory leaks.', N'Senior', N'Dart uses a cycle-detecting garbage collector that identifies objects no longer reachable from the root set. However, developers must still manually manage resources that are not under GC control, such as native FFI resources or persistent stream subscriptions, which are common sources of memory leaks if not explicitly closed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f4de67a-ed0f-40ac-9a9a-bc5433bd92ba', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''observability'' more complex in microservices than in monolithic applications?', N'Middle', N'In microservices, a single user request often traverses multiple services, making it difficult to trace the flow of execution. Observability requires distributed tracing, centralized logging, and aggregated metrics to provide a unified view of the system''s health and performance across service boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3639051a-199d-4d67-a7f9-bc581184a03e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the x-ref directive?', N'Intern', N'The x-ref directive is used to reference specific DOM elements within a component. You can then access these elements using the $refs magic property, which is useful for direct DOM manipulation when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4ef7b23-11fe-4240-8eaf-bc5b7cfb227d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to loop inside JSX?', N'Fresher', N'You can simply use Array.prototype.map with ES6 _arrow function_ syntax. For example, the items array of objects is mapped into an array of components: But you can''t iterate using for loop: This is because JSX tags are transpiled into _function calls_, and you can''t use statements inside expressions. This may change thanks to do expressions which are _stage 1 proposal_.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d94577d-20dd-4180-9e48-bc5e7ec56504', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between setTimeout, setImmediate and process.nextTick?', N'Fresher', N'1. Set Timeout: setTimeout() is to schedule execution of a one-time callback after delay milliseconds. 2. Set Immediate: The setImmediate function is used to execute a function right after the current event loop finishes. 3. Process NextTick: If process.nextTick() is called in a given phase, all the callbacks passed to process.nextTick() will be resolved before the event loop continues. This will block the event loop and create I/O Starvation if process.nextTick() is called recursively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2032d765-2bfd-4549-bece-bc5ee0660298', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are nested routes in Next.js?', N'Junior', N'Nested routes are created by placing folders inside folders within the app directory. Each level of nesting maps to a segment of the URL, allowing for a structured hierarchy that mirrors your application''s UI design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36f71ec5-9c80-4a19-85ea-bc621c239fe5', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support multi-tenancy and what are the architectural implications?', N'Senior', N'Micronaut supports multi-tenancy through resolvers that identify the tenant from headers, parameters, or subdomains. This architecture allows developers to isolate data and configurations per tenant, which is crucial for building scalable SaaS applications while maintaining clear separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'927521af-547a-4ab3-a762-bc678902c2d7', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a requirement that seems technically impossible given the current system constraints?', N'Junior', N'I would document the constraints clearly and present them to the stakeholders to explain why the requirement is challenging. I would then suggest alternative approaches or a phased implementation that could achieve the desired goal within the existing limitations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c535818-42dd-4996-b07e-bc67e6d3cfb9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is ''Write-Ahead Logging'' (WAL) critical for database durability?', N'Senior', N'WAL ensures durability by recording all changes to a persistent sequential log before applying them to the actual data pages. In the event of a crash, the database can reconstruct the state by replaying the log, allowing for asynchronous data flushing which improves overall write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b473b51-97ec-4813-9cd7-bc68585445e7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''internal'' and ''public'' access modifiers?', N'Intern', N'Public access allows a member to be accessed from any code in the same project or a different project that references it. Internal access restricts visibility to code within the same assembly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e2f64f4-38d1-43c5-ae63-bc698af8f9c7', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the concept of middleware composition in Hono.', N'Middle', N'Hono uses a ''next'' function pattern to manage the middleware execution chain, similar to Koa or Express. However, because it is built for edge environments, the middleware execution is optimized to be non-blocking and highly efficient, allowing for rapid request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
