INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acbf7d82-a96e-44c2-889e-bc6f1d79e850', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary trade-off when choosing between strong consistency and eventual consistency in a distributed system?', N'Junior', N'Strong consistency ensures all users see the same data at the same time but can increase latency and decrease system availability. Eventual consistency prioritizes high availability and performance, accepting that data might be temporarily inconsistent across different nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be4e5792-0253-43a1-a23e-bc7528890c05', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi support Method-based routing?', N'Fresher', N'Yes, Chi provides specific methods for common HTTP verbs like GET, POST, PUT, DELETE, and PATCH. This allows you to map different request methods to different functions for the same URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1b9fdb0-8906-4621-8bb2-bc772f5073f3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is Svelte and how does it differ from traditional frameworks?', N'Fresher', N'Svelte is a component-based frontend framework that shifts the work from the browser to a compile step. Unlike frameworks that use a virtual DOM, Svelte compiles your code into tiny, highly optimized vanilla JavaScript that surgically updates the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad40f284-3d16-411f-8043-bc78408b290c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass operators work?', N'Intern', N'Sass supports standard mathematical operators like addition, subtraction, multiplication, and division. These allow you to calculate values dynamically, such as adjusting widths or font sizes relative to other elements directly within your stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98aa4048-f887-46cf-a2d5-bc7889a42207', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What does the ''suspend'' modifier mean?', N'Junior', N'The ''suspend'' modifier marks a function as one that can pause execution and resume later without blocking the thread it is running on. These functions can only be called from within a coroutine or another suspend function. This is the fundamental building block for asynchronous, non-blocking code in Kotlin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f58c3d29-82ba-489f-b0c0-bc801f04935a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the time required for a feature when you have significant uncertainty regarding the underlying architecture?', N'Middle', N'I would break the task into smaller sub-components and identify the specific areas of technical risk. I would then provide a range-based estimate rather than a single point, noting that the upper bound accounts for potential spikes or research time needed to resolve those uncertainties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'707f5b81-4598-49dd-97bc-bc8132e25727', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the significance of the ''working set'' in MongoDB performance tuning?', N'Senior', N'The working set represents the subset of data and indexes that the application accesses most frequently. Ideally, the entire working set should reside in physical memory (RAM); if the working set exceeds available RAM, the database will experience frequent page faults, leading to significant performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df746eb1-f906-4933-bc3a-bc82d1a1fba5', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What architectural challenges arise when implementing a many-to-many relationship in DynamoDB?', N'Senior', N'DynamoDB does not support joins, so many-to-many relationships require data denormalization or multiple queries. You must either store redundant data or use GSI design patterns to map relationships, which increases the complexity of maintaining data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd51a3d73-a155-4595-b3bf-bc863dc8e617', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Discuss the impact of using ''async/await'' in Express middleware on stack trace visibility.', N'Senior', N'Modern Node.js versions have improved stack traces for async functions, but historically, async/await could obscure errors if not properly caught. Always wrapping async handlers in a utility that catches errors and passes them to ''next'' is essential for maintaining visibility and preventing unhandled promise rejections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6f8cf49-78a7-4aab-a5b5-bc86c30f89f4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is it important to use ''Result'' types in Rocket handlers?', N'Junior', N'Using Result in your handlers allows you to return either a successful response or an error. This makes error handling explicit and ensures that your application can communicate failure states effectively to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19072ca9-85db-48ea-89bb-bc8855d0f4cd', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the primary difference between horizontal and vertical scaling, and when would you prefer one over the other?', N'Middle', N'Vertical scaling involves increasing the capacity of a single server by adding more CPU or RAM, while horizontal scaling involves adding more servers to the pool. Horizontal scaling is generally preferred for distributed systems as it provides better fault tolerance and avoids the hard physical limits of single-machine upgrades.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05a44f8f-6e1f-4274-8291-bc8e61720682', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What happens if a user interacts with a page before the JavaScript is loaded?', N'Fresher', N'Qwik catches the user interaction through global event delegation. It then quickly fetches the necessary code chunk for that specific interaction, executes it, and resumes the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5aa6917-9baa-4479-9ca2-bc8eb4db5074', N'4c000000-0000-0000-0000-000000000005', N'How does database sharding improve performance, and what are the main risks associated with it?', N'Middle', N'Sharding improves performance by splitting a large database into smaller, more manageable pieces called shards, which distributes the read and write load across multiple servers. The main risks include increased complexity in managing cross-shard queries, the potential for unbalanced data distribution, and the risk of a single shard becoming a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79a19e26-d5c3-4d5e-bf8d-bc8fed6545f5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is ''joining'' data difficult in NoSQL?', N'Junior', N'In NoSQL, data is often distributed across multiple servers, making it technically challenging to perform joins between different nodes. To maintain speed, developers are usually encouraged to structure data so that all necessary information is retrieved in a single read.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ea5e73c-d99e-4664-8103-bc9064b574ce', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a schema-less database?', N'Intern', N'A schema-less database is one that does not require a rigid, predefined structure for the data it stores. This allows developers to insert data with different fields or formats into the same collection without needing to alter the database structure first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'433d6d29-aa7d-4ddd-950e-bc92778b3b7d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the function of the ''public'' folder in a Vite project?', N'Intern', N'The public folder is used for static assets that should not be processed by Vite. Files placed here are copied directly to the root of the build output and can be accessed via absolute paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aed0b89c-21c0-40c2-a85b-bc95db1409e0', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain how Preact handles prop types and why it excludes them from the core library.', N'Senior', N'Preact excludes PropTypes to maintain its small core size, shifting the responsibility to external utility libraries or TypeScript for compile-time validation. This design choice forces a separation of concerns, ensuring that runtime performance is not penalized by validation logic that is often only needed during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdabebf6-7f8e-4509-b4b4-bc9690b04a36', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the trade-off between Svelte''s compile-time optimizations and build-time performance?', N'Senior', N'The main trade-off is that Svelte''s compilation process is more computationally expensive than the transpilation process of runtime-heavy frameworks. In large projects, this can increase CI/CD build times, though this is usually offset by the significant runtime performance gains for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d83f7ce-f5e9-412b-9f94-bc97acfec866', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Is Gin suitable for building a REST API?', N'Intern', N'Yes, Gin is specifically designed for building REST APIs due to its native support for HTTP methods, JSON handling, parameter extraction, and structured routing. It is one of the most popular choices in the Go ecosystem for this purpose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c3413d0-1f1d-48ea-871c-bc98c52a3e73', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if an action type is not recognized by a reducer?', N'Fresher', N'If a reducer receives an action type it does not handle, it should simply return the current state unchanged. This ensures that the application state remains stable when unknown actions are dispatched.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfb1002d-8618-4af1-9bae-bc98fddea08b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'In a distributed system, how would you implement rate limiting within a Gin application?', N'Senior', N'Rate limiting is best implemented as a custom middleware that tracks request counts per user or API key in a distributed store like Redis. This ensures that limits are enforced consistently across multiple instances of the service, rather than being local to a single process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce3a4785-397d-46de-93a8-bc99a2cd1c26', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus achieve a smaller memory footprint compared to traditional Java frameworks?', N'Middle', N'Quarkus uses GraalVM to compile applications into native executables, removing the need for the full JVM and JIT compiler. Additionally, it eliminates unused classes and reflection-heavy code paths during the build process, leading to leaner memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e45170e8-7827-4ee4-a132-bc9b46e69f76', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Does Litestar support sessions?', N'Fresher', N'Yes, Litestar has built-in support for session management. It allows the server to store stateful information about a user across multiple requests, usually handled through cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d7ca54c-69bd-4671-aacd-bc9c4be58ac5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging a distributed cache issue, what aspects do you prioritize?', N'Middle', N'I would focus on cache invalidation policies and data consistency, specifically checking if the cache is serving stale data due to race conditions or improper updates. I would also monitor cache hit/miss ratios and eviction policies to ensure that the cache is not being cleared too frequently or holding onto corrupted entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4887f9ec-0ed0-4a36-9283-bca04f86014f', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the shadow DOM?', N'Intern', N'The shadow DOM is a browser technology that provides encapsulation by creating a separate scope for a component''s DOM and CSS. It prevents the component''s styles from leaking out and global styles from affecting the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cbab2ca-8941-4ce4-8b40-bca1b24a7ab2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are interfaces in TypeScript and why are they used?', N'Junior', N'Interfaces are a way to define the structure or shape of an object. They ensure that objects adhere to a specific contract regarding their properties and methods, which makes code more predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a0eceea-c8e8-454c-ac52-bca25d7b23fe', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs of using R''s ''vectorization'' versus explicit loops?', N'Senior', N'Vectorization leverages highly optimized C/Fortran code to perform operations on entire arrays at once, significantly reducing the overhead of the R interpreter''s loop machinery. While it offers superior performance, it can sometimes be memory-intensive as it requires creating temporary intermediate vectors during complex chain operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28fcd542-a417-451e-91fe-bca4a88a6f82', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the hoisting behaviour inside let/const blocks, and how does it affect switch statements?', N'Intern', N'let and const are block-scoped and hoisted within their block to the TDZ. A switch statement''s {} is a single block — all case clauses share the same block scope. This causes a subtle bug: a let declared in one case is technically in scope (hoisted) for all other cases in the same switch block, causing a SyntaxError if another case attempts to declare the same name. Example: Real-World Use Case: This exact bug has appeared in production Redux reducers where developers switched from var to let during a linting migration. All case branches in a reducer''s switch share one block, so re-declaring let draft in multiple cases causes a SyntaxError caught only at parse time — blocking the entire app from loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8612d299-2359-49e6-a14f-bcaa9bba1257', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is type narrowing and why is it useful?', N'Middle', N'Type narrowing is the process of moving from a broader type to a more specific type within a conditional block, such as using type guards. It allows TypeScript to understand exactly what a variable is in a specific scope, preventing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'313a932e-5255-4051-bc9a-bcab01ce6b3f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the primary benefit of Gin''s tree-based routing compared to standard libraries?', N'Middle', N'Gin uses a Radix tree structure which allows for significantly faster lookup times than iterative list-based routing. This approach ensures that path matching performance remains constant regardless of the number of registered routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0592f6e-30b7-47e0-a43d-bcabb87f91d6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does an index affect insert and update performance?', N'Junior', N'While indexes speed up read operations, they can slow down insert and update operations. This happens because the database must update the index structure every time the indexed data is modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a043907-56d4-4351-ae95-bcafac7d6833', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How do Generational Garbage Collectors leverage the Weak Generational Hypothesis?', N'Senior', N'The hypothesis states that most objects die young, so generational collectors focus their efforts on the ''Young Generation'' to reclaim memory frequently and efficiently. By segregating objects based on their age, the collector can perform minor collections on short-lived objects without needing to traverse the entire heap, minimizing pause times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfcf9279-1c69-4143-b3ea-bcb215bc8ed2', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Pattern Matching work in Scala?', N'Fresher', N'Pattern matching is a mechanism for checking a value against a series of patterns and executing the corresponding code block. It is much more powerful than a traditional switch statement because it can deconstruct complex data types and objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bd800c9-0e93-4d5d-a7fd-bcb2dc9d05f9', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''sealed'' keyword affect class design and performance?', N'Middle', N'Sealed prevents a class from being inherited, which can protect the intended design of a component. From a performance perspective, it can allow the JIT compiler to perform devirtualization optimizations since it knows the method cannot be overridden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6022290d-3971-48b2-b64f-bcb32079c9e9', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What ARIA and screenreaders are, and how to make a website accessible?', N'Senior', N'Screen readers are software programs that provide assistive technologies that allow people with disabilities (such as no sight, sound or mouse-ing ability) to use web applications. You can make your sites more accessible by following ARIA standards such as semantic HTML, alt attributes and using [role=button] in the expected ways', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0679cc0e-70db-438c-a4a3-bcb532df736d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why would you choose a typed language over an untyped or dynamically typed one?', N'Fresher', N'Typed languages catch errors at compile-time, which leads to more robust and predictable code as the project grows. Dynamically typed languages allow for faster prototyping and more flexible code, but they are more prone to runtime errors that are harder to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59fa51cd-2b50-4a03-9bca-bcb8adcaa84a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between document load and DOMContentLoaded events', N'Fresher', N'The DOMContentLoaded event is fired when the initial HTML document has been completely loaded and parsed, without waiting for assets(stylesheets, images, and subframes) to finish loading. Whereas The load event is fired when the whole page has loaded, including all dependent resources(stylesheets, images).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1103730-e212-401d-aa3d-bcbb6301b1f6', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''noscript'' element?', N'Middle', N'The ''noscript'' element defines content to be displayed to users who have disabled JavaScript in their browser or whose browser does not support it. While it is less common to build sites that rely on this today, it is still a best practice for providing a graceful fallback or a message explaining why the application is not functioning. It ensures that users are not left with a completely blank or broken screen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c67c5115-1f9d-491b-967e-bcc346d0cc92', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro’s partial hydration approach affect SEO compared to a standard React-based SSR setup?', N'Senior', N'Since Astro ships zero JavaScript by default for static content, search engine crawlers receive fully rendered HTML without needing to execute client-side scripts. This removes the risk of indexing delays or failures common in client-side rendered apps, ensuring optimal SEO performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb561a6a-e539-40d6-8aa6-bcc5ba7d46c4', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Discuss the internal mechanism of the AdonisJS ''Hook'' system in models.', N'Senior', N'Model hooks are event-driven triggers that execute before or after specific lifecycle methods like saving or deleting. They run synchronously by default, meaning heavy operations inside a hook will block the event loop, requiring developers to offload intensive tasks to a separate queue system to maintain high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70ee88ea-3331-4a84-99d4-bcc5f264f9b5', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the primary architectural difference between jQuery''s AJAX implementation and the modern Fetch API?', N'Middle', N'jQuery''s AJAX is based on the older XMLHttpRequest object and provides a heavy abstraction layer with built-in data serialization. The Fetch API is a native, promise-based interface that provides more granular control over requests and responses without the overhead of a large library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f1c085e-2052-4dee-96ca-bcc8f27dded0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you use window.history API?', N'Fresher', N'The window.history API allows you to manipulate the browser''s session history. You can use history.pushState() to add a new entry to the history stack, history.replaceState() to modify the current entry, and history.back(), history.forward(), and history.go() to navigate through the history. For example, history.pushState({page: 1}, "title 1", "?page=1") adds a new entry to the history. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ea31800-6300-46cc-a2ce-bccb236c3857', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Describe the security implications of using Express''s ''res.render'' with unsanitized input.', N'Senior', N'If template engines are used with user-provided input without proper escaping, the application becomes vulnerable to Cross-Site Scripting (XSS) or Server-Side Template Injection (SSTI). It is critical to use template engines that provide automatic context-aware escaping by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ed692c9-cac6-41d2-a59d-bcce3a6e86c3', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of Qwik City?', N'Junior', N'Qwik City is the meta-framework built on top of Qwik that provides features like file-based routing, layout management, and data loading. It is designed to simplify the development of full-stack applications by handling infrastructure tasks automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1868c285-7563-4125-b1fc-bcced1614beb', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between ''get()'' and ''filter()'' in the ORM?', N'Junior', N'The ''get()'' method returns a single object matching the given lookup, raising an error if zero or multiple objects are found. In contrast, ''filter()'' returns a QuerySet containing all objects that match the criteria, returning an empty list if no results are found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'864d9359-05d6-464f-97b4-bcd023355a40', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Discuss the trade-offs of using ''Semi-Synchronous Replication'' in terms of data loss.', N'Senior', N'Semi-synchronous replication ensures that at least one slave has received the transaction before the master acknowledges the commit to the client. This significantly reduces the window for data loss compared to fully asynchronous replication, though it introduces a latency penalty on every write operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c779b73e-daf5-4593-8aca-bcd0c85518c2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono achieve its small file size?', N'Intern', N'Hono achieves a small footprint by avoiding heavy dependencies and relying on built-in browser-like APIs. This makes it ideal for environments where cold start times and bundle sizes are critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e446c332-1673-49b0-b658-bcd633170ac3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the architectural considerations for implementing a multi-tenant application using Symfony?', N'Senior', N'Multi-tenancy requires isolating data and configuration per tenant, often achieved via dynamic database connection switching or discriminator columns. Key challenges include managing request-scoped services, global event listeners that must be tenant-aware, and ensuring that security contexts are strictly partitioned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52836a89-b411-49c8-9cb3-bcd65e410bca', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the trade-offs between monolithic and microservices architecture?', N'Senior', N'A monolith is preferred for early-stage development to maximize velocity and minimize cross-service communication overhead. Microservices are justified when the organizational size increases to the point where team autonomy, independent deployment cycles, and fine-grained resource scaling provide a net benefit that outweighs the operational complexity of distributed tracing and service discovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65ac57c1-e0a5-449a-858a-bcd72ed0ea59', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between prototype and proto in JavaScript?', N'Fresher', N'1. Proto: It is an actual object that provides a way inherit to inherit properties from JavaScript with the help of an object which is created with new. Every object with behavior associated has internal property [[prototype]]. Syntax: Example: &#9885; Try this example on CodeSandbox 2. Prototype: It is a special object which means it holds shared attributes and behaviors of instances. It is a way to inherit properties from javascript as it is available in every function declaration. Syntax: Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aa7010c-9b31-498b-afa2-bcd769d3386c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is it important to keep indexes lean and avoid over-indexing?', N'Middle', N'While indexes speed up read operations, every index adds overhead to write operations because the index structure must be updated whenever data is inserted, updated, or deleted. Over-indexing can lead to significant performance degradation during write-heavy workloads and consumes unnecessary storage space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de871a77-dd91-4266-a8ad-bcdc453eb93b', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the trade-off of using a microservices architecture?', N'Middle', N'Microservices offer improved scalability, technology flexibility, and independent deployment, but they introduce significant operational complexity. Challenges include managing inter-service communication, distributed data consistency, and the overhead of service orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc7b97d4-9760-4758-b041-bcdcd0bd76be', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why do distributed databases often choose BASE over ACID?', N'Middle', N'The CAP theorem implies that in the presence of a network partition, a system must choose between consistency and availability. BASE (Basically Available, Soft state, Eventual consistency) prioritizes availability and scalability, accepting that data might not be immediately consistent across all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0692c64d-03bd-46c7-8c1a-bcdfbcbd8c5e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a formal parameter vs an actual argument?', N'Intern', N'A formal parameter is the variable declared in the function signature to receive input. An actual argument is the value or variable passed to the function when it is called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df327991-0418-4b52-9275-bce0eaba0b0d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How does ''parking lot'' or ''buffer'' time help in project estimation?', N'Fresher', N'Buffer time acts as a safety net to absorb unexpected delays, such as technical difficulties, environment issues, or requirement changes. It acknowledges that estimations are not perfect and that reality often deviates from plans. Incorporating a reasonable buffer makes the project schedule more resilient and reduces the stress of meeting strict deadlines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76eda8c6-7537-41d1-afac-bce22e2520d3', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between an ''app'' directory and the older ''pages'' directory?', N'Fresher', N'The app directory is the newer, recommended approach that supports React Server Components and nested layouts. The pages directory is the legacy system that primarily relies on client-side rendering or basic server-side methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0171870f-800a-4e83-b1f9-bce2f93ba458', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do ''Global Checkpoints'' ensure data consistency across primary and replica shards?', N'Senior', N'Global checkpoints track the highest sequence number that has been processed by all active shards in a replication group. This ensures that when a primary fails, the replica promoted to primary has all the acknowledged data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcc9c6c1-49df-45d0-bfd6-bce5efc8c89b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle memory consumption compared to other Java frameworks?', N'Fresher', N'Because Micronaut avoids heavy use of reflection and runtime proxies, it requires less heap memory. This makes it highly efficient for deployment in containerized environments where memory resources are limited.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38398384-6b56-4a9e-88ea-bce9a3a94c0d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik considered ''Server-Side Rendering'' (SSR) focused?', N'Intern', N'Qwik is heavily focused on SSR because it generates the full HTML for the page on the server. By sending a fully formed page with serialized state to the browser, it eliminates the need for the browser to do heavy lifting on startup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'524459d7-0618-43fb-95f5-bcec43f0b868', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass mixins differ from placeholders?', N'Middle', N'Mixins are used to generate CSS blocks that can be included in multiple selectors, often accepting arguments for flexibility. Placeholders are used with the extend directive to share common styles across selectors without duplicating the CSS code in the final output, resulting in smaller file sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91714afd-2b57-419a-ab2c-bced01115739', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'In what scenario would a fiber-based architecture perform worse than a standard thread-per-request model?', N'Middle', N'If the workload is primarily CPU-intensive, fibers provide no performance benefit and may even introduce overhead due to the scheduler. Threads are better suited for heavy computation because they can be preempted and managed effectively by the OS scheduler for balanced CPU distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bf6568b-0602-439e-96f6-bcef0e0d6379', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is an extension function?', N'Intern', N'An extension function allows you to add new functionality to existing classes without having to inherit from them. It is called as if it were a member function of the original class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6cdc4a3-9016-4302-8b3e-bcf0467fc40d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What are the trade-offs between push-based and pull-based monitoring architectures?', N'Senior', N'Pull-based systems, like Prometheus, provide better control over service discovery and prevent monitoring overload since the server controls the scrape rate. Push-based systems are superior for ephemeral workloads like serverless functions or batch jobs that do not exist long enough to be scraped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c0476e0-eb53-470a-8160-bcf7d2db8920', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s dependency injection container facilitate modular architecture?', N'Senior', N'The container serves as a centralized registry that manages the lifecycle and instantiation of objects like services and controllers. By using dependency injection, components remain decoupled from their dependencies, allowing for easier unit testing through dependency mocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56026060-eb02-498f-9fc4-bcf7e38c533d', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you secure your NestJS application?', N'Fresher', N'Securing a NestJS application involves several aspects, including authentication, authorization, data validation, and error handling. Here are some ways to secure your NestJS application: Authentication: You can use Passport.js, a popular authentication library, which is integrated into NestJS via the @nestjs/passport module. Passport supports a wide range of authentication strategies, including OAuth, JWT, and local username/password. Authorization: NestJS provides the @Roles() decorator and AuthGuard to handle role-based access control. You can define roles on your route handlers and then use AuthGuard to check if the authenticated user has the required roles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ae72f08-8911-466e-8799-bcf892c85278', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Describe the trade-offs of using a ''push'' model versus a ''pull'' model for message delivery.', N'Senior', N'A push model reduces latency as the broker immediately sends data to consumers, but risks overwhelming slower consumers. A pull model allows consumers to process messages at their maximum throughput, preventing buffer overflows, but introduces polling latency and empty-request overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'685a7eb4-a3eb-4c79-be80-bcf977073b2a', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between Quarkus''s ''Agroal'' and traditional connection pooling?', N'Senior', N'Agroal is a high-performance, low-overhead connection pool designed specifically for the Quarkus ecosystem. It is optimized for small memory footprints and integrates seamlessly with build-time configuration to ensure that database resources are managed efficiently in cloud-native environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'055e8039-b520-4a4b-89c1-bcf9d576b498', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your code handles errors gracefully?', N'Junior', N'I anticipate potential failure points, such as network timeouts or invalid user input, and implement proper error handling to catch these exceptions. Instead of letting the application crash, I provide meaningful error messages to the user and log the details for debugging purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1ba9ac2-e6ed-44f0-a87e-bcfa04b59d5d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is Active Record in the context of Rails?', N'Junior', N'Active Record is the Object-Relational Mapping (ORM) layer in Rails that connects your database tables to Ruby classes. It allows you to interact with database records as if they were standard Ruby objects, abstracting away the need to write complex SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7699bdd8-698c-47e4-9f5c-bcfc09150086', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the benefits and drawbacks of using a ''State Management'' library like NgRx vs. using RxJS-based Service pattern?', N'Senior', N'NgRx provides a centralized, predictable state container with powerful debugging tools and middleware support, ideal for complex, high-interaction applications. The Service-based pattern is lighter and easier to implement for smaller apps, but can become difficult to manage and debug as the state requirements scale and side effects proliferate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5bbd858-b5b8-4b86-b92a-bd0176d38261', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the NULL pointer used?', N'Fresher', N'The NULL pointer is a special pointer value that points to nothing and is used to indicate that a pointer does not currently reference a valid memory address. It is essential for avoiding errors like dereferencing uninitialized pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69a323b9-06fb-4e42-9092-bd018b1c0819', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the benefit of using ''nodemon'' during development?', N'Junior', N'Nodemon is a utility that monitors for any changes in your source code and automatically restarts the server. This eliminates the need to manually stop and start the process every time a file is saved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bf13e63-3064-4326-891a-bd01fa0cf0bc', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is a Qwik ''Resumable'' application?', N'Middle', N'A resumable application is one that can pause its execution on the server and resume it exactly where it left off on the client. It carries all necessary state and metadata in the HTML, allowing the browser to skip the expensive process of rebuilding the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f97150-edff-4389-9d8c-bd02310a51a1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can you perform joins in DynamoDB like in SQL?', N'Fresher', N'No, DynamoDB does not support join operations. Data modeling in DynamoDB typically requires denormalization, where related data is stored within a single item or managed through application-level logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd9432ba-d9e2-4d82-b5d3-bd0582ad65ea', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Describe the purpose of the ''fillfactor'' parameter in PostgreSQL indexes and tables.', N'Middle', N'The fillfactor determines how much space on a page is filled with data during an update or insert. Leaving empty space on a page allows for future updates to occur in-place without needing to create a new row version elsewhere, which significantly reduces index bloat and improves performance for write-heavy workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f9eadf-bdc8-46cf-ad42-bd05e76d7ad5', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What performance challenges arise from having too many Alpine.js components on a single page?', N'Senior', N'Each Alpine component creates its own reactive Proxy and initialization overhead. Excessive use of components can lead to high memory usage and slow page initialization times because the engine must walk the DOM and initialize each component''s scope individually, which can block the main thread during heavy page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f28977de-91e4-48bf-90d8-bd061c0a146c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between a bug and an edge case?', N'Fresher', N'A bug is a flaw that prevents the system from performing its intended function, while an edge case is an extreme or unusual input condition. Edge cases may not be bugs, but they reveal how the system handles unexpected data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
