INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f206c71f-f635-4f4c-9007-bd1b48f9401d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the trade-offs of using pointer receivers versus value receivers in methods.', N'Middle', N'Value receivers copy the data, which is safer for small, immutable structures but can be expensive for large structs. Pointer receivers avoid copying and allow the method to modify the original value, but they introduce potential issues with nil pointers and shared state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'805c4c35-6f57-4683-8deb-bd1d1c9ea5e7', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What does ''Kubernetes-native'' mean in the context of Quarkus?', N'Intern', N'Being Kubernetes-native means the framework is optimized to run efficiently within container orchestration platforms. It focuses on low memory consumption, fast boot times, and small artifact sizes to improve scalability and resource usage in a cloud environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1bdab50-988b-4f2a-9952-bd1d475a0630', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Discuss the implications of using ''Module#extend'' versus ''Module#include'' on instance versus class behavior.', N'Senior', N'Include adds instance methods to the class, making them available to all instances of that class. Extend adds methods to the specific object it is called on, typically being used to inject class-level methods into a class object, effectively modifying the behavior of that specific constant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcdfd5fb-9f23-4a55-89c2-bd1da440681a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the benefits of a schema-less design for development speed?', N'Middle', N'Schema-less designs allow developers to iterate faster by removing the need to run time-consuming database migrations when requirements change. The application code can adapt to new data formats dynamically, which is highly beneficial in agile development environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77e7d362-a864-499c-a02d-bd1ebc4b9ba1', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of a database driver in PHP?', N'Intern', N'A database driver acts as a bridge between the PHP application and a specific database management system. It provides the necessary functions to establish connections, send queries, and retrieve results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab1169f0-58df-400f-973b-bd227a71fc43', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does ''Module Augmentation'' enable safer plugin architectures?', N'Senior', N'Module augmentation allows developers to add properties or methods to existing modules without modifying the original source code. This is vital for plugin systems where external packages need to inject functionality into a core library while maintaining full type safety and IDE autocompletion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b58fb87a-a041-4254-9a34-bd23131ae742', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do you handle ''Hot Spot'' issues in a distributed MySQL architecture?', N'Senior', N'Hot spots are typically addressed by using read replicas to distribute traffic or by sharding the data across multiple instances based on a partitioning key. Application-side caching is also critical to reduce the direct load on the primary node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a8d649b-abe9-4232-a176-bd26971a76f9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit''s ''env'' modules provide a secure way to handle secrets?', N'Senior', N'SvelteKit provides separate modules for public and private environment variables, ensuring that only variables explicitly marked for the client are bundled into the browser JavaScript. This prevents accidental exposure of API keys or database credentials that should strictly remain in the server environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea6be364-b54d-46c1-b64f-bd27057d56b3', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does consistent hashing improve a sharded database architecture?', N'Middle', N'Consistent hashing minimizes the amount of data that needs to be remapped when adding or removing nodes from the cluster. By mapping both data and nodes to a circular hash space, it ensures that only a small portion of keys need to be relocated during scaling events.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd06c8da3-b8c1-419c-a7b5-bd27e3773061', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the primary differences between Rust''s ''Result'' type and traditional exception-handling mechanisms?', N'Senior', N'Result is a sum type that forces the developer to handle errors explicitly as part of the function signature, ensuring that all possible failure states are addressed. Unlike exceptions, which propagate through the call stack implicitly and often lead to hidden control flow, Result makes error handling a visible, type-safe aspect of the program''s logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a6f5d4f-a371-4f21-90f9-bd29c94942cf', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain how Rust handles the ''diamond problem'' with trait inheritance.', N'Senior', N'Rust avoids the diamond problem by disallowing traditional class-based inheritance, opting instead for trait composition. Since traits define shared behavior rather than state, and method resolution must be explicit, there is no ambiguity regarding which implementation to execute when a type implements multiple traits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b9c8b9b-74d6-422f-81d1-bd2a7329631b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s ''Plugin'' system enhance modularity?', N'Middle', N'Plugins allow developers to extend the framework''s core functionality, such as database integration or serialization, in a decoupled manner. By registering plugins, you can inject framework-wide services without tightly coupling your business logic to specific external libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
