INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39283259-96ab-4545-99a3-bd2ec16ec49f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the trade-offs of using a refresh interval versus a full commit in Elasticsearch.', N'Senior', N'Refreshing makes documents searchable by creating new small segments in memory, which is lightweight but increases resource overhead if done too frequently. A full commit forces an fsync to disk, which provides durability but is significantly more I/O intensive and should be performed sparingly to maintain write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
