INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c61ede29-f860-4f3e-9484-bd377e5e3d23', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI manage request validation errors by default?', N'Middle', N'When validation fails, FastAPI automatically catches the Pydantic error and returns a 422 Unprocessable Entity response containing detailed information about which fields failed and why. This behavior ensures that clients receive structured feedback without requiring manual validation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
