INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'849ae1ab-0f0a-46ec-940c-bd409a24f369', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of a coordinator node in a distributed NoSQL system?', N'Middle', N'A coordinator node acts as a proxy for client requests, routing them to the appropriate nodes that hold the relevant data. It is responsible for aggregating responses from multiple nodes and returning a unified result to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b953e92e-b1bc-4cc4-a008-bd410b46d5a6', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between LOCAL_QUORUM and EACH_QUORUM?', N'Middle', N'LOCAL_QUORUM ensures that a majority of replicas in the local data center acknowledge the request, which is faster and avoids cross-datacenter latency. EACH_QUORUM requires a majority of replicas in every data center to acknowledge the operation, ensuring stronger consistency across the entire cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef441bbd-222e-4933-9208-bd4338a576db', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between synchronous and asynchronous handlers in Actix?', N'Intern', N'Asynchronous handlers use the ''async'' keyword and do not block the thread while waiting for I/O, allowing better scalability. Synchronous handlers block the entire worker thread until the task is complete, which can degrade performance under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
