INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62a6d909-8455-466a-bb4c-bd4a47127b14', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do you identify slow queries in MySQL?', N'Middle', N'The primary method is enabling the Slow Query Log, which records queries that exceed a defined time threshold or do not use indexes. Tools like the Performance Schema or the ''EXPLAIN'' statement can further analyze these queries to identify bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0d5fc09-9095-456f-9731-bd4d580804df', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of Vert.x in the Quarkus ecosystem?', N'Middle', N'Vert.x provides the core reactive engine for Quarkus, enabling non-blocking I/O operations and event-driven communication. It acts as the foundation for both the HTTP server and various reactive clients, ensuring high concurrency and low resource usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'829b49ca-bfb7-4e43-b144-bd50f4302a98', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle input binding in a way that respects the platform''s standard event flow?', N'Senior', N'Lit encourages the use of standard DOM events, such as ''input'' or ''change'', to propagate data back to parent components. Instead of two-way data binding, it follows the ''properties down, events up'' pattern, which keeps the data flow unidirectional and easier to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe7a9c32-fb11-4230-b620-bd51bae862c4', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does the PHP Zend Engine''s Opcache mechanism improve performance in a production environment?', N'Senior', N'Opcache stores the compiled bytecode of PHP scripts in shared memory, eliminating the need to parse and compile the source code on every request. This significantly reduces CPU overhead and latency, as the engine can execute the pre-compiled instructions directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'163b6a35-47cf-4fe4-87d1-bd52b0dd2979', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the impact of long-tail latency on overall user experience?', N'Senior', N'I look at the 99th percentile (P99) latency metrics rather than the mean, as the tail latency often dictates the experience for the most active users. I estimate the frequency of these tail events and use them to justify the investment in optimization strategies like request hedging or improved load balancing to smooth out the distribution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a029dd5-df8f-4866-81f1-bd5467cede0c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a Spring ''Proxy'' and why is it used?', N'Middle', N'A proxy is an object that wraps a bean to add additional functionality like transaction management, security, or logging without modifying the original class. This technique, known as Aspect-Oriented Programming, allows for cross-cutting concerns to be handled in a decoupled way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'385e6ff4-e18b-4804-99bb-bd5557f412ce', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the default port for an Echo server?', N'Intern', N'Echo does not enforce a default port; the developer specifies the port when starting the server. It is common practice to use environment variables to define the port for different deployment environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'577cf55a-2397-4e0a-a147-bd559f3c33c9', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the concept of graceful degradation.', N'Middle', N'Graceful degradation is a design strategy where a system maintains limited functionality even when some components fail. Instead of crashing, the system disables non-essential features to ensure the core service remains available to users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33cc7c11-00e8-4eef-b893-bd5db4efb4ff', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary difference between Tailwind CSS and traditional CSS frameworks like Bootstrap?', N'Fresher', N'Tailwind CSS is a utility-first framework that provides low-level utility classes to build custom designs directly in your markup, whereas Bootstrap is a component-based framework that provides pre-styled, ready-to-use components like buttons and navbars. This means Tailwind requires more manual assembly of styles, offering greater flexibility and smaller bundle sizes compared to the rigid, opinionated structure of traditional frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eafd1fff-2a8d-4aac-b57b-bd60ded73938', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the scalability trade-offs of using Axum with a large number of handlers?', N'Senior', N'As the number of handlers grows, the complexity of the router type can increase compile times significantly. To manage this, developers should split their application into multiple modules with their own routers and merge them using the ''.merge()'' method to keep the type system manageable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'621c3d44-dbc0-49bc-8437-bd6566aec9cf', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage distributed tracing in a microservices environment?', N'Senior', N'Micronaut integrates with tracing systems like Zipkin or Jaeger by automatically instrumenting HTTP clients and servers to propagate trace headers. It handles the context propagation across thread boundaries, ensuring that spans are correctly linked in a distributed, asynchronous environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11756e7a-be1c-407f-ba20-bd67a79770d2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you architect a secure multi-tenant SaaS application to prevent data leakage between tenants?', N'Senior', N'Security in multi-tenancy is achieved through a combination of logical isolation at the application layer, such as row-level security in databases, and physical isolation using separate databases or schemas. Architectural enforcement should also include tenant-aware authorization checks at the API gateway to ensure users can only access resources associated with their specific tenant ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8707ace8-758b-456e-a32c-bd6a256f8a05', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is it important to keep transactions as short as possible?', N'Junior', N'Long-running transactions hold locks on database resources for extended periods. This can lead to decreased performance, reduced concurrency, and increased likelihood of deadlocks, which blocks other users from accessing the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2385b659-faca-4b9b-b0a7-bd6ba179dea7', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the security implications of using a high-performance framework like Fiber?', N'Middle', N'High performance does not imply high security; Fiber requires manual configuration for security headers, rate limiting, and input validation. Developers must ensure they implement standard security middleware to protect against common threats like CSRF, XSS, and SQL injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ee9966e-10eb-41ef-8de8-bd6f8f7405af', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are named parameters in Dart?', N'Intern', N'Named parameters allow you to specify arguments by name rather than position when calling a function. They improve code readability and allow for optional parameters, making functions easier to use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef9f3496-0095-492d-9a1b-bd735ec28657', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the InnoDB Buffer Pool handle memory management and page flushing?', N'Senior', N'The Buffer Pool uses an LRU algorithm to cache data and index pages in memory, minimizing disk I/O. Background threads perform ''dirty page'' flushing via checkpoints to balance memory availability with the overhead of writing to the doublewrite buffer and data files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a365abd-d1b8-4435-9c64-bd73778fa731', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can you use standard JavaScript classes with SolidJS reactivity?', N'Middle', N'Yes, you can incorporate signals into class properties or use them within class methods. However, because SolidJS components are just functions that run once, the framework''s reactivity is best utilized through its functional primitives rather than traditional class-based state management patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
