INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c12075f5-2aae-4444-a721-bd78d01339f1', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does consistent hashing improve the scalability of a distributed cache or database?', N'Senior', N'Consistent hashing maps both data keys and nodes to a logical ring, ensuring that when a node is added or removed, only a small fraction of keys need to be remapped. This minimizes data movement compared to standard modulo hashing, which would require rehashing almost all keys upon cluster size changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d0569c1-fced-407a-b2b4-bd7995746096', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the fundamental data structure used by MongoDB to store information?', N'Intern', N'MongoDB stores data in documents, which are organized into collections. These documents are represented in a format called BSON, a binary-encoded serialization of JSON-like documents that allows for more data types and efficient processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e36b4ed0-fc30-4c26-94e6-bd7c91b2c236', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does the Alpine.js ''x-cloak'' directive prevent UI flickering?', N'Senior', N'The x-cloak directive hides elements from the user until Alpine has finished initializing the component and processed the directives. This prevents the ''Flash of Unstyled Content'' (FOUC) where the raw template might be visible to the user for a split second before Alpine evaluates the expressions and applies the correct visibility or state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8df33fc-15d2-4aa1-83cd-bd7ca7242611', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the role of technical debt as a conscious trade-off?', N'Intern', N'Technical debt is often a planned trade-off where the team chooses a quick, suboptimal solution to hit a deadline. The key is that the team must acknowledge the debt and plan to pay it back later, turning it from a mistake into a strategic decision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
