INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fc19438-4ff6-4a77-819e-bd92939d53c5', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you evaluate the choice between a B-Tree index and an LSM-Tree index?', N'Senior', N'B-Trees are optimized for read-heavy workloads and provide consistent performance for point and range queries by keeping data sorted in balanced structures. LSM-Trees are optimized for write-heavy workloads, as they buffer writes in memory and flush them to disk as sorted files, significantly reducing disk I/O at the cost of slower read performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
