INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdde4dbb-7771-42ed-890b-bdbc7abebb74', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s handling of ASGI compare to standard Starlette-based implementations?', N'Senior', N'While Litestar uses similar ASGI foundations, it provides a much more opinionated and structured approach to request-response cycles. It abstracts the raw ASGI interface into a sophisticated set of controller-based handlers, providing features like automatic dependency resolution and granular exception handling that are manual or non-existent in lower-level frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf6e8e99-d060-4e51-adbe-bdbe6f0813c6', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular CLI Builder?', N'Intern', N'In Angular8, the CLI Builder API is stable and available to developers who want to customize the Angular CLI by adding or modifying commands. For example, you could supply a builder to perform an entirely new task, or to change which third-party tool is used by an existing command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb6d72aa-3a77-42cd-9666-bdc011b85139', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the ''IWebHostEnvironment'' service used for?', N'Junior', N'IWebHostEnvironment provides information about the hosting environment the application is running in, such as Development, Staging, or Production. It allows developers to conditionally execute logic or load configurations based on the current environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca90263-1761-4ddf-9627-bdc1324288eb', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is the Shadow DOM considered a core feature of Lit?', N'Intern', N'The Shadow DOM is essential because it provides the isolation needed for complex components to function reliably. By using it, Lit ensures that a component''s internal structure and styles remain private and protected from the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c8d75eb-c1a0-4f3b-a6dd-bdc24d177dc4', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of a database index and what is a potential trade-off?', N'Junior', N'An index is a data structure that allows the database engine to find rows much faster without scanning every single row in a table. The trade-off is that indexes consume additional disk space and can slow down data modification operations like inserts, updates, and deletes because the index must be updated every time the data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'856bcd40-77bf-4824-b5b3-bdc60346d367', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle request routing compared to the standard library net/http?', N'Senior', N'Gin uses a custom radix tree data structure for routing, which allows for significantly faster path lookups compared to the linear search or map-based approaches in some other frameworks. This constant-time complexity is crucial for high-throughput services where many routes are registered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ea374f2-50fd-4334-ad9a-bdc86247ad3b', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit improve SEO compared to client-side only apps?', N'Fresher', N'By pre-rendering pages into static HTML on the server, search engine crawlers can easily read the page content. This makes indexed pages more discoverable compared to apps that only render content via JavaScript after the page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ee3aa43-1c63-445b-b470-bdccc23a57b0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of Redis modules?', N'Middle', N'Redis modules allow developers to extend the core functionality of Redis by adding new data types and commands. This enables the use of specialized structures like search indexes, time-series data, or graph databases directly within the Redis memory space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9ac051b-c2df-4033-9418-bdcd567bd2e9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the Go workspace structure, specifically the GOROOT and GOPATH environment variables?', N'Intern', N'GOROOT points to the directory where the Go language itself is installed, while GOPATH specifies the location of your workspace containing source code, binaries, and dependencies. In modern Go development, Go Modules have largely replaced the need to manually manage GOPATH.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
