INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63d5b245-b23f-470c-83b3-bdd158c454df', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the primary mechanism behind Go''s interface implementation, and what are the performance implications?', N'Senior', N'Go interfaces are implemented via an ''itab'' structure, which contains type information and a function pointer table (vtable). While this enables polymorphism without explicit inheritance, it introduces a small indirection overhead for method dispatch and can lead to heap allocations if concrete values are boxed into interface variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40de496e-d2cf-46ed-83b3-bdd183b04a72', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s JIT (Just-In-Time) compilation alter the execution pipeline compared to traditional Zend VM interpretation?', N'Senior', N'JIT compilation targets the translation of Zend bytecode into native machine code at runtime, bypassing the standard VM interpretation overhead for computationally intensive tasks. While it significantly boosts performance for CPU-bound operations, it provides negligible benefits for typical I/O-bound web requests and increases the complexity of memory management and debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
