INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ce5ff66-69eb-4a41-a5f3-bdd5ca02f0f3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the trade-offs of setting a consistency level to ''ONE'' vs ''QUORUM''.', N'Senior', N'Consistency level ONE provides the lowest latency and highest availability but risks returning stale data if a replica is out of sync. QUORUM ensures that a majority of replicas agree on the data, offering a balance between strong consistency and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
