INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e16a622-4210-4408-8409-bde83e2a7647', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the performance impacts of enabling RTTI in a large-scale application?', N'Senior', N'Runtime Type Information adds memory overhead to polymorphic classes by storing additional metadata, such as type names and inheritance structures, in the vtable or associated structures. While usually negligible, in embedded systems or massive codebases, this can impact binary size and cache performance, leading many to disable it via compiler flags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4a3b381-d10e-4a17-bdb7-bde991fa6521', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How do ''Bloom Filters'' contribute to system performance?', N'Senior', N'Bloom filters are space-efficient probabilistic data structures used to test whether an element is a member of a set. They prevent unnecessary disk lookups by quickly identifying if a key definitely does not exist, significantly reducing latency in distributed caching layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff991096-a0d7-488c-9007-bdec1e3d14b5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of static typing in TypeScript?', N'Intern', N'Static typing allows developers to define the types of variables, parameters, and return values at compile time. This helps identify type-related bugs before the code is ever executed, leading to more robust applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58655169-753d-4999-82e8-bdef659ad2fb', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the .stop() method in jQuery?', N'Fresher', N'.stop() is used to immediately halt currently running animations on the selected elements. This is useful for preventing animation queues from building up when a user triggers multiple events rapidly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13903d42-e77f-48ba-8e09-bdefa67eec19', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a request router in the context of backend development?', N'Intern', N'A request router is a component that inspects incoming HTTP requests and directs them to the appropriate handler function based on the URL path, HTTP method, and other request criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
