INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30531575-904c-499a-b318-bdf268f4e358', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are symbols in Ruby and how do they differ from strings?', N'Intern', N'Symbols are immutable, reusable identifiers that are often used as labels or keys. Unlike strings, which are mutable and created as a new object in memory each time, symbols are stored in a global table and represent the same object throughout the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc02d28b-dffb-4891-96ba-bdf509723c58', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary advantage of Tailwind''s utility approach regarding specificity?', N'Fresher', N'Utility classes eliminate the common issue of CSS specificity wars. Since every class has a very specific, narrow purpose and is applied directly to the element, you avoid the complexity of cascading rules and overriding deep selector chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95e0a389-edb7-45f3-9dbe-bdf53f802a93', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the MySQL InnoDB doublewrite buffer prevent data corruption during a crash?', N'Senior', N'When a page is flushed from the buffer pool, it is first written to a contiguous area called the doublewrite buffer. If a system crash occurs during the page write, InnoDB can recover the page from the doublewrite buffer copy, ensuring data integrity since partial page writes are prevented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d7e76f0-18e1-4868-ace8-bdf559c6ba89', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the benefit of using the ''class'' attribute in Preact?', N'Junior', N'Using ''class'' instead of ''className'' makes Preact more intuitive for developers coming from a background in raw HTML. It reduces the need for mapping standard attributes to React-specific prop names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0eef277-8f12-4d6b-aeb6-bdf5a7873e87', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the security implications of FastAPI''s ''auto-include'' features in OpenAPI?', N'Senior', N'FastAPI exposes all endpoints in the OpenAPI schema by default, which can inadvertently reveal internal API structures. For production, sensitive endpoints should be explicitly hidden or protected by authentication layers to prevent unauthorized discovery through the /docs or /openapi.json endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd20d005b-f118-4967-8013-bdf85578d78f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Is it possible to have a transaction with only one operation?', N'Junior', N'Yes, every single SQL statement in most systems is wrapped in an implicit transaction. Even if the statement is a single update, the database treats it as an atomic transaction to ensure data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35921978-d8c4-42cc-8768-bdf8ec5d63f9', N'075b8862-431c-4678-9767-f55359758a4a', N'What is Vue.js and why would you use it?', N'Intern', N'Vue.js is a progressive JavaScript framework primarily used for building user interfaces and single-page applications. It is known for its adaptability, small file size, and the progressive learning curve. Key Features Virtual DOM Vue uses a virtual DOM, which is a lightweight copy of the actual DOM. This approach significantly speeds up UI updates by only rendering what has changed. JS and Template Integration Vue combines JavaScript and HTML-like templates for component structure. It then uses a virtual DOM renderer to update the actual DOM when data changes. Two-Way Data Binding Vue offers two-way data binding using the v-model directive, where changes in the UI instantly reflect in the data model and vice versa. Directives Vue leverages HTML directives for actions, loops, and more.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afbb5742-9624-4457-b1da-bdf8f4ba669c', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the benefit of Litestar''s opinionated design?', N'Fresher', N'The opinionated design provides a standardized way of building applications, which reduces decision fatigue. It ensures that common tasks like validation, serialization, and error handling are performed consistently across the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28208afe-8cdc-4838-85ae-bdfabe7ee93c', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How does ''Backpressure'' contribute to system stability in stream processing?', N'Senior', N'Backpressure allows a system to signal to upstream producers that it cannot keep up with the current ingestion rate. By slowing down the producer, the system prevents buffer overflows and crashes, maintaining overall stability even under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79e74b0b-3b69-4929-a938-bdfc354b32d0', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When designing an API, how do you manage versioning to avoid breaking changes for existing clients?', N'Senior', N'I enforce a clear versioning strategy, typically through URL path versioning or request headers, ensuring that breaking changes are only introduced in major version updates. I also implement a deprecation policy with clear communication and sunset periods for older versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88db3c6d-eb48-4510-9acf-bdfdbd0e4c50', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why are interfaces preferred over abstract classes for defining contracts in Java?', N'Middle', N'Interfaces allow for multiple inheritance of type, providing more flexibility than abstract classes, which only support single inheritance. They are better suited for defining capabilities or behaviors that can be shared across unrelated classes. While abstract classes are useful for sharing state and implementation, interfaces are generally preferred for designing decoupled, extensible systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfd591c0-b454-493e-9c6f-bdffdb3818ff', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a primary key?', N'Intern', N'A primary key is a column or a set of columns that uniquely identifies each row in a table. It must contain unique values and cannot contain NULL values, ensuring that every record can be referenced individually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef37c25a-e3ed-45e1-bc18-be0125636e79', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the primary performance implications of using jQuery''s Sizzle engine compared to native querySelectorAll?', N'Middle', N'Sizzle was designed for cross-browser compatibility when native methods were inconsistent. Today, native methods are significantly faster as they are implemented in highly optimized C++ within the browser engine, whereas Sizzle involves additional JavaScript parsing and abstraction layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6c8dde-a0c1-49d1-9a9b-be03213e0c4c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s type system handle nullability without a dedicated ''null'' type?', N'Senior', N'Rust utilizes the ''Option'' enum to represent the presence or absence of a value, forcing developers to explicitly handle the ''None'' case. This approach eliminates null-pointer exceptions by making the possibility of missing data a compile-time requirement for the consumer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5c6eb08-5c99-433f-a8e5-be03fd17084c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the ''Refinement'' feature in Ruby and why use it?', N'Middle', N'Refinements provide a way to modify classes locally within a specific scope. They are a safer alternative to monkey patching because the changes are only active within the file or module where the refinement is activated, preventing global side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3702aaa6-1fdc-4ad6-a4eb-be04aa9f0320', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence the decision to build a custom solution versus buying an existing service?', N'Intern', N'Building is preferred when you need high customization, competitive advantage, or complete control over the solution. Buying is better when the functionality is a commodity, time-to-market is critical, or the cost of maintaining a custom version outweighs the subscription fee.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b069ef72-6cab-4c57-b565-be08d3f78d94', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the architectural trade-offs of using Laravel''s Eloquent ORM versus using the Query Builder for high-throughput applications.', N'Senior', N'Eloquent provides a rich, expressive interface that significantly improves developer productivity and code readability, but it introduces overhead due to object instantiation and hydration. For high-throughput scenarios, the Query Builder is more performant as it avoids the memory overhead of model objects and allows for more efficient, fine-grained control over the SQL execution plan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'622242d7-1e8e-48ca-8d94-be09a98b5568', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are DDL and DML?', N'Fresher', N'DDL stands for Data Definition Language, which deals with the structure of the database like CREATE or ALTER. DML stands for Data Manipulation Language, which deals with the data within the tables like INSERT, UPDATE, or DELETE.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
