INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ddb4af0-9df2-457b-ab5c-be11b38c1a81', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between ''Atomic'' in ACID and ''Atomic'' in BASE?', N'Middle', N'In ACID, atomicity implies an immediate, all-or-nothing operation within a single system. In BASE, atomicity is often interpreted loosely, where the system eventually reaches a consistent state, but intermediate operations may be visible to other processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7a457ab-f33d-46b9-acac-be1244fce4f8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s reconciliation algorithm handle SVG elements differently from HTML elements?', N'Senior', N'Preact includes specific logic to handle SVG namespaces during the creation and update of DOM nodes, ensuring that attributes are mapped correctly to the SVG DOM API. This is handled as an internal optimization to avoid the need for external libraries to manage complex vector graphics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5355228-f720-4072-960c-be136adb3627', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix favor server-side state over complex client-side state management libraries?', N'Senior', N'Remix shifts the source of truth to the server, treating the URL as the primary state container. By synchronizing the UI with server state through loaders and actions, it reduces the need for complex global state management and minimizes the risk of state inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdcc0aa8-c500-44ec-b605-be16879ab28f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to document your work, even if you are the only person currently working on it?', N'Intern', N'Documentation serves as a reference for your future self, as it is easy to forget the reasoning behind specific decisions after time has passed. It also ensures that if another team member needs to take over your work, they can understand your approach and pick up where you left off without significant delay.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd80725b-658d-4620-bd57-be16fe502488', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the implications of Python being a dynamically typed language?', N'Middle', N'Dynamic typing allows for greater flexibility and faster prototyping, as variables do not require explicit type declarations. However, it shifts error checking to runtime, making static analysis and type safety harder to guarantee without tools like type hints and external linters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ff83c8c-0aed-405e-878c-be17375b81f5', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'In a distributed system, how should one handle Echo''s session management to ensure horizontal scalability?', N'Senior', N'Echo''s default session middleware often relies on local cookies or memory stores, which are not suitable for distributed environments. You must implement a custom store backed by a shared service like Redis to ensure that state persists across multiple horizontally scaled instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'927fdcff-6a1f-441f-815f-be187abdb276', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why is the concept of immutability critical when updating state in Redux?', N'Middle', N'Immutability is critical because Redux relies on shallow equality checks to determine if the state has changed. If state objects are mutated directly, the UI components may not re-render because the reference to the state object remains the same.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68dd6a48-f188-4107-974c-be18f8e784ee', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why would you choose to use a standard library or framework instead of building a custom solution from scratch?', N'Junior', N'Standard libraries and frameworks are usually well-tested, documented, and supported by the community, which saves significant development time. Building from scratch often leads to reinventing the wheel and introduces security or performance risks that established tools have already solved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5e99e81-5727-4aae-a8d6-be1924bd037c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you handle asynchronous operations in Redux?', N'Junior', N'Since reducers must be pure and synchronous, asynchronous operations like API calls are typically handled using middleware. Redux Thunk is the most common middleware that allows you to write action creators that return a function instead of an object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6952710e-bb70-4573-b505-be19835a08c7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Discuss the trade-offs of using ''JSONB'' in a relational database versus a native Document store.', N'Senior', N'JSONB allows for flexible schema evolution within a ACID-compliant relational environment, but it lacks the specialized query capabilities and horizontal sharding features native to document stores. It is best used for small portions of the schema that require high volatility rather than as a replacement for pure document-based architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
