INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ca3d139-b0f2-4521-9532-be19db1ae32f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the difference between a Controller and a Middleware in AdonisJS?', N'Junior', N'Controllers are responsible for handling the logic of specific HTTP requests and returning a response. Middleware, however, acts as a filter that intercepts requests before they reach the controller, which is useful for tasks like authentication or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6278802-d2e5-4828-b20a-be1ca3fa0fa0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is CSRF and how does Django protect against it?', N'Junior', N'CSRF stands for Cross-Site Request Forgery, an attack where a user is tricked into submitting unwanted actions. Django protects against this by requiring a unique, secret token for every POST request, which is verified by the server to ensure the request originated from your site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
