INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fffa5098-7d10-4fa1-ad0b-be2825c8db99', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'When should you choose a NoSQL database over a traditional RDBMS?', N'Middle', N'NoSQL is preferred when dealing with unstructured or rapidly changing data schemas, massive horizontal scalability requirements, or high-velocity data ingestion. RDBMS remains superior for applications requiring strict ACID compliance and complex relational integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
