INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b74ae04-db83-4007-8a07-be2f8f034b20', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the Common Language Runtime (CLR) implement interface dispatch, and why is it slower than non-virtual method calls?', N'Senior', N'The CLR uses interface method tables (vtable-like structures) to resolve calls at runtime. Because a class can implement multiple interfaces, the runtime must perform a lookup to find the correct method implementation, which prevents the compiler from performing devirtualization and inlining optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a23d0cf-69c4-4737-8c59-be2fd4460fe1', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why is data modeling different for NoSQL compared to RDBMS?', N'Middle', N'In RDBMS, you design around normalization and the structure of the data itself. In NoSQL, you design around the specific access patterns and queries the application will perform, often embedding data to avoid expensive application-level joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bfc7c1b-6794-48aa-a928-be305f611fee', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to keep the event loop non-blocking?', N'Junior', N'The event loop is responsible for handling network I/O for many concurrent connections. If it is blocked by a long-running synchronous task, no other requests can be processed, which destroys the performance benefits of the asynchronous architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
