INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'033a2227-38ca-46fd-9db1-be32b8cbbb89', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Explain the purpose of the public directory in a Vite project.', N'Middle', N'The public directory serves as a static asset folder where files are copied to the root of the build output without being transformed or processed. This is ideal for assets that need to be referenced by an exact path, such as robots.txt or favicon files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dedfc6f-ebba-4cd7-99c0-be342e39cee7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle data consistency during a primary election?', N'Middle', N'When a primary fails, the replica set initiates an election to select a new primary. During this window, the cluster may be temporarily unavailable for writes, and the system ensures that the new primary has the most recent Oplog entries to minimize data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
