INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8211bc1-5475-44c5-96aa-be3ec4aaaca7', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the utility functions provided by RxJS?', N'Intern', N'The RxJS library also provides below utility functions for creating and working with observables. 1. Converting existing code for async operations into observables 2. Iterating through the values in a stream 3. Mapping values to different types 4. Filtering streams 5. Composing multiple streams', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'513d8f69-b03f-433d-a595-be40127eac1d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary difference between SvelteKit''s load functions and traditional client-side data fetching?', N'Middle', N'SvelteKit load functions run during the initial server-side rendering phase, allowing data to be fetched and serialized into the HTML before it reaches the browser. This eliminates the ''waterfall'' effect and improves Largest Contentful Paint by delivering fully populated content immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ab51e96-b221-44d9-b735-be43bbc66e5f', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the benefit of using Micronaut''s ''Client'' annotation for HTTP requests?', N'Middle', N'The @Client annotation allows developers to define declarative HTTP clients using interfaces. Micronaut automatically generates the implementation at compile-time, handling serialization, deserialization, and request building without the need for manual boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69fa2005-f1d9-484c-8ec1-be467ffcc4bc', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between embedding and referencing in MongoDB?', N'Fresher', N'Embedding stores related data within a single document for better read performance, while referencing stores relationships by keeping the ID of one document inside another. Referencing is often used to avoid data duplication or to manage large, growing datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3e080e9-5e65-4d8e-889f-be47aeeeadb0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are Qwik loaders and what purpose do they serve?', N'Junior', N'Loaders are functions used in Qwik to fetch data required for a component to render. They run on the server and ensure that the necessary data is available before the component is sent to the client, preventing unnecessary client-side data fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d340f0d-6afc-435d-95c5-be49582c6d71', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a constructor and when is it called?', N'Fresher', N'A constructor is a special member function that initializes an object of a class. It is automatically called by the compiler whenever an instance of the class is created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df0e8e7b-cd93-4e07-8340-be4afb523fbe', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the difference between CQL and SQL?', N'Fresher', N'CQL (Cassandra Query Language) is similar to SQL in syntax, but it lacks complex features like joins and subqueries. It is optimized for the distributed, wide-column architecture of Cassandra rather than relational data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'131f41ac-e9a3-417e-81c0-be4bc3b12db8', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a class in Java?', N'Intern', N'A class is a blueprint or template used to create objects in Java. It defines the state and behavior that the objects created from it will possess.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4597a09a-ec97-4ea6-a085-be4c89d458fb', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the advantage of using ''Service'' traits in Actix?', N'Middle', N'The Service trait is the core abstraction for processing requests in Actix, allowing for highly composable middleware and handler stacks. By implementing this trait, you can create modular components that can be easily plugged into different parts of the request-response pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0c23604-5fd9-4b61-8b2c-be4e22811522', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'When should you use ''useContext'' in Qwik?', N'Junior', N'UseContext is used to share data across multiple components without having to pass props through every intermediate level. It is ideal for global state like themes, user authentication status, or language preferences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f68f275-ed02-4051-9ef5-be5342277ace', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the ''extern'' keyword work?', N'Junior', N'The ''extern'' keyword declares that a variable or function is defined in a different source file. It tells the compiler that the identifier exists somewhere else in the program, so the linker can resolve the reference during the build process. It is the primary way to share global variables across multiple files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1791e27a-6516-489c-a121-be5370f6a04f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach security in an internal-facing microservices network?', N'Senior', N'I implement a Zero Trust model, where every request is authenticated and authorized regardless of its origin within the network. I use mTLS for service-to-service communication to ensure traffic is encrypted and verified, minimizing the risk of lateral movement by an attacker.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15c6e540-6f60-4fc3-ad9e-be540d63ceab', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does class inheritance work with extends and super, and what are the rules around super() in constructors?', N'Fresher', N'The extends keyword establishes two separate prototype chains simultaneously. It links both the instances and the classes themselves. 1. Child.prototype.proto === Parent.prototype — instance method inheritance. 2. Child.proto === Parent — static method inheritance. super is used in two contexts: - In a constructor: super(...args) calls the parent constructor. In a derived class, super() must be called before any access to this. The engine throws ReferenceError if you access this before super() — this is because the parent constructor is responsible for allocating the this object for derived classes. - In a method: super.methodName() calls the parent''s prototype method, enabling cooperative method overriding. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1ce9ad3-40bf-4b3e-9a19-be55455e9f5a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the significance of ''factory'' constructors in Dart.', N'Senior', N'Factory constructors allow a class to return an existing instance, a cached instance, or a subclass instance. This pattern is essential for implementing the singleton pattern, object pooling, or returning subtypes based on input arguments without exposing the underlying instantiation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6f199de-13ed-4f89-93d5-be56251b35bd', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is meant by a ''micro-framework'' in the context of Flask?', N'Fresher', N'A micro-framework is a framework that provides only the essential components to get a web application running, such as routing and request handling. It avoids imposing specific database abstractions or form validation tools, allowing developers to choose their preferred libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f250c799-2b33-4982-a270-be56d3105da9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When debugging an issue with no clear cause, how do you estimate how long it will take to fix?', N'Junior', N'I would perform a time-boxed investigation to narrow down the scope of the problem. After the investigation, I would provide a more informed estimate for the actual fix based on the findings from that initial research period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'870bb7bc-38db-48b6-ac1d-be5a3dd5d377', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do NoSQL databases typically handle transactions compared to Relational databases?', N'Junior', N'Many NoSQL databases prioritize availability and speed over strict ACID compliance, often providing transactions only at the document level. While many modern NoSQL systems have added multi-document transaction support, traditional relational databases are generally built around strict ACID compliance by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bfc82fd-3b5c-4019-aa6b-be5c12a59780', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with an incident involving data corruption, what are the first three steps you take?', N'Senior', N'First, I halt the process causing the corruption to prevent further impact. Second, I perform a thorough impact analysis to identify the scope of affected records using audit logs. Third, I develop a remediation plan to restore integrity, potentially involving a point-in-time recovery or a corrective data patch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a4cba5d-296d-440f-a2b2-be5c360c2d04', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is ''read-before-write'' often an anti-pattern in high-scale distributed NoSQL systems?', N'Senior', N'Read-before-write creates a synchronization bottleneck that negates the latency benefits of distributed writes. It forces a round-trip to the storage layer before the update, increasing transaction time and sensitivity to network jitter, which can lead to contention and performance degradation under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'859804ad-f596-4f9d-93f8-be5d89cfeb5f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Define the term ''Durability'' in the context of ACID.', N'Middle', N'Durability guarantees that once a transaction is committed, its effects are permanent, even in the event of a system failure like a power outage or crash. This is achieved by flushing transaction data to non-volatile storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f86f4e72-a46a-4f7a-ab22-be60fe3b6f3f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When is it appropriate to use an ''API-first'' development methodology?', N'Senior', N'API-first development is ideal when multiple teams or external partners need to consume the same service, as it forces the design of the interface before any implementation occurs. This approach facilitates parallel development, ensures consistency, and allows for stakeholder feedback early in the lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01eb972b-19a2-4d5c-9951-be66a6404ed2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How are WebSockets handled in Axum?', N'Middle', N'Axum provides a dedicated ''WebSocketUpgrade'' extractor that handles the protocol handshake process. Once upgraded, it provides a stream of messages that can be managed using standard async loops, allowing for full-duplex communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd62e46c8-b3b4-43d8-8f33-be683c8895be', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are data attributes in HTML?', N'Junior', N'Data attributes are custom attributes prefixed with data- that allow developers to store extra information on standard elements. They are primarily used to pass data from HTML to JavaScript without affecting the visual presentation of the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'576ecc1b-19b6-4581-8366-be6b240b944b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between shallow and deep copying in the context of mutable objects.', N'Senior', N'A shallow copy creates a new object but inserts references to the original objects found in the original, while a deep copy recursively clones the entire object tree. Deep copying is necessary when modifying the internal structure of the copy must not affect the original data structure''s nested members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78c99995-82c2-43a5-98d8-be6bbbedccb1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to reset state in Redux?', N'Fresher', N'You need to write a _root reducer_ in your application which delegate handling the action to the reducer generated by combineReducers(). For example, let us take rootReducer() to return the initial state after USER_LOGOUT action. As we know, reducers are supposed to return the initial state when they are called with undefined as the first argument, no matter the action. In case of using redux-persist, you may also need to clean your storage. redux-persist keeps a copy of your state in a storage engine. First, you need to import the appropriate storage engine and then, to parse the state before setting it to undefined and clean each storage state key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae04bd25-f5f9-4cc2-91df-be6dc1d0cdb7', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the Logger middleware in Echo?', N'Fresher', N'The Logger middleware is a standard feature in Echo that automatically logs information about every incoming HTTP request. This typically includes the status code, request method, path, and the time taken to process the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e7dd3e3-7009-4c5b-9bac-be6e2bed5ad4', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary architectural benefit of using Redis as a message broker?', N'Junior', N'As a message broker, Redis uses its Pub/Sub (Publish/Subscribe) feature or Streams to allow different parts of an application to communicate asynchronously. It provides a fast, centralized hub for passing messages between services without needing persistent storage for every message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7d015d6-33ef-496c-9590-be72d5c18874', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Describe the strategy for handling database session management in a Flask-SQLAlchemy application.', N'Senior', N'You should utilize the scoped_session pattern, which ensures that each thread or request context receives its own unique database session. It is critical to ensure that sessions are automatically closed or committed at the end of every request to prevent connection pool exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ddf2737-2513-4db8-b5d5-be75825c2c60', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s error handling mechanism improve application reliability?', N'Middle', N'Fastify provides a centralized error handler that catches exceptions thrown within the request lifecycle and automatically formats them into a standard error response. This ensures that the server does not crash unexpectedly and that clients receive consistent, well-structured error messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfba01b0-6600-4e68-b567-be7780041e29', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the need of tree shaking', N'Intern', N'Tree Shaking can significantly reduce the code size in any application. i.e, The less code we send over the wire the more performant the application will be. For example, if we just want to create a “Hello World” Application using SPA frameworks then it will take around a few MBs, but by tree shaking it can bring down the size to just a few hundred KBs. Tree shaking is implemented in Rollup and Webpack bundlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'291adaae-e6d4-44fb-8ba6-be795762620d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the ILogger interface?', N'Junior', N'ILogger is an abstraction provided by ASP.NET Core for logging information, warnings, and errors throughout the application. It allows developers to send log data to various providers, such as the console, debug window, or external logging services, in a consistent way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'571d3aa6-07ab-4d48-a29b-be7c675313c0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How are event listeners created in Node.JS?', N'Fresher', N'An array containing all eventListeners is maintained by Node.js. Each time .on(), .once(), or .addListener() function is executed, a new event listener is added to that array. When the concerned event is emitted, each eventListener that is present in the array is called in a sequential or synchronous manner. The event listeners are called in a synchronous manner to avoid logical errors, race conditions etc. The total number of listeners that can be registered for a particular event, is controlled by .setMaxListeners(n). The default number of listeners is 10. Example: .on() — persistent listener Example: .once() — single-fire listener As an event Listener once registered, exists throughout the life cycle of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a83212e-1b11-47ff-ab35-be8058c1cb7c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a ''Snapshot'' in Redis?', N'Intern', N'A snapshot is a point-in-time copy of the entire dataset stored in memory. It is saved to a binary file on disk and is used for data backup and recovery purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dd6a8ba-a158-4ab9-ae9c-be81b3d5d564', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What happens if a request exceeds the provisioned throughput capacity?', N'Middle', N'If a request exceeds the provisioned capacity, DynamoDB will throttle the request and return a ProvisionedThroughputExceededException. Clients are expected to implement exponential backoff and retry logic to handle these transient failures gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dacb3f70-67cd-48a3-8c9f-be8400b87570', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of Hinted Handoff?', N'Intern', N'Hinted handoff is a mechanism that allows a node to store a ''hint'' when it detects that a target node is down. When the target node comes back online, the storing node delivers the missed data to ensure eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66ca0d0e-9910-42b8-89a2-be8967be9a80', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a relational and a non-relational database?', N'Intern', N'Relational databases store data in structured tables with predefined schemas and use SQL for querying. Non-relational databases, or NoSQL, use various models like document, key-value, or graph to store unstructured or semi-structured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47fe9490-eb76-4383-a15a-be89ab7b27f3', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the significance of the commit log in Cassandra''s durability model?', N'Senior', N'The commit log acts as a durable write-ahead log that records all mutations before they are applied to the memtable. In the event of a node crash, Cassandra replays the commit log to recover data that was not yet flushed to SSTables, ensuring durability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'950ce604-3bb9-4a0c-b628-be89f964876b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Transactional Outbox'' pattern?', N'Middle', N'This pattern ensures that a service can update its local database and send a message to a broker atomically. It prevents the inconsistency that occurs if a database update succeeds but the subsequent event notification fails to publish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da79a956-ae63-47a9-8cbf-be8ae2c7701c', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the ORM in Django and what are its main performance trade-offs?', N'Middle', N'The ORM provides an abstraction layer to interact with databases using Python objects instead of raw SQL. The main trade-off is that it can generate inefficient queries, such as N+1 problems, if the developer is not careful about using select_related or prefetch_related.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a44f0a2f-3f59-4ba0-8002-be8db043fe85', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When reviewing someone else''s code, what do you look for first?', N'Junior', N'I first check if the code solves the intended problem correctly and if it adheres to the project''s coding standards. Then, I look for potential bugs, readability issues, and opportunities to improve performance or logic structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52721669-5349-401b-a48f-be8e0651298f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is data normalization and why is it important?', N'Fresher', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them, which helps minimize anomalies during updates, insertions, and deletions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e5db59-08eb-4487-a6db-be8fca81ead3', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a before_request hook in Flask?', N'Junior', N'A before_request hook is a function that runs before every single request is processed by your route functions. It is commonly used for tasks like connecting to a database, checking user authentication, or logging request information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60f4929e-b6d1-48b0-abb4-be900df867ef', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are mixins in Dart, and when are they used?', N'Junior', N'Mixins are a way of reusing a class''s code in multiple class hierarchies without using inheritance. They are used to share functionality across classes that do not share the same parent class, avoiding the complexities of multiple inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6310f501-eeb5-465a-b6c8-be9438209bdc', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a primary disadvantage of using a NoSQL database?', N'Junior', N'A main disadvantage is the lack of support for complex multi-table joins and limited transaction support compared to SQL databases. This can make data reporting and maintaining strict data integrity more difficult for the application developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
