INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6c63b82-f2f3-4d00-a354-be9b39393da2', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle event delegation?', N'Fresher', N'Event delegation is handled using the .on() method, which allows you to attach an event handler to a parent element that captures events from its current or future children. This is more memory-efficient than attaching individual handlers to many elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495b5a3c-0a66-4bee-bbf2-be9d8f6bb030', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB''s partitioning strategy impact data distribution and hotspotting?', N'Senior', N'DynamoDB distributes data across partitions based on the hash key. If the hash key has low cardinality or follows a sequential pattern, requests can cluster on a single partition, leading to throughput throttling known as a hot partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa2871e9-edfb-4268-a8e1-be9e198887ed', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why does Qwik favor fine-grained reactivity?', N'Middle', N'Fine-grained reactivity allows the framework to update only the specific DOM nodes that depend on a changed piece of state. This avoids re-rendering entire component trees, which is a major performance bottleneck in traditional virtual DOM-based frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4739957-c9c8-46d7-bd65-be9ee93a93fb', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the risk of a single point of failure in a legacy system?', N'Senior', N'I perform a failure mode and effects analysis to rank the system''s components by criticality and probability of failure. The estimate is then based on the cost of downtime versus the cost of implementing a redundant, high-availability architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efa12111-2023-4a79-848b-be9effc243a5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What happens if you do not specify a primary key in a table?', N'Intern', N'While MySQL allows a table to exist without a primary key, it is considered bad practice. Without one, searching, updating, and deleting specific rows becomes slower and more difficult to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eefca2f-f281-4ced-bf59-bea32aefb68e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle request routing compared to the standard library net/http?', N'Junior', N'While the standard library uses a basic multiplexer, Echo uses a high-performance router based on a radix tree algorithm. This allows for significantly faster route matching, especially when dealing with complex path parameters or a large number of defined endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
