INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d9b6f16-88ec-4705-9346-bea9b1415e9f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between an array and a pointer?', N'Fresher', N'An array is a collection of elements of the same type stored in contiguous memory locations, and its name acts as a constant pointer to the first element. A pointer is a variable that holds an address and can be reassigned to point to different memory locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34e6ec8c-f66f-4798-9dc5-bead97bb3b82', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can you have a transaction that spans multiple tables?', N'Fresher', N'Yes, relational databases are designed to handle transactions that span multiple tables. As long as the operations are part of the same transaction block, the database ensures that all related tables are updated together atomically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b01822e2-71f7-4db7-a00e-bead9a91a3e8', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why might you ask a colleague to review your troubleshooting steps?', N'Intern', N'A fresh pair of eyes can identify assumptions you might have made or suggest a different perspective on the problem. This peer review process often helps uncover oversights and leads to a more robust and efficient solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3c3907a-7387-4b65-aabd-beaeee72c228', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle error management compared to traditional approaches?', N'Middle', N'Fiber provides a centralized error handling mechanism where developers can define a global error handler to catch and format errors consistently. This separates business logic from error logging and response formatting, ensuring a uniform API contract for client errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21646a17-22d3-4441-8390-beb00b0e71a1', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does implementing a Zero Trust Architecture change the traditional network perimeter model?', N'Senior', N'Zero Trust assumes the network is already compromised and removes the concept of a trusted internal network. It requires explicit, continuous verification of every user and device request based on identity, context, and security posture, regardless of the origin of the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
