INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23f74d10-1238-4da7-aa68-bebb24262750', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a scenario where logs are completely unavailable due to a service crashing on startup?', N'Senior', N'I would attempt to run the service in a restricted staging environment with increased verbosity and standard error output capturing. If that fails, I would inspect the environment variables, configuration files, and secrets to identify invalid parameters or missing dependencies that could be preventing the service from initializing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
