INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f13b025-0b8e-4418-8557-bedd04793d14', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of ''AppDomain'' in the context of legacy versus modern .NET.', N'Senior', N'AppDomains were designed to provide isolation within a single process, allowing code to be unloaded without restarting the application. In .NET Core and modern .NET, this concept has been deprecated in favor of AssemblyLoadContext. This change reflects a shift toward process-level isolation and simpler, more performant runtime architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
