INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee7da7cc-576c-4ce1-8e88-bee50328955e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between synchronous and asynchronous route handlers in FastAPI?', N'Junior', N'A synchronous route handler runs in the main event loop and will block it if it performs a long-running operation. An asynchronous handler uses the async keyword, allowing the server to pause that function and handle other requests while waiting for an I/O operation to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
