INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61d76a5a-a52f-4edd-82de-beed3da1e123', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a shallow copy and a deep copy in Rust?', N'Intern', N'A shallow copy involves copying only the metadata or pointers of a value, while a deep copy duplicates the actual data stored on the heap. In Rust, assigning a complex type usually moves ownership, effectively performing a shallow transfer unless a deep copy is explicitly requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
