INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09cde634-49e4-4265-9057-bef181ff1c9c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono’s ''Context'' object being mutable, and how should it be managed to prevent race conditions?', N'Senior', N'The mutability of the context object allows for efficient data sharing across middleware, such as storing a user object derived from an auth check. To prevent race conditions in asynchronous environments, developers should treat context as a local request-scoped container and avoid side effects that persist across different request lifecycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
