INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cde85e97-b5e9-44dd-bee5-bef7485aaac3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Is Svelte a library or a framework?', N'Intern', N'Svelte is often referred to as a framework, though it is technically a compiler. Because it provides a structured way to build complex user interfaces, it serves the same purpose as traditional frontend frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a93b8163-9e41-4aa3-a9aa-bef973d2fd21', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Describe how Lit components handle events and communication with parent elements.', N'Middle', N'Lit components communicate with their parents by dispatching standard DOM events via the dispatchEvent method. This maintains compatibility with native browser event bubbling and avoids tight coupling between components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
