INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'935f8f78-b225-4dcf-b304-befd428896c0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle memory management, and what is a memory leak?', N'Middle', N'Node.js uses the V8 garbage collector to automatically reclaim memory that is no longer reachable. A memory leak occurs when the application maintains references to objects that are no longer needed, preventing the garbage collector from freeing that memory and eventually leading to process crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77677644-c226-411f-b33a-befff6df850b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the function of a ''Witness Table'' in Swift''s protocol implementation?', N'Senior', N'A witness table is a lookup table that maps protocol requirements to the actual implementation methods provided by a conforming type. When a protocol method is called on an existential type, the runtime uses the witness table to identify and jump to the correct function address. This enables polymorphism while allowing different types to conform to the same protocol without knowing their concrete structure at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
