INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca7af653-9db9-4789-b912-bf2447f20b54', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is ''Index Condition Pushdown'' (ICP) and how does it reduce the number of row fetches?', N'Senior', N'ICP allows the storage engine to evaluate parts of the WHERE clause directly during the index scan rather than fetching the full row to the server layer. This reduces the number of full row reads, significantly decreasing I/O overhead for queries involving partial index matches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
