INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20652b95-593e-4eaa-8970-bf25dd964f39', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How can you implement rate limiting in an Axum application?', N'Middle', N'Rate limiting can be implemented by applying a ''RateLimit'' layer from the Tower ecosystem to the router. This allows you to restrict the number of requests a client can make per unit of time, protecting the service from abuse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f03a3bc-b25c-48e6-b211-bf2666311dfc', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''loading=lazy'' attribute on images impact the critical rendering path?', N'Senior', N'The lazy attribute defers the loading of off-screen images until they are near the viewport, which reduces initial bandwidth usage and main thread contention. This allows the browser to prioritize other critical resources, leading to faster completion of the initial page render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eb9e040-9960-4243-9f13-bf28638ea2ff', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a distributed system issue where the root cause is not immediately obvious in logs?', N'Middle', N'I would start by correlating timestamps across services using a distributed tracing tool to identify where the request latency or error propagation begins. By isolating the specific service hop that fails, I can narrow the scope of investigation to the infrastructure configuration or service logic at that point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7fae49b-263f-46e6-ba31-bf28e2572cf5', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it generally recommended to use smart pointers instead of raw pointers in modern C++?', N'Middle', N'Smart pointers automate memory management by using RAII to ensure objects are deleted when they go out of scope. This significantly reduces memory leaks and dangling pointer issues compared to manual allocation and deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d75905c-ba16-4eff-a2f4-bf2a97357bea', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the trade-offs of using Server-Side Rendering (SSR) versus Static Site Generation (SSG) regarding HTML delivery?', N'Senior', N'SSR generates HTML dynamically per request, ensuring highly personalized content but increasing time-to-first-byte and server load. SSG generates HTML at build time, offering superior performance and scalability via CDN caching, but it is less suitable for content that changes frequently based on user state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
