INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53fba461-85aa-4c46-aef3-bf47f9d7edce', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go lack traditional inheritance in its type system?', N'Senior', N'Inheritance often leads to fragile base class problems and complex, rigid hierarchies that are difficult to refactor. Go promotes composition through interfaces and embedded structs, which encourages a modular design where objects define their behavior by what they do rather than what they are. This approach keeps the type system flat, readable, and highly maintainable as systems grow in scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
