INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df6d30cb-e825-4bee-9ec1-bf4d705fc6cd', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the benefit of Rust''s type system in Actix-web?', N'Fresher', N'Rust''s strong type system ensures that many errors, such as type mismatches or null pointer exceptions, are caught at compile-time. This leads to more robust and reliable backend services with fewer runtime crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5975e5ce-b955-4702-8409-bf4e970f6da8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is scope chain in javascript?', N'Intern', N'The scope chain is the mechanism JavaScript uses to resolve variable references by searching through nested scopes from innermost to outermost until the variable is found (or a ReferenceError is thrown). Example:: Note: * The chain is created at function definition time (lexical scoping), not at call time * It only goes outward — outer scopes cannot access inner variables * Closures work because inner functions retain a reference to their outer scope chain', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a0baf5a-c461-46cf-9c5a-bf4fd0ee0563', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you handle asynchronous operations in NestJS, and what is the role of the Promise object?', N'Fresher', N'NestJS supports asynchronous operations through the use of the async and await keywords. When a function returns a Promise, it can be awaited, allowing non-blocking execution. The Promise object represents a value that may be available now, or in the future, or never. In this example, getHello() is an asynchronous method that returns a Promise. The await keyword is used to pause the execution of the function until someAsyncOperation() completes and the Promise is resolved. Promises are useful for handling single asynchronous operations. If you need to handle a stream of asynchronous values, you might want to use Observables instead, which are provided by the RxJS library and are also integrated into NestJS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11dd8931-87dd-4347-b147-bf4ff6cde8f9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Does Remix require a JavaScript-enabled browser to function?', N'Intern', N'No, Remix is designed to work even if JavaScript is disabled in the user''s browser. Because it relies on standard HTML forms and links, the core functionality remains intact for all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'747d44ba-7175-4ce4-976e-bf503bc8a286', N'075b8862-431c-4678-9767-f55359758a4a', N'What are props in Vue?', N'Junior', N'Props are custom attributes used to pass data from a parent component down to a child component. They are read-only for the child component, ensuring a unidirectional data flow that makes applications easier to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8d05a24-3de5-4da0-a952-bf54d1630e1e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the constant in action types?', N'Intern', N'Using constants for action types helps prevent typos and makes it easier to search for all occurrences of a specific action across the codebase. It improves code quality and maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037616f2-bb64-442f-a505-bf554b6b8a8f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you adjust your estimation process as a project progresses from discovery to implementation?', N'Middle', N'As more information is gathered, I shift from broad, high-level estimates to granular, task-based estimates. I regularly update the project roadmap based on actual velocity, ensuring that the estimates reflect the reality of the work completed rather than initial, less-informed guesses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9661951-8aa1-45e6-b627-bf564308f13c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle CSS styling?', N'Middle', N'Qwik supports scoped CSS and CSS-in-JS libraries that are optimized to load only the styles necessary for the current view. This ensures that the browser does not load unused CSS, further contributing to the framework''s performance focus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63a8162f-d2b5-4456-ba7f-bf56ad5e1387', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the core philosophy of the Astro framework regarding client-side JavaScript?', N'Intern', N'Astro follows an island architecture approach that prioritizes delivering zero-JavaScript by default. It renders pages into static HTML on the server and only sends JavaScript to the browser for specific interactive components, which significantly improves site performance and loading speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee429452-3df1-4df0-a583-bf56cf5075ed', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are environment variables in SvelteKit?', N'Fresher', N'Environment variables allow you to store configuration settings like API keys or database URLs outside your code. SvelteKit provides specific modules to access public variables on the client and private variables only on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f47b6f18-4f34-4cab-ada4-bf5894e0b5a2', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a relational database and a NoSQL database in terms of schema?', N'Intern', N'Relational databases use a rigid, predefined schema where data must be structured into tables with fixed rows and columns before inserting data. In contrast, NoSQL databases typically use dynamic schemas, allowing for unstructured or semi-structured data like documents or key-value pairs. This makes NoSQL databases more flexible for handling rapidly changing or varied data formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96df69f9-d6fa-4775-829a-bf5b4b4b47c7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are Python metaclasses, and how do they differ from class decorators?', N'Senior', N'Metaclasses are the ''classes of classes'' that define how a class is constructed, allowing for the modification of class creation logic at runtime. While class decorators provide a way to modify a class after it has been created, metaclasses operate at the point of definition, offering deeper control over class namespaces and inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'843e270f-73cd-40a9-ad7e-bf5b6e9fe6ec', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''Buffer Pool'' influence database scalability?', N'Senior', N'The buffer pool caches frequently accessed data pages in memory, minimizing expensive physical disk I/O. Scalability is heavily dependent on the hit ratio of this cache; as the working set grows, insufficient memory leads to thrashing, where the system spends more time moving pages between disk and memory than executing queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e46d5ae0-39c4-49e8-90f6-bf5d07c317bc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are ''filters'' in Rails controllers?', N'Intern', N'Filters are methods that are run before, after, or around controller actions. They are commonly used for tasks like ensuring a user is authenticated before allowing access to certain pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
