INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42c359ed-f350-4f37-962f-bf68f84dd475', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is Scala considered a ''statically typed'' language?', N'Fresher', N'Scala is statically typed because all type checks are performed at compile-time, ensuring that types are correct before the program runs. This approach catches many common errors early and improves performance by avoiding runtime type checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'521dbc93-b8cb-4f7b-85ab-bf6a144ccc20', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is it generally discouraged to use mutable objects as default arguments in Python functions?', N'Senior', N'Default arguments are evaluated only once at the time of function definition, not at each call. If a mutable object like a list or dictionary is used, subsequent calls to the function will share the same instance, leading to state leakage between executions. The standard practice is to use ''None'' as the default and initialize the mutable object inside the function body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
