INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fe26049-f279-4afd-9548-bf6c55f6aeb9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle asynchronous code?', N'Junior', N'Fastify natively supports async and await. If a route handler returns a promise or is defined as an async function, Fastify will automatically wait for the promise to resolve before sending the response, simplifying error handling and flow control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e4bde4e-446b-4ec0-ba1f-bf6cc8eb1f09', N'a000805c-e41f-42a9-af12-66b45348f77b', N'When should you use AdonisJS ''Events'' over standard method calls?', N'Middle', N'Events should be used when you need to trigger decoupled side effects, such as sending emails or logging, after a primary action occurs. This prevents the main execution flow from being blocked by non-essential tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcc3ad6c-1dba-4b06-b77a-bf6e599c9b97', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does the ''Suspense'' component in SolidJS integrate with its reactivity system?', N'Senior', N'Suspense in SolidJS reacts to asynchronous signals or resources; when a resource is pending, the framework tracks the suspension and prevents the UI from updating until the data is resolved. It leverages the reactive graph to determine exactly which part of the tree needs to pause rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74404e99-885a-4787-9603-bf6ec430e5f0', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the concept of stores in Svelte and when you should use them.', N'Middle', N'Stores are objects that provide a mechanism for state management outside of the component hierarchy. They are ideal for shared global state, as they allow any component to subscribe to updates without needing prop drilling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b750e9eb-54de-4374-88ec-bf700fc7b3ac', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does the ''lazyfree'' configuration parameter affect Redis background operations?', N'Senior', N'When enabled, lazyfree allows Redis to delete large objects, such as massive hashes or sets, in a background thread instead of the main event loop. This prevents the event loop from blocking while memory is being deallocated, significantly improving latency stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd109cd9a-01c6-43c6-8a39-bf726e043c4e', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the role of a ''retry strategy with exponential backoff''?', N'Middle', N'This strategy retries failed requests while increasing the delay between each attempt exponentially. It prevents overwhelming a struggling service with immediate, repetitive requests, allowing it time to recover before the next attempt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16393c83-1a7c-42d8-9d16-bf731d37ff28', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is memoization in JavaScript?', N'Intern', N'Memoization is a programming technique which attempts to increase a function''s performance by caching its previously computed results. Each time a memoized function is called, its parameters are used to index the cache. If the data is present, then it can be returned, without executing the entire function. Otherwise the function is executed and then the result is added to the cache. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faf43fdd-2fbf-4c27-a106-bf74c40df815', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of the ''Validator'' schema when dealing with nested objects?', N'Middle', N'The validator schema allows for recursive definitions, enabling the framework to validate complex, nested JSON objects passed in request bodies. This ensures that the entire payload structure is strictly typed and validated before reaching the business logic layer, preventing null pointer errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
