INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65b5220d-b2e6-4cf2-92a8-bf7a623fc7ef', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the trade-offs of using a cache layer like Redis in front of a database?', N'Middle', N'A cache layer dramatically improves read performance by serving frequent queries from memory rather than disk. However, it introduces complexity regarding cache invalidation and the risk of serving stale data if the cache and database are not synchronized properly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
