INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62a22de4-6f55-43a5-8e6d-bf7b6409c308', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between centralizing and decentralizing system authority?', N'Intern', N'Centralized systems are easier to manage and secure because control is concentrated in one place. Decentralized systems are more resilient to individual component failures and can scale horizontally, but they are more complex to synchronize and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4885fecf-84e5-4892-be78-bf8063340112', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the benefit of using NestJS''s ''ConfigModule'' with a ''load'' function over direct environment variable access?', N'Senior', N'The ''load'' function allows for the externalization and validation of configuration schemas using libraries like Joi or Zod. This approach centralizes configuration management, ensures that the application fails fast if critical environment variables are missing, and simplifies testing by allowing mock configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0372768-d694-47c0-8040-bf80aa307d10', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s OpCache improve application performance?', N'Middle', N'OpCache stores precompiled script bytecode in shared memory, eliminating the need for PHP to parse and compile source code on every request. This significantly reduces CPU overhead and latency for frequently accessed scripts. It is a fundamental optimization for production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d85c6f9-ac29-4aab-bed3-bf85cddc168e', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the role of the Database-per-Service pattern and how it impacts service autonomy.', N'Senior', N'This pattern ensures that each microservice has its own private database, preventing hidden coupling through shared schemas. It allows services to choose the optimal storage technology for their specific workload and enables independent schema evolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db49d295-fdeb-42c7-a3e5-bf882ba7f75b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''Unit'' and ''Nothing'' in Scala?', N'Fresher', N'Unit is a type that indicates a method returns no meaningful value, similar to void in other languages. Nothing is a bottom type that represents a value that never exists, often used for methods that throw exceptions or enter infinite loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f830014-28fe-4deb-84cb-bf8837b17d21', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the trade-offs of using a large number of columns in a single partition?', N'Middle', N'A partition that grows too large can cause performance degradation during compaction and increase heap pressure during reads. It is recommended to keep partition sizes manageable to ensure predictable latency and efficient cluster balancing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
