INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcab7537-e9d3-4567-835a-bf8fb36816bf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide if a system needs real-time processing versus batch processing?', N'Intern', N'Real-time processing is chosen when immediate feedback or action is required, such as in chat apps or fraud detection. Batch processing is used for heavy, non-time-sensitive data tasks that can be performed more efficiently in bulk during off-peak hours.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a9c29cd-adee-44bf-a647-bf93aad72ee7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How can you optimize a database for write-heavy workloads?', N'Middle', N'To optimize for writes, consider reducing the number of indexes, using write-ahead logging effectively, and implementing load balancing or partitioning strategies. Additionally, shifting to an asynchronous processing model where writes are queued can prevent bottlenecks during peak traffic periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb3bed75-1962-40df-9f90-bf94bcd71bc3', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the trade-offs of using Gin''s context object across goroutines?', N'Middle', N'The Gin context object is not thread-safe and is automatically recycled by the engine once the request handler returns. Accessing it from a background goroutine can lead to data races or panics, necessitating a read-only copy of necessary data before spawning the goroutine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8943ac86-d435-447a-b6fa-bf980657bf80', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''fixed'' keyword in C# and how does it interact with the runtime''s memory management?', N'Senior', N'The fixed keyword prevents the garbage collector from relocating a managed object in memory, providing a stable memory address for pointer-based operations. It is essential when interoperating with unmanaged code or performing high-performance memory manipulation, but it restricts the GC''s ability to defragment the heap in that specific memory segment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f23ca946-7a07-4363-9839-bf9a3e84186b', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ownership model fundamentally differ from traditional garbage collection in terms of memory safety and predictability?', N'Senior', N'Rust enforces memory safety at compile-time through affine types and ownership rules, eliminating the need for a runtime garbage collector. This approach provides deterministic resource cleanup and avoids the non-deterministic latency spikes associated with GC pauses, making it suitable for systems programming and real-time constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2f2230a-ce21-4b23-9cef-bf9ad6e30404', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the PostgreSQL ''Data Type''?', N'Intern', N'Data types define the kind of data that can be stored in a column, such as integers, text, dates, or booleans. They ensure data consistency and allow the database to perform specific operations based on the type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f51a3e11-1457-4b1e-aa3f-bf9ad76c4d0e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between ''lazy loading'' and ''eager loading'' in Doctrine?', N'Middle', N'Lazy loading fetches associated data only when it is explicitly accessed, which saves initial memory but can lead to the ''N+1'' query problem. Eager loading fetches the associated data in the initial query, which improves performance for known access patterns but consumes more memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97641bc3-9cc8-4a9f-a648-bf9b62ac0a36', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is it important to handle errors in asynchronous code explicitly?', N'Middle', N'Uncaught errors in asynchronous code often do not bubble up to the global scope in the same way synchronous errors do, potentially leaving the application in an inconsistent state. Proper handling ensures the promise chain is terminated gracefully and allows the application to recover or inform the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a48d38c-c3d8-42cb-879b-bf9cbad73b2b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'In a microservices architecture, how does Micronaut''s native service discovery integration improve fault tolerance?', N'Senior', N'Micronaut provides pluggable support for service discovery providers like Consul, Eureka, or Kubernetes. By integrating discovery directly into the client layer, it enables client-side load balancing and automatic retries, which prevents single points of failure and reduces dependency on centralized infrastructure load balancers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd76fc85a-6808-4fc8-8a28-bf9cfb617b80', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the Request Guard trait in Rocket''s security architecture?', N'Senior', N'Request Guards provide a declarative way to enforce authentication, authorization, or data validation before a handler is ever invoked. By decoupling security logic from business logic, they prevent common vulnerabilities like unauthorized access or malformed input processing, ensuring that handlers only execute with validated state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be8932c2-0236-42f8-93c3-bfa1be7ea32f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between the ''public'' directory and the ''src'' directory in Vite?', N'Junior', N'Files in the ''public'' directory are served at the root path and are copied as-is to the build output without being processed. Files in the ''src'' directory are processed by Vite, meaning they can be transformed, hashed, or bundled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8605716-ee5e-4323-aefa-bfa528fd66e1', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you manage database schema migrations in a high-traffic production environment without causing downtime?', N'Senior', N'Migrations must be additive and backward-compatible, meaning you should never rename or drop columns in a single deployment. Perform changes in multiple steps: first add the new column or table, update the application code to support both formats, and only remove the old structure in a subsequent deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90bdead6-4e43-45c5-835b-bfa7b0e2568d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the concept of ''Build-time validation'' in Quarkus.', N'Senior', N'Build-time validation checks for common misconfigurations—such as broken dependency injections, missing configuration properties, or invalid bean scopes—during the compilation phase. By surfacing these errors before deployment, it increases the reliability and stability of the application in production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84dc8e24-197a-490a-a31c-bfa92dfab2b1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is meant by ''polyglot persistence''?', N'Middle', N'Polyglot persistence is the strategy of using multiple data storage technologies within a single application architecture. It recognizes that different parts of an application have different data needs, such as using a graph database for social connections and a document store for user profiles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82e7f17c-57ba-4d07-b61f-bfa9b76d07d8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the pros and cons of using Promises instead of callbacks in JavaScript?', N'Intern', N'Promises offer a cleaner alternative to callbacks, helping to avoid callback hell and making asynchronous code more readable. They facilitate writing sequential and parallel asynchronous operations with ease. However, using promises may introduce slightly more complex code. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain AJAX in as much detail as possible AJAX (Asynchronous JavaScript and XML) facilitates asynchronous communication between the client and server, enabling dynamic updates to web pages without reloading. It uses techniques like XMLHttpRequest or the fetch() API to send and receive data in the background. In modern web applications, the fetch() API is more commonly used to implement AJAX. Using XMLHttpRequest Using fetch() ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35f74b55-bacb-4f96-8e24-bfaa53e19f86', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the main advantage of using ''Result'' types?', N'Junior', N'The Result type is an enum that represents the outcome of an operation, either a success containing a value or a failure containing an error. It provides a structured and type-safe way to handle operations that might fail, replacing traditional error handling patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a09cdd0-0264-430e-97d6-bfab37ddeffa', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the libuv library and why is it important?', N'Junior', N'Libuv is a multi-platform C library that provides the foundation for the Node.js Event Loop and asynchronous I/O. It manages the thread pool and handles communication with the operating system for tasks like file system access and networking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cd1db13-d817-4de4-afbd-bfac104579c1', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between @mixin and @extend?', N'Intern', N'A mixin copies the entire block of code wherever it is included, while @extend allows a selector to inherit the styles of another selector. Using @extend results in grouped selectors in the compiled CSS, which can keep the output file size smaller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39eaeec9-cf27-446f-b777-bfad10307b70', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''Nothing'' and ''Null'' in Scala?', N'Intern', N'Null is a trait that represents the absence of a value for reference types, similar to null in Java. Nothing is a subtype of every other type and represents a computation that never returns a value, often used to signal an error or infinite loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cec2ca87-7eb3-4492-9712-bfaed8aea658', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does the ''Astro'' build system prevent CSS bloat?', N'Middle', N'Astro automatically extracts and scopes CSS for each component. It only includes the styles required for the components present on the page, preventing the inclusion of unused CSS that often plagues larger component-based applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3141d37-46ed-4721-b7bb-bfb0d6229ee1', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is meant by scoping in R?', N'Fresher', N'Scoping refers to the rules that determine how R looks for the value of a variable. R uses lexical scoping, which means the visibility of variables depends on the structure of the functions and the environment in which they were defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5570ed36-0a01-4aa1-811a-bfb1b09ca283', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is Webpack considered highly configurable?', N'Intern', N'Webpack is considered highly configurable because it uses a JavaScript-based configuration file that allows developers to define complex build behaviors. Through its system of loaders and plugins, it can be adapted to almost any project structure or build requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
