INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f24d8b6a-4238-4647-bad5-bfba5992bf20', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does a Service Mesh differ from an API Gateway?', N'Middle', N'An API Gateway manages external-to-internal traffic, handling edge concerns like authentication and rate limiting for clients. A Service Mesh manages internal-to-internal service communication, providing fine-grained traffic control, mutual TLS, and observability between services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d591f9e-7ff9-4c85-bba8-bfbaa6ed65b4', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you design a secure secret management strategy for dynamic cloud environments?', N'Senior', N'You should use a centralized, hardware-backed secret management service that provides dynamic, short-lived credentials rather than static keys. This allows for automated secret rotation and detailed audit logging, ensuring that compromised credentials have a limited blast radius and lifespan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88b058b1-7f23-4af5-888c-bfbbe87d63c0', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between development mode and production mode in Vite?', N'Intern', N'In development mode, Vite serves files as-is using native ESM for speed. In production mode, Vite uses Rollup to bundle, minify, and optimize the code for the best possible browser performance and file size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15566a4b-085c-4506-84a2-bfc09a42d3ca', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between a GET and POST request in a Phoenix Router?', N'Junior', N'A GET request is intended to retrieve data and should not have side effects on the server state. A POST request is typically used to submit data to the server to create or update resources, often triggering database modifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
