INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2914d703-8746-4c18-bc63-bfc17668e233', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the role of an Operating System in managing computer resources?', N'Intern', N'The operating system acts as an intermediary between the hardware and the software applications. It manages the allocation of CPU time, memory, and storage to ensure that different programs can run simultaneously without interfering with each other. It also provides a standard interface for software to interact with hardware components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84ed7535-78cc-406a-bac0-bfc255a46373', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the difference between synchronous and asynchronous messages in Actix?', N'Junior', N'Asynchronous messages are handled via the Handle trait and do not block the actor''s thread, while synchronous messages use the Handler trait and can perform blocking operations. Synchronous messages are typically processed in a separate thread pool to avoid stalling the main event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38a19e0e-1f4e-4939-bc4d-bfc2f79a45f7', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is Elasticsearch primarily used for?', N'Fresher', N'Elasticsearch is a distributed, open-source search and analytics engine. It is primarily used for full-text search, log analytics, and operational intelligence due to its ability to store, search, and analyze large volumes of data in near real-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc5331f-b9af-4c8d-b42f-bfc41b123e98', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB determine the optimal shard key, and why is it critical for performance?', N'Senior', N'An optimal shard key must have high cardinality, low frequency, and be monotonically increasing to avoid hotspots. Poor shard key selection leads to uneven data distribution and ''jumbo chunks,'' which force the balancer to work excessively and cause uneven resource utilization across shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47fa8f33-d915-48f3-b48b-bfc5b9c2dd12', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the main advantages and challenges of using a Sidecar pattern?', N'Middle', N'The sidecar pattern allows developers to offload cross-cutting concerns like logging, monitoring, and security to a separate container, keeping the core application logic clean. However, it increases resource consumption and adds operational complexity in managing and updating the sidecar containers across the fleet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4ef5477-5e72-4e8f-bd8c-bfc6cc0e6d61', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different ways to execute external scripts?', N'Intern', N'There are three different ways to execute external scripts, 1. async: The script is downloaded in parallel to parsing the page, and executed as soon as it is available even before parsing completes. The parsing of the page is going to be interuppted once the script is downloaded completely and then the script is executed. Thereafter, the parsing of the remaining page will continue. The syntax for async usage is as shown below, 2. defer: The script is downloaded in parallel to parsing the page, and executed after the page has finished parsing. The syntax for defer usage is as shown below, 3. Neither async or defer: The script is downloaded and executed immediately by blocking parsing of the page until the script execution is completed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35f15fa6-6ac8-40f6-9265-bfc7a3645d5a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your strategy for debugging a production issue that cannot be reproduced in staging?', N'Senior', N'I would perform a ''differential analysis'' between the environments, comparing traffic volume, hardware specifications, data distribution, and configuration parameters. If the discrepancy persists, I would introduce targeted, safe telemetry into the production environment to capture runtime state during the occurrence of the issue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b78a750-943e-4142-9106-bfc8a40e175c', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle concurrency control during document updates?', N'Middle', N'Elasticsearch uses optimistic concurrency control with the ''if_seq_no'' and ''if_primary_term'' parameters. This ensures that a document is only updated if the version in the database matches the version the client last read, preventing lost updates in multi-threaded environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48becdce-a707-4fbd-9e8d-bfc8c0e7463d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are query parameters in Rocket?', N'Intern', N'Query parameters are key-value pairs appended to the end of a URL. Rocket allows handlers to extract these values automatically by adding a parameter to the function signature with a specific type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b9fd45d-17f0-4b80-a527-bfc9ef0d5b05', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a Goroutine in Go and how does it differ from a standard operating system thread?', N'Intern', N'A Goroutine is a lightweight execution thread managed by the Go runtime rather than the operating system. They are much more memory-efficient than OS threads, allowing a single program to run thousands of concurrent tasks without significant performance overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee190ad-f21c-4976-9e9c-bfca363510f7', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is ''layout'' nesting in SvelteKit superior to a single monolithic layout?', N'Senior', N'Nested layouts allow for modular, hierarchical UI structures where only necessary parts of the component tree re-render during navigation. This improves performance by preserving state in shared parent layouts while only updating the specific content segments defined by the child routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f858231-5147-4c8e-804c-bfcf5c218eaf', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the impact of using ''teleport'' components in an SSR environment?', N'Senior', N'Teleport components pose a challenge in SSR because they attempt to render content outside of the main application mounting point, which may not exist during the server-side render phase. Nuxt manages this by serializing the teleported content correctly, but developers must ensure that the target DOM element is available on the client to avoid hydration errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7999fa84-4974-44ad-928e-bfcff8640921', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage documentation while working on a project?', N'Fresher', N'I document my progress incrementally rather than leaving it for the end. I update comments or project notes whenever I reach a milestone, ensuring that the documentation stays current with the actual implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'473841a9-737a-42b4-a661-bfd8a4f5382e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the concept of cache locality.', N'Middle', N'Cache locality refers to the tendency of a processor or system to access the same set of memory locations repeatedly over a short period. Designing systems to favor temporal and spatial locality ensures higher cache hit rates and improves overall throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e05fd06-a1f8-4154-945b-bfd9947272f0', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a WSGI server and why is it necessary for production Flask apps?', N'Junior', N'WSGI is a standard interface between web servers and Python web applications. Flask''s built-in development server is not secure or efficient enough for production, so a production-grade WSGI server like Gunicorn or uWSGI is used to handle concurrent requests reliably.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a703b8e-1990-4b95-8366-bfe19b8e1fcf', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are the limitations of Go''s type system regarding generics and variance?', N'Senior', N'Go''s generics are implemented via monomorphization, which generates specific code for each type instantiation to ensure performance. However, Go does not support variance in generics; an interface or type with a generic parameter is considered invariant. This prevents certain polymorphic patterns common in languages with covariance or contravariance, favoring type safety and simplicity over complex subtyping relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6651fa3e-4c9e-45f7-aba9-bfe332f1b4ac', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is ''strict'' mode recommended in TypeScript?', N'Fresher', N'Strict mode enables a set of compiler checks that significantly improve type safety across the application. It forces developers to write more explicit code, which helps catch subtle bugs that would otherwise go unnoticed in looser settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f67455da-9881-4f52-ace8-bfe6fe73262b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of Axum using the ''http'' crate types?', N'Intern', N'By using the standard http crate types, Axum remains compatible with the wider Rust ecosystem. This allows developers to use various third-party libraries that also adhere to these standard definitions for requests and responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a77f7193-1f85-4282-a9f4-bfec7c17ac1b', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between a ref and reactive in the Composition API?', N'Junior', N'Ref can hold any data type, including primitives, and requires accessing its value via a .value property. Reactive only accepts objects and provides a deep reactive proxy, allowing you to access properties directly without needing .value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8799093c-b8a1-412e-8e14-bfed60623462', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of ''Escape Analysis'' and how the JVM utilizes it for object allocation optimization.', N'Senior', N'Escape analysis determines if an object''s scope is confined to the method where it is created. If the object does not escape, the JIT compiler can perform stack allocation instead of heap allocation or eliminate the object entirely through scalar replacement, significantly reducing pressure on the garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed32b4d6-0f3e-413b-a276-bfee4d2a5d35', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is Garbage Collection?', N'Intern', N'The concept of removing unused or unreferenced objects from the memory location is known as a Garbage Collection. While executing the program, if garbage collection takes place then more memory space is available for the program and rest of the program execution becomes faster. Garbage collector is a predefined program, which removes the unused or unreferenced objects from the memory location. Any object reference count becomes zero then we call that object as a unused or unreferenced object Then no.of reference variables which are pointing the object is known as a reference count of the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12d855c9-f298-4bc9-94df-bfee63f09502', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Eloquent ORM and why is it used?', N'Fresher', N'Eloquent is Laravel''s built-in Object-Relational Mapper that provides an expressive, object-oriented syntax for interacting with database tables. It allows developers to work with database records as objects, eliminating the need to write complex manual SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
