INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b183a16-62cf-4e5f-ae13-bff0faaf2b48', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the ''Template'' compilation in Phoenix, and how does it optimize runtime performance?', N'Senior', N'Phoenix compiles EEx templates into highly optimized Elixir code at compile time, treating them as functions. This eliminates the runtime overhead of parsing and interpreting template files during a request, resulting in extremely fast view rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca3f4725-2f4f-4faa-8401-bff38c6a34cd', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do ''Read-Copy-Update'' (RCU) mechanisms improve performance in high-read systems?', N'Senior', N'RCU allows multiple readers to access data concurrently without locks, even while a writer is modifying it. It creates a new copy for the modification and atomically switches the pointer, ensuring readers always see a consistent, although potentially slightly stale, version of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e191f4de-9165-4d33-8a06-bff968bbefc6', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a local variable and a global variable?', N'Intern', N'A local variable is declared inside a function or block and is only accessible within that specific scope. A global variable is declared outside of all functions and is accessible from any part of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
