INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb5440c5-abf3-4c10-b0c6-c0024d4426c9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What does the recycling rule mean in R?', N'Junior', N'The recycling rule is an automatic behavior where R stretches a shorter vector to match the length of a longer vector during an operation. If the lengths are not multiples of each other, R will typically issue a warning while still performing the calculation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aa1a062-4991-49cd-bdf5-c002aa5fa6d8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are Promises and how do they work?', N'Intern', N'Promises in JavaScript are objects that represent the eventual completion (or failure) of an asynchronous operation and its resulting value. They have three states: pending, fulfilled, and rejected. You can handle the results of a promise using the .then() method for success and the .catch() method for errors. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the different states of a Promise A Promise in JavaScript can be in one of three states: pending, fulfilled, or rejected. When a Promise is created, it starts in the pending state. If the operation completes successfully, the Promise transitions to the fulfilled state, and if it fails, it transitions to the rejected state. Here''s a quick example: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0979f58-3cce-48d1-ba10-c005bc3ea728', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why might you choose to use a ''layout'' in Nuxt rather than creating a wrapper component?', N'Middle', N'Layouts provide a standardized structure for pages, such as headers and footers, that persist across route changes. Using layouts keeps page components focused on their specific content and allows for seamless transitions between pages that share the same architectural shell.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2bad1c4-4b13-4c03-8680-c00663d1eb48', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do you ensure thread safety when using global variables in C?', N'Middle', N'Global variables are shared across threads, so they must be protected using synchronization primitives like mutexes or semaphores to prevent race conditions. Alternatively, using thread-local storage with the _Thread_local keyword ensures that each thread has its own private instance of the variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea510909-01d4-4967-916d-c0074c70b9bc', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How can Gin be optimized for high-performance WebSocket communication?', N'Senior', N'Gin is primarily designed for request-response cycles, so WebSocket handling requires upgrading the connection and handing off the underlying net.Conn to a dedicated manager. Keeping Gin’s overhead low by offloading socket management to a separate pool of goroutines prevents the HTTP router from becoming a bottleneck during long-lived connection management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7d28462-3954-4ef0-8ee0-c008840d9366', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between a value type and a reference type?', N'Intern', N'Value types hold their data directly in memory, typically on the stack, and include types like integers and structures. Reference types store a pointer to the data''s location on the heap, and include objects like classes and strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0cec6e7-a1cd-44ca-a224-c00b7d65aa2c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is the finalizer mechanism deprecated in modern Java and what is the recommended alternative?', N'Senior', N'Finalizers are unreliable because they are executed by a low-priority thread, leading to potential resource leaks and unpredictable object reclamation delays. The recommended alternative is the Cleaner API or the AutoCloseable interface with try-with-resources, which provide explicit control over resource lifecycle management and timely deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9390d26d-f1a4-41ec-8753-c00bb0e218c7', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the benefit of using an Identity Provider (IdP) like OAuth2/OIDC?', N'Middle', N'Using an IdP centralizes user authentication and management, allowing for Single Sign-On (SSO) across multiple applications. It reduces the risk associated with managing credentials internally and provides standardized, secure authorization flows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3e70c6d-41ba-43d2-8461-c00dbbb21fec', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach learning a new tool or technology for a project?', N'Intern', N'I start by reviewing the official documentation and following a tutorial to get a basic working example. Then, I apply it to a small part of the project to understand its practical limitations and strengths before integrating it fully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6a55f76-1f0f-4f03-b516-c00ea55bc0d9', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''connect'' function or ''useSelector'' hook determine when a component should re-render?', N'Middle', N'These tools perform a reference equality check on the result of the selector function. If the returned value is strictly equal to the previous value, the component will skip the re-render process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1329252a-2ca5-4269-a7e3-c0103b781403', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''partial'' classes and methods?', N'Fresher', N'A partial class allows splitting the definition of a class across multiple files. A partial method allows one part of a class to define a signature and another part to provide the implementation, or leave it empty if not needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2e8ba42-06bc-4f23-9ec8-c01066f2923c', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of ''Lifetimes'' in the Rust compiler''s verification process?', N'Senior', N'Lifetimes are a mechanism for the compiler to track how long references remain valid, ensuring they do not point to deallocated memory. By analyzing the relationship between the scope of data and the scope of references, the compiler can mathematically prove the absence of dangling pointers without runtime checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c280d06-75da-4f5e-a089-c011b797d462', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a ''ForeignKey'' and a ''ManyToManyField''?', N'Junior', N'A ForeignKey represents a one-to-many relationship where one object is associated with one parent object. A ManyToManyField represents a relationship where multiple objects on one side can be associated with multiple objects on the other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b8a3961-29b8-40e4-91df-c0142d5d9d32', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle the trade-off between performance and the ''magic'' of its declarative directive system?', N'Senior', N'Alpine achieves its declarative syntax by scanning the DOM and mapping directives to internal JS expressions, which introduces a slight initialization overhead. While this ''magic'' simplifies development, it can lead to performance bottlenecks in massive DOM trees if not managed with careful nesting. The tradeoff is a significant reduction in boilerplate code in exchange for a runtime cost in DOM tree traversal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0712c5aa-4374-4989-9ab5-c01566194ca5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a system where background workers are failing to complete tasks within the expected timeframe?', N'Senior', N'I would analyze the worker concurrency settings, the size of the task queue, and the efficiency of the task execution logic itself. I would also check for external dependencies that the workers might be waiting on, such as database locks or slow downstream service calls that are holding up the worker thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53419988-52f2-459d-8d0e-c015f458b02e', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Describe the impact of the N+1 query problem in Django and how to mitigate it.', N'Senior', N'The N+1 problem occurs when accessing related model fields in a loop, triggering individual queries for each iteration. It is mitigated by using select_related for foreign key relationships and prefetch_related for many-to-many or reverse foreign key relationships to fetch data in bulk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70965336-3f38-47ea-ba0e-c0177f4d9bb4', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can you have transactions across multiple tables?', N'Junior', N'Yes, a transaction can involve operations on any number of tables. The database ensures that all changes across all affected tables are treated as a single atomic unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
