INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90d0a043-ffd2-416c-86c9-c01fb718ffab', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing for security, how do you decide where to implement validation and authorization?', N'Middle', N'I apply a ''defense in depth'' strategy. Validation must occur at the entry point of the system and again at the database layer. Authorization should be enforced at the API Gateway level for coarse-grained access and within the service layer for fine-grained resource-level control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f677e7d-d1a4-43d5-a7c7-c02106e328be', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of ''Micronaut Context'' in a non-web application?', N'Middle', N'Micronaut Context allows you to bootstrap the dependency injection container for standalone applications, CLI tools, or background workers. It provides the same bean management capabilities as the web server, allowing for modularity and testability outside of an HTTP context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69c535e3-70f8-4cef-a5c7-c0214b2ff138', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is an enumerated type?', N'Intern', N'An enumerated type is a user-defined type consisting of a set of named integer constants. It is used to make code more readable by replacing raw numbers with descriptive names that represent specific states or categories.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0af0b826-1292-432b-a19f-c021a87d00d2', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are Global Secondary Indexes (GSI) and how do they differ from Local Secondary Indexes (LSI)?', N'Middle', N'A GSI allows you to query data using a partition key different from the base table, and it can be created at any time. An LSI shares the same partition key as the base table but uses a different sort key, and it must be defined at the time of table creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d60cf93-0930-41fa-93a2-c02523f7305a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of the ''inline'' keyword in modern C++?', N'Middle', N'The inline keyword acts as a hint to the compiler to perform function inlining, which replaces the function call with the actual function body to eliminate overhead. In modern C++, it is also used to allow defining functions in header files without violating the One Definition Rule.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'344d44d6-87c7-48fc-af4e-c02849ea2d74', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the benefit of using a load balancer?', N'Middle', N'A load balancer distributes incoming network traffic across multiple servers to ensure no single server bears too much load. This increases the responsiveness and availability of applications while providing a mechanism to easily add or remove servers without downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e38cf009-de4c-4d5c-9206-c0285a1488e7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the concept of ''Covered Queries'' and their efficiency.', N'Senior', N'A covered query occurs when all fields requested in the query are present in the index used to satisfy the filter. Since the database does not need to fetch the actual documents from disk, the query is executed significantly faster by only scanning the index tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa851c89-435b-4c61-a29b-c0293e4e4fc9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the database engine ensure transaction isolation using locks?', N'Middle', N'The engine uses lock managers to grant shared locks for reading and exclusive locks for writing. By enforcing protocols like Two-Phase Locking, the engine ensures that a transaction releases its locks only after it has completed all its operations, preventing data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af235dbe-3e22-45fd-a034-c02964f10112', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How can you test asynchronous tasks in a Django application?', N'Middle', N'When using task queues like Celery, you should test the task functions by running them synchronously in your test suite. This allows you to verify the logic without needing to start a background worker process, ensuring your tests remain fast and deterministic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3baa171d-91e9-4d68-a97d-c02b6594cd80', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the difference between normalization and denormalization?', N'Intern', N'Normalization involves organizing data to reduce redundancy, which is standard in SQL databases. Denormalization, common in NoSQL, involves combining related data into a single record to optimize read performance at the cost of potential data redundancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c78d674b-f46c-4145-9960-c0320df637a2', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a ''WeakReference'' and when is it used?', N'Middle', N'A WeakReference allows the garbage collector to reclaim an object while still maintaining a reference to it. It is useful for implementing caches or scenarios where you want to keep an object in memory if it exists but do not want to prevent its collection if memory pressure is high.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fb722a8-2a6f-445b-816c-c0327898ea94', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Can DynamoDB store complex data structures?', N'Intern', N'Yes, DynamoDB supports document data types, including lists and maps. This allows you to nest data structures within a single attribute, providing flexibility for complex information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0710bbd3-6af4-4d63-b403-c03310345a7d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does ''Strict Two-Phase Locking'' (S2PL) differ from standard 2PL?', N'Senior', N'Strict 2PL requires that all exclusive locks held by a transaction be released only after the transaction commits or aborts. This prevents cascading rollbacks and ensures that other transactions cannot read uncommitted data, providing a higher level of isolation than standard 2PL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e310eef-9cee-4a13-81c1-c03403b432ed', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is dynamic typing in the context of Python?', N'Intern', N'Dynamic typing means that the type of a variable is determined at runtime rather than at compile time. In Python, you do not need to declare the data type of a variable when you create it, and the same variable can hold different types of data throughout the execution of a program. This provides flexibility but requires developers to be mindful of types during program logic to avoid runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ca6d77d-330f-4864-aff7-c03bd8bbf472', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the ''checkpoint'' process work?', N'Middle', N'A checkpoint is a point in the WAL sequence at which all data files are guaranteed to be updated with the information in the log. Frequent checkpoints increase I/O load, while infrequent ones increase the time required for crash recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcd79608-9793-4b53-8012-c040fdd6a363', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin facilitate graceful shutdowns in a microservices architecture?', N'Senior', N'Gin does not handle graceful shutdown natively; it relies on the standard http.Server object''s Shutdown method. In a production environment, you should capture OS signals, stop accepting new requests, and allow existing connections to drain before exiting the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
