INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9de05f0-f11e-4806-8686-c044adef9ffd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage cross-cutting concerns like logging, tracing, and authentication in microservices?', N'Senior', N'I prefer using a sidecar pattern or a service mesh to handle cross-cutting concerns, which keeps the application logic clean and consistent across different services. This centralization allows for unified policy enforcement and observability without requiring individual teams to maintain duplicate boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6b52dca-96d7-4841-bf49-c0472982a29a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the role of the Svelte compiler''s ''invalidation'' mechanism in reactivity.', N'Senior', N'Svelte tracks state changes through static analysis during compilation, identifying every assignment to a reactive variable. When a variable is updated, the compiler injects a reactive update call immediately following the assignment, ensuring the DOM reflects the state change without a secondary reconciliation phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
