INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8af3b01-3862-4398-8173-c052231c5628', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''mixins'' system work, and why is it preferred over multiple inheritance?', N'Middle', N'Mixins allow code reuse across classes without creating a rigid hierarchical structure. By avoiding multiple inheritance, Dart bypasses the diamond problem, where conflicts arise from inheriting the same method from two different parent classes, leading to a cleaner and more maintainable architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a9ee2de-381a-4605-8597-c05225deec53', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle concurrent requests?', N'Middle', N'Flask itself is a synchronous framework, so it handles one request at a time per worker process. To handle concurrent requests, you must deploy Flask with a production-grade WSGI server like Gunicorn or uWSGI, which manages a pool of worker processes or threads to serve multiple requests in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
