INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'708849ea-6bba-463f-9d46-c062f74f0e44', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you handle global state in a Next.js App Router application?', N'Middle', N'For global state, you typically use React Context wrapped in a Client Component provider at the root level of your layout. Alternatively, you can use external state management libraries, but they must be initialized within Client Components since Server Components cannot hold client-side state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1c527a4-609f-4469-82e5-c063db043fe6', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the ''Write-Ahead Logging'' (WAL) technique and why is it important for database reliability?', N'Middle', N'WAL ensures data integrity by recording all changes to a log file on stable storage before they are applied to the main database files. In the event of a crash, the system can replay these logs to reconstruct the state of the database, ensuring no committed transactions are lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'825ff0ec-d77e-4196-9f19-c066dd36f553', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle file caching?', N'Intern', N'Webpack can generate unique file names using content hashes, which change whenever the file content changes. This allows browsers to cache files efficiently, as they only download new versions when the file content is actually modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd68d25dd-6041-4346-8a07-c069f32570c2', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the implications of using Redis as a primary data store versus a caching layer?', N'Senior', N'Using Redis as a primary store requires careful configuration of persistence and memory eviction policies to prevent data loss. As a cache, the primary concern is hit ratio and cache invalidation strategies, whereas primary storage demands high availability, replication lag management, and disaster recovery planning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'097d882e-1605-403d-8ab7-c06a8c846dc1', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an alias in SQL?', N'Junior', N'An alias is a temporary name given to a table or a column in a query to make the output more readable or to simplify references. It is typically used during complex joins or when performing calculations on columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1669592b-90fd-4223-b1bc-c06b08f30c39', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the MongoDB WiredTiger storage engine implement concurrency control?', N'Senior', N'WiredTiger uses optimistic concurrency control at the document level. It utilizes multi-version concurrency control to allow multiple readers and writers to access the same collection simultaneously without locking the entire database, only escalating to intent locks at the collection level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
