INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3cd4465-1bfd-416e-9441-c06cebb9f88e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Describe the concept of ''tearing'' in React concurrent rendering and how useDeferredValue helps mitigate it.', N'Senior', N'Tearing occurs when the UI displays inconsistent versions of data because state updates were processed in separate chunks without synchronization. useDeferredValue allows you to defer updating non-urgent parts of the UI, ensuring that urgent updates take precedence and preventing the user from seeing partial or mismatched visual states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bffc014-57ae-417f-9f4a-c06dee531739', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary trade-off when using Qwik''s `useTask$` for side effects?', N'Senior', N'The primary trade-off is that `useTask$` runs both on the server and the client, which can lead to double execution if not handled carefully. Developers must implement guards to ensure that specific side effects, such as API calls or DOM manipulations, occur only in the appropriate environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
