INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bd3e9cb-1af0-4c75-b8f9-c075f9f32e46', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the primary architectural benefits of moving from a monolith to a microservices architecture in PHP?', N'Senior', N'The main benefit is the ability to independently scale and deploy specific business domains. Since each service runs in an isolated PHP-FPM environment, faults are contained, and resource allocation can be tuned specifically for the workload of each microservice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
