INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a9eab9a-35f1-40b5-9713-c07beeed6628', N'954a0331-deff-4399-b588-96f39fec001d', N'Why should you use an InjectionToken instead of a class for dependency injection?', N'Middle', N'InjectionTokens are used for types that do not have a runtime representation, such as interfaces or primitive values like configuration strings. Using a class for injection can lead to tree-shaking issues, whereas tokens provide a lightweight, unique identifier that does not force the inclusion of unnecessary code in the final bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
