INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'186b4c23-60ed-4014-ac45-c08b5f19158e', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What role do Controllers play in scaling a Litestar application?', N'Senior', N'Controllers provide a modular way to group related request handlers, allowing for the application of middleware, security guards, and dependencies at the class level. This hierarchical structure prevents the ''fat route file'' anti-pattern and enables team-based scaling where different modules can be developed and registered independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89c03e64-ea6f-453c-b4b8-c091008d3670', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What does ''utility-first'' mean?', N'Intern', N'Utility-first means that the framework provides small, single-purpose classes that do one thing, such as setting a margin, color, or font size. This approach allows developers to style elements without leaving their HTML or writing traditional CSS rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e20c178f-4426-4edb-a7c6-c0910223e1db', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is the order of Tailwind''s core plugins and custom plugins significant during the build process?', N'Senior', N'The order of plugins determines the order of the generated CSS in the final output, which is crucial for managing the cascade. If a custom plugin relies on a utility defined in a core plugin, the custom plugin must be ordered correctly to ensure that the generated CSS rules have the correct specificity and override order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4157ded2-84f4-4bf5-94db-c092474a9315', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a Data Transfer Object?', N'Intern', N'A Data Transfer Object is an object that carries data between processes. It is used in APIs to decouple the internal database model from the structure of the data exposed to the client, improving security and maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ecb048-3e16-4df8-8f2c-c092d8f40548', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you pass data from a child component back to a parent?', N'Junior', N'A child component communicates with a parent by emitting custom events using the emit function. The parent listens for these events and can execute methods or update its own data in response to the payload provided by the child.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eba3102-9d3f-4538-9d15-c093b7932dcf', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Model-View-Controller (MVC) pattern in Rails?', N'Junior', N'MVC is a design pattern that separates an application into three logical components. The Model handles data and business logic, the View manages the user interface and presentation, and the Controller acts as an intermediary that processes requests and coordinates between the Model and the View.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f512518-8f4c-43fc-a317-c09751fadd23', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can you prevent SQL injection vulnerabilities in JavaScript applications?', N'Fresher', N'To prevent SQL injection vulnerabilities in JavaScript applications, always use parameterized queries or prepared statements instead of string concatenation to construct SQL queries. This ensures that user input is treated as data and not executable code. Additionally, use ORM libraries that handle SQL injection prevention for you, and always validate and sanitize user inputs. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9d9dd61-1b72-4dda-a4c4-c09dc1b848ed', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is globalThis, and what is the importance of it?', N'Intern', N'Nowadays JavaScript language is used in a wide variety of environments and each environment has its own object model. Due to this fact, there are different ways(syntax) to access the global object. 1. In web browser, the global object is accessible via window, self, or frames. 2. In Node environment, you have to use global. 3. In Web workers, the global object is available through self. The globalThis property provides a standard way of accessing the global object without writing various code snippet to support multiple environments. For example, the global object retuned from multiple environments as shown below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e9d3941-3e58-49e0-afa5-c09f906ada40', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the purpose of the ''Recover'' middleware in Fiber?', N'Junior', N'The Recover middleware is used to prevent the application from crashing when a panic occurs inside a handler. It catches the panic, logs the error, and returns a 500 Internal Server Error response to the client instead of allowing the process to terminate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97802ff1-99c3-48f3-be39-c09fc3e4eee0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do database checkpoints improve recovery performance?', N'Middle', N'Checkpoints periodically flush modified data from memory to disk and record a point of consistency in the transaction log. During recovery, the database only needs to process the log starting from the last successful checkpoint, significantly reducing downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a89a23b8-d53a-4622-bde6-c0a386611171', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the concept of ACID properties in the context of database transactions.', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, meaning a transaction is either fully completed or not at all, and the database remains in a valid state even in the event of a system failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'256f4559-2eb5-40e7-a089-c0a4c8c076f3', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the role of an API schema registry in a microservices ecosystem?', N'Senior', N'A schema registry acts as a central repository for API contracts, ensuring consistency and enabling automated testing of compatibility. It prevents breaking changes by validating proposed updates against existing consumers before deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d779079-0fbf-4473-ae3d-c0a63a8f6019', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle service discovery in a dynamic, containerized microservices environment?', N'Senior', N'Use a service registry or a platform-native discovery mechanism like Kubernetes DNS. Services register their network locations upon startup, and clients or load balancers query the registry to resolve service names to dynamic IP addresses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf26c613-6724-4c1b-9cdb-c0a76eb9d24b', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB ensure atomicity and isolation during multi-item transactions?', N'Middle', N'DynamoDB supports ACID transactions through TransactWriteItems and TransactGetItems operations. These ensure that multiple operations across one or more tables either all succeed or all fail, maintaining data integrity without requiring application-side locking mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd085d474-21e2-4cda-a425-c0a9eae19436', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does the choice of template engine in Express impact performance and security?', N'Senior', N'Server-side rendering in Express can be a performance bottleneck if the template engine is synchronous or lacks proper caching. Security-wise, failure to use engines with auto-escaping features exposes the application to Cross-Site Scripting (XSS) vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0623444-f946-4172-a334-c0ac6da30481', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is it important to use ''relative'' paths for links in SvelteKit?', N'Middle', N'Using relative paths ensures that the router can correctly resolve links regardless of the base URL or deployment environment. This makes the application more portable and prevents issues when the site is hosted in a subdirectory or behind a proxy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
