INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78da3270-b11b-4047-8159-c0b49b81d5d2', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Discuss the impact of ''Data Locality'' on performance in large-scale distributed systems.', N'Senior', N'Data locality involves moving computation to where the data resides rather than moving massive datasets over the network. This significantly reduces latency and network bandwidth consumption, which is a fundamental optimization for big data processing frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
