INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c817f23-36c1-4a7f-831d-c0b8c651391a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the trade-offs of using Qwik''s fine-grained lazy loading compared to a standard SPA framework?', N'Senior', N'While Qwik drastically improves startup performance and Core Web Vitals, it requires a more complex build pipeline and server-side infrastructure to manage the serialization of state. Developers must also be mindful of closure limitations, as the framework relies on static analysis to split code into small, loadable chunks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8376154-d497-4716-8a16-c0b9dfe7be30', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to use a microservices architecture or a monolithic architecture for a new project?', N'Junior', N'Monoliths are generally better for small teams and early-stage projects because they are simpler to deploy, test, and debug. Microservices should be considered when the system needs to scale independently, involves large teams working on different domains, or requires different technology stacks for various components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0429193-8b97-442c-8c84-c0ba12cc01df', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does log compaction in a message broker differ from traditional message deletion or expiration policies?', N'Senior', N'Traditional deletion removes messages based on time or size, whereas log compaction retains the latest state for every unique key within the log. This is essential for event-sourced systems where you need to reconstruct the current state of an entity by replaying its most recent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
