INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2de81fa-9ec8-4df8-b3d5-c0be7bc46683', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Startup class or Program file configuration?', N'Junior', N'These files are the entry point of the application where you configure services, set up the request processing pipeline, and define the application''s behavior. They act as the central hub for initializing dependencies and middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'425272b4-f0d7-4228-8580-c0c090f45ec5', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of jQuery''s .each() method, and how does it differ from Array.prototype.forEach?', N'Middle', N'jQuery''s .each() is designed for iterating over jQuery-wrapped collections and provides an index and the raw DOM element as arguments. Array.prototype.forEach is a native method for iterating over standard arrays, and using it on a jQuery object requires converting the object to an array first.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbf41951-ef82-44ae-afed-c0c0e9438fd2', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the significance of the ''Confused Deputy'' problem in system design?', N'Senior', N'The Confused Deputy problem occurs when a privileged service is coerced into misusing its authority by an unprivileged user. To prevent this, services must never perform actions on behalf of another entity without validating the caller''s authorization for the specific target resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19a6c742-0e56-462b-95c0-c0c145507562', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between a Service and a Component in Angular?', N'Middle', N'A component is responsible for managing the view and user interactions, while a service handles business logic, data fetching, and state sharing. Separating these concerns makes the codebase more modular and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9041fed2-2d52-4678-9fc8-c0c15b8ad86c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Can Rocket serve static files?', N'Intern', N'Yes, Rocket provides a built-in static file server. It can be configured to serve files from a specific directory, making it easy to deliver assets like images, CSS, or client-side JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53bd6339-0c20-47c0-8acb-c0c18f62f5ae', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut achieve lower memory consumption compared to traditional reflection-based frameworks?', N'Middle', N'Micronaut uses Ahead-of-Time (AOT) compilation to perform dependency injection and aspect-oriented programming at compile time. By generating bytecode during the build process instead of relying on runtime reflection, it eliminates the need for large metadata caches and reduces startup time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'891b7f07-e4f7-46d9-83c3-c0c198bba8ed', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is it generally difficult to perform complex joins in NoSQL databases?', N'Middle', N'NoSQL databases are typically distributed across multiple servers, making cross-node joins computationally expensive due to network latency. The architecture is designed to avoid joins by structuring data to be self-contained within a single record or document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'220b2ff8-b485-4203-a496-c0c3a06f5512', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do Redis transactions work, and do they provide atomicity like SQL transactions?', N'Middle', N'Redis transactions use the MULTI, EXEC, and DISCARD commands to queue a sequence of operations that are executed sequentially. While they ensure that all commands in a block are processed without interruption, they do not support true rollback capabilities if an error occurs during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c58eb9c-dd21-4485-91a9-c0c57325a67f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the purpose of the Kestrel web server and why a reverse proxy is often used in front of it.', N'Middle', N'Kestrel is a cross-platform, high-performance web server designed specifically for ASP.NET Core applications. A reverse proxy like Nginx or IIS is placed in front of it to handle edge concerns such as SSL termination, request buffering, static file caching, and protection against certain types of denial-of-service attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06f182db-db2f-4305-a614-c0c59d10e969', N'4c000000-0000-0000-0000-000000000005', N'How do you ensure idempotency in a distributed message processing system?', N'Senior', N'Idempotency is typically achieved by assigning a unique request identifier to every operation and tracking processed IDs in a persistent store like Redis or a database. Before executing an action, the system checks if the ID has already been recorded, preventing duplicate side effects from retried requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
