INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb0859c9-7015-4968-aa13-c0c7c7fb67b2', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut optimize startup time in a cloud-native, auto-scaling environment?', N'Senior', N'By eliminating reflection, proxy generation, and dynamic classpath scanning, Micronaut reduces the application startup time to milliseconds. This is critical for environments where instances need to scale rapidly in response to load, as it minimizes the time between process invocation and readiness to serve traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8d0d27f-769d-4849-92d5-c0c9a20898b8', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the advantage of using IHttpClientFactory in ASP.NET Core?', N'Middle', N'IHttpClientFactory manages the lifetime of underlying HttpMessageHandler instances to avoid socket exhaustion and DNS change issues. It provides a centralized way to configure named or typed clients, which simplifies the management of HTTP request headers and policies like retries or circuit breakers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd853db21-d1fa-4a07-9d41-c0c9b7d8c9f0', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux ensure that the UI stays in sync with the state?', N'Middle', N'Redux relies on the store''s subscription mechanism. When an action is dispatched and the state changes, the store notifies its subscribers, triggering the UI layer to re-render the components that rely on the updated state slices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
