INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60c09800-b6e9-4dbc-9b2d-c0d0ec808270', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a Transient and a Scoped service when using them in background tasks?', N'Middle', N'Scoped services are tied to the lifecycle of an HTTP request, so they cannot be directly injected into a Singleton background task. You must create a new scope manually using an IServiceScopeFactory to resolve scoped services within that background operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
