INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2808aea8-406a-4d90-8a3e-c0d2bc9c79a3', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the B-Tree index structure impact database performance in MySQL?', N'Middle', N'B-Tree indexes maintain data in a sorted structure, allowing the database to perform efficient range searches and equality lookups in logarithmic time. By avoiding full table scans, these indexes drastically reduce the number of disk reads required to locate specific records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4f4805e-d96e-4c41-9b65-c0d32a5372e7', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the effect of consumer group rebalancing in a system like Kafka, and how can it be mitigated?', N'Senior', N'Rebalancing pauses consumption while the broker redistributes partitions among consumers, which can lead to processing spikes or latency jitter. This can be mitigated by using static membership, increasing session timeouts, or tuning the partition assignment strategy to minimize unnecessary movements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
