INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b549466-e1e2-4fa3-9744-c0d5392c01ac', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the impact of ''Inlining'' on Swift code performance?', N'Senior', N'Inlining replaces a function call with the function''s body, eliminating the overhead of creating a new stack frame and jumping to an address. While it boosts performance, excessive inlining can lead to ''code bloat,'' where the binary size increases significantly, potentially hurting instruction cache performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdaee3e5-85a8-4a5f-89a7-c0d9617d3f8d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do you handle shared state in a multi-threaded Actix-web application?', N'Senior', N'Shared state is typically managed using ''Data'' extractors, which store thread-safe objects like Arc wrapped structures in the application''s state. This allows multiple workers to access shared resources like connection pools or configuration without explicit locking overhead in most cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bce2aa2a-1bc3-4f49-9cf7-c0daa66a1136', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the size of the jQuery library impact the critical rendering path in modern web performance metrics?', N'Senior', N'Including the entire jQuery library adds significant bytes to the initial payload, delaying the First Contentful Paint. In an era of performance-focused metrics like Core Web Vitals, the cost of loading a large, monolithic library for minor utility functions is an anti-pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d93487d-c1fd-4923-8f35-c0db107ddc30', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How does the Saga pattern manage distributed transactions?', N'Middle', N'The Saga pattern breaks a long-running transaction into a series of local transactions performed by individual services. If one step fails, the Saga executes compensating transactions to undo the changes made by previous steps, ensuring eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
