INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12e4c83a-5d97-4e37-852b-c0de9caf35e6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What makes Litestar different from older frameworks like Flask or Django?', N'Intern', N'Litestar is built from the ground up to be asynchronous using the ASGI standard, whereas older frameworks were primarily synchronous. It also heavily leverages Python type hints to provide better IDE support and automated data validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a47414-b116-4b57-86d2-c0dec21f0759', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the role of the ''ResponseModel'' parameter?', N'Fresher', N'The ''ResponseModel'' parameter is used to declare the structure of the data that the API returns. This ensures that the output is validated, serialized, and documented according to the specified Pydantic model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b93e536-6809-4644-9c8c-c0dfeb156326', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you balance the need for rapid feature delivery with the necessity of technical debt reduction?', N'Senior', N'I advocate for a consistent allocation strategy, such as dedicating 20% of engineering capacity to refactoring and debt reduction in every sprint. This ensures the codebase remains maintainable while still providing the business with the velocity required to meet market demands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'300115ea-bbfc-4315-ad4d-c0e07affb8ce', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the architectural implications of using the ''defer'' vs ''async'' attributes on script tags.', N'Senior', N'Defer maintains script execution order and waits for the DOM to be fully parsed, making it ideal for dependency-heavy applications. Async executes scripts as soon as they download, which is better for independent tracking pixels but can cause race conditions if scripts rely on DOM readiness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'555dc88d-55de-4e1f-86d4-c0e199abd29d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the role of the ''preact/compat'' layer, and what potential performance costs does it introduce?', N'Senior', N'The compat layer acts as an alias to bridge the API differences between React and Preact, allowing the use of existing React ecosystems. However, it introduces additional bundle size and potentially slower reconciliation because it must emulate React-specific behaviors that aren''t native to the core Preact engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09a538a5-e93e-4b5d-9f21-c0e2e60ea0e4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of the ''DefinePlugin'' in Webpack?', N'Middle', N'The DefinePlugin allows you to create global constants that are configured at compile time. It is commonly used to inject environment-specific variables, such as API endpoints or feature flags, directly into the source code, allowing the same code to behave differently depending on the build environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf98a47b-b53e-4ba3-848d-c0e3233206b1', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle JSON serialization?', N'Fresher', N'Micronaut uses non-blocking, efficient JSON libraries to serialize and deserialize data. It automatically handles the conversion between Java objects and JSON format for HTTP request and response bodies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7da4a3a-02b0-4a7a-a343-c0e42ef9a721', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why is the order of fields in a struct important for memory alignment?', N'Middle', N'Go aligns struct fields based on their size to optimize CPU access, often inserting padding between fields. Ordering fields from largest to smallest can reduce this padding, significantly shrinking the total memory footprint of a struct when millions of instances are stored in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8129e2a8-7ebc-4371-91ba-c0e71691a7e9', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is a LitElement?', N'Intern', N'LitElement is the base class provided by Lit for creating custom web components. It extends the native HTMLElement class and adds features like reactive properties, an efficient rendering system, and a template engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05a0ca93-4a62-4102-925f-c0eab9c8332e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind CSS cause HTML to look messy, and is this a drawback?', N'Junior', N'While utility-heavy HTML can appear cluttered, it is a trade-off for not having to manage external CSS files or worry about class naming collisions. Many developers find that using component frameworks or template partials effectively hides this complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'418e0e89-6d0f-42ee-b5f5-c0f0874de73c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle input validation errors?', N'Intern', N'When a client sends data that does not match the defined Pydantic model, FastAPI automatically catches the validation error. It returns a 422 Unprocessable Entity response to the client, explaining exactly which fields are invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a2d7ece-521c-4440-9f10-c0f1ec1c11c2', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is Sass?', N'Intern', N'Sass is a CSS preprocessor that extends CSS with features like variables, nested rules, and mixins. It allows developers to write cleaner, more maintainable code before it is compiled into standard CSS that browsers can understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03d10d4f-192a-47bb-808f-c0f299880659', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Can Redis be used as a primary database?', N'Intern', N'While Redis is often used as a cache, it can be used as a primary database if the data is transient, small enough to fit in memory, or if high performance is more critical than complex relational queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cfae1c2-3888-4ea8-8701-c0f4de5bfeea', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django ensure protection against CSRF attacks?', N'Senior', N'Django generates a unique, cryptographically strong token for every user session and requires that token to be sent back with every POST, PUT, or DELETE request. The middleware validates this token against the one stored in the user''s session, effectively blocking requests originated from unauthorized third-party sites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a04f0f6-f60f-441d-8bf8-c0f86156830d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the role of the Dart VM in development compared to production?', N'Middle', N'During development, the Dart VM uses Just-In-Time compilation to enable fast hot reloads and rapid iteration. In production, the VM is replaced by Ahead-Of-Time compilation, which converts Dart code into native machine code for improved startup performance and runtime execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b256426-bd7c-411b-a443-c0fa85907a8e', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is sequential disk I/O a core performance driver for Cassandra?', N'Senior', N'Cassandra''s storage engine is designed to append data to files, which maximizes sequential I/O and avoids the mechanical overhead of seeking on spinning disks. This sequential nature remains highly efficient on modern SSDs by reducing write wear and fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cd1e2cb-293d-48b1-b8fc-c0fb76eb02e0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the difference between a functional bug and a performance bug?', N'Junior', N'A functional bug means the system is producing incorrect results or failing to perform an action. A performance bug means the system is functioning correctly in terms of logic but is taking too long or using too many resources to complete the task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26f0da5a-7048-42ba-a5a0-c0fd4f543e9a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach learning a large, unfamiliar codebase?', N'Junior', N'I start by running the application to understand its main features, then I explore the directory structure to get a high-level view of how components are organized. I often look for common patterns or tests to see how existing features are implemented, which helps me understand the system''s architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05e0e904-85ef-4eb0-abfb-c0ff1bc1f8b2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do ''Sagas'' manage long-lived transactions in microservices architectures?', N'Senior', N'Sagas decompose a long-lived transaction into a sequence of local transactions, each updating the database and publishing an event. If a step fails, the saga executes a series of compensating transactions to undo the changes made by preceding steps, effectively providing eventual consistency without locking resources for long durations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12bede96-2d95-4cda-bf4c-c0ff96d9bafb', N'4c000000-0000-0000-0000-000000000005', N'What is a circuit breaker pattern?', N'Middle', N'The circuit breaker pattern stops an application from repeatedly trying to execute an operation that is likely to fail. It prevents cascading failures in a distributed system by failing fast and allowing the failing service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d595d39-2a4d-4aec-862a-c0fff53c5f39', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the performance implications of having a deeply nested component structure?', N'Senior', N'Deep nesting increases the complexity of the dependency injection tree and can slow down the change detection cycle if not managed correctly. It also complicates the data flow, often requiring ''prop drilling'' which makes components harder to maintain and refactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4849f0f2-b168-4350-aeb4-c103bc0b9ccf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What should you do if you encounter an error message that you do not understand?', N'Intern', N'I would document the exact error message and look it up in official documentation, technical forums, or the team''s internal knowledge base. If the information is still unclear, I would consult with a mentor or team lead to explain the context of where the error occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9e5a3ea-38de-43ce-9146-c107dc02a866', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Materialized View in Cassandra and when should it be used?', N'Middle', N'A Materialized View provides a way to query data by non-primary key columns by automatically maintaining a secondary table. It should be used when you need to query the same data by different attributes, though it incurs a performance penalty on writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd956f609-b368-4dd5-9e96-c10a9dd039e5', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How can you optimize performance when dealing with large lists?', N'Middle', N'Use the Index or For components provided by SolidJS, as they are specifically optimized for granular DOM manipulation. Avoid using map functions directly in JSX, as those do not track changes and will cause the entire list to re-render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c7e4075-5b08-448e-9247-c10bc14f38ab', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the role of the ''loader'' function in Remix''s server-side rendering strategy?', N'Senior', N'The loader acts as a server-side gatekeeper that fetches necessary data for a route before the initial HTML is sent to the client. This ensures that the user receives a fully populated page on the first paint, significantly improving Core Web Vitals like LCP.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79e8509c-5134-43c2-ae8b-c10d85a1b548', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What happens if you mutate the state inside a reducer?', N'Intern', N'Mutating the state directly inside a reducer is a bug because Redux relies on reference comparisons to detect changes. If you mutate the object, the state reference remains the same, and React components may not re-render even if the data has changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ac6d7d9-304d-4dd5-adf2-c10ee0480a1e', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between ACID and BASE models?', N'Intern', N'ACID emphasizes strict consistency and reliability, typical of relational databases, while BASE emphasizes availability and eventual consistency. BASE stands for Basically Available, Soft state, and Eventual consistency, reflecting the typical behavior of many NoSQL systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3405b862-51b4-47fd-9154-c10fa5104504', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''Panic'' mechanism affect safety and resource cleanup?', N'Senior', N'When a panic occurs, the thread either aborts or unwinds the stack, calling destructors for all objects in scope to ensure memory safety and resource cleanup. While this prevents memory leaks, it is intended for unrecoverable errors rather than standard control flow, as it can be disabled in specific environments to reduce binary size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dfa2c1b-70e6-496c-a5ee-c11182861938', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is a ''Bean'' in the context of Micronaut?', N'Junior', N'A bean is a managed object that is instantiated, configured, and assembled by the Micronaut container. These objects form the foundation of the application, representing services, controllers, and data repositories.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4b1148e-164a-4e0e-a513-c111fd55e3d4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is ''Tree Shaking'' and how does Webpack achieve it?', N'Middle', N'Tree shaking is the process of removing dead or unused code from the final bundle to reduce its size. Webpack achieves this by relying on the static structure of ES modules to identify exports that are never imported or used by other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc4c757f-65b6-412d-ac67-c113f114ad67', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What does the ''ShouldBind'' method do in Gin?', N'Intern', N'ShouldBind is a variation of the bind method that returns an error instead of automatically aborting the request. This allows developers to handle validation failures gracefully in their logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35c50718-9f73-4e5c-8b81-c1164bf8a1ab', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a post message', N'Intern', N'Post message is a method that enables cross-origin communication between Window objects.(i.e, between a page and a pop-up that it spawned, or between a page and an iframe embedded within it). Generally, scripts on different pages are allowed to access each other if and only if the pages follow same-origin policy(i.e, pages share the same protocol, port number, and host).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'957f5673-44b1-4870-9079-c116d446273d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why might ''SELECT *'' be considered an anti-pattern in production environments?', N'Middle', N'Selecting all columns increases network traffic, consumes more memory in the application, and prevents the database from using ''covering indexes.'' It also makes the application more fragile to schema changes, such as adding large text columns that are unnecessary for the specific query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbc6a935-c18f-4d8a-adcc-c1193fca108e', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the ''Copy'' trait in Rust?', N'Middle', N'The Copy trait allows a type to be implicitly copied by bitwise duplication rather than moved. It is generally reserved for simple types that do not own heap resources, as copying heap-allocated data could lead to double-free errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41e039a8-28f8-4002-a448-c119b4d33bf0', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a NULL value in a database?', N'Intern', N'A NULL value represents missing, unknown, or inapplicable data. It is important to note that NULL is not the same as zero or an empty string, as it specifically signifies the absence of a value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f81d007d-71b2-4919-b583-c119ba7b6694', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support standard Web APIs?', N'Junior', N'Yes, Hono is built entirely around standard Web APIs such as Request, Response, and Fetch. This makes it highly portable and ensures that developers can leverage their knowledge of standard browser and server-side JavaScript APIs without needing framework-specific objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d8cc39f-b88d-415a-8157-c11c4c02610f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide when to stop researching and start implementing a solution?', N'Intern', N'I stop researching once I have a clear understanding of the core concepts and a viable plan to address the requirements. While research is important, there is a point of diminishing returns where practical implementation provides more learning and value than further theoretical reading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8715c9f2-8bb1-45d1-b2a8-c11e06b403c6', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass improve maintainability compared to CSS?', N'Fresher', N'Sass improves maintainability by allowing you to break code into smaller files, use variables for global consistency, and nest selectors for better readability. These features reduce code duplication and make it much easier to update styles across large projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5de0906-b5c1-490f-9458-c1202832ff54', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''onMount'' lifecycle hook used for?', N'Junior', N'onMount is used to execute code immediately after the component is rendered and inserted into the DOM for the first time. It is the ideal place for tasks like fetching initial data or setting up third-party library integrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf386cad-b3fb-449a-aa89-c122881e0930', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle ''heisenbugs'' that disappear when you try to instrument or log them?', N'Middle', N'I would analyze the system environment and dependencies rather than the code itself, looking for timing-dependent factors like disk I/O, network jitter, or CPU scheduling. I would use non-intrusive monitoring tools that rely on existing telemetry or hardware-level traces to avoid changing the timing of the execution. If that fails, I would create a controlled reproduction environment that attempts to artificially induce the same timing stress.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08039112-4953-4756-a75f-c122a17440da', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the role of ''Consumer Groups'' in horizontal scaling.', N'Senior', N'Consumer groups allow multiple instances of a service to share the consumption load of a topic. The broker manages partition assignment among the group, ensuring that each message is processed by only one instance, thereby allowing the system to scale processing throughput linearly as more instances are added.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4b2a11f-91f6-4348-ba4d-c124c9895704', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use Preact with existing CSS-in-JS libraries?', N'Middle', N'Yes, most CSS-in-JS libraries that support React can be used with Preact via the compatibility layer. However, some libraries may require specific configurations or might perform better if they are framework-agnostic or specifically optimized for Preact''s smaller bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0491f461-3590-486d-be12-c12573d85c82', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''useActionData'' hook?', N'Intern', N'The useActionData hook allows components to access the data returned by a server-side action. It is commonly used to display validation errors or success messages after a form submission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89ae25a4-d834-49c1-9c67-c1263cd52248', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the impact of heavy write-load on the Memtable and Flush process?', N'Senior', N'High write volumes fill the Memtable quickly, triggering frequent flushes to disk. If flushes cannot keep up, the system may block incoming writes to prevent memory exhaustion, leading to significant latency spikes and throughput degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fe5ec70-cdb5-417a-8c16-c12658379d70', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between ''Box'', ''Rc'', and ''Arc''?', N'Middle', N'Box provides unique ownership on the heap. Rc provides multiple ownership for single-threaded scenarios using reference counting, while Arc provides the same for multi-threaded scenarios by using atomic reference counting to ensure thread-safe increments and decrements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de131036-fc81-4131-92f0-c12760edf256', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is meant by ''Zero JS'' by default in Astro?', N'Fresher', N'Zero JS by default means that Astro strips away all JavaScript from your components during the build process. Only the HTML and CSS are sent to the client unless you explicitly opt-in to interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b56e84bd-e572-4ff0-ace9-c127761fcdcf', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the distinction between shallow and deep copying in Python, specifically concerning nested objects.', N'Senior', N'A shallow copy creates a new object but inserts references to the objects found in the original, meaning nested objects are still shared. A deep copy recursively constructs new objects for everything found in the original, ensuring complete independence between the copy and the source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c8a420f-7dab-409b-9703-c1285b307ad2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Does Cassandra support Joins?', N'Fresher', N'No, Cassandra does not support joins. Because data is distributed across multiple nodes, performing joins would require expensive network communication, which contradicts Cassandra''s design goal of fast, localized data access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cda005c-7151-4fbb-988e-c12a7006b5a8', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the main benefit of using jQuery''s selector engine?', N'Fresher', N'The selector engine allows developers to select HTML elements using CSS-style syntax, making it much easier and more concise to target specific parts of the DOM. This replaces the more verbose and browser-inconsistent methods found in standard JavaScript, such as getting elements by ID or tag name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db27b497-156a-491b-82c8-c12a940d2fe3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the concept of ''Transaction Idempotency'' in distributed systems.', N'Senior', N'Idempotency ensures that performing the same transaction multiple times has the same effect as performing it once, which is critical for recovering from network retries. By tracking transaction IDs, a system can recognize duplicate requests and ignore them, preventing double-processing of operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d9b35b-c338-48d4-9dc5-c12ab49bfb6d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it important to use schemas in Fastify?', N'Junior', N'Schemas improve performance by allowing Fastify to optimize serialization and provide automatic documentation via Swagger. Additionally, they enforce data integrity by ensuring the request input matches the expected structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2432ac3-921b-459f-8f48-c12b616e493e', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain how the ''z-index'' property works and what causes it to fail in some scenarios.', N'Middle', N'The z-index property controls the vertical stacking order of elements, but it only functions on positioned elements. It fails or acts unexpectedly when elements are in different stacking contexts, which are created by properties like opacity, transform, or flex/grid items, causing the z-index to be scoped only to that parent''s container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95dc83d2-97f8-4c23-a35f-c12e52b89c54', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the IOptions pattern, and why is it preferred over raw configuration access?', N'Senior', N'The IOptions pattern provides a strongly-typed, decoupled way to access configuration settings, supporting features like change tracking and validation. It prevents tight coupling between the application code and the underlying configuration provider, facilitating easier testing and cleaner configuration management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6b08380-ccc7-4b5f-b6d4-c12f53e6b7c7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When should you prefer logging over simply debugging with breakpoints?', N'Junior', N'Breakpoints are useful for local troubleshooting but cannot be used in production environments where you cannot stop execution. Logging provides a persistent record of the application''s behavior and state over time, which is essential for diagnosing issues in live production systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bb5c7d5-0052-4bc1-a77e-c12f9aed4e14', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the importance of API monitoring and observability?', N'Middle', N'Monitoring and observability allow teams to track the health, latency, and error rates of an API in real-time. This is crucial for proactive incident management, capacity planning, and understanding usage patterns, which inform future design and optimization decisions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02aa4609-9e34-4bc5-8832-c132d17df560', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Discuss the impact of tail-call optimization (TCO) constraints on recursive algorithm design in Scala.', N'Senior', N'The JVM imposes strict limitations on TCO, requiring functions to be final and recursive calls to be in the tail position. This forces developers to use specific coding patterns or trampoline structures for deep recursion to avoid stack overflow errors, which can complicate the implementation of complex algorithms compared to iterative approaches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfb37472-6e67-4e24-ac76-c137cbb665c7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ''Atomicity'' mean in the context of database transactions?', N'Fresher', N'Atomicity is a property of a transaction ensuring that it is treated as a single unit of work. This means that either all operations within the transaction are completed successfully, or none of them are applied, preventing partial updates to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e196e8c-be81-4499-aa8f-c13ea57a30c1', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What happens when an actor''s mailbox becomes full?', N'Junior', N'By default, mailboxes in Actix have a capacity limit. If the mailbox is full, the sender will be asynchronously suspended or experience backpressure until there is space available to process more messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf6a1f96-828a-4cef-83dc-c14131b585d1', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the Ember Template engine?', N'Fresher', N'Ember uses Handlebars-based templates to define the user interface. These templates are HTML-based with embedded expressions that allow for dynamic content rendering and data binding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2475dc8-50f3-4647-8a3c-c142a1e67ed5', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is Rust considered a memory-safe language?', N'Fresher', N'Rust is memory-safe because its ownership model and borrow checker prevent common memory errors at compile time. By enforcing strict rules on variable scope and pointer usage, the compiler eliminates the need for a garbage collector while ensuring memory is managed safely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eac1f26-e660-4f64-820d-c1463befe653', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the difference between ''equal?'', ''eql?'', and ''=='' in Ruby.', N'Middle', N'The ''equal?'' method checks for object identity (same memory address). The ''eql?'' method is used by Hashes for key comparison, and the ''=='' operator is a general equality check that can be overridden by classes to define custom value equivalence logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cc08d2c-9fb0-476f-b917-c146914f07d9', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between Spring''s ''Blocking'' and ''Non-Blocking'' I/O models in a high-concurrency environment.', N'Senior', N'Blocking I/O uses a thread-per-request model, which can lead to thread pool exhaustion under heavy load. Non-blocking models like Spring WebFlux utilize the Reactor pattern with an event loop, allowing a small number of threads to handle a massive volume of concurrent requests by avoiding thread suspension during I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5bc0b3e-6486-4b4b-b6a7-c146ac372b83', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is DynamoDB considered a NoSQL database?', N'Fresher', N'It is considered NoSQL because it does not use SQL as its primary query language, does not require a fixed table schema, and does not support complex joins between tables. It is designed to prioritize horizontal scalability and low-latency performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bd319a4-ab09-42e0-88ef-c146ec825737', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s MRO work in inheritance?', N'Junior', N'MRO stands for Method Resolution Order, which determines the order in which Python looks for methods in a hierarchy of classes. Python uses the C3 Linearization algorithm to calculate this order, ensuring that children are checked before parents and that the order is consistent. You can view the MRO of a class by accessing its __mro__ attribute or calling the mro() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7021c5e9-e4dc-4b4d-af6c-c149a9a1ca6b', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''key'' attribute in Vue list rendering, and why is it important?', N'Middle', N'The key attribute provides a unique identifier for each node in a list, which helps Vue''s virtual DOM diffing algorithm track element identity. Without it, Vue uses an in-place patch strategy that can cause issues when list order changes or when components hold internal state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24c6866e-a9ac-4c61-a3fc-c149b8a937fe', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain how the Angular Router''s ''preloading strategy'' impacts application performance.', N'Senior', N'Preloading strategies allow the router to load lazy-loaded modules in the background after the initial application load. By choosing an optimal strategy, such as preloading only critical modules or using custom logic, you balance the initial bundle size against the perceived navigation speed for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cf57e62-932a-4b36-8607-c14a471311e9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do Actix middleware components interact with the underlying request-response cycle?', N'Senior', N'Middleware in Actix acts as a layer that intercepts the request before it reaches the handler and the response before it is sent to the client. This allows for cross-cutting concerns like logging, authentication, and compression to be applied consistently without polluting the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e0c92fb-e626-41bd-9b17-c14ad6786110', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is ''autowiring'' considered a double-edged sword in large-scale enterprise applications?', N'Senior', N'Autowiring significantly reduces configuration boilerplate by automatically injecting dependencies based on type-hints. However, in very large systems, it can lead to ''magic'' dependency resolution that is difficult to debug and may cause performance degradation during container compilation if the graph becomes too complex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61b3e851-013f-4134-b09b-c14b4ddbf427', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different methods to find HTML elements in DOM', N'Intern', N'If you want to access any element in an HTML page, you need to start with accessing the document object. Later you can use any of the below methods to find the HTML element, 1. document.getElementById(id): It finds an element by Id 2. document.getElementsByTagName(name): It finds an element by tag name (returns an node list) 3. document.getElementsByClassName(name): It finds an element by class name (returns an node list) 4. document.querySelector(cssSelector): It finds an element by css selector 5. document.querySelectorAll(cssSelector): It finds all elements by css selector (returns a node list)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20f129b7-af2a-42b3-9712-c14cf520f65d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'When is it appropriate to use the ''at-root'' directive in Sass?', N'Senior', N'The @at-root directive is useful when you want to break out of a nested selector structure to place a style rule at the top level of the stylesheet. It is commonly used in BEM methodology to handle block-level styling while maintaining the visual hierarchy of the Sass code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5129b365-1250-4954-a5a5-c14da5e7ce36', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the benefit of an asynchronous API pattern using webhooks or message queues?', N'Senior', N'Asynchronous patterns allow the server to offload long-running tasks, improving responsiveness and system throughput. This approach decouples the producer and consumer, enabling better scalability and reliability, provided the client is prepared to handle non-immediate state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'230014f0-bb99-4e15-b9d5-c14e8935731b', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are HTML entities?', N'Intern', N'HTML entities are codes used to display reserved characters or symbols that might otherwise be misinterpreted as HTML code by the browser. For example, using an entity is necessary to display characters like the less-than sign or the ampersand correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a886680f-195a-446d-b8b8-c14f9de0c3cd', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''extern'' keyword do?', N'Fresher', N'The ''extern'' keyword is used to declare a variable or function that is defined in another source file. It tells the compiler that the identifier exists elsewhere, preventing duplicate definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92fbea91-53f8-41c0-815c-c14fd0168556', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of Middleware in ASP.NET Core, and how does it function within the application pipeline?', N'Junior', N'Middleware consists of software components assembled into an application pipeline to handle requests and responses. Each component chooses whether to pass the request to the next component in the pipeline and can perform work both before and after the next component is invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c480a9e7-3ae8-4b1c-b0fd-c152fb5d4e8c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary benefit of the ''preact-render-to-string'' package?', N'Middle', N'This package is essential for server-side rendering, as it converts the virtual DOM tree into a static HTML string. It is highly optimized to run on Node.js, enabling faster initial page loads and better SEO by serving pre-rendered content to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6dd8ef-d822-420e-9abd-c156ea47c940', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How MongoDB supports ACID transactions and locking functionalities?', N'Fresher', N'ACID stands that any update is: * Atomic: it either fully completes or it does not * Consistent: no reader will see a "partially applied" update * Isolated: no reader will see a "dirty" read * Durable: (with the appropriate write concern) MongoDB, has always supported ACID transactions in a single document and, when leveraging the document model appropriately, many applications don''t need ACID guarantees across multiple documents. MongoDB is a document based NoSQL database with a flexible schema. Transactions are not operations that should be executed for every write operation since they incur a greater performance cost over a single document writes. With a document based structure and denormalized data model, there will be a minimized need for transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a850ffc-0acc-4e29-8296-c1585fb0244d', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the distinction between S3 and S4 object systems in R?', N'Senior', N'S3 is a lightweight, informal system based on generic functions and naming conventions, prioritizing flexibility and ease of use. S4 is a formal system featuring strict class definitions, multiple inheritance, and complex method dispatch, providing stronger encapsulation and compile-time-like validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a731e56a-6f6b-4225-bdf1-c15dd6be8b58', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are some key differences to bear in mind when coding in Python vs. Java?', N'Intern', N'Disclaimer #1. The differences between Java and Python are numerous and would likely be a topic worthy of its own (lengthy) post. Below is just a brief sampling of some key differences between the two languages. Disclaimer #2. The intent here is not to launch into a religious battle over the merits of Python vs. Java (as much fun as that might be!). Rather, the question is really just geared at seeing how well the developer understands some practical differences between the two languages. The list below therefore deliberately avoids discussing the arguable advantages of Python over Java from a programming productivity perspective. - With the above two disclaimers in mind, here is a sampling of some key differences to bear in mind when coding in Python vs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dbf613ce-94cf-49d7-850e-c15f7438fd2f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is an Outlet in Ember?', N'Fresher', N'An outlet is a placeholder in a template where the router renders nested content. It allows for hierarchical routing, where a parent template remains visible while the content inside the outlet changes based on the child route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b75dec17-7631-4320-8d56-c1638497595b', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if you do not define a loader for a specific file type?', N'Junior', N'If Webpack encounters a file type it does not know how to handle, it will throw a build error. Webpack assumes by default that all files are JavaScript modules, so non-JS files must be explicitly handled by a loader.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
