INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac681123-b438-4c01-b684-c1679f97fe5d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is a ''callback hell'' and how can it be avoided?', N'Junior', N'Callback hell occurs when multiple nested asynchronous operations lead to deeply indented and unreadable code. It is avoided by using Promises, async-await syntax, or by modularizing code into smaller named functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
