INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9aebe1d-a2ab-4de8-bf9e-c167fb7cdffc', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS optimize memory usage for large database result sets?', N'Senior', N'For large datasets, AdonisJS provides cursor-based iteration and pagination strategies that avoid fetching all records into memory at once. By using streaming or chunking, the application can process thousands of rows while maintaining a stable, low memory footprint, essential for batch processing or report generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a71ada7-5284-429b-8e87-c16819b4086a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the jQuery noConflict() method?', N'Intern', N'The noConflict() method releases control of the dollar sign ($) variable, which is useful if another library is also using the dollar sign. It allows jQuery to coexist with other JavaScript libraries on the same page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c448f05-125e-486f-a441-c16a0a2cf187', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the significance of the ''IntoResponse'' trait when returning values from handlers.', N'Senior', N'IntoResponse is a conversion trait that ensures any type returned by a handler can be transformed into a valid HTTP response. This design allows for type-safe, ergonomic error handling and custom content-type rendering without requiring manual response construction in every handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3f97931-588d-4488-9777-c1710f26307f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go support concurrency?', N'Fresher', N'Go supports concurrency through the use of goroutines and channels. This model, based on Communicating Sequential Processes, allows developers to write efficient concurrent programs without complex locking mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80a49472-1676-4a75-8ede-c174e1ed5af7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle cross-origin resource sharing (CORS)?', N'Middle', N'CORS is typically handled in Rocket by implementing a Fairing that inspects incoming OPTIONS requests and adds the necessary headers to responses. This allows you to centralize CORS policy management rather than repeating header logic in every single handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c02a29f1-a77c-4bc9-961b-c175d125bdd9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the effort for a project that involves integrating with a legacy system with no documentation?', N'Middle', N'I add a ''discovery phase'' to the project estimate where I spend time reverse-engineering the system, creating documentation, and writing tests. By making the unknown known before committing to the full project timeline, I significantly reduce the risk of late-stage surprises.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63b24c1e-5f03-4efc-acf9-c176ba5d37f5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the impact of Kotlin''s ''Multiplatform'' architecture on the build system and binary size?', N'Senior', N'Multiplatform requires a hierarchical build structure that manages separate compilations for each target platform (JVM, Native, JS), leading to increased build complexity and potentially larger binaries due to duplicated logic or bridge code. It enables shared business logic across platforms but requires strict separation of platform-specific APIs to maintain portability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e716e4b6-e02b-4f89-a820-c176dd3b48aa', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does horizontal scaling of the application impact an in-memory local cache?', N'Middle', N'Horizontal scaling creates multiple independent instances of the application, each with its own local cache, leading to data fragmentation and inconsistency across instances. This requires developers to either accept eventual consistency or switch to a centralized distributed cache to ensure all instances see the same data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'871aa1ea-8921-48b0-b8b5-c177c331fe1b', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you verify your understanding of a requirement before providing an estimate?', N'Junior', N'I ask clarifying questions and summarize the requirement back to the stakeholder in my own words to ensure we are aligned. I also look for potential edge cases or scenarios that were not explicitly mentioned to ensure my mental model is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3cab348-517f-4c3c-bf77-c177fb9c0b13', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Can NoSQL databases handle relationships between data?', N'Fresher', N'Yes, NoSQL databases can handle relationships, but they do not use formal foreign keys or complex joins like relational databases. Relationships are typically managed through embedding documents or using references to other data records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'707141dd-48b5-4cdb-ae93-c1781a424587', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is meant by the term ''declarative'' in the context of Alpine.js?', N'Intern', N'Declarative means that you describe what the UI should do or look like directly in your HTML tags, rather than writing imperative JavaScript code to manually select elements and update their properties. You define the behavior as an attribute, and Alpine handles the underlying logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a601ea6a-cd35-4bc4-b1bf-c17b6223bea8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What should you consider before choosing an external library or dependency for your project?', N'Junior', N'Evaluate the library''s maintenance activity, community support, documentation, and security record. Adding a dependency introduces long-term maintenance costs, potential security vulnerabilities, and potential bloat, so it should be avoided if the feature can be easily implemented with standard tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7690b68-fc20-4fe1-a5b5-c17d52ec40eb', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the primary benefit of master-slave replication?', N'Middle', N'The primary benefit is the ability to scale read-heavy workloads by directing traffic to multiple slaves while keeping the master dedicated to write operations. It also provides a basic form of fault tolerance, as a slave can be promoted to master if the original fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9297896-e32a-420b-9e61-c17dd5456a74', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails determine the database connection to use when multiple databases are configured?', N'Middle', N'Rails uses the ''connects_to'' method in the application record to define multiple database clusters. It automatically switches connections based on the defined roles, such as primary and replica, or by using the ''connected_to'' block to explicitly route specific queries to the appropriate database during the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'798c3a09-037b-4649-a06a-c17fa34cc65d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are Spring Profiles and when should you use them?', N'Middle', N'Profiles allow developers to segregate parts of the application configuration and make it available only in certain environments. You use them to maintain different settings for development, testing, and production, such as different database URLs or third-party service credentials.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'375439f8-446a-4b50-926a-c17fd912c840', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik require a specific build process?', N'Junior', N'Yes, Qwik uses a sophisticated build process that performs code splitting at the function level. This allows the framework to transform the application into many small, individual files that can be fetched independently by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36ff73d3-faf5-498c-8cb1-c1802aebc42e', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between ''req.send()'' and ''req.json()''?', N'Fresher', N'res.send() can take various types of input, such as a buffer, string, or object, and sets the content type automatically based on the input. res.json() explicitly sends a JSON-formatted response and always ensures the correct JSON headers are set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c60fd3b9-ec51-4955-99e4-c1814dfb3f44', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Discuss the internal mechanism of Scala macros and why they are considered a ''black box'' for IDE support.', N'Senior', N'Macros function by providing the compiler with code that transforms the Abstract Syntax Tree during the compilation phase. They are difficult for IDEs because the IDE must invoke the compiler''s own macro-expansion logic to understand the resulting code structure. Since macros can perform arbitrary computations during expansion, they break traditional static analysis workflows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c3c1859-b7a9-422b-ad82-c18279ae7a4e', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the difference between strong and weak exception guarantees.', N'Senior', N'A strong exception guarantee ensures that if an operation fails, the state of the program remains as it was before the operation began, typically achieved via rollback mechanisms. A weak guarantee ensures that no resources are leaked, but the state of the objects involved might be left in a valid but unspecified state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999338c9-126d-4ac9-8493-c18aeba64c46', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Schematics CLI?', N'Intern', N'Schematics come with their own command-line tool known as Schematics CLI. It is used to install the schematics executable, which you can use to create a new schematics collection with an initial named schematic. The collection folder is a workspace for schematics. You can also use the schematics command to add a new schematic to an existing collection, or extend an existing schematic. You can install Schematic CLI globally as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12da1d3e-d9d4-477b-9486-c18b918e5572', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why would you use ''Tracked'' properties in Ember?', N'Junior', N'Tracked properties are used to tell Ember that a specific value should be monitored for changes. When a tracked property is updated, Ember automatically triggers a re-render of any UI elements that depend on it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8a51f7d-17f7-4485-8aeb-c18c80ea90cc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web''s ''State'' extractor differ from global mutable state in terms of concurrency?', N'Senior', N'Actix-web''s State is typically shared as an Arc, which provides safe, read-only access or interior mutability via synchronization primitives across threads. Global mutable state without proper locking or atomic operations would lead to data races and undefined behavior in a multi-threaded asynchronous environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ebc85da-2ccb-48b5-8e47-c18d1260bf6c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle exception handling?', N'Fresher', N'Ruby uses a ''begin'', ''rescue'', ''ensure'', and ''end'' block structure to handle exceptions. Code that might raise an error is placed in ''begin'', potential errors are caught in ''rescue'', and ''ensure'' defines code that will run regardless of whether an error occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd74fedef-8cb8-4679-b29b-c1922055454f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does the Express routing pattern matching order impact application performance and security?', N'Senior', N'Express evaluates routes in the order they are defined. Placing highly specific or frequently accessed routes at the top reduces the number of regex evaluations needed for matching, while improper ordering can cause requests to be erroneously intercepted by catch-all or broader wildcard routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd81a73b1-bcfa-4191-8deb-c19481787498', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You are tasked with choosing between a relational database and a NoSQL database for a new application. How do you decide which one to use?', N'Fresher', N'I would evaluate the structure of the data and the required consistency. If the data is highly structured with predefined schemas and requires complex relationships or ACID compliance, a relational database is the best choice. If the data is unstructured, rapidly evolving, or requires horizontal scaling for high-velocity ingestion, a NoSQL database would be more appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4264eb0-18be-48bc-835a-c195ed817918', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Router component resolve a URL?', N'Middle', N'The Router matches the incoming URL against a collection of defined route patterns to identify the corresponding controller and action. It also extracts dynamic parameters from the URL, which are passed to the controller for further processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6433a8b6-6445-44f9-86a4-c196c20168de', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''readonly'' modifier used for?', N'Junior', N'The ''readonly'' modifier prevents a property from being reassigned after it is initialized. This is useful for creating immutable data structures and ensuring object state remains consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0738b8ec-ec2c-4392-bc31-c198068301b7', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do you handle database migration in a system with zero-downtime requirements?', N'Middle', N'Zero-downtime migrations typically use a multi-phase approach where the schema is updated in a backwards-compatible way. Applications are updated to support both old and new schema versions before a final cleanup phase removes the deprecated columns or tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f167b597-7609-40d5-a8ae-c198e2fe1f1f', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do you handle the trade-offs between SEO and client-side rendering with HTML templates?', N'Senior', N'Client-side rendering requires an initial empty shell, which can be detrimental to SEO if the crawler does not execute JavaScript. Using server-side rendering or static site generation ensures the crawler receives full HTML, providing a better baseline for indexing and performance metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8645a3a3-9c80-485a-a844-c1990327d15e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the advantage of Micronaut''s ahead-of-time (AOT) compilation?', N'Fresher', N'AOT compilation ensures that much of the framework''s metadata is generated during the build process. This reduces the work the application has to do when it starts, leading to lower CPU usage and faster readiness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99aa4ec3-c5b4-4645-90c8-c19a207c21b0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the architectural shift from ''DOM as the state'' to ''State-driven UI'' and why jQuery fails here.', N'Senior', N'jQuery treats the DOM as the primary source of truth, meaning any UI state must be manually synced back from the DOM. Modern architecture treats state as the source of truth, where the UI is a pure function of that state, making jQuery''s imperative approach fundamentally incompatible with reactive design patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd32eb2fe-a28d-4c0d-b518-c19a749ba6f7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Why should you never mutate the state directly in Redux?', N'Fresher', N'Direct mutation prevents Redux from detecting changes, which means UI components may not re-render correctly. Redux relies on returning a new object reference to trigger updates, which is why immutability is strictly required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c69218e-956a-49ca-a33d-c19c4278d4d0', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis considered faster than traditional relational databases?', N'Intern', N'Redis is faster because it operates primarily in-memory rather than reading from or writing to a physical disk. Because RAM access is significantly faster than disk access, Redis can perform operations in sub-millisecond time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'250e1ecb-da1f-48f5-92b8-c1a2f6d4374f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of the ''never'' type?', N'Middle', N'The ''never'' type represents values that will never occur, such as a function that always throws an error or an infinite loop. It is useful for exhaustive checking in switch statements, ensuring that all possible cases in a union type have been handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'098aaea2-f815-42c5-a7bd-c1a69605e700', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the ''super'' keyword used for?', N'Fresher', N'The ''super'' keyword is used within a method to call the version of that method defined in the parent class. It allows a subclass to extend the functionality of a superclass method rather than completely replacing it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87c10904-255a-4fb5-b3d5-c1a6d707c34e', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you evaluate the trade-offs between choosing an Event-Driven Architecture versus a Request-Response model for microservices?', N'Senior', N'Event-driven architectures decouple services and improve scalability by allowing asynchronous processing, but they introduce complexity in data consistency and distributed tracing. Request-response models are easier to reason about and debug but can lead to tight coupling and cascading failures if not properly implemented with circuit breakers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6537364e-a2f4-47bb-a87b-c1a8cfe4e4ed', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Compare the use of ''Health Checks'' versus ''Readiness Probes'' in Kubernetes.', N'Senior', N'Health checks (liveness) determine if a container needs to be restarted to resolve a deadlocked state. Readiness probes determine if a container is prepared to accept traffic, preventing load balancers from routing requests to services that are still initializing or undergoing heavy background processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68eae1e8-7406-49ac-9639-c1a9bf18db63', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you architect for secure inter-service communication in an untrusted network?', N'Senior', N'The standard approach is enforcing mTLS for all traffic, which ensures both encryption in transit and mutual authentication between services. This prevents man-in-the-middle attacks and ensures that only authorized services can communicate with one another within the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ea4c92-4c98-4d3f-81f7-c1aa5c3c9f49', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a ''context'' in the context of a Chi request?', N'Junior', N'The context in Chi is the standard Go context associated with the incoming HTTP request. It carries request-scoped values, such as URL path parameters, which are populated by the router during the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34d750b0-fcfd-427d-bb1b-c1aec341d8c5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the impact of database sharding on transactional integrity.', N'Senior', N'Sharding distributes data across multiple nodes, which makes cross-shard transactions significantly more complex and expensive. Systems must use distributed commit protocols like two-phase commit to ensure atomicity, which introduces latency and potential availability risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dee7adb1-c5a4-4e4a-a13f-c1b1abc999b9', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of CSS variables (custom properties) and why are they useful in large applications?', N'Middle', N'CSS variables allow developers to store reusable values like colors, spacing, or font sizes in a central location. They are highly beneficial in large applications because they can be updated dynamically at runtime via JavaScript and provide a single source of truth, making theme management and maintenance much easier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8738bfe-0b70-40e5-8036-c1b28bfda7c8', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the impact of using ''box-sizing: border-box'' on architectural consistency in complex UI systems?', N'Senior', N'Border-box forces the inclusion of padding and borders within the defined width and height of an element, preventing the ''box model overflow'' common with default content-box sizing. This makes layout calculations more intuitive and less prone to breaking when padding or borders are added to components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f58a6c43-2a98-4f7f-b7e2-c1b36128ab05', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the architectural implications of the V8 engine''s TurboFan compiler pipeline.', N'Senior', N'TurboFan is a highly optimizing JIT compiler that uses sea-of-nodes IR to perform complex optimizations like escape analysis and speculative speculation. It trades off initial compilation latency for superior runtime performance by making assumptions about types that can be deoptimized if violated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0affe9d4-43c5-4832-b528-c1b5ac7be27d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi''s performance profile stable under high load?', N'Senior', N'Chi’s stability under load stems from its low-allocation routing algorithm and the absence of complex reflection-based processing. By leveraging standard interfaces and avoiding unnecessary layers, it keeps CPU and memory usage predictable as request volume scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f835b56-26db-4422-8d26-c1b6f6b5d7f9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are Actix ''Workers''?', N'Junior', N'Workers are independent threads spawned by the Actix HTTP server to handle incoming requests in parallel. The number of workers is typically configured based on the number of available CPU cores to maximize performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd454cf01-a3a7-4578-b913-c1b843c88f30', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Explain the difference between a functional bug and a performance issue.', N'Junior', N'A functional bug means a feature is not working as expected, such as a button failing to trigger an action or incorrect data being displayed. A performance issue means the feature works correctly, but it is slow or resource-heavy, causing a poor experience for the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62fd7870-e825-4c0d-ad27-c1ba3909beec', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a ''Mailbox'' in Actix?', N'Junior', N'A mailbox is a queue that stores incoming messages for an actor. When a message is sent to an actor, it is placed in this queue and processed sequentially by the actor''s event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01de102a-1208-475a-a08f-c1baa6796ae9', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between ''atomic'' and ''non-atomic'' requests in the context of database transactions?', N'Middle', N'By default, Django commits every individual statement to the database immediately. Using ''atomic'' wraps a block of code in a single transaction, ensuring that if any part fails, the entire set of changes is rolled back to maintain a consistent database state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38dce4c8-0b74-4185-a519-c1bed9d9bab0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the @warn directive?', N'Intern', N'The @warn directive prints a warning message to the terminal while compiling without stopping the process. It is useful for alerting other developers about deprecated features or potential issues in the stylesheet code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1d1583b-08ca-41fe-9c7c-c1c0a6a53740', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the difference between ''next/image'' and the standard HTML ''img'' tag?', N'Fresher', N'The ''next/image'' component provides automatic optimization, such as lazy loading and responsive sizing, which the standard ''img'' tag does not offer. Using it helps prevent layout shifts and ensures images are served in efficient formats.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6798814-5e19-44c0-97f9-c1c3eb935aa9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the Python garbage collector handle circular references?', N'Middle', N'Python primarily uses reference counting for memory management, which fails when objects reference each other in a cycle. The cyclic garbage collector periodically traverses object graphs to identify unreachable groups of objects that reference each other and deallocates them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3c7d853-b8f0-4f94-8319-c1c4c7254426', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is Isolation in a database transaction?', N'Intern', N'Isolation ensures that concurrent transactions do not interfere with each other. It makes it appear as if transactions are occurring sequentially, even when they are running at the same time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9ed585f-be3e-4679-a56a-c1c5a90005d1', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What does it mean for Litestar to be an ASGI framework?', N'Fresher', N'Being an ASGI (Asynchronous Server Gateway Interface) framework means Litestar is designed to handle asynchronous requests and responses natively. This allows it to handle many concurrent connections efficiently by not blocking the execution thread while waiting for I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7c87ff4-5cbd-4637-b1a5-c1c611904e8a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle process signals and graceful shutdowns in a containerized environment?', N'Senior', N'Node.js processes should listen for SIGTERM signals to initiate a graceful shutdown, which includes stopping new request acceptance and closing existing database connections. In Kubernetes, this ensures the pod terminates cleanly without dropping inflight requests. Failing to handle these signals can lead to data inconsistency or connection errors during rolling updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5644bea8-a706-44c7-9548-c1ca80108d83', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a Guard and Middleware?', N'Intern', N'Middleware is unaware of which handler will be executed next, while guards have access to the execution context. This allows guards to perform complex logic like checking user roles for specific routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9aaf126d-1b8b-43cd-8509-c1cc69b29b09', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the difference between Quarkus ''Imperative'' and ''Reactive'' programming models.', N'Senior', N'The imperative model uses traditional blocking I/O and standard servlet-style processing, which is easier to debug but consumes more resources under high load. The reactive model uses non-blocking I/O and asynchronous streams, offering higher concurrency and efficiency at the cost of increased code complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5297788f-e62e-407a-8325-c1ce25e588cc', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between using a pre-built library versus building a custom solution?', N'Fresher', N'You analyze the requirements against the cost of maintenance and the degree of control needed. Using a library saves time and leverages community testing, while a custom solution offers a perfect fit for unique constraints but requires long-term effort to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61ebfbb1-41cd-4759-bc89-c1cf1c38a545', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ attributes (e.g., [[likely]], [[nodiscard]]) influence code generation?', N'Senior', N'Attributes provide hints to the compiler to assist with optimization or static analysis. For instance, [[likely]] informs the branch predictor to optimize for a specific path, while [[nodiscard]] forces the compiler to issue a warning if a function return value is ignored, helping prevent bugs at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91720b13-5b7a-4d1f-ba82-c1cfbbe0be3e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the difference between ''let'', ''const'', and ''var'' regarding hoisting and scoping.', N'Middle', N'Var is function-scoped and hoisted with an undefined initial value, leading to potential bugs. Let and const are block-scoped and exist in the temporal dead zone until declared, which ensures safer variable usage and prevents unintentional reassignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d88e9b0-dfb0-4f4a-b1f2-c1d50b1d68cb', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS manage scoped providers, and what is the performance impact of REQUEST-scoped dependencies?', N'Senior', N'REQUEST-scoped providers are instantiated per incoming request, meaning the DI container must create a new tree of dependencies for every request. This introduces significant memory and CPU overhead compared to SINGLETON-scoped providers, which are instantiated only once, and can degrade performance under high-concurrency workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f5b1018-8b4a-4b4b-85ae-c1da5ec378ca', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What does it mean that Hono is ''ultrafast''?', N'Intern', N'Hono is optimized for performance by using a highly efficient routing algorithm and keeping its internal dependency tree extremely small. This results in low overhead during the request-response cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f6912a5-29ab-4591-9d33-c1daa6b35d5d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the application controller?', N'Junior', N'The application controller is the base class from which all other controllers inherit. It is the ideal place to define logic that should apply to all controllers, such as authentication checks or setting up global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00889464-2b41-494d-92d9-c1db832ff299', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the ''Buy vs. Build'' decision for a critical system component?', N'Middle', N'I weigh the cost of licensing and integration against the long-term cost of development and maintenance. If the component is a core differentiator for the business, building is often better; if it is a commodity service, buying or using an open-source solution usually provides better efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b3c4e66-c412-4383-9c12-c1dc2ea05eae', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are Guards in Litestar?', N'Intern', N'Guards are functions used to restrict access to route handlers. They run before the handler is executed and typically perform checks like verifying user permissions or authentication status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
