INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'556f12b4-fe12-4ef1-89e9-c1e154d8abf7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the difference between vertical and horizontal scaling in the context of NoSQL.', N'Senior', N'Vertical scaling involves increasing the resources of a single node, which eventually hits a cost-effective ceiling. Horizontal scaling, the foundation of NoSQL, involves adding more commodity nodes to the cluster, allowing the workload to be distributed across the entire infrastructure for virtually linear performance growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9077ab5d-0525-49af-82d8-c1e6fb867566', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''Majority'' read concern affect data consistency?', N'Middle', N'The ''majority'' read concern ensures that the data returned by a query has been acknowledged by a majority of the replica set members. This protects against ''dirty reads'' where data is read from a node that might be rolled back after a primary failover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c031ebb4-6d9e-4314-b778-c1e858a04196', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the primary purpose of Alpine.js in a web project?', N'Fresher', N'Alpine.js is a lightweight, minimal framework used to add reactive and declarative behavior directly to HTML markup. It is designed to provide the functionality of heavy frameworks like Vue or React without the need for a complex build step or large bundle sizes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65f470ef-9dc2-430e-886b-c1f3276d8d38', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the Gin router?', N'Fresher', N'The router is responsible for mapping incoming HTTP requests (defined by a method and a path) to specific handler functions. It enables developers to organize endpoints logically and supports grouped routes for better maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93eeb641-b605-419a-9a0d-c1f3c5c77833', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ memory models interact with hardware-level cache coherency protocols?', N'Senior', N'The C++ memory model defines the behavior of multithreaded programs by establishing rules for visibility and ordering of memory operations. It abstracts hardware-specific cache coherency protocols by requiring compilers and CPUs to insert memory barriers or fences, ensuring that atomic operations and synchronization primitives behave predictably across different processor architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ba38448-7eac-4871-8990-c1f82218f62e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the benefit of using the ''components'' directory in Nuxt?', N'Junior', N'Components placed in the components directory are automatically imported by Nuxt. This means you do not need to manually write import statements in your files, which reduces boilerplate code and improves developer experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3485cca-39d4-4f32-862e-c1fa43367636', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar ensure type safety in route parameters?', N'Senior', N'Litestar uses type hints on handler arguments to automatically parse and validate path, query, and header parameters. By using standard Python types, the framework ensures that incoming data conforms to the expected structure before it ever reaches the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d06eeaa-76ff-4ccf-a66e-c1facf86a93b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How do you handle state persistence in Hono when the framework itself is designed to be stateless?', N'Senior', N'Since Hono is stateless, state persistence must be delegated to external systems like Redis, DynamoDB, or distributed caches via middleware. The framework is designed to facilitate this by allowing easy integration of these stores into the context object, ensuring that the stateless nature of the application server is maintained while session or request data remains available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32398142-0f58-42cd-9892-c1faeec897e7', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'In what scenario would you choose a point-to-point queue over a publish/subscribe topic?', N'Senior', N'A point-to-point queue is appropriate for task distribution where exactly one consumer should handle each job. Pub/Sub is required when a single event triggers multiple distinct business processes, necessitating the broadcast of the event to multiple subscribers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e67da28-8d73-4d5a-8660-c1fb8e06f72e', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the trade-offs of using HTML Imports versus ES Modules for component-based architecture?', N'Senior', N'HTML Imports were deprecated due to performance issues and lack of standardized scoping, whereas ES Modules provide native dependency management and tree-shaking capabilities. ES Modules are now the industry standard, offering better integration with modern bundlers and more predictable execution order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76ff7673-7b53-49a7-875f-c1fd18899774', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''rel=preconnect'' resource hint improve performance?', N'Middle', N'Preconnect allows the browser to establish a connection to a third-party domain—including DNS lookup, TCP handshake, and TLS negotiation—before an actual request is made. This reduces latency when fetching resources like fonts or APIs from external origins. It is most effective when you know for certain that a resource will be needed shortly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'639d24df-8ad0-42ba-b402-c1fdbd11cfd7', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot''s Auto-Configuration leverage the ConditionEvaluator, and what is its impact on startup performance?', N'Senior', N'Auto-configuration uses conditional annotations like @ConditionalOnClass to dynamically register beans based on the classpath. While it simplifies setup, a massive classpath can increase startup time due to the iterative evaluation of these conditions, which is why optimizing dependency management is critical in large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3199549c-d761-4c47-ae34-c2013904802b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is a handler in the context of Echo?', N'Fresher', N'A handler is a function that processes an HTTP request and returns a response. In Echo, handlers must follow a specific signature that accepts the Echo context as an argument and returns an error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'620b1b1f-1be8-4aed-9b7a-c201408058f4', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it often recommended to avoid ''magic numbers'' in Tailwind?', N'Junior', N'Magic numbers are hardcoded, arbitrary values that don''t align with your design system. Using them makes your project harder to maintain and breaks the consistency that Tailwind is designed to enforce.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd6ff0c0-95e9-4e63-978b-c201a2f5f145', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a ''before_action'' and a ''before_save'' callback?', N'Junior', N'A ''before_action'' is a controller callback that executes code before a specific controller action, often used for authentication or loading resources. A ''before_save'' is an Active Record model callback that executes code just before a database record is persisted to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33b6262b-b858-4d5e-a2b0-c2054fcdfd55', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s approach to error handling differ from traditional exception-based models?', N'Middle', N'Rust uses explicit return types like Result and Option, forcing developers to acknowledge and handle failure states at the call site. Unlike exceptions, which can propagate implicitly through the call stack, Rust’s model makes error paths visible in the function signature, resulting in more predictable and robust control flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0539c4d3-1d13-44ab-baec-c2084fe95a62', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you manage frustration when a difficult bug persists?', N'Fresher', N'I take a step back and shift my focus to a different task for a short period to gain a fresh perspective. Returning to the problem with a clear mind often helps me spot details I missed while I was focused on a single, unproductive path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee3589a6-52f8-4cf8-97a4-c2096fed64f5', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How you implement Server Side Rendering or SSR?', N'Fresher', N'React is already equipped to handle rendering on Node servers. A special version of the DOM renderer is available, which follows the same pattern as on the client side. This method will output the regular HTML as a string, which can be then placed inside a page body as part of the server response. On the client side, React detects the pre-rendered content and seamlessly picks up where it left off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f6a332-d001-4396-9e04-c20a6be91bd9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is GraalVM and why is it important for Quarkus?', N'Intern', N'GraalVM is a high-performance JDK that supports compiling Java code into native executables. It allows Quarkus applications to start almost instantly and use significantly less memory compared to running on a standard JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'685280fd-a1e0-46a6-bfad-c20c61484435', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between an argument and a parameter?', N'Intern', N'A parameter is a variable listed in the function definition, while an argument is the actual value that is passed to the function when it is called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ecc5b59-c021-4dd7-9cdd-c20d3b362bb7', N'4c000000-0000-0000-0000-000000000005', N'How does the ''Circuit Breaker'' pattern improve system resilience?', N'Senior', N'A circuit breaker monitors for recurring failures in a remote service and ''trips'' to prevent further requests, giving the struggling service time to recover. This prevents cascading failures across the system and allows the caller to return a default or cached response instead of hanging indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f6a9eb-dcb2-418d-9f9f-c2118fe3cddd', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is meant by ''design tokens'' in Tailwind?', N'Fresher', N'Design tokens are the underlying values like colors, spacing scales, and font sizes that make up your design system. In Tailwind, these tokens are defined in the configuration file, ensuring consistent design choices across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efa4c7b3-cb8b-4381-86aa-c212a32e8e1f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket utilize Rust''s type system to enforce request safety?', N'Middle', N'Rocket uses type-safe request guards to ensure that only requests meeting specific criteria reach the handler. If a guard fails, Rocket automatically returns a 400 Bad Request or 404 Not Found error, preventing invalid data from ever executing your business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd19b66c8-bf41-4d31-b330-c213eb488278', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What happens to TypeScript code when it is compiled?', N'Junior', N'TypeScript code undergoes a process called transpilation, where the TypeScript compiler converts it into plain JavaScript. During this process, all type annotations are removed, resulting in code that can run in any browser or JavaScript environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c90d8a67-c16e-4952-afe9-c218cf49b29e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the concept of ''Context Receivers'' and their role in dependency injection patterns.', N'Senior', N'Context receivers allow functions to declare dependencies on specific types within their scope without passing them as explicit parameters. This provides a type-safe and modular way to handle environmental dependencies, effectively acting as a lightweight, compile-time alternative to heavy reflection-based dependency injection frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd41048a-fbd9-4cac-81b8-c21bd4908298', N'4c000000-0000-0000-0000-000000000005', N'What are the architectural implications of using Event Sourcing compared to traditional CRUD?', N'Senior', N'Event Sourcing captures all state changes as a sequence of immutable events, providing a perfect audit log and the ability to reconstruct state at any point in time. However, it introduces significant complexity in handling event schema evolution and requires CQRS to efficiently query the current state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b084836c-b79f-47d9-b028-c21d8bc99625', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the ''fillfactor'' parameter in table and index storage?', N'Senior', N'The fillfactor determines how much of a data page is filled before PostgreSQL leaves free space for future updates. A lower fillfactor reduces the likelihood of page splits and promotes HOT updates, but it increases the overall size of the table on disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed41b0ff-3df3-48e3-a7ef-c21fcd22e8c4', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you handle schema evolution for a service that uses a non-relational database?', N'Senior', N'I would implement a versioning strategy for the data records and utilize an application-level adapter layer to handle transformations between old and new schema versions during reads. This allows for ''lazy'' migration where records are updated to the current schema only when accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'198cd5f3-f5d8-4304-8882-c220e7f8604d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between shadowing and mutability?', N'Junior', N'Shadowing allows you to declare a new variable with the same name as a previous one, effectively hiding the old value. Mutability allows you to change the value of an existing variable without changing its type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baff87f4-25be-4890-9c65-c223c05a9e60', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How to Search Path of Modules?', N'Fresher', N'By default python interpreter search for the imported modules in the following locations: - Current directory (main module location) - Environment variable path - Installation dependent directory - If the imported module is not found in the any one of the above locations. Then python interpreter giveserror. - Built-in attributes of a module: - By default for each and every python module some properties are added internally and we call thoseproperties as a built-in-attribute of a module', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efd358d5-740d-4220-bd75-c224ccd7165d', N'954a0331-deff-4399-b588-96f39fec001d', N'What is type narrowing?', N'Intern', N'The expression used in an ngIf directive is used to narrow type unions in the Angular template compiler similar to if expression in typescript. So *ngIf allows the typeScript compiler to infer that the data used in the binding expression will never be undefined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5b07a02-0fb0-4ad9-a6fa-c2250d52ba01', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the acronym ACID stand for in the context of transactions?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These are the four key properties that guarantee that database transactions are processed reliably.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'740b32b6-b91f-4162-891b-c22664018353', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the risk of relying solely on historical data for future estimations?', N'Intern', N'Historical data may not account for changes in technology, team composition, or project complexity that could make past performance irrelevant. While it provides a useful baseline, relying on it blindly ignores the unique variables of the current project that could lead to different outcomes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecd55366-e7e7-4633-b093-c226d679e44c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix''s approach to code-splitting differ from traditional bundler-based configuration?', N'Senior', N'Remix automatically handles code splitting based on the route structure without requiring manual configuration or dynamic imports. By analyzing the dependency tree, it ensures that only the code required for the current route is sent to the client, optimizing performance by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a57cb785-e41a-4982-86fd-c2286434c7c5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is there a trade-off between adding more features to a product and its overall stability?', N'Junior', N'Every new feature increases the complexity of the codebase and the number of potential interaction points where bugs can occur. To maintain stability while adding features, you must invest proportional time in testing and quality assurance, which slows down the feature delivery rate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
