INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'380bed4b-58e1-4dab-a502-c22c3da2fee8', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix''s ''Endpoint'' module act as the entry point for all incoming requests?', N'Senior', N'The Endpoint is the centralized pipeline through which all requests must pass, including static assets, instrumentation, and core Plug middleware. It acts as the final gatekeeper, setting the stage for request routing and providing global configuration for security headers and logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa921629-e826-4e8f-9612-c22f49834fa3', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js optimize script loading?', N'Middle', N'The next/script component allows developers to manage the loading priority of third-party scripts. By choosing strategies like ''lazyOnload'' or ''afterInteractive'', you can prevent external scripts from blocking the main thread and impacting vital performance metrics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3198770c-d41c-438c-984b-c22f5411caf7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does a component ''subscribe'' to the Redux store?', N'Fresher', N'Components subscribe to the store to be notified whenever the state changes. In React, this is typically handled by libraries like React-Redux, which automatically re-renders components when the relevant slice of state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d380b7e-b7c7-46ee-ad47-c22fb96109f4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How can you implement multiple inheritance-like behavior in Ruby?', N'Middle', N'Ruby does not support multiple inheritance for classes, but it achieves similar results through ''mixins'' using modules. By including multiple modules, a class can aggregate behaviors from different sources without the complexities of a diamond inheritance structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42c02ce3-2ad5-42e7-9309-c230802593df', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the advantage of using ''x-bind'' over standard HTML attributes?', N'Middle', N'x-bind allows you to dynamically set attributes based on your reactive state. Standard HTML attributes are static, whereas x-bind enables the UI to respond to user interactions, such as toggling a disabled state, changing a class name, or updating an aria-label in real-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27875210-4239-4263-bfe1-c23196e57484', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the architectural implications of TypeScript''s type erasure during the compilation process.', N'Senior', N'Type erasure means that all type information is stripped away during transpilation, resulting in zero runtime type overhead. Consequently, runtime features like reflection or type-based conditional logic are impossible without external metadata or manual implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16c91680-98e6-4b24-a855-c23389e138dc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How do you create a Ruby script file and execute it on a command line?', N'Fresher', N'First, you create a Ruby script file with a .rb extension that contains your Ruby code. You can then execute this script using the ruby command in your command line. Basic Steps for Creating and Running a Ruby Script in a File 1. Create a File: Use any text editor to write your Ruby code, and save the file with a .rb extension, e.g., my_ruby_script.rb. 2. Write Ruby Code: Here is a simple example. 3. Run the Ruby Script: Go to your command line and navigate to the folder where the Ruby file is saved. Then, type the following command: After pressing enter, you will see the output: Getting More Advanced Command-Line Arguments You can access command-line arguments using special variables called ARGV.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8520c096-3ae0-4262-a335-c23469410a1c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When diagnosing a slow database query, what is your standard investigative workflow?', N'Middle', N'I would start by running an ''explain'' plan on the query to analyze the execution path, looking for full table scans or inefficient index usage. Next, I would examine the database workload to ensure that the query is not being blocked by table locks or resource contention, and finally, I would assess if the query structure can be optimized or if an additional index is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5267aed5-7733-4892-9a11-c2346c465da1', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Discuss the implications of using @import in a distributed library context.', N'Senior', N'Using @import in a library causes all globally defined variables and mixins to merge into the consumer''s global scope, leading to potential naming collisions. This ''pollution'' makes it difficult for consumers to manage dependencies and versioning within their own projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcf82c4a-00fb-41c3-9598-c236eb56910a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate the number of people who use a specific app in a country, what logic would you use?', N'Fresher', N'I would estimate the population, then filter by age group and smartphone penetration rates. Then, I would make an assumption about how many people within that demographic are likely to use such an app, possibly adjusting based on internet connectivity and market competition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'302666ea-6c63-415f-826d-c23867803e21', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the difference between Interpolation and Property Binding.', N'Junior', N'Interpolation uses double curly braces to insert string values from the component into the template. Property binding uses square brackets to set the property of a DOM element to a value from the component, which is useful for non-string values like booleans or numbers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a3e3110-d965-42c8-9981-c23d73b2ddc3', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is Rust''s ownership model important for Rocket?', N'Fresher', N'The ownership model ensures memory safety without a garbage collector, which allows Rocket to be highly performant. It prevents data races and ensures that resources are cleaned up correctly after a request is finished.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d0387ef-0786-4050-bc1f-c23f7f19c0f4', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB achieve ACID transactions, and what are the limitations?', N'Middle', N'MongoDB supports multi-document ACID transactions by using a snapshot isolation model. While they ensure data integrity across multiple operations, they introduce performance overhead and should be used sparingly, as long-running transactions can impact the performance of the entire replica set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77a03a62-e1a5-4d33-b540-c244338cf440', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue involving high disk I/O wait times in a database node?', N'Senior', N'I identify the processes generating the most I/O using system monitoring tools and correlate them with query execution patterns. I look for unoptimized queries causing massive disk spills, excessive logging levels, or insufficient memory causing the database to rely on swap space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9b6de15-40cb-4dac-87fc-c2443ca7d637', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Does Litestar support automatic documentation?', N'Fresher', N'Yes, Litestar provides built-in support for generating interactive API documentation. It automatically creates OpenAPI schemas based on the type hints and models defined in the application, which can be viewed through Swagger UI or Redoc.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6c8618f-6e1d-4fd4-98f8-c244bf48b634', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are the trade-offs of using ''Store'' objects versus individual signals in SolidJS?', N'Senior', N'Signals are ideal for simple, granular state, while Stores provide a structured way to handle nested data with deep reactivity tracking. Stores offer better ergonomics for complex objects but introduce a slight overhead in proxy creation and tracking management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a9c310f-d63a-454d-a08c-c244dfafd5f6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the ''Request Store'' pattern, and why is it useful?', N'Middle', N'The Request Store pattern involves using a thread-local variable or a gem to store data that needs to be accessible anywhere during the lifecycle of a single HTTP request. It is useful for avoiding redundant lookups of global objects like the current user or configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85372ee2-0122-4746-81c3-c245bec54153', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Migration in the context of Ecto?', N'Junior', N'A migration is a version-controlled way to change the database schema over time. It allows developers to define structural changes, such as creating tables or adding columns, in a predictable and repeatable manner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc9641f-561d-4d7a-a1b6-c2493323e2af', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the concept of undefined behavior in C affect language performance and compiler design?', N'Middle', N'Undefined behavior allows compilers to make aggressive optimization assumptions by ignoring edge cases that are the programmer''s responsibility to avoid. This leads to faster execution speeds and smaller binaries, but it places a significant burden on the developer to ensure correct logic, as the compiler may produce unpredictable results if these constraints are violated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf91dec4-9c73-4f90-acb2-c24a85eca61b', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why you would like to use semantic tag?', N'Fresher', N'* Search Engine Optimization, accessibility, repurposing, light code. * Many visually impaired person rely on browser speech and semantic tag helps to interpret page content clearly. * Search engine needs to understand page content to rank and semantic tag helps. * Semantic code aids accessibility. Specially, many people whose eyes are not good rely on speech browsers to read pages to them. These programs cannot interpret pages very well unless they are clearly explained. * Help Search engines to better understand pages. Search engine need to understand what your content is about when rank you properly on search engines. Semantic code tends to improve your placement on search engines, as it is easier for the "search engine spiders" to understand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6b4a3e-ef8f-43c7-be88-c24eae8ae290', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle multiple clients at once?', N'Fresher', N'Redis uses an I/O multiplexing mechanism to handle multiple client connections. This allows a single thread to monitor multiple sockets and process requests efficiently without blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7d4e8fe-fe90-4d3d-b0ef-c25046e76c68', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you handle global CSS in Svelte?', N'Junior', N'Global CSS can be handled by using the :global() modifier within a component''s style tag. This tells the compiler to apply the styles globally rather than scoping them to the current component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9802b238-e5cc-4fb1-83b9-c250f3087174', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a decorator in Flask routing?', N'Intern', N'A decorator, such as the route decorator, is a Python feature used to wrap a function to add functionality. In Flask, it registers a function as a handler for a specific URL pattern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca824f6a-e447-4f12-93f5-c25149e96ae0', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to free dynamically allocated memory?', N'Intern', N'Dynamically allocated memory remains occupied until it is explicitly released. Failing to free this memory leads to a memory leak, which can exhaust the system''s available memory over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e46bae-a157-4d6d-a92c-c251c388f173', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is caching used in system architecture and what is a potential drawback?', N'Middle', N'Caching is used to store frequently accessed data in memory to reduce latency and database load. The main drawback is the challenge of cache invalidation, which can lead to users seeing stale or inconsistent data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'592c01ed-5798-46b4-9cf9-c254d71e915f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of the ''config'' directory in an AdonisJS project?', N'Fresher', N'The config directory contains configuration files for various services like database, authentication, and mail. It keeps settings separate from the core logic, allowing developers to manage environment-specific variables easily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8b647fa-0cd5-442d-acff-c257603902eb', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors should you consider when deciding between a synchronous and asynchronous processing model?', N'Intern', N'Synchronous processing is simpler to implement and keeps the user informed in real-time, but can lead to performance bottlenecks if tasks are long-running. Asynchronous processing allows the system to handle tasks in the background, improving responsiveness and throughput at the cost of increased complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a4f8fba-95c3-47f9-8339-c257a60d33ac', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are generics in TypeScript?', N'Intern', N'Generics provide a way to create reusable components that can work with a variety of types rather than a single one. They allow you to define functions, classes, or interfaces that can be parameterized with specific types when they are used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c678f23-a78c-4dab-a561-c25bba5059c1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Lifting State Up in React?', N'Intern', N'When several components need to share the same changing data then it is recommended to _lift the shared state up_ to their closest common ancestor. That means if two child components share the same data from its parent, then move the state to parent instead of maintaining local state in both of the child components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b1753d9-2a85-4182-9b85-c25c11976cd0', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How can you validate user input in a Spring Boot application?', N'Junior', N'You use the @Valid annotation along with standard Java Bean Validation annotations like @NotNull, @Size, or @Email on your data transfer objects. When the request reaches the controller, Spring automatically validates the input and returns errors if constraints are violated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'360969f5-7be5-4713-927c-c25cfbc7f837', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between a ''production'' environment and a ''testing'' environment?', N'Intern', N'A testing environment is a sandbox where developers can experiment and verify functionality without affecting real users. The production environment is the live system where actual users interact with the product. Keeping these separate prevents bugs or experimental changes from disrupting the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'639bbad0-14d1-49a8-96cf-c260c0b9107d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the ''search_type'' parameter in queries?', N'Middle', N'The search_type parameter defines the distributed search execution strategy, such as whether to perform a ''query_then_fetch'' or ''dfs_query_then_fetch''. It controls how the cluster gathers scores and data from different shards to ensure accurate relevance calculations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3e271b2-ef57-4659-8a31-c26275c860c6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Universal Rendering in the context of Nuxt?', N'Fresher', N'Universal rendering means the application can be rendered on both the server and the client. The server renders the initial state of the page to provide fast content delivery and SEO, after which the client takes over to provide a dynamic, interactive experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52687993-21c5-40cb-acaa-c262e1a2f2b1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you prevent blocking the Event Loop?', N'Junior', N'To prevent blocking the Event Loop, you should avoid performing heavy synchronous computations or complex CPU-bound tasks inside the main thread. Such tasks should be offloaded to worker threads or handled by external services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab1f6d4f-f78b-4603-8b2e-c26381ef7d56', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Is Echo considered a heavy framework?', N'Fresher', N'No, Echo is considered a lightweight or minimalist framework. It provides only the essential tools needed for building web services and avoids adding unnecessary abstractions or bloat, allowing for high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3669c9f8-923c-407f-955a-c263cd5f1cbb', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database triggers differ from stored procedures, and when should you use them?', N'Middle', N'Stored procedures are explicitly called by the application to perform specific tasks, whereas triggers are event-driven and execute automatically in response to data modifications like inserts or updates. Triggers are useful for maintaining audit trails or complex integrity constraints, but they can make application logic harder to debug if overused.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d6c6a07-06b8-408c-be6c-c263e1603229', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby implement ''singleton methods'' internally?', N'Senior', N'When a singleton method is defined, Ruby creates an anonymous ''singleton class'' (also called an eigenclass) that sits at the top of the object''s lookup chain. This class holds the singleton methods, ensuring they only impact the specific instance while remaining transparent to the rest of the object''s class hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c944ccdf-6286-4361-a32a-c264c673d254', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the function of the x-text directive?', N'Intern', N'The x-text directive updates the text content of an HTML element to match the result of a JavaScript expression. It ensures that the content remains synchronized with the component''s state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81685d20-aeeb-44ef-a880-c2658a420575', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between software architecture and software design?', N'Senior', N'Software architecture and software design are both vital components of the software development process. While there is some overlap between the two, they cater to different aspects of project management and execution. Core Distinctions - Scope: Architecture defines the macro structure of the system, whereas design zooms in on specific components or modules. - Focus: Architecture concentrates on high-level concepts, like system requirements and global decisions, while design is concerned with the detailed mechanism and strategies for each system component. - Abstraction Levels: The architecture operates on the high-level abstractions, focusing on the overall system, where the design is generally on the low-level abstractions dealing with detailed mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ccd7f0e-0ffb-401b-b0d2-c265abdf8de8', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the concept of Doublewrite Buffering in InnoDB and why it is necessary.', N'Senior', N'The Doublewrite Buffer is a storage area where InnoDB writes pages before flushing them to the actual data files. This prevents data corruption from partial page writes during a crash, as the database can recover a clean copy from the buffer if the original page write was interrupted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b978e552-0555-40ee-bb30-c267b702e4e9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the advantages of using ''ProblemDetails'' for API error handling?', N'Middle', N'ProblemDetails is an RFC-compliant standard for representing errors in HTTP APIs. It provides a consistent, machine-readable structure that includes fields like status, title, and trace ID, making it easier for client applications to parse and handle errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
