INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'317271ea-a40a-4969-8617-c2c4553377d3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between a table and a collection in NoSQL?', N'Intern', N'In SQL, a table stores rows of data with a fixed schema. In NoSQL document databases, a collection stores a group of documents that do not necessarily require a uniform structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'813b30c6-2ea2-439e-85f2-c2c61bb3333b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''coordinate-and-broadcast'' search model work in a distributed cluster?', N'Senior', N'When a query arrives, the coordinating node broadcasts it to all shards containing the relevant data. Each shard executes the search locally and returns partial results to the coordinating node, which then merges, sorts, and formats the final result set before sending it to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa8edf7c-0457-4ac0-8b4b-c2c81e5ad101', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the Consistency property in ACID.', N'Fresher', N'Consistency ensures that a transaction brings the database from one valid state to another valid state. It maintains all predefined rules, constraints, and triggers throughout the transaction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99e7db2f-b022-4dfc-902b-c2cc6f5938e3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the restrict keyword in C?', N'Middle', N'The restrict keyword is a type qualifier that tells the compiler that a pointer is the only way to access the object it points to. This allows the compiler to perform more aggressive optimizations, such as reordering instructions, by guaranteeing that no other pointer aliases the same memory address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e529f92e-a38c-476d-8edf-c2cca3904a0a', N'954a0331-deff-4399-b588-96f39fec001d', N'What is an RxJS Subject?', N'Intern', N'An RxJS Subject is a special type of Observable that acts as both an Observer and an Observable. - As an Observer, it can receive values using next(), error(), and complete() methods - As an Observable, you can subscribe to it using the subscribe() method The key difference from a regular Observable is that a Subject is multicast, meaning it shares a single execution stream among all its subscribers. A regular Observable is typically unicast, creating a new execution for each subscriber.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'702f2857-aea9-4f8f-b9ad-c2d2e1820fe9', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis compare to a traditional Relational Database like MySQL?', N'Fresher', N'Redis is an in-memory NoSQL store optimized for speed and simple data structures, whereas MySQL is a disk-based relational database optimized for complex queries and structured data with ACID compliance. Redis is typically used alongside a relational database to improve speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f810580-b0d5-43ce-aa5b-c2d54642bd9a', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue 3''s ''Compiler-SFC'' facilitate better integration with build tools?', N'Senior', N'The compiler transforms Single File Components into standard JavaScript modules, optimizing the template during the build process. By performing static analysis at compile-time, it generates code that is highly efficient for modern JavaScript engines, enabling features like tree-shaking for unused features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4795107b-5e22-4db2-ac4a-c2d55b818833', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe how the ''scope chain'' is resolved during execution and its impact on performance.', N'Senior', N'The scope chain is a linked list of lexical environments that the engine traverses to find variable bindings. Deep nesting of closures or functions increases the depth of this chain, which can slightly degrade performance due to the overhead of looking up identifiers through multiple lexical levels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dda1013-6a52-4530-be00-c2d60a10d003', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the Factory pattern and how is it used?', N'Intern', N'The Factory pattern is a design pattern used to create objects without specifying the exact class of the object that will be created. It provides a way to encapsulate the instantiation logic and can be particularly useful when the creation process is complex or when the type of object to be created is determined at runtime. For example, in JavaScript, you can use a factory function to create different types of objects: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the Observer pattern and its use cases The Observer pattern is a design pattern where an object, known as the subject, maintains a list of its dependents, called observers, and notifies them of any state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999d1cf9-d76d-4765-95a0-c2d909bbba56', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Describe the security risks associated with mass assignment in Rails and how modern Rails versions mitigate them.', N'Senior', N'Mass assignment allows users to inadvertently or maliciously update unauthorized attributes by passing unexpected parameters. Modern Rails mitigates this by requiring Strong Parameters, which explicitly define a whitelist of permitted attributes, ensuring that only intended fields can be modified via mass assignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa949ce6-b8f0-44da-9bd2-c2d9e679b0a9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does ''progressive enhancement'' mean in the context of Remix?', N'Intern', N'Progressive enhancement is the practice of building a site that works with basic HTML first and then adding extra features like JavaScript for a better experience. Remix encourages this by using standard web forms that work with or without JS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f6ca2d4-9baa-4261-a6e1-c2da4d9d98a9', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the concept of environment variables in NestJS, and how can they be utilized for configuration management?', N'Fresher', N'Environment variables are a way to store configuration settings that can change between different environments (like development, staging, production, etc.). They are often used to store sensitive information like database credentials, API keys, or any other configuration that might change depending on the environment. NestJS provides a ConfigModule that uses the dotenv package to load environment variables from a .env file into process.env. Here''s an example of how you might use ConfigModule to load environment variables: In the above example, ConfigModule.forRoot() loads the .env file and the variables can be accessed anywhere in your application using process.env.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b338d9eb-de95-4538-8a92-c2db4b48c09a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a router in a backend web application?', N'Fresher', N'A router is a component that matches incoming HTTP requests to specific handler functions based on the request method and the URL path. It acts as a traffic controller to ensure the request is processed by the correct part of the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f01017c9-3a7b-4676-8b12-c2dd3cfc23c2', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the architectural implications of implementing Multi-Tenancy at the database level?', N'Senior', N'Multi-tenancy can be implemented via separate databases per tenant, shared databases with tenant IDs, or shared schemas. Choosing the right approach involves balancing isolation and security against resource utilization and the ease of performing cross-tenant analytics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5c7b5e2-172c-45be-9221-c2de6015c107', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the benefit of using __init_subclass__ over a metaclass?', N'Middle', N'__init_subclass__ provides a simpler, more readable way to customize class creation without the complexity of writing a custom metaclass. It is specifically designed to handle class registration and configuration when a class is subclassed, avoiding the potential conflicts that can arise from multiple inheritance of metaclasses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd89a6dc1-0642-4184-b601-c2e07ede500d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you mitigate the ''N+1'' query problem in a microservices environment?', N'Senior', N'You can mitigate this by utilizing API composition or GraphQL to aggregate data at the edge, or by implementing a data projection layer that pre-joins necessary information. Alternatively, ensuring services have data ownership that minimizes cross-service lookups during requests effectively reduces the round-trip overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc98f763-4862-44e1-840c-c2e1694eb674', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit differ from traditional frameworks like React or Angular?', N'Fresher', N'Lit focuses on building standard web components that work natively in the browser, whereas traditional frameworks often require their own runtime to render and manage components. Lit is much smaller in size and aims to provide a lightweight abstraction over native browser features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc9e7a13-5779-4e1d-8164-c2e2d812bc2e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of an interface in Go?', N'Intern', N'An interface defines a set of method signatures that a type must implement. It allows for polymorphism by enabling different types to be treated as the same type if they satisfy the required behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a05a78af-8e8b-4a13-9786-c2e33e7e44df', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the array splice method', N'Intern', N'The splice() method in JavaScript is used to add, remove, or replace elements within an array. Unlike slice(), which creates a shallow copy and does not alter the original array, splice() modifies the original array in place and returns an array containing the removed elements. Syntax - start: The index at which to start changing the array. - deleteCount: (Optional) The number of elements to remove from the array. If omitted, all elements from the start index to the end of the array will be removed. - item1, item2, ...: (Optional) Elements to add to the array, starting at the start position. Examples Note: - The splice() method modifies the original array. - It returns an array containing the elements that were removed (if any).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'673c120f-481b-4435-8098-c2e609beca9a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi support sub-routers?', N'Junior', N'Yes, Chi supports mounting sub-routers using the Mount method. This allows you to modularize your application by splitting different parts of the API into separate files or packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc38cd4e-5e77-4608-a4a9-c2e6a761d2b4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of the context''s ''Keys'' map in Gin?', N'Senior', N'The Keys map provides a thread-safe-like mechanism to pass data between middleware and handlers within the same request lifecycle. While useful, excessive reliance on it can lead to poorly typed code; it is better to use it sparingly for request-scoped metadata like user IDs or tracing spans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
