INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc5455f7-2044-4ef9-b3ae-c2e8b719cdb7', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js implement Incremental Static Regeneration (ISR), and what problem does it solve?', N'Middle', N'ISR allows you to update static pages after you have built your application without rebuilding the entire site. It solves the limitation of traditional SSG where content could become stale until the next deployment. By setting a revalidation time, Next.js can regenerate a page in the background when a request comes in, balancing the performance of static files with the need for up-to-date content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ee3d172-8f6a-4439-a7a7-c2eb88b26c0a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s event delegation work, and why is it preferred over attaching listeners to individual elements?', N'Middle', N'Event delegation uses event bubbling to attach a single listener to a parent container rather than many listeners to individual child nodes. This reduces memory consumption and automatically handles elements added to the DOM dynamically after the initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d328323-a84e-4943-a45a-c2f3dd7c2b21', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a property delegate?', N'Intern', N'A property delegate is a mechanism that allows you to hand off the responsibility of getting and setting a property to a separate object. This is useful for implementing patterns like lazy initialization or observable properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d6a28c1-2692-4f71-9715-c2f5e692c744', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the Jinja2 template engine used for in Flask?', N'Junior', N'Jinja2 is the default templating engine for Flask used to generate dynamic HTML content. It allows developers to embed Python-like expressions, logic, and loops directly into HTML files to render data returned by the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cd47309-7245-4571-a9e3-c2f6c770d900', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between the ''const'' keyword and a ''#define'' macro?', N'Junior', N'A ''const'' variable has a specific data type and is subject to scope and type-checking by the compiler, which aids in debugging. A ''#define'' macro is a preprocessor instruction that performs simple text substitution before compilation, meaning it lacks type safety and scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1018178-c1ce-449b-94d4-c2f81173dd39', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the importance of testing in software development?', N'Intern', N'Testing is crucial because it helps identify defects and ensures the software behaves as expected before it reaches the user. It provides confidence that new changes do not break existing functionality, which is known as regression testing. A strong testing culture leads to more reliable, maintainable, and higher-quality software products.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec7484dd-ebbf-461e-8573-c2feead758ee', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can control directives like @if and @for improve styling logic?', N'Middle', N'Control directives allow you to create dynamic styles based on conditions or data sets, such as generating utility classes based on a map of breakpoints. This significantly reduces manual labor and helps create highly flexible design systems that adapt to different configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b413263b-42b6-4c66-89a5-c303979b9b10', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''Map'' and ''FlatMap''?', N'Fresher', N'A ''Map'' transforms each element in a collection to a new value. A ''FlatMap'' transforms each element into a collection and then flattens the resulting structure into a single collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59b08b01-0b99-4ce5-b9cb-c30540d88248', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the significance of the ''commit phase'' in the React rendering lifecycle.', N'Senior', N'The commit phase is where React applies the changes calculated during the render phase to the actual DOM. It is the only phase where React interacts with the host environment, and it is strictly synchronous to ensure that the user does not see partially applied DOM updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8abc026-2bb0-4d50-ad9f-c307ea78917d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a scope in Actix-web?', N'Intern', N'A scope is a way to group related routes under a common URL prefix. It helps organize large applications by allowing developers to modularize route definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cfc262d-7cb4-4ec2-8c7a-c3091738a77b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is database sharding used to scale systems?', N'Middle', N'Database sharding is a technique where a large dataset is partitioned into smaller, more manageable chunks across multiple database servers. This improves performance by reducing the load on individual database instances and allows for scaling storage capacity beyond the limits of a single machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73f6ac86-85cd-4bd2-9a69-c30a5985d014', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are Lifecycle Events in NestJS?', N'Fresher', N'Lifecycle events are hooks that allow you to tap into the lifecycle of modules and providers, such as when the application starts or shuts down. Examples include onModuleInit and onModuleDestroy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c14ddf3e-acb1-4fad-bc1c-c30a7063646f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between ''Repeatable Read'' and ''Read Committed'' isolation levels?', N'Middle', N'Read Committed ensures that a transaction only sees data committed before a query begins, preventing dirty reads. Repeatable Read is the default in InnoDB and ensures that multiple reads within the same transaction return the same data, preventing non-repeatable reads by using consistent snapshots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30edffb2-0c58-4890-b875-c30e14a43ab7', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do ''Opaque Types'' (some P) differ from ''Existential Types'' (any P) in terms of compiler visibility?', N'Senior', N'Opaque types hide the underlying concrete type while keeping the identity consistent, allowing the compiler to optimize the code as if the type were known. Existential types hide the type identity and require dynamic dispatch, leading to less efficient code execution due to the runtime cost of type erasure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e88ee5c-cb39-420e-8597-c30fdfff728e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are Form Request classes in AdonisJS?', N'Fresher', N'Form Requests are specialized classes used to encapsulate validation logic for specific routes. By moving validation to these classes, you keep your controller methods clean and focused on processing the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b3e9db5-5f65-422d-ac08-c3150c66209e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of middleware in Redux, and how does it enable side-effect management?', N'Senior', N'Middleware acts as a third-party extension point between dispatching an action and the moment it reaches the reducer. It allows developers to intercept actions to perform asynchronous tasks, logging, or routing, effectively decoupling side effects from the synchronous state transition logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90ab7d9d-9ec8-46ff-b818-c315f324a45c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the ''ApplicationEventPublisher'' in decoupling components?', N'Senior', N'It provides a mechanism for event-driven programming, allowing beans to publish events that other listeners can react to without knowing who sent them. This decouples the business logic of the producer from the side effects handled by the listeners, promoting modular design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b51c41e7-f620-4088-b80a-c3169bd54ad5', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the benefits of using a Dependency Injection framework?', N'Middle', N'Dependency Injection promotes loose coupling by removing the responsibility of object creation from the classes that use them. It makes code more modular, easier to maintain, and significantly simplifies unit testing by allowing developers to inject mock implementations of dependencies. This architectural pattern moves configuration logic outside of the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
