INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c90dc8e-17fd-4165-a4de-c321377ec73e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What does ''sideEffects: false'' in package.json tell Webpack?', N'Middle', N'This flag signals to Webpack that a package has no side effects, meaning the module does not perform any actions when imported other than exporting items. This allows Webpack to safely remove unused exports, significantly enhancing the tree-shaking process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed5dd923-a0ae-4a72-90f8-c3219aef2878', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When should you choose a message queue over a REST API for inter-service communication?', N'Middle', N'Use a message queue when you need asynchronous processing, decoupling of services, or to buffer traffic spikes. REST APIs are better suited for request-response patterns where immediate confirmation or synchronous data retrieval is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eb562a7-97e9-4dc1-8dcc-c326663a06aa', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the risk of using ''Type Assertions'' (as) compared to ''Type Guards''?', N'Senior', N'Type assertions essentially override the compiler''s inference, which can lead to runtime errors if the underlying data structure is not what the developer expected. Type guards are safer because they perform runtime checks to verify the type before allowing access to its members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4b8ffb4-8d35-4d2e-a2d2-c3271914e24f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between fail-fast and fail-safe iterators in Java collections?', N'Middle', N'Fail-fast iterators throw a ConcurrentModificationException if the collection is modified structurally while it is being iterated, ensuring early detection of bugs. Fail-safe iterators work on a copy or a modified view of the collection, allowing modifications without throwing exceptions. Fail-fast is safer for detecting inconsistencies, while fail-safe is better for concurrent access scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e1eebf-4e47-4fde-bc3f-c32867e00653', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the importance of ''Pagination'' and the different strategies for implementing it.', N'Senior', N'Pagination prevents overwhelming clients and servers with large payloads, improving overall system stability. Offset-based pagination is simple but inefficient for large datasets, while cursor-based pagination is more performant and robust for real-time data feeds as it avoids issues with shifting data during navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8de0c633-fbf7-480e-a6c1-c32bc9a93300', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you optimize Angular applications for server-side rendering (SSR) using Angular Universal?', N'Senior', N'Optimization involves ensuring that initial state is transferred from the server to the client to prevent redundant API calls, and keeping the component logic isomorphic. One must also be careful with browser-specific APIs, using platform-checkers to ensure that code only executes in the appropriate environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
