INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddfcb6fe-e363-4c95-b854-c3311370ad75', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do Lit''s directives, such as ''repeat'' or ''cache'', optimize rendering performance?', N'Senior', N'Directives like ''repeat'' use keyed reconciliation to minimize DOM mutations when lists change, ensuring existing elements are reordered rather than destroyed and recreated. ''Cache'' helps by preserving the DOM structure of complex templates, reducing the overhead of re-parsing and re-rendering when the view toggles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6b0290b-0a50-4667-a488-c3334894f08b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How could you make sure a const value is garbage collected?', N'Fresher', N'In JavaScript, garbage collection is automatically performed by the browser or the JavaScript engine. When a value is no longer being used or referenced, it becomes eligible for garbage collection. In the case of a const value, the same rules apply as with any other value. As long as the const value is not referenced by any other variables or objects in the program, it will become eligible for garbage collection when the variable goes out of scope. Here are some best practices to follow when working with const variables: 1. Only use const when you know that the value should not be reassigned. 2. If you ever want to change the contents of the variable for any reason in the future, then don''t declare it as const. 3. Use let or var instead of const if you need to reassign the value. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
