INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5064d86-8a66-4384-8375-c33929082c4c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you handle global state in a Lit-based application without violating component encapsulation?', N'Senior', N'Global state is typically managed through external stores or services that expose observables or event emitters. Components subscribe to these stores within their lifecycle, ensuring that while the state is global, the component''s internal logic remains self-contained and testable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'427f4c12-9279-47f3-b3ea-c33ab7c6c19a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''go mod'' tool used for?', N'Junior', N'The ''go mod'' tool is Go''s dependency management system. It tracks external package versions in a file and ensures that the project uses reproducible builds by managing the dependencies required for the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'751db000-b55d-4c79-a55a-c33bb9b73052', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why would you choose Server-Side Rendering (SSR) over Static Site Generation (SSG)?', N'Middle', N'SSR is preferred when your data changes frequently or depends on request-specific information like cookies or headers. While SSG is faster because it serves pre-built HTML, SSR ensures that the user always receives the most current data at the cost of slightly higher latency per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30613bc5-767b-48b4-95aa-c33f8788e280', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix handle navigation differently than standard HTML links?', N'Fresher', N'Remix uses a special component that intercepts standard link clicks to prevent a full page reload. Instead, it fetches only the data and components needed for the next page, allowing for a much smoother and faster transition between views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'453c0cae-4eb9-4182-abbf-c343957fb7a0', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of Service Discovery in a microservices architecture?', N'Middle', N'Service discovery enables services to automatically find the network locations of other service instances in a dynamic environment where nodes frequently scale up or down. It typically involves a registry where services announce their presence and location.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb40fc72-da77-479b-9734-c3449a051df1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is reflection a concern in native compilation?', N'Fresher', N'Native compilation requires all code paths to be known at build time. Reflection allows for dynamic code execution at runtime, so Quarkus needs to be explicitly told about reflected classes to ensure they are included in the native binary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce59f760-37d6-42bf-a4a4-c3472bf9249c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does the ''useSelector'' hook work?', N'Junior', N'The useSelector hook takes a selector function as an argument and returns the specific data requested from the Redux store. It also subscribes the component to the store, ensuring the component re-renders whenever the selected data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f31843b-5a9f-4157-963a-c3472dc75b41', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the performance implications of using Box in Rust?', N'Middle', N'Box allocates data on the heap, which provides a fixed-size pointer on the stack for dynamically sized data. While it allows for recursive data structures, it introduces a heap allocation and a pointer indirection, which can be slower than stack-allocated data due to memory fragmentation and cache misses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd526097-933b-45d4-b33e-c34810803158', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the trade-offs when choosing between a push and pull model for monitoring system metrics?', N'Senior', N'A pull model is generally more robust for service discovery and allows for centralized configuration of scraping intervals, though it requires the service to be reachable. A push model is better for ephemeral or serverless tasks that don''t have a stable network location, but it can easily overwhelm the metrics collector during traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b05857e-389f-4de0-9063-c34a42b15c81', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does Journaling work in MongoDB?', N'Fresher', N'Mongod primarily hosts the write operations in memory in shared view. It is called shared because it has memory mapping in actual disc. In this process, a write operation occurs in mongod, which then creates changes in private view. The first block is memory and the second block is "my disc". After a specified interval, which is called a "journal commit interval", the private view writes those operations in journal directory (residing in the disc). Once the journal commit happens, mongod pushes data into shared view. As part of the process, it gets written to actual data directory from the shared view (as this process happens in background). The basic advantage is, we have a reduced cycle from 60 seconds to 200 milliseconds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'169257aa-09e0-4a79-838f-c34a437b9bd6', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the refresh interval in Elasticsearch?', N'Junior', N'The refresh interval is the frequency at which new data in the index buffer is made searchable. By default, Elasticsearch performs this operation every second, balancing the need for near real-time search with the performance cost of frequent index updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58287b94-c356-47e9-8e6a-c34ad15966e2', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does Atomicity mean in the context of a transaction?', N'Junior', N'Atomicity ensures that a transaction is treated as a single ''all-or-nothing'' unit. If any part of the transaction fails, the entire transaction is aborted, and the database is rolled back to its state before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43ea884b-4eaa-47e7-961b-c34dccf6c2fb', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix emphasize the use of standard HTML forms?', N'Intern', N'Remix emphasizes standard HTML forms to ensure that applications remain functional even if JavaScript fails to load or execute. By relying on browser-native form behaviors, the framework provides a robust fallback mechanism while enhancing the experience with progressive enhancement when JavaScript is available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90d410a3-59a1-4e81-b3bc-c34f8485b5a4', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you ensure data integrity in a Rails application beyond model validations?', N'Middle', N'Model validations are for user feedback and application-level constraints, but they do not guarantee data integrity. True integrity should be enforced at the database layer using constraints such as foreign keys, unique indexes, and NOT NULL constraints to prevent corrupt data from being inserted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
