INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6beec541-e2f7-4bf7-a730-c362045fa7de', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Purge Thread'' in InnoDB contribute to space reclamation and performance?', N'Senior', N'The purge thread is responsible for cleaning up old row versions in the undo logs that are no longer needed by active transactions. If this thread cannot keep up with the rate of changes, the undo log grows uncontrollably, increasing disk pressure and slowing down performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
