INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'481d7cf2-cd2c-4c48-bfe1-c372c7a56f83', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are controlled components?', N'Intern', N'A controlled component is a React component that fully manages the form element''s state(e.g, elements like , , or )) using React''s internal state mechanism. i.e, The component does not manage its own internal state — instead, React acts as the single source of truth for form data. The controlled components will be implemented using the below steps, 1. Initialize the state using useState hooks in function components or inside constructor for class components. 2. Set the value of the form element to the respective state variable. 3. Create an event handler(onChange) to handle the user input changes through useState''s updater function or setState from class component. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
