INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8365e863-6ae9-444f-b3a1-c3925e0a6261', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Explain the underlying data structure Gin uses for routing and why it is more performant than standard library routing.', N'Senior', N'Gin utilizes a Radix tree, also known as a compact trie, to store route paths. This structure allows for O(k) lookup time where k is the length of the path, significantly outperforming the standard library''s map or sequential search approaches when handling large numbers of dynamic or static routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d4a73aa-7f98-4f19-9fc7-c392ae0ff844', N'4c000000-0000-0000-0000-000000000005', N'How do you implement graceful degradation in a system under high load?', N'Senior', N'Graceful degradation involves identifying non-critical features and disabling or limiting them when system resources are scarce. Techniques include circuit breakers to fail-fast on slow dependencies and prioritizing traffic for essential services to maintain core functionality for users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e77316fa-7784-4818-b502-c3949c317dbd', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain what happens when the useState setter function is called in React', N'Fresher', N'When the setter function returned by the useState hook is called in React, it schedules an update to the component''s state value. React then queues a re-render of the component with the new state. This process is typically asynchronous, and React batches multiple state updates together for performance. The same mechanism applies to other state setters such as useReducer''s dispatch — it is distinct from the legacy class-based this.setState. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6adcb1b8-f1ae-4ada-a6fc-c397a5cc4734', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber manage request bodies?', N'Fresher', N'Fiber provides built-in methods to parse incoming request bodies into various formats like JSON, XML, or form data. It allows developers to bind the request body directly to a struct for easy access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a95f4c2-3560-425c-86af-c398f554d699', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Can Hono be used for building REST APIs?', N'Fresher', N'Yes, Hono is excellent for building RESTful APIs. Its routing system supports standard HTTP methods like GET, POST, PUT, and DELETE, making it a perfect fit for resource-oriented service design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'470bbd0c-1660-4360-9ac2-c3a119a2b9dc', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular handle forms?', N'Fresher', N'Angular handles forms primarily through two distinct approaches: Template-driven forms and Reactive forms. - Template-driven forms are simpler and suitable for basic forms. They rely heavily on directives like ngModel and ngForm directly within the template to manage form state and validation. The logic is largely handled by Angular directives in the HTML. - Reactive forms are more robust and scalable, ideal for complex forms. They build the form model programmatically in the component class using classes like FormControl, FormGroup, and FormArray. This approach offers better testability, predictability, and control over form data flow and validation. Choose Template-driven for simple forms and Reactive for more complex scenarios or when testability is a priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3df12b2c-e28c-416f-9188-c3a413ad1bd9', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you distinguish between a bug in the code and an issue caused by environmental factors?', N'Fresher', N'You can isolate environmental issues by testing the application in a different setup or comparing the current environment configuration to a known working one. If the application works elsewhere, the issue is likely due to configuration, dependencies, or hardware rather than the logic itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02d21499-801e-4802-8fa8-c3a4ff5daa44', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How can you isolate your cursors from intervening with the write operations?', N'Fresher', N'As cursor is not isolated during its lifetime, thus intervening write operations on a document may result in cursor that returns a document more than once. The snapshot() method can be used on a cursor to isolate the operation for a very specific case. snapshot() traverses the index on the _id field and guarantees that the query will return each document no more than once. Restriction: * We cannot use snapshot() with sharded collections. * We cannot use snapshot() with sort() or hint() cursor methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6399ee74-77fb-4412-9b13-c3a9dc20e28d', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the purpose of an API schema, such as OpenAPI/Swagger?', N'Middle', N'An API schema provides a machine-readable contract that defines the endpoints, request/response formats, and authentication requirements. It facilitates automated documentation, client SDK generation, and contract-based testing to ensure consistency between development teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c7bd2ab-64f2-47ba-b7f9-c3aa401c4613', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you write a custom pipe?', N'Fresher', N'A custom pipe in Angular allows you to transform data within your templates. To create one, you typically use the Angular CLI command ng generate pipe . This creates a class decorated with @Pipe, which requires a name property used in templates. The class must implement the PipeTransform interface, which mandates a transform method. This method takes the input value and optional args and returns the transformed output. Once created, you use it in your template like {{ data | myCustomPipe:arg1:arg2 }}. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30f7314e-898f-4c9d-adaa-c3ad5f607122', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the Astro ''client'' directives in the context of progressive enhancement?', N'Senior', N'Client directives control when and how a component''s JavaScript is loaded and executed. By choosing between strategies like ''load'', ''idle'', or ''visible'', developers can defer non-critical interactivity until the browser is ready, effectively prioritizing critical path rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a513279b-a5ef-4099-bd29-c3af504fbb64', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of media queries?', N'Intern', N'Media queries are a CSS technique used to apply different styles based on specific conditions, such as the width, height, or orientation of the screen. They are the core tool for building responsive layouts that adjust to different devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be9e5b36-d278-47e7-ab47-c3af57b8caee', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the functional interfaces Supplier<T>, BooleanSupplier, DoubleSupplier, IntSupplierand LongSupplier?', N'Intern', N'Supplier (provider) - the interface through which a function is implemented that takes nothing to the input, but returns the result of the class to the output T; * DoubleSupplier- the supplier is returning Double; * IntSupplier- the supplier is returning Integer; * LongSupplier- the supplier is returning Long.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f057b80d-f735-4f43-ac27-c3b2945e4a1f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is strict mode in TypeScript?', N'Intern', N'Strict mode is a configuration setting that enables a comprehensive set of type-checking rules. Enabling it ensures that the compiler is as thorough as possible, which helps developers write safer and more predictable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'883ba745-3620-4f9d-b3af-c3b36f3e231a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the risks of using ''useAsyncData'' improperly regarding network waterfalls?', N'Senior', N'Improper use of ''useAsyncData'' can lead to request waterfalls if data fetching is nested within conditional logic or secondary component loads rather than being initiated in parallel at the page level. This forces the browser to wait for serial completion of requests, significantly increasing the time to interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be387266-d0bd-44d0-8e63-c3b5ba5a9c1f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What happens to the JavaScript used in an Astro component?', N'Intern', N'The JavaScript inside an Astro component runs exclusively on the server during the build process or request time. It is stripped out of the final output unless you specifically use a client directive to hydrate a component on the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ad557a3-720c-4934-8540-c3b732b0ba02', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a fatal error in PHP?', N'Intern', N'A fatal error is a critical issue that occurs during script execution, such as calling a non-existent function or class. When a fatal error occurs, the PHP engine stops the script execution immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca07236a-bc52-4e18-938e-c3b75a0e395f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is FastAPI considered ''editor-friendly''?', N'Fresher', N'Because FastAPI relies heavily on standard Python type hints, modern code editors can provide excellent autocompletion, type checking, and error detection. This significantly improves developer productivity and reduces common bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e28e8fb-dead-4059-8c91-c3b966301e82', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of the Hinted Handoff mechanism in Cassandra?', N'Senior', N'Hinted handoff is a temporary storage mechanism used when a node is unavailable during a write operation. The coordinator node stores a hint locally and replays it to the target node once it becomes available, helping to maintain eventual consistency without requiring a full repair.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42275473-a39f-4984-909d-c3b97644ca9c', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you test Redux logic effectively without relying on UI component integration tests?', N'Senior', N'Redux logic is tested by unit testing individual reducers with specific actions and asserting the returned state, and by testing action creators and middleware in isolation. Because these are pure functions or controlled pipelines, they are highly deterministic and can be tested quickly without mounting any components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56dc93aa-5c48-495c-be87-c3bdfcf5f7e5', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the consequence of using array indices as the value for keys in React?', N'Intern', N'Using array indices as keys causes React to reconcile the list incorrectly when items are reordered, inserted, or removed. Because the key identifies a position rather than an item, React reuses the wrong component instances — leaving stale local state, focus, and DOM attached to the wrong rows. The fix is to use a stable, unique identifier from the data (e.g. item.id). Index keys are only safe when the list is static and never reordered, filtered, or prepended to. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e1f611c-bef6-4341-a450-c3bf5235dafc', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is diffing algorithm?', N'Intern', N'React needs to use algorithms to find out how to efficiently update the UI to match the most recent tree. The diffing algorithms is generating the minimum number of operations to transform one tree into another. However, the algorithms have a complexity in the order of O(n³) where n is the number of elements in the tree. In this case, displaying 1000 elements would require in the order of one billion comparisons. This is far too expensive. Instead, React implements a heuristic O(n) algorithm based on two assumptions: 1. Two elements of different types will produce different trees. 2. The developer can hint at which child elements may be stable across different renders with a key prop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55a7e49-313f-407d-b038-c3c10d7f7723', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''when'' expression?', N'Intern', N'The ''when'' expression is a powerful alternative to the traditional switch-case statement found in other languages. It can match values against various conditions, including ranges and types, and can be used as an expression that returns a value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbba8d4d-d5d1-45af-8832-c3c636fd735e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'If you are asked to prioritize either development speed or system performance for an MVP, how do you decide?', N'Junior', N'For an MVP, speed to market is usually prioritized to validate the business idea with users. However, I would document technical debt and ensure the architecture allows for future performance refactoring once the product gains traction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'782e6a4c-9632-4e72-a822-c3c689d9ea4a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite manage caching during development?', N'Middle', N'Vite leverages browser caching for dependency chunks and uses a versioned approach to ensure that updated code is always fetched. If the dependency graph changes, Vite forces the browser to bypass the cache for the affected modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a47dd08-1c7e-4aa1-ad82-c3c7cd114d67', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is the use of non-virtual destructors in a base class considered dangerous?', N'Senior', N'If a base class has a non-virtual destructor, deleting a derived object through a pointer to the base class invokes undefined behavior because the derived class''s destructor will not be called. This results in resource leaks, such as unreleased memory or unclosed file handles, as only the base part of the object is cleaned up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c63c541-cc83-43c3-8a1d-c3ce681a1536', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does it mean to refactor code, and why is it useful?', N'Junior', N'Refactoring is the process of restructuring existing code to improve its readability, maintainability, and efficiency without changing its external behavior. It is useful for reducing technical debt and making the codebase easier for others to work with in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e75c7c70-d9a9-4136-ac08-c3cf462a3a17', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What do you do if you notice a mistake in a colleague''s work?', N'Fresher', N'I approach them privately and present my findings in a helpful, non-confrontational manner. My goal is to collaborate on a fix rather than criticizing, ensuring the quality of the team''s output remains high.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c75ff7df-ddb6-47cb-b373-c3d03c09234c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is ''Tree Shaking'' in Dart?', N'Intern', N'Tree shaking is an optimization process performed by the Dart compiler that removes unused code from the final output. This results in smaller application sizes, which is crucial for web and mobile performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d950466-1a04-4f7f-aa81-c3d129f6756f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the concept of ''sealed classes'' and when you should use them.', N'Middle', N'Sealed classes represent restricted class hierarchies, where all subclasses must be defined within the same package or file. They are ideal for representing state machines or exhaustive ''when'' expressions, as the compiler can ensure all possible types are handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcef80db-2690-487a-b954-c3d570427cde', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the difference between Write-Through and Write-Back caching strategies?', N'Middle', N'In Write-Through, data is written to the cache and the backing store simultaneously, ensuring consistency but increasing latency. In Write-Back, data is written only to the cache, and the backing store is updated later, offering lower latency but risking data loss if the cache fails before the sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2483d43c-1ae4-4a33-9d9b-c3d6635d72ae', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why are type hints important in FastAPI?', N'Intern', N'Type hints tell FastAPI what kind of data to expect for request parameters and return values. This allows the framework to provide automatic data validation, serialization, and high-quality editor support like autocompletion and error checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'064f9fef-ac6a-4362-8b97-c3d8ae82184d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Can you use standard HTML attributes in Preact JSX?', N'Junior', N'Yes, Preact supports standard HTML attributes directly in JSX, such as ''class'' instead of ''className''. This makes it feel closer to writing standard HTML compared to React''s requirement for camelCased attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'198eca6f-f160-4a0a-b333-c3dc3884d3cc', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you use immer library for state updates?', N'Fresher', N'Immer library enforces the immutability of state based on copy-on-write mechanism. It uses JavaScript proxy to keep track of updates to immutable states. Immer has 3 main states as below, 1. Current state: It refers to actual state 2. Draft state: All new changes will be applied to this state. In this state, draft is just a proxy of the current state. 3. Next state: It is formed after all mutations applied to the draft state Immer can be used by following below instructions, 1. Install the dependency using npm install use-immer command 2. Replace useState hook with useImmer hook by importing at the top 3. The setter function of useImmer hook can be used to update the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc313c78-2355-4db3-9013-c3dda267dbe0', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of Micronaut''s ''Filters''?', N'Middle', N'Filters in Micronaut are used to intercept HTTP requests and responses. They are commonly used for tasks like security authentication, logging, header manipulation, or metrics collection before the request reaches the controller or after the response is generated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'764f4343-cbe7-448d-8419-c3de16d6fcaa', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a custom provider in NestJS?', N'Fresher', N'A custom provider allows you to manually define how a dependency should be instantiated. This is useful when you need to use values, classes, or factories that are not simple class-based dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aec731c3-e790-42c9-ad58-c3de4b47dc85', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the application.yml file?', N'Junior', N'The application.yml file is the central configuration file for a Micronaut application. It defines settings for the server, data sources, security, and any custom properties required by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e370b3d9-8264-4218-b186-c3deb9a91fd3', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle context compared to the standard library?', N'Intern', N'Fiber uses its own ''Ctx'' struct to manage the request and response lifecycle, which is optimized for performance. This context object provides methods to access request parameters, headers, and body content much faster than the standard library''s approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5564abb0-bbee-4450-a99d-c3e2c354ea64', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What strategy would you use to prevent excessive re-renders in a large Redux-connected component tree?', N'Senior', N'I would implement granular selector patterns that subscribe to the smallest possible slice of state required for that specific component. Additionally, I would leverage shallow equality checking in `useSelector` and ensure that state is normalized to prevent unnecessary re-computations of derived data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'352306f3-2409-432d-977f-c3e36891d1d9', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the ''State'' extractor in Axum, and why is it preferred over using global variables for shared resources?', N'Middle', N'The State extractor allows for dependency injection by passing shared resources, like database pools or configuration, directly into handlers through the application state. Using this approach is preferred over global variables because it promotes testability through dependency mocking, ensures thread safety via Axum''s type-safe state management, and avoids the hidden side effects associated with global mutable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f24b0e27-bbf9-4838-8e14-c3e3a1ef500d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact have a built-in router?', N'Intern', N'Preact does not include a router in its core package. Instead, it relies on community-developed packages like ''preact-router'' to handle navigation and state management across different application views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9d839d5-462f-43b4-9e34-c3e3c8242e59', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt’s auto-import feature affect application performance and development experience?', N'Middle', N'The auto-import feature enhances development experience by reducing boilerplate, as developers do not need to manually import components or composables. While this creates a slight overhead during the initial build process due to auto-generation of type definitions, it does not negatively impact runtime performance because Nuxt resolves these imports into explicit statements during the compilation phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c52a0b82-dcb7-4b63-a041-c3e76e5f22ee', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a key-value database?', N'Intern', N'A key-value database is a simple type of NoSQL database that stores data as a collection of key-value pairs. Each item consists of a unique key and a corresponding value, making it highly efficient for fast lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d361c0d-39da-474f-8517-c3e97493a021', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why might you choose a graph database over a relational one?', N'Middle', N'Graph databases are superior for managing highly interconnected data where relationships are as important as the data itself. They allow for much more efficient traversal of complex networks compared to relational databases, which require expensive join operations for deep relationship levels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c455783f-078b-43fe-8db6-c3ec5fd4a1be', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is On-Demand capacity mode?', N'Intern', N'On-Demand capacity mode is a billing option where DynamoDB automatically scales throughput up or down based on your application''s traffic. You pay only for the requests you actually perform, making it ideal for unpredictable workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
