INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8a1151c-6495-4672-92e6-c3f4e27b1913', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Describe the purpose of the ''app.html'' template file.', N'Middle', N'The ''app.html'' file acts as the base shell for your entire application. It contains the essential HTML structure, including placeholders where SvelteKit injects the rendered page content, and is the primary location for adding global resources like fonts or meta tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'202c5154-0cdc-4312-9d5d-c3f5d82b62f0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a composite index, and what is the importance of column ordering?', N'Middle', N'A composite index covers multiple columns to speed up queries filtering on those fields. The order is critical because the database engine uses the leftmost prefix of the index; if the leading column is not used in the query''s WHERE clause, the index may be ignored by the query optimizer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f613bc1c-6fad-4120-a526-c3f5f9b7b876', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary goal of Preact?', N'Intern', N'Preact is designed to be a lightweight alternative to React. Its primary goal is to provide a similar API while maintaining a significantly smaller bundle size for better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'872907c3-374c-4e41-82b1-c3fa5d6d435b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Are all values in Ruby objects?', N'Fresher', N'Yes, Ruby is a pure object-oriented language. This means that every piece of data, including numbers, booleans, and even nil, is an instance of a class and possesses methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dce743bb-bf41-4329-8031-c3fbbc9f8b43', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is Fiber generally considered faster than the standard library net/http?', N'Junior', N'Fiber uses Fasthttp, which is optimized for high performance by minimizing memory allocations and reusing objects via sync.Pool. The standard library is designed for generality and compliance, whereas Fiber prioritizes raw throughput and low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4961b0dd-381e-4809-bb7b-c3fc2ad82274', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the benefits of using a module bundler?', N'Intern', N'Using a module bundler like Webpack, Rollup, or Parcel helps manage dependencies, optimize performance, and improve the development workflow. It combines multiple JavaScript files into a single file or a few files, which reduces the number of HTTP requests and can include features like code splitting, tree shaking, and hot module replacement. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of tree shaking in module bundling Tree shaking is a technique used in module bundling to eliminate dead code, which is code that is never used or executed. This helps to reduce the final bundle size and improve application performance. It works by analyzing the dependency graph of the code and removing any unused exports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'139eeffc-564e-42f1-be3f-c3ff27afbc63', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is ''uvicorn'' typically paired with ''gunicorn'' in production environments for FastAPI?', N'Senior', N'While Uvicorn is a high-performance ASGI server, it is often not fully featured for process management in production. Using Gunicorn as a process manager allows for robust worker management, graceful restarts, and configuration of multiple worker processes, which improves fault tolerance and CPU core utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'657895bc-558f-4048-97cf-c3ffa97dc9e0', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are the differences between const and readonly keywords?', N'Intern', N'C# supports two mechanisms for creating immutable fields: const and readonly. Key Distinctions - Initialization: const fields are initialized when declared, while readonly fields can be initialized at the point of declaration or in the class constructor. - Visibility: readonly fields allow for differing values within different class instances, whereas const ensures the same value across all instances. - Type Compatibility: const fields are limited to primitive data types, String, and null. readonly can be utilized with any data type. - Compile-Time/Run-Time: const fields are evaluated at compile time. On the contrary, readonly fields are evaluated at run-time, fittingly appealing to scenarios that necessitate a run-time reference or state. Code Example: const vs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83d2c66f-86b9-4b18-87eb-c40353501d3c', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of using ''Router::merge'' in Axum?', N'Junior', N'The merge method allows you to combine multiple routers into one. This is useful for modularizing large applications by keeping routes for different features in separate modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a3c382d-3152-4d27-92fc-c4041c617f36', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''app'' directory in modern Next.js?', N'Intern', N'The app directory is the modern way to structure Next.js applications using the App Router. It introduces React Server Components by default, allowing for better performance, streaming, and more advanced data fetching patterns compared to the older pages directory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab956903-11b6-4bf8-9822-c409c3b17059', N'4c000000-0000-0000-0000-000000000005', N'How does Service Mesh facilitate security and observability in a microservices architecture?', N'Senior', N'A Service Mesh offloads cross-cutting concerns like mTLS encryption, rate limiting, and request tracing to a sidecar proxy. This allows developers to focus on business logic while the infrastructure team manages uniform security policies and telemetry across the entire service fleet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3460232-59f5-4f6e-8543-c409fe29a231', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Are there limits to how many indexes a table can have?', N'Junior', N'Yes, there are limits on the number of indexes per table. Currently, you can have up to 20 GSIs and 5 LSIs per table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59c7fa2c-6548-4f93-aeda-c40df7248f7a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket facilitate testing?', N'Middle', N'Rocket includes a ''local'' module that provides a client for making requests directly to the application without binding to a network port. This allows for fast, reliable unit and integration tests that simulate the full request-response lifecycle in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd25b3f9-8344-4ef3-91a4-c40e10954822', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the trade-offs between using Scala''s path-dependent types and generic type parameters.', N'Senior', N'Path-dependent types bind a type to a specific object instance, enforcing strict encapsulation and preventing the mixing of types from different instances. In contrast, generic type parameters provide abstraction over types globally. The trade-off is that path-dependent types increase design complexity and runtime safety while reducing the flexibility associated with universal quantification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20bf7a36-9944-4d50-9bed-c40f148fc3fe', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why would you choose to use a ''Task'' module instead of a ''GenServer'' for background work?', N'Middle', N'A Task is designed for short-lived, one-off operations that do not need to maintain state. It is simpler to implement and more efficient for executing concurrent tasks where you just need to perform an action and optionally wait for a result, whereas GenServers are for persistent stateful services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fe1949e-1370-4c05-a37b-c4102fdbb6e9', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you make sure vue application is CSP complaint?', N'Fresher', N'Some environments(Google Chrome Apps) prohibits the usage of new Function() for evaluating expressions and the full builds of vue applications depends on this feature to compile templates. Due to this reason, the full builds of VueJS application are not CSP complaint. In this case you can use runtime-only builds with Webpack + vue-loader or Browserify + vueify technology stack through which templates will be precompiled into render functions. This way you can make sure VueJS applications are 100% CSP complaint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20344bee-713c-46c3-a87e-c4109ec76364', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember manage memory leaks in long-running single-page applications?', N'Senior', N'Ember manages the lifecycle of objects through the container, which automatically destroys components, services, and routes when they are no longer in use. Developers must ensure they manually teardown event listeners or external timers registered within the lifecycle hooks to assist the framework''s garbage collection efforts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f1c0ebc-70a5-46f4-8ce1-c411a7488782', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging a performance issue, what is the importance of establishing a baseline?', N'Intern', N'Establishing a baseline provides a measurement of the system''s normal behavior under standard conditions. Without a baseline, it is impossible to quantify how severe a performance degradation is or to verify if a fix has successfully restored the system to its expected state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eff5b073-cb3e-44e3-a408-c411d7540d14', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is IndexedDB', N'Intern', N'IndexedDB is a low-level API for client-side storage of larger amounts of structured data, including files/blobs. This API uses indexes to enable high-performance searches of this data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8fab543-a239-4992-b198-c41af870604e', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of database denormalization?', N'Middle', N'Denormalization involves adding redundant data or grouping data to reduce the number of joins needed for queries. It is used to improve read performance in read-heavy systems at the cost of increased storage and write complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15a91550-4a33-418e-9d54-c41c2c28f687', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the architectural role of a WSGI middleware in a Flask application?', N'Senior', N'A WSGI middleware acts as a wrapper around the Flask app, allowing you to intercept and modify requests or responses before they reach the framework or after they leave. It is useful for implementing cross-cutting concerns like compression, authentication, or rate limiting that should remain independent of the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b27a330f-b39d-4725-9bd4-c41cbc5b1a09', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the ''require'' cache work in Node.js?', N'Middle', N'When a module is first loaded, Node.js caches the result in the require.cache object. Subsequent calls to require the same module return the cached version, which improves performance by avoiding redundant file system I/O and re-evaluation of the module code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a6f99c7-0133-4a42-b479-c41e1ad01d2a', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s plugin system differ from Webpack''s ''loader'' pattern?', N'Senior', N'Vite uses a plugin system based on Rollup’s hook architecture, which is more streamlined and declarative. Unlike Webpack''s complex loader chains, Vite plugins interact with the build process through standard lifecycle hooks, making them easier to compose and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b32b241-bb9a-4288-92b5-c41ed8eaf816', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What happens if a request body fails validation in Litestar?', N'Junior', N'If validation fails, Litestar automatically intercepts the request and returns an error response to the client. This response typically includes details about which fields failed validation and why, using a 422 Unprocessable Entity status code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6be6bc6e-ffdd-4d52-ab41-c42036350b63', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''flash'' function?', N'Junior', N'The flash function stores a message in the user''s session to be displayed on the next page load. It is commonly used for showing feedback to users, such as success messages after form submissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9445e37a-b0a3-4264-a4f8-c42247bb2204', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What are slices in Go, and how do they differ from arrays?', N'Intern', N'Slices in Go are dynamic, flexible and reference-based data structures that enable efficient list management. They are built on top of arrays and offer features such as automatic resizing and ease of use. Slice Characteristics - Dynamic Sizing: Slices are resizable, ensuring adaptability as elements are added or removed. - Reference Semantics: Underneath, slices reference an array, meaning any modifications to the slice apply to the referred array. - Bounds Checking: Slices automatically handle out-of-bounds errors, offering an added layer of safety during indexing. - Reslice Efficiency: Operations like slicing a slice are highly efficient and do not involve element copying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41578aa6-5edc-4152-907e-c428dac2e257', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing between a relational database and a NoSQL database, what is the primary trade-off regarding data structure?', N'Junior', N'Relational databases require a strict, predefined schema which ensures data integrity but makes it harder to evolve data structures. NoSQL databases offer a flexible schema, allowing for faster development and handling of unstructured data at the cost of complex consistency management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5794cb5-8c7a-4591-a877-c42c4de3bc47', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle props destructuring?', N'Middle', N'In SolidJS, props are reactive objects, and destructuring them normally would break reactivity by disconnecting the signals. Developers must use the ''splitProps'' or ''mergeProps'' utilities, or access properties directly through the props object to preserve the reactive connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e402441-1974-4c7c-b47d-c42cffa6eb3f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the role of the Dependency Injection system in FastAPI and why it is useful for testing.', N'Middle', N'The Dependency Injection system allows you to define reusable components that FastAPI resolves and injects into path operations. It facilitates testing by allowing you to override dependencies with mocks or simplified versions during the testing lifecycle without modifying the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0581458-0832-44d0-b669-c43347253e5f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the architectural implications of using PostgreSQL''s TOAST mechanism?', N'Senior', N'TOAST automatically moves large attribute values to out-of-line storage to ensure that data rows fit within the page size limit. This prevents performance degradation for queries that do not access the large columns, though it can increase I/O overhead when those large columns are actually retrieved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c24dcd0-a803-4cf2-9ad7-c4335823bdfa', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do ''Retries with Exponential Backoff'' help system stability?', N'Middle', N'This strategy prevents a system from overwhelming a failing service by increasing the wait time between successive retry attempts. It helps avoid a ''thundering herd'' problem where many clients simultaneously hammer a recovering service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e5d20e0-858a-4f68-9679-c434129e12e3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary difference between a ''term'' query and a ''match'' query in Elasticsearch?', N'Middle', N'A term query performs an exact match search against the inverted index, meaning it does not analyze the search string. In contrast, a match query processes the input string through the same analyzer used during indexing, enabling full-text search capabilities like tokenization and normalization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e75cf234-8b58-471d-806c-c436a0741a59', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the ''createEffect'' primitive?', N'Intern', N'The createEffect function is used to create side effects that depend on signals. It automatically tracks any signals accessed inside its callback and re-runs whenever those specific signals change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df30404b-8a79-428d-8589-c436f64dd027', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''Mapped Types'' and their utility.', N'Middle', N'Mapped types allow you to create new types by transforming the properties of an existing type. They are highly useful for creating variations of object structures, such as making all properties optional or read-only, without manually redefining the interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79b56fcc-83b8-4626-b66d-c4395a14f617', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does it mean for a reducer to be pure?', N'Intern', N'A pure function always returns the same output for the same input and does not cause side effects. In Redux, this means you should not modify the existing state directly but rather return a new object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c219c3d-8acd-457e-b8e9-c43d60e6c57b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the ''Voter'' interface improve authorization logic compared to standard annotations?', N'Middle', N'Voters provide a flexible, object-oriented way to implement complex authorization logic that depends on the state of the object being accessed. Unlike static annotations, they can handle multi-layered permissions and are easily unit-tested in isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d7b7184-cb7a-44da-9f7b-c43da5457a9d', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'When should you avoid caching entirely?', N'Middle', N'Caching should be avoided for highly sensitive data that must always be accurate, or for data that changes with every single request. Adding a cache layer in these scenarios introduces unnecessary complexity and potential for consistency bugs without providing any performance benefits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52089810-90e4-483e-83ba-c43db385232c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why might you choose Redis over a disk-based NoSQL database like MongoDB?', N'Junior', N'You would choose Redis when your primary requirement is extreme speed and low latency, or when you are using it specifically for caching or transient data. MongoDB is better suited for storing large volumes of persistent, complex documents that require more advanced query capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50811ac7-5620-4f8d-a6fa-c4401b74392a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What does ''asynchronous'' mean in the context of the Litestar framework?', N'Fresher', N'Being asynchronous means Litestar can handle multiple network requests concurrently without blocking the execution thread. It leverages Python''s ''asyncio'' library to perform I/O-bound tasks efficiently, improving the overall throughput of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65c0f72d-f232-461d-86c0-c443a1d8079c', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s ''Helpers'' differ from ''Components'' in terms of rendering logic?', N'Senior', N'Helpers are intended for simple, stateless transformations of data within templates, whereas components are designed to manage state, DOM interaction, and lifecycle logic. Using a component for simple data formatting introduces unnecessary overhead, while using a helper for complex logic makes the code difficult to maintain and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94aec46c-4429-4f05-a217-c443bc17be36', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you distinguish between ''effort'' and ''duration'' when estimating a project task?', N'Fresher', N'Effort represents the total amount of person-hours required to complete the work itself, regardless of who does it or when. Duration is the actual elapsed time from the start to the finish of the task, which is influenced by availability, dependencies, and external factors. Understanding this distinction prevents errors where total effort is mistakenly equated to project timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e428e6b0-1e7a-4e0c-b362-c4444d2a31c7', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C memory model handle the visibility of writes across threads?', N'Senior', N'C does not have a formal memory model in the language standard prior to C11; visibility depends on the underlying hardware and OS-level memory barriers. C11 introduced atomic types and memory ordering constraints to provide a portable way to ensure synchronization between concurrent threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'327cffb0-26db-4114-a121-c445b96c8e45', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Can Actix-web perform blocking operations?', N'Junior', N'Yes, but blocking operations should be moved to a dedicated thread pool using ''web::block''. This prevents the main asynchronous event loop from stalling, which would otherwise stop the server from processing other incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86a7a510-ba1c-458c-9d5b-c447e4e5fc37', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What role does intuition play in engineering problem-solving?', N'Intern', N'Intuition is a useful starting point derived from past experience that helps generate potential hypotheses quickly. However, it should always be followed by rigorous verification and data analysis to ensure the instinctive conclusion is logically sound.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fd64f3d-96eb-4454-b883-c447f5367301', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the register storage class specifier influence the compiler?', N'Middle', N'The register keyword is a hint to the compiler that a variable will be frequently accessed and should ideally be stored in a CPU register rather than memory. In modern compilers, this keyword is largely ignored as the compiler''s optimization algorithms are usually much better at deciding which variables to keep in registers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82c1a276-3484-4134-939a-c44aeb21db0b', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do you manage client-side state in an environment where the page transitions are mostly server-rendered?', N'Senior', N'For global state that must persist across page navigations, developers typically use React Context or external libraries like Zustand. However, because the server-rendered HTML is the source of truth, state synchronization must account for the difference between the initial server state and subsequent client updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
