INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2a09dbb-b021-4672-9700-c4534800a453', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does ''Ember''s strict adherence to conventions'' affect the onboarding and maintenance of large-scale applications?', N'Senior', N'Conventions reduce decision fatigue by providing a ''standard'' way to solve common problems like directory structure, naming, and data flow. For large applications, this ensures that any developer can understand the codebase quickly, as the architectural patterns are consistent throughout the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bab2e1a-cf4b-4ee6-bfbf-c456e77d7fb9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the role of documentation in a software project?', N'Intern', N'Documentation serves as a knowledge bridge for current and future team members. It explains how to set up, use, and maintain the system, reducing the time spent on onboarding and preventing knowledge silos.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19b7c6db-4780-4411-84c5-c45988307902', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the AdonisJS ''config'' directory?', N'Intern', N'The config directory contains configuration files for various parts of the application, such as the database, authentication, and session management. These files allow you to change the behavior of framework features without modifying the core code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34c2972f-92c0-4460-b6bf-c45bd772ddd6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''declaration'' flag impact the distribution of libraries, and what are the associated build costs?', N'Senior', N'Generating declaration files is necessary for library consumers to benefit from static typing, but it adds processing overhead to the build pipeline as the compiler must map source AST nodes to public declarations. This cost is compounded in large projects and necessitates careful management of include/exclude patterns to keep build times acceptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a3ad464-af04-4ff4-9dbe-c46174172739', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra considered ''Write Optimized''?', N'Intern', N'Cassandra is write-optimized because it treats all writes as an append-only operation to the CommitLog and Memtable. This avoids expensive random disk seeks during the write process, allowing for very high write throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7398fecb-fb81-440a-8cfe-c461e1dd07ad', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach API versioning when breaking changes are necessary?', N'Middle', N'I prefer using URI versioning or header-based versioning to allow clients to migrate at their own pace. I would maintain the old version for a defined deprecation period while providing clear documentation and automated migration guides for consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b445a49d-7d1b-4e93-b1a2-c462ac63140b', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does scalability affect technical trade-offs?', N'Intern', N'Designing for scalability often requires adding layers of abstraction or distributed systems, which increases complexity. If the project''s current user base is small, the trade-off of higher complexity might not be justified until the growth requires it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0ad3854-2339-44c6-bc8c-c463ca9006d4', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the architectural challenges of migrating a large jQuery-based application to a modern framework?', N'Senior', N'The primary challenge is the tight coupling between logic and DOM structure, which makes it nearly impossible to extract business logic into framework-agnostic services. This usually necessitates a complete rewrite, as the imperative nature of jQuery is fundamentally incompatible with the declarative nature of modern component-based architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a69632d-46ca-477e-b476-c467237b0cb5', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the ''PropertyAccess'' component abstract data manipulation in Symfony?', N'Senior', N'PropertyAccess provides a unified interface to read and write data to objects or arrays, regardless of their internal structure or access modifiers. This abstraction is essential for components like Forms and Serializers, as it allows them to interact with diverse data structures through a consistent API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25b9f01b-a5ea-4c1e-ba8c-c46940ab0d1e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s inline function mechanism impact binary size and performance in large-scale applications?', N'Senior', N'Inlining functions avoids the overhead of object allocation for function literals and allows the compiler to integrate the function body directly into the call site. While this improves performance by reducing stack frame creation, excessive inlining can lead to significant binary bloat and increased instruction cache misses, potentially degrading performance in memory-constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ea2fb1a-cfba-403e-a617-c470d579f687', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the primary difference between value types and reference types?', N'Intern', N'Value types, such as structs and enums, are copied when passed around, ensuring each instance has its own unique data. Reference types, such as classes, share the same instance, so changes made in one place are reflected everywhere that instance is referenced.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89549eee-bbde-485a-84ed-c475996af597', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi improve upon the default ServeMux?', N'Intern', N'While the default ServeMux is limited, Chi offers advanced routing features like URL parameters, regex matching, and built-in middleware support. It provides a more powerful and flexible API for complex web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af6f392a-006c-41ff-8562-c47bf292090f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the purpose of the ''Recoverer'' middleware commonly used with Chi?', N'Middle', N'The Recoverer middleware is designed to prevent the entire server from crashing when a handler panics. It catches the panic, logs the stack trace, and returns a 500 Internal Server Error response, ensuring the application remains resilient and available for other requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91e64e3f-8f00-4a0b-9e74-c47c1ece2766', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''...'' (ellipsis) argument in R?', N'Middle', N'The ellipsis allows functions to accept an arbitrary number of arguments and pass them along to other functions. It is essential for wrapper functions or methods that need to remain flexible without explicitly defining every possible parameter of underlying functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0142a316-e9f0-4bfe-8ab8-c47c7a354ac9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing for fault tolerance, what are the trade-offs between active-active and active-passive failover?', N'Senior', N'Active-active configurations provide instant failover and better resource utilization, but they require complex data replication and conflict resolution. Active-passive is much simpler to implement and ensures data integrity but results in downtime during the failover transition and wastes idle standby capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef214c96-dfee-4559-bd3e-c47efb7cf3ad', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of a database constraint?', N'Intern', N'Constraints are rules applied to columns in a table to limit the type of data that can be inserted. They ensure the accuracy and reliability of the data, such as requiring unique values or preventing null entries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5014b137-1aa4-4484-8ec4-c481fa58c9a3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What factors influence the decision to implement a caching layer versus optimizing the underlying database queries?', N'Senior', N'Query optimization should always be the first step to address efficiency at the source. Caching is then introduced to solve latency issues or to offload heavy read traffic, accepting the trade-off of cache invalidation complexity and potential data inconsistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2af2c9b-2fd6-4347-8c97-c484a653708b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is Axum''s approach to routing?', N'Junior', N'Axum uses a router to map HTTP methods and URI paths to handler functions. It supports nested routing, which allows you to group related routes under a common path prefix for better organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b15943-9deb-40f9-aa6f-c484bb600b5f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle reactivity compared to a Virtual DOM-based framework like React?', N'Intern', N'SolidJS uses fine-grained reactivity based on signals instead of a Virtual DOM. When state changes, Solid updates only the specific part of the DOM bound to that state rather than re-rendering an entire component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa189d51-5310-4f73-b0ad-c48765a564e6', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between nominal and structural typing, and why is TypeScript structural?', N'Senior', N'Nominal typing requires explicit declarations to establish subtyping relationships, while structural typing relies on member parity. TypeScript is structural because it is designed to model the dynamic, duck-typed nature of JavaScript objects, allowing for fluid interoperability with existing libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2db13f8-e2b3-4b0b-9468-c4891c3bfc86', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the trade-offs of using Vuex or Pinia for state management?', N'Middle', N'Centralized state management provides a predictable architecture for large applications and makes debugging easier with tools like time-travel. However, it introduces significant boilerplate and complexity, which can be overkill for small applications that could otherwise rely on simple reactive objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'288602ed-8c65-456e-b20b-c48b0038bbb9', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of a Type Class in Scala, and how does it differ from traditional object-oriented inheritance?', N'Middle', N'A Type Class provides a way to add polymorphic behavior to types without modifying their source code or using class hierarchies. Unlike inheritance, which ties behavior to the object''s type, type classes use implicit evidence to attach functionality, promoting better composition and decoupling in functional design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
