INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05938d6a-b474-4e79-801c-c48e48a732e8', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What does ''type safety'' mean in the context of C#?', N'Intern', N'Type safety ensures that a program accesses only the memory locations it is authorized to access and that operations are performed only on appropriate data types. C# is a strongly typed language, meaning the compiler verifies that operations are valid for the specific type of data involved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b491301-5e98-4e55-97bb-c4abe9990aa5', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony handle environment configuration?', N'Fresher', N'Symfony uses environment variables and configuration files to manage settings that change based on where the application is running. This allows developers to use different database credentials or debug settings for development, testing, and production environments without changing the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c9c14cf-b366-4fbd-ae03-c4acbf362c24', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the concept of ''poison pills'' in a message queue.', N'Middle', N'A poison pill is a malformed message that consistently causes a consumer to crash or fail to process it. Without proper handling, such as moving it to a DLQ, the message will be repeatedly retried, consuming system resources and potentially blocking the queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'813eb2a1-327d-411c-8478-c4ae0108c0bd', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does a <DOCTYPE html> do?', N'Intern', N'A DOCTYPE is always associated to a DTD ( Document Type Definition ). A DTD defines how documents of a certain type should be structured (i.e. a button can contain a span but not a div), whereas a DOCTYPE declares what DTD a document supposedly respects (i.e. this document respects the HTML DTD). For webpages, the DOCTYPE declaration is required. It is used to tell user agents what version of the HTML specifications your document respects. Once a user agent has recognized a correct DOCTYPE, it will trigger the no-quirks mode matching this DOCTYPE for reading the document. If a user agent doesn''t recognize a correct DOCTYPE, it will trigger the quirks mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd06603ce-7d36-49ff-8209-c4aeb4491bc5', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of the ''c'' or ''context'' object in Hono?', N'Intern', N'The context object is a central interface passed to every Hono handler. It provides methods to access request data, send responses, set headers, and manage state throughout the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce966948-8334-496b-ab46-c4b2f284e2a4', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Discuss the benefits of AdonisJS ''Config'' management.', N'Senior', N'The config system provides a centralized way to manage environment-specific variables and application settings. By utilizing an environment loader, it ensures that sensitive credentials remain outside the codebase, facilitating secure deployments across staging and production environments without changing the underlying application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90b8c930-3d92-4833-aa9e-c4b2f60c57c6', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is it important to use the ''goto'' helper instead of standard anchor tags in some cases?', N'Middle', N'The ''goto'' helper allows for programmatic navigation that integrates with SvelteKit''s client-side router, enabling faster transitions without a browser refresh. Standard anchor tags work for basic links, but ''goto'' is essential when you need to perform logic or state changes before changing the route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'454b0759-a69b-4d95-9615-c4b32260b095', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the useReducer hook in React and when should it be used?', N'Fresher', N'The useReducer hook in React is used for managing complex state logic in functional components. It is an alternative to useState and is particularly useful when the state has multiple sub-values or when the next state depends on the previous one. It takes a reducer function and an initial state as arguments and returns the current state and a dispatch function. Use useReducer when you have complex state logic that involves multiple sub-values or when the next state depends on the previous state. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dc6d2df-13c3-4ba7-98cc-c4b75b8cdda6', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle the ''props vs attributes'' distinction compared to modern frameworks?', N'Senior', N'jQuery frequently conflates HTML attributes and DOM properties, which can cause unexpected behavior when dealing with stateful elements like checkboxes or inputs. Modern frameworks maintain a clear separation, ensuring that property updates correctly reflect the desired state without side effects on attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0ec7784-547a-4c94-8c8c-c4b867f287f3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Discuss the trade-offs of using Entity Framework Core versus Dapper in a high-throughput ASP.NET Core application.', N'Senior', N'EF Core provides high developer productivity and abstraction but can introduce overhead due to its tracking and query generation mechanisms. Dapper is a lightweight micro-ORM that offers near-native performance by mapping raw SQL results to objects, making it preferred for performance-critical read paths at the cost of more manual query management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9133a37-af2d-426f-b279-c4b9eeff069e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do you access route parameters in Fastify?', N'Intern', N'Route parameters are accessed through the params property of the request object. If a route is defined with a dynamic segment, Fastify automatically maps that segment to the corresponding key in the params object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b906d54-908e-43f4-80b7-c4bc5937c3a7', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Compare Kotlin''s sealed classes with traditional Java enums regarding architectural scalability.', N'Senior', N'Sealed classes provide a restricted class hierarchy that allows each instance to hold state and have unique behavior, whereas enums are strictly singleton-based and limited in state management. This makes sealed classes significantly more scalable for complex state modeling, such as representing result patterns or finite state machines in reactive systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49b6d093-d3e5-4dc6-8307-c4c177572de6', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s reactivity model differ from React''s state management?', N'Middle', N'Svelte uses a compiler-based reactivity model where variable assignments are intercepted during build time to trigger DOM updates. In contrast, React relies on runtime reconciliation and a virtual DOM to detect changes, leading to different performance characteristics and developer experiences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a3835fb-8c84-424f-9e3c-c4c48607e3ce', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite support Server-Side Rendering (SSR)?', N'Middle', N'Yes, Vite provides first-class support for SSR. It allows you to transform code for the server environment and provides utilities to load and bundle components, which can then be rendered to strings or streams on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76654038-e8a5-4c5a-8aad-c4c52891a63d', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Three-Phase Commit'' (3PC) protocol improve upon the two-phase commit protocol?', N'Senior', N'The Three-Phase Commit protocol introduces a ''pre-commit'' phase that separates the decision to commit from the actual commit action. This removes the blocking nature of 2PC, as nodes can reach a consensus even if the coordinator fails, provided a majority of participants remain online.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a268c49-cc97-4602-8655-c4c783866f13', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Describe the impact of the 400KB item size limit on database design.', N'Senior', N'The 400KB limit forces developers to offload large binary data or documents to Object Storage like S3, storing only the metadata or pointers in DynamoDB. This constraint encourages granular data modeling and prevents single-item operations from becoming latency bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e10b798-9533-4222-b23f-c4c7c14e629e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage your time when you realize a task is taking longer than you initially estimated?', N'Intern', N'I would reassess the remaining work and communicate the delay to my manager as soon as possible. Being proactive about delays allows the team to adjust timelines or provide additional support before the final deadline is missed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4f587b8-f16c-44fb-9801-c4c7c956b0a1', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the ''Poison Pill'' message scenario and how to mitigate it.', N'Senior', N'A poison pill is a malformed message that consistently causes consumer crashes or processing failures, blocking the queue. Mitigation involves implementing a Dead Letter Queue (DLQ) where such messages are routed after a fixed number of failed retry attempts, allowing the system to continue processing subsequent valid messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ed04749-9c36-4f56-8c64-c4c9aeed9314', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is testing FastAPI applications easier compared to synchronous frameworks?', N'Middle', N'FastAPI provides a ''TestClient'' based on the standard library''s ''requests'' module, which allows you to test endpoints without running a live server. Its dependency injection system also makes it trivial to swap out real database connections or external services for mocks during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2847d6dd-941c-4d26-812b-c4ca87886814', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the primary purpose of the Ember CLI?', N'Intern', N'Ember CLI is the command-line interface tool for Ember applications. It is used to generate project structures, manage dependencies, run local development servers, and handle the build process, ensuring consistency across all Ember projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8fdbbf7-ad31-4d66-abac-c4cb1e86715e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the function of the @property decorator?', N'Fresher', N'The @property decorator is used to declare reactive properties in a Lit component. When a property marked with this decorator changes, Lit automatically triggers an update cycle to reflect the new value in the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bdbf79e-c46c-40e2-b2a9-c4cbded06656', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What does ''two-way data binding'' mean in Ember?', N'Intern', N'Two-way data binding means that changes made to the data in the JavaScript code are automatically reflected in the UI, and changes made by the user in the UI are automatically updated in the JavaScript data. This keeps the application state and the view in sync.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
