INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3650a578-d549-4682-afb0-c4cd4cec2f9a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Discuss the performance implications of deep state nesting in a Redux store.', N'Senior', N'Deeply nested state increases the complexity of immutable update logic, often requiring verbose spread operations that are prone to errors. Furthermore, it complicates shallow equality checks in selectors, leading to unnecessary re-renders that can degrade performance in complex UI trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd46d1ce9-8e71-4674-add7-c4cd61c7bf36', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''List'' and ''Array'' in Scala?', N'Fresher', N'A List is a linked list that is immutable and optimized for functional programming patterns. An Array is a mutable, fixed-size data structure that maps directly to primitive arrays in the JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3284c32-159f-4546-a283-c4cd723d4b6c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the main difference between Vite and traditional bundlers like Webpack?', N'Fresher', N'Traditional bundlers process your entire application before starting the development server, which can lead to slow startup times as the project grows. Vite leverages native ES modules in the browser to serve files on demand, allowing the development server to start almost instantly regardless of the project size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db1952aa-e632-4e5d-aebe-c4ce72b52d79', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does the ''target=_blank'' attribute pose a security risk, and how can it be mitigated?', N'Middle', N'Using ''target=_blank'' allows the newly opened page to potentially access the original page via the window.opener property, which can lead to performance issues or phishing attacks. This is mitigated by adding ''rel=noopener'' or ''rel=noreferrer'' to the anchor tag. These attributes prevent the new page from accessing the origin, ensuring a secure browsing experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58cb0d49-70f4-4bc3-ada9-c4cf2a2a2638', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What strategies can be employed to manage transactions across multiple microservices?', N'Senior', N'Managing transactions across multiple microservices presents certain challenges, primarily due to the principles of independence and isolation that microservices are designed around. However, there are both traditional and modern strategies to handle multi-service transactions, each with its own benefits and trade-offs. Traditional Approaches Two-Phase Commit (2PC) Two-Phase Commit is a transaction management protocol in which a global coordinator communicates with all participating services to ensure that the transaction can either be committed globally or rolled back across all involved services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fef689b-8804-40db-9f8c-c4cf55295ea5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'When should you implement an external job queue like Oban instead of using internal processes?', N'Middle', N'You should use an external queue when tasks need to persist across application restarts or require sophisticated features like retries, scheduling, and rate limiting. While internal processes are great for immediate concurrency, they disappear if the node crashes, making them unsuitable for critical background jobs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999aea13-6978-45ad-805e-c4d1d732fb3f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of a database schema?', N'Fresher', N'A schema is the formal definition or blueprint of the database structure. It defines how data is organized, including table names, column data types, and the relationships between tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3685000-f206-40a2-bb5e-c4d2d8f26e0f', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does the CAP theorem influence the design of highly available stateful systems?', N'Senior', N'In the event of a network partition, you must choose between consistency and availability. For systems requiring high reliability, designers often opt for eventual consistency models or consensus algorithms like Raft or Paxos to maintain a balance between data integrity and service uptime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'777fece8-4d41-483b-9710-c4d4462c7b64', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you define a route that accepts multiple HTTP methods?', N'Junior', N'Fiber allows you to define a route using a specific method-based function, or you can use a generic method that accepts a slice of HTTP verbs. This is useful when the same handler logic needs to respond to both GET and POST requests for a single endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'175fc81c-d2ac-49c0-9f68-c4d4a6593710', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are data classes in Kotlin and when should they be used?', N'Fresher', N'Data classes are classes primarily used to hold data. When declared, the compiler automatically generates standard functions like equals, hashCode, and toString based on the properties defined in the primary constructor, making them ideal for representing models or states in an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7de78829-2efb-44fd-bf37-c4d5082aafd9', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'If Node.js is single threaded then how it handles concurrency?', N'Middle', N'Node js despite being single-threaded is the asynchronous nature that makes it possible to handle concurrency and perform multiple I/O operations at the same time. Node js uses an event loop to maintain concurrency and perform non-blocking I/O operations. As soon as Node js starts, it initializes an event loop. The event loop works on a queue (which is called an event queue) and performs tasks in FIFO (First In First Out) order. It executes a task only when there is no ongoing task in the call stack. The call stack works in LIFO(Last In First Out) order. The event loop continuously checks the call stack to check if there is any task that needs to be run. Now whenever the event loop finds any function, it adds it to the stack and runs in order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'397b927b-0e5b-4ab2-b686-c4d63e6190d4', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the ''Logger'' in Fastify?', N'Intern', N'Fastify includes a built-in, high-performance logger based on the Pino library. It is designed to be non-blocking and efficient, allowing developers to track application events and errors without significantly impacting the server''s performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26ca63a7-928e-4640-94fc-c4d6c5b58112', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the middleware pipeline work in ASP.NET Core?', N'Middle', N'Middleware components are executed in the order they are added to the request pipeline. Each component can perform work before and after the next component in the chain, effectively wrapping the request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a45eb107-cade-4c73-be8d-c4db80fd234f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is reactivity in the context of SolidJS?', N'Fresher', N'Reactivity in SolidJS refers to the ability of the framework to automatically track dependencies between state and the DOM. When a piece of reactive state changes, only the parts of the application that depend on that specific state are updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1c2b160-79ea-46e6-9fe0-c4dd2f56041f', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the purpose of the InnoDB Buffer Pool and why it is critical for performance.', N'Middle', N'The Buffer Pool is a memory area where InnoDB caches table and index data as it is accessed. Keeping frequently used data in RAM significantly reduces disk I/O operations, which is the primary bottleneck in database performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
