INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76836456-c3fe-4e81-94ca-c4e82ded49c8', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of the Django template context processor?', N'Middle', N'Context processors are functions that take a request object as an argument and return a dictionary of variables to be added to the template context. They are used to make data available to every template globally, such as user authentication status or site settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd98f0ed9-898a-4575-908c-c4e8e8a5e109', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''GOMAXPROCS'' setting and how does it affect scheduling?', N'Senior', N'GOMAXPROCS determines the number of operating system threads that can execute user-level Go code simultaneously. Setting this value higher allows for greater parallelism on multi-core systems, but excessively high values can lead to increased context-switching overhead. It fundamentally defines the number of P structures that can be active at any given time, limiting the concurrency throughput of the Go scheduler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fb29969-6a6c-45f9-ab75-c4f2dfa3301a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is dependency injection in Micronaut?', N'Fresher', N'Dependency injection is a design pattern where an object''s dependencies are provided by the framework rather than the object creating them itself. Micronaut manages these dependencies through its inversion of control container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d4956d4-8ccb-4174-9a8b-c4f46bcf984a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the difference between @Singleton and @Prototype?', N'Intern', N'@Singleton ensures that only one instance of a bean is created for the entire application. In contrast, @Prototype creates a brand new instance of the bean every time it is injected or requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e3d64b1-79f8-4f0a-baab-c4f6ba162bbb', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between HTML and XHTML?', N'Fresher', N'The Extensible Hypertext Markup Language, or XHTML, has two important notes for front end developers. 1) It needs to be well formed, meaning all elements need to be closed and nested correctly or you will return errors. 2) Since it is more strict than HTML is requires less pre-processing by the browser, which may improve your sites performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'777125c3-d81d-42c2-956a-c4f9c1b522e2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the use of rel="nofollow", rel="noreferrer", rel="noopener" attribute?', N'Fresher', N'1. rel="nofollow" When rel="nofollow" tag is used, it instruct the search engines not to pass any PageRank from one page to the other. It does not allow it to pass the authority to the specific website. The main advantage of using this attribute is to control the spam attack. There may be times, when you do not have control over what people publish on your websites, for example some blog comments and some kind of forum posting. Example: 2. rel="noreferrer" Noreferrer is related to analytics and tracking. The referrer value shows the previous page where a user came from. By using the noreferrer attribute on a link, you are preventing other pages from seeing that traffic came from a click on your link. Example: 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec115942-ecc2-476b-b398-c4fb69271675', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik support component-based architecture?', N'Fresher', N'Yes, Qwik follows a component-based architecture similar to other modern frontend frameworks. Developers can build reusable UI components that encapsulate their own logic, state, and styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'142e66f9-84f5-4262-8685-c4fddbd9fd66', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the ''subscribe'' method?', N'Fresher', N'The subscribe method allows you to register a callback function that will be executed whenever an action is dispatched and the state changes. It is the mechanism that allows the UI to listen for updates from the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99ad0358-1746-4dc1-9127-c4ff972da0bc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s singleton class (eigenclass) model facilitate method dispatch for individual objects?', N'Senior', N'The singleton class acts as an invisible, anonymous class that sits between the object and its actual class in the lookup chain. When a method is defined on a specific instance, it is stored in this singleton class, ensuring that the modification remains unique to that object without impacting other instances of the same class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
