INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77020546-0378-402f-b67c-c5045638393e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Compare the maintainability of Tailwind''s ''apply'' directive versus keeping utility classes directly in the markup.', N'Senior', N'Using the ''apply'' directive creates a tighter coupling between HTML and CSS, effectively recreating the maintenance overhead of traditional CSS classes. Keeping utilities in the markup is generally preferred for maintainability because it makes component behavior immediately transparent, whereas ''apply'' hides logic inside CSS files, complicating the debugging process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
