INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'898f3c51-a72f-4b88-864a-c51987250fe2', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the difference between ''ref'' and ''shallowRef'' in the context of performance-critical lists.', N'Senior', N'Ref applies deep reactivity recursively, which can be computationally expensive for large arrays or objects. ShallowRef tracks only the reference, making it significantly more efficient for large data sets that do not require deep reactivity or are treated as immutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
