INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'469aa63c-b64d-4744-ad69-c52391a01e99', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are Micronaut Beans?', N'Intern', N'Beans are objects that are instantiated, assembled, and managed by the Micronaut inversion of control container. They are typically defined using annotations, allowing the framework to track and provide these objects wherever they are needed in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8db0924-a605-47e3-a26d-c524af0a4adb', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix PubSub?', N'Intern', N'PubSub stands for Publish and Subscribe. It is a messaging mechanism that allows different parts of an application, or even different nodes in a cluster, to communicate by broadcasting messages to specific topics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbea683d-1804-493a-a4f6-c526d81a2d46', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are Nuxt modules?', N'Intern', N'Nuxt modules are extensions that allow you to easily add new features or integrations to your application. They can handle tasks like connecting to external APIs, adding authentication, or optimizing images without writing complex configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb03e7ce-8627-44a8-9c28-c526fc868d8e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Discuss the trade-offs between using Global Guards vs. Controller-scoped Guards in a complex authorization flow.', N'Senior', N'Global guards ensure consistent security policies across the entire application but can be difficult to override for specific public endpoints. Controller-scoped guards offer higher granularity and better adherence to the principle of least privilege, though they risk configuration drift if authorization requirements evolve unevenly across modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26a5f0ee-5c88-4eb5-9e7a-c526fd0dede3', N'a2838158-7305-480a-b22b-4dc35776b400', N'How do you handle schema evolution in a distributed system where services may be running different versions of the code?', N'Senior', N'Schema evolution is managed by ensuring backward and forward compatibility, typically through techniques like additive changes only, using flexible formats like Protobuf or Avro, and implementing contract testing. Deploying with a ''expand and contract'' strategy allows services to handle multiple versions of a schema during the transition period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b083b34-3eb2-45ce-8c46-c52722336a62', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is horizontal scaling in NoSQL databases?', N'Intern', N'Horizontal scaling, or scaling out, is the process of adding more servers or nodes to a database cluster to handle increased traffic. This is a primary benefit of NoSQL, allowing the system to distribute data across multiple machines rather than just increasing the power of a single server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4813f4ca-c40d-45a8-be35-c527a5c8d84b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What does ARC stand for and how does it work?', N'Junior', N'ARC stands for Automatic Reference Counting, which is Swift''s memory management mechanism. It automatically tracks the number of references to class instances and deallocates memory when the reference count drops to zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8cb5362-ac36-449b-a5d7-c52a73d69e50', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core manage environment-specific configurations?', N'Middle', N'ASP.NET Core uses the ''ASPNETCORE_ENVIRONMENT'' variable to load different configuration files, such as ''appsettings.Development.json'' or ''appsettings.Production.json''. This allows developers to maintain separate settings for different stages of the deployment pipeline without changing code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac893d06-f400-4153-b723-c52b53ea008a', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi differ from the standard library''s ServeMux?', N'Fresher', N'While the standard library ServeMux is simple, Chi provides more advanced routing features like URL parameters, regex matching, and middleware chaining. It is built to be fully compatible with the standard library''s http.Handler interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7066b7cd-3426-4775-812e-c52e1235ab4a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle configuration management?', N'Intern', N'Micronaut uses a hierarchical configuration system that allows properties to be loaded from various sources, such as files, environment variables, or system properties. This system makes it easy to manage different settings across development, testing, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3748414-560b-41cc-87bd-c531f7b9f14c', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why does Ruby not support multiple inheritance, and how is this handled?', N'Middle', N'Multiple inheritance is avoided to prevent the Diamond Problem, where ambiguity arises from conflicting methods in parent classes. Ruby handles this limitation through mixins using modules, which provide a linearized method lookup path. This ensures that the order of precedence is always deterministic and easy to trace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcde3298-50e3-47d0-9f39-c5361eff240d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the section element?', N'Junior', N'The section element represents a generic, thematic grouping of content within a document. It helps organize the page into logical parts, typically with a heading for each section.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58451bce-0db1-46a5-9c0c-c53652a98f57', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why is structural subtyping useful, and how is it implemented in Scala?', N'Middle', N'Structural subtyping allows a method to accept any object that possesses a specific set of members, regardless of the object''s class hierarchy. In Scala, this is implemented via structural types using refinement syntax, providing flexibility at the cost of potential runtime reflection overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e9acfbe-3d7e-4610-9502-c536cad7342d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it important to use a custom HTTP error handler in an Echo application?', N'Middle', N'A custom error handler allows for centralized management of all application errors, ensuring that the client receives consistent, properly formatted error responses regardless of where the error occurred. It prevents sensitive stack traces or internal implementation details from leaking to the client while logging the detailed error for backend monitoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
