INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30bfe326-62ca-46de-a692-c53cdedb8e3f', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the architectural benefit of ''Eventual Consistency'' for system reliability?', N'Senior', N'Eventual consistency allows services to operate independently without waiting for synchronous cross-service writes. This minimizes the impact of transient network issues and increases system throughput, sacrificing immediate consistency for higher resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e86143a-2058-4ccb-9594-c53cefdf5084', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of Ember Engines, and in what architectural scenarios should they be used?', N'Senior', N'Ember Engines allow you to split a monolithic application into smaller, independently mountable applications. They are ideal for large-scale enterprise projects where different teams need to own specific features or modules that require separate routing, services, and dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26f9e276-c4e2-4b70-9d0e-c53e0c52b733', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a replica in Elasticsearch?', N'Intern', N'A replica is a copy of a primary shard used for data redundancy and high availability. If a node fails, replicas ensure that the data remains accessible and can be used to handle search requests to improve throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8ca8e4b-f398-4cc9-9144-c53fd3dabfb4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser handle style invalidation when applying dynamic class changes?', N'Senior', N'When a class is added or removed, the browser triggers a style invalidation process that marks affected elements as dirty. It then performs a style recalculation pass, checking only the affected subtrees to update the computed styles before the next paint cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e192b8-f71d-4b77-b419-c54787d30b64', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a session in PHP and why is it used?', N'Fresher', N'A session is a way to store information across multiple pages for a single user. It works by creating a unique session ID stored on the server, which allows the application to remember user data like login status or preferences while the user navigates the site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
