INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0c9bea1-6cc7-4109-82ec-c551b85358c6', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the concept of ''Islands Architecture'' in Astro?', N'Intern', N'Islands Architecture is a pattern where the majority of a page is rendered as static HTML, and only specific, interactive components are hydrated with JavaScript. This approach keeps the rest of the page lightweight and non-interactive, significantly improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4334f485-8deb-4438-8b0f-c551bafa8765', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If two team members disagree on which technology to use for a small internal tool, how would you resolve the conflict?', N'Fresher', N'I would suggest creating a list of requirements for the tool and evaluating each technology based on factors like ease of use, team familiarity, and the availability of documentation. If the conflict remains, I would propose building a small proof-of-concept for both options to see which performs better in practice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd42551cc-c9a4-42bb-afc4-c5522ede64b0', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do Rails callbacks (before_save, after_create, etc.) impact performance and system design?', N'Middle', N'Callbacks provide a convenient way to trigger logic based on lifecycle events, but they can hide side effects and make debugging difficult as the object lifecycle grows. Overuse can lead to performance degradation, especially if callbacks trigger external network requests or complex background jobs that block the primary execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81fc07d5-177a-4a37-9bec-c55287be1900', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle dependency resolution?', N'Middle', N'Webpack resolves dependencies by looking at the import/require statements and traversing the dependency graph starting from the entry point. It uses the ''resolve'' configuration to determine how to find files, including setting extensions to check and aliases to simplify complex import paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e32b08df-420f-4a00-867d-c55363d57617', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle reactivity compared to a framework that uses a Virtual DOM?', N'Middle', N'Alpine.js uses a proxy-based reactivity system that tracks state changes directly on the DOM elements. Instead of diffing a virtual tree, it updates specific DOM nodes when the underlying data changes, which is highly efficient for smaller-scale state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eeed46b-ca59-481e-bc78-c553efeb8250', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''Thundering Herd'' problem, and how do you prevent it?', N'Senior', N'The thundering herd problem occurs when a large number of processes wake up simultaneously to request a resource that has just become invalid or available, potentially crashing the backend. It is prevented by introducing jitter (randomized delays) in retries, using distributed caching with lock-free updates, or using request collapsing so that only one process fetches the data while others wait.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59249437-0727-49fe-a5ea-c55777cb57d9', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''Split'' architecture in Dart''s compilation pipeline support cross-platform development?', N'Senior', N'The pipeline is split into a front-end that produces a common kernel representation and a back-end that targets specific platforms like Dart VM, AOT, or JS. This abstraction allows the language to maintain consistent semantics across disparate execution environments while optimizing output for each target.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a6eea61-7712-475f-bd89-c55839662fa6', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are Vite aliases and why are they useful?', N'Fresher', N'Aliases are paths configured in Vite that map short names to specific directory structures. They are useful because they allow developers to import files using clean, readable paths instead of complex relative directory navigation like ''../../../''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936667cb-9579-41fa-9020-c55b08a91fd2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle the lack of a shared memory space in multi-tenant edge environments?', N'Senior', N'Hono relies on the stateless nature of request handling, where state is managed through headers, cookies, or external stores like KV or D1. Since memory cannot be shared across edge isolates, Hono encourages a pure, functional approach to request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
