INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd40138bf-c2c6-4d1b-a15f-c582e7804008', N'954a0331-deff-4399-b588-96f39fec001d', N'What are directives in Angular and can you name a few commonly used ones?', N'Intern', N'Directives in Angular are powerful tools that allow you to extend HTML vocabulary. They attach special behaviors to elements or transform DOM structure and View elements in several unique ways. Types of Directives 1. Component Directives: These are the most common directives. They define components responsible for handling views and logic. 2. Attribute Directives: These modify the behavior and appearance of DOM elements. They are essentially markers on a DOM element that invoke some JavaScript logic. 3. Structural Directives: These are a special type of directives that modify the DOM layout by adding, removing, or manipulating elements. Commonly Used Directives 1. ngIf: This Angular structural directive conditionally adds or removes elements from the DOM tree. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
