INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34b9de7f-4361-4af4-a683-c58b9171744f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does the descriptor protocol function as a foundational element of Python''s object model?', N'Senior', N'Descriptors are objects that define how attribute access is managed through the __get__, __set__, or __delete__ methods. They are the underlying mechanism for properties, methods, static methods, and class methods. By implementing this protocol, developers can intercept attribute access to enforce validation or implement lazy evaluation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5fbd6c8-a5c9-4ac7-9638-c58ba76b0261', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is it recommended to avoid ''SELECT *'' and large partition scans?', N'Senior', N'Large partition scans force the coordinator to query multiple nodes and aggregate massive amounts of data in memory, which can lead to high latency and garbage collection overhead. Efficient queries should always utilize the partition key to hit a specific node and limit the scope of the scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c335385-9fda-4c34-bea3-c58bb2f455b3', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the role of a service discovery mechanism in microservices?', N'Middle', N'Service discovery allows microservices to find each other''s network locations dynamically without hardcoding IP addresses. It is essential in elastic environments where service instances are frequently created and destroyed, ensuring that clients can always reach available service instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c73501b-a44d-4a46-acc4-c58cb42c4790', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of the ''nitro'' engine in Nuxt 3 and how does it impact deployment architecture?', N'Senior', N'Nitro is a high-performance server engine that enables cross-platform deployment by abstracting the underlying server environment. It allows Nuxt applications to run on edge functions, serverless platforms, or traditional Node.js environments without changing the core application logic, facilitating a truly platform-agnostic architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5e2c9a0-1d21-42a7-aa34-c58d0999ac2d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is meant by ''Request'' and ''Response'' objects in AdonisJS?', N'Intern', N'The Request object provides information about the incoming HTTP request, such as headers and body data. The Response object allows the developer to send data back to the client, such as JSON or rendered HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0be4ba7-62a3-4aa1-a84f-c58d37ed77e1', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does the Radix Tree implementation in Gin''s router impact performance and scalability compared to a standard map-based lookup approach?', N'Senior', N'Gin uses a Radix Tree (or prefix tree) to store routes, which allows for O(k) lookup time where k is the length of the path, significantly outperforming linear searching or full-string map hashing as the number of routes grows. This structure is highly memory-efficient because it shares common prefixes between routes, reducing the memory footprint for applications with large, deeply nested API hierarchies. Furthermore, it naturally handles dynamic path parameters by identifying segments during the traversal without requiring expensive regex evaluation for every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'024fe674-8f3b-40f9-ac49-c58e82c59500', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the Dart runtime ensure type safety in generic classes while maintaining compatibility with erased types?', N'Senior', N'Dart uses reified generics, meaning type information is preserved at runtime. Unlike languages that perform type erasure, Dart allows developers to perform type checks and casts on generic types during execution, providing stronger runtime guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab55b53d-4d4d-4088-8585-c592eb04478a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary difference between an inverted index and a standard B-tree index in relational databases?', N'Middle', N'An inverted index maps terms to the list of documents containing them, which is optimized for full-text search. In contrast, B-tree indexes are designed for range queries and equality lookups on structured data, making them less efficient for keyword-based retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23e4b442-75b8-4197-93ef-c59a6a7e1c68', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage your time when a problem turns out to be much harder than anticipated?', N'Intern', N'I re-evaluate the complexity of the task and communicate the updated time estimate to my supervisor as soon as I realize the original plan is insufficient. I look for ways to break the task down into smaller, deliverable phases. This ensures that I am still making progress and provides transparency to the team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fa101aa-4265-4fc2-ace5-c59af1857036', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is a page component in Next.js?', N'Fresher', N'A page component is the core unit of UI that corresponds to a specific route in your application. It is exported from a file within the app directory and defines what the user sees when they visit that URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'754a482e-9a56-463c-a229-c59b1fec394d', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you handle API rate limiting in a distributed system?', N'Middle', N'Rate limiting in distributed systems is typically handled using a centralized data store like Redis to track request counts across multiple nodes. This ensures that global limits are enforced consistently regardless of which server instance processes the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
