INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd929cbbd-d74f-4ec4-8954-c5a22247f5ae', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a local and a global variable?', N'Intern', N'A local variable is declared inside a function and is only accessible within that specific block. A global variable is declared outside all functions and can be accessed by any part of the program throughout its execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
