INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4088596-f4aa-4523-898f-c5b12686d36e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik support server-side rendering (SSR) and how does it differ from React SSR?', N'Middle', N'Yes, Qwik supports SSR, but it produces ''resumable'' HTML. Unlike React SSR, which requires a full hydration phase on the client, Qwik''s SSR output includes all the information needed for the client to interact immediately without re-rendering components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
