INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9f0c1ac-4e72-4b1c-9bc7-c5b4261931a2', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik ensure that serializable data is handled correctly?', N'Middle', N'Qwik relies on a serialization mechanism that converts complex objects into a format that can be embedded in HTML. Developers must ensure that their state objects contain only serializable data, as functions or non-serializable classes cannot be directly passed through the server-to-client boundary without special handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb0f51d5-4066-4b4e-9c7b-c5b46a9876a8', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the difference between a sidecar and a service mesh in microservices communication?', N'Senior', N'A sidecar is a proxy container deployed alongside an application container to handle cross-cutting concerns like logging and TLS. A service mesh is the infrastructure layer composed of these sidecars, which abstracts service-to-service communication, traffic shaping, and observability from the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cd6968d-262e-4d25-9e07-c5b7c94e0da0', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What mechanism does Phoenix use to prevent ''N+1'' query problems when fetching nested associations?', N'Senior', N'Phoenix leverages Ecto''s preload and join capabilities to fetch associations efficiently. By providing structured ways to batch or pre-join queries, it avoids the overhead of executing individual queries for every association, which is a common performance bottleneck in ORM-based frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b089d81-b35d-41a3-a0f3-c5b90e11be66', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the scalability limitations of the monitor-based synchronization approach in Java?', N'Senior', N'Monitor-based synchronization relies on intrinsic locks that force thread serialization, which becomes a bottleneck in high-concurrency systems. As the number of threads competing for a single monitor increases, the cost of contention and context switching grows exponentially, often favoring lock-free structures or concurrent collection frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f635575d-44f9-460a-8146-c5b9e2331b2f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is MDX in Astro?', N'Junior', N'MDX is a format that allows you to write JSX components directly inside Markdown files. It is useful for adding interactive elements like charts or buttons within content-heavy pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d97c24e-faec-4482-bfb3-c5b9fc92659d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are Read Capacity Units (RCUs) and Write Capacity Units (WCUs)?', N'Junior', N'RCUs measure the throughput for reading data, while WCUs measure the throughput for writing data. These units determine your performance limits and influence the cost of your database operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
