INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61c8fa78-29b2-48a0-b6d2-c5bee48bb585', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a module in Rust?', N'Intern', N'A module is a way to organize code into a tree structure within a crate. It helps manage privacy by allowing you to define which functions or variables are accessible from outside the module, promoting better project structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf9dcf4a-e181-4226-bdff-c5c17c5c4b9e', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js achieve non-blocking I/O despite being a single-threaded runtime?', N'Senior', N'Node.js delegates I/O operations to the operating system kernel or the libuv thread pool, depending on the OS capabilities and the nature of the request. Once the operation completes, a callback is queued in the event loop, allowing the main thread to continue executing other code while the I/O task runs in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10f21d39-d98e-4533-9760-c5c1987aba3e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are assigned a task you do not understand, what is your first step?', N'Intern', N'My first step is to carefully review the task requirements and documentation to identify specific areas of confusion. Once I have isolated the gaps, I would ask clarifying questions to my supervisor or mentor to ensure I have a complete understanding of the expected outcome before proceeding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7e87a7d-c1fb-4bb5-ae89-c5c244e4bcb4', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''reactive declaration'' syntax using the dollar sign label?', N'Fresher', N'The dollar sign label ($: ) is a special syntax in Svelte used to create reactive statements that automatically re-run whenever any referenced variables change. It is primarily used for derived state, where one value depends on the calculation or transformation of other reactive variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
