INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf7b1470-3db7-4b0e-bb0f-c5cc95cf92a9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is native compilation in Quarkus?', N'Fresher', N'Native compilation is the process of converting Java bytecode into a standalone machine-code executable using GraalVM. This results in an application that starts in milliseconds and consumes very little memory, as it does not require a full Java Virtual Machine to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c60c75e6-02f0-4eef-a335-c5ce2289bd3f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the architectural trade-offs between using a Virtual DOM versus direct DOM manipulation in high-frequency update scenarios.', N'Senior', N'The Virtual DOM provides a declarative abstraction that minimizes expensive direct DOM mutations by calculating the difference between states. However, it introduces memory overhead and the cost of tree diffing. Direct manipulation is faster for simple, localized updates but becomes complex and error-prone to maintain as application state scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
