INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b9213b8-748b-4026-984b-c5d09f7be737', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is reflection in Java and why is it a challenge for native compilation?', N'Intern', N'Reflection is a feature that allows a program to inspect or modify its own structure at runtime. It is difficult for native compilation because the compiler needs to know all code paths in advance to optimize the executable; therefore, reflection often requires explicit configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'772be80f-6c54-4b46-9a34-c5d2128ef423', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle the initial page load for better performance?', N'Fresher', N'Qwik achieves high performance by sending fully rendered HTML from the server to the client. Since the HTML already contains all the necessary state information and event triggers, the browser does not need to execute heavy JavaScript logic to make the page functional, resulting in near-instant load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d41639c-8e71-462f-9449-c5d2db6b7d34', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a lambda function, and where would you use it?', N'Intern', N'A lambda function is a small, anonymous function defined using the lambda keyword. Unlike standard functions defined with def, lambdas are typically used for short-lived operations where a formal name is unnecessary for the logic being performed. Distinctive Features Anonymity Lambdas are not bound to a name by default, making them ideal for one-off utility tasks within a localized scope, such as inside a function call. Single Expression Body The body is strictly limited to a single expression. This facilitates brevity but prevents the use of multiple statements, assignments, or complex control flow (like loops) within the function body. Implicit Return There is no explicit return statement; the evaluated result of the expression is returned automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37f85c63-7e15-4010-ba35-c5d59566ab00', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the benefit of progressive enhancement in Remix?', N'Middle', N'Progressive enhancement ensures that the application remains functional even if JavaScript fails to load or is disabled. By relying on native browser behavior for forms and links, Remix guarantees a baseline level of usability while providing a richer experience for users with JavaScript enabled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'462c60aa-1eeb-4efa-ac15-c5d5d31a6894', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''error boundary'' behavior in SolidJS?', N'Senior', N'Error boundaries catch JavaScript errors within their children components during rendering or reactive updates. They allow you to show a fallback UI and prevent the entire application from crashing, providing a robust way to handle unexpected runtime failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2506ff85-b53b-4141-8aab-c5d65d0a668f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary purpose of Elasticsearch in a data architecture?', N'Fresher', N'Elasticsearch is a distributed, open-source search and analytics engine primarily used for full-text search. It is designed to store, search, and analyze large volumes of data in near real-time, making it ideal for log analytics, application search, and operational intelligence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00bbc3cb-3229-4df6-85f9-c5d8b95ff3ca', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the impact of Tailwind on the ''CSS Cascade'' complexity?', N'Senior', N'By using utility classes, Tailwind flattens the cascade, making it easier to predict element behavior. This reduces the likelihood of styles being overridden by unintended global CSS rules or deep selector nesting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'584d007e-6006-459b-839f-c5da9e2b85d4', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is a Spring configuration file?', N'Intern', N'Spring configuration files provide a way to configure Spring applications. These files, often written in XML, contain bean definitions and other configuration elements. Key Elements - Bean Definitions: XML files define beans using bean elements, or annotation-based configurations can be used. - Module Configurations: These files specify Spring modules to use, such as context, mvc, or aop. - External Configurations: XML files can import other Spring configurations, often used in larger projects. Roles and Responsibilities - Central Configuration Repository: Provides a central place for application-specific and infrastructure-level configurations. - Dependency Injection Configuration: Specifies dependencies and how they should be injected into beans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1e5dbdd-268f-49a8-a8ac-c5dbb1a0eb80', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are Python ''packages''?', N'Intern', N'Packages are a way of structuring Python''s module namespace by using dotted module names. They allow for a hierarchical organization of related modules in a directory structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2618c0e-25cc-42f8-bfaa-c5e04a9b0854', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Describe the difference between DynamoDB Streams and Kinesis Data Streams integration.', N'Senior', N'DynamoDB Streams provide a time-ordered sequence of item-level changes within a 24-hour retention period, primarily for triggers or replication. Kinesis Data Streams integration allows for longer retention periods and higher throughput, enabling more complex stream processing at scale. Choosing between them depends on whether you need simple event-driven architecture or high-volume data streaming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'135acfe7-9238-450b-a821-c5e4353245af', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a ''Try'' object and how does it handle errors?', N'Junior', N'A ''Try'' is a container that represents a computation that might either succeed or throw an exception. It uses ''Success'' and ''Failure'' to encapsulate results, allowing for functional error handling instead of try-catch blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31a4407c-663f-44b3-9264-c5eb6c8c46b9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle errors?', N'Intern', N'Fastify includes a built-in error handling mechanism that captures errors during the request lifecycle. You can define a custom error handler to transform errors into appropriate HTTP responses with consistent status codes and error messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b76ed91-b2e4-4cbc-9b23-c5ebc1f2ea9b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of ''Idempotency'' when designing distributed systems?', N'Senior', N'Idempotency ensures that performing the same operation multiple times produces the same result as performing it once. It is critical for ensuring reliable communication over unreliable networks, as it allows services to safely retry failed requests without causing duplicate side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b4a6ba1-aac4-4bd7-86a1-c5ebc9f86059', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose asynchronous communication over synchronous communication between services?', N'Intern', N'Synchronous communication is easier to reason about but can create bottlenecks if one service waits for another to respond. Asynchronous communication decouples services, allowing them to operate independently and improving overall system resilience and responsiveness under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63c52952-58af-4ab7-bd85-c5edec656f94', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the concept of ''Ahead-of-Time'' (AOT) compilation in Micronaut.', N'Fresher', N'AOT compilation refers to the process where Micronaut analyzes the application code during the build phase. It generates metadata and infrastructure code upfront, ensuring that the application does not have to perform expensive reflection tasks while it is running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cae05db9-87bf-4dfb-a2da-c5eeb5cff5c7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go support object-oriented programming?', N'Intern', N'Go is not a traditional object-oriented language because it lacks classes and inheritance. Instead, it uses structs and interfaces to achieve composition and polymorphism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e466d825-ab70-4d99-8a64-c5f19af28215', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Explain the role of the ''static styles'' property in a Lit component.', N'Middle', N'The static styles property is used to define CSS that is shared across all instances of a component. By defining styles here, Lit creates a single Constructible Stylesheet, which is highly efficient because it is parsed only once and shared across multiple instances of the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
