INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a038d61b-126d-45f1-b177-c5ff8b0a38bc', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Compensation Transaction'' in the context of Saga patterns?', N'Middle', N'A compensation transaction is a series of operations designed to undo the effects of a previously completed step in a long-running distributed transaction. It is used in Sagas to maintain eventual consistency when a distributed transaction cannot be rolled back atomically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6ce402b-bf91-4914-bb6e-c60024deab38', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB ensure high availability?', N'Senior', N'High Availability (HA) refers to the improvement of system and app availability by minimizing the downtime caused by routine maintenance operations (planned) and sudden system crashes (unplanned). Replica Set: The replica set mechanism of MongoDB has two main purposes: * One is for data redundancy for failure recovery. When the hardware fails, or the node is down for other reasons, you can use a replica for recovery. * The other purpose is for read-write splitting. It routes the reading requests to the replica to reduce the reading pressure on the primary node. MongoDB automatically maintains replica sets, multiple copies of data that are distributed across servers, racks and data centers. Replica sets help prevent database downtime using native replication and automatic failover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4297df2-21a2-4cc9-bc80-c600db157b6c', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does API rate limiting help in maintaining system stability?', N'Middle', N'Rate limiting restricts the number of requests a user or client can make within a specific timeframe. It prevents abuse, protects backend services from being overwhelmed by spikes, and ensures fair resource distribution among all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
