INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34e83c6a-1d82-4100-8549-c60380fb5a63', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass handle math operations with different units?', N'Middle', N'Sass supports arithmetic operations, but it enforces unit compatibility, such as not being able to add pixels to percentages directly. You must use specific Sass functions like calc() or unit conversion helpers if you need to perform calculations between incompatible units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
