INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd251d7d-34c8-4ed0-a3af-c614d89d5a19', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Does Tailwind impact accessibility negatively due to its utility-first nature?', N'Senior', N'Tailwind does not inherently impact accessibility, but it places the responsibility on the developer to use correct semantic HTML. Since utility classes are purely presentational, developers must ensure they are not using them as a replacement for accessible markup structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31021cd0-be1e-47ed-98e4-c61501ec65b6', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is Alpine.js considered a ''declarative'' framework, and what are the implications for code readability?', N'Senior', N'Alpine is declarative because developers describe the UI state and behavior directly within HTML attributes rather than writing imperative JavaScript to manipulate the DOM. This keeps logic close to the markup, enhancing readability for small features, but it can lead to cluttered HTML templates if the logic becomes too complex for a single tag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
