INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'572e5c0c-2b8c-486d-8d1b-c619ec35fdf4', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do NestJS''s custom lifecycle hooks (e.g., OnModuleInit) aid in graceful service shutdown?', N'Senior', N'Lifecycle hooks allow developers to orchestrate the closing of database connections, message queue consumers, or cache instances during application termination. By ensuring resources are released in the correct order, these hooks prevent data corruption and ensure that pending tasks are completed or safely aborted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
