INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a61e0f38-e015-449d-8e95-c626be4024f4', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a scenario where two microservices need to maintain data consistency without using distributed transactions?', N'Middle', N'I would implement an event-driven architecture using the Saga pattern or transactional outbox pattern to ensure eventual consistency. By using a message broker, I can ensure that events are reliably published and processed by subscribers, providing a way to perform compensating transactions if a step fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
