INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4aee3bc1-5dab-4508-ad42-c633657eabfe', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the primary performance concerns when passing large structures by value vs. by pointer?', N'Senior', N'Passing by value requires copying the entire structure contents onto the stack, consuming stack space and cycles for every member copy. Passing by pointer involves only a single register-sized address copy, which is significantly more efficient for larger data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
