INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03b02924-7240-4045-9cad-c6403ba483f6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s fiber architecture change the way reconciliation works compared to the stack reconciler, and what are the implications for performance?', N'Senior', N'The Fiber architecture introduced a linked-list tree structure that allows the reconciliation process to be split into incremental units of work. This enables React to pause, abort, or prioritize tasks, preventing the main thread from blocking during long-running updates. Consequently, it significantly improves responsiveness by allowing high-priority user interactions to interrupt lower-priority background rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a6bb833-ff18-43b4-962b-c642dec3b3e2', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does the ''publicDir'' option impact asset delivery?', N'Senior', N'The public directory serves static files as-is without undergoing any processing or hashing by Vite. It is ideal for files like robots.txt or icons that must maintain a static URL structure regardless of the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fc56ca1-f7d2-422e-bb0a-c64330442584', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is Fastify''s design choice of using the ''find-my-way'' router beneficial for high-throughput applications?', N'Senior', N'The router utilizes a highly optimized Radix tree implementation, which ensures constant or logarithmic time complexity for route lookups regardless of the total number of defined routes. This avoids the performance degradation seen in regex-based or linear-search routing systems as the API surface grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8592e36d-f8c0-4849-8e8a-c644a24ec60b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is meant by ''eventual consistency'' in a distributed database?', N'Middle', N'Eventual consistency is a consistency model where, given no new updates to a specific data item, all accesses to that item will eventually return the last updated value. It accepts that replicas may be temporarily out of sync to favor system availability and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bdf9bfa-faa4-453a-b2f9-c6494f939299', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the Provider component in React-Redux?', N'Intern', N'The Provider component wraps your entire application and makes the Redux store available to all components within the component tree. It uses React context to pass the store down to any component that needs it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fa72e63-1680-4356-90dc-c64adeb87dde', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary goal of the Astro framework?', N'Junior', N'Astro is designed to build content-focused websites with a focus on performance. It achieves this by shipping zero JavaScript to the browser by default, only loading interactivity when specifically requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcd7731f-fc23-475a-90ed-c64b3533f2ca', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does backpressure manifest in a messaging system, and what are the architectural consequences?', N'Senior', N'Backpressure occurs when data producers outpace consumers, leading to buffer overflows or memory exhaustion within the broker. Architectural solutions include rate-limiting producers, implementing circuit breakers, or utilizing persistent storage to overflow data to disk, which protects system stability at the cost of increased latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d378c8f-19b9-4e13-8923-c64b63ba67ca', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to verify if a variable is an array?', N'Fresher', N'It is possible to check if a variable is an array instance using 3 different ways, 1. Array.isArray() method: The Array.isArray(value) utility function is used to determine whether value is an array or not. This function returns a true boolean value if the variable is an array and a false value if it is not. 2. instanceof operator: The instanceof operator is used to check the type of an array at run time. It returns true if the type of a variable is an Array other false for other type. 3. Checking constructor type: The constructor property of the variable is used to determine whether the variable Array type or not.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ade8a9f-ca40-4792-a16b-c64c7c329c4d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you define and use a function in TypeScript?', N'Fresher', N'When defining a function in TypeScript, you have the following fundamental components to consider: - Function Signature: Comprising the function''s purpose, parameters, type, and return value. - Function Body: Containing the actual operation or series of steps the function will execute. Key Concepts 1) Function Declaration To declare a function, you specify its name, its parameter list, and its return type. If the function doesn''t return a value, you set the return type to void. Here is a code example: 2) Function Expression You can also declare functions using expressions, which involve assigning functions to variables as values. This approach allows you to be more flexible, such as when you''re using callbacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b329d91c-9c87-412c-add9-c64eb91db81e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a database migration in Ruby on Rails?', N'Intern', N'A migration is a feature that allows you to evolve your database schema over time in a consistent and version-controlled manner. Instead of writing raw SQL, developers define changes to the database structure using Ruby, which Rails then applies to the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'474a5bc9-b44c-4c31-ada7-c64f35258305', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''Action Creator'' pattern and why is it preferred over raw object dispatching?', N'Senior', N'Action creators provide an abstraction layer that promotes code reusability, simplifies refactoring, and ensures consistent action structures throughout the application. They centralize the creation logic, making it easier to manage payloads and metadata without exposing the internal implementation details of the action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'665f21e7-7232-42f4-89d6-c65068f30b67', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle errors compared to languages that use exceptions?', N'Intern', N'Rust does not use exceptions for error handling. Instead, it uses the Result type for recoverable errors and the panic macro for unrecoverable errors, which forces developers to explicitly acknowledge and handle potential failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'832a5f07-8444-4625-9b5f-c651d6ffbe2a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does the Lit rendering cycle optimize performance compared to manual DOM manipulation?', N'Middle', N'Lit uses a batching mechanism that schedules updates asynchronously, ensuring that multiple property changes result in only a single render pass. It also employs efficient DOM patching techniques to update only the specific parts of the template that have changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603fa26d-ff92-48c9-9830-c652376e2dfe', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you access URL parameters in an Express route?', N'Junior', N'You can define dynamic segments in a route path using a colon prefix, such as /users/:id. These parameters are then accessible within the request handler through the req.params object. The key used in the route path becomes the property name in the params object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02439441-2fe2-4fc7-877d-c6536245e2e1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure your work is accessible to team members with different levels of experience?', N'Intern', N'I focus on writing clear documentation and using descriptive naming conventions for my work. I try to explain complex problems in simple terms and am always open to answering questions. Making my work easy to understand helps the entire team collaborate more effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e56ef6a-88b9-40bd-a043-c6537b6bf43c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle query strings in a URL?', N'Middle', N'Express automatically parses query strings and makes them available in the ''req.query'' object as a JavaScript object. This allows developers to easily filter, sort, or paginate data by reading the key-value pairs appended to the URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80159baa-b7e2-4c15-a91a-c65581b4ed02', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do microservices communicate with each other?', N'Senior', N'Microservices often work together, and they need efficient communication mechanisms... Communication Patterns - Synchronous: Web services and RESTful APIs synchronize requests and responses. They are simpler to implement but can lead to tighter coupling between services. For dynamic traffic or workflow-specific requests, this is a suitable choice. - Asynchronous: Even with service unavailability or high loads, queues lead to the delivery of messages. The services do not communicate or interact beyond their immediate responsibilities and workloads. For unpredictable or lengthy processes, use asynchronous communication. - Data Streaming: For continuous data needs or applications that work with high-frequency data, such as stock prices or real-time analytics, this method is highly effective.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5ddba91-0fa8-445c-a5e6-c656a3d6b460', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik considered ''O(1)'' regarding hydration?', N'Junior', N'Qwik is considered O(1) because the cost of initializing the application does not grow with the size of the application. Whether the app is small or massive, the initial load remains consistently fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'755d45ac-a317-433f-8166-c65775bd7c7c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the TypeScript compiler (tsc)?', N'Fresher', N'The TypeScript compiler is responsible for transpiling TypeScript code into standard JavaScript that browsers can understand. It also performs type checking and reports any errors found in the code based on the defined types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
