INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1b98f10-2982-467e-abf9-c65f146c4100', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the virtual DOM, and why does Svelte avoid it?', N'Intern', N'The virtual DOM is a programming concept where a virtual representation of the UI is kept in memory and synced with the real DOM. Svelte avoids it because comparing virtual DOM trees introduces overhead; instead, Svelte updates the actual DOM directly via compiled code, which is faster and more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
