INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a37a2ff-a36d-4e6b-a101-c6610d9404b6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go lack traditional inheritance, and how does this affect system architecture?', N'Senior', N'Go favors composition over inheritance to avoid complex, fragile class hierarchies that are difficult to refactor. This promotes a design pattern where functionality is bundled into small, reusable interfaces, leading to more modular and testable system architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e93952e-6e73-4b44-a5c0-c6645f20a282', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the impact of using ''export const ssr = false'' in a SvelteKit route?', N'Middle', N'Setting SSR to false disables server-side rendering for that specific route, causing it to be rendered entirely in the browser. This is useful for highly dynamic, private dashboards where SEO is irrelevant and the initial load time can be traded for reduced server work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'420d030a-0333-4d74-aa06-c664dfdedab7', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of a Controller in AdonisJS?', N'Fresher', N'A Controller is responsible for handling incoming HTTP requests and returning a response. It acts as the bridge between the route definitions and the application logic, keeping the code organized by separating concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed5e9f2a-7036-416b-b2b6-c66928077215', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the express.Router class?', N'Intern', N'The express.Router is a powerful tool for managing multiple route controllers. It helps in organizing routes and their handling functions into modular, self-contained groups. Key Features - Modularity: Rely on separate route modules for improved code organization, maintainability, and collaboration. - Middlewares: Like the main express app, the router can also use middlewares to process incoming requests. - HTTP Method Chaining: Simplifies route handling by allowing method-specific routes to be defined using method names. Example: Middleware and Route Handling Here is the Node.js code: In this example, we: - Utilize the built-in express.Router. - Attach a general-purpose middleware and two different HTTP method-specific routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4e523b2-1949-42a4-98a8-c66b1ec9fd95', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Why is Hono considered a ''future-proof'' framework in the context of the Web Standards evolution?', N'Senior', N'Because Hono is built entirely on top of the Fetch API and standard web primitives, it will remain compatible with future enhancements to the JavaScript runtime environments. Unlike frameworks tied to proprietary legacy APIs, Hono evolves alongside the standards, ensuring long-term technical alignment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf213bda-5cfc-4bb0-b5b7-c66da616912f', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the role of the ''Manager'' class in Django models and when to create a custom one.', N'Middle', N'The Manager is the interface through which database query operations are provided to Django models. You should create a custom manager to encapsulate common filtering logic or to provide specialized queryset methods, promoting DRY principles and keeping view logic thin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8aad4e76-6c6d-4726-9d6b-c670217be7b0', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the trade-offs of using third-party APIs versus building custom internal solutions?', N'Senior', N'I consider the build-versus-buy decision based on core competency, total cost of ownership, and competitive advantage. I estimate the long-term maintenance costs, dependency risks, and flexibility constraints of the third-party solution compared to the development cost and ongoing operational burden of a custom build.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f980f112-7b38-470a-8960-c670f9409989', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain relational operators in Python?', N'Fresher', N'Relational operators compare values. > - Less than ( ) If the value on the left is greater, it returns True. 1.1 + 2.2 > 3.3 True This is because of the flawed floating-point arithmetic in Python, due to hardware dependencies. Less than or equal to ( =) If the value on the left is greater than or equal to, it returns True. True >= False True Equal to (==) If the two values are equal, it returns True. {1,3,2,2} == {1,2,3} True Not equal to (!=) If the two values are unequal, it returns True. True!=0.1 True False!=0.1 True', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30acd7e7-4a02-4449-86aa-c67678dbd435', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain how ''BigInt'' differs from the ''Number'' type at the engine level.', N'Senior', N'The Number type is a 64-bit float, which limits precision for large integers, while BigInt uses a arbitrary-precision integer representation. Because they operate on different data structures, they cannot be implicitly mixed in arithmetic, which prevents precision loss and requires explicit conversion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'104dc21b-8784-4aac-81d1-c67de6ffb55a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the advantage of using ''Ref'' directives in Lit?', N'Middle', N'The Ref directive provides a way to get a direct reference to a specific DOM element rendered by a component. It is useful for integrating with third-party libraries that need to interact directly with the DOM node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'974cc0a5-4107-47bc-9669-c67e80fd8552', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Why is ''Sampling'' necessary for distributed tracing, and what are the risks?', N'Senior', N'Sampling is required to manage the massive storage and network overhead generated by tracing every transaction in a high-traffic system. The primary risk is the loss of visibility into ''long-tail'' events or specific outlier errors that might only occur in a tiny fraction of total requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff118d82-4762-4f35-a6ec-c67e8e411f48', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'When is it appropriate to use a cache-aside pattern versus a write-through cache?', N'Senior', N'Cache-aside is best for read-heavy workloads where the application handles cache population, allowing for lazy loading and flexibility. Write-through is better for write-heavy workloads where data consistency between the cache and database is critical, as it ensures the cache is always updated during the write operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f14aef8b-e3ec-44d4-a934-c67f1d5989b7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite considered faster than older build tools for large projects?', N'Intern', N'Vite is faster because it does not bundle the entire application at startup. By using native browser support for ES modules, it only transforms and serves the files that are actually being requested by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ecaf40d0-868c-4527-8db7-c6807a185e55', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is state in Preact?', N'Intern', N'State refers to the internal data of a component that can change over time in response to user actions or network events. When the state of a component updates, Preact automatically triggers a re-render to reflect those changes in the user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e5aea29-4f8c-4c7b-9d03-c680be025ab4', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is a ''Future'' in Dart?', N'Intern', N'A Future represents a potential value or error that will be available at some point in the future. It is the primary way Dart handles asynchronous operations, allowing the program to continue running while waiting for a task to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12f9639e-355d-4e4a-a0f1-c682c3047743', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are blocks, procs, and lambdas?', N'Junior', N'Blocks are chunks of code passed to methods that are not objects themselves. Procs and lambdas are objects that store blocks of code for later execution, with lambdas being stricter about argument count and return behavior compared to procs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21c90dc1-f8b4-4f86-800c-c68391e25f17', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can you use different frontend frameworks in the same Astro project?', N'Junior', N'Yes, Astro is framework-agnostic, meaning you can mix components from React, Vue, Svelte, Solid, and others within a single project. This flexibility allows teams to choose the best tool for each specific part of the user interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38c48152-8661-4109-b6fc-c6843100ee03', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS lifecycle support graceful shutdowns?', N'Senior', N'The framework provides lifecycle hooks to handle application termination, allowing for the closing of database connections and completion of pending background tasks before the process exits. This ensures data integrity and prevents corrupted state or lost messages during deployments or service restarts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8103dec8-c4f4-450b-8af8-c687515f3d10', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser''s compositor thread differ from the main thread in the context of CSS animations?', N'Senior', N'The main thread handles JavaScript execution and style recalculation, while the compositor thread handles the drawing of layers onto the screen. Animations involving transform and opacity can be offloaded to the compositor thread, allowing for smooth performance even when the main thread is busy with complex application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b71eb8f2-9e3c-42b7-bcc3-c688a6b02d05', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the primary differences between structural and nominal typing, and how does TypeScript''s design influence this?', N'Senior', N'TypeScript uses a structural type system where compatibility is determined by members, not explicit declarations. This contrasts with nominal systems like Java, where type names must match. Structural typing facilitates flexible code composition but requires careful interface design to prevent accidental type compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'536e3300-bd9a-4bb0-b49f-c689d4c12232', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between an interface and an abstract class in PHP, and when would you choose one over the other?', N'Middle', N'Interfaces define a contract of methods that a class must implement without providing logic, while abstract classes can contain both method declarations and shared implementation code. Choose an interface for defining shared capabilities across unrelated classes and an abstract class for defining a base template for a hierarchy of related classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d61145d-e9e5-4279-82f8-c68cbec0fa9f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the mechanism of biased locking and why it was deprecated in recent JDK versions.', N'Senior', N'Biased locking reduced contention costs by assuming a lock would only be acquired by a single thread, effectively removing the need for atomic operations. It was deprecated because the complexity of maintaining the bias state across thread handshakes outweighed the performance gains in modern, multi-core systems with higher contention patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59b52202-9595-4876-a223-c690800de969', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''defer'' and ''async'' attributes in script tags, and when should you use each?', N'Middle', N'The ''async'' attribute downloads the script in the background and executes it as soon as it is downloaded, which may block the parser if it finishes early. The ''defer'' attribute also downloads in the background but waits to execute until the HTML document is fully parsed, preserving the execution order of scripts. Use ''defer'' for scripts that depend on the DOM, and ''async'' for independent scripts like analytics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'514f7221-a91f-4dea-b17f-c6928c8c8337', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you manage configuration across multiple environments in Laravel, and what is the precedence order?', N'Senior', N'Configuration is managed via environment files and the internal config directory, with environment variables taking precedence over static files. This allows for sensitive or environment-specific data to be injected via the server environment without being committed to version control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ea3f95-236d-4a79-a3c1-c6929e1f931b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between native, host and user objects?', N'Fresher', N'1. Native Objects: Are objects that are part of the JavaScript language defined by the ECMAScript specification. For example, String, Math, RegExp, Object, Function etc core objects defined in the ECMAScript spec. 2. Host Objects: Are objects provided by the browser or runtime environment (Node). For example, window, XmlHttpRequest, DOM nodes etc considered as host objects. 3. User Objects: Are objects defined in the javascript code. For example, User object created for profile information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c272ba-2d2b-4503-8ddb-c694a90079b9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a generic, and why is it useful?', N'Junior', N'Generics allow you to create reusable components or functions that work with a variety of types rather than a single one. By using a placeholder for the type, you can maintain type safety while keeping the logic flexible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afef0948-8694-4f01-b58e-c69540258c63', N'954a0331-deff-4399-b588-96f39fec001d', N'How does angular finds components, directives and pipes?', N'Fresher', N'The Angular compiler finds a component or directive in a template when it can match the selector of that component or directive in that template. Whereas it finds a pipe if the pipe''s name appears within the pipe syntax of the template HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6f5b6d3-d4e0-498c-9a1e-c69564e543ab', N'4c000000-0000-0000-0000-000000000005', N'How do you handle database transactions in a microservices environment?', N'Middle', N'Since traditional ACID transactions are difficult across services, you typically use the Saga pattern. This breaks a large transaction into a series of local transactions, with compensating transactions defined to roll back changes if a step in the sequence fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f13b100-f682-4868-9890-c6957fdfa6d5', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the benefits of using Problem Details (RFC 7807) for error handling in ASP.NET Core APIs?', N'Senior', N'Problem Details provides a standardized, machine-readable format for reporting errors in HTTP APIs, ensuring consistency across different endpoints. It helps clients understand exactly what went wrong without leaking sensitive internal implementation details, improving API usability and security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'280df43e-23a1-4785-b20f-c69588a3b18a', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the benefit of using ''final'' on a class or method?', N'Middle', N'The final keyword prevents a class from being subclassed or a method from being overridden. This improves performance by allowing the compiler to use static dispatch instead of dynamic vtable dispatch, and it enforces design constraints by preventing unintended behavior changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02605924-7d20-49fd-b884-c695aac7ec0e', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are Secondary Indexes?', N'Intern', N'Secondary indexes allow you to query data in a table using attributes other than the primary key. They provide flexibility by allowing you to query the same data in different ways without changing the main table structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f33b2b47-d9c0-413a-ac23-c695efaab592', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is ''hydration'' in the context of Astro?', N'Intern', N'Hydration is the process of attaching JavaScript functionality to static HTML elements on the client side. In Astro, you control exactly which components get hydrated, preventing unnecessary script execution for static parts of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8f8297c-b478-48cc-8198-c6963a5dba8d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is ''Declaration Merging'' and how does it affect global type definitions?', N'Middle', N'Declaration merging allows the compiler to automatically combine multiple separate declarations with the same name into a single definition. This is particularly useful for extending global interfaces like Window or adding custom properties to third-party library definitions without modifying their source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89424dac-7be2-4317-adce-c6968567894f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo manage headers?', N'Intern', N'Echo''s response object provides methods to easily add, retrieve, or delete HTTP headers. This is useful for setting cookies, authentication tokens, or custom metadata for the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4afcf3a-4839-45f5-b285-c69b74d31988', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the significance of the ''Cake Pattern'' in Scala, and why has it fallen out of favor in modern architecture?', N'Senior', N'The Cake Pattern uses self-types and trait composition to achieve dependency injection without external frameworks. It is often criticized for becoming unwieldy as component complexity grows, leading to difficult-to-trace initialization order issues and overly verbose boilerplate, which is why functional approaches like ReaderT or ZIO environments are now preferred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9342680-d1ff-4773-ab83-c69bdb3e14fb', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''TailRec'' annotation differ from the compiler''s automatic tail-call optimization?', N'Senior', N'The ''@tailrec'' annotation is a developer-driven enforcement mechanism that forces the compiler to verify that a method is indeed tail-recursive and can be optimized. If the method does not meet the criteria, the compiler generates an error instead of silently falling back to a non-optimized version. This provides a safety net for critical performance-sensitive code where stack overflow prevention is mandatory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8c83153-1bd1-4ef8-aa82-c69ed5855558', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the benefit of ''Schema-on-read'' compared to the traditional ''Schema-on-write'' approach?', N'Senior', N'Schema-on-read allows for greater flexibility in data storage since the application interprets the data at the time of retrieval rather than enforcing structure during ingestion. This enables developers to evolve data formats without performing expensive schema migrations, although it shifts the responsibility of data validation and transformation to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a407675-7b2b-49f1-8b60-c69fca609964', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the role of the Django ''views'' layer?', N'Intern', N'The view layer is responsible for processing incoming web requests and returning a web response. It contains the business logic that retrieves data from the model and passes it to the template for rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
