INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a235bd5-4684-4943-89aa-c6a073081297', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the role of Phoenix Views and Templates.', N'Junior', N'Templates define the structure of the HTML output, while Views act as modules that contain helper functions to transform raw data into a format suitable for the templates. This separation ensures that logic remains out of the HTML files, keeping the presentation layer clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
