INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea8afb91-f7a8-4f5d-9abb-c6a39d08d358', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach debugging a production issue that cannot be reproduced in a staging environment?', N'Middle', N'I would rely on enhanced observability, such as increasing log verbosity for the affected components and using distributed tracing to correlate specific requests with their execution path. I would also compare the production environment''s configuration and traffic patterns against staging to identify environmental differences, such as load, data volume, or infrastructure settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b636690e-2a29-41ef-a36b-c6a50607aac8', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack''s implementation of ''Module Federation'' solve micro-frontend scalability issues?', N'Senior', N'Module Federation allows multiple independent builds to share modules at runtime rather than build time. It enables dynamic dependency resolution and shared singleton management across separate applications, facilitating true micro-frontend architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
