INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c3e116c-69b4-4202-b5bf-c6a80e7de983', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Can NoSQL databases handle complex queries?', N'Intern', N'While NoSQL databases are optimized for simple, high-speed lookups, they often lack the complex join capabilities found in relational databases. Many NoSQL systems require developers to denormalize their data to handle queries that would otherwise require joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
