INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1010b77-c4f4-4ed6-8768-c6b396677660', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the trade-off between using Fastify''s ''fast-json-stringify'' and standard native methods?', N'Senior', N'The trade-off is startup time versus runtime speed. Fast-json-stringify requires an initial compilation phase that consumes extra startup time, but it provides significantly faster execution speeds for high-volume requests compared to native reflection methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9cc755f-f0b5-4f8f-aad9-c6b424b358a2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''infer'' keyword do in the context of conditional types?', N'Middle', N'The ''infer'' keyword is used within a conditional type to introduce a type variable that can be extracted from another type, such as the return type of a function. It allows for advanced type manipulation where you can dynamically capture and reuse parts of an existing type structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be8cf3a9-6268-429c-8506-c6baef915341', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does "type inference" mean in the context of TypeScript?', N'Intern', N'In TypeScript, type inference is a core feature that allows the type of a variable to be automatically determined from its value. This provides the benefits of static typing without the need for explicit type annotations. How It Works TypeScript employs a best common type algorithm to infer a variable''s type. When TypeScript encounters multiple types for a variable during assignment or an array literal, it computes the union of these types and selects the best common type for the variable. Code Example: Type Inference Consider the following code: TypeScript can infer the most likely type from the context, such as: - When a value is assigned immediately, TypeScript assigns the value''s type to the variable. - Type information from adjacent types is used to determine the best common type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ecf1de7-9033-4e05-ad88-c6bb8811f5cd', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the significance of the ''idempotency key'' in distributed API design.', N'Senior', N'An idempotency key allows a client to safely retry a request without worrying about duplicate state changes if the original request was processed but the acknowledgement was lost. The server uses this key to check if the request has already been executed, returning the cached result instead of performing the operation again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00456285-e457-4d78-8786-c6be17ac01b4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Describe the impact of the R global interpreter lock (GIL) on multi-threaded execution.', N'Senior', N'R is essentially single-threaded at the language level due to its design, which lacks a true global interpreter lock but lacks native thread safety for internal data structures. Consequently, true parallel execution in R requires multi-processing strategies where separate instances of the interpreter are spawned, each with its own memory space, necessitating efficient inter-process communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78876097-dd6b-4c86-a5c8-c6be3a0c277c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a view in MySQL?', N'Intern', N'A view is a virtual table based on the result set of an SQL statement. It does not store data itself but displays data from one or more tables, allowing users to simplify complex queries or restrict access to specific columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db7bf76f-b128-4312-babb-c6bf123eaaf1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between an ''Injectable'' and a ''Controller'' in NestJS?', N'Middle', N'An Injectable class is a provider meant to contain business logic and be shared across the app. A Controller is the entry point that handles incoming HTTP requests and delegates tasks to these services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
