INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33d731cb-f2fa-4e1f-a2b2-c6c1211f2257', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of media queries in responsive web design?', N'Middle', N'Media queries allow developers to apply different CSS rules based on device characteristics like viewport width, height, or resolution. They are the foundation of responsive design, enabling the layout to adapt fluidly to different screen sizes, from mobile phones to desktop monitors. This ensures an optimal user experience across all devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01e4d523-005f-4ebb-a52a-c6c2c1c4166d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it generally recommended to avoid mapping fields as both ''text'' and ''keyword'' unnecessarily?', N'Middle', N'Mapping a field as both types increases storage consumption and index size because Elasticsearch stores the data in two different structures. While useful for scenarios requiring both full-text search and exact aggregations or sorting, it creates overhead that should be avoided if only one functionality is needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd380442b-dd44-4d1f-9f6d-c6c6c2ac9604', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of idempotency in API design?', N'Middle', N'Idempotency ensures that performing the same request multiple times has the same effect as performing it once. This is critical in distributed systems to handle network retries safely, ensuring that a duplicated request does not result in duplicate actions like double charging a customer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39f8c886-91b1-44d3-a8ee-c6cabee7a323', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Explain how you would reason through the choice between horizontal and vertical scaling for a service experiencing latency under load.', N'Middle', N'I would analyze the service''s current resource utilization; if the bottleneck is CPU or memory saturation on a single instance, vertical scaling is a quick, temporary fix. However, horizontal scaling is generally preferred for long-term reliability and fault tolerance, as it distributes the load across multiple instances and eliminates single points of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48e45c8c-f1d2-4c8f-8a4c-c6cb937393b9', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Describe the impact of ''key'' prop misuse on application performance and component state.', N'Senior', N'Using unstable values like indices for keys can cause incorrect component reuse, leading to lost internal state or broken UI updates when lists are reordered or filtered. Proper key usage ensures that React can accurately track the identity of elements, preventing expensive re-mounts of complex component subtrees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c98d9aa-c2b6-4157-b90d-c6ce2e40ce26', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a Transaction?', N'Fresher', N'A transaction is a single logical unit of work that consists of one or more SQL operations. To maintain data integrity, all operations within a transaction must either succeed or fail as a group.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb88ca6d-bc18-48b4-8397-c6cecafa5ff9', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the purpose of the ''$:'' syntax in Svelte and how it handles side effects.', N'Middle', N'The ''$:'' syntax represents a reactive statement that the Svelte compiler automatically re-runs whenever any referenced variables change. It is designed to handle derived state and side effects efficiently without needing manual dependency arrays or hook triggers found in other frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'006e39cc-ae95-43c1-90ba-c6cf5005be5a', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the advantage of using containers with microservices?', N'Middle', N'Containers provide environmental consistency, ensuring that a service runs the same way in development, testing, and production. They also facilitate efficient resource utilization and rapid scaling by allowing services to be started or stopped quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd1e5c3e-8753-4820-8b23-c6cf8f7e1538', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is a foreign key constraint?', N'Junior', N'A foreign key constraint enforces referential integrity between two tables. It ensures that a value entered in one table must already exist in the primary key column of the related table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f7c3c95-212c-4517-819b-c6d1b9bd92f0', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'In the context of scaling, why is Phoenix''s ''Endpoint'' design advantageous for deployment flexibility?', N'Senior', N'The Endpoint acts as the single entry point for all requests, decoupling the transport layer from the business logic. This design allows for seamless upgrades, hot code reloading, and the ability to run multiple Phoenix applications or different versions on the same node without interfering with the underlying connection handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495dddaf-e47a-46f2-9be2-c6d2372c6060', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle distributed tracing without manual instrumentation?', N'Senior', N'Quarkus integrates natively with OpenTelemetry, automatically instrumenting HTTP and database calls. This allows for seamless observability in microservices architectures, providing deep insights into request propagation across services without requiring extensive boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f393675-a923-4fe9-a4c0-c6d2a2ac166f', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is state immutability?', N'Fresher', N'Immutability means that once an object is created, it cannot be changed. In Redux, you must create a new object rather than modifying the existing state object to ensure state changes are tracked correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af202ac5-344d-4b4b-95a3-c6d3c4d2b58a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are ''Hooks'' in the context of Hono middleware?', N'Junior', N'Hooks are specialized functions that allow you to intercept the request lifecycle at specific points. They are commonly used for tasks like parsing input data or validating authentication tokens before the main logic runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
