INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9f87522-f833-4970-a6af-c6d8b30f80ae', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can Fiber serve static files?', N'Intern', N'Yes, Fiber has built-in support for serving static files such as images, CSS, and JavaScript. Developers can define a directory path where these files are stored, and the framework will handle serving them to clients automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8bd8530-783c-4802-80ec-c6d929ac2e1e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the difference between a ''term'' query and a ''match'' query.', N'Middle', N'A term query performs an exact lookup against the inverted index without analyzing the input, making it suitable for keywords or status fields. A match query analyzes the input text using the field''s analyzer, allowing for fuzzy matching and tokenization suited for full-text search.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc5223a8-9dc8-4418-a48a-c6dbadf6659f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s caching strategy work during development and build phases?', N'Senior', N'In development, Vite caches pre-bundled dependencies in the node_modules/.vite directory to avoid re-processing on every restart. During production builds, it relies on standard file hashing to facilitate long-term caching at the CDN or browser level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84b3469b-0743-4063-a08f-c6dc33dfe6ea', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Compare the performance impacts of Bloom filters in LSM-tree versus B-Tree based storage.', N'Senior', N'Bloom filters are essential in LSM-trees to prevent unnecessary disk reads by determining if a key exists in an SSTable before opening it. In B-Trees, Bloom filters are less critical because the structure inherently directs the search path, making them more of an optional optimization rather than a core performance component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e024d19-9eca-4ee4-b0cc-c6dc83126290', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different ways to copy an object or an array?', N'Intern', N'To copy an object or an array in JavaScript, you can use several methods. For shallow copies, you can use the spread operator (...) or Object.assign(). For deep copies, you can use JSON.parse(JSON.stringify()) or libraries like Lodash''s _.cloneDeep(). ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the difference between shallow copy and deep copy A shallow copy duplicates the top-level properties of an object, but nested objects are still referenced. A deep copy duplicates all levels of an object, creating entirely new instances of nested objects. Object.assign() and the spread operator (...) create shallow copies. structuredClone() is the modern built-in for deep copies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69dc0360-6965-4f95-b27a-c6dfb7a3b9ad', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Can TypeScript be run directly in the browser?', N'Fresher', N'No, TypeScript cannot be run directly in the browser. It must be compiled or ''transpiled'' into standard JavaScript by the TypeScript compiler before it can be executed by a browser or a runtime like Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a54dd62-e764-45e9-a6f7-c6e323bdc337', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''Suspense'' in SolidJS?', N'Intern', N'Suspense is a component that manages the loading state of asynchronous resources. It allows you to display a fallback UI while data is being fetched and automatically swaps it for the real content when the data is ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'300a77b3-cfb4-466f-8aa0-c6e59b381c5a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the main trade-off of adopting a microservices architecture?', N'Intern', N'Microservices enable independent deployment and scaling of specific components, which is great for large teams. However, they introduce significant complexity in networking, monitoring, and distributed transaction management that a monolith does not have.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37603da5-a895-4667-a98c-c6ea03154c67', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the primary trade-offs when choosing between a normalized and a denormalized database schema?', N'Middle', N'Normalization reduces data redundancy and prevents update anomalies by splitting data into related tables. Denormalization improves read performance by reducing the number of costly joins but increases storage requirements and risks data inconsistency during write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0ff2402-6cd3-49f0-828f-c6ed629c2c8f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte perform hydration in the context of Server-Side Rendering (SSR)?', N'Middle', N'During SSR, Svelte renders the component as static HTML on the server. On the client, the Svelte runtime takes over by attaching event listeners and reactive logic to the existing DOM structure, a process known as hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'704c123c-9498-47dd-bce1-c6ee1f3d7ac2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Describe the ''keyof'' and ''indexed access'' operators and how they improve type synchronization.', N'Senior', N'The ''keyof'' operator extracts a union of literal keys from an object type, while indexed access types allow you to look up a property type by its key. Together, they enable developers to write code that stays in sync with data models automatically, preventing hardcoded string errors when accessing object properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51dd7935-336d-4d12-97c1-c6f37bb7b23c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you detect a mobile browser using regexp?', N'Fresher', N'You can detect mobile browser by simply running through a list of devices and checking if the navigator.userAgent matches anything. This is an alternative solution for RegExp usage, Example: The /i flag makes the match case-insensitive. The | operator checks for any of the device strings in the user agent string. Note: User agent detection is considered unreliable for feature detection. Prefer feature detection APIs (e.g., navigator.maxTouchPoints, CSS media query hover: none) for deciding UI behavior, and reserve UA sniffing for analytics or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2e2bafc-c515-4aa1-91e6-c6f45ab05563', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is ''Database Sharding'' considered a last-resort strategy for scaling?', N'Senior', N'Sharding significantly increases system complexity by requiring application-level routing, making joins across shards nearly impossible, and complicating rebalancing as the data grows. It is generally reserved for when vertical scaling or read-replicas can no longer accommodate the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e6dd39-9381-457f-a005-c6f5a842dc53', N'954a0331-deff-4399-b588-96f39fec001d', N'What are dynamic components?', N'Intern', N'Dynamic components are the components in which the component''s location in the application is not defined at build time i.e. they are not used in any angular template. Instead, the component is instantiated and placed in the application at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b148ab64-b40e-468d-ade8-c6f5f392efca', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails manage database transactions during concurrent web requests, and what are the risks of using long-running transactions?', N'Senior', N'Rails wraps controller actions in transactions if configured, but generally relies on explicit blocks. Long-running transactions hold database row locks, which can lead to connection pool exhaustion, increased latency for other processes, and potential deadlocks under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcb6ee3f-609b-4b7e-baa3-c6f60862a84b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the ''IntoResponse'' trait in Axum?', N'Fresher', N'IntoResponse is a trait that defines how a type can be converted into an HTTP response. Any type that implements this trait can be returned from an Axum handler, allowing for custom response structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a7d34a-6741-482b-8ed4-c6f7d2c191c0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you detect a mobile browser using regexp?', N'Fresher', N'You can detect mobile browser by simply running through a list of devices and checking if the navigator.userAgent matches anything. This is an alternative solution for RegExp usage, Example: The /i flag makes the match case-insensitive. The | operator checks for any of the device strings in the user agent string. Note: User agent detection is considered unreliable for feature detection. Prefer feature detection APIs (e.g., navigator.maxTouchPoints, CSS media query hover: none) for deciding UI behavior, and reserve UA sniffing for analytics or logging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'594ca0e7-acd9-4cd5-896a-c6f912a400a6', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the benefit of using semantic versioning in an API?', N'Middle', N'Semantic versioning provides clear signals about the compatibility of changes to consumers. It helps maintain reliability by ensuring that breaking changes are clearly signaled, preventing unexpected failures in dependent services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78e8f9c3-c6c1-43e9-87bb-c6fd852edd47', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the difference between an Exception and an Error in Python.', N'Middle', N'In Python, both are technically classes that inherit from the BaseException class, but they serve different purposes. Errors generally represent serious, unrecoverable system conditions that should not be caught, while Exceptions represent conditions that a program might want to catch and handle. It is best practice to catch only specific subclasses of Exception rather than the base class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'226db5f9-6180-49ce-ab0c-c6fdef1cb1be', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the architectural risks of ''Shadow IT'' in a large organization.', N'Senior', N'Shadow IT introduces unmanaged, unpatched, and non-compliant infrastructure that bypasses corporate security policies. It creates blind spots in the security landscape, making it impossible to enforce uniform access control or monitor for vulnerabilities, significantly increasing the organization''s overall risk profile.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'152a6f2a-a4d2-4add-8ae2-c6fe3da84de4', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle request body parsing?', N'Fresher', N'Litestar uses type hints to determine how to parse the request body. If a route handler expects a model as an argument, the framework will automatically attempt to deserialize the JSON body into that model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70c01737-b9d1-4d72-8bdb-c6ff38b25d2b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What does the ''public static void main'' signature mean?', N'Junior', N'Public allows the JVM to access the method from outside the class, static means it belongs to the class and doesn''t require an object, void indicates it returns no value, and main is the designated entry point for the program execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c823c539-50fc-4baf-8ff4-c70442294874', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do Rust''s Result and Option types differ from null pointers in other languages?', N'Middle', N'Option and Result force developers to explicitly handle the absence of a value or the possibility of an error. Unlike null pointers, which are often implicit and can lead to unexpected crashes, these types ensure that edge cases are addressed during development to achieve compile-time safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96978f9f-986a-48f2-b007-c7049e366b86', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the primary purpose of a WSGI server in a Flask application?', N'Fresher', N'WSGI stands for Web Server Gateway Interface. It acts as a bridge between the web server and the Flask application, ensuring that the server can communicate with the Python application to process HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff931ecb-a77b-4781-b6ce-c704bc42c073', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the security implications of using ''v-html'' in Vue?', N'Senior', N'Using v-html renders raw HTML strings, which makes the application vulnerable to Cross-Site Scripting (XSS) attacks if the content is not sanitized. It should only be used on trusted content, and external libraries like DOMPurify should be utilized to sanitize data before rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fad43f56-689f-47b0-aa2a-c7062e933b22', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What does ''Service'' mean in Symfony?', N'Fresher', N'A service is any PHP object that performs a global task, such as sending emails, logging messages, or querying a database. In Symfony, these objects are managed by the container to ensure they are available whenever and wherever they are needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfa9016c-81c2-4a8f-8005-c7076d306be4', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB''s Global Secondary Index (GSI) differ from a Local Secondary Index (LSI)?', N'Senior', N'A GSI allows you to query across all partitions using a different partition key, whereas an LSI shares the base table''s partition key but provides an alternative sort key. GSIs are asynchronous and eventually consistent, while LSIs are synchronous and can be strongly consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb7b2c58-a398-48c4-9716-c7084710f74a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of the ''c.Next()'' function in Gin middleware?', N'Middle', N'The c.Next() function is used within a middleware to pause its execution and invoke the subsequent handlers in the chain. Once the rest of the chain finishes, execution resumes in the current middleware, allowing for post-processing tasks like measuring response time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'514d6b82-b448-4332-bce2-c70f4a8b3283', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a situation where a service is intermittently failing under load, but shows no errors during low-traffic testing?', N'Senior', N'I suspect resource contention or thread pool saturation and would inspect thread dumps to identify blocked threads or lock contention. I also look for hidden bottlenecks like synchronous logging, disk I/O limits, or garbage collection pauses that only trigger under significant throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28b50e5b-ca00-499d-82a4-c7109fcccfba', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a browser engine?', N'Intern', N'The browser engine is to take the HTML, CSS and other code of a web page - the text you can see in the page source or open in a text editor, setting out layouts, page content, and styling - and convert it into what you actually see on screen. The browser engine, rendering engine, and JavaScript engine are all essentially working together to get raw web code into a viewable and usable-form inside your browser. Browser Engines: 1. Gecko: It''s a Mozilla''s browser engine. It is used in the Firefox web browser, the Thunderbird email client, and the SeaMonkey internet suite. Goanna also is a fork of Gecko used in the Pale Moon browser. 2. WebKit: This engine created by Apple for its Safari browser, by forking the KHTML engine of the KDE project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40a983f9-a51a-4db0-ba31-c71259f47875', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a managed cloud service versus hosting your own infrastructure?', N'Junior', N'Managed services are preferred when you want to reduce operational overhead, offload maintenance tasks like patching and backups, and gain faster time-to-market. Self-hosting is only recommended if you have strict data sovereignty requirements, need highly custom configurations, or want to optimize costs at a very large scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd223afab-ab5f-44bd-8bca-c713492ce528', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are skip navigation links and why are they important?', N'Intern', N'Skip navigation links (or "skip links") are hidden anchor links placed at the very top of a page that allow keyboard and screen reader users to jump past repetitive navigation blocks directly to the main content. Without a skip link, keyboard users must Tab through every navigation item on every page load before reaching the content — a significant accessibility barrier. Implementation: *Note: tabindex="-1" on ensures it can receive programmatic focus when the skip link is activated.*', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbe17a8d-9dba-48b8-82c9-c713848954d1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the primary difference between Quarkus and traditional Java frameworks regarding build-time and runtime?', N'Middle', N'Quarkus performs most framework initialization and dependency injection wiring at build-time rather than runtime. This shift significantly reduces the application''s memory footprint and accelerates startup time, as the bytecode is already optimized for the specific deployment environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb08b3e1-395c-40c4-93c7-c71451a1ba62', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''jsonify'' function?', N'Intern', N'The jsonify function is used to return a JSON response from a Flask route. It automatically sets the correct content-type header for the response, making it easy to create APIs that communicate with frontend applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da19cda8-cedb-4b5f-90f3-c7158b67b2ef', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is typeof operator', N'Intern', N'You can use the JavaScript typeof operator to find the type of a JavaScript variable. It returns the type of a variable or an expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f22feb4c-e8de-40ef-b1f9-c71665b70260', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary role of a loader in Remix?', N'Intern', N'A loader is a server-side function responsible for fetching data required for a specific route. It runs before the page renders, ensuring that the necessary information is ready for the component to display.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8416128-7aba-4919-ba53-c7174235d55a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What does the term ''micro-framework'' mean in the context of Flask?', N'Fresher', N'A micro-framework means that the core of the framework is small, providing only the essential features needed to get a web application running. It does not include built-in database abstraction, form validation, or authentication, allowing developers to choose their own tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92fef196-c5db-4406-bb72-c717f66552a1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of tunable consistency.', N'Middle', N'Tunable consistency allows developers to adjust the level of consistency on a per-request basis. By choosing how many nodes must acknowledge a read or write operation, a system can trade off between lower latency and higher data accuracy depending on the use case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ca84038-5da0-4fef-bac8-c71855c91619', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you test Lit components in an isolated environment?', N'Middle', N'Lit components are tested by rendering them into a test fixture, which is a temporary DOM container in the test environment. You then verify the component''s state, attributes, and DOM output using standard testing frameworks like Web Test Runner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4155d46-4748-48c9-918d-c71e03a2cc97', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why is it important to separate the Express ''app'' definition from the server ''listen'' execution?', N'Senior', N'Separating definition from execution is essential for integration testing, allowing you to start the app in a test environment without binding to a network port. It also enables better management of multi-server setups or testing configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d91b539-baaf-484e-a968-c71e233af344', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the primary use case for AdonisJS ''View'' composition?', N'Middle', N'View composition allows you to build complex pages using reusable components and layouts. It promotes DRY principles in the frontend layer, ensuring consistent UI elements across different pages of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e93364e-99d3-4aab-994b-c71ea1d73c73', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''CAP Theorem'' and why is it relevant to scalability?', N'Middle', N'The CAP Theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. Understanding this helps architects make informed trade-offs when designing systems that must remain scalable and available during network failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be934e3f-c3c6-4227-8bc2-c71f4fc590a2', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the challenge of server-side rendering (SSR) in applications heavily dependent on jQuery?', N'Senior', N'jQuery assumes the existence of the window and document objects, which are not present in server-side environments like Node.js. This makes it nearly impossible to perform SSR without complex mocking libraries, hindering SEO and initial load performance compared to framework-native rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84e4b60b-dd16-4338-a156-c7232ee8743d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What architectural benefits does Litestar gain from its ''msgspec'' support?', N'Senior', N'Msgspec offers significantly faster serialization and validation compared to standard Pydantic, which is vital for high-performance backend systems. By supporting both, Litestar gives architects the flexibility to balance development speed with raw execution performance based on the specific needs of the service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c0637d-fc58-476b-9ef6-c7237f726478', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine when it is time to move from a shared database to dedicated service databases?', N'Senior', N'I monitor for database contention, performance degradation due to long-running queries, and team velocity bottlenecks caused by monolithic schema changes. Once the operational coupling outweighs the maintenance cost of managing separate databases, I initiate a service-oriented database decomposition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37c6dc5e-b608-47a0-a458-c724e5aa4ec7', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular Ivy and what advantages does it provide for compilation and rendering?', N'Intern', N'Angular Ivy is the default compilation and rendering pipeline for Angular applications, introduced as the default in Angular 9. It''s a complete rewrite designed to improve build times, reduce bundle sizes, and enhance runtime performance. Key advantages include: - Locality: Ivy compiles components independently, leading to significantly faster build times, especially during development. - Tree-shaking: The generated code is highly tree-shakable, meaning unused parts of the Angular framework can be removed from the final bundle, resulting in smaller application sizes. - Smaller bundles: Due to better tree-shaking and a more efficient runtime, applications built with Ivy are generally smaller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b40bc1c1-bbb6-4f63-b7be-c72642009943', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the function of the Startup class?', N'Fresher', N'The Startup class is the entry point for configuring the application''s request pipeline and services. It contains methods to register services in the DI container and to configure the middleware components that process HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b9b4241-6ee1-4132-81ee-c72676e99eb9', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle server-side rendering (SSR) compared to client-side hydration?', N'Senior', N'During SSR, Svelte renders components into static HTML strings, which are then sent to the client. Upon hydration, the client-side Svelte runtime attaches event listeners and reactivity to the existing DOM structure, ensuring a seamless transition without re-rendering the entire page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88e161da-27d6-4018-8675-c72ae15a2cbf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to debug the data rather than the code?', N'Junior', N'Sometimes the code logic is correct, but the input data is malformed, unexpected, or contains edge cases that the application was not designed to handle. Debugging the data involves inspecting inputs, API payloads, or database entries to see if they are the true source of the unexpected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7aaff025-04eb-4760-afc9-c72b468c2f41', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is service versioning important in microservices?', N'Middle', N'Since microservices are deployed independently, breaking changes can cause failures in dependent services. Versioning, typically through URI versioning or header-based versioning, allows multiple versions of an API to coexist, ensuring backward compatibility and smooth transitions during updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5eeadbf-17ff-4e3f-a5a0-c72c89ef6ceb', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Explain the trade-offs between push-based and pull-based telemetry collection systems.', N'Senior', N'Pull-based systems offer better control over service discovery and prevent monitoring saturation, but require the exporter to be reachable by the collector. Push-based systems handle ephemeral or short-lived tasks effectively and simplify firewall traversal, but can lead to a thundering herd problem at the ingestion layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75c833e1-7b45-4468-b2a8-c7301714e014', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar manage exception handling globally?', N'Middle', N'Litestar provides an exception-handling mechanism where you can register custom exception handlers for specific error types. This allows the application to return consistent, structured error responses across all endpoints without repetitive try-except blocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cbc9b1c-ff4d-4834-b21b-c73076559df1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the risk of having a single point of failure in a system?', N'Intern', N'A single point of failure is a component that, if it stops working, brings the entire system down. Identifying and eliminating these points through redundancy is critical for maintaining high availability and reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'887eaa22-0dc9-4eac-9663-c732164d7a4c', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular DevTools and how can it help during development?', N'Intern', N'Angular DevTools is a browser extension available for Chrome, Edge, and Firefox that provides debugging and performance profiling capabilities specifically for Angular applications. It helps developers understand the structure of their application by visualizing the component tree, inspect and modify the state of components and directives, and analyze the performance of change detection cycles to identify bottlenecks. It''s an essential tool for debugging complex Angular applications and optimizing their runtime performance. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c904ef5-5a60-435e-ac7e-c734defc2ba5', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is meant by component composition in Svelte?', N'Fresher', N'Component composition is the practice of building complex user interfaces by nesting smaller, reusable components within larger ones. This promotes modularity and makes the codebase easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ba067c5-eee7-4cf4-8302-c73556eec7f8', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the trade-offs between client-side rendering (CSR) and server-side rendering (SSR) regarding TTI and LCP.', N'Senior', N'CSR provides a faster secondary navigation experience but suffers from poor initial load times as the browser must download and execute JavaScript before content is visible. SSR improves LCP by delivering rendered HTML immediately, though it may increase time to interactive due to the cost of hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db66b8ef-da48-4f04-96e6-c738effa17d9', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the purpose of an API Gateway in terms of security.', N'Middle', N'An API Gateway acts as a single entry point that centralizes security functions such as authentication, rate limiting, and request validation. This allows developers to offload these concerns from individual microservices to a managed infrastructure layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'957b1a5e-de40-491f-99e1-c739cd457118', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the significance of the ''Service'' trait in the context of Axum''s request handling?', N'Senior', N'The Service trait is the core abstraction that defines how an asynchronous function processes a request and returns a response. By standardizing this interface, Axum allows any component that implements the trait to be used as a handler, enabling extreme flexibility in how requests are intercepted and processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10c182fe-9de1-4b2d-b611-c739ff3158f4', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the difference between a handler and a middleware in Axum?', N'Intern', N'A handler is the final function that processes a request and generates a response. Middleware are layers that wrap the handler, performing tasks like logging, authentication, or modification of the request before it reaches the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81aacf0f-3804-4bb5-907d-c73a5a349992', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database transaction, and what are ACID properties?', N'Junior', N'A transaction is a sequence of operations performed as a single logical unit of work. ACID stands for Atomicity, Consistency, Isolation, and Durability, which are the properties that ensure transactions are processed reliably even in the event of errors or crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b85385b-4fb5-43a9-8c60-c73da9510e3c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the trade-off of denormalization?', N'Middle', N'Denormalization introduces redundant data to improve read performance by reducing the need for complex JOINs. The trade-off is increased storage usage and higher complexity in maintaining data consistency, as updates to the redundant data must be carefully managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a5be250-d21f-4f28-92ce-c73f30aeb6c8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary goal of Preact compared to React?', N'Junior', N'Preact aims to provide a lightweight, high-performance alternative to React with the same API. It focuses on reducing the library size to improve load times and performance on mobile devices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f38edb3a-2e6e-46b2-a7b7-c740d958010c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle metadata generation and why is it efficient?', N'Senior', N'Metadata is generated server-side using a dedicated API, allowing for dynamic, asynchronous SEO tags based on database content. This approach prevents client-side rendering of SEO-critical tags, ensuring search engine crawlers receive fully populated HTML immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01e294b6-b4af-4707-b10f-c741b8a6d80c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do decorators in Fastify enable architectural modularity?', N'Senior', N'Decorators allow developers to attach persistent state or shared utilities to the server instance or request object. This promotes a modular architecture where plugins can expose specific functionality without relying on global imports or singleton patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbde5ddd-97d5-4aa4-86d7-c7422465aee2', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the CatchBoundary component?', N'Junior', N'The CatchBoundary component is used to handle ''expected'' errors, such as 404 Not Found or 401 Unauthorized responses. It allows you to display specific UI for these situations without crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc6b9000-034b-4a45-af5e-c7433558c673', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Describe the impact of the ''majority'' write concern on cluster availability and latency.', N'Senior', N'The ''majority'' write concern requires a majority of voting nodes to acknowledge a write before it is considered successful. While this ensures data durability and consistency during primary failover, it increases write latency and decreases system availability if a majority of nodes cannot be reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4930b77-a755-441a-af6b-c7447305da87', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does the ''Macroable'' trait work, and what are the architectural risks of overusing it?', N'Senior', N'The Macroable trait allows developers to dynamically add methods to internal framework classes at runtime. Overuse can make the codebase difficult to debug and static analysis tools less effective, as methods are not explicitly defined in the class hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
