INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef9bb73-cff1-4500-af1c-c74e347a601e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between local component state and global Redux state?', N'Junior', N'Local state is managed within a single component and is only accessible to that component and its children. Global state in Redux is accessible to any component in the application, making it ideal for shared data like user profiles or authentication status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40134766-bf12-4720-98f6-c74ff446d1e0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What happens if a request does not match any defined route in Chi?', N'Middle', N'If no route matches, Chi will fall back to the default ''NotFound'' handler. You can override this behavior by providing a custom handler to the ''NotFound'' field of the router to return a formatted JSON error response instead of a plain text message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
