INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a963506b-284b-4660-8c18-c750c978f939', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the Shadow DOM in Lit components?', N'Intern', N'The Shadow DOM is a browser technology that allows for style and markup encapsulation within a component. By using the Shadow DOM, Lit ensures that styles defined inside a component do not leak out and affect the rest of the page, and external styles do not interfere with the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4502f032-07f9-42ab-9adb-c75105c28d85', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust require explicit lifetime annotations in some cases?', N'Junior', N'Lifetimes are a way for the compiler to ensure that references remain valid. While the compiler can often infer lifetimes, explicit annotations are needed when the relationship between the lifetimes of input and output references is ambiguous.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39f241f4-61bf-46c1-a129-c753a31156f1', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the ''thundering herd'' problem in cache design, and how can Redis help mitigate it?', N'Middle', N'The thundering herd problem occurs when a popular cache key expires, causing many concurrent requests to hit the backend database simultaneously. This can be mitigated in Redis by using distributed locking or setting long expiration times with background refresh mechanisms to ensure the cache remains populated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'463c164b-4522-42fb-beb1-c7544f7685d8', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How does API documentation impact the long-term maintainability of an architecture?', N'Senior', N'API documentation serves as the ''single source of truth'' and a contract between providers and consumers. Using machine-readable formats like OpenAPI allows for automated generation of SDKs, test suites, and mock servers, which significantly reduces integration friction and prevents documentation drift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'773a803a-f485-497e-aaaa-c755427c814f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of vectorized operations in R.', N'Junior', N'Vectorization allows R to perform mathematical operations on entire arrays or vectors at once without requiring explicit loops. This makes code more readable and significantly more efficient because the underlying operations are executed in optimized compiled code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f533b57-6c50-4a78-b878-c75b13623b67', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the advantage of using ''Changesets'' in Ecto for data integrity?', N'Middle', N'Changesets provide a unified way to handle data casting, validation, and constraint checking before data is persisted. They act as a functional layer that ensures only valid data is sent to the database, preventing invalid states and providing clear feedback on validation errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
