INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f63d5384-131c-4a4d-8663-c760820eda12', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between fixing a bug quickly versus implementing a long-term solution?', N'Fresher', N'I would evaluate the severity and impact of the bug on the end users. If it is a critical blocker, a temporary hotfix might be necessary to restore service, but I would always track a follow-up task to implement the robust, long-term fix later. The decision balances immediate availability with technical debt management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3d7358e-c232-4145-bc5a-c76132713103', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js event loop handle CPU-bound tasks, and what are the architectural implications of blocking it?', N'Senior', N'The event loop runs on a single thread; therefore, CPU-bound tasks block it, preventing the handling of incoming I/O requests. This results in increased latency and potential application unresponsiveness. For heavy computation, offloading to Worker Threads or external microservices is necessary to maintain event loop health.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43a35d16-63e8-4163-ba47-c7674bd6b001', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'In Qwik, what is a component store?', N'Junior', N'A store is a reactive object used to manage the component''s state. When a property inside the store changes, Qwik automatically tracks the dependency and updates only the specific parts of the DOM that rely on that data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbf11c43-fc79-42b9-a603-c769bac11959', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for evaluating a new technology or library before integrating it into a production system?', N'Middle', N'I assess the library''s community support, documentation quality, and release frequency to ensure long-term viability. I also create a small proof-of-concept to test how it integrates with our existing stack and evaluate its impact on performance and security. This helps identify potential deal-breakers early before committing to a larger architectural dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
