INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef35783-a38f-494e-938a-c779565dabb5', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the primary paradigm that Scala supports?', N'Fresher', N'Scala is a multi-paradigm programming language that combines object-oriented and functional programming. It treats every value as an object and every function as a value, allowing developers to choose the best approach for a given problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58655766-abe4-4389-90ec-c77b76a83a78', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between a dynamic module and a static module?', N'Junior', N'A static module is defined entirely at compile-time with fixed configuration. A dynamic module allows you to pass configuration options at runtime, which is useful for modules that need settings like database credentials or API keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e47c286c-696e-439f-baff-c77d840eb5aa', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain why the following doesn''t work as an IIFE: function foo(){}();. What needs to be changed to properly make it an IIFE?', N'Fresher', N'The code function foo(){}(); doesn''t work as an Immediately Invoked Function Expression (IIFE) because the JavaScript parser treats function foo(){} as a function declaration, not an expression. To make it an IIFE, you need to wrap the function in parentheses to turn it into a function expression: (function foo(){})();. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d7d6afb-0b13-412c-9371-c77e359601d0', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''flatMap'' and ''map'' operations?', N'Middle', N'Map transforms each element into a new value, resulting in a collection of the same size. FlatMap transforms each element into a collection and then flattens all those resulting collections into a single, unified collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd30f16e3-97f6-4135-9b43-c783c57a8454', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of Tower in the Axum ecosystem, and why is this architectural choice significant?', N'Senior', N'Tower provides the foundational abstraction for modular, asynchronous services in Rust. By building on Tower, Axum gains interoperability with a vast ecosystem of middleware, allowing developers to compose complex service stacks that handle timeouts, retries, and rate limiting uniformly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaa8b491-655b-4e40-bb14-c7842e5ce7d8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle static files?', N'Intern', N'Express provides a built-in middleware function called express.static to serve static files such as images, CSS files, and JavaScript files. It maps a directory to a URL path, allowing the server to directly send these files to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db01ced-df22-4e8a-a26e-c7843ae15bda', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Can Fastify be used for building microservices?', N'Intern', N'Yes, Fastify is excellent for building microservices due to its small footprint, high performance, and modular plugin architecture. These features allow developers to create lightweight, maintainable services that can easily communicate with each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b372024-d1fe-4e17-ac5d-c787195a39ca', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Does Hono support HTTP/2?', N'Intern', N'The support for HTTP/2 depends on the underlying runtime or platform where Hono is deployed. Hono itself focuses on the application layer, while the network protocol is handled by the edge platform or server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74817fe1-b662-4c78-a5b5-c78ac5bd1422', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How is responsive design different from adaptive design?', N'Fresher', N'1) Responsive design uses CSS media queries to change styles based on the target device such as display type, width, height, etc., and only one of these is necessary for the site to adapt to different screens. Responsive doesn''t offer as much control as adaptive, but takes much less work to both build and maintain. Responsive layouts are also fluid and whilst adaptive can and do use percentages to give a more fluid feel when scaling, these can again cause a jump when a window is resized. 2) Adaptive design uses static layouts based on breakpoints which don''t respond once they\’re initially loaded. Adaptive works to detect the screen size and load the appropriate layout for it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9860829-41bc-4aeb-a373-c78e9dbe14ed', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the ''Gap Lock'' in InnoDB?', N'Senior', N'Gap locks prevent the insertion of new records into the gap between index entries to maintain strict isolation. While essential for preventing phantom reads in REPEATABLE READ, they are a frequent source of deadlocks in high-concurrency environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8f0a435-fd54-42e5-aa17-c78f44861645', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle deletions?', N'Fresher', N'Cassandra uses ''tombstones'' to handle deletions. Instead of removing data immediately, it marks it with a tombstone, which is later removed during the compaction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
