INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da400b1f-8783-444c-9ae7-c78ffb748ad9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of the ''c'' variable in Hono handlers?', N'Fresher', N'The ''c'' variable stands for context. It is the primary interface for interacting with the request data and the response object within a route handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37bc0526-3036-4b4a-be7b-c79219918b3a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s method dispatch mechanism interact with the search path?', N'Senior', N'When a generic function is called, R searches for an applicable method based on the class of the arguments by traversing the search path and package namespaces. This dynamic dispatch allows for highly extensible polymorphic behavior, but can lead to ambiguity if multiple packages define methods for the same class and generic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66a4ad66-57ce-4f75-a412-c7934f19b1b4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik suitable for large-scale applications?', N'Fresher', N'Yes, Qwik is designed to be scalable. Its ability to load code incrementally means that as an application grows, the performance impact remains minimal because users only load the code for the parts of the app they actually use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
