INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'522b2233-66c3-4e34-83d1-c7942d16cd90', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do Middleware components intercept requests in Actix-web?', N'Senior', N'Middleware in Actix-web wraps the request-response cycle by implementing specific service traits that allow for pre-processing of incoming requests and post-processing of outgoing responses. They form a chain of responsibility, enabling cross-cutting concerns like logging, authentication, and compression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
