INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e50ec253-b087-4c3c-82d4-c794dcaf60b8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach capacity planning for a system expecting a significant spike in traffic?', N'Middle', N'I use historical metrics and load testing to simulate the expected traffic volume and identify the system''s breaking point. Based on these findings, I scale resources ahead of the event and implement traffic shaping techniques like queuing or load shedding to protect core services. Monitoring real-time telemetry allows for active adjustment as the load increases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
