INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d602fe3-78bc-47bb-87f8-c7a0589e97a9', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your strategy for testing a system''s resilience to infrastructure failure?', N'Senior', N'I would employ chaos engineering principles by intentionally injecting failures like network latency, pod kills, or node termination in a controlled production-like environment. This validates the system''s automated recovery mechanisms and exposes hidden dependencies that could cause downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
