INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'175e66b4-981b-46df-9a45-c7a6674c1791', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s store implementation achieve decoupling from the component model?', N'Senior', N'Svelte stores are simple objects implementing a contract with a subscribe method. This allows state management to exist entirely outside the component tree, making them highly testable, framework-agnostic, and easy to integrate into non-component logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
