INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a09eb318-81b0-4bd2-aee6-c7a9cde8c30f', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why should you avoid using ''z-index'' with large integers?', N'Middle', N'Using excessively large z-index values, such as 9999, often indicates a lack of understanding of the stacking context, leading to ''z-index wars'' where developers try to outbid each other to get an element on top. It makes the code brittle and difficult to maintain when new UI elements are introduced. It is better to manage stacking contexts explicitly using parent containers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91372b4d-04c3-44a2-867d-c7ab5c521961', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a Plug in the Phoenix framework?', N'Junior', N'A Plug is a specification for composable modules that sit between the web server and the application. They are used to transform the connection object, perform authentication, or log requests as they pass through the pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87275323-018b-4ed2-b290-c7ad26647dc3', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a ''type alias'' and how does it affect type safety?', N'Middle', N'A type alias provides an alternative name for an existing type, making complex signatures more readable. It does not create a new, distinct type, so it does not improve type safety, but it significantly improves code clarity and maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85007526-d01c-42b8-8b4f-c7af41e4efdd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is an Angular ''Resolver'' and when should it be used?', N'Middle', N'A Resolver is a route guard that fetches data before a route is activated. It is used to ensure that a component has all the necessary information before it is rendered, preventing the display of empty states or flickering content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'253c14cd-3edd-4c59-a9c2-c7b0bd9bc7ce', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why is it difficult to implement self-referential structures in safe Rust?', N'Senior', N'Safe Rust forbids self-referential structures because the borrow checker cannot guarantee that the interior references remain valid if the outer structure is moved in memory. Since moving an object changes its memory address, any internal pointer would become dangling, violating the fundamental memory safety guarantees of the language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26168030-d599-4a96-ba7e-c7b0f413e4a7', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the Node.js event loop handle ''process.nextTick'' compared to ''setImmediate''?', N'Senior', N'process.nextTick queues a callback to be executed immediately after the current operation completes, regardless of the current phase of the event loop. In contrast, setImmediate schedules a callback to be executed in the check phase of the next iteration of the event loop, allowing for I/O tasks to process in between.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce0c572e-5512-4dfe-919e-c7b1218d66d5', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the benefit of using ''template'' indices in Elasticsearch?', N'Middle', N'Index templates allow you to define default settings and mappings that are automatically applied to new indices matching a specific naming pattern. This ensures consistency across time-series indices without manual configuration for every new index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
