INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8845f7a2-7715-40be-9cb5-c7c17fab70a2', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the advantage of using Remix over a simple React app?', N'Fresher', N'Remix handles data loading and routing at the framework level, whereas a basic React app requires additional libraries to manage these concerns. Remix also provides better performance out of the box through server-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3636beed-6b74-49c9-9143-c7c35adb87c7', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach database schema migrations in a high-availability environment where downtime is not acceptable?', N'Middle', N'I would use a multi-step deployment strategy where schema changes are additive and backward-compatible. This involves applying changes in stages—such as adding a new column before removing the old one—allowing the application code to be updated incrementally while ensuring that both old and new versions of the application can interact with the database simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76b8e315-c1ff-4e40-85e4-c7c465d6c75d', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the restrict keyword, and how does it assist the optimizer?', N'Senior', N'The restrict keyword is a type qualifier that tells the compiler that a pointer is the sole means of accessing the object it points to for the duration of the pointer''s scope. This eliminates the need for the compiler to assume potential memory overlap, allowing it to perform much more aggressive optimizations such as loop vectorization and instruction scheduling. It effectively informs the compiler that it can safely cache values without worrying about side effects from other pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
