INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e15a66-9e59-4778-ae7c-c7c5e1a7963c', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the concept of an ''Anti-Corruption Layer'' (ACL) in microservices.', N'Middle', N'An ACL is a translation layer placed between two services to prevent the data model of one service from leaking into another. It ensures that changes in a legacy or external system do not force breaking changes on the internal domain model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
