INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5256f9b-7cbf-449e-8356-c7ce4a4a21c0', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik maintain SEO benefits while implementing aggressive lazy loading?', N'Senior', N'Because Qwik renders the full HTML on the server and serializes the application state into the document, search engine crawlers receive a fully functional, content-rich page immediately. The lazy loading mechanism only affects post-load interactivity, meaning SEO performance remains unaffected by the deferred loading of JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
