INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ba865d1-36aa-491d-ad5d-c7d0021c8b51', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is the use of the x-cloak directive recommended in Alpine.js?', N'Middle', N'The x-cloak directive is used to prevent the ''flash of unstyled content'' that can occur while the browser is loading the Alpine.js script. It hides elements until the framework has initialized and processed the page, ensuring a smooth user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9db779e-36df-4f3b-8408-c7d03627268e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why does Kotlin favor composition over inheritance, and how does the language facilitate this?', N'Senior', N'Composition is favored because it avoids the tight coupling and fragile base class problems inherent in deep inheritance hierarchies. Kotlin supports this through features like class delegation, extension functions, and interface-based design, which allow functionality to be added to objects without requiring a rigid taxonomic structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0125c7e3-9010-4fc2-854e-c7d0780d4051', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is a ''Context'' in Go and how does Chi use it?', N'Intern', N'A Context is a standard Go package used to carry deadlines, cancellation signals, and request-scoped values across API boundaries. Chi uses the request context to store and retrieve URL parameters and other metadata parsed from the route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'735609f6-ac27-44df-a65c-c7d0e214a0b6', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of an associative array in PHP?', N'Intern', N'An associative array is a data structure in PHP that uses named keys instead of numeric indices to store and access values. This makes it highly efficient for mapping specific labels or identifiers to data, similar to a dictionary or hash map.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4a35648-3bb9-420f-85de-c7d164255494', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the concept of ''Context Bounds'' and their relationship to type classes.', N'Senior', N'Context bounds are syntactic sugar for implicitly passing a type class instance to a function, allowing for clean, generic interfaces. They decouple the algorithm from the implementation details of the data type, enabling the ad-hoc polymorphism that is central to idiomatic functional programming in Scala.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'066b6772-49cd-4bfd-9591-c7d1ae60848c', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is type juggling in PHP?', N'Fresher', N'Type juggling is the automatic conversion of a variable from one data type to another based on the context in which it is used. For example, PHP may convert a string containing a number into an integer during a mathematical operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65fe0920-f833-43a8-8283-c7d305925ad8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between uneval and eval', N'Fresher', N'The uneval function returns the source of a given object; whereas the eval function does the opposite, by evaluating that source code in a different memory area. Let''s see an example to clarify the difference,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c4df9a5-3d13-4e8c-bcb8-c7d40f4c3b09', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between authentication and authorization?', N'Intern', N'Authentication is the process of verifying a user''s identity, such as logging in with a username and password. Authorization is the process of determining what an authenticated user is permitted to do, such as accessing a specific page or editing a post.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc03bf51-c868-4d2b-a4d0-c7d5e1d62291', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis hash?', N'Intern', N'A Redis hash is a data type that maps fields to values, making it perfect for representing objects. It is similar to a dictionary or an associative array where you can store multiple attributes under a single key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c55f7a1-4ea2-4de5-82af-c7d5e65cd966', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .show() and .fadeIn()?', N'Junior', N'.show() immediately changes the CSS display property to make an element visible. .fadeIn() gradually changes the opacity of an element over a specified duration to create a smooth animation effect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63ceab5a-a9c3-4dad-b08b-c7d9089784e9', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''include'' versus ''require'' statement?', N'Junior', N'Both statements pull in external files, but they differ in how they handle errors. If the file is not found, ''include'' generates a warning and allows the script to continue, whereas ''require'' triggers a fatal error and stops execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6600cbf3-10a7-4593-97d2-c7db7d7ad2b9', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between assignment operators ''='' and ''<-''?', N'Fresher', N'While both can be used to assign values, ''<-'' is the standard assignment operator in R and is preferred for its clarity and scope. The ''='' operator is generally reserved for passing arguments within functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ccadd76-f3bc-450e-8851-c7df174d74bd', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of middleware in a Flask application, and how does it differ from decorators?', N'Middle', N'Middleware acts as a wrapper around the entire WSGI application, allowing you to intercept and modify requests and responses globally before they reach Flask. Decorators are applied specifically to individual routes or view functions, providing more granular control over specific endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'082b2916-6e09-4fbe-8ca0-c7e3915a5197', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the trade-offs of using DynamoDB Streams for event-driven architecture?', N'Senior', N'Streams provide a time-ordered sequence of item-level modifications, enabling decoupled microservices and cross-region replication. However, they introduce additional latency and require careful management of shard consumers to prevent throughput bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba78d2b9-0775-4d32-b654-c7e3ab50961a', N'954a0331-deff-4399-b588-96f39fec001d', N'What happens if you use script tag inside template?', N'Junior', N'Angular recognizes the value as unsafe and automatically sanitizes it, which removes the script tag but keeps safe content such as the text content of the script tag. This way it eliminates the risk of script injection attacks. If you still use it then it will be ignored and a warning appears in the browser console. Let''s take an example of innerHtml property binding which causes XSS vulnerability,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9c3d4c2-78d0-403b-9f59-c7e422b2d796', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Describe the trade-off of using FastAPI''s automatic request validation.', N'Middle', N'The main trade-off is the overhead of schema validation and serialization performed by Pydantic on every request. While this adds a minor latency penalty, it significantly improves code maintainability and reduces bugs by ensuring data integrity before business logic is processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9eda546-0eb7-4653-81cb-c7e462115d63', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s ''Mixins'' work, and why are they considered a legacy pattern in favor of composition?', N'Senior', N'Mixins merge methods and properties into a class, which can lead to name collisions and difficulty tracing the origin of behavior. Composition, through components or utility functions, is now preferred because it offers more predictable behavior and better code clarity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39fa6e9c-64c2-4433-80ad-c7e60286a0c9', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''Context'' in SolidJS?', N'Middle', N'Context provides a way to pass data through the component tree without prop drilling. It is inherently reactive, meaning that if the value provided by the context changes, all consuming components will automatically update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efd7af77-bbc8-48f6-a0fb-c7e7e82427f7', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik sometimes described as a ''server-first'' framework?', N'Middle', N'It is called server-first because the server does the heavy lifting of rendering and state preparation, while the client is essentially a thin execution environment. The framework is designed to move the complexity of initializing the application to the server, resulting in a lightweight client experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ea15967-d309-42b3-822e-c7e890b993ae', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Symfony Events and Listeners?', N'Fresher', N'Events and Listeners implement the Observer pattern, allowing different parts of the application to communicate without being tightly coupled. A listener performs an action when a specific event occurs, such as a user logging in or a request being handled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79026b63-085e-4ba5-90e2-c7eb22a5f9ec', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono mitigate the overhead of serializing and deserializing JSON payloads in serverless functions?', N'Senior', N'Hono provides optimized built-in JSON parsing and serialization helpers that leverage native runtime capabilities. By keeping the middleware stack lightweight and minimizing object transformation, it reduces the cold-start and execution time overhead in ephemeral environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c05e95ae-5e92-4d09-b05a-c7ecf7330820', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the difference between an inner join and a left join in terms of result sets?', N'Middle', N'An inner join returns only the rows where there is a match in both participating tables. A left join returns all rows from the left table and the matched rows from the right table, filling with nulls if no match exists, which is critical for identifying records that lack corresponding data in related tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75b5ad75-e1aa-454f-9a38-c7edfe07a90b', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'When would a senior architect choose a custom router over Chi?', N'Senior', N'A custom router might be chosen only when the application requires highly specialized routing logic, such as dynamic, runtime-defined routes that change based on database state. For 99% of web applications, Chi’s flexibility and performance provide the optimal balance, making custom implementations unnecessary and harder to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e15a349a-4641-4068-be16-c7ee265d2bcd', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do ''Template Literal Types'' impact the performance and static analysis capabilities of a TypeScript compiler?', N'Senior', N'Template literal types allow for string manipulation at the type level, effectively enabling domain-specific language creation within types. While powerful, overly complex nested template types can significantly increase compilation time due to the complexity of the type inference engine''s recursive resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0848581e-5c3e-4955-bd82-c7efdd708417', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the purpose of the ''ParamConverter'' in Symfony.', N'Middle', N'The ParamConverter automatically resolves request parameters into objects, such as fetching a database entity based on an ID in the route. It simplifies controller logic by handling the boilerplate of database lookups and potential 404 error triggering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f4b6e38-912d-4171-9d63-c7f6476aabf6', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the significance of the Quarkus ''Build Time'' boot concept?', N'Senior', N'Build-time boot allows the framework to configure extensions and integrate dependencies during the packaging phase. By locking down the application state and object graph before the executable is created, Quarkus avoids runtime dynamic class loading, significantly reducing memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1737470d-73a2-4a12-b3a6-c7f6656d00d1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle routing compared to basic Go approaches?', N'Junior', N'Fiber provides a robust routing engine that supports path parameters, wildcards, and regex, making it easier to define complex API structures. It allows developers to group routes under common prefixes, which simplifies code organization and middleware application for specific URL paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'defdd271-c2c4-4d3e-a201-c7f6b7cd0ba2', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the purpose of the ''Context'' object in an Actix actor.', N'Middle', N'The Context object represents the execution environment for an actor. It allows the actor to manage its own lifecycle, schedule delayed messages, spawn other futures, and communicate with other actors via addresses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aff7712d-7a72-4e31-97c2-c7f80602d720', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do you manage complex race conditions in Redux during asynchronous operations?', N'Senior', N'Managing race conditions often involves tracking request status in the store, using cancellation tokens, or utilizing Redux-Saga''s effect creators like ''takeLatest''. These patterns ensure that only the result of the most recent or relevant action is applied to the state, preventing stale data from overwriting newer updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'418ec58b-3b05-4adc-a36b-c7fa1297d915', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is ''Cache Stampede'' and how can it be mitigated?', N'Middle', N'Cache Stampede occurs when a popular key expires, causing multiple concurrent requests to simultaneously miss the cache and overwhelm the underlying database. It can be mitigated using request collapsing, mutex locks, or implementing probabilistic early expiration to refresh the key before it technically expires.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f0c50c8-5a8d-41d3-b6d1-c804604a9f85', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is ''Secure by Design'' a fundamental principle for senior software architects?', N'Senior', N'Secure by design implies that security is considered during the initial requirements and architectural phases rather than as an afterthought. It reduces the cost of remediation, prevents fundamental design flaws, and ensures that security requirements are foundational to system performance and functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60c39514-33cc-454c-ad29-c805c0d805e4', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the use of the gets function considered dangerous?', N'Middle', N'The gets function provides no way to limit the number of characters read, making it inherently vulnerable to buffer overflows. Because it does not know the size of the destination buffer, an attacker can input more data than the buffer can hold, leading to potential security exploits by overwriting return addresses or memory data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db718f55-4c54-4955-b5b2-c80aeae5f2de', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What impact does the ''optimizeDeps'' configuration have on build performance?', N'Senior', N'The optimizeDeps configuration allows developers to force Vite to pre-bundle specific dependencies that might otherwise be missed or cause issues. Fine-tuning this ensures that the dev server remains responsive and avoids slow on-the-fly transformations of complex packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d1e9650-f394-4d1b-b17a-c80ba025a52a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize ''Time to Interactive'' compared to SSR frameworks?', N'Middle', N'Standard SSR frameworks require the browser to download and execute all JavaScript before the page is fully interactive. Qwik eliminates this requirement by serving static HTML that is already ''ready'' to respond to events without requiring a full hydration phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03738625-5294-4f53-b15c-c80ded5f4302', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is an aggregation pipeline in MongoDB?', N'Fresher', N'An aggregation pipeline is a framework for data aggregation modeled on the concept of data processing pipelines. Documents enter a multi-stage pipeline that transforms the documents into aggregated results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93cac77c-f977-47ca-8a87-c80ee9bbd666', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the benefit of using ''async def'' instead of ''def''?', N'Intern', N'Using ''async def'' allows the endpoint to run concurrently, preventing the server from blocking during long-running tasks like database queries or network requests. Standard ''def'' functions run synchronously and block the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02956911-f41f-45f4-9b47-c80f7fca02ee', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why should you be cautious when using third-party middleware with Fiber?', N'Middle', N'Since Fiber''s context is not compatible with the standard library''s context, many standard middleware packages will fail to compile or function correctly. Developers must either use Fiber-specific middleware or write wrappers to map standard library interfaces to Fiber''s internal context structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'703a3686-e712-421e-acd4-c8100563fac1', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Describe the trade-offs of using ''Reflection'' in Scala for library development.', N'Senior', N'Reflection allows for runtime inspection and manipulation of types, which is powerful for generic serialization or dependency injection frameworks. However, it is slow, bypasses compile-time type safety checks, and can be fragile when dealing with complex generic types. In modern Scala, reflection is increasingly replaced by compile-time metaprogramming to maintain performance and type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d1f2e67-c4b9-42b2-bda4-c813d1290865', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the impact of unbounded document growth in MongoDB?', N'Senior', N'MongoDB documents are stored on disk with a specific size allocation; if a document grows beyond its allocated space due to updates, the database must relocate the document to a new location. This causes fragmentation and expensive I/O operations, which can significantly degrade write performance over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81b6b96f-4d89-4ae3-87ee-c813ffebe72a', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How can you optimize API responses for mobile clients?', N'Middle', N'Mobile optimization involves minimizing payload size, using compression like Gzip or Brotli, and reducing the number of round-trips. Providing tailored endpoints or using GraphQL can help ensure mobile devices only receive the data they strictly need.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d4423ae-e3cd-41d2-a864-c8145e27d496', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''Partial Hydration'' in the context of SolidJS SSR?', N'Senior', N'Partial hydration involves sending static HTML from the server and only attaching reactive listeners to the specific parts of the DOM that are interactive. This minimizes the amount of JavaScript sent to the client, significantly improving Time to Interactive metrics compared to full-page hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c923b758-f906-4037-be59-c8163aa6854a', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary difference between a traditional OS thread and a fiber in the context of concurrency?', N'Middle', N'OS threads are managed by the kernel and involve expensive context switching and large stack memory allocation. Fibers are lightweight threads managed by the runtime or user space, allowing for much faster context switching and the ability to spawn thousands of concurrent tasks with minimal memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a3b1045-3cc8-4043-9bec-c81d1e8a074c', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring''s AOP proxying work, and what are the limitations of JDK Dynamic Proxies versus CGLIB?', N'Senior', N'Spring AOP uses JDK Dynamic Proxies when the target class implements interfaces, while it uses CGLIB to subclass the target when no interfaces are present. JDK proxies are restricted to interface methods, whereas CGLIB cannot proxy final classes or final methods, which can lead to unexpected behavior in specific design patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
