INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a168a94-d4eb-4d3f-9b0e-c82930e6a58e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s null safety mechanism differ from traditional Java null handling?', N'Middle', N'Kotlin enforces null safety at compile-time by distinguishing between nullable and non-nullable types in the type system. This forces developers to handle potential null values explicitly before accessing members, effectively eliminating most NullPointerExceptions before the code even runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
