INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bc9a6cd-3214-4337-a78b-c82fb24ceadb', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the primary purpose of the Java Virtual Machine?', N'Intern', N'The Java Virtual Machine acts as a bridge between the compiled Java code and the underlying hardware. It interprets bytecode and executes it, allowing Java to be platform-independent by ensuring the same code runs on any system with a JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83973637-4ccc-4daa-a543-c83155ab1fac', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you perform conditional rendering in Lit?', N'Junior', N'Conditional rendering is achieved using standard JavaScript ternary operators or logical AND operators within the template literal. Lit directives like ''when'' can also be used to make complex conditions more readable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9221e23-6556-4d72-a265-c8396cee94d6', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do you handle schema evolution in a schemaless NoSQL database?', N'Middle', N'In a schemaless database, schema evolution is handled at the application level rather than the database level. Developers must write code that can handle different versions of documents simultaneously, often employing strategies like application-side transformation or lazy migration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e75c5c7-abc3-4d92-9e93-c83cb095aba8', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When evaluating a new cloud service, how do you estimate the transition cost and vendor lock-in risk?', N'Senior', N'I calculate the effort to migrate data and refactor application logic to integrate with the new service. I assess the difficulty of extracting data or moving to a competitor in the future, comparing the immediate operational convenience against the long-term strategic flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e6bdc21-ba73-4601-8f85-c842a3385020', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why use the ''apply'' family of functions?', N'Junior', N'The apply family of functions is used to perform repetitive tasks on structures like lists or matrices without using explicit loops. They provide a more functional and efficient approach to data manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'963fd520-06a7-45b2-bdd8-c844ec5e1642', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the benefit of using structured logging over plain text logging?', N'Middle', N'Structured logging outputs logs in a machine-readable format like JSON. This makes it significantly easier to query, aggregate, and visualize data in observability tools, enabling faster root cause analysis during incidents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23d0ff9d-bfd0-44a9-a839-c845d7bf05a5', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''bool'' query work for complex searches?', N'Middle', N'The bool query is a compound query that combines multiple query clauses using must, should, must_not, and filter blocks. It allows for sophisticated logic, such as requiring certain terms, scoring based on relevance, and filtering results without affecting the relevance score.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac098105-e218-40ba-a549-c846c2f8d60d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the performance implication of using many layers of middleware in a Chi application?', N'Middle', N'Each layer of middleware adds a small amount of overhead to the request cycle due to function invocation and context wrapping. While minimal, excessive middleware depth can increase latency, so it is important to only include necessary layers and avoid redundant operations in the request path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d0de732-18bb-4a99-a768-c8497f73473d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a filter context in search queries?', N'Junior', N'Filter context is used for binary questions, such as whether a field matches a value, and does not affect the relevance score. Filters are often faster than queries because they can be cached by Elasticsearch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a6f255d-5642-4925-a9e1-c84efac2ef45', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is ''hydrating'' a component?', N'Intern', N'Hydration is the process of attaching JavaScript event listeners and state management to static HTML after it has loaded in the browser. It makes the static elements interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd97bd244-d68d-4682-8f06-c84f07310c97', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the best way to handle database connection pooling in a Flask application?', N'Middle', N'Database connection pooling is typically managed by the database driver or an ORM extension like Flask-SQLAlchemy. It prevents the overhead of creating a new connection for every request by maintaining a set of open connections that are reused across requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c59bad2a-2d51-4af7-851c-c851b5820225', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the advantages of using MongoDB?', N'Intern', N'Key advantages include high flexibility due to its document model, ease of scaling horizontally via sharding, and high performance for read and write operations. It is particularly well-suited for applications with rapidly changing data requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6af09eb5-373a-4909-b84f-c8527c9e6216', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'When should you use the ''updated'' lifecycle callback versus the ''firstUpdated'' callback?', N'Middle', N'firstUpdated is called only once after the component has rendered for the first time, making it ideal for one-time initialization tasks. The updated callback runs after every render, making it suitable for actions that need to react to subsequent property changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19e8ce7f-0479-4bf4-a3ce-c85888dc8efa', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What does the term ''Islands Architecture'' mean in Astro?', N'Intern', N'Islands Architecture is a pattern where static HTML pages are rendered on the server, and interactive UI components are hydrated individually. This allows parts of the page to remain static while others become dynamic, reducing the overall JavaScript load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9253667a-3895-4b3c-8ef2-c85db75d0e73', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'When would you prefer using a Custom Hook over a Higher-Order Component (HOC) for logic reuse?', N'Senior', N'Custom hooks are generally preferred because they avoid ''wrapper hell'' and do not introduce extra nodes into the component tree. They allow for better type safety, easier testing, and clearer separation of concerns without the complexity of component composition patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d0ae0d7-d0e7-4bb6-8065-c861a6dbf645', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the challenges of maintaining persistent database connections in PHP?', N'Senior', N'Because PHP processes are short-lived, maintaining a persistent connection pool is difficult. While the ''pconnect'' feature exists, it can lead to connection exhaustion on the database server if the number of PHP-FPM workers exceeds the database''s connection limit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2abaf44-d9ce-4c6a-8342-c8633535398e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your approach to monitoring and alerting for a distributed system?', N'Middle', N'I would implement a ''Golden Signals'' approach, focusing on latency, traffic, errors, and saturation. I would use centralized logging, distributed tracing to visualize request flow across services, and set up threshold-based alerts that are prioritized to avoid alert fatigue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67adce0f-4fec-4802-b1a2-c8648386e967', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the importance of logging in a production application?', N'Junior', N'Logging provides a record of application events, which is essential for diagnosing issues after they occur in production. Without logs, it would be extremely difficult to trace the sequence of events that led to a specific error or crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eff7a63-dee1-416e-b1b7-c864bc1e4387', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle CSS and why is it more efficient than traditional approaches?', N'Senior', N'Next.js supports CSS Modules and Tailwind CSS, which are processed at build time to output optimized, scoped CSS. By only injecting the CSS required for the specific page being viewed, it reduces the payload size and prevents style conflicts common in global stylesheet architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe464eb7-1466-491a-95cf-c8686ddff505', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle WebSocket upgrades, and how does it integrate with the router?', N'Senior', N'Axum provides a ''WebSocketUpgrade'' extractor that handles the protocol handshake and upgrades the connection to a full-duplex stream. This is integrated directly into the routing table, allowing specific paths to be designated for WebSocket traffic while maintaining standard HTTP behavior for other routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dae59d65-e85a-4d54-a58d-c86ac1ad4ea3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Describe the difference between Symfony''s ''Compiler Passes'' and ''Service Decorators'' in terms of service modification.', N'Senior', N'Compiler passes are used during the build phase to manipulate the container definition globally, such as registering tagged services. Service decorators are used to wrap existing services at runtime to extend or modify their behavior without replacing the original implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9303513-0ec1-4359-a6ac-c86b273e571f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of Rocket''s ''State'' management?', N'Intern', N'Rocket''s managed state allows you to share data across different parts of your application. You can register types at launch, and handlers can request access to that data as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29f72099-9c06-447c-84a6-c86cb34db1f9', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does the ''trust proxy'' setting in Express affect security in a cloud-native environment?', N'Senior', N'When ''trust proxy'' is enabled, Express trusts the X-Forwarded-* headers provided by the load balancer to determine the client''s original IP and protocol. If misconfigured, an attacker could spoof these headers to bypass rate limits, security filters, or geolocation restrictions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c93f8ec-77a8-4e11-8c65-c86e65628753', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What role does database partitioning play in disaster recovery and high availability?', N'Senior', N'Partitioning allows for smaller, more manageable data units that can be backed up or restored independently, reducing recovery time objectives. Furthermore, if a single partition fails, the rest of the database remains operational, limiting the blast radius of a failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ddbfb30-2d07-4b05-8330-c8703fba94d5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does the DROP command do?', N'Intern', N'The DROP command is used to permanently remove an entire database object, such as a table or index, from the database. This action cannot be easily undone and deletes both the structure and the contained data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'635f611b-6e83-4646-b7ce-c8736a84b5cd', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle URL parameter extraction compared to a standard net/http ServeMux?', N'Senior', N'Standard ServeMux lacks native path parameter support, requiring manual parsing of the request URI. Chi integrates parameter extraction directly into the routing tree, exposing captured values via the request context, which reduces overhead and simplifies controller logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73da0c86-dec8-4272-9bde-c87640c1d61b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does error handling work in Axum handlers?', N'Junior', N'Error handling is typically done by returning a Result type where the error type implements IntoResponse. This allows developers to map internal application errors to specific HTTP status codes automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05b2d14d-85b3-4935-b3da-c87896165f5a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Can SolidJS components be used inside React or other frameworks?', N'Middle', N'SolidJS components are distinct from React components and cannot be used directly inside them. Because they rely on a different reactivity model and compilation process, they require specific adapters if they are to be integrated into another framework''s ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
