INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66839c41-8e1b-46af-9bb2-c87bc1bca81d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript engine handle memory management, and what is the role of the garbage collector?', N'Middle', N'JavaScript uses an automatic garbage collection process, typically utilizing a mark-and-sweep algorithm. The engine periodically identifies objects that are no longer reachable from the root execution context and reclaims their memory, though developers must still be mindful of memory leaks caused by lingering references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa0b2ed4-8df1-41f5-931e-c880359dd263', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you notice that a specific database query is performing slowly, how would you approach optimizing it?', N'Junior', N'I would start by analyzing the query execution plan to identify bottlenecks like full table scans or missing indexes. Once identified, I would evaluate if adding an index or simplifying the query structure improves the performance without negatively impacting other operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
