INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9595fe9e-6e9a-49c8-a6be-c88300f54048', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the risk of using insecure direct object references (IDOR) in an API?', N'Middle', N'IDOR vulnerabilities occur when an application provides direct access to objects based on user-supplied input without verifying authorization. This allows an attacker to bypass authorization checks and access or modify data belonging to other users simply by changing an ID parameter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
