INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eb9f82e-8c96-44e1-88cf-c8885af4fa58', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of the virtual destructor in a base class?', N'Fresher', N'A virtual destructor ensures that when an object of a derived class is deleted through a pointer to the base class, the derived class''s destructor is called first. This prevents memory leaks and ensures proper cleanup of derived class resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25b00da7-bf52-4cdc-a54b-c889f15aca42', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between forced unwrapping and optional binding?', N'Fresher', N'Forced unwrapping uses an exclamation mark to access an optional value directly, which can cause a crash if the value is nil. Optional binding, such as using ''if let'' or ''guard let'', safely checks for a value before accessing it, avoiding crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
