INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77f6aabf-f50f-4a25-837c-c88f34ec0592', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the trade-offs of using Micronaut''s AOP implementation?', N'Middle', N'Micronaut''s AOP is implemented at compile-time, which offers superior performance over runtime proxies. However, this means that adding interceptors requires a recompilation, and you cannot easily apply AOP to third-party classes without a wrapper.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0259515-dfc7-4a5b-bedc-c8905f0eb4d2', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is meant by the term reactivity in Svelte?', N'Intern', N'Reactivity in Svelte refers to the framework''s ability to automatically update the DOM when the state of an application changes. When a variable is modified, Svelte detects the assignment and updates only the specific parts of the user interface that depend on that variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e888ef-0fd2-4d90-b188-c8909ff17998', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between absolute and relative paths?', N'Intern', N'An absolute path provides the complete URL to a file, including the protocol and domain. A relative path points to a file based on the location of the current file, making it more flexible when moving files within the same website.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dc3e244-f403-40bb-81bf-c891fbd6555d', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the architectural implication of using ''at-least-once'' vs ''exactly-once'' delivery semantics in a distributed system?', N'Senior', N'At-least-once delivery requires consumers to be idempotent because retries can result in duplicate processing. Exactly-once processing typically necessitates atomic commits or distributed transactions between the message broker and the consumer''s state store, which introduces significant latency and complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adfe1010-fcd5-41b0-9bef-c896baee4d6f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the drawback of declaring methods directly in JavaScript objects?', N'Intern', N'One of the drawback of declaring methods directly in JavaScript objects is that they are very memory inefficient. When you do that, a new copy of the method is created for each instance of an object. Example: Here, each instance variable emp1, emp2 has own copy of formatSalary method. However the formatSalary2 will only be added once to an object Employee.prototype. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c9f44cf-2eec-49de-a76f-c89875d688c3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you conditionally render components?', N'Fresher', N'In some cases you want to render different components depending on some state. JSX does not render false or undefined, so you can use conditional _short-circuiting_ to render a given part of your component only if a certain condition is true. If you need an if-else condition then use _ternary operator_.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b1cb0eb-9a55-4d22-ba96-c89ad14bf570', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of a TypeScript configuration file (tsconfig.json)?', N'Junior', N'The configuration file defines the compiler options for the project, such as target JavaScript version, strictness levels, and file inclusion patterns. It acts as the blueprint that tells the TypeScript compiler how to process and transpile the codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8e66872-14ed-4784-9470-c89da2489fc7', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle transaction propagation when calling a method annotated with @Transactional from within the same class?', N'Senior', N'Because Spring''s transaction management relies on AOP proxies, an internal method call bypasses the proxy and executes directly on the target instance. Consequently, the @Transactional annotation on the internal method is ignored, and the transaction context of the caller remains unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f27ea38-616b-4650-80a2-c8a03def65b2', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Does Webpack support TypeScript out of the box?', N'Fresher', N'No, Webpack does not support TypeScript directly. You need to use a loader like ''ts-loader'' or ''babel-loader'' to transpile TypeScript code into standard JavaScript that Webpack can bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
