INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28e21ef4-a8e3-485e-aaa9-c8a486ed793e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the trade-off between using Actix actors versus standard asynchronous handlers in Actix-web?', N'Senior', N'Actors are ideal for managing complex stateful workflows and background tasks, but they introduce overhead due to message passing and mailbox management. Standard async handlers are more performant for simple request-response cycles where state can be managed via shared application data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f8bf553-1bd6-4388-9559-c8a7545d4074', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the x-if directive, and how does it differ from x-show?', N'Intern', N'The x-if directive conditionally adds or removes an element from the DOM entirely based on an expression. In contrast, x-show only toggles the CSS visibility, keeping the element present in the DOM structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0d023df-7730-4617-8389-c8aa789b9b00', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does ''immutability'' mean in the context of Redux?', N'Intern', N'Immutability means that once a state object is created, it cannot be changed. To update the state, you must create a new object that includes the changes while keeping the rest of the data intact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f406690-8944-4cf3-931c-c8ab8d358a2a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How do GiST and GIN indexes differ in their use cases and underlying data structures?', N'Senior', N'GiST is a balanced tree-like structure supporting various data types and complex queries like geometric or range searches, while GIN is an inverted index optimized for multi-valued data like arrays or full-text search. GIN is generally faster for lookups but significantly slower for updates due to the overhead of maintaining the inverted lists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f748288a-8b26-4217-bb0a-c8ade1b66090', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis achieve high performance with data structures like Hashes and Sorted Sets?', N'Middle', N'Redis uses highly optimized, memory-efficient internal implementations for its data structures, such as ziplists and skiplists. These structures are designed to provide O(1) or O(log N) performance for common operations, minimizing memory overhead while maintaining speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5abfcdac-87c8-43cb-a7ba-c8af66bf0f8f', N'4c000000-0000-0000-0000-000000000005', N'How does data partitioning help with large-scale systems?', N'Middle', N'Data partitioning divides a large dataset into smaller subsets, allowing the system to distribute the I/O load across multiple servers. This prevents any single node from becoming a hotspot and allows the database to scale linearly with the amount of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e81783c-ed27-4613-8400-c8b2ec20b635', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of the ''search_type'' parameter in a query, specifically ''dfs_query_then_fetch''?', N'Senior', N'Standard search queries calculate relevance scores based only on local shard statistics, which can lead to inaccuracies. ''dfs_query_then_fetch'' first gathers global term frequencies from all shards to calculate more accurate scores, which is crucial for relevance in multi-shard environments at the cost of an extra network round trip.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c3fdc0a-e915-448d-ba99-c8b442b97437', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the primary difference between a process and a thread in Python?', N'Middle', N'A process has its own memory space and interpreter instance, allowing it to bypass the GIL and utilize multiple CPU cores for parallel execution. A thread shares the same memory space and is limited by the GIL, making it suitable for I/O-bound operations rather than CPU-intensive tasks. Processes have higher overhead for creation and inter-process communication compared to threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f545ce0d-b50a-43bc-acf6-c8b69f3a698c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a project deadline is realistic when you have never done the task before?', N'Intern', N'I would break the task into smaller, manageable sub-tasks and estimate the time required for each. I would then add a buffer for unforeseen complexity and check if the total duration aligns with the project timeline, while proactively asking a mentor for their input on my estimates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adcd8d76-ecf6-4a7c-8d40-c8bafa4c982e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''Rails.cache'' interface?', N'Middle', N'It provides a unified way to store and retrieve data across different caching backends like Memcached or Redis. This is used to cache expensive database queries, rendered view fragments, or computed values to reduce latency and server load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7d9cbb4-469d-4889-ba6a-c8bd9c3cb3e0', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Compare the performance implications of PHP''s copy-on-write (COW) mechanism during variable assignment.', N'Senior', N'COW allows PHP to optimize memory usage by using reference counting for variables. Data is only physically duplicated in memory when a modification is attempted on a shared value, which prevents unnecessary memory allocation during read-heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27a54cb6-d291-460d-8902-c8bdcfd89933', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you handle errors in FastAPI?', N'Intern', N'FastAPI provides an HTTPException class that allows you to raise errors with specific status codes and messages. When raised, the framework automatically catches these exceptions and returns a structured JSON response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
