INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f13e3c6-bb5c-4390-b054-c8ef177c3f67', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of Django middleware and how does it affect request processing?', N'Middle', N'Middleware is a series of hooks into Django’s request/response cycle that allows you to globally alter input or output. It processes requests before they reach the view and processes responses before they are sent to the client, which is ideal for tasks like authentication, logging, or session management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
