INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d71d791-c993-4e72-9b32-c908a0663967', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you ensure your Flask application is secure against Cross-Site Request Forgery (CSRF)?', N'Middle', N'You should use an extension like Flask-WTF, which automatically generates and validates unique CSRF tokens for forms. Ensuring that state-changing requests use proper HTTP methods and validating tokens prevents malicious sites from performing unauthorized actions on behalf of the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ea9580a-fef7-46c5-ae26-c90ef3da71a8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the primary disadvantages of the Two-Phase Commit protocol?', N'Middle', N'2PC is a blocking protocol, meaning if the coordinator fails, participants may be left in an uncertain state while holding locks. This can lead to significant latency issues and reduced availability in large-scale distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7907d3b8-529b-4ca3-be4c-c90f6b700cbd', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is transactional isolation level selection critical for system performance?', N'Senior', N'Higher isolation levels (like Serializable) prevent all anomalies but require extensive locking or snapshot management, which reduces concurrency. Lower levels (like Read Committed) increase performance by allowing more concurrent access, but the application must be designed to tolerate potential race conditions or dirty reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf3064b7-93fd-4eeb-81f0-c90fde9b85ac', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your strategy for managing secrets in a distributed environment?', N'Middle', N'I would use a dedicated secret management service, such as HashiCorp Vault or a cloud provider''s native solution, to inject secrets at runtime. Access should be restricted using identity-based policies, and secrets should be rotated automatically to minimize the impact of a potential credential leak.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
