INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'021e737f-15e8-41d4-b8ce-c921e57d194a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a system failure where logs are incomplete or missing due to the error itself?', N'Middle', N'I would rely on infrastructure-level metrics and external system snapshots, such as load balancer access logs, container health statuses, or database transaction logs. If logs are lost, I would implement better persistent logging or remote centralized logging to ensure that future failures are captured even if the service itself crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
