INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92a8bdfd-42c4-44e6-afa8-c9297489c4da', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between an optimistic and pessimistic locking strategy?', N'Middle', N'Pessimistic locking prevents others from accessing data while a transaction is in progress, which can cause contention. Optimistic locking assumes conflicts are rare and only checks for them during the final update, providing better performance in high-concurrency environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ce6d285-431a-4312-86da-c929aecbb2c2', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach observability in a system with hundreds of microservices?', N'Senior', N'I would focus on the three pillars: structured logging for traceability, metrics for health monitoring, and distributed tracing to follow request flows across boundaries. I would mandate correlation IDs across all services to enable stitching together logs and traces for effective root cause analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63515ecd-2bff-4e22-9090-c92aa6d5feb9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What does ASGI stand for and why does Litestar use it?', N'Intern', N'ASGI stands for Asynchronous Server Gateway Interface. Litestar uses it to handle asynchronous communication between web servers and Python web applications, allowing for high concurrency and non-blocking I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'539626dc-ac0e-42a7-9771-c92b264035b7', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a bug that you cannot reproduce on your local machine?', N'Intern', N'I would collect environmental details such as operating system version, browser settings, or specific user inputs from the reported environment. Then, I would attempt to mirror those exact conditions to replicate the issue in a controlled staging environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a45d1b2-ac8c-4b15-ab22-c92fb3da1236', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the lack of a standardized component lifecycle in jQuery affect the predictability of UI states?', N'Senior', N'Without a lifecycle, developers must manually manage initialization and teardown logic, which is prone to race conditions and missing cleanup steps. Modern component architectures provide clear entry and exit points, ensuring that side effects are strictly managed and resources are released correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f58998-9aca-4351-9541-c93403259fbe', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the technical impact of jQuery''s ''ready'' event on modern page load performance?', N'Senior', N'The document ready event waits for the DOM to be parsed but can delay script execution until everything is loaded, potentially blocking the main thread. Modern techniques prefer deferring scripts or placing them at the bottom of the body to allow the browser to parse the document asynchronously without blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92a41234-af82-4bc8-85cb-c9367b1fd66b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why does Elasticsearch recommend using ''Aliases'' for indices in production environments?', N'Senior', N'Aliases decouple the application logic from the underlying index name, allowing for zero-downtime index rotation or reindexing. This is critical for maintaining consistency while performing maintenance tasks or updating mappings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'549e2054-4f74-4545-ad3f-c9376c022db8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the function of the ''render'' method in Preact?', N'Intern', N'The ''render'' method is the entry point that takes a virtual node tree and inserts it into a real DOM element in the browser. It is responsible for the initial painting of the application onto the screen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41215176-ae99-4644-a98e-c93b5c9ac2cc', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the trade-off between readability and performance in software design?', N'Fresher', N'Readability is prioritized for long-term maintainability and reducing bugs, while performance is prioritized only when specific bottlenecks are identified. Generally, code should be clear and expressive first, and optimized only if profiling indicates it is necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06559344-58e9-4937-b678-c93bdba3573c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are Hono''s built-in hooks for lifecycle management?', N'Junior', N'Hono provides hooks like ''before'' and ''after'' that allow developers to run logic at specific stages of the request processing. These hooks help in executing repetitive tasks or validation without cluttering the main route logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da9a61ce-d1bc-4d22-b8ea-c93cbd8787cb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a distributed system, how do you handle the trade-off between consistency and availability during a network partition?', N'Middle', N'According to the CAP theorem, you must choose between consistency and availability when a network partition occurs. If the business requires data integrity above all, prioritize consistency by blocking requests, but if user experience and uptime are paramount, prioritize availability by serving potentially stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f3cb5ac-2d68-475d-ad34-c93cde0bdf03', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin provide support for cross-origin resource sharing (CORS)?', N'Middle', N'Gin does not have built-in CORS middleware, but it supports it by allowing developers to write custom middleware to set appropriate HTTP headers. This ensures that the server can safely communicate with browsers regarding permitted origins, methods, and headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84a84445-59f9-40f9-aa7b-c93d00469b86', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does ''ARC'' (Automatic Reference Counting) handle cyclical dependencies in Swift?', N'Senior', N'ARC does not automatically detect or break cycles, which is why developers must explicitly use weak or unowned modifiers to break strong reference chains. If a cycle is formed between objects, ARC will never see the reference count hit zero, causing a permanent memory leak unless manual intervention is applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c047c23-3b1d-4c1c-9a5d-c93d4d4f0481', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'In the context of the Echo framework, what is middleware and why is it used?', N'Intern', N'Middleware is a function that sits between the incoming HTTP request and the final route handler. It is used to perform common tasks such as logging, authentication, or error handling across multiple endpoints, ensuring that these operations are executed consistently before or after the main application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b480ba1-6cdf-4114-9abf-c93e5b6c7820', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using ''Ecto.Repo'' as a wrapper around the database connection pool?', N'Senior', N'Ecto.Repo provides a unified interface for database interactions, managing connection pooling and transaction lifecycle automatically. It abstracts the underlying database driver, providing safety features like automatic parameterization to prevent SQL injection and connection management that prevents resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccc5237c-826c-4e64-8daf-c93f00b49f73', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is ReactDOMServer?', N'Intern', N'The ReactDOMServer object enables you to render components to static markup (typically used on node server). This object is mainly used for _server-side rendering_ (SSR). The following methods can be used in both the server and browser environments: 1. renderToString() 2. renderToStaticMarkup() For example, you generally run a Node-based web server like Express, Hapi, or Koa, and you call renderToString to render your root component to a string, which you then send as response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'202727bf-0810-4f9b-bd76-c93fc0acba81', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the benefit of using Cassandra over a traditional RDBMS for logging?', N'Junior', N'Cassandra is optimized for high-volume write operations, making it ideal for logging data where you have constant streams of incoming records. RDBMS systems often struggle with the locking overhead and performance degradation associated with such massive, frequent write workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb4d7cc9-551b-43da-a8e4-c942267d7f7b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain the trade-offs between WiredTiger''s cache usage and the operating system''s filesystem cache in MongoDB.', N'Senior', N'WiredTiger manages its own internal cache to store uncompressed data pages, while the OS caches compressed blocks from the disk. Relying on both can lead to double caching, consuming significant RAM, so administrators must balance the WiredTiger cache size to leave sufficient memory for the OS filesystem cache to avoid excessive disk I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'451769db-8a28-4a34-a5f7-c943ce8551a2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a Repository and an Entity in Doctrine?', N'Junior', N'An Entity represents the data structure and content of a single record, while a Repository provides the methods used to fetch those entities from the database. You use the Repository to perform queries and the Entity to manipulate the specific data returned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7522e59-72cd-40df-9911-c945fa4747e4', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle error responses?', N'Intern', N'Echo includes a centralized HTTP error handler that manages how errors are returned to the client. You can trigger this by returning an error from a handler, which Echo will then convert into a standard HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18eb1f74-73a0-4031-bce1-c94ae74ebb7e', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you emit an event from a child component to a parent?', N'Junior', N'A child component can communicate with its parent by calling an internal emit function with the name of the custom event. The parent component listens for this event using the v-on directive or the @ syntax to trigger a method or update its own state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb31d3ab-73ad-4b77-84a7-c94ce897f370', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the difference between an ''optimal'' solution and a ''satisficing'' solution in engineering?', N'Intern', N'An optimal solution is the best possible choice based on all defined variables, while a satisficing solution meets the minimum requirements and constraints. In practice, engineers often choose a satisficing solution to save time and resources when the marginal gains of optimization are low.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'810dc06e-69ce-40cf-aa40-c94e401e8b5a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain how Astro handles global state management.', N'Middle', N'Astro does not have a built-in global state manager because it is designed to be multi-page and component-isolated. For shared state, developers typically use browser-native solutions like Web Storage, Nano Stores, or state management libraries that work across framework boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a64e13e3-9a7a-478b-9d79-c95118b227f9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Function binding?', N'Intern', N'Function binding ( .bind() ) is a method on the prototype of all functions in JavaScript. It allows to create a new function from an existing function, change the new function''s this context, and provide any arguments you want the new function to be called with. The arguments provided to bind will precede any arguments that are passed to the new function when it is called. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb0947b4-35a3-4540-a89d-c95176a44b2e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of displayName class property?', N'Intern', N'The displayName string is used in debugging messages. Usually, you don’t need to set it explicitly because it’s inferred from the name of the function or class that defines the component. You might want to set it explicitly if you want to display a different name for debugging purposes or when you create a higher-order component. For example, To ease debugging, choose a display name that communicates that it’s the result of a withSubscription HOC.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e7a0abb-5e6c-4c6b-a861-c955e77b4fe7', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is it generally discouraged to put complex business logic inside Alpine.js directives?', N'Middle', N'Placing complex logic directly in HTML attributes makes the codebase hard to test, debug, and maintain. Alpine.js works best when logic is abstracted into external scripts or components, keeping the HTML clean and focused on declarative bindings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7f07e25-ead9-4d63-a702-c956ce54d653', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What mechanism does Gin use to handle form data and file uploads?', N'Middle', N'Gin wraps the standard library''s multipart form handling, providing convenient methods to access uploaded files and form fields. It abstracts the complexity of parsing multipart/form-data requests, allowing developers to save files or access values directly through the Context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cc41150-90b0-4839-a1de-c95892b173a0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a transaction rollback?', N'Intern', N'A rollback is the process of canceling a transaction before it is committed. It undoes all changes made during the transaction, effectively restoring the database to the state it was in before the transaction started.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
