INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea75b5c7-4c08-43e8-8803-c967b060b25c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a Memory Leak?', N'Intern', N'The standard definition of a memory leak is a scenario that occurs when objects are no longer being used by the application, but the Garbage Collector is unable to remove them from working memory – because they''re still being referenced. As a result, the application consumes more and more resources – which eventually leads to a fatal OutOfMemoryError. Some tools that do memory management to identifies useless objects or memeory leaks like: * HP OpenView * HP JMETER * JProbe * IBM Tivoli Example: Output Types of Memory Leaks in Java: * Memory Leak through static Fields * Unclosed Resources/connections * Adding Objects With no hashCode() and equals() Into a HashSet * Inner Classes that Reference Outer Classes * Through finalize() Methods * Calling String.intern() on Long String', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a864e53-c374-450b-b682-c96a4ac68811', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is it important to keep the database server clock synchronized in a replicated environment?', N'Middle', N'Time synchronization is crucial for accurate logging, consistent transaction sequencing, and proper monitoring. In distributed environments, clock skew can cause issues with conflict resolution, audit trails, and the timing of automated maintenance tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
