INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'245fdb97-9113-482a-907c-c96e89a80baf', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go''s ''M:N'' scheduling model differ from OS-level threading?', N'Senior', N'The M:N model maps many goroutines onto fewer OS threads, allowing the runtime to multiplex concurrency without the heavy overhead of context switching between OS threads. This allows Go to scale to massive numbers of concurrent operations while keeping the kernel-level thread count relatively low and stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
