INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77e798eb-0024-4e28-9fd9-c97fc412d0b3', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do signals work in SolidJS?', N'Junior', N'Signals are the basic reactive primitives that contain a value and a subscription mechanism. When a signal''s value is updated, Solid automatically tracks all parts of the UI that depend on that signal and updates only those specific parts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feff7371-5454-4ccb-ae28-c98086d4d9ba', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to use await outside of async function prior to ES2022?', N'Fresher', N'Prior to ES2022, if you attempted to use an await outside of an async function resulted in a SyntaxError. But you can fix this issue with an alternative IIFE (Immediately Invoked Function Expression) to get access to the feature. In ES2022, you can write top-level await without writing any hacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57210f26-f5d7-4a0a-9e1b-c9831a7b24ec', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is ''Nitro'' in the context of Nuxt?', N'Junior', N'Nitro is the server engine that powers Nuxt. It is designed to be high-performance, lightweight, and cloud-provider agnostic, allowing Nuxt to be deployed to various environments like serverless functions or traditional Node.js servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5426d5fe-b15e-4a02-94e4-c98610589b61', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does server-side rendering (SSR) work in Svelte?', N'Middle', N'Svelte supports SSR by serializing components into plain HTML strings on the server, which are then ''hydrated'' by Svelte on the client. This improves SEO and perceived load time, as users see the rendered content before the full JavaScript bundle has been processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eebc4b2-7a8f-41dc-a6be-c98da7d60366', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'When is it appropriate to use a ''Service Mesh''?', N'Senior', N'A service mesh is appropriate when managing complex microservice interactions that require advanced traffic management, mutual TLS, and detailed observability. It abstracts these infrastructure concerns out of the application code, though it adds significant operational complexity and overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'182a0434-85e8-4953-9ce3-c98ec0852e14', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is testing Alpine.js components different from testing React components?', N'Middle', N'Testing Alpine components typically involves end-to-end testing tools like Playwright or Cypress because the logic is deeply integrated with the DOM. Unlike React, where you can easily unit test the component logic in isolation, Alpine components are often tested as part of the live rendered page to ensure directives are correctly bound.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'782ccb15-caa3-4f6f-9a3a-c9912a6a9472', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''pluck'' method in ActiveRecord and when should you use it?', N'Middle', N'The pluck method retrieves specific columns from the database as an array of values instead of instantiating full ActiveRecord objects. It is significantly more memory-efficient when you only need a subset of data and do not intend to perform any operations that require the full object lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
