INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f47b3415-1882-476f-9c54-c998005f5666', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web''s internal architecture leverage the Actor model for concurrency?', N'Senior', N'Actix-web is built on the Actix framework, which uses a system of isolated actors that communicate via asynchronous message passing. Each actor runs in its own context and manages its own state, allowing for highly concurrent systems that avoid shared-mutable state and data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd74c553f-d8ce-4c35-b502-c99b9f91b082', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of using Chi''s middleware stack compared to manual request processing?', N'Middle', N'Chi''s middleware stack provides a composable way to inject cross-cutting concerns like logging, recovery, and authentication into the request lifecycle. By using a standardized chain, you ensure consistent behavior across all routes and reduce code duplication, while maintaining compatibility with the standard http.Handler interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f000c80-335e-4783-a51a-c99c680da2b9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What happens if a transaction is ''committed''?', N'Junior', N'When a transaction is committed, all changes made during the transaction are permanently saved to the database. Once the commit command is issued, the changes become visible to other users and cannot be easily undone without a new, separate transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9e849a-fb1d-4ec4-8a5b-c99d9303b5c2', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it generally discouraged to perform massive bulk updates on existing documents?', N'Middle', N'Because Lucene segments are immutable, every update is technically an insert of a new document and a logical delete of the old one. Frequent updates cause rapid segment creation and increase the frequency of background merges, which can degrade performance significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
