INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fd37f1a-3b18-4a3c-b03d-c9a4223c4ff1', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a JOIN and a UNION in SQL?', N'Junior', N'A JOIN is used to combine columns from two or more tables based on a related column between them, effectively widening the result set. A UNION is used to combine the result sets of two or more SELECT statements into a single result set, stacking rows vertically provided the column structures are identical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
