INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d5a95fa-e24e-4d0e-9fe6-c9a6f33d95f5', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Discuss the trade-offs between keeping state in the Redux store versus keeping it local to a component.', N'Senior', N'Local state is optimal for ephemeral UI concerns like toggling a modal or tracking form inputs, as it reduces store overhead and complexity. Redux state is reserved for data that needs to be shared across multiple components or persisted across navigation, preventing prop-drilling and ensuring synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
