INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7e7a610-8d3d-42a4-9db4-c9b4f1d2f1cd', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut''s configuration property binding work and how is it different from manual property parsing?', N'Senior', N'Micronaut uses annotation processing to generate binding logic that maps environment variables or YAML properties directly to immutable configuration classes at compile time. This ensures type safety and allows the framework to validate configuration properties before the application even starts, catching errors early in the lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ca31304-d2b1-42f2-86d2-c9b62fa0b1fa', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between AddTransient, AddScoped, and AddSingleton?', N'Junior', N'AddTransient creates a new instance every time the service is requested. AddScoped creates an instance once per client request, and AddSingleton creates a single instance the first time it is requested and reuses it for all subsequent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee45e05-8104-421c-9dca-c9b6cbbfe41c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the difference between Class-based and Interface-based design patterns in TypeScript.', N'Senior', N'Class-based design uses classes to define both types and runtime implementations, which is useful for dependency injection and prototype-based behavior. Interface-based design focuses on defining contracts, allowing for lighter, more flexible architectural patterns that decouple behavior from data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
