INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b61911e-b914-406e-af0b-c9bebb6c8bf1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are push notifications in PWA?', N'Intern', N'Push Notifications allow a server to send messages to a user''s device even when the PWA is not open in the browser, using the Push API and Notifications API together. Flow: 1. App requests notification permission from the user. 2. App subscribes to the browser''s push service (generates a unique subscription endpoint). 3. Subscription is sent to the app''s server. 4. Server sends a push message to the endpoint via the Web Push Protocol. 5. Service worker receives the push event and shows a notification. Step 1 — Request permission: Step 2 — Subscribe: Step 3 — Handle push in service worker (sw.js): The service worker acts as a background daemon — it can receive push events and display notifications even when the app tab is closed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea828f45-2c01-4ef3-96e0-c9bfd803e34b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the switch statement?', N'Intern', N'The switch statement is used to execute one block of code among many based on the value of an expression. It is an alternative to using multiple if...else if statements. The switch statement evaluates an expression, matches the expression''s value to a case label, and executes the associated block of code. If no case matches, the default block is executed. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'613f8982-06e5-491e-bdbc-c9c09b534a61', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between a route and a group in Hono?', N'Intern', N'A route defines a single path and its handler. A route group allows developers to organize multiple routes together, often applying shared middleware or a common path prefix to all routes within that group.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1c0b72c-fa2a-481c-a745-c9c13b0ed4e9', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Does Quarkus support testing out of the box?', N'Junior', N'Yes, Quarkus provides a powerful testing framework that allows you to start the application in a test context. It supports standard JUnit 5 tests and provides special annotations to inject resources or mock external services during the testing lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ba1432a-1bbd-435d-beb6-c9c268fefae5', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''nuxt.config.ts'' file?', N'Fresher', N'The nuxt.config.ts file is the central configuration hub for your Nuxt application. It is where you define settings like environment variables, module integrations, global styles, and build-time configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57749e99-c7aa-41b5-8278-c9c286429d14', N'075b8862-431c-4678-9767-f55359758a4a', N'How do custom directives differ from components in terms of their lifecycle and usage?', N'Senior', N'Custom directives provide a mechanism for low-level direct DOM element manipulation, such as focus management or third-party library integration. Unlike components, they do not have a template or a component instance, but they expose hooks like mounted and updated to interact with the target element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dea705f-707f-441b-b4a9-c9c2eb8b3aaa', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''weak'' and ''unowned'' references?', N'Intern', N'A weak reference does not keep a strong hold on the instance it refers to, and it becomes nil when the instance is deallocated. An unowned reference assumes the referenced instance will always have the same lifetime or a longer lifetime than the reference itself, so it is never nil.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
