INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2c77bee-eef3-4b4c-9d9c-c9c4327f453b', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the trade-off between consistency and availability in the CAP theorem during a network partition?', N'Middle', N'During a network partition, you must choose between consistency and availability. If you choose consistency, the system will return an error or timeout if it cannot guarantee the data is up-to-date across all nodes, whereas choosing availability means the system will return the most recent available data, even if it might be stale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06c6e28f-872e-4d5e-bcd2-c9c468d5a08a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a class in C++?', N'Intern', N'A class is a user-defined data type that acts as a blueprint for creating objects. It encapsulates data members and member functions into a single unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fadce530-dfcf-43c5-8475-c9c7a80d6465', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle polyfills?', N'Middle', N'Vite does not automatically inject polyfills for older browsers. It encourages targeting modern browser baselines, but developers can use plugins or manual imports to include necessary polyfills if support for legacy browsers is a project requirement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25d3b8ae-1e3a-49ee-adb7-c9c7e7bd7a2f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is the use of ''chi.URLParam'' considered better than parsing strings manually?', N'Senior', N'Using chi.URLParam provides a standardized, safe way to extract path variables that have already been matched and parsed by the router. This avoids brittle string splitting or regex parsing in the handler, reducing the surface area for bugs related to malformed input URLs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43e401ab-439f-495c-9b72-c9c8f4131bc7', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the primary trade-offs when choosing between a microservices architecture and a monolithic architecture for a growing application?', N'Middle', N'A monolith offers simpler deployment, testing, and debugging due to a unified codebase, but it can become difficult to scale and maintain as the team grows. Microservices provide independent scalability and technology flexibility, but introduce significant complexity in inter-service communication, data consistency, and operational monitoring. The choice depends on balancing the need for rapid feature development versus the requirement for granular system scalability and fault isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed6d74ad-9f76-441e-a48c-c9cc2ced4e70', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch differ from a traditional relational database like MySQL?', N'Junior', N'Elasticsearch is a document-oriented NoSQL database optimized for search, whereas MySQL is a relational database optimized for ACID-compliant transactions and structured data. Elasticsearch stores data as JSON documents rather than rows in tables, making it better suited for unstructured text and high-speed retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
