INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6c2092-93a4-4c6c-92fc-c9cfec6b0f8d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle ''null'' and ''undefined'' under strict mode?', N'Middle', N'With strict null checks enabled, ''null'' and ''undefined'' are no longer considered assignable to other types by default. This forces developers to explicitly handle the possibility of missing values, significantly reducing runtime errors caused by accessing properties of null or undefined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
