INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e33ebdd-b7a9-48d1-b662-c9dfced87da6', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the difference between shallow and deep copying in the context of mutable nested structures.', N'Senior', N'Shallow copying creates a new container but populates it with references to the original nested objects, which can lead to unintended side effects if those objects are modified. Deep copying recursively traverses the structure to create independent clones of all nested mutable objects, ensuring complete isolation at the cost of significantly higher memory and time usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
