INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'956975b7-35f6-4a8a-894a-c9efb7246392', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What Are The Implementation In Python Program?', N'Intern', N'Python program can be implemented by two ways > 1. Interactive Mode (Submit statement by statement explicitly) 2. Batch Mode (Writing all statements and submit all statements) In Interactive mode python command shell is required. It is available in installation of python cell. In Interactive mode is not suitable for developing the projects & Applications Interactive mode is used for predefined function and programs. Example: X, Y is not find. Interactive mode is unfit for looping purpose. Interactive Mode: The concept of submitting one by one python statements explicitly in the python interpreter is known as "Interactive Mode" In Order to submit the one by one python statements explicitly to the python interpreter we use python command line shell.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
