INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1682d680-1484-4f6b-94c2-c9f098460dd6', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a ''CORS'' policy and why might you need it in FastAPI?', N'Intern', N'CORS stands for Cross-Origin Resource Sharing, a security feature that allows a browser to restrict web pages from making requests to a different domain than the one that served the page. You configure CORS in FastAPI to explicitly permit or deny requests from specific front-end origins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ec57a39-57ec-4480-be5d-c9f270865ce8', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis single-threaded?', N'Intern', N'Redis primarily uses a single-threaded architecture for its main command execution loop. While it uses background threads for tasks like persistence, the single-threaded core avoids the complexity and overhead of managing locks in a multi-threaded environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'045c179c-fd10-485c-99ec-c9f32acc4280', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the concept of ''Covering Index'' and its performance benefits.', N'Middle', N'A covering index is an index that contains all the columns required by a query, allowing the database to retrieve data directly from the index tree without looking up the actual table rows. This eliminates the need for an expensive ''Bookmark Lookup'' or ''Clustered Index Scan,'' significantly speeding up execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a1c8b71-4491-44e1-a56a-c9f39a650ef6', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle security?', N'Junior', N'Quarkus provides a robust security extension that supports standard protocols like OIDC, JWT, and basic authentication. It allows developers to secure endpoints using declarative annotations based on roles or identity providers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
