INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c2b3048-15d7-4221-9982-c9f5e26a1048', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is Sass inheritance with @extend?', N'Intern', N'The @extend directive allows one selector to inherit the styles of another selector. It is useful for sharing a common set of styles among multiple elements while keeping the HTML clean of extra class names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f7ebc91-c003-46df-8a66-c9f6dee23d9c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro ensure type safety for CSS classes?', N'Middle', N'Astro supports CSS modules and various pre-processors, but for strict type safety, developers often use libraries like Tailwind CSS. Because Astro components are modular, CSS can be scoped to individual components to prevent styles from leaking into other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ba32e76-e551-4aa2-96ee-c9fcb8344eb3', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a dirty read in a database?', N'Intern', N'A dirty read occurs when a transaction reads data that has been modified by another transaction but not yet committed. If the other transaction rolls back, the first transaction is left with invalid or ''dirty'' data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28ec31b3-17aa-4971-81dc-c9fe08071bf1', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you manage secrets and sensitive configuration in a distributed environment?', N'Senior', N'I would use a centralized secret management service that provides dynamic, short-lived credentials and audit logging. Secrets should never be stored in plain text or version control, but rather injected into the application environment at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b63dc3f-32b7-44b9-b159-c9fe197db577', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How to detect if a function is called as constructor', N'Fresher', N'You can use new.target pseudo-property to detect whether a function was called as a constructor(using the new operator) or as a regular function call. 1. If a constructor or function invoked using the new operator, new.target returns a reference to the constructor or function. 2. For function calls, new.target is undefined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0e14501-5f16-4038-ba5a-c9fe56cd1e7e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why are surrogate keys often used instead of natural keys?', N'Junior', N'A surrogate key is an artificial, system-generated identifier, whereas a natural key is a piece of real-world data like a social security number or email. Surrogate keys are preferred because they are immutable and guaranteed to never change, ensuring stability in the database design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2214bd38-db60-4949-9d15-c9ffbdbc351f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary architectural difference between Astro and a traditional single-page application framework?', N'Fresher', N'Astro is a content-focused framework that prioritizes server-side rendering by default to send zero JavaScript to the browser. In contrast, traditional single-page application frameworks typically ship the entire JavaScript bundle to the client, which can result in larger initial load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1e63570-b43d-4ff5-9bc7-ca00445ae5c5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s approach to typography differ from a standard ''reset'' stylesheet?', N'Middle', N'Tailwind''s typography plugin provides a way to style long-form content using a single class, which applies a consistent set of styles to nested elements. This is more efficient than writing custom CSS for every heading, paragraph, and list item within dynamic content sections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cd787ef-b964-4ddf-9fb9-ca006c8f4ea3', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the advantages and disadvantages of using a ''hashed'' shard key?', N'Middle', N'A hashed shard key ensures even distribution of data across shards by hashing the field value, which prevents ''hot spots'' caused by monotonically increasing values. The disadvantage is that it does not support efficient range-based queries, as related data points are scattered randomly across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e9e3573-4baa-4340-9b60-ca0192b55d07', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is an ASGI server and why is it needed for FastAPI?', N'Fresher', N'ASGI (Asynchronous Server Gateway Interface) is a standard interface between web servers and Python frameworks. FastAPI requires an ASGI server, such as Uvicorn or Hypercorn, to translate HTTP requests into a format the application can process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f098aaba-3fcc-4a23-9d49-ca0386c4a26b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do Coroutines provide a lighter-weight alternative to threads?', N'Middle', N'Coroutines use cooperative multitasking by suspending execution rather than blocking the underlying thread. This allows thousands of coroutines to run on a very small pool of threads, significantly reducing memory consumption and context switching overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a14ea97-3d52-4b5c-aa95-ca03dfa0748a', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are Quarkus extensions, and why are they important?', N'Junior', N'Extensions are the building blocks of Quarkus that integrate various libraries and frameworks, such as Hibernate or RESTEasy, into the application. They provide the necessary configuration and build-time logic to make these libraries compatible with Quarkus''s efficient execution model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4e0ed41-e2bf-40d5-a0a7-ca0510cf83a7', N'954a0331-deff-4399-b588-96f39fec001d', N'What is property binding? How is it different from event binding?', N'Intern', N'Property binding in Angular allows you to set the value of a target element''s property using a component''s property value. The data flow is one-way, from the component class to the DOM element or directive property. You use square brackets [] around the target property name, like [src]="imageUrl". Event binding, on the other hand, lets you listen for events dispatched by a target element (like a button click or input change) and execute a method in your component class when that event occurs. The data flow is from the DOM element to the component. You use parentheses () around the target event name, like (click)="saveData()". The main difference is the direction of data flow: property binding sends data _to_ the element, while event binding receives notifications _from_ the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f43329de-e4d5-43c4-8716-ca07410c4a33', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a constraint in MySQL?', N'Intern', N'A constraint is a rule applied to a table column to limit the type of data that can be inserted. Common constraints include NOT NULL, UNIQUE, PRIMARY KEY, and CHECK.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0590dd89-cdd0-491d-af05-ca07aa0d9acf', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary architectural benefit of using Phoenix Channels compared to traditional HTTP polling?', N'Middle', N'Phoenix Channels utilize persistent WebSocket connections, allowing for full-duplex, low-latency communication. This removes the overhead of repeated HTTP headers and eliminates the latency associated with polling intervals for real-time applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd29f3b0e-fad3-4dda-9d2b-ca08a4b7b537', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the difference between a node and a cluster in NoSQL?', N'Junior', N'A node is a single instance of the database running on a server, while a cluster is a collection of multiple nodes working together to store data and process requests. The cluster acts as a single logical database to the application, providing scalability and redundancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88a252a9-ebf2-46d8-8451-ca0abb008ec4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle external dependencies, such as waiting for an API from another team, when estimating your work?', N'Junior', N'I account for the lead time of the dependency and add a buffer for potential integration delays. I also proactively communicate with the external team to clarify their delivery schedule and identify any risks that might affect my own timeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea2a979d-588d-45cc-9bd8-ca0bd964ffe7', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the difference between ''preHandler'' and ''preValidation'' hooks.', N'Middle', N'The preValidation hook runs before the schema validation process, allowing you to modify the request payload if necessary. The preHandler hook runs after validation is complete, making it ideal for authentication or business logic that requires a guaranteed valid payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c84c3bdf-e8f1-4120-8f38-ca0bfb047c97', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is a supervision tree?', N'Intern', N'A supervision tree is a hierarchical structure of processes where supervisor processes monitor worker processes. If a worker fails, the supervisor can automatically restart it to ensure system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bf292b0-3e8f-4de3-b3ab-ca0d6dc9327a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Is Gin thread-safe?', N'Intern', N'Gin itself is designed to handle multiple concurrent requests by spawning a new goroutine for each incoming connection. As long as you do not share state improperly between goroutines, it is safe to use in a concurrent environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59308e06-910f-4b46-87a2-ca0e47bdb45a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage state during navigation between complex, data-heavy routes?', N'Senior', N'Remix uses its internal router to manage the transition state, keeping the current page active until the new route''s loader data is fully fetched. This provides a clean ''all-or-nothing'' navigation experience, preventing partial UI updates that can lead to layout shifts or inconsistent data states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30aa1cb8-d23b-4bc3-b6fc-ca0eda7183c7', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure your work meets the quality standards of your team?', N'Fresher', N'I ensure quality by following the team''s coding conventions, writing clear documentation, and performing thorough self-testing. I also value feedback during code reviews and ensure that I address any concerns raised by my teammates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7584a9b8-f4a9-4c0b-b3e7-ca0fa1397b8f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''map'' and ''flatMap'' collections?', N'Junior', N'The map function transforms each element in a collection into a new value, resulting in a collection of the same size. FlatMap transforms each element into a collection and then flattens all those resulting collections into a single, unified list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05b8c2a7-33b6-41ea-b970-ca118ffdd3f7', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Quarkus Dev Mode and how does it assist developers?', N'Junior', N'Dev Mode allows developers to make changes to their code and see the results immediately without manually restarting the application. It automatically recompiles and reloads the application when a file is saved, significantly speeding up the development feedback loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2328c0cd-a06a-4d4f-9b61-ca11f866bb24', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does scalability impact the trade-off between system complexity and performance?', N'Intern', N'High scalability often requires distributed systems, which significantly increase architectural complexity and operational overhead. An engineer must weigh whether the expected performance gains justify the increased difficulty in monitoring, debugging, and maintaining that complex infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3e1f043-6d43-4119-9a4b-ca1273db5684', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Describe the impact of cache locality on system performance in high-throughput distributed architectures.', N'Senior', N'Cache locality reduces network I/O overhead by keeping data closer to the compute resources. Improved locality minimizes latency and lowers the load on backend databases, though it necessitates complex cache invalidation strategies to maintain data freshness across distributed nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8984dd9-1aff-4a25-9412-ca14606c1b6b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What mechanisms exist in NestJS to prevent circular dependencies, and why are they considered a code smell?', N'Senior', N'NestJS provides forward references to resolve circular dependencies, but their presence often indicates a violation of the Single Responsibility Principle or poor module design. Circular dependencies make the dependency graph brittle, complicate testing, and often point to a need for refactoring shared logic into a separate, independent module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dbbdbd0-bb19-4331-a864-ca16c2d637e9', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Describe the trade-offs of using Qwik''s global event delegation model.', N'Senior', N'Global delegation allows for extreme lazy loading by decoupling events from component instances. The trade-off is a slight overhead in event bubbling and the requirement that all interactive elements must be registered within the framework''s serialization manifest to be correctly linked to their handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df85c86a-21dc-4f77-85e9-ca18eb503dac', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix facilitate file uploads?', N'Middle', N'Remix provides built-in utilities to parse multipart form data directly within the action function using standard request handling. This allows developers to stream file uploads directly to storage services without needing to write complex custom server middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'891d891d-e7d9-4012-893e-ca1c23317e38', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of SmallRye in the Quarkus ecosystem?', N'Middle', N'SmallRye is the community project that provides implementations for many MicroProfile specifications used within Quarkus. It serves as the foundation for features like fault tolerance, health checks, and metrics, ensuring compliance with industry standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da08f9a7-1609-4798-ad2f-ca1e3f84220a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is a ''Group'' in Echo routing?', N'Intern', N'A Group is a subset of routes that can share common properties, such as a prefix or middleware. It is useful for versioning APIs, such as grouping all routes under a ''/v1'' prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'333b3b27-7bc4-4423-8586-ca20793c82b1', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar ensure thread safety in asynchronous handlers?', N'Middle', N'Litestar is designed for the ASGI specification, which promotes an event-driven architecture rather than relying on multi-threading. By staying within the asynchronous ecosystem, Litestar avoids race conditions typical of multi-threaded synchronous frameworks, provided shared state is managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f944bd26-edc7-4d10-aa54-ca227c1caff6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go''s ''init'' function behavior impact application startup?', N'Middle', N'Init functions run automatically before the main function, providing a place to perform package-level setup. However, they can make dependencies difficult to track and should be used sparingly to avoid complex side effects during the initialization phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fba6a1c0-21d4-4542-86af-ca2444741069', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the advantage of using reflection-free frameworks like Micronaut?', N'Fresher', N'Reflection-free frameworks avoid the performance overhead and memory consumption associated with inspecting classes at runtime. This results in faster application initialization and a significantly smaller memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'237fa0fb-76e2-4786-b696-ca2598f657ac', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is middleware in the context of the Echo framework?', N'Fresher', N'Middleware in Echo are functions that sit between the incoming HTTP request and the final route handler. They are used to perform tasks such as logging, authentication, recovering from panics, or modifying request and response headers globally before the main logic executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0f8d76c-0b32-4905-843b-ca2df0b0b2fe', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the concept of ''Hot Partitions'' in DynamoDB and how to prevent them.', N'Middle', N'Hot partitions occur when a specific partition key receives a disproportionately high volume of traffic compared to others, leading to throttling. This is prevented by choosing a high-cardinality partition key that distributes write and read requests evenly across the entire keyspace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0ee1df6-2e41-4cc1-a951-ca31e8862185', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Can you explain how useState works?', N'Junior', N'useState in Modern React (2026) useState is a fundamental React Hook that enables functional components to maintain state across re-renders. It returns a pair: the current state value and a dispatch function to update it. By leveraging Fiber architecture, React tracks the order of hook calls via a linked list stored on the memoizedState property of the fiber node. Core Components of useState 1. Stateful Value: The first element in the returned array represents the current state. React preserves this value between renders. 2. Dispatch Function: The second element is the state-setter. In React 19+, this function is stable across renders, allowing it to be passed as a prop without triggering unnecessary downstream re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7164d8c7-90c2-411b-b5b4-ca32d62859f0', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between .empty() and .remove()?', N'Fresher', N'.empty() removes all child nodes from the selected element, but the element itself remains in the DOM. .remove() deletes the selected element and all of its children from the DOM entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf8983fd-25d5-4b59-b258-ca366b27a360', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the role of the Redis Sentinel system?', N'Middle', N'Redis Sentinel provides high availability by monitoring master and replica instances. It automatically performs failover by promoting a replica to master if the current master becomes unreachable, and it notifies applications of the new master address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c167112b-3b91-43de-8ba5-ca3a7a925725', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the role of the Zend VM''s executor in managing the call stack during recursion?', N'Senior', N'The executor manages the call stack via stack frames that store local variables and function execution pointers. Because PHP scripts are limited by the memory allocated to the process, deep recursion can trigger a stack overflow or exhaust the memory limit defined in the runtime configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fb1e51f-3711-4931-b3f7-ca3db146cbb6', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'A system''s cache is causing high memory pressure. What strategies would you use to mitigate this?', N'Middle', N'I would first implement or tune an appropriate eviction policy like Least Recently Used to ensure high-value data remains cached. Then, I would evaluate if the cache keys are too large or if the time-to-live settings are too long, potentially moving to a distributed caching layer like Redis if the memory pressure exceeds the application node''s capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce2500a5-ffe7-45e9-a926-ca42f808bee7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB''s WiredTiger storage engine implement document-level concurrency control, and what are the trade-offs regarding memory usage?', N'Senior', N'WiredTiger uses optimistic concurrency control with multi-version concurrency control (MVCC) to allow multiple writers to modify different documents within the same collection simultaneously. By utilizing document-level locking, it reduces contention significantly compared to collection-level locking; however, this architecture increases memory overhead due to the need for maintaining multiple versions of documents in the cache and the associated metadata for transaction management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8bdad2a-7e5a-4fe9-b7ba-ca48140fbfd7', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between @RequestBody and @ModelAttribute?', N'Junior', N'@RequestBody is used to bind the entire incoming HTTP request body to a Java object, typically for JSON payloads. @ModelAttribute is used to bind request parameters or form data to an object, often used when handling traditional HTML form submissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b76cd08-b6b7-41d1-b7b1-ca482c9f63f9', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @SpringBootApplication annotation?', N'Intern', N'This annotation is a convenience annotation that adds @Configuration, @EnableAutoConfiguration, and @ComponentScan. It tells Spring Boot to automatically configure the application and look for other components in the current package and its sub-packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdacd973-f8ee-4171-91e0-ca4a79762d02', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Twig in relation to Symfony?', N'Intern', N'Twig is the default template engine for Symfony used to generate HTML responses. It provides a secure and concise syntax for displaying data, helping to separate the presentation layer from the business logic within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19ae33f3-bdfc-4f0d-9294-ca4fb6a3c5bb', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of the constants in Redux?', N'Intern', N'Constants allows you to easily find all usages of that specific functionality across the project when you use an IDE. It also prevents you from introducing silly bugs caused by typos – in which case, you will get a ReferenceError immediately. Normally we will save them in a single file (constants.js or actionTypes.js). In Redux, you use them in two places:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fe668fc-8188-4093-b620-ca5008a7c6f8', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s schema-driven approach facilitate API documentation?', N'Senior', N'Because the schemas are a mandatory part of the route definition, they act as a ''single source of truth''. This allows tools like Swagger or OpenAPI to auto-generate accurate documentation without requiring manual maintenance of separate specification files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6eb8238-8169-4fbf-ad26-ca50f091499b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the benefit of using an Enum in TypeScript?', N'Junior', N'Enums allow you to define a set of named constants, making your code more readable and easier to maintain. They provide a way to document intent by grouping related values under a single, descriptive name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85f7a56b-1f53-459e-aa61-ca517900ec8e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte considered ''lightweight''?', N'Fresher', N'Svelte is considered lightweight because it lacks a heavy runtime library that must be shipped to the browser. Since the framework does the heavy lifting during the build process, the final application contains only the necessary code to update the DOM, resulting in a smaller footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7adebb7-55f6-47bc-89cf-ca5187f01a62', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the lifecycle methods going to be deprecated in React v16?', N'Fresher', N'The following lifecycle methods going to be unsafe coding practices and will be more problematic with async rendering. 1. componentWillMount() 2. componentWillReceiveProps() 3. componentWillUpdate() Starting with React v16.3 these methods are aliased with UNSAFE_ prefix, and the unprefixed version will be removed in React v17.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'773c24d8-1c16-4788-8641-ca51ce6c4e24', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are halfway through a task and realize your original time estimate was too optimistic, what is your next step?', N'Junior', N'I immediately communicate the delay to my manager or team lead, explaining the specific blocker or complexity that caused the discrepancy. I provide a revised estimate based on the remaining work and offer options, such as scaling back the scope or adjusting priorities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75c109e8-9a67-4773-b7a4-ca535b5acc6d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is the partition key design critical for preventing hot spots in a Cassandra cluster?', N'Senior', N'Data is distributed across the cluster based on the hash of the partition key; an poorly chosen key leads to skewed data distribution where one node handles significantly more traffic than others. This creates a hot spot that limits horizontal scalability and can lead to node-level saturation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4e71656-ff89-423a-8c71-ca553a72ef3d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the function of the ''model()'' hook in a route?', N'Junior', N'The model hook is used to fetch data from the server or a store before a route is rendered. It ensures that the required data is available for the route''s template and controller before the user sees the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78a5a47d-067b-41cc-bcdb-ca5636856097', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is React strict mode and what are its benefits?', N'Intern', N'React strict mode is a development tool that helps identify potential problems in an application. It activates additional checks and warnings for its descendants. It doesn''t render any visible UI and doesn''t affect the production build. The benefits include identifying unsafe lifecycle methods, warning about legacy string ref API usage, detecting unexpected side effects, and ensuring that components are resilient to future changes. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f36bba1-7a27-4ada-8b56-ca56dc18feac', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a transaction deadlock?', N'Junior', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on resources. This causes the database to halt operations until one of the transactions is aborted or rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'904ff3c0-cb1e-457d-ba82-ca5952e37632', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary benefit of using TypeScript over plain JavaScript?', N'Intern', N'The primary benefit is the ability to catch errors early during development through static type checking. This helps developers identify bugs related to incorrect data types before the code is even executed in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23494be6-81d3-4918-a13a-ca5a3c35da3f', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the role of a ''shard key'' and why is its selection critical?', N'Middle', N'The shard key determines how data is distributed across the cluster. A poor choice can lead to uneven data distribution, known as data skew, where some shards become significantly larger or more active than others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6e87898-8a77-41aa-89b3-ca5d68634138', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle large-scale state updates?', N'Middle', N'Redux relies on shallow comparison to determine if state has changed. By using immutable update patterns, it quickly detects changes, which is highly efficient for managing large datasets without deep object cloning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a6d03fb-b2fe-4c30-bba2-ca5e7853a069', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''Transition'' in SolidJS and why is it useful?', N'Senior', N'Transitions allow marking state updates as non-urgent, enabling the UI to remain responsive during heavy updates. It allows the framework to prioritize user interactions while background tasks complete, preventing input lag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d382e35-a924-42d6-9998-ca600fa671c9', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How do Bloom filters interact with index lookups in PostgreSQL?', N'Senior', N'Bloom filters provide a space-efficient way to test if a key exists in a set, which is useful for pruning partitions or skipping unnecessary index pages. By checking the filter before accessing disk-based indexes, PostgreSQL can significantly reduce I/O for large-scale data lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c9ea8e8-2d9b-4211-802f-ca608039358b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary programming language used by Phoenix?', N'Intern', N'Phoenix is built using the Elixir programming language. Elixir runs on the Erlang VM, which is known for its ability to handle massive concurrency and fault-tolerant systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac661602-66b3-4f6c-bbef-ca616d09d4cb', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are Source Maps, and why should they be handled carefully in production?', N'Middle', N'Source maps provide a bridge between the minified code in the browser and the original source code, making debugging significantly easier. They should be handled carefully in production because they expose your entire source code to the public, potentially creating security and intellectual property risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6f7c9c0-c235-4a12-971b-ca618687ce66', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is the order of columns in a Primary Key important?', N'Junior', N'The primary key consists of a partition key and optional clustering columns. The partition key determines which node stores the data, while clustering columns determine the physical sort order of the data on that node, which directly impacts query efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e14f8c0d-a666-4335-bd2f-ca626cb24d5a', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the garbage collector handle objects that implement a finalizer?', N'Middle', N'Objects with a finalizer are promoted to a finalization queue instead of being collected immediately. The garbage collector must run the finalizer on a dedicated thread before the memory can be reclaimed in a subsequent collection cycle, which increases the lifecycle and memory pressure of those objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61a44009-6299-4ba6-8a2b-ca627d259b6e', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the ''Fragment'' component in Preact?', N'Junior', N'A Fragment allows you to group multiple children without adding an extra node to the DOM tree. It is useful for returning multiple elements from a component without needing a wrapper div.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bda3e5dd-d1c9-4043-940d-ca6ab7d0e8a6', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between Spring and Spring Boot?', N'Intern', N'Spring is a comprehensive framework that provides dependency injection, aspect-oriented programming, and various infrastructure modules. Spring Boot is an extension of the Spring Framework that focuses on making it easier to start and run Spring applications by providing pre-configured defaults.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0478184f-7691-41f4-b9b1-ca6ace49d587', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Service Container implement Dependency Injection, and why is it preferred over Service Location?', N'Senior', N'The Container uses a compile-time pass to resolve dependencies and build an optimized graph of services. Dependency Injection promotes loose coupling and testability by explicitly declaring requirements, whereas Service Location hides dependencies and makes the system harder to reason about or mock during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
