INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69970f1b-29bc-46db-94d0-ca6be73effa9', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass handle lists and maps?', N'Middle', N'Lists are ordered sequences of values, while maps are key-value pairs that function like associative arrays. Both are powerful tools for managing complex design tokens, such as breakpoints or color palettes, allowing developers to iterate over data to generate repetitive CSS automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54be573b-566a-4708-a440-ca6e34472984', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the concept of template inheritance and its benefit for large-scale applications.', N'Senior', N'Template inheritance allows developers to build a base skeleton with common elements and extend it in specific pages. This promotes code reuse, ensures consistent UI across the application, and reduces maintenance overhead, as global changes only need to be made in the base template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'075553f3-b106-439f-895e-ca70ec731921', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the performance implications of ''source-map'' types in development versus production?', N'Senior', N'Development source maps prioritize speed and accuracy for debugging, whereas production source maps must balance debugging utility against build time and bundle size. Using high-fidelity source maps in production can significantly increase build times and expose sensitive source code, so usually, hidden or external source maps are preferred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6df3c073-4b3b-4b7c-b6e0-ca72ea93e990', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How do you add or remove CSS classes using jQuery?', N'Fresher', N'You can use the .addClass() method to add a CSS class and the .removeClass() method to remove one from a selected element. There is also a .toggleClass() method that switches between adding and removing a class based on its current state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b5c8a20-093a-4131-bf1c-ca754d259fee', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you debug an issue with background workers or message queue consumers?', N'Middle', N'I would inspect the queue depth and consumer status to see if messages are backing up or if consumers are crashing. I would check for poisonous messages that cause failures and investigate the dead-letter queue to see if they are being handled appropriately. Ensuring idempotency in the consumer logic is crucial so that retries do not cause duplicate processing errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fff2b7be-6056-4515-b706-ca7ab8a371d2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary benefit of the utility-first approach in Tailwind CSS?', N'Junior', N'The utility-first approach helps developers build complex user interfaces quickly without leaving their HTML. It eliminates the need to invent class names for every element and reduces the overhead of managing large, separate CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
