INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec8b6864-32c8-42f1-814d-ca80789f4fa5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the primary difference between Qwik''s resumability and traditional hydration?', N'Junior', N'Traditional hydration requires downloading, parsing, and executing the entire component tree to attach event listeners, which causes a performance delay. Qwik skips this process entirely by loading only the specific event handler code required for the interaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2784944-2470-45fc-87aa-ca817277935a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix optimize for performance?', N'Fresher', N'Remix optimizes performance by pre-fetching data and assets for links on the page. It also reduces the amount of JavaScript sent to the client by keeping heavy logic and data fetching on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b11bd5a4-7105-4370-8a2f-ca840e147f63', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain how Kotlin''s ''suspend'' modifier transforms a function''s signature at the bytecode level.', N'Senior', N'The ''suspend'' modifier adds a hidden ''Continuation'' parameter to the function''s signature, which acts as a callback to resume execution after suspension. The compiler transforms the function body into a state machine, where each suspension point becomes a state, allowing the function to pause and resume without losing its execution context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
