INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdf72326-9d03-493e-969c-ca86a608625f', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the overhead of jQuery''s wrapper object compared to native NodeList or HTMLCollection.', N'Senior', N'Every time a jQuery selector is used, it creates a new jQuery object that wraps the native DOM elements with additional properties and methods. This creates significant memory overhead when handling large sets of elements, whereas native APIs provide direct access to the DOM nodes with minimal memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a94470cd-a110-409d-bf62-ca87c7253c1e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is a common trade-off when implementing database sharding?', N'Middle', N'Sharding increases system complexity, particularly regarding cross-shard queries and data integrity. Performing joins across different shards becomes significantly more difficult and expensive to manage compared to a single-instance database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
