INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ad065a-04b1-4aad-a3c5-ca8930462357', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the limitations of Alpine.js regarding server-side rendering?', N'Middle', N'Alpine.js is designed to be hydrated on the client, so it expects the server to deliver the initial HTML structure. While it works perfectly with SSR frameworks like Laravel or Next.js, it does not perform server-side component execution itself, meaning the initial state must be injected into the HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86327e26-7c5d-43b4-ab86-ca8ad5b0a49b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When is it appropriate to use a cache, and what is a common risk associated with it?', N'Junior', N'Caches are appropriate when you need to speed up data retrieval for frequently accessed, rarely changing information. The primary risk is data staleness, where the cache serves outdated information because it hasn''t been updated to match the primary data source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9744dbd8-e232-4b7c-9481-ca8b045cd0f0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the significance of the ''cluster state'' and why its size matters.', N'Senior', N'The cluster state contains metadata about all indices, mappings, shards, and node health, and it must be replicated to every node in the cluster. As the number of indices and shards grows, the cluster state size increases, leading to slower updates and longer times for new nodes to join or recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
