INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91f0b74f-e55b-4f8e-98aa-caab5687835d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the function of the Dart Isolate memory model, and how does it affect concurrency?', N'Senior', N'Isolates are independent workers that do not share mutable memory, preventing race conditions and the need for traditional locks or mutexes. Communication between isolates occurs exclusively through asynchronous message passing, which simplifies concurrency management but introduces serialization overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
