INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c4f27e9-df70-456b-b1eb-caaf57cfcc80', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the trade-offs of using ''change_tracking'' in Ecto?', N'Middle', N'Change tracking allows Ecto to determine exactly which fields have been modified, preventing unnecessary database updates. While this improves performance and helps avoid race conditions, it requires developers to manage the changeset structure explicitly, which can add complexity to data validation logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51d599b3-d556-4deb-a551-cab065c65cb4', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is QuerySet in Django?', N'Intern', N'A QuerySet is a collection of objects from your database that can be filtered, ordered, or sliced. It is the primary way to retrieve data from the database using the Django ORM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3e3425d-6c89-4d5f-ae43-cab0b604698c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle errors in Express?', N'Intern', N'Error handling in Express is done by defining error-handling middleware functions that take four arguments instead of three. These functions must be defined after all other app.use and route calls to catch errors passed through the next function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a54487f8-2ce5-4130-b14e-cab1e7f6cdd0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch store data compared to a traditional relational database?', N'Intern', N'While a relational database stores data in rows and tables, Elasticsearch stores data as JSON documents. These documents are grouped into indices, which function similarly to tables but are optimized for fast retrieval and indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cacf28fb-a370-4f49-9cde-cab2bb4d1463', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security implications of utilizing serverless functions for critical processing?', N'Senior', N'Serverless functions reduce the attack surface by abstracting the OS, but they shift the risk to identity and configuration management. Security focus must move to securing function environment variables, IAM permissions, and limiting the scope of function triggers to prevent unauthorized execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2734025b-dae7-4379-9658-cab7a5ebe316', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you manage shared code in a microservices architecture to avoid coupling?', N'Senior', N'Avoid sharing code that contains business logic across services; instead, use shared libraries only for cross-cutting concerns like logging or authentication clients. If business logic needs to be shared, consider if the boundaries between services are correctly drawn or if that logic should be encapsulated in its own service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75edc074-9deb-4093-88d1-cab7ce98ff98', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How would you implement authentication middleware in Axum?', N'Middle', N'Authentication is usually implemented by creating a custom Tower Layer that intercepts the request, checks for credentials, and either proceeds to the next service or returns an unauthorized response. This layer can then be applied to specific routes or the entire router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c61331a-1b76-45a7-9ff4-cab87e3fc1e8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What are the architectural implications of ''Tombstones'' in deletion-heavy NoSQL workloads?', N'Senior', N'Since data is immutable in many NoSQL engines, deletions are handled by writing a ''tombstone'' marker. Over time, an accumulation of tombstones can degrade read performance and increase storage footprint, necessitating periodic compaction processes to reclaim disk space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7aafb56-df27-4a3b-9b37-cac2c97cfb3d', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the architectural trade-offs of using Async Local Storage compared to passing context explicitly through function arguments.', N'Senior', N'Async Local Storage allows for tracking context across asynchronous calls without cluttering method signatures, which is ideal for tracing or logging. However, it relies on complex internal V8 mechanisms that can be harder to debug and may introduce subtle performance overhead compared to the clean, predictable nature of explicit dependency injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
