INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2572b77-771d-45c1-9307-cac544f5761e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the Rails middleware stack and how does it affect request processing?', N'Middle', N'The middleware stack is a chain of components that process incoming HTTP requests and outgoing responses, handling tasks like sessions, cookies, and error logging. Each middleware can inspect, modify, or halt the request before it reaches the Rails controller, which allows for highly customizable cross-cutting concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d6f6f5c-b8ed-41bb-92ec-cac8b779e00c', N'075b8862-431c-4678-9767-f55359758a4a', N'What are directives in Vue.js? Can you give examples?', N'Intern', N'Vue.js directives are special attributes that manipulate the Document Object Model (DOM) based on the bound values. Despite closely resembling HTML attributes, directives are distinct and recognized by the v- prefix, e.g., v-bind. They are fundamental for data-driven applications and ensure the View remains synced with the ViewModel. Core Directives v-bind: Dynamically Setting Attributes The v-bind directive syncs an HTML attribute with a Vue.js expression. This is especially useful for setting dynamic classes, styles, and attributes, including inputs. Reactive Class Example: v-if and v-show: Conditionally Rendering Elements Both of these directives control an element''s visibility based on a Boolean. - v-if completely removes the element from the DOM when its attached value is false.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b70150a-74ca-4571-8a7c-caccb5d9a4fc', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the role of a task queue in a Node.js-based microservices architecture?', N'Middle', N'A task queue, like RabbitMQ or Redis, is used to decouple services and handle asynchronous background processing. By offloading tasks to a queue, the main application can respond immediately to the client while the heavy processing is handled independently by worker services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
