INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f71a1ac-9524-4adf-99cc-cae974104f97', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the impact of output buffering on PHP script execution?', N'Middle', N'Output buffering captures the output generated by a script before it is sent to the web server, allowing for header modifications or content manipulation after the script has started producing output. It can also improve performance by reducing the number of write calls to the web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f2ca7e9-9634-4766-8165-caef33dcea4a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle ''Graceful Shutdown'' to ensure data integrity during deployments?', N'Senior', N'Spring Boot can be configured to stop accepting new requests while allowing active requests to complete within a specified timeout period. This prevents abrupt connection termination, ensuring that ongoing transactions or background tasks have sufficient time to finish safely before the process exits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fd212b0-734e-4268-8c64-caf0068ae0bc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are literal types in TypeScript?', N'Junior', N'Literal types allow you to specify exact values that a variable can hold. For example, you can define a string variable that must be exactly ''red'', ''green'', or ''blue''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46e88c1d-a65e-48c3-a28a-caf1ec739fd8', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How do you conditionally render content in Preact?', N'Intern', N'Conditional rendering is achieved using standard JavaScript expressions like ternary operators or the logical AND operator within JSX. You evaluate a boolean condition and return the corresponding virtual nodes based on the result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f4b3811-9c0d-4acb-b044-caf2a39bdf83', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of a header file in C?', N'Junior', N'Header files are used to declare function prototypes, macros, and data structures that need to be shared across multiple source files. They act as an interface, allowing different parts of a program to know how to interact with provided functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c0e5aae-946d-4fe7-b7e3-caf2fa22efcf', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit ensure that updates are performed efficiently when multiple properties change simultaneously?', N'Senior', N'Lit uses a microtask-based batching strategy where all property changes are collected, and the ''performUpdate'' cycle is only executed once per task. This ensures that the component does not perform redundant DOM operations if several reactive properties are updated in the same execution context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3291c840-69d1-4da0-abca-caf57001916d', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the advantages and disadvantages of using database views?', N'Middle', N'Views simplify complex queries for users, enhance security by restricting access to specific columns or rows, and provide logical data independence. However, they can impact performance if they contain complex logic or joins, and they can sometimes be difficult to update compared to base tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4175c6db-729c-4b4c-a1fd-caf61cf6a573', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design an event-driven system to ensure that events are processed exactly once?', N'Senior', N'Achieving strict exactly-once processing is extremely difficult; I would focus on idempotent event consumers combined with a persistent storage mechanism to track processed event IDs. This allows the system to be ''effectively'' exactly-once by ignoring duplicate events that may arrive due to retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8a1cdd7-30dd-429e-a060-caf7540ee405', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'You are tasked with integrating a new third-party payment gateway that occasionally experiences high latency. How would you design the system to ensure that your application remains responsive and maintains data consistency?', N'Middle', N'I would decouple the payment processing from the user''s primary request path by implementing an asynchronous message queue. The system would acknowledge the user''s action immediately while the payment is processed in the background, using idempotency keys to ensure that retries do not result in duplicate charges. Additionally, I would implement a circuit breaker pattern to stop requests to the gateway if latency exceeds defined thresholds, protecting the application from cascading failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f1bc46d-a644-42a0-9ebd-caf8cbd04d8b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does it mean for Scala to be a hybrid functional and object-oriented language?', N'Intern', N'Scala treats every value as an object, inheriting the principles of object-oriented programming like encapsulation and inheritance. Simultaneously, it supports functional programming paradigms, such as treating functions as first-class citizens and emphasizing immutability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'160f99c2-9326-4a7f-93a5-caf98c2825dc', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the benefits of using an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point that handles cross-cutting concerns like authentication, SSL termination, request routing, and rate limiting. This centralizes management and simplifies the client-side experience by hiding the underlying complexity of the internal microservices structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09e29659-947f-4b8f-bfa4-cafe6f534c3e', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you handle environment variables securely in Node.js?', N'Middle', N'Sensitive information should never be hardcoded; instead, they should be loaded from environment variables or a secure secret management service. Use tools like dotenv for development and ensure that sensitive files are excluded from version control systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f911095f-7d16-4f0d-b07f-cb00d60d2f5a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the ''Form'' component in Remix and why it is preferred over standard HTML forms.', N'Senior', N'The Remix Form component provides an enhanced version of the native HTML form that intercepts submissions to enable client-side transitions. It maintains the native behavior for accessibility and progressive enhancement, while automatically handling loading states and submission revalidation through the framework''s internal state machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22d08ea0-6607-443d-a7a9-cb0217026c5c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core''s built-in dependency injection container handle circular dependencies, and what is the recommended architectural fix?', N'Senior', N'The built-in container does not support circular dependencies and will throw an exception during object resolution if one is detected. The architectural fix is to refactor the code to extract the shared logic into a third service or use the Service Locator pattern as a last resort, though refactoring is always preferred to maintain clean design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a274507-2a78-4dbb-88cc-cb040b770870', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the difference between a ''TemplateView'' and a ''ListView''?', N'Intern', N'A TemplateView is a generic view used to render a template without needing specific database logic. A ListView is a specialized generic view that automatically fetches a collection of objects from a model and displays them in a list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9f97e7-daba-4efc-87cd-cb057fc05e31', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are the architectural trade-offs of using Proxy-based state management in Qwik?', N'Senior', N'Proxy-based state allows Qwik to track precisely which components depend on which pieces of state, enabling highly granular reactivity. The trade-off is the underlying complexity of the Proxy object, which can lead to unexpected behavior if not handled according to the framework''s strict immutability and serialization rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eed05036-6574-4e28-89a9-cb07422c1b8a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the steps involved in return false usage', N'Intern', N'The return false statement in event handlers performs the below steps, 1. First it stops the browser''s default action or behaviour. 2. It prevents the event from propagating the DOM 3. Stops callback execution and returns immediately when called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a1ee9f2-a3de-4cfc-a295-cb077e621891', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the difference between Physical and Logical backups in MySQL and when to prioritize one over the other.', N'Senior', N'Physical backups copy the raw data files, which is significantly faster for large datasets and allows for rapid point-in-time recovery. Logical backups, created via tools like mysqldump, export data as SQL statements, offering better portability across MySQL versions and granular table-level restoration at the cost of slower performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'209f2eb7-4737-4f82-822f-cb07d38ab182', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the __call__ magic method?', N'Middle', N'The __call__ method allows an instance of a class to be invoked as if it were a function. This is useful for creating objects that maintain internal state while acting as callable entities, such as function decorators or specialized processors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6afa159c-c031-4f17-b68c-cb092e333097', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of an Index in a PostgreSQL database?', N'Fresher', N'An index is a data structure that improves the speed of data retrieval operations on a table. It works like an index in a book, allowing the database engine to find rows without scanning every single record in the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c96674d-e497-4f3a-9753-cb0e289a9026', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js handle caching for dynamic routes with many potential parameters?', N'Middle', N'Next.js uses cache tags or time-based revalidation to manage dynamic data. For routes with many parameters, you can use ''generateStaticParams'' to pre-render specific paths, while leaving others to be rendered on-demand and cached dynamically upon the first request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12810f8d-e2ec-4e7f-8fb4-cb0f415cf316', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a scenario where a load balancer is routing traffic to a ''healthy'' node that is actually failing?', N'Senior', N'I would examine the load balancer''s health check configuration to ensure that it is probing an endpoint that accurately reflects the service''s internal state rather than just the availability of the web server port. I would also look for ''false positive'' health checks where the service returns a 200 OK despite having lost connection to its critical backend dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95a2109e-3d2d-498f-a8e9-cb12d72b2ea8', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''Dispatchers'' concept influence coroutine performance?', N'Middle', N'Dispatchers determine which thread or thread pool a coroutine runs on, allowing developers to optimize tasks based on their nature. For example, using IO dispatchers for blocking operations prevents the main thread from freezing, while Default dispatchers are optimized for CPU-bound computational tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a59d99a1-b55c-4480-9bae-cb141399159f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you handle errors using try...catch blocks?', N'Fresher', N'To handle errors using try...catch blocks, you wrap the code that might throw an error inside a try block. If an error occurs, the control is transferred to the catch block where you can handle the error. Optionally, you can use a finally block to execute code regardless of whether an error occurred or not. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'760b6fca-6313-4314-a1b0-cb16f7827b35', N'075b8862-431c-4678-9767-f55359758a4a', N'What are watchers in Vue.js?', N'Intern', N'In Vue.js, watchers are key features that track data changes and enable developers to execute specific logic or tasks in response to those changes. These watchers are defined inside Vue components and serve as an indispensable tool for building reactive behavior. They work in tandem with the Vue instance to monitor specific data properties, methods, or even component options.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cae4d094-282a-4401-ac4a-cb1888468e79', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What happens during a ''Full Text Search'' in MySQL, and how does it differ from standard B-tree index usage?', N'Senior', N'Full-text search utilizes inverted indexes that map individual words to their document locations, enabling efficient keyword searching across large text blocks. Unlike B-tree indexes, which are optimized for range and equality lookups, inverted indexes are specifically designed for linguistic matching and relevance scoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4074cf3b-aea1-4aa4-afea-cb19479ec713', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ''Unsafe'' block function within the context of its safety guarantees?', N'Senior', N'Unsafe blocks do not turn off the borrow checker; they grant the developer permission to perform operations that the compiler cannot verify as safe, such as dereferencing raw pointers or calling FFI functions. The developer assumes the responsibility of upholding safety invariants, which must then be encapsulated in a safe abstraction to prevent leaking undefined behavior to the rest of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9990733b-a77e-459b-93bc-cb1ea6fffdc0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is JavaScript''s ''this'' binding considered a source of architectural complexity in larger systems?', N'Senior', N'The ''this'' context is determined by the call site rather than the lexical scope, which can lead to unexpected behavior in callbacks. This complexity necessitated the introduction of arrow functions, which lexically capture the surrounding context to provide predictable behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1badc7c1-4112-4e51-a012-cb1f159c78ea', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle feedback that suggests your initial approach was incorrect?', N'Intern', N'I view feedback as a learning opportunity rather than a personal critique. I ask clarifying questions to understand why my approach was not ideal, which helps me improve my mental model for future problem-solving.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36579962-032d-4892-8cae-cb21f2e448ac', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the benefit of the ''alias'' feature in Vite?', N'Fresher', N'The alias feature allows you to define shortcuts for import paths. This simplifies imports, especially in large projects where you might otherwise have to use complex relative path strings like ''../../../components''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdd8f8bd-c563-498d-a080-cb238efc5b8d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does it mean for Actix to be asynchronous?', N'Intern', N'Being asynchronous means Actix can handle multiple concurrent connections without blocking the execution thread. It utilizes Rust''s async and await syntax to perform non-blocking I/O operations efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
