INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6c32508-b57c-4468-9521-cb2939303f26', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an Actix-web ''Handler''?', N'Fresher', N'A handler is an asynchronous function that processes an incoming HTTP request and returns a response. These functions are associated with specific routes and are executed whenever a request matches that route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
