INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11281d5d-321b-430e-8efc-cb32c90dc0c2', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Why is the main method declared as ''public static void''?', N'Junior', N'The main method is public so the JVM can access it, static so it can be called without creating an instance of the class, and void because it does not return any value to the operating system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
