INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fb91af9-0f5a-4a4d-a80c-cb4142a2f89b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the role of the ''State'' extractor in Actix-web and why it is preferred over global variables for sharing data.', N'Middle', N'The State extractor provides a type-safe, dependency-injection mechanism to share application-wide data, such as database pools or configuration, across different request handlers. Using State is preferred over global variables because it ensures thread safety through managed ownership, facilitates easier unit testing via dependency mocking, and provides a clear lifecycle management for shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
