INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c52cd88a-2e35-4059-8aa9-cb547531718a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the functional interfaces Function<T,R>, DoubleFunction<R>, IntFunction<R> and LongFunction<R>?', N'Intern', N'Function - the interface with which a function is implemented that receives an instance of the class T and returns an instance of the class at the output R. Default methods can be used to build call chains ( compose, andThen). * DoubleFunction - a function that receives input Double and returns an instance of the class at the output R; * IntFunction - a function that receives input Integerand returns an instance of the class at the output R; * LongFunction - a function that receives input Longand returns an instance of the class at the output R.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1c905f6-56d1-43cc-a105-cb54cd42d2a6', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do NestJS Middleware differ from Interceptors?', N'Middle', N'Middleware has access to the raw request and response objects and executes before the route handler. Interceptors have access to the execution context and can transform both the request and the final response, offering more control over the data flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fda0f56-06de-40a9-8873-cb575006b647', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What are the primary challenges in implementing lock-free data structures in C++?', N'Senior', N'Implementing lock-free structures requires a deep understanding of atomic memory orderings and hardware-specific primitives like Compare-and-Swap (CAS). The main challenge is preventing ABA problems, where a memory location is modified and restored, tricking the algorithm into assuming no change occurred, and ensuring proper memory reclamation to avoid use-after-free errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9cc03ad-c020-4485-9935-cb58dfd5d3c1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does it mean for a reducer to be a pure function?', N'Intern', N'A pure function is a function where the return value is determined solely by its input values, without observable side effects. This means a reducer should not modify its arguments or call external APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5044637-4073-416c-9e74-cb5f5593f20d', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why might you choose to implement a custom server middleware in Nuxt instead of handling logic in a component?', N'Senior', N'Server middleware operates at the request/response lifecycle level, making it ideal for cross-cutting concerns like authentication, logging, or header manipulation. Handling this in components would be inefficient and insecure, as component logic only executes after the request has already been processed by the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a35715e2-3373-480b-9b6c-cb6040f288a1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where a teammate disagrees with your proposed technical design?', N'Middle', N'I would request a structured technical review to discuss the specific trade-offs, constraints, and long-term implications of both approaches. By focusing on data-driven metrics and project requirements, we can find a middle ground or conduct a small-scale proof of concept to validate which design performs better.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a40207a5-8b64-481d-bb3c-cb62078d973b', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the Spring Boot Starter project?', N'Junior', N'Starters are a set of convenient dependency descriptors that you can include in your application. They bundle all the necessary dependencies to get started with a specific technology, such as web development or database access, without needing to manage individual library versions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7dae17d-5b3c-4dad-aa4f-cb628e11c83e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do generics improve code quality and performance?', N'Middle', N'Generics allow developers to write flexible, reusable functions and types that work with any data type while maintaining strict type safety. At compile time, the compiler specializes the generic code, often eliminating the need for type casting and improving execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f6d6683-3838-4482-b58d-cb646f095e61', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit manage the ''flash of unstyled content'' (FOUC)?', N'Senior', N'Because SvelteKit performs server-side rendering, the HTML is sent to the browser with the necessary styles applied, ensuring the layout is ready before the client-side JavaScript finishes executing. This architectural decision eliminates FOUC and provides a smooth experience for users on slower networks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81c92c3d-0f59-4ef2-a2bb-cb652c4a1e1c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the limitations of R''s single-threaded execution model for parallel processing?', N'Senior', N'R''s base interpreter is single-threaded, meaning it cannot natively utilize multi-core architectures for simultaneous computation without external intervention. Parallelism must be achieved through process-level parallelism using packages that spawn separate R instances, which introduces significant serialization overhead for data transfer between cores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5ca5cd0-15fc-4089-aac6-cb679826ff50', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the risks of circular dependencies between Actix actors?', N'Senior', N'Circular dependencies can lead to deadlocks if two actors wait for each other to complete a message before they can process the next request in their mailbox. Furthermore, they can prevent the graceful shutdown of the system, as neither actor will drop its address to the other, keeping both alive indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42884a9b-bf05-4bc2-b752-cb67a5e9daa7', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Explain the trade-off between readability and performance in code.', N'Fresher', N'Readable code uses clear abstractions and naming conventions that are easy for humans to maintain but may introduce slight execution overhead. High-performance code often uses complex, low-level optimizations that make it faster for the machine but harder for developers to understand and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00f2620c-2deb-4862-a4c1-cb695b26b73c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the definition of a higher-order function in JavaScript?', N'Intern', N'A higher-order function is any function that takes one or more functions as arguments, which it uses to operate on some data, and/or returns a function as a result. Higher-order functions are meant to abstract some operation that is performed repeatedly. The classic example of this is Array.prototype.map(), which takes an array and a function as arguments. Array.prototype.map() then uses this function to transform each item in the array, returning a new array with the transformed data. Other popular examples in JavaScript are Array.prototype.forEach(), Array.prototype.filter(), and Array.prototype.reduce(). A higher-order function doesn''t just need to be manipulating arrays as there are many use cases for returning a function from another function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6af7f71-f7cc-4d0e-b1ec-cb699989a358', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle concurrency?', N'Fresher', N'Rust handles concurrency by enforcing safety rules through its ownership and type system at compile time. This prevents data races because the compiler ensures that mutable data cannot be accessed by multiple threads simultaneously without synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93a8c08f-704b-45bb-8544-cb6bc254debc', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go ensure the atomicity of map operations?', N'Senior', N'Go maps are not inherently thread-safe; concurrent read/write operations result in a runtime panic. The Go runtime implements a non-blocking hash map with bucket-level locking or atomic operations for some internal state, but it does not provide high-level synchronization for user data. Developers must use synchronization primitives like sync.RWMutex or sync.Map to ensure atomicity when accessing maps from multiple goroutines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce5a1a83-308e-4e57-92ce-cb7419dac917', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the @Global() decorator?', N'Junior', N'The @Global() decorator makes a module global, meaning its exported providers are available in all other modules without needing to import them explicitly. It should be used sparingly to avoid making dependencies unclear.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13c2b438-ab0e-408c-90cd-cb7539f5c12c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is a ''library'' in Dart?', N'Intern', N'A library is a way to organize and share code in Dart, typically consisting of one or more files. It allows developers to encapsulate functionality and control the visibility of classes and functions using private or public access modifiers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52587194-7d29-4fcc-9c01-cb7626af470e', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What trade-offs are involved when choosing between embedded documents and references?', N'Middle', N'Embedding provides faster read performance for related data and atomic updates within a single document but can lead to document size limits. Referencing allows for flexible data relationships and normalization but requires application-level joins or multiple queries to fetch related data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'010abd41-bbde-40cc-9920-cb76f9d9e06f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the @debug directive used for?', N'Intern', N'The @debug directive is used to print information to the terminal during the compilation process. It is a helpful tool for developers to inspect the values of variables or verify that their logic is working as intended while building.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8e9c1f0-fad0-4579-95d7-cb7747b3b57c', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite use esbuild to achieve high performance?', N'Middle', N'Vite uses esbuild to pre-bundle dependencies and transform TypeScript or JSX files. Because esbuild is written in Go, it performs these tasks 10-100 times faster than JavaScript-based bundlers, significantly reducing cold start times and HMR latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb31d359-2fc0-424d-b314-cb78d3e7ad5c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS perform server-side rendering (SSR)?', N'Middle', N'SolidJS supports streaming SSR, where it sends the HTML as it becomes available. This improves the Time to First Byte and allows the client to hydrate individual components or sections of the page independently as they become interactive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ac69d94-7840-4995-ba05-cb7c18951bb5', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the impact of ''Fencing Tokens'' in distributed locks?', N'Senior', N'Fencing tokens are monotonically increasing numbers assigned to a client holding a lock, used to detect late-arriving requests from clients that may have been paused by a garbage collection pause. This prevents ''zombie'' clients from committing data after their lock lease has expired and been granted to another process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc7b0969-8448-4483-93f9-cb7dca92f199', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to ask for help before spending hours stuck on a problem?', N'Junior', N'Spending too much time on a single problem can lead to diminishing returns and missed deadlines, which impacts the whole team. Asking for help after a reasonable amount of effort shows professional maturity and allows the team to leverage collective knowledge to solve the issue faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8495b438-b719-4830-afcf-cb7e1caff7d5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do distributed databases handle ''clock skew'' when using logical or physical clocks for timestamping?', N'Senior', N'Systems handle clock skew by employing hybrid logical clocks or vector clocks to establish a partial ordering of events that is independent of physical time. This prevents causality violations in distributed systems where NTP-synced physical clocks might drift, ensuring that the database can correctly reconcile concurrent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ece3b63-55f8-40c6-b975-cb8025046252', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does the ''Two-Phase Commit'' (2PC) protocol function?', N'Middle', N'2PC uses a coordinator to first ask all participating nodes if they are ready to commit (prepare phase) and then commands them to finalize the commit (commit phase). If any node fails during the prepare phase, the coordinator instructs all nodes to abort, ensuring atomic outcomes across distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'163b52eb-582b-4efd-900c-cb80e370362b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the architectural trade-offs of using WeakReferences for caching?', N'Senior', N'WeakReferences allow objects to be garbage collected when memory is tight, providing a natural mechanism for cache eviction. The trade-off is the loss of control over the eviction policy, as the GC''s timing is non-deterministic, which can lead to unpredictable cache hit rates under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd542f0bd-529f-4922-a145-cb81e7d48db4', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''req'' and ''res'' objects?', N'Fresher', N'The req object represents the HTTP request and has properties for the request query string, parameters, body, and headers. The res object represents the HTTP response that the Express app sends when it receives an HTTP request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fa31bf-ea5e-400c-9ece-cb820420f225', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the implications of using Sass to generate thousands of utility classes?', N'Senior', N'Generating excessive utility classes via Sass loops can result in a massive CSS file size that increases the browser''s parsing time and creates a heavy DOM. It is usually more performant to use a pre-compiled utility framework or implement Just-In-Time generation strategies if a large volume of variations is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7dac83d0-a965-4a6c-a9ac-cb83838a1818', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the architectural benefits of using ''Duck'' or ''Feature-based'' directory structures in Redux.', N'Senior', N'Feature-based structures group all logic related to a specific domain—actions, reducers, and selectors—together, which improves maintainability and encapsulation. This reduces the cognitive load of navigating the codebase and makes it easier to add, remove, or refactor features without affecting unrelated parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbed70a0-bc67-4d0f-afc9-cb8408a3f370', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a list in Python?', N'Intern', N'A list is a built-in data structure that stores a collection of items in a specific order. Lists are mutable, meaning you can change, add, or remove items after the list has been created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dc84aa3-8455-4586-b410-cb854261ad4e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between pushing data (WebSockets) and polling for real-time updates?', N'Senior', N'WebSockets provide low-latency, real-time communication but require stateful connections that are harder to scale and load balance. Polling is simpler to implement and scales well, but it introduces latency and unnecessary overhead, making it only suitable for lower-frequency updates or where strict real-time performance is not required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d4098b6-e6e2-4b6d-aebd-cb867c6bcec5', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Discuss the impact of cache stampede (thundering herd) and how to mitigate it.', N'Senior', N'Cache stampede occurs when a popular key expires and multiple concurrent requests hit the database simultaneously to regenerate the value. It can be mitigated by using probabilistic early expiration, mutex locks on the cache miss, or background refresh strategies to ensure only one process updates the cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61b07399-b189-4c42-9af9-cb87e8f3d877', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does dependency injection work in Litestar?', N'Fresher', N'Dependency injection in Litestar allows you to define dependencies that are automatically provided to route handlers when called. These are declared as function arguments, and the framework resolves and injects the required values at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15e81133-4a0d-4a59-8f54-cb8bc417495f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik need a ''Virtual DOM''?', N'Fresher', N'Qwik does not rely on a traditional Virtual DOM in the same way as frameworks like React. Its architecture is focused on direct DOM updates and efficient serialization, which reduces memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f64da021-a249-4488-9b69-cb8ede04c861', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between request data and form data?', N'Intern', N'Request data generally refers to any information sent by the client, including query strings in the URL. Form data specifically refers to the key-value pairs submitted when a user fills out and submits an HTML form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55b96c26-73b3-428f-94d1-cb8eef7aaf12', N'954a0331-deff-4399-b588-96f39fec001d', N'Why is it recommended to use ''readonly'' or ''private'' members in components?', N'Middle', N'Using access modifiers improves code maintainability and encapsulation by clearly defining which properties are public API and which are internal. It prevents external components from accidentally modifying the internal state, reducing bugs and side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f761312-291f-4e30-b34a-cb8fb6cfd659', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain the role of Middleware in an ASP.NET Core request pipeline.', N'Fresher', N'Middleware components are software parts assembled into an application pipeline to handle requests and responses. Each component chooses whether to pass the request to the next component in the pipeline and can perform actions before or after the next component is invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5f65eb3-f5dd-4c7c-a6da-cb923e81a0a3', N'4c000000-0000-0000-0000-000000000005', N'What is the architectural purpose of a CQRS pattern?', N'Senior', N'CQRS separates read and write operations into different models, allowing each to be scaled and optimized independently. This is particularly useful in systems where read patterns are distinct from write patterns, enabling the use of specialized stores like Elasticsearch for search and relational databases for transactional integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a096e10-1638-4522-b88c-cb944ba27c19', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you define default values for request parameters?', N'Junior', N'Default values can be defined by assigning them in the function signature of your path operation. If the client does not provide the parameter in the request, FastAPI will automatically use the assigned default value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d599464-336d-4701-9de9-cb94c706100a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are Redis ''Replication'' and ''Master-Slave'' architecture?', N'Intern', N'Replication allows one Redis instance (the master) to copy its data to one or more instances (the slaves). This provides redundancy and allows read operations to be spread across multiple servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc8af457-4b75-42c2-9b48-cb94e2f9a4fc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the advantage of using ''reply.hijack()'' in Fastify?', N'Middle', N'The hijack method allows you to take control of the underlying Node.js raw response object, bypassing Fastify''s default serialization and lifecycle handling. This is useful for streaming large files or implementing custom protocols like WebSockets where the standard JSON-centric response flow is inappropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32af209b-2a06-455c-a2e1-cb98d68c0f74', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a session and a cookie?', N'Junior', N'A cookie is a small piece of data stored on the client''s browser, while a Flask session is a server-side or client-side storage mechanism that uses cookies to track user state. Sessions allow you to store user-specific information across multiple requests securely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
