INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb694bb3-9d9c-425c-b5ca-cb9c7204b5f1', N'075b8862-431c-4678-9767-f55359758a4a', N'How does the ''keep-alive'' component manage state during component transitions?', N'Senior', N'Keep-alive caches component instances in an internal map when they are toggled out of the DOM, preserving their state and DOM tree. This avoids the cost of destroying and re-mounting components during navigation, though it requires careful management of lifecycle hooks like onActivated and onDeactivated to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'192fa651-c515-4f2b-9ea9-cb9cb2f09159', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are the limitations of ''Structural Typing'' in TypeScript compared to ''Nominal Typing''?', N'Senior', N'Structural typing determines compatibility based on members, which facilitates flexibility but can allow accidental type mismatches if two types happen to share the same shape. Nominal typing enforces identity based on explicit declaration, preventing unintended assignment even if the structures match.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a573a91-b72a-4dd9-9f80-cb9e7648797a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the function of the Spring Data JPA repository?', N'Junior', N'Spring Data JPA repositories abstract data access by providing standard CRUD operations without requiring boilerplate implementation code. By extending interfaces like JpaRepository, you get built-in methods for database interaction based on your entity types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99525561-cd16-4626-ab00-cb9f47598cdf', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s ''Test Helpers'' facilitate integration testing compared to manual DOM manipulation?', N'Senior', N'Ember''s test helpers simulate user interactions and wait for asynchronous operations like routing or data loading automatically. This makes tests more robust, less flaky, and ensures they reflect real user behavior rather than just testing implementation details.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77385fbb-4d7a-4d4a-bb71-cba1c89ad8e4', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the concept of Dependency Injection in AdonisJS.', N'Fresher', N'Dependency Injection is a design pattern where an object receives other objects that it depends on, rather than creating them internally. AdonisJS uses an IoC (Inversion of Control) container to manage these dependencies, which makes the code more modular and easier to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'732c5a6a-c5fb-4fac-aea0-cbaccc0c05c9', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the role of ''ng-template'' and ''ng-container''.', N'Middle', N'ng-template defines a block of code that is not rendered until explicitly instructed by a directive, while ng-container is a grouping element that does not introduce extra DOM nodes. Both are essential for structural directives like ngIf or ngFor when complex template logic is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db636e9c-4066-4c84-be7b-cbaccca35745', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why should you use an application factory pattern in a production Flask project?', N'Middle', N'An application factory allows you to create multiple instances of the app with different configurations, such as separate settings for testing, development, and production. It also avoids circular imports by allowing you to register blueprints and extensions after the application object has been initialized. This pattern is essential for writing clean, modular, and testable codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a046968-0741-47f9-8e4d-cbb1098c55f8', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is Dart and where is it primarily used?', N'Fresher', N'Dart is a client-optimized programming language developed by Google. It is primarily used for building fast, multi-platform applications including mobile, web, and desktop software, most notably through the Flutter framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d06bf68-8e89-4fbe-88b1-cbb267b073a3', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of jQuery events?', N'Fresher', N'jQuery events allow a web page to respond to user interactions, such as clicking a button, hovering over an element, or submitting a form. These events trigger specific functions to update the page content dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8552c9e0-d195-46f1-9863-cbb5bfa3cde3', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle service-to-service authentication and authorization in a distributed microservices environment?', N'Senior', N'I utilize a zero-trust model, typically implementing short-lived mTLS for transport security and identity-aware tokens like JWTs or SPIFFE/SPIRE for service identity. Authorization is managed via centralized policy engines like OPA to decouple business logic from security enforcement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ac4ed6d-7265-4eab-9612-cbb7500f35da', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why might you use a custom JSON encoder with Gin instead of the standard library one?', N'Middle', N'The standard library''s JSON encoder is sometimes slower than specialized alternatives like ''json-iterator/go''. Using a faster encoder can significantly reduce CPU usage and latency in applications that handle high volumes of JSON-heavy traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'844b8860-d8ea-4cb6-abff-cbb850575ff6', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of an API Controller?', N'Intern', N'An API Controller is designed to handle HTTP requests for web services that return data rather than views. It typically returns data in formats like JSON or XML and uses specific attributes to define routing and HTTP methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a5ddf5d-c5ed-401b-b791-cbbe7b63d1c9', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is it important to use .lazy or .debounce modifiers in Alpine.js?', N'Middle', N'These modifiers optimize performance by controlling how often state updates are triggered. .lazy delays updates until the input loses focus, while .debounce limits the frequency of updates during rapid input, preventing unnecessary re-renders and potential performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7d221e0-69a7-49a0-bca9-cbc0e0e76e3a', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django''s ORM handle database transactions, and how can you manage them manually?', N'Middle', N'By default, Django wraps each HTTP request in a transaction if ATOMIC_REQUESTS is enabled in settings. You can manage them manually using the atomic decorator or context manager, which ensures that all database operations within the block succeed or fail as a single unit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0306dec-ea3a-48a7-a474-cbc35306ad8d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the difference between @Transactional propagation levels REQUIRED and REQUIRES_NEW.', N'Senior', N'REQUIRED joins an existing transaction if one exists, otherwise it creates a new one. REQUIRES_NEW always suspends the current transaction and creates a brand-new, independent transaction, ensuring that the inner operation is committed or rolled back regardless of the outer transaction''s outcome.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
