INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b665ce0-e1a2-4221-914a-cbf036df46df', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How would you implement a multi-tenant architecture in Django, and what are the trade-offs of the shared-database approach?', N'Senior', N'Multi-tenancy is typically implemented via shared-database with a tenant identifier column or separate databases per tenant. The shared-database approach is easier to maintain and migrate but requires strict filtering on every query and poses a higher risk of data leakage between tenants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
