INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ac231c3-13d6-4b01-8ff2-cbf70ce81f8d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the benefit of using ''Response Model'' in FastAPI path operations?', N'Junior', N'The response_model parameter allows you to define a Pydantic schema for the data returned by an endpoint. This ensures that the output is automatically filtered, validated, and serialized to JSON, providing a clear contract for API consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b410c112-6af6-4d50-a466-cbf7f659d2e4', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of Write-Ahead Logging (WAL) in database durability?', N'Senior', N'WAL ensures data integrity by logging all modifications to a persistent file before applying them to the actual data pages. In the event of a crash, the database can reconstruct its state by replaying these logs, ensuring that committed transactions are not lost even if the buffer pool wasn''t flushed to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2de7ed1-84a8-449d-818e-cbfc55dde1d5', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s reflection API facilitate the creation of modern frameworks?', N'Middle', N'The reflection API allows code to inspect other code at runtime, including classes, methods, and parameters. Frameworks use this capability to perform dependency injection, auto-wire services, and parse annotations or attributes to configure application behavior dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09ca9620-26df-49a5-8118-cbfc87a34f66', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the impact of using ''use client'' in a deeply nested component tree?', N'Senior', N'Using ''use client'' marks the entry point into the client-side bundle, transitioning the rendering process from the server to the browser. While necessary for interactivity, overusing it in deep trees can increase the JavaScript bundle size and prevent the rest of the component tree from benefiting from server-side rendering optimizations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d4ba447-d30f-424f-944b-cbfc91c38676', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go’s approach to interface satisfaction handle pointer receivers versus value receivers?', N'Senior', N'If a method is defined on a pointer receiver, the interface can only be satisfied by a pointer to that type, whereas a value receiver can be satisfied by both a value and a pointer. This distinction is crucial for maintaining method set consistency and ensuring that interface implementation behaves predictably regarding object mutability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8861c51-9134-4823-b546-cbfce4d43f46', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What impact does Alpine.js have on Search Engine Optimization (SEO)?', N'Middle', N'Because Alpine.js is designed to work with server-side rendered HTML, it is generally SEO-friendly. Search engines receive the fully rendered content immediately, unlike client-side rendered frameworks that might require the search engine to execute JavaScript to reveal the page content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce3a4635-0aed-4112-9067-cbfe24b0ffbc', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a database lock?', N'Intern', N'A lock is a mechanism used by the database to restrict access to a specific piece of data during a transaction. It ensures that multiple users do not try to modify the same data simultaneously, preventing conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35a2a8b6-8c42-4035-8869-cbffab091a21', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the usecases of useLayoutEffect?', N'Intern', N'You need to use useLayoutEffect when your effect must run before the browser paints, such as: * Reading layout measurements (e.g., element size, scroll position) * Synchronously applying DOM styles to prevent visual flicker * Animating layout or transitions * Integrating with third-party libraries that require DOM manipulation If there''s no visual or layout dependency, prefer useEffect — it''s more performance-friendly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9172878d-a0f5-43bc-ab52-cc029460b668', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is Fastify''s view on encapsulation?', N'Junior', N'Encapsulation ensures that plugins have their own scope, meaning that decorators and hooks registered in one plugin do not leak into another. This prevents side effects and makes large applications easier to maintain and test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'295973b8-454f-400d-b4a1-cc02b69ab05d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of a ''dummy'' or ''mock'' object in debugging?', N'Fresher', N'Mock objects simulate the behavior of complex components like databases or APIs, allowing you to test specific logic in isolation. This helps determine if an error is occurring within your code or within the external service you are interacting with.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09250aaa-67a3-4912-a890-cc05c0b05c93', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you design a system to ensure data consistency across multiple microservices?', N'Middle', N'I would favor eventual consistency using the Saga pattern to manage distributed transactions through a series of local transactions and compensating actions. If strong consistency is mandatory, I would consider a two-phase commit, though I would warn against the performance and availability trade-offs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cd24af1-c5f7-4242-a912-cc0838ce8cd7', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix utilize connection pooling for performance?', N'Senior', N'Actix relies on external connection pool libraries like r2d2 or sqlx-pool, which are injected via app_data. These pools manage a set of persistent connections, preventing the overhead of frequent TCP handshakes and authentication for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2fb2c3-81cb-4b69-9b93-cc0899d59d36', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the architectural difference between a ''Layout'' and a ''Component'' in Astro.', N'Senior', N'Components are modular, reusable pieces of UI that encapsulate their own logic and styling. Layouts are specialized components designed to act as wrappers, providing structural consistency—such as headers and footers—across multiple pages while accepting nested content via the ''slot'' mechanism.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'664bd69c-1386-4bdf-947d-cc0907395abf', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your process for choosing between horizontal and vertical scaling?', N'Middle', N'Vertical scaling is usually simpler but has a hard limit based on the physical capacity of the hardware. I prefer horizontal scaling because it offers better fault tolerance and nearly unlimited growth potential. I choose horizontal scaling when the system workload is predictably high and requires redundancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04f27735-4ef0-4e16-ad39-cc09b72de5ac', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the ''Micronaut Data'' project in database access?', N'Middle', N'Micronaut Data is a repository implementation toolkit that generates data access code at compile-time. It eliminates the need for reflection-based runtime implementations, resulting in faster performance and catching potential query errors during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
