INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d5fed2c-3f56-4efd-94b8-cc0b2e56a57e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do ''Observers'' and ''Inspectors'' in the BEAM assist in debugging Phoenix applications?', N'Senior', N'BEAM tools like :observer allow developers to visualize the supervision tree, process memory, and message queues in real-time. This provides deep visibility into the system''s state, enabling the identification of memory leaks, deadlocks, or process bottlenecks that are otherwise invisible in standard logging systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02059852-6b9f-4285-988d-cc0bdadc8ae7', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a Flask ''blueprint'' and the main application object?', N'Junior', N'A Flask application object represents the entire web service, while a blueprint is a way to organize related routes, templates, and static files into modular components. Blueprints allow developers to break down large applications into smaller, manageable parts that can be registered to the main application object later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98aa322d-0dca-4080-bc06-cc0cb1021299', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a Proc in Ruby?', N'Intern', N'A Proc is an object that encapsulates a block of code, allowing it to be stored in a variable and passed around as an argument. Procs provide a way to treat code as data, which is a core feature of functional programming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e187b7b9-e820-4b8b-ad95-cc0ec8a90521', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you account for non-development time, such as meetings or bug fixes, when estimating project completion?', N'Junior', N'I calculate my available capacity by subtracting recurring commitments like meetings and estimated support time from the total work hours. I then apply this reduced capacity to my estimates to ensure I do not overcommit based on an unrealistic expectation of full-time coding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'decdae69-2f1e-4d4c-9312-cc0f41dce1a6', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of Django''s ''Session'' framework?', N'Junior', N'The session framework allows you to store and retrieve arbitrary data on a per-site-visitor basis. It uses a cookie on the client side to keep track of the user''s state across multiple requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c383a8f-7318-49c4-84ee-cc108dca54f9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'You are assigned a task that seems much larger than the time remaining in the sprint. What do you do?', N'Junior', N'I would break the task down into smaller, manageable sub-tasks and identify if any parts can be deferred or simplified. I would then communicate with my manager or the product owner to discuss the scope and potential timeline adjustments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61ef4929-fe9b-4fc4-b6cd-cc11d78477c7', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the benefit of using gRPC instead of REST in microservices?', N'Middle', N'gRPC uses Protocol Buffers, a binary serialization format that is more compact and faster to parse than JSON. It also leverages HTTP/2, enabling multiplexing and streaming, which results in significantly lower latency and higher throughput for internal service-to-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27f4ffc8-1d01-4639-887c-cc1376d6a432', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle schema migrations in a Flask application?', N'Middle', N'Schema migrations are best handled using a tool like Flask-Migrate, which is a wrapper around Alembic. It tracks changes to your database models over time and generates versioned migration scripts, allowing you to reliably upgrade or downgrade your database schema as your application evolves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53a84de4-3149-48e3-8718-cc15c10d3332', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is meant by Flask being a ''micro-framework''?', N'Intern', N'Being a micro-framework means that Flask is designed to be simple and extensible. It does not include built-in features like database abstraction or form validation by default, but allows developers to add these features via extensions as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'913d47e2-28aa-4da5-b0a3-cc163000dcfd', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''N+1'' query problem and how can it be avoided?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a list of items and then executes ''N'' additional queries to fetch related data for each item. It can be avoided by using eager loading or batching requests to fetch all necessary data in fewer queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55e28d8e-d0b9-41f3-b63e-cc1a58d5cb3d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the difference between JSON() and IndentedJSON() in Gin?', N'Junior', N'JSON() serializes the object into a compact string, which is standard for API performance. IndentedJSON() adds whitespace and line breaks to the output, making the response much more readable for developers during debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cd9177e-02ef-4f34-8fb9-cc1b21aa77ac', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the concept of ''eager loading'' versus ''lazy loading''.', N'Middle', N'Lazy loading fetches associated data only when it is explicitly accessed in the code, which can cause performance issues like N+1 queries. Eager loading fetches the associated data upfront, typically in a single join or a separate query, significantly reducing the total database round-trips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b0ce865-a2b6-4023-a4ea-cc24a529bce3', N'075b8862-431c-4678-9767-f55359758a4a', N'What is composition API?', N'Intern', N'The Composition API in Vue 3 is a new way to organize and reuse logic in Vue components. It was introduced to address some limitations of the Options API (used in Vue 2), especially when dealing with large or complex components where logic can become scattered and hard to manage. The Composition API is a set of APIs (e.g., setup(), ref, reactive, computed, watch, etc.) that allow developers to compose component logic more flexibly and cleanly, especially when logic is reused across components. Key Concepts', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4048d14-f64e-4bf0-9f23-cc26a061adca', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the role of the Spring Boot ''Application Context''?', N'Middle', N'The Application Context is the central interface for providing configuration to the application. It acts as a container that manages the lifecycle of beans, performs dependency injection, and provides access to application components, resources, and event publishing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'359cb0fd-3b50-4ba3-80c2-cc272095de87', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the challenges of performing continuous security scanning in a CI/CD pipeline?', N'Senior', N'The primary challenge is balancing developer velocity with the time required for comprehensive scanning, such as SAST and DAST. Overly strict or slow scanners can become a bottleneck, leading to developer frustration; success requires integrating lightweight scanners early in the pipeline and handling high-fidelity alerts that provide actionable remediation advice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51888592-1a9a-4fdc-b905-cc2843214f98', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle error management compared to traditional exception-based languages?', N'Junior', N'Go treats errors as regular values rather than using try-catch exception blocks. Functions typically return an error as the final return value, which the caller is expected to check explicitly, making control flow more transparent and preventing hidden runtime crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ca5a5f2-ef46-4c20-afb4-cc287bcb99c1', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust require explicit ''mut'' keywords for variable mutability?', N'Senior', N'Explicit mutability makes side effects visible at the call site, which aids code auditing and prevents unintentional state changes. By defaulting to immutability, Rust encourages functional programming patterns that lead to safer, more concurrent, and easier-to-reason-about codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75e5a8e3-f19f-4794-8d60-cc2974f6a7b2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How can you pass data into an Alpine component?', N'Fresher', N'You can pass data into a component by setting the initial state within the x-data attribute. This object can contain variables, arrays, objects, and even methods that the component will use throughout its lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'705dd6f3-7e7b-4913-b136-cc297f149acd', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it generally better to validate user input on both the client-side and the server-side?', N'Fresher', N'Client-side validation provides immediate feedback to the user and improves the overall experience. Server-side validation is essential for security, as it acts as the final gatekeeper to prevent malicious data from reaching the database, regardless of how the request was sent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0192b107-b93e-4e7e-9bfa-cc2a23d7ce92', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R''s copy-on-modify mechanism affect performance in memory-intensive applications?', N'Middle', N'R uses a copy-on-modify semantic, meaning that when an object is modified, R creates a new copy in memory rather than changing the original in place. While this ensures functional purity and avoids side effects, it can lead to significant memory overhead and performance degradation when working with large data structures. Developers must be cautious with loops that repeatedly modify objects, as this triggers frequent memory reallocations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eab69d7a-6871-4c33-9454-cc2edb5bf050', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the difference between active and passive expiration in cache systems?', N'Senior', N'Passive expiration removes an entry only when it is accessed and found to be expired, which is low overhead but keeps stale data in memory. Active expiration periodically scans the cache for expired keys and removes them, ensuring better memory utilization at the cost of background CPU usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1a51ce9-4e02-400c-b122-cc2f70034871', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a production incident where the root cause is unclear and the team is panicking?', N'Senior', N'I would immediately establish a clear communication loop, appoint an incident commander, and focus on mitigating the impact first—such as rolling back recent changes or diverting traffic. Once the system is stabilized, I would move to a structured investigation, ensuring all findings are documented to prevent bias or circular reasoning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45080629-abfb-4dc8-9b4c-cc33bd72ad11', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do mixins handle arguments?', N'Fresher', N'Mixins can accept arguments, which act like variables that you pass into the mixin when calling it. This makes mixins highly flexible, as you can customize the output of the same mixin based on the specific values provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'837b7bd8-3e5a-447a-b09f-cc36b23fde77', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of file-based routing?', N'Intern', N'File-based routing simplifies development by using the directory structure to define routes. This eliminates the need for complex configuration files to map URLs to specific page components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fc7b82e-bff0-4ad5-bbb3-cc372b0cf205', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a pointer?', N'Intern', N'A pointer is a variable that stores the memory address of another variable. It allows for indirect access to data and is fundamental for dynamic memory management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa5307ed-6b64-42d5-8ef3-cc3dfd442bab', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How do Sort Keys facilitate complex data retrieval?', N'Senior', N'Sort keys allow for hierarchical data organization and range-based queries, such as fetching all items for a specific user within a specific time window. They enable efficient filtering and sorting of data at the storage level without requiring secondary indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ea59796-a7e7-485d-92cd-cc3eb7523208', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the role of the Garbage Collector in C#.', N'Junior', N'The Garbage Collector automatically manages the allocation and release of memory for applications. It periodically identifies objects that are no longer being used by the application and frees the memory they occupied to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'042bcddc-e649-441f-b4f2-cc40db22ec00', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you handle errors in async/await, and what are the pitfalls of unhandled rejections?', N'Fresher', N'Errors in async functions are handled with standard try/catch/finally blocks. An awaited Promise that rejects throws at the await expression, which catch intercepts exactly like a synchronous throw. Key pitfalls: 1. Forgetting await — the Promise is created but not awaited; errors are silently swallowed. 2. Missing catch — an unhandled rejection in Node.js (since v15) causes the process to exit with a non-zero code; in browsers it fires window.unhandledrejection. 3. try/catch around non-awaited Promises — try only catches synchronous throws and awaited rejections, not fire-and-forget Promises inside the block. 4. Partial failure in loops — await inside a for loop is sequential; one failure aborts all subsequent iterations unless each is individually caught.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'657d6159-463d-4e76-8842-cc47d00e098e', N'954a0331-deff-4399-b588-96f39fec001d', N'How do Signals improve upon the traditional RxJS-based reactivity in Angular?', N'Senior', N'Signals provide a fine-grained reactivity model that tracks dependencies automatically, reducing the frequency of redundant change detection cycles. Unlike RxJS, which can lead to complex streams and subscription management issues, Signals offer a simpler, synchronous API that is easier to debug and more performant for UI state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13f9d3cb-a9cf-4f4d-af11-cc4978d1b87e', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the concept of the ''Hidden Classes'' optimization in V8.', N'Middle', N'V8 uses hidden classes to track the structure of objects at runtime, allowing it to optimize property access by caching offsets. When objects have a consistent structure, the engine can generate faster machine code, improving overall execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34098756-dc1f-45fd-aa35-cc49bd5f9e73', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you return a specific HTTP status code in Gin?', N'Junior', N'You can use the ''Status'' method on the context object to set the response code manually. Alternatively, helper methods like ''JSON'' or ''String'' accept a status code as an argument to finalize the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'317a42c1-9495-4d41-ad1c-cc4a2c5351f7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between synchronous and asynchronous programming?', N'Junior', N'Synchronous programming executes tasks one after another in a specific order, where each task must complete before the next one starts. Asynchronous programming allows tasks to start and run in the background, preventing the main thread from being blocked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96c2ac76-d405-4275-aa07-cc4bb0e8968d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s partial hydration approach differ from traditional frameworks like React?', N'Senior', N'SvelteKit utilizes a compiler-first approach where component logic is transformed into efficient imperative code rather than relying on a heavy virtual DOM runtime. This results in smaller bundle sizes and faster time-to-interactive, as the framework hydrates only the necessary parts of the DOM with minimal overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7098b188-6593-4c6a-948a-cc4c4bf1ade5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do decorators modify function behavior without altering the source code?', N'Senior', N'Decorators are high-order functions that take a function as input and return a wrapper function, effectively wrapping the original logic in additional functionality. This pattern allows for cross-cutting concerns like logging or caching to be implemented as composable, reusable layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6aca4e6-8b05-42cf-9faa-cc4c4cb9cf95', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What does the Atomicity property mean in a transaction?', N'Intern', N'Atomicity ensures that all operations within a transaction are completed successfully as a single unit. If any part of the transaction fails, the entire transaction is aborted and the database remains unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0746090-a8f9-4438-be29-cc4c8ef70b74', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s type-safe request handling leverage Rust''s procedural macros to enforce architectural constraints at compile time?', N'Senior', N'Rocket utilizes procedural macros to perform static analysis on route handlers, ensuring that request inputs, path parameters, and state dependencies are verified before the binary is even produced. This approach eliminates runtime reflection and type-casting errors, shifting the burden of validation to the compiler and reducing the risk of runtime panics in complex request-response lifecycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa5bce92-1022-4a8c-8618-cc4ddcba4fc0', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte 5''s ''Runes'' system change the framework''s fundamental approach to reactivity?', N'Senior', N'Runes shift Svelte from a compiler-dependent reactivity model to a more explicit signal-based system. This provides finer-grained control over reactivity, allowing for consistent behavior across components and better integration with external state management libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3149e80-bdd1-45fc-9a6f-cc4de9e3f26a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'When would you prefer a custom middleware over using Gin''s built-in features?', N'Senior', N'Custom middleware is necessary when you need to integrate cross-cutting concerns like distributed tracing, complex custom authentication logic, or specialized rate limiting that requires stateful coordination. Built-in features are excellent for boilerplate, but custom logic is required for architectural requirements specific to your infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c2d13f7-a458-4c88-9c4a-cc4e3b17fb87', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a property in Kotlin?', N'Intern', N'A property is a member that acts like a field but includes built-in getter and setter methods. When you declare a variable in a class, Kotlin automatically generates these accessors for you.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f30cfafb-15c1-4e2e-88ba-cc4e458595a6', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What design patterns should be followed to avoid the ''N+1'' query problem in DynamoDB?', N'Senior', N'The N+1 problem is solved by using Query operations with filter expressions or by denormalizing data into a single table. Storing related entities together in a single item or using composite keys allows retrieving complete datasets in a single round-trip. This avoids the excessive latency and throughput costs of performing multiple individual GetItem calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6c1da39-7f23-4b8f-9138-cc4f1a5836e2', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @error directive?', N'Middle', N'The @error directive is used to stop the compilation process and print a custom message to the console. It is primarily used in mixins or functions to validate inputs, ensuring that developers providing incorrect arguments receive immediate feedback rather than silently generated broken CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e80326a2-d568-46d6-9adf-cc4f9af080fc', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are decorators in the context of Lit?', N'Fresher', N'Decorators in Lit are special annotations used to configure properties and behaviors of a class or its members. They simplify the syntax for defining reactive properties, querying DOM elements, and registering custom elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93cad5b5-d064-43ed-86de-cc4fa77bc885', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When handling error states, what is the trade-off between showing generic error messages and detailed technical messages?', N'Junior', N'Generic messages provide a better user experience and prevent information disclosure that could be used for attacks. Detailed messages are helpful for internal troubleshooting, so I would log the technical details server-side while showing the user a friendly, generic message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce16b764-0c72-4fbb-8376-cc4ff5513d69', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do you define a route in AdonisJS?', N'Fresher', N'Routes are defined in a dedicated file using a router object. You specify the HTTP method, the URL pattern, and the controller method that should handle the request when that URL is visited.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936b42bc-4a6d-436c-82f2-cc5424bff087', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it often necessary to move heavy tasks out of the request-response cycle in Rails?', N'Senior', N'Rails processes are typically blocked while executing long-running tasks, which reduces the number of concurrent requests a single worker can handle. Moving these to background jobs improves user-perceived performance and ensures system stability by decoupling heavy processing from the web server thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9255b06c-2061-4277-bbad-cc57fc602830', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can Alpine.js be used to fetch data from an API?', N'Intern', N'Yes, Alpine.js can be used to fetch data by using the browser''s native fetch API within an x-init directive or a component method. The fetched data can then be stored in the component''s state and rendered in the HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
