INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c902751d-5c8e-4368-87fe-cc6d79d6af72', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the trade-offs of using ''Generic'' types in Dart compared to type erasure in other languages?', N'Senior', N'Dart uses reified generics, meaning type information is available at runtime, allowing for checks like ''is T''. While this provides greater safety and enables features like type-safe collections, it introduces a small runtime overhead for storing type descriptors and can increase the complexity of the object graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9689a47b-f759-4a8f-9302-cc6f38057e10', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the performance implications of using Svelte''s stores?', N'Middle', N'Stores are highly efficient because they use a simple pub-sub pattern with minimal overhead. Because they avoid the overhead of a virtual DOM diffing process, they provide excellent performance for managing large amounts of reactive data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'729a4306-fa65-4a6f-96b9-cc6f77f41dca', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''string'' immutability affect performance?', N'Middle', N'Because strings are immutable, any operation that modifies a string actually creates a new string object in memory. Repeatedly concatenating strings in a loop causes excessive memory allocations and garbage collection pressure, which is why StringBuilder is preferred for complex string manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc743383-8307-4f54-818f-cc765040cfd8', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of the ''Workflow'' component?', N'Middle', N'The Workflow component provides a state machine to manage the lifecycle of an object, such as an order or a document. It ensures that an object only transitions between states in a predefined order, centralizing business process logic and preventing invalid state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eb1232d-02ee-4c2a-9c99-cc7963f91f6d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s interface-based design improve application scalability?', N'Middle', N'By programming to interfaces rather than concrete classes, developers can swap out implementation details without affecting the rest of the application. This loose coupling makes it significantly easier to extend functionality or replace external services as the application grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc5893d2-4149-4f15-a4fb-cc79cc28c31a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why might you choose a custom Webpack loader over a standard plugin?', N'Senior', N'Loaders are designed to preprocess the source code of a file before it is added to the dependency graph, such as transpiling or linting. Plugins, conversely, operate on the entire bundle or specific hooks of the compilation lifecycle, making them better for overarching build orchestration tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2b9a31b-443b-4273-bf1c-cc7f8471f06f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does Isolation benefit database transactions?', N'Junior', N'Isolation ensures that concurrent transactions do not interfere with each other. It makes it appear as if each transaction is running in total isolation, even when multiple transactions are executing simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aba600a2-6148-4562-b29b-cc807460e4c6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does the ''context'' object in an Actix actor influence its state management and message processing?', N'Senior', N'The context object provides the actor with methods to interact with the runtime, such as stopping itself, spawning futures, or delayed execution. It acts as the bridge between the actor''s internal state and the external environment, encapsulating the actor''s lifecycle and capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cf36812-0dbc-4836-98c0-cc80ab4e9fd9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why is it generally recommended to avoid high-cardinality fields when using aggregations in Elasticsearch?', N'Middle', N'Aggregations on high-cardinality fields require loading a large amount of unique values into the field data cache in memory. This can lead to significant memory pressure, potential OutOfMemory errors, and degraded query performance due to the overhead of managing the unique buckets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'785a89bc-0b12-492e-bd0a-cc818e39de33', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How can you implement rate limiting in an AdonisJS application?', N'Middle', N'Rate limiting is best implemented using a middleware that tracks request counts per IP or user in a fast, in-memory store like Redis. AdonisJS allows you to easily attach this middleware to specific route groups to protect your API from abuse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58cda78a-c90e-42d3-8c90-cc83ab54cf7e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift use Optionals instead of null pointers?', N'Middle', N'Optionals enforce type safety by explicitly requiring the developer to handle the absence of a value. This prevents common runtime crashes associated with null pointer dereferencing found in other languages. It forces the logic to account for missing data at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25c64cae-11a2-4650-a28d-cc8466721d94', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of the ''app'' directory?', N'Intern', N'The app directory is the heart of an AdonisJS application where the main business logic resides. It typically contains controllers, models, and middleware, keeping the application structure consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd29a6cdc-1925-4fb8-9cc6-cc848bd44798', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''type'' assertion and ''type'' casting?', N'Middle', N'TypeScript performs type assertion, which is a way to inform the compiler about the type of a value, but it does not perform any runtime type conversion. Unlike languages like C++, type assertions in TypeScript are purely a compile-time construct that does not affect the generated JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77935916-1a81-4b12-b35e-cc8554175ce3', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between a self-closing tag and a container tag?', N'Intern', N'A container tag requires both an opening and a closing tag because it wraps around content. A self-closing or void element, such as an image or a line break, does not contain any content and therefore does not require a closing tag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ba0898c-d625-4d3c-b7ba-cc85c69fdcee', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the @Injectable decorator?', N'Intern', N'The @Injectable decorator tells NestJS that a class is a provider that can be managed by the Nest IoC container. It marks the class as a dependency that can be injected into other classes, such as controllers or other services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e74f2b88-36d2-45d3-8d85-cc93402b6298', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you ensure message integrity while in transit?', N'Middle', N'Message integrity is typically ensured using checksums or digital signatures generated by the producer and validated by the consumer. Transport-level security, such as TLS, is also used to prevent tampering and eavesdropping during transit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33ee7f22-d88a-446b-820e-cc93d85adc21', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a rate-limiting strategy for a public API to ensure fair usage while preventing service outages?', N'Middle', N'I would implement a token bucket algorithm at the API gateway level to allow for bursts while maintaining a steady average rate. By using a distributed store like Redis to track request counts per user identifier, I can ensure consistency across multiple service instances and return standard HTTP 429 status codes when thresholds are exceeded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'186912bc-c94d-475f-bd8d-cc9572014928', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Global Secondary Index (GSI) and what are its trade-offs?', N'Middle', N'A GSI allows you to query data using a different partition and sort key than the base table. The trade-offs include asynchronous replication delay, additional storage costs, and the fact that GSI writes count against the provisioned throughput of the index.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14b2123a-fa55-4814-b549-cc9668be9d3d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra achieve high availability?', N'Intern', N'Cassandra achieves high availability through its peer-to-peer architecture and data replication. Because there is no master node, any node can handle read and write requests, and data is copied across multiple nodes to ensure it remains available if one fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1489652c-815e-4f47-b90b-cc973e4fce8a', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is an ''object'' in Kotlin?', N'Junior', N'An ''object'' in Kotlin is used to define a singleton, an instance of a class that is created only once. When you declare an object, the runtime ensures that there is exactly one instance of it throughout the application. It is useful for shared managers, utility collections, or global states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa6780df-f291-4aaa-aa60-cc973e78e4e1', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the relationship between Preact and React?', N'Intern', N'Preact is a separate library that is API-compatible with React. This means that many concepts and patterns used in React are directly applicable to Preact, allowing developers to switch between them with minimal friction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9652db5-79be-41dc-88bc-cc97f7dc720a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Can Litestar handle synchronous functions?', N'Fresher', N'Yes, Litestar can handle both synchronous and asynchronous route handlers. If a handler is defined as a standard function, the framework will run it in a separate thread to avoid blocking the main event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60a3eeeb-ec8f-441c-9792-cc9aa02aece6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle concurrency if it is a single-threaded framework?', N'Middle', N'Flask itself is a WSGI application and is synchronous by design, meaning it handles one request at a time per worker process. To handle concurrency, you must deploy it behind a production-grade WSGI server like Gunicorn or uWSGI, which can spawn multiple worker processes or threads to handle concurrent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd71508e1-e084-4a18-8448-cc9bd6b4eace', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do goroutines differ from OS threads in terms of scheduling and resource consumption?', N'Senior', N'Goroutines are M:N scheduled by the Go runtime, mapping many goroutines onto a small number of OS threads. They consume significantly less memory due to their initial 2KB stack size, which dynamically expands and shrinks, unlike the fixed-size megabyte-scale stack of OS threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1b9b8e8-8e74-469f-9e30-cc9c3f133535', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the effort required to refactor a legacy module without breaking existing functionality?', N'Middle', N'I would first ensure there is adequate test coverage for the existing module; if not, the initial effort must include building those tests. I then estimate the refactoring in small, verifiable increments, allowing for constant validation that the system behavior remains consistent throughout the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdd05ea1-285b-4178-80c7-cc9d4678d2af', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Discuss the trade-offs of using `SyncArbiter` versus manually managing thread pools for blocking tasks.', N'Senior', N'SyncArbiter provides a convenient, structured way to scale blocking actors by automatically managing a thread pool and routing messages. Manually managing thread pools offers more granular control over resource allocation and priority, but increases architectural complexity and the risk of deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64b21e45-f946-44e5-99bb-cc9f4a8cda3c', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does a distributed lock service like ZooKeeper handle network partitions?', N'Senior', N'ZooKeeper uses the ZAB protocol to maintain a quorum of nodes. If a partition occurs, the partition containing the majority of nodes remains operational, while the minority partition becomes read-only or unavailable, preventing the system from issuing conflicting locks to multiple clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'643b05bc-3147-4544-a56a-cca0375591f6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are Redis ''Bitmaps''?', N'Junior', N'Bitmaps are not a separate data type but a set of bit-oriented operations on string values. They are highly memory-efficient and are commonly used for tasks like tracking user activity, such as whether a user logged in on a specific day.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a56f90ae-59a3-4cdb-883f-cca0fcf19d79', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the advantages of using Event Sourcing instead of traditional state-based storage?', N'Senior', N'Event Sourcing stores the sequence of state-changing events rather than the current state, providing a perfect audit log and the ability to reconstruct state at any point in time. It also facilitates easier debugging and integration with event-driven architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
