INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3aaefc29-c48f-4fd0-9204-ccacffe313b6', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the difference between ''covariant'' and ''contravariant'' type parameters.', N'Middle', N'Covariance allows a generic type to be a subtype of another if its parameter is a subtype, making it suitable for producers. Contravariance reverses this relationship, making it suitable for consumers that accept a broader range of types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52d4d535-6cff-4868-8604-ccae1796296d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the value of explaining the problem to someone else, even if they aren''t helping?', N'Intern', N'Explaining the problem forces you to articulate the logic and assumptions of your current understanding. This process, often called rubber ducking, frequently leads to realizing where your logic is flawed or where you missed a simple detail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
