INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70af817e-e41d-47b6-a263-ccb032967ba0', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why is PostgreSQL considered ''Object-Relational''?', N'Intern', N'It is called object-relational because it combines traditional relational database features with object-oriented concepts. It allows users to define custom data types, inheritance, and functions, providing more flexibility than standard relational models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f7219e4-43c0-427f-ae4a-ccb1e17dec66', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the purpose of middleware in Redux, and how does its composition pattern work?', N'Senior', N'Middleware provides a third-party extension point between dispatching an action and the moment it reaches the reducer. It uses a higher-order function composition pattern, where each middleware wraps the next, allowing developers to intercept, transform, or delay actions for side effects like logging, crash reporting, or asynchronous API calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ade7daf3-a9c2-4f63-bec5-ccb26dceff33', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''position: sticky'' property behave, and what are its requirements?', N'Middle', N'Position sticky acts like a hybrid between relative and fixed positioning, keeping an element within its parent container as the user scrolls. It requires a defined scrollable container and at least one directional property, such as top, bottom, left, or right, to trigger the ''stickiness'' behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eeeb0d9-4509-4374-8f37-ccb3b1fc60e0', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is the Svelte bundle size typically smaller than React''s?', N'Middle', N'Svelte does not ship a virtual DOM library or a reconciliation engine to the browser. Because the framework logic is compiled away during the build process, the final bundle contains only the application-specific code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d123b66-dbf4-422c-aac7-ccb42a6392ce', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between synchronous and asynchronous programming in backend development?', N'Junior', N'Synchronous programming blocks the execution thread until an operation completes, which can lead to performance bottlenecks. Asynchronous programming allows the thread to be released while waiting for an operation to finish, significantly improving the scalability of web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
