INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f392b6f-8b5b-4cc1-b6cd-ccc37a385076', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB store data compared to a relational database?', N'Fresher', N'Relational databases store data in tables with fixed rows and columns. MongoDB stores data in documents grouped into collections, which allows for dynamic schemas where each document can have a different structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a32230f7-8491-454b-afd8-ccc3be530532', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between an ''index prefix'' and a ''compound index''?', N'Middle', N'A compound index is an index on multiple fields, and MongoDB can use an index for queries that match the beginning of that index, known as the index prefix. This means that if you have an index on (A, B), it can also efficiently service queries that filter only by A, but not those that filter only by B.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
