INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'289e5263-8395-4f4b-abb5-ccd9aa6e515e', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the difference between select_related and prefetch_related in terms of database performance.', N'Middle', N'select_related performs a SQL JOIN to fetch related objects in a single query, which is ideal for single-valued relationships like ForeignKey or OneToOne. prefetch_related performs a separate lookup for each relationship and joins the results in Python, which is better for many-to-many or reverse foreign key relationships to avoid massive result sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c99c732-7c16-48ef-9634-ccdbd78019d1', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Are there any external dependencies required to use Chi?', N'Junior', N'Chi is designed to have zero external dependencies. It relies only on the Go standard library, which makes it easy to maintain and keeps the binary size small.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4c88093-4e44-4a95-afde-ccdf0e81af15', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s Global Interpreter Lock (GIL) affect multi-threaded performance?', N'Middle', N'The GIL ensures that only one thread executes Ruby code at any given time, preventing internal data corruption. While this simplifies thread safety for the interpreter, it means Ruby cannot achieve true parallel execution of CPU-bound tasks across multiple cores. Developers must use multi-processing or external C extensions to bypass this limitation for compute-heavy operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90e69f7c-a281-4533-93ec-ccdfba5d2474', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are ''doc values'' and why are they important?', N'Middle', N'Doc values are a disk-based, column-oriented data structure that is built at index time to support sorting, aggregations, and scripting. They allow Elasticsearch to perform these memory-intensive tasks without loading all field values into the JVM heap, preventing out-of-memory errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33c73c78-45c1-4105-a65e-cce1f671271d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What does it mean for a system to be ''stateless''?', N'Fresher', N'A stateless system does not store any information about previous interactions between the client and the server. Each request must contain all the information necessary for the server to understand and process it, which makes the system easier to scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2e0f53f-a219-4a58-93f3-cce2eb3b0ae6', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is it important to use aliases in SQL?', N'Fresher', N'Aliases are temporary names given to tables or columns in a query. They make the code more readable and are essential when performing joins or when column names are long and complex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9d20df2-ef07-4739-8fc2-cce5a1333668', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the Scala Type System?', N'Intern', N'The Scala type system is a highly expressive and static system that includes features like generics, variance annotations, and type bounds. It ensures type safety at compile time, reducing runtime errors and allowing for complex abstraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'629b1590-8399-44b1-a6e4-cce6d6c464b5', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is an escaping closure?', N'Junior', N'An escaping closure is a closure that is called after the function it was passed to has already returned. This is common in asynchronous programming, such as network requests, where the closure is stored to be executed later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61759f92-9a62-46f5-9d35-cce83c3ea965', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What does ''at-least-once'' delivery guarantee imply for consumer implementation?', N'Middle', N'It means a message is guaranteed to reach the consumer, but network issues may cause it to be delivered multiple times. Consequently, consumers must be designed to be idempotent so that duplicate processing does not result in incorrect state updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3362f14-69ad-4ec6-9076-cceaff703a80', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does Node.js handle memory management, and what are the common causes of memory leaks?', N'Middle', N'Node.js uses the V8 garbage collector to manage memory, which cleans up objects that are no longer reachable. Memory leaks usually occur due to global variables that are never cleared, closures retaining references to large objects, or persistent event listeners that are not removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34a1f7ce-3a9a-4827-8ef5-cceb47e13097', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the Commit Log?', N'Middle', N'The Commit Log acts as a crash-recovery mechanism that records all incoming write operations before they are applied to the Memtable. If a node crashes, it can replay the log to restore data that was not yet flushed to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc0c1b53-f1e0-4b58-af9f-ccf3fee19e9c', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle multi-part form data, and what are the security considerations?', N'Senior', N'Express does not include a body parser for multi-part forms, requiring external middleware like Multer. Security risks include Denial of Service via large file uploads or malicious file uploads that bypass mime-type checks, necessitating strict file size and type validation at the middleware layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'155f5c8f-7d46-44c7-b289-ccf419fcdc07', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket handle dependency injection for request-local state?', N'Middle', N'Rocket uses the Managed State feature, which allows developers to inject thread-safe data into handlers. By using the manage method on a Rocket instance, the framework stores the state, and handlers can access it via the State type, ensuring safe concurrent access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2eece010-32ca-471f-8f4f-ccf4f195d8b4', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket utilize Rust''s type system to enforce security in request handling?', N'Middle', N'Rocket uses type-safe request guards to ensure that handlers only execute if specific criteria, such as authentication headers or data models, are met. By leveraging Rust''s ownership and trait system, these guards validate input data at the type level before the handler logic even runs. This approach significantly reduces common vulnerabilities like injection attacks by ensuring developers explicitly define and validate the data structures they expect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
