INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ab89df5-98b4-4e06-9f1f-cd105c254464', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the CAP theorem in relation to distributed databases?', N'Intern', N'The CAP theorem states that a distributed data store can only provide two out of three guarantees simultaneously: Consistency, Availability, and Partition tolerance. In NoSQL systems, architects often choose which two to prioritize based on the specific needs of the application, as network partitions are inevitable in distributed systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67b98ca0-434e-41d4-b539-cd11e6543cec', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of ''Object.freeze'' and how does it affect the engine''s ability to optimize an object?', N'Senior', N'Object.freeze makes an object immutable, preventing structural changes. Because the object''s shape becomes constant, the engine can safely make stronger assumptions about property access, potentially leading to better optimization, though this is secondary to the functional safety it provides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d7c96e8-0838-4c11-9949-cd1346f090eb', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of an API Gateway in a distributed system?', N'Senior', N'An API Gateway acts as a single entry point for clients, handling cross-cutting concerns like authentication, rate limiting, request routing, and response aggregation. It decouples internal service topology from the client, allowing for internal refactoring without impacting external consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03f155ba-9c0f-4b3f-83cb-cd161f27ed05', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask-WTF and why are they used?', N'Fresher', N'Flask-WTF is an extension that integrates the WTForms library with Flask. It is used to simplify form handling, validation, and protection against Cross-Site Request Forgery (CSRF) attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8c48ca5-a79f-430f-9610-cd1703019fcc', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Does Quarkus support standard Java annotations?', N'Fresher', N'Yes, Quarkus supports standard Java annotations, including those from JAX-RS for REST, CDI for dependency injection, and JPA for database mapping. This makes it easy for developers familiar with Jakarta EE or Spring to transition to Quarkus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603eac96-4b98-4f02-8b4c-cd18f2e3e0a8', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Discuss the architectural trade-offs of using Laravel''s ''Broadcast'' system with WebSockets vs. traditional polling.', N'Senior', N'WebSockets provide real-time, low-latency updates but require maintaining stateful persistent connections and server-side socket management. Polling is simpler to implement and scales naturally with stateless architectures, but it introduces significant latency and unnecessary server load for applications requiring high-frequency updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae15e393-e8da-4997-9cd5-cd19ca0aeeac', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a macro in C?', N'Intern', N'A macro is a fragment of code that has been given a name and is expanded by the preprocessor before compilation. It is commonly used to define constant values or simple functions that are replaced directly in the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6f6268e-03b8-4016-80d1-cd19d2a3a862', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the mechanics of Svelte''s reactivity system and how it handles state updates compared to standard proxies.', N'Senior', N'Svelte uses a static analysis approach during compilation to inject fine-grained dependency tracking code, allowing it to surgically update only the specific DOM nodes affected by a state change. Unlike frameworks that rely on deep proxy observation or dirty checking, Svelte''s system is deterministic and direct, reducing memory usage by avoiding the need for reactive wrappers around every data property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13e90fe4-fadc-49ef-a93d-cd1b4c1097a2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''isset'' function?', N'Fresher', N'The isset function checks whether a variable has been declared and is not null. It is commonly used to verify if form inputs or array keys exist before attempting to access them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e9192f3-8f0a-4979-9b6d-cd2073f9bcef', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the Django admin interface?', N'Intern', N'The admin interface is an out-of-the-box feature that provides a professional, ready-to-use website for managing application data. It allows administrators to add, edit, and delete records based on the models defined in the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'477ffe52-0470-4e4b-98f3-cd21b0688b4a', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between Reflow and Repaint, and how do they impact performance?', N'Middle', N'Reflow occurs when changes affect the geometry of elements, such as width, height, or position, forcing the browser to recalculate the layout. Repaint happens when only visual styles change, like color or background, which is less computationally expensive than reflow. Minimizing both is critical for maintaining high frame rates and smooth animations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5a40e08-088f-4572-86fc-cd21b146517b', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the levels of data abstraction?', N'Intern', N'1. Physical level – how data is stored (files, pages, extents). 2. Logical level – tables, columns, relationships, constraints. 3. View level – filtered subsets exposed to users (VIEWs, row-level security). Example – view-level abstraction:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f48f04a-a3eb-452a-8b6c-cd23a79e4504', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of ''IConfiguration'' in ASP.NET Core?', N'Middle', N'IConfiguration provides a unified way to access settings from various sources like JSON files, environment variables, command-line arguments, and user secrets. It abstracts away the source of the configuration, allowing the application to behave consistently across different deployment environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
