INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'332541a7-616d-49e8-9f32-cd2593c278b8', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'When should you prefer pass-by-reference over pass-by-value?', N'Middle', N'Pass-by-reference is preferred for objects to avoid the overhead of copying, especially for large classes or containers. It is also required when you need the function to modify the original object passed to it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14a2a1da-6bcc-4d42-93dd-cd2760a29196', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of a Schema in PostgreSQL?', N'Fresher', N'A schema is a namespace that contains database objects like tables, indexes, and views. It helps in organizing database objects into logical groups and prevents naming conflicts between different users or applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cf9a95d-6fab-4705-9876-cd2a82506faa', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the architectural advantages of using Symfony''s ''Workflow'' component for complex state management.', N'Senior', N'The Workflow component externalizes state transition logic from the domain entities, providing a centralized definition of allowed states and transitions. This prevents ''if-else'' sprawl in models, simplifies auditing, and allows for the easy integration of event-driven side effects when state changes occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2787d794-5b17-4433-ae90-cd2a94a327a5', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is Stream?', N'Intern', N'An interface java.util.Stream is a sequence of elements on which various operations can be performed. Operations on streams can be either intermediate (intermediate) or final (terminal) . Final operations return a result of a certain type, and intermediate operations return the same stream. Thus, you can build chains of several operations on the same stream. A stream can have any number of calls to intermediate operations and the last call to the final operation. At the same time, all intermediate operations are performed lazily and until the final operation is called, no actions actually happen (similar to creating an object Threador Runnable, without a call start()). Streams are created based on sources of some, for example, classes from java.util.Collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbb6c575-8c57-4c76-918a-cd2b6d32a69d', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''externals'' in Webpack, and when should it be used?', N'Senior', N'Externals allow you to prevent certain modules from being bundled, instead referencing them from the global scope or other sources. It is primarily used to reduce bundle size by consuming libraries provided via CDNs or to integrate with existing legacy globals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'278c6242-9c96-4b09-9b97-cd2c1ab18275', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between pure and impure pipe?', N'Fresher', N'A pure pipe is only called when Angular detects a change in the value or the parameters passed to a pipe. For example, any changes to a primitive input value (String, Number, Boolean, Symbol) or a changed object reference (Date, Array, Function, Object). An impure pipe is called for every change detection cycle no matter whether the value or parameters changes. i.e, An impure pipe is called often, as often as every keystroke or mouse-move.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c01482ff-3bba-4ec0-9986-cd2cf3c039f5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the role of conditional types in complex type definitions.', N'Middle', N'Conditional types allow the selection of a type based on a logical condition, functioning like a ternary operator for types. They are essential for creating flexible utility types that adapt their return types based on the input type provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'801d93ff-668d-4cef-927b-cd3253d267e3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are private environment variables in SvelteKit?', N'Junior', N'Private environment variables are variables that are only accessible on the server side. They are defined using the $env/static/private module, ensuring that sensitive information is never exposed to the client''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d1a2cd3-245b-451c-bfcc-cd3350332555', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you factor in ''hidden'' costs like maintenance or testing when estimating a project?', N'Intern', N'I include these as separate line items or as a percentage multiplier applied to the core development effort. Recognizing that development is only a portion of the lifecycle helps ensure that the estimate covers the full cost of ownership, including future support and quality assurance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e60b653-45e8-497d-98db-cd33a2bffa5c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle asynchronous requests compared to traditional synchronous frameworks?', N'Junior', N'FastAPI is built on top of Starlette and utilizes Python''s async and await keywords to handle concurrent requests efficiently. Unlike synchronous frameworks that may block the entire process during I/O operations, FastAPI can process other incoming requests while waiting for a task to complete, significantly improving performance for I/O-bound applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6b53557-831b-433b-9507-cd35bef610aa', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do props work in SolidJS?', N'Fresher', N'Props in SolidJS are read-only objects passed to components. Because props are reactive, they must be accessed directly to maintain their reactivity tracking; destructuring them usually breaks the reactivity link.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2b02421-a585-416f-8eaa-cd3a62d8dd71', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of Rails Engines, and when should you use them?', N'Middle', N'Rails Engines are essentially miniature applications that can provide functionality to a main host application. They should be used for modularizing large applications into smaller, reusable components or for sharing common features like authentication across multiple projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a8993b9-dfd3-471f-8677-cd3c5564f91b', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What does it mean for a function to panic?', N'Intern', N'A panic is an unrecoverable error that stops the execution of the entire program. It is typically used when the program reaches an state from which it cannot safely continue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd7f6d2e-1c23-4b5b-b3be-cd3ce51d1b20', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a table and a view?', N'Fresher', N'A table is a physical object that stores actual data in the database. A view is a virtual table based on the result-set of an SQL statement, which does not store data itself but provides a saved query to represent data from one or more tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd135084c-7306-44be-87a1-cd3e962365ab', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the trade-offs of using Java''s default garbage collection algorithms?', N'Middle', N'Different garbage collection algorithms, such as G1 or ZGC, offer varying trade-offs between throughput and latency. Higher throughput algorithms may cause longer pause times, which are unacceptable for real-time applications. Conversely, low-latency collectors often require more CPU resources and memory overhead to maintain responsiveness. Choosing the right collector depends on the application''s specific performance requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18ec8d2d-5624-436d-a850-cd403afd17b3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s compilation strategy differ from the runtime reconciliation process used by React or Vue?', N'Senior', N'Svelte shifts the reconciliation work to a build-time step, transforming declarative components into highly optimized imperative code that directly manipulates the DOM. Unlike frameworks that use a Virtual DOM to compute differences at runtime, Svelte generates surgical updates, resulting in smaller bundle sizes and superior performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd66148aa-ba5b-4a8c-a62b-cd407f1213ca', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you approach securing a Laravel API against common vulnerabilities like mass assignment and CSRF?', N'Senior', N'Mass assignment is prevented by defining fillable or guarded attributes on models, which acts as a whitelist for input. CSRF is handled automatically for web routes through encrypted tokens, while for stateful APIs, you should utilize Sanctum or Passport to manage token-based authentication, ensuring that each request is properly verified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd17b24fc-ffb1-4305-9d2a-cd4b9ec5b0ba', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the architectural significance of the ''Method Cache'' in the Ruby VM.', N'Senior', N'The method cache stores the result of the method lookup path to avoid repetitive traversal of the ancestor chain, which is a computationally expensive operation. Any action that alters the class structure, such as adding a method or modifying a module, forces the VM to clear this cache, temporarily slowing down dispatch across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'816accfb-cfed-4c60-aa41-cd4c704c1cc1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain fetch() properties in JavaScript?', N'Fresher', N'A fetch() function is available in the global window object. The fetch() function takes one mandatory argument, the path to the resource you want to fetch. It returns a Promise, whether it is successful or not. If request is successful .then() function will receive Response object, if request fails then .catch() function will receive an error object Example: &#9885; Try this example on CodeSandbox Headers Object The Headers interface allows to create own headers object via the Headers() constructor. A headers object is a collection of name-value pairs. Example: &#9885; Try this example on CodeSandbox Request Object The Request Object represents a resource request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03a07edc-dd88-4a5c-a565-cd4c822af568', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the bitwise operators available in javascript', N'Intern', N'Below are the list of bitwise logical operators used in JavaScript 1. Bitwise AND ( & ) 2. Bitwise OR ( | ) 3. Bitwise XOR ( ^ ) 4. Bitwise NOT ( ~ ) 5. Left Shift ( > ) 7. Zero fill Right Shift ( >>> )', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'476cfa03-7b98-4f6f-8466-cd4ca774e878', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a project is falling behind schedule, what is your process for deciding what to cut?', N'Junior', N'I would identify non-essential features or secondary requirements that can be moved to a future release without breaking core functionality. I would then present these options to the product team to ensure the remaining scope still delivers the intended value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a48cc332-1d5f-4f34-acf0-cd4f31bd695b', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why would you choose to use a custom provider over standard class-based DI in NestJS?', N'Senior', N'Custom providers allow you to inject values, factory functions, or existing instances into the DI container, which is necessary when dealing with third-party libraries that don''t use class constructors. They provide the flexibility to bridge external resources with the NestJS DI system seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fbafd90-874a-4d59-8c76-cd530d53dfec', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is meant by high availability in NoSQL?', N'Intern', N'High availability means the database system remains operational and accessible to users even if some components, such as servers or network links, fail. NoSQL systems achieve this through replication and distributed architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b914f95-c472-4f25-9143-cd53c9e8cb55', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle shared state in a multi-threaded asynchronous environment?', N'Senior', N'Axum uses a thread-safe ''State'' extractor that wraps data in an Arc. By utilizing the State pattern, Axum ensures that shared resources like database pools or configuration objects are accessible across handler threads without violating Rust''s ownership or concurrency guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2243da4a-d73f-492e-9e85-cd548a0e5ddb', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the x-for directive used for?', N'Intern', N'The x-for directive is used to render a list of elements based on an array or object in the component''s state. It iterates through the data and creates a new DOM element for each item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3453192a-2a34-4cfb-a555-cd54fd4983c8', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the drawbacks of MVW pattern?', N'Intern', N'1. DOM manipulation is very expensive which causes applications to behave slow and inefficient. 2. Due to circular dependencies, a complicated model was created around models and views. 3. Lot of data changes happens for collaborative applications(like Google Docs). 4. No way to do undo (travel back in time) easily without adding so much extra code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9449d6f-4b47-45a7-bebd-cd55c228a728', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system is running slowly, how would you begin to investigate?', N'Intern', N'You would start by monitoring system resource usage such as CPU, memory, and network throughput to identify bottlenecks. Once you determine which resource is being exhausted, you can investigate the processes or configurations consuming it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf2210e8-973f-450d-8a0c-cd583729b4b1', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the implications of using jQuery''s .val() or .text() on performance compared to native property access.', N'Senior', N'These methods wrap native property access in functional logic that includes error handling and normalization. While convenient, this abstraction creates unnecessary function call overhead that compounds when performing bulk updates in high-frequency UI interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6838b17a-17e4-4219-a18a-cd60d4065373', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is FastAPI considered ''production-ready''?', N'Fresher', N'FastAPI is considered production-ready because it is based on the ASGI standard, supports asynchronous operations, has built-in data validation, and integrates seamlessly with common deployment tools. Its reliance on standard Python types also leads to fewer bugs and better IDE support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed366224-d505-4438-9e65-cd614b5eefbc', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens if a node in an Elasticsearch cluster goes down?', N'Junior', N'If a node goes down, the cluster detects the failure and promotes existing replica shards to primary status to maintain data availability. Once the node returns, it synchronizes with the current state of the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c93a3ed9-e68c-45a1-860a-cd61afab61a2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi support regex in route patterns?', N'Fresher', N'Yes, Chi supports basic regular expression patterns within the route definitions. This allows for more complex path matching, such as restricting a parameter to only contain numeric characters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eae46a38-696d-45b4-8f50-cd67be1a59fb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you balance the trade-off between feature richness and time-to-market?', N'Fresher', N'You should identify the minimum viable product features that deliver the most value to the user. Cutting non-essential features allows for a faster release, which provides early feedback, whereas waiting for every feature risks missing market opportunities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa1d328a-9138-4326-9a27-cd687eb348d4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the real world use cases of proxy?', N'Intern', N'Proxies are not used in regular day to day JavaScript work but they enabled many exciting programming patterns. Some of the real world use cases are listed below, 1. Vue3 used proxy concept to implement reactive state 2. SolidJS implemented reactive stores 3. Immerjs built upon proxy to track updates to immutable updates 4. ZenStack improved Prisma ORM for access control layer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fc3ae91-a794-41a8-b6f8-cd68ea3be14a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why is Micronaut particularly well-suited for AWS Lambda or other serverless functions?', N'Senior', N'Micronaut''s minimal startup time and low memory usage address the cold-start problem inherent in serverless environments. Because the framework performs the heavy lifting during compilation, the resulting artifact is lightweight and executes quickly without needing to initialize a massive runtime context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b89b7111-1ce2-4540-8485-cd6cf0269120', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is Cross-Site Scripting (XSS) and how can you prevent it?', N'Intern', N'Cross-Site Scripting (XSS) is a security vulnerability that allows attackers to inject malicious scripts into web pages viewed by other users. This can lead to data theft, session hijacking, and other malicious activities. To prevent XSS, you should validate and sanitize user inputs, use Content Security Policy (CSP), and escape data before rendering it in the browser. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer Explain the concept of Cross-Site Request Forgery (CSRF) and its mitigation techniques Cross-Site Request Forgery (CSRF) is an attack where a malicious website tricks a user''s browser into making an unwanted request to another site where the user is authenticated. This can lead to unauthorized actions being performed on behalf of the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'611bd63e-cc4d-4041-9712-cd6da757ebe4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you handle a situation where a library you are using is no longer maintained?', N'Fresher', N'I would evaluate the risks associated with using an unmaintained library, such as security vulnerabilities or compatibility issues. If the risks are significant, I would plan to replace it with a well-supported alternative or, if the project is small, potentially fork the library to maintain it myself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd8baa99-b7ef-4a3f-be89-cd732d3c6a1a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do composite indexes differ from single-column indexes?', N'Middle', N'A composite index covers multiple columns and is highly effective for queries that filter or sort by those specific columns in the order they appear in the index. A single-column index is more flexible for varied query patterns but is less efficient for queries that require filters on multiple fields simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ac7c54a-1380-4e74-8e12-cd73754afd66', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Describe the mechanism behind Laravel''s Queue Workers and how you ensure idempotency in background jobs.', N'Senior', N'Queue workers process jobs asynchronously by consuming messages from a configured backend store, decoupling the execution from the request-response cycle. To ensure idempotency, jobs should implement a check-before-act pattern using unique identifiers in the database or a distributed lock, ensuring that processing the same job multiple times does not result in inconsistent application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'862203c1-b8d4-4f26-9f2c-cd73fdc8fb46', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you restrict provider scope to a module?', N'Fresher', N'It is possible to restrict service provider scope to a specific module instead making available to entire application. There are two possible ways to do it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'644b9368-618b-44ac-a7cd-cd77f6af4034', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why is ''API Gateway'' considered a bottleneck and how can it be mitigated?', N'Senior', N'An API gateway centralizes authentication, rate limiting, and routing, making it a potential single point of failure and a performance bottleneck. Mitigation involves deploying the gateway in a distributed, load-balanced cluster and offloading heavy processing tasks to downstream services or edge workers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8553645-e09b-4fb3-a302-cd7a2e820fcb', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP handle variable scope within functions?', N'Junior', N'Variables defined outside a function have global scope and are not automatically accessible inside a function. To use a global variable inside a function, you must explicitly declare it using the global keyword.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f7ec4ed-e7f7-46f2-a79b-cd7a9a20821d', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging, why is it useful to review the most recent changes made to a system?', N'Fresher', N'Bugs are most frequently introduced by the most recent modifications. Reviewing recent changes helps you identify the specific update that might have introduced the error, significantly narrowing your search area.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf70aa39-4145-4c7a-b6ae-cd7b7fb1b28c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does multi-version concurrency control (MVCC) function in InnoDB?', N'Senior', N'MVCC maintains multiple versions of rows using undo logs, allowing transactions to read consistent snapshots of data without locking. This enables high concurrency by letting readers access older versions of a record while writers modify the current version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17272b3e-206a-486b-9edc-cd80430672f3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the role of ''TypedArrays'' and ''ArrayBuffers'' in handling binary data efficiently.', N'Senior', N'TypedArrays provide a view into a fixed-length raw binary data buffer, allowing for efficient, low-level manipulation of data types. They are essential for performance-critical applications like WebGL, audio processing, or file manipulation, where standard JavaScript arrays would be too memory-intensive and slow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed1ed788-68de-4d06-ae09-cd810bdf5fba', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is ''Anyhow'' or a similar error handling crate often used in Axum?', N'Middle', N'These crates simplify error propagation by providing a convenient way to wrap diverse error types into a single return type. This reduces the boilerplate associated with manual error mapping while maintaining descriptive error messages for API consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b9b223-e154-49a4-8c69-cd82fea309e1', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket use Rust''s type system to handle incoming request data?', N'Fresher', N'Rocket uses Rust''s strong type system and procedural macros to perform automatic data validation and request parsing. By defining the expected types in function signatures, Rocket ensures that if a request does not match the required format, it is automatically rejected before the application logic even runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c455b4f9-d5fa-425f-b8d0-cd8595e0a76c', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'When would you prefer using ''web::Payload'' over standard request extraction?', N'Senior', N'You use web::Payload when dealing with streaming request bodies or large payloads that cannot be buffered into memory. It allows for manual, chunked consumption of the incoming data stream, which is critical for memory-constrained environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f8cce12-6373-4847-9d68-cd85dad0ba05', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does the Actix ''Arbiter'' facilitate concurrency?', N'Middle', N'An Arbiter acts as an event loop thread that runs an asynchronous runtime. It manages the execution of actors and futures within its specific context, allowing for isolated execution environments that prevent blocking the main application thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24978ea2-830d-4337-8325-cd877426bd69', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does setTimeout(fn, 0) actually behave, and what are its timer accuracy limitations?', N'Fresher', N'setTimeout(fn, 0) does not execute fn immediately or even after exactly 0 milliseconds. It schedules fn as a macrotask — it will not run until: 1. The current call stack is empty. 2. The entire microtask queue is drained. 3. The event loop picks the next macrotask. Additionally, browsers enforce a minimum timer delay of 4ms after 5 nested setTimeout calls (the "clamping" rule, per the HTML spec). In background tabs, browsers further throttle timers to 1000ms (1 second) to save CPU. Node.js has a minimum delay of 1ms but also subject to the event loop''s libuv timer phase overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'face97dd-b187-4f74-8b09-cd87badb182d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between DELETE and TRUNCATE in MySQL?', N'Junior', N'DELETE is a DML operation that removes rows one by one and can be used with a WHERE clause to filter specific records. TRUNCATE is a DDL operation that removes all rows from a table by dropping and recreating it, which is generally much faster but cannot be filtered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1543362-171b-4c76-99c8-cd88316a0215', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle errors compared to exceptions in other languages?', N'Intern', N'Go does not use a try-catch exception model. Instead, it treats errors as values that are returned explicitly from functions, requiring the caller to check and handle them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7a4ee8b-bd91-4b7b-9924-cd8a11f30042', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the response object in Express?', N'Intern', N'The response object represents the HTTP response that an Express app sends when it receives an HTTP request. It contains methods to send data to the client, such as sending JSON, setting HTTP status codes, or rendering templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd14dacc-e719-4f5d-81bf-cd8a563fb861', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is Accessibility (a11y) in a web application?', N'Intern', N'Accessibility refers to how software or hardware combinations are designed to make a system accessible to persons with disabilities, such as: * Visual impairment * Hearing loss * Limited dexterity For example, a website developed with accessibility in mind might have text-to-speech capabilities or output for special braille hardware geared toward individuals with visual impairments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcd6d406-9bbb-44c8-89a1-cd8b21f55c9d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the strategy for managing multi-tenancy in an AdonisJS application.', N'Senior', N'Multi-tenancy is typically managed by implementing a custom middleware that resolves the tenant context based on headers or subdomains. This context is then injected into the database connection configuration or used to filter queries, ensuring strict data isolation between tenants while sharing the same application infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'749b24ea-5705-461c-956c-cd906a5897c5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Discuss the memory overhead of Kotlin delegated properties compared to manual implementation.', N'Senior', N'Delegated properties introduce an additional object reference for the delegate instance and require an extra method call to access the underlying value. While the overhead is negligible for small systems, in high-throughput or extremely memory-sensitive scenarios, this indirection can increase object allocation pressure and impact cache locality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ee72a3e-b5bb-48a7-82f5-cd95b8c91d18', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why are joins not supported in Cassandra?', N'Junior', N'Cassandra is a distributed system that stores data across many nodes. Performing joins across nodes would be extremely slow and complex, so it encourages denormalization instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61675638-28b8-4f1f-880d-cd978c072bd0', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the architectural benefit of Rocket''s ''Outcome'' type for request guards?', N'Senior', N'The Outcome type allows guards to return success, failure, or a ''forward'' signal. This enables complex routing logic where a guard can decide to pass control to the next matching route if conditions aren''t met, rather than simply failing the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b919d9e5-c52c-4aa2-9873-cd98970e19d6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are ''server routes'' in Nuxt and why are they useful?', N'Middle', N'Server routes located in the ''server/api'' directory allow you to create backend endpoints directly within your Nuxt project. They are useful for proxying requests to external APIs, handling authentication, or performing server-side tasks without needing a separate backend infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98d0657c-aef3-4eeb-95f8-cd9b1c2cdf3d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser''s critical rendering path impact CSS performance, and how can you optimize it?', N'Middle', N'The browser blocks initial page rendering until all CSS is parsed and the CSSOM is constructed, making external stylesheets render-blocking resources. You can optimize this by inlining critical CSS directly into the HTML document, deferring non-critical stylesheets, and minimizing the size of your CSS files to reduce the time to first paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faedf82f-8e33-4819-8ee1-cd9bfec431ba', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What does ''fine-grained reactivity'' mean in the context of SolidJS?', N'Junior', N'It means that the framework knows exactly which DOM nodes depend on which pieces of state. This allows it to update only the specific text content or attributes that changed without re-evaluating the entire component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
