INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'568fe61f-e321-4885-9b4e-cd9e87257257', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the trade-off between using ''eval'' strings versus blocks for dynamic code execution?', N'Senior', N'Using ''eval'' with strings is dangerous because it is susceptible to injection vulnerabilities and difficult to debug, as the source code doesn''t exist in a file. Blocks are generally safer and more performant because they can be analyzed by the VM and benefit from lexical scoping, providing a more robust way to execute dynamic logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ed5da34-dce4-41e6-917b-cd9ff3b04b91', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle error handling?', N'Fresher', N'Hono provides a dedicated error-handling middleware that catches exceptions thrown during the execution of a route. Developers can define a global error handler to return a consistent JSON error response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02caaf02-54fc-424b-b2d0-cda310e31efc', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is it important to override ''GetHashCode'' when overriding ''Equals''?', N'Middle', N'In C#, if two objects are considered equal according to the Equals method, they must also return the same hash code. Failure to maintain this contract breaks the behavior of hash-based collections like Dictionary or HashSet, as they rely on hash codes to locate items quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
