INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dc4a37b-1daa-4d8d-ab22-cda811188d39', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What architectural trade-offs exist when using Fastify for WebSocket integration?', N'Senior', N'Fastify is optimized for HTTP request/response cycles. While it supports WebSockets via plugins, the integration involves upgrading the connection, which bypasses the standard lifecycle hooks and requires manual management of the persistent connection state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9211e176-892b-4c41-b7ee-cdaa27679fc1', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'In the context of SvelteKit''s routing, what are the implications of using server-only load functions versus universal load functions?', N'Senior', N'Server-only load functions execute exclusively on the server, ensuring sensitive logic and private API keys remain hidden from the client. Universal load functions run on both the server and client, offering faster navigation for subsequent page transitions but requiring strict care to avoid exposing backend secrets in the browser bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'096052c4-d056-4dc3-a315-cdaa7e0124df', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach the challenge of ''observability gaps'' when troubleshooting legacy systems?', N'Senior', N'I would focus on retrofitting the system with lightweight, out-of-process monitoring agents that capture system-level metrics and network traffic metadata without requiring deep code changes. Simultaneously, I would implement centralized log aggregation to provide a unified view of the system state, even if the individual service logs are fragmented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
