INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a002f073-ab34-4a2c-9e20-cdb3dcd3197f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle error management?', N'Intern', N'Express uses special middleware functions that accept four arguments instead of three, with the first argument being the error object. When an error occurs, you pass it to the next function, and Express skips all remaining non-error handling middleware to jump directly to the first defined error-handling middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
