INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'803530b0-9b0c-43f0-ae6b-cdd833cacc8b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the ''initialize'' method in Ruby?', N'Middle', N'The ''initialize'' method is a private hook that is automatically called when a new instance of a class is created via the ''new'' method. Its primary purpose is to set the initial state of the object by assigning values to instance variables. It does not return anything; the return value of ''new'' is always the newly instantiated object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7336a59-1462-4dde-a259-cdd8b58ad41c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the impact of synchronous versus asynchronous script loading on the browser''s critical rendering path.', N'Senior', N'Synchronous scripts block the HTML parser, causing the browser to stop rendering until the script is downloaded and executed. Asynchronous or deferred scripts allow the parser to continue, improving time-to-first-paint by decoupling resource fetching from the DOM construction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0d2a3db-53bb-4c26-b449-cdd913b18cca', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What are ''unknown unknowns'' and how do they impact your estimation strategy?', N'Fresher', N'Unknown unknowns are risks that are impossible to predict before starting a task. I account for them by keeping my estimates flexible and maintaining regular communication with stakeholders so that if a major roadblock appears, it can be addressed early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f4c5bc9-1f81-4927-beb8-cddbd4d3439b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify handle backpressure in streams?', N'Senior', N'Fastify integrates natively with Node.js streams, allowing the framework to respect backpressure signals from the underlying socket. This prevents the server from buffering too much data in memory when the client is slow to read the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42415724-0de3-4cfa-a580-cddcc9845bc8', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the Sass @use rule improve upon the older @import directive?', N'Senior', N'The @import directive globally exposes variables, mixins, and functions, which can cause naming collisions and make dependency tracking difficult. The @use rule enforces namespacing, imports modules only once, and treats them as private by default, leading to better encapsulation and more maintainable architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f34e8565-5888-48fe-b77a-cde03a8ebd38', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to handle a massive spike in traffic during a flash sale without over-provisioning infrastructure?', N'Senior', N'I would implement a tiered architecture utilizing a global content delivery network for static assets and an asynchronous message queue to buffer incoming requests. By decoupling the front-end submission from the backend processing, the system can gracefully handle bursts using auto-scaling groups while preventing database saturation through rate limiting and load shedding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c8ac705-dc41-4e7d-81ee-cde0699ba682', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are the trade-offs of using Laravel''s ''Active Record'' implementation?', N'Middle', N'The Active Record pattern in Eloquent is convenient and highly productive because models contain both data and behavior. However, it can lead to fat models and tight coupling between the database schema and application logic, which may become harder to manage in very large or complex domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'305e659b-da2c-45b0-8ae8-cde097c4e5df', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the trade-offs of using C++ integration via Rcpp?', N'Middle', N'Rcpp provides a seamless way to write high-performance C++ code that can be called directly from R, significantly speeding up bottlenecks. The trade-off is increased complexity in the build process, the need for C++ knowledge, and potential memory management risks that bypass R''s safety checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07463176-6e6b-40d3-ab28-cde242c71ddf', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle JSON serialization?', N'Junior', N'Quarkus primarily uses JSON-B or Jackson to handle the conversion between Java objects and JSON payloads. These are configured automatically by the RESTEasy extensions, requiring minimal manual setup for standard REST APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e88f515-ae2e-4529-b1af-cde3cccb82d9', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the difference between synchronous and asynchronous communication in a system?', N'Intern', N'Synchronous communication requires the sender to wait for a response from the receiver before continuing, which can cause bottlenecks. Asynchronous communication allows the sender to proceed immediately, improving system responsiveness and decoupling the components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f096d04-483f-468c-9a5d-cde6f6e7ebe5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does monitoring help in troubleshooting?', N'Fresher', N'Monitoring provides real-time visibility into system health, such as memory usage, CPU load, and error rates. It allows you to catch issues as they happen and provides historical data to correlate when a failure started relative to system changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7855981c-d973-42ae-bbe7-cdeb6d63e9af', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Your system requires a global rate limiter to prevent API abuse. How would you design this?', N'Middle', N'I would use a centralized distributed cache like Redis to store request counters per client identifier. This ensures that the rate limit state is consistent across all instances of the service, though it adds a network dependency that must be mitigated with local caching or fail-open strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60444c7-95dc-4f5d-a55b-cdeca123e373', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle component styles?', N'Junior', N'Styles are defined using the css tagged template literal. Lit injects these styles into the component''s shadow root, which ensures that the styles are encapsulated and only apply to that specific component instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96319fb6-9c4b-4cbc-a69e-cdf0dc76e5bc', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Can you use middleware for just one route instead of the whole application?', N'Junior', N'Yes, middleware can be applied to specific routes or groups of routes using the ''layer'' method on a Router. This allows you to apply different security or performance policies to different sections of your API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53ad518e-c3c7-4c1e-9411-cdf12d3d3b50', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the role of an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway acts as a single entry point for all client requests, routing them to the appropriate microservices. It handles cross-cutting concerns like authentication, rate limiting, logging, and protocol translation, shielding clients from internal system changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79df2b03-c88b-4a4a-9c76-cdf17a513aa8', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the role of the ''load-path'' configuration in Sass compilation?', N'Senior', N'The load-path allows you to define custom directories for Sass to search when resolving imports. This is essential for managing dependencies from third-party packages or internal shared libraries, simplifying import statements and centralizing style assets across different parts of a project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
