INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30c85e02-3ee2-4adf-855c-cdf4c5dcf5ca', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why is it important to keep the main event loop free of blocking operations?', N'Middle', N'Since Dart''s main thread is responsible for UI rendering, blocking it with heavy synchronous computations causes the application to stutter or become unresponsive. Keeping the loop free ensures that input events and UI updates can be processed immediately, maintaining a smooth user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69d640cf-4f3a-4219-8366-cdf56e526679', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the benefit of using ''inline'' functions in Kotlin?', N'Middle', N'The ''inline'' keyword instructs the compiler to copy the function body directly into the call site, which reduces the overhead of function calls and object allocation for functional types. It is particularly useful when passing lambdas, as it avoids creating an extra object for the function interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ce90d0f-5e59-4060-9a8e-cdf64f86bda5', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What does the .stop() method do in jQuery?', N'Fresher', N'The .stop() method is used to immediately stop any currently running animations on the selected elements. This is helpful to prevent animation queues from building up if a user triggers an event multiple times in rapid succession.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
