INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5e42909-3d71-4951-9fc6-cdfb5a902668', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis Cluster implement data sharding, and how are keys mapped to nodes?', N'Senior', N'Redis Cluster uses a concept called hash slots, with a total of 16,384 available slots distributed across nodes. Keys are mapped to a specific slot using a CRC16 algorithm, ensuring consistent distribution and allowing the cluster to redistribute slots during scaling operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
