INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f75019b3-5d01-40eb-8dae-ce33c07558a2', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a foreign key constraint and why is it used?', N'Junior', N'A foreign key constraint enforces referential integrity by ensuring that a value in one table matches a valid primary key in another table. It prevents the creation of ''orphaned'' records that reference data that does not exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
