INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ebcf050-4e95-4357-8d7a-ce480cd25dcc', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'In a distributed system, how does the CAP theorem influence your choice of consensus algorithms for a global data store?', N'Senior', N'The CAP theorem forces a choice between consistency and availability during a network partition. For systems prioritizing strong consistency, consensus protocols like Paxos or Raft are required, which inherently trade off write latency and availability; conversely, AP systems favor eventual consistency using gossip protocols or CRDTs to ensure constant uptime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
