INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74e187ef-1e9a-4ab6-b437-ce48e236728a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the concept of MVCC in PostgreSQL and how it manages concurrency.', N'Middle', N'Multi-Version Concurrency Control allows multiple transactions to read and write to the database simultaneously without blocking each other. It works by creating multiple versions of a row whenever an update occurs, ensuring that each transaction sees a consistent snapshot of the data based on the transaction''s start time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
