INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b4766b5-b0dc-4323-ae50-ce50784ab2d3', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between client-side routing and server-side routing in SvelteKit?', N'Intern', N'Server-side routing occurs when the browser requests a new page from the server, which then generates the full HTML for that specific URL. Client-side routing happens after the initial page load, where SvelteKit intercepts navigation to update the page content dynamically without requiring a full browser refresh. This hybrid approach allows SvelteKit to provide the SEO benefits of server-side rendering while maintaining the fast, app-like performance of a single-page application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d773c3a-d4e9-4f7f-abdc-ce51735db883', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js''s reactivity system compare to Vue 3''s proxy-based approach in terms of architectural trade-offs?', N'Senior', N'Alpine.js uses a more lightweight observation mechanism based on object property descriptors, which is optimized for small-scale DOM manipulation rather than heavy data-driven applications. Vue 3 utilizes Proxies to intercept operations, offering better performance for deep reactivity at the cost of higher bundle size and complexity. Alpine prioritizes low overhead and immediate integration into existing server-side rendered HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
