INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6641eb03-3365-43bf-8e9f-ce671e7e5093', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Compare the performance trade-offs of using ''Gap Locking'' versus ''Next-Key Locking'' in InnoDB.', N'Senior', N'Gap locking prevents phantom reads by locking the space between index records, while Next-Key locking combines record-level and gap-level locking. While these ensure strict isolation, they significantly reduce concurrency by blocking insert operations in locked ranges, potentially leading to increased deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfaf5241-eb5a-4466-bd74-ce6780c0c5ce', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the primary challenge with asynchronous replication in read replicas?', N'Middle', N'Asynchronous replication introduces a lag between the primary database and the replicas, meaning users might read stale data. This requires the application to handle potential consistency issues if immediate data accuracy is required after a write.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00dd5d0b-5411-4212-8bb5-ce6f6a1427bc', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What does ''provisioned throughput'' mean in DynamoDB?', N'Junior', N'Provisioned throughput refers to the amount of read and write capacity units you reserve for your table. It defines the maximum number of requests your application can perform per second before DynamoDB begins to throttle requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e1695f8-bed5-4a03-b8b4-ce70e751e588', N'954a0331-deff-4399-b588-96f39fec001d', N'What are template expressions?', N'Intern', N'A template expression produces a value similar to any Javascript expression. Angular executes the expression and assigns it to a property of a binding target; the target might be an HTML element, a component, or a directive. In the property binding, a template expression appears in quotes to the right of the = symbol as in [property]="expression". In interpolation syntax, the template expression is surrounded by double curly braces. For example, in the below interpolation, the template expression is {{username}}, The below javascript expressions are prohibited in template expression 1. assignments (=, +=, -=, ...) 2. new 3. chaining expressions with ; or , 4. increment and decrement operators (++ and --) ----------------------------------', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e620caf6-39ef-4cd0-a2e0-ce73bf213a34', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the Quarkus ''Profile'' concept?', N'Intern', N'Profiles allow developers to define different sets of configurations for different environments, such as ''dev'', ''test'', or ''prod''. This enables the application to behave differently based on where it is being deployed without changing the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'278474c9-c419-4f72-9bf1-ce7447fe4036', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle partial resynchronization during a replica reconnection?', N'Senior', N'Redis maintains a replication backlog buffer; if a replica reconnects within a certain window, it can request only the missing data instead of performing a full resynchronization. This significantly reduces network bandwidth and CPU usage by avoiding the need to regenerate and transmit an entire RDB snapshot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c26de2ce-ff9b-4e4d-b957-ce751b5929ba', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you create a constructor function?', N'Fresher', N'To create a constructor function in JavaScript, define a regular function with a capitalized name to indicate it''s a constructor. Use the this keyword to set properties and methods. When creating an instance, use the new keyword. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd18bf24b-7d3e-4db3-8ca9-ce7789b87c84', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you evaluate whether to build a custom solution or use a third-party managed service?', N'Middle', N'I consider the core competency of the business, the maintenance overhead, and the time-to-market. I prefer managed services for commodity features like authentication, storage, or email delivery to reduce operational burden. I only build custom solutions if the requirement is a unique competitive advantage or if existing tools fail to meet performance requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a34d559a-48bd-4a0f-9c11-ce77bce1edc8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the difference between a primary key and a unique index?', N'Intern', N'A primary key is a logical constraint that identifies a row and implies the column cannot be null. A unique index is a physical structure that ensures all values in a column are distinct, but it does not necessarily enforce the primary key concept.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52661d6f-2d51-487b-9151-ce78cea95ec3', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between ''Lazy Loading'' and ''Eager Loading'' in terms of initial application startup?', N'Senior', N'Eager loading forces all modules to be loaded during application bootstrap, which increases the initial bundle size and delays time to first paint. Lazy loading splits the application into smaller chunks that are fetched on demand, significantly reducing the initial payload and improving the startup experience for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77762d33-687e-4536-a386-ce7adf530f4a', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the impact of ''Fillfactor'' on table and index storage?', N'Senior', N'Fillfactor determines the percentage of space used in a page during inserts, leaving the remainder as free space for future updates. A lower fillfactor reduces the need for page splits and promotes HOT updates, but it increases the overall storage footprint and reduces cache efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b63ca12d-6fc9-406f-8fc0-ce7c660f22b9', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do service meshes assist with observability?', N'Middle', N'A service mesh transparently intercepts network traffic between services to collect telemetry data like request rates, error codes, and latency. This allows developers to gain observability without adding custom instrumentation code to every individual service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acc0b7d0-f70f-46ff-80ca-ce7e4481f931', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What role does the DOM play in Qwik''s architecture?', N'Fresher', N'The DOM acts as the single source of truth for the application''s state and structure in Qwik. Because the state is serialized into the HTML, the framework can reconstruct the application by reading the DOM rather than re-executing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07034a1a-097b-4e76-a919-ce87b5f58dea', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''factory'' constructor in Dart''s object model?', N'Senior', N'A factory constructor allows a class to return an instance of itself or a subclass without necessarily creating a new instance every time. This is architecturally useful for implementing design patterns like the Singleton, caching, or returning pre-computed instances, which enhances resource management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f70fe1b-c177-42ac-8a9f-ce87fccb70f2', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How do procedural macros in Rust differ from declarative macros?', N'Senior', N'Declarative macros use pattern matching to generate code based on a set of rules, offering a simpler syntax for common transformations. Procedural macros operate as functions that receive and return tokens, providing deep introspection into the abstract syntax tree and enabling advanced code generation patterns that are impossible with declarative macros.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08f51ea7-e29c-48a6-97aa-ce881a1b4607', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the trade-offs when choosing Preact over React for a large-scale enterprise application?', N'Middle', N'The main trade-off is the loss of React''s extensive ecosystem support, complex debugging tools, and large community-maintained packages that may depend on React-specific internals. While Preact offers better performance and smaller size, it may require more configuration or custom workarounds for complex enterprise-grade requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56511bf9-5983-4e2e-a2ca-ce88a869c695', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is it difficult to achieve total ordering of events in a distributed system without a centralized sequencer?', N'Senior', N'Without a central authority, clocks across distributed nodes drift, making it impossible to determine a globally consistent temporal order using timestamps alone. Systems must rely on logical clocks like Lamport clocks or vector clocks, which only provide partial ordering based on causal dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2deefa1a-0d72-467a-bf51-ce8b5850495a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the significance of the CAP theorem in the context of choosing a database for a global application.', N'Senior', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In a global network where partitions are inevitable, architects must prioritize either consistency (CP) to ensure data accuracy or availability (AP) to maintain service uptime during failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6769f244-3e74-48d6-96c9-ce8c79b82615', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Describe the function of the drop checker in Rust''s ownership system.', N'Senior', N'The drop checker determines whether a generic type can safely access references during its destructor. It prevents use-after-free errors by ensuring that no data is accessed after the objects it depends on have been dropped, imposing strict constraints on the lifetimes of references within data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da2fc7a2-d5e3-45e1-9a94-ce8d15bdb42f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''const'' qualifier do when applied to a variable in C?', N'Junior', N'The const qualifier indicates that a variable''s value cannot be modified after its initial assignment. It is used to define read-only variables, helping to prevent accidental changes to data that should remain constant throughout the program''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'899ce451-de23-423c-a36a-ce90f591c945', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Why is it generally better to use surrogate keys over natural keys?', N'Middle', N'Surrogate keys (like auto-incrementing integers) are immutable, compact, and provide consistent performance. Natural keys (like email addresses or usernames) can change, are often large strings, and are less efficient to index and join compared to integer-based keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e73cb66-4395-4204-af6d-ce912c17ea85', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Is it possible to deploy Astro to static hosting providers?', N'Junior', N'Yes, because Astro outputs standard HTML, CSS, and JavaScript files, it can be hosted on any static site hosting service like Netlify, Vercel, GitHub Pages, or any traditional web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8bbc3b6-f7c5-4fc6-a706-ce930cd4bc85', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the ''DTO'' (Data Transfer Object) in Litestar?', N'Intern', N'DTOs in Litestar are used to define the schema for data being sent to or received from the client. They help decouple the internal data models from the external API representation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fb82131-0fdc-4497-b424-ce96d1738bac', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between client-side and server-side scripting?', N'Intern', N'Client-side scripting runs on the user''s web browser, while server-side scripting runs on the web server. PHP is server-side, meaning the server processes the logic and sends the resulting HTML output to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'311ffa89-0a2f-476b-a8dc-ce980ff60d09', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Describe the concept of ''batching'' in SolidJS and why it is used.', N'Senior', N'Batching is used to group multiple signal updates into a single transaction, preventing redundant effects or DOM updates from firing for every individual change. By wrapping updates in a batch function, the reactive system waits until the end of the execution block to notify subscribers, improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27e412cc-40a9-4c0f-8f5e-ce9a05dd1701', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the benefit of using NestJS''s Task Scheduling module over cron-based OS-level schedulers?', N'Senior', N'The Task Scheduling module provides a programmatic way to define and manage background tasks within the application runtime, allowing for better access to application services and DI-managed resources. This approach ensures that cron jobs are synchronized with the application state and can be easily tested alongside business logic, unlike OS-level scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a044fc-3289-443c-acae-ce9a61e3527b', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the oplog?', N'Junior', N'The oplog (operations log) is a capped collection that keeps a rolling record of all operations that modify the data stored in the database. It is essential for replication, as secondary nodes read from the primary''s oplog to apply the same changes locally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79e14827-5e95-44b2-8645-ce9ac65ac502', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How would you implement custom middleware in FastAPI to handle cross-cutting concerns like logging or rate limiting?', N'Senior', N'Custom middleware can be implemented by inheriting from BaseHTTPMiddleware or by using Starlette''s middleware framework to wrap the application. This allows you to intercept incoming requests and outgoing responses globally, enabling centralized observation and security enforcement without polluting individual route logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdb424c2-b496-46ee-84b2-ce9b5e7ce1ec', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the significance of the ''volatile'' keyword?', N'Fresher', N'The volatile keyword tells the compiler that a variable''s value can change at any time due to external factors, such as hardware or another thread. It prevents the compiler from performing optimizations that assume the variable''s value remains constant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc497d58-facc-441f-a806-cea582946484', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''components'' directory in Nuxt?', N'Intern', N'The components directory is where you store reusable UI parts of your application, such as buttons, headers, or footers. Nuxt automatically imports these components so you can use them throughout your pages without manual import statements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'197c6342-193d-409c-b109-cea5f0113cd8', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle database transactions across multiple connections, and what are the risks?', N'Senior', N'Laravel supports multi-connection transactions by specifying the connection name, but it does not support distributed transactions (2PC) out of the box. The risk is partial data commitment if one connection fails after another succeeds, requiring manual compensation logic or sagas in distributed architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e4548ee-148a-4244-ac17-cea77a0f92c2', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Can FastAPI handle synchronous code?', N'Intern', N'Yes, FastAPI can handle synchronous functions by running them in a separate thread pool. However, it is optimized for asynchronous code, so using async functions is preferred for I/O-bound operations to maintain performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2a90d58-e20b-4651-801d-cea78c9eb1c5', N'4c000000-0000-0000-0000-000000000005', N'What are the implications of using a Bloom filter in large-scale storage systems?', N'Senior', N'A Bloom filter is a space-efficient probabilistic data structure used to test if an element is in a set. While it can produce false positives, it prevents unnecessary disk lookups for non-existent keys, significantly improving read performance in key-value stores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cacacccb-349f-48fb-9903-ceab1395bbe6', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural impact of moving from a monolith to microservices regarding the security perimeter?', N'Senior', N'In a monolith, the perimeter is largely external, whereas microservices introduce a vast internal attack surface. This necessitates shifting from a ''trusted intranet'' model to a Zero Trust model, where every internal request must be authenticated, authorized, and inspected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4580ae10-36e9-4c1d-8685-ceabdab061df', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is Immutability, and why is it preferred in Scala?', N'Intern', N'Immutability means that once an object is created, its state cannot be changed. It is preferred in Scala because it eliminates bugs related to shared state, making code safer, more predictable, and easier to execute in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16ae4e24-f3e3-48f5-ab3e-ceac093ae7d0', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do HTML slots in the Shadow DOM facilitate flexible component composition?', N'Senior', N'Slots provide a mechanism for placeholder injection where external markup can be passed into a custom element''s shadow tree. This allows for a clean separation between the component''s internal structure and the user-provided content, enabling highly reusable and configurable UI patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
