INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a77b9144-1c73-48a7-bf53-ceb4801f5722', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between GET and POST methods?', N'Junior', N'GET is intended to retrieve data from a server without changing its state, and it should be idempotent. POST is used to submit data to the server to create a new resource, which often results in a state change on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
