INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b87b48b-5512-4010-9422-cedc75ca76d0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the purpose of using a configuration file instead of hardcoding settings in the code?', N'Fresher', N'A configuration file allows settings to be changed without needing to recompile or modify the source code. This makes the application more flexible, as the same code can be deployed to different environments with unique settings simply by changing the external config file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'757d1f7c-9458-44b9-a530-cedf263d97dd', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass''s built-in color functions handle color space transformations?', N'Senior', N'Sass provides functions to manipulate colors by adjusting hue, saturation, and lightness, or by mixing colors together. These functions ensure consistent color math during the build process, allowing for dynamic theme generation without needing to manually calculate hex or RGB values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05520931-93eb-4153-b8fc-cedfa71e0cbc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the role of the ''Server'' builder in Actix-web.', N'Middle', N'The Server builder is used to configure the HTTP server''s runtime behavior, such as the number of worker threads, the address to bind, and the maximum number of concurrent connections. It acts as the entry point for starting the underlying asynchronous runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90fa5fb7-af2e-4356-8b10-cee06049fb26', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage shared state across different middlewares?', N'Middle', N'Hono provides a ''set'' and ''get'' mechanism within the context object. This allows developers to pass data from an authentication middleware, for example, to subsequent route handlers without polluting the global scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51b7d6bc-4df8-4cf1-af6b-cee0eeb5149f', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between force unwrapping and optional binding?', N'Intern', N'Force unwrapping uses an exclamation mark to access an optional value, which causes a runtime error if the value is nil. Optional binding uses if let or guard let statements to safely check if a value exists before accessing it, which is the recommended way to handle optionals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04abc4f8-4c38-4e2f-b1f0-cee1b54ba603', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the role of the Vercel edge runtime.', N'Middle', N'The Edge Runtime is a lightweight environment designed for high-performance, low-latency execution of code close to the user. It is ideal for tasks like authentication checks, A/B testing, and simple API responses where minimal boot time is critical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9329eb1a-1011-4516-9b98-cee1d2216255', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the role of ''backpressure'' in maintaining system reliability?', N'Senior', N'Backpressure allows a system to signal upstream services to slow down when it is approaching its processing capacity. This prevents buffer overflows and crashes, ensuring the system fails gracefully under load rather than becoming unresponsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a777b651-bfd6-471a-aad6-cee4613676f3', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the concept of ''Type Erasure'' as an architectural pattern in Swift.', N'Senior', N'Type erasure is a technique to hide the specific type of a generic object behind a non-generic wrapper, often used to work around limitations with associated types in protocols. It allows developers to store heterogeneous objects in a collection while maintaining a clean API surface. While powerful, it often requires manual wrapping or using ''any'' to bridge the gap between concrete implementations and generic requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'914b9682-9bef-4697-86b9-cee7d837bfa3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is event capturing?', N'Intern', N'Event capturing is a type of event propagation where the event is first captured by the outermost element and then successively triggers on the descendants (children) of the target element in the same nesting hierarchy till it reaches the inner DOM element. Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9a505ee-855e-435b-9736-cee97cf254a0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of an environment variable?', N'Fresher', N'Environment variables are used to store configuration settings, such as database URLs or API keys, outside of the application code. This allows the same code to run in different environments, like testing or production, just by changing the values assigned to those variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb32c5a1-9ff4-499e-93ad-cef01cc729f1', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do mixins support the ''DRY'' (Don''t Repeat Yourself) principle?', N'Middle', N'Mixins allow you to define a block of styles once and reuse it across multiple selectors. This reduces code duplication and ensures that if a change needs to be made to that style block, you only have to update it in one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e992ef5-0ba8-4560-9e6c-cef1d972c44e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix approach data fetching?', N'Fresher', N'Remix fetches data on the server during the initial request, eliminating the ''waterfall'' effect where components fetch data sequentially. By centralizing data loading in route-level functions, the application avoids unnecessary client-side network requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7240ac31-e58c-488c-9b92-cef40eeda673', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How can you handle cache invalidation in a microservices architecture?', N'Middle', N'Cache invalidation is difficult in distributed systems due to data propagation delays across multiple nodes. Common strategies include using TTLs for eventual consistency, publishing invalidation events via a message broker, or using versioning to ensure that services do not read stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
