INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2012c9c-2303-4e87-b54e-cef5019104e1', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is a Provider scope?', N'Junior', N'Provider scope determines how long an instance of a provider exists. The default scope is singleton, meaning the same instance is shared across the whole app, but it can also be set to request-scoped, creating a new instance for every incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dae52bed-26b5-4f97-afc4-cef5d971a562', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does file-based routing work in Next.js?', N'Intern', N'Next.js uses the filesystem to define routes based on the structure of the files inside the app or pages directory. Each file or folder corresponds to a specific URL path, removing the need for complex manual route configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
