INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aec3456e-1c6e-475e-ae14-cf00b4b0f6fa', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the B-Tree index structure improve query performance?', N'Middle', N'A B-Tree index keeps data sorted and allows for efficient search, sequential access, and insertions. It reduces the number of disk I/O operations by maintaining a balanced tree structure where every path from the root to a leaf node is the same length.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'652d57ec-b476-423b-b40d-cf036febeebf', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the architectural trade-offs between using a monolithic vs. micro-frontend approach in Angular applications.', N'Senior', N'Monoliths offer simpler dependency management and unified state, but often lead to long build times and deployment bottlenecks as the team grows. Micro-frontends allow independent team autonomy and faster deployment cycles but introduce significant complexity regarding shared state, styling isolation, and orchestration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
