INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'017dfd2f-ee4d-4d57-b8c4-cf048939cbf8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are default parameters and how are they used?', N'Intern', N'Default parameters in JavaScript allow you to set default values for function parameters if no value or undefined is passed. This helps avoid undefined values and makes your code more robust. You can define default parameters by assigning a value to the parameter in the function definition. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9d8b843-9754-4a87-83ec-cf06d6cae82d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the advantages of using ''Result'' types over throwing errors?', N'Middle', N'Result types make error handling explicit in the function signature, ensuring the caller is aware that an operation might fail. While throwing errors is often more concise, Result types are highly beneficial in asynchronous code, as they capture the error state as a value that can be passed across execution contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68f4aed9-8062-4653-99ac-cf07271bddda', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''Read-Committed'' isolation level differ from ''Repeatable Read'' regarding snapshot stability?', N'Senior', N'In Read-Committed, each query within a transaction sees a new snapshot of the database, meaning data can change between queries. In Repeatable Read, the transaction uses a single snapshot taken at the start of the transaction, ensuring all subsequent reads are consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fabe3e82-7cb8-441a-a5dd-cf0d7d70b290', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine if a problem requires a simple fix or a redesign?', N'Fresher', N'I look at the frequency of the issue and whether it is a symptom of a larger, systemic architectural problem. If a simple fix is fragile and likely to break again, a redesign is worth the investment to save time in the long run. I weigh the immediate effort against the future maintenance cost to make an informed decision.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78ce5487-b781-478a-ad30-cf155ce0ca7d', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does the @Transactional annotation handle proxying?', N'Middle', N'Spring uses AOP proxies to wrap the target bean when @Transactional is detected. When a method is called, the proxy intercepts the invocation to start a transaction before the method executes and commits or rolls it back afterward. This mechanism only works for external calls; self-invocation within the same class bypasses the proxy and thus the transaction logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec757330-5399-4be0-92ab-cf168802bdac', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle global state compared to frameworks like React?', N'Middle', N'In Qwik, state is serialized into the HTML document during server-side rendering. When the application resumes, it recovers this serialized state from the DOM, allowing it to maintain consistency across the server-client boundary without needing a complex re-initialization process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b16576b-8f32-4979-bd3c-cf17d2e172ad', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is an unrepeatable read?', N'Intern', N'An unrepeatable read happens when a transaction reads the same row twice and gets different data each time. This occurs because another transaction modified and committed that row in between the two reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26ab8aff-f0d9-4db8-8091-cf185f43da43', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the limitations of type hinting in Python, given that it is a dynamically typed language?', N'Senior', N'Type hints in Python provide static analysis benefits but are ignored at runtime, meaning they do not enforce type safety or change the language''s dynamic execution behavior. They rely on external tools like MyPy for validation, and they can be complex to maintain for highly dynamic patterns like dynamic attribute generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b72b08a-bc13-46af-8995-cf18cde86c04', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle memory leaks compared to standard DOM manipulation?', N'Middle', N'jQuery attempts to manage event listener cleanup when an element is removed via its own methods, which helps prevent memory leaks. However, if developers manipulate the DOM outside of jQuery while having listeners attached, or fail to unbind events properly, leaks can still occur, highlighting the need for careful lifecycle management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ccfe80c-4990-459b-91cd-cf1cd3cc7881', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What does ''root cause analysis'' mean to you in a professional setting?', N'Fresher', N'It means digging past the symptoms of a problem to find the fundamental error that caused it. Instead of just patching the immediate issue, I look for ways to prevent the same problem from recurring in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62108fdc-8fa1-4e90-8a3a-cf1e9944fc8d', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why use optimistic locking instead of pessimistic locking in database operations?', N'Middle', N'Pessimistic locking prevents others from accessing data, which can lead to deadlocks and poor performance in high-concurrency environments. Optimistic locking assumes conflicts are rare and only checks for version changes at the time of commit, improving throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e71297f9-2f7d-494e-a043-cf1f56c422c3', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the main challenge of testing an application built with many utility classes?', N'Middle', N'The main challenge is that visual regression tests can be fragile if class names change or if the HTML structure is heavily coupled with style. Using component-based testing strategies helps isolate style changes from logical functionality, keeping tests stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d47428c-5c5d-45d5-860b-cf22a64b8494', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the role of the ''rocket::build()'' function?', N'Junior', N'The build function initiates the Rocket application builder. It is the entry point where you configure your routes, mount paths, attach fairings, and manage the application state before officially launching the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8b72e08-e9b0-423d-8170-cf2625ba09e7', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage concurrent data loading when multiple nested routes are active?', N'Senior', N'Remix executes all loaders for the active route hierarchy in parallel on the server. By aggregating these requests, it ensures that the complete data payload is available for the initial render, preventing the nested request sequences that plague client-side SPA architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b86eb0c4-a617-457a-9cdc-cf27884e66c1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between an application instance and a group in Fiber?', N'Intern', N'An application instance is the main server object, while a group allows you to prefix a set of routes with a common path. Groups are useful for organizing code, such as grouping all API v1 endpoints under a single path prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a70cd29b-698a-4053-a9d2-cf27ba02b5ab', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Redis ''String''?', N'Intern', N'A Redis string is the simplest data type and can hold text, binary data, or even serialized objects. It is the fundamental building block and is often used to store simple values like tokens or counts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'631663c0-acbf-4ee9-b62b-cf280b564fcb', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the concept of immutability in Redux and why it is necessary.', N'Middle', N'Immutability means the state is never modified directly; instead, a new object is returned. This is necessary because it allows the store to perform shallow comparisons to determine if the state has changed, which is critical for performance optimization in view layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1f60d7e-4d86-4916-8305-cf29a49bc97b', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does the ''sandbox'' attribute do on an iframe?', N'Middle', N'The ''sandbox'' attribute enables extra security restrictions for content within an iframe, such as preventing form submission, script execution, or accessing top-level navigation. By applying this attribute, developers can create a safe environment for displaying untrusted or third-party content. It helps prevent cross-site scripting (XSS) attacks from compromising the main application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16fa928d-bb0f-4480-ab80-cf2a3e7bceb6', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix differ from traditional Single Page Applications in terms of data loading?', N'Middle', N'Remix leverages server-side data loading via loader functions that execute before the component renders. Unlike SPAs that often fetch data on the client after mounting, Remix ensures the UI and its required data arrive simultaneously, preventing layout shifts and loading states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8d589e0-f2c1-41f3-8a4a-cf2bcb78ed7b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask and what is its primary classification?', N'Fresher', N'Flask is a lightweight WSGI web application framework written in Python. It is classified as a micro-framework because it does not require particular tools or libraries and keeps the core simple while remaining extensible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'956b64cd-a2b4-4dfc-920a-cf2cf6e58f2d', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is an Asynchronous Controller action?', N'Junior', N'An asynchronous action uses the async and await keywords to perform non-blocking I/O operations, such as database queries. This allows the server thread to be released back to the thread pool while waiting for the operation to complete, which improves application scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d63cb49-f986-4c5a-a9fe-cf2eb77139db', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are Rails Generators?', N'Intern', N'Generators are command-line tools that automatically create the boilerplate code for various components of a Rails application. They help save time by scaffolding files like controllers, models, migrations, and tests according to the established framework conventions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0007ef37-70d5-4f4c-901c-cf323cd11fa0', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte ensure that only necessary DOM parts are updated?', N'Middle', N'The compiler generates precise DOM update instructions that target only the specific elements affected by state changes. Because the framework tracks dependencies at compile-time, it knows exactly which parts of the DOM are dynamic and which are static.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36249517-fee6-491e-8c93-cf32505300ab', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is it important to compile Sass into CSS before deployment?', N'Junior', N'Browsers cannot interpret Sass files directly because they do not understand its syntax. Compilation converts the Sass code into standard CSS that every modern browser can render correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c6da00b-a6d0-4b91-be20-cf3396798e03', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the potential performance trade-offs when adding too many indexes to a table?', N'Middle', N'Each additional index consumes extra disk space and memory. More importantly, every INSERT, UPDATE, or DELETE operation incurs additional overhead because the database must update all associated index structures, which can significantly degrade write performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21762422-6c2c-4199-bab8-cf38908477c5', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle key expiration and eviction?', N'Middle', N'Redis uses both passive and active expiration; it checks keys when accessed and periodically samples keys to delete expired ones. Eviction is triggered when the memory limit is reached, based on the configured policy to select which keys to remove to make room for new data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50e5c94c-30fc-43dd-b84a-cf3925f8460b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is referential integrity and why is it important?', N'Junior', N'Referential integrity ensures that relationships between tables remain consistent, meaning a foreign key value must always point to an existing primary key in the related table. It is important because it prevents orphaned records and maintains the overall accuracy and reliability of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
