INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd12f0073-5a35-4fd7-8f61-cf39a95d0bcd', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s event delegation differ from standard DOM event handling?', N'Middle', N'Lit doesn''t implement a custom event delegation system; it relies on the native browser event propagation. Since events from the Shadow DOM are retargeted to appear as if they originated from the host element, it simplifies how parent components listen to child actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6c4396d-ccfd-4ba1-af2f-cf3bbb531be8', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why should you avoid using the ''SELECT *'' pattern in production?', N'Middle', N'Selecting all columns increases network traffic and memory usage by fetching unnecessary data. Furthermore, it breaks the functionality of covering indexes and can cause application failures if the schema changes, such as adding a large text column to the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d9dd949-5e4f-431d-89b7-cf3c22c52ed7', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary purpose of null safety in Kotlin?', N'Intern', N'Null safety is a feature designed to eliminate the risk of null pointer exceptions in applications. By distinguishing between nullable and non-nullable types at compile time, it forces developers to handle potential null values explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0ee2975-4864-4409-b089-cf3d697f1d4f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the significance of the key prop in Preact lists?', N'Junior', N'The key prop helps Preact uniquely identify elements in a list during the diffing process. Using stable keys improves rendering performance and prevents bugs when items are reordered, added, or removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'578cd237-9f0b-462c-9f18-cf3f083f0533', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle ''routing'' and why would you manually define a routing key?', N'Senior', N'Routing determines which shard a document belongs to, usually via a hash of the document ID. Manually defining a routing key ensures that related documents are colocated on the same shard, which allows for highly efficient queries that target specific shards instead of broadcasting to all nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65e6043f-58a3-4adf-bb1e-cf4316e00078', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between high availability and data consistency in a distributed system?', N'Junior', N'According to the CAP theorem, during a network partition, you must choose either to remain available by serving potentially stale data or to prioritize consistency by refusing requests until data is synchronized. You cannot perfectly achieve both in the event of a failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45f9a61c-7f03-4b68-a3b0-cf43d08b039b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the concept of ''Content Detection'' in Tailwind and why it is critical for build performance.', N'Senior', N'Tailwind uses regex-based scanning of source files to identify which utility classes are used. Accurate content detection ensures that the generated CSS remains minimal, preventing the inclusion of thousands of unused classes in the final production bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'789720e8-6662-4a98-9af2-cf48fbc16dbd', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Explain the concept of ''Signals'' in the context of Preact''s state management.', N'Middle', N'Signals are a reactive primitive that allow state to be updated and consumed outside of the standard component lifecycle. They enable fine-grained updates, meaning only the specific components or DOM nodes that depend on a signal will re-render when its value changes, bypassing the need for a global component tree update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6ec3ba7-6fae-4219-b96d-cf4a09c81873', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of using Environment Variables in AdonisJS?', N'Fresher', N'Environment variables allow you to store sensitive configuration data, such as database credentials and API keys, outside of the application code. This improves security and allows the same codebase to behave differently across development, testing, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b3f23d6-1d7a-41fb-87e2-cf4ce5c61219', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the primary considerations when designing a plugin architecture for a large Fastify application?', N'Senior', N'Key considerations include proper scope management, avoiding circular dependencies, and ensuring that plugins are truly modular. It is essential to use the encapsulation feature to prevent leakage of logic between unrelated parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0148d51a-3f81-4c6e-9bed-cf4e9d3947f7', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is cache stampede and how can you mitigate it?', N'Senior', N'Cache stampede occurs when a highly requested key expires, causing multiple concurrent requests to miss the cache and overwhelm the underlying database. It is typically mitigated using request collapsing, mutex locks to ensure only one process fetches the data, or probabilistic early expiration techniques.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60fbae5b-a998-4d7e-b7e3-cf5159cbce4f', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you pass data from a parent to a child component?', N'Intern', N'Data is passed from a parent to a child component using properties, commonly referred to as props. In the child component, you mark variables as props so they can receive values provided by the parent during component instantiation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6990d3fb-7ccb-4772-82f3-cf52a955e959', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is an optimistic concurrency control strategy?', N'Intern', N'Optimistic concurrency control assumes that conflicts are rare. Instead of locking data, it checks for changes made by other transactions only at the time of commit; if a conflict is detected, the transaction is rejected and retried.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b18d38b8-afa4-48a0-9f61-cf547566eed7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you set custom headers in Express?', N'Fresher', N'You can set custom headers using the res.set or res.header methods. These methods accept the header name and the value, and they should be called before sending the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab874a9d-0cd1-4226-afe2-cf574e2fd88c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do C# value types and reference types interact with the garbage collector, and what are the implications of boxing on heap allocation and GC pressure?', N'Senior', N'Value types are typically allocated on the stack or inline within objects, whereas reference types are always allocated on the managed heap, requiring GC tracking. Boxing forces a value type onto the heap, creating an object wrapper that increases memory pressure and triggers more frequent GC collections. For high-performance systems, minimizing boxing is essential to reduce object allocation rates and avoid unnecessary garbage collection overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3281216b-f6b7-4fad-b28d-cf577a5b29ee', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of the Response object?', N'Fresher', N'The Response object is returned by a handler to define what the server sends back to the client. It includes the status code, the response body, and any necessary headers or cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69a5836c-6cbf-4bfd-a998-cf58266fbbd7', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing an API, what are the trade-offs of using a RESTful approach versus GraphQL?', N'Junior', N'REST is simple to implement and leverages existing HTTP caching, but often leads to over-fetching or under-fetching data. GraphQL allows clients to request exactly what they need in one call, but it is more complex to implement and harder to cache effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fd658f8-3ba6-41e2-8a2d-cf590f76f843', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s plugin pattern contrast with modern composition patterns?', N'Senior', N'jQuery plugins typically extend the global jQuery object, creating a monolithic, rigid structure. Modern development favors composition, where small, functional modules are combined to create complex behavior, leading to greater flexibility and easier refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
