INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a3df723-c48f-4e9f-99db-cf5b31d4fb2a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it often necessary to use a reverse proxy like Nginx in front of a Flask application?', N'Senior', N'A reverse proxy handles concerns like SSL termination, static file serving, and load balancing, which are inefficient for a Python application to manage. It also shields the Flask application from direct internet exposure, providing an extra layer of security and protection against certain types of denial-of-service attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bbbfe09-d8e2-4631-84bb-cf5bb5ffae85', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why is it important to prevent ''Index Intersection'' from becoming a primary query strategy?', N'Senior', N'While MongoDB can use multiple indexes to satisfy a query, index intersection is often less efficient than a single, well-designed compound index. Relying on it can lead to unpredictable performance spikes and higher CPU utilization compared to a singular index that covers the query requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7314e185-c420-4c6d-8952-cf5d9828e86e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do Redis eviction policies interact with TTL settings in a memory-constrained environment?', N'Senior', N'Redis can evict keys based on LRU or LFU algorithms. If volatile-lru is selected, Redis only considers keys with an expiration set, whereas allkeys-lru allows the eviction of any key, which is more effective for preventing OOM errors but risks removing frequently accessed persistent data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37548389-d9f7-4c42-a7bf-cf5dfbe21d5f', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''key'' attribute when rendering lists?', N'Middle', N'The key attribute helps Vue''s diffing algorithm uniquely identify nodes. Without it, Vue uses an in-place patch strategy that can cause issues with stateful components or transition effects during list reordering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
