INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c38db40-4ac8-46cf-8ac4-cf661a3667c3', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you handle memory leaks in a long-running Node.js process, and what tools are used to diagnose them?', N'Senior', N'Memory leaks usually stem from unintended closures, global variables, or unreleased event listeners. Diagnosis involves taking heap snapshots using the V8 inspector and comparing them over time to identify objects that are not being garbage collected. Tools like Chrome DevTools, Clinic.js, and Memlab are standard for identifying the retention path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bce0ac0-d8d1-4264-bd16-cf673c216c28', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are C preprocessor macros?', N'Fresher', N'Macros are fragments of code that have been given a name, defined using the ''#define'' directive. Before compilation, the preprocessor replaces every occurrence of the macro name with its defined value or code snippet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
