INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee9e231e-77a6-4165-b9ba-cf71ab1ad701', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s ''KeepAlive'' component impact the lifecycle of nested components, and what are the performance trade-offs?', N'Senior', N'KeepAlive prevents component destruction by caching the instance in memory, which improves performance by avoiding expensive re-renders and re-initialization. However, it increases memory consumption and requires careful management of lifecycle hooks like activated and deactivated rather than mounted and unmounted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85ab3837-d2f0-4c0d-8ca4-cf71f2019ccc', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why might you choose a struct with static methods over a singleton class?', N'Middle', N'A struct with static methods is more lightweight and avoids the complexities of shared global state that comes with a singleton. It is easier to test and reason about because it does not maintain persistent state, promoting a more functional and stateless programming style.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
