INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22fba1e9-bcca-457b-89c8-cf7d31edc3e2', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Discuss the impact of ''async rendering'' on Lit''s update lifecycle.', N'Senior', N'Lit''s updates are asynchronous by default, meaning that property changes are batched until the next microtask. This improves responsiveness by preventing the UI from locking up during rapid-fire state updates and ensures the browser performs only one paint operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
