INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e29b712-fd86-435e-bfba-cf833746646b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the trade-offs of using Flask for high-performance I/O bound vs. CPU-bound tasks.', N'Senior', N'Flask is well-suited for I/O-bound tasks when integrated with asynchronous workers, but it performs poorly for CPU-bound tasks due to the Global Interpreter Lock (GIL). For intensive computation, the task must be offloaded to a separate worker process or service written in a language that supports true multi-threading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'431bdcba-7f12-424d-98c2-cf840183c07a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Is it possible to have a database without transactions?', N'Fresher', N'Yes, some simple key-value stores or data logging systems may not support transactions. These systems sacrifice data integrity guarantees for extreme simplicity and speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
