INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ee1962b-2332-4345-a7d3-cfacc534d2db', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB implement concurrency control during item updates?', N'Senior', N'DynamoDB uses optimistic locking through conditional expressions to ensure that an update only occurs if the item state remains unchanged since it was read. This prevents lost updates in concurrent environments without the overhead of pessimistic database-level locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29d2ba28-1a22-441a-b83b-cfae08d6c265', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s ''Policy'' system differ from ''Gates''?', N'Middle', N'Gates are simple closures used to determine if a user is authorized to perform an action, often for simpler logic. Policies are class-based authorization handlers that are specifically tied to a model, making them better for organizing complex authorization logic related to specific resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8626ff4-5be0-4202-9452-cfaf59eb1fd7', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Dependency Injection work in Symfony?', N'Fresher', N'Dependency Injection is a design pattern where an object receives other objects it depends on rather than creating them internally. In Symfony, the container automatically injects these dependencies into classes, promoting loose coupling between components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fa6f22b-6cde-4076-bf90-cfafada6280a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between synchronous and asynchronous operations in Node.js?', N'Intern', N'Synchronous operations block the execution of subsequent code until the current task completes. Asynchronous operations allow the program to continue executing other tasks while waiting for a background process, such as a file read or database query, to finish.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19888759-73a3-41aa-bef3-cfafbfaaa115', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the trade-offs of using client-side transactions versus server-side transactions?', N'Senior', N'Server-side transactions are managed by the database engine, providing strong consistency and simplified application logic. Client-side transactions, often implemented via application-level coordination, offer more flexibility for complex workflows but are significantly harder to implement correctly and are prone to data anomalies during system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfa786e8-7b29-4b2c-a9ba-cfb0795c6112', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the default behavior of Fiber when a route is not found?', N'Fresher', N'If a route does not match any defined paths, Fiber automatically returns a 404 Not Found error. This behavior can be customized by defining a custom 404 handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd530cf51-0e84-42e4-96d1-cfb0a63ef822', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you discover a bug in production, what is your immediate priority?', N'Intern', N'My immediate priority is to assess the impact and severity of the bug to determine if an emergency rollback or hotfix is required. I would communicate the issue to the relevant team members to ensure everyone is aware of the situation. Once the immediate danger is mitigated, I would document the steps to reproduce it and work on a permanent solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c353b6d-f046-4a47-b547-cfb255877fd5', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you access a DOM element inside a Lit component?', N'Fresher', N'You can use the query decorator, such as query, to find a specific element within the component''s Shadow DOM. This allows you to interact directly with the DOM node after the component has rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04f0e430-2f51-460a-81ca-cfb54e981076', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the trade-offs of using Preact instead of React for large-scale enterprise applications?', N'Middle', N'The primary trade-off is the reduced ecosystem support and potential compatibility issues with complex third-party component libraries that rely heavily on React internals. While Preact is faster and smaller, React offers a larger community, more extensive tooling, and deeper integration with frameworks like Next.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a442d65-8fd9-4876-b14c-cfb5bace678c', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is the order of execution in the ''update'' lifecycle phase critical for performance?', N'Senior', N'The update cycle follows a strict order: property changes, validation, and rendering. Understanding this sequence is vital for developers to avoid blocking the main thread or causing layout thrashing by performing DOM reads/writes in the wrong lifecycle hook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'509be599-bbe6-4099-9670-cfb9e5427903', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'In what scenario would you choose Astro over Next.js?', N'Middle', N'Astro is ideal for content-centric sites where minimizing JavaScript is the top priority for performance. Next.js is generally a better choice for highly dynamic, complex web applications that require deep integration with React ecosystem features and persistent client-side state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb52c9df-5dcf-4553-8657-cfbb46856c74', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Describe the architectural trade-offs of using Worker Threads versus the Cluster module in Node.js.', N'Senior', N'The Cluster module forks separate processes, each with its own memory space and event loop, which is ideal for scaling horizontally across CPU cores. Worker Threads share the same process memory and provide lighter-weight parallelism for CPU-bound tasks, though they require careful management of shared memory to avoid data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0283cbbe-42bc-45f6-b919-cfbf90ad8bbc', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it difficult to implement server-side rendering (SSR) in applications heavily dependent on jQuery?', N'Senior', N'jQuery is fundamentally tied to the browser''s DOM API, which is missing in server-side environments like Node.js. Implementing SSR requires heavy mocking of the DOM or a complete rewrite of the UI logic, as jQuery cannot perform its primary function of DOM manipulation without a real browser context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78e02327-d7d1-47ee-b8ff-cfc28f7d8bb7', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a request context and an application context?', N'Intern', N'The request context keeps track of request-level data like URL parameters and headers. The application context tracks application-level data like configuration and database connections, existing for the duration of a request or CLI command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df9a8d00-7a7e-4e9b-945a-cfc4580e91b1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between ''let'', ''const'', and ''var'' in JavaScript?', N'Junior', N'The ''var'' keyword is function-scoped and allows redeclaration, which can lead to bugs. In contrast, ''let'' and ''const'' are block-scoped. The difference between them is that ''let'' allows you to reassign the value later, whereas ''const'' creates a constant reference that cannot be reassigned.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'413cb471-a026-4a92-969e-cfc6445398f2', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of Data Annotations in models?', N'Junior', N'Data Annotations are attributes applied to model properties to define validation rules, such as requiring a field or setting a maximum string length. These rules are automatically checked by the framework during model binding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa165835-91ba-405d-90dc-cfc68ebf5f3b', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Rails ''Autoloading'' mechanism?', N'Middle', N'Autoloading allows Rails to automatically require and load application classes and modules when they are first referenced in the code, eliminating the need for explicit require statements. While convenient, it can lead to confusing load-order issues if not managed correctly in complex, multi-threaded environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3188ab02-b68c-4e58-a956-cfcb27c54fd7', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How does verifying the infrastructure help during troubleshooting?', N'Intern', N'Sometimes an issue is not caused by the software itself, but by the underlying hardware, server configuration, or network connectivity. Verifying that the environment is healthy ensures you aren''t wasting time debugging perfectly functional code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11a87b7a-81f7-4e46-9e47-cfceaa86fde0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''Hydration Mismatch'' error, and how can it be avoided in Nuxt?', N'Middle', N'A hydration mismatch occurs when the server-rendered HTML differs from the initial client-side render, often due to non-deterministic data or browser-specific APIs. It can be avoided by ensuring data consistency, avoiding direct window or document usage during rendering, and using the ClientOnly component for browser-specific elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cf79365-3227-4aae-aa09-cfd048af3e06', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle error propagation and why is a four-argument middleware function required for error handling?', N'Middle', N'Express identifies error-handling middleware by checking if the function signature contains four arguments: err, req, res, and next. If any middleware calls next() with an argument, Express skips all non-error-handling middleware and proceeds directly to the first registered error-handling function in the chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c3e18f8-7dfa-4432-b182-cfd3a91b32fd', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What does ''status_code'' parameter do in a path operation decorator?', N'Intern', N'The ''status_code'' parameter allows you to define the specific HTTP status code that the endpoint should return upon a successful request. If not specified, FastAPI defaults to 200 OK for most successful operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cba70daa-f43d-4aa6-958a-cfd46b0a41c1', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Can you define data types in Sass?', N'Fresher', N'Yes, Sass supports various data types including numbers, strings, colors, booleans, nulls, lists, and maps. These types allow for more complex logic and data structures within your styling code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd906c6ac-fa7a-4de0-aeaf-cfd4d5944058', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the three states of promise', N'Fresher', N'Promises have three states: 1. Pending: This is an initial state of the Promise before an operation begins 2. Fulfilled: This state indicates that the specified operation was completed. 3. Rejected: This state indicates that the operation did not complete. In this case an error value will be thrown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb322dc3-e514-4cc9-a3f1-cfd64f920650', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where you realize your estimation was significantly off?', N'Intern', N'I would communicate the discrepancy to my supervisor as soon as I realized it, rather than waiting until the deadline. I would provide an updated estimate, explain the reasons for the change, and suggest potential ways to adjust the project scope if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a3f9902-0a56-48d4-b5fd-cfd8f30aaf9e', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is AOF in Redis?', N'Intern', N'AOF (Append Only File) records every write operation received by the server. This log can be replayed to reconstruct the dataset, providing better data durability than snapshots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c137124-d801-41f9-98d9-cfda99f8783c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify manage the event loop when processing a large number of concurrent requests?', N'Middle', N'Fastify''s architecture is highly non-blocking, ensuring that the event loop remains free to process incoming connections while awaiting I/O tasks. By offloading serialization and validation to optimized internal modules, it ensures that minimal synchronous work is performed per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'671f029a-4993-4ebc-931e-cfdc50e3a630', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is the choice of ''Extension'' important for application size in Quarkus?', N'Senior', N'Each extension adds code to the native binary. By selecting only the necessary extensions, developers can keep the final native binary size small, which improves deployment speed and reduces container image storage costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e58511e-897b-49b1-8ee6-cfde9ed51033', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What does it mean for Fiber to be ''zero memory allocation'' focused?', N'Intern', N'Being zero memory allocation focused means the framework is designed to minimize the creation of temporary objects that trigger garbage collection. By reusing buffers and structures, it reduces the CPU overhead required to manage memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b73c4db5-b761-45f8-b1de-cfe03c5b5e0a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Discuss the performance implications of deep component trees within a Nuxt application and how to mitigate them.', N'Senior', N'Deeply nested components increase the overhead of the reconciliation process and hydration, as the framework must traverse the entire tree to attach event listeners. Mitigating this involves utilizing lazy loading for non-critical components and leveraging the ''slots'' pattern to decouple parent-child dependencies, thereby flattening the dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4a87ca6-96d6-4185-9fa2-cfe7b00fe004', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the trade-off between building a quick prototype versus a production-ready feature during estimation?', N'Middle', N'I evaluate the business goal: if the goal is to validate an idea, I estimate for a prototype with minimal technical debt. If the goal is a permanent solution, I estimate for scalability and maintainability, clearly communicating the timeline differences to stakeholders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd8225ba-3fa5-4419-a60e-cfe8f0d236cd', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is an Actuator in Spring Boot?', N'Intern', N'Spring Boot Actuator provides built-in endpoints that help you monitor and manage your application when it is running in production. It provides information about application health, metrics, environment properties, and thread dumps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9689ef39-7d8f-45c9-adf6-cfe9ec385775', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the role of a header file in C++?', N'Intern', N'Header files contain declarations of functions, classes, and variables that can be shared across multiple source files. By including these files, a programmer can use pre-defined functionality without needing to rewrite it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac430a46-3c89-498c-b67a-cfea026ac447', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why do some systems prefer ''Eventual Consistency'' over strong transaction models?', N'Senior', N'Eventual consistency allows for high availability and low-latency writes because the system does not need to synchronize state across all nodes before acknowledging a write. This is ideal for systems where temporary data divergence is acceptable, such as social media feeds or recommendation engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29917220-1665-4540-912a-cfeafaddf9c8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite handle environment variables and what is the benefit of the ''VITE_'' prefix?', N'Senior', N'Vite exposes environment variables via import.meta.env, but only those prefixed with ''VITE_'' are embedded into the client-side code to prevent accidental leakage of sensitive server-side secrets. This security mechanism ensures that build-time variables are explicitly exposed to the browser runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3c8ea48-1123-4f82-be89-cfebee03eee0', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Mean Time To Recovery'' (MTTR) differ from ''Mean Time Between Failures'' (MTBF) as a reliability metric?', N'Senior', N'MTBF measures the average time elapsed between inherent system failures, reflecting the reliability of the components themselves. MTTR measures how quickly a system can be restored after a failure occurs, focusing on operational efficiency, monitoring effectiveness, and recovery automation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54d82882-7f60-48a8-a4a9-cfed8f4eaa3d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s automatic request serialization improve throughput?', N'Middle', N'Fastify serializes outgoing JSON responses using a fast, pre-compiled schema-based approach rather than the standard JSON.stringify method. This reduces CPU overhead per request, allowing the server to handle a higher number of concurrent connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89e354fb-fb5f-46fa-945c-cfee1ecfbad4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the primary performance implications of using Fasthttp as the underlying engine for Fiber?', N'Senior', N'Fasthttp achieves high throughput by using a zero-allocation buffer pool for request and response contexts, which significantly reduces GC pressure. However, this approach sacrifices full compliance with certain edge cases of the HTTP/1.1 specification and makes the framework incompatible with standard net/http middleware ecosystems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b343864b-446d-467d-a921-cfee4d212c96', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of Hono''s approach to type-safety in route parameters?', N'Senior', N'Hono uses TypeScript generics to infer route parameters and query types directly from the URL pattern. This eliminates runtime errors caused by missing or incorrectly typed parameters, providing a superior developer experience and reducing the risk of production runtime failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e885d304-969a-4ea8-99c0-cfeea97ff73e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the splitProps function?', N'Intern', N'The splitProps function is used to divide a props object into multiple smaller objects. This is useful for separating different types of props, such as passing some to a child and keeping others for the current component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'566554a0-8f5f-4589-97f9-cfef52872b36', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does reflection in Go impact performance and why is it often avoided in hot paths?', N'Senior', N'Reflection requires runtime type inspection and dynamic memory allocation, bypassing compile-time type safety and optimizations. Accessing data via the reflect package is orders of magnitude slower than direct access, making it unsuitable for performance-critical code paths or high-frequency request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
