INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'befb99c7-2f1f-4aa7-9978-cff2ec85b1c8', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a friend function?', N'Intern', N'A friend function is a non-member function that is given special access to the private and protected members of a class. It is declared inside the class using the friend keyword, allowing it to interact with the class internals without being a member itself. This is useful for certain operations that need access to private data but do not fit logically as a member function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
