INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0754dbe2-109f-43e8-9d06-d01bddc83446', N'4c000000-0000-0000-0000-000000000005', N'Why would you implement a message queue in a system architecture?', N'Middle', N'Message queues enable asynchronous communication between microservices, allowing them to decouple processing from request handling. This improves system resilience by buffering spikes in traffic and ensuring that tasks can be retried if a downstream service is temporarily unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
