INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76d4a980-f713-43e2-b193-d01cf4b826b8', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle database connection pooling in an Express application to ensure stability?', N'Senior', N'Database connections should be initialized once at application startup and shared across route handlers via a singleton pattern or dependency injection. Creating a new connection for every request is extremely expensive and will quickly exhaust the database''s connection limit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f17bada3-eb71-4e29-aa67-d01d0284ddf2', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the architectural purpose of the ''pub'' package manager in the Dart ecosystem?', N'Senior', N'Pub handles dependency resolution, versioning, and package distribution. It ensures that transitive dependencies are resolved correctly using a dependency graph, which helps prevent version conflicts and provides a consistent build environment across development and production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1756bb56-17f9-4fd7-875e-d022c63fe51c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Discuss the performance trade-offs of thread pooling in MySQL.', N'Senior', N'Thread pooling limits the number of active threads to reduce context switching overhead under high connection counts. While it stabilizes performance during connection spikes, it can introduce latency if the pool is undersized or if long-running queries starve the pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9299f815-8911-40ee-9d63-d024d309c7f0', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is cache poisoning and how is it prevented?', N'Middle', N'Cache poisoning occurs when malicious or incorrect data is injected into the cache, causing the application to serve invalid content to users. It is prevented by sanitizing inputs, using secure validation logic before caching, and ensuring that cache keys are properly scoped to the user or context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07c44a87-421a-4bc6-a3d8-d027b59699d5', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony’s Messenger component facilitate asynchronous processing and handle failures?', N'Senior', N'Messenger decouples the dispatching of a message from its execution by utilizing a transport layer like RabbitMQ or Amazon SQS. It handles failures through retry strategies and dead-letter queues, ensuring that background tasks are processed reliably without blocking the main request thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdc063db-37bc-4a30-a833-d02973c4a73e', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you handle 404 and 405 errors in a Chi-based application?', N'Middle', N'Chi allows you to explicitly define custom NotFound and MethodNotAllowed handlers on the router instance. This gives developers the ability to return consistent error responses in JSON or other formats instead of default browser text.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9bf1a8b-467f-4dab-967e-d02ab347415f', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the parent selector (&) used for in Sass?', N'Junior', N'The parent selector (&) refers to the current parent element within a nested block. It is commonly used for creating hover states, focus states, or applying styles based on a parent class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3be33160-34dd-44dc-b776-d02b97f4cdf1', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Incremental Static Regeneration?', N'Intern', N'Incremental Static Regeneration allows you to update static pages after you have built your site. It enables you to regenerate specific pages in the background as traffic comes in, ensuring content stays fresh without rebuilding the entire site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b11ebf6-3a36-40a2-8eb2-d02ba3e5dd98', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of ''composer.json'' in a Symfony project?', N'Junior', N'The composer.json file lists all the third-party dependencies required by the application. It is used by the Composer package manager to install, update, and manage the versions of libraries needed for the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c9b5a56-8546-43a6-abad-d02e9eeed652', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo respond with different data formats?', N'Intern', N'Echo provides helper methods to send responses in various formats, such as JSON, XML, or plain text. The framework automatically sets the appropriate Content-Type header based on the method used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33372fd4-8fe0-4da8-94af-d032e651a556', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What’s the difference between @injectable() and @inject() decorators?', N'Fresher', N'@Injectable(): This decorator marks a class as a provider that can be managed by the NestJS dependency injection system. It means that NestJS will create an instance of this class and can inject it where it''s needed. It''s typically used on services, which can then be injected into controllers or other services. @Inject():This decorator is used inside a class to inject a dependency. It''s used in the constructor of a class to specify a dependency that should be injected. If you''re injecting a class provider, you don''t need to use @Inject() because TypeScript''s reflection system can infer the type. But if you''re injecting a non-class provider (like a value or a factory), or if you''re working in JavaScript, you need to use @Inject() to tell NestJS what to inject.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3fcd79d-c3cd-49ff-823d-d03331cb6734', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Eloquent ORM in Laravel?', N'Intern', N'Eloquent ORM is a fast and flexible way to query databases using Laravel models. It simplifies many common tasks such as establishing database relationships and performing CRUD operations. In Eloquent, each database table has a corresponding "Model" which is used to interact with that table. Models and relationships in Eloquent allow for common database tasks without requiring direct SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
