INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'700872d3-edd3-4fa4-8e0e-d039943d1590', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the architectural advantages of using Hono in a micro-frontend or federated architecture?', N'Senior', N'Hono''s small footprint and platform-agnostic nature make it ideal for ''edge-side'' composition where routing and data fetching occur closest to the user. It can seamlessly act as an orchestration layer that mediates between disparate micro-services while maintaining the performance overhead of a native edge primitive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
