INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2328354c-897f-4a92-8c94-d040293ec608', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide between using a monolithic architecture and a microservices architecture for a new system?', N'Senior', N'Evaluate the organizational structure, team size, and deployment velocity requirements. Monoliths offer simplicity and lower operational overhead for early-stage startups, while microservices provide independent scalability and fault isolation at the cost of significant infrastructure complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c77294b-0e4a-4c8f-b4e9-d040cf546178', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the concept of ''Hydration Mismatch'' and how to mitigate it in Nuxt.', N'Senior', N'Hydration mismatch occurs when the server-rendered HTML does not match the initial client-side virtual DOM tree. It is typically mitigated by ensuring consistent data fetching, avoiding non-deterministic server-side logic like random number generation, and using the ''ClientOnly'' component for elements that rely exclusively on browser-specific APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
