INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92b487c0-b605-496d-bd9c-d041dfdf7fd9', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the significance of the .astro file format?', N'Middle', N'The .astro format is a component-syntax file that strictly separates the frontmatter (TypeScript code) from the HTML template. This separation makes it easier to manage data fetching logic separately from the component''s UI structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83f47043-0dcb-427e-b8b4-d043652321f2', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the difference between Quarkus''s ''Build Time'' and ''Runtime'' processing and why it benefits performance.', N'Middle', N'Quarkus performs dependency injection wiring, annotation processing, and dead-code elimination during the build phase rather than at application startup. By moving this overhead to build time, the application achieves a significantly smaller memory footprint and faster startup times, which is critical for serverless and containerized environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd103003-5185-4a40-b2a6-d047caf330d8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is ES6', N'Intern', N'ES6 is the sixth edition of the javascript language and it was released in June 2015. It was initially known as ECMAScript 6 (ES6) and later renamed to ECMAScript 2015. Almost all the modern browsers support ES6 but for the old browsers there are many transpilers, like Babel.js etc.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
