INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e60680b5-25d9-49d1-8460-d049038bc057', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''apply'' and ''let'' scope functions?', N'Junior', N'The ''apply'' function returns the object itself after executing the block, making it useful for object configuration. The ''let'' function returns the result of the block, and it is commonly used for null checks and transforming variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccb06cce-8e86-4bcc-b293-d04b906c391b', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do Litestar''s ''Guards'' contribute to a secure-by-default architecture?', N'Senior', N'Guards provide a declarative, composable way to enforce authorization policies before a request reaches the handler, ensuring that unauthorized access is rejected early in the pipeline. By centralizing security logic, they prevent common vulnerabilities such as missing authorization checks on newly added endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8870cd1c-3f38-4aa7-8101-d04f315aa2bb', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you define a redirect in SvelteKit?', N'Junior', N'You can use the ''redirect'' helper function provided by SvelteKit within your load functions or form actions. This allows you to programmatically send a user to a different URL based on specific conditions, such as unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8bddb1f-8ee4-497e-b04c-d04fbdb790c7', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the CAP theorem and its implications for choosing a database.', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the presence of a network partition, an architect must choose between consistency (refusing requests to ensure accuracy) or availability (serving potentially stale data).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd93ce846-544e-4fb4-953a-d04fccd23a19', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''decorate'' API, and what are the risks of overusing it?', N'Senior', N'The decorate API allows developers to attach custom properties or methods to the Fastify instance, request, or reply objects. Overusing it can lead to tight coupling and make the codebase harder to maintain, as it creates implicit dependencies that are not easily tracked by static analysis tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4d949fc-2481-47b5-9772-d04ff0f27c5e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the difference between ''createEffect'' and ''createRenderEffect''?', N'Middle', N'createEffect is intended for side effects that occur after the DOM has been updated, ensuring a clean separation of concerns. createRenderEffect is designed for cases where you need to perform actions during the DOM update process itself, though it is used much less frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff785570-a875-4752-8ea1-d050ccf1864b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why use a framework instead of the Go standard library?', N'Fresher', N'While the standard library is powerful, a framework like Echo provides pre-built solutions for common tasks like routing, middleware, and data binding. This saves development time and promotes consistent coding patterns across a team.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dbe69f0-a181-4a6f-b286-d052a4ae0b7d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the meaning of ''inline'' in C++?', N'Intern', N'The ''inline'' keyword serves as a hint to the compiler to replace the function call with the actual code of the function body. This can reduce the overhead of function calls, though the compiler may ignore the request if the function is too complex.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6afe4b7-787b-43ef-b561-d052d25bde96', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is it recommended to disable Transparent Huge Pages (THP) on Linux when running Redis?', N'Senior', N'THP can cause significant latency spikes during the Redis fork process used for RDB snapshots or AOF rewriting. When the kernel performs a copy-on-write operation on a huge page, it must copy a large amount of memory, which stalls the Redis process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be8941f0-7066-4d16-a69d-d059aba2a7a3', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What does the ''make'' built-in function do?', N'Fresher', N'The make function is used to initialize slices, maps, and channels. It allocates and initializes the underlying data structures for these types, which cannot be used until they are properly initialized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
