INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b823e922-d7c5-4be4-bae8-d06eae6f8f87', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the role of the ''asyncio'' event loop in Python''s concurrency model?', N'Senior', N'The event loop is the central executor that manages non-blocking I/O operations and schedules tasks. It allows a single thread to switch between multiple coroutines when they are waiting for I/O, effectively enabling high-concurrency performance without the overhead of thread context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
