INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4eec1aff-b2ac-4327-a706-d07123e150e3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary role of a GenServer in a Phoenix application?', N'Junior', N'A GenServer is a behavior module used to implement client-server relationships, encapsulating state and providing a synchronous or asynchronous interface for interacting with that state. In Phoenix, it is commonly used to manage background tasks, maintain shared data, or interface with external resources that require a persistent connection. It simplifies the process of creating concurrent, fault-tolerant processes within the Erlang VM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
