INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee6641bf-6446-4c17-9719-d07599671bc2', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle the potential race condition between user input and background code fetching?', N'Senior', N'Qwik uses a pre-fetching strategy that starts downloading the associated QRL chunks as soon as the user interacts with an element. While there might be a minor delay, the framework prioritizes the execution of the requested handler, and the browser''s high-speed network stack typically resolves the chunk before the logic execution becomes a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da86d639-d30d-40fe-b52c-d0759e2f0c4f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you decide between fixing a symptom versus fixing the root cause?', N'Intern', N'Fixing a symptom provides a temporary patch that may allow the system to function briefly, but the underlying issue will likely recur. A root cause analysis focuses on identifying the source of the error to implement a permanent solution that prevents future occurrences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b11cb83b-2a7c-4acf-975f-d07671868008', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Discuss the pros and cons of using Django Rest Framework (DRF) versus a lightweight alternative.', N'Senior', N'DRF is a comprehensive, feature-rich toolkit that handles serialization, authentication, and documentation out of the box, but it is heavy and can introduce significant performance bottlenecks. Lightweight alternatives offer better raw performance and smaller dependency chains but require the developer to manually implement many standard API features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e28cb1b7-ef90-444f-aa21-d07b96516b79', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is a functional component?', N'Intern', N'A functional component is a plain JavaScript function that accepts props as an argument and returns a description of the UI. They are the preferred way to write components in modern Preact because they are simpler, easier to test, and encourage cleaner code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4628b56-7219-48d9-b47c-d07d3677ada3', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between synchronous and asynchronous programming in ASP.NET Core?', N'Intern', N'Synchronous programming blocks the execution thread while waiting for an operation to finish, which can reduce application scalability. Asynchronous programming releases the thread back to the pool while waiting, allowing the server to handle more concurrent requests efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e3d8ae5-4cb7-4dea-bd15-d07ef6fbfd05', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the impact of ''Object.freeze'' or ''Object.seal'' on engine optimization.', N'Senior', N'Making an object immutable allows the engine to make stronger assumptions about the object''s stability, potentially allowing for better inline caching and optimization. However, constant attempts to modify frozen objects can lead to performance overhead in strict mode due to the resulting type errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
