INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'311d184d-02db-4798-b2c7-d0a342c1e828', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the difference between client-side and server-side rendering, and when would you choose one over the other?', N'Intern', N'Server-side rendering generates pages on the server and sends them to the browser, which is beneficial for search engine optimization and initial load times. Client-side rendering builds the page in the browser, providing a smoother, app-like experience after the initial load by offloading processing from the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
