INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c984bc65-94f8-4bda-81f8-d0adb69e6a15', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the ''balancer'' in a sharded cluster?', N'Middle', N'The balancer is a background process that monitors the distribution of data chunks across shards. If it detects an imbalance, it migrates chunks from shards with high data volume to shards with lower volume to ensure even resource utilization and query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07467c25-bd9d-4a87-acd6-d0b01d0f15e2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why would you choose to use a ''Task'' over a ''GenServer'' for concurrent operations in Phoenix?', N'Senior', N'Tasks are designed for one-off, fire-and-forget, or awaitable background computations, whereas GenServers are intended for long-running processes that maintain state. Using a Task is more lightweight and idiomatic for simple parallel operations that do not require continuous management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1a8855e-d4ed-4bf9-a6a9-d0b0ea54872d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How are relationships handled in NoSQL?', N'Fresher', N'Relationships in NoSQL are typically handled through embedding or referencing. Embedding places related data inside a single document, while referencing stores a pointer or ID in one document to link to another.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50392b51-19d9-4ae6-ab33-d0b439d5ee31', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify manage ''decorators'' and why are they preferred over monkey-patching?', N'Middle', N'Decorators provide a safe way to extend the Fastify server, request, and reply objects. Unlike monkey-patching, which is prone to naming collisions and hard to debug, decorators are managed by the framework and ensure consistency across the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcc4e859-56bc-4433-8043-d0b5036e3fd9', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the relationship between Chi''s router and the standard library ''ServeMux''?', N'Middle', N'Chi acts as a sophisticated wrapper around the standard library. While ServeMux is a basic multiplexer for mapping paths to handlers, Chi enhances this with advanced pattern matching, middleware capabilities, and a cleaner API for defining RESTful routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00db6f94-5914-40f2-84d4-d0b71c76a547', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''loading.js'' file?', N'Intern', N'The loading file is a special Next.js convention used to show a loading UI while a page or component is fetching data. It automatically wraps the page content in a React Suspense boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b0c5936-668d-479e-89ea-d0baba552956', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why is it important to use Spring''s @Async annotation carefully in a production environment?', N'Senior', N'The @Async annotation uses a default task executor, which can lead to memory exhaustion if the task volume exceeds the queue capacity. You must always configure a custom TaskExecutor with defined thread pool sizes and rejection policies to maintain system stability under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80f4d294-7461-4dc2-ac8e-d0bb780b5f46', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle WebSocket connections differently than standard HTTP?', N'Middle', N'Fiber provides a specialized upgrade mechanism that transitions an HTTP connection into a WebSocket connection. It integrates directly with the event loop, allowing for efficient, non-blocking communication that benefits from the same underlying performance optimizations as the HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61f5e59f-0a4c-41d3-ac90-d0bb82c02b9e', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural purpose of mutual TLS (mTLS) in a microservices environment?', N'Middle', N'mTLS ensures that both the client and the server authenticate each other using digital certificates, providing strong identity verification. This prevents man-in-the-middle attacks and ensures that only authorized services can communicate within the internal network.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7cd8212-f381-4b73-b2da-d0bbef1ae663', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check whether a string contains a substring', N'Fresher', N'There are 3 possible ways to check whether a string contains a substring or not, 1. Using includes: ES6 provided String.prototype.includes method to test a string contains a substring 2. Using indexOf: In an ES5 or older environment, you can use String.prototype.indexOf which returns the index of a substring. If the index value is not equal to -1 then it means the substring exists in the main string. 3. Using RegEx: The advanced solution is using Regular expression''s test method(RegExp.test), which allows for testing for against regular expressions', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a7ad9b9-5617-4271-a6a9-d0bf6c403c97', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the function of the app.vue file?', N'Intern', N'The app.vue file serves as the main entry point for a Nuxt application. It is the root component that wraps your entire project and is used for global layouts or shared configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77976a4a-f332-4455-9ec0-d0c0b2f40ae4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does the Phoenix Presence module leverage CRDTs to maintain distributed state consistency across a cluster without a centralized bottleneck?', N'Senior', N'Phoenix Presence utilizes Conflict-free Replicated Data Types (CRDTs) to allow each node in a cluster to maintain a local, eventually consistent view of user state. When state changes occur, updates are propagated via gossip protocols to other nodes, ensuring that concurrent operations can be merged deterministically without requiring a global lock or a single source of truth. This design ensures high availability and low latency, as state synchronization happens asynchronously in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76fbcf35-cea6-4ed9-9046-d0c1176c9256', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Discuss the impact of network latency on distributed cache clusters.', N'Senior', N'In distributed caches, network latency often becomes the bottleneck compared to the local memory access time. Architects must account for serialization/deserialization costs and cross-rack bandwidth, sometimes opting for localized caches to minimize these network-related overheads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c29f765-56da-44de-bdc6-d0c455711b92', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why is FastAPI considered faster than some other Python frameworks?', N'Junior', N'FastAPI is built on Starlette for web handling and Pydantic for data validation, both of which are highly optimized. Its asynchronous design allows it to handle many concurrent connections efficiently, making it one of the fastest Python frameworks available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
