INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0adff1f5-47cb-444d-b898-d0cf29e8f2f6', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'When should you consider moving from a relational database to a NoSQL solution?', N'Middle', N'NoSQL is generally preferred when you have massive amounts of unstructured data, require flexible schemas, or need horizontal scaling that is difficult to achieve with relational systems. It is also useful when low latency and high availability are prioritized over strict ACID compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6812d5d0-872a-4027-a75b-d0d02ab4191a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Describe the Svelte strategy for handling event forwarding.', N'Senior', N'Svelte simplifies event handling by allowing components to forward events up the tree using a declarative syntax. The compiler ensures that these events are properly bubbled, reducing the amount of boilerplate code needed to pass events through multiple layers of components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
