INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60c26e09-2092-459a-aec0-d0d1d8397088', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Why is it generally preferred to use ''rem'' units over ''px'' for font sizing?', N'Middle', N'Using ''rem'' units ensures that font sizes are relative to the root element''s font size, which improves accessibility for users who have customized their browser''s default font size. Pixels are absolute units that do not scale automatically, potentially breaking the layout or making text unreadable for users with visual impairments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc5c417e-6556-4a3c-b20e-d0d1f917d531', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the impact of microservices on the ''testing pyramid''?', N'Senior', N'Microservices shift the focus toward consumer-driven contract testing to ensure that API changes do not break downstream dependencies. While unit tests remain important, integration and end-to-end tests become more complex, requiring robust mocking and environment virtualization to isolate services during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
