INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'335d2d23-4b06-4c7a-b4e0-d0d76f7f8d06', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the difference between Symfony''s ''Request'' and ''Session'' objects in terms of state management.', N'Senior', N'The Request object represents stateless data incoming from a single HTTP call, whereas the Session object provides a mechanism to persist state across multiple requests. Relying heavily on the Session can hinder horizontal scalability unless externalized into a shared store like Redis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a7aaf26-224e-4df4-b0e1-d0d7f44fc39f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is an Exception Filter in NestJS?', N'Intern', N'Exception filters are responsible for catching unhandled exceptions that occur anywhere in the application. They allow you to control the exact flow of the response sent back to the user when an error occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89556ccb-ed4a-479e-ad9f-d0db1371ca12', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why is it important to use ''Dispatcher.IO'' for network or disk operations?', N'Middle', N'The IO dispatcher is specifically designed to offload blocking tasks to a shared pool of threads that can expand or shrink as needed. This prevents the main thread from being blocked, ensuring the application remains responsive during heavy input/output operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0fc5962-87a4-42e5-89c7-d0de64393e57', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the @Introspected annotation?', N'Fresher', N'@Introspected tells the Micronaut compiler to generate bean introspection data at compile-time. This allows the framework to access bean properties without using runtime reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc3bc414-f3ea-471f-a27b-d0e035552d95', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an API, why is it important to consider versioning from the start?', N'Intern', N'Versioning prevents breaking changes for existing clients when you need to update the API''s functionality. By including version information in the request path or headers, you allow new features to be introduced while maintaining backward compatibility for older integrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfc3665f-27b3-4ced-bde5-d0e1cfd52c29', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the primary purpose of a database view?', N'Middle', N'A view acts as a virtual table that presents a subset or a transformation of data from one or more underlying tables. It simplifies complex queries for users, provides an abstraction layer to hide sensitive data, and maintains a consistent interface if the underlying schema changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5189b1f1-aaa5-4c68-bad1-d0e35ace3973', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does ''sideEffects'' in package.json affect Webpack''s tree shaking?', N'Middle', N'The sideEffects flag allows you to signal to Webpack whether a package contains code with side effects, such as modifying global variables or attaching prototypes. If a package is marked as having no side effects, Webpack can safely prune unused exports even if they are imported elsewhere, enhancing tree-shaking efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92802715-8075-4d8e-a2c0-d0e62514fbeb', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Doctrine ORM in Symfony?', N'Intern', N'Doctrine is an Object-Relational Mapper that acts as an abstraction layer between the application and the database. It allows developers to interact with database tables using PHP objects instead of writing raw SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7ef0744-de82-4afb-a92d-d0e9690a8532', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle CORS?', N'Intern', N'Gin does not have built-in CORS support by default, but it is typically implemented using middleware. You create a function that adds the necessary headers, such as ''Access-Control-Allow-Origin'', to the response before the request reaches the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'872feb73-4ab3-4c1d-be01-d0e9ace034db', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s Form component handle data validation?', N'Middle', N'The Form component integrates with the Validator component to automatically apply constraints defined on object properties or through configuration. It manages the flow of data binding, transformation, and validation errors, ensuring that the input is sanitized and conforms to expected business rules before being processed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3522ede2-9f1d-4c95-b306-d0e9f506ebce', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is a static class?', N'Junior', N'A static class cannot be instantiated, and all of its members must be static. It is commonly used as a container for utility methods or constants that do not require state associated with a specific object instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66953433-b617-400b-a531-d0ebec7dccb1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is sharding in NoSQL databases?', N'Junior', N'Sharding is the process of splitting a large dataset into smaller chunks and distributing those chunks across multiple servers. This technique allows a database to handle larger datasets and higher throughput by sharing the workload across a cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b831a66f-17d8-4bad-97d0-d0ec43f4d44f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the benefits of using Preact for mobile-first or low-bandwidth web applications?', N'Middle', N'The primary benefit is the significantly smaller JavaScript payload, which leads to faster download and parse times on mobile devices. This directly improves Time to Interactive and First Contentful Paint metrics, which are critical for performance in low-bandwidth environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee4ce524-77a2-4876-8496-d0edf1623342', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do NoSQL databases typically handle ACID properties compared to RDBMS?', N'Middle', N'Many NoSQL databases prioritize availability and partition tolerance over strict ACID compliance, often adopting the BASE model (Basically Available, Soft state, Eventual consistency). While some NoSQL systems offer multi-document transactions, they often trade off performance or global consistency to maintain scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c824431-b576-489d-87ae-d0f035dc7d36', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between ''std::vector'' and ''std::array''?', N'Junior', N'std::vector is a dynamic array that can resize itself at runtime, while std::array has a fixed size determined at compile time. std::vector manages memory on the heap, whereas std::array stores elements on the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3745c7c-0735-4770-be8a-d0f2e66dd590', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime handle panic and recovery across goroutine boundaries?', N'Senior', N'Panic and recovery are local to the individual goroutine and cannot be propagated across goroutine boundaries. If a panic is not recovered within the goroutine where it originated, the entire process terminates. This design enforces strict isolation, requiring programmers to handle errors explicitly within the scope of execution or use alternative mechanisms like channels to report failure states to parent routines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09521ef7-a838-4be0-b42b-d0f388eac9b0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle large-scale aggregations?', N'Middle', N'Elasticsearch performs aggregations by building a global view of the data across all shards and merging the results. For large datasets, this can be memory-intensive, so the system uses global ordinals and specific data structures like doc values to keep memory usage predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf3d3a81-6e88-42dc-8fbb-d0f8a0cb347a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of a Memtable in Cassandra?', N'Intern', N'A Memtable is an in-memory data structure where Cassandra stores writes before they are flushed to disk. Once the Memtable reaches a certain size, its contents are written to an SSTable on disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72f6678b-489d-435b-8420-d0fa89a824b1', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is Redux in the context of frontend development?', N'Intern', N'Redux is a predictable state container designed for JavaScript applications. It helps developers manage the global state of an application in a centralized location, making the data flow easier to understand and debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fe1676c-d463-4ea4-b66c-d0fa97e90356', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are the advantages of using Ecto.Multi for database transactions?', N'Middle', N'Ecto.Multi allows you to group multiple database operations into a single atomic transaction. It provides a structured way to handle complex workflows where each step depends on the success of the previous one, ensuring that if any operation fails, the entire batch is rolled back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b82173c-8d7c-411d-825f-d0fccdef273e', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s approach to error handling differ from frameworks that use global error handlers?', N'Middle', N'Chi encourages handling errors within the scope of the handler or through specific middleware that inspects the response status. Unlike some frameworks that force a global error-handling structure, Chi keeps error management flexible and closer to the standard Go pattern of returning errors as values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f71feb74-fd54-4a4c-8c8f-d0fd7646a426', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''volatile'' keyword in C#?', N'Middle', N'Volatile ensures that a field is read from and written to main memory rather than a CPU cache, preventing stale data. It is primarily used in multi-threaded scenarios to ensure that the most up-to-date value is always accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23b06cdc-cd4e-44ef-b74f-d100e7261c2b', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the primary difference between a struct and a class in C# regarding memory allocation?', N'Middle', N'A class is a reference type allocated on the managed heap, while a struct is a value type typically allocated on the stack or inline within a containing type. This distinction impacts performance because value types are cleaned up automatically when they go out of scope, whereas reference types rely on the garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36b8336d-3bc3-44db-8fbe-d1011a41bcd9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the function of the Recovery middleware in Gin?', N'Fresher', N'The Recovery middleware is a built-in feature that catches any panics that occur during the execution of a request. It prevents the entire server from crashing and allows for a standardized internal server error response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f550973-46ff-4ab6-aebc-d101765c1f25', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the significance of the ''suspend'' modifier in coroutines?', N'Middle', N'The ''suspend'' modifier marks a function as capable of pausing its execution without blocking the underlying thread. When the function reaches a suspension point, it yields control back to the coroutine dispatcher, allowing the thread to perform other work until the suspended operation completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a028c777-e246-45e1-860e-d10234003fcc', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the trade-off between cache granularity and cache hit ratios.', N'Senior', N'Fine-grained caching allows for more precise invalidation and better utilization of memory, but it increases the complexity of managing dependencies. Coarse-grained caching, such as caching entire pages, simplifies invalidation but leads to lower hit ratios if only small portions of the data change frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'915a653d-e954-4eb4-8da2-d1047f1675ab', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Scope Chain'' lookup process work in nested function environments?', N'Senior', N'The scope chain is a linked list of variable objects created during function execution. Each step up the chain involves a lookup in the lexical environment, which is cached by the engine to speed up access to outer scope variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
