INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc673394-15c0-4776-a913-d136ebf50e62', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s value class (inline class) improve performance in domain-driven design?', N'Senior', N'Value classes allow developers to wrap primitive types with type-safe domain semantics without the overhead of additional object allocations. By inlining the underlying value at the call site, the compiler eliminates the heap allocation and pointer indirection, providing the performance of primitives with the safety of specialized types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48ec135c-693b-4d8e-bf55-d1387ac52c91', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact achieve a smaller bundle size compared to React, and what are the architectural trade-offs involved?', N'Middle', N'Preact achieves a smaller footprint by omitting features like synthetic event systems, internal prop-type validation, and extensive legacy support, instead relying on standard browser APIs. The trade-off is that it does not provide the same level of abstraction or out-of-the-box compatibility with the entire React ecosystem, requiring a compatibility layer for certain complex libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'232c2857-0bf8-469c-9f70-d139eff33dcf', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the scalability considerations when running FastAPI with multiple worker processes?', N'Senior', N'When running under a process manager like Gunicorn with Uvicorn workers, state should be managed externally via tools like Redis or a database. Since workers share no memory, any internal caching or local state will not be synchronized across processes, necessitating a stateless application design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
