INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3a0ee5f-75d0-47e5-a9cc-d14025970c62', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the $(document).ready() method?', N'Junior', N'This method ensures that the DOM is fully loaded and ready to be manipulated before any jQuery code executes. It prevents errors that would occur if you tried to select or modify HTML elements that have not yet been rendered in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad3e700c-82b0-4d6d-a614-d14446ac8c4a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the advantages of using Option in Scala?', N'Senior', N'In Scala, Option is a powerful tool that offers clear benefits throughout the development process. Core Advantages of Using Option 1. Robust Error Handling: It provides a structured approach for situations where a method might not return a valid value, thereby reducing the chances of null-pointer exceptions. 2. Distinct Semantics: By explicitly differentiating between a valid result (Some) and the absence of one (None), it promotes logical clarity and aids in code comprehension. 3. Forced Consideration: The Some and None constructs compel developers to actively assess potential absence or presence of a value, which leads to a *more mindful* coding practice. 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
