INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03dacdf4-de32-4b27-ad04-d14f65624436', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why do segment merges happen in Elasticsearch, and what are the associated trade-offs?', N'Senior', N'Segment merges are background processes that combine smaller segments into larger ones to reclaim space and optimize search performance by reducing the number of files the engine must query. While necessary for efficiency, they are I/O intensive and can significantly impact indexing performance if not managed or throttled correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
