INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c6e56ec-fe6d-401c-b5ae-d19707bde757', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does ''echo'' do in PHP?', N'Intern', N'The echo command is a language construct used to output one or more strings to the screen. It is the most common way to display content generated by PHP to the user''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c284dff6-6fcc-42bc-8f81-d19dd167a66c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the significance of the zero value in Go?', N'Middle', N'In Go, every variable is automatically initialized to its zero value upon declaration. This design choice eliminates uninitialized memory bugs and simplifies code by ensuring that variables are always in a predictable, ready-to-use state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4420d089-65a2-417e-b1c8-d19ea8536f0d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is meant by the term ''static typing'' in TypeScript?', N'Intern', N'Static typing means that variable types are checked during development before the code is executed. This prevents accidental type mismatches, such as trying to perform arithmetic on a string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a301df4-c3d9-451a-89d2-d1a0fbb79225', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of ''Database Normalization'' beyond just removing redundancy?', N'Senior', N'Normalization enforces data integrity by ensuring that each fact is stored in exactly one place, which simplifies maintenance and prevents partial update errors. It also helps in identifying the natural relationships between entities, leading to a more robust and logical database schema design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82ae24f5-e226-4e9c-a473-d1a2b726f02a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle file uploads?', N'Fresher', N'AdonisJS provides a built-in file upload handler that processes incoming multipart form data. It allows developers to specify validation rules for file size, extension, and type to ensure security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44e363c5-da4c-4f05-be12-d1a2e8bae2d9', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are parameter defaults?', N'Fresher', N'Parameter defaults allow you to assign a default value to a function parameter. If the caller does not provide an argument for that parameter, the default value is used, which reduces the need for function overloading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad7a9ca5-f0e9-4c5d-b931-d1b313f05c12', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you troubleshoot a cascading failure in a microservices architecture?', N'Middle', N'I would first identify the primary service that started failing and analyze its dependencies to see if the failure spread due to lack of circuit breakers or timeouts. I would then check for resource exhaustion, such as thread pool saturation or connection pool depletion, caused by retries. The solution typically involves implementing backpressure, rate limiting, and graceful degradation patterns to isolate the impacted service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c63b2e1-f1af-4b1a-a236-d1b433e8cd11', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''onClose'' hook used for?', N'Fresher', N'The onClose hook is triggered when the Fastify server instance is closing. It is primarily used to perform cleanup tasks, such as closing database connections or stopping background workers, ensuring a graceful shutdown.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25489cc6-8264-4eae-91d4-d1b72a78cd57', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web manage connection concurrency compared to a standard threaded web server?', N'Senior', N'Actix-web utilizes an asynchronous event loop based on Tokio, allowing it to handle thousands of concurrent connections with a small, fixed number of threads. This avoids the high memory overhead and context switching costs associated with spawning a new thread for every incoming connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17d1be22-a560-4f0f-bf08-d1b98c97a572', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does NoSQL handle data redundancy?', N'Intern', N'NoSQL databases often handle redundancy through replication, where data is copied across multiple nodes in a cluster. This ensures that the system remains operational even if one of the nodes fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b02a60e-baaa-4a36-b23c-d1b9e66cb3a0', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a signature model in Litestar?', N'Fresher', N'A signature model is an internal component that Litestar generates for each route handler to inspect its parameters and return types. This allows the framework to validate inputs and serialize outputs correctly based on the type annotations provided by the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'188b3911-7a31-4615-9fbe-d1bd89ae3289', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik solve the ''double-download'' problem common in traditional SSR frameworks?', N'Senior', N'Qwik eliminates the double-download by removing the need for hydration. In traditional frameworks, the browser downloads the HTML and then downloads the JavaScript to rebuild the state; Qwik''s state is already embedded in the HTML, so the second ''rebuilding'' phase is entirely skipped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1332a50-c89f-48aa-b444-d1bd8ebf685d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix improve page load performance?', N'Intern', N'Remix improves performance by fetching all data for a page on the server in parallel before the request is finished. By serving a complete HTML document, it removes the need for multiple ''loading'' states or waterfall requests on the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0eece33-b77b-436e-a112-d1c18de16f18', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When designing a system that requires strict ordering of events, what challenges arise in a distributed environment?', N'Senior', N'Maintaining order is difficult in parallel processing systems; I would use partition-based ordering within a message broker like Kafka to ensure events with the same key are processed by the same consumer instance. This introduces a trade-off between strict ordering and throughput, as it limits the horizontal scaling of individual partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'611e554c-ae81-4b80-87cd-d1c2b6235b5c', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you define custom key modifier aliases?', N'Fresher', N'You can define custom key modifier aliases via the global config.keyCodes. There are few guidelines for the properties 1. You can''t use camelCase. Instead you can use kebab-case with double quotation marks 2. You can define multiple values in an array format', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c0305dc-e1e9-4fae-a99d-d1c3abf5b7a3', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'In a microservices architecture, why might you choose a framework over Express, and what specific gaps does Express have?', N'Senior', N'Express is unopinionated and lacks built-in features for enterprise concerns like strict type safety, dependency injection, and integrated configuration management. Frameworks like NestJS provide a structured architecture that facilitates better modularity, testing, and maintenance, which are critical for large-scale microservice ecosystems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5888fa72-043b-4348-85c2-d1c6f725b34c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Describe the difference between ''Vertical'' and ''Horizontal'' partitioning (sharding) in terms of scalability.', N'Senior', N'Vertical partitioning splits a table by columns, useful for isolating frequently accessed fields or separating large blobs from main data. Horizontal partitioning splits rows across multiple nodes, which is essential for overcoming hardware capacity limits and scaling linearly with data volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd931dd91-061c-497f-8e57-d1ca6694ddf3', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the value of ''triangulation'' in estimation?', N'Intern', N'Triangulation involves using multiple, independent methods to estimate the same value. If the results from different approaches converge on a similar range, it increases confidence in the estimate; if they differ widely, it indicates that the underlying assumptions or models need further investigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fafb4804-286e-4f75-a13c-d1cb2008c129', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the dangers of allowing Express to use ''res.render'' in a high-traffic environment?', N'Senior', N'Server-side rendering in Express is synchronous and CPU-intensive, which blocks the event loop and significantly increases response times. For high-traffic applications, it is preferable to offload UI rendering to a client-side framework or a dedicated rendering service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd088c95-0dd5-4d83-a6d1-d1d16fc66ff4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Why is it discouraged to perform long-running blocking operations directly in a Gin handler?', N'Senior', N'Blocking operations in a handler consume a goroutine and block the event loop flow, potentially leading to goroutine starvation and increased latency for other requests. Long tasks should be offloaded to worker pools or background jobs to ensure the main server remains responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c991b4cb-c0e2-49b2-a595-d1dbfeadd0ea', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary role of Redis as a ''cache''?', N'Fresher', N'As a cache, Redis stores frequently accessed data in memory to reduce the load on the primary backend database. This speeds up application performance by serving requests directly from the fast cache instead of querying the slower main database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77ebba35-c8a8-4f06-bdf1-d1ded03438fe', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s use of the Web Standards API influence its portability compared to traditional Node.js-based frameworks?', N'Middle', N'By leveraging the Request and Response objects defined in the Fetch API, Hono is decoupled from the underlying Node.js runtime. This architecture allows it to run seamlessly on various platforms, including Cloudflare Workers, Deno, Bun, and standard Node.js environments, without requiring platform-specific middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'accac752-6920-4609-872d-d1e0519b1918', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the garbage collector determine when an object is eligible for collection?', N'Middle', N'The garbage collector uses a root-finding algorithm to trace all reachable objects starting from roots like static fields, local variables, and CPU registers. Any object that cannot be reached through this graph of references is considered unreachable and eligible for reclamation. It does not rely on simple reference counting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96a36142-c4a5-4d2a-9b94-d1e12d1d1891', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Partition Key in Cassandra?', N'Intern', N'The partition key is the part of the primary key that determines which node in the cluster will store a specific row of data. It is essential for distributing data evenly across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e013a0d-c3cf-4772-9663-d1e40123d906', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a primary key in MySQL?', N'Intern', N'A primary key is a column or a set of columns that uniquely identifies each row in a table. It must contain unique values and cannot contain null values, ensuring that every record can be referenced individually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5af0c45-9f51-4c5b-be2b-d1e4ae27f5a2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a gossip protocol in Cassandra?', N'Intern', N'The gossip protocol is a peer-to-peer communication mechanism used by nodes to exchange information about the state of the cluster. It allows nodes to discover each other and detect failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5587b4f-fe8f-44de-9da8-d1e4cb80fab1', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a context dictionary in Django?', N'Intern', N'The context is a dictionary that maps template variable names to Python objects. It is passed from the view to the template so that the template can access and display the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6af9003c-c52f-4c65-ba59-d1e7037ee5be', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'In a distributed system, why is it dangerous to rely on goroutine-local state similar to thread-local storage?', N'Senior', N'Goroutines are dynamically scheduled and migrated across OS threads by the runtime, meaning there is no guarantee of execution affinity to a specific thread. Attempting to use thread-local storage leads to race conditions and unpredictable state corruption, as the underlying thread identity is abstracted away.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f25173b-39c0-4148-b3a4-d1e74f56567b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is Tailwind CSS often considered more performant than runtime CSS-in-JS in terms of the Critical Rendering Path?', N'Senior', N'Tailwind produces static CSS that is ready to be parsed as soon as it is fetched by the browser, whereas CSS-in-JS requires the browser to download, parse, and execute JavaScript before styles can be computed. This avoids the ''flash of unstyled content'' and layout shifts associated with the delayed injection of styles by JavaScript frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1e8fd35-833b-4d24-8f38-d1e764880856', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis handle high availability?', N'Middle', N'Redis achieves high availability through Redis Sentinel, a distributed system that monitors master and replica instances. If a master fails, Sentinel performs an automatic failover by promoting a replica to master, ensuring minimal downtime and continuous service availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'892daece-3f7b-4e67-834d-d1e87c8bfad9', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the popular choice for form handling?', N'Intern', N'Formik is a form library for react which provides solutions such as validation, keeping track of the visited fields, and handling form submission. In detail, You can categorize them as follows, 1. Getting values in and out of form state 2. Validation and error messages 3. Handling form submission It is used to create a scalable, performant, form helper with a minimal API to solve annoying stuff.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5230493-3eff-447c-b1de-d1ed7e959f34', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the primary purpose of the Rocket framework in Rust?', N'Junior', N'Rocket is a web framework designed to make it simple to write fast, secure, and type-safe web applications. It leverages Rust''s ownership model and type system to ensure that common web vulnerabilities are caught at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebadeb4e-b500-4f10-bdcd-d1efad3153fd', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are ''client directives'' in Astro?', N'Intern', N'Client directives are attributes used on components to control when and how their JavaScript should be loaded in the browser. For example, they can tell the browser to load a component only when it becomes visible on the screen or when the page has finished loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbf345c0-fcb5-4934-ae0b-d1f01bd2ca23', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How can you implement custom validation in Micronaut?', N'Middle', N'Micronaut integrates with the Bean Validation API (JSR 380) to provide declarative validation. You can define custom constraints using annotations and validators, which the framework automatically invokes during bean lifecycle events or HTTP request handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ea02677-1299-411a-9808-d1f482aa4b3e', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Describe the architectural patterns for handling long-running processes via an API.', N'Senior', N'Long-running tasks should be handled asynchronously using a polling pattern or webhooks. The API returns a 202 Accepted status with a location header pointing to a status resource, allowing the client to periodically check the progress or receive an asynchronous callback once the operation completes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a506d5a2-6952-4e62-8822-d1f5c45d6c9c', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik maintain SEO performance despite its heavy reliance on client-side interactivity?', N'Senior', N'Qwik is fundamentally server-side rendered, meaning the initial HTML contains the full content of the page. Because the framework does not require client-side hydration to show the page, search engine crawlers receive a fully populated document without needing to execute JavaScript, ensuring top-tier SEO performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'558e16b2-2c4e-4f62-804e-d1fe95b6b68d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is a Sass mixin and when should you use one?', N'Junior', N'A mixin is a reusable block of CSS declarations that can be included in other rules. You should use them to avoid repeating complex or repetitive styles across your project, such as vendor prefixes or common layout patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71ed1e4a-1496-4fd3-8bc8-d203a5852fc2', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Describe how to implement graceful shutdown in a Gin-based application and why it is critical for distributed systems.', N'Senior', N'Graceful shutdown is achieved by using the http.Server''s Shutdown method to stop accepting new connections while allowing existing requests to complete. This is vital in distributed systems to prevent data corruption and ensure that load balancers do not receive 5xx errors during deployment rollouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c974af45-a071-4bc5-a7c1-d20591892f32', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is data denormalization and why is it used for scaling?', N'Middle', N'Denormalization involves intentionally adding redundant data to tables to reduce the need for complex joins. It improves read performance and makes queries simpler, which is beneficial when scaling reads in a distributed environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02684a1c-7561-4420-949d-d2083521f247', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go scheduler handle system calls to prevent blocking the entire process?', N'Senior', N'When a goroutine performs a blocking system call, the runtime detaches the OS thread from the processor and creates a new thread to continue executing other goroutines. This ensures that a single blocking I/O operation does not stall the entire application, maintaining high concurrency for other tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
