INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbf429f8-5ba0-486e-8b47-d20a15946fec', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Does Redis support data persistence if the server restarts?', N'Fresher', N'Yes, Redis supports persistence through two main mechanisms: RDB and AOF. RDB takes point-in-time snapshots of the data, while AOF logs every write operation to disk to reconstruct the state upon reboot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
