INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a65976b-3f03-4747-8974-d2193ad00f18', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the main benefit of using Actix-web for a backend developer?', N'Fresher', N'The main benefit is performance. Actix-web consistently ranks as one of the fastest web frameworks due to its efficient asynchronous design and the zero-cost abstractions provided by Rust.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdd5b87c-e30f-4515-8f6e-d21a98aef541', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the types of validator functions?', N'Intern', N'In reactive forms, the validators can be either synchronous or asynchronous functions, 1. Sync validators: These are the synchronous functions which take a control instance and immediately return either a set of validation errors or null. Also, these functions passed as second argument while instantiating the form control. The main use cases are simple checks like whether a field is empty, whether it exceeds a maximum length etc. 2. Async validators: These are the asynchronous functions which take a control instance and return a Promise or Observable that later emits a set of validation errors or null. Also, these functions passed as second argument while instantiating the form control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7267c561-51ca-4e3f-89cd-d21bd43ffc95', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the CAP theorem in the context of NoSQL?', N'Intern', N'The CAP theorem states that a distributed data store can only provide two out of three guarantees: Consistency, Availability, and Partition tolerance. NoSQL databases are usually categorized based on which of these two they prioritize.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d04d42b-52c5-4fc4-9a26-d21c633e450d', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is Static Site Generation (SSG) in Astro?', N'Intern', N'SSG is the process of building your pages into static HTML files during the build process. These files are then served directly to the user, making the site extremely fast and secure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c9f2fd8-772d-4778-86a1-d21c655adc6f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''libuv'' library in the Node.js architecture?', N'Middle', N'Libuv is a multi-platform support library that provides the foundation for Node.js''s asynchronous I/O capabilities. It manages the event loop, thread pool for file system and DNS operations, and low-level system communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e559fba-6093-4784-a5c9-d21e7f30dcab', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the best way to document your work so it is useful for others?', N'Junior', N'I aim for clear, concise comments in the code for complex logic and maintain updated documentation in our shared project wiki. I try to explain the ''why'' behind a decision, which is often more helpful to future maintainers than just the ''what''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c370e5b-3add-4b4c-8b3e-d22106797e69', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why do we use data types in database design?', N'Fresher', N'Data types define the kind of information a column can store, such as integers, text, dates, or boolean values. They are essential because they ensure data validation, optimize storage space, and enable the database to perform appropriate operations on the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd675a3a-e580-4196-969e-d225f78d788d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the impact of excessive Pydantic model nesting on FastAPI performance?', N'Senior', N'Deeply nested Pydantic models increase the overhead of validation and serialization. While usually negligible, in high-frequency endpoints, complex tree structures can lead to increased CPU usage; flattening models or using simpler structures can improve performance in extreme cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1fb9683-8d40-45d7-a76a-d226391ea111', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Why might a write-heavy system prefer a Log-Structured Merge-tree (LSM) over a B-Tree storage engine?', N'Senior', N'LSM trees optimize write performance by converting random writes into sequential disk I/O, which is significantly faster for storage backends. This makes them ideal for high-throughput write workloads, though they require background compaction processes that can affect read latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b39bec26-3887-4ffa-aaa1-d227b0d615af', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does memory usage impact the choice of a data structure?', N'Fresher', N'Some data structures prioritize lookup speed at the cost of high memory consumption, while others are memory-efficient but slower to search. Choosing the right one depends on whether the system is constrained by hardware resources or needs to respond instantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d7a9161-2335-425b-b047-d22d7c0b9d29', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the architectural advantages of Vue''s ''Composable'' pattern over Mixins?', N'Senior', N'Mixins suffer from implicit namespace collisions and opaque data flow, making it difficult to determine the origin of properties. Composables leverage the Composition API to provide explicit inputs and outputs, improving type safety, code readability, and testability through standard JavaScript function composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00581d8b-bfec-4916-bbe6-d22e4a9fc156', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is an R package?', N'Intern', N'An R package is a collection of R functions, compiled code, and sample data. Packages extend the functionality of the base R installation by providing specialized tools for specific tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8472c12-8ebe-4a6e-9ba8-d22eac8f7b03', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you group routes in Echo?', N'Junior', N'Route grouping allows you to organize related endpoints under a common URL prefix. You can also apply specific middleware to an entire group, which keeps the code clean and modular.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a154c178-786d-44a0-8bc3-d230a55c9ffb', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If you suspect a library or third-party tool is causing a bug, how do you verify this?', N'Fresher', N'You can check the documentation for known issues, look at the project''s issue tracker, or try to isolate the library usage in a simplified test setup. If the bug only appears when using the library, the issue is likely within that third-party dependency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18bc3189-c143-4d15-bbe3-d231b8c015ee', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'When should you consider partitioning a table in PostgreSQL?', N'Middle', N'Partitioning is recommended when a single table becomes too large to manage efficiently, leading to performance degradation in maintenance tasks like indexing or vacuuming. It improves query performance by allowing the query planner to skip partitions that do not contain relevant data, a process known as partition pruning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58023f6a-7f3a-4366-95fa-d2337ad177cc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'In what scenarios is ''Type Predicate'' preferred over standard type narrowing?', N'Senior', N'Type predicates are essential when performing narrowing inside a custom function rather than inline. They allow the compiler to understand the type of a variable outside the scope of the function, which is critical for complex validation logic that cannot be expressed via standard control flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab98502d-ddac-4e42-836d-d2337ba5f1b8', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s ''context'' API differ from ''props'' for data sharing?', N'Middle', N'Props are for passing data directly to immediate child components, whereas the context API allows data to be shared across a component tree without ''prop drilling''. Context is scoped to a component and its descendants, making it suitable for dependency injection or theming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3681495b-e2ad-45a4-beed-d2347c88dd23', N'075b8862-431c-4678-9767-f55359758a4a', N'Why is the use of ''shallowRef'' recommended when handling large data structures in Vue 3?', N'Senior', N'ShallowRef bypasses deep reactivity for nested objects, significantly reducing memory overhead and initialization time for large, immutable data sets. It is a performance optimization used when you only need to track top-level changes rather than every nested property mutation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed20ebb1-59d6-480e-a65d-d234e39be015', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the trade-offs between using a work-stealing scheduler versus a cooperative scheduler in high-concurrency systems.', N'Senior', N'A work-stealing scheduler allows idle processors to take tasks from busy processors, optimizing CPU utilization and load balancing across cores. A cooperative scheduler relies on tasks to yield control, which can lead to starvation if a task is CPU-intensive, whereas work-stealing provides better fairness and throughput for heterogeneous workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'405ac974-3877-4635-8a01-d235924486c1', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How does the garbage collector treat objects that are referenced within a closure compared to those in a global scope?', N'Senior', N'Objects in a closure are kept in memory as long as the function scope remains active, preventing them from being garbage collected. Global variables persist for the entire lifetime of the process, which can lead to permanent memory leaks if not carefully managed, whereas closure-based memory is reclaimed once the reference chain is broken.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a665168-ab12-4c01-886b-d23637e099b6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the ''TTL Index'' work in MongoDB?', N'Senior', N'A TTL (Time-To-Live) index automatically removes documents from a collection after a certain amount of time or at a specific clock time. This is highly efficient for managing data like session logs or temporary cache entries without needing manual cleanup scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5ed372c-97e0-48c5-914a-d23821242f81', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis Cluster achieve data distribution?', N'Middle', N'Redis Cluster uses a concept called hash slots to distribute data across multiple nodes. There are 16,384 available slots, and each key is mapped to a slot using a CRC16 algorithm, ensuring even distribution and allowing for easy scaling by moving slots between nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84d96be8-5f92-4f98-b045-d23987a22345', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you enforce rate limiting in a distributed system with multiple API instances?', N'Senior', N'Use a centralized store like Redis to maintain counters for rate limiting across multiple instances. This ensures global consistency for user or API key quotas, though it introduces a network dependency that must be mitigated with local caching or sliding window algorithms to minimize latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'956ed6ca-f80c-41df-b84f-d23b1ff35c05', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the primary differences between filter context and query context in Elasticsearch, and how does each impact performance?', N'Senior', N'Query context calculates a relevance score for each document, while filter context only checks for a binary match. Filter results are frequently cached by Elasticsearch, making them significantly faster and more resource-efficient for non-scoring criteria, whereas queries must always be computed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f290d04-8a38-4304-9434-d23fd72e28e9', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What does Fastify do with the response payload?', N'Intern', N'Fastify serializes the response payload into a string or buffer before sending it to the client. If a schema is defined, it uses a fast serializer to ensure the output strictly follows the structure provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a03ff835-40c5-4c68-8905-d2400401e8a4', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the role of the ''client:*'' directives in Astro?', N'Junior', N'Client directives are used to tell Astro when and how to hydrate an interactive component. Without these directives, a component will render as static HTML, but adding them allows the component to become interactive in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a798f8-93c7-4df1-b6f2-d2403791c7aa', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the impact of jQuery on page load time and bundle size?', N'Middle', N'Including the entire jQuery library adds a significant amount of JavaScript that must be downloaded, parsed, and executed before the page becomes interactive. In modern web development, this often outweighs the utility provided, as the same functionality can be achieved with smaller, native code snippets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b5c1bb3-7a55-43b9-9f67-d240be056476', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is ''strict mode'' in TypeScript?', N'Intern', N'Strict mode is a compiler configuration setting that enables a series of type-checking rules that provide stronger guarantees of program correctness. Enabling it is highly recommended as it forces developers to write more robust and safer code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5c438ec-7ce8-4bc9-95f8-d244f4884233', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What are the trade-offs of using jQuery for AJAX requests compared to the native Fetch API?', N'Middle', N'jQuery''s AJAX module provides a consistent, high-level interface with built-in features like automatic JSON parsing and cross-browser compatibility. However, the Fetch API is now standard, more lightweight, and uses Promises natively, making it better for modern applications that don''t require legacy browser support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
