INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78ca1274-a830-467b-a2f0-d24815f17275', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a Local Secondary Index (LSI) and a Global Secondary Index (GSI)?', N'Fresher', N'An LSI must have the same partition key as the base table but a different sort key, while a GSI can have a completely different partition key and sort key. LSIs are created during table creation, whereas GSIs can be added or removed at any time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffa46464-72cc-47aa-81e2-d248171ab6a8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is ''esbuild'' and what does it do in Vite?', N'Fresher', N'esbuild is a high-performance JavaScript bundler and minifier written in Go. Vite uses esbuild for rapid transpilation of TypeScript and JSX into JavaScript during development, which is significantly faster than traditional Babel-based tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
