INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3260cd50-61fe-4c14-ad25-d2489eb9b909', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of a ''visibility timeout'' in a queue-based system?', N'Senior', N'The visibility timeout prevents other consumers from processing a message while it is being handled by a specific consumer. If the consumer fails to acknowledge the message within the timeout period, it becomes visible again for other consumers to retry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
