INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eae7210d-33b0-4026-bacb-d24b1704d46a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt optimize the loading of assets like images and fonts?', N'Middle', N'Nuxt leverages the Nitro engine and integrated modules to automatically process assets, such as resizing images or injecting critical CSS. It also supports automatic prefetching of linked pages, which significantly improves the perceived speed of subsequent page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a3b509a-0320-4ee9-b852-d24bba7d9a71', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why does Webpack use ''loaders'' instead of just plugins for file transformations?', N'Senior', N'Loaders are designed specifically to handle the transformation of individual files as they are pulled into the graph, allowing for a modular, pipeline-based approach. Plugins are designed for higher-level orchestration, whereas loaders focus on the granular conversion of specific file types into valid JS modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eed5b2f-4cb5-4841-a9f7-d24d711b88dd', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How Virtual DOM works?', N'Fresher', N'The _Virtual DOM_ works in five simple steps. 1. Initial Render When a UI component renders for the first time, it returns JSX. React uses this structure to create a Virtual DOM tree, which is a lightweight copy of the actual DOM. This Virtual DOM is then used to build and render the Real DOM in the browser. 2. State or Props Change When the component''s state or props change, React creates a new Virtual DOM reflecting the updated UI. However, it doesn''t immediately update the Real DOM; instead, it works in memory to prepare for an efficient update. !vdom 3. Diffing Algorithm React then compares the new Virtual DOM with the previous one using a process called diffing. It determines what has changed between the two versions and identifies the minimal set of updates needed. !vdom2 4.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c03901d4-bb09-41a4-9d56-d252ed0d2c27', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the benefit of using a specific build tool like Webpack?', N'Junior', N'It automates tasks that would be tedious to do manually, such as minifying code, bundling assets, and converting modern JavaScript syntax. It ensures consistent output and optimizes the application for performance and browser compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb7b1193-270d-4923-92de-d2563d10bfa5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle platform types when interacting with Java code?', N'Middle', N'Platform types are types coming from Java that do not have explicit nullability annotations, represented as T!. Kotlin cannot guarantee null safety for these types, so the compiler leaves the responsibility of null checks to the developer, potentially leading to NullPointerExceptions at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb92f460-1917-480a-b71c-d256d648b2ac', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Protractor and how is it used for end-to-end testing?', N'Fresher', N'Protractor was an end-to-end test framework specifically designed for Angular applications. It was built on top of WebDriverJS and ran tests against your application running in a real browser. Its key advantage for Angular was its ability to automatically wait for Angular-specific operations like $digest cycles and HTTP requests to complete before executing the next test step, making tests more reliable without manual waits. It also provided Angular-specific element locators, such as by.model, by.binding, and by.repeater. Protractor is now deprecated and is no longer the recommended E2E testing tool for Angular projects. Modern alternatives like Cypress, Playwright, and TestCafe are commonly used instead. > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
