INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07589c53-b1f4-4161-b42f-d263e0e47114', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the impact of excessive garbage collection on a high-throughput Node.js application, and how can it be mitigated?', N'Senior', N'Excessive garbage collection causes ''stop-the-world'' pauses that spike latency and affect throughput in event-driven systems. Mitigation strategies include optimizing object creation to reduce heap churn, using object pools for frequently created items, and monitoring memory usage to identify and resolve memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
