INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70d2b407-2e97-42a3-b7b5-d27bf4a85116', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Explain the role of the Write Barrier in Go''s Garbage Collector.', N'Senior', N'The write barrier is a mechanism used during the concurrent marking phase of the garbage collector. It ensures that any pointer modifications made by the application while the collector is running are tracked, preventing the collector from incorrectly freeing objects that are still reachable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
