INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48f923a9-6de0-474d-93e5-d2820083cfa4', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'When should an architect choose Tailwind over a zero-runtime CSS-in-JS solution?', N'Senior', N'Tailwind is preferable when team familiarity with HTML/CSS is high and the goal is a consistent, constraint-based design system with minimal runtime overhead. Zero-runtime CSS-in-JS is better if the project requires complex, programmatically generated styles that cannot be represented by a finite set of utility classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
