INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a595a96-e6a4-4c23-8229-d282e0d14801', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you implement graceful shutdown in a Gin-based service, and why is it necessary?', N'Senior', N'Graceful shutdown is achieved by using the http.Server Shutdown method, which stops accepting new connections while allowing existing requests to finish. This is essential to prevent data loss or inconsistent state for clients currently processing transactions during a deployment or restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f37bc9e-90a0-465c-9606-d28433d36458', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why do some database engines avoid using B-trees in favor of LSM trees?', N'Senior', N'LSM trees are optimized for write-heavy workloads because they transform random writes into sequential disk I/O by buffering updates in memory before flushing them to sorted files. While B-trees offer faster random reads, LSM trees significantly improve write throughput by eliminating the overhead of frequent random index updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
