INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16f6ec2d-0db3-463e-aa9a-d2a14d59ada4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain how the ''noinline'' and ''crossinline'' modifiers influence lambda capture in inline functions.', N'Senior', N'The ''noinline'' modifier prevents a lambda from being inlined, allowing it to be stored as a first-class object. ''crossinline'' allows a lambda to be inlined but restricts non-local returns, ensuring that the control flow remains predictable when the lambda is executed in a different execution context, such as an asynchronous callback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e89ebd17-50a9-4c7d-b7c1-d2a1812dc703', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the trade-offs of using Django signals versus direct method calls?', N'Middle', N'Signals decouple sender and receiver, allowing you to trigger actions without modifying the core business logic, which can lead to cleaner code. However, they make the execution flow harder to trace, increase debugging complexity, and can hide side effects that might lead to unexpected performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b539facb-b76b-446e-94f5-d2a376b8d806', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the limitations of MongoDB?', N'Junior', N'MongoDB may not be the best choice for applications that require complex joins across many tables, as it does not perform these as efficiently as relational databases. Additionally, because documents can vary in size, improper data modeling can lead to memory fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdd85934-b17d-4aca-9432-d2a4c42823b6', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What role does the ''StripSlashes'' middleware play in a Chi application?', N'Middle', N'The StripSlashes middleware normalizes request paths by removing trailing slashes, which ensures that routes defined without them match correctly. This is important for SEO and consistency, preventing different URLs from potentially mapping to different resources unintentionally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ac784d5-8505-4937-b3df-d2a4c6cb4d6e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are ''Path'' parameters in Axum?', N'Fresher', N'Path parameters are dynamic segments of a URL, such as user IDs, that are captured by the router. Axum''s Path extractor allows you to easily parse these segments into typed variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca35e10b-0db9-4a04-85e6-d2a763877c8d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you estimate the time required for disaster recovery and business continuity testing?', N'Senior', N'I define the Recovery Time Objective (RTO) and Recovery Point Objective (RPO) based on business requirements. I estimate the effort for full-system restoration exercises, including data verification and environment provisioning, to ensure the recovery plan is actually achievable within the time constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'384334c0-c052-48d6-ab5b-d2a7b8fcda53', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s context object (c) differ from the request/response pattern in traditional frameworks regarding state management?', N'Senior', N'The context object in Hono acts as a unified container for the request, response, environment variables, and execution metadata, providing a single source of truth for the entire request lifecycle. This design simplifies dependency injection and state sharing across middleware, avoiding the pitfalls of attaching data to the request object, which is common in older frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c74929de-2c41-423a-a8fe-d2a7ed89f8d5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the difference between the ''jit'' (Just-in-Time) engine and the older version of Tailwind?', N'Junior', N'The JIT engine generates CSS on-demand as you author your templates, rather than generating all possible utility classes upfront. This results in much faster build times and allows for arbitrary value support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'854e045c-a41c-4832-9a8a-d2a9171ba7f4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Compare the memory management strategies of Ruby''s ''copy-on-write'' (CoW) friendliness during process forking.', N'Senior', N'Ruby''s CoW friendliness relies on the OS''s ability to share memory pages between a parent process and its forked children until data is modified. Large objects or heavily initialized applications can trigger premature page copying, significantly increasing the RAM footprint; therefore, optimizing the boot process is crucial for memory-efficient multi-process scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78cd9732-ef6c-45fb-89bf-d2aa6f583047', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the difference between ''structural equality'' and ''referential equality''.', N'Middle', N'Structural equality, checked with the ''=='' operator, compares the content of two objects by calling their equals method. Referential equality, checked with the ''==='' operator, verifies if two variables point to the exact same memory address.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8161ca0-92ad-4867-b519-d2ab2b384db6', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you set a custom HTTP status code in Gin?', N'Junior', N'You can set a status code by passing the integer code as the first argument to any response method, such as JSON, String, or HTML. Additionally, you can explicitly set the status for a response using the Status method on the context object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ede3482-d628-4267-bed9-d2acb0d13acc', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact maintain component state consistency across deep component trees without Context bloat?', N'Senior', N'Preact implements a highly optimized Context API that minimizes the overhead of providers and consumers by utilizing a simpler object-tracking mechanism. This prevents the performance degradation that typically occurs when deep trees frequently trigger updates via high-frequency context value changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03fd705f-c4e7-4902-b8cb-d2ad9b527428', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How should an intern react when asked to make a trade-off they don''t fully understand?', N'Intern', N'I would ask for clarification on the project goals and the specific constraints involved. It is better to admit a lack of understanding and ask for guidance than to make a decision that could negatively impact the project later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b00ae667-df23-4b8f-98cd-d2b4ce379aec', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix ensure that individual WebSocket connections are isolated from one another?', N'Senior', N'Each connection in Phoenix is handled by a separate Erlang process. Because these processes share no memory and communicate exclusively through message passing, one connection crashing or misbehaving cannot affect the stability or memory of other concurrent connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
