INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6393966f-527d-444b-9292-d2b8979ae741', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the main features of Reselect library?', N'Intern', N'Let''s see the main features of Reselect library, 1. Selectors can compute derived data, allowing Redux to store the minimal possible state. 2. Selectors are efficient. A selector is not recomputed unless one of its arguments changes. 3. Selectors are composable. They can be used as input to other selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
