INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'808c5eee-ac2a-415f-b51b-d2bc808c4e07', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the Cassandra CommitLog ensure durability?', N'Middle', N'When a write request hits a node, it is first appended to the CommitLog on disk before being applied to the MemTable. This ensures that in the event of a power failure or node crash, the data can be recovered by replaying the logs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
