INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92aa35c4-abb0-40ce-95d0-d2def1b71f2a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s diffing algorithm differ from React''s?', N'Fresher', N'Preact''s diffing algorithm is optimized for speed and minimal memory footprint. While both follow similar logic, Preact simplifies several processes to reduce the total code size required to implement the rendering engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c7bb447-10b3-4422-9815-d2df3a9a075b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Is Hono purely for API development?', N'Fresher', N'No, Hono can also be used to build full-stack applications. With its JSX support and static file serving, it can handle both server-side rendering of HTML and API endpoint delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08209edf-cc1a-408f-93a9-d2df67b3ed44', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is Relay?', N'Intern', N'Relay is a JavaScript framework for providing a data layer and client-server communication to web applications using the React view layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0759a15-8d76-4c41-ae4f-d2dfb1f53a7f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle graceful shutdowns?', N'Middle', N'Echo relies on the standard library''s HTTP server configuration. By manually starting the server using a custom lifecycle management approach, you can listen for termination signals and call the Shutdown method to gracefully finish pending requests without dropping connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14361910-9768-4259-90f3-d2e5d070100c', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the N+1 query problem and how to resolve it in Rails.', N'Middle', N'An N+1 query occurs when an application executes one query to fetch a parent record and then executes individual queries for each child record associated with the parent. This is resolved by using the ''includes'' or ''eager_load'' methods to fetch associated data in a single join or a secondary optimized query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dced8e99-31ce-4d09-b7ed-d2e9473bcd03', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you scale a messaging system when the broker becomes a bottleneck?', N'Middle', N'You can scale by clustering the broker nodes, implementing partitioning to spread the load, or using a distributed messaging system that supports horizontal sharding. Additionally, optimizing message size and reducing unnecessary metadata can help improve broker throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7dd0bfe-5543-4006-908e-d2e9f0cdcc7e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle environment variables across different runtimes?', N'Junior', N'Hono provides a unified way to access environment variables through the context object. By defining an environment interface, developers can access configuration settings consistently regardless of whether the app is running on Cloudflare Workers, Node.js, or elsewhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62fcaf93-95e2-4be4-89e4-d2eb5aabf9e5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you ensure that a system is ''self-healing''?', N'Senior', N'I would leverage automated orchestration to detect and replace unhealthy instances, implement automated failover mechanisms for databases and load balancers, and use circuit breakers to isolate failures. The system should be designed to recover to a known good state without human intervention through automated rollback pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c945cc9b-e4b4-425c-a79c-d2edac4fd13b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does the CAP theorem influence database selection for distributed systems?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. Database designers must choose which two properties to prioritize based on whether the application requires strong data accuracy or high uptime during network failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cb03d3f-594f-403c-a8dc-d2f08ca5363c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How can you optimize network requests for better performance?', N'Senior', N'To optimize network requests for better performance, you can minimize the number of requests, use caching, compress data, and leverage modern web technologies like HTTP/2 and service workers. For example, you can combine multiple CSS files into one to reduce the number of requests, use Cache-Control headers to cache static assets, and enable Gzip compression on your server to reduce the size of the data being transferred. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f94ee5b-5a6c-4f23-add1-d2f7f9bcd83d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are the trade-offs of using Rocket''s request guards for authorization?', N'Senior', N'Request guards provide a clean, declarative way to enforce security policies by requiring specific headers or tokens before a route executes. While this promotes modularity, complex authorization logic can become difficult to debug if chains of guards are used, requiring careful planning to avoid hidden performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'404fe570-8a2d-49d2-8083-d2f88496d82b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the significance of the useNavigation hook?', N'Junior', N'The useNavigation hook provides access to the current state of a page transition, such as whether a form is currently submitting or a new route is loading. This is useful for implementing loading indicators or disabling buttons while waiting for server responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
