INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'216b9d73-f1d5-407b-9055-d2facd07b65a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support multiple languages?', N'Intern', N'Micronaut is designed to be language-agnostic at the framework level, providing first-class support for Java, Kotlin, and Groovy. It uses the same annotation processing logic regardless of which JVM language is chosen.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129d51f9-035f-4761-986a-d2fb7e480364', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is ''Observability'' more than just monitoring?', N'Senior', N'Monitoring tells you when a system is failing, whereas observability provides the insights to understand why it is failing by analyzing logs, metrics, and distributed traces. It requires designing the architecture for introspection so that internal states can be inferred from external outputs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0685e98-0f0e-46c3-b1e0-d2fc4d5e710d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the risk of having too many alerts in an observability system?', N'Middle', N'Excessive alerts lead to ''alert fatigue,'' where engineers become desensitized to notifications. This results in critical issues being ignored or missed, which undermines the entire purpose of having an automated monitoring system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'416c1400-58f2-4bf9-b51d-d2fd5aab1bd8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle ''hot partitions'', and what architectural patterns can mitigate this?', N'Senior', N'Hot partitions occur when specific partition keys receive disproportionately high traffic, leading to throttling. Mitigation strategies include implementing request caching, using a write-sharding strategy by appending random suffixes to keys, or redesigning the data model to distribute load more evenly across the keyspace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acde62ae-e410-4ded-bf7d-d302a94bd1f2', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are Spring Profiles?', N'Fresher', N'Profiles provide a way to segregate parts of your application configuration and make it available only in certain environments. For example, you can define separate profiles for development, testing, and production to load different database settings or external service endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ecb9dda-95d1-4be8-9fc9-d3035f9ffda4', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle lexical scoping in nested functions?', N'Middle', N'R uses lexical scoping, meaning the scope of a variable is determined by its physical location within the source code. When a function looks for a variable, it searches the current environment and then traverses up the enclosing environments until it finds a match or reaches the global environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a727fd6-1a9c-4687-8ffb-d306ea7b2171', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the security considerations for designing an API that supports CORS?', N'Senior', N'CORS must be strictly configured to whitelist only trusted origins, methods, and headers, avoiding wildcards in production. It is crucial to validate the Origin header on the server and ensure that sensitive endpoints are protected by authentication mechanisms rather than relying solely on browser-level CORS protections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'200beba0-43d9-4f5d-9344-d307c3714c9f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between mapped types and conditional types?', N'Middle', N'Mapped types transform existing types by iterating over their keys to create new types, often used for utility types like Partial or Readonly. Conditional types use a ternary-like syntax to select one of two types based on a condition, enabling advanced type logic. Both allow for highly dynamic and reusable type definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3311c03c-55c3-4bda-a999-d30b1513134f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Is Alpine.js suitable for building large single-page applications?', N'Fresher', N'Alpine.js is generally not recommended for large-scale, complex single-page applications. It is designed to enhance static HTML, and managing state across dozens of complex, deeply nested components can become difficult compared to using a dedicated SPA framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e54fc15e-d88b-4ffc-8eb0-d30cad7a46b2', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the ''build time'' metadata processing in Quarkus?', N'Junior', N'Build-time processing allows Quarkus to analyze the application code, resolve dependencies, and remove unused classes before the application even starts. This reduces the work the runtime needs to perform, significantly decreasing startup latency and memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92a375a1-b70a-4235-9043-d30e3527f6eb', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the trade-offs of using @extend when working with modular component-based architectures?', N'Senior', N'Using @extend across different files can lead to unexpected side effects because it forces a dependency between selectors that might not be intended. It can also cause issues with CSS specificity if the extended selector is defined in a different part of the stylesheet, making it difficult to maintain in large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02f8eda0-fa21-4849-a0ef-d30ee59b1972', N'4c000000-0000-0000-0000-000000000005', N'Describe the architectural benefits of moving from a monolith to a Hexagonal Architecture.', N'Senior', N'Hexagonal architecture decouples the core business logic from external dependencies like databases or APIs using ports and adapters. This increases testability, allows for easier technology swapping, and keeps the domain model isolated from infrastructure concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69725658-d694-48bb-8df4-d30f798d04ff', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the impact of using Gin''s `ShouldBind` vs `Bind` methods regarding HTTP status codes?', N'Senior', N'The `Bind` method automatically writes a 400 Bad Request status code if the binding fails, which is convenient but inflexible. `ShouldBind` returns the error instead, allowing the developer to implement granular error handling, such as returning specific validation errors or custom status codes based on the business context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1798b330-f67b-4e8a-82d9-d31087ead3ae', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between a GET and POST request in Fiber?', N'Intern', N'A GET request is typically used to retrieve data from a server, while a POST request is used to send data to be processed or stored. Fiber provides distinct methods for each, allowing developers to define different handlers for different HTTP verbs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b73ecf03-6b83-4572-a4ed-d31371dac2fc', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How do components get data from the Redux store?', N'Intern', N'Components typically use hooks like ''useSelector'' to retrieve specific data from the store. This creates a subscription, meaning the component will automatically re-render if the selected part of the state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'417657f9-b12f-4c7d-9644-d313f75f8227', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''async'' and ''await''?', N'Junior', N'The ''async'' keyword marks a method as asynchronous, allowing it to use the ''await'' keyword inside. ''Await'' pauses the execution of the method until the awaited task completes, without blocking the thread that called the method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3eabb1a7-7ddc-4f62-ac0f-d314d0701012', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the security implications of using ''vm'' module in Node.js, and what are the alternatives?', N'Senior', N'The vm module is not a secure sandbox and should not be used to execute untrusted code as it lacks robust isolation against malicious script execution. For running untrusted code, one should utilize separate processes, containers, or specialized sandboxing technologies like WebAssembly or isolated cloud functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0440c744-d35c-4eab-bf54-d316eb0b7ae9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the advantage of using sparse indexes in DynamoDB?', N'Middle', N'A sparse index only includes items that contain the index''s key attribute. This allows you to efficiently query for a subset of items, such as finding all ''pending'' orders without scanning the entire table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58995d0e-0960-4fc3-a020-d31e69c88066', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are Qwik ''Chunks''?', N'Intern', N'Chunks are small, individual files of JavaScript generated by the build process. By splitting the application into many tiny chunks, Qwik ensures that the browser only downloads the specific code needed for an interaction instead of the entire application bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d59bd05-f714-4298-a2c0-d31e925896cb', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle application state?', N'Intern', N'Qwik serializes the application state directly into the HTML sent from the server. When the browser loads the page, it can read this state immediately, allowing the framework to resume where the server left off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee561f7-ee6f-4da4-a39d-d3204705cd56', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage thread context in reactive applications?', N'Senior', N'Quarkus manages thread context propagation to ensure that security identities, transactions, and CDI contexts are correctly passed between asynchronous tasks. This prevents common reactive issues where context is lost when moving between threads in a non-blocking execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cecec386-05fe-48b1-8af1-d3281ab16b3a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off involved in documenting a project?', N'Intern', N'Writing extensive documentation ensures knowledge transfer and long-term maintainability. However, it requires time that could be spent on development, and documentation can become outdated if not maintained regularly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca59a194-1eb1-4c96-a6a6-d32822201934', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the primary difference between shallow and deep copying of objects?', N'Middle', N'A shallow copy creates a new object with copies of the top-level properties, but nested objects remain referenced by the original. A deep copy recursively duplicates all nested objects, ensuring that changes to the copy do not affect the original, which is essential for maintaining immutable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'031af39a-d7de-40df-ba3e-d32963bb55b9', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a computed property (or getter) used for in Ember?', N'Junior', N'Getters are used to derive new values from existing state or properties. They automatically update whenever the underlying data changes, allowing you to compute dynamic values without manually syncing them in your actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e450cc-508a-4d5c-9301-d32b1e1b1c73', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is ''Clone'' required for the application state in Axum?', N'Middle', N'Axum''s request handling architecture relies on cloning the state reference to pass it into individual request handlers or concurrent tasks. Since the server handles multiple requests in parallel, the state must be cheaply cloneable to be distributed across the runtime threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30c8f052-0c2d-4a8d-b0ba-d32beb4be598', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the four ACID properties in database transactions?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data validity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fc9e075-2518-4137-b068-d32d3e408be8', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the advantage of using a logging framework over simple print statements for debugging?', N'Fresher', N'Logging frameworks provide levels of severity, allowing developers to filter messages based on importance during different environments. They also automatically include useful metadata like timestamps and source locations, and can easily output to external files or monitoring tools, which print statements cannot do.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dea5b2f2-aa42-4f3b-813a-d332e8dbdfb0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the benefit of using interfaces for function parameters?', N'Intern', N'Using interfaces for function parameters makes the expected structure of the input clear and enforces consistency. It documents the requirements for the function clearly, making it easier for other developers to use the function correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a67537ae-e243-457a-8317-d334b7500b81', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When would you prefer a relational database over a NoSQL database?', N'Fresher', N'I would choose a relational database when the data is highly structured and complex relationships between entities are required. Relational databases excel at ensuring data integrity through ACID properties, which is crucial for applications like banking or inventory management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9c1be3d-1aaf-4719-9859-d3356bc6e0b8', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is Rocket state management?', N'Intern', N'State management allows you to share data across different request handlers in your application. By using managed state, you can inject shared resources like database connections or configuration settings into your handlers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70120fb8-4554-48e3-bb57-d3359dca7c3a', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a deployment that succeeds but results in a non-functional service?', N'Middle', N'I would examine the service startup logs for failed dependency checks, such as database connectivity issues or missing environment secrets. I would also use health checks to see if the container is failing to transition to a ''ready'' state, which often points to misconfiguration in the service orchestration layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'521d2e9f-204f-4c1f-a440-d33732cc9da8', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of the TypeScript control flow analysis in type narrowing, and how does it affect compiler performance?', N'Senior', N'The compiler performs reachability and flow analysis to refine types based on guards or assignments within specific branches. While this provides powerful type safety, deep analysis of complex conditional chains can significantly increase compilation time, necessitating the use of type aliases or explicit annotations to prune the search space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baa071cc-98e5-4798-9942-d3397e2413e5', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''vm'' module in Node.js, and why is it dangerous?', N'Senior', N'The vm module allows running JavaScript code within a V8 virtual machine context. It is dangerous because it does not provide a secure sandbox; malicious code can easily escape the context and access the host process. It should never be used to execute untrusted user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e2e084f-2245-495e-9226-d33aac3d188b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the primary purpose of the Composer autoloader, and how does it optimize file inclusion?', N'Middle', N'Composer''s autoloader maps class names to file paths, eliminating the need for manual require or include statements. It optimizes performance by generating class maps that allow the application to load only the necessary files at runtime instead of scanning the filesystem repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dcb722a-85cd-41de-86f4-d33b812ca361', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does ''Two-Phase Commit'' (2PC) maintain consistency in distributed systems?', N'Senior', N'2PC is a protocol that ensures all nodes in a distributed transaction either commit or abort together, providing atomic consistency. It involves a prepare phase, where nodes signal their readiness, and a commit phase, where the coordinator instructs all nodes to finalize the changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50f6e331-32c8-4223-b0ac-d33c654970ea', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is Static Site Generation (SSG) and when is it used?', N'Junior', N'SSG generates HTML files at build time rather than at request time. It is used for content that does not change frequently, as it allows the pages to be served extremely quickly from a CDN.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e193dc7d-9ed5-4328-ac74-d33c9d007c51', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik optimize the critical rendering path for SEO?', N'Senior', N'By eliminating hydration, Qwik ensures that the HTML sent to the browser is fully functional and interactive immediately upon arrival. This removes the ''interactivity gap'' where a page appears rendered but is unresponsive, which positively impacts Core Web Vitals and search engine indexing performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'280afad7-faf7-4a49-8484-d340e5dac246', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the role of the ''App'' trait in Scala?', N'Junior', N'The App trait allows you to create an executable program by simply extending it in an object. It provides a main method automatically, so you do not need to write one explicitly to run your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cde67d1-a242-4d26-b2c9-d341999161c5', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''call-by-value'' and ''call-by-name'' parameters?', N'Fresher', N'Call-by-value parameters are evaluated once before entering the function, while call-by-name parameters are evaluated every time they are accessed inside the function body. Call-by-name is denoted by adding a ''=>'' before the parameter type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b9a7e02-cf73-4eef-b879-d3428d9d5ea8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a partition in DynamoDB?', N'Junior', N'A partition is a physical storage area allocated for a table that is backed by solid-state drives. DynamoDB automatically splits and spreads data across multiple partitions as the table grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e752ab02-da12-4141-b16a-d343b86069d5', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of a Transaction Log during a rollback operation?', N'Middle', N'During a rollback, the database uses the transaction log to identify changes made by the interrupted transaction. It then applies the inverse operations stored in the log to revert the data to its original, consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f11c1314-b409-43fa-9540-d345e933bf8b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the risks of using global variables in a concurrent Go application?', N'Senior', N'Global variables create implicit shared state that requires explicit synchronization, such as mutexes or atomic operations, to prevent data races. This increases the complexity of unit testing and makes it significantly harder to reason about the system state in a highly concurrent environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8a8bbde-9f70-49f9-8c4a-d3461d2aecf0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the purpose of a replica shard?', N'Junior', N'Replica shards are copies of primary shards used for high availability and fault tolerance. They ensure that if a node fails, the data remains accessible, and they also help improve search performance by distributing query load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa360b6e-d6a2-41a6-a54f-d346ca1a4f58', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the difference between message queuing and a publish-subscribe model?', N'Middle', N'Message queuing typically involves a point-to-point communication pattern where a message is delivered to exactly one consumer. In contrast, publish-subscribe allows a single message to be broadcasted to multiple interested subscribers simultaneously, decoupling the producer from all consumers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5571bcf1-ee0b-493b-bc30-d34d26caa5ed', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React''s fiber architecture improve UI performance during heavy rendering tasks?', N'Senior', N'Fiber allows React to break the reconciliation process into smaller units of work that can be paused, resumed, or aborted. This enables the engine to yield back to the main thread, preventing UI blocking and ensuring high-priority updates like animations or user input remain responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fee09a7a-0b37-4e3a-a0b9-d34d936fb77e', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the risk of exposing internal database IDs in public API responses?', N'Middle', N'Exposing internal IDs can reveal information about your database size or architecture, and it can facilitate enumeration attacks. It is safer to use public-facing identifiers like UUIDs or slugs that are decoupled from the primary database key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fa4c75e-8810-4082-b84c-d34fd49d7565', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a monolithic architecture and microservices for a small startup team?', N'Junior', N'Monoliths are generally easier to deploy, test, and debug for small teams due to lower operational overhead. Microservices offer better independent scaling and team autonomy but introduce significant complexity in networking, service discovery, and distributed data management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cff502db-79b2-4700-a7ba-d35591720674', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between ''map'' and ''flatMap'' when working with collections?', N'Middle', N'''map'' transforms each element in a collection to a new value, resulting in a collection of the same size. ''flatMap'' transforms each element into a collection and then flattens all those resulting collections into a single, unified collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e92c23a6-8413-49b1-a74c-d35a7b154d4c', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What does   { box-sizing: border-box; } do? What are its advantages?', N'Intern', N'* Make every element in the document include the padding and border in the element''s inner dimensions; making it easier to reason about the layout of elements on the page. * By default, elements have box-sizing: content-box applied, and only the content size is being accounted for. * box-sizing: border-box changes how the width and height of elements are being calculated, border and padding are also being included in the calculation. * The height of an element is now calculated by the content''s height + vertical padding + vertical border width. * The width of an element is now calculated by the content''s width + horizontal padding + horizontal border width.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa3b0927-61b1-4005-a567-d35b68411aad', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between a relational database and a NoSQL document database regarding schema flexibility?', N'Junior', N'Relational databases require a predefined, rigid schema where every row in a table must follow the same structure. In contrast, NoSQL document databases are schema-less or flexible, allowing each document in a collection to have different fields and data types. This makes it easier to iterate on data structures without needing to perform complex schema migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
