INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dde79db3-4a3e-4d5f-adcc-d379d14886a3', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s router handle overlapping route patterns?', N'Middle', N'Chi evaluates routes in the order they are defined or based on the specificity of the pattern matching logic in its radix tree. When overlapping paths exist, the router ensures that the most specific match is prioritized, preventing ambiguous routing outcomes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
