INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7122aa78-f346-4ff2-b816-d3831fb7f49e', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the primary architectural advantage of using property delegates in Kotlin?', N'Senior', N'Property delegates decouple the storage of a property from its access logic, enabling cross-cutting concerns like lazy initialization, observable patterns, or database binding to be implemented generically. This separation of concerns allows for cleaner, modular code that abstracts complex state management away from the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e03cf2f-82f0-4f94-81f7-d38447ad4c63', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you handle a situation where two services are deadlocking each other?', N'Middle', N'I would start by analyzing logs and thread dumps to identify the resources being contested and the sequence of calls causing the cycle. I would then resolve the deadlock by implementing strict lock ordering, reducing the scope of the locks, or moving to a more asynchronous, event-driven communication model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
