INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fc4cec9-0a46-409a-b414-d38959970013', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Explain how MongoDB handles document growth and what happens when a document exceeds its allocated space.', N'Middle', N'When a document increases in size beyond its allocated record space, MongoDB must relocate the document to a new location on disk. This can lead to storage fragmentation and requires the database to update all corresponding index entries pointing to that document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b213ae7-f861-4f42-be91-d38ac5404bdf', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''val'' and ''var'' in Scala, and when should you prefer one over the other?', N'Junior', N'In Scala, ''val'' declares an immutable variable that cannot be reassigned after initialization, while ''var'' declares a mutable variable that can be changed. You should prefer ''val'' by default because immutability makes code easier to reason about, safer in concurrent environments, and reduces side-effect related bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
