INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b931a0b-a6ce-4752-b35f-d38f04a5098e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What are the performance implications of using eager loading versus lazy loading in a Rails application with complex object graphs?', N'Senior', N'Eager loading reduces N+1 query issues by fetching associated data upfront, which optimizes database round-trips but increases initial memory consumption. Lazy loading conserves memory by fetching data only when accessed, but it risks causing performance degradation due to multiple sequential database hits during object iteration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5538103a-301a-4816-abb8-d3908a4b08ce', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing a user interface, why is it important to consider the principle of ''least privilege'' for user roles?', N'Fresher', N'Applying the principle of least privilege ensures that users only have access to the specific features and data necessary for their role. This design decision minimizes the risk of accidental data modification or unauthorized access. It improves overall security by limiting the potential impact if a user account is compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'701bad4c-d13b-4114-bbd4-d3965b3f8639', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the primary trade-off between Snapshot Isolation and Serializability?', N'Senior', N'Snapshot Isolation prevents dirty reads and non-repeatable reads while allowing higher concurrency by letting transactions operate on a consistent version of the database. However, it is susceptible to write skew, which Serializability strictly prohibits, making Snapshot Isolation less restrictive but potentially less correct for certain business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76fd0cbe-74b6-4e32-a39e-d3967e64dcb0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of breakpoints in debugging', N'Intern', N'You can set breakpoints in the javascript code once the debugger statement is executed and the debugger window pops up. At each breakpoint, javascript will stop executing, and let you examine the JavaScript values. After examining values, you can resume the execution of code using the play button.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
