INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89f8bb52-d8ed-4928-a378-d3a75d5c0107', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What happens when a variable goes out of scope in Rust?', N'Fresher', N'When a variable goes out of scope, Rust automatically calls a special function called ''drop'' to clean up the resources associated with that variable. This ensures that memory is managed automatically without needing a runtime garbage collector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69d10f59-4ef1-4464-9200-d3a88aee2862', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Can you use third-party middleware with Chi?', N'Middle', N'Yes, because Chi is compatible with standard http.HandlerFunc, any middleware that conforms to the standard library pattern can be used. There is no need for specialized ''Chi-only'' middleware to extend functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25451dd4-fc0d-41a0-b56a-d3aab2921973', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle routing?', N'Intern', N'Routing is the process of mapping specific URL paths and HTTP methods to dedicated handler functions. Actix-web uses a routing table defined during the application configuration phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a84ac5e9-655d-4ca5-88b2-d3ab063f6bc2', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are assignment operators in Python?', N'Intern', N'This one is an Important Interview question in Python Interview. We can combine all arithmetic operators with the assignment symbol. a = 7 a += 1 a 8 a -= 1 a 7 a*=2 a 14 a/=2 a 7.0 a=2 a 49.0 a//=3 a 16.0 a%=4 a 0.0', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46155029-7801-4f8f-981e-d3ad0bfda3cb', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does the query planner decide between a sequential scan and an index scan?', N'Middle', N'The query planner uses table statistics to estimate the cost of different execution plans. If it determines that scanning a small percentage of a table via an index is cheaper than reading the entire table, it will use an index scan; otherwise, it defaults to a sequential scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d03802e-6a92-4320-b482-d3ad19df47e4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your approach to fault tolerance in a system with high dependency chains?', N'Senior', N'Implement bulkhead and circuit breaker patterns to isolate service failures and prevent cascading errors. Ensure that timeouts and retries are configured with exponential backoff and jitter to avoid overwhelming recovering services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17fb558f-797b-425e-80a5-d3ada8c256db', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What does ''Graceful Degradation'' mean in system architecture?', N'Middle', N'Graceful degradation is the design philosophy of allowing a system to continue operating in a reduced capacity rather than failing completely. For example, a search engine might return cached results or omit non-essential features when the main database is unavailable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f425415-6f98-4786-b970-d3b125a2fa60', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you perform graceful shutdown of a Gin server?', N'Middle', N'A graceful shutdown is implemented by using the standard library''s http.Server with a custom listener and listening for OS signals like SIGINT or SIGTERM. Once a signal is received, the server stops accepting new connections and waits for existing requests to complete before closing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09eb7ca3-e436-4013-ba9a-d3b23f9cd8fc', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the trade-offs of using Read Committed versus Serializable isolation levels.', N'Middle', N'Read Committed provides better concurrency and performance by allowing non-blocking reads but is susceptible to non-repeatable reads and phantoms. Serializable offers the highest level of data integrity by preventing all concurrency anomalies but significantly reduces throughput due to increased locking or validation overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3553052-b30b-4ffa-b66f-d3b2f4756ea8', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s middleware execution order influence the behavior of authentication versus rate-limiting?', N'Senior', N'Middleware executes in the order it is registered; therefore, rate-limiting should generally be placed before authentication to protect the auth service from DoS attacks. Conversely, if authentication is required to determine the rate-limit tier, auth must precede rate-limiting, illustrating a classic trade-off between resource protection and business logic requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'719fd9cc-d090-41c4-b559-d3b343300681', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite ensure consistency between the development server and the production build?', N'Senior', N'Vite uses a unified plugin configuration for both dev and production to ensure that transformations are applied consistently across environments. By sharing the same Rollup-compatible plugin interface, Vite minimizes the risk of ''it works in dev but fails in production'' scenarios caused by configuration drift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57e364e8-c01b-4add-be2b-d3b731c34d70', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does the C translation unit model affect build scalability in large systems?', N'Senior', N'Each translation unit is compiled independently, which allows for parallel build processes and incremental compilation. However, this isolation prevents the compiler from performing global optimizations across the entire program without link-time optimization support. This architectural trade-off prioritizes build speed and modularity over the potential gains of holistic code analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5e5aa02-74f1-4932-ab77-d3b7e80dd00a', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are Nuxt ''Modules'' and why are they used?', N'Fresher', N'Modules are extension packages that allow you to add new features or integrations to your Nuxt application without manually configuring them. They are used to simplify tasks like adding support for state management, UI frameworks, or third-party analytics tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4d52ee6-6d1f-44df-adaf-d3b86b01f96e', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is ''type-safe routing'' in the Rocket framework?', N'Intern', N'Type-safe routing means that the parameters extracted from a URL or request body are automatically converted into the specific Rust types defined in the handler function signature. If the incoming data does not match the expected type, Rocket automatically rejects the request, ensuring that the backend logic only receives data that adheres to the defined structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b51a41c4-842b-4859-ab56-d3baff155d3d', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain how ''Drop-checking'' prevents memory safety issues in complex data structures.', N'Senior', N'Drop-checking is a static analysis process that ensures a type does not contain references to data that could be dropped before the type itself. It protects against use-after-free errors by enforcing strict rules on the order in which objects are destroyed during scope exit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'567d9dc2-94d7-4345-a831-d3bb829301a0', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can fibers run in parallel on multi-core systems?', N'Middle', N'Yes, if the fiber runtime supports multi-threading by pinning fibers to a pool of OS threads. In this configuration, multiple fibers can execute simultaneously on different CPU cores, provided the underlying runtime handles the necessary synchronization for the scheduler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7770f22-206b-4565-b870-d3c34a9caded', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''public'', ''private'', and ''protected'' access modifiers?', N'Intern', N'Public members are accessible from anywhere, while private members are restricted to the class where they are defined. Protected members are accessible within the class and any classes that inherit from it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8e62997-fc06-498a-aeaf-d3c44895b21f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle database integration?', N'Junior', N'NestJS is database-agnostic and provides modules for integrating various ORMs like TypeORM, Mongoose, or Prisma. These modules act as wrappers that allow you to easily inject database repositories into your services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7771898-4381-454e-bac2-d3c615c9991a', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the BASE model in NoSQL?', N'Intern', N'BASE stands for Basically Available, Soft state, and Eventual consistency. It is a design philosophy used in many NoSQL databases that favors high availability over the immediate consistency found in ACID transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a56ba601-51e6-4bcc-922e-d3c7d30edab7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between [] and new Array()?', N'Fresher', N'[] and new Array() are two different ways of creating an array, but they are functionally equivalent. The primary difference between them is in how they are created and in their behavior when used with certain methods. [] is a shorthand for creating a new array. It is the preferred way to create an array in most cases, because it''s more concise and easier to read. For example: On the other hand, new Array() is a constructor function that creates a new array object. It can be used to create an array of a specific length or with specific elements. For example: One potential pitfall of using new Array() is that it can be ambiguous when you pass a single argument to the constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b43401c2-0d92-4bc6-b8da-d3ca1e4f17b4', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Can Chi handle wildcard routes?', N'Junior', N'Yes, Chi supports wildcard patterns using the asterisk character. This allows you to match arbitrary paths, which is often used for serving static files or implementing catch-all routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fc9af11-cf25-480c-bcc2-d3cc2cf65436', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle asynchronous concurrency compared to synchronous frameworks?', N'Middle', N'Litestar is built on an asynchronous foundation using Starlette and asyncio, allowing it to handle thousands of concurrent connections efficiently. Unlike synchronous frameworks that block the event loop during I/O, Litestar allows the server to process other requests while waiting for external resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cab97403-0e52-4595-b12a-d3cc823a8972', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is it dangerous to destructure props in a SolidJS component without using ''splitProps'' or getters?', N'Senior', N'Props in SolidJS are reactive objects, and destructuring them normally extracts the current value, breaking the reactive link to the parent. Using getters or utility functions like splitProps maintains the reactivity, ensuring that changes in the parent component correctly update the child component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7899c9bd-cc1e-45c8-a8ec-d3cc9a24dede', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to prevent memory leaks in Node.js?', N'Fresher', N'Tools to help debug memory leaks: 1. Node-heapdump: The node-heapdump module is good for post-mortem debugging. It generates heap dumps on your SIGUSR2. To help catch bugs easily in a development environment, add node-heapdump as a dependency to your project like so: 2. Clinic.js: Clinic.js is a handy toolset to diagnose and pinpoint performance bottlenecks in your Node applications. The Clinic.js HeapProfiler uses flame graphs to highlight memory allocations. You can use it with tools such as AutoCannon to simulate HTTP load when profiling. 3. The process.memoryUsage method: The process.memoryUsage method provides a simple way of monitoring memory usage in your Node applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac768540-1594-496a-8d59-d3ce079fdd0b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the role of an Anti-Corruption Layer (ACL) in microservices?', N'Senior', N'An ACL acts as a translation layer between two services with different domain models. It prevents the internal domain logic of one service from being ''corrupted'' by the external, incompatible model of another, maintaining clean boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4685a76d-d1ce-40c7-8cae-d3ce1dec5b8a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why is it important to use ''Rocket'' managed state over global variables?', N'Middle', N'Managed state is managed by the framework''s lifecycle, ensuring that objects are properly initialized and available only when the application is running. This approach avoids the risks of mutable global state, simplifies testing by allowing dependency injection, and ensures thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd60bc8ee-d89e-457a-ba08-d3d004120584', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of the ''onMount'' lifecycle hook?', N'Fresher', N'The onMount lifecycle hook is used to run code once after the component has been successfully rendered and inserted into the DOM. It is typically used for tasks like fetching data or initializing third-party libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bdf0ce4-a4e9-466d-af93-d3d2a52c4bed', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the first thing you should do if you accidentally deploy a bug to production?', N'Junior', N'The priority is to minimize impact, so I would immediately inform the team and assess if a rollback to the previous stable version is possible. Once the service is restored, I would perform a post-mortem to understand how the bug bypassed testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5e451d3-4b0b-4f01-9d91-d3d2ac25355c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi often preferred for microservices?', N'Middle', N'Chi is preferred for microservices due to its small footprint, high performance, and adherence to the standard library. It provides just enough routing functionality to build robust APIs without the overhead or opinionated constraints of larger, monolithic frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44f91af8-c69a-4f68-a778-d3d570d98648', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is data compaction in Cassandra?', N'Intern', N'Compaction is the background process of merging multiple SSTables into a single new one. This process cleans up obsolete data and optimizes storage and read performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82ff5bfc-524b-474b-82ce-d3d73b8b6f66', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do I modify the url without reloading the page?', N'Fresher', N'The window.localtion.url property will be helpful to modify the url but it reloads the page. HTML5 introduced the history.pushState() and history.replaceState() methods, which allow you to add and modify history entries, respectively. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cedac5cf-6f84-4312-91fb-d3d8a05db6e7', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between a Group and a standard route in Fiber?', N'Fresher', N'A Group allows you to organize routes that share a common prefix or middleware. It helps in keeping the code clean and structured, especially when managing multiple API versions or nested resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa7efcea-a41d-41a3-823f-d3d9cdb16043', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Can you explain the differences between let and let mut in Rust?', N'Junior', N'In Rust, both let and let mut are used for variable declaration, but they have different characteristics relating to mutability. Let: Immutability by Default When you define a variable with let, Rust treats it as immutable by default, meaning its value cannot be changed once set. Example: let Let mut: Enabling Mutability On the other hand, using let mut allows you to make the variable mutable. Example: let mut Benefits and Safe Defaults Rust''s design, with immutability as the default, is consistent with security and predictability. It aids in avoiding potential bugs and helps write clearer, more maintainable code. For variables where mutability is needed, the use of let mut is an explicit guide that makes the code easier to comprehend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7681591e-511a-410a-9fee-d3dc99724b54', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What causes ''Shard Allocation'' to become stuck in a ''PENDING'' state?', N'Senior', N'Shard allocation can stall due to disk watermarks, insufficient nodes, or shard sizing issues. When a node exceeds the low or high disk watermark, Elasticsearch stops allocating new shards to that node to prevent disk exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97444729-b9e1-4806-8015-d3deea9d8193', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik affect Search Engine Optimization (SEO)?', N'Fresher', N'Qwik is excellent for SEO because it sends fully rendered, static HTML from the server to the browser. Search engine crawlers can read the content immediately without needing to execute complex JavaScript, leading to better indexing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e087383-640c-4a29-9600-d3e0ff80eab6', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''val'' keyword versus ''var'' in Scala, and why is immutability preferred?', N'Middle', N'Val defines an immutable reference, while var defines a mutable one. Immutability is preferred because it simplifies reasoning about state, eliminates race conditions in concurrent programming, and prevents accidental side effects, leading to more predictable and maintainable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54ee2b7e-48f0-482a-9194-d3e1a98a7ef6', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the concept of Cache Eviction and list two common policies.', N'Middle', N'Cache eviction is the process of removing entries from a cache when it reaches its capacity limit to make room for new data. Two common policies are Least Recently Used (LRU), which discards the item accessed furthest back in time, and Least Frequently Used (LFU), which discards the item with the lowest access count.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66d80006-b9ae-4d4b-9b8a-d3e59d3278af', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the CAP theorem and how does it relate to database scaling?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. When scaling databases, architects must choose between prioritizing consistency or availability during network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3df387c-f758-4bcd-b898-d3e804883204', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do ''Route Rules'' improve the maintainability of a Nuxt application?', N'Middle', N'Route Rules allow you to define rendering behavior, caching, and redirects in a single configuration file rather than scattering this logic across individual pages. This centralized approach makes it easier to manage and modify the infrastructure strategy as the application scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4462730b-6f8c-460e-80ad-d3eb81ee538a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do you handle side effects in Svelte that depend on multiple reactive variables?', N'Middle', N'You can use a reactive block starting with a dollar sign to group multiple statements. The compiler will automatically track all variables used within that block and re-run the code whenever any of those dependencies change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14c30f01-5ad3-42e2-b6a7-d3ec76de4aa8', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar handle configuration management across different environments?', N'Senior', N'Litestar encourages the use of structured configuration objects that can be injected into the application. By separating environment-specific variables from application logic through these objects, it allows for seamless transitions between development, staging, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4fb9919-2296-4b86-96ca-d3edc83705d0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach a bug that you cannot reproduce locally?', N'Junior', N'I would first review the application logs and error reporting tools to gather specific telemetry about the failure in the remote environment. If logs are insufficient, I would try to simulate the production conditions, such as network latency or specific user permissions, to see if the behavior can be isolated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cd691e7-d969-4b5a-9fe3-d3ee254f3e7e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you ensure your system remains observable after a major architectural migration?', N'Middle', N'I establish a baseline of key performance indicators before the migration and update monitoring dashboards to reflect the new architecture. I also ensure that distributed tracing is configured correctly to track requests as they traverse the new components, allowing for quick diagnosis of latency or errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77a93985-63fb-462d-93d5-d3ef57ec9b36', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How do you handle local state in SolidJS?', N'Fresher', N'Local state is handled using the createSignal primitive. It allows you to create reactive variables that the component can read and update locally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff5cb982-dd51-43a4-8a9c-d3efa147ccd2', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the limitations of Scala''s approach to tail-call optimization (TCO)?', N'Senior', N'Scala''s TCO is restricted to methods that are explicitly marked as final or private, as non-final methods could be overridden in a way that breaks the tail-recursive property. Because the JVM lacks a native bytecode instruction for tail-call optimization, the Scala compiler must rewrite recursive calls into while-loops. This limitation prevents TCO from working across mutually recursive functions or through higher-order functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1094659-e87c-49fc-94df-d3f0df506ba1', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono utilize the Web Standards API?', N'Intern', N'Hono is built upon standard Web APIs such as Request and Response objects, which are native to modern browsers and Edge runtimes. By following these standards, Hono ensures better compatibility and avoids relying on non-standard, legacy Node.js-specific modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0167ec63-f714-4d92-bd7c-d3f1983f6e38', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Explain the significance of the ''Thundering Herd'' problem in cache design.', N'Senior', N'The thundering herd occurs when many processes wake up simultaneously to handle an event or a cache miss, causing a massive spike in resource consumption. This is typically managed by introducing jitter, randomized backoff, or request coalescing to spread the load over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebe4a255-a84e-4b04-acdb-d3f2263fa52e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the common pitfalls when integrating asynchronous tasks into a Flask application, and how are they typically mitigated?', N'Senior', N'The primary pitfall is attempting to run long-running processes within the request-response cycle, which blocks the worker and causes timeouts. This is mitigated by offloading these tasks to a distributed task queue like Celery or RQ, ensuring the Flask worker remains available to handle incoming HTTP traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ca9dadd-8f94-4825-a1e5-d3f43f5d150a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the jQuery .each() method?', N'Intern', N'The .each() method is used to iterate over a collection of jQuery objects. It allows you to execute a function for every element selected by a selector.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4886f10-bb29-4ba7-b299-d3f66fd784f8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the role of the ''defer'' statement in resource management?', N'Middle', N'Defer ensures that a function call is executed immediately before the surrounding function returns, regardless of the exit path. This is crucial for managing resources like file handles or mutex locks, as it guarantees cleanup even when errors occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55bb1e1c-0437-4ccb-811a-d3f7f0a6b324', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a Subscript?', N'Fresher', N'Subscripts are shortcuts for accessing the member elements of a collection, list, or sequence. You can define subscripts for classes, structures, and enumerations to provide simple access to their internal data using square bracket syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f1bd03c-1815-432a-881d-d3f81ef1d464', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Evaluate the security implications of Alpine.js''s use of ''eval'' or ''new Function'' in its directive parsing.', N'Senior', N'Alpine.js evaluates expression strings, which introduces a potential XSS vector if user-generated content is injected into directives. To mitigate this, strict Content Security Policy (CSP) headers must be implemented to disallow ''unsafe-eval'', though this might require using the CSP-compatible build of Alpine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
