INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9aa3578d-df93-4712-9da8-d41bcef8a5fe', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'In what scenarios should you prefer Redis over a traditional relational database for caching?', N'Middle', N'Redis is preferred for caching when low-latency read and write performance is critical, as it operates entirely in-memory. It is ideal for handling high-throughput scenarios like session management, real-time leaderboards, or temporary data storage where the overhead of disk-based relational storage would be prohibitive. However, it should be avoided for complex relational queries or scenarios requiring strict ACID compliance across multiple tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
