INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2963a7b5-096b-4366-97d4-d41eb3d01271', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel protect against CSRF attacks, and why is this protection typically disabled for stateless APIs?', N'Senior', N'Laravel uses encrypted tokens verified against the user session to ensure requests originate from the application itself. It is disabled for stateless APIs (like Sanctum or Passport) because these rely on non-session authentication, such as Bearer tokens, which are not susceptible to CSRF in the same way cookie-based sessions are.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
