INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a83b815-a065-4b41-b379-d42cfc23895b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is Write-Around caching, and in what scenario is it beneficial?', N'Middle', N'Write-Around caching writes data directly to the database while bypassing the cache, only loading data into the cache upon a subsequent read request. This is beneficial for workloads that involve infrequent reads of data that has just been written, as it prevents the cache from being polluted with data that may never be accessed again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
