INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64966f87-04a8-4767-8d56-d4337ff88f52', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the architectural impact of Fiber''s monolithic ''Context'' object?', N'Senior', N'The monolithic context provides a ''batteries-included'' approach, offering helpers for JSON, XML, and template rendering. While this is convenient, it can lead to ''bloated'' interfaces; however, it ensures that all common operations are highly optimized for the underlying engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c77c319e-d779-4203-92d3-d43751d353be', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-offs between using a standard library versus a third-party open-source dependency?', N'Senior', N'I favor standard libraries to reduce external dependencies and simplify security auditing. I introduce third-party dependencies only when they provide mature, well-maintained functionality that solves a complex problem significantly better than a custom implementation, while factoring in the long-term risk of the dependency becoming unmaintained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a169562-c686-4a0a-97a5-d43dc1b9e372', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you determine if a bug is caused by a hardware failure or a software error?', N'Intern', N'You can check system logs for hardware-related warnings or run diagnostic tools provided by the hardware manufacturer to verify physical component health. If the hardware passes these tests and the error occurs consistently during a specific software task, the issue is likely software-related.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3926abb-0800-460e-8b88-d43dc84ab768', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of an entity-relationship diagram?', N'Intern', N'An entity-relationship diagram is a visual representation of the entities within a system and the relationships between them. It serves as a blueprint for designing a database schema before implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
