INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d2716b9-7679-4102-951d-d440cbd44931', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of Quarkus extensions?', N'Junior', N'Extensions are the primary way to integrate third-party libraries and technologies into a Quarkus application. They provide the necessary configuration, build-time integration, and native compilation support to ensure the library works seamlessly within the Quarkus ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'747d4ae9-ff01-4215-b532-d441d15f2fce', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember ensure stability across framework updates?', N'Senior', N'Ember follows a strict ''Deprecation Policy'' where breaking changes are introduced as deprecations in multiple minor releases before being removed in a major version. This gives developers ample time to refactor code, supported by automated ''codemods'' that can migrate the codebase to the newest patterns automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15d15b48-78be-40d9-a53f-d441ee0e68ef', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of a Route in AdonisJS?', N'Intern', N'A route maps a specific URL and HTTP method to a specific controller action or closure. It acts as the entry point that directs incoming traffic to the correct part of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aff870e-80e0-4ba9-869a-d444b6919a0d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go achieve efficient network I/O through the netpoller?', N'Senior', N'The netpoller is an internal mechanism that uses non-blocking I/O and multiplexing system calls like epoll, kqueue, or iocp to monitor network connections. When a goroutine performs a network operation that would block, it yields control back to the scheduler, and the netpoller notifies the runtime when the I/O is ready. This allows a small number of threads to handle thousands of concurrent network connections without blocking the underlying OS threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5c8b374-b281-4dd6-938e-d44989faeef6', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''Tail Latency'' problem, and how can it be mitigated at the architectural level?', N'Senior', N'Tail latency refers to the response time experienced by the slowest percentage of requests, often caused by garbage collection, background tasks, or network jitter. Mitigation strategies include hedged requests, where a second request is sent if the first is slow, and ''tied requests'' to cancel redundant work. Additionally, load balancing algorithms like ''power of two choices'' help distribute load away from overloaded nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93a2286e-02cf-455c-9237-d44ab7e481e9', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why is Astro considered ''framework agnostic'' and what are the implications for a design system team?', N'Senior', N'Astro uses a virtual component interface that allows developers to compose UI components from React, Vue, Svelte, or Solid within the same project. For design systems, this means teams can maintain a unified design language even if different departments prefer different underlying component libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129c7cd3-60ac-4cce-8745-d44b0c02e533', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle conditional rendering?', N'Intern', N'Conditional rendering is handled using standard JavaScript expressions like ternary operators or logical AND operators within JSX. This allows you to show or hide specific parts of the UI based on the current state or props.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'106396c7-5336-4abc-b439-d44cfa4ccf7c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact often described as being more lightweight than React?', N'Intern', N'Preact is designed to be extremely small, usually under 3KB in size, by stripping away features that are rarely used or can be implemented separately. This smaller footprint allows for faster download and parsing times, which is particularly beneficial for performance-sensitive web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b5d9cd3-f767-4fde-bf1e-d44e7a0b7921', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are case classes in Scala and how do they benefit pattern matching?', N'Senior', N'A case class in Scala is automatically equipped with useful features such as apply and constructors for creating instances, unapply to support deconstruction, and more. This makes it ideal for pattern matching, enhancing both readability and maintainability. Key Features - Immutability: Fields are val by default, preventing accidental modification. - Automatic equals() and hashCode(): Encourages safe comparisons and set membership. - Copy Method: Enables immutable update operations while maintaining the original instance''s integrity. - toString: Offers concise textual representation for easy debugging. Code Example: Case Class Here is the Scala code: In this example, copy is used to create a new Person instance with an updated age field.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b0a72ee-2dda-43c9-a6e2-d4542345d2bd', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React handle memory leaks in asynchronous operations?', N'Senior', N'Memory leaks in React often occur when an asynchronous operation attempts to update the state of an unmounted component. Developers should use cleanup functions in useEffect or abort controllers to cancel pending requests or clear timeouts when the component unmounts to prevent state update errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f8e5fb2-ff96-4c58-aa80-d45942e782de', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle static files?', N'Fresher', N'Actix-web provides a built-in static file serving service. By configuring a Files service in the application, the framework can automatically serve files from a specified directory on the server''s filesystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af044a32-b003-4296-bbc4-d45a5a31270b', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the difference between Quarkus and a traditional Java EE framework?', N'Intern', N'Traditional frameworks often perform heavy scanning and configuration at runtime, making them slower to start. Quarkus shifts this configuration to the build phase, resulting in a lightweight runtime that is better suited for microservices and serverless architectures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
