INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6f7b6d1-db3e-4248-ac26-d45df90ab6c3', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust favor explicit error handling via the ''Result'' type over exceptions?', N'Senior', N'Exceptions introduce hidden control flow paths and non-deterministic recovery points that make reasoning about resource cleanup difficult. The ''Result'' type forces the developer to acknowledge and handle potential failures, leading to more predictable and robust code paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
