INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e25f71b6-44a5-4b64-b4e7-d46ac5f21edb', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is middleware in Express?', N'Intern', N'Middleware functions are functions that have access to the request object, the response object, and the next middleware function in the application''s request-response cycle. They can execute code, make changes to the request and response objects, and end the cycle or call the next function in the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08831014-5ee8-4abb-823e-d46b89734e2d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide when to implement database indexing?', N'Junior', N'I implement indexes on columns that are frequently used in search queries, joins, or sorting operations to speed up data retrieval. I balance this by limiting the number of indexes, as they can slow down write operations and consume extra storage space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e2a7cc3-f01b-4cbd-9da3-d46bb337e132', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s architecture influence SEO performance?', N'Senior', N'Qwik produces highly optimized, static HTML that is immediately ready for search engine crawlers. Because there is no client-side hydration phase that could potentially hide content or create empty states, search engines receive a complete and indexable version of the page immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da6be340-143d-4e39-9def-d46e8df2bd67', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of a Bundle in Symfony?', N'Fresher', N'A Bundle is a structured directory that contains a set of files that implement a specific feature, such as user authentication or database management. Bundles are designed to be modular and reusable across different Symfony projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22bb6207-2288-4acc-9ebf-d4723af78d1b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do database locks affect concurrency in a high-traffic system?', N'Middle', N'Locks ensure data integrity by preventing simultaneous modifications, but excessive locking leads to contention and performance degradation. Choosing the right isolation level and keeping transactions short are essential strategies to minimize locking overhead and improve concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c0e7acd-3283-4479-a70d-d478a53af9c9', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the main benefits of using microservices?', N'Senior', N'Let''s look at the main advantages of using microservices: Key Benefits 1. Scalability Each microservice can be scaled independently, which is particularly valuable in dynamic, going-viral, or resource-intensive scenarios. 2. Flexibility Decoupling services means one service''s issues or updates generally won''t affect others, promoting agility. 3. Technology Diversity Different services can be built using varied languages or frameworks. While this adds some complexity, it allows for best-tool-for-the-job selection. 4. Improved Fault Tolerance If a microservice fails, it ideally doesn''t bring down the entire system, making the system more resilient. 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'652b37a2-2ec9-4e78-95f2-d48015141a1c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is inheritance in Java?', N'Intern', N'Inheritance is an object-oriented programming feature where a class derives properties and behaviors from another class. It promotes code reusability by allowing a new class to build upon the foundation of an existing class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4d810fc-26c2-4b30-9285-d488edd83c4a', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What are the limitations of FastAPI''s default dependency injection when handling deep dependency trees?', N'Senior', N'While powerful, complex dependency trees can lead to difficult debugging and performance overhead due to repeated evaluation if not properly cached. Developers should leverage the ''use_cache'' parameter within dependencies to prevent redundant execution of expensive operations within a single request context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cfd12e4-c6d4-4314-a066-d48a5f78e3d4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why might you choose a framework like Fiber over a minimal approach like using only the standard library?', N'Middle', N'Fiber provides a rich set of features out-of-the-box, such as body parsing, template rendering, and powerful routing, which would take significant effort to implement manually. It balances these high-level abstractions with performance that rivals or exceeds simple standard library implementations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa860d5a-1d9f-406f-acc0-d48aabc60b2d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the difference between Router and Mux in Chi?', N'Fresher', N'In Chi, ''Mux'' is the primary implementation of the ''Router'' interface. While you interact with the Router interface for defining routes, the Mux struct is what performs the actual request matching and dispatching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3eb8d8d8-8252-4c8a-a3d9-d48ab7d47336', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between client-side and server-side validation?', N'Junior', N'Client-side validation provides instant feedback and improves user experience by preventing unnecessary network requests. Server-side validation is mandatory for security and data integrity, as client-side checks can be easily bypassed by malicious users or automated tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9357ba1-84af-405b-8fc3-d48b9774ffad', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the advantage of SvelteKit''s file-based routing compared to dynamic configuration-based routing.', N'Senior', N'File-based routing enforces a predictable project structure where the directory hierarchy directly maps to the application''s URL structure. This reduces cognitive load for developers and enables the framework to perform automatic code-splitting based on the route, optimizing the delivery of JavaScript bundles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb7d6e19-1260-4c77-a606-d48e8baf5727', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the architectural implications of PHP''s shared-nothing execution model?', N'Senior', N'The shared-nothing architecture means that every request starts with a clean state, with no memory shared between requests. While this simplifies state management and prevents memory leaks from accumulating across requests, it necessitates external storage mechanisms like Redis or databases to maintain application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cf62bfa-b0e9-4203-bddb-d4954f58630c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go manage the synchronization of global variables across multiple goroutines?', N'Senior', N'Go relies on synchronization primitives like mutexes, atomic operations, or channels to manage shared state, as the language does not provide automatic thread-local or global locking mechanisms. This design places the responsibility of data integrity on the developer, requiring strict adherence to memory model rules to prevent data races in concurrent environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a244810-2193-44d6-9496-d499353c65c5', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the difference between ''localStorage'', ''sessionStorage'', and ''cookies''?', N'Middle', N'Cookies are sent to the server with every request and have size limits and expiration dates. LocalStorage persists data even after the browser is closed until explicitly deleted, while SessionStorage only persists data for the duration of the page session. Use local or session storage for client-side data, and cookies primarily for server-side authentication or tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c196ffdc-215e-4a5d-8e27-d49ca65c08ba', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the difference between ''shallow'' and ''deep'' copies in Ruby and how the GC interacts with them.', N'Senior', N'A shallow copy creates a new object containing references to the same internal objects as the original, whereas a deep copy recursively duplicates the entire object graph. Deep copies are computationally expensive and significantly increase the number of objects the garbage collector must track, potentially leading to increased memory pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4ea799c-49e7-4fd2-865f-d4a3c20b987f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you keep track of your tasks and ensure nothing falls through the cracks?', N'Junior', N'I utilize project management tools like Jira or Trello to maintain a clear list of my tasks, their status, and due dates. I also review my progress at the end of each day to plan my priorities for the following morning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dbd90e6-eddd-4581-9c07-d4a5a65c3e2d', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What strategies are used to ensure API backward compatibility without forcing clients to migrate immediately?', N'Senior', N'Employ additive changes only, such as adding optional fields or supporting multiple versions simultaneously through the gateway. Deprecation headers should be used proactively to warn clients of upcoming removals, while maintaining support for legacy versions until metrics confirm usage has dropped below a threshold.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c30a75e2-d29f-4b8d-8049-d4a70dd23555', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite achieve Hot Module Replacement (HMR) performance?', N'Middle', N'Vite performs HMR over native ESM. When a file is edited, Vite only invalidates the chain between the changed module and its nearest HMR boundary, allowing the browser to fetch only the specific updated module, which is consistently fast regardless of app size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e87b5420-21bc-48c9-b18c-d4a93982f929', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What criteria do you use to choose between a message queue and a streaming platform like Kafka for inter-service communication?', N'Senior', N'I assess the need for message replayability, order guarantees, and the volume of data throughput. Message queues are typically better for simple point-to-point task distribution where processing acknowledgement is required, whereas streaming platforms are superior for high-throughput event sourcing, complex stream processing, and scenarios where multiple consumers need to read the same data stream independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72f6820e-eef5-4981-b0b8-d4ac34a2a17f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the relationship between Qwik and HTML streaming?', N'Fresher', N'Qwik supports HTML streaming, which allows the server to start sending the page content to the browser as it is being rendered. This improves the perceived performance of the page, as users see content appearing as it is generated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dce279f9-3e9b-4fd7-9bdf-d4ac4000b4b2', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''fielddata'' cache differ from ''doc_values''?', N'Middle', N'Doc values are an on-disk column-oriented structure used for sorting and aggregations, providing efficient memory usage. Fielddata is an in-memory structure that resides in the heap and is used for non-analyzed fields; it is generally avoided due to the risk of OutOfMemory errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3da8c260-a880-4405-bc3d-d4ad8ee9fe33', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a header file in C++ and why is it used?', N'Intern', N'A header file is a file with an extension that contains declarations of functions, classes, and variables. It is used to share these declarations across multiple source files, allowing the compiler to understand the structure of the code without needing the implementation details immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2acae44c-38b7-4718-9956-d4ae1b17a6fc', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the updated lifecycle callback?', N'Fresher', N'The updated callback is triggered after the component has finished rendering and updating its DOM. It is the ideal place to perform manual DOM manipulations or run logic that depends on the component being fully rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a398973-4fce-45d1-b987-d4b266eb36f2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When debugging a complex issue, why is it important to change only one thing at a time?', N'Junior', N'Changing multiple variables simultaneously makes it impossible to determine which specific change resolved the issue or if you inadvertently introduced a new one. By isolating variables, you maintain a scientific approach to troubleshooting and ensure the fix is targeted and verified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6b1ca75-1c6d-4d75-9905-d4b343fffae9', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to managing service dependencies during deployment?', N'Senior', N'Ensure backward and forward compatibility for APIs to prevent breaking changes during rolling deployments. Use contract testing to verify that service interactions remain consistent as individual components evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd133ffbb-dc99-44d1-a849-d4b352370253', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Describe the role of ''Task Groups'' in structured concurrency.', N'Senior', N'Task Groups provide a way to create and manage dynamic, concurrent child tasks that must all complete before the parent task finishes. They ensure that all spawned work is accounted for, preventing orphaned tasks and simplifying the management of lifetime and error propagation. This structured approach is fundamental to building scalable, reliable parallel processing systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bf8095f-587b-4a1a-9532-d4b5763ff1b0', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Node in Cassandra?', N'Intern', N'A node is a single instance of the Cassandra software running on a physical server or virtual machine. It is the fundamental building block of a Cassandra cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b855ed34-544a-4d54-bd33-d4b5de9c4940', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do you handle cross-browser compatibility within a Sass-based architecture?', N'Senior', N'Instead of manually writing vendor prefixes, you should use mixins combined with tools like Autoprefixer in your post-processing step. This separates the concern of writing clean, standard CSS from the requirement of ensuring cross-browser support, which is handled automatically based on your target browser list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'beb01608-76c4-4e90-8fb5-d4b735cb6241', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the architectural implications of using HATEOAS in a public API?', N'Senior', N'HATEOAS decouples the client from the server''s URI structure by providing hypermedia links that guide the client through the API''s state transitions. While it increases discoverability and flexibility, it adds significant payload overhead and complexity to client implementations, often leading to it being omitted in favor of strict documentation-driven contracts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'598426d7-ad1d-4a6b-bba4-d4bb6b6135b8', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL implement transaction isolation levels?', N'Middle', N'PostgreSQL uses snapshot isolation to implement its standard isolation levels. Serializable isolation is achieved by using predicate locking to track dependencies and detecting conflicts that would violate serializability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c1f1bab-5cff-4a5d-97da-d4bcf43755d0', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix manage form submissions?', N'Intern', N'Remix leverages standard HTML form behavior, allowing forms to work even if JavaScript is disabled in the browser. When a form is submitted, Remix automatically invokes the corresponding action on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b26dff1f-15d5-4e24-966d-d4c23dfcd3af', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the significance of the Fasthttp engine for Fiber?', N'Fresher', N'Fasthttp is the underlying HTTP engine that powers Fiber. It provides a much faster implementation of the HTTP protocol than the Go standard library, specifically by avoiding the overhead of creating new request/response objects for every single incoming connection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'905b07f1-e753-41e6-b5b4-d4c2aaf6d27b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Column Family in Cassandra?', N'Intern', N'A column family is a container for rows of related columns, analogous to a table in a relational database. It is a collection of rows where each row can have a different number of columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a7a77cc-c491-459a-97b6-d4c48309ad28', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the Django template context?', N'Fresher', N'The context is a dictionary-like object that holds the data passed from the view to the template. It allows the template to access variables and logic defined in the view during the rendering process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2e43b39-60c2-43ba-aa9b-d4c871c17662', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why would you choose to use ''data.table'' over base R data frames for large datasets?', N'Middle', N'data.table is highly optimized for performance and memory efficiency, utilizing in-place modifications to avoid the costly copying behavior of standard data frames. It provides a more concise syntax and significantly faster aggregation speeds on large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01a0665a-8b46-485d-93e3-d4ca7773dfba', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the advantage of using a Write-Ahead Log (WAL) in distributed storage engines?', N'Senior', N'A WAL ensures durability by logging changes to persistent storage before applying them to the data structure. In the event of a crash, the system can replay the log to restore the state, which is significantly faster and more reliable than reconstructing indexes or data files from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45be8f62-fda5-4918-bbe8-d4cb3505d824', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Is Redis single-threaded or multi-threaded?', N'Intern', N'The core of Redis is primarily single-threaded. This design avoids the complexity of locking and thread contention, allowing it to perform very fast operations without overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eeb7286f-2691-4e7c-98d8-d4cb5e208ea4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does class inheritance work with extends and super, and what are the rules around super() in constructors?', N'Fresher', N'The extends keyword establishes two separate prototype chains simultaneously. It links both the instances and the classes themselves. 1. Child.prototype.proto === Parent.prototype — instance method inheritance. 2. Child.proto === Parent — static method inheritance. super is used in two contexts: - In a constructor: super(...args) calls the parent constructor. In a derived class, super() must be called before any access to this. The engine throws ReferenceError if you access this before super() — this is because the parent constructor is responsible for allocating the this object for derived classes. - In a method: super.methodName() calls the parent''s prototype method, enabling cooperative method overriding. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f7bb863-7d05-420b-a27d-d4ce641f69c6', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is a reactive scope?', N'Fresher', N'A reactive scope is a context where the library tracks dependencies for signals. Any function or block that uses signals within this scope will automatically be re-triggered when those signals update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8654a5be-3136-4cff-9ed9-d4d07a98ced3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''Coalescing'' of DOM updates work in modern frontend frameworks to optimize rendering?', N'Senior', N'Frameworks use a virtual DOM or fine-grained reactivity to batch multiple state changes into a single DOM update cycle. This minimizes layout thrashing and reflows, which are computationally expensive processes that occur when the browser recalculates the geometry of elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae076ab5-cdc2-4701-9d36-d4d18cd6b51f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the ''package'' keyword used for?', N'Fresher', N'The package keyword is used to group related files together. It serves as a namespace for code and determines which identifiers are exported to other parts of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21d65886-9a31-4258-b040-d4d33958f7ff', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between stack and heap allocation?', N'Middle', N'Stack allocation is automatic, extremely fast, and has a limited, fixed size controlled by the scope of the function. Heap allocation is manual, slower due to complex management and potential fragmentation, but allows for large or dynamic-lifetime objects that persist beyond the scope of the creating function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c155595a-c6c6-4675-a1a1-d4d5619fd322', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain the role of the Zend VM''s executor in the execution pipeline.', N'Senior', N'The executor is the core loop of the Zend VM that iterates through the opcode array generated by the compiler. It maps each opcode to a corresponding C function implementation, managing the stack, symbol tables, and internal state of the script during execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'718d2441-f5cb-46b4-b89c-d4d6e653cd52', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does the ''mount'' method do in Rocket?', N'Intern', N'The mount method is used to attach a collection of routes to a specific base path in the application. This allows developers to organize routes into logical groups or modules, such as grouping all authentication routes under an ''/auth'' prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e69c40b-af4a-4d5e-8787-d4d9cb898811', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Can you list and explain the basic data types in Go?', N'Junior', N'Go provides a robust set of data types, addressing various data needs efficiently. Primary Data Types - Numeric Types: Integers (int and byte), Floating-Points (float32 and float64). - String: Unicode characters encoded in UTF-8. - Boolean: Represents true/false states. Composite Data Types - Arrays: Fixed-size sequences of elements of the same type. - Slices: Similar to arrays but with dynamic sizing. - Maps: Key-value pairs suitable for quick lookups. - Structs: Encapsulation of various data types inside a single entity. - Pointers: Holds the memory address of a value. Derived/Special Types - Constants: Immutable values known at compile time. - Functions: First-class citizens, enabling higher-order functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38499faf-0e5c-4f43-8574-d4da4b29a835', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the role of the ''preact-render-to-string'' package?', N'Middle', N'This package is used for server-side rendering, allowing Preact components to be rendered into static HTML strings on the server. It is essential for SEO and initial load performance, enabling the server to send a fully formed document to the client before the JavaScript bundle executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'909d491f-37a9-4508-b61b-d4da5c68fd41', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is shallow copy and deep copy in javascript?', N'Intern', N'1. Shallow Copy: Shallow copy is a bit-wise copy of an object. A new object is created that has an exact copy of the values in the original object. If any of the fields of the object are references to other objects, just the reference addresses are copied i.e., only the memory address is copied. A Shallow copy of the object can be done using object.assign() Example: 2. Deep Copy: A deep copy copies all fields, and makes copies of dynamically allocated memory pointed to by the fields. A deep copy occurs when an object is copied along with the objects to which it refers. A Deep copy of the object can be done using JSON.parse(JSON.stringify(object)) Example: &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e51bf9bf-188f-4f70-b992-d4da932074e8', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a ''Gem'' in the context of Ruby on Rails?', N'Intern', N'A Gem is a self-contained package of Ruby code that provides specific functionality to an application. Gems allow developers to share and reuse code efficiently, such as adding authentication, API integration, or pagination without having to build those features from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc32a00d-76ba-4480-9f9c-d4dccda1d35f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why might you use template engines in Express instead of serving static HTML?', N'Middle', N'Template engines allow for server-side rendering, which enables dynamic injection of data into HTML views before they are sent to the client. This is useful for SEO purposes and for applications that require complex server-rendered layouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936a2a98-bddb-4b62-96fc-d4df585c8129', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the ''final'' keyword in PHP class and method declarations?', N'Middle', N'The ''final'' keyword prevents a class from being extended or a method from being overridden. This is useful for enforcing design constraints, ensuring security by preventing modification of core logic, and signaling clear intent to other developers regarding the class''s intended use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e5da15f-48d8-49f0-96f9-d4e0d0f2b596', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the concept of ''Graceful Degradation'' in the context of Laravel''s queue worker failure handling.', N'Senior', N'Graceful degradation involves implementing retry logic, dead-letter queues, and monitoring for failing jobs to prevent a single bad request from crashing the worker process. By configuring max attempts and failed job providers, the system ensures that transient errors don''t cause data loss and that problematic jobs are isolated for manual inspection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06ee3a63-b36c-47e3-bf95-d4e112ba4a28', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between IQueryable and IEnumerable?', N'Junior', N'IEnumerable executes the query on the client side after fetching all data from the database, which can be inefficient for large datasets. IQueryable allows the query to be translated into SQL and executed on the database server, retrieving only the necessary records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8828a4c6-e8b9-427f-8227-d4e1e60690fe', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why is Litestar considered ''opinionated'' regarding type hints and what are the architectural consequences?', N'Senior', N'Litestar enforces strict typing to drive its internal machinery, which leads to a highly consistent and predictable codebase where the API structure is self-documenting. The consequence is a steeper initial learning curve, but it results in significantly fewer runtime bugs and easier refactoring in large systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'381a3097-86e6-4fb3-bba9-d4e81d5f6f0e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the role of ''ElementInternals'' in Lit components?', N'Middle', N'ElementInternals provides a way for custom elements to participate in browser features like forms, accessibility, and focus management. It allows developers to define internal states that the browser recognizes, such as form validity or custom labels, which are otherwise hidden behind the Shadow DOM boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ec4cd72-634b-45f1-b013-d4e9fc497aea', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do aliases improve index management?', N'Middle', N'Aliases provide a layer of abstraction between the application and the index, allowing you to swap indices or perform zero-downtime reindexing. By pointing the application to an alias rather than a specific index name, you can update the underlying data without changing the client code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1a4ea01-fbfe-4ed4-9b8f-d4ebfdcfe8f5', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Options pattern in ASP.NET Core?', N'Middle', N'The Options pattern provides a strongly-typed way to access and configure application settings from configuration files like appsettings.json. By using IOptions, IOptionsSnapshot, or IOptionsMonitor, developers can inject configuration sections directly into services. This approach promotes clean separation of concerns and facilitates easier unit testing by allowing settings to be mocked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fd0e869-caee-4bac-a48b-d4ecae4214dc', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the concept of a ''Saga Pattern'' in microservices.', N'Senior', N'The Saga pattern manages distributed transactions by breaking them into a sequence of local transactions. Each step has a corresponding compensating transaction that rolls back the changes if a subsequent step fails, ensuring eventual consistency without requiring global locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3234410f-e928-4465-ab18-d4ede24a993e', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the risk of hardcoding credentials in an application?', N'Fresher', N'Hardcoding credentials exposes sensitive information to anyone with access to the source code or version control system. If the code is accidentally pushed to a public repository, the credentials could be compromised by malicious actors. It is always better to use environment variables or a dedicated secret management service to keep sensitive data separate from the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5e14bd0-3d31-49fe-9109-d4f2841d9f90', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Commit'' operation in a transaction?', N'Fresher', N'A commit is the command that permanently saves the changes made during the current transaction to the database. Once a transaction is committed, its effects are visible to other users and cannot be undone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b46bdf7-d19a-48b1-8662-d4f57f59d5e4', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are Tag Helpers?', N'Fresher', N'Tag Helpers enable server-side code to participate in creating and rendering HTML elements in Razor files. They make Razor markup look like standard HTML while providing dynamic behavior and data binding capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61bfc5d1-fc53-4041-bcb1-d4f8c14fe7f6', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Compare the security implications of using JWTs versus opaque tokens in a distributed system.', N'Senior', N'JWTs are stateless and allow for decentralized validation, which improves scalability but makes revocation difficult without a blacklist or short expiry. Opaque tokens require a round-trip to an authorization server for validation, introducing latency but providing superior control over immediate token revocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d78607c-d795-4883-95ff-d4f8e7b41e02', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are the restrictions that are applied to the Java static methods?', N'Intern', N'If a method is declared as static, it is a member of a class rather than belonging to the object of the class. It can be called without creating an object of the class. A static method also has the power to access static data members of the class. There are a few restrictions imposed on a static method * The static method cannot use non-static data member or invoke non-static method directly. * The this and super cannot be used in static context. * The static method can access only static type data ( static type instance variable ). * There is no need to create an object of the class to invoke the static method. * A static method cannot be overridden in a subclass Example: This generates a compile time error. The output is as follows −', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72223d08-4ad6-48eb-91d7-d4f8eeb4ce3e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the role of the database buffer pool?', N'Middle', N'The buffer pool is a portion of main memory where the database caches frequently accessed data pages from the disk. By keeping hot data in memory, the database avoids expensive disk I/O operations, which is critical for system performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ab41d3-92b3-42da-b24d-d4fca6a00881', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of the MySQL server?', N'Intern', N'The MySQL server is the core program that manages database files, handles client connections, and executes SQL commands. It acts as the central engine that processes requests and stores or retrieves data from the storage layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1254856-c1de-4c37-a0d3-d4fcdcac62b1', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it important to define a virtual destructor in a base class?', N'Middle', N'If a base class does not have a virtual destructor, deleting a derived class object via a base class pointer will result in undefined behavior because the derived class destructor will not be called. Defining it as virtual ensures the full destruction chain is executed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36d5ae50-b8ee-470c-85c5-d4fdb84dde3d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you are tasked with debugging a system that is failing intermittently, what is your first step?', N'Intern', N'The first step is to establish a reliable way to reproduce the issue consistently. I would gather logs, timestamps, and environment details to identify patterns that correlate with the failure before attempting any fixes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'296bd9b6-6f38-44e1-a690-d4ffd850f69f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when implementing blue-green deployment versus canary releases?', N'Senior', N'Blue-green deployment allows for near-instant rollback and full isolation between environments but requires double the infrastructure capacity. Canary releases minimize blast radius for new features by exposing them to a subset of traffic, but they require sophisticated traffic routing and real-time monitoring to detect regressions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ae69587-e125-437b-a5e4-d5013fc1dd69', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you ensure your work is secure against common vulnerabilities like SQL injection?', N'Fresher', N'I would use parameterized queries or prepared statements, which separate the SQL command from the data provided by the user. This prevents the database from interpreting user input as part of the query, effectively neutralizing attempts to inject malicious commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6212fcb-21a6-43cb-9c6c-d5018cf5060b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is data redundancy and why is it generally discouraged?', N'Fresher', N'Data redundancy occurs when the same piece of data is stored in multiple places. It is discouraged because it wastes storage space and increases the risk of data inconsistency, where one record is updated while its duplicates remain outdated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c22efb65-6dca-455a-b77e-d5036ee9c880', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''by-name'' and ''by-value'' parameters in Scala?', N'Senior', N'By-value parameters are evaluated once before entering the function, while by-name parameters are evaluated every time they are accessed within the function body. By-name parameters are essential for implementing custom control structures or lazy evaluation logic without needing explicit function wrapping. This distinction is fundamental for performance, as it allows for conditional execution of expensive logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22fb9ba3-6fec-47ff-bfc6-d505075529b6', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Describe the architectural benefits of using the ''CQRS'' pattern within a NestJS application.', N'Senior', N'CQRS separates the read and write models, allowing for independent scaling and optimized performance for each. In NestJS, this is often implemented using a mediator pattern, which decouples command/query handlers from the transport layer, resulting in a system that is easier to test, maintain, and evolve.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'171c557b-44c0-48d5-a0e0-d505838d94cd', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the benefit of using Gin''s built-in validation?', N'Junior', N'Gin uses the ''validator/v10'' package, which allows you to use struct tags to enforce rules like ''required'', ''email'', or ''min/max''. This eliminates the need for writing manual, repetitive checks in your handler logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
