INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a482bb21-302c-4cf7-b313-d5061ae2d092', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the architectural role of the ''context API'' in Svelte, and when should it be preferred over stores?', N'Senior', N'The context API is designed for sharing state between a component and its descendants without prop drilling. It should be preferred for static or configuration data that is set once, whereas stores are superior for dynamic, globally accessible state that changes frequently over the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
