INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e1721b8-0e7b-4c66-9612-d50f7f86525b', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are some of the data structures supported by Redis?', N'Intern', N'Beyond simple strings, Redis supports complex data structures such as lists, sets, sorted sets, hashes, and bitmaps. This flexibility allows it to handle various application requirements more efficiently than a basic key-value store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7df9d357-f942-486f-834e-d5103ac9a675', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the purpose of the ''Request'' object in FastAPI?', N'Fresher', N'The Request object allows you to access details about the incoming HTTP request, such as headers, cookies, query parameters, and the body. It is useful when you need to inspect or process information that is not automatically handled by type hints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25a0fb90-ac52-4033-8480-d511fc1977a5', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does the ''write-ahead logging'' (WAL) protocol ensure ACID compliance?', N'Senior', N'WAL ensures durability by requiring that all modifications are recorded in a persistent transaction log before they are applied to the actual data files. This allows the database to reconstruct state after a crash by replaying committed logs or rolling back uncommitted changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0798126-b506-4d6f-aff2-d5120ce04f30', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle middleware execution order, and what are the architectural implications for request lifecycle management?', N'Senior', N'Gin uses a chain-of-responsibility pattern where middleware are executed sequentially in the order they are registered. Each handler calls the next function in the chain, allowing for pre-processing of requests and post-processing of responses, which is critical for logging, recovery, and authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c5b5009-f6b5-4df1-a30d-d514ae1e0e84', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why might you choose optimistic locking over pessimistic locking?', N'Junior', N'Optimistic locking is generally more efficient in systems with low contention because it avoids the overhead of managing locks. It allows higher concurrency because records are not held for long periods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cb1f8e1-0020-4a45-a305-d515ae3d6178', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle concurrency in a way that differs from thread-per-request models?', N'Middle', N'Phoenix leverages the Erlang VM, which uses lightweight processes to handle concurrency. Instead of blocking threads, Phoenix can manage millions of concurrent connections efficiently because each request or channel is isolated within its own lightweight process, preventing a single failure from crashing the entire server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9adffde-3488-437b-abd6-d51692dbf185', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Does Fiber support grouping of routes?', N'Fresher', N'Yes, Fiber allows developers to group routes that share a common prefix. This is useful for organizing code, such as grouping all API version 1 routes under a single path prefix.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8720671-4918-4e7e-85d4-d517da4b425e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between technical debt and product delivery velocity?', N'Senior', N'I treat technical debt as a financial loan, assessing the interest rate based on how much it slows down future development versus the immediate market advantage of shipping early. I advocate for a structured ''debt ceiling'' where a fixed percentage of each sprint is dedicated to refactoring, ensuring that velocity does not permanently plummet due to unmanaged complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ee207ef-ea24-44e0-be40-d51a9e98dd0b', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the concept of CSS specificity and how the browser resolves conflicts.', N'Middle', N'Specificity is a weight calculation the browser applies to selectors to determine which styles take precedence when multiple rules target the same element. It follows a hierarchy based on the types of selectors used, such as IDs, classes, and elements, with inline styles holding the highest weight. If specificity is equal, the browser applies the last rule defined in the stylesheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2971b776-331b-45f7-a69f-d51acbbc19c7', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the method collect()for streams for?', N'Intern', N'A method collect()is the final operation that is used to represent the result as a collection or some other data structure. collect()accepts an input that contains four stages: * supplier — initialization of the battery, * accumulator — processing of each element, * combiner — connection of two accumulators in parallel execution, * [finisher] —a non-mandatory method of the last processing of the accumulator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25430102-3729-4dc6-b667-d52028c3665c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the danger of ''fix-and-forget'' when troubleshooting?', N'Intern', N'Fixing an issue without documenting the root cause or updating the system''s documentation creates a knowledge gap. This increases the likelihood that the same issue will return, and future team members will have to waste time solving the same problem from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a758af3f-882a-42f2-8685-d520c767cfe6', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does an ''Index-Only Scan'' differ from a standard index scan?', N'Senior', N'An index-only scan retrieves all requested data directly from the index structure without needing to fetch the actual table heap. This reduces random disk I/O, though it requires that the index contains all columns requested in the query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab492048-09d3-480b-b085-d52288fe9117', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the risks of over-engineering Sass mixins?', N'Senior', N'Over-engineering results in complex, hard-to-read code that is difficult for other team members to maintain or debug. It can also lead to bloated CSS output if the mixin generates too much boilerplate code, ultimately negating the benefits of modularity and reusability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37acf9f2-65c6-4dfc-ad33-d523bf103e75', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between ''print'' and ''cat'' in R?', N'Intern', N'Print is a generic function that displays an object along with its index or structure, while cat is used to concatenate and print character representations of objects. Cat is generally preferred for creating custom messages or writing strings to files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc459e97-fa8b-41d1-9628-d526d61c272a', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the concept of ''lazy'' initialization in Alpine.js.', N'Middle', N'Lazy initialization refers to delaying the Alpine framework''s startup until a specific point in the page lifecycle. This can be used to prioritize critical content loading before adding interactivity, improving the Core Web Vitals of the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb4ab9bb-0de1-4a8a-9fd2-d5270647d93d', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the difference between ''map'' and ''flatMap'' in the context of monads?', N'Middle', N'Map applies a transformation to the value inside a container, resulting in a nested structure if the transformation also returns a container. FlatMap performs the same transformation but flattens the result, preventing the creation of nested structures like Options within Options.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c2b6a45-c9eb-43f0-bbb7-d52b059751d9', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the main advantage of using a strongly-typed language like C#?', N'Intern', N'A strongly-typed language helps catch type-related errors at compile time rather than at runtime. This leads to more reliable code and better tool support, such as IntelliSense, during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58a29022-c278-478b-a84f-d52b08922cb4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you determine if an object is sealed or not', N'Fresher', N'The Object.isSealed() method is used to determine if an object is sealed or not. An object is sealed if all of the below conditions hold true 1. If it is not extensible. 2. If all of its properties are non-configurable. 3. If it is not removable (but not necessarily non-writable). Let''s see it in the action', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2165ebc0-aeec-48d1-990b-d52b8fc9bc46', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the risk of ''Split-Brain'' in a clustered database environment.', N'Senior', N'Split-brain happens when a network failure causes a cluster to partition, leading both sides to believe the other is down and both to elect a primary node. This creates conflicting writes and data divergence, requiring fencing mechanisms or majority-quorum logic to force one side to become read-only.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd70f18a6-83fb-4d52-bf98-d52e08b82955', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How many kinds of sequences are supported by Python? What are they?', N'Fresher', N'Python supports 7 sequence types. They are str, list, tuple, unicode, byte array, xrange, and buffer. where xrange is deprecated in python 3.5.X.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd42826c-ea8e-44fb-9222-d533132f8399', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is documentation important when using a framework like Fiber?', N'Intern', N'Documentation provides guidance on how to use the framework''s features, available methods, and best practices. It is crucial for interns to understand the framework''s capabilities and avoid common pitfalls during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c7c427-8776-48a6-b5ee-d533175231be', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of a translation unit in C compilation?', N'Senior', N'A translation unit is the result of the preprocessor expanding a source file, including all headers, into a single stream of code. It is the fundamental unit of compilation that the compiler processes independently to produce an object file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd000c0e5-c5ae-4e6f-82a2-d5332ce6db71', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you scale out a message broker when the number of partitions exceeds node capacity?', N'Senior', N'Scaling out involves rebalancing the partition distribution across a larger cluster of brokers. This process requires moving data between nodes, which can cause transient performance degradation while the cluster re-syncs to the new topology.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aedc9fc4-a74e-4327-9b03-d533b17f91e8', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Is Webpack required to run a website?', N'Intern', N'No, Webpack is a build tool, not a requirement for the browser. A website can function without a bundler, but Webpack is used to manage complex dependencies and optimize performance in modern professional applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55711966-3bf9-4b08-8695-d534b4e52767', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js facilitate communication between components?', N'Senior', N'Communication is primarily achieved through event dispatching using the native browser event system or by sharing a common global store. This decoupled approach is effective for small-to-medium applications but can become difficult to track as the number of cross-component interactions scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f742542e-fbb7-4ffa-b1a0-d537546601a8', N'954a0331-deff-4399-b588-96f39fec001d', N'What are decorators?', N'Intern', N'Decorators in Angular are special kinds of declarations that can be attached to classes, methods, properties, or parameters. They are a TypeScript feature that provides a way to add metadata to code elements. Angular uses decorators extensively to configure classes and their members, telling Angular how they should be processed, instantiated, or interacted with. For example: - @Component tells Angular that a class is a component and provides configuration like its template, styles, and selector. - @Injectable tells Angular that a class can be injected into other classes, making it part of the dependency injection system. - @Input marks a property as an input binding, allowing data to flow into a component from its parent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cf41408-102d-4890-9281-d5379d204c29', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the role of the Redo Log in crash recovery?', N'Senior', N'The Redo Log is a write-ahead log that records changes to data pages; during recovery, InnoDB replays these logs to ensure that committed transactions are not lost even if they were not yet persisted to the main data files. It effectively converts random disk updates into sequential writes for durability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'533cd0dc-4957-4de7-98eb-d5383a7957ca', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the typical use case of portals?', N'Intern', N'React Portals are primarily used to render UI components such as modals, tooltips, dropdowns, hovercards, and notifications outside of their parent component''s DOM tree. This helps avoid common CSS issues caused by parent elements, such as: * overflow: hidden on parent elements clipping or hiding child elements like modals or tooltips, * stacking context and z-index conflicts created by parent containers that prevent child elements from appearing above other content. That means, you need to visually “break out” of its container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99a18461-fd2b-4d56-917f-d53d4f238fb0', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the ''when'' expression differ from a ''switch'' statement?', N'Junior', N'The ''when'' expression is more powerful than a traditional switch statement because it can match against ranges, types, and complex conditions. It also functions as an expression that returns a value, rather than just a control flow statement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62e825fd-afbd-433a-a3e5-d5411f75148a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s routing mechanism handle path parameters, and what is its performance profile compared to a linear search?', N'Senior', N'Echo uses a radix tree (prefix tree) for routing, which provides O(k) lookup time where k is the length of the path. This is significantly more efficient than linear searching, especially as the number of routes grows, making it suitable for large-scale microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'846ac93a-5d0d-4794-ad9e-d5414925c4e1', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a stack and the heap in C++ memory management?', N'Intern', N'The stack is a region of memory that stores local variables and is managed automatically by the compiler, meaning memory is allocated and freed in a predictable order. The heap is a larger pool of memory used for dynamic allocation, where the programmer is responsible for manually allocating and deallocating memory as needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'968b7ddf-ac17-4143-9627-d54250c2e4a8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''Nothing'' type?', N'Intern', N'The ''Nothing'' type is a subtype of every other type in Scala and has no instances. It is typically used to represent the return type of methods that never terminate normally, such as those that throw exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a1ddddf-c1cb-4e82-912d-d547a15e28ce', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Can Remix be deployed on edge networks?', N'Junior', N'Yes, Remix is designed to run in edge environments like Cloudflare Workers or Vercel Edge. Its reliance on standard Web APIs makes it highly efficient for deployment on global, distributed server networks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c005c92-955a-426c-8c12-d54b0837f098', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a data frame in R and why is it important?', N'Intern', N'A data frame is a two-dimensional, table-like structure used to store data where each column can contain different types of data. It is the standard way to store datasets in R, making it essential for performing operations on structured information similar to a database table or a spreadsheet.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc8c6c5d-1123-4293-97fc-d54b80e00037', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is a data frame in R and why is it used?', N'Fresher', N'A data frame is a two-dimensional, table-like structure used to store data where each column can contain a different data type. It is the most common data structure for statistical analysis because it allows for the organization of variables in columns and observations in rows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d6af58a-8928-4af5-bfa6-d54df21c8cae', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between Kestrel and IIS in the context of ASP.NET Core?', N'Intern', N'Kestrel is a cross-platform, lightweight web server included by default in ASP.NET Core to handle incoming HTTP requests directly. IIS is a full-featured web server used on Windows environments that often acts as a reverse proxy, forwarding requests to Kestrel for processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'848a391f-edce-4ac4-a60f-d54eb8e43413', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle breaking changes in an existing public API?', N'Junior', N'I avoid breaking changes by using versioning in the URL or headers. If a change is unavoidable, I maintain the old version for a grace period while notifying users, allowing them time to migrate to the new version before the deprecated one is removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad0947dd-bb1d-4f5f-a53c-d54fbe670e95', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it generally better to use classes over IDs for jQuery selectors?', N'Intern', N'Using classes allows for more flexibility and reusability, as multiple elements can share the same class. IDs are intended to be unique, making them less suitable for scripts that need to manipulate groups of similar elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0d1cb4f-1a7a-4b2f-adea-d554b75b4c76', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you debug a production issue where a service is intermittently failing with connection timeouts despite showing low CPU and memory usage?', N'Senior', N'I would investigate the connection pool saturation and downstream dependency availability, checking if the service is hitting socket limits or experiencing TCP backpressure. I would also examine firewall rules, load balancer health check patterns, and potential upstream network partitions that might be causing silent packet loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e6382a8-ddb8-4f82-b1fe-d5553998d1da', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between local and global scope?', N'Fresher', N'Variables declared outside a function have global scope and can only be accessed outside functions. Variables declared inside a function have local scope and can only be accessed within that specific function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b910ea45-77ab-4dad-be4b-d555b26bc332', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is a ''single source of truth'' in system design and why is it important?', N'Intern', N'A single source of truth ensures that a specific piece of data is stored and managed in exactly one location. This prevents inconsistencies, duplication, and synchronization errors that can occur when the same information exists in multiple places.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afce5328-a3e5-4fa9-9e7a-d558cd74559c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle URL parameters, and why is this approach preferred over query parameters for resource identification?', N'Middle', N'Chi uses path parameters defined in the route pattern, which are then extracted into the request context for easy access. This approach is preferred for resource identification because it creates clean, semantic URLs that follow RESTful design principles, making the API more intuitive and easier to cache compared to using complex query strings for primary resource lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afdc6f1b-7a86-49b4-be28-d55970817dbc', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does it mean for Remix to be ''web-standard'' centric?', N'Intern', N'Being web-standard centric means Remix relies on built-in browser APIs like Request, Response, and URL objects rather than custom framework-specific abstractions. This makes the knowledge gained in Remix transferable to general web development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dad551f0-d02f-4ee4-92ff-d55a8a32e2fa', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'When would you prefer using a Custom Provider with ''useFactory'' over a standard class-based provider?', N'Senior', N'Use ''useFactory'' when the provider depends on other services that must be resolved dynamically or when the provider requires complex initialization logic based on configuration. It is essential for injecting values from external sources like environment variables or database connections that aren''t available at compile-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'186ff0bd-f54d-4048-9ef9-d55f0513be85', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Describe the impact of ''inlining'' on Go''s runtime performance.', N'Senior', N'Inlining eliminates the overhead of function calls and allows the compiler to perform cross-function optimizations. It is a critical performance factor in Go, though the compiler is conservative with inlining to keep compilation times fast and binary sizes manageable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c97bcc22-f447-49d9-b6d2-d56369ee5db0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens when you delete a document in Elasticsearch?', N'Junior', N'When a document is deleted, it is not removed immediately. Instead, Elasticsearch marks it as deleted in a .del file, and the space is reclaimed during the segment merging process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16201a5c-1c8e-41c5-9f07-d5678efcd3d6', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''exports'' array in a module?', N'Junior', N'The exports array makes specific providers within a module available for use by other modules that import it. Without exporting a provider, it remains private to the module where it is defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58f25906-4f19-4166-88df-d5697de1de04', N'075b8862-431c-4678-9767-f55359758a4a', N'What is a Vue instance and its purpose?', N'Intern', N'The Vue Instance serves as the entry point for Vue applications, acting as the core engine that controls and coordinates the entire application. Core Functions The Vue Instance offers key functions, including: Data Management - Data: Houses the application''s state, organized as key-value pairs. Changes to data are automatically reflected across the application. - Computed Properties: Derive new data from existing app state, ensuring reactivity and performance gains. - Watchers: Track specific data points (or computed properties) for changes, enabling additional actions or logic. Lifecycle Management - Lifecycle Hooks: Provides customized behaviors at key application stages, such as when a component is created, mounted, updated, or destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a72bc50d-c4df-4a11-9698-d56d8470ceb7', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are the implications of using Django’s ''save'' method for performing complex business logic?', N'Senior', N'Overriding the ''save'' method can lead to issues because it is not always called during bulk operations or certain ORM updates, leading to inconsistent business rule enforcement. Complex logic should be encapsulated in service layers or model managers rather than inside the save method to ensure consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74a638d2-403f-496c-a5d1-d56db5f88f09', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a function signature in TypeScript?', N'Fresher', N'A function signature defines the types of the parameters a function accepts and the type of the value it returns. It provides a contract that ensures the function is called with the correct arguments and handles the return value appropriately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'548b9e2b-9b78-459a-9bef-d5738089f7e8', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the significance of the ''concurrency is not parallelism'' mantra in Go design?', N'Senior', N'This principle highlights that concurrency is a way to structure a program to handle multiple tasks, while parallelism is the act of running multiple tasks simultaneously on multiple cores. Go provides primitives to express concurrency easily, letting the runtime decide how to distribute that work across available parallel hardware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2100dfac-8445-4c4a-9b94-d574b8756141', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is LIBUV needed in Node JS?', N'Fresher', N'libuv is a cross-platform C library that gives Node.js its ability to perform non-blocking, asynchronous I/O — the core of everything Node.js does efficiently. It provides the following features: * It allows the CPU and other resources to be used simultaneously while still performing I/O operations, thereby resulting in efficient use of resources and network. * It facilitates an event-driven approach wherein I/O and other activities are performed using callback-based notifications. * It provides mechanisms to handle file system, DNS, network, child processes, pipes, signal handling, polling and streaming * It also includes a thread pool for offloading work for some things that can''t be done asynchronously at the operating system level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27e42840-ba9d-4258-8a1e-d5753a639f97', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are the performance implications of Hono''s middleware system?', N'Middle', N'Hono''s middleware is designed to be lightweight with minimal initialization overhead. Because it relies on standard objects and avoids complex wrapping, the performance impact per middleware is significantly lower than in older frameworks like Express.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c14961ef-752a-491b-b9ee-d5780c3c9908', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the use of Promise.any()?', N'Fresher', N'The Promise.any() method is used to handle multiple promises simultaneously, and it resolves with the value of the first fulfilled promise.regardless of whether any of the other promises reject. If all of the promises reject, then Promise.any() rejects with an AggregateError object that contains an array of rejection reasons. The Promise.any() method takes an iterable of Promises as an input, and returns a new Promise. Here''s an example: Example: *Note: Promise.any() is supported in all modern browsers since 2021.*', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2a42160-633b-478c-87e8-d578b2d27140', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between @mixin and @function in Sass?', N'Middle', N'A mixin is designed to generate and output CSS blocks, making it ideal for reusable component styles or vendor-prefixed properties. A function is intended to perform calculations or data manipulation and returns a single value, such as a color or a unit, to be used within properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1fad855-3fa4-4f0e-a63c-d5792ad3753a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the impact of including the full jQuery library for simple tasks like class toggling?', N'Middle', N'Including the entire library adds unnecessary file size and parsing time for tasks that can be handled by native methods like classList. In modern web development, this contributes to poor Core Web Vitals and slower initial load times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a71e6fa7-0f1b-4fb4-b77a-d57ac07be50d', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the primary difference between normalization and denormalization in database design?', N'Middle', N'Normalization is the process of organizing data to reduce redundancy and improve data integrity by splitting tables. Denormalization is the strategic introduction of redundancy to improve read performance by reducing the number of complex joins required for queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b9afb89-4922-4c5f-813c-d57add42aeb7', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why React tab is not showing up in DevTools?', N'Fresher', N'When the page loads, _React DevTools_ sets a global named REACT_DEVTOOLS_GLOBAL_HOOK, then React communicates with that hook during initialization. If the website is not using React or if React fails to communicate with DevTools then it won''t show up the tab.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcb8f7c0-28ea-4fda-9a2e-d57d793ec6a2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are the performance implications of Astro''s zero-bundle-by-default philosophy?', N'Senior', N'By stripping all JavaScript by default, Astro eliminates render-blocking execution and minimizes payload size. This directly correlates to improved Core Web Vitals, specifically Largest Contentful Paint and Total Blocking Time, by ensuring the browser only processes the minimal code required for interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'164fbc5a-b7d3-44f6-8b1d-d57d9ccfce35', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why is it recommended to place script tags at the end of the body?', N'Junior', N'Placing script tags at the end of the body allows the browser to parse and render the HTML content before executing the JavaScript. This prevents the page from appearing blank or frozen while waiting for heavy scripts to load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3821361d-43ed-4208-83dc-d57f5b4eddac', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of an App in Actix-web?', N'Fresher', N'The App object is the central structure in Actix-web used to configure the application, define routing, and register middleware. It acts as the container for all the routes and services that your web server exposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df699c74-a951-4fba-8a2d-d57ffca3f843', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you ensure service discovery in a highly dynamic, containerized microservices environment?', N'Senior', N'You utilize a dedicated Service Registry where instances register their health and location upon startup. Clients or load balancers query this registry to discover healthy instances, abstracting the underlying network IP changes caused by orchestration platforms like Kubernetes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b24f6477-bb22-4da7-b9aa-d5828b3d795f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why does Fastify use schemas for serialization?', N'Junior', N'Fastify uses schemas to serialize output data into JSON, which is significantly faster than using the native JSON.stringify method. By knowing the structure of the data beforehand, Fastify can pre-compile a function to generate the response string, reducing CPU cycles per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ac09e98-c327-474a-9bed-d58b8cec4295', N'4c000000-0000-0000-0000-000000000005', N'What is the significance of the ''Backpressure'' pattern in streaming systems?', N'Senior', N'Backpressure allows a consumer to signal to a producer that it is overwhelmed, preventing memory overflow and system crashes. Without it, high-velocity producers can easily saturate the buffers of slow consumers, leading to data loss or total system collapse.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93f6f9bb-176d-460f-9cc8-d58c71ed7a67', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of Write-Ahead Logging (WAL) in database systems?', N'Senior', N'WAL ensures durability and atomicity by requiring that all modifications be written to a persistent log on disk before the actual data pages are updated. This allows the system to recover the state of the database after a crash by replaying committed transactions from the log.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc66ed3-b18d-4ca4-b867-d58e13fd1e8d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the importance of feedback loops during the engineering process?', N'Intern', N'Feedback loops allow for early detection of issues and course correction before a project becomes too expensive or complex to change. Whether through peer reviews or user testing, feedback ensures the work remains aligned with requirements. It turns the development process into an iterative cycle rather than a rigid, linear path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'636c67a3-0ac3-4133-ba8f-d58f9a241d25', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the primary purpose of the Dart programming language?', N'Intern', N'Dart is a client-optimized programming language designed for building fast apps on any platform. It is primarily used for cross-platform development, particularly with the Flutter framework for mobile, web, and desktop applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd841359c-167f-478d-8ba3-d58fcf09d926', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Why is observability important in microservices architecture?', N'Middle', N'In distributed systems, debugging a single request can be difficult as it touches multiple services. Observability, through distributed tracing and centralized logging, provides the visibility needed to identify bottlenecks and locate the root cause of failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5f3479e-7394-487e-87b3-d5903a830039', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the concept of ''split-brain'' in an Elasticsearch cluster.', N'Middle', N'Split-brain occurs when a network partition causes the cluster to split into two groups, each electing its own master node. This leads to data inconsistency and corruption, which modern Elasticsearch prevents using proper discovery settings and quorum-based voting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6d11f97-9387-421f-a2f4-d59298ae60c3', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your approach to handling a production outage?', N'Junior', N'I would follow the team''s incident response protocol, which usually involves helping to identify the root cause and potentially reverting the last change. I stay calm, assist where needed, and focus on restoring service for users before performing a post-mortem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aff82ffb-8b63-44cb-93b7-d59816d44d19', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the performance implications of using barrel files in a large Vite-based project?', N'Senior', N'Barrel files can significantly increase the module graph size and slow down HMR because changing a single file can trigger updates across the entire barrel dependency chain. In large projects, it is often better to import specific files directly to improve build efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90cf62ba-e15c-40cc-9630-d5983fe0300b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass variables and how do they help?', N'Fresher', N'Sass variables allow you to store reusable information like colors, font stacks, or spacing values. If you need to change a global value, you only update it in one place, and it propagates throughout your entire project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'375fa617-e800-40c4-b868-d5987c9c3a59', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the function of the workspace in R?', N'Junior', N'The workspace is the current R working environment that stores all user-defined objects such as variables, functions, and data sets. These objects persist in memory during an active session until they are explicitly removed or the session is terminated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb7590d5-9a2b-4ad0-8d6e-d59b151d2674', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the advantage of using ''Flask-RESTful'' or ''Flask-RESTX'' over standard Flask routes for APIs?', N'Middle', N'These extensions provide a structured way to define resources and methods, automatically handle request parsing, and generate documentation like Swagger/OpenAPI. They enforce a more consistent API design compared to writing raw route functions, which can become messy and redundant as the API surface area grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a76c0962-ed40-4b82-8931-d59c48547eda', N'075b8862-431c-4678-9767-f55359758a4a', N'Discuss the strategy for code splitting and lazy loading components in a large Vue application.', N'Senior', N'Code splitting is achieved using dynamic imports, which allow Vue to split the application bundle into smaller chunks that are loaded on demand. This improves initial load time, and these components are integrated seamlessly using the defineAsyncComponent utility to handle loading and error states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e1f8ce3-700c-48c5-b64e-d59d55b67503', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between modularity and integration overhead?', N'Intern', N'Breaking a system into small, independent modules improves testability and team autonomy. However, it also increases the overhead of managing communication between those modules and ensuring they integrate seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6aec16ea-2d8c-49e6-9470-d59f16029113', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle secret management in a distributed environment to minimize the blast radius of a credential leak?', N'Senior', N'I utilize a centralized secret management service that provides dynamic, short-lived credentials with limited scopes. I also ensure that secrets are rotated automatically and are never hardcoded or stored in version control, reducing the impact if a specific service is compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92b69638-f1b4-44df-8d02-d59f7b640cc4', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of metadata json files?', N'Intern', N'The metadata.json file can be treated as a diagram of the overall structure of a decorator''s metadata, represented as an abstract syntax tree(AST). During the analysis phase, the AOT collector scan the metadata recorded in the Angular decorators and outputs metadata information in .metadata.json files, one per .d.ts file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83eb8e13-979f-4d92-836b-d59f7cc3fcd6', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the function of the ''vendor'' directory?', N'Fresher', N'The vendor directory contains all the dependencies and packages installed via Composer. These are external libraries that Laravel uses to provide its various features and functionalities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ab942b-f581-426e-ac0d-d5a4523f0c96', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is a PHP interface?', N'Intern', N'An interface is a template that specifies which methods a class must implement, but does not define how those methods work. It allows different classes to share the same structure without sharing the same implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037064bb-b79a-4545-9b57-d5a4e4d23cca', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What does the For component do, and why is it preferred over array.map?', N'Junior', N'The For component is a specialized control flow utility for rendering lists. It is optimized to track individual items and perform minimal DOM updates when the array changes, whereas array.map would re-render the entire list.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fd7dcc9-3583-4c58-864d-d5ad66a05935', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to keep the team informed during a major troubleshooting effort?', N'Fresher', N'Keeping the team informed prevents redundant effort where multiple people might try to solve the same problem simultaneously. It also helps manage expectations regarding downtime and provides visibility into the status of the resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f179dbe1-ebac-48d4-afee-d5ae233b41b6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the performance impact of the Rails middleware stack on request processing.', N'Senior', N'Every request passes through the entire middleware stack before reaching the controller, which adds overhead for every layer. To optimize, you should remove unnecessary middleware from the stack and utilize faster, specialized proxies like Nginx to handle static assets or simple request filtering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bd2f828-a105-405b-8287-d5b00c8aa49c', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a scenario where a third-party dependency is causing intermittent system instability?', N'Senior', N'I first implement a fallback or circuit breaker to isolate the dependency and protect my system. Then, I work on a long-term solution such as creating an abstraction layer to replace the dependency or collaborating with the vendor to resolve the instability while monitoring the impact via telemetry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'017d1e1a-9a0a-4160-9e08-d5b12d2818b5', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate the number of windows in a skyscraper, how would you approach the problem?', N'Intern', N'I would break the problem down by estimating the number of floors, the number of windows per floor based on the building''s perimeter, and then multiplying those figures. I would also account for external factors like the building shape and omit non-window areas like the lobby or roof.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd71a0f85-ea76-4419-b741-d5b1c934b8cf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What role do logs play in the debugging process?', N'Intern', N'Logs provide a historical timeline of events, system states, and errors that occurred leading up to a failure. They are essential for reconstructing the sequence of events and identifying the state of the system when an issue was triggered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb9c7a7e-76d1-4617-90c4-d5b20cc78974', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does a service mesh enhance security in a microservices architecture?', N'Middle', N'A service mesh manages service-to-service communication, often providing automatic mTLS, traffic encryption, and centralized policy enforcement for authorization. It removes the burden of implementing these complex security features from individual service developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b66b73ac-eba9-4640-80a0-d5b2bb3609b8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What does ''Lazy Evaluation'' mean in Scala and when should it be used?', N'Middle', N'Lazy evaluation delays the computation of a value until it is first accessed. It is useful for improving performance in cases where a value might not always be needed or to break circular dependencies during initialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b8aa3c4-0e20-4773-941a-d5b31d6357e5', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a manifest file in Webpack?', N'Intern', N'A manifest file is a JSON file that maps your original file names to the final, hashed bundle names. This is useful for server-side applications to know exactly which files to include when a request is made.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec477160-1907-47cf-9c9c-d5b65da0bede', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a static file and a template in Flask?', N'Intern', N'Static files, like CSS, JavaScript, or images, are served directly to the browser without modification. Templates are HTML files that contain placeholders which are filled with dynamic data by the server before being sent to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
