INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34734a13-1e71-44b1-a09b-d5b88843a5f5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle ''backpressure'' in real-time channels?', N'Middle', N'Phoenix uses the underlying Erlang process mailbox mechanism to handle backpressure. If a process is overwhelmed, its mailbox grows, and the system can apply backpressure by slowing down the producers or using transient error responses until the consumer catches up.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5e44199-954d-469a-9e17-d5b942c31cb4', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''untrack''?', N'Junior', N'Untrack is a utility that allows you to access a signal''s value without creating a reactive dependency. This is useful when you want to read a value inside an effect or a memo without triggering a re-run when that specific signal changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
