INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e91df029-9a16-46ab-98ad-d5bb675d44f7', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is connection pooling and why is it important for scaling?', N'Middle', N'Connection pooling maintains a cache of open database connections that are reused for future requests. It avoids the high overhead of establishing a new TCP connection for every database query, significantly reducing latency and resource consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c82ca56-2d17-444a-ab77-d5bc49e79c63', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the primary architectural benefit of using Ember Data’s Adapter and Serializer pattern?', N'Senior', N'This pattern decouples the application''s internal data models from the external API''s wire format. Adapters handle the ''how'' of communication, while Serializers handle the ''what'' of data transformation, allowing developers to consume inconsistent or legacy APIs without polluting the domain models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
