INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae771a9a-ced8-4af8-ad14-d5cd23d60157', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the methods order when component re-rendered?', N'Intern', N'An update can be caused by changes to props or state. The below methods are called in the following order when a component is being re-rendered. 1. static getDerivedStateFromProps() 2. shouldComponentUpdate() 3. render() 4. getSnapshotBeforeUpdate() 5. componentDidUpdate()', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c14c1729-8336-4318-b342-d5d03db0b1e0', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is ''String'' immutable in C#, and how does ''StringBuilder'' solve the associated performance issues?', N'Senior', N'String immutability ensures thread safety and allows for string interning, which saves memory by sharing identical string literals. StringBuilder avoids the performance penalty of creating new string instances during concatenation by using a mutable buffer that can be resized efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44e275ee-1708-4bc8-821f-d5d0677f9bfa', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis considered single-threaded, and does this limit its performance?', N'Middle', N'Redis uses a single-threaded event loop to handle network I/O and command processing, which eliminates the overhead of context switching and lock contention. While it only uses one CPU core for command execution, it remains exceptionally fast because most operations are memory-bound rather than CPU-bound.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc8ff36a-6b46-4f90-ae01-d5d3c79f12af', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the benefit of Ember''s ''Convention over Configuration'' philosophy?', N'Junior', N'This approach means that if you follow standard naming conventions, Ember will automatically wire things together without needing custom configuration. It significantly reduces boilerplate code and helps new developers understand the project structure faster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f3b3457-e8b2-4581-ab98-d5d985a9d9ed', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Does Redis support data persistence?', N'Intern', N'Yes, although it is an in-memory database, Redis can persist data to disk. It offers mechanisms like RDB snapshots and AOF logs to save the state of the database so data is not lost during a restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'872b71ca-1e14-4d52-a63c-d5dab702da8f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Why is it recommended to use ''useFetch'' instead of standard ''fetch'' in Nuxt?', N'Middle', N'The ''useFetch'' composable is a wrapper that handles data fetching, state management, and SSR hydration automatically. It is optimized to prevent duplicate network requests and integrates directly with Nuxt''s life cycle to ensure data is available before the page renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d542576-ff51-4126-85d9-d5db4ac94d55', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering data storage, what is the trade-off between normalized and denormalized database schemas?', N'Junior', N'Normalization reduces data redundancy and prevents update anomalies, ensuring data integrity. Denormalization can significantly improve read performance by reducing the need for complex joins, but it increases the risk of inconsistent data across tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c86850cb-a52e-49c8-b8c2-d5dbb2ec4fb4', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask signals and when should you use them?', N'Middle', N'Signals allow you to send notifications to other parts of the application when certain events occur, such as a request finishing or a model being saved. They are useful for decoupled tasks like logging or analytics that should not block the main request flow. They should be used sparingly to avoid making the control flow difficult to trace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'210c128e-140e-484d-8c1e-d5dd40bd9e16', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the ''jsonify'' function?', N'Intern', N'The jsonify function is a helper that serializes a Python dictionary or list into a JSON-formatted response. This is essential for building web APIs, as it ensures the correct Content-Type header is set for the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25f710ba-9da0-4181-92d0-d5de7db447de', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Can Elasticsearch perform joins like a SQL database?', N'Fresher', N'Elasticsearch does not support traditional SQL-style joins because they are expensive in a distributed environment. Instead, it encourages data denormalization or using specific types like nested or join fields for parent-child relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a1ee627-fca4-463f-98eb-d5e39c5bae3e', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a ''unit test'' and a ''functional test'' in Rails?', N'Fresher', N'Unit tests focus on testing individual models or methods in isolation. Functional tests, often called controller tests, verify that specific web requests correctly execute controller actions and render the expected responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2dbe9082-abdf-464a-b560-d5e99cd16454', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is tree-shaking and how does Vite/Rollup handle it?', N'Junior', N'Tree-shaking is the process of removing unused code from your final production bundle. Since Vite uses Rollup, it performs static analysis on your code to identify and exclude imports that are never actually used in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'656597dd-b3c6-4c42-bd7c-d5ed4a1890ce', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is ''export const dynamic = ''force-dynamic'''' used?', N'Middle', N'This export forces a route to be rendered dynamically on every request, bypassing the build-time static generation. It is used when a page depends on highly volatile data or cookies that cannot be determined until the request hits the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa9e040b-a747-488d-afba-d5ee8c69e473', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why use the Serializer component instead of manual JSON encoding?', N'Middle', N'The Serializer component provides a robust, configurable way to convert objects to various formats like JSON or XML and back again. It handles complex object graphs, circular references, and custom data formats, ensuring consistent data representation across an API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d5ba301-6842-4396-97d6-d5f618e3fcfa', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the difference between a static prop and a reactive prop?', N'Junior', N'A static prop is passed as a constant value and does not change over the lifetime of the component. A reactive prop is a signal or a derived value that allows the child component to stay in sync with the parent''s state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da6ee361-ac16-4a09-a342-d5f9539bd50f', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why do you need additional care for component libraries while using forward refs?', N'Fresher', N'When you start using forwardRef in a component library, you should treat it as a breaking change and release a new major version of your library. This is because your library likely has a different behavior such as what refs get assigned to, and what types are exported. These changes can break apps and other libraries that depend on the old behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da00019f-e965-4645-bb0b-d5fa297eaa2a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the trade-offs between using ''eval-source-map'' and ''source-map'' in a production-like environment?', N'Senior', N'Eval-source-map generates source maps as data URLs inside the bundle, which is faster for builds but significantly increases bundle size. Standard source-map produces separate files, which is better for production performance and debugging without bloating the main JavaScript payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03530d46-e741-4435-889b-d600ab341b03', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do you share data between a parent and child component in Lit?', N'Junior', N'Data is passed from parent to child via properties using attribute or property binding in the template. The child component receives these values and can use them to update its internal state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdc01d63-b256-4f30-b7e5-d600e9792c41', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the advantage of using a CSS reset or normalize file?', N'Middle', N'Browsers have different default styles for elements, leading to inconsistent appearances across platforms. A reset file clears all default browser styles to a baseline, while normalize preserves useful defaults while fixing cross-browser inconsistencies. Both approaches ensure that the design remains consistent regardless of the browser or device being used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8ef83e7-97be-4f56-87ac-d601a274173c', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the call stack', N'Intern', N'Call Stack is a data structure for javascript interpreters to keep track of function calls(creates execution context) in the program. It has two major actions, 1. Whenever you call a function for its execution, you are pushing it to the stack. 2. Whenever the execution is completed, the function is popped out of the stack. Let''s take an example and it''s state representation in a diagram format The above code processed in a call stack as below, 3. Add the hungry() function to the call stack list and execute the code. 4. Add the eatFruits() function to the call stack list and execute the code. 5. Delete the eatFruits() function from our call stack list. 6. Delete the hungry() function from the call stack list since there are no items anymore. !Screenshot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15b24037-6e60-4f12-8ac2-d603d24da2fd', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI''s handling of HTTP exceptions differ from traditional frameworks?', N'Senior', N'FastAPI allows you to register custom exception handlers for specific error types, which are then automatically converted into standardized JSON responses. This architectural pattern keeps error handling code centralized and ensures consistent API error structures across all endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bae0c7f-391c-48c4-94a3-d606b463d825', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of void 0', N'Intern', N'Void(0) is used to prevent the page from refreshing. This will be helpful to eliminate the unwanted side-effect, because it will return the undefined primitive value. It is commonly used for HTML documents that use href="JavaScript:Void(0);" within an element. i.e, when you click a link, the browser loads a new page or refreshes the same page. But this behavior will be prevented using this expression. For example, the below link notify the message without reloading the page', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b338ebdc-628b-4e71-9b09-d60a13eb5532', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi''s middleware stack architecture differ from standard net/http middleware patterns?', N'Senior', N'Chi utilizes a functional middleware pattern that wraps http.Handler interfaces, allowing for a lightweight and composable chain. Unlike some frameworks that rely on heavy reflection or complex context injection, Chi remains strictly idiomatic by aligning with the standard library''s http.Handler signature, ensuring deep compatibility with existing ecosystem tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0064796-64a6-451f-a453-d60ad7292d8c', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is ''Consistency'' difficult to maintain in distributed NoSQL systems?', N'Junior', N'In distributed systems, data is replicated across multiple nodes. Maintaining strict consistency requires ensuring all nodes agree on the state before a transaction finishes, which creates significant latency and can hurt availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ae6db6c-75cd-43de-ba7e-d60efc12f703', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a database dump?', N'Intern', N'A database dump is a file containing the SQL commands or data required to recreate a database. It is primarily used for backup and migration purposes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a22505c8-ab0a-4452-a08a-d60f2d2f1065', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is a database migration in AdonisJS?', N'Intern', N'Migrations act as version control for your database schema. They allow you to define and modify the database structure in code, making it easy to share schema changes across different development environments and team members.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'837ee12c-3cd0-470b-b3d4-d61240cd5077', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What does ''Developer Joy'' mean in the Quarkus ecosystem?', N'Intern', N'Developer Joy refers to the framework''s live coding capabilities, which allow developers to see changes in their code immediately without manually restarting the application. This creates a rapid feedback loop that simplifies testing and accelerates the overall development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac706623-1765-4819-aa0f-d61372ade971', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you identify the culprit when a database query suddenly becomes slow after months of consistent performance?', N'Senior', N'I would inspect the query execution plan to see if the optimizer has chosen a different path due to changing data distribution or outdated statistics. I would also check if the database engine has undergone a version upgrade or if the underlying hardware is experiencing resource contention from other workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bc7ca88-0ea6-4b14-a4ab-d613b23ba00c', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between ''Ecto.Repo'' and a standard data access object?', N'Middle', N'Ecto.Repo is a process that acts as a gateway to the database, managing connection pooling and executing queries. Unlike a standard DAO, it is designed to work within a functional paradigm, accepting query expressions and returning data structures, rather than maintaining an internal object-oriented state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40cae7b3-4dde-4a65-bb53-d613f51cdc82', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is string templating in Kotlin?', N'Intern', N'String templating allows you to embed variables or expressions directly into string literals using the dollar sign syntax. This replaces the need for manual string concatenation, making code easier to read.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e469b043-3f9d-44b6-a749-d6149029a9d0', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a Mixin?', N'Junior', N'A Mixin is a technique where a module is included into a class to provide additional functionality. This allows for code reuse without the limitations of single inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b7692ab-d862-4d2a-b641-d615158c71d7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Can data in Redis be persisted to disk?', N'Fresher', N'Yes, although Redis is an in-memory database, it supports data persistence through mechanisms like RDB snapshots and AOF logs. These allow the state of the database to be saved to disk so that data can be recovered after a server restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd42e21b-f06b-47cf-abd4-d616ee95a561', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle component life cycles compared to traditional frameworks?', N'Intern', N'SolidJS components are functions that run only once when they are initialized. Because reactivity is fine-grained, the framework does not need to re-run the entire component function to update UI elements, making the life cycle model simpler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1131dd2d-ed7a-41a3-936a-d61b75f45240', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of appsettings.json?', N'Intern', N'The appsettings.json file is a configuration file used to store application settings such as database connection strings, API keys, and environment-specific parameters. It allows developers to change application behavior without recompiling the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53dca618-6662-41b8-ab61-d61c83652dcb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut facilitate testing?', N'Middle', N'Micronaut supports testing through its ''Micronaut Test'' module, which provides JUnit 5 integration to manage the application context efficiently. It allows for the injection of mocks and the easy replacement of beans, enabling fast and isolated unit and integration tests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f6cff63-53b0-4ae8-8911-d61d5a2735ce', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the role and limitations of the libuv thread pool in Node.js.', N'Senior', N'Libuv manages a thread pool of default size four to handle asynchronous operations like file I/O, DNS lookups, and crypto functions that cannot be performed non-blockingly by the kernel. The limitation is that this pool is shared across the entire process; if multiple long-running tasks occupy these threads, other operations will be queued, creating a bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd2176a6-33e1-43be-869d-d61f65f511c3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to programmatically trigger click event in React?', N'Fresher', N'You could use the ref prop to acquire a reference to the underlying HTMLInputElement object through a callback, store the reference as a class property, then use that reference to later trigger a click from your event handlers using the HTMLElement.click method. This can be done in two steps: 1. Create ref in render method: 2. Apply click event in your event handler:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ba1e615-6bae-4fab-92aa-d621b7ee31c5', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the difference between SvelteKit''s ''ssr'', ''csr'', and ''prerender'' configuration options.', N'Middle', N'SSR enables server-side rendering for initial page loads, CSR allows the application to run as a single-page app after the initial load, and prerendering generates static HTML files at build time. These settings can be toggled per-route to optimize performance based on whether the content is dynamic or static.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'895fd21e-5396-4fa8-9b4d-d6280e09e481', N'075b8862-431c-4678-9767-f55359758a4a', N'What is vuex?', N'Intern', N'Vuex is a state management pattern + library (Flux-inspired Application Architecture) for Vue.js applications. It serves as a centralized store for all the components in an application, with rules ensuring that the state can only be mutated in a predictable fashion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40600a87-01ab-455b-8c91-d62ab4e57a72', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the Svelte ''each'' block?', N'Fresher', N'The each block is a template syntax used for rendering a list of items. It allows you to iterate over an array or iterable and generate a piece of UI for each element, automatically updating the list if the underlying data changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
