INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95c4fc07-25e1-4d6b-822c-d62ff6c9d480', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Explain the performance trade-off of using @extend.', N'Middle', N'@extend works by grouping selectors together in the compiled CSS, which keeps the output file size smaller. However, it can lead to complex selector chains and unexpected specificity issues, making it harder to debug compared to mixins which simply output their code where called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8da467d-6dc3-4db7-8585-d630f207ef28', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between relative and absolute positioning in terms of the document flow?', N'Middle', N'Relative positioning shifts an element without affecting the layout of surrounding elements, as it still occupies its original space. Absolute positioning removes the element from the normal document flow entirely, allowing it to be positioned relative to its nearest positioned ancestor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea202266-8f4d-48b4-a295-d631a93ce630', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the impact of implementing eventual consistency in a global system?', N'Senior', N'Eventual consistency allows for high availability and low latency by permitting replicas to diverge temporarily. The trade-off is the architectural requirement to handle conflict resolution and potential stale reads, often requiring application-level logic to ensure business processes remain correct.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd488ff84-d1f9-417e-a184-d637144ccce2', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the concept of eventual consistency in NoSQL databases.', N'Middle', N'Eventual consistency is a model where, given no new updates, all accesses to an item will eventually return the last updated value. This allows for higher availability and partition tolerance, as the system does not require immediate synchronization across all replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef92365b-b12d-4ed7-b3c9-d637653fa7fe', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is Redis persistence?', N'Intern', N'Persistence is the process of saving data from the RAM to a disk so that it is not lost when the server restarts. Redis offers options like RDB snapshots and AOF logs to handle this.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63bc9fe2-2555-46b0-a80a-d63847a718d1', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a write lock in a database?', N'Junior', N'A write lock prevents other transactions from reading or writing to a specific data object. It is used when a transaction needs to perform an update, ensuring the data remains consistent until the operation is complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03ad8c36-6908-4525-87c1-d63917968e79', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using ''Changesets'' over manual validation?', N'Middle', N'Changesets provide a unified way to cast, filter, and validate data before it is sent to the database. They keep validation logic close to the data schema and allow the application to return detailed, field-specific error messages that are easily displayed to the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ebf6e232-ffc5-40c1-b5f0-d639698c568f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the ''LinkTo'' component?', N'Intern', N'The LinkTo component is a built-in helper used to create navigation links between different routes in an Ember application. It automatically updates the URL and handles the transition between states without a full page refresh.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e41e1f21-2458-491e-b9e0-d63abb98f372', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are ''context locals'' in Flask?', N'Junior', N'Context locals are objects that behave like global variables but are actually local to the current request thread. This mechanism allows Flask to keep track of request-specific data without needing to pass objects manually through every function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'456ecfc0-a61a-487d-acfe-d63b34a1ec59', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does an index represent in the relational database model?', N'Intern', N'An index maintains a sorted copy of one or more columns and stores pointers to the corresponding data rows, allowing the engine to find rows without scanning the entire table — similar to a book''s index that lets you jump directly to a page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae49d9e1-f3d7-42be-84f3-d63b8cbc9f77', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the trade-offs of using Gin''s global middleware versus route-specific middleware?', N'Middle', N'Global middleware applies to every request and is easier to maintain for cross-cutting concerns like logging or CORS. Route-specific middleware provides better performance and isolation by only executing logic where it is strictly required, reducing overhead for simple endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'900c9ab9-977f-491a-871f-d63de4086ca2', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle concurrency compared to Flask?', N'Middle', N'FastAPI is built on Starlette and supports asynchronous programming using the async and await keywords, allowing it to handle concurrent I/O-bound operations efficiently. Flask is traditionally synchronous, requiring worker-based concurrency, whereas FastAPI leverages the Python asyncio event loop to handle many simultaneous connections with fewer resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba4db634-6205-4799-9ea7-d63dfbfdded4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the benefit of breaking a complex problem into smaller modular parts?', N'Intern', N'Modularization reduces cognitive load, making it easier to reason about the system''s logic and identify potential faults. It allows for independent testing and development, which improves efficiency and maintainability. If a part fails, it is easier to isolate and fix without affecting the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f115cab-2aad-4b95-be5e-d63eb18fd350', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between a push-based and a pull-based monitoring system?', N'Middle', N'Pull-based systems are generally more resilient as the monitoring server controls the collection rate and can detect if an instance is down. Push-based systems are better suited for ephemeral or short-lived tasks, such as serverless functions, where the instance disappears before it can be polled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce97643c-5c42-4897-9141-d642148fadf5', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ASP.NET Core request pipeline differ from the traditional ASP.NET HttpModule/HttpHandler model?', N'Senior', N'ASP.NET Core uses a lightweight middleware pipeline where each component decides whether to pass the request to the next component or terminate early. Unlike the event-driven HttpModule model, this linear approach provides better performance, modularity, and explicit control over the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'221d5ff3-6275-417c-8ebe-d6436c211c2f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi require a specific folder structure?', N'Intern', N'No, Chi is unopinionated regarding project structure. You can organize your handlers and routes however you prefer, which is a common practice in the Go ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b410e62f-1247-444f-86a2-d64731e882ae', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the benefit of using ''Arc'' over ''Rc''?', N'Middle', N'Rc is used for reference counting within a single thread and is not thread-safe. Arc is an atomic reference counter that allows shared ownership across multiple threads, ensuring that the reference count is updated safely through atomic operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ccd4af9-67c4-4121-8fcd-d648eee21ebc', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the role of Virtual Method Tables (vtables) and the cost of multiple inheritance.', N'Senior', N'A vtable is a static array of function pointers used to facilitate dynamic dispatch for virtual functions. Multiple inheritance increases the complexity of the vtable and the object layout, often requiring multiple vtable pointers and pointer adjustments during casting, which can impact performance and memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fc75476-b058-4979-9419-d64b34e2840e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik compatible with standard web technologies?', N'Intern', N'Yes, Qwik is built on standard web technologies like HTML, CSS, and standard JavaScript. It does not introduce proprietary syntax that prevents the use of standard browser features or common web development practices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'accc8a7f-3ed2-4fab-bf2c-d64ffd464a4e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'A web page is not loading correctly for a user, but it works on your machine. How would you approach identifying the source of the issue?', N'Fresher', N'I would start by isolating the variables by asking the user for their browser type, version, and operating system. I would then use the browser''s developer tools to check for network errors, blocked resources, or console warnings specific to their environment. Finally, I would clear the cache or test in an incognito window to determine if the issue is caused by local stored data or a cross-platform incompatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c9125ac-8ae9-43cf-948e-d651081e6bca', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the difference between synchronous and asynchronous replication in a leader-follower architecture?', N'Senior', N'Synchronous replication waits for the follower to acknowledge the write before confirming success, ensuring strong consistency but increasing latency. Asynchronous replication returns success as soon as the leader commits, providing lower latency at the risk of losing data if the leader fails before the follower updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'144d51ab-9eaa-45d5-a025-d6510ec5b32d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the Sass `!default` flag assist in building a scalable UI library?', N'Senior', N'The `!default` flag allows theme developers or consumers of a library to override a variable''s value only if it has not been defined previously. This pattern is essential for creating configurable components that provide sensible defaults while remaining highly customizable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd078eade-26f1-491f-8727-d65918bb8f81', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are regular expression patterns', N'Intern', N'Regular Expressions provide a group of patterns in order to match characters. Basically they are categorized into 3 types, 1. Brackets: These are used to find a range of characters. For example, below are some use cases, 1. [abc]: Used to find any of the characters between the brackets(a,b,c) 2. [0-9]: Used to find any of the digits between the brackets 3. (a|b): Used to find any of the alternatives separated with | 2. Metacharacters: These are characters with a special meaning. For example, below are some use cases, 1. \\d: Used to find a digit 2. \\s: Used to find a whitespace character 3. \\b: Used to find a match at the beginning or ending of a word 3. Quantifiers: These are useful to define quantities. For example, below are some use cases, 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4816e02-4069-40f4-9a48-d659410d1946', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the purpose of the ''useHead'' composable in Nuxt?', N'Middle', N'useHead is used to manage the document head tags, such as meta descriptions, titles, and script tags, in a reactive way. This is critical for SEO and ensuring that social media scrapers correctly interpret the content of dynamic pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85920983-a0e8-434d-9c38-d65b43e05fdb', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it important to document the steps taken during a troubleshooting session?', N'Intern', N'Documentation ensures that you do not repeat ineffective attempts and provides a clear audit trail for the team. It also helps in identifying patterns if similar issues occur in the future and facilitates knowledge sharing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5b09254-8449-4868-9d6f-d65d058405a7', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you maintain data consistency in a distributed microservices environment?', N'Middle', N'Since distributed transactions are expensive, systems often rely on eventual consistency using patterns like Sagas or transactional outbox. The system guarantees that data will reach a consistent state eventually, even if it is temporarily out of sync across services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'244b92c5-fd5e-4141-bdbc-d65e65914f09', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does the ''OpenAPI Config'' in Litestar improve API documentation compliance?', N'Senior', N'The configuration object allows for centralized control over the generated schema, including metadata, server definitions, and security schemes. This ensures that the resulting API documentation adheres to organizational standards and allows for automated integration with client-side code generators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1aefcb53-7428-44c2-937c-d6658b1262e4', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What does ACID stand for in the context of PostgreSQL?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably and maintain data integrity even in the event of system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5508c39d-a095-4c91-b7c8-d667dc749baf', N'075b8862-431c-4678-9767-f55359758a4a', N'What are lifecycle hooks in Vue?', N'Junior', N'Lifecycle hooks are special methods that allow you to tap into different stages of a component''s existence, such as when it is created, mounted to the DOM, updated, or destroyed. They provide clear entry points for running logic like fetching data or cleaning up event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a6d436-58a2-4feb-841b-d667e32fd6b4', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Explain the concept of ''sparse indexes'' in DynamoDB.', N'Middle', N'A sparse index contains entries only for items that actually have the index''s partition or sort key attributes defined. This allows you to create efficient indexes that only track a subset of items, such as finding all ''pending'' orders by indexing only items where a status attribute exists.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73d1a3a5-e747-48a5-8ccd-d66d279ba29a', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the scalability benefits of adopting a ''Web Components'' strategy for a design system?', N'Senior', N'Web Components provide true style and markup encapsulation through the Shadow DOM, preventing CSS leakage and global namespace collisions. This allows a design system to be framework-agnostic, enabling teams to share components across different stacks without the risk of style bleeding or dependency conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3d4249d-eb8d-4438-a551-d6708cedabff', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does the AdonisJS IoC container achieve dependency inversion and why is this critical for testing?', N'Senior', N'The IoC container manages dependency resolution by abstracting concrete implementations behind interfaces or service aliases. This allows developers to swap real services with mock implementations during unit tests without modifying the business logic, ensuring isolated and deterministic test results.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ca38122-131b-440a-ada9-d6711b34e6f8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do CRDTs address the challenges of conflict resolution in multi-master NoSQL systems?', N'Senior', N'Conflict-free Replicated Data Types (CRDTs) ensure eventual consistency by defining data structures that follow mathematical properties like commutativity and associativity. This allows updates to be applied in any order across distributed nodes, ensuring all replicas converge to the same state without requiring central coordination or complex locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42dc78c4-eef4-42f6-8903-d67724593d76', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a view in PostgreSQL?', N'Intern', N'A view is a virtual table based on the result of a SQL query. It does not store data physically but provides a simplified way to access complex data structures or restrict access to specific columns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'941f24e2-0785-4b33-a0b6-d6799553bc67', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach a situation where your code works on your local machine but fails in the production environment?', N'Junior', N'I would check for environment-specific discrepancies such as configuration settings, environment variables, or database differences. Comparing the logs of both environments often reveals missing dependencies or permission issues that explain the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10313900-b621-4f9c-b645-d67cf6cde94a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are Flask request hooks?', N'Junior', N'Request hooks are functions that trigger at specific stages of the request lifecycle, such as before a request is processed, after it is processed, or when an exception occurs. They provide a clean way to perform repetitive setup or teardown logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6d9784d-9b26-49c8-85c7-d67d5e3511f9', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does late static binding solve the limitations of inheritance in PHP''s object-oriented model?', N'Senior', N'Late static binding allows the engine to reference the class that was initially called at runtime rather than the class where the method was defined. This is essential for inheritance hierarchies where static methods need to access subclass-specific constants or properties dynamically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd640bfef-b622-41da-89a4-d67ecbafd29f', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the principles for vuex application structure?', N'Intern', N'Vuex enforces below rules to structure any application. 1. Application-level state is centralized in the store. 2. The only way to mutate the state is by committing mutations, which are synchronous transactions. 3. Asynchronous logic should be encapsulated in, and can be composed with actions. The project structure for any non-trivial application would be as below,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28d2f57e-dcb9-4d0d-b4ec-d681abfaaea4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Why should you avoid using ''tabindex'' values greater than zero?', N'Senior', N'Using a positive tabindex forces a non-standard tab order that ignores the document''s logical structure, creating a frustrating experience for keyboard users. It is almost always better to order elements correctly in the DOM and use zero or negative values to manage focus programmatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa89ee3a-a313-4935-91d8-d682ca918b1e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the order of members in a C struct important?', N'Middle', N'The order of members affects the amount of padding inserted by the compiler to meet alignment requirements. Arranging members from largest to smallest can minimize the total size of the struct, resulting in more efficient memory usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd97f139e-a096-4e95-8ee9-d682e6a78217', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'If you are designing a system to store user profile pictures, what factors would influence your choice between a database and an object storage service?', N'Intern', N'You should consider the size and frequency of data retrieval. Databases are optimized for structured queries and small text fields, while object storage is designed for large binary files and provides better scalability and cost-efficiency for media assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b95a7f-356a-4598-9d4c-d684b2ee810a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you verify if a fix you implemented actually solved the user''s problem?', N'Junior', N'I verify the fix by reproducing the initial steps that caused the bug and confirming that the unexpected behavior no longer occurs. I also perform a quick check of related features to ensure the fix did not unintentionally break anything else.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c4c2421-68cc-4bbc-9f7d-d6879f6f4c29', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How do you manage ''Multi-tenancy'' in an ASP.NET Core application effectively?', N'Senior', N'Multi-tenancy is typically handled by identifying the tenant from the request—usually via hostname, header, or claim—and injecting a scoped tenant context. This context is then used to filter database queries, resolve tenant-specific configurations, or route requests to different storage backends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4501a1b1-7abf-43e6-8290-d68801e0332b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Does SolidJS support lifecycle hooks?', N'Fresher', N'Yes, SolidJS provides lifecycle hooks like onMount to run code after the component is rendered. It also provides onCleanup to perform tasks when a component or effect is removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a1eb4a3-954f-4613-99f0-d688b7c8704c', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the difference between an Edge runtime and a traditional Node.js server?', N'Intern', N'An Edge runtime runs code closer to the user''s geographical location, often in a restricted environment with fast cold starts. Traditional Node.js servers usually run on persistent infrastructure, providing a larger set of APIs but potentially slower startup times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c0ed619-369d-4aaa-9873-d68d4bb99e91', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL manage shared buffers and what is the role of the clock sweep algorithm?', N'Senior', N'Shared buffers cache data pages in memory to minimize disk I/O. The clock sweep algorithm is a variation of the Least Recently Used policy that efficiently identifies and evicts pages that have not been accessed recently, balancing memory pressure against cache hit rates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
