INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b4194a4-2469-49f3-a496-d6b55527928a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the performance implications of Svelte''s lack of a virtual DOM?', N'Senior', N'Without a virtual DOM, Svelte avoids the constant overhead of tree diffing and memory allocation for object representations of the UI. This leads to smaller bundle sizes, lower memory consumption, and faster initial paint times, as the browser executes minimal, optimized instructions to update the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43495d37-d2b4-41b7-864e-d6b60e2bc1c1', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your strategy for handling a third-party API that frequently experiences downtime?', N'Middle', N'I would implement a circuit breaker pattern to prevent cascading failures in my own system when the third-party service becomes unresponsive. Additionally, I would introduce a fallback mechanism, such as serving stale cached data or a default response, while using an asynchronous queue to retry requests once the service recovers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3dc8ef8-33c3-4969-9d27-d6b70eb0d40b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are decorators and why are they used?', N'Junior', N'Decorators are a design pattern that allows you to modify or extend the behavior of a function or method without changing its source code. They are commonly used for tasks like logging, access control, or caching by wrapping the original function in another function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
