INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7a7d437-9d40-46ab-82ed-d6b8dafee6fd', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Why is Svelte considered beginner-friendly?', N'Fresher', N'Svelte is considered beginner-friendly because it relies heavily on standard HTML, CSS, and JavaScript. It does not require learning complex framework-specific abstractions or a heavy runtime API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
