INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68e92827-c91d-40a2-bcc7-d6f67989f426', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage thread models differently in its reactive stack?', N'Senior', N'Quarkus utilizes Vert.x as its underlying reactive engine, employing an event-loop threading model that allows a small number of threads to handle a massive number of concurrent requests. This prevents thread starvation and improves scalability compared to traditional thread-per-request blocking models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd00a5de1-9469-42c3-8933-d6f758e27f2e', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the performance implications of Ember''s object model and its use of proxies?', N'Senior', N'Ember''s object model provides powerful features like computed properties and observers, but it adds memory and CPU overhead compared to plain JavaScript objects. Modern Ember has moved toward native classes and tracked properties to mitigate this, reducing the reliance on heavy Proxy-based observation systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c9eae1e-8af7-421f-9d1c-d6f7de2a6758', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain the concept of ''monkey patching'' in Python and why it is considered a dangerous practice.', N'Senior', N'Monkey patching involves modifying the behavior of classes or modules at runtime by replacing attributes or methods. It is considered dangerous because it creates hidden dependencies and unpredictable side effects, making the codebase difficult to debug, test, and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a2dc461-f525-485c-aab7-d6fafb8db2c8', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''Dirty Read'' anomaly?', N'Junior', N'A dirty read occurs when a transaction reads data that has been modified by another concurrent transaction but has not yet been committed. If the first transaction rolls back, the second transaction is left with incorrect or ''dirty'' data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'214932b6-9db3-4515-b0e2-d6fb1d4e6f46', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the N+1 query problem and how it is typically addressed in Rails.', N'Middle', N'The N+1 query problem occurs when an application executes one query to fetch parent records and then executes an additional query for each parent to retrieve associated child records. It is typically resolved using eager loading methods like includes, preload, or eager_load, which fetch associations in as few queries as possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'585dd133-7401-4037-b203-d6fe5fc91e3e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why is it important to implement rate limiting in ASP.NET Core APIs, and how can it be achieved?', N'Senior', N'Rate limiting protects infrastructure from DDoS attacks, brute-force attempts, and resource exhaustion by limiting the number of requests a client can make in a given timeframe. It can be implemented using built-in middleware, custom filters, or at the infrastructure level via API Gateways or Nginx.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c9df2ca-c2cc-4d79-b1ce-d700feb91315', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the benefit of using FastAPI over a framework like Django?', N'Middle', N'FastAPI is a micro-framework focused on high-performance API development, offering more flexibility and speed for services that don''t need the heavy, opinionated structure of Django. Django is a full-stack framework that includes built-in ORM, admin panels, and authentication, which may be unnecessary overhead for simple microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3ac7e88-3adf-4e41-a9ce-d7012a53c661', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Describe the architectural implications of implementing message ordering in a partitioned message queue like Kafka.', N'Senior', N'Message ordering is typically guaranteed only within a single partition, requiring producers to use a consistent partitioning key for related events. Scaling horizontally by increasing partition counts for an existing topic can break existing ordering guarantees if the key-to-partition mapping logic changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcb5b134-014f-4233-a20b-d703621dd4bd', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How would you create an empty NumPy array?', N'Fresher', N'Ans. To create an empty array with NumPy, we have two options: a. Option 1 import numpy numpy.array([]) array([], dtype=float64) b. Option 2 numpy.empty(shape=(0,0)) array([], shape=(0, 0), dtype=float64)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67085075-4304-4175-92bc-d7054a76f5c0', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the purpose of a Kernel Request listener?', N'Middle', N'A kernel request listener is triggered early in the request lifecycle, allowing you to perform actions before the controller is executed. This is ideal for tasks like authentication, setting locale based on the user''s header, or maintaining a site-wide maintenance mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'589fa187-0e9d-472f-bbc9-d705d5109da1', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does the ''Saga'' pattern manage distributed transactions across microservices without a two-phase commit?', N'Senior', N'Sagas decompose a global transaction into a sequence of local transactions, each updating its own database. If one step fails, the saga executes a series of compensating transactions to undo the changes made by previous steps, maintaining eventual consistency without holding long-lived locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7c0e266-a4ef-4750-a2d0-d709b5d38f23', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''State'' extractor in Axum?', N'Fresher', N'The State extractor allows you to share application-wide data, such as database connection pools or configuration settings, across different request handlers. It provides a thread-safe way to access shared resources throughout the lifecycle of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c6f3d4a-230e-4021-81c6-d70a91ea5f9d', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you optimize performance when working with large lists in Ember?', N'Middle', N'You can optimize large lists by implementing pagination, infinite scrolling, or using specialized addons like ''vertical-collection'' to render only the visible items. Minimizing the number of observers and ensuring that models are efficiently loaded also significantly improves rendering speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd27fac90-9929-4f50-a3db-d70d2d346fa2', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the JVM, and why is it important for Scala?', N'Intern', N'The JVM is the Java Virtual Machine, which is the engine that executes compiled bytecode. Scala is designed to run on the JVM, allowing it to interoperate fully with Java libraries and benefit from the mature performance optimizations of the Java ecosystem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ef5a2e-70d8-47c5-8106-d70dbc940fc8', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the difference between an ''equals'' comparison and ''=='' in Java?', N'Middle', N'The ''=='' operator checks for reference equality, meaning it returns true only if both variables point to the exact same memory location. The equals method is intended to check for logical equality, which is defined by the class implementation. When comparing objects for value equivalence, developers must override the equals method and ensure it follows the contract of symmetry, reflexivity, and transitivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'603ca5d1-7fab-4b73-847c-d70e689fbd5f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'When should you use ''implements'' versus ''extends'' with classes?', N'Middle', N'Use ''extends'' to inherit functionality and properties from a base class, creating an ''is-a'' relationship. Use ''implements'' to ensure a class adheres to a specific interface''s structure without inheriting logic. ''Implements'' is preferred for architectural design to enforce contracts while keeping classes loosely coupled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5017421a-84be-412a-b7c2-d70f602b0a4d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When is it appropriate to use event sourcing instead of traditional CRUD state management?', N'Middle', N'Event sourcing is appropriate when there is a strict requirement for an audit log of all changes or the ability to reconstruct the system state at any point in time. It adds significant complexity, so I only use it when the business domain requires the historical context of how data arrived at its current state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9d2cec0-761d-4ad4-a257-d71165a83e4f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a Shard?', N'Fresher', N'A shard is a horizontal partition of data in a database or search engine. Each shard is held on a separate database server instance to spread the load and improve performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a650682-c5af-44fb-b6eb-d712571fbc89', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do Loaders and Plugins differ?', N'Fresher', N'Loaders work at the individual file level to transform specific file types into modules during the bundle process. Plugins work at the bundle level, performing tasks on the final output or during the entire compilation lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfd0b51d-0e2f-4904-a22e-d71429e2a077', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a namedtuple?', N'Intern', N'A namedtuple will let us access a tuple''s elements using a name/label. We use the function namedtuple() for this, and import it from collections. 95 As you can see, it let us access the marks in Chemistry using the Chemistry attribute of object Ramayan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bb97670-4c02-4977-8726-d714bd643d68', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you balance the need for new feature development with the need for system maintenance and reliability?', N'Middle', N'I advocate for allocating a consistent percentage of each development cycle, such as 20%, to technical debt and infrastructure improvements. This prevents the accumulation of issues that could slow down future feature velocity. By framing maintenance as an investment in stability and developer productivity, I keep stakeholders aligned on its value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34bea57e-bcc0-43de-82b2-d716423ec5df', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are ''Hooks'' in Lucid ORM?', N'Fresher', N'Hooks are lifecycle methods that can be triggered before or after specific database operations, such as saving, updating, or deleting a record. They are useful for tasks like hashing passwords before saving a user or cleaning up related files when a record is deleted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9da2543-651e-4d8c-bfc9-d717f9046912', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are meta tags used for?', N'Junior', N'Meta tags provide metadata about the HTML document that is used by browsers, search engines, and other web services. Common uses include defining page descriptions, keywords, author information, and viewport settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3582c2d4-9d46-4723-896a-d718749df7a1', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why might you choose Redis over Memcached for a distributed system?', N'Middle', N'Redis offers advanced data structures, built-in replication, persistence options, and Lua scripting, which provide greater flexibility for complex application states. Memcached is strictly a simple key-value store, making it faster and easier to deploy for pure, high-performance object caching scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb72ee60-07b7-416c-93e6-d71984bb0596', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Does Express support environment variables?', N'Fresher', N'Express does not directly manage environment variables, but it is common practice to use them for configuration. You can access them via Node.js''s process.env object to set configurations like database URLs or application port numbers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97abaf4d-c572-4d6b-af33-d71aef9fff3d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How do table partitioning strategies (declarative partitioning) improve performance and management?', N'Senior', N'Declarative partitioning allows large tables to be split into smaller, more manageable pieces based on ranges, lists, or hashes. This enables partition pruning, where the query planner ignores partitions irrelevant to the query, and simplifies data lifecycle management by allowing old partitions to be dropped instead of running expensive delete operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a8206ba-9841-4cf0-b1c5-d71b01a978a7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why are nested transactions often avoided in distributed systems?', N'Middle', N'Nested transactions add significant complexity to the commit protocol and locking mechanisms, making it difficult to maintain global consistency. They often lead to performance bottlenecks and increase the risk of deadlocks, so most distributed systems prefer flat transaction models instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56a39fcd-2fe6-4604-9b66-d720365c0d25', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary trade-off when choosing between consistency and availability in a distributed system?', N'Intern', N'According to the CAP theorem, a distributed system can only guarantee two out of three properties: consistency, availability, and partition tolerance. You must choose based on whether your application can tolerate stale data during a network failure or if it must remain offline to ensure accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcb9ec79-91c1-4999-8674-d721f55ac257', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is a Ruby mixin and how is it implemented?', N'Junior', N'A mixin allows a class to gain the functionality of another module without using traditional class inheritance. It is implemented using the include or extend keywords, which inject the methods defined in a module into the class, enabling multiple inheritance-like behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd34b246e-97e1-40cf-917e-d722754d0c19', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is isMounted() an anti-pattern and what is the proper solution?', N'Fresher', N'The primary use case for isMounted() is to avoid calling setState() after a component has been unmounted, because it will emit a warning. Checking isMounted() before calling setState() does eliminate the warning, but it also defeats the purpose of the warning. Using isMounted() is a code smell because the only reason you would check is because you think you might be holding a reference after the component has unmounted. An optimal solution would be to find places where setState() might be called after a component has unmounted, and fix them. Such situations most commonly occur due to callbacks, when a component is waiting for some data and gets unmounted before the data arrives. Ideally, any callbacks should be canceled in componentWillUnmount(), prior to unmounting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bc0d9bc-75b8-41ca-8372-d7281510e64e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is an Embedded Server?', N'Intern', N'An embedded server is a web server, such as Tomcat or Jetty, that is bundled directly into the application''s executable JAR file. This allows the application to run as a standalone process without needing an external web server installation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e31c1b3e-f208-488e-a706-d728bacfbf89', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the catch boundary in Remix?', N'Junior', N'A catch boundary is used to handle expected responses that are not successful, such as a 404 Not Found or 401 Unauthorized status. It provides a way to gracefully inform the user about these specific navigation outcomes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3afa170b-59a1-492a-8bfc-d728c6314cf1', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is schema-based validation in Fastify?', N'Intern', N'Schema-based validation allows you to define the expected structure of incoming requests using JSON Schema. Fastify automatically validates the input against these schemas and returns an error response if the input does not match, protecting the application from malformed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'373a4e57-743e-4cb8-a059-d729e476d51d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do placeholders (%) help in Sass?', N'Fresher', N'Placeholders allow you to define a block of styles that will not be rendered in the final CSS unless they are specifically extended. This helps keep the compiled CSS clean by preventing unused code from being included.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e943f29-57f2-424f-91ab-d730af032a1e', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is a ''loading.js'' file used for?', N'Intern', N'The loading file is used to create a loading UI that is automatically shown while the content of a specific route is being fetched. This improves user experience by providing immediate feedback during data loading.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1afd4885-228c-472b-a794-d731a6806e88', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''finally'' block?', N'Fresher', N'The ''finally'' block is used to execute important code, such as closing a file or a database connection, regardless of whether an exception is thrown or caught. It ensures that critical cleanup operations are always performed after a try block.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12905e46-7a09-40eb-aae2-d734a0c758cc', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do Form Actions work in SvelteKit?', N'Intern', N'Form Actions allow you to send data from an HTML form directly to the server without needing to write a manual fetch request. The server processes the form data using an action function and returns a response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'799d7a62-93c3-4104-a3c9-d73949ee5725', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the concept of ''Speculative Retry'' in Cassandra.', N'Senior', N'Speculative retry allows a coordinator to proactively send a read request to an additional replica if the initial replica does not respond within a configured latency threshold. This helps mask transient node slowness, though it increases total cluster load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2f61360-5f2b-4022-a6af-d73b261a3121', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Can you use different response formats in Gin besides JSON?', N'Junior', N'Yes, Gin supports multiple response formats including XML, YAML, HTML, and plain text. The Context object provides specific methods for each format to set the appropriate headers and serialize the data correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afd10c60-643c-4fc3-8bda-d73bc5f2c067', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How does HTML5''s ''formnovalidate'' attribute work?', N'Middle', N'The ''formnovalidate'' attribute, when applied to a submit button, tells the browser to skip the native HTML5 constraint validation for the form fields during submission. This is useful for ''cancel'' or ''save as draft'' buttons where you want to allow the user to submit the form even if required fields are missing. It provides a way to override default browser behavior for specific user actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0d31f4e-ddba-4c4e-932f-d73c24efbf6f', N'f2e963ff-7635-4429-a389-4d92535fb972', N'How do you evaluate the trade-offs between using Shadow DOM versus standard DOM encapsulation strategies?', N'Senior', N'Shadow DOM provides true style and DOM isolation, preventing global CSS leakage and accidental selector collisions. However, it complicates global style theming and accessibility auditing, as tools may struggle to pierce the shadow boundary without specific configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6313c94-c69f-4917-b02d-d73cf2c3a7ca', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Why is it often necessary to use a proxy header middleware when running Flask behind a reverse proxy like Nginx?', N'Senior', N'When behind a proxy, Flask may misidentify the client''s IP address or the request''s original protocol (HTTP vs HTTPS) because it sees the proxy as the direct client. A middleware like ProxyFix updates the request environment using headers like X-Forwarded-For, ensuring Flask correctly generates URLs and logs the actual client source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69f3adac-6b8e-4ecb-add3-d745c4824849', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you verify that your solution works as intended in different environments?', N'Fresher', N'I test the solution across different settings if possible, or simulate varied conditions to ensure it is not dependent on a specific environment. I also ensure that all necessary dependencies are clearly identified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7134a7f-6117-4c0c-bf89-d745d586067a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What are ''Hono Helpers''?', N'Junior', N'Helpers are utility functions provided by the framework to simplify common tasks like setting cookies, managing sessions, or streaming content. They extend the functionality of the Context object to reduce the amount of code needed for recurring operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7b6995d-975e-4d9d-ab94-d74891aaffa5', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens when you perform a search query in Elasticsearch?', N'Fresher', N'When a query is received, the node acting as the coordinator forwards the request to all relevant shards. Each shard performs the search locally, and the results are returned to the coordinator, which merges them into a final response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74616d2a-e27c-4c21-ad41-d749febda627', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s ''object'' keyword implement the Singleton pattern?', N'Middle', N'The object keyword creates a thread-safe, lazily initialized singleton instance managed by the language runtime. It ensures that only one instance of the object is created throughout the application lifecycle, eliminating the need for complex locking or manual instance management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc68ed74-c4fe-479c-a9a8-d74dddcaa847', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''entry'' property in Webpack configuration?', N'Intern', N'The entry property indicates which module Webpack should use to begin building out its internal dependency graph. From this entry point, Webpack figures out which other modules and libraries the entry point depends on.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68d9258f-4316-4983-bf61-d74efc959a60', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of ''Data'' in Rocket?', N'Fresher', N'The Data type in Rocket is used to read the raw body of a request. It is often used for streaming large payloads or handling custom data formats that aren''t automatically parsed by other built-in types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'638269f6-d4f4-46b3-a998-d74f61e6beef', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the architectural implications of using Dependency Injection in FastAPI.', N'Senior', N'Dependency Injection in FastAPI allows for modular, decoupled code by injecting shared logic—such as database sessions, authentication, or configuration—directly into path operations. This promotes high testability, as dependencies can be easily overridden during unit tests without modifying the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cac5035-88f5-4bb4-a0ed-d750729c5713', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the trade-offs of using a ''Distributed Cache'' like Redis in an architecture?', N'Senior', N'A distributed cache significantly improves read performance and reduces load on the primary database, but it introduces the challenge of cache invalidation and potential data staleness. It also adds another component to the infrastructure that must be monitored and scaled independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'751b684b-b499-4152-a27f-d75079ef5ab4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is it often recommended to use the ''MiniCssExtractPlugin'' for production builds?', N'Middle', N'Unlike the style-loader, which injects CSS into the DOM via JavaScript, MiniCssExtractPlugin extracts CSS into separate files. This allows for parallel loading of CSS and JavaScript, improves browser caching, and prevents the flash of unstyled content during initial load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c560ab7-7eea-40fe-a1c8-d7511009cc08', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'When is it appropriate to use an In-Memory NoSQL database?', N'Middle', N'In-memory databases are appropriate when extremely low latency and high throughput are required for read and write operations. They are commonly used for caching, real-time analytics, and session management where the cost of RAM is justified by the performance gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee81f5ff-2f06-45cb-88ad-d7529c9d2df5', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the difference between complexity and effort in the context of estimation?', N'Fresher', N'Complexity refers to the number of moving parts and the difficulty of the logic involved in a task, while effort is the actual time required to perform the work. A task can be low complexity but high effort if it involves repetitive, manual work, or vice-versa.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb66cf31-b60e-4694-8841-d755134d68ab', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What are the advantages of using Laravel''s ''API Resources'' layer over returning models directly?', N'Senior', N'API Resources act as a translation layer, decoupling the internal database schema from the external API contract. This allows for schema changes without breaking client integrations and provides a clean way to transform, hide, or aggregate data before transmission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4dfe4cb-a851-4d43-a76a-d758c802e711', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the concept of a ''circuit breaker'' in Elasticsearch.', N'Middle', N'A circuit breaker is a memory management mechanism that monitors the memory usage of requests and operations. If a request is likely to cause an OutOfMemory error, the circuit breaker triggers and rejects the request to protect the stability of the node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f6e8450-f3f9-4fc1-bf6b-d75902ab05ec', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is Ruby on Rails, and why is it popular for web development?', N'Intern', N'Ruby on Rails, often termed simply as Rails, is a popular web application framework known for its simplicity and productivity. It is built on the Ruby programming language and adheres to the MVC (Model-View-Controller) architectural pattern. Rails takes a strong stance on conventions over configurations, reducing the need for boilerplate code. Key Components - Active Record: Simplifies data handling from databases, treating tables as classes and rows as objects. - Action View: Manages user interface elements like forms and templates. - Action Controller: Handles requests, processes data, and manages flow between models and views. Rails also comes with an integrated testing suite and a robust security system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e776250-1935-4f79-af8d-d75bfa72f8ed', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you define an optional property in an interface?', N'Junior', N'You define an optional property by placing a question mark after the property name in the interface definition. This tells TypeScript that the property is not required to be present on the object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0772855e-58d8-4695-992c-d75c4c4f8b0d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s Sizzle engine differ from modern native query selector engines?', N'Middle', N'Sizzle was built to provide a consistent CSS selector implementation across browsers, including older ones that lacked support for advanced selectors. Modern browsers now have highly optimized, native query engines that outperform Sizzle, rendering its custom parsing logic largely unnecessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'466be9f6-7d77-4b08-8603-d7610a80f691', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle content management compared to traditional Single Page Applications (SPAs)?', N'Junior', N'Astro is designed as a content-focused framework that prioritizes server-side rendering and static site generation, making it ideal for blogs and documentation. Unlike SPAs that typically rely on client-side routing and hydration, Astro delivers optimized HTML by default, which improves search engine optimization and initial page load speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77cf1fc0-8904-4f39-b657-d7623d2fdb68', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s testing infrastructure support ''Integration'' versus ''Unit'' testing?', N'Senior', N'Ember provides specific test helpers for different scopes: unit tests isolate functions or classes, while integration tests render components or routes in a simulated DOM environment. This tiered approach ensures that developers can verify both the logic of individual units and the correctness of the final DOM composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9874fcf8-e205-42a9-a43d-d7644a7450fd', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''externals'' in Webpack?', N'Middle', N'Externals allow you to exclude specific dependencies from the bundle, such as large libraries provided via a Content Delivery Network. This reduces the bundle size and allows the browser to cache these libraries independently of the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e31eed5-4c15-40a9-b473-d7678b7deba1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is virtual DOM in React?', N'Intern', N'The "virtual DOM" in React is a tree of plain JavaScript objects (React elements) that describes what the UI should look like — it is not a copy of the actual DOM. When state or props change, React builds a new tree, compares it with the previous one (a process called reconciliation, performed by the Fiber reconciler since React 16), and applies only the necessary changes to the real DOM. The React team now prefers the terms "React elements" and "Fiber tree." The main benefit is the declarative programming model, not raw speed over hand-written DOM updates. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d836271-caf1-4e75-a073-d768e27dd13f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How are missing values represented in R?', N'Intern', N'Missing values in R are represented by the symbol NA, which stands for Not Available. It is used to indicate that a specific data point is missing or unknown within a dataset.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'147372ca-99a4-4dc2-938f-d76c56012887', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between ''serve'' and ''build'' modes in Vite?', N'Middle', N'The ''serve'' mode uses a dev server optimized for rapid iteration using native ESM, while the ''build'' mode invokes Rollup to generate a production-ready, minified, and bundled static application. Each mode targets a distinct environment and optimization goal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da73dd5d-b68b-4ef3-ab34-d771bf7b1808', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the significance of the ''ACID'' properties in database system design?', N'Senior', N'ACID properties define the standard for reliable transaction processing, ensuring that a database remains in a consistent state even in the event of errors or hardware failure. While critical for financial and transactional systems, some modern distributed databases relax these constraints to achieve the higher scalability and availability required by web-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41da5b1c-1659-439b-9cca-d7722ca95e3e', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If two team members disagree on the best way to solve a problem, how should the team proceed?', N'Intern', N'The team should analyze the pros and cons of each proposed approach in the context of project goals and constraints. If a consensus cannot be reached, they should present both options to a senior lead who can make a final decision based on technical requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66856ba6-78e8-49b6-a1a3-d77632099567', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What steps do you take when you realize you will miss a project deadline?', N'Intern', N'I would communicate the delay to my supervisor as soon as I identify the risk, rather than waiting until the deadline passes. I would explain the bottleneck, provide a revised completion estimate, and ask for guidance on whether to deprioritize other tasks to focus on this one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'933fe471-7c35-4f8b-91a0-d77bf529d105', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'In what scenario would you decide NOT to use Tailwind CSS in a project?', N'Senior', N'Tailwind may be inappropriate for projects with extremely strict requirements for legacy browser support where modern CSS features are unsupported, or for simple projects where the overhead of a build step outweighs the benefits of a utility-first workflow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
