INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21534cde-a5a2-4610-8fa9-d7808d249a95', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is an inline function?', N'Fresher', N'An inline function is a function that the compiler attempts to expand in-place at the point of each call. This reduces the overhead of function calls but can increase the binary size if used excessively for large functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7224134d-b9e2-4ac5-b2d9-d78116340edb', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is a Qwik ''loader'' used for?', N'Junior', N'A loader is a function used to fetch data for a component during the server-side rendering process. It ensures the necessary data is available when the page is served to the client, preventing unnecessary client-side fetch requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70c0a96b-6c6a-41d1-a59a-d784029372f6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What are the advantages of using the ''data.table'' package compared to base R for large data?', N'Senior', N'The data.table package introduces a memory-efficient, in-place modification architecture that avoids the overhead of the standard copy-on-modify semantics. By optimizing internal lookups and minimizing allocations, it provides significantly better performance and lower memory usage for large, heterogeneous datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fce4444-3426-418b-a5c1-d786d3a90053', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the Micronaut ''Bean'' scope, and why is it important for performance?', N'Middle', N'Bean scopes define the lifecycle of a component, such as Singleton, Prototype, or Request. By selecting appropriate scopes, developers can reduce memory overhead and garbage collection pressure, as singletons are created once and reused throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64c4a8cc-dc50-430f-9962-d787c695c743', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the primary purpose of a Partition Key in DynamoDB, and how does it influence data distribution?', N'Junior', N'The Partition Key is the primary component of a table''s primary key and is used as input for an internal hash function to determine the physical partition where the data is stored. By choosing a partition key with high cardinality, you ensure that data is distributed evenly across multiple partitions, which prevents performance bottlenecks known as hot partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33df659f-f208-4a61-8dca-d788ba6d6586', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle the ''C10k'' problem?', N'Senior', N'By building on top of Hyper and Tokio, Axum handles the C10k problem by using an event-loop architecture that avoids the high memory cost of OS threads. Each connection consumes very few resources, allowing the application to scale horizontally and vertically to accommodate thousands of concurrent users with minimal hardware investment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f4d3d61-3c6d-4ecb-909b-d78aad99d57c', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle dynamic routes?', N'Fresher', N'Dynamic routes are created by using brackets in the file name, such as [id]/+page.svelte. This allows you to capture parameters from the URL, which can then be accessed via the params object in your load functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05c1709b-2527-4950-815f-d78bb137393a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you balance the need for speed with the need for quality in engineering?', N'Fresher', N'I maintain quality by adhering to best practices and writing clean, documented work, which prevents long-term technical debt. I balance this with speed by focusing on core requirements and avoiding unnecessary features until they are proven to be needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e7cb3d3-09ac-4801-90dd-d78c9c08632e', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''strict'' flag in tsconfig.json do?', N'Middle', N'The ''strict'' flag enables a wide range of type-checking behaviors that ensure stronger guarantees about your code, such as strict null checks and consistent ''this'' typing. It is highly recommended to enable this to catch potential bugs early in the development lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e801baa-aca5-41a2-b868-d78d22a8b352', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React batch multiple state updates?', N'Fresher', N'React prevents component from re-rendering for each and every state update by grouping multiple state updates within an event handler. This strategy improves the application performance and this process known as batching. The older version of React only supported batching for browser events whereas React18 supported for asynchronous actions, timeouts and intervals along with native events. This improved version of batching is called automatic batching. Let''s demonstrate this automatic batching feature with a below example. The preceding code updated two state variables with in an event handler. However, React will perform automatic batching feature and the component will be re-rendered only once for better performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09102d3c-d998-4919-b2f4-d78d6b0ec1e9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core handle memory management for large request bodies to avoid memory pressure?', N'Senior', N'The framework utilizes memory pooling through `ArrayPool` and streaming APIs to process large request bodies without loading the entire payload into RAM. By working with streams, the application can handle large file uploads or data imports efficiently, preventing `OutOfMemoryException` errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b330a38-1a08-46f4-9de0-d79001e1602e', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain how Micronaut''s ''Security'' module integrates with authentication providers.', N'Senior', N'The Micronaut Security module offers a pluggable architecture for authentication, supporting protocols like JWT, OAuth2, and OpenID Connect. It leverages interceptors to protect routes based on security rules, ensuring a consistent and modular approach to securing service endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aee7dbef-4c7a-4a82-8425-d791941a1ff9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the limitations of multi-document ACID transactions regarding performance and lock duration?', N'Senior', N'Multi-document transactions incur overhead due to the need for state tracking and conflict detection across multiple shards or documents. Long-running transactions can hold locks that prevent other operations from proceeding, potentially leading to increased latency and transaction aborts due to write conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eff8542-6f33-4cae-9613-d791c58e96a0', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is security often at odds with user experience?', N'Intern', N'High security, such as multi-factor authentication or frequent timeouts, adds friction to the user''s workflow. The trade-off involves finding the ''sweet spot'' where the system is secure enough to protect data without frustrating the user to the point of abandonment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5af5fdf-b53a-47ba-8e76-d7923167b8fc', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is Nuxt.js?', N'Intern', N'Nuxt.js is an open-source framework based on Vue.js that simplifies the development of web applications. It provides a structured architecture and out-of-the-box features like server-side rendering, static site generation, and automatic routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8413e0e-4489-4df7-bf9f-d794d6a7affa', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a fix works in your local environment but fails in the staging environment, what might be the cause?', N'Junior', N'The issue is likely due to environment-specific differences such as database content, environment variables, or external service dependencies. I would compare the configuration settings and infrastructure state of both environments to identify the missing or conflicting factor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'967cc02f-81a2-4641-93d2-d7952c385cfb', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the ''select'' statement handle multiple channel operations, and what are its performance considerations?', N'Senior', N'The select statement enables a goroutine to wait on multiple channel operations, choosing one at random if multiple are ready. While it provides powerful flow control, it involves runtime overhead for polling all involved channels, which can become a bottleneck if overused in tight loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21e074b6-506d-47ad-b9bd-d79b9ab97bb3', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you create your own package in Python?', N'Fresher', N'It overrides the any initialization from an inherited class and is called when the class is instantiated. We know that a package may contain sub-packages and modules. A module is nothing but Python code. To create a package of our own, we create a directory and create a file init.py in it. We leave it empty. Then, in that package, we create a module(s) with whatever code we want. For a detailed explanation with pictures, refer to Python Packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0b1f8d2-fce7-4e14-abc7-d79c14ab3edc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are global variables', N'Intern', N'Global variables are those that are available throughout the length of the code without any scope. The var keyword is used to declare a local variable but if you omit it then it will become global variable', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5106aa76-a717-445e-8373-d79c9db9d4a1', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you handle environment variables in a Flask application?', N'Junior', N'Environment variables are typically handled using a configuration file or a library like python-dotenv. Storing sensitive information like API keys and database credentials in environment variables keeps them out of the source code for security.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd6e3a14-c3d3-42b7-9801-d79cbef99997', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary benefit of using Vite for a frontend project?', N'Junior', N'The primary benefit is significantly faster Hot Module Replacement (HMR) and development server startup. Because it does not bundle the entire application during development, changes are reflected almost instantly regardless of project size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c99603d-4862-4da8-b875-d79da4974727', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact handle property drilling?', N'Intern', N'Preact manages property drilling using the Context API, which allows data to be passed through the component tree without manually passing props at every level. This is useful for global data like themes or user authentication status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab05344c-43c6-46cc-8ac5-d7a07da70900', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle data validation?', N'Intern', N'Echo supports integration with validation libraries to ensure that the data received from requests meets specific criteria. By using a validator, you can verify fields like required strings or numeric ranges before processing the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d240abc-48e9-4a70-9d99-d7a2d22ab53a', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of the ''body-parser'' in older Express versions?', N'Intern', N'Body-parser was a middleware used to extract the entire body portion of an incoming request stream and expose it on the request object. In modern Express, this functionality is built-in, so external middleware is no longer required for parsing JSON or URL-encoded data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88da5770-071c-4ea7-b512-d7a55942d3e4', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Why is connection pooling important for high-traffic databases?', N'Senior', N'Establishing a new database connection is an expensive operation in terms of time and system resources. Connection pooling maintains a set of open connections that are reused across requests, preventing the database from becoming overwhelmed by connection overhead and limiting the total number of concurrent active connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01657ffc-aeb9-4cf4-a07b-d7a7b7d1d959', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are props in SolidJS?', N'Intern', N'Props are read-only objects passed to components to receive data from parent components. In SolidJS, props are reactive, meaning you can track changes to them directly if they are accessed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'350880b8-b190-42d9-b5b8-d7abf578b89a', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does sharding a database affect the implementation of global secondary indexes?', N'Senior', N'Sharding complicates secondary indexes because an index entry might reside on a different shard than the primary record, necessitating cross-shard lookups. Architects often address this by creating local indexes within shards or by implementing a global index service, which introduces significant cross-shard coordination and latency overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9a9aea5-8b54-4e47-9069-d7b2e1d82505', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the difference between function foo() {} and var foo = function() {}?', N'Fresher', N'1. Function Declaration: Function declarations are evaluated upon entry into the enclosing scope, before any step-by-step code is executed. The function''s name (foo) is added to the enclosing scope. 2. Function Expression: Function expressions are evaluated as part of the step-by-step code, at the point where they appear. That one creates a function with no name, which it assigns to the foo variable. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fded978-45a4-4747-8286-d7b3adbf03df', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the difference between an inverted index and a forward index?', N'Intern', N'A forward index maps documents to the terms they contain, which is efficient for retrieving the content of a specific document. An inverted index maps terms to the documents they appear in, which is efficient for searching across many documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe6ffaa5-54fe-4802-bf13-d7b43ce35d33', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is the Vert.x event loop model central to Quarkus''s performance?', N'Senior', N'The Vert.x event loop is designed for high-concurrency, non-blocking I/O. By using this model, Quarkus minimizes context switching between threads, allowing the CPU to spend more time processing requests rather than managing thread synchronization and blocking states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7acef7aa-fd83-41d5-92f1-d7b8b960ee5b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum compare to other Rust frameworks like Actix-web?', N'Intern', N'While both are high-performance frameworks, Axum is built on Tower and focuses on providing an API that feels like idiomatic Rust. Actix-web is known for its custom actor-based heritage and high performance, while Axum emphasizes modularity through Tower.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac2cec5d-f7f6-49ca-8183-d7bba1fd03d7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is async/await and how does it relate to Promises under the hood?', N'Senior', N'async/await is syntactic sugar over the Promise API introduced in ES2017 (ES8). An async function always returns a Promise — if you return a plain value, the runtime wraps it in Promise.resolve(value); if you throw, it wraps the error in Promise.reject(error). The await keyword can only be used inside an async function (or at the top level of an ES module). When the engine encounters await expr, it: 1. Evaluates expr — converting it to a Promise if it isn''t one already. 2. Suspends the current async function, saving its execution context (local variables, instruction pointer) to the heap as a microtask continuation. 3. Returns control to the caller immediately (non-blocking). 4. When the awaited Promise settles, the microtask queue schedules resumption of the suspended function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5d22852-2175-4f6f-8da0-d7c0866a2cc7', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Shadow Traffic'' testing improve system reliability?', N'Senior', N'Shadow traffic involves routing a copy of live production traffic to a new service version without affecting the user response. It allows engineers to observe how the new code performs under real-world conditions, identifying bugs and performance issues without risking user data or availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef5c5316-cb44-42e2-a2cb-d7c08947a4c6', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are Django sessions?', N'Fresher', N'Sessions allow you to store and retrieve arbitrary data on a per-site-visitor basis. It maintains state between different HTTP requests, which is essential for features like shopping carts or user authentication status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc20a6da-ba87-4cd1-8116-d7c0f67f0035', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you approach debugging a system that is failing only under specific conditions?', N'Fresher', N'I would start by reproducing the error in a controlled environment to verify the conditions that trigger it. Once reproduced, I would use logging and step-by-step observation to isolate the variable or component causing the unexpected behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15a5dc58-2c6c-4906-943f-d7c348f29a33', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How does implementing an Event-Driven Architecture (EDA) complicate security auditing?', N'Senior', N'EDA decouples producers and consumers, making it harder to trace the lifecycle of a request across multiple services and message brokers. To maintain auditability, architects must implement distributed tracing with security metadata attached to events and ensure that the message bus itself supports encryption and strict access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ef8712b-57d1-4525-b6c3-d7c41d3b3d10', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the function of the ''Micronaut Data'' project?', N'Middle', N'Micronaut Data is a database access toolkit that performs query generation at compile time rather than at runtime. It inspects repository interfaces and annotations to generate the necessary SQL, avoiding the performance overhead of traditional ORMs that generate queries using reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e436b74e-bc7f-4396-ac16-d7c45b775a1d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a Data Center in Cassandra?', N'Intern', N'A data center is a grouping of nodes within a cluster, often physically located in the same geographic region. Cassandra uses this grouping to optimize data replication and minimize latency across wide-area networks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'140b3c29-0878-4c77-8ce3-d7c48e38146f', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Explain the concept of ''Hydration'' in the context of Astro.', N'Middle', N'Hydration is the process of attaching event listeners and state management to static HTML components on the client side. Astro allows developers to control this process via client directives, ensuring hydration only happens when and where it is strictly necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'206576ad-0aac-4652-88cb-d7c67095642d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is ''lazy loading'' and how does Qwik leverage it?', N'Fresher', N'Lazy loading is the practice of delaying the loading of non-critical resources until they are required. Qwik leverages this by splitting the application into small chunks and only downloading the specific chunk required for an interaction, making the initial page load extremely fast.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a4a476-c3c6-4d0f-aebd-d7c7088cd643', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the compiler in Svelte?', N'Intern', N'The compiler is the core of Svelte''s architecture that runs during the build process. It analyzes your components and converts them into optimized JavaScript that directly manipulates the DOM, removing the need for a framework runtime in the user''s browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b82ab6a-2198-416f-9a21-d7c836cbee32', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik manage server-side state transfer to the client?', N'Senior', N'Qwik serializes the application state into the DOM as part of the initial HTML payload. When the client-side code resumes, it reads the serialized state from the DOM, effectively ''hydrating'' the data without needing to re-run expensive server-side data fetching logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2400f85c-1fba-4c1f-ac9f-d7c89b03031a', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Angular and how is it different from AngularJS?', N'Intern', N'Angular is a modern, open-source framework developed by Google for building large-scale, single-page applications (SPAs) primarily using TypeScript. It follows a component-based architecture and provides a comprehensive set of tools and features for development, including routing, forms, state management, and testing utilities. Angular is a complete rewrite of its predecessor, AngularJS (version 1.x), and is not backward compatible. The key differences include: - Architecture: Angular uses a component-based structure, while AngularJS used MVC/MVVM patterns with controllers and scopes. - Language: Angular is built with and strongly encourages TypeScript, whereas AngularJS was primarily JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0fc6931-5eae-4954-8ac0-d7c969c6deff', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the common data structures supported by Redis?', N'Intern', N'Redis supports various data structures including strings, lists, sets, sorted sets, hashes, and bitmaps. These structures allow developers to model data in more complex ways than just simple key-value pairs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb4f334b-143f-46fe-84b7-d7c993714125', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro be used for static site generation?', N'Fresher', N'Yes, static site generation is the default behavior of Astro. It builds the site into pure HTML and CSS files, which can be easily hosted on any static hosting provider like Netlify, Vercel, or GitHub Pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fefc3652-0ce1-4d27-9177-d7ce8aaca586', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Are joins supported in MongoDB?', N'Intern', N'MongoDB does not support traditional relational joins, but it provides a lookup operator in its aggregation framework. This allows users to perform left outer joins between collections, though it is generally recommended to model data in a way that minimizes the need for joins.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcae1338-99e2-43d0-b5ca-d7d0f41f58d2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary challenge when scaling a Phoenix application globally?', N'Middle', N'The primary challenge is managing distributed state and PubSub across geographical regions, as the default clustering mechanism relies on low-latency node connectivity. Developers often have to implement custom strategies like using Redis or PG2 to bridge PubSub events across data centers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2386eac9-40fc-4580-b305-d7d18879f83b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the interaction between Tokio tasks and Axum request processing.', N'Senior', N'When a request hits an Axum server, the underlying Hyper server spawns a new Tokio task to handle it. This ensures that a long-running computation or a blocked I/O operation in one request does not stall the entire event loop, maintaining high throughput for the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeb3ee27-1264-41cc-8438-d7d3ce230b00', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle cookies?', N'Fresher', N'Express does not handle cookies by default. To handle cookies, you typically use the ''cookie-parser'' middleware, which parses the Cookie header and populates the req.cookies object with an object keyed by the cookie names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c110925-b9f4-4542-a779-d7d5485d2b3e', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the primary purpose of NestJS in backend development?', N'Intern', N'NestJS is a progressive Node.js framework used to build efficient, scalable, and enterprise-grade server-side applications. It provides an out-of-the-box application architecture that allows developers to create highly testable, scalable, and loosely coupled applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3f50f4e-7da5-4bd8-902b-d7d7893c38b1', N'954a0331-deff-4399-b588-96f39fec001d', N'How does Angular''s AOT (Ahead-of-Time) compilation impact application security and performance?', N'Senior', N'AOT compiles HTML and TypeScript into efficient JavaScript during the build process, preventing injection vulnerabilities by pre-validating templates. It also reduces runtime overhead by eliminating the need for the compiler to be shipped with the bundle, leading to faster initial page loads and reduced memory footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'333c171f-fe40-4262-8fce-d7d9ebabe1d9', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What does the ''Redirect'' method do in Gin?', N'Intern', N'The redirect method allows the server to send an HTTP response that instructs the client''s browser or API consumer to navigate to a different URL. It is commonly used after successful operations like form submissions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'332e5c29-b993-41fa-8ae4-d7da6f5455f0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the common strategies for logging in a production Node.js environment?', N'Middle', N'You should use structured logging in JSON format, which allows log aggregation tools to index and search logs effectively. It is also important to implement log levels like info, warn, and error to filter noise and focus on critical issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8573e5d3-2b26-42f4-b511-d7df38a5a758', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the function of a partition key?', N'Intern', N'The partition key is an attribute used by DynamoDB''s internal hash function to determine the physical location where the data is stored. It ensures data is distributed across multiple partitions for scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feb72bfe-d500-4358-937a-d7dfd5775978', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some popular JavaScript testing frameworks?', N'Fresher', N'Some popular JavaScript testing frameworks include Jest, Mocha, Jasmine, and Cypress. Jest is known for its simplicity and integration with React. Mocha is highly flexible and often used with other libraries like Chai for assertions. Jasmine is a behavior-driven development framework that requires no additional libraries. Cypress is an end-to-end testing framework that provides a great developer experience. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac5ceb29-cc4a-4f63-a398-d7e65c55259f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is ''Middleware'' in a web framework?', N'Intern', N'Middleware is software that sits between the incoming request and the final handler. In Rocket, features like fairings act as middleware to process or modify requests and responses globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bfeda33-da1e-41ab-954e-d7e8d8bcb2dc', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between ''=='' and ''equal?'' in Ruby?', N'Intern', N'The ''=='' operator checks for value equality, determining if two objects contain the same content. The ''equal?'' method checks for object identity, determining if both references point to the exact same object in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f413d39-f873-48db-98bc-d7eb676f796f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket ensure type safety?', N'Fresher', N'Rocket utilizes Rust''s strong static type system to ensure that request parameters match the types expected by the handler functions. If a type mismatch occurs during parsing, Rocket returns an error response automatically, preventing invalid data from reaching your logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e92ea7a0-efaf-4da5-ba87-d7eb6a642e88', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the Scan operation?', N'Junior', N'The Scan operation reads every item in a table or index. It is generally inefficient for large datasets and should be used sparingly, as it consumes significant read capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c2afada-514a-4902-a978-d7ed39311b71', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why would you choose SvelteKit over a standard Svelte application?', N'Middle', N'SvelteKit provides a production-ready framework with built-in routing, server-side rendering, data fetching, and API capabilities. A standard Svelte application requires manual configuration for these features, making SvelteKit the better choice for full-stack, scalable web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e45ad3c-f531-45a0-9696-d7ef5d72b333', N'4c000000-0000-0000-0000-000000000005', N'What is the purpose of a circuit breaker pattern?', N'Middle', N'The circuit breaker pattern prevents a service from repeatedly trying to execute an operation that is likely to fail. By failing fast, it allows the upstream system to recover and prevents a cascading failure across the entire architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f46ab7e1-c8e5-47e1-b571-d7f29fce71e3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How do replica shards improve both availability and performance?', N'Middle', N'Replica shards provide high availability by ensuring data remains accessible even if a node fails. They also improve read throughput because search requests can be distributed across all available replicas of a shard, effectively scaling read capacity horizontally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11f3a487-de66-4689-9ae2-d7f3e4760491', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between event.preventDefault() and event.stopPropagation()?', N'Fresher', N'event.preventDefault() is used to prevent the default action that belongs to the event, such as preventing a form from submitting. event.stopPropagation() is used to stop the event from bubbling up to parent elements, preventing any parent event handlers from being executed. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bf92298-112c-4c48-88ad-d7f4f23bff71', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix''s ''Presence'' module handle the issue of distributed state tracking?', N'Middle', N'Presence uses a Conflict-free Replicated Data Type (CRDT) to track the state of connected users across a distributed cluster. It ensures eventual consistency by synchronizing presence information between nodes without requiring a central database or a single source of truth, making it highly resilient to network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'586d75a4-084f-44ac-abb7-d7f56b51a157', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the architectural impact of moving logic out of a Phoenix Controller and into a ''Context'' module?', N'Senior', N'Moving logic into Contexts enforces a clear boundary between the web layer and the domain logic, ensuring that database operations and business rules are reusable and decoupled from HTTP concerns. This leads to a more maintainable codebase where business logic can be tested in isolation from the Phoenix web framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef981aa-f9bb-4533-876d-d7f80441bfea', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle dependency injection in a way that differs from Spring?', N'Senior', N'Quarkus uses ArC, a CDI-based dependency injection container optimized for build-time resolution. Unlike traditional frameworks that resolve dependencies via reflection at runtime, ArC generates the necessary wiring logic during build time, ensuring type safety and performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23161ac6-4672-4abd-b0f3-d7f827275339', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the advantages of using dependency injection over a service locator pattern?', N'Middle', N'Dependency injection makes dependencies explicit in the constructor, which significantly improves testability and readability. A service locator acts as a global registry that hides dependencies, making it difficult to determine what a class requires without reading the implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e35359e-cf8f-452e-b21b-d7fe618b9e1a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''as'' keyword do in TypeScript?', N'Junior', N'The ''as'' keyword is used for type assertions, which tell the compiler to treat a value as a specific type even if the compiler cannot verify it. It should be used carefully, as it overrides the compiler''s safety checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f578d870-9def-4614-b1a0-d7ff62a60f54', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the default behavior of Fastify when an error occurs in a plugin?', N'Junior', N'If a plugin fails to load, Fastify will catch the error and stop the application startup process. This fail-fast behavior ensures that your application does not run in an unstable or misconfigured state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58310ba5-6570-4148-bf7f-d7ffa2ab8ea1', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a ''before_action'' and a standard controller method?', N'Fresher', N'A ''before_action'' is a filter that runs automatically before a specific controller action is executed. It is commonly used for tasks like authentication or loading a resource, whereas a standard controller method contains the specific logic required to handle the final request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'271b3e5f-747e-4a4c-99d7-d800c688b601', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What is the role of historical data in improving your estimation accuracy?', N'Middle', N'Historical data serves as a reality check for future estimates by providing evidence of our actual velocity and the frequency of unexpected roadblocks. By reviewing past sprint outcomes, I can adjust my estimation baseline to be more reflective of the team''s true pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50e7e49f-7330-45fe-9d4b-d801fc70ce05', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is an alias in Elasticsearch?', N'Intern', N'An alias is a virtual name that points to one or more indices. It allows users to refer to an alias in search queries, making it easy to swap underlying indices without changing application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a40ea069-a1c2-4127-9384-d802b882e91c', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do attributes affect the behavior of objects in R?', N'Middle', N'Attributes are metadata attached to R objects that can fundamentally change how generic functions treat the object. For example, changing the ''class'' attribute of an object will determine which methods are dispatched to it during function calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff4dd525-b839-49ce-a04e-d802f71dd8ae', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the common strategies for managing migrations in a Flask application?', N'Middle', N'The standard strategy is using Flask-Migrate, which is a wrapper around Alembic. It tracks changes to your database schema and generates migration scripts that can be applied to update the database. This ensures that database schema evolution is consistent across development, staging, and production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fbb8d1a-542a-44c5-b762-d80378fbd13c', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is Chi in the context of Go web development?', N'Intern', N'Chi is a lightweight, idiomatic, and composable router for building HTTP services in Go. It is designed to be compatible with the standard library''s net/http package while providing additional features like URL parameter parsing and middleware support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8dfc1cb-2c1c-483e-8de6-d8063dc0353a', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle request routing internally, and what is the performance impact of high-volume route registration?', N'Senior', N'Flask uses the Werkzeug routing system, which maps URL patterns to view functions by iterating through a rule map. A massive number of routes can increase memory usage and latency during the matching process, so for high-scale applications, grouping routes within Blueprints or implementing dynamic routing patterns is preferred over flat route registration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'539f8f9d-e7ff-45e8-8c4c-d808941fff28', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact considered more ''future-proof'' regarding browser standards?', N'Middle', N'Preact is designed to evolve alongside web standards rather than wrapping them in proprietary layers. By relying on native DOM APIs, it ensures that as browsers improve their native capabilities, Preact applications naturally benefit from those performance and feature enhancements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3351136-fc78-4618-af7a-d8117928cba6', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Are Fastify plugins synchronous or asynchronous?', N'Fresher', N'Fastify plugins can be either synchronous or asynchronous. If a plugin needs to perform an asynchronous task, such as connecting to a database, it should return a Promise or use the callback provided by the registration function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0695c7ee-8fd1-4887-ba54-d8172245f8b7', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle inheritance?', N'Fresher', N'Ruby supports single inheritance, meaning a class can inherit features from only one superclass. This structure helps maintain a clear and predictable hierarchy in the object model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ce8e6f-c092-46a4-a2c8-d81757afaff2', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro''s ''Client Directives'' system impact performance compared to typical framework hydration?', N'Middle', N'Client directives allow developers to control exactly when and how individual components are hydrated on the client side. By using directives like client:idle or client:visible, Astro defers loading and executing JavaScript for non-critical components until they are actually needed. This significantly reduces the initial page load time and the total main-thread blocking time compared to full-page hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46fdc19c-d316-46bd-884d-d817da35c70d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi often preferred over Gorilla Mux for large-scale production services?', N'Senior', N'Chi is generally preferred because it adheres strictly to the standard net/http.Handler interface, providing better interoperability with the ecosystem. It also avoids the heavy use of reflection found in older routers, leading to better performance and easier debugging through stack traces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af31c00e-c247-48a0-9c5c-d81a10bc0533', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do you manage cross-cutting concerns like distributed tracing in a Fastify ecosystem?', N'Senior', N'You should use the ''onRequest'' or ''preHandler'' hooks to extract or inject trace IDs and integrate with OpenTelemetry. By wrapping the request lifecycle with tracing spans, you gain visibility into the entire request flow across microservices without modifying business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8bd1357-2563-4cae-84ee-d81ab8ee1b70', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro maintain SEO integrity when using client-side interactivity?', N'Senior', N'Astro prioritizes server-rendered HTML for all interactive components, ensuring that search engine crawlers receive the complete content of the page immediately upon request. Because client-side JavaScript is only used for enhancement rather than core content delivery, there is no risk of crawlers missing critical page information due to hydration delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c0ecaa6-b70c-4db3-8437-d81b2381ea45', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do memory-mapped files or swap impact Redis performance?', N'Senior', N'Redis is designed to be an in-memory store, so it relies on RAM for performance. If the OS swaps Redis memory to disk, the performance will drop by several orders of magnitude due to disk I/O latency, making it vital to disable swap or ensure sufficient memory allocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89026f80-5436-4a6f-b797-d81d61cb821d', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do Migrations help in a development team?', N'Junior', N'Migrations act as version control for your database schema. They allow team members to share database structure changes consistently without manually running SQL scripts, ensuring everyone''s local environment stays synced with the production structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4fab778-c601-40af-be72-d82211fb8812', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''as const'' assertion affect object literals?', N'Middle', N'The ''as const'' assertion tells the compiler to treat an object or array as a literal type, making all properties recursively read-only. This prevents TypeScript from widening types, which is useful when working with configuration objects or constant value sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c1abd2e-3496-461d-afd1-d82268981ea3', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between a declarative and imperative approach in Angular?', N'Middle', N'The imperative approach involves manually managing state and DOM updates, often leading to complex, hard-to-track side effects. The declarative approach, typically using observables and pipes, describes the desired state, allowing Angular to handle the synchronization of that state with the UI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7425eaa-bcc7-4dd6-996a-d823fbe233ad', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when implementing a multi-region deployment compared to a single-region deployment?', N'Senior', N'Multi-region deployments provide disaster recovery and reduced latency for global users, but they introduce significant complexity in data replication, synchronization, and conflict resolution. Single-region deployments are simpler and cost-effective but represent a single point of failure and higher latency for geographically distant users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'271e56e8-ce1b-4e6c-89f6-d82801b33880', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is application state in Actix-web?', N'Intern', N'Application state is a thread-safe data container that can be shared across all request handlers in an application. It is commonly used to store database connection pools or configuration settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78ab3a4f-4fa6-4404-8bc7-d82816db3f55', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle browser inconsistencies, and is this still relevant today?', N'Middle', N'jQuery abstracts away browser-specific quirks by normalizing events, AJAX behavior, and CSS property names across different engines. This is largely irrelevant in modern web development because current browsers adhere closely to W3C standards, removing the need for such a heavy compatibility layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e5237db-fe5e-4445-8d7e-d8282990eba1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are query parameters in Fiber?', N'Intern', N'Query parameters are key-value pairs appended to the URL after a question mark. Fiber provides methods to retrieve these values from the request context to filter or sort data in an API request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d82b731-1813-424b-a7de-d828a7d9a807', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a request and a response in Flask?', N'Intern', N'A request represents the data sent by the client to the server, such as parameters, headers, and body content. A response is the data sent by the server back to the client, typically containing HTML content, JSON data, or status codes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ae3a23c-4d70-4858-bc20-d82b494cc1c4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a header file in C++?', N'Intern', N'A header file is a file containing declarations of classes, functions, and variables that are shared across multiple source files. It allows different parts of a program to know about the interfaces of modules without needing the full implementation details. Header files are typically included using the preprocessor directive to make their contents available to the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0e4816e-6e2b-4772-98af-d82de614f8f5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the difference between a list and a set in Kotlin?', N'Intern', N'A list is an ordered collection that allows duplicate elements, whereas a set is an unordered collection that contains only unique elements. Both are standard interfaces in the Kotlin collection framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f77e647-2cb2-44e3-afd0-d82f0153e0df', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why does Profiler use in MongoDB?', N'Fresher', N'The database profiler captures data information about read and write operations, cursor operations, and database commands. The database profiler writes data in the system.profile collection, which is a capped collection. The database profiler collects detailed information about Database Commands executed against a running mongod instance. This includes CRUD operations as well as configuration and administration commands. Profiler has 3 profiling levels. * Level 0 - Profiler will not log any data * Level 1 - Profiler will log only slow operations above some threshold * Level 2 - Profiler will log all the operations 1. To get current profiling level. 2. To check current profiling status: 3. To set profiling level:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fab789b6-bb80-46f4-a007-d82f48f14f60', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s virtual DOM diffing algorithm optimize performance, and under what conditions does it become a bottleneck?', N'Senior', N'Vue uses a hybrid approach combining static tree hoisting and patch flags to skip static nodes during re-renders. It becomes a bottleneck when dealing with massive lists or highly dynamic components that require frequent, deep tree traversals, necessitating manual optimizations like ''v-once'' or virtualization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adb4db80-9958-4b47-bf08-d834dfd82766', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby interpret the ''nil'' value?', N'Fresher', N'In Ruby, ''nil'' is an object of the NilClass and represents the absence of a value. It is considered ''falsy'' in conditional statements, meaning any condition evaluating to nil will be treated as false.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5ee4459-9e88-479c-bcfd-d83991efdb87', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How would you handle memory leaks in a Node.js application?', N'Middle', N'Memory leaks are typically handled by taking heap snapshots to identify objects that are not being garbage collected. Common causes include global variables, forgotten event listeners, or closures holding references to large objects, which can be mitigated by ensuring proper cleanup and scoping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
