INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be7c4e4e-1be3-480b-a5cc-d83da00b7514', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Discuss the performance implications of Axum''s reliance on ''hyper'' as its HTTP engine.', N'Senior', N'Relying on hyper provides Axum with a highly optimized, asynchronous HTTP implementation that excels in low-latency environments. This architecture allows Axum to handle a large number of concurrent connections with minimal memory overhead, making it well-suited for high-throughput, IO-bound microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05057176-2cdf-4281-a75b-d83f544f94d5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a type assertion?', N'Intern', N'A type assertion is a way to tell the compiler to treat a value as a specific type, effectively overriding the compiler''s inference. It is used when the developer knows more about the variable''s structure than the compiler does, but it does not perform any actual data conversion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9264c198-a2b0-4f74-bb17-d842860107f7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to use environment variables for configuration instead of hardcoding values?', N'Junior', N'Hardcoding configuration values makes it difficult to manage different settings for development, testing, and production environments. Using environment variables allows the same application build to be deployed across different environments safely without modifying the source code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5636bf85-396d-4bff-8957-d843faf1a82b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Discuss the implications of Gin''s synchronous execution model regarding long-running blocking operations.', N'Senior', N'Gin handlers run synchronously within the goroutine allocated to the request by the underlying net/http server. If a handler performs a blocking operation without offloading it to another goroutine, it will exhaust the server''s connection pool, preventing it from accepting new requests and leading to head-of-line blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00b5ab71-493e-4b02-a942-d8445e2f5c30', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why use an ORM like Lucid instead of raw SQL?', N'Intern', N'An ORM abstracts the database logic into readable code, which makes it easier to maintain and prevents common security risks like SQL injection. It also allows developers to remain productive without needing to be experts in complex SQL syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6365b0a-2a61-410b-b39e-d84670667bd1', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is MongoDB and what are its main features?', N'Intern', N'MongoDB is a robust, document-oriented NoSQL database designed for high performance, scalability, and developer agility. Key Features Flexible Data Model - Employs JSON-like documents (BSON format), facilitating complex data representation, deep nesting, and array structures. - Provides dynamic schema support, allowing on-the-fly data definition and data types. - Permits multi-document transactions within a replica set (group of nodes). Sharding extends this to support large distributed systems. Indexed Queries - Offers extensive indexing capabilities, such as single and multi-field support, text, geospatial, and TTL (Time to Live) Indexes for data expiration. - Gives developers the tools needed to design and optimize query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3e6a407-6f9b-4b4f-9df9-d846d5fcc980', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What architectural challenges arise when implementing a custom object proxy for performance-sensitive data structures?', N'Senior', N'Proxies introduce a layer of indirection that prevents the engine from applying standard optimizations like inline caching or hidden class transitions. Frequent proxy usage often leads to significant performance degradation compared to plain objects or classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa1b0f43-04c4-4fde-b915-d84b8c9b23a3', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can interpolation be used in Sass?', N'Middle', N'Interpolation allows you to inject Sass variables or expressions into strings or selectors where they are not usually allowed. It is commonly used for dynamic property names, media query strings, or generating class names based on loop indices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
