INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'628ebccc-9261-4501-acb0-d84dc932040a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle styling compared to CSS-in-JS libraries?', N'Middle', N'SolidJS encourages standard CSS or CSS modules to leverage the browser''s native capabilities. Since it does not use a Virtual DOM, the overhead of CSS-in-JS runtime injection is often unnecessary and less performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
