INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bf0f97a-cb6c-4671-9e0a-d859d96c64c2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why is Chi often described as ''zero-dependency''?', N'Intern', N'Chi is called zero-dependency because it relies only on the Go standard library. This minimizes the risk of supply-chain vulnerabilities and keeps the project''s build size small and manageable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cefb2e71-6184-40f0-8240-d8631918c17b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What happens if a database transaction exceeds its timeout limit?', N'Middle', N'If a transaction exceeds its timeout, the database management system will force an abort to prevent it from holding locks indefinitely. This protects the overall health and responsiveness of the database by clearing out blocked resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b83bf0b4-5aa3-46e0-8682-d867d4277a63', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are the main components of a NestJS application?', N'Intern', N'The main contents of the nestjs application inlcude: Modules: Modules are a way of organizing related components into a single block. They provide a way to structure your application. Controllers: Controllers are responsible for handling incoming requests and returning responses to the client.Controllers organize routes and handle HTTP requests that come to those routes. Services: services are responsible for business logic and interacting with data sources. They can be injected into controllers or other services, promoting code reusability and separation of concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2880a494-7fdf-47f4-8442-d86c09db043d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do CRDTs facilitate conflict resolution in multi-master NoSQL systems?', N'Senior', N'Conflict-free Replicated Data Types (CRDTs) use mathematically defined structures that ensure updates are commutative and associative. This allows nodes to merge state updates independently without a central coordinator, eventually reaching a consistent state across replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68c3260b-de98-44c0-b52a-d86c3df3e662', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the Link component?', N'Intern', N'The Link component is a built-in replacement for the standard HTML anchor tag. It enables optimized client-side navigation between pages within the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e87411f7-7d15-4aa8-b7b2-d86c74b6b42d', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between ngIf and hidden property?', N'Fresher', N'The main difference is that *ngIf will remove the element from the DOM, while [hidden] actually plays with the CSS style by setting display:none. Generally it is expensive to add and remove stuff from the DOM for frequent actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eff72348-9a40-4dfe-96d0-d86e6ec5cb8e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a primary key in a PostgreSQL table?', N'Intern', N'A primary key is a column or a set of columns that uniquely identifies each row in a table. It must contain unique values and cannot contain null values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90807b98-3774-4efb-91c8-d8703229f3c4', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the ''DefinePlugin'' and when would you use it?', N'Middle', N'The DefinePlugin allows you to create global constants that are configured at compile time. It is commonly used to inject environment-specific variables like API endpoints or feature flags into the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f9877cb-d781-44f9-8251-d87511aae980', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Under what conditions would you prefer a fan-out (Pub/Sub) pattern over a Competing Consumers pattern?', N'Senior', N'Fan-out is preferred when multiple independent downstream services need to react to the same event, ensuring decoupled extensibility. Competing Consumers is preferred when the objective is to distribute a high volume of work across multiple instances of the same service to improve throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb1522c4-fa2a-4b8a-bc96-d87f0e645704', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you design for auditability in a distributed system?', N'Senior', N'Design a centralized, immutable logging architecture where every security-sensitive action generates a signed, timestamped event containing the user identity, resource, and result. These logs must be streamed in real-time to a secure, write-once-read-many storage system to prevent tampering by intruders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43b724ec-5cd3-4d87-9ae6-d883825c0770', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the trade-offs of using database normalization.', N'Middle', N'Normalization reduces data redundancy and improves data integrity by organizing tables into logical structures. However, excessive normalization can lead to complex multi-table joins that degrade read performance, requiring a balance based on the application''s read-to-write ratio.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43cb883d-8b0e-4f6a-93d0-d883cbac353d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What factors influence your decision between using an SQL versus a NoSQL database for a new product feature?', N'Middle', N'I evaluate the data structure''s consistency requirements and the expected query patterns. If the data requires complex relationships, ACID transactions, and a fixed schema, SQL is the better choice; if the data is highly unstructured, requires massive horizontal scalability, or has rapidly evolving schema needs, NoSQL is generally more appropriate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'374810c5-aa11-4e91-9462-d8841bb243b2', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the architectural trade-offs when choosing between binary (e.g., Protobuf) and text-based (e.g., JSON) formats for messages?', N'Senior', N'Binary formats significantly reduce message size and CPU serialization overhead, leading to higher throughput and lower storage costs. Text-based formats offer better human readability, easier debugging, and platform independence, making them preferable when performance constraints are secondary to operational simplicity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'856c69a6-617e-4a4c-93c2-d887a2c42b19', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the concept of ''Discriminated Unions'' and why they are preferred over simple unions.', N'Senior', N'Discriminated unions use a common literal property across all members of a union to allow the compiler to narrow down the specific type based on that property. This approach provides exhaustive switch-case checking and precise type inference, significantly improving safety and developer experience compared to standard unions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1560698c-3195-4ce1-8c22-d888b4d587c8', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the concept of ''database sharding'' and the primary trade-off involved with cross-shard operations.', N'Senior', N'Sharding distributes data across multiple nodes based on a partition key to horizontally scale write throughput. The primary trade-off is that cross-shard joins or transactions become significantly more complex, often requiring distributed coordination protocols like 2PC or application-level aggregation, which reduces performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41ed468e-1e37-44e5-82d1-d88933fbec9c', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is Currying?', N'Intern', N'Currying is the process of transforming a function that takes multiple arguments into a chain of functions that each take a single argument. It provides flexibility in function application and partial function usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
