INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5b76a2c-5ed2-40b1-9285-d88e76b100ac', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How do partial indexes (or lack thereof) affect query performance in MySQL?', N'Senior', N'MySQL does not natively support partial indexes (indexes on a subset of rows). Users must work around this by creating full indexes on specific columns, which requires more storage and increases the cost of maintaining the index, or by using generated columns to simulate indexing only specific data patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
