INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f1d9ff0-a4c2-4c8b-b86a-d8974f68050d', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a TypeScript declaration file?', N'Fresher', N'A declaration file, typically ending in .d.ts, provides type information for existing JavaScript code that lacks types. It allows TypeScript to understand external libraries and provide autocompletion and error checking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c762085-d539-42d6-9639-d89a86e418a1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is it dangerous to mutate props directly in React?', N'Senior', N'React''s reconciliation algorithm relies on shallow equality checks to determine if a component should update. Mutating props directly bypasses React''s state management, leading to inconsistent UI states, broken re-renders, and bugs that are extremely difficult to track as the data flow becomes unpredictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dfd9fd1-21dc-4e05-9810-d89e5f5050d0', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is a schema in MySQL?', N'Intern', N'In MySQL, a schema is logically equivalent to a database. It acts as a container for objects such as tables, views, stored procedures, and indexes that belong to a particular application or user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e071bce9-cbd5-4234-8bfd-d8a2ac5617e2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is a ''type'' in TypeScript?', N'Intern', N'A type is a way to define the shape and behavior of data within a program. It tells the compiler what kind of value a variable, function parameter, or object property is expected to hold, allowing the compiler to ensure that the data is used correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9571112e-9ecc-4baa-9c67-d8a456c2c1b8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What does ''non-blocking'' mean in Micronaut?', N'Intern', N'Non-blocking refers to an execution model where the thread is not kept waiting for an I/O operation to complete. Instead, the thread is released to perform other tasks, which allows the application to handle many concurrent connections with very few threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02d4740b-016f-4a56-b278-d8aae4d4d8d2', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the trade-offs of using SvelteKit''s ''page data'' versus global stores for state management?', N'Senior', N'Page data is ephemeral and scoped to the current route, making it ideal for data that needs to be fetched and reset upon navigation. Global stores are better suited for persistent application-wide state that should survive route changes, but they introduce the risk of memory leaks if not managed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'958c55c6-443c-43b9-978c-d8ae2eebedab', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does C# handle ''Covariance'' and ''Contravariance'' with delegates and interfaces?', N'Senior', N'Covariance allows using a more derived type than originally specified, while contravariance allows using a less derived type. In C#, this is restricted to reference types to ensure type safety, preventing invalid casts at runtime. These features enable more flexible API design, particularly in functional programming patterns and collection hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f528aa48-35f4-42fa-8a5b-d8ae38f45aa6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''helmet'' middleware?', N'Intern', N'Helmet is a security middleware that helps protect an Express app by setting various HTTP headers. It mitigates common web vulnerabilities like cross-site scripting and clickjacking by configuring secure default headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
