INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a18d2830-efb9-4049-99ea-d8b2c3170e18', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between a long-polling approach and WebSockets for real-time data updates?', N'Middle', N'WebSockets provide persistent, full-duplex communication with lower latency, which is ideal for highly interactive applications. Long-polling is simpler to implement and more compatible with traditional infrastructure, but it consumes more overhead per request and may not be efficient for high-frequency data updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e245e6f2-336e-44bc-bfe8-d8b393a02b34', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Explain the role of the work-stealing scheduler in the Go runtime.', N'Senior', N'The work-stealing scheduler allows idle processor threads to steal goroutines from the run queues of busy threads. This mechanism ensures load balancing across available CPU cores, minimizing idle time and maximizing throughput in highly concurrent applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a63e4bf-71f5-46c1-b083-d8b40e20dbaa', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is purging unused CSS essential for Tailwind, and how does it function under the hood?', N'Senior', N'Purging is necessary to keep the CSS footprint minimal, as Tailwind''s potential utility surface area is theoretically infinite. The JIT engine scans source files for class strings and dynamically generates the required CSS, ensuring only the necessary rules are present in the final production output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7ecd218-dac6-4712-b993-d8b4706da17d', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is ''database denormalization'' and why is it used for scaling?', N'Middle', N'Denormalization involves intentionally adding redundant data to a database to avoid expensive join operations across tables. While it increases storage usage, it significantly speeds up read performance, which is often a critical bottleneck in large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ce634e5-9a05-4944-b176-d8b547a25c10', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does the MongoDB oplog facilitate replication and disaster recovery?', N'Senior', N'The oplog is a capped collection that acts as a rolling log of all operations that modify data. Secondaries tail this log to replay operations in order, and it is essential for initial sync, catching up after downtime, and point-in-time recovery processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eba2b20c-c219-4553-9f1d-d8b978766519', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage the lifecycle of custom Fairings?', N'Middle', N'Fairings are registered during the application building phase and are executed in a sequence defined by the framework. Rocket manages their activation at specific stages, such as at startup, before a request is processed, or after a response is constructed, ensuring predictable execution order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
