INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'835d7e74-7a99-4b09-8377-d8ca40e3f632', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the trade-offs between using a clustered index versus a secondary index in MySQL?', N'Senior', N'A clustered index physically orders the data rows by the primary key, making primary key lookups extremely fast but causing secondary index lookups to require a pointer resolution. Secondary indexes store the primary key value as a reference, which adds an extra look-up step but allows for efficient non-key filtering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ba609b3-9636-4f70-afe4-d8cc49dee01d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs of caching data at the edge versus at the application server level?', N'Middle', N'Edge caching significantly reduces latency for end-users and offloads traffic from the origin server, but it creates challenges with cache invalidation and data freshness. Application-level caching provides finer control over data consistency and business logic but increases the load on the application infrastructure and requires more careful management of memory resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e143a168-1cf1-4ed5-8b2e-d8cc855e3e70', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s ''infer'' keyword in conditional types enable advanced type extraction?', N'Senior', N'The ''infer'' keyword allows the compiler to extract and name sub-components of a type, such as the return type of a function or the element type of an array. This is a foundational technique for creating powerful utility types that dynamically adapt to the structure of provided data, though it requires careful handling to avoid complex recursive resolution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
