INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f59595f-954b-40d0-bca1-d8d0cb4fa7f8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is async/await and how does it relate to Promises under the hood?', N'Senior', N'async/await is syntactic sugar over the Promise API introduced in ES2017 (ES8). An async function always returns a Promise — if you return a plain value, the runtime wraps it in Promise.resolve(value); if you throw, it wraps the error in Promise.reject(error). The await keyword can only be used inside an async function (or at the top level of an ES module). When the engine encounters await expr, it: 1. Evaluates expr — converting it to a Promise if it isn''t one already. 2. Suspends the current async function, saving its execution context (local variables, instruction pointer) to the heap as a microtask continuation. 3. Returns control to the caller immediately (non-blocking). 4. When the awaited Promise settles, the microtask queue schedules resumption of the suspended function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8ed0768-244e-4013-ae42-d8d0f2ef4b32', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket ensure thread safety in concurrent request handling?', N'Senior', N'Rocket utilizes Rust''s Sync and Send traits to ensure that any data stored in Managed State is safe to share across threads. This prevents data races at the compiler level, enabling safe, high-concurrency request processing without the need for manual locking mechanisms in the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9453235b-2a01-4a70-9f06-d8d39ced106d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle CSS scoping, and what is its primary advantage?', N'Middle', N'Lit uses Shadow DOM to encapsulate styles, ensuring that CSS defined within a component does not leak to the outside and global styles do not accidentally affect the component. This provides true style isolation and prevents naming collisions in large-scale applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
