INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'287cc7ec-0f00-4bc1-8743-d8f07aefbfd2', N'954a0331-deff-4399-b588-96f39fec001d', N'What are dynamic components and how do you create them?', N'Fresher', N'Dynamic components in Angular are components that are not declared in your template but are loaded and rendered programmatically at runtime. You typically use them for scenarios like creating dashboards, modal dialogs, or tabs where the specific component to display isn''t known until the application is running. To create and load a dynamic component: 1. Identify a location in your template where the dynamic component should be inserted. This is usually marked by an element that serves as an anchor point. 2. In your component class, get a reference to the ViewContainerRef associated with that anchor point. You can inject ViewContainerRef and query for elements using @ViewChild or @ViewChildren. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
