INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33326f2a-c4d1-411e-8033-d8fd47838727', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is logging important for troubleshooting, and what makes a good log message?', N'Middle', N'Logs provide a historical record of system events, which is essential for reconstructing the state leading up to a failure. A good log message should include a unique request ID, a clear description of the event, the relevant context or metadata, and a severity level. This structure allows for efficient filtering and correlation across multiple services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e1e1b27-e724-429b-80d3-d8fdb6440929', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using an event-sourcing pattern versus a traditional state-based CRUD approach?', N'Senior', N'Event sourcing provides a perfect audit trail and the ability to reconstruct state at any point in time, which is invaluable for complex domains. However, it introduces significant complexity in querying and requires eventual consistency models that are much harder to debug than standard CRUD.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb037275-fda6-44a1-a946-d8ff05b8a085', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between DROP and DELETE?', N'Fresher', N'DROP is a DDL command that removes the entire table structure and its data from the database. DELETE is a DML command that removes only the data rows while keeping the table structure intact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
