INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e04532f-eecd-4f62-a119-d904bebb6aab', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a reducer and what is its primary responsibility?', N'Junior', N'A reducer is a pure function that takes the current state and an action as arguments and returns a new state object. Its primary responsibility is to calculate the next state based on the action received without modifying the original state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f358e059-e237-4507-849b-d904fb101fcd', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''register'' keyword mean?', N'Junior', N'The ''register'' keyword is a hint to the compiler to store a variable in a CPU register rather than in RAM for faster access. Modern compilers are very good at optimizing this automatically, so the keyword is rarely necessary. It is largely a legacy feature that cannot be used to take the address of a variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a2870e-7c51-4ea0-b0a7-d908eaa23815', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Discuss the challenges of parallelizing R code due to its single-threaded design.', N'Senior', N'R''s core is inherently single-threaded, meaning parallelization requires either process-level parallelism (forking) or node-level distributed computing. Forking introduces significant overhead due to memory duplication on systems without copy-on-write support, and managing state across workers often requires complex serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91e6c11e-7c8d-41ee-9a7c-d90a6326cc75', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Rails connection pool handle database connectivity in a multi-threaded web server environment?', N'Senior', N'The connection pool maintains a set of available database connections that threads checkout when performing queries and return when finished. If all connections are in use, additional threads must wait until one becomes available or a timeout occurs. Proper sizing is critical to prevent thread starvation and database overhead under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed9bdbd4-ff33-4b2e-9bf3-d90b507c8b80', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it important to document your work or code?', N'Intern', N'Documentation acts as a bridge of knowledge between team members, ensuring that others can understand the reasoning and functionality of the work. It saves significant time during onboarding, debugging, and future maintenance. Good documentation ensures that institutional knowledge is not lost when someone leaves the project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78931702-3b94-4de1-b1a1-d90cc8a2be5b', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java Memory Model handle instruction reordering and what role does the happens-before relationship play?', N'Senior', N'The JMM allows the compiler and processor to reorder instructions for optimization as long as the result is consistent with a single-threaded execution. The happens-before relationship establishes a partial ordering on memory operations, ensuring that if one action happens-before another, the results of the first are visible to the second, providing the necessary synchronization for thread safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96711ab3-308a-4f80-a373-d90eca21f428', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the scalability risks of using too many plugins in Fastify?', N'Senior', N'While plugins are isolated, excessive nesting can lead to complex dependency chains and increased startup latency due to the recursive initialization of contexts. It is critical to balance modularity with a flat plugin structure to maintain predictable boot times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dc9a50c-3b60-4511-be63-d90ee4b07107', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the ''Technical Debt'' trade-off?', N'Intern', N'It is the trade-off between building a quick, suboptimal solution to meet an immediate deadline and building a high-quality, maintainable solution. While the quick fix helps short-term velocity, it creates ''interest'' that must be paid back later through refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25c4eb2a-f968-4c22-8836-d910218e0c59', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the role of a HandlerFunc in Echo?', N'Junior', N'A HandlerFunc is a specific function type that processes an HTTP request. It accepts the Echo context as an argument and returns an error, which the framework then handles appropriately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adc5e7a9-9032-4eb8-a3ea-d910ead4b3d0', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are ''Shadow Endpoints'' in SvelteKit and how do they relate to form actions?', N'Middle', N'Shadow endpoints refer to the capability of ''page.server.js'' to export functions that handle POST requests directly within the route file. This simplifies the architecture by keeping the UI and the logic that handles form submissions in the same directory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed5860ad-c7cb-45b3-a2d9-d912b1ca0286', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is currying, and how does it differ from partial application?', N'Intern', N'Currying transforms a function of n arguments into a chain of n unary (single-argument) functions: f(a, b, c) becomes f(a)(b)(c). Each call returns a new function waiting for the next argument until all arguments are supplied. Partial application fixes some arguments of a function, returning a new function that expects the remaining arguments — the result does not have to be unary. The distinction: - Currying always produces unary functions step by step. - Partial application fixes k of n args at once, producing a function of n-k args (which can be > 1). - .bind(null, arg1) is partial application, not currying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1603a78d-b943-442c-905f-d916e0f09682', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Discuss the trade-offs of using doc values versus field data.', N'Senior', N'Doc values are a disk-based, column-oriented structure that is memory-efficient and enabled by default for most fields. Field data is an in-memory structure used for sorting and aggregations on text fields, which is highly memory-intensive and often deprecated in favor of keyword fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd2ebe2b-44a2-4a82-a4a3-d918024bff03', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Describe the impact of ''database connection pooling'' on system scalability.', N'Senior', N'Database connections are expensive to establish and consume significant memory on the database server. Connection pooling allows an application to reuse existing connections, reducing latency and preventing the database from crashing due to thread exhaustion under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
