INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa0ba137-8d62-4b4c-9810-d93cf35c63c5', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Explain the role of the Arbiter in an Actix system.', N'Senior', N'An Arbiter represents a dedicated thread running an asynchronous event loop. It acts as the execution context for actors, managing the lifecycle of tasks and ensuring that blocking operations do not stall the main reactor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fed7c2e0-bde7-441b-a315-d93e4082be51', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are the architectural implications of using ''Result Builders'' in Swift?', N'Senior', N'Result builders transform declarative syntax into a sequence of function calls, effectively building complex trees or structures at compile-time. This reduces the need for imperative boilerplate code but can lead to increased compile times and debugging difficulty due to the abstraction layer it introduces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc006225-e5a0-491f-899c-d942e305c430', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the difference between client-side and server-side rendering?', N'Fresher', N'Client-side rendering builds the page in the browser using JavaScript, which can be faster for navigation once the app is loaded. Server-side rendering generates the full HTML on the server and sends it to the browser, which is generally better for initial page load speed and search engine optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6444628d-147b-4c47-b205-d942ff92caf7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle memory management?', N'Intern', N'Go uses an automatic garbage collector to manage memory. This means developers do not need to manually allocate or free memory, as the runtime automatically reclaims memory that is no longer being referenced by the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21ffd80c-6ba6-48a6-8ea0-d94658dbde5f', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is a poison pill message?', N'Middle', N'A poison pill is a malformed message that consistently causes a consumer to crash or fail during processing. If not handled, it can cycle through retries indefinitely, consuming system resources and blocking the queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff511cac-f0b4-4e61-8565-d947636772cb', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'When would you prefer a custom Express server over the built-in Next.js server?', N'Senior', N'A custom server is only necessary if you need to integrate with legacy middleware, perform complex request manipulation before it hits the Next.js router, or manage custom session logic that isn''t compatible with standard Next.js patterns. In most cases, it is discouraged because it prevents the use of Vercel-specific optimizations and serverless deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f252c41-e461-4cd3-bf3c-d9478b50351a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does NoSQL differ from SQL in terms of data relationships?', N'Intern', N'SQL databases are relational and rely on joins to link data across tables, which requires a structured schema. NoSQL databases typically avoid joins, preferring to store related data together in a single document or structure to improve read performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1f891cb-d210-4285-99d3-d94828896a2d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte manage component lifecycle?', N'Intern', N'Svelte provides lifecycle functions such as onMount, onDestroy, and beforeUpdate. These functions allow you to run code at specific stages of a component''s existence, such as when it is first added to the DOM or just before it is removed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92c2dbca-ac89-4172-b5d8-d948c457f23b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a schema in a relational database?', N'Junior', N'A schema acts as the blueprint or structure of the database, defining the tables, fields, data types, and relationships. It ensures that the data stored in the database adheres to a consistent set of rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b1f2f1-b60e-4673-98a4-d949c537559f', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How can you pass data between middleware and handlers in Gin?', N'Intern', N'You can use the ''Set'' and ''Get'' methods on the context object to store and retrieve data. This allows middleware to perform tasks like authentication and pass the user''s information down to the final handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd93d63ff-183f-4938-801f-d94bcea8c8fe', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can Sass modules be leveraged to enforce a design system''s constraints?', N'Senior', N'By creating a dedicated module for design tokens like spacing, color palettes, and typography, you can enforce consistency across a team. Using private members within these modules ensures that internal implementation details are hidden, exposing only the approved API for developers to consume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57354155-f4ff-44d2-8bb5-d94ccbf42a51', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL ensure data consistency during a crash if the OS reports a write is finished but the disk hasn''t flushed it?', N'Senior', N'PostgreSQL relies on fsync calls to force the operating system to flush data to physical storage. If the hardware lies about flush completion, data corruption can occur, which is why reliable hardware with battery-backed write caches is recommended for mission-critical databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac7b2afd-3bb8-4f95-bc62-d94e4a2a6fa5', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the Java Garbage Collector?', N'Intern', N'The Garbage Collector is an automatic memory management process in the JVM. It identifies and removes objects that are no longer being used by the application to free up memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81d883fd-39df-4554-9fd7-d9545d98c68c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using a centralized configuration management system versus environment-specific configuration files?', N'Middle', N'Centralized systems provide a single source of truth and dynamic updates without redeployments, but they introduce a central point of failure. Environment-specific files are simple and reliable for local development but become difficult to manage and synchronize as the number of environments and services increases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a8f5605-c95c-4e84-a67e-d9561f3958b8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a partition key?', N'Intern', N'The partition key, also known as the hash key, is the first part of a primary key. DynamoDB uses this value as input to an internal hash function to determine the physical partition where the data is stored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9af7c2a-2eb8-42d3-8315-d9566f76981e', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are AdonisJS ''Hooks'' in the context of Models?', N'Junior', N'Hooks are lifecycle events that trigger code execution before or after a database operation, such as saving or deleting a record. They are useful for tasks like hashing passwords before saving a user or cleaning up related files after deleting a model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86247871-71b2-4f4f-8dc0-d95926ff48b7', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How do actors communicate with each other in Actix?', N'Junior', N'Actors communicate by sending messages through addresses. One actor sends a message to the recipient''s address, and the recipient processes that message within its own mailbox.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
