INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac5c1c05-9ce8-4ff8-a5ac-d95a8ff52098', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Discuss the trade-offs of using FastAPI''s integrated security tools compared to an API Gateway like Kong or Istio.', N'Senior', N'FastAPI''s security utilities are excellent for granular, application-level authorization and handling OAuth2 flows. However, using an API Gateway is preferable for infrastructure-level concerns like global rate limiting, DDoS protection, and unified authentication across a distributed microservices architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d0807eb-1483-489d-a1f2-d95b8cfd11e6', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the benefit of Svelte''s component model regarding bundle size?', N'Senior', N'Since Svelte is a compiler, it only includes the code necessary for the features actually used in the application. Unlike runtime frameworks that ship their entire library architecture, Svelte produces a ''surgically'' crafted bundle, resulting in significantly smaller payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c66159b-e0a8-4394-a843-d95c8486a010', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel''s Eloquent ORM handle the N+1 query problem, and what are the performance implications?', N'Senior', N'The N+1 problem occurs when an application executes a query for a main entity and then triggers individual queries for each related entity within a loop. Laravel mitigates this via Eager Loading using the ''with'' method, which utilizes a single ''WHERE IN'' query to fetch all relations upfront, drastically reducing database round trips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3954b65-8f27-46c9-beb9-d95e277e4ddc', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the role of a consumer group in a distributed messaging system?', N'Senior', N'A consumer group enables load balancing by distributing the set of partitions among multiple consumer instances. This allows for parallel processing of messages and provides automatic fault tolerance, as the broker reassigns partitions when an instance in the group fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d56dc24-7a30-47cc-b3cf-d95f8f5b2baa', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'The difference between block, inline and inline-block element?', N'Fresher', N'a) Block Elements The block elements always start on a new line. They will also take space of an entire row or width. List of block elements are , , , . Example: b) Inline Elements Inline elements don''t start on a new line, they appear on the same line as the content and tags beside them. Some examples of inline elements are , , , and tags. When it comes to margins and padding, browsers treat inline elements differently. You can add space to the left and right on an inline element, but you cannot add height to the top or bottom padding or margin of an inline element. Example: c) Inline-Block Elements Inline-block elements are similar to inline elements, except they can have padding and margins added on all four sides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5507b1b-c455-474f-a91a-d960409833a6', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the purpose of the ''alias_method'' command?', N'Middle', N'It creates a copy of an existing method with a new name, which is useful for wrapping or extending existing functionality through monkey-patching. It allows a developer to maintain the original method''s behavior while adding custom logic before or after it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ace12a5a-5aeb-44e4-be2c-d961eb3ea06e', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the ''M:N'' scheduling model relate to fibers?', N'Middle', N'The M:N model maps M fibers onto N kernel threads. This allows the system to balance the high concurrency of fibers with the parallel processing power of multiple CPU cores, providing an optimal balance between throughput and resource utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff99fa27-0878-4fd5-ac43-d966cccfac05', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What are the architectural implications of moving from a monolithic database to a sharded architecture?', N'Senior', N'Sharding improves write throughput and capacity by distributing data across multiple instances, but it introduces significant operational complexity. It necessitates careful shard key selection to avoid hotspots and complicates cross-shard joins or transactions, which must be handled at the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64637a19-cd16-48d3-9dae-d967cc8dbb57', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Discuss the trade-offs of using Sass logic (loops, conditionals) versus native CSS features like CSS variables and container queries.', N'Senior', N'Sass logic runs at build-time, which is useful for generating repetitive utility classes or theme variants. However, native CSS features like variables and container queries run at runtime, providing much greater flexibility for responsive, dynamic interfaces without the need for recompilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a75bcf9-c873-43a0-847c-d96800369257', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does Rails manage database transactions, and how can you ensure data consistency?', N'Middle', N'Rails provides the ''transaction'' block, which ensures that all database operations within the block succeed or none of them are applied. You ensure consistency by wrapping related operations in these blocks, which roll back changes automatically if an exception is raised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29ab1734-5f32-4b09-96f1-d969c7a8a8bd', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the advantages of using DynamoDB Transactions over standard operations?', N'Senior', N'Transactions ensure ACID compliance across multiple items or tables, guaranteeing that a series of operations either all succeed or all fail. This is crucial for maintaining data integrity in complex operations, though it doubles the throughput consumption and introduces higher latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed3521ef-9094-4a0c-aade-d97145aea1d7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''protected'' access modifier?', N'Junior', N'The ''protected'' access modifier restricts access to the member so that it can only be seen by code within the same class or by classes derived from that class. It is used to hide internal logic from the public API while allowing subclasses to utilize it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d4b0255-805f-4809-bdb3-d972ed53191c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why should you avoid using the ''SELECT *'' statement in production applications?', N'Middle', N'Using ''SELECT *'' retrieves all columns, which increases network traffic and memory usage if only a subset is needed. It also makes the application code fragile to schema changes, such as adding large binary or text columns to a table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'154b60a6-e974-4db0-8af2-d973a9e5add0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine whether a task should be handled by a background job or in the main request-response cycle?', N'Junior', N'If a task is time-consuming, such as sending emails or processing large files, it should be moved to a background job to keep the main request cycle fast. Only tasks that are required for the immediate response should be handled synchronously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a480e1f-906a-4a1d-8ff3-d973ab469785', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When a system is failing under high load, how do you decide between scaling out versus optimizing the code?', N'Middle', N'Scaling out is a short-term fix to maintain availability, while code optimization is a long-term solution to improve efficiency and reduce costs. I would first assess if the system has reached a genuine resource limit or if there is a ''low-hanging fruit'' optimization, like an N+1 query problem, that can be fixed quickly. A balanced approach involves scaling to stabilize the system while simultaneously profiling the code to address the root cause.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'080f1163-5e5a-49d2-8782-d974ee301ef6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle schema migrations in a large-scale system without causing downtime?', N'Senior', N'I adopt an additive-only approach where database changes are decoupled from application logic. This involves a multi-phase rollout: first, applying the schema change that allows both old and new code to function, then updating the application, and finally cleaning up the deprecated schema elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'432c960a-dc22-4839-8623-d975c4d08195', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to use JSON Web Token (JWT) for authentication in Node.js?', N'Fresher', N'JSON Web Token (JWT) is an open standard that defines a compact and self-contained way of securely transmitting information between parties as a JSON object. This information can be verified and trusted because it is digitally signed. There are some advantages of using JWT for authorization: * Purely stateless. No additional server or infra required to store session information. * It can be easily shared among services. Syntax: * Header - Consists of two parts: the type of token (i.e., JWT) and the signing algorithm (i.e., HS512) * Payload - Contains the claims that provide information about a user who has been authenticated along with other information such as token expiration time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71c3c18c-970f-44c5-90e6-d9767a21bb53', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''attribute'' option in a property definition?', N'Intern', N'The attribute option allows you to configure how a property maps to an HTML attribute. You can use it to specify a custom attribute name or to disable attribute reflection entirely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0b1cb06-6767-48d8-b909-d978054a1742', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the main difference between Server Components and Client Components in Next.js?', N'Junior', N'Server Components are rendered exclusively on the server, which helps reduce the amount of JavaScript sent to the client and improves initial page load performance. Client Components are rendered on the client side, allowing you to use interactive features like state, effects, and event listeners that require browser-specific APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc76ecfb-9591-48c0-adff-d97820727144', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does the Facade pattern in Laravel affect testability?', N'Senior', N'Facades provide a static-like interface to classes in the service container, which can make code hard to test if used directly. Laravel solves this by providing ''fake'' methods for facades, allowing you to intercept and assert calls without triggering the actual underlying service, thus maintaining a balance between convenience and testability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55f4738-228e-4bdc-9c72-d97b4de7eabd', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is tail recursion in Scala?', N'Fresher', N'Tail recursion is a form of recursion where the recursive call is the final action performed by the function. Scala can optimize tail-recursive functions by converting them into loops, which prevents stack overflow errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ee7a32-dd75-492c-b1e0-d97bb64225f9', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of keep alive tag?', N'Intern', N'Keep-alive tag is an abstract component used to preserve component state or avoid re-rendering. When you wrapped tag around a dynamic component, it caches the inactive component instances without destroying them. Let''s see the example usage of it, When there are multiple conditional children, it requires that only one child is rendered at a time. Note: Remember that keep-alive tag doesn''t render a DOM element itself, and doesn''t show up in the component parent chain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94646bc0-e1a2-46ff-bcc4-d97f915c6f4d', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''const'' keyword signify when applied to a variable?', N'Junior', N'The const keyword indicates that a variable''s value cannot be modified after its initial assignment. This helps prevent accidental changes to data that should remain constant throughout the program execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ff1f916-1bd2-4ad0-a838-d9845080baf3', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How would you handle a situation where two requirements conflict?', N'Fresher', N'I would document the conflict and discuss it with stakeholders to understand which requirement provides more business value. Often, one requirement can be adjusted or deferred to resolve the conflict without sacrificing quality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca1740ce-7f3e-4e93-ba25-d98721bbb2bf', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How do C++ modules improve upon traditional header-based compilation?', N'Senior', N'Modules replace the textual inclusion of headers with a binary representation of interfaces, significantly reducing compilation times by eliminating redundant parsing of the same header files. They also provide better encapsulation, as symbols can be explicitly exported, preventing leakage of internal implementation details into the global namespace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f713a810-3816-4858-b2e3-d98a741603c2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for evaluating the scalability of a new architectural component?', N'Senior', N'Perform load testing under simulated peak conditions to observe how the system behaves under stress. Identify the breaking point and determine if the component scales linearly or hits a bottleneck due to shared resources or locking mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b9c0efc-8b14-43a7-9bb8-d98b16bc5117', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you handle a scenario where a production issue is reported, but it is not reproducible in the staging environment?', N'Middle', N'I would compare the environmental differences, such as traffic volume, database state, or specific infrastructure configurations like firewall rules and load balancer settings. If those are identical, I would implement enhanced observability, such as request-level logging or custom metrics, to capture the state of the system during the actual failure event.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4464b6a2-7920-46d6-b401-d98b78928194', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Compare Async-Await and Generators usage to achive same functionality?', N'Middle', N'1. Generators/Yield: Generators are objects created by generator functions — functions with an * (asterisk) next to their name. The yield keyword pauses generator function execution and the value of the expression following the yield keyword is returned to the generator''s caller. It can be thought of as a generator-based version of the return keyword. Example: 2. Async/Await: Async keyword is used to define an asynchronous function, which returns a AsyncFunction object. Await keyword is used to pause async function execution until a Promise is fulfilled, that is resolved or rejected, and to resume execution of the async function after fulfillments. When resumed, the value of the await expression is that of the fulfilled Promise. Key points: 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d214bb3-9336-4825-a26e-d98ce65a2fba', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the function of the ''config'' directory?', N'Junior', N'The config directory holds configuration files for various components like database, sessions, and mailers. Storing these settings separately allows for environment-specific configurations without modifying the application code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b6d7fcd-207a-4f07-ac9c-d98d832704b6', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the difference between a Statefull and Stateless firewall in Symfony Security.', N'Middle', N'A stateful firewall uses sessions to persist the user''s authentication across multiple requests, which is typical for web applications. A stateless firewall does not store session state and requires authentication on every request, which is standard for RESTful APIs using tokens.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'780b7700-7b1d-4b3c-aa70-d9918e1fa6d0', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different methods for iterating over an array?', N'Intern', N'There are several methods to iterate over an array in JavaScript. The most common ones include for loops, forEach, map, filter, reduce, and for...of. Each method has its own use case. For example, for loops are versatile and can be used for any kind of iteration, while forEach is specifically for executing a function on each array element. map is used for transforming arrays, filter for filtering elements, reduce for accumulating values, and for...of for iterating over iterable objects. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75529c38-0b43-437d-8e31-d995b340bd93', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the ''Any'' method in Gin''s router?', N'Middle', N'The Any method registers a handler for all standard HTTP methods, including GET, POST, PUT, and DELETE. It is useful for proxying requests or implementing catch-all endpoints that need to handle multiple types of incoming requests identically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27b14870-24f8-4389-b502-d996f6586d3f', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the ''typedef'' keyword?', N'Intern', N'Typedef is used to create an alias for an existing data type. It does not create a new type, but rather provides a more descriptive or convenient name for an existing one, improving code readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41827b0c-5211-47c6-bcb9-d998e1d3b7da', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What architectural role does the virtual DOM play in Preact''s memory management strategy?', N'Senior', N'The virtual DOM serves as a transient state representation that is garbage-collected after every render cycle, keeping the heap clean. By continuously recycling these objects during diffing, Preact prevents the long-term memory accumulation that can occur in frameworks with more persistent internal state tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17ec667a-2df2-482d-af37-d99b27552617', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How to debug an application in Node.js?', N'Fresher', N'1. node-inspector: Run 2. Debugging: * Debugger * Node Inspector * Visual Studio Code * Cloud9 * Brackets 3. Profiling: 4. Heapdumps: * node-heapdump with Chrome Developer Tools 5. Tracing: * Interactive Stack Traces with TraceGL 6. Logging: Libraries that output debugging information * Caterpillar * Tracer * scribbles Libraries that enhance stack trace information * Longjohn', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9671d1d-aabb-4f32-85e1-d99b773bfd9d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you implement security in a system with high compliance requirements?', N'Senior', N'I follow the principles of defense-in-depth and Zero Trust, ensuring every service-to-service call is authenticated and authorized. All data is encrypted at rest and in transit, and I maintain a comprehensive audit log of all access requests to meet regulatory standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d5ddf3e-1279-4426-a3c5-d99cf1fb2748', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do you manage long-running migrations on a production database with high availability requirements?', N'Senior', N'This is typically achieved through ''expand and contract'' patterns, where the database schema is updated in additive steps that are backward-compatible. This allows the application to be deployed in phases, keeping the system online while the migration occurs in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'794d6ef2-68a8-445a-b95e-d99fc3ec4463', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What happens when you define a function prototype?', N'Junior', N'A function prototype informs the compiler about the function''s name, return type, and parameters before the function is actually called. This allows the compiler to check for correct usage and argument types throughout the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ee52edb-d297-478b-89ff-d9a0ecd48e77', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the benefit of using Ecto Changesets for data validation?', N'Middle', N'Changesets provide a robust, functional way to cast, filter, and validate data before it is sent to the database. By decoupling the validation logic from the database schema, they allow for complex state transitions and error handling that are independent of the underlying storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8398e2c2-9d02-4b8e-8eda-d9a218aaaa3e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is an action in Redux?', N'Intern', N'_Actions_ are plain JavaScript objects or payloads of information that send data from your application to your store. They are the only source of information for the store. Actions must have a type property that indicates the type of action being performed. For example, let''s take an action which represents adding a new todo item:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df67430e-4ace-4426-b4c3-d9a283c1e93a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Security''s filter chain architecture provide a defense-in-depth approach?', N'Senior', N'Spring Security wraps the application in a series of security filters that execute before the request reaches the dispatcher servlet. This allows for granular, modular security policies such as CSRF protection, authentication, and authorization to be applied consistently across all endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
