INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e433c70-c1ec-48eb-946f-d9bde7370391', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI handle file uploads, and what should be considered regarding performance?', N'Middle', N'FastAPI uses ''UploadFile'' objects to handle file uploads, which store large files in memory up to a certain threshold before spooling them to disk. For performance, you should ensure you process these files asynchronously or offload them to storage services to prevent blocking the event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c495e92e-041b-4005-a5d9-d9c037703c18', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle streaming responses, and why is this critical for high-latency backend architectures?', N'Senior', N'Hono leverages the underlying ReadableStream API to push data to the client incrementally as it becomes available, rather than buffering the entire response in memory. This is critical for high-latency architectures because it reduces the Time To First Byte (TTFB), allowing the client to begin rendering or processing content while the server continues to generate subsequent parts of the payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f49aaa4-f645-4a45-a377-d9c21eea3802', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How do S3 methods handle generic dispatch?', N'Middle', N'When a generic function is called, R inspects the class attribute of the first argument to determine which specific method to execute. It looks for a function named with the generic name followed by a dot and the class name, allowing for polymorphic behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9beea28-bc5f-45d3-b482-d9c44de09494', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using Quarkus for serverless functions?', N'Fresher', N'The main benefit is the elimination of ''cold starts''. Because Quarkus applications start in milliseconds, they are perfectly suited for serverless environments where functions are frequently scaled down to zero and restarted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3a7e1e0-a5e0-4507-8ce9-d9c46a4ebfbf', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a CommitLog in Cassandra?', N'Intern', N'The CommitLog is a crash-recovery log that records all write operations sent to the database. If a node fails, it uses the CommitLog to replay operations and restore data to its last known state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59ab8c8f-5f64-42c9-aa27-d9c5082510c6', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between a Template-driven form and a Reactive form?', N'Middle', N'Template-driven forms rely on directives in the HTML to manage form state, making them suitable for simple scenarios. Reactive forms are model-driven, providing more control, easier testing, and better scalability for complex validation and dynamic form structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63697feb-17f7-4f43-9d0d-d9c7296e8719', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember handle dependency injection, and why is it useful?', N'Middle', N'Ember uses a container-based dependency injection system to manage the instantiation and lifecycle of objects like services and components. This promotes modularity and testability by allowing developers to easily inject mock dependencies during unit or integration testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4208a48-08c7-4b11-bce1-d9c895873274', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does Escape Analysis assist the JIT compiler in optimizing object allocation?', N'Senior', N'Escape Analysis determines if an object is accessible outside the scope of its method or thread. If an object does not escape, the compiler can perform scalar replacement, effectively breaking the object into individual primitive fields and allocating them on the stack or in registers, thereby avoiding heap allocation and GC pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18dd6b30-c9d9-45df-90c9-d9c8fa8597fb', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle dynamic path parameters?', N'Fresher', N'Hono allows developers to define routes with a colon prefix, such as /user/:id. The router automatically extracts the value provided in that segment and makes it available through the context object for use in the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b75bbf30-b477-4ad1-81c4-d9ca80aa1e9f', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''String'' class in Java?', N'Intern', N'The String class is used to represent sequences of characters. In Java, String objects are immutable, meaning their values cannot be changed once they are created.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04b7b798-5f43-4d11-9507-d9cb520a7021', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between a Bundle and a Component in Symfony?', N'Middle', N'A Component is a standalone library designed to solve a specific problem, such as routing or HTTP handling, with no external dependencies. A Bundle is a plugin for the Symfony framework that provides integration between various components and adds specific functionality to an application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b72c9c19-ec56-4b3f-bab7-d9cd6082a928', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the role of an Idempotency key in API design?', N'Middle', N'An idempotency key is a unique identifier included in requests to ensure that performing the same operation multiple times results in the same outcome as performing it once. This is critical for reliable communication between services to prevent duplicate processing in case of network retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7f2578e-a345-408e-9959-d9d0a2807260', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the best way to Implement Microservices?', N'Senior', N'- Ease of Development: If you need to onboard a large number of developers or have strict timelines, RESTful APIs are often easier to work with. - Performance: gRPC and other RPC approaches are superior to RESTful APIs in terms of speed, making them ideal when performance is paramount. - Type Safety: gRPC, due to its use of Protocol Buffers, ensures better type safety at the cost of being slightly less human-readable when compared to RESTful JSON payloads. - Portability: RESTful APIs, being HTTP-based, are more portable across platforms and languages. On the other hand, gRPC is tailored more towards microservices built with Protobufs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'844bd1c7-6e53-4489-a7eb-d9d27de71e3e', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the trade-offs of using Server-Side Generation (SSG) versus Server-Side Rendering (SSR)?', N'Middle', N'SSG generates HTML files at build time, resulting in extremely fast performance and zero server costs, but it requires a rebuild for any content changes. SSR generates pages on-demand at runtime, which is better for dynamic content that updates frequently but requires a running server to handle requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a285775-a764-41d6-a3ca-d9d3aec553fe', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How are path parameters defined in Axum routes?', N'Fresher', N'Path parameters are defined using a colon prefix in the route string, such as /users/:id. Axum then uses a Path extractor to map these dynamic segments into typed variables in the handler function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0159d65-0756-4644-9c40-d9d4cf5a18cd', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the impact of Astro''s component-level scoping on CSS management?', N'Senior', N'Astro automatically scopes CSS to the component level, preventing style leakage and unintended overrides without requiring external CSS-in-JS libraries. This isolation simplifies maintenance in large teams, as developers can write styles with the confidence that they will not affect other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f55426a-d3ce-4ec0-b71a-d9d4f84c6b1c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a database partition or sharding?', N'Intern', N'Sharding is the process of splitting a large dataset into smaller, more manageable pieces called shards. These shards are distributed across multiple servers to improve database performance and storage capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed5ce66c-e0d4-4608-8c4a-d9d5cee18d5b', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the trade-offs between using OnPush change detection versus the Default strategy in a complex component tree.', N'Senior', N'Default change detection checks every component on every browser event, which can lead to performance bottlenecks in deep trees. OnPush limits checks to when input references change or events originate within the component, significantly reducing CPU overhead but requiring developers to manage object immutability explicitly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
