INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b94ab70b-8ed0-44a0-858d-d9e03d3631a4', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How do you handle schema changes in a sharded database environment?', N'Middle', N'Schema changes in a sharded environment require careful orchestration to ensure all shards are updated consistently. This often involves rolling out changes in stages or using tools that can manage multi-node migrations to avoid downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f9c5c48-ce2d-4332-820b-d9e120cb3143', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React.memo differ from useMemo, and how do they impact memory versus CPU usage?', N'Senior', N'React.memo is a higher-order component that prevents component re-rendering if props are shallowly equal, saving CPU cycles at the cost of memory used to store the previous props. useMemo memoizes the result of a calculation, which is useful for expensive operations but should be used sparingly as the cost of comparison can sometimes exceed the cost of recalculation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9937c210-a2f1-4465-880a-d9e3c2678098', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the IConfiguration interface?', N'Intern', N'The IConfiguration interface provides access to the application''s configuration settings from various sources such as JSON files, environment variables, or command-line arguments. It acts as a unified way to retrieve settings throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
