INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38aec246-f0b3-48af-9d71-d9e808b18b12', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the DynamoDB Accelerator (DAX) and when should it be used?', N'Senior', N'DAX is a managed, write-through cache designed to reduce read latency from milliseconds to microseconds. It is ideal for read-heavy workloads that require high performance and for applications that perform frequent, repeated reads on the same items.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62524486-2a64-4593-8c23-d9ebe6a32dc3', N'4c000000-0000-0000-0000-000000000005', N'How does the CAP theorem influence the choice of a distributed database?', N'Senior', N'The CAP theorem forces a choice between Consistency and Availability during a network partition. In practice, most systems choose AP for high availability and low latency, relying on eventual consistency, while financial systems prioritize CP, accepting downtime if a partition prevents a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b894c1ec-ca18-4f27-acb4-d9ec021ce0a8', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the ''Link'' component used for?', N'Fresher', N'The Link component is a built-in wrapper for HTML anchor tags that enables prefetching and client-side navigation. It allows users to transition between pages without a full browser reload, resulting in a faster and smoother experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cef17ccc-6eb3-4e4a-962b-d9ee40ec94be', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you declare variables in TypeScript?', N'Fresher', N'In TypeScript, variable declarations support different methodologies for declaring variables and their associated types. Variable and Type Declaration Methods 1. var This declaration can lead to variable hoisting and has global scope or function-level scope. 2. let Use let when you want to define variables within a block scope. This is the recommended default choice: 3. const const allows you to declare constants and is especially useful for maintaining data integrity: 4. Function Scope All three methods (var, let, and const) are confined to their immediate function scope: Rules for Variable Declaration and Initialization - Order Matters: In TypeScript, a variable must be declared before being used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75fff809-fdb9-4d5a-90be-d9f1c56439ec', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the concept of ''Tombstones'' and their impact on cluster performance.', N'Senior', N'Tombstones are markers used to record the deletion of data in an immutable storage engine. They can cause performance degradation because they are scanned during reads and only removed during compaction, potentially leading to increased memory pressure and latency if a large number of deletes occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcf6d8c3-1ebc-4fa4-a7a2-d9f1f8fdc8cb', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between horizontal scaling of a database through sharding versus using a read-replica approach?', N'Senior', N'Read replicas are excellent for scaling read-heavy workloads with minimal application changes but offer no help for write contention. Sharding allows for massive write scaling but forces the application to handle data distribution logic and makes cross-shard transactions extremely difficult to implement.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc04cce4-61c2-40aa-bfe4-d9f2d0906b0a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What happens if Webpack encounters an error during the build process?', N'Intern', N'If Webpack encounters a syntax error or a missing module, it will stop the build process and output an error message in the console. This prevents the generation of an incorrect or broken bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f532adad-482b-4c4f-90de-d9f6a9ad1ac0', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle route matching order?', N'Junior', N'Chi matches routes in the order they are defined. The first route pattern that matches the incoming request path will be the one executed, which is important to consider when defining overlapping or broad route patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccd14e1e-a8cf-477e-8809-d9f8b787b433', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Explain the architectural difference between @ControllerAdvice and a standard Filter for global exception handling.', N'Senior', N'A Filter operates at the servlet level, catching exceptions before they reach the DispatcherServlet, which is useful for security or low-level request interception. @ControllerAdvice operates within the Spring MVC framework, allowing for richer integration with Spring''s exception handling hierarchy and the ability to return structured responses like ResponseEntity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd28cd134-00c9-4bbf-9a95-d9fb2753077f', N'075b8862-431c-4678-9767-f55359758a4a', N'How to trigger watchers on initialization?', N'Fresher', N'You can use immediate: true option in order to trigger watchers when the vue instance (or component) is being created. i.e This option will trigger the callback immediately with the current value of the expression.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'192a2efd-247e-43ac-8dcf-d9fdec1df6b3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the role of monitoring tools in debugging?', N'Junior', N'Monitoring tools provide real-time visibility into system performance metrics like CPU usage, memory consumption, and request latency. They help identify trends or spikes that occur right before an error, allowing you to correlate system state with the incident.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f22ac3f0-2597-4975-a708-d9ff0a93e3cc', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do you need to avoid with statement', N'Fresher', N'JavaScript''s with statement was intended to provide a shorthand for writing recurring accesses to objects. So it can help reduce file size by reducing the need to repeat a lengthy object reference without performance penalty. Let''s take an example where it is used to avoid redundancy when accessing an object several times. Using with it turns this into: But this with statement creates performance problems since one cannot predict whether an argument will refer to a real variable or to a property inside the with argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'484c43a3-d6be-4528-a7ec-d9ff6d6c233c', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Describe the benefits of using AdonisJS ''Named Routes''.', N'Senior', N'Named routes decouple the application logic from the underlying URL structure. If a URL path changes, only the route definition needs to be updated, and all links generated via route helpers remain functional, reducing maintenance overhead and preventing broken links throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac07ac1f-c47a-4bac-80c8-d9ffa0992b5f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is Circular dependency (dependency cycle) in Nestjs, and how can they be fixed?', N'Intern', N'A circular dependency occurs when two classes depend on each other. For example, class A needs class B, and class B also needs class A. Circular dependencies can arise in Nest between modules and between providers. Nest enables resolving circular dependencies between providers in two ways. 1.forward referencing: allows Nest to reference classes which aren''t yet defined using the forwardRef() utility function. For example, if CatsService and CommonService depend on each other, both sides of the relationship can use @Inject() and the forwardRef() utility to resolve the circular dependency. Otherwise Nest won''t instantiate them because all of the essential metadata won''t be available.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee1c33d0-b395-40cf-9df9-da014cb61f23', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut manage cross-cutting concerns like security or logging?', N'Senior', N'Micronaut uses interceptors that are applied at compile-time. When a method is annotated, the framework generates a wrapper that executes the cross-cutting logic before or after the method call, maintaining performance parity with standard method invocations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9dcb32de-a2de-48c8-b2dd-da0479b01d5d', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How can you return JSON from a Hono endpoint?', N'Junior', N'Hono provides a dedicated method on the context object to return JSON responses. This method automatically sets the appropriate Content-Type header to application/json and serializes the provided JavaScript object or array into a string.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b01ba9d3-49e5-4e14-bf2e-da070819aafe', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the purpose of the x-data directive?', N'Fresher', N'The x-data directive is used to declare a new Alpine component scope. It initializes a block of HTML with a JavaScript object that contains the data and state variables used by other Alpine directives within that element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7534195-d477-4ec2-bf2b-da07e67c8ffd', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between public, private, and protected visibility modifiers in classes?', N'Junior', N'Public properties or methods are accessible from anywhere. Protected members are accessible only within the class itself and its child classes. Private members are accessible exclusively within the class where they are defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936d488c-8e4b-4a25-8851-da0960dcc9bd', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does ''SSTable Attached Secondary Index'' (SASI) improve upon the standard Secondary Index?', N'Senior', N'SASI allows for more complex queries and range scans by indexing data directly on the SSTable, which is more performant than the traditional index implementation. However, it still requires careful monitoring as it can consume significant heap memory and impact the compaction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
