INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'516daba6-3a5a-48d2-946c-da0c14ea5011', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What does it mean to perform a binary search when debugging a complex issue?', N'Intern', N'A binary search approach involves disabling half of the new components or changes to see if the issue persists. By iteratively narrowing the scope by half, you can efficiently isolate the specific module or configuration causing the problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6823bde3-43e8-4e46-90eb-da0c1d3dd62f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''useFetch'' composable used for?', N'Junior', N'useFetch is the recommended way to fetch data in Nuxt. It handles the data fetching lifecycle, state management, and ensures that data is fetched on the server during the initial render and then hydrated on the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e76f1e89-9a03-4259-a3f2-da0d39a5efa6', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Does Go support inheritance, and if not, how does it achieve polymorphic behavior?', N'Junior', N'Go does not support class-based inheritance. Instead, it uses interfaces to define behavior; a type implements an interface implicitly by providing the necessary method signatures, which allows for polymorphism where different types can be treated uniformly if they satisfy the same interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1093407a-a0fd-4752-add0-da0fd5248b19', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the Dictionary?', N'Intern', N'- Dictionary objects can be created by using curly braces{} or by calling dictionary function. - Dictionary objects are mutable objects. - Dictionary represents key value base. - Each key value pair of Dictionary is known as a item. - Dictionary keys must be immutable. - Dictionary values can be mutable or immutable. - Duplicate keys are not allowed but values can be duplicate. - Insertion order is not preserved. - Heterogeneous keys and heterogeneous values are allowed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07700244-403d-4426-867a-da1019f2b410', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the +layout.svelte file?', N'Intern', N'A +layout.svelte file defines shared UI elements that wrap multiple pages, such as headers, footers, or navigation menus. It allows you to maintain consistent design across different sections of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c76f402-5653-427f-ab69-da12549808c0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If a user reports that a website loads very slowly, what is the first step you would take to diagnose the issue?', N'Fresher', N'The first step is to isolate where the delay occurs by checking the network tab in browser developer tools. This helps determine if the slowness is due to server response time, large asset sizes, or client-side script execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f0a1b91-9992-44ad-afb6-da16ba6d29c3', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the @Autowired annotation?', N'Fresher', N'The @Autowired annotation is used for automatic dependency injection. It tells the Spring container to find a matching bean in the application context and inject it into the annotated field, constructor, or setter method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da2ac1b5-8ab6-4962-ba71-da1a33d8c89f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is meant by ''reactivity'' in the context of Alpine.js?', N'Intern', N'Reactivity refers to the ability of the framework to automatically update the DOM whenever the underlying data changes. When a property defined in x-data is modified, Alpine detects this change and updates any related parts of the interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2516233c-2a26-49ac-b725-da1b7cf7a42d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why might you use a ''hashed'' shard key instead of a ''ranged'' shard key?', N'Middle', N'A hashed shard key provides a uniform distribution of data by randomly hashing the field value, which effectively prevents write hotspots. A ranged shard key is better suited for range-based queries, but it is more susceptible to hotspots if the data is inserted sequentially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ab06986-73c4-42a7-a926-da1d9db9add6', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the difference between a cache-aside and a write-through cache strategy?', N'Middle', N'In cache-aside, the application handles loading data from the database into the cache. In a write-through strategy, the cache is updated synchronously with the database, ensuring that the cache always stays in sync with the primary storage at the cost of higher write latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'653e8f74-8984-4c7a-8088-da1f56ec9257', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the difference between ''createComputed'' and ''createEffect'' in SolidJS?', N'Senior', N'createComputed is a synchronous derivative that updates whenever its dependencies change, often used for data transformation where immediate consistency is required. createEffect is intended for side effects and is scheduled to run after the DOM has been updated, ensuring that the DOM is stable before the effect executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31e55a08-b3eb-4442-99d2-da205d51aa90', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How do you perform unit testing in NestJS?', N'Middle', N'Unit testing is performed using the Test package, which allows for isolating components by mocking their dependencies. By creating a ''TestingModule'', you can replace real service implementations with mocks or stubs to verify the logic of a single controller or provider in isolation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90d499d6-5170-47ce-a4a1-da25babdfc65', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimation shows that a project will miss a hard deadline, what is your strategy for pruning scope?', N'Senior', N'I collaborate with product managers to categorize features into ''must-have'' for the core value proposition versus ''nice-to-have'' enhancements. By focusing on the minimum viable product that satisfies the core business requirement, I can deliver a functional, stable solution on time while deferring secondary features to future iterations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'212190f6-fb71-45f9-9596-da26caa2cccf', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the performance implications of using SvelteKit''s ''prerendering'' feature for large-scale applications?', N'Senior', N'Prerendering generates static HTML at build time, which significantly improves SEO and initial load times by offloading work from the server. However, for applications with millions of dynamic pages, it can lead to massive build times, necessitating a hybrid strategy that combines static generation with on-demand server rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bd67d06-b395-4ab1-bfe9-da26dfb3f3cf', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle reactivity when properties change?', N'Junior', N'Lit uses a reactive property system. When a property marked with the property decorator changes, Lit automatically schedules an update to re-render the component''s template if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
