INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11cd8366-aa78-4413-a1b6-da2cad2bdf1d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar facilitate testing through its dependency injection implementation?', N'Senior', N'Because dependencies are resolved at runtime through a container, they can be easily mocked or overridden during test execution without altering the application code. This allows for isolated unit tests and reliable integration tests by swapping external services with test-doubles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2643d493-2711-4913-97f6-da2dc5b711fc', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What architectural patterns would you use to handle heavy background processing in Laravel without blocking the main worker threads?', N'Senior', N'You should offload heavy tasks to a specialized queue worker cluster, potentially separating high-priority queues from long-running, CPU-intensive background jobs. This prevents queue saturation and ensures that critical path tasks, such as transactional emails or payments, are processed with minimal latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94782263-34a3-4cdc-bcfb-da2e69faf9f6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of callback function as an argument of setState()?', N'Intern', N'The callback function provided as the second argument to setState is executed after the state has been updated and the component has re-rendered. Because setState() is asynchronous, you cannot reliably perform actions that require the updated state immediately after calling setState. The callback ensures your code runs only after the update and re-render are complete. Example When to use the callback? Use the setState callback when you need to perform an action immediately after the DOM has been updated in response to a state change. i.e, The callback is a reliable way to perform actions after a state update and re-render, especially when the timing is critical due to the asynchronous nature of state updates in React.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f978bb3-be61-4257-bd48-da2ed79c9b23', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why is it often recommended to avoid ''hidden classes'' transitions in high-performance JavaScript applications?', N'Senior', N'JavaScript engines optimize property access by creating hidden classes based on object structure. Frequently changing an object''s shape by adding or deleting properties forces the engine to de-optimize the object into a slow dictionary mode, significantly degrading performance in performance-critical loops.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
