INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb7603fb-dc85-474a-983e-da38b4932f56', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can you use Alpine.js with Web Components, and what are the architectural considerations?', N'Senior', N'Yes, Alpine.js can be used within or alongside Web Components to provide reactive internal logic. However, care must be taken regarding shadow DOM boundaries, as Alpine''s scope traversal might be restricted by the shadow root, potentially requiring explicit passing of data or using Alpine''s global store to bridge the gap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7e46a7f-76f5-4a95-abe0-da3a7f488851', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to use a GET or a POST request when designing an API endpoint?', N'Fresher', N'I would use GET for requests that only retrieve data and do not change the server state, as it is idempotent and cacheable. I would use POST when the request involves submitting data to be processed, creating a new resource, or performing an action that modifies the server state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3ad86a9-e2be-4a34-9997-da3b80b8f8c7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does ''Single Source of Truth'' mean in Redux?', N'Intern', N'This principle states that the entire state of your application is stored in an object tree within a single store. Having one central location for state makes it easier to create universal apps and simplifies debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
