INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd6aa026-4aa5-46b4-bf68-da3cb7ea998a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between a variable and a constant in R?', N'Fresher', N'In R, there is no strict concept of a constant. Any value assigned to a name can be reassigned to a different value at any point, meaning all variables are mutable within the current environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d7e071d-9fdb-49f7-9386-da3e99d75853', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite utilize esbuild for performance, and what are its limitations regarding production builds?', N'Senior', N'Vite uses esbuild, written in Go, to transform TypeScript and JSX at 10-100x the speed of JavaScript-based transpilers. However, esbuild does not support type-checking or generating decorator metadata, which is why Vite delegates production-grade bundling and code splitting to Rollup for better plugin compatibility and output optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f250d304-4180-4e5d-9b3f-da3f418c605f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the advantage of using ''State'' over global variables?', N'Junior', N'Using ''State'' is safer and more testable than global variables because it explicitly passes dependencies to the handlers. This makes it easier to inject mock data or different configurations during unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfc8bd14-3314-4054-bc5c-da41a037e12c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the ''String'' data type in Redis?', N'Intern', N'The string is the most basic Redis data type. It can store text, serialized objects, or even binary data, with a maximum size limit of 512 megabytes per key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a21d856-8a13-43a1-8b3d-da41bd48754c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS''s DI container handle circular dependencies, and what is the architectural implication of relying on them?', N'Senior', N'NestJS uses forward references to handle circular dependencies, but their presence typically indicates a violation of the Single Responsibility Principle. Architecturally, they suggest high coupling between modules, which complicates unit testing and often necessitates refactoring into a shared module or a more hierarchical service structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77af91f5-8c49-4b6f-ae35-da4380acd109', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What mechanism does Micronaut use to perform dependency injection without runtime classpath scanning?', N'Senior', N'Micronaut uses a custom annotation processor that analyzes classes during the build phase to generate a ''BeanDefinition'' for each injectable component. These definitions contain all the metadata required to instantiate and wire dependencies, removing the need for runtime scanning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'222b0d77-1f69-436c-8e85-da444b0a5078', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you parse JSON string', N'Fresher', N'When receiving the data from a web server, the data is always in a string format. But you can convert this string value to a javascript object using parse() method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d481135-6e09-4aa6-b050-da4646576042', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you ensure auditability in a highly distributed architecture?', N'Senior', N'Auditability is achieved by centralizing event logs from all services into a tamper-evident, immutable storage system. Every request must be traceable via correlation IDs that span across service boundaries, providing a clear audit trail of who performed what action and when.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a06a7edb-17f2-42d6-b4c0-da486c315a08', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle routing?', N'Junior', N'SvelteKit uses a file-system based router. The structure of your directories within the src/routes folder determines the URL paths of your application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4feb7159-d0de-48bc-b5b0-da48dccac113', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of using a composable router like Chi?', N'Fresher', N'Composability allows developers to break down large routing tables into smaller, modular sub-routers. This makes the code easier to maintain, test, and organize as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'575eb489-741b-4df1-a335-da49a0a60467', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why does Swift prioritize ''Structs'' over ''Classes'' for data modeling?', N'Senior', N'Structs offer better performance due to stack allocation and improved cache locality, as they avoid the overhead of heap allocation and pointer indirection inherent to classes. Furthermore, their copy-by-value nature makes them inherently safer in concurrent programming models, reducing the surface area for side-effect-related bugs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4490642-72c5-49a1-bcc4-da4b8b1945ac', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How do you mount one router inside another in Chi?', N'Junior', N'You can use the Mount method to attach a sub-router to a specific path prefix. This is useful for modularizing an application by splitting routes into different packages or domains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82e16104-e03c-4a87-9b3d-da4d0dd194a9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the function of SvelteKit''s ''hooks.server.js'' and why is it critical for cross-cutting concerns?', N'Senior', N'Hooks act as a middleware layer that intercepts every request to the server, allowing for centralized authentication, authorization, and header manipulation. This architectural pattern prevents code duplication across multiple routes and ensures consistent security policy enforcement globally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a9c1f12-a386-4143-b329-da545c99309d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain event bubbling.', N'Junior', N'Event bubbling is a process where an event triggered on a nested element propagates upward through its parent elements in the DOM hierarchy. This allows parent elements to capture and handle events triggered by their children, which is useful for event delegation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bb5d668-61b2-47b4-b73e-da55be691d6b', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of Rocket''s ''Request Guards''?', N'Middle', N'Request guards are a mechanism for validating and authorizing incoming requests before they reach the handler. They implement the FromRequest trait, allowing for logic like authentication checks or header validation to run automatically, returning a failure if requirements are not met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14d9ba18-ccf0-476b-83fb-da570e32523d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Discuss the maintenance burden of a large-scale jQuery application.', N'Middle', N'Large jQuery applications often suffer from ''spaghetti code'' due to the lack of enforced architectural patterns like components or unidirectional data flow. Without strict structure, global variables and tight coupling between the UI and business logic make testing and scaling extremely difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'180499e6-dde6-4cf5-90bc-da58906fbd9c', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the impact of Go''s slice header structure on performance and safety?', N'Senior', N'A slice header contains a pointer to an underlying array, a length, and a capacity, which provides efficient, constant-time access and slicing operations without copying data. The primary risk is that multiple slices can point to the same underlying array, potentially leading to unintended side effects if the underlying data is mutated across different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a37c850f-50fa-4551-bcca-da5c40c4e2b9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the purpose of the MongoDB shell?', N'Intern', N'The MongoDB shell is an interactive JavaScript interface that allows users to communicate with a MongoDB instance. It is used to perform administrative tasks, query data, and update database content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'718137b0-7edc-4ca2-9f79-da5f8c2e1889', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the function of the ''context'' package in Go?', N'Middle', N'The context package provides a mechanism to carry deadlines, cancellation signals, and request-scoped values across API boundaries and goroutines. It is essential for managing the lifecycle of long-running requests and ensuring that resources are cleaned up if a request is canceled or times out.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc29c0c6-a215-4048-b06a-da62c8399492', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the benefit of using ''Depends'' for database connection management?', N'Middle', N'Using ''Depends'' ensures that a database session is created when a request starts and is closed automatically after the response is sent, even if an error occurs. This prevents connection leaks and ensures that database resources are managed predictably throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16c80f70-4c70-4cc5-88f6-da62cb55caa1', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''Transition'' API used for in SolidJS?', N'Middle', N'The Transition API allows you to mark specific state updates as non-urgent. This lets the framework keep the UI responsive while performing background updates, showing a loading state or keeping the old content until the new data is ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42ffdd0e-6aca-4e5c-81a5-da6390170279', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'Why might you see a high number of ''page faults'' in a MongoDB monitoring tool?', N'Middle', N'High page faults indicate that the database is frequently requesting data that is not currently in the RAM cache, forcing it to fetch data from disk. This typically points to an undersized working set or missing indexes, significantly slowing down performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21df4e63-e265-47ba-91f2-da65adcfd6be', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is ACID compliance in the context of PostgreSQL?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability, which are properties that guarantee reliable database transactions. PostgreSQL ensures that transactions are processed reliably, meaning they either complete entirely or not at all, maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c134511f-a174-489d-a49e-da68dcd3e278', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Describe the ''Sidecar'' pattern and its utility in microservices.', N'Senior', N'A sidecar is a secondary container deployed alongside the application container that handles peripheral tasks like log shipping, proxying, or telemetry collection. This keeps the primary application container lightweight and focused on core business logic while providing a standard interface for platform-level requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cc09bd2-4073-4b84-b868-da6ca073f731', N'954a0331-deff-4399-b588-96f39fec001d', N'What are host bindings and host listeners?', N'Intern', N'Host bindings and host listeners are decorators used in Angular directives and components to interact directly with the host element, which is the element the directive or component is applied to. - @HostBinding allows you to bind a property of the host element (like class, style, id, src, etc.) to a property of your directive or component class. This is useful for dynamically changing the host element''s appearance or attributes based on the component/directive''s state. - @HostListener allows you to subscribe to events emitted by the host element (like click, mouseover, keydown, etc.) and execute a method in your directive or component class when that event occurs. This is useful for reacting to user interactions directly on the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88bf17f2-351f-432c-9afe-da6d075f25f8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the role of Dependency Injection in FastAPI and why it is preferred over global variables.', N'Middle', N'Dependency Injection allows for the modular management of shared resources like database sessions or authentication logic. It makes components decoupled and testable by allowing you to override dependencies during unit tests without modifying the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
