INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1154af9-ed07-42fe-9781-da6f74acea0f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the ''Strong Parameters'' pattern in Rails security?', N'Middle', N'Strong Parameters prevent mass assignment vulnerabilities by requiring developers to explicitly whitelist which attributes can be updated via web requests. It ensures that sensitive database columns cannot be modified by malicious users simply by injecting extra parameters into the request payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fb62256-2649-4af0-9890-da7280ad4edd', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a data binding?', N'Intern', N'Data binding is a core concept in Angular and allows to define communication between a component and the DOM, making it very easy to define interactive applications without worrying about pushing and pulling data. There are four forms of data binding(divided as 3 categories) which differ in the way the data is flowing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adfcfe67-a3d9-42ce-8f99-da74ac390730', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does cache partitioning (sharding) impact system scalability and hot-key management?', N'Senior', N'Sharding distributes the cache load across multiple nodes, increasing memory capacity and throughput. However, if a specific key becomes a ''hot-key'', a single shard may become a bottleneck; this is often solved by replicating hot keys across all shards or using a dedicated local memory cache on the application nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69c6ec48-9ae2-4c9e-be90-da7593f4d65a', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you use ''worst-case'' and ''best-case'' scenarios in your estimation process?', N'Middle', N'I use these scenarios to establish a confidence interval for the project. This helps stakeholders understand the range of potential outcomes and allows us to create contingency plans for higher-risk items, rather than relying on a single, often overly optimistic, date.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b3c4f1f-3e08-4f77-9495-da7b629797b2', N'075b8862-431c-4678-9767-f55359758a4a', N'Explain the difference between ''computed'' properties and ''watchers'' in terms of execution context.', N'Senior', N'Computed properties are lazy, cached, and intended to derive new data from existing state, recalculating only when dependencies change. Watchers are eager, side-effect-heavy, and meant to perform asynchronous or expensive operations in response to specific state changes, lacking the caching and dependency-tracking benefits of computed properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'101f570b-f4c8-4460-91e7-da7c287eddd9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web achieve high performance in handling HTTP requests?', N'Middle', N'Actix-web leverages the low-level, high-performance ''h2'' and ''http'' crates alongside the Tokio event loop. It minimizes allocations and uses a highly optimized request routing mechanism to achieve extremely low latency and high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a69805f5-033a-4fdd-b45a-da7dd5a7cce0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to build a feature internally or buy/use an existing third-party service?', N'Intern', N'You should evaluate whether the feature is a core differentiator for your product. If it is a commodity task like authentication or payment processing, using a specialized third-party service is usually more efficient, whereas building it internally is better for unique, high-value business requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'031189d7-13ce-46ca-902c-da80ca9fb2af', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the role of the ''load path'' ($LOAD_PATH) in Ruby.', N'Middle', N'The $LOAD_PATH is an array of directories that Ruby searches when looking for files to require. Modifying this array allows developers to add custom locations for library files that are not in the standard Ruby installation path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42bc35aa-8bda-47e6-b157-da81ce8e071d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle the ''Diamond Problem'' through interface delegation?', N'Senior', N'Kotlin resolves the diamond problem of multiple inheritance by enforcing explicit implementation overrides when a class inherits from multiple interfaces with conflicting method signatures. Furthermore, interface delegation allows a class to forward method calls to a specific instance of an interface, providing a clean compositional alternative to complex class hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69844ece-741b-4189-b3b2-da83db235a58', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you handle complex component styling with Tailwind without creating unreadable HTML?', N'Middle', N'For complex components, developers should utilize component composition by breaking UI into smaller, reusable UI components within their framework of choice. This keeps the markup clean while delegating style management to the individual component''s defined utility set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93aaecf1-5b76-4177-80ad-da8401cebec6', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask''s routing system determine the correct endpoint, and what is the overhead of complex routing logic?', N'Senior', N'Flask uses a Werkzeug-based Rule system that evaluates regex patterns for each request, which can introduce latency if the routing table is extremely large. For high-performance requirements, keeping the routing table lean or utilizing an external router at the gateway level is preferred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7bf920e-5301-419d-a4cb-da8536bc8500', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Kestrel''s role in relation to Reverse Proxy servers?', N'Fresher', N'While Kestrel can run on its own, it is recommended to use a production-grade reverse proxy like Nginx or IIS in front of it. The reverse proxy handles tasks like load balancing, SSL termination, and static file caching, leaving Kestrel to focus on executing application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3ace4b4-ff4f-422d-96cf-da8720aaa4f2', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the significance of the ''rel=preconnect'' and ''rel=dns-prefetch'' hints.', N'Senior', N'Dns-prefetch resolves domain names to IP addresses early, while preconnect goes further by establishing the TCP handshake and TLS negotiation. These are crucial for reducing latency when fetching third-party resources, though they should be used sparingly to avoid consuming too many socket connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'818bd91e-5da6-4b8f-87b5-da8923679c06', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the architectural significance of Remix being a ''document-request'' driven framework?', N'Senior', N'By prioritizing the document request, Remix treats the browser as the primary platform rather than abstracting it away. This ensures that the application remains functional without JavaScript, as every navigation is a standard HTTP request that Remix progressively enhances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34f548d3-e464-466c-9ecb-da89d33ce30a', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle query parameters?', N'Intern', N'Gin allows developers to retrieve query parameters from the URL using the Query method on the context object. If a parameter is missing, Gin can return a default value or an empty string depending on the method used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f10017aa-e053-4e7a-a2cb-da8a3653207a', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s approach to ''Streaming'' responses benefit long-running requests?', N'Senior', N'Hono supports native streaming of responses, allowing the server to send parts of a payload as they become available. This reduces the Time to First Byte and prevents the server from buffering large responses in memory, which is essential for memory-constrained edge environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16651cad-4c2f-4cea-9143-da8c092a6636', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the recommendation for provider scope?', N'Intern', N'You should always provide your service in the root injector unless there is a case where you want the service to be available only if you import a particular @NgModule.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'676d43b5-f0e8-4ded-94f8-da904db060eb', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the performance implications of using scan versus query operations?', N'Senior', N'A query operation is highly efficient as it target specific partitions using keys, resulting in O(1) or O(log n) lookups. A scan operation iterates over the entire table or index, consuming massive throughput and increasing latency as the dataset grows. Scans should be avoided in production environments except for infrequent, non-time-sensitive analytical tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3abe6725-337e-4558-bf0e-da91f08c13db', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is Fastify?', N'Intern', N'Fastify is a high-performance web framework for Node.js. It is designed to be extremely fast and low-overhead, focusing on developer experience and plugin architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ffcc4fe-c892-4600-ad91-da97f14dec62', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is horizontal scaling, and why is it often associated with NoSQL databases?', N'Intern', N'Horizontal scaling, or scaling out, involves adding more servers or nodes to a distributed system to handle increased traffic or data storage requirements. NoSQL databases are typically designed to support this architecture natively, allowing them to distribute data across multiple commodity servers rather than relying on a single powerful machine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae624c62-978f-4d6d-9ce4-da9a6439f21e', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI compare to traditional frameworks regarding request context?', N'Senior', N'Unlike frameworks that use thread-local storage for request context, FastAPI relies on explicit dependency injection. This approach is safer for asynchronous programming, as it avoids the pitfalls of shared global state in concurrent environments, making the code more predictable and easier to debug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2181cc-6f83-49ef-8492-da9a7e8aa92a', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the virtual DOM, and why does Vue use it?', N'Junior', N'The virtual DOM is a lightweight JavaScript representation of the actual DOM. Vue uses it to calculate the minimal number of changes required to update the real DOM, which significantly improves performance by reducing expensive browser reflows and repaints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b64f89ed-02de-48d5-aff9-da9c3f734bda', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''keyof'' operator?', N'Junior', N'The ''keyof'' operator takes an object type and produces a union of its keys. It is highly useful in generic programming to ensure that a function only accepts property names that actually exist on a given object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd076b9f5-836e-4134-b9dd-da9e446b7669', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the function of the Flask ''g'' object?', N'Fresher', N'The ''g'' object is a special global variable that stores data during the lifecycle of a single request. It is commonly used to share information across different functions or modules while processing one specific user request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'653062af-581e-45ad-9299-daa1f3dba378', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the function of the ''runtime.Gosched'' call?', N'Senior', N'Gosched yields the processor, allowing other goroutines to run. It is useful in tight loops to prevent a single goroutine from starving others, although the scheduler typically handles this automatically via preemption signals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72b7957a-a146-48c0-9a0e-daa62af16f52', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does rate limiting contribute to system stability and scalability?', N'Middle', N'Rate limiting restricts the number of requests a user or service can make within a specific timeframe. This protects the system from being overwhelmed by malicious traffic or runaway processes, ensuring that resources remain available for legitimate users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9853b8ed-dae7-4826-b3f9-daa69ba83d68', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the x-bind directive used for?', N'Fresher', N'The x-bind directive is used to dynamically set HTML attributes on an element based on the value of a JavaScript expression. You can use it for attributes like class, style, href, or disabled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24ce4b6d-e02a-49e1-8f52-daacdcb61813', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro manage global state?', N'Middle', N'Astro does not have a built-in global state manager like Redux, as it is primarily a page-based framework. For cross-component state, developers typically use browser-native solutions like Nano Stores, which are lightweight and highly compatible with Astro''s islands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e12bbac-be04-4597-9e7c-daaf5543c8b3', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the role of feature flags in debugging production issues?', N'Middle', N'Feature flags allow for the rapid isolation of a problematic component by enabling or disabling specific code paths without requiring a full redeployment. This provides a safe way to verify if a new feature is the source of the performance degradation or bug by toggling it off in real-time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89c9a1f3-6f74-467d-847d-daaf72abd762', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you access query parameters in Axum?', N'Junior', N'You use the Query extractor in your handler function. By defining a struct with Serde attributes, Axum will automatically parse the query string and populate your struct fields.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4049f5e-0825-4e4f-86cc-dab5f5407325', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle request lifecycle management?', N'Junior', N'AdonisJS uses a middleware-based system to process incoming requests. Each request passes through a defined stack of middleware where tasks like authentication, validation, and logging are performed before reaching the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4561c31-4083-42b9-b693-dab7228fd5f7', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do overflow-x and overflow-y work independently?', N'Fresher', N'overflow-x controls horizontal overflow; overflow-y controls vertical overflow. They can be set to different values to get precise control over each axis. Example: Important constraints: * If one axis is set to visible and the other is set to hidden, scroll, or auto, the visible value is automatically treated as auto by the browser. * Setting overflow-x: hidden does not prevent absolutely positioned children from overflowing — use overflow: hidden on a positioned ancestor for that.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88524556-0321-4a89-ba4c-dab7531c6bb2', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do <iframe> on a page communicate?', N'Fresher', N'elements on a page can communicate using the postMessage API. This allows for secure cross-origin communication between the parent page and the iframe. The postMessage method sends a message, and the message event listener receives it. Here''s a simple example: ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a7218c4-643c-4dfc-8aa4-dab7f96f2a02', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the difference between useState and useRef hook?', N'Fresher', N'1. useState causes components to re-render after state updates whereas useRef doesn’t cause a component to re-render when the value or state changes. Essentially, useRef is like a “box” that can hold a mutable value in its (.current) property. 2. useState allows us to update the state inside components. While useRef allows referencing DOM elements and tracking values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bbfec8f-a8b5-42df-892f-dabc513fba4d', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What does ''Imperative'' vs ''Reactive'' mean in Quarkus?', N'Fresher', N'Imperative programming follows a traditional style where each thread handles one request at a time. Reactive programming is a style that uses non-blocking event loops, allowing a single thread to handle multiple concurrent tasks, which improves scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c263f174-dbf3-41b1-8e38-dabd33b14210', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the MySQL InnoDB storage engine handle the ''gap locking'' phenomenon, and what are the primary trade-offs regarding concurrency and phantom reads?', N'Senior', N'Gap locking prevents other transactions from inserting rows into the gap between index records, which is essential for maintaining the isolation guarantees of the Repeatable Read level by preventing phantom reads. While this mechanism ensures data consistency, it significantly reduces concurrency in write-heavy environments, as multiple transactions may be blocked from inserting into the same index range. Designers must weigh the necessity of strict isolation against the potential for increased deadlock frequency and reduced throughput in high-contention systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27e04fc1-0b5c-4195-9843-dac10ee6aab5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to use a local file system or an object storage service for user uploads?', N'Junior', N'I choose object storage for scalability and accessibility, as it allows files to be served globally and offloads storage management from the application server. Local file storage is only suitable for small, temporary files or internal testing environments where simplicity is the primary goal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65a3d21c-ff99-4bb8-988a-dac2128a69c0', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is x-model used for?', N'Junior', N'The x-model directive is used to implement two-way data binding between an HTML input element and the component''s data. When the user types into the input, the underlying data property updates, and conversely, if the data changes, the input reflects that new value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d0ac1bb-827c-401a-b3b4-dac33c6ff595', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are global variables and why are they discouraged?', N'Junior', N'Global variables are accessible from anywhere in the program and are denoted by a ''$'' prefix. They are generally discouraged because they make code difficult to debug, test, and maintain due to their unpredictable state changes across the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
