INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'517fc3d0-caa1-4773-af92-dac537e83518', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the trade-off between synchronous and asynchronous replication in terms of RPO and RTO.', N'Senior', N'Synchronous replication guarantees zero data loss (RPO=0) but increases write latency and risks availability if the replica is slow. Asynchronous replication offers higher performance and availability but risks data loss during a failover because the replica may be behind the primary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
