INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b54478aa-b1cf-45e3-9a9c-dad40b96865f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the architectural implications of using an In-Memory cache versus a Distributed cache like Redis in ASP.NET Core?', N'Senior', N'In-Memory cache is extremely fast but is limited to the local process, meaning it is not suitable for horizontal scaling where state must be shared across server instances. A distributed cache like Redis provides a unified state, allowing for consistent data access across multiple nodes, though it introduces network latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
