INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e2a9ea3-7730-42e8-b0d9-dad837a93af9', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a ''hot partition'' in DynamoDB and how can it be avoided?', N'Middle', N'A hot partition occurs when a single partition receives a disproportionately high amount of traffic compared to others, leading to throttling. It is best avoided by choosing a high-cardinality partition key that distributes data and request volume evenly across all partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
