INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71269f76-29b2-4286-95df-dade9de45438', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi’s design facilitate the implementation of custom Request ID middleware across microservices?', N'Senior', N'Because Chi adheres to standard HTTP interfaces, middleware can easily inject or extract request headers like X-Request-ID and store them in the request context. This allows for seamless distributed tracing and log aggregation across microservice boundaries without tight coupling to the framework internals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c4b5670-f9f7-45ca-97fd-dadec8f6a1cd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the role of ''Type Coercion'' in JavaScript and why is it often criticized?', N'Senior', N'Type coercion automatically converts values between types during operations, such as equality checks or arithmetic. While it provides flexibility, its unpredictable behavior with falsy values and object prototypes often leads to subtle bugs, necessitating the use of strict equality operators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6e683bc-b506-41bb-b3d8-dae37dfae4f2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach a situation where a third-party API integration starts failing sporadically?', N'Middle', N'I would first check the status page of the third-party service and review the error codes returned in my logs to see if they match known service issues. If the issue is on my end, I would investigate connection pooling issues, timeout configurations, or rate-limiting responses. Implementing circuit breakers or retries with exponential backoff is a standard strategy to make the integration more resilient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f3edb56c-8ce0-4814-a29e-dae3f769dcfa', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Describe the browser''s strategy for handling CSS selector specificity and why deep nesting is considered an anti-pattern.', N'Senior', N'Browsers match selectors from right to left, starting with the key selector to discard irrelevant nodes quickly. Deep nesting increases specificity, which makes overrides difficult, and forces the engine to traverse longer paths, potentially slowing down style recalculation when the DOM is large.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'255951cc-c385-46a1-b1e7-dae61abb795d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the difference between client-side and server-side logic in SvelteKit?', N'Intern', N'Client-side logic runs in the user''s browser to handle interactivity, while server-side logic runs on the server to handle database connections or sensitive operations. SvelteKit provides a clear structure to separate these concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bedb264b-8deb-433f-bb35-daecccc8bc23', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is horizontal scaling in the context of Elasticsearch?', N'Intern', N'Horizontal scaling involves adding more nodes to an existing cluster to increase processing power and storage capacity. Elasticsearch handles this by redistributing shards across the new and existing nodes automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d063fb3-d535-48fa-aae7-daf1066a5000', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between append() vs appendChild()?', N'Fresher', N'* ParentNode.append() allows you to also append DOMString object, whereas Node.appendChild() only accepts Node objects. * ParentNode.append() has no return value, whereas Node.appendChild() returns the appended Node object. * ParentNode.append() can append several nodes and strings, whereas Node.appendChild() can only append one node. The main difference is that appendChild() is a DOM function meanwhile append() is a JavaScript function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d681b48-8d50-44a4-9cf6-daf1ed28b198', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle HTTP requests and responses?', N'Fresher', N'AdonisJS uses the ''HttpContext'' object, which encapsulates both the incoming request and the outgoing response. This object is passed to controllers and middleware, providing methods to access input data, headers, cookies, and to send back formatted responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
