INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c3d5ff1-5bbf-418c-92c7-daf9312f2d0a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why are NoSQL databases often preferred for unstructured or semi-structured data?', N'Middle', N'NoSQL databases use flexible schemas, such as JSON or BSON, allowing them to store diverse data types without requiring a rigid, predefined structure. This flexibility is essential for agile development where data requirements change frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ded7a84-d7a4-485a-a606-dafb56517421', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala support both Object-Oriented and Functional programming?', N'Fresher', N'Scala is a hybrid language where every value is an object, supporting object-oriented concepts like classes and inheritance. Simultaneously, it treats functions as first-class citizens, allowing for functional programming patterns like immutability and higher-order functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3dde187-822a-4125-a670-dafc95320545', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the performance implications of using ''def'' versus ''async def'' in FastAPI route handlers.', N'Senior', N'Using ''async def'' allows the event loop to switch tasks during I/O-bound operations, preventing blocking. Conversely, ''def'' functions are executed in an external threadpool to avoid blocking the main event loop, which is useful for CPU-bound tasks or synchronous database drivers that lack native asynchronous support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
