INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'783e0f73-8106-4c62-9fa5-db11064a28aa', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the choice of hashing algorithm affect the performance of distributed hash tables?', N'Senior', N'The choice of algorithm determines the distribution uniformity and the computational overhead of key placement in a distributed system. Consistent hashing is typically preferred because it minimizes the number of keys remapped when nodes are added or removed, reducing network churn and maintaining stable routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
