INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49c1c80b-59a3-4164-8442-db17323942a3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a node in the context of an Elasticsearch cluster?', N'Junior', N'A node is a single running instance of Elasticsearch. Multiple nodes can join together to form a cluster, sharing the data and workload across the infrastructure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bda31ea-d047-4136-bc1e-db1836e85b4d', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you handle error boundaries in Vue?', N'Middle', N'Vue uses the ''errorCaptured'' lifecycle hook to catch errors bubbling up from descendant components. This allows the parent to display an error UI or log the issue without crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ffe9f00-2482-49d7-9187-db19404ac884', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle bean scoping and why is it important for performance?', N'Middle', N'Micronaut supports standard scopes like Singleton, Request, and Prototype, but defaults to Singleton for most beans to minimize object allocation. By resolving dependencies at compile time and avoiding dynamic proxies, Micronaut ensures that the bean lifecycle management adds negligible overhead to the application''s execution path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dee14722-b112-45ae-bbce-db1c2a5eac1b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the Commit Log in Cassandra?', N'Intern', N'The commit log is a crash-recovery mechanism that records all data mutations. Before data is written to memory, it is appended to the commit log to ensure that data can be recovered in the event of a system failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c3bb571-f467-4282-aa5e-db1dfb9a6ac4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between ''=='', ''eql?'', and ''equal?''?', N'Intern', N'The ''=='' operator checks for value equality, ''eql?'' is often used for hash keys to check both type and value equality, and ''equal?'' checks for object identity, verifying if both references point to the exact same object in memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a600a31e-dff3-4e9a-bd4c-db214fda5e61', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What are the trade-offs of using native executables versus standard JVM mode in Quarkus?', N'Middle', N'Native executables offer near-instant startup and lower memory usage but take much longer to build and do not support dynamic class loading. JVM mode supports the full range of Java features and faster build times but requires more memory and has a longer startup latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
