INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d7cc1ee-5daf-45f0-bfd8-db30ac0fb8a7', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do you ensure data integrity when dealing with concurrent requests?', N'Middle', N'Data integrity under concurrency is managed using database transactions and locking mechanisms like pessimistic or optimistic locking. These prevent race conditions where two processes attempt to read and update the same data simultaneously, leading to inconsistent states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cc1cd1d-9ea5-4ae4-9b85-db31fc7c9970', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono handle routing performance in scenarios with thousands of defined endpoints?', N'Senior', N'Hono employs a radix tree-based routing algorithm, which provides O(k) lookup complexity where k is the length of the path. This structure is significantly more efficient than linear array scanning, allowing the framework to scale to large API surfaces without degrading request-matching latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dd37cef-13b3-4e41-98dd-db33072b2153', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why should you avoid storing large blobs of text or binary data directly in a primary database table?', N'Junior', N'Storing large files or binary data directly in a database can significantly increase the size of the table, leading to slower query performance and higher backup costs. It is generally better to store these files in object storage and keep only the reference URL in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
