INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8961cb60-b998-4a8e-821f-db44702db85f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle feedback during a peer code review?', N'Junior', N'I view feedback as an opportunity to learn and improve my skills rather than a critique of my ability. I carefully review each comment to understand the rationale behind the suggestions and ask questions if I need clarification. I then apply the feedback and acknowledge the reviewer, maintaining a professional and collaborative attitude.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1a88f8c-3cdf-4ecf-ab93-db47fba6ca51', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch achieve high availability in a distributed cluster?', N'Middle', N'Elasticsearch achieves high availability by distributing shards across multiple nodes and maintaining replica shards for each primary shard. If a node fails, the cluster promotes a replica to primary status and automatically rebalances to maintain the desired replication factor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d732177-b759-4176-88df-db49638115c7', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the purpose of the ''Extractors'' pattern in Axum.', N'Middle', N'Extractors are a mechanism to pull data from an incoming HTTP request and map it to function arguments. They promote clean architecture by decoupling business logic from the boilerplate of parsing headers, query parameters, or request bodies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e21f5bf-1bb2-46bb-96cd-db4a2e2e72b6', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'In what scenarios would you choose a ''Custom Server'' over Nitro''s default capabilities?', N'Senior', N'A custom server is necessary only when you need to integrate deeply with existing Node.js middleware ecosystems, such as legacy Express or Koa applications, or when specific low-level socket management is required. In most modern cases, Nitro''s extensibility via server plugins and API routes is sufficient for complex requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12666ff8-17ee-44ad-a732-db4bb468d6c1', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the benefits of using DynamoDB Streams?', N'Middle', N'DynamoDB Streams capture a time-ordered sequence of item-level modifications in a table, such as inserts, updates, and deletes. They enable event-driven architectures, allowing you to trigger secondary processes like data synchronization, notifications, or archiving to S3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'748f3b92-40c2-46f8-903c-db4c870ec00d', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the primary benefit of using Redis for session storage in web applications?', N'Junior', N'Using Redis for session storage allows for extremely fast retrieval of user session data, improving overall web performance. Because Redis is separate from the application server, it also allows for easy scaling and session persistence across multiple app instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdcd1b6e-2939-43a7-a860-db4cf5c9eedc', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Explain the concept of Redis persistence and its two main modes.', N'Middle', N'Redis persistence allows data to survive restarts by saving in-memory data to disk. RDB creates point-in-time snapshots of your dataset at specified intervals, which is efficient for backups, while AOF logs every write operation received by the server, providing better durability by replaying the log upon restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'691789f1-e63e-45a2-80fa-db4fe78a965b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do PHP''s internal HashTables handle collisions and maintain performance?', N'Senior', N'PHP HashTables use a technique called separate chaining, where each bucket points to a linked list of elements with the same hash. Modern PHP versions have optimized this structure to be more cache-friendly and to prevent hash-flooding attacks by using a randomized hash seed for each process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6c856c3-3331-4e46-80d4-db50fbb18520', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How does Nuxt''s built-in image optimization module affect server performance?', N'Senior', N'Nuxt''s image processing, often powered by Nitro, shifts the heavy lifting of resizing and format conversion from the browser to the build or server stage. While this improves performance for the end-user, it requires careful resource planning on the server to handle potential CPU spikes during heavy image processing tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'367609f6-4481-46a8-8a1f-db51f835691f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If your application experiences a sudden spike in traffic that exceeds database connection limits, how would you approach scaling?', N'Middle', N'I would first implement a connection pool to manage existing connections efficiently and introduce a message queue to decouple traffic spikes from direct database writes. If the bottleneck persists, I would consider read replicas to distribute query load or horizontal sharding to partition the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d594f99-7671-45c5-964e-db555dc63a76', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the implication of using ''Projection Expressions'' in queries?', N'Senior', N'Projection expressions allow you to retrieve only the required attributes from an item, which reduces network bandwidth and the amount of data processed. This optimization helps keep read operations efficient and minimizes costs associated with RCU consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95f047a6-ca05-4b7e-b298-db564da89195', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is the initial component execution different in SolidJS compared to other frameworks?', N'Fresher', N'In SolidJS, the component function is only executed once during initialization to set up the reactive structure. In many other frameworks, the component function is re-executed every time the state changes to calculate new UI snapshots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cb76ce0-d30b-44df-9752-db56c241e076', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind assist in maintaining design system tokens at scale?', N'Senior', N'The configuration file acts as a centralized schema for design tokens like spacing, colors, and typography. This ensures that every developer uses the same constraints, preventing the ''drift'' that often occurs when tokens are hardcoded as arbitrary CSS values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ea9abf2-cdbb-4003-9bb0-db5d16c40e50', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the purpose of the ''it'' keyword in lambdas?', N'Junior', N'The ''it'' keyword is an implicit name given to a single parameter passed into a lambda expression. If a lambda has only one parameter, Kotlin allows you to omit the explicit parameter declaration and use ''it'' by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b70f29f1-b4d9-42d4-b2c3-db5d573cb117', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are some tools that can be used to measure and analyze JavaScript performance?', N'Intern', N'To measure and analyze JavaScript performance, you can use tools like Chrome DevTools, Lighthouse, WebPageTest, and JSPerf. Chrome DevTools provides a Performance panel for profiling, Lighthouse offers audits for performance metrics, WebPageTest allows for detailed performance testing, and JSPerf helps in comparing the performance of different JavaScript snippets. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e35c0aee-aa26-460d-87e2-db62330ddf44', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you handle a stakeholder who demands a precise estimate for an inherently unpredictable task?', N'Intern', N'I would explain the nature of the uncertainty and the risks associated with providing a false sense of precision. I would offer to provide a range based on current knowledge and commit to providing frequent updates as we learn more, shifting the focus from a single fixed number to a dynamic management process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90da9455-2273-42d2-82f4-db62f863934d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the GridFS feature?', N'Intern', N'GridFS is a specification for storing and retrieving files that exceed the 16 MB BSON document size limit. It divides large files into smaller chunks and stores them in separate collections within the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'234cfa8b-4ed4-42d5-97ce-db64afc5fe85', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is an API endpoint?', N'Intern', N'An API endpoint is a specific URL path where an API can be accessed by a client. Each endpoint represents a specific resource or action that the server can perform, such as fetching user data or creating a new record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
