INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abd5686e-ae67-4ac3-82e6-db674ccde58e', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What does it mean for Litestar to be ''opinionated'' regarding type hints?', N'Intern', N'Being opinionated means Litestar expects developers to use Python type annotations for all request and response data. By enforcing this standard, the framework provides better automated documentation and validation features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58afaf15-6a1f-4067-8981-db678ee603eb', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is ''any'' in TypeScript?', N'Intern', N'The ''any'' type is a top type that essentially opts out of type checking for a specific variable. It allows a value to be of any type, which can be useful for migrating legacy code but should be avoided because it bypasses the safety benefits of TypeScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1e3ce75-659e-4d25-8afb-db68ceeb9c58', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Explain the ''Circuit Breaker'' pattern. Why is it important in a microservices ecosystem?', N'Senior', N'The Circuit Breaker pattern is a key mechanism in microservices architecture that aims to enhance fault tolerance and resilience. Core Mechanism - State Management: The circuit breaker can be in one of three states: Closed (normal operation), Open (indicating a failure to communicate with the service), and Half-Open (an intermittent state to test if the service is again available). - State Transition: The circuit breaker can transition between states based on predefined triggers like the number of consecutive failures or timeouts. Benefits 1. Failure Isolation: Preventing cascading failures ensures that malfunctioning services do not drag down the entire application. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef56336b-3944-4661-b492-db6ae7041b7f', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What does the ''never'' type represent?', N'Junior', N'The ''never'' type represents values that will never occur. It is often used as the return type for functions that always throw an error or contain an infinite loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61682120-bab2-4dfc-ba53-db7425fe37a3', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How can you optimize Laravel application performance in a containerized, auto-scaling environment?', N'Senior', N'Optimization involves caching configuration, routes, and views during the build process, along with using an efficient opcode cache like OPcache. Additionally, separating the application code from persistent storage and using shared cache drivers like Redis is essential for horizontal scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
