INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36de9ef8-5b2e-497c-9b0d-db77ea36f3e9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How can one implement rate limiting in Fiber without introducing significant latency?', N'Senior', N'Rate limiting should be implemented as a middleware that interacts with an in-memory store like Redis. By using a distributed cache, the rate limiter can remain performant and accurate across multiple horizontally scaled instances of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
