INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'969f5564-ce96-4d9d-bcdb-db7b0a279b37', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the benefit of the ''Request Delegate'' in the middleware pipeline?', N'Fresher', N'A request delegate is a function that handles an HTTP request. By chaining these delegates together, ASP.NET Core creates a pipeline that allows developers to modularize request processing, making the application easier to maintain and extend.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7e3863e-c5b1-46e6-8b21-db7b2dba800f', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why is it better to test a small part of a system in isolation before testing the entire integration?', N'Fresher', N'Testing in isolation, or unit testing, allows you to verify that individual components work as expected without interference from others. If a bug is found, it is significantly easier to pinpoint the exact location of the issue compared to testing the whole system at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9e4a8a1-5cb5-47f8-b41f-db7d52da3da4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Generics and why are they useful?', N'Junior', N'Generics allow you to create reusable components that can work with a variety of types rather than a single one. They provide type safety while keeping functions or classes flexible enough to handle different data structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23dc71eb-0606-47b9-a4ff-db7e7d734f7c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a simple and a composite primary key?', N'Intern', N'A simple primary key consists only of a partition key, which uniquely identifies each item. A composite primary key consists of both a partition key and a sort key, allowing for more complex queries and data relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'098fa8b5-696c-456d-a2fb-db7f6ed4dfef', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing a programming language or framework, what is the trade-off between a large ecosystem and niche performance?', N'Junior', N'A large ecosystem offers abundant libraries, community support, and easier hiring, which accelerates development speed. A niche, high-performance language might provide better execution speed or resource efficiency for specific tasks, but it often comes with a steeper learning curve and fewer available tools.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bd1e291-1cc3-4bdb-afa3-db7fe9931fd8', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do logs, metrics, and traces complement each other?', N'Middle', N'Metrics provide a high-level view of system health and trends, logs provide granular details about specific events, and traces provide context on how requests flow through distributed systems. Together, they form the ''three pillars'' of observability, allowing for full-stack visibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cde90f35-6c8a-4ee8-84b0-db81983f29f5', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the trade-offs of using ''atomic'' operations versus ''sync.Mutex''?', N'Senior', N'Atomic operations are lock-free and generally faster for simple counter or flag updates, as they map directly to CPU instructions. Mutexes are necessary for protecting complex data structures where multiple operations must be performed atomically as a single unit, providing better safety at the cost of potential contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a56eb93f-ed05-4760-951d-db824fe70872', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the ''Environment'' variable affect an ASP.NET Core application?', N'Middle', N'The environment (e.g., Development, Staging, Production) allows the application to conditionally apply configuration, logging levels, and middleware. For example, it is common to enable detailed error pages only in the Development environment while enforcing stricter security in Production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
