INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'435caeba-0277-4d67-9465-db83673d6f15', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the ''ConditionExpression'' parameter?', N'Middle', N'ConditionExpression allows you to implement optimistic locking or business logic constraints at the database level. An operation will only succeed if the specified condition evaluates to true, preventing accidental overwrites when multiple clients are modifying the same item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
