INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af30b5e4-c4f7-4997-94d3-db8f82d22aef', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the role of ''ARC'' (Automatic Reference Counting) in Swift''s memory management and its limitations.', N'Senior', N'ARC manages memory by inserting retain and release instructions at compile-time based on object ownership. Its primary limitation is the inability to automatically resolve circular dependencies, which requires developers to manually define ownership relationships using weak or unowned references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
