INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a7b2893-fe47-400d-870f-db940df78f6f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the purpose of monitoring tools in a production environment?', N'Junior', N'Monitoring tools provide real-time visibility into the health and performance of the application, alerting the team to issues before they become widespread. They allow developers to identify trends, such as increasing error rates or latency, which can help prevent outages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79a5d4c2-b554-4b1c-a7dd-db94692156ac', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the primary architectural benefits of using Sass mixins versus Sass extends in a large-scale project?', N'Middle', N'Mixins are best for reusable blocks of logic that accept arguments, making them highly flexible but potentially increasing the final CSS bundle size due to duplicated declarations. Extends utilize CSS selector grouping to share styles across different elements, which results in a smaller output file but can lead to complex specificity issues and fragile dependency chains if overused. Generally, mixins are preferred for their predictability and encapsulation, while extends are reserved for simple, static style sharing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'758ee395-5840-41d2-b9f1-db94828c220a', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the role of the frame object in Python''s execution stack?', N'Senior', N'A frame object represents a single execution context, containing local variables, the instruction pointer, and a reference to the global namespace. When a function is called, a new frame is pushed onto the stack, allowing Python to maintain state across nested calls and exception unwinding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6dad1df9-87fc-4704-b5ff-db953e5a29d3', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the concept of an inverted index and why Elasticsearch uses it.', N'Middle', N'An inverted index is a data structure that maps terms to the documents containing them, similar to an index in the back of a book. Elasticsearch uses it to perform full-text searches extremely quickly because it avoids scanning every document in the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c60b539-b4ed-4a3f-a8ed-db955973f188', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How do you define a constant in PHP?', N'Fresher', N'In PHP, a constant is a named identifier whose value remains consistent during the execution of a script. Key define() features - Case-Sensitivity: Constants are not case-sensitive by default. - Global Scope: Constants can be accessed from any part of the code without additional requirements. - Value Types: Constants can hold values like integers, floats, strings, or arrays. Syntax: define(NAME, value, case-insensitive) - NAME: The designated constant name (specific naming rules apply). - value: The constant''s assigned literal value or expression. - case-insensitive (Optional): A boolean flag (true for case-insensitive) determining if the constant''s name is case-sensitive. Code Example: Defining Constants Here is the PHP code: Best Practice 1.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7e4e5cb-39ab-4aa1-bb37-db95fb0bb527', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why does SvelteKit use the + prefix for file names?', N'Intern', N'The + prefix is a reserved naming convention used by SvelteKit to identify special files that control routing, data loading, and error handling. This distinguishes them from regular components inside the routes directory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82ab2be3-0e3c-44e6-8393-db9602f36ac3', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a channel in Go, and when would you use one?', N'Intern', N'In Go, a channel is a way to safely and efficiently share data among Goroutines. Its primary design goal is to streamline concurrent communication and data transfer. Key Characteristics - First-In-First-Out (FIFO) Order: Data enqueued to the channel is sent out in the same order. - Type Safety: Channels are type-specific to ensure clear data communication. - Blocking Synchronization: When the data is sent or received, the sending or receiving Goroutine is blocked until the operation is complete, promoting synchronization. Common Use Cases 1. Goroutine Coordination: Establish communication and synchronization among concurrent Goroutines. 2. Resource Sharing Among Goroutines: Use channels to manage shared resources, such as a fixed number of database connections between Goroutines. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24fd7617-ce1f-4600-8a29-db961a3db82b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is middleware in the context of Express?', N'Intern', N'Middleware functions are functions that have access to the request object, the response object, and the next middleware function in the application''s request-response cycle. They are used to execute code, make changes to request or response objects, end the request-response cycle, or call the next middleware in the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'111fe8cc-d2d6-46f6-b02b-db96b8ad736a', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot''s Actuator provide production-grade monitoring without compromising security?', N'Senior', N'Actuator exposes operational endpoints for health, metrics, and environment status. Security is maintained by requiring explicit configuration to enable sensitive endpoints and integrating with Spring Security to restrict access to authorized roles, preventing the leakage of internal system information to unauthorized users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61552407-c4d3-4360-8d3d-db98e6d9c79f', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why is it important to control the size of the request body in Echo, and how is it done?', N'Senior', N'Without body size limits, an application is vulnerable to memory exhaustion attacks where an attacker sends massive payloads to overwhelm the server. This is managed in Echo via middleware that checks the Content-Length header or limits the reader''s capacity before processing the body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd528ee85-bb1f-4e47-b06c-db9a080bc95a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a situation where two senior team members disagree on the technical approach to a task?', N'Junior', N'I would listen to the reasoning behind both perspectives to understand the pros and cons of each approach. If a decision is needed, I would ask for clarification on which criteria are most important for the project, such as performance, maintainability, or speed of delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e978ef89-b08b-4e46-b968-db9c2a296737', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you manage secrets like API keys or database credentials?', N'Junior', N'I never commit secrets to version control. I use dedicated secret management tools or encrypted environment variables provided by the deployment platform to inject these values at runtime, ensuring they remain secure and are easily rotated if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4fa08cf-ce35-462d-9f89-dbabd5bd9b78', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing an API, what are the trade-offs of using REST versus GraphQL?', N'Middle', N'REST is standardized, caches easily, and is straightforward to implement for simple resource-based interactions. GraphQL provides flexibility by allowing clients to request exactly the data they need, reducing over-fetching, but it adds complexity in server-side query execution and performance optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5f0340f-21e6-4594-9121-dbacf18e28d7', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is a pure function in the context of Redux?', N'Fresher', N'A pure function is a function that returns the same output for the same input and produces no side effects. Reducers must be pure functions because they must not modify the existing state object but instead return a new state object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9e53782-3268-4374-8b6b-dbb0ae4338f9', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the role of ''HTTP Cache'' headers in Symfony and how they interact with Varnish or Nginx.', N'Senior', N'Symfony uses cache headers like ''Cache-Control'' and ''ETag'' to instruct reverse proxies like Varnish or Nginx on how long to store a response. By properly configuring these headers within the application, you can offload traffic from the PHP engine, drastically increasing the system''s throughput and reducing server load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15c54626-8a87-4dab-9ae6-dbb430f8a0d8', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between throughput and latency?', N'Middle', N'Latency is the time taken to process a single request from start to finish, while throughput is the total number of requests a system can handle within a specific timeframe. A system can have low latency but low throughput, or high throughput but relatively high latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38a884ae-d775-43dd-8900-dbb525f6548e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is Redux and how is it used in web development?', N'Intern', N'Redux is a predictable state container principally designed for JavaScript applications. It efficiently manages and updates the app state, serving as a centralized global store. Core Concepts Store The store is at Redux''s nucleus and acts as a single source of truth. Here, you''ll find the current state alongside the ability to dispatch actions. Actions Actions are payloads of data - typically objects - that describe what needs to happen. These are dispatched to the store. Reducers Reducers are pure functions that specify how the state changes in response to actions. Each reducer handles a particular part of the state and combines to produce the full state. View The user interface (UI) or the output your app produces, is ideally a direct derivative of the current state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db040fe-b337-4708-a2f5-dbb5d2549271', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is throttling and debouncing in javascript?', N'Intern', N'Debouncing and throttling techniques are used to limit the number of times a function can execute. These are two widely-used techniques to improve the performance of code that gets executed repeatedly within a period of time. Throttling enforces a maximum number of times a function can be called over time. As in "execute this function at most once every 100 milliseconds." Example: Debouncing enforces that a function not be called again until a certain amount of time has passed without it being called.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e64cbda-f8aa-4388-b65e-dbb847bec951', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Describe how you would troubleshoot a system that is failing due to ''too many open files'' errors under load.', N'Senior', N'I would first inspect the file descriptor limits at the OS level and compare them against the current usage patterns of the application. I would then analyze the application''s connection handling logic to identify if it is failing to properly close sockets or file handles, leading to a resource leak that only triggers when the system hits a high request volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f26dda0d-ca6b-4923-87a0-dbbf1d308240', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Why use ''morgan'' or similar logging middleware?', N'Junior', N'Logging middleware like Morgan automatically records details about incoming HTTP requests, such as the method, URL, status code, and response time. This is essential for debugging and monitoring the health of a backend application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7e7e48c-dd98-4397-8f66-dbc042c4cf25', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle database migrations?', N'Fresher', N'Database migrations in AdonisJS allow you to version-control your database schema. They provide a structured way to create, modify, and rollback database tables using JavaScript files instead of manually executing SQL commands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbcb3bf1-7678-4c1f-874e-dbc3e436d934', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of the ''c.req'' object in Hono?', N'Junior', N'The c.req object provides access to the incoming request details, such as headers, cookies, query parameters, and the body. It abstracts the underlying platform''s request object into a standardized interface that is consistent across all supported runtimes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fd18de0-c201-437f-a829-dbc49203a71f', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the ''owner'' object work in Ember?', N'Middle', N'The owner object is the internal API that provides access to the application''s container, allowing objects to look up services or other registered classes. It is the backbone of Ember''s dependency injection system, ensuring that components and services can easily access the resources they need.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'905203d4-9c92-41d4-9b70-dbc5de758879', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask and why is it categorized as a micro-framework?', N'Fresher', N'Flask is a lightweight Python web framework designed to be simple and easy to get started with. It is called a micro-framework because it provides only the core essentials for building web applications, leaving the choice of tools and libraries for databases or authentication to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b03ff2cf-6414-4558-bfc4-dbc8a6998f6f', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''Any'' type in Scala?', N'Intern', N'The ''Any'' type is the root of the Scala class hierarchy. Every other class in Scala, whether user-defined or built-in, inherits from this type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5dc0fca-5f12-4533-8715-dbc9a6b69e52', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the difference between a ''has_many'' and ''belongs_to'' association?', N'Intern', N'These associations define the relationship between two database models. ''Has_many'' indicates that one record can be associated with multiple other records, while ''belongs_to'' signifies the inverse relationship where a record is linked to a single parent record.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6058bb4f-b319-4937-b409-dbcbbe1f95ee', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between server-side and client-side scripting in the context of PHP?', N'Fresher', N'PHP is a server-side language, meaning the code is executed on the web server before the resulting HTML is sent to the browser. In contrast, client-side scripting occurs within the user''s browser, relying on the user''s hardware to process the code. This distinction ensures that PHP source code remains hidden from the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd3260b2-64a6-482e-9619-dbcc7397e12a', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'When would you prefer an ''Hashed'' shard key over a ''Ranged'' shard key?', N'Senior', N'Hashed shard keys are preferred when you need to distribute data evenly across shards to prevent write hotspots. Ranged shard keys are better when you frequently perform range-based queries, as they allow the query router to target specific shards rather than broadcasting to the entire cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'683f3aa0-13f1-4f72-a425-dbcebd598936', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How do you maintain design consistency across a project when using Tailwind?', N'Middle', N'Design consistency is maintained by strictly adhering to the theme configuration file for spacing, colors, and typography. By using the design tokens defined in the configuration instead of hardcoded values, developers ensure that all UI elements align with the established design system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7a06143-9d5c-486f-b170-dbcf6c65004e', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is it generally discouraged to perform long-running blocking operations inside a Phoenix controller action?', N'Senior', N'Because Phoenix controller actions run within the context of a request-handling process, performing blocking operations like synchronous I/O or heavy computation can starve the process scheduler. This prevents the process from responding to heartbeats or other concurrent requests, leading to increased latency and potential system-wide performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b469274b-371e-4621-a636-dbd26b07808f', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the AsyncPipe and why is it preferred over manual subscription management?', N'Middle', N'The AsyncPipe automatically subscribes to an observable and emits the latest value, while also handling unsubscription when the component is destroyed. This prevents memory leaks by ensuring that stale subscriptions do not persist and simplifies component logic by removing the need for manual lifecycle hook management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04a60071-f991-4b8a-a119-dbd3c695854b', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to use a relational database or a NoSQL database for a new feature?', N'Junior', N'You should choose a relational database if the data is highly structured with clear relationships and requires strong consistency. NoSQL is preferable if the data model is flexible, unpredictable, or if you need to scale horizontally to handle massive amounts of unstructured data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6779f36-ce43-4a4e-9d81-dbd4c0515861', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the function of the @Service annotation?', N'Fresher', N'The @Service annotation is a specialization of the @Component annotation, used to mark a class as a service layer component. It is primarily used to indicate that the class holds business logic, making it easier for the component scanner to identify and register it as a bean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b74da18-8254-413e-a761-dbd68180a6f4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an entity-relationship diagram?', N'Intern', N'An entity-relationship diagram is a visual representation of the entities, attributes, and the relationships between them in a database. It acts as a planning tool to design the structure of the database before implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16cf092f-7d3f-4882-9cb5-dbd7a5a83ba5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is Tailwind CSS and how does it differ from traditional CSS frameworks like Bootstrap?', N'Intern', N'Tailwind CSS is a utility-first framework that provides low-level utility classes to build custom designs directly in your markup. Unlike Bootstrap, which provides pre-built components like buttons or navbars, Tailwind focuses on atomic classes that allow you to style elements without leaving your HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'032ff48a-c33d-4630-b188-dbd7af604f6a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why does Rocket use type-safe routing instead of dynamic path parsing?', N'Middle', N'Rocket uses type-safe routing to ensure that the parameters extracted from a URL are automatically converted into the desired Rust types. This design eliminates runtime casting errors and ensures that if a route matches, the data provided to the handler is already validated and correctly typed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1eac790e-3689-47fc-b042-dbdb25128a15', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the trade-offs of using Express.js as a non-opinionated framework versus a more opinionated one like NestJS?', N'Middle', N'Express is minimalist and highly flexible, allowing developers to choose their own structure and libraries, which is great for small projects. However, this lack of structure can lead to maintainability issues in large-scale applications, whereas opinionated frameworks enforce architecture patterns that improve consistency and scalability in large teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e2fc661-c3a6-4037-b87c-dbdbb1f6eaaf', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you decide between a hotfix and a standard release cycle when a critical bug is discovered in production?', N'Middle', N'The decision depends on the impact, risk, and urgency; if the issue causes significant data loss or service downtime, a hotfix is prioritized with rigorous testing and rapid deployment. For non-critical bugs, I prefer following the standard release cycle to ensure that testing, documentation, and regression checks are fully addressed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05e10218-0d81-4f1a-a635-dbde78193737', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How would you debug an issue where a cache layer is serving stale data despite a cache invalidation strategy being in place?', N'Senior', N'I would verify the propagation delay of the invalidation signals across the cache cluster to ensure that there isn''t a network partition or a failure in the pub/sub notification system. I would also check for edge cases where the cache key construction logic might be inconsistent between the writer and the reader, causing the system to write to and read from different buckets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00565ee1-21ae-47a0-af82-dbe12144bd13', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the benefit of using the Actix framework for high-load applications?', N'Intern', N'Actix is designed for high performance and low memory footprint. Its use of the actor model and asynchronous I/O allows it to handle massive numbers of concurrent requests with minimal resource usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aff3fa1f-52f4-438e-861c-dbe1726ea26a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''final'' keyword in Java?', N'Junior', N'The final keyword restricts modification. When applied to a variable, it prevents reassignment; when applied to a method, it prevents overriding; and when applied to a class, it prevents inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13817500-330b-42f3-8bee-dbe1cdf2d014', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the benefit of using ''inline'' functions?', N'Middle', N'The ''inline'' keyword serves as a request to the compiler to replace the function call with the actual function body, potentially eliminating the overhead of a function call. While it can improve performance, it may also increase the overall size of the binary if used excessively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7897c5dd-5387-4748-a125-dbe6ea696e8b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Describe the trade-off of using ''lazy val'' in a Scala program.', N'Middle', N'Lazy vals defer initialization until the first time the variable is accessed, which helps in avoiding expensive computations during startup. However, they introduce a performance cost due to the synchronization checks required to ensure thread-safe, single-time evaluation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edb6592d-a571-4067-8bff-dbea273184e5', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of the @Transactional annotation?', N'Middle', N'It provides a declarative way to manage database transactions, allowing you to define the boundaries of a transaction without manually opening and closing connections. It ensures that operations within the annotated method either all succeed or all roll back, maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b63f04b-3fcf-475d-9bc8-dbea58a10bcb', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the role of the ''tracked'' decorator in modern Ember?', N'Middle', N'The tracked decorator marks a property as observable, meaning the Glimmer rendering engine will automatically track its usage and trigger a re-render when the value changes. It is the fundamental mechanism for reactive state updates in modern Ember components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78c5eb10-f336-43c3-8cf3-dbed3cdf74ed', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of setting ''trust proxy'' in an Express application?', N'Middle', N'When an Express application sits behind a reverse proxy like Nginx or a load balancer, the proxy changes the request metadata. Setting ''trust proxy'' ensures that Express correctly identifies the real client IP address and the original protocol from the X-Forwarded headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2412f2ef-ec79-4306-b80b-dbee0a2128fb', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''ref'' and ''out'' parameter modifier differ?', N'Middle', N'The ''ref'' keyword requires the variable to be initialized before it is passed to the method, and the method can read or modify it. The ''out'' keyword does not require prior initialization but mandates that the method assigns a value to it before returning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5289a34b-17f2-472a-9fb4-dbf6087e2d2a', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does query offloading improve database performance?', N'Middle', N'Query offloading involves moving expensive, long-running analytical queries to a separate data warehouse or an analytical replica. This protects the operational database from resource-intensive tasks, ensuring low-latency performance for user-facing transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eacc12d-661d-4657-9a0e-dbf8aa4592a7', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do Axum''s ''Nested'' routers impact middleware scoping?', N'Senior', N'When you nest a router into another, middleware applied to the parent router will affect all routes in the nested router. Conversely, middleware applied to the nested router only affects its own children, allowing for granular control over security and logging per API module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c46d940-6d13-47e3-82bb-dbf99747b764', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Does FastAPI support both synchronous and asynchronous path operations?', N'Fresher', N'Yes, FastAPI supports both. You can define route handlers using either standard ''def'' for synchronous code or ''async def'' for asynchronous code, and the framework will handle them appropriately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
