INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdb59992-ccff-479e-af60-dbff5e8a8768', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you achieve multi-tenancy in a Litestar application using dependency injection?', N'Middle', N'Multi-tenancy can be implemented by creating a dependency that extracts tenant information from headers or tokens and injects a scoped tenant service into the request context. This ensures that every handler receives the correct tenant-specific data without needing to perform manual extraction in every route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'342f3994-866c-487b-881e-dc01e44757b5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik require a virtual DOM?', N'Junior', N'No, Qwik does not use a virtual DOM in the way frameworks like React do. Because of its resumability architecture, it directly updates the DOM based on the serialized state and event triggers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89d54fad-4926-418e-b0be-dc01eaed9565', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the significance of the ''readonly'' keyword when applied to fields?', N'Middle', N'A readonly field can only be assigned a value during its declaration or within the constructor of the containing class. This ensures that the field''s value remains immutable after object initialization, which helps in thread safety and preventing accidental state modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1663b656-c770-4f4e-beaf-dc03a3b14c30', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik often called a ''zero-cost'' framework?', N'Fresher', N'It is called zero-cost because it minimizes the amount of JavaScript the browser needs to download and execute on the main thread during the initial load. By deferring execution until interaction, the cost of the framework is effectively pushed to the point of use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5269f3d-7a87-4201-a634-dc0444fa418a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the impact of using ''readonly'' versus ''const'' in TypeScript?', N'Senior', N'Const is a JavaScript keyword that prevents reassignment of a variable, while readonly is a TypeScript modifier that prevents mutation of object properties at compile time. Readonly is essential for enforcing immutability in state management and ensuring data integrity across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
