INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56409394-6291-4cda-938e-dc09aba3e233', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does a broker handle ''head-of-line'' blocking in a queue?', N'Senior', N'Head-of-line blocking occurs when a slow or failed message at the front of the queue prevents subsequent messages from being processed. Brokers address this through mechanisms like per-consumer acknowledgments, message retries with backoff, or moving the stalled message to a DLQ.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'294cf0e9-1f50-4bf5-bcf3-dc0af2fbb796', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Explain the architectural difference between Nuxt’s Server-Side Rendering (SSR) and Client-Side Rendering (CSR) modes.', N'Senior', N'In SSR, the server generates the full HTML string for a route, which improves SEO and initial load speed. In CSR, the server sends a minimal HTML shell and the browser fetches the JavaScript bundle, shifting the rendering workload entirely to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51189d6b-f3a2-4a85-9054-dc0b36b3413b', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain how partitioning (sharding) impacts transaction atomicity.', N'Senior', N'Sharding complicates atomicity because a single transaction may need to span multiple nodes, requiring distributed locking or a two-phase commit protocol. This increases the complexity of failure recovery and often leads to significant performance overhead compared to single-node transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bb58095-7ca0-4b82-85f4-dc0f393bbf93', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the types of feature modules?', N'Intern', N'Below are the five categories of feature modules, 1. Domain: Deliver a user experience dedicated to a particular application domain(For example, place an order, registration etc) 2. Routed: These are domain feature modules whose top components are the targets of router navigation routes. 3. Routing: It provides routing configuration for another module. 4. Service: It provides utility services such as data access and messaging(For example, HttpClientModule) 5. Widget: It makes components, directives, and pipes available to external modules(For example, third-party libraries such as Material UI)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a27e514f-f604-4f7c-9eaa-dc0fded187d5', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is ''Distributed Elixir'' and how does Phoenix leverage it?', N'Middle', N'Distributed Elixir allows multiple nodes to communicate as if they were a single system. Phoenix leverages this through features like distributed PubSub and Presence, enabling seamless synchronization of state and events across a cluster of servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51a70ff1-bc5a-4bfa-a47a-dc0feacbb4c6', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the ''mailbox'' in the Actor model?', N'Middle', N'The mailbox is a queue that stores incoming messages for an actor. It ensures that messages are processed one by one, providing an asynchronous, thread-safe way for different parts of the application to interact without needing complex locking mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7b37eb9-bc2b-4fed-8373-dc12a2d7d186', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a foreign key, and what role does it play in database design?', N'Fresher', N'A foreign key is a field in one table that links to the primary key of another table. It is used to establish and enforce a relationship between two tables, ensuring referential integrity by preventing actions that would destroy links between data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3055cefa-535b-4f81-81a9-dc1418770112', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix handle sessions and cookies?', N'Fresher', N'Phoenix uses Plugs to manage sessions, typically storing them in encrypted cookies. The session data is signed to prevent tampering, and it provides a way to persist user-related information across requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f82b8a1-6578-4980-926d-dc141dd90a7d', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of serialization in Fastify?', N'Fresher', N'Serialization is the process of converting JavaScript objects into a JSON string before sending them as a response. Fastify uses high-performance libraries to perform this task, which significantly speeds up response times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6e5215c-073e-497a-bd6e-dc14aa184f92', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Why is Qwik considered ''SEO friendly''?', N'Intern', N'Qwik is SEO friendly because it delivers fully rendered HTML to the browser immediately. Search engine crawlers receive the complete content of the page without having to wait for the JavaScript to execute or hydrate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83097fbe-4f23-4916-9dfd-dc163426d5a6', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are AdonisJS migrations?', N'Intern', N'Migrations are a version control system for your database schema. They allow you to define, modify, and share the structure of your database tables in a collaborative way, ensuring that every team member has the same database structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1392c07-e9a4-4038-bd2a-dc16e71a3854', N'954a0331-deff-4399-b588-96f39fec001d', N'What are feature modules?', N'Intern', N'Feature modules are NgModules, which are used for the purpose of organizing code. The feature module can be created with Angular CLI using the below command in the root directory, Angular CLI creates a folder called my-custom-feature with a file inside called my-custom-feature.module.ts with the following contents Note: The "Module" suffix shouldn''t present in the name because the CLI appends it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6920c9f-0e55-4923-9ca9-dc1799db7241', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where your estimate is rejected by your manager for being too high?', N'Fresher', N'I would walk the manager through my breakdown of the task, explaining the specific complexities and risks that contributed to my estimate. I would ask if there are ways to simplify the requirements or if certain parts of the task can be deferred to reduce the scope. This creates a collaborative conversation focused on meeting business needs while remaining realistic about technical constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef0541ca-c868-4636-8c5a-dc17a93af5ca', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a static file server in Fiber?', N'Fresher', N'A static file server is a built-in feature that serves files like images, CSS, or JavaScript directly from a local directory. It allows the web application to provide frontend assets to the browser without additional configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fe1ab84-3179-4a16-9d64-dc1cd4f90c1d', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the ''Switch'' and ''Match'' pattern in SolidJS?', N'Fresher', N'The Switch and Match components are used for complex conditional logic, similar to a switch-case statement. This is a cleaner alternative to nesting multiple ternary operators for conditional rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbe35fd7-f0bd-4307-8c22-dc1d26a69a61', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the risks of ''Serializable'' isolation?', N'Middle', N'Serializable isolation is the strictest level and prevents all concurrency anomalies, but it often requires extensive locking or complex validation. This significantly reduces throughput and increases the likelihood of transaction deadlocks, making it a performance-intensive design choice.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b6b8353-4f42-4884-9abf-dc1e15116274', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala handle type inference?', N'Intern', N'Scala uses local type inference to determine the data type of a variable or expression based on its initialization or usage. This allows developers to omit explicit type declarations in many cases, making the code cleaner while maintaining type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51815c15-bf25-49fe-8824-dc244ed3775c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are extension methods and how are they resolved by the compiler?', N'Middle', N'Extension methods allow you to add new methods to existing types without modifying the original source code. The compiler resolves these by treating them as static method calls where the object instance is passed as the first argument.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d1610ad-9e86-40c3-9ad1-dc27472532a2', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do ''Vector Clocks'' or ''Version Vectors'' resolve conflicts in distributed NoSQL stores?', N'Senior', N'These mechanisms track the causal relationship between updates in a distributed system, allowing the database to detect concurrent updates that cannot be ordered by timestamps alone. They enable the system to identify conflicts and delegate resolution to either the application or a conflict-resolution policy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25c2021c-36d1-45a9-943f-dc29434a654f', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the trade-offs of using Lucid ORM versus a raw query builder in a high-throughput AdonisJS application?', N'Senior', N'Lucid ORM provides developer productivity and abstraction but incurs overhead due to model instantiation and object tracking. For high-throughput scenarios, raw query builders reduce memory footprint and latency, though they sacrifice the maintainability and type safety features provided by the ORM layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72f515b5-5362-4d6c-900d-dc29ed3a166c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why might you use the ''use client'' directive in Next.js?', N'Junior', N'You use this directive to explicitly tell Next.js that a specific component requires client-side interactivity. It is required whenever you use React hooks like useState or useEffect, or when you need to attach event listeners to elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24448d23-a06e-4fd0-81ae-dc2c29892e70', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle caching of modules?', N'Middle', N'Webpack caches modules during the build process to avoid unnecessary re-compilation. With Webpack 5, persistent caching allows the build state to be saved to the filesystem, which drastically reduces subsequent build times by skipping the processing of modules that have not changed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a811a1d-6335-48af-9296-dc31df5a178e', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono leverage Web Standards to improve performance?', N'Middle', N'By utilizing the Request and Response objects defined in the Fetch API, Hono avoids the overhead of legacy Node.js-specific HTTP abstractions. This alignment with native browser standards ensures that the framework remains lightweight and highly performant in edge computing environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b00aa57-5e75-40fe-a5af-dc33112f373d', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the ''Backends for Frontends'' (BFF) pattern and why use it?', N'Senior', N'The BFF pattern involves creating separate API gateways for different types of clients, such as mobile, web, and IoT. This allows the backend to tailor data responses and performance characteristics to the specific needs of each client type without bloating a single gateway.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0835cd04-effa-41e6-a11e-dc35d18a25ee', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are plugins in Nuxt?', N'Intern', N'Plugins are scripts that run before the main application logic starts. They are used to inject global functionality, such as third-party libraries or global configuration, into the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deb8468a-0a0b-4381-a97d-dc37daaa3e6e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your strategy for database migrations in a production environment?', N'Middle', N'I ensure all migrations are backward-compatible, typically following a multi-step process: adding columns, supporting both old and new code, migrating data, and finally removing the old structures. I always have a rollback plan and execute migrations during low-traffic periods to minimize potential downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9eb3ce00-4344-42e7-b98e-dc38f23a7f71', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the function of the Quarkus ''Dev Services'' feature?', N'Junior', N'Dev Services automatically provisions and configures external dependencies, such as databases or message brokers, in Docker containers during development. This removes the need for developers to manually set up these services on their local machines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc26ff6a-7069-4797-bb48-dc3c94178b16', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What does it mean that Kotlin is statically typed?', N'Intern', N'Statically typed means that the type of every variable is known at compile time. This allows the compiler to perform type checking before the program runs, catching many potential errors early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78b72248-134f-46c8-a718-dc3d4a5b4b3b', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the Result enum?', N'Junior', N'The Result enum is used for error handling and represents either success or failure. It forces the programmer to acknowledge the possibility of an error and handle it explicitly before accessing the underlying value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8225911-0149-4ebe-9689-dc3fd6920e57', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the performance implications of using Echo''s middleware for cross-cutting concerns like rate limiting?', N'Senior', N'Middleware-based rate limiting is convenient but can introduce latency if the store is external, such as Redis. For high-throughput systems, implementing rate limiting at the API gateway layer is often more efficient than processing it within the application logic itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'180c7b7d-59da-4b5a-be98-dc43c3ac88a5', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Helpers in Ember and when should they be used?', N'Middle', N'Helpers are small, reusable functions that transform values within a template, such as formatting dates or performing simple arithmetic. They should be used for pure logic that does not require internal state or interaction with the component lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'344e4e8d-a5a6-434c-bd0d-dc4550879b98', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the Garbage Collector (GC) in C#?', N'Intern', N'The Garbage Collector is an automatic memory management feature that reclaims memory occupied by objects that are no longer being used by the application. This helps prevent memory leaks by periodically cleaning up unreachable objects from the heap.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f7fc5b7-5a81-44c4-8ba2-dc45e8f82437', N'954a0331-deff-4399-b588-96f39fec001d', N'What are router links and how are they used?', N'Intern', N'Router links, provided by the routerLink directive in Angular, are the primary way to enable navigation between different routes within your application using declarative syntax in your templates. Instead of using the standard HTML href attribute, which causes a full page reload, routerLink leverages Angular''s Router to perform client-side navigation. You typically apply routerLink to an anchor ( ) tag, but it can be used on any element. Here are common ways to use it: - Static path: - Path with parameters: Use an array syntax. - Path with query parameters and fragment: Using routerLink ensures that Angular''s routing mechanism handles the navigation, allowing for features like route guards, resolvers, and smooth transitions without a full page refresh.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87ec7c53-c3eb-4752-a1bb-dc461bab67cd', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database isolation levels affect performance and consistency?', N'Middle', N'Higher isolation levels like Serializable provide maximum data consistency by preventing all concurrency phenomena but significantly reduce performance due to increased locking. Lower levels like Read Committed offer better throughput but are susceptible to issues like non-repeatable reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d7b88e7-c842-49b9-8cd1-dc465c7d2cf1', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar optimize performance compared to traditional synchronous frameworks?', N'Senior', N'Litestar is built on an asynchronous-first architecture using Starlette''s ASGI implementation, which allows for non-blocking I/O operations and high concurrency. By leveraging Python''s ''asyncio'' and avoiding blocking calls in the event loop, it sustains higher throughput for I/O-bound microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba5d2999-b955-4a46-ac63-dc49deb0e74d', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How can you prevent form submission data from being injected with malicious code?', N'Fresher', N'To prevent cross-site scripting (XSS) attacks on your website, it is crucial to validate and sanitize any data submitted through forms. Key Anti-XSS Techniques Manual Escaping Escape form data using htmlspecialchars to convert special characters to HTML entities. JavaScript Sanitization To prevent execution of JavaScript code, you can use: - JavaScript replace method: Replace the less-than and greater-than characters with their HTML entities. - JSON encoding for non-text data in hidden fields. Safe Back-End Handling Always perform thorough server-side validation and ensure only intended actions are executed in response to form submissions: - Database Prepared Statements: Use prepared statements alongside parameterized queries when interfacing with the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c43a3c7-caf9-439c-b255-dc4eafcc86ae', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why might a system prefer ''Eventual Consistency'' in its caching layer over ''Strong Consistency''?', N'Senior', N'Eventual consistency significantly improves availability and write performance by removing the need for distributed locks or synchronous invalidation across nodes. It is preferred when the business logic can tolerate slightly stale data in exchange for lower latency and better system resilience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7a9cf86-7448-436b-9f2b-dc4f428824a6', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are the technical considerations for implementing HTML-based client-side hydration?', N'Senior', N'Hydration involves attaching event listeners and application state to server-rendered HTML. To be successful, the client-side framework must match the server''s output exactly; otherwise, the mismatch can lead to layout shifts, state loss, and performance degradation during the transition from static content to interactive application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a090b4f5-5b9f-4a9c-9f72-dc5289facd1b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the potential drawbacks of using Echo''s internal Logger middleware in a production environment?', N'Senior', N'The default logger is often insufficient for structured logging requirements, such as JSON-formatted logs needed by systems like ELK or Splunk. Senior developers should replace the default middleware with a structured logging library to ensure logs are machine-readable and provide adequate context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
