INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e1d8957-dfda-4121-888a-dc559e42d889', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS handle asynchronous programming?', N'Fresher', N'NestJS fully supports modern JavaScript features like Promises and Observables. It relies heavily on async/await syntax, which allows developers to write clean, readable asynchronous code when dealing with database operations or external API calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0fecac2-4332-4f5f-9503-dc576b9a6295', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does ''Database Replication'' affect read and write scalability?', N'Senior', N'Read replicas allow for horizontal scaling of read-heavy workloads by distributing queries across multiple servers. However, write operations must typically go through a primary node, which remains a potential bottleneck unless complex multi-master setups are implemented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
