INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ca36948-317e-4980-8235-dc643cd9599a', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is Read Repair?', N'Fresher', N'Read repair is a background process that ensures consistency by comparing data across replicas during a read request. If the replicas contain different versions of the data, the most recent version is returned to the client and the out-of-date replicas are updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09123648-5e7c-4f77-9625-dc645d67dbbf', N'f2e963ff-7635-4429-a389-4d92535fb972', N'Explain the performance trade-offs of using ''inline'' CSS versus external stylesheets in the HTML head.', N'Senior', N'Inlining critical CSS reduces round-trip times by avoiding an extra network request for the initial render, which improves First Contentful Paint. However, it prevents the browser from caching the CSS separately and can bloat the HTML file size, making it less efficient for repeat visits compared to external cached files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
