INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4904189-86a0-47c5-8691-dc66cfc67a10', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does Next.js optimize image loading, and why is this critical for Core Web Vitals?', N'Senior', N'Next.js uses an automatic image optimization engine that resizes, compresses, and converts images to modern formats like WebP or AVIF based on the user''s device. This significantly reduces the payload and prevents layout shifts, which directly improves Cumulative Layout Shift and Largest Contentful Paint scores.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'902637b2-8a8f-483a-b43e-dc6a374b20f6', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why is it beneficial to compare the behavior of a failing system against a working one?', N'Intern', N'Comparing a failing system to a working one helps identify differences in configuration, environment, or input processing. By isolating these differences, you can often pinpoint the exact component or setting that is causing the failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'78cca331-7451-4bfa-a4c7-dc6bca3112d5', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is backpressure in the context of Node.js streams?', N'Middle', N'Backpressure occurs when a readable stream produces data faster than a writable stream can consume it. To prevent memory overflow, the system signals the readable stream to pause or slow down until the writable stream is ready to process more data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62d35984-24bc-432b-8203-dc6c1db8ccc0', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the advantage of Rocket''s ''type-directed'' design?', N'Fresher', N'The advantage is that the framework uses the types of your function arguments to determine how to parse the request. This eliminates the need for manual type conversion and reduces the likelihood of runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fdd234b-ff6a-4cbb-8672-dc6eec936aa7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go not support traditional class-based inheritance?', N'Junior', N'Go favors composition over inheritance. By using struct embedding and interfaces, Go achieves code reuse and polymorphic behavior in a way that is generally considered easier to maintain and reason about.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de7eceb4-9f21-417b-b35e-dc6fbe769fa9', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the purpose of Automatic Reference Counting (ARC) in Swift.', N'Middle', N'ARC is a memory management mechanism that tracks and manages an application''s memory usage by automatically freeing up memory when class instances are no longer needed. It works by counting the number of active references to an object and deallocating it when the count reaches zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c1477cd-530f-41be-978e-dc6fe61339dd', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between res.send and res.end?', N'Fresher', N'res.send sends the HTTP response and automatically handles headers and character encoding for the response body. res.end is used to end the response process without sending any data, typically used when the response is already handled by other means.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5112003d-752a-4a16-b886-dc70410dfe73', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you approach designing for fault tolerance in a system with multiple dependencies?', N'Middle', N'I implement patterns like circuit breakers to prevent cascading failures and use timeouts to ensure that a slow dependency doesn''t exhaust the system''s thread pool. I also ensure that retries are idempotent and include exponential backoff to avoid overwhelming failing services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa580d3d-51e6-4cac-8fd1-dc73579ba95e', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle concurrency?', N'Junior', N'Actix handles concurrency through asynchronous execution powered by the Tokio runtime. Actors run within this runtime, allowing many tasks to be executed concurrently on a small number of threads without blocking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f683830a-fcfb-4ff2-8cd8-dc73e4fa44eb', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''hot module replacement''?', N'Intern', N'Hot module replacement allows parts of an application to be updated without a full page refresh. This preserves the application state, such as form inputs or UI state, while showing the changes made to the code immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43263bfa-5fc8-43a6-9d83-dc743dfaa3fb', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s ''Self-types'' feature differ from inheritance in terms of architectural coupling?', N'Senior', N'Self-types define an expectation that an object must be mixed into a specific trait without creating a hard ''is-a'' relationship. This allows for decoupled composition where traits can declare dependencies on external functionality while remaining modular. Inheritance creates a rigid, hierarchical dependency that is harder to test and evolve compared to the flexible composition enabled by self-types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a8966a3-6a35-42e5-869b-dc7536d6431d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''assets'' pipeline?', N'Intern', N'The asset pipeline is a framework for managing and serving static assets like CSS, JavaScript, and images. It provides features like concatenation, minification, and pre-processing, which help optimize the delivery of frontend files to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be79e04c-830c-4b81-b318-dc75bfff142c', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket prevent common web vulnerabilities?', N'Intern', N'Rocket leverages Rust''s memory safety to prevent common issues like buffer overflows. Additionally, its request guards and type-safe routing help prevent injection attacks by validating input before it reaches your logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3c54a4d-8b6b-43d6-b7f7-dc76fe5234b5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why might you choose an asynchronous messaging queue over direct synchronous API calls between microservices?', N'Middle', N'Asynchronous messaging decouples services, allowing them to scale independently and maintain functionality even if a downstream service is temporarily unavailable. It also smooths out traffic spikes by acting as a buffer, preventing system-wide cascading failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f60cad5-634f-42e1-8797-dc78726524b8', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the difference between ''page actions'' and ''load functions'' in SvelteKit.', N'Middle', N'Load functions are responsible for reading data and preparing the initial view of a page. Conversely, page actions are designed for handling data mutations, such as form submissions, and are the primary way to perform server-side side effects like database writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ded7da4c-07ee-44b7-9c26-dc793488dc98', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber''s routing engine handle dynamic path parameters, and what are the performance benefits?', N'Senior', N'Fiber uses a Radix tree or a similar trie-based structure for routing, which allows for constant-time or logarithmic-time lookup regardless of the number of registered routes. This is significantly more efficient than linear array-based routing, especially when dealing with complex API surfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
