INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a14b91e5-ec5f-4c25-b9ca-dc7c8b8f3ddd', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the trade-off between normalized and denormalized database design?', N'Junior', N'Normalization reduces data redundancy and prevents update anomalies but requires complex joins that can be slow. Denormalization improves read performance by grouping related data together but increases the risk of data inconsistency and makes updates more difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
