INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a647fbaf-1b1e-45df-88d4-dc84e3cf6bb7', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between {} vs new Object()?', N'Fresher', N'1. Object Literal Syntax ({}): Object literal syntax is a shorthand way of creating an object. We can create an object by placing a comma-separated list of key-value pairs inside curly braces { }. The key represents a property name of the object and the value represents the value of that property. Syntax: Example: 2. Object Constructor Syntax (new Object()): The object constructor syntax is a way of creating an object using the new operator and the Object constructor function. We can create an empty object by calling the Object constructor without any arguments. We can also create an object by passing an object literal as an argument to the Object constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffe3952d-d391-490f-aa85-dc856fdc67fa', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do NoSQL databases handle relationships compared to SQL?', N'Intern', N'SQL databases use joins to connect tables based on related data. NoSQL databases typically avoid joins, instead favoring data denormalization by embedding related data within a single document or structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3e61745-bdf6-4604-a16e-dc8965db80c5', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the significance of the Zend VM''s stack-based architecture?', N'Senior', N'The Zend VM uses an operand stack to manage temporary variables and function arguments during opcode execution. This stack-based approach simplifies the compiler implementation and allows for efficient management of nested expressions, though it adds a layer of indirection compared to register-based VMs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63481923-2014-49dd-bbdc-dc8a59cb404f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How does ''Multi-Version Concurrency Control'' (MVCC) work in a document database?', N'Senior', N'MVCC allows the database to maintain multiple versions of a document simultaneously, enabling read operations to access a consistent snapshot of the data even while concurrent writes are occurring. This approach prevents read-write contention and ensures that readers never block writers, maintaining high performance in multi-user environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a73504a-b7e5-4616-9ed7-dc8aa227e5f0', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of the ''Undo'' and ''Redo'' logs in ARIES recovery?', N'Senior', N'The Redo log is used to reapply changes from committed transactions that might not have been flushed to disk before a crash. The Undo log is used to roll back changes from transactions that were in progress at the time of the crash, ensuring the database returns to a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62571787-6960-425c-ba67-dc8ee528e4ba', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle function overloading?', N'Fresher', N'Function overloading allows you to define a function with multiple signatures but a single implementation. This provides better type inference for different input combinations, helping the compiler understand the relationship between the arguments and the returned value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8c06218-c24b-4621-8031-dc8f2534a67b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is difference between spawn() and fork() methods in Node.js?', N'Fresher', N'1. spawn(): In Node.js, spawn() launches a new process with the available set of commands. This doesn''t generate a new V8 instance only a single copy of the node module is active on the processor. It is used when we want the child process to return a large amount of data back to the parent process. When spawn is called, it creates a streaming interface between the parent and child process. Streaming Interface — one-time buffering of data in a binary format. Example: Output 2. fork(): The fork() is a particular case of spawn() which generates a new V8 engines instance. Through this method, multiple workers run on a single node code base for multiple tasks. It is used to separate computation-intensive tasks from the main event loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f88b957-1276-4255-a227-dc8fe79304d8', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the role of Nuxt''s auto-import feature and what are the potential trade-offs?', N'Middle', N'Nuxt automatically imports components, composables, and utilities from specific directories to reduce boilerplate code. The trade-off is that it can make it harder to trace where a specific function or component originated, potentially leading to name collisions in large projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0abc0080-a2bb-46db-9198-dc98d0860069', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What does it mean that Ruby is an interpreted language?', N'Intern', N'Ruby code is executed by an interpreter that reads and processes the instructions at runtime. This differs from compiled languages, which require a separate step to convert code into a machine-readable binary format before execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06ea6222-51e5-4b01-9084-dc9bdfb7e434', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the Ruby VM handle ''Tail Call Optimization'' (TCO), and why is it not enabled by default?', N'Senior', N'TCO allows the VM to reuse the current stack frame for a method call when it is the final action, preventing stack overflow in recursive algorithms. It is disabled by default because it obscures backtraces during debugging, making it difficult to trace the execution flow when an error occurs deep in the call stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea0a0e1c-3d1c-47b0-bdfb-dc9e0e7ae22e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are PWAs', N'Intern', N'Progressive web applications (PWAs) are a type of mobile app delivered through the web, built using common web technologies including HTML, CSS and JavaScript. These PWAs are deployed to servers, accessible through URLs, and indexed by search engines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6d9b83c-208d-45e4-8d88-dc9ebfede93b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the role of the ''Supervisor'' in Actix?', N'Middle', N'The Supervisor pattern is used to monitor an actor''s lifecycle and restart it automatically if it crashes or stops unexpectedly. This adds a layer of fault tolerance, ensuring that critical services remain available despite individual failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6eaced2-a86d-4e98-8164-dca0b1c8ac66', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain how Node.js manages memory for buffers and the difference between Buffer and ArrayBuffer.', N'Senior', N'Buffers are allocated outside the V8 heap in C++ space, allowing for efficient memory management of binary data. ArrayBuffer is a fixed-length raw binary data buffer, while Buffer is a subclass of Uint8Array that provides specific methods for handling different encodings and character sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
