INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fe09bae-5547-49d6-b22a-dcc433da0bab', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the advantages of using a composite primary key?', N'Middle', N'A composite primary key uniquely identifies a record using a combination of two or more columns. It is useful in junction tables for many-to-many relationships, as it inherently enforces the uniqueness of the relationship between the two entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
