INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b78e6b00-348c-4455-9bfc-dcf810451a78', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is a major risk of tight coupling in software architecture?', N'Middle', N'Tight coupling makes systems fragile, as a change in one component often requires changes in others. It complicates testing, limits independent scalability, and increases the likelihood that a failure in one service will cascade to the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f29b7d66-1cde-4c12-babf-dcf8fb646356', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Describe the mechanism of Copy-on-Write (COW) and why it is crucial for Swift performance.', N'Senior', N'COW is an optimization strategy for value types where the actual underlying data is only copied when a mutation occurs. By checking the reference count of the heap-allocated buffer, the runtime determines if the data is uniquely held; if so, it mutates in place, otherwise, it performs a deep copy. This provides the safety of value semantics with the performance efficiency of reference types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f6d2209-638e-4bb8-a6b3-dcf9f6d59b13', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you ensure data consistency in a distributed system while maintaining high availability?', N'Senior', N'According to the CAP theorem, you must choose between consistency and availability during a network partition. In highly available systems, move toward ''eventual consistency'' using mechanisms like sagas or conflict-free replicated data types to ensure the system remains responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f45eb428-cb61-4cb9-831b-dcfab8263b27', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why would you use ''Arc'' with the application state in Axum?', N'Junior', N'Arc (Atomic Reference Counted) is used to share the application state across multiple threads safely. Since Axum handlers may run concurrently, wrapping the state in an Arc ensures that it can be accessed and modified safely by different requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
