INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49720d58-dd37-4539-8baf-dd0693cdbd78', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the ''container query'' specification change frontend architecture?', N'Senior', N'Container queries allow components to respond to the size of their parent container rather than the viewport. This enables a truly modular component architecture, as components are no longer dependent on global breakpoints and can be reused in various contexts without needing external overrides.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d6271f4-b79d-4156-beed-dd06f599f9fa', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When selecting a deployment frequency, what is the trade-off between moving fast and ensuring stability?', N'Junior', N'Frequent deployments allow for rapid feature delivery and quick feedback loops, keeping the team agile. However, they increase the risk of introducing bugs into production, necessitating robust automated testing and canary deployment strategies to maintain system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e2111c7-0b67-402b-91d3-dd0838e7ef89', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain how Micronaut supports GraalVM native images.', N'Middle', N'Micronaut is architected to be GraalVM-friendly by avoiding reflection and dynamic class loading, which are the primary hurdles for native compilation. This allows developers to compile their applications into single, standalone executables that start in milliseconds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bca637bc-cde2-469e-98f1-dd083a4b6bd6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing an API, how do you balance backward compatibility with the need for clean, updated interfaces?', N'Senior', N'I prioritize backward compatibility to avoid breaking downstream consumers, typically using versioning strategies like URI or header versioning. I accept the burden of maintaining legacy endpoints until metrics show usage has dropped below a threshold that justifies a deprecation cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95685380-5f14-4947-83ad-dd0911b2b447', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why should you avoid overuse of the @at-root directive?', N'Middle', N'@at-root moves selectors outside of their nested parent context, which can break the expected cascading logic of your styles. While it is useful for specific layout patterns or BEM modifiers, overusing it makes the stylesheet structure non-intuitive and harder for other developers to read.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7780b09a-422b-4098-8382-dd0ccc585ef6', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is PHP PDO?', N'Fresher', N'PDO stands for PHP Data Objects and is a consistent interface for accessing databases. It provides a data-access abstraction layer, which means you can use the same functions to query different types of databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ca7dc73-a2ab-4302-a1ba-dd0d9bd3e890', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle file uploads and storage abstraction?', N'Middle', N'AdonisJS uses the ''Drive'' package, which provides a unified API for interacting with various storage backends like local disk, AWS S3, or GCS. This abstraction allows developers to switch storage providers through configuration changes without having to modify the application''s file handling logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9852329-5532-439c-86cc-dd0f74ad0186', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is an interpreted language, and how does it apply to Python?', N'Intern', N'An interpreted language is one where instructions are executed directly by an interpreter rather than being compiled into machine code beforehand. In Python, the source code is compiled into bytecode, which is then executed by the Python Virtual Machine. This process allows for faster development cycles as there is no explicit compilation step required by the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fced0207-0267-496a-a1ae-dd10e93615e5', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Is jQuery''s plugin architecture still a recommended way to extend functionality?', N'Middle', N'The plugin architecture is great for modularizing jQuery-based logic, but it ties your code strictly to the jQuery library. In a modern context, creating reusable modules using ES6 classes or functional programming patterns is preferred as it avoids vendor lock-in and dependency bloat.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e98841c0-a079-4174-939b-dd11c1dea074', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How does the Rails routing system work?', N'Fresher', N'The routing system maps incoming HTTP requests to specific controller actions. It acts as a gatekeeper that matches a URL pattern to a defined route in the routes file, which then triggers the appropriate method within the corresponding controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6efd1d44-a739-437c-b9a2-dd1294f627a2', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite manage the ''double-bundling'' issue in monorepo setups?', N'Senior', N'Vite handles monorepos by allowing dependencies from outside the root directory to be symlinked and resolved as part of the dependency graph. Using Vite''s dependency optimization allows developers to force specific packages to be pre-bundled, preventing multiple versions from being loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3eb3dad-afaa-41bc-b64c-dd12a2e16fee', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why would you prefer ''web::Data'' over global static variables in Actix-web?', N'Senior', N'web::Data provides a clean, scoped way to inject dependencies into application state that is tied to the lifecycle of the server instance. Global static variables are often difficult to test, prone to initialization order issues, and less flexible for dependency injection patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d70a035-a1f8-4c47-b621-dd12d34d818a', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the trade-offs of using virtual tables versus template-based static polymorphism.', N'Senior', N'Virtual tables provide runtime polymorphism by using indirection via a vptr, which enables dynamic dispatch at the cost of a small memory overhead per object and a potential instruction cache miss due to pointer chasing. Template-based static polymorphism resolves calls at compile time, allowing for aggressive inlining and optimization but leading to code bloat and strictly coupled compilation units.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9d369b9a-4767-4dc5-92ee-dd14ab8e52c1', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How would you implement a robust logging and observability strategy for a Django production environment?', N'Senior', N'Observability requires more than basic logging; it involves structured logging to JSON, distributed tracing to track requests across services, and metrics collection. Integrating tools like Sentry, ELK, or Datadog allows for proactive identification of bottlenecks and errors across the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c373e697-674e-457d-b33c-dd18339b5427', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you create a CSS loading spinner animation?', N'Fresher', N'Key points: - border-radius: 50% makes the element a circle. - Only the border-top-color is visually distinct, creating the spinner effect. - animation-iteration-count: infinite keeps it running continuously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7277f6fc-6d25-4d27-9bb1-dd1937c0b5ef', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do ''Quorum'' settings (R + W > N) guarantee consistency?', N'Senior', N'By setting the number of nodes participating in a read (R) and write (W) such that their sum exceeds the total replication factor (N), the system ensures that at least one node in the read set has the most recent update. This overlap forces the coordinator to see the latest version, providing strong consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2816978c-2fce-4372-a66d-dd1c5435d9b2', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Why is Quarkus considered a strong candidate for modernizing monoliths?', N'Senior', N'Quarkus allows for a gradual transition to microservices by supporting both traditional imperative code and modern reactive paradigms. Its ability to run on standard JVMs while offering the option to switch to native compilation makes it flexible for teams wanting to improve performance without a total architectural rewrite.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e946743c-1c4b-4959-b909-dd1d129fed89', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the trade-offs of using ''Content-Type'' negotiation versus specific URL endpoints for different response formats?', N'Senior', N'Content negotiation follows the principle of identifying a resource by a single URI, which is cleaner for REST purists but can be difficult to test in browser-based tools. Specific URL endpoints (e.g., /resource.json) are easier to navigate and cache, but they violate RESTful resource identification principles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd94f21a-a2f5-4ae5-9e40-dd1eba765a68', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Why is the separation of concerns between Providers and Modules essential for maintaining a clean architecture in large NestJS applications?', N'Senior', N'Modules act as logical boundaries that encapsulate related providers and controllers, preventing the ''Big Ball of Mud'' anti-pattern. By strictly managing exports and imports, developers can enforce domain boundaries, reduce circular dependencies, and improve the overall maintainability and modularity of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9105d0d-b839-4b48-81b5-dd205bdf4f9d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the properties of the Intl object', N'Intern', N'Below are the list of properties available on the Intl object, 1. Collator: These are the objects that enable language-sensitive string comparison. 2. DateTimeFormat: These are the objects that enable language-sensitive date and time formatting. 3. ListFormat: These are the objects that enable language-sensitive list formatting. 4. NumberFormat: Objects that enable language-sensitive number formatting. 5. PluralRules: Objects that enable plural-sensitive formatting and language-specific rules for plurals. 6. RelativeTimeFormat: Objects that enable language-sensitive relative time formatting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eb6c178-f7ef-4dce-854a-dd23812d0e25', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do ''Materialized Views'' provide denormalization, and what are the performance trade-offs?', N'Senior', N'Materialized Views automatically maintain an alternative view of the base table data, allowing for different partition keys and clustering columns. While they simplify querying, they introduce significant write amplification and can cause performance issues if the base table experiences high update volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4883830-8c88-4a14-8107-dd25dbd56ebc', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket ensure thread safety for shared state?', N'Middle', N'Rocket requires managed state to implement the Send and Sync traits, ensuring it can be safely shared across threads. Because Rocket runs in a multi-threaded async environment, developers must wrap shared data in synchronization primitives like Mutex or RwLock if modification is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d12dc02-67d4-4e0b-8834-dd2b8440ce0c', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the possible ways to provide transitions?', N'Intern', N'There are many ways Vue provides transition effects when items are inserted, updated, or removed from the DOM. Below are the possible ways, 1. Automatically apply classes for CSS transitions and animations 2. Integrate 3rd-party CSS animation libraries. For example, Animate.css 3. Use JavaScript to directly manipulate the DOM during transition hooks 4. Integrate 3rd-party JavaScript animation libraries. For example, Velocity.js', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f45d287-5f97-4e41-be03-dd2dbd27ce73', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the significance of the ''GraalVM'' support in Micronaut?', N'Junior', N'Micronaut is designed to be compatible with GraalVM Native Image, which compiles Java code into a standalone executable. Because Micronaut uses compile-time dependency injection and introspection, it avoids the reflection-heavy code that typically breaks native image compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaaec2e2-abf7-40b2-a02a-dd2dd90fbfd7', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are assigned a task you have never seen before, what is your first step?', N'Intern', N'My first step is to break the task down into smaller, manageable sub-components and identify the core objective. I would then research the underlying concepts or documentation to understand what tools or processes are required to achieve the goal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ee59001-abce-4c37-8b7a-dd319b9ff76f', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Why is it recommended to use a flat naming convention for resources?', N'Middle', N'Flat naming conventions are easier to maintain and understand, reducing complexity in URL routing. Deeply nested resources often reflect internal database structures and can lead to overly complicated endpoints that are hard to navigate for clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26ee376d-3c0b-446e-a9d0-dd3308203611', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage HTTP status codes?', N'Fresher', N'Hono provides built-in methods on the context object to set the status of a response. It also provides helper functions for common status codes, making it easy to send responses like 200 OK or 404 Not Found.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a8a76ee-9d92-438b-a9b4-dd35334bf585', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between MySQL and NoSQL?', N'Intern', N'MySQL is a relational database that uses structured tables with predefined schemas. NoSQL databases are non-relational and are designed to handle unstructured or semi-structured data, often offering more flexibility in data modeling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'adcdaf2e-7b9f-4e32-a66d-dd390740b59e', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the trade-offs of ''Sharding'' a database.', N'Senior', N'Sharding increases write throughput and storage capacity by partitioning data across multiple nodes, but it introduces significant operational complexity regarding re-balancing, cross-shard queries, and join operations. It should only be used when vertical scaling limits are reached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e5e29f96-b408-41b1-b286-dd3c8bc905b2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the trade-offs between using declaration files (.d.ts) versus native TypeScript source files in a monorepo architecture.', N'Senior', N'Declaration files decouple the API contract from implementation details, allowing for faster build times and smaller packages. However, they introduce a maintenance burden where the contract can drift from the implementation, whereas native source files ensure synchronization but may increase build complexity across package boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'305a6f41-d01d-4273-9d46-dd4102eed2d5', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do I find undefined g++ symbols builtinnew or purevirtual?', N'Fresher', N'To dynamically load g++ extension modules, you must: Recompile Python Re-link it using g++ (change LINKCC in the python Modules Makefile) Link your extension module using g++ (e.g., "g++ -shared -o mymodule.so mymodule.o").', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59c813a3-1576-4a19-ae97-dd46ae624007', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the ''Query Cache'' (deprecated in newer versions) impact performance, and why was it removed?', N'Senior', N'The query cache stored result sets for identical queries, which provided speed for read-heavy workloads. It was removed because the global mutex required to manage the cache created massive contention in multi-core systems, often negating any performance benefits it provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'877d1e48-f632-441e-868d-dd49417ed987', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle navigation errors?', N'Intern', N'SvelteKit provides a special +error.svelte file that you can create to catch and display errors when a page fails to load or when a user visits a non-existent route. This prevents the user from seeing a blank screen and provides a better feedback loop.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abce525f-81d9-4675-890d-dd49557e154c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is a Database Migration?', N'Intern', N'A migration is a way to keep a database schema in sync with the application''s data model as it evolves. It allows developers to version control the database structure and apply changes incrementally in a reliable way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ccf400a-7b72-4f8b-96f6-dd4a2b3fad8b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the main benefit of Axum''s ''macro-free'' approach?', N'Intern', N'The main benefit is improved compile times and easier debugging, as there are no hidden code generation processes. It also results in clearer error messages when something goes wrong during the development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd25f49d-268b-42ce-a912-dd4b422e493d', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between an ''App'' and a ''Router'' in Litestar?', N'Junior', N'An App is the root instance that manages the entire lifecycle of the server and global configurations. A Router is a modular sub-component used to organize related endpoints, which can then be mounted onto the main App.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9e2cdb3-737c-4025-8beb-dd4d1e682bca', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is a route handler in Hono?', N'Intern', N'A route handler is a function that executes when a request matches a specific route definition. Its primary purpose is to process the request and return a response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86fa43db-d0d9-4d14-9f8d-dd4f7d73eb49', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is a native executable in Quarkus?', N'Intern', N'A native executable is a self-contained binary file produced by compiling Java code with GraalVM. It does not require a traditional Java Virtual Machine to run, as it includes the necessary minimal runtime dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22fc3592-7b58-468c-abbf-dd522dd3017d', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the ''Circuit Breaker'' pattern and its role in fault tolerance.', N'Senior', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail, such as a timed-out remote service call. It switches to an ''open'' state to fail fast, giving the downstream system time to recover and preventing resource exhaustion in the calling service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab826493-6ae7-44b2-86d4-dd533e37f949', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the mechanics of Ruby''s method lookup path and how prepending differs from including a module.', N'Senior', N'Ruby uses a linear ancestor chain to resolve method calls. When a module is included, it is inserted into the chain after the class itself, whereas prepending inserts the module before the class, allowing the module''s methods to override those defined in the class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90c753ab-73b3-4d14-9159-dd550cfe074b', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the implications of having a single global store versus multiple store slices in a large-scale enterprise application?', N'Senior', N'Redux is architecturally designed around a single store, which simplifies cross-component communication and state synchronization. Attempting to use multiple stores introduces complexity in coordination and violates the fundamental Redux principle that state should be centralized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e300a8-24d7-425f-a783-dd558feff7b1', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are the advantages and disadvantages of using a Columnar storage format for analytical queries?', N'Senior', N'Columnar storage is highly efficient for analytical workloads because it only reads the columns requested, reducing I/O and enabling better compression. However, it is poorly suited for transactional workloads that require frequent row-level inserts or updates, as these operations require rewriting large portions of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f13102f8-aeea-4baa-a681-dd56cee20da0', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the difference between DELETE and TRUNCATE in PostgreSQL.', N'Junior', N'DELETE is a DML operation that removes rows one by one and can be filtered with a WHERE clause, allowing for rollbacks. TRUNCATE is a DDL operation that quickly removes all rows from a table by resetting the storage, which is faster but generally cannot be undone in the same way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'940bfdbf-600b-4fcc-a51f-dd584a9c1c3d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you are struggling to understand a complex piece of legacy code, what is your process for gaining clarity?', N'Junior', N'I would start by reading existing documentation and checking for related tests to understand the intended behavior of the module. If that is insufficient, I would use debugging tools to step through the execution flow and add descriptive comments or small refactors to improve readability as I go.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7481bf03-7b19-42d8-a9fc-dd5895a09df5', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the difference between @apply and writing utility classes in HTML?', N'Junior', N'The @apply directive allows you to bundle multiple utility classes into a single custom CSS class. While useful for reducing markup clutter, it should be used sparingly as it can lead back to the maintenance problems of traditional CSS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'326f70ee-4e8d-4646-ba93-dd59673750c0', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the advantage of using Alpine''s declarative approach over imperative DOM manipulation?', N'Middle', N'The declarative approach makes the code easier to read and maintain because the behavior is explicitly defined within the HTML markup. It eliminates the need to manually query the DOM and update elements, which reduces the surface area for bugs and state synchronization errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfc80935-5789-4c50-998a-dd655479f067', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is heap', N'Intern', N'Heap(Or memory heap) is the memory location where objects are stored when we define variables. i.e, This is the place where all the memory allocations and de-allocation take place. Both heap and call-stack are two containers of JS runtime. Whenever runtime comes across variables and function declarations in the code it stores them in the Heap. !Screenshot', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'777e600b-5f12-45a5-b07d-dd6602a51b5f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for estimating the time required for a task?', N'Junior', N'I break the task down into smaller, manageable units and estimate the effort for each based on my current understanding. I also add a buffer for unforeseen issues or testing, and I compare my estimate against similar tasks I have completed in the past to ensure accuracy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a4f61ce-0b38-400c-800a-dd66a5c11c34', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you determine if a feature is worth adding to a product?', N'Intern', N'You evaluate a feature based on user demand, alignment with product goals, and the potential impact on system complexity. If the effort to maintain the feature outweighs the value it provides, it should be reconsidered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'700eed21-161c-4125-8795-dd66e6b9465c', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a dependency graph?', N'Intern', N'A dependency graph is a visual or logical representation of how modules in an application relate to one another. Webpack constructs this graph by recursively traversing every module to understand the import and export relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f058acc6-0ddc-4f88-9c35-dd675716a569', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle ''Namespace'' limitations in modern versions?', N'Senior', N'Earlier versions of MongoDB had strict limits on the number of collections and indexes due to namespace file constraints. Modern versions using WiredTiger have removed these fixed limits, allowing for a much larger number of collections and indexes, constrained only by available system resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcbd7592-e76c-4c20-8607-dd67b9b46727', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you reflect on a completed task to improve your future performance?', N'Intern', N'I conduct a brief self-review to identify what went well and what could have been handled more efficiently. I think about the challenges I faced and how I might resolve them faster or more effectively if I encountered them again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6d8017d-e103-4960-b53d-dd6888c590e9', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the difference between synchronous and asynchronous middleware, and why are both supported?', N'Middle', N'Synchronous middleware executes immediately and is useful for simple operations like setting headers or modifying request properties. Asynchronous middleware is necessary for I/O-bound tasks like database queries or file system access, ensuring the event loop remains unblocked during these operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f24ed11f-16f1-4b65-aeba-dd688e1834b0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Is it possible to perform color manipulation in Sass?', N'Junior', N'Yes, Sass provides built-in color functions that allow you to lighten, darken, saturate, or shift the hue of colors dynamically. This is helpful for creating hover states or secondary color variants based on a primary brand color.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d79412c-a627-4465-801e-dd689b81bee3', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Why is Shadow DOM ''closed'' mode generally discouraged in Lit components?', N'Middle', N'Closed mode prevents the host application from accessing the component''s internal DOM structure, which makes testing, debugging, and accessibility implementations much harder. Open mode is preferred as it respects the standard Web Component design principles for interoperability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c6da003-b716-437d-ba0a-dd6d74b85df5', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of packages in R?', N'Intern', N'Packages are collections of functions, data, and compiled code that extend the capabilities of the base R installation. They allow users to access specialized tools for tasks such as advanced visualization, machine learning, and data manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
