INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa52d319-bb12-4a83-8a3c-dd6f73303e0c', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Vert.x and how is it used in Quarkus?', N'Fresher', N'Vert.x is a toolkit for building reactive, non-blocking applications on the JVM. Quarkus uses Vert.x as its underlying engine to handle asynchronous I/O and networking, allowing it to remain highly performant under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'287133b4-46bf-45f0-b243-dd6faefb2168', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you define path parameters in an Axum route?', N'Junior', N'Path parameters are defined using a colon prefix in the route string, such as /users/:id. Axum then allows you to use the Path extractor in your handler to access the specific value captured in that part of the URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b225aa46-3900-4dd3-a01c-dd70d52e91dc', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when choosing between microservices and a monolithic architecture?', N'Middle', N'A monolith is easier to deploy and test during early stages but can become difficult to scale and maintain as the team grows. Microservices provide better team autonomy and independent scalability but introduce significant operational overhead regarding inter-service communication, distributed tracing, and data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'44ad47d3-78c4-438b-860e-dd710780c266', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What does the @Controller annotation do?', N'Intern', N'The @Controller annotation marks a class as a request handler that exposes HTTP endpoints. It allows the framework to automatically detect the class and register its methods as routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23349cca-0092-4140-b89f-dd71429d8dba', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the trade-offs of using Alpine.js for complex state management?', N'Middle', N'Alpine.js excels at local UI state, but it lacks a built-in architecture for complex global state management found in frameworks like Redux or Pinia. For large-scale apps, managing shared state across distant components can become difficult, requiring external stores or custom event-based patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4acfac1-bff8-4676-8dfa-dd719d96b614', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it important to use a minified version of jQuery in production?', N'Intern', N'A minified version of jQuery removes unnecessary spaces, comments, and shortened variable names to reduce the file size. Smaller file sizes lead to faster page load times for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53f7d02a-01b3-4ced-9b78-dd733e67bfea', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the difference between the ''public'' directory and assets imported in source code?', N'Junior', N'Files in the public directory are served at the root path and are copied as-is to the build folder without processing. Assets imported in source code are processed by Vite, which may include fingerprinting, minification, or URL path updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77efe6bd-4bef-45e8-bd61-dd74f5e35b2d', N'075b8862-431c-4678-9767-f55359758a4a', N'How does the ''key'' attribute affect Vue''s diffing algorithm?', N'Middle', N'The key attribute helps Vue uniquely identify elements in a list. When the list order changes, Vue uses these keys to decide whether to reuse and reorder existing elements or destroy and recreate them, which is essential for maintaining component state during list updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73fc7248-88d8-41b7-810c-dd75ddf0b174', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle ''Adopted StyleSheets'' to optimize memory usage across multiple component instances?', N'Senior', N'Lit utilizes the Adopted StyleSheets API to share a single CSSStyleSheet instance across multiple Shadow Roots. This drastically reduces memory overhead because the browser parses the CSS once and shares the resulting style object rather than duplicating it for every component instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f9d10b9-bcf2-458b-a178-dd79926bb009', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How can I pass optional or keyword parameters from one function to another?', N'Fresher', N'Collect the arguments using the * and specifier in the function''s parameter list; this gives you the positional arguments as a tuple and the keyword arguments as a dictionary. You can then pass these arguments when calling another function by using * and : In the unlikely case that you care about Python versions older than 2.0, use ''apply'':', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9b7dc7b-f036-4942-9af1-dd7a0aab36aa', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate something impossible to count, what approach do you take?', N'Intern', N'I use Fermi estimation, where I decompose the problem into smaller, guessable variables. I make reasonable assumptions for these variables and combine them mathematically to reach an order-of-magnitude estimate. The goal is to provide a logical framework rather than an exact, impossible-to-verify number.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38a38083-2a39-40d0-bec8-dd7b3b2c9330', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the benefit of using Axum''s ''Router::nest'' method?', N'Middle', N'The nest method allows for the modular organization of code by grouping related routes under a common URL prefix. This promotes better maintainability and code structure in large-scale applications with many endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8d67850-ec3f-4142-b493-dd7d02b99095', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How can you implement server-side rendering (SSR) for Lit components?', N'Senior', N'Lit supports SSR by rendering component templates to static HTML strings on the server, which are then hydrated on the client. This improves perceived performance and SEO, although it requires careful management of state serialization to ensure the client-side state matches the server-generated markup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72d83748-7d3a-461a-a944-dd7f64de8eb1', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the architectural role of Middleware in Next.js?', N'Senior', N'Middleware acts as a lightweight edge-based interceptor that executes before a request is completed. It is primarily used for authentication, geo-blocking, A/B testing, and URL rewriting, allowing logic to run close to the user for minimal latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cacdbe30-ccb6-4af2-89e1-dd821d59408d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the EXPLAIN statement in MySQL?', N'Junior', N'EXPLAIN provides information about how the MySQL optimizer executes a specific query. It shows the order of joins, which indexes were used, and how many rows were scanned, helping developers identify performance bottlenecks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a8e67f2-e439-408d-85f8-dd8637c6bdae', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the impact of the V8''s ''deoptimization'' process on application performance.', N'Senior', N'Deoptimization occurs when the engine''s speculative optimizations—such as assumptions about object shapes or types—are invalidated by runtime changes. This forces the engine to discard highly optimized machine code and revert to the slower interpreter or baseline compiler, causing significant latency spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
