INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c19c7bd5-c9f3-4c2e-9f26-dd8c9c982297', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you maintain code quality in a Symfony project?', N'Middle', N'Code quality is maintained through strict use of type-hinting, automated unit and integration tests using PHPUnit, static analysis tools like PHPStan, and adhering to Symfony coding standards. Leveraging Dependency Injection also ensures that components remain loosely coupled and easily testable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
