INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acf4a068-c9da-4925-a78e-dd8e7649adc0', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the ''storage'' directory used for?', N'Fresher', N'The storage directory is used to store logs, compiled Blade templates, file uploads, and other framework-generated files. It is essential that the web server has write permissions to this directory for the application to function correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'479608b2-65eb-434d-a6ef-dd8f5ef9a680', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of using the ''next/link'' component instead of a standard HTML anchor tag?', N'Junior', N'The ''next/link'' component enables client-side transitions between routes without a full page reload. It also automatically prefetches the linked page in the background, making navigation feel instantaneous to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7693654-9bc7-433d-ac85-dd8f999aa128', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain parameter-passing mechanism in python?', N'Fresher', N'- To pass its parameters to a function, Python uses pass-by-reference. If you change a parameter within a function, the change reflects in the calling function. This is its default behavior. - However, when we pass literal arguments like strings, numbers, or tuples, they pass by value. This is because they are immutable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63e41672-980e-4aad-97af-dd8ff27c8a99', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the decision to build a custom solution versus purchasing an off-the-shelf product?', N'Senior', N'I buy when the solution is not a core differentiator for the business and the vendor provides high value at a reasonable cost. I build when the custom solution provides a unique competitive advantage or when existing vendor offerings fail to meet specific performance or integration requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b67184d-037e-4a1e-8d14-dd926f47f54d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the MVC architectural pattern in Ruby on Rails?', N'Intern', N'MVC stands for Model-View-Controller. The Model manages data and business logic, the View handles the user interface display, and the Controller acts as the intermediary that processes incoming requests and directs data to the appropriate model or view.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e36abd7a-89bd-4e89-aff1-dd92d4828d8e', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Explain the concept of ''structural typing'' in Scala.', N'Middle', N'Structural typing allows a method to accept any object that provides a specific set of methods, regardless of the object''s explicit class hierarchy. This provides flexibility but comes at a performance cost due to the use of reflection at runtime to verify the required signatures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b642037-f8a2-4cbc-a66e-dd93648e30a6', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Does FastAPI support environment variables?', N'Intern', N'Yes, FastAPI often uses Pydantic''s settings management features to load environment variables into configuration objects. This is a secure and standard practice for handling sensitive data like database URLs or API keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f44655ca-1d19-4ea5-b2c2-dd9439d72e58', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is rate limiting important from a security perspective?', N'Middle', N'Rate limiting protects systems from denial-of-service (DoS) attacks and brute-force attempts by restricting the number of requests a user can make within a certain timeframe. It ensures system availability and prevents malicious actors from overwhelming the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8a5ceb9-36b9-4735-b9a3-dd95e6af50b7', N'954a0331-deff-4399-b588-96f39fec001d', N'Describe the difference between an Angular Interceptor and a Service.', N'Middle', N'Services are general-purpose classes used for sharing data and business logic across the application. Interceptors are a specific type of service that specifically hooks into the HttpClient pipeline, allowing you to globally transform or inspect outgoing requests and incoming responses, such as adding authorization headers or handling errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2074af2-ac05-46c6-98d9-dd9629fa7576', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What does it mean that Vite is ''unbundled'' in development?', N'Intern', N'It means that during development, Vite does not concatenate all your source files into a single large bundle. Instead, it serves them as individual modules, which allows the server to start instantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2e8e02e-c2c0-485b-b690-dd99d4e58665', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of an HTTP Method in Fiber?', N'Fresher', N'HTTP methods like GET, POST, PUT, and DELETE define the action to be performed on a resource. Fiber uses these methods to determine which handler function should be executed for a specific route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02cc48d4-1983-406d-99bd-dd9a385343c7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a list and a set?', N'Intern', N'A list is an ordered collection that allows duplicate elements. A set is an unordered collection that does not allow duplicate elements and is optimized for membership testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b4145852-8338-4a82-abee-dd9f4138c4ec', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is WSGI in the context of Flask?', N'Intern', N'WSGI stands for Web Server Gateway Interface. It is a standard specification that describes how a web server communicates with a Python web application, allowing Flask to interact with servers like Gunicorn or uWSGI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'008a8c8f-a982-4b1c-951a-dda16583fc28', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is it recommended to use DTOs or Serializers in AdonisJS instead of exposing database models directly?', N'Middle', N'Using DTOs or Serializers provides an abstraction layer that prevents sensitive database fields from being exposed in API responses. It also allows the internal database schema to evolve independently from the external API contract, improving long-term maintainability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'033de8bb-d440-4b30-98ae-dda20018fcc7', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When tasked with estimating a feature with no clear documentation, how do you proceed?', N'Middle', N'I would dedicate time to code exploration and analysis of the existing system behavior to map out the dependencies and constraints. I would treat this discovery phase as a formal part of the estimation process, ensuring that the time spent understanding the system is explicitly accounted for.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'542bb9fa-6147-40b1-9e6f-dda3b43385bb', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of ''tracked'' properties in Ember?', N'Intern', N'Tracked properties are variables that Ember watches for changes. When a tracked property is updated, Ember automatically triggers a re-render of any part of the UI that depends on that property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99997ef6-998c-49cb-8a7e-dda72257a446', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the spread operator and how is it used?', N'Intern', N'The spread operator, represented by three dots (...), is used in JavaScript to expand iterable objects like arrays or strings into individual elements. It can also be used to spread object properties. For example, you can use it to combine arrays, copy arrays, or pass array elements as arguments to a function. ↑ &nbsp;&nbsp;/&nbsp;&nbsp; ✏️ Edit answer', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'deb97c7f-995e-49a8-b19b-dda8bf1456d4', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What happens if you don''t return from a Fiber handler?', N'Junior', N'In Go, functions continue execution until they finish. If you don''t return, the code below the handler logic will still execute, which can lead to unexpected behavior or multiple response attempts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2924acf-b563-4333-8d5d-dda94302ed53', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Describe the benefits of using ''LitElement'' over raw Web Components.', N'Senior', N'LitElement provides a high-level abstraction that simplifies attribute-to-property mapping, efficient rendering, and lifecycle management. It eliminates the boilerplate associated with standard Web Component APIs while offering optimized performance via its declarative templating system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
