INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fd645ed-a828-4860-9f35-ddafd3491875', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Why is ''Module#prepend'' considered superior to ''alias_method'' chains for method wrapping?', N'Senior', N'Prepend modifies the inheritance chain, allowing the prepended module to call ''super'' to trigger the original implementation cleanly. Alias_method chains, by contrast, create brittle method aliases that are harder to track and can lead to infinite loops if not implemented with extreme caution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73cdb80f-c617-4b7b-8730-ddb1721b0e62', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are API routes in SvelteKit?', N'Intern', N'API routes are defined using +server.js files. They allow you to create custom endpoints that handle HTTP requests like GET, POST, or DELETE, functioning like a backend API within your frontend project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c9cf369-b96c-40d0-b2c6-ddb4cda560f4', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does reactivity work in Alpine.js?', N'Fresher', N'Alpine.js uses a reactivity system that tracks changes to data properties defined in x-data. When a property changes, Alpine automatically detects which parts of the DOM are dependent on that data and updates them efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51f08144-df9a-4c84-a138-ddb55f3a9d9c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What factors should influence the choice between a document database and a key-value store?', N'Middle', N'Key-value stores are best for simple, high-speed lookups where data structure is irrelevant to the database engine. Document databases are preferred when you need to perform queries based on the internal fields of the stored objects or maintain relationships.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72fa616f-e51b-4c78-b1de-ddb5a58a980d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the primary benefit of modular design in managing future trade-offs?', N'Intern', N'Modular design allows components to be swapped or upgraded independently, reducing the ripple effect of changes. It makes the system more flexible, allowing you to make different trade-offs in the future without having to rewrite the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd6d64b11-a8f1-4edd-b86c-ddb709902b34', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Describe the impact of Django''s middleware stack on request latency.', N'Senior', N'Every middleware layer adds processing overhead as it wraps the request and response cycle, increasing the total execution time for every request. To mitigate latency, middleware should be kept to a minimum, and heavy operations should be deferred to asynchronous tasks or processed post-response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd686cc52-ed35-4fda-861d-ddb8dba649cc', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the trade-off between using Echo''s built-in static file serving and serving files through a reverse proxy like Nginx?', N'Senior', N'Serving files through Echo is convenient for small projects, but it wastes application-level resources for a task that Nginx can handle much more efficiently. Offloading static assets to Nginx or a CDN improves performance by reducing the load on the Go runtime and utilizing highly optimized delivery mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a228819-38f6-4215-9c69-ddb8f09c858f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is a dictionary in Python?', N'Intern', N'The built-in datatypes in Python is called dictionary. It defines one-to-one relationship between keys and values. Dictionaries contain pair of keys and their corresponding values. Dictionaries are indexed by keys. Let''s take an example: The following example contains some keys. Country, Capital & PM. Their corresponding values are India, Delhi and Modi respectively. dict={''Country'':''India'',''Capital'':''Delhi'',''PM'':''Modi''} print dict[Country] 3 A dictionary is mutable, and we can also use a comprehension to create it. {25: 5, 16: 4, 9: 3, 4: 2, 1: 1}', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6c6c3ff-aa4c-435f-8732-ddbda4001258', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the significance of the global environment in R?', N'Intern', N'The global environment is the main workspace where all user-created objects are stored. When you create a variable at the command line, it is placed in the global environment so it can be accessed by any function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b0e6d38-2853-4997-9e61-ddbef557069d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the environment variable PORT commonly used for in Express?', N'Fresher', N'The PORT environment variable is used to define the port number on which the Express server should listen. It allows for flexibility, letting the server run on different ports in development versus production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66076fd8-66ac-4de4-b074-ddc00f4b5bb4', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Are SolidJS components re-executed like React components?', N'Fresher', N'No, SolidJS components are executed only once when they are first mounted. The reactivity system handles updates at the element or attribute level, so the component function logic does not run repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64707d7e-e62b-4bd1-84c5-ddc0b969775f', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you manage configuration drift across large-scale infrastructure environments?', N'Senior', N'I implement Infrastructure as Code (IaC) with immutable infrastructure patterns, ensuring that no manual changes occur on live nodes. I use automated drift detection tools that continuously reconcile the current state against the desired state defined in version-controlled repositories.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b108f26-0015-47ba-b7e9-ddc163191f35', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is logging and monitoring considered a critical component of security architecture?', N'Middle', N'Logging and monitoring provide visibility into system activity, which is essential for detecting anomalies, investigating security incidents, and performing forensics. Without robust telemetry, it is nearly impossible to determine the scope of a breach or identify the root cause of unauthorized access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb01c856-80b1-447c-bb19-ddc2c3db0725', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How do you ensure data consistency in a system using asynchronous messaging?', N'Middle', N'Consistency is managed through patterns like the Saga pattern, where distributed transactions are broken into a series of local transactions coordinated via events. If one step fails, compensating actions are triggered to revert the changes made by previous steps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aca7b816-4a78-420c-b683-ddc496a326f1', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why are NoSQL databases often used for Big Data?', N'Intern', N'NoSQL databases are designed to handle high volumes, high velocity, and high variety of data. Their ability to scale horizontally and store unstructured data makes them perfect for processing massive datasets that do not fit into relational structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95f913fd-1498-4f7b-810a-ddc4b6301ef1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are Pure Components?', N'Intern', N'Pure components are the components which render the same output for the same state and props. In function components, you can achieve these pure components through memoized React.memo() API wrapping around the component. This API prevents unnecessary re-renders by comparing the previous props and new props using shallow comparison. So it will be helpful for performance optimizations. But at the same time, it won''t compare the previous state with the current state because function component itself prevents the unnecessary rendering by default when you set the same state again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4ed56d7-d886-41d6-acb9-ddc8443643c3', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the common tools used to debug Redux?', N'Fresher', N'The most common tool is the Redux DevTools extension. It allows developers to inspect every action dispatched, view the state tree, and even travel back and forth in time to see how the state evolved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54565767-ca33-4997-8363-ddc8dfb1be85', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between an interpreter and a compiler in the context of R?', N'Fresher', N'R is primarily an interpreted language, meaning the code is executed line-by-line by the R interpreter rather than being compiled into machine code before execution. This makes R highly interactive and convenient for exploratory data analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c31bbfa4-0222-4629-affb-ddc98181e6e3', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What happens if you use variables defined inside a partial?', N'Junior', N'If you import that partial into your main file, the variables become available for use in that scope. This allows you to centralize configuration settings like themes or layout constants in a single file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5d6dee6-2809-4c60-8b9f-ddcbe5004e77', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the favicon link?', N'Intern', N'A favicon is a small icon displayed in the browser tab or bookmark bar to represent the website. It is defined in the head section of the HTML document using a link tag with a specific relation attribute.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50bcacf7-8643-4555-b5e5-ddccfedf325e', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does ''Data Locality'' affect performance in sharded databases?', N'Senior', N'Data locality ensures that related data is stored on the same shard, which minimizes cross-node communication and network latency for queries. Poor data locality forces the database to perform ''scatter-gather'' operations, where the coordinator must wait for responses from multiple shards, significantly increasing query execution time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3b50669-4f04-42a3-a2e5-ddcf5a742534', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the security risk associated with jQuery''s HTML string parsing capabilities?', N'Senior', N'jQuery''s methods for creating elements from HTML strings can easily lead to Cross-Site Scripting (XSS) vulnerabilities if user input is not sanitized properly. Modern frameworks provide built-in protection against common XSS vectors by using safer DOM APIs or templating languages that auto-escape output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab7394fe-fd4b-4aa1-92f5-ddd08630b0f5', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the performance considerations for using RequestAnimationFrame versus SetTimeout for animations?', N'Senior', N'RequestAnimationFrame synchronizes with the browser''s display refresh rate, ensuring smooth animations and pausing automatically when the tab is inactive. SetTimeout is not frame-aware, often leading to visual stuttering or wasted CPU cycles when the browser is not ready to paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98517323-060a-42f2-a6a1-ddd11b150ac5', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What are ''Qwik Symbols''?', N'Intern', N'Qwik Symbols are references to functions or components that the framework can lazy-load independently. They allow the framework to keep track of where code is located so it can be fetched from the server only when needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1a0783b-3627-409e-8daf-ddd152bd7f05', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the primary purpose of using Redux?', N'Intern', N'The primary purpose is to provide a single source of truth for an application''s state. It makes state management predictable and easier to debug by ensuring that state changes happen in a consistent, traceable way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3302c58b-66ba-4dee-af20-ddd1d8c63051', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Discuss the scalability of Litestar''s middleware implementation.', N'Senior', N'Litestar''s middleware is designed to be highly granular, allowing developers to apply specific logic to subsets of routes or controllers. This enables fine-tuned performance optimizations, such as only applying compute-heavy authentication middleware to sensitive endpoints while bypassing it for public ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1628c2d-f5db-497a-8d33-ddd27b6a3e48', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Is Qwik suitable for beginners?', N'Fresher', N'Qwik is accessible for beginners as it uses familiar concepts like components and reactivity. While the underlying resumability model is advanced, developers can build applications using standard patterns without needing to understand the complex serialization occurring in the background.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a02215f-8688-49f1-929e-ddd48d630e07', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is idempotency critical in an event-driven microservices architecture?', N'Senior', N'In distributed systems, network retries often lead to duplicate event delivery. Services must be idempotent to ensure that processing the same event multiple times does not result in incorrect state changes, typically by using unique message IDs and state checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3943ab01-15c7-4f38-ab7f-ddded4f336c2', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the function of the ''FFI'' (Foreign Function Interface) in Dart''s architecture?', N'Senior', N'FFI allows Dart code to call C-based native libraries directly. It provides a high-performance bridge to hardware-specific or system-level APIs by mapping native memory layouts to Dart objects, bypassing the need for complex platform channels.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd66f1bc-4e0a-46cd-9623-dddef923ec7c', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the performance implications of deep nesting in Sass?', N'Middle', N'Deep nesting leads to overly specific CSS selectors, which can make styles harder to override and negatively impact browser rendering performance. It also makes the generated CSS harder to debug and often results in bloated file sizes due to long, redundant selector chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cdc6de5-473c-4580-a14b-dddf94bd9a9f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the function of the ''virtual'' keyword?', N'Intern', N'The virtual keyword is used to declare a method or property in a base class that can be overridden by a derived class. It allows for polymorphism, enabling a base class reference to execute the version of the method defined in the derived class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ad86012-49b2-47bb-bfc1-dddfae591897', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the difference between an Orchestrator and a Choreography in a Saga?', N'Middle', N'In orchestration, a centralized controller manages the workflow and tells services what to do. In choreography, each service emits events and listens for events from others, making the process more decentralized but harder to monitor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c487f3e5-5ef6-4509-ac74-dde05d7a5b2a', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is it difficult to implement true asynchronous programming within the native PHP engine?', N'Senior', N'The core of PHP was designed for a synchronous, request-response lifecycle where execution is expected to be linear. Introducing true asynchronous concurrency requires non-blocking I/O support throughout the entire engine and standard library, which contradicts the fundamental design of the Zend VM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48cdc246-3787-4d4d-a283-dde1876a564a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How are exceptions handled in AdonisJS?', N'Fresher', N'AdonisJS includes a global exception handler that catches errors thrown during the request cycle. It allows developers to define custom logic for how specific errors should be displayed to the user or logged for debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87a0bdb3-433d-423d-9621-dde1c122e4bc', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''unknown'' type?', N'Fresher', N'The ''unknown'' type is a type-safe counterpart to ''any'' that requires the developer to perform type checking before performing operations on the value. It prevents accidents by forcing you to verify the type of the variable before using it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e228c4b9-b010-44a5-99a2-dde1ddd6e822', N'954a0331-deff-4399-b588-96f39fec001d', N'What are pipes?', N'Intern', N'Pipes are simple functions that use template expressions to accept data as input and transform it into a desired output. For example, let us take a pipe to transform a component''s birthday property into a human-friendly date using date pipe.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bc5443b-dde1-4e8c-96e1-dde7c7c31e83', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of a ''Canary Release'' in reducing the impact of production bugs?', N'Middle', N'A canary release allows you to deploy the new version to a small subset of users, limiting the blast radius of any potential bugs. By monitoring the performance and error rates of this group compared to the baseline, you can catch regressions early without affecting the entire user base. This significantly lowers the risk and makes troubleshooting more manageable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59d7d177-9f05-44f8-a8d2-dde9de470231', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is CSRF protection in Symfony?', N'Fresher', N'CSRF protection is a security feature that prevents malicious sites from performing actions on behalf of an authenticated user. Symfony forms automatically include a hidden token that verifies the request originated from the legitimate form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'632853f7-7523-49bf-adb4-ddee82282b37', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the ''using'' statement in C#?', N'Intern', N'The using statement is primarily used to ensure that resources like file handles or database connections are disposed of correctly after use. It automatically calls the dispose method on an object that implements the IDisposable interface once the scope of the statement ends.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5491433c-acf8-4dce-89e6-ddf384f8f48f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is a trampoline function? What is it used for?', N'Intern', N'The trampoline is just a technique to optimize recursion and prevent stack-overflow exceptions in languages that don''t support tail call optimization like Javascript ES5 implementation. However, ES6 will probably have support for tail call optimization. The problem with regular recursion is that every recursive call adds a stack frame to the call stack, which you can visualize as a pyramid of calls. Here is a visualization of calling a factorial function recursively: Here is a visualization of the stack where each vertical dash is a stack frame: The problem is that the stack has limited size, and stacking up these stack frames can overflow the stack. Depending on the stack size, a calculation of a larger factorial would overflow the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad57a61d-355e-45c1-a871-ddf402be18c3', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Does Qwik support standard web standards?', N'Fresher', N'Yes, Qwik is built with web standards in mind. It works within the browser''s native capabilities, making it compatible with standard HTML and CSS practices while providing a modern reactive programming model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1dc6c54-d8b9-4f83-a1a2-ddf4700c84f4', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does the Go compiler not support traditional header files or a preprocessor?', N'Senior', N'The absence of headers and preprocessors minimizes compilation time by eliminating redundant parsing and complex macro expansion. This design decision enforces a clean, dependency-graph-based compilation model that is highly parallelizable and prevents common pitfalls associated with C-style macro metaprogramming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'165b5ec5-4a7a-4a63-b9f9-ddf7651a1070', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'Why might you ask a user for a screenshot or screen recording during a bug report?', N'Intern', N'Visual evidence can capture details that a user might accidentally omit in a written description, such as error codes or specific UI elements. It provides a more accurate representation of the user''s workflow leading to the error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9de7bbc-fcf1-4e2b-bb76-ddf7817343ef', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro’s View Transitions API handle state persistence compared to a standard multi-page application (MPA)?', N'Senior', N'Astro''s View Transitions emulate a single-page application experience by intercepting navigation to swap DOM elements and animate transitions without a full page reload. Unlike a standard MPA where global state is lost on navigation, this approach allows for persistent client-side state and smoother transitions while maintaining the SEO benefits of standard HTML navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db3c1beb-5fd2-402a-b394-ddf786eaa42d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach refactoring a legacy module that lacks unit tests?', N'Middle', N'I start by wrapping the module in integration tests to define its current behavior and ensure no regressions. Then, I perform incremental refactoring, adding unit tests for each small change to slowly increase coverage and maintain stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a97ce192-7067-4f93-bcc1-ddf7d2286fe6', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle estimation when the team''s velocity is highly inconsistent due to external dependencies?', N'Senior', N'I move away from absolute time-based estimates and focus on relative sizing while explicitly mapping external dependencies as risk blocks. By establishing a ''lead time'' metric for these dependencies, I can better forecast delivery dates by treating those blockers as variable inputs rather than fixed constants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d6043b8-726f-482e-90bc-ddf84f3b6833', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Workflow component, and how does it differ from a standard state machine?', N'Senior', N'The Workflow component manages the transition of an object between predefined states based on triggers, providing a central place for business process logic. It differs from a simple state machine by supporting multiple concurrent states, complex transitions, and event listeners for side effects during transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86f12c0d-3582-4960-8331-ddf9d7b10a08', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the Durability property in a database?', N'Junior', N'Durability guarantees that once a transaction has been committed, the changes are permanent and will survive even in the event of a system crash or power failure. This is usually achieved by writing transaction logs to non-volatile storage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e17833b6-effb-42e2-a1b1-ddfe38d6515d', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do controllers help in organizing logic within Lit components?', N'Middle', N'Controllers allow you to extract reusable, stateful logic out of the component class and into standalone objects. This promotes cleaner code, better testability, and the ability to share complex behavior across multiple different component types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'160fb8be-a2b8-4946-89a2-de03c044a3bf', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach a task where you have no prior experience with the required technology or tool?', N'Junior', N'I would begin by reviewing official documentation and looking for established best practices or patterns related to the tool. I would then create a small, isolated proof-of-concept to understand the basic functionality and limitations. If I am still struggling, I would time-box my exploration and ask a senior developer for guidance to ensure I am heading in the right direction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'721d955a-f953-4de4-8324-de064ab66347', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the difference between ''covariant'' and ''contravariant'' types in Dart.', N'Middle', N'Covariance allows a type to be replaced by its subtypes, which is the default behavior for return types in Dart. Contravariance, which is less common in Dart''s type system, would allow a type to be replaced by its supertypes, primarily relevant when dealing with function parameter types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f40d6519-2dc3-4c0a-a4be-de083d2d8f18', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What are ACID properties in database transactions?', N'Junior', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably, maintaining data validity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'148abce6-bb00-43ba-96fa-de0bdf2cf3de', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What should you do if your initial hypothesis for a bug is proven wrong?', N'Junior', N'I would step back, re-evaluate the evidence, and form a new hypothesis based on the new information gained from the failed test. It is common for initial assumptions to be incorrect, and the key is to stay objective and let the data guide the investigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69bce3cb-41b3-41fa-9454-de115dfb5f4b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the purpose of a database index, and when might you use one?', N'Fresher', N'A database index is like an index in a book that allows the system to find data quickly without scanning every row. You would use one on columns that are frequently used in search filters or join conditions to improve query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfec57e8-60bd-426b-88ec-de11e7fc46c4', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do you handle large object storage in NoSQL databases?', N'Middle', N'Storing large blobs directly in a NoSQL database can degrade performance and exceed record size limits. The standard practice is to store the actual file in a dedicated object store and save only the URI or file path reference within the NoSQL database document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'542323d3-9c5a-4f9c-bdd1-de12586f03b5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the concept of ''Covering Index''.', N'Middle', N'A covering index occurs when all the columns required by a query are present within a single index structure. Because the database engine can retrieve all needed data directly from the index tree without looking up the actual table rows, query performance is significantly improved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dba2b730-6546-4870-abf1-de13f01e2bd6', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the Micronaut ''Introduction Advice'' and how does it affect application design?', N'Middle', N'Introduction Advice allows developers to define an interface and have Micronaut provide an implementation at compile time based on annotations. This promotes a design pattern where you declare behavior via interfaces, and the framework automatically manages the boilerplate implementation, reducing the need for manual class generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'205ee935-4167-4f05-acae-de142bf646cf', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle code splitting?', N'Fresher', N'Qwik automatically performs fine-grained code splitting at the component and event listener level. By breaking the application into many small, lazy-loadable chunks, it ensures the browser only downloads the specific code needed for current actions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2c5f829-2fc7-4eb2-a529-de14387cc865', N'4c000000-0000-0000-0000-000000000005', N'Explain the concept of eventual consistency.', N'Middle', N'Eventual consistency is a consistency model where, in the absence of new updates, all accesses to a data item will eventually return the last updated value. It allows for higher availability and partition tolerance by allowing replicas to be out of sync temporarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
