INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c9b8361-4b63-4275-91a1-de1520143fe3', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''firstUpdated'' lifecycle method?', N'Intern', N'The firstUpdated method runs only once after the component''s template is first rendered and added to the DOM. It is useful for initialization tasks that need to run immediately after the first paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0fb3baf-d4db-4ed6-a623-de16b728c8e3', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why does Preact prefer native browser features over custom abstractions?', N'Middle', N'Preact prioritizes native browser features to minimize the library''s footprint and maximize interoperability. By leveraging native APIs, Preact stays lightweight, benefits from future browser performance improvements, and ensures that developers can use standard web development patterns without learning proprietary abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec970e00-d6f0-46fe-913d-de17b033ea0f', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you get the current url with javascript', N'Fresher', N'You can use window.location.href expression to get the current url path and you can use the same expression for updating the URL too. You can also use document.URL for read-only purposes but this solution has issues in FF.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
