INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8669f609-6480-444d-804b-de1a9a5e721d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between an array and a slice in Go?', N'Intern', N'An array has a fixed size defined at the time of creation, whereas a slice is a dynamically sized reference to an underlying array. Slices are used much more frequently in Go because of their flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9e4dc96-e498-47da-b3e2-de1af1575ccc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When faced with a choice between a fast, ''quick-fix'' solution and a robust, time-consuming one, how do you decide?', N'Fresher', N'I consider the long-term goals and the urgency of the project. If the quick fix is only for an immediate emergency and won''t be used long-term, it may be acceptable; otherwise, I choose the robust solution to avoid technical debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba74acdb-b878-4c8a-9b24-de1b7cf584c3', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you create custom RxJS operators?', N'Fresher', N'Creating custom RxJS operators allows you to encapsulate common observable transformation logic for reusability and readability. A custom operator is essentially a function that takes a source observable as input and returns a new observable, typically by applying one or more existing RxJS operators using the pipe method. The most common pattern for a custom operator is a function that returns another function. The outer function can optionally take configuration arguments, and the inner function takes the source observable and returns the transformed observable. Here''s a basic structure: You then use it with the pipe method on an observable: This pattern makes your code cleaner and easier to maintain by abstracting complex observable sequences into single, descriptive functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14f55ee9-e847-4523-8802-de1b832e873a', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle event listeners?', N'Intern', N'SolidJS uses standard HTML event attributes to attach listeners directly to elements. These are handled efficiently by the framework to ensure minimal overhead and consistent behavior across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e638e0c8-eded-4d1c-af50-de1c64bc81c3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is ''Implicit Binding'' discouraged in modern Ember development?', N'Senior', N'Implicit binding creates hidden dependencies between components and controllers, making the codebase difficult to refactor and reason about. Explicitly passing data via arguments makes the contract between components clear and improves the maintainability of the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e978b78-05f0-408f-9b8c-de2200821f9c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What does the ''static'' keyword mean in Java?', N'Junior', N'The static keyword indicates that a variable or method belongs to the class itself rather than any specific instance of that class. Static members are shared across all objects created from that class and can be accessed without creating an instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57e2cf2a-66d6-4d9c-8a0e-de2249a30784', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of the Tower library in Axum?', N'Fresher', N'Tower is a library of modular and reusable components for building robust networking clients and servers. Axum uses Tower services and middleware to handle incoming requests and outgoing responses in a composable way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e339a87c-65e8-4c25-a40c-de22fd3db815', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are DynamoDB''s primary access patterns?', N'Intern', N'Access patterns in DynamoDB are typically based on the primary key or secondary indexes. Unlike SQL databases, you must design your table structure based on how you intend to query the data before creating the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67098e33-868c-473d-85d7-de23dd3bce06', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you manage the trade-off between system idempotency and performance?', N'Senior', N'Idempotency is critical for distributed systems to ensure reliability during retries, but it often requires storing state or performing lookups, which adds latency. I accept this performance cost on critical write paths because the risk of duplicate operations (like double billing) is usually far greater than the cost of a few milliseconds of latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9180e3e3-1d3d-4300-b706-de23dfd720c2', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of ''nextTick'' in the context of the event loop?', N'Senior', N'nextTick allows developers to execute a callback after Vue has completed its DOM update cycle. Since Vue updates the DOM asynchronously after state changes, nextTick is essential for accessing the updated DOM elements immediately after modifying reactive data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
