INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd453a22-fbe0-4f9b-8c30-de2e4ea113ec', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind approach pseudo-classes and pseudo-elements compared to standard CSS?', N'Senior', N'Tailwind handles pseudo-classes like hover or focus through utility prefixes, keeping the logic declarative within the markup. This reduces the need for custom CSS definitions for basic interaction states, keeping the stylesheet lean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'423cc9cf-7fb7-4101-a120-de2e97c86757', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'In what scenarios would you choose a local in-memory cache over a distributed cache like Redis?', N'Senior', N'Local in-memory caches are used for extremely low-latency requirements where the penalty of network hops to a central cache is unacceptable. They are ideal for static configuration data or session-agnostic information but introduce challenges regarding synchronization and memory management across multiple instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb13d2e8-c45e-49d8-9065-de32d4416489', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the Go ''zero value'' concept?', N'Intern', N'Every variable in Go is automatically initialized to a default ''zero value'' when declared without an explicit value. For example, integers become zero, booleans become false, and strings become empty, ensuring that variables are always in a valid state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
