INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45ceca16-b946-4412-8d3c-de35fd01aa8b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of the ''dot-dot-dot'' (ellipsis) argument and how does it affect function signature transparency?', N'Senior', N'The ellipsis allows functions to accept an arbitrary number of arguments and pass them to downstream functions, facilitating flexible wrappers and higher-order functions. While powerful, it obscures the function''s interface, making it difficult for users to determine the exact arguments a function expects without inspecting the implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59db52f4-3c72-49c9-8462-de36fb9f20e9', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does the Ruby Global Interpreter Lock (GIL/GVL) impact multi-threaded performance, and what are the implications for I/O-bound versus CPU-bound tasks?', N'Senior', N'The GVL ensures that only one thread executes Ruby bytecode at a time, preventing true parallel execution of Ruby code on multiple cores. This makes the GVL efficient for I/O-bound tasks, where threads spend most of their time waiting, but it significantly bottlenecks CPU-bound tasks that require raw computational throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f214dd4-a891-4cce-b471-de3732dc0a8f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is Preact a full framework or a library?', N'Fresher', N'Preact is a UI library, not a full framework. It focuses specifically on rendering components and managing the UI, leaving other tasks like routing or state management to external libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd02d4ad9-56ef-4fdd-95a7-de3860d82d84', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the significance of the ''app.config'' file versus ''nuxt.config''?', N'Senior', N'nuxt.config is intended for build-time configuration and module setup, whereas app.config is designed for public-facing application settings that can be updated or overridden at runtime. This separation ensures that sensitive build configuration remains isolated from the application''s reactive configuration state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0615af06-31c5-4014-9b0f-de389203dc6e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of using standard protocols instead of custom ones?', N'Intern', N'Standard protocols are widely documented, supported by existing tools, and familiar to developers, which simplifies integration and debugging. Creating a custom protocol often introduces unnecessary complexity and limits interoperability with other systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26266568-9050-45f1-99bd-de38c41c53d4', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Describe the security implications of using server-side load functions.', N'Middle', N'Server-side load functions are highly secure because the code inside them never reaches the client''s browser. This allows developers to use environment variables and private API keys directly in the load function without exposing sensitive credentials to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9574eff-c5f5-4017-824b-de3c093150bf', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of service discovery in a dynamic microservices environment?', N'Middle', N'In a cloud environment, service instances are ephemeral and have dynamic IP addresses. Service discovery provides a mechanism for services to automatically find each other''s network locations through a registry without hardcoding configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82abd86f-3421-4062-9a48-de41741afd3c', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What are methods of Object Class?', N'Intern', N'The Object class is the parent class of all the classes in java by default. Method Description public final Class getClass() returns the Class class object of this object. The Class class can further be used to get the metadata of this class. public int hashCode() returns the hashcode number for this object. public boolean equals(Object obj) compares the given object to this object. protected Object clone() throws CloneNotSupportedException creates and returns the exact copy (clone) of this object. public String toString() returns the string representation of this object. public final void notify() wakes up single thread, waiting on this object''s monitor. public final void notifyAll() wakes up all the threads, waiting on this object''s monitor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
