INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3445f9b1-fa35-4e56-b82d-de4b5f8293d3', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the purpose of the @nestjs/jwt package in NestJS?', N'Fresher', N'The @nestjs/jwt package is a NestJS module that provides functionality around JSON Web Tokens (JWTs). JWTs are a popular method for handling authentication and authorization in web applications. It includes decorators like @AuthGuard(''jwt'') to protect routes with JWT-based authentication and supports the generation and verification of JWTs. Here are some of the things you can do with the @nestjs/jwt package: Generate JWTs: You can create a new JWT with specific payloads and sign it with a secret key. Verify JWTs: You can verify a received JWT to ensure it''s valid and hasn''t been tampered with. Decode JWTs: You can decode a JWT to access the payload information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
