INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a60cb1e3-e425-41d7-a993-de4fa9f973ac', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How can you gracefully shut down an Express server?', N'Middle', N'A graceful shutdown involves stopping the server from accepting new connections using server.close(), allowing existing requests to finish processing, and then closing database connections and cleanup tasks. This prevents data loss and ensures a clean exit for the process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
