INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f044718-639b-45e0-84fd-de5a06a7c096', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain the role of Svelte''s reactivity system based on assignments.', N'Senior', N'Svelte uses a compiler-level transformation where simple variable assignments are treated as triggers for state updates. By intercepting these assignments, the compiler injects reactive logic to update the DOM and invalidate derived state without requiring complex proxies or observable patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
