INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84a8a53b-7dad-4100-b682-de767bc80c73', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript modules improve code maintainability and scope management?', N'Middle', N'Modules provide a native way to split code into isolated files, preventing global scope pollution. They explicitly define dependencies and exports, making the codebase easier to test, refactor, and understand by establishing clear boundaries between components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db588528-b43a-44d4-8177-de7948dd9c4b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the C++ memory model handle data races in multithreaded environments?', N'Senior', N'The C++ memory model defines a happens-before relationship between operations to ensure thread synchronization. It mandates that any data race—defined as two unsynchronized accesses to the same memory location where at least one is a write—results in undefined behavior, forcing developers to use atomic operations or mutexes to establish necessary memory barriers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f24a3f16-5908-492d-a1ff-de79c9399ba0', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What happens if you use a client directive on a non-UI component?', N'Fresher', N'Client directives are only intended for UI framework components like React or Vue. If you apply a client directive to a standard .astro component, it will not function as expected because Astro components are server-side only.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73d3fca4-112d-4daf-86e0-de79f4f6045e', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between using third-party libraries versus writing custom code?', N'Senior', N'I evaluate based on whether the library provides a commodity function or a unique competitive advantage. Third-party libraries save time but introduce external dependencies and security risks. I advocate for using established, well-maintained libraries for common tasks while keeping internal code strictly for unique business logic that differentiates the product.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f506ce32-65d2-4e31-9814-de7c466ec1f3', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does the ''Context API'' differ from a Flux-based state management system regarding performance optimizations?', N'Senior', N'The Context API triggers a re-render in all consuming components whenever the value changes, making it difficult to perform granular updates without complex memoization. Flux-based systems typically provide selectors or subscription models that allow components to re-render only when a specific slice of state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff97e782-7ce8-4b62-8913-de7eddf35037', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How do you take input in Python?', N'Fresher', N'For taking input from user, we have the function input(). In Python 2, we had another function raw_input(). The input() function takes, as an argument, the text to be displayed for the task: a=input(''Enter a number'') Enter a number7 But if you have paid attention, you know that it takes input in the form of a string. type(a) Multiplying this by 2 gives us this: a*=2 a ''77'' So, what if we need to work on an integer instead? We use the int() function for this. a=int(input(''Enter a number'')) Enter a number7 Now when we multiply it by 2, we get this: a*=2 a 14', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe622dcd-0331-4751-9d1d-de8794970454', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the difference between a vulnerability and an exploit?', N'Middle', N'A vulnerability is a weakness or flaw in a system''s security design or implementation. An exploit is the specific code or set of actions that leverages that vulnerability to perform unauthorized actions or gain access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d6d513-ced0-473f-b99f-de897099fb22', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Compare the security implications of using jQuery''s DOM manipulation methods versus modern framework-sanitized rendering.', N'Senior', N'jQuery methods like html() can easily introduce Cross-Site Scripting (XSS) vulnerabilities if user input is not rigorously sanitized, as they directly inject strings into the DOM. Modern frameworks typically handle data binding with built-in security features that automatically escape content, reducing the risk of injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8175a99-0634-4f0b-9b42-de8b41cf6a60', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What does ACID stand for in the context of databases?', N'Fresher', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These are the four properties that ensure database transactions are processed reliably and maintain data accuracy even in the event of errors or power failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c5298d4-7f92-4a98-81a7-de8b43be62aa', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s decorator system differ from standard prototype modification?', N'Middle', N'Decorators provide a safe way to extend the server, request, or reply objects without directly modifying their prototypes in a way that could lead to naming collisions. This approach ensures that extensions are scoped and explicitly documented, improving maintainability in large codebases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69174f15-ec9c-4060-84a3-de8cb4892124', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the architectural advantage of Litestar''s ''Guard'' system?', N'Senior', N'Guards are composable authentication and authorization mechanisms that execute before the handler logic. Because they are part of the dependency injection system, they can easily access request data and state, providing a secure and reusable way to enforce access control across different routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6718d7b-6658-4943-b96b-de8d58acfe0d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you implement a multi-region deployment to ensure high availability and low latency for a global user base?', N'Senior', N'I would deploy regional clusters behind a global load balancer using latency-based routing to direct users to the nearest node. I would then use asynchronous cross-region data replication to maintain read-local performance while ensuring disaster recovery capabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd81351dc-b143-4efd-a465-de8e6af326df', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the Json extractor?', N'Intern', N'The Json extractor is used to automatically deserialize the body of an incoming HTTP request from a JSON format into a Rust struct. It also handles the conversion of Rust structs back into JSON responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd072b62-20ed-409c-be75-de8f8de5ffae', N'4c000000-0000-0000-0000-000000000005', N'Explain the difference between monolith and microservices deployment.', N'Middle', N'A monolith is deployed as a single unit, making it easier to manage initially but harder to scale or modify. Microservices are deployed independently, allowing teams to iterate faster and scale specific components based on demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f681218-f2fe-4ed4-a0aa-de910b2ee165', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS contribute to ''Dead Code Elimination'' compared to traditional CSS methodologies?', N'Senior', N'Tailwind performs tree-shaking on the CSS level by only generating classes that are physically present in the source code. Traditional methodologies often result in large, monolithic CSS files containing unused styles that are difficult to identify and prune manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9ff9241-5bf5-4e59-8bbd-de93e3f67822', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between latency and throughput?', N'Middle', N'Latency is the time it takes for a single request to be processed, whereas throughput is the number of requests a system can handle within a specific time frame. Optimizing for one does not always improve the other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dded32fc-cd57-4589-ad1d-de97c8e2739e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the performance implications of function pointers in C?', N'Middle', N'Function pointers enable polymorphism and callback mechanisms, but they can hinder compiler optimization. Because the compiler cannot always determine which function will be called at runtime, it may be unable to perform inlining or other inter-procedural optimizations that improve execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ad33f18-2904-420e-83fe-de9b3a89f665', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of the Circuit Breaker pattern?', N'Middle', N'The Circuit Breaker pattern prevents a system from repeatedly trying to execute an operation that is likely to fail, such as calling an unresponsive service. It allows the system to fail fast and return a fallback response, preventing resource exhaustion and allowing the failing service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae002417-9de6-4c99-b513-de9c13c3b6ba', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the data types in Node.js?', N'Intern', N'Node.js uses the same data types as JavaScript, categorized into Primitive and Non-Primitive (Reference) types, but it also introduces specialized classes like Buffer to handle server-side needs. 1. Primitives: * String: Represents textual data (e.g., "Hello"). * Number: Represents both integers and floating-point values. Node.js numbers are 64-bit double-precision floats. * BigInt: Used for integers larger than (2⁵³ - 1), which is the limit for the standard Number type. * Boolean: Represents a logical entity with two values: true or false. * Undefined: A variable that has been declared but not assigned a value. * Null: Represents the intentional absence of any object value. * Symbol: Unique and immutable values often used as private identifiers for object properties. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'566f624c-3b5e-44a8-8170-de9d3baee0db', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does the ''newtype'' pattern improve type safety?', N'Middle', N'The newtype pattern wraps a primitive type in a tuple struct, creating a distinct type that the compiler treats differently. This prevents accidental mixing of values that share the same underlying representation but represent different logical concepts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeb76df0-1584-4652-88af-de9d5c2e95ab', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the benefit of using Form Requests for validation.', N'Middle', N'Form Requests encapsulate validation logic within a dedicated class rather than bloating controllers. This separation of concerns improves maintainability and allows for reusable validation rules across different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5e6f0be-42f4-4205-a2e8-de9e70383ab7', N'954a0331-deff-4399-b588-96f39fec001d', N'Explain the concept of ''Content Projection'' vs. ''Component Composition'' and their impact on component reusability.', N'Senior', N'Content projection (ng-content) allows components to act as layout wrappers, injecting external elements into defined slots, which is ideal for generic UI shells like modals or cards. Component composition involves building complex features by nesting smaller, focused components, promoting high maintainability and better adherence to the Single Responsibility Principle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c6ace1-ffdc-405e-8947-dea11f320ccf', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the architectural significance of Litestar''s ''Provide'' object in dependency management?', N'Senior', N'The ''Provide'' object acts as a factory for dependencies, decoupling the consumption logic from the instantiation logic. By utilizing this pattern, developers can inject complex objects like database sessions or authentication providers into handlers while maintaining strict type safety and request-level lifecycle management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0c6fde9-bc5a-44fd-b891-dea6f361775f', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural significance of ''least privilege'' in identity management?', N'Senior', N'Least privilege mandates that users and services are granted only the minimum level of access required to perform their functions. Architecturally, this is enforced through granular IAM policies and role-based access control, which limits the potential damage if a specific identity or service is compromised.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c9b7d9c-b8c2-422d-b572-deaa16a08705', N'954a0331-deff-4399-b588-96f39fec001d', N'What is router state?', N'Intern', N'The RouteState is an interface which represents the state of the router as a tree of activated routes. You can access the current RouterState from anywhere in the Angular app using the Router service and the routerState property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40d9c019-8473-4804-b8d2-deac65b1a192', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle CORS (Cross-Origin Resource Sharing) and why is it required?', N'Middle', N'CORS is handled by adding specific headers like Access-Control-Allow-Origin to the response, often via the ''cors'' middleware. It is required by browsers to enforce security policies that prevent malicious sites from making unauthorized requests to a different domain on behalf of a user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c38392dc-570f-4d80-b95a-deacdc776ca3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are C data types?', N'Intern', N'Data types define the type of data a variable can hold, such as integers, floating-point numbers, or characters. Common types include int, float, char, and double, which determine how much memory is allocated for the variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd31e75b1-c139-4267-b049-dead4eb72cec', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the concept of ''zombie'' or ''orphaned'' processes in a Node.js cluster and how to prevent them.', N'Senior', N'Orphaned processes occur when the master process dies but worker processes continue running, or vice versa. This can be prevented by implementing robust lifecycle management using tools like PM2 or integrated container orchestrators like Kubernetes. Proper signal handling ensures that when a parent process exits, it cleans up all its children.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f36af2bf-93af-4a7e-a3b9-dead5f3e1370', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why might you use multiple Webpack configurations for different environments?', N'Middle', N'Using separate configurations for development and production allows you to tailor the build process to specific needs. For instance, you might include source maps and HMR in development while prioritizing minification, code splitting, and asset optimization for production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f32b6c7-ba47-40df-aa4b-deb27ef4f7ce', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle factors?', N'Junior', N'Factors are a special data type used to store categorical data. They represent categories as integers with associated labels, which is particularly useful for statistical modeling and organizing data for plots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c00e762-ada9-4998-9d83-deb3c77c031a', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of Micronaut''s ''Scopes''?', N'Intern', N'Scopes define the lifecycle and visibility of a bean within the application. Common scopes include singleton, which creates a single instance for the entire application, and prototype, which creates a new instance every time the bean is requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7a5e631-a71e-4c81-9750-deb471f48a46', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle JSON data binding for incoming requests?', N'Junior', N'Gin uses the Bind or ShouldBind family of methods to automatically parse incoming request bodies into Go structs. It uses struct tags to map JSON fields to Go struct fields, validating the data based on those tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21ec924a-964e-4e60-a026-deb5d0dcceed', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the architectural benefits of using a Shadow DOM?', N'Senior', N'Shadow DOM provides true encapsulation by scoping CSS styles and DOM structure within a component. This prevents global style leakage and accidental external DOM manipulation, which is essential for building scalable, maintainable design systems and third-party widgets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'428913a2-b72b-410e-ac71-deb77a42a752', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the Fastify hook system?', N'Intern', N'Hooks are functions that run at specific stages of the request-response lifecycle, such as ''onRequest'', ''preHandler'', or ''onSend''. They allow developers to intercept and modify the request or response flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb3d7473-afc4-4322-bdc5-deb78ceb0627', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind mitigate the risk of style collisions in large, multi-team projects?', N'Senior', N'Tailwind’s atomic nature inherently avoids the cascade-related bugs found in global CSS because classes represent single, predictable properties. By removing the reliance on broad CSS selectors and deep nesting, team members can modify component styles without fearing unintended side effects on distant parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89511f80-7f7b-4618-8dc6-deb80e5dc38f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the primary difference between ASP.NET and ASP.NET Core?', N'Fresher', N'ASP.NET is a legacy framework that runs only on Windows using the full .NET Framework. ASP.NET Core is a modern, cross-platform, and high-performance framework that runs on Windows, Linux, and macOS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdb145ac-8fb7-44a6-a35a-deb8ad63ea4c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are ''group'' modifiers in Tailwind CSS?', N'Junior', N'Group modifiers allow you to style an element based on the state of its parent. By adding the ''group'' class to a parent and using ''group-hover'' on a child element, you can trigger styles on the child when the parent is hovered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63d4c2a1-e70a-46b4-9367-deb8c28602f9', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of an index in a MySQL database, and when should you use one?', N'Junior', N'An index is a data structure that improves the speed of data retrieval operations on a table at the cost of slower writes and additional storage space. You should use indexes on columns that are frequently used in WHERE clauses, JOIN conditions, or ORDER BY statements to avoid full table scans.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7744b668-75f5-4e27-8899-debdbfb5478e', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is the lack of a full synthetic event system considered a positive for Preact?', N'Middle', N'By relying on native browser events, Preact reduces bundle size and avoids the ''event bubbling'' issues that sometimes occur within React''s synthetic event wrappers. It also ensures that the application behavior is more consistent with standard web specifications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02e5dc3a-b446-4e1b-8bd3-debf8f174a5c', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Discuss the strategy Micronaut employs for validation and how it impacts runtime performance.', N'Senior', N'Validation is handled through compile-time generation of validation logic, typically integrated with the Bean Validation specification. By generating the validation code during the build, Micronaut avoids the overhead of runtime reflection on annotations, ensuring that data integrity checks are fast and efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bf7a7f8-e0bb-4029-b064-debfb50985d0', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s garbage collection (GC) strategy handle object generations, and how does this affect application performance?', N'Senior', N'Ruby uses a generational garbage collector that categorizes objects into young and old generations. Young objects are collected frequently because they have high mortality rates, while old objects are scanned less often, reducing the overhead of GC pauses during long-running request cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67d082c1-2a00-45ed-b8bd-dec13c82b153', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Explain the interaction between the Node.js process and the underlying Operating System regarding file descriptors.', N'Senior', N'Every open network socket, file, or pipe consumes a file descriptor from the operating system''s process limit. If an application fails to close these resources properly, it hits the file descriptor limit, preventing new connections or file operations and leading to process instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'637641f7-cd36-4df9-912f-dec73190a230', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix achieve high performance in terms of memory management?', N'Middle', N'Actix leverages Rust''s ownership and borrowing model to minimize memory allocations and data copying. By avoiding garbage collection and using zero-copy deserialization where possible, it ensures predictable memory usage and low latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
