INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da0fa508-e3c5-46d4-a557-ded8e5cfd7e7', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to implement vertical or horizontal scaling for a service experiencing high load?', N'Middle', N'I look at the current hardware utilization and the nature of the bottleneck. If the bottleneck is resource-bound on a single machine, vertical scaling is a quick fix. If the system is already optimized, horizontal scaling is preferred to improve fault tolerance and handle larger traffic volumes by distributing the load across instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'066815b0-4e44-4475-9fe1-ded974dce36f', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is a MemTable and how does it relate to the SSTable?', N'Middle', N'A MemTable is an in-memory structure that stores write operations before they are persisted to disk. Once the MemTable reaches a certain threshold, its contents are flushed to an immutable file on disk called an SSTable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
