INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'513f6814-ec58-4978-ad49-df04570c0eea', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are extension functions in Kotlin?', N'Intern', N'Kotlin''s extension functions provide a convenient mechanism for adding methods to existing classes without altering their source code. This is especially useful for extending classes that are otherwise fixed or derive from external libraries, such as built-in types from Java. Benefits of Extension Functions - Improved Readability: Extension functions enable adding context-specific methods to types. - Consistent Naming: These functions ensure a standard naming convention for classes. - No Inheritance Issues: Overriding is not a concern, making extension functions ideal for providing custom behavior to existing classes. - Modular Code: Associates utility methods directly with the classes they operate on, streamlining code organization. Function vs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
