INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'451e1a07-8690-46ae-8777-df19d4b1772a', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Explain the role of the Send and Sync traits in Rust''s concurrency model.', N'Senior', N'Send and Sync are marker traits that define thread safety properties for types. Send indicates that ownership of a type can be safely transferred between threads, while Sync indicates that it is safe to share references to the type across threads. These traits allow the compiler to prevent data races by ensuring only thread-safe types are shared or moved across execution contexts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89d55e2a-47ba-4165-a62c-df1cb0586479', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust handle null or nil values?', N'Fresher', N'In Rust, the concept of null traditionally found in languages like Java or Swift is replaced by the concept of an Option . The absence of a value is represented by None while the presence of a value of type T is represented by Some(T). This approach is safer and eliminates the need for many null checks. Option Enum The Option type in Rust is a built-in enum, defined as follows: The generic type T represents the data type of the potential value. Use Cases - Functions: Indicate a possible absence of a return value or an error. This can be abstracted as "either this operation produced a value or it didn''t for some reason". - Variables: Signal that a value may not be present, often referred to as "nullable" in other languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c2489b2-8a96-466b-869e-df1d027c2fb4', N'4c000000-0000-0000-0000-000000000005', N'What is the difference between ''Synchronous'' and ''Asynchronous'' communication in distributed systems?', N'Senior', N'Synchronous communication requires both services to be available and waiting, which creates tight coupling and propagation of latency. Asynchronous communication decouples the sender and receiver via a broker, improving resilience and scalability but increasing the difficulty of debugging and handling failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
