INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6998fc27-0e66-4082-b1ee-df2032cabe98', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the primary architectural difference between a WSGI server and a Flask application?', N'Middle', N'A Flask application is a WSGI-compliant framework that handles routing and request logic, while a WSGI server acts as the gateway between the web server and the application. The server is responsible for receiving raw HTTP requests, parsing them, and passing them to the Flask application in a standardized format.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
