INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06c74dc3-7f0c-4c02-be1e-df22dbc8acaf', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the ''select'' statement work in Go''s concurrency model?', N'Middle', N'The select statement allows a goroutine to wait on multiple channel operations simultaneously, proceeding with whichever one becomes ready first. This is essential for building non-blocking systems and multiplexing input from various concurrent sources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d8422f0-851e-4eb7-9742-df25447ceb22', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the purpose of an idempotency key in distributed systems?', N'Middle', N'An idempotency key is a unique identifier sent by a client with a request to ensure that the server processes the operation exactly once. If a request is retried due to a network timeout, the server uses the key to recognize the duplicate and return the previous result instead of re-processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
