INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62c05f66-cea9-482b-967d-df2c15f86951', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'When is it appropriate to use a ''Nitro Plugin'' versus a standard Nuxt plugin?', N'Senior', N'Nitro plugins are used to hook into the server-side request lifecycle, such as modifying headers or handling global errors at the server level. Standard Nuxt plugins are used to configure the Vue instance or integrate client-side libraries, making the choice dependent on whether the logic must execute before or after the application is bootstrapped.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04e4da68-fab0-4b83-98e2-df2e5e027ee2', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Discuss the trade-offs of using ''useAsyncData'' versus ''useFetch'' in Nuxt.', N'Senior', N'useFetch is a high-level wrapper around useAsyncData that automatically handles the fetch call and simplifies common use cases. useAsyncData provides more control for complex scenarios where you need to perform manual data transformation or handle dependency-based fetching, offering a deeper hook into the data lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
