INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4016e3c7-b8cf-43a7-94b1-df464d7c9b52', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the primary output of the Svelte build process?', N'Intern', N'The primary output is a set of highly optimized JavaScript files that directly manipulate the DOM. This output contains only the logic required by your specific application, without any unnecessary framework overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57e56199-2463-4c36-9e42-df49a6ab7ff3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js process directives and what is the impact of its execution order on performance?', N'Senior', N'Alpine.js walks the DOM tree and parses directives sequentially based on their priority. While this allows for predictable initialization, complex deeply-nested structures can increase the time-to-interactive, necessitating careful use of the x-cloak directive to prevent layout shifts during the parsing phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'afba8b82-647e-4cf7-bceb-df4ce1d75a78', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do ''Generators'' provide a memory-efficient alternative to arrays in data processing?', N'Senior', N'Generators implement lazy evaluation, producing values one at a time only when requested rather than materializing an entire collection in memory. This is architecturally superior for handling large datasets or infinite streams where keeping the full result set in RAM would be prohibitive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bec38c4-ec00-4c20-869b-df51cfef05f8', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How are event listeners handled in SolidJS?', N'Intern', N'Event listeners are added using JSX attributes that start with ''on'', such as onClick. SolidJS efficiently delegates these events to the root element to keep the DOM clean and performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'187addeb-d979-4a92-9769-df531efd7d55', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux handle large-scale data updates without blocking the main thread?', N'Senior', N'Redux itself runs on the main thread, so heavy computations should be performed outside the reducer or using memoized selectors. If data processing is extremely heavy, it may be necessary to use Web Workers to process data before dispatching the final result to the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'179f0d25-b6bb-44d0-94a6-df574b0d46f5', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of the Sidecar pattern in microservices infrastructure?', N'Senior', N'The sidecar pattern offloads cross-cutting concerns like service mesh traffic management, logging, and security to a separate process running alongside the service. This keeps the application code focused on business logic while standardizing infrastructure capabilities across the organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
