INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70f27923-f27f-42cc-a7f7-df57ae8545e8', N'954a0331-deff-4399-b588-96f39fec001d', N'What does ''Locality'' mean in the context of the Angular Ivy compiler, and how does it impact build performance?', N'Senior', N'Locality means that a component''s compilation only depends on its own decorators and metadata, without needing to know about the entire application graph. This allows for parallelized compilation and incremental builds, as changing one file does not force the recompilation of unrelated components in the dependency tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54b5543c-433a-4490-8ee4-df5b1aa57053', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue handle ''Provide/Inject'' for cross-component communication, and what are the architectural concerns?', N'Senior', N'Provide/Inject allows dependency injection across deep component trees without prop drilling. While convenient, it creates implicit coupling between components, making the dependency graph harder to trace compared to explicit props; it is best reserved for global configurations or plugins rather than volatile business state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c2cbc7-fded-4d11-9bec-df5c583093d7', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the trade-offs of using a ''Schema-less'' NoSQL database versus a ''Schema-enforced'' SQL database?', N'Senior', N'Schema-less databases offer high flexibility for evolving data models and rapid prototyping but shift the burden of validation to the application layer. Schema-enforced databases provide structural integrity and performance optimizations for complex queries at the cost of rigid development cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
