INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c1e1f42-89b0-440a-97af-df6023029cd0', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono facilitate testing compared to frameworks that rely on the Node.js HTTP server?', N'Middle', N'Hono''s reliance on the Fetch API allows for testing by simply passing request objects to the Hono instance and inspecting the resulting response object. This eliminates the need to start an actual network server during testing, resulting in faster and more reliable unit tests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75a0f859-f5f5-4874-aafe-df615754d9c2', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ''Ownership'' system handle circular references?', N'Senior', N'The ownership system prevents circular references by default because each value has exactly one owner. To create circular structures, one must use interior mutability and reference counting, such as Rc or Weak pointers, which explicitly acknowledge the complexity of the graph and require manual management of the reference cycles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cef41db-2721-4bd2-b9fa-df67f00269e6', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do modules affect the JavaScript execution lifecycle?', N'Senior', N'Modules enable static analysis, allowing the engine to resolve dependencies before execution begins. This structure facilitates tree-shaking and deferred loading, which reduces the amount of code that needs to be parsed and compiled during initial page load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c57786cb-f79f-4993-82ca-df6acd66cd96', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the limitations of Echo''s context-based approach?', N'Middle', N'Because the Echo context is specific to the framework, it can create a tight coupling between your business logic and the framework if you pass the context deep into your service layer. It is generally recommended to extract the necessary data from the context in the handler and pass clean objects to your services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23c6efda-f3e5-4566-b2b2-df6ce90f4507', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does an interface differ from a type alias?', N'Intern', N'While both can be used to define the shape of objects, interfaces are specifically designed for object structures and can be extended or merged. Type aliases are more flexible and can represent primitives, unions, and tuples in addition to object shapes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a72f1aa-2b7d-4df2-85c7-df6ef809ee0d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle data storage?', N'Fresher', N'DynamoDB automatically scales storage by partitioning data across multiple physical servers. The partition key determines which server holds a specific piece of data, making it invisible to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd180eb7d-9f83-45d0-9e39-df700ddb10af', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your process for evaluating the trade-off between consistency and availability in a distributed system?', N'Middle', N'I analyze the impact of temporary data staleness on the user experience based on the CAP theorem. For financial or critical inventory data, I prioritize consistency. For social feeds or analytics where eventual consistency is acceptable, I prioritize availability to ensure the system remains responsive under partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ec5908ce-4382-4419-a3cd-df7747a4c01e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of ''Service Tagging'' and why it is a critical pattern for building extensible Symfony bundles.', N'Senior', N'Service tagging allows developers to mark services as belonging to a specific group, which can then be injected into a central collector service. This enables dynamic extensibility, where new features can be added by simply registering a service with a specific tag, without altering the consuming code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f259cc79-285a-4938-a482-df78900ad268', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a route in a Flask application?', N'Fresher', N'A route is a mapping between a specific URL pattern and a Python function that handles the request. When a user visits the URL, Flask invokes the associated function to generate and return the response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6de13390-dc14-4c2b-8977-df7ad5e787ce', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust''s ownership model influence memory management compared to languages using a garbage collector?', N'Middle', N'Rust enforces strict ownership and borrowing rules at compile time, which allows the compiler to determine the exact lifetime of each variable and insert deallocation code automatically. This eliminates the need for a runtime garbage collector, resulting in predictable performance, no stop-the-world pauses, and minimal runtime overhead. Consequently, memory safety is guaranteed without the memory-intensive tracking overhead typical of managed languages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b2ab59b-78a5-4af9-ae79-df7af083edcd', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are reactive declarations in Svelte?', N'Intern', N'Reactive declarations are a special syntax used to re-run code whenever specific variables change. They are created using a label syntax and are useful for computed values that depend on other pieces of state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3808205e-5b1f-48b4-a56b-df7d785ea46e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the impact of escape analysis on Go''s memory management?', N'Middle', N'Escape analysis allows the compiler to determine if a variable''s lifetime is confined to the scope of a function. If a variable does not escape, the compiler can allocate it on the stack instead of the heap, significantly reducing garbage collection pressure and improving performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7b12b25-f7d9-4023-95dd-df7dfc0f4e84', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What role does the ''define'' configuration play in Vite?', N'Senior', N'The define option allows for global constant replacements during compilation. It is commonly used to inject build-time flags or replace development-only logging code, effectively allowing dead-code elimination by the minifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ded0753d-e3f0-4124-9b8e-df7f8171174e', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the heap in Rust?', N'Intern', N'The heap is a section of memory used for data that has an unknown size at compile time or needs to live longer than the current scope. Accessing the heap is generally slower than the stack because it requires a pointer lookup and manual management by the ownership system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a5f83a2-e3a2-4b93-b3a8-df7fac83621f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum utilize the ''hyper'' crate under the hood?', N'Middle', N'Axum acts as a high-level abstraction layer built directly on top of Hyper, which is a low-level HTTP implementation in Rust. Axum simplifies the complexity of Hyper by providing ergonomic extractors and responses while relying on Hyper''s performance for the underlying HTTP/1 and HTTP/2 transport.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1a2cdb9-0b1a-41ca-a37b-df814027586e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the concept of ''tail call optimization'' and its state in modern JavaScript engines.', N'Senior', N'Tail call optimization allows a function to call another without increasing the stack size by reusing the current stack frame. While part of the ES6 specification, it is rarely implemented in major engines due to the difficulty of maintaining accurate stack traces for debugging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0fbc0c4-0226-4759-98d2-df831c9f6185', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a redirect and a render_template?', N'Junior', N'render_template returns an HTML page to the user directly, while redirect sends an HTTP 302 status code telling the browser to navigate to a new URL. Redirects are typically used after a successful form submission to prevent duplicate form data if the user refreshes the page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
