INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'970b235f-7267-4475-a5cf-df88e17d5545', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the impact of ''Gap Locking'' on insert performance.', N'Senior', N'Gap locking prevents other transactions from inserting rows into the range between index entries, which is required to prevent phantom reads. While necessary for serializability, it can cause significant contention in high-concurrency environments where many transactions try to insert into the same index range.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
