INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85556037-d8c9-476c-aec5-df9510e6fde5', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the primary difference between Vite and traditional bundlers like Webpack?', N'Fresher', N'Traditional bundlers bundle the entire application before starting the development server, which slows down as the app grows. Vite serves source files over native ES modules, meaning it only transforms and serves files on demand as the browser requests them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd8dee35-453c-4b67-8a18-df95d541742c', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a shallow copy and a deep copy in Python, and when should you choose one over the other?', N'Middle', N'A shallow copy creates a new object but inserts references into it for the objects found in the original, meaning nested structures remain shared. A deep copy recursively copies the original object and all nested objects, creating a completely independent clone. You should choose deep copying when you need to modify nested elements without affecting the original structure, whereas shallow copying is more memory-efficient when dealing with immutable or non-nested objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
