INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02c6ba4b-ddc2-4030-8135-df99ccd893f0', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the implications of using ZTS (Zend Thread Safety) in a production environment?', N'Senior', N'ZTS is required when running PHP in a multi-threaded web server environment, such as Apache with the worker MPM, to ensure that global variables and internal structures are thread-local. However, enabling ZTS introduces a performance penalty due to the overhead of mutex locking and may lead to compatibility issues with specific non-thread-safe C extensions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6598d498-0040-497d-aae8-df99eee9a4bd', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''CatchBoundary'' in Remix?', N'Intern', N'A CatchBoundary is used to handle expected server-side errors, such as a 404 Not Found or 401 Unauthorized status. It allows you to show a friendly UI to the user when a request does not result in a successful response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b2e3d15-899d-40ef-bd6e-df9a37ec0e5b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go choose to use a non-generational garbage collector?', N'Senior', N'Non-generational collectors are simpler and avoid the complex write barriers required to track inter-generational pointers. This design choice aligns with Go''s focus on low latency and predictable performance, even if it might result in higher throughput costs compared to generational collectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd719f3c2-601e-4b63-91a4-df9b1ef2a6c8', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are the architectural implications of Python''s Method Resolution Order (MRO) in complex multiple inheritance scenarios?', N'Senior', N'Python uses the C3 Linearization algorithm to determine MRO, which ensures monotonicity and local precedence. This prevents the diamond problem by providing a stable, predictable path for attribute resolution. Understanding this is critical for designing robust class hierarchies and avoiding subtle bugs in method overriding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69df5e9a-7fea-43c3-8e24-df9b9e986371', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the benefit of zero-cost abstractions in Rust?', N'Middle', N'Zero-cost abstractions mean that the features you use do not incur a runtime cost compared to writing the code manually. If you don''t use a feature, you don''t pay for it, and what you do use is as efficient as the equivalent low-level implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'267da99f-525f-4ea2-82dd-df9bc756e35a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''sealed'' keyword for classes or traits?', N'Intern', N'The sealed keyword restricts class hierarchy to the same file, which ensures that all possible subtypes are known at compile time. This is especially useful for pattern matching, as it allows the compiler to warn you if you have missed a case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2db43a8a-bd3b-4081-b42d-df9c53a0296b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik handle component lifecycle methods?', N'Middle', N'Qwik replaces traditional lifecycle hooks with more focused hooks like ''useVisibleTask.'' These hooks are designed to run only when specific conditions are met, such as when a component becomes visible in the viewport, aligning with the lazy-loading architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e639e4b1-399f-4759-a0a4-dfa18a65018d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where the team disagrees significantly on an estimate?', N'Middle', N'I facilitate a discussion where the individuals with the highest and lowest estimates explain their reasoning. This often uncovers hidden complexities or alternative approaches that others hadn''t considered, leading to a more refined and accurate consensus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c0f70ee-0aba-4dfa-96ff-dfa18c2f59de', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What happens if you perform a blocking I/O operation inside an ''async def'' route?', N'Middle', N'Performing a blocking operation, such as a synchronous database query, inside an ''async def'' route blocks the entire event loop, preventing other concurrent requests from being processed. This effectively nullifies the performance benefits of using asynchronous code and can lead to significant latency spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a37953b5-8ce2-4f5d-9c2d-dfa6a429fec7', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why would someone choose a NoSQL database over a traditional RDBMS?', N'Fresher', N'NoSQL is often chosen when the data is unstructured, the requirements are rapidly changing, or there is a need for high flexibility in data storage. It allows developers to store data without needing to perform complex schema migrations, which can be time-consuming in relational databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a171b6de-efdb-49a0-b056-dfa7aacd5fa9', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a self-join?', N'Fresher', N'A self-join is a regular join, but the table is joined with itself. This is useful for querying hierarchical data or comparing rows within the same table, such as finding employees who report to the same manager.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc6650f0-0826-4e97-a319-dfac9bbf0dac', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Contrast the behavior of the ConcurrentDictionary with a standard Dictionary protected by a lock.', N'Senior', N'ConcurrentDictionary uses granular locking and lock-free techniques to allow multiple threads to access and update the collection simultaneously without blocking the entire structure. A standard Dictionary protected by a global lock provides simpler consistency semantics but becomes a scalability bottleneck under high read-write contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'376dac3e-8b85-4959-a456-dfaf87775101', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens during a shard rebalancing operation?', N'Middle', N'Shard rebalancing involves moving shards from one node to another to ensure an even distribution of data and load across the cluster. This process consumes network and I/O resources and is managed by the master node to maintain cluster health.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdcd3ab2-b408-4616-9f37-dfb24ffbe984', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the risk of using ''fire-and-forget'' in a distributed messaging system?', N'Middle', N'Fire-and-forget means the producer sends a message without waiting for an acknowledgment, which provides high performance but risks silent data loss. If the broker is unreachable or the message is rejected, the producer will have no way of knowing the operation failed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e18331b7-c43a-4b6e-96e2-dfb4a47a58d4', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do you handle dynamic parameters in routes?', N'Junior', N'You use square brackets in folder names, such as [slug] or [id], to represent dynamic segments in a URL. SvelteKit makes these parameters available in your load functions so you can fetch data specific to that ID or slug.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb1f9886-e2d5-49b8-8c5c-dfb793ee6f58', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass variable scoping work?', N'Middle', N'Variables defined at the top level of a file are globally scoped. When a variable is defined inside a block, like a media query or a mixin, it is locally scoped to that block, though it can be made global using the !global flag if absolutely necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73785df7-23f5-4dc1-a8a3-dfb8aa4f54de', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is documentation considered a critical part of the problem-solving process?', N'Intern', N'Documentation serves as a reference for why specific decisions were made, which helps prevent repeating past mistakes and assists team members in understanding the system. It ensures continuity of work and provides a trail of logic that can be audited if a solution fails. Without it, knowledge becomes siloed and difficult to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed353186-3276-4aa1-9d29-dfb8ca0a478d', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are local functions?', N'Fresher', N'Local functions are functions defined inside another function. They are used to encapsulate logic that is only relevant to the outer function, keeping the scope clean and preventing naming conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50a0a830-80cb-4230-b2da-dfba75f0ed1d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s ''action'' pattern improve code reuse compared to React''s ''hooks''?', N'Senior', N'Actions provide a way to hook into the lifecycle of a specific DOM element directly. They are more imperative and focused on DOM manipulation, which avoids the unnecessary re-renders that can occur when managing DOM-level logic through higher-level component state hooks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f38c697-3efc-431b-a442-dfbb5595c28f', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik ensure type safety?', N'Junior', N'Qwik is built with TypeScript, so it provides full type support for components, hooks, and loaders. This helps catch bugs during development and ensures that data passed between the server and client remains consistent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6528f53-c259-48f8-ab64-dfbba2482ff7', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the Scala ''Option'' type affect memory layout compared to a null reference in Java?', N'Senior', N'In Scala, an ''Option'' is a full object wrapper, which introduces a small memory overhead for the instance compared to a primitive null reference. However, the use of Scala''s functional patterns with Option often allows for better compiler optimizations like escape analysis. The primary trade-off is the slight increase in heap usage versus the significant gain in runtime safety and clarity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3dd1bc08-ad3b-4bc8-9775-dfbc0a0adbd5', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What does the ''use server'' directive do?', N'Junior', N'The ''use server'' directive marks a function or file as a Server Action. It ensures that the code inside is executed exclusively on the server, preventing sensitive logic or database queries from being exposed to the client-side bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd93b51a1-dc11-4f8e-b059-dfbc5d5e3a2e', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite considered ''fast'' for developers?', N'Intern', N'Vite is fast because it leverages native browser support for ES modules during development and uses a highly optimized bundler called Rollup for production builds. This eliminates the need for long startup times and provides near-instant feedback during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'074281e0-3a06-4dbb-a7a2-dfbd3753e548', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of ''useTask$'' in Qwik?', N'Middle', N'The ''useTask$'' hook is used to run asynchronous side effects, such as data fetching or subscriptions. It is designed to be aware of the resumability state, ensuring that tasks are only triggered when necessary and can be resumed across the server-client boundary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cf2b5ca6-3c5a-45e0-a0c5-dfbdb7d307c4', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does database replication contribute to read scalability?', N'Middle', N'Database replication involves copying data from a primary node to one or more secondary nodes. By directing read-only queries to these replicas, the system can distribute the read load, significantly improving performance and throughput for read-heavy applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2f40920-032b-4ae4-a30a-dfc431d24678', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why is ''deterministic rendering'' important for Next.js, and how do you ensure it?', N'Senior', N'Deterministic rendering ensures that given the same input, the server always produces the same output, which is required for effective caching. It is ensured by avoiding reliance on non-deterministic data like random numbers, timestamps, or user-agent strings during the render phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a98696c7-c484-4587-b663-dfc437c27429', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When working on a team project, how do you ensure your work integrates well with others?', N'Fresher', N'I focus on clear communication and adhering to shared team standards and interfaces. By discussing how components will interact before starting, I can ensure that my work fits seamlessly into the broader system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c788aedd-4954-4d78-bc69-dfc44de01960', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why does Cassandra discourage the use of ''Lightweight Transactions'' (LWT) in high-throughput workloads?', N'Senior', N'LWTs use the Paxos consensus protocol, which requires four round-trips between nodes to ensure linearizability. This creates significant latency and increases resource utilization, making it unsuitable for performance-critical paths where eventual consistency is acceptable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9bba493c-f38d-4fe2-83ef-dfc635bbd299', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Explain the trade-offs between using the ''refresh_interval'' versus manual refreshes in high-ingestion scenarios.', N'Senior', N'The refresh_interval determines how often the index buffer is written to a new searchable segment. Setting this too low causes excessive segment creation and high I/O overhead, while setting it too high increases the latency between document ingestion and searchability. In high-ingestion scenarios, increasing this interval or disabling it during bulk loads can significantly improve throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae1c5f49-6308-4fc9-b220-dfc964af3ffb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of using Redis replication?', N'Junior', N'Replication allows you to create copies of your data on multiple secondary servers. This improves read performance by allowing you to offload read requests to replicas and provides a backup if the primary server fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17458d42-b401-4ec1-a439-dfd07c0be095', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS manage memory usage during large data exports via Lucid streams?', N'Senior', N'Lucid supports database streaming, which allows developers to process large datasets record-by-record without loading the entire result set into RAM. This is critical for maintaining application stability and performance when dealing with high-volume exports or batch processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11c1725e-530b-40be-aaf1-dfd1faab79fb', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut support multiple environments?', N'Fresher', N'Micronaut allows developers to define environment-specific configurations using property files or environment variables. The framework automatically detects the active environment and loads the appropriate settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd08eae1f-926b-443b-81e2-dfd602b1c7fe', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you balance the need for high-quality code with the need for speed in a startup environment?', N'Middle', N'I advocate for ''pragmatic quality''—using automated tests and clean architecture for critical paths while allowing for more flexibility in non-core, exploratory features. I ensure the team understands which parts of the system are ''disposable'' and which are ''foundational'' to guide their investment in quality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c6c5e1d-498c-415b-854e-dfd6d0e44a3b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the function of nesting in Sass?', N'Junior', N'Nesting allows developers to write CSS selectors in a way that follows the visual hierarchy of the HTML. It reduces the need to repeat parent selectors, making the stylesheet cleaner and easier to navigate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1ec7919-ad69-43d1-a792-dfd6e137ff37', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are named parameters in Dart and how are they defined?', N'Junior', N'Named parameters allow developers to specify arguments by name rather than by position during a function call. They are defined by wrapping the parameters in curly braces within the function signature, which improves code readability and reduces errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e09ed76-fa42-4f47-ba7c-dfdd3daa96b6', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Can you use custom CSS alongside Tailwind?', N'Intern', N'Yes, Tailwind allows you to include custom CSS if you need styles that aren''t covered by utility classes. You can add these in your main CSS file using the ''@layer'' directive or standard CSS syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8177decd-5c9f-4dfb-a02c-dfdd9630f75b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the ''Mixin'' pattern in Ember impact code maintainability in the long term?', N'Senior', N'Mixins can lead to ''hidden'' dependencies and name collisions, making it difficult to trace where properties or methods originate in a component. Modern Ember development discourages their use in favor of composition, modifiers, and services, which offer clearer ownership and better type safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1257896-038f-4761-922c-dfdde7b4832f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are the trade-offs of using native ESM for development?', N'Middle', N'Using native ESM allows for faster startup and HMR, but it can lead to network waterfalls if an application has a deeply nested dependency graph. It also requires a browser environment that supports ES modules, which effectively limits development to modern browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7ba6310-980b-4978-8cb1-dfde13e97129', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating the memory usage of a simple application, what factors would you consider?', N'Fresher', N'I would consider the base memory required for the runtime environment, the overhead of the libraries used, and the volume of data the application will process at any given time. I would also account for potential memory leaks or inefficient resource handling. Starting with a baseline and adding expected usage patterns provides a solid conceptual estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3a33cf6-ab49-48fd-8b92-dfde60440f34', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the trade-offs of using ''final'' versus ''const'' in Dart?', N'Middle', N'Final variables are set once at runtime, which is useful for values determined during execution. Const variables are compile-time constants that are canonicalized and stored in the constant pool, offering better performance and memory efficiency for immutable data known before the program runs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63d59327-0fc8-416c-bb0b-dfdf58a7f886', N'4c000000-0000-0000-0000-000000000005', N'What is the trade-off of using microservices versus a monolith?', N'Middle', N'Microservices offer independent scalability, technology flexibility, and organizational decoupling, but introduce significant operational complexity. Monoliths are simpler to develop and deploy initially but can become difficult to maintain and scale as the codebase grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7873035-b79f-42ea-bb9b-dfe23ab81d72', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How can you implement rate limiting in a Fiber application?', N'Middle', N'Rate limiting is typically implemented via middleware that tracks request counts per IP address in an in-memory store like Redis or a local map. Fiber''s middleware architecture makes it easy to intercept requests before they hit the business logic, enabling efficient rejection of excess traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'236f2d83-ae8c-4536-89d5-dfe2bc16ccaa', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the role of the ''Quarkus Dev Services''?', N'Middle', N'Dev Services automatically provision and configure necessary infrastructure, such as databases or message brokers, in containers during development mode. This removes the need for developers to manually set up local dependencies, speeding up the onboarding and development process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'140ef6d6-a2dd-41e0-8d0b-dfeaa3b1fcce', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to test edge cases when solving a problem?', N'Fresher', N'Edge cases represent unusual conditions that can easily cause a system to fail if not accounted for. Testing these ensures the system is resilient and behaves predictably under unexpected circumstances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd35aa1f8-61e3-4655-a455-dfeb591d957e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the common pitfalls when testing Redux applications?', N'Middle', N'Common pitfalls include testing implementation details instead of behavior, forgetting to mock the store, or creating overly complex test cases. Effective testing should focus on verifying the reducer logic and the integration between actions and the store.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'509af52a-0e5b-4848-940f-dfebd81086c2', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the main benefit of ''Generics''?', N'Junior', N'Generics allow you to write flexible, reusable functions and types that can work with any type, subject to specific requirements. They eliminate code duplication by allowing you to write a single implementation that works across multiple data types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f51b3e6-4657-47a2-b984-dfee36b1274a', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does C handle multi-dimensional arrays?', N'Junior', N'C handles multi-dimensional arrays as arrays of arrays. They are stored in contiguous memory in a row-major order, meaning all elements of the first row are stored together, followed by the second row, and so on. This structure allows the compiler to calculate the memory address of any element using a simple mathematical formula.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffc11582-b31d-4401-84a5-dfef1e5b2b69', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How do you perform background tasks in Flask without blocking the request-response cycle?', N'Middle', N'You should offload long-running tasks to a dedicated task queue system like Celery or Redis Queue. The Flask application triggers the task by sending a message to the queue, and a separate worker process picks it up and processes it asynchronously, allowing the main thread to return an immediate response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b54ffd3-2cb8-46e5-88f7-dff037a67e1d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does the adaptive hash index feature in InnoDB optimize performance?', N'Senior', N'InnoDB monitors index searches and, if it detects that a specific index page is being accessed frequently, it automatically creates a hash index for that page in memory. This provides constant-time lookups for those specific paths, effectively turning B-Tree lookups into hash lookups for hot data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eef89ec-fca1-46a3-87c3-dff119ebafda', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you architect a system to handle a sudden ''thundering herd'' event during a high-traffic marketing campaign?', N'Senior', N'I focus on implementing proactive load shedding, request collapsing at the edge, and aggressive caching strategies to prevent the origin from being overwhelmed. Additionally, I would ensure that downstream services are protected by circuit breakers and bulkhead patterns to prevent cascading failures, while relying on auto-scaling triggers based on leading indicators like queue depth rather than just CPU utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c3efa0f-96a7-45dd-86a7-dff2a62ed6c6', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the function of the WHERE clause in a SQL query?', N'Junior', N'The WHERE clause is used to filter records based on specific conditions. It ensures that only the rows meeting the defined criteria are returned by the query, which helps in retrieving only the necessary data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e4a89db-dd1b-40d4-97ad-dff60779b934', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'Explain how Svelte''s ''stores'' interact with the concept of dependency tracking.', N'Senior', N'Svelte stores implement a contract where components can subscribe to state changes, and the compiler automatically handles unsubscribing when components are destroyed. This declarative subscription model ensures that components only re-render when the specific data they observe changes, optimizing the update cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00fb1927-b39b-44fe-9297-dff76c5573a6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is a trade-off in the context of engineering design?', N'Intern', N'A trade-off is a situational decision that involves losing one quality or aspect of a system to gain another. It recognizes that resources and constraints are finite, meaning you cannot maximize every performance metric simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b7e7b9e-3f5d-4807-ac3d-dffa59827ce1', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Why is it generally better to use context managers when handling file I/O?', N'Middle', N'Context managers ensure that resources like file handles or network sockets are properly closed immediately after their scope ends, even if an exception occurs. This prevents resource leaks and ensures that file buffers are flushed correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a0311e6-ec84-4dae-b3a0-dffad692961b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Describe the difference between Choreography and Orchestration in event-driven microservices.', N'Senior', N'Choreography involves services communicating via events without a central coordinator, favoring loose coupling but making it harder to track workflows. Orchestration uses a central controller that directs the flow of operations, providing better visibility but creating a potential single point of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5555b50-5b89-4b72-9d5e-dffb8c0415f8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when choosing between a monolithic and a microservices approach?', N'Fresher', N'A monolith is simpler to develop, test, and deploy for small teams but becomes difficult to scale and maintain as it grows. Microservices offer better modularity and independent scalability but introduce significant complexity in networking and inter-service communication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e78d357-735a-422a-be9e-dffc61fa41ab', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How do C structure layouts affect cache line utilization and CPU throughput?', N'Senior', N'The layout of structure members influences cache locality; grouping frequently accessed fields together minimizes cache misses. By considering the size of the CPU cache line, developers can arrange structures to ensure that related data is fetched into the cache simultaneously. This optimization is crucial for high-performance applications where memory latency is the primary bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a938e47-e229-41ab-bd73-dffcaa406dd7', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are Symfony Voters, and how do they relate to security?', N'Middle', N'Voters are custom security logic classes used to determine whether a user has permission to perform a specific action on a resource. They allow for fine-grained authorization checks that can evaluate complex business rules beyond simple role-based access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'896d4c78-09b6-4266-af93-dffd5629842d', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is Sharding in MongoDB?', N'Intern', N'Sharding is a method for distributing data across multiple machines. MongoDB uses sharding to support deployments with very large data sets and high throughput operations. Database systems with large data sets or high throughput applications can challenge the capacity of a single server. For example, high query rates can exhaust the CPU capacity of the server. Working set sizes larger than the system''s RAM stress the I/O capacity of disk drives. There are two methods for addressing system growth: vertical and horizontal scaling. 1. Vertical Scaling: Vertical Scaling involves increasing the capacity of a single server, such as using a more powerful CPU, adding more RAM, or increasing the amount of storage space. 2.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4edadb50-7ace-42bb-9d02-dffe3a2c68ec', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How does API design impact the ''Principle of Least Privilege''?', N'Middle', N'A well-designed API follows the principle of least privilege by exposing only the specific data and actions required for a client''s role. Using granular scopes and fine-grained access control ensures that clients cannot access unauthorized resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4fae1ac9-0063-4bf0-83b2-e002988b9368', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Explain the role of reducers in Redux and why they must be pure functions.', N'Middle', N'Reducers are responsible for calculating the next state based on the previous state and an action. They must be pure functions to ensure predictability, meaning they should not cause side effects or modify the existing state object directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'595ac814-b869-476c-ba19-e0047a5da5dd', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is Hono?', N'Fresher', N'Hono is a small, simple, and ultra-fast web framework designed for the edge. It is built to run on various JavaScript runtimes such as Cloudflare Workers, Deno, Bun, and Node.js.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8002189f-a7b4-4ecc-b06a-e005c70f1cd6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the primary trade-off when choosing between synchronous and asynchronous processing?', N'Fresher', N'Synchronous processing is simpler to implement and debug because tasks execute in a predictable sequence. Asynchronous processing improves user experience and system responsiveness by allowing long-running tasks to execute in the background without blocking the main execution thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae44c42d-ad20-4043-8801-e0080919c480', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are the trade-offs of using Extension Methods in Dart?', N'Middle', N'Extension methods allow developers to add functionality to existing types without modifying their source code or using inheritance. The trade-off is that they are resolved statically, meaning they cannot be overridden polymorphically, and excessive use can make code harder to trace or discover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
