INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'becdb75b-26cc-49fe-ba5a-e00f867cc1c9', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the difference between a constant and a variable?', N'Intern', N'A constant is a value that is fixed at compile time and cannot be changed throughout the program''s execution. A variable, conversely, is a storage location whose value can be updated during runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4a4afd6-1dd3-4687-bcfa-e01090f047c0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the purpose of Django''s ''select_related'' and ''prefetch_related'', and how do they impact memory usage?', N'Senior', N'Both methods solve the N+1 query problem: ''select_related'' uses SQL JOINs for single-valued relationships, while ''prefetch_related'' performs separate queries for multi-valued relationships. Excessive use can lead to high memory consumption, as the ORM must instantiate all related objects at once.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f3e9ae4-ace1-4dd5-974b-e0120c0c27e7', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach the estimation of non-functional requirements like security or observability?', N'Senior', N'I treat these as first-class citizens within the backlog rather than afterthoughts. I allocate a fixed percentage of capacity—usually 15-20%—specifically for these requirements to ensure they are addressed incrementally alongside new feature development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
