INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbf50eda-9505-424c-99e1-e012fd9daf7e', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why does Cassandra favor ''Wide Rows'' over ''Narrow Rows''?', N'Middle', N'Wide rows allow grouping related data together within a single partition, reducing the overhead of indexing and improving query performance for related records. This design pattern aligns with Cassandra''s storage engine, which is optimized for sequential disk access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f4b0ae-7cbf-4c8e-9a9f-e013209123a7', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the __slots__ attribute, and how does it optimize memory usage?', N'Senior', N'The __slots__ attribute prevents the creation of a dynamic __dict__ for each instance, forcing the object to store attributes in a fixed-size array. This reduces the per-instance memory overhead significantly, especially when creating millions of small objects, though it restricts the ability to add new attributes at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
