INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f799107-56f1-46dc-8e4e-e0155716c3fe', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Explain the performance implications of ''dynamic dispatch'' versus ''static dispatch''.', N'Middle', N'Static dispatch happens at compile time, allowing the compiler to inline code and optimize execution, making it very fast. Dynamic dispatch occurs at runtime, requiring a lookup in a vtable, which adds overhead but is necessary for polymorphic behavior in inheritance hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
