INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74736b4e-2923-4ed4-bc9f-e021840e5292', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why can''t you update props in React?', N'Fresher', N'The React philosophy is that props should be _immutable_(read only) and _top-down_. This means that a parent can send any prop values to a child, but the child can''t modify received props.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b25eaa8-816a-431c-9048-e023f48a7094', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the concept of ''Anti-Entropy'' in the context of background synchronization.', N'Senior', N'Anti-entropy is a background process that periodically compares the entire dataset across replicas to identify and fix inconsistencies caused by missed updates or partial failures. It acts as a safety net for eventual consistency, ensuring that long-term data integrity is maintained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd44404b-eb52-4dba-939c-e0278220c6b3', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are utility types in TypeScript and provide an example of their benefit.', N'Middle', N'Utility types are built-in global types that facilitate common type transformations, such as making all properties optional or picking specific keys from an existing interface. They help reduce code duplication and maintain synchronization between different parts of the application''s data model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'383b2ca5-cf51-4008-af7e-e02beebc3068', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do Node.js memory leaks occur in a long-running process, and how should they be investigated?', N'Senior', N'Leaks often occur through retained closures, global variables, or unbounded cache growth that prevents garbage collection. Investigation requires capturing heap snapshots over time and analyzing them for retained objects that should have been garbage collected. Comparing snapshots helps identify which objects are accumulating in memory unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4057f760-e1ad-4ba3-bd7a-e02c71f65b31', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the Phoenix Framework?', N'Intern', N'Phoenix is a web development framework written in Elixir, designed for building scalable and maintainable applications. It runs on the Erlang VM, which is known for its ability to handle high concurrency and provide fault-tolerant systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad01e8c6-4143-4c86-ac02-e02dca0a7c12', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How do property observers like ''willSet'' and ''didSet'' interact with state management?', N'Middle', N'Property observers provide a clean way to react to state changes without polluting business logic with setter code. They are useful for updating the user interface, validating values, or logging changes, though they should be used carefully to avoid infinite loops or unnecessary side effects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'920d3157-c1df-4f67-a336-e02edb253b79', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Describe the ''Bulkhead'' pattern in software architecture.', N'Senior', N'The bulkhead pattern isolates system components into pools so that if one component fails, the others continue to function. This prevents a cascading failure where one overwhelmed service consumes all available resources, such as thread pools or memory, from the entire system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ed5a4f1-99e9-4546-8aba-e02f6633fef0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the primary purpose of the NestJS Dependency Injection container?', N'Middle', N'The DI container manages the lifecycle and instantiation of classes, allowing for loose coupling between components. It enables better testability by allowing you to swap real service implementations with mocks during unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
