INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7b1c068-4f03-4120-8a75-e033af17b16b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How are arrays handled in PHP?', N'Intern', N'In PHP, an array is an ordered map that associates values with keys. PHP supports both indexed arrays with numeric keys and associative arrays with named string keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04cf11d3-ea1f-42f1-9718-e037a8cd348f', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'Discuss the trade-offs between B-Trees and LSM Trees in the context of storage engine design.', N'Senior', N'B-Trees are optimized for read-heavy workloads with balanced tree structures that provide predictable performance. LSM Trees are optimized for write-heavy workloads by buffering updates in memory and flushing them sequentially to disk, though they may suffer from read amplification and background compaction overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef42eaf-54cc-4823-8702-e038edec3eb0', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s ''Transition'' system handle enter/leave operations?', N'Senior', N'The Transition component automatically applies and removes CSS classes at specific stages of the entering and leaving lifecycle. It tracks the element''s presence in the DOM and coordinates the timing of transitions, allowing for declarative animations without manual DOM manipulation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63ec0440-708e-4955-b51d-e03a72bbcaf8', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript ''Proxy'' object enable meta-programming and reactive state management?', N'Senior', N'Proxies allow for the interception and redefinition of fundamental operations like property lookups, assignments, and function invocations. This capability is the foundation for modern reactive libraries, as it allows frameworks to track dependencies and trigger UI updates automatically whenever state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93a650e1-adfd-42e9-b9c8-e03a87721526', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a buffer overflow?', N'Fresher', N'A buffer overflow occurs when a program writes more data to a memory buffer than it is designed to hold. This extra data overwrites adjacent memory, which can cause the program to crash or lead to security vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
