INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b4b4027-aba0-49f7-b6cb-e048c6de9a65', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the benefit of normalizing the state shape in Redux?', N'Middle', N'Normalizing state involves storing data in a flat structure, similar to a database table, using IDs as keys. This prevents data duplication and makes updates more efficient by ensuring that an entity only needs to be updated in one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc756e44-302d-464e-ae5d-e04915e5514d', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS differ from React in terms of its reactivity model?', N'Fresher', N'Unlike React, which typically re-renders the entire component tree when state changes, SolidJS uses fine-grained reactivity. It tracks individual data dependencies and updates only the specific parts of the DOM that depend on that data. This approach avoids the overhead of a virtual DOM and constant component function re-execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a8478be-e724-4127-a160-e04955ceac89', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue 3 improve performance compared to Vue 2?', N'Middle', N'Vue 3 uses JavaScript Proxies for reactivity, which is faster and supports dynamic property addition better than Vue 2''s Object.defineProperty. It also features a more optimized virtual DOM diffing algorithm, static hoisting during template compilation, and a smaller runtime footprint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
