INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46fc0c31-63d7-4b57-9cba-e05578f84ef7', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What is the architectural impact of moving from stateful to stateless session management in a distributed system?', N'Senior', N'Stateless sessions, typically managed via signed tokens like JWTs, improve horizontal scalability by removing the need for sticky sessions or shared server-side state. However, this introduces challenges in token revocation and requires careful management of secret rotation and token expiration strategies to mitigate replay attack risks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22b58c5f-ced0-47d3-b31e-e0566176ecc1', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit manage large lists efficiently compared to basic DOM injection?', N'Senior', N'Lit''s templating system uses efficient reconciliation through keyed templates, which helps minimize DOM operations when items are added, removed, or reordered. While not as extensive as the virtual DOM diffing in other frameworks, it provides an optimized path that updates only the changed list items rather than re-rendering the entire container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8de1cc48-c3b7-4537-a034-e056cfaa51c6', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the benefit of streaming in the context of React Suspense and Next.js?', N'Middle', N'Streaming allows you to send the HTML of a page in smaller chunks as they are generated, rather than waiting for the entire page to be ready on the server. This significantly improves the Time to First Byte and allows users to see and interact with parts of the page sooner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
