INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59e1516e-be78-48fa-bb6b-e058f27b7027', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of ''ABI Stability'' in the Swift ecosystem?', N'Senior', N'ABI stability allows libraries compiled with different versions of the Swift compiler to interact with each other, provided they adhere to a defined binary interface. This eliminates the need for applications to ship the Swift runtime, as it is now part of the host operating system. It significantly reduces app bundle sizes and allows for smoother system-wide updates to the Swift language.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb4e2343-c56d-40c2-bf6f-e05bf373de9e', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the security implications of using the ''trust proxy'' setting in Express?', N'Middle', N'The ''trust proxy'' setting tells Express whether to trust the X-Forwarded-For header sent by a reverse proxy. If enabled incorrectly, an attacker could spoof their IP address by manually setting the header, which can bypass IP-based rate limiting or security filters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e1534c2-c760-4639-99da-e05d0652b5d3', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How does memory allocation (buffer pool) affect database performance?', N'Middle', N'The buffer pool caches frequently accessed data pages in memory, drastically reducing the need for disk I/O. A properly sized buffer pool allows the database to serve most queries directly from RAM, which is essential for achieving high throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36745ebd-0f08-467b-8ab5-e0608e52259f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why might a system designer choose a polling mechanism over an event-driven notification system?', N'Fresher', N'Polling is simple to implement and requires no complex infrastructure, though it can lead to wasted resources if the state does not change often. Event-driven systems are more efficient and responsive but require a more complex architecture to handle event queues and delivery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53c46945-c671-46e2-a323-e0609607c384', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you trim a string in javascript?', N'Fresher', N'The trim() method removes whitespace from both sides of a string. JavaScript provides 3 simple functions on how to trim strings. 1. string.trim(): The string.trim() removes sequences of whitespaces and line terminators from both the start and the end of the string. 2. string.trimStart(): The string.trimStart() removes sequences of whitespaces and line terminators only from the start of the string. 3. string.trimEnd(): The string.trimEnd() removes sequences of whitespaces and line terminators only from the end of the string. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8bafdf8c-f3d6-49d2-b5e4-e06118b63a9c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the risks of using the ''SAVE'' command in a production environment?', N'Senior', N'The SAVE command is a synchronous, blocking operation that freezes the entire Redis server until the RDB snapshot is fully written to disk. It should be avoided in production; instead, the BGSAVE command should be used to perform the snapshot in a background process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42b4dd4d-cefe-4e9f-abb3-e061a0bbd034', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a companion object?', N'Intern', N'A companion object is a singleton object defined within a class that allows you to access its members using the class name as a qualifier. It serves as a replacement for static members found in languages like Java.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8f2f372-bee5-4609-a589-e063eaa83f8f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s CSS-in-JS integration differ from React''s?', N'Senior', N'Preact does not inherently favor any CSS-in-JS library, but because it follows a standard DOM structure, most CSS-in-JS solutions work without modification. The primary difference is that Preact does not have the same level of internal coordination with style engines as React''s Fiber, which may lead to minor differences in how style injection is ordered during hydration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6c59138-9766-40dd-8e54-e066af60baac', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do distributed databases handle the trade-off between consistency and availability during a network partition?', N'Senior', N'According to the CAP theorem, a system must sacrifice either consistency or availability during a partition. CP systems prioritize data integrity by refusing writes until the partition heals, while AP systems allow continued operation at the risk of returning stale data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2896522f-1a7a-4e2d-8126-e066bb8ffbe3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is an index and why should you use it?', N'Junior', N'An index is a data structure that improves the speed of data retrieval operations on a table. Without an index, the database must perform a full scan of all rows, which is significantly slower for large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72fb58f1-2cc4-42b5-8d69-e067132ba630', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the impact of ''target'' in the compiler configuration?', N'Middle', N'The ''target'' option specifies which ECMAScript version the TypeScript code should be transpiled into. It determines which built-in features and syntax are supported, and it may require additional polyfills if the target version is older than the features being used.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ca3335a-f091-49cb-bf63-e0688fde67fa', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the ''prerender'' option in SvelteKit?', N'Intern', N'Prerendering is a setting that tells SvelteKit to generate the HTML for a page at build time rather than at request time. This is ideal for content that doesn''t change often, as it makes the page load extremely fast for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99e3086f-cf81-4041-89e8-e068bd82373f', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the architectural considerations when implementing a custom C-extension for performance-critical Ruby code?', N'Senior', N'When writing C-extensions, one must manually manage Ruby''s internal object reference counting and ensure that the GVL is released during long-running C operations to avoid blocking the VM. Improper handling of the Ruby heap or pointers can lead to segmentation faults or memory leaks that are difficult to debug within the high-level Ruby environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae9b03b-09a8-49d6-a1d4-e06ae5f675e8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between using a well-known library versus building a custom solution?', N'Intern', N'A library saves development time and maintenance effort but may introduce unnecessary bloat or dependencies. A custom solution provides exactly what is needed but requires significant time for development, testing, and long-term support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ca11969-44b7-49de-95ff-e06d37b5eb1e', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the benefit of SolidJS being ''compiled''?', N'Fresher', N'The compilation step allows SolidJS to transform JSX into optimized DOM operations and track reactive dependencies at build time. This results in smaller bundle sizes and faster runtime performance compared to libraries that do heavy lifting in the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'457b3ea2-0a06-449c-b682-e06ea980e3bb', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can you use environment variables in Astro?', N'Fresher', N'Yes, Astro supports environment variables for storing sensitive information or configuration settings. They can be accessed in both server-side code and, if explicitly allowed, within client-side code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd74d8b3c-82d9-40c8-90d8-e0726af46962', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is difference between async or defer keyword in JavaScript?', N'Fresher', N'1. async Attribute The async attribute is used to indicate to the browser that the script file can be executed asynchronously. The HTML parser does not need to pause at the point it reaches the script tag to fetch and execute, the execution can happen whenever the script becomes ready after being fetched in parallel with the document parsing. * Script downloads in parallel with HTML parsing * Executes immediately when download completes (pauses HTML parsing) * No guaranteed order between multiple async scripts * Best for independent scripts (e.g., analytics, ads) 2. defer Attribute The defer attribute tells the browser not to wait for the script. Instead, the browser will continue to process the HTML, build DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e61e3462-9be0-4c2a-b3c8-e0786bdfc9f2', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the subscribe method in Redux?', N'Fresher', N'The subscribe method allows you to add a listener function that will be called whenever the state changes. This is commonly used in UI frameworks to re-render the interface when the data in the store is updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'448b57bc-8cf6-48c5-a390-e07ad1cdbead', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the architectural benefit of Axum being built on top of Hyper?', N'Senior', N'Building on Hyper allows Axum to benefit from a battle-tested, high-performance HTTP/1 and HTTP/2 implementation. This separation of concerns allows Axum to focus on the application-layer ergonomics while leaving the low-level socket management and protocol compliance to the underlying library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2068eb9b-5c1f-4d21-a6b0-e07c4dce607a', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a channel and what is its primary purpose in Go?', N'Junior', N'A channel is a communication pipe that allows goroutines to send and receive values. Its primary purpose is to synchronize execution and share data between concurrent processes, following the philosophy of communicating by sharing memory instead of sharing memory by communicating.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8088feeb-49fd-4a0f-876a-e08007f3cbd7', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between an include header guard and #pragma once?', N'Junior', N'Header guards are a traditional, portable method using preprocessor directives to prevent a file from being included multiple times. #pragma once is a non-standard but widely supported directive that tells the compiler to include the file only once, offering a cleaner and often faster alternative.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
