INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1da15459-f8dd-42b0-9886-e085930b6775', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why should you avoid destructuring props in SolidJS components?', N'Junior', N'Props in SolidJS are reactive objects that track access. Destructuring props removes the reactivity connection, meaning the component will not update when the parent changes those specific values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf92ad92-68bc-487d-ad32-e0885ac53dc3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Discuss the trade-offs of using Alpine.js''s ''lazy loading'' approach to directives.', N'Senior', N'Alpine loads and processes directives on the fly, which keeps the initial footprint small. However, this dynamic nature can make it harder to perform static analysis or unit testing of the UI compared to a pre-compiled framework like Svelte or Vue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e25a46e-6151-4eef-aaec-e089e7653524', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does data partitioning improve performance in large systems?', N'Middle', N'Partitioning divides a large dataset into smaller subsets based on a partition key. This limits the scope of queries to a single partition, reducing the amount of data the system needs to search or lock, which enhances overall performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd37900c8-435f-4a3b-a0c1-e08ac2b0a737', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte handle component events?', N'Fresher', N'Svelte components can communicate with their parents by dispatching events using a built-in event dispatcher. The parent can then listen for these custom events just like native DOM events, facilitating communication up the component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85659adc-a60b-41e6-86a4-e08ec106b2ea', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the difference between ''finalizers'' and the ''IDisposable'' pattern?', N'Middle', N'Finalizers are used by the garbage collector to reclaim unmanaged resources, but their execution timing is non-deterministic. The IDisposable pattern allows the developer to explicitly release resources immediately, which is much more efficient for system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a162cd63-5a14-4376-81cb-e08fede5004a', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the function of the @ConfigProperty annotation?', N'Junior', N'It is used to inject configuration values from the application''s configuration sources into a field or method within a bean. It allows for flexible configuration where values can be overridden via system properties or environment variables without changing the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
