INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42483712-523c-4eae-bc76-e0928ea174be', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the difference between an Event Listener and an Event Subscriber?', N'Fresher', N'An Event Listener is a standalone service configured to listen for events, while an Event Subscriber is a class that defines its own subscribed events internally. Subscribers are generally preferred in Symfony because they keep the configuration logic within the class itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93879f76-ac79-4c64-aaf7-e093bc2660a8', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the advantages of using Cassandra for time-series data?', N'Fresher', N'Cassandra is ideal for time-series data because its clustering columns allow for efficient sorting of data by time. It also handles high-frequency write volumes very well by appending data sequentially to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdebffe8-0140-4e44-a839-e09587d8c452', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Is Tailwind CSS a replacement for standard CSS?', N'Intern', N'No, Tailwind is a tool built on top of CSS. You still need a fundamental understanding of CSS concepts like the box model, flexbox, grid, and specificity to effectively use and troubleshoot Tailwind utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2fac0c93-4a9a-4324-820a-e095c02b87bf', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Explain the purpose of Kotlin''s null safety mechanism and how it differs from Java''s approach.', N'Middle', N'Kotlin distinguishes between nullable and non-nullable types at the type system level, forcing developers to handle potential null values at compile-time. Java relies on the developer to remember to check for nulls, often leading to runtime NullPointerExceptions, whereas Kotlin prevents these errors through explicit syntax like safe calls and the Elvis operator.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'656efb8c-d804-4bb8-a6db-e09d7dae3495', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the primary architectural benefit of using PHP-FPM compared to mod_php?', N'Senior', N'PHP-FPM operates as an independent FastCGI process manager, decoupling the PHP execution environment from the web server process. This allows for independent scaling, resource limitation per pool, and improved stability, as a crash in the PHP environment does not necessarily impact the web server''s ability to handle static assets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d37d54e-27d0-41c4-8502-e09eb9bee370', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin manage resource cleanup for incoming requests?', N'Middle', N'Gin manages the lifecycle of the Context object using a sync.Pool to reuse memory. This reduces the pressure on the Garbage Collector by recycling objects instead of allocating and deallocating them for every single incoming request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3df7c802-7fdc-4b17-9f2e-e09fbba2209a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of registerServiceWorker in React?', N'Intern', N'React creates a service worker for you without any configuration by default. The service worker is a web API that helps you cache your assets and other files so that when the user is offline or on a slow network, he/she can still see results on the screen, as such, it helps you build a better user experience, that''s what you should know about service worker for now. It''s all about adding offline capabilities to your site.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3130139-2660-40df-a04e-e0a0df909d13', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain how to implement graceful failure in Laravel''s queue workers.', N'Senior', N'Graceful failure is achieved by configuring custom retry limits, exponential backoff strategies, and utilizing the ''failed_jobs'' table for manual inspection. Furthermore, implementing ''failed'' methods within the job class allows for custom cleanup logic or notifications to be executed when a job exceeds its maximum attempts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74b76729-3903-4e24-8720-e0a296f70611', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why is the use of ''this'' important in Ember classes?', N'Junior', N'The ''this'' keyword refers to the instance of the component or class. It is used to access properties, methods, and injected services that are available within that specific scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a045930f-53ad-4cc7-9e5c-e0a4fc9daa8b', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is a load balancer''s role in achieving high availability?', N'Middle', N'A load balancer distributes incoming network traffic across multiple backend servers to ensure no single server bears too much load. It also performs health checks on these servers, automatically routing traffic away from failed nodes to ensure the system remains available despite individual component failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bb4b6b4-999b-417d-9ebd-e0a62889bc33', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are ''variants'' in Tailwind?', N'Intern', N'Variants are modifiers that allow you to change the state of an element or the context in which a style is applied. Examples include responsive breakpoints, hover states, and dark mode variants.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b9c5a56-18b2-44fa-bdf8-e0a73ca44109', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do you handle background jobs in a Phoenix application?', N'Middle', N'Background jobs are typically handled by external libraries like Oban, which uses the database as a reliable queue. This ensures that jobs are processed reliably even if the application process restarts, providing persistence and job visibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34bc8d14-fbea-44ce-8c42-e0ae1be67a68', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the ''state'' in Redux?', N'Intern', N'The state represents the current data of your application at any given point in time. It is a read-only object that can only be changed by dispatching actions, ensuring that the application behavior is predictable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'261d3d2b-af59-47d0-a888-e0b0340b905c', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Why does FastAPI provide a ''test_client'' based on HTTPX?', N'Middle', N'The ''test_client'' allows you to send HTTP requests to your FastAPI application without needing to run a live web server. By using HTTPX, it simulates real network requests and provides an interface that is consistent with how external clients interact with your API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dce566b5-44c1-4e38-9b63-e0b08235043e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe how the Just-In-Time (JIT) compiler utilizes tiered compilation to balance startup time and long-term performance.', N'Senior', N'Tiered compilation uses a multi-stage approach where the C1 compiler provides quick, light optimization for rapid startup, while the C2 compiler performs intensive profile-guided optimization for hot methods. This ensures that the application becomes responsive quickly while eventually achieving peak performance through sophisticated machine code generation based on real-time execution statistics.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20820c6a-9cb2-4afb-ba20-e0b0da20d346', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the trade-offs of using a CSS-in-JS library versus traditional CSS/SCSS modules?', N'Senior', N'CSS-in-JS offers dynamic styling based on component props and easier component isolation, but it incurs a runtime cost for style injection and increased bundle size. Traditional CSS modules provide zero-runtime performance and better caching, though they require more boilerplate for dynamic style generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53be3d72-8c35-4c6a-b7fb-e0b22a408e9f', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the security implications of using loaders that execute arbitrary code?', N'Senior', N'Custom loaders run within the Node.js process during the build. If a loader is malicious or compromised, it has full access to the file system and environment variables, posing a significant supply chain security risk to the build pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32692fbe-4b10-4c04-a490-e0bac8fe414d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Does Vite support multiple pages in a single project?', N'Fresher', N'Yes, Vite supports Multi-Page Applications. You can configure the build to output multiple HTML entry points, each with its own set of assets and scripts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57d63293-45f9-4e42-8f01-e0bbda859117', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When considering data partitioning, how do you balance hot-spot avoidance versus query complexity?', N'Senior', N'I select a shard key that distributes load uniformly across nodes to prevent hot spots, even if it requires secondary indexing or scatter-gather queries. If the query patterns require complex joins, I reconsider the data model or introduce a read-optimized service layer rather than allowing a single shard to become a performance bottleneck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdf15809-d9a1-44a6-a650-e0bfa759b3f2', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What happens if a Rocket route handler fails to execute?', N'Fresher', N'If a handler fails or returns an error, Rocket provides mechanisms to catch these errors and return appropriate HTTP error codes. You can define custom error catchers to handle specific status codes gracefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d7c83f1-2bb9-4002-a2c3-e0bfe27b6ef1', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the client:only directive?', N'Middle', N'The client:only directive tells Astro to skip server-side rendering for that component entirely and only render it on the client. This is useful for components that rely on browser-specific APIs that are unavailable during the build or server-side render phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ad706f3-52c2-4ac6-8774-e0c0b87b7d2f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What are the trade-offs of using ''Autoconfiguration'' in the Service Container?', N'Middle', N'Autoconfiguration reduces boilerplate by automatically applying tags or method calls to services based on their interface or class. However, it can sometimes make the dependency graph harder to trace for developers, requiring them to check the container state to understand how services are interconnected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f23ad7b3-cf3c-46ee-b92b-e0c58b4ca151', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What does ''Schemaless'' mean for DynamoDB?', N'Fresher', N'Schemaless means that items in the same table do not need to have the same attributes, except for the primary key. This allows for flexible data structures that can evolve over time without requiring database migrations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2ad3bd8-dd1c-433b-af74-e0ca75317ea5', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit maintain security against CSRF in form actions?', N'Senior', N'SvelteKit''s form actions are inherently designed to work well with traditional browser security features, but because it is a server-side framework, developers can easily implement custom anti-CSRF tokens within the ''load'' and ''action'' lifecycle. By validating these tokens on the server, the application remains protected against cross-site request forgery attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d5d989b-1cbf-4079-a8a0-e0caba9727fe', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the role of body-parser in Express?', N'Intern', N'Body-parser is a middleware used to extract the entire body portion of an incoming request stream and expose it on the request object. It is essential for parsing data submitted via forms or JSON payloads, making it available as a JavaScript object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dfb3d688-026d-464b-8aa3-e0d040ccf184', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it important to write unit tests for your code?', N'Fresher', N'Unit tests ensure that individual components of the system behave exactly as expected in isolation. They provide a safety net that allows you to refactor or update your code with confidence, knowing that any regressions will be caught immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00c4d455-86bf-407a-8d38-e0d205b03f87', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is Remix in the context of frontend development?', N'Fresher', N'Remix is a full-stack web framework that focuses on web standards and modern user experiences. It allows developers to build both the frontend and backend of an application within a single project, prioritizing fast page loads and seamless data transitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab01af1d-b595-4338-8a40-e0d23f03b494', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the main differences between a stateful component and a stateless component in Preact?', N'Fresher', N'A stateless component is a simple function that accepts props and returns UI elements, making it predictable and easy to test. A stateful component manages its own internal data using hooks, allowing it to track changes over time and trigger re-renders whenever that data is updated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e93768c0-5794-4ded-93e0-e0d55ce6d2d9', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra achieve high availability during node failure?', N'Middle', N'Cassandra achieves high availability through its peer-to-peer architecture and replication factor. Because data is replicated across multiple nodes, the cluster can continue to serve read and write requests even if some nodes are unreachable, provided the consistency level is met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c251cc4c-1264-4829-8b09-e0d8be0883ae', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What architectural patterns prevent ''Waterfall'' data fetching in Next.js?', N'Senior', N'Waterfalls are prevented by initiating all necessary data requests in parallel at the server level using Promise.all or similar patterns. By fetching data in the layout or component tree concurrently rather than sequentially, the total request time is limited by the slowest individual query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd9850aa-66f5-4574-b3e9-e0e31be0ffff', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle component rendering?', N'Fresher', N'Lit uses a fast, declarative template system that renders to the Shadow DOM. When component properties change, Lit efficiently re-renders only the parts of the DOM that actually need updates rather than re-rendering the entire component tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae1b9e30-c62b-4702-81f3-e0e5a518f570', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is a load balancer and why is it essential for system design?', N'Intern', N'A load balancer distributes incoming network traffic across multiple servers to ensure no single server becomes overwhelmed. It is essential for high availability and scalability, as it allows you to add or remove capacity without downtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f92c7157-f137-4682-9d64-e0ea82a060a0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does Rust achieve zero-cost abstractions, and what does this mean for the developer?', N'Senior', N'Zero-cost abstractions ensure that higher-level language features like iterators or closures have no runtime overhead compared to hand-written, low-level code. For the developer, this means they can write expressive, maintainable code without sacrificing the raw performance characteristic of C or C++.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'911c4fe2-2f44-413e-bf29-e0ea839c506d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When designing for high availability, how do you handle the ''split-brain'' scenario?', N'Senior', N'I utilize quorum-based consensus algorithms like Raft or Paxos to ensure that only a single partition of the cluster can accept writes. By requiring a majority of nodes to agree on a state change, I prevent conflicting data updates and maintain system integrity during network partitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
