INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fc7bf9e-c709-47b1-b1a4-e104fbeac372', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB''s read concern ''snapshot'' differ from ''majority''?', N'Senior', N'Read concern ''majority'' ensures the data returned has been acknowledged by a majority of the replica set, protecting against rollback. Read concern ''snapshot'' provides a point-in-time view of the data across multiple shards, ensuring that transactions see a consistent state of the database as it existed at the start of the transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
