INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7eee49fc-cafd-410d-9f74-e117d4aee6b4', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is error.js used for in Next.js?', N'Junior', N'The error.js file defines an error boundary for a specific route segment. It catches unexpected errors during the rendering process and allows you to display a fallback UI, such as an error message or a retry button, instead of crashing the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9e93477-8493-460d-9274-e119106f664a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''extends'' keyword?', N'Intern', N'The ''extends'' keyword is used to define class inheritance or to mix in a trait. It allows a class to inherit members from a parent class or adopt the behavior defined in a trait.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'791dcbe6-abf7-4718-b570-e1197e05f0aa', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How do ''Advisory Locks'' differ from standard table or row-level locks?', N'Senior', N'Advisory locks are application-defined locks that do not map to physical database objects, allowing developers to implement custom concurrency control logic. They are useful for managing external resources or complex transactions that span multiple operations without blocking standard database access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77773594-04c1-42f9-a321-e11eeff61732', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Why would you choose Astro over a traditional SPA for a large-scale e-commerce platform?', N'Senior', N'Astro''s emphasis on fast initial loads and SEO is superior for e-commerce, where conversion rates are directly tied to performance. By rendering product pages statically and hydrating only critical sections like the shopping cart, Astro provides a faster experience than an SPA that requires a heavy JavaScript runtime for the initial render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd90b8ae4-ebe5-4210-92a0-e12013b99901', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby handle memory management?', N'Intern', N'Ruby utilizes an automatic garbage collector to manage memory. It periodically identifies and removes objects that are no longer reachable or referenced by the program, relieving the developer from manual memory deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5125a193-1022-4b79-9a26-e120e39bef47', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do NoSQL databases handle transactions differently than relational databases?', N'Junior', N'Many NoSQL databases prioritize availability and scalability, often supporting transactions only at the document or partition level. Unlike SQL databases that typically offer full multi-table ACID transactions, NoSQL systems may favor eventual consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
