INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b5f80b1a-96f6-4ef1-ae30-e125eaeeed8e', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Can Remix work without JavaScript enabled?', N'Intern', N'Yes, Remix is designed to work with basic HTML functionality, such as form submissions and link navigation, even if JavaScript is disabled. This makes applications more resilient and accessible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14fecccb-ab84-4e8f-8353-e1268b573383', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a helper method?', N'Fresher', N'Helper methods are small utility functions that are available for use within your view templates. They are used to simplify complex logic or formatting within the HTML, keeping the view files clean and readable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a912047a-8f67-4c5c-8168-e12965c7ccff', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you distinguish between a symptom and the root cause of a technical problem?', N'Intern', N'A symptom is the observable issue, while the root cause is the underlying trigger that created it. I would use techniques like the ''Five Whys'' to drill down from the symptom to the fundamental problem. Fixing only the symptom often leads to the issue recurring, whereas addressing the root cause provides a permanent solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b9e3957-d54c-438c-a746-e129933985d8', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the concept of ''tree shaking'' as applied to Dart.', N'Senior', N'Tree shaking is a static analysis process where the compiler identifies and removes unused code paths, methods, and classes from the final binary. This is highly effective in Dart due to its strong typing and modular library system, ensuring that only the code necessary for the application''s runtime functionality is included.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c26cb612-ab0d-4b35-bbce-e12d1823ac92', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the trade-offs between using synchronous and asynchronous replication in a high-availability PostgreSQL cluster.', N'Senior', N'Synchronous replication ensures zero data loss by requiring the primary to wait for confirmation from at least one standby before committing, which increases latency. Asynchronous replication improves write performance by committing locally first, but risks data loss during a failover if the standby has not yet received the latest changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'345d6104-e34e-4939-984c-e12e26149a46', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Describe the concept of ''Index-Only Scans'' and the conditions required to perform them.', N'Senior', N'Index-only scans retrieve data directly from the index, avoiding a heap visit entirely. This requires that all columns requested in the query are present in the index and that the visibility map confirms the pages contain only visible tuples.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f862f83-9b42-41f3-8739-e13453d6c691', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the architectural role of an API Gateway in mitigating Distributed Denial of Service (DDoS) attacks.', N'Senior', N'An API Gateway acts as a centralized enforcement point that can implement rate limiting, request throttling, and IP filtering to shed load before it reaches core backend services. By offloading these tasks, the gateway protects the system from resource exhaustion and provides a unified interface for applying WAF rules and traffic shaping policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8014bdd-beb7-4a3f-85d1-e136e4e46497', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the primary purpose of Nuxt.js?', N'Junior', N'Nuxt.js is a framework built on top of Vue.js that simplifies the development of universal or single-page applications. It provides a standardized structure, automatic routing, and server-side rendering capabilities out of the box.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b1d4072-8c5a-4d0e-a620-e138c4232a88', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Are there any performance considerations when using Alpine.js?', N'Junior', N'Because Alpine.js processes the DOM directly, it is very fast for small to medium-sized applications. However, for extremely large pages with thousands of reactive elements, performance may degrade, so it is best suited for enhancing specific parts of a page rather than building large single-page applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a1d1e05-a443-46d4-9d61-e13922f4cb66', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the Java Virtual Machine (JVM) in the Java platform?', N'Intern', N'The JVM is an abstract computing machine that enables a computer to run a Java program. It converts Java bytecode into machine-specific code, which allows Java applications to be platform-independent. This means that code written once can run on any device equipped with a JVM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'967ffbe3-3eb9-4d52-a21b-e139281d3fb7', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is it difficult to achieve ACID properties in a highly scalable NoSQL database?', N'Senior', N'ACID properties require strong coordination and locking, which limit horizontal scalability and increase latency in distributed environments. Most NoSQL systems favor the BASE model, prioritizing availability and partition tolerance over immediate consistency to handle massive data volumes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b63a2d7b-4c98-44ca-8fd1-e13b97e56075', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the architectural considerations for implementing an API ''Sidecar'' for cross-cutting concerns.', N'Senior', N'A sidecar handles tasks like logging, authentication, and telemetry outside the main application logic, promoting language-agnostic reuse. The primary trade-off is the increased resource footprint per service instance and the added complexity in managing the lifecycle of the sidecar container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f679bd9-c664-4dd5-882c-e13c59c7c49a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the function of the InnoDB doublewrite buffer?', N'Middle', N'The doublewrite buffer is a storage area where InnoDB writes pages before flushing them to the data files. It provides a safety mechanism against data corruption during a crash, ensuring that if a partial page write occurs, the database can recover the original page from the doublewrite buffer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7ea2772-4f0c-4746-8602-e13e928d059a', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'When would you choose Alpine.js over a library like jQuery?', N'Middle', N'Alpine.js is preferred over jQuery because of its reactive data-binding system, which eliminates the need to manually synchronize the DOM with data. jQuery is imperative and often leads to spaghetti code, whereas Alpine enforces a structured, declarative flow that scales better for modern UI interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7128f4aa-642b-4215-96c8-e1400d96eec6', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS''s platform-agnostic design allow for switching between Express and Fastify, and what are the trade-offs?', N'Senior', N'NestJS abstracts the underlying HTTP framework into an adapter, allowing developers to switch between Express and Fastify with minimal changes. Fastify offers significantly higher throughput and lower overhead, but Express provides a massive ecosystem of middleware that might be required for legacy integrations or specific compliance needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ebd4267-abe5-4a9e-8b12-e14835aaf5ba', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you use the Symfony Messenger component instead of standard synchronous processing?', N'Middle', N'Messenger allows you to offload time-consuming tasks to background workers, improving the responsiveness of the web interface. It supports message queues, enabling asynchronous processing, retries, and better handling of spikes in system load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97b455b7-91f3-4f1a-bf91-e14867f69abc', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How do you access a specific DOM element within an Alpine component?', N'Junior', N'You can use the x-ref directive to give an element a name, and then access that element via the $refs magic property. This is the preferred way to interact directly with specific DOM nodes without relying on global document selectors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
