INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ddece89-5328-480c-b546-e14de8690365', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a namespace?', N'Fresher', N'A namespace is a declarative region that provides a scope to the identifiers (names of types, functions, variables) inside it. It is used to organize code into logical groups and prevent name conflicts between different parts of a program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c4dbbed-1ff3-4ca2-819b-e14dfc19d26c', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Describe the Command Query Responsibility Segregation (CQRS) pattern and why it is useful in microservices.', N'Senior', N'CQRS separates read and write operations into different models, allowing each to be scaled and optimized independently. It is particularly effective in microservices when complex business logic needs to be separated from high-performance read projections of the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4969c0ea-3d28-4cf1-8d4e-e151fbbdcf27', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle request lifecycle management compared to Express, and why is this architectural choice beneficial for large-scale applications?', N'Senior', N'AdonisJS utilizes a strictly structured lifecycle with lifecycle hooks and a dependency injection container, whereas Express relies on middleware chains. This structure enforces consistency and predictability across large teams, reducing the cognitive load required to maintain complex request flows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0dc2524-32a0-4e8c-bb11-e1520e615f7f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Symfony EventDispatcher component?', N'Intern', N'The EventDispatcher allows different parts of an application to communicate by dispatching and listening to events. It decouples the core system logic from custom functionality, enabling developers to hook into specific moments of the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9875528e-baf8-487c-987d-e15249d29cd1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What does it mean for a search to be distributed?', N'Junior', N'A distributed search means that a query is sent to all relevant shards across the cluster, executed in parallel, and then merged by the coordinating node. This allows the system to scale search performance linearly with more nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40c94f42-0f80-4acc-8621-e155e1b186f8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why might you want to customize the ''rollupOptions'' in Vite?', N'Middle', N'Customizing rollupOptions allows for fine-tuning the final bundle structure, such as manual chunking, renaming output files, or configuring external dependencies that should not be bundled into the main application file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd8a5747-cc91-4b7d-a6da-e156ae6701b0', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'What does it mean to ''timebox'' a task?', N'Intern', N'Timeboxing is the practice of allocating a fixed amount of time to a specific activity, after which I must stop working on it regardless of completion. This prevents ''analysis paralysis'' or over-engineering and helps keep the project moving according to schedule.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccb4ed05-e17b-4601-8763-e157bb98e0e6', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'Are Lit components compatible with server-side rendering?', N'Fresher', N'Yes, Lit supports server-side rendering (SSR), which allows components to be rendered on the server and sent to the client as static HTML. This improves the initial loading performance and search engine optimization of web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51190d56-9c7d-43cc-8b0d-e157d3e76467', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between a failable initializer and a regular initializer?', N'Junior', N'A failable initializer can return an optional instance if the initialization parameters are invalid, using ''init?''. A regular initializer always returns a fully initialized instance and will trigger a runtime error if requirements are not met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd166d714-47d9-41ad-9766-e15b28a5f3af', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a router in FastAPI?', N'Intern', N'A router is a way to group related API endpoints together into a separate module or file. This helps keep the codebase organized as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d78b18a-8676-4526-ad7b-e15dc6d78fe2', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of ''hinted handoff'' in achieving high availability?', N'Senior', N'Hinted handoff is a mechanism where a node stores a write intended for a temporarily unavailable neighbor. Once the target node recovers, the stored hint is replayed to ensure the node is updated, reducing the window of inconsistency without requiring a full anti-entropy repair.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2948d05d-9c09-4954-8fc8-e15f86184f41', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the technical trade-off between using ''reified'' type parameters and standard generics?', N'Senior', N'Standard generics in Kotlin suffer from type erasure, meaning the type information is lost at runtime, preventing direct checks like ''is T''. Reified type parameters solve this by allowing the compiler to inline the function at each call site and substitute the actual type, effectively bypassing erasure but increasing the size of the generated bytecode due to repetition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45065689-3c37-465c-95bb-e164b48256d3', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Describe the strategy for handling long-running tasks in NestJS without blocking the event loop.', N'Senior', N'Long-running tasks should be offloaded to a background task queue (e.g., BullMQ) rather than executing directly within the request-response cycle. This keeps the event loop free to handle incoming HTTP traffic, ensuring the application remains responsive under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'259dcc5a-4be7-4afa-9c9f-e164d1696a63', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach the migration of a legacy database without incurring significant downtime?', N'Senior', N'Use a phased approach starting with double-writes or change data capture (CDC) to synchronize the old and new systems. Perform gradual traffic shifting with feature flags to ensure data parity before finalizing the switchover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a08da828-d9dd-4b5e-b863-e166c9fafdb0', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a data node?', N'Intern', N'A data node is a node that holds shards and performs data-related operations like CRUD, search, and aggregations. These nodes are the primary workhorses for processing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0af66e88-0878-4ab8-8a66-e167680e83ee', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL manage shared memory and why is the ''shared_buffers'' parameter critical for performance?', N'Senior', N'PostgreSQL uses shared memory for caching data pages, known as shared_buffers, to minimize disk I/O. If set too low, the database relies heavily on the operating system''s kernel cache; if set too high, it may lead to memory contention or reduced space for other operations like sorting and joining.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40cbc782-d4e5-4710-8e32-e1676b195076', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are read-only properties?', N'Intern', N'Read-only properties are object fields that can only be assigned a value during the initialization of the object. Once they are set, their values cannot be changed or reassigned, ensuring immutability for those specific properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a57fb83-a435-47bf-a00f-e16795f31b3f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you ensure proper cleanup of resources when a Node.js process receives a termination signal?', N'Middle', N'You should listen for system signals like SIGTERM or SIGINT and implement a graceful shutdown routine. This includes closing database connections, finishing active HTTP requests, and flushing logs, ensuring that the application exits in a clean state without data corruption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
