INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4b5f274-0f30-4578-a1a4-e16a49233d15', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you distinguish between a symptom and a root cause?', N'Intern', N'A symptom is the outward manifestation of an issue, while the root cause is the underlying condition that triggers the symptom. I use techniques like the ''Five Whys'' to drill down past the surface-level problem until I find the fundamental flaw. Addressing the root cause prevents the issue from recurring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef8ea489-93a7-47fa-85ba-e16cf852ba1a', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it important to document the reasoning behind a design trade-off?', N'Intern', N'Documentation ensures that future team members understand why a specific decision was made, preventing them from reversing a correct decision. It provides context for the constraints that existed at the time, which helps prevent ''bikeshedding'' or unnecessary rework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19756405-61e1-4eac-8abb-e16e237e6761', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you handle ''hot partitions'' in a sharded database?', N'Middle', N'Hot partitions occur when one shard receives significantly more traffic than others, often due to an uneven distribution of keys. This is mitigated by choosing a better shard key, implementing load balancing at the application level, or dynamically re-sharding the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db53ca8e-8f03-4c5c-9fc2-e16fd115a2d1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is an Axum ''Extractor'' and when should you use one?', N'Middle', N'Extractors are mechanisms used to pull data from an incoming HTTP request into function arguments. They should be used for parsing JSON bodies, headers, query parameters, or path variables to keep route handler logic clean and decoupled from request parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
