INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc5f468b-3e93-4315-823f-e17db5ea364a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of the ''Response'' class in Litestar?', N'Fresher', N'The Response class is the base class for all responses in Litestar. It allows developers to customize headers, status codes, and media types for specific endpoints when the default automated response is not sufficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05ebe9e3-f456-44e7-9d9a-e17e262b63fe', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How can you optimize memory usage in ASP.NET Core when processing large files or data streams?', N'Senior', N'Memory usage can be optimized by using streams instead of loading entire files into memory and by utilizing ''PipeReader'' and ''PipeWriter'' for efficient buffer management. Avoiding large object heap allocations and leveraging pooled memory also helps reduce garbage collection pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40575e47-f2c9-4f2a-8a56-e17f90741755', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the architectural purpose of using InjectionTokens instead of concrete classes for dependency injection?', N'Senior', N'InjectionTokens allow you to provide values or interfaces that do not have a runtime representation, which is crucial for decoupling services from their implementation. They prevent circular dependencies and allow for easier mocking during unit testing by abstracting the dependency provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2509380f-f795-4e46-8efd-e181f5ca1831', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is data binding in Echo?', N'Fresher', N'Data binding is the process of automatically converting incoming request data, such as JSON, form data, or query parameters, into a Go struct. This eliminates the need for manual parsing of request bodies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24d49215-33e8-44e5-9961-e181fd3822d4', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Is SolidJS a framework or a library?', N'Intern', N'SolidJS is often referred to as a library, similar to React, because it focuses primarily on the view layer. However, it provides a comprehensive set of primitives that function similarly to a framework for building complex applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'384268f3-52a1-437f-ada1-e1824da31712', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript engine''s ''JIT compilation'' process work, and when does it transition from interpreting to machine code?', N'Senior', N'Engines initially interpret bytecode and monitor execution to identify ''hot'' functions that are executed frequently. Once a threshold is reached, the baseline compiler generates machine code, and eventually, an optimizing compiler applies speculative optimizations based on type feedback to produce highly efficient binary code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'782ff84f-9e04-4b53-b056-e185a6ff7595', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is an alias in MySQL?', N'Intern', N'An alias is a temporary name given to a table or a column in a query. It is primarily used to make column names more readable or to distinguish between tables in complex queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
