INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38033242-aacf-440c-a133-e18be391eea3', N'075b8862-431c-4678-9767-f55359758a4a', N'What are the caveats with vuex mutations?', N'Intern', N'Since a Vuex store''s state is made reactive by Vue, the same reactivity caveats of vue will apply to vuex mutations. These are the rules should be followed for vuex mutations, 1. It is recommended to initialize store''s initial state with all desired fields upfront 2. Add new properties to state Object either by set method or object spread syntax (OR)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'241f556f-2c4c-4bc7-89f2-e18c4048dfa6', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a static variable in a class?', N'Fresher', N'A static variable belongs to the class itself rather than any specific instance of the class. This means that all objects of the class share the same single copy of that variable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f3b25f2-60ca-4d16-acc8-e18c88d40940', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the ''Binary Log'' and how does the choice between ''Statement'' and ''Row'' based logging affect replication?', N'Senior', N'The binary log records all changes to the database for replication and recovery. Statement-based logging is compact but can lead to non-deterministic data divergence, whereas row-based logging is safer and ensures exact data parity but significantly increases the volume of logs generated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6644261a-bf4b-4a90-9994-e18e29a2eb62', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the advantage of using WebSockets in Phoenix?', N'Intern', N'WebSockets allow for a persistent, full-duplex communication channel between the client and server. This avoids the overhead of repeatedly opening and closing HTTP connections, making real-time features much more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0ec531b-0fdd-49d5-b820-e18e6f42f3f7', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Explain how ASP.NET Core handles Model Binding and Validation, and why you would use FluentValidation instead.', N'Senior', N'Model Binding maps incoming request data to action parameters, while Validation ensures the data adheres to defined constraints. FluentValidation is often preferred because it separates validation logic from the model class itself, supports complex validation rules, and promotes better maintainability compared to Data Annotations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
