INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99979643-fdd8-4bba-a9da-e1988a041957', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Are there any limitations to using Redis as a primary database?', N'Fresher', N'The main limitation is that Redis is constrained by the amount of available RAM on the server. Because it is an in-memory store, storing very large datasets can become expensive compared to traditional disk-based databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
