INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7401c2f-979d-4903-875d-e19af547e8ee', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the ''contain'' property in CSS and how does it improve rendering performance?', N'Middle', N'The contain property allows developers to inform the browser that a specific subtree of the DOM is independent of the rest of the page. This limits the scope of browser calculations for layout, paint, and style, which significantly improves performance during updates by preventing unnecessary reflows in unrelated parts of the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e55d8f96-3b0a-4c16-863f-e1a03388dd0e', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a pointer in the C programming language?', N'Intern', N'A pointer is a variable that stores the memory address of another variable rather than a direct value. It allows programs to interact directly with memory locations, which is essential for dynamic memory allocation and efficient data structure management. Pointers are considered a fundamental feature for low-level memory manipulation in C.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5713823-a9d5-4b1d-94bb-e1a43c8e7785', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When a new deployment causes a spike in 5xx errors, what is your immediate process?', N'Middle', N'My immediate step is to initiate a rollback to the previous stable version to restore service availability. Once stability is restored, I would perform a post-mortem analysis by comparing the diffs of the new deployment, reviewing logs for new error signatures, and checking health check patterns. This allows for a root cause analysis in a safe environment without impacting users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'788673e2-9592-4cf6-9c3e-e1a68b0a3487', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is an abstract class in C++?', N'Intern', N'An abstract class is a class that contains at least one pure virtual function, making it impossible to instantiate. It serves as a blueprint for derived classes to implement the specific behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8d2c0f4-b6c0-43a1-be88-e1a73f1b93db', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle data redundancy?', N'Intern', N'MongoDB handles redundancy primarily through replication, where data is copied across multiple servers. This ensures that even if one server fails, the data remains accessible and secure on other nodes in the replica set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f33ad715-72d8-4246-b9ab-e1a8744f30fc', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When refactoring code, how do you verify you haven''t broken anything?', N'Junior', N'Ensure you have a comprehensive test suite in place before starting the refactor. Run these tests frequently throughout the process to catch any unexpected behavior, and perform manual smoke tests on the affected module to ensure it still functions as expected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
