INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'49696e37-7681-47d6-9418-e1ab8ae824d4', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between a Path Parameter and a Query Parameter in Litestar?', N'Fresher', N'Path parameters are part of the URL path itself, defined inside curly braces in the path string. Query parameters are appended to the end of the URL after a question mark and are optional unless specified otherwise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5bd5e1fc-8672-4d89-8442-e1abf2224d60', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide whether to fix a performance bottleneck by optimizing existing code or by introducing a caching layer?', N'Middle', N'I first analyze the bottleneck to determine if it is CPU-bound or I/O-bound. If the operation is computationally expensive but redundant, caching is the appropriate solution. If the code itself is inefficient or causing memory leaks, optimization is preferred to reduce technical debt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
