INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0db13c9a-9666-4d16-ab98-e1ada5159f99', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are destructuring declarations?', N'Fresher', N'Destructuring declarations allow you to unpack an object into multiple variables in a single statement. This is frequently used with data classes to extract property values quickly and efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5111d5ba-4fd4-4e29-ad2d-e1b134132936', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle reactivity when data changes?', N'Intern', N'Lit uses reactive properties to track changes to a component''s state. When a property marked as reactive changes, Lit automatically schedules an asynchronous update to re-render the component and reflect those changes in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a478290d-10bb-4835-95cd-e1b176492de9', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the primary difference between ''Optimistic'' and ''Pessimistic'' locking in a high-concurrency database?', N'Senior', N'Pessimistic locking prevents others from accessing data until a transaction finishes, which is safe but limits throughput and risks deadlocks. Optimistic locking assumes conflicts are rare and only checks for them at commit time, which is much more performant but requires handling retries if a conflict occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f4e8b9e-84f7-4ac5-bde8-e1b3540d47bc', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Symfony Guard or Security Authenticator?', N'Fresher', N'The security system manages authentication and authorization, determining who a user is and what they are allowed to do. It uses authenticators to verify credentials and providers to fetch user information from a database or other source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77505a01-20f7-4c31-ac6c-e1b3bd9d8c81', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the difference between Alpine.js and a full-stack framework like React?', N'Fresher', N'Alpine.js is a drop-in library that works directly inside the browser by enhancing existing HTML, making it ideal for simple interactivity on static sites. React is a complete library for building complex user interfaces that typically requires a build process, a virtual DOM, and a component-based architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c6de460e-9799-4461-ac69-e1b575946a51', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does Chi handle middleware, and why is this useful for a backend developer?', N'Junior', N'Chi allows you to wrap your handlers with middleware functions that execute before or after the main request processing. This is useful for implementing cross-cutting concerns like logging, authentication, recovery from panics, and setting common HTTP headers without repeating code in every handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bef723b-1ee4-4df4-b0fa-e1b9db916d78', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the concept of ''Service Autowiring''.', N'Middle', N'Autowiring allows the service container to automatically detect and inject dependencies into constructors based on type-hinting. This significantly reduces the amount of manual configuration required in service definition files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02aec720-4736-45e7-912e-e1ba4444d6de', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it often recommended to use the @apply directive sparingly?', N'Junior', N'While @apply can extract common utility patterns into custom CSS classes, overusing it can lead to the same maintenance issues as traditional CSS. It is generally better to leverage component reuse in your framework of choice rather than creating many custom CSS classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b598cd60-669c-4877-a8a6-e1ba816557f7', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are the benefits of using an ''@each'' loop?', N'Middle', N'The @each loop allows you to iterate over lists or maps to generate repetitive CSS, such as utility classes for colors, spacing, or icons. This reduces code duplication significantly and makes it trivial to add new items to your design system by simply updating a list or map.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b60197a-54e8-44e8-9fef-e1bdd7287506', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the benefit of explaining your thought process to others while solving a problem?', N'Intern', N'Explaining your thought process helps others understand your logic and allows them to identify potential flaws in your reasoning early on. It also serves as a communication tool that fosters collaboration and ensures that everyone is aligned on the chosen approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf4158dc-a778-4068-a890-e1c0403685de', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the difference between a Commit and a Rollback?', N'Fresher', N'A Commit saves all changes made during a transaction permanently to the database. A Rollback undoes all changes made during the transaction, returning the database to its state before the transaction began.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ed00f3f-61ca-4460-b4f1-e1c370c984a0', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Describe the concept of ''Denormalization'' in NoSQL database design.', N'Senior', N'Denormalization involves embedding related data within a single document or record to satisfy common query patterns in a single read operation. This approach eliminates the performance overhead of join operations, which are computationally expensive in distributed environments, at the cost of increased data redundancy and potential update anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09255264-919f-42d1-aa45-e1c3959671fd', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is it dangerous to capture a reference to a local variable in a lambda?', N'Senior', N'Capturing a local variable by reference creates a dangling reference if the lambda outlives the scope of that variable, such as when returned from a function or passed to an asynchronous task. This leads to undefined behavior when the lambda is eventually executed and attempts to access the now-destroyed stack memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c48f15f-d7b7-4864-b7c1-e1c4371081e1', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit''s ''task'' controller help in handling asynchronous data?', N'Senior', N'The task controller simplifies the management of async operations by providing built-in states like pending, complete, and error. It automates the lifecycle of fetching data, ensuring that components update gracefully without manual tracking of promises or loading flags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f07c79ae-724d-4fdf-a5b3-e1c9ba2b8109', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the TypeScript compiler, and what is its role?', N'Intern', N'The TypeScript compiler is a tool that takes TypeScript code as input and transforms it into plain JavaScript code that browsers or environments can execute. This process is known as transpilation, and it also performs type checking to ensure the code adheres to the defined type rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65110366-6e5a-42ed-8294-e1cb06a2a976', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is a ''hot'' update in PostgreSQL?', N'Middle', N'A Heap-Only Tuple (HOT) update occurs when an update modifies only columns not indexed by any index on the table. This allows the system to update the row without modifying existing index entries, significantly reducing overhead and fragmentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
