INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25739768-16d6-49c5-b376-e1dd97367f45', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the default behavior for components in Astro?', N'Intern', N'The default behavior is to output zero client-side JavaScript. This ensures that every page is as fast as possible by default, requiring the developer to opt-in to interactivity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faa5bbc8-7457-45ed-b26d-e1dfeb863f1b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the purpose of ''TypedArrays'' and why they are necessary for low-level performance.', N'Senior', N'TypedArrays provide a fixed-size, contiguous block of memory that represents binary data, allowing for direct buffer manipulation and better cache locality. They bridge the gap between JavaScript and native memory, which is essential for tasks like image processing, audio manipulation, and WebGL integration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd70ed2ec-c538-454d-aebd-e1e174133a8d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''jsonify'' function in Flask?', N'Intern', N'The jsonify function is a helper that converts a Python dictionary or list into a JSON-formatted response. It automatically sets the correct content-type header to application/json, making it ideal for building APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ec83eb3-a4f5-4b10-936c-e1e342c11fa8', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala''s type erasure affect the implementation of generic collections compared to languages like C#?', N'Senior', N'Scala relies on JVM type erasure, meaning generic type information is discarded at runtime, which prevents direct instantiation of generic types or specific type checking without manifests or type tags. In contrast, C# reifies generics, allowing the runtime to preserve type identity and perform operations like generic instantiation natively. Scala compensates for this by using context bounds and implicit evidence to pass type information manually through the call stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75794ee9-25e7-41cc-9e30-e1e46dd8a7f9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'When is it appropriate to use a schema-less database?', N'Middle', N'A schema-less design is appropriate when the application requirements are evolving rapidly or when the data structures are highly polymorphic and do not fit well into a rigid table format. It provides flexibility for developers to iterate quickly without performing costly migrations, though it shifts the responsibility of data validation to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f1dc5a9-c8f5-400a-a5a3-e1e4873357ef', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a responder in Actix-web?', N'Intern', N'A responder is a trait that defines how a type can be converted into an HTTP response. Any type that implements this trait can be returned from an Actix-web handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
