INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fbb355d-4e84-401b-8634-e1e98e2ee857', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Discuss the trade-offs of using an atomic CSS methodology like Tailwind.', N'Senior', N'Atomic CSS produces a consistent design language and eliminates the need for large CSS files, as the bundle size stays constant regardless of the application''s complexity. However, it can make HTML difficult to read and tightly couples the view layer to the design system, making global design changes more challenging.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a65bc7be-b9ea-4d76-a3e3-e1e9e080ed38', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is PostgreSQL and what kind of database system is it?', N'Fresher', N'PostgreSQL is an open-source, object-relational database management system. It is designed to handle a wide range of workloads while emphasizing extensibility and standards compliance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa4ffdc9-31ac-4a5e-b3e6-e1ed63cb851c', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the benefit of using ''Codable'' for data serialization?', N'Middle', N'Codable provides a standardized, type-safe way to convert between custom data types and external formats like JSON or Property Lists. It reduces boilerplate code by allowing the compiler to automatically synthesize serialization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b81ce47-232f-4266-95cd-e1ed93c131b0', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between ''target: web'' and ''target: node''?', N'Middle', N'The target property tells Webpack which environment the bundle is intended for. Setting it to ''web'' ensures the code is compatible with browser APIs and polyfills, while ''node'' ensures the bundle uses Node.js-specific modules and global variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40bf24f5-954d-45b2-a44d-e1f2d8a4d215', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the ''main'' function?', N'Fresher', N'The main function is the designated entry point of any C program where execution begins. The operating system calls this function when the program is launched, and it typically returns an integer value to signify completion status.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0ee47f6-c40d-4b31-8250-e1f4186f8c22', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does cache hit latency compare to database query latency?', N'Middle', N'Cache hits typically occur in memory, resulting in sub-millisecond response times, whereas database queries involve disk I/O and query execution, often taking milliseconds to seconds. This massive performance gap is the primary reason why caching is essential for scaling high-traffic systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b87f392-ed35-471a-9281-e1f4520a4dc8', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the difference between a ''replica set'' and a ''sharded cluster''?', N'Middle', N'A replica set provides high availability and data redundancy by maintaining multiple copies of the same dataset. A sharded cluster provides horizontal scalability by partitioning a large dataset across multiple replica sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'993680cc-5628-4e9d-a365-e1f567ee74cf', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the Micronaut ''Context'' event system?', N'Junior', N'The event system allows beans to publish and listen for application events. This creates a loosely coupled way for different parts of an application to communicate without having direct references to each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcdae018-a664-4527-a295-e1fa1e938d67', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Discuss the security implications of using Gin’s default error rendering in production.', N'Senior', N'Default error rendering might expose sensitive internal stack traces or system information if not configured properly. In production, developers should always use a custom error handler to sanitize responses and ensure that only user-safe information is returned to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7df6c3b-3e81-451e-bc08-e1fe3f7d4193', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it important to use ''pluck'' or ''select'' instead of loading full Active Record objects when performing bulk data processing?', N'Middle', N'Active Record objects are memory-intensive because they instantiate complex Ruby objects for every row. Using ''pluck'' or ''select'' retrieves only the required columns from the database and returns raw values, significantly reducing memory consumption and improving performance for large data sets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fd1f52f-65d1-4954-9050-e1ffccd63c1c', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs when choosing between horizontal and vertical scaling for a backend service?', N'Middle', N'Vertical scaling involves increasing the resources of a single server, which is simple to implement but has a hard upper limit and creates a single point of failure. Horizontal scaling, adding more nodes, provides better fault tolerance and limitless growth potential but requires more complex load balancing and data partitioning strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b45a9a8-94ee-4562-a9b6-e20152cf359c', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why would you implement a custom UserProvider in Symfony Security?', N'Middle', N'You implement a custom user provider when your user data is stored in a non-standard source, such as a legacy database, an external API, or an LDAP server. It allows the Symfony security component to authenticate and load users regardless of where the identity data originates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1e5ce18-b290-48e0-93f3-e2037ba97f49', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'Define ''Backpressure'' in the context of asynchronous communication.', N'Senior', N'Backpressure is a mechanism where a consumer signals to the producer that it is overwhelmed and cannot handle more data. This prevents the consumer from crashing due to buffer overflows and forces the producer to slow down or buffer data, preserving system integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a93bd0e-73a8-404f-8e99-e204383f8717', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with an application that crashes with an out-of-memory error without a heap dump, what is your next step?', N'Senior', N'I would configure the environment to automatically generate a heap dump upon an out-of-memory event and enable detailed GC logging to see if the memory pressure is coming from the heap or the native memory space (off-heap). I would also check the OS-level OOM killer logs to see if the kernel terminated the process because it exceeded the container''s cgroup memory limits.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45dc5b2b-ad44-4302-b2c3-e204568d313c', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design an authentication system for a microservices architecture?', N'Senior', N'I would use a centralized identity provider and issue cryptographically signed tokens like JWTs at the gateway level. Individual services then validate the tokens locally using the provider''s public key, allowing for stateless authentication across the entire service mesh without repeated calls to a central authority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4024232-dd27-4b21-9c86-e2073ca0bd9d', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you access headers in a Gin request?', N'Junior', N'You can access request headers using the GetHeader method on the context object by providing the header key. This returns the value associated with the header, or an empty string if the header is not present.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23421c0c-1327-4552-9d84-e20bdc4b251d', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is it important to consider ''maintenance costs'' when choosing between two equivalent technical solutions?', N'Intern', N'While two solutions might perform equally well initially, one might be significantly easier to update or debug than the other. Ignoring long-term maintenance is a common mistake that leads to systems becoming brittle and expensive to modify over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc3dbde-35d9-4afc-bef8-e20d6a982af2', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between an iterable and an iterator?', N'Middle', N'An iterable is an object that can be looped over, possessing an __iter__ method that returns an iterator. An iterator is an object that maintains state and provides a __next__ method to yield the next value in a sequence until it is exhausted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98900a38-30b2-4979-bdce-e20d7477c574', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why does Redis recommend against using ''KEYS *'' in production environments?', N'Senior', N'The ''KEYS *'' command is an O(N) operation that iterates over the entire keyspace, which blocks the single-threaded event loop for the duration of the scan. In a production environment with millions of keys, this causes severe latency and can effectively bring the service to a halt.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0f086d0-df5f-4b16-b1e2-e20f622bea37', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the core philosophy of Quarkus regarding application startup time and memory footprint?', N'Junior', N'Quarkus is designed for Kubernetes-native environments, focusing on fast startup times and low memory consumption. It achieves this by performing much of the framework''s initialization during the build phase rather than at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c51a50f1-0c32-4df0-bfe1-e2109f4eed47', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of the MySQL binary log and when is it used?', N'Middle', N'The binary log records all changes to the database structure and content, serving as a vital component for point-in-time recovery and data replication. It allows secondary replicas to synchronize with the primary server by replaying the logged events sequentially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
