INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22aec74d-4d54-446c-8b49-e2174aaa29f9', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the difference between Fiber''s context and Go''s standard context package?', N'Junior', N'Fiber''s context is a custom struct designed for high-performance HTTP operations within the framework. Go''s standard context package is used for managing request-scoped values, cancellation signals, and deadlines across API boundaries and goroutines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09ea5c77-c5b5-40ad-b10f-e219cd5b8a3e', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are the performance implications of using Axum''s ''Extractors'' versus traditional manual parsing?', N'Senior', N'Extractors are highly optimized and designed to be composed, allowing for late-bound deserialization. While there is a slight overhead compared to raw byte processing, the benefit is improved type safety and reduced boilerplate, which is negligible compared to the overhead of network I/O.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eefbb8f-a60e-4f10-a435-e21b2a655b47', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are Tailwind ''plugins''?', N'Intern', N'Plugins are external modules that allow you to extend Tailwind''s functionality. They can be used to add new utilities, components, or base styles that are not provided by the core framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cfc28f8-d341-4223-8516-e21be9b1fb32', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the three phases of AOT?', N'Intern', N'The AOT compiler works in three phases, 1. Code Analysis: The compiler records a representation of the source 2. Code generation: It handles the interpretation as well as places restrictions on what it interprets. 3. Validation: In this phase, the Angular template compiler uses the TypeScript compiler to validate the binding expressions in templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fdb9719-ff52-41ad-861c-e21c19f1c9e4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the styles property in a Lit component?', N'Fresher', N'The styles property is used to define CSS rules specific to the component. Because Lit uses the Shadow DOM, these styles are scoped to the component and will not affect the rest of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'240ae05d-bb1a-4785-8777-e220470b899b', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Why might you choose to deploy a Next.js application to a specialized platform versus a generic containerized environment?', N'Senior', N'Specialized platforms like Vercel provide deep integration with the framework, including automatic edge functions, image optimization, and global CDN distribution. Containerized environments give more control over the server environment but require manual configuration to replicate features like ISR or optimized edge routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9806c265-9f5d-4b9c-97da-e2216cefb12a', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is a DTO in Litestar?', N'Intern', N'A DTO, or Data Transfer Object, is used to define the structure of data that is sent to or received from the API. It helps in decoupling the internal database models from the external API representation, enhancing security and data control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e4dd9a-6007-48e1-80d8-e2219aed71dd', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you install a Ruby gem?', N'Fresher', N'To install a Ruby gem, start by using either of the following: - Directly from RubyGems.org: $ gem install gem_name - From a local file: $ gem install /path/to/gem.gem To select a specific version, add the --version flag, and for developer tools, use the --dev or --development flags. For development or testing, it''s best to install gems in your project''s directory, a process known as bundling. Common bundler commands Bundle Install The bundle install command installs all gem dependencies in the local project, as specified in the Gemfile. Bundle Update Running bundle update gem_name updates the specified gem to its latest version. To update all gems, omit the gem name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08ef2fb1-fa64-489f-8fba-e221ea84306f', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the purpose of the ''h'' function in Preact?', N'Intern', N'The ''h'' function, or hyperscript, is used to define the structure of the user interface. It translates UI elements into virtual DOM nodes that Preact can understand and eventually render to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0514ea6e-e521-4355-be0d-e22431094637', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of ''self'' inside a class?', N'Junior', N'The ''self'' property refers to the current instance of the class. It is commonly used to distinguish between a property of the class and a parameter passed into a method with the same name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a120d51-c4c7-4f08-a48c-e225a9273378', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is ''Secondary Read Preference'', and why is it used?', N'Middle', N'Secondary read preference allows read operations to be directed to secondary nodes in a replica set. This is used to offload read-heavy workloads from the primary node, thereby increasing the total read capacity of the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37f7d8c3-44be-4636-a9d4-e226fe43cea7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is the purpose of the ''resolve.alias'' configuration in a large-scale Vite project?', N'Senior', N'The alias configuration helps simplify complex import paths by mapping shorthands to absolute file system paths. This is critical for maintaining clean imports in large monorepos or projects with deeply nested directory structures, preventing the use of brittle relative paths like ''../../../../''.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d52f2b2-1390-4747-8807-e2272e7f3eda', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does backpressure management prevent system collapse under high load?', N'Senior', N'Backpressure is the mechanism where a system signals to upstream services that it is unable to handle more traffic, preventing the buffer overflow of internal queues. By employing techniques like load shedding, circuit breakers, or reactive streams, a system can maintain stability and degrade gracefully rather than crashing due to resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'371ff84f-327e-4309-9d32-e2282228e07e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a GET and a POST request?', N'Intern', N'A GET request is used to retrieve data from the server without modifying any resources. A POST request is typically used to submit data to the server to create or update a resource.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10ee72ac-d817-4d26-ae32-e2297747906a', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What does NoSQL mean in the context of DynamoDB?', N'Intern', N'NoSQL means that the database does not use traditional relational tables with fixed schemas. Instead, it offers flexible data models that allow for storing unstructured or semi-structured data, which can evolve over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7452b9f-fab4-4435-bcd5-e229e14b0538', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the benefit of horizontal scaling in NoSQL?', N'Fresher', N'Horizontal scaling involves adding more servers to the existing infrastructure to handle increased load. NoSQL databases are designed to distribute data across multiple servers, making it easier to scale out compared to traditional vertical scaling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b6dbc97-8c34-4e77-a28d-e22ad9aa4a08', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the benefits of using symbols over strings as hash keys?', N'Middle', N'Symbols are immutable and represent a unique identifier, meaning the same symbol points to the same memory location throughout the application''s lifecycle. Strings are mutable and create new objects in memory, making symbols more memory-efficient and faster for comparison operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ce7721c-4de6-4c60-bbb9-e22fd202e8e8', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the difference between $(document).ready() and window.onload?', N'Fresher', N'$(document).ready() executes as soon as the DOM hierarchy is fully constructed, even if external resources like images are still loading. In contrast, window.onload waits for the entire page, including all images and external files, to be completely loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0148bb4b-d717-4f38-9a25-e23025303fb1', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database transactions?', N'Junior', N'Django provides a transaction management system that ensures database operations are either all committed or all rolled back. This maintains data integrity, ensuring that if a process involving multiple steps fails halfway through, the database does not end up in an inconsistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
