INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19edfbe5-4b51-42a1-9dbc-e23289508661', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro be used with other frontend frameworks?', N'Intern', N'Yes, Astro is framework-agnostic. It allows you to use components from frameworks like React, Vue, Svelte, or Solid within the same project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8e07daf-b3d1-47e3-98fe-e2358f75922b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the architectural implications of choosing between ''nested'' fields and ''parent-child'' relationships?', N'Senior', N'Nested fields store related data as hidden separate documents within the same Lucene document, allowing for fast, join-free retrieval at the cost of reindexing the entire object on updates. Parent-child relationships use a join field to link separate documents, allowing independent updates but requiring higher memory overhead and slower query-time joining.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b1cfb6a-5e9a-453b-990a-e23739a41fa0', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web handle graceful shutdowns?', N'Junior', N'Actix-web listens for system signals like SIGINT or SIGTERM to initiate a graceful shutdown. This allows the server to finish processing current requests before stopping the event loop and closing connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e204d4b-51d1-4d8f-a700-e23a6fe6f3cf', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is time-series data often a strong use case for Cassandra?', N'Senior', N'Cassandra''s column-family structure allows for efficient storage of time-ordered data by including timestamps in the clustering key. This enables high-velocity write throughput and efficient range queries based on time slices, which is ideal for logs or sensor telemetry.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'329c022a-7307-4d14-81ef-e23a811a8cdd', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary design philosophy of Echo?', N'Fresher', N'The core philosophy of Echo is to provide a minimalist approach that keeps the framework lightweight while offering essential features. It focuses on high performance, ease of use, and a clean, predictable API structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'540f3396-ed5c-4141-a119-e23e609a1ed2', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle high-concurrency scenarios, and where does it typically reach its scaling limit?', N'Senior', N'Express scales well for I/O-bound tasks due to its asynchronous, non-blocking nature. However, it reaches its limit when the event loop becomes saturated with synchronous operations or when memory usage grows beyond the heap limit, necessitating a horizontal scaling strategy using multiple processes or containerized instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60ae058f-f176-4dc7-9f23-e23e6a753a67', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using internal state versus persistent storage for session data?', N'Junior', N'Storing session data in internal memory is extremely fast but is lost if the server restarts. Persistent storage ensures data survives restarts and can be shared across multiple server instances, but it introduces latency because it requires database or cache network calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f66ba38-aa0d-418a-9c83-e24009725e35', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How do Rocket''s ''Catchers'' contribute to robust error handling?', N'Senior', N'Catchers provide a global or route-specific mechanism to intercept HTTP errors, such as 404s or 500s. This architectural approach separates error presentation from error generation, ensuring that the application maintains a consistent response format even during unexpected failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b99cbade-6899-465c-b2f7-e242bab0099e', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of ''fail-fast'' versus ''fail-safe'' iterators.', N'Middle', N'Fail-fast iterators throw a ConcurrentModificationException if the collection is modified structurally while iterating. Fail-safe iterators work on a clone of the collection or a snapshot, allowing modifications during iteration without throwing exceptions. Fail-fast is safer for detecting bugs in synchronization, while fail-safe is useful for high-concurrency read operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19019676-efae-45c9-9818-e24565b976bd', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''AnyVal'' class, and how does it relate to JVM primitive boxing?', N'Senior', N'AnyVal is a base class for user-defined value classes that allows developers to create custom types with zero runtime allocation overhead. The compiler replaces instances of these classes with the underlying primitive type wherever possible, effectively eliminating the cost of object boxing. However, this optimization is bypassed if the value class is treated as its underlying type or assigned to a field, which can lead to unexpected heap allocations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f97129a8-9e05-4307-b7d2-e2469647ebb6', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between a constructor and a method?', N'Intern', N'A constructor is a special function used specifically to initialize a new instance of a class. A method is a function associated with an object that performs actions or provides information about the object''s state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18bfd400-1f1f-43f1-b080-e24babfa6ed5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why would you use a default value in a column?', N'Junior', N'A default value is used to provide a standard value for a column if no value is specified during an insert operation. This helps ensure data consistency and reduces the need for manual input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36d94fdc-a054-42f1-9a40-e24c02dca67b', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo manage error handling across the application?', N'Junior', N'Echo provides a centralized error handling mechanism through a custom HTTP error handler. Instead of returning error responses manually in every route, developers can trigger an error, which the framework catches and processes consistently to return the correct status codes and messages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6509552-7a94-4b4c-bc6d-e24c4439c448', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why is it important to use Fastify''s request object instead of the raw Node.js request object?', N'Middle', N'Fastify''s request object is a wrapper that provides normalized access to params, query, and headers, and it is cached for performance. Using the raw Node.js request object bypasses Fastify''s optimizations and schema validation, potentially leading to security vulnerabilities or performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb05ca81-78c6-41cc-9ca6-e24cfb497b44', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Quarkus and why is it referred to as a Kubernetes-native Java framework?', N'Fresher', N'Quarkus is a full-stack, Kubernetes-native Java framework designed for containers and serverless environments. It is called Kubernetes-native because it optimizes Java applications for minimal memory footprint and fast startup times, making it ideal for running in cloud environments and container orchestrators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a4b0440-e556-4f12-aa0c-e24d8bcf0c2f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''application_controller.rb'' file?', N'Junior', N'The ApplicationController is the base class from which all other controllers in your application inherit. It is the ideal place to define methods or filters, such as authentication logic, that need to be accessible across all controllers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f26099a-88d0-4427-bb21-e24f4d9e927d', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a service is experiencing intermittent failures, how do you differentiate between a network issue and an application logic error?', N'Middle', N'I check the correlation between error rates and network metrics like packet loss or latency spikes. If the errors coincide with network jitter, it is likely infrastructure; if the errors occur predictably during specific operations, I inspect application logs for unhandled exceptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3e96370-eee1-45c4-b8d7-e251ddd97420', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does partitioning by time range affect database management?', N'Senior', N'Time-based partitioning allows for efficient data lifecycle management, such as archiving or dropping old data partitions without expensive delete operations. However, it can cause hotspots on the current time range partition if the write volume is extremely high, requiring further sub-partitioning strategies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
