INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54a61728-f7a2-49a3-a134-e25792e72777', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why should you use ''weak'' or ''unowned'' references in Swift?', N'Junior', N'These keywords are used to prevent strong reference cycles, which occur when two objects hold strong references to each other, preventing memory from being freed. ''Weak'' references become nil when the object is deallocated, while ''unowned'' assume the object will always exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0cb2c63-a019-4227-8baf-e259c5bd1dcb', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Explain the risk of side-channel attacks in multi-tenant cloud environments.', N'Senior', N'Side-channel attacks, such as cache-timing analysis, exploit shared hardware resources to infer sensitive data from other tenants on the same physical host. Mitigating this requires rigorous infrastructure isolation, such as using dedicated hosts or hardware-level partitioning for high-security workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
