INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa6206ed-4d31-4625-b376-e26500bf56a8', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the role of the ''Next'' method in Gin middleware?', N'Intern', N'The ''Next'' method is used to explicitly call the next handler in the chain. It allows the developer to execute code both before and after the actual request handler is executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0ef3599-8210-4f90-a179-e26519150eef', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is it generally recommended to avoid long-running synchronous operations in a Node.js event-driven architecture?', N'Middle', N'Since Node.js operates on a single-threaded event loop, any synchronous operation that takes a significant amount of time will block the entire process, preventing it from handling incoming requests or executing other pending callbacks. This causes the application to become unresponsive, leading to increased latency and potential timeouts for all users. Developers should use asynchronous patterns or offload such tasks to background workers to keep the event loop free.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9301180c-503c-4830-817a-e267051cbaa1', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the purpose of a constructor in C++?', N'Fresher', N'A constructor is a special member function that is automatically called when an object of a class is created. Its primary purpose is to initialize the object''s data members and allocate necessary resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c108deb-0c1b-4e83-9bbe-e26d51e8a993', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does name mangling affect C++ linkage?', N'Middle', N'Name mangling encodes function parameter types and namespaces into the symbol name during compilation to support overloading. This causes issues when trying to call C++ functions from other languages like C, which is why ''extern C'' is required to prevent mangling for cross-language compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad6ef9be-7e63-4912-a47f-e270403a7dcb', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the impact of large HTML files on the browser''s main thread and interactivity?', N'Senior', N'Extremely large HTML files force the browser to spend significant time in the tokenization and tree construction phases. This blocks the main thread, delaying the execution of initial scripts and impacting metrics like First Input Delay and Time to Interactive, as the browser cannot process user interactions until the DOM is sufficiently built.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
