INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9eb87b9-2e39-4bd5-899d-e275f39c5829', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why is GraalVM support significant for Micronaut?', N'Middle', N'GraalVM allows Micronaut applications to be compiled into native binaries, removing the need for a JVM at runtime. This results in near-instant startup times and significantly reduced memory usage, making the application ideal for containerized or serverless deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1f92d93-ff3a-4549-aa4a-e2765993e448', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a ''Path-dependent type'' in Scala?', N'Middle', N'A path-dependent type is a type that is tied to a specific instance of an object rather than the class itself. This is used to ensure that resources or types created by one instance cannot be accidentally mixed with those created by another, providing an extra layer of compile-time safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a7a4867-355e-48fd-ab26-e27a45c39250', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go ensure memory safety without being fully memory-managed in the traditional sense?', N'Middle', N'Go provides memory safety through a combination of garbage collection, bounds checking on slices and arrays, and the absence of manual pointer arithmetic. These features prevent common vulnerabilities like buffer overflows and dangling pointers, while maintaining high performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9d975d6-338d-4c29-8f1d-e27c171e69e2', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a column-family store?', N'Intern', N'A column-family store is a type of NoSQL database that organizes data into columns rather than rows. This design is highly efficient for analytical queries and processing large volumes of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce8c7142-3651-4e97-b915-e27c94038ab5', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is a CORS policy and how is it managed in FastAPI?', N'Junior', N'CORS, or Cross-Origin Resource Sharing, is a security feature that restricts web pages from making requests to a different domain than the one that served the page. In FastAPI, this is managed using the CORSMiddleware to specify which origins are allowed to interact with your API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2e7b43f-6cac-48d9-9993-e27fd61309f3', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the role of the Garbage Collector in .NET?', N'Junior', N'The Garbage Collector automatically manages the allocation and release of memory for the application. It periodically identifies objects that are no longer being used by the program and reclaims their memory to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af6af652-2c78-4475-ae15-e281f8156f36', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'When should you choose Sass over PostCSS for modern frontend projects?', N'Senior', N'Sass is superior for structured, developer-friendly syntax, complex logic, and deep design system integration via modules and maps. PostCSS is better suited for global transformations, autoprefixing, and plugins that interact directly with the CSS AST, often serving as a post-processor to Sass output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f1a655a-3d66-4ba1-b92a-e283f818e6f5', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can Alpine.js be used in a project that already has a larger framework?', N'Middle', N'Yes, Alpine.js is often used alongside other frameworks to handle small, localized interactive snippets that might be overkill for a heavy framework to manage. However, care must be taken to avoid DOM conflicts where both frameworks might try to manage the same elements simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b3d93d7-02f2-454d-ae35-e285b14742aa', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the difference between visibility: hidden; and display: none;? What are the pros and cons of using display:none?', N'Fresher', N'* visibility: hidden simply hides the element but it will occupy space and affect the layout of the document. * display: none removes the element from the normal layout flow (causes DOM reflow). It will not affect the layout of the document nor occupy space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38f6115f-89ac-432b-bd5c-e28ade1929e7', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What is dependency pre-bundling in Vite and why is it necessary?', N'Middle', N'Pre-bundling converts CommonJS or UMD dependencies into ESM and collapses many internal modules into a single file to reduce the number of HTTP requests. This prevents the browser from being overwhelmed by hundreds of network requests when importing large libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f676991e-b23a-4729-b1a1-e28d6aee3868', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Computed Properties?', N'Fresher', N'Computed properties are functions that behave like variables. They automatically update whenever their dependent properties change, making them highly efficient for calculating derived data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
