INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98ec25dc-225a-486c-9d97-e28fe91dcbf0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the purpose of the ''any'' type in TypeScript?', N'Intern', N'The ''any'' type acts as an escape hatch from the type-checking system. It allows a variable to hold any type of value and disables all type checking for that specific variable, effectively treating it like standard JavaScript.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c63171e-d0ee-4572-b463-e29345e28d42', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What are tuples and how are they useful in Swift?', N'Intern', N'In Swift, a tuple is a compound data type that enables bundling multiple values together. Unlike arrays or dictionaries, tuples provide a lightweight, fixed-size grouping. Tuple Syntax You define a tuple using parentheses and separate its components with commas: You can also assign type aliases to tuple elements: Benefits of Tuples - Data Grouping: They allow you to pair or group values conveniently. - Lightweight: Tuples are ideal when you need a quick, temporary grouping of values without creating a custom data structure. - Out-of-the-box: They come with built-in, generic equality checks, making them easy to use. - Multiple Return Values: Instead of encapsulating values within a custom type for multiple returns from a function, you can use a tuple.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b1b2979-50c1-4c35-8538-e2961c8ac115', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django handle database migrations?', N'Fresher', N'Migrations are a way to propagate changes made to your models into the database schema. When you change your models, you run commands that generate migration files, which Django then applies to keep the database structure in sync with your Python code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d2c7c2c-9c6b-4e85-920d-e29653352f30', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is middleware in Litestar?', N'Intern', N'Middleware is a layer that sits between the incoming request and your route handler. It allows you to execute code before a request reaches the handler or after the response is generated, which is useful for tasks like logging, authentication, or modifying headers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'96f3c581-4ff9-4c06-832c-e297a4587a01', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Does Elasticsearch support transactional consistency?', N'Intern', N'Elasticsearch does not provide full ACID transactions like a traditional relational database. It is designed for high performance and scalability, which involves trade-offs regarding strict transactional consistency during concurrent updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b941a565-66a2-4bb9-b4e2-e299595aab39', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle CSRF protection?', N'Fresher', N'Laravel automatically generates a CSRF token for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application, preventing cross-site request forgery attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
