INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d17a0a9-10a2-4b3b-9f5c-e2a0b0919dea', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When should you ask for help on a task you are struggling with?', N'Junior', N'I generally try to debug or research the issue for a set amount of time, such as one hour, before reaching out. If I feel I am not making progress or the problem is blocking other team members, I ask for help sooner to prevent wasting time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff06b25a-40d2-480f-b716-e2a0b0c8d8ad', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Describe the security advantages of using a sidecar proxy pattern for mTLS.', N'Senior', N'The sidecar pattern decouples security concerns from application code, allowing developers to upgrade TLS versions and rotate certificates globally without modifying individual services. It provides a consistent, transparent transport layer security across the entire mesh, ensuring that even legacy services can communicate securely without code changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5aaafcf8-2a9a-4442-8a25-e2a1f586b1ec', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When would you choose to use a micro-frontend architecture?', N'Intern', N'You would choose micro-frontends when multiple teams need to work on a single large-scale web application independently. This approach allows teams to deploy different parts of the user interface without coordinating across the entire codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6cbb3754-d532-4b30-915b-e2a2b91818d6', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you approach estimating the latency impact of a third-party API integration?', N'Middle', N'I would first establish a baseline performance expectation and implement robust observability tools to measure actual response times in a staging environment. I would also design the system with circuit breakers and asynchronous processing to ensure that external latency does not degrade the internal service responsiveness.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
