INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'478723bd-ecc4-4768-bd56-e2a702e6ba70', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain how ''Snitches'' determine cluster topology and proximity.', N'Senior', N'Snitches inform Cassandra about the network topology, specifically which data centers and racks nodes belong to. This information is critical for the replica placement strategy to ensure that data is correctly distributed for high availability and low-latency access across different availability zones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcd1c0a1-08cc-4296-b975-e2a725cb198e', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'How does database indexing impact write performance?', N'Middle', N'While indexes significantly speed up read operations, they slow down write, update, and delete operations. This is because every write must also trigger an update to the index structure, adding overhead to the transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b24c0722-339e-4864-a40e-e2a7e93c86b4', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Why is SolidJS considered to have a smaller memory footprint?', N'Middle', N'By avoiding the Virtual DOM, SolidJS does not need to maintain a tree of objects representing the UI state. Since it creates real DOM elements directly and only updates them via granular subscriptions, it uses significantly less memory than frameworks that keep a full secondary representation of the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbde3128-b669-4ffe-ad99-e2aa701d29d9', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the ''Actix-web'' crate?', N'Intern', N'The actix-web crate is the specific library within the Actix ecosystem that provides the web server and routing functionality. It leverages the lower-level actix-rt runtime for efficient execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
