INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee5343ed-6fa8-4f84-b407-e2ac073774ee', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How do you pass data to a component in Astro?', N'Fresher', N'You pass data to components using props. In the receiving component, you define these props in the frontmatter, and they can then be used to render dynamic content within the component''s HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
