INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fabd2e62-cd32-4e96-91e0-e2b26321c7dd', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between ''struct'' and ''union''?', N'Junior', N'A ''struct'' allocates enough memory to hold all of its members, which exist independently at different offsets. A ''union'' allocates only enough memory to hold its largest member, as all members share the same memory space. Only one member of a union can hold a valid value at any given time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c4b339d-56eb-4948-9242-e2b275677851', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of the Redis ''TTL'' or Time-To-Live?', N'Intern', N'TTL is a feature that allows you to set an expiration time on a key. Once the time expires, Redis automatically deletes the key, which is useful for managing cache data that should not persist indefinitely.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
