INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f16cc08-a57a-4acd-9e52-e2b899f4cd17', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the purpose of middleware in Hono?', N'Fresher', N'Middleware in Hono are functions that execute during the request-response lifecycle before the final route handler. They are used for tasks like logging, authentication, adding headers, or modifying the request data, allowing developers to keep route logic clean and modular.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
