INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a6e93a3-1332-43ad-b2d0-e2bee90baf89', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the scope chain work during variable lookup, and what is the performance implication?', N'Fresher', N'When a variable is referenced, the JavaScript engine performs a scope chain lookup: it starts at the current scope''s environment record and walks up through enclosing records until the variable is found or the global scope is exhausted. V8 optimises this through: 1. Hidden classes / shapes — objects have stable layouts; property access is compiled to a direct memory offset. 2. Inline caching (IC) — after the first lookup, V8 caches the resolved location. Repeated access to the same variable from the same call site is O(1). 3. Closure context allocation — V8''s Turbofan compiler performs context allocation analysis. Variables that are only used locally stay on the stack (fast).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f30278dd-a77d-4eb7-9664-e2c121b14d31', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the differences between a class component and a functional component?', N'Intern', N'Technical Audit: Component Architecture (2026 Standards) In 2026, Functional Components are the industry standard for all new development. Class Components are considered legacy and should be avoided in modern React 19+ applications. Core Distinctions Class Components (Legacy): * Defined by extending React.Component or React.PureComponent. * Relies heavily on the this keyword, which often leads to complex binding issues. * Encapsulates state in an object-based this.state. * Uses imperative lifecycle methods (e.g., componentDidMount, componentDidUpdate). Functional Components (Modern): * Defined as pure JavaScript functions. * Stateless by nature but achieve state/effect persistence via Hooks. * Eliminates the this binding overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7fac54f-16c0-42dc-a7db-e2c18a479e52', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What does ''transpilation'' mean in the Vite ecosystem?', N'Junior', N'Transpilation is the process of converting modern JavaScript or TypeScript code into an older, compatible version that can run in all target browsers. Vite handles this automatically for modern syntax and framework-specific features like JSX or Vue templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66cb0e78-e5f9-47ce-acb5-e2c6c266cc0c', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis achieve high performance?', N'Fresher', N'Redis achieves high performance primarily by keeping its entire dataset in memory, avoiding disk I/O bottlenecks. Additionally, it uses an event-driven architecture and a single-threaded execution model to handle commands efficiently without the overhead of context switching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
