INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'439811db-2d14-44cf-beba-e2ca0cf92793', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI leverage Python''s asynchronous capabilities to achieve high performance compared to Flask?', N'Senior', N'FastAPI is built on Starlette and Uvicorn, utilizing an asynchronous event loop that allows it to handle concurrent I/O-bound operations without blocking the main thread. By leveraging async/await syntax, it efficiently manages thousands of simultaneous connections, whereas traditional synchronous frameworks typically require a multi-threaded or multi-process approach that consumes more memory per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06b6f133-e4f8-4889-a904-e2cec3f5879a', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How does Redux-Toolkit''s ''createSlice'' address the historical boilerplate issues of Redux?', N'Senior', N'createSlice abstracts the manual creation of action types, action creators, and reducer logic into a single cohesive unit. It uses the Immer library internally, allowing developers to write ''mutative'' code that is safely converted into immutable state updates, drastically reducing boilerplate and human error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8190a91e-16ad-40d8-a19d-e2cfb5a8b147', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the benefit of fine-grained lazy loading in Qwik?', N'Middle', N'Fine-grained lazy loading ensures that the initial JavaScript payload remains minimal regardless of application size. By breaking code into tiny chunks, Qwik drastically reduces the Time to Interactive (TTI) for complex web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39aceff2-6069-4330-bb78-e2cfdddf7f5b', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does Fiber handle incoming HTTP requests compared to the default Go server?', N'Intern', N'Fiber uses the Fasthttp engine, which employs a worker pool pattern to handle concurrent connections. Unlike the standard library, which spawns a new goroutine for every single request, Fiber''s approach can be more memory-efficient under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f45c68f4-cc47-4480-834a-e2d64a9a075d', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why do distributed systems often prefer eventual consistency over strong consistency?', N'Senior', N'Strong consistency often requires synchronous communication and distributed locks, which dramatically increase latency and reduce availability. Eventual consistency allows for local-first operations and high availability, making it more suitable for systems that must remain responsive under high load or network instability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68420970-90a0-46ce-bcb4-e2d85b8b1c08', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the purpose of Spring''s ''BeanPostProcessor'' interface?', N'Senior', N'It allows developers to inject custom logic into the bean lifecycle by intercepting the instantiation process. You can use it to wrap beans in proxies, modify properties, or perform validation immediately after a bean is created but before it is put into service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee2985c0-6656-4b99-9435-e2d9ef02d1ec', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of the ''req.body'' object?', N'Intern', N'The req.body object contains key-value pairs of data submitted in the request body. It is typically populated by middleware like body-parser or the built-in express.json middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5279f322-2908-4103-805f-e2dc0db2c95e', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the function of the ''settings.py'' file in a Django project?', N'Junior', N'This file contains all the configuration parameters for a Django project. It manages settings such as database connections, installed applications, middleware, template configuration, and static file paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0279b0a1-da87-4628-b2a7-e2dc0f987b1b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the scope of a variable defined in ''x-data''?', N'Intern', N'The scope of a variable defined in x-data is limited to the element it is attached to and all of its descendants. This allows you to encapsulate logic within specific sections of your page without worrying about global variable conflicts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'015a9371-45f8-4dc9-b261-e2e1e92353d3', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between a single large cluster versus multiple smaller clusters for a distributed service?', N'Senior', N'Multiple smaller clusters provide better blast-radius isolation, ensuring that a failure in one region or group does not take down the entire system. A single large cluster offers easier management and resource pooling, which is preferred only if the operational team is small and the system can tolerate a higher risk of systemic failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58ab0f68-b21a-465b-abfd-e2e3799c8e71', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the total power consumption of a large office building?', N'Intern', N'I would identify the major power-consuming components such as HVAC, lighting, and computing equipment. I would estimate the average wattage for each component and the total duration they are in use during a standard workday. Summing these values gives an approximation of the building''s total energy demand.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c08b2ec-ba4e-4215-9a52-e2e6f34750c5', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum facilitate testing of handlers?', N'Middle', N'Because handlers are just asynchronous functions that take extractors as arguments, they can be tested by invoking them directly with mocked state and request objects. This decoupling allows for fast, unit-level testing without needing to spin up a full HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'134d7fc2-7323-4504-b2e1-e2e768db51b0', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the trade-offs of using CSS-in-JS libraries versus CSS Modules in a large-scale application?', N'Senior', N'CSS-in-JS allows for dynamic styling based on props and easier scoping, but incurs a runtime overhead for style injection and parsing. CSS Modules offer static, build-time compilation that results in faster performance and smaller bundles, at the cost of less flexibility in dynamic style generation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'559a98a3-fe0a-483e-bca1-e2ebc5fc77e2', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''thundering herd'' problem and how do you prevent it?', N'Middle', N'The thundering herd problem occurs when a large number of requests hit the backend simultaneously because a cached item expired or a service crashed. It can be prevented by implementing cache expiration jitter, request collapsing, or using circuit breakers to throttle incoming traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a04c43b1-dd59-4816-8ff9-e2f19500383f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between a list comprehension and a generator expression?', N'Middle', N'A list comprehension creates and stores the entire list in memory immediately upon execution. A generator expression returns an object that generates items on demand, using significantly less memory for large sequences. Choose list comprehensions for small datasets or when random access is needed, and generator expressions for large data processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
