INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'478b177b-d63d-4513-b48d-e30496d75bd4', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Discuss the impact of Qwik''s approach on Core Web Vitals, specifically INP (Interaction to Next Paint).', N'Senior', N'Qwik significantly improves INP by ensuring the Main Thread is not busy with hydration tasks during the critical post-load period. By keeping the execution of logic deferred until the interaction occurs, the browser remains highly responsive to user input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
