INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b817e444-9f11-4001-8b1f-e30bf98f0470', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the role of a database coordinator in distributed transactions?', N'Intern', N'The coordinator manages the commit or rollback process across multiple distributed nodes. It ensures that all participating nodes agree on the final outcome of the transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15f6d319-5663-4096-a457-e30ea6506df5', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''any'' type differ from the ''unknown'' type in terms of type safety?', N'Middle', N'The ''any'' type disables type checking entirely, allowing any operations on the variable. ''Unknown'' is a type-safe counterpart that requires explicit type narrowing or casting before performing operations, preventing runtime errors caused by unexpected data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
