INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'720afc03-d820-46df-9323-e3115eb8c6f4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'You are assigned to fix a bug that is reported as ''the page is slow.'' How would you approach identifying the root cause without immediately jumping into the codebase?', N'Junior', N'I would start by reproducing the issue in a controlled environment to confirm the behavior and narrow down whether it is a client-side or server-side performance bottleneck. I would use browser developer tools to analyze network requests and load times to see if the delay is caused by large assets, slow API responses, or heavy client-side processing. By isolating the specific layer causing the latency, I can then focus my investigation on the relevant logs or service metrics rather than guessing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60203ee9-3b05-42f4-80cd-e312eb3da4c4', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What are the limitations of Gin''s ''Context'' when dealing with asynchronous tasks?', N'Senior', N'The Gin context is tied to the lifecycle of the incoming request and is reset after the request finishes. Passing it to background goroutines is dangerous; instead, you should copy only the necessary values from the context to the background task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fb67c15-578a-46f0-b68b-e313a3db036e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How should you approach testing a Fastify application?', N'Middle', N'Testing should leverage the ''inject'' method provided by the Fastify instance, which simulates HTTP requests without actually binding to a network port. This allows for fast, isolated integration tests that verify the entire request lifecycle, including hooks and serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a38f4d66-8956-4b44-aad7-e316b9e87d7b', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the purpose of the ''factory'' keyword in a constructor?', N'Junior', N'A factory constructor is used when you do not always want to create a new instance of a class. It can return an existing instance from a cache or return an instance of a subclass, providing more flexibility than a standard constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3ea6c421-3b1d-4601-a2d0-e31852b433ac', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''target'' in Webpack?', N'Fresher', N'The target property specifies the environment in which the bundled code will run, such as a web browser or Node.js. Webpack adjusts its output format and included polyfills based on this setting to ensure compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94c06d5a-caf6-4da3-80bb-e319b1862cd5', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Explain the concept of ''Graceful Degradation'' in architecture.', N'Senior', N'Graceful degradation involves designing a system to maintain partial functionality when certain components fail. Instead of a total outage, the system provides a limited user experience, such as disabling non-essential features, to ensure critical business operations remain accessible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a82c7f1e-d6ea-4ab5-870e-e31a932608f7', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle attribute-to-property reflection?', N'Fresher', N'Reflection allows a component to keep an HTML attribute in sync with a JavaScript property. When the property changes, Lit automatically updates the corresponding attribute on the custom element in the DOM.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fed7ce68-d080-4aa5-8cab-e31b92e2069b', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the ''Render-as-you-fetch'' pattern, and how does it compare to the traditional ''Fetch-on-render'' approach?', N'Senior', N'The ''Render-as-you-fetch'' pattern initiates data requests as soon as the navigation or component load begins, rather than waiting for the component to mount and trigger an effect. This eliminates network waterfalls, leading to a significantly faster perceived loading experience compared to the traditional fetch-on-render model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'286a953f-e1c9-4b04-98b2-e31e4bb46f82', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does the Scala compiler''s ''Tail-Recursive'' annotation act as a safety net?', N'Senior', N'The ''@tailrec'' annotation instructs the compiler to verify that a method is indeed tail-recursive and can be optimized into a loop. If the compiler cannot perform the optimization, it issues an error, preventing potential stack overflow runtime issues in production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67f360a0-be15-49f5-9b8d-e31fe7c7e074', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How does the Go runtime handle system calls that could potentially block an OS thread?', N'Senior', N'When a goroutine invokes a blocking system call, the runtime detaches the OS thread from the processor and hands it off to the blocked call, while simultaneously spawning or waking a new thread to continue executing other goroutines. This ensures that the entire scheduler does not stall while waiting for I/O completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8313a6ea-69fd-47f3-a401-e320716a53ed', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What role does the ''Session'' API play in a Remix authentication architecture?', N'Senior', N'The Session API provides a secure, server-side way to store user data across requests. By using encrypted cookies and server-side session storage, it allows the application to authenticate users securely without exposing session tokens or user details in the client-side bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9f17a84-73fe-4cab-ae9d-e3218547e499', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the ''Snitch'' component work in Cassandra?', N'Senior', N'The snitch is responsible for informing the database about the network topology, including datacenter and rack awareness. This allows Cassandra to optimize data placement and replica selection, ensuring that replicas are spread across different failure domains for high availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8c8806e-e0f2-4e3a-b425-e32258323a04', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle data types?', N'Intern', N'Because MongoDB uses BSON, it supports a wide variety of data types beyond standard JSON, including dates, regular expressions, binary data, and 64-bit integers. This allows for rich and complex data storage within a single document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8e9903f8-268c-471c-89eb-e326a41a3cd2', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is R primarily used for?', N'Intern', N'R is a programming language and environment specifically designed for statistical computing, data analysis, and graphical representation. It is widely used by statisticians and data miners for developing statistical software and performing data analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ed74b2d-835a-4c78-ad74-e32a4b7fbf8d', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your approach to handling database migrations without downtime?', N'Middle', N'I follow an additive change strategy where database schema updates are backwards compatible with the current application version. This allows me to deploy the database changes first, update the application code in a rolling fashion, and clean up deprecated columns in a later deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25dbf8aa-a5c7-4e56-adaa-e32bfa8d882f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the ''x-if'' directive, and how is it different from ''x-show''?', N'Intern', N'The x-if directive conditionally adds or removes an element from the DOM entirely based on an expression. While x-show only toggles the visibility of an element that is already in the DOM, x-if physically inserts or destroys the element in the document structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8459f4f1-2867-4bd3-acf8-e32c49add965', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is shared state in Actix-web wrapped in ''Arc'' or ''Data''?', N'Middle', N'Since handlers are executed in a multi-threaded environment, shared data must be thread-safe. Wrapping state in Arc or the Data extractor ensures that the data is safely shared and accessible across different threads without causing data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74589033-6a57-452e-9787-e32ed0593125', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'How do you prevent ''N+1'' query problems in an API endpoint?', N'Senior', N'The N+1 problem occurs when an API fetches a parent resource and then makes individual requests for each child resource. It is mitigated by using batch loading or eager loading techniques, allowing the API to fetch all related data in a single optimized query.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ea91e0f-e4ea-4fe9-a36d-e32f81eb994d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery''s ''data'' method differ from the HTML5 ''data-attributes'' API?', N'Middle', N'While jQuery''s data method reads HTML5 data attributes, it also stores data in an internal object mapping to the DOM element in memory. This means that changing data via jQuery might not reflect in the DOM, potentially leading to inconsistencies if native attribute getters are used elsewhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c9ea838-ddac-4175-86a6-e332548a4c99', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the architectural significance of Litestar''s ''Provide'' dependency injection system?', N'Senior', N'The Provide system allows for the decoupling of business logic from infrastructure concerns by injecting dependencies at the request or application scope. This promotes testability by enabling developers to inject mocks or stubs during unit tests without modifying the handler logic, and it efficiently manages resource lifecycles such as database connections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d58c4a8-2a24-4c37-bb89-e33317c27b6c', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of the restrict keyword in C pointers?', N'Middle', N'The restrict keyword is a type qualifier that tells the compiler that a particular pointer is the only way to access the object it points to within its scope. This allows the compiler to perform more aggressive optimizations, such as reordering instructions or caching values, since it knows no other pointer will modify the memory simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8027c491-5c22-4332-97de-e33345cab047', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the role of the Repository Pattern in a Laravel application?', N'Middle', N'The Repository Pattern acts as an abstraction layer between the domain logic and the data access layer. It promotes cleaner code by centralizing data retrieval logic, making it easier to swap storage implementations or mock database interactions during unit testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8680c158-c1c2-42fc-ada8-e33679f22a4b', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How do Generic type parameters affect JIT compilation and code bloat?', N'Senior', N'The JIT compiler generates specialized machine code for generic methods used with reference types by sharing the implementation across types. However, for value types, the JIT creates unique machine code for each distinct type to maximize performance, which can lead to increased memory footprint in applications using a vast array of generic combinations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3111d664-2fbd-446f-9549-e3380ffadfbc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the trade-offs of using Fastify''s ''onSend'' hook?', N'Middle', N'The onSend hook allows you to modify the payload just before it is sent to the client. While powerful for tasks like compression or encryption, it adds overhead to every response and can lead to memory pressure if handling very large payloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d497dff-fbae-4877-8264-e338b0397b4a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is SQL and what is it used for?', N'Intern', N'SQL (Structured Query Language) SQL is the standardized domain-specific, declarative language for managing and querying Relational Database Management Systems (RDBMS). Beyond legacy relational models, modern SQL dialects (e.g., PostgreSQL 18, DuckDB 1.2) now incorporate support for semi-structured data (JSONB) and vector embeddings for RAG (Retrieval-Augmented Generation) workflows. --- Core Components * DDL (Data Definition Language): Defines schema objects (e.g., CREATE, ALTER, DROP). * DML (Data Manipulation Language): Manages row-level data (e.g., INSERT, UPDATE, DELETE, MERGE). * DCL (Data Control Language): Manages authorization and security (e.g., GRANT, REVOKE). * TCL (Transaction Control Language): Ensures state consistency (e.g., COMMIT, ROLLBACK, SAVEPOINT).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02372ea1-fc5e-42c1-9637-e3399d367478', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Can Alpine.js coexist with other JavaScript frameworks on the same page?', N'Middle', N'Yes, Alpine.js can coexist with other frameworks because it operates on a localized scope and does not attempt to control the entire DOM. However, developers should be careful to avoid overlapping state management or event conflicts between the two frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d9a398e-e68f-468d-b92a-e33a989af601', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Why does Rust forbid global mutable variables?', N'Intern', N'Rust forbids global mutable variables by default to prevent data races. Allowing multiple parts of a program to change the same memory location simultaneously makes it impossible to guarantee thread safety and predictable state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c12bd865-dd1d-41cf-b7dd-e33b04eb42d8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What does ''dispatch'' mean in Redux?', N'Fresher', N'Dispatch is the only way to trigger a state change in Redux. It is a function that sends an action object to the store, which then triggers the reducer to update the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc7f17f-baae-46ef-8be8-e340f77a8386', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the z-index and how a stacking context is formed?', N'Intern', N'The z-index helps specify the stack order of positioned elements that may overlap one another. The z-index default value is zero, and can take on either a positive or negative number. An element with a higher z-index is always stacked above than a lower index. z-index can take the following values: * Auto: Sets the stack order equal to its parents. * Number: Orders the stack order. * Initial: Sets this property to its default value (0). * Inherit: Inherits this property from its parent element. Example: Live Demo: Z-Index', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33e34a05-9009-46e1-bfdc-e3449a2bfddc', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why is Micronaut''s approach to JSON serialization considered more efficient than standard libraries?', N'Senior', N'Micronaut uses compile-time generated serializers that avoid runtime reflection to inspect object fields. By knowing the structure of the classes at compile time, the framework creates highly optimized serialization paths that significantly reduce CPU cycles and garbage collection pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e65f93a3-65d2-485d-a249-e344c009048e', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach troubleshooting a distributed system experiencing intermittent latency spikes without clear error logs?', N'Senior', N'I would implement distributed tracing to visualize request flow across microservices and correlate latency with infrastructure metrics. By analyzing p99 latency distributions and comparing them against resource saturation metrics like CPU steal time or network I/O wait, I can identify bottlenecks in downstream dependencies or resource contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'707ec273-e0ef-4a6b-bdfb-e344c4505663', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does escape analysis influence Go''s memory layout and performance?', N'Senior', N'Escape analysis determines if a variable''s lifetime exceeds the scope of its function, dictating whether it is allocated on the stack or the heap. Proper utilization of this analysis reduces garbage collection pressure by keeping short-lived objects on the stack, which is faster and avoids expensive heap management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10f5fd77-a23d-468f-b6a1-e3452ac5d152', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a ''dirty read'' in the context of transactions?', N'Intern', N'A dirty read occurs when a transaction reads data that has been modified by another concurrent transaction but has not yet been committed. If the first transaction rolls back, the second transaction is left with data that technically never existed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7e0fcfb-b491-4e3e-af05-e348fdcc19a2', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the refresh interval impact Elasticsearch performance?', N'Middle', N'The refresh interval determines how often in-memory data is written to a new segment on disk to become searchable. A shorter interval allows for near real-time search but places significant I/O pressure on the system, while a longer interval improves indexing throughput at the cost of search latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94baeded-0342-4d0e-aec2-e3492ce1e663', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What does x-init do?', N'Fresher', N'The x-init directive allows you to run code as soon as a component is initialized by Alpine.js. It is commonly used for fetching initial data or setting up event listeners.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9927d0e-6dba-471c-bd90-e34935d9dd30', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus manage thread pools in a reactive environment?', N'Middle', N'In a reactive flow, Quarkus utilizes a small, fixed-size Event Loop thread pool to handle many concurrent connections without blocking. This approach is highly scalable as it avoids the overhead of creating a dedicated thread per request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62392a9e-5b19-4c34-9172-e34c4bdd7434', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What are the primary considerations when selecting between horizontal and vertical scaling for a service?', N'Senior', N'Vertical scaling is a short-term fix for immediate resource constraints on a single node, but it hits a hardware ceiling and introduces a single point of failure. Horizontal scaling is the long-term architectural goal, requiring stateless service design and robust load balancing to ensure linear capacity growth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'066e1acc-ec4d-4445-8ad5-e34f278258bd', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the architectural considerations when choosing between gRPC and REST?', N'Senior', N'gRPC offers high-performance, binary serialization via Protobuf, making it ideal for internal service-to-service communication with strict contracts. REST is preferred for public-facing APIs due to its broad compatibility, ease of caching through HTTP semantics, and human-readability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b5f4659-92bc-45f0-9639-e34fb91fa502', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What happens when a process in a Phoenix application crashes?', N'Middle', N'When a process crashes, it sends an exit signal to its supervisor. The supervisor then restarts the process based on its restart strategy, such as one-for-one or one-for-all, maintaining the stability of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a63e815-c2a7-42ed-811c-e34fdae7cf8a', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What role do Sass partials play in organizing a large-scale project''s directory structure?', N'Senior', N'Partials allow developers to break down styles into logical, small files that correspond to individual components or system sections. This modularity improves maintainability, makes it easier to navigate the codebase, and prevents the creation of massive, monolithic CSS files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
