INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0e46614-d781-43c9-93e6-e35403aa5147', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Why is Node.js considered suitable for real-time applications?', N'Intern', N'Node.js is ideal for real-time applications because its non-blocking, event-driven architecture handles high volumes of concurrent connections efficiently. This makes it well-suited for chat applications, collaboration tools, and live data streaming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3ec9fe4-7a24-4f1e-a965-e354ca5befef', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby implement encapsulation?', N'Fresher', N'Encapsulation is achieved in Ruby through the use of access control modifiers like public, private, and protected. By restricting access to internal state and methods, Ruby ensures that an object''s data is only modified through defined interfaces.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c453dad6-e5f0-451d-8410-e354cf3b9757', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the trade-offs of using a gossip protocol for cluster membership management?', N'Senior', N'Gossip protocols provide high resilience and scalability by propagating information through random peer-to-peer exchanges without a central authority. However, they suffer from non-deterministic convergence times and potential bandwidth overhead, making them less ideal for systems requiring instantaneous state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60e8504a-8e0d-48ff-aeab-e3557e6c2a2d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a segment in Elasticsearch?', N'Intern', N'A segment is an immutable internal file that stores a portion of the data within a shard. Periodically, these segments are merged into larger ones through a process called segment merging to optimize search performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
