INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'affb2058-8d90-4524-b673-e355d6a1b692', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a ''hot partition'' and why should it be avoided?', N'Junior', N'A hot partition occurs when a large volume of traffic is directed at a single partition key, exceeding its throughput limits. This leads to request throttling, as the specific partition cannot handle the high concentration of read or write requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'500aab9d-1dc6-4e28-80da-e359f4e2f822', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of a Partition Key in DynamoDB, and how does it influence performance?', N'Middle', N'The partition key is an attribute used as input for an internal hash function to determine which physical partition stores the data. If the key has low cardinality or is accessed unevenly, it causes ''hot partitions,'' leading to throttled requests and inefficient resource utilization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9efca3bd-f821-4f2a-9d65-e35baa769659', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a ''fallback'' in the context of debugging?', N'Junior', N'A fallback is a secondary path or default value that the application uses when a primary process fails. Debugging a system that uses fallbacks can be tricky because the application might appear to be working normally even when a core component is broken.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
