INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b340218-77c1-4278-9a19-e35f1a6c2193', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the Hinted Handoff feature?', N'Fresher', N'Hinted handoff is a mechanism where a node stores a ''hint'' about a write operation intended for another node that is currently unavailable. Once the failed node returns, the hint is used to deliver the missed data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd34550cb-70b6-4215-98a8-e360c043e9ea', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the purpose of a database transaction?', N'Intern', N'A transaction is a sequence of one or more database operations treated as a single unit of work. It ensures that either all operations succeed together or none of them are applied, maintaining database consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba3c668b-b7df-4e5a-843f-e3622e3e4d93', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the use case for Redis Bitmaps?', N'Middle', N'Bitmaps are space-efficient data structures used to store boolean information, such as tracking user logins or feature flags. They allow you to perform fast bitwise operations across large sets of data, making them ideal for analytics tasks like counting active users over long time periods with minimal memory overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a777e69-e34e-4e16-b8a6-e36ada640e82', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What happens if a request does not match any route in an Axum application?', N'Fresher', N'If a request does not match any defined route, Axum automatically returns a 404 Not Found response. This behavior is standard for web frameworks to indicate that the requested resource path does not exist.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c43cf69-5dfa-451e-8738-e37148db83ac', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What are Astro components?', N'Intern', N'Astro components are the building blocks of an Astro site, defined in files with the .astro extension. They are server-side templating components that do not run in the browser and are used to structure the HTML of your pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'074bb32f-66ed-4248-88bb-e371f6ea9eac', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle bean scoping?', N'Junior', N'Micronaut uses the Jakarta Dependency Injection specification to manage bean scopes. Common scopes include Singleton, which is the default, and Request or Prototype scopes, which determine the lifecycle and creation frequency of the bean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'303b70fd-cde6-434b-940a-e37263fe3245', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Why would you implement a custom middleware in Chi instead of using an existing third-party one?', N'Middle', N'Custom middleware should be implemented when you need specific behavior not provided by generic libraries, such as proprietary authentication logic or custom request tracing for observability. It allows you to tailor the request pipeline exactly to your application''s architecture without introducing external dependencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdd8a1cd-9026-4c32-afff-e375c43ea1fa', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you manage configuration changes in a large-scale system to prevent outages?', N'Senior', N'I enforce a strategy of immutable configuration, where changes are versioned and deployed alongside code. By utilizing canary releases and feature flags, I ensure that any configuration error can be rolled back instantly without requiring a full redeployment or system restart.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'511f13d9-b997-464e-a033-e376655b6354', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do Symfony''s Guard or Authenticator systems handle security tokens, and what is the benefit of this abstraction?', N'Senior', N'These systems decouple the identification of the user from the authentication logic, allowing multiple authentication methods to coexist seamlessly. This abstraction allows developers to implement complex security flows like MFA or OAuth without modifying the core user management logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9413f8c9-3189-4ee6-be62-e377519de9d6', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a user interface, what is the trade-off between providing ''power user'' shortcuts and a ''simple'' interface for beginners?', N'Fresher', N'Power user shortcuts increase efficiency for experienced users but can clutter the interface and overwhelm beginners. A simple interface is more accessible but might make frequent tasks take longer for skilled users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'91343b41-410f-4fde-8a1e-e37813c68a8e', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does the .css() method work in jQuery?', N'Junior', N'The .css() method is used to get or set one or more CSS properties of the selected elements. You can pass a single property name to retrieve its value, or pass a key-value pair to update the styling of the element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07d71271-98cc-4300-970e-e378b7f07159', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does choosing a proven technology compare to choosing a modern, trending one?', N'Fresher', N'Proven technology offers better stability, documentation, and community support, reducing project risk. Modern technology might offer better performance or new features but carries higher risk due to lack of maturity and fewer experienced developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e6cf951-ff60-45ff-bba5-e379d9cb4884', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle request routing?', N'Fresher', N'Flask uses an internal routing system that maps incoming HTTP request URLs to the specific view function defined by the developer. It matches the requested path against the registered routes to determine which function should handle the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a653311-6189-444a-9022-e37b041d648f', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What are the architectural implications of using Nuxt modules in a large-scale enterprise application?', N'Senior', N'Nuxt modules allow for modular architecture by encapsulating logic, components, and server routes into reusable packages. They improve scalability by separating concerns and promoting DRY principles, though they can introduce complexities in dependency management and build-time overhead if not properly architected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38e4616a-ad75-49bc-a4ef-e37c460aa8cb', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How does read-replica load balancing improve system performance?', N'Senior', N'By offloading read-only traffic to multiple read replicas, the primary database node is freed to handle write operations, increasing throughput. This strategy is effective for read-heavy workloads but requires the application to handle potential stale reads due to replication lag.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1648d38-c5ba-432c-8a28-e37c8b78577f', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How would you work with numbers other than those in the decimal number system?', N'Fresher', N'With Python, it is possible to type numbers in binary, octal, and hexadecimal. Binary numbers are made of 0 and 1. To type in binary, we use the prefix 0b or 0B. int(0b1010) 10 To convert a number into its binary form, we use bin(). bin(0xf) ''0b1111'' Octal numbers may have digits from 0 to 7. We use the prefix 0o or 0O. oct(8) ''0o10'' Hexadecimal numbers may have digits from 0 to 15. We use the prefix 0x or 0X. hex(16) ''0x10'' hex(15) ''0xf''', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbbb6104-c69c-40ca-82c3-e37f32dbfa08', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra differ from a traditional Relational Database Management System (RDBMS) regarding data modeling?', N'Junior', N'In an RDBMS, you typically normalize data into multiple tables to reduce redundancy and use joins to combine them. In Cassandra, you design data models based on the specific queries you need to run, often denormalizing data into a single table to avoid expensive join operations at read time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8fc979dd-51f4-4ba3-8695-e381536680a5', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How are custom error messages sent in Gin?', N'Fresher', N'Custom errors are usually sent by returning a JSON object containing the error message along with the appropriate HTTP status code. The JSON method in the context is typically used for this purpose.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ca4b360-15d5-456d-be18-e381d2b2ac5a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between ''source'' and ''library'' in R?', N'Junior', N'The ''source'' command is used to execute an R script file from the disk into the current session. The ''library'' command is used to load and attach an installed package so that its functions and datasets become available for use.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cf0034e-5229-4399-87b9-e38670c635f5', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What are the trade-offs of using Rocket''s procedural macros?', N'Middle', N'Procedural macros like route attributes simplify routing and parameter extraction but can increase compile times significantly. They also obscure the underlying transformation logic, which may make debugging more difficult for developers unfamiliar with how Rocket generates boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10b1cffe-0d67-4830-b4a5-e387bf96639f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Explain the significance of the ''Service'' trait in the Axum/Tower ecosystem.', N'Middle', N'The ''Service'' trait is the fundamental interface for request processing in Tower, defining a function that takes a request and returns a future response. By standardizing this interface, Axum allows for seamless interoperability with any middleware that follows the Service contract.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe6831c6-697e-427c-ba4b-e3894046aee8', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you approach designing a system that must handle an unpredictable, sudden spike in traffic?', N'Middle', N'I focus on architectural patterns like asynchronous processing, load balancing, and horizontal scaling. I would also implement rate limiting and circuit breakers to prevent cascading failures in downstream services, ensuring that the system remains responsive under extreme load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46045b62-f81b-4269-9be8-e38d98188c4a', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the significance of the ''Context'' object in Actix actors?', N'Middle', N'The ''Context'' object provides an actor with access to its own lifecycle, control over its mailbox, and the ability to spawn new tasks or timers. It serves as the primary interface for an actor to interact with the runtime environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f4fcfc4-201b-4242-bb3b-e38fe25fa6b5', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'How do gossip protocols influence cluster membership and failure detection in NoSQL systems?', N'Senior', N'Gossip protocols allow nodes to exchange state information periodically with a small subset of peers, spreading cluster membership and health data throughout the system exponentially. This decentralized approach avoids single points of failure and prevents the communication bottlenecks inherent in centralized heartbeat mechanisms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'274acc46-809a-4e32-8cc5-e3933bff5cab', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the number of daily active users for a new mobile application?', N'Intern', N'I would look at the total addressable market and estimate the potential conversion rate based on similar apps in the industry. I would consider factors like marketing reach, user retention cycles, and market competition. These inputs allow for a reasoned projection of the daily traffic the system should support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'577de134-7f28-4913-8339-e3942c476d20', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Compare the performance and safety trade-offs of using Scala''s Option type versus standard null references.', N'Senior', N'Using Option forces the developer to handle the absence of a value explicitly, preventing null pointer exceptions at compile time. While it introduces a slight object allocation overhead, the safety benefit in large-scale distributed systems far outweighs the marginal performance cost, as it eliminates entire categories of runtime failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1364662-2537-4525-aa3a-e3964e511310', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are ''Models'' in Lucid?', N'Junior', N'Models represent a single table in your database and provide an interface to interact with the data. They allow you to easily perform CRUD operations by treating database rows as JavaScript objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'852cc78e-5c7c-4eec-a89a-e39694a4300b', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is Type Inference, and what are its limitations?', N'Middle', N'Type inference is TypeScript''s ability to automatically deduce the type of a variable based on its initialization or usage. While it reduces boilerplate, it can sometimes be too broad, such as inferring a wider type than desired. Developers should explicitly annotate complex types to ensure intent is preserved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbf5fba7-b239-48cc-80ca-e396be1cbaf1', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Does Axum support asynchronous handlers?', N'Junior', N'Yes, Axum handlers are inherently asynchronous. They are defined as async functions, allowing the server to handle multiple requests concurrently without blocking the underlying thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f9bf34f-4604-40a5-a32f-e397be08a097', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the box-sizing property?', N'Intern', N'The box-sizing CSS property sets how the total width and height of an element is calculated. * content-box: the default width and height values apply to the element''s content only. The padding and border are added to the outside of the box. * padding-box: Width and height values apply to the element''s content and its padding. The border is added to the outside of the box. Currently, only Firefox supports the padding-box value. * border-box: Width and height values apply to the content, padding, and border. * inherit: inherits the box sizing of the parent element. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d4afc70-a29b-4c82-8350-e3987634b37b', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What are args, kwargs ?', N'Intern', N'In cases when we don''t know how many arguments will be passed to a function, like when we want to pass a list or a tuple of values, we use *args. 3 2 1 4 7 kwargs takes keyword arguments when we don''t know how many there will be: a.1 b.2 c.7 The words args and kwargs are a convention, and we can use anything in their place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9db1f952-f06e-4690-83da-e39937f80044', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you implement rate limiting in an Express application and why is it necessary?', N'Middle', N'Rate limiting is typically implemented using middleware that tracks request counts per IP address over a specific window of time. It is necessary to prevent brute-force attacks, resource exhaustion, and denial-of-service attempts by restricting the number of requests a single client can make.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a3ee8f8-b985-4880-b4a4-e3993f45891f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the main purpose of the ''Consistency'' property in ACID?', N'Middle', N'Consistency ensures that a transaction brings the database from one valid state to another, maintaining all predefined rules, constraints, and triggers. It guarantees that the database never contains incomplete or illegal data patterns even if a transaction fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7240216-c6a5-4eae-8c73-e39b6c029aa0', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the significance of the ''Module#prepend'' method compared to ''include'' in terms of method overriding?', N'Senior', N'Prepend inserts a module at the beginning of the ancestor chain, specifically before the class itself, whereas include places the module after the class. This allows prepended modules to override methods defined in the class, providing a robust mechanism for decorating or wrapping class functionality without explicit inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09c5d746-3b85-4005-ae92-e39e8c0f1c1d', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the copy-and-swap idiom improve exception safety?', N'Middle', N'The copy-and-swap idiom creates a temporary copy of the data, modifies it, and then swaps the temporary with the current object''s internal state. This ensures that if an exception occurs during the copy process, the original object remains unchanged, providing strong exception safety.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f93fccf1-54aa-4224-917d-e39e9467a96d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s sound null safety differ from non-sound systems?', N'Middle', N'Sound null safety ensures that a variable cannot be null if it is not explicitly marked as nullable. The compiler and runtime cooperate to guarantee this property, meaning that if a variable is typed as non-nullable, it is impossible for it to hold a null value at any point.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aec75dcf-3a61-4038-a549-e3a205ce49d1', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the architectural difference between Alpine''s ''data'' components and ''stores''?', N'Senior', N'Data components are scoped to specific DOM trees and are ephemeral, while stores are global and persistent throughout the application lifecycle. Components are best for localized UI logic, whereas stores are intended for cross-component communication and shared application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'261d8e29-0e31-452d-9e01-e3a2b58a5929', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the significance of the class attribute in R?', N'Junior', N'The class attribute determines how generic functions behave when applied to an object. It allows R to implement object-oriented programming, where different classes trigger different specific methods for the same generic function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b8e4ca2-a8f9-491e-9f29-e3a562192f2b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the Hono ''Validator''?', N'Intern', N'The Hono validator is a middleware feature that checks incoming request data against defined rules or schemas. If the data is invalid, it can automatically reject the request before it reaches the business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c40e973e-b84a-48ee-b992-e3a74c356cd6', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you manage configuration settings across different environments in Gin?', N'Middle', N'Configuration is best managed by utilizing environment variables or external configuration files, which are loaded during the initialization of the Gin engine. This ensures that sensitive credentials and environment-specific settings are decoupled from the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48703b4c-847c-49fe-bc62-e3a891ac04b6', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a pointer and a variable in C?', N'Fresher', N'A standard variable holds a direct value, such as an integer or a character, at a specific memory location. A pointer is a special type of variable that stores the memory address of another variable instead of a data value. Pointers allow for dynamic memory management and enable functions to modify variables defined outside their own scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd3c61e21-b987-4788-8567-e3a93b9b683f', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to verify assumptions during the problem-solving process?', N'Fresher', N'Assumptions are a common source of error because they are often based on outdated or incomplete information. Verifying them ensures that the solution is based on reality rather than guesswork, which reduces the risk of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b35d9ec1-6254-4639-a188-e3aa53eac91f', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of the COMMIT command?', N'Junior', N'The COMMIT command is used to permanently save the changes made during the current transaction to the database. Once committed, the changes are visible to other users and cannot be undone via a rollback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e9bdbfc-3308-4573-bbb7-e3abb0cb7235', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the trade-offs between vertical and horizontal scaling in a distributed architecture.', N'Senior', N'Vertical scaling increases the capacity of an existing node, which is simpler but limited by hardware ceilings and single points of failure. Horizontal scaling adds more nodes to the system, providing better fault tolerance and near-infinite capacity, but introduces significant complexity regarding data consistency and network partitioning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8f8d08a-a6a3-48c0-ba9a-e3ac27d4a5dd', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'How does jQuery handle cross-browser compatibility?', N'Intern', N'jQuery abstracts the differences between various web browsers by providing a consistent API. It handles the nuances of how different browsers implement JavaScript features, allowing developers to write one set of code that works reliably across all major browsers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'852e32f6-aa65-4712-895f-e3ad39eb7a40', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the trade-off of using RefCell or interior mutability?', N'Middle', N'RefCell allows for mutable data even when the outer structure is immutable, but it shifts borrow checking from compile-time to runtime. The trade-off is that it introduces a risk of runtime panics if borrow rules are violated, whereas standard ownership rules would have caught the error during compilation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
