INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e39284f6-7fb9-48ac-bccf-e3b98940f35c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''const'' keyword impact memory allocation and performance in Dart?', N'Senior', N'The ''const'' keyword ensures that an object is canonicalized and created at compile-time, meaning it is allocated in the read-only section of the binary. This reduces heap allocation pressure and garbage collection frequency, as identical constant objects share the same memory reference throughout the application lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
