INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88bdf612-f3c5-410e-96dd-e3c8c8ec7e23', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift ensure thread safety with value types?', N'Middle', N'Because value types are copied rather than shared, they are inherently thread-safe as each thread operates on its own unique instance. This prevents data races that occur when multiple threads try to modify the same reference-type object simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cb5ebcf-6d40-45ef-9afe-e3cad885f286', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain the concept of ''ActionController::Parameters'' and why it is critical for application security.', N'Senior', N'It implements ''strong parameters,'' which forces developers to explicitly whitelist attributes allowed for mass assignment. This prevents malicious users from injecting unauthorized parameters into the database, effectively neutralizing mass-assignment vulnerabilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b76b97a-d746-4d6c-93d1-e3d33209194b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How do secondary indexes impact Cassandra performance?', N'Middle', N'Secondary indexes can be inefficient because they require querying multiple nodes to find data that is not part of the partition key. They are generally recommended only for low-cardinality data and should be avoided for high-traffic or large-scale analytical queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0fcdb77-621d-4587-927f-e3d6965cbe30', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are observers in Ember?', N'Intern', N'Observers are a mechanism that allows a piece of code to run automatically whenever a specific property changes. While powerful, they are used sparingly in modern Ember compared to computed properties.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82bb9313-e2fa-4043-92b8-e3dbf66ea538', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of rate limiting in an API?', N'Middle', N'Rate limiting protects backend services from being overwhelmed by excessive requests from a single user or bot. It ensures fair usage, prevents resource exhaustion, and helps mitigate certain types of denial-of-service attacks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38c5729c-c089-4108-9037-e3deecd2ff59', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the Read Uncommitted isolation level?', N'Intern', N'Read Uncommitted is the lowest isolation level where transactions can see uncommitted changes from other transactions. While it offers the highest performance, it is prone to dirty reads, non-repeatable reads, and phantom reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aea6e048-1425-4cbf-a79c-e3e1892d2595', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''untrack'' and when should you use it?', N'Middle', N'The untrack utility allows you to execute code without establishing a reactive dependency relationship between the signals accessed and the current effect. It is useful in scenarios where you need to read a signal''s value without triggering a re-run of the surrounding scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18867c59-4ea9-4a93-9ef5-e3e2a3aaa300', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of using Quarkus for microservices?', N'Intern', N'Quarkus allows microservices to start up rapidly and use very little memory, which significantly reduces cloud infrastructure costs. Its fast development cycle also increases developer productivity when managing many small, independent services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
