INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9bf896b-2b68-46ea-bc12-e3e7a4d5ca4a', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors should you consider when choosing a file format, like JSON versus XML, for data exchange?', N'Fresher', N'Consider the readability of the format and the support in your programming environment. JSON is generally preferred for web applications due to its lightweight structure and native compatibility with JavaScript, while XML might be chosen for legacy systems or complex documents requiring strict schema validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
