INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b653a0a-976a-487f-9d93-e3f33c0398ce', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Explain the difference between optimistic and pessimistic concurrency control in distributed transactions.', N'Senior', N'Pessimistic concurrency control uses locks to prevent conflicts before they happen, ensuring data integrity but potentially reducing throughput and increasing deadlock risks. Optimistic control assumes conflicts are rare, allowing transactions to proceed without locking and checking for violations only at commit time, which improves performance in read-heavy systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
