INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caef54e8-38c0-4068-8902-e40239fccb03', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Discuss the difference between internal and external linkage in terms of symbol visibility.', N'Senior', N'Internal linkage limits the visibility of a symbol to the current translation unit, while external linkage allows the symbol to be accessed from other translation units. Proper management of linkage is crucial for reducing binary size, preventing naming conflicts, and allowing the linker to optimize the final executable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f1bed88-18f3-45fd-8c8b-e40582d00db3', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What happens if a message broker goes down and persistence is not enabled?', N'Middle', N'If persistence is disabled, all messages currently stored in memory will be lost. The system will suffer from downtime for the duration of the broker outage, and any unconsumed messages that were in the queue will need to be re-sent by the producers if they maintain their own buffer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c99404c4-c7f7-46d0-a582-e407d8eb0dfc', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the benefit of using ''signals'' in Flask, and what is a common architectural risk?', N'Senior', N'Signals allow decoupling of components by enabling one part of the application to broadcast events that other parts can listen to. The risk is that they can make the application flow non-linear and difficult to debug, as it becomes unclear which side effects will be triggered by a specific action.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
