INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fea1604-9f81-435b-80a2-e40e28f6f576', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the main benefit of SolidJS''s compilation process?', N'Fresher', N'The compilation process allows SolidJS to optimize the application by converting JSX templates into highly efficient DOM operations. This minimizes the amount of overhead and allows the framework to achieve high performance with a small bundle size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36dd7f99-5389-4e4b-bf3d-e4119bb4dcfd', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle concurrent write conflicts?', N'Senior', N'DynamoDB follows a last-writer-wins policy by default for standard writes. To handle complex concurrency, developers must implement condition expressions or transactional operations to enforce business-specific consistency rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3c4adfe-48eb-4408-aec6-e41308a9acf8', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What does asynchronous programming (async/await) mean in the context of FastAPI?', N'Intern', N'Asynchronous programming allows the server to handle multiple incoming requests concurrently without waiting for a single long-running task to complete. This is particularly useful for I/O-bound operations like database queries or calling external APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd28fabca-70c2-4b51-a92a-e413fdf4ab81', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the significance of the ''Consistency'' property in ACID?', N'Middle', N'Consistency ensures that a transaction brings the database from one valid state to another, maintaining all predefined database rules, constraints, and cascades. It guarantees that the database state remains logically correct according to business logic after any successful or failed transaction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca356961-92e5-40aa-ad3c-e41780aec8dd', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'How does Ruby''s exception handling mechanism impact performance?', N'Middle', N'Raising and rescuing exceptions in Ruby is a computationally expensive process because it involves capturing the backtrace and unwinding the stack. Consequently, exceptions should be reserved for truly exceptional, non-recoverable events rather than standard flow control. Using exceptions for logic control can significantly degrade application throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be4f64ec-4973-439c-bf04-e4196a0022d5', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are stored procedures?', N'Junior', N'A stored procedure is a prepared collection of SQL statements stored within the database. It allows developers to execute complex logic with a single call, reducing network traffic and improving security by preventing direct table access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3362475d-f87e-424a-b9ac-e4199c8dd47f', N'4c000000-0000-0000-0000-000000000005', N'Describe the difference between monolithic and microservices architecture.', N'Middle', N'A monolith is a single, unified codebase where all functions are tightly coupled, making it easier to deploy initially but harder to scale or modify. Microservices break the application into independent, loosely coupled services, enabling teams to scale and deploy specific components independently at the cost of increased operational overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0141713-e69f-440d-92ca-e41a0b20e559', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What are the implications of running Remix on an Edge runtime compared to a traditional Node.js environment?', N'Senior', N'Running on the Edge reduces latency by placing compute closer to the user, which is ideal for Remix’s server-side logic. However, developers must be mindful of limitations in the Edge runtime, such as the absence of certain Node.js APIs or persistent file system access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f9ae58b-01f2-49b0-abbc-e41c1f1aa1f0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are Modifiers in Ember?', N'Fresher', N'Modifiers are a way to perform DOM-related tasks on an element, such as adding event listeners or integrating third-party libraries. They help keep DOM manipulation logic separate from component state logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdc2dc98-a0a4-416d-9c14-e41ddd2e1d7b', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'Explain the role of the ''Circuit Breaker'' pattern in maintaining system resilience.', N'Senior', N'The circuit breaker pattern prevents a system from repeatedly attempting an operation that is likely to fail, such as a timed-out remote service call. By tripping the circuit, the system fails fast and allows the downstream dependency to recover, preventing cascading failures across the architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97bab5c4-4ec1-40d9-b92e-e42250f639e2', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How do Phoenix LiveView''s state-diffing mechanisms optimize bandwidth usage?', N'Senior', N'LiveView tracks state changes and sends only the minimal set of diffs over the WebSocket connection rather than the entire rendered template. This drastically reduces the data transferred per update, allowing for efficient UI synchronization even over high-latency or low-bandwidth networks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8910897-1a50-4caf-8bc7-e4234ed7ff94', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS prevent the ''stale closure'' problem common in other frameworks?', N'Senior', N'Because SolidJS components execute only once and rely on signals for data access rather than capturing variables in closures for rendering, stale closures are largely avoided. By reading signals directly in the template or within effects, the system ensures the most current value is always accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c3cad91-7994-4aaf-a2b1-e4237aaae788', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does the DynamoDB TTL (Time to Live) feature impact storage costs and performance?', N'Senior', N'TTL automatically deletes expired items in the background without consuming write throughput or affecting table performance. This reduces storage costs over time by pruning stale data without requiring manual delete operations or complex batch management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
