INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fade4c4-7ad1-4dd8-b553-e424aaf8539e', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket''s use of ''Macros'' influence the developer experience?', N'Senior', N'Rocket uses procedural macros to eliminate boilerplate code, such as manual JSON deserialization or path parsing. While this creates a powerful DSL-like experience, it requires developers to understand the generated code structures to effectively debug or extend the framework''s behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd17186bd-b9c1-485c-bd00-e4253902f3e3', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between call-by-value and call-by-reference?', N'Intern', N'Call-by-value passes a copy of a variable''s data to a function, meaning changes made inside the function do not affect the original variable. Call-by-reference passes the address of the variable, allowing the function to directly access and modify the original value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'771edd17-9d2c-4d92-986a-e4270a6c46dd', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the primary purpose of the Phoenix framework?', N'Junior', N'Phoenix is a web framework built on Elixir designed for creating productive, scalable, and maintainable web applications. It leverages the Erlang VM to handle high concurrency and provide fault-tolerant systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8d1e238-8fcb-4e59-ba0b-e428303ca47f', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What is the benefit of Chi''s context usage?', N'Intern', N'By using the standard library''s context, Chi ensures that request-scoped data is handled safely across concurrent goroutines. It also makes it easier to integrate with other libraries that expect standard context usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a6ff4fc-e1ed-461a-a535-e429f80c70ed', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the significance of the viewport meta tag in mobile-responsive design?', N'Middle', N'The viewport meta tag instructs the browser on how to control the page''s dimensions and scaling on different devices. Without it, mobile browsers often render the page at a desktop width and shrink it, resulting in tiny text and poor readability. It is essential for ensuring that media queries function correctly and that the layout adapts to the physical screen size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57963f15-190f-4b97-998f-e42a55135b5f', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the function of the ''resolve.alias'' configuration option?', N'Middle', N'The resolve.alias option allows developers to create shorter or more meaningful import paths for frequently used directories. This prevents the need for complex relative path structures like deep directory nesting and makes the codebase cleaner and easier to maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'66fdcfbc-4bbe-4637-9983-e42fd080dbe9', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between shallow and deep copying in Python?', N'Middle', N'A shallow copy creates a new object but inserts references into it for the objects found in the original, meaning nested structures remain shared. A deep copy recursively constructs a new object and then inserts copies of the objects found in the original, ensuring no shared references exist between the original and the new container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cffa0f61-7ec6-4f5e-93ba-e43181d7c930', N'954a0331-deff-4399-b588-96f39fec001d', N'What is safe navigation operator?', N'Intern', N'The safe navigation operator(?)(or known as Elvis Operator) is used to guard against null and undefined values in property paths when you are not aware whether a path exists or not. i.e. It returns value of the object path if it exists, else it returns the null value. For example, you can access nested properties of a user profile easily without null reference errors as below, Using this safe navigation operator, Angular framework stops evaluating the expression when it hits the first null value and renders the view without any errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4e1a78b-f8ec-46ed-b1c6-e4321033da5b', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS handle horizontal scalability when managing session state?', N'Senior', N'AdonisJS defaults to memory stores for development but requires externalized session stores like Redis or databases for production. To scale horizontally, sessions must be offloaded to a shared, centralized store to ensure that stateless application nodes can process subsequent requests from the same user regardless of which node receives the traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99148b20-2f18-4fcc-82f5-e4336510d63e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How is memory managed in Python?', N'Fresher', N'Python memory is managed by Python private heap space. All Python objects and data structures are located in a private heap. The programmer does not have an access to this private heap and interpreter. Like other programming language python also has garbage collector which will take care of memory management in python.Python also have an inbuilt garbage collector, which recycle all the unused memory and frees the memory and makes it available to the heap space. The allocation of Python heap space for Python objects is done by Python memory manager. The core API gives access to some tools for the programmer to code. Python has a private heap space to hold all objects and data structures. Being programmers, we cannot access it; it is the interpreter that manages it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddc7b508-e06a-4b44-b3c6-e43510be8def', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the purpose of the ''static styles'' property?', N'Intern', N'The static styles property is a class field used to define CSS rules that apply to the component. Because it is static, Lit parses these styles once per class definition rather than per instance, which improves performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'703e6faf-35f5-4f66-8d41-e4358ff9cebd', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between a synchronous view and an asynchronous view in Flask 2.0+?', N'Middle', N'Synchronous views block the worker thread while waiting for I/O operations, whereas asynchronous views use ''async'' and ''await'' to allow the event loop to handle other requests while waiting for I/O. Asynchronous views are more efficient for applications with high-latency network or database calls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9837e01-44cb-4503-98d9-e43682b9a243', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the layered architectural pattern?', N'Senior', N'The Layered Architecture Pattern is characterized by the hierarchical organization of the software components into distinct layers, each serving a specific role and potentially necessitating communication with adjacent layers. It''s also known as the N-Tier Architecture or the Multi-Tier Architecture. Key Components - Layers: The logical groupings of software elements that collaborate to perform specific tasks or operations. There can be any level of separation, with most applications distinguishing between three primary layers: Presentation, Business Logic, and Data. - Inter-Layer Communication: Layers communicate with one another in a strictly defined order.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67d6c104-8295-4756-bcc4-e4370db662fb', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the purpose of the ''Either'' type?', N'Junior', N'Either is used to represent a value that can be one of two possible types, often used for error handling. By convention, ''Left'' is used to hold an error or failure message, while ''Right'' holds the successful result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'249a54c6-9256-4732-8d4b-e43aa6d6b6d9', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are the trade-offs of using Litestar''s ''Before Request'' and ''After Request'' hooks for cross-cutting concerns?', N'Senior', N'These hooks provide powerful interception points for logging, metrics, or authentication, but if overused, they can obscure the request execution flow and make debugging difficult. They are ideal for cross-cutting concerns, but should be avoided for core business logic to maintain architectural transparency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
