INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaae5d6e-e9ab-49fa-a254-e44560b38a52', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Describe the difference between optimistic and pessimistic locking in the context of Redis transactions.', N'Senior', N'Redis uses an optimistic locking approach via the WATCH command, which monitors keys for changes; if a watched key is modified before the transaction executes, the transaction fails. Pessimistic locking is not natively supported, so developers must implement distributed locks using algorithms like Redlock to prevent concurrent access to shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
