INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c47a1bb-b628-4677-939d-e44dab577606', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do Scala''s path-dependent types influence the architectural design of complex systems?', N'Senior', N'Path-dependent types allow a type to be bound to a specific instance of an object rather than just its class. This enforces strict encapsulation and type safety in modular systems, ensuring that members belonging to one instance cannot be interchanged with those of another, effectively preventing structural logic errors at compile time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
