INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3eb4b273-5501-4eb9-bf7b-e462a10deccd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is recursion in JavaScript?', N'Intern', N'Recursion is a technique in which a function calls itself until it reaches a base case (a condition that stops further calls). Every recursive function must have a base case to avoid infinite loops and stack overflow errors. Example 01: Factorial Example 02: Fibonacci Example 03: Flatten a nested array Recursion vs Iteration: * Recursion is more readable for tree/graph traversal, nested structures, and divide-and-conquer problems * Iteration is more performant for simple loops — use it when recursion depth could be large *Note: For deeply nested structures, iterative solutions with an explicit stack are preferred over recursion to avoid stack-overflow errors.*', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c5f6864-6792-47d0-b231-e46a4d699007', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you know when a bug is truly fixed?', N'Fresher', N'A bug is fixed when the reported issue is no longer reproducible under the same conditions. Additionally, I verify that the fix has not introduced new regressions in related parts of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e4148a9-15f4-447c-a43e-e46ba391bab4', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of ''Dependency Injection'' and why it is used in C# applications.', N'Middle', N'Dependency Injection is a design pattern where a class receives its dependencies from an external source rather than creating them itself. This promotes loose coupling, makes code easier to maintain, and significantly simplifies unit testing by allowing the injection of mock objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01455108-be2d-42b8-94b4-e46bb139f0c7', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the role of Middleware in Axum?', N'Junior', N'Middleware in Axum allows you to intercept requests and responses to perform common tasks like logging, authentication, or error handling. Because Axum is built on Tower, you can use any Tower-compatible middleware in your application pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28f7a3ae-5175-44fb-8fa4-e46f6d9e711e', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Explain the role of the ''PostCSS'' ecosystem in the Tailwind build pipeline.', N'Senior', N'PostCSS acts as the engine that parses Tailwind’s directives and transforms them into standard CSS through plugins. It enables Tailwind to perform tasks like auto-prefixing, nesting, and minification as part of a modular build pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2f93733-ace4-42c7-8b29-e46fbda6211f', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the difference between a Route Handler and a Middleware?', N'Intern', N'A route handler contains the specific business logic for a single endpoint. Middleware performs cross-cutting concerns, such as authentication or rate limiting, that apply to multiple requests globally or to specific groups of routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'57cb55e3-924b-4aa0-b25e-e470169dfff3', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What does the @RestController annotation do?', N'Intern', N'It is a specialized version of @Controller that combines @Controller and @ResponseBody. It tells Spring that every method in the class should return data directly as a response body, typically in JSON or XML format, rather than a view template.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'678b4168-0fb5-4056-9a4a-e4705d68901b', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle props?', N'Intern', N'Props in SolidJS are reactive objects that provide access to data passed from a parent component. Because they are reactive, you should use helper functions like splitProps or mergeProps to maintain reactivity when deconstructing them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00817455-0395-4fe7-a063-e472abaf8aae', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the concept of ''Eventual Consistency'' and when it is acceptable.', N'Senior', N'Eventual consistency guarantees that if no new updates are made to an object, eventually all accesses will return the last updated value. It is acceptable in systems where high availability and low latency are prioritized over immediate data accuracy, such as social media feeds or product recommendations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb8e0a3e-0e6b-4f44-a13d-e47318aa0dec', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the benefit of using Concurrent Mode in React 18+?', N'Senior', N'Concurrent Mode allows React to prepare multiple versions of the UI simultaneously without blocking the main thread. This enables features like transition interrupts, where lower-priority updates are paused to prioritize urgent user interactions, resulting in a smoother perceived performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd065c28-c43f-498f-9eb4-e4749997c9a5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass handle color manipulation, and why is this useful for dynamic theming?', N'Senior', N'Sass provides built-in color functions that allow for programmatic adjustments like lightening, darkening, or saturating colors. This is highly effective for building theme systems where you derive secondary, hover, or focus states from a base brand color palette, ensuring color harmony throughout the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
