INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47cdb9f2-592c-4a75-b81c-e47a76dfd797', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you optimize inter-service communication latency?', N'Senior', N'Minimize network hops by optimizing service placement and using high-performance protocols like gRPC for internal traffic. Implement connection pooling and persistent connections to reduce the overhead of handshake establishment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1e114eb-9962-442d-9b30-e47c4ffaf6a8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the role of the DynamoDB Accelerator (DAX) and when should it be used?', N'Middle', N'DAX is a fully managed, highly available, in-memory cache for DynamoDB that delivers microsecond latency for read-heavy workloads. It should be used when an application requires extremely fast read performance or when there is a need to reduce the read load on the base table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15b57f0b-c869-442a-824f-e47cada541c4', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the purpose of the final keyword when applied to a class or method?', N'Junior', N'When applied to a class, the final keyword prevents other classes from inheriting from it. When applied to a method, it prevents that method from being overridden by any child classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'502fd3ed-62a3-46cc-b309-e47d9011fd30', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Discuss the trade-offs of using SvelteKit''s ''prerendering'' feature versus dynamic SSR.', N'Senior', N'Prerendering generates static HTML files at build time, offering superior performance and scalability for content that doesn''t change per user. Dynamic SSR provides fresh data per request, which is necessary for personalized content but introduces server-side overhead and higher latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95f1c132-4575-47d9-aedc-e47db7e37c69', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are lists in Redis and what are some common operations you can perform on them?', N'Intern', N'Redis provides a standalone list data structure known as Redis List, which is operationally efficient for working with ordered collections. Lists in Redis are: - Dynamic in sizing, expanding or shrinking as elements are added or removed respectively. - Indexed, which means elements within a list are accessible based on a 0-based index. Key Operations Add Elements - LEFT PUSH (LPUSH): Adds an element at the head of the list. - RIGHT PUSH (RPUSH): Adds an element at the tail of the list. Remove Elements - LEFT POP (LPOP): Removes and returns the element at the head of the list. - RIGHT POP (RPOP): Removes and returns the element at the tail of the list. Range Operations - RANGE: Provides a range of elements based on index positions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e8aeaea-8286-472a-a283-e47e5457b60c', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If a system is running slowly, how would you begin to identify the bottleneck?', N'Intern', N'You should start by monitoring system resources like CPU, memory, and disk usage to see if any component is hitting its limit. If resources are normal, analyze the flow of the request to identify which specific process or external service is taking the longest to complete.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'061cc6d0-a532-42d9-aac1-e47e65cbbfce', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is ''Cache Poisoning'' and how can it be mitigated in an API gateway layer?', N'Senior', N'Cache poisoning occurs when an attacker manipulates requests to force the cache to store malicious or incorrect responses that are then served to other users. Mitigation involves strictly defining cache keys based on authorized parameters and validating response headers to ensure sensitive data is never cached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
