INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c35780cc-2893-4fd6-a0e7-e484902307fa', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the significance of the ''readonly'' modifier in TypeScript and how does it prevent mutation?', N'Senior', N'The ''readonly'' modifier prevents reassignment of properties after initialization, which is crucial for maintaining immutability in state management. While it is a compile-time check, it helps prevent accidental side effects and makes intention clear, though it does not provide deep immutability by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb77bbcd-90cd-461f-b7c7-e4888fd9ff40', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'How does Phoenix leverage the Erlang VM''s scheduler to handle high-concurrency workloads?', N'Senior', N'The Erlang VM uses a preemptive, multi-threaded scheduler that manages thousands of lightweight processes. Phoenix capitalizes on this by isolating each user request or channel connection in its own process, ensuring that long-running tasks do not block the execution of other concurrent operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f7e41f95-fc0b-46da-a4dc-e48ad6419226', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What happens when you perform a full-text search in Elasticsearch?', N'Junior', N'When a search request is made, Elasticsearch uses analyzers to process the query string into tokens. It then looks up these tokens in the inverted index to find the relevant documents, scoring them based on how well they match the query criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53744baa-b368-4649-afb7-e48b722f06f3', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the primary purpose of Next.js in the context of React?', N'Intern', N'Next.js is a React framework that enables server-side capabilities such as server-side rendering and static site generation. It simplifies building full-stack web applications by providing built-in routing, performance optimizations, and backend API routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0e3494f-647c-40e8-af8b-e48e0954ead6', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are stuck on a problem for a long time, what is your strategy for breaking through?', N'Intern', N'I switch to a different task for a while or physically step away to reset my focus. Often, the subconscious mind continues to work on the problem, and a fresh return to the task can provide the clarity needed to see the solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b772c9b8-cf4d-4e97-975f-e48e5c900f01', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of a tombstone in Cassandra, and what potential performance issues can it cause?', N'Middle', N'A tombstone is a marker used to record the deletion of data, as Cassandra performs updates via append-only logs rather than in-place modifications. An excessive number of tombstones can degrade read performance because the database must scan through them during query execution, leading to increased latency and potential timeouts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd25c198d-b6f8-46aa-aff8-e49354027974', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'How does a message queue help in smoothing out traffic spikes?', N'Middle', N'A queue acts as a buffer between a high-traffic producer and a slower consumer. During a spike, messages accumulate in the queue, allowing the consumer to process them at a steady, sustainable rate rather than crashing under the load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c88a8c6-0b20-44b7-af12-e495fa10847c', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the JIT compiler in Tailwind CSS?', N'Intern', N'The JIT (Just-In-Time) compiler generates CSS on-demand as you author your HTML. Instead of generating every possible CSS variation upfront, it only creates the styles you actually use, resulting in smaller file sizes and faster build times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'076db1e5-97a3-4a4a-b452-e49638c06db0', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the role of the ''Provide'' dependency injection system in Litestar?', N'Junior', N'The dependency injection system allows developers to inject shared resources, like database sessions or authentication services, into route handlers. This promotes cleaner code by decoupling business logic from the instantiation of common utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d9a0e29-61e1-4320-a326-e49689a099e6', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite optimize performance for large-scale applications?', N'Middle', N'Vite employs code splitting, where dynamic imports are automatically converted into separate chunks. This ensures that only the necessary code is loaded for a specific route, reducing the initial load time and bandwidth consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'640929eb-bbd0-43d2-8a62-e497ac8fcade', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is state in React?', N'Intern', N'_State_ of a component is an object that holds some information that may change over the lifetime of the component. The important point is whenever the state object changes, the component re-renders. It is always recommended to make our state as simple as possible and minimize the number of stateful components. !state Let''s take an example of User component with message state. Here, useState hook has been used to add state to the User component and it returns an array with current state and function to update it. Whenever React calls your component or access useState hook, it gives you a snapshot of the state for that particular render.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd6cf0cc-61fb-4bf4-929f-e49cd514ae62', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is CORS in the context of FastAPI?', N'Intern', N'CORS stands for Cross-Origin Resource Sharing and is a security feature that controls which domains can access your API. FastAPI provides a built-in middleware to configure these settings and allow or restrict cross-origin requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce6077e9-ec26-44a1-bee6-e49f6d95a983', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What are nullable types in C#?', N'Intern', N'Nullable types are a special data type in Cthat can represent both a regular value and null. It is a beneficial feature for representing data that might be absent or unknown. Key Considerations for Using Nullable Types - Memory Consumption: Data types with explicit sizes, such as int or bool, need more space in memory when converted to nullable types. - Performance: Nullable types might result in fewer optimizations, particularly with certain operations. - Clarity: They offer transparency about the possible absence of a value. The "null-conditional" operators In C#, there are dedicated "null-conditional" operators caters to appropriately performing actions for nullable types, ensuring that there is no NullReferenceException. Among these are ?., ??, ??=, and ?.[].', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'713abe85-1f90-4aae-b560-e4a20d61f76b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the role of the ''Registry'' in a Phoenix application, and why is it preferred over global process naming?', N'Senior', N'The Registry provides a way to locally register processes under a specific key, which prevents the bottleneck and potential single-point-of-failure associated with global process registries. It allows for efficient process lookup and message routing within a node while avoiding name collisions across a distributed Erlang cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87e87fcf-5707-4acd-ae1a-e4a21b99b01a', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit ensure type safety between the server-side data loaders and the client-side components?', N'Senior', N'SvelteKit automatically generates TypeScript definitions for the data returned by load functions. This provides end-to-end type safety, ensuring that components receive the expected data structures and reducing runtime errors caused by API schema changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7a4c6a1-6264-42e0-aa05-e4a41b8d9bb9', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What are the considerations for tree-shaking when using barrel files?', N'Senior', N'Barrel files, which re-export many modules from a single file, can inadvertently break tree-shaking if the bundler cannot determine which individual exports are unused. Because all exports are imported into the barrel file, Webpack may be forced to include the entire dependency tree of the barrel file, even if only one module is consumed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbc450dd-d798-4110-9e93-e4a4b3ef644d', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is a Projection Expression in a query?', N'Junior', N'A Projection Expression allows you to specify only the attributes you want to retrieve from a table. This reduces the amount of data transferred and lowers the read capacity consumption compared to retrieving the entire item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e12e994a-077e-4ad5-969f-e4a54f12f953', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the alignment requirement in memory management?', N'Middle', N'Alignment ensures that data types are stored at memory addresses that are multiples of their size, which is critical for hardware performance. Misaligned access can force the CPU to perform multiple memory cycles for a single read, significantly degrading performance or triggering hardware errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bcdf3d7-5aa6-4d46-8cf6-e4aaf408c659', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between using a centralized configuration store versus environment variables?', N'Middle', N'Environment variables are simple and standard across all platforms, but they can be difficult to manage at scale and are not easily updated without restarting services. A centralized configuration store allows for dynamic updates and complex versioning but introduces a dependency on an external system and adds architectural complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7acd845f-c89e-45de-b95a-e4abd7a2bd2d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What happens if a route handler returns a type that does not implement the Responder trait?', N'Fresher', N'The code will fail to compile. Rocket enforces at compile time that every route must return a type that can be converted into a valid HTTP response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1b91e23-b151-4ae0-9cd1-e4ac99f3dc83', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a Deadlock in a database system?', N'Junior', N'A deadlock occurs when two or more transactions are waiting for each other to release locks on resources. Neither transaction can proceed, and the system must intervene, usually by aborting one of the transactions to break the cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b6c8939-f304-4b69-914e-e4adb2115cd0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind support the implementation of design tokens from tools like Figma?', N'Senior', N'Tailwind''s configuration file acts as an integration point where design tokens from Figma can be mapped directly to the framework''s theme settings. This creates a bridge between design and code, ensuring that changes in the design system are propagated to the CSS utility classes automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c89c6b7a-bd70-4ec5-b4e8-e4aeac4c9bcf', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'Discuss the implications of using native addons (C++) in Node.js regarding binary compatibility and deployment.', N'Senior', N'Native addons provide high performance but introduce complexity in deployment as they must be compiled against the specific version of V8 and Node.js ABI. Changes in the underlying engine or Node.js upgrades often require re-compilation, increasing the risk of runtime crashes if binary incompatibilities are not managed through strict CI/CD pipelines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9281d3f-0069-482e-ad87-e4b40a3e9d2c', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the benefits of using buffers instead of standard strings for binary data?', N'Middle', N'Buffers are memory-efficient because they represent raw memory outside the V8 heap. They are essential for handling binary data streams efficiently, as they avoid the overhead of converting data into JavaScript string objects repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ba9dc02-35e1-4ab6-be6a-e4b4bdff6267', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are portals in React?', N'Intern', N'A Portal is a React feature that enables rendering children into a DOM node that exists outside the parent component''s DOM hierarchy, while still preserving the React component hierarchy. Portals help avoid CSS stacking issues—for example, elements with position: fixed may not behave as expected inside a parent with transform. Portals solve this by rendering content (like modals or tooltips) outside such constrained DOM contexts. * child: Any valid React node (e.g., JSX, string, fragment). * container: A real DOM node (e.g., document.getElementById(''modal-root'')). Even though the content renders elsewhere in the DOM, it still behaves like a normal child in React. It has access to context, state, and event handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6baa5798-9810-4049-b318-e4b65e71c458', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the Eloquent ORM in Laravel, and why is it useful for database interactions?', N'Junior', N'Eloquent is an Object-Relational Mapper that allows you to interact with your database using PHP syntax instead of writing raw SQL queries. It maps database tables to model classes, making it easier to perform CRUD operations while keeping the code readable and maintainable. Additionally, it provides built-in features for handling relationships between tables, such as one-to-many or many-to-many associations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b48e28fc-ca42-4ae6-939e-e4b6b5da437b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why is it important to use ''Sequence'' for large collection processing?', N'Middle', N'Sequences provide lazy evaluation, meaning operations are performed one by one across the entire collection rather than creating intermediate result collections at every step. This can significantly improve memory efficiency and performance when chaining multiple operations on large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8a5e60b-2f1f-4b3f-b8ca-e4b72844f1cf', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it better to ask for help early rather than struggling alone for days?', N'Intern', N'Asking for help early prevents wasted time and frustration, and it keeps the project timeline on track. It is a sign of good professional judgment to recognize when an obstacle requires external input to overcome efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3538998a-950b-437f-ae46-e4b75786fd9c', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is a cookie in Fiber?', N'Intern', N'A cookie is a small piece of data stored on the client side that the server sends during a request. Fiber provides methods to set, read, and delete cookies to manage session state or user preferences.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f7fee09-3273-4694-b869-e4b90f1818f9', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the best way to re-render a component?', N'Intern', N'The best way to force Vue to re-render a component is to set a :key on the component. i.e, Whenever the component to be re-rendered, just change the value of the key then Vue will re-render the component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42a44248-c578-4d50-a914-e4b92972b808', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How can you mitigate the ''N+1 query problem''?', N'Middle', N'The N+1 problem occurs when an application executes one query to fetch a parent record and then executes additional queries for each child record. It can be mitigated by using eager loading or joining tables to retrieve the necessary data in a single, more efficient operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c67c912a-e547-4df2-b271-e4b97f056f99', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What architectural strategies help prevent ''Cascading Failures''?', N'Senior', N'Strategies include implementing timeouts, using circuit breakers, employing bulkheads to isolate resources, and using rate limiting to throttle incoming requests. These patterns collectively prevent a single failing component from depleting system resources like thread pools or memory across the entire stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65f389ff-250d-40f7-98a3-e4b986df78bd', N'075b8862-431c-4678-9767-f55359758a4a', N'What is teleport?', N'Intern', N'The component allows you to render a part of your component''s template into a different location in the DOM — outside the current component''s hierarchy. Example: 1. Wrap teleport component around the modal template inside app.vue file 2. Render modal component inside main index.html file In Vue 2, this functionality was possible via the community plugin portal-vue Use cases 1. Modals 2. Toasts 3. Tooltips 4. Context menus 5. Dropdowns 6. Anything that needs to break out of DOM nesting', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d9edeb0-433f-4826-ae6a-e4b9af051d83', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why should you avoid using Sass for runtime-determined values?', N'Senior', N'Sass is a preprocessor, meaning all its logic is executed during the build step, not in the browser. It cannot access runtime data like window dimensions or dynamic user settings, so attempting to force Sass to handle these values is fundamentally flawed compared to using CSS variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cc67400-8439-4648-b22f-e4bd023a875a', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify''s plugin registration order affect the application''s runtime behavior?', N'Senior', N'The order of registration determines the order of execution for hooks and setup logic. Because Fastify processes registrations sequentially, a plugin registered later may depend on a capability provided by an earlier, parent-scoped plugin.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7109dacb-9d7d-4b98-bade-e4befa869876', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is a header file in C and what does it contain?', N'Fresher', N'A header file typically has a .h extension and contains function declarations, macro definitions, and data type definitions. It is used to share these definitions across multiple source files by using the include directive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64dc208f-8986-4166-9f14-e4c0be532dc3', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it generally considered bad practice to put business logic into ActiveRecord models?', N'Senior', N'Placing business logic in models leads to ''Fat Models,'' which are difficult to test, maintain, and reason about. Moving logic to Service Objects or Domain Models keeps the application layer clean and follows the Single Responsibility Principle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b7748ea-8877-4003-9c14-e4c1a59d6693', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS''s authentication system facilitate the implementation of Role-Based Access Control (RBAC)?', N'Senior', N'AdonisJS provides a flexible authentication contract that can be extended to integrate user roles and permissions into the request context. By decoupling the auth provider from the application code, security policies can be enforced globally via middleware, ensuring consistent authorization checks across the entire API surface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca528efb-6a94-45d3-85d2-e4c29310d26b', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the significance of the ''fetcher'' hook in complex Remix applications?', N'Senior', N'The fetcher hook allows developers to interact with loaders and actions without triggering a full page navigation. It is essential for building complex UI components like sidebars, global search inputs, or independent widgets that need to perform mutations or data fetches in isolation from the main route transition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c379e5d0-5916-4760-b0ed-e4c4a5dfbc55', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to get query parameters in React Router v4?', N'Fresher', N'The ability to parse query strings was taken out of React Router v4 because there have been user requests over the years to support different implementation. So the decision has been given to users to choose the implementation they like. The recommended approach is to use query strings library. You can also use URLSearchParams if you want something native: You should use a _polyfill_ for IE11.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0aaa7c99-d538-4442-8fd9-e4c4e21f1e86', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind''s specificity model work with standard CSS?', N'Middle', N'Tailwind utility classes are designed with a flat specificity model, meaning that the order in which classes appear in the CSS bundle determines which style wins if there''s a conflict. This is why Tailwind generates CSS in a specific order: base, then components, then utilities, to ensure utilities always have the final say.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1058519-6fd2-4d32-bbc8-e4c5279cb46e', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Why is it important to clear the cache during development?', N'Junior', N'Symfony caches configuration, routing, and service definitions to improve performance. During development, changes made to these files might not be reflected until the cache is cleared, ensuring the application uses the most up-to-date configuration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d85f66c-0589-4577-aef8-e4c96f38ccaa', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is an Actor in the context of the Actix framework?', N'Fresher', N'An actor is an independent unit of computation that maintains its own state and communicates with other actors by sending and receiving messages. In Actix, actors are the fundamental building blocks used to manage concurrency and state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'757f95fb-01f4-4ed3-aa7d-e4cbd0b3f9fd', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the purpose of a CDN (Content Delivery Network) in web scalability?', N'Middle', N'A CDN caches static content like images, CSS, and JavaScript files on globally distributed edge servers. This reduces latency for users by serving content from a location physically closer to them and offloads traffic from the origin server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f9c387a-6de1-4138-aee4-e4cd090e9e28', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @extend directive?', N'Fresher', N'The @extend directive allows one selector to inherit the styles of another selector. This is useful for sharing common base styles between different elements, resulting in more efficient and less repetitive CSS output.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c27027d-7015-444c-aa37-e4d113c5d521', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Why is Micronaut suitable for cloud-native development?', N'Intern', N'Micronaut is suitable for cloud-native development because of its low memory footprint and fast startup times, which are essential for ephemeral environments like serverless functions. It also includes built-in support for distributed tracing, service discovery, and configuration management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d52c28e-f036-4778-a15f-e4d350fd8d79', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of the ''super'' keyword?', N'Fresher', N'The ''super'' keyword is used to refer to the immediate parent class object. It is used to call parent class constructors or to access methods and fields that have been overridden or hidden by the subclass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1805c159-263b-4b58-a576-e4d48675b4f7', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the performance trade-offs of using Chi''s radix tree router compared to a standard map-based look-up.', N'Senior', N'Chi''s radix tree implementation optimizes memory usage and lookup speed by sharing common prefixes among routes. While a simple map lookup is O(1), it suffers from high memory overhead and lacks support for path parameters, whereas the radix tree provides O(k) complexity, where k is the path length, offering a superior balance for complex API routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17a41ec1-c4e1-4000-be7b-e4d8efd6cbd2', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''Form'' component in Remix?', N'Intern', N'The Form component is a wrapper around the standard HTML form tag. It enhances the native form behavior by automatically managing submission states and triggering data revalidation on the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7e86d8f-fb10-4ede-8273-e4da51378492', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does the Go runtime handle stack management, and what are the implications for goroutine scalability?', N'Senior', N'Go uses segmented stacks that start small and grow dynamically as needed by copying the stack to a larger memory segment. This allows the runtime to support hundreds of thousands of concurrent goroutines with minimal memory overhead, avoiding the fixed-size thread stack limitations found in traditional operating system threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45d25c7f-54d3-41bb-ba0d-e4dc7cd4322a', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What role does the ''container'' play in enabling lazy loading of services in AdonisJS?', N'Senior', N'The container supports deferred loading, where services are only instantiated when they are actually requested by the application. This reduces initial startup time and memory usage, as only the core components necessary for a specific request cycle are loaded into memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2842ba6f-4e3f-4691-add4-e4dd709ded4d', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the concept of recycling in R.', N'Junior', N'Recycling occurs when performing operations on two vectors of unequal length. R automatically repeats the shorter vector until it matches the length of the longer one to complete the operation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28808ff3-b6c7-45b5-9d2c-e4e073d503d0', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Can you use standard Maven or Gradle with Quarkus?', N'Intern', N'Yes, Quarkus provides plugins for both Maven and Gradle. These plugins are essential for managing dependencies, triggering build-time optimizations, and launching the application in development mode.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'040fd7d3-4b86-49ef-b6ea-e4e144213feb', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are struggling with a task for a long time, at what point do you ask for help?', N'Fresher', N'I set a personal time limit for independent problem-solving, such as thirty minutes or an hour. If I am still stuck after that time, I ask for help to ensure I do not waste unnecessary time and to keep the project moving forward.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ade30da9-c457-4e92-bb46-e4e3373cb0f7', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the benefit of using a CDN for jQuery?', N'Intern', N'Using a CDN can improve performance because the file may already be cached in the user''s browser from another site. It also offloads the bandwidth requirement from your own server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83082044-0070-4a4e-97ff-e4e4a5a1ba12', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Describe the mechanism Gin uses for request binding and the potential performance bottlenecks involved.', N'Senior', N'Gin uses reflection-based binding to map request data into structs. While convenient, heavy reliance on reflection during binding can introduce latency; for high-throughput systems, pre-validating or using manual parsing can mitigate the CPU overhead associated with the reflection engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0989492-a607-4bd4-9184-e4e6fb260cbd', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is the purpose of the ''useLayoutEffect'' hook, and why should it be used sparingly?', N'Senior', N'useLayoutEffect fires synchronously after all DOM mutations but before the browser paints, allowing for DOM measurements and visual adjustments before the user sees the screen. It is performance-intensive because it blocks the browser''s painting process, which can lead to visual lag if the logic inside is not highly optimized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcb7dd2e-7e10-4509-ab78-e4eac6d636a4', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Discuss the trade-offs of using ''Group Replication'' versus traditional asynchronous replication.', N'Senior', N'Group replication provides built-in high availability and automatic failover via a consensus protocol, ensuring data consistency across the cluster. Traditional asynchronous replication offers lower latency and higher write throughput but requires external orchestration tools to manage failover and does not guarantee zero data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9781cead-6975-4a56-912c-e4ecbbb304b4', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the primary purpose of semantic HTML?', N'Junior', N'Semantic HTML uses tags that convey the meaning of the content rather than just its visual appearance. This improves accessibility for screen readers and helps search engines understand the structure and hierarchy of your web page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'573cf325-a400-45d5-9348-e4edbe0b54a1', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Describe the difference between ''sideEffects'' in package.json and the ''TerserPlugin'' optimization.', N'Senior', N'The ''sideEffects'' flag is a hint to Webpack that a module contains no top-level code that modifies the global state, allowing the bundler to skip it entirely if its exports are unused. TerserPlugin, however, is a minifier that performs dead-code elimination within the module content, removing code that is unreachable or logically redundant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fc3eb04-64d1-4cf0-919d-e4eed71d7405', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does the rendering performance of Preact compare to React in deep component trees?', N'Middle', N'Preact often outperforms React in deep component trees due to its simpler reconciliation algorithm and reduced overhead per component. Without the complex fiber architecture, Preact can process updates faster, provided the application does not rely on advanced React features that would require the compatibility layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'879ffc28-61aa-4865-bc15-e4efb356756d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a connection pool?', N'Intern', N'A connection pool is a cache of database connections maintained so that the connections can be reused when future requests to the database are required. Actix-web applications often use these to avoid the overhead of creating a new connection for every request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36eed79a-f035-4a6c-89d1-e4f01f3c969e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose a relational database over a NoSQL database for an application?', N'Fresher', N'A relational database is preferred when data integrity and complex relationships are critical, such as in financial systems. It uses a rigid schema that ensures ACID compliance, making it ideal for structured data where consistency is non-negotiable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43806187-8f1a-4c8c-9dba-e4f54870376b', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Does Preact require a specific build tool or configuration?', N'Junior', N'While Preact works with most modern bundlers like Vite, Webpack, or Rollup, it is designed to be highly flexible. It does not require a specific framework-level CLI, though tools like Preact CLI exist to help bootstrap projects quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
