INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ae42547-be79-43f6-975c-e4fbbfcce7bb', N'075b8862-431c-4678-9767-f55359758a4a', N'How to make router param changes as reactive?', N'Fresher', N'When you navigate from one URL to other(mapped with a single component) using routes with params then the same component instance will be reused. Even though it is more efficient than destroying the old instance and then creating a new one, the lifecycle hooks of the component will not be called. This problem can be solved using either of the below approaches,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8a8d337-9455-4d8f-ae03-e4fbed4d5b32', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django URLconf?', N'Fresher', N'A URLconf is a set of patterns that maps URLs to specific view functions. It acts as a routing table that tells Django which view to execute when a user visits a particular path in the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24cc1f4e-716a-449b-84fe-e4fd39ff7bb0', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is a Django application?', N'Intern', N'A Django application is a Python package that provides a specific set of features within a project. It is designed to be modular and reusable across different projects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b77ab18-67fc-4bc5-8014-e4ff99c34de0', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is observability crucial in distributed systems?', N'Middle', N'Distributed systems are complex and prone to intermittent failures, making it difficult to trace requests across multiple services. Observability tools like distributed tracing, logging, and metrics provide the visibility needed to identify the root cause of issues quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b1f5945-a332-4fe2-be96-e500509018e4', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are the advantages of using Fastify''s ''Reply'' object over the standard Node.js ''http.ServerResponse''?', N'Middle', N'The Reply object provides a high-level, chainable API that abstracts away complex header management and chunked encoding details. It also integrates natively with Fastify''s serialization and error handling pipelines, resulting in cleaner and more maintainable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccae4f68-50c5-42f3-9f02-e5016dc59e67', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''worker_threads'' module?', N'Middle', N'The worker_threads module enables the execution of JavaScript in parallel on separate threads. It is designed for CPU-intensive tasks that would otherwise block the main event loop, allowing for better performance without needing to spawn separate processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c94b45f3-9e1e-43d9-8442-e501eb1829a7', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Describe the role of the ''volatile'' keyword in memory model guarantees and instruction reordering.', N'Senior', N'The volatile keyword prevents the compiler and the CPU from reordering memory access around the marked field. It ensures that reads and writes are performed directly to memory, providing a lightweight synchronization mechanism that guarantees freshness across threads without full lock contention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'329ff956-a9b6-43cb-b2d0-e502415c2e69', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you pass data from a controller to a view?', N'Fresher', N'In Ruby on Rails, the primary way to transfer data from the controller to the view is by using instance variables. Using Instance Variables Setting Data in the Controller Here, @article is accessible within the show view. Accessing Data in the View You can directly display data in views: Limitations - Global visibility: All instance variables set in a controller''s action are available to the corresponding view. This can be a cause of accidental data leakage and can make code harder to follow. - Lack of Context: Misuse of instance variables can sometimes lead to difficulty in understanding which action set a variable currently being used in the view. Tips and Best Practices - Keep it As Needed: Only fetch and set data needed for the specific view being rendered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a74004b-c488-4520-8351-e5031ea93bf8', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'In what scenario would you choose Micronaut''s ''Introspected'' annotation?', N'Senior', N'The @Introspected annotation is used when you need to enable reflection-free access to a class''s properties, such as for JSON serialization or data binding. It is especially useful for DTOs or entity classes when using native images where standard reflection would fail or be inefficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd35b32f0-6599-4562-9627-e504b17c5dd2', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you ensure data consistency across microservices?', N'Senior', N'Data consistency in a microservices architecture is crucial for ensuring that business-critical operations are executed accurately. Approaches to Data Consistency in Microservices 1. Synchronous Communication: Via REST or gRPC, which ensures immediate consistency but can lead to performance issues and tight coupling. 2. Asynchronous Communication: Using message queues which ensure eventual consistency but are more resilient and performant. 3. Eventual Consistency with Compensating Actions: Involves completing a series of potentially inconsistent operations within a microservice and compensating for any errors, often orchestrated through a dedicated event handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'650a4fa1-0cd0-4265-97cd-e50899f38759', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How does Axum handle routing compared to other frameworks?', N'Junior', N'Axum uses a declarative routing system where routes are defined as part of a Router object. It allows for nesting routers, which helps in organizing code by grouping related endpoints together.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c5708aa-00ad-4b16-a9b9-e5091711efd3', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What are the common strategies for handling global exceptions in a Spring Boot REST API?', N'Middle', N'The most common and clean approach is to use a @ControllerAdvice class combined with @ExceptionHandler methods. This allows you to centralize error handling logic across all controllers, ensuring consistent error responses and status codes are returned to the client regardless of where the exception occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
