INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a65264f7-6fe3-47d1-b3d0-e5138bded702', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Describe the trade-offs of using Hono’s built-in ''Validator'' middleware versus custom validation logic.', N'Senior', N'Built-in validation offers seamless integration and type inference, which significantly speeds up development and improves maintainability by keeping the schema close to the endpoint definition. The trade-off is a potential dependency on specific validation libraries, which may offer less granular control compared to hand-written validation logic for highly specialized, non-standard request structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc897c3f-15f5-43fb-a24f-e513a4a0b8b7', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of the API Gateway pattern?', N'Middle', N'An API Gateway acts as a single entry point for all client requests, routing them to the appropriate microservices. It handles cross-cutting concerns like authentication, SSL termination, rate limiting, and request transformation, which simplifies the client-side interaction and centralizes security policies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7a284ff-227f-4df3-9012-e513c7419fac', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does event forwarding work in Svelte components?', N'Middle', N'Event forwarding is achieved by using the ''on:'' directive without a handler value. This allows a component to pass events from its internal elements to its parent, facilitating cleaner component composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'98826261-1dc4-4724-b4d4-e5181be298a8', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the advantage of using Tailwind over inline styles?', N'Intern', N'Unlike inline styles, Tailwind utility classes support hover states, responsive design, and design tokens like consistent spacing and color palettes. It maintains the benefits of a structured design system while keeping HTML clean and readable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2bb89256-abbb-4a56-a3cc-e5183bdd9b9a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Can Elasticsearch handle real-time data?', N'Fresher', N'Yes, Elasticsearch is designed for real-time search. As soon as a document is indexed and refreshed, it becomes searchable, making it suitable for monitoring and log analysis applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28794fa5-46d4-4100-85c0-e518b8f425c7', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket facilitate testing of endpoints?', N'Middle', N'Rocket provides a local client module that allows you to dispatch requests to your application without needing to bind to a physical network port. This enables fast, isolated integration tests that verify routes, guards, and handlers in a realistic environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab884e6a-6de4-431b-a05a-e518ea957b1e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit ensure type safety in property declarations?', N'Senior', N'Lit uses TypeScript decorators to define property types, which provides compile-time checks for property assignments. This ensures that the data passed to components matches expected formats, reducing runtime bugs and improving developer experience through IDE autocompletion and static analysis.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83a91c25-efe2-427b-829b-e51ae1139021', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between a copy constructor and a move constructor?', N'Middle', N'A copy constructor creates a duplicate of an existing object, requiring resources to be copied or allocated. A move constructor transfers ownership of resources from a temporary object to the new object, which is significantly more efficient as it avoids deep copying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fa6e1b3-96b3-4a28-b6ba-e51aeb00913d', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why might a query plan change from an Index Scan to a Sequential Scan even when an index exists?', N'Middle', N'The PostgreSQL query planner may switch to a sequential scan if it determines that fetching the data via the index is too expensive, usually because the query retrieves a large percentage of the table. In such cases, the overhead of random I/O from the index exceeds the cost of a full table scan.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20c14aba-0bea-4a05-91a3-e51b3ea40760', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the benefit of using Echo''s group routing for multi-tenant application architectures?', N'Senior', N'Group routing allows for the hierarchical organization of routes and the application of middleware specifically to subsets of the API. This is ideal for multi-tenancy as it permits per-tenant authentication and rate-limiting policies to be applied consistently without duplicating code across routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'888fb43b-f9cc-4bec-a72b-e51ced3b6a5c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why would you choose Preact over React for a project?', N'Junior', N'You would choose Preact if performance and small bundle size are critical requirements, such as for mobile-first web apps or small widgets. It is also a great choice if you prefer a simpler API that sticks closer to standard web development patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'814c6536-37ce-4d1e-8da8-e51d48a32936', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is it important to choose a good partition key?', N'Junior', N'A well-chosen partition key ensures that data is evenly distributed across all nodes in the cluster. If the key is poor, some nodes may become ''hot'' with too much data, leading to performance bottlenecks and uneven disk usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c19e80a9-b35b-4bd4-ab77-e51f163e595c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What strategies do you use to ensure zero-downtime deployments?', N'Senior', N'Utilize blue-green or canary deployment strategies that allow for traffic shifting and immediate rollback. Ensure that database schema changes are backward-compatible and decoupled from application code deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8eea70ea-0d44-4aaa-b111-e51fcb797191', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Why is the production mode different from the development mode?', N'Intern', N'Production mode focuses on optimization, minification, and performance, resulting in smaller and faster-running bundles. Development mode focuses on build speed, detailed error reporting, and debugging features, which are not necessary for the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e903b28-2cae-4841-a5a2-e522bf9c9066', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why might you choose a BRIN index over a B-Tree index?', N'Middle', N'BRIN indices store summary information like minimum and maximum values for blocks of data, making them extremely small and efficient for massive, naturally ordered tables like time-series data. They are not suitable for high-cardinality columns where B-Tree indices provide much faster random access performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10bddb79-df11-4796-a95f-e52773b1112d', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'In what scenario would you choose Server-Side Rendering (SSR) over Static Site Generation (SSG) in an Astro project?', N'Senior', N'SSG is preferred for content-heavy sites where data changes infrequently, as it generates files at build time. SSR is necessary when the application requires real-time data, user-specific authentication, or dynamic content that must be fetched per request, which cannot be pre-computed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3aba5997-ef1e-4dbf-a8a7-e52b10e625f7', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the C standard library''s malloc/free model often insufficient for high-performance systems?', N'Senior', N'The standard malloc/free model is general-purpose and must handle a wide variety of allocation sizes, which can lead to heap fragmentation and contention in multi-threaded applications. High-performance systems often implement custom memory allocators, such as pool allocators or slab allocators, to improve cache locality and reduce locking overhead. This allows the system to tailor memory management to the specific access patterns of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fca4978-746a-47df-ae47-e52d35cff69a', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik compare to React Server Components (RSC)?', N'Middle', N'While both aim to reduce client-side JS, RSC focuses on server-side rendering of components and streaming. Qwik goes a step further by removing the need for a hydration phase entirely through its resumability model, making the client-side footprint much smaller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8f1055ea-6db2-4a11-8762-e52e8d3f3cd4', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between batch processing and stream processing for data analytics?', N'Middle', N'Batch processing is simpler to implement and debug for large datasets where real-time results aren''t necessary. Stream processing provides immediate insights and reacts quickly to events, but requires more complex infrastructure and is harder to manage regarding late-arriving data and exactly-once processing guarantees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64adc7d1-041c-49f3-b318-e52ed8a7015d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do circuit breakers improve system reliability?', N'Middle', N'A circuit breaker prevents an application from repeatedly trying to execute an operation that is likely to fail. By failing fast, it prevents resource exhaustion in the calling service and allows the failing downstream service time to recover.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f028d701-0ac9-4838-adee-e52f482eda45', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do Middleware functions in Next.js impact the request/response lifecycle?', N'Senior', N'Middleware runs before a request is completed, allowing for logic such as authentication, URL rewrites, or header modification. Because it executes at the edge, it enables low-latency global routing decisions before the request reaches the main application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20c174d7-4999-41e4-9bc4-e52f4d0552d7', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the difference between synchronous and asynchronous logging, and how does it affect reliability?', N'Middle', N'Synchronous logging writes logs immediately to disk, which is safer for data persistence but can block application performance. Asynchronous logging buffers logs in memory before writing them, improving performance but risking the loss of recent logs if the application crashes unexpectedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d77aa24-faf5-4395-8942-e53000acfd33', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Describe the difference between an iterable and an iterator in Python.', N'Senior', N'An iterable is any object that implements the __iter__ method and can return an iterator, whereas an iterator is an object that implements both __iter__ and __next__. The iterator maintains internal state to track its position during iteration, allowing it to yield values one by one.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'996f1bad-9c87-4a4b-ae5c-e53734f37fd1', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When choosing an authentication mechanism, what are the trade-offs between stateful sessions and stateless JWTs?', N'Senior', N'Stateful sessions are easier to revoke and manage centrally but require shared state storage that can become a bottleneck. Stateless JWTs scale better across distributed services but introduce challenges regarding token revocation and the risk of embedding too much sensitive data in the payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ed166b9-6fa5-4e01-a265-e538506c4596', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you determine if a feature request is worth implementing?', N'Intern', N'I evaluate the feature based on its alignment with user needs, the effort required for development, and the potential impact on the product''s overall goals. I would look for data or user feedback to support the necessity of the feature. Ultimately, it is a balance of cost versus the value it provides to the end user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1f25726-54dd-4398-b029-e53990876ea8', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you upgrade angular version?', N'Fresher', N'The Angular upgrade is quite easier using Angular CLI ng update command as mentioned below. For example, if you upgrade from Angular 7 to 8 then your lazy loaded route imports will be migrated to the new import syntax automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7112871-032e-4c3a-89f4-e53acdba0405', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What are the common HTTP methods used with the Elasticsearch REST API?', N'Fresher', N'Elasticsearch uses standard HTTP methods: GET to retrieve data, POST to add or update data, PUT to create or replace data, and DELETE to remove data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a56baf71-1d8b-4f80-ab31-e53c731ddc8c', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Explain the concept of Streaming in Next.js.', N'Middle', N'Streaming allows you to break down a page into smaller chunks and progressively render them as they become ready on the server. This prevents the entire page from being blocked by a slow data fetch, improving the perceived loading performance for users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'babf80c8-f015-4985-b9c9-e54293f612e8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB achieve high performance at scale?', N'Middle', N'DynamoDB achieves performance by storing data on SSDs and partitioning it across multiple servers. By forcing specific access patterns through partition and sort keys, it ensures that every operation has a predictable, single-digit millisecond latency regardless of the table size.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a1ba49b-673e-4f22-a792-e5464ba24035', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why is ''Durability'' challenging to guarantee in distributed cloud environments?', N'Middle', N'Durability requires that data be written to non-volatile storage before a transaction is confirmed. In distributed systems, this is complicated by network delays and the need to replicate data across multiple physical disks or nodes to survive hardware failures, which increases latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'479921bf-3d0e-4904-8436-e5473e7db56e', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the difference between a ''sequential scan'' and an ''index scan'' in terms of I/O cost.', N'Senior', N'A sequential scan reads the entire table from disk, which is efficient for small tables or when a large percentage of rows must be returned. An index scan uses the index to find specific row locations, which is highly efficient for retrieving small subsets of data but can be slower than a sequential scan if the table is small or the result set is large.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48660c9f-371f-49d6-8790-e5489fedee81', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB differ from a traditional Relational Database Management System (RDBMS)?', N'Fresher', N'Unlike an RDBMS, which relies on fixed tables with predefined columns and complex joins, DynamoDB is schema-less and designed for high-speed, predictable performance. It does not support complex SQL joins, focusing instead on simple key-based access patterns to manage large amounts of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2cfc7f5d-4d40-4b01-961c-e54ae7f24564', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do NoSQL databases typically handle transactions compared to RDBMS?', N'Middle', N'RDBMS typically enforce ACID properties across multiple tables with strong consistency. Many NoSQL databases prioritize BASE properties, offering atomic operations at the row or document level but lacking native support for multi-document ACID transactions, often shifting this logic to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cdc3713-21d1-44ee-a671-e54c3e7f4942', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript differ from JavaScript in terms of execution?', N'Junior', N'TypeScript is a superset of JavaScript that cannot be executed directly by browsers or Node.js. It must be compiled or transpiled into standard JavaScript before it can run in an environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fcd8543-24c1-4416-ab22-e54dd946acac', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you handle graceful shutdowns in an Echo-based application to ensure no inflight requests are dropped?', N'Senior', N'You should use the Shutdown method provided by the Echo instance in combination with a signal listener for OS interrupts. This ensures the server stops accepting new connections while allowing existing requests to complete, effectively preventing data inconsistency or half-processed transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da32e0aa-7063-4e53-b8d2-e54e671a225d', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'When would you choose Chi over a high-performance framework like Gin?', N'Senior', N'You would choose Chi when you prefer a framework that sticks strictly to the standard library''s net/http interface, avoiding the ''framework lock-in'' associated with Gin''s custom context objects. Chi is ideal for teams that value interoperability and wish to use standard Go patterns rather than framework-specific abstractions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'289c21de-87b7-4411-9baf-e551623739cf', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono achieve type safety without requiring a complex build step?', N'Middle', N'Hono leverages TypeScript''s inference capabilities and provides a robust RPC (Remote Procedure Call) mechanism. By sharing the application interface between the server and the client, it allows for end-to-end type safety without manual API contract synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'16a6ae9d-c5c6-451a-8c27-e55354921231', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the significance of database sharding?', N'Middle', N'Sharding is the process of partitioning a large database horizontally into smaller, faster, and more manageable pieces called shards. It improves performance and scalability by distributing the data and the query load across multiple database servers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'368f6489-513f-4d6b-969a-e5554fbb13cc', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala handle lazy initialization?', N'Fresher', N'Scala uses the ''lazy val'' keyword to delay the initialization of a variable until the first time it is accessed. This is efficient for expensive operations that might not be needed in every execution path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6ad8564-363a-4993-9f4c-e55969eb88d2', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do index signatures work in TypeScript?', N'Middle', N'Index signatures allow you to define types for objects where property names are not known in advance, such as dictionaries. You define the key type, usually string or number, and the value type, which ensures that any dynamic property added to the object conforms to that value type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5658c5e3-cc57-4213-8c79-e55a55cb5ca1', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How would you design a multi-tenant application in Laravel using a shared database architecture?', N'Senior', N'You can implement multi-tenancy by adding a ''tenant_id'' column to all tables and creating a Global Scope that automatically filters queries based on the authenticated tenant. This approach requires careful indexing and ensures that cross-tenant data leakage is prevented at the framework level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68ab55ec-3e02-47cc-8b45-e55b6ffe3a92', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What are ''route handlers'' in the context of Litestar?', N'Junior', N'Route handlers are functions or methods decorated to process incoming HTTP requests. They represent the endpoints of your application, where you define the logic to process data and return a response to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1e3d96b-368e-4f0b-b752-e55c62a70017', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What are the advantages of using Micronaut''s ''Introduction Advice'' compared to traditional AOP?', N'Senior', N'Introduction Advice allows developers to define an interface and have the framework automatically implement it at compile-time. This is highly efficient for pattern-based implementations like repositories or clients, as it eliminates the need for manual boilerplate or complex runtime proxying.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1873712f-3ca3-41a2-b90f-e55d93bdbeed', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When selecting a data structure, what is the common trade-off between searching speed and insertion speed?', N'Fresher', N'Some structures like Hash Maps offer O(1) search time but may require overhead for rehashing during insertions. Other structures like linked lists allow O(1) insertion but require O(n) time for searching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31736f3a-3ed4-4ace-90bb-e55e1b16f760', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does the Kestrel web server''s architecture differ from traditional IIS hosting models?', N'Senior', N'Kestrel is a cross-platform, event-driven, asynchronous I/O server designed for high performance and low overhead, running directly within the application process. In contrast, traditional IIS hosting often relies on the ASP.NET module to proxy requests, which adds additional overhead and architectural complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd673664-76bb-4307-a1d4-e55ee0f4bb41', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the IntoResponse trait in Axum?', N'Fresher', N'The IntoResponse trait defines how a specific type can be converted into an HTTP response. By implementing this trait, custom data structures can be returned directly from handlers, and Axum will automatically handle the conversion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8db0dc5-93b0-48f2-a434-e560b844bb97', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does a Redis List work?', N'Fresher', N'A Redis List is a linked list of strings. It allows for efficient insertion and removal of elements from both the head and the tail of the list, making it useful for queues and message processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbb5e0b0-8afe-41eb-b68e-e56174f8bab7', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the primary difference between SvelteKit''s ''load'' functions in server-side versus client-side execution?', N'Middle', N'Server-side load functions run on the server during the initial request, allowing direct database access and sensitive API calls. Client-side load functions run in the browser during navigation, meaning they can only access public APIs or data already available in the browser context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2843e82-bdfe-4db7-b196-e561ffa8d8fd', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is it important to use const for pointers whenever possible?', N'Middle', N'Using const provides a clear contract that the data pointed to will not be modified, which enhances code readability and safety. Furthermore, it allows the compiler to perform optimizations and can prevent accidental side effects, making the code more robust.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'61ce6aa8-82db-4df1-bfc6-e5638fa0a518', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'Why would you choose to use Elasticsearch for log storage?', N'Junior', N'Elasticsearch is ideal for log storage because it handles massive streams of unstructured data and provides high-speed search capabilities. When combined with tools like Kibana, it allows teams to visualize logs, perform real-time trend analysis, and troubleshoot issues quickly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
