INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2723fe5a-a354-43f2-84ca-e564c55083f9', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is C called a middle-level language?', N'Fresher', N'C is considered a middle-level language because it combines the low-level capabilities of assembly language, such as direct memory manipulation, with the high-level features of structured programming languages. This makes it suitable for both system programming and application development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8fe37d6-11ad-401b-a2d5-e5655ac32994', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the limitations of multi-document transactions in sharded clusters?', N'Senior', N'Multi-document transactions in sharded clusters incur high performance overhead due to the coordination required across multiple shards and nodes. They also impose limits on the duration and the amount of data modified, and they cannot be used for operations that affect the cluster metadata, such as collection creation or dropping.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1b10065a-cd51-4087-9dcb-e56730a26ee0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Why use Echo''s ''Group'' over defining individual routes?', N'Middle', N'Using groups promotes DRY (Don''t Repeat Yourself) principles, especially when applying shared prefix paths or common middleware like authentication. It makes the routing table easier to read and maintain as the application scales.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ddcd12f-6bd2-4c46-ba5c-e567a37552db', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does ''Atomicity'' mean in ACID?', N'Fresher', N'Atomicity ensures that all operations within a transaction are treated as a single ''all or nothing'' unit. If any part of the transaction fails, the entire transaction is aborted, and the database state remains unchanged.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'645c9bc9-4b94-4cba-abb5-e568002ee2c0', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s architecture facilitate better tree-shaking than component-based frameworks that rely on a large runtime?', N'Senior', N'Because Svelte does not ship a large, generic runtime library, only the code required for the specific components and features used in an application is included in the final bundle. This granular control allows modern bundlers to perform much more effective tree-shaking compared to frameworks where the entire core library must be loaded.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
