INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21a221cc-8c80-46ff-a9a7-e56f37545a81', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What is the significance of ''Consistent Hashing'' in distributed cache clusters?', N'Senior', N'Consistent hashing minimizes the amount of data movement required when adding or removing cache nodes from a cluster. By mapping nodes and keys onto a logical ring, it ensures that only a small fraction of keys need to be remapped during scaling events, maintaining system stability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
