INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c4ae1a6-853f-434a-9944-e5704e69a894', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why is ''deadlock detection'' necessary, and how is it typically handled?', N'Senior', N'Deadlocks occur when two transactions wait for each other to release locks, causing a system halt. Databases typically handle this by maintaining a wait-for graph or using timeouts to detect cycles and automatically aborting one of the transactions to break the deadlock and allow others to proceed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
