INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10eb5561-1cc4-4d11-afd2-e574a1c98b33', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is Django Middleware and when is it executed?', N'Intern', N'Middleware is a series of hooks in Django''s request and response processing system that allows you to globally alter the input or output of the application. It sits in a layer between the web server and the view function. Middleware is executed during every request before it reaches the view, and again during the response phase before it is sent back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
