INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83b87e22-6e4b-4857-bf01-e5971d2e69ae', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain how Rails handles optimistic locking and its impact on database performance.', N'Senior', N'Optimistic locking adds a version column to the table and checks it before every update to prevent race conditions. It is highly performant in low-contention environments as it avoids database row-level locks, but it can lead to frequent retries and poor user experience in high-write scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50feb537-6415-4d15-b554-e597bbb46427', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is data revalidation in Remix?', N'Fresher', N'Data revalidation is the process where Remix automatically re-runs your loaders after an action is performed. This ensures that the data displayed on the screen is always up-to-date with the database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
