INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'efb4cfea-4e1e-4b92-8cc1-e5a3d4b8c9e1', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the ''useFetch'' hook in Nuxt?', N'Intern', N'useFetch is a built-in composable used for fetching data from an API. It handles the request lifecycle, manages loading states, and ensures that the data is correctly fetched during server-side rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33012a54-7eef-45ea-91c5-e5a5864352e3', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the limitations of the Preact diffing algorithm?', N'Middle', N'The diffing algorithm is optimized for speed and size, which means it lacks some of the complex prioritization and scheduling logic found in React''s concurrent mode. It is highly effective for most standard web applications but may require manual optimization for extremely complex, high-frequency data updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bb5ff58-d8e3-4c5c-9052-e5a80cc256f3', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Why might you choose a ''Key-Value'' store over a more complex database for caching?', N'Senior', N'Key-value stores provide the lowest possible latency for simple read/write operations by eliminating the overhead of query parsing, planning, and complex relational logic. Their simplicity makes them highly performant and scalable for transient data that requires O(1) access time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c354bc1-8a6f-4be5-b90e-e5a83f46b152', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix prefer standard web APIs?', N'Fresher', N'Remix prioritizes standard web APIs like Request, Response, and URLSearchParams because they are universal and long-lasting. This makes the knowledge gained in Remix transferable to other parts of web development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eb4e4c12-6e16-493d-9b0f-e5a879657ed1', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Explain the role of the Quarkus ''Build Time'' optimization phase and its impact on reflection.', N'Senior', N'During the build phase, Quarkus performs aggressive static analysis to identify all reachable code paths, effectively eliminating the need for dynamic class loading. Because the framework determines the dependency graph ahead of time, it can replace heavy runtime reflection with direct calls, which is essential for successful compilation into native binaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc5f046a-6eeb-49b2-9417-e5aa87a0f089', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript ''WeakMap'' differ from a standard ''Map'' regarding garbage collection?', N'Senior', N'WeakMap holds weak references to its keys, meaning the garbage collector can reclaim memory associated with those keys if there are no other references to them. This makes WeakMap ideal for caching data associated with objects without preventing those objects from being garbage collected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
