INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df2f740e-b9e5-474e-9618-e5ac1eb4cd9e', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the benefits of using numeric data types over string types for primary keys?', N'Middle', N'Numeric types are more compact, which reduces the size of the primary key and all associated secondary indexes. They are also significantly faster to compare during join operations and index lookups compared to variable-length character strings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
