INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6f51bcc-2e49-4af1-9f47-e5afdb07e4b2', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is inheritance in Ruby?', N'Intern', N'Inheritance is a feature where a class can derive attributes and behaviors from a parent class. The subclass inherits all methods from the superclass, allowing for code reuse and the creation of specialized versions of existing classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8803af94-4e56-447d-9142-e5b3c2ed0ab9', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between Promise and AJAX?', N'Fresher', N'A Promise is an interface for asynchronous operations. They keep track of when asynchronous operations complete and what their results are and let you coordinate that completion and those results (including error conditions) with other code or other asynchronous operations. They aren''t actually asynchronous operations in themselves. An Ajax (Asynchronous JavaScript and XML) call is a specific asynchronous operation that can be used with with a traditional callback interface or wrapped in a promise interface. We can make an Ajax call either with a traditional callback using the XMLHttpRequest() interface or we can make an Ajax call (in modern browsers), using a promise with the fetch() interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dc49ec9e-6823-4398-9b7a-e5b3d4a8b791', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is meant by data redundancy?', N'Intern', N'Data redundancy occurs when the same piece of data is held in two or more separate places within a database. It is generally avoided because it wastes storage space and can lead to data inconsistencies if one instance is updated but another is not.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
