INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be534eca-621e-466b-92d9-e5b8ae473d31', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is dynamic binding?', N'Junior', N'Dynamic binding, or late binding, occurs when the specific function to be executed is determined at runtime based on the object''s actual type. This is achieved through the use of virtual functions and base class pointers or references.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95eeb284-7c51-498e-a0a7-e5b8d205dcad', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How should one approach scaling a Node.js application that requires shared state?', N'Senior', N'Since Node.js processes are isolated, they cannot share in-memory state directly. Scaling requires an external data store like Redis for session management or shared state synchronization. This introduces latency and complexity, so the architecture should aim for stateless design wherever possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0a3a6c4-243a-41d1-ba5e-e5bb34875162', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does the ''adapter'' pattern in SvelteKit simplify infrastructure abstraction?', N'Senior', N'The adapter pattern decouples the application code from the deployment target by providing a unified interface for server-side execution. It allows developers to write platform-agnostic code while delegating platform-specific concerns like serverless functions, static file storage, or node server configuration to the adapter.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'491f9f5a-c6b6-422f-b2e7-e5bbccc26d9f', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is the difference between a Path Operation and an API endpoint?', N'Junior', N'In FastAPI, a path operation is the specific function decorated with a path decorator like @app.get(). An endpoint is the logical URL path that a client accesses to interact with the API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'558a5d49-672f-4d6f-9681-e5c133efcc93', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between relative, absolute, and fixed positioning in CSS?', N'Junior', N'Relative positioning shifts an element from its normal position without affecting surrounding elements. Absolute positioning removes an element from the document flow and positions it relative to its nearest positioned ancestor. Fixed positioning also removes the element from the document flow, but keeps it positioned relative to the browser viewport, meaning it stays in place when the user scrolls.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ab80b1-141b-4d80-89cc-e5c25844b585', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the common side effects that need middleware in Redux?', N'Junior', N'Common side effects include fetching data from an API, interacting with browser storage, or logging information to a server. Since reducers must be pure, these operations cannot happen directly inside them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'373f33f5-def5-4d8a-87b9-e5c2af37287b', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the trade-offs of using Async/Await compared to traditional Promise chaining?', N'Middle', N'Async/Await provides cleaner, more readable code that resembles synchronous logic, making error handling with try-catch blocks more intuitive. However, it can hide the fact that operations are still asynchronous, potentially leading to performance issues if developers accidentally execute independent tasks sequentially instead of in parallel.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
