INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5a55a59-a05c-4755-b389-e5c5c930e92e', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What are semantic HTML elements?', N'Intern', N'Semantic elements clearly describe their meaning to both the browser and the developer. Using tags like header, footer, or article helps provide context for the content, which improves accessibility for screen readers and helps search engines understand the page hierarchy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caf90ed5-3e56-4b27-8d5b-e5c8560d77b4', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is ''reflect'' in a Lit property definition?', N'Junior', N'Reflect is an option that keeps the attribute on the DOM element in sync with the JavaScript property. When the property changes, the attribute on the HTML element is updated automatically, which is useful for CSS styling based on attributes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f41c4bee-3f87-4e43-9d92-e5cfe37f6310', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'How does Swift''s Error Handling model differ from traditional exception handling?', N'Middle', N'Swift uses a typed propagation model where errors are explicitly thrown and caught, forcing the developer to handle failure cases. Unlike traditional exceptions that can crash or bubble up silently, Swift''s model requires explicit ''try'' markers and ''do-catch'' blocks, leading to more robust and readable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd47f4639-be7a-4b48-9e75-e5d22ab4d03a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the primary difference between a relational database and a NoSQL database regarding data schema?', N'Junior', N'Relational databases use a rigid, predefined schema where all rows in a table must follow the same structure. NoSQL databases are schema-less or schema-flexible, allowing each document or record to have different fields and structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed25f1a5-d0bd-4af9-b0bb-e5d28ac85839', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'When estimating the impact of a system migration, what is the most important factor to consider?', N'Middle', N'The most important factor is the risk of downtime and data integrity, so I prioritize estimating the verification and rollback procedures. I reason that if the migration takes longer than expected, the ability to safely revert or recover is more valuable than the actual speed of the migration itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
