INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc53d2b7-f7bf-4327-bca4-e5d7f5b5df14', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How would you design a multi-tenant architecture in Django, and what are the risks of using the ''shared database, shared schema'' approach?', N'Senior', N'Multi-tenancy can be implemented via shared databases with tenant IDs or separate databases/schemas. The shared approach risks data leakage if query filters are accidentally omitted, necessitating rigorous use of custom managers or middleware to enforce tenant isolation at every level.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f70f856-0b0c-4126-ac45-e5da00f6cecc', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Discuss the trade-offs of using Ecto.Multi for database transactions versus standard transactional wrappers.', N'Senior', N'Ecto.Multi provides a composable way to define a series of database operations that are executed within a single transaction. Unlike nested transactional blocks, Multi allows for granular error handling and clear separation of operations, making complex business workflows easier to reason about and safer to roll back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edf8ad66-9fe6-40e2-a974-e5da85556dbc', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'In what scenario would you choose Litestar’s ''Provide'' mechanism over a traditional middleware approach?', N'Senior', N'You should choose the Provide mechanism for dependency-specific data that needs to be injected into handler signatures, as it is type-safe and explicitly declared. Middleware is more appropriate for cross-cutting request-response transformations that apply globally or to groups of routes regardless of the handler''s specific requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
