INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2c8499a-228b-48e9-9bb7-e5f32a6c3e55', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to use an asynchronous messaging system over direct HTTP requests for long-running tasks?', N'Fresher', N'Asynchronous messaging decouples the sender from the receiver, allowing the system to handle long-running tasks in the background without blocking the user interface. This improves responsiveness and system reliability, as the sender does not need to wait for the task to finish. It also allows the system to manage spikes in demand by queueing tasks for processing at a steady pace.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
