INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d4ffbfc-bd27-4a85-86b6-e5fff4d776b1', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is duck typing in Ruby?', N'Intern', N'Duck typing is a concept where an object''s suitability for a task is determined by the presence of certain methods rather than its specific class type. If it walks like a duck and quacks like a duck, it is treated as a duck.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3ae5a07-b062-4dce-910d-e6013540a0d6', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB''s ''Read Concern: Linearizable'' differ from ''Majority''?', N'Senior', N'Linearizable read concern provides the highest level of consistency by ensuring the read returns data that reflects all successful writes that completed before the read began. It requires communication with a majority of nodes to verify the current state, which introduces significantly higher latency than majority read concern.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6406ef76-1fa4-4b0e-9692-e6048e31e901', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the purpose of the Engine instance in Gin?', N'Middle', N'The Engine instance is the core framework object that contains the router, middleware stack, and configuration settings. It acts as the primary entry point for defining routes and starting the HTTP server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5af82b62-46a1-41d8-a2dc-e6067cb24815', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between a Controller and a Minimal API?', N'Intern', N'Controllers are classes that group related action methods to handle HTTP requests following the MVC pattern. Minimal APIs provide a lightweight approach to building small APIs by defining endpoints directly in the application configuration without the overhead of controller classes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9a342aa-d99f-4c59-9bda-e609c2e43e36', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you manage configuration drift between development, staging, and production environments?', N'Middle', N'I use Infrastructure as Code (IaC) tools to ensure that environment configurations are version-controlled and reproducible. By automating the deployment process through a single pipeline, I ensure that the same configuration artifacts are promoted consistently across all environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd11d16ec-8c17-4050-be2a-e60a9542ec76', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the function of the CommitLog?', N'Middle', N'The CommitLog is a crash-recovery mechanism that records all incoming write operations before they are applied to the MemTable. In the event of a node crash, Cassandra replays the CommitLog to restore data that was not yet flushed to disk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'230c8535-a41c-4e52-b180-e60aba58dd33', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between eventually consistent and strongly consistent reads in DynamoDB, and when should you choose one over the other?', N'Middle', N'Eventually consistent reads are the default, offering lower latency and higher throughput but potentially returning stale data since replication across nodes takes time. Strongly consistent reads guarantee the latest data by returning the most recent successful write, but they consume more read capacity units and have higher latency. You should use strong consistency only when your application logic requires immediate data accuracy, such as financial transactions or critical inventory updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'824b26c0-d9aa-4405-801e-e60b5e424a41', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket optimize response delivery?', N'Middle', N'Rocket optimizes delivery through efficient buffering and support for streaming response bodies. By using asynchronous streams, the server can begin sending data to the client as soon as it is available, reducing latency and memory overhead for large responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'604b7421-8e5b-44f1-89da-e60de2b477f0', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why does Rocket enforce a specific directory structure for static files?', N'Senior', N'Rocket''s static file handling is optimized for security and performance, using pre-defined file system access patterns to prevent directory traversal attacks. By enforcing a structured mapping between routes and static assets, it minimizes the risk of exposing sensitive server configuration files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc850a9a-f712-4ec1-b6d7-e60e67910d41', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Describe the role of the Swift compiler''s ''Existential Containers''.', N'Senior', N'Existential containers are internal structures used to store values of any type that conforms to a specific protocol. They handle the storage of the value itself, its type metadata, and its protocol witness table. Because they must accommodate any conforming type, they can incur performance costs related to heap allocation and indirection when the value exceeds the inline storage limit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'be210a9b-ea2e-4ae0-840b-e60f4ff00e32', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the ''panic!'' macro used for?', N'Fresher', N'The panic! macro is used for unrecoverable errors where the program cannot safely continue execution. It stops the program immediately, cleans up the stack, and reports the error message.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1ee980c-ae00-4769-9b69-e614ee91995d', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go prefer composition over inheritance?', N'Middle', N'Composition through struct embedding is favored because it avoids the fragile base class problem and deep, complex object hierarchies. It allows for more flexible code reuse and clearer visibility into object behavior by explicitly building types from smaller, independent components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8348677-3351-4c77-9ee5-e6150fa71bf6', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why should you avoid ''hard-coding'' values into a program?', N'Intern', N'Hard-coding makes a system rigid and difficult to update, as every change requires modifying the source code and redeploying. Using configuration files or environment variables makes the system more flexible and easier to adapt to different environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f059d279-6977-43fd-ab52-e618cc85fde2', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the trade-offs of using a leader-follower replication model for write-heavy workloads?', N'Senior', N'Leader-follower models centralize writes on the leader, creating a potential bottleneck that limits horizontal scaling for write operations. However, it provides strong consistency for reads from the leader and enables easy scaling of read-only workloads by adding more followers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
