INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'083a7773-c412-4744-b9b4-e62d7de4020f', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is the Actor model, as implemented in Erlang/Elixir, important for Phoenix performance?', N'Middle', N'The Actor model allows each connection to be handled by a lightweight process that does not share memory with others. This isolation prevents a single failing process from crashing the entire system and enables massive concurrency by avoiding global locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'50d0a5ba-aa1d-4a62-bcd3-e6348675baa9', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is ''Linearizability'' often considered too expensive for wide-area distributed systems?', N'Senior', N'Linearizability requires every operation to appear instantaneous and global, necessitating coordination between nodes that incurs significant network round-trip latency. In distributed systems spanning large geographic distances, the speed-of-light constraints make this level of coordination prohibitively slow for most user-facing applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0c77f7d-fdb8-40a4-b19e-e63535b66dcb', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is Redis considered ''fast''?', N'Intern', N'Redis is fast because it operates entirely in memory, avoiding the latency of disk access. Additionally, its simple data structures and efficient command processing allow it to handle hundreds of thousands of operations per second.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41969dc1-1939-4d94-802e-e635d77b803f', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Messenger component handle message retries and worker failure, and how does this affect system reliability?', N'Senior', N'Messenger supports configurable retry strategies and failure transports, allowing failed messages to be persisted for inspection or automatic redelivery. This ensures eventual consistency and robustness in asynchronous processing, preventing data loss when external dependencies or transient errors occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
