INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8f41a8c-f643-4a8c-98ba-e63780cf1098', N'954a0331-deff-4399-b588-96f39fec001d', N'What are custom elements and how does it work internally?', N'Intern', N'Angular Custom Elements allow you to package an Angular component as a native web platform custom element. This makes it possible to use your Angular components in any HTML environment, whether it''s a plain HTML page, a React app, a Vue app, or another framework, without needing the full Angular application context. Internally, Angular uses the @angular/elements package. The core mechanism involves the createCustomElement function, which takes an Angular component class and an injector. It returns a standard JavaScript class that extends HTMLElement. This generated class acts as a bridge: - It maps the native custom element lifecycle callbacks (like connectedCallback, disconnectedCallback) to the corresponding Angular component lifecycle hooks (ngOnInit, ngOnDestroy).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59a89b90-29e6-48c7-b976-e63904e8cac6', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is ''Exactly-Once'' delivery difficult to achieve in distributed systems?', N'Senior', N'Exactly-once delivery is difficult because it requires coordination between the sender, the message broker, and the receiver to ensure that every operation is atomic and reversible. In practice, this is usually achieved through a combination of at-least-once delivery and idempotent processing at the destination.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fab8d3bc-77fb-435e-a37f-e63d6efa3a34', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of the ''public'' folder?', N'Intern', N'The public folder is used to store static assets such as images, fonts, and icons that do not need processing. Files placed here are served directly from the root of the domain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4b35205-b463-4aef-9fa7-e64321fa2cab', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of the ''$lib'' alias?', N'Intern', N'The $lib alias is a convenient shortcut provided by SvelteKit to import files from the ''src/lib'' directory. It prevents long relative path strings like ''../../../../lib'' and keeps your import statements clean and easy to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b7ff0f0-8169-45d7-b830-e64ddd66600a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the volatile keyword in Java?', N'Middle', N'The volatile keyword ensures that any thread reading a variable sees the most recent write to that variable by any other thread. It prevents thread-local caching and ensures that operations on the variable are atomic regarding visibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02f47182-516a-41e9-8b4f-e64fb5fc0634', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is a read replica and when should it be used?', N'Middle', N'A read replica is a copy of the database used exclusively for read operations. It is used to offload read-heavy traffic from the primary database, thereby improving the overall throughput of the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72c915e4-d161-4584-b130-e6509790ec7b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does Sass compilation time scale with the size of the project?', N'Senior', N'Compilation time scales linearly with the number of imports and the complexity of Sass logic like loops and map lookups. In very large projects, modularizing files and avoiding excessive deep nesting or complex recursive functions are necessary to maintain fast incremental build times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e3b80b6-d5be-46b1-8dff-e651e6ea28d4', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Can you explain how to use decorators in a NestJS controller?', N'Junior', N'Before explaining how to use decorators, let me explain more about what are decorators: decorators are special functions that are prefixed with an @ symbol and can be attached to classes, methods, or properties. They are used to add metadata, methods, properties, or observe the behavior of the classes, methods, or properties they are attached to. NestJS provides several built-in decorators, and you can also create custom decorators. Here are some examples of built-in decorators in NestJS: 1. Class decorators like @Controller(), @Module(), @Injectable(), etc. These are used to annotate classes. 2. Method decorators like @Get(), @Post(), @Put(), etc. These are used to annotate methods within controller classes to handle specific routes. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c132a76-bc7c-4b59-a5b0-e65303285480', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What happens if a user interacts with a Qwik app before the code is downloaded?', N'Junior', N'Qwik captures the user interaction and queues it. Once the necessary JavaScript chunk is fetched and executed, the framework replays the interaction, ensuring no user intent is lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6517c843-0a8a-4e17-b1d4-e65320d3a88b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core handle model validation, and where is it typically enforced?', N'Middle', N'Model validation uses data annotations or fluent validation libraries to ensure the incoming request data matches defined business rules. It is typically enforced automatically by the MVC framework before the controller action is executed, returning a 400 Bad Request if the model state is invalid.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6771d6b7-c646-42dd-97ad-e653b44a119c', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'Why is ''data class'' restricted from being open, and what are the implications?', N'Senior', N'Data classes are designed to be simple data containers that automatically generate equality, hashing, and copying methods, which rely on a fixed, known set of properties. Allowing inheritance would break the contract of these generated methods, as subclasses might introduce new fields that the base class''s generated methods cannot account for.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81e410df-7c14-4243-8b71-e662346393c5', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is an index, and how does it improve performance?', N'Junior', N'An index is a database structure that provides a fast lookup path to specific rows in a table. It improves performance by reducing the amount of data the database engine needs to scan during a search operation, similar to an index at the back of a textbook.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a6c6b90-652c-4197-b6c7-e666b8b889bd', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel follow the MVC architecture?', N'Senior', N'Laravel consistently implements the Model-View-Controller (MVC) architectural pattern, providing a methodical means to segregate data, application logic, and user interface. MVC Overview - Model: Represents the data and the business rules concerning the data. This includes data persistence, validation, business logic, and authentication. - View: Presents data to the user in a specific format. The view receives data from the model and user interactions from the controller. - Controller: Acts as an intermediary between models and views. It processes user input, interacts with the model, and selects the view to display. Laravel''s Implementation of MVC - Model: Laravel uses Eloquent, a powerful ORM for modeling database entities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70daf93a-789a-47bf-8f2b-e667177a22a4', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What does ''serialization'' mean in the context of FastAPI?', N'Fresher', N'Serialization is the process of converting Python objects, such as dictionaries or Pydantic models, into a format like JSON that can be transmitted over the network. FastAPI handles this automatically based on the return type or response model defined in the endpoint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'137a3305-8fce-4f55-8dd3-e668ccfb3d3a', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are Lit templates?', N'Intern', N'Lit templates are the way you define the HTML structure for your component using tagged template literals. They are highly efficient because they parse the static parts of the template once and only update the dynamic parts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
