INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8ca93bf-9e84-450e-a7c7-e66f6d4af73b', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Explain how PHP manages global state and the dangers it poses to testability.', N'Senior', N'PHP''s reliance on global variables and the superglobal scope can create hidden dependencies between functions. This makes unit testing difficult because tests cannot be isolated, as they often require manual resetting of global state to avoid side effects between test cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95a48b5f-3216-4158-ac20-e67103c40b8f', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is Ecto in the context of Phoenix?', N'Intern', N'Ecto is a toolkit for data mapping and database integration in Elixir. It is used to define database schemas, manage changesets for data validation, and execute queries against a database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b332e0bb-ebb8-4844-9f08-e672631f15d0', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Laravel and why is it used?', N'Intern', N'Laravel is a PHP web framework that excels in the MVC (Model-View-Controller) architecture model. It stands out for its fluent and expressive syntax, making web development tasks more accessible and faster. Laravel''s component-based system and extensive toolset streamline development workflows, ensuring robust, secure, and maintainable web applications. Key Features - Modular Packaging System: Composant provides an organized venue for managing all third-party packages. - Eloquent ORM: Offers an intuitive and PHP-analogous way to perform database operations. - Database Migrations, Seeding, and Query Builder: Simplifies database tasks, including seamless transition across multiple environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'973db2c2-e100-4811-9056-e6733ec0af44', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is a default parameter value?', N'Fresher', N'Default parameters allow you to provide a default value for a function argument if the caller does not specify one. This reduces the need for function overloading with multiple variations of the same method.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ff603b34-1795-4bed-8161-e67352586cf4', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is Phoenix''s ''View'' layer separated into separate templates and layout files?', N'Senior', N'This separation follows the DRY principle and facilitates consistent UI structures across multiple pages. By nesting templates within layouts, Phoenix allows developers to manage global UI elements like navigation and headers independently from the content-specific view logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f03eed9c-a360-42e1-994b-e6789fb74bb3', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the concept of ''duck typing'' in Ruby.', N'Middle', N'Duck typing means that Ruby focuses on what an object can do rather than what it is. If an object responds to a specific method, it is treated as a valid participant, allowing for polymorphic behavior without strict inheritance hierarchies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0857db74-eaee-4534-8187-e678ef92d5f5', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the role of Database Migrations in a team environment.', N'Middle', N'Migrations act as version control for your database schema, allowing teams to define, modify, and share the database structure within code. They ensure that all developers and environments are synchronized with the same schema changes without manual intervention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe15caab-7e6a-4155-a632-e67921227342', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are the trade-offs of using ''data classes'' in Kotlin?', N'Middle', N'Data classes provide boilerplate-free implementations of equals, hashCode, and toString, which reduces code size and improves maintainability. The trade-off is that they are restricted to having at least one primary constructor parameter and cannot be open for inheritance, which limits their use in certain design patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9a9d65bc-c993-43c4-aa71-e67964c896f9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is database normalization and why is it used?', N'Intern', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them. This practice helps ensure that each piece of data is stored in only one place, which prevents update anomalies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdcffd99-922e-4bd7-9d6b-e67d84e855b8', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is it discouraged to nest CSS selectors too deeply in Sass?', N'Junior', N'Excessive nesting results in overly specific CSS selectors that are difficult to override later. It can also lead to bloated CSS output and performance issues, as the browser must resolve longer selector chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'edea3f43-9092-4415-8daa-e67fbfcf6db4', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the different ways to access object properties', N'Intern', N'There are 3 possible ways for accessing the property of an object. 1. Dot notation: It uses dot for accessing the properties 2. Square brackets notation: It uses square brackets for property access 3. Expression notation: It uses expression in the square brackets', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'177f8cff-3b49-46e4-afa3-e67ff2b48b2d', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'Explain the architectural trade-offs between CSS Modules, CSS-in-JS, and Utility-first CSS.', N'Senior', N'CSS Modules provide local scoping with static extraction, making them excellent for caching and performance. CSS-in-JS offers dynamic styling based on application state but introduces a heavy runtime cost. Utility-first CSS reduces bundle size as the project scales but sacrifices semantic class naming and can lead to cluttered HTML structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'430a7700-4995-4443-859e-e680ec09847a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is an Action in Remix?', N'Intern', N'An action is a server-side function used to handle data mutations, such as form submissions or data updates. It processes incoming requests, performs tasks like saving to a database, and then triggers a page reload or update.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0787a5a8-ebd4-4346-b36f-e682c7e455b4', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary architectural advantage of Hono compared to traditional Node.js frameworks?', N'Junior', N'Hono is designed to be platform-agnostic, meaning it can run on various runtimes like Cloudflare Workers, Bun, Deno, and Node.js. This flexibility is achieved by using the standard Web Standards API, such as Request and Response objects, instead of relying on Node-specific modules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8777e1d9-a56f-4021-b555-e686754541b7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is a Key-Value pair in the context of Redis?', N'Fresher', N'A key-value pair is the fundamental data structure in Redis where each piece of data is stored under a unique identifier called a key. The value can be various types like strings, lists, or sets, and you access the data by referencing its unique key.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a356f97-a61b-4872-b963-e68729be1deb', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the workspace in R?', N'Intern', N'The workspace is the current working environment in R that contains all user-defined objects such as variables, functions, and data frames. It is stored in memory during an active session.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fd62a87-112e-4673-94c4-e68870cacbcc', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the primary danger of using ''ALL'' as a consistency level in a large Cassandra cluster?', N'Senior', N'Using ''ALL'' requires every single replica to be up and responsive for a write or read to succeed, which drastically reduces availability. If even one node is down, the operation fails, effectively turning the highly available distributed system into a fragile one that is only as strong as its weakest node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c43f611-c7f3-4f29-a294-e68a0aa86229', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How do Lit controllers differ from standard component lifecycle methods?', N'Middle', N'Controllers are reusable objects that can hook into a component''s lifecycle without cluttering the main component class. They allow for logic like data fetching or event handling to be modularized and shared across multiple components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1b6c01e-6fdc-469d-8686-e68ad81201f3', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'Discuss the trade-offs of using Echo''s validator interface versus performing validation inside the service layer.', N'Senior', N'Validating at the Echo layer provides early exit for malformed requests but couples the transport layer to the domain model. Service layer validation is more portable and adheres to clean architecture principles but requires redundant validation logic if multiple entry points are exposed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ef56b7d-c98d-412b-ad0d-e68bd8d0aed6', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What are the advantages and disadvantages of using Express for microservices architecture?', N'Middle', N'Express is lightweight and fast to start, which is ideal for microservices that need to be small and efficient. However, it requires significant boilerplate for cross-service concerns like service discovery, distributed tracing, and standardized logging compared to specialized frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9c6b182-59a5-4848-b7b0-e68caf469336', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Does Rocket support asynchronous programming?', N'Intern', N'Yes, Rocket is built on top of the asynchronous ecosystem in Rust. This allows it to handle many concurrent requests efficiently without blocking the server thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1bed79a7-abbb-4577-b48d-e6934921a3cd', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the architectural benefits of using ''Self-Types'' compared to traditional dependency injection?', N'Senior', N'Self-types allow a trait to declare its dependency on another trait, forcing the compiler to verify that the dependency is satisfied at the point of composition. This provides compile-time safety for component wiring, unlike runtime dependency injection frameworks which only detect missing dependencies when the application starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6a97596-d83c-4007-acd7-e69657e8f8e9', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the primary differences between optimistic and pessimistic concurrency control in distributed systems?', N'Senior', N'Pessimistic concurrency control prevents conflicts by locking resources before access, which is suitable for high-contention environments but reduces throughput. Optimistic concurrency control assumes conflicts are rare, allows operations to proceed without locks, and validates at commit time, providing higher performance in low-contention scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd3b7b25-5a64-4924-810c-e6974df34c1c', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence the choice between a microservices architecture and a monolithic architecture?', N'Junior', N'A monolith is generally better for early-stage startups needing rapid development and simple deployment. Microservices should be considered when the team grows significantly, different parts of the application need to scale independently, or when team autonomy becomes a priority.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'164a1c2e-5678-414f-944b-e69b85fd4da4', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How do you handle type safety when working with third-party JavaScript libraries?', N'Middle', N'You handle third-party libraries by using declaration files, typically found in the DefinitelyTyped repository, which provide type definitions for the library. If definitions are unavailable, you can create a custom declaration file or declare the module as ''any'' to bypass compilation errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dff9fd26-d291-4cfa-94a2-e69d5aa775f7', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the case types in Angular?', N'Intern', N'Angular uses capitalization conventions to distinguish the names of various types. Angular follows the list of the below case types. 1. camelCase : Symbols, properties, methods, pipe names, non-component directive selectors, constants uses lowercase on the first letter of the item. For example, "selectedUser" 2. UpperCamelCase (or PascalCase): Class names, including classes that define components, interfaces, NgModules, directives, and pipes uses uppercase on the first letter of the item. 3. dash-case (or "kebab-case"): The descriptive part of file names, component selectors uses dashes between the words. For example, "app-user-list". 4. UPPER_UNDERSCORE_CASE: All constants uses capital letters connected with underscores. For example, "NUMBER_OF_USERS".', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a64391f8-7acc-40ad-8fd9-e69eb65a4bb3', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between a Template and a Layout in Phoenix?', N'Fresher', N'A template represents the specific content of a single page or view. A layout is a wrapper template that contains common elements like headers, footers, and navigation, which are shared across multiple templates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0f4e197d-35c9-4b0e-a843-e6a04687be6e', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the ''composer.json'' file?', N'Intern', N'The composer.json file defines the dependencies and project requirements for your Laravel application. It is managed by Composer, the PHP dependency manager, which downloads and installs the necessary packages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'857539bc-6cad-4c0f-b313-e6a2c106fdd4', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the function of the ''tp_traverse'' and ''tp_clear'' slots in the C-API for objects?', N'Senior', N'These slots are used by the cyclic garbage collector to identify and break reference cycles. ''tp_traverse'' allows the collector to inspect an object''s references, while ''tp_clear'' provides a mechanism to nullify those references during the collection process to free unreachable structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'05df8d33-5985-4807-ae23-e6a424bb670e', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How do you implement global middleware versus route-specific middleware in Gin?', N'Middle', N'Global middleware is applied by registering it directly to the engine instance, affecting all incoming requests. Route-specific middleware is applied by wrapping individual routes or route groups, allowing for granular control over security and performance logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47c488ee-d6eb-4293-851c-e6a6d1d9e842', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix encourage using standard web APIs?', N'Junior', N'By adhering to web standards like Request and Response objects, Remix ensures that the skills you learn are portable. It also makes the framework more compatible with different hosting environments and future browser updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
