INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6df5cf5e-bb45-4519-aaad-e6aeae73de4f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'Why is ''Scan'' generally discouraged for large tables?', N'Fresher', N'A Scan operation reads every item in the entire table, which is very inefficient and consumes a large amount of read capacity as the dataset grows. It is recommended to use Queries or Secondary Indexes for targeted data retrieval.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0e806d0-bea9-4fe7-81c7-e6b105134b6a', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the role of Eager Loading in Eloquent ORM and why it is necessary for performance.', N'Middle', N'Eager Loading retrieves related models alongside the main query, preventing the ''N+1'' query problem where the application executes an additional database query for every single record in a result set. Using eager loading significantly reduces the number of database round-trips, which drastically improves application performance when dealing with large datasets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'56338d75-44be-4c67-8c28-e6b1e106fd35', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle retries for failed operations?', N'Middle', N'Micronaut offers a @Retryable annotation that can be applied to methods to automatically retry operations upon failure. It supports configurable policies like delay, maximum attempts, and specific exceptions to catch, simplifying the implementation of resilient communication patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea364ca6-bc3c-45ff-b997-e6b298ff0908', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you handle database connection pooling in a multi-threaded environment?', N'Middle', N'Rails handles connection pooling automatically via the database configuration file, where you define the ''pool'' size. This ensures that each thread in a multi-threaded web server can check out a connection from the pool, preventing race conditions and resource exhaustion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'152d9a8c-0fe9-407e-a8d3-e6b488455388', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'If an application crashes immediately upon launch, what is your first step in troubleshooting?', N'Fresher', N'I would first check the application''s error logs or system event viewer to identify the specific error message or exception code. This helps distinguish between a missing dependency, a configuration error, or a runtime failure before attempting to modify any settings.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4abe5890-9230-4961-8f1d-e6b7311d30cf', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are Svelte components?', N'Intern', N'Svelte components are reusable building blocks for your user interface, typically defined in files with a specific extension. Each component encapsulates its own HTML structure, CSS styling, and JavaScript logic in a single file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'531d77df-a608-4dc3-80cf-e6b742c87e35', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the purpose of dynamic memory allocation?', N'Intern', N'Dynamic memory allocation allows a program to request memory from the operating system during runtime. This is useful when the required amount of memory is not known until the program is already running.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a73b1eb-04ef-4e5f-a3af-e6b89eee7e48', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the size of an integer in Python?', N'Intern', N'Unlike C/Java where int is fixed at 4 bytes, Python integers have arbitrary precision — they grow as needed. CPython uses a PyLongObject struct. A small integer takes 28 bytes minimum (sys.getsizeof(0)), and size grows with magnitude. CPython also maintains a small integer cache for values in [-5, 256], reusing the same object rather than allocating new ones. Use Case: Cryptographic libraries (e.g., RSA key generation) rely on Python''s arbitrary-precision integers to perform modular exponentiation with 2048-bit or 4096-bit numbers natively, without any overflow concerns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de905f8d-caa7-485e-980d-e6b92eaeadf2', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What steps do you take after fixing a bug to ensure the solution is correct and won''t break anything else?', N'Junior', N'I verify the fix by running existing test suites and adding a new test case specifically for this bug to prevent future regressions. I also perform manual exploratory testing in the affected area to ensure the change did not cause unintended side effects in related features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f9ca75b-548a-46a3-9690-e6ba16f0a3c0', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Why is HTTPS mandatory for modern web applications?', N'Middle', N'HTTPS uses TLS/SSL to encrypt data in transit, protecting sensitive information from eavesdropping and man-in-the-middle attacks. Additionally, it ensures data integrity, guaranteeing that the content has not been tampered with during transmission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4f558539-41e6-48ee-ac21-e6bbe44995e6', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is FastAPI?', N'Intern', N'FastAPI is a modern, high-performance web framework for building APIs with Python. It is based on standard Python type hints and is designed to be easy to learn and use while providing fast execution speeds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'232cc556-831d-4436-90ab-e6c06f520efe', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the ''useNavigation'' hook in Remix?', N'Intern', N'The useNavigation hook allows components to access the current navigation state of the application. It is primarily used to determine if a page is currently loading or if a form is being submitted to provide feedback to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3cdfdc5c-9421-449b-aea2-e6c13587fbae', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How does Fastify perform input validation?', N'Junior', N'Fastify uses the AJV library to compile the JSON schemas you provide into optimized JavaScript functions. When a request hits a route, Fastify automatically runs this validator against the input, returning a 400 error if the data does not match the defined schema.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7651e40b-0242-46a6-a071-e6c1ea1288dd', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the role of the recovery middleware, and why is it mandatory in production Echo apps?', N'Senior', N'The recovery middleware catches panics during request handling, prevents the entire server process from crashing, and returns a 500 error to the client. This is vital for application resilience, as a single malformed request shouldn''t lead to a total service outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e79298ad-e10f-4db6-9788-e6c38a4db773', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the trade-offs between a hashed shard key and a ranged shard key?', N'Middle', N'Ranged sharding supports efficient range-based queries but can lead to hotspots if data is inserted sequentially. Hashed sharding provides a more uniform distribution of data, effectively preventing hotspots, but it makes range queries less efficient as they must be broadcast to all shards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d14bf3d-d012-4d54-b2f6-e6c3ef8a0207', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When choosing between a monolithic and a microservices architecture, what is the main trade-off regarding complexity?', N'Fresher', N'A monolithic architecture is simpler to develop, test, and deploy initially because the entire application is a single unit. Microservices introduce higher complexity in terms of network communication, deployment, and service orchestration. You would choose microservices only if the team size and application scale justify the overhead of managing distributed components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'21792eb0-822f-4035-8d6c-e6c9df88c96a', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s approach to props differ from React?', N'Middle', N'In Svelte, props are declared as exported variables within the component file. This makes them easily accessible and keeps the syntax concise, unlike React where props are passed as a single object argument to the component function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'93b7213c-c052-4eff-ad5e-e6c9ecd9bc3e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the difference between local state and stores?', N'Fresher', N'Local state is specific to a single component and is defined within that component''s script tag. Stores are external objects designed for shared state, allowing data to be communicated and synced across different parts of the application tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfe8d4d7-3da3-4176-8372-e6caeb151077', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Discuss the performance implications of ''Model Hooks'' in Ember and how to mitigate them.', N'Senior', N'Model hooks are blocking calls that determine when a route transition completes. If they fetch large amounts of data, the UI can feel unresponsive; developers should mitigate this by using query parameters for pagination or implementing loading sub-states to provide immediate user feedback.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b0e812a-acef-48dd-946e-e6ce43c0542a', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Model in the MVC pattern?', N'Intern', N'The Model represents the data and the business logic of the application. It is responsible for retrieving data from a database, validating it, and maintaining the state of the application''s domain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06bfd0b3-d0d5-4bfd-993a-e6ce4ed1ec32', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does atomic operation mean in the context of Redis?', N'Intern', N'An atomic operation means that a command is processed as a single, indivisible step. In Redis, all commands are atomic, ensuring that no other client can see a partial state during the execution of a command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'17ecba49-ae26-4efd-aa99-e6cebe3b38b6', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What are Django signals and when are they useful?', N'Junior', N'Signals are a mechanism that allows certain senders to notify a set of receivers when specific actions occur, such as saving a model instance. They are useful for decoupling code, allowing you to trigger side effects without modifying the original model logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf7f04be-70f5-4d11-bc53-e6d0a609fc0a', N'075b8862-431c-4678-9767-f55359758a4a', N'Why do you need to use key attribute on for directive?', N'Fresher', N'In order to track each node''s identity, and thus reuse and reorder existing elements, you need to provide a unique key attribute for each item with in v-for iteration. An ideal value for key would be the unique id of each item. Let us take an example usage, Hence, It is always recommended to provide a key with v-for whenever possible, unless the iterated DOM content is simple. Note: You shouldn''t use non-primitive values like objects and arrays as v-for keys. Use string or numeric values instead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'158db198-9b46-4dc1-a3f0-e6d2b0e1e605', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What happens if a user interacts with an element before the JavaScript has loaded?', N'Junior', N'Qwik captures the interaction event and queues it. Once the corresponding JavaScript chunk is downloaded and parsed, the event is replayed, ensuring the user''s intent is processed without any loss of functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0caca3b-e5f7-4b81-a23f-e6d3e6d80d08', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What does the ''useNavigation'' hook provide?', N'Intern', N'The useNavigation hook allows you to monitor the state of the current page transition. It helps you provide visual feedback to users, such as loading spinners or progress bars, while waiting for data to load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'753954c9-92b9-4dc9-a190-e6d5652245fc', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the function of ''babel-loader'' in a Webpack pipeline?', N'Middle', N'Babel-loader is used to transpile modern JavaScript (ES6+) into backward-compatible versions that can run in older browsers. It acts as a bridge between the Webpack bundling process and the Babel compiler, ensuring that all processed modules meet the defined compatibility requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
