INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77fa1639-0dbf-42cb-8a4e-e6d9c91f7b2a', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is jQuery''s approach to cross-browser compatibility no longer required for modern web development?', N'Senior', N'jQuery was primarily designed to normalize inconsistencies between legacy browser engines like IE6-8 and modern standards. With modern browsers adhering strictly to the ECMAScript and W3C specifications, the abstraction layer jQuery provides is redundant and adds unnecessary weight to the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95933ac4-930b-4193-aef0-e6da435ac753', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the primary benefit of using a Framework like Symfony over plain PHP?', N'Intern', N'Symfony provides a standardized structure, security best practices, and reusable components that speed up development. It reduces the need to write boilerplate code and ensures that the application is easier to maintain and scale.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5884619a-3d29-46bf-98d8-e6dd4460b626', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of a CSS reset?', N'Intern', N'A CSS reset is a set of styles used to override the default browser styling for various HTML elements. This ensures that a website looks consistent across different browsers, which may have slightly different default margins or padding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38bf9774-9074-494a-9524-e6dd4e7abb71', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you determine when it is appropriate to use an asynchronous communication pattern between services?', N'Middle', N'Asynchronous communication is ideal when the sender does not need an immediate response or when the task is long-running and could impact user experience. It helps decouple services, improves system resilience through retries, and allows for better load balancing during peak times. However, it introduces complexity in terms of eventual consistency and monitoring, which must be accounted for in the architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62f05d2a-78c8-40ca-8ad9-e6de36d1b147', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Describe the architectural purpose of the ''Addr'' and ''Recipient'' types in Actix.', N'Senior', N'Addr and Recipient serve as type-safe handles for communicating with actors. Addr allows for full actor lifecycle management, while Recipient provides a constrained interface that only allows sending specific message types, promoting loose coupling and better API design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ea85b3f-47e7-45ec-956d-e6de7fc1b75f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does the ''factory'' constructor pattern influence memory allocation?', N'Senior', N'Factory constructors provide the flexibility to return existing instances instead of always creating a new object, which is essential for implementing the Singleton pattern or caching strategies. This allows developers to control memory consumption by reusing objects where appropriate without exposing the underlying instantiation logic to the caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c43ecc41-5779-4085-9b10-e6e18fb249f2', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between static and dynamic binding in PHP?', N'Middle', N'Static binding resolves method calls at compile-time based on the type of the variable, while late static binding allows methods to be resolved at runtime based on the class that was initially called. This is crucial for inheritance and polymorphic behavior in static methods. It enables more flexible design patterns in large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1dbb54b-9b97-4e24-9769-e6e4c11d2be4', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the trade-offs of using Ruby''s ''Fiber'' mechanism versus traditional OS-level threads?', N'Senior', N'Fibers provide cooperative concurrency, meaning context switching is manually controlled by the developer rather than preemptively by the OS. This results in significantly lower memory overhead and faster switching times compared to threads, but it requires the code to be non-blocking, as a single blocking operation will halt all other fibers in the thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b81ff27-357f-466c-93c5-e6e545643cd2', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How does vertical scaling differ from horizontal scaling?', N'Intern', N'Vertical scaling involves adding more power, like CPU or RAM, to an existing machine to increase its capacity. Horizontal scaling involves adding more machines to the resource pool, which is generally more resilient and capable of handling larger traffic spikes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa5d8e19-d220-428c-a7fb-e6e639183c4c', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the concept of an ''isolate'' in Dart.', N'Fresher', N'An isolate is an independent worker unit in Dart that has its own memory heap and does not share state with other isolates. Because they do not share memory, they communicate by passing messages, which prevents race conditions and simplifies concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a662c58a-2acf-4cc6-9145-e6e8486eae4f', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is an Anonymous Type?', N'Fresher', N'An anonymous type is a temporary data structure that allows you to encapsulate a set of read-only properties into a single object without having to explicitly define a class. They are often used in LINQ queries to project specific data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b163c424-3036-49dd-a779-e6e84b544aa2', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS middleware ensure that requests are processed in a specific order?', N'Middle', N'AdonisJS uses a stack-based middleware pattern where each middleware calls a next function to pass control to the next layer. This creates a predictable pipeline where requests are intercepted before reaching the controller and responses are handled after the controller finishes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'41536cfd-df33-4104-babb-e6e87987d654', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the purpose of the DynamoDB Streams feature?', N'Middle', N'DynamoDB Streams captures a time-ordered sequence of item-level modifications in a table, such as inserts, updates, and deletes. It is commonly used for event-driven architectures, such as triggering Lambda functions to update other databases or perform real-time data replication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29489b0b-8fbc-47fc-b117-e6eb193e2f7c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the consequence of having a high ''replication factor'' in a small cluster?', N'Senior', N'A high replication factor increases fault tolerance but also consumes more disk space and increases the overhead of every write operation. If the replication factor equals the number of nodes, any write requires all nodes to be healthy, which can degrade performance and limit cluster flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
