INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cb14e64-f4ca-4434-9581-e6fd6570c994', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the role of the borrow checker in Rust?', N'Junior', N'The borrow checker is a component of the compiler that validates references to data to ensure memory safety. It enforces the rule that you can have either one mutable reference or any number of immutable references to a piece of data at any given time, preventing data races.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd329a7eb-b2e6-4663-ac18-e6ffb6209b00', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is the purpose of a ''proof of concept'' in a larger project?', N'Intern', N'A proof of concept is used to verify that a specific idea or technology will work as intended before committing significant time and resources to full-scale development. It serves to reduce technical risk by validating assumptions early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3828d401-aad5-458b-93da-e703c574ae11', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are tasked with debugging a system you have never seen before, what is your first step?', N'Fresher', N'My first step is to reproduce the issue consistently to understand the expected versus actual behavior. I would then review existing documentation and logs to isolate the component where the failure occurs before making any assumptions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42b030ee-38e3-4a52-8294-e703d7ba72b1', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'In what scenarios would Qwik''s architectural approach be detrimental?', N'Senior', N'Qwik may be overkill for highly dynamic, client-heavy applications that do not benefit from SEO or initial load performance. Additionally, the complexity of serialization can make integrating legacy client-side libraries that expect a standard DOM lifecycle difficult.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13713702-5c87-4e63-8363-e703d9f6edca', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Why is it often better to use ''GenServer'' for background tasks instead of spawning raw processes in Phoenix?', N'Senior', N'GenServers provide a formal framework for maintaining state, handling asynchronous messages, and implementing supervision strategies. They offer built-in error handling and lifecycle management, which are essential for building robust, fault-tolerant background services that can recover from crashes automatically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e64c71f-cb2f-456b-847d-e70619c639c4', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the purpose of the @content directive in Sass?', N'Fresher', N'The @content directive is used within a mixin to allow you to pass a block of custom styles into that mixin. This makes mixins highly flexible, as they can provide a structural wrapper while allowing the developer to define the specific inner content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb9e035b-e2de-42da-bbb5-e708e8e09189', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is the Redis ''KEYS'' command discouraged in production, and what is the appropriate alternative?', N'Senior', N'The KEYS command scans the entire keyspace and blocks the event loop, which can cause significant latency spikes in large datasets. The SCAN command is the appropriate alternative, as it uses a cursor-based approach to return results incrementally without blocking the server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c12ca95-cb1b-4a3c-a61b-e709aa2f51c5', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What does the Echo ''Context'' object represent?', N'Fresher', N'The Context object represents the entire lifecycle of an HTTP request and response cycle. It holds information about the request, provides methods to bind data, and includes helper functions to send responses back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6482401d-1aa2-483e-9410-e70a0078a33b', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the ''Either'' type?', N'Fresher', N'Either is a type used to represent a value that can be one of two possible types. It is commonly used as an alternative to throwing exceptions, where the ''Left'' side typically represents an error and the ''Right'' side represents a successful result.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43ded800-8b67-41d6-a8e4-e70c8f29bf28', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''Merkle Tree'' and how is it used for database anti-entropy?', N'Senior', N'A Merkle Tree is a hash tree where leaf nodes represent data chunks and parent nodes represent hashes of their children, allowing for efficient comparison of large datasets. By comparing the root hashes of Merkle trees, nodes can quickly identify which specific segments of data differ, minimizing the amount of data transferred during synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15b54ce0-e7bc-485a-aed2-e70cbbdc1d02', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you explain a complex technical bug to a non-technical stakeholder?', N'Junior', N'I avoid technical jargon and focus on the user impact, explaining what is failing and why it matters to the business. I provide a high-level summary of the cause, the steps being taken to fix it, and an estimate of when the service will be fully restored.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c30798c7-c3ca-48a0-8688-e70d779ffa0b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is normalization in database design?', N'Intern', N'Normalization is the process of organizing data in a database to reduce redundancy and improve data integrity. It involves dividing large tables into smaller, related tables and defining relationships between them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1f047fb-c1ac-4f77-b173-e7108c7d6f3c', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does an ''Isolation Level'' impact database performance?', N'Middle', N'Higher isolation levels provide stronger protection against concurrency issues like phantom reads and non-repeatable reads but require more restrictive locking mechanisms. Lowering the isolation level reduces locking contention and improves throughput, but it increases the risk of data inconsistency for concurrent transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a9c8b71-ee90-488b-aade-e715ecefc542', N'4c000000-0000-0000-0000-000000000005', N'Why is idempotency critical in message-driven distributed systems?', N'Senior', N'Distributed systems often rely on ''at-least-once'' delivery, which guarantees messages arrive but risks duplicates. Idempotency ensures that processing the same message multiple times results in the same state, preventing data corruption or inconsistent business outcomes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a3a72b5-15de-47b4-ac66-e717e9ade885', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the difference between ''enum'' and ''const enum''?', N'Middle', N'A standard enum creates a runtime object that exists in the compiled JavaScript, providing both forward and reverse mapping. A ''const enum'' is inlined during compilation, meaning it is removed from the final output and provides better performance. However, ''const enums'' cannot be used in certain scenarios where the runtime object is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb2ed2ca-a898-4b2a-8eec-e7193909854e', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the ''repeat'' directive used for?', N'Junior', N'The repeat directive is used to efficiently render lists of items. It uses unique keys to track items, which helps Lit minimize DOM mutations when the order or content of the list changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'399bcaa4-3938-4f6a-9a1f-e71be0d6d4ec', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain the trade-offs between using a micro-frontend architecture versus a monorepo-based monolith for a large-scale enterprise application.', N'Senior', N'Micro-frontends allow independent deployment cycles and technology heterogeneity, but they introduce significant complexity in state sharing, CSS isolation, and orchestration. Monorepos provide better code sharing, unified tooling, and simpler dependency management, though they can lead to longer build times and require stricter governance to prevent tight coupling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'261d88f1-ba88-4ff5-9ff4-e71f8abee584', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between using a monolithic architecture versus microservices for a rapidly growing startup?', N'Middle', N'A monolith offers simplicity in deployment and low latency due to in-process calls, but it becomes difficult to maintain and scale as the team grows. Microservices provide independent deployability and team autonomy, but introduce significant operational complexity, network latency overhead, and challenges in distributed transaction management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d599f1b-bd4e-4cfe-88a1-e7204feb2197', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is type inference in Rust?', N'Intern', N'Type inference is the compiler''s ability to deduce the data type of a variable based on the value assigned to it. This allows developers to write code without explicitly stating the type every time while still maintaining the safety of static typing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac4a0db7-dc4f-4a16-a536-e7212bd3485e', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of CSS media queries at the asset level versus the CSS level?', N'Senior', N'Media queries at the CSS level allow for layout adjustments based on viewport width, while media queries within link tags allow the browser to download only the necessary stylesheets for the current device. Asset-level queries optimize bandwidth by preventing the download of large, irrelevant CSS files for mobile users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53d77223-35e0-4c11-9db8-e72391c94119', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Describe the difference between an inner join and a left outer join.', N'Middle', N'An inner join returns only the rows where there is a match in both participating tables. A left outer join returns all rows from the left table and the matched rows from the right table, filling with nulls if no match exists on the right side.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e1f65794-9970-4065-b571-e72626783830', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the purpose of the ''Angular Compiler''?', N'Middle', N'The compiler transforms the component templates and metadata into highly optimized JavaScript code that the browser can execute efficiently. It ensures that the application is type-safe and performs runtime checks to validate bindings before execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bc140770-6328-40c4-8552-e726f4fff09f', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the impact of high indexing throughput on search latency?', N'Middle', N'High indexing throughput consumes significant CPU and I/O resources, which can lead to contention with search queries. If the system is saturated, search requests may experience increased latency due to competing for shared resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e78e744-beb1-4c9f-bef9-e72700022a69', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of using ''Dev Services'' in Quarkus during local development?', N'Senior', N'Dev Services automatically provision required external infrastructure, such as databases or message brokers, using Testcontainers when the application starts in Dev Mode. This eliminates the need for developers to manually install and manage local database instances.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06276d16-6cee-4f99-bef1-e727fe59d22d', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is database integrity?', N'Intern', N'Database integrity refers to the accuracy and consistency of data stored in a database. It is maintained through constraints like primary keys, foreign keys, and unique rules that prevent invalid data from being entered.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'714d0acf-6d2c-46f0-96b3-e7294994b079', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why does Rocket prioritize compile-time checks over runtime reflection?', N'Senior', N'By avoiding reflection, Rocket shifts the burden of error detection from runtime to compile-time, drastically reducing the possibility of ''it works on my machine'' bugs. This architecture results in faster startup times and better overall performance, as the compiler can optimize the execution path based on fully resolved types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80d4306d-37f1-444f-b3f9-e72e066f05ac', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is Preact and how does it relate to React?', N'Intern', N'Preact is a lightweight JavaScript library that serves as a high-performance alternative to React. It maintains a similar API, allowing developers to use familiar patterns while benefiting from a much smaller file size and faster execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29347965-ead0-4267-8b95-e72eabc0a0e9', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the role of the @use rule in modern Sass compared to @import?', N'Middle', N'@use is the modern standard that namespaces variables, functions, and mixins automatically. Unlike @import, which adds everything to the global scope and leads to naming collisions, @use keeps modules isolated and makes dependency tracking much more explicit.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51d553ba-9463-46df-8bd5-e72fb9c15e73', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the versioning behavior in preset plugins?', N'Intern', N'You can explicitly specify versions of the plugins being used. For official plugins, the CLI will automatically use the latest version available in the registry', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69cfce42-0f59-41a8-b5f3-e73432577318', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'Explain the architectural rationale behind NestJS''s ''Module'' system and its impact on large-scale application modularity.', N'Senior', N'The module system enforces encapsulation by logically grouping related components, controllers, and providers. This allows developers to partition the application into domain-driven boundaries, making it easier to manage codebase complexity, implement feature-level isolation, and facilitate team-based development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d1d2310-1ac1-4bd3-b06d-e73e1f3f3726', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is an interface in Kotlin?', N'Intern', N'An interface defines a contract of methods and properties that a class must implement. Unlike abstract classes, interfaces cannot hold state and allow for multiple implementation, supporting a form of multiple inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86c8295d-11a7-40e7-bc18-e73fb8ea62de', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'When faced with a complex bug report, how do you decide where to start your investigation?', N'Junior', N'I start by validating the reported issue to ensure I can see the expected failure. Then, I narrow down the scope by checking recent changes, verifying input data, and reviewing logs to determine if the issue is occurring at the client, server, or database layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0492bd2c-3a15-4985-a50c-e740a39d9fba', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is the distinction between ''static'' and ''instance'' methods critical for PHP memory usage?', N'Senior', N'Instance methods require an object to be instantiated, which consumes memory for the class properties and internal object headers. Static methods are invoked without object instantiation, reducing the memory overhead, but they limit the ability to use dependency injection and polymorphic behaviors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'046323ef-1f08-45cf-abaa-e74192bf169d', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the concept of routing in a Flask application.', N'Fresher', N'Routing is the process of mapping a specific URL to a corresponding Python function that handles the request. In Flask, this is achieved using decorators that associate a URL path with a function, which then determines what content or data is returned to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a79aa0bd-9377-4ad1-8084-e742d10278af', N'210c7148-726e-4e8b-bf12-40be36e55130', N'How does error handling in Rust differ from exception-based languages?', N'Junior', N'Rust uses the Result enum to return errors explicitly rather than throwing exceptions. This requires the caller to acknowledge and handle the error path, leading to more predictable program flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90f1c173-fd52-4761-aed1-e742efc821b5', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the garbage collector''s role in memory management in R?', N'Middle', N'The garbage collector automatically reclaims memory that is no longer reachable by any active R object. R uses a reference-counting mechanism combined with a mark-and-sweep algorithm, which helps prevent memory leaks but can occasionally cause performance pauses in memory-intensive tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e8a8cde-8fd9-4649-ad5d-e745941c43a9', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the role of the WSGI in a Flask application?', N'Intern', N'WSGI stands for Web Server Gateway Interface. It acts as a specification that describes how a web server communicates with web applications, allowing Flask to interact with production-grade servers like Gunicorn or uWSGI.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e3355a9-5ee3-4c8d-8025-e74600635c14', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is the benefit of using ''Value Classes'' in Scala?', N'Middle', N'Value classes allow developers to create type-safe wrappers around primitive types without incurring the performance penalty of heap allocation. At runtime, the wrapper is often stripped away, and the underlying value is used directly, providing type safety with zero runtime overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
