INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7ab9453f-75b2-4b60-8e43-e7515012a9fe', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When building a multi-region system, what are the architectural challenges you prioritize regarding data replication?', N'Senior', N'I prioritize the latency impact of synchronous cross-region replication versus the risk of data loss in asynchronous replication. I typically choose asynchronous replication with multi-master or active-passive setups, ensuring conflict resolution strategies are clearly defined to handle write collisions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
