INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'684665a9-9f0d-4e2a-85ad-e75626c71762', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the purpose of the ''remix.config.js'' file?', N'Fresher', N'The config file is used to define project-specific settings for the framework. It allows developers to configure build paths, server-side entry points, and other environment-specific behaviors for the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f603972-76aa-41f0-bba9-e75b40ab3881', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you identify the root cause of a silent failure where the system returns a 200 OK but with incorrect data?', N'Middle', N'I would perform data reconciliation between the application output and the source of truth, such as the database or an upstream service. I would trace the data transformation pipeline to see where the logic deviates from expectations, often looking for stale cache entries or unhandled edge cases in data mapping. Logging the input and output of specific transformation functions is usually the most effective way to pinpoint where the logic failure occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcbf3d96-a773-40b8-ac06-e75b4ce37355', N'4c000000-0000-0000-0000-000000000005', N'Explain the difference between leader-based replication and multi-leader replication in terms of write availability.', N'Senior', N'Leader-based replication creates a single point of failure and bottleneck for writes, as all traffic must route to the primary node. Multi-leader replication improves write availability and latency by allowing writes at any local node, though it introduces significant complexity in conflict resolution and causal ordering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cda0bfdb-04c9-4cd2-9cb0-e75cb965c644', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you achieve observability in a distributed architecture where a single request spans multiple services?', N'Senior', N'Implement distributed tracing by injecting a correlation ID into the header of every incoming request. This ID is propagated across all service calls, allowing tools to reconstruct the full request flow and identify bottlenecks or points of failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6d5acc06-5213-4771-af85-e75cc1d2c480', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a header file?', N'Intern', N'A header file contains declarations of functions, classes, and variables that can be shared across multiple source files. It allows different parts of a program to access common interfaces without re-declaring them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e2ba153-b062-4acb-9540-e75d4b35da11', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you design a system to notify users when a long-running background task completes?', N'Middle', N'I would use a message broker to queue the task and a dedicated worker service to process it. Once complete, the worker would push a notification event to a real-time transport layer like WebSockets or a push notification service to update the user immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5221d651-9973-4bdf-a60e-e75e42649aee', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the ''JIT'' mode in Tailwind?', N'Intern', N'JIT stands for Just-In-Time mode. It generates CSS on-demand as you author your HTML, rather than generating all possible utility classes upfront, which leads to faster build times and more flexibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'941e2049-d985-4732-a20d-e762395d50f1', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the best way to handle shared state across different plugins?', N'Middle', N'Shared state should be managed by attaching it to the Fastify instance via a decorator within a root-level plugin. This makes the state globally accessible while maintaining clear ownership and initialization logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07b303c5-f71a-4591-8bf8-e764bbd1d722', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How does NestJS manage provider scope (Request, Transient, Singleton) and what are the performance implications?', N'Senior', N'Singleton is the default and most performant scope. Request-scoped providers are recreated for every request, which can cause significant latency and memory overhead, while Transient providers are unique to each consumer. Excessive use of non-singleton scopes should be avoided in performance-critical paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa872181-85b9-44e2-ad4a-e766c488a1b3', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How do Service Providers function within the AdonisJS framework?', N'Junior', N'Service Providers are the primary place to configure and register application services, such as database connections or third-party packages. They act as the bootstrapper for your code, ensuring that necessary dependencies are available before the application starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29acd6e0-2462-4e9f-87c4-e768669d549e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the advantage of using a standard format like JSON for data exchange between services?', N'Fresher', N'JSON is a language-agnostic, lightweight format that is easily human-readable and supported by almost every modern programming language. Its standardized nature ensures that different systems can reliably exchange and parse data without compatibility issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'046d76af-b20c-4932-ac37-e7689935c688', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are the advantages of using Flask-SQLAlchemy over raw SQL or standard SQLAlchemy?', N'Middle', N'Flask-SQLAlchemy simplifies the integration of the SQLAlchemy ORM by automating the setup of database sessions and teardown processes after each request. It also provides helper functions for pagination and configuration that align with Flask''s application patterns, reducing boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2c5436d-c4eb-4139-bbdd-e76cb6291821', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the difference between an Action and an Event in Ember?', N'Middle', N'An Action is an abstraction used to communicate user intent from the template to the component or controller. An Event is a raw DOM-level interaction; Ember wraps these events and promotes them to actions to maintain a clear boundary between the DOM and the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4378b849-4af0-40a1-a288-e76ecaf0d911', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Can Remix be used with a database?', N'Intern', N'Yes, Remix acts as the bridge between the browser and your database. You can write server-side code within loaders and actions to query your database and return the data directly to your components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7cde6e6-d3e3-4617-bbf2-e76fa922bf9a', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the concept of Null Safety in Dart.', N'Fresher', N'Null safety ensures that variables cannot contain null values unless explicitly declared as nullable. This prevents common runtime errors caused by accessing members of a null object, leading to more stable and reliable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5998823-c215-4a19-acb7-e7714fae98af', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'When considering data consistency, why is it risky to rely solely on the frontend for data validation?', N'Junior', N'Frontend validation is meant for user experience and immediate feedback, but it can be easily bypassed by malicious users or automated tools. The backend must always perform independent validation to ensure data integrity and security before processing any requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01c4e52a-d605-4933-af62-e7718c8aff96', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is a mailbox in the context of Actix actors?', N'Intern', N'A mailbox is a queue that stores incoming messages for an actor. Each actor processes the messages in its mailbox one by one to ensure thread-safe state modification.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
