INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b8ae3747-8679-4d57-9a45-e77c274892bc', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage memory in components that are removed from the DOM?', N'Senior', N'Alpine.js listens for DOM mutations to detect when elements are removed from the document, allowing it to clean up references and event listeners. However, if developers store long-lived references to component data in global variables, they may inadvertently create memory leaks, as the framework relies on the DOM''s lifecycle to trigger its own cleanup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e5e2284-1a22-44fc-afcb-e77d6e6ddd67', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you handle parameters in a controller action?', N'Fresher', N'When you work in Ruby on Rails, most of the data is accessed through ActiveRecord models, either by direct retrieval or through relationships. However, there are cases where you need to directly handle parameters, especially for more complex data flows or for actions that don''t involve models. Parameter Handling Rails'' ActionController::Parameters ensures that incoming parameters are secure, and it structures them, providing tools for effortless processing. This takes away the need for manual sanitation code or direct manipulation of the params hash. Security Benefits - Strong Parameters: Specify which parameters are permitted. This improves security by explicitly disallowing unwanted parameters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e18ea7a-337e-4758-9c57-e782508018d8', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'How are actions used to change the state in a Redux application?', N'Fresher', N'Redux follows a strict unidirectional data flow pattern, which means that actions are the only way to modify state. The Cycle of Action and State 1. Action Creation: You use Action Creators to create actions. 2. Dispatch: Actions are dispatched using store.dispatch(action). Here, the store is the single source of truth in a Redux app and is responsible for action delivery to reducers. 3. Reducer Listening: Reducers, which are pure functions, listen for dispatched actions. If a matching action is identified, the reducer performs the necessary state modifications and returns the new state. 4. Store Update: The updated state is then stored, and any bound UI components are notified for necessary updates. Key Points to Remember - State is read-only: Direct changes to state are not allowed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b7cccc2-04d8-490f-9de7-e783b5cd3421', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does database sharding impact system design?', N'Middle', N'Sharding distributes data across multiple nodes to improve read and write performance. While it solves scaling issues, it introduces significant complexity in managing cross-shard queries, data rebalancing, and maintaining referential integrity across the distributed nodes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6ffa2e6c-09af-4069-b2c7-e784ac39caf6', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the difference between shallow and deep copying in Java.', N'Middle', N'A shallow copy creates a new object but copies the references of the original object''s fields, meaning both objects share references to the same internal mutable objects. A deep copy creates a new object and recursively copies all objects referenced by the original, ensuring complete independence between the two. Deep copying is more resource-intensive but safer for maintaining data integrity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
