INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4409bb04-a8a2-4f7a-90cb-e7b1520d5854', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of the NestJS ''EventEmitter'' in decoupling system components?', N'Senior', N'The EventEmitter provides a built-in pub/sub mechanism that allows services to communicate asynchronously without direct dependencies. This promotes loose coupling, as the producer of an event does not need to know which services are listening, making it easier to add new features or side effects without modifying existing business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e909e8e-abef-4c27-86e9-e7b25d3539cd', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the trade-offs between using Django''s built-in User model and creating a custom one.', N'Middle', N'Using the built-in User model is fast for simple projects but lacks flexibility if you need different authentication fields later. Creating a custom User model at the start of a project is recommended because changing it after database migrations have been applied is complex and error-prone.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c09c595-cd7c-4a43-9a0f-e7b2fa48f7c0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the function of a foreign key constraint?', N'Fresher', N'A foreign key constraint maintains referential integrity by ensuring that a value in one table must match a value in another related table. It prevents actions that would leave orphaned records or break the link between associated data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf0246f0-ae60-45bc-9a6f-e7b352d371da', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'Explain the significance of Hono''s ''Hono-JSX'' or SSR capabilities in the context of unified backend-frontend architecture.', N'Senior', N'Hono''s built-in JSX support enables server-side rendering directly within the backend logic, allowing developers to share types and data-fetching patterns between the server and the UI layer. This reduces the complexity of maintaining separate frontend and backend projects, promoting a more cohesive and type-safe architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e27f03b4-f828-4275-9f1c-e7b61ce5fd2b', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the role of Pydantic in FastAPI''s performance and data validation architecture.', N'Senior', N'Pydantic uses Python type hints to perform runtime data validation and serialization. By offloading these tasks to optimized core libraries written in Rust, it ensures high performance while maintaining strict schema enforcement between the request body and the application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee9cdcb6-1db0-47c4-8e9a-e7b9b929736f', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you decide whether to handle validation on the client-side, server-side, or both?', N'Junior', N'Client-side validation is for user experience and immediate feedback, but it is never enough for security. Server-side validation is mandatory because you can never trust data coming from the client, ensuring the integrity and security of your database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
