INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73dc41fc-a97d-404d-a931-e7bfc7e3b0d1', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch achieve horizontal scalability through sharding, and what are the implications of choosing an incorrect shard count?', N'Senior', N'Elasticsearch distributes data across multiple nodes using primary and replica shards. An insufficient number of shards limits the ability to scale horizontally, while too many shards lead to ''over-sharding,'' which increases memory overhead for metadata, puts pressure on the cluster state, and slows down recovery processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f071c8a7-70ba-42cf-889a-e7c05f5804c9', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Can a transaction contain read-only operations?', N'Fresher', N'Yes, a transaction can consist of read-only operations. Even if no data is changed, grouping select queries into a transaction ensures that the data read remains consistent throughout the entire process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63b4aa03-3732-45d2-b3a7-e7c0b7a3e8d7', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Describe the role of the ''Implicit Conversion'' and the risks it poses in large-scale system architecture.', N'Senior', N'Implicit conversions allow the compiler to automatically transform one type into another to satisfy a type mismatch, which can be useful for domain-specific language design. However, they significantly reduce code readability by hiding transformation logic and can introduce performance bottlenecks or runtime errors if complex conversions are triggered implicitly. In large systems, they are often discouraged in favor of explicit extension methods to maintain predictable code paths.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
