INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35e2314c-f29a-4e48-9517-e7dc9760d78b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the ''Netty'' event loop in Micronaut?', N'Middle', N'The Netty event loop is the core of Micronaut''s networking layer, managing all incoming and outgoing non-blocking I/O operations. It ensures that the application thread pool is not blocked by waiting for network responses, maximizing throughput under high load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6eb542ec-9962-4e63-bc3b-e7e1310b9138', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the purpose of Redis replicas?', N'Junior', N'Replicas are copies of the primary Redis instance used to provide read scaling and fault tolerance. By directing read operations to replicas, you can offload the primary node, and if the primary fails, a replica can be promoted to maintain service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'861a9f2c-180b-49e6-ac24-e7e214cf171c', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the impact of excessive ''chattiness'' in API design and how do you mitigate it?', N'Senior', N'Chattiness increases network latency and resource overhead due to frequent round-trips for small pieces of data. Mitigation strategies include implementing field filtering, supporting bulk resource retrieval, or utilizing GraphQL to fetch required graphs in a single request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
