INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7091bab0-4eb0-4443-8b35-e7f6361e6750', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'Why does Go use goroutines instead of OS threads?', N'Junior', N'Goroutines are much more lightweight than OS threads, requiring significantly less memory and having faster startup times. This allows a single Go program to manage thousands or even millions of concurrent tasks efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29e383c4-c8c2-42f2-9b75-e7f94ef1e01b', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R handle method dispatch in the S3 system?', N'Middle', N'Method dispatch in S3 occurs when a generic function is called and uses the class attribute of the first argument to find the appropriate implementation. The system searches for a function named by concatenating the generic name, a dot, and the class name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
