INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'954eee44-3091-4b14-8cb7-e7fb7a607063', N'a2838158-7305-480a-b22b-4dc35776b400', N'What are the primary architectural challenges when implementing multi-leader replication?', N'Senior', N'The main challenge is conflict detection and resolution, as writes can occur concurrently on different nodes without immediate coordination. This necessitates techniques like Last-Write-Wins, vector clocks, or operational transformation to merge divergent data states. It also complicates read-after-write consistency, as a client may read from a replica that has not yet received the latest updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d2b26d0-39a0-4a98-ace5-e8021832778b', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does Elasticsearch handle full-text search?', N'Fresher', N'Elasticsearch uses analyzers to break down text into tokens, which are then stored in an inverted index. When a user searches, the engine matches the query terms against these tokens to find relevant documents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0c14b39e-2738-4b65-aa2c-e8024a74fe3e', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a major trade-off when using pointer receivers versus value receivers?', N'Middle', N'Value receivers copy the data, which is safe from side effects but can be expensive for large structs. Pointer receivers avoid the copy and allow the method to modify the original instance, but they can lead to memory aliasing issues if not managed carefully.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f5a34b8-28b5-4132-9bbf-e8029b99b4fe', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What are the trade-offs of using a user-space scheduler for fibers compared to relying on the OS kernel scheduler?', N'Middle', N'User-space scheduling is highly efficient because it avoids the overhead of kernel transitions and can be optimized for specific application patterns. However, it requires the runtime to be responsible for preemption and load balancing across cores, which adds complexity and potential issues if the scheduler is not perfectly implemented to handle long-running compute tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
