INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fda7ad94-2339-4a2d-815d-e8100b433928', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What is the role of HATEOAS in RESTful API design, and why is it often omitted in practice?', N'Senior', N'HATEOAS allows clients to discover API capabilities dynamically via hyperlinks included in responses, theoretically decoupling the client from URI structures. It is often omitted because it increases payload size, adds implementation complexity for both server and client, and most developers prefer static documentation over runtime discovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'282a31fd-2819-4d6c-be25-e811022bee89', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the difference between ''npm install'' and ''npm ci''?', N'Junior', N'npm install is used for local development and may update the package-lock.json file if new compatible versions are found. npm ci is designed for automated environments, strictly following the package-lock.json file and deleting the node_modules folder before installation for a clean build.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b11aa0b-a3fb-4140-baee-e8129b4954f6', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the benefit of Litestar''s ''Before Request'' and ''After Response'' hooks in a microservices architecture?', N'Senior', N'These hooks provide standardized entry and exit points for cross-cutting concerns like observability, metrics collection, and security header injection. By abstracting these logic blocks into hooks, services remain clean and compliant with organizational standards without repeating boilerplate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e814f8f-0fd6-45ec-b9db-e812d262a117', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the role of a scheduler in a fiber-based system?', N'Intern', N'The scheduler is responsible for deciding which fiber should run next on a given thread. It maintains a queue of ready-to-run fibers and coordinates the switching process when a running fiber yields control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f75bc251-d6e3-46d1-8399-e813e044ed9b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does data binding work in Ember?', N'Intern', N'Data binding in Ember automatically synchronizes data between the JavaScript objects and the DOM templates. When the underlying data changes, the UI updates automatically, ensuring the view is always in sync with the state of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b49e073d-e181-4bfb-814c-e81406285465', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is ''idempotency'' and why is it critical for distributed reliability?', N'Middle', N'Idempotency ensures that performing an operation multiple times has the same effect as performing it once. It is critical in distributed systems to prevent data corruption or duplicate side effects when retrying requests that may have failed due to network issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ceeb02ed-cf57-47ab-bb23-e81a0eb8590d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket optimize for binary size and compile time compared to other frameworks?', N'Senior', N'Rocket relies heavily on procedural macros, which can significantly increase compile times. To mitigate binary bloat, it utilizes conditional compilation features and modular design, allowing developers to opt-out of unnecessary components, though it generally prioritizes type safety and expressive syntax over raw compilation speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8556a516-008e-478b-a15f-e81a12bef48c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary architectural difference between React and Preact regarding internal state management?', N'Middle', N'Preact prioritizes a minimal footprint by using a simplified internal structure. It implements a more direct approach to component updates, avoiding the complex fiber architecture found in React to keep the bundle size significantly smaller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a29153de-288a-4abb-8d13-e81cb7de549f', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What are Content-Type Parsers used for?', N'Junior', N'Content-Type Parsers allow Fastify to handle different request body formats beyond standard JSON. You can register custom parsers to handle formats like plain text, binary data, or custom media types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'285f0610-d799-4c56-b557-e81d96d680cc', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Discuss the performance implications of the Ruby Global Interpreter Lock (GIL) on Rails applications.', N'Senior', N'The GIL ensures only one thread executes Ruby code at a time, limiting CPU-bound performance gains from multi-threading within a single process. While I/O-bound tasks still benefit from threads, Rails applications often scale better by utilizing multiple processes with a few threads each to bypass this limitation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cd72b4b-4ecf-4243-ac74-e81ea6cf6451', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the impact of Preact''s lack of a synthetic event system on browser debugging?', N'Middle', N'Because Preact uses native DOM events, debugging is more straightforward as developers can inspect events directly via standard browser developer tools. There is no need to navigate through complex internal synthetic event wrappers, making the stack trace clearer and more representative of the actual DOM execution flow.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f57b759-7502-44e2-b907-e81eb695e6c6', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'Compare the performance of Gin''s routing tree to a standard map-based router.', N'Middle', N'A radix tree (or prefix tree) used by Gin is more memory-efficient and faster for route lookup because it avoids hashing collisions. As route complexity increases with path parameters, the tree structure scales better than a flat map which requires parsing and matching segments repeatedly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
