INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11c7be30-452a-4b8d-a64c-e82fe0ea69e9', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the primary function of the translog and how does it contribute to data durability?', N'Senior', N'The translog acts as a write-ahead log that records every operation before it is committed to the Lucene index. It ensures data durability in the event of a node crash, as operations can be replayed from the log during recovery.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
