INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3defe350-59ac-4fdc-b40c-e833b36222fb', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Explain the concept of ''middleware chaining'' in Express.', N'Middle', N'Middleware chaining is the sequential execution of functions where each function performs a task and optionally passes control to the next. This modular architecture allows developers to build complex request processing pipelines by combining reusable units of logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b7ce8cc-0af2-4681-b4ad-e8388582b0e4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is DOM reflow?', N'Intern', N'Reflow is the name of the web browser process for re-calculating the positions and geometries of elements in the document, for the purpose of re-rendering part or all of the document. Reflow occurs when * insert, remove or update an element in the DOM * modify content on the page, e.g. the text in an input box * move a DOM element * animate a DOM element * take measurements of an element such as offsetHeight or getComputedStyle * change a CSS style * change the className of an element * add or remove a stylesheet * resize the window * scroll Minimizing browser reflow * Reduce unnecessary DOM depth. Changes at one level in the DOM tree can cause changes at every level of the tree - all the way up to the root, and all the way down into the children of the modified node.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e621a3df-b279-4262-bdec-e838c973c52a', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Template Literal Types and what use cases do they address?', N'Middle', N'Template literal types allow you to manipulate string types by performing concatenation or mapping operations on string literals. They are useful for creating type-safe strings for complex patterns like CSS class names, event names, or dynamic API routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'582b9133-2e08-440d-a49b-e839b5f0c68d', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Explain browser console logs features?', N'Fresher', N'The Console method log() outputs a message to the web console. The message may be a single string or it may be any one or more JavaScript objects. 1. console.table() Output 2. console.log() 3. console.warn() 4. console.error()', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'163a302f-3cf6-4ea6-899a-e839de94add2', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What are ''Responders'' in Axum?', N'Fresher', N'Responders are types that can be converted into an HTTP response. Axum allows handlers to return any type that implements the IntoResponse trait, which provides flexibility in returning status codes, headers, or body content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'608aff6e-a05e-4894-83d8-e83a9977f90e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the difference between Redux and Context API?', N'Fresher', N'Context API is a built-in React feature for passing data through the component tree without prop drilling. Redux is a more robust, independent library designed for managing complex state with advanced debugging tools and middleware support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63f19c8c-86bd-4128-ad78-e83ab7760d28', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If a deployment fails, what is the first thing you should do?', N'Junior', N'The first step is to roll back the deployment to the last known stable version to minimize downtime for users. After the system is restored, I would investigate the logs to identify the cause of the failure and prevent it from recurring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4b341839-f912-42e3-b6ad-e83b39d2955d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM maintain binary compatibility despite evolving language specifications?', N'Senior', N'The JVM maintains binary compatibility through a stable, well-defined class file format and a strict set of rules for bytecode verification and class loading. This ensures that compiled bytecode remains functional across different versions of the JDK, provided that the underlying API signatures and behavioral contracts are preserved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74892e83-f96d-412b-88e4-e83c447d8342', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What intermediate methods of working with streams do you know?', N'Junior', N'* filter() filters records, returning only records matching the condition; * skip() allows you to skip a certain number of elements at the beginning; * distinct()returns a stream without duplicates (for a method equals()); * map() converts each element; * peek() returns the same stream, applying a function to each element; * limit() allows you to limit the selection to a certain number of first elements; * sorted()allows you to sort values ​​either in natural order or by setting Comparator; * mapToInt(), mapToDouble(), mapToLong()- analogues map()return stream numeric primitives; * flatMap(), flatMapToInt(), flatMapToDouble(), flatMapToLong()- similar to map(), but can create a single element more.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'502e42db-cc83-4fe7-b6e4-e83ea8c9deab', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is your approach to securing sensitive user data in transit and at rest?', N'Middle', N'For data in transit, I enforce TLS encryption for all communications. For data at rest, I use robust encryption standards like AES-256 and ensure that cryptographic keys are managed securely through a dedicated key management service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0f0e058-cf56-4096-8d36-e83fa9bbda1f', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is the importance of logging context, and how does it help in troubleshooting?', N'Middle', N'Logging context, such as user IDs, session IDs, and request metadata, allows developers to reconstruct the specific sequence of events for a single interaction. Without this context, logs become a chaotic stream of events that are difficult to correlate to a specific user''s reported problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43d4550c-860e-42d1-a8ce-e840118ebdeb', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you unit test a FastAPI application?', N'Middle', N'You can use the ''TestClient'' class from the ''fastapi.testclient'' module, which is built on the requests library. It allows you to simulate HTTP requests to your app without actually starting a server, making it easy to test routes, status codes, and JSON responses in an isolated environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdf2aab9-39da-4372-b010-e84306a1f0dc', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the benefit of the ''inputmode'' attribute?', N'Middle', N'The inputmode attribute hints at the type of virtual keyboard that should be displayed for an input field on mobile devices. For example, setting it to ''numeric'' or ''email'' displays a keyboard optimized for those inputs. This improves the user experience by reducing the number of steps required to input specific types of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd08771c9-17ce-498c-a933-e8438a5bf3fd', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo facilitate graceful shutdowns, and why is this critical for distributed systems?', N'Senior', N'Echo exposes the underlying HTTP server, allowing developers to call the shutdown method to stop accepting new requests while finishing active ones. This is essential for zero-downtime deployments and ensuring that database transactions or file operations are not abruptly terminated.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b27fdbcd-13c4-4f7c-b9b0-e845367b1747', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does the framework''s OpenAPI integration assist in contract-driven development?', N'Senior', N'Litestar automatically generates the OpenAPI schema based on the application''s handlers, types, and DTOs. This enables contract-driven development where the API schema is the single source of truth, facilitating parallel development between frontend and backend teams.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e51aa5c3-0496-48dd-859b-e847ce245544', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you ensure system performance during heavy traffic spikes?', N'Senior', N'I implement load shedding and rate limiting to protect core services, ensuring that critical operations succeed even under load. I also use background processing and caching to offload work from synchronous paths, maintaining a baseline level of service for all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c77bc3e8-392f-423d-b339-e848a3b7e411', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Explain the role of the ''Mount'' functionality in Chi and its impact on service composition.', N'Senior', N'The Mount function allows for mounting sub-routers at specific path prefixes, enabling the composition of large applications from smaller, isolated packages. This promotes a plugin-like architecture where different services or API versions can be integrated into the main router without knowing the implementation details of the others.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39ee513f-e5aa-49c7-8fd3-e8492f97a55b', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does Ember''s Glimmer VM improve rendering performance compared to traditional DOM-based templating engines?', N'Senior', N'The Glimmer VM compiles templates into a custom bytecode that is executed by a lightweight virtual machine. This approach minimizes DOM operations by tracking granular data dependencies and updating only the specific nodes that have changed, rather than re-rendering entire component trees.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4412d94d-c055-447c-81bf-e84a48b4a983', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle error management?', N'Fresher', N'Echo uses a centralized HTTP error handler that catches errors returned by handlers or middleware. This allows developers to define custom error pages or JSON response formats for different HTTP status codes in one place.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01c55949-86c9-4043-8b44-e84b8722e06c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''keyof'' operator used for?', N'Junior', N'The ''keyof'' operator creates a union type consisting of all the property names of a given type. It is useful for creating functions that safely access properties of an object based on its keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c93aaa79-3d0e-4f8b-a9cd-e84d6ae03af4', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is documentation often considered a trade-off in fast-paced engineering environments?', N'Intern', N'Documentation is time-consuming to create, which can divert resources away from feature development. However, the trade-off is that lacking documentation leads to higher knowledge silos and slower onboarding for future team members, creating long-term technical friction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9e2ceff-157a-4eba-b5ba-e84e6df7be69', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the significance of the ''common'' block in legacy C compilers versus modern standards?', N'Senior', N'Common blocks allow multiple translation units to declare uninitialized global variables with the same name, which the linker merges into a single storage unit. Modern standards encourage explicit definitions to avoid the ambiguity inherent in common block merging, as it can lead to unexpected initialization behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aee49ab7-619c-481b-93ee-e84f4140db4b', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle ''hot-reloading'' and state persistence in a long-running Express process?', N'Senior', N'Hot-reloading in production is risky, so Express apps usually rely on process managers like PM2 to perform zero-downtime restarts. State persistence must always be externalized to a database or cache, as local memory is volatile and lost during process rotation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b082e32-8d68-4b85-ba4f-e85065c1775f', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How can Fairings be used to implement cross-cutting concerns like logging or timing?', N'Middle', N'Fairings can hook into the request-received and response-sent events to track the execution time of handlers or log request metadata. By implementing these as Fairings, you maintain a clean separation of concerns, keeping your route handlers focused strictly on business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5e7d270-6c49-43d5-817e-e850f85b8d79', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'In what scenarios would you choose ''Partitioning'' over ''Sharding'' for a large MySQL database?', N'Senior', N'Partitioning is used to manage large tables on a single server by splitting data logically into smaller files, which improves maintenance and query performance for time-series data. Sharding is used for horizontal scaling across multiple physical servers when a single instance can no longer handle the total write or storage volume.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5794f023-11a3-4bd0-abb6-e8517201ea99', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the use of the ''page'' store in SvelteKit?', N'Fresher', N'The page store provides reactive access to information about the current route. It includes data such as the current URL, parameters, and form state, allowing components to react to navigation changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04cc96f5-a6b6-48dc-8b4a-e852bec297a6', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the limitations of React?', N'Intern', N'Apart from the advantages, there are few limitations of React too, 1. React is just a view library, not a full framework. 2. There is a learning curve for beginners who are new to web development. 3. Integrating React into a traditional MVC framework requires some additional configuration. 4. The code complexity increases with inline templating and JSX. 5. Too many smaller components leading to over engineering or boilerplate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'936540d4-0fff-47da-8431-e853255a1dab', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the purpose of SvelteKit''s ''load'' functions, and why is it important to handle data fetching there rather than in component lifecycle hooks?', N'Middle', N'Load functions are designed to fetch data before a page or layout is rendered, ensuring that all necessary information is available to the component upon mounting. By placing data fetching here, you prevent ''waterfall'' issues and layout shifts, allowing the server to populate the initial HTML response fully before sending it to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'780ab963-4c76-4fc5-a553-e8535d4d7467', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the ''partial'' keyword used for?', N'Intern', N'The partial keyword allows the definition of a class, struct, or method to be split across multiple files. This is useful for separating auto-generated code from manual logic within the same logical type.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c4fdc4c-95f8-446f-96a0-e855d79117fc', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you prioritize tasks when you have multiple assignments due at the same time?', N'Fresher', N'I evaluate the urgency and importance of each task based on dependencies and impact. I then create a plan that addresses the most critical tasks first to ensure deadlines are met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b08aa83e-dad5-432c-ac52-e855f0f9c42b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Explain the role of Flask Blueprints in modularizing a large codebase.', N'Senior', N'Blueprints allow you to partition a large application into smaller, reusable components, each with its own set of routes, templates, and static files. This improves maintainability and allows teams to work on different modules independently while still being registered under a single application instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcf450e3-5309-4fb6-bca6-e8584daf8426', N'a2838158-7305-480a-b22b-4dc35776b400', N'Explain the concept of ''split-brain'' in a distributed cluster and how it is mitigated.', N'Senior', N'Split-brain occurs when a network partition causes a cluster to divide into two or more sub-clusters that each believe they are the primary, leading to data divergence. This is mitigated by using a quorum-based approach where a majority of nodes must agree to elect a leader, effectively isolating the minority partition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'563c3ce2-c25a-4597-b816-e858e735c70b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is the Gin framework in the context of Go?', N'Intern', N'Gin is a high-performance web framework for the Go programming language. It is designed to be lightweight and fast, providing a robust set of tools for building web applications and microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'23cbab49-4fe8-4d4e-a844-e85de3b89fcb', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the advantage of using ''Quarkus REST'' (formerly RESTEasy Reactive)?', N'Middle', N'Quarkus REST is a non-blocking implementation of JAX-RS that is built specifically for the reactive engine. It is significantly faster and more memory-efficient than traditional blocking REST frameworks, making it the preferred choice for high-performance microservices.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c674c761-9094-44a3-85d8-e8609b1675d3', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket manage the lifecycle of a request?', N'Middle', N'The lifecycle begins with parsing the request, moving through applicable guards, executing the handler, and finally converting the return value into a response. Each step is designed to be short-circuited if a guard fails, ensuring that only fully validated requests reach the handler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'129b808f-afc3-46d5-9c2a-e860e62602e9', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about selecting between a managed cloud service and a self-hosted solution?', N'Middle', N'I weigh the operational burden of managing the infrastructure myself against the cost and flexibility limitations of a managed service. Managed services are preferred when the team lacks domain expertise or when speed-to-market is the primary goal, while self-hosting is chosen for cost optimization at scale or strict data sovereignty requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22aeea02-09ac-4ec9-a598-e865d090ef45', N'954a0331-deff-4399-b588-96f39fec001d', N'How do you handle events in Angular templates?', N'Fresher', N'In Angular templates, you handle events using event binding syntax, which looks like (eventName)="statement". The eventName is typically a standard DOM event like click, input, or submit, but it can also be a custom event emitted by a component using @Output. The statement is a template statement that Angular executes when the event occurs, usually involving calling a method defined in the component class. You can access the event payload using the $event variable within the statement. For example, to handle a button click: To get the input value from an input field: And in the component class: > Try out Angular coding questions on GreatFrontEnd. ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5fde0bdf-9013-4791-985d-e865e7410577', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the architectural implication of SolidJS''s ''compiler-assisted'' reactivity?', N'Senior', N'The compiler transforms JSX into optimized imperative DOM operations, effectively turning a declarative template into a set of precise updates. This allows the framework to know exactly which DOM nodes depend on which signals, bypassing the need for a runtime reconciliation tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
GO
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b69dd5e4-7b39-4e9d-8fdf-e86600d19bb0', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What are ''hover'', ''focus'', and ''active'' states in Tailwind?', N'Intern', N'These are state variants that allow you to style elements when a user interacts with them. By prefixing utility classes with these keywords, Tailwind automatically generates the necessary pseudo-class CSS for those interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69db1cf4-3cc5-4c29-8200-e8674c5af86d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why is it dangerous to perform side effects directly in the main body of a functional component?', N'Senior', N'React components should be pure functions with respect to props and state. Side effects in the main body can execute multiple times during a single render cycle or even during discarded render attempts, leading to inconsistent state, infinite loops, or memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4740f20-e1cd-4c52-863f-e86a450d95f6', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the benefit of using constants instead of hardcoding values throughout your project?', N'Fresher', N'Using constants improves maintainability by providing a single source of truth for values that might change later. If a value needs to be updated, you only modify it in one location instead of searching for every instance throughout the entire codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e3483df-a854-4051-8d31-e86eee9a3dfa', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'How does pointer arithmetic interact with data types in C?', N'Middle', N'Pointer arithmetic is scaled by the size of the underlying data type pointed to by the pointer. When you increment a pointer, it moves forward in memory by the number of bytes required to reach the next element of that specific type, rather than just one byte.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7a969d9-a860-4a66-8755-e8707473d8eb', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Explain the difference between Type Widening and Type Narrowing in the context of the TypeScript compiler.', N'Senior', N'Type widening occurs when the compiler infers a more general type for a mutable variable, such as treating a literal as a broad primitive. Narrowing is the process of moving from a general type to a more specific one, typically achieved through control flow analysis like type guards, ensuring type safety in conditional branches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c71243a7-0022-4cd3-b59b-e8735aca5a23', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the Garbage Collector in C#?', N'Intern', N'The Garbage Collector automatically manages memory by reclaiming memory occupied by objects that are no longer being used by the application. This helps prevent memory leaks and removes the need for manual memory deallocation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
