INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a79b145f-2407-47fe-b305-e87a333a0cba', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Explain the difference between ''Pessimistic'' and ''Optimistic'' concurrency control.', N'Senior', N'Pessimistic locking prevents conflicts by locking resources before modification, which is effective for high-contention environments but reduces concurrency. Optimistic concurrency control assumes conflicts are rare and validates versions at commit time, providing higher throughput at the cost of potential transaction retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
