INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'521d27fa-0332-4c8f-b2e5-e8838f91b522', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does ''Const Assertions'' change the way TypeScript infers literal types?', N'Senior', N'Const assertions instruct the compiler to infer the most specific, literal type for an expression rather than widening it to a base type like string or number. This is crucial for defining configuration objects or state machines where literal values must be strictly preserved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
