INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b391ca25-2ca5-47cb-afb7-e88627b9352d', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does the Symfony Routing component function?', N'Fresher', N'The Routing component maps an incoming HTTP request URL to a specific controller action. It parses defined routes from configuration files or attributes, matches them against the request path, and extracts any parameters to be passed to the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0623b902-5be5-4f78-a803-e888b4e34ad0', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you receive two conflicting requirements from different stakeholders, how do you handle it?', N'Junior', N'I would document both requirements and schedule a meeting with both stakeholders to clarify the business goals. My goal is to facilitate a conversation that aligns their expectations with the project''s overall objectives and technical feasibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
