INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3782433d-f412-44cd-bcf1-e88a9fcdd840', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a trait?', N'Intern', N'A trait defines shared behavior that types can implement. It allows you to write functions that work with any type that provides a specific set of methods, enabling polymorphic behavior in a type-safe way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9a9a6eb-ad19-41d8-b9a1-e88b9dc16751', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you are asked to estimate the number of tennis balls that can fit into a plane, how would you reason through it?', N'Fresher', N'I would estimate the volume of the plane''s interior and the volume of a single tennis ball. I would then account for the packing efficiency, as spheres cannot occupy 100 percent of the space, to arrive at a reasonable approximation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51d24b59-9b37-4743-b5cf-e88bf5c2f289', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What are configuration variables in Flask?', N'Intern', N'Configuration variables are settings used to control the behavior of the Flask application, such as the secret key used for sessions or database connection strings. They are typically stored in a configuration object or file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'822f6a5d-7792-4f76-b93e-e88c8a35d19b', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono compare to Express?', N'Intern', N'Hono is conceptually similar to Express in its use of middleware and routing, but it is much lighter and designed for modern, non-Node.js environments. It focuses on performance and compatibility with edge computing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd66673d3-a4c4-41e4-a9f2-e88e43e16f88', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'How can database indexes affect write performance in a scalable system?', N'Middle', N'While indexes significantly speed up read queries, each write operation requires the system to update the index trees. Excessive indexing can lead to slower write performance and increased storage overhead, necessitating a balance between read and write optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6866cce4-29a4-484a-9f98-e8954f745cac', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Kestrel?', N'Intern', N'Kestrel is the cross-platform, open-source, event-driven, asynchronous web server used by default in ASP.NET Core applications. It is designed to be lightweight and fast, usually placed behind a reverse proxy like Nginx or IIS.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9807286a-7371-43c6-8bb9-e89868da7053', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What are the architectural risks of sharing global state via Alpine.js''s $store compared to a dedicated store like Redux or Pinia?', N'Senior', N'Alpine''s $store lacks the formal action/mutation structure and middleware support found in robust state management libraries. This can lead to unpredictable state mutations across the application, making it difficult to track state changes, implement time-travel debugging, or enforce strict data flow constraints in large-scale enterprise applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa7303fa-1997-446f-8937-e8994aff54a4', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the benefit of SvelteKit''s ''shallow routing'' or ''parallel loading'' capabilities?', N'Middle', N'SvelteKit executes load functions in parallel across the layout hierarchy, significantly reducing the total time spent waiting for data. This architecture ensures that the page displays content as soon as the slowest necessary request completes, rather than waiting for every single piece of data sequentially.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f7ca5dd-b4d5-4dc2-b1e2-e899bec8bd66', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle routing?', N'Fresher', N'Express handles routing by matching the request URL and HTTP method against defined route paths. When a match is found, the associated callback function is executed to handle the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12ed0208-648a-4e16-a32b-e89bd140ce34', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How do Webpack plugins differ from loaders?', N'Intern', N'While loaders perform transformations on a per-file basis during the bundling process, plugins are used for more complex tasks that affect the entire bundle. Plugins can perform actions like bundle optimization, asset management, and environment variable injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4dbe3ea2-ae61-4ac0-afa7-e89de6f6e824', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Why does Fastify use a ''fast-json-stringify'' library internally?', N'Middle', N'Standard JSON.stringify is slow because it inspects the object structure at runtime to determine how to serialize it. Fast-json-stringify uses the schema to generate an optimized function that knows exactly how to serialize the object, drastically increasing speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d147b4a-d03b-4240-96ba-e89e40fc3ed3', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the role of the Symfony Messenger component?', N'Intern', N'The Messenger component allows applications to send and handle messages, which can be processed synchronously or asynchronously. It is commonly used for background tasks like sending emails or processing file uploads without blocking the user''s request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a609bc8-625c-4e54-ad5f-e89f8a5379f7', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do CSS Houdini APIs allow for extending the browser''s rendering engine?', N'Senior', N'CSS Houdini provides low-level APIs that allow developers to hook into the styling and layout processes. By writing custom paint or layout worklets, developers can implement complex visual effects or layout behaviors that run at the same speed as native browser features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'32cd32f2-a853-40f3-ba30-e89fb44d0c0e', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the Svelte compiler in tree-shaking unused reactive declarations?', N'Senior', N'The compiler performs static analysis to determine if reactive declarations depend on state that is never modified or utilized within the component. If a reactive statement is determined to be dead code, the compiler omits it from the final generated JavaScript, ensuring that the bundle only contains logic essential for the component''s functionality.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4ea8bb17-4374-46c2-9f82-e8a2f55b8b2f', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Discuss the trade-offs of using ''Surrogate Keys'' versus ''Natural Keys''.', N'Senior', N'Natural keys use existing data, which can lead to performance issues if they are long strings or if the business logic changes. Surrogate keys, such as auto-incrementing integers or UUIDs, are independent of business data, ensuring stability and better indexing performance at the cost of requiring an extra lookup for identity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9701de5e-f83a-4b1e-81a8-e8a3a395b16e', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the difference between AddScoped, AddTransient, and AddSingleton in Dependency Injection?', N'Middle', N'AddTransient creates a new instance every time it is requested. AddScoped creates an instance once per client request, while AddSingleton creates a single instance the first time it is requested and reuses that same instance for all subsequent requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'548426d7-dc55-4b44-802d-e8a41a668574', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Does SvelteKit require a backend server to run?', N'Fresher', N'It depends on the adapter used. If you use a server-side adapter, you need a Node.js server, but if you use a static adapter, the application can be served from simple static file hosting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33da5017-a1ee-4f2e-b1fe-e8a5a5927b6e', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the purpose of the deinit method in a class?', N'Fresher', N'The deinit method is called automatically just before a class instance is deallocated from memory. It is primarily used to perform cleanup tasks, such as closing file handles or invalidating timers, to prevent memory leaks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1d1b8e16-2b96-46f0-981c-e8a983ab61f0', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the role of the ''avvio'' library in Fastify''s lifecycle?', N'Senior', N'Avvio is the asynchronous bootstrapping library that manages the loading of plugins in Fastify. It ensures that plugins are registered and initialized in the correct order, handling asynchronous dependencies properly so that the server only starts once all plugins have successfully loaded their configurations and routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e9b7d29-f426-4458-ba2a-e8ae44fb448b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the role of the Micronaut Ahead-of-Time (AOT) compilation process?', N'Intern', N'The AOT compilation process pre-computes dependency injection metadata, bean definitions, and aspect-oriented proxy logic during the build phase. This eliminates the need for reflection at runtime, making the application significantly more efficient.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'01d5ef4c-eec3-4ab4-af64-e8b03ef2e7dc', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the primary benefit of Fiber''s routing engine?', N'Junior', N'Fiber''s routing engine is designed for high performance and speed by using a trie-based structure to match routes. This allows the application to resolve incoming requests to the correct handler very quickly, even with a large number of routes defined.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c63524b-c81c-4704-b07f-e8b093264c4c', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why is Preact''s approach to the ''key'' prop crucial for list performance?', N'Senior', N'The key prop allows Preact''s diffing engine to track list items by identity rather than index, preventing unnecessary DOM re-creation when elements are reordered or filtered. Proper key usage is essential for maintaining UI state integrity and performance in dynamic collections.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b671a567-4a1a-4eb0-bfd0-e8b0986dbc16', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the trade-off of using eventual consistency in a distributed system?', N'Middle', N'Eventual consistency allows for higher availability and better performance by not requiring every replica to be updated simultaneously. The trade-off is that users may temporarily see stale data, which requires careful design to manage in user-facing applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37e19c00-3714-4938-983b-e8b3eed7817a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle a distributed transaction across three independent microservices while ensuring data consistency?', N'Senior', N'Instead of using traditional two-phase commits, which hinder availability, I would implement the Saga pattern. This uses a sequence of local transactions coordinated via events or messages, where each step includes a defined compensation logic to roll back changes if a subsequent step fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eaafc32-f3e2-428a-9cfc-e8b625418313', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How do SvelteKit layout files (+layout.svelte) handle data inheritance?', N'Middle', N'Layout files allow you to share components and data across multiple pages in a hierarchy. Data returned from a layout''s load function is passed down to all nested child pages, enabling you to fetch shared global data once and provide it to the entire route branch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
