INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ec3e3be-d0bd-4bef-b72f-e8b9b76e77db', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you find a contradiction in the project requirements, what do you do?', N'Intern', N'I would stop work immediately to avoid building the wrong solution. I would reach out to the project owner or stakeholder to clarify the intent, present the conflict I discovered, and ask for a definitive decision on which requirement takes precedence.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd660715-64a3-47ff-9a83-e8bcc746b76a', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary architectural difference between Remix and traditional client-side SPAs?', N'Middle', N'Remix is a server-centric framework that relies on standard web APIs like Request and Response objects. Unlike SPAs that fetch data after the page loads, Remix fetches data on the server before the page renders, minimizing the need for loading states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'972bd7bf-bdcd-49d1-9fd4-e8bcd8f8bc30', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you handle a situation where a developer’s estimate is significantly higher than the rest of the team''s?', N'Senior', N'I facilitate a discussion where the developer explains their rationale, specifically looking for hidden risks or edge cases they identified that others might have missed. If their concerns are valid, the team updates their estimates; if not, we use the discussion to clarify requirements and reach a consensus.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b8238f5-4a71-4cdc-b7bf-e8bd988b6904', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the ''nil'' object in Ruby?', N'Junior', N'In Ruby, nil is an object that represents the absence of a value or the ''nothing'' state. It is the sole instance of the NilClass and evaluates to false in a boolean context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6477d0b3-a1dc-4efd-9aed-e8bdf4fd4b5b', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the purpose of the jQuery .on() method?', N'Junior', N'The .on() method is the standard way to attach event handlers to selected elements. It supports event delegation, which allows you to bind a single event listener to a parent element that triggers for current and future child elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81d2cce0-5ff5-45bd-85cc-e8c006a57ec0', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How does the Ember Run Loop manage performance in an application?', N'Middle', N'The Run Loop batches internal operations like rendering, binding updates, and event handling into specific queues. By grouping these tasks, Ember minimizes browser reflows and prevents unnecessary execution cycles, significantly improving application performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'75714910-2e77-416d-93a2-e8c0950e2ebc', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'When would you use a Provider with a Custom Token?', N'Middle', N'Custom tokens are used when you need to inject non-class values like configuration objects, constants, or third-party libraries. By using a unique token, you can provide an implementation for an interface or an abstract class that cannot be instantiated directly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33bc1d04-8373-4c7e-89f3-e8c2a005eb6d', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does ''Consistent Hashing'' solve the problem of traditional modulo-based hashing in distributed caches?', N'Senior', N'Traditional modulo hashing results in massive data remapping whenever the number of nodes changes, causing cache misses. Consistent hashing maps both keys and nodes to a circular hash space, ensuring that adding or removing a node only requires remapping a small fraction of the keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ede7ca31-0918-4fc3-9567-e8c38d1306fc', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the primary goal of Fastify regarding performance?', N'Intern', N'The primary goal of Fastify is to minimize the overhead of processing requests to achieve high throughput and low latency. It achieves this by using a highly optimized internal routing mechanism and efficient JSON serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
