INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cc0d7a0-b2ea-420f-afe5-e8d5e9770afd', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How do you optimize Vite production builds for large-scale enterprise applications?', N'Senior', N'Optimization involves fine-tuning Rollup output options, implementing aggressive code splitting with manual chunks, and leveraging Vite''s asset compression plugins. Additionally, ensuring that the dependency graph is tree-shakeable is critical to keeping the final bundle size minimal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ee4e1e-f46f-407f-aca0-e8db5965450e', N'a2838158-7305-480a-b22b-4dc35776b400', N'How does ''Data Locality'' influence the design of distributed data processing systems?', N'Senior', N'Data locality involves moving the computation to where the data resides rather than moving large datasets over the network to the compute nodes. This minimizes network congestion and significantly improves processing performance in big data frameworks like Hadoop or Spark. Designing for locality requires a coordinated placement strategy between storage and execution layers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'840a3cc7-429f-4a79-b2f2-e8de6bfa97a9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of Entity Framework Core?', N'Fresher', N'Entity Framework Core is an Object-Relational Mapper that enables developers to work with a database using .NET objects. It eliminates the need for most of the data-access code that developers usually need to write by mapping database tables to class structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3470813-f727-4b93-bb69-e8e0d73055ce', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s development server leverage native ES modules to achieve near-instant startup times compared to traditional bundler-based dev servers?', N'Senior', N'Vite bypasses the time-consuming process of bundling the entire application during development by serving source code over native ESM. It performs on-demand compilation, transforming modules only when the browser requests them, which allows the server to start instantly regardless of project size. This approach shifts the workload from the build step to the browser, which efficiently handles dependency resolution and module execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c938958c-5bad-4d44-8185-e8e1ea62c50f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between ''sync'' and ''async'' queue drivers?', N'Middle', N'The ''sync'' driver executes jobs immediately within the same process as the request, which is useful for local debugging. The ''async'' (or persistent) drivers move jobs to a storage medium like Redis or SQS, allowing them to be processed by separate, independent worker processes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad5d0ab0-bbeb-4567-b546-e8e41459783b', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''context'' package in Go?', N'Middle', N'The context package is used to manage cancellation signals, deadlines, and request-scoped values across API boundaries and goroutines. It provides a standardized way to ensure that resources are cleaned up and long-running operations are terminated when they are no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7fa758b1-7522-4b89-afee-e8e52467eb7e', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the role of the Partitioning strategy?', N'Fresher', N'The partitioning strategy determines how data is distributed across the ring of nodes. It uses a hash function on the partition key to map data to a specific location in the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ee19bd9-71bf-4f8a-889f-e8e68bdd8b18', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is difference between ClassNotFoundException and NoClassDefFoundError?', N'Fresher', N'ClassNotFoundException and NoClassDefFoundError occur when a particular class is not found at runtime. However, they occur at different scenarios. ClassNotFoundException is an exception that occurs when you try to load a class at run time using Class.forName() or loadClass() methods and mentioned classes are not found in the classpath. NoClassDefFoundError is an error that occurs when a particular class is present at compile time, but was missing at run time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2710ab09-52b2-4a0c-a9d5-e8e6c061a46b', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Why should you use asynchronous programming in ASP.NET Core controllers?', N'Middle', N'Asynchronous programming prevents thread starvation by releasing the request thread back to the pool while waiting for I/O operations to complete. This significantly improves the application''s scalability and ability to handle high concurrency under load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e08fe9dd-564a-46ae-9852-e8e9e3a02d85', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js manage its reactive state internally compared to a framework like Vue, and what are the architectural implications for memory management in large-scale applications?', N'Senior', N'Alpine.js leverages the Proxy-based reactivity system from Vue''s core, which tracks property access during component initialization to establish dependencies. In large-scale applications, the architectural trade-off is that Alpine lacks a centralized state management pattern or virtual DOM, meaning reactivity is strictly localized to DOM nodes. Consequently, developers must be cautious about memory leaks when dynamically injecting large component trees, as Alpine must manually bind and unbind observers to individual DOM elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1cc7a86c-9ad0-4943-b98e-e8ea80d0fe2f', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the difference between a table and an item in DynamoDB?', N'Intern', N'A table is a collection of related data, similar to a table in a relational database. An item is a single record within that table, comparable to a row in a relational database.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b8e50af-2345-4c4a-850c-e8ec3ae79a7c', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'How does the ''async'' state machine transform an asynchronous method?', N'Senior', N'The compiler transforms the method into a struct-based state machine that maintains the local variables and control flow across await points. This allows the method to suspend execution and yield control to the caller without blocking the underlying thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd62439d2-50f6-41f7-b824-e8f062089ade', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you ensure you are not falling into ''confirmation bias'' when analyzing data?', N'Intern', N'I would actively look for evidence that contradicts my hypothesis rather than just seeking data that supports it. I also find it helpful to present my analysis to others and ask them to play ''devil''s advocate'' to identify potential blind spots.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1de830c-fc38-46b2-b6b9-e8f31a2e93a5', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is a goroutine in Go and how does it differ from a traditional operating system thread?', N'Fresher', N'A goroutine is a lightweight thread of execution managed by the Go runtime rather than the operating system. It consumes significantly less memory than a traditional thread because it starts with a small stack that grows and shrinks dynamically. This allows developers to run thousands or even millions of concurrent goroutines within a single application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dfe9ac4-87a8-4458-8a26-e8f347df3e59', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the JavaScript engine optimize hot functions using hidden classes and inline caching?', N'Senior', N'Engines create hidden classes representing the structure of objects to track property offsets. Inline caching stores the results of property lookups for specific hidden classes, allowing the engine to skip the full prototype chain traversal during subsequent accesses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7056d4c4-f9d1-4059-9bee-e8f61b773f53', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a tombstone in a NoSQL database?', N'Middle', N'A tombstone is a marker used to indicate that a specific piece of data has been deleted in a distributed system. Since data is replicated, a standard delete command might not reach every node, so the tombstone ensures that the deletion is eventually propagated to all replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d682fcd-39bf-4dd5-8d00-e8f6aee4ffd5', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the purpose of a closure in R?', N'Middle', N'A closure is a function that ''encloses'' the environment in which it was created, allowing it to remember and access variables from that scope even after the parent function has finished executing. This is useful for creating factory functions that generate specialized functions with persistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a7a151-fbfa-4215-8926-e8f743e81d26', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is an HTTP status code in the context of Web APIs?', N'Fresher', N'HTTP status codes are standard responses sent by the server to indicate the result of a request. For example, 200 indicates success, 404 indicates the resource was not found, and 500 indicates a server-side error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18ec180a-8e5a-4c88-a571-e8f8371f4c60', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the Response object in AdonisJS?', N'Intern', N'The Response object provides methods to send data back to the client. It allows you to set HTTP status codes, send JSON payloads, redirect users, or serve files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e4f0a6e-70e8-4c75-a811-e8fb99bf45f5', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you evaluate the trade-off between building a custom solution versus using a third-party library?', N'Fresher', N'A custom solution allows for complete control and perfectly tailored functionality but requires significant time to build and maintain. A third-party library saves development time and provides standard features, but you become dependent on the maintainer''s updates and security patches.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'702d6c8f-c31e-4d2f-933b-e8fce5fa68ae', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'If you are assigned a task in a technology stack you are unfamiliar with, what is your process for learning it?', N'Junior', N'I would start by reviewing the official documentation and existing examples within our codebase to understand the conventions. I would then perform small, isolated experiments to test my understanding before tackling the actual task, while keeping my lead informed of my progress.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ce98c5-0dc7-41f5-ac58-e8fd2a8ddbab', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'Why is it recommended to use Tailwind over writing plain CSS?', N'Junior', N'Tailwind enforces consistency by restricting your options to a predefined design system, preventing the ''CSS bloat'' that often occurs in large projects. It also keeps styles co-located with the structure, making it easier to understand which styles apply to a specific element.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6f1ce88-93ca-42d8-bf5e-e901aec48ea4', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you identify risks in a project plan?', N'Fresher', N'I look for areas where the requirements are vague, the technology is unfamiliar, or there are external dependencies. Identifying these potential points of failure early allows me to plan for contingencies or seek assistance before they become critical issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c776e9c5-afd4-4dc8-8cbc-e902b4376355', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What are the limitations of PHP''s native thread safety (ZTS) mode?', N'Senior', N'ZTS mode introduces global mutexes and thread-local storage to protect internal structures, which significantly slows down execution and reduces throughput. Furthermore, many third-party C extensions are not thread-safe, making ZTS unsuitable for most production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20a5c13e-2f8f-4638-9aee-e90516ba0ebb', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do you handle global state in an Ember application?', N'Middle', N'Global state should be managed within singleton Services. Because services are injected into any component or route that needs them, they provide a centralized, testable, and reactive way to share data across non-hierarchical parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9426f953-d5cd-4111-867f-e9092b474f91', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What does the ''typedef'' keyword do?', N'Junior', N'Typedef creates an alias for an existing data type rather than creating a new type. It is primarily used to make code more readable or to simplify complex declarations like function pointers or structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f362dda-0225-45b8-b564-e90bd3ee5899', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'Why is the Redis ''THP'' (Transparent Huge Pages) setting often disabled in production?', N'Senior', N'THP can cause significant latency spikes during the fork() system call used for RDB snapshots. When the kernel copies memory pages, it may have to handle huge pages, which increases the time the parent process is blocked, potentially causing severe performance degradation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a306b806-9593-47cd-9b13-e90ddbb74274', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is Quarkus and why is it called a Kubernetes Native Java framework?', N'Fresher', N'Quarkus is a full-stack, Kubernetes-native Java framework made for Java virtual machines and native compilation. It is called Kubernetes-native because it is optimized for low memory usage and fast startup times, which are critical requirements for containerized environments like Kubernetes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
