INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8ca034d6-e2eb-4d39-be59-e90f1bb1d10d', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is the purpose of res.send?', N'Fresher', N'The res.send method sends the HTTP response. The body parameter can be a Buffer object, a string, an object, or an array, and Express automatically sets the Content-Type header based on the data type provided.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bc2618c-bdf3-479e-ae94-e90f451ee139', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Is it possible to use Preact with a framework like Next.js?', N'Middle', N'Yes, it is possible to use Preact with frameworks like Next.js by aliasing React to Preact in the build configuration. This replaces the React library with Preact during the bundling process, allowing developers to benefit from Preact''s speed while keeping the Next.js developer experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81a562dd-7545-4f99-8f48-e9133a12f5cd', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the core philosophy of Astro?', N'Fresher', N'Astro is designed as an island-based web framework that focuses on content-driven websites. It aims to deliver high performance by sending little to no JavaScript to the client by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3ac7a8c-9a9f-49b9-ab60-e916cd8d3f37', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is a Sass function and how is it different from a mixin?', N'Junior', N'A function is designed to perform calculations or operations and return a single value, such as a color manipulation or a math result. A mixin, by contrast, is designed to output blocks of CSS declarations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'523004cb-0229-42dc-8a8b-e91f593bf80c', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'When would you prefer ''createDeferred'' over a standard ''createMemo''?', N'Senior', N'createDeferred is used to prioritize user-driven updates over less urgent background updates by introducing a delay in the reactivity chain. It is useful for high-frequency state changes where you want to prevent UI jank by yielding to the main thread.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8941df4e-9ad8-48f0-bd68-e92248dc8335', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik maintain SEO performance?', N'Junior', N'Qwik maintains high SEO performance by delivering fully rendered HTML from the server. Because the page is interactive immediately, search engine crawlers can index the content without waiting for heavy JavaScript execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5304a42a-ce1b-4835-af44-e924299b37a8', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony maintain security against CSRF attacks?', N'Fresher', N'Symfony''s Form component automatically generates a hidden token in every form submission. When the form is submitted, the framework verifies that the token matches the one expected for that session, preventing malicious third-party websites from submitting forms on behalf of an authenticated user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9cacccfb-4905-4ea0-81b9-e925ff21a30a', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'When you have multiple tasks of similar priority, how do you decide which one to tackle first?', N'Middle', N'I evaluate the potential business impact, technical dependency, and the risk of delaying each task. I prioritize tasks that unblock other team members or address critical system vulnerabilities, ensuring that my effort provides the most value to the project and the organization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b758081a-de6c-412f-af17-e92fc3f49cff', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of the ''Launch'' macro?', N'Fresher', N'The launch macro is the entry point of a Rocket application. It initializes the server, sets up the routing table, and begins listening for incoming HTTP requests on a specified address and port.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b43ff33b-bfd0-422e-94be-e9304a6ee73f', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle database migrations in a CI/CD pipeline?', N'Senior', N'Migrations should be treated as version-controlled schema definitions that are run automatically during the deployment process. To avoid downtime, migrations must be designed to be additive and backward-compatible, ensuring that the application remains functional even if a partial deployment occurs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd126395-d4ac-440b-abce-e9305a8eb0fc', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is a transaction log?', N'Fresher', N'A transaction log is a file that records all changes made to the database. It is used to ensure durability by allowing the system to recover committed data or undo incomplete transactions after a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
