INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5212e748-d967-4666-9303-e935a9708a65', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS maintain state persistence across component unmounting?', N'Middle', N'SolidJS state lives outside of the component lifecycle. If state is defined in a higher-level store or context, it remains accessible even if the child component is unmounted and later remounted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5d5a47a-9b7e-4431-a5e0-e9363eebb5f0', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the benefit of using Database Transactions during data updates.', N'Middle', N'Transactions ensure that a group of related database operations succeeds or fails as a single unit, preventing partial data updates. This is crucial for maintaining data consistency in scenarios like processing payments or transferring funds between accounts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb083b11-c13f-4e51-ab58-e939c10927e3', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'In Ember.js, what is a Component and why is it used?', N'Intern', N'A Component is a reusable UI element that encapsulates both its own template and the logic required to handle user interactions. Components are used to break complex user interfaces into smaller, manageable, and modular pieces that can be reused throughout the application to maintain consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'858ea3c9-254b-49d3-bd33-e93af68484e5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a memory leak and how does it manifest?', N'Fresher', N'A memory leak occurs when a program fails to release memory that is no longer needed, eventually causing the system to slow down or crash. It typically manifests as a gradual increase in memory usage over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45ab4db3-72ea-42c2-99c2-e93c8d8075a9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono support cross-platform compatibility without sacrificing performance?', N'Senior', N'Hono achieves performance by utilizing the built-in native APIs provided by the underlying runtime (like Web Crypto or standard Fetch) instead of wrapping them in heavy abstraction layers. This ensures that the framework remains as fast as the host environment allows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ca4eacb-7237-492c-8e37-e93f085ad733', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Compare document stores and key-value stores.', N'Middle', N'Key-value stores are simple, highly performant systems that retrieve data based on a unique key, making them ideal for caching. Document stores are more complex, allowing for semi-structured data storage and secondary indexing, which supports richer query patterns than simple key-value lookups.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbdffd92-4db7-427f-b321-e9401e9efb01', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'Discuss the trade-offs of using a Web Application Firewall (WAF) versus application-level input validation.', N'Senior', N'WAFs provide a perimeter defense against common attack patterns like SQLi and XSS without requiring code changes, but they can be bypassed by sophisticated obfuscation. Application-level validation is more robust and specific to the business logic, but it is harder to maintain and update consistently across a large codebase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8201a36-d07c-47ad-a4ec-e940757153de', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix generators?', N'Junior', N'Generators are command-line tools that scaffold boilerplate code for your application. They create files for controllers, views, schemas, and migrations, following the framework''s conventions to save time during the initial setup of new features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'839d2cba-fc65-44e3-bb78-e940d3b3339c', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'What is the primary benefit of Remix''s ''nested routing'' for application performance?', N'Senior', N'Nested routing allows the application to split the UI into segments that map directly to data dependencies. This architecture ensures that only the data for the changed segments is re-fetched during navigation, significantly reducing the payload size and improving perceived performance compared to monolithic data fetching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3f71443b-aefd-46b3-9bdb-e941ec77bdbe', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the role of the ''Replica-Read-Only'' configuration?', N'Senior', N'This setting ensures that replicas do not accept writes, which prevents data divergence between the master and replicas. It enforces a strict topology where all write traffic is directed to the master, simplifying consistency management at the cost of write scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
