INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'446c185b-ff52-45ed-a196-e947ac9f2a2e', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the benefit of Quarkus''s ''Vert.x'' integration?', N'Fresher', N'Vert.x is a reactive toolkit that provides the underlying engine for non-blocking I/O in Quarkus. It allows the framework to handle a massive number of simultaneous requests with very low resource consumption compared to traditional thread-per-request models.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb0c341c-167d-4921-825c-e94a4ac3039f', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If a senior developer gives you feedback that contradicts your approach, how do you handle it?', N'Junior', N'I ask questions to understand the reasoning behind their feedback so I can learn from their perspective. If I still have concerns, I respectfully share my thoughts, but I ultimately defer to their experience while documenting the decision for future reference.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6da5f94f-48eb-4a3a-861b-e94ac57d3804', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'Explain the importance of test isolation in Laravel testing.', N'Middle', N'Test isolation ensures that each test run is independent and does not rely on data left behind by previous tests. Laravel achieves this by using database transactions that roll back automatically, ensuring a clean state for every test case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab24b0eb-56ac-490b-b388-e94c85240e22', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How would you estimate the number of books in a library without counting them one by one?', N'Fresher', N'I would count the number of books on one average shelf and the number of shelves in a single bookcase. Then, I would multiply these numbers by the total number of bookcases in the library to get a reliable estimate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b5b134c-e12d-4fff-bf39-e94ca2014fdc', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the role of the ''ngOnChanges'' lifecycle hook and why should it be used sparingly?', N'Senior', N'ngOnChanges triggers every time an input property changes, providing a mechanism to react to data updates. Frequent logic inside this hook can cause performance degradation; it is generally better to use setters or RxJS streams for more efficient and reactive data handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1753231a-f0b1-40ab-8221-e94d489585c4', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'What is your process for diagnosing a performance bottleneck in a microservices architecture that involves multiple asynchronous message queues?', N'Senior', N'I start by establishing a distributed tracing baseline to identify latency spikes across service boundaries. I then inspect queue depths, consumer processing rates, and resource utilization on individual nodes to isolate whether the issue is caused by backpressure, resource contention, or inefficient serialization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6af096fc-ecc4-4ee6-a8e5-e94eaf8b33f7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'Why would you use a Service instead of a Component for global data?', N'Junior', N'A service is a singleton that persists as long as the application is running, making it ideal for data that needs to be accessed by many components. Components are transient and recreated often, making them unsuitable for holding global application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9451863e-1f8a-490b-9fbe-e94f562513e8', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When designing a public-facing API, what is the trade-off between versioning and backward compatibility?', N'Junior', N'Maintaining backward compatibility prevents breaking existing client integrations, which is crucial for user trust. However, it often leads to ''API bloat'' where deprecated features must be supported indefinitely, making the system harder to clean up and evolve over time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f390aa92-318b-472c-9dde-e9503b00ae5c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of the Write-Ahead Logging (WAL) protocol?', N'Middle', N'WAL ensures data integrity by requiring that all modifications be recorded in a log on stable storage before the changes are applied to the actual data files. This allows the database to recover to a consistent state in the event of a crash or power failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb3da9e6-e3b4-4435-9dff-e950e86d08ff', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'Why is ''Deployment Independence'' a key goal of microservices?', N'Middle', N'Deployment independence allows teams to update, scale, and roll back individual services without requiring a full system deployment. This significantly increases development velocity and reduces the blast radius of potential bugs or production incidents.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'380ffc2e-f8bf-4909-bd8c-e95102a3a17d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What are the risks of using Echo''s context as a general-purpose dependency injection container?', N'Senior', N'Using the context as a container hides dependencies and makes code harder to test, as handlers become reliant on the context''s state. It is better to use explicit constructor-based dependency injection for services, keeping the context strictly for request-scoped metadata.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd3e17aa-a2aa-4142-b5e7-e952ca0f2fe3', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you serve your pages for feature-constrained browsers? What techniques do you use?', N'Fresher', N'* Graceful degradation: The practice of building an application for modern browsers while ensuring it remains functional in older browsers. * Progressive enhancement: The practice of building an application for a base level of user experience, but adding functional enhancements when a browser supports it. * caniuse: to check for feature support. * Autoprefixer: for automatic vendor prefix insertion. * Feature detection: using Modernizr. * CSS Feature queries: using @support', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ba061fc3-ff4f-4ae0-81c5-e954f868fd2a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'Why might a web page load slowly for a user even if the server is performing well?', N'Fresher', N'The issue could be caused by large, unoptimized media files that take time to download over the user''s network connection. Additionally, excessive client-side scripts or third-party tracking tools can block the browser from rendering the page quickly. The user''s own internet latency or geographical distance from the content delivery network also plays a significant role.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd32c5b02-bcd4-4bce-b4c5-e956d1f68966', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is a stream in C++?', N'Intern', N'A stream is an abstraction that represents a flow of data, such as input from a keyboard or output to a file or console. C++ uses the standard library streams to perform input and output operations in a uniform way.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e049908f-b272-4a44-b54e-e9577398f4ef', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the benefit of Cassandra''s Peer-to-Peer architecture?', N'Intern', N'The peer-to-peer architecture ensures there is no single point of failure in the system. Because all nodes are equal, any node can handle requests, which makes the system highly resilient to hardware failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c357a939-1c7e-470e-8a02-e958af849dfe', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the purpose of ''use client''?', N'Intern', N'The ''use client'' directive is placed at the top of a file to indicate that a component should be rendered on the client side. This is necessary for components that use React hooks or browser-specific APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dcbdcb50-e3c6-443b-aea8-e959032b9c0b', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'Explain the significance of the ''onSend'' hook in Fastify''s request lifecycle for performance optimization.', N'Senior', N'The ''onSend'' hook is the final opportunity to intercept the payload before it is sent to the client. It is ideal for implementing late-stage optimizations like on-the-fly compression, payload transformation, or injecting headers that depend on the final response body.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ce6f22f-7cf1-4c52-bbcf-e95a018d4f7a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What is the role of the React Server Components (RSC) architecture in Next.js, and how does it impact the client-side bundle size?', N'Senior', N'RSC allows components to execute entirely on the server, sending only the resulting UI structure to the client instead of JavaScript code. This significantly reduces the client-side bundle size because dependencies used exclusively on the server are never sent to or executed by the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a084869-37d6-4b00-9eb3-e95ab976fbc8', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB Time to Live (TTL) function without impacting throughput?', N'Senior', N'TTL allows items to expire automatically based on a timestamp attribute, with the background deletion process managed by DynamoDB at no extra cost. This process occurs at the storage layer without consuming provisioned throughput, making it highly efficient for managing transient data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97581aa2-28d3-4825-9334-e95bf7899131', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the role of the ''Master-Eligible'' node, and how is it different from a ''Dedicated Master'' node?', N'Senior', N'A master-eligible node can participate in elections and become the cluster master. A dedicated master node is configured to have no data or ingest roles, isolating it from high memory and I/O pressure, which ensures that the cluster state remains stable and avoids election delays.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f37685b-f734-4263-a565-e95de767cb8d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is CORS and why is it important?', N'Intern', N'CORS stands for Cross-Origin Resource Sharing, a security feature implemented by browsers to prevent malicious scripts on one website from accessing data from another. FastAPI provides built-in tools to configure which origins are permitted to interact with your API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2f5f51a-d7a6-44fc-8849-e9616e2b5890', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the purpose of the ''Handler'' in Axum?', N'Fresher', N'A handler is an asynchronous function that processes an incoming request and returns a response. It is the core logic unit of the application where business requirements are implemented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92c14989-c74a-4464-8744-e96255c242cc', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are inline conditional expressions?', N'Intern', N'You can use either _if statements_ or _ternary expressions_ which are available in JS(and JSX in React) to conditionally execute or render expressions. Apart from these approaches, you can also embed any expressions in JSX by wrapping them in curly braces and then followed by JS logical operator &&. It is helpful to render elements conditionally within a single line and commonly used for concise logic, especially in JSX rendering.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'078a5417-06c9-4a56-b506-e968ee3f7b7f', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you handle request validation without polluting business logic?', N'Senior', N'The idiomatic way to handle validation in Axum is to implement custom extractors or use the ''validator'' crate inside a custom wrapper type. By performing validation within the extractor before the handler is called, you guarantee that only valid data reaches your business logic, keeping it clean and focused.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8963192-a0b1-4e39-bdcc-e96bf371eea6', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the trade-offs between using a Choreography-based vs. Orchestration-based Saga pattern?', N'Senior', N'Choreography is decentralized and removes a single point of failure but becomes difficult to track as complexity grows. Orchestration centralizes the logic in a single coordinator, making it easier to manage complex workflows at the cost of coupling the orchestrator to multiple services.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'303aa442-9d25-4e04-9bab-e96d39389196', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the browser handle invalid CSS rules, and why is this behavior useful for progressive enhancement?', N'Senior', N'The CSS specification mandates that browsers ignore invalid or unknown declarations while continuing to parse the rest of the stylesheet. This allows developers to use modern features while providing fallback values for older browsers, effectively enabling seamless progressive enhancement without requiring complex feature detection logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f32caa0-0a38-4a68-803e-e96e3ed6d1e6', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the benefits of using Redis for session management?', N'Intern', N'Redis is excellent for session management because of its speed and expiration features. It allows web applications to store user session data in memory and automatically clean up expired sessions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3a29910-df03-4f62-b465-e973d2080fe9', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security implications of implementing a Service Mesh in a microservices environment?', N'Senior', N'A service mesh enhances security by centralizing mTLS, traffic encryption, and fine-grained authorization policies at the infrastructure layer, decoupling them from application code. However, it increases system complexity and creates a centralized point of failure or compromise within the control plane, requiring strict access control for mesh configurations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'42fdb3a1-049b-4bc7-ad97-e973fc985168', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the difference between a mixin and a function?', N'Intern', N'A mixin is intended to output chunks of CSS code that contain declarations like properties and values. A function is intended to return a single value, such as a calculated color or a specific pixel measurement, to be used elsewhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1db67444-1829-4284-b9cd-e97830099f33', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is UI/UX?', N'Intern', N'1) UI or User Interface: is how a product or website is laid out and how you interact with it: Where the buttons are, how big the fonts are, and how menus are organized are all elements of UI. 2) UX or User Experience: is how you feel about using a product or a website. So, your love for the way the new Apple Watch looks or your excitement that there''s finally a tablet-sized iPhone to watch those Corgi videos you’re obsessed with are reflections of UX. So the new look of the Facebook news feed involves a change to UI, and the way you navigate that new page is the UX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f7f1939-73fa-422a-9415-e9783741d59e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do secondary indexes work in a distributed system where data is sharded?', N'Senior', N'Secondary indexes in a sharded system are either local to the shard, requiring a broadcast query across all nodes to find data, or global, which are maintained on a separate index node. Global indexes improve query performance for non-shard key lookups but introduce significant overhead for write operations due to distributed consistency requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4aa4fa3-ed93-41e8-b14b-e9786dc40561', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the primary purpose of using TypeScript instead of plain JavaScript for frontend development?', N'Fresher', N'TypeScript is a superset of JavaScript that introduces static type checking to the development process. It helps developers catch potential errors during compilation rather than at runtime, improving code reliability and maintainability. Additionally, it provides better IDE support through features like autocompletion and easier refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'71f70a88-60fa-4d06-b07e-e97a4f4db84a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the purpose of an aggregate function?', N'Junior', N'Aggregate functions perform a calculation on a set of values and return a single scalar value. Common examples include COUNT, SUM, AVG, MIN, and MAX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4fd48aa-43c4-4760-9aaf-e97a669a2ef4', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is ''Database Denormalization'' and when is it a valid strategy?', N'Middle', N'Denormalization involves combining tables or adding redundant columns to simplify queries and reduce join operations. It is a valid strategy in read-heavy applications where the performance cost of joins outweighs the risks of data anomalies, provided the application handles the complexity of maintaining data consistency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4726282-86f3-498f-88f0-e97a8f900921', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of the ''View'' layer in AdonisJS for server-side rendering?', N'Middle', N'The View layer provides a robust templating engine that supports components, layouts, and helpers, simplifying the generation of HTML on the server. It allows for efficient data binding and keeps the UI logic separate from the business logic, which is easier to maintain than client-side hydration for simpler apps.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30d1188e-78c8-4fd1-9ec7-e97fc89fd58e', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What happens if output an else statement after after block?', N'Junior', N'The code in the else block is executed after the for loop completes, unless a break is encountered in the for loop execution. in which case the else block is not executed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e91a131-65dd-4651-858a-e982579221e0', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the difference between GenServer and Task in Elixir/Phoenix?', N'Middle', N'GenServer is a generic process used for maintaining long-lived state and handling asynchronous calls or requests. A Task is a specialized process designed for executing a single computation or asynchronous operation and returning a result, making it better suited for short-lived background tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4043940e-8d13-450f-b624-e9845522c376', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the difference between a static site and a server-side rendered site in Nuxt?', N'Intern', N'A static site is pre-rendered at build time, resulting in files that do not require a server to run. A server-side rendered site generates content dynamically on the server for every request, which is necessary for data that changes frequently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e0896a8-f050-4cc8-b2f6-e98594188758', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''request cache'' differ from the ''node query cache''?', N'Senior', N'The request cache stores the results of aggregation queries and search hits for requests with size zero, useful for dashboards. The node query cache stores the bitsets for filter contexts, which are reused across different queries to speed up the filtering process by avoiding repetitive bitwise operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2884978-cd50-4bc3-b8fa-e987b8031f2d', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix leverage CDNs for performance?', N'Senior', N'By supporting standard HTTP caching headers via the loader and headers functions, Remix allows assets and even dynamic content to be cached at the edge. This significantly reduces server load and improves latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c42ff93-96c4-4278-9c00-e988124a83cd', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Why do you need Obfuscation', N'Fresher', N'Below are the few reasons for Obfuscation, 1. The Code size will be reduced. So data transfers between server and client will be fast. 2. It hides the business logic from outside world and protects the code from others 3. Reverse engineering is highly difficult 4. The download time will be reduced', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'15efb3ca-86ff-43e3-b11c-e98905553c30', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you apply middleware in an Axum application?', N'Junior', N'Middleware in Axum is applied using the layer method on a router. Because Axum is built on Tower, any Tower-compatible layer can be added to the request processing pipeline to handle tasks like logging or authentication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68d99479-a87c-4aab-8160-e98a7ad69a1d', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a query DSL in Elasticsearch?', N'Intern', N'Query DSL is a JSON-based language used to define complex queries for searching and filtering data in Elasticsearch. It provides a flexible way to construct queries for various search requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48b8d377-8929-48aa-b9b4-e98ab6bef993', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does the CAP theorem influence the choice of a database system?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In the event of a network partition, designers must choose between returning the most recent write (Consistency) or remaining responsive with potentially stale data (Availability).', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'893517a4-0c10-4cea-9833-e98bd3b42ea9', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does distributed tracing help identify performance bottlenecks?', N'Middle', N'Distributed tracing attaches a unique ID to a request as it travels across various microservices. By recording the time spent in each service, engineers can visualize the entire request lifecycle and pinpoint exactly which component is introducing latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86bb15a4-e1aa-4806-8df4-e98e4fe5b005', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What are the advantages of using MongoDB''s Aggregation Framework compared to MapReduce?', N'Middle', N'The Aggregation Framework is faster, easier to maintain, and more optimized for most analytical tasks because it runs natively within the database engine using pipeline stages. MapReduce is generally slower, more complex to write, and is largely deprecated in favor of the pipeline approach.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d3abdc4-3b9d-4c33-8385-e992d7c35d4a', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What happens if a request fails a guard check in Rocket?', N'Fresher', N'If a request guard fails, Rocket automatically stops the execution of the route handler for that request. It will return a 404 or 422 error response to the client, effectively preventing the handler from processing invalid input.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
