INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'655f6767-47f2-400a-a26a-e9972cc229b3', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Why is ''String'' immutable in C# and what is the alternative for frequent modifications?', N'Middle', N'Strings are immutable to ensure thread safety and to allow for efficient memory management through string interning. For scenarios requiring frequent modifications, the StringBuilder class is preferred as it maintains a mutable buffer to avoid creating new string objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f79aed8f-215b-4b6e-ac60-e9996131f7e0', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How node.js prevents blocking code?', N'Fresher', N'Blocking vs Non-blocking: Blocking is when the execution of additional JavaScript in the Node.js process must wait until a non-JavaScript operation completes. This happens because the event loop is unable to continue running JavaScript while a blocking operation is occurring. Synchronous methods in the Node.js standard library that use libuv are the most commonly used blocking operations. Native modules may also have blocking methods. Blocking methods execute synchronously and non-blocking methods execute asynchronously. Example:', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
