INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'46ca420b-f5e2-49f0-92b2-e9a097853337', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the role of the ''Root Reducer'' in a large-scale Redux application?', N'Senior', N'The root reducer acts as the composition point for all slice reducers in the application. It uses a pattern similar to ''combineReducers'' to aggregate individual state slices into the global state object, ensuring that every action is processed by the relevant parts of the state tree.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'855a8207-b820-4cf6-9ed1-e9a346cc13e7', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the memory model implication of using channels versus shared memory with mutexes?', N'Senior', N'Channels are based on the principle of communicating by sharing memory, effectively acting as synchronization primitives that handle memory visibility implicitly. Using mutexes requires the programmer to explicitly manage memory barriers and critical sections to avoid data races. While channels are generally safer and follow CSP theory, mutexes can be more performant for high-contention scenarios where fine-grained locking is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9c2c39c-852c-499a-ae80-e9a77690d417', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is Java String Pool?', N'Intern', N'String Pool in java is a pool of Strings stored in Java Heap Memory. String pool helps in saving a lot of space for Java Runtime although it takes more time to create the String. When we use double quotes to create a String, it first looks for String with the same value in the String pool, if found it just returns the reference else it creates a new String in the pool and then returns the reference. However using new operator, we force String class to create a new String object in heap space.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33e34f66-22e7-429d-ad76-e9a94b66a258', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''StackMapTable'' attribute in the Java bytecode format?', N'Senior', N'The StackMapTable was introduced to facilitate type checking during the class verification phase without requiring the JVM to perform complex type inference. It provides information about the types of stack variables and local variables at specific branch targets, significantly speeding up the verification process for modern JVMs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c5a12a1-6f59-4484-a616-e9ab850fa7a0', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the benefit of the Astro Island API in terms of testing?', N'Middle', N'Because islands are isolated components, unit testing them is straightforward as they rely less on the overall page context. You can test the interactivity of an island independently of the surrounding static content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'488d4416-79c0-41d2-bf44-e9abe2c090bc', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What is the purpose of a Middleware in Actix and how does it differ from a Request Handler?', N'Middle', N'Middleware in Actix wraps the request processing pipeline, allowing you to execute code before or after the main handler, such as logging, authentication, or error handling. While handlers process the core business logic for a specific route, middleware acts as a cross-cutting concern applied to groups of routes or the entire application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1689f98-f007-458c-83e7-e9abe465f250', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of the array slice method', N'Intern', N'The slice() method in JavaScript is used to extract a section of an array, returning a new array containing the selected elements. It does not modify the original array. The method takes two arguments: - start: The index at which extraction begins (inclusive). - end (optional): The index before which to end extraction (exclusive). If omitted, extraction continues to the end of the array. You can also use negative indices, which count from the end of the array. Examples: Note: The slice() method does not mutate (change) the original array; instead, it returns a new array containing the extracted elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c774901a-c444-4303-b4ec-e9b801e82ac3', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js maintain reactivity?', N'Fresher', N'Alpine.js uses a proxy-based reactivity system similar to Vue.js. When you change a piece of data within your x-data object, Alpine automatically tracks that change and updates any part of the DOM that relies on that specific piece of data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4d68c0b-065f-4ee0-93d0-e9b89b968f58', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What happens if a DynamoDB partition exceeds its physical size limit?', N'Middle', N'DynamoDB automatically splits partitions when they exceed their storage capacity limits or when the throughput requirements demand more horizontal scaling. This process is handled seamlessly by the service, ensuring that the table remains available and performant.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e64216d-d914-4415-9ccd-e9b9871aad06', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are SvelteKit ''form actions''?', N'Intern', N'Form actions allow you to handle form submissions on the server without needing to write a separate API endpoint. They provide a simple way to process data, perform validation, and return responses or errors directly to the component that submitted the form.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acac1f8b-1b25-4a4a-a9cd-e9c732cbc7ba', N'4c000000-0000-0000-0000-000000000005', N'How does ''Database Sharding'' impact cross-shard queries?', N'Senior', N'Sharding splits data across multiple physical databases, which makes queries involving joins or aggregations across shards extremely expensive and slow. To mitigate this, architects often denormalize data, use global secondary indexes, or shift complex aggregation tasks to an analytical read-model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97f882e6-124c-4488-a4e2-e9c7e3749e10', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''init'' function in Go?', N'Fresher', N'The init function is an optional function that runs automatically when a package is initialized. It is typically used to set up global state, register drivers, or perform other one-time setup tasks before the main function starts.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac8b4644-3fed-4ba1-a419-e9c8e403d52f', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of the ''providers'' array in a module?', N'Intern', N'The providers array registers services or classes that should be available for injection within the scope of that module. Once registered, these classes can be injected into any controller or service within the same module.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'690877a6-0af6-48f9-b42f-e9c91807536b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach a task that seems overwhelming?', N'Junior', N'I break the task down into smaller, manageable sub-tasks. By tackling one piece at a time, I gain momentum and can more clearly see the progress I am making toward the final goal.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'52640d68-3815-44a4-a79a-e9ca2fba11b2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage environment-specific variables like API keys across different runtimes?', N'Middle', N'Hono uses a unified binding mechanism where environment variables are injected through the Context object. This abstracts the underlying provider''s implementation, allowing the same code to access secrets in Cloudflare Workers, Deno Deploy, or local development environments seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd30917dc-d3b2-4247-9f81-e9cb8fc95fd8', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you optimize Echo for high-throughput JSON processing?', N'Senior', N'For extreme performance, you can replace the default standard library JSON encoder with faster alternatives like segmentio/encoding/json or easyjson. This reduces CPU usage during serialization, which is often a bottleneck in JSON-heavy RESTful APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0543c1a-82c4-4301-9763-e9cfa7856f61', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How do database migrations help in a team development environment?', N'Middle', N'Migrations act as version control for your database schema, allowing teams to share changes without manually executing SQL scripts. They ensure that all environments remain synchronized and provide a reliable way to roll back changes if a deployment fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'719a3509-4c79-435a-afb4-e9cfb2cc1e34', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is a ''fine-grained'' update in SolidJS?', N'Fresher', N'A fine-grained update refers to the ability of the framework to update a specific piece of text or an attribute in the DOM without re-running the surrounding component function. This is achieved by creating granular subscriptions to specific state changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9026cb0-334a-4d64-9193-e9cfb633699c', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'Why is it recommended to use ''readonly'' arrays?', N'Middle', N'Readonly arrays prevent unintended side effects by ensuring the array contents cannot be modified after creation. This is critical in functional programming patterns where immutability is required to prevent bugs related to shared state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f052b8fa-0ea2-4e60-be11-e9d090b0e24b', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is a ''mutating'' method in a struct?', N'Junior', N'Because structs are value types, their properties cannot be modified by default within methods. The ''mutating'' keyword allows a method to modify the properties of the struct and change the instance itself.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2b7a8414-ffb9-465e-a5f8-e9d1ebc07963', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro differ from frameworks like React or Vue?', N'Junior', N'While React and Vue are primarily single-page application frameworks that render on the client, Astro is a multi-page application framework. It renders components into static HTML on the server, resulting in faster initial page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1e17e50-d864-4300-a90f-e9d2d963aa6a', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Can you use CSS Modules in Next.js?', N'Fresher', N'Yes, Next.js has built-in support for CSS Modules. They allow you to write CSS with local scope by automatically generating unique class names, which prevents style collisions between different components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54587524-eb0f-47cf-bc05-e9dc7c5185a8', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is partial hydration?', N'Junior', N'Partial hydration is the process of only sending and executing JavaScript for specific components on a page. This significantly improves performance because the rest of the page remains as plain, static HTML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'180977f6-7c2d-465f-a2b9-e9dcb969dced', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is a Migration in Doctrine?', N'Junior', N'A migration is a version-controlled script that records changes to your database schema. It allows developers to safely update the database structure in different environments without manually modifying tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5df32da5-2936-41cf-8829-e9dd91c61a74', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How can you implement optimistic locking in DynamoDB?', N'Senior', N'Optimistic locking is implemented using a version number or timestamp attribute within an item. During an update, the application includes a condition expression to check if the version matches the expected value, preventing accidental overwrites in concurrent update scenarios.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cda41900-c1fc-4218-ad6f-e9de2f6a6fbb', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin support testing without starting a real network server?', N'Middle', N'Gin allows you to perform unit tests by using the net/http/httptest package to create a mock response recorder. You can then pass a constructed request directly to the Gin router''s ServeHTTP method, which bypasses the network stack and speeds up test execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2904314-4b19-4215-900d-e9dec4425354', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the role of the ''Service Worker'' in Qwik?', N'Middle', N'In some Qwik configurations, a service worker can be used to prefetch code chunks in the background. This further enhances responsiveness by anticipating user actions and ensuring the necessary JS is already cached when the user decides to interact.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd08fe59c-37e8-4f5c-b378-e9e70d89e8ab', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What are the limitations of the Two-Phase Commit (2PC) protocol in large-scale systems?', N'Senior', N'2PC is a blocking protocol, meaning if the coordinator fails during the commit phase, participants remain locked, which significantly impacts availability. Furthermore, it introduces high latency due to multiple round-trip communications, making it unsuitable for geographically distributed systems with high traffic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3bc71bf-d251-4caf-a7fc-e9f044f1de79', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are render props in React and what are they for?', N'Intern', N'Render props in React are a technique for sharing code between components using a prop whose value is a function. The component calls that function with some internal state or data, and the function returns the React element to render. The prop does not have to be named render — passing a function as children is the more common modern form. Render props were popular before hooks. As of modern React, custom hooks have largely replaced them for sharing stateful logic, though render props are still useful for components that own a piece of UI structure (e.g. virtualized lists, headless component libraries). ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c4fe490b-415c-4c48-8d3a-e9f2866a154c', N'075b8862-431c-4678-9767-f55359758a4a', N'Why should you avoid using the index as a key in a v-for loop?', N'Middle', N'Using the index as a key is problematic when the list is filtered, sorted, or items are added or removed, as Vue may incorrectly reuse existing DOM elements. This can lead to bugs where component state, such as form inputs or local data, is incorrectly associated with the wrong item.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'99b1b480-c402-45b9-8cf0-e9f2c44330fb', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Why is ''Sharding'' essential for scaling NoSQL databases, and what are the risks of choosing an improper shard key?', N'Senior', N'Sharding distributes data across multiple nodes to horizontally scale storage and throughput, preventing any single node from becoming a bottleneck. Choosing an improper shard key can lead to ''hot partitions,'' where a subset of nodes handles disproportionately high traffic, or ''cross-shard queries,'' which significantly increase latency and resource consumption.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d5f2607-78b6-4a25-8c85-e9f2e7203f60', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between ''raise'' and ''throw'' in Ruby?', N'Middle', N'Raise is used to trigger an exception that halts the program unless caught by a rescue block, intended for handling error conditions. Throw is part of a flow-control mechanism used with ''catch'' to exit deeply nested loops or blocks, and it is not intended for standard error handling.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
