INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6be70488-5922-483d-9117-e9f4f4d5d9be', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the Rails routing system?', N'Intern', N'The routing system serves as the entrance point for web requests, mapping incoming URLs to specific controller actions. It interprets the HTTP request method and path, ensuring that the application knows exactly which piece of logic should execute to handle that particular request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1af81e4-6178-480d-bdd1-e9f5657f2887', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the difference between a Policy and a Gate?', N'Junior', N'Gates are closures that determine if a user is authorized to perform a given action, usually defined in the AuthServiceProvider. Policies are classes that organize authorization logic around a particular model or resource, making them cleaner for larger applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'214cb9ec-fee6-4041-b606-e9f592f12e94', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the purpose of the EXPLAIN command in PostgreSQL?', N'Junior', N'The EXPLAIN command displays the execution plan that the PostgreSQL query planner generates for a specific query. It helps developers understand how the database intends to retrieve the requested data, such as whether it will perform a sequential scan or use an index, which is useful for performance troubleshooting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47eca023-7f39-4ffd-843f-e9f59d19a09b', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the ACID properties in database management?', N'Intern', N'ACID stands for Atomicity, Consistency, Isolation, and Durability. These properties ensure that database transactions are processed reliably and maintain data integrity even in the event of errors or system failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
