INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3bae93a2-f9d0-41a8-bf82-e9fc58d62e92', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the main difference between Nuxt and Vue?', N'Junior', N'Vue is a framework for building user interfaces, while Nuxt is a meta-framework built on top of Vue. Nuxt provides additional features like file-based routing, server-side rendering, and auto-imports that are not natively part of core Vue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
