INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f775e408-7da5-4c40-b248-ea02b9f45310', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How does Scala handle concurrency compared to traditional Java?', N'Middle', N'Scala encourages the use of higher-level abstractions like Futures, Promises, and the Actor model rather than raw threads and locks. This approach minimizes state sharing and promotes message-passing, which makes concurrent systems more robust and easier to manage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7e80704-64f3-4c02-a075-ea035f462307', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What is the advantage of using Lit over vanilla Web Components?', N'Fresher', N'While vanilla Web Components provide the basic browser standard, Lit adds essential features like reactive data binding, an efficient rendering system, and a simpler API for managing state, which reduces boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0d64191a-01cc-4d68-9c36-ea05284afa1a', N'55404b9c-91b6-4b62-9dc7-63248e8ea1df', N'What is the ''thundering herd'' problem in cache management?', N'Middle', N'The thundering herd problem occurs when a popular cache key expires, causing a massive influx of concurrent requests to hit the underlying database simultaneously. This can overwhelm the database and lead to system failure, which is often mitigated using distributed locks or cache pre-warming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5dc3a5ee-e33b-4bc0-bdbe-ea092164d259', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'Why should you use an ''Actuator'' in a production Spring Boot application?', N'Middle', N'Spring Boot Actuator provides built-in endpoints to monitor and interact with the application, such as health checks, metrics, and thread dumps. It is essential for observability in production environments, allowing automated systems or administrators to verify system status without needing to manually debug the application state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6d810b7-0d83-4a8e-9c28-ea11c1564d66', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus implement security differently than traditional Java EE?', N'Senior', N'Quarkus uses a unified security model that integrates seamlessly with OIDC, JWT, and standard identity providers. It shifts security policy enforcement closer to the transport layer and utilizes build-time optimizations to minimize the performance impact of authentication and authorization checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b4d92bd-ff1a-4b4e-9b38-ea121b52bcbd', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the advantage of not using a virtual DOM?', N'Intern', N'The main advantage is performance and reduced code overhead. By avoiding the virtual DOM, Svelte skips the expensive process of comparing two object trees and directly performs the necessary DOM updates, leading to faster execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'baf6dc79-7e44-432e-bfc8-ea16de938f2e', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Explain the significance of the ''invalidate'' and ''invalidateAll'' functions in SvelteKit.', N'Senior', N'These functions force the re-execution of ''load'' functions associated with current routes, enabling reactive data updates when the underlying state changes. This is critical for keeping the UI in sync with external data changes, such as user profile updates or database mutations, without manual state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53bd3bd3-9a24-4bd8-a696-ea171bf50545', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Why is it important to avoid blocking calls in a fiber-based system?', N'Middle', N'Blocking calls pause the underlying OS thread, which prevents the scheduler from running other fibers assigned to that thread. This negates the concurrency benefits of the architecture and can lead to severe performance degradation if many fibers block simultaneously.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'005df266-172d-4342-82ca-ea1742152fb9', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Explain the difference between ''Hooks'' and ''Events'' in the context of Lucid models.', N'Middle', N'Hooks are synchronous or asynchronous lifecycle methods tied directly to model operations like saving or deleting, intended for data manipulation. Events are more suited for broadcasting that a model operation has occurred, allowing other parts of the system to react independently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03b1d4bc-2986-461d-a0f0-ea192c35be1f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain why SolidJS can be faster than frameworks that rely on VDOM in memory-constrained environments.', N'Senior', N'By avoiding the creation of virtual DOM objects and the subsequent diffing process, SolidJS significantly reduces memory pressure and CPU overhead. The framework creates real DOM nodes immediately and updates them directly, leading to a much smaller memory footprint and faster initial paint times.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7ac68b9-96a5-481f-b2d2-ea19e68d9c2f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s ''when'' expression improve upon Java''s ''switch'' statement?', N'Middle', N'''when'' is more powerful because it can match against arbitrary expressions, ranges, and types, not just constants. It also acts as an expression, returning a value, and requires exhaustive handling, which helps prevent bugs by forcing developers to account for all possible cases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9052e6c9-8fe3-4150-88a0-ea1ce990ab2a', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the risks of ''Cascading Deletes'' in a large-scale database?', N'Senior', N'Cascading deletes can trigger massive, long-running transactions that lock large swaths of the database, leading to performance degradation or blocking. In distributed systems, these operations can be nearly impossible to manage consistently, often leading developers to prefer soft deletes or application-level cleanup tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e77905e-4a8a-4c87-ae3e-ea1de11bd7a3', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'You see a failing test in the continuous integration pipeline that you didn''t write. Should you ignore it?', N'Junior', N'No, I should investigate the failure to determine if it is a flaky test or if my recent changes inadvertently broke existing functionality. If it is a legitimate failure caused by my work, I must fix it before merging; if it is unrelated, I should report it to the owner.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef98b998-9850-4c85-b1fd-ea1fc9351bf2', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does the ''preflight'' feature in Tailwind CSS affect cross-browser consistency?', N'Senior', N'Preflight is an opinionated set of base styles that normalizes browser defaults, such as removing margins on headings and ensuring consistent rendering of buttons and inputs. It acts as a baseline that minimizes the differences between browsers, allowing developers to start from a clean, predictable slate without worrying about legacy browser inconsistencies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7a676e0-4081-4e64-9315-ea21ad2f5d72', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What is the purpose of connection pooling?', N'Middle', N'Connection pooling maintains a cache of database connections that can be reused for future requests. This avoids the high overhead of establishing a new connection for every single query, which is crucial for maintaining performance under high concurrency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7cf40670-d6aa-4fa8-b202-ea232d02ce6f', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the purpose of the ''Before Request'' hook, and how can it be used for cross-cutting concerns?', N'Senior', N'The ''before_request'' hook executes code before processing the main route handler, making it perfect for global tasks like authentication checks, request logging, or setting up database sessions. This centralizes common logic, ensuring consistency across all endpoints without repeating code inside every view function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f2077d2-7b2d-496b-affe-ea233e2147dd', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit handle the transition between server-side rendering and client-side navigation?', N'Senior', N'After the initial SSR request, SvelteKit initializes a client-side router that intercepts link clicks. This allows the application to perform subsequent navigations by fetching only the necessary data and updating the DOM, effectively transforming the application into a single-page app while maintaining the benefits of SSR.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd165094a-2d8b-41e3-a845-ea241b517459', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'Why would an architect choose Rocket over a lower-level framework like Hyper?', N'Senior', N'Rocket provides a higher-level abstraction that handles routing, request validation, and lifecycle management, which increases developer productivity and reduces boilerplate. Hyper is a lower-level library that offers more control but requires significant manual implementation for common web features, making it better for specialized, performance-critical proxies rather than typical API development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d209561-c94f-4273-8e5b-ea243057c7c7', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle schema evolution?', N'Senior', N'DynamoDB is schema-less, meaning each item can have different attributes regardless of the table structure. This allows developers to add or remove attributes dynamically without performing expensive DDL operations, facilitating agile development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9098263-8a1c-41f2-be9a-ea25931f6426', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is a join in a relational database?', N'Intern', N'A join is a method used to combine rows from two or more tables based on a related column between them. It allows users to retrieve data that is spread across different tables into a single result set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
