INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a9a15eb-15fd-4929-8261-ea2874a0082e', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Explain the difference between vertical and horizontal scaling in databases.', N'Middle', N'Vertical scaling involves increasing the power of the existing server, such as adding more CPU or RAM. Horizontal scaling involves adding more servers to the database cluster, distributing the load across multiple machines to achieve greater capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'320f7a56-26ec-4322-9e8f-ea2b490cf84c', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the ''dead letter queue'' pattern?', N'Middle', N'A dead letter queue is a destination for messages that cannot be processed successfully after multiple attempts. It allows developers to isolate and inspect problematic messages without blocking the main processing pipeline or losing data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a81dd72-f5f1-4ea6-b3fc-ea2b5e2f8831', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the primary benefit of using Echo''s Context over the standard library?', N'Fresher', N'The Echo Context provides a much richer set of helper methods for reading request data and writing responses compared to the standard Go HTTP library. It simplifies common tasks like rendering templates, sending JSON, and reading cookies.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa9b3f3b-e95c-4ae9-a462-ea2cfb25d5e4', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'When optimizing a database query, what are the trade-offs of adding more indexes?', N'Middle', N'Adding indexes significantly improves read performance by reducing the need for full table scans. However, every index incurs a cost in terms of storage and slows down write operations, as the index must be updated whenever data is modified, leading to a balance between read and write efficiency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d205de7-b07e-49a8-8ec8-ea2d67033ade', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are traits in Scala and how do they differ from Java interfaces?', N'Fresher', N'Traits are used to define object types by specifying the signature of supported methods, similar to interfaces. However, traits in Scala can also contain concrete method implementations and state, supporting a form of multiple inheritance through mixin composition.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae0e6b9c-9564-4250-ae75-ea2def98c911', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you handle security for distributed data processing jobs involving sensitive information?', N'Senior', N'Security involves ensuring data is encrypted both at rest and in transit between processing nodes, and using fine-grained access control for storage buckets. It is also critical to ensure that processing logs do not inadvertently leak PII by applying masking or anonymization techniques during the logging process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a36ea3d-404a-462e-bb16-ea2e81ddee74', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the trade-offs of using Synchronous vs. Asynchronous replication?', N'Middle', N'Synchronous replication ensures zero data loss by waiting for the standby to confirm the write, but it increases latency and impacts availability if the standby fails. Asynchronous replication provides better performance and lower latency but risks losing committed data if the primary fails before the standby receives the changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
