INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2704b37d-2dc4-49f9-8d20-ea3a4ae1f4cb', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you check if a key exists in an object?', N'Fresher', N'1. Using in operator: You can use the in operator whether a key exists in an object or not and If you want to check if a key doesn''t exist, remember to use parenthesis, 2. Using hasOwnProperty() method: You can use hasOwnProperty to particularly test for properties of the object instance (and not inherited properties) 3. Using Object.hasOwn() (ES2022 — preferred): Object.hasOwn() is the modern replacement for hasOwnProperty(). It is safer because it works correctly even on objects created with Object.create(null) (which have no prototype). &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
