INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11a6d460-9821-4a02-9b18-ea3ce260944d', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the CAP theorem and how does it influence NoSQL database selection?', N'Middle', N'The CAP theorem states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. NoSQL databases are typically categorized by which two they prioritize, helping architects choose systems based on whether they need strong data integrity or high uptime during network failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a6c17a20-cd8e-4770-a949-ea3db3ba2293', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'If you are asked to deliver a feature quickly, what quality attribute might you compromise?', N'Fresher', N'I would likely compromise on ''future-proofing'' or extensibility by writing code that solves the immediate requirement without building a highly generic or reusable framework. The trade-off is that it saves time now, but may require refactoring if requirements change significantly later.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'505638be-eae0-4be0-9899-ea3f3036c9bd', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is a handler function in Axum?', N'Intern', N'A handler is an asynchronous function that receives an HTTP request and returns an HTTP response. These functions serve as the primary logic containers where the business requirements of each API endpoint are implemented.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd7ccff0c-9377-4874-8433-ea418b3db26e', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is SQL injection and how can it be prevented in PHP?', N'Fresher', N'SQL injection is a security vulnerability where an attacker inserts malicious SQL code into form inputs to manipulate database queries. It can be prevented by using prepared statements with parameterized queries, which treat user input as data rather than executable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'eaa4b5fc-6f20-497f-af34-ea422756d62c', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the difference between a static site and an Astro site?', N'Fresher', N'While both can serve static HTML, a standard static site usually requires manual coding or basic templates. Astro provides a robust framework that allows for component reuse, data fetching, and partial hydration, making it much more powerful for developers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcccb356-8257-4939-864c-ea4272fac827', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the primary benefit of using utility classes over traditional CSS?', N'Intern', N'The primary benefit is that it eliminates the need to invent class names for every element. It also prevents the CSS file from growing indefinitely as the project scales, because you reuse existing utilities rather than writing new custom rules.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'00f40d00-e0d2-4f78-a41f-ea463fc38ba3', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the Edge template engine?', N'Intern', N'Edge is the default template engine for AdonisJS used to render dynamic HTML on the server. It provides a clean syntax for logic, loops, and partials, making it easier to generate server-side rendered pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc10469b-cdd2-41a5-81dd-ea47963b2444', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'Can Fiber run over HTTPS?', N'Intern', N'Yes, Fiber supports HTTPS by allowing you to provide TLS certificates directly in the configuration. This ensures that all traffic between the client and the server is encrypted and secure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51b65271-d0b9-423b-9480-ea49fd026aef', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'Explain the concept of ''tail call'' optimization in the context of the .NET JIT compiler.', N'Senior', N'Tail call optimization allows the JIT compiler to reuse the current stack frame for a method call that is the final operation in a function, preventing stack overflow during recursion. While the IL includes a tail prefix, the compiler only applies this optimization if specific architectural constraints and security requirements are met.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6db8311-4bd2-4705-abbf-ea4e39528499', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How do you achieve ''Observability'' in a serverless architecture?', N'Senior', N'Observability in serverless requires externalizing telemetry because you lack access to the underlying infrastructure. This is achieved through distributed tracing headers, structured logging sent to external aggregators, and custom metrics exported via cloud-native monitoring APIs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df03afc5-820c-4b8b-88be-ea51544f7988', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the purpose of the ''final'' keyword?', N'Intern', N'In Java, the final keyword offers restrictions and benefits. It primarily maintains the immutability of different entities. Core Functions - Class Immutability: Makes a class unextendable. - Method Immutability: Disallows method overriding. - Variable Immutability: Commands a constant value for primitives and a constant reference for objects. Advantages - Enhanced Security: Avoids data tampering through unintended extensions, method modifications, or reassignments. - Code Clarity: Clarifies the intended use of class members, ensuring a reliable and coherent design. - Concurrent Safety: Guarantees thread-safe data in situations of code shared across threads. Practical Applications - Inheritance Control: Effortlessly sets up classes that are not designed for extension.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c60416bc-65f3-4cc6-b707-ea5185d6845d', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why do we use logging and monitoring in a production system?', N'Intern', N'Logging records events and errors to help developers trace the root cause of issues, while monitoring provides real-time visibility into the health and performance of the system. Together, they are essential for identifying bottlenecks and responding to incidents before they impact users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81442694-dcbd-4763-9070-ea51dc61bf61', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the purpose of ''Consumer-Driven Contract Testing''?', N'Senior', N'It allows consumers to define the expected API behavior, which the provider then validates against their own implementation. This ensures that any provider-side change that breaks a consumer contract is caught during the CI/CD phase before it reaches production.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06839c6e-babb-4944-b0d9-ea55aed16164', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Describe the benefit of multi-data center replication in Cassandra.', N'Middle', N'Multi-data center replication provides disaster recovery and allows for low-latency access by serving users from the closest geographic region. It also enables the system to remain functional even if an entire data center goes offline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59984471-6c45-400e-b45a-ea55b433d00b', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is null safety in Kotlin?', N'Intern', N'Null safety is a feature that prevents the common null pointer exception by distinguishing between nullable and non-nullable types in the type system. The compiler forces developers to explicitly handle potential null values, reducing the risk of runtime crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c953f3a-3e98-4cfc-826f-ea5622c3d6c6', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'How can you generate API documentation using Swagger in NestJS? Discuss the importance of documenting your API and how it benefits developers?', N'Fresher', N'Generating API documentation in NestJS can be done using the @nestjs/swagger package. This package provides decorators and a SwaggerModule to easily create Swagger documentation. Here is a basic setup: - Start by installing the required dependency. - npm install --save @nestjs/swagger In the above example, SwaggerModule.createDocument(app, config) generates the Swagger JSON. SwaggerModule.setup(''api'', app, document) serves the Swagger UI at the specified path (''api'' in this case). Documenting your API is important for several reasons: Ease of Use: It helps other developers understand how to use your API. They can see the available endpoints, the expected request format, and the response format. Testing: Tools like Swagger UI allow developers to test the API directly from the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c4c41b9-477b-4291-ba1a-ea5638eb530d', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'Why are weak references necessary in Swift, and how do they prevent memory leaks?', N'Middle', N'Weak references are necessary to break retain cycles in Automatic Reference Counting (ARC) where two objects hold strong references to each other. By using weak references, one object does not increase the reference count of the other, allowing ARC to deallocate the objects when they are no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbb703c3-4592-4c09-bee8-ea5663550f39', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are ''server-only'' modules and why are they important for security?', N'Middle', N'Server-only modules are files that are guaranteed to never be bundled into the client-side code, even if imported. This is crucial for security because it prevents sensitive code, such as database credentials or secret API keys, from accidentally leaking into the browser bundle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bae3b208-614a-425d-8127-ea583d4bc4f6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Why is it important to use index columns in a database?', N'Junior', N'Indexes significantly speed up data retrieval operations by allowing the database to find rows without scanning the entire table. They are essential for columns that are frequently used in search queries or as foreign keys.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a17e2aa6-431b-4e27-a97c-ea5c4cabce4d', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the Java Memory Model handle visibility in the context of JIT compiler optimizations?', N'Senior', N'The JIT compiler may reorder instructions or cache variables in registers for performance. The Java Memory Model mandates that the happens-before relationship, established through synchronization or volatile variables, forces a memory barrier that flushes registers and prevents illegal instruction reordering across thread boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3c03fded-3a5e-4552-bc5d-ea5c6218d8f4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is Blade in the context of Laravel?', N'Intern', N'Blade is the powerful templating engine provided with Laravel. It allows you to write plain PHP code in your templates while providing helpful shortcuts for common tasks like echoing data, including other views, and managing control structures like loops and conditionals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f22e6ba8-2cd8-49fc-a8d4-ea5cd339e6fa', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How does Svelte''s approach to ''Dynamic Components'' affect bundle splitting?', N'Senior', N'Svelte allows dynamic component loading, which enables efficient code splitting. By using standard import patterns, the compiler can optimize the split points, ensuring that only the necessary component code is fetched when a dynamic component is requested.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ef1ad85-d4fe-4a0e-874f-ea62ca006ffe', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'How do Svelte Actions provide a low-level bridge to DOM elements?', N'Senior', N'Actions are functions that provide direct access to an element''s lifecycle and DOM node. They allow developers to integrate non-Svelte libraries or perform manual DOM manipulation without interfering with the framework''s internal reactivity system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bc5d7c4-9ea9-4de9-9556-ea6527ea7d78', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What is the benefit of using Time to Live (TTL) in DynamoDB?', N'Middle', N'TTL allows you to automatically expire and delete items after a certain timestamp without consuming write capacity. This is useful for managing temporary data like session states or logs while reducing storage costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'744b5726-d7c1-4e70-9b95-ea669ad3e7ca', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the primary purpose of a Webpack loader, and how does it differ from a plugin?', N'Middle', N'Loaders are used to transform files from different formats into valid modules that Webpack can process, such as converting TypeScript to JavaScript or Sass to CSS. Plugins are more powerful tools that perform a wider range of tasks, such as bundle optimization, environment variable injection, or asset management, by hooking into the entire compilation lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee5b678d-854e-422f-878a-ea6ba3f29908', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'What are reactive properties in Lit?', N'Intern', N'Reactive properties are class fields that trigger an automatic update to the component''s DOM when their values change. By declaring these properties, Lit tracks changes and re-renders the component efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97edb97e-0e2b-4a83-af54-ea6c269c055c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How does breaking down a large task into smaller tickets help improve estimation accuracy?', N'Junior', N'Smaller tasks are easier to visualize and understand, which reduces the chance of missing hidden complexities. By focusing on smaller pieces, I can identify specific risks early and provide a more granular, accurate estimate for each segment of the work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f589b57-87ed-46b6-a76c-ea6d2d9e5866', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain Inheritance in Python with an example?', N'Fresher', N'When one class inherits from another, it is said to be the child/ derived/sub class inheriting from the parent/base/super class. It inherits/gains all members (attributes and methods). Inheritance lets us reuse our code, and also makes it easier to create and maintain applications. Inheritance allows One class to gain all the members(say attributes and methods) of another class. Inheritance provides code reusability,makes it easier to create and maintain an application. The class from which we are inheriting is called super-class and the class that is inherited is called a derived/child class. - They are different types of inheritance supported by Python: - Single Inheritance – where a derived class acquires the members of a single super class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a760614-5396-4369-8510-ea6d42ff874b', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass functions differ from mixins when implementing logic in a design system?', N'Senior', N'Mixins are best for generating blocks of CSS rules and layout structures, whereas functions are designed to return a single value, such as a computed color, a unit conversion, or a map lookup. Functions are conceptually closer to pure utilities that support the generation of styles rather than the styles themselves.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'10ceb159-1922-46c2-a5ca-ea6d8902dcac', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix-web ensure memory safety without a garbage collector?', N'Senior', N'Actix-web relies on Rust''s ownership and borrowing rules, which enforce strict memory management at compile-time. By moving ownership of data through the actor system and using reference counting for shared data, it eliminates memory leaks and dangling pointers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'495fdfa5-24e7-444c-9a75-ea71bc61d50d', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you manage environment-specific configurations in FastAPI?', N'Middle', N'Environment variables are typically managed using Pydantic Settings, which allows you to define a configuration model that automatically reads values from the environment. This provides type-safe configuration and validation, ensuring the application fails early if required variables are missing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07b77d1b-f95b-4ff0-80c8-ea733792899a', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the primary performance metrics to monitor in a production Node.js application?', N'Middle', N'Key metrics include event loop lag, CPU usage, memory heap consumption, and request latency. Monitoring these helps identify bottlenecks, such as blocking code or memory leaks, before they impact the end-user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
