INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58d20f7a-21db-4e02-856e-ea79967c197a', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s ''inline'' keyword interact with the ''reified'' keyword to provide runtime type information?', N'Senior', N'The inline keyword allows the compiler to insert the function''s bytecode directly into the call site. Because the call site knows the specific type being used, the reified keyword allows the compiler to substitute the generic parameter with that concrete type, making it accessible at runtime where generic information would usually be erased.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11b374c4-8010-4605-9eb8-ea7aefed2064', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the advantage of using the @forward rule in a Sass library?', N'Middle', N'@forward allows you to bundle multiple modules into a single entry point file without loading them into the current file. It provides a clean API for library consumers, allowing them to import only what they need while keeping the internal file structure hidden.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'431a4b82-4ee5-49a5-8373-ea7c93d01cc9', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you decide between vertical and horizontal scaling for a legacy application?', N'Senior', N'Vertical scaling is a quick, low-complexity fix for resource-bound applications but hits a physical cost-to-performance ceiling. Horizontal scaling allows for theoretically infinite growth but requires significant investment in load balancing, state management, and infrastructure automation. I choose vertical scaling for immediate relief and plan for horizontal scaling once the application''s growth trajectory justifies the architectural refactoring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd8154886-61d9-4a15-a7ec-ea7e70104aa2', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you handle a scenario where you discover a major flaw in an existing system while working on a small feature?', N'Junior', N'I would first document the flaw and assess its potential impact on the system''s stability and security. I would then inform my lead or manager about the issue before deciding whether to address it immediately or schedule it as a separate technical debt task. I prioritize safety and communication over making unapproved changes to core systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
