INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0f5d81e-6778-4a07-989d-ea83349d1663', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is meant by the term ''micro-framework''?', N'Intern', N'A micro-framework is a minimalist web framework that provides the absolute minimum required to get a web application running. It avoids adding extra features like database abstraction or form validation by default, leaving those choices to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e15157a2-0ac0-43e5-922d-ea838d2bceea', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between function overloading and overriding?', N'Intern', N'Function overloading occurs when multiple functions in the same scope share the same name but have different parameter lists. Function overriding occurs when a derived class provides a specific implementation for a function that is already defined in its base class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'176bd74c-1a6e-42b1-bf61-ea83b0574d23', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'How does Alpine.js handle asynchronous data fetching within its reactivity cycle?', N'Senior', N'Alpine.js allows for asynchronous operations within directives or methods, but it does not have built-in mechanisms to handle loading states or race conditions automatically. Developers must manually manage component state variables to track pending or failed requests, as the reactivity system triggers updates only when the underlying data object is modified.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
