INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4423ddbb-830d-4eee-9d45-ea87fb928827', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What does it mean for a function to be pass-by-reference?', N'Junior', N'Pass-by-reference means that the function receives a reference to the actual variable rather than a copy of its value. Any changes made to the variable inside the function will persist and affect the original variable outside the function''s scope.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e3a078f-d946-4557-ad07-ea894b7c1e12', N'6d977270-8873-49d3-b588-8f7a83e485c7', N'What is the purpose of the ''Object.GetHashCode'' and ''Equals'' contract in dictionary performance?', N'Senior', N'The contract ensures that equal objects generate the same hash code, allowing the hash table to map keys to buckets efficiently. Violating this contract causes collisions or retrieval failures, forcing the collection to degrade from O(1) average lookup time to O(n) linear scanning.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b0d412a-e2f6-4c1b-b6f9-ea89835fe1bd', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How would you design a rate-limiting mechanism to protect an API from abuse?', N'Middle', N'I would implement a distributed rate-limiting strategy using a fast, in-memory store like Redis to track request counts by user or IP address. I would then configure the system to return a specific HTTP status code when thresholds are exceeded, ensuring the system remains responsive for legitimate users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
