INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'035a062b-ff62-479d-bb59-ea8d4b280c46', N'954a0331-deff-4399-b588-96f39fec001d', N'What is a DI token?', N'Intern', N'A DI token is a lookup token associated with a dependency provider in dependency injection system. The injector maintains an internal token-provider map that it references when asked for a dependency and the DI token is the key to the map. Let''s take example of DI Token usage,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'685b125e-94b8-450e-957b-ea8d7add6d45', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'In a distributed system, how do you manage the trade-off between increased observability and system performance?', N'Middle', N'Extensive logging and metrics collection provide invaluable insights for debugging but introduce overhead in terms of storage costs, network bandwidth, and CPU cycles on the application nodes. To balance this, one should implement sampling strategies for traces and prioritize logging only critical events in production. The goal is to collect enough data to ensure reliable troubleshooting without significantly degrading the latency or throughput of the primary business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a7f0cdf-a36b-4068-9be4-ea8d84d9d97d', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is jQuery AJAX?', N'Intern', N'jQuery AJAX provides a set of methods to perform asynchronous HTTP requests to a server. This allows a webpage to update specific content without requiring a full page reload, improving the user experience.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d74f7c0-aa38-401f-b28e-ea8f653a679a', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How does Express handle asynchronous error propagation in middleware, and what are the limitations compared to newer frameworks?', N'Senior', N'Express middleware historically required explicitly passing errors to the next function. Modern frameworks like Fastify or Koa leverage async/await natively with better stack trace propagation, whereas Express struggles with unhandled promise rejections unless explicitly wrapped or using specific error-handling middleware.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90de60ea-44e0-4656-9141-ea90ce9b39ea', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the role of the Phoenix Presence module in a distributed system.', N'Middle', N'Phoenix Presence allows you to track user state across a cluster of nodes. It uses Conflict-free Replicated Data Types (CRDTs) to ensure that presence information is eventually consistent across all nodes without requiring a central database for state synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf040824-0cc5-4d38-927e-ea92fae89b45', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Discuss the scalability limitations of Django’s session framework when stored in the database.', N'Senior', N'Storing sessions in the database creates a persistent write and read load on the primary database, which can become a bottleneck as user traffic scales. Moving to a distributed key-value store like Redis improves performance by reducing database contention and lowering latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bd41de5d-6da5-4b24-bdce-ea9460d9acc9', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the appsettings.json file?', N'Intern', N'The appsettings.json file is used to store configuration settings for the application, such as database connection strings, API keys, or environment-specific variables. It allows developers to change application behavior without recompiling the code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'983d8a65-c109-4388-addf-ea96da137b4f', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Explain the benefit of using ''isolates'' for heavy computational tasks.', N'Middle', N'Since Dart runs on a single main thread, performing heavy computations there would block the event loop and freeze the UI. Offloading these tasks to a separate isolate allows them to run in parallel on a different CPU core, ensuring the main application remains responsive.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58d1a2e2-6b8e-4c6e-87ec-ea9a59f68dcc', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the advantages of using the ''Normalized State'' pattern for relational data?', N'Senior', N'Normalization prevents data duplication and inconsistencies by storing entities in a flat lookup table rather than nested trees. This makes updates more efficient, as modifying an entity in one place automatically reflects across all parts of the UI that reference that specific ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f290cfd1-a7ad-42d1-8b98-ea9a6f5d9b51', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the significance of the V8 engine in the Node.js ecosystem?', N'Middle', N'V8 is the high-performance JavaScript engine developed by Google that compiles JavaScript code into native machine code. Its speed and efficient garbage collection are primary reasons why Node.js is performant enough to be used for server-side development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3abaa211-ea85-4110-aa13-ea9c73fe83c0', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you approach debugging a distributed system issue where errors occur intermittently across multiple microservices?', N'Middle', N'I would start by implementing distributed tracing to follow request flows across service boundaries. By analyzing aggregate logs and correlation IDs, I can identify which specific service or network hop is introducing latency or failures, then narrow down the state of that service at the time of the error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'182c6365-0de3-4074-a957-ea9d29515718', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'Why would a developer choose to use Preact over a native web component approach?', N'Middle', N'Preact provides a robust state management system, a familiar component-based lifecycle, and a mature ecosystem that native web components lack. It balances the performance benefits of raw DOM manipulation with the developer productivity of a modern frontend framework.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8986d97-b9e8-4865-afe4-eaa40dafb96c', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'If you realize your estimate was wrong because you missed a critical requirement, how do you handle the situation?', N'Junior', N'I would immediately inform the stakeholders of the missing requirement and how it changes the project scope. I would then provide a re-estimate based on the new information and offer options, such as removing other tasks to compensate for the additional work.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2f2c7330-5314-4152-90b3-eaa441adb9bd', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How does MongoDB handle ''stale'' reads in a replica set?', N'Senior', N'Stale reads occur when a client reads from a secondary that has not yet caught up to the primary''s state. To prevent this, clients can use causal consistency sessions or specify a read concern of ''majority'' to ensure the data read has been acknowledged by a majority of the replica set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf6ed0c9-4301-4105-898c-eaa45069e986', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What is the @error directive in Sass?', N'Intern', N'The @error directive is used to stop the compilation process and display a custom message if something goes wrong. It is helpful for catching configuration errors or invalid inputs during the development phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
