INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e73070e3-5958-41fe-873b-eaa92d46d1c4', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'Discuss the overhead of Nitro''s ''Storage'' abstraction.', N'Senior', N'The Nitro storage layer provides a unified interface for different key-value storage backends like Redis or the filesystem. While it adds a small abstraction layer, the performance impact is negligible compared to the architectural benefit of being able to switch storage providers without refactoring application logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e9d04ccb-ed2a-4e2c-ae4e-eaaece2579ab', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle concurrent access to the same request path, and is it thread-safe?', N'Senior', N'Echo is thread-safe by design because it creates a new context instance for every incoming request. The router itself is read-only after initialization, allowing for safe concurrent access by the underlying net/http server''s worker pool.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0b32b551-0a58-4b7b-83bb-eab00877b38a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is microtask', N'Intern', N'A microtask is a type of JavaScript callback that is scheduled to run immediately after the currently executing script and before the next event loop tick. Microtasks are executed after the current task completes and before any new tasks (macrotasks) are run. This ensures a fast and predictable update cycle. Common sources of microtasks stored in the microtask queue include: 1. Promises: When a Promise is resolved or rejected, its .then(), .catch(), and .finally() callbacks are placed in the microtask queue.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a21d6177-7a3c-4641-8603-eab05f4fde9c', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What does ''Atomicity'' mean in a transaction?', N'Junior', N'Atomicity ensures that all operations within a transaction are completed successfully. If any part of the transaction fails, the entire transaction is rolled back so that no partial changes are saved.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e32214cc-4780-420d-8230-eab14f6bccd2', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How do you say that props are readonly?', N'Fresher', N'When you declare a component as a function or a class, it must never modify its own props. Let us take a below capital function, The above function is called “pure” because it does not attempt to change their inputs, and always return the same result for the same inputs. Hence, React has a single rule saying "All React components must act like pure functions with respect to their props."', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cb864a6c-895c-4f4f-a2ea-eab2f42f21a8', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'Why is the use of ''async'' functions required in Axum?', N'Fresher', N'Axum handlers must be async because they perform non-blocking I/O operations, such as reading from a database or a network socket. The async keyword ensures the thread is freed up to handle other requests while waiting for I/O completion.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7e27b163-469d-4daf-8ded-eabd87bd20a9', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is a ''nested route'' in Ember?', N'Junior', N'Nested routes allow you to create complex URL structures where sub-pages share a common layout or parent data. They are defined in the router file and help maintain a clear hierarchy for the application''s navigation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de5e42ee-26ce-4cb6-88d0-eabe6a796658', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''tsconfig.json'' project reference feature enhance scalability in large monorepo architectures?', N'Senior', N'Project references allow for the decomposition of a massive codebase into smaller, independently compilable segments that share build artifacts. This drastically reduces incremental build times and allows for granular dependency management, ensuring that changes in one module only trigger downstream rebuilds when necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8cb3c853-8beb-4253-9493-eac0a07ac8d6', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the significance of the .Call interface in extending R with compiled code.', N'Senior', N'The .Call interface provides a stable API for passing R objects directly to C or C++ routines, allowing developers to bypass R''s overhead for performance-critical loops. It requires manual memory management and strict adherence to R''s internal data representation, which is a major source of potential segmentation faults if not handled correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a7437125-9b43-4e3a-85ff-eac29919d941', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'Discuss the trade-offs of using MediatR in an ASP.NET Core application for implementing the Mediator pattern.', N'Senior', N'MediatR promotes loose coupling by decoupling the request initiation from the request handler, which simplifies controller logic and improves testability. However, it can also make the code harder to navigate due to implicit dependencies and may introduce unnecessary abstraction overhead if the application is simple.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c4b5daa-f7db-4aaa-8ec9-eac38a3ac21b', N'd5b12859-0c9f-4e2f-9b3a-1ccb6c5080e5', N'What are the implications of using a ''sharding key'' that is not uniformly distributed?', N'Senior', N'A non-uniformly distributed sharding key leads to skewed partitions, where some nodes handle significantly more load and storage than others. This imbalance negates the benefits of horizontal scaling, as the overall system performance becomes limited by the performance of the most heavily loaded shard.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a07186c-a5d7-4c54-b0ab-eac4f78bb370', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What are the common data types supported by Redis?', N'Intern', N'Redis supports several data structures including strings, lists, sets, sorted sets, hashes, and bitmaps. These structures allow developers to model data in ways that are more efficient for specific application needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f894a94-ae30-4e93-ad8c-eac636dbd260', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the validity properties', N'Intern', N'The validity property of an input element provides a set of properties related to the validity of data. 1. customError: It returns true, if a custom validity message is set. 2. patternMismatch: It returns true, if an element''s value does not match its pattern attribute. 3. rangeOverflow: It returns true, if an element''s value is greater than its max attribute. 4. rangeUnderflow: It returns true, if an element''s value is less than its min attribute. 5. stepMismatch: It returns true, if an element''s value is invalid according to step attribute. 6. tooLong: It returns true, if an element''s value exceeds its maxLength attribute. 7. typeMismatch: It returns true, if an element''s value is invalid according to type attribute. 8.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f2fd30e2-3b4b-4f3d-8b76-eac6710adccc', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'When should you use the Options pattern in ASP.NET Core?', N'Middle', N'The Options pattern should be used to manage strongly-typed configuration settings. It promotes the Interface Segregation Principle by allowing classes to inject only the settings they need, rather than the entire configuration object. This approach simplifies unit testing and makes configuration management more maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79ebc80d-2fb1-4d49-a606-eaca1a7376bc', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'How does middleware nesting affect performance in Chi?', N'Middle', N'While middleware nesting is highly flexible, excessive nesting can introduce minor overhead due to function call stacks. However, this is generally negligible compared to I/O operations, and the benefit of cleaner, modular code far outweighs the micro-performance costs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'304e7e74-a336-4a29-a839-eacd5f8fa5d8', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is data denormalization?', N'Fresher', N'Denormalization is the process of storing related data together in one place, even if it results in data duplication. This is a common strategy in NoSQL to optimize read performance and simplify data access patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc631d2b-1658-4d26-8f72-eacf080cbd6a', N'954a0331-deff-4399-b588-96f39fec001d', N'What is the difference between a Module-based and a Standalone component architecture?', N'Middle', N'Module-based architecture organizes code into NgModules that manage dependencies and scope for components. Standalone components simplify the architecture by allowing components to manage their own dependencies directly, reducing the need for intermediate modules and boilerplate code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb73807d-6baa-42a5-b22f-eacf55770c9b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does a Cache-Aside pattern work, and what is a common concurrency risk associated with it?', N'Middle', N'In Cache-Aside, the application first checks the cache and, upon a miss, fetches data from the database to populate the cache for future requests. A common risk is the race condition where a stale value is written to the cache by a slow database read that completes after a more recent update has already invalidated or updated the cache.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2ea0b440-79ed-4912-a94e-ead02337200a', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'How do database systems handle ''phantom reads'' using Multi-Version Concurrency Control (MVCC)?', N'Senior', N'MVCC allows a transaction to see a consistent snapshot of the data based on the transaction ID or timestamp at the start of the process. By reading older versions of rows that were visible when the transaction started, the system effectively isolates the query from inserts or deletes performed by concurrent transactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0043832-9a67-4ac1-8b2a-ead1dc7e5475', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the role of the Mongos process in a sharded environment?', N'Middle', N'Mongos acts as a query router that interfaces between client applications and the sharded cluster. It determines which shard holds the necessary data by consulting the cluster metadata and routes operations accordingly, shielding the client from the underlying cluster complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd01d640-0602-4bb7-8c80-ead22195732a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are the benefits of pure functions', N'Intern', N'Some of the major benefits of pure functions are listed below, - Easier testing: Since output depends only on input, pure functions are simple to test. - Predictability: No hidden side effects make behavior easier to reason about. - Immutability: Pure functions align with ES6 best practices, such as preferring const over let, supporting safer and more maintainable code. - No side effects: Reduces bugs related to shared state or mutation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c10aee5a-bd24-464a-ac8c-ead61c2e75e1', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are ''branded types'' and how do they prevent accidental type mixing?', N'Senior', N'Branded types use intersection types to add a unique, non-existent property to a primitive, effectively creating a nominal-like constraint. This prevents the accidental passing of different types that share the same underlying structure, such as confusing a user ID with a product ID.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3fceedda-0173-4ec1-8ee2-ead825e9eb1b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What is the difference between class variables and instance variables?', N'Fresher', N'Instance variables are specific to a single object instance and are prefixed with an @ symbol. Class variables are shared across all instances of a class and are prefixed with @@, making them accessible to all objects of that class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d6c8017-2f46-4ddf-bd6d-ead850ad23cf', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How do you handle unhandled promise rejections in a production Node.js environment?', N'Middle', N'You should listen to the ''unhandledRejection'' event on the process object to log errors and perform graceful shutdowns. Relying on global handlers is a safety net, so the best practice is to always attach catch blocks to promises or use async/await with try-catch wrappers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'496fa829-1e62-4b29-8a13-ead8ae7832a2', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''Gemfile.lock'' file?', N'Junior', N'The Gemfile.lock file records the exact versions of every gem and its dependencies that were installed. It ensures that every developer working on the project and every production server uses the exact same library versions to avoid ''it works on my machine'' issues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1436d3a-b6db-48f0-a009-eada1aef8435', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage routing for complex sub-applications, and how does this affect code organization?', N'Senior', N'Hono supports route grouping and sub-applications, allowing developers to mount separate Hono instances under specific paths. This hierarchical routing architecture promotes modularity, enabling teams to develop, test, and deploy specific domains independently while maintaining a unified API surface and shared middleware stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33f17f6b-7fe4-4cc8-b388-eada6a888779', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'Does Chi provide built-in support for serving static files?', N'Fresher', N'Yes, Chi provides a FileServer helper that makes it easy to serve static assets from a directory. It integrates seamlessly with the routing system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbde658a-0b5b-4eb6-a977-eaddefbbda28', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'How do you handle multi-tenancy in a Rails application at the database level?', N'Senior', N'Multi-tenancy can be implemented via a shared schema with a tenant_id column or separate schemas per tenant. Shared schemas are easier to scale but require strict application-level filtering, whereas separate schemas provide better data isolation but increase migration and operational complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'779a1baa-818b-48ff-8c86-eade38c53301', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind CSS achieve a significantly smaller bundle size compared to traditional CSS-in-JS libraries?', N'Senior', N'Tailwind uses a static analysis tool called JIT (Just-In-Time) compiler that scans source files and only generates the specific CSS rules actually used in the project. Unlike CSS-in-JS, which often injects styles at runtime via JavaScript, Tailwind produces a static CSS file, eliminating the runtime overhead and reducing the payload to the minimal set of required atomic styles.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'185e54c4-dec9-4885-acc3-eae01663b87b', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What is the primary architectural goal of ''Domain-Driven Design'' in microservices?', N'Senior', N'The goal is to define ''Bounded Contexts'' that correspond to business domains. By mapping services to these contexts, you ensure that each service has a clear, isolated responsibility and a ubiquitous language that aligns with business needs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b48959c0-fd61-4ccb-af72-eae0f34030ef', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How can you debug database queries in Laravel?', N'Middle', N'You can use the DB::enableQueryLog method to capture executed queries or use a tool like Laravel Debugbar to visualize them in the browser. These methods help identify performance bottlenecks or incorrect query structures during development.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3e0721a2-14e4-4000-ba50-eae50ede89f8', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How do Astro''s ''Content Layer'' and ''Remote Data'' integration patterns improve scalability?', N'Senior', N'The Content Layer allows decoupling data sourcing from UI rendering, enabling the ingestion of data from various CMSs or APIs into a unified local store. This improves scalability by allowing developers to query a local, normalized data structure instead of hitting external APIs repeatedly during build or request time.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bf5cf21-e507-4516-a3f1-eae5ee65b7cf', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the difference between a stateless and stateful service?', N'Middle', N'A stateless service does not store client session data between requests, making it easier to scale horizontally. A stateful service maintains context, which requires session persistence or sticky sessions, complicating the scaling process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92f65de1-d166-49be-95d9-eae6260255df', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the purpose of ''resolve.extensions''?', N'Junior', N'This setting allows you to specify which file extensions Webpack should try to resolve automatically. It enables you to import files without typing their full extensions, making your import statements cleaner and more flexible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'36044b1d-9def-4cd0-b6c8-eae7171640fb', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'How does DynamoDB handle data replication?', N'Junior', N'DynamoDB automatically replicates data across multiple physical disks and availability zones within an AWS region. This ensures high durability and availability of your data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6481faef-9363-4882-80d5-eae7312e787a', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is meant by ''eventual consistency'' in NoSQL?', N'Junior', N'Eventual consistency is a theoretical guarantee that if no new updates are made to a data item, eventually all accesses to that item will return the last updated value. It acknowledges that data might be temporarily inconsistent across distributed nodes during a synchronization process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26edd832-7a8f-41b6-90d2-eae85794a3b0', N'a000805c-e41f-42a9-af12-66b45348f77b', N'How does AdonisJS ensure consistent error handling across the application?', N'Middle', N'AdonisJS uses a global exception handler that catches all unhandled errors and maps them to appropriate HTTP status codes. This centralizes logging and formatting, ensuring that clients always receive predictable error structures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'229a86e0-d68c-4c05-a920-eae8c484aa63', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How do Generics contribute to type safety in Java?', N'Middle', N'Generics provide compile-time type checking, allowing developers to define classes and methods that operate on specific types without needing to cast objects explicitly. This eliminates the risk of ClassCastException during runtime and makes code more readable and reusable. Type erasure is the mechanism by which Java implements generics, stripping type information after compilation to maintain backward compatibility.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bed29222-a1fa-401c-95a5-eaead180901f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core''s Data Protection API ensure security in a distributed, multi-node environment?', N'Senior', N'The Data Protection API provides a set of cryptographic services for protecting data at rest, such as cookies or tokens. In a distributed environment, it must be configured to use a shared key repository, such as Redis or Azure Key Vault, so that all instances can decrypt data encrypted by any other instance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5003358e-8329-4b69-9443-eaef5fefa371', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle security in a microservices architecture?', N'Middle', N'Security is typically handled using a ''Defense in Depth'' approach, often involving an API Gateway for external authentication and token-based authorization like JWT for internal communication. This ensures that every service validates the identity and permissions of the requester before processing the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b62446fc-757e-42ef-a303-eaf2d17f1f18', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Why does Scala distinguish between ''covariant'', ''contravariant'', and ''invariant'' type parameters?', N'Middle', N'These annotations define subtyping relationships between generic types, ensuring type safety during assignment and method invocation. Covariance allows a list of subtypes to be treated as a list of supertypes, while contravariance allows a consumer of a supertype to accept a subtype.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd0ebadc2-9c4d-454b-96e3-eaf6427732d7', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''key'' attribute when using v-for?', N'Junior', N'The key attribute provides a unique identifier for each item in a list. It helps Vue''s virtual DOM algorithm track element identity, which improves performance and prevents bugs during list reordering or updates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'113df91e-b4bf-4ef0-b42c-eaf667bf0229', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the function of the +error.svelte file?', N'Intern', N'The +error.svelte file is a specialized component that renders when an error occurs while loading a route. It provides a way to show a user-friendly message rather than a blank screen or a default browser error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'692978b0-11d6-4263-a5ea-eafa66fabdcf', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'How does Tailwind handle responsive design at the architectural level, and how does it differ from standard media queries?', N'Senior', N'Tailwind uses mobile-first responsive modifiers that stack naturally, allowing developers to define layout changes directly in the HTML. This is architecturally superior to scattered media queries in external CSS files, as it keeps the responsive logic co-located with the structure, making it easier to audit and debug component behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58ee50db-2eac-4d34-90b8-eafbc61fecb4', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'How does SvelteKit''s reactivity system compare to the ''Virtual DOM'' regarding reconciliation?', N'Senior', N'SvelteKit''s reactivity is based on explicit variable assignments, allowing the compiler to know exactly which DOM nodes need to change without comparing old and new states. This results in highly efficient, targeted updates that outperform Virtual DOM systems which must always perform a comparison pass.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9604409-4528-4186-a547-eafc5f5bbd5e', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'What are the performance implications of content negotiation in APIs?', N'Middle', N'Content negotiation allows the client to request specific formats via headers, such as JSON or XML. While flexible, it requires the server to implement logic to handle and transform responses, which can add complexity and impact serialization performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae2ed0a4-5c3a-4ed1-8527-eafe573c4eaa', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the architectural considerations for implementing a custom structural directive?', N'Senior', N'Structural directives manipulate the DOM by adding or removing elements, which requires careful management of ViewContainers and EmbeddedViews. Developers must ensure proper cleanup of these views to avoid memory leaks and must consider how the directive interacts with Angular''s change detection cycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e163e11-a3f1-4ad1-ae12-eafe8dad6fd7', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What happens if your application exceeds its provisioned throughput?', N'Junior', N'If your application exceeds its provisioned capacity, DynamoDB will throttle the requests. This results in an error being returned to the client, which should be handled by implementing retry logic with exponential backoff.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a3cce4e6-7200-49dd-9ada-eb04c91677b9', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'How does Laravel handle concurrent database updates, and what are the strategies to prevent race conditions?', N'Senior', N'Laravel provides pessimistic locking via ''lockForUpdate'' or optimistic locking via version columns to prevent race conditions. Pessimistic locking is safer for high-contention scenarios but can cause deadlocks, while optimistic locking is better for high-read, low-contention environments where conflicts are rare.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'056ac3fb-ff14-4dab-8849-eb061962f4d9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono provide support for OpenAPI?', N'Middle', N'Hono provides a dedicated OpenAPI/Swagger integration that generates documentation directly from the route definitions. This allows developers to maintain their API spec and implementation in sync, reducing the risk of documentation drift.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'02455341-95a2-4928-bddd-eb074f21fbc0', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What are Phoenix Channels and why are they used?', N'Fresher', N'Phoenix Channels are a mechanism for real-time communication between the server and clients. They allow developers to build features like chat applications or live dashboards by enabling bidirectional, low-latency messaging over WebSockets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad6a9530-2264-42aa-96e1-eb095fcd4596', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why is it good practice to use dependency injection in your code?', N'Fresher', N'Dependency injection makes components easier to test because you can inject mock versions of dependencies during testing. It also reduces tight coupling between classes, making the overall codebase more modular and easier to maintain or refactor in the future.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'abff55cd-6f43-4d76-8129-eb0c78037027', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does the lang attribute in html do?', N'Intern', N'The lang attribute specifies the language of an element''s content. It is placed on the tag to declare the language of the entire page, or on individual elements to override the page language. What it does: 1. CSS styling — Enables the :lang() pseudo-class to apply language-specific styles: 2. Spelling & grammar checkers — Browsers and tools use it to apply the correct dictionary for spell-checking 3. Search engine language detection — Helps search engines understand the language of content for accurate indexing and localized results 4. Screen readers & accessibility — Assistive technologies use it to select the correct pronunciation and reading rules for text-to-speech 5. Browser behavior — Affects automatic translation prompts (e.g., Chrome''s "Translate this page?") 6.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb28eda1-0912-4f08-8755-eb1280ab893f', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the role of the Rails middleware stack, and when would you interact with it?', N'Middle', N'The middleware stack is a chain of components that process incoming HTTP requests and outgoing responses. You interact with it when you need to perform global tasks like authentication, session management, or logging that should occur before the request reaches the Rails controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92779631-c57b-4b0b-b11c-eb15afff1c20', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the architectural significance of the ''Compiler-Informed Virtual DOM'' in Vue 3?', N'Senior', N'The compiler analyzes templates during build time and marks static parts of the DOM, allowing the runtime to skip reconciliation for unchanging nodes. This reduces the work required by the diffing algorithm by effectively flattening the virtual tree and focusing exclusively on dynamic content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae547d43-ec83-4106-9a10-eb17e10826a7', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Explain the architectural trade-offs of Remix''s ''nested routing'' model regarding performance.', N'Senior', N'Nested routing allows granular data fetching for specific page segments, meaning only the necessary data for a sub-route is requested during navigation. While this significantly reduces payload sizes, it requires careful architectural planning to manage state synchronization across multiple independent loader boundaries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ceb5b0e8-7e9c-40e8-9a4d-eb18a2783888', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What are the advantages and drawbacks of using SvelteKit''s ''Adapter'' pattern for deployment?', N'Senior', N'The adapter pattern decouples the application from the deployment environment, allowing the same code to be deployed to Vercel, Netlify, or a custom Node.js server. The drawback is that some platform-specific features, like edge functions or specific caching headers, may require platform-specific adapter configurations that limit portability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6e4281f9-ad84-432a-afe3-eb19691aefdb', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the architectural trade-offs of using Phoenix Channels versus standard HTTP polling for real-time features.', N'Senior', N'Channels maintain long-lived, stateful TCP connections, offering significantly lower latency and reduced overhead for frequent updates compared to HTTP polling. However, they require more memory per connection on the server and mandate horizontal scaling strategies that account for connection stickiness or distributed pub/sub backplanes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ba9e50e-9291-48d0-a6d8-eb1b9d898f76', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'Is Quarkus strictly for new projects?', N'Fresher', N'No, Quarkus can be used for existing projects. While migrating from other frameworks may require refactoring, Quarkus provides compatibility layers that allow many standard Java EE and Jakarta EE applications to run with minimal changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'22a9e21d-bb61-4165-8be7-eb1c6811dcd7', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'What is the technical trade-off of using jQuery''s animate() method versus CSS transitions?', N'Senior', N'jQuery''s animate() uses JavaScript-based timing loops that execute on the main thread, making animations susceptible to stuttering when the thread is busy. CSS transitions are handled by the browser''s compositor thread, enabling hardware acceleration and smoother frame rates.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e368037b-8c98-4ab0-bf8d-eb1d48379e3c', N'a2838158-7305-480a-b22b-4dc35776b400', N'What is the benefit of database replication?', N'Middle', N'Replication involves copying data from a primary database to one or more replicas, which increases read throughput and provides data redundancy. If the primary node fails, a replica can be promoted to ensure high availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b188b9bd-9735-438b-99df-eb1e5e692cc0', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the role of middleware in the Echo framework?', N'Middle', N'Middleware in Echo acts as a layer that executes before or after the main handler. It is used for cross-cutting concerns like logging, authentication, compression, and error recovery, allowing for modular and reusable code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae1281c7-411b-4902-bd71-eb20673a3b3d', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'What is the benefit of the ''keepalive'' property in Nuxt page transitions?', N'Middle', N'The keepalive property allows Nuxt to cache inactive page components in memory instead of destroying them. This improves performance during navigation by preserving the component state and avoiding the need to re-fetch data or re-render the component when the user navigates back.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'362dc24e-46ed-4992-a0e4-eb22c5b5c886', N'a2838158-7305-480a-b22b-4dc35776b400', N'Why is rate limiting important for a public-facing API?', N'Middle', N'Rate limiting prevents abuse, such as DoS attacks, and ensures fair usage among clients by restricting the number of requests a user can make within a specific timeframe. It helps protect backend resources from being overwhelmed and ensures stable service for all users.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5eb64f0a-209c-4569-9447-eb23ce263ac6', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What are ''Control Flow'' components in SolidJS?', N'Fresher', N'Control flow components are built-in elements like Show, For, and Switch that handle logic within JSX. They are designed to be reactive, ensuring that only the necessary DOM changes occur when conditions or data lists change.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1107fd9f-e4c7-4f03-b933-eb26e17a6562', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What are the primary architectural risks of a shared database across multiple microservices?', N'Senior', N'A shared database creates tight coupling between services, preventing independent deployment cycles and scaling. It also risks data integrity issues if one service modifies schema or data structures that another service relies on, effectively turning a microservices architecture into a distributed monolith.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7b2cfe9f-78f6-473a-a9fc-eb2a89537a4a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis achieve ''read-your-writes'' consistency in a replicated environment?', N'Senior', N'To ensure read-your-writes consistency, applications must route write operations to the master instance and subsequent reads to that same master. Relying on replicas for reads will always introduce the risk of reading stale data due to the inherent asynchronous nature of replication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'804cd3ad-9351-4456-8cb6-eb2ca48aeed8', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does ''Tunable Consistency'' (QUORUM, ALL, ONE) affect the CAP theorem balance in Cassandra?', N'Senior', N'Tunable consistency allows architects to choose between availability and consistency on a per-request basis. Setting R+W > N provides strong consistency at the cost of latency and availability, while R+W <= N prioritizes low latency and high availability at the cost of potential stale reads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'45a39248-175b-49da-a94b-eb2d2e6a1692', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What does the term ''asynchronous'' mean in FastAPI?', N'Intern', N'Asynchronous programming allows the application to handle multiple requests concurrently without waiting for a single operation to complete. This is achieved using the async and await keywords, which improves performance for I/O-bound tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
