INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c2d1fca1-ef87-46ee-bba0-eb321968ac48', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What is the difference between a static library and a dynamic library in terms of linking?', N'Senior', N'A static library is archived code that is copied into the executable at link time, resulting in a self-contained binary. A dynamic library is loaded at runtime, allowing multiple processes to share the same physical memory for the code, while updates to the library do not require recompiling the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
