INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f6e5a25f-f723-4753-a26e-eb500f1de278', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the purpose of void(0)?', N'Intern', N'The void(0) is used to prevent the page from refreshing. This will be helpful to eliminate the unwanted side-effect, because it will return the undefined primitive value. It is commonly used for HTML document that uses href="JavaScript:void(0);" within an element. i.e, when you click a link, the browser loads a new page or refreshes the same page. But this behavior will be prevented using this expression. Example: the below link notify the message without reloading the page &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1e5e919f-a769-480d-9193-eb50a968aee4', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'Can you describe the type hierarchy in Scala?', N'Senior', N'Scala, being a hybrid of object-oriented and functional paradigms, features an expressive and intricate type hierarchy. This hierarchy is rooted in a single type, Any, which has two direct subclasses: AnyVal and AnyRef. Key Hierarchy Components 1. Any: Root type of Scala''s type system. All other types are its subtypes. Divided into AnyVal and AnyRef subtypes. 2. AnyVal: Represents values. Subtypes include: - Unit: Correlates to void in Java and signals the absence of a "useful" value. - Boolean: Equivalent to its Java counterpart, representing true or false. - Char: Represents a single character, akin to Java''s char. - Byte, Short, Int, Long, Float, Double: Finite-size numeric types, comparable to native types in Java like int or double. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
