INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f5bf0df-dbf4-4c53-bb2a-eb95476f0954', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is your strategy for managing long-term technical debt?', N'Senior', N'I treat technical debt as a first-class citizen by prioritizing ''refactoring sprints'' and allocating a fixed percentage of engineering capacity to debt reduction. I track debt through documentation and observability, ensuring that the most impactful issues are addressed systematically.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a32bba4-fd1a-47a5-b5f2-eb95b365607d', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What does the ''autocomplete'' attribute do in forms?', N'Middle', N'The autocomplete attribute allows developers to suggest browser-level assistance for filling out form fields. It helps the browser identify the type of information expected—such as email, address, or credit card info—based on saved user data. This significantly improves usability and reduces friction in the conversion process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84503651-5203-4b47-b3da-eb97d1ca2cfa', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript''s structural typing system differ from nominal typing?', N'Middle', N'TypeScript uses structural typing, meaning type compatibility is determined by the members of the type rather than explicit declarations or names. In a nominal system, two types are only compatible if they share the same explicit name or origin, even if their structure is identical.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
