INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd2375b97-ecb7-471b-b42a-eb995a67f503', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the purpose of Pipes in NestJS?', N'Intern', N'Pipes are used for two main purposes: transformation and validation. They take input data and transform it to the desired output or evaluate the input to ensure it meets specific criteria, throwing an exception if the validation fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9c08473c-3e8e-494e-9bfb-eb9ae0475369', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'Explain the trade-offs of using a ''Shared-Nothing'' architecture in a message broker.', N'Senior', N'A shared-nothing architecture avoids contention on shared storage or memory, allowing for linear scalability and increased fault isolation between nodes. However, it requires more complex logic for data replication and consistency management, as nodes must communicate explicitly to synchronize state across the cluster.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
