INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c126a64-5bea-4f89-a30e-ebb32201d16e', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the ''N+1'' query problem in Django, and what are the architectural strategies to identify and fix it?', N'Senior', N'The N+1 problem occurs when an application executes a query to fetch parent records and then executes an additional query for each record to fetch its children. It can be identified using tools like Django Debug Toolbar and fixed by using select_related or prefetch_related to fetch the data in bulk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
