INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd187ccb4-6dbe-42fc-a901-ebb6d0e85e78', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the difference between a loader and a plugin?', N'Intern', N'Loaders are used to transform certain types of modules into valid bundles, typically working at the file level. Plugins are more powerful tools that can perform a wider range of tasks, such as bundle optimization, asset management, and environment variable injection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
