INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31774154-2dac-4116-bc18-ebba9417052b', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'How does Flask handle static files?', N'Intern', N'Flask serves static files like CSS, JavaScript, and images from a folder named ''static''. These files are accessible via a specific URL path, allowing the browser to load them to style or enhance the web page.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f1f57f70-9ac1-4a8c-9e8f-ebc4d3194048', N'954a0331-deff-4399-b588-96f39fec001d', N'What are Interceptors in Angular, and what are their typical use cases?', N'Middle', N'Interceptors are services that intercept HTTP requests and responses globally. They are commonly used for tasks like adding authentication tokens to headers, logging, error handling, or modifying outgoing request data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'faf4021b-ef67-470c-aaaf-ebc5297cf976', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What does the ''@apply'' directive do?', N'Intern', N'The @apply directive allows you to extract common utility patterns into a single custom class name in your CSS. It is useful for reducing repetitive code when you have the same set of utilities applied to many elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73ac08ea-4c64-43f8-ba40-ebc9a73b7955', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the role of Middleware in AdonisJS?', N'Fresher', N'Middleware are functions that run during the request-response cycle before the final route handler. They are commonly used for tasks like authenticating users, logging requests, or modifying input data before it reaches the controller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2d43e0ca-8113-43bf-934e-ebcc1be1f7fa', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the difference between list and tuple?', N'Fresher', N'Lists and Tuples are ordered sequences in Python, but they differ significantly in mutability, performance, and storage behavior. Key Distinctions - Mutability: Lists are mutable, meaning elements can be added, removed, or modified after creation. Tuples are immutable; their structure and references cannot be changed once instantiated. - Memory & Performance: Tuples have a lower memory footprint. Lists utilize over-allocation to facilitate $O(1)$ amortized time for append() operations, whereas tuples are allocated the exact amount of memory required. Consequently, tuples are faster to create and slightly faster to iterate over. - Hashability: Because they are immutable, tuples (containing only hashable elements) are hashable and can be used as dictionary keys or set elements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4416066b-be82-4b72-b636-ebcea8a5f837', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of a ''loader'' in Webpack?', N'Junior', N'Loaders allow Webpack to process and transform files other than standard JavaScript, such as CSS, images, or TypeScript files. By using loaders, Webpack can convert these non-JavaScript files into valid modules that can be included in your application''s dependency graph.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76675030-4b6f-4fc2-9ac4-ebcfcbe7e0f1', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the benefit of the AdonisJS ''Hook'' system in models for complex business rules?', N'Senior', N'Hooks allow for the execution of logic at specific points in a model''s lifecycle, such as before saving or after deleting. This centralizes data integrity rules within the model, ensuring they are executed regardless of which controller triggered the operation, thus maintaining consistent data state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89dbfe2b-d32c-4296-be32-ebd07d3f2a33', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How does testing coverage impact development speed trade-offs?', N'Intern', N'High test coverage slows down the initial development process but significantly increases the speed and safety of future changes. The trade-off is a slower start for the benefit of a more stable and faster-moving project in the long term.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c76719b8-d3ee-4fa9-8ced-ebd43d1e5cf5', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'Describe the concept of ''CQRS'' and when it is appropriate to use.', N'Senior', N'CQRS (Command Query Responsibility Segregation) separates the read and write models of an application, often using different data schemas or storage technologies for each. It is ideal for systems with complex domain logic or highly asymmetric read/write loads, though it introduces significant complexity regarding data synchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74a1f6e1-7912-4f78-b6e3-ebd7d6a89239', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'When building a highly scalable service, why might you choose to bypass Fastify''s built-in logging system for an external observability platform?', N'Senior', N'While Fastify''s Pino-based logger is highly optimized, offloading log processing to external sidecars or agents can reduce the I/O burden on the main event loop. This is critical in high-traffic scenarios where synchronous logging overhead could induce latency spikes or impact throughput.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'560ca267-169e-4709-b5c2-ebd99764ca09', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'How Does the Event Loop Work?', N'Fresher', N'1. Initialization: When Node.js starts, it initializes the event loop to watch for I/O operations and other asynchronous tasks. 2. Queueing: Any task or I/O operation is added to a queue, which can be either the microtask queue or the macrotask/Callback queue. 3. Polling: The event loop iteratively checks for tasks in the queue while also waiting for I/O and timers. 4. Execution Phases: When the event loop detects tasks in the queue, it executes them in specific phases, ensuring order efficiency. Task Scheduler Zones: microtask and Callback Queue - Microtask Queue: This is a highly prioritized queue, usually acting over tasks in the Callback Queue. Useful for tasks that require immediate attention.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a322bdb1-3077-46a7-bfdb-ebda39a1dafe', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'How does Go handle multi-threading?', N'Intern', N'Go handles multi-threading through the scheduler, which multiplexes many Goroutines onto a smaller number of OS threads. This abstraction allows developers to write concurrent code without managing thread lifecycles manually.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a46c4d9-6dca-46af-9955-ebdc00c9323c', N'8a4da180-cd1d-4acd-8bc3-651f11abd04c', N'What are the implications of large item sizes on performance and cost?', N'Senior', N'Items are limited to 400KB in size, and exceeding this requires splitting the data into multiple items or storing it in S3 with a pointer in DynamoDB. Large items consume more throughput per operation, increasing costs and latency. Efficient design usually involves keeping items small and splitting large objects to maintain consistent performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6b61fe3f-c565-4355-aa8d-ebdc1aad7bca', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the ''any'' type in TypeScript?', N'Intern', N'The ''any'' type tells the TypeScript compiler to stop checking the type of a variable. It effectively opts out of type safety, allowing the variable to hold any value and perform any operation, which should be avoided when possible.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'58a86d60-2ca7-4b27-bad7-ebdc9eab054e', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'When would you prefer an asynchronous message queue over a synchronous REST call for system reliability?', N'Senior', N'Asynchronous communication decouples services, allowing the system to buffer requests during traffic spikes. This increases reliability by ensuring that the failure of a downstream service does not immediately crash the upstream caller.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'27e938d1-46e3-4bf5-8444-ebdd90a8cb20', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'Explain your approach to estimating the availability impact of a major database schema migration on a live system.', N'Senior', N'I would analyze the lock contention duration for the specific migration steps and assess the rollback strategy''s complexity to determine the potential downtime window. By simulating the migration in a staging environment that mirrors production load, I can generate a statistically sound estimate of the performance degradation and service unavailability risk.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
