INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dad045d-a69f-4c47-b599-ebe0ed0a4f3a', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact manage state and hooks differently than React?', N'Middle', N'Preact''s implementation of hooks is built into the core rather than being a separate addition, which helps keep the bundle size small. While the API for hooks like useState and useEffect is identical to React, the underlying state management is optimized for Preact''s specific rendering lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
