INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6c7b14d9-6963-487a-b7f4-ebe7b112080e', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What does ''tree shaking'' mean in Webpack?', N'Fresher', N'Tree shaking is a term for dead-code elimination. Webpack analyzes your code to identify and remove unused exports, ensuring that the final bundle only contains the code that is actually being used by the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dec1ca3-e99e-41de-91ba-ebe7cfb6eb99', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does MySQL handle auto-increment columns?', N'Junior', N'An auto-increment column automatically generates a unique sequence number for every new row inserted into the table. This is commonly used for primary keys to ensure that every record has a distinct and sequential identifier.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe3596a4-b3bf-45be-9425-ebe86ed0ddbc', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What is the purpose of the FromForm trait in Rocket?', N'Junior', N'The FromForm trait allows Rocket to automatically parse incoming HTML form data or query parameters into a struct. This simplifies the process of extracting and validating user input without manual parsing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31835684-3775-4808-abd8-ebe973fc54bc', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'In what scenarios would an architect prefer R''s RC (Reference Classes) over S4?', N'Senior', N'RC is preferred when the application requires mutable state and encapsulation similar to traditional object-oriented languages like Java or C++. Unlike S4, which is functional and immutable, RC allows for in-place modifications to objects, which is more efficient for large-scale simulations or managing complex system state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'729df51f-2cf9-4d73-a120-ebedd3f66ffb', N'075b8862-431c-4678-9767-f55359758a4a', N'How does Vue''s reactivity system handle nested object tracking differently in version 2 versus version 3?', N'Senior', N'Vue 2 used Object.defineProperty to intercept property access, which required manual handling for adding new properties or array indexing. Vue 3 utilizes ES6 Proxies, allowing the system to observe deep mutations, property additions, and array index changes automatically without additional helper methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1c62c93f-427e-45c2-aeb3-ebf0cee15917', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What are the advantages of using NestJS''s ''Application Context'' in standalone scripts or background workers?', N'Senior', N'The Application Context allows developers to leverage the full DI system, configuration services, and database providers in environments outside of the standard HTTP request-response cycle. This ensures that cron jobs, CLI commands, and message consumers share the same codebase, logging, and dependency management as the main web server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'090d6f51-9189-4120-91fb-ebf203fcdc25', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'If you are assigned a task involving a technology you have never used before, what is your step-by-step approach to completing it?', N'Fresher', N'First, I would break down the task into smaller, manageable components to identify the core requirements. Then, I would consult official documentation and reliable tutorials to understand the fundamental concepts of the new technology. Finally, I would create a small prototype or proof-of-concept to validate my understanding before proceeding with the actual implementation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb04966e-6d2e-4c1f-8f92-ebf278cda29e', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How do you handle pagination and sorting in Spring Data JPA?', N'Middle', N'Spring Data JPA repositories can accept a Pageable parameter in query methods, which automatically handles offset and limit logic. This built-in support simplifies the implementation of paginated data access without needing to write custom SQL queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'80b0a3e4-84b9-4eaf-ad75-ebf4679b05a2', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'How does Micronaut handle property binding and configuration?', N'Middle', N'Micronaut uses a type-safe configuration system that maps external properties from YAML, properties files, or environment variables directly into POJOs. It supports property injection through constructors or setters and validates configuration types during the startup phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4015aa0-9156-4317-9ee9-ebf602ad2322', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What is the primary advantage of Preact''s small size for mobile users?', N'Junior', N'The small size results in faster download and parse times, which significantly improves the initial load speed on mobile devices with slow or unstable network connections. This improves the user experience by reducing the time to first interactive paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0d489fc-01ee-4953-ada6-ebf7234da5c9', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does the ''strict'' flag in the tsconfig file affect your development process?', N'Junior', N'The ''strict'' flag enables a wide range of type-checking behaviors that ensure stronger correctness in your code. Enabling it forces you to handle potential null or undefined values explicitly and prevents implicit ''any'' types, leading to more robust applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20b35a10-367b-402a-8a42-ebf984e91e7e', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What is the difference between a monolithic and a microservices architecture?', N'Intern', N'A monolith is a single unified unit where all components are tightly coupled, making it easier to deploy initially but harder to scale. Microservices break the application into independent, loosely coupled services, which improves scalability and fault isolation but increases operational complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'90350d44-85f7-4b3a-8833-ebfd1ef3a55a', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is a bundle?', N'Intern', N'A bundle is the final file or set of files produced by Webpack after it has processed all the modules in your project. It contains all the necessary code, including dependencies and assets, packaged together for the browser to run.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51b841fd-9075-49b8-8185-ec00b9594efe', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is Authentication in ASP.NET Core?', N'Fresher', N'Authentication is the process of identifying who a user is. ASP.NET Core provides a flexible framework to handle various authentication methods, such as cookies, JWT tokens, and external providers like Google or Microsoft.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f916bcb8-a8b5-4697-9f83-ec00ec45e1dd', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the purpose of the ''teleport'' component?', N'Middle', N'Teleport allows you to render a component''s template in a different part of the DOM tree, outside the current parent component hierarchy. It is commonly used for modals, tooltips, and notifications to avoid issues with CSS layering, z-index, or overflow hidden constraints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3f40f82-594b-463b-8619-ec048673c3a5', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What are the trade-offs of using wide-column stores versus document stores?', N'Middle', N'Wide-column stores excel at handling massive datasets with sparse data and high write throughput, similar to a multi-dimensional map. Document stores offer more flexibility for hierarchical data and complex querying on nested structures at the cost of potential query complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3b91109d-d7f4-4907-9bf2-ec06ed350689', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono’s validator middleware differ from schema-based validation libraries like Zod?', N'Senior', N'Hono provides an interface for validation that integrates directly into the request lifecycle, while Zod acts as the schema definition layer. Hono does not reinvent validation but provides a bridge to use tools like Zod to parse and validate incoming data, ensuring that invalid requests are rejected before reaching business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
