INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5cb56fb3-ead8-4e45-a251-ec0878b7b8b3', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the MVC pattern in Ruby on Rails?', N'Junior', N'MVC stands for Model-View-Controller. It separates the application into three components: the Model manages data and business logic, the View handles the user interface, and the Controller acts as an intermediary that processes requests and coordinates between the Model and the View.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0031174c-04b6-4581-a3cc-ec0bf42761e3', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the purpose of the ''inherit'' keyword in CSS?', N'Junior', N'The inherit keyword forces an element to take the computed value of a property from its parent element. This is useful for ensuring that child elements stay consistent with parent styles, even for properties that do not inherit by default.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'745e8135-a922-4f1c-b0f2-ec0c892054b8', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the role of the ''process.nextTick'' queue compared to ''setImmediate''?', N'Senior', N'process.nextTick executes immediately after the current operation completes, regardless of the current phase of the event loop, effectively prioritizing it over other tasks. setImmediate schedules a task to run in the check phase of the event loop. Overusing nextTick can starve I/O and prevent the event loop from moving to the next phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0bd14148-fec6-4880-aeeb-ec0e4cc0a87f', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the best practices for security in angular?', N'Senior', N'Below are the best practices of security in angular, 1. Use the latest Angular library releases 2. Don''t modify your copy of Angular 3. Avoid Angular APIs marked in the documentation as “Security Risk.”', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f45b29b9-30c0-4200-a7c5-ec0ead86bc00', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the benefit of using ''Read Preference: secondaryPreferred''?', N'Senior', N'This read preference allows applications to offload read operations to secondary nodes, reducing the load on the primary node. It is ideal for read-heavy applications where slight data replication lag is acceptable in exchange for higher throughput and scalability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b49e8f9c-1627-43c2-a533-ec1021935f74', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Contrast the use of consistency levels LOCAL_QUORUM and EACH_QUORUM in a multi-datacenter deployment.', N'Senior', N'LOCAL_QUORUM ensures consistency within the local datacenter, providing lower latency, while EACH_QUORUM requires acknowledgment from a majority of replicas in every datacenter. EACH_QUORUM offers stronger global consistency but significantly increases write latency due to cross-datacenter network round-trips.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1da5c92b-b37d-4474-ac0c-ec102d0d3238', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'How do you manage database connection pools in an Axum application?', N'Middle', N'Database pools are usually wrapped in an ''Arc'' and passed through the application state. By injecting the pool as a shared resource, handlers can acquire connections dynamically as needed, ensuring efficient resource management across the request lifecycle.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd849e7f7-300e-4425-af54-ec11343f108c', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is the role of the ''static'' folder in SvelteKit?', N'Intern', N'The static folder is used to store files that should be served exactly as they are, such as images, fonts, or robots.txt files. These assets are not processed by the build system and are served directly from the root of your domain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e47d33a-f10a-46a4-8a7e-ec13d96f3e9d', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the core concept of Resumability in the Qwik framework, and how does it differ from traditional Hydration?', N'Junior', N'Resumability allows the application to become interactive without downloading or executing the entire JavaScript bundle on load. Unlike traditional hydration, which requires re-running component logic to attach event listeners, Qwik pauses execution on the server and resumes it in the browser exactly where it left off by loading only the necessary code chunks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'94f378b3-9394-4877-95bb-ec152ec3520b', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is Cassandra considered ''schema-optional'' compared to SQL databases?', N'Junior', N'While Cassandra requires a defined schema for tables, it is more flexible than relational databases because it supports sparse columns. You do not need to store values for every column in a row, and you can add new columns without affecting existing records.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df5bcddc-b528-4492-9e0c-ec155daf01ff', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI support security and authentication?', N'Intern', N'FastAPI provides built-in tools for handling authentication, such as OAuth2 with JWT tokens and API keys. These tools integrate seamlessly with the dependency injection system to secure specific endpoints.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74eb2a63-e592-4727-830e-ec17211da56e', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is the Least Recently Used (LRU) eviction policy generally preferred over First-In-First-Out (FIFO)?', N'Middle', N'LRU is preferred because it exploits the principle of temporal locality, assuming that data accessed recently is likely to be accessed again soon. FIFO ignores access patterns and may evict frequently used items simply because they were loaded earlier, leading to a higher miss rate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'84cd840b-7c56-4c85-ad19-ec1c5899b3c2', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What does ''composable'' mean in the context of Chi?', N'Intern', N'Composable means that the router allows you to build complex applications by nesting routers or combining middleware in a modular fashion. You can define small, independent route groups and merge them together into a single application structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9128ac53-dcf0-4c20-8358-ec207c875822', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'How do you decide between using a relational database and a NoSQL store for a new service?', N'Middle', N'I analyze the data structure and access patterns. If the data has rigid, complex relationships that require ACID compliance, I prefer a relational database. If the data is highly unstructured, requires massive horizontal scale, or needs flexible schemas, I opt for a NoSQL solution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8d1c95cf-f3be-478a-8d8f-ec2481e20486', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the role of the Svelte compiler during the build process?', N'Middle', N'The compiler analyzes your code during build time to determine which parts of the component are dynamic and need to be updated. It generates highly optimized, vanilla JavaScript that performs updates without needing a runtime reconciliation process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b68dec9-78ba-4259-8901-ec2987bc8c8b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'When a task is behind schedule, how do you communicate this to your manager?', N'Fresher', N'I would communicate the delay as early as possible, explaining the specific technical blockers causing the delay. I would also offer a revised timeline and propose a plan to prioritize essential features to ensure we meet the most important project goals.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a50705ad-042e-4507-9ed1-ec29c7b2434e', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is the difference between Flask and a full-stack framework like Django?', N'Intern', N'Flask is a micro-framework that provides only the core tools for web development, leaving architectural decisions to the developer. Django is a full-stack framework that comes with a built-in ORM, admin panel, and authentication system, following a ''batteries-included'' philosophy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f602fc8e-4440-42f0-8ba9-ec2cea1e90e5', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the difference between a process and a thread to a non-technical stakeholder?', N'Intern', N'A process is like an individual program running on a computer with its own dedicated memory space. A thread is a smaller unit of execution that lives inside a process, allowing multiple tasks to run simultaneously while sharing the same memory. You can think of a process as a house and threads as the people working on different tasks inside that same house.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39a14148-a6e1-44ca-87b7-ec2d191cf650', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Describe the concept of ''Time Travel Debugging'' and the underlying Redux mechanism that enables it.', N'Senior', N'Time travel debugging allows developers to jump between past and future states of the application. This is made possible because Redux treats every state change as a discrete transition triggered by an action, allowing the dev tools to replay the sequence of actions or revert to any previous state snapshot.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'244daff8-d45f-48db-9563-ec2eeb0a1993', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'How does Gin handle redirects?', N'Intern', N'Gin provides a helper method on the context object to perform HTTP redirects. This allows the server to send a response that instructs the client to navigate to a different URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2067ece0-bdea-413c-817d-ec2f35a97c08', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Why is the use of ''ALLOW FILTERING'' generally discouraged in production environments?', N'Senior', N'ALLOW FILTERING forces the coordinator node to scan all partitions to find matching data, which is an O(N) operation that can lead to timeouts and extreme cluster instability. It bypasses the primary partitioning mechanism and defeats the purpose of Cassandra''s high-performance query model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
