INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae683150-bb25-42f1-8718-ec42d467b399', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does the ''prototype chain'' work in JavaScript object lookup?', N'Middle', N'When a property is accessed on an object, the engine first checks the object itself; if not found, it traverses up the prototype chain until it reaches the end of the chain or finds the property. This mechanism supports inheritance but can introduce performance overhead if the chain is too deep.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'285bf8fa-6dce-4558-8f4d-ec4574bfe4d7', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How do you create a new MongoDB collection?', N'Fresher', N'The process for creating a new collection in MongoDB is simple and instantaneous. Benefits of Instantaneous Creation - MongoDB collections are schemaless, leading to immediate collection creation. - Document structure and content drive schema design. - No predefined schema requirements allow for dynamic, evolving data models. Steps to Create a Collection 1. Select the Database: Ensure you are connected to the intended database for the collection''s creation. Switch to the desired database using use in the mongo shell or select the database programmatically in your driver''s API. 2. Perform a Write Operation: The new collection is created the moment you execute a write operation such as insert, update, or save. 3.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'48d356b5-8a9e-4097-ac81-ec468dba4819', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a regression bug and how can it be avoided?', N'Intern', N'A regression bug is a new issue introduced by a change or a fix to an existing piece of functionality. These can be avoided by performing thorough regression testing whenever a change is made to ensure that previously working features remain stable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3306324b-1b65-4773-a5ca-ec469b8e3d89', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the trade-off between using synchronous and asynchronous replication in a distributed SQL system?', N'Senior', N'Synchronous replication ensures zero data loss by waiting for all replicas to acknowledge a write, but it increases latency and reduces system availability during network partitions. Asynchronous replication provides lower latency and higher availability but introduces the risk of data loss if the primary node fails before the latest changes propagate.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
