INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bef1cc38-5ac5-487d-b27d-ec5768704fd5', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your strategy for troubleshooting a memory leak in a long-running production service?', N'Middle', N'I would first capture heap dumps at different time intervals to compare object retention and identify which classes are growing monotonically. Then, I would analyze these snapshots to check for static collections or unclosed resources that prevent garbage collection, verifying the fix in a staging environment with load testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
