INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'741e750b-0863-473f-96a5-ec5bdd23c89f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Why might you choose a BRIN index over a B-tree index on a large table?', N'Middle', N'BRIN, or Block Range Indexes, are significantly smaller than B-tree indexes because they store the minimum and maximum values for blocks of pages rather than every row. They are ideal for very large tables where data is physically sorted or naturally sequential, providing massive storage savings with acceptable query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfeabdc9-67a7-489a-aac9-ec5ce1c639ca', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain how Webpack''s ''target'' option influences the generated bundle code.', N'Senior', N'The target option instructs Webpack to output code compatible with specific environments like Node.js or browsers. It adjusts built-in modules, chunk loading strategies, and global variable assumptions to ensure the resulting bundle executes correctly in the target runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'acfd69b8-7be1-4bbd-b7eb-ec5e2f9cb55b', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'Can you use multiple stores in a single Redux application?', N'Middle', N'While technically possible, it is highly discouraged. Redux is designed around the concept of a single store to maintain a predictable state tree and simplify debugging and state synchronization across the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'06a4cb96-9c33-4f99-adc4-ec5e799b9b47', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is Partition Tolerance in the CAP theorem?', N'Fresher', N'Partition Tolerance means the system continues to operate despite arbitrary message loss or failure of part of the system. In distributed databases, this is essential as network failures are inevitable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fca81f0-11a0-4193-ab7d-ec5f906096f2', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is the YAML configuration format used for in Symfony?', N'Fresher', N'YAML is a human-readable data serialization format used in Symfony to define application settings, routing rules, and service configurations. It provides a clean and organized way to manage settings without using complex PHP arrays or XML.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95fb0046-5cb0-42e3-af7d-ec5fa0c1b769', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the significance of the ''app'' folder in an Ember project?', N'Fresher', N'The ''app'' folder is the core directory where all your application code lives, including components, routes, models, and services. Ember CLI uses the structure within this folder to automatically register and organize your resources.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0de1ccf-ce75-47ed-b472-ec60ef8ddde8', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What happens when a route''s ''model'' hook returns a promise?', N'Middle', N'The Ember router pauses the transition until that promise resolves. If the promise is rejected, it triggers an error state, which can be caught by an error route to display an appropriate message to the user, preventing the application from entering an invalid state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'76e957fd-6d4b-42ef-bdfa-ec641435e131', N'075b8862-431c-4678-9767-f55359758a4a', N'What is the difference between ''emits'' and ''props''?', N'Middle', N'Props are the mechanism for parent-to-child data flow, allowing parents to configure children. Emits are the mechanism for child-to-parent communication, allowing children to notify parents of events that have occurred.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a9a6fa7f-1cf4-4fdd-962a-ec6631b6c5c4', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'How does the ''override'' keyword improve code quality?', N'Middle', N'The ''override'' keyword ensures that a virtual function in a derived class is actually overriding a base class virtual function. If the signatures do not match, the compiler will issue an error, preventing accidental creation of a new function instead of an intended override.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'31c8c80a-4b53-40d1-a472-ec67462fbc19', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is tree shaking', N'Intern', N'Tree shaking is a form of dead code elimination. It means that unused modules will not be included in the bundle during the build process and for that it relies on the static structure of ES2015 module syntax,( i.e. import and export). Initially this has been popularized by the ES2015 module bundler rollup, these days practically all bundlers use this technique.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2c305eab-fd30-4be0-945e-ec6d1dbb1722', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'What is the purpose of the ''Vert.x'' integration in Quarkus?', N'Middle', N'Vert.x provides the reactive foundation for Quarkus, enabling non-blocking, event-driven I/O operations. It allows Quarkus to handle high concurrency with a low number of threads, which is essential for building scalable microservices that remain performant under heavy load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fb52c28-d85d-42d8-8a5a-ec6e2a27bc09', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'Discuss the trade-offs of using Express for a high-concurrency microservice versus an event-driven architecture like NestJS or Go.', N'Senior', N'Express is minimalist and relies on a blocking event loop for heavy computation, which can lead to event loop lag. While sufficient for I/O-bound tasks, high-concurrency services often require vertical scaling or delegation to worker threads, whereas Go''s concurrency model handles high throughput more efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd753d19-483d-4c4a-bd45-ec6ed999b28b', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is an HTTP Response object in Symfony?', N'Intern', N'A Response object represents the HTTP output sent back to the client, including headers, the content body, and the status code. It provides a standardized way for the controller to communicate the result of a request to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aa0fa88f-80e9-4581-b615-ec7015eeb3d0', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the primary trade-off of using a monolithic NestJS architecture versus Microservices?', N'Middle', N'A monolith is simpler to deploy and maintain but can become a bottleneck as the codebase grows. Microservices offer better scalability and independent deployment but introduce complexity regarding inter-service communication and distributed tracing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4aebffde-1614-4407-9d8e-ec71f6b66511', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What is a Case Class, and why is it useful?', N'Intern', N'A case class is a special type of class that is optimized for use in pattern matching and immutable data modeling. The compiler automatically generates useful methods like equals, hashCode, and a constructor-based pattern extractor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'832742d2-c16b-4a32-8c4d-ec73d2557794', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'Why might a developer choose a database with ''Eventual Consistency''?', N'Middle', N'Developers choose eventual consistency to maximize performance and availability in distributed systems. It allows the system to remain responsive even during network partitions, acknowledging that data replicas will converge to a consistent state after a short period.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f899e0f-670c-47dc-a0a2-ec758067d954', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why should you avoid global variables in your design?', N'Fresher', N'Global variables can be modified from anywhere in the application, making it extremely difficult to track down bugs or predict the state of the system. This practice creates hidden dependencies between unrelated parts of the code, making the system fragile and harder to test.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30f2e469-3e7e-426b-bd11-ec7607e3f88b', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you handle long-running background tasks to ensure they don''t impact the performance of the main application?', N'Senior', N'I would offload these tasks to a separate worker pool, utilizing a durable task queue to manage scheduling and prioritization. By isolating the background workload from the request-response cycle, the system maintains high responsiveness and allows for independent scaling of workers based on queue depth.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd50b0aba-ae8c-495b-8273-ec779f7f3a10', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Actix handle routing?', N'Fresher', N'Routing in Actix is the process of mapping a specific URL pattern and HTTP method to a designated handler function. You define these mappings in the App configuration, and Actix uses this configuration to direct incoming traffic to the correct business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07425c3e-b501-414c-9743-ec77b896ec7d', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'What is a SvelteKit adapter?', N'Intern', N'An adapter is a small plugin that tells SvelteKit how to build your application for a specific deployment environment. It transforms the project into a format compatible with platforms like Vercel, Netlify, or a standard Node.js server.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a501d41-8da5-47cd-999a-ec7a7aa7195e', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is a REST API in the context of Elasticsearch?', N'Intern', N'Elasticsearch exposes a RESTful API that allows users to interact with the cluster using HTTP methods like GET, POST, PUT, and DELETE. This makes it accessible from any programming language via standard web requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'715372ab-8c97-4f3d-8c17-ec7aa702266b', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''extension'' system provide modularity without modifying original source code?', N'Senior', N'Extensions provide a way to add functionality to existing classes without subclassing or modifying the original definition. This preserves the original class''s API while allowing developers to inject domain-specific logic, promoting composition over inheritance and keeping the class hierarchy clean.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aaa5e42b-a5ca-4273-915e-ec7c7a60892a', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'Explain the purpose of the ''var/cache'' directory.', N'Junior', N'This directory stores compiled versions of the application, including service definitions, configuration, and generated template files. Clearing this directory forces Symfony to re-parse the configuration, which is a common troubleshooting step when changes do not appear to take effect.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a3f26fd-ad9b-405b-9a51-ec7d50ddcd5e', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What are JavaScript polyfills for?', N'Intern', N'Polyfills in JavaScript are pieces of code that provide modern functionality to older browsers that lack native support for those features. They bridge the gap between the JavaScript language features and APIs available in modern browsers and the limited capabilities of older browser versions. They can be implemented manually or included through libraries and are often used in conjunction with feature detection. Common use cases include: - New JavaScript Methods: For example, Array.prototype.includes(), Object.assign(), etc. - New APIs: Such as fetch(), Promise, IntersectionObserver, etc. Modern browsers support these now, but for a long time they had to be polyfilled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62715811-5074-4adc-9393-ec88ec4334d4', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'Why would you choose to use HTTPS instead of HTTP for a web application even if it does not handle payments?', N'Fresher', N'HTTPS encrypts the communication between the client and the server, protecting user data from being intercepted or tampered with. It also provides authentication to ensure the user is connected to the legitimate website. Using HTTPS is essential for building trust and protecting user privacy in all web interactions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'43393cc8-aee7-40d7-9042-ec89bfddd281', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'How does SolidJS handle reactivity compared to React?', N'Intern', N'Unlike React, which re-renders components when state changes, SolidJS tracks state dependencies. It only updates the specific parts of the DOM that depend on the changed state, avoiding unnecessary re-renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'64257b4e-bc25-40ab-94ef-ec89f13d3915', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between the WHERE and ON clauses in a JOIN?', N'Junior', N'The ON clause specifies the condition for joining two tables. The WHERE clause is used to filter the final result set after the join has been performed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28a4cbb9-d37b-4a3a-a7bb-ec8aee065726', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the purpose of the Startup class or Program.cs configuration in ASP.NET Core?', N'Intern', N'These files are the entry point for the application where the server is configured and the request pipeline is defined. They are used to register services in the dependency injection container and to specify how the application handles HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'217aeead-631f-4381-8a17-ec8b73d94941', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What are the trade-offs of using Entity Framework Core compared to Dapper?', N'Middle', N'Entity Framework Core is an Object-Relational Mapper that simplifies database interactions with strong typing and change tracking, but it can introduce performance overhead. Dapper is a micro-ORM that provides much higher performance by executing raw SQL, but it requires more manual effort to map results and handle complex queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5e21fbf-7184-4b3f-b7ba-ec8c3fc43f80', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How do you define a status code for a route in Litestar?', N'Junior', N'You can define the status code by using the ''status_code'' parameter in the route decorator. If not specified, Litestar defaults to standard codes like 200 for successful operations or 201 for resource creation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab9c9c11-deb1-4366-a0b4-ec8f6fe78471', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'How does Webpack handle modules without a configuration file?', N'Intern', N'Webpack has a default configuration that works for simple projects by assuming an entry point of ''src/index.js'' and an output of ''dist/main.js''. However, most real-world applications require a configuration file to handle specific loaders and complex build requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12b20125-dba4-48e6-a4df-ec902a326390', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between ''em'' and ''rem'' units?', N'Intern', N'The ''em'' unit is relative to the font size of the element''s parent, which can lead to compounding effects. The ''rem'' unit is relative to the root element''s font size, making it more predictable throughout the document.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26734585-0a2f-4b14-b416-ec903463695c', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the difference between a WHERE clause and a HAVING clause?', N'Fresher', N'A WHERE clause filters rows before any groupings are performed. A HAVING clause is used to filter groups of data after the GROUP BY operation has been applied.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'365d840b-8128-4572-8250-ec9080a7c699', N'954a0331-deff-4399-b588-96f39fec001d', N'What are the Route Parameters? Could you explain each of them?.', N'Intern', N'Route parameters are used to pass dynamic values in the URL of a route. They allow you to define variable segments in the route path, which can be accessed and used by components and services. Path parameters are represented by a colon (":") followed by the parameter name. There are three types of route parameters in Angular: Path parameters: Path parameters are used to define dynamic segments in the URL path. They are specified as part of the route''s path and are extracted from the actual URL when navigating to that route. Path parameters are represented by a colon (":") followed by the parameter name. For example: In this example, ":id" is the path parameter. When navigating to a URL like "/users/123", the value "123" will be extracted and can be accessed in the UserComponent.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed915dca-4fa8-4044-a908-ec916a0d4e32', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Explain the difference between S3 and S4 object systems in terms of dispatch and validation.', N'Senior', N'S3 is a dynamic, informal system based on naming conventions and list attributes, offering flexibility at the cost of strict structure. S4 is a formal system requiring explicit class definitions, method signatures, and strict validation, making it more suitable for complex, enterprise-grade architectures where consistency is paramount.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1fabc95c-bbda-403e-a784-ec931eea62f9', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'Why is autoloading preferred over manual file inclusion?', N'Middle', N'Autoloading improves performance and maintainability by only loading class files when they are actually instantiated. This avoids the overhead of including massive amounts of unused code and removes the need for complex, manual file management chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63fb1883-2c1c-479d-ba9d-ec9620ab2311', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is the purpose of ''children'' in SolidJS?', N'Intern', N'The ''children'' property allows a component to receive and render elements passed to it from a parent component. It is a fundamental way to build reusable layout components or wrappers.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2305eaac-84f5-4db4-99e4-ec975d2315d1', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What happens when you raise an exception inside a ''finally'' block?', N'Middle', N'If an exception is raised in a ''finally'' block, it will override any exception that was previously raised in the ''try'' or ''except'' block. This can mask the original error, so it is generally recommended to avoid raising exceptions within ''finally'' blocks unless necessary for cleanup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79e8bb56-577e-4b37-aab1-ec9871a0fc1c', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the difference between @Body(), @Query(), and @Param() decorators?', N'Junior', N'@Body() extracts the data sent in the request body, @Query() accesses the URL query parameters after the question mark, and @Param() retrieves dynamic route parameters defined in the URL path.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'20c9a9d6-aceb-4dca-a1a5-ec98c152d1e9', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the significance of the ''fillfactor'' parameter in index and table storage.', N'Senior', N'Fillfactor determines how much of a page is filled with data, leaving the remainder as free space for updates. A lower fillfactor allows for more HOT updates and fewer page splits, reducing bloat at the cost of increased disk storage usage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'591dc78e-09de-44cf-be23-ec9b49b81696', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are the architectural benefits of using ''Pods'' or ''Classic'' structure in an Ember project?', N'Senior', N'Pods group related files like templates and components together, which improves developer productivity by reducing context switching. Classic structure separates files by type, which can be easier for newcomers to navigate but may become cumbersome as the application grows in complexity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'df143d00-334d-483c-8ea1-ec9c81b27505', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is declaration merging?', N'Intern', N'Declaration merging is a process where the compiler merges two or more separate declarations with the same name into a single definition. This is most commonly used to extend interfaces across different files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce446588-d4e4-4007-8dda-ec9f39b7ecf1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the possible return types of render method?', N'Intern', N'Below are the list of following types used and return from render method, 1. React elements: Elements that instruct React to render a DOM node. It includes html elements such as and user defined elements. 2. Arrays and fragments: Return multiple elements to render as Arrays and Fragments to wrap multiple elements 3. Portals: Render children into a different DOM subtree. 4. String and numbers: Render both Strings and Numbers as text nodes in the DOM 5. Booleans or null: Doesn''t render anything but these types are used to conditionally render content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bcbf1f24-29e9-4307-9344-eca191faed9a', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'How does R’s lexical scoping mechanism interact with its closure implementation, and what are the potential scalability risks of this design?', N'Senior', N'R uses lexical scoping where functions maintain an environment containing the variables present when they were defined, effectively creating closures. While this facilitates powerful functional programming patterns, it can lead to memory leaks in long-running processes because the entire environment remains in scope as long as the closure exists. Architects must be cautious when creating closures within loops or iterative processes, as they can inadvertently pin large objects in memory that would otherwise be eligible for garbage collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fb7a8466-358c-437b-9e23-eca46c16cb0a', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'When should you use an API Gateway in a microservices architecture?', N'Middle', N'An API Gateway should be used when you need a single entry point to abstract the internal complexity of multiple microservices. It is essential for centralizing cross-cutting concerns like authentication, SSL termination, request routing, and rate-limiting, which would be inefficient to implement in every individual service.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fa7f5e5e-bf18-4f42-8845-eca7715ddf1e', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo handle JSON serialization?', N'Junior', N'Echo provides a built-in JSON method on the context object that automatically marshals Go structs into JSON format and sets the correct Content-Type header. This eliminates the need for manual marshalling and header setting for every response.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97484b70-6952-4189-8369-eca7839b67ec', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle type inference?', N'Intern', N'Type inference is the process where the TypeScript compiler automatically determines the type of a variable when an explicit annotation is not provided. It bases this on the value assigned to the variable at the time of declaration.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ed234fcf-2a92-4008-ba76-eca9161697c4', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What is useCallback and why is it used?', N'Intern', N'The useCallback is a React Hook used to memoize function definitions between renders. It returns the same function reference unless its dependencies change. This is especially useful when passing callbacks to optimized child components (e.g. those wrapped in React.memo) to prevent unnecessary re-renders. Example: Without useCallback, a new function is created on every render, potentially causing child components to re-render unnecessarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26fe2d1b-14d2-45f5-b078-ecaf1d94e60d', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'What does ''type safety'' mean in the context of Rocket?', N'Fresher', N'Type safety means that the framework leverages Rust''s compiler to ensure that the data you receive in a request matches the data types your functions expect. This catches errors at compile-time rather than at runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a47ddf33-48d4-4b4c-a8cb-ecb07c85c920', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is a functional interface in Java?', N'Middle', N'A functional interface is an interface that contains exactly one abstract method. These interfaces act as targets for lambda expressions, enabling a more concise and declarative style of programming in Java.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'55ac0565-2586-4a0a-9d09-ecb1e706d0c6', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''tombstone'' in the context of NoSQL databases?', N'Middle', N'A tombstone is a marker used in log-structured storage engines to indicate that a specific record has been deleted. Since data is often immutable, the tombstone prevents deleted records from being returned in query results until a compaction process physically removes the data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24f95d28-a54d-4208-ba86-ecb77c9d36d6', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the ''NoRoute'' handler in Echo?', N'Intern', N'The NoRoute handler is triggered when a client requests a URL that does not match any defined routes. It allows you to return a custom 404 Not Found response to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd449262-59c3-44da-8f2a-ecb7c6d78f92', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the primary trade-off when using an immutable state management pattern in Dart?', N'Middle', N'Immutable state ensures that application state cannot be modified unexpectedly, making debugging and state tracking much easier. The trade-off is the overhead of constantly creating new objects instead of mutating existing ones, which requires careful management to avoid excessive garbage collection pressure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd5f47df1-98fa-4825-903a-ecba57ace29f', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'How does Vite''s ''worker'' support enable multi-threaded execution?', N'Senior', N'Vite treats files with query parameters like ?worker as entry points to spawn separate web workers. It automatically bundles the worker logic into a separate file, allowing for off-main-thread computation without complex manual setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8af9cb02-3b00-47ef-8c6e-ecbb675b6063', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the Global Interpreter Lock (GIL)?', N'Intern', N'The GIL is a mutex that protects access to Python objects, preventing multiple threads from executing Python bytecodes at once. It ensures that only one thread executes in the interpreter at any given time, even on multi-core processors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
