INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'431fac95-a588-4614-9f8f-ecd045046b65', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between ''call'', ''apply'', and ''bind''?', N'Junior', N'All three are used to set the ''this'' context for a function. ''call'' and ''apply'' execute the function immediately with provided arguments, whereas ''bind'' returns a new function with the ''this'' context permanently set.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e4feb7ca-bbc7-4128-b9c9-ecd09f00102f', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What are the middleware functions in Node.js?', N'Intern', N'Middleware functions are functions that have access to the request object (req), the response object (res), and the next function in the application''s request-response cycle. Middleware functions can perform the following tasks: * Execute any code. * Make changes to the request and the response objects. * End the request-response cycle. * Call the next middleware in the stack. If the current middleware function does not end the request-response cycle, it must call next() to pass control to the next middleware function. Otherwise, the request will be left hanging. The following figure shows the elements of a middleware function call: Middleware functions that return a Promise will call next(value) when they reject or throw an error.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d7bef15-8834-4a07-a68e-ecd2818095e7', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to keep message processing non-blocking?', N'Junior', N'Since actors run on a shared event loop, blocking the thread prevents the actor from processing other messages or tasks. This can lead to system-wide latency, reduced throughput, and potential deadlocks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a4bec285-aa13-4a3e-a188-ecd287918a88', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'How does Litestar''s approach to OpenAPI generation improve developer velocity in large-scale systems?', N'Senior', N'Litestar generates OpenAPI specifications dynamically based on type annotations and method signatures, eliminating the need for manual documentation maintenance. This ensures that the documentation is always in sync with the codebase, which is critical for maintaining consistency in distributed systems where frontend and backend teams rely on automated contract testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c5caf17f-58d6-478f-8336-ecd39c4b4463', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Explain the architectural risks of using jQuery''s $.ajax compared to the modern Fetch API.', N'Senior', N'jQuery''s $.ajax is a wrapper that forces an older Deferred implementation, which predates the standardized Promise/A+ specification. Using native Fetch allows for better integration with service workers, streaming requests, and standard async/await patterns without the bloat of an external library.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca93bfed-7ea6-491a-8fe4-ecd3e71d8be2', N'954a0331-deff-4399-b588-96f39fec001d', N'What is an optional dependency?', N'Intern', N'The optional dependency is a parameter decorator to be used on constructor parameters, which marks the parameter as being an optional dependency. Due to this, the DI framework provides null if the dependency is not found. For example, If you don''t register a logger provider anywhere, the injector sets the value of logger(or logger service) to null in the below class.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'24233ca9-0604-4a23-8fb8-ecd5413d8e05', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a WSGI server and why is it used with Flask?', N'Junior', N'WSGI stands for Web Server Gateway Interface, which acts as a bridge between the web server and the Flask application. It is necessary because Flask''s built-in development server is not secure or performant enough for production environments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8c19fe4-caff-481b-a244-ecd55accb13d', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'Explain the architectural trade-offs of using Phoenix Channels versus standard HTTP polling or long-polling.', N'Senior', N'Phoenix Channels utilize WebSockets to provide full-duplex communication, significantly reducing latency and server overhead by eliminating repeated HTTP handshakes. While polling consumes resources through constant request-response cycles, Channels maintain a persistent stateful connection, making them superior for real-time applications but requiring careful management of connection state and memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
