INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ec82ea1-417d-4ded-92cd-ecde3b667914', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the event loop in JavaScript?', N'Intern', N'JavaScript is single-threaded — it can execute only one task at a time. The event loop is the mechanism that allows JavaScript to perform non-blocking I/O operations (like network requests and timers) despite this single-thread constraint. How it works: 1. Synchronous code runs on the call stack first. 2. Async operations (e.g. setTimeout, fetch) are handed off to Web APIs. 3. When complete, their callbacks are pushed to a queue. 4. The event loop continuously checks: *"Is the call stack empty?"* — if yes, it dequeues the next callback and pushes it onto the stack. Microtask queue vs. macro-task queue: * Microtasks (Promises .then/.catch, queueMicrotask, MutationObserver) are processed before the next macro-task.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'360d5a15-9b14-4918-94c1-ecdf17968216', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does the coordinator node manage client requests in a distributed cluster?', N'Senior', N'Any node can act as a coordinator for a client request, receiving the request and determining which replicas should handle it based on the partition key. The coordinator then manages the communication with those replicas, waits for the required consistency level, and returns the result to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
