INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'54aa09e0-03a6-4db0-b30c-ecf4b36accfe', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How do isolation levels affect transaction behavior?', N'Junior', N'Isolation levels define the degree to which one transaction is protected from the effects of concurrent transactions. Higher isolation levels provide more consistency but reduce concurrency and performance due to increased locking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a2a012e-44de-458f-b8f0-ecf4ca02e5e9', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s approach to error handling facilitate resiliency in distributed systems?', N'Senior', N'Hono provides a centralized ''onError'' hook that allows for consistent translation of internal errors into standard HTTP responses. By decoupling the error generation from the response formatting, developers can implement unified logging, observability, and circuit-breaking logic that adheres to enterprise-grade fault tolerance standards.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4075ed95-81ed-4a08-a88a-ecf6153efea1', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the ''Request'' object in Fastify?', N'Intern', N'The Request object is an abstraction of the incoming HTTP request. It provides easy access to parameters, query strings, headers, and the body of the request.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79f3b296-e7b9-4aee-8071-ecfce7364b17', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the performance trade-off of using @import in stylesheets?', N'Senior', N'Using @import prevents the browser from downloading multiple files in parallel because it forces the browser to download and parse the main file before discovering the imported dependencies. This increases the total time to first paint and should be avoided in favor of build-time concatenation or link tags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f50ce223-3e1b-443b-a0ac-ecfdb5fe418b', N'e4845007-4dc6-43ab-89c6-60ca39ac050d', N'What is the difference between a path parameter and a query parameter in Axum?', N'Fresher', N'Path parameters are segments of the URL URI used to identify a specific resource, while query parameters are appended after the question mark and are typically used for filtering or sorting. Axum provides different extractors for each.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'874bb387-9848-497f-8bdf-ed0717a24fa4', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How do Kotlin''s ''context receivers'' improve the architectural design of dependency injection?', N'Senior', N'Context receivers allow functions to declare dependencies implicitly without passing them as parameters, reducing clutter and boilerplate. This approach enables more granular control over scope and capability, effectively replacing the need for global state or complex ''Reader'' patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'28219966-58b0-457a-8509-ed07e717b19a', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'What are the trade-offs in using ''Value Classes'' for domain modeling?', N'Senior', N'Value classes provide a way to add type safety without the overhead of additional object allocations at runtime. However, they have strict limitations, such as not allowing multiple fields, and can trigger unexpected boxing in certain scenarios, requiring careful evaluation of their impact on memory.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9122ba9-8b11-4483-98d1-ed09c870a239', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the purpose of the ''Outlet'' in an Ember template?', N'Fresher', N'An outlet acts as a placeholder in a parent template where nested content, determined by the router, will be rendered. It allows for the construction of hierarchical layouts where specific sections of the page change while the main layout remains static.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'09ab4270-50d2-4cde-929d-ed0afe7e4b33', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Is Alpine.js suitable for large-scale single-page applications?', N'Junior', N'Alpine.js is generally not recommended for large-scale, complex applications with heavy state management and complex routing. It is better suited for sprinkling interactivity into static or server-rendered sites.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'661d8d40-cbd7-4eac-ab5d-ed0b973b9a55', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What role do ''Conditions'' play in Micronaut''s conditional bean registration?', N'Senior', N'Conditions allow beans to be registered only if certain criteria—such as the presence of a configuration property or a specific class on the classpath—are met. This enables the creation of highly flexible, modular libraries that adapt their behavior based on the specific environment and dependencies present.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb3db4ff-0339-4c92-a164-ed0d2a877fa9', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'Why does Remix emphasize web standards?', N'Fresher', N'Remix is built on top of the Fetch API, Request, and Response objects, which are native to the web platform. By using these standards, developers gain skills that are transferable across different environments and ensure long-term stability for their applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2deef80-e554-40c1-8c99-ed0d5451f184', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'How does Spring Boot handle logging?', N'Intern', N'Spring Boot uses Apache Commons Logging for all internal logging, but it also provides default configurations for Logback. It automatically sets up console output and offers a simple way to configure log levels and output destinations through the application properties file.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdf17df6-ce77-43c5-9221-ed0fdb52c569', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is a ''SSTable'' in the context of LSM-trees?', N'Middle', N'An SSTable (Sorted String Table) is an immutable data file that stores key-value pairs sorted by key. Because they are sorted, they allow for efficient range scans and binary searching, which is a core component of the storage performance in many NoSQL databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95419e11-acd3-4e9b-bd93-ed11bebea1b4', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the .env file?', N'Intern', N'The .env file is used to store environment-specific configuration variables, such as database credentials and API keys. It keeps sensitive information out of your version control system and allows the application to behave differently depending on the environment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e10f20c0-38d8-4e38-b734-ed11ffa88707', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Explain the concept of ''Deoptimization'' in the JVM and why it occurs.', N'Senior', N'Deoptimization is the process where the JVM reverts compiled machine code back to interpreted bytecode because an optimistic optimization, such as an assumption about class hierarchy or field values, has been invalidated. This often happens when dynamic class loading or runtime changes violate the assumptions made by the JIT compiler during the original compilation phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bb03e3bc-b50d-44b0-9d55-ed149ef5d21b', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of the Phoenix ''Endpoint'' and how does it relate to the Supervision tree?', N'Senior', N'The Endpoint is the entry point for all requests entering the Phoenix application and acts as a supervision supervisor. By placing the Endpoint at the top of the supervision tree, Phoenix ensures that if the server process crashes, it is automatically restarted with its original configuration, maintaining system uptime and fault tolerance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7a505c63-b90e-43c1-8a44-ed14e1fbebd3', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Discuss the implications of memory leaks in single-page applications (SPAs).', N'Senior', N'In SPAs, memory leaks often occur due to lingering event listeners, global variables, or detached DOM nodes that are held in closures. Since the page never reloads, these leaks accumulate over time, eventually leading to increased garbage collection pressure and browser crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd65c6ff2-718d-4106-9e7d-ed174b8085f0', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin''s null safety mechanism differ from Java''s Optional type?', N'Middle', N'Kotlin''s null safety is built into the type system itself, distinguishing between nullable and non-nullable types at compile time. In contrast, Java''s Optional is a wrapper object that requires explicit wrapping and unwrapping, which can lead to runtime overhead and does not prevent null references from being assigned to standard object types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbdebe21-84cd-468c-9eb1-ed199c0a1708', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do you convert character to ASCII code', N'Fresher', N'You can use the String.prototype.charCodeAt() method to convert string characters to ASCII numbers. For example, let''s find ASCII code for the first letter of ''ABC'' string, Whereas String.fromCharCode() method converts numbers to equal ASCII characters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'912e8489-a145-4459-b230-ed19c9fca3e7', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What is ''Transition'' in SolidJS and when should it be used?', N'Senior', N'Transitions allow you to mark certain state updates as non-urgent, preventing the UI from blocking while waiting for complex async tasks. It allows the framework to keep showing the previous state while preparing the next state in the background, improving perceived performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c8315135-847a-4061-9e11-ed1a8d79b7eb', N'a088dc80-0ccc-442b-9916-ac1c0d5009f4', N'Why is it difficult to write unit tests for jQuery-heavy code?', N'Middle', N'jQuery code is often deeply coupled with the DOM, making it difficult to isolate logic for unit testing without a full browser environment. Unlike frameworks that separate business logic from the UI, jQuery tests frequently require complex DOM setups and teardowns for every test case.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
