INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5159dc71-6b68-4ae9-acc7-ed1f901b360f', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'When is a graph database preferred over a document database?', N'Intern', N'A graph database is preferred when the focus of the application is on the relationships between data points rather than the data itself. If your application involves heavy traversal of interconnected entities, a graph model is significantly more efficient than a document model.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0e18809c-9ce8-446b-a39e-ed213649781c', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''decorate'' method?', N'Fresher', N'The decorate method allows you to add custom properties or methods to the Fastify server instance, request object, or reply object. This is useful for sharing utility functions or database clients across different parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'67ba910d-2283-47f9-a066-ed22eaa82318', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the ''Bulkhead'' pattern in service architecture?', N'Senior', N'The bulkhead pattern isolates resources, such as thread pools or connection pools, so that a failure in one area of the application does not consume all resources for the entire system. By partitioning resources, you contain the impact of a fault to a specific sub-component or user group.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33fa1b5d-5f43-4c4d-a712-ed25fdbcdff0', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What factors influence your decision to choose a microservices architecture over a monolith?', N'Middle', N'I consider the organization size, deployment velocity, and team autonomy requirements. Microservices are appropriate when different parts of the system need independent scaling or different technology stacks, whereas a monolith is better for early-stage products where simplicity and rapid iteration are prioritized.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fcbbd33a-a3f0-4f94-aa64-ed27c17caf72', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'What is the purpose of the ''__init__'' method?', N'Junior', N'The ''__init__'' method is a special constructor method that is automatically called when a new instance of a class is created. Its primary purpose is to initialize the object''s attributes with provided values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'19a01242-80bd-4880-8a65-ed27f6163054', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'What is the difference between a static method and a non-static method?', N'Junior', N'A static method belongs to the class itself and can be called without creating an instance of the class. A non-static method belongs to a specific object instance and requires an object to be created before it can be invoked.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4a9d06e-42c4-4c9b-b71f-ed28b4613318', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Describe the purpose of the AdonisJS ''Ignitor'' process.', N'Middle', N'The Ignitor is responsible for bootstrapping the application, loading environment variables, and initializing the IoC container. It ensures that all necessary services are ready before the HTTP server begins accepting incoming requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'984bbc0e-d341-4aa4-84f7-ed2abfab67a0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is meant by ''Thread Safety'' in Rust?', N'Fresher', N'Rust’s ownership and type system prevent data races at compile time, which is a common cause of concurrency bugs. Because the compiler enforces these rules, code that is compiled is generally considered thread-safe by design.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d9f9d03-ec8c-4f59-ad36-ed2c233ea73c', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'How does a cache improve system availability?', N'Middle', N'By serving content from memory, a cache reduces the reliance on downstream services like databases or external APIs. If those services experience intermittent failures or slowness, the cache can continue to serve previously stored data, maintaining partial availability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5f0d635e-de5e-4af9-ba05-ed2cebdbeb0d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What does ''web::Json'' do in Actix?', N'Intern', N'The web::Json extractor is used to deserialize the body of an incoming HTTP request into a structured Rust type. It ensures that the client-provided data matches the expected format before the handler processes it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'59f7583b-57c7-4870-b96d-ed2d5cefeb7e', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the trade-offs between using React Server Components (RSC) versus client-side hydration for large-scale data-driven applications.', N'Senior', N'RSC allows components to execute entirely on the server, significantly reducing the bundle size sent to the client and eliminating the need for hydration of those specific parts. While this improves initial load times and data fetching efficiency, it limits interactivity because RSCs cannot use browser-only APIs or React hooks. The trade-off is a shift in complexity, as developers must architect a clear boundary between server-side static content and client-side interactive islands.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'878157df-763a-4ea3-b650-ed2dd73479e1', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How do you handle browser differences in your user base?', N'Fresher', N'The @supports query in CSS can be very useful to scan if the user''s current browser has a certain feature. The @supports CSS at-rule lets you specify declarations that depend on a browser''s support for one or more specific CSS features. This is called a feature query. The rule may be placed at the top level of your code or nested inside any other conditional group at-rule.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f9af6ce9-6fb0-4212-90ab-ed2e0b4d1008', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What are the performance implications of the AdonisJS middleware pipeline?', N'Senior', N'The middleware pipeline uses an onion-layered execution model that allows for both pre-processing and post-processing of requests. While highly flexible, excessive middleware usage can increase latency; senior developers must optimize by ordering middleware based on necessity and offloading heavy logic to background jobs.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aeb6593d-f17a-4132-a60c-ed2ead278b3e', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What is the significance of the ''Ember CLI'' build pipeline?', N'Middle', N'Ember CLI provides a standardized environment that handles transpilation, minification, and asset fingerprinting out of the box. Its convention-over-configuration approach ensures consistent project structures and simplifies the integration of third-party addons.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'37aaa273-ff8b-4a29-85da-ed2eff22b4d5', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is an ORM in the context of Django?', N'Intern', N'An ORM, or Object-Relational Mapper, is a technique that allows developers to interact with a database using Python code instead of writing raw SQL queries. Django''s ORM maps database tables to Python classes, making data manipulation intuitive and database-agnostic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da019f31-5252-4892-af66-ed2f1679aa09', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How do you handle 404 errors in Express?', N'Intern', N'You handle 404 errors by adding a middleware function at the very end of your middleware stack that does not match any specific path. Since this middleware is reached only if no previous routes matched, it serves as a catch-all for undefined routes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ccb69b4b-e331-46e4-bd36-ed322d0f7926', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you handle cascading failures in a microservices ecosystem?', N'Senior', N'You implement the Circuit Breaker pattern to prevent a failing service from exhausting resources in calling services. This stops requests to a failing endpoint for a specified duration, allowing the downstream service to recover while providing a fallback response to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'38ed1cf4-31ad-442c-803f-ed362142afc9', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is the primary difference between WiredTiger and MMAPv1 storage engines in MongoDB?', N'Middle', N'WiredTiger uses document-level concurrency control, allowing multiple clients to modify different documents in a collection simultaneously, which significantly improves write performance. MMAPv1 used collection-level locking, which created bottlenecks during high-write workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e029ce8b-2d93-495d-b4a3-ed36caa6445d', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the trade-offs of using the Actor model for web services?', N'Middle', N'The Actor model offers excellent isolation and scalability for complex stateful services. However, it can introduce significant architectural complexity, potential for message deadlocks, and overhead for simple request-response scenarios compared to standard functional web frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'07d278a6-1dc6-414d-ac39-ed36cdd94188', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'How does the JVM handle the ''False Sharing'' phenomenon in multi-threaded programming?', N'Senior', N'False sharing occurs when multiple threads modify independent variables that happen to reside on the same CPU cache line, causing unnecessary cache coherency traffic. In Java, this is mitigated by using the @Contended annotation, which instructs the JVM to add padding around fields to ensure they occupy distinct cache lines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'062e229e-780b-4827-b345-ed376002f1e6', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is a database transaction in Active Record?', N'Intern', N'A transaction ensures that a series of database operations are treated as a single unit of work. If any operation within the block fails or raises an exception, the entire transaction is rolled back, ensuring the database remains in a consistent state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4bdfb797-32e6-4771-80f5-ed4091ae736b', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How are errors handled in Actix-web?', N'Middle', N'Actix-web uses a dedicated ''ResponseError'' trait that allows developers to map internal application errors to specific HTTP status codes and response bodies. This provides a clean way to centralize error logic and return meaningful feedback to clients.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
