INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'87181eff-6181-4aaf-91e2-ed4783bf706b', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the main challenge in migrating an existing large-scale React application to Qwik?', N'Middle', N'The main challenge is the paradigm shift from hydration to resumability. Existing React codebases rely on hooks and component lifecycles that expect a specific execution sequence, which does not exist in Qwik; therefore, significant refactoring is required to align with Qwik''s reactive signal and serialization patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
