INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e36545f-dd5f-4ae4-b36b-ed4b45e391f0', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How does the choice of a primary key impact performance in a B-Tree based storage engine?', N'Middle', N'An incremental, monotonically increasing primary key is ideal because it prevents page fragmentation and minimizes tree rebalancing. Conversely, a random or non-sequential key like a UUID often leads to frequent page splits and poor write throughput due to data being inserted in random locations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5a5c6a4-64d5-42fb-a7cc-ed4bfd79cfe2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'Why is ''perfect'' code often considered a poor target when balancing trade-offs?', N'Intern', N'Striving for perfection often leads to over-engineering, which consumes excessive time and resources. Instead, delivering a functional solution that meets current requirements allows for faster iterations and provides more value to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
