INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'554a24b0-53f1-49c6-8658-ed501359d4e5', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is the ''smart cast'' feature?', N'Fresher', N'Smart cast is a feature where the compiler automatically casts a variable to a specific type after a type check. Once you verify the type using ''is'', you can use the variable as that type without manual casting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e8081a4a-ff8d-4afd-8c24-ed505e1dc082', N'075b8862-431c-4678-9767-f55359758a4a', N'How do you reuse elements with key attribute?', N'Fresher', N'Vue always tries to render elements as efficient as possible. So it tries to reuse the elements instead of building them from scratch. But this behavior may cause problems in few scenarios. For example, if you try to render the same input element in both v-if and v-else blocks then it holds the previous value as below, In this case, it shouldn''t reuse. We can make both input elements as separate by applying key attribute as below, The above code make sure both inputs are independent and doesn''t impact each other.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'74c41e66-7ae5-4058-9c6b-ed531d4b0d3f', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you manage the trade-off between caching latency and data staleness?', N'Senior', N'I analyze the cost of serving stale data versus the cost of cache misses on the backend. For frequently updated data, I implement shorter TTLs or event-driven cache invalidation, while for static assets, I maximize TTLs to reduce load. The final strategy is determined by the tolerance of the end-user for slightly outdated information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'95c65add-ec61-4c7f-b9b6-ed58ef50d0ed', N'e48de9d9-e09e-4573-aff6-4627c7a58e9f', N'What is the purpose of Phoenix PubSub and why is it essential for horizontal scaling?', N'Middle', N'PubSub facilitates message broadcasting across different processes and nodes. By decoupling the message producer from the consumer, it allows a Phoenix application to scale horizontally, ensuring that events like real-time updates are propagated to all connected clients regardless of which server node they are connected to.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4768b2d9-b90a-43b9-82db-ed59ba69c215', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Why is the strict directory structure in AdonisJS considered an architectural benefit for large teams?', N'Senior', N'The opinionated structure provides a standard cognitive map for developers, allowing them to navigate any AdonisJS codebase with minimal ramp-up time. This reduces architectural drift and ensures that team members follow a shared convention for organizing logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d143e02-2857-4818-9706-ed5a0ebe113b', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What considerations should be made when using Gin in a serverless (FaaS) environment?', N'Senior', N'Serverless environments favor fast cold starts and minimal memory usage. Gin''s reflection-heavy initialization can be slower than lightweight alternatives; therefore, developers must ensure that the framework''s startup time and memory footprint do not exceed the execution limits imposed by the cloud provider.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'872ff995-9feb-4dec-bc0c-ed5d7816dfb2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'How do you approach the trade-off between using a managed cloud service versus deploying your own infrastructure on Kubernetes?', N'Senior', N'Managed services minimize operational overhead and time-to-market but risk vendor lock-in and potentially higher long-term costs. Self-managed infrastructure provides granular control and portability across providers but requires a dedicated, highly skilled team to maintain security, upgrades, and platform reliability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac8c8ddc-585e-4ab0-b303-ed5df26958d0', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'Can Astro work without any client-side JavaScript?', N'Intern', N'Yes, Astro is perfectly capable of building fully functional websites without any client-side JavaScript. This is the default behavior and is ideal for simple sites like blogs or documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ea6577eb-9e5d-45b9-bcac-ed5ed71f91d0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How does the Sass `meta.load-css()` function differ from a standard `@use`?', N'Senior', N'The `meta.load-css()` function allows for dynamic loading of a module at runtime during compilation, which is useful for conditional styling based on build-time configuration. Unlike `@use`, which is static, this allows the build system to include or exclude styles based on complex logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd932d72a-0606-4388-a758-ed5ff7771675', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the main difference between value types and reference types?', N'Intern', N'Value types, like structs, are copied when they are assigned to a new variable, ensuring each instance maintains its own state. Reference types, like classes, share a single instance, so multiple variables can point to and modify the same underlying object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3d658d4-aba0-4a15-97b6-ed60d2df6d9d', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of the ''log'' folder?', N'Intern', N'The log folder contains text files that record the activity of the application as it runs. These files provide valuable information for debugging, as they show the requests handled, database queries executed, and any errors that occurred during application execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'caabe299-8f62-4f66-9755-ed62f9732de7', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass partials and how are they identified?', N'Fresher', N'Partials are Sass files that contain small snippets of CSS intended to be imported into other files rather than compiled into a standalone CSS file. They are identified by a leading underscore in the filename, which tells the Sass compiler to ignore them during the build process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffb6fdec-86b7-49ed-9de7-ed63bed4fd04', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is an Entity in Doctrine?', N'Intern', N'An Entity is a standard PHP class that represents a specific table in the database. Each instance of the class corresponds to a single row in that table, allowing data to be manipulated as objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd08ecc5-b38c-434b-8e85-ed63cd8c0c9a', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How do you approach managing secrets in a production cloud environment?', N'Middle', N'I use a dedicated secret management service to store and inject secrets at runtime rather than hardcoding them. I also enforce rotation policies and use IAM roles to grant least-privilege access, ensuring only authorized services can retrieve the secrets.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b1963264-2a3e-4c17-9f90-ed63dacf2731', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'How do you handle cascading failures in a distributed system?', N'Senior', N'Cascading failures are mitigated using patterns like circuit breakers, bulkheads, and timeouts to isolate failing components. These mechanisms prevent a single service''s latency or failure from exhausting thread pools or connection resources across the entire architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ca43e8d6-d832-4560-8724-ed64a0e3c197', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono manage environment-specific variables (bindings) compared to traditional Node.js process.env?', N'Senior', N'Hono treats bindings as an injected ''env'' object passed through the context, rather than relying on global process-level state. This promotes better testability and type safety, as dependencies are explicitly defined and injected, preventing the hidden coupling associated with global environmental variable access.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7f7e1a11-faa9-49f1-8734-ed64b06c9d5f', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the benefit of using Hono''s ''validator'' middleware?', N'Junior', N'The validator middleware allows developers to enforce schema checks on incoming data like JSON bodies, queries, or headers before they reach the main handler. This ensures that the application logic only processes valid, expected input, reducing runtime errors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'693f4d9d-bc4d-4244-bc1c-ed693e8b3001', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What is an object declaration in Kotlin?', N'Fresher', N'An object declaration is a way to define a singleton class in Kotlin. It ensures that only one instance of that class is ever created, providing a thread-safe way to manage global state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6295638b-21cc-4e04-b392-ed695135786a', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'What is the ''filter'' context in a search query, and how does it differ from ''query'' context?', N'Middle', N'The filter context is used for binary yes/no questions and is cached by Elasticsearch, making it very performant for repeated lookups. The query context calculates a relevance score for each document, which is more computationally expensive and is not cached.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'271e33c1-f221-4d59-bc21-ed6a30d2ea05', N'13e2ca28-eea5-41c9-b9f7-bb329afd8eb8', N'How does PHP''s copy-on-write (COW) mechanism handle variable assignment and memory efficiency?', N'Senior', N'COW allows multiple variables to point to the same memory location, deferring data duplication until one of the variables is actually modified. This optimization significantly reduces memory consumption when passing large arrays or objects by value, as the duplication only occurs if a write operation is initiated on the shared data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cfe3596a-3f6f-49e8-b421-ed6a55ebec05', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is a Migration in the context of AdonisJS database management?', N'Junior', N'A migration is a version-controlled way to define and manage changes to your database schema. It allows developers to share database structure updates across a team by tracking modifications in code rather than manual SQL script execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a1b85bb3-7aa1-423f-b5a2-ed6d6c7fe67c', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Why is the rule of five essential for resource management in C++?', N'Senior', N'The rule of five dictates that if a class manages a resource, it must explicitly define the copy constructor, copy assignment operator, move constructor, move assignment operator, and destructor. This ensures correct resource ownership transfer, prevents shallow copies of unique resources, and avoids dangling pointers or double-free errors during object lifetime management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b2919017-6ef0-470d-a7af-ed6e28b97aec', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How does Symfony''s Twig integration support template inheritance and performance?', N'Senior', N'Twig templates are compiled into native PHP classes, which provides high performance during rendering. Template inheritance allows for a modular design where base layouts define the structure, and child templates override specific blocks, reducing code duplication.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f00d306a-1e05-45f8-89ef-ed6f4876c4b7', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Why is the ''main'' function special in C?', N'Fresher', N'The main function serves as the entry point of every C program. When the program is executed, the operating system calls the main function to begin the program''s execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'72ee58ce-0910-4998-940f-ed6f91ca4c10', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are variables in Sass and why are they useful?', N'Intern', N'Variables are a way to store information like colors, font stacks, or any CSS value that you want to reuse throughout your stylesheet. They are useful because if a value needs to be changed, you only have to update it in one place instead of searching and replacing it throughout the entire project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4e72e8db-ebb3-4fd9-b37c-ed71699a35b7', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How does the Next.js App Router differ from the Pages Router in terms of architecture?', N'Middle', N'The App Router is built on React Server Components and uses a file-system-based routing structure with nested layouts and loading states. The Pages Router relies on a simpler directory structure where every file represents a route, making it less flexible for complex layout management compared to the App Router.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
