INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'999f623f-00d7-46cf-a531-ed7bfdc1b2de', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'What is the advantage of Fiber''s design regarding memory footprint?', N'Middle', N'Fiber''s focus on minimizing allocations ensures that even under heavy load, the application maintains a low and stable memory footprint. This prevents frequent garbage collection cycles, which are a major source of latency spikes in Go web applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9785ad62-2507-49fa-8834-ed7d7776af00', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the concept of Index Cardinality and why it matters.', N'Middle', N'Cardinality refers to the number of unique values in an indexed column. High cardinality is ideal for indexes because it allows the optimizer to filter out a large percentage of rows, whereas low cardinality makes an index less effective for query optimization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
