INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1a6c483d-b947-428c-bb00-ed7d8188e485', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How does JavaScript garbage collection work?', N'Fresher', N'Garbage collection in JavaScript is an automatic memory management mechanism that reclaims memory occupied by objects and variables that are no longer in use by the program. The two most common algorithms are mark-and-sweep and generational garbage collection. Mark-and-sweep The most common garbage collection algorithm used in JavaScript is the Mark-and-sweep algorithm. It operates in two phases: - Marking phase: The garbage collector traverses the object graph, starting from the root objects (global variables, currently executing functions, etc.), and marks all reachable objects as "in-use". - Sweeping phase: The garbage collector sweeps through memory, removing all unmarked objects, as they are considered unreachable and no longer needed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc48efd1-d770-42ac-b552-ed7f7f356d10', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is dependency injection in Litestar and why is it useful?', N'Intern', N'Dependency injection is a design pattern where the framework automatically provides the necessary components or services, such as database connections, to a handler function. This promotes modularity, makes testing easier, and reduces boilerplate code by ensuring that dependencies are managed centrally.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'30eaae7b-0ca6-473d-a384-ed81da4eaec5', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How can Sass maps be used to manage complex design systems or theme configurations?', N'Senior', N'Sass maps allow you to group related key-value pairs—such as color palettes, font sizes, or breakpoints—into a single data structure. This facilitates programmatic access and iteration over design tokens, ensuring consistency and making it easier to update the entire design system from a single source.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'88020414-a327-40df-bc88-ed81e6c2d230', N'f47122b3-d4b6-48ae-ba90-6f28e9c6c68b', N'Why is it important to consider edge cases when planning a solution?', N'Intern', N'Edge cases are unusual or extreme scenarios that are not part of normal operations but can cause a system to fail. Considering them early ensures that the solution is robust and reliable under all conditions, not just the most common ones.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bdf24ff8-afec-4633-98db-ed84252eaef9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is optimistic concurrency control and when should it be used?', N'Middle', N'Optimistic concurrency control assumes that conflicts are rare and allows multiple transactions to proceed without locking resources. It checks for conflicts only at the time of commit, making it highly scalable for read-heavy systems, though it requires the application to handle retries if a conflict is detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'914a5457-6963-45a6-9a1e-ed8564adde24', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Is Micronaut purely synchronous?', N'Fresher', N'No, Micronaut supports both blocking and non-blocking IO. It provides excellent support for reactive programming models, allowing developers to build asynchronous, event-driven applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3611f932-606d-4c72-a0f6-ed87205a9d23', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the CAP theorem and why does it matter for distributed systems?', N'Middle', N'The CAP theorem states that a distributed system can only guarantee two out of three properties: Consistency, Availability, and Partition Tolerance. Understanding this trade-off helps architects choose the right database system based on whether their application prioritizes data accuracy or system uptime during network failures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f86dc256-2468-4e8f-b624-ed889646cdec', N'a000805c-e41f-42a9-af12-66b45348f77b', N'What is the purpose of Middleware in an AdonisJS application?', N'Fresher', N'Middleware acts as a layer that intercepts incoming HTTP requests before they reach the controller. It is commonly used for tasks such as authenticating users, validating request data, or logging information, allowing these concerns to be separated from the core business logic.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7bd138cd-dff8-4c8e-8c2c-ed88a4b05221', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the primary architectural difference between R''s base graphics and the grid graphics system?', N'Middle', N'Base graphics are immediate-mode, meaning they draw directly to the device and cannot be modified after the fact. The grid system is a high-level graphics framework that builds a hierarchical tree of viewports, allowing for complex, modular, and editable graphic compositions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'86842bd1-e842-4e23-8b7d-ed8ab1b2f2d9', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How do you define a static route in Echo?', N'Intern', N'A static route is a fixed URL path that does not contain any variable segments. You define it by mapping a specific string path to a handler function using one of the HTTP method functions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'feed823a-f481-4502-89c7-ed8e1fc3c9bb', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you handle graceful shutdowns in a Fiber application?', N'Middle', N'Graceful shutdown is typically handled by listening for OS signals like interrupt or terminate. Once caught, you call the shutdown method on the Fiber app instance, which stops the server from accepting new requests while allowing current requests to finish processing before exiting.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'196ba4cc-b2da-4077-9879-ed8e874ddd7d', N'954a0331-deff-4399-b588-96f39fec001d', N'When should you choose a Resolver over fetching data directly within a component?', N'Senior', N'Resolvers are best used when you want to ensure data is available before a route is activated, preventing partial UI states or ''jank'' during navigation. However, they can delay the route transition, so they should be avoided for slow-loading data where a loading spinner in the component is a better UX.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9e80aff5-ba98-4b0c-9afe-ed8f3e2914e3', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What is the purpose of the ''each'' block in Svelte?', N'Intern', N'The each block is used for rendering a list of items. It iterates over an array or iterable object and generates a set of elements for each item in the collection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'550e6591-c27d-4a10-b65a-ed90616603c2', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'How does Hono''s architecture support ''cold-start'' optimization?', N'Middle', N'By avoiding large dependency trees and favoring native Web APIs, Hono applications have a very small footprint. This results in faster initialization times when a serverless function is invoked after inactivity, which is crucial for maintaining responsiveness in user-facing applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'063e3521-d60a-4a30-b36a-ed90c409aac0', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What are the primary advantages of Rust''s macro system?', N'Middle', N'Rust macros allow for code generation and meta-programming, which reduces boilerplate and enables custom syntax extensions. They operate by transforming source code before it is compiled, providing high performance and safety compared to runtime reflection.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
