INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9fe11006-bb56-4598-92e8-ed9561e83f59', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What is the importance of a circuit breaker pattern in microservice architecture?', N'Middle', N'A circuit breaker prevents a failing service from cascading its issues across the entire system by failing fast once a threshold of errors is reached. This allows the failing service time to recover and prevents the calling service from wasting resources on requests that are likely to fail.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'08e74fcf-64c3-4c20-a611-ed994aa7e946', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'What is the purpose of a transaction log?', N'Intern', N'A transaction log is a file that records all changes made to the database before they are permanently applied. It is essential for recovery, allowing the system to redo committed transactions or undo uncommitted ones after a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'12f1da93-4cd8-4c07-89ea-ed999737a645', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is R considered an interpreted language?', N'Fresher', N'R is considered an interpreted language because the code is executed line-by-line by an interpreter rather than being compiled into machine code beforehand. This allows for an interactive programming experience where users can test code snippets immediately.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
