INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e2c54a9b-5edb-4433-bc49-ed9d1c9dbd3f', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'How does PostgreSQL handle transaction isolation levels internally?', N'Senior', N'PostgreSQL uses snapshots to provide isolation levels. In Read Committed, a new snapshot is taken for every statement, while in Repeatable Read and Serializable, a single snapshot is used for the duration of the entire transaction, ensuring consistent views of the data even if other transactions commit changes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ed93349-d035-4265-8494-ed9d26b2a8f7', N'108bf9e6-5ec2-45e1-ab9b-f6df6a74e5d1', N'What is the primary difference between Hono and Express?', N'Fresher', N'Hono is built for modern edge runtimes and follows Web Standards, while Express is built specifically for Node.js. Hono is significantly smaller and faster, whereas Express has a larger ecosystem and legacy support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'037c1430-fb4c-40d2-9a80-ed9ecbf79738', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'How do you handle breaking changes in a public-facing API?', N'Middle', N'I prefer versioning the API through URL paths or header versioning to ensure backward compatibility. This allows existing clients to continue functioning while providing a migration path. I also communicate changes well in advance and provide clear documentation for the new version.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b472ac4a-d881-40ab-be4d-eda0131cd2e1', N'bee93334-72db-476a-ac7b-33bb7b95f2f9', N'How does Remix prevent data waterfalls?', N'Middle', N'Remix prevents waterfalls by loading data for the entire route hierarchy in parallel on the server during the initial request. Because the server knows the entire route structure, it can trigger all required loaders simultaneously instead of waiting for components to mount.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c488beb3-a291-41fd-a6b7-eda020aac57d', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'How does ''Dead Letter Queue'' (DLQ) pattern enhance system reliability in message-driven architectures?', N'Senior', N'A DLQ captures messages that fail to process after multiple retries, preventing them from blocking the main queue. It allows engineers to inspect and replay failed messages later, ensuring no data is lost and system progress continues.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'97fba4b6-5de5-4032-a06f-eda0e426f465', N'4abbd457-7382-47ee-93af-fb74f3ad2ed4', N'How do Traits differ from Abstract Classes in Scala?', N'Middle', N'Traits support multiple inheritance and are designed to define modular behavior that can be mixed into classes. Abstract classes are better suited for defining a clear identity or hierarchy and allow for constructor arguments, which traits do not support.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a78ba3cc-7636-4d91-ae4b-eda83e7dffb3', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is a Context in the Echo framework?', N'Intern', N'The Context object represents the current HTTP request-response cycle. It holds information about the incoming request, such as headers and parameters, and provides methods to send the response back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e6dad1f3-f792-471b-b369-edaa4056437b', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What are the trade-offs of using an auto-incrementing integer as a primary key versus a UUID?', N'Middle', N'Auto-incrementing integers are space-efficient and ensure that new data is appended to the end of the B+ tree, preventing page splits. UUIDs are larger, potentially fragmented due to random insertion patterns, and can cause significant performance degradation in large InnoDB tables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9ecb2cca-da14-4861-a799-edab3b438ceb', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'How do you maintain data consistency across microservices given they each have their own database?', N'Middle', N'Since distributed transactions like 2PC are often impractical, developers use the Saga pattern. Sagas manage consistency through a sequence of local transactions, where each service performs its work and publishes an event to trigger the next step, or executes compensating transactions if a step fails.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'79295eea-8315-4de2-bc16-edaf8ae34e6d', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What architectural considerations should be made when implementing custom error handling middleware in Echo?', N'Senior', N'A centralized error handler should differentiate between domain-specific errors and internal server errors to avoid leaking implementation details. It must handle the response commitment status to ensure clients receive consistent status codes while logging sufficient metadata for observability.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'985b34e5-c37b-4e23-af68-edb2567d152f', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'What is the role of the output property in Webpack?', N'Intern', N'The output property tells Webpack where to emit the bundles it creates and how to name those files. It specifies the directory and file structure for the processed static assets that will be served to the browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bfc87085-200e-42d2-bb66-edb34477a843', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the architectural purpose of ''GOMAXPROCS''?', N'Senior', N'GOMAXPROCS limits the number of OS threads that can execute user-level Go code simultaneously. While it defaults to the number of CPU cores, adjusting it allows developers to tune the level of parallelism to match the workload characteristics, particularly in containerized environments where CPU resources might be throttled.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b831de30-6f93-44ce-87fb-edb45e0435dc', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What role does ''monitoring'' play in preventing the need for debugging?', N'Intern', N'Monitoring tools provide real-time alerts on system health, allowing teams to address potential issues before they escalate into full-blown failures. By visualizing trends and thresholds, monitoring helps identify degraded performance early.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'689b2fc4-48fa-4aac-bbcc-edb57c5179c0', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'How does TypeScript handle recursive types and what are the limitations in terms of compiler depth?', N'Senior', N'TypeScript supports recursive type definitions, but they are subject to depth limits to prevent infinite loops during type resolution. When building deep data structures, recursive types can trigger compilation errors, often requiring a transition to iterative type definitions or specific compiler flags.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
