INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'259895cc-1335-4002-802e-edb69fd63f31', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the role of a Type Guard?', N'Middle', N'A type guard is an expression that performs a runtime check which guarantees the type of a variable in a specific scope. These can be custom functions returning type predicates or built-in operators like ''typeof'' or ''instanceof'' to help TypeScript''s type inference engine.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3a5d905e-d6cd-4110-9b0e-edb6caa93f91', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'How does Qwik''s serialization mechanism handle complex data types like closures or class instances?', N'Senior', N'Qwik uses a specialized serializer that maps complex objects into a format compatible with JSON. It breaks down closures and state into separate, lazy-loadable symbols, ensuring that references can be reconstituted on-demand without needing to store the entire application memory state in the initial payload.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ffa4000-2b15-43f9-9227-edb983a81549', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is a database in MongoDB?', N'Intern', N'A database is a physical container for collections in MongoDB. Each database gets its own set of files on the file system, and a single MongoDB server can host multiple databases.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d39a163-42da-49d0-a6c1-edc1f7790007', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'Describe the function of the Java Virtual Machine (JVM).', N'Junior', N'The JVM is an abstract computing machine that enables a computer to run a Java program by interpreting or compiling bytecode into machine-specific code. It manages memory through automatic garbage collection and provides a platform-independent environment. This is the core component that allows Java to be write-once, run-anywhere.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
