INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f8369de9-611d-4ea9-9a84-edc552b445fa', N'3664fb9e-c2f5-4d47-b61e-a19bbc2b8107', N'What is the purpose of the ''cluster'' module in Node.js?', N'Middle', N'The cluster module allows you to create child processes that share the same server port to take advantage of multi-core systems. Since Node.js is single-threaded, clustering is essential for scaling applications to utilize all available CPU cores effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd9d5db13-c66d-40f7-8814-edc6a898281a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How does Redis manage memory fragmentation?', N'Middle', N'Redis manages memory fragmentation using the jemalloc memory allocator, which is designed to reduce fragmentation in long-running processes. If fragmentation becomes severe, Redis can be configured to perform active defragmentation, which moves data blocks in memory to reclaim space, though this can introduce slight latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'737a67bf-9bfc-42c4-abfa-edc7cca22109', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is a ''silent failure'' and why is it dangerous?', N'Junior', N'A silent failure occurs when an application encounters an error but continues running without throwing an exception or alerting the user. It is dangerous because the system may produce incorrect data or enter an inconsistent state without anyone realizing there is a problem.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'429f8a74-79ff-445e-b927-edc98ea46b56', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is meant by the term ''zero-cost abstractions'' in Rust?', N'Intern', N'Zero-cost abstractions mean that the high-level features you use in Rust do not impose additional performance penalties compared to writing low-level, manual code. The compiler optimizes these abstractions so that the resulting machine code is as efficient as if you had written it without them.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ffb5c893-80f7-4ca6-b84b-edca76e1bd78', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'What is horizontal scaling (sharding) in MongoDB?', N'Junior', N'Sharding is the process of storing data records across multiple machines to support deployments with very large data sets and high throughput operations. As the size of the data grows, a single machine might not be sufficient to store or process the load, so sharding distributes the data load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0fd5473c-77e7-456c-860c-edd3bbdd1926', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the purpose of a data type in a database column?', N'Intern', N'Data types define the kind of information that can be stored in a column, such as integers, strings, dates, or booleans. This ensures that the database only accepts valid data and helps optimize storage and query performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae4c08bf-4c18-4ed3-9286-edd6b5ec04b4', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'How does the CSS stacking context affect z-index behavior?', N'Middle', N'A stacking context is a three-dimensional conceptualization of HTML elements along the z-axis relative to the user. Elements inside a stacking context are layered only relative to their siblings within that same context, meaning an element with a high z-index inside a lower-level context cannot appear above an element in a higher-level context.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cda6676f-1cbd-46c8-a662-edd8ac1e038b', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What are the benefits of using a message broker to implement a microservices event-driven architecture?', N'Middle', N'A message broker enables loose coupling, allowing services to evolve independently without needing to be online simultaneously. It also facilitates horizontal scalability, as multiple instances of a service can subscribe to the same queue to share the processing load.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a8c2bfb5-d1e4-479e-8cb6-edd925a17ced', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'Explain how SolidJS manages component lifecycle compared to React''s hooks.', N'Senior', N'SolidJS lifecycles are essentially reactive events; since components only run once, lifecycles like ''onMount'' simply register callbacks to be executed when the reactive scope is first created. This simplifies the mental model by removing the need for dependency arrays and the risks of stale closures.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6bed4a27-288a-4f83-9d20-eddc64a89779', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How does Echo''s router handle path parameters, and what is its performance implication?', N'Middle', N'Echo uses a high-performance radix tree (or prefix tree) for routing, which allows for efficient lookup of dynamic paths. Path parameters are parsed during the tree traversal, making it significantly faster than using regular expressions for routing as the number of routes grows.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6505a55-ba51-4d02-9122-eddd69e34084', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What happens when a node is down for a period longer than the max_hint_window_in_ms?', N'Middle', N'If a node is down longer than the hint window, the coordinator stops storing hints for that node to prevent the commit log from filling up. In this case, an administrator must run a manual anti-entropy repair to synchronize the data once the node is back online.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6f7b1c51-e133-4024-b3e0-eddf24f53785', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'How do you handle migrations in a Symfony project using Doctrine?', N'Middle', N'Migrations are handled by the Doctrine Migrations bundle, which tracks changes to the database schema over time. By versioning these changes as classes, you can reliably deploy schema updates across different environments and revert them if necessary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'39fce2e1-bca9-4e9b-9c29-ede218836d58', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'Why does Dart use an isolate-based concurrency model instead of shared-memory threads?', N'Middle', N'Isolates do not share memory, which eliminates the need for complex locking mechanisms like mutexes or semaphores. By communicating exclusively through message passing, Dart avoids data races and simplifies concurrent programming, leading to more stable and scalable applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0f58c46-7610-4579-9d95-ede44c88f1c7', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What are extension methods in Dart?', N'Intern', N'Extension methods allow you to add new functionality to existing libraries or types without modifying their source code. They are a convenient way to enhance classes or types that you do not own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'03526dd1-1f7a-4c58-b843-ede66114668e', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'What is the purpose of a Request object in Litestar?', N'Fresher', N'The Request object contains all the information sent by the client, such as headers, cookies, query parameters, and the request body. It allows the developer to inspect and interact with the incoming request data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1f244f98-6fa3-46c8-a8d0-ede79ffe8aaa', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the architectural implications of Alpine.js''s ''progressive enhancement'' philosophy compared to traditional Single Page Applications.', N'Senior', N'Alpine.js maintains the integrity of the server-rendered DOM, treating it as the single source of truth, whereas SPAs often replace the DOM with a virtual representation managed by JavaScript. This approach minimizes initial load times and ensures the page is functional without waiting for the full hydration process. It avoids the architectural complexity of state synchronization between client and server found in heavy framework deployments.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0a77d07d-453d-4985-ba8f-ede7d605938d', N'7f9135d1-d5d8-4b44-a443-3bbc74bf6d9b', N'What are the risks of over-using ''bind'' in Svelte?', N'Middle', N'While convenient, excessive use of two-way binding can lead to difficult-to-track state changes and tight coupling between components. It is generally recommended to prefer one-way data flow for complex applications to maintain predictable state management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0dc048e9-3dd4-4331-8735-ede958987135', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the purpose of the Replication Factor?', N'Junior', N'The replication factor determines the total number of copies of data that are stored across different nodes in the cluster. A higher factor increases fault tolerance but requires more storage capacity.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34ef212f-66a0-4e20-9489-edec091bbbc5', N'8dd2851f-4131-42c0-9b9c-e71960cfe3d4', N'What is the difference between RGBa, HEX and HSLa?', N'Fresher', N'* RGB (Red/Green/Blue) is a color model. * HEX (Hexadecimal color values) * HSLa (Hue Saturation Lightness alpha)', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'de10aecb-5f2c-47c3-a17f-edf3559b71ab', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'What is your process for troubleshooting a service that experiences sudden, unexplained spikes in CPU usage?', N'Senior', N'I use profilers to capture CPU flame graphs to identify which functions or methods are consuming the most cycles. I also correlate these spikes with specific incoming request types or scheduled background tasks to determine if the issue is a change in workload, an inefficient algorithm, or a sudden increase in garbage collection overhead.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8356a382-e55d-4f95-87a5-edf38015920f', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'When would you choose Alpine.js over a full-featured SPA framework for a large-scale application?', N'Senior', N'Alpine.js is ideal for enhancing server-side rendered applications where you need interactivity without the overhead of a full SPA architecture. It is best suited for projects where page loads are handled by the server, and frontend logic is limited to specific UI components rather than complex application-wide routing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'406ce405-ee78-4305-a79d-edf4dd71c6fb', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'Explain the difference between ''Depends'' and ''Security'' in FastAPI.', N'Junior', N'Both are used for dependency injection, but ''Security'' is specifically designed to handle authentication and authorization requirements. Using ''Security'' allows FastAPI to include security scopes and authentication schemes in the generated OpenAPI documentation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a17a53d4-30a7-4e43-a27e-edf7dce4df1a', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is the role of a handler function in Echo?', N'Fresher', N'A handler function is a piece of logic that processes a specific HTTP request and generates a response. It receives the Echo Context as an argument and uses it to extract information and send back status codes or data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c9decd4b-e19b-470d-a3ce-edf90d33f555', N'074508f7-35bd-405f-8cc6-b41377b2d92c', N'What is the purpose of a Dead Letter Queue (DLQ) in a messaging system?', N'Middle', N'A DLQ stores messages that cannot be processed successfully after a certain number of attempts or due to malformed data. It allows developers to isolate problematic messages for manual inspection or debugging without stalling the main processing pipeline.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
