INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5e38315f-c5ee-42c3-b1f7-edfa5545e3ae', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Does the browser read Sass files directly?', N'Intern', N'No, browsers cannot read Sass files directly. They only understand standard CSS, so Sass files must be compiled or transpiled into CSS before they can be rendered by a browser.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f55e2696-9c05-46a7-b727-edfaf7efcc1d', N'a000805c-e41f-42a9-af12-66b45348f77b', N'Describe the purpose of the ''Preload'' feature in Lucid ORM and its performance impact.', N'Middle', N'Preloading is a technique used to solve the N+1 query problem by fetching related data in a separate query or join. While it significantly improves performance by reducing database round trips, over-preloading can lead to excessive memory usage if large datasets are retrieved unnecessarily.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c3d23e15-f897-4cbf-b4bb-edfee958f5b6', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the role of the String pool in Java memory management?', N'Middle', N'The String pool is a special memory region in the heap used to store unique string literals. By reusing existing instances instead of creating new ones, the JVM reduces memory consumption and speeds up comparison operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6a0a6cef-828b-409a-bd45-ee005639d066', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why is cache invalidation often considered one of the hardest problems in software architecture?', N'Middle', N'Invalidation is difficult because it requires ensuring that distributed caches remain synchronized with the database whenever data changes. Achieving perfect consistency often requires complex distributed locking or messaging patterns that can negate the performance benefits of caching.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'70b1be1e-46cc-4906-b6a6-ee0132c36a34', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Why is R considered an object-oriented language?', N'Fresher', N'R supports object-oriented programming through systems like S3 and S4, which allow developers to create custom classes and define methods that interact with those objects. This structure enables polymorphic behavior where different types of objects can respond to the same command.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c25259d8-a279-43be-a05f-ee013b836cbe', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'Explain the significance of memory alignment in high-performance C++ systems.', N'Senior', N'Memory alignment ensures that data structures start at memory addresses that are multiples of their size or word boundaries, which is required by hardware for efficient access. Proper alignment prevents performance penalties from unaligned access and is essential for utilizing SIMD instructions and cache lines effectively.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82431c90-8e72-46c7-b4dd-ee0194f4957f', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'How would you implement a circuit breaker pattern within an Express-based microservice architecture?', N'Senior', N'A circuit breaker should be implemented as a wrapper around downstream service calls within the service layer. It monitors the health of the downstream service and trips to an ''open'' state if errors exceed a threshold, preventing cascading failures across the system.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
