INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'69c1eed4-159c-40a7-b3e3-ee06fe27c0b2', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'Explain the role of the partition key in Cassandra data distribution.', N'Middle', N'The partition key determines which node in the cluster is responsible for storing a specific row of data. Cassandra applies a consistent hashing algorithm to the partition key to map it to a specific token range, ensuring even data distribution across the ring.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ae3c70c4-3a83-423e-a703-ee074f2aa33a', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the primary advantage of Astro''s ''Islands Architecture''?', N'Fresher', N'Islands Architecture allows developers to render static HTML for most of a page while isolating interactive components into independent ''islands''. This significantly reduces the amount of JavaScript sent to the client, leading to faster page loads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e0443b42-0f88-427d-ba13-ee085e1eaa82', N'210c7148-726e-4e8b-bf12-40be36e55130', N'Describe the role of the borrow checker in verifying lifetime constraints.', N'Senior', N'The borrow checker performs data-flow analysis to ensure that all references remain valid for the duration of their usage. It verifies that no reference outlives the data it points to, preventing dangling pointers and use-after-free errors through static analysis rather than runtime checks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3974e672-1673-48da-97de-ee1125df23dd', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the common risks associated with manual memory management, and how can they be mitigated?', N'Middle', N'Manual management risks include memory leaks, double frees, and dangling pointers, which can lead to unstable or insecure software. These can be mitigated by adopting strict ownership patterns, utilizing automated static analysis tools, and maintaining consistent coding standards for initialization and cleanup routines.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ac650483-6b18-45f3-b9b9-ee143d0fcbe0', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the benefit of using the ''Result'' pattern in ASP.NET Core APIs instead of throwing exceptions for control flow?', N'Senior', N'Exceptions are computationally expensive and intended for truly exceptional error conditions, not expected business logic outcomes. Using a Result object makes the API more predictable, improves performance by avoiding stack trace generation, and forces the caller to explicitly handle success or failure states.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'595b7a06-5c00-4e7d-aac6-ee14ab1c3223', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How to use <FormattedMessage> as placeholder using React Intl?', N'Fresher', N'The components from react-intl return elements, not plain text, so they can''t be used for placeholders, alt text, etc. In that case, you should use lower level API formatMessage(). You can inject the intl object into your component using injectIntl() higher-order component and then format the message using formatMessage() available on that object.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1dc69cd9-10e4-490a-b905-ee1520bb4288', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'Why is it important to consider the ''mailbox order'' when designing complex message flows in Actix?', N'Senior', N'Although Actix guarantees that messages sent from the same address to the same actor are processed in order, messages from different actors may arrive non-deterministically. Designing systems that rely on strict global ordering requires implementing explicit sequence tracking or centralized orchestration actors.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fe7ba181-4233-4ab0-8efc-ee15230539e7', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What is the purpose of the ''storage'' directory?', N'Intern', N'The storage directory contains compiled Blade templates, file-based sessions, cache files, and other files generated by the framework. It is divided into subdirectories for logs, framework-specific data, and user-uploaded files.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b3708c27-a688-441a-aeb1-ee154da10027', N'3344fa85-0b06-4357-81ea-4294d3199fc4', N'How does Lit handle rendering efficiently?', N'Junior', N'Lit uses a reactive rendering system that only updates parts of the DOM that have changed. It utilizes tagged template literals to parse the template once and then updates dynamic expressions during subsequent renders.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0cbbab4f-b6bc-421f-ad30-ee15b41ac84c', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'What is the role of replication in NoSQL databases?', N'Middle', N'Replication involves copying data across multiple nodes to ensure fault tolerance and high availability. It allows the system to remain functional if one or more nodes fail and can also improve read performance by allowing reads from multiple replicas.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'343b3187-2664-46e0-90bf-ee18913907be', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is Type Casting in Swift?', N'Fresher', N'Type casting is a way to check the type of an instance or to treat that instance as a different superclass or subclass from somewhere else in its own class hierarchy. It is performed using the ''is'' and ''as'' operators.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a979484c-cdea-4249-ae38-ee1894e16f75', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What is the impact of placing business logic inside Redux reducers versus action creators?', N'Senior', N'Reducers must be pure functions, so placing business logic there ensures predictability and testability without side effects. Placing logic in action creators or middleware is better suited for handling asynchronous operations or complex orchestrations before the action reaches the reducer, maintaining the reducer''s role as a simple state transition function.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd992b05-a0d8-44c6-8e02-ee19376aa867', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is a middleware in a web framework?', N'Intern', N'Middleware is a layer that sits between the web server and the application. It processes requests before they reach the application or processes responses before they are sent back to the client.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83893210-7f60-4ead-bc1a-ee1e36df12c1', N'b903153c-4b94-4387-ad3d-450649fa0c50', N'What is Symfony Flex?', N'Intern', N'Symfony Flex is a tool that automates the installation and configuration of packages. It helps manage dependencies and automatically applies standard configuration files to a project.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'25fd922a-8872-42fb-8405-ee1eca3afad7', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'How do persistence mechanisms like RDB and AOF impact Redis performance and data safety?', N'Middle', N'RDB persistence captures point-in-time snapshots of the dataset at specified intervals, which is efficient for backups but risks losing data since the last snapshot. AOF logs every write operation to disk, offering better durability at the cost of larger file sizes and potentially higher I/O overhead. A common strategy is to use both concurrently to balance recovery speed and minimize the window of potential data loss.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'63261c4d-be4a-4d14-a096-ee20bae4f9ac', N'24c74bdc-c63e-4370-b1ac-bd560cb834d6', N'Explain the trade-offs between REST and GraphQL in a high-traffic microservices architecture.', N'Senior', N'REST offers better cacheability due to standardized resource-based endpoints and HTTP semantics, while GraphQL minimizes over-fetching and under-fetching by allowing clients to request exactly what they need. However, GraphQL introduces complexity in query depth limiting, cost analysis, and caching strategies compared to REST.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce54796c-c4eb-4c8a-be85-ee25771db642', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What happens if you try to mutate a signal''s value directly?', N'Junior', N'Mutating the value directly will not trigger the reactivity system. Because SolidJS relies on the setter function to notify listeners of a change, direct mutation will result in the UI failing to update to reflect the new state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd1291a62-b6cf-4294-87c4-ee25a5676a1d', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are the recommended ways for static type checking?', N'Intern', N'Normally we use _PropTypes library_ (React.PropTypes moved to a prop-types package since React v15.5) for _type checking_ in the React applications. For large code bases, it is recommended to use _static type checkers_ such as Flow or TypeScript, that perform type checking at compile time and provide auto-completion features.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'426e8702-d9b2-4153-8724-ee289b0c8d92', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'How does Rust''s ownership model prevent data races in Actix''s actor-based concurrency?', N'Senior', N'Since actors own their internal state and communicate only via immutable or explicitly moved messages, the framework enforces the ''share by communicating'' principle. Rust''s borrow checker ensures that multiple actors cannot mutate the same memory simultaneously, eliminating the need for complex global locks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cbe7e257-6ecc-408f-ac59-ee2a5ba54a5c', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'How does ASP.NET Core support ''Health Checks'' and why are they critical in a Kubernetes environment?', N'Senior', N'Health checks provide endpoints that report the internal status of the application, such as database connectivity or memory usage. In Kubernetes, these are essential for the liveness and readiness probes, allowing the orchestrator to automatically restart failing pods or stop sending traffic to nodes that are not yet ready.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ad27c9f8-1805-470b-a0ce-ee2d317ee848', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'Discuss the implications of using Flask''s ''g'' object versus the ''session'' object for request-scoped data storage.', N'Senior', N'The ''g'' object is a temporary, request-scoped storage meant for data that does not persist beyond a single request cycle. In contrast, the ''session'' object persists across requests by serializing data into a signed cookie or server-side store, introducing overhead and potential security vulnerabilities related to session hijacking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdb4193d-4d95-4ea8-bfdf-ee2e26d9bf69', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s computed properties handle cache invalidation?', N'Middle', N'Computed properties are lazily evaluated and cached based on their dependent keys. When any of the specified dependent keys change, Ember automatically marks the property as dirty, forcing a re-calculation only when the property is accessed again.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6fd9beb7-70d5-42dd-b4d8-ee2e73d43f60', N'4151818e-de4c-4774-bd55-b8900ff33d42', N'Why would you choose to use a ''Before Request'' hook instead of a middleware in Litestar?', N'Middle', N'Hooks provide more granular control at the route or controller level, whereas middleware applies globally to every request. Using hooks allows for specific logic to be applied only to relevant endpoints, keeping the global middleware chain lightweight.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8a1934e0-cabc-4ed4-8f32-ee32897a0602', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'Can Next.js be used to build a completely static website?', N'Fresher', N'Yes, Next.js can export a static version of your application using a process called static exporting. This generates a collection of HTML, CSS, and JavaScript files that can be hosted on any static web server without needing a Node.js runtime.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ab3d02a4-a9c9-4ae8-950d-ee35e7cfb94a', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What is the benefit of using Redis pipelines?', N'Middle', N'Pipelining reduces the network round-trip time by allowing a client to send multiple commands to the server without waiting for individual replies. This significantly improves performance in high-latency network environments by batching requests into a single network transmission.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
