INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7f860be-e263-41b4-b3c7-ee37cc949c6c', N'fcd5873e-c89a-47d6-bb4c-c60b57c2ede1', N'What is the purpose of the ''Circuit Breaker'' pattern in a distributed system?', N'Senior', N'The circuit breaker prevents a system from repeatedly attempting an operation that is likely to fail, such as a downstream service call. It provides a fail-fast mechanism that preserves system resources and allows the failing service time to recover while providing a fallback response to the user.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'391eeb6d-5b8a-4b1a-8047-ee3904860167', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'A task is estimated to take two days, but after one day, you realize you have barely made progress. What is your immediate next step?', N'Junior', N'I would stop working to avoid further wasted effort and immediately communicate the blocker to my lead. I would explain what I have tried so far, why it is not working, and propose a revised plan or ask for guidance to get back on track.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4c7f409-400a-4cd7-8eb8-ee3aefe95441', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is the difference between ''synchronized'' behavior in Objective-C and modern Swift concurrency?', N'Middle', N'Objective-C relied on locking mechanisms like @synchronized, which were prone to deadlocks and performance bottlenecks. Modern Swift uses structured concurrency, such as Tasks and Actors, to manage state safely without explicit locks by isolating mutable data.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6587d6f3-6e04-42f1-8104-ee3ed0c1b16b', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of Micronaut''s ''Ahead-of-Time'' (AOT) compilation?', N'Intern', N'AOT compilation pre-computes application metadata during the build process. By shifting work from runtime to build time, the framework reduces memory usage and eliminates the need for reflection, leading to faster execution.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e716db84-139e-4fef-8cb5-ee433287674d', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are clustering columns used for?', N'Fresher', N'Clustering columns are used to determine the physical storage order of data within a single partition. They allow for efficient range queries and sorting of data based on specific criteria.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d906d7a-d3d9-4223-8f6d-ee449ca05389', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What is the impact of ''Data Modeling for Queries'' compared to ''Normalization'' in Cassandra?', N'Senior', N'Cassandra requires data to be modeled specifically to support query patterns, often requiring heavy denormalization and duplication. Unlike normalized RDBMS models, joins are not supported, so data must be stored in the exact format required by the application to avoid expensive cross-partition queries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9455b76e-1858-4b55-a81b-ee4880e35464', N'1bc18970-8682-4a97-b4f3-e9e21274e17a', N'What is type casting in Swift and how is it implemented?', N'Intern', N'Type casting in Swift refers to the ability to check a variable''s type and conditionally convert it to a different type (upcasting or downcasting). Upcasting: Converting to a Superclass or Protocol Type - Superclass Type: You might cast a Dog instance to its superclass, Animal, for example, to treat all animals the same way, whether they are cats, dogs, or any other animal type that is a subclass of Animal. - Code Example: Here we have a set of animals ([Animal]) and a Dog instance. We treat both as Animal using Upcasting. - Protocol Type: With protocols, you can group different types that conform to the same protocol interface.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c122663a-87ab-48f6-8243-ee496d2be4e5', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the architectural implications of the ''restrict'' keyword in C?', N'Senior', N'The restrict keyword is a type qualifier that informs the compiler that a pointer is the sole means of accessing the memory block it points to. This allows the compiler to perform aggressive optimizations like register allocation and instruction scheduling by eliminating the need to assume potential memory aliasing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b3de99b-84fd-4bb7-aac6-ee49f686f8b0', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'What are Sass operators?', N'Fresher', N'Sass operators allow you to perform mathematical calculations directly within your stylesheets, such as addition, subtraction, multiplication, and division. This is helpful for creating responsive layouts based on dynamic values.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11e9ea27-419c-4b4f-9d06-ee4be8ece995', N'356ac66d-c432-46d0-a476-69e89c4b1403', N'How do you determine if a production issue is caused by a configuration change versus a code change?', N'Middle', N'I would audit the deployment history and configuration management logs to correlate the timing of the issue with any infrastructure or environment variable updates. If the timeline points to a config change, I would compare the current configuration against a known-good backup or versioned state to identify the discrepancy.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5d2f4991-0d9c-45e0-9bbf-ee4d06d58608', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What are Mapped Types and how can they be used to enforce API contract consistency?', N'Senior', N'Mapped types allow you to create new types by transforming every property of an existing type, such as making all fields optional, readonly, or wrapped in a Promise. They are critical for maintaining DRY code when mapping internal data models to external API response structures or form state objects.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e3528783-8f4e-4feb-847f-ee51dcded0d0', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the benefits of using ''Middleware'' in Actix-web?', N'Middle', N'Middleware allows you to intercept requests and responses globally to implement cross-cutting concerns. Examples include logging, authentication, request rate limiting, and adding headers, which keeps business logic clean and decoupled from infrastructure requirements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e62d76b9-fdc7-4a4d-a913-ee52290bdfe1', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Explain the architectural trade-offs between using React Context versus a global state management library like Redux or Zustand.', N'Senior', N'Context is ideal for low-frequency updates like theme or localization, but triggers re-renders across all consumers when the value changes, potentially causing performance bottlenecks. State management libraries provide fine-grained selectors and middleware, allowing components to subscribe to specific slices of state to prevent unnecessary re-renders in large applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd782fd5-c5e6-4dfa-a54c-ee53a9c2843e', N'73bda9de-bb38-4b7c-acac-426ba7aca048', N'How does Rocket process requests asynchronously?', N'Junior', N'Rocket is built on top of the Tokio asynchronous runtime. By marking your route handlers as ''async'', you allow the framework to handle multiple requests concurrently without blocking the underlying threads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c7113976-5977-475b-a8ca-ee57c9e2452b', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the purpose of the ''important'' flag in Tailwind configuration?', N'Middle', N'The ''important'' flag forces all utility classes to be generated with an ''!important'' rule, which increases their specificity to the highest possible level. This is typically used as a ''last resort'' when integrating Tailwind into a legacy codebase where existing global CSS styles are difficult to override otherwise.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0ef1144f-a077-4915-bb68-ee5812e4b2bf', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'How do Sass @mixin and @extend differ in terms of the generated CSS output and performance impact?', N'Senior', N'@mixin copies the defined styles into every location it is called, which can lead to larger CSS files if used excessively. @extend applies the DRY principle by grouping selectors that share the same styles into a single rule, resulting in cleaner output but potentially leading to unexpected specificity issues or long selector chains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1382f515-f350-42bd-87b7-ee5a2a225921', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the ''Configuration Properties'' feature?', N'Junior', N'Configuration properties allow you to map configuration values from files to strongly-typed Java objects. This makes it easier to manage application settings and provides IDE support for property names.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd20cf6e0-a523-4df1-904a-ee5ad4a69f4e', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Can Sass be read directly by web browsers?', N'Intern', N'No, web browsers cannot read Sass files directly. Sass must be compiled or transpiled into standard CSS files before the browser can interpret and apply the styles to a webpage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33b9ca7a-5b3a-469c-bc65-ee6351a576b9', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'What is the benefit of using Django''s built-in Authentication system?', N'Intern', N'It provides a secure, battle-tested system for handling user accounts, groups, permissions, and cookie-based user sessions. By using the built-in system, developers avoid the significant security risks associated with implementing custom authentication logic from scratch.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
