INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b6d48e5b-9fb4-478b-8b51-ee6433798b8b', N'91fb4eff-ac6a-48b9-8ba4-2bbdf6237429', N'What is the purpose of a bulkhead pattern?', N'Middle', N'The bulkhead pattern isolates elements of an application into pools so that if one fails, the others continue to function. It prevents a failure in a single service or thread pool from consuming all system resources and causing a cascading failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
