INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a5815080-4a27-4654-93fa-ee6b65efb0de', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What is the role of the PostgreSQL transaction log?', N'Fresher', N'The transaction log, known as Write-Ahead Logging (WAL), records all changes made to the database before they are permanently written to the data files. It ensures data recovery and consistency in case of a crash.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd07f64c-b326-45d7-96fa-ee6bfe643066', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How does FastAPI manage middleware execution order, and what are the implications for global state modification?', N'Senior', N'Middleware in FastAPI follows the ASGI middleware stack pattern, executing in the order they are added. Modifications to the request or response state within middleware must be carefully managed to avoid race conditions or unintended side effects, especially when performing asynchronous operations within the stack.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b9fc7aa0-2774-4adf-9e24-ee7048a67ce6', N'9a0e3785-3b73-4abc-ab01-df75bf097dff', N'What are the downsides of ''Eventual Consistency'' and how do you mitigate them?', N'Senior', N'The primary downside is that users may see stale data, which can lead to confusion or logic errors. Mitigate this by designing UI/UX to handle pending states, or by using read-your-writes consistency patterns where the client is pinned to a specific replica.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cdaa9c11-4b44-4500-bcdf-ee7110329a45', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the advantages of Cassandra over a relational database?', N'Fresher', N'Cassandra provides superior write performance, horizontal scalability, and high fault tolerance. It is better suited for applications requiring high availability and massive data ingestion compared to traditional relational systems.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
