INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2e84f688-ee7e-4fa2-95c1-ee8fe5028f5f', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does the Kotlin compiler ensure null safety without incurring a performance penalty for every access?', N'Senior', N'Kotlin performs static analysis during compilation to enforce nullability rules and inserts null checks only where necessary to guarantee type safety. By leveraging the JVM''s optimized bytecode and avoiding runtime wrappers for nullable types, the language maintains high performance while moving the cost of safety to the compilation phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'68a5723d-8ca4-48ef-879e-ee91dde34658', N'0b90236e-1b84-4abe-abc2-c153ce1b03d9', N'How do you perform a rolling index build in a replica set to minimize downtime?', N'Middle', N'A rolling index build involves building the index on secondary nodes one by one, then stepping down the primary to update it last. This ensures that the primary remains available for operations throughout the process, preventing a full cluster outage.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d221043-6912-4124-a491-ee9338c0b275', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'What are the trade-offs of using macros versus inline functions?', N'Middle', N'Macros are expanded by the preprocessor and can be error-prone due to lack of type checking and side effects from multiple evaluations. Inline functions provide type safety and debugging support while still suggesting to the compiler to eliminate function call overhead, making them generally safer and more maintainable.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
