INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd978d95f-32cb-486f-a26f-eea95f71a62b', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What is the role of Write-Ahead Logging (WAL) in maintaining ACID compliance?', N'Senior', N'WAL ensures durability and atomicity by recording all modifications to a sequential log file before they are applied to the actual data files. In the event of a system crash, the database can replay the log to restore the state, ensuring that committed transactions are not lost.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
