INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8b2cf0cb-946a-4b35-a588-eec6a81a0b6d', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you determine if a performance issue is a ''quick fix'' or a systemic architecture problem?', N'Senior', N'I use profiling tools to distinguish between localized bottlenecks, such as an inefficient query, and systemic issues like a lack of caching or poor service-to-service communication. If the issue persists after targeted optimization, it is a clear indicator that a broader architectural rethink is required.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89d073f9-0a87-4d86-9838-eec6ed4fbd99', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'What are the architectural implications of using lightweight transactions (LWT) in Cassandra?', N'Senior', N'LWT uses the Paxos consensus protocol to achieve linearizable consistency for compare-and-set operations. This process requires multiple round trips between nodes, which significantly increases latency and reduces overall cluster throughput compared to standard asynchronous writes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'18541cd5-8bcd-499f-8ab2-eec7c18d8581', N'9392e17b-213b-4c58-8a72-3d143d85e23b', N'What does ''key-value'' storage mean?', N'Fresher', N'A key-value storage system is a database model where every piece of data is stored as a specific key linked to a corresponding value. This simple structure allows for very fast lookups based on the key name.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a22e348f-b7f5-4bc8-94c5-eeca5482399b', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro improve SEO compared to client-side rendered applications?', N'Middle', N'Because Astro renders pages to HTML on the server, search engine crawlers receive a fully populated document immediately. This eliminates the need for crawlers to execute JavaScript to see content, leading to better indexing and faster performance metrics like Largest Contentful Paint.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'53933cae-0882-4d01-9133-eed0c1a5c7f8', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'What are dependency pre-bundling and why are they used?', N'Intern', N'Vite pre-bundles dependencies using esbuild to convert CommonJS or UMD modules into native ES modules. This improves page load speed and handles complex import structures that browsers cannot process efficiently on their own.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bf2ff18e-4554-4cd4-a0e3-eed1f233942c', N'0aa88a73-9782-4ed7-93c8-fa76c04f5f3c', N'How does Cassandra handle data deletions?', N'Fresher', N'Cassandra handles deletions using a special marker called a ''tombstone''. Instead of immediately removing the data, it marks the record as deleted so that it is ignored during read operations and eventually cleaned up during a compaction process.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'bbac7dde-4c7c-4d2a-9e3f-eed2c3a1d112', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'How does Adaptive Hash Indexing improve performance, and what are its limitations?', N'Senior', N'Adaptive Hash Indexing creates an in-memory hash index on frequently accessed pages to provide O(1) lookups. It is highly beneficial for read-heavy workloads but can become a source of contention in high-concurrency environments with varying query patterns.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'51832a8c-c005-4a48-b2c3-eed3b874b3e2', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Why is Alpine.js often preferred for server-rendered stacks like Laravel or Rails?', N'Senior', N'It aligns with the philosophy of these frameworks by keeping the logic close to the HTML, avoiding the need for a separate SPA build pipeline. It minimizes the impedance mismatch between backend templates and frontend interactivity, resulting in faster development cycles for content-driven applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'db7b6d58-29d8-41db-acc0-eed3d0ed26b3', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'What is the purpose of the Micronaut Bean?', N'Intern', N'A Bean is an object that is instantiated, assembled, and managed by the Micronaut IoC container. Beans are the fundamental building blocks of a Micronaut application, allowing developers to modularize code and define dependencies clearly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81882890-b19e-4699-95ed-eed6067f6de7', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'Explain the architectural difference between using Django''s Class-Based Views (CBVs) versus Function-Based Views (FBVs) in terms of extensibility.', N'Senior', N'CBVs leverage inheritance and mixins, making them highly reusable for common patterns like CRUD operations and complex logic reuse. FBVs are often more explicit and easier to debug, but they can lead to code duplication when complex patterns are repeated across multiple views.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5311144f-6b29-4bae-8ac0-eed91711c0e0', N'f55c7dbb-2269-422d-8b2b-88da21a280de', N'How do you manage cross-origin requests in Nuxt?', N'Middle', N'You can use the ''devProxy'' configuration to bypass CORS issues during local development. For production, you should typically use server-side API routes within Nuxt to act as a proxy or handle authentication, keeping API keys private.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'29a11579-9e85-415e-bf8e-eed9455a2bd0', N'f04d4428-efbd-41a0-a683-26abe8f4bd8c', N'What is Flask and why is it considered a micro-framework?', N'Junior', N'Flask is a lightweight Python web framework designed to be simple and easy to extend. It is called a micro-framework because it provides only the core essentials for web development, leaving decisions about database integration or form validation to the developer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c003af02-fb28-43be-a466-eee0ca31be6a', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is destructuring assignment', N'Intern', N'The destructuring assignment is a JavaScript expression that makes it possible to unpack values from arrays or properties from objects into distinct variables. Let''s get the month values from an array using destructuring assignment and you can get user properties of an object using destructuring assignment,', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5c0ff0d6-0d48-40fa-a442-eee501bff3f9', N'68f370eb-bff8-4a95-b65d-e7c7dc2a724e', N'Why is SvelteKit considered ''full-stack''?', N'Intern', N'SvelteKit is considered full-stack because it allows you to write both your frontend UI code and your backend API logic within the same project. It provides a unified development experience where the server and client components can communicate seamlessly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af32d940-726b-42d6-9386-eee62c2a7f56', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'Explain what is Dogpile effect? How can you prevent this effect?', N'Fresher', N'Dogpile effect is referred to the event when cache expires, and websites are hit by the multiple requests made by the client at the same time. This effect can be prevented by using semaphore lock. In this system when value expires, first process acquires the lock and starts generating new value.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4d937d0f-baaf-4818-bb4f-eee979e03652', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'How does Astro handle multiple UI frameworks?', N'Fresher', N'Astro is framework-agnostic, meaning you can use components from React, Vue, Svelte, or Solid within the same project. It enables this by rendering these components to static HTML during the build phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef91d35b-8764-440e-adbe-eeec1935c77e', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'What is the purpose of ''serialization'' in the context of Qwik?', N'Junior', N'Serialization is the process of converting complex application state into a text format that can be embedded in HTML. This allows the client-side app to resume exactly where the server left off.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'35e31ad9-0254-452c-ad3d-eeec5e64667a', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'What are some React anti-patterns?', N'Intern', N'React anti-patterns are practices that lead to inefficient, buggy, or hard-to-maintain code. Common ones in modern (hooks-era) React include: - Mutating state directly instead of producing a new value - Using useState to mirror props or other state instead of computing the value during render - Using useEffect to derive data that could just be computed - Using array index as key for dynamic lists - Stale closures inside effects (missing or wrong dependencies) - Forgetting to clean up effects (subscriptions, timers, listeners) - Mutating refs during render - Not using keys in lists at all - Reaching for useMemo/useCallback everywhere instead of where they actually help ↑', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f4c52bed-f994-4d9d-bb21-eeecdd8095e6', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the impact of Safepoints on application throughput and predictability?', N'Senior', N'A safepoint is a state where the thread''s execution is paused so the JVM can perform tasks like GC or deoptimization. While necessary for heap consistency, frequent or long-running safepoints—often caused by excessive code cache usage or slow thread handshakes—can significantly degrade tail latency.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0215a151-e047-44fa-b17f-eeef7cc9a5ff', N'5daa1051-b59c-4e3c-91d3-e9348a1447b9', N'What is the architectural impact of Tailwind''s ''group'' and ''peer'' modifiers?', N'Senior', N'These modifiers allow for sophisticated styling based on the state of parent or sibling elements without needing custom JavaScript or complex CSS selectors. They provide a declarative way to handle UI patterns like ''hover on parent to show child,'' which keeps the logic within the component''s declarative structure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
