INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'62b8591a-3329-4a93-aad3-eef0c9cf399f', N'5ffde826-06cd-4a09-a7bf-80142fe5fbb6', N'What architectural challenges arise when integrating third-party DOM libraries with SolidJS?', N'Senior', N'Integrating third-party libraries that directly manipulate the DOM can conflict with SolidJS''s reactivity system. You must ensure that such libraries are initialized within an ''onMount'' hook and that any cleanup is handled in an ''onCleanup'' hook to prevent state desynchronization.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'11909e7e-3fb6-4f33-9b7f-eef18a431737', N'bf04fc00-2412-4cd5-8e4e-918ff3a5834d', N'What does ''Dependency Injection'' mean in Laravel?', N'Junior', N'Dependency injection is a design pattern where a class receives its dependencies from an external source rather than creating them internally. In Laravel, the Service Container automatically injects these dependencies into your controllers or constructors, making the code easier to test and maintain.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
