INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3d8d553d-e066-4b05-bb25-eef6718e8727', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you evaluate if a task is ''too big'' to estimate accurately?', N'Fresher', N'If I find that I cannot break a task down into components that take less than a few days, it is likely too large and vague. In such cases, the best approach is to define a ''research'' or ''investigation'' phase to gain enough information to decompose the task properly. Breaking down the work into smaller units is essential for both estimation accuracy and progress tracking.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
