INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4040c5a4-604d-4b10-b1c0-eeffc6bcb8f3', N'1ad89512-2f43-42c9-af01-2f95e211d5dd', N'How does Django''s caching framework improve performance?', N'Middle', N'Caching stores the result of expensive database queries or rendered template fragments in memory, reducing the need to recompute data on every request. This significantly lowers database load and response times, especially for high-traffic sites with frequently accessed, rarely changing content.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'13d7dd59-f5f5-41dc-ab8e-ef03250728cb', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the difference between an expression object and a call object in R?', N'Senior', N'A call object represents a single function call, while an expression object is a vector of calls or other R objects. They are both fundamental to metaprogramming, allowing R to treat code as data that can be manipulated, analyzed, or transformed before evaluation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
