INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da77c32b-ce2f-434f-be97-ef06b179dffa', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'How do JavaScript engines manage the memory overhead of closures?', N'Senior', N'Engines perform static scope analysis to identify which variables are captured by closures. These variables are moved from the stack to a heap-allocated context object, which persists as long as the closure exists, potentially leading to memory leaks if references are not carefully managed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a2d340c2-bf18-4e71-8723-ef0a51ad147b', N'00cbf7f5-8e2a-4465-9805-7124fcdcfb06', N'What is the difference between stack and heap memory allocation in C++?', N'Junior', N'Stack memory is managed automatically by the compiler and is used for local variables with a fixed scope, making it very fast. Heap memory is managed manually by the programmer, allowing for dynamic allocation of objects that persist beyond the scope of a single function until they are explicitly deleted.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f0c9b6ec-d65b-49ec-9325-ef0a910e4535', N'ceb5d4ec-8897-4250-8e39-c9a7f29daab7', N'How does Python''s `asyncio` loop handle I/O-bound concurrency without threads?', N'Senior', N'Asyncio uses an event loop to manage cooperatively multitasking tasks, where tasks yield control back to the loop during I/O operations. This model eliminates the overhead of thread context switching and locking mechanisms, allowing a single process to handle thousands of concurrent connections efficiently.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'14129b20-006d-4dfc-98bc-ef0aebf7ba0e', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the role of the x-text directive?', N'Fresher', N'The x-text directive is used to set the text content of an element. It updates the innerText property of the element whenever the underlying data it is bound to changes, ensuring the view stays in sync with the state.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e05cf71a-71a3-4837-98fc-ef0c7ee54ad7', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What architectural risks are introduced by the ''background tasks'' feature in FastAPI?', N'Senior', N'The primary risk is the lack of reliability; background tasks are tied to the process lifecycle and do not persist across restarts. For critical tasks requiring durability, retries, or observability, it is better to use a dedicated task queue system rather than the built-in background tasks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
