INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'dd9337b9-49e6-400a-8ac2-ef19bf5d0f33', N'ddeec341-ac26-4444-b495-9e2e07ff2eca', N'How does consensus-based replication differ from traditional primary-secondary replication regarding transaction safety?', N'Senior', N'Consensus-based replication ensures that a majority of nodes must acknowledge a write before it is considered committed, preventing data loss during failover. Traditional primary-secondary replication is often asynchronous, meaning there is a window where a failed primary could result in the loss of data that was not yet replicated to the secondary.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'da841c12-98a2-4a06-b8dc-ef1a5998b450', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'How does React’s synthetic event system differ from native DOM events in terms of performance and cross-browser consistency?', N'Senior', N'The synthetic event system implements event delegation by attaching a single listener to the root of the document, which reduces memory usage. It normalizes event behavior across different browsers to ensure a consistent API, though modern browser standards have reduced the necessity of this abstraction.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
