INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'331b89d5-e747-4a37-9969-ef1bbc12d650', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'What is the purpose of a ''Decorator'' or ''Presenter'' pattern in Rails?', N'Senior', N'These patterns move display-related logic out of the model and view, keeping the model focused on data and the view focused on presentation. This results in cleaner code that is easier to test and avoids cluttering the model with view-specific helpers or formatters.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'1ef5b058-2231-47b7-9847-ef1cd73ff8ee', N'4408b91f-d0a3-4568-a5ea-3e625efd9c77', N'Why should we not update the state directly?', N'Fresher', N'If you try to update the state directly then it won''t re-render the component. Instead use setState() method. It schedules an update to a component''s state object. When state changes, the component responds by re-rendering. Note: You can directly assign to the state object either in _constructor_ or using latest javascript''s class field declaration syntax.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c0d3dcbf-5585-48da-8dcb-ef210fbf0ee2', N'0a728321-c234-4b3b-871d-eb8a37768d9f', N'What is the role of the NestJS execution context?', N'Middle', N'The execution context provides a way to inspect the current request, such as the handler being called, the class, or the arguments passed to it. It is critical for building cross-cutting concerns like logging, caching, or role-based access control.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'40ccf0be-bd42-4210-93d2-ef22145ceb9b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'What are the trade-offs of using a local in-memory cache versus a distributed cache like Redis?', N'Middle', N'Local caches offer extremely low latency by avoiding network overhead but are limited by individual server memory and are not shared across instances. Distributed caches provide a shared state and horizontal scalability but introduce network latency and the complexity of managing an external infrastructure component.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33916505-a370-4e3e-b9b1-ef2480f9f2b2', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What is the trade-off between write-heavy and read-heavy database optimization strategies?', N'Middle', N'Write-heavy optimizations often involve minimizing indexes and using write-ahead logs to increase throughput, which can slow down read operations. Conversely, read-heavy optimizations rely on extensive indexing and materialized views, which improve query speed but increase the latency and storage cost of write operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cc7de8fc-231a-4d30-97f1-ef25994690d9', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What Are Route-Handler Chains?', N'Intern', N'You can associate numerous route-managing middleware functions to a single route. Every middleware function in the chain has to either proceed to the following function using next() or conclude the request-response cycle. This allows for checks like user authentication before accessing a route. HTTP Method Convenience Methods Express.js offers specialized, highly-readable methods for the most common HTTP requests: - app.get() - app.post() - app.put() - app.delete() - app.use() These methods streamline route handling setup.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b523b293-28c4-4672-9c7e-ef264d416687', N'6e8f95a0-e79a-47ff-92bf-0a7632a3713f', N'Explain the architectural advantage of Micronaut''s ''Event Loop'' separation.', N'Senior', N'Micronaut separates the event loop (handling I/O) from the execution of business logic, allowing developers to configure dedicated executors for blocking tasks. This prevents blocking code from starving the server''s ability to accept new connections, a common bottleneck in purely reactive frameworks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d2b0ea4-5b50-4eeb-bea4-ef28274f4e25', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Explain the difference between ''extend'' and ''include'' in Ruby.', N'Middle', N'Include adds the methods of a module to a class as instance methods, making them available to all objects of that class. Extend adds the module methods to the class itself as class methods, which is useful for defining module-level utilities or singleton methods.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'83f0787d-fa9b-4ae6-821a-ef344e0c14a1', N'3bf2a9e1-c179-4303-830e-b8439aee3834', N'How do you define a group of routes in Fiber?', N'Fresher', N'Route grouping is achieved using the Group method, which allows developers to prefix a set of routes with a common path. This is useful for versioning APIs or grouping routes by specific resource types.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'353ee713-0b2a-48e9-8181-ef3488d47c26', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is a module system in Rust?', N'Intern', N'The module system allows you to organize code into a hierarchy of namespaces, which helps manage visibility and scope. It uses the mod keyword to define modules and provides control over whether items are public or private to other parts of the program.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd92d3041-e8ac-4e26-9fa1-ef36f97859da', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'Why might you denormalize a database schema?', N'Middle', N'Denormalization is used to improve read performance by reducing the need for expensive joins. By storing redundant data, you can retrieve complete information in a single query, which is beneficial for reporting or analytical workloads.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ee5d4aaa-dba3-42e3-a962-ef370d373e2d', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why does Vite use esbuild for development instead of Babel?', N'Intern', N'Vite uses esbuild because it is written in Go and performs build tasks significantly faster than JavaScript-based tools. By offloading tasks like transpilation to esbuild, Vite can handle project files much more efficiently during the development phase.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f271546d-35c1-49a3-9d1c-ef38537ee656', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'How do Server Actions improve the developer experience for form handling?', N'Middle', N'Server Actions allow you to define server-side functions that are called directly from the client without manually creating dedicated API routes. They simplify data mutation by keeping the logic within the component context while maintaining security through automatic request validation.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
