INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9437dd60-b252-4407-8b81-ef3a21c5861d', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'How does Preact''s hook implementation achieve compatibility without Fiber?', N'Senior', N'Preact implements hooks by using a global linked list of state objects associated with the current component being rendered. By tracking the execution context through an internal variable, it can accurately map state calls to specific components without needing the complex scheduling machinery of React''s Fiber.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9f3cc3ea-ab69-4882-8448-ef3c738e3ea0', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between a table and a view?', N'Intern', N'A table is a physical database object that stores data directly on the disk. A view is a virtual table based on the result of a query, which does not store its own data but retrieves it from underlying tables when accessed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'89aa9d82-f5bc-4701-9e19-ef41b0703031', N'da16179b-7f96-480b-ab6e-d9c7beeb753b', N'What is the purpose of the ''astro.config.mjs'' file?', N'Fresher', N'This file is the configuration hub for an Astro project. It allows you to define integrations, set output modes, configure server settings, and manage project-wide variables.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'3af5e54f-9380-40ae-bc80-ef425a00978b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Analyze the impact of ''JIT'' (Just-In-Time) compilation on Ruby applications with high method-dispatch frequency.', N'Senior', N'JIT compilation aims to convert frequently executed Ruby methods into native machine code, significantly improving performance for compute-intensive tasks. However, it can increase memory usage and initial startup time, and its effectiveness is highly dependent on the stability of the code''s call patterns; highly dynamic code can trigger constant re-compilation, negating the gains.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'784a4336-3062-4c1d-b2c2-ef42fc1646ff', N'ec592f10-23c6-4cf2-b197-7ce2ebe54120', N'What are Layouts in Next.js?', N'Fresher', N'Layouts allow you to share common UI elements across multiple pages, such as headers, footers, or sidebars. They persist state across navigation, preventing the common UI from re-rendering when the user moves between pages.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'65d5a189-a076-48f0-bcac-ef467ee64fac', N'221eef6f-c59c-44f4-b8ea-cb70a4a6786c', N'What are the limitations of using Preact with complex state management libraries like Redux?', N'Middle', N'There are generally no major limitations, as Preact works well with standard state management patterns. However, developers must ensure that the library bindings they choose are compatible with Preact, often requiring the use of the compat layer to mimic the React environment expected by those libraries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
