INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'92be2b36-c002-4978-bca8-ef483d0ff757', N'abbea783-abdd-4b9e-893f-9087683f97bb', N'Explain how Rails caching works and the difference between fragment and low-level caching.', N'Middle', N'Rails caching reduces database and rendering load by storing computation results in a cache store like Redis or Memcached. Fragment caching stores portions of a view template, while low-level caching allows developers to manually store and retrieve arbitrary data, like expensive method results or API responses.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a333afcc-8389-4f63-b2fd-ef486df0cb7a', N'3ea04738-14f7-4e0d-91de-0464e7e56d1d', N'What is the significance of ''this'' keyword in Java?', N'Intern', N'The this keyword in Java is a reference to the current instance of a class. It serves several important purposes in object-oriented programming. Key Uses of ''this'' Keyword 1. Distinguishing Instance Variables from Local Variables When a method or constructor parameter has the same name as an instance variable, this helps to differentiate between them: 2. Invoking Current Class Methods this can be used to call other methods within the same class: 3. Passing Current Object as Parameter this can be passed as an argument in method calls when an object needs to pass a reference to itself: 4. Constructor Chaining this() can be used to call another constructor in the same class: 5.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fbf3c95d-1f1d-4885-b2de-ef4a25a1ac07', N'f05a0449-5113-45ff-b5d4-b056c62be0b9', N'How do you reason about the feasibility of implementing a new technology stack within an existing legacy ecosystem?', N'Senior', N'I perform a gap analysis focusing on interoperability, developer velocity impact, and operational overhead. I estimate the effort required for bridge components or sidecar patterns and evaluate the long-term maintainability versus the potential productivity improvements.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
