INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f82cd977-25ef-4a64-9270-ef6b50a2e55b', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'Explain the primary design philosophy of Alpine.js compared to heavy frameworks like React or Vue.', N'Middle', N'Alpine.js is designed as a lightweight, declarative framework for adding interactivity directly into HTML markup. Unlike React or Vue, it does not require a complex build step or a virtual DOM, making it ideal for progressively enhancing static sites rather than building full single-page applications.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
