INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c1c5a718-32d0-46ab-a188-ef6f978515ce', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'How does Kotlin handle platform types when interacting with Java libraries?', N'Senior', N'Platform types represent types coming from Java where nullability is unknown, effectively disabling null-safety checks at compile time. While this provides flexibility, it shifts the responsibility to the developer to ensure null-safety, as these types can be treated as either nullable or non-nullable by the compiler.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
