INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7f4fafc-e627-4561-aa7f-ef9745c383f1', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'Describe the architectural implications of implementing a micro-frontend approach compared to a monolithic frontend structure.', N'Senior', N'Micro-frontends allow independent deployment cycles and technology heterogeneity, facilitating scaling across large teams. However, they introduce significant complexity in state management, shared dependency overhead, and consistent UI/UX design, necessitating robust governance and clear communication protocols.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'81de51f4-d40a-46da-b990-ef97c02f1ebe', N'dd8c0e9c-1166-438c-89e9-e2318fb4e1a5', N'What is the trade-off of using ''Ambient Declarations'' (.d.ts files) for JavaScript libraries?', N'Senior', N'Ambient declarations provide type safety for legacy JavaScript code, but they are not validated against the actual implementation. This creates a risk where the declarations can diverge from the actual runtime behavior, leading to a false sense of security if the declarations are not meticulously maintained.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'cd4ae0ec-77ec-4d55-bb16-ef99b58e9ff0', N'4c000000-0000-0000-0000-000000000005', N'What is the ''Outbox Pattern'' in microservices?', N'Senior', N'The outbox pattern ensures data consistency between a database and a message broker when a service needs to perform both a local transaction and an event publication. By writing the event to an ''outbox'' table within the same local transaction, it guarantees the event will eventually be published even if the service crashes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7d860e6f-c971-4985-9a6f-ef9ac37d395f', N'6a4c2a4f-7eec-4974-b88e-fe56e755e992', N'What is the role of the Kestrel web server?', N'Intern', N'Kestrel is a cross-platform, lightweight, and fast web server included by default in ASP.NET Core. It is designed to be used as an edge server or behind a reverse proxy like Nginx or IIS to handle incoming HTTP requests.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'85dbd86e-adad-4845-a6b5-ef9b67627116', N'a47cf39c-d07e-4297-90d7-38117d5c38ba', N'Explain the purpose of header files in C.', N'Fresher', N'Header files are used to include declarations of functions, macros, and data types that are defined in other files or libraries. They allow programmers to share code across multiple source files without rewriting definitions.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ddf915e5-d890-4bda-90d5-ef9b6944d3ef', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'What is the role of the ''promise'' object in R''s evaluation model?', N'Senior', N'A promise is a data structure used to implement lazy evaluation; it contains the expression to be evaluated, the environment in which the expression should be evaluated, and the cached value once evaluated. Promises decouple the definition of an argument from its execution, enabling flexible parameter passing in functional programming.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7c850cc1-e17b-4059-a97c-ef9d78adfc12', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'What does it mean for a database to be ''denormalized''?', N'Junior', N'Denormalization is the intentional process of adding redundant data or grouping data together to improve read performance. It is often used in scenarios where complex joins between normalized tables would be too slow for the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ce804fd6-ff84-47c7-baab-ef9dc87db3bd', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle configuration profiles?', N'Intern', N'Quarkus supports profiles like ''dev'', ''test'', and ''prod'' to manage different configurations for different environments. You can specify properties for a profile by prefixing the key with the profile name, such as %prod.my.property.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'2a65226e-fcd7-4c16-82d7-ef9e73017d88', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'How does Dart''s ''mixin application'' differ from a standard class inheritance?', N'Senior', N'A mixin application creates a new class by applying a mixin to a superclass, effectively flattening the hierarchy during compilation. This allows for horizontal composition of behavior while keeping the inheritance chain linear, which is safer and more performant than deep, multi-level inheritance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8050ff56-bad4-469a-a59a-ef9e79e39409', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the primary trade-off when choosing between optimistic and pessimistic concurrency control?', N'Senior', N'Pessimistic control locks resources upfront to prevent conflicts, which is ideal for high-contention environments but reduces throughput. Optimistic control assumes conflicts are rare, validating changes only at commit time, which performs better under low contention but risks high abort rates if conflicts occur.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'af8a0332-94e0-45e9-b93a-efa157f7094f', N'9f26ac8a-903d-4d82-b5bc-f8b074ec9acb', N'Discuss the implications of using reference classes (RC) for stateful object-oriented programming in R.', N'Senior', N'Reference classes allow for mutable state within objects, breaking the traditional copy-on-modify paradigm and enabling more traditional OOP patterns. While they offer improved efficiency for large objects by avoiding copies, they introduce side effects that can make code harder to reason about and test compared to purely functional R code.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'ef2bfb77-ffc6-4c88-8c9d-efa217907787', N'22ffc421-8d7a-4c1c-807f-bcf64f116685', N'Explain the significance of the ''Gossip Protocol'' in distributed NoSQL database clusters.', N'Senior', N'The Gossip Protocol allows nodes to communicate state information, such as cluster membership and health status, in a decentralized peer-to-peer fashion. This ensures high availability and resilience, as the system can quickly detect node failures and propagate topology changes without relying on a single master node or centralized control plane.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0760afd4-6ba6-46a0-8195-efa3967708e9', N'954a0331-deff-4399-b588-96f39fec001d', N'When should you use an InjectionToken instead of a class for dependency injection?', N'Middle', N'InjectionToken is used when the dependency is not a class, such as configuration objects, primitive values, or external API interfaces. It avoids the need for a concrete class and provides a way to provide values for tokens that do not have a constructor.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'33d6ffe1-dd1c-4bf5-bc18-efa63a89fc66', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'What is the impact of ''Select *'' on database performance?', N'Middle', N'Using ''Select *'' retrieves all columns, which can increase network traffic and memory usage, especially if large or unnecessary columns are fetched. It also prevents the database from using covering indexes effectively, as the index cannot contain all columns in the table.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a898f6a9-b6d5-427c-a944-efa9ec623923', N'210c7148-726e-4e8b-bf12-40be36e55130', N'What is the difference between a struct and an enum?', N'Junior', N'A struct is used to create a custom data type that groups related named values together. An enum allows you to define a type that can be one of several different variants, which is particularly useful for representing state or data that can take multiple forms.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4c545a8e-0c9f-44c2-addc-efadf54ad89a', N'ad677689-ab20-40df-9d49-c6e2f1d3580f', N'Explain the architectural purpose of the Doublewrite Buffer in InnoDB.', N'Senior', N'The Doublewrite Buffer prevents data corruption caused by partial page writes during power failures or OS crashes. Before writing pages to the actual tablespace, InnoDB writes them to a contiguous doublewrite area; if a page is corrupted, InnoDB can recover the original page from this buffer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f07f948a-6fa7-4af9-b8da-efadfbecd1b1', N'1efc8698-3202-4eae-a9cc-81fe7228234a', N'Explain how Webpack handles circular dependencies and the potential impact on runtime behavior.', N'Senior', N'Webpack resolves circular dependencies by creating a partial export object that is populated as modules execute. This can lead to runtime errors if code relies on exports that have not been initialized yet, requiring careful architectural planning to avoid cyclic imports.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7ac3229-da2e-4cba-9147-efb0180e210d', N'4d37c79b-f411-4292-a04b-22bc6d757931', N'Why is it important to compile Sass?', N'Intern', N'Browsers are not capable of reading Sass files directly; they only understand standard CSS. Compiling turns your Sass code into a standard CSS file that the browser can interpret and render correctly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'd4546e24-79bc-4d1b-be73-efb2ba43416d', N'9ef0d328-f3d3-443e-b5fe-1ca002a8fa5d', N'What is the difference between Just-In-Time (JIT) and Ahead-Of-Time (AOT) compilation in Dart?', N'Intern', N'JIT compilation compiles code on the fly during development, allowing for fast iteration and features like hot reload. AOT compilation converts Dart code into native machine code before the app is run, resulting in faster startup times and better performance for production builds.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'34bc82e5-99f8-4858-aa68-efb2e6a6adcb', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'What is an Exception Handler in FastAPI?', N'Intern', N'An exception handler is a custom function that catches specific errors and returns a structured response to the client. This allows you to provide consistent error messages and status codes when something goes wrong during request processing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fd76e09a-687c-4505-bcdb-efb3ea7b37a1', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'How are URL parameters accessed in Echo?', N'Fresher', N'URL parameters are accessed using the Param method on the Context object. You provide the name of the parameter defined in the route pattern to retrieve the corresponding value from the URL.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b0a062d3-898c-4853-82ad-efb8270adf50', N'8096a3fe-963b-4d44-92af-2afcfe60f132', N'What is the difference between a clustered and non-clustered index?', N'Intern', N'A clustered index determines the physical order of data in a table and a table can only have one. A non-clustered index creates a separate structure that points to the data rows, and a table can have multiple non-clustered indexes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'60261dce-74c0-4b66-b68d-efb88e784773', N'ede98781-dbb4-4edd-88de-2db0c39c5f9e', N'How does the ''Query Rewrite'' phase optimize execution for wildcard or fuzzy queries?', N'Senior', N'Query rewrite expands broad queries into specific term queries against the inverted index before execution. By converting fuzzy or wildcard patterns into a set of concrete terms, the engine avoids scanning the entire index, significantly improving execution speed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e32729b9-3645-4d6c-898a-efba8104a216', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'What are the security implications of moving a legacy application to a public cloud environment?', N'Senior', N'The shift requires transitioning from perimeter-based security to a Zero Trust architecture, focusing on identity-based access control and micro-segmentation. I would prioritize encryption at rest and in transit, alongside robust audit logging and automated compliance scanning to monitor for misconfigurations in the cloud control plane.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'641c9779-c87e-4fee-a4b1-efbd2d33d6a6', N'99a6cf43-096d-436d-ab30-4f4676a363be', N'What are higher-order functions in Kotlin?', N'Junior', N'A higher-order function is a function that either takes another function as a parameter or returns a function. This capability allows for more flexible and functional programming patterns, such as passing logic as an argument. They are frequently used with collection operations like map, filter, and fold.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77e06cb4-00ca-4b2d-9846-efbdaa2b0e6b', N'bfab7837-58c8-4127-b91b-b693be64edfb', N'What is the difference between typeof and instanceof operator?', N'Fresher', N'The typeof operator checks if a value has type of primitive type which can be one of boolean, function, object, number, string, undefined, symbol, or bigint. Example: The instanceof is a binary operator, accepting an object and a constructor. It returns a boolean indicating whether or not the object has the given constructor in its prototype chain. &#9885; Try this example on CodeSandbox', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'73629bb0-1cf3-45cf-b517-efc17e9e7394', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'What are the security trade-offs of using server-side rendering (SSR) versus client-side rendering (CSR) for sensitive applications?', N'Senior', N'SSR often exposes more server-side logic and potential vulnerabilities to the network, but it allows for better control over security headers and data exposure. CSR reduces server-side surface area but shifts the security burden to the client environment, making the application more susceptible to DOM-based XSS and data exposure if API endpoints are not properly secured.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'364f68ca-371d-403a-924d-efc3c33d4db9', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'Describe the difference between optimistic and pessimistic locking.', N'Middle', N'Pessimistic locking prevents conflicts by locking records as soon as they are accessed, ensuring data integrity at the cost of concurrency. Optimistic locking assumes conflicts are rare and only checks for modification at the time of commit, making it more performant for high-concurrency environments but requiring logic to handle transaction retries.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8038a4ac-030f-4ad1-8629-efc430e0ce87', N'954a0331-deff-4399-b588-96f39fec001d', N'What is Data Binding in Angular?', N'Junior', N'Data binding is the mechanism for coordinating parts of a template with parts of a component. It allows information to flow between the logic layer and the view layer, supporting techniques like interpolation, property binding, and event binding.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e67407fd-0923-48e1-af52-efc66b405c01', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'What is the purpose of the ''register'' method in Fastify?', N'Intern', N'The register method is used to load plugins into a Fastify application. It ensures that plugins are loaded in a specific order and allows for the creation of encapsulated contexts where settings or decorators do not leak to other parts of the application.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'0593af3a-3ce7-4692-a140-efc767add6cd', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'Explain the difference between a physical and a logical backup, and when would you choose one over the other?', N'Senior', N'A physical backup copies raw data files and is generally faster for large datasets and point-in-time recovery. A logical backup, such as one generated by pg_dump, exports data as SQL statements, which is more portable across different PostgreSQL versions or platforms but significantly slower to restore.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'77881248-c8d3-4a65-a5b6-efc92950fac6', N'bb0c1e54-46e9-4a65-98a2-e93a00322228', N'What are the risks of ''Serializable'' isolation level in PostgreSQL?', N'Senior', N'The Serializable level uses SSI (Serializable Snapshot Isolation) to detect concurrent data dependencies that could cause serialization anomalies. Applications must be prepared to handle serialization failures by implementing retry logic, which adds complexity to the application layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f5534f95-d792-4f17-b3e2-efcee6326e0e', N'f80c0dc5-f2dd-4fce-b733-6221f4c33894', N'What are the trade-offs of using Redux in a small-scale application?', N'Middle', N'The main trade-off is the significant amount of boilerplate code required to set up actions, reducers, and store configurations. For smaller projects, this can result in unnecessary complexity compared to using built-in React features like Context API.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
