INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fdf8f32e-8c15-44ab-8dc3-efde5da6966b', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'What are the architectural implications of Ruby''s ''Fiber'' implementation for concurrency?', N'Senior', N'Fibers provide light-weight, cooperative concurrency, allowing developers to pause and resume execution contexts explicitly. Unlike threads, which are preemptively scheduled by the OS, fibers are managed by the application, reducing memory overhead and context switching costs while requiring careful control over blocking I/O operations.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
