INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'c24676af-7853-4957-b1e5-efe4d3b7f7d1', N'a4e77760-3b47-4b57-920d-23e75be812d7', N'Why is Vite''s development server faster than Webpack''s?', N'Fresher', N'Vite is faster because it does not perform a full bundle of the application before starting the server. Instead, it serves individual files on demand as the browser requests them, reducing the initial wait time to almost zero.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'9b2e12d8-b6a5-49d3-83eb-efe7c1e3cf46', N'9cfe3e09-6b79-4c45-b236-3b66bdf29fc5', N'What are the trade-offs between implementing optimistic versus pessimistic locking in a high-concurrency database environment?', N'Senior', N'Pessimistic locking prevents conflicts by locking resources for the duration of the transaction, which ensures consistency but severely limits throughput. Optimistic locking assumes few conflicts occur, allowing higher concurrency, but it requires robust retry logic and handling for transaction failures when collisions are detected.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
