INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'82f85058-7ccb-4142-8fd7-efedfaebcac5', N'dc8474fd-6adb-4fb0-b08d-e61d04c5dc05', N'What architectural patterns do you use to handle massive spikes in read traffic?', N'Senior', N'I implement a multi-tiered caching strategy, starting from CDNs at the edge down to application-level local caches. I also leverage read replicas to offload database pressure and, if necessary, implement aggressive request collapsing to ensure redundant queries don''t reach the underlying storage layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'7748a1e1-94fa-4dba-8f3c-eff0078d8c0b', N'18ebabb7-555b-4ba1-beb6-844b8ee55dbd', N'Why might you use a read-through cache strategy?', N'Middle', N'In a read-through strategy, the cache sits between the application and the database; when a request misses, the cache itself fetches the data from the database. This simplifies application logic by abstracting the data retrieval process away from the business layer.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5b61f54d-104c-4546-ae5c-eff011356f80', N'a85a4110-ca75-4672-b1d2-ac89cf67c37d', N'How would you explain the concept of ''caching'' to a user?', N'Intern', N'Caching is the process of storing copies of data in a temporary storage location so that future requests for that data can be served much faster. Instead of fetching the data from the original, slower source every time, the system pulls it from the cache. It is similar to keeping a frequently used book on your desk instead of walking to the library every time you need to reference it.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'70c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4cd20e3f-ae63-4938-b77c-eff04b4d2ee7', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'What are ''Modifiers'' in Ember and how do they interact with the DOM safely?', N'Senior', N'Modifiers are used to attach behavior to DOM elements, such as third-party library initializations or event listeners. They provide a safe lifecycle-aware mechanism to manage DOM elements, ensuring that resources are cleaned up properly when the element is destroyed.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'6392f253-52f2-4659-934b-eff1af01dbd8', N'3e2fcecc-f41b-4cee-926f-5a31cabb36c7', N'What are the limitations of Chi''s routing when dealing with complex regex-based path matching?', N'Senior', N'While Chi supports basic regex in routes, complex or nested patterns can increase the complexity of the radix tree traversal. For highly dynamic routing requirements, a more specialized custom router might be necessary, though it often comes at the cost of performance.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'04320b7b-311e-4257-8718-eff2b8e56076', N'2be02c8a-41dc-4c4c-afc1-3f0bac5de249', N'How does Quarkus handle configuration properties compared to standard Spring Boot?', N'Middle', N'Quarkus uses a unified configuration system that supports environment variables, system properties, and files like application.properties. It allows for build-time configuration, which helps in optimizing the application for a specific environment before deployment.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'075b422f-26de-4c8c-b8c1-eff3aa775ea6', N'368072d9-3146-42c7-8f59-b4bf61b3cc3f', N'What is the difference between a Bean scope of ''singleton'' and ''prototype''?', N'Junior', N'A ''singleton'' scope ensures that only one instance of the bean is created per Spring container and shared across the entire application. A ''prototype'' scope creates a new instance of the bean every time it is requested from the container.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'a0791ff8-6437-43cd-9cd9-eff4f06e9a29', N'2faed488-a2fb-4a50-bf01-4e482f5231c2', N'How do you handle database transactions in FastAPI?', N'Middle', N'Database transactions are typically managed using a dependency that provides a session object to the path operation. By using a ''try-except'' block or a context manager within the dependency or the route, you can ensure that transactions are committed on success or rolled back on failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'8c06ba0c-1b81-49dc-b25f-eff6fbc3b232', N'993daf40-0c78-418c-8ba4-0980967ad34b', N'What is middleware in Echo and why is it used?', N'Fresher', N'Middleware in Echo is a function that sits between the incoming request and the final handler. It is used to perform cross-cutting concerns like logging, authentication, compression, or recovering from panics before or after the handler executes.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'26b85c42-354c-424a-83aa-eff79ab8739e', N'7d778e96-db84-4b18-88a8-dc9859f564ac', N'Describe the architectural purpose of the ''BasicObject'' class.', N'Senior', N'BasicObject is the root of the Ruby class hierarchy, intentionally stripped of almost all methods to provide a clean slate for objects that do not need the full overhead of the Object class. It is commonly used for implementing proxies, wrappers, or objects that rely heavily on method_missing for custom behavior.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5ceb2ec2-6d28-48d2-8c41-eff7ac07827e', N'af3c8131-3efd-496d-99f3-5f3d47158038', N'How do you log information in Fastify?', N'Junior', N'Fastify includes a built-in logger called Pino, which is highly performant. You can access the logger instance via the request object or the main application instance to log events, errors, or debugging information.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'47365f6d-eda5-4eb3-a43e-eff7fa4865d3', N'30a3eeb8-6a30-478c-80b3-f3c13190365e', N'Discuss the challenges of integrating third-party libraries into a Qwik application.', N'Senior', N'Integrating third-party libraries can be challenging because Qwik relies on its own serialization and lazy-loading boundaries. Libraries that depend on legacy lifecycle hooks or global state management may require special wrappers or adapters to ensure they work within the resumable architecture.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'310ef93f-f3f8-42c4-acb1-eff861a2f61f', N'cdde756d-0737-41a9-9f27-44cbd7cf7f17', N'What is the purpose of the ''recover'' function in Go''s panic-recovery mechanism?', N'Middle', N'The recover function allows a program to regain control after a panic, effectively stopping the propagation of an error that would otherwise crash the process. It should only be used in specific scenarios, such as cleaning up resources in a server process, to prevent total application failure.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6fc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'fc61cdaa-634f-4c79-ad36-eff92dc7a816', N'f2e963ff-7635-4429-a389-4d92535fb972', N'What is the purpose of the ''fieldset'' and ''legend'' elements?', N'Middle', N'The ''fieldset'' element groups related fields in a form, and the ''legend'' element provides a caption for that group. This structure is essential for accessibility, as it helps screen reader users understand the logical relationship between different form controls. It makes complex forms much easier to navigate and interpret.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
