INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'f03efaf3-097c-4e51-815e-effef24bc57d', N'1d0c7fc3-2329-4d3d-91e0-a6e1ce14363d', N'What is the advantage of Alpine.js over a heavy framework for simple tasks?', N'Intern', N'For simple tasks, Alpine.js is significantly lighter and easier to set up because it does not require a complex build pipeline or large JavaScript bundles. It keeps the logic close to the HTML, which can be more readable for simple UI components.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'b7c13baf-6fbc-448e-884f-f003dd9a8caf', N'48b769c0-6f69-433b-b800-ecce0e6df7c6', N'What are the trade-offs of using Addr vs Recipient in Actix actor communication?', N'Senior', N'Addr provides full control, including the ability to restart or stop an actor, but creates a tighter coupling. Recipient is a type-erased handle that only allows sending specific message types, promoting better decoupling and making it easier to mock actors during testing.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'aae27f0a-d443-40f7-8896-f0063b402ce7', N'e9b11e50-e216-48f0-8347-994de2fdbd4c', N'What is an application-level middleware?', N'Fresher', N'Application-level middleware is bound to an instance of the express application object using app.use(). It executes for every request that the application receives, regardless of the route.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'5a2959b6-baf1-4c86-8841-f00642ccbcc8', N'8d34dfc0-4a64-4128-b41a-cafa62ddad41', N'How do you protect data at rest versus data in transit?', N'Middle', N'Data at rest is protected using disk-level or database-level encryption to ensure that physical access to storage does not expose data. Data in transit is protected using protocols like TLS to prevent eavesdropping and man-in-the-middle attacks while information is moving across networks.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'71c1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'e7948321-6f4a-41f2-833f-f00d14bdef54', N'191e091d-3f1f-4406-9ce1-333f65c15a28', N'How do Ember''s ''Modifiers'' improve component reusability compared to mixins?', N'Senior', N'Modifiers decouple DOM-level interactions—like integrating third-party libraries—from the component''s logical state. Unlike mixins, which merge behavior directly into the component''s prototype and create fragile inheritance chains, modifiers are functional, reusable, and explicit in their DOM lifecycle management.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6dc1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'4a6428df-ad35-4f8c-9850-f00e5695375f', N'92eccda1-3910-46e5-9bf4-2d4ee5e4be48', N'How do ''Covering Indexes'' improve query performance?', N'Senior', N'Covering indexes contain all the columns requested by a query, allowing the database to satisfy the request entirely from the index tree. This prevents the engine from performing a ''bookmark lookup'' to the base table, effectively reducing random I/O and speeding up execution significantly.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6ec1cfe6-a888-f111-b9fd-d362599bedcb')
INSERT [dbo].[Questions] ([QuestionId], [CategoryId], [Question], [Difficulty], [Answer], [Status], [IsDeleted], [DeletedAt], [CreatedBy], [CreatedAt], [UpdatedAt], [DeletedBy], [PositionId]) VALUES (N'394fdc6a-0351-4857-a3b6-f00ee42e1def', N'77901f17-6a33-4f4d-9e19-b6f73572e000', N'What is Gin in the context of Go web development?', N'Fresher', N'Gin is a high-performance HTTP web framework written in the Go programming language. It provides a lightweight, minimalist structure for building web applications and APIs by wrapping standard library features with developer-friendly utilities.', N'Active', 0, NULL, NULL, CAST(N'2026-07-13T14:49:57.3860866' AS DateTime2), CAST(N'2026-07-13T14:49:57.4119316' AS DateTime2), NULL, N'6cc1cfe6-a888-f111-b9fd-d362599bedcb')
